INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546192,54,1,1,1,'Na počátku stvořil Bůh nebe a zemi.'),
(1546193,54,1,1,2,'Země pak byla nesličná a pustá, a tma byla nad propastí, a Duch Boží vznášel se nad vodami.'),
(1546194,54,1,1,3,'I řekl Bůh: Buď světlo! I bylo světlo.'),
(1546195,54,1,1,4,'A viděl Bůh světlo, že bylo dobré; i oddělil Bůh světlo od tmy.'),
(1546196,54,1,1,5,'A nazval Bůh světlo dnem, a tmu nazval nocí. I byl večer a bylo jitro, den první.'),
(1546197,54,1,1,6,'Řekl také Bůh: Buď obloha u prostřed vod, a děl vody od vod!'),
(1546198,54,1,1,7,'I učinil Bůh tu oblohu, a oddělil vody, kteréž jsou pod oblohou, od vod, kteréž jsou nad oblohou. A stalo se tak.'),
(1546199,54,1,1,8,'I nazval Bůh oblohu nebem. I byl večer a bylo jitro, den druhý.'),
(1546200,54,1,1,9,'Řekl také Bůh: Shromažďte se vody, kteréž jsou pod nebem, v místo jedno, a ukaž se místo suché! A stalo se tak.'),
(1546201,54,1,1,10,'I nazval Bůh místo suché zemí, shromáždění pak vod nazval mořem. A viděl Bůh, že to bylo dobré.'),
(1546202,54,1,1,11,'Potom řekl Bůh: Zploď země trávu, a bylinu vydávající símě, a strom plodný, nesoucí ovoce podlé pokolení svého, v němž by bylo símě jeho na zemi. A stalo se tak.'),
(1546203,54,1,1,12,'Nebo země vydala trávu, a bylinu nesoucí semeno podlé pokolení svého, i strom přinášející ovoce, v němž bylo símě jeho, podlé pokolení jeho. A viděl Bůh, že to bylo dobré.'),
(1546204,54,1,1,13,'I byl večer a bylo jitro, den třetí.'),
(1546205,54,1,1,14,'Opět řekl Bůh: Buďte světla na obloze nebeské, aby oddělovala den od noci, a byla na znamení a rozměření časů, dnů a let.'),
(1546206,54,1,1,15,'A aby svítila na obloze nebeské, a osvěcovala zemi. A stalo se tak.'),
(1546207,54,1,1,16,'I učinil Bůh dvě světla veliká, světlo větší, aby správu drželo nade dnem, a světlo menší, aby správu drželo nad nocí; též i hvězdy.'),
(1546208,54,1,1,17,'A postavil je Bůh na obloze nebeské, aby osvěcovala zemi;'),
(1546209,54,1,1,18,'A aby správu držela nade dnem a nocí, a oddělovala světlo od tmy. A viděl Bůh, že to bylo dobré.'),
(1546210,54,1,1,19,'I byl večer a bylo jitro, den čtvrtý.'),
(1546211,54,1,1,20,'Řekl ještě Bůh: Vydejte vody hmyz duše živé v hojnosti, a'),
(1546212,54,1,1,21,'I stvořil Bůh velryby veliké a všelijakou duši živou, hýbající se, kteroužto v hojnosti vydaly vody podlé pokolení jejich, a všeliké ptactvo křídla mající, podlé pokolení jeho. A viděl Bůh, že to bylo dobré.'),
(1546213,54,1,1,22,'I požehnal jim Bůh, řka: Ploďtež se a množte se, a naplňte vody mořské; též ptactvo ať se rozmnožuje na zemi!'),
(1546214,54,1,1,23,'I byl večer a bylo jitro, den pátý.'),
(1546215,54,1,1,24,'Řekl též Bůh: Vydej země duši živou, jednu každou podlé pokolení jejího, hovada a zeměplazy, i zvěř zemskou, podlé pokolení jejího. A stalo se tak.'),
(1546216,54,1,1,25,'I učinil Bůh zvěř zemskou podlé pokolení jejího, též hovada vedlé pokolení jejich, i všeliký zeměplaz podlé pokolení jeho. A viděl Bůh, že bylo dobré.'),
(1546217,54,1,1,26,'Řekl opět Bůh: Učiňme člověka k obrazu našemu, podlé podobenství našeho, a ať panují nad rybami mořskými, a nad ptactvem nebeským, i nad hovady, a nade vší zemí, i nad všelikým zeměplazem hýbajícím se na zemi.'),
(1546218,54,1,1,27,'I stvořil Bůh člověka k obrazu svému, k obrazu Božímu stvořil jej, muže a ženu stvořil je.'),
(1546219,54,1,1,28,'A požehnal jim Bůh, a řekl jim Bůh: Ploďtež se a rozmnožujte se, a naplňte zemi, a podmaňte ji, a panujte nad rybami mořskými, a nad ptactvem nebeským, i nad všelikým živočichem hýbajícím se na zemi.'),
(1546220,54,1,1,29,'Řekl ještě Bůh: Aj, dal jsem vám všelikou bylinu, vydávající símě, kteráž jest na tváři vší země, a všeliké stromoví, (na němž jest ovoce stromu), nesoucí símě; to bude vám za pokrm.'),
(1546221,54,1,1,30,'Všechněm pak živočichům zemským, i všemu ptactvu nebeskému, a všemu tomu, což se hýbe na zemi, v čemž jest duše živá, všelikou bylinu zelenou dal jsem ku pokrmu. I stalo se tak.'),
(1546222,54,1,1,31,'A viděl Bůh vše, což učinil, a aj, bylo velmi dobré. I byl večer a bylo jitro, den šestý.'),
(1546223,54,1,2,1,'A tak dokonána jsou nebesa a země, i všecko vojsko jejich.'),
(1546224,54,1,2,2,'A dokonal Bůh dne sedmého dílo své, kteréž dělal; a odpočinul v den sedmý ode všeho díla svého, kteréž byl dělal.'),
(1546225,54,1,2,3,'I požehnal Bůh dni sedmému a posvětil ho; nebo v něm odpočinul Bůh ode všeho díla svého, kteréž byl stvořil, aby učiněno bylo.'),
(1546226,54,1,2,4,'Tiť jsou rodové nebes a země, (když stvořena jsou v den, v němž učinil Hospodin Bůh zemi i nebe),'),
(1546227,54,1,2,5,'I každé chrastiny polní, dříve než byla na zemi, i všeliké byliny polní, prvé než vzcházela; nebo ještě byl nedštil Hospodin Bůh na zemi, aniž byl který člověk, ješto by dělal zemi.'),
(1546228,54,1,2,6,'A aniž pára vystupovala z země, aby svlažovala všecken svrchek země.'),
(1546229,54,1,2,7,'I učinil Hospodin Bůh člověka z prachu země, a vdechl v chřípě jeho dchnutí života, i byl člověk v duši živou.'),
(1546230,54,1,2,8,'Štípil pak byl Hospodin Bůh ráj v Eden na východ, a postavil tam člověka, jehož byl učinil.'),
(1546231,54,1,2,9,'A vyvedl Hospodin Bůh z země všeliký strom na pohledění libý, a ovoce k jídlu chutné; též strom života u prostřed ráje, i strom vědění dobrého a zlého.'),
(1546232,54,1,2,10,'(A řeka vycházela z Eden, k svlažování ráje, a odtud dělila se, a byla ve čtyři hlavní řeky.'),
(1546233,54,1,2,11,'Jméno jedné Píson, ta obchází všecku zemi Hevilah, kdež jest zlato.'),
(1546234,54,1,2,12,'A zlato země té jest výborné; tam jest i bdelium, a kámen onychin.'),
(1546235,54,1,2,13,'Jméno pak druhé řeky Gihon, ta obchází všecku zemi Chus.'),
(1546236,54,1,2,14,'A jméno řeky třetí Hiddekel, kteráž teče k východní straně Assyrské země. A řeka čtvrtá jest Eufrates).'),
(1546237,54,1,2,15,'Pojav tedy Hospodin Bůh člověka, postavil jej v ráji v zemi Eden, aby jej dělal a ostříhal ho.'),
(1546238,54,1,2,16,'I zapověděl Hospodin Bůh člověku, řka: Z každého stromu rajského svobodně jísti budeš;'),
(1546239,54,1,2,17,'Ale z stromu vědění dobrého a zlého nikoli nejez; nebo v který bys koli den z něho jedl, smrtí umřeš.'),
(1546240,54,1,2,18,'Řekl byl také Hospodin Bůh: Není dobré člověku býti samotnému; učiním jemu pomoc, kteráž by při něm byla.'),
(1546241,54,1,2,19,'(Nebo když byl učinil Hospodin Bůh z země všelikou zvěř polní, i všecko ptactvo nebeské, přivedl je k Adamovi, aby pohleděl na ně, jaké by jméno kterému dáti měl; a jak by koli nazval Adam kterou duši živou, tak aby jmenována byla.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546242,54,1,2,20,'I dal Adam jména všechněm hovadům, i ptactvu nebeskému, a všeliké zvěři polní; Adamovi pak není nalezena pomoc, kteráž by při něm byla.)'),
(1546243,54,1,2,21,'Protož uvedl Hospodin Bůh tvrdý sen na Adama, i usnul; a vyňal jedno z žeber jeho, a to místo vyplnil tělem.'),
(1546244,54,1,2,22,'A z toho žebra, kteréž vyňal z Adama, vzdělal Hospodin Bůh ženu, a přivedl ji k Adamovi.'),
(1546245,54,1,2,23,'I řekl Adam: Teď tato jest kost z kostí mých a tělo z těla mého; tato slouti bude mužatka, nebo z muže vzata jest.'),
(1546246,54,1,2,24,'Z té příčiny opustí muž otce svého i matku svou, a přídržeti se bude manželky své, i budou v jedno tělo.'),
(1546247,54,1,2,25,'Byli pak oba dva nazí, Adam i žena jeho, a nestyděli se.'),
(1546248,54,1,3,1,'Had pak byl nejchytřejší ze všech živočichů polních, kteréž byl učinil Hospodin Bůh. A ten řekl ženě: Tak-liž jest, že vám Bůh řekl: Nebudete jísti z každého stromu rajského?'),
(1546249,54,1,3,2,'I řekla žena hadu: Ovoce stromů rajských jíme;'),
(1546250,54,1,3,3,'Ale o ovoci stromu, kterýž jest u prostřed ráje, řekl Bůh: Nebudete ho jísti, aniž se ho dotknete, abyste nezemřeli.'),
(1546251,54,1,3,4,'I řekl had ženě: Nikoli nezemřete smrtí!'),
(1546252,54,1,3,5,'Ale ví Bůh, že v kterýkoli den z něho jísti budete, otevrou se oči vaše; a budete jako bohové, vědouce dobré i zlé.'),
(1546253,54,1,3,6,'Viduci tedy žena, že dobrý jest strom k jídlu i příjemný očima, a k nabytí rozumnosti strom žádostivý, vzala z ovoce jeho a jedla; dala také i muži svému s sebou, a on jedl.'),
(1546254,54,1,3,7,'Tedy otevříny jsou oči obou dvou, a poznali, že jsou nazí; i navázali lístí fíkového a nadělali sobě věníků.'),
(1546255,54,1,3,8,'A v tom uslyšeli hlas Hospodina Boha chodícího po ráji k větru dennímu; i skryl se Adam a žena jeho před tváří Hospodina Boha, u prostřed stromoví rajského.'),
(1546256,54,1,3,9,'I povolal Hospodin Bůh Adama, a řekl jemu: Kdež jsi?'),
(1546257,54,1,3,10,'Kterýžto řekl: Hlas tvůj slyšel jsem v ráji a bál jsem se, že jsem nahý; protož skryl jsem se.'),
(1546258,54,1,3,11,'I řekl Bůh: Kdožť oznámil, že jsi nahý? Nejedl-lis ale z toho stromu, z něhožť jsem jísti zapověděl?'),
(1546259,54,1,3,12,'I řekl Adam: Žena, kterouž jsi mi dal, aby byla se mnou, ona mi dala z stromu toho, a jedl jsem.'),
(1546260,54,1,3,13,'I řekl Hospodin Bůh ženě: Což jsi to učinila? I řekla žena: Had mne podvedl, i jedla jsem.'),
(1546261,54,1,3,14,'Tedy řekl Hospodin Bůh hadu: Že jsi to učinil, zlořečený budeš nade všecka hovada a nade všecky živočichy polní; po břiše svém plaziti se budeš, a prach žráti budeš po všecky dny života svého.'),
(1546262,54,1,3,15,'Nad to, nepřátelství položím mezi tebou a mezi ženou, i mezi semenem tvým a semenem jejím; ono potře tobě hlavu, a ty potřeš jemu patu.'),
(1546263,54,1,3,16,'Ženě pak řekl: Velice rozmnožím bolesti tvé a počínání tvá, s bolestí roditi budeš děti, a pod mocí muže tvého bude žádost tvá, a on panovati bude nad tebou.'),
(1546264,54,1,3,17,'Adamovi také řekl: Že jsi uposlechl hlasu ženy své, a jedl jsi z stromu toho, kterýžť jsem zapověděl, řka: Nebudeš jísti z něho; zlořečená země pro tebe, s bolestí jísti budeš z ní po všecky dny života svého.'),
(1546265,54,1,3,18,'Trní a bodláčí tobě ploditi bude, i budeš jísti byliny polní.'),
(1546266,54,1,3,19,'V potu tváři své chléb jísti budeš, dokavadž se nenavrátíš do země, poněvadž jsi z ní vzat. Nebo prach jsi a v prach se navrátíš.'),
(1546267,54,1,3,20,'Dal pak byl Adam jméno ženě své Eva, proto že ona byla mátě všech živých.'),
(1546268,54,1,3,21,'I zdělal Hospodin Bůh Adamovi a ženě jeho oděv kožený, a přioděl je.'),
(1546269,54,1,3,22,'Tedy řekl Hospodin Bůh: Aj, člověk učiněn jest jako jeden z nás, věda dobré i zlé; pročež nyní, aby nevztáhl ruky své, a nevzal také z stromu života, a jedl by, i byl by živ na věky, vyžeňme jej.'),
(1546270,54,1,3,23,'I vypustil jej Hospodin Bůh z zahrady Eden, aby dělal zemi, z níž vzat byl.'),
(1546271,54,1,3,24,'A tak vyhnal člověka a osadil zahradu Eden cherubíny k východní straně s mečem plamenným blýskajícím se, aby ostříhali cesty k stromu života.'),
(1546272,54,1,4,1,'Adam pak poznal Evu ženu svou, kterážto počavši, porodila Kaina a řekla: Obdržela jsem muže na Hospodinu.'),
(1546273,54,1,4,2,'A opět porodila bratra jeho Abele. I byl Abel pastýř ovcí, a Kain byl oráč.'),
(1546274,54,1,4,3,'Po mnohých pak dnech stalo se, že obětoval Kain z úrody zemské obět Hospodinu.'),
(1546275,54,1,4,4,'Ano i Abel také obětoval z prvorozených věcí stáda svého, a z tuku jejich. I vzhlédl Hospodin na Abele a na obět jeho.'),
(1546276,54,1,4,5,'Na Kaina pak a na obět jeho nevzhlédl. Protož rozlítil se Kain náramně, a opadla tvář jeho.'),
(1546277,54,1,4,6,'I řekl Hospodin Kainovi: Proč jsi se tak rozpálil hněvem? A proč jest opadla tvář tvá?'),
(1546278,54,1,4,7,'Zdaliž nebudeš příjemný, budeš-li dobře činiti? Pakli nebudeš dobře činiti, hřích ve dveřích leží; a pod mocí tvou bude žádost jeho, a ty panovati budeš nad ním.'),
(1546279,54,1,4,8,'I mluvil Kain k Abelovi bratru svému. Stalo se pak, když byli na poli, že povstav Kain proti Abelovi bratru svému, zabil jej.'),
(1546280,54,1,4,9,'I řekl Hospodin Kainovi: Kdež jest Abel bratr tvůj? Kterýž odpověděl: Nevím. Zdaliž jsem já strážným bratra svého?'),
(1546281,54,1,4,10,'I řekl Bůh: Co jsi učinil? Hlas krve bratra tvého volá ke mně z země.'),
(1546282,54,1,4,11,'Protož nyní zlořečený budeš i od té země, kteráž otevřela ústa svá, aby přijala krev bratra tvého z ruky tvé.'),
(1546283,54,1,4,12,'Když budeš dělati zemi, nebude více vydávati moci své tobě; tulákem a běhounem budeš na zemi.'),
(1546284,54,1,4,13,'I řekl Kain Hospodinu: Většíť jest nepravost má, než aby mi odpuštěna býti mohla.'),
(1546285,54,1,4,14,'Aj, vyháníš mne dnes z země této, a před tváří tvou skrývati se budu, a budu tulákem a běhounem na zemi. I přijde na to, že kdo mne koli nalezne, zabije mne.'),
(1546286,54,1,4,15,'I řekl mu Hospodin: Zajisté kdo by koli zabil Kaina, nad tím sedmnásobně mštěno bude. Pročež vložil Hospodin znamení naKaina, aby ho žádný nezabil, kdo by jej koli nalezl.'),
(1546287,54,1,4,16,'Tedy odšed Kain od tváři Hospodinovy, bydlil v zemi Nód, k východní straně naproti Eden.'),
(1546288,54,1,4,17,'Poznal pak Kain ženu svou, kterážto počala a porodila Enocha. I stavěl město, a nazval jméno města toho jménem syna svého Enoch.'),
(1546289,54,1,4,18,'I narodil se Enochovi Irád, a Irád zplodil Maviaele, Maviael pak zplodil Matuzaele, a Matuzael zplodil Lámecha.'),
(1546290,54,1,4,19,'Vzal sobě pak Lámech dvě ženy; jméno jedné Ada, a jméno druhé Zilla.'),
(1546291,54,1,4,20,'I porodila Ada Jábale, kterýž byl otec přebývajících v staních a stádo pasoucích.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546292,54,1,4,21,'A jméno bratra jeho Jubal; ten byl otec všech hrajících na harfu a nástroje hudebné.'),
(1546293,54,1,4,22,'A Zilla také porodila Tubalkaina, kterýž byl řemeslník všelikého díla od mědi a od železa. Sestra pak Tubalkainova byla Noéma.'),
(1546294,54,1,4,23,'I řekl Lámech ženám svým, Adě a Zille: Slyšte hlas můj, ženy Lámechovy, poslouchejte řeči mé, že jsem zabil muže k ráně své a mládence k zsinalosti své.'),
(1546295,54,1,4,24,'Jestližeť sedmnásobně pomštěno bude pro Kaina, tedy pro Lámecha sedmdesátekrát sedmkrát.'),
(1546296,54,1,4,25,'Poznal pak ještě Adam ženu svou, i porodila syna a nazvala jméno jeho Set; nebo řekla: Dal mi Bůh jiné símě místo Abele, kteréhož zabil Kain.'),
(1546297,54,1,4,26,'Setovi pak také narodil se syn, a nazval jméno jeho Enos. Tehdáž začalo se vzývání jména Hospodinova.'),
(1546298,54,1,5,1,'Tato jest kniha rodů Adamových. V ten den, v kterémž stvořil Bůh člověka, ku podobenství Božímu učinil ho.'),
(1546299,54,1,5,2,'Muže a ženu stvořil je a požehnal jim, a nazval jméno jejich Adam v ten den, když stvořeni jsou.'),
(1546300,54,1,5,3,'Byl pak Adam ve stu a třidcíti letech, když zplodil syna ku podobenství svému a k obrazu svému, a nazval jméno jeho Set.'),
(1546301,54,1,5,4,'I bylo dnů Adamových po zplození Seta osm set let, a plodil syny a dcery.'),
(1546302,54,1,5,5,'A tak bylo všech dnů Adamových, v kterýchž byl živ, devět set a třidceti let, i umřel.'),
(1546303,54,1,5,6,'Set pak byl ve stu a pěti letech, když zplodil Enosa.'),
(1546304,54,1,5,7,'A po zplození Enosa živ byl Set osm set a sedm let, a plodil syny a dcery.'),
(1546305,54,1,5,8,'I bylo všech dnů Setových devět set a dvanácte let, i umřel.'),
(1546306,54,1,5,9,'Byl pak Enos v devadesáti letech, když zplodil Kainana.'),
(1546307,54,1,5,10,'A po zplození Kainana živ byl Enos osm set a patnácte let, a plodil syny a dcery.'),
(1546308,54,1,5,11,'I bylo všech dnů Enosových devět set a pět let, i umřel.'),
(1546309,54,1,5,12,'Kainan pak byl v sedmdesáti letech, když zplodil Mahalaleele.'),
(1546310,54,1,5,13,'A po zplození Mahalaleele živ byl Kainan osm set a čtyřidceti let, a plodil syny a dcery.'),
(1546311,54,1,5,14,'I bylo všech dnů Kainanových devět set a deset let, i umřel.'),
(1546312,54,1,5,15,'Mahalaleel pak byl v šedesáti a pěti letech, když zplodil Járeda.'),
(1546313,54,1,5,16,'A po zplození Járeda živ byl Mahalaleel osm set a třidceti let, a plodil syny a dcery.'),
(1546314,54,1,5,17,'I bylo všech dnů Mahalaleelových osm set devadesáte a pět let, i umřel.'),
(1546315,54,1,5,18,'Járed pak byl ve stu šedesáti a dvou letech, když zplodil Enocha.'),
(1546316,54,1,5,19,'A po zplození Enocha živ byl Járed osm set let, a plodil syny a dcery.'),
(1546317,54,1,5,20,'I bylo všech dnů Járedových devět set šedesáte a dvě létě, i umřel.'),
(1546318,54,1,5,21,'Enoch pak byl v šedesáti a pěti letech, když zplodil Matuzaléma.'),
(1546319,54,1,5,22,'A chodil Enoch stále s Bohem po zplození Matuzaléma tři sta let, a plodil syny a dcery.'),
(1546320,54,1,5,23,'I bylo všech dnů Enochových tři sta šedesáte a pět let.'),
(1546321,54,1,5,24,'A chodil Enoch stále s Bohem a nebyl více vidín; nebo vzal ho Bůh.'),
(1546322,54,1,5,25,'Matuzalém pak byl ve stu osmdesáti sedmi letech, když zplodil Lámecha.'),
(1546323,54,1,5,26,'A po zplození Lámecha živ byl Matuzalém sedm set osmdesáte a dvě létě, a plodil syny a dcery.'),
(1546324,54,1,5,27,'I bylo všech dnů Matuzalémových devět set šedesáte a devět let, i umřel.'),
(1546325,54,1,5,28,'Lámech pak byl ve stu osmdesáti a dvou letech, když zplodil syna,'),
(1546326,54,1,5,29,'Jehož jméno nazval Noé, řka: Tento nám odpočinutí způsobí od díla našeho,od práce rukou našich, kterouž máme s zemí, jížto zlořečil Hospodin.'),
(1546327,54,1,5,30,'A živ byl Lámech potom, když zplodil Noé, pět set devadesáte a pět let, a plodil syny a dcery.'),
(1546328,54,1,5,31,'I bylo všech dnů Lámechových sedm set sedmdesáte a sedm let, i umřel.'),
(1546329,54,1,5,32,'A když byl Noé v pěti stech letech, zplodil Sema, Chama a Jáfeta.'),
(1546330,54,1,6,1,'Stalo se pak, když se počali množiti lidé na zemi, a dcery se jim zrodily,'),
(1546331,54,1,6,2,'Že vidouce synové Boží dcery lidské, any krásné jsou, brali sobě ženy ze všech, kteréž oblibovali.'),
(1546332,54,1,6,3,'Pročež řekl Hospodin: Nebude se nesnaditi duch můj s člověkem na věky, proto že také tělo jest, a bude dnů jeho sto a dvadceti let.'),
(1546333,54,1,6,4,'Obrové pak byli na zemi v těch dnech; ano i potom, když vcházeli synové Boží k dcerám lidským, ony rodily jim. To jsou ti mocní, kteříž zdávna byli, muži na slovo vzatí.'),
(1546334,54,1,6,5,'Ale když viděl Hospodin, an se rozmnožuje zlost lidská na zemi, a že by všeliké myšlení srdce jejich nebylo než zlé po všecken čas,'),
(1546335,54,1,6,6,'Litoval Hospodin, že učinil člověka na zemi, a bolest měl v srdci svém.'),
(1546336,54,1,6,7,'Tedy řekl Hospodin: Vyhladím z země člověka, kteréhož jsem stvořil, od člověka až do hovada, až do zeměplazu, až i do ptactva nebeského; nebo líto mi, že jsem je učinil.'),
(1546337,54,1,6,8,'Ale Noé našel milost před Hospodinem.'),
(1546338,54,1,6,9,'Tito jsou příběhové Noé: Noé muž spravedlivý, dokonalý byl za svého věku, s Bohem ustavičně chodil Noé.'),
(1546339,54,1,6,10,'(Zplodil pak Noé tři syny: Sema, Chama a Jáfeta.)'),
(1546340,54,1,6,11,'Ale země byla porušena před Bohem, a naplněna byla země nepravostí.'),
(1546341,54,1,6,12,'Viděl tedy Bůh zemi, a aj, porušena byla, nebo bylo porušilo všeliké tělo cestu svou na zemi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546342,54,1,6,13,'Protož řekl Bůh k Noé: Konec všelikého těla přichází přede mne, nebo naplněna jest země nepravostí od nich; z té příčiny, hle, již zkazím je s zemí.'),
(1546343,54,1,6,14,'Učiň sobě koráb z dříví gofer; příhrady zděláš v tom korábu, a oklejuješ jej vnitř i zevnitř klím.'),
(1546344,54,1,6,15,'A na tento způsob uděláš jej: Tří set loktů bude dlouhost toho korábu, padesáti loktů širokost jeho a třidceti loktů vysokost jeho.'),
(1546345,54,1,6,16,'Okno uděláš v korábu, a svrchkem na loket vysokým zavřeš jej; dvéře také korábu v boku jeho postavíš, a pokoje spodní, druhé i třetí zděláš v něm.'),
(1546346,54,1,6,17,'Já pak, aj, já uvedu potopu vod na zemi, aby zkaženo bylo všeliké tělo, v němž jest duch života pod nebem. Cožkoli bude na zemi, umře.'),
(1546347,54,1,6,18,'S tebou však učiním smlouvu svou; a vejdeš do korábu, ty i synové tvoji, žena tvá i ženy synů tvých s tebou.'),
(1546348,54,1,6,19,'A ze všech živočichů všelikého těla, po dvém z každého uvedeš do korábu, abys je živé zachoval s sebou; samec a samice budou.'),
(1546349,54,1,6,20,'Z ptactva podlé pokolení jeho, a z hovad podlé pokolení jejich, ze všelikého také zeměplazu podlé pokolení jeho, po dvém z každého vejdou k tobě, aby živi zůstali.'),
(1546350,54,1,6,21,'Ty pak nabeř s sebou všeliké potravy, kteráž se jísti může, a shromažď sobě, aby byla tobě i jim ku pokrmu.'),
(1546351,54,1,6,22,'I učinil Noé podlé všeho, jakž mu rozkázal Bůh, tak učinil.'),
(1546352,54,1,7,1,'Potom řekl Hospodin k Noé: Vejdiž ty i všecka čeled tvá do korábu; nebo jsem tě viděl spravedlivého před sebou v národu tomto.'),
(1546353,54,1,7,2,'Ze všech hovad čistých vezmeš sobě sedmero a sedmero, samce a samici jeho, ale z hovad nečistých dvé a dvé, samce a samici jeho.'),
(1546354,54,1,7,3,'Z ptactva také nebeského sedmero a sedmero, samce a samici, aby živé zachováno bylo símě na vší zemi.'),
(1546355,54,1,7,4,'Nebo po dnech ještě sedmi já dštíti budu na zemi za čtyřidceti dnů a čtyřidceti nocí; a vyhladím se svrchku země všelikou podstatu, kterouž jsem učinil.'),
(1546356,54,1,7,5,'Tedy učinil Noé všecko tak, jakž mu přikázal Hospodin.'),
(1546357,54,1,7,6,'(Byl pak Noé v šesti stech letech, když ta potopa přišla na zemi.)'),
(1546358,54,1,7,7,'A protož přišel Noé a synové jeho, i žena jeho, i ženy synů jeho s ním k korábu, pro vody potopy.'),
(1546359,54,1,7,8,'Z hovad také čistých i z hovad nečistých, i z ptactva a ze všeho, což se hýbe na zemi,'),
(1546360,54,1,7,9,'Po dvém vešli k Noé do korábu, samec a samice, tak jakž byl rozkázal Bůh Noé.'),
(1546361,54,1,7,10,'Stalo se pak po sedmi dnech, že vody potopy přišly na zemi.'),
(1546362,54,1,7,11,'Léta šestistého věku Noé, druhého měsíce, sedmnáctého dne téhož měsíce, v ten den protrženy jsou všecky studnice propasti veliké, a průduchové nebeští otevříni jsou.'),
(1546363,54,1,7,12,'I byl příval na zemi čtyřidceti dní a čtyřidceti nocí.'),
(1546364,54,1,7,13,'Toho dne všel Noé, Sem a Cham i Jáfet, synové Noé, žena Noé, a tři ženy synů jeho s ním do korábu.'),
(1546365,54,1,7,14,'Oni i všeliký živočich podlé pokolení svého, i všeliké hovado podlé pokolení svého, a všeliký zeměplaz, kterýž se hýbe na zemi, podlé pokolení svého, i všeliké ptactvo vedlé pokolení svého, všelijací ptáci, všecko, což křídla má,'),
(1546366,54,1,7,15,'Vešli k Noé do korábu, po dvém ze všelikého těla, v němž byl duch života.'),
(1546367,54,1,7,16,'A což jich vešlo, samec a samice ze všelikého těla vešli, tak jakž byl přikázal jemu Bůh, a zavřel Hospodin po něm.'),
(1546368,54,1,7,17,'A když byla potopa za čtyřidceti dnů na zemi, tedy rozmnoženy jsou vody, až i vyzdvihly koráb, a vznesly jej od země.'),
(1546369,54,1,7,18,'Nebo zmohly se vody a rozmnoženy jsou velmi nad zemí, i zplýval koráb na vodách.'),
(1546370,54,1,7,19,'A tak náramně rozmohly se vody nad zemí, že přikryty jsou všecky hory nejvyšší, kteréž byly pode vším nebem.'),
(1546371,54,1,7,20,'Patnácte loktů zvýší rozmohly se vody, když přikryty jsou hory.'),
(1546372,54,1,7,21,'I umřelo všeliké tělo, kteréž se hýbe na zemi, tak z ptactva, jako z hovad a živočichů, i všelikého hmyzu, kterýž se plazí po zemi, i každého člověka.'),
(1546373,54,1,7,22,'Všecko, což mělo dýchání ducha života v chřípích svých, ze všeho, což bylo na suše, pomřelo.'),
(1546374,54,1,7,23,'A tak vyhladil Bůh všelikou podstatu, kteráž byla na tváři země, od člověka až do hovada, až do zeměplazu, a až do ptactva nebeského, vyhlazeno jest, pravím, z země; a zůstal toliko Noé, a kteříž s ním byli v korábu.'),
(1546375,54,1,7,24,'I trvaly vody nad zemí za sto a padesáte dnů.'),
(1546376,54,1,8,1,'Rozpomenul se pak Bůh na Noé, i všecky živočichy a všecka hovada, kteráž byla s ním v korábu; pročež uvedl Bůh vítr na zemi, i zastavily se vody.'),
(1546377,54,1,8,2,'A zavříny jsou studnice propasti i průduchové nebeští, a zastaven jest příval s nebe.'),
(1546378,54,1,8,3,'I navrátily se vody se svrchku země, odcházejíce zase, a opadly vody po stu a padesáti dnech,'),
(1546379,54,1,8,4,'Tak že odpočinul koráb sedmého měsíce, v sedmnáctý den toho měsíce na horách Ararat.'),
(1546380,54,1,8,5,'Když pak vody odcházely a opadaly až do desátého měsíce, prvního dne téhož desátého měsíce ukázali se vrchové hor.'),
(1546381,54,1,8,6,'I stalo se po čtyřidcíti dnech, otevřev Noé okno v korábu, kteréž byl udělal,'),
(1546382,54,1,8,7,'Vypustil krkavce. Kterýžto vyletuje zase se vracoval, dokudž nevyschly vody na zemi.'),
(1546383,54,1,8,8,'Potom vypustil holubici od sebe, aby věděl, již-li by opadly vody se svrchku země.'),
(1546384,54,1,8,9,'Kterážto když nenašla, kde by odpočinula noha její, navrátila se k němu do korábu; nebo vody byly po vší zemi. On pak vztáhna ruku svou, vzal ji, a vnesl k sobě do korábu.'),
(1546385,54,1,8,10,'A počekal ještě sedm dní jiných, a opět vypustil holubici z korábu.'),
(1546386,54,1,8,11,'I přiletěla k němu holubice k večerou, a aj, list olivový utržený v ústech jejích. Tedy poznal Noé, že opadly vody se svrchku země.'),
(1546387,54,1,8,12,'I čekal ještě sedm dní jiných, a opět vypustil holubici, kterážto nevrátila se k němu více.'),
(1546388,54,1,8,13,'I stalo se šestistého prvního léta, v první den měsíce prvního, že vyschly vody na zemi. I odjal Noé přikrytí korábu a uzřel, ano již oschl svrchek země.'),
(1546389,54,1,8,14,'Druhého pak měsíce, v dvadcátý sedmý den téhož měsíce oschla země.'),
(1546390,54,1,8,15,'I mluvil Bůh k Noé, řka:'),
(1546391,54,1,8,16,'Vyjdi z korábu, ty i žena tvá, a synové tvoji, i ženy synů tvých s tebou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546392,54,1,8,17,'Všecky živočichy, kteříž jsou s tebou ze všelikého těla, tak z ptactva jako z hovad a všelikého zeměplazu, kterýž se hýbe na zemi, vyveď s sebou; ať se v hojnosti rozplozují na zemi, a rostou a množí se na zemi.'),
(1546393,54,1,8,18,'I vyšel Noé a synové jeho, i žena jeho a ženy synů jeho s ním;'),
(1546394,54,1,8,19,'Každý živočich, každý zeměplaza všecko ptactvo, všecko, což se hýbe na zemi, po pokoleních svých vyšlo z korábu.'),
(1546395,54,1,8,20,'Tedy vzdělal Noé oltář Hospodinu, a vzav ze všech hovad čistých i ze všeho ptactva čistého, obětoval zápaly na tom oltáři.'),
(1546396,54,1,8,21,'I zachutnal Hospodin vůni tu příjemnou, a řekl Hospodin v srdci svém: Nebudu více zlořečiti zemi pro člověka, proto že myšlení srdce lidského zlé jest od mladosti jeho; aniž budu více bíti všeho, což živo jest, jako jsem učinil.'),
(1546397,54,1,8,22,'Nýbrž dokavadž země trvati bude, setí a žeň, studeno i horko, léto a zima, den také a noc nepřestanou.'),
(1546398,54,1,9,1,'Tedy požehnal Bůh Noé i synům jeho a řekl jim: Ploďtež se a rozmnožujte se, a naplňte zemi.'),
(1546399,54,1,9,2,'Strach váš a hrůza vaše buď na všeliký živočich země, a na všecko ptactvo nebeské. Všecko, což se hýbe na zemi, a všecky ryby mořské v ruce vaše dány jsou.'),
(1546400,54,1,9,3,'Všecko, což se hýbe a jest živo, bude vám za pokrm; jako i bylinu zelenou, dal jsem vám to všecko.'),
(1546401,54,1,9,4,'A však masa s duší jeho, kteráž jest krev jeho, nebudete jísti.'),
(1546402,54,1,9,5,'A zajisté krve vaší, duší vašich vyhledávati budu; z rukou každého hovada vyhledávati jí budu, i z ruky člověka, ano i z ruky každého bratra jeho budu vyhledávati duše člověka.'),
(1546403,54,1,9,6,'Kdo by koli vylil krev člověka, skrze člověka vylita bude krev jeho; nebo k obrazu svému učinil Bůh člověka.'),
(1546404,54,1,9,7,'Vy pak ploďte a množte se; v hojnosti se rozploďte na zemi, a rozmnoženi buďte na ní.'),
(1546405,54,1,9,8,'I mluvil Bůh k Noé a synům jeho s ním, řka:'),
(1546406,54,1,9,9,'Já zajisté vcházím v smlouvu svou s vámi, i s semenem vaším po vás,'),
(1546407,54,1,9,10,'A se všelikou duší živou, kteráž jest s vámi, z ptactva, z hovad a ze všech živočichů zemských, kteříž jsou s vámi, ode všech, kteříž vyšli z korábu, až do všelikého živočicha zemského.'),
(1546408,54,1,9,11,'Protož utvrzuji smlouvu svou s vámi, že nebude vyhlazeno více všeliké tělo vodami potopy; aniž bude více potopa k zkažení země.'),
(1546409,54,1,9,12,'I řekl Bůh: Totoť bude znamení smlouvy, kteréž já dávám, mezi mnou a mezi vámi, a mezi všelikou duší živou, kteráž jest s vámi, po všecky věky.'),
(1546410,54,1,9,13,'Duhu svou postavil jsem na oblaku, a bude na znamení smlouvy mezi mnou a mezi zemí.'),
(1546411,54,1,9,14,'A budeť, když uvedu mračný oblak nad zemí, a ukáže se duha na oblaku,'),
(1546412,54,1,9,15,'Že se rozpomenu na smlouvu svou, kteráž jest mezi mnou a mezi vámi a mezi všelikou duší živou v každém těle; a nebudou více vody ku potopě, aby zahladily všeliké tělo.'),
(1546413,54,1,9,16,'Nebo když bude duha ta na oblaku, popatřím na ni, abych se rozpomenul na smlouvu věčnou mezi Bohem a mezi všelikou duší živou v každém těle, kteréž jest na zemi.'),
(1546414,54,1,9,17,'I řekl Bůh k Noé: Toť jest znamení smlouvy, kterouž jsem utvrdil mezi sebou a mezi všelikým tělem, kteréž jest na zemi.'),
(1546415,54,1,9,18,'Byli pak synové Noé, kteříž vyšli z korábu: Sem, Cham a Jáfet; a Cham byl otec Kanánův.'),
(1546416,54,1,9,19,'Ti tři jsou synové Noé, a ti se rozprostřeli po vší zemi.'),
(1546417,54,1,9,20,'Noé pak obíraje se s zemí, začal dělati vinice.'),
(1546418,54,1,9,21,'A pije víno, opil se, a obnažil se u prostřed stanu svého.'),
(1546419,54,1,9,22,'Viděl pak Cham, otec Kanánův, hanbu otce svého, a pověděl oběma bratřím svým vně.'),
(1546420,54,1,9,23,'Tedy vzali Sem a Jáfet oděv, kterýžto oba položili na ramena svá, a jdouce zpátkem, zakryli hanbu otce svého; tváři pak jich byly odvráceny, a hanby otce svého neviděli.'),
(1546421,54,1,9,24,'Procítiv pak Noé po svém víně, zvěděl, co mu učinil syn jeho mladší.'),
(1546422,54,1,9,25,'I řekl: Zlořečený Kanán, služebník služebníků bude bratřím svým.'),
(1546423,54,1,9,26,'Řekl také: Požehnaný Hospodin, Bůh Semův, a buď Kanán služebníkem jejich.'),
(1546424,54,1,9,27,'Rozšiřiž Bůh milostivě Jáfeta, aby bydlil v stáncích Semových, a buď Kanán služebníkem jejich.'),
(1546425,54,1,9,28,'Živ pak byl Noé po potopě tři sta a padesáte let.'),
(1546426,54,1,9,29,'A tak bylo všech dnů Noé devět set a padesáte let; i umřel jest.'),
(1546427,54,1,10,1,'Tito jsou pak rodové synů Noé, Sema, Chama a Jáfeta, jimž se tito synové zrodili po potopě.'),
(1546428,54,1,10,2,'Synové Jáfetovi: Gomer a Magog, a Madai, a Javan, a Tubal, a Mešech, a Tiras.'),
(1546429,54,1,10,3,'Synové pak Gomerovi: Ascenez, Rifat, a Togorma.'),
(1546430,54,1,10,4,'Synové pak Javanovi: Elisa a Tarsis, Cetim a Dodanim.'),
(1546431,54,1,10,5,'Od těch rozděleni jsou ostrovové národů po krajinách jejich, každý podlé jazyku svého, vedlé čeledi své, v národech svých.'),
(1546432,54,1,10,6,'Synové pak Chamovi: Chus a Mizraim a Put a Kanán.'),
(1546433,54,1,10,7,'A synové Chusovi: Sába, Evila, a Sabata, a Regma, a Sabatacha. Synové pak Regmovi: Sába a Dedan.'),
(1546434,54,1,10,8,'Zplodil také Chus Nimroda; onť jest počal býti mocným na zemi.'),
(1546435,54,1,10,9,'To byl silný lovec před Hospodinem; protož se říká: Jako Nimrod silný lovec před Hospodinem.'),
(1546436,54,1,10,10,'Počátek pak jeho království byl Babylon a Erech, Achad a Chalne, v zemi Sinear.'),
(1546437,54,1,10,11,'Z země té vyšel do Assur, kdežto vystavěl Ninive, a Rohobot město, a Chále,'),
(1546438,54,1,10,12,'A Rezen mezi Ninive a mezi Chále; toť jest město veliké.'),
(1546439,54,1,10,13,'Mizraim pak zplodil Ludim a Anamim, a Laabim, a Neftuim,'),
(1546440,54,1,10,14,'A Fetruzim, a Chasluim, (odkudž pošli Filistinští) a Kafturim.'),
(1546441,54,1,10,15,'Kanán pak zplodil Sidona prvorozeného svého, a Het,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546442,54,1,10,16,'A Jebuzea, a Amorea, a Gergezea,'),
(1546443,54,1,10,17,'A Hevea, a Aracea, a Sinea,'),
(1546444,54,1,10,18,'A Aradia, a Samarea, a Amatea; a potom odtud rozprostřely se čeledi Kananejských.'),
(1546445,54,1,10,19,'A bylo pomezí Kananejských od Sidonu, když jdeš k Gerar až do Gázy; a odtud když jdeš k Sodomě a Gomoře, a Adama a Seboim až do Lázy.'),
(1546446,54,1,10,20,'Ti jsou synové Chamovi po čeledech svých, vedlé jazyků svých, po krajinách svých, v národech svých.'),
(1546447,54,1,10,21,'Semovi také, otci všech synů Heber, bratru Jáfeta staršího zrozeni jsou synové.'),
(1546448,54,1,10,22,'A tito jsou synové Semovi: Elam, a Assur, a Arfaxad, a Lud, a Aram.'),
(1546449,54,1,10,23,'Synové pak Aramovi: Hus, a Hul, a Geter, a Mas.'),
(1546450,54,1,10,24,'Potom Arfaxad zplodil Sále; a Sále zplodil Hebera.'),
(1546451,54,1,10,25,'Heberovi také narodili se dva synové; jméno jednoho Peleg, proto že za dnů jeho rozdělena byla země, a jméno bratra jeho Jektan.'),
(1546452,54,1,10,26,'Jektan pak zplodil Elmodada, a Salefa, a Azarmota, a Járe,'),
(1546453,54,1,10,27,'A Adoráma, a Uzala, a Dikla,'),
(1546454,54,1,10,28,'A Obale, a Abimahele, a Sebai,'),
(1546455,54,1,10,29,'A Ofira, a Evila, a Jobaba; všickni ti jsou synové Jektanovi.'),
(1546456,54,1,10,30,'A bylo bydlení jejich od Mesa, když jdeš k Sefar hoře na východ slunce.'),
(1546457,54,1,10,31,'Tiť jsou synové Semovi po čeledech svých, vedlé jazyků svých, po krajinách svých, v národech svých.'),
(1546458,54,1,10,32,'Ty jsou čeledi synů Noé po rodech svých, v národech svých; a od těch rozdělili se národové na zemi po potopě.'),
(1546459,54,1,11,1,'Byla pak všecka země jazyku jednoho a řeči jedné.'),
(1546460,54,1,11,2,'I stalo se, když se brali od východu, nalezli pole v zemi Sinear, a bydlili tam.'),
(1546461,54,1,11,3,'A řekli jeden druhému: Nuže, nadělejme cihel, a vypalme je ohněm. I měli cihly místo kamení, a zemi lepkou místo vápna.'),
(1546462,54,1,11,4,'Nebo řekli: Nuže, vystavějme sobě město a věži, jejíž by vrch dosahal k nebi; a tak učiňme sobě jméno, abychom nebyli rozptýleni po vší zemi.'),
(1546463,54,1,11,5,'Sstoupil pak Hospodin, aby viděl to město a věži, kterouž stavěli synové lidští.'),
(1546464,54,1,11,6,'A řekl Hospodin: Aj, lid jeden a jazyk jeden všechněch těchto, a toť jest začátek díla jejich; nyní pak nedadí sobě v tom překaziti, což umínili dělati.'),
(1546465,54,1,11,7,'Protož sstupme a změťme tam jazyk jejich, aby jeden druhého jazyku nerozuměl.'),
(1546466,54,1,11,8,'A tak rozptýlil je Hospodin odtud po vší zemi; i přestali stavěti města toho.'),
(1546467,54,1,11,9,'Protož nazváno jest jméno jeho Bábel; nebo tu zmátl Hospodin jazyk vší země; a odtud rozptýlil je Hospodin po vší zemi.'),
(1546468,54,1,11,10,'Titoť jsou rodové Semovi: Sem, když byl ve stu letech, zplodil Arfaxada ve dvou letech po potopě.'),
(1546469,54,1,11,11,'A byl živ Sem po zplození Arfaxada pět set let; a plodil syny a dcery.'),
(1546470,54,1,11,12,'Arfaxad pak živ byl pět a třidceti let, a zplodil Sále.'),
(1546471,54,1,11,13,'A po zplození Sále živ byl Arfaxad čtyři sta a tři léta; a plodil syny a dcery.'),
(1546472,54,1,11,14,'Sále také živ byl třidceti let, a zplodil Hebera.'),
(1546473,54,1,11,15,'A živ byl Sále po zplození Hebera čtyři sta a tři léta; a plodil syny a dcery.'),
(1546474,54,1,11,16,'Živ pak byl Heber čtyři a třidceti let, a zplodil Pelega.'),
(1546475,54,1,11,17,'A živ byl Heber po zplození Pelega čtyři sta a třidceti let; a plodil syny a dcery.'),
(1546476,54,1,11,18,'Peleg pak živ byl třidceti let, a zplodil Réhu.'),
(1546477,54,1,11,19,'A živ byl Peleg po zplození Réhu dvě stě a devět let; a plodil syny a dcery.'),
(1546478,54,1,11,20,'Réhu také živ byl třidceti a dvě létě, a zplodil Sáruga.'),
(1546479,54,1,11,21,'A po zplození Sáruga živ byl Réhu dvě stě a sedm let; a plodil syny a dcery.'),
(1546480,54,1,11,22,'Živ pak byl Sárug třidceti let, a zplodil Náchora.'),
(1546481,54,1,11,23,'A byl živ Sárug po zplození Náchora dvě stě let; a plodil syny a dcery.'),
(1546482,54,1,11,24,'Náchor pak živ byl dvadceti a devět let, a zplodil Táre.'),
(1546483,54,1,11,25,'A živ byl Náchor po zplození Táre sto a devatenácte let; a plodil syny a dcery.'),
(1546484,54,1,11,26,'Živ pak byl Táre sedmdesáte let, a zplodil Abrama, Náchora a Hárana.'),
(1546485,54,1,11,27,'Tito jsou pak rodové Táre: Táre zplodil Abrama, Náchora a Hárana; Háran pak zplodil Lota.'),
(1546486,54,1,11,28,'Umřel pak Háran prvé než Táre otec jeho v zemi narození svého, totiž v Ur Kaldejských.'),
(1546487,54,1,11,29,'I zpojímali sobě ženy Abram a Náchor; jméno ženy Abramovy Sarai, a jméno ženy Náchorovy Melcha, dcera Háranova, kterýž byl otec Melchy a Jeschy.'),
(1546488,54,1,11,30,'Byla pak Sarai neplodná, a neměla dětí.'),
(1546489,54,1,11,31,'I vzal Táre Abrama syna svého, a Lota syna Háranova, vnuka svého, a Sarai nevěstu svou, ženu Abrama syna svého, a vyšli spolu z Ur Kaldejských, aby se brali do země Kananejské, a přišli až do Cháran, a bydlili tam.'),
(1546490,54,1,11,32,'A byli dnové Táre dvě stě a pět let; i umřel Táre v Cháran.'),
(1546491,54,1,12,1,'Nebo byl řekl Hospodin Abramovi: Vyjdi z země své a z příbuznosti své, i z domu otce svého do země, kterouž ukáži tobě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546492,54,1,12,2,'A učiním tě v národ veliký, a požehnám tobě, a zvelebím jméno tvé, a budeš požehnání.'),
(1546493,54,1,12,3,'Požehnám také dobrořečícím tobě, a zlořečícím tobě zlořečiti budu; ano požehnány budou v tobě všecky čeledi země.'),
(1546494,54,1,12,4,'I vyšel Abram, tak jakž mu byl mluvil Hospodin, a šel s ním Lot. (Byl pak Abram v sedmdesáti pěti letech, když vyšel z Cháran.)'),
(1546495,54,1,12,5,'A vzal Abram Sarai manželku svou, a Lota syna bratra svého, a všecko zboží své, kteréhož nabyli, i duše, kterýchž dosáhli v Cháran. A vyšedše, brali se do země Kananejské, až i přišli do ní.'),
(1546496,54,1,12,6,'I prošel Abram tu zemi až k místu Sichem, to jest až k rovině More. A tehdáž Kananejští byli v zemi.'),
(1546497,54,1,12,7,'I ukázal se Hospodin Abramovi a řekl: Semeni tvému dám zemi tuto. Tedy vzdělal tu oltář Hospodinu, kterýž se byl ukázal jemu.'),
(1546498,54,1,12,8,'A odtud podal se k hoře, kteráž leží na východ od Bethel, kdežto rozbil stan svůj, tak že mu Bethel byl na západ, Hai pak na východ; i vzdělal tam oltář Hospodinu, a vzýval jméno Hospodinovo.'),
(1546499,54,1,12,9,'Potom hnul se Abram dále, a odebral se odtud ku poledni.'),
(1546500,54,1,12,10,'Byl pak hlad v té zemi; protož sstoupil Abram do Egypta, aby tam byl pohostinu; nebo veliký byl hlad v té zemi.'),
(1546501,54,1,12,11,'I stalo se, že když přicházel blízko k Egyptu, řekl k Sarai manželce své: Aj, nyní znám, že jsi žena krásné tváři.'),
(1546502,54,1,12,12,'A stane se, že když tě uzří Egyptští, řeknou: To jest manželka jeho; i zabijí mne, tebe pak živé nechají.'),
(1546503,54,1,12,13,'Prav medle, že jsi sestra má, aby mi dobře bylo příčinou tvou, a živa zůstala duše má pro tebe.'),
(1546504,54,1,12,14,'I stalo se, když všel Abram do Egypta, viděli Egyptští ženu, že krásná byla náramně.'),
(1546505,54,1,12,15,'A vidouce ji knížata Faraonova, schválili ji před ním; i vzata jest žena do domu Faraonova.'),
(1546506,54,1,12,16,'Kterýžto i Abramovi dobře učinil pro ni; a měl ovce a voly a osly, i služebníky a děvky, též oslice a velbloudy.'),
(1546507,54,1,12,17,'Ale Hospodin trápil Faraona ranami velikými, i dům jeho, pro Sarai manželku Abramovu.'),
(1546508,54,1,12,18,'Protož povolal Farao Abrama a řekl: Cos mi to učinil? Pročežs mi neoznámil, že ona manželka tvá jest?'),
(1546509,54,1,12,19,'Proč jsi řekl: Sestra má jest? A vzal jsem ji sobě za ženu. Protož nyní, teď máš manželku svou, vezmi a jdi.'),
(1546510,54,1,12,20,'I poručil o něm Farao mužům, a propustili ho, i manželku jeho i všecko, což měl.'),
(1546511,54,1,13,1,'Vstoupil tedy Abram z Egypta on i žena jeho i všecko, což měl, a Lot s ním, ku poledni.'),
(1546512,54,1,13,2,'(Byl pak Abram bohatý velmi na dobytek, na stříbro i na zlato.)'),
(1546513,54,1,13,3,'A šel cestami svými od poledne až do Bethel, až k místu tomu, kdež prvé byl stánek jeho, mezi Bethel a Hai,'),
(1546514,54,1,13,4,'K místu oltáře, kterýž tam byl prvé vzdělal, kdežto vzýval Abram jméno Hospodinovo.'),
(1546515,54,1,13,5,'Také i Lot, kterýž s Abramem chodil, měl ovce a voly i stany.'),
(1546516,54,1,13,6,'A nemohla jim země postačovati, aby spolu bydlili, proto že zboží jich bylo veliké, tak že nemohli spolu bydliti.'),
(1546517,54,1,13,7,'Odkudž vznikla nesnáz mezi pastýři stáda Abramova a mezi pastýři stáda Lotova; nebo Kananejští a Ferezejští tehdáž bydlili v zemi té.'),
(1546518,54,1,13,8,'Řekl tedy Abram k Lotovi: Nechžť, prosím, není nesnáze mezi mnou a tebou, a mezi pastýři mými a pastýři tvými, poněvadž muži bratří jsme.'),
(1546519,54,1,13,9,'Zdaliž není před tebou všecka země? Odděl se, prosím, ode mne. Půjdeš-li na levo, já na pravo se držeti budu; pakli půjdeš na pravo, na levo se držeti budu.'),
(1546520,54,1,13,10,'Pozdvih tedy Lot očí svých, spatřil všecku rovinu vůkol Jordánu, kteráž před tím, než Hospodin zkazil Sodomu a Gomoru, všecka až k Ségor svlažována byla, jako zahrada Hospodinova, a jako země Egyptská.'),
(1546521,54,1,13,11,'I zvolil sobě Lot všecku rovinu Jordánskou, a bral se k východu; a tak oddělili se jeden od druhého.'),
(1546522,54,1,13,12,'Abram bydlil v zemi Kananejské, ale Lot přebýval v městech té roviny, podav stanů až k Sodomě.'),
(1546523,54,1,13,13,'Lidé pak Sodomští byli zlí, a hříšníci před Hospodinem velicí.'),
(1546524,54,1,13,14,'I řekl Hospodin Abramovi, když se oddělil od něho Lot: Pozdvihni nyní očí svých, a pohleď z místa, na němž jsi, na půlnoci a na poledne, i na východ a na západ.'),
(1546525,54,1,13,15,'Nebo všecku zemi, kterouž vidíš, tobě dám a semeni tvému až na věky.'),
(1546526,54,1,13,16,'A rozmnožím símě tvé jako prach země; nebo jestliže kdo bude moci sčísti prach země, tedy i símě tvé sečteno bude.'),
(1546527,54,1,13,17,'Vstaň, projdi tu zemi na dýl i na šíř její; nebo tobě ji dám.'),
(1546528,54,1,13,18,'Tedy Abram hnuv se s stanem, přišel a bydlil v rovinách Mamre, kteréž jsou při Hebronu, kdežto vzdělal oltář Hospodinu.'),
(1546529,54,1,14,1,'Stalo se pak ve dnech těch, že Amrafel král Sinearský, Arioch král Elasarský, Chedorlaomer král Elamitský, a Thádal král Goimský,'),
(1546530,54,1,14,2,'Vyzdvihli válku proti Bérovi králi Sodomskému, a proti Bersovi králi Gomorskému, a Senábovi králi Adamatskému, a Semeberovi králi Seboimskému, a králi Bélamskému, to jest Ségorskému.'),
(1546531,54,1,14,3,'Všickni tito sjeli se do údolí Siddim, to jest již moře solné.'),
(1546532,54,1,14,4,'Dvanácte let sloužili Chedorlaomerovi, třináctého pak léta zprotivili se.'),
(1546533,54,1,14,5,'Protož léta čtrnáctého přitáhl Chedorlaomer a králové, kteříž byli s ním, a pobili Refaimské v Astarotu Karnaimských, a Zuzimské v Cham, a Eminské na rovinách Kariataimských,'),
(1546534,54,1,14,6,'A Horejské na hoře jich Seir, až k rovině Fáran, kteráž leží nad pouští.'),
(1546535,54,1,14,7,'A vracejíce se, přitáhli k En Misfat, kteráž již jest Kádes, a pohubili všecku krajinu Amalechitského, také i Amorejského, bydlícího v Hasesontamar.'),
(1546536,54,1,14,8,'Protož vytáhl král Sodomský, a král Gomorský, a král Adamatský, a král Seboimský, a král Bélamský, to jest Ségorský, a sšikovali se proti nim k bitvě v údolí Siddim,'),
(1546537,54,1,14,9,'Proti Chedorlaomerovi králi Elamitskému, a Thádalovi králi Goimskému, a Amrafelovi králi Sinearskému, i Ariochovi králi Elasarskému, čtyři králové proti pěti.'),
(1546538,54,1,14,10,'(V údolí pak Siddim bylo mnoho studnic klejovatých.) I utíkajíce král Sodomský a Gomorský, padli tam; a kteří pozůstali, utekli na hory.'),
(1546539,54,1,14,11,'A pobravše všecko zboží Sodomských a Gomorských, a všecky potravy jich, odtáhli.'),
(1546540,54,1,14,12,'Vzali také Lota, a zboží jeho, syna bratra Abramova, a odjeli; nebo on bydlil v Sodomě.'),
(1546541,54,1,14,13,'Přišel pak jeden, kterýž byl utekl, a zvěstoval Abramovi Hebrejskému, kterýž tehdáž bydlil v rovinách Mamre Amorejského, bratra Eškolova a bratra Anerova; nebo ti měli smlouvu s Abramem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546542,54,1,14,14,'Uslyšev tedy Abram, že by zajat byl bratr jeho, vypravil způsobných k boji a v domě svém zrozených služebníků tři sta a osmnácte, a honil je až k Dan.'),
(1546543,54,1,14,15,'A odděliv se, připadl na ně v noci, on i služebníci jeho, a porazil je; a stihal je až k Chobah, kteréž leží na levo Damašku.'),
(1546544,54,1,14,16,'I odjal zase všecko zboží; také i Lota bratra svého s statkem jeho zase přivedl, ano i ženy a lid.'),
(1546545,54,1,14,17,'Tedy vyšel král Sodomský proti němu, když se navracoval od pobití Chedorlaomera a králů, kteříž byli s ním, k údolí Sáveh, kteréž jest údolí královské.'),
(1546546,54,1,14,18,'Melchisedech také král Sálem, vynesl chléb a víno; a ten byl kněz Boha silného nejvyššího.'),
(1546547,54,1,14,19,'I požehnal mu a řekl: Požehnaný Abram Bohu silnému nejvyššímu, kterýž vládne nebem a zemí;'),
(1546548,54,1,14,20,'A požehnaný Bůh silný nejvyšší, kterýž dal nepřátely tvé v ruce tvé. I dal mu Abram desátky ze všech věcí.'),
(1546549,54,1,14,21,'Král pak Sodomský řekl Abramovi: Dej mi lid, a zboží vezmi sobě.'),
(1546550,54,1,14,22,'I řekl Abram králi Sodomskému: Pozdvihl jsem ruky své k Hospodinu, Bohu silnému nejvyššímu, kterýž vládne nebem i zemí,'),
(1546551,54,1,14,23,'Že nevezmu od niti až do řeménka obuvi ze všech věcí, kteréž jsou tvé, abys neřekl: Já jsem obohatil Abrama,'),
(1546552,54,1,14,24,'Kromě toliko toho, což snědli bojovníci, a dílu mužů, kteříž se mnou šli, totiž Aner, Eškol a Mamre; oni nechať vezmou díl svůj.'),
(1546553,54,1,15,1,'Když pak ty věci pominuly, stalo se slovo Hospodinovo k Abramovi u vidění, řkoucí: Neboj se, Abrame; já budu pavéza tvá, a odplata tvá velmi veliká.'),
(1546554,54,1,15,2,'Jemužto řekl Abram: Panovníče Hospodine, což mi dáš, poněvadž já scházím bez dětí, a ten, jemuž zanechám domu svého, bude Damašský Eliezer?'),
(1546555,54,1,15,3,'Řekl ještě Abram: Aj, mně jsi nedal semene; a aj, schovanec můj bude mým dědicem.'),
(1546556,54,1,15,4,'A aj, slovo Hospodinovo k němu, řkuci: Nebudeť ten dědicem tvým, ale kterýž vyjde z života tvého, ten dědicem tvým bude.'),
(1546557,54,1,15,5,'I vyvedl jej ven a řekl: Vzhlédniž nyní k nebi, a sečti hvězdy, budeš-li je však moci sčísti? Řekl mu ještě: Tak bude símě tvé.'),
(1546558,54,1,15,6,'I uvěřil Hospodinu, a počteno mu to za spravedlnost.'),
(1546559,54,1,15,7,'(Nebo byl řekl jemu: Já jsem Hospodin, kterýž jsem tě vyvedl z Ur Kaldejských, aťbych dal zemi tuto k dědičnému vládařství.'),
(1546560,54,1,15,8,'I řekl: Panovníče Hospodine, po čem poznám, že ji dědičně obdržím?'),
(1546561,54,1,15,9,'I odpověděl jemu: Vezmi mně jalovici tříletou, a kozu tříletou, a skopce tříletého, hrdličku také a holoubátko.'),
(1546562,54,1,15,10,'Kterýžto vzav ty všecky věci, zroztínal je na poly, a rozložil na dvě straně, jednu polovici proti druhé; ptáků pak nezroztínal.'),
(1546563,54,1,15,11,'Ptáci pak sedali na ta mrtvá těla, a Abram je sháněl.'),
(1546564,54,1,15,12,'I stalo se, když slunce zapadalo, že dřímota těžká připadla na Abrama; a aj, hrůza a tma veliká obklíčila jej).'),
(1546565,54,1,15,13,'Řekl tedy Bůh Abramovi: To zajisté věz, že pohostinu bude símě tvé v zemi cizí, a v službu je podrobí, a trápiti je budou za čtyři sta let.'),
(1546566,54,1,15,14,'Však národ, jemuž sloužiti budou, já souditi budu; a potom vyjdou s velikým zbožím.'),
(1546567,54,1,15,15,'Ty pak půjdeš k otcům svým v pokoji; a pohřben budeš v starosti dobré.'),
(1546568,54,1,15,16,'A čtvrté pokolení sem se navrátí; nebť ještě není doplněna nepravost Amorejských.'),
(1546569,54,1,15,17,'I stalo se, když zapadlo slunce, a tma bylo, a aj, ukázala se pec kouřící se, a pochodně ohnivá, kteráž šla mezi díly těmi.'),
(1546570,54,1,15,18,'V ten den učinil Hospodin smlouvu s Abramem, řka: Semeni tvému dám zemi tuto, od řeky Egyptské až do řeky té veliké, řeky Eufraten:'),
(1546571,54,1,15,19,'Cinejské, Cenezejské, Cethmonské,'),
(1546572,54,1,15,20,'A Hetejské, Ferezejské, a Refaimské,'),
(1546573,54,1,15,21,'Amorejské, i Kananejské také, a Gergezejské a Jebuzejské.'),
(1546574,54,1,16,1,'Sarai pak manželka Abramova jemu nerodila; a měla děvku Egyptskou, jménem Agar.'),
(1546575,54,1,16,2,'I řekla Sarai Abramovi: Aj, nyní Hospodin zavřel život můj, abych nerodila; vejdi, prosím, k děvce mé, zda bych aspoň z ní mohla míti syny. I povolil Abram řeči Sarai.'),
(1546576,54,1,16,3,'Tedy vzavši Sarai manželka Abramova Agar Egyptskou děvku svou, po desíti letech, jakž bydliti počal Abram v zemi Kananejské, dala ji Abramovi muži svému za ženu.'),
(1546577,54,1,16,4,'I všel k Agar, kterážto počala. Viduci pak ona, že počala, zlehčila sobě paní svou.'),
(1546578,54,1,16,5,'I řekla Sarai Abramovi: Křivdou mou tys vinen; já jsem dala děvku svou v lůno tvé, kterážto viduci, že počala, zlehčila mne sobě. Sudiž Hospodin mezi mnou a mezi tebou.'),
(1546579,54,1,16,6,'I řekl Abram k Sarai: Aj, děvka tvá v moci tvé; učiň s ní, cožť se za dobré vidí. Tedy trápila ji Sarai, a ona utekla od ní.'),
(1546580,54,1,16,7,'Našel ji pak anděl Hospodinův u studnice vody na poušti, u studnice té, kteráž jest při cestě Sur.'),
(1546581,54,1,16,8,'A řekl: Agar, děvko Sarai, odkud jdeš, a kam se béřeš? I řekla: Od tváři Sarai paní své já utíkám.'),
(1546582,54,1,16,9,'Tedy řekl jí anděl Hospodinův: Navrať se ku paní své, a pokoř se pod ruku její.'),
(1546583,54,1,16,10,'Opět řekl anděl Hospodinův: Velice rozmnožím símě tvé, aniž bude moci sečteno býti pro množství.'),
(1546584,54,1,16,11,'Potom také řekl anděl Hospodinův: Aj, ty jsi těhotná, a tudíž porodíš syna, a nazůveš jméno jeho Izmael; nebo uslyšel Hospodin trápení tvé.'),
(1546585,54,1,16,12,'Budeť pak lítý člověk; ruce jeho proti všechněm, a ruce všech proti němu; a před tváří všech bratří svých bydliti bude.'),
(1546586,54,1,16,13,'I nazvala Agar jméno Hospodinovo, kterýž mluvil jí: Ty jsi silný Bůh vidění; nebo řekla: Zdaliž teď také nevidím po tom, kterýž mne viděl?'),
(1546587,54,1,16,14,'Protož nazvala studnici tu studnicí Živého vidoucího mne. Aj, ta jest mezi Kádes a Barad.'),
(1546588,54,1,16,15,'Porodila pak Agar Abramovi syna; a nazval Abram jméno syna svého, kteréhož porodila Agar, Izmael.'),
(1546589,54,1,16,16,'Abram pak byl v osmdesáti šesti letech, když mu porodila Agar Izmaele.'),
(1546590,54,1,17,1,'Když pak Abram byl v devadesáti devíti letech, ukázal se mu Hospodin, a řekl jemu: Já jsem Bůh silný všemohoucí; chodiž ustavičně přede mnou a budiž dokonalým.'),
(1546591,54,1,17,2,'A učiním smlouvu svou mezi sebou a tebou a rozmnožím tě náramně velmi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546592,54,1,17,3,'Padl pak Abram na tvář svou; i mluvil Bůh s ním, řka:'),
(1546593,54,1,17,4,'Jáť jsem, aj, smlouva má s tebou, a budeš otcem národů mnohých.'),
(1546594,54,1,17,5,'Aniž více slouti bude jméno tvé Abram, ale bude jméno tvé Abraham; nebo otcem mnohých národů učinil jsem tě.'),
(1546595,54,1,17,6,'A učiním, abys se rozplodil náramně velmi, a rozšířím tě v národy; i králové z tebe vyjdou.'),
(1546596,54,1,17,7,'Utvrdím také smlouvu svou mezi sebou a tebou, i mezi semenem tvým po tobě, po rodech jejich, za smlouvu věčnou, totiž abych byl Bohem tvým i semene tvého po tobě.'),
(1546597,54,1,17,8,'Nadto dám tobě i semeni tvému po tobě zemi, v nížto obýváš pohostinu, všecku zemi Kananejskou k vládařství věčnému; a budu jejich Bohem.'),
(1546598,54,1,17,9,'Řekl ještě Bůh Abrahamovi: Ty pak ostříhati budeš smlouvy mé, ty i símě tvé po tobě, po rodech svých.'),
(1546599,54,1,17,10,'Tatoť jest smlouva má mezi mnou a mezi vámi, i mezi semenem tvým po tobě, kteréž ostříhati budete: Aby obřezán byl mezi vámi každý pohlaví mužského.'),
(1546600,54,1,17,11,'Obřežete pak tělo hanby své; a to bude znamením smlouvy mezi mnou a mezi vámi.'),
(1546601,54,1,17,12,'Každý tedy pohlaví mužského osmého dne obřezán bude mezi vámi po rodech vašich, doma narozený i koupený za stříbro, z kterých by koli cizozemců byl, jenž není z semene tvého.'),
(1546602,54,1,17,13,'Konečně ať jest obřezán narozený v domě tvém, i koupený za peníze tvé; a budeť smlouva má na těle vašem za smlouvu věčnou.'),
(1546603,54,1,17,14,'Neobřezaný pak pacholík, kterýž by neobřezal těla neobřízky své, vyhlazena zajisté bude duše ta z lidu svého; nebo smlouvu mou zrušil.'),
(1546604,54,1,17,15,'Řekl také Bůh Abrahamovi: Sarai manželce své nebudeš říkati Sarai, ale Sára bude jméno její.'),
(1546605,54,1,17,16,'Nebo požehnám jí a dámť z ní syna; požehnámť jí, a bude v národy; králové národů z ní vyjdou.'),
(1546606,54,1,17,17,'Tedy padl Abraham na tvář svou, a zasmáv se, řekl v srdci svém: Zdali stoletému narodí se syn? A zdali Sára v devadesáti letech porodí?'),
(1546607,54,1,17,18,'I řekl Abraham Bohu: Ó byť jen Izmael živ byl před tebou!'),
(1546608,54,1,17,19,'Jemužto řekl Bůh: Nýbrž Sára manželka tvá porodí tobě syna, a nazůveš jméno jeho Izák; i utvrdím smlouvu svou s ním za smlouvu věčnou, i s semenem jeho po něm.'),
(1546609,54,1,17,20,'Také o Izmaele uslyšel jsem tě; a aj, požehnám jemu, a učiním to, aby se rozplodil, a rozmnožím ho náramně velmi; dvanáctero knížat zplodí, a rozšířím jej v národ veliký.'),
(1546610,54,1,17,21,'Ale smlouvu svou utvrdím s Izákem, kteréhožť porodí Sára po roce, při tomto času.'),
(1546611,54,1,17,22,'A když dokonal Bůh řeč svou s ním, vstoupil od Abrahama.'),
(1546612,54,1,17,23,'Vzal tedy Abraham Izmaele syna svého, i všecky zrozené v domě svém, i všecky koupené za stříbro své, každého, kdož byl pohlaví mužského, z domácích svých, a obřezal tělo neobřízky jejich hned v ten den, jakž s ním Bůh mluvil.'),
(1546613,54,1,17,24,'A byl Abraham v devadesáti devíti letech, když obřezáno bylo tělo neobřízky jeho.'),
(1546614,54,1,17,25,'Izmael pak syn jeho byl v třinácti letech, když obřezáno bylo tělo neobřízky jeho.'),
(1546615,54,1,17,26,'Jednoho a téhož dne obřezáni jsou, Abraham a Izmael syn jeho.'),
(1546616,54,1,17,27,'I všickni domácí jeho, doma zrození i za stříbro od cizozemce koupení, obřezáni jsou s ním.'),
(1546617,54,1,18,1,'Ukázal se pak jemu Hospodin v rovině Mamre; a on seděl u dveří stanu, když veliké horko na den bylo.'),
(1546618,54,1,18,2,'A když pozdvihl očí svých, viděl, a aj, tři muži stáli naproti němu. Kteréžto jakž uzřel, běžel jim vstříc ode dveří stanu, a sklonil se až k zemi.'),
(1546619,54,1,18,3,'A řekl: Pane můj, jestliže jsem nyní nalezl milost před očima tvýma, prosím, nepomíjej služebníka svého.'),
(1546620,54,1,18,4,'Přineseno bude trochu vody, a umyjete nohy své, a odpočinete pod stromem.'),
(1546621,54,1,18,5,'Zatím přinesu kus chleba, a posilníte srdce svého; potom půjdete, poněvadž mimo služebníka svého jdete. I řekli: Tak učiň, jakž jsi mluvil.'),
(1546622,54,1,18,6,'Tedy pospíšil Abraham do stanu k Sáře, a řekl: Spěšně tři míry mouky bělné zadělej, a napec podpopelných chlebů.'),
(1546623,54,1,18,7,'Abraham pak běžel k stádu; a vzav tele mladé a dobré, dal služebníku, kterýžto pospíšil připraviti je.'),
(1546624,54,1,18,8,'Potom vzav másla a mléka, i tele, kteréž připravil, položil před ně; sám pak stál při nich pod stromem, i jedli.'),
(1546625,54,1,18,9,'Řekli pak jemu: Kde jest Sára manželka tvá? Kterýžto odpověděl: Teď v stanu.'),
(1546626,54,1,18,10,'A řekl: Jistotně se navrátím k tobě vedlé času života, a aj, syna míti bude Sára manželka tvá. Ale Sára poslouchala u dveří stanu, kteréž byly za ním.'),
(1546627,54,1,18,11,'Abraham pak i Sára byli staří a sešlého věku, a přestal byl Sáře běh ženský.'),
(1546628,54,1,18,12,'I smála se Sára sama v sobě, řkuci: Teprv když jsem se sstarala, v rozkoše se vydám? A ještě i pán můj se sstaral.'),
(1546629,54,1,18,13,'Tedy řekl Hospodin Abrahamovi: Proč jest se smála Sára, řkuci: Zdaliž opravdu ještě roditi budu, a já se sstarala?'),
(1546630,54,1,18,14,'Zdaliž co skrytého bude před Hospodinem? K času určitému navrátím se k tobě vedlé času života, a Sára bude míti syna.'),
(1546631,54,1,18,15,'Zapřela pak Sára a řekla: Nesmála jsem se; nebo se bála. I řekl Hospodin: Neníť tak, ale smála jsi se.'),
(1546632,54,1,18,16,'Tedy vstavše odtud muži ti, obrátili se k Sodomě; Abraham pak šel s nimi, aby je provodil.'),
(1546633,54,1,18,17,'A řekl Hospodin: Zdali já zatajím před Abrahamem, což dělati budu?'),
(1546634,54,1,18,18,'Poněvadž Abraham jistotně bude v národ veliký a silný, a požehnáni budou v něm všickni národové země.'),
(1546635,54,1,18,19,'Nebo znám jej; protož přikáže synům svým a domu svému po sobě, aby ostříhali cesty Hospodinovy, a činili spravedlnost a soud, aťby naplnil Hospodin Abrahamovi, což mu zaslíbil.'),
(1546636,54,1,18,20,'I řekl Hospodin: Proto že rozmnožen jest křik Sodomských a Gomorských, a hřích jejich že obtížen jest náramně:'),
(1546637,54,1,18,21,'Sstoupím již a pohledím, jestliže podle křiku jejich, kterýž přišel ke mně, činili, důjde na ně setření; a pakli toho není, zvím.'),
(1546638,54,1,18,22,'A obrátivše se odtud muži, šli do Sodomy; Abraham pak ještě stál před Hospodinem.'),
(1546639,54,1,18,23,'V tom přistoupiv Abraham, řekl: Zdali také zahladíš spravedlivého s bezbožným?'),
(1546640,54,1,18,24,'Bude-li padesáte spravedlivých v tom městě, zdali předce zahubíš, a neodpustíš místu pro padesáte spravedlivých, kteříž jsou v něm?'),
(1546641,54,1,18,25,'Odstup to od tebe, abys takovou věc učiniti měl, abys usmrtil spravedlivého s bezbožným; takť by byl spravedlivý jako bezbožný. Odstup to od tebe; zdaliž soudce vší země neučiní soudu?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546642,54,1,18,26,'I řekl Hospodin: Jestliže naleznu v Sodomě, v městě tom, padesáte spravedlivých, odpustím všemu tomu místu pro ně.'),
(1546643,54,1,18,27,'A odpovídaje Abraham, řekl: Aj, nyní chtěl bych mluviti ku Pánu svému, ačkoli jsem prach a popel.'),
(1546644,54,1,18,28,'Co pak, nedostane-li se ku padesáti spravedlivým pěti, zdali zkazíš pro těch pět všecko město? I řekl: Nezahladím, jestliže najdu tam čtyřidceti pět.'),
(1546645,54,1,18,29,'Opět mluvil Abraham a řekl: Snad nalezeno bude tam čtyřidceti? A odpověděl: Neučiním pro těch čtyřidceti.'),
(1546646,54,1,18,30,'I řekl Abraham: Prosím, nechť se nehněvá Pán můj, že mluviti budu: Snad se jich nalezne tam třidceti? Odpověděl: Neučiním, jestliže naleznu tam třidceti.'),
(1546647,54,1,18,31,'A opět řekl: Aj, nyní počal jsem mluviti ku Pánu svému: Snad se nalezne tam dvadceti? Odpověděl: Nezahladím i pro těch dvadceti.'),
(1546648,54,1,18,32,'Řekl ještě: Prosím, ať se nehněvá Pán můj, jestliže jednou ještě mluviti budu: Snad se jich najde tam deset? Odpověděl: Nezahladím i pro těch deset.'),
(1546649,54,1,18,33,'I odšel Hospodin, když dokonal řeč k Abrahamovi; Abraham pak navrátil se k místu svému.'),
(1546650,54,1,19,1,'Přišli pak dva andělé do Sodomy u večer, a Lot seděl v bráně Sodomské. Kteréžto když uzřel, vstav, šel jim v cestu a sklonil se tváří až k zemi.'),
(1546651,54,1,19,2,'A řekl: Aj, prosím páni moji, uchylte se nyní do domu služebníka svého, a zůstaňte přes noc; umyjete také nohy své a ráno vstanouce, půjdete cestou svou. Oni pak odpověděli: Nikoli, ale přenocujeme na ulici.'),
(1546652,54,1,19,3,'Ale když on je velmi nutil, obrátivše se k němu, vešli do domu jeho. I udělal jim hody, a napekl chlebů přesných, i jedli.'),
(1546653,54,1,19,4,'Prvé pak než lehli, muži města toho, muži Sodomští, osuli se vůkol domu toho, od mladého až do starého, všecken lid odevšad.'),
(1546654,54,1,19,5,'I volali na Lota, a řekli jemu: Kde jsou ti muži, kteříž přišli k tobě v noci? Vyveď je k nám, ať je poznáme.'),
(1546655,54,1,19,6,'I vyšel k nim Lot ven, a zavřel po sobě dvéře.'),
(1546656,54,1,19,7,'A řekl: Prosím, bratří moji, nečiňte zlého.'),
(1546657,54,1,19,8,'Aj, mám teď dvě dcery, kteréžto nepoznaly muže; vyvedu je nyní k vám, čiňte s nimi, jak se vám líbí; toliko mužům těmto nic nečiňte, poněvadž vešli pod stín střechy mé.'),
(1546658,54,1,19,9,'I řekli: Odejdi tam! A mluvili: Sám se dostal sem pohostinu, a chce nás souditi? Nyní tobě hůř uděláme, než jim. I obořili se násilně na muže toho, totiž na Lota, a přistoupili, aby vylomili dvéře.'),
(1546659,54,1,19,10,'Tedy muži ti vztáhli ven ruku svou, a uvedli Lota k sobě do domu, a dvéře zavřeli.'),
(1546660,54,1,19,11,'A ty muže, kteříž byli přede dveřmi domu, ranili slepotou velikou, od nejmenšího až do největšího, tak že ustali, hledajíce dveří.'),
(1546661,54,1,19,12,'I řekli muži k Lotovi: Máš-li ještě zde koho, buď zetě neb syny své, neb dcery své, i všecko, což máš v městě, vyveď z místa tohoto.'),
(1546662,54,1,19,13,'Nebo zkazíme místo toto, proto že se velmi rozmohl křik jejich před Hospodinem, a poslal nás Hospodin, abychom zkazili je.'),
(1546663,54,1,19,14,'Vyšed tedy Lot, mluvil k zeťům svým, kteříž již měli pojímati dcery jeho, a řekl: Vstaňte, vyjděte z místa tohoto, nebo zkazí Hospodin město toto. Ale zdálo se zeťům jeho, jako by žertoval.'),
(1546664,54,1,19,15,'A když zasvitávalo, nutili andělé Lota, řkouce: Vstaň, vezmi ženu svou a dvě dcery své, kteréž tu jsou, abys nezahynul v pomstě města.'),
(1546665,54,1,19,16,'A když prodléval, chopili muži ruku jeho, a ruku ženy jeho, a ruku dvou dcer jeho, nebo se slitoval nad ním Hospodin; i vyvedli jej, a pustili za městem.'),
(1546666,54,1,19,17,'A stalo se, když je vedli ven, řekl jeden: Zachovejž život svůj, neohlédej se zpět, ani se zastavuj na vší této rovině; ujdi na horu, abys nezahynul.'),
(1546667,54,1,19,18,'I řekl jim Lot: Ne tak, prosím, páni moji.'),
(1546668,54,1,19,19,'Aj, nyní nalezl služebník tvůj milost před očima tvýma, a veliké jest milosrdenství tvé, kteréž jsi učinil se mnou, když jsi zachoval duši mou; ale jáť nebudu moci ujíti na tu horu, aby mne nepostihlo to zlé, a umřel bych.'),
(1546669,54,1,19,20,'Hle, teď jest toto město blízko, do něhož bych utekl, a toť jest malé; prosím, nechť tam ujdu; však pak neveliké jest, a živa bude duše má.'),
(1546670,54,1,19,21,'I řekl k němu: Aj, uslyšel jsem žádost tvou i v této věci, abych nepodvrátil města toho, o němž jsi mluvil.'),
(1546671,54,1,19,22,'Pospěšiž, ujdi tam; neboť nebudu moci učiniti ničehož, dokudž tam nedojdeš. A z té příčiny nazváno jest jméno města toho Ségor.'),
(1546672,54,1,19,23,'Slunce vzcházelo nad zemi, když Lot všel do Ségor.'),
(1546673,54,1,19,24,'A Hospodin dštil na Sodomu a naGomoru sirou a ohněm od Hospodina s nebe.'),
(1546674,54,1,19,25,'A podvrátil ta města i všecku tu rovinu, všecky také obyvatele těch měst, i všecko, což roste z země.'),
(1546675,54,1,19,26,'I ohlédla se žena jeho, jduc za ním, a obrácena jest v sloup solný.'),
(1546676,54,1,19,27,'Vstav pak Abraham ráno, pospíšil k místu tomu, kdež byl stál před Hospodinem.'),
(1546677,54,1,19,28,'A pohleděv k Sodomě a Gomoře,i na všecku zemi té roviny, uzřel, a aj, vystupoval dým z země té, jako dým z vápenice.'),
(1546678,54,1,19,29,'Stalo se tedy, když kazil Bůh města té roviny, že se rozpomenul Bůh na Abrahama, a vytrhl Lota z prostředku podvrácení, když podvracel města, v nichž bydlil Lot.'),
(1546679,54,1,19,30,'Potom vyšel Lot z Ségor, a bydlil na hoře té, a obě dvě dcery jeho s ním; nebo nesměl bydliti v Ségor. I bydlil v jeskyni s oběma dcerami svými.'),
(1546680,54,1,19,31,'I řekla prvorozená k mladší: Otec náš jest již starý, a není žádného muže na zemi, ješto by všel k nám podlé obyčeje vší země.'),
(1546681,54,1,19,32,'Poď, dejme píti otci našemu vína, a spěme s ním, abychom zachovaly z otce našeho símě.'),
(1546682,54,1,19,33,'I daly píti otci svému vína té noci; a všedši prvorozená, spala s otcem svým, kterýžto necítil, ani když lehla, ani když vstala.'),
(1546683,54,1,19,34,'Nazejtří pak řekla prvorozená k mladší: Aj, spala jsem včerejší noci s otcem svým; dejme mu píti vína ještě této noci; potom vejduc, spi s ním, a zachovejme símě z otce našeho.'),
(1546684,54,1,19,35,'I daly píti ještě té noci otci svému vína; a vstala ta mladší, a spala s ním; on pak necítil, ani když ona lehla, ani když vstala.'),
(1546685,54,1,19,36,'A tak počaly obě dcery Lotovy z otce svého.'),
(1546686,54,1,19,37,'I porodila prvorozená syna, a nazvala jméno jeho Moáb; onť jest otec Moábských až do dnešního dne.'),
(1546687,54,1,19,38,'I mladší také porodila syna, a nazvala jméno jeho Ben Ammon; onť jest otcem Ammonitských až do dnešního dne.'),
(1546688,54,1,20,1,'Odtud bral se Abraham do země polední, aby bydlil mezi Kádes a Sur; i byl pohostinu v Gerar;'),
(1546689,54,1,20,2,'Kdežto pravil Abraham o Sáře manželce své: Sestra má jest. Tedy poslav Abimelech, král Gerarský, vzal Sáru.'),
(1546690,54,1,20,3,'Ale přišed Bůh k Abimelechovi ve snách v noci, řekl jemu: Aj, ty již umřeš pro ženu, kterouž jsi vzal, poněvadž jest vdaná za muže.'),
(1546691,54,1,20,4,'Abimelech pak nepřiblížil se k ní; protož řekl: Pane, zdaž také spravedlivý národ zabiješ?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546692,54,1,20,5,'Zdaliž mi sám nepravil: Sestra má jest? A ona též pravila: Bratr můj jest. V upřímnosti srdce svého a v nevinnosti rukou svých učinil jsem to.'),
(1546693,54,1,20,6,'I řekl jemu Bůh ve snách: Jáť také vím, že v upřímnosti srdce svého učinil jsi to, a já také zdržel jsem tě, abys nezhřešil proti mně; protož nedalť jsem se jí dotknouti.'),
(1546694,54,1,20,7,'Nyní tedy, navrať ženu muži tomu; nebo prorok jest, a modliti se bude za tebe, a živ budeš. Pakli jí nenavrátíš, věz, že smrtí umřeš ty i všecko, což tvého jest.'),
(1546695,54,1,20,8,'A vstav Abimelech ráno, svolal všecky služebníky své, a vypravoval všecka slova ta v uši jejich. I báli se ti muži velmi.'),
(1546696,54,1,20,9,'Potom povolav Abimelech Abrahama, řekl jemu: Co jsi nám to učinil? A co jsem zhřešil proti tobě, že jsi uvedl na mne a na království mé hřích veliký? Učinils mi, čehož jsi učiniti neměl.'),
(1546697,54,1,20,10,'A řekl opět Abimelech Abrahamovi: Cos myslil, žes takovou věc učinil?'),
(1546698,54,1,20,11,'Odpověděl Abraham: Řekl jsem: Jistě že není bázně Boží na místě tomto, a zabijí mne pro ženu mou.'),
(1546699,54,1,20,12,'A také v pravdě jest sestra má, dcera otce mého, však ne dcera matky mé; a pojal jsem ji sobě za manželku.'),
(1546700,54,1,20,13,'Když pak vyvedl mne Bůh z domu otce mého, abych pohostinu bydlil, tedy řekl jsem jí: Toto mi dobrodiní učiníš: Na každém místě, kamž půjdeme, prav o mně: Bratr můj jest.'),
(1546701,54,1,20,14,'Tedy vzav Abimelech ovce a voly, služebníky také a děvky, dal je Abrahamovi; a navrátil mu Sáru manželku jeho.'),
(1546702,54,1,20,15,'A řekl Abimelech: Aj, země má před tebou; kdežť se koli příhodné býti vidí, tu přebývej.'),
(1546703,54,1,20,16,'Sáře pak řekl: Aj, dal jsem tisíc stříbrných bratru tvému, hle, onť jest tobě zástěrou očí u všech, kteříž jsou s tebou. A všemi těmito věcmi Sára poučena byla.'),
(1546704,54,1,20,17,'I modlil se Abraham Bohu, a uzdravil Bůh Abimelecha, a ženu jeho, a děvky jeho; i rodily.'),
(1546705,54,1,20,18,'Nebo byl zavřel Hospodin každý život ženský v domě Abimelechově, pro Sáru manželku Abrahamovu.'),
(1546706,54,1,21,1,'Navštívil pak Hospodin Sáru, tak jakž byl řekl; a učinil Hospodin Sáře, jakož byl mluvil.'),
(1546707,54,1,21,2,'Nebo počala a porodila Sára Abrahamovi syna v starosti jeho, v ten čas, kterýž předpověděl Bůh.'),
(1546708,54,1,21,3,'A nazval Abraham jméno syna svého, kterýž se mu narodil, jehož porodila Sára, Izák.'),
(1546709,54,1,21,4,'A obřezal Abraham syna svého Izáka, když byl v osmi dnech, tak jakž mu byl přikázal Bůh.'),
(1546710,54,1,21,5,'Byl pak Abraham ve stu letech, když se mu narodil Izák syn jeho.'),
(1546711,54,1,21,6,'I řekla Sára: Radost mi učinil Bůh; kdokoli uslyší, radovati se bude spolu se mnou.'),
(1546712,54,1,21,7,'A přidala: Kdo by byl řekl Abrahamovi, že bude Sára děti kojiti? A však jsem porodila syna v starosti jeho.'),
(1546713,54,1,21,8,'I rostlo dítě a ostaveno jest. Tedy učinil Abraham veliké hody v ten den, v němž ostaven byl Izák.'),
(1546714,54,1,21,9,'Viděla pak Sára, že syn Agar Egyptské, kteréhož porodila Abrahamovi, jest posměvač.'),
(1546715,54,1,21,10,'I řekla Abrahamovi: Vyvrz děvku tuto i syna jejího; neboť nebude dědicem syn děvky té s synem mým Izákem.'),
(1546716,54,1,21,11,'Ale Abraham velmi těžce nesl tu řeč, pro syna svého.'),
(1546717,54,1,21,12,'I řekl Bůh Abrahamovi: Nestěžuj sobě o dítěti a o děvce své; cožkoli řekla tobě Sára, povol řeči její, nebo v Izákovi nazváno bude tobě símě.'),
(1546718,54,1,21,13,'A však i syna děvky učiním v národ; nebo tvé símě jest.'),
(1546719,54,1,21,14,'Vstal tedy Abraham velmi ráno, a vzav chléb a láhvici vody, dal Agar a vložil na rameno její, a pustil ji od sebe i s dítětem. Kterážto odešla a chodila po poušti Bersabé.'),
(1546720,54,1,21,15,'A když nebylo vody v láhvici, povrhla dítě pod jedním stromem.'),
(1546721,54,1,21,16,'A odšedši, sedla naproti tak daleko, jako by mohl z lučiště dostřeliti; nebo pravila: Nebudu se dívati na smrt dítěte. Seděla tedy naproti, a pozdvihši hlasu svého, plakala.'),
(1546722,54,1,21,17,'I uslyšel Bůh hlas dítěte; a anděl Boží s nebe zavolal na Agar, a řekl jí: Coť jest, Agar? Neboj se; nebo Bůh uslyšel hlas dítěte z místa, na kterémž jest.'),
(1546723,54,1,21,18,'Vstaň, vezmi dítě, a ujmi je rukou svou; nebo v národ veliký učiním je.'),
(1546724,54,1,21,19,'A otevřel Bůh oči její, aby uzřela studnici vody. I šla a naplnila láhvici vodou, a napojila dítě.'),
(1546725,54,1,21,20,'A Bůh byl s dítětem, kteréžto zrostlo a bydlilo na poušti, a byl z něho střelec.'),
(1546726,54,1,21,21,'Bydlil pak na poušti Fáran; i vzala mu matka jeho ženu z země Egyptské.'),
(1546727,54,1,21,22,'Stalo se pak toho času, že mluvil Abimelech a Fikol, kníže vojska jeho, k Abrahamovi těmito slovy: Bůh s tebou jest ve všech věcech, kteréž ty činíš.'),
(1546728,54,1,21,23,'Protož nyní, přisáhni mi teď skrze Boha: Toto ať se stane, jestliže mi sklamáš, neb synu mému, aneb vnuku mému; vedlé milosrdenství, kteréž jsem já učinil s tebou, i ty že učiníš se mnou a s zemí, v níž jsi byl pohostinu.'),
(1546729,54,1,21,24,'I řekl Abraham: A já přisáhnu.'),
(1546730,54,1,21,25,'(A přitom domlouval se Abraham na Abimelecha o studnici vody, kterouž mu mocí odjali služebníci Abimelechovi.'),
(1546731,54,1,21,26,'I řekl Abimelech: Nevím, kdo by učinil takovou věc; a aniž jsi ty mi oznámil, aniž jsem já také co slyšel, až dnes.)'),
(1546732,54,1,21,27,'Vzav tedy Abraham ovce i voly dal Abimelechovi; a vešli oba dva v smlouvu.'),
(1546733,54,1,21,28,'A postavil Abraham sedm jehnic stáda obzvlášť.'),
(1546734,54,1,21,29,'I řekl Abimelech Abrahamovi: K čemu jest těchto sedm jehnic, kteréž jsi postavil obzvlášť?'),
(1546735,54,1,21,30,'Odpověděl: Že sedm těch jehnic vezmeš z ruky mé, aby mi to bylo na svědectví, že jsem kopal studnici tuto.'),
(1546736,54,1,21,31,'Pročež nazváno jest to místo Bersabé, že tu oba dva přisáhli.'),
(1546737,54,1,21,32,'A tak učinili smlouvu v Bersabé. Vstav pak Abimelech a Fikol, kníže vojska jeho, navrátili se do země Filistinské.'),
(1546738,54,1,21,33,'I nasázel stromoví v Bersabé, a vzýval tam jméno Hospodina, Boha silného, věčného.'),
(1546739,54,1,21,34,'A bydlil Abraham v zemi Filistinské za mnoho dní.'),
(1546740,54,1,22,1,'Když pakty věci pominuly, zkusil Bůh Abrahama, a řekl k němu: Abrahame! Kterýžto odpověděl: Teď jsem.'),
(1546741,54,1,22,2,'I řekl: Vezmi nyní syna svého, toho jediného svého, kteréhož miluješ, Izáka, a jdi do země Moria; a obětuj ho tam v obět zápalnou na jedné hoře, o níž povím tobě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546742,54,1,22,3,'Tedy vstav Abraham velmi ráno, osedlal osla svého a vzal dva služebníky své s sebou, a Izáka syna svého; a nasekav dříví k oběti zápalné, vstal a bral se k místu, o němž pověděl mu Bůh.'),
(1546743,54,1,22,4,'Třetího pak dne pozdvihl Abraham očí svých, a uzřel to místo zdaleka.'),
(1546744,54,1,22,5,'A řekl Abraham služebníkům svým: Pozůstaňte vy tuto s oslem, já pak a dítě půjdeme tamto; a pomodlíce se, navrátíme se k vám.'),
(1546745,54,1,22,6,'Tedy vzal Abraham dříví k zápalné oběti, a vložil je na Izáka syna svého; sám pak nesl v ruce své oheň a meč. I šli oba spolu.'),
(1546746,54,1,22,7,'Mluvě pak Izák Abrahamovi otci svému, řekl: Otče můj! Kterýž odpověděl: Co chceš, synu můj? A řekl: Aj, teď oheň a dříví, a kdež hovádko k zápalné oběti?'),
(1546747,54,1,22,8,'Odpověděl Abraham: Bůh opatří sobě hovádko k oběti zápalné,synu můj. A šli předce oba spolu.'),
(1546748,54,1,22,9,'A když přišli k místu, o němž mu byl mluvil Bůh, udělal tu Abraham oltář, a srovnal dříví; a svázav syna svého, vložil ho na oltář na dříví.'),
(1546749,54,1,22,10,'I vztáhl Abraham ruku svou, a vzal meč, aby zabil syna svého.'),
(1546750,54,1,22,11,'Tedy zavolal na něho anděl Hospodinův s nebe a řekl: Abrahame, Abrahame! Kterýžto odpověděl: Aj, já.'),
(1546751,54,1,22,12,'I řekl jemu: Nevztahuj ruky své na dítě, aniž mu co čiň; neboť jsem již poznal, že se Boha bojíš, když jsi neodpustil synu svému, jedinému svému pro mne.'),
(1546752,54,1,22,13,'A pozdvih Abraham očí svých, viděl, a hle, skopec za ním vězel v trní za rohy své. I šel Abraham a vzal skopce toho, a obětoval jej v obět zápalnou místo syna svého.'),
(1546753,54,1,22,14,'A nazval Abraham jméno místa toho: Hospodin opatří. Odkudž říká se do dnes: Na hoře Hospodinově opatří se.'),
(1546754,54,1,22,15,'Zvolal pak anděl Hospodinův na Abrahama podruhé s nebe,'),
(1546755,54,1,22,16,'A řekl: Skrze sebe samého přisáhl jsem, praví Hospodin, poněvadž jsi učinil tu věc, že jsi neodpustil synu svému, jedinému svému:'),
(1546756,54,1,22,17,'Požehnám velmi tobě, a velice rozmnožím símě tvé jako hvězdy nebeské, a jako písek, kterýž jest na břehu mořském; nadto dědičně vládnouti bude símě tvé branami nepřátel svých.'),
(1546757,54,1,22,18,'Ano požehnáni budou v semeni tvém všickni národové země, proto že jsi uposlechl hlasu mého.'),
(1546758,54,1,22,19,'Tedy navrátil se Abraham k služebníkům svým; a vstavše, šli spolu do Bersabé; nebo bydlil Abraham v Bersabé.'),
(1546759,54,1,22,20,'A když se tyto věci staly, zvěstováno jest Abrahamovi v tato slova: Aj, porodila také Melcha syny Náchorovi, bratru tvému:'),
(1546760,54,1,22,21,'Husa prvorozeného svého, a Buza bratra jeho, a Chamuele, otce Aramova;'),
(1546761,54,1,22,22,'A Kazeda a Azana, a Feldasa, a Jidlafa i Bathuele.'),
(1546762,54,1,22,23,'Bathuel pak zplodil Rebeku. Osm těchto porodila Melcha Náchorovi, bratru Abrahamovu.'),
(1546763,54,1,22,24,'Ale i ženina jeho, jejíž jméno bylo Réma, porodila také ona Tábe a Gahama, Thása a Máchu.'),
(1546764,54,1,23,1,'Živa pak byla Sára sto a sedmmecítma let; ta jsou léta života Sáry.'),
(1546765,54,1,23,2,'A umřela v městě Arbe, kteréž slove Hebron, v zemi Kananejské. I přišel Abraham, aby kvílil nad Sárou, a plakal jí.'),
(1546766,54,1,23,3,'Potom vstav Abraham od mrtvého svého, mluvil k synům Het, řka:'),
(1546767,54,1,23,4,'Hostem a příchozím jsem u vás; dejte mi místo ku pohřbu u vás, abych pochoval mrtvého svého od tváři své.'),
(1546768,54,1,23,5,'A odpovídajíce synové Het Abrahamovi, řekli jemu:'),
(1546769,54,1,23,6,'Slyš nás, pane milý! Kníže Boží jsi u prostřed nás, v nejpřednějších hrobích našich pochovej mrtvého svého; žádný z nás hrobu svého nebude zbraňovati tobě, abys neměl pochovati v něm mrtvého svého.'),
(1546770,54,1,23,7,'Abraham pak vstav, poklonil se lidu země té, totiž synům Het.'),
(1546771,54,1,23,8,'A mluvil s nimi, řka: Jestliže se vám líbí, abych pochoval mrtvého svého od tváři své, slyšte mne, a přimluvte se za mne k Efronovi synu Sohar,'),
(1546772,54,1,23,9,'Ať mi dá jeskyni Machpelah, kterouž má na konci pole svého; za slušné peníze ať mi ji dá u prostřed vás, k dědičnému pohřbu.'),
(1546773,54,1,23,10,'(Ten pak Efron seděl u prostřed synů Het.) Tedy odpověděl Efron Hetejský Abrahamovi při přítomnosti synů Het, přede všemi, kteříž vcházejí do brány města jeho, řka:'),
(1546774,54,1,23,11,'Nikoli, pane můj, ale slyš mne: Pole to dávám tobě, dávámť také i jeskyni, kteráž na něm jest; před očima synů lidu svého dávám ji tobě; pochovejž mrtvého svého.'),
(1546775,54,1,23,12,'Tedy poklonil se Abraham před lidem země té,'),
(1546776,54,1,23,13,'A mluvil k Efronovi v přítomnosti lidu země, řka: A však jestliže ty jsi ten, prosím, vyslyš mne! Dámť stříbro za pole, vezmi je ode mne, a pochovám mrtvého svého tam.'),
(1546777,54,1,23,14,'A odpovídaje Efron Abrahamovi, řekl jemu:'),
(1546778,54,1,23,15,'Můj pane, poslechni mne: Země ta za čtyři sta lotů stříbrných jest; ale mezi mnou a tebou co jest o to? Mrtvého svého pochovej.'),
(1546779,54,1,23,16,'I uposlechl Abraham Efrona, a odvážil mu stříbra, jakž oznámil při přítomnosti synů Het, čtyři sta lotů stříbrných, běžných mezi kupci.'),
(1546780,54,1,23,17,'A odvedeno jest pole Efronovo, kteréž bylo v Machpelah, proti Mamre, pole a jeskyně na něm, a všecko stromoví, což ho na tom poli i na všech mezech jeho vůkol,'),
(1546781,54,1,23,18,'Abrahamovi v držení, před očima synů Het, a všech, kteříž vcházejí do brány města toho.'),
(1546782,54,1,23,19,'A potom pochoval Abraham Sáru,manželku svou, v jeskyni pole Machpelah, proti Mamre, (to slove Hebron), v zemi Kananejské.'),
(1546783,54,1,23,20,'Protož odevzdáno jest pole to i jeskyně, kteráž byla na něm, Abrahamovi k dědičnému pohřbu od synů Het.'),
(1546784,54,1,24,1,'Abraham pak již byl starý a sešlého věku; a Hospodin požehnal mu ve všech věcech.'),
(1546785,54,1,24,2,'Tedy řekl Abraham služebníku svému staršímu v domě svém, kterýž spravoval všecky věci jeho: Vlož nyní ruku svou pod bedro mé,'),
(1546786,54,1,24,3,'Abych tě zavázal přísahou skrze Hospodina, Boha nebe a Boha země, abys nebral manželky synu mému ze dcer Kananejských, mezi nimiž já bydlím.'),
(1546787,54,1,24,4,'Ale půjdeš do země mé a příbuznosti mé; a odtud vezmeš manželku synu mému Izákovi.'),
(1546788,54,1,24,5,'I řekl jemu služebník ten: Kdyby pak nechtěla žena ta se mnou jíti do země této, mám-li zase uvésti syna tvého do země, z níž jsi vyšel?'),
(1546789,54,1,24,6,'Kterýžto odpověděl: Hleď, abys zase neuvodil syna mého tam.'),
(1546790,54,1,24,7,'Hospodin Bůh nebe, kterýž vzal mne z domu otce mého a z vlasti mé, a mluvil mi, a kterýž mi přisáhl, řka: Semeni tvému dám zemi tuto, onť pošle anděla svého před tebou, a vezmeš manželku synu mému odtud.'),
(1546791,54,1,24,8,'Jestliže by pak žena ta nechtěla jíti s tebou, svoboden budeš od této přísahy mé; toliko syna mého neuvoď tam zase.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546792,54,1,24,9,'Tedy vložil služebník ten ruku svou pod bedro Abrahama, pána svého, a přisáhl jemu na tu řeč.'),
(1546793,54,1,24,10,'A vzal služebník ten deset velbloudů z velbloudů pána svého, aby se bral; (nebo měl všecken statek pána svého v rukou svých.) I vstav, bral se k Aram Naharaim do města Náchor.'),
(1546794,54,1,24,11,'A zastavil se s velbloudy před městem, u studnice vody k večerou, času toho, když vycházejí vážiti vody.'),
(1546795,54,1,24,12,'A řekl: Hospodine, Bože pána mého Abrahama, dejž, prosím, ať se potká se mnou dnes to, čehož hledám; a učiň milosrdenství se pánem mým Abrahamem.'),
(1546796,54,1,24,13,'Aj, já stojím u studnice vody, a dcery mužů města tohoto vycházejí, aby vážily vodu.'),
(1546797,54,1,24,14,'Děvečka tedy, kteréž bych řekl: Nachyl medle věderce svého, ať se napiji, a ona by řekla: Pí, také i velbloudy tvé napojím, ta aby byla, kterouž jsi způsobil služebníku svému Izákovi; a po tomť poznám, že jsi milosrdenství učinil se pánem mým.'),
(1546798,54,1,24,15,'I stalo se prvé, než on přestal mluviti, aj, Rebeka, kteráž se narodila Bathuelovi, synu Melchy, manželky Náchora bratra Abrahamova, vycházela, a věderce její bylo na rameni jejím.'),
(1546799,54,1,24,16,'A byla děvečka na pohledění velmi krásná, panna, a muž nepoznal jí; kterážto sešla k studnici té, a naplnivši věderce své, šla vzhůru.'),
(1546800,54,1,24,17,'Tedy běžel služebník ten proti ní, a řekl: Dej mi píti, prosím, maličko vody z věderce svého.'),
(1546801,54,1,24,18,'I řekla: Napí se, pane můj. A rychle složila věderce své na ruku svou a dala mu píti.'),
(1546802,54,1,24,19,'A davši mu píti, řekla: Také velbloudům tvým navážím, dokudž se nenapijí.'),
(1546803,54,1,24,20,'Tedy rychle vylila z věderce svého do koryta, a běžela ještě k studnici, aby vážila vodu; a vážila všechněm velbloudům jeho.'),
(1546804,54,1,24,21,'Muž pak ten s užasnutím divil se jí mlče, rozjímaje, aby zvěděl, zdařil-li Hospodin cestu jeho, čili nic.'),
(1546805,54,1,24,22,'I stalo se, když přestali píti velbloudové, vyňav muž náušnici zlatou, ztíží půl lotu, a dvě náramnice, dal na ruce její, kteréž vážily deset lotů zlata.'),
(1546806,54,1,24,23,'A řekl: Čí jsi dcera? Pověz mi, prosím, jest-li v domě otce tvého nám místo, kdež bychom přes noc zůstali?'),
(1546807,54,1,24,24,'Jemužto odpověděla: Dcera jsem Bathuele, syna Melchy, kteréhož porodila Náchorovi.'),
(1546808,54,1,24,25,'Řekla ještě k němu: Slámy také a potravy hojně u nás jest, ano i místo, kdež byste přes noc zůstali.'),
(1546809,54,1,24,26,'Tedy skloniv hlavu, poklonu učinil Hospodinu.'),
(1546810,54,1,24,27,'A řekl: Požehnaný Hospodin, Bůh pána mého Abrahama, kterýž neodjal milosrdenství svého a pravdy své od pána mého, mne také na cestě vedl Hospodin k domu bratří pána mého.'),
(1546811,54,1,24,28,'I běžela děvečka, a oznámila v domě matky své tak, jakž se stalo.'),
(1546812,54,1,24,29,'A měla Rebeka bratra, jménem Lábana; ten běžel k muži tomu ven k studnici.'),
(1546813,54,1,24,30,'Nebo uzřev náušnici a náramnice na rukou sestry své, a slyšev slova Rebeky sestry své, ana praví: Tak mluvil ke mně člověk ten, přišel k muži, a on stál při velbloudích u studnice.'),
(1546814,54,1,24,31,'Jemuž řekl: Vejdi, požehnaný Hospodinův. Proč bys stál vně, kdyžť jsem připravil dům a místo velbloudům?'),
(1546815,54,1,24,32,'Tedy všel muž ten do domu, a odsedlal velbloudy, a dal Lában slámy a potravy velbloudům, i vody k umytí noh jeho a noh mužů těch, kteří s ním byli.'),
(1546816,54,1,24,33,'A položil předeň chléb, aby jedl. Ale on řekl: Nebudu jísti, dokudž nevypravím řečí svých. I řekl Lában: Mluv.'),
(1546817,54,1,24,34,'Tedy řekl: Služebník Abrahamův jsem já.'),
(1546818,54,1,24,35,'A Hospodin požehnal pánu mému velice, tak že veliký učiněn jest; nebo dal mu ovce a voly, stříbro a zlato, služebníky a děvky, velbloudy a osly.'),
(1546819,54,1,24,36,'A porodila Sára, manželka pána mého, pánu mému v starosti své syna, jemuž dal, cožkoli má.'),
(1546820,54,1,24,37,'I zavázal mne přísahou pán můj, řka: Nevezmeš manželky synu mému ze dcer Kananejských, v jejichž zemi já bydlím.'),
(1546821,54,1,24,38,'Ale k domu otce mého půjdeš, a k rodině mé, a odtud vezmeš manželku synu mému.'),
(1546822,54,1,24,39,'A když jsem řekl pánu svému: Snad nepůjde žena ta se mnou?'),
(1546823,54,1,24,40,'Odpověděl mi: Hospodin, před jehož oblíčejem ustavičně jsem chodil, pošle anděla svého s tebou, a šťastnou způsobí cestu tvou, a vezmeš manželku synu mému z rodiny mé, a z domu otce mého.'),
(1546824,54,1,24,41,'A budeš svoboden od přísahy mé, když bys přišel k rodině mé; a jestliže by nedali tobě, budeš prost od přísahy mé.'),
(1546825,54,1,24,42,'Protož dnes přišed k studnici, řekl jsem: Hospodine, Bože pána mého Abrahama, jestliže ty nyní šťastně spravuješ cestu mou, po níž já jdu,'),
(1546826,54,1,24,43,'Aj, já stojím u studnice vody; protož,nechžť panna, kteráž vyjde vážiti vody, když bych jí řekl: Dej mi píti nyní maličko vody z věderce svého,'),
(1546827,54,1,24,44,'A ona by mi odpověděla: I ty pí, i velbloudům tvým také navážím, ta ať jest manželka, kterouž způsobil Hospodin synu pána mého.'),
(1546828,54,1,24,45,'Prvé pak než jsem já přestal mluviti v srdci svém, aj, Rebeka vycházela mající věderce své na rameni svém, a sšedši k studnici, vážila. I řekl jsem jí: Prosím, dej mi píti.'),
(1546829,54,1,24,46,'Ona pak rychle složila věderce své s sebe, a řekla: Pí, také i velbloudy tvé napojím. Tedy pil jsem, a napojila také velbloudy.'),
(1546830,54,1,24,47,'I ptal jsem se jí, a řekl jsem: Čí jsi dcera? Ona odpověděla: Dcera Bathuele, syna Náchorova, jehož mu porodila Melcha. Tedy dal jsem náušnici na tvář její, a náramnice na ruce její.'),
(1546831,54,1,24,48,'A skloniv hlavu, poklonu jsem učinil Hospodinu, a dobrořečil jsem Hospodina, Boha pána mého Abrahama, kterýž vedl mne po cestě přímé, abych dceru bratra pána svého vzal synu jeho.'),
(1546832,54,1,24,49,'Protož nyní, činíte-li milosrdenství, a pravdu se pánem mým, oznamte mi; pakli nic, také mi oznamte, a obrátím se na pravo neb na levo.'),
(1546833,54,1,24,50,'Tedy odpověděli Lában a Bathuel, řkouce: Od Hospodina vyšla jest věc tato; nemůžemeť odepříti v ničemž.'),
(1546834,54,1,24,51,'Aj, Rebeka před tebou, vezmiž ji a jeď; a nechť jest manželkou synu pána tvého, jakož mluvil Hospodin.'),
(1546835,54,1,24,52,'I stalo se, že jakž uslyšel služebník Abrahamův slova jejich, poklonil se Hospodinu až k zemi.'),
(1546836,54,1,24,53,'A vyňav služebník ten nádoby stříbrné a nádoby zlaté a oděv, dal Rebece; drahé také dary dal bratru jejímu a matce její.'),
(1546837,54,1,24,54,'Tedy jedli a pili, on i muži, kteříž byli s ním, a zůstali tu přes noc. Ráno pak když vstali, řekl: Propusťte mne ku pánu mému.'),
(1546838,54,1,24,55,'I odpověděl bratr její a matka: Nechať pozůstane děvečka s námi za některý den, aspoň za deset; potom půjdeš.'),
(1546839,54,1,24,56,'On pak řekl jim: Nezdržujte mne, poněvadž Hospodin šťastnou způsobil cestu mou; propusťtež mne, ať jdu ku pánu svému.'),
(1546840,54,1,24,57,'I řekli: Zavolejme děvečky a zeptejme se, co dí k tomu.'),
(1546841,54,1,24,58,'Tedy zavolali Rebeky, a řekli jí: Chceš-li jíti s mužem tímto? I řekla: Půjdu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546842,54,1,24,59,'A propouštějíce Rebeku sestru svou a chovačku její, služebníka také Abrahamova s muži jeho,'),
(1546843,54,1,24,60,'Požehnali Rebeky a mluvili jí: Sestro naše, ty buď v tisíce tisíců, a símě tvé dědičně obdrž brány nepřátel svých.'),
(1546844,54,1,24,61,'Tedy vstala Rebeka a děvečky její, a vsedše na velbloudy, jely za mužem tím. A tak vzal služebník ten Rebeku, a odjel.'),
(1546845,54,1,24,62,'Izák pak šel, navracuje se od studnice Živého vidoucího mne; nebo bydlil v zemi polední.'),
(1546846,54,1,24,63,'A vyšel Izák k přemyšlování na pole, když se chýlilo k večerou; a pozdvih očí svých, uzřel, an velbloudové jdou.'),
(1546847,54,1,24,64,'Pozdvihla také Rebeka očí svých, a uzřevši Izáka, ssedla s velblouda.'),
(1546848,54,1,24,65,'(Nebo řekla byla služebníku: Kdo jest ten muž, kterýž jde po poli proti nám? Odpověděl služebník: To jest pán můj.) I vzala rouchu, a přistřela se.'),
(1546849,54,1,24,66,'Tedy vypravoval služebník Izákovi vše, což působil.'),
(1546850,54,1,24,67,'I uvedl ji Izák do stanu Sáry matky své, a vzal Rebeku, a měl ji za manželku, a miloval ji. I potěšil se Izák po smrti matky své.'),
(1546851,54,1,25,1,'Abraham pak opět pojal ženu jménem Ceturu.'),
(1546852,54,1,25,2,'Kterážto porodila jemu Zamrana, a Jeksana, a Madana, a Madiana, Jezbocha a Suecha.'),
(1546853,54,1,25,3,'Jeksan potom zplodil Sábu a Dedana. Synové pak Dedanovi byli: Assurim, a Latuzim, a Laomim.'),
(1546854,54,1,25,4,'Ale synové Madianovi: Efa, a Efer, a Enoch, a Abida, a Helda; všickni ti synové byli Cetury.'),
(1546855,54,1,25,5,'I dal Abraham Izákovi všecko, což měl.'),
(1546856,54,1,25,6,'Synům pak ženin svých dal Abraham dary, a odeslal je od Izáka syna svého, ještě živ jsa, k východu do země východní.'),
(1546857,54,1,25,7,'Tito pak jsou dnové let života Abrahamova, v nichž byl živ: Sto sedmdesáte a pět let.'),
(1546858,54,1,25,8,'I skonal a umřel Abraham v starosti dobré, stár jsa a plný dnů; a připojen jest k lidu svému.'),
(1546859,54,1,25,9,'Tedy pochovali ho Izák a Izmael synové jeho v jeskyni Machpelah, na poli Efrona, syna Sohar Hetejského, naproti Mamre,'),
(1546860,54,1,25,10,'Na tom poli, kteréž byl koupil Abraham od synů Het; tu pochován jest Abraham i Sára manželka jeho.'),
(1546861,54,1,25,11,'Po smrti pak Abrahamově požehnal Bůh Izákovi synu jeho, a bydlil Izák u studnice Živého vidoucího mne.'),
(1546862,54,1,25,12,'Tito jsou pak rodové Izmaele syna Abrahamova, jehož porodila Agar Egyptská, děvka Sářina, Abrahamovi.'),
(1546863,54,1,25,13,'A tato jsou jména synů Izmaelových, jimiž se jmenují po rodech svých: Prvorozený Izmaelův Nabajot, po něm Cedar, a Adbeel a Mabsan,'),
(1546864,54,1,25,14,'A Masma, a Dumah a Massa,'),
(1546865,54,1,25,15,'Hadar a Tema, Jetur, Nafis a Cedma.'),
(1546866,54,1,25,16,'Ti jsou synové Izmaelovi, a ta jména jejich, po vsech jejich, a po městech jejich, dvanáctero knížat po čeledech jejich.'),
(1546867,54,1,25,17,'(Bylo pak života Izmaelova sto třidceti a sedm let, i skonal; a umřev, připojen jest k lidu svému.)'),
(1546868,54,1,25,18,'A bydlili od Hevilah až do Sur, jenž jest proti Egyptu, když jdeš do Assyrie; před tváří všech bratří svých položil se.'),
(1546869,54,1,25,19,'Tito jsou také rodové Izáka syna Abrahamova: Abraham zplodil Izáka.'),
(1546870,54,1,25,20,'Byl pak Izák ve čtyřidcíti letech, když sobě vzal za manželku Rebeku, dceru Bathuele Syrského, z Pádan Syrské, sestru Lábana Syrského.'),
(1546871,54,1,25,21,'I modlil se Izák pokorně Hospodinu za manželku svou; nebo byla neplodná. A uslyšel jej Hospodin; a tak počala Rebeka manželka jeho.'),
(1546872,54,1,25,22,'A když se děti potiskali v životě jejím, řekla: Má-liť tak býti, proč jsem já počala? Šla tedy, aby se otázala Hospodina.'),
(1546873,54,1,25,23,'I řekl jí Hospodin: Dva národové jsou v životě tvém, a dvůj lid z života tvého se rozdělí; lid pak jeden nad druhý bude silnější, a větší sloužiti bude menšímu.'),
(1546874,54,1,25,24,'A když se naplnili dnové její, aby porodila, a aj, blíženci byli v životě jejím.'),
(1546875,54,1,25,25,'I vyšel první ryšavý všecken, a jako oděv chlupatý; i nazvali jméno jeho Ezau.'),
(1546876,54,1,25,26,'Potom pak vyšel bratr jeho, a rukou svou držel Ezau za patu; pročež nazváno jest jméno jeho Jákob. A byl Izák v šedesáti letech, když ona je porodila.'),
(1546877,54,1,25,27,'A když dorostli ti děti, byl Ezau lovec umělý, chodě po polích; Jákob pak byl muž prostý a v staních bydlil.'),
(1546878,54,1,25,28,'I byl Izák laskav na Ezau, proto že z lovu jeho míval pokrm; ale Rebeka laskava byla na Jákoba.'),
(1546879,54,1,25,29,'Uvařil pak Jákob krmičku. Tedy Ezau přišel z pole zemdlený,'),
(1546880,54,1,25,30,'A řekl Jákobovi: Dej mi, prosím, jísti krmě té červené, nebo jsem umdlel. (Protož nazváno jest jméno jeho Edom.)'),
(1546881,54,1,25,31,'Odpověděl Jákob: Prodej mi dnes hned prvorozenství své.'),
(1546882,54,1,25,32,'I řekl Ezau: Aj, já k smrti se blížím, k čemuž mi tedy to prvorozenství?'),
(1546883,54,1,25,33,'Dí Jákob: Přisáhni mi dnes hned. I přisáhl mu, a prodal prvorozenství své Jákobovi.'),
(1546884,54,1,25,34,'Tedy Jákob dal Ezauchovi chleba a té krmě z šocovice. Kterýžto jedl a pil, a vstav, odšel; a tak pohrdl Ezau prvorozenstvím.'),
(1546885,54,1,26,1,'Byl pak opět hlad na zemi, mimo hlad první, kterýž byl za dnů Abrahamových. Tedy odebral se Izák k Abimelechovi králi Filistinskému do Gerar.'),
(1546886,54,1,26,2,'Nebo ukázal se jemu Hospodin a řekl: Nesstupuj do Egypta; ale bydli v zemi, kterouž oznámím tobě.'),
(1546887,54,1,26,3,'Budiž tedy pohostinu v zemi této, a budu s tebou, a požehnám tobě; nebo tobě a semeni tvému dám všecky země tyto, a utvrdím přísahu, kterouž jsem přisáhl Abrahamovi, otci tvému.'),
(1546888,54,1,26,4,'Rozmnožím také símě tvé jako hvězdy nebeské, a dám semeni tvému všecky země tyto, a požehnáni budou v semeni tvém všickni národové země;'),
(1546889,54,1,26,5,'Protože uposlechl Abraham hlasu mého, a ostříhal nařízení mých, přikázaní mých, ustanovení mých a zákonů mých.'),
(1546890,54,1,26,6,'Bydlil tedy Izák v Gerar.'),
(1546891,54,1,26,7,'Ptali se pak muži místa toho o manželce jeho. Kterýžto odpověděl: Sestra má jest; nebo nesměl říci: Manželka má jest, mysle sobě: Aby mne nezabili muži místa toho pro Rebeku. Nebo byla krásná na pohledění.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546892,54,1,26,8,'I přihodilo se, když již čas nějaký tam bydlil, že vyhlédal Abimelech král Filistinský z okna a uzřel Izáka, an pohrává s Rebekou manželkou svou.'),
(1546893,54,1,26,9,'Protož povolav Abimelech Izáka, řekl: Aj, v pravdě manželka tvá to jest. Jakž to, že jsi pravil: Sestra má jest? I odpověděl jemu Izák: Nebo jsem řekl sám u sebe: Abych snad neumřel pro ni.'),
(1546894,54,1,26,10,'I řekl Abimelech: Což jsi to učinil nám? O málo, že by byl spal někdo z lidu s manželkou tvou, a ty byl bys uvedl na nás vinu.'),
(1546895,54,1,26,11,'I přikázal Abimelech všemu lidu, řka: Kdo by se dotkl člověka toho, aneb manželky jeho, smrtí umře.'),
(1546896,54,1,26,12,'Sel pak Izák v zemi té, a shledal v tom roce sto měr; nebo požehnal mu Hospodin.'),
(1546897,54,1,26,13,'I rostl muž ten, a prospíval vždy více v zrostu, až i zrostl velmi.'),
(1546898,54,1,26,14,'Nebo měl stáda ovcí i stáda volů, a čeledi mnoho; pročež záviděli mu Filistinští.'),
(1546899,54,1,26,15,'A všecky studnice, kteréž vykopali služebníci otce jeho za dnů Abrahama otce jeho, zařítili Filistinští, zasypavše je prstí.'),
(1546900,54,1,26,16,'I řekl Abimelech Izákovi: Odejdi od nás; nebo mnohem mocnější jsi než my.'),
(1546901,54,1,26,17,'Tedy odšel odtud Izák, a rozbil stany v údolí Gerar, a bydlil tu.'),
(1546902,54,1,26,18,'A kopal zase Izák studnice vod, kteréž byli vykopali za dnů Abrahama otce jeho, a kteréž zařítili Filistinští po smrti Abrahamově; a nazval je těmi jmény, kterýmiž je jmenoval otec jeho.'),
(1546903,54,1,26,19,'I kopali služebníci Izákovi v tom údolí, a nalezli tam studnici vody živé.'),
(1546904,54,1,26,20,'Vadili se pak pastýři Gerarští s pastýři Izákovými, pravíce: Naše jest voda. Pročež nazval jméno studnice té Esek, že se vadili s ním.'),
(1546905,54,1,26,21,'Vykopali také jinou studnici, a nesnáz byla i o tu; pročež dal jí jméno Sitnah.'),
(1546906,54,1,26,22,'I hnul se odtud, a kopal jinou studnici, o kterouž se nevadili; protož nazval jméno její Rehobot. Nebo řekl: Nyní uprostrannil nám Hospodin, a vzrostli jsme na zemi.'),
(1546907,54,1,26,23,'Vstoupil pak odtud do Bersabé.'),
(1546908,54,1,26,24,'A ukázal se mu Hospodin v tu noc, a řekl: Já jsem Bůh Abrahama otce tvého; neboj se, nebo s tebou já jsem, a požehnám tobě, a rozmnožím símě tvé pro Abrahama služebníka svého.'),
(1546909,54,1,26,25,'I vzdělal tu oltář, a vzýval jméno Hospodinovo, a rozbil tu stan svůj; a služebníci Izákovi vykopali tam studnici.'),
(1546910,54,1,26,26,'Abimelech pak přijel k němu z Gerar, a Ochozat, přítel jeho, a Fikol, kníže vojska jeho.'),
(1546911,54,1,26,27,'I řekl jim Izák: Z jaké příčiny přišli jste ke mně? Poněvadž vy nenáviděli jste mne, a vybyli jste mne od sebe.'),
(1546912,54,1,26,28,'Kteřížto odpověděli: Patrně jsme to shledali, že jest Hospodin s tebou, i řekli jsme: Učiňme nyní přísahu mezi sebou, mezi námi a mezi tebou; a učiníme smlouvu s tebou:'),
(1546913,54,1,26,29,'Že neučiníš nám nic zlého, jako i my nedotkli jsme se tebe, a jakž jsme my toliko dobře činili tobě, a propustili jsme tě v pokoji; ty nyní tedy povol tomu, požehnaný Hospodinův.'),
(1546914,54,1,26,30,'Tedy učinil jim hody, i jedli a pili.'),
(1546915,54,1,26,31,'A vstavše velmi ráno, přisáhli jeden druhému. I propustil je Izák, a oni odešli od něho v pokoji.'),
(1546916,54,1,26,32,'Toho dne přišli služebníci Izákovi, a oznámili mu o studnici, kterouž kopali, řkouce: Nalezli jsme vodu.'),
(1546917,54,1,26,33,'I nazval ji Seba. Protož jméno města toho jest Bersabé až do dnešního dne.'),
(1546918,54,1,26,34,'Ezau pak jsa v letech čtyřidcíti, pojal ženu Judit, dceru Béry Hetejského, a Bazematu, dceru Elona Hetejského.'),
(1546919,54,1,26,35,'A kormoutily Izáka a Rebeku.'),
(1546920,54,1,27,1,'Když se pak sstaral Izák, a pošly byly oči jeho, tak že neviděl, povolal Ezau syna svého staršího, a řekl jemu: Synu můj. Kterýžto odpověděl: Aj, teď jsem.'),
(1546921,54,1,27,2,'I dí: Aj, já jsem se již sstaral, a nevím dne smrti své.'),
(1546922,54,1,27,3,'Protož nyní vezmi medle nástroje své, toul svůj a lučiště své, a vyjda do pole, ulov mi zvěřinu.'),
(1546923,54,1,27,4,'A přistroj mi krmi chutnou, jakž já rád jídám, a přines mi, a budu jísti, aťby požehnala duše má, prvé než umru.'),
(1546924,54,1,27,5,'(Slyšela pak Rebeka, když mluvil Izák s Ezau synem svým.) I odšel Ezau na pole, aby ulovil zvěřinu a přinesl.'),
(1546925,54,1,27,6,'Tedy řekla Rebeka Jákobovi synu svému takto: Aj, slyšela jsem, když otec tvůj mluvil k Ezau bratru tvému, a pravil:'),
(1546926,54,1,27,7,'Přines mi něco z lovu, a přistroj mi krmě chutné, abych jedl, a požehnámť před Hospodinem, prvé než umru.'),
(1546927,54,1,27,8,'Nyní tedy, synu můj, poslechni hlasu mého v tom, což já přikazuji tobě.'),
(1546928,54,1,27,9,'Jdi medle k stádu, a odtud mi vezmi dva kozelce výborné, abych přistrojila z nich krmě chutné otci tvému, jakž on rád jídá.'),
(1546929,54,1,27,10,'A přineseš otci svému, a on jísti bude, na to, aby požehnal tobě, prvé než umře.'),
(1546930,54,1,27,11,'I řekl Jákob Rebece matce své: Víš, že Ezau bratr můj jest člověk chlupatý, a já jsem člověk hladký.'),
(1546931,54,1,27,12,'Jestliže omaká mne otec můj, tedy zůstanu u něho za podvodného; a tak uvedu na sebe zlořečenství, a ne požehnání.'),
(1546932,54,1,27,13,'Jemužto odpověděla matka: Nechť jest na mne zlořečenství tvé, synu můj; jen ty poslechni hlasu mého, a jdi, přines mi.'),
(1546933,54,1,27,14,'Tedy odšed, vzal, a přinesl matce své. I připravila matka jeho krmě chutné, jakž otec jeho rád jídal.'),
(1546934,54,1,27,15,'A vzala Rebeka nejlepší šaty Ezausyna svého staršího, kteréž měla u sebe v domě, a oblékla Jákoba, syna svého mladšího.'),
(1546935,54,1,27,16,'A kožkami kozelčími obvinula ruce jeho, a díl hladký hrdla jeho.'),
(1546936,54,1,27,17,'I dala chléb a krmě chutné, kteréž připravila, v ruce Jákoba syna svého.'),
(1546937,54,1,27,18,'A on přišed k otci svému, řekl: Otče můj! Kterýžto odpověděl: Aj, teď jsem. Kdož jsi ty, synu můj?'),
(1546938,54,1,27,19,'I dí Jákob otci svému: Já jsem Ezau,prvorozený tvůj. Učinil jsem, jakž jsi mi poručil. Vstaň, prosím, sedni a jez z lovu mého, aby mi požehnala duše tvá.'),
(1546939,54,1,27,20,'Tedy řekl Izák synu svému: Což to? Brzys to nalezl, synu můj. A on dí: Nebo Hospodin Bůh tvůj způsobil to, aby mi se pojednou nahodilo.'),
(1546940,54,1,27,21,'I řekl Izák Jákobovi: Přistupiž, ať omakám tě, synu můj, ty-li jsi syn můj Ezau, či nejsi.'),
(1546941,54,1,27,22,'Tedy přistoupil Jákob k Izákovi otci svému; a on omakal ho, i řekl: Hlas jest hlas Jákobův, ale ruce tyto ruce Ezau.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546942,54,1,27,23,'A nepoznal ho; nebo byly ruce jeho, jako ruce Ezau bratra jeho, chlupaté. I požehnal mu.'),
(1546943,54,1,27,24,'A řekl: Ty-liž jsi pak syn můj Ezau? Odpověděl: Já.'),
(1546944,54,1,27,25,'I řekl: Podejž mi, ať jím z lovu syna svého, aby tobě požehnala duše má. Tedy podal mu, a on jedl. Přinesl mu také vína, a on pil.'),
(1546945,54,1,27,26,'I řekl jemu Izák otec jeho: Přistupiž nyní, a polib mne, synu můj.'),
(1546946,54,1,27,27,'I přistoupil a políbil ho. A jakž ucítil Izák vůni roucha jeho, požehnal mu, řka: Pohleď, vůně syna mého jest jako vůně pole, jemuž požehnal Hospodin.'),
(1546947,54,1,27,28,'Dejž tobě Bůh z rosy nebeské, a z tučnosti zemské, i hojnost obilé a vína.'),
(1546948,54,1,27,29,'Nechažť slouží tobě lidé, a sklánějí se před tebou národové. Budiž pánem bratří svých, a ať se sklánějí před tebou synové matky tvé. Kdož by zlořečili tobě, nechť jsou zlořečení, a kdo by dobrořečili tobě, požehnaní.'),
(1546949,54,1,27,30,'A když přestal Izák požehnání dávati Jákobovi, a sotva že vyšel Jákob od Izáka otce svého, Ezau bratr jeho přišel z lovu svého.'),
(1546950,54,1,27,31,'A připraviv i on krmě chutné, přinesl otci svému a řekl mu: Nechžť vstane otec můj, a jí z lovu syna svého, aby mi požehnala duše tvá.'),
(1546951,54,1,27,32,'I řekl jemu Izák otec jeho: Kdo jsi ty? Dí on: Já jsem syn tvůj, prvorozený tvůj Ezau.'),
(1546952,54,1,27,33,'Tedy zhrozil se Izák hrůzou velikou náramně, a řekl: Kdo pak a kde jest ten, ješto uloviv zvěřinu, přinesl mi? A já jsem jedl ze všeho, prvé než jsi ty přišel, a požehnal jsem mu, a budeť požehnaným.'),
(1546953,54,1,27,34,'Uslyšev Ezau slova otce svého, zkřikl hlasem velikým, a hořkostí naplněn jest náramně, a řekl otci svému: Požehnejž mně, i mně také, můj otče!'),
(1546954,54,1,27,35,'Kterýžto řekl: Přišel bratr tvůj podvodně a uchvátil požehnání tvé.'),
(1546955,54,1,27,36,'Tedy řekl: Právětě nazváno jméno jeho Jákob; nebo již po dvakráte mne podvedl, prvorozenství mé odjal, a teď nyní uchvátil požehnání mé. Řekl ještě: Zdali jsi nezachoval i mně požehnání?'),
(1546956,54,1,27,37,'Odpověděl Izák a řekl k Ezau: Aj, ustavil jsem ho pánem nad tebou, a všecky bratří jeho dal jsem mu za služebníky; obilím také a vínem opatřil jsem ho. Což tedy již tobě učiniti mohu, synu můj?'),
(1546957,54,1,27,38,'I řekl Ezau otci svému: Zdaliž to jedno toliko máš požehnání, otče můj? Požehnejž mně, i mně také, můj otče! I povýšil Ezau hlasu svého a plakal.'),
(1546958,54,1,27,39,'Tedy odpověděl Izák otec jeho, a řekl k němu: Aj, v tučnostech země bude bydlení tvé a v rose nebeské s hůry;'),
(1546959,54,1,27,40,'A v meči svém živ budeš, a bratru svému sloužiti budeš; ale přijde čas, že budeš panovati a svržeš jho jeho s šíje své.'),
(1546960,54,1,27,41,'Protož v nenávisti měl Ezau Jákoba pro požehnání, jímž požehnal mu otec jeho, a řekl v srdci svém: Přiblížiť se dnové smutku otce mého, a zabiji Jákoba, bratra svého.'),
(1546961,54,1,27,42,'I oznámena jsou Rebece slova Ezau, staršího syna jejího. Pročež ona poslavši, povolala Jákoba syna svého mladšího, a řekla jemu: Hle, Ezau bratr tvůj těší se tím, že tě zabije.'),
(1546962,54,1,27,43,'Protož nyní, synu můj, poslechni hlasu mého, a vstana, utec k Lábanovi, bratru mému do Cháran.'),
(1546963,54,1,27,44,'A pobuď s ním za některý čas, až by se odvrátila prchlivost bratra tvého,'),
(1546964,54,1,27,45,'A přestalo rozhněvání bratra tvého na tebe, a zapomenul by na to, což jsi mu učinil. Potom já pošli a vezmu tě odtud. Proč mám zbavena býti obou synů jednoho dne?'),
(1546965,54,1,27,46,'I řekla Rebeka Izákovi: Stýště mi se živu býti pro dcery Het. Vezme-li Jákob ženu ze dcer Het, jako tyto jsou ze dcer země této, k čemu mi život?'),
(1546966,54,1,28,1,'Povolal pak Izák Jákoba, a požehnal jemu, a přikázal mu, řka: Nepojímej ženy ze dcer Kananejských.'),
(1546967,54,1,28,2,'Ale vstana, jdi do Pádan Syrské do domu Bathuele, otce matky své, a pojmi sobě odtud manželku ze dcer Lábana ujce svého.'),
(1546968,54,1,28,3,'A Bůh silný všemohoucí požehnejž tobě, a dejžť zrůst, a rozmnožiž tě, abys byl v zástup mnohého lidu.'),
(1546969,54,1,28,4,'A dejž tobě požehnání Abrahamovo, tobě i semeni tvému s tebou, abys dědičně obdržel zemi, v níž pohostinu jsi, kterouž dal Bůh Abrahamovi.'),
(1546970,54,1,28,5,'I odeslal Izák Jákoba, kterýžto šel do Pádan Syrské k Lábanovi synu Bathuele Syrského, bratru Rebeky matky Jákobovy a Ezau.'),
(1546971,54,1,28,6,'Vida pak Ezau, že požehnání dal Izák Jákobovi, a že ho odeslal do Pádan Syrské, aby sobě odtud vzal manželku, a že, když mu požehnání dával, přikázal mu, řka: Nepojmeš ženy ze dcer Kananejských;'),
(1546972,54,1,28,7,'A že by uposlechl Jákob otce svého a matky své a odšel do Pádan Syrské;'),
(1546973,54,1,28,8,'Vida také Ezau, že dcery Kananejské těžké byly v očích Izákovi otci jeho:'),
(1546974,54,1,28,9,'Tedy odšel Ezau k Izmaelovi, a mimo prvnější ženy své, pojal sobě za ženu Mahalat, dceru Izmaele, syna Abrahamova, sestru Nabajotovu.'),
(1546975,54,1,28,10,'Vyšed pak Jákob z Bersabé, šel do Cháran.'),
(1546976,54,1,28,11,'I trefil na jedno místo, na kterémžto zůstal přes noc, (nebo slunce již bylo zapadlo,) a nabrav kamení na místě tom, položil pod hlavu svou, a spal na témž místě.'),
(1546977,54,1,28,12,'I viděl ve snách, a aj, žebřík stál na zemi, jehožto vrch dosahal nebe; a aj, andělé Boží vstupovali a sstupovali po něm.'),
(1546978,54,1,28,13,'A aj, Hospodin stál nad ním, a řekl: Já jsem Hospodin, Bůh Abrahama otce tvého, a Bůh Izákův; zemi tu, na kteréž ty spíš, tobě dám a semeni tvému.'),
(1546979,54,1,28,14,'A bude símě tvé jako prach země; nebo rozmůžeš se k západu, i k východu, na půlnoci, i ku poledni; nad to požehnány budou v tobě všecky čeledi země, a v semeni tvém.'),
(1546980,54,1,28,15,'A aj, já jsem s tebou, a ostříhati tě budu, kamžkoli půjdeš, a přivedu tě zase do země této; nebo neopustím tebe, až i učiním, což jsem mluvil tobě.'),
(1546981,54,1,28,16,'Procítiv pak Jákob ze sna svého, řekl: V pravdě Hospodin jest na místě tomto, a já jsem nevěděl.'),
(1546982,54,1,28,17,'(Nebo zhroziv se, řekl: Jak hrozné jest místo toto! Není jiného,jediné dům Boží, a tu jest brána nebeská.)'),
(1546983,54,1,28,18,'Vstav pak Jákob ráno, vzal kámen, kterýž byl podložil pod hlavu svou, a postavil jej na znamení pamětné, a polil jej svrchu olejem.'),
(1546984,54,1,28,19,'Protož nazval jméno místa toho Bethel, ješto prvé to město sloulo Lůza.'),
(1546985,54,1,28,20,'Zavázal se také Jákob slibem, řka: Jestliže Bůh bude se mnou, a ostříhati mne bude na cestě této, kterouž já jdu; a dá-li mi chléb ku pokrmu a roucho k oděvu,'),
(1546986,54,1,28,21,'A navrátím-li se v pokoji do domu otce svého, a bude mi Hospodin za Boha:'),
(1546987,54,1,28,22,'Kámen tento, kterýž jsem postavil na památku, bude domem Božím; a ze všech věcí, kteréž mi dáš, desátky spravedlivě tobě dám.'),
(1546988,54,1,29,1,'Tedy Jákob vstav, odšel do země východní.'),
(1546989,54,1,29,2,'A pohleděv, uzřel studnici v poli a tři stáda ovcí, ana se složila při ní; nebo z té studnice napájeli stáda; a kámen veliký byl navrchu studnice.'),
(1546990,54,1,29,3,'Shánívána pak tam bývala všecka stáda, a teprv odvalovali kámen ten od vrchu té studnice, a napájeli dobytky; potom zas přivalovali kámen na vrch studnice, na místo jeho.'),
(1546991,54,1,29,4,'Tedy řekl jim Jákob: Bratří moji, odkud jste? Kteřížto odpověděli: Jsme z Cháran.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1546992,54,1,29,5,'I řekl jim: Znáte-li Lábana, syna Náchorova? A oni řekli: Známe.'),
(1546993,54,1,29,6,'I dí opět k nim: Dobře-li se má? Odpověděli: Dobře, a aj, Ráchel dcera jeho tamto jde s dobytkem.'),
(1546994,54,1,29,7,'Tedy řekl: Však ještě daleko do večera, aniž ještě čas, aby dobytek byl sehnán; napojte stáda, a jděte, paste.'),
(1546995,54,1,29,8,'A oni odpověděli: Nemůžeme, než až se všecka stáda seženou, a odvalen bude kámen od svrchku studnice, abychom napojili ovce.'),
(1546996,54,1,29,9,'Když on ještě mluvil s nimi, přišla k tomu Ráchel s stádem otce svého; neb ona pásla stádo.'),
(1546997,54,1,29,10,'Tedy Jákob uzřev Ráchel, dceru Lábana ujce svého, a stádo jeho, přistoupil a odvalil ten kámen od vrchu studnice, a napojil stádo Lábana ujce svého.'),
(1546998,54,1,29,11,'A políbil Jákob Ráchel, a povýšiv hlasu svého, plakal.'),
(1546999,54,1,29,12,'Oznámil jí pak byl Jákob, že jest bratr otce jejího, a že jest syn Rebeky; a ona přiběhši, oznámila to otci svému.'),
(1547000,54,1,29,13,'I stalo se, když Lában uslyšel pověst o Jákobovi, synu sestry své, že vyběhl proti němu, a objav ho, políbil, a uvedl do domu svého; on pak vypravoval Lábanovi o všech těch věcech.'),
(1547001,54,1,29,14,'Jemužto odpověděl Lában: Jistě kost má a tělo mé jsi. I zůstal s ním přes celý měsíc.'),
(1547002,54,1,29,15,'Tedy řekl Lában Jákobovi: Zdali proto, že jsi bratr můj, darmo mi sloužiti budeš? Pověz mi, jaká má býti mzda tvá?'),
(1547003,54,1,29,16,'(Měl pak Lában dvě dcery; jméno starší Lía, a jméno mladší Ráchel.'),
(1547004,54,1,29,17,'Než Lía měla oči mdlé, ale Ráchel byla pěkné postavy a krásné tváři.'),
(1547005,54,1,29,18,'I miloval Jákob Ráchel.) Řekl tedy: Buduť sloužiti sedm let za Ráchel, dceru tvou mladší.'),
(1547006,54,1,29,19,'Odpověděl Lában: Lépeť jest, abych ji tobě dal, nežli bych ji dal muži jinému; zůstaniž se mnou.'),
(1547007,54,1,29,20,'Takž Jákob sloužil za Ráchel sedm let; a bylo před očima jeho jako něco málo dnů, proto že laskav byl na ni.'),
(1547008,54,1,29,21,'Potom řekl Jákob k Lábanovi: Dejž mi ženu mou; nebo vyplněni jsou dnové moji, abych všel k ní.'),
(1547009,54,1,29,22,'Tedy sezval Lában všecky muže místa toho, a učinil hody.'),
(1547010,54,1,29,23,'U večer pak vzav Líu, dceru svou, uvedl ji k němu; a on všel k ní.'),
(1547011,54,1,29,24,'Dal také Lában Zelfu děvku svou Líe, dceři své, za služebnici.'),
(1547012,54,1,29,25,'A když bylo ráno, poznal, že jest Lía. I řekl k Lábanovi: Což jsi mi to učinil? Zdaliž jsem za Ráchel nesloužil u tebe? Pročežs mne tedy oklamal?'),
(1547013,54,1,29,26,'Odpověděl Lában: Nebývá toho v kraji našem, aby vdávána byla mladší dříve, než prvorozená.'),
(1547014,54,1,29,27,'Vyplň týden této; dámeť potom i tuto za službu, kterouž sloužiti budeš u mne ještě sedm let jiných.'),
(1547015,54,1,29,28,'I udělal tak Jákob, a vyplnil týden její. Potom dal mu Ráchel dceru svou za manželku.'),
(1547016,54,1,29,29,'Dal také Lában Ráchel, dceři své, Bálu, děvku svou za služebnici.'),
(1547017,54,1,29,30,'Tedy všel také k Ráchel, a miloval ji více než Líu; i sloužil u něho ještě sedm let jiných.'),
(1547018,54,1,29,31,'Vida pak Hospodin, že Lía nemá lásky, otevřel život její; a Ráchel nechal neplodné.'),
(1547019,54,1,29,32,'Tedy počala Lía a porodila syna, a nazvala jméno jeho Ruben; nebo řekla: Jistě viděl Hospodin trápení mé; jižť nyní milovati mne bude muž můj.'),
(1547020,54,1,29,33,'I počala opět a porodila syna, a řekla: Jistě uslyšel Hospodin, že jsem v nenávisti, protož dal mi i tohoto. A nazvala jméno jeho Simeon.'),
(1547021,54,1,29,34,'A opět počala a porodila syna, a řekla: Již nyní připojí se ke mně muž můj, nebo jsem mu porodila tři syny. Z té příčiny nazváno jest jméno jeho Léví.'),
(1547022,54,1,29,35,'I počala ještě a porodila syna, a řekla: Již nyní chváliti budu Hospodina. Pročež nazvala jméno jeho Juda; i přestala roditi.'),
(1547023,54,1,30,1,'Viduci pak Ráchel, že by nerodila Jákobovi, záviděla sestře své, a řekla Jákobovi: Dej mi syny; pakli nedáš, umru.'),
(1547024,54,1,30,2,'Pročež rozhněval se velmi Jákob na Ráchel, a řekl: Zdali já jsem za Boha, kterýžť nedal plodu života?'),
(1547025,54,1,30,3,'Řekla ona: Hle, děvka má Bála; vejdi k ní, aby rodila na kolena má, a budu míti já také syny z ní.'),
(1547026,54,1,30,4,'I dala mu Bálu děvku svou za ženu; a všel k ní Jákob.'),
(1547027,54,1,30,5,'Tedy počavši Bála, porodila Jákobovi syna.'),
(1547028,54,1,30,6,'I řekla Ráchel: Soudil Bůh při mou, a uslyšel také hlas můj, a dal mi syna. Protož nazvala jméno jeho Dan.'),
(1547029,54,1,30,7,'Opět počavši Bála, děvka Ráchel, porodila syna druhého Jákobovi.'),
(1547030,54,1,30,8,'I řekla Ráchel: Tuhé jsem odpory měla s sestrou svou, a všakť jsem přemohla. A nazvala jméno jeho Neftalím.'),
(1547031,54,1,30,9,'Viduci pak Lía, že by přestala roditi, vzala Zelfu děvku svou, a dala ji Jákobovi za ženu.'),
(1547032,54,1,30,10,'A porodila Zelfa, děvka Líe, Jákobovi syna.'),
(1547033,54,1,30,11,'Protož řekla Lía: Již přišel zástup. A nazvala jméno jeho Gád.'),
(1547034,54,1,30,12,'Porodila také Zelfa děvka Líe syna druhého Jákobovi.'),
(1547035,54,1,30,13,'A řekla Lía: To na mé štěstí; nebo šťastnou mne nazývati budou ženy. A nazvala jméno jeho Asser.'),
(1547036,54,1,30,14,'Vyšel pak Ruben v čas žně pšeničné, a nalezl pěkná jablečka na poli, a přinesl je Líe matce své. I řekla Ráchel Líe: Dej mi, prosím, těch jableček syna svého.'),
(1547037,54,1,30,15,'Jížto ona odpověděla: Máloť se snad zdá, že jsi vzala muže mého; chceš také užívati jableček syna mého? I řekla Ráchel: Nechažť tedy spí s tebou této noci za jablečka syna tvého.'),
(1547038,54,1,30,16,'Když pak navracoval se Jákob s pole večer, vyšla Lía proti němu, a řekla: Ke mně vejdeš; nebo ze mzdy najala jsem tě za jablečka syna svého. I spal s ní té noci.'),
(1547039,54,1,30,17,'A uslyšel Bůh Líu; kterážto počala a porodila Jákobovi syna pátého.'),
(1547040,54,1,30,18,'I řekla Lía: Dal mi Bůh mzdu mou, i potom, když jsem dala děvku svou muži svému. Pročež nazvala jméno jeho Izachar.'),
(1547041,54,1,30,19,'A počala opět Lía, a porodila šestého syna Jákobovi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547042,54,1,30,20,'I řekla Lía: Obdařil mne Bůh darem dobrým; již nyní bydliti bude se mnou muž můj, nebo porodila jsem mu šest synů. A nazvala jméno jeho Zabulon.'),
(1547043,54,1,30,21,'Potom porodila dceru; a nazvala jméno její Dína.'),
(1547044,54,1,30,22,'A rozpomenuv se Bůh na Ráchel,uslyšel jí, a otevřel život její.'),
(1547045,54,1,30,23,'Tedy počala a porodila syna, a řekla: Odjal Bůh pohanění mé.'),
(1547046,54,1,30,24,'A nazvala jméno jeho Jozef, řkuci: Přidejž mi Hospodin syna jiného.'),
(1547047,54,1,30,25,'Stalo se pak, když porodila Ráchel Jozefa, řekl Jákob Lábanovi: Propusť mne, ať odejdu na místo své a do země své.'),
(1547048,54,1,30,26,'Dej mi ženy mé a dítky mé, za kteréž jsem sloužil tobě, ať odejdu; nebo ty znáš službu mou, kterouž jsem sloužil tobě.'),
(1547049,54,1,30,27,'I řekl mu Lában: Jestliže nyní nalezl jsem milost před očima tvýma, zůstaň se mnou, nebo v skutku jsem poznal, že požehnal mi Hospodin pro tebe.'),
(1547050,54,1,30,28,'Řekl také: Oznam mi ze jména mzdu svou a dámť ji.'),
(1547051,54,1,30,29,'Jemužto odpověděl: Ty víš, jak jsem sloužil tobě, a jaký byl dobytek tvůj při mně.'),
(1547052,54,1,30,30,'Nebo to málo, kteréž jsi měl přede mnou, zrostlo velmi, a požehnalť Hospodin, jakž jsem k tobě nohou vkročil. A nyní, kdy pak já své hospodářství opatrovati budu?'),
(1547053,54,1,30,31,'A řekl: Coť mám dáti? Odpověděl Jákob: Nedávej mi nic. Jestliže mi učiníš toto, zase pásti budu a ostříhati dobytka tvého:'),
(1547054,54,1,30,32,'Projdu skrze všecka stáda tvá dnes, vyměšuje z nich každé dobytče peřesté a strakaté, a každé dobytče načernalé mezi ovcemi, a strakaté a peřesté mezi kozami; a takové budou mzda má.'),
(1547055,54,1,30,33,'A osvědčena potom bude spravedlnost má před tebou, když přijde na mzdu mou: Cožkoli nebude peřestého, neb strakatého mezi kozami, a načernalého mezi ovcemi, za krádež bude mi to počteno.'),
(1547056,54,1,30,34,'I řekl Lában: Hle, ó by tak bylo, jakž jsi mluvil.'),
(1547057,54,1,30,35,'A odloučil toho dne kozly přepásané na nohách a strakaté, a všecky kozy peřesté a strakaté, všecko, na čemž byla místa bílá, všecko také načernalé mezi dobytkem, a dal v ruce synů svých.'),
(1547058,54,1,30,36,'Uložil pak mezi sebou a Jákobem místo vzdálí tří dní cesty; a Jákob pásl ostatek dobytka Lábanova.'),
(1547059,54,1,30,37,'Nabral pak sobě Jákob prutů topolových zelených, a lískových a kaštanových; a poobloupil s nich po místech kůru až do bělosti, kteráž byla na prutech.'),
(1547060,54,1,30,38,'A nakladl těch prutů tak obloupených do žlábků a koryt, (v nichž bývá voda, k nimž přicházel dobytek, aby pil), proti dobytku, aby počínaly, když by přicházely píti.'),
(1547061,54,1,30,39,'I počínaly ovce, hledíce na ty pruty, a rodily jehňata přepásaná na nohách, a peřestá i strakatá.'),
(1547062,54,1,30,40,'Potom ta jehňata odloučil Jákob, a dobytek stáda Lábanova obrátil tváří k těm přepásaným na nohách, a ke všemu načernalému; a své stádo postavil obzvlášť, a neobrátil ho k stádu Lábanovu.'),
(1547063,54,1,30,41,'A bylo, že kdyžkoli silnější připouštíny bývaly, kladl Jákob ty pruty před oči ovcem do koryt, aby počínaly, hledíce na pruty.'),
(1547064,54,1,30,42,'Když pak pozdní dobytek připouštín býval, nekladl jich; a tak býval pozdní Lábanův a ranný Jákobův.'),
(1547065,54,1,30,43,'Vzrostl tedy muž ten náramně velmi, a měl dobytka mnoho, děvek i služebníků, velbloudů i oslů.'),
(1547066,54,1,31,1,'Když pak uslyšel Jákob slova synů Lábanových, ani praví: Pobral Jákob všecko, co měl otec náš, a z těch věcí, kteréž byly otce našeho, způsobil sobě tu všecku slávu;'),
(1547067,54,1,31,2,'A viděl tvář Lábanovu, a aj, nebyla k němu tak jako prvé:'),
(1547068,54,1,31,3,'I řekl mu Hospodin: Navrať se do země otců svých, a k příbuznosti své, a budu s tebou.'),
(1547069,54,1,31,4,'Protož poslav Jákob, vyvolal Ráchele a Líe na pole k stádu svému.'),
(1547070,54,1,31,5,'A řekl jim: Vidím tvář otce vašeho, že není ke mně tak jako prvé, ješto Bůh otce mého byl se mnou.'),
(1547071,54,1,31,6,'A vy samy víte, že vší svou silou sloužil jsem otci vašemu.'),
(1547072,54,1,31,7,'Ale otec váš oklamal mne, a na desetkráte změnil mzdu mou; však nedopustil mu Bůh, aby mi zle učinil.'),
(1547073,54,1,31,8,'Když takto řekl: Co bude peřestého,to nechť jest mzda tvá, tedy všecky ovce rodily peřestý plod. Když pak takto řekl: Co přepásaného na nohách, to bude mzda tvá, tedy všecky ovce rodily přepásané na nohách.'),
(1547074,54,1,31,9,'A tak odjal Bůh stádo otce vašeho a dal mně.'),
(1547075,54,1,31,10,'Nebo takto bylo: Tehdáž, když se dobytek běžel, já jsem pozdvihl očí svých, a viděl jsem ve snách, a aj, berani scházející se s ovcemi byli přepásaní na nohách, peřestí a skropení.'),
(1547076,54,1,31,11,'Tedy řekl mi anděl Boží ve snách: Jákobe! A já jsem odpověděl: Teď jsem.'),
(1547077,54,1,31,12,'I řekl: Pozdvihni nyní očí svých a pohleď, že všickni berani scházející se s ovcemi jsou přepásaní na nohách, peřestí a skropení; nebo jsem viděl všecko, co tobě Lában dělá.'),
(1547078,54,1,31,13,'Já jsem ten silný Bůh, kterýž jsem se ukázal tobě v Bethel, kdež jsi pomazal kamene, kdež jsi mi se slibem zavázal; vstaniž nyní, vyjdi z země této, a navrať se do země příbuznosti své.'),
(1547079,54,1,31,14,'Tedy odpověděly mu Ráchel a Lía, řkouce: Zdaž ještě máme díl jaký a dědictví v domě otce našeho?'),
(1547080,54,1,31,15,'Zdaliž nejsme počteny před ním za cizí? Nebo prodal nás, ano i peníze naše do čista utratil.'),
(1547081,54,1,31,16,'Všecko zajisté bohatství, kteréž odjal Bůh otci našemu, naše jest a synů našich; protož nyní učiň vše, což mluvil tobě Bůh.'),
(1547082,54,1,31,17,'Vstav tedy Jákob, vsadil syny své a ženy své na velbloudy.'),
(1547083,54,1,31,18,'A pobral všecken dobytek svůj, a všecko jmění své, kteréhož byl dosáhl, dobytek svého vychování, kteréhož nabyl v Pádan Syrské, aby se navrátil k Izákovi otci svému do země Kananejské.'),
(1547084,54,1,31,19,'(Lában pak byl odšel, aby střihl ovce své. V tom ukradla Ráchel modly, kteréž měl otec její.'),
(1547085,54,1,31,20,'I ušel Jákob tajně od Lábana Syrského, neoznámiv mu, že jde pryč.)'),
(1547086,54,1,31,21,'Takž ušel se vším, což měl; a vstav, přepravil se přes řeku, a bral se přímo k hoře Galádské.'),
(1547087,54,1,31,22,'I povědíno jest Lábanovi dne třetího, že utekl Jákob.'),
(1547088,54,1,31,23,'Tedy on vzav bratří své s sebou, honil ho za dnů sedm; a postihl ho na hoře Galádské.'),
(1547089,54,1,31,24,'(Přišed pak Bůh k Lábanovi Syrskému ve snách noci té, řekl mu: Varuj se, abys nemluvil s Jákobem nic jináč než přátelsky.)'),
(1547090,54,1,31,25,'Dohonil tedy Lában Jákoba; a Jákob již byl rozbil stan svůj na té hoře; Lában také položil se s bratřími svými na též hoře Galádské.'),
(1547091,54,1,31,26,'I řekl Lában k Jákobovi: Cos to učinil? Nebo jsi ušel tajně, a odvedls dcery mé jako zjímané mečem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547092,54,1,31,27,'Proč jsi tajně utekl, a vykradl se ode mne, a nepověděls mi, ješto bych tě byl vesele sprovodil s zpěvy, s bubnem a s harfou?'),
(1547093,54,1,31,28,'A nedopustils mi, abych políbil synů svých a dcer svých? Nemoudřes jistě udělal, čině tak.'),
(1547094,54,1,31,29,'Mělť bych dosti s to moci, abych vám zle učinil, ale Bůh otce vašeho mluvil mi noci pominulé, řka: Hleď, abys nemluvil s Jákobem nic jináč, než přátelsky.'),
(1547095,54,1,31,30,'Ale již to tam, poněvadž jsi předce odšel, roztouživ se po domu otce svého; než proč jsi ukradl bohy mé?'),
(1547096,54,1,31,31,'Tedy Jákob odpovídaje Lábanovi, řekl: Ušel jsem tajně; nebo jsem se bál a řekl jsem, že bys snad mocí odjal dcery své.'),
(1547097,54,1,31,32,'Nalezneš-li pak u koho bohy své,nechať ten umře; před bratřími našimi ohledej sobě, jest-li co u mne tvého, a vezmi sobě. Ale nevěděl Jákob, že Ráchel je ukradla.'),
(1547098,54,1,31,33,'Všed tedy Lában do stanu Jákobova, a do stanu Líe, a do stanu obou děvek, nic nenalezl. A vyšed z stanu Líe, všel do stanu Ráchel.'),
(1547099,54,1,31,34,'Ráchel pak vzavši modly, vložila je pod sedlo, kteréž na velbloudu bývá, a sedla na ně. I přemetal Lában všecken stan, ale nic nenalezl.'),
(1547100,54,1,31,35,'A ona řekla otci svému: Nechť to není proti mysli, pane můj, že nemohu povstati proti tobě; nebo vedlé běhu ženského nyní mi se přihodilo. A všecko přehledav, nenalezl modl.'),
(1547101,54,1,31,36,'Protož rozhněvav se Jákob, tuze se domlouval na Lábana. I odpověděl Jákob, a řekl Lábanovi: Jaké jest přestoupení mé? Jaký hřích můj, že rozpáliv se, honíš mne?'),
(1547102,54,1,31,37,'Nu již jsi přemetal všecky mé věci, a cos nalezl ze všech věcí domu svého? Polož teď před bratřími mými a bratřími svými, nechť rozeznají mezi námi dvěma.'),
(1547103,54,1,31,38,'Byl jsem již dvadceti let s tebou; ovce tvé ani kozy tvé nikdy nezmetaly; a skopců stáda tvého nejedl jsem.'),
(1547104,54,1,31,39,'Co od zvěři roztrháno, toho jsem neodvodil tobě; sám jsem tu škodu nahražoval, a ty jsi z ruky mé vyhledával toho, jako i toho, co bylo ukradeno ve dne aneb v noci.'),
(1547105,54,1,31,40,'Bývalo tak, že ve dne trápilo mne horko, a v noci mráz, tak že odcházel i sen můj od očí mých.'),
(1547106,54,1,31,41,'Již dvadceti let, jakž jsem v domě tvém; sloužil jsem tobě čtrnácte let za dvě dcery tvé, a šest let za dobytek tvůj, a změnils mzdu mou na desetkrát.'),
(1547107,54,1,31,42,'A kdyby Bůh otce mého, Bůh Abrahamův, a strach Izákův nebyl se mnou, jistě bys ty byl nyní pustil mne prázdného; ale trápení mé, a práci rukou mých viděl Bůh, protož tě pominulé noci trestal.'),
(1547108,54,1,31,43,'Odpovídaje pak Lában, dí Jákobovi: Dcery tyto jsou dcery mé a synové tito jsou synové moji, i dobytek tento můj dobytek jest, ano cokoli vidíš, mé jest; ale což mám již učiniti dcerám těmto svým aneb synům jich, kteréž zrodily?'),
(1547109,54,1,31,44,'Protož poď, vejděme v smlouvu já a ty, aby byla na svědectví mezi mnou a tebou.'),
(1547110,54,1,31,45,'Tedy Jákob vzal kámen, a postavil jej vzhůru na znamení.'),
(1547111,54,1,31,46,'A řekl bratřím svým: Nasbírejte kamení. A nabravše kamení, udělali hromadu, a jedli tu na té hromadě.'),
(1547112,54,1,31,47,'I nazval ji Lában Jegar Sahadutha, a Jákob nazval ji Gál Ed.'),
(1547113,54,1,31,48,'Nebo řekl Lában: Tato hromada nechžť jest svědkem od dnešku mezi mnou a tebou. Protož nazval jméno její Gál Ed,'),
(1547114,54,1,31,49,'A Mispah; nebo řekl Lában: Nechať Hospodin hledí na mne a na tebe, když se rozejdeme od sebe.'),
(1547115,54,1,31,50,'Jestliže bys trápil dcery mé, a uvedl bys jiné ženy na dcery mé, žádného člověka není s námi; hlediž, Bůh jest svědek mezi mnou a tebou.'),
(1547116,54,1,31,51,'A řekl ještě Lában Jákobovi: Aj, hromada tato, a aj, sloup, kterýž jsem postavil mezi sebou a tebou,'),
(1547117,54,1,31,52,'Svědkem ať jest hromada tato, svědkem také sloup tento, já že nepůjdu dále k tobě za hromadu tuto, a ty tolikéž že nepůjdeš dále ke mně za hromadu tuto a sloup tento, k činění zlého.'),
(1547118,54,1,31,53,'Bůh Abrahamův, a Bůh Náchorův, Bůh otce jejich nechť soudí mezi námi. Přisáhl tedy Jákob skrze strach otce svého Izáka.'),
(1547119,54,1,31,54,'Nabil také Jákob hovad na té hoře, a pozval bratří svých, aby hodovali; i hodovali a zůstali přes noc na též hoře.'),
(1547120,54,1,31,55,'I vstal Lában velmi ráno, a políbiv synů svých a dcer svých, požehnal jich; i odšel a navrátil se k místu svému.'),
(1547121,54,1,32,1,'Jákob pak odšel cestou svou, a potkali se s ním andělé Boží.'),
(1547122,54,1,32,2,'I řekl Jákob, když je viděl: Vojsko Boží jest toto. A nazval jméno místa toho Mahanaim.'),
(1547123,54,1,32,3,'Poslal pak Jákob posly před sebou k bratru svému Ezau, do země Seir, do kraje Idumejského.'),
(1547124,54,1,32,4,'A přikázal jim, řka: Takto povězte pánu mému Ezau: Totoť vzkazuje služebník tvůj Jákob: U Lábana jsem byl pohostinu, a zůstával až do tohoto času.'),
(1547125,54,1,32,5,'A mám voly a osly, ovce, a služebníky i děvky; a poslal jsem, abych se ohlásil pánu svému, a našel milost před očima tvýma.'),
(1547126,54,1,32,6,'I navrátili se poslové k Jákobovi, řkouce: Přišli jsme k bratru tvému Ezau, kterýž také jde proti tobě, a čtyři sta mužů s ním.'),
(1547127,54,1,32,7,'Jákob pak bál se velmi, a rmoutil se náramně. Tedy rozdělil lid, kterýž s sebou měl, ovce také a voly, a velbloudy na dva houfy.'),
(1547128,54,1,32,8,'Nebo řekl: Jestliže by přišel Ezau k houfu jednomu, a pobil by jej, bude aspoň zadní houf zachován.'),
(1547129,54,1,32,9,'I řekl Jákob: Bože otce mého Abrahama, a Bože otce mého Izáka, Hospodine, kterýž jsi mi řekl: Navrať se do země své, a k příbuznosti své, a dobře učiním tobě,'),
(1547130,54,1,32,10,'Menší jsem všech milosrdenství a vší pravdy, kterouž jsi učinil s služebníkem svým; nebo s holí svou přešel jsem Jordán tento, nyní pak dva houfy mám.'),
(1547131,54,1,32,11,'Vytrhni mne, prosím, z ruky bratra mého, z ruky Ezau; nebť se ho bojím, aby přijda, nepohubil mne i matky s dětmi.'),
(1547132,54,1,32,12,'Však jsi ty řekl: Dobře učiním tobě, a rozmnožím símě tvé jako písek mořský, kterýžto pro množství sečten býti nemůže.'),
(1547133,54,1,32,13,'I zůstal tu noci té; a vzal z toho, což bylo před rukama, poctu bratru svému Ezau:'),
(1547134,54,1,32,14,'Totiž dvě stě koz, a kozlů dvadceti, ovec dvě stě, a beranů dvadceti,'),
(1547135,54,1,32,15,'Velbloudů s mladými jich třidceti, krav čtyřidceti, volů deset, oslic dvadceti, a oslátek deset.'),
(1547136,54,1,32,16,'A poručil je služebníkům svým, každé stádo obzvláštně, a řekl služebníkům svým: Jděte přede mnou, a stádo od stáda ať jde opodál.'),
(1547137,54,1,32,17,'I poručil přednímu, řka: Když se potká s tebou Ezau bratr můj, a optá se tebe, řka Čí jsi? a kam jdeš? a čí jest to stádo před tebou?'),
(1547138,54,1,32,18,'Řekneš: Jsem služebníka tvého Jákoba, a dar tento jest poslán pánu mému Ezau; a teď i sám jde za námi.'),
(1547139,54,1,32,19,'Poručil také druhému i třetímu, a všechněm jdoucím za těmi stády, řka: V táž slova mluvte k Ezau, když byste naň trefili.'),
(1547140,54,1,32,20,'A díte také: Aj, služebník tvůj Jákob za námi; nebo řekl: Ukrotím tvář jeho darem, kterýž jde přede mnou, a potom uzřím tvář jeho; snad přijme tvář mou.'),
(1547141,54,1,32,21,'A tak předšel dar před ním; on pak zůstal tu noc při houfu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547142,54,1,32,22,'A vstav ještě v noci, vzal obě ženy své, a dvě děvky své, a jedenácte synů svých, a přešel přes brod Jabok.'),
(1547143,54,1,32,23,'Vzav tedy je, přepravil je přes tu řeku; přepravil také i vše, což měl.'),
(1547144,54,1,32,24,'A zůstal Jákob sám; a tu zápasil s ním muž až do svitání.'),
(1547145,54,1,32,25,'A vida, že ho nepřemůže, obrazil jej v příhbí vrchní stehna jeho; i vyvinulo se příhbí stehna Jákobova, když zápasil s ním.'),
(1547146,54,1,32,26,'A řekl: Pusť mne, nebť zasvitává. I řekl: Nepustím tě, leč mi požehnáš.'),
(1547147,54,1,32,27,'I řekl jemu: Jaké jest jméno tvé? Odpověděl: Jákob.'),
(1547148,54,1,32,28,'I dí: Nebude více nazýváno jméno tvé toliko Jákob, ale také Izrael; nebo jsi statečně zacházel s Bohem i lidmi, a přemohls.'),
(1547149,54,1,32,29,'I otázal se Jákob, řka: Oznam, prosím, jméno své. Kterýžto odpověděl: Proč se ptáš na jméno mé? I dal mu tu požehnání.'),
(1547150,54,1,32,30,'Tedy nazval Jákob jméno místa toho Fanuel; nebo jsem prý viděl Boha tváří v tvář, a zachována jest duše má.'),
(1547151,54,1,32,31,'I vzešlo mu slunce, když pominul místa toho Fanuel, a kulhal na nohu svou.'),
(1547152,54,1,32,32,'Protož nejedí synové Izraelští až do tohoto dne té žily krátké, kteráž jest v vrchním příhbí stehna, proto že obrazil příhbí stehna Jákobova na žile krátké.'),
(1547153,54,1,33,1,'Pozdvih pak očí svých Jákob, uzřel, an Ezau jde, a čtyři sta mužů s ním; i rozdělil syny Líe zvlášť a Ráchele zvlášť, a obou děvek zvlášť.'),
(1547154,54,1,33,2,'Postavil, pravím, děvky s syny jejich napřed, potom Líu s syny jejími za nimi, Ráchel pak a Jozefa nejzáze.'),
(1547155,54,1,33,3,'A sám šel před nimi, a poklonil se až k zemi po sedmkrát, až právě přišel k bratru svému.'),
(1547156,54,1,33,4,'I běžel Ezau proti němu, a objal ho; a pad na šíji jeho, líbal ho. I plakali.'),
(1547157,54,1,33,5,'Pozdvih pak očí svých, a spatřiv ženy s dětmi, řekl: Kdo jsou onino s tebou? Odpověděl: Jsou dítky, kteréž Bůh dal z milosti služebníku tvému.'),
(1547158,54,1,33,6,'Mezi tím přiblížily se děvky s syny svými, i poklonili se.'),
(1547159,54,1,33,7,'Přiblížila se také Lía s syny svými, a poklonili se; a potom přiblížil se Jozef a Ráchel, a také se poklonili.'),
(1547160,54,1,33,8,'I řekl Ezau: K čemu jest všecken ten houf, kterýž jsem potkal? Odpověděl: Abych nalezl milost před očima pána mého.'),
(1547161,54,1,33,9,'Tedy řekl Ezau: Mám hojně, bratře můj; nech sobě, což tvého jest.'),
(1547162,54,1,33,10,'I řekl Jákob: Nezbraňuj se, prosím; jestliže jsem nyní nalezl milost před očima tvýma, přijmi dar můj z ruky mé, poněvadž jsem viděl tvář tvou, jako bych viděl tvář Boží, a laskavě jsi mne přijal.'),
(1547163,54,1,33,11,'Přijmi, prosím, dar můj obětovaný tobě, poněvadž štědře obdařil mne Bůh, a mám všeho dosti. Takž ho přinutil, a on vzal.'),
(1547164,54,1,33,12,'I dí: Poď, a jděme; já půjdu s tebou.'),
(1547165,54,1,33,13,'I řekl k němu Jákob: Ví pán můj, že děti jsou outlí, a mám s sebou ovce i krávy březí; kteréžto budou-li hnány přes moc jeden den, pomře mi všecken dobytek.'),
(1547166,54,1,33,14,'Nechžť medle jde pán můj před služebníkem svým, já pak poznenáhlu se poberu, tak jakž bude moci jíti stádo, kteréž před sebou mám, a jakž postačiti budou moci děti, až tak dojdu ku pánu svému do Seir.'),
(1547167,54,1,33,15,'I řekl Ezau: Nechť ale pozůstavím něco lidu, kterýž mám s sebou. I odpověděl: K čemu to? Nechť toliko naleznu milost před očima pána svého.'),
(1547168,54,1,33,16,'Tedy Ezau toho dne navrátil se cestou svou do Seir.'),
(1547169,54,1,33,17,'Jákob pak bral se do Sochot, a ustavěl sobě dům, a dobytku svému zdělal stáje; protož nazval jméno místa toho Sochot.'),
(1547170,54,1,33,18,'A tak Jákob navracuje se z Pádan Syrské, přišel ve zdraví k městu Sichem, kteréž jest v zemi Kananejské, a položil se před městem.'),
(1547171,54,1,33,19,'I koupil díl pole toho, na němž byl rozbil stan svůj, od synů Emora, otce Sichemova, za sto ovec.'),
(1547172,54,1,33,20,'A postavil tu oltář, kterémužto dal jméno Bůh silný, Bůh Izraelský.'),
(1547173,54,1,34,1,'Vyšla pak Dína, dcera Líe, kterouž porodila Jákobovi, aby se dívala na dcery té země.'),
(1547174,54,1,34,2,'Kteroužto uzřev Sichem, syn Emora Hevejského, knížete v krajině té, vzal ji, i ležel s ní, a ponížil jí.'),
(1547175,54,1,34,3,'I připojila se duše jeho k Díně, dceři Jákobově; a zamilovav děvečku, mluvil k srdci jejímu.'),
(1547176,54,1,34,4,'Mluvil potom Sichem k Emorovi, otci svému, těmito slovy: Vezmi mi děvečku tuto za manželku.'),
(1547177,54,1,34,5,'Uslyšev pak Jákob, že poškvrnil Díny dcery jeho, (a synové jeho byli s stádem na poli), mlčel, až oni přišli.'),
(1547178,54,1,34,6,'Tedy vyšel Emor, otec Sichemův, k Jákobovi, aby mluvil s ním o to.'),
(1547179,54,1,34,7,'A v tom synové Jákobovi přišli s pole; a uslyšavše o tom, bolestí naplněni jsou muži ti, a rozhněvali se velmi, proto že hanebnou věc učinil v Izraeli, ležav se dcerou Jákobovou, čehož činiti nenáleželo.'),
(1547180,54,1,34,8,'I mluvil Emor s nimi na tento způsob: Sichem, syn můj, hoří milostí k vaší dceři; prosím, dejte mu ji za manželku.'),
(1547181,54,1,34,9,'A spřízněte se s námi: Dcery své dávejte nám, a naše dcery pojímejte sobě.'),
(1547182,54,1,34,10,'A bydlete s námi, nebo všecka země bude před vámi; osaďte se a obchod veďte v ní, a vládněte jí.'),
(1547183,54,1,34,11,'Mluvil i Sichem otci jejímu, a bratřím jejím: Nechť naleznu milost před očima vašima, dám, co mi koli díte.'),
(1547184,54,1,34,12,'Jmenujte mi věno i dary jak chcete veliké, dám, jak mi koli řeknete; jen mi tu děvečku dejte za manželku.'),
(1547185,54,1,34,13,'Odpovídajíce pak synové Jákobovi Sichemovi a Emorovi, otci jeho, lstivě mluvili, proto že poškvrnil Díny sestry jich.'),
(1547186,54,1,34,14,'A řekli jim: Nemůžeme učiniti toho, abychom dali sestru svou za muže neobřezaného; nebo to ohavnost jest u nás.'),
(1547187,54,1,34,15,'Než na tento způsob vám povolíme: Jestliže se chcete srovnati s námi, aby obřezán byl každý z vás pohlaví mužského:'),
(1547188,54,1,34,16,'Tedy budeme dávati dcery své vám, a dcery vaše bráti sobě; a budeme bydliti s vámi, a budeme lid jeden.'),
(1547189,54,1,34,17,'Pakli neuposlechnete nás, abyste se obřezali, vezmeme zase dceru svou a odejdeme.'),
(1547190,54,1,34,18,'Tedy líbila se řeč jejich Emorovi i Sichemovi, synu Emorovu.'),
(1547191,54,1,34,19,'A nemeškal mládenec učiniti toho; nebo se mu zalíbila dcera Jákobova. A on byl nejvzácnější ze všech v domě otce svého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547192,54,1,34,20,'I přišel Emor a Sichem, syn jeho, k bráně města svého; a mluvili mužům města svého, řkouce:'),
(1547193,54,1,34,21,'Muži tito pokojně se mají k nám, nechť tedy bydlí v zemi této, a obchod vedou v ní, (nebo země jest dosti široká a prostranná před nimi;) dcery jejich budeme sobě bráti za manželky, a dcery své budeme dávati jim.'),
(1547194,54,1,34,22,'Než na tento způsob přivolí nám ti muži k tomu, aby bydlili s námi, a abychom byli jeden lid: Jestliže obřezán bude každý pohlaví mužského mezi námi, tak jako oni jsou obřezáni.'),
(1547195,54,1,34,23,'Dobytek jejich a statek jejich, i všecka hovada jejich, zdaliž nebudou naše? Toliko v tom jim povolme, a budou bydliti s námi.'),
(1547196,54,1,34,24,'I uposlechli Emora a Sichema, syna jeho, všickni vycházející branou města jeho; a obřezali se všickni pohlaví mužského, což jich koli vycházelo z brány města jeho.'),
(1547197,54,1,34,25,'A toť dne třetího, když oni největší bolest měli, dva synové Jákobovi, Simeon a Léví, bratří Díny, vzav každý z nich meč svůj, vpadli do města směle, a pomordovali všecky pohlaví mužského.'),
(1547198,54,1,34,26,'Emora také a Sichema, syna jeho, zamordovali mečem, a vzavše Dínu z domu Sichemova, odešli.'),
(1547199,54,1,34,27,'Potom synové Jákobovi přišedše na zbité, vzebrali město, proto že poškvrnili sestry jejich.'),
(1547200,54,1,34,28,'Stáda jejich, a voly i osly jejich, a což bylo v městě i po poli, pobrali.'),
(1547201,54,1,34,29,'K tomu i všecko jmění jejich, a všecky malé dítky jejich, a ženy jejich zajali, a vybrali, co kde v domích bylo.'),
(1547202,54,1,34,30,'Řekl pak Jákob Simeonovi a Léví: Zkormoutili jste mne, a zošklivili jste mne u obyvatelů krajiny této, u Kananejských a Ferezejských, a já jsem s malým počtem lidí. Seberou-li se na mne, zbijí mne, a tak vyhlazen budu já i dům můj.'),
(1547203,54,1,34,31,'A oni odpověděli: A což měli jako nevěstky zle užívati sestry naší?'),
(1547204,54,1,35,1,'Potom mluvil Bůh k Jákobovi: Vstana, vstup do Bethel, a bydli tam; a udělej tam oltář Bohu silnému, kterýž se ukázal tobě, kdyžs utíkal před Ezau bratrem svým.'),
(1547205,54,1,35,2,'Tedy řekl Jákob čeládce své, a všechněm, kteříž s ním byli: Odvrzte bohy cizí, kteréž máte mezi sebou, a očisťte se, a změňte roucha svá.'),
(1547206,54,1,35,3,'A vstanouce, vstupme do Bethel, a udělám tam oltář silnému Bohu, kterýž vyslyšel mne v den ssoužení mého, a byl se mnou na cestě, kterouž jsem šel.'),
(1547207,54,1,35,4,'Tedy dali Jákobovi všecky bohy cizí, kteréž měli, i náušnice, kteréž byly na uších jejich; i zakopal je Jákob pod tím dubem, kterýž byl u Sichem.'),
(1547208,54,1,35,5,'I brali se odtud. (A byl strach Boží na městech, kteráž byla vůkol nich, a nehonili synů Jákobových.)'),
(1547209,54,1,35,6,'Tedy přišel Jákob do Lůz, kteréž jest v zemi Kananejské, (to již slove Bethel,) on i všecken lid, kterýž byl s ním.'),
(1547210,54,1,35,7,'I vzdělal tu oltář, a nazval to místo Bůh silný Bethel; nebo tu se mu byl zjevil Bůh, když utíkal před bratrem svým.'),
(1547211,54,1,35,8,'Tehdy umřela Debora, chovačka Rebeky, a pochována jest pod Bethel, pod dubem; i nazval jméno jeho Allon Bachuth.'),
(1547212,54,1,35,9,'Ukázal se pak opět Bůh Jákobovi, když se navracoval z Pádan Syrské, a požehnal mu.'),
(1547213,54,1,35,10,'I řekl jemu Bůh: Jméno tvé jest Jákob. Nebude více nazývano jméno tvé toliko Jákob, ale Izrael také bude jméno tvé. Protož nazval jméno jeho Izrael.'),
(1547214,54,1,35,11,'Řekl ještě Bůh jemu: Já jsem Bůh silný všemohoucí; rostiž a množ se; národ, nýbrž množství národů bude z tebe, i králové z bedr tvých vyjdou.'),
(1547215,54,1,35,12,'A zemi tu, kterouž jsem dal Abrahamovi a Izákovi, tobě ji dám; semeni také tvému po tobě dám tu zemi.'),
(1547216,54,1,35,13,'I vstoupil od něho Bůh z místa, na kterémž mluvil s ním.'),
(1547217,54,1,35,14,'Jákob pak vyzdvihl znamení pamětné na místě tom, na kterémž mluvil s ním, sloup kamenný; a pokropil ho skropením, a svrchu polil jej olejem.'),
(1547218,54,1,35,15,'A nazval Jákob jméno místa toho, na kterémž mluvil s ním Bůh, Bethel.'),
(1547219,54,1,35,16,'I brali se z Bethel, a bylo již nedaleko do Efraty. I porodila Ráchel, a těžkosti trpěla roděci.'),
(1547220,54,1,35,17,'A když s těžkostí rodila, řekla jí baba: Neboj se, nebo také tohoto syna míti budeš.'),
(1547221,54,1,35,18,'I stalo se, když k smrti pracovala, (nebo umřela), nazvala jméno jeho Ben Oni; ale otec jeho nazval ho Beniaminem.'),
(1547222,54,1,35,19,'I umřela Ráchel, a pochována jest na cestě k Efratě, jenž jest Betlém.'),
(1547223,54,1,35,20,'A postavil Jákob znamení pamětné nad hrobem jejím; toť jest znamení hrobu Ráchel až do dnešního dne.'),
(1547224,54,1,35,21,'I odebral se odtud Izrael, a rozbil stan svůj za věží Eder.'),
(1547225,54,1,35,22,'Stalo se pak také, když bydlil Izrael v té krajině, že Ruben šel, a spal s Bálou, ženinou otce svého; o čemž uslyšel Izrael. Bylo pak synů Jákobových dvanácte.'),
(1547226,54,1,35,23,'Synové pak Líe: Prvorozený Jákobův Ruben, potom Simeon, a Léví, a Juda, a Izachar, a Zabulon.'),
(1547227,54,1,35,24,'Synové Ráchel: Jozef a Beniamin.'),
(1547228,54,1,35,25,'A synové Bály, děvky Ráchel: Dan a Neftalím.'),
(1547229,54,1,35,26,'A synové Zelfy, děvky Líe: Gád a Asser. Tiť jsou synové Jákobovi, kteříž mu zrozeni jsou v Pádan Syrské.'),
(1547230,54,1,35,27,'Tedy přišel Jákob k Izákovi otci svému do Mamre, do města Arbe, jenž jest Hebron, kdežto bydlil pohostinu Abraham a Izák.'),
(1547231,54,1,35,28,'A bylo dnů Izákových sto osmdesáte let.'),
(1547232,54,1,35,29,'I dokonal Izák, a umřel, a připojen jest k lidu svému, stár jsa a plný dnů; i pochovali ho Ezau a Jákob, synové jeho.'),
(1547233,54,1,36,1,'Tito jsou pak rodové Ezau, kterýž měl přijmí Edom.'),
(1547234,54,1,36,2,'Ezau pojal sobě ženy ze dcer Kananejských, Adu, dceru Elona Hetejského, a Olibamu, dceru Anovu, dceru Sebeona Hevejského,'),
(1547235,54,1,36,3,'A Bazematu, dceru Izmaelovu, sestru Nabajotovu.'),
(1547236,54,1,36,4,'I porodila Ada Ezauchovi Elifaza, a Bazemat porodila Rahuele.'),
(1547237,54,1,36,5,'Olibama pak porodila Jehusa, a Jheloma, a Koré. Ti jsou synové Ezau, kteříž se mu zrodili v zemi Kananejské.'),
(1547238,54,1,36,6,'I pobral Ezau ženy své, i syny své, a dcery své, a všecku čeleď svou, i dobytek svůj, a všecka hovada svá, i všecko jmění své, kteréhož nabyl v zemi Kananejské, a odebral se do země Seir, před příchodem Jákoba bratra svého.'),
(1547239,54,1,36,7,'Nebo zboží jejich bylo tak veliké, že nemohli bydliti spolu; aniž ta země, v níž oni pohostinu byli, mohla jich snésti, pro dobytky jejich.'),
(1547240,54,1,36,8,'Protož bydlil Ezau na hoře Seir; Ezau pak ten jest Edom.'),
(1547241,54,1,36,9,'A tak tito jsou rodové Ezau, otce Idumejských, na hoře Seir.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547242,54,1,36,10,'Tato byla jména synů Ezau: Elifaz, syn Ady, ženy Ezau; Rahuel, syn Bazematy, ženy Ezau.'),
(1547243,54,1,36,11,'Synové pak Elifazovi byli: Teman, Omar, Sefo, a Gatam a Kenaz.'),
(1547244,54,1,36,12,'Tamna pak byla ženina Elifaza, syna Ezau. Ta porodila Elifazovi Amalecha. Ti jsou synové Ady, ženy Ezau.'),
(1547245,54,1,36,13,'Synové pak Rahuelovi tito: Nahat, Zára, Samma a Méza. To byli synové Bazematy, ženy Ezau.'),
(1547246,54,1,36,14,'A tito byli synové Olibamy, dcery Anovy, dcery Sebeonovy, ženy Ezau, kteráž porodila Ezauchovi Jehusa, Jheloma a Koré.'),
(1547247,54,1,36,15,'Tito všickni byli knížata synů Ezau. Synové Elifaza prvorozeného Ezau: Kníže Teman, kníže Omar, kníže Sefo, kníže Kenaz,'),
(1547248,54,1,36,16,'Kníže Koré, kníže Gatam, kníže Amalech. Ta jsou knížata pošlá z Elifaza v zemi Idumejské; ti jsou synové Ady.'),
(1547249,54,1,36,17,'Tito pak jsou synové Rahuele, syna Ezau: Kníže Nahat, kníže Zára, kníže Samma, kníže Méza. Ta knížata pošla z Rahuele, v zemi Idumejské; to jsou synové Bazematy, ženy Ezau.'),
(1547250,54,1,36,18,'A synové Olibamy, ženy Ezau, tito jsou: Kníže Jehus, kníže Jhelom, kníže Koré. To jsou knížata z Olibamy, dcery Anovy, ženy Ezau.'),
(1547251,54,1,36,19,'Tiť jsou synové Ezau, a ta knížata jejich; onť jest Edom.'),
(1547252,54,1,36,20,'Tito pak jsou synové Seir, totiž Horejští, obyvatelé země té: Lotan, Sobal, Sebeon a Ana,'),
(1547253,54,1,36,21,'A Dison, Eser a Dízan. Ta jsou knížata Horejská, synové Seir, v zemi Idumejské.'),
(1547254,54,1,36,22,'Synové Lotanovi byli: Hori a Hemam; a sestra Lotanova Tamna.'),
(1547255,54,1,36,23,'Synové pak Sobalovi tito: Alvan, Manáhat, Ebal, Sefo a Onam.'),
(1547256,54,1,36,24,'A tito synové Sebeonovi: Aia a Ana. To jest ten Ana, kterýž nalezl mezky na poušti, když pásl osly Sebeona otce svého.'),
(1547257,54,1,36,25,'Tito pak děti Anovi: Dison a Olibama, dcera Anova.'),
(1547258,54,1,36,26,'A synové Dízanovi tito: Hamdan, Eseban, Jetran a Charan.'),
(1547259,54,1,36,27,'Synové Eser tito: Balaan, Závan a Achan.'),
(1547260,54,1,36,28,'Tito synové Dízanovi: Hus a Aran.'),
(1547261,54,1,36,29,'Tato jsou knížata Horejská: Kníže Lotan, kníže Sobal, kníže Sebeon, kníže Ana,'),
(1547262,54,1,36,30,'Kníže Dison, kníže Eser, kníže Dízan. To byla knížata Horejská, po knížetstvích svých v zemi Seir.'),
(1547263,54,1,36,31,'Tito pak byli králové, kteříž kralovali v zemi Idumejské, prvé než kraloval král nad syny Izraelskými.'),
(1547264,54,1,36,32,'Kraloval tedy v Edom Béla, syn Beorův, a jméno města jeho Denaba.'),
(1547265,54,1,36,33,'I umřel Béla, a kraloval místo něho Jobab, syn Záre z Bozra.'),
(1547266,54,1,36,34,'I umřel Jobab, a kraloval na místě jeho Husam z země Temanské.'),
(1547267,54,1,36,35,'Umřel i Husam, a kraloval místo něho Adad, syn Badadův, kterýž porazil Madianské v krajině Moábské; a jméno města jeho Avith.'),
(1547268,54,1,36,36,'Když pak umřel Adad, kraloval místo něho Semla z Masreka.'),
(1547269,54,1,36,37,'A po smrti Semlově kraloval na místě jeho Saul z Rohobot od řeky.'),
(1547270,54,1,36,38,'Umřel i Saul, a kraloval místo něho Bálanan, syn Achoborův.'),
(1547271,54,1,36,39,'A když i Bálanan umřel, syn Achoborův, kraloval na místě jeho Adar; a jméno města jeho Pahu; jméno pak ženy jeho Mehetabel, dcera Matredy, dcery Mezábovy.'),
(1547272,54,1,36,40,'Ta jsou jména knížat pošlých z Ezau, po čeledech jejich, po místech jejich, vedlé jmen jejich: Kníže Tamna, kníže Alva, kníže Jetet,'),
(1547273,54,1,36,41,'Kníže Olibama, kníže Ela, kníže Finon.'),
(1547274,54,1,36,42,'Kníže Kenaz, kníže Teman, kníže Mabsar.'),
(1547275,54,1,36,43,'Kníže Magdiel, kníže Híram. Tať jsou knížata Idumejská, tak jakž kteří bydlili v zemi dědictví svého. Toť jest ten Ezau, otec Idumejských.'),
(1547276,54,1,37,1,'Jákob pak bydlil v zemi putování otce svého, v zemi Kananejské.'),
(1547277,54,1,37,2,'Tito jsou příběhové Jákobovi: Jozef, když byl v sedmnácti letech, pásl s bratřími svými dobytek, (a byl mládeneček), s syny Bály a Zelfy, žen otce svého. A oznamoval Jozef zlou pověst o nich otci svému.'),
(1547278,54,1,37,3,'Izrael pak miloval Jozefa nad všecky syny své; nebo v starosti své zplodil jej. A udělal mu sukni proměnných barev.'),
(1547279,54,1,37,4,'A když spatřili bratří jeho, že ho miluje otec jejich nad všecky bratří jeho, nenáviděli ho, aniž mohli pokojně k němu promluviti.'),
(1547280,54,1,37,5,'Měl pak Jozef sen, a vypravoval jej bratřím svým; pročež v větší nenávisti ho měli.'),
(1547281,54,1,37,6,'Nebo pravil jim: Slyšte, prosím, sen, kterýž jsem měl.'),
(1547282,54,1,37,7,'Hle, vázali jsme snopy na poli, a aj, povstal snop můj, a stál. Vůkol také stáli snopové vaši, a klaněli se snopu mému.'),
(1547283,54,1,37,8,'Jemužto odpověděli bratří jeho: Zdaliž kralovati budeš nad námi, aneb pánem naším budeš? Z té příčiny ještě více nenáviděli ho pro sny jeho, a pro slova jeho.'),
(1547284,54,1,37,9,'Potom ještě měl jiný sen, a vypravoval jej bratřím svým, řka: Hle, opět jsem měl sen, a aj, slunce a měsíc, a jedenácte hvězd klanělo mi se.'),
(1547285,54,1,37,10,'I vypravoval otci svému a bratřím svým. A domlouval mu otec jeho, a řekl jemu: Jakýž jest to sen, kterýž jsi měl? Zdaliž přijdeme, já a matka tvá i bratří tvoji, abychom se klaněli před tebou až k zemi?'),
(1547286,54,1,37,11,'Tedy záviděli mu bratří jeho; ale otec jeho měl pozor na tu věc.'),
(1547287,54,1,37,12,'Odešli pak bratří jeho, aby pásli dobytek otce svého v Sichem.'),
(1547288,54,1,37,13,'A řekl Izrael Jozefovi: Zdaliž nepasou bratří tvoji v Sichem: Poď, a pošli tě k nim. Kterýžto odpověděl: Aj, teď jsem.'),
(1547289,54,1,37,14,'I řekl jemu: Jdi nyní, zvěz, jak se mají bratří tvoji, a co se děje s dobytkem; a zase mi povíš o tom. A tak poslal ho z údolí Hebron, a on přišel do Sichem.'),
(1547290,54,1,37,15,'Našel ho pak muž nějaký, an bloudí po poli. I zeptal se ho muž ten, řka: Čeho hledáš?'),
(1547291,54,1,37,16,'Odpověděl: Bratří svých hledám; pověz mi, prosím, kde oni pasou?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547292,54,1,37,17,'I řekl muž ten: Odešli odsud; nebo slyšel jsem je, ani praví: Poďme do Dothain. Tedy šel Jozef za bratřími svými, a našel je v Dothain.'),
(1547293,54,1,37,18,'Kteřížto, jakž ho uzřeli zdaleka, prvé než k nim došel, ukládali o něm, aby jej zahubili.'),
(1547294,54,1,37,19,'Nebo řekli jeden druhému: Ej, mistr snů teď jde.'),
(1547295,54,1,37,20,'Nyní tedy poďte, a zabíme jej, a uvržeme ho do některé čisterny, a díme: Zvěř lítá sežrala jej. I uzříme, nač jemu vyjdou snové jeho.'),
(1547296,54,1,37,21,'A uslyšev to Ruben, aby ho vytrhl z ruky jejich, (nebo řekl: Neodjímejme mu hrdla,)'),
(1547297,54,1,37,22,'Řekl jim Ruben: Nevylévejte krve. Vrzte jej do této čisterny, kteráž jest na poušti, a nevztahujte ruky na něj. Ale on chtěl vysvoboditi ho z ruky jejich, a pomoci mu, aby se navrátil k otci svému.'),
(1547298,54,1,37,23,'A když přišel Jozef k bratřím svým, strhli s něho sukni jeho, sukni proměnných barev, kterouž měl na sobě.'),
(1547299,54,1,37,24,'A pochopivše, uvrhli jej do čisterny. Čisterna pak ta byla prázdná, v níž nebylo vody.'),
(1547300,54,1,37,25,'I usadili se, aby jedli chléb. A pozdvihše očí svých, uzřeli, a aj, množství Izmaelitských přicházejících z Galád, kteřížto na velbloudích svých nesli vonné věci a kadidlo a mirru do Egypta.'),
(1547301,54,1,37,26,'I řekl Juda bratřím svým: Jaký zisk míti budeme, zabijeme-li bratra svého, a zatajíme-li krve jeho?'),
(1547302,54,1,37,27,'Poďte, prodejme ho Izmaelitským, a nevztahujme na něj rukou svých, nebo bratr náš, tělo naše jest. I uposlechli ho bratří jeho.'),
(1547303,54,1,37,28,'Když pak mimo ně jeli muži ti, kupci Madianští, vytáhli a vyvedli Jozefa z té čisterny, a prodali jej Izmaelitským za dvadceti stříbrných. Ti zavedli Jozefa do Egypta.'),
(1547304,54,1,37,29,'A navrátil se Ruben k čisterně, a aj, již nebylo Jozefa v ní. I roztrhl roucha svá.'),
(1547305,54,1,37,30,'A navrátiv se k bratřím svým, řekl: Pacholete není, a já kam se mám podíti?'),
(1547306,54,1,37,31,'Tedy vzali sukni Jozefovu, a zabivše kozla, smočili sukni tu ve krvi.'),
(1547307,54,1,37,32,'A poslali sukni tu proměnných barev, a dali ji donésti k otci svému, aby řekli: Tuto jsme nalezli; pohleď nyní, jest-li sukně syna tvého, či není?'),
(1547308,54,1,37,33,'A on poznav ji, řekl: Sukně syna mého jest; zvěř lítá sežrala jej, konečně roztrhán jest Jozef.'),
(1547309,54,1,37,34,'I roztrhl Jákob roucha svá, a vloživ žíni na bedra svá, zámutek nesl po synu svém za mnoho dní.'),
(1547310,54,1,37,35,'Sešli se pak všickni synové jeho, a všecky dcery jeho, aby ho těšili. Ale on nedal se potěšiti, a řekl: Nýbrž já tak v zámutku sstoupím za synem svým do hrobu. A plakal ho otec jeho.'),
(1547311,54,1,37,36,'Mezi tím Madianští prodali Jozefa do Egypta Putifarovi, dvořeninu Faraonovu, hejtmanu žoldnéřů.'),
(1547312,54,1,38,1,'Stalo se pak v ten čas, že sstupuje Juda od bratří svých, uchýlil se k muži Odolamitskému, jehož jméno bylo Híra.'),
(1547313,54,1,38,2,'I uzřel tam Juda dceru muže Kananejského, kterýž sloul Sua; a pojav ji, všel k ní.'),
(1547314,54,1,38,3,'Kterážto počala a porodila syna; i nazval jméno jeho Her.'),
(1547315,54,1,38,4,'A počavši opět, porodila syna; a nazvala jméno jeho Onan.'),
(1547316,54,1,38,5,'Porodila pak ještě syna, jehož jméno nazvala Séla. A byl Juda v Chezib, když ona jej porodila.'),
(1547317,54,1,38,6,'I dal Juda Herovi prvorozenému svému manželku, jménem Támar.'),
(1547318,54,1,38,7,'A byl Her, prvorozený Judův, zlý před očima Hospodina; i zabil jej Hospodin.'),
(1547319,54,1,38,8,'Tedy řekl Juda Onanovi: Vejdi k ženě bratra svého, a podlé příbuznosti pojmi ji, abys vzbudil símě bratru svému.'),
(1547320,54,1,38,9,'Věděl pak Onan, že to símě nebude jeho. Protož kdykoli vcházel k ženě bratra svého, vypouštěl símě na zem, aby nezplodil synů bratru svému.'),
(1547321,54,1,38,10,'I nelíbilo se Hospodinu to, co dělal Onan; protož ho také zabil.'),
(1547322,54,1,38,11,'Tedy řekl Juda k Támar nevěstě své: Pobuď v domě otce svého vdovou, dokudž nedoroste Séla, syn můj. (Nebo řekl: Aby on také neumřel, jako i bratří jeho.) I odešla Támar, a bydlila v domě otce svého.'),
(1547323,54,1,38,12,'A po mnohých dnech umřela dcera Suova, manželka Judova. Kterýžto potěšiv se zas, šel do Tamnas k těm, kteříž střihli ovce jeho, a s ním Híra Odolamitský, přítel jeho.'),
(1547324,54,1,38,13,'I oznámeno jest Támar těmito slovy: Aj, tchán tvůj vstupuje do Tamnas, aby střihl ovce své.'),
(1547325,54,1,38,14,'Tedy ona složivši s sebe šaty své vdovské, zavila se v rouchu, a oděla se a seděla na rozcestí, kudy se jde do Tamnas. Nebo viděla, že Séla dorostl, a že není dána jemu za manželku.'),
(1547326,54,1,38,15,'Kteroužto uzřev Juda, za to měl, že jest nevěstka; nebo zakryla tvář svou.'),
(1547327,54,1,38,16,'Protož uchýliv se k ní s cesty, řekl: Dopusť medle, ať vejdu k tobě. (Nebo nevěděl, aby nevěsta jeho byla.) I řekla: Co mi dáš, jestliže vejdeš ke mně?'),
(1547328,54,1,38,17,'Odpověděl: Pošliť kozelce z stáda. Dí ona: Kdybys něco zastavil, dokavadž nepošleš.'),
(1547329,54,1,38,18,'I řekl: Cožť mám dáti v zástavě? Odpověděla ona: Pečetní prsten svůj, a halži svou, a hůl svou, kterouž máš v ruce své. I dal jí, a všel k ní; a počala z něho.'),
(1547330,54,1,38,19,'Tedy vstavši, odešla, a sňavši rouchu svou s sebe, oblékla se v šaty své vdovské.'),
(1547331,54,1,38,20,'I poslal Juda kozelce po příteli svém Odolamitském, aby vzal zase základ od ženy. A nenalezl jí.'),
(1547332,54,1,38,21,'I ptal se mužů toho místa, řka: Kde jest ta nevěstka, kteráž seděla na rozcestí této cesty? Řekli oni: Nebylotě zde nevěstky.'),
(1547333,54,1,38,22,'Tedy navrátiv se k Judovi, řekl: Nenašel jsem jí; a také muži místa toho pravili: Nebylo zde nevěstky.'),
(1547334,54,1,38,23,'I řekl Juda: Nechť sobě to má, abychom neuvedli se v lehkost. Jáť jsem poslal toho kozelce, ale tys jí nenalezl.'),
(1547335,54,1,38,24,'I stalo se okolo tří měsíců, že oznámili Judovi, řkouce: Dopustila se smilství Támar nevěsta tvá, a jest již i těhotná z smilství. I řekl Juda: Vyveďte ji, aby byla upálena.'),
(1547336,54,1,38,25,'Když pak vedena byla, poslala k tchánu svému, řkuci: Z muže, jehož tyto věci jsou, těhotná jsem. A při tom řekla: Pohleď, prosím, čí jsou tyto věci, pečetní prsten, halže a hůl tato?'),
(1547337,54,1,38,26,'Tedy pohleděv na to Juda, řekl: Spravedlivějšíť jest než já, poněvadž jsem nedal jí Sélovi synu svému. A více jí nepoznával.'),
(1547338,54,1,38,27,'Stalo se pak, že když přišel čas porodu jejího, aj, bliženci v životě jejím.'),
(1547339,54,1,38,28,'A když rodila, jeden z nich vyskytl ruku, kteroužto chytivši baba, uvázala na ni červenou nitku, řkuci: Ten vyjde prvé.'),
(1547340,54,1,38,29,'Když pak vtáhl ruku svou zase, hle, vyšel bratr jeho. I řekla: Jak jsi protrhl? Tvéť jest protržení. I nazváno jest jméno jeho Fáres.'),
(1547341,54,1,38,30,'A potom vyšel bratr jeho, kterýž měl na ruce nitku červenou. I nazváno jest jméno jeho Zára.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547342,54,1,39,1,'Jozef pak doveden byl do Egypta; a koupil ho Putifar, dvořenin Faraonův, nejvyšší nad drabanty, muž Egyptský, od Izmaelitských, kteříž ho tam dovedli.'),
(1547343,54,1,39,2,'Byl pak Hospodin s Jozefem, a všecko se mu šťastně vedlo, a bydlil v domě pána svého toho Egyptského.'),
(1547344,54,1,39,3,'A viděl pán jeho, že Hospodin byl s ním, a že všecko, což činil, Hospodin k prospěchu přivedl v rukou jeho.'),
(1547345,54,1,39,4,'Tedy nalezl Jozef milost před očima jeho, a sloužil mu. I představil ho domu svému, a všecko, což měl, dal v ruku jeho.'),
(1547346,54,1,39,5,'A hned, jakž ustanovil ho nad domem svým, a nade vším, což měl, požehnal Hospodin domu Egyptského toho pro Jozefa. A bylo požehnání Hospodinovo na všech věcech, kteréž měl doma i na poli.'),
(1547347,54,1,39,6,'Všech tedy věcí, kteréž měl, zanechal v rukou Jozefových; aniž o čem, tak jako on, věděl, jediné o chlebě, kterýž jedl. Byl pak Jozef ušlechtilé postavy a krásného vzezření.'),
(1547348,54,1,39,7,'I stalo se potom, že vzhlédala žena pána jeho očima svýma na Jozefa, a řekla: Spi se mnou.'),
(1547349,54,1,39,8,'Kterýžto odpíraje, řekl ženě pána svého: Aj, pán můj neví tak jako já, co jest v domě, a všecko, což má, dal v ruce mé.'),
(1547350,54,1,39,9,'Není žádného přednějšího nade mne v domě tomto, aniž co vyňal z správy mé, kromě tebe, jelikož jsi ty manželka jeho. Jak bych tedy učinil takovou nešlechetnost, a hřešil i proti Bohu?'),
(1547351,54,1,39,10,'A když mluvila ona Jozefovi den po dni, nepovolil jí, aby spal s ní, ani aby býval s ní.'),
(1547352,54,1,39,11,'Tedy dne jednoho, když přišel do domu k práci své, a nebylo tu žádného z domácích v domě,'),
(1547353,54,1,39,12,'Chytila jej ona za roucho jeho, řkuci: Lež se mnou. On pak nechav roucha svého v rukou jejích, utekl, a vyšel ven.'),
(1547354,54,1,39,13,'A ona viduci, že nechal roucha svého v rukou jejích a vyběhl ven,'),
(1547355,54,1,39,14,'Svolala domácí své, a řekla k nim takto: Pohleďte, přivedl nám muže Hebrejského, kterýž by měl posměch z nás; nebo přišel ke mně, aby ležel se mnou; i křičela jsem hlasem velikým.'),
(1547356,54,1,39,15,'A když uslyšel, že jsem hlasu svého pozdvihla a křičela, nechav roucha svého u mne, utekl a vyšel ven.'),
(1547357,54,1,39,16,'Tedy schovala roucho jeho u sebe, až přišel pán jeho do domu svého.'),
(1547358,54,1,39,17,'K němuž mluvila v tato slova, řkuci: Přišel ke mně služebník ten Hebrejský, kteréhožs přivedl nám, aby mi lehkost učinil.'),
(1547359,54,1,39,18,'A když jsem hlasu svého pozdvihla a křičela, tedy nechal roucha svého u mne, a utekl ven.'),
(1547360,54,1,39,19,'I stalo se, že, když uslyšel pán jeho slova ženy své, kteráž mluvila mu, pravěci: Tak mi učinil služebník tvůj, rozhněval se velmi.'),
(1547361,54,1,39,20,'Protož vzal ho pán jeho, a dal jej do věže žalářné, v to místo, kdež vězňové královští seděli; i byl tam v žaláři.'),
(1547362,54,1,39,21,'Byl pak Hospodin s Jozefem, a naklonil se k němu milosrdenstvím; a dal jemu milost u vládaře nad žalářem.'),
(1547363,54,1,39,22,'I dal vládař žaláře v moc Jozefovi všecky vězně, kteříž byli v věži žalářné; a cožkoli tam činiti měli, on to spravoval.'),
(1547364,54,1,39,23,'Aniž vládař žaláře k čemu dohlídal,což jemu svěřil; proto že Hospodin byl s ním, a což on činil, Hospodin tomu prospěch dával.'),
(1547365,54,1,40,1,'Stalo se potom, že šeňkýř krále Egyptského a pekař provinili proti pánu svému, králi Egyptskému.'),
(1547366,54,1,40,2,'I rozhněval se Farao na oba úředníky své, na vládaře nad šeňkýři, a na vládaře nad pekaři.'),
(1547367,54,1,40,3,'A dal je do vězení v domě nejvyššího nad drabanty, do věže žalářné, v místo, v němž Jozef vězněm byl.'),
(1547368,54,1,40,4,'I postavil jim nejvyšší nad drabanty Jozefa k službě; a byli drahně dní u vězení.'),
(1547369,54,1,40,5,'I měli sen oba dva, každý z nich sen svůj noci jedné, každý podlé vyložení sna svého, šeňkýř i pekař krále Egyptského, kteříž seděli v věži.'),
(1547370,54,1,40,6,'Tedy přišel k nim Jozef ráno, a hleděl na ně; a aj, byli smutní.'),
(1547371,54,1,40,7,'I optal se těch úředníků Faraonových, kteříž s ním byli v vězení v domě pána jeho, řka: Proč jsou dnes tváři vaše smutnější?'),
(1547372,54,1,40,8,'Kteřížto odpověděli jemu: Měli jsme sen, a nemáme, kdo by jej vyložil. I řekl jim Jozef: Zdaliž Boží nejsou výkladové? Pravte mi medle.'),
(1547373,54,1,40,9,'Tedy správce nad šeňkýři vypravoval sen svůj Jozefovi, a řekl jemu: Zdálo se mi ve snách, že jsem viděl před sebou vinný kmen,'),
(1547374,54,1,40,10,'A na tom kmenu tři ratolesti; a ten kmen jako by pupence pouštěl, a vycházel květ jeho, až k sezrání přišli hroznové jeho.'),
(1547375,54,1,40,11,'A já maje koflík Faraonův v ruce své, bral jsem hrozny, a vytlačoval je do koflíka Faraonova, a podával jsem koflíka Faraonovi do rukou.'),
(1547376,54,1,40,12,'I řekl jemu Jozef: Toto jest vyložení jeho: Ti tři révové jsou tři dnové.'),
(1547377,54,1,40,13,'Po třech dnech povýší Farao hlavy tvé, a k úřadu tvému tě navrátí; i budeš podávati koflíka Faraonova do ruky jeho podlé obyčeje prvního, když jsi byl šeňkýřem jeho.'),
(1547378,54,1,40,14,'Ale mějž mne v své paměti, kdyžť se dobře povede; a učiň, prosím, se mnou to milosrdenství, abys zmínku učinil o mně před Faraonem, a vysvobodil mne z domu tohoto.'),
(1547379,54,1,40,15,'Nebo kradmo jsem vzat z země Židovské; a zde jsem ničeho neučinil, pročež by mne do tohoto vězení dali.'),
(1547380,54,1,40,16,'Vida pak správce nad pekaři, že dobře vyložil, řekl Jozefovi: Mně také zdálo se ve snách, ano tři košové pletení na hlavě mé.'),
(1547381,54,1,40,17,'A v koši vrchním byli všelijací pokrmové Faraonovi dílem pekařským strojení, a ptáci jedli je z koše nad hlavou mou.'),
(1547382,54,1,40,18,'I odpověděl Jozef a řekl: Toto jest vyložení jeho: Tři košové jsou tři dnové.'),
(1547383,54,1,40,19,'Po třech dnech odejme tobě Farao hlavu tvou, a oběsí tě na dřevě; i budou jísti ptáci maso tvé s tebe.'),
(1547384,54,1,40,20,'Tedy stalo se v den třetí, v den pamatný narození Faraonova, že učinil hody všechněm služebníkům svým; i počítal hlavu vládaře nad šeňky, i hlavu vládaře nad pekaři, mezi služebníky svými.'),
(1547385,54,1,40,21,'A navrátil nejvyššího nad šeňky k místu jeho, aby podával koflíku Faraonovi do ruky.'),
(1547386,54,1,40,22,'Vládaře pak nad pekaři oběsil, tak jakž jim byl sen vyložil Jozef.'),
(1547387,54,1,40,23,'A nezpomenul správce nad šeňky na Jozefa, ale zapomenul na něj.'),
(1547388,54,1,41,1,'Stalo se pak po dvou letech, měl Farao sen. Zdálo mu se, že stál nad potokem.'),
(1547389,54,1,41,2,'A aj, z toho potoku vycházelo sedm krav, pěkných na pohledění a tlustých, kteréžto pásly se na mokřinách.'),
(1547390,54,1,41,3,'A aj, sedm krav jiných vycházelo za nimi z potoku, šeredných na pohledění a hubených, kteréžto stály podlé oněch krav při břehu potoka.'),
(1547391,54,1,41,4,'A ty krávy na pohledění šeredné a hubené sežraly oněch sedm krav na pohledění pěkných a tlustých. I procítil Farao.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547392,54,1,41,5,'A když usnul zase, zdálo se jemu podruhé. A aj, sedm klasů vyrostlo z stébla jednoho, plných a pěkných.'),
(1547393,54,1,41,6,'A aj, sedm klasů tenkých a východním větrem usvadlých vzcházelo za nimi.'),
(1547394,54,1,41,7,'A ti klasové tencí pohltili sedm oněch klasů zdařilých a plných. I procítiv Farao, a aj, byl sen.'),
(1547395,54,1,41,8,'Když pak bylo ráno, zkormoucena byla mysl jeho; a poslav, svolal všecky hadače Egyptské, a všecky mudrce jejich. I vypravoval jim Farao sny své; a nebylo žádného, kdo by je vyložil Faraonovi.'),
(1547396,54,1,41,9,'Tedy mluvil nejvyšší šeňk Faraonovi takto: Na provinění své rozpomínám se dnes.'),
(1547397,54,1,41,10,'Farao rozhněvav se na služebníky své, dal mne byl do vězení v domě nejvyššího nad drabanty, mne a správce nad pekaři.'),
(1547398,54,1,41,11,'Měli jsme pak sen jedné noci, on i já, jeden každý podlé vyložení snu svého.'),
(1547399,54,1,41,12,'A byl tam s námi mládenec Hebrejský, služebník nejvyššího nad drabanty, jemuž když jsme vypravovali, vykládal nám sny naše; jednomu každému podlé snu jeho vykládal.'),
(1547400,54,1,41,13,'A stalo se, že jakž vykládal nám, tak bylo: Já jsem navrácen k úřadu svému, a on oběšen.'),
(1547401,54,1,41,14,'Tedy poslav Farao, povolal Jozefa, a rychle vypustili ho z žaláře. Kterýžto oholiv se, a změniv roucho své, přišel k Faraonovi.'),
(1547402,54,1,41,15,'I řekl Farao Jozefovi: Měl jsem sen, a není, kdo by jej vyložil; o tobě pak slyšel jsem to, že když uslyšíš sen, umíš jej vyložiti.'),
(1547403,54,1,41,16,'Odpověděl Jozef Faraonovi, řka: Není to má věc; Bůh oznámí šťastné věci Faraonovi.'),
(1547404,54,1,41,17,'Tedy řekl Farao Jozefovi: Zdálo mi se ve snách, že jsem stál na břehu potoka.'),
(1547405,54,1,41,18,'A aj, z potoka toho vystupovalo sedm krav tlustých a pěkných, kteréžto pásly se na mokřinách.'),
(1547406,54,1,41,19,'A aj, sedm jiných krav vystupovalo za nimi churavých a šeredných velmi a hubených; neviděl jsem tak šeredných ve vší zemi Egyptské.'),
(1547407,54,1,41,20,'A sežraly krávy ty hubené a šeredné sedm krav prvnějších tlustých.'),
(1547408,54,1,41,21,'A ač dostaly se do břicha jejich, však nebylo znáti, by se dostaly v střeva jejich; nebo na pohledění byly mrzké, jako i před tím. I procítil jsem.'),
(1547409,54,1,41,22,'Viděl jsem také ve snách, ano sedm klasů vyrostlo z stébla jednoho plných a pěkných.'),
(1547410,54,1,41,23,'A aj, sedm klasů drobných, tenkých a východním větrem usvadlých vycházelo za nimi.'),
(1547411,54,1,41,24,'I pohltili klasové ti drobní sedm klasů pěkných. Což když jsem vypravoval hadačům, nebyl, kdo by mi vyložil.'),
(1547412,54,1,41,25,'Odpověděl Jozef Faraonovi: Sen Faraonův jednostejný jest. Což Bůh činiti bude, to ukázal Faraonovi.'),
(1547413,54,1,41,26,'Sedm krav pěkných jest sedm let, a sedm klasů pěkných tolikéž jest sedm let; sen jest jednostejný.'),
(1547414,54,1,41,27,'Sedm pak hubených krav a šeredných, vystupujících za nimi, sedm let jest; a sedm klasů drobných a větrem východním usvadlých bude sedm let hladu.'),
(1547415,54,1,41,28,'Toť jest, což jsem mluvil Faraonovi: Což Bůh činiti bude, ukazuje Faraonovi.'),
(1547416,54,1,41,29,'Aj, sedm let nastane, v nichž hojnost veliká bude ve vší zemi Egyptské.'),
(1547417,54,1,41,30,'A po nich nastane sedm let hladu,v nichž v zapomenutí přijde všecka ta hojnost v zemi Egyptské; a zhubí hlad zemi.'),
(1547418,54,1,41,31,'Aniž poznána bude hojnost ta v zemi, pro hlad, kterýž přijde potom; nebo velmi veliký bude.'),
(1547419,54,1,41,32,'Že pak opětován jest sen Faraonovi podvakrát, znamená, že jistá věc jest od Boha, a že tím spíše Bůh vykoná to.'),
(1547420,54,1,41,33,'Protož nyní ať vyhledá Farao muže opatrného a moudrého, kteréhož by ustanovil nad zemí Egyptskou.'),
(1547421,54,1,41,34,'To ať učiní Farao, a postaví úředníky nad zemí, a béře pátý díl z úrod země Egyptské, po sedm let hojných.'),
(1547422,54,1,41,35,'Ať shromáždí všeliké potravy těch úrodných let nastávajících, a sklidí obilí k ruce Faraonovi; a potravy v městech ať se chovají pilně.'),
(1547423,54,1,41,36,'A budou pokrmové ti za poklad zemi této k sedmi letům hladu, kteráž budou v zemi Egyptské, aby nebyla zkažena země tato hladem.'),
(1547424,54,1,41,37,'I líbila se řeč ta Faraonovi i všechněm služebníkům jeho.'),
(1547425,54,1,41,38,'Tedy řekl Farao služebníkům svým: Najdeme-liž podobného tomuto muži, v němž by byl Duch Boží?'),
(1547426,54,1,41,39,'Jozefovi pak řekl: Poněvadž Bůh dal znáti tobě všecko toto, neníť žádného tak rozumného a moudrého, jako ty jsi.'),
(1547427,54,1,41,40,'Ty budeš nad domem mým, a líbati bude tvář tvou všecken lid můj; stolicí toliko královskou vyšší nad tebe budu.'),
(1547428,54,1,41,41,'Řekl také Farao Jozefovi: Aj, ustanovil jsem tě nade vší zemi Egyptskou.'),
(1547429,54,1,41,42,'A sňav Farao prsten svůj s ruky své, dal jej na ruku Jozefovu, a oblékl ho v roucho kmentové, a vložil zlatý řetěz na hrdlo jeho.'),
(1547430,54,1,41,43,'A dal ho voziti na svém druhém voze, a volali před ním: Klanějte se! I ustanovil ho nade vší zemi Egyptskou.'),
(1547431,54,1,41,44,'A řekl Farao Jozefovi: Já jsem Farao, a bez dopuštění tvého nepozdvihne žádný ruky své ani nohy své ve vší zemi Egyptské.'),
(1547432,54,1,41,45,'A dal Farao jméno Jozefovi Safenat Paneach, a dal mu Asenat dceru Putifera, knížete On, za manželku. I vyšel Jozef na zemi Egyptskou.'),
(1547433,54,1,41,46,'(Jozef pak byl ve třidcíti letech, když stál před Faraonem králem Egyptským.) A vyšed od tváři Faraonovy, projel všecku zemi Egyptskou.'),
(1547434,54,1,41,47,'A vydala země po sedm let úrodných obilí hojnost.'),
(1547435,54,1,41,48,'I nahromáždil všelijakých potrav v těch sedmi letech hojných v zemi Egyptské, a složil potravu tu v městech; úrody polní jednoho každého města, kteréž byly okolo něho, složil v něm.'),
(1547436,54,1,41,49,'A tak nahromáždil Jozef obilí velmi mnoho, jako jest písku mořského, tak že přestali počítati; nebo mu nebylo počtu.'),
(1547437,54,1,41,50,'Jozefovi pak narodili se dva synové, prvé než přišel rok hladu, kteréž mu porodila Asenat, dcera Putifera, knížete On.'),
(1547438,54,1,41,51,'A nazval Jozef jméno prvorozeného Manasses, řka: Nebo způsobil to Bůh, abych zapomenul na všecky práce své, a na všecken dům otce svého.'),
(1547439,54,1,41,52,'Jméno pak druhého nazval Efraim, řka: Nebo dal mi Bůh zrůst v zemi trápení mého.'),
(1547440,54,1,41,53,'Tedy pominulo sedm let hojných v zemi Egyptské;'),
(1547441,54,1,41,54,'A počalo sedm let hladu přicházeti, jakž byl předpověděl Jozef. I byl hlad po všech krajinách, ale po vší zemi Egyptské byl chléb.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547442,54,1,41,55,'Potom také nedostatek trpěla všecka země Egyptská, a volal lid k Faraonovi o chléb. I řekl Farao všechněm Egyptským: Jděte k Jozefovi, což vám rozkáže, učiníte.'),
(1547443,54,1,41,56,'A byl hlad na tváři vší země. Tedy otevřel Jozef všecky obilnice, v nichž obilí bylo, a prodával Egyptským; nebo rozmohl se hlad v zemi Egyptské.'),
(1547444,54,1,41,57,'A všickni obyvatelé země přicházeli do Egypta k Jozefovi, aby kupovali; nebo rozmohl se byl hlad po vší zemi.'),
(1547445,54,1,42,1,'Vida pak Jákob, že by potrava byla v Egyptě, řekl synům svým: Co hledíte jeden na druhého?'),
(1547446,54,1,42,2,'I mluvil jim: Aj, slyšel jsem, že mají potravu v Egyptě; jděte tam, a kupte nám odtud, abychom živi byli a nezemřeli.'),
(1547447,54,1,42,3,'Tedy šlo deset bratrů Jozefových, aby nakoupili obilí v Egyptě.'),
(1547448,54,1,42,4,'Ale Beniamina, bratra Jozefova, neposlal Jákob s bratřími jeho, nebo řekl: Aby se mu tam něco zlého nepřihodilo.'),
(1547449,54,1,42,5,'I šli synové Izraelovi spolu s jinými, aby kupovali; nebo byl hlad v zemi Kananejské.'),
(1547450,54,1,42,6,'Jozef pak byl nejvyšší správce v zemi té; on prodával obilí všemu lidu země. Tedy přišli bratří Jozefovi, a skláněli se před ním tváří až k zemi.'),
(1547451,54,1,42,7,'A uzřev Jozef bratří své, poznal je; a ukázal se k nim jako cizí, a tvrdě mluvil k nim,řka jim: Odkud jste přišli? I odpověděli: Z země Kananejské, abychom nakoupili potrav.'),
(1547452,54,1,42,8,'Poznal, pravím, Jozef bratří své, ale oni nepoznali ho.'),
(1547453,54,1,42,9,'Tedy zpomenul Jozef na sny, kteréž měl o nich, a řekl jim: Špehéři jste, a přišli jste, abyste shlédli nepevná místa země.'),
(1547454,54,1,42,10,'Kteřížto odpověděli jemu: Nikoli, pane můj, ale služebníci tvoji přišli, aby nakoupili pokrmů.'),
(1547455,54,1,42,11,'Všickni my synové jednoho muže jsme, upřímí jsme; nikdyť jsou nebyli služebníci tvoji špehéři.'),
(1547456,54,1,42,12,'Jimž zase řekl: Není tak, ale přišli jste, abyste shlédli nepevná místa země.'),
(1547457,54,1,42,13,'Odpověděli oni: Dvanácte nás bratří služebníků tvých bylo, synů muže jednoho v zemi Kananejské; a aj, nejmladší s otcem naším nyní jest doma, a jednoho není.'),
(1547458,54,1,42,14,'I řekl jim Jozef: Toť jest, což jsem mluvil vám, když jsem řekl: Špehéři jste.'),
(1547459,54,1,42,15,'Touto věcí zkušeni budete: Živť jest Farao, že nevyjdete odsud, až přijde sem bratr váš mladší.'),
(1547460,54,1,42,16,'Vyšlete z sebe jednoho, ať vezma, přivede bratra vašeho; vy pak u vězení zůstaňte, a zkušena budou vaše slova, pravdu-li jste mluvili. Pakli nic, živť jest Farao, že jste špehéři.'),
(1547461,54,1,42,17,'Tedy dal je všecky spolu do vězení za tři dni.'),
(1547462,54,1,42,18,'Třetího pak dne řekl jim Jozef: Toto učiňte, abyste živi byli; neboť já se bojím Boha.'),
(1547463,54,1,42,19,'Jste-li šlechetní muži, jeden bratr váš ať jest ukován v žaláři, v němž jste byli; vy pak jděte, a odneste obilí k zapuzení hladu domů vašich.'),
(1547464,54,1,42,20,'Bratra pak svého mladšího přivedete ke mně; a pravdomluvná prokázána budou vaše slova, a nezemřete. Tedy učinili tak.'),
(1547465,54,1,42,21,'I mluvil jeden k druhému: Jistě provinili jsme proti bratru svému. Nebo viděli jsme ssoužení duše jeho, když nás pokorně prosil, a nevyslyšeli jsme ho; protož přišlo na nás ssoužení toto.'),
(1547466,54,1,42,22,'Odpověděl pak jim Ruben, řka: Zdaliž jsem tehdy vám nepravil těmito slovy: Nehřešte proti pacholeti. Ale neposlechli jste; pročež také krve jeho, hle, vyhledává se.'),
(1547467,54,1,42,23,'A nevěděli oni, že by rozuměl Jozef; nebo skrze tlumače mluvil jim.'),
(1547468,54,1,42,24,'A odvrátiv se od nich, plakal. Potom navrátiv se k nim, mluvil s nimi, a vzav Simeona z nich, svázal ho před očima jejich.'),
(1547469,54,1,42,25,'Přikázal pak Jozef, aby naplněni byli pytlové jejich obilím, a navráceny peníze jejich jednomu každému do pytle jeho, a aby dána jim byla potrava na cestu. I stalo se tak.'),
(1547470,54,1,42,26,'A vloživše obilí svá na osly své, odešli odtud.'),
(1547471,54,1,42,27,'A rozvázav jeden z nich pytel svůj, aby dal obrok oslu svému v hospodě, uzřel peníze své, kteréž byly na vrchu v pytli jeho.'),
(1547472,54,1,42,28,'I řekl bratřím svým: Navráceny jsou mi peníze mé, a aj, jsou v pytli mém. Tedy užasli se, a předěšeni jsouce, mluvili jeden k druhému: Což nám to učinil Bůh?'),
(1547473,54,1,42,29,'Navrátivše se pak k Jákobovi otci svému do země Kananejské, vypravovali jemu všecko, co se jim přihodilo, pravíce:'),
(1547474,54,1,42,30,'Muž ten, pán země, mluvil k nám tvrdě, a dal nás do vězení, jako špehéře země.'),
(1547475,54,1,42,31,'A řekli jsme jemu: Upřímí jsme, nikdy jsme nebyli špehéři.'),
(1547476,54,1,42,32,'Dvanácte bylo nás bratří, synů otce našeho, z nichž jednoho není, a mladší nyní jest s otcem naším v zemi Kananejské.'),
(1547477,54,1,42,33,'I řekl nám muž ten, pán země té: Po tomto poznám, že upřímí jste: Bratra vašeho jednoho zanechte u mne, a obilí k zapuzení hladu od domů vašich vezmouce, odejděte.'),
(1547478,54,1,42,34,'A přiveďte bratra svého mladšího ke mně, abych poznal, že nejste špehéři, ale upřímí; tehdy bratra vašeho vrátím vám, a budete moci v zemi této obchod vésti.'),
(1547479,54,1,42,35,'I stalo se, že, když vyprazdňovali pytle své, a aj, jeden každý měl uzlík peněz svých v pytli svém. Vidouce pak oni i otec jejich uzlíky peněz svých, báli se.'),
(1547480,54,1,42,36,'I řekl jim Jákob otec jejich: Mne jste zbavili synů: Jozefa není, Simeona nemám, a Beniamina vezmete. Na mneť jsou se tyto všecky věci svalily.'),
(1547481,54,1,42,37,'Tedy řekl Ruben otci svému těmito slovy: Dva syny mé zabí, jestliže ho nepřivedu zase k tobě; poruč ho v ruce mé, a já zase přivedu ho k tobě.'),
(1547482,54,1,42,38,'I řekl: Nesstoupíť syn můj s vámi. Nebo bratr jeho umřel, a on sám pozůstal; a přihodilo-li by se mu co zlého na té cestě, kterouž půjdete, uvedli byste šediny mé s bolestí do hrobu.'),
(1547483,54,1,43,1,'Byl pak hlad veliký v krajině té.'),
(1547484,54,1,43,2,'I stalo se, když vytrávili obilí, kteréž přinesli z Egypta, že řekl k nim otec jejich: Jděte zase, a nakupte nám něco potravy.'),
(1547485,54,1,43,3,'I mluvil k němu Juda těmito slovy: Velice se zařekl muž ten, řka: Neuzříte tváři mé, nebude-li bratr váš s vámi.'),
(1547486,54,1,43,4,'Jestliže pošleš bratra našeho s námi, půjdeme a nakoupíme tobě potravy;'),
(1547487,54,1,43,5,'Pakli nepošleš, nepůjdeme. Nebo pověděl nám muž ten: Neuzříte tváři mé, nebude-li bratr váš s vámi.'),
(1547488,54,1,43,6,'I řekl Izrael: Proč jste mi tak zle učinili, oznámivše muži tomu, že máte ještě bratra?'),
(1547489,54,1,43,7,'Odpověděli: Pilně vyptával se muž ten na nás, i na rod náš, mluvě: Jest-li živ ještě otec váš? Máte-li bratra? A dali jsme mu zprávu na ta slova. Zdaž jsme to jak věděti mohli, že dí: Přiveďte bratra svého?'),
(1547490,54,1,43,8,'I řekl Juda Izraelovi, otci svému: Pošli to pachole se mnou, a vstanouce, půjdeme, abychom živi byli, a nezemřeli, i my, i ty, i maličcí naši.'),
(1547491,54,1,43,9,'Já slibuji za něj; z ruky mé vyhledávej ho. Jestliže nepřivedu ho k tobě, a nepostavím ho před tebou, vinen budu hříchem tobě po všecky dny.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547492,54,1,43,10,'A kdybychom byli neprodlévali, jistě již bychom se byli dvakrát vrátili.'),
(1547493,54,1,43,11,'I řekl jim Izrael otec jejich: Jestližeť tak býti musí, učiňtež toto: Nabeřte nejvzácnějších užitků země do nádob svých, a doneste muži tomu dar, něco kadidla, a trochu strdi, a vonných věcí a mirry, daktylů a mandlů.'),
(1547494,54,1,43,12,'Peníze také dvoje vezměte v ruce své, a peníze vložené na vrch do pytlů vašich zase doneste v rukou svých; snad z omýlení to přišlo.'),
(1547495,54,1,43,13,'Bratra svého také vezměte, a vstanouce, jděte zase k muži tomu.'),
(1547496,54,1,43,14,'A Bůh silný všemohoucí dejž vám najíti milost před mužem tím, ať propustí vám onoho bratra vašeho i tohoto Beniamina. Jáť pak zbaven jsa synů, jako osiřelý budu.'),
(1547497,54,1,43,15,'Tedy vzali muži ti dar ten, a dvoje peníze vzali v ruce své, a Beniamina; a vstavše, sstoupili do Egypta, a postavili se před Jozefem.'),
(1547498,54,1,43,16,'Vida pak Jozef Beniamina s nimi, řekl tomu, kterýž spravoval dům jeho: Uveď tyto muže do domu, a zabí hovado a připrav; nebo se mnou jísti budou muži ti o poledni.'),
(1547499,54,1,43,17,'I učinil muž ten, jakž rozkázal Jozef, a uvedl ty lidi do domu Jozefova.'),
(1547500,54,1,43,18,'Báli se pak muži ti, když uvedeni byli do domu Jozefova, a řekli: Pro ty peníze, kteréž prvé vloženy byly do pytlů našich, sem uvedeni jsme, aby obvině, obořil se na nás, a vzal nás za služebníky i osly naše.'),
(1547501,54,1,43,19,'A přistoupivše k muži tomu, kterýž spravoval v domě Jozefově, mluvili k němu ve dveřích domu,'),
(1547502,54,1,43,20,'A řekli: Slyš mne, pane můj. Přišli jsme byli ponejprvé kupovati potrav.'),
(1547503,54,1,43,21,'I přihodilo se, když jsme do hospody přišli, a rozvazovali pytle své, a aj, peníze jednoho každého byly svrchu v pytli jeho, peníze naše podlé váhy své; a přinesli jsme je zase v rukou svých.'),
(1547504,54,1,43,22,'Jiné také peníze přinesli jsme v rukou svých, abychom nakoupili potravy; nevíme, kdo jest zase vložil peníze naše do pytlů našich.'),
(1547505,54,1,43,23,'A on odpověděl: Mějte o to pokoj, nebojte se. Bůh váš, a Bůh otce vašeho dal vám poklad do pytlů vašich; penízeť jsem vaše já přijal. I vyvedl k nim Simeona.'),
(1547506,54,1,43,24,'Uved tedy muž ten lidi ty do domu Jozefova, dal jim vody, aby umyli nohy své, dal také obrok oslům jejich.'),
(1547507,54,1,43,25,'Mezi tím připravili dar ten, dokudž nepřišel Jozef v poledne; nebo slyšeli, že by tu měli jísti chléb.'),
(1547508,54,1,43,26,'Tedy přišel Jozef domů. I přinesli mu dar, kterýž měli v rukou svých, a klaněli se jemu až k zemi.'),
(1547509,54,1,43,27,'I ptal se jich, jak se mají, a řekl: Zdráv-liž jest otec váš starý, o němž jste pravili? Živ-li jest ještě?'),
(1547510,54,1,43,28,'Kteřížto odpověděli: Zdráv jest služebník tvůj otec náš, a ještě živ jest. A sklánějíce hlavy, poklonu mu činili.'),
(1547511,54,1,43,29,'Pozdvih pak očí svých, viděl Beniamina bratra svého, syna matky své, a řekl: Tento-li jest bratr váš mladší, o němž jste mi pravili? I řekl: Učiniž Bůh milost s tebou, synu můj!'),
(1547512,54,1,43,30,'Tedy pospíšil Jozef, (nebo pohnula se střeva jeho nad bratrem jeho,) a hledal, kde by mohl plakati; a všed do pokoje, plakal tam.'),
(1547513,54,1,43,31,'Potom umyv tvář svou, vyšel zase, a zdržoval se, a řekl: Klaďte chléb.'),
(1547514,54,1,43,32,'I kladli jemu zvláště, a jim obzvláště, Egyptským také, kteříž s ním jídali, obzvláštně; nebo nemohou Egyptští jísti s Židy chleba, proto že to ohavnost jest Egyptským.'),
(1547515,54,1,43,33,'Tedy seděli proti němu, prvorozený podlé prvorozenství svého, a mladší podlé mladšího věku svého. I divili se muži ti vespolek.'),
(1547516,54,1,43,34,'A bera jídlo před sebou, podával jim; Beniaminovi pak dostalo se pětkrát více než jiným. I hodovali a hojně se s ním napili.'),
(1547517,54,1,44,1,'Rozkázal pak tomu, kterýž spravoval dům jeho, řka: Naplň pytle mužů těch potravou, co by jen unésti mohli; a peníze každého polož zas do pytle jeho na vrch.'),
(1547518,54,1,44,2,'A koflík můj, koflík stříbrný, vlož na vrch do pytle mladšího s penězi jeho za obilí. I učinil podlé řeči Jozefovy, kterouž mluvil.'),
(1547519,54,1,44,3,'Ráno pak propuštěni jsou ti muži, oni i oslové jejich.'),
(1547520,54,1,44,4,'A když vyšli z města, a nedaleko ještě byli, řekl Jozef správci domu svého: Vstaň, hoň muže ty, a dohoně se jich, mluv k nim: Pročež jste se odplatili zlým za dobré?'),
(1547521,54,1,44,5,'Zdaliž to není ten koflík, z kteréhož píjí pán můj? A z tohoť on jistým zkušením pozná, jací jste vy. Zle jste učinili, co jste učinili.'),
(1547522,54,1,44,6,'Tedy dohoniv se jich, mluvil jim slova ta.'),
(1547523,54,1,44,7,'Kteřížto odpověděli jemu: Proč mluví pán můj taková slova? Odstup od služebníků tvých, aby co takového učinili.'),
(1547524,54,1,44,8,'A my ty peníze, kteréž jsme našli na vrchu v pytlích svých, přinesli jsme tobě zase z země Kananejské; jakž bychom tedy krásti měli z domu pána tvého stříbro neb zlato?'),
(1547525,54,1,44,9,'U koho z služebníků tvých nalezeno bude, nechžť umře ten; a my také budeme pána tvého služebníci.'),
(1547526,54,1,44,10,'I řekl: Nu dobře, nechť jest podlé řeči vaší. U koho se nalezne, ten bude mým služebníkem, a vy budete bez viny.'),
(1547527,54,1,44,11,'Protož rychle každý složil pytel svůj na zem, a rozvázal každý pytel svůj.'),
(1547528,54,1,44,12,'I přehledával, od staršího počal, a na mladším přestal; i nalezen jest koflík v pytli Beniaminovu.'),
(1547529,54,1,44,13,'Tedy oni roztrhše roucha svá, vložil každý břímě na osla svého, a vrátili se do města.'),
(1547530,54,1,44,14,'I přišel Juda s bratřími svými do domu Jozefova, (on pak ještě tam byl,) a padli před ním na zemi.'),
(1547531,54,1,44,15,'I dí jim Jozef: Jakýž jest to skutek, který jste učinili? Zdaž nevíte, že takový muž, jako jsem já, umí poznati?'),
(1547532,54,1,44,16,'Tedy řekl Juda: Což díme pánu svému? co mluviti budeme? a čím se ospravedlníme? Bůhť jest našel nepravost služebníků tvých. Aj, služebníci jsme pána svého, i my i ten, u něhož nalezen jest koflík.'),
(1547533,54,1,44,17,'Odpověděl Jozef: Odstup ode mne, abych to učinil. Muž, u něhož nalezen jest koflík, ten bude mým služebníkem; vy pak jděte u pokoji k otci svému.'),
(1547534,54,1,44,18,'I přistoupil k němu Juda a řekl: Slyš mne, pane můj. Prosím, nechažť promluví služebník tvůj slovo v uši pána svého, a nehněvej se na služebníka svého; nebo jsi ty jako sám Farao.'),
(1547535,54,1,44,19,'Pán můj ptal se služebníků svých, řka: Máte-li otce, neb bratra?'),
(1547536,54,1,44,20,'A odpověděli jsme pánu mému: Máme otce starého, a pachole v starosti jeho zplozené malé, jehož bratr umřel, a on sám pozůstal po mateři své, a otec jeho miluje jej.'),
(1547537,54,1,44,21,'I řekl jsi služebníkům svým: Přiveďte ho ke mně, a pohledím na něj.'),
(1547538,54,1,44,22,'A řekli jsme pánu mému: Nemůžeť pachole opustiti otce svého; nebo opustí-li otce svého, on umře.'),
(1547539,54,1,44,23,'Ty pak řekl jsi služebníkům svým: Nepřijde-li bratr váš mladší s vámi, nepokoušejte se více viděti tváři mé.'),
(1547540,54,1,44,24,'I stalo se, když jsme se vrátili k služebníku tvému, otci mému, a jemu vypravovali slova pána svého,'),
(1547541,54,1,44,25,'Že řekl otec náš: Jděte zase, nakupte nám něco potravy.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547542,54,1,44,26,'Odpověděli jsme: Nemůžeme jíti,než bude-li bratr náš mladší s námi, tedy půjdeme; nebo bychom nemohli viděti tváři toho muže, nebyl-li by bratr náš nejmladší s námi.'),
(1547543,54,1,44,27,'I řekl nám služebník tvůj, otec můj: Vy víte, že dva toliko syny porodila mi žena má.'),
(1547544,54,1,44,28,'A vyšel jeden ode mne, o němž jsem pravil: Jistě roztrhán jest, a neviděl jsem ho dosavad.'),
(1547545,54,1,44,29,'Vezmete-li i tohoto ode mne, a přišlo by na něj něco zlého, tedy uvedete šediny mé s trápením do hrobu.'),
(1547546,54,1,44,30,'Tak tedy, když přijdu k služebníku tvému, otci svému, a pacholete nebude s námi, (ješto duše jeho spojena jest s duší tohoto):'),
(1547547,54,1,44,31,'Přijde na to, když uzří, že pacholete není, umře; a uvedou služebníci tvoji šediny služebníka tvého, otce svého, s žalostí do hrobu.'),
(1547548,54,1,44,32,'Nebo služebník tvůj slíbil za pachole, abych je vzal od otce svého, řka: Jestliže ho nepřivedu zase k tobě, tedy vinen budu hříchem otci mému po všecky dny.'),
(1547549,54,1,44,33,'Protož nyní nechť zůstane, prosím, služebník tvůj místo pacholete tohoto za služebníka pánu svému, a pachole ať vstoupí s bratry svými.'),
(1547550,54,1,44,34,'Nebo jak bych já vstoupil k otci svému, kdyby tohoto pacholete nebylo se mnou? Leč bych chtěl viděti trápení, kteréž by přišlo na otce mého.'),
(1547551,54,1,45,1,'Jozef pak nemoha se déle zdržeti, přede všemi přístojícími zvolal: Kažte všechněm ven! I nezůstal žádný s nimi, když se známil Jozef s bratřími svými.'),
(1547552,54,1,45,2,'Potom pozdvihl hlasu svého s pláčem; a slyšeli to Egyptští, slyšel také dům Faraonův.'),
(1547553,54,1,45,3,'I řekl Jozef bratřím svým: Já jsem Jozef. Ještě-li jest živ otec můj? A nemohli mu odpovědíti bratří jeho; nebo se ho velmi ulekli.'),
(1547554,54,1,45,4,'Tedy řekl Jozef bratřím svým: Přistuptež medle ke mně. I přistoupili. A řekl: Já jsem Jozef bratr váš, kteréhož jste prodali do Egypta.'),
(1547555,54,1,45,5,'Protož nyní nermuťte se, a neztěžujte sobě toho, že jste mne sem prodali; nebo pro zachování života vašeho poslal mne Bůh před vámi.'),
(1547556,54,1,45,6,'Nebo dvě létě již hlad jest v zemi, a ještě pět let přijde, v nichž nebudou orati, ani žíti.'),
(1547557,54,1,45,7,'Poslal mne, pravím, Bůh před vámi, pro zachování vás ostatků na zemi, a pro zachování životů vašich vysvobozením velikým.'),
(1547558,54,1,45,8,'Tak tedy ne vy jste mne poslali sem, ale Bůh, kterýž mne dal za otce Faraonovi, a za pána všemu domu jeho, a panovníka po vší zemi Egyptské.'),
(1547559,54,1,45,9,'Pospěšte a vstupte k otci mému, a rcete jemu: Toto praví syn tvůj Jozef: Učinil mne Bůh pánem všeho Egypta; přijdiž ke mně, neprodlévej.'),
(1547560,54,1,45,10,'A bydliti budeš v zemi Gesen; a budeš blízko mne, ty i synové tvoji, i vnukové tvoji, stáda tvá, a volové tvoji, a cožkoli máš.'),
(1547561,54,1,45,11,'A budu tě chovati tam, (nebo ještě pět let hlad bude), abys snad pro hlad nezahynul, ty i dům tvůj, a cožkoli máš.'),
(1547562,54,1,45,12,'A aj, oči vaše vidí, i oči bratra mého Beniamina, že ústa má mluví vám.'),
(1547563,54,1,45,13,'Povíte také otci mému o vší slávě mé v Egyptě, a což jste koli viděli; pospěštež tedy, a přiveďte otce mého sem.'),
(1547564,54,1,45,14,'Tedy padl na šíji Beniamina bratra svého, a plakal; Beniamin také plakal na šíji jeho.'),
(1547565,54,1,45,15,'A políbiv všech bratří svých, plakal nad nimi; a potom mluvili bratří jeho s ním.'),
(1547566,54,1,45,16,'Slyšána pak jest v domě Faraonově pověst tato: Přišli bratří Jozefovi. I bylo to velmi vděčné Faraonovi i všechněm služebníkům jeho.'),
(1547567,54,1,45,17,'A řekl Farao Jozefovi: Rci bratřím svým: Toto učiňte: Naložíce na hovada svá, jděte, a navraťte se do země Kananejské.'),
(1547568,54,1,45,18,'A vezmouce otce svého a čeládky své, přiďte ke mně, a dám vám dobré místo v zemi Egyptské, a jísti budete tuk země této.'),
(1547569,54,1,45,19,'Ty pak rozkaž jim: Toto učiňte: Vezměte sobě z země Egyptské vozy pro děti a ženy své, a vezměte otce svého, a přiďte.'),
(1547570,54,1,45,20,'Aniž se ohlédejte na nábytky své; nebo nejlepší místo ve vší zemi Egyptské vaše bude.'),
(1547571,54,1,45,21,'I učinili tak synové Izraelovi. A dal jim Jozef vozy podlé rozkázaní Faraonova; dal také jim pokrmy na cestu.'),
(1547572,54,1,45,22,'Všechněm jim dal, každému dvoje šaty; ale Beniaminovi dal tři sta stříbrných, a patery šaty jiné a jiné.'),
(1547573,54,1,45,23,'Otci pak svému poslal tyto věci: Deset oslů, kteříž nesli z nejlepších věcí Egyptských, a deset oslic, kteréž nesly obilí, a chléb a pokrmy otci jeho na cestu.'),
(1547574,54,1,45,24,'A propouštěje bratří své, aby odešli, řekl jim: Nevaďtež se na cestě.'),
(1547575,54,1,45,25,'Tedy brali se z Egypta, a přišli do země Kananejské k Jákobovi otci svému.'),
(1547576,54,1,45,26,'A zvěstovali jemu, řkouce: Jozef ještě živ jest, ano i panuje ve vší zemi Egyptské. I omdlelo srdce jeho; nebo slyšev to nevěřil jim.'),
(1547577,54,1,45,27,'Tedy vypravovali jemu všecka slova Jozefova, kteráž mluvil jim; a vida vozy, kteréž poslal Jozef pro něho, okřál duch Jákoba otce jejich.'),
(1547578,54,1,45,28,'I řekl Izrael: Dostiť jest, když ještě syn můj živ jest; půjdu a uzřím ho, prvé než umru.'),
(1547579,54,1,46,1,'Tedy bral se Izrael se vším, což měl; a přišed do Bersabé, obětoval oběti Bohu otce svého Izáka.'),
(1547580,54,1,46,2,'I mluvil Bůh Izraelovi u vidění nočním, řka: Jákobe, Jákobe! Kterýžto odpověděl: Aj, teď jsem.'),
(1547581,54,1,46,3,'I řekl: Já jsem ten Bůh silný, Bůh otce tvého. Neboj se sstoupiti do Egypta, nebo v národ veliký tam tebe učiním.'),
(1547582,54,1,46,4,'Já sstoupím s tebou do Egypta, a já tě také i zase přivedu; a Jozef položí ruku svou na oči tvé.'),
(1547583,54,1,46,5,'Vstal tedy Jákob z Bersabé; a synové Izraelovi vzali Jákoba otce svého, a děti své s ženami svými na vozy, kteréž poslal pro něho Farao.'),
(1547584,54,1,46,6,'Pobrali také dobytek svůj, a zboží své, kteréhož nabyli v zemi Kananejské; a přišli do Egypta, Jákob i všecko símě jeho s ním.'),
(1547585,54,1,46,7,'Syny i vnuky, dcery i vnučky své, a všecku rodinu svou uvedl s sebou do Egypta.'),
(1547586,54,1,46,8,'A tato jsou jména synů Izraelových, kteříž vešli do Egypta: Jákob a synové jeho. Prvorozený Jákobův Ruben.'),
(1547587,54,1,46,9,'A synové Rubenovi: Enoch, Fallu, Ezron a Charmi.'),
(1547588,54,1,46,10,'Synové pak Simeonovi: Jamuel, Jamin, Ahod, Jachin, Sohar a Saul, syn jedné ženy Kananejské.'),
(1547589,54,1,46,11,'Synové Léví: Gerson, Kahat a Merari.'),
(1547590,54,1,46,12,'Synové Judovi: Her, Onan, Séla, Fáres a Zára. (Ale umřel Her a Onan v zemi Kananejské.) Fáres pak měl syny: Ezrona a Hamule.'),
(1547591,54,1,46,13,'Synové Izacharovi: Tola, Fua, Job a Simron.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547592,54,1,46,14,'A synové Zabulonovi: Sared, Elon a Jahelel.'),
(1547593,54,1,46,15,'Tiť jsou synové Líe, kteréž porodila Jákobovi v Pádan Syrské, a Dínu, dceru jeho. Všech duší synů i dcer jeho bylo třidceti a tři.'),
(1547594,54,1,46,16,'Synové Gád: Sefon, Aggi, Suni, Esebon, Heri, Arodi a Areli.'),
(1547595,54,1,46,17,'Synové Asser: Jemna, Jesua, Jesui, Beria, a Serach sestra jejich. Synové pak Beriovi: Heber a Melchiel.'),
(1547596,54,1,46,18,'To jsou synové Zelfy, kterouž Lában dal Líe dceři své; a ty porodila Jákobovi, šestnácte duší.'),
(1547597,54,1,46,19,'Synové pak Ráchel, manželky Jákobovy: Jozef a Beniamin.'),
(1547598,54,1,46,20,'A Jozefovi narodili se v zemi Egyptské z Asenat, dcery Putifera knížete On, Manasses a Efraim.'),
(1547599,54,1,46,21,'Ale synové Beniaminovi: Béla, Becher, Asbel, Gera, Náman, Echi, Roz, Mufim, Chuppim a Ared.'),
(1547600,54,1,46,22,'Tiť jsou synové Ráchel, kteréž porodila Jákobovi; všech duší čtrnáct.'),
(1547601,54,1,46,23,'A syn Danův: Chusim.'),
(1547602,54,1,46,24,'Synové pak Neftalím: Jaziel, Guni, Jezer a Sallem.'),
(1547603,54,1,46,25,'Ti jsou synové Bály, kterouž Lában dal Ráchel dceři své, a ty porodila Jákobovi; všech duší sedm.'),
(1547604,54,1,46,26,'Všech duší, kteréž vešly s Jákobem do Egypta, což jich pošlo z bedr jeho, kromě žen synů Jákobových, všech duší bylo šedesáte a šest.'),
(1547605,54,1,46,27,'K tomu synové Jozefovi, kteříž se jemu narodili v Egyptě, dva. A tak všech duší domu Jákobova, kteréž vešly do Egypta, bylo sedmdesáte.'),
(1547606,54,1,46,28,'Poslal pak Judu napřed k Jozefovi, aby oznámil jemu prvé, než přišel do Gesen. A tak přišli do země Gesen.'),
(1547607,54,1,46,29,'Jozef pak zapřáh do svého vozu, vyjel vstříc Izraelovi otci svému do Gesen; a jakž ho Jákob uzřel, padl na jeho šíji, a plakal dlouho na šíji jeho.'),
(1547608,54,1,46,30,'I řekl Izrael Jozefovi: Nechť již umru, když jsem viděl tvář tvou; nebo ty ještě jsi živ.'),
(1547609,54,1,46,31,'Jozef pak řekl bratřím svým a domu otce svého: Pojedu a zvěstuji Faraonovi, a dím jemu: Bratří moji a dům otce mého, kteříž bydlili v zemi Kananejské, přišli ke mně.'),
(1547610,54,1,46,32,'Ale jsou pastýři stáda, nebo s dobytkem se obírají; protož ovce své a voly, i cožkoli mají, přihnali.'),
(1547611,54,1,46,33,'A když by povolal vás Farao, a řekl:Jaký jest obchod váš?'),
(1547612,54,1,46,34,'Odpovíte: Dobytkem se živili služebníci tvoji od mladosti své až do této chvíle, i my i otcové naši; abyste bydlili v zemi Gesen; nebo v mrzkosti mají Egyptští všecky pastýře stáda.'),
(1547613,54,1,47,1,'A protož přišed Jozef, oznámil Faraonovi, a řekl: Otec můj a bratří moji, s drobným i větším dobytkem svým i se vším, což mají, přišli z země Kananejské, a aj, jsou v zemi Gesen.'),
(1547614,54,1,47,2,'A vzav z počtu bratří svých pět mužů, postavil je před Faraonem.'),
(1547615,54,1,47,3,'I řekl Farao bratřím jeho: Jaký jest obchod váš? Kteřížto odpověděli Faraonovi: Pastýři ovcí jsou služebníci tvoji, i my, i otcové naši.'),
(1547616,54,1,47,4,'Řekli ještě Faraonovi: Abychom pohostinu byli v zemi této, přišli jsme; nebo není pastvy dobytku, kterýž mají služebníci tvoji, nebo hlad veliký jest v zemi Kananejské; protož nyní prosíme, nechať bydlí služebníci tvoji v zemi Gesen.'),
(1547617,54,1,47,5,'I mluvil Farao Jozefovi, řka: Otec tvůj a bratří tvoji přišli k tobě.'),
(1547618,54,1,47,6,'Země Egyptská před tebou jest; v nejlepším kraji země této osaď otce svého a bratří své, nechť bydlí v zemi Gesen. A srozumíš-li, že jsou mezi nimi muži rozšafní, ustanovíš je úředníky nad dobytkem, kterýž mám.'),
(1547619,54,1,47,7,'Uvedl také Jozef Jákoba otce svého, a postavil ho před Faraonem; a pozdravil Jákob Faraona.'),
(1547620,54,1,47,8,'Tedy řekl Farao k Jákobovi: Kolik jest let života tvého?'),
(1547621,54,1,47,9,'Odpověděl Jákob Faraonovi: Dnů let putování mého sto a třidceti let jest; nemnozí a zlí byli dnové let života mého, a nedošli dnů let života otců mých, v nichž živi byli.'),
(1547622,54,1,47,10,'A požehnav Jákob Faraona, vyšel od něho.'),
(1547623,54,1,47,11,'I osadil Jozef otce svého a bratří své, a dal jim vládařství v zemi Egyptské v kraji výborném, v zemi Ramesses, jakž rozkázal Farao.'),
(1547624,54,1,47,12,'A opatroval Jozef otce svého, a bratří své, a všecken dům jeho chlebem, až do nejmenších.'),
(1547625,54,1,47,13,'A chleba nebylo ve vší zemi; nebo veliký hlad byl velmi, a trápení veliké bylo na zemi Egyptské a zemi Kananejské od hladu.'),
(1547626,54,1,47,14,'Shromáždil pak Jozef všecky peníze, což jich nalezeno v zemi Egyptské a v zemi Kananejské, za potravy, kteréž kupovali; a vnesl Jozef peníze do domu Faraonova.'),
(1547627,54,1,47,15,'A když utratili peníze z země Egyptské a z země Kananejské, přicházeli všickni Egyptští k Jozefovi, řkouce: Dej nám chleba; nebo proč mříti máme před tebou pro nedostatek peněz?'),
(1547628,54,1,47,16,'I řekl Jozef: Dejte dobytky své, a dám vám chleba za dobytky vaše, poněvadž se vám peněz nedostává.'),
(1547629,54,1,47,17,'Tedy přivedli dobytky své k Jozefovi; i dal jim Jozef potrav za koně a za stáda ovcí, a za stáda volů i za osly; a přechoval je chlebem, za všecky dobytky jejich, toho roku.'),
(1547630,54,1,47,18,'A po roce tom přišli k němu léta druhého, a řekli mu: Nebudeme tajiti před pánem svým, že jsme všecky peníze utratili, i stáda dobytků jsou u pána našeho; nezůstávají nám před pánem naším kromě těla naše a dědiny naše.'),
(1547631,54,1,47,19,'I proč máme mříti před očima tvýma? I my i rolí naše hyne. Kup nás i rolí naši za chléb, a budeme my i rolí naše ve službě Faraonovi; a dej nám semena, abychom živi byli a nezemřeli, a rolí aby nespustla.'),
(1547632,54,1,47,20,'Tedy koupil Jozef všecku zemi Egyptskou Faraonovi; nebo prodali Egyptští jeden každý pole své, proto že se rozmohl mezi nimi hlad. I dostala se země Faraonovi.'),
(1547633,54,1,47,21,'Lid pak převedl do měst, od jednoho pomezí Egyptského až do druhého.'),
(1547634,54,1,47,22,'Rolí toliko kněžských nekoupil. Nebo kněží uloženou potravu měli od Faraona, a jedli z uložených pokrmů svých, kteréž dával jim Farao; protož neprodali rolí svých.'),
(1547635,54,1,47,23,'I řekl Jozef lidu: Aj, koupil jsem vás dnes i rolí vaše Faraonovi; teď máte semeno, osívejtež tedy ji.'),
(1547636,54,1,47,24,'A když se urodí, dáte pátý díl Faraonovi, a čtyři díly zůstavíte sobě k semenu a ku pokrmu svému a těm, kteříž jsou v domích vašich, i ku pokrmu dítkám svým.'),
(1547637,54,1,47,25,'Tedy řekli: Zachoval jsi životy naše. Nechať nalezneme milost v očích pána svého, a budeme služebníci Faraonovi.'),
(1547638,54,1,47,26,'I ustanovil to Jozef za právo až do tohoto dne, po vší zemi Egyptské, aby dáván byl Faraonovi pátý díl; toliko samy rolí kněžské nebyly Faraonovy.'),
(1547639,54,1,47,27,'A tak bydlil Izrael v zemi Egyptské v krajině Gesen; a osadili se v ní, a rozplodili se, a rozmnoženi jsou velmi.'),
(1547640,54,1,47,28,'Živ pak byl Jákob v zemi Egyptské sedmnácte let; a bylo dnů Jákobových, a let života jeho, sto čtyřidceti sedm let.'),
(1547641,54,1,47,29,'I přiblížili se dnové Izraelovi, aby umřel. A povolav syna svého Jozefa, řekl jemu: Jestliže jsem nalezl milost v očích tvých, vlož, prosím, ruku svou pod bedro mé, a učiň se mnou milosrdenství a pravdu. Prosím, nepochovávej mne v Egyptě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547642,54,1,47,30,'Když spáti budu s otci svými, vyneseš mne z Egypta, a pochováš mne v hrobě jejich. Tedy řekl jemu: Já učiním podlé slova tvého.'),
(1547643,54,1,47,31,'I řekl Jákob: Přisáhni mi. Tedy přisáhl jemu. I sklonil se Izrael k hlavám lůže.'),
(1547644,54,1,48,1,'Stalo se pak potom, že povědíno jest Jozefovi: Aj, otec tvůj nemocen jest. I vzal s sebou dva syny své, Manasse a Efraima.'),
(1547645,54,1,48,2,'Tedy oznámeno jest Jákobovi a povědíno: Aj, syn tvůj Jozef přišel k tobě.'),
(1547646,54,1,48,3,'A posilniv se Izrael, usadil se na ložci a řekl Jozefovi: Bůh silný všemohoucí ukázav mi se v Lůza v zemi Kananejské, požehnal mi.'),
(1547647,54,1,48,4,'A řekl ke mně: Aj, já rozplodím tě a rozmnožím tebe, a učiním tě v zástupy lidí; dám také zemi tuto semeni tvému po tobě za dědictví věčné.'),
(1547648,54,1,48,5,'Protož nyní, dva synové tvoji, kteřížť jsou se zrodili v zemi Egyptské, prvé než jsem přišel k tobě do Egypta, moji jsou; Efraim a Manasses budou mi jako Ruben a Simeon.'),
(1547649,54,1,48,6,'Ale děti, kteréž po těchto zplodíš, tvoji budou; jménem bratří svých jmenováni budou v dědictvích svých.'),
(1547650,54,1,48,7,'Nebo když jsem se vracel z Pádan, umřela mi Ráchel v zemi Kananejské na cestě, když již nedaleko bylo do Efraty; a pochoval jsem ji tam u cesty k Efratě, jenž jest Betlém.'),
(1547651,54,1,48,8,'Uzřev potom Izrael syny Jozefovy, řekl: Kdo jsou onino?'),
(1547652,54,1,48,9,'Odpověděl Jozef otci svému: Synové moji jsou, kteréž dal mi Bůh zde. I řekl:Přiveď je medle ke mně, a požehnám jim'),
(1547653,54,1,48,10,'(Oči pak Izraelovy mdlé byly pro starost, a nemohl dobře viděti.) I přivedl je k němu, a on líbal a objímal je.'),
(1547654,54,1,48,11,'I řekl Izrael Jozefovi: Nemyslilť jsem já, abych měl kdy viděti tvář tvou, a aj, dal mi Bůh, abych viděl i símě tvé.'),
(1547655,54,1,48,12,'Tedy vzav je Jozef z klína jeho, sklonil se tváří až k zemi.'),
(1547656,54,1,48,13,'A vzav oba, Efraima na pravou stranu sobě, Izraelovi pak na levou, a Manassesa na levou sobě, Izraelovi pak na pravou, postavil je před ním.'),
(1547657,54,1,48,14,'Tedy vztáh Izrael pravici svou, vložil ji na hlavu Efraimovu, kterýž byl mladší, levici pak svou na hlavu Manassesovu, naschvál přeloživ ruce, ačkoli Manasses byl prvorozený.'),
(1547658,54,1,48,15,'I požehnal Jozefovi, řka: Bůh, před jehož oblíčejem ustavičně chodili otcové moji Abraham a Izák, Bůh, kterýž mne spravoval po všecken život můj až do dne tohoto;'),
(1547659,54,1,48,16,'Anděl ten, kterýž vytrhl mne ze všeho zlého, požehnejž dítek těchto; a ať slovou synové moji a synové otců mých Abrahama a Izáka; a ať se jako hmyz rozmnoží u prostřed země.'),
(1547660,54,1,48,17,'Vida pak Jozef, že vložil otec jeho ruku svou pravou na hlavu Efraimovu, nerád byl tomu. I zdvihl ruku otce svého, aby ji přenesl s hlavy Efraimovy na hlavu Manassesovu.'),
(1547661,54,1,48,18,'A řekl jemu: Ne tak, otče můj; nebo toto jest prvorozený, vložiž pravici svou na hlavu jeho.'),
(1547662,54,1,48,19,'Ale nepovolil otec jeho, a řekl: Vím, synu můj, vím; takéť i on bude v lid, a také i on vzroste; však bratr jeho mladší více poroste než on, a símě jeho bude u veliké množství národů.'),
(1547663,54,1,48,20,'I požehnal jim v ten den, řka: Skrze tebe požehnání bude dávati Izrael takto: Učiniž tobě Bůh jako Efraimovi a jako Manassesovi. I představil Efraima Manassesovi.'),
(1547664,54,1,48,21,'Řekl také Izrael Jozefovi: Aj, já umírám, a budeť Bůh s vámi, a zase vás přivede do země otců vašich.'),
(1547665,54,1,48,22,'Já pak dal jsem tobě jeden díl výš nad bratří tvé, kteréhož jsem mečem svým a lučištěm svým dosáhl z ruky Amorejského.'),
(1547666,54,1,49,1,'Povolal pak Jákob synů svých, a řekl: Sejděte se, a oznámím vám, co se s vámi díti bude potomních dnů.'),
(1547667,54,1,49,2,'Shromažďte se a slyšte synové Jákobovi, poslyšte Izraele otce svého.'),
(1547668,54,1,49,3,'Ruben, prvorozený můj jsi ty, síla má, a počátek moci mé, vyvýšenost důstojenství a vyvýšenost síly.'),
(1547669,54,1,49,4,'Prudce sběhneš jako voda. Nebudeš vyvýšen, proto že jsi vstoupil na lůže otce svého; a jakž jsi poškvrnil postele mé, zmizelo vyvýšení tvé.'),
(1547670,54,1,49,5,'Simeon a Léví bratří, nástrojové nepravosti jsou v příbytcích jejich.'),
(1547671,54,1,49,6,'Do tajné rady jejich nevcházej duše má, k shromáždění jejich nepřipojuj se slávo má; nebo v prchlivosti své zbili muže, a svévolně vyvrátili zed.'),
(1547672,54,1,49,7,'Zlořečená prchlivost jejich, nebo neustupná; i hněv jejich, nebo zatvrdilý jest. Rozdělím je v Jákobovi, a rozptýlím je v Izraeli.'),
(1547673,54,1,49,8,'Judo, ty jsi, tebe chváliti budou bratří tvoji; ruka tvá bude na šíji nepřátel tvých; klaněti se budou tobě synové otce tvého.'),
(1547674,54,1,49,9,'Lvíče Juda, z loupeže, synu můj, vrátil jsi se; schýliv se, ležel jako lev a jako lvice; kdo zbudí ho?'),
(1547675,54,1,49,10,'Nebude odjata berla od Judy, ani vydavatel zákona od noh jeho, dokudž nepřijde Sílo; a k němu se shromáždí národové.'),
(1547676,54,1,49,11,'Uváže k vinnému kmenu osle své, a k výbornému kmenu oslátko oslice své. Práti bude u víně roucho své, a v červeném víně oděv svůj.'),
(1547677,54,1,49,12,'Červenějších očí bude nad víno, a zubů bělejších nad mléko.'),
(1547678,54,1,49,13,'Zabulon bydliti bude na břehu mořském, a na přístavu lodí, a pomezí jeho až k Sidonu.'),
(1547679,54,1,49,14,'Izachar osel silný, ležící mezi dvěma břemeny.'),
(1547680,54,1,49,15,'A vida odpočinutí, že jest dobré, a zemi, že jest rozkošná, sehne rameno své k nošení, a dávati bude daně.'),
(1547681,54,1,49,16,'Dan souditi bude lid svůj, jako jedno z pokolení Izraelských.'),
(1547682,54,1,49,17,'Budeť Dan jako had podlé cesty, jako had rohatý podlé stezky, štípaje kopyta koně, aby spadl jezdec jeho zpět.'),
(1547683,54,1,49,18,'Spasení tvého očekávám, ó Hospodine!'),
(1547684,54,1,49,19,'Gád, vojsko přemůže jej, však on svítězí potom.'),
(1547685,54,1,49,20,'Asser, tučný bude pokrm jeho, a onť vydávati bude rozkoše královské.'),
(1547686,54,1,49,21,'Neftalím jako laň vypuštěná, vydávaje výmluvnosti krásné.'),
(1547687,54,1,49,22,'Ratolest rostoucí Jozef, ratolest rostoucí podlé studnice; ratolesti vycházely nad zed.'),
(1547688,54,1,49,23,'Ačkoli hořkostí naplnili jej, a stříleli na něj, a v tajné nenávisti měli ho střelci:'),
(1547689,54,1,49,24,'Však zůstalo v síle lučiště jeho, a zsilila se ramena rukou jeho z rukou mocného Jákobova; odkudž byl pastýř a kámen Izraelův;'),
(1547690,54,1,49,25,'Od silného Boha, jemuž sloužil otec tvůj, kterýž spomáhá tobě, a od všemohoucího, kterýž požehná tobě požehnáními nebeskými s hůry, požehnáními propasti ležící hluboko, požehnáním prsů a života.'),
(1547691,54,1,49,26,'Požehnání otce tvého silnější budou nad požehnání předků mých, až k končinám pahrbků věčných; budou nad hlavou Jozefovou, a na vrchu hlavy Nazarejského mezi bratřími jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547692,54,1,49,27,'Beniamin, vlk dravý, ráno bude jísti loupež, a večer rozdělí kořisti.'),
(1547693,54,1,49,28,'Všech těchto pokolení Izraelských jest dvanácte; a to jest, což mluvil jim otec jejich; požehnal jim také, jednomu každému vedlé požehnání jeho požehnal.'),
(1547694,54,1,49,29,'A poroučeje jim, řekl: Já připojen budu k lidu svému; pochovejte mne s otci mými v jeskyni té, kteráž jest na poli Efrona Hetejského,'),
(1547695,54,1,49,30,'V jeskyni, kteráž jest na poli Machpelah, jenž jest naproti Mamre v zemi Kananejské, kterouž koupil Abraham spolu s polem tím od Efrona Hetejského k dědičnému pohřbu.'),
(1547696,54,1,49,31,'Tam pochovali Abrahama a Sáru ženu jeho; tam pochovali Izáka a Rebeku ženu jeho; tam také pochovali Líu.'),
(1547697,54,1,49,32,'Koupeno pak bylo pole a jeskyně, kteráž na něm, od synů Het.'),
(1547698,54,1,49,33,'A když přestal Jákob přikazovati synům svým, složil nohy své na ložci a umřel; a připojen jest k lidu svému.'),
(1547699,54,1,50,1,'Tedy padl Jozef na tvář otce svého, a plakal nad ním, líbaje ho.'),
(1547700,54,1,50,2,'A poručil služebníkům svým lékařům, aby vonnými věcmi pomazali otce jeho. I pomazali lékaři vonnými věcmi Izraele.'),
(1547701,54,1,50,3,'A vyplnilo se při něm čtyřidceti dní; (nebo tak vyplňují se dnové těch, kteříž mazáni bývají vonnými věcmi). I plakali ho Egyptští za sedmdesáte dní.'),
(1547702,54,1,50,4,'Když pak dnové pláče toho pominuli, mluvil Jozef k domu Faraonovu, řka: Jestliže jsem nyní nalezl milost před očima vašima, mluvte, prosím, v uši Faraonovy, a rcete:'),
(1547703,54,1,50,5,'Otec můj přísahou mne zavázal, řka: Aj, já umírám; v hrobě mém, kterýž jsem sobě vykopal v zemi Kananejské, tam mne pochovej. Nyní tedy, prosím, nechť vstoupím a pochovám otce svého, a navrátím se zase.'),
(1547704,54,1,50,6,'I řekl Farao: Vstup a pochovej otce svého tak, jakž tě přísahou zavázal.'),
(1547705,54,1,50,7,'Tedy vstoupil Jozef, aby pochoval otce svého, a vstoupili s ním všickni služebníci Faraonovi, starší domu jeho a všickni starší země Egyptské,'),
(1547706,54,1,50,8,'Všecken také dům Jozefův, a všickni bratří jeho i dům otce jeho; toliko dětí svých, ovec a volů nechali v zemi Gesen.'),
(1547707,54,1,50,9,'Vstoupili s ním také i vozové a jezdci, a bylo vojsko to veliké velmi.'),
(1547708,54,1,50,10,'I přišli až k místu Atád, kteréž jest při brodu Jordánském, a kvílili tam kvílením velikým a velmi žalostným; i držel tu zámutek po otci svém za dnů sedm.'),
(1547709,54,1,50,11,'Vidouce pak obyvatelé země té, totiž Kananejští, zámutek na místě tom Atád, řekli: Těžký to mají zámutek Egyptští. Protož nazváno jest jméno jeho Abel Mizraim, a to jest při brodu Jordánském.'),
(1547710,54,1,50,12,'Učinili tedy s ním synové jeho tak, jakž jim byl poručil.'),
(1547711,54,1,50,13,'A donesše ho do země Kananejské, pochovali ho v jeskyni na poli Machpelah, kterouž byl koupil Abraham s tím polem k dědičnému pohřbu od Efrona Hetejského, naproti Mamre.'),
(1547712,54,1,50,14,'A když pochoval Jozef otce svého, navrátil se do Egypta s bratřími svými a se všemi, kteříž byli vstoupili s ním, aby pochovali otce jeho.'),
(1547713,54,1,50,15,'Vidouce pak bratří Jozefovi, že umřel otec jejich, řekli: Snad v nenávisti nás míti bude Jozef, a vrchovatě nahradí nám všecko zlé, kteréž jsme jemu činili.'),
(1547714,54,1,50,16,'Protož vzkázali Jozefovi, řkouce: Otec tvůj ještě před smrtí svou přikázal, řka:'),
(1547715,54,1,50,17,'Takto díte Jozefovi: Prosím, odpusť již bratřím svým přestoupení a hřích jejich; nebo zle učinili tobě. Protož již odpusť, prosím, přestoupení služebníkům Boha, jehož ctil otec tvůj. I rozplakal se Jozef, když k němu mluvili.'),
(1547716,54,1,50,18,'Přistoupili potom také bratří jeho, a padše před ním, řekli: Aj, my jsme služebníci tvoji.'),
(1547717,54,1,50,19,'Jimž odpověděl Jozef: Nebojte se; nebo zdaliž jsem já vám za Boha?'),
(1547718,54,1,50,20,'Vy zajisté skládali jste proti mně zlé; ale Bůh obrátil to v dobré, aby učinil to, což vidíte nyní, a při životu zachoval lid mnohý.'),
(1547719,54,1,50,21,'Protož nebojte se již; já chovati vás budu i děti vaše. A tak těšil je, a mluvil k srdci jejich.'),
(1547720,54,1,50,22,'Bydlil pak Jozef v Egyptě, on i dům otce jeho, a živ byl Jozef sto a deset let.'),
(1547721,54,1,50,23,'A viděl Jozef syny Efraimovy až do třetího pokolení; ano i synové Machira, syna Manassesova, vychováni jsou u Jozefa.'),
(1547722,54,1,50,24,'Mluvil potom Jozef bratřím svým: Já tudíž umru; Bůh pak jistotně navštíví vás, a vyvede vás z země této do země, kterouž přisáhl Abrahamovi, Izákovi a Jákobovi.'),
(1547723,54,1,50,25,'Protož přísahou zavázal Jozef syny Izraelovy, řka: Když navštíví vás Bůh, vynestež kosti mé odsud.'),
(1547724,54,1,50,26,'I umřel Jozef, když byl ve stu a v desíti letech; a pomazán jsa vonnými věcmi, vložen jest do truhly v Egyptě.'),
(1547725,54,2,1,1,'Tato jsou pak jména synů Izraelských, kteříž vešli do Egypta s Jákobem; každý s čeledí svou přišel:'),
(1547726,54,2,1,2,'Ruben, Simeon, Léví a Juda;'),
(1547727,54,2,1,3,'Izachar, Zabulon a Beniamin;'),
(1547728,54,2,1,4,'Dan a Neftalím, Gád a Asser.'),
(1547729,54,2,1,5,'A bylo všech osob pošlých z bedr Jákobových sedmdesáte duší; Jozef pak byl v Egyptě.'),
(1547730,54,2,1,6,'I umřel Jozef a všickni bratří jeho, a všecken ten rod.'),
(1547731,54,2,1,7,'Synové pak Izraelští rozmnožili se a rodili se v hojnosti; a rozhojňovali se, i zsilili se náramně velmi, a naplněna jest jimi země.'),
(1547732,54,2,1,8,'V tom povstal král nový v Egyptě, kterýž neznal Jozefa.'),
(1547733,54,2,1,9,'Ten řekl lidu svému: Aj, lid synů Izraelských jest mnohý a silnější nad nás.'),
(1547734,54,2,1,10,'Nuže, opatrně sobě počínejme před ním, aby se nerozmohl; a když by přišla válka, aby se nepřipojil i on k nepřátelům našim, a nebojoval proti nám, a nevyšel z země.'),
(1547735,54,2,1,11,'Protož ustanovili nad ním úředníky, kteříž by plat vybírali, aby je trápili břemeny svými. I vystavěl lid Izraelský Faraonovi města skladů, Fiton a Ramesses.'),
(1547736,54,2,1,12,'Ale čím více trápili jej, tím více rostl a tím se více rozmáhal. I vzali sobě syny Izraelské v ošklivost.'),
(1547737,54,2,1,13,'A tak podrobovali Egyptští syny Izraelské v službu těžkou.'),
(1547738,54,2,1,14,'A k hořkosti přivodili život jejich robotami těžkými, v hlině a cihlách a ve všelijakém díle na poli, mimo všelikou potřebu svou, k níž práce jejich užívali nenáležitě a bez lítosti.'),
(1547739,54,2,1,15,'I poručil král Egyptský babám Hebrejským, z nichž jedna sloula Sefora a druhá Fua,'),
(1547740,54,2,1,16,'A řekl: Když budete pomáhati ženám Hebrejským při porodu, a uzříte, že již rodí, byl-li by syn, zabíte ho, pakli dcera, tedy ať jest živa.'),
(1547741,54,2,1,17,'Bály se pak ty baby Boha, a nečinily tak, jakž jim poručil král Egyptský, ale živých nechávaly pacholíků.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547742,54,2,1,18,'Povolav tedy bab král Egyptský, mluvil jim: Proč jste to učinily, že jste živé zachovaly pacholíky?'),
(1547743,54,2,1,19,'I odpověděly baby Faraonovi: Nejsou ženy Hebrejské jako ženy Egyptské; nebo ony jsou silnějšího přirození. Dříve než přijde k nim baba, ony porodí.'),
(1547744,54,2,1,20,'I učinil dobře Bůh těm babám. A rozmnožen jest lid, a zsilili se velmi.'),
(1547745,54,2,1,21,'Stalo se pak proto, že se bály baby ty Boha, vzdělal jim domy.'),
(1547746,54,2,1,22,'I přikázal Farao všemu lidu svému, řka: Každého syna, kterýž se narodí, do řeky uvrzte; každé pak dcery nechte živé.'),
(1547747,54,2,2,1,'Odšed pak muž jeden z domu Léví, vzal dceru z pokolení Léví.'),
(1547748,54,2,2,2,'I počala žena ta, a porodila syna; a viduci, že jest krásný, kryla ho za tři měsíce.'),
(1547749,54,2,2,3,'A když ho nemohla déle tajiti, vzala mu ošitku z sítí, a omazala ji klím a smolou; a vložila do ní to dítě, a vyložila do rákosí u břehu řeky.'),
(1547750,54,2,2,4,'A postavila sestru jeho zdaleka, aby zvěděla, co se s ním díti bude.'),
(1547751,54,2,2,5,'A v tom sešla dcera Faraonova, aby se myla v řece; a děvečky její procházely se po břehu řeky. A uzřevši ošitku mezi rákosím, poslala děvečku svou, a vzala ji.'),
(1547752,54,2,2,6,'A když otevřela, uzřela dítě; a aj, plakalo pacholátko. A slitovavši se nad ním, řekla: Z dětí Hebrejských jest toto.'),
(1547753,54,2,2,7,'I řekla sestra jeho k dceři Faraonově: Mám-li jíti a zavolati tobě chůvy z žen Hebrejských, kteráž by odchovala tobě dítě?'),
(1547754,54,2,2,8,'Odpověděla dcera Faraonova: Jdi. Tedy šla děvečka a zavolala matky toho dítěte.'),
(1547755,54,2,2,9,'I řekla jí dcera Faraonova: Vezmi toto dítě, a odchovej mi je; a jáť dám mzdu tvou. I vzala žena dítě, a chovala je.'),
(1547756,54,2,2,10,'A když odrostlo pachole, dovedla je k dceři Faraonově, kteráž jej měla za syna; a nazvala jméno jeho Mojžíš, řkuci: Nebo jsem ho z vody vytáhla.'),
(1547757,54,2,2,11,'I stalo se ve dnech těch, když vyrostl Mojžíš, že vyšel k bratřím svým, a hleděl na trápení jejich. Uzřel také muže Egyptského, an tepe muže Hebrejského, jednoho z bratří jeho. A sem i tam se ohlédna, vida, že žádného tu není, zabil Egyptského, a zahrabal jej v písku.'),
(1547758,54,2,2,12,'Vyšed potom druhého dne, a aj, dva muži Hebrejští vadili se. I řekl tomu, kterýž křivdu činil: Proč tepeš bližního svého?'),
(1547759,54,2,2,13,'Kterýžto odpověděl: Kdo tě ustanovil knížetem a soudcí nad námi? Zdali zabiti mne myslíš, jako jsi zabil Egyptského? Protož ulekl se Mojžíš a řekl: Jistě známá jest ta věc.'),
(1547760,54,2,2,14,'A uslyšav Farao tu věc, hledal zabiti Mojžíše. Ale Mojžíš utekl od tváři Faraonovy, a bydlil v zemi Madianské; i usadil se podlé studnice.'),
(1547761,54,2,2,15,'Kníže pak Madianské mělo sedm dcer. Kteréžto přišedše, vážily vodu, a nalívaly do koryt, aby napájely dobytek otce svého.'),
(1547762,54,2,2,16,'I přišli pastýři, a odehnali je. Tedy Mojžíš vstav, pomohl jim a napojil dobytek jejich.'),
(1547763,54,2,2,17,'A když se navrátily k Raguelovi, otci svému, řekl on: Jakž jste to dnes tak brzo přišly?'),
(1547764,54,2,2,18,'Odpověděly: Muž Egyptský vysvobodil nás z ruky pastýřů; ano také ochotně navážil nám vody, a napojil dobytek.'),
(1547765,54,2,2,19,'I řekl dcerám svým: Kdež pak jest? Pročež jste pustily muže toho? Povolejte ho, ať pojí chleba.'),
(1547766,54,2,2,20,'A svolil Mojžíš k tomu, aby bydlil s mužem tím. Kterýžto dal Zeforu, dceru svou, Mojžíšovi.'),
(1547767,54,2,2,21,'I porodila syna, a nazval jméno jeho Gerson; nebo řekl: Příchozí jsem byl v zemi cizí.'),
(1547768,54,2,2,22,'Stalo se pak po mnohých časích, že umřel král Egyptský; a synové Izraelští úpěli pro roboty, a křičeli. I vstoupil k Bohu křik jejich pro roboty.'),
(1547769,54,2,2,23,'A uslyšel Bůh naříkání jejich, a rozpomenul se Bůh na smlouvu svou s Abrahamem, Izákem a Jákobem.'),
(1547770,54,2,2,24,'I vzhlédl Bůh na syny Izraelské, a poznal Bůh.'),
(1547771,54,2,3,1,'Mojžíš pak pásl dobytek Jetry tchána svého, kněze Madianského, a hnav stádo po poušti, přišel až k hoře Boží Oréb.'),
(1547772,54,2,3,2,'Tedy ukázal se mu anděl Hospodinův v plameni ohně z prostředku kře. I viděl, a aj, keř hořel ohněm, a však neshořel.'),
(1547773,54,2,3,3,'Protož řekl Mojžíš: Půjdu nyní, a spatřím vidění toto veliké, proč neshoří keř.'),
(1547774,54,2,3,4,'Vida pak Hospodin, že jde, aby pohleděl, zavolal naň Bůh z prostředku kře, a řekl: Mojžíši, Mojžíši! Kterýžto odpověděl: Aj, teď jsem.'),
(1547775,54,2,3,5,'I řekl: Nepřistupuj sem, szuj obuv svou s noh svých; nebo místo, na kterémž ty stojíš, země svatá jest.'),
(1547776,54,2,3,6,'A řekl: Já jsem Bůh otce tvého, Bůh Abrahamův, Bůh Izákův, a Bůh Jákobův. I zakryl Mojžíš tvář svou, (nebo se bál), aby nepatřil na Boha.'),
(1547777,54,2,3,7,'Jemužto řekl Hospodin: Zřetelně viděl jsem trápení lidu mého, kterýž jest v Egyptě; a křik jejich pro přísnost úředníků jeho slyšel jsem; nebo znám bolesti jeho.'),
(1547778,54,2,3,8,'Protož jsem sstoupil, abych vysvobodil jej z ruky Egyptských, a vyvedl jej z země té do země dobré a prostranné, do země oplývající mlékem a strdí, na místa Kananejského a Hetejského, a Amorejského a Ferezejského, a Hevejského a Jebuzejského.'),
(1547779,54,2,3,9,'Nebo nyní, aj, křik synů Izraelských přišel ke mně; viděl jsem také i ssoužení, jímž je ssužují Egyptští.'),
(1547780,54,2,3,10,'Protož, nyní poď a pošli tě k Faraonovi; a vyvedeš lid můj, syny Izraelské z Egypta.'),
(1547781,54,2,3,11,'I řekl Mojžíš Bohu: Kdo jsem já, abych šel k Faraonovi, a abych vyvedl syny Izraelské z Egypta?'),
(1547782,54,2,3,12,'I odpověděl: Však budu s tebou; a toto budeš míti znamení, že jsem já tě poslal: Když vyvedeš lid ten z Egypta, sloužiti budete Bohu na hoře této.'),
(1547783,54,2,3,13,'I řekl Mojžíš Bohu: Aj, já půjdu k synům Izraelským a dím jim: Bůh otců vašich poslal mne k vám. Řeknou-li mi: Které jest jméno jeho? co jim odpovím?'),
(1547784,54,2,3,14,'I řekl Bůh Mojžíšovi: JSEM, KTERÝŽ JSEM. Řekl dále: Takto díš synům Izraelským: JSEM poslal mne k vám.'),
(1547785,54,2,3,15,'Řekl ještě Bůh Mojžíšovi: Takto díš synům Izraelským: Hospodin, Bůh otců vašich, Bůh Abrahamův, Bůh Izákův, a Bůh Jákobův poslal mne k vám; toť jest jméno mé na věčnost, a tať jest památka má po všecky věky.'),
(1547786,54,2,3,16,'Jdi, a shromáždě starší Izraelské, mluv jim: Hospodin Bůh otců vašich ukázal mi se, Bůh Abrahamův, Bůh Izákův, a Bůh Jákobův, řka: Rozpomínaje, rozpomenul jsem se na vás, a na to, co se vám dálo v Egyptě.'),
(1547787,54,2,3,17,'Protož jsem řekl: Vyvedu vás z trápení Egyptského do země Kananejského, a Hetejského, a Amorejského, a Ferezejského, a Hevejského, a Jebuzejského, do země oplývající mlékem a strdí.'),
(1547788,54,2,3,18,'I poslechnou hlasu tvého. Půjdeš pak ty a starší Izraelští k králi Egyptskému, a díte jemu: Hospodin Bůh Hebrejský potkal se s námi; protož nyní, nechť medle jdeme cestou tří dnů na poušť, abychom obětovali Hospodinu Bohu našemu.'),
(1547789,54,2,3,19,'Ale já vím, žeť vám nedopustí král Egyptský jíti; leč v ruce silné.'),
(1547790,54,2,3,20,'Protož vztáhnu ruku svou, a bíti budu Egypt divnými věcmi svými, kteréž činiti budu u prostřed něho; a potom propustí vás.'),
(1547791,54,2,3,21,'A dám milost lidu tomuto před očima Egyptských. I stane se, že když půjdete, neodejdete prázdní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547792,54,2,3,22,'Ale vypůjčí žena od sousedy své, a od hospodyně domu svého klínotů stříbrných, a klínotů zlatých a roucha; i vložíte to na syny a na dcery své, a tak obloupíte Egypt.'),
(1547793,54,2,4,1,'Odpověděl pak Mojžíš, a řekl: Aj, neuvěří mi, ani uposlechnou hlasu mého; nebo řeknou: Neukázalť se tobě Hospodin.'),
(1547794,54,2,4,2,'Tedy řekl jemu Hospodin: Co jest to v ruce tvé? Odpověděl: Hůl.'),
(1547795,54,2,4,3,'I řekl: Vrz ji na zem. I povrhl ji na zem, a obrácena jest v hada; a utíkal Mojžíš před ním.'),
(1547796,54,2,4,4,'Tedy řekl Hospodin Mojžíšovi: Vztáhni ruku svou, a chyť ho za ocas. Kterýžto vztáh ruku svou, chytil jej, a obrácen jest v hůl v rukou jeho.'),
(1547797,54,2,4,5,'Aby věřili, že se ukázal tobě Hospodin, Bůh otců jejich, Bůh Abrahamův, Bůh Izákův a Bůh Jákobův.'),
(1547798,54,2,4,6,'Potom zase řekl jemu Hospodin: Vlož nyní ruku svou za ňadra svá. I vložil ruku svou za ňadra svá; a vyňal ji, a aj, ruka jeho byla malomocná, bílá jako sníh.'),
(1547799,54,2,4,7,'Řekl opět: Vlož ruku svou zase v ňadra svá. Kterýž vložil ruku svou zase v ňadra svá; a vyňal ji z ňader svých, a aj, učiněna jest zase jako jiné tělo jeho.'),
(1547800,54,2,4,8,'I budeť, jestliže neuvěří tobě, a neposlechnou hlasu a znamení prvního, uvěří hlasu a znamení druhému.'),
(1547801,54,2,4,9,'A pakli neuvěří ani těm dvěma znamením, a neuposlechnou hlasu tvého, tedy nabereš vody z řeky, a vyliješ ji na zem; a promění se vody, kteréž vezmeš z řeky, a obrátí se v krev na zemi.'),
(1547802,54,2,4,10,'I řekl Mojžíš Hospodinu: Prosím, Pane, nejsem muž výmluvný, aniž prvé, ani jakž jsi mluvil s služebníkem svým; nebo zpozdilých úst a neohbitého jazyku jsem.'),
(1547803,54,2,4,11,'Jemuž odpověděl Hospodin: Kdo dal ústa člověku? Aneb kdo může učiniti němého, neb hluchého, vidoucího, neb slepého? Zdali ne já Hospodin?'),
(1547804,54,2,4,12,'Nyní tedy jdi, a já budu v ústech tvých, a naučím tě, co bys mluviti měl.'),
(1547805,54,2,4,13,'I řekl: Slyš mne, Pane, pošli, prosím, toho, kteréhož poslati máš.'),
(1547806,54,2,4,14,'A rozhněvav se velmi Hospodin na Mojžíše, řekl: Zdaliž nemáš Arona bratra svého z pokolení Léví? Vím, že on výmluvný jest; ano aj, sám vyjde v cestu tobě, a vida tebe, radovati se bude v srdci svém.'),
(1547807,54,2,4,15,'Ty mluviti budeš k němu, a vložíš slova v ústa jeho; a já budu v ústech tvých a v ústech jeho, a naučím vás, co byste měli činiti.'),
(1547808,54,2,4,16,'A on mluviti bude za tebe k lidu; a bude tobě on za ústa, a ty budeš jemu za Boha.'),
(1547809,54,2,4,17,'Hůl pak tuto vezmeš v ruku svou, kterouž činiti budeš ta znamení.'),
(1547810,54,2,4,18,'Tedy odšed Mojžíš, navrátil se k Jetrovi tchánu svému, a řekl jemu: Nechť jdu nyní, a navrátím se k bratřím svým, kteříž jsou v Egyptě, a pohledím, jsou-li ještě živi. I řekl Jetro Mojžíšovi: Jdi v pokoji.'),
(1547811,54,2,4,19,'Nebo řekl byl Hospodin Mojžíšovi v zemi Madianské: Jdi, navrať se do Egypta; nebo zemřeli jsou všickni muži, kteříž hledali bezživotí tvého.'),
(1547812,54,2,4,20,'A vzav Mojžíš ženu svou, a syny své, vsadil je na osla, aby se navrátil do země Egyptské; vzal také Mojžíš hůl Boží v ruku svou.'),
(1547813,54,2,4,21,'I řekl Hospodin Mojžíšovi: Když půjdeš a navrátíš se do Egypta, hleď, abys všecky zázraky, kteréž jsem složil v ruce tvé, činil před Faraonem. Jáť pak zatvrdím srdce jeho, aby nepropustil lidu.'),
(1547814,54,2,4,22,'Protož díš Faraonovi: Toto praví Hospodin: Syn můj, prvorozený můj jest Izrael.'),
(1547815,54,2,4,23,'I řekl jsem tobě: Propusť syna mého, ať slouží mi; a nechtěl jsi ho propustiti. Aj, já zabiji syna tvého, prvorozeného tvého.'),
(1547816,54,2,4,24,'I stalo se, když byl Mojžíš na cestě v hospodě, že se obořil na něj Hospodin, a hledal ho usmrtiti.'),
(1547817,54,2,4,25,'Tedy vzala Zefora nůž ostrý, a obřezala neobřízku syna svého, kteroužto vrhla k nohám jeho, řkuci: Zajisté ženich krví jsi mi.'),
(1547818,54,2,4,26,'I nechal ho. Ona pak nazvala ho tehdáž ženichem krví pro obřezání.'),
(1547819,54,2,4,27,'Řekl také Hospodin Aronovi: Jdi vstříc Mojžíšovi na poušť. I šel a potkal se s ním na hoře Boží, a políbil ho.'),
(1547820,54,2,4,28,'A vypravoval Mojžíš Aronovi všecka slova Hospodinova, kterýž ho poslal, i o všech znameních, kteráž přikázal jemu.'),
(1547821,54,2,4,29,'Tedy šel Mojžíš s Aronem, a shromáždili všecky starší synů Izraelských.'),
(1547822,54,2,4,30,'I mluvil Aron všecka slova, kteráž byl mluvil Hospodin k Mojžíšovi, a činil znamení před očima lidu.'),
(1547823,54,2,4,31,'A uvěřil lid, když uslyšeli, že navštívil Hospodin syny Izraelské, a že viděl ssoužení jejich. A sklonivše se, poklonu učinili.'),
(1547824,54,2,5,1,'Potom pak přišli Mojžíš s Aronem, a řekli Faraonovi: Takto praví Hospodin, Bůh Izraelský: Propusť lid můj, ať mi slaví svátky na poušti.'),
(1547825,54,2,5,2,'Odpověděl Farao: Kdo jest Hospodin, abych poslechl hlasu jeho a propustil Izraele? Hospodina neznám, Izraele také nepropustím.'),
(1547826,54,2,5,3,'I řekli: Bůh Hebrejský potkal se s námi. Nechť medle jdeme cestou tří dní na poušť, a obětujeme Hospodinu Bohu našemu, aby nedopustil na nás moru neb meče.'),
(1547827,54,2,5,4,'I řekl jim král Egyptský: Proč ty Mojžíši a Arone, odtrhujete lid od prací jejich? Jděte k robotám svým.'),
(1547828,54,2,5,5,'Řekl také Farao: Hle, již nyní mnoho jest lidu toho v zemi, a vy odvozujete je od robot jejich.'),
(1547829,54,2,5,6,'I přikázal Farao v ten den úředníkům nad lidem a šafářům jeho, řka:'),
(1547830,54,2,5,7,'Nedávejte již více slámy lidu k dělání cihel jako prvé; nechať jdou sami a sbírají sobě slámu.'),
(1547831,54,2,5,8,'Však touž summu cihel, kterouž udělávali prvé, uložte na ně, nic neujímejte z ní; neboť zahálejí, a protož volají, řkouce: Poďme, obětujme Bohu našemu.'),
(1547832,54,2,5,9,'Nechť se přitíží robot mužům těm; a nechť pracují v nich, aby se neohlédali na slova lživá.'),
(1547833,54,2,5,10,'Vyšedše tedy úředníci nad lidem a šafáři jeho, mluvili k lidu, řkouce: Takto praví Farao: Já nebudu vám dávati slámy.'),
(1547834,54,2,5,11,'Sami jděte, beřte sobě slámu, kdekoli naleznete; ale nic nebude ujato díla vašeho.'),
(1547835,54,2,5,12,'I rozběhl se lid po vší zemi Egyptské, aby trhal strniště místo slámy.'),
(1547836,54,2,5,13,'A úředníci nutili je, řkouce: Vyplňte díla svá, úkol denní v den jeho, jako když sláma byla.'),
(1547837,54,2,5,14,'I biti jsou šafáři synů Izraelských, kteréž ustanovili nad nimi úředníci Faraonovi, a mluveno k nim: Proč jste nevyplnili úkolu svého v díle cihel, jako prvé, ani včera ani dnes?'),
(1547838,54,2,5,15,'I přišli šafáři synů Izraelských, a volali k Faraonovi, řkouce: Proč tak děláš služebníkům svým?'),
(1547839,54,2,5,16,'Slámy se nedává služebníkům tvým, a říkají nám: Dělejte cihly; a hle, služebníci tvoji biti bývají, a hřeší lid tvůj.'),
(1547840,54,2,5,17,'I řekl: Zahálíte, zahálíte, a protož mluvíte: Poďme, obětujme Hospodinu.'),
(1547841,54,2,5,18,'Protož nyní jděte, dělejte; slámy se vám dávati nebude, ale vy summu cihel vyplňujte.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547842,54,2,5,19,'Vidouce šafáři synů Izraelských, že zle s nimi, poněvadž řečeno: Neujmete počtu cihel vašich z úkolu denního v den jeho,'),
(1547843,54,2,5,20,'Potkali se s Mojžíšem a Aronem, kteříž stáli, aby jim vstříc vyšli, když by se vraceli od Faraona.'),
(1547844,54,2,5,21,'A mluvili jim: Pohlediž Hospodin na vás, a suď; nebo zošklivili jste nás před Faraonem a služebníky jeho, a dali jste meč v ruku jejich, aby nás zamordovali.'),
(1547845,54,2,5,22,'I navrátil se Mojžíš k Hospodinu a řekl: Pane, proč jsi tyto zlé věci uvedl na lid tento? Proč jsi mne sem poslal?'),
(1547846,54,2,5,23,'Nebo od té chvíle, jakž jsem všel k Faraonovi, abych mluvil jménem tvým, hůře nakládá s lidem tímto, a ty jsi vždy nevysvobodil lidu svého.'),
(1547847,54,2,6,1,'Odpověděl Hospodin Mojžíšovi: Nyní uzříš, co učiním Faraonovi; nebo v ruce silné propustí je, a v ruce mocné vyžene je z země své.'),
(1547848,54,2,6,2,'Mluvil ještě Bůh k Mojžíšovi a řekl jemu: Já jsem Hospodin.'),
(1547849,54,2,6,3,'Ukázalť jsem se zajisté Abrahamovi, Izákovi a Jákobovi v tom, že jsem Bůh silný všemohoucí; ale v jménu svém, Hospodin, nejsem poznán od nich.'),
(1547850,54,2,6,4,'K tomu utvrdil jsem smlouvu svou s nimi, že jim dám zemi Kananejskou, zemi putování jejich, v níž pohostinu byli.'),
(1547851,54,2,6,5,'Nad to, já slyšel jsem křik synů Izraelských, kteréž Egyptští v službu podrobují, a rozpomenul jsem se na smlouvu svou.'),
(1547852,54,2,6,6,'Protož pověz synům Izraelským: Já jsem Hospodin, a vyvedu vás z robot Egyptských, a vytrhnu vás z služby jejich, a vysvobodím vás v ruce vztažené a skrze soudy veliké.'),
(1547853,54,2,6,7,'A vezmu vás sobě za lid, a budu vám za Boha; a zvíte, že jsem Hospodin Bůh váš, vysvobozující vás z robot Egyptských.'),
(1547854,54,2,6,8,'Uvedu vás také do země, o níž jsem, zdvihna ruku svou, přisáhl, že ji dám Abrahamovi, Izákovi a Jákobovi; a dám ji vám v dědictví; Já Hospodin.'),
(1547855,54,2,6,9,'I mluvil tak Mojžíš synům Izraelským; ale neslyšeli Mojžíše pro úzkost ducha a službu přetěžkou.'),
(1547856,54,2,6,10,'Protož mluvil Hospodin Mojžíšovi, řka:'),
(1547857,54,2,6,11,'Vejdi, mluv Faraonovi králi Egyptskému, ať propustí syny Izraelské z země své.'),
(1547858,54,2,6,12,'I mluvil Mojžíš před Hospodinem, řka: Hle, synové Izraelští neposlechli mne, kterakž tedy poslechne mne Farao, a já jsem zpozdilý v řeči?'),
(1547859,54,2,6,13,'I mluvil Hospodin Mojžíšovi a Aronovi, a přikázaní dal jim k synům Izraelským a k Faraonovi králi Egyptskému, aby vyvedli syny Izraelské z země Egyptské.'),
(1547860,54,2,6,14,'Tito jsou přední v čeledech otců svých. Synové Rubenovi, prvorozeného Izraelova: Enoch, Fallu, Ezron a Charmi. Ty jsou čeledi Rubenovy.'),
(1547861,54,2,6,15,'Synové pak Simeonovi: Jamuel, Jamin, Ahod, Jachin, Sohar a Saul, syn Kananejské. Ty jsou čeledi Simeonovy.'),
(1547862,54,2,6,16,'A tato jsou jména synů Léví v rodech jejich: Gerson, Kahat a Merari. Let pak života Léví bylo sto třidceti a sedm let.'),
(1547863,54,2,6,17,'Synové Gerson: Lebni a Semei po čeledech svých.'),
(1547864,54,2,6,18,'A synové Kahat: Amram, Izar, Hebron a Uziel. Let pak života Kahat bylo sto třidceti a tři léta.'),
(1547865,54,2,6,19,'A synové Merari: Moholi a Musi. Ty jsou čeledi Léví v rodech svých.'),
(1547866,54,2,6,20,'Pojal pak Amram ženu Jochebed, tetu svou, sobě za manželku, kterážto porodila mu Arona a Mojžíše. A let života Amramova bylo sto třidceti a sedm let.'),
(1547867,54,2,6,21,'Synové také Izarovi: Chore, Nefega Zechri.'),
(1547868,54,2,6,22,'A synové Uzielovi: Mizael, Elzafan a Sethri.'),
(1547869,54,2,6,23,'Pojal pak Aron Alžbětu, dceru Aminadabovu, sestru Názonovu, sobě za manželku; kterážto porodila jemu Nádaba, Abiu, Eleazara a Itamara.'),
(1547870,54,2,6,24,'Synové pak Chore: Asser, Elkana a Abiazaf. Ty jsou čeledi Choritských.'),
(1547871,54,2,6,25,'Eleazar pak syn Aronův vzal jednu ze dcer Putielových sobě za manželku; kteráž mu porodila Fínesa. Ti jsou přední z otců Levítských po čeledech svých.'),
(1547872,54,2,6,26,'To jest ten Aron a Mojžíš, jimž řekl Hospodin: Vyveďte syny Izraelské z země Egyptské po houfích jejich.'),
(1547873,54,2,6,27,'Tito jsou, kteříž mluvili Faraonovi, králi Egyptskému, aby vyvedli syny Izraelské z Egypta; toť jest ten Mojžíš a Aron.'),
(1547874,54,2,6,28,'Stalo se pak, když mluvil Hospodin k Mojžíšovi v zemi Egyptské,'),
(1547875,54,2,6,29,'Že mu řekl takto: Já Hospodin; mluv k Faraonovi, králi Egyptskému, všecko, což já mluvím tobě.'),
(1547876,54,2,6,30,'A řekl Mojžíš před Hospodinem: Aj, já jsem zpozdilý v řeči, kterakž tedy poslouchati mne bude Farao?'),
(1547877,54,2,7,1,'I řekl Hospodin Mojžíšovi: Aj, ustanovil jsem tě za Boha Faraonovi; Aron pak bratr tvůj bude prorokem tvým.'),
(1547878,54,2,7,2,'Ty mluviti budeš všecko, což tobě přikáži; Aron pak bratr tvůj mluviti bude k Faraonovi, aby propustil syny Izraelské z země své.'),
(1547879,54,2,7,3,'Ale jáť zatvrdím srdce Faraonovo, a množiti budu znamení svá a zázraky své v zemi Egyptské.'),
(1547880,54,2,7,4,'Aniž poslechne vás Farao. I vzložím ruku svou na Egypt, a vyvedu vojska svá, lid svůj, syny Izraelské, z země Egyptské skrze soudy veliké.'),
(1547881,54,2,7,5,'I zvědíť Egyptští, že já jsem Hospodin, když vztáhnu ruku svou na Egypt; a vyvedu syny Izraelské z prostředku jich.'),
(1547882,54,2,7,6,'Tedy učinil Mojžíš a Aron tak; jakž přikázal jim Hospodin, tak učinili.'),
(1547883,54,2,7,7,'A byl Mojžíš v osmdesáti, Aron pak v osmdesáti a třech letech, když mluvili s Faraonem.'),
(1547884,54,2,7,8,'I řekl Hospodin Mojžíšovi a Aronovi takto:'),
(1547885,54,2,7,9,'Když mluviti k vám bude Farao, řka: Ukažte od sebe zázrak, tedy díš Aronovi: Vezmi hůl svou, a povrz před Faraonem, i obrátí se v hada.'),
(1547886,54,2,7,10,'Tedy všel Mojžíš s Aronem k Faraonovi, a učinili tak, jakž přikázal Hospodin; a povrhl Aron hůl svou před Faraonem i před služebníky jeho, a obrácena jest v hada.'),
(1547887,54,2,7,11,'Povolal pak také Farao mudrců a čarodějníků; a učinili i ti čarodějníci Egyptští skrze čáry své tolikéž.'),
(1547888,54,2,7,12,'Nebo povrhl každý z nich hůl svou, a obráceny jsou v hady; ale požřela hůl Aronova hole jejich.'),
(1547889,54,2,7,13,'I posililo se srdce Faraonovo, a neuposlechl jich, tak jakž byl mluvil Hospodin.'),
(1547890,54,2,7,14,'Protož řekl Hospodin Mojžíšovi: Obtížilo se srdce Faraonovo; nechce propustiti lidu toho.'),
(1547891,54,2,7,15,'Jdi k Faraonovi ráno, aj, půjde ven k vodě, a stůj naproti němu při břehu řeky; a hůl, kteráž obrácena byla v hada, vezmeš do ruky své.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547892,54,2,7,16,'A díš mu: Hospodin Bůh Hebrejský poslal mne k tobě, aťbych řekl: Propusť lid můj, aby sloužili mi na poušti; a aj, neuposlechls až dosavad.'),
(1547893,54,2,7,17,'Protož takto praví Hospodin: Po tomto poznáš, že já jsem Hospodin: Aj, já udeřím holí, kteráž jest v ruce mé, na vody, kteréž jsou v řece, a obráceny budou v krev.'),
(1547894,54,2,7,18,'A ryby, kteréž jsou v řece, pomrou; i nasmradí se řeka, a ustávati budou Egyptští, hledajíce vody, kterouž by pili z řeky.'),
(1547895,54,2,7,19,'Protož řekl Hospodin Mojžíšovi: Rci Aronovi: Vezmi hůl svou, a vztáhni ruku svou na vody Egyptské, na řeky jejich, na potoky jejich, i na jezera jejich, a na všecka shromáždění vod jejich, aby se obrátily v krev; i bude krev po vší zemi Egyptské, tak v nádobách dřevěných, jako kamenných.'),
(1547896,54,2,7,20,'Tedy učinili tak Mojžíš a Aron, jakž byl přikázal Hospodin; a zdvihna hůl, udeřil v vodu, kteráž byla v řece, před očima Faraonovýma a před očima služebníků jeho; i obráceny jsou všecky vody, kteréž byly v řece, v krev.'),
(1547897,54,2,7,21,'Ryby pak, kteréž byly v řece, pomřely, a nasmradila se řeka, tak že nemohli Egyptští píti vody z řeky; a byla krev po vší zemi Egyptské.'),
(1547898,54,2,7,22,'To též učinili i čarodějníci Egyptští skrze čáry své. I zsililo se srdce Faraonovo, aby neuposlechl jich, tak jakž byl mluvil Hospodin.'),
(1547899,54,2,7,23,'A odvrátiv se Farao, přišel do domu svého; a ani k tomu nepřiložil srdce svého.'),
(1547900,54,2,7,24,'Kopali pak všickni Egyptští vůkol řeky, hledajíce vody ku pití; nebo nemohli píti vody z řeky.'),
(1547901,54,2,7,25,'A vyplnilo se dní sedm, jakž ranil Hospodin řeku.'),
(1547902,54,2,8,1,'I mluvil Hospodin k Mojžíšovi: Vejdi k Faraonovi a rci jemu: Takto praví Hospodin: Propusť lid můj, ať mi slouží.'),
(1547903,54,2,8,2,'Pakli nebudeš chtíti propustiti, aj, já raním všecky krajiny tvé žabami.'),
(1547904,54,2,8,3,'A vydá řeka množství žab, kteréž vystoupí a polezou do domu tvého a do pokoje, v němž líháš, a na ložce tvé, a do domů služebníků tvých i lidu tvého, a do pecí tvých a do těsta tvého.'),
(1547905,54,2,8,4,'I na tebe a na lid tvůj, i na všecky služebníky tvé polezou žáby.'),
(1547906,54,2,8,5,'I řekl Hospodin Mojžíšovi: Rci Aronovi: Vztáhni ruku svou s holí svou na řeky, na potoky a na jezera, a vyveď žáby na zemi Egyptskou.'),
(1547907,54,2,8,6,'I vztáhl Aron ruku svou na vody Egyptské; a vystoupily žáby a přikryly zemi Egyptskou.'),
(1547908,54,2,8,7,'A učinili tolikéž čarodějníci skrze své čáry; a udělali, že vyšly žáby na zemi Egyptskou.'),
(1547909,54,2,8,8,'Tedy Farao povolav Mojžíše a Arona, řekl: Modlte se Hospodinu, ať odejme žáby ode mne a od lidu mého; a propustím ten lid, aby obětovali Hospodinu.'),
(1547910,54,2,8,9,'I řekl Mojžíš Faraonovi: Poctím tě tím, a pověz, kdy bych se měl modliti za tě a za služebníky tvé, a za lid tvůj, aby vypléněny byly žáby od tebe, i z domů tvých; toliko v řece zůstanou.'),
(1547911,54,2,8,10,'Kterýžto odpověděl: Zítra. A Mojžíš řekl: Podlé slova tvého nechť jest, abys věděl, že žádného takového není, jako Hospodin Bůh náš.'),
(1547912,54,2,8,11,'I odejdou žáby od tebe a od domů tvých, i od služebníků tvých a od lidu tvého; toliko v řece zůstanou.'),
(1547913,54,2,8,12,'Tedy vyšel Mojžíš s Aronem od Faraona. I volal Mojžíš k Hospodinu, aby odjaty byly žáby, kteréž byl dopustil na Faraona.'),
(1547914,54,2,8,13,'I učinil Hospodin podlé slova Mojžíšova; a vymřely žáby z domů, ze vsí i z polí.'),
(1547915,54,2,8,14,'I shrnuli je na hromady; a nasmradila se země.'),
(1547916,54,2,8,15,'Vida pak Farao, že by dáno bylo oddechnutí, více zatvrdil se v srdci svém, a neuposlechl jich, jakož byl mluvil Hospodin.'),
(1547917,54,2,8,16,'I řekl Hospodin Mojžíšovi: Rci k Aronovi: Vztáhni hůl svou, a udeř v prach země, aby obrátil se v stěnice na vší zemi Egyptské.'),
(1547918,54,2,8,17,'Kteříž učinili tak. Nebo vztáhl Aron ruku svou s holí svou, a udeřil prach země. I byly stěnice na lidech i hovadech; všecken prach země obrátil se v stěnice ve vší zemi Egyptské.'),
(1547919,54,2,8,18,'Dělali také tak čarodějníci skrze čáry své, aby vyvedli stěnice, ale nemohli. A byly stěnice na lidech i hovadech.'),
(1547920,54,2,8,19,'Tedy řekli čarodějníci Faraonovi: Prst Boží toto jest. A posililo se srdce Faraonovo, aniž poslechl jich, jakož mluvil Hospodin.'),
(1547921,54,2,8,20,'Řekl pak Hospodin Mojžíšovi: Vstaň ráno a stůj před Faraonem. Hle vyjde k vodě, a díš k němu: Takto praví Hospodin: Propusť lid můj, ať mi slouží.'),
(1547922,54,2,8,21,'Pakli nepropustíš lidu mého, hle, já pošli na tě a na služebníky tvé, a na lid tvůj, a na domy tvé směsici všelikých škodlivých žížal; a naplněni budou domové Egyptští těmi žížalami, nad to i země ta, na níž oni jsou.'),
(1547923,54,2,8,22,'A oddělím v ten den zemi Gesen, v níž lid můj zůstává, aby tam nebylo směsice té; abys věděl, že jsem já Hospodin u prostřed země.'),
(1547924,54,2,8,23,'A vysvobozením rozdíl učiním mezi lidem svým a lidem tvým. Zítra bude znamení toto.'),
(1547925,54,2,8,24,'I učinil Hospodin tak. Nebo přišla těžká směsice škodlivých žížal na dům Faraonův,a do domů služebníků jeho i na všecku zemi Egyptskou; a nakazila se země od té směsice.'),
(1547926,54,2,8,25,'Povolal pak Farao Mojžíše a Arona, a řekl: Jděte, obětujte Bohu svému tu v zemi.'),
(1547927,54,2,8,26,'I řekl Mojžíš: Nenáleží nám tak činiti; nebo ohavnost Egyptských obětovali bychom Hospodinu Bohu našemu. A jestliže bychom obětovali to, což jest ohavnost před očima Egyptských, zdaž by nás neukamenovali?'),
(1547928,54,2,8,27,'Cestou tří dnů půjdeme na poušť, a obětovati budeme Hospodinu Bohu našemu, jakž nám rozkázal.'),
(1547929,54,2,8,28,'I řekl Farao: Já propustím vás, abyste obětovali Hospodinu Bohu svému na poušti, však dále abyste nikoli neodcházeli. Modltež se za mne.'),
(1547930,54,2,8,29,'Odpověděl Mojžíš: Aj, já vycházím od tebe, a modliti se budu Hospodinu, aby odešla ta směsice od tebe, od služebníků tvých i od lidu tvého zítra; avšak ať Farao více nezklamává, nepropouštěje lidu, aby obětovali Hospodinu.'),
(1547931,54,2,8,30,'A vyšed Mojžíš od Faraona, modlil se Hospodinu.'),
(1547932,54,2,8,31,'I učinil Hospodin podlé slova Mojžíšova, a odjal tu směsici od Faraona, od služebníků jeho i od lidu jeho, tak že ani jedné žížaly nezůstalo.'),
(1547933,54,2,8,32,'Ale Farao ztížil srdce své také i tehdáž, a nepropustil lidu.'),
(1547934,54,2,9,1,'Tedy řekl Hospodin Mojžíšovi: Vejdi k Faraonovi, a mluv k němu: Takto praví Hospodin, Bůh Hebrejský: Propusť lid můj, ať mi slouží.'),
(1547935,54,2,9,2,'Pakli nebudeš chtíti propustiti, než předce držeti je budeš:'),
(1547936,54,2,9,3,'Aj, ruka Hospodinova bude na dobytku tvém, kterýž jest na poli, na koních, na oslích, na velbloudích, na volích a na ovcech, mor těžký velmi.'),
(1547937,54,2,9,4,'A učiní Hospodin rozdíl mezi dobytky Izraelských a mezi dobytky Egyptských, aby nic neumřelo ze všeho, což jest synů Izraelských.'),
(1547938,54,2,9,5,'A uložil Hospodin čas jistý, řka: Zítra učiní Hospodin věc takovou na zemi.'),
(1547939,54,2,9,6,'I učinil Hospodin tu věc na zejtří, a pomřel všecken dobytek Egyptským; z dobytku pak synů Izraelských ani jedno neumřelo.'),
(1547940,54,2,9,7,'I poslal Farao, a aj, neumřelo z dobytků Izraelských ani jedno. Ale obtíženo jest srdce Faraonovo, a nepropustil lidu.'),
(1547941,54,2,9,8,'I řekl Hospodin Mojžíšovi a Aronovi: Vezměte sobě plné hrsti své popela z peci, a ať jej sype Mojžíš k nebi před očima Faraonovýma.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547942,54,2,9,9,'I obrátí se v prach po vší zemi Egyptské, a budou z něho na lidech i na hovadech vředové prýštící se neštovicemi po vší zemi Egyptské.'),
(1547943,54,2,9,10,'Nabravše tedy popela z peci, stáli před Faraonem, a sypal jej Mojžíš k nebi. I byli vředové plní neštovic, prýštící se na lidech i na hovadech.'),
(1547944,54,2,9,11,'Aniž mohli čarodějníci státi před Mojžíšem pro vředy; nebo byli vředové na čarodějnících i na všech Egyptských.'),
(1547945,54,2,9,12,'I zsilil Hospodin srdce Faraonovo, a neposlechl jich, tak jakž byl mluvil Hospodin k Mojžíšovi.'),
(1547946,54,2,9,13,'Tedy řekl Hospodin Mojžíšovi: Vstana ráno, postav se před Faraonem, a rci k němu: Takto praví Hospodin, Bůh Hebrejský: Propusť lid můj, ať mi slouží.'),
(1547947,54,2,9,14,'Nebo já teď již pošli všecky rány své na srdce tvé, i na služebníky tvé a na lid tvůj, abys věděl, žeť není podobného mně na vší zemi.'),
(1547948,54,2,9,15,'Nebo nyní, když jsem vztáhl ruku svou, byl bych tebe také ranil i lid tvůj morem tím; a tak bys byl vyhlazen z země.'),
(1547949,54,2,9,16,'Ale však proto jsem tě zachoval, abych ukázal na tobě moc svou, a aby vypravovali jméno mé na vší zemi.'),
(1547950,54,2,9,17,'Ještě ty pozdvihuješ se proti lidu mému, nechtěje ho propustiti?'),
(1547951,54,2,9,18,'Aj, já dštíti budu zítra v tentýž čas krupobitím těžkým náramně, jakéhož nebylo v Egyptě od toho dne, jakž založen jest, až do tohoto času.'),
(1547952,54,2,9,19,'Protož nyní pošli, shromažď dobytek svůj a cokoli máš na poli. Na všecky lidi i hovada, kteráž by nalezena byla na poli, a nebyla by shromážděna do domu, spadne krupobití, a pomrou.'),
(1547953,54,2,9,20,'Kdo tedy z služebníků Faraonových ulekl se slova Hospodinova, svolal hbitě služebníky své i dobytek svůj do domu.'),
(1547954,54,2,9,21,'Ale kdož nepřiložil srdce svého k slovu Hospodinovu, nechal služebníků svých a dobytka svého na poli.'),
(1547955,54,2,9,22,'I řekl Hospodin Mojžíšovi: Vztáhni ruku svou k nebi, ať jest krupobití po vší zemi Egyptské, na lidi i na hovada i na všelikou bylinu polní v zemi Egyptské.'),
(1547956,54,2,9,23,'Tedy vztáhl Mojžíš hůl svou k nebi, a Hospodin vydal hřímání a krupobití. I sstoupil oheň na zem, a dštil Hospodin krupobitím na zemi Egyptskou.'),
(1547957,54,2,9,24,'I bylo krupobití a oheň smíšený s krupobitím těžký velmi, jakéhož nebylo nikdy ve vší zemi Egyptské, jakž v ní bydliti lidé začali.'),
(1547958,54,2,9,25,'I ztloukly kroupy po vší zemi Egyptské, cožkoli bylo na poli od člověka až do hovada; všecku také bylinu polní potloukly kroupy, i všecko stromoví na poli zpřerážely.'),
(1547959,54,2,9,26,'Toliko v zemi Gesen, v níž byli synové Izraelští, nebylo krupobití.'),
(1547960,54,2,9,27,'Poslav tedy Farao, povolal Mojžíše a Arona a řekl jim: Zhřešil jsem i nyní. Hospodinť jest spravedlivý, ale já a lid můj bezbožní jsme.'),
(1547961,54,2,9,28,'Modlte se Hospodinu, (nebo dosti jest), ať není hřímání Božího a krupobití. Tedy propustím vás, aniž déle zůstávati budete.'),
(1547962,54,2,9,29,'I řekl jemu Mojžíš: Když vyjdu ven z města, rozprostru ruce své k Hospodinu, a hřímání přestane, i krupobití více nebude, abys poznal, že Hospodinova jest země.'),
(1547963,54,2,9,30,'Ale vím, že ani ty, ani služebníci tvoji ještě se nebudete báti tváři Hospodina Boha.'),
(1547964,54,2,9,31,'I potlučen jest len a ječmen; nebo ječmen se byl vymetal, len také byl v hlávkách.'),
(1547965,54,2,9,32,'Ale pšenice a špalda nebyla ztlučena, nebo pozdní byla.'),
(1547966,54,2,9,33,'Tedy Mojžíš vyšed od Faraona z města, rozprostřel ruce své k Hospodinu. I přestalo hřímání a krupobití, a ani déšť nelil se na zemi.'),
(1547967,54,2,9,34,'Uzřev pak Farao, že přestal déšť a krupobití a hřímání, opět hřešil; a více obtížil srdce své, on i služebníci jeho.'),
(1547968,54,2,9,35,'I zsililo se srdce Faraonovo, a nepropustil synů Izraelských, tak jakž byl mluvil Hospodin skrze Mojžíše.'),
(1547969,54,2,10,1,'I řekl Hospodin Mojžíšovi: Vejdi k Faraonovi, ačkoli jsem já obtížil srdce jeho, a srdce služebníků jeho, abych učinil divy tyto své u prostřed nich;'),
(1547970,54,2,10,2,'A abys ty vypravoval v uši synů svých i vnuků svých, co jsem učinil v Egyptě, a znamení má, kteráž jsem prokázal na nich; abyste věděli, že já jsem Hospodin.'),
(1547971,54,2,10,3,'I všel Mojžíš s Aronem k Faraonovi, a řekli jemu: Takto praví Hospodin Bůh Hebrejský: Dokavadž nechceš se ponížiti přede mnou? Propusť lid můj, ať mi slouží.'),
(1547972,54,2,10,4,'Pakli nechceš propustiti lidu mého, aj, já uvedu zítra kobylky na krajinu tvou.'),
(1547973,54,2,10,5,'A přikryjí svrchek země, aby jí nebylo viděti, a snědí ostatky pozůstalé, kteříž vám zanecháni jsou po krupobití; zhryzou vám také každý strom pučící se na poli.'),
(1547974,54,2,10,6,'A naplní domy tvé, i domy všech služebníků tvých, a domy všech Egyptských; čehož neviděli otcové tvoji a otcové otců tvých, od počátku bytu svého na zemi až do dne tohoto. A odvrátiv se, vyšel od Faraona.'),
(1547975,54,2,10,7,'Řekli pak služebníci Faraonovi k němu: Dokavadž tento bude nám osídlem? Propusť ty muže, ať slouží Hospodinu Bohu svému. Zdaž ještě nevíš, že zkažen jest Egypt?'),
(1547976,54,2,10,8,'I zavolán jest Mojžíš s Aronem před Faraona. Jimž řekl: Jděte, služte Hospodinu Bohu svému. Kdo jsou ti, kteříž jíti mají?'),
(1547977,54,2,10,9,'A odpověděl Mojžíš: S dítkami i s starými našimi půjdeme, s syny i s dcerami našimi, s ovcemi a s větším dobytkem naším odejdeme; nebo slavnost Hospodinovu držeti máme.'),
(1547978,54,2,10,10,'Tedy řekl jim: Nechať jest tak Hospodin s vámi, jako já propustím vás i dítky vaše. Hleďte, nebo zlé jest před tváři vaší.'),
(1547979,54,2,10,11,'Nebudeť tak. Jděte vy sami muži, a služte Hospodinu, nebo toho vy toliko žádáte. I vyhnáni jsou od tváři Faraonovy.'),
(1547980,54,2,10,12,'Tedy řekl Hospodin Mojžíšovi: Vztáhni ruku svou na zemi Egyptskou pro kobylky, ať vystoupí na zemi Egyptskou, a sežerou všelikou bylinu země té, cožkoli zůstalo po krupobití.'),
(1547981,54,2,10,13,'I vztáhl Mojžíš hůl svou na zemi Egyptskou; a Hospodin uvedl vítr východní na zemi, aby vál celého toho dne a celou noc. A když bylo ráno, vítr východní přinesl kobylky.'),
(1547982,54,2,10,14,'A vystoupily kobylky na všecku zemi Egyptskou, a připadly na všecky končiny Egyptské nesčíslně. Před těmi nebylo takových kobylek, aniž po těch takové budou.'),
(1547983,54,2,10,15,'I přikryly veškeren svrchek země, tak že pro ně nebylo lze znáti země; a sežraly všelikou bylinu země, a všeliké ovoce na stromích, kteréž zůstalo po krupobití; a nepozůstalo nic zeleného na stromích a bylinách polních ve vší zemi Egyptské.'),
(1547984,54,2,10,16,'Tedy Farao spěšně povolav Mojžíše s Aronem, řekl: Zhřešil jsem proti Hospodinu Bohu vašemu, i proti vám.'),
(1547985,54,2,10,17,'Ale nyní, odpusť, prosím, hřích můj aspoň tento, a modlte se Hospodinu Bohu vašemu, ať jen tuto smrt odejme ode mne.'),
(1547986,54,2,10,18,'Protož vyšed Mojžíš od Faraona, modlil se Hospodinu.'),
(1547987,54,2,10,19,'I obrátil Hospodin vítr západní tuhý velmi, kterýžto zachvátiv kobylky, uvrhl je do moře Rudého, tak že nezůstalo žádné kobylky ve vší krajině Egyptské.'),
(1547988,54,2,10,20,'Ale obtížil Hospodin srdce Faraonovo, a nepropustil synů Izraelských.'),
(1547989,54,2,10,21,'I řekl Hospodin Mojžíšovi: Vztáhni ruku svou k nebi, a bude tma na zemi Egyptské, a makati ji budou.'),
(1547990,54,2,10,22,'I vztáhl Mojžíš ruku svou k nebi, a byla tma přehustá po vší zemi Egyptské za tři dni.'),
(1547991,54,2,10,23,'Aniž viděl jeden druhého, a aniž kdo vstal z místa svého za tři dni; ale synové Izraelští všickni měli světlo v příbytcích svých.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1547992,54,2,10,24,'Potom povolav Farao Mojžíše, řekl: Jděte, služte Hospodinu. Toliko ovce vaše a větší dobytek váš nechať zůstane, také dítky vaše půjdou s vámi.'),
(1547993,54,2,10,25,'Odpověděl Mojžíš: Dáš také v ruce naše oběti a zápaly, kteréž bychom obětovali Hospodinu Bohu našemu.'),
(1547994,54,2,10,26,'A protož také dobytek náš půjde s námi, a nezůstane ani kopyta; nebo z nich vezmeme ku poctě Hospodinu Bohu našemu. My pak nevíme, čím sloužiti máme Hospodinu, dokudž nepřijdeme tam.'),
(1547995,54,2,10,27,'Zatvrdil pak Hospodin srdce Faraonovo, tak že nechtěl propustiti jich.'),
(1547996,54,2,10,28,'I řekl mu Farao: Odejdi ode mne, a varuj se, abys více neviděl tváři mé; nebo v který den uzříš tvář mou, umřeš.'),
(1547997,54,2,10,29,'Odpověděl Mojžíš: Dobře jsi řekl; neuzřímť více tváři tvé.'),
(1547998,54,2,11,1,'Řekl pak byl Hospodin Mojžíšovi: Ještě ránu jednu uvedu na Faraona a na Egypt, potom propustí vás odsud; propustí docela, anobrž vypudí vás odsud.'),
(1547999,54,2,11,2,'Mluv nyní v uši lidu, ať vypůjčí jeden každý od bližního svého, a každá od bližní své klínotů stříbrných a klínotů zlatých.'),
(1548000,54,2,11,3,'A dal Hospodin milost lidu před očima Egyptských. (Sám také Mojžíš veliký byl velmi v zemi Egyptské, před očima služebníků Faraonových i před očima lidu.)'),
(1548001,54,2,11,4,'I řekl Mojžíš: Takto praví Hospodin: O půlnoci já půjdu prostředkem Egypta.'),
(1548002,54,2,11,5,'A pomře všecko prvorozené v zemi Egyptské, od prvorozeného Faraonova, jenž seděti měl na stolici jeho, až do prvorozeného děvky, kteráž jest při žernovu, i všecko prvorozené hovad.'),
(1548003,54,2,11,6,'I bude křik veliký po vší zemi Egyptské, jakéhož nebylo prvé, a jakéhož nikdy nebude více.'),
(1548004,54,2,11,7,'U synů pak Izraelských nikdež nehne pes jazykem svým, ovšem pak ani člověk ani hovado, abyste věděli, že rozdíl učinil Hospodin mezi Egyptskými a Izraelskými.'),
(1548005,54,2,11,8,'I sstoupí všickni tito služebníci tvoji ke mně, a skláněti mi se budou, řkouce: Vyjdi, ty i všecken lid, kterýž jest pod správou tvou; a potom vyjdu. A vyšel od Faraona s velikým hněvem.'),
(1548006,54,2,11,9,'I řekl Hospodin Mojžíšovi: Neposlechneť vás Farao, abych rozmnožil zázraky své v zemi Egyptské.'),
(1548007,54,2,11,10,'Ale Mojžíš a Aron činili všecky ty zázraky před Faraonem; Hospodin pak zatvrdil srdce Faraonovo, tak že nepropustil synů Izraelských z země své.'),
(1548008,54,2,12,1,'Mluvil pak Hospodin k Mojžíšovi a k Aronovi v zemi Egyptské, řka:'),
(1548009,54,2,12,2,'Tento měsíc počátek měsíců vám bude; první vám bude mezi měsíci ročními.'),
(1548010,54,2,12,3,'Mluvte ke všemu shromáždění Izraelskému, řkouce: Desátého dne měsíce tohoto vezmete sobě jeden každý beránka po čeledech, beránka na každý dům.'),
(1548011,54,2,12,4,'Byl-li by pak dům tak malý, že by s beránka býti nemohl, přivezme souseda svého, kterýž jest blízký domu jeho, podlé počtu duší; jeden každý počte tolik osob, kolikž by jich snísti mohlo beránka.'),
(1548012,54,2,12,5,'Beránka bez vady, samce ročního míti budete, kteréhož z ovcí aneb z koz vezmete.'),
(1548013,54,2,12,6,'A chovati ho budete až do čtrnáctého dne měsíce tohoto; a zabije ho všecko množství shromáždění Izraelského k večerou.'),
(1548014,54,2,12,7,'A vezmouce krve, pomaží obou veřejí a nade dveřmi u domů, v nichž jej jísti budou.'),
(1548015,54,2,12,8,'I budou jísti noci té maso pečené ohněm, s chleby přesnými; s bylinami hořkými jísti jej budou.'),
(1548016,54,2,12,9,'Nebudete jísti z něho nic surového ani v vodě vařeného, ale pečené ohněm, s hlavou jeho i s nohami a droby.'),
(1548017,54,2,12,10,'Nezanecháte z něho ničehož do jitra; pakli by co pozůstalo z něho až do jitra, ohněm spálíte.'),
(1548018,54,2,12,11,'Takto jej pak jísti budete: Bedra svá přepásaná míti budete, obuv svou na nohách svých a hůl svou v ruce své, a jísti budete s chvátáním; nebo Jití jest Hospodinovo.'),
(1548019,54,2,12,12,'V tu noc zajisté půjdu po zemi Egyptské, a budu bíti všecko prvorozené v zemi Egyptské, od člověka až do hovada, a nade všemi bohy Egyptskými učiním soud: Já Hospodin.'),
(1548020,54,2,12,13,'Krev pak ta na domích, v nichž budete, budeť vám na znamení; a když uzřím krev, pominu vás, a nebude mezi vámi rána zahubující, když bíti budu prvorozené v zemi Egyptské.'),
(1548021,54,2,12,14,'A budeť vám den ten na památku, a slaviti jej budete slavný Hospodinu po rodech svých; právem věčným slaviti jej budete.'),
(1548022,54,2,12,15,'Za sedm dní přesné chleby jísti budete, a hned prvního dne vyprázdníte kvas z domů vašich; nebo kdožkoli jedl by co kvašeného od prvního až do sedmého dne, vyhlazena bude duše ta z Izraele.'),
(1548023,54,2,12,16,'A v den první budeť shromáždění svaté; dne také sedmého shromáždění svaté míti budete. Žádného díla nebude děláno v nich; toliko čehož se užívá k jídlu od každého, to samo připraveno bude od vás.'),
(1548024,54,2,12,17,'A ostříhati budete přesnic, nebo v ten den vyvedl jsem vojska vaše z země Egyptské; protož zachovávati budete den ten po rodech svých právem věčným.'),
(1548025,54,2,12,18,'Prvního měsíce, čtrnáctého dne téhož měsíce, u večer jísti budete chleby přesné, až do dne jedenmecítmého téhož měsíce k večerou.'),
(1548026,54,2,12,19,'Za sedm dní nebude nalezeno kvasu v domích vašich; nebo kdo by koli jedl něco kvašeného, vyhlazena bude duše ta z shromáždění Izraelského, tak příchozí jako zrozený v zemi.'),
(1548027,54,2,12,20,'Nic kvašeného jísti nebudete, ale ve všech příbytcích vašich jísti budete chleby přesné.'),
(1548028,54,2,12,21,'Tedy svolal Mojžíš všecky starší Izraelské, a řekl jim: Vybeřte a vezměte sobě beránka po čeledech svých, a zabíte Fáze.'),
(1548029,54,2,12,22,'Vezmete také svazček yzopu, a omočíte v krvi, kteráž bude v medenici, a pomažete nade dveřmi a na obou veřejích tou krví, kteráž bude v nádobě; z vás pak žádný nevycházej ze dveří domu svého až do jitra.'),
(1548030,54,2,12,23,'Neboť půjde Hospodin, aby bil Egypt, a kde uzří krev nade dveřmi a na obou veřejích, přeskočí Hospodin ty dvéře, aniž dopustí zhoubci vjíti do domů vašich k hubení.'),
(1548031,54,2,12,24,'Protož ostříhati budete věci této za ustanovení tobě i synům tvým až na věky.'),
(1548032,54,2,12,25,'A když vejdete do země, kterouž dá Hospodin vám, jakž zaslíbil, zachovávati budete službu tuto.'),
(1548033,54,2,12,26,'Když by pak řekli vám synové vaši: Jaká jest to služba vaše?'),
(1548034,54,2,12,27,'Tedy díte: Obět Fáze toto jest Hospodinu, kterýž pominul domů synů Izraelských v Egyptě, když bil Egypt, domy pak naše vysvobodil. A lid sklonivše hlavy, poklonu učinili.'),
(1548035,54,2,12,28,'A rozšedše se synové Izraelští, učinili, jakž byl Hospodin přikázal Mojžíšovi a Aronovi; tak a nejinak učinili.'),
(1548036,54,2,12,29,'Stalo se pak o půlnoci, pobil Hospodin všecko prvorozené v zemi Egyptské, od prvorozeného Faraonova, kterýž seděti měl na stolici jeho, až do prvorozeného vězně, kterýž byl v žaláři, i všecko prvorozené hovad.'),
(1548037,54,2,12,30,'Tedy vstal Farao noci té, a všickni služebníci jeho i všickni Egyptští, a vzešel křik veliký v Egyptě; nebo žádného nebylo domu, v němž by nebylo něčeho mrtvého.'),
(1548038,54,2,12,31,'A povolav Mojžíše a Arona v noci, řekl: Vstaňte, vyjděte z prostředku lidu mého, i vy i synové Izraelští, a odejdouce, služte Hospodinu, jakž jste mluvili.'),
(1548039,54,2,12,32,'Ovce také vaše i voly vaše vezměte, jakž jste žádali, a jděte; a dejte mi také požehnání.'),
(1548040,54,2,12,33,'I nutkali Egyptští lid, aby co nejrychleji vyšli z země; nebo pravili: Všickni již teď zemřeme.'),
(1548041,54,2,12,34,'Protož vzal lid těsto své, prvé než zkysalo, obaliv je v šaty své, na ramena svá.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548042,54,2,12,35,'Učinili pak synové Izraelští podlé rozkazu Mojžíšova; nebo vyžádali byli od Egyptských klínotů stříbrných a zlatých, i šatů.'),
(1548043,54,2,12,36,'A Hospodin dal milost lidu před očima Egyptských, tak že půjčovali jim. I obloupili Egyptské.'),
(1548044,54,2,12,37,'Tedy táhli synové Izraelští z Ramesses k Sochot, okolo šestkrát sto tisíc pěších, mužů toliko kromě dětí.'),
(1548045,54,2,12,38,'Ano také jiného lidu mnoho vyšlo s nimi, ovec také a volů, dobytka velmi mnoho.'),
(1548046,54,2,12,39,'I napekli z těsta, kteréž vynesli z Egypta, koláčů nekvašených; nebo ještě bylo nezkynulo, proto že vypuzeni byli z Egypta, a nemohli prodlévati, a ani pokrmů na cestu nepřipravili sobě.'),
(1548047,54,2,12,40,'Čas pak bydlení synů Izraelských, kteříž byli v Egyptě, byl čtyři sta a třidceti let.'),
(1548048,54,2,12,41,'A když se vyplnilo čtyři sta a třidceti let, právě toho dne vyšla všecka vojska Hospodinova z země Egyptské.'),
(1548049,54,2,12,42,'Noc tato pilně ostříhána býti má Hospodinu, v níž vyvedl je z země Egyptské; tať tedy noc Hospodinova ostříhána bude ode všech synů Izraelských po národech jejich.'),
(1548050,54,2,12,43,'I řekl Hospodin Mojžíšovi a Aronovi: Tentoť bude řád při slavnosti Fáze: Žádný cizozemec nebude jísti z něho.'),
(1548051,54,2,12,44,'Každý pak služebník váš za stříbro koupený, když by obřezán byl, teprv jísti bude z něho.'),
(1548052,54,2,12,45,'Příchozí a nájemník nebude jísti z něho.'),
(1548053,54,2,12,46,'V témž domě jísti jej budeš, nevyneseš z domu ven masa jeho; a kostí v něm nezlámete.'),
(1548054,54,2,12,47,'Všecko shromáždění Izraelské tak s ním učiní.'),
(1548055,54,2,12,48,'Jestliže by pak cizozemec bydlil s tebou pohostinu, a slaviti by chtěl Fáze Hospodinu, prvé obřezán bude každý pohlaví mužského; a tehdy přistoupí k slavení jeho, a bude jako tu v zemi zrozený; žádný pak neobřezaný nebude jísti z něho.'),
(1548056,54,2,12,49,'Jednostejné právo bude tu zrodilému a příchozímu, kterýž jest pohostinu u prostřed vás.'),
(1548057,54,2,12,50,'Tedy učinili všickni synové Izraelští, jakž přikázal Hospodin Mojžíšovi a Aronovi; tak učinili.'),
(1548058,54,2,12,51,'A tak stalo se právě toho dne, že vyvedl Hospodin syny Izraelské z země Egyptské s vojsky jejich.'),
(1548059,54,2,13,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1548060,54,2,13,2,'Posvěť mi všeho prvorozeného, cožkoli otvírá každý život mezi syny Izraelskými, tak z lidí jako z hovad, nebo mé jest.'),
(1548061,54,2,13,3,'Protož řekl Mojžíš lidu: Pamatujte na den tento, v kterémž jste vyšli z Egypta, z domu služby; nebo v silné ruce vyvedl vás odsud Hospodin, aniž kdo jez co kvašeného.'),
(1548062,54,2,13,4,'Dnes vycházíte vy, měsíce Abib.'),
(1548063,54,2,13,5,'Když tedy uvede tě Hospodin do země Kananejských, Hetejských, Amorejských, Hevejských a Jebuzejských, tak jakž přisáhl otcům tvým, a dá tobě zemi oplývající mlékem a strdí: tedy vykonávati budeš službu tuto v tento měsíc.'),
(1548064,54,2,13,6,'Za sedm dní jísti budeš chleby přesné, dne pak sedmého slavnost bude Hospodinova.'),
(1548065,54,2,13,7,'Přesní chlebové jedeni budou za dnů sedm, aniž spatříno bude u tebe co kvašeného, aniž se uhlédá u tebe kvas ve všech končinách tvých.'),
(1548066,54,2,13,8,'A vypravovati budeš synu svému v ten den, řka: Proto, což mi učinil Hospodin, když jsem vycházel z Egypta.'),
(1548067,54,2,13,9,'A budeť tobě to jako nějaké znamení na ruce tvé, a jako památka před očima tvýma, aby zákon Hospodinův byl v ústech tvých; nebo v ruce silné vyvedl tě Hospodin z Egypta.'),
(1548068,54,2,13,10,'Protož zachovávati budeš ustanovení toto v čas jistý, rok po roce.'),
(1548069,54,2,13,11,'A když by tě uvedl Hospodin do země Kananejských, tak jakž přisáhl tobě a otcům tvým, a dal by ji tobě:'),
(1548070,54,2,13,12,'Tedy všecko, což otvírá život, oddělíš Hospodinu, i každý plod hovada tvého otvírající život, což by koli bylo samců, Hospodinovo jest.'),
(1548071,54,2,13,13,'Každé pak prvorozené osle vyplatíš hovádkem; pakli bys nevyplatil, zlom jemu šíji; každého také prvorozeného člověka mezi syny svými vyplatíš.'),
(1548072,54,2,13,14,'A když by se tebe vzeptal syn tvůj potom, a řekl: Co jest to? tedy povíš jemu: V ruce silné vyvedl nás Hospodin z Egypta, z domu služebnosti.'),
(1548073,54,2,13,15,'Nebo když se byl zatvrdil Farao, a nechtěl nás propustiti, pobil Hospodin všecko prvorozené v zemi Egyptské, od prvorozeného z lidí, až do prvorozeného z hovad; i tou příčinou já obětuji Hospodinu všecky samce otvírající život, ale všecko prvorozené z synů svých vyplacuji.'),
(1548074,54,2,13,16,'Mějž to tedy jako znamení na ruce své, a jako náčelník mezi očima svýma, že v ruce silné vyvedl nás Hospodin z Egypta.'),
(1548075,54,2,13,17,'Stalo se pak, když pustil Farao lid, že nevedl jich Bůh cestou země Filistinské, ačkoli bližší byla; nebo řekl Bůh: Aby nepykal lid, když by uzřel, an válka nastává, a nevrátili se do Egypta.'),
(1548076,54,2,13,18,'Ale obvedl Bůh lid cestou přes poušť, kteráž jest při moři Rudém. A vojensky zpořádaní vyšli synové Izraelští z země Egyptské.'),
(1548077,54,2,13,19,'Vzal také Mojžíš kosti Jozefovy s sebou; nebo byl přísahou zavázal syny Izraelské, řka: Jistotně navštíví vás Bůh, protož vyneste odsud kosti mé s sebou.'),
(1548078,54,2,13,20,'Vytáhše tedy z Sochot, položili se v Etam při kraji pouště.'),
(1548079,54,2,13,21,'Hospodin pak předcházel je ve dne v sloupu oblakovém, aby je vedl cestou, v noci pak v sloupu ohnivém, aby svítil jim, aby ve dne i v noci jíti mohli.'),
(1548080,54,2,13,22,'Neodjal sloupu oblakového ve dne, ani ohnivého sloupu v noci od tváři toho lidu.'),
(1548081,54,2,14,1,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1548082,54,2,14,2,'Mluv k synům Izraelským, ať navrátíce se, rozbijí stany před Fiarot, mezi Magdalem a mořem, proti Belsefon; naproti němu rozbijete stany při moři.'),
(1548083,54,2,14,3,'A dí Farao o synech Izraelských: Ssouženi jsou na zemi, sevřela je poušť.'),
(1548084,54,2,14,4,'I zatvrdím srdce Faraonovo, a honiti je bude, a oslaven budu v Faraonovi a ve všem vojsku jeho; a zvědí Egyptští, že já jsem Hospodin. I učinili tak.'),
(1548085,54,2,14,5,'Povědíno pak bylo králi Egyptskému, že by lid utíkal. I obráceno jest srdce Faraonovo a služebníků jeho proti lidu, a řekli: Co jsme to učinili, že jsme propustili Izraele, aby nesloužil nám?'),
(1548086,54,2,14,6,'Protož zapřáhl do svého vozu, a lid svůj vzal s sebou.'),
(1548087,54,2,14,7,'A vzal šest set vozů vybraných, i všecky vozy Egyptské, nad nimiž nade všemi byli hejtmané.'),
(1548088,54,2,14,8,'I zatvrdil Hospodin srdce Faraona krále Egyptského, tak že honil syny Izraelské; synové pak Izraelští vyšli v ruce vyvýšené.'),
(1548089,54,2,14,9,'I honili je Egyptští, a postihli je, když se položili při moři, všickni vozové Faraonovi, a jezdci jeho i vojsko jeho podlé Fiarot, před Belsefon.'),
(1548090,54,2,14,10,'A když se přiblížil Farao, pozdvihli synové Izraelští očí svých, a aj, Egyptští táhnou za nimi. I báli se velmi, a volali synové Izraelští k Hospodinu.'),
(1548091,54,2,14,11,'A řekli Mojžíšovi: Zdali proto, že nebylo hrobů v Egyptě, vyvedl jsi nás, abychom zemřeli na poušti? Co jsi nám to učinil, že jsi vyvedl nás z Egypta?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548092,54,2,14,12,'Zdali jsme toho nemluvili tobě ještě v Egyptě, řkouce: Nech nás, ať sloužíme Egyptským? Nebo lépe bylo nám sloužiti Egyptským, než zemříti na poušti.'),
(1548093,54,2,14,13,'I řekl Mojžíš lidu: Nebojte se, stůjte a vizte spasení Hospodinovo, kteréž vám způsobí dnes; nebo Egyptských, kteréž jste viděli dnes, neuzříte nikdy více až na věky.'),
(1548094,54,2,14,14,'Hospodin bojovati bude za vás, a vy mlčeti budete.'),
(1548095,54,2,14,15,'I řekl Hospodin Mojžíšovi: Co voláš ke mně? Mluv synům Izraelským, ať jdou předce.'),
(1548096,54,2,14,16,'Ty pak zdvihni hůl svou, a vztáhni ruku svou na moře, a rozděl je; a nechať jdou synové Izraelští prostředkem moře po suše.'),
(1548097,54,2,14,17,'Jáť pak, aj, já zatvrdím srdce Egyptských, a vejdou za nimi; i budu oslaven v Faraonovi, a ve všem vojsku jeho, v vozích jeho i v jezdcích jeho.'),
(1548098,54,2,14,18,'A zvědí Egyptští, že já jsem Hospodin, když oslaven budu v Faraonovi, v vozích jeho a v jezdcích jeho.'),
(1548099,54,2,14,19,'I bral se anděl Boží, kterýž byl prvé předcházel vojsko Izraelské, a šel z zadu za nimi; nebo hnul se sloup oblakový, kterýž byl před nimi, a stál z zadu za nimi.'),
(1548100,54,2,14,20,'A přišed mezi vojska Egyptských a vojska Izraelská, byl Egyptským oblakem a tmou, Izraelským pak osvěcoval noc, tak aby nepřiblížili se jedni k druhým přes celou noc.'),
(1548101,54,2,14,21,'I vztáhl Mojžíš ruku svou na moře, a Hospodin rozdělil moře větrem východním prudce vějícím přes celou noc; a učinil moře v suchost, když se rozstoupily vody.'),
(1548102,54,2,14,22,'Tedy šli synové Izraelští prostředkem moře po suše, a vody jim byly jako zed po pravé i po levé straně.'),
(1548103,54,2,14,23,'A honíce je Egyptští, vešli za nimi do prostřed moře, všecka jízda Faraonova, vozové i jízdní jeho.'),
(1548104,54,2,14,24,'Stalo se pak v bdění jitřním, že pohleděl Hospodin na vojska Egyptských z sloupu ohně a oblaku, a zmátl vojsko Egyptské.'),
(1548105,54,2,14,25,'A odjal kola vozů jejich, aby je těžce táhli. I řekli Egyptští: Utecme před Izraelem, nebo Hospodin bojuje za ně proti Egyptským.'),
(1548106,54,2,14,26,'Tedy řekl Hospodin Mojžíšovi: Vztáhni ruku svou na moře, ať se zase vrátí vody na Egyptské, na vozy jejich a na jezdce jejich.'),
(1548107,54,2,14,27,'I vztáhl Mojžíš ruku svou na moře, a navrátilo se moře ráno k moci své, a Egyptští utíkali proti němu; a vrazil Hospodin Egyptské do prostřed moře.'),
(1548108,54,2,14,28,'A navrátivše se vody, zatopily vozy i jezdce se vším vojskem Faraonovým, což jich koli vešlo za nimi do moře, tak že nezůstal z nich ani jeden.'),
(1548109,54,2,14,29,'Ale synové Izraelští šli po suchu prostředkem moře, a vody jim byly místo zdi po pravé i po levé straně.'),
(1548110,54,2,14,30,'A tak vysvobodil Hospodin v ten den Izraele z ruky Egyptských; a viděl Izrael Egyptské mrtvé na břehu mořském.'),
(1548111,54,2,14,31,'Viděl také Izrael moc velikou, kterouž prokázal Hospodin na Egyptských. I bál se lid Hospodina, a věřili Hospodinu i Mojžíšovi, služebníku jeho.'),
(1548112,54,2,15,1,'Tehdy zpíval Mojžíš a synové Izraelští píseň tuto Hospodinu, a řekli takto: Zpívati budu Hospodinu, neboť jest slavně zveleben; koně i s jezdcem uvrhl do moře.'),
(1548113,54,2,15,2,'Síla má a píseň jest Hospodin, nebo vysvobodil mne. Onť jest Bůh můj silný, protož stánek vzdělám jemu; onť jest Bůh otce mého, protož vyvyšovati ho budu.'),
(1548114,54,2,15,3,'Hospodin jest udatný bojovník, Hospodin jméno jeho.'),
(1548115,54,2,15,4,'Vozy Faraonovy i vojsko jeho uvrhl do moře; a nejpřednější hejtmané jeho ztopeni jsou v moři Rudém.'),
(1548116,54,2,15,5,'Propasti přikryly je; vpadli do hlubiny jako kámen.'),
(1548117,54,2,15,6,'Pravice tvá, Hospodine, zvelebena jest v síle, pravice tvá, ó Hospodine, potřela nepřítele.'),
(1548118,54,2,15,7,'A ve mnohé vyvýšenosti své podvrátil jsi povstávající proti tobě; pustils hněv svůj, kterýžto sežral je jako strniště.'),
(1548119,54,2,15,8,'A duchem chřípí tvých shromážděny jsou vody, stály tekuté vody jako hromada, ssedly se propasti u prostřed moře.'),
(1548120,54,2,15,9,'Řekl nepřítel: Honiti budu, dohoním se, budu děliti loupeže, nasytí se jimi duše má, vytrhnu meč svůj, zahladí je ruka má.'),
(1548121,54,2,15,10,'Povanul jsi větrem svým, i přikrylo je moře; pohlceni jsou jako olovo v prudkých vodách.'),
(1548122,54,2,15,11,'Kdo podobný tobě mezi silnými, ó Hospodine? Kdo jest tak, jako ty, velebný v svatosti, hrozný v chvalách, činící divy?'),
(1548123,54,2,15,12,'Vztáhls pravici svou, i požřela je země.'),
(1548124,54,2,15,13,'Zprovodíš v milosrdenství svém lid tento, kterýž jsi vykoupil; laskavě povedeš jej v síle své k příbytku svatosti své.'),
(1548125,54,2,15,14,'Uslyší lidé, bouřiti se budou; bolest zachvátí obyvatele Filistinské.'),
(1548126,54,2,15,15,'Tedy zkormoucena budou knížata Idumejská, silné Moábské podejme strach, rozplynou se všickni obyvatelé Kananejští.'),
(1548127,54,2,15,16,'Připadne na ně strach a lekání, pro velikost ramene tvého; mlčeti budou jako kámen, dokudž nepřejde lid tvůj, ó Hospodine, dokudž nepřejde lid ten, kteréhožs sobě dobyl.'),
(1548128,54,2,15,17,'Uvedeš je, a štípíš je na hoře dědictví svého, na místě, kteréž jsi k příbytku svému připravil, Hospodine, v svatyni, kterouž utvrdí ruce tvé, Pane.'),
(1548129,54,2,15,18,'Hospodin kralovati bude na věky věků.'),
(1548130,54,2,15,19,'Nebo vešli koni Faraonovi s vozy jeho i s jezdci jeho do moře, a obrátil na ně Hospodin vody mořské, synové pak Izraelští šli po suše u prostřed moře.'),
(1548131,54,2,15,20,'I vzala Maria prorokyně, sestra Aronova, buben v ruku svou, a vyšly za ní všecky ženy s bubny a s píšťalami.'),
(1548132,54,2,15,21,'I odpovídala jim Maria: Zpívejte Hospodinu, poněvadž slavně zveleben jest; koně i s jezdcem uvrhl do moře.'),
(1548133,54,2,15,22,'Hnul pak Mojžíš lidem Izraelským od moře Rudého, a táhli na poušť Sur. I šli tři dni po poušti, a nenalezli vod.'),
(1548134,54,2,15,23,'A přišedše do Marah, nemohli píti vod z Marah, nebo byly hořké; protož nazváno jest jméno jeho Marah.'),
(1548135,54,2,15,24,'Z té příčiny reptal lid na Mojžíše, řka: Co budeme píti?'),
(1548136,54,2,15,25,'I volal k Hospodinu, a ukázal mu Hospodin dřevo, kteréž jakž uvrhl do vod, učiněny jsou sladké vody. Tu vydal jemu práva a soudy, a tu ho zkusil.'),
(1548137,54,2,15,26,'A řekl: Jestliže skutečně poslouchati budeš hlasu Hospodina Boha svého, a činiti budeš, což spravedlivého jest před očima jeho, a nakloníš uší k přikázaním jeho, a ostříhati budeš všech ustavení jeho: žádné nemoci, kterouž jsem dopustil na Egypt, nedopustím na tebe; nebo já jsem Hospodin, kterýž tě uzdravuji.'),
(1548138,54,2,15,27,'I přišli do Elim, kdež bylo dvanácte studnic vod a sedmdesáte palm; i rozbili tu stany při vodách.'),
(1548139,54,2,16,1,'Když se pak hnuli z Elim, přišlo všecko množství synů Izraelských na poušť Sin, kteráž jest mezi Elim a Sinai, v patnáctý den druhého měsíce po vyjití z země Egyptské.'),
(1548140,54,2,16,2,'I reptalo všecko shromáždění synů Izraelských proti Mojžíšovi a proti Aronovi na poušti.'),
(1548141,54,2,16,3,'A mluvili jim synové Izraelští: Ó bychom byli zemřeli od ruky Hospodinovy v zemi Egyptské, když jsme sedávali nad hrnci masa, když jsme se najídali chleba do sytosti! A teď vyvedli jste nás na tuto poušť, abyste zmořili všecko shromáždění toto hladem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548142,54,2,16,4,'I řekl Hospodin Mojžíšovi: Aj, já dám vám chleba s nebe jako déšť, a vycházeti bude lid a sbírati, což by postačilo na každý den, abych ho zkusil, bude-li choditi v zákoně mém, či nebude.'),
(1548143,54,2,16,5,'V den pak šestý přistrojí sobě to, co přinesou; a bude toho dvakrát více, než toho, což sbírati mají na každý den.'),
(1548144,54,2,16,6,'Tedy mluvil Mojžíš a Aron všechněm synům Izraelským: U večer poznáte, že Hospodin vyvedl vás z země Egyptské.'),
(1548145,54,2,16,7,'A ráno uzříte slávu Hospodinovu; neboť jest slyšel reptání vaše proti Hospodinu. My zajisté co jsme, že repcete proti nám?'),
(1548146,54,2,16,8,'Mluvil dále Mojžíš: Z toho, pravím, poznáte, když vám dá Hospodin u večer masa, abyste se najedli, a chleba ráno do sytosti, poněvadž slyšel Hospodin reptání vaše, jimiž jste na něj reptali. Nebo my co jsme? Ne proti námť jsou reptání vaše, ale proti Hospodinu.'),
(1548147,54,2,16,9,'I řekl Mojžíš Aronovi: Mluv ke všemu shromáždění synů Izraelských: Přistuptež před oblíčej Hospodinův; neboť jest slyšel reptání vaše.'),
(1548148,54,2,16,10,'Stalo se pak, když mluvil Aron ke všemu shromáždění synů Izraelských, že se obrátili tváří k poušti, a aj, sláva Hospodinova ukázala se v oblaku.'),
(1548149,54,2,16,11,'(A již byl mluvil Hospodin k Mojžíšovi, řka:'),
(1548150,54,2,16,12,'Slyšelť jsem reptání synů Izraelských. Mluviž jim a pověz: K večerou jísti budete maso, a ráno chlebem nasyceni budete, abyste poznali, že já jsem Hospodin Bůh váš.)'),
(1548151,54,2,16,13,'Tedy stalo se u večer, že přiletěly křepelky a přikryly tábor; ráno pak spadla rosa okolo táboru.'),
(1548152,54,2,16,14,'A když přestalo padání rosy, aj, ukázalo se po vrchu pouště drobného cosi a okrouhlého, drobného jako jíní na zemi.'),
(1548153,54,2,16,15,'Což vidouce synové Izraelští, řekli jeden druhému: Man jest toto. Nebo nevěděli, co by bylo. Tedy řekl jim Mojžíš: To jest ten chléb, kterýž vám dal Hospodin ku pokrmu.'),
(1548154,54,2,16,16,'To jest, o čemž přikázal Hospodin: Nasbírejte sobě toho každý k svému pokrmu; gomer na jednoho člověka vedlé počtu osob vašich, každý na ty, kteříž jsou v stanu jeho, vezmete.'),
(1548155,54,2,16,17,'I učinili tak synové Izraelští, a nasbírali jiní více, jiní méně.'),
(1548156,54,2,16,18,'Potom měřili na gomer. A nezbylo tomu, kdo nasbíral mnoho, a ten, kdo nasbíral málo, neměl nedostatku; ale každý, což mohl snísti, nasbíral.'),
(1548157,54,2,16,19,'I řekl jim Mojžíš: Žádný ať nic z toho nepozůstavuje k jitru.'),
(1548158,54,2,16,20,'Ale neuposlechli Mojžíše. Nebo někteří zanechali díl z toho až do jitra; i zčervivělo a zsmradilo se. Pročež rozhněval se na ně Mojžíš.'),
(1548159,54,2,16,21,'Tak tedy sbírali to každého jitra, každý což snísti mohl. A když horké bylo slunce, tedy se ta manna rozpouštěla.'),
(1548160,54,2,16,22,'Když pak bylo v den šestý, nasbírali toho chleba dvojnásobně, po dvou gomer na každého; protož přišla všecka knížata toho shromáždění, a pověděli Mojžíšovi.'),
(1548161,54,2,16,23,'Kterýžto řekl jim: Toť jest, což mluvil Hospodin: Odpočinutí soboty svaté Hospodinu bude zítra. Což byste měli péci, pecte, a což byste vařiti měli, vařte dnes; což pak koli zbude, nechte sobě a schovejte to k jitru.'),
(1548162,54,2,16,24,'Protož schovali to do rána, jakž přikázal Mojžíš; a nezsmradilo se, ani v něm červů nebylo.'),
(1548163,54,2,16,25,'I řekl Mojžíš: Jeztež to dnes, poněvadž sobota jest dnes Hospodinu; dnes toho nenaleznete na poli.'),
(1548164,54,2,16,26,'Po šest dní budete to sbírávati, den pak sedmý sobota jest; nebude bývati manny v ní.'),
(1548165,54,2,16,27,'Stalo se pak dne sedmého, že vyšli někteří z lidu sbírat, a nenašli.'),
(1548166,54,2,16,28,'Tedy řekl Hospodin Mojžíšovi: I dokudž zpěčovati se budete přikázaní mých ostříhati a zákonů mých?'),
(1548167,54,2,16,29,'Viztež, žeť Hospodin vám dal sobotu, a proto on vám dává v den šestý chleba na dva dni. Zůstaňte každý v svém, aniž kdo vycházej z místa svého v den sedmý.'),
(1548168,54,2,16,30,'I odpočinul lid v den sedmý.'),
(1548169,54,2,16,31,'Nazval pak lid Izraelský jméno toho chleba man; kterýž byl jako símě koliandrové, a bílý, a chut jeho jako koláče s medem.'),
(1548170,54,2,16,32,'Řekl také Mojžíš: Toť jest, což přikázal Hospodin: Naplň gomer tou mannou, aby chována byla na budoucí věky vaše, aby viděli pokrm, kterýž jsem vám dával jísti na poušti, když jsem vás vyvedl z země Egyptské.'),
(1548171,54,2,16,33,'I řekl Mojžíš Aronovi: Vezmi jedno věderce, a vsyp do něho plné gomer manny; a nech jí před tváří Hospodinovou, aby chována byla na budoucí věky vaše.'),
(1548172,54,2,16,34,'A protož jakž byl přikázal Hospodin Mojžíšovi, nechal jí Aron před svědectvím, aby tu chována byla.'),
(1548173,54,2,16,35,'Jedli pak synové Izraelští mannu za čtyřidceti let, dokudž nevešli do země, v níž bydliti měli; mannu jedli, dokudž nepřišli k končinám země Kananejské.'),
(1548174,54,2,16,36,'Gomer pak jest desátý díl efi.'),
(1548175,54,2,17,1,'Tedy když se odebralo všecko shromáždění synů Izraelských z pouště Sin, po stanovištích svých vedlé rozkazu Hospodinova, položili se v Rafidim, kdež nebylo vod, kteréž by lid píti mohl.'),
(1548176,54,2,17,2,'Protož domlouval se lid na Mojžíše, pravě: Dejte nám vody, abychom pili. Jimž odpověděl Mojžíš: Proč se na mne domlouváte? Proč pokoušíte Hospodina?'),
(1548177,54,2,17,3,'I žíznil tu lid pro nedostatek vod, a reptal na Mojžíše a mluvil: Proč jsi vyvedl nás z Egypta, abys mne s syny i dobytky mými žízní zmořil?'),
(1548178,54,2,17,4,'Tedy volal Mojžíš k Hospodinu, řka: Což mám činiti s tím lidem? Však již tudíž ukamenují mne.'),
(1548179,54,2,17,5,'I řekl Hospodin Mojžíšovi: Jdiž před lidem, pojma s sebou některé z starších Izraelských; hůl také svou kterouž jsi udeřil v vodu, vezmi do ruky své a jdi.'),
(1548180,54,2,17,6,'Aj, já státi budu před tebou tam na skále, na Orébě; i udeříš v skálu, a vyjdou z ní vody, kteréž bude píti lid. I učinil tak Mojžíš před očima starších Izraelských.'),
(1548181,54,2,17,7,'A dal jméno místu tomu Massah a Meribah, pro reptání synů Izraelských, a že pokoušeli Hospodina, řkouce: Jest-li Hospodin u prostřed nás, či není?'),
(1548182,54,2,17,8,'Přitáhl pak Amalech, a bojoval s Izraelem v Rafidim.'),
(1548183,54,2,17,9,'I řekl Mojžíš k Jozue: Vybeř nám některé muže, a vytáhna, bojuj s Amalechem; já zítra státi budu na vrchu hory, a hůl Boží v ruce své míti budu.'),
(1548184,54,2,17,10,'Tedy Jozue udělal tak, jakž mu poručil Mojžíš, a bojoval s Amalechem; Mojžíš pak, Aron a Hur vstoupili na vrch hory.'),
(1548185,54,2,17,11,'A dokudž Mojžíš vzhůru držel ruce své, vítězil Izrael; ale jakž opouštěl ruku svou, přemáhal Amalech.'),
(1548186,54,2,17,12,'Ale že ruce Mojžíšovy byly obtíženy, protož vzavše kámen, podložili pod něho, a on sedl na něm; Aron pak a Hur podpírali ruce jeho, jeden z jedné, druhý z druhé strany. I byly obě ruce jeho vztažené až do západu slunce.'),
(1548187,54,2,17,13,'A tak porazil Jozue Amalecha i lid jeho mečem.'),
(1548188,54,2,17,14,'Mluvil potom Hospodin k Mojžíšovi: Vpiš to do knih na památku, a pilně to vkládej v uši Jozue, že do konce vyhladím památku Amalechovu všudy pod nebem.'),
(1548189,54,2,17,15,'Tedy vzdělal Mojžíš oltář a nazval jméno jeho: Hospodin korouhev má.'),
(1548190,54,2,17,16,'Nebo řekl: Tak má jmenován býti, proto že ruka nad trůnem Hospodinovým osvědčuje boj Hospodinův proti Amalechovi od národu až do národu.'),
(1548191,54,2,18,1,'Uslyšel pak Jetro, kníže Madianské, test Mojžíšův, o všech věcech, kteréž učinil Bůh Mojžíšovi a Izraelovi, lidu svému, že vyvedl Hospodin Izraele z Egypta.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548192,54,2,18,2,'A vzal Jetro, test Mojžíšův, Zeforu manželku Mojžíšovu, kterouž byl odeslal,'),
(1548193,54,2,18,3,'A dva syny její, z nichž jméno jednoho Gerson; nebo řekl: Příchozí jsem byl v zemi cizí;'),
(1548194,54,2,18,4,'Jméno pak druhého Eliezer; nebo řekl: Bůh otce mého spomocník můj byl, a vytrhl mne od meče Faraonova.'),
(1548195,54,2,18,5,'I přišel Jetro, test Mojžíšův, s syny jeho i s ženou jeho k Mojžíšovi na poušť, kdež se byl položil při hoře Boží.'),
(1548196,54,2,18,6,'A vzkázal Mojžíšovi: Já, test tvůj Jetro, jdu k tobě, i žena tvá a oba synové její s ní.'),
(1548197,54,2,18,7,'I vyšel Mojžíš proti testi svému, a pokloniv se, políbil ho. I ptal se jeden druhého, jak se má; potom vešli do stanu.'),
(1548198,54,2,18,8,'A vypravoval Mojžíš testi svému všecko, což učinil Hospodin Faraonovi a Egyptským pro Izraele, a o všech nevolech, kteréž přicházely na ně na cestě, a jak je vysvobodil Hospodin.'),
(1548199,54,2,18,9,'I radoval se Jetro ze všeho dobrého, což učinil Hospodin Izraelovi, a že vytrhl jej z ruky Egyptských.'),
(1548200,54,2,18,10,'A řekl Jetro: Požehnaný Hospodin, kterýž vytrhl vás z ruky Egyptských a z ruky Faraonovy, kterýž vytrhl ten lid z poroby Egyptské.'),
(1548201,54,2,18,11,'Nyní jsem poznal, že větší jest Hospodin nade všecky bohy; nebo touž věcí, kterouž se vyvyšovali, on je převýšil.'),
(1548202,54,2,18,12,'A vzal Jetro, test Mojžíšův, zápal a oběti, kteréž obětoval Bohu. Potom přišel Aron a všickni starší Izraelští, aby jedli chléb s tchánem Mojžíšovým před Bohem.'),
(1548203,54,2,18,13,'Nazejtří pak posadil se Mojžíš, aby soudil lid; a stál lid před Mojžíšem od jitra až do večera.'),
(1548204,54,2,18,14,'Vida pak test Mojžíšův všecku práci jeho při lidu, řekl: Co jest to, což děláš s lidem? Proč ty sám sedíš, a všecken lid stojí před tebou od jitra až do večera?'),
(1548205,54,2,18,15,'Odpověděl Mojžíš tchánu svému: Přichází ke mně lid raditi se s Bohem.'),
(1548206,54,2,18,16,'Když mají o nějakou věc činiti, přicházejí ke mně, a soud činím mezi stranami, a oznamuji rady Boží a ustanovení jeho.'),
(1548207,54,2,18,17,'I řekl jemu test Mojžíšův: Nedobře děláš.'),
(1548208,54,2,18,18,'Tudíž tak ustaneš i ty i lid, kterýž s tebou jest. Nad možnost tvou těžká jest tato věc, nebudeš jí moci sám dosti učiniti.'),
(1548209,54,2,18,19,'Protož nyní uposlechni řeči mé; poradím tobě, a bude Bůh s tebou. Stůj ty za lid před Bohem, a donášej věci nesnadné k Bohu.'),
(1548210,54,2,18,20,'A vysvětluj jim řády a zákony, a oznamuj jim cestu, po níž by šli, a co by dělati měli.'),
(1548211,54,2,18,21,'Vyhledej také ze všeho lidu muže statečné, bohabojné, muže pravdomluvné, kteříž v nenávisti mají lakomství, a ustanov z nich knížata nad tisíci, setníky, padesátníky a desátníky.'),
(1548212,54,2,18,22,'Oni ať soudí lid každého času. Což bude většího, vznesou na tebe, a menší pře sami nechť soudí; a tak lehčeji bude tobě, když jiní ponesou břímě s tebou.'),
(1548213,54,2,18,23,'Jestliže to učiníš a rozkážeť Bůh, budeš moci trvati; také i všecken lid tento navracovati se bude k místům svým pokojně.'),
(1548214,54,2,18,24,'Tedy uposlechl Mojžíš řeči tchána svého, a učinil všecko, což on řekl.'),
(1548215,54,2,18,25,'A vybral Mojžíš muže statečné ze všeho Izraele, a ustanovil je hejtmany nad lidem, knížata nad tisíci, setníky, padesátníky a desátníky,'),
(1548216,54,2,18,26,'Kteříž soudili lid každého času. Nesnadnější věci vznášeli na Mojžíše, všecky pak menší pře sami soudili.'),
(1548217,54,2,18,27,'Potom propustil Mojžíš tchána svého; i odšel do země své.'),
(1548218,54,2,19,1,'Měsíce třetího po vyjití synů Izraelských z země Egyptské, v ten den přišli na poušť Sinai.'),
(1548219,54,2,19,2,'Nebo hnuvše se z Rafidim, přišli až na poušť Sinai a položili se na té poušti; a tu rozbili Izraelští stany naproti hoře.'),
(1548220,54,2,19,3,'Mojžíš pak vstoupil k Bohu. A mluvil hlasem k němu Hospodin s té hory, řka: Takto díš domu Jákobovu, a oznámíš synům Izraelským:'),
(1548221,54,2,19,4,'Sami jste viděli, co jsem učinil Egyptským, a jak jsem vás nesl na křídlách orličích, a přivedl jsem vás k sobě.'),
(1548222,54,2,19,5,'Protož nyní, jestliže skutečně poslouchati budete hlasu mého, a ostříhati smlouvy mé, budete mi lid zvláštní mimo všecky lidi, ačkoli má jest všecka země.'),
(1548223,54,2,19,6,'A vy budete mi království kněžské a národ svatý. Tať jsou slova, kteráž mluviti budeš synům Izraelským.'),
(1548224,54,2,19,7,'Protož přišel Mojžíš a svolav starší lidu, předložil jim všecka slova ta, kteráž mu přikázal Hospodin.'),
(1548225,54,2,19,8,'Odpověděl pak všecken lid společně, a řekl: Cožkoli mluvil Hospodin, budeme činiti. A oznámil zas Mojžíš Hospodinu slova lidu.'),
(1548226,54,2,19,9,'I řekl Hospodin Mojžíšovi: Aj, já půjdu k tobě v hustém oblaku, aby slyšel lid, když mluviti budu s tebou, ano také, aby tobě věřil na věky. Nebo byl oznámil Mojžíš Hospodinu slova lidu.'),
(1548227,54,2,19,10,'Řekl dále Hospodin Mojžíšovi: Jdi k lidu, a posvěť jich dnes a zítra; a nechť svá roucha zeperou.'),
(1548228,54,2,19,11,'A ať jsou hotovi ke dni třetímu, nebo v den třetí sstoupí Hospodin před očima všeho lidu na horu Sinai.'),
(1548229,54,2,19,12,'Uložíš pak lidu meze všudy vůkol a povíš: Varujte se, abyste nevstupovali na horu, ani nedotýkali se krajů jejích. Kdož by se koli dotkl hory, smrtí umře.'),
(1548230,54,2,19,13,'Nedotkneť se ho ruka, ale ukamenován neb zastřelen bude; buď že by hovado bylo, buď člověk, nebudeť živ. Když se zdlouha troubiti bude, teprv oni vstoupí na horu.'),
(1548231,54,2,19,14,'Sstoupiv tedy Mojžíš s hůry k lidu, posvětil ho; a oni zeprali roucha svá.'),
(1548232,54,2,19,15,'I mluvil k lidu: Buďtež hotovi ke dni třetímu; nepřistupujte k manželkám svým.'),
(1548233,54,2,19,16,'I stalo se dne třetího, když bylo ráno, že bylo hřímání s blýskáním a oblak hustý na té hoře, zvuk také trouby velmi tuhý, až se zhrozil všecken lid, kterýž byl v ležení.'),
(1548234,54,2,19,17,'Tedy Mojžíš vyvedl lid z ležení vstříc Bohu; a lid stál dole pod horou.'),
(1548235,54,2,19,18,'Hora pak Sinai všecka se kouřila, proto že sstoupil na ni Hospodin v ohni, a vystupoval dým její jako dým z vápenice, a třásla se všecka hora velmi hrubě.'),
(1548236,54,2,19,19,'Zvuk také trouby více se rozmáhal, a silil se náramně. Mojžíš mluvil, a Bůh mu odpovídal hlasem.'),
(1548237,54,2,19,20,'Sstoupil pak Hospodin na horu Sinai, na vrch hory; a když povolal Hospodin Mojžíše na vrch hory, vstoupil Mojžíš.'),
(1548238,54,2,19,21,'I řekl Hospodin Mojžíšovi: Sstup, osvědč lidu, ať se nevytrhují k Hospodinu, chtějíce ho viděti, aby nepadlo jich množství;'),
(1548239,54,2,19,22,'Nýbrž ani sami kněží, kteříž, majíce přistupovati k Hospodinu, posvěcují se, aby se neobořil na ně Hospodin.'),
(1548240,54,2,19,23,'Mojžíš pak řekl Hospodinu: Nebudeť moci lid vstoupiti na horu Sinai, poněvadž jsi ty osvědčil nám, řka: Obmez horu a posvěť ji.'),
(1548241,54,2,19,24,'I řekl jemu Hospodin: Jdi, sstup, a potom vstup ty a Aron s tebou. Kněží pak a lid ať se nepokoušejí vstoupiti k Hospodinu, aby se na ně neobořil.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548242,54,2,19,25,'I sešel Mojžíš k lidu, a to jim oznámil.'),
(1548243,54,2,20,1,'I mluvil Bůh všecka slova tato, řka:'),
(1548244,54,2,20,2,'Já jsem Hospodin Bůh tvůj, kterýž jsem tě vyvedl z země Egyptské, z domu služby.'),
(1548245,54,2,20,3,'Nebudeš míti bohů jiných přede mnou.'),
(1548246,54,2,20,4,'Neučiníš sobě rytiny, ani jakého podobenství těch věcí, kteréž jsou na nebi svrchu, ani těch, kteréž na zemi dole, ani těch, kteréž u vodách pod zemí.'),
(1548247,54,2,20,5,'Nebudeš se jim klaněti, ani jich ctíti. Nebo já jsem Hospodin Bůh tvůj, Bůh silný, horlivý, navštěvující nepravost otců na synech do třetího i čtvrtého pokolení těch, kteříž nenávidí mne,'),
(1548248,54,2,20,6,'A činící milosrdenství nad tisíci těmi, kteříž mne milují, a ostříhají přikázaní mých.'),
(1548249,54,2,20,7,'Nevezmeš jména Hospodina Boha svého nadarmo; neboť nenechá bez pomsty Hospodin toho, kdož by bral jméno jeho nadarmo.'),
(1548250,54,2,20,8,'Pomni na den sobotní, abys jej světil.'),
(1548251,54,2,20,9,'Šest dní pracovati budeš, a dělati všeliké dílo své;'),
(1548252,54,2,20,10,'Ale dne sedmého odpočinutí jest Hospodina Boha tvého. Nebudeš dělati žádného díla, ty i syn tvůj i dcera tvá, služebník tvůj i děvka tvá, hovado tvé i příchozí, kterýž jest v branách tvých.'),
(1548253,54,2,20,11,'Nebo v šesti dnech učinil Hospodin nebe a zemi, moře a všecko, což v nich jest, a odpočinul dne sedmého; protož požehnal Hospodin dne sobotního, a posvětil ho.'),
(1548254,54,2,20,12,'Cti otce svého i matku svou, ať se prodlejí dnové tvoji na zemi, kterouž Hospodin Bůh tvůj dá tobě.'),
(1548255,54,2,20,13,'Nezabiješ.'),
(1548256,54,2,20,14,'Nesesmilníš.'),
(1548257,54,2,20,15,'Nepokradeš.'),
(1548258,54,2,20,16,'Nepromluvíš proti bližnímu svému křivého svědectví.'),
(1548259,54,2,20,17,'Nepožádáš domu bližního svého, aniž požádáš manželky bližního svého, ani služebníka jeho, ani děvky jeho, ani vola jeho, ani osla jeho, ani cožkoli jest bližního tvého.'),
(1548260,54,2,20,18,'Veškeren pak lid viděl hřímání to a blýskání, a zvuk trouby, a horu kouřící se. To když viděl lid, pohnuli se a stáli zdaleka.'),
(1548261,54,2,20,19,'A řekli Mojžíšovi: Mluv ty s námi, a poslouchati budeme; a nechť nemluví s námi Bůh, abychom nezemřeli.'),
(1548262,54,2,20,20,'Odpověděl Mojžíš lidu: Nebojte se; nebo pro zkušení vás sám Bůh přišel, aby bázeň jeho byla mezi vámi, abyste nehřešili.'),
(1548263,54,2,20,21,'Tedy stál lid zdaleka; Mojžíš pak přistoupil k mrákotě, kdež byl Bůh.'),
(1548264,54,2,20,22,'I řekl Hospodin Mojžíšovi: Tak povíš synům Izraelským: Vy jste sami viděli, že s nebe mluvil jsem s vámi.'),
(1548265,54,2,20,23,'Protož nevyzdvihujte ničehož ku poctě se mnou; bohů stříbrných a bohů zlatých neučiníte sobě.'),
(1548266,54,2,20,24,'Oltář z země uděláš mi a obětovati budeš na něm zápaly své, a pokojné oběti své, ovce své a voly své. Na kterémkoli místě rozkáži slaviti památku jména svého, přijdu k tobě a požehnám tobě.'),
(1548267,54,2,20,25,'Jestliže mi pak vzděláš oltář kamenný, nedělej ho z kamene tesaného; nebo jestliže pozdvihneš železa na něj, poškvrníš ho.'),
(1548268,54,2,20,26,'Aniž po stupních vstupovati budeš k oltáři mému, aby hanba tvá u něho odkryta nebyla.'),
(1548269,54,2,21,1,'Tito jsou pak soudové, kteréž jim předložíš:'),
(1548270,54,2,21,2,'Jestliže koupíš k službě Žida, šest let sloužiti bude, a sedmého odejde svobodný darmo.'),
(1548271,54,2,21,3,'Přišel-li by sám toliko, sám také odejde; pakli měl ženu, vyjde s ním i žena jeho.'),
(1548272,54,2,21,4,'Jestliže pán jeho dá mu ženu, a ona zrodí jemu syny neb dcery: žena ta i děti její budou pána jeho, on pak sám toliko odejde.'),
(1548273,54,2,21,5,'Pakli by řekl služebník: Miluji pána svého, manželku svou a syny své, nevyjdu svobodný:'),
(1548274,54,2,21,6,'Tedy postaví ho pán jeho před soudci, a přivede ho ke dveřím neb k veřeji,a probodne pán jeho ucho jemu špicí; i zůstaneť služebníkem jeho na věky.'),
(1548275,54,2,21,7,'Když by pak prodal někdo dceru svou, aby byla děvkou, nevyjdeť tak, jako vycházejí služebníci.'),
(1548276,54,2,21,8,'Nelíbila-li by se pánu svému, kterýž jí sobě ještě nezasnoubil, dopustí ji vyplatiti. Lidu cizímu nebude míti práva prodati ji, poněvadž zhřešil proti ní.'),
(1548277,54,2,21,9,'Pakli by synu svému ji zasnoubil, učiníť jí tak, jakž obyčej jest činiti dcerám.'),
(1548278,54,2,21,10,'A dal-li by mu jinou, z stravy její, oděvu jejího, a přívětivosti manželské nic této neujme.'),
(1548279,54,2,21,11,'Neudělal-li by nic z toho trojího, vyjde darmo bez stříbra.'),
(1548280,54,2,21,12,'Kdo by ubil člověka, až by od toho umřel, smrtí umře.'),
(1548281,54,2,21,13,'Když by pak neukládal o bezživotí jeho, než Bůh dal by jej v ruce jeho: tedy uložím tobě místo, do něhož by takový mohl uteci.'),
(1548282,54,2,21,14,'Pakli by kdo tak pyšně sobě počínal proti bližnímu svému, že by ho lstivě zabil, i od oltáře mého odtrhneš jej, aby umřel.'),
(1548283,54,2,21,15,'Kdo by otce svého neb matku svou bil, smrtí ať umře.'),
(1548284,54,2,21,16,'Kdo by pak, ukradna někoho, prodal jej, a nalezen by byl v ruce jeho, smrtí ať umře.'),
(1548285,54,2,21,17,'I ten, kdož by zlořečil otci svému neb mateři své, smrtí ať umře.'),
(1548286,54,2,21,18,'Když by se svadili muži, a urazil by který bližního svého kamenem neb pěstí, a ten by neumřel, než složil se na lůži;'),
(1548287,54,2,21,19,'A potom by povstal a chodil vně o holi své: již nebude vinen ten, kdož urazil; toliko co zatím obmeškal, to jemu nahradí, a na vyhojení jeho naloží.'),
(1548288,54,2,21,20,'Když by pak ubil kdo služebníka svého neb děvku svou kyjem, tak že by umřel mu v ruce jeho: pomstou pomštěno bude nad takovým.'),
(1548289,54,2,21,21,'A však jestliže by den neb dva přečkal, neponese pomsty, nebo jej zaplatil.'),
(1548290,54,2,21,22,'Když by se svadili muži, a urazili ženu těhotnou, tak že by vyšel z ní plod její, však by se zhouba nestala: pokutován bude, jakž by uložil naň muž té ženy, a dá vedlé uznání soudců.'),
(1548291,54,2,21,23,'Pakliť by smrt přišla, tedy dáš život za život,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548292,54,2,21,24,'Oko za oko, zub za zub, ruku za ruku, nohu za nohu,'),
(1548293,54,2,21,25,'Spáleninu za spáleninu, ránu za ránu, modřinu za modřinu.'),
(1548294,54,2,21,26,'Jestliže by kdo urazil služebníka svého v oko, aneb děvku svou v oko, tak že by jej o ně připravil: svobodného jej propustí za oko jeho.'),
(1548295,54,2,21,27,'Pakli by zub služebníku svému neb zub děvce své vyrazil, svobodného jej propustí za zub jeho.'),
(1548296,54,2,21,28,'Jestliže by vůl utrkl muže neb ženu, tak že by umřel člověk: ukamenován bude ten vůl, aniž jedeno bude maso jeho, však pán vola toho bez viny bude.'),
(1548297,54,2,21,29,'Než byl-liť by vůl trkavý prvé, a bylo by to osvědčeno pánu jeho, on pak nezavřel by ho, a v tom zabil by muže neb ženu: vůl ten ukamenován bude, a pán jeho také umře.'),
(1548298,54,2,21,30,'Pakliť mu bude uloženo, aby se vyplatil: tedy dá výplatu za život svůj, jakážkoli na něj uložena bude.'),
(1548299,54,2,21,31,'Buď že by syna utrkl, buď dceru, podlé soudu toho stane se jemu.'),
(1548300,54,2,21,32,'Jestliže by služebníka vůl ztrkal neb děvku, třidceti lotů stříbra dá pánu jeho, a vůl ten bude ukamenován.'),
(1548301,54,2,21,33,'Kdyby kdo odhradil studnici, a neb vykopal někdo studnici, a zase jí nepřikryl, a vpadl by tam vůl neb osel:'),
(1548302,54,2,21,34,'Pán té studnice nahradí to, a peníze položí pánu jeho, a což se zabilo, to sobě míti bude.'),
(1548303,54,2,21,35,'A ustrčil-li by vůl něčí vola sousedova, že byl umřel: tedy prodadí vola toho živého, a podělí se penězi jeho; i s zabitým volem také se rozdělí.'),
(1548304,54,2,21,36,'Pakli vědíno bylo, že vůl byl trkavý prvé, a nezavřel ho pán jeho: bez výmluvy ať dá vola za vola, a zabitý ať mu zůstane.'),
(1548305,54,2,22,1,'Jestliže by kdo ukradl vola aneb dobytče, a zabil by je neb prodal: pět volů navrátí za toho vola, a čtvero dobytčat za to dobytče.'),
(1548306,54,2,22,2,'(Jestliže by zloděj zastižen byl při podkopávání a ubit jsa, umřel by: ten, kdo ho ranil, nebude vinen smrtí.'),
(1548307,54,2,22,3,'Pakli by to ve dne učinil, smrtí vinen bude.) Bez prodlévání ať navrátí; pakli nemá co, prodán bude pro zlodějství své.'),
(1548308,54,2,22,4,'Jestliže nalezena bude v rukou jeho krádež, buď vůl, neb osel, buď dobytče ještě živé, dvénásobně navrátí.'),
(1548309,54,2,22,5,'Jestliže by kdo spásl pole neb vinici, a vpustil hovado své, aby se páslo na cizím poli: což nejlepšího má na poli svém neb vinici své, tím tu škodu nahradí.'),
(1548310,54,2,22,6,'Vyšel-li by oheň, a chytilo by se trní, a shořel by stoh neb stojaté obilí neb pole: nahradí ten, kdož zapálil, to, což shořelo.'),
(1548311,54,2,22,7,'Kdyby někdo dal schovati bližnímu svému peníze neb nádoby, a bylo by ukradeno z domu muže toho, jestliže nalezen bude zloděj, dvojnásobně navrátí.'),
(1548312,54,2,22,8,'Pakli nebude zloděj nalezen, tedy postaven bude pán domu toho před soudce, a přisáhne, že nevztáhl ruky své na věc bližního svého.'),
(1548313,54,2,22,9,'O všelijakou věc, o niž by byla nesnáz, buď o vola neb osla, dobytče neb roucho, pro všelikou věc ztracenou, když by kdo pravil, že to jest: před soudce přijde pře obou dvou; ten, kohož oni vinného usoudí, dvojnásobně navrátí bližnímu svému.'),
(1548314,54,2,22,10,'Jestliže by kdo dal bližnímu svému k chování osla neb vola, neb dobytče a jakékoli hovado, a umřelo by neb ochromělo, neb zajato bylo, že žádný neviděl:'),
(1548315,54,2,22,11,'Přísaha Hospodinova vkročí mezi oba, že nevztáhl ruky své k věci bližního svého; a přijme jej v tom pán věci té, a onen nebude povinen navraceti.'),
(1548316,54,2,22,12,'Pakli by krádeží vzato bylo od něho, navrátiti zase má pánu jeho.'),
(1548317,54,2,22,13,'Pakli by udáveno bylo, postaví svědka a nebude povinen upláceti toho, což udáveno jest.'),
(1548318,54,2,22,14,'Kdyby pak někdo vypůjčil něčeho od bližního svého, a ochromělo by aneb umřelo v nepřítomnosti pána jeho, bez výmluvy navrátí zase.'),
(1548319,54,2,22,15,'Pakli by pán jeho byl s ním, není povinen platiti, poněvadž bylo za peníze najaté, a přišlo za mzdu svou.'),
(1548320,54,2,22,16,'Jestliže by kdo namluvil pannu, kteráž není zasnoubena, a spal by s ní: dáť jí věno, a vezme ji sobě za manželku.'),
(1548321,54,2,22,17,'Pakli by otec její nikoli nechtěl jí dáti jemu, odváží stříbra podlé obyčeje věna panenského.'),
(1548322,54,2,22,18,'Čarodějnici nedáš živu býti.'),
(1548323,54,2,22,19,'Kdo by koli scházel se s hovadem, smrtí ať umře.'),
(1548324,54,2,22,20,'Kdo by obětoval bohům, kromě samému Hospodinu, jako proklatý vyhlazen bude.'),
(1548325,54,2,22,21,'Příchozímu neučiníš křivdy, aniž utiskneš ho; nebo příchozí byli jste v zemi Egyptské.'),
(1548326,54,2,22,22,'Žádné vdovy neb sirotka trápiti nebudete.'),
(1548327,54,2,22,23,'Pakli bez lítosti trápiti je budete, a oni by volali ke mně, vězte, že vyslyším křik jejich.'),
(1548328,54,2,22,24,'A rozhněvá se prchlivost má, i zbiji vás mečem; a budou ženy vaše vdovy a děti vaši sirotci.'),
(1548329,54,2,22,25,'Půjčíš-li peněz lidu mému chudému, kterýž jest s tebou: nebudeš jemu jako lichevník, aniž ho lichvou obtížíš.'),
(1548330,54,2,22,26,'Pakli v základu vezmeš roucho bližního svého, do západu slunce jemu je navrátíš.'),
(1548331,54,2,22,27,'Nebo ten jediný má oděv, to jest roucho, jímž přikrývá tělo své, a na němž spí. Když bude volati ke mně, tedy uslyším, nebo jsem milosrdný.'),
(1548332,54,2,22,28,'Soudcům nebudeš utrhati, a knížeti lidu svého zlořečiti nebudeš.'),
(1548333,54,2,22,29,'Z hojnosti obilí, a tekutých věcí svých neobmeškáš prvotin obětovati. Prvorozeného z synů svých mně dáš.'),
(1548334,54,2,22,30,'Tak učiníš s volem svým a s dobytkem svým: Sedm dní bude s matkou svou, dne pak osmého mně je dáš.'),
(1548335,54,2,22,31,'Lid svatý budete mi, a nebudete jísti masa z udáveného na poli; psu je vržete.'),
(1548336,54,2,23,1,'Nebudeš vynášeti pověsti lživé. Neklaď s bezbožným ruky své, abys měl býti s ním svědek nepravý.'),
(1548337,54,2,23,2,'Nepostoupíš po množství ke zlému,a nebudeš se přimlouvati k rozepři, tak abys se uchýlil po větším počtu k převrácení soudu.'),
(1548338,54,2,23,3,'Ani chudého šanovati nebudeš v při jeho.'),
(1548339,54,2,23,4,'Trefil-li bys na vola nepřítele svého neb osla jeho, an bloudí, obrátíš a dovedeš ho k němu.'),
(1548340,54,2,23,5,'Uzřel-li bys an osel toho, jenž tě má v nenávisti, leží pod břemenem svým, zdaž se zdržíš, abys mu neměl pomoci? Nýbrž opravdově pomůžeš jemu, spolu s tím, kdož tě v nenávisti má.'),
(1548341,54,2,23,6,'Nepřevrátíš soudu chudého svého v jeho při.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548342,54,2,23,7,'Od slova lživého vzdálíš se. Nevinného a spravedlivého nezabiješ, nebo já neospravedlním bezbožného.'),
(1548343,54,2,23,8,'Aniž bráti budeš darů, nebo dar oslepuje i prozřetelné, a převrací slova spravedlivých.'),
(1548344,54,2,23,9,'Příchozího nebudeš ssužovati; nebo sami znáte, jaký jest život příchozích, poněvadž pohostinu jste byli v zemi Egyptské.'),
(1548345,54,2,23,10,'Po šest let osívati budeš zemi svou, a shromažďovati úrodu její;'),
(1548346,54,2,23,11,'Sedmého pak léta ponecháš jí, ať odpočine, aby jedli chudí lidu tvého. Co pak zůstane po nich, pojí zvěř polní. Tak uděláš s vinicí svou i s olivovím svým.'),
(1548347,54,2,23,12,'Šest dní budeš dělati díla svá, dne pak sedmého přestaneš, aby odpočinul vůl tvůj i osel tvůj, a oddechl syn děvky tvé i příchozí.'),
(1548348,54,2,23,13,'Ve všech těch věcech, kteréž mluvil jsem vám, ostříhati se budete. Jména bohů cizích ani připomínati nebudete, aniž bude slyšáno z úst tvých.'),
(1548349,54,2,23,14,'Třikrát slaviti mi budeš svátek na každý rok.'),
(1548350,54,2,23,15,'Slavnosti přesnic ostříhati budeš. Sedm dní jísti budeš chleby přesné, jakž jsem přikázal tobě, v čas vyměřený měsíce Abib; nebo v ten vyšel jsi z Egypta. Aniž se ukážete přede mnou prázdní.'),
(1548351,54,2,23,16,'A držeti budeš slavnost žně, když mi obětovati budeš prvotiny prací svých z toho, což jsi vsel na poli. Slavnost také sklizení držeti budeš při vyjití roku, když sklidíš práce své z pole.'),
(1548352,54,2,23,17,'Třikrát v roce ukáže se každý z tvých pohlaví mužského před tváří Panovníka Hospodina.'),
(1548353,54,2,23,18,'Nebudeš obětovati krve z oběti mé, dokavadž u tebe kvas jest, aniž zůstane tuk slavnosti mé do jitra.'),
(1548354,54,2,23,19,'Prvotiny prvních úrod země své přinášeti budeš do domu Hospodina Boha svého. Nebudeš vařiti kozelce v mléku mateře jeho.'),
(1548355,54,2,23,20,'Aj, já pošli anděla před tebou, aby ostříhal tebe na cestě, a přivedl tě na místo, kteréž jsem připravil.'),
(1548356,54,2,23,21,'Šetrně se měj před ním, a poslouchej hlasu jeho. Nepopouzej ho, neboť nepromine přestoupení vašeho, poněvadž jméno mé jest u prostřed něho.'),
(1548357,54,2,23,22,'Nebo budeš-li věrně poslouchati hlasu jeho, a činiti, cožť bych koli řekl: tedy nepřítelem budu nepřátel tvých, a trápiti budu ty, jenž tebe trápí.'),
(1548358,54,2,23,23,'Nebo půjde anděl můj před tebou, a uvede tě do země Amorejského a Hetejského, Ferezejského a Kananejského, Hevejského a Jebuzejského, kteréž vyhladím.'),
(1548359,54,2,23,24,'Nebudeš se klaněti bohům jejich, ani jim sloužiti, aniž dělati budeš tak, jako oni dělají; ale z gruntu vyvrátíš je, a obrazy jejich na kusy stroskoceš.'),
(1548360,54,2,23,25,'Sloužiti pak budete Hospodinu Bohu svému, a požehnáť chlebu tvému i vodám tvým; a odejmu nemoc z prostředku tvého.'),
(1548361,54,2,23,26,'Nebudeť, která by potratila, ani neplodná v zemi tvé; počet dnů tvých doplním.'),
(1548362,54,2,23,27,'Strach svůj pustím před tebou, a předěsím všeliký lid, proti kterémuž vyjdeš, a způsobím to, aby všickni nepřátelé tvoji utíkali před tebou.'),
(1548363,54,2,23,28,'Pošli i sršně před tebou, aby vyhnali Hevea, a Kananea a Hetea před tváří tvou.'),
(1548364,54,2,23,29,'Nevyženu ho od tváři tvé v jednom roce, aby se země neobrátila v poušť, a nerozmnožily se proti tobě šelmy divoké.'),
(1548365,54,2,23,30,'Pomalu vyháněti jej budu od tváři tvé, až bys ty se rozplodil, a dědičně mohl ujíti zemi.'),
(1548366,54,2,23,31,'Položím pak meze tvé od moře Rudého až k moři Filistinskému, a od pouště až k řece; nebo v ruce vaše dám obyvatele země, a vyženeš je od tváři své.'),
(1548367,54,2,23,32,'Neučiníš s nimi a bohy jejich smlouvy.'),
(1548368,54,2,23,33,'Nebudou bydliti v zemi tvé, aby nepřipravili tě k hříchu proti mně, když bys ctil bohy jejich; nebo by to bylo tobě osídlem.'),
(1548369,54,2,24,1,'Mojžíšovi pak řekl: Vstup k Hospodinu ty a Aron, Nádab a Abiu, a sedmdesáte z starších Izraelských, a klaněti se budete zdaleka.'),
(1548370,54,2,24,2,'Sám pak toliko Mojžíš vstoupí k Hospodinu, ale oni se nepřiblíží; aniž lid vstoupí s ním.'),
(1548371,54,2,24,3,'Tedy přišel Mojžíš, a vypravoval lidu všecka slova Hospodinova a všecky soudy. I odpověděl všecken lid jedním hlasem, a řekli: Všecka slova, kteráž mluvil Hospodin, učiníme.'),
(1548372,54,2,24,4,'Napsal pak Mojžíš všecka slova Hospodinova, a vstav ráno, vzdělal oltář pod horou, a dvanácte sloupů podlé počtu dvanáctera pokolení Izraelského.'),
(1548373,54,2,24,5,'A poslal mládence z synů Izraelských, kteříž obětovali zápaly; a obětovali oběti pokojné Hospodinu, totiž voly.'),
(1548374,54,2,24,6,'I vzav Mojžíš polovici krve, vlil do medenic, a polovici druhou vylil na oltář.'),
(1548375,54,2,24,7,'Vzav také knihu smlouvy, četl v uších lidu. Kteříž řekli: Cožkoli mluvil Hospodin, činiti a poslouchati budeme.'),
(1548376,54,2,24,8,'Vzal také Mojžíš krev a pokropil lidu a řekl: Aj, krev smlouvy, kterouž učinil s vámi Hospodin při všech těchto věcech.'),
(1548377,54,2,24,9,'Potom vstoupili Mojžíš a Aron, Nádab a Abiu a sedmdesáte z starších Izraelských,'),
(1548378,54,2,24,10,'A viděli Boha Izraelského. A pod nohami jeho bylo jako dílo z kamene zafirového, a jako nebe, když jest jasné.'),
(1548379,54,2,24,11,'Na knížata pak synů Izraelských nevztáhl ruky své, ačkoli viděli Boha, a potom jedli i pili.'),
(1548380,54,2,24,12,'I řekl Hospodin Mojžíšovi: Vstup ke mně na horu a buď tam; a dám tobě tabule kamenné, zákon i přikázaní, kteráž jsem napsal, abys je učil.'),
(1548381,54,2,24,13,'Tedy vstal Mojžíš a Jozue služebník jeho; i vstoupil Mojžíš na horu Boží.'),
(1548382,54,2,24,14,'Starším pak řekl: Zůstaňte tuto, dokudž se nenavrátíme k vám. A teď Aron a Hur jsou s vámi, kdož by měl rozepři, k nim ať jde.'),
(1548383,54,2,24,15,'Tedy vstoupil Mojžíš na horu, a přikryl oblak horu.'),
(1548384,54,2,24,16,'I přebývala sláva Hospodinova na hoře Sinai, a přikryl ji oblak za šest dní; a dne sedmého zavolal na Mojžíše z prostřed oblaku.'),
(1548385,54,2,24,17,'A tvárnost slávy Hospodinovy byla jako spalující oheň na vrchu hory, před očima synů Izraelských.'),
(1548386,54,2,24,18,'I všel Mojžíš do prostřed oblaku a vstoupil na horu. A byl Mojžíš na hoře čtyřidceti dní a čtyřidceti nocí.'),
(1548387,54,2,25,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1548388,54,2,25,2,'Mluv k synům Izraelským, ať mi vybírají obět vzhůru pozdvižení. Od každého člověka, kterýž by ji z srdce dobrovolně dal, přijměte takovou obět mou.'),
(1548389,54,2,25,3,'Tatoť pak jest obět pozdvižení, kterouž budete bráti od nich: Zlato, a stříbro, a měď,'),
(1548390,54,2,25,4,'Postavec modrý, šarlat, a červec dvakrát barvený, bílé hedbáví a srsti kozí;'),
(1548391,54,2,25,5,'Též kůže skopcové na červeno barvené, a kůže jezevčí, a dříví setim,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548392,54,2,25,6,'Olej k svícení, vonné věci na olej ku pomazování, a pro kadění vonné věci;'),
(1548393,54,2,25,7,'Kamení onychinové, a jiné kamení k vsazování do náramníku a náprsníku.'),
(1548394,54,2,25,8,'I udělajíť mi svatyni, abych bydlil uprostřed nich.'),
(1548395,54,2,25,9,'Vedlé všeho, jakž já ukazuji tobě podobenství stánku a podobenství všech nádob jeho, tak uděláte.'),
(1548396,54,2,25,10,'Udělají také truhlu z dříví setim. Půl třetího lokte bude dlouhost její, půl druhého lokte širokost její, půl druhého také lokte vysokost její.'),
(1548397,54,2,25,11,'A obložíš ji zlatem čistým, vnitř i zevnitř obložíš ji; a uděláš nad ní vůkol korunu zlatou.'),
(1548398,54,2,25,12,'Sliješ k ní také čtyři kruhy zlaté, kteréž přiděláš ke čtyřem úhlům jejím, dva totiž kruhy po jedné straně její, a dva kruhy po druhé straně její.'),
(1548399,54,2,25,13,'Uděláš k tomu i sochory z dříví setim, a obložíš je zlatem.'),
(1548400,54,2,25,14,'I uvlečeš sochory do kruhů po stranách té truhly, aby na nich nošena byla truhla.'),
(1548401,54,2,25,15,'V kruzích té truhly budou bývati sochorové; nebudou vytahováni z nich.'),
(1548402,54,2,25,16,'A dáš do truhly svědectví, kteréž dám tobě.'),
(1548403,54,2,25,17,'Uděláš i slitovnici z zlata čistého. Půl třetího lokte bude dlouhost její, půl druhého pak lokte širokost její.'),
(1548404,54,2,25,18,'Uděláš také dva cherubíny zlaté, z taženého zlata uděláš je na dvou koncích slitovnice.'),
(1548405,54,2,25,19,'Uděláš pak cherubína jednoho na jednom konci, a cherubína druhého na druhém konci; na slitovnici uděláte cherubíny na obou koncích jejích.'),
(1548406,54,2,25,20,'A budou míti cherubínové křídla vztažená svrchu, zastírajíce křídly svými slitovnici, a tváři jejich obráceny budou jednoho k druhému; k slitovnici budou tváři cherubínů.'),
(1548407,54,2,25,21,'Dáš pak slitovnici svrchu na truhlu, a do truhly vložíš svědectví, kteréž dám tobě.'),
(1548408,54,2,25,22,'A tam budu přicházeti k tobě, a s tebou z té slitovnice, z prostředku dvou cherubínů, kteříž jsou nad truhlou svědectví, mluviti o všecko, cožť bych poroučeti chtěl k synům Izraelským.'),
(1548409,54,2,25,23,'Uděláš také stůl z dříví setim. Dvou loket bude dlouhost jeho, a na loket širokost jeho, půl druhého pak lokte vysokost jeho.'),
(1548410,54,2,25,24,'A obložíš jej zlatem čistým, a uděláš mu okolek zlatý vůkol.'),
(1548411,54,2,25,25,'Uděláš také okolo něho lištu čtyř prstů zšíří; a okolek zlatý uděláš okolo té lišty.'),
(1548412,54,2,25,26,'Uděláš u něho i čtyři kruhy zlaté, kteréž vpustíš do čtyř úhlů, kteříž jsou ve čtyřech nohách jeho.'),
(1548413,54,2,25,27,'Pod tou lištou budou kruhové, skrze něž provlačováni budou sochorové k nošení stolu.'),
(1548414,54,2,25,28,'Ty pak sochory uděláš z dříví setim, a obložíš je zlatem; i bude stůl nošen na nich.'),
(1548415,54,2,25,29,'Uděláš také misy jeho, a lžice jeho, a přikryvadla jeho, a koflíky jeho, k přikrývání; z čistého zlata naděláš toho.'),
(1548416,54,2,25,30,'A klásti budeš na ten stůl chleby předložení před tvář mou ustavičně.'),
(1548417,54,2,25,31,'Uděláš také svícen z zlata čistého, z taženého zlata ať jest ten svícen; sloupec jeho i prutové jeho, misky jeho a koule jeho, i květové jeho z něho budou.'),
(1548418,54,2,25,32,'A šest prutů vycházeti bude z boků jeho, tři prutové svícnu s jedné strany jeho,a tři prutové s druhé strany jeho.'),
(1548419,54,2,25,33,'Tři misky udělané na způsob pecky mandlové ať jsou na prutu jednom, a koule a květ, a tři misky udělané na způsob pecky mandlové na prutu druhém, a koule a květ; takž i na jiných šesti prutech z svícnu vycházejících.'),
(1548420,54,2,25,34,'Na svícnu také budou čtyři misky udělané na způsob mandlové pecky, a koule jeho, i květové jeho.'),
(1548421,54,2,25,35,'A bude koule pode dvěma pruty z něho, koule též pod druhými dvěma pruty z něho, koule opět pod jinými dvěma pruty z něho; a tak pod šesti pruty vycházejícími z svícna.'),
(1548422,54,2,25,36,'Koule jejich i prutové jejich z něho budou; všecko to z cela kované z zlata čistého.'),
(1548423,54,2,25,37,'Uděláš i sedm lamp na něj; a bude je rozsvěcovati kněz, aby svítily po stranách jeho.'),
(1548424,54,2,25,38,'I utěradla jeho, i nádoby k oharkům jeho z zlata čistého.'),
(1548425,54,2,25,39,'Z centnéře zlata čistého uděláno bude to se vším tím nádobím.'),
(1548426,54,2,25,40,'Hlediž pak, abys udělal podlé podobenství toho, kteréž tobě ukázáno jest na hoře.'),
(1548427,54,2,26,1,'Příbytek pak uděláš z desíti čalounů, kteříž budou z bílého hedbáví soukaného, a z postavce modrého, a z šarlatu, a z červce dvakrát barveného; a cherubíny dílem řemeslným uděláš.'),
(1548428,54,2,26,2,'Dlouhost čalounu jednoho osm a dvadceti loket, a širokost čalounu jednoho čtyři lokty; míra jedna bude všech čalounů.'),
(1548429,54,2,26,3,'Pět čalounů spolu spojeno bude jeden s druhým, a pět druhých čalounů též spolu spojeno bude jeden s druhým.'),
(1548430,54,2,26,4,'A naděláš i ok z hedbáví modrého po kraji čalounu jednoho na konci, kde se má spojovati s druhým; a tolikéž uděláš na kraji čalounu druhého na konci v spojení druhém.'),
(1548431,54,2,26,5,'Padesáte ok uděláš na čalounu jednom, a padesáte ok uděláš po kraji čalounu, kterýmž má připojen býti k druhému; oko jedno proti druhému aby bylo.'),
(1548432,54,2,26,6,'Uděláš také padesáte haklíků zlatých a spojíš čalouny jeden s druhým haklíky těmi; a tak bude příbytek jeden.'),
(1548433,54,2,26,7,'Nadto uděláš houní z srstí kozích na stánek k přistírání příbytku po vrchu; jedenácte takových houní uděláš.'),
(1548434,54,2,26,8,'Dlouhost houně jedné třidceti loktů, a širokost houně jedné čtyř loktů; jednostejná míra těch jedenácti houní bude.'),
(1548435,54,2,26,9,'A spojíš pět houní obzvláštně, a šest houní opět obzvláštně, a přehneš na dvé houni šestou napřed v čele stánku.'),
(1548436,54,2,26,10,'Uděláš pak padesáte ok po kraji houně jedné na konci, kdež se spojovati má, a padesáte ok po kraji houně k spojení druhému.'),
(1548437,54,2,26,11,'Uděláš také haklíků měděných padesát, kteréž vepneš do ok, a spojíš stánek, aby byl jedno.'),
(1548438,54,2,26,12,'Co pak zbývá houní po přikrytí stánku, totiž půl houně přesahující, převisne při zadní straně příbytku.'),
(1548439,54,2,26,13,'A loket s jedné a loket s druhé strany, zbývající na dýl z houní stánku, převisne po stranách příbytku sem i tam, aby jej přikrýval.'),
(1548440,54,2,26,14,'Uděláš také přikrytí na stánek z koží skopových na červeno barvených, přikrytí také z koží jezevčích svrchu.'),
(1548441,54,2,26,15,'Naděláš k příbytku i desk stojatých z dříví setim.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548442,54,2,26,16,'Desíti loktů dlouhost dsky, a půl druhého lokte širokost dsky jedné.'),
(1548443,54,2,26,17,'Dva čepy dska jedna míti bude, podobně jako stupně u schodu zpořádané, jeden proti druhému; tak uděláš u všech desk příbytku.'),
(1548444,54,2,26,18,'Zděláš pak desky k příbytku, dvadceti desk k straně polední, k větru polednímu.'),
(1548445,54,2,26,19,'(A čtyřidceti podstavků stříbrných uděláš pod dvadceti desk; dva podstavky pod jednu dsku ke dvěma čepům jejím, a dva podstavky pod dsku druhou pro dva čepy její.)'),
(1548446,54,2,26,20,'Na druhé pak straně příbytku k straně půlnoční dvadceti desk,'),
(1548447,54,2,26,21,'A čtyřidceti podstavků jejich stříbrných; dva podstavky pod jednu dsku a dva podstavky pod dsku druhou.'),
(1548448,54,2,26,22,'Na straně také příbytku k západu šest uděláš desk.'),
(1548449,54,2,26,23,'A dvě dsky uděláš v obou dvou úhlech příbytku;'),
(1548450,54,2,26,24,'Kteréž budou spojené pozpodu, a tolikéž spojené svrchu k jednomu kruhu; tak bude při dvou těch, ve dvou úhlech budou.'),
(1548451,54,2,26,25,'A tak bude osm desk, a podstavkové jejich stříbrní, šestnácte podstavků; dva podstavkové pod dskou jednou a dva podstavkové pod dskou druhou.'),
(1548452,54,2,26,26,'Naděláš také svlaků z dříví setim. Pět jich bude dskám k straně příbytku jedné,'),
(1548453,54,2,26,27,'A pět svlaků dskám při straně příbytku druhé, a pět svlaků dskám k straně západní příbytku dosahující k oběma úhlům.'),
(1548454,54,2,26,28,'Ale prostřední svlak u prostřed desk provleče se od jednoho konce k druhému.'),
(1548455,54,2,26,29,'Ty pak dsky obložíš zlatem, a kruhy k nim uděláš zlaté, do nichž by svlakové byli uvlačováni; a obložíš i svlaky zlatem.'),
(1548456,54,2,26,30,'A tak vyzdvihneš příbytek podlé způsobu toho, kterýž tobě ukázán na hoře.'),
(1548457,54,2,26,31,'Uděláš i oponu z postavce modrého, a z šarlatu, a z červce dvakrát barveného, a z bílého hedbáví soukaného; dílem řemeslným uděláš ji s cherubíny.'),
(1548458,54,2,26,32,'A zavěsíš ji na čtyřech sloupích z dříví setim, obložených zlatem, (hákové jejich zlatí), na čtyřech podstavcích stříbrných.'),
(1548459,54,2,26,33,'A dáš oponu na háky, a vneseš vnitř za oponu truhlu svědectví; a oddělovati vám bude ta opona svatyni od svatyně svatých.'),
(1548460,54,2,26,34,'Položíš také slitovnici na truhlu svědectví v svatyni svatých.'),
(1548461,54,2,26,35,'A postavíš stůl vně před oponou, svícen pak naproti stolu v straně příbytku polední, a stůl dáš na stranu půlnoční.'),
(1548462,54,2,26,36,'A uděláš zastření dveří stánku z postavce modrého a z šarlatu, a z červce dvakrát barveného, a z bílého hedbáví přesukovaného, dílem vyšívaným.'),
(1548463,54,2,26,37,'K zastření pak tomu uděláš pět sloupů z dříví setim, kteréž obložíš zlatem, a hákové jejich zlatí; a sleješ k nim pět podstavků měděných.'),
(1548464,54,2,27,1,'Uděláš také oltář z dříví setim pěti loket zdýlí a pěti loket zšíří; čtverhranatý bude oltář, a tří loket zvýší bude.'),
(1548465,54,2,27,2,'A zděláš mu rohy na čtyřech úhlech jeho; z něho budou rohové jeho; a obložíš jej mědí.'),
(1548466,54,2,27,3,'Naděláš také k němu hrnců, do kterýchž by popel bral, a lopat a kotlíku, a vidliček a nádob k uhlí. Všecka nádobí jeho z mědi uděláš.'),
(1548467,54,2,27,4,'Uděláš mu i rošt mřežovaný měděný, a u té mříže čtyři kruhy měděné na čtyřech rozích jejích.'),
(1548468,54,2,27,5,'A dáš ji pod okolek oltáře do vnitřku; a bude ta mříže až do polu oltáře.'),
(1548469,54,2,27,6,'Uděláš k tomu oltáři i sochory z dříví setim, a mědí je okuješ.'),
(1548470,54,2,27,7,'A ti sochorové provlečeni budou skrze ty kruhy; a budou sochorové ti na obou stranách oltáře, když nošen bude.'),
(1548471,54,2,27,8,'Uděláš jej z desk, aby byl vnitř prázdný; jakž ukázáno tobě na hoře, tak udělají.'),
(1548472,54,2,27,9,'Uděláš také síň příbytku k straně polední; koltry síně té očkovaté budou z bílého hedbáví soukaného; sto loket zdélí ať má kraj jeden.'),
(1548473,54,2,27,10,'Sloupů pak bude k nim dvadcet, a podstavků k nim měděných dvadcet; háky na sloupích a přepásaní jich stříbrné.'),
(1548474,54,2,27,11,'A tak i strana půlnoční na dýl ať má koltry očkovaté sto loket zdýlí, a sloupů svých dvadceti, a podstavků k nim měděných dvadceti; háky na sloupích a přepásaní jich stříbrné.'),
(1548475,54,2,27,12,'Na šíř pak té síně k straně západní budou koltry očkovaté padesáti loktů zdýlí, a sloupů k nim deset, a podstavků jejich deset.'),
(1548476,54,2,27,13,'A širokost síně v straně přední na východ bude padesáti loktů.'),
(1548477,54,2,27,14,'Patnácti loktů budou koltry očkovaté k straně jedné, sloupové k nim tři, a podstavkové jejich tři.'),
(1548478,54,2,27,15,'A k straně druhé patnácti loktů zdýlí budou koltry očkovaté, sloupové jejich tři, a podstavkové jejich tři.'),
(1548479,54,2,27,16,'K bráně pak té síně uděláno bude zastření dvadcíti loktů z postavce modrého a šarlatu, a z červce dvakrát barveného, a bílého hedbáví soukaného, dílem krumpéřským, sloupové k němu čtyři, a podstavkové jejich čtyři.'),
(1548480,54,2,27,17,'Všickni sloupové síně vůkol přepásani budou stříbrem; hákové pak jejich budou stříbrní, a podstavkové jejich mědění.'),
(1548481,54,2,27,18,'Dlouhost síně bude sto loket, a širokost padesáte, všudy jednostejná, vysokost pak pěti loktů, z bílého hedbáví soukaného, a podstavkové budou mědění.'),
(1548482,54,2,27,19,'Všecka nádobí příbytku, ke vší službě jeho, a všickni kolíkové jeho, i všickni kolíkové síně z mědi budou.'),
(1548483,54,2,27,20,'Ty také přikaž synům Izraelským, ať nanesou oleje olivového čistého, vytlačeného k svícení, aby lampy vždycky rozsvěcovány byly.'),
(1548484,54,2,27,21,'V stánku úmluvy před oponou, kteráž zastírati bude svědectví, spravovati je budou Aron a synové jeho od večera až do jitra před Hospodinem. Toť bude řád věčný, kterýž zachovávati budou potomci jejich mezi syny Izraelskými.'),
(1548485,54,2,28,1,'Ty pak přijmi k sobě Arona bratra svého s syny jeho z prostředku synů Izraelských, aby úřad kněžský konali přede mnou: Aron, Nádab, Abiu, Eleazar a Itamar, synové Aronovi.'),
(1548486,54,2,28,2,'A uděláš roucha svatá Aronovi bratru svému k slávě a k ozdobě.'),
(1548487,54,2,28,3,'Ty také mluviti budeš se všechněmi umělými řemeslníky, kteréž jsem naplnil duchem moudrosti, aby dělali roucha Aronovi ku posvěcení jeho, v nichž by úřad kněžský konal přede mnou.'),
(1548488,54,2,28,4,'Tato pak jsou roucha, kteráž udělají, náprsník, náramenník, plášť a sukni s oky, čepici a pás. Takové šaty svaté udělají Aronovi bratru tvému a synům jeho, aby úřad kněžský konali přede mnou.'),
(1548489,54,2,28,5,'A vezmou řemeslníci zlato a modrý postavec, a šarlat a červec dvakrát barvený a kment.'),
(1548490,54,2,28,6,'Udělají pak náramenník z zlata, z postavce modrého a šarlatu, z červce dvakrát barveného a hedbáví bílého, přesukovaného dílem řemeslným.'),
(1548491,54,2,28,7,'Dva vrchní kraje spojená míti bude na dvou koncích svých, a tak se spolu držeti bude.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548492,54,2,28,8,'Přepásaní pak přes ten náramenník, kteréž na něm bude, podobné bude dílu jeho; z týchž věcí bude, totiž z zlata, z postavce modrého a z šarlatu, a z červce dvakrát barveného, a z hedbáví bílého přesukovaného.'),
(1548493,54,2,28,9,'Vezmeš také dva kameny onychinové, a vyryješ na nich jména synů Izraelských.'),
(1548494,54,2,28,10,'Šest jmen jejich na kameni jednom, a jmen šest ostatních na kameni druhém, podlé pořádku narození jejich.'),
(1548495,54,2,28,11,'Dílem řemeslníka, kterýž řeže na kameni, a kterýž vyrývá pečeti, vyryješ na těch dvou kameních jména synů Izraelských; do zlata je vsadíš.'),
(1548496,54,2,28,12,'A položíš dva kameny ty na vrchních krajích náramenníku, kameny pro pamět na syny Izraelské; a nositi bude Aron jména jejich před Hospodinem na obou ramenách svých na památku.'),
(1548497,54,2,28,13,'Uděláš i haklíky zlaté.'),
(1548498,54,2,28,14,'A dva řetízky z zlata čistého jednostejně uděláš dílem točeným, a zavěsíš řetízky ty stočené na ty haklíky.'),
(1548499,54,2,28,15,'Uděláš také náprsník soudu dílem řemeslným, takovým dílem, jako náramenník uděláš jej z zlata, z postavce modrého, z šarlatu, z červce dvakrát barveného, a z bílého hedbáví přesukovaného.'),
(1548500,54,2,28,16,'Čtverhraný bude a dvojnásobní; pídi dlouhost, a pídi širokost jeho bude.'),
(1548501,54,2,28,17,'A vysadíš jej všudy kamením drahým. Čtyřmi řady ať jest kamení, pořádkem tímto: Sardius, topazius a smaragdus v prvním řadu;'),
(1548502,54,2,28,18,'V druhém pak zpořádaní karbunkulus, zafir a jaspis;'),
(1548503,54,2,28,19,'A v řadu třetím linkurius, achates a ametyst;'),
(1548504,54,2,28,20,'V čtvrtém řadu chryzolit, onychin a beryl. Vsazeni budou do zlata v svém pořádku.'),
(1548505,54,2,28,21,'Těch pak kamenů s jmény synů Izraelských bude dvanácte, podlé jmen jejich, dílem řežících pečeti; jeden každý podlé jména svého, pro dvanáctero pokolení budou.'),
(1548506,54,2,28,22,'Uděláš i k náprsníku řetízky jednostejné dílem točeným z zlata čistého.'),
(1548507,54,2,28,23,'Uděláš také k náprsníku dva kroužky zlaté, a dáš je na dva kraje náprsníka.'),
(1548508,54,2,28,24,'A prostrčíš dva řetízky zlaté skrze dva kroužky po krajích náprsníka.'),
(1548509,54,2,28,25,'A druhé konce těch dvou řetízků připneš k haklíkům, a dáš na vrchní kraje náramenníka po předu.'),
(1548510,54,2,28,26,'Uděláš i dva kroužky zlaté, kteréž dáš na dva kraje náprsníka, na tu obrubu jeho, kteráž jest po té straně k náramenníku do vnitřku.'),
(1548511,54,2,28,27,'Uděláš ještě dva jiné kroužky zlaté, kteréž dáš na dvě strany náramenníka zespod po předu naproti spojení jeho, svrchu nad přepásaním náramenníka.'),
(1548512,54,2,28,28,'Tak svíží náprsník ten, kroužky jeho s kroužky náramenníka, tkanicí z postavce modrého, aby byl nad přepásaním náramenníka, a neodevstával náprsník od náramenníka.'),
(1548513,54,2,28,29,'I bude nositi Aron jména synů Izraelských na náprsníku soudu na srdci svém, když vcházeti bude do svatyně, na památku před Hospodinem ustavičně.'),
(1548514,54,2,28,30,'Položíš pak do náprsníku soudu urim a thumim, aby bylo na srdci Aronově, když vcházeti bude před Hospodina; a nositi bude Aron soud synů Izraelských na srdci svém před Hospodinem vždycky.'),
(1548515,54,2,28,31,'Uděláš také plášť pod náramenník, všecken z postavce modrého.'),
(1548516,54,2,28,32,'A bude na vrchu v prostřed něho díra; okolek její všudy vůkol dílem tkaným, jako obojek u pancíře bude, aby se neroztrhl.'),
(1548517,54,2,28,33,'Uděláš i na podolku jeho jablka zrnatá z hedbáví modrého, z šarlatu a z červce dvakrát barveného, na podolku jeho vůkol, a zvonečky zlaté mezi nimi vůkol.'),
(1548518,54,2,28,34,'Zvonček zlatý a jablko zrnaté, opět za tím zvonček zlatý a jablko zrnaté na podolku pláště vůkol.'),
(1548519,54,2,28,35,'A bude to míti na sobě Aron při službách, aby slyšán byl zvuk jeho, když vcházeti bude do svatyně před Hospodina, i když vycházeti bude, aby neumřel.'),
(1548520,54,2,28,36,'Uděláš také plech z zlata čistého, a vyryješ na něm dílem vyrývajících pečeti: Svatost Hospodinu.'),
(1548521,54,2,28,37,'Kterýž dáš na tkanici z modrého postavce, a bude na čepici; napřed na čepici bude.'),
(1548522,54,2,28,38,'I bude nad čelem Aronovým, aby nesl Aron nepravosti posvěcených věcí, kterýchž by posvětili synové Izraelští při všech dařích posvěcených věcí svých; a bude nad čelem jeho vždycky, aby příjemné je činil před Hospodinem.'),
(1548523,54,2,28,39,'Uděláš také sukni z hedbáví bílého vázanou s oky; uděláš i čepici z hedbáví bílého; pás také uděláš dílem krumpéřským.'),
(1548524,54,2,28,40,'Synům také Aronovým zděláš sukně; pasy také jim uděláš a klobouky k slávě a k ozdobě.'),
(1548525,54,2,28,41,'A oblečeš v ně Arona bratra svého a syny jeho s ním, a pomažeš jich, a naplníš ruce jejich, a posvětíš mi jich, aby úřad kněžský konali přede mnou.'),
(1548526,54,2,28,42,'Nadělej jim i košilek lněných k zakrytí nahoty těla; od bedr až do stehen budou.'),
(1548527,54,2,28,43,'A ať je na sobě mají Aron i synové, když vcházeti budou do stánku úmluvy, aneb když přistupovati budou k oltáři, aby sloužili v svatyni; a neponesou nepravosti, aniž zemrou. Řád tento bude věčný jemu i potomkům jeho po něm.'),
(1548528,54,2,29,1,'Toto také učiníš jim ku posvěcení jich, aby úřad kněžský konali přede mnou: Vezmi volka jednoho ještě mladého a skopce dva bez vady.'),
(1548529,54,2,29,2,'Chleby též přesné a koláče přesné s olejem smíšené, a oplatky přesné polité olejem; z běli pšeničné naděláš toho.'),
(1548530,54,2,29,3,'A vklada to do koše jednoho, obětovati to budeš v koši, spolu s tím volkem a dvěma skopci.'),
(1548531,54,2,29,4,'Potom Aronovi a synům jeho přistoupiti kážeš ke dveřím stánku úmluvy, a umyješ je vodou.'),
(1548532,54,2,29,5,'A vezma roucha, oblečeš Arona v sukni, a v plášť náležící pod náramenník, a v náramenník, a v náprsník, a přepášeš ho pasem náramenníka.'),
(1548533,54,2,29,6,'Vstavíš i čepici na hlavu jeho, a korunu svatosti vstavíš na čepici.'),
(1548534,54,2,29,7,'Naposledy vezmeš olej pomazání, a vyleje na hlavu jeho, pomažeš ho.'),
(1548535,54,2,29,8,'Potom synům jeho přistoupiti kážeš, a zobláčíš je v sukně.'),
(1548536,54,2,29,9,'A zopasuješ je pasy, Arona i syny jeho, a vstavíš jim čepičky na hlavu. I budouť míti kněžství řádem věčným; a posvětíš ruky Aronovy a ruky synů jeho.'),
(1548537,54,2,29,10,'Přivedeš také volka před stánek úmluvy, i vloží Aron a synové jeho ruce své na hlavu volka.'),
(1548538,54,2,29,11,'A zabiješ volka před Hospodinem u dveří stánku úmluvy.'),
(1548539,54,2,29,12,'A nabera krve z volka, pomažeš na rozích oltáře prstem svým, a všecku krev vyleješ k spodku oltáře.'),
(1548540,54,2,29,13,'Vezmeš pak všecken tuk přikrývající droby a branici s jater, a dvě ledviny s tukem, kterýž jest na nich, a zapálíš to na oltáři.'),
(1548541,54,2,29,14,'Maso pak z toho volka, a kůži s lejny jeho spálíš ohněm vně za stany; nebo obět za hříchy jest.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548542,54,2,29,15,'Skopce také jednoho vezmeš, a vloží Aron a synové jeho ruce své na hlavu toho skopce.'),
(1548543,54,2,29,16,'A zabiješ toho skopce, a nabera krve jeho, pokropíš oltáře na vrchu vůkol.'),
(1548544,54,2,29,17,'Skopce pak rozsekáš na kusy, a vymyje droby jeho i nohy, vkladeš je na ty kusy z něho a na hlavu jeho.'),
(1548545,54,2,29,18,'A potom všeho skopce zapálíš na oltáři; nebo zápal ten jest Hospodinu vůně příjemná, obět ohnivá jest Hospodinu.'),
(1548546,54,2,29,19,'Vezmeš také skopce druhého; i vloží Aron a synové jeho ruce své na hlavu téhož skopce.'),
(1548547,54,2,29,20,'A zabiješ skopce toho, a vezma krev jeho, pomažeš jí konce ucha Aronova, a konce pravého ucha synů jeho, i palce na pravé ruce jejich, a palce na pravé noze jejich; a vykropíš tu krev na oltář vůkol.'),
(1548548,54,2,29,21,'A vezma krve, kteráž bude na oltáři, a oleje pomazání, pokropíš Arona a roucha jeho i synů jeho a roucha jejich s ním; a budeť posvěcen on i roucho jeho, i synové jeho, a roucho synů jeho s ním.'),
(1548549,54,2,29,22,'Potom vezmeš z skopce tuk a ocas, a tuk přikrývající droby, a branici s jater, a dvě ledviny s tukem, kterýž jest na nich, a plece pravé, (nebo skopec naplnění jest),'),
(1548550,54,2,29,23,'A jeden pecník chleba, a jeden koláč chleba s olejem, a oplatek jeden z koše chlebů přesných, kterýž jest před Hospodinem.'),
(1548551,54,2,29,24,'A dáš to vše v ruce Aronovy a v ruce synů jeho, a obraceti to budeš sem i tam, aby byla obět obracení před Hospodinem.'),
(1548552,54,2,29,25,'Potom vezma to z rukou jejich, zapálíš na oltáři v zápal, k vůni příjemné před Hospodinem. Toť jest obět ohnivá Hospodinu.'),
(1548553,54,2,29,26,'Vezmeš také hrudí z skopce posvěcení, kterýž bude Aronův, a obraceti je budeš sem i tam, aby byla obět obracení před Hospodinem; a budeť na tvůj díl.'),
(1548554,54,2,29,27,'Posvětíš tedy hrudí obracení, a plece pozdvižení, kteréž obracíno a kteréž pozdvihováno bylo z skopce posvěcení, z toho, kterýž bude Aronův, a z toho, kterýž bude synů jeho.'),
(1548555,54,2,29,28,'A bude to Aronovi a synům jeho právem věčným od synů Izraelských, když obět pozdvižení bude. Nebo pozdvižení bude od synů Izraelských, z obětí jejich pokojných; pozdvižení jejich náleží Hospodinu.'),
(1548556,54,2,29,29,'Roucha pak svatá, kteráž jsou Aronova, zůstanou synům jeho po něm, aby pomazováni byli v nich, a aby posvěcovány byly v nich ruce jejich.'),
(1548557,54,2,29,30,'Sedm dní bude v nich choditi kněz, kterýž bude na jeho místě z synů jeho, kterýž vcházeti bude do stánku úmluvy, aby sloužil v svatyni.'),
(1548558,54,2,29,31,'Skopce pak posvěcení vezma, uvaříš maso jeho na místě svatém.'),
(1548559,54,2,29,32,'A budeť jísti Aron s syny svými maso toho skopce a chléb, kterýž jest v koši u dveří stánku úmluvy.'),
(1548560,54,2,29,33,'Jísti budou to ti, za něž očištění se stalo ku posvěcení rukou jejich, aby posvěceni byli. Cizí pak nebude jísti, nebo svatá věc jest.'),
(1548561,54,2,29,34,'Zůstalo-li by co masa posvěcení a chleba až do jitra, spálíš ostatky ohněm; nebude jedeno, nebo svatá věc jest.'),
(1548562,54,2,29,35,'Tak tedy uděláš s Aronem a syny jeho vedlé všeho, což jsem přikázal tobě; za sedm dní posvěcovati budeš rukou jejich.'),
(1548563,54,2,29,36,'A volka za hřích obětovati budeš na každý den na očištění, a krví za hřích pokropíš oltáře, čině očištění na něm, a pomažeš ho ku posvěcení jeho.'),
(1548564,54,2,29,37,'Za sedm dní očišťování konati budeš na oltáři, a posvětíš ho, a ten oltář bude nejsvětější. Cokoli dotkne se oltáře, posvěceno bude.'),
(1548565,54,2,29,38,'A toto jest, což obětovati budeš na oltáři, beránky roční dva, na každý den ustavičně.'),
(1548566,54,2,29,39,'Jednoho beránka obětovati budeš ráno, a beránka druhého obětovati budeš k večerou.'),
(1548567,54,2,29,40,'A desátý díl efi běli smíšené s olejem vytlačeným, jehož by bylo s čtvrtý díl hin, a k oběti mokré čtvrtý díl hin vína na jednoho beránka.'),
(1548568,54,2,29,41,'Tolikéž beránka druhého obětovati budeš k večerou. Jako při oběti suché ranní, a jako při mokré oběti její, tak při této učiníš, aby byla vůně příjemná, obět ohnivá Hospodinu.'),
(1548569,54,2,29,42,'Zápalná obět tato ustavičná ať jest po všecky věky vaše u dveří stánku úmluvy před Hospodinem, kdež přicházeti budu k vám, abych tam s tebou mluvil.'),
(1548570,54,2,29,43,'A tam přicházeti budu k synům Izraelským, a posvěceno bude místo slávou mou.'),
(1548571,54,2,29,44,'Nebo posvětím stánku úmluvy i oltáře; Arona také a synů jeho posvětím, aby mi úřad kněžský konali.'),
(1548572,54,2,29,45,'A bydliti budu u prostřed synů Izraelských, a budu jim za Boha.'),
(1548573,54,2,29,46,'A zvědíť, že já jsem Hospodin Bůh jejich, kterýž jsem je vyvedl z země Egyptské, abych přebýval u prostřed nich, já Hospodin Bůh jejich.'),
(1548574,54,2,30,1,'Uděláš i oltář, na němž by se kadilo; z dříví setim uděláš jej.'),
(1548575,54,2,30,2,'Lokte zdélí, a lokte zšíří, čtverhraný bude, a dvou loket zvýší; z něho budou rohy jeho.'),
(1548576,54,2,30,3,'Obložíš pak jej zlatem čistým, svrchek jeho i po stranách vůkol i rohy jeho; a uděláš mu korunu zlatou vůkol.'),
(1548577,54,2,30,4,'Po dvou také kruzích zlatých uděláš u něho, pod korunou ve dvou úhlech jeho, po obou stranách jeho; a skrze ně provlečeš sochory, aby nošen byl na nich.'),
(1548578,54,2,30,5,'Ty pak sochory uděláš z dříví setim, a obložíš je zlatem.'),
(1548579,54,2,30,6,'A postavíš jej před oponou, za kterouž jest truhla svědectví, před slitovnicí, kteráž jest nad svědectvím, kdež přicházeti budu k tobě.'),
(1548580,54,2,30,7,'I kaditi bude na něm Aron kadidlem z vonných věcí; každého jitra, když spraví světla, kaditi bude.'),
(1548581,54,2,30,8,'Tolikéž když rozsvítí Aron lampy k večerou, kaditi bude kaděním vonných věcí ustavičně před Hospodinem po rodech vašich.'),
(1548582,54,2,30,9,'Nevložíte na něj kadidla cizího, ani zápalu, ani oběti suché, ani oběti mokré obětovati budete na něm.'),
(1548583,54,2,30,10,'Toliko očištění vykoná nad rohy jeho Aron jednou v roce, krví oběti za hřích v den očišťování; jednou v roce očištění vykoná na něm po rodech vašich; svatosvaté jest Hospodinu.'),
(1548584,54,2,30,11,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1548585,54,2,30,12,'Když vyzdvihneš hlavní summu synů Izraelských náležejících ku počtu, dá jeden každý výplatu duše své Hospodinu, když je počítati budeš, aby nebyla na nich rána, když sečteni budou.'),
(1548586,54,2,30,13,'Toto pak dají: Každý z těch, kteří jdou v počet, půl lotu dá, podlé lotu svatyně. (Dvadceti peněz platí ten lot.) Půl lotu obět pozdvižení bude Hospodinu.'),
(1548587,54,2,30,14,'Kdožkoli jde v počet od dvadcíti let a výše, tu obět pozdvižení ať dá Hospodinu.'),
(1548588,54,2,30,15,'Bohatý nedá více, a chudý nedá méně, než půl lotu, když dávati budou obět pozdvižení Hospodinu k očištění duší vašich.'),
(1548589,54,2,30,16,'A vezma stříbro očištění od synů Izraelských, dáš je na potřeby k službě stánku úmluvy; a bude to synům Izraelským na památku před Hospodinem k očištění duší vašich.'),
(1548590,54,2,30,17,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1548591,54,2,30,18,'Uděláš i umyvadlo měděné k umývání a podstavek jeho měděný, a postavíš je mezi stánkem úmluvy a oltářem, a naleješ do něho vody.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548592,54,2,30,19,'Umývati budou z něho Aron i synové jeho ruce své i nohy své.'),
(1548593,54,2,30,20,'Když vcházeti budou do stánku úmluvy, umývati se budou vodou, aby nezemřeli, aneb když by měli přistupovati k oltáři, aby sloužili, a zapalovali obět ohnivou Hospodinu.'),
(1548594,54,2,30,21,'I budou umývati ruce i nohy své, aby nezemřeli. A bude jim ustanovení toto věčné, Aronovi i semeni jeho po rodech jejich.'),
(1548595,54,2,30,22,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1548596,54,2,30,23,'Ty pak vezmi sobě vonných věcí předních: Mirry nejčistší pět set lotů, a skořice vonné polovici toho, totiž dvě stě a padesát, a prustvorce vonného dvě stě a padesát;'),
(1548597,54,2,30,24,'Kasie pak pět set lotů na váhu svatyně, oleje olivového míru hin.'),
(1548598,54,2,30,25,'A uděláš z toho olej pomazání svatého, mast nejvýbornější dílem apatykářským. Olej pomazání svatého bude.'),
(1548599,54,2,30,26,'Pomažeš jím stánku úmluvy i truhly svědectví,'),
(1548600,54,2,30,27,'A stolu i všech nádob k němu, svícnu i všech nádob jeho, i oltáře, na němž se kadí;'),
(1548601,54,2,30,28,'Oltáře také, na němž se pálí oběti, a všech nádob jeho, i umyvadla s podstavkem jeho.'),
(1548602,54,2,30,29,'Tak posvětíš jich, aby byly nejsvětější. Cožkoli dotkne se jich, posvěceno bude.'),
(1548603,54,2,30,30,'Arona také a synů jeho pomažeš, a posvětíš jich, aby úřad kněžský konali přede mnou.'),
(1548604,54,2,30,31,'K synům pak Izraelským mluviti budeš, řka: Tento olej pomazání svatého bude mi v národech vašich.'),
(1548605,54,2,30,32,'Tělo člověka nebude mazáno jím, a podlé složení jeho neuděláte podobného. Svatýť jest, svatý vám bude.'),
(1548606,54,2,30,33,'Kdo by koli udělal mast podobnou, a neb mazal by jí cizího, vyhlazen bude z lidu svého.'),
(1548607,54,2,30,34,'I řekl Hospodin Mojžíšovi: Vezmi sobě vonných věcí, balsamu, onychi, galbanu vonného, a kadidla čistého; jednostejná váha toho bude.'),
(1548608,54,2,30,35,'A uděláš z toho kadidlo, složení dílem apatykářským smíšené, čisté a svaté.'),
(1548609,54,2,30,36,'A ztluka to drobně, klásti budeš z něho před svědectvím v stánku úmluvy, kdež přicházeti budu k tobě. Nejsvětější to vám bude.'),
(1548610,54,2,30,37,'Neuděláte sobě kadidla podlé složení tohoto, kteréž připravíš; za svatou věc tobě bude pro Hospodina.'),
(1548611,54,2,30,38,'Kdo by koli dělal co podobného k vůni sobě, vyhlazen bude z lidu svého.'),
(1548612,54,2,31,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1548613,54,2,31,2,'Hle, povolal jsem ze jména Bezeleele, syna Uri, syna Hur, z pokolení Judova.'),
(1548614,54,2,31,3,'A naplnil jsem ho duchem Božím, moudrostí a rozumností, i uměním všelijakého řemesla,'),
(1548615,54,2,31,4,'Aby vtipně smysliti uměl, což by koli řemeslně uděláno býti mohlo z zlata a z stříbra i z mědi.'),
(1548616,54,2,31,5,'I v řezání kamení drahého k vsazování, i v umělém vysazování na dřevě aby dělal všelijaké dílo.'),
(1548617,54,2,31,6,'A aj, já přidal jsem jemu Aholiaba, syna Achisamechova, z pokolení Dan. A v srdci každého vtipného složil jsem moudrost, aby spravili vše, což jsem přikázal tobě:'),
(1548618,54,2,31,7,'Stánek úmluvy a truhlu svědectví, a slitovnici, kteráž má býti na ní, i všelijaké nádobí stánku;'),
(1548619,54,2,31,8,'Stůl také a nádoby k němu, i svícen čistý se všemi nádobami jeho, a oltář pro kadění;'),
(1548620,54,2,31,9,'Též oltář k zápalům se všemi nádobami jeho, a umyvadlo s podstavkem jeho;'),
(1548621,54,2,31,10,'I roucha k službě, i roucha svatá Aronovi knězi, i roucha synů jeho, aby mi úřad kněžský konali;'),
(1548622,54,2,31,11,'I olej pomazání a kadidlo vonné do svatyně. Všecko tak, jakž jsem přikázal tobě, udělají.'),
(1548623,54,2,31,12,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1548624,54,2,31,13,'Ty pak mluv k synům Izraelským a rci: A však sobot mých ostříhati budete. Nebo to znamením jest mezi mnou a vámi po rodech vašich, aby známo bylo, že já jsem Hospodin, kterýž vás posvěcuji.'),
(1548625,54,2,31,14,'Protož ostříhati budete soboty, nebo svatá jest vám. Kdož by ji poškvrnil, smrtí umře; a kdo by koli dělal v ní dílo, vyhlazena bude ta duše z prostředku lidu svého.'),
(1548626,54,2,31,15,'Šest dní děláno bude dílo, ale v den sedmý sobota odpočinutí jest, svatost Hospodinu. Každý, kdož by dělal dílo v den sobotní, smrtí umře.'),
(1548627,54,2,31,16,'Protož ostříhati budou synové Izraelští soboty, tak aby světili sobotu po rodech svých smlouvou věčnou.'),
(1548628,54,2,31,17,'Mezi mnou a syny Izraelskými za znamení jest na věčnost; nebo šest dní činil Hospodin nebe i zemi, v den pak sedmý přestal a odpočinul.'),
(1548629,54,2,31,18,'I dal Pán Mojžíšovi po dokonání těchto řečí s ním na hoře Sinai dvě dsky svědectví, dsky kamenné, psané prstem Božím.'),
(1548630,54,2,32,1,'Vida pak lid, že by prodléval Mojžíš sstoupiti s hůry, sebrali se proti Aronovi a řekli jemu: Vstaň, udělej nám bohy, kteříž by šli před námi; nebo Mojžíšovi, muži tomu, kterýž vyvedl nás z země Egyptské, nevíme, co se přihodilo.'),
(1548631,54,2,32,2,'I řekl jim Aron: Odejměte náušnice zlaté, kteréž jsou na uších žen vašich, synů vašich i dcer vašich, a přineste ke mně.'),
(1548632,54,2,32,3,'Tedy strhl všecken lid náušnice zlaté, kteréž byly na uších jejich, a přinesli k Aronovi.'),
(1548633,54,2,32,4,'Kteréžto vzav z rukou jejich, dal je do formy, a udělal z nich tele slité. I řekli: Tito jsou bohové tvoji, Izraeli, kteříž tě vyvedli z země Egyptské.'),
(1548634,54,2,32,5,'Což vida Aron, vzdělal oltář před ním. I volal Aron, a řekl: Slavnost Hospodinova zítra bude.'),
(1548635,54,2,32,6,'A nazejtří vstavše velmi ráno, obětovali zápaly, a přivedli oběti pokojné. I sedl lid, aby jedl a pil, potom vstali, aby hrali.'),
(1548636,54,2,32,7,'Mluvil pak Hospodin k Mojžíšovi: Jdi, sstup, nebo porušil se lid tvůj, kterýž jsi vyvedl z země Egyptské.'),
(1548637,54,2,32,8,'Sešli brzo s cesty, kterouž jsem přikázal jim. Udělali sobě tele slité, a klaněli se mu, a obětovali jemu, řkouce: Tito jsou bohové tvoji, Izraeli, kteříž tě vyvedli z země Egyptské.'),
(1548638,54,2,32,9,'Řekl také Hospodin Mojžíšovi: Viděl jsem lid tento, a aj, lid jest tvrdé šíje.'),
(1548639,54,2,32,10,'Protož nyní nech mne, abych v hněvě prchlivosti své vyhladil je, tebe pak učiním v národ veliký.'),
(1548640,54,2,32,11,'I modlil se Mojžíš Hospodinu Bohu svému, a řekl: Pročež, ó Hospodine, rozněcuje se prchlivost tvá na lid tvůj, kterýž jsi vyvedl z země Egyptské v síle veliké a v ruce mocné?'),
(1548641,54,2,32,12,'A proč mají mluviti Egyptští, řkouce: Lstivě je vyvedl, aby zmordoval je na horách, a aby vyhladil je se svrchku země? Odvrať se od hněvu prchlivosti své, a lituj zlého, kteréžs uložil uvésti na lid svůj.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548642,54,2,32,13,'Rozpomeň se na Abrahama, Izáka a Izraele, služebníky své, jimž jsi zapřisáhl skrze sebe samého a mluvil jsi jim: Rozmnožím símě vaše jako hvězdy nebeské, a všecku zemi tuto, o kteréž jsem mluvil, dám semeni vašemu, a dědičně obdržíte ji na věky.'),
(1548643,54,2,32,14,'I litoval Hospodin zlého, kteréž řekl, že učiní lidu svému.'),
(1548644,54,2,32,15,'A obrátiv se Mojžíš, sstoupil s hůry, dvě dsky svědectví maje v rukou svých, dsky po obou stranách psané; s jedné i s druhé strany byly popsané.'),
(1548645,54,2,32,16,'A dsky ty dílo Boží byly; písmo také písmo Boží bylo vyryté na dskách.'),
(1548646,54,2,32,17,'Uslyšev pak Jozue hlas lidu křičícího, řekl Mojžíšovi: Hřmot boje v táboru jest.'),
(1548647,54,2,32,18,'Kterýžto odpověděl: Není to křik vítězících, ani křik poražených, hlas zpívajících já slyším.'),
(1548648,54,2,32,19,'I stalo se, když se přiblížil k stanům, že uzřel tele a tance. A rozhněvav se Mojžíš velmi, povrhl z rukou svých dsky, a rozrazil je pod Horou.'),
(1548649,54,2,32,20,'Vzal také tele, kteréž byli udělali, a spálil je v ohni, a setřel je až na prach, a vsypav na vodu, dal píti synům Izraelským.'),
(1548650,54,2,32,21,'A řekl Mojžíš Aronovi: Coť učinil lid tento, že jsi uvedl na něj hřích veliký?'),
(1548651,54,2,32,22,'Odpověděl Aron: Nehněvej se, pane můj. Ty víš, že lid tento k zlému nakloněn jest.'),
(1548652,54,2,32,23,'Nebo řekli mi: Udělej nám bohy, kteříž by šli před námi; nebo Mojžíšovi, muži tomu, kterýž vyvedl nás z země Egyptské, nevíme, co se stalo.'),
(1548653,54,2,32,24,'Jimž jsem odpověděl: Kdo má zlato, strhněte je s sebe. I dali mi, a uvrhl jsem je do ohně, a udělalo se to tele.'),
(1548654,54,2,32,25,'A vida Mojžíš lid obnažený, že obnažil jej Aron ku potupě před nepřátely, kteříž povstati měli proti nim,'),
(1548655,54,2,32,26,'Stoje v bráně táboru, řekl: Kdo jest Hospodinův, přistup ke mně. I shromáždili se k němu všickni synové Léví.'),
(1548656,54,2,32,27,'Jimž řekl: Tak praví Hospodin Bůh Izraelský: Připaš jeden každý meč svůj k boku svému; přejděte sem i tam od brány táboru k bráně, a zabí jeden každý bratra svého, a každý přítele svého i bližního svého.'),
(1548657,54,2,32,28,'I učinili synové Léví podlé řeči Mojžíšovy, a padlo jich v ten den z lidu na tři tisíce mužů.'),
(1548658,54,2,32,29,'Nebo řekl byl Mojžíš: Posvěťtež dnes rukou svých Hospodinu, jeden každý na synu svém a na bratru svém, aby vám dal dnes požehnání.'),
(1548659,54,2,32,30,'A když bylo nazejtří, řekl Mojžíš lidu: Vy jste zhřešili hříchem velikým. Protož nyní vstoupím k Hospodinu, zda bych ho ukrotil pro hřích váš.'),
(1548660,54,2,32,31,'Tedy navrátiv se Mojžíš k Hospodinu, řekl: Prosím, zhřešilť jest lid ten hříchem velikým; nebo udělali sobě bohy zlaté.'),
(1548661,54,2,32,32,'Nyní pak neb odpusť hřích jejich, a pakli nic, vymaž mne, prosím, z knihy své, kteroužs psal.'),
(1548662,54,2,32,33,'I řekl Hospodin Mojžíšovi: Kdo zhřešil proti mně, toho vymaži z knihy své.'),
(1548663,54,2,32,34,'Protož nyní jdi, veď lid tento, kamž jsem rozkázal tobě. Aj, anděl můj půjde před tebou; v den pak navštívení mého navštívím i na nich hřích jejich.'),
(1548664,54,2,32,35,'I bil Hospodin lid, proto že učinili tele, kteréž byl udělal Aron.'),
(1548665,54,2,33,1,'I mluvil Hospodin k Mojžíšovi: Jdi, vstup odsud, ty i lid, kterýž jsi vyvedl z země Egyptské do země, kterouž jsem přisáhl Abrahamovi, Izákovi a Jákobovi, řka: Semeni tvému dám ji,'),
(1548666,54,2,33,2,'(A pošli před tebou anděla, a vyženu Kananea, Amorea, Hetea, Ferezea, Hevea a Jebuzea,)'),
(1548667,54,2,33,3,'Do země oplývající mlékem a strdí. Neboť sám nevstoupím s tebou, proto že lid tvrdé šíje jsi, abych nezahubil tebe na cestě.'),
(1548668,54,2,33,4,'A uslyšav lid řeč tuto přezlou, zámutek nesli, aniž vzal kdo okrasy své na sebe.'),
(1548669,54,2,33,5,'Nebo byl řekl Hospodin Mojžíšovi: Mluv synům Izraelským: Vy jste lid tvrdé šíje; jakž jen jedinou vstoupím mezi vás, zahladím vás. Protož již, slož okrasu svou s sebe, a zvím, co učiniti mám s tebou.'),
(1548670,54,2,33,6,'I svlékli s sebe synové Izraelští okrasy své u hory Oréb.'),
(1548671,54,2,33,7,'Mojžíš pak vzav stánek, rozbil jej sobě vně za stany, vzdáliv se od táboru, a nazval jej stánkem úmluvy. Tedy kdokoli hledal Hospodina, ven choditi musil k stánku úmluvy, kterýž byl vně za stany.'),
(1548672,54,2,33,8,'K tomu také, když vycházel Mojžíš k stánku, povstával všecken lid a stál každý u dveří stanu svého, a hleděli za Mojžíšem, dokudž nevšel do stánku.'),
(1548673,54,2,33,9,'Bývalo pak toto, že když vcházíval Mojžíš do stánku, sstupoval sloup oblakový, a stával u dveří stánku, a mluvil s Mojžíšem.'),
(1548674,54,2,33,10,'A všecken lid vida sloup oblakový, an stojí u dveří stánku, povstávali všickni, a klaněli se každý u dveří stanu svého.'),
(1548675,54,2,33,11,'A mluvíval Hospodin k Mojžíšovi tváří v tvář, tak jako mluví člověk s přítelem svým. Potom navracel se do táboru, ale služebník jeho Jozue, syn Nun, mládenec, neodcházel z stánku.'),
(1548676,54,2,33,12,'I řekl Mojžíš Hospodinu: Pohleď, ty velíš mi, abych vedl lid tento, a neoznámils mi, koho pošleš se mnou, ještos pravil: Znám tě ze jména, k tomu také nalezl jsi milost přede mnou.'),
(1548677,54,2,33,13,'Již tedy, jestliže jsem jen nalezl milost před tebou, oznam mi, prosím, cestu svou, abych tě poznal, a abych nalezl milost před tebou; a pohleď, že národ tento jest lid tvůj.'),
(1548678,54,2,33,14,'I odpověděl: Tvář má předcházeti vás bude, a dámť odpočinutí.'),
(1548679,54,2,33,15,'I řekl: Nemá-liť předcházeti nás tvář tvá, nevyvozuj nás odsud.'),
(1548680,54,2,33,16,'Nebo po čem poznáno bude zde, že jsem nalezl milost před tebou, já i lid tvůj? Zdali ne po tom, když půjdeš s námi, a když odděleni budeme, já a lid tvůj, ode všeho lidu, kterýž jest na tváři země?'),
(1548681,54,2,33,17,'I řekl Hospodin Mojžíšovi: I tu také věc, kterouž jsi pravil, učiním; nebo jsi nalezl milost přede mnou, a znám tě ze jména.'),
(1548682,54,2,33,18,'Řekl opět: Okažiž mi, prosím, slávu svou.'),
(1548683,54,2,33,19,'Kterýž odpověděl: Já způsobím to, aby šlo mimo tebe před tváří tvou všecko dobré mé, a zavolám ze jména: Hospodin před tváří tvou. Smiluji se, nad kýmž se smiluji, a slituji se, nad kýmž se slituji.'),
(1548684,54,2,33,20,'Řekl také: Nebudeš moci viděti tváři mé; neboť neuzří mne člověk, aby živ zůstal.'),
(1548685,54,2,33,21,'I to řekl Hospodin: Aj, místo u mne, a staneš na skále.'),
(1548686,54,2,33,22,'A když tudy půjde sláva má, postavím tě v rozsedlině skály, a přikryji tě rukou svou, dokudž nepřejdu.'),
(1548687,54,2,33,23,'Potom odejmu ruku svou, i uzříš hřbet můj, ale tvář má nebude spatřína.'),
(1548688,54,2,34,1,'I řekl Hospodin k Mojžíšovi: Vyteš sobě dvě dsky kamenné podobné prvním, a napíši na dskách těch slova, kteráž byla na dskách prvních, kteréž jsi rozrazil.'),
(1548689,54,2,34,2,'Budiž tedy hotov ráno, a vstoupíš v jitře na horu Sinai, a staneš přede mnou na vrchu hory té.'),
(1548690,54,2,34,3,'Žádný ať nevstupuje s tebou, aniž také kdo vidín bude na vší hoře; ani ovce neb volové pásti se budou naproti hoře této.'),
(1548691,54,2,34,4,'Tedy Mojžíš vytesal dvě dsky kamenné podobné prvním, a vstav ráno, vstoupil na horu Sinai, jakž mu přikázal Hospodin, a vzal v ruku svou dvě dsky kamenné.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548692,54,2,34,5,'I sstoupil Hospodin v oblaku, a stál s ním tam, a zavolal ze jména: HOSPODIN.'),
(1548693,54,2,34,6,'Nebo pomíjeje Hospodin tvář jeho, volal: Hospodin, Hospodin, Bůh silný, lítostivý a milostivý, dlouhočekající a hojný v milosrdenství a pravdě,'),
(1548694,54,2,34,7,'Milosrdenství čině tisícům, odpouštěje nepravost a přestoupení i hřích, a kterýž nikoli neospravedlňuje vinného, navštěvuje nepravost otců na synech, a na synech synů do třetího i čtvrtého pokolení.'),
(1548695,54,2,34,8,'Mojžíš pak rychle sklonil hlavu k zemi, a poklonu učinil.'),
(1548696,54,2,34,9,'A řekl: Prosím, našel-li jsem milost v očích tvých, Pane, nechť jde, prosím, Pán u prostřed nás, nebo lid jest tvrdé šíje, a milostiv buď nepravosti naší a hříchu našemu, a měj nás za dědictví.'),
(1548697,54,2,34,10,'Kterýžto řekl: Aj, já učiním smlouvu přede vším lidem tvým. Učiním divné věci, kteréž nejsou učiněny na vší zemi a ve všech národech, a viděti bude všecken lid, (mezi nimiž jsi,) skutky Hospodinovy; nebo hrozné bude to, což já učiním s tebou.'),
(1548698,54,2,34,11,'Zachovej to, což já dnes tobě přikazuji. Aj, já vyženu před tváří tvou Amorea a Kananea, Hetea a Ferezea, Hevea a Jebuzea.'),
(1548699,54,2,34,12,'Varuj se pak, abys nečinil smlouvy s obyvateli země té, do kteréž vejdeš, ať by nebyli osídlem u prostřed tebe.'),
(1548700,54,2,34,13,'Ale zboříte oltáře jejich, a modly jejich polámete, a jejich háje posekáte.'),
(1548701,54,2,34,14,'Nebo nebudeš se klaněti Bohu jinému, proto že Hospodin jest, jméno má horlivý, Bůh silný, horlivý jest.'),
(1548702,54,2,34,15,'Nevcházej v smlouvu s obyvateli země té, aby když by smilnili, jdouce po bozích svých, a obětovali bohům svým, nepovolali tě, a jedl bys z oběti jejich.'),
(1548703,54,2,34,16,'A abys nebral ze dcer jeho synům svým, i smilnily by dcery jejich, jdouce po bozích svých, a naučily by smilniti syny tvé, jdouce po bozích svých.'),
(1548704,54,2,34,17,'Bohů slitých neuděláš sobě.'),
(1548705,54,2,34,18,'Slavnost přesnic zachovávati budeš. Za sedm dní jísti budeš chleby nekvašené, jakž jsem přikázal tobě, v čas vyměřený měsíce Abib; nebo měsíce toho vyšel jsi z Egypta.'),
(1548706,54,2,34,19,'Všecko což otvírá život, mé jest, i všeliký samec v dobytku tvém, prvorozený z volů a ovcí.'),
(1548707,54,2,34,20,'Ale prvorozené osle vyplatíš dobytčetem; pakli bys nevyplatil, šíji zlomíš jemu. Každého prvorozeného z synů svých vyplatíš, aniž ukáží se přede mnou prázdní.'),
(1548708,54,2,34,21,'Šest dní pracovati budeš, dne pak sedmého přestaneš; v čas orání i žně přestaneš.'),
(1548709,54,2,34,22,'A učiníš sobě slavnost téhodnů, svátek prvotin žně pšeničné a slavnost klizení po vyjití každého roku.'),
(1548710,54,2,34,23,'Třikrát v roce ukáže se každý z vás pohlaví mužského před oblíčejem Panovníka Hospodina, Boha Izraelského.'),
(1548711,54,2,34,24,'Nebo vyvrhu národy od tváři tvé a rozšířím meze tvé, aniž kdo sáhne na zemi tvou, když vstoupíš, abys se ukázal před Hospodinem Bohem svým třikrát v roce.'),
(1548712,54,2,34,25,'Nebudeš obětovati krve oběti mé, dokavadž u tebe kvas jest, aniž zůstane do jitra obět slavnosti Fáze.'),
(1548713,54,2,34,26,'Prvotiny prvních úrod země své přinášeti budeš do domu Hospodina Boha svého. Nebudeš vařiti kozelce v mléce matky jeho.'),
(1548714,54,2,34,27,'I řekl Hospodin Mojžíšovi: Napiš sobě slova tato; nebo podlé slov těch učinil jsem smlouvu s tebou a s Izraelem.'),
(1548715,54,2,34,28,'Byl pak tam s Hospodinem čtyřidceti dní a čtyřidceti nocí, chleba nejedl a vody nepil; a napsal na dskách slova té smlouvy, totiž deset slov.'),
(1548716,54,2,34,29,'I stalo se, když sstupoval Mojžíš s hory Sinai, (a měl dvě dsky svědectví v rukou svých, když sstupoval s hory), nevěděl, že by se stkvěla kůže tváři jeho, když mluvil s ním.'),
(1548717,54,2,34,30,'A viděl Aron i všickni synové Izraelští Mojžíše, a aj, stkvěla se kůže tváři jeho, a nesměli přistoupiti k němu.'),
(1548718,54,2,34,31,'Ale Mojžíš zavolal jich, a navrátili se k němu Aron i všecka knížata shromáždění toho, a mluvil Mojžíš s nimi.'),
(1548719,54,2,34,32,'Potom přišli také k němu všickni synové Izraelští, jimžto přikázal všecko, což s ním mluvil Hospodin na hoře Sinai.'),
(1548720,54,2,34,33,'Dokudž pak mluvil Mojžíš s nimi, měl zástěru na tváři své.'),
(1548721,54,2,34,34,'Ale když vcházel Mojžíš před tvář Hospodina, aby mluvil s ním, odjímal zástěru, dokudž nevyšel. Vyšed pak, mluvil synům Izraelským, což mu bylo rozkázáno.'),
(1548722,54,2,34,35,'Tedy viděli synové Izraelští tvář Mojžíšovu, že se stkvěla kůže tváři jeho. A kladl zase Mojžíš zástěru na tvář svou, dokudž nevcházel, aby mluvil s ním.'),
(1548723,54,2,35,1,'Tedy svolal Mojžíš všecko shromáždění synů Izraelských, a řekl jim: Tato jsou slova, kteráž přikázal vám Hospodin, abyste je činili.'),
(1548724,54,2,35,2,'Šest dní děláno bude dílo, ale v sedmý den mějte svátek, sobotu odpočinutí Hospodinova. Kdo by dělal v něm dílo, umře.'),
(1548725,54,2,35,3,'Nezanítíte ohně nikdež v příbytcích svých v den sobotní.'),
(1548726,54,2,35,4,'Mluvil také Mojžíš ke všemu shromáždění synů Izraelských takto: Toto jest slovo, kteréž přikázal Hospodin, řka:'),
(1548727,54,2,35,5,'Sebeřte z sebe obět pozdvižení Hospodinu. Každý, kdož jest ochotný v srdci svém, přinese tu obět Hospodinu: Zlato, stříbro a měď,'),
(1548728,54,2,35,6,'A postavec modrý, a šarlat, a červec dvakrát barvený, a bílé hedbáví, a kozí srsti;'),
(1548729,54,2,35,7,'Též kůže skopců na červeno barvené, a kůže jezevčí, a dříví setim,'),
(1548730,54,2,35,8,'A olej k svícení a vonné věci na olej ku pomazání a pro kadění vonné,'),
(1548731,54,2,35,9,'A kamení onychinové, a jiné kamení k vsazování do náramenníku a náprsníku.'),
(1548732,54,2,35,10,'A všickni, kdož jsou vtipní mezi vámi, přijdou a dělati budou, cožkoli přikázal Hospodin:'),
(1548733,54,2,35,11,'Příbytek, stánek jeho i přikrytí jeho a háky jeho, dsky jeho, svlaky jeho, sloupy jeho i podstavky jeho;'),
(1548734,54,2,35,12,'Truhlu s sochory jejími, slitovnici a oponu zastření;'),
(1548735,54,2,35,13,'Stůl i sochory k němu se všemi nádobami jeho, i chléb předložení;'),
(1548736,54,2,35,14,'A svícen k svícení s nádobami jeho i lampy jeho, a olej k svícení;'),
(1548737,54,2,35,15,'Též oltář pro kadění a sochory jeho, i olej pomazání a kadidlo z vonných věcí, i zastření dveří v příbytku;'),
(1548738,54,2,35,16,'Oltář k zápalu a rošt jeho měděný a sochory jeho, i všecka nádobí jeho, i umyvadlo s podstavkem jeho;'),
(1548739,54,2,35,17,'Koltry očkovaté k síni, sloupy její a podstavky její, i zastření brány do síně;'),
(1548740,54,2,35,18,'Kolíky k příbytku, a kolíky síně s provázky jejich;'),
(1548741,54,2,35,19,'Roucha k službě, k přisluhování v svatyni, i roucho svaté Arona kněze, i roucho synů jeho k konání úřadu kněžského.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548742,54,2,35,20,'Vyšlo tedy všecko shromáždění synů Izraelských od tváři Mojžíšovy,'),
(1548743,54,2,35,21,'A přišli, každý muž, kteréhož ponuklo srdce jeho, a každý, v němž duch jeho byl dobrovolný, a přinesli obět pozdvižení Hospodinu, k dílu stánku úmluvy a ke vší službě jeho, i k rouchu svatému.'),
(1548744,54,2,35,22,'Přicházeli muži i ženy, každý, kdož byl ochotný v srdci, a přinášeli spinadla, a náušnice, a prsteny, a záponky z pravých rukou, všelijaké nádobí zlaté, a kdožkoli obětoval obět zlata Hospodinu.'),
(1548745,54,2,35,23,'Každý, kdož měl postavec modrý a šarlat, a červec dvakrát barvený, a bílé hedbáví a kozí srsti, a kůže skopců na červeno barvené, a kůže jezevčí, přinesl to.'),
(1548746,54,2,35,24,'Kdokoli obětoval obět stříbra a mědi, přinášeli to za obět pozdvižení Hospodinu; každý také, kdo měl dříví setim, ke všelikému dílu služebnosti, přinášeli je.'),
(1548747,54,2,35,25,'Ano i všecky ženy vtipné rukama svýma předly, a přinesly, co napředly, postavec modrý a šarlat, a červec dvakrát barvený a bílé hedbáví.'),
(1548748,54,2,35,26,'Všecky pak ženy, kterýchž ponuklo srdce jejich, aby předly uměle, předly srsti kozí.'),
(1548749,54,2,35,27,'Knížata pak přinášeli kamení onychinové, a jiné kamení k vsazování do náramenníku a náprsníku,'),
(1548750,54,2,35,28,'Též vonné věci a olej k svícení, a k oleji pomazání, a k vonnému kadidlu.'),
(1548751,54,2,35,29,'Každý muž i žena, v nichž ochotné srdce jejich bylo k tomu, aby přinášeli potřeby ke všelikému dílu, kteréž byl přikázal dělati Hospodin skrze Mojžíše, přinášeli synové Izraelští obět dobrovolnou Hospodinu.'),
(1548752,54,2,35,30,'Tedy řekl Mojžíš synům Izraelským: Pohleďte, povolal ze jména Hospodin Bezeleele, syna Uri, syna Hur, z pokolení Judova.'),
(1548753,54,2,35,31,'A naplnil ho duchem Božím, moudrostí, rozumností i uměním všelijakého řemesla,'),
(1548754,54,2,35,32,'Aby vtipně smysliti uměl, jak by se co dělati mělo na zlatu a stříbru a mědi,'),
(1548755,54,2,35,33,'I v řemeslném strojení kamenů k vsazování, i v díle od dřeva, aby dělal všelijakým řemeslem vtipným.'),
(1548756,54,2,35,34,'Dal nadto v srdce jeho i to, aby učiti mohl on i Aholiab, syn Achisamechův z pokolení Dan.'),
(1548757,54,2,35,35,'Naplnil je moudrostí srdce, aby dělali všelijaké dílo tesařské a řemeslné, i krumpéřské a vytkávané z postavce modrého a šarlatu, a červce dvakrát barveného, a bílého hedbáví, a aby dělali všelijaké dílo a vymýšleli vtipné věci.'),
(1548758,54,2,36,1,'Tedy dělal Bezeleel a Aholiab i všeliký muž vtipný, jimž dal Hospodin moudrost a rozumnost, aby uměli dělati všeliké dílo k službě svatyně, všecko, což přikázal Hospodin.'),
(1548759,54,2,36,2,'Povolal pak Mojžíš Bezeleele a Aholiaba i každého muže vtipného, v jehož srdce dal Hospodin moudrost, každého také, kohož ponoukalo srdce jeho, aby přistoupil ku práci díla toho.'),
(1548760,54,2,36,3,'A vzali od Mojžíše všecky dary, kteréž přinesli synové Izraelští k dílu služebnému svatyně, aby dělali je. Ale oni vždy předce přinášeli k němu každého jitra dary dobrovolné.'),
(1548761,54,2,36,4,'Tedy přišli všickni vtipní dělníci díla svatyně, každý od díla svého, kteréž dělali,'),
(1548762,54,2,36,5,'A mluvili k Mojžíšovi těmi slovy: Mnohem více přináší lid, nežli potřebí jest k dělání díla, kteréž přikázal Hospodin dělati.'),
(1548763,54,2,36,6,'I rozkázal Mojžíš, aby provoláno bylo v vojště takto: Muž ani žena, žádný nepřinášej více oběti k svatyni. I zbráněno jest lidu, aby nenosili.'),
(1548764,54,2,36,7,'Nebo měli potřeb hojně dosti k dělání všelikého díla, tak že zbývalo.'),
(1548765,54,2,36,8,'I dělal každý vtipný z dělníků těch dílo to, příbytek z desíti čalounů, kteříž byli z bílého hedbáví přesukovaného, a z postavce modrého a šarlatu, a z červce dvakrát barveného, cherubíny dílem řemeslným udělal na nich.'),
(1548766,54,2,36,9,'Dlouhost čalounu jednoho osm a dvadceti loktů, a čtyř loktů širokost čalounu jednoho; všickni čalounové byli jednostejné míry.'),
(1548767,54,2,36,10,'Potom spojil pět čalounů jeden s druhým, a pět jiných čalounů spojil jeden s druhým.'),
(1548768,54,2,36,11,'Nadělal i ok z hedbáví modrého po kraji čalounu jednoho na konci, kde se spojovati má s druhým, a tolikéž udělal na kraji čalounu druhého na konci v spojení druhém.'),
(1548769,54,2,36,12,'Padesáte ok udělal na čalounu jednom, a padesáte ok udělal po kraji čalounu, kterýmž připojen byl k druhému; oko jedno proti druhému bylo.'),
(1548770,54,2,36,13,'Udělal i padesáte haklíků zlatých a spojil čalouny jeden s druhým haklíky těmi; a tak udělán jest příbytek jeden.'),
(1548771,54,2,36,14,'Nadto nadělal houní z srstí kozích na stánek, k přistírání příbytku po vrchu; jedenácte houní udělal.'),
(1548772,54,2,36,15,'Dlouhost houně jedné třidceti loktů, a širokost houně jedné čtyř loktů; jednostejná míra byla těch jedenácti houní.'),
(1548773,54,2,36,16,'A spojil pět houní obzvláštně, a šest houní obzvláštně.'),
(1548774,54,2,36,17,'Udělal také padesáte ok po kraji houně na konci, kdež se spojovati má, a padesáte ok udělal po kraji houně v spojení druhém.'),
(1548775,54,2,36,18,'Udělal k tomu haklíků měděných padesáte k spojení stánku, aby byl jedno.'),
(1548776,54,2,36,19,'Nadto udělal přikrytí stánku z koží skopcových na červeno barvených, a přikrytí z koží jezevčích svrchu.'),
(1548777,54,2,36,20,'Nadělal k příbytku i desk z dříví setim stojatých.'),
(1548778,54,2,36,21,'Desíti loktů dlouhost dsky, a půl druhého širokost dsky každé.'),
(1548779,54,2,36,22,'Dva čepy měla dska jedna, podobně jako stupně u schodu spořádané, jeden proti druhému; tak udělal u všech desk příbytku.'),
(1548780,54,2,36,23,'Zdělal i dsky k příbytku, dvadceti desk k straně polední, k větru polednímu.'),
(1548781,54,2,36,24,'A čtyřidceti podstavků stříbrných udělal pode dvadceti desk, dva podstavky pod jednu dsku ke dvěma čepům jejím, a dva podstavky pod dsku druhou pro dva čepy její.'),
(1548782,54,2,36,25,'Na druhé pak straně příbytku k straně půlnoční udělal dvadceti desk,'),
(1548783,54,2,36,26,'A čtyřidceti podstavků jejich stříbrných, dva podstavky pod jednu dsku a dva podstavky pod dsku druhou.'),
(1548784,54,2,36,27,'Na straně pak příbytku k západu udělal šest desk.'),
(1548785,54,2,36,28,'Dvě dsky udělal v úhlech po obou stranách příbytku.'),
(1548786,54,2,36,29,'A byly spojené po spodu a tolikéž spojené svrchu k jednomu kruhu; tak udělal po obou stranách ve dvou úhlech.'),
(1548787,54,2,36,30,'A tak bylo osm desk a podstavků jejich stříbrných šestnácte, dva podstavkové pod každou dskou.'),
(1548788,54,2,36,31,'Nadělal i svlaků z dřívi setim, pět ke dskám straně příbytku jedné,'),
(1548789,54,2,36,32,'A pět svlaků ke dskám druhé strany příbytku, a pět svlaků ke dskám strany příbytku západní, dosahujících k oběma úhlům.'),
(1548790,54,2,36,33,'A svlak prostřední udělal, aby šel po prostředku desk od jednoho kraje k druhému.'),
(1548791,54,2,36,34,'Dsky pak obložil zlatem a kruhy jejich udělal z zlata, aby v nich svlaky byly; a obložil svlaky zlatem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548792,54,2,36,35,'Udělal také oponu z postavce modrého a šarlatu, a z červce dvakrát barveného, a z bílého hedbáví přesukovaného; dílem řemeslným udělal ji s figurami cherubínů.'),
(1548793,54,2,36,36,'A udělal pro ni čtyři sloupy z dříví setim, a obložil je zlatem; hákové pak jejich byli zlatí, a slil k nim čtyři podstavky stříbrné.'),
(1548794,54,2,36,37,'Udělal také zastření ke dveřům stánku z postavce modrého, z šarlatu a z červce dvakrát barveného a z bílého hedbáví přesukovaného, dílem krumpéřským,'),
(1548795,54,2,36,38,'A sloupů k tomu zastření pět s háky jejich, (obložil pak makovice a přepásaní jich zlatem), a podstavků pět měděných.'),
(1548796,54,2,37,1,'Udělal také Bezeleel truhlu z dříví setim, jejíž dlouhost byla půl třetího lokte, a půl druhého lokte širokost, vysokost také půl druhého lokte.'),
(1548797,54,2,37,2,'A obložil ji zlatem čistým vnitř i zevnitř, a udělal jí korunu zlatou vůkol.'),
(1548798,54,2,37,3,'Slil jí také čtyři kruhy zlaté ke čtyřem úhlům jejím, dva totiž kruhy po jedné straně její, a dva kruhy po druhé straně její.'),
(1548799,54,2,37,4,'Zdělal i sochory z dříví setim a obložil je zlatem.'),
(1548800,54,2,37,5,'A uvlékl sochory do kruhů po stranách truhly; aby na nich nošena byla truhla.'),
(1548801,54,2,37,6,'Udělal také slitovnici z zlata čistého. Půl třetího lokte byla dlouhost její, a půl druhého lokte širokost její.'),
(1548802,54,2,37,7,'Udělal i dva cherubíny z zlata, z taženého zlata udělal je na dvou koncích slitovnice,'),
(1548803,54,2,37,8,'Cherubína jednoho na jednom konci a cherubína druhého na druhém konci; na slitovnici udělal cherubíny, na obou koncích jejích.'),
(1548804,54,2,37,9,'Ti pak cherubínové měli křídla vztažená svrchu nad ní, zastírajíce křídly svými slitovnici; a tváři jejich byly obráceny jedna k druhé, k slitovnici byly obráceny tváři cherubínů.'),
(1548805,54,2,37,10,'Udělal i stůl z dříví setim. Dvou loket byla dlouhost jeho a na loket širokost jeho, půl druhého pak lokte vysokost.'),
(1548806,54,2,37,11,'A obložil jej zlatem čistým, i korunu zlatou udělal mu vůkol.'),
(1548807,54,2,37,12,'Udělal mu i lištu dlani zšíří vůkol, a udělal korunu zlatou okolo té lišty.'),
(1548808,54,2,37,13,'Slil také k němu čtyři kruhy zlaté a vpustil je do čtyř úhlů, kteříž byli na čtyřech nohách jeho.'),
(1548809,54,2,37,14,'Proti té liště byli kruhové, skrze něž by provlačováni byli sochorové k nošení stolu.'),
(1548810,54,2,37,15,'Udělal i sochory z dříví setim, kteréžto obložil zlatem k nošení stolu.'),
(1548811,54,2,37,16,'A zdělal nádoby, kteréž byly na stole, misy jeho a lžice jeho, a koflíky jeho, a přikryvadla k přikrývání z čistého zlata.'),
(1548812,54,2,37,17,'Udělal také svícen z zlata čistého, z taženého zlata udělal svícen; sloupec jeho i prutové jeho, misky jeho, koule jeho i květové jeho z něho byli.'),
(1548813,54,2,37,18,'Šest pak prutů bylo po stranách jeho, tři prutové s jedné strany jeho, a tři prutové s druhé strany jeho.'),
(1548814,54,2,37,19,'Tři misky na způsob pecky mandlové udělány byly na prutu jednom, a koule a květ, a tři misky na způsob pecky mandlové udělány na prutu druhém, a koule a květ; tak i na jiných šesti prutech z svícnu vycházejících.'),
(1548815,54,2,37,20,'Na svícnu také byly čtyři misky, udělané na způsob mandlové pecky, a koule jeho i květové jeho.'),
(1548816,54,2,37,21,'A byla koule pode dvěma pruty z něho, a koule druhá pode dvěma pruty z něho, a koule třetí pode dvěma pruty z něho, a tak pod šesti pruty vycházejícími z něho.'),
(1548817,54,2,37,22,'Koule jejich i prutové jejich z něho byli, všecko hned jedním tažením z zlata čistého.'),
(1548818,54,2,37,23,'Udělal i lamp jeho sedm, i utěradla jeho, i nádoby k oharkům jeho z zlata čistého.'),
(1548819,54,2,37,24,'Z centnéře zlata čistého udělal jej se vším tím nádobím.'),
(1548820,54,2,37,25,'Udělal také oltář pro kadění z dříví setim, lokte zdélí a lokte zšíří, čtverhraný, dvou pak loket zvýší; z něho byli rohové jeho.'),
(1548821,54,2,37,26,'A obložil jej zlatem čistým, svrchek jeho i po stranách vůkol, i rohy jeho; a udělal mu korunu zlatou vůkol.'),
(1548822,54,2,37,27,'Po dvou podobně kruzích zlatých udělal u něho, pod korunou ve dvou úhlech jeho, po dvou stranách jeho, skrze něž by provlačováni byli sochorové, aby nošen byl na nich.'),
(1548823,54,2,37,28,'A zdělal ty sochory z dříví setim, a obložil je zlatem.'),
(1548824,54,2,37,29,'Nadělal také oleje pomazání svatého, a kadidla z vonných věcí, čistého, dílem apatykářským.'),
(1548825,54,2,38,1,'Udělal také oltář k zápalu z dříví setim, pěti loket zdélí a pěti loket zšíří, čtverhraný, a tří loket zvýší.'),
(1548826,54,2,38,2,'A zdělal mu rohy na čtyřech úhlech jeho; z něho byli rohové jeho, a obložil jej mědí.'),
(1548827,54,2,38,3,'Nadělal také všelijakých nádob k oltáři, hrnců a lopat, a kotlíků a vidliček, a nádob jeho k uhlí; všecka nádobí jeho udělal měděná.'),
(1548828,54,2,38,4,'Udělal k oltáři i rošt mřežovaný, měděný, pod okolkem oltáře dole, až do prostřed něho.'),
(1548829,54,2,38,5,'A slil čtyři kruhy na čtyřech krajích k roštu měděnému, v nichž by sochorové bývali.'),
(1548830,54,2,38,6,'Sochory pak udělal z dříví setim a obložil je mědí.'),
(1548831,54,2,38,7,'A uvlékl ty sochory do těch kruhů po obou stranách oltáře k nošení jeho na nich; prázdný z prken udělal jej.'),
(1548832,54,2,38,8,'Udělal též umyvadlo měděné, a podstavek jeho měděný z zrcadel houfně přicházejících žen, kteréž přicházely ke dveřím stánku úmluvy.'),
(1548833,54,2,38,9,'Udělal také síň k straně polední; koltry očkovaté síně té z bílého hedbáví přesukovaného na sto loket,'),
(1548834,54,2,38,10,'Sloupů jejich dvadceti, a k nim podstavků dvadceti z mědi, háky na sloupích, a přepásaní jejich z stříbra.'),
(1548835,54,2,38,11,'Tolikéž k straně půlnoční koltry na sto loket, sloupů k nim dvadceti a podstavků jejich dvadceti z mědi, háky na sloupích a přepásaní jejich z stříbra.'),
(1548836,54,2,38,12,'K straně pak západní koltry očkovaté na padesáte loket, sloupů k nim deset a podstavků jejich deset, háky na sloupích a přepásaní jejich z stříbra.'),
(1548837,54,2,38,13,'A v straně přední na východ padesáti loktů,'),
(1548838,54,2,38,14,'Koltry očkovaté patnácti loktů byly při straně jedné, sloupové k nim tři, a podstavkové jejich tři.'),
(1548839,54,2,38,15,'A k straně druhé, u brány síně té, jakž tam, tak tuto, koltry očkovaté patnácti loktů, sloupové k nim tři a podstavkové jejich tři.'),
(1548840,54,2,38,16,'Všecky koltry síně vůkol očkovaté z bílého hedbáví přesukovaného.'),
(1548841,54,2,38,17,'Podstavkové pak sloupů z mědi, hákové na sloupích a přepásaní jich z stříbra, a obložení makovic jejich z stříbra; všickni také sloupové síně přepásáni byli stříbrem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548842,54,2,38,18,'Zastření pak brány síňce dílem krumpéřským z postavce modrého a šarlatu, a červce dvakrát barveného a hedbáví bílého přesukovaného; dlouhost jeho dvadceti loktů, výsost pak šířky pěti loktů, jako i jiných koltr síně očkovatých.'),
(1548843,54,2,38,19,'A sloupové k ní čtyři a podstavkové jejich čtyři z mědi, hákové jejich stříbrní, a obložení makovic jejich a přepásaní jejich z stříbra.'),
(1548844,54,2,38,20,'Všickni pak kolíkové příbytku a síně vůkol byli z mědi.'),
(1548845,54,2,38,21,'Tyto jsou věci vyčtené k příbytku, příbytku svědectví, kteréž jsou vyčteny podlé rozkázaní Mojžíšova, skrze Itamara, syna Arona kněze, k službě Levítů.'),
(1548846,54,2,38,22,'A Bezeleel, syn Uri, syna Hur, z pokolení Juda, udělal všecky tyto věci, kteréž přikázal Hospodin Mojžíšovi;'),
(1548847,54,2,38,23,'A s ním Aholiab, syn Achisamechův z pokolení Dan, tesař a vtipný řemeslník, a krumpéř na modrém postavci a šarlatu, a červci dvakrát barveném a kmentu.'),
(1548848,54,2,38,24,'Všeho zlata vynaloženého na samo dílo, na všecko dílo svatyně, (bylo pak zlato obětované), devět a dvadceti centnéřů, a sedm set třidceti lotů podlé váhy svatyně.'),
(1548849,54,2,38,25,'Stříbra pak od těch, jenž náležejí ku počtu shromáždění, sto centnéřů, a tisíc sedm set sedmdesáte pět lotů podlé váhy svatyně.'),
(1548850,54,2,38,26,'Půl lotu z každé hlavy podlé váhy svatyně, ode všech jdoucích v počet od dvadcíti let a výše, jichž bylo šestkrát sto tisíc, tři tisíce pět set a padesáte.'),
(1548851,54,2,38,27,'A bylo sto centnéřů stříbra k slévání podstavků svatyně a podstavků opony; sto podstavků ze sta centnéřů, centnéř do podstavku.'),
(1548852,54,2,38,28,'A z tisíce sedmi set sedmdesáti pěti lotů udělal háky na sloupy, a obložil makovice jejich a přepásal je.'),
(1548853,54,2,38,29,'Mědi pak obětované bylo sedmdesáte centnéřů a dva tisíce a čtyři sta lotů.'),
(1548854,54,2,38,30,'A udělal z ní podstavky ke dveřům stánku svědectví a oltář měděný, a rošt měděný k němu, a všecky nádoby oltáře,'),
(1548855,54,2,38,31,'A podstavky síně vůkol a podstavky brány síně, všecky také kolíky příbytku a všecky kolíky síňce vůkol.'),
(1548856,54,2,39,1,'Z modrého pak postavce a šarlatu a červce dvakrát barveného udělali roucha k službě, k přisluhování v svatyni. Udělali i roucho svaté, kteréž by bylo Aronovi, jakž byl přikázal Hospodin Mojžíšovi.'),
(1548857,54,2,39,2,'A udělal náramenník z zlata, postavce modrého a šarlatu, a červce dvakrát barveného, a bílého hedbáví přesukovaného.'),
(1548858,54,2,39,3,'I nadělali plíšků zlatých, a nastříhali z nich nití, aby jimi províjeli skrze modrý postavec a šarlat, a červec dvakrát barvený a bílé hedbáví, dílem řemeslným.'),
(1548859,54,2,39,4,'Náramky u něho udělali tak, aby se jeden s druhým spojiti mohl; na dvou krajích svých spojoval se.'),
(1548860,54,2,39,5,'Přepásaní také náramenníka, kteréž bylo na něm, z týchž věcí bylo a týmž dílem, z zlata, postavce modrého a šarlatu a červce dvakrát barveného, a bílého hedbáví přesukovaného, jakž byl přikázal Hospodin Mojžíšovi.'),
(1548861,54,2,39,6,'Přisadili i kamení onychinové, vložené a vsazené do zlata, řezané tak, jako ryty bývají pečeti, s jmény synů Izraelských.'),
(1548862,54,2,39,7,'A vložil je na vrchní kraje náramenníku, aby byli kamenové pro pamět na syny Izraelské, jakž byl přikázal Hospodin Mojžíšovi.'),
(1548863,54,2,39,8,'Udělal i náprsník dílem řemeslným, takovým dílem jako náramenník, z zlata, postavce modrého a šarlatu, a červce dvakrát barveného, a bílého hedbáví přesukovaného.'),
(1548864,54,2,39,9,'Čtverhranatý byl; dvojnásobní udělali náprsník, na píd zdélí, a na píd zšíří, dvojnásobní.'),
(1548865,54,2,39,10,'A vysadili jej čtyřmi řady kamení drahého pořádkem tímto: Sardius, topazius a smaragdus v řadu prvním;'),
(1548866,54,2,39,11,'V řadu pak druhém karbunkulus, zafir a jaspis;'),
(1548867,54,2,39,12,'A v řadu třetím linkurius, achates a ametyst;'),
(1548868,54,2,39,13,'A v čtvrtém řadu chrysolit, onychin a beryl, vložení a vsazení do zlata v svém pořádku.'),
(1548869,54,2,39,14,'Těch pak kamenů s jmény synů Izraelských bylo dvanácte vedlé jmen jejich, vyrytých, jako pečet ryta bývá, každý vedlé jména svého pro dvanáctero pokolení.'),
(1548870,54,2,39,15,'Udělali i k náprsníku řetízky jednostejné, dílem točeným z zlata čistého.'),
(1548871,54,2,39,16,'Udělali také dva haklíky zlaté, a dva kroužky zlaté, a připjali ty dva kroužky na dvou krajích náprsníku.'),
(1548872,54,2,39,17,'A prostrčili dva řetízky zlaté skrze dva kroužky na krajích náprsníku.'),
(1548873,54,2,39,18,'Druhé pak dva konce dvou řetízků vpjali do dvou těch haklíků, a dali je na vrchní kraje náramenníku po předu.'),
(1548874,54,2,39,19,'Udělali též dva kroužky zlaté, kteréž dali na dva kraje náprsníku, na té obrubě jeho, kteráž byla po straně náramenníka po spodu.'),
(1548875,54,2,39,20,'Udělali ještě dva jiné kroužky zlaté, kteréž dali na dvě strany náramenníka zespod po předu, proti spojení jeho, kteréž jest nad přepásaním náramenníka.'),
(1548876,54,2,39,21,'I přivázali náprsník od kroužků jeho k kroužkům toho náramenníka tkanicí hedbáví modrého, aby byl nad přepásaním náramenníka, a aby neodevstával náprsník od náramenníka, jakž byl přikázal Hospodin Mojžíšovi.'),
(1548877,54,2,39,22,'Udělal také plášť náležející k náramenníku, dílem vytkávaným, všecken z postavce modrého,'),
(1548878,54,2,39,23,'A díru u prostřed pláště, jako díra v pancíři; okolek byl po kraji jejím vůkol, aby se neroztrhl.'),
(1548879,54,2,39,24,'Udělali také na podolku pláště jablka zrnatá z postavce modrého a šarlatu, a červce dvakrát barveného, a bílého hedbáví přesukovaného.'),
(1548880,54,2,39,25,'Nadělali i zvonečků z zlata čistého, a zzavěšovali zvonečky ty mezi jablky zrnatými u podolku pláště vůkol, u prostřed mezi jablky zrnatými;'),
(1548881,54,2,39,26,'Zvonček a jablko zrnaté, opět za tím zvonček a jablko zrnaté u podolku pláště vůkol, k užívání toho při službě, jakž byl přikázal Hospodin Mojžíšovi.'),
(1548882,54,2,39,27,'Potom udělali sukni z bílého hedbáví dílem vytkávaným, Aronovi a synům jeho.'),
(1548883,54,2,39,28,'I čepici z bílého hedbáví, a klobouky ozdobné z bílého hedbáví, a košilky tenké z bílého hedbáví přesukovaného,'),
(1548884,54,2,39,29,'Pás také z bílého hedbáví přesukovaného, a postavce modrého a šarlatu, a červce dvakrát barveného, dílem krumpéřským, jakž byl přikázal Hospodin Mojžíšovi,'),
(1548885,54,2,39,30,'Udělali i plech koruny svaté z zlata čistého, a napsali na něm písmo dílem vyrývajících pečeti: Svatost Hospodinu.'),
(1548886,54,2,39,31,'A dali do něho tkanici z hedbáví modrého, aby přivázán byl k čepici na hoře, jakž byl přikázal Hospodin Mojžíšovi.'),
(1548887,54,2,39,32,'A tak dokonáno jest všecko dílo příbytku stánku úmluvy; a učinili synové Izraelští všecko, jakž přikázal Hospodin Mojžíšovi, tak učinili,'),
(1548888,54,2,39,33,'A přinesli příbytek ten k Mojžíšovi, stánek i všecka nádobí jeho, háky jeho, dsky jeho, svlaky jeho, i sloupy jeho a podstavky jeho,'),
(1548889,54,2,39,34,'Přikrytí také z koží skopových na červeno barvených, a přikrytí z koží jezevčích i oponu zastření,'),
(1548890,54,2,39,35,'Truhlu svědectví s sochory jejími i slitovnici,'),
(1548891,54,2,39,36,'Stůl, všecka nádobí jeho i chléb předložení,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548892,54,2,39,37,'Svícen čistý, lampy jeho, lampy zpořádané, i všecka nádobí jeho, i olej k svícení,'),
(1548893,54,2,39,38,'Též oltář zlatý a olej pomazání a kadidlo z vonných věcí a zastření ke dveřům stánku,'),
(1548894,54,2,39,39,'Oltář měděný a rošt jeho měděný, sochory jeho a všecka nádobí jeho, i umyvadlo a podstavek jeho,'),
(1548895,54,2,39,40,'Očkovaté koltry síně a sloupy k nim s podstavky jejich, i zastření k bráně té síně, provazy také její a kolíky i všecka nádobí k službě příbytku, k stánku úmluvy,'),
(1548896,54,2,39,41,'Roucha k službě, k přisluhování v svatyni, roucho svaté Arona kněze i roucho synů jeho k konání úřadu kněžského.'),
(1548897,54,2,39,42,'Vedlé všeho, což přikázal Hospodin Mojžíšovi, tak udělali synové Izraelští všecko to dílo.'),
(1548898,54,2,39,43,'A viděl Mojžíš všecko to dílo, a aj, udělali je, jakž byl přikázal Hospodin, tak udělali. I požehnal jim Mojžíš.'),
(1548899,54,2,40,1,'Potom mluvil Hospodin k Mojžíšovi, řka:'),
(1548900,54,2,40,2,'V den měsíce prvního, prvního dne téhož měsíce vyzdvihneš příbytek, stánek úmluvy.'),
(1548901,54,2,40,3,'A postavíš tam truhlu svědectví a zastřeš ji oponou.'),
(1548902,54,2,40,4,'Vneseš i stůl a zřídíš řád jeho, vneseš také svícen a rozsvítíš lampy jeho.'),
(1548903,54,2,40,5,'Postavíš též oltář zlatý pro kadění naproti truhle svědectví, a zavěsíš zastření ve dveřích příbytku.'),
(1548904,54,2,40,6,'Potom postavíš oltář k zápalům přede dveřmi příbytku stánku úmluvy.'),
(1548905,54,2,40,7,'Postavíš také umyvadlo mezi stánkem úmluvy a mezi oltářem, do něhož naleješ vody.'),
(1548906,54,2,40,8,'Naposledy vyzdvihneš síň vůkol a zavěsíš zastření brány síně.'),
(1548907,54,2,40,9,'Tedy vezmeš olej pomazání a pomažeš příbytku a všech věcí, kteréž v něm jsou, a posvětíš ho i všech nádob jeho, a bude svatý.'),
(1548908,54,2,40,10,'Pomažeš i oltáře zápalu a všech nádob jeho a posvětíš oltáře, a budeť oltář svatý.'),
(1548909,54,2,40,11,'Pomažeš také umyvadla a podstavku jeho, a posvětíš ho.'),
(1548910,54,2,40,12,'A přistoupiti kážeš Aronovi i synům jeho ke dveřím stánku svědectví, a umyješ je vodou.'),
(1548911,54,2,40,13,'A oblečeš Arona v roucha svatá a pomažeš ho a posvětíš ho, aby úřad kněžský konal přede mnou.'),
(1548912,54,2,40,14,'Synům také jeho přistoupiti kážeš, a zobláčíš je v sukně.'),
(1548913,54,2,40,15,'A pomažeš jich, tak jako jsi pomazal otce jejich, aby úřad kněžský konali přede mnou, aby jim bylo pomazání jejich toto k kněžství věčnému po rodech jejich.'),
(1548914,54,2,40,16,'I učinil Mojžíš tak. Všecko, jakž mu rozkázal Hospodin, tak učinil.'),
(1548915,54,2,40,17,'I stalo se měsíce prvního léta druhého, prvního dne měsíce, že vyzdvižen jest příbytek.'),
(1548916,54,2,40,18,'Mojžíš tedy vyzdvihl příbytek a podložil podstavky jeho a postavil dsky jeho, a provlékl svlaky jeho, a vyzdvihl sloupy jeho.'),
(1548917,54,2,40,19,'Potom postavil stánek v příbytku a dal přikrytí stánku svrchu na něj, jakož mu byl přikázal Hospodin.'),
(1548918,54,2,40,20,'A vzav svědectví, vložil je do truhly, uvlékl také sochory k truhle a dal slitovnici svrchu na truhlu.'),
(1548919,54,2,40,21,'I vnesl truhlu do příbytku a zavěsil oponu zastření, a zastřel truhlu svědectví, jakož byl přikázal Hospodin Mojžíšovi.'),
(1548920,54,2,40,22,'Postavil i stůl v stánku úmluvy k straně příbytku půlnoční, vně před oponou.'),
(1548921,54,2,40,23,'A zřídil na něm zpořádaní chlebů před Hospodinem, jakž přikázal Hospodin Mojžíšovi.'),
(1548922,54,2,40,24,'A postavil svícen v stánku úmluvy naproti stolu, v straně příbytku ku poledni.'),
(1548923,54,2,40,25,'A rozsvítil lampy před Hospodinem, jakož přikázal Hospodin Mojžíšovi.'),
(1548924,54,2,40,26,'Postavil také oltář zlatý v stánku úmluvy před oponou,'),
(1548925,54,2,40,27,'A kadil na něm kadidlem vonným, jakž přikázal Hospodin Mojžíšovi.'),
(1548926,54,2,40,28,'Zavěsil také zastření dveří příbytku.'),
(1548927,54,2,40,29,'A oltář zápalu postavil ke dveřům příbytku stánku úmluvy, a obětoval na něm oběti zápalné a suché, jakož přikázal Hospodin Mojžíšovi.'),
(1548928,54,2,40,30,'A postavil umyvadlo mezi stánkem úmluvy a mezi oltářem, do něhož nalil vody k umývání.'),
(1548929,54,2,40,31,'A umýval z něho Mojžíš, Aron a synové jeho ruce své i nohy své.'),
(1548930,54,2,40,32,'Když vcházeli do stánku úmluvy, a když přistupovali k oltáři, umývali se, jakož přikázal Hospodin Mojžíšovi.'),
(1548931,54,2,40,33,'Naposledy vyzdvihl síň vůkol příbytku a oltáře, a zavěsil zastření brány síně. A tak dokonal Mojžíš dílo to.'),
(1548932,54,2,40,34,'Tedy přikryl oblak stánek úmluvy, a sláva Hospodinova naplnila příbytek.'),
(1548933,54,2,40,35,'A nemohl Mojžíš vjíti do stánku úmluvy; nebo byl nad ním oblak, a sláva Hospodinova naplnila příbytek.'),
(1548934,54,2,40,36,'Když pak odnášel se oblak s příbytku, brali se synové Izraelští po všech taženích svých.'),
(1548935,54,2,40,37,'Pakli se neodnášel oblak, nehýbali se až do dne, v němž se zdvihl.'),
(1548936,54,2,40,38,'A byl oblak Hospodinův nad příbytkem ve dne, a oheň býval v noci na něm, před očima všeho domu Izraelského ve všech taženích jejich.'),
(1548937,54,3,1,1,'Povolal pak Hospodin Mojžíše, a mluvil k němu z stánku úmluvy, řka:'),
(1548938,54,3,1,2,'Mluv k synům Izraelským a rci jim: Když by kdo z vás obětoval obět Hospodinu, z hovad, totiž z volů aneb z drobného dobytka obětovati budete obět svou.'),
(1548939,54,3,1,3,'Jestliže zápalná obět jeho byla by z skotů, samce bez vady obětovati bude. U dveří stánku úmluvy obětovati jej bude dobrovolně, před oblíčejem Hospodinovým.'),
(1548940,54,3,1,4,'A vloží ruku svou na hlavu oběti zápalné, i bude příjemná jemu k očištění jeho.'),
(1548941,54,3,1,5,'Tedy zabije volka toho před tváří Hospodinovou, a obětovati budou kněží, synové Aronovi, krev, a pokropí tou krví oltáře svrchu vůkol, kterýž jest u dveří stánku úmluvy.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548942,54,3,1,6,'I stáhne kůži s oběti zápalné, a rozseká ji na díly své.'),
(1548943,54,3,1,7,'A dají synové Arona kněze oheň na oltář, a narovnají dříví na tom ohni.'),
(1548944,54,3,1,8,'Potom zpořádají kněží, synové Aronovi, díly ty, hlavu i tuk, na dříví vložené na oheň, kterýž jest na oltáři.'),
(1548945,54,3,1,9,'A droby jeho i nohy jeho vymyjete vodou. I páliti bude kněz všecko to na oltáři; zápal jest v obět ohnivou, vůně spokojující Hospodina.'),
(1548946,54,3,1,10,'Jestliže pak z drobného dobytka bude obět jeho, z ovcí aneb z koz k oběti zápalné, samce bez poškvrny obětovati bude.'),
(1548947,54,3,1,11,'A zabije ho při straně oltáře půlnoční před tváří Hospodinovou, a pokropí kněží, synové Aronovi, krví oltáře vůkol.'),
(1548948,54,3,1,12,'I rozseká ho na díly jeho s hlavou jeho i tukem jeho, a zpořádá je kněz na dříví vložené na oheň, kterýž jest na oltáři.'),
(1548949,54,3,1,13,'A střeva jeho i nohy jeho vymyje vodou. Tedy obětovati bude kněz všecko to, a páliti bude to na oltáři; zápal jest v obět ohnivou, vůně spokojující Hospodina.'),
(1548950,54,3,1,14,'Jestliže pak z ptactva obět zápalnou obětovati bude Hospodinu, tedy ať obětuje z hrdliček aneb z holoubat obět svou.'),
(1548951,54,3,1,15,'I vloží je kněz na oltář a nehtem natrhne hlavy jeho, a zapálí na oltáři, vytlače krev jeho na stranu oltáře.'),
(1548952,54,3,1,16,'Odejme také vole jeho s nečistotami jeho, a povrže je blízko oltáře k straně východní na místo, kdež jest popel.'),
(1548953,54,3,1,17,'A natrhne ho za křídla jeho, kterýchž však neodtrhne. I páliti bude je kněz na oltáři na dříví, kteréž jest na ohni; zápalť jest v obět ohnivou, vůně spokojující Hospodina.'),
(1548954,54,3,2,1,'Když by pak který člověk obětoval dar oběti suché Hospodinu, mouka bělná bude obět jeho. I poleje ji olejem a vloží na ni kadidlo.'),
(1548955,54,3,2,2,'Přinese ji pak k synům Aronovým kněžím, a vezme odtud plnou hrst svou té mouky bělné a toho oleje se vším kadidlem jejím; i páliti to bude kněz na památku její na oltáři v obět ohnivou, vůně spokojující Hospodina.'),
(1548956,54,3,2,3,'Ostatek pak té oběti suché bude Aronovi i synům jeho, svaté svatých, z ohnivých obětí Hospodinových.'),
(1548957,54,3,2,4,'Když bys pak obětoval dar oběti suché, pečené v peci, ať jsou z mouky bělné koláčové nekvašení, zadělaní olejem, aneb oplatkové přesní olejem pomazaní.'),
(1548958,54,3,2,5,'Jestliže pak obět suchou na pánvici smaženou obětovati budeš, bude z mouky bělné olejem zadělané a nenakvašené.'),
(1548959,54,3,2,6,'Rozlámeš ji na kusy a naleješ na ni oleje, obět suchá jest.'),
(1548960,54,3,2,7,'Pakli obět suchou v kotlíku připravenou obětovati budeš, z mouky bělné s olejem bude.'),
(1548961,54,3,2,8,'I přineseš obět suchou, kteráž z těch věcí bude Hospodinu, a dáš ji knězi, kterýžto donese ji k oltáři.'),
(1548962,54,3,2,9,'A vezma kněz z oběti té pamětné její, páliti je bude na oltáři, v obět ohnivou, vůně spokojující Hospodina.'),
(1548963,54,3,2,10,'Což pak zůstane z oběti té suché, bude Aronovi i synům jeho, svaté svatých, z ohnivých obětí Hospodinových.'),
(1548964,54,3,2,11,'Žádná obět suchá, kterouž obětovati budete Hospodinu, nebude kvašena; nebo nižádného kvasu, ani medu nebudete obětovati v obět ohnivou Hospodinu.'),
(1548965,54,3,2,12,'V oběti prvotin toliko obětovati budete je Hospodinu, ale na tento oltář neobětujte jich u vůni spokojující.'),
(1548966,54,3,2,13,'Také všeliký dar suché oběti své solí osolíš, a neodejmeš soli smlouvy Boha svého od suché oběti své. Při každé oběti své sůl obětovati budeš.'),
(1548967,54,3,2,14,'Jestliže bys pak obětoval obět suchou z prvotin Hospodinu, klasy nové ohněm upražíš, a což vymneš z těch klasů nových, to obětovati budeš, suchou obět prvotin svých.'),
(1548968,54,3,2,15,'A poleješ ji svrchu olejem, kadidlo také vložíš na ni; obět suchá jest.'),
(1548969,54,3,2,16,'I páliti bude kněz pamětné její z obilí zetřeného, a z oleje toho, se vším tím kadidlem jejím; v obět ohnivou bude Hospodinu.'),
(1548970,54,3,3,1,'Jestliže pak obět pokojná bude obět jeho, když by z skotů obětoval, buď vola neb krávu, bez vady bude obětovati je před tváří Hospodinovou.'),
(1548971,54,3,3,2,'Tedy položí ruku svou na hlavu oběti své, i zabije ji u dveří stánku úmluvy; a kropiti budou kněží synové Aronovi krví na oltář vůkol.'),
(1548972,54,3,3,3,'Potom obětovati bude z oběti pokojné ohnivou obět Hospodinu, tuk střeva kryjící, i všeliký tuk, kterýž jest na nich,'),
(1548973,54,3,3,4,'Též obě ledvinky s tukem, kterýž jest na nich i na slabinách, tolikéž i branici, kteráž jest na jatrách; s ledvinkami odejme ji.'),
(1548974,54,3,3,5,'I páliti to budou synové Aronovi na oltáři spolu s obětí zápalnou, kteráž bude na dříví vloženém na oheň; obět zajisté ohnivá jest, vůně spokojující Hospodina.'),
(1548975,54,3,3,6,'Jestliže pak z drobného dobytka bude obět jeho v obět pokojnou Hospodinu, samce aneb samici, bez poškvrny obětovati bude ji.'),
(1548976,54,3,3,7,'Jestliže by obětoval beránka, obět svou, tedy obětovati jej bude před tváří Hospodinovou.'),
(1548977,54,3,3,8,'A vloží ruku svou na hlavu oběti své, a zabije ji před stánkem úmluvy, a kropiti budou synové Aronovi krví její na oltář vůkol.'),
(1548978,54,3,3,9,'Potom obětovati bude z oběti pokojné obět ohnivou Hospodinu, tuk její i ocas celý, kterýž od hřbetu odejme, též i tuk střeva kryjící se vším tím tukem, kterýž jest na nich,'),
(1548979,54,3,3,10,'Též obě dvě ledvinky s tukem, kterýž jest na nich i na slabinách, ano i branici, kteráž jest na jatrách; s ledvinkami odejme ji.'),
(1548980,54,3,3,11,'I páliti to bude kněz na oltáři; pokrm jest oběti ohnivé Hospodinovy.'),
(1548981,54,3,3,12,'Jestliže pak koza byla by obět jeho, tedy bude ji obětovati před oblíčejem Hospodinovým.'),
(1548982,54,3,3,13,'A vloží ruku svou na hlavu její, a zabije ji před stánkem úmluvy; i kropiti budou synové Aronovi krví její na oltáři vůkol.'),
(1548983,54,3,3,14,'Potom obětovati bude z ní obět svou v obět ohnivou Hospodinu, tuk střeva kryjící, i všecken tuk, kterýž jest na nich,'),
(1548984,54,3,3,15,'Též obě dvě ledvinky s tukem, kterýž jest na nich i na slabinách, ano i branici, kteráž jest na jatrách; s ledvinkami odejme ji.'),
(1548985,54,3,3,16,'I páliti to bude kněz na oltáři, pokrm oběti ohnivé u vůni příjemnou. Všecken tuk Hospodinu bude.'),
(1548986,54,3,3,17,'Právem věčným po rodech vašich, ve všech příbytcích vašich žádného tuku a žádné krve nebudete jísti.'),
(1548987,54,3,4,1,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1548988,54,3,4,2,'Mluv synům Izraelským a rci: Když by kdo zhřešil z poblouzení proti některému ze všech přikázaní Hospodinových, čině, čehož býti nemá, a přestoupil by jedno z nich;'),
(1548989,54,3,4,3,'Jestliže by kněz pomazaný zhřešil hříchem jiných lidí: tedy obětovati bude za hřích svůj, kterýmž zhřešil, volka mladého bez poškvrny Hospodinu v obět za hřích.'),
(1548990,54,3,4,4,'I přivede volka toho ke dveřím stánku úmluvy před oblíčej Hospodinův, a položí ruku svou na hlavu volka toho, a zabije ho před oblíčejem Hospodinovým.'),
(1548991,54,3,4,5,'Tedy vezme kněz pomazaný krve z toho volka, a vnese ji do stánku úmluvy.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1548992,54,3,4,6,'Potom omočí kněz prst svůj v té krvi, a kropiti jí bude sedmkráte před Hospodinem, před oponou svatyně.'),
(1548993,54,3,4,7,'Pomaže také kněz tou krví rohů oltáře, na němž se kadí vonnými věcmi před Hospodinem, kterýž jest v stánku úmluvy, a ostatek krve volka toho vyleje k spodku oltáře zápalu, kterýž jest u dveří stánku úmluvy.'),
(1548994,54,3,4,8,'Všecken pak tuk volka toho za hřích vyjme z něho, totiž tuk přikrývající střeva a všecken tuk, kterýž jest na nich,'),
(1548995,54,3,4,9,'Též obě dvě ledvinky s tukem, kterýž jest na nich i na slabinách, tolikéž i branici, kteráž jest na jatrách, s ledvinkami odejme ji,'),
(1548996,54,3,4,10,'Tak jako se odjímá od volka oběti pokojné, a páliti to bude kněz na oltáři zápalu.'),
(1548997,54,3,4,11,'Kůži pak volka toho, i všecko maso jeho s hlavou i s nohami jeho, střeva jeho i s lejny jeho,'),
(1548998,54,3,4,12,'A tak celého volka vynese ven za stany na místo čisté, tam kdež se popel vysýpá, a spálí jej na dříví ohněm; na místě, kdež se popel vysýpá, spálen bude.'),
(1548999,54,3,4,13,'Jestliže by pak všecko množství Izraelské pobloudilo, a byla by ta věc skrytá před očima shromáždění toho, a učinili by proti některému ze všech přikázaní Hospodinových, čehož by býti nemělo, tak že by vinni byli,'),
(1549000,54,3,4,14,'A byl by poznán hřích, kterýmž zhřešili: tedy obětovati bude shromáždění volka mladého v obět za hřích, a přivedou ho před stánek úmluvy.'),
(1549001,54,3,4,15,'I položí starší shromáždění toho ruce své na hlavu volka před Hospodinem, a zabije volka před Hospodinem.'),
(1549002,54,3,4,16,'I vnese kněz pomazaný z krve volka toho do stánku úmluvy,'),
(1549003,54,3,4,17,'A omoče kněz prst svůj v té krvi, kropiti jí bude sedmkráte před Hospodinem, před oponou.'),
(1549004,54,3,4,18,'Pomaže také kněz tou krví rohů oltáře, kterýž jest před Hospodinem v stánku úmluvy; potom všecku krev pozůstávající vyleje k spodku oltáře zápalu, kterýž jest u dveří stánku úmluvy.'),
(1549005,54,3,4,19,'Všecken také tuk jeho vyjme z něho, a páliti bude na oltáři.'),
(1549006,54,3,4,20,'S tím pak volkem tak učiní, jako učinil s volkem za hřích obětovaným, rovně tak učiní s ním. A tak očistí je kněz, i bude jim odpuštěno.'),
(1549007,54,3,4,21,'Volka pak vynese ven z táboru a spálí jej, jako spálil volka prvního; nebo obět za hřích shromáždění jest.'),
(1549008,54,3,4,22,'Jestliže pak kníže zhřeší, a učiní proti některému ze všech přikázaní Hospodina Boha svého, čehož býti nemělo, a to z poblouzení, tak že vinen bude,'),
(1549009,54,3,4,23,'A byl by znám hřích jeho, jímž zhřešil: tedy přivede obět svou z koz, samce bez poškvrny.'),
(1549010,54,3,4,24,'I položí ruku svou na hlavu toho kozla a zabije ho na místě, kdež se bijí oběti zápalné před Hospodinem; obět za hřích jest.'),
(1549011,54,3,4,25,'A vezma kněz z krve oběti za hřích na prst svůj, pomaže rohů oltáře zápalu, ostatek pak krve jeho vyleje k spodku oltáře zápalu.'),
(1549012,54,3,4,26,'Všecken také tuk jeho páliti bude na oltáři, jako i tuk obětí pokojných. A tak očistí jej kněz od hříchu jeho, a odpuštěn bude jemu.'),
(1549013,54,3,4,27,'Jestliže pak zhřeší člověk z lidu obecného z poblouzení, učině proti některému přikázaní Hospodinovu, čehož by nemělo býti, tak že vinen bude,'),
(1549014,54,3,4,28,'A byl by znám hřích jeho, kterýmž zhřešil: tedy přivede obět svou z koz, samici bez poškvrny, za hřích svůj, jímž zhřešil.'),
(1549015,54,3,4,29,'I položí ruku svou na hlavu oběti té za hřích a zabije tu obět za hřích na místě obětí zápalných.'),
(1549016,54,3,4,30,'A vezma kněz z krve její na prst svůj, pomaže rohů oltáře zápalu, a ostatek krve její vyleje u spodku oltáře.'),
(1549017,54,3,4,31,'Všecken také tuk její odejme, jako se odjímá tuk od obětí pokojných, a páliti jej bude kněz na oltáři u vůni příjemnou Hospodinu. A tak očistí jej kněz, a bude mu odpuštěno.'),
(1549018,54,3,4,32,'Pakli by z ovcí přinesl obět svou za hřích, samici bez poškvrny přinese.'),
(1549019,54,3,4,33,'A vloží ruku svou na hlavu té oběti za hřích a zabije ji v obět za hřích na místě, kdež se bijí oběti zápalné.'),
(1549020,54,3,4,34,'Potom vezma kněz krve z oběti té za hřích na prst svůj, pomaže rohů oltáře zápalu, ostatek pak krve její vyleje k spodku oltáře.'),
(1549021,54,3,4,35,'Všecken také tuk její odejme, jakž se odjímá tuk beránka z obětí pokojných, a páliti jej bude kněz na oltáři v obět ohnivou Hospodinu. A tak očistí jej kněz od hříchu jeho, kterýmž zhřešil, a odpuštěn bude jemu.'),
(1549022,54,3,5,1,'Zhřešil-li by člověk, tak že slyše hlas zakletí a jsa svědkem toho, což viděl neb slyšel, a neoznámil by, poneseť pokutu za nepravost svou.'),
(1549023,54,3,5,2,'Aneb jestliže by se dotkl člověk některé věci nečisté, buďto těla zvěři nečisté, buďto těla hovada nečistého, aneb těla žížaly nečisté, a bylo by to skryto před ním, tedy nečistý bude a vinen jest.'),
(1549024,54,3,5,3,'Aneb jestliže by se dotkl nečistoty člověka, jaká by koli byla nečistota jeho, kterouž se poškvrňuje, a bylo by to skryto před ním, a potom poznal by to, vinen jest.'),
(1549025,54,3,5,4,'Aneb jestliže by se kdo zapřisáhl, vynášeje to rty svými, že učiní něco zlého aneb dobrého, a to o jakékoli věci, o níž člověk s přísahou obyčej má mluviti, a bylo by to skryto před ním, a potom by poznal, že vinen jest jednou věcí z těch,'),
(1549026,54,3,5,5,'Když tedy vinen bude jednou věcí z těch: vyzná hřích svůj,'),
(1549027,54,3,5,6,'A přivede obět za vinu svou Hospodinu, za hřích svůj, kterýmž zhřešil, samici z dobytku drobného, ovci aneb kozu za hřích, a očistíť jej kněz od hříchů jeho.'),
(1549028,54,3,5,7,'A pakli by s to býti nemohl, aby dobytče obětoval, tedy přinese obět za vinu svou, kterouž zhřešil, dvě hrdličky aneb dvé holoubátek Hospodinu, jedno v obět za hřích a druhé v obět zápalnou.'),
(1549029,54,3,5,8,'I přinese je k knězi, a on obětovati bude nejprvé to, kteréž má býti v obět za hřích, a nehtem natrhne hlavy jeho naproti tylu jeho, však nerozdělí jí.'),
(1549030,54,3,5,9,'I pokropí krví z oběti za hřích strany oltáře, a což zůstane krve, vytlačí ji k spodku oltáře; nebo obět za hřích jest.'),
(1549031,54,3,5,10,'Z druhého pak učiní obět zápalnou vedlé obyčeje. A tak očistí jej kněz od hříchu jeho, kterýmž zhřešil, a bude mu odpuštěn.'),
(1549032,54,3,5,11,'A pakli nemůže s to býti, aby přinesl dvě hrdličky aneb dvé holoubátek, tedy přinese obět svou ten, kterýž zhřešil, desátý díl míry efi mouky bělné v obět za hřích. Nenalejeť na ni oleje, aniž položí na ni kadidla, nebo obět za hřích jest.'),
(1549033,54,3,5,12,'Kterouž když přinese k knězi, tedy kněz vezma z ní plnou hrst svou, pamětné její, páliti to bude na oltáři mimo obět ohnivou Hospodinu, obět za hřích jest.'),
(1549034,54,3,5,13,'I očistí jej kněz od hříchu jeho, kterýmž zhřešil v kterékoli věci z těch, a budeť mu odpuštěn; ostatek pak bude knězi jako při oběti suché.'),
(1549035,54,3,5,14,'Mluvil opět Hospodin k Mojžíšovi, řka:'),
(1549036,54,3,5,15,'Kdyby člověk přestoupil přestoupením, a zhřešil by z poblouzení, ujímaje věcí posvěcených Hospodinu: tedy přinese obět za vinu svou Hospodinu, skopce bez poškvrny z drobného dobytka, podlé ceny tvé, nejníž za dva loty stříbra, vedlé lotu svatyně, za vinu.'),
(1549037,54,3,5,16,'A tak, což zhřešil, ujímaje posvěcených věcí, nahradí, a pátý díl nad to přidá, dada to knězi; kněz pak očistí jej skrze skopce oběti za vinu, a bude jemu odpuštěna.'),
(1549038,54,3,5,17,'Jestliže by pak člověk zhřešil, a učinil by proti některému ze všech přikázaní Hospodinových, čehož by nemělo býti, neznaje toho, a byl by vinen, rovně též ponese nepravost svou.'),
(1549039,54,3,5,18,'A přivede skopce bez poškvrny z drobného dobytka vedlé ceny tvé v obět za vinu k knězi. I očistí jej kněz od poblouzení jeho, kterýmž pobloudil a o němž nevěděl, a bude mu odpuštěno.'),
(1549040,54,3,5,19,'Obět za provinění jest, nebo zavinil Hospodinu.'),
(1549041,54,3,6,1,'Mluvil opět Hospodin k Mojžíšovi, řka:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549042,54,3,6,2,'Kdyby člověk zhřešil a přestoupením přestoupil proti Hospodinu, buď že by oklamal bližního svého v věci sobě svěřené, aneb v spolku nějakém, aneb mocí by vzal něco, aneb lstivě podvedl bližního svého,'),
(1549043,54,3,6,3,'Buď že nalezna ztracenou věc, za přelby mu ji, buď že by přisáhl falešně, kteroukoli věcí z těch, kterouž přihází se člověku učiniti a zhřešiti jí,'),
(1549044,54,3,6,4,'Když by tedy zhřešil a vinen byl: navrátí zase tu věc, kterouž mocí sobě vzal, aneb tu, kteréž lstivě s útiskem dosáhl, aneb tu, kteráž mu svěřena byla, aneb ztracenou věc, kterouž nalezl,'),
(1549045,54,3,6,5,'Aneb o kterékoli věci falešně přisáhl: tedy navrátí to z cela, a nad to pátý díl toho přidá tomu, číž bylo; to navrátí v den oběti za hřích svůj.'),
(1549046,54,3,6,6,'Obět pak za hřích svůj přivede Hospodinu z drobného dobytku, skopce bez poškvrny, vedlé ceny tvé, v obět za vinu knězi.'),
(1549047,54,3,6,7,'I očistí jej kněz před Hospodinem, a odpuštěno mu bude, jedna každá z těch věcí, kterouž by učinil a jí vinen byl.'),
(1549048,54,3,6,8,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549049,54,3,6,9,'Přikaž Aronovi i synům jeho a rci: Tento bude řád při oběti zápalné: (slove pak obět zápalná od pálení na oltáři celou noc až do jitra, nebo oheň na oltáři vždycky hořeti bude),'),
(1549050,54,3,6,10,'Obleče se kněz v roucho své lněné, a košilku lněnou vezme na tělo své, a vyhrabe popel, když oheň spálí obět zápalnou na oltáři, a vysype jej u oltáře.'),
(1549051,54,3,6,11,'Potom svleče šaty své a obleče se v roucho jiné, a vynese popel ven z stanů na místo čisté.'),
(1549052,54,3,6,12,'Oheň pak, kterýž jest na oltáři, bude hořeti na něm, nebude uhašován. A bude zapalovati jím kněz dříví každého jitra, a zpořádá na něm obět zápalnou, a páliti bude na něm tuk pokojných obětí.'),
(1549053,54,3,6,13,'Oheň ustavičně hořeti bude na oltáři, a nebudeť uhašen.'),
(1549054,54,3,6,14,'Tento pak bude řád při oběti suché, kterouž obětovati budou synové Aronovi Hospodinu u oltáře:'),
(1549055,54,3,6,15,'Vezme hrst bělné mouky z oběti té a z oleje jejího, se vším tím kadidlem, kteréž bude na oběti suché, a páliti to bude na oltáři u vůni líbeznou, pamětné její Hospodinu.'),
(1549056,54,3,6,16,'Což pak zůstane z ní, to jísti budou Aron i synové jeho; přesné jísti se bude na místě svatém, v síni stánku úmluvy jísti to budou.'),
(1549057,54,3,6,17,'Nebude vařeno s kvasem, nebo jsem jim to dal za díl z obětí mých ohnivých; svaté svatých to jest, jako i obět za hřích a jako obět za vinu.'),
(1549058,54,3,6,18,'Každý mužského pohlaví z synů Aronových jísti bude to právem věčným po rodech vašich, z ohnivých obětí Hospodinových. Což by se koli dotklo toho, svaté bude.'),
(1549059,54,3,6,19,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549060,54,3,6,20,'Tato jest obět Aronova a synů jeho, kterouž obětovati budou Hospodinu v den pomazání jeho: Desátý díl míry efi mouky bělné za obět suchou ustavičnou, polovici toho ráno a polovici u večer.'),
(1549061,54,3,6,21,'Na pánvici s olejem strojena bude; smaženou přineseš ji, a pečené kusy oběti suché obětovati budeš u vůni spokojující Hospodina.'),
(1549062,54,3,6,22,'A kněz, kterýž z synů jeho po něm pomazán bude, ať ji obětuje právem věčným. Hospodinu všecko to páleno bude.'),
(1549063,54,3,6,23,'A všeliká suchá obět kněžská celá spálena bude; nebudeť jedena.'),
(1549064,54,3,6,24,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1549065,54,3,6,25,'Mluv Aronovi a synům jeho a rci: Tento bude řád oběti za hřích: Na místě, kdež se zabijí obět zápalná, zabita bude obět za hřích před Hospodinem; svatá svatých jest.'),
(1549066,54,3,6,26,'Kněz obětující tu obět za hřích budeť jísti ji; na místě svatém jedena bude v síni stánku úmluvy.'),
(1549067,54,3,6,27,'Což by se koli dotklo masa jejího, svaté bude; a jestliže by krví její šaty skropeny byly, to, což skropeno jest, obmyješ na místě svatém.'),
(1549068,54,3,6,28,'A nádoba hliněná, v níž by vařeno bylo, rozražena bude; pakli by v nádobě měděné vařeno bylo, vytřena a vymyta bude vodou.'),
(1549069,54,3,6,29,'Všeliký pohlaví mužského mezi kněžími jísti to bude; svaté svatých jest.'),
(1549070,54,3,6,30,'Ale žádná obět za hřích, (z jejížto krve něco vneseno bylo by do stánku úmluvy k očištění v svatyni), nebude jedena; ohněm spálena bude.'),
(1549071,54,3,7,1,'Tento pak bude řád oběti za provinění; svatá svatých jest.'),
(1549072,54,3,7,2,'Na kterémž místě zabijí se obět zápalná, na témž zabijí i obět za vinu, a pokropí krví její oltáře svrchu vůkol.'),
(1549073,54,3,7,3,'Všecken pak tuk její obětovati bude z ní, ocas i tuk střeva přikrývající.'),
(1549074,54,3,7,4,'Též obě dvě ledvinky s tukem, kterýž jest na nich i na slabinách; a branici, kteráž jest na jatrách, s ledvinkami odejme.'),
(1549075,54,3,7,5,'I bude páliti to kněz na oltáři v obět ohnivou Hospodinu; obět za provinění jest.'),
(1549076,54,3,7,6,'Všeliký pohlaví mužského mezi kněžími jísti bude ji, na místě svatém jedena bude; svatá svatých jest.'),
(1549077,54,3,7,7,'Jakož obět za hřích, tak obět za vinu, jednostejné právo míti budou; knězi, kterýž by ho očišťoval, přináležeti bude.'),
(1549078,54,3,7,8,'Knězi pak, kterýž by něčí obět zápalnou obětoval, kůže té oběti zápalné, kterouž obětoval, přináležeti bude.'),
(1549079,54,3,7,9,'Nadto všeliká obět suchá, kteráž v peci pečena bude, a všecko, což na pánvici aneb v kotlíku strojeno bude, knězi, kterýž to obětuje, přináležeti bude.'),
(1549080,54,3,7,10,'Tolikéž všeliká obět suchá olejem zadělaná aneb upražená, všechněm synům Aronovým přináležeti bude, a to jednomu jako druhému.'),
(1549081,54,3,7,11,'Tento pak bude řád oběti pokojné, kterouž by obětoval Hospodinu:'),
(1549082,54,3,7,12,'Jestliže by ji obětoval v oběti chvály, tedy obětovati bude v obět chvály koláče nekvašené, olejem zadělané a oplatky nekvašené, olejem pomazané a mouku bělnou smaženou, s těmi koláči olejem zadělanými.'),
(1549083,54,3,7,13,'Mimo ty koláče také chléb kvašený obětovati bude obět svou, v obět chvály pokojných obětí svých.'),
(1549084,54,3,7,14,'A budeť obětovati z něho jeden pecník, ze vší té oběti Hospodinu obět ku pozdvižení, a ten přináležeti bude tomu knězi, kterýž kropil krví té oběti pokojné.'),
(1549085,54,3,7,15,'Maso pak obět, z té oběti chvály, jenž jest obět pokojná, v den obětování jejího jedeno bude, aniž co zůstane z něho do jitra.'),
(1549086,54,3,7,16,'Jestliže by pak z slibu aneb z dobré vůle obětoval obět svou, tolikéž v den obětování jejího jedena bude; a jestliže by co zůstalo z toho, tedy na druhý den jísti se bude.'),
(1549087,54,3,7,17,'Jestliže by pak co masa z té oběti zůstalo do třetího dne, ohněm spáleno bude.'),
(1549088,54,3,7,18,'Pakli by kdo předce jedl maso oběti pokojné dne třetího, nebudeť příjemný ten, kterýž ji obětoval, aniž přijata bude, ale ohavnost bude, a kdož by koli jedl je, ponese nepravost svou.'),
(1549089,54,3,7,19,'Též maso, kteréž by se dotklo něčeho nečistého, nebude jedeno, ale ohněm spáleno bude; maso pak jiné, kdož by koli čistý byl, bude moci jísti.'),
(1549090,54,3,7,20,'Nebo člověk, kterýž by jedl maso z oběti pokojné, kteráž jest Hospodinu obětována, a byl by poškvrněný: tedy vyhlazen bude člověk ten z lidu svého.'),
(1549091,54,3,7,21,'A kdož by se dotkl něčeho nečistého, buďto nečistoty člověka, buď hovada nečistého aneb všeliké ohavnosti nečisté, a jedl by maso z oběti pokojné, kteráž jest Hospodinu posvěcena: tedy vyhlazen bude člověk ten z lidu svého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549092,54,3,7,22,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1549093,54,3,7,23,'Mluv k synům Izraelským a rci jim: Žádného tuku z vola, aneb z ovce, aneb z kozy nebudete jísti.'),
(1549094,54,3,7,24,'Ačkoli tuk mrtvého a tuk udáveného hovada může užíván býti k všeliké potřebě, ale jísti ho nikoli nebudete.'),
(1549095,54,3,7,25,'Nebo kdož by koli jedl tuk z hovada, kteréž obětovati bude člověk v obět ohnivou Hospodinu, vyhlazen bude člověk ten, kterýž jedl, z lidu svého.'),
(1549096,54,3,7,26,'Tolikéž krve žádné jísti nebudete ve všech příbytcích svých, buď z ptactva, buď z hovada.'),
(1549097,54,3,7,27,'Všeliký člověk, kterýž by jedl jakou krev, vyhlazen bude z lidu svého.'),
(1549098,54,3,7,28,'Mluvil opět Hospodin k Mojžíšovi, řka:'),
(1549099,54,3,7,29,'Mluv k synům Izraelským a rci: Kdož by obětoval obět svou pokojnou Hospodinu, on sám přinese obět svou Hospodinu z obětí pokojných svých.'),
(1549100,54,3,7,30,'Ruce jeho obětovati budou obět ohnivou Hospodinu. Tuk s hrudím přinese, a hrudí aby bylo v obět sem i tam obracení před Hospodinem.'),
(1549101,54,3,7,31,'Páliti pak bude kněz tuk na oltáři, ale hrudí to zůstane Aronovi i synům jeho.'),
(1549102,54,3,7,32,'A plece pravé dáte knězi ku pozdvižení z obětí pokojných vašich.'),
(1549103,54,3,7,33,'Kdožkoli z synů Aronových obětovati bude krev obětí pokojných a tuk, tomu se dostane plece pravé na díl jeho.'),
(1549104,54,3,7,34,'Nebo hrudí sem i tam obracení a plece vzhůru pozdvižení vzal jsem od synů Izraelských z obětí pokojných jejich, a dal jsem je Aronovi knězi i synům jeho právem věčným od synů Izraelských.'),
(1549105,54,3,7,35,'Toť jest díl pomazání Aronova, a pomazání synů jeho z ohnivých obětí Hospodinových, ode dne toho, v kterémž jim přistoupiti rozkázal k vykonávání kněžství Hospodinu,'),
(1549106,54,3,7,36,'Kterýž přikázal Hospodin, aby jim ode dne, v kterémž jich pomazal, dáván byl od synů Izraelských právem věčným po rodech jejich.'),
(1549107,54,3,7,37,'Tenť jest řád oběti zápalné, oběti suché, oběti za hřích, oběti za vinu, a posvěcování i obětí pokojných,'),
(1549108,54,3,7,38,'Kteréž přikázal Hospodin Mojžíšovi na hoře Sinai toho dne, když přikázal synům Izraelským, aby obětovali oběti své Hospodinu na poušti Sinai.'),
(1549109,54,3,8,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549110,54,3,8,2,'Vezmi Arona a syny jeho s ním, i roucha jejich a olej pomazání, též volka k oběti za hřích, a dva skopce, a koš s přesnými chleby,'),
(1549111,54,3,8,3,'A shromažď všecko množství ke dveřím stánku úmluvy.'),
(1549112,54,3,8,4,'I učinil Mojžíš, jakž přikázal jemu Hospodin, a shromáždilo se všecko množství ke dveřím stánku úmluvy.'),
(1549113,54,3,8,5,'Tedy řekl Mojžíš tomu množství: Totoť jest to slovo, kteréž přikázal vykonati Hospodin.'),
(1549114,54,3,8,6,'A rozkázav přistoupiti Mojžíš Aronovi a synům jeho, umyl je vodou.'),
(1549115,54,3,8,7,'A oblékl jej v sukni a přepásal ho pasem, a oděv ho pláštěm, dal náramenník svrchu na něj, a připásal jej pasem náramenníka a otáhl ho jím.'),
(1549116,54,3,8,8,'A vložil na něj náprsník, do něhožto dal urim a thumim.'),
(1549117,54,3,8,9,'Potom vstavil čepici na hlavu jeho; a dal na čepici jeho po předu plech zlatý, korunu svatou, jakož přikázal Hospodin Mojžíšovi.'),
(1549118,54,3,8,10,'Vzal také Mojžíš olej pomazání a pomazal příbytku i všech věcí, kteréž byly v něm, a posvětil jich.'),
(1549119,54,3,8,11,'A pokropil jím oltáře sedmkrát, a pomazal oltáře i všeho nádobí jeho, též umyvadla i s podstavkem jeho, aby to všecko posvěceno bylo.'),
(1549120,54,3,8,12,'Vlil také oleje pomazání na hlavu Aronovu, a pomazal ho ku posvěcení jeho.'),
(1549121,54,3,8,13,'Rozkázal také Mojžíš přistoupiti synům Aronovým, a zobláčel je v sukně, a opásal je pasem, a vstavil na ně klobouky, jakož byl přikázal Hospodin jemu.'),
(1549122,54,3,8,14,'A přivedl volka k oběti za hřích, i položil Aron a synové jeho ruce své na hlavu volka oběti za hřích.'),
(1549123,54,3,8,15,'I zabil jej a vzal krev jeho, a pomazal rohů oltáře vůkol prstem svým, a tak očistil oltář. Ostatek pak krve vylil k spodku oltáře a posvětil ho k očišťování na něm.'),
(1549124,54,3,8,16,'Vzal také všecken tuk, kterýž byl na střevách, a branici s jater a obě ledvinky i tuk jejich, a pálil to Mojžíš na oltáři.'),
(1549125,54,3,8,17,'Volka pak toho i kůži jeho, i maso jeho, i lejna jeho spálil ohněm vně za stany, jakož byl přikázal Hospodin Mojžíšovi.'),
(1549126,54,3,8,18,'Potom přivedl skopce oběti zápalné, a položil Aron i synové jeho ruce své na hlavu toho skopce.'),
(1549127,54,3,8,19,'I zabil jej, a pokropil Mojžíš krví oltáře po vrchu vůkol.'),
(1549128,54,3,8,20,'Skopce také rozsekal na kusy jeho, a pálil Mojžíš hlavu, kusy i tuk.'),
(1549129,54,3,8,21,'Střeva pak a nohy vymyl vodou, a tak spálil Mojžíš všeho skopce na oltáři. I byl zápal u vůni líbeznou, obět ohnivá Hospodinu, jakož přikázal Hospodin Mojžíšovi.'),
(1549130,54,3,8,22,'Rozkázal také přivésti skopce druhého, skopce posvěcení, a položil Aron i synové jeho ruce své na hlavu skopce.'),
(1549131,54,3,8,23,'I zabil jej, a vzav Mojžíš krve jeho, pomazal jí konce pravého ucha Aronova a palce ruky jeho pravé, i palce nohy jeho pravé.'),
(1549132,54,3,8,24,'Tolikéž synům Aronovým rozkázav přistoupiti, pomazal kraje ucha jejich pravého a palce ruky jejich pravé, též palce nohy jejich pravé, a vykropil krev na oltář svrchu vůkol.'),
(1549133,54,3,8,25,'Potom vzal tuk a ocas i všecken tuk přikrývající droby a branici s jater, též obě dvě ledvinky i tuk jejich i plece pravé.'),
(1549134,54,3,8,26,'Také z koše přesných chlebů, kteříž byli před Hospodinem, vzal jeden koláč přesný a jeden pecník chleba s olejem a jeden oplatek, a položil to s tukem a s plecem pravým.'),
(1549135,54,3,8,27,'A dal to všecko v ruce Aronovy a v ruce synů jeho, rozkázav obraceti sem i tam v obět obracení před Hospodinem.'),
(1549136,54,3,8,28,'Potom vzav z rukou jejich, pálil to na oltáři v zápal. Posvěcení toto jest u vůni rozkošnou, obět ohnivá Hospodinu.'),
(1549137,54,3,8,29,'Vzal také Mojžíš hrudí a obracel je sem i tam v obět obracení před Hospodinem;a z skopce posvěcení dostal se Mojžíšovi díl, jakož mu byl přikázal Hospodin.'),
(1549138,54,3,8,30,'Vzal také Mojžíš oleje pomazání a krve, kteráž byla na oltáři, a pokropil Arona i roucha jeho, též synů Aronových a roucha jejich s ním. A tak posvětil Arona i roucha jeho, též synů jeho i roucha jejich s ním.'),
(1549139,54,3,8,31,'I řekl Mojžíš Aronovi a synům jeho: Vařte to maso u dveří stánku úmluvy, a jezte je tu, i chléb, kterýž jest v koši posvěcení, jakož jsem přikázal, řka: Aron a synové jeho jísti budou je.'),
(1549140,54,3,8,32,'Což by pak zůstalo masa i chleba toho, ohněm to spálíte.'),
(1549141,54,3,8,33,'A ze dveří stánku úmluvy za sedm dní nevycházejte až do dne, v kterémž by se vyplnili dnové svěcení vašeho; nebo za sedm dní posvěcovány budou ruce vaše.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549142,54,3,8,34,'Jakož se stalo dnešní den, tak přikázal Hospodin činiti k očištění vašemu.'),
(1549143,54,3,8,35,'Protož u dveří stánku úmluvy zůstanete ve dne i v noci za sedm dní, a ostříhati budete nařízení Hospodinova, abyste nezemřeli; nebo tak mi jest přikázáno.'),
(1549144,54,3,8,36,'Učinil tedy Aron i synové jeho všecky věci, kteréž přikázal Hospodin skrze Mojžíše.'),
(1549145,54,3,9,1,'Stalo se pak dne osmého, povolal Mojžíš Arona a synů jeho i starších Izraelských.'),
(1549146,54,3,9,2,'I řekl Aronovi: Vezmi sobě tele k oběti za hřích, a skopce k oběti zápalné, obé bez poškvrny, a obětuj před Hospodinem.'),
(1549147,54,3,9,3,'K synům pak Izraelským mluviti budeš, řka: Vezměte kozla k oběti za hřích, a tele a beránka, roční, bez vady, k oběti zápalné,'),
(1549148,54,3,9,4,'Vola také a skopce k oběti pokojné, abyste obětovali před Hospodinem, a obět suchou zadělanou olejem; nebo dnes se vám ukáže Hospodin.'),
(1549149,54,3,9,5,'Tedy vzali ty věci, kteréž přikázal Mojžíš před stánkem úmluvy, a přistoupivši všecko shromáždění, stáli před Hospodinem.'),
(1549150,54,3,9,6,'I řekl Mojžíš: Toto jest ta věc, kterouž přikázal Hospodin. Vykonejtež ji, a ukáže se vám sláva Hospodinova.'),
(1549151,54,3,9,7,'Aronovi pak řekl Mojžíš: Přistup k oltáři a obětuj obět za hřích svůj, a obět zápalnou svou k vykonání očištění za sebe i za lid tento; obětuj také obět lidu všeho, a učiň očištění za ně, jakož přikázal Hospodin.'),
(1549152,54,3,9,8,'Přistoupiv tedy Aron k oltáři, zabil tele své k oběti za hřích.'),
(1549153,54,3,9,9,'I dali mu synové Aronovi krev. Kterýžto omočiv prst svůj ve krvi, pomazal rohů oltáře, ostatek pak krve vylil k spodku oltáře.'),
(1549154,54,3,9,10,'Ale tuk a ledvinky, i branici s jater té oběti za hřích pálil na oltáři, jakož byl přikázal Hospodin Mojžíšovi.'),
(1549155,54,3,9,11,'Maso pak s kůží spálil vně za stany.'),
(1549156,54,3,9,12,'Zabil také obět zápalnou. I podali mu synové Aronovi krve, kterouž pokropil po vrchu oltáře vůkol.'),
(1549157,54,3,9,13,'Podali jemu také i oběti zápalné s kusy jejími i hlavy její, a pálil ji na oltáři.'),
(1549158,54,3,9,14,'A vymyv střeva i nohy její, pálil je s obětí zápalnou na oltáři.'),
(1549159,54,3,9,15,'Obětoval také obět všeho lidu. A vzav kozla oběti za hřích, kterýž byl všeho lidu, zabil jej a obětoval ho za hřích jako i prvního.'),
(1549160,54,3,9,16,'Obětoval též obět zápalnou a učinil ji vedlé obyčeje.'),
(1549161,54,3,9,17,'Tolikéž i obět suchou obětoval, a vzav plnou hrst z ní, pálil to na oltáři, mimo obět zápalnou jitřní.'),
(1549162,54,3,9,18,'Zabil ještě i vola a skopce k oběti pokojné, kteráž byla za lid. I podali mu synové Aronovi krve, kterouž pokropil oltáře po vrchu vůkol.'),
(1549163,54,3,9,19,'Dali jemu také tuk z vola a z skopce ocas, a tuk přikrývající střeva i ledvinky a branici s jater.'),
(1549164,54,3,9,20,'A položili včecken tuk na hrudí; i pálil ten tuk na oltáři.'),
(1549165,54,3,9,21,'Hrudí pak a plece pravé obracel sem i tam Aron v obět obracení před Hospodinem, jakož byl přikázal Mojžíšovi.'),
(1549166,54,3,9,22,'Potom Aron pozdvihna rukou svých k lidu, dal jim požehnání, a sstoupil od obětování oběti za hřích a oběti zápalné i oběti pokojné.'),
(1549167,54,3,9,23,'Tedy všel Mojžíš s Aronem do stánku úmluvy; a když vycházeli z něho, požehnání dávali lidu. I ukázala se sláva Hospodinova všemu lidu.'),
(1549168,54,3,9,24,'Nebo sstoupil oheň od tváři Hospodina, a spálil na oltáři obět zápalnou i všecken tuk. Což když uzřel veškeren lid, zkřikli a padli na tváři své.'),
(1549169,54,3,10,1,'Synové pak Aronovi Nádab a Abiu, vzavše jeden každý kadidlnici svou, dali do nich oheň a položili na něj kadidlo, a obětovali před Hospodinem oheň cizí, čehož jim byl nepřikázal.'),
(1549170,54,3,10,2,'Protož sstoupiv oheň od Hospodina, spálil je; a zemřeli tu před Hospodinem.'),
(1549171,54,3,10,3,'I řekl Mojžíš Aronovi: Toť jest, což mluvil Hospodin, řka: V těch, kteříž přistupují ke mně, posvěcen budu, a před oblíčejem všeho lidu oslaven budu. I mlčel Aron.'),
(1549172,54,3,10,4,'Tedy povolal Mojžíš Mizaele a Elizafana, synů Uziele, strýce Aronova, a řekl jim: Poďte a vyneste bratří své od svatyně ven za stany.'),
(1549173,54,3,10,5,'I přišli a vynesli je v sukních jejich ven za stany, jakž byl rozkázal Mojžíš.'),
(1549174,54,3,10,6,'Mluvil pak Mojžíš Aronovi, Eleazarovi a Itamarovi, synům jeho: Hlav svých neodkrývejte a roucha svého neroztrhujte, abyste nezemřeli, a aby se Bůh na všecko množství nerozhněval; ale bratří vaši, všecka rodina Izraelská, budou plakati nad tím spálením, kteréž uvedl Hospodin.'),
(1549175,54,3,10,7,'Vy pak ze dveří stánku úmluvy nevycházejte, abyste nezemřeli; nebo olej pomazání Hospodinova jest na vás. I učinili vedlé rozkázaní Mojžíšova.'),
(1549176,54,3,10,8,'Mluvil také Hospodin Aronovi, řka:'),
(1549177,54,3,10,9,'Vína a nápoje opojného nebudeš píti,ty ani synové tvoji s tebou, kdyžkoli budete míti vcházeti do stánku úmluvy, abyste nezemřeli, (ustanovení věčné to bude po rodech vašich);'),
(1549178,54,3,10,10,'Také abyste rozeznati mohli mezi svatým a neposvěceným, a mezi čistým a nečistým;'),
(1549179,54,3,10,11,'Též abyste učili syny Izraelské všechněm ustanovením, kteráž mluvil Hospodin k nim skrze Mojžíše.'),
(1549180,54,3,10,12,'Mluvil pak Mojžíš Aronovi, Eleazarovi a Itamarovi, synům jeho, kteříž živi zůstali: Vezměte obět suchou, kteráž zůstala z ohnivých obětí Hospodinových, a jezte ji s přesnicemi u oltáře; nebo svatá svatých jest.'),
(1549181,54,3,10,13,'Protož jísti budete ji na místě svatém, nebo to jest právo tvé a právo synů tvých z ohnivých obětí Hospodinových; tak zajisté jest mi přikázáno.'),
(1549182,54,3,10,14,'Hrudí pak sem i tam obracení, a plece vznášení jísti budete na místě čistém, ty i synové tvoji, i dcery tvé s tebou; nebo to právem tobě a synům tvým dáno jest z pokojných obětí synů Izraelských.'),
(1549183,54,3,10,15,'Plece vzhůru vznášení a hrudí sem i tam obracení s obětmi ohnivými tuků, kteréž přinesou, aby sem i tam obracíno bylo, tak jako obět obracení před Hospodinem, bude tobě i synům tvým s tebou právem věčným, jakož přikázal Hospodin.'),
(1549184,54,3,10,16,'Mojžíš pak hledal pilně kozla k oběti za hřích, a hle, již spálen byl. Tedy rozhněval se na Eleazara a Itamara, syny Aronovy pozůstalé, a řekl:'),
(1549185,54,3,10,17,'Pročež jste nejedli oběti za hřích na místě svatém? Nebo svatá svatých byla, poněvadž ji dal vám, abyste nesli nepravost všeho množství k očištění jejich před Hospodinem.'),
(1549186,54,3,10,18,'A hle, ani krev její není vnesena do vnitřku svatyně. Jísti jste měli ji v svatyni, jakož jsem byl přikázal.'),
(1549187,54,3,10,19,'Tedy odpověděl Aron Mojžíšovi: Aj, dnes obětovali obět svou za hřích a obět svou zápalnou před Hospodinem, ale přihodila se mně taková věc, že, kdybych byl jedl obět za hřích dnes, zdali by se to líbilo Hospodinu?'),
(1549188,54,3,10,20,'Což když uslyšel Mojžíš, přestal na tom.'),
(1549189,54,3,11,1,'I mluvil Hospodin Mojžíšovi a Aronovi, řka jim:'),
(1549190,54,3,11,2,'Mluvte k synům Izraelským, řkouce: Tito jsou živočichové, kteréž jísti budete ze všech hovad, kteráž jsou na zemi:'),
(1549191,54,3,11,3,'Všeliké hovado, kteréž má kopyta rozdělená, tak aby rozdvojená byla, a přežívá, jísti budete.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549192,54,3,11,4,'A však z těch, kteráž přežívají, a z těch, kteráž kopyta rozdělená mají, nebudete jísti, jako velblouda; nebo ač přežívá, ale kopyta rozděleného nemá, nečistý vám bude.'),
(1549193,54,3,11,5,'Ani králíka, kterýž ač přežívá, ale kopyta rozděleného nemá, nečistý vám bude.'),
(1549194,54,3,11,6,'Ani zajíce; nebo ač přežívá, ale kopyta rozděleného nemá, nečistý vám bude.'),
(1549195,54,3,11,7,'Tolikéž ani svině; nebo ač má rozdělené kopyto, tak že se rozdvojuje, ale nepřežívá, nečistá bude vám.'),
(1549196,54,3,11,8,'Masa jejich nebudete jísti, ani těla jejich mrtvého se dotýkati, nečistá budou vám.'),
(1549197,54,3,11,9,'Ze všech pak živočichů, kteříž u vodách jsou, tyto jísti budete: Všecko, což má plejtvy a šupiny u vodách mořských i v řekách, jísti budete.'),
(1549198,54,3,11,10,'Všecko pak, což nemá plejtví a šupin v moři i v řekách, buď jakýkoli hmyz vodný, aneb jakákoli duše živá u vodách, ohavností bude vám.'),
(1549199,54,3,11,11,'A tak v ohavnosti vám budou, abyste masa jejich nejedli a těla jejich v ohyzdnosti měli.'),
(1549200,54,3,11,12,'Což tedy nemá plejtví a šupin u vodách, to v ohavnosti míti budete.'),
(1549201,54,3,11,13,'Z ptactva pak tyto v ohavnosti míti budete, jichžto nebudete jísti, nebo ohavnost jsou, jako jest orel, noh a orlice mořská,'),
(1549202,54,3,11,14,'Též sup, káně a luňák vedlé pokolení svého,'),
(1549203,54,3,11,15,'A všeliký krkavec vedlé pokolení svého,'),
(1549204,54,3,11,16,'Také pstros, sova, vodní káně, a jestřáb vedlé pokolení svého,'),
(1549205,54,3,11,17,'A bukač, křehař a kalous,'),
(1549206,54,3,11,18,'A porfirián, pelikán a labut,'),
(1549207,54,3,11,19,'Též čáp a kalandra vedlé pokolení svého, dedek a netopýř.'),
(1549208,54,3,11,20,'Všeliký zeměplaz křídla mající, kterýž na čtyřech nohách chodí, v ohavnosti míti budete.'),
(1549209,54,3,11,21,'A však ze všelikého zeměplazu křídla majícího, kterýž na čtyřech nohách chodí, jísti budete ty, kteříž mají stehénka na nohách svých, aby skákali na nich po zemi.'),
(1549210,54,3,11,22,'Titoť pak jsou, kteréž jísti budete: Arbes vedlé pokolení svého, sálem vedlé pokolení svého, chargol vedlé pokolení svého, a chagab vedlé pokolení svého.'),
(1549211,54,3,11,23,'Jiný pak zeměplaz všeliký křídla mající, kterýž na čtyřech nohách chodí, v ohavnosti míti budete.'),
(1549212,54,3,11,24,'Nebo těmi byste se poškvrňovali. Protož kdož by se koli dotkl těla jich, nečistý bude až do večera.'),
(1549213,54,3,11,25,'A kdož by koli nesl těla jich, zpéřeť roucho své a nečistý bude až do večera.'),
(1549214,54,3,11,26,'Všeliké hovado, kteréž má rozdělené kopyto, ale není rozdvojené, a nepřežívá, nečisté vám bude. Kdož by koli jeho se dotekl, nečistý bude.'),
(1549215,54,3,11,27,'A cožkoli chodí na tlapách svých ze všech hovad čtvernohých, nečisté bude vám. Kdož by koli dotkl se těl jejich, nečistý bude až do večera.'),
(1549216,54,3,11,28,'A kdož by koli nesl těla jejich, zpéře roucha svá a nečistý bude až do večera; nebo nečistá jsou vám.'),
(1549217,54,3,11,29,'Také i toto vám nečisté bude mezi zeměplazy, kteříž lezou po zemi: Kolčava a myš a žába, každé vedlé pokolení svého;'),
(1549218,54,3,11,30,'Též ježek a ještěrka, hlemejžď, štír a krtice.'),
(1549219,54,3,11,31,'Tyto věci nečisté vám budou ze všelijakého zeměplazu. Kdož by se koli dotkl jich mrtvých, nečistý bude až do večera.'),
(1549220,54,3,11,32,'A všeliká věc, na kterouž by padlo něco z těch již mrtvých těl, nečistá bude, buď nádoba dřevěná, neb roucho, neb kůže, aneb pytel. A všeliká nádoba, kteréž se k dílu nějakému užívá, do vody vložena bude a nečistá zůstane až do večera, potom čistá bude.'),
(1549221,54,3,11,33,'Všeliká pak nádoba hliněná, do níž by něco toho upadlo, i což by koli v ní bylo, nečisté bude, ona pak rozražena bude.'),
(1549222,54,3,11,34,'Všeliký také pokrm, jehož se užívá, jestliže by na něj voda vylita byla, nečistý bude; a všeliký nápoj ku pití příhodný v každé nádobě nečisté bude nečistý.'),
(1549223,54,3,11,35,'A všecko, na čež by něco z těla jejich upadlo, nečisté bude. Pec a kotliště zbořeno bude, nebo nečisté jest; protož za nečisté je míti budete.'),
(1549224,54,3,11,36,'Ale studnice a čisterna, i všeliké shromáždění vod, čistá budou; však což by se dotklo umrliny jejich, nečisté bude.'),
(1549225,54,3,11,37,'Jestliže by pak něco z mrchy jejich upadlo na některé semeno, kteréž síti obyčej jest, čisté bude.'),
(1549226,54,3,11,38,'Ale když by polito bylo vodou semeno, a potom padlo by něco z umrliny jejich na ně, nečisté bude vám.'),
(1549227,54,3,11,39,'Jestliže by umřelo hovado z těch, kteráž vám jsou ku pokrmu, kdož by se koli mrchy jeho dotkl, nečistý bude až do večera.'),
(1549228,54,3,11,40,'Kdo by jedl z těla toho, zpéřeť roucha svá a nečistý bude až do večera. Také i ten, kterýž by vynesl tu mrchu, zpéře roucha svá, a nečistý bude až do večera.'),
(1549229,54,3,11,41,'Tolikéž všeliký zeměplaz, kterýž se plazí po zemi, v ohavnosti bude vám; nebudete ho jísti.'),
(1549230,54,3,11,42,'Ničeho, což se plazí na prsech, aneb cožkoli čtvermo leze, aneb více má noh, ze všeho zeměplazu, kterýž se plazí po zemi, nebudete jísti nebo jsou ohavnost.'),
(1549231,54,3,11,43,'Nezohavujtež duší svých žádným zeměplazem, kterýž se plazí, a nepoškvrňujte se jimi, abyste nečistí nebyli učiněni skrze ně.'),
(1549232,54,3,11,44,'Nebo já jsem Hospodin Bůh váš; protož posvěťtež se, a svatí buďte, nebo já svatý jsem, a nepošvrňujte duší svých žádným zeměplazem, kterýž se plazí po zemi.'),
(1549233,54,3,11,45,'Nebo já jsem Hospodin, kterýž jsem vás vyvedl z země Egyptské, abych vám byl za Boha; protož svatí buďte, nebo já jsem svatý.'),
(1549234,54,3,11,46,'Toť jest právo strany hovada, ptactva a všeliké duše živé, kteráž se hýbe u vodách, a každé duše živé, kteráž se plazí na zemi,'),
(1549235,54,3,11,47,'Aby rozdíl činěn byl mezi nečistým a čistým, a mezi živočichy, kteříž se mají jísti, a mezi živočichy, kteříž se nemají jísti.'),
(1549236,54,3,12,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549237,54,3,12,2,'Mluv synům Izraelským a rci: Žena počnuc, porodí-li pacholíka, nečistá bude za sedm dní; podlé počtu dnů, v nichž odděluje se pro nemoc svou, nečistá bude.'),
(1549238,54,3,12,3,'Potom dne osmého obřezáno bude tělo neobřízky jeho.'),
(1549239,54,3,12,4,'Ona pak ještě za třidceti a tři dni zůstávati bude v očišťování se od krve. Nižádné věci svaté se nedotkne a k svatyni nepůjde, dokudž se nevyplní dnové očištění jejího.'),
(1549240,54,3,12,5,'Pakli děvečku porodí, nečistá bude za dvě neděle vedlé nečistoty oddělení svého, a šedesáte šest dní zůstávati bude v očištění od krve.'),
(1549241,54,3,12,6,'Když pak vyplní se dnové očištění jejího po synu aneb po dceři, přinese beránka ročního na obět zápalnou, a holoubátko aneb hrdličku na obět za hřích, ke dveřím stánku úmluvy, knězi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549242,54,3,12,7,'Kterýž obětovati ji bude před Hospodinem, a očistí ji, a tak očištěna bude od toku krve své. Ten jest zákon té, kteráž porodila pacholíka aneb děvečku.'),
(1549243,54,3,12,8,'Pakli nebude moci býti s beránka, tedy vezme dvé hrdličátek, aneb dvé holoubátek, jedno v obět zápalnou a druhé v obět za hřích. I očistí ji kněz, a tak čistá bude.'),
(1549244,54,3,13,1,'Mluvil také Hospodin Mojžíšovi a Aronovi, řka:'),
(1549245,54,3,13,2,'Člověk ješto by na kůži těla jeho byla nějaká oteklina aneb prašivina, aneb poškvrna pobělavá, a bylo by na kůži těla jeho něco podobného k ráně malomocenství: tedy přiveden bude k Aronovi knězi, aneb k některému z synů jeho kněží.'),
(1549246,54,3,13,3,'I pohledí kněz na ránu, kteráž jest na kůži těla jeho. Jestliže chlupové na té ráně zbělejí, a ta rána bude-li na pohledění hlubší nežli jiná kůže těla jeho, rána malomocenství jest. Když tedy spatří ji kněz, za nečistého vyhlásí jej.'),
(1549247,54,3,13,4,'Pakli by poškvrna pobělavá byla na kůži těla jeho, a rána ta nebyla by hlubší nežli jiná kůže, a chlupové její nezběleli by: tedy rozkáže zavříti kněz majícího takovou ránu za sedm dní.'),
(1549248,54,3,13,5,'Potom pohledí na něj kněz v den sedmý, a jestli rána ta zůstává tak před očima jeho a nerozmáhá se po kůži: tedy rozkáže ho zavříti kněz po druhé za sedm dní.'),
(1549249,54,3,13,6,'I pohledí na ni kněz v den sedmý po druhé, a jestliže ta rána pozčernalá bude, a nerozmohla by se po kůži: tedy za čistého vyhlásí ho kněz, nebo prašivina jest. I zpéře roucha svá a čistý bude.'),
(1549250,54,3,13,7,'Pakliť by se dále rozmohla ta prašivina po kůži jeho, již po ukázání se knězi k očištění svému, tedy ukáže se znovu knězi.'),
(1549251,54,3,13,8,'I pohledí na něj kněz, a jestliže se rozmohla ta prašivina po kůži jeho, za nečistého vyhlásí jej kněz, nebo malomocenství jest.'),
(1549252,54,3,13,9,'Rána malomocenství když bude na člověku, přiveden bude k knězi.'),
(1549253,54,3,13,10,'I pohledí na něj kněz, a bude-li oteklina bílá na kůži, až by učinila chlupy bílé, byť pak i zdravé maso bylo na té oteklině:'),
(1549254,54,3,13,11,'Malomocenství zastaralé jest na kůži těla jeho. Protož za nečistého vyhlásí jej kněz, a nedá ho zavříti, nebo zjevně nečistý jest.'),
(1549255,54,3,13,12,'Jestliže by se pak vylilo malomocenství po kůži, a přikrylo by malomocenství všecku kůži nemocného, od hlavy jeho až do noh jeho, všudy kdež by kněz očima viděti mohl:'),
(1549256,54,3,13,13,'I pohledí na něj kněz, a přikrylo-li by malomocenství všecko tělo jeho, tedy za čistého vyhlásí nemocného. Nebo všecka ta rána v bělost se změnila, protož čistý jest.'),
(1549257,54,3,13,14,'Ale kdykoli ukáže se na ní živé maso, nečistý bude.'),
(1549258,54,3,13,15,'I pohledí kněz na to živé maso a vyhlásí jej za nečistého, nebo to maso živé nečisté jest, malomocenství jest.'),
(1549259,54,3,13,16,'Když by pak odešlo zase maso živé a změnilo by se v bělost, tedy přijde k knězi.'),
(1549260,54,3,13,17,'A vida kněz, že obrátila se rána ta v bělost, za čistou vyhlásí ji; čistá jest.'),
(1549261,54,3,13,18,'Když by pak byl na kůži těla vřed, a byl by zhojen,'),
(1549262,54,3,13,19,'Byla-li by na místě vředu toho oteklina bílá, aneb poškvrna pobělavá a náryšavá, tedy ukázána bude knězi.'),
(1549263,54,3,13,20,'A vida kněz, že na pohledění to místo jest nižší nežli jiná kůže, a chlupové na něm by zběleli, za nečistého vyhlásí jej kněz. Rána malomocenství jest, kteráž na vředu vyrostla.'),
(1549264,54,3,13,21,'Pakli, když pohledí na ni kněz, uzří, že chlupové nezběleli na něm, a není nižší nežli jiná kůže, ale že jest pozčernalé místo, tedy zavře ho kněz za sedm dní.'),
(1549265,54,3,13,22,'Pakliť by šíře se rozmáhala po kůži, za nečistého vyhlásí jej kněz; rána malomocenství jest.'),
(1549266,54,3,13,23,'Pakli by ta poškvrna pobělavá zůstávala na místě svém, a nerozmáhala by se, znamení toho vředu jest; protož za čistého vyhlásí jej kněz.'),
(1549267,54,3,13,24,'Tělo, na jehož kůži byla by spálenina od ohně, a po zhojení té spáleniny zůstala by poškvrna pobělavá a náryšavá, anebo bílá toliko:'),
(1549268,54,3,13,25,'Pohledí na ni kněz, a jestliže chlupové na ní zběleli, a lsknou se, způsob také její jest hlubší nežli jiné kůže vůkol: malomocenství jest, kteréž zrostlo na spálenině; protož za nečistého vyhlásí jej kněz, nebo rána malomocenství jest.'),
(1549269,54,3,13,26,'Pakli uzří kněz, an na poškvrně pobělavé není žádného chlupu bílého, a že nižší není nežli jiná kůže, ale že jest pozčernalá, poručí ho zavříti kněz za sedm dní.'),
(1549270,54,3,13,27,'I pohledí na ni kněz dne sedmého. Jestliže se více rozmohla po kůži, tedy za nečistého vyhlásí jej; nebo rána malomocenství jest.'),
(1549271,54,3,13,28,'Pakli bělost lsknutá na svém místě zůstávati bude, a nerozmůže se po kůži, ale bude pozčernalá: zprýštění od spáleniny jest; za čistého vyhlásí jej kněz, nebo šrám spáleniny jest.'),
(1549272,54,3,13,29,'Byla-li by pak rána na hlavě aneb na bradě muže neb ženy,'),
(1549273,54,3,13,30,'Tedy pohledí kněz na tu ránu, a jestliže způsob její bude hlubší nežli jiná kůže, a bude na ní vlas prožlutlý a tenký: tedy za nečistého vyhlásí jej kněz, nebo poškvrna černá jest; malomocenství na hlavě aneb na bradě jest.'),
(1549274,54,3,13,31,'Když pak pohledí kněz na ránu poškvrny černé a uzří, že způsob její není hlubší nežli jiná kůže, a že není vlasu černého na ní: zavříti dá kněz majícího ránu poškvrny černé za sedm dní.'),
(1549275,54,3,13,32,'I pohledí kněz na tu ránu dne sedmého, a aj, nerozmohla se ta poškvrna černá, a není vlasu žlutého na ní, a způsob té poškvrny černé není hlubší nežli kůže:'),
(1549276,54,3,13,33,'Tedy oholen bude člověk ten, ale poškvrny té černé nedá holiti. I dá zavříti kněz majícího tu poškvrnu za sedm dní po druhé.'),
(1549277,54,3,13,34,'I pohledí kněz na poškvrnu černou dne sedmého, a jestliže se nerozmohla poškvrna černá dále po kůži, a místo její není-li hlubší nežli jiná kůže: za čistého vyhlásí ho kněz, i zpéře roucha svá a čistý bude.'),
(1549278,54,3,13,35,'Pakli by se dále rozmohla poškvrna ta černá po kůži, již po očištění jeho,'),
(1549279,54,3,13,36,'Tedy pohledí na ni kněz, a uzří-li, že se dále rozmohla ta poškvrna černá po kůži, nebude více šetřiti vlasu žlutého; nečistý jest.'),
(1549280,54,3,13,37,'Pakli poškvrna černá tak zůstává před očima jeho, a černý vlas vzrostl by na ní, tedy zhojena jest ta poškvrna černá; čistý jest, a za čistého vyhlásí jej kněz.'),
(1549281,54,3,13,38,'Když by na kůži těla muže aneb ženy byly poškvrny, totiž poškvrny pobělavé,'),
(1549282,54,3,13,39,'I pohledí kněz, a jestliže budou na kůži těla jejich poškvrny bílé, pozčernalé, tedy poškvrna bílá jest, kteráž na kůži zrostla; čistý jest.'),
(1549283,54,3,13,40,'Muž, z jehož by hlavy vlasové slezli, lysý jest a čistý jest.'),
(1549284,54,3,13,41,'Jestliže pak po jedné straně obleze hlava jeho, nálysý jest a čistý jest.'),
(1549285,54,3,13,42,'Pakli na té lysině, aneb na tom oblysení byla by rána bílá a ryšavá, tedy malomocenství zrostlo na lysině jeho, aneb na oblysení jeho.'),
(1549286,54,3,13,43,'I pohledí na něj kněz, a uzří-li oteklinu rány bílou a ryšavou na lysině jeho, aneb na oblysení jeho, jako způsob malomocenství na kůži těla:'),
(1549287,54,3,13,44,'Člověk malomocný jest a nečistý jest. Bez meškání za nečistého vyhlásí jej kněz, nebo na hlavě jeho jest malomocenství jeho.'),
(1549288,54,3,13,45,'Malomocný pak, na němž by ta rána byla, bude míti roucho roztržené a hlavu odkrytou a ústa zastřená, a Nečistý, nečistý jsem! volati bude.'),
(1549289,54,3,13,46,'Po všecky dny, v nichž ta rána bude na něm, za nečistého jmín bude; nebo nečistý jest. Sám bydliti bude, vně za stany bude přebývání jeho.'),
(1549290,54,3,13,47,'Když by pak na rouchu byla rána malomocenství, buď na rouchu soukenném aneb na rouchu lněném,'),
(1549291,54,3,13,48,'Buď na osnově aneb na outku ze lnu aneb z vlny, buď na kůži aneb na každé věci kožené,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549292,54,3,13,49,'A byla by ta rána zelená neb náryšavá na rouchu aneb na kůži, aneb na osnově, aneb na outku, aneb na kterékoli nádobě kožené: rána malomocenství jest, ukázána bude knězi.'),
(1549293,54,3,13,50,'I pohledí kněz na tu ránu, a dá zavříti tu věc mající ránu za sedm dní.'),
(1549294,54,3,13,51,'A pohledě na tu ránu dne sedmého, uzří-li, že se dále rozmohla ta rána na rouchu, neb po osnově anebo po outku, aneb na kůži, k čemuž by jí koli užíváno bylo: rána ta malomocenství rozjídavá jest, věc nečistá jest.'),
(1549295,54,3,13,52,'I spálí to roucho aneb osnovu, aneb outek z vlny neb ze lnu, aneb jakoukoli nádobu koženou, na níž by byla rána ta; nebo malomocenství škodlivé jest, protož ohněm spáleno bude.'),
(1549296,54,3,13,53,'Pakli pohledě kněz, uzřel by, že se nerozmohla rána ta na rouchu, aneb na osnově, aneb na outku, aneb na kterékoli nádobě kožené:'),
(1549297,54,3,13,54,'Rozkáže kněz, aby zeprali tu věc, na níž byla by rána, i káže ji zavříti za sedm dní po druhé.'),
(1549298,54,3,13,55,'I pohledí kněz po zeprání té věci na ránu. Jestliže nezměnila rána barvy své, byť se pak nerozmohla dále, předce nečistá jest. Ohněm spálíš ji; nebo rozjídavá věc jest na vrchní neb spodní straně její.'),
(1549299,54,3,13,56,'Pakli pohledě kněz, uzřel by, an pozčernala rána po zeprání svém, odtrhne ji od roucha aneb od kůže, aneb od osnovy, aneb od outku.'),
(1549300,54,3,13,57,'Jestliže se pak ukáže ještě na rouchu aneb na osnově, aneb na outku, aneb na kterékoli nádobě kožené, malomocenství rozjídající se jest. Ohněm spálíš věc tu, na kteréž by ta rána byla.'),
(1549301,54,3,13,58,'Roucho pak aneb osnovu, aneb outek, aneb kteroukoli nádobu koženou, když bys zepral, a odešla by od ní ta rána, ještě po druhé zpéřeš, a čisté bude.'),
(1549302,54,3,13,59,'Tenť jest zákon o ráně malomocenství na rouchu soukenném aneb lněném, aneb na osnově, aneb na outku, aneb na kterékoli nádobě kožené, kterak má za čistou aneb za nečistou uznána býti.'),
(1549303,54,3,14,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549304,54,3,14,2,'Tento bude řád při malomocném v den očišťování jeho: K knězi přiveden bude.'),
(1549305,54,3,14,3,'I vyjde kněz ven z stanů a pohledí na něj, a uzří-li, že uzdravena jest rána malomocenství malomocného:'),
(1549306,54,3,14,4,'Rozkáže kněz tomu, kterýž se očišťuje, vzíti dva vrabce živé a čisté, a dřevo cedrové, a červec dvakrát barvený, a yzop.'),
(1549307,54,3,14,5,'I rozkáže kněz zabiti vrabce jednoho, a vycediti krev z něho do nádoby hliněné nad vodou živou.'),
(1549308,54,3,14,6,'A vezme vrabce živého a dřevo cedrové, též červec dvakrát barvený, a yzop, a omočí to všecko i s vrabcem živým ve krvi vrabce zabitého nad vodou živou.'),
(1549309,54,3,14,7,'Tedy pokropí toho, kterýž se očišťuje od malomocenství, sedmkrát, a za čistého jej vyhlásí, i pustí vrabce živého na pole.'),
(1549310,54,3,14,8,'Ten pak, kterýž se očišťuje, zpéře roucho své a oholí všecky vlasy své, umyje se vodou, a čistý bude. Potom vejde do táboru, a bydliti bude vně, nevcházeje do stanu svého za sedm dní.'),
(1549311,54,3,14,9,'Dne pak sedmého sholí všecky vlasy své, hlavu i bradu svou, i obočí své, a tak všecky vlasy své sholí; zpéře také roucha svá a tělo své umyje vodou, a tak očistí se.'),
(1549312,54,3,14,10,'Dne pak osmého vezme dva beránky bez poškvrny, a ovci jednu roční bez poškvrny, a tři desetiny efi mouky bělné k oběti suché, olejem zadělané, a oleje jednu mírku.'),
(1549313,54,3,14,11,'Kněz pak, kterýž očišťuje, postaví toho člověka očišťujícího se s těmi věcmi před Hospodinem u dveří stánku úmluvy.'),
(1549314,54,3,14,12,'I vezme kněz beránka jednoho, kteréhožto obětovati bude v obět za hřích, a mírku oleje, a obraceti bude tím sem i tam v obět obracení před Hospodinem.'),
(1549315,54,3,14,13,'A zabije beránka toho na místě, kdež se zabijí obět za hřích a obět zápalná, totiž na místě svatém; nebo jakož obět za hřích, tak obět za vinu knězi přináleží, svatá svatých jest.'),
(1549316,54,3,14,14,'I vezme kněz krve z oběti za hřích, a pomaže jí kraje ucha pravého člověka toho, kterýž se očišťuje, a palce ruky jeho pravé, a palce nohy jeho pravé.'),
(1549317,54,3,14,15,'Vezme také kněz z té mírky oleje, a naleje na ruku svou levou.'),
(1549318,54,3,14,16,'A omoče prst svůj pravý v tom oleji, kterýž má na ruce své levé, pokropí z něho prstem svým sedmkrát před Hospodinem.'),
(1549319,54,3,14,17,'Z ostatku pak oleje toho, kterýž má na ruce své, pomaže kněz kraje ucha pravého člověka toho, kterýž se očišťuje, a palce pravé ruky jeho, a palce pravé nohy jeho, na krev oběti za vinu.'),
(1549320,54,3,14,18,'Což pak zůstane oleje, kterýž jest v ruce kněze, pomaže tím hlavy toho, kterýž se očišťuje; a tak očistí jej kněz před Hospodinem.'),
(1549321,54,3,14,19,'Učiní také kněz obět za hřích, a očistí očišťujícího se od nečistoty jeho. A potom zabije obět zápalnou.'),
(1549322,54,3,14,20,'I bude obětovati kněz tu obět zápalnou, i obět suchou na oltáři; a tak očistí jej, i bude čistý.'),
(1549323,54,3,14,21,'Jestliže pak bude chudý, tak že by s to býti nemohl, tedy vezme jednoho beránka v obět za provinění, k obracení jí sem i tam pro očištění své, a desátý díl mouky bělné olejem zadělané k oběti suché, a mírku oleje,'),
(1549324,54,3,14,22,'Též dvě hrdličky aneb dvé holoubátek, kteréž by mohl míti, a bude jedno v obět za hřích, a druhé v obět zápalnou.'),
(1549325,54,3,14,23,'I přinese je v osmý den očišťování svého knězi, ke dveřům stánku úmluvy před Hospodina.'),
(1549326,54,3,14,24,'Tedy kněz vezma beránka oběti za vinu a mírku oleje, obraceti je bude sem i tam v obět obracení před Hospodinem.'),
(1549327,54,3,14,25,'I zabije beránka oběti za provinění, a vezma krve z oběti za provinění, pomaže jí kraje ucha pravého člověka toho, kterýž se očišťuje, a palce ruky jeho pravé, a palce nohy jeho pravé.'),
(1549328,54,3,14,26,'Oleje také naleje kněz na ruku svou levou.'),
(1549329,54,3,14,27,'A omoče prst svůj pravý v oleji, kterýž bude na ruce jeho levé, pokropí jím sedmkrát před Hospodinem.'),
(1549330,54,3,14,28,'Pomaže také kněz olejem, kterýž má na ruce své, kraje ucha pravého toho, kdož se čistí, a palce pravé ruky jeho, a palce pravé nohy jeho, na místě krve z oběti za vinu.'),
(1549331,54,3,14,29,'Což pak zůstává oleje, kterýž jest v ruce kněze, pomaže jím hlavy toho, kterýž se očišťuje; a tak očistí jej před Hospodinem.'),
(1549332,54,3,14,30,'Tolikéž učiní i s hrdličkou jednou aneb s holoubátkem z těch, kteréž zjednati mohl.'),
(1549333,54,3,14,31,'Z těch, kterýchž dostati mohl, obětovati bude jedno za hřích a druhé v obět zápalnou s obětí suchou; a tak očistí kněz očišťujícího se před Hospodinem.'),
(1549334,54,3,14,32,'Ten jest zákon toho, na komž by se ukázala rána malomocenství, a kterýž by nemohl býti s ty věci k očištění svému přináležité.'),
(1549335,54,3,14,33,'I mluvil Hospodin Mojžíšovi a Aronovi, řka:'),
(1549336,54,3,14,34,'Když vejdete do země Kananejské, kterouž já vám za dědictví dávám, a dopustil bych ránu malomocenství na některý dům země, kterouž vládnouti budete,'),
(1549337,54,3,14,35,'Tedy přijde hospodář domu a oznámí knězi řka: Zdá mi se, jako by byla rána malomocenství na domě.'),
(1549338,54,3,14,36,'I rozkáže kněz vyprázdniti dům, dříve než by všel do něho hleděti na tu ránu, aby nebylo poškvrněno něco z těch věcí, kteréž v domě jsou. Potom pak vejde, aby pohleděl na ten dům.'),
(1549339,54,3,14,37,'Tedy vida ránu tu, uzří-li, že rána jest na stěnách domu, totiž důlkové názelení aneb náčervení, a na pohledění jsou nižší než stěna jinde:'),
(1549340,54,3,14,38,'Vyjde kněz z domu toho ke dveřím jeho, a dá zavříti dům ten za sedm dní.'),
(1549341,54,3,14,39,'A v den sedmý navrátí se kněz, a uzří-li, ano se rozmohla rána na stěnách domu toho:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549342,54,3,14,40,'Rozkáže vyníti kamení, na němž by rána taková byla, a vyvrci je ven za město na místo nečisté.'),
(1549343,54,3,14,41,'Dům pak rozkáže vystrouhati vnitř všudy vůkol; a vysypou prach ten, kterýž sstrouhali, vně za městem na místo nečisté.'),
(1549344,54,3,14,42,'A vezmouce jiné kamení, vyplní jím místo onoho kamení; tolikéž hliny jiné vezmouce, vymaží dům.'),
(1549345,54,3,14,43,'Pakliť by se navrátila rána, a vzrostla by v tom domě po vyvržení kamení a vystrouhání domu, i po vymazání jeho,'),
(1549346,54,3,14,44,'Tedy vejda kněz, uzří-li, an se rozmohla rána v domě, malomocenství rozjídající se jest v tom domě, nečistý jest.'),
(1549347,54,3,14,45,'I rozboří ten dům a kamení jeho, i dříví jeho, a všecko mazání domu toho, a vynosí ven za město na místo nečisté.'),
(1549348,54,3,14,46,'Jestliže by pak kdo všel do domu toho v ten čas, když zavřín byl, nečistý bude až do večera.'),
(1549349,54,3,14,47,'A jestliže by kdo spal v tom domě, zpéře roucha svá; tolikéž jestliže by kdo jedl v tom domě, zpéře roucha svá.'),
(1549350,54,3,14,48,'Jestliže by pak kněz vejda tam, uzřel, že se nerozmohla rána v domě po obnovení jeho, tedy za čistý vyhlásí dům ten; nebo uzdravena jest rána jeho.'),
(1549351,54,3,14,49,'A vezma k očištění domu toho dva vrabce a dřevo cedrové, a červec dvakrát barvený a yzop,'),
(1549352,54,3,14,50,'I zabije vrabce jednoho, a vycedí krev do nádoby hliněné nad vodou živou.'),
(1549353,54,3,14,51,'A vezme dřevo cedrové a yzop, a červec dvakrát barvený, a vrabce živého, omočí to všecko ve krvi vrabce zabitého a u vodě živé, a pokropí domu toho sedmkrát.'),
(1549354,54,3,14,52,'A tak když očistí dům ten krví vrabce a vodou živou a ptákem živým, dřevem cedrovým, yzopem a červcem dvakrát barveným:'),
(1549355,54,3,14,53,'Vypustí ven vrabce živého z města na pole, a očistí dům ten, i budeť čistý.'),
(1549356,54,3,14,54,'Ten jest zákon o všeliké ráně malomocenství a poškvrny černé,'),
(1549357,54,3,14,55,'A malomocenství roucha i domu,'),
(1549358,54,3,14,56,'I otekliny, prašiviny a poškvrny pobělavé,'),
(1549359,54,3,14,57,'K ukázání, kdy jest kdo čistý, aneb kdy jest kdo nečistý. Tenť jest zákon malomocenství.'),
(1549360,54,3,15,1,'Mluvil pak Hospodin Mojžíšovi a Aronovi, řka:'),
(1549361,54,3,15,2,'Mluvte synům Izraelským a rcete jim: Když by který muž trpěl tok semene z těla svého, nečistý bude.'),
(1549362,54,3,15,3,'Tato pak bude nečistota jeho v toku jeho: Jestliže vypěňuje tělo jeho tok svůj, aneb že by se zastavil tok v těle jeho, nečistota jeho jest.'),
(1549363,54,3,15,4,'Každé lůže, na němž by ležel, kdož má tok semene, nečisté bude; a všecko, na čemž by seděl, nečisté bude.'),
(1549364,54,3,15,5,'A kdož by se dotekl lůže jeho, zpéře roucha svá, a umyje se vodou, a bude nečistý až do večera.'),
(1549365,54,3,15,6,'A kdo by sedl na to, na čemž seděl ten, kdož má tok semene, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.'),
(1549366,54,3,15,7,'Jestliže by se kdo dotekl těla trpícího tok semene, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.'),
(1549367,54,3,15,8,'A jestliže by ten, kdož trpí tok semene, plinul na čistého, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.'),
(1549368,54,3,15,9,'Každé sedlo, na němž by seděl ten, kdož má tok semene, nečisté bude.'),
(1549369,54,3,15,10,'A kdož by koli dotekl se něčeho, což bylo pod ním, nečistý bude až do večera; a kdož by co z toho nesl, zpéře roucha svá, a umyje se vodou, a bude nečistý až do večera.'),
(1549370,54,3,15,11,'Kohož by se pak dotekl ten, kdož má tok semene, a neumyl rukou svých vodou, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.'),
(1549371,54,3,15,12,'Nádoba hliněná, kteréž by se dotekl ten, kdo má tok semene, bude rozbita, a každá nádoba dřevěná vodou vymyta bude.'),
(1549372,54,3,15,13,'Když by pak očištěn byl ten, kdož tok semene trpěl, od toku svého, sečte sedm dní po svém očištění, a zpéře roucha svá, a vodou živou zmyje tělo své, i bude čist.'),
(1549373,54,3,15,14,'Potom dne osmého vezme sobě dvě hrdličky aneb dvé holoubátek, a přijda před Hospodina ke dveřím stánku úmluvy, dá je knězi.'),
(1549374,54,3,15,15,'Kterýž obětovati je bude, jedno za hřích a druhé v obět zápalnou; a očistí jej kněz před Hospodinem od toku jeho.'),
(1549375,54,3,15,16,'Muž, z něhož by vyšlo símě scházení, zmyje vodou všecko tělo své, a bude nečistý až do večera.'),
(1549376,54,3,15,17,'Každé roucho i každá kůže, na níž by bylo símě scházení, zeprána bude vodou, a nečistá bude až do večera.'),
(1549377,54,3,15,18,'Žena také, s kterouž by obýval muž scházením semene, oba zmyjí se vodou, a nečistí budou až do večera.'),
(1549378,54,3,15,19,'Žena pak, když by trpěla nemoc svou, a tok krve byl by z těla jejího, za sedm dní oddělena bude; každý, kdož by se jí dotekl, nečistý bude až do večera.'),
(1549379,54,3,15,20,'Na čemž by koli ležela v čas oddělení svého, nečistéť bude; tolikéž, na čem by koli seděla, nečisté bude.'),
(1549380,54,3,15,21,'Také kdož by se dotekl lůže jejího, zpéře roucho své, a umyje se vodou, i bude nečistý až do večera.'),
(1549381,54,3,15,22,'Kdož by se koli dotekl toho, na čemž seděla, zpéře roucha svá, a umyje se vodou, i bude nečistý až do večera.'),
(1549382,54,3,15,23,'Což by koli bylo na lůži tom, neb na jaké by koli věci seděla, a dotekl by se toho někdo, nečistý bude až do večera.'),
(1549383,54,3,15,24,'Jestliže by kdo spal s ní, a byla by nečistota její na něm, nečistý bude za sedm dní; i každé lůže, na němž by spal, nečisté bude.'),
(1549384,54,3,15,25,'Žena pak trpěla-li by krvotok po mnohé dny, kromě času nemoci své, totiž krvotok by trpěla přes čas přirozené nemoci: po všecky dny toku nečistoty své, jako i v čas nemoci své přirozené, nečistá bude.'),
(1549385,54,3,15,26,'Každé lůže, na němž by spala po všecky dny toku svého, bude jí jako lůže v přirozené nemoci její; a každá věc, na kteréž by seděla, nečistá bude, podlé nečistoty přirozené nemoci její.'),
(1549386,54,3,15,27,'Kdož by koli dotekl se těch věcí, nečistý bude. Protož zpéře roucho své, a umyje se vodou, i bude nečistý až do večera.'),
(1549387,54,3,15,28,'Když pak očištěna bude od toku svého, sečte sobě sedm dní, a potom očišťovati se bude.'),
(1549388,54,3,15,29,'A v den osmý vezme sobě dvě hrdličky aneb dvé holoubátek, a přinese je knězi ke dveřím stánku úmluvy.'),
(1549389,54,3,15,30,'Z nichž jedno obětovati bude kněz v obět za hřích, a druhé v obět zápalnou, a očistí ji kněz před Hospodinem od toku nečistoty její.'),
(1549390,54,3,15,31,'I budete oddělovati syny Izraelské od nečistot jejich, aby nezemřeli pro nečistoty své, když by poškvrnili příbytku mého, kterýž jest u prostřed nich.'),
(1549391,54,3,15,32,'Toť jest právo trpícího tok semene, i toho, z něhož vychází símě scházení, jímž poškvrněn bývá,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549392,54,3,15,33,'Též nemocné ženy v oddělení jejím, i všelikého trpícího tok svůj, buď mužského pohlaví neb ženského, a muže, kterýž by spal s nečistou.'),
(1549393,54,3,16,1,'Mluvil pak Hospodin k Mojžíšovi po smrti dvou synů Aronových, kteřížto, když předstoupili před Hospodina, zemřeli,'),
(1549394,54,3,16,2,'A řekl Hospodin Mojžíšovi: Mluv Aronovi bratru svému, ať nevchází každého času do svatyně za oponu před slitovnici, kteráž jest na truhle, aby neumřel; nebo já v oblace ukáži se nad slitovnicí.'),
(1549395,54,3,16,3,'S tímto vcházeti bude Aron do svatyně: S volkem mladým, kterýž bude v obět za hřích, a s beranem k oběti zápalné.'),
(1549396,54,3,16,4,'V sukni lněnou svatou obleče se, a košilku lněnou bude míti na těle hanby své, pasem také lněným opáše se, a čepici lněnou vstaví na hlavu, roucha zajisté svatá jsou tato; i umyje vodou tělo své a obleče se v ně.'),
(1549397,54,3,16,5,'Od shromáždění pak synů Izraelských vezme dva kozly k oběti za hřích, a jednoho berana k zápalné oběti.'),
(1549398,54,3,16,6,'I bude obětovati Aron volka svého v obět za hřích, a očistí sebe i dům svůj.'),
(1549399,54,3,16,7,'Potom vezme ty dva kozly a postaví je před Hospodinem u dveří stánku úmluvy.'),
(1549400,54,3,16,8,'I dá Aron na ty dva kozly losy, los jeden Hospodinu, a los druhý Azazel.'),
(1549401,54,3,16,9,'A obětovati bude Aron kozla toho, na něhož by los padl Hospodinu, obětovati jej bude za hřích.'),
(1549402,54,3,16,10,'Kozla pak toho, na něhož přišel los Azazel, postaví živého před Hospodinem, aby skrze něho učinil očištění, a pustí ho na poušť k Azazel.'),
(1549403,54,3,16,11,'I bude obětovati Aron volka svého v obět za hřích, a očistí sebe i dům svůj, a zabije volka svého v obět za hřích.'),
(1549404,54,3,16,12,'Vezme také plnou kadidlnici uhlí řeřavého s oltáře, kterýž jest před tváří Hospodinovou, a plné obě hrsti své vonných věcí stlučených, a vnese za oponu.'),
(1549405,54,3,16,13,'A vloží kadidlo to na oheň před Hospodinem, a dým kadění toho přikryje slitovnici, kteráž jest nad svědectvím, a neumře.'),
(1549406,54,3,16,14,'Potom vezma krve volka toho, pokropí prstem svým na slitovnicí k východu; tolikéž před slitovnicí kropiti bude sedmkrát krví tou prstem svým.'),
(1549407,54,3,16,15,'Zabije také v obět za hřích kozla toho, kterýž jest lidu, a vnese krev jeho do vnitřku za oponu, a učiní se krví jeho, jakož učinil se krví volka, totiž pokropí jí na slitovnici a před slitovnicí.'),
(1549408,54,3,16,16,'A očistí svatyni od nečistot synů Izraelských a od přestoupení jejich i všech hříchů jejich. Totéž učiní i stánku úmluvy, kterýž jest mezi nimi u prostřed nečistot jejich.'),
(1549409,54,3,16,17,'(Žádný pak člověk ať není v stánku úmluvy, když on vchází k očišťování do svatyně, dokudž by on zase nevyšel a očištění za sebe, za dům svůj i za všecko množství Izraelské nevykonal.)'),
(1549410,54,3,16,18,'Vyjde pak k oltáři, kterýž jest před Hospodinem, a očistí jej. A vezma krve volka toho, a ze krve kozla, dá na rohy oltáře vůkol.'),
(1549411,54,3,16,19,'A pokropí ho svrchu krví tou prstem svým sedmkrát, a očistí jej i posvětí ho od nečistot synů Izraelských.'),
(1549412,54,3,16,20,'A když by dokonal očištění svatyně a stánku úmluvy a oltáře, obětovati bude kozla živého.'),
(1549413,54,3,16,21,'A vlože Aron obě ruce své na hlavu kozla živého, vyznávati bude nad ním všecky nepravosti synů Izraelských, a všecka přestoupení jejich se všemi hříchy jejich, a vloží je na hlavu kozla, a vyžene ho člověk k tomu zřízený na poušť.'),
(1549414,54,3,16,22,'(Kozel ten zajisté ponese na sobě všecky nepravosti jejich do země pusté.) A pustí kozla toho na poušti.'),
(1549415,54,3,16,23,'Potom pak přijda Aron do stánku úmluvy, svleče s sebe roucha lněná, v něž se byl oblékl, když vjíti měl do svatyně, a nechá jich tu.'),
(1549416,54,3,16,24,'A umyje tělo své vodou na místě svatém, a obleče se zase v roucha svá, a vyjda, obětovati bude obět zápalnou svou a obět zápalnou lidu, a očistí sebe i lid.'),
(1549417,54,3,16,25,'A tuk oběti za hřích páliti bude na oltáři.'),
(1549418,54,3,16,26,'Ten pak, kterýž vyvedl kozla na Azazel, zpéře roucha svá, a zmyje tělo své vodou, a potom vejde do stanů.'),
(1549419,54,3,16,27,'Volka pak za hřích a kozla za hřích, jejichž krev vnesena byla k vykonání očištění v svatyni, vynese ven z táboru, a spálí ohněm kůže jejich, i maso jejich, i lejna jejich.'),
(1549420,54,3,16,28,'Kdož by pak spálil je, zpéře roucha svá, a umyje tělo své vodou, a potom vejde do táboru.'),
(1549421,54,3,16,29,'Bude vám i toto za věčné ustanovení: Sedmého měsíce, desátého dne téhož měsíce ponižovati budete duší svých, a žádného díla nebudete dělati, ani doma zrozený, ani příchozí, kterýž jest pohostinu mezi vámi.'),
(1549422,54,3,16,30,'Nebo v ten den očistí vás, abyste očištěni byli; ode všech hříchů svých před Hospodinem očištěni budete.'),
(1549423,54,3,16,31,'Sobota odpočinutí bude vám, a ponižovati budete duší svých ustanovením věčným.'),
(1549424,54,3,16,32,'Očišťovati pak bude kněz, kterýž jest pomazaný, a jehož ruce posvěceny jsou k vykonávání úřadu kněžského místo otce svého, a obleče se v roucha lněná, roucha svatá.'),
(1549425,54,3,16,33,'A očistí svatyni svatou a stánek úmluvy, očistí také i oltář, i kněží, i všecken lid shromážděný očistí.'),
(1549426,54,3,16,34,'A bude vám to ustanovením věčným k očišťování synů Izraelských ode všech hříchů jejich, každého roku jednou. I učinil Mojžíš tak, jakž jemu byl přikázal Hospodin.'),
(1549427,54,3,17,1,'I mluvil Hospodin Mojžíšovi, řka:'),
(1549428,54,3,17,2,'Mluv k Aronovi a synům jeho i ke všechněm synům Izraelským, a rci jim: Tato jest věc, kterouž přikázal Hospodin, řka:'),
(1549429,54,3,17,3,'Kdož by koli z domu Izraelského zabil vola aneb beránka, neb kozu, buď mezi stany, aneb kdož by zabil vně za stany,'),
(1549430,54,3,17,4,'A ke dveřím stánku úmluvy nepřivedl by ho, aby obětoval obět Hospodinu před příbytkem Hospodinovým: vinen bude krví, nebo krev vylil; protož vyhlazen bude muž ten z prostředku lidu svého.'),
(1549431,54,3,17,5,'Přivedou tedy synové Izraelští oběti své, kteréž by na poli zabíjeti chtěli, přivedou je, pravím, k Hospodinu ke dveřím stánku úmluvy, k knězi, a obětovati budou oběti pokojné Hospodinu.'),
(1549432,54,3,17,6,'A pokropí kněz krví na oltáři Hospodinovu u dveří stánku úmluvy, a páliti bude tuk u vůni líbeznou Hospodinu.'),
(1549433,54,3,17,7,'A nikoli více nebudou obětovati obětí svých ďáblům, po nichžto odcházejíce, oni smilní. Zákon tento bude jim věčný i všechněm potomkům jejich.'),
(1549434,54,3,17,8,'Protož povíš jim: Kdož by koli z domu Izraelského aneb z příchozích, kteříž by pohostinu byli mezi vámi, obětoval zápal aneb jinou obět,'),
(1549435,54,3,17,9,'A ke dveřím stánku úmluvy nepřivedl by jí, aby ji obětoval Hospodinu; tedy vyhlazen bude člověk ten z lidu svého.'),
(1549436,54,3,17,10,'A kdož by koli z domu Izraelského aneb z příchozích, kteříž jsou pohostinu mezi nimi, jedl jakou krev: postavím tvář svou proti člověku tomu, a vyhladím jej z prostředku lidu jeho.'),
(1549437,54,3,17,11,'Nebo duše všelikého těla ve krvi jest, já pak oddal jsem vám ji k oltáři, k očišťování duší vašich. Nebo sama krev na duši očišťuje.'),
(1549438,54,3,17,12,'Protož řekl jsem synům Izraelským: Nižádný z vás nebude jísti krve; ani příchozí, kterýž pohostinu jest mezi vámi, nebude krve jísti.'),
(1549439,54,3,17,13,'A kdož by koli z synů Izraelských aneb z příchozích, kteříž jsou pohostinu mezi vámi, honě, ulovil zvíře aneb ptáka, což se jísti může, tedy vycedí krev jeho a zasype ji prstí.'),
(1549440,54,3,17,14,'Nebo duše všelikého těla jest krev jeho, kteráž jest v duši jeho. Protož jsem pověděl synům Izraelským: Krve žádného těla jísti nebudete, nebo duše všelikého těla jest krev jeho; kdož by koli jedl ji, vyhlazen bude.'),
(1549441,54,3,17,15,'Kdož by pak koli jedl tělo mrtvé aneb udávené, buď on doma zrozený aneb příchozí: zpéře roucha svá, a umyje se vodou, a nečistý bude až do večera, potom pak čistý bude.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549442,54,3,17,16,'A pakli nezpéře roucha svého, a těla svého neumyje, tedy ponese nepravost svou.'),
(1549443,54,3,18,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549444,54,3,18,2,'Mluv synům Izraelským a rci jim: Já jsem Hospodin Bůh váš.'),
(1549445,54,3,18,3,'Vedlé skutků země Egyptské, v níž jste bydlili, nečiňte, ani podlé skutků země Kananejské, do kteréž já vás uvozuji, činiti budete, a v ustanoveních jejich nechoďte.'),
(1549446,54,3,18,4,'Soudy mé čiňte a ustanovení mých ostříhejte, abyste chodili v nich: Já jsem Hospodin Bůh váš.'),
(1549447,54,3,18,5,'Ostříhejte ustanovení mých a soudů mých. Člověk ten, kterýž by je činil, živ bude v nich: Já jsem Hospodin.'),
(1549448,54,3,18,6,'Nižádný člověk k žádné přítelkyni krevní nepřistupuj k obnažení hanby její: Já jsem Hospodin.'),
(1549449,54,3,18,7,'Hanby otce svého a matky své neodkryješ; matka tvá jest, neodkryješ hanby její.'),
(1549450,54,3,18,8,'Hanby ženy otce svého neodkryješ; nebo hanba otce tvého jest.'),
(1549451,54,3,18,9,'Hanby sestry své, dcery otce svého aneb dcery matky své, kteráž doma zplozena aneb vně zplozena jest, neodkryješ hanby jejich.'),
(1549452,54,3,18,10,'Hanby vnučky své, buď po synu neb dceři své, neodkryješ; nebo hanba tvá jsou.'),
(1549453,54,3,18,11,'Hanby dcery manželky otce svého, kteráž jest zplozena od otce tvého, tvá sestra jest, neodkryješ hanby její.'),
(1549454,54,3,18,12,'Hanby sestry otce svého neodkryješ; nebo krevní přítelkyně otce tvého jest.'),
(1549455,54,3,18,13,'Hanby sestry matky své neodkryješ; nebo krevní přítelkyně matky tvé jest.'),
(1549456,54,3,18,14,'Hanby bratra otce svého neodkryješ; k manželce jeho nevejdeš, stryna tvá jest.'),
(1549457,54,3,18,15,'Hanby nevěsty své neodkryješ; manželka jest syna tvého, neodkryješ hanby její.'),
(1549458,54,3,18,16,'Hanby manželky bratra svého neodkryješ; nebo hanba bratra tvého jest.'),
(1549459,54,3,18,17,'Hanby ženy a dcery její neodkryješ. Vnučky její po synu neb po dceři její nepojmeš, abys odkryl hanbu její; nebo krevní jsou, a nešlechetnost jest.'),
(1549460,54,3,18,18,'Nevezmeš sobě ženy k ženě první, abys ssoužil ji, odkrývaje hanbu její za života jejího.'),
(1549461,54,3,18,19,'Také k ženě, když jest v své nemoci nečisté, nepřistoupíš, odkrývaje hanbu její.'),
(1549462,54,3,18,20,'S manželkou bližního svého nebudeš obcovati, poškvrňuje se s ní.'),
(1549463,54,3,18,21,'Nedopustíš, aby kdo z semene tvého proveden byl skrze oheň modly Moloch, abys nepoškvrnil jména Boha svého: Já jsem Hospodin.'),
(1549464,54,3,18,22,'Nebudeš obcovati s mužským pohlavím, scházeje se s ním jako s ženou; nebo ohavnost jest.'),
(1549465,54,3,18,23,'A s žádným hovadem nebudeš obcovati, poškvrňuje se s ním; ani žena nepoddá se hovadu, aby s ním obývala; nebo mrzkost jest.'),
(1549466,54,3,18,24,'A protož nepoškvrňujtež se žádnou touto věcí; nebo těmito všemi věcmi poškvrnili se pohané, kteréž já vyvrhu od tváři vaší.'),
(1549467,54,3,18,25,'Nebo poškvrnila se země, a navštívím nepravost její na ní, a vyvrátí země obyvatele své.'),
(1549468,54,3,18,26,'Ale vy ostříhejte ustanovení mých a soudů mých, a nečiňte nižádných ohavností těchto, tak domácí jako příchozí, kterýž jest pohostinu u prostřed vás.'),
(1549469,54,3,18,27,'(Nebo všecky ty ohavnosti činili lidé země té, kteříž byli před vámi, čímž poškvrněna jest země.)'),
(1549470,54,3,18,28,'Aby nevyvrátila vás země, proto že byste jí poškvrnili, jako vyvrátila národ, kterýž byl před vámi.'),
(1549471,54,3,18,29,'Nebo kdož by koli dopustil se některé ze všech ohavností těch: duše zajisté, kteréž by činily to, vyhlazeny budou z prostředku lidu svého.'),
(1549472,54,3,18,30,'Protož ostříhejte přikázání mých, abyste nečinili ničeho z obyčejů ohavných,kteříž činěni jsou před vámi, aniž sebe jimi poškvrňujte: Já jsem Hospodin Bůh váš.'),
(1549473,54,3,19,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549474,54,3,19,2,'Mluv ke všemu množství synů Izraelských a rci jim: Svatí buďte, nebo svatý jsem, já Hospodin Bůh váš.'),
(1549475,54,3,19,3,'Jeden každý matky své a otce svého báti se budete. A sobot mých ostříhejte, nebo já jsem Hospodin Bůh váš.'),
(1549476,54,3,19,4,'Neobracejte se k modlám, a bohů litých nedělejte sobě: Já jsem Hospodin Bůh váš.'),
(1549477,54,3,19,5,'A když obětovati budete oběti pokojné Hospodinu, z dobré vůle své obětovati budete je.'),
(1549478,54,3,19,6,'Kterého dne obětovati budete, jísti budete je, i nazejtří; což by pak zůstalo až do třetího dne, ohněm spáleno bude.'),
(1549479,54,3,19,7,'Pakli předce jísti budete dne třetího, věc ohavná bude, a nebude oblíbena.'),
(1549480,54,3,19,8,'Kdož by to jedl, pokutu nepravosti své ponese; nebo svatosti Hospodinovy poškvrnil, protož vyhlazena bude duše ta z lidu svého.'),
(1549481,54,3,19,9,'Když budete žíti obilé země vaší, nesežneš naskrze všeho pole svého, a nebudeš sbírati pozůstalých klasů žně své.'),
(1549482,54,3,19,10,'Tolikéž ostatků vinice své nebudeš bráti, a zrní vinice své nebudeš sbírati; chudému a příchozímu zanecháš toho: Já jsem Hospodin Bůh váš.'),
(1549483,54,3,19,11,'Nekraďte a nelžete, a nižádný neoklamávej bližního svého.'),
(1549484,54,3,19,12,'Nepřisahejte křivě ve jméno mé, aniž kdo poškvrňuj jména Boha svého: Já jsem Hospodin.'),
(1549485,54,3,19,13,'Neutiskneš mocí bližního svého, aniž obloupíš ho. Nezůstane mzda dělníka u tebe až do jitra.'),
(1549486,54,3,19,14,'Hluchému nebudeš zlořečiti, a před slepým nepoložíš úrazu, ale báti se budeš Boha svého, nebo já jsem Hospodin.'),
(1549487,54,3,19,15,'Neučiníš neprávě v soudu. Nepřijmeš osoby chudého, aniž šanovati budeš osoby bohatého; spravedlivě souditi budeš bližního svého.'),
(1549488,54,3,19,16,'Nebudeš choditi jako utrhač v lidu svém, aniž státi budeš na hrdlo bližnímu svému: Já jsem Hospodin.'),
(1549489,54,3,19,17,'Nebudeš nenáviděti bratra svého v srdci svém; svobodně potresceš bližního svého, a nesneseš na něm hříchu.'),
(1549490,54,3,19,18,'Nebudeš se mstíti, aniž držeti budeš hněvu proti synům lidu svého, ale milovati budeš bližního svého jako sebe samého: Já jsem Hospodin.'),
(1549491,54,3,19,19,'Ustanovení mých ostříhejte. Hovadu svému nedáš se scházeti s hovadem jiného pokolení. Pole svého neposeješ rozdílným semenem, a rouchem z rozdílných věcí, jako z vlny a ze lnu, setkaným nebudeš se odívati.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549492,54,3,19,20,'Jestliže by muž spal s ženou, a obcoval s ní, kteráž děvkou jsuc, byla by zasnoubená jinému muži, a nebyla by žádnou mzdou vykoupena, ani propuštěna: oba dva zmrskáni budou, a neumrouť; nebo nebyla svobodná učiněna.'),
(1549493,54,3,19,21,'On pak přivede obět za vinu svou Hospodinu ke dveřím stánku úmluvy, skopce za vinu.'),
(1549494,54,3,19,22,'I očistí jej kněz skopcem, kterýž se obětuje za vinu před Hospodinem, od hříchů jeho, kterýmž zhřešil, a bude mu odpuštěn hřích jeho.'),
(1549495,54,3,19,23,'Když pak vejdete do země, a nasázíte všelikého stromoví ovoce nesoucího, tedy obřežete neobřezání jeho, totiž ovoce jeho. Po tři léta budete míti je za neobřezané, protož nebude jedeno.'),
(1549496,54,3,19,24,'Čtvrtého pak léta bude všeliké ovoce jeho posvěcené k chválení Hospodina,'),
(1549497,54,3,19,25,'(Pátého teprv léta jísti budete ovoce jeho), aby rozmnožil vám úrody jeho; nebo já jsem Hospodin Bůh váš.'),
(1549498,54,3,19,26,'Nic nebudete jísti se krví. Nebudete hádati, aniž na časích zakládati budete.'),
(1549499,54,3,19,27,'Nebudeš střihati vlasů hlavy své okrouhle, aniž zohaví kdo brady své.'),
(1549500,54,3,19,28,'Nad mrtvým pak nebudete řezati těla svého, a žádného znamení vyrytého na sobě neučiníte: Já jsem Hospodin.'),
(1549501,54,3,19,29,'Nepoškvrňuj dcery své, dopouštěje smilniti jí, aby země nesmilnila a nebyla naplněna nešlechetností.'),
(1549502,54,3,19,30,'Sobot mých ostříhati budete, a svatyně mé báti se budete: Já jsem Hospodin.'),
(1549503,54,3,19,31,'Neobracejte se k hadačům a věšťcům, ani od nich rady beřte, poškvrňujíce se s nimi: Já jsem Hospodin Bůh váš.'),
(1549504,54,3,19,32,'Před člověkem šedivým povstaň, a cti osobu starého, a boj se Boha svého, nebo já jsem Hospodin.'),
(1549505,54,3,19,33,'Jestliže bude pohostinu u tebe příchozí v zemi vaší, nečiňte jemu křivdy.'),
(1549506,54,3,19,34,'Jakožto jeden z doma zrozených vašich, tak bude vám příchozí, kterýž jest u vás pohostinu, a milovati ho budeš jako sebe samého; nebo i vy pohostinu jste byli v zemi Egyptské: Já jsem Hospodin Bůh váš.'),
(1549507,54,3,19,35,'Nečiňte neprávě v soudu, v rozměřování, v váze a v míře.'),
(1549508,54,3,19,36,'Závaží spravedlivé, kámen spravedlivý, korec spravedlivý, pintu spravedlivou míti budete: Já jsem Hospodin Bůh váš, kterýž jsem vás vyvedl z země Egyptské.'),
(1549509,54,3,19,37,'Protož ostříhejte všech ustanovení mých a všech soudů mých, a čiňte je, nebo já jsem Hospodin.'),
(1549510,54,3,20,1,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1549511,54,3,20,2,'Synům také Izraelským díš: Kdo by koli z synů Izraelských a z příchozích, kteříž by byli pohostinu v Izraeli, dal z semene svého modle Moloch, smrtí umře. Lid země té kamením jej uhází.'),
(1549512,54,3,20,3,'Nebo já postavím tvář svou proti takovému, a vyhladím ho z prostředku lidu jeho, proto že z semene svého dal modle Moloch, a tak zprznil svatyni mou, a poškvrnil jména svatosti mé.'),
(1549513,54,3,20,4,'Jestliže by pak lid země té všelijak přehlídal to na člověku tom, kterýž by dal z semene svého modle Moloch, a nezahubil by ho:'),
(1549514,54,3,20,5,'Tedy já postavím tvář svou proti muži tomu a proti čeledi jeho, a vyhladím ho i všecky, kteříž smilníce, odcházeli po něm, aby smilnili, následujíce Molocha, z prostředku lidu jeho.'),
(1549515,54,3,20,6,'Duše, kteráž by se obrátila k hadačům a věšťcům, aby smilnila, postupujíc po nich: postavím tvář svou proti duši té, a vyhladím ji z prostředku lidu jejího.'),
(1549516,54,3,20,7,'A protož posvěťte se a buďte svatí, nebo já jsem Hospodin Bůh váš.'),
(1549517,54,3,20,8,'A ostříhejte ustanovení mých, a čiňte je: Já jsem Hospodin posvětitel váš.'),
(1549518,54,3,20,9,'Kdož by koli zlořečil otci svému neb matce své, smrtí umře. Otci svému a matce své zlořečil, krev jeho bude na něm.'),
(1549519,54,3,20,10,'Muž, pak, kterýž by se cizoložství dopustil s ženou něčí, že zcizoložil s ženou bližního svého, smrtí umře cizoložník ten i cizoložnice.'),
(1549520,54,3,20,11,'A kdož by koli obcoval s ženou otce svého, hanbu otce svého odkryl. Smrtí umrou oba dva, krev jejich bude na ně.'),
(1549521,54,3,20,12,'Kdož by pak obcoval s nevěstou svou, smrtí umrou oba dva. Mrzkosti se dopustili, krev jejich bude na ně.'),
(1549522,54,3,20,13,'A kdož by se scházel s pohlavím mužským jako s ženou, ohavnost učinili oba dva. Smrtí umrou, krev jejich bude na ně.'),
(1549523,54,3,20,14,'A kdož by vzal ženu a matku její nešlechetnost jest. Ohněm spálí i jej i je, aby nebylo nešlechetností u prostřed vás.'),
(1549524,54,3,20,15,'Kdož by pak obcoval s hovadem, smrtí umře, a hovado zabijete.'),
(1549525,54,3,20,16,'Tolikéž žena, kteráž by přistoupila k některému hovadu, aby obcovala s ním, zabiješ ji i to hovado. Smrtí umrou, krev jejich bude na ně.'),
(1549526,54,3,20,17,'Kdož by koli vezma sestru svou, dceru otce svého, aneb dceru matky své, viděl by hanbu její, a ona také viděla by hanbu jeho, mrzkost jest. Protož vyhlazeni budou před očima synů lidu svého; nebo hanbu sestry své odkryl, nepravost svou ponese.'),
(1549527,54,3,20,18,'A kdož by koli spal s ženou v její nemoci a obnažil by hanbu její, a tok její by odkryl, i ona ukázala by krvotok svůj: vyhlazeni budou oba z prostředku lidu svého.'),
(1549528,54,3,20,19,'Hanby sestry matky své a sestry otce svého neodkryješ. Nebo kdož by to učinil, krevní přítelkyni svou by obnažil; protož nepravost svou ponesou.'),
(1549529,54,3,20,20,'Kdož by pak spal s ženou strýce svého, hanbu strýce svého odkryl. Ponesou hřích svůj, bez dětí zemrou.'),
(1549530,54,3,20,21,'Tolikéž kdož by vzal manželku bratra svého, mrzkost jest. Hanbu bratra svého obnažil, protož bez dětí budou.'),
(1549531,54,3,20,22,'Ostříhejtež tedy všech ustanovení mých a všech soudů mých, a čiňte je, aby nevyvrátila vás země, do níž já uvozuji vás, abyste v ní bydlili.'),
(1549532,54,3,20,23,'Aniž choďte v ustanoveních národu toho, kterýž já vyvrhu od tváři vaší; nebo všecky ty věci činili, a měl jsem je v ošklivosti.'),
(1549533,54,3,20,24,'Vám jsem pak řekl: Vládnouti budete zemí jejich, a já dám ji vám, abyste ji dědičně obdrželi, zemi tekoucí mlékem a strdí. Já jsem Hospodin Bůh váš, kterýž jsem vás oddělil od jiných národů.'),
(1549534,54,3,20,25,'Protož vy mějte rozdíl mezi hovadem čistým a nečistým, a mezi ptákem čistým a nečistým, a nepoškvrňujte duší svých hovady a ptactvem, a tím vším, což se plazí po zemi, kteréž jsem já vám oddělil, abyste je měli za nečisté.'),
(1549535,54,3,20,26,'Ale budete mi svatí; nebo svatý jsem já Hospodin, a oddělil jsem vás od jiných národů, abyste byli moji.'),
(1549536,54,3,20,27,'Muž pak neb žena, kteříž by měli ducha čarodějného a věštího, smrtí umrou. Kamením uházejí je, krev jejich bude na ně.'),
(1549537,54,3,21,1,'Řekl také Hospodin Mojžíšovi: Mluv kněžím synům Aronovým a rci jim: Při mrtvém nepoškvrní se žádný z vás v lidu svém.'),
(1549538,54,3,21,2,'Toliko při krevním příteli svém, mateři neb otci svém, synu neb dceři své a bratru svém,'),
(1549539,54,3,21,3,'Též při sestře své, panně sobě nejbližší, kteráž neměla muže, při té poškvrní se.'),
(1549540,54,3,21,4,'Nepoškvrní se při knížeti lidu svého, tak aby nečistý byl.'),
(1549541,54,3,21,5,'Nebudou dělati sobě lysiny na hlavě své, vytrhávajíce sobě vlasy. A brady své nebudou holiti, ani těla svého řezati.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549542,54,3,21,6,'Budou svatí Bohu svému, aniž poškvrní jména Boha svého; nebo oběti ohnivé Hospodinovy, chléb Boha svého obětují, protož svatí budou.'),
(1549543,54,3,21,7,'Ženy nevěstky aneb poškvrněné nevezmou sobě, a ženy zahnané od muže jejího nepojmou; nebo svatý jest jeden každý z nich Bohu svému.'),
(1549544,54,3,21,8,'Ty také, lide, za svatého budeš jej míti, nebo chléb Boha tvého obětuje. Protož svatý bude tobě, nebo já svatý jsem Hospodin, kterýž posvěcuji vás.'),
(1549545,54,3,21,9,'Dcera pak některého kněze, když by se smilství dopustila, otce svého poškvrnila. Ohněm spálena buď.'),
(1549546,54,3,21,10,'Kněz pak nejvyšší mezi bratřími svými, na jehožto hlavu vylit jest olej pomazání, a posvětil rukou svých, aby obláčel se v roucho svaté, hlavy své neodkryje a roucha svého neroztrhne.'),
(1549547,54,3,21,11,'Aniž k kterému tělu mrtvému přistoupí, a aniž při otci aneb mateři své poškvrní se.'),
(1549548,54,3,21,12,'Nevyjde z svatyně a nepoškvrní svatyně Boha svého; nebo koruna oleje pomazání Boha jeho jest na něm: Já jsem Hospodin.'),
(1549549,54,3,21,13,'On také ženu v panenstvím jejím za manželku sobě pojme.'),
(1549550,54,3,21,14,'Vdovy, aneb zahnané, aneb poškvrněné, nevěstky, žádné z těch nebude sobě bráti, ale pannu z lidu svého vezme sobě za manželku.'),
(1549551,54,3,21,15,'A nepoškvrní semene svého v rodu svém, nebo já jsem Hospodin posvětitel jeho.'),
(1549552,54,3,21,16,'Mluvil opět Hospodin Mojžíšovi, řka:'),
(1549553,54,3,21,17,'Mluv k Aronovi a rci: Kdožkoli z semene tvého po všech rodech svých bude míti na sobě vadu, nechť nepřistupuje, aby obětoval chléb Boha svého.'),
(1549554,54,3,21,18,'Nebo žádný muž, kterýž by měl na sobě vadu, nemá přistupovati: Muž slepý, aneb kulhavý, aneb mající oud některý příliš malý, aneb příliš veliký,'),
(1549555,54,3,21,19,'Aneb muž, kterýž by měl zlámanou nohu, aneb zlámanou ruku,'),
(1549556,54,3,21,20,'Aneb hrbovatý, aneb krhavý, aneb kterýž má bělmo na oku svém, aneb prašivost ustavičnou, neb lišeje, aneb stlačené lůno.'),
(1549557,54,3,21,21,'Nižádný muž, kterýž by měl na sobě nějakou vadu, z semene Arona kněze, nepřistoupí, aby obětoval oběti ohnivé Hospodinu; nebo vada na něm jest. Nepřistoupíť, aby obětoval chléb Boha svého.'),
(1549558,54,3,21,22,'Chléb však Boha svého z věcí svatosvatých a z věcí svatých jísti bude.'),
(1549559,54,3,21,23,'Ale za oponu nebude vcházeti a k oltáři nebude přistupovati, nebo vada jest na něm, aby nepoškvrnil svatyně mé; nebo já jsem Hospodin posvětitel jejich.'),
(1549560,54,3,21,24,'Ta slova mluvil Mojžíš k Aronovi a k synům jeho, i ke všechněm synům Izraelským.'),
(1549561,54,3,22,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549562,54,3,22,2,'Mluv Aronovi a synům jeho, ať se zdržují od věcí těch, kteréž jsou posvěceny od synů Izraelských, a ať nepoškvrňují jména svatého mého v tom, což mi oni posvěcují: Já jsem Hospodin.'),
(1549563,54,3,22,3,'Rci jim: Kdo by koli ze všeho semene vašeho v pronárodech vašich přistoupil ku posvěceným věcem, kterýchž by posvětili synové Izraelští Hospodinu, když nečistota jeho na něm jest, vyhlazena bude duše ta od tváři mé: Já jsem Hospodin.'),
(1549564,54,3,22,4,'Kdo by koli z semene Aronova byl malomocný, aneb tok semene trpící, nebude jísti z věcí posvěcených, dokavadž by se neočistil. A kdož by se koli dotekl nečistoty těla mrtvého, aneb toho, z něhož by vyšlo símě scházení,'),
(1549565,54,3,22,5,'Aneb kdo by se dotkl kterého zeměplazu, jímž by se poškvrnil, aneb člověka, pro něhož by byl nečistý vedlé všelijaké nečistoty jeho:'),
(1549566,54,3,22,6,'Člověk, kterýž by se čehokoli toho dotekl, nečistý bude až do večera, a nebude jísti z věcí posvěcených, leč by umyl tělo své vodou.'),
(1549567,54,3,22,7,'A po západu slunce čistý bude, a potom bude moci jísti z věcí posvěcených, nebo pokrm jeho jest.'),
(1549568,54,3,22,8,'Mrchy a udáveného jísti nebude, aby se tím nepoškvrnil: Já jsem, Hospodin.'),
(1549569,54,3,22,9,'Protož ostříhati budou přisluhování mých, aby hříchů na se neuvedli, a nezemřeli v něm, proto že je zprznili: Jáť jsem Hospodin posvětitel jejich.'),
(1549570,54,3,22,10,'Žádný cizí nebude jísti z věcí posvěcených, ani podruh kněžský, ani nájemník nebude jísti věcí posvěcených.'),
(1549571,54,3,22,11,'Koupil-li by kněz člověka za své peníze, ten jísti bude z věcí těch, též v domě jeho zplozený; ti budou jísti z pokrmu jeho.'),
(1549572,54,3,22,12,'Ale dcera knězova, kteráž by se vdala za muže z jiného pokolení, ta z obětí vzhůru pozdvižených, totiž věcí svatých, nebude jísti.'),
(1549573,54,3,22,13,'Kdyby pak dcera knězova ovdověla, aneb zahnána byla od muže, nemající plodu, a navrátila by se do domu otce svého: tak jako v dětinství svém chléb otce svého jísti bude, cizí pak žádný nebude jísti z něho.'),
(1549574,54,3,22,14,'Jedl-li by pak kdo z nedopatření věci posvěcené, pátý díl nad to přidá knězi, a nahradí jemu tu věc posvěcenou,'),
(1549575,54,3,22,15,'Aby nepoškvrňovali věcí svatých, kteréž by synové Izraelští obětovali Hospodinu,'),
(1549576,54,3,22,16,'A neuvozovali na ně pokuty za provinění, že jedli věci posvěcené jejich; nebo já jsem Hospodin, kterýž jich posvěcuji.'),
(1549577,54,3,22,17,'Dále mluvil Hospodin Mojžíšovi, řka:'),
(1549578,54,3,22,18,'Mluv k Aronovi a k synům jeho i ke všechněm synům Izraelským, a rci jim: Kdož by koli z domu Izraelského aneb z pohostinných, kteříž jsou v Izraeli, obětovali obět svou vedlé všech slibů svých, vedlé všech darů dobrovolných svých, kteréž by obětovali Hospodinu v obět zápalnou:'),
(1549579,54,3,22,19,'Z dobré vůle své obětovati budete samce bez poškvrny, z skotů, z ovcí a z koz.'),
(1549580,54,3,22,20,'Což by koli mělo na sobě vadu, nebudete toho obětovati; nebo nebude příjemné od vás.'),
(1549581,54,3,22,21,'Pakli by kdo obětoval obět pokojnou Hospodinu, vykonávaje slib svůj, aneb dobrovolný dar, buď z skotů, aneb z bravů; ať jest bez vady, aby bylo příjemné; nebudeť žádné poškvrny na něm.'),
(1549582,54,3,22,22,'Slepého aneb polámaného, osekaného aneb uhřivého, prašivého aneb s lišeji, takového neobětujte Hospodinu a nedávejte jich k ohnivé oběti na oltář Hospodinův.'),
(1549583,54,3,22,23,'Vola neb dobytče s nedorostlými neb přerostlými oudy, v dobrovolný zajisté dar obětovati je budeš, ale za slib nebude příjemný.'),
(1549584,54,3,22,24,'Ztlačeného aneb ztlučeného, odtrženého, vykleštěného nebudete obětovati Hospodinu; neučiníte toho v zemi vaší.'),
(1549585,54,3,22,25,'A z ruky cizozemce nebudete obětovati chleba Bohu svému ze všech těch věcí, nebo porušení jejich jest na nich; vadu mají, nebudou příjemné od vás.'),
(1549586,54,3,22,26,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1549587,54,3,22,27,'Vůl neb beran, aneb koza, když se urodí, za sedm dní při matce své zanecháno bude, osmého pak dne i potom bude přijemné k oběti ohnivé Hospodinu.'),
(1549588,54,3,22,28,'Krávy pak a dobytčete s mladým jeho nezabijete jednoho dne.'),
(1549589,54,3,22,29,'A když byste obětovali obět chvály Hospodinu, dobrovolně ji obětovati budete.'),
(1549590,54,3,22,30,'V tentýž den snědena bude a nepozůstavíte z ní ničeho až do jitra: Já jsem Hospodin.'),
(1549591,54,3,22,31,'Protož ostříhejte přikázaní mých a čiňte je: Já jsem Hospodin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549592,54,3,22,32,'A nepoškvrňujte jména svatého mého, i buduť posvěcen u prostřed synů Izraelských: Já jsem Hospodin posvětitel váš,'),
(1549593,54,3,22,33,'Kterýž jsem vás vyvedl z země Egyptské, abych vám byl za Boha: Já jsem Hospodin.'),
(1549594,54,3,23,1,'Mluvil opět Hospodin Mojžíšovi, řka:'),
(1549595,54,3,23,2,'Mluv k synům Izraelským a rci jim: Slavnosti Hospodinovy, kteréž nazývati budete shromáždění svatá, tyto jsou slavnosti mé:'),
(1549596,54,3,23,3,'Šest dní dělati budete, dne pak sedmého sobota odpočinutí jest, shromáždění svaté bude. Žádného díla nedělejte, nebo jest sobota Hospodinova, ve všech příbytcích vašich.'),
(1549597,54,3,23,4,'Protož tyto jsou slavnosti Hospodinovy, shromáždění svatá, kteréž slaviti budete v časy jich určité:'),
(1549598,54,3,23,5,'Měsíce prvního, čtrnáctého dne téhož měsíce u večer bude Fáze Hospodinovo.'),
(1549599,54,3,23,6,'A patnáctého dne téhož měsíce svátek přesnic bude Hospodinu; za sedm dní přesné chleby jísti budete.'),
(1549600,54,3,23,7,'Dne prvního sbor svatý míti budete; žádného díla robotného nebudete dělati.'),
(1549601,54,3,23,8,'Ale obětovati budete obět ohnivou Hospodinu za sedm dní. Dne také sedmého sbor svatý bude; žádného díla robotného nebudete dělati.'),
(1549602,54,3,23,9,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549603,54,3,23,10,'Mluv k synům Izraelským a rci jim: Když vejdete do země, kterouž já dávám vám, a žíti budete obilí její, tedy přinesete snopek prvotiny žně vaší k knězi.'),
(1549604,54,3,23,11,'Kterýž obraceti bude sem i tam snopek ten před Hospodinem, aby byl příjemnou obětí za vás; nazejtří po sobotě obraceti jej bude kněz.'),
(1549605,54,3,23,12,'Kterého dne obraceti budete snopek ten, téhož zabijete beránka ročního bez poškvrny v obět zápalnou Hospodinu.'),
(1549606,54,3,23,13,'Též i obět suchou jeho, dvě desetiny mouky bělné olejem zadělané, v obět ohnivou Hospodinu u vůni příjemnou, a mokrou obět jeho, vína čtvrtý díl míry hin.'),
(1549607,54,3,23,14,'Chleba pak, ani pražmy, ani zrní vymnutého nebudete jísti, až právě do toho dne, když obětovati budete obět Bohu svému. Ustanovení to věčné bude v pronárodech vašich, ve všech příbytcích vašich.'),
(1549608,54,3,23,15,'Počtete sobě také od prvního dne po sobotě, ode dne, v němž jste obětovali snopek sem i tam obracení, (plných sedm téhodnů ať jest),'),
(1549609,54,3,23,16,'Až do prvního dne po sedmém téhodni, sečtete padesáte dní, a tehdy obětovati budete novou obět suchou Hospodinu.'),
(1549610,54,3,23,17,'Z příbytků svých přinesete chleby sem i tam obracení, dva bochníky ze dvou desetin mouky bělné budou; kvašené je upečete, prvotiny jsou Hospodinu.'),
(1549611,54,3,23,18,'A s tím chlebem obětovati budete sedm beránků ročních bez vady, a volka mladého jednoho, a skopce dva; obět zápalná budou Hospodinu, s obětmi svými suchými i mokrými, obět ohnivá vůně spokojující Hospodina.'),
(1549612,54,3,23,19,'Zabijete také kozla jednoho za hřích, a dva beránky roční k oběti pokojné.'),
(1549613,54,3,23,20,'I bude je kněz sem i tam obraceti s chleby prvotin v obět sem i tam obracení před Hospodinem, i s těmi dvěma beránky; a budou svaté věci Hospodinu, a dostanou se knězi.'),
(1549614,54,3,23,21,'I vyhlásíte v ten den slavnost, shromáždění svaté míti budete, žádného díla robotného nebudete dělati. Ustanovení to bude věčné ve všech příbytcích vašich, v pronárodech vašich.'),
(1549615,54,3,23,22,'A když budete žíti obilé krajiny vaší, nesežneš všeho až do konce pole svého, a pozůstalých klasů po žni své nebudeš sbírati; chudému a příchozímu zanecháš jich: Já jsem Hospodin Bůh váš.'),
(1549616,54,3,23,23,'Mluvil ještě Hospodin k Mojžíšovi, řka:'),
(1549617,54,3,23,24,'Mluv synům Izraelským takto: Měsíce sedmého, v první den téhož měsíce, budete míti odpočinutí, památku troubení, shromáždění svaté držíce.'),
(1549618,54,3,23,25,'Žádného díla robotného nebudete dělati, a budete obětovati obět ohnivou Hospodinu.'),
(1549619,54,3,23,26,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1549620,54,3,23,27,'Desátý pak den každého měsíce sedmého den očišťování jest. Shromáždění svaté míti budete, a ponižovati budete životů svých, a obětovati obět ohnivou Hospodinu.'),
(1549621,54,3,23,28,'Žádného díla nebudete dělati v ten den; nebo den očišťování jest, k očišťování vás před Hospodinem Bohem vaším.'),
(1549622,54,3,23,29,'A všeliká duše, kteráž by neponižovala se toho dne, vyhlazena bude z lidu svého.'),
(1549623,54,3,23,30,'Kdož by koli dílo nějaké dělal toho dne, zatratím člověka toho z lidu jeho.'),
(1549624,54,3,23,31,'Žádného díla nedělejte. Ustanovení to bude věčné v pronárodech vašich, ve všech příbytcích vašich.'),
(1549625,54,3,23,32,'Sobotu odpočinutí míti budete, když ponižovati budete duší svých, devátého dne téhož měsíce u večer; od večera až do druhého večera držeti budete sobotu svou.'),
(1549626,54,3,23,33,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1549627,54,3,23,34,'Mluv synům Izraelským a rci: Každého patnáctého dne měsíce sedmého slavnost stánků za sedm dní bude Hospodinu.'),
(1549628,54,3,23,35,'Dne prvního shromáždění svaté bude; žádného díla robotného nebudete dělati.'),
(1549629,54,3,23,36,'Za sedm dní obětovati budete obět ohnivou Hospodinu. Dne osmého shromáždění svaté míti budete, a obětovati budete obět ohnivou Hospodinu; svátek jest, žádného díla robotného nebudete dělati.'),
(1549630,54,3,23,37,'To jsou slavnosti Hospodinovy, kteréž slaviti budete, mívajíce shromáždění svatá, abyste v nich obětovali obět ohnivou Hospodinu, zápal, obět suchou, obět pokojnou, a oběti mokré, jedno každé ve dni svém,'),
(1549631,54,3,23,38,'Kromě sobot Hospodinových, a kromě darů vašich, i všech slibů vašich a kromě všech dobrovolných obětí vašich, kteréž dávati budete Hospodinu.'),
(1549632,54,3,23,39,'A však dne patnáctého toho měsíce sedmého, když byste shromáždili úrody země, světiti budete svátek Hospodinův za sedm dní. Dne prvního odpočinutí bude, tolikéž dne osmého bude odpočinutí.'),
(1549633,54,3,23,40,'A naberouce sobě dne prvního ovoce z stromů krásných, a ratolestí palmových, a větvoví z stromů hustých, a vrbí od potoku, veseliti se budete před Hospodinem Bohem svým za sedm dní.'),
(1549634,54,3,23,41,'A tak držeti budete ten svátek Hospodinův za sedm dní každého roku. Ustanovení to bude věčné v pronárodech vašich; každého měsíce sedmého slaviti jej budete.'),
(1549635,54,3,23,42,'V staních zůstanete za sedm dní. Kdožkoli doma zrozený jest v Izraeli, v staních zůstávati budete,'),
(1549636,54,3,23,43,'Aby věděli potomci vaši, že jsem choval v staních syny Izraelské, když jsem je vyvedl z země Egyptské: Já Hospodin Bůh váš.'),
(1549637,54,3,23,44,'I oznámil Mojžíš slavnosti Hospodinovy synům Izraelským.'),
(1549638,54,3,24,1,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1549639,54,3,24,2,'Přikaž synům Izraelským, ať přinesou tobě oleje olivového, čistého, vytlačeného, k svícení, aby lampy ustavičně rozsvěcovány byly.'),
(1549640,54,3,24,3,'Před oponou svědectví v stánku úmluvy zpořádá je Aron, aby hořely od večera až do jitra před Hospodinem vždycky. Toť bude ustanovení věčné v národech vašich.'),
(1549641,54,3,24,4,'Na svícen čistý rozstavovati bude lampy před Hospodinem vždycky.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549642,54,3,24,5,'A vezma mouky bělné, upečeš z ní dvanácte koláčů; jeden každý koláč bude ze dvou desetin efi.'),
(1549643,54,3,24,6,'A rozkladeš je dvěma řady, šest v řadu jednom, na stole čistém před Hospodinem.'),
(1549644,54,3,24,7,'Dáš také na každý řad kadidla čistého, aby bylo za každý chléb ten kouření pamětné v obět ohnivou Hospodinu.'),
(1549645,54,3,24,8,'Každého dne sobotního klásti budete je řadem před Hospodinem vždycky, berouce je od synů Izraelských smlouvou věčnou.'),
(1549646,54,3,24,9,'I budou Aronovi a synům jeho, kteřížto jísti budou je na místě svatém; nebo nejsvětější věc jest jim z obětí ohnivých Hospodinových právem věčným.'),
(1549647,54,3,24,10,'Vyšel pak syn ženy Izraelské, kteréhož měla s mužem Egyptským, mezi syny Izraelskými, a vadili se v staních syn ženy té Izraelské s mužem Izraelským.'),
(1549648,54,3,24,11,'I zlořečil syn ženy té Izraelské a rouhal se jménu Božímu. Tedy přivedli ho k Mojžíšovi. (Jméno pak matky jeho bylo Salumit, dcera Dabri, z pokolení Dan.)'),
(1549649,54,3,24,12,'A dali jej do vězení, až by jim bylo oznámeno, co s ním Bůh káže učiniti.'),
(1549650,54,3,24,13,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1549651,54,3,24,14,'Vyveď toho ruhače ven z stanů, a nechať všickni ti, kteříž slyšeli, vloží ruce na hlavu jeho, a všecken lid ať ho ukamenuje.'),
(1549652,54,3,24,15,'Mluvě pak k synům Izraelským, díš jim: Kdož by koli zlořečil Bohu svému, poneseť hřích svůj.'),
(1549653,54,3,24,16,'Kdož by zlořečil jménu Hospodinovu, smrtí umře, a všecko shromáždění bez milosti ukamenuje jej. Tak cizí, jako doma zchovaný, když by zlořečil jménu Hospodinovu, smrtí umře.'),
(1549654,54,3,24,17,'Zabil-li by kdo kterého člověka, smrtí umře.'),
(1549655,54,3,24,18,'Jestliže by pak zabil hovado, navrátí jiné, hovado za hovado.'),
(1549656,54,3,24,19,'Kdož by pak zohavil bližního svého, vedlé toho, jakž on učinil, tak se staň jemu:'),
(1549657,54,3,24,20,'Zlámaní za zlámaní, oko za oko, zub za zub. Jakouž by ohavu učinil na těle člověka, taková zase učiněna bude jemu.'),
(1549658,54,3,24,21,'Kdož by zabil hovado, navrátí jiné, ale kdož by zabil člověka, umře.'),
(1549659,54,3,24,22,'Jednostejné právo míti budete. Jakož příchozímu, tak domácímu stane se; nebo já jsem Hospodin Bůh váš.'),
(1549660,54,3,24,23,'Tedy mluvil Mojžíš k synům Izraelským ty věci. I vyvedli toho ruhače ven za stany, a kamením ho zametali. Učinili, pravím, synové Izraelští vedlé toho, jakož přikázal Hospodin Mojžíšovi.'),
(1549661,54,3,25,1,'Mluvil ještě Hospodin k Mojžíšovi na hoře Sinai, řka:'),
(1549662,54,3,25,2,'Mluv synům Izraelským a rci jim: Když vejdete do země, kterouž já dávám vám, odpočívati bude země, nebo sobota jest Hospodinova.'),
(1549663,54,3,25,3,'Šest let osívati budeš rolí svou, a šest let obřezovati budeš vinici svou a sbírati úrody její.'),
(1549664,54,3,25,4,'Sedmého pak léta sobotu odpočinutí bude míti země, sobotu Hospodinovu; nebudeš na poli svém síti a vinice své řezati.'),
(1549665,54,3,25,5,'Což se samo od sebe zrodí obilí tvého, nebudeš toho žíti, a hroznů vinice zanechané od tebe nebudeš sbírati. Rok odpočinutí bude míti země.'),
(1549666,54,3,25,6,'Ale ovoce země toho odpočinutí budete míti ku pokrmu, ty i služebník tvůj, i děvka tvá, i nájemník tvůj, i příchozí tvůj, kterýž bydlí u tebe,'),
(1549667,54,3,25,7,'I hovado tvé, i všeliký živočich, kterýž jest v zemi tvé, všecky úrody její budou míti ku pokrmu.'),
(1549668,54,3,25,8,'Sečteš také sobě sedm téhodnů let, totiž sedmkrát sedm let, tak aby čas sedmi téhodnů let učinil tobě čtyřidceti devět let.'),
(1549669,54,3,25,9,'Tedy dáš troubiti trubou veselé všudy sedmého měsíce v desátý den; v den očišťování dáš troubiti trubou po vší zemi vaší.'),
(1549670,54,3,25,10,'I posvětíte léta padesátého, a vyhlásíte svobodu v zemi té všechněm obyvatelům jejím. Léto milostivé toto míti budete, abyste se navrátili jeden každý k statku svému, a jeden každý k čeledi své zase přijde.'),
(1549671,54,3,25,11,'Ten rok milostivý padesátého léta míti budete; nebudete síti, ani žíti toho, což by samo od sebe vzrostlo, ani sbírati vína opuštěných vinic léta toho.'),
(1549672,54,3,25,12,'Nebo milostivé léto jest, protož za svaté je míti budete; ze všelikého pole jísti budete úrody jeho.'),
(1549673,54,3,25,13,'Toho léta milostivého navrátí se jeden každý k statku svému.'),
(1549674,54,3,25,14,'Když nějakou věc prodáš bližnímu svému, aneb koupíš něco od bližního svého, nikoli neutiskujte jeden druhého.'),
(1549675,54,3,25,15,'Vedlé počtu let po létu milostivém koupíš od bližního svého, a vedlé počtu let, v kterýchž úrody bráti máš, prodá tobě.'),
(1549676,54,3,25,16,'Čím více bude let, tím větší placení bude, a čím méně let, tím, menší placení bude; nebo počet úrod prodá tobě.'),
(1549677,54,3,25,17,'Protož nikoli neoklamávejte jeden druhého, ale boj se každý Boha svého; nebo já jsem Hospodin Bůh váš.'),
(1549678,54,3,25,18,'Ostříhejte ustanovení mých, a soudy mé zachovávejte a čiňte je, a bydliti budete v zemi té bezpečně.'),
(1549679,54,3,25,19,'A přinese vám země úrody své; i budete jísti až do sytosti, bydlíce bezpečně v ní.'),
(1549680,54,3,25,20,'Pakli díte: Co budeme jísti léta sedmého, jestliže nebudeme síti, ani shromažďovati užitků svých?'),
(1549681,54,3,25,21,'Dám požehnání své vám léta šestého, tak že přinese úrody na tři léta.'),
(1549682,54,3,25,22,'I budete síti léta osmého, a jísti úrody staré až do léta devátého; dokudž by nezrostly úrody jeho, jísti budete staré.'),
(1549683,54,3,25,23,'Země pak nebude prodávána v manství; nebo má jest země, a vy jste příchozí a podruzi u mne.'),
(1549684,54,3,25,24,'A po vší zemi vládařství svého dopustíte dávati výplatu země.'),
(1549685,54,3,25,25,'Jestliže by ochudl bratr tvůj, tak že by prodal něco z statku svého, tedy přijde příbuzný jeho, nejbližší jeho, a vyplatí prodanou věc od bratra svého.'),
(1549686,54,3,25,26,'Pakli kdo nemaje výplatce, mohl by tomu sám dosti učiniti, tak že shledal by, což potřebí k vyplacení:'),
(1549687,54,3,25,27,'Tedy počte léta prodaje svého, a navrátí, což zůstane, tomu, jemuž prodal; tak zase přijde k statku svému.'),
(1549688,54,3,25,28,'Pakli by nemohl shledati toho, což by navrátiti měl, tedy zůstane věc prodaná v rukou toho, kterýž ji koupil, až do léta milostivého. I postoupí mu ji v čas léta milostivého, a on navrátí se zase k dědictví svému.'),
(1549689,54,3,25,29,'Když by kdo prodal dům k bydlení v městě hrazeném, bude míti právo k vyplacení jeho, dokudž nevyplní se rok prodaje jeho. Za celý rok bude míti právo k vyplacení jeho.'),
(1549690,54,3,25,30,'Pakliť ho nevyplatí dříve, než vyjde ten celý rok, tedy zůstane dům ten v městě hrazeném tomu, kterýž jej koupil, dědičně v pronárodech jeho, aniž ho postoupí v létě milostivém.'),
(1549691,54,3,25,31,'Domové pak ve vsech, kteréž nejsou zdí ohrazené, tak jako pole země počítati se budou. Budou moci býti vyplacováni, a léta milostivého navráceni budou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549692,54,3,25,32,'Ale města Levítská, a domové v městech dědictví jejich, ti vždycky vyplaceni mohou býti od Levítů.'),
(1549693,54,3,25,33,'Ten pak, kdož vyplacuje, ať jest z Levítů. Aneb ať vyjde kupec z koupeného domu a města dědictví jeho v čas léta milostivého; nebo domové měst Levítských jsou dědictví jejich mezi syny Izraelskými.'),
(1549694,54,3,25,34,'Pole pak na předměstí měst jejich nebude prodáváno, nebo dědictví jejich věčné jest.'),
(1549695,54,3,25,35,'Jestliže by schudl bratr tvůj, a ustaly by ruce jeho u tebe, posilníš ho; též příchozí aneb podruh živiti se bude při tobě.'),
(1549696,54,3,25,36,'Nevezmeš od něho lichvy aneb úroku, ale báti se budeš Boha svého, aby se mohl bratr tvůj živiti u tebe.'),
(1549697,54,3,25,37,'Peněz svých nedáš jemu na lichvu, aniž pro zisk půjčovati budeš obilí svého.'),
(1549698,54,3,25,38,'Já jsem Hospodin Bůh váš, kterýž jsem vyvedl vás z země Egyptské, abych vám dal zemi Kananejskou, a byl vám za Boha.'),
(1549699,54,3,25,39,'Jestliže by pak schudl bratr tvůj u tebe, tak že by se prodal tobě, nebudeš ho podrobovati v dílo otrocké.'),
(1549700,54,3,25,40,'Jakožto nájemník a jako podruh bude při tobě; až do léta milostivého sloužiti bude u tebe.'),
(1549701,54,3,25,41,'Potom vyjde od tebe s dětmi svými, a navrátí se k čeledi své, a v dědictví otců svých navrátí se.'),
(1549702,54,3,25,42,'Nebo jsou služebníci moji, kteréž jsem vyvedl z země Egyptské; nebudou prodáváni tak jako jiní služebníci.'),
(1549703,54,3,25,43,'Nebudeš panovati nad ním tvrdě, ale báti se budeš Boha svého.'),
(1549704,54,3,25,44,'Služebník pak tvůj aneb děvka tvá, kteréž míti budeš, budou z národů těch, kteříž jsou vůkol vás; z nich kupovati budete služebníky a děvky.'),
(1549705,54,3,25,45,'I od synů bydlitelů, kteříž jsou u vás pohostinu, od těch kupovati budete, a z čeledí těch, kteříž jsou s vámi, kteréž zplodili v zemi vaší, a budou vám v dědictví.'),
(1549706,54,3,25,46,'A vládnouti budete jimi právem dědičným, i synové vaší po vás, abyste je dědičně obdrželi. Na věčnost služby jejich užívati budete, ale nad bratřími svými, syny Izraelskými, nižádný nad bratrem svým nebude tvrdě panovati.'),
(1549707,54,3,25,47,'Jestliže by pak zbohatl příchozí aneb host, kterýž bydlí s tebou, a bratr tvůj přišel by na chudobu při něm, tak že by se prodal příchozímu aneb hosti tvému, aneb obyvateli, kterýž jest z čeledi cizí,'),
(1549708,54,3,25,48,'Když by se tedy prodal, může zase vyplacen býti. Někdo z bratří jeho vyplatí ho.'),
(1549709,54,3,25,49,'Buďto strýc jeho, aneb syn strýce jeho vyplatí jej, aneb někdo z přátel krevních jeho, z rodiny jeho, vyplatí ho; aneb jestli potom sám bude moci s to býti, vyplatí se.'),
(1549710,54,3,25,50,'I počte se s tím, kterýž ho koupil, od léta, v kterémž se jemu prodal, až do léta milostivého, aby peníze, za něž jest prodán, byly vedlé počtu let; a jakožto s nájemníkem, tak se s ním stane.'),
(1549711,54,3,25,51,'Jestliže ještě mnoho let zůstává k létu milostivému, vedlé nich navrátí výplatu svou z peněz, za něž koupen jest.'),
(1549712,54,3,25,52,'Pakli málo zůstává let do léta milostivého, tedy počte se s ním, a vedlé počtu let jeho navrátí výplatu svou.'),
(1549713,54,3,25,53,'Tak jako s čeledínem ročním nakládáno bude s ním; nebude nad ním tvrdě panovati před očima tvýma.'),
(1549714,54,3,25,54,'Pakli by se nevyplatil v těch letech, tedy vyjde léta milostivého on, i synové jeho s ním.'),
(1549715,54,3,25,55,'Nebo synové Izraelští jsou moji služebníci, služebníci moji jsou, kteréž jsem vyvedl z země Egyptské: Já Hospodin Bůh váš.'),
(1549716,54,3,26,1,'Nedělejte sobě modl, ani obrazu rytého, aneb sloupu nevyzdvihnete sobě, ani kamene malovaného v zemi vaší nestavějte, abyste se jemu klaněli; nebo já jsem Hospodin Bůh váš.'),
(1549717,54,3,26,2,'Sobot mých ostříhejte, a svatyně mé se bojte: Já jsem Hospodin.'),
(1549718,54,3,26,3,'Jestliže v ustanoveních mých choditi budete, a přikázaní mých ostříhajíce, budete je činiti:'),
(1549719,54,3,26,4,'Tedy dám vám deště vaše časy svými, a země vydá úrody své, a stromoví polní vydá ovoce své,'),
(1549720,54,3,26,5,'Tak že mlácení postihne vinobraní, a vinobraní postihne setí. I budete jísti chléb svůj do sytosti, a přebývati budete bezpečně v zemi své.'),
(1549721,54,3,26,6,'Nebo dám pokoj v zemi, i budete spáti, a nebude, kdo by vás předěsil; vypléním i zvěř zlou z země, a meč nebude procházeti země vaší.'),
(1549722,54,3,26,7,'Nýbrž honiti budete nepřátely své, a padnou před vámi od meče.'),
(1549723,54,3,26,8,'Pět vašich honiti jich bude sto, a sto vašich honiti bude deset tisíců, i padnou nepřátelé vaši před vámi od meče.'),
(1549724,54,3,26,9,'Nebo obrátím tvář svou k vám, a dám vám zrůst, a rozmnožím vás, a utvrdím smlouvu svou s vámi.'),
(1549725,54,3,26,10,'A jísti budete úrody několikaleté, a když nové přijdou, staré vyprázdníte.'),
(1549726,54,3,26,11,'Vzdělám příbytek svůj u prostřed vás, a duše má nebude vás nenáviděti.'),
(1549727,54,3,26,12,'A procházeti se budu mezi vámi, a budu Bohem vaším, a vy budete lidem mým.'),
(1549728,54,3,26,13,'Já jsem Hospodin Bůh váš, kterýž jsem vyvedl vás z země Egyptských, abyste jim nesloužili, a polámal jsem závory jha vašeho, abyste chodili prosti.'),
(1549729,54,3,26,14,'Pakli nebudete mne poslouchati, a nebudete činiti všech přikázaní těchto,'),
(1549730,54,3,26,15,'A jestli ustanovení má zavržete, a soudy mé zoškliví-li sobě duše vaše, tak abyste nečinili všech přikázaní mých, a zrušili byste smlouvu mou:'),
(1549731,54,3,26,16,'Já také toto učiním vám: Uvedu na vás strach, souchotiny a zimnici pálčivou, což zkazí oči vaše, a bolestí naplní duši. Semeno své nadarmo síti budete, nebo nepřátelé vaši snědí je.'),
(1549732,54,3,26,17,'Postavím zůřivou tvář svou proti vám, tak že poraženi budete od nepřátel svých, a panovati budou nad vámi ti, kteříž vás nenávidí. Utíkati budete, ano vás žádný nehoní.'),
(1549733,54,3,26,18,'Jestliže ani tak poslouchati mne nebudete, tedy ještě sedmkrát více trestati vás budu pro hříchy vaše.'),
(1549734,54,3,26,19,'A potru vyvýšenost síly vaší, a učiním nebe nad vámi jako železo, a zemi vaši jako měď.'),
(1549735,54,3,26,20,'Nadarmo bude vynaložena síla vaše, nebo země vaše nevydá vám úrody své, a stromoví země nevydá ovoce svého.'),
(1549736,54,3,26,21,'Jestliže pak se mnou maní zacházeti budete, a nebudete mne chtíti poslouchati, tedy přidám na vás sedmkrát více ran vedlé hříchů vašich.'),
(1549737,54,3,26,22,'A pustím na vás zvěř polní, kteráž uvede na vás sirobu, a vyhubí hovada vaše a umenší vás; i zpustnou cesty vaše.'),
(1549738,54,3,26,23,'Pakli ani potom nenapravíte se, ale vždy se mnou maní zacházeti budete,'),
(1549739,54,3,26,24,'I já s vámi maní zacházeti budu, a bíti vás budu sedmkrát více pro hříchy vaše.'),
(1549740,54,3,26,25,'A uvedu na vás meč, kterýž vrchovatě pomstí zrušení smlouvy. I shrnete se do měst svých; tam pošli mor mezi vás, a dáni budete v ruce nepřátelům.'),
(1549741,54,3,26,26,'A když polámi vám hůl chleba, tedy deset žen péci bude chléb váš v peci jedné, a zase chléb váš odvažovati vám budou. Budete pak jísti, a nenasytíte se.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549742,54,3,26,27,'Pakli i s tím nebudete mne poslouchati, ale předce maní se mnou zacházeti budete:'),
(1549743,54,3,26,28,'I já také v hněvě maní s vámi zacházeti budu, a trestati vás budu i já sedmkrát více pro hříchy vaše.'),
(1549744,54,3,26,29,'A budete jísti těla synů svých, a těla dcer svých.'),
(1549745,54,3,26,30,'A zkazím výsosti vaše, a vypléním slunečné obrazy vaše, a skladu těla vaše na špalky ukydaných bohů vašich, a duše má bude vás nenáviděti.'),
(1549746,54,3,26,31,'Města vaše dám v zpuštění, a učiním, aby zpustly svatyně vaše, aniž více zachutnám oběti vůně příjemné vaší.'),
(1549747,54,3,26,32,'Já zpustím zemi, tak že ztrnou nad ní nepřátelé vaši, kteříž bydliti budou v ní.'),
(1549748,54,3,26,33,'Vás pak rozptýlím mezi národy, a učiním, aby s dobytým mečem vás honili. I bude země vaše vyhubena, a města vaše zpustnou.'),
(1549749,54,3,26,34,'A tehdy země užive sobot svých po všecky dny, v nichž pustá bude, vy pak budete v zemi nepřátel svých. Tehdáž, pravím, odpočine země, a užive sobot svých.'),
(1549750,54,3,26,35,'Po všecky dny, v nichž pustá bude, odpočívati bude; nebo neodpočívala v soboty vaše, když jste vy bydlili v ní.'),
(1549751,54,3,26,36,'Kteříž pak ještě pozůstanou z vás, uvedu strach na srdce jejich v krajinách nepřátel jejich, tak že zažene je chřest listu větrem chřestícího. I budou utíkati, rovně jako před mečem, a padnou, an jich žádný honiti nebude.'),
(1549752,54,3,26,37,'A budou padati jeden přes druhého jakožto od meče, ač jich žádný honiti nebude; aniž kdo z vás bude moci ostáti před nepřátely svými.'),
(1549753,54,3,26,38,'I zahynete mezi národy, a zžíře vás země nepřátel vašich.'),
(1549754,54,3,26,39,'Kteříž pak pozůstanou z vás, svadnouti budou pro nepravost svou v zemi nepřátel vašich, ano i pro nepravosti otců vašich s nimi usvadnou.'),
(1549755,54,3,26,40,'Ale jestliže budou vyznávati nepravost svou, a nepravost otců svých vedlé přestoupení svého, kterýmž přestoupili proti mně, a maní se mnou zacházeli,'),
(1549756,54,3,26,41,'I já také že jsem maní s nimi zacházel, a uvedl je do země nepřátel jejich; jestliže, pravím, tehdáž poníží se srdce jejich neobřezané, a schválí pokutu nepravosti své:'),
(1549757,54,3,26,42,'Tedy rozpomenu se na smlouvu svou s Jákobem, a na smlouvu svou s Izákem, i na smlouvu svou s Abrahamem rozpomenu se; také i na tu zemi pamětliv budu.'),
(1549758,54,3,26,43,'Mezi tím země jsuc jich zbavena, užive sobot svých, kdyžto zpuštěna bude pro ně. Tehdáž oni schválí pokutu nepravosti své proto, že všelijak soudy mými pohrdali, a ustanovení má zošklivila sobě duše jejich.'),
(1549759,54,3,26,44,'A však i tak, když by v zemi nepřátel svých byli, nezavrhl bych jich, a nezošklivil jich sobě, abych je měl do konce zkaziti, a zrušiti smlouvu svou s nimi; nebo já jsem Hospodin Bůh jejich.'),
(1549760,54,3,26,45,'Ale rozpomenu se na ně pro smlouvu učiněnou s předky jejich, kteréž jsem vyvedl z země Egyptské před očima pohanů, abych jim byl za Boha: Já Hospodin.'),
(1549761,54,3,26,46,'Ta jsou ustanovení a soudové, i zákonové, kteréž vydal Hospodin na hoře Sinai skrze Mojžíše, aby byli mezi ním a mezi syny Izraelskými.'),
(1549762,54,3,27,1,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1549763,54,3,27,2,'Mluv synům Izraelským a rci jim: Když by kdo slibem oddal duše Hospodinu, vedlé ceny tvé dá výplatu.'),
(1549764,54,3,27,3,'Tato pak bude cena tvá: Osobě mužského pohlaví, počna od toho, kterýž jest ve dvadcíti letech, až do šedesátiletého, uložíš výplatu padesáte lotů stříbra vedlé lotu svatyně.'),
(1549765,54,3,27,4,'Pakli ženského pohlaví bude, uložíš výplatu třidceti lotů.'),
(1549766,54,3,27,5,'A od pětiletých až do dvadcítiletých uložíš výplatu, za osobu mužského pohlaví dvadceti lotů, ženského pak deset lotů.'),
(1549767,54,3,27,6,'A od dítěte jednoho měsíce zstáří až do pětiletých, uložíš za pachole pět lotů stříbra, a za děvče tři loty stříbra.'),
(1549768,54,3,27,7,'Od šedesáti pak let a výše, bude-li muž, uložíš výplatu patnácte lotů, a ženě deset lotů.'),
(1549769,54,3,27,8,'Pakli bude tak chudý, že by nemohl uložené výplaty dáti, tedy postaven bude před knězem, aby mu kněz uložil výplatu. Podlé toho, seč bude moci býti ten, kdož slib učinil, uloží mu výplatu.'),
(1549770,54,3,27,9,'Jestliže by pak kdo hovado z těch, kteréž se obětují Hospodinu, slíbil, každé, kteréž dá z nich Hospodinu, svaté bude.'),
(1549771,54,3,27,10,'Nesmění ho, aniž dá jiného za ně, lepšího za horší, aneb horšího za lepší. Jestliže by pak jakýmkoli způsobem je směnil, hovado za hovado, tedy ono i toto, kteréž za ně dáno, svaté bude.'),
(1549772,54,3,27,11,'Pakli by které nečisté hovado slíbil, z jehož pokolení neobětují oběti Hospodinu, tedy postaví to hovado před knězem.'),
(1549773,54,3,27,12,'A bude je šacovati kněz, buď ono dobré aneb zlé. Jakž je kněz cení, tak buď.'),
(1549774,54,3,27,13,'Pakli bude chtíti vyplatiti je, přidá pátý díl nad cenu tvou.'),
(1549775,54,3,27,14,'Když by pak někdo posvětil domu svého, aby byl svatý Hospodinu, bude jej kněz ceniti, buďto že by dobrý byl aneb zlý. Jakž jej procení kněz, tak zůstane.'),
(1549776,54,3,27,15,'Pakli ten, kterýž posvětil domu svého, chtěl by jej vyplatiti, přidá pátý díl peněz nad cenu tvou, i bude jeho.'),
(1549777,54,3,27,16,'Jestliže by kdo díl pole dědictví svého posvětil Hospodinu, tedy budeš je ceniti vedlé toho, jakž se osívá. Chomer ječmene kde se vseje, za padesáte lotů stříbra ceněno bude.'),
(1549778,54,3,27,17,'Jestliže by hned od léta milostivého posvětil pole svého, tedy vedlé ceny tvé zůstane.'),
(1549779,54,3,27,18,'Pakli by po létě milostivém posvětil pole svého, tedy sečte mu kněz peníze vedlé počtu let zůstávajících ještě do léta milostivého, i odejme to z ceny tvé.'),
(1549780,54,3,27,19,'Chtěl-li by pak vyplatiti pole ten, kterýž ho posvětil, přidá pátý díl peněz nad cenu tvou, a zůstane jemu.'),
(1549781,54,3,27,20,'Nevyplatil-li by pak pole toho, a prodáno by bylo někomu jinému, nemůže víc vyplaceno býti.'),
(1549782,54,3,27,21,'I bude pole to, když svobodné vyjde léta milostivého, svaté Hospodinovo, jakožto pole posvěcené; knězi bude v dědictví jeho.'),
(1549783,54,3,27,22,'Jestliže pak pole koupené, kteréž by nebylo z pole dědictví jeho, posvětil Hospodinu,'),
(1549784,54,3,27,23,'Tedy sečte mu kněz summu ceny jeho až do léta milostivého, i dá cenu jeho v ten den, jako posvěcenou Hospodinu.'),
(1549785,54,3,27,24,'V létě milostivém navrátí se pole k tomu, od kohož bylo koupeno, jehož dědictví jest pole to.'),
(1549786,54,3,27,25,'Všeliká pak cena tvá bude vedlé lotu svatyně. Lot pak váží dvadceti haléřů.'),
(1549787,54,3,27,26,'Ale prvorozeného, což právem prvorozenství dává se Hospodinu z hovad, nižádný neposvětí, buďto z skotů aneb z bravů; Hospodinovo jest prvé.'),
(1549788,54,3,27,27,'A jestliže by z hovad nečistých bylo, vyplatí je vedlé ceny tvé, a přidá pátý díl nad ní. Pakliť nebude vyplaceno, tedy nechť jest prodáno vedlé ceny tvé.'),
(1549789,54,3,27,28,'Všeliká pak věc posvěcená, kterouž by někdo slibem posvětil Hospodinu ze všech věcí, kteréž má, buď z lidí aneb z hovad, aneb z pole dědictví svého, nebude prodávána, ani vyplacována; nebo všecko, což takovým slibem posvěceno jest, věc nejsvětější bude Hospodinu.'),
(1549790,54,3,27,29,'Všeliké hovado tak oddané, kteréž slibem tím se oddává od člověka, nebude vyplacováno, ale smrtí umře.'),
(1549791,54,3,27,30,'Všickni také desátkové země, buď z semene země, aneb z ovoce stromů, Hospodinovi budou; nebo posvěceni jsou Hospodinu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549792,54,3,27,31,'Bude-li kdo chtíti vyplatiti desátky své, pátý díl jejich přidá nad ně.'),
(1549793,54,3,27,32,'A všeliký desátek z volů aneb drobného dobytka, jakž přichází pod hůl pastýře, každý ten desátek svatý bude Hospodinu.'),
(1549794,54,3,27,33,'Nebude vyhledávati, dobré-li by bylo čili zlé, aniž ho smění. Pakli je předce smění, bude to i ono odměněné svaté, a nebude vyplaceno.'),
(1549795,54,3,27,34,'Ta jsou přikázaní, kteráž přikázal Hospodin Mojžíšovi na hoře Sinai, aby je oznámil synům Izraelským.'),
(1549796,54,4,1,1,'Mluvil pak Hospodin k Mojžíšovi na poušti Sinai, v stánku úmluvy, prvního dne měsíce druhého, léta druhého po vyjití jejich z země Egyptské, řka:'),
(1549797,54,4,1,2,'Sečtěte summu všeho množství synů Izraelských po čeledech jejich, a po domích otců jejich, vedlé počtu jmen každého pohlaví mužského po hlavách jejich,'),
(1549798,54,4,1,3,'Od dvadcítiletých a výše všecky, kteříž by mohli jíti k boji v Izraeli, sečtěte je po houfích jejich, ty a Aron.'),
(1549799,54,4,1,4,'A bude s vámi z každého pokolení jeden muž, kterýž by přední byl v domě otců svých.'),
(1549800,54,4,1,5,'Tato pak jsou jména mužů, kteříž stanou s vámi: Z pokolení Rubenova Elisur, syn Sedeurův;'),
(1549801,54,4,1,6,'Z Simeonova Salamiel, syn Surisaddai;'),
(1549802,54,4,1,7,'Z Judova Názon, syn Aminadabův;'),
(1549803,54,4,1,8,'Z Izacharova Natanael, syn Suar;'),
(1549804,54,4,1,9,'Z Zabulonova Eliab, syn Helonův;'),
(1549805,54,4,1,10,'Z synů Jozefových, z pokolení Efraimova Elisama, syn Amiudův; z Manassesova Gamaliel, syn Fadasurův;'),
(1549806,54,4,1,11,'Z Beniaminova Abidan, syn Gedeonův;'),
(1549807,54,4,1,12,'Z pokolení Dan Ahiezer, syn Amisaddai;'),
(1549808,54,4,1,13,'Z Asser Fegiel, syn Ochranův;'),
(1549809,54,4,1,14,'Z pokolení Gád Eliazaf, syn Duelův;'),
(1549810,54,4,1,15,'Z Neftalímova Ahira, syn Enanův.'),
(1549811,54,4,1,16,'Ti jsou slovoutní z lidu, knížata pokolení otců svých, ti jako hlavy tisíců Izraelských budou.'),
(1549812,54,4,1,17,'Vzal tedy Mojžíš a Aron muže ty, kteříž jmenováni byli,'),
(1549813,54,4,1,18,'A shromáždili všecko množství prvního dne měsíce druhého, kteříž přiznávali se k rodům svým po čeledech svých, po domích otců svých, a vedlé počtu jmen, od dvadcítiletých a výše po osobách svých.'),
(1549814,54,4,1,19,'Jakož byl přikázal Hospodin Mojžíšovi, tak sčetl je na poušti Sinai.'),
(1549815,54,4,1,20,'I bylo synů Rubena prvorozeného Izraelova, rodiny jejich, po čeledech jejich, po domích otců jejich, a podlé počtu jmen, po hlavách jejich, všech pohlaví mužského, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,'),
(1549816,54,4,1,21,'A načteno jich z pokolení Rubenova čtyřidceti šest tisíců a pět set.'),
(1549817,54,4,1,22,'Z synů Simeonových, rodiny jejich, po čeledech jejich, po domích otců jejich, sečtených jeho vedlé počtu jmen, po hlavách jejich, všech pohlaví mužského od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,'),
(1549818,54,4,1,23,'Načteno jich z pokolení Simeonova padesáte devět tisíců a tři sta.'),
(1549819,54,4,1,24,'Z synů Gádových, rodiny jejich, po čeledech jejich, po domích otců jejich, podlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli bojovati,'),
(1549820,54,4,1,25,'Načteno jich z pokolení Gádova čtyřidceti pět tisíců, šest set a padesát.'),
(1549821,54,4,1,26,'Z synů Judových, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcíti let a výše, všech, kteříž mohli jíti k boji,'),
(1549822,54,4,1,27,'Načteno jich z pokolení Judova sedmdesáte čtyři tisíce a šest set.'),
(1549823,54,4,1,28,'Z synů Izacharových, rodiny jejich, po čeledech jejich, po domích otců jejich, podlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,'),
(1549824,54,4,1,29,'Načteno jich z pokolení Izacharova padesáte čtyři tisíce a čtyři sta.'),
(1549825,54,4,1,30,'Z synů Zabulonových, rodiny jejich, po čeledech jejich, po domích otců jejich, podlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,'),
(1549826,54,4,1,31,'Načteno jich z pokolení Zabulonova padesáte sedm tisíců a čtyři sta.'),
(1549827,54,4,1,32,'Z synů Jozefových, a nejprv, synů Efraimových, rodiny jejich, po čeledech jejich, po domích otců jejich, podlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,'),
(1549828,54,4,1,33,'Načteno jich z pokolení Efraimova čtyřidceti tisíc a pět set.'),
(1549829,54,4,1,34,'Potom z synů Manassesových, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž vycházeli k boji,'),
(1549830,54,4,1,35,'Načteno jich z pokolení Manassesova třidceti dva tisíce a dvě stě.'),
(1549831,54,4,1,36,'Z synů Beniaminových, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti do boje,'),
(1549832,54,4,1,37,'Načteno jich z pokolení Beniaminova třidceti pět tisíců a čtyři sta.'),
(1549833,54,4,1,38,'Z synů Dan, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž vycházeli k boji,'),
(1549834,54,4,1,39,'Načteno jich z pokolení Dan šedesáte dva tisíce a sedm set.'),
(1549835,54,4,1,40,'Z synů Asser, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti na vojnu,'),
(1549836,54,4,1,41,'Načteno jich z pokolení Asser čtyřidceti jeden tisíců a pět set.'),
(1549837,54,4,1,42,'Z synů Neftalímových, rodiny jejich, po čeledech jejich, po domích otců jejich, vedlé počtu jmen, od dvadcítiletých a výše, všech, kteříž mohli jíti k boji,'),
(1549838,54,4,1,43,'Načteno jich z pokolení Neftalímova padesáte tři tisíce a čtyři sta.'),
(1549839,54,4,1,44,'Ten jest počet těch, kteréž sečtl Mojžíš a Aron a knížata Izraelská, dvanácte mužů, kteříž byli vybráni po jednom z domů otců svých.'),
(1549840,54,4,1,45,'I bylo všech sečtených synů Izraelských po domích otců jejich, od dvadcítiletých a výše, všech, kteříž mohli vycházeti k boji v Izraeli,'),
(1549841,54,4,1,46,'Všech sečtených bylo šestkrát sto tisíc, a tři tisíce, pět set a padesáte.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549842,54,4,1,47,'Levítové pak vedlé pokolení otců svých nejsou počítáni mezi ně.'),
(1549843,54,4,1,48,'Nebo byl mluvil Hospodin k Mojžíšovi, řka:'),
(1549844,54,4,1,49,'Pokolení Levítského nebudeš počítati, a nepřičteš jich k synům Izraelským,'),
(1549845,54,4,1,50,'Ale ustanovíš Levíty nad příbytkem svědectví, a nade vším nádobím jeho, a nade všemi věcmi, kteréž přináležejí k němu. Oni nositi budou příbytek i všecka nádobí jeho, oni přisluhovati budou jemu, a vůkol příbytku klásti se budou.'),
(1549846,54,4,1,51,'Když se pak s místa bude míti hýbati příbytek, složí jej Levítové; a když se bude klásti příbytek, vyzdvihnou jej Levítové. Kdož by koli cizí přistoupil, umře.'),
(1549847,54,4,1,52,'I budouť se klásti synové Izraelští, jeden každý v ležení svém, a jeden každý pod praporcem svým, a po houfích svých.'),
(1549848,54,4,1,53,'Levítové pak klásti se budou vůkol příbytku svědectví, aby nepřišlo rozhněvání mé na shromáždění synů Izraelských; i budou Levítové držeti stráž u příbytku svědectví.'),
(1549849,54,4,1,54,'Učinili tedy to synové Izraelští; všecko, jakž přikázal Hospodin Mojžíšovi, tak učinili.'),
(1549850,54,4,2,1,'Mluvil také Hospodin k Mojžíšovi a Aronovi, řka:'),
(1549851,54,4,2,2,'Synové Izraelští klásti se budou jeden každý pod korouhví svou, při praporci domu otců svých; vůkol stánku úmluvy opodál klásti se budou.'),
(1549852,54,4,2,3,'Tito pak rozbijí stany k východní straně: Korouhev vojska Judova po houfích svých, a kníže synů Juda Názon, syn Aminadabův,'),
(1549853,54,4,2,4,'A u vojště jeho lidu sečteného sedmdesáte čtyři tisíce a šest set.'),
(1549854,54,4,2,5,'Podlé něho pak položí se pokolení Izachar, a kníže synů Izachar Natanael, syn Suar,'),
(1549855,54,4,2,6,'A u vojště jeho lidu sečteného padesáte čtyři tisíce a čtyři sta.'),
(1549856,54,4,2,7,'Pokolení Zabulon podlé nich, a kníže synů Zabulon Eliab, syn Helonův,'),
(1549857,54,4,2,8,'A u vojště jeho lidu sečteného padesáte sedm tisíců a čtyři sta.'),
(1549858,54,4,2,9,'Summa všech sečtených u vojště Judově sto osmdesáte šest tisíců a čtyři sta, po houfích jejich. Ti napřed potáhnou.'),
(1549859,54,4,2,10,'Korouhev vojska Rubenova klásti se bude ku poledni po houfích svých, a kníže synů Ruben Elisur, syn Sedeurův,'),
(1549860,54,4,2,11,'A u vojště jeho lidu sečteného čtyřidceti šest tisíců a pět set.'),
(1549861,54,4,2,12,'Podlé něho pak položí se pokolení Simeonovo, a kníže synů Simeon Salamiel, syn Surisaddai,'),
(1549862,54,4,2,13,'A u vojště jeho lidu sečteného padesáte devět tisíců a tři sta.'),
(1549863,54,4,2,14,'Potom pokolení Gád, a kníže synů Gád Eliazaf, syn Ruelův,'),
(1549864,54,4,2,15,'A u vojště jeho lidu sečteného čtyřidceti pět tisíců, šest set a padesáte.'),
(1549865,54,4,2,16,'Summa všech sečtených u vojště Rubenově sto padesáte a jeden tisíců, čtyři sta a padesáte, po houfích svých. A ti za prvními potáhnou.'),
(1549866,54,4,2,17,'Potom půjde stánek úmluvy s vojskem Levítů u prostřed všeho vojska. Jakýmž pořádkem klásti se budou, takovým potáhnou, každý v svém šiku pod korouhví svou.'),
(1549867,54,4,2,18,'Korouhev vojska Efraimova po houfích svých bude k západu, a kníže synů Efraimových Elisama, syn Amiudův,'),
(1549868,54,4,2,19,'A u vojště jeho lidu sečteného čtyřidceti tisíc a pět set.'),
(1549869,54,4,2,20,'Podlé něho pak položí se pokolení Manassesovo, a kníže synů Manassesových Gamaliel, syn Fadasurův,'),
(1549870,54,4,2,21,'A u vojště jeho lidu sečteného třidceti dva tisíce a dvě stě.'),
(1549871,54,4,2,22,'Potom položí se pokolení Beniaminovo, a kníže synů Beniamin Abidan, syn Gedeonův,'),
(1549872,54,4,2,23,'A u vojště jeho lidu sečteného třidceti pět tisíců a čtyři sta.'),
(1549873,54,4,2,24,'Summa všech sečtených u vojště Efraimově sto osm tisíců a sto osob, po houfích jejich. A tito za druhými potáhnou.'),
(1549874,54,4,2,25,'Korouhev vojska Dan bude k straně půlnoční, po houfích svých, a kníže synů Dan Ahiezer, syn Amisaddai,'),
(1549875,54,4,2,26,'A u vojště jeho lidu sečteného šedesáte dva tisíce a sedm set.'),
(1549876,54,4,2,27,'Podlé něho položí se pokolení Asser, a kniže Asser Fegiel, syn Ochranův,'),
(1549877,54,4,2,28,'A u vojště jeho lidu sečteného čtyřidceti jeden tisíc a pět set.'),
(1549878,54,4,2,29,'Za nimi pokolení Neftalímovo, a kníže synů Neftalímových Ahira, syn Enanův,'),
(1549879,54,4,2,30,'A u vojště jeho lidu sečteného padesáte tři tisíce a čtyři sta.'),
(1549880,54,4,2,31,'Summa všech sečtených u vojště Dan sto padesáte sedm tisíců a šest set. Oni nazad potáhnou při praporcích svých.'),
(1549881,54,4,2,32,'Ta jest summa synů Izraelských po domích otců jejich, všech sečtených v celém vojště po houfích jejich, šestkrát sto tisíců, tři tisíce, pět set a padesáte.'),
(1549882,54,4,2,33,'Levítové pak nejsou počítáni mezi syny Izraelské, jakož přikázal Hospodin Mojžíšovi.'),
(1549883,54,4,2,34,'I učinili synové Izraelští všecko; jakž přikázal Hospodin Mojžíšovi, tak rozbijeli stany při korouhvech svých, a tak táhli jeden každý po čeledech svých a po domích otců svých.'),
(1549884,54,4,3,1,'Tito jsou příběhové Aronovi a Mojžíšovi od toho dne, když mluvil Hospodin s Mojžíšem na hoře Sinai.'),
(1549885,54,4,3,2,'A tato jsou jména synů Aronových: Prvorozený Nádab, potom Abiu, Eleazar a Itamar.'),
(1549886,54,4,3,3,'Ta jsou jména synů Aronových, kněží pomazaných, jejichžto ruce naplněny, aby úřad kněžství konali.'),
(1549887,54,4,3,4,'Umřel pak Nádab a Abiu před Hospodinem, když obětovali cizí oheň před Hospodinem na poušti Sinai, a neměli synů. Protož konal úřad kněžský Eleazar a Itamar před tváří Arona otce svého.'),
(1549888,54,4,3,5,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1549889,54,4,3,6,'Rozkaž přistoupiti pokolení Léví, a postav je před Aronem knězem, aby mu přisluhovali,'),
(1549890,54,4,3,7,'A drželi stráž jeho, i stráž všeho množství před stánkem úmluvy k vykonávání služby příbytku,'),
(1549891,54,4,3,8,'Též aby ostříhali všeho nádobí stánku úmluvy, a drželi stráž synů Izraelských a konali služby příbytku.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549892,54,4,3,9,'Dáš tedy Levíty Aronovi i synům jeho; vlastně dáni jsou mu oni z synů Izraelských.'),
(1549893,54,4,3,10,'Arona pak a syny jeho představíš, aby ostříhali kněžství svého; nebo přistoupil-li by kdo cizí, umře.'),
(1549894,54,4,3,11,'I mluvil Hospodin Mojžíšovi, řka:'),
(1549895,54,4,3,12,'Aj, já vzal jsem Levíty z prostředku synů Izraelských na místo všelikého prvorozeného, kteréž otvírá život mezi syny Izraelskými. Protož moji budou Levítové.'),
(1549896,54,4,3,13,'Nebo mně přináleží všecko prvorozené. Od toho dne, když jsem pobil všecko prvorozené v zemi Egyptské, posvětil jsem sobě všeho prvorozeného v Izraeli od člověka až do hovada. Mně bude: Já Hospodin.'),
(1549897,54,4,3,14,'Mluvil také Hospodin k Mojžíšovi na poušti Sinai, řka:'),
(1549898,54,4,3,15,'Sečti syny Léví vedlé domů otců jejich, po čeledech jejich, každého pohlaví mužského; zstáří jednoho měsíce a výše počítati budeš je.'),
(1549899,54,4,3,16,'I sčetl je Mojžíš podlé řeči Hospodinovy, jakž rozkázáno mu bylo.'),
(1549900,54,4,3,17,'I byli synové Léví ze jména tito: Gerson, Kahat a Merari.'),
(1549901,54,4,3,18,'Tato pak jsou jména synů Gersonových po čeledech jejich: Lebni a Semei.'),
(1549902,54,4,3,19,'A synové Kahat po čeledech svých: Amram a Izar, Hebron a Uziel.'),
(1549903,54,4,3,20,'Synové pak Merari po čeledech svých: Moholi a Musi. Ty jsou čeledi Léví vedlé domů otců svých.'),
(1549904,54,4,3,21,'Od Gersona čeled Lebnitská a čeled Semejská. Ty jsou čeledi Gersonovy.'),
(1549905,54,4,3,22,'A načteno jich v počtu všech pohlaví mužského zstáří jednoho měsíce a výše sedm tisíců a pět set.'),
(1549906,54,4,3,23,'Čeledi Gersonovy za příbytkem klásti se budou k straně západní.'),
(1549907,54,4,3,24,'Kníže pak domu otce Gersonitských bude Eliazaf, syn Laelův.'),
(1549908,54,4,3,25,'A k opatrování synům Gersonovým při stánku úmluvy náležeti bude příbytek i stánek, přikrytí jeho i zastření dveří stánku úmluvy,'),
(1549909,54,4,3,26,'A očkovaté koltry k síni, i zavěšení dveří síně, kteráž jest před příbytkem a při oltáři vůkol, i provazové jeho ke všeliké potřebě jeho.'),
(1549910,54,4,3,27,'Od Kahat pak pošla čeled Amramitská a čeled Izaritská, a čeled Hebronitská, a čeled Uzielitská. Ty jsou čeledi Kahat.'),
(1549911,54,4,3,28,'V počtu všech pohlaví mužského zstáří jednoho měsíce a výše bylo osm tisíců a šest set, držících stráž při svatyni.'),
(1549912,54,4,3,29,'Čeledi synů Kahat klásti se budou k straně příbytku polední,'),
(1549913,54,4,3,30,'A kníže domu otcovského v čeledech Kahat Elizafan, syn Uzielův.'),
(1549914,54,4,3,31,'V jejich pak opatrování bude truhla, stůl, svícen, oltářové a nádobí svatyně, jímž přisluhovati budou, a opona i všecko, což přináleží k ní.'),
(1549915,54,4,3,32,'Kníže pak nad knížaty Levítskými Eleazar, syn Arona kněze, ustavený nad těmi, kteříž drží stráž při svatyni.'),
(1549916,54,4,3,33,'Od Merari pak čeled Moholitská a čeled Musitská. Ty jsou čeledi Merari.'),
(1549917,54,4,3,34,'A načteno jich v počtu všech mužského pohlaví zstáří jednoho měsíce a výše šest tisíců a dvě stě.'),
(1549918,54,4,3,35,'A kníže domu otcovského v čeledech Merari Suriel, syn Abichailův. A ti klásti se budou k straně příbytku půlnoční.'),
(1549919,54,4,3,36,'Toto pak poručeno k opatrování synům Merari: Dsky příbytku a svlakové jeho, sloupové a podstavkové a všecka nádobí jeho i všecka práce při nich,'),
(1549920,54,4,3,37,'Tolikéž sloupové síně vůkol i podstavkové jejich, kolíkové i provazové jejich.'),
(1549921,54,4,3,38,'Položí se pak před příbytkem po přední straně před stánkem úmluvy od východu slunce Mojžíš a Aron i synové jeho, držíce stráž při svatyni, stráž za syny Izraelské. Jiný přistoupil-li by kdo, umře.'),
(1549922,54,4,3,39,'Všech sečtených Levítů, kteréž sečtl Mojžíš s Aronem vedlé poručení Hospodinova, po čeledech jejich, všech pohlaví mužského jednoho měsíce zstáří a výše dvamecítma tisíců.'),
(1549923,54,4,3,40,'I řekl Hospodin k Mojžíšovi: Sečti všecky prvorozené mužského pohlaví mezi syny Izraelskými jednoho měsíce zstáří a výše, a sečti summu jmen jejich.'),
(1549924,54,4,3,41,'A vezmeš mi Levíty, (jáť jsem Hospodin), místo všech prvorozených mezi syny Izraelskými, i hovada Levítů místo všeho prvorozeného mezi hovady synů Izraelských.'),
(1549925,54,4,3,42,'Když pak sčetl Mojžíš, jakož mu přikázal Hospodin, všecky prvorozené mezi syny Izraelskými,'),
(1549926,54,4,3,43,'Bylo všech prvorozených pohlaví mužského vedlé počtu jmen, jednoho měsíce zstáří a výše sečtených jich, dvamecítma tisíců, dvě stě, sedmdesáte a tři.'),
(1549927,54,4,3,44,'A mluvil Hospodin k Mojžíšovi, řka:'),
(1549928,54,4,3,45,'Vezmi Levíty místo všech prvorozených z synů Izraelských, i hovada Levítů za hovada jejich; i budou moji Levítové: Já jsem Hospodin.'),
(1549929,54,4,3,46,'K vyplacení pak těch dvou set, sedmdesáti a tří, kteříž zbývají nad počet Levítů z prvorozených synů Izraelských,'),
(1549930,54,4,3,47,'Vezmeš pět lotů z každé hlavy, (vedlé lotu svatyně bráti budeš, lot pak dvadceti haléřů váží),'),
(1549931,54,4,3,48,'A dáš ty peníze Aronovi a synům jeho, výplatu těch, kteříž zbývají nad počet jejich.'),
(1549932,54,4,3,49,'Vzal tedy Mojžíš peníze výplaty od těch, kteříž zbývali, kromě těch, kteréž vykoupili sebou Levítové,'),
(1549933,54,4,3,50,'Od prvorozených synů Izraelských vzal peněz tisíc, tři sta, šedesáte pět lotů, vedlé lotu svatyně.'),
(1549934,54,4,3,51,'I dal ty peníze výplaty Aronovi a synům jeho, podlé řeči Hospodinovy, jakož byl přikázal jemu Hospodin.'),
(1549935,54,4,4,1,'I mluvil Hospodin k Mojžíšovi a k Aronovi, řka:'),
(1549936,54,4,4,2,'Sečti summu synů Kahat z prostředku synů Léví po čeledech jejich a po domích otců jejich,'),
(1549937,54,4,4,3,'Od třidcítiletých a výše až do padesátiletých, kteříž by způsobní jsouce k boji, mohli práci vésti při stánku úmluvy.'),
(1549938,54,4,4,4,'Tato pak bude práce synů Kahat při stánku úmluvy svatyně svatých:'),
(1549939,54,4,4,5,'Když by se měla vojska hnouti s místa, přijde Aron s syny svými a sejmou oponu zastření, a přikryjí ní truhlu svědectví.'),
(1549940,54,4,4,6,'A na to dají přikrytí z koží jezevčích, a přistrou svrchu rouchem z samého postavce modrého, a provlekou sochory její.'),
(1549941,54,4,4,7,'Na stůl pak chlebů předložení prostrou roucho z postavce modrého, a dají na něj misy a kadidlnice a koflíky a přikryvadla k přikrývání; a chléb ustavičně na něm bude.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549942,54,4,4,8,'A prostrou na to roucho z červce dvakrát barveného, a přikryjí to přistřením z koží jezevčích, a provlekou sochory jeho.'),
(1549943,54,4,4,9,'Vezmou také roucho z postavce modrého, a přikryjí svícen světla a lampy jeho, i utěradla jeho, i nádoby k oharkům jeho, a všecky nádoby k oleji jeho, jichž při něm užívají.'),
(1549944,54,4,4,10,'A obvinou jej se všechněmi nádobami jeho přikrytím z koží jezevčích, a vloží na sochory.'),
(1549945,54,4,4,11,'Na oltář pak zlatý prostrou roucho z postavce modrého, a přikryjí jej přikrytím z koží jezevčích, a provlekou sochory.'),
(1549946,54,4,4,12,'Vezmou i všecky nádoby k službě, jimiž přisluhovali v svatyni, a zavinouce do roucha z postavce modrého, přikryjí je přikrytím z koží jezevčích, a vloží na sochory.'),
(1549947,54,4,4,13,'Vyprázdní i popel z oltáře, a prostrou na něj roucho šarlatové.'),
(1549948,54,4,4,14,'A vloží svrchu všecko nádobí jeho, jímž přisluhují na něm, nádoby k uhlí, vidličky, pometla, kotlíky a všecko nádobí oltáře, a přistrouce jej přikrytím z koží jezevčích, uvlekou sochory jeho.'),
(1549949,54,4,4,15,'A když to vykoná Aron s syny svými, a přikryje svatyni i všecka nádobí její, a již by se měla hýbati vojska, tedy přijdou synové Kahat, aby nesli; ale nedotknou se svatyně, aby nezemřeli. Ta jest práce synů Kahat při stánku úmluvy.'),
(1549950,54,4,4,16,'Eleazar pak, syn Arona kněze, pečovati bude o olej k svícení a kadění vonnými věcmi a obět ustavičnou i o olej pomazání, svěřený sobě maje všecken příbytek a všecky věci, kteréž v něm jsou, svatyni a nádoby její.'),
(1549951,54,4,4,17,'A mluvil Hospodin k Mojžíšovi a Aronovi, řka:'),
(1549952,54,4,4,18,'Hleďtež, abyste nevyhladili pokolení čeledi Kahat z prostředku Levítů.'),
(1549953,54,4,4,19,'Ale toto učiníte jim, aby zachováni byli a nezemřeli, když by přistupovali k svatyni svatých: Aron a synové jeho přijdouce, zřídí je, jednoho každého ku práci a břemenu jeho.'),
(1549954,54,4,4,20,'A onino nepřicházejte hleděti na věci svaté, když zavinovány bývají, aby nezemřeli.'),
(1549955,54,4,4,21,'Mluvil opět Hospodin k Mojžíšovi, řka:'),
(1549956,54,4,4,22,'Sečti také syny Gersonovy po domích otců jich a po čeledech jejich.'),
(1549957,54,4,4,23,'Od třidcítiletých a výše až do padesátiletých sečteš je, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy.'),
(1549958,54,4,4,24,'Tato pak bude práce čeledí Gersonových v službě a nošení:'),
(1549959,54,4,4,25,'Nositi budou kortýny příbytku a stánek úmluvy s přikrytím jeho, a přikrytí z koží jezevčích, kteréž svrchu na něm jest, a zastření dveří stánku úmluvy,'),
(1549960,54,4,4,26,'A očkovaté koltry síně, a zastření brány síně, kteráž jest při stanu a při oltáři vůkol, a provazy její, a všecky nádoby přisluhování jejich, a čehožkoli užívají při službě své.'),
(1549961,54,4,4,27,'Vedlé rozkazu Aronova a synů jeho konati budou všecky služby své synové Gersonovi při všech pracech svých, a při všech službách svých, a svěříte jim k ostříhání všecka břemena jejich.'),
(1549962,54,4,4,28,'Ta jest práce čeledí synů Gersonových v stánku úmluvy, a Itamar, syn Arona kněze, stráž nad nimi držeti bude.'),
(1549963,54,4,4,29,'Syny také Merari po čeledech jejich a domích otců jejich sečteš.'),
(1549964,54,4,4,30,'Od třidcítiletých a výše až do padesátiletých sečteš všecky, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy.'),
(1549965,54,4,4,31,'Tato pak bude povinnost práce jejich, nad všecku službu jejich při stánku úmluvy: Dsky příbytku a svlaky jeho, i sloupy s podstavky jeho nositi,'),
(1549966,54,4,4,32,'Sloupy také vůkol síně s podstavky jejich, kolíky a provazy jejich, se všechněmi potřebami, i se vším přisluhováním jejich. A ze jména vyčtete nádoby svěřené jim k ostříhání.'),
(1549967,54,4,4,33,'Ta bude práce čeledí synů Merari při všech službách jejich při stánku úmluvy, pod spravou Itamara, syna Arona kněze.'),
(1549968,54,4,4,34,'I sečtl Mojžíš s Aronem a s knížaty lidu syny Kahat po čeledech jejich, a po domích otců jejich,'),
(1549969,54,4,4,35,'Od třidcítiletých a výše až do padesátiletých, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy.'),
(1549970,54,4,4,36,'A bylo jich sečtených po čeledech jejich dva tisíce, sedm set, padesáte.'),
(1549971,54,4,4,37,'Ti jsou sečteni z čeledi Kahat, všickni služebníci při stánku úmluvy, kteréž sčetl Mojžíš s Aronem podlé rozkazu Hospodinova skrze Mojžíše.'),
(1549972,54,4,4,38,'Sečtených také synů Gersonových po čeledech jejich, a po domích otců jejich,'),
(1549973,54,4,4,39,'Od třidcítiletých a výše až do padesátiletých, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy,'),
(1549974,54,4,4,40,'Sečtených jich po čeledech jejich, po domích otců jejich, dva tisíce, šest set, třidceti.'),
(1549975,54,4,4,41,'Ti jsou sečteni z čeledí synů Gersonových, všickni přisluhující v stánku úmluvy, kteréž sečtli Mojžíš s Aronem k rozkazu Hospodinovu.'),
(1549976,54,4,4,42,'Sečtených pak z čeledí synů Merari po čeledech jejich, po domích otců jejich,'),
(1549977,54,4,4,43,'Od třidcítiletých a výše až do padesátiletých, kteříž by způsobní jsouce k boji, mohli konati službu při stánku úmluvy,'),
(1549978,54,4,4,44,'Načteno jich po čeledech jejich tři tisíce a dvě stě.'),
(1549979,54,4,4,45,'Ti jsou sečteni z čeledí synů Merari, kteréž sčetl Mojžíš s Aronem podlé rozkazu Hospodinova skrze Mojžíše.'),
(1549980,54,4,4,46,'Všech sečtených, kteréž sčetl Mojžíš s Aronem a s knížaty Izraelskými z Levítů po čeledech jejich a po domích otců jejich,'),
(1549981,54,4,4,47,'Od těch, kteříž byli ve třidcíti letech a výše, až do padesátiletých, kteřížkoli přináležejí k vykonávání služby přisluhování a práce břemena při stánku úmluvy,'),
(1549982,54,4,4,48,'Sečtených těch bylo osm tisíců, pět set a osmdesáte.'),
(1549983,54,4,4,49,'Vedlé rozkazu Hospodinova sečtl je Mojžíš, jednoho každého vedlé přisluhování jeho, a vedlé břemene jeho. Sečteni pak jsou ti, kteréž rozkázal čísti Hospodin Mojžíšovi.'),
(1549984,54,4,5,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1549985,54,4,5,2,'Přikaž synům Izraelským, ať vyženou z stanů každého malomocného a každého trpícího tok semene, i každého nad mrtvým poškvrněného.'),
(1549986,54,4,5,3,'I muže i ženu vyženete, ven za stany vyženete je, aby nepoškvrňovali vojska těch, mezi nimiž já přebývám.'),
(1549987,54,4,5,4,'I učinili tak synové Izraelští, a vyhnali je ven za stany. Jakož byl mluvil Hospodin k Mojžíšovi, tak učinili synové Izraelští.'),
(1549988,54,4,5,5,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1549989,54,4,5,6,'Mluv k synům Izraelským: Muž aneb žena, když učiní nějaký hřích lidský, dopouštěje se výstupku proti Hospodinu, a byla by vinna duše ta:'),
(1549990,54,4,5,7,'Tedy vyzná hřích svůj, kterýž učinil, navrátí pak to, čímž vinen byl, v cele, a pátý díl přidá nad to, a dá tomu, proti komuž zavinil.'),
(1549991,54,4,5,8,'A neměl-li by muž ten přítele, jemuž by nahradil tu škodu, pokuta dána buď Hospodinu a knězi, mimo skopce očištění, jímž očištěn býti má.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1549992,54,4,5,9,'Též všeliká obět všech věcí posvěcených od synů Izraelských, kterouž přinesou knězi, jemu se dostane.'),
(1549993,54,4,5,10,'Tak i věci posvěcené od kohokoli jemu se dostanou; a dal-li kdo co knězi, také jeho bude.'),
(1549994,54,4,5,11,'Mluvil ještě Hospodin k Mojžíšovi, řka:'),
(1549995,54,4,5,12,'Mluv k synům Izraelským a rci jim: Kdyby od některého muže uchýlila se žena, a dopustila by se výstupku proti němu,'),
(1549996,54,4,5,13,'Tak že by obýval někdo jiný s ní, a bylo by to skryto před očima muže jejího, a tajila by se, jsuci poškvrněna, a svědka by nebylo proti ní, a ona nebyla by postižena;'),
(1549997,54,4,5,14,'Pohnul-li by se duch muže horlivostí velikou, tak že by horlil proti ženě své, kteráž by poškvrněna byla; aneb pohnul-li by se duch muže velikou horlivostí, tak že by horlil proti ženě své, kteráž by poškvrněna nebyla:'),
(1549998,54,4,5,15,'Tedy přivede muž ženu svou k knězi, a přinese obět její při ní, desátý díl efi mouky ječné. Nenalejeť na ni oleje, aniž dá na ni kadidla; nebo obět veliké horlivosti jest, obět suchá pamětná, uvozující v pamět nepravost.'),
(1549999,54,4,5,16,'I bude ji kněz obětovati, a postaví ji před Hospodinem.'),
(1550000,54,4,5,17,'A nabere vody svaté do nádoby hliněné, a vezma prachu, kterýž jest na zemi v příbytku, dá jej do té vody.'),
(1550001,54,4,5,18,'Potom postaví kněz ženu tu před Hospodinem, a odkryje hlavu její, a dá jí do rukou obět suchou pamětnou, kteráž jest obět veliké horlivosti; v ruce pak kněze bude voda hořká zlořečená.'),
(1550002,54,4,5,19,'I zaklínati bude ji kněz a řekne k ní: Jestliže neobcoval s tebou žádný, a jestliže jsi neuchýlila se k nečistotě od muže svého, budiž čistá od vody této hořké zlořečené.'),
(1550003,54,4,5,20,'Paklis se uchýlila od muže svého a nečistá jsi, a obcoval-li někdo jiný s tebou kromě manžela tvého,'),
(1550004,54,4,5,21,'(Zaklínati pak bude kněz tu ženu, čině klatbu zlořečenství, a řekne jí:) Dejž tebe Hospodin v zlořečení a v prokletí u prostřed lidu tvého, dopustě, aby lůno tvé hnilo a břicho tvé oteklo.'),
(1550005,54,4,5,22,'Vejdiž voda zlořečená tato do života tvého, aby oteklo břicho tvé, a lůno tvé shnilo. I odpoví žena ta: Amen, amen.'),
(1550006,54,4,5,23,'Napíše pak všecko zlořečenství toto do knihy, a smyje je tou vodou hořkou.'),
(1550007,54,4,5,24,'I dá ženě, aby pila vodu hořkou a zlořečenou; a vejdeť do ní voda zlořečená, a obrátí se v hořkosti.'),
(1550008,54,4,5,25,'Potom vezme kněz z ruky ženy obět veliké horlivosti, a obraceti ji bude sem i tam před Hospodinem, a bude ji obětovati na oltáři.'),
(1550009,54,4,5,26,'A vezma plnou hrst pamětného jejíhoz oběti suché, páliti to bude na oltáři; a potom dá vypíti ženě tu vodu.'),
(1550010,54,4,5,27,'A když jí dá píti tu vodu, stane se, jestliže nečistá byla, a dopustila se výstupku proti muži svému, že vejde do ní voda zlořečená,a obrátí se v hořkost, i odme se břicho její, a vyhnije lůno její; i bude žena ta v zlořečení u prostřed lidu svého.'),
(1550011,54,4,5,28,'Pakli není poškvrněna žena ta, ale čistá jest, tedy bez viny bude, a roditi bude děti.'),
(1550012,54,4,5,29,'Ten jest zákon veliké horlivosti, když by se uchýlila žena od muže svého, a byla by poškvrněna,'),
(1550013,54,4,5,30,'Aneb když by se pohnul duch veliké horlivosti v manželu, tak že by horlil velmi proti ženě své, aby postavil ji před Hospodinem, a aby vykonal při ní kněz všecko vedlé zákona tohoto.'),
(1550014,54,4,5,31,'I bude ten muž očištěn od hříchu, žena pak ponese nepravost svou.'),
(1550015,54,4,6,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550016,54,4,6,2,'Mluv k synům Izraelským a rci jim: Muž neb žena, když se oddělí, činíce slib nazareův, aby se oddali Hospodinu,'),
(1550017,54,4,6,3,'Od vína i nápoje opojného zdrží se, octa vinného a octa z nápoje opojného nebude píti, ani co vytlačeného z hroznů, zelených hroznů ani suchých nebude jísti.'),
(1550018,54,4,6,4,'Po všecky dny nazarejství svého nebude jísti žádné věci pocházející z vinného kmene, od zrnka až do šupiny.'),
(1550019,54,4,6,5,'Po všecky dny slibu nazarejství svého břitva nevejde na hlavu jeho, dokavadž by se nevyplnili dnové, v nichž se oddělil Hospodinu. Svatý bude, a nechá růsti vlasů hlavy své.'),
(1550020,54,4,6,6,'Po všecky dny, v nichž se oddělí Hospodinu, k tělu mrtvému nevejde.'),
(1550021,54,4,6,7,'Nad otcem svým aneb nad matkou svou, nad bratrem svým aneb nad sestrou svou, kdyby zemřeli, nebude se poškvrňovati; nebo posvěcení Boha jeho jest na hlavě jeho.'),
(1550022,54,4,6,8,'Po všecky dny nazarejství svého svatý bude Hospodinu.'),
(1550023,54,4,6,9,'Umřel-li by pak kdo blízko něho náhlou smrtí, a poškvrnil-li by hlavy v nazarejství jeho, oholí hlavu svou v den očišťování svého; dne sedmého oholí ji.'),
(1550024,54,4,6,10,'A dne osmého přinese dvě hrdličky, aneb dvé holoubátek knězi, ke dveřím stánku úmluvy.'),
(1550025,54,4,6,11,'I bude kněz obětovati jedno za hřích,a druhé v zápalnou obět, a očistí jej od toho, čímž zhřešil nad mrtvým, a posvětí hlavy jeho v ten den.'),
(1550026,54,4,6,12,'A oddělí Hospodinu dny nazarejství svého, a přinese beránka ročního za provinění, a dnové první přijdou v nic; nebo poškvrněno jest nazarejství jeho.'),
(1550027,54,4,6,13,'Tento pak jest zákon nazareův: V ten den, když se vyplní čas nazarejství jeho, přijde ke dveřím stánku úmluvy.'),
(1550028,54,4,6,14,'A bude obětovati obět svou Hospodinu, beránka ročního bez poškvrny, jednoho v obět zápalnou, a ovci jednu roční bez poškvrny v obět za hřích, a skopce jednoho bez poškvrny v obět pokojnou,'),
(1550029,54,4,6,15,'A koš chlebů přesných, koláče z mouky bělné olejem zadělané, a pokruty nekvašené, olejem pomazané, s obětmi jejími suchými i mokrými.'),
(1550030,54,4,6,16,'Kteréžto věci obětovati bude kněz před Hospodinem, a učiní obět za hřích jeho, i zápalnou obět jeho.'),
(1550031,54,4,6,17,'Skopce také obětovati bude v obět pokojnou Hospodinu, spolu s košem chlebů přesných; tolikéž obětovati bude kněz i obět suchou i mokrou jeho.'),
(1550032,54,4,6,18,'Tedy oholí nazareus u dveří stánku úmluvy hlavu nazarejství svého, a vezma vlasy z hlavy nazarejství svého, vloží je na oheň, kterýž jest pod obětí pokojnou.'),
(1550033,54,4,6,19,'Potom vezme kněz plece vařené z skopce toho, a jeden koláč přesný z koše, a pokrutu nekvašenou jednu, a dá v ruce nazarejského, když by oholeno bylo nazarejství jeho.'),
(1550034,54,4,6,20,'I bude obraceti kněz ty věci sem i tam v obět obracení před Hospodinem; a ta věc svatá přináležeti bude knězi mimo hrudí obracení, i plece pozdvižení. A již potom nazareus bude moci víno píti.'),
(1550035,54,4,6,21,'Ten jest zákon nazarea, kterýž slib učinil, a jeho obět Hospodinu za oddělení jeho, kromě toho, což by více učiniti mohl. Vedlé slibu svého, kterýž učinil, tak učiní podlé zákona oddělení svého.'),
(1550036,54,4,6,22,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550037,54,4,6,23,'Mluv k Aronovi a synům jeho a rci: Takto budete požehnání dávati synům Izraelským, mluvíce k nim:'),
(1550038,54,4,6,24,'Požehnejž tobě Hospodin, a ostříhejž tebe.'),
(1550039,54,4,6,25,'Osvěť Hospodin tvář svou nad tebou, a buď milostiv tobě.'),
(1550040,54,4,6,26,'Obratiž Hospodin tvář svou k tobě,a dejž tobě pokoj.'),
(1550041,54,4,6,27,'I budou vzývati jméno mé nad syny Izraelskými, a já jim žehnati budu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550042,54,4,7,1,'I stalo se toho dne, když dokonal Mojžíš a vyzdvihl příbytek, a pomazal i posvětil ho se všechněmi nádobami jeho, také oltáře a všeho nádobí jeho pomazal a posvětil,'),
(1550043,54,4,7,2,'Že přistupujíce knížata Izraelská, přední v domích otců svých, (ti byli knížata pokolení, postavení nad sečtenými),'),
(1550044,54,4,7,3,'Obětovali dar svůj před Hospodinem, šest vozů přikrytých a dvanácte volů. Dvé knížat dalo jeden vůz, a jeden každý jednoho vola, i obětovali to před příbytkem.'),
(1550045,54,4,7,4,'I řekl Hospodin Mojžíšovi, řka:'),
(1550046,54,4,7,5,'Vezmi ty věci od nich, ať jsou ku potřebě při službě stánku úmluvy, a dej je Levítům, každé čeledi podlé přisluhování jejího.'),
(1550047,54,4,7,6,'Vzav tedy Mojžíš ty vozy i voly, dal je Levítům.'),
(1550048,54,4,7,7,'Dva vozy a čtyři voly dal synům Gersonovým vedlé přisluhování jejich.'),
(1550049,54,4,7,8,'Čtyři pak vozy a osm volů dal synům Merari vedlé přisluhování jejich, kteříž byli pod spravou Itamara, syna Aronova, kněze.'),
(1550050,54,4,7,9,'Synům pak Kahat nic nedal; nebo přisluhování svatyně k nim přináleželo, a na ramenou nositi měli.'),
(1550051,54,4,7,10,'Obětovali tedy knížata ku posvěcování oltáře v ten den, když pomazán byl; obětovali, pravím, dar svůj před oltářem.'),
(1550052,54,4,7,11,'Řekl pak Hospodin Mojžíšovi: Jedno kníže v jeden den, druhé kníže v druhý den, pořád obětovati budou dar svůj ku posvěcení oltáře.'),
(1550053,54,4,7,12,'Protož obětoval prvního dne dar svůj Názon, syn Aminadabův, z pokolení Judova.'),
(1550054,54,4,7,13,'Dar pak jeho byl misa stříbrná jedna, sto třidceti lotů ztíží; též báně jedna stříbrná, sedmdesáti lotů ztíží, jakž jest lot svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550055,54,4,7,14,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550056,54,4,7,15,'Volek jeden mladý, skopec jeden, a beránek roční jeden k oběti zápalné;'),
(1550057,54,4,7,16,'Kozel jeden za hřích;'),
(1550058,54,4,7,17,'A k oběti pokojné volové dva, skopců pět, kozlů pět, a beránků ročních pět. Ta byla obět Názona, syna Aminadabova.'),
(1550059,54,4,7,18,'Druhého dne obětoval Natanael, syn Suar, kníže z pokolení Izachar.'),
(1550060,54,4,7,19,'Obětoval dar svůj misu stříbrnou jednu, sto třidceti lotů ztíží; báni stříbrnou jednu, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550061,54,4,7,20,'Kadidlnici jednu z desíti lotů zlata, plnou kadidla;'),
(1550062,54,4,7,21,'Volka mladého jednoho, skopce jednoho, a beránka ročního jednoho k oběti zápalné;'),
(1550063,54,4,7,22,'Kozla jednoho za hřích;'),
(1550064,54,4,7,23,'A k oběti pokojné voly dva, skopců pět, kozlů pět, a beránků ročních pět. Ten byl dar Natanaele, syna Suar.'),
(1550065,54,4,7,24,'Dne třetího kníže synů Zabulonových Eliab, syn Helonův.'),
(1550066,54,4,7,25,'Dar pak jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550067,54,4,7,26,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550068,54,4,7,27,'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550069,54,4,7,28,'Kozel jeden za hřích;'),
(1550070,54,4,7,29,'A k oběti pokojné volové dva, skopců pět, kozlů pět, a beránků ročních pět. Ta byla obět Eliaba, syna Helonova.'),
(1550071,54,4,7,30,'Čtvrtého dne kníže synů Rubenových Elisur, syn Sedeurův.'),
(1550072,54,4,7,31,'Dar jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané v obět suchou;'),
(1550073,54,4,7,32,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550074,54,4,7,33,'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550075,54,4,7,34,'Kozel jeden za hřích;'),
(1550076,54,4,7,35,'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ten byl dar Elisura, syna Sedeurova.'),
(1550077,54,4,7,36,'Dne pátého kníže synů Simeonových, Salamiel, syn Surisaddai;'),
(1550078,54,4,7,37,'Obět jeho byla misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550079,54,4,7,38,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550080,54,4,7,39,'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550081,54,4,7,40,'Kozel jeden za hřích;'),
(1550082,54,4,7,41,'A na obět pokojnou volové dva, skopců pět, kozlů pět, beránků ročních pět. Ta byla obět Salamiele, syna Surisaddai.'),
(1550083,54,4,7,42,'Dne šestého kníže synů Gád, Eliazaf, syn Duelův.'),
(1550084,54,4,7,43,'Dar jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550085,54,4,7,44,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550086,54,4,7,45,'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550087,54,4,7,46,'Kozel jeden za hřích;'),
(1550088,54,4,7,47,'A k oběti pokojné volové dva, skopců pět, kozlů pět, a beránků ročních pět. Ten byl dar Eliazafa, syna Duelova.'),
(1550089,54,4,7,48,'Dne sedmého kníže synů Efraimových, Elisama, syn Amiudův.'),
(1550090,54,4,7,49,'Dar jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané na obět suchou;'),
(1550091,54,4,7,50,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550092,54,4,7,51,'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550093,54,4,7,52,'Kozel jeden za hřích;'),
(1550094,54,4,7,53,'A na obět pokojnou volové dva, skopců pět, kozlů pět, beránků ročních pět. Ten byl dar Elisamův, syna Amiudova.'),
(1550095,54,4,7,54,'Dne osmého kníže synů Manasse, Gamaliel, syn Fadasurův.'),
(1550096,54,4,7,55,'Dar jeho byl misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550097,54,4,7,56,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550098,54,4,7,57,'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550099,54,4,7,58,'Kozel jeden za hřích;'),
(1550100,54,4,7,59,'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ta byla obět Gamaliele, syna Fadasurova.'),
(1550101,54,4,7,60,'Dne devátého kníže synů Beniaminových, Abidan, syn Gedeonův.'),
(1550102,54,4,7,61,'Obět jeho misa stříbrná jedna, kteráž sto třidceti lotů vážila; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550103,54,4,7,62,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550104,54,4,7,63,'Volek mladý jeden, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550105,54,4,7,64,'Kozel jeden za hřích;'),
(1550106,54,4,7,65,'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ten byl dar Abidanův, syna Gedeonova.'),
(1550107,54,4,7,66,'Desátého dne kníže synů Dan, Ahiezer, syn Amisaddai.'),
(1550108,54,4,7,67,'Obět jeho misa stříbrná jedna, jejížto váha byla sto třidceti lotů; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě plné mouky bělné, olejem zadělané k oběti suché;'),
(1550109,54,4,7,68,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550110,54,4,7,69,'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550111,54,4,7,70,'Kozel jeden za hřích;'),
(1550112,54,4,7,71,'A k oběti pokojné volové dva, skopců pět, kozlů pět, a beránků ročních pět. Ten byl dar Ahiezera, syna Amisaddai.'),
(1550113,54,4,7,72,'Jedenáctého dne kníže synů Asser, Fegiel, syn Ochranův.'),
(1550114,54,4,7,73,'Obět jeho misa stříbrná jedna, jejížto váha byla sto třidceti lotů; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550115,54,4,7,74,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550116,54,4,7,75,'Volek jeden mladý, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550117,54,4,7,76,'Kozel jeden za hřích;'),
(1550118,54,4,7,77,'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ten byl dar Fegiele, syna Ochranova.'),
(1550119,54,4,7,78,'Dvanáctého dne kníže synů Neftalím, Ahira, syn Enanův.'),
(1550120,54,4,7,79,'Obět jeho byla misa stříbrná jedna, jejížto váha byla sto třidceti lotů; báně stříbrná jedna, sedmdesáti lotů ztíží vedlé lotu svatyně; obě dvě nádoby plné mouky bělné, olejem zadělané k oběti suché;'),
(1550121,54,4,7,80,'Kadidlnice jedna z desíti lotů zlata, plná kadidla;'),
(1550122,54,4,7,81,'Volek mladý jeden, skopec jeden, beránek roční jeden k oběti zápalné;'),
(1550123,54,4,7,82,'Kozel jeden za hřích;'),
(1550124,54,4,7,83,'A k oběti pokojné volové dva, skopců pět, kozlů pět, beránků ročních pět. Ta byla obět Ahiry, syna Enanova.'),
(1550125,54,4,7,84,'Toť jest posvěcení oltáře (toho dne, když pomazán jest), od knížat Izraelských: Mis stříbrných dvanácte, bání stříbrných dvanácte, kadidlnic zlatých dvanácte.'),
(1550126,54,4,7,85,'Sto třidceti lotů vážila jedna misa stříbrná, a sedmdesáte báně jedna; všecko nádobí stříbrné vážilo dva tisíce a čtyři sta lotů na lot svatyně.'),
(1550127,54,4,7,86,'Kadidlnic zlatých dvanácte, plných kadidla; deset lotů vážila každá kadidlnice na váhu svatyně. Všecky kadidlnice zlaté sto a dvadceti lotů vážily.'),
(1550128,54,4,7,87,'Všeho dobytka k oběti zápalné dvanácte volků, skopců dvanácte, beránků ročních dvanácte s obětí jejich suchou, a kozlů dvanácte za hřích.'),
(1550129,54,4,7,88,'Všeho pak dobytka k oběti pokojné čtyřmecítma volů, skopců šedesáte, kozlů šedesáte, beránků ročních šedesáte. To bylo posvěcení oltáře, když pomazán byl.'),
(1550130,54,4,7,89,'Potom když vcházel Mojžíš do stánku úmluvy, aby mluvil s Bohem, tedy slýchal hlas mluvícího k sobě z slitovnice, kteráž byla nad truhlou svědectví mezi dvěma cherubíny,a mluvíval k němu.'),
(1550131,54,4,8,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550132,54,4,8,2,'Mluv k Aronovi a rci jemu: Když rozsvěcovati budeš lampy, ven z svícnu sedm lamp svítiti má.'),
(1550133,54,4,8,3,'I učinil Aron tak; ven z svícnu světlo od sebe dávající rozsvítil lampy jeho, jakož přikázal Hospodin Mojžíšovi.'),
(1550134,54,4,8,4,'Bylo pak dílo svícnu takové: Z taženého zlata byl všecken, až i sloupec jeho i květové jeho z taženého zlata byli; podlé podobenství toho, kteréž ukázal Hospodin Mojžíšovi, tak udělal svícen.'),
(1550135,54,4,8,5,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1550136,54,4,8,6,'Vezmi Levíty z prostředku synů Izraelských, a očisť je.'),
(1550137,54,4,8,7,'Tímto pak způsobem očišťovati je budeš: Pokropíš jich vodou očištění; oholí všecko tělo své, a zperou roucha svá, a očištěni budou.'),
(1550138,54,4,8,8,'Potom vezmou volka mladého a obět suchou z mouky bělné, olejem skropené; a druhého volka mladého vezmeš k oběti za hřích.'),
(1550139,54,4,8,9,'Tedy přistoupiti rozkážeš Levítům před stánek úmluvy, a shromáždíš všecko množství synů Izraelských.'),
(1550140,54,4,8,10,'Postavíš Levíty před Hospodinem, a vloží synové Izraelští ruce své na Levíty.'),
(1550141,54,4,8,11,'A obětovati bude Aron Levíty v obět před Hospodinem od synů Izraelských, aby vykonávali službu Hospodinu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550142,54,4,8,12,'Levítové pak vloží ruce své na hlavy těch volků; a obětovati budeš jednoho za hřích, a druhého v obět zápalnou Hospodinu k očištění Levítů.'),
(1550143,54,4,8,13,'A postavíš Levíty před Aronem a před syny jeho, a obětovati je budeš v obět Hospodinu.'),
(1550144,54,4,8,14,'I oddělíš Levíty z prostředku synů Izraelských, aby moji byli Levítové.'),
(1550145,54,4,8,15,'Potom pak přijdou Levítové, aby přisluhovali při stánku úmluvy, když bys očistil je a obětoval v obět.'),
(1550146,54,4,8,16,'Nebo vlastně dáni jsou mi z prostředku synů Izraelských za všecky otvírající život, za prvorozené ze všech synů Izraelských vzal jsem je sobě.'),
(1550147,54,4,8,17,'Nebo mé jest všecko prvorozené mezi syny Izraelskými, tak z lidí jako z hovad; od toho dne, jakž jsem pobil všecko prvorozené v zemi Egyptské, posvětil jsem jich sobě.'),
(1550148,54,4,8,18,'Vzal jsem pak Levíty za všecky prvorozené synů Izraelských.'),
(1550149,54,4,8,19,'A dal jsem Levíty darem Aronovi i synům jeho z prostředku synů Izraelských, aby konali službu místo synů Izraelských při stánku úmluvy, a očišťovali od hříchů syny Izraelské; a tak nepřijde na syny Izraelské rána,kteráž by přišla, kdyby přistupovali synové Izraelští k svatyni.'),
(1550150,54,4,8,20,'I učinili Mojžíš a Aron i všecko množství synů Izraelských při Levítích všecko to, což přikázal Hospodin Mojžíšovi o Levítích; tak s nimi učinili synové Izraelští.'),
(1550151,54,4,8,21,'A očistili se Levítové a zeprali roucha svá; a obětoval je Aron v obět před Hospodinem, a očistil je Aron, aby byli čisti.'),
(1550152,54,4,8,22,'Potom teprv přistoupili Levítové k vykonávání služby své při stánku úmluvy, před Aronem i před syny jeho; jakž přikázal Hospodin Mojžíšovi o Levítích, tak s nimi učinili.'),
(1550153,54,4,8,23,'I mluvil opět Hospodin k Mojžíšovi, řka:'),
(1550154,54,4,8,24,'I toto k Levítům přináleží: V pětmecítma letech zstáří a výše jeden každý z nich přistoupí, a postaví se k ochotnému práce konání v službě při stánku úmluvy.'),
(1550155,54,4,8,25,'V padesáti pak letech přestane od práce služby té, a více přisluhovati nebude.'),
(1550156,54,4,8,26,'Ale přisluhovati bude bratřím svým při stánku úmluvy stráž držícím, sám pak služeb konati nebude. Tak učiníš s Levíty při pracech jejich.'),
(1550157,54,4,9,1,'Mluvil pak Hospodin k Mojžíšovi na poušti Sinai, léta druhého po vyjití z země Egyptské, měsíce prvního, řka:'),
(1550158,54,4,9,2,'Slaviti budou synové Izraelští velikunoc v čas svůj vyměřený.'),
(1550159,54,4,9,3,'Čtrnáctého dne měsíce toho u večer budete ji slaviti jistým časem svým, vedlé všech ustanovení jejích, a podlé všech řádů jejích slaviti ji budete.'),
(1550160,54,4,9,4,'I mluvil Mojžíš k synům Izraelským, aby slavili Fáze.'),
(1550161,54,4,9,5,'Tedy slavili Fáze v měsíci prvním, čtrnáctého dne u večer na poušti Sinai; vedlé všeho toho, což přikázal Hospodin Mojžíšovi, tak učinili synové Izraelští.'),
(1550162,54,4,9,6,'I byli někteří muži, ješto se poškvrnili při mrtvém, kteříž nemohli slaviti Fáze toho dne. I přistoupili před Mojžíše a Arona v ten den,'),
(1550163,54,4,9,7,'A promluvili muži ti k němu: My jsme se poškvrnili nad mrtvým. Nebude-liž nám zbráněno obětovati oběti Hospodinu v jistý čas spolu s syny Izraelskými?'),
(1550164,54,4,9,8,'I řekl jim Mojžíš: Počekejte, až uslyším, co vám učiniti rozkáže Hospodin.'),
(1550165,54,4,9,9,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1550166,54,4,9,10,'Mluv k synům Izraelským a rci: Kdož by koli byl poškvrněný nad mrtvým, aneb byl by na cestě daleké, buď z vás aneb z potomků vašich, budeť slaviti Fáze Hospodinu.'),
(1550167,54,4,9,11,'Měsíce druhého, čtrnáctého dne u večer slaviti budou je, s chleby nekvašenými, a s řeřichami jísti je budou.'),
(1550168,54,4,9,12,'Nezanechajíť ho nic až do jitra, a kosti v něm nezlámí; vedlé všelikého ustanovení Fáze budou je slaviti.'),
(1550169,54,4,9,13,'Ale člověk ten, kterýž by byl čistý, a nebyl na cestě, a však by zanedbal slaviti Fáze, vyhlazena bude duše ta z lidu svého; nebo oběti Hospodinu neobětoval v jistý čas její; hřích svůj ponese člověk ten.'),
(1550170,54,4,9,14,'Jestliže by s vámi bydlil příchozí, a slavil by Fáze Hospodinu, vedlé ustanovení Fáze, a vedlé řádu jeho bude je slaviti. Ustanovení jednostejné bude vám, tak příchozímu, jako obyvateli v zemi.'),
(1550171,54,4,9,15,'Toho pak dne, v kterémž vyzdvižen jest příbytek, přikryl oblak příbytek, a stál nad stánkem svědectví; u večer pak bývalo nad příbytkem na pohledění jako oheň až do jitra.'),
(1550172,54,4,9,16,'Tak bývalo ustavičně, oblak přikrýval jej ve dne, záře pak ohnivá v noci.'),
(1550173,54,4,9,17,'A když se zdvihl oblak od stánku, hned také hýbali se synové Izraelští; a na kterém místě pozůstal oblak, tu také kladli se synové Izraelští.'),
(1550174,54,4,9,18,'K rozkazu Hospodinovu hýbali se synové Izraelští, a k rozkazu Hospodinovu kladli se; po všecky dny, dokudž zůstával oblak nad příbytkem, i oni leželi.'),
(1550175,54,4,9,19,'Když pak trval oblak nad příbytkem po mnohé dny, tedy drželi synové Izraelští stráž Hospodinovu, a netáhli odtud.'),
(1550176,54,4,9,20,'A když oblak byl nad příbytkem po nemnohé dny, k rozkazu Hospodinovu kladli se, a k rozkazu Hospodinovu hýbali se.'),
(1550177,54,4,9,21,'Kdyžkoli byl oblak od večera až do jitra, a v jitře se vznesl, hned i oni šli; buď že trval přes den a noc, (jakž kdy vznášel se oblak, tak oni táhli,)'),
(1550178,54,4,9,22,'Buď že za dva dni, aneb za měsíc, aneb za rok prodléval oblak nad příbytkem, zůstávaje nad ním, synové Izraelští také leželi,a nehnuli se; když pak on vznášel se, též i oni táhli.'),
(1550179,54,4,9,23,'K rozkazu Hospodinovu kladli se, a k rozkazu Hospodinovu hýbali se, stráž Hospodinovu držíce podlé rozkazu jeho skrze Mojžíše.'),
(1550180,54,4,10,1,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550181,54,4,10,2,'Udělej sobě dvě trouby stříbrné. Dílem taženým uděláš je, kterýchž užívati budeš k svolání všeho množství, a když by se mělo hnouti vojsko.'),
(1550182,54,4,10,3,'Protož kdyžkoli zatroubí na ně, shromáždí se k tobě všecko množství ke dveřím stánku úmluvy.'),
(1550183,54,4,10,4,'Jestliže v jednu toliko zatroubí, tedy shromáždí se k tobě knížata, přední lidu Izraelského.'),
(1550184,54,4,10,5,'Pakli by s nějakým přetrubováním troubili, hnou se s místa, kteříž leželi k východní straně.'),
(1550185,54,4,10,6,'Když by pak troubili s přetrubováním po druhé, tedy hnou se ti, kteříž leželi ku poledni. S přetrubováním troubiti budou k tažení svému.'),
(1550186,54,4,10,7,'Ale když byste měli svolati všecko množství, prostě bez přetrubování troubiti budete.'),
(1550187,54,4,10,8,'Synové Aronovi kněží trubami těmi budou troubiti, a bude vám to ustanovení věčné v pronárodech vašich.'),
(1550188,54,4,10,9,'Když vyjdete na vojnu v zemi vaší proti nepříteli ssužujícímu vás, s přetrubováním troubiti budete v trouby ty, a budete v paměti před Hospodinem Bohem svým, a zachováni budete od nepřátel svých.'),
(1550189,54,4,10,10,'V den také veselí vašeho, a při slavnostech svých, a při začátcích měsíců vašich troubiti budete v trouby ty k obětem svým zápalným a pokojným, i budou vám na památku před Bohem vaším: Já Hospodin Bůh váš.'),
(1550190,54,4,10,11,'I stalo se léta druhého, dvadcátý den měsíce druhého, že se vyzdvihl oblak z příbytku svědectví.'),
(1550191,54,4,10,12,'I táhli synové Izraelští po svých taženích z pouště Sinai; a zastavil se oblak na poušti Fáran.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550192,54,4,10,13,'Takto nejprvé brali se z rozkazu Hospodinova skrze Mojžíše:'),
(1550193,54,4,10,14,'Šla napřed korouhev vojska synů Juda po houfích svých, a nad nimi byl Názon, syn Aminadabův.'),
(1550194,54,4,10,15,'Nad vojskem pak pokolení synů Izachar byl Natanael, syn Suar.'),
(1550195,54,4,10,16,'A nad vojskem pokolení synů Zabulon Eliab, syn Helonův.'),
(1550196,54,4,10,17,'Složen jest také i příbytek, a šli synové Gersonovi a synové Merari nesouce příbytek.'),
(1550197,54,4,10,18,'Potom šla korouhev vojska Rubenova po houfích svých, a nad nimi byl Elisur, syn Sedeurův.'),
(1550198,54,4,10,19,'Nad vojskem pak pokolení synů Simeon Salamiel, syn Surisaddai.'),
(1550199,54,4,10,20,'A nad vojskem pokolení synů Gád Eliazaf, syn Duelův.'),
(1550200,54,4,10,21,'Šli také i Kahatští, nesouce svatyni; onino pak vyzdvihovali příbytek, až i tito přišli.'),
(1550201,54,4,10,22,'Potom šla korouhev vojska synů Efraim po houfích svých, a nad nimi byl Elisama, syn Amiudův.'),
(1550202,54,4,10,23,'Nad vojskem pak pokolení synů Manasse Gamaliel, syn Fadasurův.'),
(1550203,54,4,10,24,'A nad vojskem pokolení synů Beniamin Abidan, syn Gedeonův.'),
(1550204,54,4,10,25,'Šla potom i korouhev vojska synů Dan, obsahující ostatek vojska po houfích svých, a nad vojskem jeho Ahiezer, syn Amisaddai.'),
(1550205,54,4,10,26,'Nad vojskem pak pokolení synů Asser Fegiel, syn Ochranův.'),
(1550206,54,4,10,27,'A nad vojskem pokolení synů Neftalím Ahira, syn Enanův.'),
(1550207,54,4,10,28,'Ta jsou tažení synů Izraelských po houfích jejich, a tím pořádkem táhli.'),
(1550208,54,4,10,29,'Řekl pak Mojžíš Chobabovi, synu Raguelovu Madianskému, tchánu svému: My se béřeme k místu, o kterémž řekl Hospodin: Dám je vám. Protož poď s námi, a dobře učiníme tobě; nebo Hospodin mnoho dobrého zaslíbil Izraelovi.'),
(1550209,54,4,10,30,'Kterýž odpověděl jemu: Nepůjdu, ale k zemi své a k příbuznosti své se navrátím.'),
(1550210,54,4,10,31,'I řekl Mojžíš: Neopouštěj medle nás; nebo ty jsi svědom na poušti, kde bychom se měli klásti, a budeš nám za vůdce.'),
(1550211,54,4,10,32,'Když pak půjdeš s námi, a přijde to dobré, jímž dobře učiní nám Hospodin, tedy i tobě dobře učiníme.'),
(1550212,54,4,10,33,'A tak brali se od hory Hospodinovy cestou tří dnů, (a truhla smlouvy Hospodinovy předcházela je,) cestou tří dnů, pro vyhlédání sobě místa k odpočinutí.'),
(1550213,54,4,10,34,'A oblak Hospodinův byl nad nimi ve dne, když se hýbali z ležení.'),
(1550214,54,4,10,35,'Když pak počínali jíti s truhlou, říkával Mojžíš: Povstaniž Hospodine, a rozptýleni buďte nepřátelé tvoji, a ať utíkají před tváří tvou, kteříž tě v nenávisti mají.'),
(1550215,54,4,10,36,'Když pak stavína byla, říkával: Navratiž se, Hospodine, k desíti tisícům tisíců Izraelských.'),
(1550216,54,4,11,1,'I stalo se, že lid ztěžoval a stýskal sobě, cožse nelíbilo Hospodinu. Protož, slyše to Hospodin, rozhněval se náramně, a roznítil se proti nim oheň Hospodinův, a spálil zadní díl vojska.'),
(1550217,54,4,11,2,'Tedy volal lid k Mojžíšovi. I modlil se Mojžíš Hospodinu, a uhasl oheň.'),
(1550218,54,4,11,3,'I nazval jméno místa toho Tabbera; nebo rozpálil se proti nim oheň Hospodinův.'),
(1550219,54,4,11,4,'Lid pak k nim přimíšený napadla žádost náramná; a obrátivše se, plakali i synové Izraelští a řekli: Kdo nám to dá, abychom se masa najedli?'),
(1550220,54,4,11,5,'Rozpomínáme se na ryby, jichž jsme dosti v Egyptě darmo jídali, na okurky a melouny, též na por, cibuli a česnek.'),
(1550221,54,4,11,6,'A nyní duše naše vyprahlá, nic jiného nemá, kromě tu mannu před očima svýma.'),
(1550222,54,4,11,7,'(Manna pak byla jako semeno koliandrové, a barva její jako barva bdelium.'),
(1550223,54,4,11,8,'I vycházíval lid, a sbírali a mleli žernovy, neb tloukli v moždířích, a smažili na pánvici, aneb koláče podpopelné dělali z ní; chut pak její byla jako chut nového oleje.'),
(1550224,54,4,11,9,'Když pak sstupovala rosa na vojsko v noci, tedy sstupovala také i manna).'),
(1550225,54,4,11,10,'Tedy uslyšel Mojžíš, an lid pláče po čeledech svých, každý u dveří stanu svého. Pročež roznítila se prchlivost Hospodinova náramně; Mojžíšovi to také těžké bylo.'),
(1550226,54,4,11,11,'I řekl Mojžíš Hospodinu: Proč jsi tak zle učinil služebníku svému? Proč jsem nenalezl milosti před očima tvýma, že jsi vložil břímě všeho lidu tohoto na mne?'),
(1550227,54,4,11,12,'Zdaliž jsem já počal všecken lid tento? Zdali jsem já zplodil jej, že mi díš: Nes jej na rukou svých, jako nosí chůva děťátko, do země té, kterouž jsi s přísahou zaslíbil otcům jejich?'),
(1550228,54,4,11,13,'Kde mám nabrati masa, abych dal všemu lidu tomuto? Nebo plačí na mne, řkouce: Dej nám masa, ať jíme.'),
(1550229,54,4,11,14,'Nemohuť já sám nésti všeho lidu tohoto, nebo jest to nad možnost mou.'),
(1550230,54,4,11,15,'Pakli mi tak dělati chceš, prosím, zabí mne raději, jestliže jsem nalezl milost před očima tvýma, abych více nehleděl na trápení své.'),
(1550231,54,4,11,16,'Tedy řekl Hospodin Mojžíšovi: Shromažď mi sedmdesáte mužů z starších Izraelských, kteréž znáš, že jsou starší v lidu a správcové jeho; i přivedeš je ke dveřím stánku úmluvy, a státi budou tam s tebou.'),
(1550232,54,4,11,17,'A já sstoupím a mluviti budu s tebou, a vezmu z ducha, kterýž jest na tobě, a dám jim. I ponesou s tebou břímě lidu, a tak ty ho sám neponeseš.'),
(1550233,54,4,11,18,'Lidu pak díš: Posvěťtež se k zítřku,a budete jísti maso; nebo jste plakali v uších Hospodinových, řkouce: Kdo nám dá najísti se masa? Jistě že lépe nám bylo v Egyptě. I dá vám Hospodin masa, a budete jísti.'),
(1550234,54,4,11,19,'Nebudete toliko jeden den jísti, ani dva, ani pět, ani deset, ani dvadcet,'),
(1550235,54,4,11,20,'Ale za celý měsíc, až vám chřípěmi poleze, a zoškliví se, proto že jste pohrdli Hospodinem, kterýž jest u prostřed vás, a plakali jste před ním, říkajíce: Proč jsme vyšli z Egypta?'),
(1550236,54,4,11,21,'I řekl Mojžíš: Šestkrát sto tisíců pěších jest tohoto lidu, mezi nimiž já jsem, a ty pravíš: Dám jim masa, aby jedli za celý měsíc.'),
(1550237,54,4,11,22,'Zdali ovcí a volů nabije se jim, aby jim postačilo? Aneb zdali všecky ryby mořské shromáždí se jim, aby jim dosti bylo?'),
(1550238,54,4,11,23,'Tedy řekl Hospodin Mojžíšovi: Zdali ruka Hospodinova ukrácena jest? Již nyní uzříš, přijde-li na to, což jsem mluvil, čili nic.'),
(1550239,54,4,11,24,'Vyšed tedy Mojžíš, mluvil lidu slova Hospodinova, a shromáždiv sedmdesáte mužů z starších lidu, postavil je vůkol stánku.'),
(1550240,54,4,11,25,'I sstoupil Hospodin v oblaku a mluvil k němu, a vzav z ducha, kterýž byl na něm, dal sedmdesáti mužům starším. I stalo se, když odpočinul na nich ten duch, že prorokovali, ale potom nikdy více.'),
(1550241,54,4,11,26,'Byli pak zůstali v staních dva muži, jméno jednoho Eldad, a druhého Medad, na nichž také odpočinul duch ten, nebo i oni napsani byli, ačkoli nevyšli k stánku. I ti také prorokovali v staních.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550242,54,4,11,27,'Tedy přiběh služebník, oznámil to Mojžíšovi, řka: Eldad a Medad prorokují v staních.'),
(1550243,54,4,11,28,'Jozue pak, syn Nun, služebník Mojžíšův, jeden z mládenců jeho, dí k tomu: Pane můj, Mojžíši, zabraň jim.'),
(1550244,54,4,11,29,'Jemuž odpověděl Mojžíš: Proč ty horlíš pro mne? Nýbrž ó kdyby všecken lid Hospodinův proroci byli, a aby dal Hospodin ducha svého na ně!'),
(1550245,54,4,11,30,'I navrátil se Mojžíš do stanů s staršími Izraelskými.'),
(1550246,54,4,11,31,'Tedy strhl se vítr od Hospodina, a zachvátiv křepelky od moře, spustil je na stany tak široce a dlouze, co by mohl za jeden den cesty ujíti všudy vůkol táboru, takměř na dva lokty zvýší nad zemí.'),
(1550247,54,4,11,32,'Protož vstav lid, celý ten den a celou noc, i celý druhý den shromažďovali sobě ty křepelky; a kdož nejméně nashromáždil, měl jich s deset měr. I rozvěšeli je sobě pořád okolo stanů.'),
(1550248,54,4,11,33,'Ještě maso vězelo v zubích jejich, a nebylo právě sžvýkáno, když hněv Hospodinův vzbudil se na lid. I ranil Hospodin lid ranou velikou náramně.'),
(1550249,54,4,11,34,'Protož nazváno jest jméno místa toho Kibrot Hattáve; nebo tu pochovali lid, kterýž žádal masa.'),
(1550250,54,4,11,35,'I bral se lid z Kibrot Hattáve na poušť Hazerot, a pozůstali v Hazerot.'),
(1550251,54,4,12,1,'A mluvila Maria i Aron proti Mojžíšovi příčinou manželky Madianky, kterouž sobě vzal; nebo byl pojal manželku Madianku.'),
(1550252,54,4,12,2,'A řekli: Zdaliž jen toliko skrze Mojžíše mluvil Hospodin? Zdaž také nemluvil skrze nás? I slyšel to Hospodin.'),
(1550253,54,4,12,3,'(Byl pak Mojžíš člověk nejtišší ze všech lidí, kteříž byli na tváři země).'),
(1550254,54,4,12,4,'A ihned řekl Hospodin Mojžíšovi a Aronovi i Marii: Vyjděte vy tři k stánku úmluvy. I vyšli toliko oni tři.'),
(1550255,54,4,12,5,'Tedy sstoupil Hospodin v sloupu oblakovém, a stál u dveří stánku. I zavolal Arona a Marie, a vyšli oba dva.'),
(1550256,54,4,12,6,'Jimž řekl: Slyšte nyní slova má: Prorok když jest mezi vámi, já Hospodin u vidění ukáži se jemu, ve snách mluviti budu s ním.'),
(1550257,54,4,12,7,'Ale není takový služebník můj Mojžíš, kterýž ve všem domě mém věrný jest.'),
(1550258,54,4,12,8,'Ústy k ústům mluvím s ním, ne u vidění, ani v zavinutí, a podobnost Hospodinovu spatřuje. Pročež jste tedy neostýchali se mluviti proti služebníku mému Mojžíšovi?'),
(1550259,54,4,12,9,'I roznícena jest prchlivost Hospodinova na ně, a odšel.'),
(1550260,54,4,12,10,'Oblak také zdvihl se s stánku. A aj, Maria byla malomocná, bílá jako sníh. A pohleděl Aron na Marii, ana malomocná.'),
(1550261,54,4,12,11,'Tedy řekl Aron Mojžíšovi: Poslyš mne, pane můj, prosím, nevzkládej na nás té pokuty za hřích ten, jehož jsme se bláznivě dopustili, a jímž jsme zhřešili.'),
(1550262,54,4,12,12,'Prosím, ať není tato jako mrtvý plod, kterýž když vychází z života matky své, polovici těla jeho zkaženého bývá.'),
(1550263,54,4,12,13,'I volal Mojžíš k Hospodinu, řka: Ó Bože silný, prosím, uzdraviž ji.'),
(1550264,54,4,12,14,'Odpověděl Hospodin Mojžíšovi: Kdyby otec její plinul jí na tvář, zdaž by se nemusila styděti za sedm dní? Protož ať jest vyobcována ven z stanů za sedm dní, a potom zase uvedena bude.'),
(1550265,54,4,12,15,'Tedy vyloučena jest Maria ven z stanů za sedm dní; a lid nehnul se odtud, až zase uvedena jest Maria.'),
(1550266,54,4,13,1,'Potom pak bral se lid z Hazerot, a položil se na poušti Fáran.'),
(1550267,54,4,13,2,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550268,54,4,13,3,'Pošli sobě muže, kteříž by spatřili zemi Kananejskou, kterouž já dám synům Izraelským; jednoho muže z každého pokolení otců jejich vyšlete, ty, kteříž by byli přednější mezi nimi.'),
(1550269,54,4,13,4,'Poslal je tedy Mojžíš z pouště Fáran, jakž byl rozkázal Hospodin; a všickni ti muži byli knížata mezi syny Izraelskými.'),
(1550270,54,4,13,5,'Tato jsou pak jména jejich: Z pokolení Ruben Sammua, syn Zakurův;'),
(1550271,54,4,13,6,'Z pokolení Simeon Safat, syn Huri;'),
(1550272,54,4,13,7,'Z pokolení Juda Kálef, syn Jefonův;'),
(1550273,54,4,13,8,'Z pokolení Izachar Igal, syn Jozefův;'),
(1550274,54,4,13,9,'Z pokolení Efraim Ozeáš, syn Nun;'),
(1550275,54,4,13,10,'Z pokolení Beniamin Falti, syn Rafův;'),
(1550276,54,4,13,11,'Z pokolení Zabulon Gaddehel, syn Sodi;'),
(1550277,54,4,13,12,'Z pokolení Jozef a z pokolení Manasses Gaddi, syn Susi;'),
(1550278,54,4,13,13,'Z pokolení Dan Amiel, syn Gemalův;'),
(1550279,54,4,13,14,'Z pokolení Asser Setur, syn Michaelův;'),
(1550280,54,4,13,15,'Z pokolení Neftalím Nahabi, syn Vafsi;'),
(1550281,54,4,13,16,'Z pokolení Gád Guhel, syn Máchův;'),
(1550282,54,4,13,17,'Ta jsou jména mužů, kteréž poslal Mojžíš, aby shlédli zemi. I přezděl Mojžíš Ozeovi, synu Nun, Jozue.'),
(1550283,54,4,13,18,'Tedy poslal je Mojžíš, aby prohlédli zemi Kananejskou, a řekl jim: Jděte tudyto při straně polední a vejděte na hory.'),
(1550284,54,4,13,19,'A shlédněte, jaká jest země ta, i lid, kterýž bydlí v ní, silný-li jest či mdlý? málo-li jich, či mnoho?'),
(1550285,54,4,13,20,'A jaká jest též země ta, v níž on bydlí, dobrá-li jest, či zlá? a jaká jsou města, v nichž přebývají, v staních-li, či v hrazených místech?'),
(1550286,54,4,13,21,'Tolikéž jaká jest země, úrodná-li, či neúrodná, jest-li na ní stromoví, či není? A buďte udatné mysli, a přineste nám z ovoce té země. A byl tehdáž čas, v němžto hroznové zaměkali.'),
(1550287,54,4,13,22,'Odšedše tedy, prohlédli tu zemi od pouště Tsin až do Rohob, kudy se jde do Emat.'),
(1550288,54,4,13,23,'I šli stranou polední, a přišli až do Hebronu, kdežto byli Achiman a Sesai a Tolmai, synové Enakovi. Hebron pak o sedm let prvé ustaveno jest, nežli Soan, město Egyptské.'),
(1550289,54,4,13,24,'Potom přišli až do údolí Eškol, a tu uřezali ratolest s hroznem jedním jahodek plným, a nesli jej na sochoře dva; též i jablka zrnatá i fíky té země.'),
(1550290,54,4,13,25,'I nazváno jest to místo Nehel Eškol, od hroznu, kterýž tu uřezali synové Izraelští.'),
(1550291,54,4,13,26,'Navrátili se pak zase, prošedše zemi, po čtyřidcíti dnech.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550292,54,4,13,27,'A jdouce, přišli k Mojžíšovi a k Aronovi i ke všemu množství synů Izraelských, na poušti Fáran v Kádes, a oznámili jim i všemu množství to, co spravili, a ukázali jim ovoce země té.'),
(1550293,54,4,13,28,'A vypravujíce jim, řekli: Přišli jsme do země, do kteréž jsi nás poslal, kteráž v pravdě oplývá mlékem a strdí, a toto jest ovoce její.'),
(1550294,54,4,13,29,'Než že lid jest silný, kterýž bydlí v zemi té, města také pevná jsou a veliká velmi, k tomu i syny Enakovy tam jsme viděli.'),
(1550295,54,4,13,30,'Amalech bydlí v kraji poledním, a Hetejský, Jebuzejský a Amorejský bydlejí na horách, Kananejský pak bydlí při moři a při břehu Jordánském.'),
(1550296,54,4,13,31,'I krotil Kálef lid bouřící se proti Mojžíšovi, a mluvil: Jděme předce, a opanujme zemi, nebo zmocníme se jí.'),
(1550297,54,4,13,32,'Ale muži ti, kteříž chodili s ním, pravili: Nikoli nebudeme moci vstoupiti proti lidu tomu, nebo silnější jest nežli my.'),
(1550298,54,4,13,33,'I zhaněli a zošklivili zemi shlédnutou synům Izraelským, mluvíce: Země, již jsme prošli a spatřili, jest země taková, ješto hubí obyvatele své; a všecken lid, kterýž jsme viděli u prostřed ní, jsou muži postavy vysoké velmi.'),
(1550299,54,4,13,34,'Také jsme tam viděli obry, syny Enakovy, kteříž jsou větší než jiní obrové, ješto se nám zdálo, že jsme proti nim jako kobylky,a takoví jsme se i jim zdáli.'),
(1550300,54,4,14,1,'Tehdy pozdvihše se všecko množství, křičeli, a plakal lid v tu noc.'),
(1550301,54,4,14,2,'A reptali proti Mojžíšovi i proti Aronovi všickni synové Izraelští, a řeklo k nim všecko množství: Ó bychom byli zemřeli v zemi Egyptské, aneb na této poušti, ó bychom byli zemřeli!'),
(1550302,54,4,14,3,'A proč Hospodin vede nás do země té, abychom padli od meče, ženy naše i dítky naše aby byly v loupež? Není-liž nám lépe navrátiti se zase do Egypta?'),
(1550303,54,4,14,4,'I řekli jeden druhému: Ustanovme sobě vůdci, a navraťme se do Egypta.'),
(1550304,54,4,14,5,'Tedy padli Mojžíš a Aron na tváři své přede vším množstvím shromáždění synů Izraelských.'),
(1550305,54,4,14,6,'Jozue pak, syn Nun, a Kálef, syn Jefonův, z těch, kteříž byli shlédli zemi, roztrhli roucha svá,'),
(1550306,54,4,14,7,'A mluvili ke všemu množství synů Izraelských, řkouce: Země, kterouž jsme prošli a vyšetřili, jest země velmi velice dobrá.'),
(1550307,54,4,14,8,'Bude-li Hospodin laskav na nás, uvedeť nás do země té, a dá ji nám, a to zemi takovou, kteráž oplývá mlékem a strdí.'),
(1550308,54,4,14,9,'Toliko nepozdvihujte se proti Hospodinu, ani se bojte lidu země té, nebo jako chléb náš jsou. Odešlatě od nich ochrana jejich, ale s námi jest Hospodin; nebojtež se jich.'),
(1550309,54,4,14,10,'Tedy mluvilo všecko množství, aby je kamením uházeli, ale sláva Hospodinova ukázala se nad stánkem úmluvy všechněm synům Izraelským.'),
(1550310,54,4,14,11,'I řekl Hospodin Mojžíšovi: I dokavadž popouzeti mne bude lid ten? A dokud nebudou mi věřiti pro tak mnohá znamení, kteráž jsem činil u prostřed nich?'),
(1550311,54,4,14,12,'Raním jej morem a rozženu jej, tebe pak učiním v národ veliký a silnější, nežli jest tento.'),
(1550312,54,4,14,13,'I řekl Mojžíš Hospodinu: Ale uslyšíť to Egyptští, z jejichž prostředku vyvedl jsi lid tento v síle své,'),
(1550313,54,4,14,14,'A řeknou s obyvateli země té: (nebo slyšeli, že jsi ty, ó Hospodine, byl u prostřed lidu tohoto, a že jsi okem v oko spatřován byl, ó Hospodine, a oblak tvůj stál nad nimi, a v sloupě oblakovém předcházel jsi je ve dne, a v sloupě ohnivém v noci),'),
(1550314,54,4,14,15,'Když tedy zmoříš lid ten, všecky až do jednoho, mluviti budou národové, kteříž slyšeli pověst o tobě, říkajíce:'),
(1550315,54,4,14,16,'Proto že nemohl Hospodin uvésti lidu toho do země, kterouž jim s přísahou zaslíbil, zmordoval je na poušti.'),
(1550316,54,4,14,17,'Nyní tedy, prosím, nechať jest zvelebena moc Páně, jakož jsi mluvil, řka:'),
(1550317,54,4,14,18,'Hospodin dlouhočekající a hojný v milosrdenství, odpouštějící nepravost a přestoupení, kterýž však z vinného nečiní nevinného, ale navštěvuje nepravost otců na synech do třetího i čtvrtého pokolení.'),
(1550318,54,4,14,19,'Odpusť, prosím, nepravost lidu tohoto podlé velikého milosrdenství svého, tak jako jsi odpouštěl lidu tomuto, jakž vyšel z Egypta až dosavad.'),
(1550319,54,4,14,20,'I řekl Hospodin: Odpustil jsem vedlé slova tvého.'),
(1550320,54,4,14,21,'A však živ jsem já, a sláva má naplňuje všecku zemi,'),
(1550321,54,4,14,22,'Že všickni ti, kteříž viděli slávu mou a znamení má, kteráž jsem činil v Egyptě a na poušti této, a kteříž pokoušeli mne již desetkrát, aniž uposlechli hlasu mého,'),
(1550322,54,4,14,23,'Neuzří země té, kterouž jsem s přísahou zaslíbil otcům jejich, aniž jí kdo z těch, kteříž mne popouzeli, uhlédá.'),
(1550323,54,4,14,24,'Ale služebníka svého Kálefa, (nebo v něm byl jiný duch, a cele následoval mne), uvedu jej do země, do kteréž chodil, a símě jeho dědičně obdrží ji.'),
(1550324,54,4,14,25,'Ale poněvadž Amalechitský a Kananejský bydlí v tom údolí, obraťte se zase zítra, a beřte se na poušť cestou k moři Rudému.'),
(1550325,54,4,14,26,'Mluvil také Hospodin k Mojžíšovi a Aronovi, řka:'),
(1550326,54,4,14,27,'Až dokud snášeti budu množství toto zlé, kteréž repce proti mně? Až dokud reptání synů Izraelských, kteříž repcí proti mně, slyšeti budu?'),
(1550327,54,4,14,28,'Rci jim: Živ jsem já, praví Hospodin, žeť vám učiním tak, jakž jste mluvili v uši mé:'),
(1550328,54,4,14,29,'Na poušti této padnou mrtvá těla vaše, a všickni, kteříž jste sečteni, podlé všeho počtu vašeho od majících let dvadceti a výše, kteříž jste reptali proti mně,'),
(1550329,54,4,14,30,'Nevejdete, pravím, vy do země, o kteréž, zdvihna ruku svou, přisáhl jsem, že vás osadím v ní, jediné Kálef, syn Jefonův, a Jozue, syn Nun.'),
(1550330,54,4,14,31,'Ale dítky vaše malé, o nichž jste řekli, že v loupež budou, ty uvedu, aby užívali země té, kterouž jste vy pohrdli.'),
(1550331,54,4,14,32,'Těla pak vaše mrtvá padnou na poušti této.'),
(1550332,54,4,14,33,'A synové vaši budou tuláci na poušti této čtyřidceti let, a ponesou pokutu smilství vašeho, až do konce vyhynou těla vaše na poušti.'),
(1550333,54,4,14,34,'Podlé počtu dnů, v nichž jste procházeli zemi tu, totiž čtyřidceti dnů, jeden každý den za rok počítaje, ponesete nepravosti své čtyřidceti let, a poznáte pomstu svého odtržení se ode mne.'),
(1550334,54,4,14,35,'Já Hospodin mluvil jsem, že to učiním všemu tomuto množství zlému, kteréž se zrotilo proti mně; na poušti této do konce zhynou, a tu zemrou.'),
(1550335,54,4,14,36,'Muži pak ti, kteréž poslal byl Mojžíš k shlédnutí země té, a kteříž, navrátivše se, uvedli v reptání proti němu všecko množství to, haněním ošklivíce zemi,'),
(1550336,54,4,14,37,'Ti, řku, muži, kteříž haněli zemi, ranou těžkou zemřeli před Hospodinem.'),
(1550337,54,4,14,38,'Jozue pak, syn Nun, a Kálef, syn Jefonův, živi zůstali z mužů těch, kteříž chodili k vyšetření země.'),
(1550338,54,4,14,39,'Tedy mluvil Mojžíš slova ta ke všechněm synům Izraelským; i plakal lid velmi.'),
(1550339,54,4,14,40,'A vstavše ráno, vstoupili na vrch hory, a řekli: Aj, my hotovi jsme, abychom šli k místu, o němž mluvil Hospodin; nebo jsme zhřešili.'),
(1550340,54,4,14,41,'Jimž řekl Mojžíš: Proč jest to, že vy přestupujete přikázaní Hospodinovo? ješto vám to na dobré nevyjde.'),
(1550341,54,4,14,42,'Nevstupujte, nebo Hospodin není u prostřed vás, abyste nebyli poraženi od nepřátel vašich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550342,54,4,14,43,'Amalechitský zajisté a Kananejský jest tu před vámi, a padnete od meče, proto že jste se odvrátili od následování Hospodina, aniž také Hospodin bude s vámi.'),
(1550343,54,4,14,44,'Oni pak předce usilovali vstoupiti na vrch hory, ale truhla smlouvy Hospodinovy a Mojžíš nevycházeli z stanů.'),
(1550344,54,4,14,45,'Tedy sstoupili Amalechitský a Kananejský, kteříž bydlili na těch horách, a porazili je, a potírali je až do Horma.'),
(1550345,54,4,15,1,'Mluvil opět Hospodin k Mojžíšovi, řka:'),
(1550346,54,4,15,2,'Mluv k synům Izraelským a rci jim: Když vejdete do země přebývání vašich, kterouž já dám vám,'),
(1550347,54,4,15,3,'A budete chtíti obětovati obět ohnivou Hospodinu v zápal, aneb obět buď slíbenou, buď dobrovolnou, aneb při slavnostech vašich, abyste učinili vůni spokojující Hospodina, buďto z skotů, aneb z drobného dobytku:'),
(1550348,54,4,15,4,'Tedy kdož by koli obětoval dar svůj Hospodinu, obětuj obět suchou, desátý díl efi mouky bělné, zadělané olejem, jehož bude čtvrtý díl míry hin.'),
(1550349,54,4,15,5,'A vína v obět mokrou čtvrtinku hin obětovati budeš při zápalu, aneb při oběti vítězné k jednomu každému beránku.'),
(1550350,54,4,15,6,'Při beranu pak obětovati budeš obět suchou, mouky bělné dvě desetiny, zadělané olejem, třetinkou míry hin.'),
(1550351,54,4,15,7,'Vína také k oběti mokré třetí díl míry hin obětovati budeš u vůni spokojující Hospodina.'),
(1550352,54,4,15,8,'Jestliže pak obětovati budeš volka v obět zápalnou, aneb v obět k splnění slibu, aneb v obět pokojnou Hospodinu:'),
(1550353,54,4,15,9,'Tedy budeš obětovati spolu s volkem obět suchou, tři desetiny mouky bělné, zadělané olejem, jehož by byla půlka hin.'),
(1550354,54,4,15,10,'A vína k oběti mokré obětovati budeš půlku hin. Ta jest obět ohnivá vůně spokojující Hospodina.'),
(1550355,54,4,15,11,'Tak uděláte s každým volem i s každým skopcem, i s dobytčetem buď ono z ovec neb z koz.'),
(1550356,54,4,15,12,'Podlé toho, jakž mnoho jich obětovati budete, tak se zachováte při jednom každém z nich.'),
(1550357,54,4,15,13,'Všeliký obyvatel tak bude to vykonávati, aby obětoval obět ohnivou vůně spokojující Hospodina.'),
(1550358,54,4,15,14,'Takž bude-li u vás i příchozí, aneb kdokoli mezi vámi v pronárodech vašich, a bude obětovati obět ohnivou vůně spokojující Hospodina, jakž vy se při tom chováte, tak i on chovati se bude.'),
(1550359,54,4,15,15,'V shromáždění tomto ustanovení jednostejné buď vám i příchozímu, kterýž by u vás byl, ustanovení věčné v pronárodech vašich; jakož vy, tak příchozí bude před Hospodinem.'),
(1550360,54,4,15,16,'Zákon jednostejný a pořádek jednostejný bude vám i přichozímu kterýž by u vás byl.'),
(1550361,54,4,15,17,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1550362,54,4,15,18,'Mluv k synům Izraelským a rci jim: Když přijdete do země, do kteréž já uvedu vás,'),
(1550363,54,4,15,19,'Tedy, když počnete jísti chléb země, obětovati budete obět vzhůru pozdvižení Hospodinu.'),
(1550364,54,4,15,20,'Z prvotin těsta vašeho koláč obětovati budete v obět vzhůru pozdvižení; tak jako obět z humna, obětovati budete ji.'),
(1550365,54,4,15,21,'Z prvotin těsta vašeho dávati budete Hospodinu obět vzhůru pozdvižení, vy i potomci vaši.'),
(1550366,54,4,15,22,'A když byste pozbloudili, a neučinili všech přikázaní těch, kteráž mluvil Hospodin k Mojžíšovi,'),
(1550367,54,4,15,23,'Totiž všech věcí, kteréž přikázal Hospodin vám skrze Mojžíše, od toho dne, v kterémž přikázaní vydal Hospodin, i potom v pronárodech vašich:'),
(1550368,54,4,15,24,'Tedy jestliže z nedopatření všeho shromáždění to stalo se, obětovati bude všecko množství volka mladého jednoho v obět zápalnou, k vůni spokojující Hospodina, též obět suchou, a obět mokrou při něm podlé pořádku, a kozla jednoho v obět za hřích.'),
(1550369,54,4,15,25,'I očistí kněz všecko množství synů Izraelských, a odpuštěno jim bude; nebo poblouzení jest. A oni také obětovati budou obět svou, obět ohnivou Hospodinu, a obět za hřích svůj před Hospodinem za poblouzení své.'),
(1550370,54,4,15,26,'I bude odpuštěno všemu shromáždění synů Izraelských i příchozímu, kterýž jest pohostinu u prostřed nich; nebo všeho lidu poblouzení jest.'),
(1550371,54,4,15,27,'Jestliže by pak člověk jeden zhřešil z poblouzení, bude obětovati kozu roční v obět za hřích.'),
(1550372,54,4,15,28,'I očistí kněz duši pobloudilou, kteráž zhřešila poblouzením před Hospodinem; očistí ji, a budeť jí odpuštěno.'),
(1550373,54,4,15,29,'Domácímu mezi syny Izraelskými i příchozímu, kterýž pohostinu mezi nimi jest, zákon tento jednostejný bude vám, když by kdo zhřešil z poblouzení.'),
(1550374,54,4,15,30,'Člověk pak, kterýž by z pychu svévolně zhřešil, tak doma zrozený jako příchozí, takový potupil velice Hospodina; protož vyhlazen bude z prostředku lidu svého.'),
(1550375,54,4,15,31,'Nebo slovem Hospodinovým pohrdl, a přikázaní jeho za nic sobě položil; protož konečně vyhlazen bude člověk ten, a nepravost jeho zůstane na něm.'),
(1550376,54,4,15,32,'Stalo se pak, když synové Izraelští byli na poušti, že nalezli jednoho, an sbírá dříví v den sobotní.'),
(1550377,54,4,15,33,'A ti, kteříž ho nalezli sbírajícího dříví, přivedli jej k Mojžíšovi a k Aronovi i ke všemu množství.'),
(1550378,54,4,15,34,'I dali jej do vězení; nebo ještě nebylo jim oznámeno, co by s ním mělo činěno býti.'),
(1550379,54,4,15,35,'I řekl Hospodin Mojžíšovi: Smrtí ať umře člověk ten; nechať ho bez milosti ukamenuje všecko množství vně za stany.'),
(1550380,54,4,15,36,'A protož vyvedli jej všecko množství ven za stany, a uházeli ho kamením, až umřel, jakož rozkázal Hospodin.'),
(1550381,54,4,15,37,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550382,54,4,15,38,'Mluv k synům Izraelským a rci jim, ať sobě dělají třepení široké na podolcích oděvů svých všickni rodové jejich, a ať dávají nad třepením šňůrku modrou.'),
(1550383,54,4,15,39,'A to budete míti za premování, na něžto hledíce, rozpomínati se budete na všecka přikázaní Hospodinova, abyste je činili, a nepustíte se po žádosti srdce svého, a po očích svých, jichžto následujíce, smilnili byste,'),
(1550384,54,4,15,40,'Ale abyste pamatovali a činili všecka přikázaní má, a byli svatí Bohu svému.'),
(1550385,54,4,15,41,'Já jsem Hospodin Bůh váš, kterýž jsem vyvedl vás z země Egyptské, abych vám byl za Boha: Já Hospodin Bůh váš.'),
(1550386,54,4,16,1,'Chóre pak syn Izarův, syna Kahat z pokolení Léví, vytrhl se z jiných, tolikéž Dátan a Abiron, synové Eliabovi, také Hon, syn Feletův, z synů Rubenových,'),
(1550387,54,4,16,2,'A povstali proti Mojžíšovi, i jiných mužů z synů Izraelských dvě stě a padesáte, knížata shromáždění, kteříž svoláváni byli do rady, muži slovoutní.'),
(1550388,54,4,16,3,'A sebravše se proti Mojžíšovi a proti Aronovi, řekli jim: Příliště to již na vás; všecko zajisté množství toto, všickni tito svatí jsou, a u prostřed nich jest Hospodin. Pročež se tedy vyzdvihujete nad shromážděním Hospodinovým?'),
(1550389,54,4,16,4,'To když uslyšel Mojžíš, padl na tvář svou,'),
(1550390,54,4,16,5,'A mluvil k Chóre a ke vší rotě jeho, řka: Ráno ukáže Hospodin, kdo jsou jeho, a kdo jest svatý, i kdo před něj předstupovati má; nebo kohožkoli vyvolil, tomu rozkáže přistoupiti k sobě.'),
(1550391,54,4,16,6,'Toto učiňte: Vezměte sobě kadidlnice, ty Chóre i všecko shromáždění tvé,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550392,54,4,16,7,'A naklaďte do nich uhlí, a vložte na ně kadidla před Hospodinem zítra; i stane se, že kohožkoli vyvolí Hospodin, ten bude svatý. Příliště to již na vás, synové Léví.'),
(1550393,54,4,16,8,'I řekl Mojžíš k Chóre: Slyšte, prosím, synové Léví.'),
(1550394,54,4,16,9,'Zdaliž málo vám to jest, že vás oddělil Bůh Izraelský ode všeho množství Izraelského, a rozkázal vám přistupovati k sobě, abyste vykonávali službu příbytku Hospodinova, a abyste stáli před shromážděním, a sloužili jim,'),
(1550395,54,4,16,10,'A vzal tě sobě, a všecky bratří tvé syny Léví s tebou, a že ještě přes to i kněžství hledáte?'),
(1550396,54,4,16,11,'Protož věz, že ty a všickni tvoji jste ti, kteříž se rotíte proti Hospodinu; nebo Aron co jest, že jste reptali proti němu?'),
(1550397,54,4,16,12,'Tedy poslal Mojžíš, aby zavolali Dátana a Abirona, synů Eliabových. Kteříž odpověděli: Nepůjdem.'),
(1550398,54,4,16,13,'Cožť se ještě málo zdá, že jsi vyvedl nás z země oplývající mlékem a strdí, abys nás zmořil na poušti, že také chceš i panovati nad námi, a rozkazovati nám?'),
(1550399,54,4,16,14,'A ještě jsi nás neuvedl do země oplývající mlékem a strdí, aniž jsi nám dal v dědictví rolí a vinic. Zdali oči mužům těmto vyloupiti chceš? Nepůjdeme.'),
(1550400,54,4,16,15,'I rozhněval se Mojžíš velmi, a řekl k Hospodinu: Nepatřiž na oběti jejich. Ani jednoho osla od nich jsem nevzal, aniž jsem komu z nich co zlého učinil.'),
(1550401,54,4,16,16,'Potom řekl Mojžíš k Chóre: Ty a všickni tvoji, postavte se zítra před Hospodinem, ty i oni, též i Aron.'),
(1550402,54,4,16,17,'A vezmouce jeden každý kadidlnici svou, dáte do nich kadidla, a postavíte se před Hospodinem, jeden každý s kadidlnicí svou; dvě stě a padesáte kadidlnic bude, ty také i Aron, každý s kadidlnicí svou.'),
(1550403,54,4,16,18,'Tedy vzal jeden každý kadidlnici svou, a nabravše do nich uhlí, vložili na ně i kadidla, a stáli u dveří stánku úmluvy, i Mojžíši Aron.'),
(1550404,54,4,16,19,'Chóre pak již byl sebral proti nim všecko množství ke dveřím stánku úmluvy; i ukázala se sláva Hospodinova všemu množství.'),
(1550405,54,4,16,20,'I mluvil Hospodin k Mojžíšovi a k Aronovi, řka:'),
(1550406,54,4,16,21,'Oddělte se z prostředku množství tohoto, ať je v okamžení zahladím.'),
(1550407,54,4,16,22,'Kteřížto padše na tváři své, řekli: Bože silný, Bože duchů i všelikého těla, jediný tento člověk zhřešil, a což na všecko shromáždění hněvati se budeš?'),
(1550408,54,4,16,23,'Tedy mluvil Hospodin k Mojžíšovi, řka:'),
(1550409,54,4,16,24,'Mluv k množství a rci: Odstupte od příbytku Chóre, Dátana a Abirona.'),
(1550410,54,4,16,25,'A vstav Mojžíš, šel k Dátanovi a Abironovi; i šli za ním starší Izraelští.'),
(1550411,54,4,16,26,'A mluvil k množství, řka: Odstupte, prosím, od stanů bezbožných mužů těchto, aniž se čeho dotýkejte, což jejich jest, abyste nebyli zachváceni ve všech hříších jejich.'),
(1550412,54,4,16,27,'I odstoupili se všech stran od příbytku Chóre, Dátana a Abirona; ale Dátan a Abiron vyšedše, stáli u dveří stanů svých, i ženy jejich a synové jejich, i maličcí jejich.'),
(1550413,54,4,16,28,'Tedy řekl Mojžíš: Po tomto poznáte, že Hospodin poslal mne, abych činil všecky skutky tyto, a že nic o své ujmě nečiním:'),
(1550414,54,4,16,29,'Jestliže tak jako jiní lidé mrou, zemrou i tito, a navštívením obecným všechněm lidem jestliže navštíveni budou, neposlal mne Hospodin.'),
(1550415,54,4,16,30,'Pakliť něco nového učiní Hospodin, a země, otevra ústa svá, požře je se vším, což mají, a sstoupí-li za živa do pekla, tedy poznáte, že jsou popouzeli muži ti Hospodina.'),
(1550416,54,4,16,31,'I stalo se, když přestal mluviti slov těch, že rozstoupila se země pod nimi.'),
(1550417,54,4,16,32,'A otevřevši země ústa svá, požřela je i domy jejich i všecky lidi, kteříž byli s Chóre, i všecken statek jejich.'),
(1550418,54,4,16,33,'A tak sstoupili oni se vším, což měli, za živa do pekla, a přikryla je země; i zahynuli z prostředku shromáždění.'),
(1550419,54,4,16,34,'Všickni pak Izraelští, kteříž byli vůkol nich, utíkali, slyšíce křik jejich; nebo řekli: Utecme, aby i nás nesehltila země.'),
(1550420,54,4,16,35,'Vyšel také oheň od Hospodina, a spálil těch dvě stě a padesáte mužů, kteříž kadili.'),
(1550421,54,4,16,36,'Tedy mluvil Hospodin k Mojžíšovi, řka:'),
(1550422,54,4,16,37,'Rci Eleazarovi, synu Arona kněze, ať sbéře kadidlnice z toho spáleniště, a uhlí z nich pryč rozmece, nebo posvěceny jsou,'),
(1550423,54,4,16,38,'Kadidlnice totiž těch, kteříž proti svým dušem hřešili, a ať je rozkuje na plechy k obložení oltáře; nebo kadili jimi před Hospodinem, protož posvěceny jsou, a budou na znamení synům Izraelským.'),
(1550424,54,4,16,39,'I sebral Eleazar kněz kadidlnice měděné, jimiž kadili ti, kteříž spáleni jsou, a rozkovali je k obložení oltáře,'),
(1550425,54,4,16,40,'Pro budoucí pamět synům Izraelským, aby nepřistupoval žádný jiný, kdož by nebyl z rodu Aronova, k kadění před Hospodinem, aby se mu nestalo jako Chóre a jako rotě jeho, jakož byl mluvil jemu Hospodin skrze Mojžíše.'),
(1550426,54,4,16,41,'Nazejtří pak reptalo všecko množství synů Izraelských na Mojžíše a na Arona, řkouce: Vy jste příčinou smrti lidu Hospodinova.'),
(1550427,54,4,16,42,'I stalo se, když se opět sbíral lid proti Mojžíšovi a proti Aronovi, že se ohlédli k stánku úmluvy, a aj, přikryl jej oblak, a ukázala se sláva Hospodinova.'),
(1550428,54,4,16,43,'Přišel také Mojžíš s Aronem před stánek úmluvy.'),
(1550429,54,4,16,44,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550430,54,4,16,45,'Vyjděte z prostředku množství tohoto, a zahladím je v okamžení. I padli na tváři své.'),
(1550431,54,4,16,46,'Tedy řekl Mojžíš Aronovi: Vezma kadidlnici, dej do ní uhlí z oltáře, a vlož kadidla, a běž rychle k množství a očisť je; nebo vyšla prchlivost od tváři Hospodinovy, a již rána se začala.'),
(1550432,54,4,16,47,'I vzav Aron kadidlnici, jakž rozkázal Mojžíš, běžel do prostřed shromáždění, (a aj, rána již se byla začala v lidu,) a zakadiv, očistil lid.'),
(1550433,54,4,16,48,'A stál mezi mrtvými a živými; i zastavena jest rána.'),
(1550434,54,4,16,49,'Bylo pak těch, kteříž od té rány zemřeli, čtrnácte tisíců a sedm set, kromě těch, jenž zemřeli příčinou Chóre.'),
(1550435,54,4,16,50,'I navrátil se Aron k Mojžíšovi, ke dveřím stánku úmluvy, když ta rána přetržena byla.'),
(1550436,54,4,17,1,'Tedy mluvil Hospodin k Mojžíšovi, řka:'),
(1550437,54,4,17,2,'Mluv k synům Izraelským, a vezmi od nich po jednom prutu z každého domu otců, totiž ode všech knížat jejich, vedlé domů otců jich dvanácte prutů, a jednoho každého jméno napíšeš na prutu jeho.'),
(1550438,54,4,17,3,'Jméno pak Aronovo napíšeš na prutu Léví; nebo jeden každý prut bude místo jednoho předního z domu otců jejich.'),
(1550439,54,4,17,4,'I necháš jich v stánku úmluvy před svědectvím, kdež přicházím k vám.'),
(1550440,54,4,17,5,'I stane se, že kohož vyvolím, toho prut zkvetne; a tak spokojím a svedu s sebe reptání synů Izraelských, kterýmž repcí na vás.'),
(1550441,54,4,17,6,'Ty věci když mluvil Mojžíš k synům Izraelským, dali jemu všecka jejich knížata pruty své, jedno každé kníže prut z domu otce svého, totiž prutů dvanácte, prut pak Aronův byl též mezi pruty jejich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550442,54,4,17,7,'I zanechal Mojžíš prutů před Hospodinem v stánku svědectví.'),
(1550443,54,4,17,8,'Nazejtří pak přišel Mojžíš do stánku svědectví, a aj, vyrostl prut Aronův z domu Léví, a vypustiv z sebe pupence, zkvetl a vydal mandly zralé.'),
(1550444,54,4,17,9,'I vynesl Mojžíš všecky ty pruty od tváři Hospodinovy ke všechněm synům Izraelským; a uzřevše je, vzali jeden každý prut svůj.'),
(1550445,54,4,17,10,'Řekl pak Hospodin Mojžíšovi: Dones zase prut Aronův před svědectví, aby chován byl na znamení proti buřičům zpurným, a tak přítrž učiníš reptání jejich na mne, aby nezemřeli.'),
(1550446,54,4,17,11,'I učinil tak Mojžíš; jakž byl přikázal jemu Hospodin, tak učinil.'),
(1550447,54,4,17,12,'Tedy mluvili synové Izraelští k Mojžíšovi, řkouce: Hle, již mřeme, mizíme a všickni my hyneme.'),
(1550448,54,4,17,13,'Kdožkoli blízko přistoupá k příbytku Hospodinovu, umírá. Všickni-liž smrtí zhyneme?'),
(1550449,54,4,18,1,'A protož řekl Hospodin Aronovi: Ty a synové tvoji i dům otce tvého s tebou ponesete nepravost svatyně; ty také i synové tvoji s tebou ponesete nepravost kněžství svého.'),
(1550450,54,4,18,2,'Bratří také své, pokolení Léví, čeled otce svého připoj k sobě, ať jsou při tobě a posluhují tobě; ty pak a synové tvoji s tebou před stánkem svědectví sloužiti budete.'),
(1550451,54,4,18,3,'A pilně ostříhati budou rozkázaní tvého, bedlivi jsouce při všem stánku; a však ať k nádobám svatyně a k oltáři nepřistupují, aby nezemřeli i oni i vy.'),
(1550452,54,4,18,4,'A přídržeti se budou tebe, pilně ostříhajíce stánku úmluvy při všech službách jeho; a cizí žádný nepřistupuj k vám.'),
(1550453,54,4,18,5,'Protož pilně ostříhejte svatyně i služby oltáře, ať nepřichází více zůřivá prchlivost na syny Izraelské,'),
(1550454,54,4,18,6,'Poněvadž jsem já vybral bratří vaše Levíty z synů Izraelských vám, za dar dané Hospodinu, aby konali službu při stánku úmluvy.'),
(1550455,54,4,18,7,'Ty pak a synové tvoji s tebou ostříhati budete kněžství svého při všech věcech přináležejících k oltáři, a kteréž jsou za oponou, a sloužiti budete. Úřad kněžství vašeho darem jsem vám dal, protož, přistoupil-li by kdo cizí, umře.'),
(1550456,54,4,18,8,'Mluvil také Hospodin k Aronovi: Aj, já dal jsem tobě k ostříhání oběti své, kteréž se vzhůru pozdvihují; všecko také, což se posvěcuje od synů Izraelských, tobě jsem dal pro pomazání i synům tvým ustanovením věčným.'),
(1550457,54,4,18,9,'Toto bude tvé z věcí posvěcených, kteréž nepřicházejí na oheň: Všeliká obět jejich, buď suchá obět jejich, neb obět za hřích jejich, aneb obět za provinění jejich, kteréž mi dávati budou, svatosvaté tobě bude to i synům tvým.'),
(1550458,54,4,18,10,'V svatyni budeš je jísti, každý pohlaví mužského bude je jísti; svaté bude tobě.'),
(1550459,54,4,18,11,'Tvá tedy bude obět darů jejich, kteráž vzhůru pozdvižena bývá; každou také obět synů Izraelských, kteráž sem i tam obracína bývá, tobě jsem dal a synům tvým, i dcerám tvým s tebou ustanovením věčným. Každý, kdož jest čistý v domě tvém, bude je jísti.'),
(1550460,54,4,18,12,'Všecko, což předního jest z oleje, a což nejlepšího jest vína a obilé, prvotiny těch věcí, kteréž dají Hospodinu, dal jsem tobě.'),
(1550461,54,4,18,13,'Prvotiny všech věcí, kteréž rostly v zemi jejich, ty přinesou Hospodinu, a tvé budou. Každý, kdož jest čistý v domě tvém, jísti je bude.'),
(1550462,54,4,18,14,'Všecko oddané Bohu v Izraeli tvé bude.'),
(1550463,54,4,18,15,'Cožkoli otvírá život všelikého těla, kteréž obětováno bývá Hospodinu, tak z lidí jako z hovad, tvé bude; prvorozené však z lidí, vyplaceno bude, prvorozené také z nečistých hovad vyplatiti kážeš.'),
(1550464,54,4,18,16,'Výplata pak jeho, když mu již jeden měsíc bude, vedlé ceny tvé bude pěti loty stříbra podlé lotu svatyně; dvadceti peněz váží lot.'),
(1550465,54,4,18,17,'Ale prvorozeného z volů, neb z ovcí, neb z koz, nedáš vyplatiti; nebo posvěceny jsou. Krev jejich vykropíš na oltář, a tuk jejich zapálíš, aby byl obětí ohnivou vůně spokojující Hospodina.'),
(1550466,54,4,18,18,'Maso pak jejich tvé bude; jako hrudí z oběti sem i tam obracení, a jako plece pravé tvé bude.'),
(1550467,54,4,18,19,'Každou obět vzhůru pozdvižení z věcí posvěcených, kteréž přinášejí synové Izraelští Hospodinu, dal jsem tobě, a synům tvým, i dcerám tvým s tebou ustanovením věčným, smlouvou trvánlivou a věčnou před Hospodinem, tobě i semeni tvému s tebou.'),
(1550468,54,4,18,20,'Mluvil také Hospodin k Aronovi: V zemi jejich, dědictví ani dílu svého mezi nimi nebudeš míti; já jsem díl tvůj, a dědictví tvé u prostřed synů Izraelských.'),
(1550469,54,4,18,21,'Synům pak Léví, aj, dal jsem všecky desátky v Izraeli za dědictví, za službu jejich, kterouž vykonávají, sloužíce při stánku úmluvy.'),
(1550470,54,4,18,22,'A synové Izraelští nechať nepřistupují k stánku úmluvy, aby nenesli hříchu a nezemřeli.'),
(1550471,54,4,18,23,'Ale sami Levítové konati budou službu při stánku úmluvy, a sami ponesou nepravost svou. Ustanovení věčné v pronárodech vašich to bude, aby dědictví nemívali mezi syny Izraelskými.'),
(1550472,54,4,18,24,'Nebo desátky synů Izraelských, kteréž přinášeti budou Hospodinu v obět vzhůru pozdvižení, dal jsem Levítům za dědictví; protož jsem o nich řekl: U prostřed synů Izraelských nebudou míti dědictví.'),
(1550473,54,4,18,25,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550474,54,4,18,26,'Mluv k Levítům a rci jim: Když vezmete desátky od synů Izraelských, kteréž jsem vám dal od nich za dědictví vaše, tedy přinesete z nich obět vzhůru pozdvižení Hospodinu, desátky z desátků.'),
(1550475,54,4,18,27,'A počtena vám bude ta obět vaše jako obilí z humna, a jako víno od presu.'),
(1550476,54,4,18,28,'Tak vy také přinesete obět vzhůru pozdvižení Hospodinu ze všech desátků svých, kteréž vezmete od synů Izraelských, a dáte z nich obět Hospodinovu Aronovi knězi.'),
(1550477,54,4,18,29,'Ze všech darů svých přinesete každou obět vzhůru pozdvižení Hospodinu, díl posvěcený všeho, což nejlepšího jest.'),
(1550478,54,4,18,30,'Díš jim také: Když obětovati budete z toho, což nejlepšího jest, počteno bude Levítům jako úrody z humna, a jako úrody od presu.'),
(1550479,54,4,18,31,'Jísti pak budete ty desátky na všelikém místě vy i čeled vaše; nebo mzda vaše jest za službu vaši při stánku úmluvy.'),
(1550480,54,4,18,32,'A neponesete pro to hříchu, když obětovati budete to, což nejlepšího jest; a tak nepoškvrníte věcí posvěcených od synů Izraelských, a nezemřete.'),
(1550481,54,4,19,1,'I mluvil Hospodin k Mojžíšovi a k Aronovi, řka:'),
(1550482,54,4,19,2,'Toto jest ustanovení zákona, kteréž přikázal Hospodin, řka: Mluv k synům Izraelským, ať vezmouce, přivedou k tobě jalovici červenou bez vady, na níž by nebylo poškvrny, a na kterouž by ještě jho nebylo kladeno.'),
(1550483,54,4,19,3,'A dáte ji Eleazarovi knězi, kterýž vyvede ji ven z stanů, a rozkáže ji zabiti před sebou.'),
(1550484,54,4,19,4,'A vezma Eleazar kněz krve její na prst svůj, kropiti bude jí naproti stánku úmluvy sedmkrát.'),
(1550485,54,4,19,5,'Potom káže tu jalovici spáliti před očima svýma; kůži její, i maso její, i krev její s lejny jejími dá spáliti.'),
(1550486,54,4,19,6,'A vezma kněz dřeva cedrového, yzopu a červce dvakrát barveného, uvrže to vše do ohně, v kterémž ta jalovice hoří.'),
(1550487,54,4,19,7,'I zpéře kněz roucha svá, a tělo své umyje vodou; potom vejde do stanů, a bude nečistý až do večera.'),
(1550488,54,4,19,8,'Takž také i ten, kterýž ji pálil, zpéře roucha svá u vodě, a tělo své obmyje vodou, a nečistý bude až do večera.'),
(1550489,54,4,19,9,'Popel pak té jalovice spálené smete muž čistý, a vysype jej vně za stany na místě čistém, aby byl všechněm synům Izraelským chován k vodě očištění, kteráž bude k očištění za hřích.'),
(1550490,54,4,19,10,'A ten, kdož by smetl popel té jalovice, zpéře roucha svá a nečistý bude až do večera. A budou to míti synové Izraelští i příchozí, kterýž jest pohostinu u prostřed nich, za ustanovení věčné.'),
(1550491,54,4,19,11,'Kdo by se dotkl těla kteréhokoli mrtvého člověka, nečistý bude za sedm dní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550492,54,4,19,12,'Takový očišťovati se bude tou vodou dne třetího a dne sedmého, i bude čistý; neočistí-li se pak dne třetího a dne sedmého, nebudeť čistý.'),
(1550493,54,4,19,13,'Kdo by koli, dotkna se těla mrtvého člověka, kterýž umřel, neočistil se, příbytku Hospodinova poškvrnil. Protož vyhlazena bude duše ta z Izraele, nebo vodou očišťování není pokropen; nečistýť bude, a nečistota jeho zůstává na něm.'),
(1550494,54,4,19,14,'Tento jest také zákon, kdyby člověk umřel v stanu: Kdo by koli všel do toho stanu, a kdo by koli byl v stanu, nečistý bude za sedm dní.'),
(1550495,54,4,19,15,'Tolikéž všeliká nádoba odkrytá, kteráž by neměla svrchu přikryvadla na sobě, nečistá bude.'),
(1550496,54,4,19,16,'Tak kdož by se koli dotkl na poli buď mečem zabitého, aneb mrtvého, buďto kosti člověka, aneb hrobu, nečistý bude za sedm dní.'),
(1550497,54,4,19,17,'A vezmou pro nečistého popela z spálené za hřích, a nalejí na něj vody živé do nádoby.'),
(1550498,54,4,19,18,'Potom vezme člověk čistý yzopu, a omočí jej v té vodě, a pokropí stanu, i všeho nádobí i lidí, kteříž by tu byli, tolikéž toho, kterýž dotkl se kosti, aneb zabitého, aneb mrtvého, aneb hrobu.'),
(1550499,54,4,19,19,'Pokropí tedy čistý nečistého v den třetí a v den sedmý; a když jej očistí dne sedmého, zpéře šaty své, a umyje se vodou, a čistý bude u večer.'),
(1550500,54,4,19,20,'Jestliže by pak kdo nečistý jsa, neočistil se, vyhlazena bude duše ta z prostředku shromáždění; nebo svatyně Hospodinovy poškvrnil, vodou očišťování nejsa pokropen; nečistý jest.'),
(1550501,54,4,19,21,'I bude jim to za ustanovení věčné. Kdož by pak tou vodou očišťování kropil, zpéře roucha svá, a kdož by se dotkl vody očišťování, nečistý bude až do večera.'),
(1550502,54,4,19,22,'Čehokoli dotkl by se nečistý, nečisté bude; člověk také, kterýž by se dotkl toho, nečistý bude až do večera.'),
(1550503,54,4,20,1,'I přitáhlo všecko množství synů Izraelských na poušť Tsin, měsíce prvního; i pozůstal lid v Kádes, kdež umřela Maria, a tu jest pochována.'),
(1550504,54,4,20,2,'A když množství to nemělo vody, sešli se proti Mojžíšovi, a proti Aronovi.'),
(1550505,54,4,20,3,'I domlouval se lid na Mojžíše, a mluvili, řkouce: Ó kdybychom i my byli zemřeli, když zemřeli bratří naši před Hospodinem!'),
(1550506,54,4,20,4,'Proč jste jen uvedli shromáždění Hospodinovo na poušť tuto, abychom zde pomřeli i my i dobytek náš?'),
(1550507,54,4,20,5,'A proč jste nás vyvedli z Egypta, abyste uvedli nás na toto zlé místo, na němž se nerodí ani obilí, ani fíků, ani hroznů, ani jablek zrnatých, na kterémž ani vody ku pití není?'),
(1550508,54,4,20,6,'Tedy odšel Mojžíš s Aronem od tváři shromáždění ke dveřím stánku úmluvy, a padli na tváři své; i ukázala se sláva Hospodinova nad nimi.'),
(1550509,54,4,20,7,'A mluvil Hospodin k Mojžíšovi, řka:'),
(1550510,54,4,20,8,'Vezmi hůl, a shromáždíce všecko množství, ty i Aron bratr tvůj, mluvte k skále této před očima jejich, a vydá vodu svou. I vyvedeš jim vodu z skály, a dáš nápoj všemu množství i dobytku jejich.'),
(1550511,54,4,20,9,'Tedy vzal Mojžíš hůl před tváří Hospodinovou, jakž rozkázal jemu.'),
(1550512,54,4,20,10,'I svolali Mojžíš s Aronem všecko množství před skálu, a řekl jim: Slyštež nyní, ó reptáci: Zdali z skály této vyvedeme vám vodu?'),
(1550513,54,4,20,11,'I pozdvihl Mojžíš ruky své, a udeřil v skálu holí svou po dvakrát; i vyšly vody hojné, a pilo všecko množství i dobytek jejich.'),
(1550514,54,4,20,12,'Potom řekl Hospodin Mojžíšovi a Aronovi: Že jste mi nevěřili, abyste posvětili mne před očima synů Izraelských, proto neuvedete shromáždění tohoto do země, kterouž jsem jim dal.'),
(1550515,54,4,20,13,'Toť jsou ty vody sváru, o kteréž svařili se synové Izraelští s Hospodinem, a posvěcen jest v nich.'),
(1550516,54,4,20,14,'I poslal Mojžíš posly z Kádes k králi Edom, aby řekli: Totoť vzkazuje bratr tvůj Izrael: Ty víš o všech těžkostech, kteréž přišly na nás,'),
(1550517,54,4,20,15,'Že sstoupili otcové naši do Egypta, a bydlili jsme tam za mnoho let. Egyptští pak ssužovali nás i otce naše.'),
(1550518,54,4,20,16,'A volali jsme k Hospodinu, kterýž uslyšel hlas náš, a poslav anděla, vyvedl nás z Egypta, a aj, již jsme v Kádes městě, při pomezí tvém.'),
(1550519,54,4,20,17,'Nechť, prosím, projdeme skrze zemi tvou. Nepůjdeme přes rolí, ani přes vinice, aniž píti budeme vody z čí studnice; cestou královskou půjdeme a neuchýlíme se na pravo ani na levo, dokavadž nepřejdeme mezí tvých.'),
(1550520,54,4,20,18,'Jemužto odpověděl Edom: Nechoď skrze mou zemi, abych s mečem nevyšel v cestu tobě.'),
(1550521,54,4,20,19,'I řekli mu synové Izraelští: Obecnou silnicí půjdeme, a jestliže vody tvé napili bychom se, buď my neb dobytek náš, zaplatíme ji; nic jiného nežádáme, toliko pěší abychom prošli.'),
(1550522,54,4,20,20,'Odpověděl: Neprojdeš. A vytáhl proti nim Edom s množstvím lidu a s silou velikou.'),
(1550523,54,4,20,21,'Když tedy nedopustil Edom Izraelovi, aby přešel meze jeho, uchýlil se Izrael od něho.'),
(1550524,54,4,20,22,'A hnuvše se synové Izraelští i všecko množství jejich z Kádes, přišli na horu řečenou Hor.'),
(1550525,54,4,20,23,'I mluvil Hospodin k Mojžíšovi a Aronovi na hoře Hor, při pomezí země Edom, řka:'),
(1550526,54,4,20,24,'Připojen bude Aron k lidu svému; nebo nevejde do země, kterouž jsem dal synům Izraelským, proto že jste odporni byli řeči mé při vodách sváru.'),
(1550527,54,4,20,25,'Pojmi Arona a Eleazara syna jeho, a uvedeš je na horu Hor.'),
(1550528,54,4,20,26,'A svlečeš Arona z roucha jeho, a oblečeš v ně Eleazara syna jeho; nebo Aron připojen bude k lidu svému, a tam umře.'),
(1550529,54,4,20,27,'I učinil Mojžíš, jakž rozkázal Hospodin, a vstoupili na horu Hor před očima všeho množství.'),
(1550530,54,4,20,28,'A svlékl Mojžíš Arona z roucha jeho, a oblékl v ně Eleazara syna jeho. I umřel tam Aron na pahrbku hory, Mojžíš pak a Eleazar sstoupili s hory.'),
(1550531,54,4,20,29,'Vidouce pak všecko množství, že umřel Aron, plakali ho za třidceti dní všecken dům Izraelský.'),
(1550532,54,4,21,1,'To když uslyšel Kananejský král v Arad, kterýž bydlil na poledne, že by táhl Izrael tou cestou, kterouž byli špehéři šli, bojoval s ním, a zajal jich množství.'),
(1550533,54,4,21,2,'Tedy Izrael učinil slib Hospodinu, řka: Jestliže dáš lid tento v ruce mé, do gruntu zkazím města jejich.'),
(1550534,54,4,21,3,'I uslyšel Hospodin hlas Izraele a dal mu Kananejské, kterýžto do gruntu zkazil je i města jejich, a nazval jméno toho místa Horma.'),
(1550535,54,4,21,4,'Potom hnuli se s hory Hor cestou k moři Rudému, aby obešli zemi Idumejskou; i ustával lid velice na cestě.'),
(1550536,54,4,21,5,'A mluvil lid proti Bohu a proti Mojžíšovi: Proč jste vyvedli nás z Egypta, abychom zemřeli na poušti? Nebo ani chleba ani vody není, a duše naše chléb tento ničemný sobě již zošklivila.'),
(1550537,54,4,21,6,'Protož dopustil Hospodin na lid hady ohnivé, kteříž jej štípali, tak že množství lidu zemřelo z Izraele.'),
(1550538,54,4,21,7,'Tedy přišel lid k Mojžíšovi a řekli: Zhřešili jsme nebo jsme mluvili proti Hospodinu a proti tobě; modl se Hospodinu, ať odejme od nás ty hady. I modlil se Mojžíš za lid.'),
(1550539,54,4,21,8,'I řekl Hospodin Mojžíšovi: Udělej sobě hada podobného těm ohnivým, a vyzdvihni jej na sochu; a každý ušťknutý, když pohledí na něj, živ bude.'),
(1550540,54,4,21,9,'I udělal Mojžíš hada měděného, a vyzdvihl jej na sochu; a stalo se, když ušťkl had někoho, a on vzhlédl na hada měděného, že zůstal živ.'),
(1550541,54,4,21,10,'Tedy hnuli se odtud synové Izraelští, a položili se v Obot.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550542,54,4,21,11,'Potom pak hnuvše se z Obot, položili se při pahrbcích hor Abarim na poušti, kteráž jest naproti zemi Moábské k východu slunce.'),
(1550543,54,4,21,12,'Odtud brali se, a položili se v údolí Záred.'),
(1550544,54,4,21,13,'Opět hnuvše se odtud, položili se u brodu potoka Arnon, kterýž jest na poušti, a vychází z končin Amorejských. Nebo Arnon jest pomezí Moábské mezi Moábskými a Amorejskými.'),
(1550545,54,4,21,14,'Protož praví se v knize bojů Hospodinových, že proti Vahebovi u vichřici bojoval, a proti potokům Arnon.'),
(1550546,54,4,21,15,'Nebo tok těch potoků, kterýž se nachyluje ku položení Ar, ten jde vedlé pomezí Moábského.'),
(1550547,54,4,21,16,'A odtud táhli do Beer; a to jest to Beer, o němž byl řekl Hospodin k Mojžíšovi: Shromažď lid, a dám jim vodu.'),
(1550548,54,4,21,17,'Tedy zpíval lid Izraelský písničku tuto: Vystupiž studnice, prozpěvujte o ní;'),
(1550549,54,4,21,18,'Studnice, kterouž kopala knížata, kterouž vykopali přední z lidu s vydavatelem zákona holemi svými. Z pouště pak brali se do Matana,'),
(1550550,54,4,21,19,'A z Matana do Nahaliel, z Nahaliel do Bamot,'),
(1550551,54,4,21,20,'A z Bamot do údolí, kteréž jest na poli Moábském, až k vrchu hory, kteráž leží na proti poušti.'),
(1550552,54,4,21,21,'Tedy poslal lid Izraelský posly k Seonovi králi Amorejskému, řka:'),
(1550553,54,4,21,22,'Nechť jdeme skrze zemi tvou. Neuchýlíme se ani do pole, ani do vinic, ani z studnic vody píti nebudeme, ale cestou královskou půjdeme, dokavadž nepřejdeme pomezí tvého.'),
(1550554,54,4,21,23,'I nedopustil Seon jíti lidu Izraelskému skrze krajinu svou, nýbrž sebrav Seon všecken lid svůj, vytáhl proti lidu Izraelskému na poušť, a přitáh do Jasa, bojoval proti Izraelovi.'),
(1550555,54,4,21,24,'I porazil jej lid Izraelský mečem, a vzal v dědictví zemi jeho, od Arnon až do Jabok, a až do země synů Ammon; nebo pevné bylo pomezí Ammonitských.'),
(1550556,54,4,21,25,'Tedy vzal Izrael všecka ta města, a přebýval ve všech městech Amorejských, v Ezebon a ve všech městečkách jeho.'),
(1550557,54,4,21,26,'Nebo Ezebon bylo město Seona krále Amorejského, kterýž když bojoval proti králi Moábskému prvnímu, vzal mu všecku zemi jeho z rukou jeho až do Arnon.'),
(1550558,54,4,21,27,'Protož říkávali v přísloví: Poďte do Ezebon, aby vystaveno bylo a vzděláno město Seonovo.'),
(1550559,54,4,21,28,'Nebo oheň vyšel z Ezebon, a plamen z města Seon, i spálil Ar Moábských a obyvatele výsosti Arnon.'),
(1550560,54,4,21,29,'Běda tobě Moáb, zahynuls lide Chámos; dal syny své v utíkání, a dcery své v zajetí králi Amorejskému Seonovi.'),
(1550561,54,4,21,30,'A království jejich zahynulo od Ezebon až do Dibon, a vyhladili jsme je až do Nofe, kteréž jest až k Medaba.'),
(1550562,54,4,21,31,'A tak bydlil Izrael v zemi Amorejské.'),
(1550563,54,4,21,32,'Potom poslal Mojžíš, aby shlédli Jazer, kteréž vzali i s městečky jeho; a tak vyhnal Amorejské, kteříž tam bydlili.'),
(1550564,54,4,21,33,'Obrátivše se pak, táhli cestou k Bázan. I vytáhl Og, král Bázan, proti nim, on i všecken lid jeho, aby bojoval v Edrei.'),
(1550565,54,4,21,34,'Tedy řekl Hospodin Mojžíšovi: Neboj se ho; nebo v ruce tvé dal jsem jej, i všecken lid jeho, i zemi jeho, a učiníš jemu tak, jakož jsi učinil Seonovi, králi Amorejskému, kterýž bydlil v Ezebon.'),
(1550566,54,4,21,35,'I porazili jej i syny jeho, i všecken lid jeho, tak že žádný živý po něm nezůstal, a uvázali se dědičně v zemi jeho.'),
(1550567,54,4,22,1,'I táhli synové Izraelští a položili se na polích Moábských, nedocházeje k Jordánu, naproti Jerichu.'),
(1550568,54,4,22,2,'A viděl Balák, syn Seforův, všecko, co učinil Izrael Amorejskému.'),
(1550569,54,4,22,3,'I bál se Moáb toho lidu velmi, proto že ho bylo mnoho, a svíral se pro přítomnost synů Izraelských.'),
(1550570,54,4,22,4,'Protož řekl Moáb k starším Madianským: Tudíž toto množství požere všecko, což jest vůkol nás, jako sžírá vůl trávu polní. Byl pak Balák, syn Seforův, toho času králem Moábským.'),
(1550571,54,4,22,5,'I poslal posly k Balámovi, synu Beorovu, do města Petor, kteréž jest při řece v zemi vlasti jeho, aby povolal ho, řka: Aj, lid vyšel z Egypta, aj, přikryl svrchek země, a usazuje se proti mně.'),
(1550572,54,4,22,6,'Protož nyní poď medle, zlořeč mně k vůli lidu tomuto,nebo silnější mne jest; snad svítězím nad ním, a porazím jej, aneb vyženu z země této. Vím zajisté, že komuž ty žehnáš, požehnaný bude, a komuž ty zlořečíš, bude zlořečený.'),
(1550573,54,4,22,7,'Tedy šli starší Moábští a starší Madianští, nesouce v rukou svých peníze za zlořečení; i přišli k Balámovi, a vypravovali mu slova Balákova.'),
(1550574,54,4,22,8,'On pak řekl jim: Pobuďte zde přes tuto noc, a dám vám odpověd, jakž mi mluviti bude Hospodin. I zůstala knížata Moábská s Balámem.'),
(1550575,54,4,22,9,'Přišel pak Bůh k Balámovi a řekl: Kdo jsou ti muži u tebe?'),
(1550576,54,4,22,10,'Odpověděl Balám Bohu: Balák, syn Seforův, král Moábský, poslal ke mně, řka:'),
(1550577,54,4,22,11,'Aj, lid ten, kterýž vyšel z Egypta, přikryl svrchek země; protož nyní poď, proklň mi jej, snad svítězím, bojuje s ním, a vyženu jej.'),
(1550578,54,4,22,12,'I řekl Bůh k Balámovi: Nechoď s nimi, aniž zlořeč lidu tomu, nebo požehnaný jest.'),
(1550579,54,4,22,13,'Tedy Balám vstav ráno, řekl knížatům Balákovým: Navraťte se do země své, nebo nechce mi dopustiti Hospodin, abych šel s vámi.'),
(1550580,54,4,22,14,'A vstavše knížata Moábská, přišli k Balákovi a řekli: Nechtěl Balám jíti s námi.'),
(1550581,54,4,22,15,'Tedy opět poslal Balák více knížat a znamenitějších, nežli první.'),
(1550582,54,4,22,16,'Kteříž přišedše k Balámovi, řekli jemu: Toto praví Balák, syn Seforův: Nezpěčuj se, prosím, přijíti ke mně.'),
(1550583,54,4,22,17,'Nebo velikou ctí tě ctíti chci, a což mi koli rozkážeš, učiním; protož přiď, prosím, proklň mi lid tento.'),
(1550584,54,4,22,18,'Odpovídaje pak Balám, řekl služebníkům Balákovým: Byť mi pak dal Balák plný dům svůj stříbra a zlata, nemohl bych přestoupiti slova Hospodina Boha svého, a učiniti proti němu malé neb veliké věci.'),
(1550585,54,4,22,19,'Nyní však zůstaňte, prosím, zde i vy také této noci, abych zvěděl, co dále mluviti bude Hospodin se mnou.'),
(1550586,54,4,22,20,'Přišed pak Bůh k Balámovi v noci, řekl jemu: Poněvadž proto, aby povolali tě, přišli muži tito, vstana, jdi s nimi, a však což přikáži tobě, to čiň.'),
(1550587,54,4,22,21,'Tedy Balám vstav ráno, osedlal oslici svou, a bral se s knížaty Moábskými.'),
(1550588,54,4,22,22,'Ale rozpálil se hněv Boží, proto že jel s nimi, a postavil se anděl Hospodinův na cestě, aby mu překazil; on pak seděl na oslici své, maje s sebou dva služebníky své.'),
(1550589,54,4,22,23,'A když uzřela oslice anděla Hospodinova, an stojí na cestě, a meč jeho vytržený v ruce jeho, uhnula se s cesty, a šla polem. I bil ji Balám, aby ji navedl zase na cestu.'),
(1550590,54,4,22,24,'A anděl Hospodinův stál na stezce u vinice mezi dvěma zídkami.'),
(1550591,54,4,22,25,'Viduci pak oslice anděla Hospodinova, přitiskla se ke zdi, přitřela také nohu Balámovi ke zdi; pročež opět bil ji.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550592,54,4,22,26,'Potom anděl Hospodinův šel dále, a stál v úzkém místě, kdež nebylo žádné cesty k uchýlení se na pravo neb na levo.'),
(1550593,54,4,22,27,'A viduci oslice anděla Hospodinova, padla pod Balámem; pročež rozhněval se velmi Balám, a bil oslici kyjem.'),
(1550594,54,4,22,28,'I otevřel Hospodin ústa oslice, a řekla Balámovi: Cožť jsem učinila, že již po třetí mne biješ?'),
(1550595,54,4,22,29,'Řekl Balám k oslici: To, že jsi mne v posměch uvedla. Ó bych měl meč v rukou, jistě bych tě již zabil.'),
(1550596,54,4,22,30,'Odpověděla oslice Balámovi: Zdaliž nejsem oslice tvá? Jezdíval jsi na mně, jak jsi mne dostal, až do dnes; zdaliž jsem kdy obyčej měla tak činiti tobě? Kterýž odpověděl: Nikdy.'),
(1550597,54,4,22,31,'V tom otevřel Hospodin oči Balámovy, i uzřel anděla Hospodinova, an stojí na cestě, maje meč dobytý v ruce své; a nakloniv hlavy, poklonu učinil na tvář svou.'),
(1550598,54,4,22,32,'I mluvil k němu anděl Hospodinův: Proč jsi bil oslici svou po třikrát? Aj, já vyšel jsem, abych se protivil tobě; nebo uchýlil jsi se s cesty přede mnou.'),
(1550599,54,4,22,33,'Když viděla mne oslice, vyhnula mi již po třikrát; a byť mi se byla nevyhnula, již bych byl také tebe zabil, a jí živé nechal.'),
(1550600,54,4,22,34,'Odpověděl Balám andělu Hospodinovu: Zhřešilť jsem, nebo jsem nevěděl, že ty stojíš proti mně na cestě; protož nyní, jestliže se nelíbí tobě, raději navrátím se domů.'),
(1550601,54,4,22,35,'Řekl anděl Hospodinův k Balámovi: Jdi s muži těmi, avšak slovo, kteréž mluviti budu tobě, to mluviti budeš. Tedy šel Balám s knížaty Balákovými.'),
(1550602,54,4,22,36,'Uslyšev pak Balák o příchodu Balámovu, vyšel proti němu do města Moábského, kteréž bylo při řece Arnon, jenž jest při konci pomezí.'),
(1550603,54,4,22,37,'I řekl Balák Balámovi: Zdaliž jsem víc než jednou neposílal pro tě? Pročež jsi tedy nepřišel ke mně? Proto-li, že bych tě náležitě uctiti nemohl?'),
(1550604,54,4,22,38,'Odpověděl Balám Balákovi: Aj, již jsem přišel k tobě; nyní pak zdaliž všelijak budu co moci mluviti? Slovo, kteréž vložil Bůh v ústa má, to mluviti budu.'),
(1550605,54,4,22,39,'I bral se Balám s Balákem, a přijeli do města Husot.'),
(1550606,54,4,22,40,'Kdežto nabiv Balák volů a ovec, poslal k Balámovi a k knížatům, kteříž s ním byli.'),
(1550607,54,4,22,41,'Nazejtří pak ráno, pojav Balák Baláma, uvedl ho na výsosti modly Bál, odkudž shlédl i nejdalší díl lidu Izraelského.'),
(1550608,54,4,23,1,'A řekl Balám Balákovi: Udělej mi tuto sedm oltářů, a připrav mi také sedm volků a sedm skopců.'),
(1550609,54,4,23,2,'I udělal Balák, jakž mluvil Balám. Tedy obětoval Balák a Balám volka a na každém oltáři.'),
(1550610,54,4,23,3,'Řekl pak Balám Balákovi: Postůj při oběti své zápalné, a půjdu, zdali by se potkal se mnou Hospodin, a což by koli mně ukázal, povím tobě. I odšel sám.'),
(1550611,54,4,23,4,'I potkal se Bůh s Balámem, a řekl jemu Balám: Sedm oltářů zpořádal jsem, a obětoval jsem volka a skopce na každém oltáři.'),
(1550612,54,4,23,5,'Vložil pak Hospodin slovo v ústa Balámova a řekl: Navrať se k Balákovi a tak mluv.'),
(1550613,54,4,23,6,'I navrátil se k němu, a nalezl jej, an stojí při oběti své zápalné, i všecka knížata Moábská.'),
(1550614,54,4,23,7,'Tedy vzav před sebe přísloví své, řekl: Z Aram přivedl mne Balák král Moábský, z hor východních, řka: Poď, zlořeč mi k vůli Jákoba, a poď, vydej klatbu na Izraele.'),
(1550615,54,4,23,8,'Proč bych zlořečil, komuž Bůh silný nezlořečí? A proč bych klel, kohož Hospodin neproklíná?'),
(1550616,54,4,23,9,'Když s vrchu skal hledím na něj, a s pahrbků spatřuji jej, aj, lid ten sám bydlí, a k jiným národům se nepřiměšuje.'),
(1550617,54,4,23,10,'Kdo sečte prach Jákobův? a kdo počet? Kdo sečte čtvrtý díl Izraelského lidu? Ó bych já umřel smrtí spravedlivých, a dokonání mé ó by bylo jako i jeho!'),
(1550618,54,4,23,11,'I řekl Balák Balámovi: Což mi to děláš? Abys zlořečil nepřátelům mým, povolal jsem tě, a ty pak ustavičně dobrořečíš jim.'),
(1550619,54,4,23,12,'Kterýž odpovídaje, řekl: Zdali toho, což Hospodin vložil v ústa má, nemám šetřiti, abych tak mluvil?'),
(1550620,54,4,23,13,'I řekl jemu Balák: Poď, prosím, se mnou na jiné místo, odkudž bys viděl jej, (toliko zadní díl jeho viděti budeš, a všeho nebudeš viděti), a proklň mi jej odtud.'),
(1550621,54,4,23,14,'I pojav jej, vyvedl ho na rovinu Zofim, na vrch jednoho pahrbku, a udělav sedm oltářů, obětoval volka a skopce na každém oltáři.'),
(1550622,54,4,23,15,'Řekl pak Balákovi: Postůj tuto při zápalné oběti své, a já půjdu tamto vstříc Hospodinu.'),
(1550623,54,4,23,16,'I potkal se Hospodin s Balámem, a vloživ slovo v ústa jeho, řekl: Navrať se k Balákovi a mluv tak.'),
(1550624,54,4,23,17,'Přišel tedy k němu, a hle, on stál při zápalné oběti své, a knížata Moábská s ním. Jemužto řekl Balák: Co mluvil Hospodin?'),
(1550625,54,4,23,18,'A on vzav přísloví své, řekl: Povstaň Baláku a slyš, pozoruj mne, synu Seforův.'),
(1550626,54,4,23,19,'Bůh silný není jako člověk, aby klamal, a jako syn člověka, aby se měnil. Což by řekl, zdaliž neučiní? Což by promluvil, zdali neutvrdí toho?'),
(1550627,54,4,23,20,'Hle, abych dobrořečil, přijal jsem to na sebe; nebo dobrořečilť jest, a já toho neodvolám.'),
(1550628,54,4,23,21,'Nepatříť na nepravosti v Jákobovi, aniž hledí na přestoupení v Izraeli; Hospodin Bůh jeho jestiť s ním, a zvuk krále vítězícího v něm.'),
(1550629,54,4,23,22,'Bůh silný vyvedl je z Egypta, jako silou jednorožcovou byv jim.'),
(1550630,54,4,23,23,'Nebo není kouzlů proti Jákobovi, ani zaklínání proti Izraelovi; již od toho času vypravováno bude o Jákobovi a Izraelovi, co učinil s ním Bůh silný.'),
(1550631,54,4,23,24,'Aj, lid jakožto silný lev povstane, a jakožto lvíče vzchopí se; nepoloží se, dokudž by nejedl loupeže, a dokudž by nevypil krve zbitých.'),
(1550632,54,4,23,25,'I řekl Balák Balámovi: Aniž mu již zlořeč více, ani dobrořeč.'),
(1550633,54,4,23,26,'Jemuž odpověděl Balám, řka: Zdaližť jsem nepravil, že, což by mi koli mluvil Hospodin, to učiním?'),
(1550634,54,4,23,27,'I řekl Balák Balámovi: Poď, prosím, povedu tě na jiné místo, odkudž snad líbiti se bude Bohu, abys mi je proklel.'),
(1550635,54,4,23,28,'A pojav Balák Baláma, uvedl jej na vrch hory Fegor, kteráž leží naproti poušti.'),
(1550636,54,4,23,29,'Tedy řekl Balám Balákovi: Udělej mi tuto sedm oltářů, a připrav mi také sedm volků a sedm skopců.'),
(1550637,54,4,23,30,'I učinil Balák, jakž řekl Balám, a obětoval volka a skopce na každém oltáři.'),
(1550638,54,4,24,1,'Vida pak Balám, že by se líbilo Hospodinu, aby dobrořečil Izraelovi, již více nešel jako prvé, jednou i po druhé, k čárům svým, ale obrátil tvář svou proti poušti.'),
(1550639,54,4,24,2,'A pozdvih očí svých, viděl Izraele bydlícího v staních po svých pokoleních, a byl nad ním duch Boží.'),
(1550640,54,4,24,3,'I vzav podobenství své, dí: Řekl Balám, syn Beorův, řekl muž mající otevřené oči,'),
(1550641,54,4,24,4,'Řekl slyšící výmluvnosti Boha silného, kterýž vidění všemohoucího vidí, kterýž když padne, otevřené má oči:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550642,54,4,24,5,'Jak velmi krásní jsou stánkové tvoji, Jákobe, příbytkové tvoji, Izraeli!'),
(1550643,54,4,24,6,'Tak jako se potokové rozšiřují, jako zahrady vedlé řeky, jako stromoví aloes, kteréž štípil Hospodin, jako cedrové podlé vod.'),
(1550644,54,4,24,7,'Poteče voda z okovu jeho, a símě jeho u vodách mnohých. A král jeho vyvýšen bude více než Agag, a vyzdvihne se království jeho.'),
(1550645,54,4,24,8,'Bůh silný vyvedl jej z Egypta, jako udatnost jednorožcova jest jemu; sžereť národy protivné sobě, a kosti jich potře a střelami svými prostřílí.'),
(1550646,54,4,24,9,'Složil se a ležel jako lvíče, a jako lev zůřivý; kdo jej zbudí? Kdo by požehnání dával tobě, požehnaný bude, a kdožť by zlořečil, bude zlořečený.'),
(1550647,54,4,24,10,'Tedy zapáliv se hněvem Balák proti Balámovi, tleskl rukama svýma a řekl Balámovi: Abys zlořečil nepřátelům mým, povolal jsem tebe, a aj, ustavičně dobrořečil jsi jim již po třikrát.'),
(1550648,54,4,24,11,'Protož nyní navrať se raději k místu svému. Bylť jsem řekl: Velikou ctí tě ctíti chci, a hle, Hospodin zbavil tě cti.'),
(1550649,54,4,24,12,'Jemuž odpověděl Balám: Však hned poslům tvým, kteréž jsi poslal ke mně, mluvil jsem, řka:'),
(1550650,54,4,24,13,'Byť mi dal Balák plný dům svůj stříbra a zlata, nebudu moci přestoupiti řeči Hospodinovy, abych činil dobré neb zlé sám od sebe; což mi Hospodin oznámí, to mluviti budu,'),
(1550651,54,4,24,14,'(Ale však ještě já, již odcházeje k lidu svému, počkej, poradím tobě,) co učiní lid ten lidu tvému v posledních dnech.'),
(1550652,54,4,24,15,'Tedy vzav podobenství své, dí: Řekl Balám, syn Beorův, řekl muž mající oči otevřené,'),
(1550653,54,4,24,16,'Řekl slyšící výmluvnosti Boha silného, kterýž zná naučení nejvyššího, a vidění všemohoucího vidí, kterýž když padne, otevřené má oči:'),
(1550654,54,4,24,17,'Uzřímť jej, ale ne nyní, pohledím na něj, ale ne z blízka. Vyjdeť hvězda z Jákoba, a povstane berla z Izraele, kteráž poláme knížata Moábská, a zkazí všecky syny Set.'),
(1550655,54,4,24,18,'I bude Edom podmaněn, a Seir v vládařstí přijde nepřátelům svým; nebo Izrael zmužile sobě počínati bude.'),
(1550656,54,4,24,19,'Panovati bude pošlý z Jákoba, a zahladí ostatky z každého města.'),
(1550657,54,4,24,20,'A když uzřel Amalecha, vzav podobenství své, řekl: Jakož počátek národů Amalech, tak konec jeho do gruntu zahyne.'),
(1550658,54,4,24,21,'Uzřev pak Cinea, vzav podobenství své, řekl: Pevný jest příbytek tvůj, a na skále založils hnízdo své;'),
(1550659,54,4,24,22,'Ale však vyhnán bude Cineus, Assur zajatého jej povede.'),
(1550660,54,4,24,23,'Opět vzav podobenství své, řekl: Ach, kdo bude živ, když toto učiní Bůh silný?'),
(1550661,54,4,24,24,'A bárky z země Citim připlynou a ssouží Assyrské, ssouží také Židy, ale i ten lid do konce zahyne.'),
(1550662,54,4,24,25,'Potom vstav Balám, odšel a navrátil se na místo své; Balák také odšel cestou svou.'),
(1550663,54,4,25,1,'V tom, když pobyl Izrael v Setim, počal lid smilniti s dcerami Moábskými.'),
(1550664,54,4,25,2,'Kteréž pozvaly lidu k obětem bohů svých; i jedl lid, a klaněli se bohům jejich.'),
(1550665,54,4,25,3,'I připojil se lid Izraelský k modle Belfegor, a popudila se prchlivost Hospodinova proti Izraelovi.'),
(1550666,54,4,25,4,'I řekl Hospodin Mojžíšovi: Vezmi všecka knížata lidu, a zvěšej ty nešlechetníky Hospodinu před sluncem, aby se odvrátila prchlivost Hospodinova od Izraele.'),
(1550667,54,4,25,5,'I řekl Mojžíš soudcům Izraelským: Zabí jeden každý z svých všelikého, kterýž se připojil k modle Belfegor.'),
(1550668,54,4,25,6,'A aj, jeden z synů Izraelských přišel, a přivedl k bratřím svým ženu Madianku, na odivu Mojžíšovi i všemu množství synů Izraelských; oni pak plakali u dveří stánku úmluvy.'),
(1550669,54,4,25,7,'To když uzřel Fínes, syn Eleazara, syna Aronova, kněze, vyvstal z prostředku množství toho, a vzal kopí do ruky své.'),
(1550670,54,4,25,8,'A všed za mužem Izraelským do stanu, probodl je oba dva, muže Izraelského, i ženu tu skrze břicho její; i odvrácena jest rána od synů Izraelských.'),
(1550671,54,4,25,9,'Zhynulo jich pak od té rány dvadceti čtyři tisíce.'),
(1550672,54,4,25,10,'Tedy mluvil Hospodin k Mojžíšovi, řka:'),
(1550673,54,4,25,11,'Fínes, syn Eleazara kněze, syna Aronova, odvrátil prchlivost mou od synů Izraelských, kdyžto horlil horlivostí mou u prostřed nich, tak abych neshladil synů Izraelských v horlivosti své.'),
(1550674,54,4,25,12,'Protož díš: Aj, já dám jemu smlouvu svou pokoje.'),
(1550675,54,4,25,13,'I bude míti on i símě jeho po něm smlouvu kněžství věčného, proto že horlil pro Boha svého, a očistil syny Izraelské.'),
(1550676,54,4,25,14,'A bylo jméno muže Izraelského zabitého, kterýž byl zabit s Madiankou, Zamri, syn Sálův, kníže domu otce svého z pokolení Simeonova.'),
(1550677,54,4,25,15,'Jméno pak ženy Madianky zabité, Kozbi, dcera Sur, kterýž byl přední v národu svém, v domě otce svého mezi Madianskými.'),
(1550678,54,4,25,16,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1550679,54,4,25,17,'Nepřátelsky zacházejte s těmi Madianskými, a zbíte je.'),
(1550680,54,4,25,18,'Nebo i oni nepřátelsky a lstivě chovali se k vám, a oklamali vás skrze modlu Fegor, a skrze Kozbu, dceru knížete Madianského, sestru svou, kteráž zabita jest v den pomsty přišlé z příčiny Fegor.'),
(1550681,54,4,26,1,'I stalo se po té ráně, že mluvil Hospodin k Mojžíšovi a Eleazarovi, synu Arona kněze, řka:'),
(1550682,54,4,26,2,'Sečtěte všecko množství synů Izraelských, od dvadcítiletých a výše po domích otců jejich, všecky, kteříž by mohli jíti k boji v Izraeli.'),
(1550683,54,4,26,3,'Tedy mluvil Mojžíš a Eleazar kněz k nim na polích Moábských, při Jordánu proti Jerichu, řka:'),
(1550684,54,4,26,4,'Sečtěte lid od dvadceti let majících a výše, jakž rozkázal Hospodin Mojžíšovi a synům Izraelským, kteříž byli vyšli z země Egyptské.'),
(1550685,54,4,26,5,'Ruben prvorozený byl Izraelův. Synové Rubenovi: Enoch, z něhož pošla čeled Enochitská; Fallu, z něhož čeled Fallutská;'),
(1550686,54,4,26,6,'Ezron, z něhož čeled Ezronitská; Charmi, z něhož čeled Charmitská.'),
(1550687,54,4,26,7,'Ty jsou čeledi Rubenovy. A bylo jich sečtených čtyřidceti tři tisíce, sedm set a třidceti.'),
(1550688,54,4,26,8,'A syn Fallův Eliab.'),
(1550689,54,4,26,9,'Synové pak Eliabovi: Nemuel, a Dátan, a Abiron. To jsou ti, Dátan a Abiron, přední z shromáždění, kteříž se vadili s Mojžíšem a s Aronem v spiknutí Chóre, když odporni byli Hospodinu.'),
(1550690,54,4,26,10,'Pročež otevřela země ústa svá, a požřela je i Chóre, tehdáž když zemřela ta rota, a oheň spálil těch dvě stě a padesáte mužů, kteříž byli za příklad jiným.'),
(1550691,54,4,26,11,'Synové pak Chóre nezemřeli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550692,54,4,26,12,'Synové Simeonovi po čeledech svých: Namuel, z něhož čeled Namuelitská; Jamin, z něhož čeled Jaminská; Jachin, z něhož čeled Jachinská;'),
(1550693,54,4,26,13,'Sohar, z něhož čeled Soharská; Saul, z něhož čeled Saulitská.'),
(1550694,54,4,26,14,'Ty jsou čeledi Simeonovy, jichž bylo dvamecítma tisíců a dvě stě.'),
(1550695,54,4,26,15,'Synové Gád po čeledech svých: Sefon, z něhož čeled Sefonitská; Aggi, z něhož čeled Aggitská; Suni, z něhož čeled Sunitská;'),
(1550696,54,4,26,16,'Ozni, z něhož čeled Oznitská; Heri, z něhož čeled Heritská;'),
(1550697,54,4,26,17,'Arodi, z něhož čeled Aroditská; Areli, z něhož čeled Arelitská.'),
(1550698,54,4,26,18,'Ty jsou čeledi synů Gád, podlé toho, jakž sečteni jsou, čtyřidceti tisíců a pět set.'),
(1550699,54,4,26,19,'Synové Judovi: Her a Onan; ale zemřeli Her i Onan v zemi Kanánské.'),
(1550700,54,4,26,20,'Byli pak synové Judovi po čeledech svých: Séla, z něhož čeled Sélanitská; Fáres, z něhož čeled Fáresská; Zára, z něhož čeled Záretská.'),
(1550701,54,4,26,21,'Byli pak synové Fáresovi: Ezron, z něhož čeled Ezronitská; Hamul, z něhož čeled Hamulská.'),
(1550702,54,4,26,22,'Ty jsou čeledi Judovy, podlé toho, jakž sečteni jsou, sedmdesáte šest tisíců a pět set.'),
(1550703,54,4,26,23,'Synové Izacharovi po čeledech svých: Tola, z něhož čeled Tolatská; Fua, z něhož čeled Fuatská;'),
(1550704,54,4,26,24,'Jasub, z něhož čeled Jasubská; Simron, z něhož čeled Simronská.'),
(1550705,54,4,26,25,'Ty jsou čeledi Izacharovy, podlé toho, jakž sečteni jsou, šedesáte čtyři tisíce a tři sta.'),
(1550706,54,4,26,26,'Synové Zabulonovi po čeledech svých: Sared, z něhož čeled Saredská; Elon, z něhož čeled Elonská; Jahelel, z něhož čeled Jahelelská.'),
(1550707,54,4,26,27,'Ty jsou čeledi Zabulonovy, podlé toho jakž sečteni jsou, šedesáte tisíc a pět set.'),
(1550708,54,4,26,28,'Synové Jozefovi po čeledech svých: Manasses a Efraim.'),
(1550709,54,4,26,29,'Synové Manassesovi: Machir, z něhož čeled Machirská. A Machir zplodil Galáda, z něhož čeled Galádská.'),
(1550710,54,4,26,30,'Ti jsou synové Galád: Jezer, z něhož čeled Jezerská; Helek, z něhož čeled Helekitská;'),
(1550711,54,4,26,31,'Asriel, z něhož čeled Asrielská; Sechem, z něhož čeled Sechemská;'),
(1550712,54,4,26,32,'Semida, z něhož čeled Semidatská; Hefer, z něhož čeled Heferská.'),
(1550713,54,4,26,33,'A Salfad, syn Heferův, neměl synů, než toliko dcery, jichž jsou tato jména: Mahla, Noa, Hegla, Melcha a Tersa.'),
(1550714,54,4,26,34,'Ty jsou čeledi Manassesovy, a načteno jich padesáte dva tisíce a sedm set.'),
(1550715,54,4,26,35,'Ale synové Efraimovi po čeledech svých: Sutala, z něhož čeled Sutalitská; Becher, z něhož čeled Becherská; Tehen, z něhož čeled Tehenská.'),
(1550716,54,4,26,36,'A ti jsou synové Sutalovi: Heran, z něhož čeled Heranská.'),
(1550717,54,4,26,37,'Ty jsou čeledi synů Efraimových, podlé toho, jakž sečteni jsou, třidceti dva tisíce a pět set. Ti jsou synové Jozefovi po čeledech svých.'),
(1550718,54,4,26,38,'Synové pak Beniaminovi po čeledech svých: Béla, z něhož čeled Bélitská; Asbel, z něhož čeled Asbelská; Ahiram, z něhož čeled Ahiramská;'),
(1550719,54,4,26,39,'Sufam, z něhož čeled Sufamská; Hufam, z něhož čeled Hufamská.'),
(1550720,54,4,26,40,'Byli pak synové Béla: Ared a Náman; z Ared čeled Aredská, z Náman čeled Námanská.'),
(1550721,54,4,26,41,'Ti jsou synové Beniaminovi po čeledech svých, podlé toho, jakž sečteni jsou, čtyřidceti pět tisíců a šest set.'),
(1550722,54,4,26,42,'Tito pak synové Danovi po čeledech svých: Suham, z něhož čeled Suhamská. Ta jest rodina Danova po čeledech svých.'),
(1550723,54,4,26,43,'Všech čeledí Suhamských, jakž sečteni jsou, šedesáte čtyři tisíce a čtyři sta.'),
(1550724,54,4,26,44,'Synové Asser po čeledech svých: Jemna, z něhož čeled Jemnitská; Jesui, z něhož čeled Jesuitská;'),
(1550725,54,4,26,45,'Beria, z něhož čeled Berietská. Synové Beriovi: Heber, z něhož čeled Heberská; Melchiel, z něhož čeled Melchielská.'),
(1550726,54,4,26,46,'Jméno pak dcery Asser bylo Serach.'),
(1550727,54,4,26,47,'Ty jsou čeledi synů Asser, tak jakž sečteni jsou, padesáte tři tisíce a čtyři sta.'),
(1550728,54,4,26,48,'Synové Neftalímovi po čeledech svých: Jasiel, z něhož čeled Jasielská; Guni, z něhož čeled Gunitská;'),
(1550729,54,4,26,49,'Jezer, z něhož čeled Jezerská; Sallem, z něhož čeled Sallemská.'),
(1550730,54,4,26,50,'Ta jest rodina Neftalímova po čeledech svých, tak jakž sečteni jsou, čtyřidceti pět tisíců a čtyři sta.'),
(1550731,54,4,26,51,'Ten jest počet synů Izraelských, šestkrát sto tisíců a jeden tisíc, sedm set a třidceti.'),
(1550732,54,4,26,52,'Mluvil pak Hospodin k Mojžíšovi, řka:'),
(1550733,54,4,26,53,'Těmto rozdělena bude země k dědictví podlé počtu jmen.'),
(1550734,54,4,26,54,'Většímu počtu větší dědictví dáš, a menšímu menší; jednomu každému vedlé počtu sečtených jeho dáno bude dědictví jeho.'),
(1550735,54,4,26,55,'A však losem ať jest rozdělena země; vedlé jmen pokolení otců svých dědictví vezmou.'),
(1550736,54,4,26,56,'Losem děleno bude dědictví její, buď jich mnoho neb málo.'),
(1550737,54,4,26,57,'Tito pak jsou sečteni z Levítů po čeledech svých: Gerson, z něhož čeled Gersonitská; Kahat, z něhož čeled Kahatská; Merari, z něhož čeled Meraritská.'),
(1550738,54,4,26,58,'Ty jsou čeledi Léví: Čeled Lebnitská, čeled Hebronitská, čeled Moholitská, čeled Musitská, čeled Choritská. Kahat pak zplodil Amrama.'),
(1550739,54,4,26,59,'A jméno manželky Amramovy Jochebed, dcera Léví, kteráž se mu narodila v Egyptě; ona pak porodila Amramovi Arona a Mojžíše, a Marii sestru jejich.'),
(1550740,54,4,26,60,'Aronovi pak zrozeni jsou: Nádab a Abiu, Eleazar a Itamar.'),
(1550741,54,4,26,61,'Ale Nádab a Abiu zemřeli, když obětovali oheň cizí před Hospodinem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550742,54,4,26,62,'I bylo jich načteno třimecítma tisíců, všech pohlaví mužského zstáří měsíce jednoho a výše; nebo nebyli počteni mezi syny Izraelskými, proto že jim nebylo dáno dědictví mezi syny Izraelskými.'),
(1550743,54,4,26,63,'Tito sečteni jsou od Mojžíše a Eleazara kněze; oni sečtli syny Izraelské na polích Moábských při Jordánu, naproti Jerichu.'),
(1550744,54,4,26,64,'Mezi těmito pak nebyl žádný z oněch sečtených od Mojžíše a Arona kněze, když počítali syny Izraelské na poušti Sinai;'),
(1550745,54,4,26,65,'(Nebo řekl byl Hospodin o nich: Smrtí zemrou na poušti;) a žádný z nich nepozůstal, jediné Kálef, syn Jefonův, a Jozue, syn Nun.'),
(1550746,54,4,27,1,'Tehdy přistoupily dcery Salfada, syna Heferova, syna Galád, syna Machir, syna Manasse, z pokolení Manasse, syna Jozefova. Tato pak jsou jména dcer jeho: Mahla, Noa, Hegla, Melcha a Tersa.'),
(1550747,54,4,27,2,'A postavily se před Mojžíšem a před Eleazarem knězem, i před knížaty a vším množstvím, u dveří stánku úmluvy, a řekly:'),
(1550748,54,4,27,3,'Otec náš umřel na poušti, kterýž však nebyl z spolku těch, kteříž se zrotili proti Hospodinu v rotě Chóre; nebo pro hřích svůj umřel, synů žádných nemaje.'),
(1550749,54,4,27,4,'Což vyhlazeno býti má jméno otce našeho z čeledi jeho, proto že neměl syna? Dej nám dědictví mezi bratřími otce našeho.'),
(1550750,54,4,27,5,'I vznesl tu věc Mojžíš na Hospodina.'),
(1550751,54,4,27,6,'Kterýž odpověděl Mojžíšovi, řka:'),
(1550752,54,4,27,7,'Dobře mluví dcery Salfad. Dejž jim bez odporu právo dědictví mezi bratřími otce jejich, a přenes dědictví otce jejich na ně.'),
(1550753,54,4,27,8,'K synům pak Izraelským toto mluviti budeš: Když by kdo umřel, nemaje syna, tedy přenesete dědictví jeho na dceru jeho.'),
(1550754,54,4,27,9,'Pakli by ani dcery neměl, tedy dáte dědictví jeho bratřím jeho.'),
(1550755,54,4,27,10,'Pakli by ani bratří neměl, tedy dáte dědictví jeho bratřím otce jeho.'),
(1550756,54,4,27,11,'Pakli by ani strýců neměl, tedy dáte dědictví jeho příteli jeho, kterýž jest nejbližší jemu v rodu jeho, aby dědičně obdržel je. A bude to synům Izraelským za ustanovení soudné, jakož přikázal Hospodin Mojžíšovi.'),
(1550757,54,4,27,12,'Řekl také Hospodin Mojžíšovi: Vstup na horu tuto Abarim, a spatř zemi, kterouž jsem dal synům Izraelským.'),
(1550758,54,4,27,13,'A když spatříš ji, připojen budeš k lidu svému i ty, jako připojen jest Aron bratr tvůj,'),
(1550759,54,4,27,14,'Poněvadž jste odporovali řeči mé na poušti Tsin, při odporování všeho množství, kdež jste mne měli posvětiti při vodách před očima jejich. To jsou ty vody sváru v Kádes, na poušti Tsin.'),
(1550760,54,4,27,15,'I řekl Mojžíš Hospodinu, řka:'),
(1550761,54,4,27,16,'Opatříš Hospodin Bůh duchů, Bůh všelikého těla, shromáždění toto mužem hodným,'),
(1550762,54,4,27,17,'Kterýž by vycházel před nimi, a kterýž by vcházel před nimi, kterýž by vyvodil a zase uvodil je, aby nebylo shromáždění Hospodinovo jako ovce, kteréž nemají pastýře.'),
(1550763,54,4,27,18,'I řekl Hospodin Mojžíšovi: Vezmi k sobě Jozue, syna Nun, muže, v kterémž jest duch můj, a vlož ruku svou na něj.'),
(1550764,54,4,27,19,'A postavě jej před Eleazarem knězem a přede vším shromážděním, dáš jemu naučení před očima jejich,'),
(1550765,54,4,27,20,'A udělíš jemu slávy své, aby ho poslouchalo všecko množství synů Izraelských.'),
(1550766,54,4,27,21,'Kterýž před Eleazarem knězem postavě se, ptáti se ho bude na soud urim před Hospodinem. K rozkazu jeho vyjdou, a k rozkazu jeho vejdou, on i všickni synové Izraelští s ním, a všecko shromáždění.'),
(1550767,54,4,27,22,'I učinil Mojžíš tak, jakž mu byl rozkázal Hospodin, a pojav Jozue, postavil jej před Eleazarem knězem a přede vším shromážděním.'),
(1550768,54,4,27,23,'A vloživ ruce své na něj, dal jemu naučení, jakž mluvil Hospodin skrze Mojžíše.'),
(1550769,54,4,28,1,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1550770,54,4,28,2,'Přikaž synům Izraelským a rci jim: Obětí mých, chleba mého, v obětech mých ohnivých u vůni spokojující mne, nezanedbávejte mi přinášeti v čas k tomu vyměřený.'),
(1550771,54,4,28,3,'Díš tedy jim: Tato jest obět ohnivá, kterouž obětovati budete Hospodinu: Beránky roční bez poškvrny dva, každého dne v obět zápalnou ustavičně.'),
(1550772,54,4,28,4,'Beránka jednoho obětovati budeš ráno, a beránka druhého obětovati budeš k večerou.'),
(1550773,54,4,28,5,'Desátý také díl míry efi mouky bělné, v obět suchou, zadělané olejem nejčistším, čtvrtou částkou míry hin.'),
(1550774,54,4,28,6,'Ta jest obět zápalná ustavičná, kteráž obětována jest na hoře Sinai u vůni příjemnou, v obět ohnivou Hospodinu.'),
(1550775,54,4,28,7,'A obět mokrá její, čtvrtý díl míry hin na každého beránka; v svatyni obětuj obět mokrou silného nápoje Hospodinu.'),
(1550776,54,4,28,8,'Beránka pak druhého obětovati budeš k večerou, tak jako obět suchou jitřní, a jako obět mokrou její obětovati budeš v obět ohnivou, u vůni spokojující Hospodina.'),
(1550777,54,4,28,9,'Dne také sobotního dva beránky roční bez poškvrny, a dvě desetiny mouky bělné, olejem zadělané v obět suchou s obětí její mokrou.'),
(1550778,54,4,28,10,'Ta bude obět zápalná sobotní každého dne sobotního, mimo zápalnou obět ustavičnou a mokrou obět její.'),
(1550779,54,4,28,11,'Také na nov měsíců vašich obětovati budete obět zápalnou Hospodinu, volky mladé dva, skopce jednoho, beránků ročních bez poškvrny sedm;'),
(1550780,54,4,28,12,'A tři desetiny mouky bělné, olejem zadělané v obět suchou při každém volku, a dvě desetiny mouky bělné, olejem zadělané v obět suchou při každém skopci;'),
(1550781,54,4,28,13,'A jednu desetinu mouky bělné olejem zadělané v obět suchou při každém beránku, k oběti zápalné u vůni příjemnou, v obět ohnivou Hospodinu.'),
(1550782,54,4,28,14,'Tyto pak oběti mokré jejich z vína: Půl míry hin bude při každém volku, a třetí částka hin při skopci, a čtvrtá částka hin při každém beránku. Ta jest obět zápalná k nov měsíci, každého měsíce přes celý rok.'),
(1550783,54,4,28,15,'Kozla také jednoho v obět za hřích, mimo obět ustavičnou, obětovati budete Hospodinu s mokrou obětí jeho.'),
(1550784,54,4,28,16,'Měsíce pak prvního, čtrnáctý den téhož měsíce velikanoc bude Hospodinu,'),
(1550785,54,4,28,17,'A v patnáctý den téhož měsíce slavnost; za sedm dní chleby nekvašené jísti budete.'),
(1550786,54,4,28,18,'Prvního dne shromáždění svaté bude, žádného díla robotného nebudete dělati v něm.'),
(1550787,54,4,28,19,'Obětovati pak budete obět ohnivou v zápal Hospodinu, volky mladé dva, skopce jednoho, a sedm beránků ročních; bez poškvrny budou.'),
(1550788,54,4,28,20,'A suchou obět při nich, totiž mouku bělnou, olejem zadělanou, tři desetiny při každém volku, a dvě desetiny při každém skopci obětovati budete.'),
(1550789,54,4,28,21,'A jednu desetinu obětovati budeš při každém beránku z těch sedmi beránků,'),
(1550790,54,4,28,22,'A kozla v obět za hřích jednoho k očištění vás.'),
(1550791,54,4,28,23,'Mimo obět zápalnou jitřní, kteráž jest obět ustavičná, obětovati budete to.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550792,54,4,28,24,'Tak obětovati budete každého dne za těch sedm dní pokrm oběti ohnivé, u vůni spokojující Hospodina, mimo zápalnou obět ustavičnou, a obět mokrou její.'),
(1550793,54,4,28,25,'Sedmého pak dne shromáždění svaté míti budete, žádného díla robotného nebudete dělati.'),
(1550794,54,4,28,26,'V den také prvotin, když obětovati budete novou obět suchou Hospodinu, vyplníc téhodny vaše, shromáždění svaté míti budete; žádného díla robotného nebudete dělati.'),
(1550795,54,4,28,27,'A obětovati budete obět zápalnou, u vůni spokojující Hospodina, volky mladé dva, skopce jednoho, beránků ročních sedm,'),
(1550796,54,4,28,28,'A obět suchou jejich, mouky bělné olejem zadělané tři desetiny při každém volku, dvě desetiny při každém skopci,'),
(1550797,54,4,28,29,'Jednu desetinu při každém beránku z těch sedmi beránků,'),
(1550798,54,4,28,30,'Kozla jednoho k očištění vašemu.'),
(1550799,54,4,28,31,'To mimo obět zápalnou ustavičnou, a obět suchou její obětovati budete; bez poškvrny ať jsou s obětmi svými mokrými.'),
(1550800,54,4,29,1,'Měsíce pak sedmého v první den jeho shromáždění svaté míti budete, žádného díla robotného nebudete dělati; to jest den troubení vašeho.'),
(1550801,54,4,29,2,'A obětovati budete zápal u vůni příjemnou Hospodinu, volka mladého jednoho, skopce jednoho, beránků ročních bez poškvrny sedm;'),
(1550802,54,4,29,3,'A obět suchou při nich z mouky bělné olejem zadělané, tři desetiny na každého volka, a dvě desetiny na každého skopce;'),
(1550803,54,4,29,4,'A desetina jedna na každého beránka z sedmi beránků;'),
(1550804,54,4,29,5,'A kozla jednoho v obět za hřích k očištění vás.'),
(1550805,54,4,29,6,'Mimo zápalnou obět novoměsíčnou s obětí její suchou, a mimo obět zápalnou ustavičnou s obětí její suchou, a s obětmi jejich mokrými vedlé pořádku jejich, u vůni příjemnou, v obět ohnivou Hospodinu.'),
(1550806,54,4,29,7,'V desátý pak den téhož měsíce sedmého shromáždění svaté míti budete, a ponižovati budete životů svých; žádného díla nebudete dělati.'),
(1550807,54,4,29,8,'A obětovati budete obět zápalnou Hospodinu u vůni příjemnou, volka mladého jednoho, skopce jednoho, beránků ročních sedm, a ti ať jsou bez poškvrny;'),
(1550808,54,4,29,9,'A obět suchou jejich z mouky bělné olejem zadělané, tři desetiny na každého volka, a dvě desetiny na každého skopce;'),
(1550809,54,4,29,10,'A desetina jedna na každého beránka z těch sedmi beránků;'),
(1550810,54,4,29,11,'Kozla jednoho v obět za hřích, mimo obět za hřích k očištění, a mimo zápal ustavičný s obětí suchou jeho, a s obětmi mokrými jejich.'),
(1550811,54,4,29,12,'V patnáctý také den měsíce sedmého shromáždění svaté míti budete; žádného díla robotného nebudete dělati, ale slaviti budete svátek Hospodinu za sedm dní.'),
(1550812,54,4,29,13,'A obětovati budete zápal v obět ohnivou u vůni spokojující Hospodina, volků mladých třinácte, skopce dva, beránků ročních čtrnácte, a ti ať jsou bez poškvrny;'),
(1550813,54,4,29,14,'Též obět suchou jejich z mouky bělné olejem zadělané, tři desetiny na každého volka z třinácti volků, dvě desetiny na každého skopce z těch dvou skopců,'),
(1550814,54,4,29,15,'A jednu desetinu na každého beránka z těch čtrnácti beránků;'),
(1550815,54,4,29,16,'A kozla jednoho v obět za hřích, mimo zápal ustavičný s obětí jeho suchou i mokrou.'),
(1550816,54,4,29,17,'Potom dne druhého volků mladých dvanácte, skopce dva, beránků ročních bez poškvrny čtrnácte,'),
(1550817,54,4,29,18,'S obětí suchou při nich, a s obětmi mokrými jejich při každém volku, skopci i beránku vedlé počtu jejich, jakž jest obyčej;'),
(1550818,54,4,29,19,'A kozla jednoho v obět za hřích, mimo zápal ustavičný s obětí suchou jeho a s obětmi mokrými jeho.'),
(1550819,54,4,29,20,'Dne pak třetího volků jedenácte, skopce dva, a beránků ročních bez poškvrny čtrnácte,'),
(1550820,54,4,29,21,'S obětí suchou a s obětmi mokrými jejich při každém volku, skopci i beránku, vedlé počtu jejich, jakž jest obyčej;'),
(1550821,54,4,29,22,'A kozla v obět za hřích jednoho, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.'),
(1550822,54,4,29,23,'Dne pak čtvrtého volků deset, skopce dva, beránků ročních bez poškvrny čtrnácte,'),
(1550823,54,4,29,24,'S obětí suchou i s obětmi mokrými jejich při každém volku, skopci a beránku, vedlé počtu jejich, jakž jest obyčej;'),
(1550824,54,4,29,25,'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.'),
(1550825,54,4,29,26,'Dne také pátého volků devět, skopce dva, beránků ročních bez poškvrny čtrnácte,'),
(1550826,54,4,29,27,'S obětí suchou i s obětmi mokrými jejich při každém volku, skopci i beránku, vedlé počtu jejich, jakž jest obyčej;'),
(1550827,54,4,29,28,'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.'),
(1550828,54,4,29,29,'A dne šestého volků osm, skopce dva, beránků ročních bez poškvrny čtrnácte,'),
(1550829,54,4,29,30,'S obětí suchou a s obětmi mokrými jejich při každém volku, skopci i beránku, vedlé počtu jejich, jakž jest obyčej;'),
(1550830,54,4,29,31,'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i s obětmi mokrými.'),
(1550831,54,4,29,32,'Tolikéž dne sedmého volků sedm, skopce dva, beránků ročních bez poškvrny čtrnácte,'),
(1550832,54,4,29,33,'S obětí suchou i s obětmi mokrými jejich na volky, skopce i beránky, vedlé počtu jejich, jakž jest obyčej;'),
(1550833,54,4,29,34,'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.'),
(1550834,54,4,29,35,'Dne pak osmého slavnost míti budete; žádného díla robotného nebudete dělati.'),
(1550835,54,4,29,36,'A obětovati budete obět zápalnou, v obět ohnivou vůně spokojující Hospodina, volka jednoho, skopce jednoho, a beránků ročních sedm bez poškvrny,'),
(1550836,54,4,29,37,'S obětí suchou i s obětmi mokrými jejich při volku, skopci i beráncích, vedlé počtu jejich, jakž jest obyčej;'),
(1550837,54,4,29,38,'A kozla jednoho v obět za hřích, mimo obět zápalnou ustavičnou s obětí její suchou i mokrou.'),
(1550838,54,4,29,39,'Ty věci vykonávati budete Hospodinu při slavnostech vašich, kromě toho, což byste z slibu aneb z dobré vůle své obětovali, buď zápalné, aneb suché, aneb mokré, aneb pokojné oběti vaše.'),
(1550839,54,4,30,1,'I oznámil Mojžíš synům Izraelským všecky ty věci, kteréž přikázal jemu Hospodin.'),
(1550840,54,4,30,2,'Mluvil také Mojžíš knížatům pokolení synů Izraelských, řka: Totoť jest, což přikázal Hospodin:'),
(1550841,54,4,30,3,'Jestliže by muž slib aneb přísahu učinil Hospodinu, závazkem zavazuje duši svou, nezruší slova svého; podlé všeho, což vyšlo z úst jeho, učiní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550842,54,4,30,4,'Když by pak osoba ženského pohlaví učinila slib Hospodinu, a závazkem zavázala se v domě otce svého v mladosti své,'),
(1550843,54,4,30,5,'A slyše otec její slib a závazek její, jímž zavázala duši svou, mlčel by k tomu: tedy stálí budou všickni slibové její, i každý závazek, jímž zavázala se, stálý bude.'),
(1550844,54,4,30,6,'Jestliže by pak to zrušil otec její toho dne, když slyšel všecky ty sliby a závazky její, jimiž zavázala duši svou, nebudouť stálí; a Hospodin odpustí jí, nebo otec její to zrušil.'),
(1550845,54,4,30,7,'Pakli by vdaná byla za muže, a měla by slib na sobě, aneb pronesla by ústy svými něco, čímž by se zavázala,'),
(1550846,54,4,30,8,'A slyše muž její, nic by jí neřekl toho dne, kteréhož slyšel: stálí budou slibové její, i závazkové, jimiž zavázala duši svou, stálí budou.'),
(1550847,54,4,30,9,'Jestliže by pak muž její toho dne, jakž uslyšel, odepřel tomu, a zrušil slib, kterýž na sobě měla, aneb něco rty svými pronesla, čímž by se zavázala, také odpustí jí Hospodin.'),
(1550848,54,4,30,10,'Všeliký pak slib vdovy aneb ženy zahnané, jímž by se zavázala, stálý bude.'),
(1550849,54,4,30,11,'Ale jestliže v domě muže svého slíbila, a závazkem zavázala se s přísahou,'),
(1550850,54,4,30,12,'A slyše to muž její, mlčel k tomu a neodepřel: tedy stálí budou všickni slibové její, a všickni závazkové, jimiž se zavázala, stálí budou.'),
(1550851,54,4,30,13,'Pakli docela odepřel muž její toho dne, jakž uslyšel, všeliký slib, kterýž vyšel z úst jejích, a závazek, jímž zavázala se, nebude stálý; muž její zrušil to, a Hospodin jí odpustí.'),
(1550852,54,4,30,14,'Všelikého slibu a každého závazku s přísahou učiněného o trápení života jejího, muž její potvrdí jeho, a muž její zruší jej.'),
(1550853,54,4,30,15,'Pakli by muž její den po dni mlčel, tedy potvrdí všech slibů jejích, a všech závazků jejích, kteréž na sobě má; potvrdilť jest jich, nebo neodepřel jí v den ten, když to uslyšel.'),
(1550854,54,4,30,16,'Jestliže by pak slyše, potom teprv zrušiti to chtěl, tedy on ponese nepravost její.'),
(1550855,54,4,30,17,'Ta jsou ustanovení, kteráž přikázal Hospodin Mojžíšovi, mezi mužem a ženou jeho, mezi otcem a dcerou jeho v mladosti její, dokudž jest v domě otce svého.'),
(1550856,54,4,31,1,'Mluvil opět Hospodin k Mojžíšovi, řka:'),
(1550857,54,4,31,2,'Pomsti prvé synů Izraelských nad Madianskými, a potom připojen budeš k lidu svému.'),
(1550858,54,4,31,3,'Mluvil tedy Mojžíš k lidu, řka: Vypravte některé z sebe k boji, aby šli proti Madianským a vykonali pomstu Hospodinovu nad nimi.'),
(1550859,54,4,31,4,'Po tisíci z pokolení, ze všech pokolení Izraelských vyšlete k boji.'),
(1550860,54,4,31,5,'I vydáno jest z mnohých tisíců Izraelských po tisíci z každého pokolení, totiž dvanácte tisíců způsobných k boji.'),
(1550861,54,4,31,6,'I poslal je Mojžíš po tisíci z každého pokolení k boji, a Fínesa syna Eleazara kněze s nimi; a nádoby svaté i trouby k troubení byly v ruce jeho.'),
(1550862,54,4,31,7,'Tedy bojovali proti Madianským, jakož byl přikázal Hospodin Mojžíšovi, a zbili všecky pohlaví mužského.'),
(1550863,54,4,31,8,'Pobili také krále Madianské mezi jinými, kteréž porazili, totiž Evi, Rekem, Sur, Hur a Rebe, pět králů Madianských; Baláma také, syna Beorova, zabili mečem.'),
(1550864,54,4,31,9,'A zajali synové Izraelští ženy Madianské i děti jejich; všecka hovada jejich, i všechny dobytky jejich, a všecka zboží jejich pobrali.'),
(1550865,54,4,31,10,'Všecka také města jejich, v kterýchž svá obydlí měli, i všecky hrady jejich vypálili ohněm.'),
(1550866,54,4,31,11,'A všecku loupež i všecky kořisti pobravše, lidi i hovada,'),
(1550867,54,4,31,12,'Vedli je k Mojžíšovi a k Eleazarovi knězi, a ke všemu množství synů Izraelských,i zajaté i kořisti, i loupeže, k vojsku na roviny Moábské, kteréž jsou při Jordánu naproti Jerichu.'),
(1550868,54,4,31,13,'I vyšli Mojžíš a Eleazar kněz a všecka knížata shromáždění proti nim ven za stany.'),
(1550869,54,4,31,14,'Tedy rozhněval se Mojžíš na vůdce vojska, hejtmany nad tisíci a setníky, kteříž se navraceli z boje,'),
(1550870,54,4,31,15,'A řekl jim Mojžíš: A což jste zachovali všecky ženy?'),
(1550871,54,4,31,16,'Ej, onyť jsou hle synům Izraelským, podlé rady Balámovy, daly příčinu k přestoupení proti Hospodinu, při modlářství Fegor, pročež ona rána přišla byla na lid Hospodinův.'),
(1550872,54,4,31,17,'Protož nyní zmordujte všecky děti pohlaví mužského, a všecky ženy, kteréž poznaly muže.'),
(1550873,54,4,31,18,'Všecky pak panny, kteréž nepoznaly muže, zachovejte sobě živé.'),
(1550874,54,4,31,19,'Vy pak zůstaňte vně za stany za sedm dní; všickni, kteřížkoli jste někoho zabili, aneb kteříž jste se zabitého dotkli, očištovati se budete dne třetího a dne sedmého, sebe i zajaté své.'),
(1550875,54,4,31,20,'Všeliké také roucho a všecky věci kožené, i všelijaké dílo z í kozích, i všelikou nádobu dřevěnou očistíte.'),
(1550876,54,4,31,21,'I řekl Eleazar kněz vojákům, kteříž byli šli k boji: Toto jest ustanovení zákona, kteréž byl přikázal Hospodin Mojžíšovi.'),
(1550877,54,4,31,22,'Zlato však, stříbro, měď, železo, cín a olovo,'),
(1550878,54,4,31,23,'A cožkoli trpí oheň, ohněm přepálíte, a přečištěno bude, však tak, když vodou očišťování obmyto bude; což pak nemůže ohně strpěti, to skrze vodu protáhnete.'),
(1550879,54,4,31,24,'Zpéřete také roucha svá v den sedmý, a čistí budete; a potom vejdete do stanů.'),
(1550880,54,4,31,25,'Mluvil i to Hospodin k Mojžíšovi, řka:'),
(1550881,54,4,31,26,'Sečti summu kořistí zajatých, tak z lidí jako z hovad, ty a Eleazar kněz, a přední z čeledi otců v lidu;'),
(1550882,54,4,31,27,'A rozdělíš ty kořisti na dva díly, jeden mezi vojáky, kteříž byli vytáhli na vojnu, a druhý mezi všecko shromáždění.'),
(1550883,54,4,31,28,'A vezmeš díl na Hospodina od mužů bojovných, kteříž byli vyšli na vojnu, jednu duši z pěti set, buďto z lidí neb z hovad, neb z oslů, neb z ovcí.'),
(1550884,54,4,31,29,'Z jejich polovice to vezmete, a dáte Eleazarovi knězi obět vzhůru pozdvižení Hospodinu.'),
(1550885,54,4,31,30,'Z polovice pak té, kteráž jest synů Izraelských, vezmeš jedno z padesáti, buďto z lidí neb z volů, neb z oslů, neb z ovcí, a tak ze všelijakých hovad, a dáš to Levítům, držícím stráž příbytku Hospodinova.'),
(1550886,54,4,31,31,'I učinil Mojžíš a Eleazar kněz tak, jakž byl rozkázal Hospodin Mojžíšovi.'),
(1550887,54,4,31,32,'A bylo té kořisti z pozůstalé ještě loupeže, kteréž nabral lid válečný, ovec šestkrát sto tisíc, sedmdesáte a pět tisíců;'),
(1550888,54,4,31,33,'A volů sedmdesáte a dva tisíce;'),
(1550889,54,4,31,34,'Oslů šedesáte a jeden tisíců;'),
(1550890,54,4,31,35,'A panen, kteréž mužů nepoznaly, všech dva a třidceti tisíců.'),
(1550891,54,4,31,36,'Dostala se pak polovice jedna na díl těm, kteříž byli vytáhli na vojnu, dobytka drobného v počtu třikrát sto tisíc, třidceti a sedm tisíců a pět set,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550892,54,4,31,37,'A na díl vzatý Hospodinu dobytka drobného šest set, sedmdesáte pět.'),
(1550893,54,4,31,38,'A z volů šest a třidceti tisíců, z nichž přišlo na díl Hospodinu sedmdesáte a dva.'),
(1550894,54,4,31,39,'Oslů také třidceti tisíc a pět set, z nichž přišlo na díl Hospodinu šedesáte a jeden.'),
(1550895,54,4,31,40,'A lidí šestnácte tisíců, z nichž přišlo na díl Hospodinu třidceti a dvě duše.'),
(1550896,54,4,31,41,'Dal tedy Mojžíš díl oddělený Hospodinu Eleazarovi knězi, jakž byl přikázal Hospodin Mojžíšovi.'),
(1550897,54,4,31,42,'Z druhé pak polovice synů Izraelských, kterouž vzal Mojžíš od těch mužů, jenž bojovali,'),
(1550898,54,4,31,43,'(A bylo té polovice k shromáždění přináležející z ovec třikrát sto tisíc, třidceti a sedm tisíců a pět set;'),
(1550899,54,4,31,44,'Volů třidceti šest tisíců;'),
(1550900,54,4,31,45,'Oslů třidceti tisíců a pět set;'),
(1550901,54,4,31,46,'A lidí šestnácte tisíců;)'),
(1550902,54,4,31,47,'Z té tedy polovice synů Izraelských vzal Mojžíš po jednom zajatém z padesáti, tak z lidí jako z hovad, a dal to Levítům, držícím stráž příbytku Hospodinova, jakž byl přikázal Hospodin Mojžíšovi.'),
(1550903,54,4,31,48,'Tedy přistoupili k Mojžíšovi vývodové vojska, hejtmané nad tisíci a setníci,'),
(1550904,54,4,31,49,'A řekli jemu: My služebníci tvoji sečtli jsme počet bojovníků, kteréž jsme měli pod spravou naší, a neubyl ani jeden z nás.'),
(1550905,54,4,31,50,'A protož obětujeme obět Hospodinu, každý z toho, čehož jest dostal, nádobí zlaté, zápony, náramky, prsteny, náušnice a řetízky, aby očištěny byly duše naše před Hospodinem.'),
(1550906,54,4,31,51,'Vzal tedy Mojžíš a Eleazar kněz od nich to zlato všelikého díla řemeslného.'),
(1550907,54,4,31,52,'Bylo pak všeho zlata odděleného, kteréž obětováno Hospodinu, šestnácte tisíců, sedm set a padesáte lotů, od hejtmanů nad tisíci a od setníků.'),
(1550908,54,4,31,53,'(Muži zajisté bojovní, což loupeží vzali, to sobě měli.)'),
(1550909,54,4,31,54,'A vzavše Mojžíš a Eleazar kněz od hejtmanů nad tisíci a setníků to zlato, vnesli je do stánku úmluvy, na památku synů Izraelských před Hospodinem.'),
(1550910,54,4,32,1,'Měli pak synové Ruben a synové Gád dobytka velmi mnoho, a uzřeli zemi Jazer a zemi Galád, ano místo to místo příhodné pro dobytek.'),
(1550911,54,4,32,2,'Protož přistoupivše synové Gád a synové Ruben, mluvili k Mojžíšovi a k Eleazarovi knězi a knížatům shromáždění, řkouce:'),
(1550912,54,4,32,3,'Atarot a Dibon, a Jazer a Nemra, Ezebon a Eleale, a Saban a Nébo a Beon,'),
(1550913,54,4,32,4,'Země, kterouž zbil Hospodin před shromážděním Izraelským, jest země příhodná ku pastvě dobytku, a my služebníci tvoji máme drahně dobytka.'),
(1550914,54,4,32,5,'(Protož řekli:) Jestliže jsme nalezli milost před očima tvýma, nechť jest dána krajina ta služebníkům tvým k vládařství, ať nechodíme za Jordán.'),
(1550915,54,4,32,6,'I odpověděl Mojžíš synům Gád a synům Ruben: Což bratří vaši půjdou sami k boji, a vy zde zůstanete?'),
(1550916,54,4,32,7,'I proč roztrhujete mysli synů Izraelských, aby nesměli jíti do země, kterouž jim dal Hospodin?'),
(1550917,54,4,32,8,'Takť jsou učinili otcové vaši, když jsem je poslal z Kádesbarne, aby prohlédli zemi tu.'),
(1550918,54,4,32,9,'Kteřížto, když přišli až k údolí Eškol a shlédli zemi, potom vrátivše se, odvrátili mysl synů Izraelských, aby nešli do země, kterouž dal jim Hospodin.'),
(1550919,54,4,32,10,'Čímž popuzen jsa k hněvu Hospodin v den ten, přisáhl, řka:'),
(1550920,54,4,32,11,'Zajisté že lidé ti, kteříž vyšli z Egypta, od dvadcítiletých a výše, neuzří země té, kterouž jsem s přísahou zaslíbil Abrahamovi, Izákovi a Jákobovi, nebo ne cele následovali mne,'),
(1550921,54,4,32,12,'Kromě Kálefa, syna Jefonova Cenezejského, a Jozue, syna Nun, nebo cele následovali Hospodina.'),
(1550922,54,4,32,13,'I popudila se prchlivost Hospodinova na Izraele, a učinil, aby byli tuláci na poušti za čtyřidceti let, dokudž nezahynul všecken ten věk, kterýž činil zlé před očima Hospodinovýma.'),
(1550923,54,4,32,14,'A hle, vy nastoupili jste na místo otců svých, plémě lidí hříšných, abyste vždy přidávali k hněvu prchlivosti Hospodinovy na Izraele.'),
(1550924,54,4,32,15,'Jestliže se odvrátíte od následování jeho, i onť také opustí jej na poušti této, a tak budete příčina zahynutí všeho lidu tohoto.'),
(1550925,54,4,32,16,'Přistoupivše pak znovu, řekli jemu: Stáje dobytkům a stádům svým zde vzděláme, a města dítkám svým,'),
(1550926,54,4,32,17,'Sami pak v odění pohotově budeme, statečně sobě počínajíce před syny Izraelskými, dokavadž jich neuvedeme na místo jejich; mezi tím zůstanou dítky naše v městech hrazených, pro bezpečnost před obyvateli země.'),
(1550927,54,4,32,18,'Nenavrátíme se do domů svých, až prvé vládnouti budou synové Izraelští jeden každý dědictvím svým;'),
(1550928,54,4,32,19,'Aniž vezmeme jakého dědictví s nimi za Jordánem neb dále, když dosáhneme dědictví svého z této strany Jordánu, k východu slunce.'),
(1550929,54,4,32,20,'I odpověděl jim Mojžíš: Jestliže učiníte tak, jakž jste mluvili, a jestliže půjdete v odění před Hospodinem k boji,'),
(1550930,54,4,32,21,'A šli byste za Jordán vy všickni v odění před Hospodinem, dokavadž by nevyhnal nepřátel svých od tváři své,'),
(1550931,54,4,32,22,'A nebyla podmaněna všecka země před Hospodinem: potom navrátíte se, a budete bez viny před Hospodinem i před Izraelem; tak přijde země tato vám v dědictví před Hospodinem.'),
(1550932,54,4,32,23,'Pakli neučiníte toho, hle, zhřešíte proti Hospodinu, a vězte, že pomsta vaše přijde na vás.'),
(1550933,54,4,32,24,'Stavějte sobě tedy města pro dítky, a stáje pro dobytky své, a což vyšlo z úst vašich, učiňte.'),
(1550934,54,4,32,25,'I odpovědělo pokolení synů Gád a synů Ruben Mojžíšovi, řka: Služebníci tvoji učiní, jakž pán náš rozkazuje.'),
(1550935,54,4,32,26,'Dítky naše a ženy naše, dobytek náš a všecka hovada naše, tu zůstanou v městech Galád,'),
(1550936,54,4,32,27,'Služebníci pak tvoji přejdou jeden každý v odění způsobný před Hospodinem k boji, jakož mluví pán můj.'),
(1550937,54,4,32,28,'I poručil o nich Mojžíš Eleazarovi knězi a Jozue, synu Nun, a předním v čeledech pokolení synů Izraelských,'),
(1550938,54,4,32,29,'A řekl jim: Jestliže přejdou synové Gád a synové Ruben s vámi za Jordán všickni hotovi k boji před Hospodinem, a byla by již podmaněna země před vámi, dáte jim zemi Galád k vládařství.'),
(1550939,54,4,32,30,'Pakli by nešli v odění s vámi, tedy dědictví míti budou u prostřed vás v zemi Kanán.'),
(1550940,54,4,32,31,'I odpověděli synové Gád a synové Ruben, řkouce: Jakž mluvil Hospodin služebníkům tvým, tak učiníme:'),
(1550941,54,4,32,32,'My půjdeme v odění před Hospodinem do země Kanán, a zůstane nám v dědictví vládařství naše z této strany Jordánu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550942,54,4,32,33,'Tedy dal jim Mojžíš, synům totiž Gád a synům Ruben a polovici pokolení Manasses, syna Jozefova, království Seona, krále Amorejského, a království Oga, krále Bázanského, zemi s městy jejími při pomezích, i města země té všudy vůkol.'),
(1550943,54,4,32,34,'A vzdělali synové Gád, Dibon, Atarot a Aroer,'),
(1550944,54,4,32,35,'A Atrot, Sofan, Jazer a Jegbaa,'),
(1550945,54,4,32,36,'A Betnemra a Betaran, města hrazená, a stáje pro dobytky.'),
(1550946,54,4,32,37,'Synové pak Ruben vystavěli Ezebon, Eleale a Kariataim,'),
(1550947,54,4,32,38,'A Nébo a Balmeon, změnivše jim jména; také Sabma, a dali jiná jména městům, kteráž vzdělali.'),
(1550948,54,4,32,39,'Táhli pak synové Machir, syna Manassesova, do Galád, a vzavše tu krajinku, vyhnali Amorejského, kterýž tam bydlil.'),
(1550949,54,4,32,40,'I dal Mojžíš zemi Galád Machirovi, synu Manassesovu, a bydlil v ní.'),
(1550950,54,4,32,41,'Jair také syn Manassesův táhl a vzal vsi jejich, a nazval je vsi Jairovy.'),
(1550951,54,4,32,42,'Nobe také táhl, a vzal Kanat a městečka jeho, a nazval je Nobe od jména svého.'),
(1550952,54,4,33,1,'Tato jsou tažení synů Izraelských, kteříž vyšli z země Egyptské po houfích svých, pod spravou Mojžíše a Arona.'),
(1550953,54,4,33,2,'Sepsal pak Mojžíš vycházení jejich podlé toho, jakž táhli k rozkazu Hospodinovu. Tato jsou tedy vycházení jejich podlé toho, jakž táhli.'),
(1550954,54,4,33,3,'Nejprv z Ramesses jdouce prvního měsíce, v patnáctý den téhož prvního měsíce, nazejtří po slavnosti Fáze vyšli synové Izraelští v ruce silné před očima všech Egyptských,'),
(1550955,54,4,33,4,'Kdyžto Egyptští pochovávali všecky prvorozené, kteréž zbil Hospodin mezi nimi, a při bozích jejich vykonal Hospodin soudy své.'),
(1550956,54,4,33,5,'Hnuvše se tedy synové Izraelští z Ramesses, položili se v Sochot.'),
(1550957,54,4,33,6,'Potom hnuvše se z Sochot, položili se v Etam, jenž jest při kraji pouště.'),
(1550958,54,4,33,7,'A hnuvše se z Etam, navrátili se zase k Fiarot, jenž jest před Belsefon, a položili se před Magdalem.'),
(1550959,54,4,33,8,'A hnuvše se z Fiarot, šli prostředkem moře na poušť, a ušedše tří dnů cesty po poušti Etam, položili se v Marah.'),
(1550960,54,4,33,9,'Jdouce pak z Marah, přišli do Elim, kdežto bylo dvanácte studnic vod, a sedmdesáte palm. I položili se tu.'),
(1550961,54,4,33,10,'A hnuvše se z Elim, položili se u moře Rudého.'),
(1550962,54,4,33,11,'Potom hnuvše se od moře Rudého, položili se na poušti Sin.'),
(1550963,54,4,33,12,'A když se hnuli z pouště Sin, položili se v Dafka.'),
(1550964,54,4,33,13,'A hnuvše se z Dafka, položili se v Halus.'),
(1550965,54,4,33,14,'Hnuvše se pak z Halus, rozbili stany v Rafidim, kdežto lid neměl vody ku pití.'),
(1550966,54,4,33,15,'A hnuvše se z Rafidim, položili se na poušti Sinai.'),
(1550967,54,4,33,16,'Hnuvše se pak z pouště Sinai, položili se v Kibrot Hattáve.'),
(1550968,54,4,33,17,'A když se hnuli z Kibrot Hattáve, položili se v Hazerot.'),
(1550969,54,4,33,18,'Hnuvše se pak z Hazerot, položili se v Retma.'),
(1550970,54,4,33,19,'A z Retma hnuvše se, položili se v Remmon Fáres.'),
(1550971,54,4,33,20,'Potom hnuvše se z Remmon Fáres, položili se v Lebna.'),
(1550972,54,4,33,21,'A hnuvše se z Lebna, položili se v Ressa.'),
(1550973,54,4,33,22,'A hnuvše se z Ressa, položili se v Cehelot.'),
(1550974,54,4,33,23,'Z Cehelot pak hnuvše se, položili se na hoře Sefer.'),
(1550975,54,4,33,24,'A když se hnuli s hory Sefer, položili se v Arad.'),
(1550976,54,4,33,25,'A hnuvše se z Arad, položili se v Machelot.'),
(1550977,54,4,33,26,'Potom hnuvše se z Machelot, položili se v Tahat.'),
(1550978,54,4,33,27,'A hnuvše se z Tahat, položili se v Tár.'),
(1550979,54,4,33,28,'A když se hnuli z Tár, položili se v Metka.'),
(1550980,54,4,33,29,'A hnuvše se z Metka, položili se v Esmona.'),
(1550981,54,4,33,30,'Z Esmona pak hnuvše se, položili se v Moserot.'),
(1550982,54,4,33,31,'A když se hnuli z Moserot, položili se v Benejakan.'),
(1550983,54,4,33,32,'A hnuvše se z Benejakan, položili se v Chor Gidgad.'),
(1550984,54,4,33,33,'A hnuvše se z Chor Gidgad, položili se v Jotbata.'),
(1550985,54,4,33,34,'Když se pak hnuli z Jotbata, položili se v Habrona.'),
(1550986,54,4,33,35,'A z Habrona hnuvše se, položili se v Aziongaber.'),
(1550987,54,4,33,36,'A odtud hnuvše se, položili se na poušti Tsin, jenž jest Kádes.'),
(1550988,54,4,33,37,'A hnuvše se z Kádes, položili se na hoře řečené Hor, při končinách země Edomské.'),
(1550989,54,4,33,38,'Tu vstoupil Aron kněz na horu, jenž slove Hor, k rozkazu Hospodinovu, a umřel tam, léta čtyřidcátého po vyjití synů Izraelských z země Egyptské, v první den měsíce pátého.'),
(1550990,54,4,33,39,'A byl Aron ve stu ve dvadcíti a třech letech, když umřel na hoře Hor.'),
(1550991,54,4,33,40,'Uslyšel také Kananejský král v Arad, kterýž bydlil na poledne v zemi Kananejské, že by táhli synové Izraelští.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1550992,54,4,33,41,'Tedy hnuvše se s hory Hor, položili se v Salmona.'),
(1550993,54,4,33,42,'A hnuvše se z Salmona, položili se v Funon.'),
(1550994,54,4,33,43,'Z Funon pak hnuvše se, položili se v Obot.'),
(1550995,54,4,33,44,'A když se hnuli z Obot, rozbili stany při pahrbcích hor Abarim, na pomezí Moábském.'),
(1550996,54,4,33,45,'Potom hnuvše se od těch pahrbků, položili se v Dibongad.'),
(1550997,54,4,33,46,'Z Dibongad hnuvše se, položili se v Helmondeblataim.'),
(1550998,54,4,33,47,'A když se hnuli z Helmondeblataim, položili se na horách Abarim proti Nébo.'),
(1550999,54,4,33,48,'Odšedše pak z hor Abarim, položili se na rovinách Moábských, při Jordánu proti Jerichu.'),
(1551000,54,4,33,49,'A rozbili stany při Jordánu, od Betsimot až do Abelsetim, na rovinách Moábských.'),
(1551001,54,4,33,50,'Mluvil pak Hospodin k Mojžíšovi na rovinách Moábských, při Jordánu naproti Jerichu, řka:'),
(1551002,54,4,33,51,'Mluv k synům Izraelským a rci jim: Když přejdete Jordán, a vejdete do země Kananejské,'),
(1551003,54,4,33,52,'Vyžeňte všecky obyvatele země té od tváři vaší, a zkazte všecky rytiny jejich; i všecky obrazy slité jejich zkazte, všecky také výsosti jejich zbořte.'),
(1551004,54,4,33,53,'A když vyženete obyvatele země, bydliti budete v ní; nebo vám jsem dal tu zemi, abyste jí dědičně vládli.'),
(1551005,54,4,33,54,'Kteroužto rozdělíte sobě k dědictví losem, vedlé čeledí svých. Kterých jest více, těm větší dědictví dáte, kterých pak jest méně, těm menší dědictví dáte. Na kterém místě komu los padne, to jemu bude; podlé pokolení otců svých dědictví dosáhnete.'),
(1551006,54,4,33,55,'Pakli nevyženete obyvatelů země od tváři své, tedy ti, kterýchž zanecháte, budou vám jako trní v očích vašich, a jako ostnové po bocích vašich, a budou vás ssužovati na zemi, na kteréž vy bydliti budete.'),
(1551007,54,4,33,56,'A na to přijde, abych to, což jsem jim umínil učiniti, vám učinil.'),
(1551008,54,4,34,1,'Mluvil také Hospodin k Mojžíšovi, řka:'),
(1551009,54,4,34,2,'Přikaž synům Izraelským a rci jim: Když vejdete do země Kanán, (tať jest země, kteráž se dostane vám v dědictví, země Kananejská s pomezími svými),'),
(1551010,54,4,34,3,'Strana polední vaše bude poušť Tsin vedlé pomezí Edomských; a bude vaše pomezí polední od břehu moře slaného k východu.'),
(1551011,54,4,34,4,'A zatočí se to pomezí polední k Maleakrabim, a půjde až k Tsin, a potáhne se od poledne přes Kádesbarne; a odtud vyjde ke vsi Addar, a vztáhne se až k Asmon.'),
(1551012,54,4,34,5,'Od Asmon zatočí se pomezí to vůkol až ku potoku Egyptskému, a tu se skonávati bude k západu.'),
(1551013,54,4,34,6,'Pomezí pak západní budete míti moře veliké; to bude vaše pomezí západní.'),
(1551014,54,4,34,7,'A pomezí půlnoční toto míti budete:Od moře velikého vyměříte sobě k hoře řečené Hor.'),
(1551015,54,4,34,8,'Od hory Hor vyměříte sobě, až kde se vchází do Emat, a skonávati se bude pomezí to u Sedad.'),
(1551016,54,4,34,9,'A odtud půjde pomezí to k Zefronu, a konec jeho u vsi Enan; to bude pomezí vaše k straně půlnoční.'),
(1551017,54,4,34,10,'Vyměříte sobě také pomezí k východu od vsi Enan až do Sefama.'),
(1551018,54,4,34,11,'A od Sefama schýlí se to pomezí až k Reblata, od východu maje Ain; a schýlí se pomezí to, a přijde k straně moře Ceneret k východu.'),
(1551019,54,4,34,12,'A vztáhne se to pomezí k Jordánu, a bude konec jeho u slaného moře. Ta země vaše bude po svých pomezích vůkol.'),
(1551020,54,4,34,13,'Tedy oznámil to Mojžíš synům Izraelským, řka: Ta jest země, kterouž dědičně obdržíte losem, jakož přikázal Hospodin, abych ji dal devateru pokolení a polovici pokolení Manassesova.'),
(1551021,54,4,34,14,'Nebo vzalo pokolení synů Ruben po domích otců svých, a pokolení synů Gád po domích otců svých, a polovice pokolení Manassesova vzali dědictví své.'),
(1551022,54,4,34,15,'Půl třetího pokolení vzali dědictví své před Jordánem proti Jerichu, k straně na východ slunce.'),
(1551023,54,4,34,16,'Mluvil opět Hospodin k Mojžíšovi, řka:'),
(1551024,54,4,34,17,'Tato jsou jména mužů, kteříž v dědictví rozdělí vám zemi: Eleazar kněz, a Jozue, syn Nun.'),
(1551025,54,4,34,18,'Kníže také jedno z každého pokolení vezmete k rozdělování dědictví země.'),
(1551026,54,4,34,19,'A tato jsou jména mužů: Z pokolení Juda Kálef, syn Jefonův;'),
(1551027,54,4,34,20,'Z pokolení synů Simeon Samuel, syn Amiudův;'),
(1551028,54,4,34,21,'Z pokolení Beniaminova Helidad, syn Chaselonův;'),
(1551029,54,4,34,22,'Z pokolení synů Dan kníže Bukci, syn Jogli;'),
(1551030,54,4,34,23,'Z synů Jozefových z pokolení synů Manasses kníže Haniel, syn Efodův;'),
(1551031,54,4,34,24,'Z pokolení synů Efraim kníže Kamuel, syn Seftanův;'),
(1551032,54,4,34,25,'A z pokolení synů Zabulon kníže Elizafan, syn Farnachův;'),
(1551033,54,4,34,26,'Z pokolení synů Izachar kníže Faltiel, syn Ozanův;'),
(1551034,54,4,34,27,'A z pokolení synů Asser kníže Ahiud, syn Salonův;'),
(1551035,54,4,34,28,'A z pokolení synů Neftalím kníže Fedael, syn Amiudův.'),
(1551036,54,4,34,29,'Ti jsou, jimž přikázal Hospodin, aby rozdělili země k dědictví synům Izraelským v zemi Kananejské.'),
(1551037,54,4,35,1,'I mluvil Hospodin k Mojžíšovi na rovinách Moábských, při Jordánu proti Jerichu, řka:'),
(1551038,54,4,35,2,'Přikaž synům Izraelským, ať dadí Levítům z dědictví, kterýmž vládnouti budou, města k bydlení, i podměstí měst vůkol nich,'),
(1551039,54,4,35,3,'Aby měli města k bydlení, podměstí pak jejich pro dobytky jejich, i pro statky jejich, a pro všecka hovada jejich.'),
(1551040,54,4,35,4,'Podměstí pak měst, kteráž dáte Levítům, vzdálí budou ode zdi městské na tisíc loktů zevnitř vůkol.'),
(1551041,54,4,35,5,'Protož vyměříte vně za každým městem na východ slunce dva tisíce loktů, na poledne též dva tisíce loktů, také na západ dva tisíce loktů, i na půlnoci dva tisíce loktů, tak aby bylo město v prostředku. Ta bude míra podměstí měst jejich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551042,54,4,35,6,'Z těch pak měst, kteráž dáte Levítům, oddělíte šest měst k útočišti, aby tam utekl, kdož by někoho zabil; a k těm přidáte jim ještě čtyřidceti dvě města.'),
(1551043,54,4,35,7,'I bude všech měst, kteráž dáte Levítům, čtyřidceti osm měst i s podměstími jejich.'),
(1551044,54,4,35,8,'Těch pak měst, kteráž dáte z vládařství synů Izraelských, od těch, kteříž více mají, více vezmete, a od těch, kteříž méně mají, méně vezmete; jedno každé pokolení vedlé velikosti dědictví, jímž vládnouti budou, dá z měst svých Levítům.'),
(1551045,54,4,35,9,'I mluvil Hospodin k Mojžíšovi, řka:'),
(1551046,54,4,35,10,'Mluv k synům Izraelským a rci jim: Když přejdete Jordán, a vejdete do země Kananejské,'),
(1551047,54,4,35,11,'Vybéřete sobě města, a ta města budete míti k utíkání, aby tam utekl ten, kterýž by někoho zabil z nedopatření.'),
(1551048,54,4,35,12,'A budou vám ta města k útočišti před přítelem, aby neumřel ten, kdož zabil, dokudž by se nepostavil před shromážděním k soudu.'),
(1551049,54,4,35,13,'Z těch tedy měst, kteráž dáte, šest měst k útočišti míti budete.'),
(1551050,54,4,35,14,'Tři města dáte před Jordánem, též tři města dáte v zemi Kananejské; i budou města útočiště.'),
(1551051,54,4,35,15,'Synům Izraelským i příchozímu, i podruhu mezi nimi bude těch šest měst k útočišti, aby tam utekl, kdož by koli ranil někoho z nedopatření.'),
(1551052,54,4,35,16,'Jestliže by pak železem ranil někoho, tak až by umřel, vražedlník jest; smrtí umře vražedlník takový.'),
(1551053,54,4,35,17,'Pakli by hodě kamenem, jímž by mohl zabiti, udeřil někoho, tak že by umřel, vražedlník jest; smrtí umře vražedlník takový.'),
(1551054,54,4,35,18,'Pakli by hodě dřevem, kterýmž by mohl zabiti, udeřil někoho, tak že by umřel, vražedlník jest; smrtí umře vražedlník takový.'),
(1551055,54,4,35,19,'Přítel zabitého zabije vražedlníka toho; kdyžkoli ho dostane, on sám zabije ho.'),
(1551056,54,4,35,20,'Aneb jestliže by z nenávisti strčil někým, aneb shodil by něco na něho z úkladu, tak že by od toho umřel;'),
(1551057,54,4,35,21,'Aneb jestliže by z nepřátelství rukou udeřil někoho, tak že by umřel: smrtí umře bitec ten, vražedlník jest; přítel zabitého zabije vražedlníka toho, jakž ho nejprv dostane.'),
(1551058,54,4,35,22,'Jestliže by pak náhodou a ne z nepřátelství strčil někým, aneb shodil by na něho nějakou věc bez úkladu;'),
(1551059,54,4,35,23,'Aneb jaký koli kámen, od něhož by umříti mohl, shodil by na něj z nedopatření, tak že by umřel, nebyv s ním v nepřátelství, ani nehledaje zlého jeho:'),
(1551060,54,4,35,24,'Tedy souditi bude shromáždění mezi bitcem a mezi přítelem zabitého vedlé soudů těchto.'),
(1551061,54,4,35,25,'A vysvobodí shromáždění vražedlníka toho z rukou přítele zabitého, a káže se jemu navrátiti shromáždění k městu útočiště jeho, do něhož utekl; i bude bydliti v něm, dokudž neumře kněz nejvyšší, kterýž pomazán jest olejem svatým.'),
(1551062,54,4,35,26,'Jestliže by pak ten, kterýž zabil člověka, vyšel z mezí města útočiště svého, do něhož utekl,'),
(1551063,54,4,35,27,'A přítel zabitého našel by jej vně, an přešel meze města útočiště svého, a zabil by přítel zabitého vražedlníka toho, nebude vinen krví.'),
(1551064,54,4,35,28,'Nebo v městě útočiště svého bydliti má, dokudž by neumřel kněz nejvyšší. Když by pak umřel kněz nejvyšší, navrátí se vražedlník do země vládařství svého.'),
(1551065,54,4,35,29,'A bude vám toto za ustanovení soudné v pronárodech vašich, ve všech příbytcích vašich.'),
(1551066,54,4,35,30,'Kdož by koli měl na smrt vydati někoho, podlé vyznání svědků sáhne na vražedlníka; ale jeden svědek nebude moci svědčiti proti někomu na smrt.'),
(1551067,54,4,35,31,'Nevezmete pak výplaty za člověka vražedlníka, kterýž, jsa nešlechetný, jest smrti hoden, než smrtí ať umře.'),
(1551068,54,4,35,32,'Aniž také vezmete výplaty od toho, kterýž utekl do města útočiště svého, aby se navrátil k bydlení do země své, prvé než by umřel kněz,'),
(1551069,54,4,35,33,'Abyste nepoškvrnili země, v níž jste. Nebo krev taková poškvrnila by země, aniž také země očištěna býti může od krve, kteráž jest vylita na ní, jediné krví toho, kterýž vylil ji.'),
(1551070,54,4,35,34,'Protož nepoškvrňujte země, v kteréž bydlíte, kdežto já přebývám; nebo já Hospodin přebývám u prostřed synů Izraelských.'),
(1551071,54,4,36,1,'Přistoupili pak starší z čeledi synů Galád, syna Machir, syna Manassesova, z čeledi synů Jozefových, a mluvili před Mojžíšem a před knížaty předními z synů Izraelských,'),
(1551072,54,4,36,2,'A řekli: Tobě pánu mému přikázal Hospodin, abys losem dal zemi v dědictví synům Izraelským; přikázáno jest také pánu mému od Hospodina, aby dal dědictví Salfada, bratra našeho, dcerám jeho.'),
(1551073,54,4,36,3,'Kteréž jestliže někomu z pokolení synů Izraelských, kromě z pokolení svého, dány budou za manželky, odejde dědictví jejich od dědictví otců našich, a přidáno bude k dědictví pokolení toho, do kteréhož by se vdaly, a tak z losu dědictví našeho ubude.'),
(1551074,54,4,36,4,'A když budou míti synové Izraelští léto milostivé, připojeno bude dědictví jejich k dědictví pokolení toho, do kteréhož by se vdaly, a tak od dědictví pokolení otců našich odtrženo bude dědictví jejich.'),
(1551075,54,4,36,5,'Tedy přikázal Mojžíš synům Izraelským podlé řeči Hospodinovy, řka: Dobře pokolení synů Jozefových mluví.'),
(1551076,54,4,36,6,'To jest, což přikázal Hospodin o dcerách Salfadových, řka: Za kohož se jim líbiti bude, nechť se vdadí, však v čeledi domu otce svého ať se vdávají,'),
(1551077,54,4,36,7,'Aby nebylo přenášíno dědictví synů Izraelských z pokolení na pokolení; nebo synové Izraelští jeden každý přídržeti se bude dědictví pokolení otců svých.'),
(1551078,54,4,36,8,'A každá dcera z pokolení synů Izraelských, kteráž by měla dědictví, za někoho z čeledi pokolení otce svého vdá se, aby vládli synové Izraelští jeden každý dědictvím otců svých,'),
(1551079,54,4,36,9,'Aby nebylo přenášíno vládařství z jednoho pokolení na druhé pokolení, ale jeden každý z pokolení synů Izraelských dědictví svého přídržeti se bude.'),
(1551080,54,4,36,10,'Jakož přikázal Hospodin Mojžíšovi, tak učinily dcery Salfadovy.'),
(1551081,54,4,36,11,'Nebo Mahla, Tersa a Hegla, Melcha a Noa, dcery Salfad, vdaly se za syny strýců svých.'),
(1551082,54,4,36,12,'Do čeledi synů Manasse, syna Jozefova, vdaly se, a zůstalo dědictví jejich při pokolení čeledi otce jejich.'),
(1551083,54,4,36,13,'Tato jsou přikázaní a soudové, kteréž přikázal Hospodin skrze Mojžíše synům Izraelským, na rovinách Moábských, při Jordánu proti Jerichu.'),
(1551084,54,5,1,1,'Tato jsou slova, kteráž mluvil Mojžíš ke všemu lidu Izraelskému před Jordánem na poušti, na rovinách proti moři Rudému, mezi Fáran a Tofel a Lában a Hazerot a Dizahab.'),
(1551085,54,5,1,2,'Jedenácte dní cesty jest od Oréb přes hory Seir až do Kádesbarne.'),
(1551086,54,5,1,3,'Stalo se pak čtyřidcátého léta, jedenáctého měsíce, v první den téhož měsíce, že mluvil Mojžíš synům Izraelským všecky věci, kteréž jemu byl přikázal Hospodin oznámiti jim,'),
(1551087,54,5,1,4,'Kdyžto již byl zabil Seona, krále Amorejského, kterýž bydlil v Ezebon, a Oga, krále Bázan, kterýž bydlil v Astarot, zabil v Edrei.'),
(1551088,54,5,1,5,'Před Jordánem, v zemi Moábské, počal Mojžíš vysvětlovati zákona tohoto, řka:'),
(1551089,54,5,1,6,'Hospodin Bůh náš mluvil k nám na Orébě, řka: Dosti jste již na hoře této bydlili.'),
(1551090,54,5,1,7,'Obraťte se, táhněte a jděte k hoře Amorejských, na všecko vůkolí její, buď na roviny, na hory, na údolí, na poledne, i na břehy mořské, k zemi Kananejské a k Libánu, až k řece veliké, k řece Eufrates.'),
(1551091,54,5,1,8,'Ej, ukázal jsem vám tu zemi; vejdětež do ní, a dědičně vládněte jí, kterouž s přísahou zaslíbil dáti Hospodin otcům vašim, Abrahamovi, Izákovi a Jákobovi, i semeni jejich po nich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551092,54,5,1,9,'A mluvil jsem k vám toho času, řka: Nemohuť sám nésti vás.'),
(1551093,54,5,1,10,'Hospodin Bůh váš rozmnožil vás, a hle, rozmnoženi jste dnes jako hvězdy nebeské.'),
(1551094,54,5,1,11,'(Hospodin Bůh otců vašich rozmnožiž vás nad to, jakž jste nyní, tisíckrát více, a požehnej vám, jakož jest mluvil vám.)'),
(1551095,54,5,1,12,'Kterak bych nesl sám práci vaši, břímě vaše a nesnáze vaše?'),
(1551096,54,5,1,13,'Vydejte z sebe muže moudré a opatrné, a zkušené z pokolení svých, abych je vám představil.'),
(1551097,54,5,1,14,'I odpověděli jste mi a řekli jste: Dobráť jest ta věc, kterouž jsi učiniti rozkázal.'),
(1551098,54,5,1,15,'Vzav tedy přední z pokolení vašich, muže moudré a zkušené, ustanovil jsem je knížaty nad vámi, hejtmany nad tisíci, setníky, padesátníky, desátníky a správce v pokoleních vašich.'),
(1551099,54,5,1,16,'Přikázal jsem také soudcům vašim toho času, řka: Vyslýchejte pře mezi bratřími svými, a suďte spravedlivě mezi mužem a bratrem jeho, i mezi příchozím jeho.'),
(1551100,54,5,1,17,'Nebudete přijímati osoby v soudu; jakž malého tak i velikého slyšeti budete, nebudete se báti žádného, nebo Boží soud jest. Jestliže byste pak měli jakou věc nesnadnou, vznesete na mne, a vyslyším ji.'),
(1551101,54,5,1,18,'Přikázal jsem vám, pravím, toho času všecko, co byste činiti měli.'),
(1551102,54,5,1,19,'Potom pak hnuvše se z Oréb, přešli jsme všecku poušť tuto velikou a hroznou, kterouž jste viděli, jdouce cestou k hoře Amorejských, jakož nám byl přikázal Hospodin Bůh náš, a přišli jsme až do Kádesbarne.'),
(1551103,54,5,1,20,'I řekl jsem vám: Přišli jste až k hoře Amorejské, kterouž Hospodin Bůh náš dává nám.'),
(1551104,54,5,1,21,'Ej, dal Hospodin Bůh tvůj tu zemi tobě; vstupiž a vládni jí, jakož řekl Hospodin Bůh otců tvých tobě; neboj se, aniž se strachuj.'),
(1551105,54,5,1,22,'Vy pak všickni přistoupili jste ke mně a řekli jste: Pošleme muže před sebou, kteříž by nám shlédli zemi, a oznámili by nám něco o cestě, kterouž bychom vstoupiti měli, i města, do nichž bychom přijíti měli.'),
(1551106,54,5,1,23,'Kterážto řeč líbila se mně, a vzal jsem z vás dvanácte mužů, jednoho muže z každého pokolení.'),
(1551107,54,5,1,24,'A oni obrátivše se a vstoupivše na horu, přišli až k údolí Eškol a shlédli zemi.'),
(1551108,54,5,1,25,'Nabrali také s sebou ovoce země té, a přinesli nám, a oznámili nám o těch věcech, řkouce: Dobráť jest země, kterouž Hospodin Bůh náš dává nám.'),
(1551109,54,5,1,26,'A však jste nechtěli jíti, ale odpírali jste řeči Hospodina Boha svého.'),
(1551110,54,5,1,27,'A reptali jste v staních svých, řkouce: Proto že nás v nenávisti měl Hospodin, vyvedl nás z země Egyptské, aby nás vydal v ruce Amorejského, a zahladil nás.'),
(1551111,54,5,1,28,'Kam bychom šli? Bratří naši zstrašili srdce naše, pravíce: Lid ten jest větší a vyšší nežli my, města veliká a hrazená až k nebi, ano i syny Enakovy tam jsme viděli.'),
(1551112,54,5,1,29,'I řekl jsem vám: Nebojte se, ani se strachujte jich.'),
(1551113,54,5,1,30,'Hospodin Bůh váš, kterýž jde před vámi, onť bojovati bude za vás rovně tak, jakž učinil s vámi v Egyptě, před očima vašima.'),
(1551114,54,5,1,31,'Ano i na poušti viděl jsi, kterak nesl tebe Hospodin Bůh tvůj, jako nosí člověk syna svého, a to po vší cestě, kterouž jste šli, až jste přišli na toto místo.'),
(1551115,54,5,1,32,'A ani tak uvěřili jste Hospodinu Bohu svému,'),
(1551116,54,5,1,33,'Kterýž k vyhledání vám místa, na kterémž byste se klásti měli, v noci předcházel vás cestou v ohni, aby vám ukázal cestu, kterouž byste měli jíti, a v oblace ve dne.'),
(1551117,54,5,1,34,'Uslyšel pak Hospodin hlas řečí vašich, a rozhněval se, a přisáhl, řka:'),
(1551118,54,5,1,35,'Jistě že nižádný z lidí těchto pokolení zlého neuzří země té dobré, kterouž jsem s přísahou zaslíbil dáti otcům vašim,'),
(1551119,54,5,1,36,'Kromě Kálefa, syna Jefonova; tenť ji uzří, a jemu dám zemi, po níž chodil, i synům jeho, proto že cele následoval Hospodina.'),
(1551120,54,5,1,37,'Ano i na mne rozhněval se Hospodin příčinou vaší, řka: Také ani ty nevejdeš tam.'),
(1551121,54,5,1,38,'Jozue, syn Nun, kterýž stojí před tebou, onť vejde tam, jeho posilň, nebo on rozdělí ji losem Izraelovi.'),
(1551122,54,5,1,39,'A dítky vaše, o kterýchž jste pravili, že v loupež budou, a synové vaši, kteříž ještě neznají dobrého ani zlého, oni vejdou do ní, a jim dám ji; oni dědičně ji obdrží.'),
(1551123,54,5,1,40,'Vy pak obrátíce se, jděte na poušť cestou k moři Rudému.'),
(1551124,54,5,1,41,'A odpověděvše, řekli jste ke mně: Zhřešiliť jsme Hospodinu. My vstoupíme a budeme bojovati podlé toho všeho, jakž rozkázal nám Hospodin Bůh náš. A vzavše všickni odění svá válečná na sebe, hotovi jste byli vstoupiti na horu.'),
(1551125,54,5,1,42,'Hospodin pak řekl mi: Rci jim: Nevstupujte a nebojujte, neboť nejsem u prostřed vás, abyste nebyli poraženi před nepřátely svými.'),
(1551126,54,5,1,43,'A když jsem vám to mluvil, neuposlechli jste, nýbrž odporni jste byli řeči Hospodinově, a všetečně vstoupili jste na horu.'),
(1551127,54,5,1,44,'Tedy vytáhl Amorejský, kterýž bydlil na té hoře, proti vám, a honili vás, jako činívají včely, a potřeli vás na hoře Seir až do Horma.'),
(1551128,54,5,1,45,'A navrátivše se, plakali jste před Hospodinem, ale neuslyšel Hospodin hlasu vašeho, a uší svých nenaklonil k vám.'),
(1551129,54,5,1,46,'I zůstali jste v Kádes za mnohé dny, podlé počtu dnů, v nichž jste tam byli.'),
(1551130,54,5,2,1,'Potom obrátivše se, táhli jsme na tu poušť cestou k moři Rudému, jakož mluvil Hospodin ke mně, a obcházeli jsme horu Seir za dlouhý čas,'),
(1551131,54,5,2,2,'Až mi řekl Hospodin takto:'),
(1551132,54,5,2,3,'Dosti jste již obcházeli horu tuto, obraťtež se k straně půlnoční.'),
(1551133,54,5,2,4,'A lidu přikaž, řka: Půjdete přes pomezí bratří svých synů Ezau, kteříž bydlí v Seir. Ačkoli budou se vás báti, hleďte však pilně,'),
(1551134,54,5,2,5,'Abyste jich nedráždili; nebo nedám vám z země jejich ani šlepěje nožné, proto že v dědictví Ezau dal jsem horu Seir.'),
(1551135,54,5,2,6,'Pokrmů koupíte od nich za peníze, a jísti budete, i vody také ku pití za peníze od nich jednati budete.'),
(1551136,54,5,2,7,'Nebo Hospodin Bůh tvůj požehnal tobě při všeliké práci rukou tvých, a zná, že jdeš přes poušť velikou tuto; již čtyřidceti let Hospodin Bůh tvůj byl s tebou, aniž jsi měl v čem nedostatku.'),
(1551137,54,5,2,8,'A šli jsme od bratří našich, synů Ezau, kteříž bydlí v Seir, s cesty polní od Elat a od Aziongaber, a uchýlili jsme se, abychom šli cestou po poušti Moábské.'),
(1551138,54,5,2,9,'I řekl mi Hospodin: Neškoď Moábským, ani jich popouzej k boji, nebo nedám tobě v zemi jejich dědictví, poněvadž synům Lot dal jsem Ar v dědictví.'),
(1551139,54,5,2,10,'(Emim prvé bydlili v ní, lid veliký a mnohý, a vysokého zrostu, jako Enakim.'),
(1551140,54,5,2,11,'Oni také za obry držáni byli jako Enakim, ale Moábští říkali jim Emim.'),
(1551141,54,5,2,12,'V Seir pak bydlili prvé Horejští, kteréž synové Ezau vyhnali, a zahladili je před tváří svou, a bydlili tu místo nich, jako učinil Izrael v zemi vládařství svého, kterouž jim dal Hospodin.)');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551142,54,5,2,13,'Nyní vstanouce, přejděte potok Záred. I přešli jsme potok Záred.'),
(1551143,54,5,2,14,'Času pak, v němž jsme šli z Kádesbarne, až jsme přešli potok Záred, bylo let třidceti osm, dokavadž nebyl vyhlazen všecken věk mužů bojovných z prostřed stanů, jakož jim přisáhl Hospodin.'),
(1551144,54,5,2,15,'Nebo ruka Hospodinova byla proti nim k setření jich z prostředku stanů, dokudž nevyhladil jich.'),
(1551145,54,5,2,16,'I stalo se, když všickni muži ti bojovní vyhynuli z prostředku lidu,'),
(1551146,54,5,2,17,'Že mluvil Hospodin ke mně, řka:'),
(1551147,54,5,2,18,'Ty přejdeš dnes pomezí Moábské k městu Ar,'),
(1551148,54,5,2,19,'A přiblížíš se k synům Ammon. Nessužujž jich a nepopouzej jich k boji, nebo nedám tobě v zemi synů Ammon dědictví, poněvadž synům Lotovým dal jsem ji k vládařství.'),
(1551149,54,5,2,20,'(I ona také držána byla za zemi obrů; nebo obrové před tím bydlili v ní, kterýmž Ammoninští říkali Zamzomim,'),
(1551150,54,5,2,21,'Lid veliký a mnohý, a vysokého zrostu, jako Enakim. Ale zahladil je Hospodin před tváří jejich, a vešli v dědictví jejich, a bydlili na místě jejich,'),
(1551151,54,5,2,22,'Jakož učinil synům Ezau bydlícím v Seir, pro něž vyhladil Horejské před tváří jejich, i vešli v dědictví jejich, a bydlili na místě jejich až do dnešního dne.'),
(1551152,54,5,2,23,'Hevejské také, kteříž bydlili v Azerim až do Gáza, Kaftorejští, kteříž vyšli z Kaftor, zahladili je, a bydlili na místě jejich.)'),
(1551153,54,5,2,24,'Vstanouce, beřte se a přejděte potok Arnon. Hle, dal jsem v ruce tvé Seona, krále Ezebon Amorejského, a zemi jeho; začniž jí vládnouti, a bojuj válečně proti němu.'),
(1551154,54,5,2,25,'Dnes počnu pouštěti strach a lekání se tebe na lidi, kteříž jsou pode vším nebem, tak že kteřížkoli uslyší pověst o tobě, třásti a lekati se budou tváři tvé.'),
(1551155,54,5,2,26,'I poslal jsem posly z pouště Kedemot k Seonovi, králi Ezebon, s slovy pokojnými, řka:'),
(1551156,54,5,2,27,'Nechť projdu skrze zemi tvou, přímo cestou půjdu, neuchýlím se ani na pravo ani na levo.'),
(1551157,54,5,2,28,'Pokrmů za peníze prodáš mi, abych jedl, vody také za peníze dáš mi, a píti budu; toliko pěšky projdu,'),
(1551158,54,5,2,29,'Jakož mi učinili synové Ezau, kteříž bydlí v Seir, a Moábští, kteříž bydlí v Ar, dokudž nepřejdu Jordánu, jda k zemi, kterouž Hospodin Bůh náš dává nám.'),
(1551159,54,5,2,30,'Ale nechtěl dopustiti Seon, král Ezebon, abychom prošli zemi jeho; nebo byl zatvrdil Hospodin Bůh tvůj ducha jeho, a ztužil srdce jeho, aby dal jej v ruce tvé, jakož se vidí podnes.'),
(1551160,54,5,2,31,'(Nebo řekl mi byl Hospodin: Aj, již jsem počal v moc dávati tobě Seona i zemi jeho; začniž jí vládnouti, abys dědičně obdržel zemi jeho.)'),
(1551161,54,5,2,32,'A vytáhl byl Seon proti nám, on i všecken lid jeho k boji do Jasa.'),
(1551162,54,5,2,33,'I dal jej nám Hospodin Bůh náš, a porazili jsme ho s syny jeho i se vším lidem jeho.'),
(1551163,54,5,2,34,'Vzali jsme také toho času všecka města jeho, a dali jsme v prokletí lid těch všech měst, i ženy i děti, žádného nepozůstavivše.'),
(1551164,54,5,2,35,'Toliko hovada rozebrali jsme sobě, a kořisti z měst, kterýchž jsme dobyli.'),
(1551165,54,5,2,36,'Od Aroer jenž jest na břehu potoka Arnon, a od města, kteréž jest v údolí, až do Galád nebylo města, kteréž by ostáti mohlo před námi; všecka nám dal Hospodin Bůh náš.'),
(1551166,54,5,2,37,'Toliko k zemi synů Ammon nepřiblížils se, ani k žádné krajině ležící při potoku Jabok, ani k městům na horách, a k žádnému místu, kteréž zapověděl Hospodin Bůh náš.'),
(1551167,54,5,3,1,'Potom obrátivše se, táhli jsme cestou k Bázan. I vytáhl Og, král Bázan, proti nám, on i všecken lid jeho k bitvě do Edrei.'),
(1551168,54,5,3,2,'I řekl mi Hospodin: Neboj se ho, nebo v ruce tvé dal jsem jej, i všecken lid jeho i zemi jeho, a učiníš jemu tak, jako jsi učinil Seonovi, králi Amorejskému, kterýž bydlil v Ezebon.'),
(1551169,54,5,3,3,'Dal tedy Hospodin Bůh náš v ruce naše i Oga, krále Bázan, a všecken lid jeho, i porazili jsme jej, tak že jsme nepozůstavili po něm žádného živého.'),
(1551170,54,5,3,4,'Dobyli jsme také téhož času všech měst jeho; nebylo města, kteréhož bychom jim neodjali, šedesáte měst, všecku krajinu Argob, království Oga v Bázan.'),
(1551171,54,5,3,5,'Všecka ta města byla ohražená zdmi vysokými, branami a závorami, kromě měst otevřených, jichž bylo velmi mnoho.'),
(1551172,54,5,3,6,'A vyplénili jsme je, jako jsme učinili Seonovi, králi Ezebon, vyhladivše všecka města, muže, ženy i dítky.'),
(1551173,54,5,3,7,'Všecka pak hovada a kořisti měst rozebrali jsme sobě.'),
(1551174,54,5,3,8,'Vzali jsme také téhož času zemi z ruky dvou králů Amorejských, kteráž byla před Jordánem, od potoku Arnon až k hoře Hermon,'),
(1551175,54,5,3,9,'(Sidonští říkají Hermonu Sarion, a Amorejští říkají jemu Sanir),'),
(1551176,54,5,3,10,'Všecka města v kraji, a všecken Galád, a všecken Bázan až do Sálecha a Edrei, kteráž byla města království Og v Bázan.'),
(1551177,54,5,3,11,'Sám toliko Og, král v Bázan, z jiných obrů byl pozůstal. Aj, lůže jeho, lůže železné, ještě zůstává v Rabbat synů Ammon, devíti loktů zdýlí, a čtyř loket zšíří, jakž jest loket muže.'),
(1551178,54,5,3,12,'Když tedy zemi tu obdrželi jsme dědičně toho času, krajinu od Aroer, jenž jest při potoku Arnon, a polovici hory Galád i města její, dal jsem pokolení Ruben a Gád.'),
(1551179,54,5,3,13,'Ostatek pak Galád a všecku zemi Bázan, království Oga, dal jsem polovici pokolení Manassesova, totiž všecku krajinu Argob, všecku Bázan, kteráž sloula země obrů.'),
(1551180,54,5,3,14,'Jair, syn Manasse, vzal všecku krajinu Argob, až ku pomezí Gessuri a Machati; pročež nazval zemi Bázan od jména svého Havot Jair až do dnešního dne.'),
(1551181,54,5,3,15,'Machirovi pak dal jsem Galád.'),
(1551182,54,5,3,16,'A Rubenovu a Gádovu pokolení dal jsem krajinu od Galád až ku potoku Arnon, polovici potoka s pomezím až ku potoku Jabok, kdež jsou hranice synů Ammonitských,'),
(1551183,54,5,3,17,'A roviny tyto i Jordán s pomezím od Ceneret až k moři pustému, jenž jest moře slané, ležící pod horou Fazga k východu.'),
(1551184,54,5,3,18,'A přikázal jsem vám toho času, řka: Hospodin Bůh váš dal vám zemi tuto, abyste ji dědičně obdrželi; vezmouce odění na sebe, půjdete před bratřími vašimi, syny Izraelskými, kteřížkoli silní jste.'),
(1551185,54,5,3,19,'Toliko ženy vaše a dítky vaše, a dobytek váš, (nebo vím, že mnoho dobytka máte,) zůstanou v městech vašich, kteráž jsem dal vám,'),
(1551186,54,5,3,20,'Dokudž by nedal odpočinutí Hospodin bratřím vašim jako i vám, aby i oni dědičně obdrželi zemi, kterouž Hospodin Bůh váš dává jim za Jordánem; tedy navrátíte se jeden každý k dědictví svému, kteréž jsem dal vám.'),
(1551187,54,5,3,21,'Také i Jozue přikázal jsem toho času, řka: Oči tvé vidí všecko, co učinil Hospodin Bůh váš těm dvěma králům; takť učiní Hospodin všechněm královstvím, do kterýchž ty půjdeš.'),
(1551188,54,5,3,22,'Nebojtež se jich, nebo Hospodin Bůh váš, onť jest, kterýž bojuje za vás.'),
(1551189,54,5,3,23,'A tehdáž prosil jsem Hospodina, řka:'),
(1551190,54,5,3,24,'Panovníče Hospodine, ty jsi počal ukazovati služebníku svému velikost svou a ruku svou přesilnou; nebo kdo jest Bůh silný na nebi aneb na zemi, ješto by činiti mohl skutky podobné tvým, a moci podobné tobě?'),
(1551191,54,5,3,25,'Prosím, nechť vejdu a uzřím zemi tu výbornou, kteráž jest za Jordánem, horu tu výbornou i Libán.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551192,54,5,3,26,'Pohnul se pak Hospodin na mne pro vás a neuslyšel mne, ale řekl mi: Dosti máš, nemluv více o to se mnou.'),
(1551193,54,5,3,27,'Vstup na vrch hory Fazga, a pozdvihna očí svých k západu a k půlnoci, ku poledni i k východu, hleď očima svýma; nebo nepřejdeš Jordánu tohoto.'),
(1551194,54,5,3,28,'Ale přikaž Jozue, a posilň ho, i potvrď ho; nebo půjde před lidem tímto, a on uvede jim v dědictví zemi, kterouž uzříš.'),
(1551195,54,5,3,29,'I zůstali jsme v údolí naproti Betfegor.'),
(1551196,54,5,4,1,'Nyní tedy, ó Izraeli, slyš ustanovení a soudy, kteréž já učím vás činiti, abyste živi byli, a vejdouce, dědičně vládli zemí, kterouž Hospodin Bůh otců vašich vám dává.'),
(1551197,54,5,4,2,'Nepřidáte nic k slovu, kteréž já přikazuji vám, aniž co ujmete od něho, abyste tak přikázaní Hospodina Boha svého, kteréž já přikazuji vám, zachovali.'),
(1551198,54,5,4,3,'Oči vaše viděly, co učinil Hospodin pro Belfegor, jak všecky lidi, kteříž odešli po Belfegor, vyhladil Hospodin Bůh tvůj z prostředku tvého.'),
(1551199,54,5,4,4,'Vy pak, přídržející se Hospodina Boha vašeho, živi jste do dnešního dne všickni.'),
(1551200,54,5,4,5,'Viztež, učilť jsem vás ustanovením a soudům, jakž mi přikázal Hospodin Bůh můj, abyste tak činili v zemi, do kteréž vejdete k dědičnému držení jí.'),
(1551201,54,5,4,6,'Ostříhejtež tedy a čiňte je, nebo to jest moudrost vaše a opatrnost vaše před očima národů, kteříž, slyšíce všecka ustanovení tato, řeknou: Jistě lid moudrý a rozumný národ veliký tento jest.'),
(1551202,54,5,4,7,'Nebo který národ tak veliký jest, kterýž by měl bohy sobě tak blízké, jako jest Hospodin Bůh váš ve všem volání našem k němu?'),
(1551203,54,5,4,8,'A který jest národ tak veliký, kterýž by měl ustanovení a soudy spravedlivé, jako jest všecken zákon tento, kterýž já vám dnes předkládám?'),
(1551204,54,5,4,9,'A však hleď se a bedlivě ostříhej duše své, abys nezapomenul na ty věci, kteréž viděly oči tvé, a aby nevyšly z srdce tvého po všecky dny života tvého; a v známost je uvedeš synům i vnukům svým.'),
(1551205,54,5,4,10,'A nezapomínej, že jsi onoho dne stál před Hospodinem Bohem svým na Orébě, když mi byl řekl Hospodin: Shromažď mi lid, ať jim předložím slova má, z nichž by se učili mne báti po všecky dny, dokudž živi budou na zemi, a témuž aby syny své učili.'),
(1551206,54,5,4,11,'Tedy přistoupili jste, a stáli jste pod horou; (hora pak ta hořela ohněm až do samého nebe, a byly na ní tmy, oblak a mrákota.)'),
(1551207,54,5,4,12,'I mluvil k vám Hospodin z prostředku ohně. Hlas slov slyšeli jste, ale obrazu žádného jste neviděli kromě hlasu,'),
(1551208,54,5,4,13,'Jímž vyhlásil vám smlouvu svou, kteréžto přikázal vám ostříhati, totiž desíti slov, a napsal je na dvou dskách kamenných.'),
(1551209,54,5,4,14,'Mně také přikázal Hospodin toho času, abych učil vás ustanovením a soudům, abyste činili je v zemi, do kteréž jdete k dědičnému držení jí.'),
(1551210,54,5,4,15,'Protož pilně pečujte o duše své, (nebo neviděli jste žádného obrazu toho dne, když k vám mluvil Hospodin na Orébě z prostředku ohně),'),
(1551211,54,5,4,16,'Abyste neporušili cesty své, a neučinili sobě rytiny aneb podobenství nějakého obrazu, tvárnosti muže neb ženy,'),
(1551212,54,5,4,17,'Podobenství nějakého hovada, kteréž jest na zemi, aneb podobenství jakéhokoli ptáka křídla majícího, kterýž létá v povětří,'),
(1551213,54,5,4,18,'Podobenství jakéhokoli zeměplazu na zemi, aneb podobenství jakékoli ryby, kteráž jest u vodě pod zemí.'),
(1551214,54,5,4,19,'Ani pozdvihuj očí svých k nebi, abys, vida slunce a měsíc, i hvězdy se vším zástupem nebeským a ponuknut jsa, klaněl bys se jim a sloužil bys jim, ješto ty věci oddal Hospodin Bůh tvůj všechněm lidem pode vším nebem,'),
(1551215,54,5,4,20,'Vás pak vzal Hospodin, a vyvedl vás jako z peci železné z Egypta, abyste byli jeho lid dědičný, jako jste dne tohoto.'),
(1551216,54,5,4,21,'Ale na mne rozhněval se Hospodin příčinou vaší, a přisáhl, že nepřejdu Jordánu, ani nevejdu do země té výborné, kterouž Hospodin Bůh tvůj dává tobě v dědictví.'),
(1551217,54,5,4,22,'Nebo já umru v zemi této, a nepřejdu Jordánu, vy pak přejdete, a dědičně obdržíte zemi tu výbornou.'),
(1551218,54,5,4,23,'Hleďtež, abyste se nezapomínali na smlouvu Hospodina Boha svého, kterouž učinil s vámi, a nečinili sobě rytiny, aneb obrazu jakékoli věci, jakož přikázal tobě Hospodin Bůh tvůj.'),
(1551219,54,5,4,24,'Nebo Hospodin Bůh tvůj jest oheň sžírající, Bůh silný, horlivý.'),
(1551220,54,5,4,25,'Když zplodíš syny a vnuky, a zstaráte se v zemi té, jestliže porušíte cestu svou, a uděláte rytinu ku podobenství jakékoli věci, aneb učiníte něco zlého před očima Hospodina Boha svého, popouzejíce ho:'),
(1551221,54,5,4,26,'Osvědčuji proti vám dnes před nebem i zemí, že hrozně a rychle vyhlazeni budete z země, do kteréž půjdete přes Jordán, abyste vládli jí. Nedlouho bydliti budete v ní, ale do konce vyhlazeni budete.'),
(1551222,54,5,4,27,'A rozptýlí vás Hospodin mezi národy, a maličký počet vás zůstane mezi pohany, do kterýchž zavede vás Hospodin,'),
(1551223,54,5,4,28,'A sloužiti tam budete bohům, dílu rukou lidských, dřevu a kameni, ješto nevidí ani slyší, ani jedí, ani čijí.'),
(1551224,54,5,4,29,'Jestliže pak i tam hledati budeš Hospodina Boha svého, tedy nalezneš, budeš-li ho hledati z celého srdce svého a z celé duše své.'),
(1551225,54,5,4,30,'Kdyžť úzko bude, a přijdou na tě všecky ty věci, naposledy však, jestliže bys se navrátil k Hospodinu Bohu svému, a poslouchal bys hlasu jeho,'),
(1551226,54,5,4,31,'(Poněvadž Hospodin Bůh tvůj jest Bůh silný, milosrdný,) neopustí tebe, ani tě nezkazí, ani zapomene se na smlouvu otců tvých, kterouž s přísahou utvrdil jim.'),
(1551227,54,5,4,32,'Nebo ptej se nyní na dni staré, kteříž byli před tebou, od toho dne, v kterémž stvořil Bůh člověka na zemi, a od jednoho kraje nebe až do druhého, stala-li se kdy věc podobná této tak veliké, aneb slýcháno-li kdy co takového?'),
(1551228,54,5,4,33,'Zdali kdy slyšel který lid hlas Boha mluvícího z prostředku ohně, jako jsi ty slyšel a živ zůstal?'),
(1551229,54,5,4,34,'Aneb zdali se kdy který Bůh pokusil, aby přijda, vzal sobě národ některý z jiného národu s zkušováním, znameními a s zázraky, skrze boje a ruku silnou, v rameni vztaženém a v hrůzi veliké, jako učinil všecko toto pro vás Hospodin Bůh váš v Egyptě před očima vašima?'),
(1551230,54,5,4,35,'Toběť jest to ukázáno, abys věděl, že Hospodin jest Bůh, a že není jiného kromě něho.'),
(1551231,54,5,4,36,'Dalť s nebe slyšeti hlas svůj, aby vyučil tebe, a na zemi ukázal tobě oheň svůj veliký, a slova jeho slyšel jsi z prostředku ohně.'),
(1551232,54,5,4,37,'Proto že miloval otce tvé, vyvolil símě jejich po nich, a vyvedl tě před sebou mocí svou velikou z Egypta,'),
(1551233,54,5,4,38,'Aby vyžena národy veliké a silnější, než jsi ty, před tváří tvou, uvedl tebe a dal tobě zemi jejich v dědictví, jakož dnes vidíš.'),
(1551234,54,5,4,39,'Věziž tedy dnes a obnov to v srdci svém, že Hospodin jest Bůh na nebi svrchu i na zemi dole, a není žádného jiného.'),
(1551235,54,5,4,40,'Protož ostříhej po všecky dny ustanovení a přikázaní jeho, kteráž já dnes přikazuji tobě, aby dobře bylo tobě i synům tvým po tobě, a abys prodlil dnů v zemi, kterouž Hospodin Bůh tvůj dá tobě.'),
(1551236,54,5,4,41,'Tehdy oddělil Mojžíš tři města před Jordánem k východu slunce.'),
(1551237,54,5,4,42,'Aby utekl do nich vražedlník, kterýž by zabil bližního svého nechtě, a neměl by ho před tím v nenávisti; když by utekl do jednoho z těch měst, aby živ zůstal:'),
(1551238,54,5,4,43,'Bozor na poušti, na rovinách v kraji Rubenitských, a Rámot v Galád, v pokolení Gád, a Golan v Bázan, v pokolení Manasse.'),
(1551239,54,5,4,44,'Ten jest zákon, kterýž předložil Mojžíš synům Izraelským,'),
(1551240,54,5,4,45,'A tato jsou svědectví a ustanovení i soudové, kteréž předložil Mojžíš synům Izraelským, když vyšli z Egypta,'),
(1551241,54,5,4,46,'Před Jordánem v údolí naproti Betfegor, v zemi Seona, krále Amorejského, kterýž bydlil v Ezebon, jejž porazil Mojžíš a synové Izraelští, když vyšli z Egypta,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551242,54,5,4,47,'A uvázali se dědičně v zemi jeho, a v zemi Oga, krále Bázan, dvou králů Amorejských, v zemi, kteráž jest před Jordánem k východu slunce,'),
(1551243,54,5,4,48,'Od Aroer, (jenž leží při břehu potoka Arnon), až k hoře Sion, kteráž jest Hermon.'),
(1551244,54,5,4,49,'I ve všecku rovinu před Jordánem k východu až k moři pustému, ležící pod horou Fazga.'),
(1551245,54,5,5,1,'I svolal Mojžíš všecken lid Izraelský, a řekl jim: Slyš, Izraeli, ustanovení a soudy, kteréž já dnes mluvím v uši vaše; naučte se jim, a v skutku jich ostříhejte.'),
(1551246,54,5,5,2,'Hospodin Bůh náš učinil s námi smlouvu na Orébě.'),
(1551247,54,5,5,3,'Ne s otci našimi učinil Hospodin tu smlouvu, ale s námi, kteříž zde jsme nyní my všickni živí.'),
(1551248,54,5,5,4,'Tváří v tvář mluvil Hospodin s vámi na té hoře z prostředku ohně,'),
(1551249,54,5,5,5,'(Já jsem pak stál mezi Hospodinem a mezi vámi toho času, abych oznámil vám řeč Hospodinovu; nebo jste se báli ohně, a nevstoupili jste na horu), řka:'),
(1551250,54,5,5,6,'Já jsem Hospodin Bůh tvůj, kterýž jsem tě vyvedl z země Egyptské z domu služby.'),
(1551251,54,5,5,7,'Nebudeš míti bohů jiných přede mnou.'),
(1551252,54,5,5,8,'Neučiníš sobě rytiny , ani jakého podobenství těch věcí, kteréž jsou na nebi svrchu, ani těch, kteréž na zemi dole, ani těch, kteréž jsou u vodách pod zemí.'),
(1551253,54,5,5,9,'Nebudeš se jim klaněti, ani jich ctíti. Nebo já jsem Hospodin Bůh tvůj, Bůh silný, horlivý, navštěvující nepravost otců na synech do třetího i čtvrtého pokolení těch, kteříž nenávidí mne,'),
(1551254,54,5,5,10,'A činící milosrdenství nad tisíci těch, kteříž mne milují, a ostříhají přikázaní mých.'),
(1551255,54,5,5,11,'Nevezmeš jména Hospodina Boha svého nadarmo, neboť nenechá bez pomsty Hospodin toho, kdož by bral jméno jeho nadarmo.'),
(1551256,54,5,5,12,'Ostříhej dne sobotního, abys jej světil, jakož přikázal tobě Hospodin Bůh tvůj.'),
(1551257,54,5,5,13,'Šest dní pracovati budeš, a dělati všeliké dílo své;'),
(1551258,54,5,5,14,'Ale dne sedmého odpočinutí jest Hospodina Boha tvého. Nebudeš dělati žádného díla, ty i syn tvůj i dcera tvá, i služebník tvůj i děvka tvá, vůl i osel tvůj i všeliké hovado tvé, i příchozí tvůj, kterýž jest v branách tvých, aby odpočinul služebník tvůj a děvka tvá jako i ty.'),
(1551259,54,5,5,15,'A pamatuj, že jsi byl služebníkem v zemi Egyptské, a vyvedl tě Hospodin Bůh tvůj odtud v ruce silné, a v rameni vztaženém. Protož přikázal tobě Hospodin Bůh tvůj, abys světil den sváteční.'),
(1551260,54,5,5,16,'Cti otce svého i matku svou, jakož přikázal tobě Hospodin Bůh tvůj, aby se prodleli dnové tvoji, a aby tobě dobře bylo na zemi, kterouž Hospodin Bůh tvůj dá tobě.'),
(1551261,54,5,5,17,'Nezabiješ.'),
(1551262,54,5,5,18,'Nesesmilníš.'),
(1551263,54,5,5,19,'Nepokradeš.'),
(1551264,54,5,5,20,'Nepromluvíš proti bližnímu svému křivého svědectví.'),
(1551265,54,5,5,21,'Nepožádáš manželky bližního svého, aniž požádáš domu bližního svého, pole jeho, neb služebníka jeho, aneb děvky jeho, vola jeho neb osla jeho, aneb čehokoli z těch věcí, kteréž jsou bližního tvého.'),
(1551266,54,5,5,22,'Ta slova mluvil Hospodin ke všemu shromáždění vašemu na hoře z prostředku ohně, oblaku a mrákoty, hlasem velikým, a nepřidal nic více, a napsal je na dvou dskách kamenných, kteréž mně dal.'),
(1551267,54,5,5,23,'Vy pak když jste uslyšeli hlas z prostředku tmy, (nebo hora ohněm hořela), přistoupili jste ke mně všickni vůdcové pokolení vašich a starší vaši,'),
(1551268,54,5,5,24,'A řekli jste: Ej, ukázal nám Hospodin Bůh náš slávu svou a velikost svou, a slyšeli jsme hlas jeho z prostředku ohně; dnešního dne viděli jsme, že Bůh mluvil s člověkem, a on živ zůstal.'),
(1551269,54,5,5,25,'Protož nyní proč máme zemříti? Nebo sežral by nás oheň veliký tento; jestli více slyšeti budeme hlas Hospodina Boha našeho, zemřeme.'),
(1551270,54,5,5,26,'Nebo co jest všeliké tělo, aby slyše hlas Boha živého mluvícího z prostředku ohně, jako my, mělo živo býti?'),
(1551271,54,5,5,27,'Přistup ty a slyš všecky věci, kteréž mluviti bude Hospodin Bůh náš; potom ty mluviti budeš nám, což by koli řekl tobě Hospodin Bůh náš, a my slyšeti i činiti budeme.'),
(1551272,54,5,5,28,'Uslyšev pak Hospodin hlas řečí vašich, když jste mluvili ke mně, řekl mi Hospodin: Slyšel jsem hlas řeči lidu tohoto, kterouž mluvili tobě. Cožkoli mluvili, dobřeť jsou mluvili.'),
(1551273,54,5,5,29,'Ó kdyby bylo jejich srdce takové, aby se báli mne a ostříhali přikázaní mých po všeliký čas, aby jim dobře bylo i synům jejich na věky!'),
(1551274,54,5,5,30,'Jdi, rci jim: Navraťte se k stanům vašim.'),
(1551275,54,5,5,31,'Ty pak stůj tuto při mně, a oznámím tobě všecka přikázaní, ustanovení i soudy, kterýmž je učiti budeš, aby je činili v zemi, kterouž já dávám jim, aby jí dědičně vládli.'),
(1551276,54,5,5,32,'Hleďtež tedy, abyste činili, jakž přikázal vám Hospodin Bůh váš; neuchylujte se na pravo ani na levo.'),
(1551277,54,5,5,33,'Po vší té cestě, kterouž vám přikázal Hospodin Bůh váš, choditi budete, abyste živi byli, a dobře bylo vám, a abyste prodlili dnů na zemi, kterouž dědičně obdržíte.'),
(1551278,54,5,6,1,'Toto pak jest přikázaní, ustanovení a soudové, kteréž přikázal Hospodin Bůh váš, abych učil vás, abyste činili je v zemi, do kteréž jdete k dědičnému držení jí,'),
(1551279,54,5,6,2,'Abys se bál Hospodina Boha svého, ostříhaje všech ustanovení jeho a přikázaní jeho, kteráž já přikazuji tobě, ty i syn tvůj i vnuk tvůj, po všecky dny života svého, aby se prodlili dnové tvoji.'),
(1551280,54,5,6,3,'Slyšiž tedy, Izraeli, a hleď tak skutečně činiti, aby tobě dobře bylo, a abyste se velmi rozmnožili, (jakož mluvil Hospodin Bůh otců tvých tobě,) v zemi oplývající mlékem a strdí.'),
(1551281,54,5,6,4,'Slyš, Izraeli, Hospodin Bůh náš, Hospodin jeden jest.'),
(1551282,54,5,6,5,'Protož milovati budeš Hospodina Boha svého z celého srdce svého, a ze vší duše své, a ze vší síly své.'),
(1551283,54,5,6,6,'A budou slova tato, kteráž já přikazuji tobě dnes, v srdci tvém.'),
(1551284,54,5,6,7,'A budeš je často opětovati synům svým, a mluviti o nich, když sedneš v domě svém, když půjdeš cestou, a léhaje i vstávaje.'),
(1551285,54,5,6,8,'Uvážeš je za znamení na ruce své, a jako náčelník mezi očima svýma.'),
(1551286,54,5,6,9,'Napíšeš je také na veřejích domu svého a na branách svých.'),
(1551287,54,5,6,10,'A když tě uvede Hospodin Bůh tvůj do země, kterouž s přísahou zaslíbil otcům tvým, Abrahamovi, Izákovi a Jákobovi, že ji tobě dá, i města veliká a výborná, kterýchžs nestavěl,'),
(1551288,54,5,6,11,'A domy plné všech dobrých věcí, kterýchž jsi nenaplnil, a studnice vykopané, kterýchž jsi nekopal, a vinice i olivoví, jichž jsi neštípil, a jedl bys a nasytil se:'),
(1551289,54,5,6,12,'Varuj se, abys nezapomenul na Hospodina, kterýž tě vyvedl z země Egyptské, z poroby těžké.'),
(1551290,54,5,6,13,'Hospodina Boha svého báti se budeš, a jemu sloužiti, a ve jméno jeho přisahati.'),
(1551291,54,5,6,14,'Neodejdeš po bozích cizích, z bohů jiných národů, kteříž vůkol vás jsou,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551292,54,5,6,15,'(Nebo Bůh silný, horlivý, Hospodin tvůj u prostřed tebe jest,) aby se neroznítila prchlivost Hospodina Boha tvého na tebe, a shladil by tě se svrchku země.'),
(1551293,54,5,6,16,'Nebudete pokoušeti Hospodina Boha svého, jako jste pokoušeli v Massah.'),
(1551294,54,5,6,17,'Pilně ostříhejte přikázaní Hospodina Boha svého, a svědectví jeho, i ustanovení jeho, kteráž přikázal tobě,'),
(1551295,54,5,6,18,'A čiň to, což pravého a dobrého jest před očima Hospodinovýma, aby tobě dobře bylo, a vejda, abys dědičně obdržel zemi výbornou, kterouž s přísahou zaslíbil Hospodin otcům tvým,'),
(1551296,54,5,6,19,'Aby vypudil všecky nepřátely tvé od tváři tvé, jakož mluvil Hospodin.'),
(1551297,54,5,6,20,'Když by se potom syn tvůj otázal tebe, řka: Co jsou to za svědectví a ustanovení i soudy, kteréž přikázal Hospodin Bůh náš vám?'),
(1551298,54,5,6,21,'Tedy díš synu svému: Služebníci jsme byli Faraonovi v Egyptě, i vyvedl nás Hospodin z Egypta v ruce silné.'),
(1551299,54,5,6,22,'A činil Hospodin znamení a zázraky veliké a škodlivé v Egyptě proti Faraonovi, a proti všemu domu jeho před očima našima,'),
(1551300,54,5,6,23,'Nás pak vyvedl odtud, aby uvedl nás, a dal nám zemi, kterouž s přísahou zaslíbil otcům našim.'),
(1551301,54,5,6,24,'Protož přikázal nám Hospodin, abychom ostříhali všech ustanovení těchto, bojíce se Hospodina Boha svého, aby nám dobře bylo po všecky dny, a aby zachoval nás při životu, jakž to činí i v dnešní den.'),
(1551302,54,5,6,25,'A spravedlnost míti budeme, když ostříhati budeme a činiti všecka přikázaní tato před Hospodinem Bohem svým, jakož přikázal nám.'),
(1551303,54,5,7,1,'Když pak tebe uvede Hospodin Bůh tvůj do země, do kteréž ty již vcházíš, abys vládl jí, a vypléní národy mnohé od tváři tvé, Hetea, Gergezea, Amorea, Kananea, Ferezea, Hevea a Jebuzea, sedm národů větších a silnějších, nežli jsi ty,'),
(1551304,54,5,7,2,'A dá je Hospodin Bůh tvůj tobě, abys je pobil: jako proklaté vypléníš je, nevejdeš s nimi v smlouvu, aniž slituješ se nad nimi.'),
(1551305,54,5,7,3,'Nikoli nespřízníš se s nimi; dcery své nedáš synu jejich, a dcery jejich nevezmeš synu svému.'),
(1551306,54,5,7,4,'Neboť by odvedla syna tvého od následování mne, a sloužili by bohům cizím, pročež popudila by se prchlivost Hospodinova na vás, a zahladila by tě rychle.'),
(1551307,54,5,7,5,'Ale raději toto jim učiňte: Oltáře jejich zbořte, modly jejich stroskotejte, háje také posekejte, a rytiny jejich ohněm spalte.'),
(1551308,54,5,7,6,'Nebo ty lid svatý jsi Hospodinu Bohu svému; tebe vyvolil Hospodin Bůh tvůj, abys jemu byl lidem zvláštním, mimo všecky národy, kteříž jsou na zemi.'),
(1551309,54,5,7,7,'Ne proto, že by vás více bylo nad jiné národy, připojil se k vám Hospodin, a vyvolil vás, (nebo menší vás počet byl nežli jiných národů,)'),
(1551310,54,5,7,8,'Ale proto, že miloval vás Hospodin, a splniti chtěl přísahu, kterouž přisáhl otcům vašim, vyvedl vás v ruce silné, a vysvobodil vás z domu služby, z ruky Faraona, krále Egyptského.'),
(1551311,54,5,7,9,'I zvíš, že Hospodin Bůh tvůj jest Bůh, Bůh silný a pravdomluvný, ostříhající smlouvy a milosrdenství těm, kteříž ho milují a ostříhají přikázaní jeho, až do tisícího kolena,'),
(1551312,54,5,7,10,'Odplacující tomu, kterýž ho nenávidí, v tvář jeho, tak aby zahladil jej. Nebudeť prodlévati; kdož ho nenávidí, v tvář jeho odplatí jemu.'),
(1551313,54,5,7,11,'Protož ostříhej přikázaní a ustanovení i soudů, kteréž já tobě dnes přikazuji, abys je činil.'),
(1551314,54,5,7,12,'I budeť to, že když poslouchati budete soudů těchto a ostříhati i činiti je, také Hospodin Bůh tvůj ostříhati bude tobě smlouvy a milosrdenství, kteréž s přísahou zaslíbil otcům tvým.'),
(1551315,54,5,7,13,'A bude tě milovati, i požehná tobě a rozmnoží tebe. Nebo požehná plodu života tvého a úrodám země tvé, obilí tvému, vínu tvému a oleji tvému, plodu skotů tvých i stádům bravů tvých v zemi, kterouž s přísahou zaslíbil otcům tvým, že ji tobě dá.'),
(1551316,54,5,7,14,'Požehnaný budeš nad všecky národy; nebude u tebe neplodný aneb neplodná, ani mezi hovady tvými.'),
(1551317,54,5,7,15,'Vzdálí také od tebe Hospodin všeliký neduh, a všecky zlé nemoci Egyptské, kteréž znáš; nevzloží jich na tebe, ale vzloží je na všecky, kteříž tě nenávidí.'),
(1551318,54,5,7,16,'A shladíš všecky národy, kteréž Hospodin Bůh tvůj dá tobě. Neslituje se nad nimi oko tvé, aniž sloužiti budeš bohům jejich, nebo to bylo by tobě osídlem.'),
(1551319,54,5,7,17,'Řekl-li bys v srdci svém: Větší jsou národové tito nežli já, kterak budu moci vyhnati je?'),
(1551320,54,5,7,18,'Neboj se jich, ale pilně pamatuj na to, co učinil Hospodin Bůh tvůj Faraonovi a všechněm Egyptským,'),
(1551321,54,5,7,19,'Na pokušení veliká, kteráž viděly oči tvé, i znamení a zázraky, a ruku silnou a rámě vztažené, v kterémž vyvedl tě Hospodin Bůh tvůj. Takť učiní Hospodin Bůh tvůj všechněm národům, kterýchž bys se obával.'),
(1551322,54,5,7,20,'Nadto sršně pošle Hospodin Bůh tvůj na ně, dokudž by nezhynuli, kteříž by pozůstali, a kteříž by se skryli před tebou.'),
(1551323,54,5,7,21,'Nelekejž se strachu jejich, nebo Hospodin Bůh tvůj jest u prostřed tebe, Bůh silný, veliký a hrozný.'),
(1551324,54,5,7,22,'I vypléní Hospodin Bůh tvůj národy ty od tváři tvé pomalu; nebudeš moci pojednou jich shladiti, aby se nerozmnožila proti tobě zvěř polní.'),
(1551325,54,5,7,23,'A však dá je Hospodin Bůh tvůj tobě, a setře je setřením velikým, dokudž nebudou vyhlazeni.'),
(1551326,54,5,7,24,'Vydá i krále jejich v ruce tvé, a vyhladíš jméno jejich pod nebem; neostojíť žádný před tebou, až je i vyhladíš.'),
(1551327,54,5,7,25,'Ryté bohy jejich ohněm popálíš; nepožádáš stříbra a zlata, kteréž jest na nich, aniž ho sobě vezmeš, aby nebylo tobě osídlem, nebo ohavnost jest Hospodinu Bohu tvému.'),
(1551328,54,5,7,26,'Aniž vneseš ohavnosti do domu svého, abys nebyl proklatý, jako i ona; všelijak v ohyzdnosti a v ohavnosti budeš míti ji, nebo proklatá jest.'),
(1551329,54,5,8,1,'Všelikého přikázaní, kteréž já přikazuji tobě dnes, skutečně ostříhejte, abyste živi byli a rozmnožili se, a vešli k dědičnému obdržení země, kterouž s přísahou zaslíbil Hospodin otcům vašim.'),
(1551330,54,5,8,2,'A rozpomínati se budeš na všecku cestu, kterouž tě vedl Hospodin Bůh tvůj již teď čtyřidceti let po poušti, aby ponížil tebe a zkusil tě, aby známé bylo, co jest v srdci tvém, budeš-li ostříhati přikázaní jeho, čili nic.'),
(1551331,54,5,8,3,'I ponížil tě a dopustil na tebe hlad, potom tě krmil mannou, kteréž jsi ty neznal, ani otcové tvoji, aby známé učinil tobě, že ne samým chlebem živ bude člověk, ale vším tím, což vychází z úst Hospodinových, živ bude člověk.'),
(1551332,54,5,8,4,'Roucho tvé nevetšelo na tobě, a noha tvá se neodhnetla, již od čtyřidceti let.'),
(1551333,54,5,8,5,'Znejž tedy v srdci svém, že jakož cvičí člověk syna svého, tak Hospodin Bůh tvůj cvičí tebe.'),
(1551334,54,5,8,6,'A ostříhej přikázaní Hospodina Boha svého, chodě po cestách jeho, a boje se jeho.'),
(1551335,54,5,8,7,'Nebo Hospodin Bůh tvůj uvozuje tě do země výborné, země, v níž jsou potokové vod, studnice a propasti prýštící se po údolích i po horách,'),
(1551336,54,5,8,8,'Do země hojné na pšenici a ječmen, na vinice a fíky a jablka zrnatá, do země, v níž jest hojnost olivoví olej přinášejícího a medu.'),
(1551337,54,5,8,9,'Země, v níž bez nedostatku chléb jísti budeš, a v ničemž nouze trpěti nebudeš, země, jejíž kamení jest železo, a z hor jejích měď sekati budeš.'),
(1551338,54,5,8,10,'Kdyžkoli jísti budeš a nasytíš se, dobrořečiti budeš Hospodina Boha svého za zemi výbornou, kterouž dal tobě.'),
(1551339,54,5,8,11,'Aniž se kdy toho dopouštěj, abys se měl zapomenouti na Hospodina Boha svého, a neostříhati přikázaní a soudů jeho i ustanovení jeho, kteráž já dnes přikazuji tobě,'),
(1551340,54,5,8,12,'Aby, když bys jedl a nasycen byl, a domů krásných nastavěje, v nich bys bydlil,'),
(1551341,54,5,8,13,'A volové i ovce tvé rozmnoženy byly by, stříbra také a zlata měl bys mnoho, a hojnost ve všech věcech svých,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551342,54,5,8,14,'Nepozdvihlo se srdce tvé, a zapomenul bys na Hospodina Boha svého, kterýž tě vyvedl z země Egyptské, z domu služby,'),
(1551343,54,5,8,15,'A vedl tě přes poušť velikou a hroznou, na níž byli hadové ohniví a štírové, poušť žíznivou, na níž nebylo žádné vody, a vyvedl tobě vodu z přetvrdé skály,'),
(1551344,54,5,8,16,'Kterýž tě krmil na poušti mannou, o kteréž nevěděli otcové tvoji, aby tě potrápil a zkusil tebe, naposledy však aby dobře učinil tobě.'),
(1551345,54,5,8,17,'Aniž říkej v srdci svém: Moc má a síla ruky mé způsobila mi tato zboží,'),
(1551346,54,5,8,18,'Ale pamatuj na Hospodina Boha svého, nebo on dává tobě moc k dobývání zboží, aby utvrdil smlouvu svou, kterouž s přísahou učinil s otci tvými, jakož to ukazuje dnešní den.'),
(1551347,54,5,8,19,'Pakli zapomena se na Hospodina Boha svého, postoupil bys po bozích cizích, a sloužil bys jim a klaněl bys se jim: osvědčuji proti vám dnes, že konečně zahynete.'),
(1551348,54,5,8,20,'Jako pohané, kteréž Hospodin zahladil před tváří vaší, tak zahynete, proto že jste neposlouchali hlasu Hospodina Boha svého.'),
(1551349,54,5,9,1,'Slyš, Izraeli, ty přejdeš dnes přes Jordán, abys vejda, dědičně vládl národy většími a silnějšími, než jsi ty, městy velikými a ohrazenými až k nebi,'),
(1551350,54,5,9,2,'Lidem velikým a vysokým, syny Enakovými, o kterýchž víš, a o kterýchž jsi slyšel praviti: Kdo se postaví proti synům Enakovým?'),
(1551351,54,5,9,3,'Protož věziž dnes, že Hospodin Bůh tvůj, kterýž jde před tebou, jest jako oheň spalující. On vyhladí je, a on sníží je před tebou; i vyženeš je a vyhladíš je rychle, jakož mluvil tobě Hospodin.'),
(1551352,54,5,9,4,'Neříkejž v srdci svém, když by je zapudil Hospodin Bůh tvůj od tváři tvé, řka: Pro spravedlnost mou uvedl mne Hospodin, abych dědičně obdržel zemi tuto, tak jako pro bezbožnost národů těch Hospodin vyhnal je od tváři tvé.'),
(1551353,54,5,9,5,'Ne pro spravedlnost svou a pravost srdce svého ty jdeš, abys dědičně obdržel zemi jejich, ale pro bezbožnost národů těch Hospodin Bůh tvůj vyhání je od tváři tvé, a aby splnil slovo, kteréž s přísahou zaslíbil otcům tvým, Abrahamovi, Izákovi a Jákobovi.'),
(1551354,54,5,9,6,'Protož věziž, že ne pro spravedlnost tvou Hospodin Bůh tvůj dává tobě zemi tu výbornou, abys dědičně držel ji, poněvadž jsi lid tvrdé šíje.'),
(1551355,54,5,9,7,'Pamatujž a nezapomínej, že jsi k hněvu popouzel Hospodina Boha svého na poušti; hned od toho dne, když jsi vyšel z země Egyptské, až jste přišli na místo toto, odporni jste byli Hospodinu.'),
(1551356,54,5,9,8,'Také i na Orébě popudili jste k hněvu Hospodina, a rozhněval se na vás Hospodin, aby vás shladil.'),
(1551357,54,5,9,9,'Když jsem vstoupil na horu, abych vzal dsky kamenné, dsky smlouvy, kterouž učinil s vámi Hospodin, tehdáž jsem trval na hoře čtyřidceti dní a čtyřidceti nocí, chleba nejeda a vody nepije.'),
(1551358,54,5,9,10,'I dal mi Hospodin dvě dsky kamenné, psané prstem Božím, na nichž byla všecka ta slova, kteráž mluvil vám Hospodin na hoře z prostředku ohně v den shromáždění.'),
(1551359,54,5,9,11,'Po skonání pak čtyřidceti dnů a čtyřidceti nocí dal mi Hospodin dvě dsky kamenné, dsky smlouvy.'),
(1551360,54,5,9,12,'I řekl mi Hospodin: Vstana, sstup rychle odsud, nebo poškvrnil se lid tvůj, kterýž jsi vyvedl z Egypta; sešli brzy s cesty, kterouž jsem jim přikázal, a učinili sobě slitinu.'),
(1551361,54,5,9,13,'Mluvil také Hospodin ke mně, řka: Viděl jsem lid ten, a jistě lid tvrdošijný jest.'),
(1551362,54,5,9,14,'Pusť mne, ať je setru, a zahladím jméno jejich pod nebem, tebe pak učiním v národ větší a silnější, nežli jest tento.'),
(1551363,54,5,9,15,'Tedy obrátiv se, sstoupil jsem s hory, (hora pak hořela ohněm), dvě dsky smlouvy maje v obou rukou svých.'),
(1551364,54,5,9,16,'Když jsem pak pohleděl a uzřel jsem, že jste zhřešili Hospodinu Bohu vašemu, udělavše sobě tele lité, (brzy jste byli sešli s cesty, kterouž přikázal vám Hospodin):'),
(1551365,54,5,9,17,'Pochytiv ty dvě dsky, povrhl jsem je z obou rukou svých, a polámal jsem je před očima vašima.'),
(1551366,54,5,9,18,'A padna, ležel jsem před Hospodinem jako i prvé, čtyřidceti dní a čtyřidceti nocí, chleba nejeda a vody nepije, pro všecky hříchy vaše, kterýmiž jste byli zhřešili, činíce to, což zlého jest před očima Hospodinovýma, a popouzejíce jeho.'),
(1551367,54,5,9,19,'Nebo bál jsem se prchlivosti a hněvu, kterýmž se byl popudil Hospodin proti vám, aby zahladil vás, a uslyšel mne Hospodin i tehdáž.'),
(1551368,54,5,9,20,'Na Arona též rozhněval se byl Hospodin náramně, tak že ho zahladiti chtěl; tedy modlil jsem se také za Arona téhož času.'),
(1551369,54,5,9,21,'Hřích pak váš, kterýž jste byli učinili, totiž tele, vzav, spálil jsem je ohněm a zdrobil jsem je, tluka je dobře, dokudž nebylo setříno na prach. Potom vsypal jsem prach jeho do potoka, kterýž tekl s té hory.'),
(1551370,54,5,9,22,'Ano i v Tabbera a v Massah a v Kibrot Hattáve popouzeli jste Hospodina k hněvu.'),
(1551371,54,5,9,23,'A když vás poslal Hospodin z Kádesbarne, řka: Vstupte a opanujte zemi tu, kterouž jsem vám dal, odporni jste byli řeči Hospodina Boha svého, a nevěřili jste jemu, aniž jste uposlechli hlasu jeho.'),
(1551372,54,5,9,24,'Odporni jste byli Hospodinu od toho dne, jakž jsem vás poznal.'),
(1551373,54,5,9,25,'A padna, ležel jsem před Hospodinem čtyřidceti dní a čtyřidceti nocí, v nichž jsem rozprostíral se; nebo řekl Hospodin, že vás chce zahladiti.'),
(1551374,54,5,9,26,'I modlil jsem se Hospodinu, řka: Panovníče Hospodine, nezatracujž lidu svého, a to dědictví svého, kteréž jsi vykoupil velikomocností svou, kteréž jsi vyvedl z Egypta v ruce silné.'),
(1551375,54,5,9,27,'Rozpomeniž se na služebníky své, Abrahama, Izáka a Jákoba; nepatřiž na tvrdost lidu tohoto, na bezbožnost jeho a na hříchy jeho,'),
(1551376,54,5,9,28,'Aby neřekli obyvatelé země té, z níž jsi nás vyvedl: Proto že nemohl Hospodin uvésti jich do země, kterouž zaslíbil jim, aneb že je měl v nenávisti, vyvedl je, aby je pobil na poušti.'),
(1551377,54,5,9,29,'Však oni jsou lid tvůj a dědictví tvé, kteréž jsi vyvedl v síle své veliké a v rameni svém vztaženém.'),
(1551378,54,5,10,1,'Toho času řekl mi Hospodin: Vyhlaď sobě dvě dsky kamenné, podobné prvním, a vstup ke mně na horu, a udělej sobě truhlu dřevěnou.'),
(1551379,54,5,10,2,'I napíši na dskách těch slova, kteráž byla na dskách prvních, kteréž jsi rozrazil, a vložíš je do té truhly.'),
(1551380,54,5,10,3,'Tedy udělal jsem truhlu z dříví setim, a vyhladiv dvě dsky kamenné, podobné prvním, vstoupil jsem na horu, nesa ty dvě dsky v rukou svých.'),
(1551381,54,5,10,4,'I napsal na těch dskách, tak jakž prvé byl napsal, deset slov, kteráž mluvil k vám Hospodin na hoře z prostředku ohně v den shromáždění onoho, a dal je Hospodin mně.'),
(1551382,54,5,10,5,'A obrátiv se, sstoupil jsem s hory té, a vložil jsem ty dsky do truhly, kterouž jsem byl udělal, a byly tam, jakož mi přikázal Hospodin.'),
(1551383,54,5,10,6,'Synové pak Izraelští hnuli se z Beerot synů Jakan do Moserah. Tam umřel Aron, a tu jest pochován; i konal úřad kněžský na místě jeho Eleazar, syn jeho.'),
(1551384,54,5,10,7,'Odtud táhli do Gadgad, a z Gadgad do Jotbata, do země vod tekutých.'),
(1551385,54,5,10,8,'Toho času oddělil Hospodin pokolení Léví, aby nosili truhlu smlouvy Hospodinovy, a aby stáli před Hospodinem k službě jemu, a k dobrořečení ve jménu jeho až do dnešního dne.'),
(1551386,54,5,10,9,'Pročež nemělo pokolení Léví dílu a dědictví s bratřími svými, nebo Hospodin jest dědictví jeho, jakož mluvil k němu Hospodin Bůh tvůj.'),
(1551387,54,5,10,10,'Já pak zůstal jsem na té hoře jako dnů prvních, čtyřidceti dní a čtyřidceti nocí, a uslyšel mne Hospodin i tehdáž, a nechtěl shladiti tebe.'),
(1551388,54,5,10,11,'Potom řekl mi Hospodin: Vstaň, jdi, předcházeje lid, aby vešli a vládli zemí, kterouž jsem s přísahou zaslíbil otcům jejich, že jim ji dám.'),
(1551389,54,5,10,12,'Nyní tedy, Izraeli, čeho žádá Hospodin Bůh tvůj od tebe? Jediné abys se bál Hospodina Boha svého, a chodil po všech cestách jeho, a abys miloval ho, a sloužil Hospodinu Bohu svému v celém srdci svém, a ve vší duši své,'),
(1551390,54,5,10,13,'Ostříhaje přikázaní Hospodinových a ustanovení jeho, kteráž já přikazuji tobě dnes k tvému dobrému.'),
(1551391,54,5,10,14,'Aj, Hospodina Boha tvého jest nebe i nebesa nebes, země a všecky věci, kteréž jsou na ní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551392,54,5,10,15,'Však toliko v otcích tvých zalíbilo se Hospodinu, aby je zamiloval, a vyvolil símě jejich po nich, vás totiž ze všech národů, jakož dnes vidíš.'),
(1551393,54,5,10,16,'Protož obřežtež neobřízku srdce svého, a šíje své nezatvrzujte více.'),
(1551394,54,5,10,17,'Nebo Hospodin Bůh váš, on jest Bůh bohů, a Pán pánů, Bůh silný, veliký, mocný a hrozný, kterýž nepřijímá osoby, ani béře darů,'),
(1551395,54,5,10,18,'Čině soud sirotku a vdově, miluje také příchozího, dávaje mu chléb a oděv.'),
(1551396,54,5,10,19,'Protož milujte hostě, nebo jste byli hosté v zemi Egyptské.'),
(1551397,54,5,10,20,'Hospodina Boha svého báti se budeš, jemu sloužiti, a jeho se přídržeti, a ve jménu jeho přisahati budeš.'),
(1551398,54,5,10,21,'Onť jest chvála tvá, a onť jest Bůh tvůj, kterýž učinil s tebou tyto veliké a hrozné věci, kteréž viděly oči tvé.'),
(1551399,54,5,10,22,'V sedmdesáti dušech sstoupili otcové tvoji do Egypta, nyní pak rozmnožil tě Hospodin Bůh tvůj, abys byl v množství jako hvězdy nebeské.'),
(1551400,54,5,11,1,'Milujž tedy Hospodina Boha svého a ostříhej nařízení jeho, ustanovení a soudů jeho, i přikázaní jeho po všecky dny.'),
(1551401,54,5,11,2,'A znejtež dnes (nebo ne k samým synům vašim mluvím, kteříž neznali toho, ani neviděli), trestání Hospodina Boha svého, důstojnost jeho, ruku jeho silnou a rámě jeho vztažené,'),
(1551402,54,5,11,3,'A znamení i skutky jeho, kteréž činil u prostřed Egypta Faraonovi, králi Egyptskému, i vší zemi jeho,'),
(1551403,54,5,11,4,'A co učinil vojsku Egyptskému, koňům i vozům jeho, kterýž uvedl vody moře Rudého na ně, když vás honili, a shladil je Hospodin až do dnešního dne;'),
(1551404,54,5,11,5,'Také co učinil vám na poušti, dokudž jste nepřišli až k místu tomuto,'),
(1551405,54,5,11,6,'A co učinil Dátanovi a Abironovi, synům Eliaba, syna Rubenova, když země otevřela ústa svá, a požřela je i čeledi jejich, stany jejich se vším statkem jejich, kterýž při sobě měli, u prostřed všeho Izraele.'),
(1551406,54,5,11,7,'Ale oči vaše viděly všecky skutky Hospodinovy veliké, kteréž činil.'),
(1551407,54,5,11,8,'Protož ostříhejte všech přikázaní, kteráž já dnes přikazuji vám, abyste zmocněni byli, a vejdouce, dědičně obdrželi zemi, do kteréž vy jdete k dědičnému jí obdržení,'),
(1551408,54,5,11,9,'A aby se prodlili dnové vaši na zemi, kterouž s přísahou zaslíbil dáti Hospodin otcům vašim i semeni jejich, zemi mlékem a strdí oplývající.'),
(1551409,54,5,11,10,'Nebo země, do kteréž ty již vcházíš, abys ji dědičně obdržel, není jako země Egyptská, z níž jsi vyšel, v kteréž jsi rozsíval símě své, a svlažoval ji do ustání noh svých jako zahradu bylinnou:'),
(1551410,54,5,11,11,'Ale země, do kteréž vy jdete, abyste jí dědičně vládli, jest země hornatá, mající i údolí, kteráž z deště nebeského svlažována bývá vodou,'),
(1551411,54,5,11,12,'Země, o kterouž Hospodin Bůh tvůj pečuje, a vždycky oči Hospodina Boha tvého obráceny jsou na ni, od počátku roku až do konce jeho.'),
(1551412,54,5,11,13,'Protož jestliže opravdově poslouchati budete přikázaní mých, kteráž já vám dnes přikazuji, milujíce Hospodina Boha svého a sloužíce jemu z celého srdce svého a ze vší duše své,'),
(1551413,54,5,11,14,'Dám déšť zemi vaší časem svým, ranní i pozdní, a sklízeti budeš obilé své, víno své i olej svůj.'),
(1551414,54,5,11,15,'Dám i pastvu na poli tvém pro hovada tvá, a budeš jísti až do sytosti.'),
(1551415,54,5,11,16,'Vystříhejtež se tedy, aby nebylo svedeno srdce vaše, abyste odstupujíce, nesloužili bohům cizím, a neklaněli se jim.'),
(1551416,54,5,11,17,'Pročež Hospodin velice by se na vás rozhněval, a zavřel by nebe, aby deště nedávalo, a země aby nedávala úrody své; i zahynuli byste rychle z země výborné, kterouž Hospodin vám dává.'),
(1551417,54,5,11,18,'Ale složte tato slova má v srdci svém a v mysli své, a uvažte je sobě za znamení na rukou svých, a budou jako náčelník mezi očima vašima.'),
(1551418,54,5,11,19,'A vyučujte jim syny své, rozmlouvajíce o nich, když sedneš v domě svém, aneb když půjdeš cestou, když lehneš i když vstaneš.'),
(1551419,54,5,11,20,'Napíšeš je také na veřejích domu svého i na branách svých,'),
(1551420,54,5,11,21,'Aby byli rozmnoženi dnové vaši a dnové synů vašich na zemi, kterouž s přísahou zaslíbil Hospodin otcům vašim, že ji dá jim, dokudž nebe trvá nad zemí.'),
(1551421,54,5,11,22,'Nebo jestliže bedlivě ostříhati budete všech přikázaní těchto, kteráž já přikazuji vám, abyste je činili, milujíce Hospodina Boha svého, a chodíce po všech cestách jeho, a přídržejíce se jeho:'),
(1551422,54,5,11,23,'Tedy vyžene Hospodin všecky ty národy od tváři vaší, a vládnouti budete dědičně národy většími i silnějšími, nežli jste vy.'),
(1551423,54,5,11,24,'Všeliké místo, na kteréž by vstoupila noha vaše, vaše bude; od pouště a od Libánu, a od řeky Eufraten až k moři nejdalšímu bude pomezí vaše.'),
(1551424,54,5,11,25,'Nepostaví se žádný proti vám; strach a bázeň vás pustí Hospodin Bůh váš na tvář vší země, po kteréž choditi budete, jakož jest mluvil vám.'),
(1551425,54,5,11,26,'Hle, já předkládám vám dnes požehnání i zlořečení,'),
(1551426,54,5,11,27,'Požehnání, budete-li poslouchati přikázaní Hospodina Boha svého, kteráž já dnes přikazuji vám,'),
(1551427,54,5,11,28,'Zlořečení pak, jestliže byste neposlouchali přikázaní Hospodina Boha svého, ale sešli byste s cesty, o kteréž já dnes přikazuji vám, následujíce bohů cizích, kterýchž neznáte.'),
(1551428,54,5,11,29,'A když by tě uvedl Hospodin Bůh tvůj do země, do kteréž ty jdeš, abys dědičně vládl jí, tedy dáš požehnání toto na hoře Garizim, a zlořečení na hoře Hébal,'),
(1551429,54,5,11,30,'Kteréž jsou za Jordánem, za cestou chýlící se k západu slunce, v zemi Kananejského, jenž bydlí na rovinách naproti Galgala, blízko rovin More.'),
(1551430,54,5,11,31,'Nebo vy půjdete přes Jordán, abyste vešli a dědičně vládli zemí, kterouž Hospodin Bůh váš dá vám; i obdržíte ji dědičně, a budete v ní bydliti.'),
(1551431,54,5,11,32,'Hleďtež tedy, abyste činili všecka ustanovení a soudy, kteréž já dnes vám předkládám.'),
(1551432,54,5,12,1,'Tato jsou ustanovení a soudové, kterýchž ostříhati budete, činíce je v zemi, kterouž Hospodin Bůh otců tvých dá tobě, abys dědičně vládl jí po všecky dny, v nichž živi budete na zemi.'),
(1551433,54,5,12,2,'Zkazíte do gruntu všecka místa, na nichž sloužili národové, (kteréž vy dědičně opanujete), bohům svým, na vrších vysokých a na pahrbcích, a pod každým stromem ratolestným.'),
(1551434,54,5,12,3,'Oltáře jejich zbořte, a obrazy jejich ztlucte, háje také jejich ohněm spalte a rytiny bohů jejich stroskotejte, a vyhlaďte jméno jejich z místa toho.'),
(1551435,54,5,12,4,'Neučiníte tak Hospodinu Bohu svému,'),
(1551436,54,5,12,5,'Ale kteréž by místo vyvolil Hospodin Bůh váš ze všech pokolení vašich, aby položil jméno své tu, a bydlil na něm, hledati ho, a tam choditi budete.'),
(1551437,54,5,12,6,'Tam také přinášeti budete zápaly své a oběti i desátky své, oběti rukou svých i sliby své, dobrovolné oběti své, i prvorozené z skotů a bravů svých,'),
(1551438,54,5,12,7,'A jísti budete tam před Hospodinem Bohem svým, a veseliti se budete v každé věci, k níž přičiníte ruky své, vy i domové vaši,v nichž požehnal tobě Hospodin Bůh tvůj.'),
(1551439,54,5,12,8,'Nebudete dělati tak, jakž my nyní zde činíme, jeden každý což se mu dobrého vidí.'),
(1551440,54,5,12,9,'Nebo až dosavad nepřišli jste k odpočinutí a dědictví, kteréž Hospodin Bůh tvůj dává tobě.'),
(1551441,54,5,12,10,'Ale když přejdouce Jordán, bydliti budete v zemi, kterouž Hospodin Bůh váš dá vám, abys jí vládl právem dědičným, a odpočinutí dá vám ode všech vůkol nepřátel vašich, a bydliti budete bezpečně:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551442,54,5,12,11,'Tedy k místu tomu, kteréž by vyvolil Hospodin Bůh váš, aby tam přebývalo jméno jeho, přinášeti budete všecky věci, kteréž já přikazuji vám, zápaly své, oběti své a desátky své, a oběti rukou svých a všecko, což předního jest v slibích vašich, kteréž byste činili Hospodinu.'),
(1551443,54,5,12,12,'A veseliti se budete před Hospodinem Bohem svým, vy i synové vaši i dcery vaše, služebníci vaši i děvky vaše, i Levíta, kterýž jest v branách tvých, nebo nemají dílu a dědictví s vámi.'),
(1551444,54,5,12,13,'Vystříhej se, abys neobětoval zápalných obětí svých na žádném místě, kteréž bys sobě obhlédl.'),
(1551445,54,5,12,14,'Ale na tom místě, kteréž by vyvolil Hospodin v jednom z pokolení tvých, tam obětovati budeš zápaly své, a tam učiníš všecko, což já přikazuji tobě.'),
(1551446,54,5,12,15,'A však jestliže by se kdy zalíbilo duši tvé, zabiješ sobě, a jísti budeš maso vedlé požehnání Hospodina Boha svého, kteréž by dal tobě ve všech městech tvých; nečistý i čistý jísti je bude, jako srnu i jelena.'),
(1551447,54,5,12,16,'Krve toliko jísti nebudete, na zemi vycedíte ji jako vodu.'),
(1551448,54,5,12,17,'Nebudeš moci jísti v městě svém desátků obilí svého, vína a oleje svého, i prvorozených skotů a bravů svých, i všeho, k čemuž se slibem zavážeš, dobrovolných obětí svých a obětí rukou svých.'),
(1551449,54,5,12,18,'Ale před Hospodinem Bohem svým jísti je budeš na místě, kteréž vyvolil Hospodin Bůh tvůj, ty i syn tvůj i dcera tvá, služebník tvůj a děvka tvá, i Levíta, kterýž jest v branách tvých, a veseliti se budeš před Hospodinem Bohem svým ve všech věcech, k nimž bys přičinil ruky své.'),
(1551450,54,5,12,19,'Vystříhejž se, abys neopouštěl Levítů v zemi své po všecky dny své.'),
(1551451,54,5,12,20,'Když rozšíří Hospodin Bůh tvůj pomezí tvé, jakož mluvil tobě, a řekl bys sám v sobě: Budu jísti maso, proto že žádá duše tvá jísti maso, vedlé vší líbosti své jísti budeš maso.'),
(1551452,54,5,12,21,'Jestliže by daleko bylo od tebe místo, kteréž vyvolí Hospodin Bůh tvůj, aby přebývalo tam jméno jeho, zabiješ hovado z skotů neb bravů svých, kteréž by dal Hospodin tobě, jakžť jsem přikázal tobě, a jísti budeš v městě svém, vedlé vší líbosti duše své.'),
(1551453,54,5,12,22,'Jakž se jídá srna a jelen, tak je jísti budeš; nečistý i čistý bude je jísti.'),
(1551454,54,5,12,23,'Toliko buď stálý, abys krve nejedl; nebo krev jest duše, protož nebudeš jísti duše s masem jejím.'),
(1551455,54,5,12,24,'Nejeziž jí, ale na zem ji vyceď jako vodu.'),
(1551456,54,5,12,25,'Nebudeš jísti jí, aby tobě dobře bylo i synům tvým po tobě, když bys činil, což dobrého jest před očima Hospodinovýma.'),
(1551457,54,5,12,26,'Ale posvěcené věci své, kteréž bys měl, a což bys slíbil, vezmeš, a doneseš na místo, kteréž vyvolí Hospodin,'),
(1551458,54,5,12,27,'A obětovati budeš oběti své zápalné, maso a krev, na oltář Hospodina Boha svého; ale krev jiných obětí tvých vylita bude na oltář Hospodina Boha tvého, maso pak jísti budeš.'),
(1551459,54,5,12,28,'Ostříhej a poslouchej všech slov těchto, kteráž já přikazuji tobě, aby tobě dobře bylo i synům tvým po tobě až na věky, když bys činil, což dobrého a pravého jest, před očima Hospodina Boha svého.'),
(1551460,54,5,12,29,'Když by pak vyplénil Hospodin Bůh tvůj od tváři tvé národy ty, k nimž ty tudíž vejdeš, abys dědičně vládl jimi, a dědičně je opanoval, a bydlil v zemi jejich,'),
(1551461,54,5,12,30,'Vystříhej se, abys neuvázl v osídle, jda za nimi, když by již vyhlazeni byli od tváři tvé. Nevyptávej se na bohy jejich, říkaje: Jak jsou sloužili národové ti bohům svým, tak i já učiním.'),
(1551462,54,5,12,31,'Neučiníš tak Hospodinu Bohu svému, nebo všecko, což v ohavnosti má Hospodin, a čehož nenávidí, činili bohům svým; také i syny své a dcery své ohněm pálili ke cti bohům svým.'),
(1551463,54,5,12,32,'Cožkoli já přikazuji vám, ostříhati budete, činíce to; nepřidáte k tomu, aniž co z toho ujmete.'),
(1551464,54,5,13,1,'Povstal-li by u prostřed tebe prorok, aneb někdo, ješto by míval sny, a ukázal by tobě znamení aneb zázrak,'),
(1551465,54,5,13,2,'Byť se pak i stalo to znamení aneb zázrak, a mluvil by tobě, řka: Poďme, následujme bohů cizích, (kterýchž neznáš,) a služme jim:'),
(1551466,54,5,13,3,'Neuposlechneš slov proroka toho, ani snáře, nebo zkušuje vás Hospodin Bůh váš, aby známé bylo, milujete-li Hospodina Boha svého z celého srdce svého a z celé duše své.'),
(1551467,54,5,13,4,'Hospodina Boha svého následujte, a jeho se bojte, přikázaní jeho ostříhejte, hlasu jeho poslouchejte, jemu služte a jeho se přídržte.'),
(1551468,54,5,13,5,'Prorok pak ten aneb snář zamordován bude, nebo mluvil to, čímž by odvrátil vás od Hospodina Boha vašeho, (kterýž vyvedl vás z země Egyptské, a vykoupil tě z domu služby,) aby tě srazil s cesty, kterouž přikázal tobě Hospodin Bůh tvůj, abys chodil po ní; a tak odejmeš zlé z prostředku svého.'),
(1551469,54,5,13,6,'Jestliže by tě tajně nabádal bratr tvůj, syn matky tvé, aneb syn tvůj, aneb dcera tvá, aneb manželka, kteráž jest v lůně tvém, aneb přítel tvůj, kterýžť by milý byl jako duše tvá, řka: Poďme a služme bohům cizím, (kterýchž jsi neznal ty ani otcové tvoji),'),
(1551470,54,5,13,7,'Z bohů pohanských, kteříž vůkol vás jsou, buď blízko aneb daleko od tebe, od jednoho konce země až do druhého konce jejího,'),
(1551471,54,5,13,8,'Nepovoluj jemu, aniž ho poslouchej;neodpustíť mu oko tvé, aniž se slituješ, aniž zatajíš ho,'),
(1551472,54,5,13,9,'Ale bez milosti zabiješ jej; ruka tvá nejprv na něj bude vztažena, abys ho zabil, a potom ruce všeho lidu.'),
(1551473,54,5,13,10,'A ukamenuješ jej až do smrti, nebo chtěl odvésti tebe od Hospodina Boha tvého, kterýž tě vyvedl z země Egyptské, z domu služby,'),
(1551474,54,5,13,11,'Aby všecken lid Izraelský, uslyšíce to, báli se, a nečinili více něco podobného věci této nejhorší u prostřed tebe.'),
(1551475,54,5,13,12,'Uslyšel-li bys o některém městě svém, kteréž Hospodin Bůh tvůj dá tobě, abys tam bydlil, ani praví:'),
(1551476,54,5,13,13,'Vyšli muži, lidé nešlechetní z prostředku tvého, kteříž svedli spoluobyvatele své, řkouce: Poďme, služme bohům cizím, kterýchž neznáte:'),
(1551477,54,5,13,14,'Tedy vyhledej a vyzvěz a dobře se na to vyptej, a jestliže jest pravda a jistá věc, že ohavnost se stala u prostřed tebe,'),
(1551478,54,5,13,15,'Zbiješ obyvatele města toho mečem, a jako věc proklatou zkazíš je i všecko, což by v něm bylo, hovada také jeho mečem pobiješ.'),
(1551479,54,5,13,16,'A všecky kořisti jeho shromáždíš u prostřed ulice jeho, a spálíš ohněm to město i všecky kořisti jeho docela Hospodinu Bohu svému, aby byla hromada rumu věčná; a nebude více staveno.'),
(1551480,54,5,13,17,'A nevezmeš ničehož z věcí proklatých, aby Hospodin odvrátil se od hněvu prchlivosti své, a učinil tobě milosrdenství svá, a smiloval se nad tebou, i rozmnožil tě, jakož s přísahou zaslíbil otcům tvým.'),
(1551481,54,5,13,18,'Protož poslouchati budeš hlasu Hospodina Boha svého, ostříhaje všech přikázaní jeho, kteráž já dnes přikazuji tobě, abys činil, což pravého jest, před očima Hospodina Boha svého.'),
(1551482,54,5,14,1,'Synové jste Hospodina Boha vašeho, protož nebudete se řezati, aniž sobě uděláte lysiny mezi očima vašima nad mrtvým.'),
(1551483,54,5,14,2,'Nebo lid svatý jsi Hospodinu Bohu svému, a tebe vyvolil Hospodin, abys jemu byl za lid zvláštní ze všech národů, kteříž jsou na tváři země.'),
(1551484,54,5,14,3,'Nebudeš jísti žádné věci ohavné.'),
(1551485,54,5,14,4,'Tato jsou hovada, kteráž jísti budete: Voly, ovce a kozy,'),
(1551486,54,5,14,5,'Jelena, dannele, srnu, kamsíka, jezevce, bůvola a losa.'),
(1551487,54,5,14,6,'Každé hovado, kteréž má kopyta rozdělená, tak aby rozdvojená byla, a přežívá mezi hovady, jísti je budete.'),
(1551488,54,5,14,7,'A však ne všech přežívajících, aneb těch, kteráž kopyta rozdělená mají, budete jísti, jako velblouda, zajíce a králíka; nebo ač přežívají, však kopyta rozděleného nemají, nečistá jsou vám.'),
(1551489,54,5,14,8,'Též svině, nebo rozdělené majíc kopyto, nepřežívá, nečistá vám bude; masa jejího jísti nebudete, a mrchy její se nedotknete.'),
(1551490,54,5,14,9,'Ze všech pak živočichů, kteříž u vodách jsou, tyto jísti budete: Cožkoli má plejtvy a šupiny, jísti budete.'),
(1551491,54,5,14,10,'Což pak nemá plejtví a šupin, toho jísti nebudete; nečisté vám bude.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551492,54,5,14,11,'Všecko ptactvo čisté jísti budete.'),
(1551493,54,5,14,12,'Těchto pak jísti nebudete: Orla, noha, orlice mořské,'),
(1551494,54,5,14,13,'A sokola, supa a luňáka vedlé pokolení jeho,'),
(1551495,54,5,14,14,'A žádného krkavce vedlé pokolení jeho,'),
(1551496,54,5,14,15,'Pstrosa, sovy, vodní káně a krahulce vedlé pokolení jeho,'),
(1551497,54,5,14,16,'Raroha, kalousa a labuti,'),
(1551498,54,5,14,17,'Pelikána, porfiriána a křehaře,'),
(1551499,54,5,14,18,'Čápa, volavky vedlé pokolení jejího, dedka a netopýře.'),
(1551500,54,5,14,19,'A všeliký zeměplaz létající nečistý bude vám, nebudete ho jísti.'),
(1551501,54,5,14,20,'Každého ptáka čistého jísti budete.'),
(1551502,54,5,14,21,'Žádné umrliny jísti nebudete; příchozímu, kterýž jest v branách tvých, dáš ji, a jísti ji bude, aneb prodáš cizozemci, nebo lid svatý jsi Hospodinu Bohu svému. Nebudeš vařiti kozelce v mléce matky jeho.'),
(1551503,54,5,14,22,'Ochotně dávati budeš desátky ze všech užitků semene svého, kteřížť by přišli s pole každého roku.'),
(1551504,54,5,14,23,'A jísti budeš před Hospodinem Bohem svým, (na místě, kteréž by vyvolil, aby tam přebývalo jméno jeho,) desátky z obilí, vína i oleje svého, a prvorozené z volů svých a drobného dobytka svého, abys se učil báti Hospodina Boha svého po všecky dny.'),
(1551505,54,5,14,24,'Jestliže by pak daleká byla cesta, a nemohl bys donésti toho, proto že daleko jest od tebe to místo, kteréž by vyvolil Hospodin Bůh tvůj k přebývání tam jména svého, když požehná tobě Hospodin Bůh tvůj:'),
(1551506,54,5,14,25,'Tedy zpeněžíš je, a svázané peníze vezma v ruku svou, půjdeš k místu, kteréž by vyvolil Hospodin Bůh tvůj,'),
(1551507,54,5,14,26,'A vynaložíš ty peníze na všecko, čehož žádá duše tvá, na voly, na ovce, na víno, aneb jiný nápoj silný, a na všecko, čehož by sobě žádala duše tvá, a jísti budeš tam před Hospodinem Bohem svým, a veseliti se budeš ty i dům tvůj.'),
(1551508,54,5,14,27,'Levíty pak, kterýž by v branách tvých bydlil, neopustíš, nebo nemá dílu a dědictví s tebou.'),
(1551509,54,5,14,28,'Každého léta třetího oddělíš všecky desátky z užitků svých toho léta, a složíš je v branách svých.'),
(1551510,54,5,14,29,'I přijde Levíta, (nebo nemá dílu a dědictví s tebou), a host a sirotek i vdova, kteříž jsou v branách tvých, i budou jísti a nasytí se, aby požehnal tobě Hospodin Bůh tvůj při všelikém díle rukou tvých, kteréž bys dělal.'),
(1551511,54,5,15,1,'Každého léta sedmého odpouštěti budeš.'),
(1551512,54,5,15,2,'Tento pak bude způsob odpuštění, aby odpustil každý věřitel, kterýž rukou svou půjčil to, čehož půjčil bližnímu svému; nebude upomínati bližního svého aneb bratra svého, nebo vyhlášeno jest odpuštění Hospodinovo.'),
(1551513,54,5,15,3,'Cizozemce upomínati budeš, ale to, což bys měl u bratra svého, propustí ruka tvá.'),
(1551514,54,5,15,4,'Toliko aby nuzným někdo nebyl příčinou tvou, poněvadž hojně požehná tobě Hospodin v zemi, kterouž Hospodin Bůh tvůj dá tobě v dědictví, abys jí dědičně vládl:'),
(1551515,54,5,15,5,'Jestliže však pilně poslouchati budeš hlasu Hospodina Boha svého, tak abys hleděl činiti každé přikázaní toto, kteréž já tobě dnes přikazuji.'),
(1551516,54,5,15,6,'Hospodin zajisté Bůh tvůj požehná tobě, jakož mluvil tobě, tak že budeš moci půjčovati národům mnohým, tobě pak nebude potřeba vypůjčovati; i budeš panovati nad národy mnohými, ale oni nad tebou nebudou panovati.'),
(1551517,54,5,15,7,'Byl-li by u tebe nuzný někdo z bratří tvých, v některém městě tvém, v zemi tvé, kterouž Hospodin Bůh tvůj dá tobě, nezatvrdíš srdce svého, a nezavřeš ruky své před nuzným bratrem svým:'),
(1551518,54,5,15,8,'Ale štědře otevřeš jemu ruku svou, a ochotně půjčíš jemu, jakž by mnoho potřeboval toho, v čemž by nouzi měl.'),
(1551519,54,5,15,9,'Vystříhej se, aby nebylo něco nepravého v srdci tvém, a řekl bys: Blíží se rok sedmý, jenž jest rok odpuštění, a bylo by nešlechetné oko tvé k bratru tvému nuznému, tak že bys neudělil jemu, pročež by volal proti tobě k Hospodinu, a byl by na tobě hřích:'),
(1551520,54,5,15,10,'Ale ochotně dáš jemu, a nebude srdce tvé neupřímé, když bys dával jemu; nebo tou příčinou požehná tobě Hospodin Bůh tvůj ve všech skutcích tvých a ve všem díle, k kterémuž bys vztáhl ruku svou.'),
(1551521,54,5,15,11,'Nebo nebudete bez chudých v zemi vaší; protož přikazuji tobě, řka: Abys ochotně otvíral ruku svou bratru svému, chudému svému a nuznému svému v zemi své.'),
(1551522,54,5,15,12,'Jestliže by prodán byl tobě bratr tvůj Žid aneb Židovka, a sloužil by tobě za šest let, sedmého léta propustíš jej od sebe svobodného.'),
(1551523,54,5,15,13,'A když jej propustíš svobodného od sebe, nepustíš ho prázdného.'),
(1551524,54,5,15,14,'Štědře darovati jej budeš dary z dobytka svého, z stodoly a z vinice své; v čemž požehnal tobě Hospodin Bůh tvůj, z toho dáš jemu.'),
(1551525,54,5,15,15,'A pamatuj, že jsi služebníkem byl v zemi Egyptské, a že tě vykoupil Hospodin Bůh tvůj, protož já to dnes tobě přikazuji.'),
(1551526,54,5,15,16,'Pakliť by řekl: Nepůjdu od tebe, proto že by tě miloval i dům tvůj, a že mu dobře u tebe,'),
(1551527,54,5,15,17,'Tedy vezma špici, probodneš ucho jeho na dveřích, a bude u tebe služebníkem na věky. Takž podobně i děvce své učiníš.'),
(1551528,54,5,15,18,'Nechť není za těžké před očima tvýma, když bys ho svobodného propustil od sebe, nebo dvojnásob více, než ze mzdy nájemník, sloužil tobě šest let; i požehná tobě Hospodin ve všech věcech, kteréž činiti budeš.'),
(1551529,54,5,15,19,'Všeho prvorozeného, což se narodí z skotů tvých neb z bravů tvých, samce posvětíš Hospodinu Bohu svému. Nebudeš dělati prvorozeným volkem svým, a nebudeš holiti prvorozených ovec svých.'),
(1551530,54,5,15,20,'Před Hospodinem Bohem svým budeš je jísti na každý rok na místě, kteréž by vyvolil Hospodin, ty i čeled tvá.'),
(1551531,54,5,15,21,'Pakliť by na něm byla vada, že by kulhavé aneb slepé bylo, aneb mělo by jakoukoli škodlivou vadu, nebudeš ho obětovati Hospodinu Bohu svému.'),
(1551532,54,5,15,22,'V branách svých budeš je jísti, buďto čistý neb nečistý, rovně jako srnu aneb jelena;'),
(1551533,54,5,15,23,'Toliko krve jeho nebudeš jísti, ale na zem vycedíš ji jako vodu.'),
(1551534,54,5,16,1,'Ostříhej měsíce Abib, abys slavil Fáze Hospodinu Bohu svému, nebo toho měsíce Abib vyvedl tě Hospodin Bůh tvůj z Egypta v noci.'),
(1551535,54,5,16,2,'A obětovati budeš Fáze Hospodinu Bohu svému z bravů i skotů na místě, kteréž by vyvolil Hospodin, aby tam přebývalo jméno jeho.'),
(1551536,54,5,16,3,'Nebudeš v něm jísti nic kvašeného. Za sedm dní jísti budeš přesnice, chléb trápení, (nebo s chvátáním vyšel jsi z země Egyptské), abys pamatoval na den, v kterémž jsi vyšel z země Egyptské, po všecky dny života svého.'),
(1551537,54,5,16,4,'Aniž spatřín bude u tebe kvas ve všech končinách tvých za sedm dní, a nezůstane nic přes noc masa toho, kteréž bys obětoval u večer toho dne prvního, až do jitra.'),
(1551538,54,5,16,5,'Nebudeš moci obětovati Fáze v každém městě svém, kteréž Hospodin Bůh tvůj dává tobě,'),
(1551539,54,5,16,6,'Ale na místě, kteréž by vyvolil Hospodin Bůh tvůj, aby přebývalo tam jméno jeho, tu obětovati budeš Fáze, a to u večer, při západu slunce v jistý čas vyjití tvého z Egypta.'),
(1551540,54,5,16,7,'Péci pak budeš a jísti na místě, kteréž by vyvolil Hospodin Bůh tvůj, a ráno navracuje se, půjdeš do stanů svých.'),
(1551541,54,5,16,8,'Šest dní jísti budeš přesnice, dne pak sedmého bude slavnost Hospodinu Bohu tvému; ničehož v ní dělati nebudeš.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551542,54,5,16,9,'Sedm téhodnů sečteš sobě; od začátku žně začneš počítati sedm téhodnů.'),
(1551543,54,5,16,10,'Tehdy slaviti budeš slavnost téhodnů Hospodinu Bohu svému; seč budeš moci býti, to dáš dobrovolně vedlé toho, jakžť by požehnal Hospodin Bůh tvůj.'),
(1551544,54,5,16,11,'I veseliti se budeš před Hospodinem Bohem svým, ty i syn tvůj i dcera tvá, služebník tvůj a děvka tvá, i Levíta, kterýž by byl v branách tvých, a příchozí, sirotek i vdova, kteříž by byli u prostřed tebe, na místě, kteréž by vyvolil Hospodin Bůh tvůj k přebývání tam jména svého.'),
(1551545,54,5,16,12,'A tak rozpomínati se budeš, že jsi byl služebníkem v Egyptě, když ostříhati a vykonávati budeš ustanovení tato.'),
(1551546,54,5,16,13,'Slavnost stanů světiti budeš za sedm dní, když shromáždíš s pole svého a z vinice své.'),
(1551547,54,5,16,14,'I budeš se veseliti v slavnosti své, ty i syn tvůj i dcera tvá, služebník tvůj a služebnice tvá, Levíta i příchozí, sirotek i vdova, kteříž by byli v branách tvých.'),
(1551548,54,5,16,15,'Sedm dní svátek světiti budeš Hospodinu Bohu svému na místě, kteréž by vyvolil Hospodin, když požehná tobě Hospodin Bůh tvůj ve všech úrodách tvých, a ve všeliké práci rukou tvých, a tak budeš vesel.'),
(1551549,54,5,16,16,'Třikrát v roce postaví se každý pohlaví mužského před Hospodinem Bohem tvým na místě, kteréž by vyvolil, na slavnost přesnic, na slavnost téhodnů a na slavnost stanů, a neukážeť se před Hospodinem prázdný;'),
(1551550,54,5,16,17,'Každý podlé daru sobě daného, vedlé požehnání Hospodina Boha tvého, jehož on udělil tobě.'),
(1551551,54,5,16,18,'Soudce a správce ustanovíš sobě ve všech městech svých, kteráž Hospodin Bůh tvůj dá tobě v každém pokolení tvém, kteříž souditi budou lid soudem spravedlivým.'),
(1551552,54,5,16,19,'Neuchýlíš soudu, a nebudeš šetřiti osoby, aniž přijmeš daru; nebo dar oslepuje oči moudrých, a převrací slova spravedlivých.'),
(1551553,54,5,16,20,'Spravedlivě spravedlnosti následovati budeš, abys živ byl, a dědičně vládl zemí,kterouž Hospodin Bůh tvůj dává tobě.'),
(1551554,54,5,16,21,'Nevysadíš sobě háje jakýmkoli dřívím u oltáře Hospodina Boha svého, kterýž uděláš sobě,'),
(1551555,54,5,16,22,'Ani vyzdvihneš sobě modly, což v ohavnosti má Hospodin Bůh tvůj.'),
(1551556,54,5,17,1,'Nebudeš obětovati Hospodinu Bohu svému vola aneb dobytčete, na němž by vada byla, aneb jakákoli věc zlá, nebo ohavnost jest Hospodinu Bohu tvému.'),
(1551557,54,5,17,2,'Bude-li nalezen u prostřed tebe v některém městě tvém, kteráž Hospodin Bůh tvůj dá tobě, muž aneb žena, ješto by se dopouštěl zlého před očima Hospodina Boha tvého, přestupuje smlouvu jeho,'),
(1551558,54,5,17,3,'A odejda, sloužil by bohům cizím, a klaněl by se jim, buď slunci neb měsíci, aneb kterému rytířstvu nebeskému, čehož jsem nepřikázal,'),
(1551559,54,5,17,4,'A bylo by povědíno tobě, a slyšel bys o tom, tedy vyptáš se pilně na to, a jestliže bude pravda a věc jistá, že by se stala taková ohavnost v Izraeli:'),
(1551560,54,5,17,5,'Bez lítosti vyvedeš muže toho aneb ženu tu, kteříž to zlé páchali, k branám svým, muže toho aneb ženu, a kamením je uházíš, ať zemrou.'),
(1551561,54,5,17,6,'V ústech dvou aneb tří svědků zabit bude ten, kdož umříti má, nebudeť pak zabit podlé vyznání svědka jednoho.'),
(1551562,54,5,17,7,'Ruka svědků nejprv bude proti němu k zabití jeho, a potom ruce všeho lidu, a tak odejmeš zlé z prostředku svého.'),
(1551563,54,5,17,8,'Bylo-li by při soudu něco nesnadného, mezi krví a krví, mezi pří a pří, mezi ranou a ranou, v jakékoli rozepři v branách tvých, tedy vstana, půjdeš k místu, kteréž by vyvolil Hospodin Bůh tvůj,'),
(1551564,54,5,17,9,'A přijdeš k kněžím Levítského pokolení aneb k soudci, kterýž by tehdáž byl, i budeš se jich ptáti, a oznámíť výpověd soudu.'),
(1551565,54,5,17,10,'Učiníš tedy vedlé naučení, kteréž by vynesli z místa toho, kteréž by vyvolil Hospodin, a hleď, abys všecko, čemuž by tě učili, tak vykonal.'),
(1551566,54,5,17,11,'Podlé vyrčení zákona, kterémuž by tě naučili, a podlé rozsudku, kterýžť by vypověděli, učiníš; neuchýlíš se od slova sobě oznámeného ani na pravo ani na levo.'),
(1551567,54,5,17,12,'Jestliže by pak kdo v zpouru se vydal, tak že by neposlechl kněze postaveného tam k službě před Hospodinem Bohem tvým, aneb soudce, tedy ať umře člověk ten, a odejmeš zlé z Izraele,'),
(1551568,54,5,17,13,'Aby všecken lid uslyšíce, báli se, a více v zpouru se nevydávali.'),
(1551569,54,5,17,14,'Když vejdeš do země, kterouž Hospodin Bůh tvůj dá tobě, abys ji dědičně obdržel, a budeš v ní bydliti, a řekneš: Ustanovím nad sebou krále, jako i jiní národové mají, kteříž jsou vůkol mne:'),
(1551570,54,5,17,15,'Toho toliko ustanovíš nad sebou krále, kteréhož by vyvolil Hospodin Bůh tvůj. Z prostředku bratří svých ustanovíš nad sebou krále; nebudeš moci ustanoviti nad sebou člověka cizozemce, kterýž by nebyl bratr tvůj.'),
(1551571,54,5,17,16,'A však ať nemívá mnoho koňů, a ať neobrací zase lidu do Egypta, z příčiny rozmnožení koňů, zvláště poněvadž Hospodin vám řekl: Nevracujte se zase cestou touto více.'),
(1551572,54,5,17,17,'Nebudeť také míti mnoho žen, aby se neodvrátilo srdce jeho; stříbra také aneb zlata ať sobě příliš nerozmnožuje.'),
(1551573,54,5,17,18,'Když pak dosedne na stolici království svého, vypíše sobě připomenutý zákon tento do knihy z té, kteráž bude před oblíčejem kněží Levítských.'),
(1551574,54,5,17,19,'A bude jej míti při sobě, a čísti jej bude po všecky dny života svého, aby se naučil báti Hospodina Boha svého, a aby ostříhal všech slov zákona tohoto i ustanovení těch, a činil je,'),
(1551575,54,5,17,20,'Aby nepozdvihlo se srdce jeho nad bratří jeho, a neuchýlilo se od přikázaní na pravo aneb na levo, aby dlouho živ byl v království svém, on i synové jeho u prostřed Izraele.'),
(1551576,54,5,18,1,'Nebudou míti kněží Levítští a všecko pokolení Levítské dílu a dědictví s jiným lidem Izraelským, oběti ohnivé Hospodinovy a dědictví jeho jísti budou.'),
(1551577,54,5,18,2,'Dědictví nebudou míti u prostřed bratří svých, Hospodin jest dědictví jejich, jakož jim mluvil.'),
(1551578,54,5,18,3,'Toto pak náležeti bude kněžím od lidu, od obětujících obět, buď vola neb dobytče: Dáno bude knězi plece, a líce a žaludek.'),
(1551579,54,5,18,4,'Prvotiny obilé svého, vína a oleje svého, i prvotiny vlny z ovec svých dáš jemu.'),
(1551580,54,5,18,5,'Nebo jej vyvolil Hospodin Bůh tvůj ze všech pokolení tvých, aby stál k službě ve jménu Hospodina, on i synové jeho po všecky dny.'),
(1551581,54,5,18,6,'Když by pak přišel který Levíta z některého města tvého, ze všeho Izraele, kdež bydlil, a přišel by s velikou žádostí duše své na místo, kteréž by vyvolil Hospodin:'),
(1551582,54,5,18,7,'Sloužiti bude ve jménu Hospodina Boha svého, jako i jiní bratří jeho Levítové, kteříž tu stojí před Hospodinem.'),
(1551583,54,5,18,8,'Díl rovný jísti budou, (bez škody toho, což by každý z nich prodal,) vedlé čeledi otců.'),
(1551584,54,5,18,9,'Když vejdeš do země, kterouž Hospodin Bůh tvůj dává tobě, neuč se činiti podlé ohavností národů těch.'),
(1551585,54,5,18,10,'Nebude nalezen v tobě, kdož by vedl syna svého aneb dceru svou skrz oheň, ani věštěc, ani planétník, ani čarodějník, ani kouzedlník.'),
(1551586,54,5,18,11,'Ani losník, ani zaklinač, ani hadač, ani černokněžník.'),
(1551587,54,5,18,12,'Nebo ohavnost jest Hospodinu, kdožkoli činí to, a pro takové ohavnosti Hospodin Bůh tvůj vymítá je od tváři tvé.'),
(1551588,54,5,18,13,'Dokonalý budeš před Hospodinem Bohem svým.'),
(1551589,54,5,18,14,'Nebo národové ti, kterýmiž vládnouti budeš, planetářů a věšťců poslouchají, tobě pak toho nedopouští Hospodin Bůh tvůj.'),
(1551590,54,5,18,15,'Proroka z prostředku tvého, z bratří tvých, jako já jsem, vzbudí tobě Hospodin Bůh tvůj; jeho poslouchati budete,'),
(1551591,54,5,18,16,'Podlé všeho toho, jakž jsi žádal od Hospodina Boha svého, na Orébě, v den shromáždění, řka: Ať více neslyším hlasu Hospodina Boha svého, ani více vidím ohně toho velikého, abych neumřel.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551592,54,5,18,17,'Pročež mi řekl Hospodin: Dobře mluvili, což jsou mluvili.'),
(1551593,54,5,18,18,'Proroka vzbudím jim z prostředku bratří jejich, jako jsi ty, a položím slova má v ústa jeho, a bude jim mluviti všecko, což mu přikáži.'),
(1551594,54,5,18,19,'I budeť, že kdo by koli neposlouchal slov mých, kteráž mluviti bude ve jménu mém, já vyhledávati budu na něm.'),
(1551595,54,5,18,20,'Prorok pak, kterýž by pyšně se vystavoval, mluvě slovo ve jménu mém, kteréhož jsem mluviti jemu nepřikázal, a kterýž by mluvil ve jménu bohů cizích, takový prorok ať umře.'),
(1551596,54,5,18,21,'Jestliže pak díš v srdci svém: Kterak poznáme slovo to, jehož by nemluvil Hospodin?'),
(1551597,54,5,18,22,'Když by mluvil něco prorok ve jménu Hospodinovu, a však by se toho nestalo, aniž by přišlo, toť jest to slovo, jehož nemluvil Hospodin; z pychuť jest to mluvil prorok ten, nebojž se ho.'),
(1551598,54,5,19,1,'Když by vyhladil Hospodin Bůh tvůj národy, jejichžto zemi Hospodin Bůh tvůj dává tobě, a opanoval bys je dědičně, a bydlil bys v městech jejich i v domích jejich:'),
(1551599,54,5,19,2,'Oddělíš sobě tři města u prostřed země své, kterouž Hospodin Bůh tvůj dává tobě, abys ji dědičně obdržel.'),
(1551600,54,5,19,3,'Spravíš sobě cesty, a rozdělíš na tři díly všecku krajinu země své, kterouž v dědictví dá tobě Hospodin Bůh tvůj, i bude utíkati tam každý vražedlník:'),
(1551601,54,5,19,4,'(Totoť pak bude právo vražedlníka, kterýž by tam utekl, aby živ byl: Kdož by zabil bližního svého nechtě, aniž by ho nenáviděl prvé.'),
(1551602,54,5,19,5,'Jako vejda někdo s bližním svým do lesa sekati dříví, rozvedl by rukou svou sekeru, aby uťal dřevo, a ona by spadla s topořiště, a trefila by bližního jeho, tak že by umřel, ten uteče do některého z měst těchto, a živ bude.)'),
(1551603,54,5,19,6,'Aby přítel zabitého, stihaje vražedlníka toho, když by se rozpálilo srdce jeho, nedohonil ho na daleké cestě, a ranil smrtedlně, ješto by nebyl hoden smrti, poněvadž ho prvé neměl v nenávisti.'),
(1551604,54,5,19,7,'Protož já přikazuji tobě, řka: Tři města oddělíš sobě.'),
(1551605,54,5,19,8,'Pakli by rozšířil Hospodin Bůh tvůj končiny tvé, jakož s přísahou zaslíbil otcům tvým, a dal by tobě všecku tu zemi, kterouž řekl dáti otcům tvým:'),
(1551606,54,5,19,9,'(Když bys ostříhal všech přikázaní těchto, čině je, kteráž já dnes přikazuji tobě, abys miloval Hospodina Boha svého, a chodil po cestách jeho po všecky dny), tedy přidáš sobě ještě tři města mimo tři onano,'),
(1551607,54,5,19,10,'Aby nebyla vylita krev nevinná u prostřed země tvé, kterouž Hospodin Bůh tvůj dá tobě v dědictví, a aby nebyla na tobě krev.'),
(1551608,54,5,19,11,'Ale byl-li by kdo, maje v nenávisti bližního svého, a činil by úklady jemu, a povstana proti němu, ranil by ho smrtedlně, tak že by umřel, a utekl by do některého z těch měst:'),
(1551609,54,5,19,12,'Tedy pošlí starší města toho, a vezmou jej odtud, a dají v ruce přítele toho zabitého, aby umřel.'),
(1551610,54,5,19,13,'Neodpustí jemu oko tvé, ale svedeš krev nevinnou z Izraele, i bude dobře tobě.'),
(1551611,54,5,19,14,'Nepřeneseš meze bližního svého, kterouž vymezili předkové v dědictví tvém, kteréž obdržíš v zemi, jižto Hospodin Bůh tvůj dává tobě, abys ji dědičně obdržel.'),
(1551612,54,5,19,15,'Nepovstane svědek jeden proti někomu z příčiny jakékoli nepravosti, a jakéhokoli hříchu ze všech hříchů, kterýmiž by kdo hřešil; v ústech dvou svědků aneb v ústech tří svědků stane slovo.'),
(1551613,54,5,19,16,'Povstal-li by svědek falešný proti někomu, aby svědčil proti němu, že odstoupil od Boha,'),
(1551614,54,5,19,17,'Tedy postaví se ti dva muži, kteříž tu rozepři mají před Hospodinem, před kněžími aneb před soudci, kteříž by za dnů těch byli.'),
(1551615,54,5,19,18,'A když se pilně vyptají soudcové, poznají-li, že svědek ten jest svědek lživý, mluvě falešné svědectví proti bližnímu svému,'),
(1551616,54,5,19,19,'Tak jemu učiňte, jakž on myslil učiniti bratru svému. I odejmeš zlé z prostředku svého.'),
(1551617,54,5,19,20,'A kteříž zůstanou, slyšíce to, báti se budou, a nikoli více nedopustí se takových zlých věcí u prostřed tebe.'),
(1551618,54,5,19,21,'A neslituje se oko tvé; život za život, oko za oko, zub za zub, ruka za ruku, noha za nohu bude.'),
(1551619,54,5,20,1,'Když bys vytáhl na vojnu proti nepřátelům svým, a uzřel bys koně a vozy, a lid větší, nežli ty máš, neboj se jich, nebo Hospodin Bůh tvůj s tebou jest, kterýž tě vyvedl z země Egyptské.'),
(1551620,54,5,20,2,'A když byste se již potýkati měli, přistoupí kněz, a mluviti bude k lidu,'),
(1551621,54,5,20,3,'A dí jim: Slyš, Izraeli, vy jdete dnes k boji proti nepřátelům svým, nebudiž strašlivé srdce vaše, nebojte se a nestrachujte, ani se jich lekejte.'),
(1551622,54,5,20,4,'Nebo Hospodin Bůh váš, kterýž jde s vámi, bojovati bude za vás proti nepřátelům vašim, aby zachoval vás.'),
(1551623,54,5,20,5,'Potom mluviti budou hejtmané k lidu, řkouce: Jest-li kdo z vás, ješto vystavěl dům nový, a ještě nepočal bydliti v něm, odejdi a navrať se do domu svého, aby nezahynul v bitvě, a někdo jiný aby nezačal bydliti v něm.'),
(1551624,54,5,20,6,'A kdo jest, ješto štípil vinici, a ještě nepřišla k obecnému užívání, odejdi a navrať se k domu svému, aby snad nezahynul v bitvě, aby někdo jiný k obecnému užívání nepřivedl jí.'),
(1551625,54,5,20,7,'A kdo jest, ješto by měl zasnoubenou manželku, a ještě by jí nepojal, odejdi a navrať se do domu svého, aby neumřel v boji, a někdo jiný nevzal jí.'),
(1551626,54,5,20,8,'Přidadí i toto hejtmané, mluvíce k lidu, a řeknou: Kdo jest bázlivý a lekavého srdce, odejdi a navrať se do domu svého, aby nezemdlil srdce bratří svých, jako jest srdce jeho.'),
(1551627,54,5,20,9,'A když přestanou hejtmané mluviti k lidu, tedy představí lidu vůdce houfů.'),
(1551628,54,5,20,10,'Když přitáhneš k některému městu, abys ho dobýval, podáš jemu pokoje.'),
(1551629,54,5,20,11,'Jestliže pokoj sobě podaný přijmou a otevrou tobě, všecken lid, kterýž by nalezen byl v něm, pod plat uvedeni jsouce, tobě sloužiti budou.'),
(1551630,54,5,20,12,'Pakli by v pokoj s tebou nevešli, ale bojovali proti tobě, oblehneš je;'),
(1551631,54,5,20,13,'A když by je Hospodin Bůh tvůj dal v ruku tvou, tedy zbiješ v něm ostrostí meče všecky pohlaví mužského.'),
(1551632,54,5,20,14,'Ženy pak, dítky a hovada, i cožkoli bylo by v městě, všecky kořisti jeho rozbituješ sobě, a užívati budeš kořistí nepřátel svých, kteréž by dal tobě Hospodin Bůh tvůj.'),
(1551633,54,5,20,15,'Tak učiníš všechněm městům daleko vzdáleným od tebe, kteráž nejsou z měst národů těchto.'),
(1551634,54,5,20,16,'Z měst pak lidu toho, kterýž Hospodin Bůh tvůj dává tobě v dědictví, žádné duše živiti nebudeš,'),
(1551635,54,5,20,17,'Ale dokonce vyhladíš je: Hetea, Amorea, Kananea, Ferezea, Hevea a Jebuzea, jakož přikázal tobě Hospodin Bůh tvůj,'),
(1551636,54,5,20,18,'Aby vás neučili činiti vedlé všech ohavností svých, kteréž činí bohům svým, i hřešili byste proti Hospodinu Bohu svému.'),
(1551637,54,5,20,19,'Když oblehneš město některé, za dlouhý čas dobývaje ho, abys je vzal, nezkazíš stromů jeho, sekerou je vytínaje, nebo z nich ovoce jísti budeš; protož jich nevysekáš, (nebo potrava člověka jest strom polní), chtěje užívati jich k obraně své.'),
(1551638,54,5,20,20,'A však stromoví, kteréž znáš, že nenese ovoce ku pokrmu, pohubíš a posekáš, a vzděláš ohrady proti městu tomu, kteréž s tebou bojuje, dokudž ho sobě nepodmaníš.'),
(1551639,54,5,21,1,'Když by nalezen byl zabitý (v zemi, kterouž Hospodin Bůh tvůj dává tobě, abys dědičně vládl jí), ležící na poli, a nebylo by vědíno, kdo by ho zabil,'),
(1551640,54,5,21,2,'Tedy vyjdou starší tvoji a soudcové tvoji, a měřiti budou k městům, kteráž jsou vůkol toho zabitého.'),
(1551641,54,5,21,3,'A když nalezeno bude město nejbližší toho zabitého, tedy vezmou starší města toho jalovici z stáda, kteréž ještě nebylo užíváno, a kteráž netáhla ve jhu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551642,54,5,21,4,'I uvedou starší toho města jalovici tu do údolí pustého, kteréž nikdy nebylo děláno aneb oseto, a setnou šíji jalovice v tom údolí.'),
(1551643,54,5,21,5,'Potom přistoupí kněží synové Léví; (nebo je Hospodin Bůh tvůj vyvolil, aby přisluhovali jemu, a požehnání dávali ve jménu Hospodinovu, vedlé jejichž výpovědi stane všeliká rozepře a každá rána.)'),
(1551644,54,5,21,6,'Všickni také starší toho města, kteříž jsou nejbližší toho zabitého, umyjí ruce své nad jalovicí sťatou v tom údolí,'),
(1551645,54,5,21,7,'A osvědčovati budou, řkouce: Nevylilyť jsou ruce naše krve té, aniž oči naše viděly vražedlníka.'),
(1551646,54,5,21,8,'Očisť lid svůj Izraelský, kterýž jsi vykoupil, Hospodine, a nepřičítej krve nevinné lidu svého Izraelskému. I bude sňata s nich vina té krve.'),
(1551647,54,5,21,9,'Ty pak odejmeš krev nevinnou z prostředku svého, když učiníš, což pravého jest před očima Hospodinovýma.'),
(1551648,54,5,21,10,'Když bys vytáhl na vojnu proti nepřátelům svým, a dal by je Hospodin Bůh tvůj v ruce tvé, a zajal bys z nich mnohé;'),
(1551649,54,5,21,11,'Uzříš-li mezi zajatými ženu krásného oblíčeje, a zamiluješ ji, tak abys ji sobě vzal za manželku:'),
(1551650,54,5,21,12,'Uvedeš ji do domu svého, i oholí sobě hlavu, a obřeže nehty své;'),
(1551651,54,5,21,13,'A složíc roucho své s sebe, v kterémž jest jata, zůstane v domě tvém, a plakati bude otce svého i matky své za celý měsíc; a potom vejdeš k ní, a budeš její manžel, a ona bude manželka tvá.'),
(1551652,54,5,21,14,'Pakliť by se nelíbila, tedy propustíš ji svobodnou; ale nikoli neprodávej jí za peníze, ani nekupč jí, poněvadž jsi jí ponížil.'),
(1551653,54,5,21,15,'Měl-li by kdo dvě ženy, jednu v milosti a druhou v nenávisti, a zplodily by mu syny, milá i nemilá, a byl-li by syn prvorozený nemilé:'),
(1551654,54,5,21,16,'Tedy když dědice ustavovati bude nad tím, což by měl, nebude moci dáti práva prvorozenství synu milé před synem prvorozeným nemilé,'),
(1551655,54,5,21,17,'Ale prvorozeného syna nemilé při prvorozenství zůstaví, a dá jemu dva díly ze všeho, což by měl; nebo on jest počátek síly jeho, jeho jest právo prvorozenství.'),
(1551656,54,5,21,18,'Měl-li by kdo syna zpurného a protivného, ješto by neposlouchal hlasu otce svého a hlasu matky své, a jsa trestán, neuposlechl by jich:'),
(1551657,54,5,21,19,'Tedy vezmouce ho otec i matka jeho, vyvedou jej k starším města svého, k bráně místa přebývání svého,'),
(1551658,54,5,21,20,'A řeknou starším města svého: Syn náš tento, jsa zpurný a protivný, neposlouchá hlasu našeho, žráč a opilec jest.'),
(1551659,54,5,21,21,'Tehdy všickni lidé města toho uházejí jej kamením a umřeť; a tak odejmeš zlé z prostředku svého, a všecken Izrael uslyšíce, báti se budou.'),
(1551660,54,5,21,22,'Když by kdo zhřešil, že by hoden byl smrti, a byl by odsouzen k ní a pověsil bys ho na dřevě:'),
(1551661,54,5,21,23,'Nezůstane přes noc tělo jeho na dřevě, ale hned v ten den pochováš jej, nebo zlořečený jest před Bohem pověšený; protož nepoškvrňuj země své, kterouž Hospodin Bůh tvůj dává tobě v dědictví.'),
(1551662,54,5,22,1,'Jestliže bys uzřel vola aneb dobytče bratra svého, an bloudí, nepomineš jich, ale přivedeš je až k bratru svému.'),
(1551663,54,5,22,2,'Byť pak nebyl blízký bratr tvůj a neznal bys ho, uvedeš je však do domu svého, a bude u tebe, dokudž by se po něm neptal bratr tvůj, a navrátíš mu je.'),
(1551664,54,5,22,3,'Tolikéž učiníš s oslem jeho, s oděvem jeho, také i se všelikou věcí ztracenou bratra svého, kteráž by mu zhynula; když bys ji nalezl, nepomineš jí.'),
(1551665,54,5,22,4,'Vida osla bratra svého aneb vola jeho pod břemenem ležící na cestě, nepomineš jich, ale i hned ho s ním pozdvihneš.'),
(1551666,54,5,22,5,'Žena nebude nositi oděvu mužského, aniž se obláčeti bude muž v roucho ženské, nebo ohavnost před Hospodinem Bohem tvým jest, kdožkoli činí to.'),
(1551667,54,5,22,6,'Když bys našel hnízdo ptačí před sebou na cestě, na jakémkoli stromu aneb na zemi, s mladými neb vejci, a matka seděla by na mladých aneb na vejcích: nevezmeš matky s mladými,'),
(1551668,54,5,22,7,'Ale hned pustíš matku a mladé vezmeš sobě, aby tobě dobře bylo, a abys prodlil dnů svých.'),
(1551669,54,5,22,8,'Když bys stavěl dům nový, udělej zabradla vůkol střechy své, abys neuvedl viny krve na dům svůj, když by kdo upadl s něho.'),
(1551670,54,5,22,9,'Neposeješ vinice své směsicí rozličného semene, aby nebyl poškvrněn užitek semene, kteréž jsi vsel, i ovoce vinice.'),
(1551671,54,5,22,10,'Nebudeš orati volem a oslem spolu.'),
(1551672,54,5,22,11,'Neoblečeš roucha z rozdílných věcí, z vlny a lnu setkaného.'),
(1551673,54,5,22,12,'Prýmy zděláš sobě na čtyřech rozích oděvu svého, jímž se odíváš.'),
(1551674,54,5,22,13,'Když by pojal někdo ženu, a všel by k ní, a potom měl by ji v nenávisti,'),
(1551675,54,5,22,14,'A dal by příčinu k řečem o ní, v zlou pověst ji obláčeje a mluvě: Ženu tuto vzal jsem, a všed k ní, nenalezl jsem jí pannou:'),
(1551676,54,5,22,15,'Tedy otec děvečky a matka její vezmouce přinesou znamení panenství děvečky k starším města svého k bráně.'),
(1551677,54,5,22,16,'A dí otec děvečky k starším: Dceru svou dal jsem muži tomuto za manželku, kterýž ji v nenávisti má.'),
(1551678,54,5,22,17,'A hle, sám příčinu dal řečem o ní, mluvě: Nenalezl jsem při dceři tvé panenství, a teď hle, znamení panenství dcery mé. I roztáhnou roucho to před staršími města.'),
(1551679,54,5,22,18,'Tedy starší města toho jmou muže a trestati ho budou,'),
(1551680,54,5,22,19,'A uloží jemu pokutu sto lotů stříbra, kteréž dají otci děvečky, proto že vynesl zlou pověst proti panně Izraelské. I bude ji míti za manželku, kteréž nebude moci propustiti po všecky dny své.'),
(1551681,54,5,22,20,'Jináč byla-li by pravá žaloba ta, a nebylo by nalezeno panenství při děvečce:'),
(1551682,54,5,22,21,'Tedy vyvedou děvečku ke dveřím otce jejího, a uházejí ji lidé města toho kamením, a umře; nebo dopustila se nešlechetnosti v Izraeli, smilnivši v domě otce svého. Tak odejmeš zlé z prostředku sebe.'),
(1551683,54,5,22,22,'Kdyby kdo postižen byl, že obýval s ženou manželkou cizí, tedy umrou oni oba dva, muž, kterýž obýval s tou ženou, i žena také; i odejmeš zlé z Izraele.'),
(1551684,54,5,22,23,'Byla-li by děvečka panna zasnoubená muži, a nalezna ji někdo v městě, obýval by s ní:'),
(1551685,54,5,22,24,'Vyvedete oba dva k bráně města toho, a uházíte je kamením, a umrou, děvečka, proto že nekřičela, jsuci v městě, a muž proto, že ponížil ženy bližního svého; a odejmeš zlé z prostředku svého.'),
(1551686,54,5,22,25,'Pakli na poli nalezl by muž děvečku zasnoubenou, a násilí jí učině, obýval by s ní: smrtí umře muž ten sám,'),
(1551687,54,5,22,26,'Děvečce pak nic neučiníš. Nedopustila se hříchu hodného smrti; nebo jakož povstává někdo proti bližnímu svému a morduje život jeho, tak i při této věci.'),
(1551688,54,5,22,27,'Na poli zajisté nalezl ji; křičela děvečka zasnoubená, a žádný tu nebyl, kdo by ji vysvobodil.'),
(1551689,54,5,22,28,'Jestliže by nalezl někdo děvečku pannu, kteráž by zasnoubena nebyla, a vezma ji, obýval by s ní, a byli by postiženi:'),
(1551690,54,5,22,29,'Tedy dá muž ten, kterýž by obýval s ní, otci děvečky padesáte stříbrných, a bude jeho manželka, protože ponížil jí; nebude moci jí propustiti po všecky dny své.'),
(1551691,54,5,22,30,'Nevezme žádný manželky otce svého, a neodkryje podolka otce svého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551692,54,5,23,1,'Nevejde do shromáždění Hospodinova, kdož by měl stlučené aneb odňaté lůno.'),
(1551693,54,5,23,2,'Aniž vejde do shromáždění Hospodinova syn postranní; také i desáté koleno jeho nevejde do shromáždění Hospodinova.'),
(1551694,54,5,23,3,'Ammonitský tolikéž ani Moábský nevejde do shromáždění Hospodinova, ani desáté koleno jejich nevejde do shromáždění Hospodinova až na věky.'),
(1551695,54,5,23,4,'Proto že proti vám nevyšli s chlebem a s vodou na cestě, když jste šli z Egypta, a že ze mzdy najal proti tobě Baláma, syna Beor, z Petor Mezopotamie Syrské, aby zlořečil tobě:'),
(1551696,54,5,23,5,'(Ačkoli nechtěl Hospodin Bůh tvůj slyšeti Baláma, ale obrátil Hospodin Bůh tvůj tobě zlořečení v požehnání, nebo miloval tebe Hospodin Bůh tvůj.)'),
(1551697,54,5,23,6,'Nebudeš hledati pokoje jejich ani dobrého jejich po všecky dny své na věky.'),
(1551698,54,5,23,7,'Nebudeš míti v ohavnosti Idumejského, nebo bratr tvůj jest, aniž Egyptského v ohavnosti míti budeš, nebo jsi byl pohostinu v zemi jeho.'),
(1551699,54,5,23,8,'Synové, kteříž se jim zrodí v třetím kolenu, vejdou do shromáždění Hospodinova.'),
(1551700,54,5,23,9,'Když bys vytáhl vojensky proti nepřátelům svým, vystříhej se od všeliké zlé věci.'),
(1551701,54,5,23,10,'Bude-li mezi vámi kdo, ješto by poškvrněn byl příhodou noční, vyjde ven z stanů, a nevejde do nich;'),
(1551702,54,5,23,11,'Ale když bude k večerou, umyje se vodou, a po západu slunce vejde do stanů.'),
(1551703,54,5,23,12,'Také místo budeš míti vně za stany, abys tam chodíval ven;'),
(1551704,54,5,23,13,'A budeš míti kolík mezi jinými nástroji svými, a když bys chtěl sednouti vně, vykopáš jím důlek, a obrátě se, zahrabeš nečistotu svou.'),
(1551705,54,5,23,14,'Nebo Hospodin Bůh tvůj chodí u prostřed stanů tvých, aby tě vysvobodil, a dal tobě nepřátely tvé; protož ať jest příbytek tvůj svatý, tak aby nespatřil při tobě mrzkosti nějaké, pročež by se odvrátil od tebe.'),
(1551706,54,5,23,15,'Nevydáš služebníka pánu jeho, kterýž k tobě utekl od pána svého.'),
(1551707,54,5,23,16,'S tebou bydliti bude u prostřed tebe na místě, kteréž by vyvolil v některém městě tvém, kdežkoli jemu se líbiti bude; nebudeš ho mocí utiskati.'),
(1551708,54,5,23,17,'Nebude nevěstka žádná z dcer Izraelských, ani nečistý smilník z synů Izraelských.'),
(1551709,54,5,23,18,'Nepřineseš mzdy nevěstky, a mzdy psa do domu Hospodina Boha svého z jakéhokoli slibu, nebo to obé ohavnost jest Hospodinu Bohu tvému.'),
(1551710,54,5,23,19,'Nedáš na lichvu bratru svému ani peněz, ani pokrmu, ani jakékoli věci, kteráž se dává na lichvu.'),
(1551711,54,5,23,20,'Cizímu půjčíš na lichvu, ale bratru svému nedáš na lichvu, aby požehnal tobě Hospodin Bůh tvůj při všech věcech, k kterýmž bys vztáhl ruku svou v zemi, do níž vejdeš, abys dědičně obdržel ji.'),
(1551712,54,5,23,21,'Když bys učinil slib Hospodinu Bohu svému, neprodlévej splniti ho; nebo konečně toho vyhledávati bude Hospodin Bůh tvůj od tebe, a byl by na tobě hřích.'),
(1551713,54,5,23,22,'Pakli nebudeš slibovati, nebude na tobě hříchu.'),
(1551714,54,5,23,23,'Což jednou vyšlo z úst tvých, to splníš, a učiníš, jakž jsi slíbil Hospodinu Bohu svému dobrovolně, což jsi vynesl ústy svými.'),
(1551715,54,5,23,24,'Všel-li bys do vinice bližního svého, jísti budeš hrozny podlé žádosti své do sytosti své, ale do nádoby své nevložíš.'),
(1551716,54,5,23,25,'Všel-li bys do obilí bližního svého, natrháš sobě klasů rukou svou, ale srpem nebudeš žíti obilí bližního svého.'),
(1551717,54,5,24,1,'Pojal-li by muž ženu a byl by manželem jejím, přihodilo by se pak, že by nenašla milosti před očima jeho pro nějakou mrzkost, kterouž by nalezl na ní, i napsal by jí lístek zapuzení a dal v ruku její, a vyhnal by ji z domu svého;'),
(1551718,54,5,24,2,'A vyjduci z domu jeho, odešla by a vdala se za druhého muže;'),
(1551719,54,5,24,3,'A ten také muž poslední v nenávisti maje ji, napsal by lístek zapuzení a dal v ruce její, a vyhnal by ji z domu svého; aneb umřel by muž její poslední, kterýž vzal ji sobě za manželku:'),
(1551720,54,5,24,4,'Nebude moci manžel její první, kterýž ji vyhnal, zase ji vzíti sobě za manželku, když již příčinou jeho poškvrněna jest; nebo ohavnost jest před Hospodinem. Protož nedopouštěj hřešiti lidu země, kterouž Hospodin Bůh tvůj dává tobě v dědictví.'),
(1551721,54,5,24,5,'Když by někdo v nově pojal ženu, nevyjde k boji, aniž na něj vzkládána bude jaká obecní práce; svoboden bude v domě svém za jeden rok, a veseliti se bude s manželkou svou, kterouž pojal.'),
(1551722,54,5,24,6,'Žádný nevezme v zástavě svrchního i spodního žernovu, nebo takový bral by duši v základu.'),
(1551723,54,5,24,7,'Byl-li by postižen někdo, že ukradl člověka z bratří svých synů Izraelských, a k zisku by sobě jej přivedl aneb prodal jej: umře zloděj ten, a odejmeš zlé z prostředku svého.'),
(1551724,54,5,24,8,'Šetř se při ráně malomocenství, abys ostříhal pilně a činil všecko, jakž učiti budou vás kněží Levítové; jakož přikázal jsem jim, ostříhati toho budete a tak činiti.'),
(1551725,54,5,24,9,'Pomni na ty věci, které učinil Hospodin Bůh tvůj Marii na cestě, když jste vyšli z Egypta.'),
(1551726,54,5,24,10,'Půjčil-li bys bližnímu svému něčeho, nevejdeš do domu jeho, abys vzal něco v zástavě od něho.'),
(1551727,54,5,24,11,'Ale vně staneš, a člověk, jemuž jsi půjčil, vynese tobě základ svůj ven.'),
(1551728,54,5,24,12,'Jestliže by pak byl člověk chudý, nebudeš spáti s základem jeho.'),
(1551729,54,5,24,13,'Bez prodlévání navrátíš jemu zastavenou věc jeho při západu slunce, aby leže v šatech svých, dobrořečil tobě, a bude to za spravedlnost tobě před Hospodinem Bohem tvým.'),
(1551730,54,5,24,14,'Neutiskneš nájemníka chudého a nuzného, tak z bratří svých jako z příchozích, kteříž jsou v zemi tvé v branách tvých.'),
(1551731,54,5,24,15,'Na každý den dáš jemu mzdu jeho, prvé nežli by slunce zapadlo; nebo chudý jest, a tím se živí, aby neúpěl proti tobě k Hospodinu, a byl by na tobě hřích.'),
(1551732,54,5,24,16,'Nebudou na hrdle trestáni otcové za syny, ani synové trestáni budou na hrdle za otce, jeden každý za svůj hřích umře.'),
(1551733,54,5,24,17,'Nepřevrátíš soudu příchozímu neb sirotku, ani vezmeš v základu roucha vdovy,'),
(1551734,54,5,24,18,'Ale pamatuj, že jsi byl služebníkem v Egyptě, a že tě vykoupil Hospodin Bůh tvůj odtud; protož přikazujiť, abys činil toto.'),
(1551735,54,5,24,19,'Když bys žal obilí své na poli svém, a zapomenul bys tam některého snopu, nenavrátíš se, abys jej vzal; příchozímu, sirotku a vdově to bude, aby požehnal tobě Hospodin Bůh tvůj při všelikém díle rukou tvých.'),
(1551736,54,5,24,20,'Když bys třásl olivy své, nebudeš shledávati po každé ratolesti za sebou; příchozímu, sirotku a vdově to zůstane.'),
(1551737,54,5,24,21,'Když bys sbíral víno na vinici své, nebudeš paběrovati jahodek za sebou; příchozímu, sirotku a vdově to bude.'),
(1551738,54,5,24,22,'Pamatuj, že jsi byl služebníkem v zemi Egyptské; protož přikazujiť, abys to činil.'),
(1551739,54,5,25,1,'Vznikla-li by jaká nesnáz mezi některými, a přistoupili by k soudu, aby je rozsoudili, tedy spravedlivého ospravedlní, a nepravého odsoudí.'),
(1551740,54,5,25,2,'Bude-li pak hoden mrskání nepravý, tedy káže ho položiti soudce a mrskati před sebou, vedlé nepravosti jeho v jistý počet ran.'),
(1551741,54,5,25,3,'Čtyřidcetikrát káže ho mrštiti, aniž přidá více, aby, jestliže by jej nadto mrskal ranami mnohými, nebyl příliš zlehčen bratr tvůj před očima tvýma.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551742,54,5,25,4,'Nezavížeš úst vola mlátícího.'),
(1551743,54,5,25,5,'Když by bratří spolu bydlili, a umřel by jeden z nich, nemaje syna, nevdá se ven žena toho mrtvého za jiného muže; bratr jeho vejde k ní, a vezme ji sobě za manželku, a právem švagrovství přižení se k ní.'),
(1551744,54,5,25,6,'Prvorozený pak, kteréhož by porodila, nazván bude jménem bratra jeho mrtvého, aby nebylo vyhlazeno jméno jeho z Izraele.'),
(1551745,54,5,25,7,'Nechtěl-li by pak muž ten pojíti příbuzné své, tedy přijde příbuzná jeho k bráně před starší a řekne: Nechce příbuzný můj vzbuditi bratru svému jména v Izraeli, a nechce podlé práva švagrovství pojíti mne.'),
(1551746,54,5,25,8,'Tedy povolají ho starší města toho, a mluviti budou s ním; a stoje, řekl-li by: Nechci jí pojíti,'),
(1551747,54,5,25,9,'Přistoupí příbuzná jeho k němu před staršími, a szuje střevíc jeho s nohy jeho, a pline mu na tvář a odpoví, řkuci: Tak se má státi muži tomu, kterýž by nechtěl vzdělati domu bratra svého.'),
(1551748,54,5,25,10,'I bude nazváno jméno jeho v Izraeli: Dům bosého.'),
(1551749,54,5,25,11,'Když by se svadili někteří spolu jeden s druhým, a přistoupila by žena jednoho, aby vysvobodila muže svého z ruky bijícího jej, i vztáhla by ruku svou a uchopila by ho za lůno:'),
(1551750,54,5,25,12,'Tedy utneš ruku její, neslituje se nad ní oko tvé.'),
(1551751,54,5,25,13,'Nebudeš míti v pytlíku svém nejednostejného kamene, většího a menšího.'),
(1551752,54,5,25,14,'Aniž budeš míti v domě svém nejednostejného korce, většího a menšího.'),
(1551753,54,5,25,15,'Váhu celou a spravedlivou míti budeš, též míru celou a spravedlivou budeš míti, aby se prodlili dnové tvoji v zemi, kterouž Hospodin Bůh tvůj dává tobě.'),
(1551754,54,5,25,16,'Nebo v ohavnosti jest Hospodinu Bohu tvému, kdožkoli činí ty věci, všeliký činící nepravost.'),
(1551755,54,5,25,17,'Pamatuj na to, coť učinil Amalech na cestě, když jste šli z Egypta:'),
(1551756,54,5,25,18,'Kterak vyšed tobě v cestu, zadní houf tvůj všech mdlých, kteříž šli za tebou, pobil, když jsi ty byl zemdlený a ustalý, a nebál se Boha.'),
(1551757,54,5,25,19,'Protož když byl Hospodin Bůh tvůj dal tobě odpočinutí ode všech nepřátel tvých vůkol v zemi, kterouž Hospodin Bůh tvůj dává tobě v dědictví, abys dědičně obdržel ji, vyhladíš památku Amalecha pod nebem; nezapomínejž na to.'),
(1551758,54,5,26,1,'Když pak vejdeš do země, kterouž Hospodin Bůh tvůj dává tobě v dědictví, a opanuje ji, bydliti v ní budeš:'),
(1551759,54,5,26,2,'Vezmeš prvotin všeho ovoce země té, kteréž obětovati budeš z země své, již Hospodin Bůh tvůj dává tobě, a vlože do koše, půjdeš k místu, kteréž by Hospodin Bůh tvůj k přebývání tam jménu svému vyvolil.'),
(1551760,54,5,26,3,'A přijda k knězi, kterýž těch dnů bude, díš jemu: Vyznávám dnes Hospodinu Bohu svému, že jsem všel do země, kterouž s přísahou zaslíbil Hospodin otcům našim, že ji nám dá.'),
(1551761,54,5,26,4,'I vezma kněz z ruky tvé koš, postaví jej před oltářem Hospodina Boha tvého.'),
(1551762,54,5,26,5,'A mluviti budeš před Hospodinem Bohem svým, řka: Syrský chudý otec můj sstoupil do Egypta s nemnohými osobami, a byv tam pohostinu, vzrostl v národ veliký, silný a mnohý.'),
(1551763,54,5,26,6,'A když zle nakládali s námi Egyptští, trápíce nás, a vzkládajíce na nás službu těžkou,'),
(1551764,54,5,26,7,'Volali jsme k Hospodinu Bohu otců našich, a vyslyšev Hospodin hlas náš, popatřil na trápení naše, práci naši a ssoužení naše.'),
(1551765,54,5,26,8,'I vyvedl nás Hospodin z Egypta v ruce silné a v rameni vztaženém, v strachu velikém, a znameních i zázracích.'),
(1551766,54,5,26,9,'A uvedl nás na toto místo, a dal nám zemi tuto oplývající mlékem a strdí.'),
(1551767,54,5,26,10,'Protož nyní, hle, přinesl jsem prvotiny úrod země, kterouž jsi mi dal, ó Hospodine. I necháš toho před Hospodinem Bohem svým, a pokloníš se před ním.'),
(1551768,54,5,26,11,'I veseliti se budeš ve všech dobrých věcech, kteréž by tobě dal Hospodin Bůh tvůj, i domu tvému, ty i Levíta i příchozí, kterýž jest u prostřed tebe.'),
(1551769,54,5,26,12,'Když bys pak vyplnil všecky desátky ze všech úrod svých léta třetího, jenž rok desátků jest, a dal bys Levítovi, příchozímu, sirotku i vdově, a jedli by v branách tvých a nasyceni byli:'),
(1551770,54,5,26,13,'Tedy díš před Hospodinem Bohem svým: Vynesl jsem, což posvěceného bylo, z domu svého, a dal jsem také Levítovi, příchozímu, sirotku a vdově vedlé všelikého přikázaní tvého, kteréž jsi mi přikázal; nepřestoupil jsem žádného z přikázaní tvých, aniž jsem zapomenul na ně.'),
(1551771,54,5,26,14,'Nejedl jsem v zámutku svém z toho, a neujal jsem z toho k věci obecné, aniž jsem dal něco odtud ku pohřbu; poslechl jsem hlasu Hospodina Boha svého, učinil jsem podlé všeho, což jsi mi přikázal.'),
(1551772,54,5,26,15,'Popatřiž z příbytku svatého svého s nebe, a požehnej lidu svému Izraelskému a zemi, kterouž jsi dal nám, jakož jsi s přísahou zaslíbil otcům našim, zemi oplývající mlékem a strdí.'),
(1551773,54,5,26,16,'Dnes Hospodin Bůh tvůj přikazuje tobě, abys ostříhal ustanovení těchto a soudů; ostříhejž tedy a čiň je z celého srdce svého a ze vší duše své.'),
(1551774,54,5,26,17,'Dnes i ty připověděls se k Hospodinu, že jej budeš míti za Boha, a choditi budeš po cestách jeho, a ostříhati ustanovení jeho, a přikázaní i soudů jeho, a poslouchati hlasu jeho.'),
(1551775,54,5,26,18,'Hospodin také připověděl se k tobě dnes, že tě bude míti za lid zvláštní, jakož mluvil tobě, abys ostříhal všech příkázaní jeho,'),
(1551776,54,5,26,19,'A že tě vyvýší nade všecky národy, kteréž učinil, abys byl vzácnější, slovoutnější a slavnější nad ně, a tak lid svatý Hospodinu Bohu svému, jakož jest mluvil.'),
(1551777,54,5,27,1,'I přikázal Mojžíš a starší Izraelští lidu, řkouce: Ostříhejž každého přikázaní, kteréž já přikazuji vám dnes.'),
(1551778,54,5,27,2,'A když přejdeš přes Jordán do země, kterouž Hospodin Bůh tvůj dává tobě, vyzdvihneš sobě kameny veliké, a obvržeš je vápnem.'),
(1551779,54,5,27,3,'A napíšeš na nich všecka slova zákona tohoto, když přejdeš, abys všel do země, kterouž Hospodin Bůh tvůj dává tobě, do země oplývající mlékem a strdí, jakož jest mluvil Hospodin Bůh otců tvých tobě.'),
(1551780,54,5,27,4,'Když tedy přejdeš Jordán a vyzdvihneš ty kameny, kteréž já přikazuji vám dnes, na hoře Hébal, a obvržeš je vápnem,'),
(1551781,54,5,27,5,'A vzděláš tam oltář Hospodinu Bohu svému: oltář z kamenů, jichž nebudeš tesati železem,'),
(1551782,54,5,27,6,'Z kamení celého vzděláš oltář Hospodinu Bohu svému, abys na něm obětoval oběti zápalné Hospodinu Bohu svému.'),
(1551783,54,5,27,7,'Obětovati budeš i oběti pokojné, a jísti tu a veseliti se před Hospodinem Bohem svým.'),
(1551784,54,5,27,8,'Napíšeš pak na těch kameních všecka slova zákona toho dobře a zřetelně.'),
(1551785,54,5,27,9,'I mluvil Mojžíš a kněží Levítští ke všemu Izraelovi, řkouce: Pozoruj a slyš, Izraeli, dnes učiněn jsi lidem Hospodina Boha svého.'),
(1551786,54,5,27,10,'Protož poslouchej hlasu Hospodina Boha svého, a zachovávej přikázaní jeho i ustanovení jeho, kteráž já tobě dnes přikazuji.'),
(1551787,54,5,27,11,'I přikázal Mojžíš v ten den lidu, řka:'),
(1551788,54,5,27,12,'Tito stanou, aby dobrořečili lidu na hoře Garizim, když byste přešli Jordán: Simeon, Léví, Juda, Izachar, Jozef a Beniamin.'),
(1551789,54,5,27,13,'Tito pak stanou, aby zlořečili na hoře Hébal: Ruben, Gád, Asser, Zabulon, Dan a Neftalím.'),
(1551790,54,5,27,14,'I budou osvědčovati Levítové, a řeknou ke všechněm mužům Izraelským vysokým hlasem:'),
(1551791,54,5,27,15,'Zlořečený člověk, kterýž by udělal rytinu aneb věc slitou, ohavnost Hospodinu, dílo rukou řemeslníka, by ji pak i do skrýše odložil. I odpoví všecken lid a řekne: Amen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551792,54,5,27,16,'Zlořečený, kdož sobě zlehčuje otce svého a matku svou; i řekne všecken lid: Amen.'),
(1551793,54,5,27,17,'Zlořečený, kdož přenáší mezník bližního svého; i řekne všecken lid: Amen.'),
(1551794,54,5,27,18,'Zlořečený, kdož zavodí slepého, aby bloudil po cestě; i řekne všecken lid: Amen.'),
(1551795,54,5,27,19,'Zlořečený, kdož převrací spravedlnost příchozího, sirotka a vdovy; a odpoví všecken lid: Amen.'),
(1551796,54,5,27,20,'Zlořečený, kdož by obýval s manželkou otce svého, nebo odkryl podolek otce svého; i řekne všecken lid: Amen.'),
(1551797,54,5,27,21,'Zlořečený, kdož by obýval s kterýmkoli hovadem; i dí všecken lid: Amen.'),
(1551798,54,5,27,22,'Zlořečený, kdož by obýval s sestrou svou, dcerou otce svého, aneb dcerou matky své; i řekne všecken lid: Amen.'),
(1551799,54,5,27,23,'Zlořečený, kdož by obýval s svegruší svou; i odpoví všecken lid: Amen.'),
(1551800,54,5,27,24,'Zlořečený, kdož by zbil bližního svého tajně; i řekne všecken lid: Amen.'),
(1551801,54,5,27,25,'Zlořečený, kdož by vzal dary, aby zabil člověka nevinného; i dí všecken lid: Amen.'),
(1551802,54,5,27,26,'Zlořečený, kdož by nezůstal v řečech zákona tohoto a nečinil jich; a řekne všecken lid: Amen.'),
(1551803,54,5,28,1,'Jestliže pak opravdově poslušen budeš hlasu Hospodina Boha svého, ostříhaje a čině všecka přikázaní jeho, kteráž já dnes přikazuji tobě, vyvýší tě Hospodin Bůh tvůj nade všecky národy země.'),
(1551804,54,5,28,2,'A přijdou na tě všecka požehnání tato, a vyplní se při tobě, když jen poslušen budeš hlasu Hospodina Boha svého.'),
(1551805,54,5,28,3,'Požehnaný budeš v městě, požehnaný i na poli.'),
(1551806,54,5,28,4,'Požehnaný plod života tvého, úrody země tvé, i plod dobytka tvého, prvorozené skotů tvých i stáda bravů tvých.'),
(1551807,54,5,28,5,'Požehnaný koš tvůj i díže tvá.'),
(1551808,54,5,28,6,'Požehnaný budeš vcházeje, požehnaný i vycházeje.'),
(1551809,54,5,28,7,'A učiní Hospodin, že nepřátelé tvoji, kteříž by povstali proti tobě, poraženi budou před tebou; jednou cestou vytáhnou proti tobě, a sedmi cestami před tebou utíkati budou.'),
(1551810,54,5,28,8,'Přikáže Hospodin požehnání svému, aby s tebou bylo v špižírnách tvých a při všem, k čemu bys koli přičinil ruku svou, a požehná tobě v zemi, kterouž Hospodin Bůh tvůj dává tobě.'),
(1551811,54,5,28,9,'Vystaví tě sobě Hospodin za lid svatý, jakož zapřisáhl tobě, když ostříhati budeš přikázaní Hospodina Boha svého, a choditi po cestách jeho.'),
(1551812,54,5,28,10,'I uzří všickni národové země, že jméno Hospodinovo vzýváno jest nad tebou, a budou se báti tebe.'),
(1551813,54,5,28,11,'Učiní také Hospodin, že hojnost míti budeš všeho dobrého, plodu života svého, i plodu dobytků svých, i úrod zemských v zemi, kterouž s přísahou zaslíbil otcům tvým, že ji tobě dá.'),
(1551814,54,5,28,12,'Otevře Hospodin tobě poklad svůj výborný, nebe, aby vydalo déšť zemi tvé časem svým, a požehná všelikému dílu ruky tvé, tak že mnohým národům půjčovati budeš, sám pak nic nevypůjčíš.'),
(1551815,54,5,28,13,'I ustanoví tě Hospodin za hlavu a ne za ocas, a budeš vždycky vyšší, a nikdy nižší, když poslouchati budeš přikázaní Hospodina Boha svého, kteráž já dnes tobě přikazuji, abys ostříhal a činil je.'),
(1551816,54,5,28,14,'A neuchýlíš se od žádného slova, kteráž já dnes přikazuji tobě, ani na pravo ani na levo, odcházeje po bozích cizích, abys jim sloužil.'),
(1551817,54,5,28,15,'Jestliže pak hlasu Hospodina Boha svého poslouchati, a všech přikázaní a ustanovení jeho, kteráž já dnes přikazuji tobě, ostříhati a činiti nebudeš, přijdou na tě všecka zlořečenství tato a postihnou tě.'),
(1551818,54,5,28,16,'Zlořečený budeš v městě, zlořečený i na poli.'),
(1551819,54,5,28,17,'Zlořečený koš tvůj, a zlořečená díže tvá.'),
(1551820,54,5,28,18,'Zlořečený plod života tvého i úrody země tvé, prvorozené skotů tvých i stáda bravů tvých.'),
(1551821,54,5,28,19,'Zlořečený budeš vcházeje, zlořečený i vycházeje.'),
(1551822,54,5,28,20,'Pošle Hospodin na tě zlořečení, zkormoucení a bídu při všem, k čemuž bys koli přičinil ruky své a což bys koli dělal, dokudž nebudeš vyhlazen, a nezahyneš v náhle pro zlé skutky tvé, skrze něž jsi opustil mne.'),
(1551823,54,5,28,21,'Dopustí Hospodin, aby se přídržely tebe morní bolesti, až tě i vypléní z země, do níž se béřeš, abys ji dědičně opanoval.'),
(1551824,54,5,28,22,'Bíti tě bude Hospodin souchotinami, zimnicí, pálivostí, horkem, mečem, suchem a rudou, a budou tě stíhati, až tě i zkazí.'),
(1551825,54,5,28,23,'I to nebe, kteréž jest nad hlavou tvou, bude měděné, a země, kteráž jest pod tebou, železná.'),
(1551826,54,5,28,24,'Dá Hospodin zemi tvé místo deště prach a popel, a toť s nebe sstoupí na tě, dokudž bys nebyl vyhlazen.'),
(1551827,54,5,28,25,'Učiní i to Hospodin, že poražen budeš od nepřátel svých; jednou cestou vytáhneš proti nim, a sedmi cestami utíkati budeš od tváři jejich, a musíš se smýkati po všech královstvích země.'),
(1551828,54,5,28,26,'I budou těla vaše mrtvá za pokrm všemu ptactvu nebeskému, a šelmám zemským, a nebude, kdo by je odehnal.'),
(1551829,54,5,28,27,'Raní tě Hospodin vředem Egyptským, neduhy na zadku, prašivinami a svrabem nezhojitelným.'),
(1551830,54,5,28,28,'Raní tě Hospodin pominutím smyslu, slepotou a tupostí srdce,'),
(1551831,54,5,28,29,'Tak že o poledni makati budeš, jako maká slepý ve tmě, a nebudeš míti prospěchu na cestách svých; k tomu také utiskán budeš, a loupen po všecky dny, a nebude, kdo by tě vysvobodil.'),
(1551832,54,5,28,30,'Manželku sobě zasnoubíš, a jiný s ní obývati bude; dům vystavíš, a nebudeš bydliti v něm; vinici štípíš, a sbírati na ní nebudeš.'),
(1551833,54,5,28,31,'Vůl tvůj před tvýma očima zabit bude, a ty jeho jísti nebudeš; osel tvůj uchvácen bude před tváří tvou, anižť se zase navrátí; dobytek tvůj vydán bude nepřátelům tvým, a žádný ho nevysvobodí.'),
(1551834,54,5,28,32,'Synové tvoji a dcery tvé cizímu národu vydáni budou, a oči tvé na to hledíce, umdlívati budou pro ně celého dne, a nebude síly v ruce tvé.'),
(1551835,54,5,28,33,'Úrody země tvé i všecko úsilí tvé sžíře národ, kteréhož ty neznáš, a nebudeš než potlačený a potřený po všecky dny.'),
(1551836,54,5,28,34,'A omámený budeš nad těmi věcmi, kteréž viděti budou oči tvé.'),
(1551837,54,5,28,35,'Raní tě Hospodin vředem nejhorším na kolenou i na lýtkách, tak že se nebudeš moci zhojiti, od spodku nohy tvé až do vrchu hlavy.'),
(1551838,54,5,28,36,'Zavede tě Hospodin i krále tvého, kteréhož ustanovíš nad sebou, do národu, kteréhož jsi ty neznal, ani předkové tvoji, a sloužiti tam budeš bohům cizím, dřevu a kameni.'),
(1551839,54,5,28,37,'A budeš k užasnutí a přísloví i v rozprávku všechněm národům, mezi kteréž zavede tě Hospodin.'),
(1551840,54,5,28,38,'Mnoho semene vyneseš na pole k rozsívání, a málo shromáždíš, nebo sžerou to kobylky.'),
(1551841,54,5,28,39,'Vinice štípíš a dělati je budeš, ale vína píti ani sbírati nebudeš, nebo červ sžíře je.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551842,54,5,28,40,'Olivoví hojnost míti budeš ve všech končinách svých, a však olejem se pomazovati nebudeš, nebo sprchne ovoce s olivy tvé.'),
(1551843,54,5,28,41,'Synů a dcer naplodíš, a nebudeš jich míti, nebo zajati budou.'),
(1551844,54,5,28,42,'Všecko stromoví tvé i úrody země tvé kobylky zkazí.'),
(1551845,54,5,28,43,'Cizozemec, kterýž s tebou přebývá, vzroste nad tebe, ty pak velice ponižovati se musíš.'),
(1551846,54,5,28,44,'On půjčovati bude tobě, a ty nebudeš míti, co bys půjčil jemu; on bude přednější, a ty poslednější.'),
(1551847,54,5,28,45,'A přijdou na tebe všecka zlořečenství tato a stíhati tě budou, a obklíčí tě, až i zahyneš, jestliže bys neuposlechl hlasu Hospodina Boha svého, a neostříhal přikázaní a ustanovení jeho, kteráž přikázal tobě.'),
(1551848,54,5,28,46,'A budou rány tyto znamením a zázrakem na tobě i semeni tvém až na věky,'),
(1551849,54,5,28,47,'Proto že jsi nesloužil Hospodinu Bohu svému s potěšením a veselím srdce, maje hojnost všech věcí.'),
(1551850,54,5,28,48,'A protož nepříteli svému, kteréhož poslal na tebe Hospodin, sloužiti musíš v hladu, žízni, v nahotě a v nedostatku všech věcí; a vloží na šíji tvou jho železné, dokudž tě nesetře.'),
(1551851,54,5,28,49,'Přivede Hospodin na tebe národ z daleka, od nejdalších končin země, jako letí orlice, národ, jehož jazyku nerozumíš,'),
(1551852,54,5,28,50,'Národ nestydatý, kterýž ani starce nebude šanovati, a nad dítětem se neslituje.'),
(1551853,54,5,28,51,'A sžíře plod dobytků tvých i úrody země tvé, dokudž nebudeš vyhlazen; a nezanechá tobě obilí, vína mladého a oleje, prvorozeného z skotů tvých, ani stáda bravů tvých, až tě i vyhladí.'),
(1551854,54,5,28,52,'A oblehne tě ve všech městech tvých, dokudž by nepadly zdi tvé vysoké a pevné, v nichž ty doufáš po vší zemi své; obležen, pravím, budeš ve všech městech svých, po vší zemi své, kterouž Hospodin Bůh tvůj dal tobě,'),
(1551855,54,5,28,53,'Tak že v obležení a ssoužení, jímž ssouží tě nepřítel tvůj, jísti budeš plod života svého, maso synů svých a dcer svých, kteréž by dal tobě Hospodin Bůh tvůj.'),
(1551856,54,5,28,54,'Člověk mezi vámi rozmazaný a v rozkoši schovaný záviděti bude bratru svému, i vlastní ženě své, i ostatním synům svým, kterýchž ještě zanechal,'),
(1551857,54,5,28,55,'Tak že neudělí žádnému z nich masa synů svých, kteréž jísti bude, proto že nezůstalo jemu nic jiného v obležení a v ssoužení, jímž ssouží tě nepřítel tvůj ve všech městech tvých.'),
(1551858,54,5,28,56,'Rozmazaná mezi vámi a v rozkoši schovaná žena, kteráž rozmazaností a rozkoší velikou ledva nohou země se dotkla, vlastnímu muži svému a synu svému i dceři své,'),
(1551859,54,5,28,57,'Také i lůžka svého, kteréž z ní vychází při porodu, ano i synů svých, kteréž zplodí, záviděti bude; nebo jísti je bude tajně pro nedostatek všech věcí v obležení a ssoužení, jímž ssouží tě nepřítel tvůj v městech tvých.'),
(1551860,54,5,28,58,'Nebudeš-li ostříhati a činiti všech slov zákona tohoto, kteráž psána jsou v knize této, abys se bál toho veleslavného a hrozného jména Hospodina Boha svého:'),
(1551861,54,5,28,59,'Rozmnoží ku podivení Hospodin rány tvé, a rány semene tvého, rány veliké a trvánlivé, i nemoci těžké a dlouhé.'),
(1551862,54,5,28,60,'A obrátí na tebe všecky neduhy Egyptské, jichžs se strašil, a přichytí se tebe.'),
(1551863,54,5,28,61,'Všelijaký také neduh a všelikou ránu, kteráž není psána v knize zákona tohoto, uvede Hospodin na tebe, dokudž nebudeš vyhlazen.'),
(1551864,54,5,28,62,'A zůstane vás maličko, ješto vás prvé bylo mnoho, jako hvězd nebeských, proto že jsi neposlouchal hlasu Hospodina Boha svého.'),
(1551865,54,5,28,63,'I stane se, že jakož se veselil Hospodin nad vámi, dobře vám čině a rozmnožuje vás, tak veseliti se bude Hospodin nad vámi, když vás zkazí a vyhladí, a vypléněni budete z země, do kteréž jdete, abyste dědičně vládli jí.'),
(1551866,54,5,28,64,'A rozptýlí tě Hospodin mezi všecky národy, od jednoho konce země až do druhého, a budeš tam sloužiti bohům cizím, kterýchž ty neznáš, ani otcové tvoji, dřevu a kameni.'),
(1551867,54,5,28,65,'A mezi národy těmi neoddechneš, aniž bude míti odpočinutí spodek nohy tvé; tam také dá Hospodin tobě srdce lekavé, a oči blíkavé, a truchlost mysli.'),
(1551868,54,5,28,66,'I bude život tvůj nejistý před tebou, a strašiti se budeš v noci i ve dne, a nikdež nebudeš jist svým životem.'),
(1551869,54,5,28,67,'Ráno díš: Ó by již byl večer! a večer díš: Ó by již bylo jitro! pro strach srdce svého, jímž se lekáš, a pro ty věci, na něž očima svýma hleděti musíš.'),
(1551870,54,5,28,68,'A zavede tě Hospodin do Egypta na lodech, cestou, o níž jsem řekl tobě: Nebudeš jí viděti více; a tam prodávati se budete nepřátelům svým za služebníky a děvky, a nebude, kdo by koupil.'),
(1551871,54,5,29,1,'Tato jsou slova smlouvy, kteráž přikázal Hospodin Mojžíšovi učiniti s syny Izraelskými v zemi Moábské, mimo onu smlouvu, kterouž učinil s nimi na Orébě.'),
(1551872,54,5,29,2,'I svolav Mojžíš všecken lid Izraelský, řekl jim: Vy sami viděli jste všecky věci, kteréž učinil Hospodin před očima vašima v zemi Egyptské, Faraonovi, i všechněm služebníkům jeho, i vší zemi jeho,'),
(1551873,54,5,29,3,'Zkušování veliká, kteráž viděly oči tvé, znamení i zázraky ty veliké.'),
(1551874,54,5,29,4,'A však nedal vám Hospodin srdce k srozumění, a očí k vidění, a uší k slyšení až do tohoto dne.'),
(1551875,54,5,29,5,'A vedl jsem vás čtyřidceti let po poušti, nezvetšela roucha vaše na vás, a obuv vaše neztrhala se na nohách vašich.'),
(1551876,54,5,29,6,'Chleba jste nejedli, vína a nápoje opojného jste nepili, abyste poznali, že já jsem Hospodin Bůh váš.'),
(1551877,54,5,29,7,'A když jste přišli na toto místo, vytáhl Seon, král Ezebon, a Og, král Bázan, proti nám k boji, a porazili jsme je,'),
(1551878,54,5,29,8,'A vzali jsme zemi jejich, i dali jsme ji v dědictví pokolení Rubenovu a Gádovu, a polovici pokolení Manassesova.'),
(1551879,54,5,29,9,'Ostříhejtež tedy slov smlouvy této a čiňte je, aby se vám šťastně vedlo všecko, což byste činili.'),
(1551880,54,5,29,10,'Vy všickni dnes stojíte před Hospodinem Bohem svým, knížata vaše v pokoleních vašich, starší vaši a úředníci vaši, všickni muži Izraelští,'),
(1551881,54,5,29,11,'Dítky vaše i ženy vaše, i příchozí vaši, kteříž bydlejí u prostřed stanů vašich, i ten, kterýž dříví seká, i ten, kterýž váží vodu,'),
(1551882,54,5,29,12,'Abyste vešli v smlouvu Hospodina Boha svého, a v přísahu jeho, v kteroužto smlouvu Hospodin Bůh tvůj dnes vchází s tebou,'),
(1551883,54,5,29,13,'Aby tě sobě dnes postavil za lid, a on byl tobě za Boha, jakož mluvil tobě, a jakož s přísahou zaslíbil otcům tvým, Abrahamovi, Izákovi a Jákobovi.'),
(1551884,54,5,29,14,'A ne s vámi samými činím smlouvu tuto a přísahu tuto,'),
(1551885,54,5,29,15,'Ale i s každým tím, jenž tuto dnes s námi stojí před Hospodinem Bohem naším, i s tím, jehož není tuto dnes s námi.'),
(1551886,54,5,29,16,'Nebo vy víte, kterak jsme bydlili v zemi Egyptské, a kterak jsme šli prostředkem těch národů, až jsme naskrze prošli.'),
(1551887,54,5,29,17,'A viděli jste ohavnosti jejich i modly jejich, dřevo i kámen, stříbro i zlato, kteréž jest při nich.'),
(1551888,54,5,29,18,'Hleďtež, ať nebývá mezi vámi muže, aneb ženy, aneb čeledi, aneb pokolení, jehož by srdce odvrátilo se dnes od Hospodina Boha našeho, a šel by sloužiti bohům těch národů; ať nebývá mezi vámi kořene plodícího jed a hořkost.'),
(1551889,54,5,29,19,'I stalo by se, že uslyše takový slova zlořečení tohoto, dobrořečil by sobě v srdci svém, řka: Pokoj míti budu, bychť pak i chodil podlé žádosti srdce svého; i přidal by opilou žíznivé.'),
(1551890,54,5,29,20,'Nechceť Hospodin odpustiti takovému, nebo tehdáž rozpálí se prchlivost Hospodinova a zůřivost jeho proti takovému člověku, tak že připadne na něj všeliké zlořečení, o kterémž psáno jest v knize této; i vyhladí Hospodin jméno jeho pod nebem.'),
(1551891,54,5,29,21,'A odloučí jej Hospodin s jeho zlým ode všech pokolení Izraelských, vedlé všech zlořečení smlouvy zapsané v této knize zákona,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551892,54,5,29,22,'Tak že řekne věk potomní, synové vaši, kteříž povstanou po vás, i cizozemec, kterýž přijde z země daleké, (když uzří rány země této, i neduhy její, kteréž uvedl na ni Hospodin,'),
(1551893,54,5,29,23,'Sirou a solí vypálenou všecku tu zemi, a že se nemůž síti, ani co vzcházeti, ani jaké byliny růsti na ní, rovně jako na místě, kdež jest podvrácena Sodoma a Gomora, Adama a Seboim, kteréž podvrátil Hospodin v hněvě svém a v prchlivosti své),'),
(1551894,54,5,29,24,'Řeknou všickni národové: Proč jest tak učinil Hospodin zemi této? Kteraký jest to hněv prchlivosti jeho náramné?'),
(1551895,54,5,29,25,'A bude odpovědíno: Proto že opustili smlouvu Hospodina Boha otců svých, kterouž učinil s nimi, když je vyvedl z země Egyptské.'),
(1551896,54,5,29,26,'Nebo odcházejíce, sloužili bohům cizím a klaněli se jim, bohům, kterýchž neznali, kteříž se s nimi také ničímž dobrým nezdělili.'),
(1551897,54,5,29,27,'I rozhněvala se prchlivost Hospodinova na tu zemi, tak že uvedl na ni všecko zlořečení zapsané v knize této.'),
(1551898,54,5,29,28,'Protož vyplénil je Hospodin z země jejich v hněvě, v rozpálení a v prchlivosti veliké, a vyvrhl je do země jiné, jakž to ukazuje dnešní den.'),
(1551899,54,5,29,29,'Věci skryté jsou Hospodina Boha našeho, věci pak zjevené ty jsou naše a synů našich, abychom plnili všecka slova zákona tohoto.'),
(1551900,54,5,30,1,'Když pak přijdou na tě všecka slova tato, požehnání i zlořečenství, kterážť jsem předložil, a rozpomeneš se v srdci svém, kdež bys koli byl mezi národy, do kterýchž by tě rozehnal Hospodin Bůh tvůj,'),
(1551901,54,5,30,2,'A obrátě se k Hospodinu Bohu svému, poslouchal bys hlasu jeho ve všem, jakž já přikazuji tobě dnes, ty i synové tvoji, z celého srdce svého a ze vší duše své:'),
(1551902,54,5,30,3,'Tehdy přivede zase Hospodin Bůh tvůj zajaté tvé a smiluje se nad tebou, a obrátě se, shromáždí tě ze všech národů, mezi něž rozptýlil tě Hospodin Bůh tvůj.'),
(1551903,54,5,30,4,'Byť pak někdo z tvých i na konec světa zahnán byl, odtud zase shromáždí tě Hospodin Bůh tvůj, a odtud půjme tě,'),
(1551904,54,5,30,5,'A uvede tě zase Hospodin Bůh tvůj do země, kterouž dědičně vládli otcové tvoji, a opanuješ ji, a dobřeť učiní a rozmnoží tě více nežli otce tvé.'),
(1551905,54,5,30,6,'A obřeže Hospodin Bůh tvůj srdce tvé a srdce semene tvého, abys miloval Hospodina Boha svého z celého srdce svého, a ze vší duše své, abys živ byl.'),
(1551906,54,5,30,7,'Všecka pak zlořečenství tato obrátí Hospodin Bůh tvůj na nepřátely tvé a na ty, jenž v nenávisti měli tebe, a protivili se tobě.'),
(1551907,54,5,30,8,'Ty tedy obrátě se, když poslouchati budeš hlasu Hospodina Boha svého, a činiti všecka přikázaní jeho, kteráž já tobě dnes přikazuji:'),
(1551908,54,5,30,9,'Dáť Hospodin Bůh tvůj prospěch při všem díle rukou tvých, v plodu života tvého i v plodu dobytka tvého, a v úrodách země tvé, tobě k dobrému. Nebo zase veseliti se bude Hospodin z tebe, dobře čině tobě, jakož veselil se z otců tvých,'),
(1551909,54,5,30,10,'Jestliže bys však poslouchal hlasu Hospodina Boha svého, a ostříhal přikázaní jeho a ustanovení jeho, napsaných v knize zákona tohoto, když bys se obrátil k Hospodinu Bohu svému celým srdcem svým a celou duší svou.'),
(1551910,54,5,30,11,'Nebo přikázaní toto, kteréž přikazuji tobě dnes, není skryté před tebou, ani vzdálené od tebe.'),
(1551911,54,5,30,12,'Není na nebi, abys řekl: Kdo nám vstoupí do nebe, aby vezma, přinesl a oznámil je nám, abychom je plnili?'),
(1551912,54,5,30,13,'Ani za mořem jest, abys řekl: Kdo se nám přeplaví za moře, aby je přinesl a oznámil nám, abychom plnili je?'),
(1551913,54,5,30,14,'Ale velmi blízko tebe jest slovo, v ústech tvých a v srdci tvém, abys činil to:'),
(1551914,54,5,30,15,'(Hle, předložil jsem tobě dnes život a dobré, smrt i zlé),'),
(1551915,54,5,30,16,'Což já přikazuji tobě dnes, abys miloval Hospodina Boha svého, chodě po cestách jeho a ostříhaje přikázaní jeho, ustanovení a soudů jeho, abys živ jsa, rozmnožen byl, a požehnal tobě Hospodin Bůh tvůj v zemi, do kteréž jdeš, abys ji dědičně obdržel.'),
(1551916,54,5,30,17,'Pakli se odvrátí srdce tvé, a nebudeš poslouchati, ale přiveden jsa k tomu, klaněti se budeš bohům cizím a jim sloužiti:'),
(1551917,54,5,30,18,'Ohlašuji vám dnes, že jistotně zahynete, aniž prodlíte dnů svých v zemi, do kteréž se přes Jordán béřeš, abys ji dědičně obdržel.'),
(1551918,54,5,30,19,'Osvědčuji proti tobě dnes nebem a zemí, žeť jsem život i smrt předložil, požehnání i zlořečenství; vyvoliž sobě tedy život, abys živ byl ty i símě tvé,'),
(1551919,54,5,30,20,'A miloval Hospodina Boha svého, poslouchaje hlasu jeho a přídrže se jeho, (nebo on jest život tvůj, a dlouhost dnů tvých), abys bydlil v zemi, kterouž s přísahou zaslíbil Hospodin otcům tvým Abrahamovi, Izákovi a Jákobovi, že jim ji dá.'),
(1551920,54,5,31,1,'Přišed tedy Mojžíš, mluvil slova ta ke všemu Izraelovi,'),
(1551921,54,5,31,2,'A řekl jim: Ve stu a ve dvadcíti letech jsem dnes, nemohuť již více vycházeti a vcházeti; a také řekl Hospodin ke mně: Nepřejdeš Jordánu tohoto.'),
(1551922,54,5,31,3,'Hospodin Bůh tvůj předcházející tebe vyhladí ty národy od tváři tvé, a ty dědičně je opanuješ, a Jozue tento půjde před tebou,jakož řekl Hospodin.'),
(1551923,54,5,31,4,'I učiní Hospodin jim, jakož učinil Seonovi a Ogovi králům Amorejským a zemi jejich, kteréž vyhladil.'),
(1551924,54,5,31,5,'Protož když je dá Hospodin vám, tedy učiníte jim vedlé každého přikázaní, kteréž jsem přikázal vám.'),
(1551925,54,5,31,6,'Buďte silní a zmužile se mějte, nebojte se, ani se lekejte tváři jejich, nebo Hospodin Bůh tvůj, on jde s tebou, neopustíť a nezanechá tebe.'),
(1551926,54,5,31,7,'Tedy povolal Mojžíš Jozue a řekl jemu před očima všeho Izraele: Budiž silný a zmužile se měj, nebo ty vejdeš s lidem tímto do země, kterouž s přísahou zaslíbil Hospodin otcům jejich, že ji dá jim, a ty ji rozdělíš jim v dědictví.'),
(1551927,54,5,31,8,'Hospodin pak předcházející tě, onť bude s tebou, neopustí tě, aniž tě zanechá; neboj se, ani se strachuj.'),
(1551928,54,5,31,9,'I napsal Mojžíš zákon tento a dal jej kněžím, synům Léví, kteříž nosili truhlu smlouvy Hospodinovy, a všechněm starším Izraelským,'),
(1551929,54,5,31,10,'A přikázal jim Mojžíš, řka: Každého léta sedmého, v jistý čas léta odpuštění, v svátek stanů,'),
(1551930,54,5,31,11,'Když přijde všecken Izrael a postaví se před Hospodinem Bohem tvým na místě, kteréž by vyvolil, čísti budeš zákon tento přede vším Izraelem v uších jejich,'),
(1551931,54,5,31,12,'Shromáždě lid, muže i ženy, i děti, i příchozí své, kteříž jsou v branách tvých, aby slyšíce, učili se a báli se Hospodina Boha vašeho, a hleděli činiti všecka slova zákona tohoto.'),
(1551932,54,5,31,13,'Synové také jejich, kteříž ještě toho nepoznali, ať slyší a učí se báti Hospodina Boha vašeho po všecky dny, v nichž živi budete na zemi, do níž, přejdouce Jordán, vejdete, abyste ji dědičně obdrželi.'),
(1551933,54,5,31,14,'I řekl Hospodin Mojžíšovi: Aj, již se přiblížili dnové tvoji, abys umřel. Povolej Jozue, a postavte se oba v stánku úmluvy, a přikáži jemu. Šel tedy Mojžíš a Jozue, a postavili se v stánku úmluvy.'),
(1551934,54,5,31,15,'I ukázal se Hospodin v stánku v sloupě oblakovém, a postavil se sloup oblakový nade dveřmi stánku.'),
(1551935,54,5,31,16,'Řekl pak Hospodin Mojžíšovi: Aj, ty již usneš s otci svými, potom lid tento vstana, smilniti bude, následuje bohů cizozemců země této, do níž vchází, aby bydlil u prostřed ní; tu mne opustí a zruší smlouvu mou, kterouž jsem učinil s ním.'),
(1551936,54,5,31,17,'Protož rozhněvá se na něj prchlivost má v ten den, a opustím je, i skryji tvář svou od nich, a bude sežrán, i přijdou na něj mnohé věci zlé a úzkosti. I řekne v ten den: Zdaliž ne proto přišly na mne tyto zlé věci, že Bůh můj není u prostřed mne?'),
(1551937,54,5,31,18,'Já pak daleko skryji tvář svou v ten den pro všecko to zlé, kteréž páchal, jakž se obrátil k bohům cizím.'),
(1551938,54,5,31,19,'Protož nyní napište sobě píseň tuto, a uč jí syny Izraelské; vlož ji v ústa jejich, aby ta píseň byla mi za svědka proti synům Izraelským.'),
(1551939,54,5,31,20,'Nebo uvedu jej do země, kterouž jsem s přísahou zaslíbil otcům jeho, oplývající mlékem a strdí, kdežto bude jísti a nasytí se a ztuční. Tehdy obrátí se k bohům cizím a sloužiti bude jim, i popudí mne a zruší smlouvu mou.'),
(1551940,54,5,31,21,'A když přijdou na něj mnohé zlé věci a úzkosti, tehdy bude jemu tato píseň na svědectví, (nebo nepřijde v zapomenutí, aniž odejde od úst semene jeho). Známť zajisté myšlení jeho, a co on ještě dnes činiti bude, prvé nežli jej uvedu do země, kterouž jsem s přísahou zaslíbil.'),
(1551941,54,5,31,22,'Tedy napsal Mojžíš tu píseň v ten den a učil jí syny Izraelské.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551942,54,5,31,23,'Potom dal přikázaní Jozue, synu Nun, řka: Budiž silný, a měj se zmužile, nebo ty uvedeš syny Izraelské do země, kterouž jsem jim s přísahou zaslíbil, a já budu s tebou.'),
(1551943,54,5,31,24,'Stalo se pak, když napsal Mojžíš slova zákona tohoto v knize, a dokonal je,'),
(1551944,54,5,31,25,'Že přikázal Levítům, kteříž nosili truhlu smlouvy Hospodinovy, řka:'),
(1551945,54,5,31,26,'Vezměte tu knihu zákona a vložte ji v straně truhly smlouvy Hospodina Boha vašeho, ať jest tam proti vám na svědectví.'),
(1551946,54,5,31,27,'Nebo já znám zpouru tvou a zatvrdilost šíje tvé. Aj, poněvadž, když jsem já ještě živ nyní s vámi, zpurní jste bývali Hospodinu, čím tedy více, když já umru?'),
(1551947,54,5,31,28,'Shromažďte ke mně všecky starší pokolení svých a správce vaše, abych mluvil v uši jejich slova tato, a osvědčil proti nim nebem i zemí.'),
(1551948,54,5,31,29,'Nebo vím, že po mé smrti velmi porušíte se a vystoupíte z cesty, kterouž jsem přikázal vám; pročež přijde na vás toto zlé v posledních dnech, když byste činili to, což se nelíbí Hospodinu, popouzejíce ho dílem rukou svých.'),
(1551949,54,5,31,30,'Mluvil tedy Mojžíš v uši všeho shromáždění Izraelského slova písně této, až je i dokonal.'),
(1551950,54,5,32,1,'Pozorujte nebesa a mluviti budu, poslyš i země výmluvností úst mých.'),
(1551951,54,5,32,2,'Sstupiž jako déšť naučení mé, spadniž jako rosa výmluvnost má, jako tichý déšť na mladistvou trávu, a jako příval na odrostlou bylinu,'),
(1551952,54,5,32,3,'Nebo jméno Hospodinovo slaviti budu. Vzdejtež velebnost Bohu našemu,'),
(1551953,54,5,32,4,'Skále té, jejíž skutkové jsou dokonalí, nebo všecky cesty jeho jsou spravedlivé. Bůh silný, pravdomluvný, a není nepravosti v něm, spravedlivý a přímý jest.'),
(1551954,54,5,32,5,'Ale pokolení převrácené a zavilé zpronevěřilo se jemu mrzkostí vlastní svou,jakáž vzdálena jest od synů jeho.'),
(1551955,54,5,32,6,'Tím-liž jste se odplacovati měli Hospodinu, lide bláznivý a nemoudrý? Zdaliž on není otec tvůj, kterýž tě sobě dobyl? On učinil tebe a utvrdil tě.'),
(1551956,54,5,32,7,'Rozpomeň se na dny staré, považte let každého věku; vzeptej se otce svého, a oznámí tobě, starců svých, a povědí tobě.'),
(1551957,54,5,32,8,'Když dědictví rozděloval Nejvyšší národům, když rozsadil syny Adamovy, rozměřil meze národům vedlé počtu synů Izraelských.'),
(1551958,54,5,32,9,'Nebo díl Hospodinův jest lid jeho, Jákob provazec dědictví jeho.'),
(1551959,54,5,32,10,'Nalezl jej v zemi pusté, a na poušti veliké a hrozné; vůkol vedl jej, vyučil jej, a ostříhal ho, jako zřítedlnice oka svého.'),
(1551960,54,5,32,11,'Jako orlice ponouká orličátek svých, sedí na mladých svých, roztahuje křídla svá, béře je, a nosí je na křídlách svých:'),
(1551961,54,5,32,12,'Tak Hospodin sám vedl jej, a nebylo s ním boha cizozemců.'),
(1551962,54,5,32,13,'Zprovodil jej na vysoká místa země, aby jedl úrody polní, a učinil, aby ssál med z skály, a olej z kamene přetvrdého,'),
(1551963,54,5,32,14,'Máslo od krav a mléko od ovcí, s nejtučnějšími beránky a skopci z Bázan a kozly s jádrem zrn pšeničných, a červené víno výborné aby pil.'),
(1551964,54,5,32,15,'Takž Izrael ztučněv, zpíčil se; vytyl jsi a ztlustl, tukem jsi obrostl; i opustil Boha stvořitele svého, a zlehčil sobě Boha spasení svého.'),
(1551965,54,5,32,16,'K horlení popudili ho cizími bohy, ohavnostmi zdráždili jej.'),
(1551966,54,5,32,17,'Obětovali ďáblům, ne Bohu, bohům, jichž neznali, novým, kteříž z blízka přišli, jichžto se nic nestrašili otcové vaši.'),
(1551967,54,5,32,18,'Na skálu, kteráž zplodila tě, zapomenul jsi; zapomněl jsi na Boha silného, stvořitele svého.'),
(1551968,54,5,32,19,'To když viděl Hospodin, popudil se hněvem proti synům a dcerám svým,'),
(1551969,54,5,32,20,'A řekl: Skryji před nimi tvář svou, podívám se posledním věcem jejich; nebo národ převrácený jest, synové, v nichž není žádné víry.'),
(1551970,54,5,32,21,'Oniť jsou mne popudili k horlení skrze to, což není Bůh silný, rozhněvali mne svými marnostmi. I jáť popudím jich k závisti skrze ty, kteříž nejsou lid, skrze národ bláznivý k hněvu jich popudím.'),
(1551971,54,5,32,22,'Nebo oheň zápalen jest v prchlivosti mé, a hořeti bude až do nejhlubšího pekla, a sžíře zemi i úrody její, a zapálí základy hor.'),
(1551972,54,5,32,23,'Shromáždím na ně zlé věci, střely své vystřílím na ně.'),
(1551973,54,5,32,24,'Hladem usvadnou, a neduhy pálčivými a nakažením morním přehořkým žráni budou; také zuby šelm pošli na ně s jedem hadů zemských.'),
(1551974,54,5,32,25,'Meč uvede sirobu vně, a v pokojích bude strach, tak na mládenci jako panně, dítěti prsí požívajícím i muži šedivém.'),
(1551975,54,5,32,26,'Ano, řekl bych:Rozptýlím je po koutech, rozkáži přestati mezi lidmi paměti jejich,'),
(1551976,54,5,32,27,'Bych se pýchy nepřítele neobával, aby spatříce to nepřátelé jejich, neřekli: Ruka naše nepřemožená byla, neučinilť jest Hospodin ničeho z těch věcí.'),
(1551977,54,5,32,28,'Nebo národ ten nesmyslný jest a nemající rozumnosti.'),
(1551978,54,5,32,29,'Ó by moudří byli, rozuměliť by tomu, prohlédali by na poslední věci své.'),
(1551979,54,5,32,30,'Jak by jich jeden honiti mohl tisíc, a dva pryč zahnati deset tisíců? Jediné že Bůh skála jejich prodal je, a Hospodin vydal je.'),
(1551980,54,5,32,31,'Nebo Bůh skála naše není jako skála jejich, což nepřátelé naši sami souditi mohou.'),
(1551981,54,5,32,32,'Nebo z kmene Sodomského kmen jejich, a z réví Gomorských hroznové jejich, hroznové jedovatí, zrní hořkosti plné.'),
(1551982,54,5,32,33,'Jed draků víno jejich, a jed lítý nejjedovatějšího hada.'),
(1551983,54,5,32,34,'Zdaliž to není schováno u mne? zapečetěno v pokladnicích mých?'),
(1551984,54,5,32,35,'Máť jest pomsta a odplata, časemť svým klesne noha jejich; nebo blízko jest den zahynutí jejich, a budoucí věci zlé rychle připadnou na ně.'),
(1551985,54,5,32,36,'Souditi zajisté bude Hospodin lid svůj, a nad služebníky svými lítost míti bude, když uzří, že odešla síla, a že jakož zajatý tak i zanechaný s nic býti nemůže.'),
(1551986,54,5,32,37,'I dí: Kde jsou bohové jejich? skála, v níž naději měli?'),
(1551987,54,5,32,38,'Z jejichžto obětí tuk jídali, a víno z obětí jejich mokrých píjeli? Nechať vstanou a spomohou vám, nechť vám skrejší jest skála ta.'),
(1551988,54,5,32,39,'Pohleďtež již aspoň, že já jsem, já jsem sám, a že není Boha kromě mne. Já mohu usmrtiti i obživiti, já raniti i uzdraviti, a není žádného, kdo by vytrhl z ruky mé.'),
(1551989,54,5,32,40,'Nebo já pozdvihám k nebi ruky své, a pravím: Živ jsem já na věky.'),
(1551990,54,5,32,41,'Jakž nabrousím ostří meče svého, a uchopí soud ruka má, učiním pomstu nad nepřátely svými, a těm, jenž v nenávisti mne měli, odplatím.'),
(1551991,54,5,32,42,'Opojím střely své krví, a meč můj sžere maso, a to krví raněných a zajatých, jakž jen začnu pomsty uvoditi na nepřátely.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1551992,54,5,32,43,'Veselte se pohané s lidem jeho, neboť pomstí krve služebníků svých, a uvede pomstu na nepřátely své, a očistí zemi svou a lid svůj.'),
(1551993,54,5,32,44,'I přišel Mojžíš, a mluvil všecka slova písně této v uši lidu, on a Jozue, syn Nun.'),
(1551994,54,5,32,45,'A když dokonal Mojžíš mluvení všech slov těch ke všemu množství Izraelskému,'),
(1551995,54,5,32,46,'Řekl jim: Přiložtež srdce svá ke všechněm slovům, kteráž já dnes osvědčuji vám,a přikažte to synům svým, aby ostříhali všech slov zákona tohoto, a činili je.'),
(1551996,54,5,32,47,'Nebo není daremné slovo, abyste jím pohrdnouti měli, ale jest život váš; a v slovu tom prodlíte dnů svých na zemi, kterouž abyste dědičně obdrželi, půjdete přes Jordán.'),
(1551997,54,5,32,48,'Téhož dne mluvil Hospodin k Mojžíšovi, řka:'),
(1551998,54,5,32,49,'Vstup na horu tuto Abarim, na vrch Nébo, kteráž jest v zemi Moábské naproti Jerichu, a spatř zemi Kananejskou, kterouž já dávám synům Izraelským právem dědičným.'),
(1551999,54,5,32,50,'A umřeš na vrchu, na kterýž vejdeš, a připojen budeš k lidu svému, jako umřel Aron, bratr tvůj, na hoře řečené Hor, a připojen jest k lidu svému.'),
(1552000,54,5,32,51,'Nebo jste zhřešili proti mně u prostřed synů Izraelských, při vodách odpírání v Kádes, na poušti Tsin, proto že jste neposvětili mne u prostřed synů Izraelských.'),
(1552001,54,5,32,52,'Před sebou zajisté uzříš zemi tu, ale tam nevejdeš do země té, kterouž dávám synům Izraelským.'),
(1552002,54,5,33,1,'Toto pak jest požehnání, kterýmž požehnal Mojžíš, muž Boží, synů Izraelských před svou smrtí,'),
(1552003,54,5,33,2,'A řekl: Hospodin z Sinai přišel, a vzešel jim z Seir, zastkvěl se s hory Fáran, a přišel s desíti tisíci svatých, z jehožto pravice oheň zákona svítil jim.'),
(1552004,54,5,33,3,'Jak velice miluješ lidi! Všickni svatí jeho jsou v ruce tvé, oni také přivinuli se k nohám tvým, vezmouť prospěch z výmluvností tvých.'),
(1552005,54,5,33,4,'Zákon vydal nám Mojžíš, dědičný shromáždění Jákobovu,'),
(1552006,54,5,33,5,'(Nebo byl v Izraeli jako král), když přední z lidu shromáždili se, i všecka pokolení Izraelská.'),
(1552007,54,5,33,6,'Buď živ Ruben a neumírej, a muži jeho ať jsou bez počtu.'),
(1552008,54,5,33,7,'Tolikéž požehnal i Judovi a řekl: Vyslyš, Hospodine, hlas Judův, a k lidu svému jej sprovozuj; ruce jeho budou bojovati za něj, a ty jemu spomáhati budeš proti nepřátelům jeho.'),
(1552009,54,5,33,8,'O Léví také řekl: Thumim tvé a urim tvé bylo, Pane, při muži svatém tvém, kteréhož jsi zkusil v pokušení, a kterýž podlé tebe měl nesnáz při vodách Meribah,'),
(1552010,54,5,33,9,'Kterýž řekl otci svému a matce své: Neohlédám se na vás; a bratří svých neznal, a o synech svých nevěděl; nebo ostříhají výmluvností tvých, a smlouvu tvou zachovávají.'),
(1552011,54,5,33,10,'Vyučovati budou soudům tvým Jákoba, a zákonu tvému Izraele, a klásti budou kadidlo před tváří tvou, a obět zápalnou na oltáři tvém.'),
(1552012,54,5,33,11,'Požehnejž, Hospodine, rytěřování jeho, a v práci rukou jeho zalib se tobě. Zlomuj ledví nepřátel jeho a těch, kteříž ho nenávidí, aby nepovstali.'),
(1552013,54,5,33,12,'A o Beniaminovi řekl: Milý jest Hospodinu, bezpečně s ním bydliti bude; ochraňovati jej bude každého dne, a mezi rameny jeho přebývati.'),
(1552014,54,5,33,13,'O Jozefovi pak řekl: Požehnaná země jeho od Hospodina pro nejlepší věci nebeské, pro rosu a vrchoviště zespod se prýštící,'),
(1552015,54,5,33,14,'A pro nejlepší úrody sluncem vyzralé, a pro nejlepší věci časem měsíců došlé,'),
(1552016,54,5,33,15,'I pro rozkoše hor nejstarších, a pro rozkoše pahrbků věčných,'),
(1552017,54,5,33,16,'Pro nejlepší věci země i plnost její, vyplývající z milosti ve kři přebývajícího. Přijdiž to požehnání na hlavu Jozefovu, a na vrch hlavy odděleného z jiných bratří jeho.'),
(1552018,54,5,33,17,'Prvorozeného, vola toho krása veliká bude, a rohové jednorožce rohové jeho, jimiž on trkati bude národy napořád až do končin země. A toť jsou mnozí tisícové Efraimovi a tisícové Manassesovi.'),
(1552019,54,5,33,18,'O Zabulonovi také řekl: Vesel se Zabulon u vycházení svém, a Izachar v staních svých.'),
(1552020,54,5,33,19,'Lidi na horu Boží svolají, a budou obětovati oběti spravedlnosti; nebo hojnost mořskou ssáti budou, a skryté poklady v písku.'),
(1552021,54,5,33,20,'Gádovi pak řekl: Požehnaný, kterýž rozšiřuje Gáda. Onť jakožto lev bydliti bude, a uchvátí rameno i s hlavou.'),
(1552022,54,5,33,21,'Kterýž opatřil ho prvotinami; nebo tam podílem skrze vydavatele zákona ubezpečen jest. Protož pobéřeť se s knížaty lidu, a spravedlnost Hospodinovu i soudy jeho s Izraelem vykonávati bude.'),
(1552023,54,5,33,22,'O Danovi pak řekl: Dan jako lvíče lvové vyskakovati bude z Bázan.'),
(1552024,54,5,33,23,'A Neftalímovi řekl: Ó Neftalíme, sytý přízní Páně, plný požehnání Hospodinova, západní a polední stranu přijmi za dědictví.'),
(1552025,54,5,33,24,'O Asserovi také řekl: Asser požehnaný nad jiné syny, budeť milý bratřím svým, omočí v oleji nohu svou.'),
(1552026,54,5,33,25,'Železo a měď pod šlepějemi tvými; pokudž trvati budou dnové tvoji, slovoutný budeš.'),
(1552027,54,5,33,26,'Neníť žádného, jako Bůh silný, ó Izraeli, kterýž se vznáší na nebesích ku pomoci tobě, a u velebnosti své na oblacích nejvyšších.'),
(1552028,54,5,33,27,'Ochrana tvá buď Bůh věčný, a zespod ramena věčnosti, kterýž vyžene nepřátely před tebou, aneb řekne: Vyhlaď je,'),
(1552029,54,5,33,28,'Aby sám bezpečně bydlil Izrael, rodina Jákobova, a to v zemi obilím a vínem oplývající, jehož nebesa také i rosu vydávati budou.'),
(1552030,54,5,33,29,'Blahoslavený jsi, Izraeli. Kdo jest podobný tobě, lide vysvobozený skrze Hospodina, jenž jest pavéza spomožení tvého a meč důstojnosti tvé? Tvoji zajisté nepřátelé poníženi budou, ale ty po všech vyvýšenostech jejich šlapati budeš.'),
(1552031,54,5,34,1,'Tedy vstoupil Mojžíš z rovin Moábských na horu Nébo, na vrch hory, kteráž jest proti Jerichu, a ukázal jemu Hospodin všecku zemi Galád až do Dan,'),
(1552032,54,5,34,2,'I všecku Neftalím, a zemi Efraim a Manasse, a všecku zemi Juda až k moři nejdalšímu,'),
(1552033,54,5,34,3,'Polední také stranu a roviny údolí Jericha, města palmovím osazeného, až do Segor.'),
(1552034,54,5,34,4,'A řekl jemu Hospodin: Tato jest země, kterouž s přísahou zaslíbil jsem Abrahamovi, Izákovi a Jákobovi, řka: Semeni tvému dám ji. Způsobil jsem to, abys ji viděl očima svýma, však do ní nevejdeš.'),
(1552035,54,5,34,5,'I umřel tam Mojžíš, služebník Hospodinův, v zemi Moábské, vedlé řeči Hospodinovy.'),
(1552036,54,5,34,6,'A pochoval jej v Gai, v zemi Moábské naproti Betfegor, a žádný nezvěděl o jeho hrobu až do tohoto dne.'),
(1552037,54,5,34,7,'Byl pak Mojžíš ve stu a dvadcíti letech, když umřel, a nepošly oči jeho, aniž síla odešla od něho.'),
(1552038,54,5,34,8,'I plakali synové Izraelští Mojžíše na rovinách Moábských třidceti dní, a vyplněni jsou dnové pláče a kvílení nad Mojžíšem.'),
(1552039,54,5,34,9,'Jozue pak, syn Nun, naplněn jest duchem moudrosti; nebo byl vložil Mojžíš ruce své na něj. I poslouchali ho synové Izraelští, a činili, jakož přikázal Hospodin skrze Mojžíše.'),
(1552040,54,5,34,10,'Ale nepovstal více prorok v Izraeli podobný Mojžíšovi, (kteréhož by tak znal Hospodin tváří v tvář),'),
(1552041,54,5,34,11,'Ve všech znameních a zázracích, pro něž poslal jej Hospodin, aby činil je v zemi Egyptské, před Faraonem a přede všechněmi služebníky jeho, a vší zemí jeho,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552042,54,5,34,12,'Také i ve všech skutcích ruky silné, a ve všeliké hrůzi veliké, kteréžto věci činil Mojžíš před očima všeho Izraele.'),
(1552043,54,6,1,1,'Stalo se pak po smrti Mojžíše, služebníka Hospodinova, že mluvil Hospodin k Jozue, synu Nun, služebníku Mojžíšovu, řka:'),
(1552044,54,6,1,2,'Mojžíš, služebník můj, umřel; protož nyní vstaň, přejdi Jordán tento, ty i všecken lid tento, a jdi do země, kterouž já dávám synům Izraelským.'),
(1552045,54,6,1,3,'Každé místo, po kterémž šlapati budete nohama svýma, dal jsem vám, jakož jsem mluvil k Mojžíšovi.'),
(1552046,54,6,1,4,'Od pouště a Libánu toho až k řece veliké, řece Eufrates, všecka země Hetejská až do moře velikého na západ slunce bude pomezí vaše.'),
(1552047,54,6,1,5,'Neostojí žádný před tebou po všecky dny života tvého; jakož jsem byl s Mojžíšem, tak budu s tebou; nenechám tebe samého, aniž tě opustím.'),
(1552048,54,6,1,6,'Posilniž se a zmužile se měj, nebo ty uvedeš v dědictví lidu tomuto zemi, kterouž jsem s přísahou zaslíbil otcům jejich, že ji dám jim.'),
(1552049,54,6,1,7,'Toliko posilň se a udatně sobě počínej, abys ostříhal a činil všecko podlé zákona, kterýž přikázal tobě Mojžíš, služebník můj; neuchyluj se od něho na pravo ani na levo, abys byl opatrný ve všem, k čemuž se obrátíš.'),
(1552050,54,6,1,8,'Neodejdeť kniha zákona tohoto od úst tvých, ale přemyšlovati budeš o něm dnem i nocí, abys ostříhal a činil všecko podlé toho, což psáno jest v něm; nebo tehdáž šťastný budeš na cestách svých, a tehdáž opatrný budeš.'),
(1552051,54,6,1,9,'Zdaliž jsem nepřikázal tobě, řka: Posilni se a zmužile se měj, neboj se, ani lekej, nebo s tebou jest Hospodin Bůh tvůj, kamž se koli obrátíš.'),
(1552052,54,6,1,10,'Tedy přikázal Jozue správcům lidu, řka:'),
(1552053,54,6,1,11,'Projděte skrze tábor a přikažte lidu, řkouce: Nachystejte sobě potravy, nebo po třech dnech půjdete přes Jordán tento, abyste vejdouce, opanovali zemi, kterouž Hospodin Bůh váš dává vám k dědičnému vládařství.'),
(1552054,54,6,1,12,'Rubenovu pak pokolení a Gádovu, a polovici pokolení Manassesova mluvil Jozue, řka:'),
(1552055,54,6,1,13,'Pomněte na to, co vám přikázal Mojžíš služebník Hospodinův, když řekl: Hospodin Bůh váš způsobil vám odpočinutí, že vám dal zemi tuto.'),
(1552056,54,6,1,14,'Ženy vaše, dítky vaše i dobytek váš nechť zůstanou v zemi, kterouž dal vám Mojžíš s této strany Jordánu, vy pak jděte vojensky zpořádaní před bratřími svými, kteříkoli jste muži silní, a pomáhejte jim,'),
(1552057,54,6,1,15,'Dokudž nedá odpočinutí Hospodin bratřím vašim jako i vám, a neobdrží dědičně také i oni země, kterouž Hospodin Bůh váš dává jim. Potom navrátíte se do země dědictví svého, kterouž dal vám Mojžíš, služebník Hospodinův, s této strany Jordánu, k východu slunce, a dědičně vlásti jí budete.'),
(1552058,54,6,1,16,'I odpověděli k Jozue, řkouce: Všecko, což jsi nám rozkázal, učiníme, a kamžkoli pošleš nás, půjdeme.'),
(1552059,54,6,1,17,'Rovně jakž jsme poslouchali Mojžíše, tak poslouchati budeme tebe; jediné nechť jest Hospodin Bůh tvůj s tebou, jako byl s Mojžíšem.'),
(1552060,54,6,1,18,'Kdo by koli odporný byl rozkázaní tvému, a neposlouchal by řečí tvých ve všech věcech, kteréž bys přikázal jemu, umřeť; toliko posilň se a zmužile se měj.'),
(1552061,54,6,2,1,'Poslal pak byl Jozue, syn Nun, z Setim dva muže špehéře tajně, řka: Jděte, shlédněte zemi, zvlášť Jericho. I šli a vešli do domu ženy nevěstky, jejíž jméno bylo Raab, a odpočinuli tu.'),
(1552062,54,6,2,2,'Ale jakž oznámeno bylo králi Jericha a povědíno: Aj, muži přišli sem této noci z synů Izraelských, aby shlédli zemi,'),
(1552063,54,6,2,3,'Tedy poslal král Jericha k Raab, řka: Vyveď muže, kteříž přišli k tobě, a vešli do domu tvého, nebo k vyšpehování vší země přišli.'),
(1552064,54,6,2,4,'(Pojavši pak žena ty dva muže, skryla je.) Kteráž odpověděla: Pravda jest, přišliť jsou ke mně muži, ale nevěděla jsem, odkud jsou.'),
(1552065,54,6,2,5,'A když bránu zavírati měli v soumrak, vyšli muži ti, a nevím, kam jsou šli; hoňte je rychle, nebo dostihnete jich.'),
(1552066,54,6,2,6,'Ale ona rozkázala jim vstoupiti na střechu, a skryla je v pazdeří lněném, kteréž byla skladla na střeše.'),
(1552067,54,6,2,7,'Muži pak vyslaní honili je cestou Jordánskou až k brodům; a zavřína jest brána, jakž vyšli ti, kteříž je honili.'),
(1552068,54,6,2,8,'Prvé pak, než usnuli špehéři, vstoupila k nim ona na střechu,'),
(1552069,54,6,2,9,'A řekla mužům těm: Vím, že Hospodin dal vám zemi tuto, nebo připadl na nás strach váš, tak že oslábli všickni obyvatelé země před tváří vaší.'),
(1552070,54,6,2,10,'Slyšeli jsme zajisté, jak vysušil Hospodin vody moře Rudého před tváří vaší, když jste vyšli z Egypta, a co jste učinili dvěma králům Amorejským, kteříž byli za Jordánem, Seonovi a Ogovi, kteréž jste zahladili jako proklaté.'),
(1552071,54,6,2,11,'Což když jsme uslyšeli, osláblo srdce naše, aniž zůstává více v kom duše před tváří vaší, nebo Hospodin Bůh váš jest Bůh na nebi svrchu, i na zemi dole.'),
(1552072,54,6,2,12,'Nyní tedy, prosím, přisáhněte mi skrze Hospodina, poněvadž jsem učinila vám milosrdenství, že i vy učiníte s domem otce mého milosrdenství, a dáte mi znamení jisté,'),
(1552073,54,6,2,13,'Že budete živiti otce mého i matku mou, bratří mé i sestry mé a všecko, cožkoli jejich jest, a vysvobodíte duše naše od smrti.'),
(1552074,54,6,2,14,'I řekli jí muži ti: Duše naše za vás nechť jsou na smrt; jestliže však nepronesete řeči naší této, takť se jistě stane, že když nám dá Hospodin zemi tuto, tehdy učiníme s tebou milosrdenství a pravdu.'),
(1552075,54,6,2,15,'Protož spustila je oknem po provazu; nebo dům její byl při zdi městské, a na zdi ona bydlila.'),
(1552076,54,6,2,16,'I řekla jim: Jděte k této hoře, aby se nepotkali s vámi, kteříž vás honí, a krejte se tam za tři dni, až se oni zase navrátí, a potom půjdete cestou svou.'),
(1552077,54,6,2,17,'Tedy řekli muži k ní: Prosti budeme od této přísahy tvé, kterouž jsi zavázala nás,'),
(1552078,54,6,2,18,'Jestliže, když vejdeme do země, neuvážeš provázku tohoto z nití hedbáví červeného dvakrát barveného v tomto okně, jímž jsi nás spustila, také otce svého a matky své, i bratří svých, a všeho domu otce svého neshromáždíš-li k sobě do domu.'),
(1552079,54,6,2,19,'Také kdo by vyšel ven ze dveří domu tvého, krev jeho bude na hlavu jeho, ale my budeme bez viny; a každého toho, kdož bude s tebou v domě, jestliže by se kdo rukou dotekl, krev jeho na hlavy naše připadni.'),
(1552080,54,6,2,20,'Jestliže pak proneseš tuto řeč naši, budeme prosti od přísahy tvé, kterouž jsi nás zavázala.'),
(1552081,54,6,2,21,'Odpověděla ona: Nechť jest tak, jakž jste řekli. I propustila je a odešli; i uvázala provázek z hedbáví červeného dvakrát barveného v tom okně.'),
(1552082,54,6,2,22,'Odšedše pak, přišli na horu, a pobyli tam za tři dni, dokudž se nenavrátili, kteříž je honili; nebo jich hledali ti, kteříž je honili po všech cestách, ale nic nenalezli.'),
(1552083,54,6,2,23,'Ti pak dva muži sšedše s hory, navrátili se a přeplavili se přes Jordán; i přišli k Jozue, synu Nun, a vypravovali jemu všecko, co se s nimi dálo.'),
(1552084,54,6,2,24,'A řekli k Jozue: Dalť jest Hospodin v ruce naše všecku zemi, nebo se zděsili všickni obyvatelé země tváři naší.'),
(1552085,54,6,3,1,'Vstal pak Jozue velmi ráno, a hnuvše se z Setim, přišli až k Jordánu, on i všickni synové Izraelští, a přenocovali tu, prvé nežli šli přes něj.'),
(1552086,54,6,3,2,'I stalo se, že třetího dne správcové šli prostředkem stanů,'),
(1552087,54,6,3,3,'A přikazovali lidu, řkouce: Když uzříte truhlu smlouvy Hospodina Boha svého a kněží Levítské, ani ji nesou, vy také hnete se s místa svého a půjdete za ní,'),
(1552088,54,6,3,4,'(A však místo mezi vámi a mezi ní bude okolo dvou tisíc loket míry obecné, nepřibližujte se k ní), abyste viděli cestu, kterouž byste jíti měli; nebo nešli jste tou cestou prvé.'),
(1552089,54,6,3,5,'Řekl pak byl Jozue lidu: Posvěťtež se, zítra zajisté učiní Hospodin divné věci mezi vámi.'),
(1552090,54,6,3,6,'Potom řekl Jozue kněžím těmi slovy: Vezměte truhlu smlouvy, a jděte před lidem. I vzali truhlu smlouvy a brali se před lidem.'),
(1552091,54,6,3,7,'Nebo řekl byl Hospodin k Jozue: V tento den začnu tebe zvelebovati před očima všeho Izraele, aby poznali, že jakož jsem byl s Mojžíšem, tak budu s tebou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552092,54,6,3,8,'Protož ty přikaž kněžím, kteříž nosí truhlu smlouvy, a rci: Když vejdete na kraj vody Jordánské, zastavte se v Jordáně.'),
(1552093,54,6,3,9,'Řekl také Jozue synům Izraelským: Přistupte sem, a slyšte slova Hospodina Boha vašeho.'),
(1552094,54,6,3,10,'I řekl Jozue: Po tomto poznáte, že Bůh silný živý jest u prostřed vás, a že konečně vyžene od tváři vaší Kananejského, Hetejského, Hevejského, Ferezejského, Gergezejského, Amorejského a Jebuzejského:'),
(1552095,54,6,3,11,'Aj, truhla smlouvy Panovníka vší země půjde před vámi přes Jordán.'),
(1552096,54,6,3,12,'Protož nyní vezměte sobě dvanácte mužů z pokolení Izraelských, po jednom muži z každého pokolení.'),
(1552097,54,6,3,13,'I bude, že hned jakž se zastaví kněží, nesoucí truhlu Hospodina Panovníka vší země, u vodě Jordánské, vody Jordánu rozdělí se, a vody tekoucí s vrchu zůstanou v jedné hromadě.'),
(1552098,54,6,3,14,'Stalo se tedy, když se bral lid z stanů svých, aby šli přes Jordán, a kněží, kteříž nesli truhlu smlouvy, před nimi,'),
(1552099,54,6,3,15,'A když ti, kteříž nesli truhlu, přišli až k Jordánu, a kněží, nesoucí truhlu, omočili nohy v kraji vod: (Jordán pak rozvodňuje se a vystupuje ze všech břehů svých v každý čas žně),'),
(1552100,54,6,3,16,'Že se zastavily vody, kteréž s hůry přicházely, a shrnuly se v hromadu jednu velmi daleko od Adam města, kteréž leží k straně Sartan, kteréž pak odcházely k moři dolů, k moři slanému sešly a sběhly, a lid přešel naproti Jerichu.'),
(1552101,54,6,3,17,'Stáli pak kněží, kteříž nesli truhlu smlouvy Hospodinovy na suše u prostřed Jordánu, nehýbajíce se, (a všecken Izrael šel po suše), až se lid všecken přepravil přes Jordán.'),
(1552102,54,6,4,1,'I stalo se, když již všecken národ přešel Jordán, (nebo byl řekl Hospodin k Jozue, řka:'),
(1552103,54,6,4,2,'Vezměte sobě z lidu dvanácte mužů, po jednom muži z každého pokolení,'),
(1552104,54,6,4,3,'A přikažte jim, řkouce: Vezměte sobě odsud z prostřed Jordánu, s místa, na němž stály nohy kněžské nepohnutě, dvanácte kamenů, a vyneste je s sebou, a sklaďte v ležení, v kterémž přes tuto noc pozůstanete),'),
(1552105,54,6,4,4,'Že povolav Jozue dvanácti mužů, kteréž k tomu zřídil z synů Izraelských, po jednom muži z každého pokolení,'),
(1552106,54,6,4,5,'I řekl jim Jozue: Jděte před truhlou Hospodina Boha svého do prostřed Jordánu a vezměte sobě každý kámen jeden na rameno své, vedlé počtu pokolení synů Izraelských,'),
(1552107,54,6,4,6,'Aby to bylo na znamení mezi vámi. Když by potom tázali se synové otců svých, řkouce: K čemu jsou vám ti kamenové?'),
(1552108,54,6,4,7,'Odpovíte jim, že se rozdělily vody Jordánské před truhlou smlouvy Hospodinovy, (když, pravím, šla přes Jordán, rozdělily se vody Jordánské), i zůstávají kamenové tito na památku synům Izraelským až na věky.'),
(1552109,54,6,4,8,'I učinili synové Izraelští tak, jakž přikázal Jozue, a vzali dvanácte kamenů z prostředku Jordánu, jakož mluvil Hospodin k Jozue, vedlé počtu pokolení synů Izraelských, a přinesli je s sebou na první stanoviště, a tu je složili.'),
(1552110,54,6,4,9,'Jozue také vyzdvihl dvanácte kamenů u prostřed Jordánu na místě, kdež stály nohy kněží nesoucích truhlu smlouvy, a byli tam až do tohoto dne.'),
(1552111,54,6,4,10,'Kněží pak, jenž nesli truhlu, stáli u prostřed Jordánu, dokudž se nevyplnilo všeliké slovo, kteréž přikázal Hospodin Jozue, aby oznámil lidu podlé všeho, jakž byl přikázal Mojžíš Jozue. I pospíšil lid a přešli.'),
(1552112,54,6,4,11,'Když pak již přešel všecken lid, přešla také truhla Hospodinova i kněží, an lid na to hledí.'),
(1552113,54,6,4,12,'Přešli i synové Rubenovi a synové Gádovi, a polovice pokolení Manassesova, vojensky zpořádaní před syny Izraelskými, jakož byl mluvil k nim Mojžíš.'),
(1552114,54,6,4,13,'Okolo čtyřidcíti tisíců oděných bojovníků šlo před Hospodinem k boji na roviny Jericha.'),
(1552115,54,6,4,14,'V ten den zvelebil Hospodin Jozue před očima všeho Izraele. I báli se ho, jako se báli Mojžíše po všecky dny života jeho.'),
(1552116,54,6,4,15,'Mluvil pak Hospodin k Jozue, řka:'),
(1552117,54,6,4,16,'Přikaž kněžím, kteříž nesou truhlu svědectví, ať vystoupí z Jordánu.'),
(1552118,54,6,4,17,'I přikázal Jozue kněžím, řka: Vystupte z Jordánu.'),
(1552119,54,6,4,18,'Když pak vystupovali kněží, jenž nesli truhlu smlouvy Hospodinovy, z prostřed Jordánu, jakž jen vytrhli kněží nohy na sucho, navrátily se vody Jordánské k místu svému, a tekly předce jako i prvé ve všech březích svých.'),
(1552120,54,6,4,19,'Vyšed pak lid z Jordánu desátého dne měsíce prvního, položili se v Galgala k straně východní Jericha;'),
(1552121,54,6,4,20,'A dvanácte kamenů těch, kteréž vynesli z Jordánu, postavil Jozue v Galgala.'),
(1552122,54,6,4,21,'A mluvil k synům Izraelským takto: Když by se otázali potom synové vaši otců svých, řkouce: Co ti kamenové znamenají?'),
(1552123,54,6,4,22,'Oznámíte synům svým a díte: Po suše přešel Izrael Jordán tento.'),
(1552124,54,6,4,23,'Nebo vysušil Hospodin Bůh váš vody Jordánské před tváří vaší, až jste přešli, jakož učinil Hospodin Bůh váš moři Rudému, kteréž vysušil před tváří naší, až jsme přešli,'),
(1552125,54,6,4,24,'Aby poznali všickni národové země ruku Hospodinovu, že silná jest, a abyste se báli Hospodina Boha vašeho po všecky dny.'),
(1552126,54,6,5,1,'Stalo se pak, když uslyšeli všickni králové Amorejští, kteříž bydlili za Jordánem k západu, a všickni králové Kananejští, kteříž bydlili při moři, že vysušil Hospodin vody Jordánské před syny Izraelskými, dokudž ho nepřešli: zemdlelo srdce jejich, aniž zůstalo více v nich duše před tváří synů Izraelských.'),
(1552127,54,6,5,2,'Toho času řekl Hospodin k Jozue: Udělej sobě nože ostré, a obřež opět syny Izraelské po druhé.'),
(1552128,54,6,5,3,'I udělal sobě Jozue nože ostré, a obřezal syny Izraelské na pahrbku Aralot.'),
(1552129,54,6,5,4,'Tato pak jest příčina, pro kterouž je obřezal Jozue, že všecken lid, kterýž byl vyšel z Egypta, pohlaví mužského, všickni muži bojovní zemřeli byli na poušti na cestě po vyjití z Egypta.'),
(1552130,54,6,5,5,'Nebo obřezán byl všecken lid, kterýž byl vyšel, ale žádného z toho lidu, kterýž se zrodil na poušti, na cestě po vyjití z Egypta, neobřezali.'),
(1552131,54,6,5,6,'(Nebo čtyřidceti let chodili synové Izraelští po poušti, dokudž nezahynul všecken národ mužů bojovných, kteříž byli vyšli z Egypta, ješto neposlouchali hlasu Hospodinova, jimžto zapřisáhl Hospodin, že neukáže jim země, kterouž s přísahou zaslíbil dáti otcům jejich, že ji nám dá, zemi oplývající mlékem a strdí.)'),
(1552132,54,6,5,7,'Ale syny jejich, kteréž postavil na místo jejich, ty obřezal Jozue, že byli neobřezaní; nebo žádný jich neobřezoval na cestě.'),
(1552133,54,6,5,8,'Když pak byl všecken lid obřezán, zůstali na místě svém v ležení, dokudž se nezhojili.'),
(1552134,54,6,5,9,'I řekl Hospodin k Jozue: Dnes jsem odjal pohanění Egyptské od vás. A nazval jméno místa toho Galgal až do tohoto dne.'),
(1552135,54,6,5,10,'Když pak ležení měli synové Izraelští v Galgala, slavili velikunoc čtrnáctého dne toho měsíce u večer, na rovinách Jericha.'),
(1552136,54,6,5,11,'I jedli z úrod té země na zejtří po velikonoci chleby nekvašené, a pražmu téhož dne.'),
(1552137,54,6,5,12,'I přestala manna na zejtří, když jedli z obilé té země, a již více neměli synové Izraelští manny, ale jedli z úrod země Kananejské toho roku.'),
(1552138,54,6,5,13,'Stalo se pak, když byl Jozue na poli Jericha, že pozdvihl očí svých a viděl, an muž stojí naproti němu, maje v ruce meč dobytý. I šel Jozue k němu, a řekl jemu: Jsi-li náš, čili nepřátel našich?'),
(1552139,54,6,5,14,'I odpověděl: Nikoli, ale já jsem kníže vojska Hospodinova, a nyní jsem přišel. I padl Jozue tváří svou na zem, a pokloniv se, řekl jemu: Co pán můj chce mluviti služebníku svému?'),
(1552140,54,6,5,15,'Tedy odpověděl kníže vojska Hospodinova k Jozue: Szuj obuv svou s noh svých, nebo místo, na němž stojíš, svaté jest. I učinil tak Jozue.'),
(1552141,54,6,6,1,'Jericho pak velmi pilně zavříno bylo pro strach synů Izraelských, a žádný nevycházel ven, ani tam nevcházel.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552142,54,6,6,2,'I řekl Hospodin k Jozue: Aj, dal jsem v ruku tvou Jericho, a krále jeho s silnými muži jeho.'),
(1552143,54,6,6,3,'Protož obcházeti budete město všickni muži bojovní, okolo města chodíce, jednou za den; tak učiníš po šest dní.'),
(1552144,54,6,6,4,'Kněží pak sedm ať nesou sedm trub z rohů beraních před truhlou; dne pak sedmého obejdete město sedmkrát, a kněží troubiti budou v trouby.'),
(1552145,54,6,6,5,'A když zdlouha troubiti budou na roh beraní, jakž nejprvé uslyšíte hlas trouby, zkřikne všecken lid křikem velikým, i oboří se zed městská na místě svém, a vejde lid do města, jeden každý proti místu, kdež stál.'),
(1552146,54,6,6,6,'Tedy povolav Jozue, syn Nun, kněží, řekl jim: Vezměte truhlu smlouvy, a sedm kněží ať vezmou sedm trub beraních před truhlou Hospodinovou.'),
(1552147,54,6,6,7,'Řekl také lidu: Jděte a obejděte město, a zbrojní ať jdou před truhlou Hospodinovou.'),
(1552148,54,6,6,8,'A když to oznámil Jozue lidu, sedm kněží, nesouce sedm trub beraních, šli před truhlou Hospodinovou, a troubili v trouby; truhla také smlouvy Hospodinovy brala se za nimi.'),
(1552149,54,6,6,9,'Zbrojní pak šli před kněžími, kteříž troubili na trouby, a ostatní šli za truhlou, jdouce a v trouby troubíce.'),
(1552150,54,6,6,10,'(Lidu pak byl přikázal Jozue, řka: Nebudete křičeti, ani slyšán bude hlas váš, ani vyjde slovo z úst vašich až do dne toho, v němž řeknu vám: Křičte, i budete křičeti.)'),
(1552151,54,6,6,11,'Tedy obešla truhla Hospodinova město vůkol jednou, a navrátili se do stanů a zůstali v nich.'),
(1552152,54,6,6,12,'Opět povstal Jozue ráno a kněží nesli truhlu Hospodinovu.'),
(1552153,54,6,6,13,'Sedm pak kněží, nesouce sedm trub beraních, předcházeli truhlu Hospodinovu, jdouce, a troubili v trouby; a zbrojní šli před nimi, a ostatní šli za truhlou Hospodinovou, když kněží šli, v trouby troubíce.'),
(1552154,54,6,6,14,'I obešli město druhého dne opět, a navrátili se do stanů. Tak činili po šest dní.'),
(1552155,54,6,6,15,'V den pak sedmý vstali, jakž zasvitávalo, a obešli město týmž způsobem sedmkrát; toliko toho dne obešli město sedmkrát.'),
(1552156,54,6,6,16,'Stalo se pak, když po sedmé obcházeli, a kněží v trouby troubili, řekl Jozue lidu: Křičtež již, dalť jest Hospodin vám město.'),
(1552157,54,6,6,17,'A budiž to město proklaté, ono i všecky věci, kteréž v něm jsou, Hospodinu; toliko Raab nevěstka ať jest živa, ona i všickni, kteříž by s ní byli v domě, nebo skryla posly, kteréž jsme byli poslali.'),
(1552158,54,6,6,18,'Avšak vystříhejte se od proklatého, abyste i vy nebyli učiněni proklatí, berouce z proklatých věcí, a uvedli byste stany Izraelské v prokletí, a zkormoutili byste je.'),
(1552159,54,6,6,19,'Všecko pak stříbro a zlato, a nádoby měděné a železné, svaté bude Hospodinu; na poklad Hospodinu složeno bude.'),
(1552160,54,6,6,20,'Tedy křičel lid, když zatroubili v trouby. Nebo když slyšel lid hlas trub, křičeli i oni křikem velikým, i obořila se zed na místě svém. Tedy všel lid do města, jeden každý proti místu, kdež stál. I vzali je.'),
(1552161,54,6,6,21,'A pohubili ostrostí meče jako proklaté všecko, což bylo v městě, od muže až do ženy, od dítěte až do starce, a až do vola, dobytčete i osla.'),
(1552162,54,6,6,22,'Dvěma pak mužům, kteříž shlédli zemi, řekl Jozue: Vejděte do domu ženy nevěstky, a vyveďte ji odtud, i všecky věci, kteréž má, jakož jste jí přisáhli.'),
(1552163,54,6,6,23,'I všedše mládenci špehéři, vyvedli Raab a otce jejího, i matku její a bratří její i všecko, což měla, a všecku rodinu její vyvedli, a nechali jich vně za stany Izraelskými.'),
(1552164,54,6,6,24,'Město pak spálili ohněm, i všecko, což v něm bylo, stříbro však a zlato a nádoby měděné a železné složili na poklad v domě Hospodinově.'),
(1552165,54,6,6,25,'Raab také nevěstku, a dům otce jejího i všecko, což měla, živé zůstavil Jozue; a bydlila v lidu Izraelském až do tohoto dne, nebo skryla posly, kteréž poslal Jozue k shlédnutí Jericha.'),
(1552166,54,6,6,26,'Toho času vydal klatbu Jozue, řka: Zlořečený buď před Hospodinem muž ten, kterýž by povstal, aby stavěl město Jericho. V prvorozeném svém založí je, a v nejmenším postaví brány jeho.'),
(1552167,54,6,6,27,'Byl pak Hospodin s Jozue, a rozhlásila se pověst o něm po vší zemi.'),
(1552168,54,6,7,1,'Zhřešili pak synové Izraelští přestoupením při věcech proklatých; nebo Achan, syn Charmi, syna Zabdi, syna Záre, z pokolení Juda, vzal něco z věcí proklatých. Pročež rozpálila se prchlivost Hospodinova na syny Izraelské.'),
(1552169,54,6,7,2,'Nebo když poslal Jozue muže některé od Jericha do Hai, kteréž bylo blízko Betaven, k východní straně Bethel, a mluvil k nim, řka: Vstupte a shlédněte zemi, vstoupili tedy muži ti, a shlédli Hai.'),
(1552170,54,6,7,3,'Kteřížto navrátivše se k Jozue, řekli jemu: Nechť nevstupuje všecken lid tento, okolo dvou tisíc mužů neb okolo tří tisíců mužů nechť vstoupí, a dobudouť Hai; neobtěžuj všeho lidu, vysílaje jej tam, nebo málo jest oněchno.'),
(1552171,54,6,7,4,'Tedy vytáhlo jich z lidu tam okolo tří tisíc mužů, a utekli před muži města Hai.'),
(1552172,54,6,7,5,'I zabili z nich obyvatelé Hai okolo třidcíti a šesti mužů, a honili je od brány až k Sabarim, a porazili je, když s vrchu utíkali. I rozpustilo se srdce lidu, a bylo jako voda.'),
(1552173,54,6,7,6,'Tedy Jozue roztrhl roucho své, a padl tváří svou na zem před truhlou Hospodinovou, a ležel až do večera, ano i starší Izraelští, a sypali prach na hlavy své.'),
(1552174,54,6,7,7,'I řekl Jozue: Ach, Panovníče Hospodine, proč jsi kdy převedl lid tento přes Jordán, abys nás vydal v ruku Amorejského, tak aby nás zahubil? Ó kdybychom byli raději zůstali za Jordánem.'),
(1552175,54,6,7,8,'Ó Pane, což mám říci, když již lid Izraelský utíká před nepřátely svými?'),
(1552176,54,6,7,9,'Nebo uslyšíce Kananejští a všickni obyvatelé země, obklíčí nás vůkol, a vyhladí jméno naše z země. I což to učiníš jménu svému velikému?'),
(1552177,54,6,7,10,'I řekl Hospodin k Jozue: Vstaň. Proč jsi padl na tvář svou?'),
(1552178,54,6,7,11,'Zhřešil Izrael, tak že smlouvu mou přestoupili, kterouž jsem jim přikázal; nebo jsou i vzali z věcí proklatých, k tomu i ukradli, také i sklamali, nad to i odložili mezi nádobí svá.'),
(1552179,54,6,7,12,'Protož nebudou moci synové Izraelští ostáti před nepřátely svými, utíkati budou před nepřátely svými, nebo poškvrnili se věcí proklatou. Nebuduť více s vámi, leč vyhladíte prokletí to z prostředku svého.'),
(1552180,54,6,7,13,'Vstaň, posvěť lidu a rci: Posvěťte se k zítřku; nebo takto praví Hospodin Bůh Izraelský: Věc proklatá jest u prostřed tebe, Izraeli, nebudeš moci ostáti před nepřátely svými, dokudž neodejmeš prokletí toho z prostředku svého.'),
(1552181,54,6,7,14,'Protož přistupovati budete ráno po pokoleních svých, a pokolení, kteréž ukáže Hospodin, přistupovati bude po rodech, takž rod, kterýž ukáže Hospodin, přistupovati bude po domích, a dům, kterýž ukáže Hospodin, přistupovati bude po osobách.'),
(1552182,54,6,7,15,'Kdož pak postižen bude vinný věcí proklatou, ohněm spálen bude, on i všecko, což jeho jest, proto že přestoupil smlouvu Hospodinovu, a že učinil nešlechetnost v Izraeli.'),
(1552183,54,6,7,16,'Vstav tedy Jozue ráno, kázal přistupovati Izraelovi po pokoleních jejich. I postiženo jest pokolení Judovo.'),
(1552184,54,6,7,17,'Tedy když kázal přistupovati čeledem Juda, postižena jest čeled Záre. Potom kázal přistupovati čeledi Záre po osobách, a postižen jest Zabdi.'),
(1552185,54,6,7,18,'I kázal přistupovati domu jeho po osobách, i postižen jest Achan, syn Charmi, syna Zabdi, syna Záre z pokolení Judova.'),
(1552186,54,6,7,19,'I řekl Jozue Achanovi: Synu můj, dej, prosím, chválu Hospodinu Bohu Izraelskému, a vyznej se jemu, a oznam mi aspoň již, co jsi učinil, netaj již toho přede mnou.'),
(1552187,54,6,7,20,'Tedy odpovídaje Achan k Jozue, řekl: Pravdať jest, já jsem zhřešil proti Hospodinu Bohu Izraelskému, tak že to a toto jsem učinil.'),
(1552188,54,6,7,21,'Viděl jsem mezi loupeží plášť jeden Babylonský pěkný, a dvě stě lotů stříbra, a prut zlatý jeden, padesáte lotů ztíží, čehož požádav, vzal jsem to, a aj, jsou ty věci skryté v zemi prostřed stanu mého, a stříbro pod tím.'),
(1552189,54,6,7,22,'Tedy poslal Jozue posly, kteříž běželi do stanu, a aj, bylo to skryto v stanu jeho, a stříbro pod tím.'),
(1552190,54,6,7,23,'A vzavše to z stanu, přinesli k Jozue a ke všechněm synům Izraelským, a položili ty věci před Hospodinem.'),
(1552191,54,6,7,24,'Vzav tedy Jozue a všecken Izrael s ním Achana, syna Záre, a stříbro i plášť, i prut zlatý, i syny jeho, i dcery jeho, voly a osly, dobytek i stan jeho i všecko, což měl, vyvedli je do údolí Achor.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552192,54,6,7,25,'Kdež řekl Jozue: Proč jsi zkormoutil nás? Zkormutiž tebe Hospodin v tento den. I uházel jej všecken lid kamením, a spálili je ohněm, ukamenovavše je kamením.'),
(1552193,54,6,7,26,'Potom nametali naň hromadu kamení velikou, kteráž trvá až do tohoto dne; a tak odvrácen jest Hospodin od hněvu prchlivosti své. Protož nazváno jest jméno místa toho údolí Achor, až do dnešního dne.'),
(1552194,54,6,8,1,'I řekl Hospodin k Jozue: Neboj se, ani se strachuj; pojmi s sebou všecken lid bojovný, a vstana, táhni k Hai. Aj, dal jsem v ruku tvou krále Hai a lid jeho, město i zemi jeho.'),
(1552195,54,6,8,2,'A učiníš Hai a králi jeho, jako jsi učinil Jerichu a králi jeho, loupež však a dobytky jeho rozbitujete mezi sebe. Zdělejž sobě zálohy k městu po zadu.'),
(1552196,54,6,8,3,'Tedy vstal Jozue a všecken lid bojovný, aby táhli k Hai. I vybral Jozue třidcet tisíců mužů velmi silných, a předeslal je v noci.'),
(1552197,54,6,8,4,'A přikázal jim, řka: Šetřtež vy, kteříž uděláte zálohy městu po zadní straně města, abyste nebyli příliš daleko od něho, ale buďte všickni pohotově.'),
(1552198,54,6,8,5,'Já pak i všecken lid, kterýž se mnou jest, přitáhneme k městu. A když oni nám vyjdou vstříc, jako prvé, utíkati budeme před nimi.'),
(1552199,54,6,8,6,'Tedy honiti budou nás, až bychom poodvedli jich od města, (nebo řeknou: Utíkají před námi, jako prvé), utíkajíce před nimi.'),
(1552200,54,6,8,7,'Vy mezi tím vyskočíte z záloh, a vyženete ostatní obyvatele města, nebo dá je Hospodin Bůh váš v ruku vaši.'),
(1552201,54,6,8,8,'A když vezmete město, zapálíte je ohněm, podlé slova Hospodinova učiníte; šetřtež toho, což jsem přikázal vám.'),
(1552202,54,6,8,9,'I poslal Jozue, a oni šli k zálohám, a zůstali mezi Bethel a Hai, od západní strany Hai; Jozue pak zůstal té noci u prostřed lidu.'),
(1552203,54,6,8,10,'Potom vstav Jozue velmi ráno, sečtl lid, i bral se napřed, on a starší Izraelští před lidem k Hai.'),
(1552204,54,6,8,11,'Všecken také lid bojovný, kterýž byl s ním, táhnouce, přiblížili se, až přišli naproti městu, a položili se po straně půlnoční Hai; údolí pak bylo mezi nimi a mezi Hai.'),
(1552205,54,6,8,12,'Vzal pak byl okolo pěti tisíc mužů, kteréž postavil v zálohách mezi Bethel a Hai, od západní stany města.'),
(1552206,54,6,8,13,'I přiblížil se lid, totiž všecko vojsko, kteréž bylo od půlnoční strany města, a kteříž byli v zálohách jeho od západní strany města; a tak vtáhl Jozue noci té do prostřed údolí.'),
(1552207,54,6,8,14,'I stalo se, že když je uzřel král Hai, pospíšili, a ráno vstavše, vyšli lidé města vstříc Izraelovi k boji, on i všecken lid jeho toho času před rovinu; nevěděl pak, že zálohy udělány byly jemu po zadu města.'),
(1552208,54,6,8,15,'I postoupil Jozue a všecken Izrael před nimi, a utíkali cestou pouště.'),
(1552209,54,6,8,16,'I svolán jest všecken lid v městě, aby je honili. I honili Jozue, a vzdálili se od města svého,'),
(1552210,54,6,8,17,'Tak že nezůstal žádný z obyvatelů Hai a Bethel, kdo by nevyšel, aby honil Izraele; a nechali města otevřeného, a honili Izraele.'),
(1552211,54,6,8,18,'Řekl pak Hospodin k Jozue: Zdvihni korouhev, kterouž máš v rukou svých, proti Hai, nebo v ruce tvé dám je. I zdvihl Jozue korouhev, kterouž měl v ruce své, proti městu.'),
(1552212,54,6,8,19,'Tedy, kteříž byli v zálohách, rychle vyskočili z místa svého, a běželi, když pozdvihl ruky své, a všedše do města, vzali je, a spěšně zapálili město ohněm.'),
(1552213,54,6,8,20,'Muži pak města Hai ohlédše se nazpět, uzřeli, a aj, vstupoval dým města k nebi, a neměli místa k utíkání sem ani tam; nebo lid, kterýž utíkati počal k poušti, obrátil se na ty, kteříž je honili.'),
(1552214,54,6,8,21,'Jozue zajisté a všecken Izrael, když viděli, že z záloh vzali město, a že se vznáší dým města, obrátili se, a bili muže Hai.'),
(1552215,54,6,8,22,'Onino také vyšli z města proti nim, a obklíčil Izrael nepřátely své, jedni odsud, druzí od onud; a zmordovali je, tak že žádný živ nezůstal ani neušel.'),
(1552216,54,6,8,23,'Ale krále Hai jali živého, a přivedli ho k Jozue.'),
(1552217,54,6,8,24,'Když pak pomordoval Izrael všecky obyvatele Hai v poli, totiž na poušti, kamž je honili, a padli ti všickni od ostrosti meče, až i zahlazeni jsou: navrátil se všecken Izrael do Hai, a zmordovali ostatky jeho mečem.'),
(1552218,54,6,8,25,'A bylo všech, kteříž padli v ten den, od muže až do ženy, dvanácte tisíců; všickni ti byli z Hai.'),
(1552219,54,6,8,26,'Ale Jozue nespustil ruky své, kterouž vyzdvihl korouhev, dokudž nebyli zmordováni všickni obyvatelé Hai.'),
(1552220,54,6,8,27,'Toliko hovada a loupež města toho rozbitovali mezi sebou synové Izraelští podlé slova Hospodinova, kteréž on přikázal Jozue.'),
(1552221,54,6,8,28,'Tedy vypálil Jozue Hai, a položil je v hromadu věčnou a pustinu, až do tohoto dne.'),
(1552222,54,6,8,29,'Krále pak Hai oběsil na dřevě, a nechal ho tam až do večera. A když zapadlo slunce, rozkázal Jozue, aby složili tělo jeho s dřeva, a povrhli je u brány města, a nametali na ně hromadu kamení velikou, kteráž trvá až do dnešního dne.'),
(1552223,54,6,8,30,'Tedy vzdělal Jozue oltář Hospodinu Bohu Izraelskému na hoře Hébal,'),
(1552224,54,6,8,31,'(Jakož přikázal Mojžíš, služebník Hospodinův, synům Izraelským, jakož psáno jest v knize zákona Mojžíšova,) oltář z kamení celého, nad nímž nebylo zdviženo železo, a obětovali na něm oběti zápalné Hospodinu, obětovali i oběti pokojné.'),
(1552225,54,6,8,32,'Napsal také tam na kameních výpis zákona Mojžíšova, kterýž psal před syny Izraelskými.'),
(1552226,54,6,8,33,'Všecken pak Izrael a starší jeho, i správcové i soudcové jeho stáli po obou stranách truhly před kněžími Levítskými, kteříž nosili truhlu smlouvy Hospodinovy, tak cizí jako doma zrozený, polovice jich proti hoře Garizim, a polovice proti hoře Hébal, jakož byl prvé přikázal Mojžíš, služebník Hospodinův, aby dobrořečil lidu Izraelskému nejprvé.'),
(1552227,54,6,8,34,'A potom četl všecka slova zákona, požehnání i zlořečení, tak jakž psáno jest v knize zákona.'),
(1552228,54,6,8,35,'Nebylo ani slova ze všeho, což přikázal Mojžíš, jehož by nečetl Jozue přede vším shromážděním Izraelským, i ženami i dětmi i příchozími, kteříž šli u prostřed nich.'),
(1552229,54,6,9,1,'To když uslyšeli všickni králové, kteříž bydlili za Jordánem, na horách i na rovinách, a na všem břehu moře velikého naproti Libánu: Hetejský, Amorejský, Kananejský, Ferezejský, Hevejský a Jebuzejský,'),
(1552230,54,6,9,2,'Sebrali se spolu, aby bojovali proti Jozue a proti Izraeli jednomyslně.'),
(1552231,54,6,9,3,'Ale obyvatelé Gabaon uslyšavše, co učinil Jozue Jerichu a Hai,'),
(1552232,54,6,9,4,'Učinili i oni chytře. Nebo odšedše, ukázali se, jako by zdaleka poslové byli, a vzali pytle staré na osly své, a kožené láhvice vinné vetché, zedrané a zzašívané,'),
(1552233,54,6,9,5,'Obuv také starou a splácenou na nohy své, též šaty otřelé na sebe; a všecken chléb, kterýž sobě na cestu vzali, vyschlý byl a zdrobený.'),
(1552234,54,6,9,6,'I šli k Jozue do ležení v Galgala, a řekli jemu i mužům Izraelským: Z země daleké jsme přišli, protož nyní učiňte s námi smlouvu.'),
(1552235,54,6,9,7,'Tedy odpověděli muži Izraelští k Hevejským: Snad u prostřed nás vy bydlíte, i kterakž bychom s vámi učinili smlouvu?'),
(1552236,54,6,9,8,'Ale oni odpověděli Jozue: Služebníci tvoji jsme. Jimž řekl Jozue: Kdo pak jste, a odkud jste přišli?'),
(1552237,54,6,9,9,'Odpověděli jemu: Z země velmi daleké přišli služebníci tvoji ve jménu Hospodina Boha tvého; nebo jsme slyšeli pověst jeho a všecky věci, kteréž činil v Egyptě.'),
(1552238,54,6,9,10,'A všecko, což učinil dvěma králům Amorejským, kteříž bydlili za Jordánem, Seonovi, králi Ezebon, a Ogovi, králi Bázan, kterýž byl v Astarot.'),
(1552239,54,6,9,11,'I řekli nám starší naši a všickni obyvatelé země naší těmito slovy: Nabeřte sobě potravy na cestu, a jděte jim vstříc, a rcete jim: Služebníci vaši jsme, protož nyní učiňte s námi smlouvu.'),
(1552240,54,6,9,12,'Totoť jest chléb náš; horký jsme na cestu vzali z domů svých v ten den, když jsme vyšli, abychom k vám šli, a hle, nyní již vyschl a zdrobil se.'),
(1552241,54,6,9,13,'A tyto kožené láhvice vinné nové byly, když jsme je naplnili, a již hle, potrhané jsou; tolikéž tento oděv náš a obuv naše zvetšela, pro přílišnou cesty dalekost.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552242,54,6,9,14,'I přijali to muži ti z pokrmů jejich, a úst Hospodinových neotázali se.'),
(1552243,54,6,9,15,'A učinil s nimi Jozue pokoj, a všel s nimi v smlouvu, aby jich při životu zanechal; také i knížata shromáždění přísahu jim učinili.'),
(1552244,54,6,9,16,'Po třech pak dnech, po té smlouvě s nimi učiněné, uslyšeli, že by velmi blízko jich byli, a že by u prostřed nich bydlili.'),
(1552245,54,6,9,17,'Jdouce tedy synové Izraelští, přitáhli k městům jejich třetího dne; města pak jejich byla Gabaon a Kafira a Berot a Kariatjeharim.'),
(1552246,54,6,9,18,'Ale nezbili jich synové Izraelští, proto že přísahu jim učinili knížata shromáždění skrze Hospodina Boha Izraelského. A reptalo všecko shromáždění proti knížatům.'),
(1552247,54,6,9,19,'Tedy řekla všecka knížata všemu shromáždění: My jsme jim přísahu učinili skrze Hospodina Boha Izraelského, protož nyní nemůžeme se jich dotknouti.'),
(1552248,54,6,9,20,'Toto jim učiníme: Zanecháme jich při životu, aby nebylo na nás rozhněvání pro přísahu, kterouž jsme jim učinili.'),
(1552249,54,6,9,21,'Řekli jim knížata i to: Nechť jsou živi a drva sekají, a vodu nosí všemu shromáždění. I přestali na tom, jakož jim mluvila knížata.'),
(1552250,54,6,9,22,'Povolal jich pak Jozue a mluvil k nim, řka: Proč jste nás podvedli, řkouce: Velmi jsme dalecí od vás? A vy u prostřed nás bydlíte.'),
(1552251,54,6,9,23,'Protož nyní zlořečení jste, a nepřestanou z vás služebníci, a kteříž by dříví sekali a vodu nosili do domu Boha mého.'),
(1552252,54,6,9,24,'Kteříž odpovídajíce Jozue, řekli: Za věc jistou oznámeno bylo služebníkům tvým, kterak přikázal Hospodin Bůh tvůj Mojžíšovi služebníku svému, dáti vám zemi tuto, a vyhladiti všecky obyvatele země této před tváří vaší; protož strachovali jsme se vás, bojíce se za životy své před vámi, a učinili jsme to.'),
(1552253,54,6,9,25,'A hle, nyní v ruce tvé jsme; cožť se dobrého a spravedlivého vidí učiniti s námi, to učiň.'),
(1552254,54,6,9,26,'I učinil jim tak, a vysvobodil je z rukou synů Izraelských, aby jich nepobili.'),
(1552255,54,6,9,27,'A ustanovil je Jozue v ten den, aby dříví sekali a vodu nosili všemu shromáždění, i k oltáři Hospodinovu, až do tohoto dne, na místě, kteréž by vyvolil.'),
(1552256,54,6,10,1,'Uslyšev pak Adonisedech, král Jeruzalémský, že Jozue vzal město Hai, a jako proklaté zkazil je, (nebo jakž učinil Jerichu a králi jeho, tak učinil Hai a králi jeho,) a že pokoj učinili obyvatelé Gabaon s Izraelem, a bydlí u prostřed něho,'),
(1552257,54,6,10,2,'I bál se velmi, proto že město veliké bylo Gabaon, jako jedno z měst královských, a že bylo větší než Hai, a všickni muži jeho udatní.'),
(1552258,54,6,10,3,'Protož poslal Adonisedech, král Jeruzalémský, k Ohamovi, králi Hebron, a k Faramovi, králi Jarmut, a k Jafiovi, králi Lachis, a k Dabirovi, králi Eglon, řka:'),
(1552259,54,6,10,4,'Sjeďte se ke mně, a pomozte mi, abychom dobyli Gabaon, proto že pokoj učinili s Jozue a s syny Izraelskými.'),
(1552260,54,6,10,5,'I shromáždilo se a vytáhlo pět králů Amorejských, král Jeruzalémský, král Hebron, král Jarmut, král Lachis, král Eglon, oni i všecka vojska jejich, a položivše se u Gabaon, dobývali ho.'),
(1552261,54,6,10,6,'Tedy poslali muži Gabaon k Jozue do ležení v Galgala, řkouce: Neodjímejž ruky své od služebníků svých; přitáhni rychle k nám, zachovej nás a spomoz nám; nebo sebrali se proti nám všickni králové Amorejští bydlící na horách.'),
(1552262,54,6,10,7,'I táhl Jozue z Galgala, on i všecken lid bojovný s ním, všickni muži udatní.'),
(1552263,54,6,10,8,'(Nebo byl řekl Hospodin k Jozue: Neboj se jich, v ruce tvé zajisté dal jsem je, neostojíť žádný z nich před oblíčejem tvým.)'),
(1552264,54,6,10,9,'I připadl na ně Jozue v náhle, nebo celou noc táhl z Galgala.'),
(1552265,54,6,10,10,'A potřel je Hospodin před Izraelem, kterýžto pobil je ranou velikou u Gabaon, a honil je cestou, kudy se jde k Betoron, a bil je až do Azeka a až do Maceda.'),
(1552266,54,6,10,11,'I stalo se, když utíkali před tváří Izraele, sstupujíce do Betoron, že Hospodin metal na ně kamení veliké s nebe, až k Azeku, a mřeli. Více jich zemřelo od krupobití kamenného, než jich pobili synové Izraelští mečem.'),
(1552267,54,6,10,12,'Tedy mluvil Jozue k Hospodinu v den, v kterýž dal Hospodin Amorejského v moc synům Izraelským, a řekl před syny Izraelskými: Slunce v Gabaon zastav se, a měsíc v údolí Aialon.'),
(1552268,54,6,10,13,'I zastavilo se slunce, a stál měsíc, dokudž nepomstil se lid nad nepřátely svými. Zdali není toho napsáno v knize Upřímého? Tedy stálo slunce u prostřed nebe, a nepospíchalo k západu, jako za jeden celý den.'),
(1552269,54,6,10,14,'Nebylo dne takového prvé ani potom, jako když vyslyšel Hospodin hlas člověka; nebo Hospodin bojoval za Izraele.'),
(1552270,54,6,10,15,'I navracel se Jozue i všecken Izrael s ním do táboru v Galgala.'),
(1552271,54,6,10,16,'Uteklo pak bylo těch králů pět, a skryli se v jeskyni při Maceda.'),
(1552272,54,6,10,17,'I oznámeno bylo Jozue těmi slovy: Nalezeno jest pět králů, kteříž se skryli v jeskyni při Maceda.'),
(1552273,54,6,10,18,'I řekl Jozue: Přivalte kamení veliké k díře té jeskyně, a osaďte ji muži, aby ostříhali jich.'),
(1552274,54,6,10,19,'Vy pak nezastavujte se, hoňte nepřátely své, a bíte je po zadu, a nedejte jim vjíti do měst jejich, nebo dal je Hospodin Bůh váš v ruku vaši.'),
(1552275,54,6,10,20,'Když pak přestali Jozue a synové Izraelští bíti jich porážkou velikou velmi, až i zahlazeni byli; a kteříž živi pozůstali z nich, utekli do měst hrazených:'),
(1552276,54,6,10,21,'Navrátil se všecken lid do ležení k Jozue do Maceda ve zdraví; nepohnul proti synům Izraelským žádný jazykem svým.'),
(1552277,54,6,10,22,'Potom řekl Jozue: Odhraďte díru u jeskyně, a vyveďte ke mně pět králů těch z jeskyně.'),
(1552278,54,6,10,23,'I učinili tak, a vyvedli k němu pět králů těch z jeskyně, krále Jeruzalémského, krále Hebron, krále Jarmut, krále Lachis, krále Eglon.'),
(1552279,54,6,10,24,'A když vyvedli ty krále k Jozue, svolav všecky muže Izraelské, řekl vývodám mužů bojovných, kteříž s ním v tažení tom byli: Přistupte sem, a šlapejte nohama svýma na hrdla těch králů. Kteřížto přistoupivše, šlapali nohama svýma na hrdla jejich.'),
(1552280,54,6,10,25,'I řekl jim Jozue: Nebojte se ani strachujte, posilňte se a buďte zmužilí, nebo tak učiní Hospodin všechněm nepřátelům vašim, proti nimž bojujete.'),
(1552281,54,6,10,26,'Potom bil je Jozue a zmordoval, a pověsil je na pěti dřevích; a viseli na dřevích až do večera.'),
(1552282,54,6,10,27,'Když pak zapadlo slunce, k rozkazu Jozue složili je s dřev, a uvrhli je do jeskyně, v kteréž se byli skryli, a přivalili kamení veliké k díře jeskyně, kteréž jest tu až do tohoto dne.'),
(1552283,54,6,10,28,'Téhož dne také dobyl Jozue Maceda, a pohubil je mečem, i krále jejich pobil spolu s nimi, a všecky lidi, kteříž byli v něm. Neživil žádného, ale učinil králi Maceda, jako učinil králi Jericha.'),
(1552284,54,6,10,29,'Táhl potom Jozue a všecken Izrael s ním z Maceda k Lebnu, a dobýval Lebna.'),
(1552285,54,6,10,30,'I vydal je také Hospodin v ruku Izraelovi i krále jeho, a pobil je mečem, a všecky duše, kteréž byly v něm; nenechal tam žádného živého, a učinil králi jeho, jako učinil králi Jericha.'),
(1552286,54,6,10,31,'Táhl také Jozue a všecken Izrael s ním z Lebna do Lachis, a položivše se u něho, dobývali ho.'),
(1552287,54,6,10,32,'I dal Hospodin Lachis v ruku Izraele, a dobyl ho druhého dne, a pohubil je mečem i všecky lidi, kteříž byli v něm, rovně tak, jakž učinil Lebnu.'),
(1552288,54,6,10,33,'Tehdy přitáhl Horam, král Gázer, aby pomoc dal Lachis. I porazil jej Jozue i lid jeho, tak že nepozůstavil žádného živého.'),
(1552289,54,6,10,34,'Táhl potom Jozue a všecken Izrael s ním z Lachis do Eglon, a položivše se naproti, bojovali proti němu.'),
(1552290,54,6,10,35,'A vzali je toho dne, a pobili je mečem, a všecky duše, kteréž byly v něm, dne toho pomordovali, rovně tak, jakž učinili Lachis.'),
(1552291,54,6,10,36,'Vstoupil pak Jozue a všecken Izrael s ním z Eglon do Hebron, a dobývali ho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552292,54,6,10,37,'I vzali je a zhubili mečem i krále jeho, i všecka města jeho, i každého člověka, kterýž byl v něm; nepozůstavil žádného živého, podobně tak, jakož učinil Eglon. I zahladil je i všelikou duši, kteráž byla v něm.'),
(1552293,54,6,10,38,'Potom navracuje se Jozue a všecken Izrael s ním, přišli do Dabir, a dobýval ho.'),
(1552294,54,6,10,39,'I vzal je a krále jeho i všecka města jeho, a pohubili je mečem, a všelikou duši, kteráž byla v něm, jako proklaté vyhladili. Nepozůstavili žádného živého; jakož učinil Hebron, tak učinil Dabir i králi jeho, a jakož učinil Lebnu a králi jeho.'),
(1552295,54,6,10,40,'A tak pohubil Jozue všecku zemi po horách, i polední stranu, i roviny a údolí, i všecky krále jejich. Nepozůstavil žádného živého, ale všelikou duši vyhladil, jakož přikázal Hospodin Bůh Izraelský.'),
(1552296,54,6,10,41,'Pohubil tedy Jozue všecko od Kádesbarne až do Gázy, a všecku zemi Gosen až do Gabaon.'),
(1552297,54,6,10,42,'A všecky krále ty a zemi jejich vzal Jozue pojednou, nebo Hospodin Bůh Izraelský bojoval za Izraele.'),
(1552298,54,6,10,43,'Potom navrátil se Jozue a všecken Izrael s ním do ležení, kteréž bylo v Galgala.'),
(1552299,54,6,11,1,'To když uslyšel Jabín, král Azor, poslal k Jobábovi, králi Mádon, a k králi Simron, a k králi Achzaf,'),
(1552300,54,6,11,2,'I k králům, kteříž bydlili k straně půlnoční na horách i na rovinách ku polední Ceneret, i na rovinách a v krajinách Dor na západ,'),
(1552301,54,6,11,3,'K Kananejskému na východ i na západ, a k Amorejskému, Hetejskému, Ferezejskému a Jebuzejskému na horách, a k Hevejskému pod horou Hermon v zemi Masfa.'),
(1552302,54,6,11,4,'I vytáhli všickni ti a všecka vojska jejich s nimi, lid mnohý jako písek, kterýž jest na břehu mořském nesčíslný, i koňů i vozů velmi mnoho.'),
(1552303,54,6,11,5,'A smluvivše se všickni králové ti, přitáhli a položili se spolu při vodách Merom, aby bojovali proti Izraelovi.'),
(1552304,54,6,11,6,'Řekl pak Hospodin k Jozue: Neboj se jich, nebo zítra o této chvíli vydám všecky tyto k zabití Izraelovi; koňům jejich žily podřežeš, a vozy jejich ohněm spálíš.'),
(1552305,54,6,11,7,'Tedy vytáhl Jozue a s ním všecken lid válečný proti nim k vodám Merom rychle, a udeřili na ně.'),
(1552306,54,6,11,8,'I dal je Hospodin v ruku Izraelovi, a porazili je. I honili je až k Sidonu velikému, a až k vodám Maserefot, a k údolí Masfe na východ, a pobili je, tak že nepozůstavili žádného živého.'),
(1552307,54,6,11,9,'A učinil jim Jozue, jakož byl rozkázal jemu Hospodin, koňům jejich žily zpodřezoval, a vozy jejich ohněm popálil.'),
(1552308,54,6,11,10,'Potom navrátiv se Jozue téhož času, dobyl Azor, a krále jeho zabil mečem. Azor pak bylo prvé nejznamenitější mezi všemi království těmi.'),
(1552309,54,6,11,11,'Pobili také všecko, cožkoli v něm živo bylo, mordujíce je mečem, tak že nezůstalo žádného živého; Azor pak spálil ohněm.'),
(1552310,54,6,11,12,'Takž podobně učinil všechněm městům králů těch, a všecky krále jejich zjímal Jozue, a zbiv je mečem, vyhladil je, jakož přikázal Mojžíš, služebník Hospodinův.'),
(1552311,54,6,11,13,'A však žádného města z těch, kteráž ještě zůstala v ohradě své, nespálil Izrael, kromě samého Azor, kteréž spálil Jozue.'),
(1552312,54,6,11,14,'A všecky loupeže měst těch i hovada rozdělili mezi sebou synové Izraelští; toliko všecky lidi zbili mečem, dokudž nevyhladili jich, nenechavše žádného živého.'),
(1552313,54,6,11,15,'Jakož byl přikázal Hospodin Mojžíšovi, služebníku svému, tak přikázal Mojžíš Jozue, a Jozue tak činil; nepominul ničeho toho, což byl přikázal Hospodin Mojžíšovi.'),
(1552314,54,6,11,16,'A tak vzal Jozue všecku tu zemi, hory i všecku stranu polední, i všecku zemi Gosen, i roviny, i pole, totiž hory Izraelské i roviny jejich,'),
(1552315,54,6,11,17,'Od hory Halak, kteráž se táhne do Seir, až k Balgad na rovině Libánské, pod horou Hermon; všecky také krále jejich zjímal, a zbil je i zmordoval.'),
(1552316,54,6,11,18,'Po mnohé dny Jozue vedl válku se všechněmi těmi králi.'),
(1552317,54,6,11,19,'A nebylo města, ješto by v pokoj vešlo s syny Izraelskými, kromě Hevejských obyvatelů v Gabaon; jiná všecka válkou vzali.'),
(1552318,54,6,11,20,'Nebo od Hospodina to bylo, že jsou zatvrdili byli srdce své, tak aby vyšli válečně proti Izraelovi, a aby je v prokletí vydal, a neučinil jim milosti, ale aby je zahubil, jakož přikázal Hospodin Mojžíšovi.'),
(1552319,54,6,11,21,'Toho pak času přitáhl Jozue a vyplénil Enaky z těch hor, totiž z Hebronu, z Dabir a z Anab, i ze všeliké hory Judské, a ze všeliké hory Izraelské; spolu s městy jejich vyhladil je Jozue.'),
(1552320,54,6,11,22,'Nezůstal žádný z Enaků v zemi synů Izraelských; toliko v Gáze, v Gát a v Azotu zůstali.'),
(1552321,54,6,11,23,'Tak tedy vzal Jozue všecku tu zemi, jakž byl rozkázal Hospodin Mojžíšovi, a dal ji Jozue v dědictví Izraelovi vedlé dílů jejich, po pokoleních jejich. I odpočinula země od válek.'),
(1552322,54,6,12,1,'Tito pak jsou králové té země, kteréž pobili synové Izraelští, a opanovali zemi jejich, za Jordánem k východu slunce, od potoku Arnon až k hoře Hermon i všecky roviny k východu:'),
(1552323,54,6,12,2,'Seon, král Amorejský, kterýž bydlil v Ezebon, a panoval od Aroer, kteréž leží při břehu potoka Arnon, a u prostřed potoka toho, a polovici Galád, až do potoka Jabok, kterýž jest na pomezí synů Ammon,'),
(1552324,54,6,12,3,'A od rovin až k moři Ceneret k východu, a až k moři pouště, jenž jest moře slané k východu, kudyž se jde k Betsimot, a od polední strany ležící pod horou Fazga.'),
(1552325,54,6,12,4,'Pomezí také Oga, krále Bázan, z ostatků Refaimských, kterýž bydlil v Astarot a v Edrei,'),
(1552326,54,6,12,5,'A kterýž panoval na hoře Hermon a v Sálecha, i ve vší krajině Bázan až ku pomezí Gessuri a Machati, a nad polovicí Galád, ku pomezí Seona, krále Ezebon.'),
(1552327,54,6,12,6,'Mojžíš, služebník Hospodinův, a synové Izraelští pobili je; a dal ji Mojžíš služebník Hospodinův k vládařství pokolení Rubenovu, Gádovu a polovici pokolení Manassesova.'),
(1552328,54,6,12,7,'Tito pak jsou králové země té, kteréž pobil Jozue a synové Izraelští za Jordánem k západu, od Balgad, kteréž jest na poli Libánském, až k hoře lysé, kteráž se táhne až do Seir, a dal ji Jozue pokolením Izraelským k vládařství po dílích jejich,'),
(1552329,54,6,12,8,'Na horách i na rovinách, i po polích, i v údolích, i na poušti a na poledne, zemi Hetejského, Amorejského, Kananejského, Ferezejského, Hevejského a Jebuzejského:'),
(1552330,54,6,12,9,'Král Jericha jeden, král Hai, kteréž bylo na straně Bethel, jeden;'),
(1552331,54,6,12,10,'Král Jeruzalémský jeden, král Hebron jeden;'),
(1552332,54,6,12,11,'Král Jarmut jeden, král Lachis jeden;'),
(1552333,54,6,12,12,'Král Eglon jeden, král Gázer jeden;'),
(1552334,54,6,12,13,'Král Dabir jeden, král Gader jeden;'),
(1552335,54,6,12,14,'Král Horma jeden, král Arad jeden;'),
(1552336,54,6,12,15,'Král Lebna jeden, král Adulam jeden;'),
(1552337,54,6,12,16,'Král Maceda jeden, král Bethel jeden;'),
(1552338,54,6,12,17,'Král Tafua jeden, král Chefer jeden;'),
(1552339,54,6,12,18,'Král Afek jeden, král Sáron jeden;'),
(1552340,54,6,12,19,'Král Mádon jeden, král Azor jeden;'),
(1552341,54,6,12,20,'Král Simron Meron jeden, král Achzaf jeden;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552342,54,6,12,21,'Král Tanach jeden, král Mageddo jeden;'),
(1552343,54,6,12,22,'Král Kedes jeden, král Jekonam z Karmelu jeden;'),
(1552344,54,6,12,23,'Král Dor z krajiny Dor jeden, král z Goim v Galgal jeden;'),
(1552345,54,6,12,24,'Král Tersa jeden. Všech králů třidceti a jeden.'),
(1552346,54,6,13,1,'Jozue pak již byl starý a sešlý věkem. I řekl jemu Hospodin: Tys se již sstaral, a jsi sešlého věku, země pak zůstává velmi mnoho k opanování.'),
(1552347,54,6,13,2,'Tato jest země, kteráž zůstává: Všecky končiny Filistinské a všecka Gessuri,'),
(1552348,54,6,13,3,'Od Níle, kterýž jest naproti Egyptu, až ku pomezí Akaron na půlnoci, kterážto krajina Kananejským se přičítá, v níž jest patero knížetství Filistinských: Gazejské, Azotské, Aškalonitské, Getejské a Akaronitské, a to bylo Hevejské;'),
(1552349,54,6,13,4,'Na poledne pak všecka země Kananejská a Mára, kteréž jest Sidonských až do Afeka, a až ku pomezí Amorejského;'),
(1552350,54,6,13,5,'Též země Giblická, a všecken Libán k východu slunce, od Balgad pod horou Hermon, až kde se vchází do Emat.'),
(1552351,54,6,13,6,'Všecky obyvatele té hory, od Libánu až k vodám Maserefot, všecky Sidonské já vyženu od tváři synů Izraelských; toliko ty rozděl ji losem lidu Izraelskému v dědictví, jakožť jsem přikázal.'),
(1552352,54,6,13,7,'Protož nyní rozděl zemi tu v dědictví devateru pokolení, a polovici pokolení Manassesova,'),
(1552353,54,6,13,8,'Poněvadž druhá polovice a pokolení Rubenovo a Gádovo vzali díl svůj, kterýž jim dal Mojžíš před Jordánem k východu, jakož dal jim Mojžíš služebník Hospodinův,'),
(1552354,54,6,13,9,'Od Aroer, kteréž jest při břehu potoka Arnon, i města u prostřed potoka, i všecky roviny Medaba až do Dibon,'),
(1552355,54,6,13,10,'I všecka města Seona, krále Amorejského, kterýž kraloval v Ezebon, až ku pomezí synů Ammon,'),
(1552356,54,6,13,11,'A Galád, i pomezí Gessuri a Machati, všecku horu Hermon, i všecken Bázan až do Sálecha,'),
(1552357,54,6,13,12,'Všecko království Oga v Bázan, kterýž kraloval v Astarot a v Edrei, kterýž byl pozůstal z ostatků Refaim, když je pobil Mojžíš, a zahladil je.'),
(1552358,54,6,13,13,'Nevyhnali pak synové Izraelští Gessuri a Machati, protož bydlil Gessura a Machata u prostřed Izraele až do dnešního dne.'),
(1552359,54,6,13,14,'Toliko pokolení Léví nedal dědictví; oběti ohnivé Hospodina Boha Izraelského jsou dědictví jeho, jakož mluvil jemu.'),
(1552360,54,6,13,15,'Dal pak Mojžíš pokolení synů Ruben po čeledech jejich dědictví.'),
(1552361,54,6,13,16,'A bylo jejich pomezí od Aroer, kteréž jest při břehu potoka Arnon, i město, kteréž jest u prostřed potoka, i všecky roviny, kteréž jsou při Medaba,'),
(1552362,54,6,13,17,'Ezebon i všecka města jeho, kteráž byla na rovinách, Dibon a Bamotbal a Betbalmeon,'),
(1552363,54,6,13,18,'Jasa a Kedemot a Mefat,'),
(1552364,54,6,13,19,'A Kariataim a Sabma, a Saratazar na hoře údolí,'),
(1552365,54,6,13,20,'A Betfegor i Assedot, Fazga a Betsimot.'),
(1552366,54,6,13,21,'Všecka také města v kraji, i všecko království Seona, krále Amorejského, kterýž kraloval v Ezebon, jehožto zabil Mojžíš i s knížaty Madianskými, Evi i Rekem, Sur, Hur a Rebe, vývodami Seonovými, obyvateli té země.'),
(1552367,54,6,13,22,'Ano i Baláma, syna Beorova, věšťce, zabili synové Izraelští mečem, s jinými, kteříž zbiti od nich.'),
(1552368,54,6,13,23,'I bylo pomezí synů Rubenových Jordán s mezemi svými. To jest dědictví synů Rubenových po čeledech jejich, města i vsi jejich.'),
(1552369,54,6,13,24,'Dal také Mojžíš pokolení Gád, synům Gádovým, po čeledech jejich dědictví.'),
(1552370,54,6,13,25,'A bylo jejich pomezí Jazer i všecka města Galád, a polovice země synů Ammon až do Aroer, kteréž jest naproti Rabba,'),
(1552371,54,6,13,26,'A od Ezebon až do Rámot, Masfe a Betonim, a od Mahanaim až ku pomezí Dabir;'),
(1552372,54,6,13,27,'V údolí také Betaram a Betnemra, a Sochot, a Sefon, ostatek království Seona, krále Ezebon, i Jordán s pomezím svým až k kraji moře Ceneret za Jordánem na východ.'),
(1552373,54,6,13,28,'To jest dědictví synů Gád po čeledech jejich, města i vsi jejich.'),
(1552374,54,6,13,29,'Dal také Mojžíš polovici pokolení Manassesova dědictví, i bylo polovice pokolení synů Manassesových, po čeledech jejich.'),
(1552375,54,6,13,30,'Pomezí jejich od Mahanaim, všecken Bázan, všecko království Oga, krále Bázan, i všecky vesnice Jair, kteréž jsou v Bázan, šedesáte měst,'),
(1552376,54,6,13,31,'A polovice Galád, a Astarot, a Edrei, města království Oga v Bázan. To dal synům Machirovým, syna Manassesova, polovici synů Machirových, po čeledech jejich.'),
(1552377,54,6,13,32,'Ta jsou dědictví, kteráž rozdělil Mojžíš na rovinách Moábských před Jordánem proti Jerichu k východu.'),
(1552378,54,6,13,33,'Pokolení pak Léví nedal Mojžíš dědictví; Hospodin Bůh Izraelský jest dědictví jejich, jakož mluvil jim.'),
(1552379,54,6,14,1,'Toto pak jest, což dědičně obdrželi synové Izraelští v zemi Kanán, což uvedli jim právem dědičným k vládařství Eleazar kněz, a Jozue, syn Nun, a přední z otců, v pokolení synů Izraelských,'),
(1552380,54,6,14,2,'Losem dělíce dědictví jejich, jakož přikázal Hospodin skrze Mojžíše, aby dal devateru pokolení a polovici pokolení.'),
(1552381,54,6,14,3,'Nebo byl dal Mojžíš dědictví půltřetímu pokolení před Jordánem, Levítům pak nedal dědictví u prostřed nich.'),
(1552382,54,6,14,4,'Nebo synů Jozefových bylo dvoje pokolení, Manassesovo a Efraimovo; a nedali dílu Levítům v zemi, kromě měst k bydlení, a podměstí jejich pro dobytek a stáda jejich.'),
(1552383,54,6,14,5,'Jakož přikázal Hospodin Mojžíšovi, tak učinili synové Izraelští, a rozdělili zemi.'),
(1552384,54,6,14,6,'Přistoupili pak synové Juda k Jozue v Galgala, i promluvil k němu Kálef, syn Jefonův, Cenezejský: Ty víš, co jest mluvil Hospodin k Mojžíšovi, muži Božímu, z příčiny mé a tvé v Kádesbarne.'),
(1552385,54,6,14,7,'Ve čtyřidceti letech byl jsem, když mne poslal Mojžíš, služebník Hospodinův, z Kádesbarne k spatření země, a oznámil jsem jemu tu věc, jakž bylo v srdci mém.'),
(1552386,54,6,14,8,'Ale bratří moji, kteříž šli se mnou, zkormoutili srdce lidu, já pak cele kráčel jsem za Hospodinem Bohem svým.'),
(1552387,54,6,14,9,'I přisáhl Mojžíš toho dne, řka: Jistě že země, po kteréž jsi chodil nohama svýma, bude v dědictví tobě i synům tvým až na věky, proto že jsi cele následoval Hospodina Boha mého.'),
(1552388,54,6,14,10,'A nyní, aj, propůjčil mi Hospodin života, jakož zaslíbil. Již čtyřidceti a pět let jest od toho času, jakž toto mluvil Hospodin k Mojžíšovi, a jakž chodil Izrael po poušti, a aj, již dnes jsem v osmdesáti pěti letech,'),
(1552389,54,6,14,11,'A ještě nyní jsem při síle jako tehdáž, když poslal mne Mojžíš. Jaká byla síla má tehdáž, taková i nyní síla má jest k boji, a k vycházení i k vcházení.'),
(1552390,54,6,14,12,'Protož nyní dej mi horu tuto, o níž mluvil Hospodin onoho dne, nebo ty slyšel jsi toho dne, že Enakim jsou tam, a města veliká a pevně hrazená. Bude-li Hospodin se mnou, vyhladím je, jakož mluvil Hospodin.'),
(1552391,54,6,14,13,'I požehnal mu Jozue, a dal Hebron Kálefovi, synu Jefone, v dědictví.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552392,54,6,14,14,'Protož dostal se Hebron Kálefovi, synu Jefona Cenezejského, v dědictví až do tohoto dne, proto že cele kráčel za Hospodinem Bohem Izraelským.'),
(1552393,54,6,14,15,'Sloulo pak Hebron prvé město Arbe, kterýžto Arbe byl člověk veliký mezi Enakim. I odpočinula země od bojů.'),
(1552394,54,6,15,1,'Tento pak byl los pokolení synů Juda po čeledech jejich, při pomezí Edomském a poušti Tsin ku poledni, k straně polední.'),
(1552395,54,6,15,2,'I byla jejich meze polední kraj moře slaného od zátoky, kteráž se chýlí ku poledni.'),
(1552396,54,6,15,3,'Odkudž jda na poledne k vrchu Akrabim, přechází Tsin, a táhne se od poledne k Kádesbarne, i přichází až do Ezron, a odtud točí se k Addar, a obchází Karkaha.'),
(1552397,54,6,15,4,'Odtud jde do Asmona, a vychází ku potoku Egyptskému, a přichází meze ta až k západu. To budete míti pomezí na poledne.'),
(1552398,54,6,15,5,'Meze pak na východ jest moře slané, až k kraji Jordánu, a meze strany půlnoční jest od zátoky moře a od kraje Jordánu.'),
(1552399,54,6,15,6,'Odkudž jde meze ta do Betogla, a táhne se od půlnoci do Betaraba; a odtud přichází k kameni Bohana syna Rubenova.'),
(1552400,54,6,15,7,'A vstupuje ta meze do Dabir od údolí Achor, a na půlnoci chýlí se k Galgala, kteréž jest naproti vcházení do Adomim, jenž jest údolí tomu ku poledni, a přechází k vodám Ensemes, a skonává se u studnice Rogel.'),
(1552401,54,6,15,8,'Odtud jde ta meze přes údolí synů Hinnom k straně Jebus od poledne, jenž jest Jeruzalém, odkudž vstupuje táž meze k vrchu hory, kteráž jest naproti údolí Hinnom na západ, a kteráž jest na konci údolí Refaim na půlnoci.'),
(1552402,54,6,15,9,'Obchází pak ta meze od vrchu té hory k studnici vody Neftoa, a vychází k městům hory Efron; a odtud jde ta meze do Bála, jenž jest Kariatjeharim.'),
(1552403,54,6,15,10,'Potom točí se ta meze od Bála na západ k hoře Seir, a odtud jde k straně hory Jeharimských od půlnoci, jenž jest Cheslon, a sstupuje do Betsemes, a přichází do Tamna.'),
(1552404,54,6,15,11,'A vychází ta meze v stranu Akaron na půlnoci, a točí se vůkol k Sechronu, a přechází až k hoře Bála, a odtud táhne se do Jebnael, i dochází ta meze k moři.'),
(1552405,54,6,15,12,'Potom západní pomezí jest při moři velikém a mezech jeho. To jest pomezí synů Juda vůkol, po čeledech jejich.'),
(1552406,54,6,15,13,'Kálefovi pak, synu Jefone, dal díl u prostřed synů Juda, podlé řeči Hospodinovy k Jozue, město Arbe, otce Enakova, jenž jest Hebron.'),
(1552407,54,6,15,14,'I vyhnal odtud Kálef tři syny Enakovy: Sesai a Achimana a Tolmai, rodinu Enakovu.'),
(1552408,54,6,15,15,'A odtud vstoupil k obyvatelům Dabir, kteréž prvé sloulo Kariatsefer.'),
(1552409,54,6,15,16,'I řekl Kálef: Kdo by dobyl Kariatsefer a vzal je, dám jemu Axu dceru svou za manželku.'),
(1552410,54,6,15,17,'Dobyl ho pak Otoniel syn Cenezův, příbuzný Kálefův, i dal jemu Axu dceru svou za manželku.'),
(1552411,54,6,15,18,'I stalo se, že když přišla k němu, ponukla ho, aby prosil otce jejího za pole; protož ssedla s osla. I řekl jí Kálef: Což tě?'),
(1552412,54,6,15,19,'A ona odpověděla: Dej mi dar, poněvadž jsi mi dal zemi suchou, dejž mi také studnice vod. I dal jí studnice horní a studnice dolní.'),
(1552413,54,6,15,20,'To jest dědictví pokolení synů Juda po čeledech jejich.'),
(1552414,54,6,15,21,'Tato pak jsou města v končinách pokolení synů Juda, podlé pomezí Edom na poledne: Kabsael, Eder a Jagur;'),
(1552415,54,6,15,22,'A Cina, a Dimona, a Adada;'),
(1552416,54,6,15,23,'A Kedes, a Azor, a Jetnan;'),
(1552417,54,6,15,24,'Zif a Telem, a Balot;'),
(1552418,54,6,15,25,'Též Azor, Chadat a Kariot, Ezron, jenž jest Azor;'),
(1552419,54,6,15,26,'Amam a Sama, a Molada;'),
(1552420,54,6,15,27,'A Azar Gadda, a Esmon, a Betfelet;'),
(1552421,54,6,15,28,'Též Azarsual, a Bersabé, a Baziothia;'),
(1552422,54,6,15,29,'Bála a Im, a Esem;'),
(1552423,54,6,15,30,'A Eltolad, a Chesil, a Horma;'),
(1552424,54,6,15,31,'A Sicelech, a Medemena, a Sensenna;'),
(1552425,54,6,15,32,'A Lebaot, a Selim, též Ain a Remmon; všech měst dvadceti a devět i vsi jejich.'),
(1552426,54,6,15,33,'Na rovinách pak: Estaol a Zaraha, a Asna;'),
(1552427,54,6,15,34,'A Zanoe, a Engannim, Tafua a Enaim;'),
(1552428,54,6,15,35,'Jarmut, Adulam, Socho a Azeka;'),
(1552429,54,6,15,36,'A Saraim, Aditaim, a Gedera, a Gederotaim, měst čtrnácte i vsi jejich;'),
(1552430,54,6,15,37,'Senan a Adassa, a Magdalgad;'),
(1552431,54,6,15,38,'Delean a Masfa, a Jektehel;'),
(1552432,54,6,15,39,'Lachis, Baskat a Eglon;'),
(1552433,54,6,15,40,'Chebon, Lemam a Cetlis;'),
(1552434,54,6,15,41,'Gederot, Betdagon, a Naama, i Maceda, měst šestnáct a vsi jejich;'),
(1552435,54,6,15,42,'Lebna, Eter a Asan;'),
(1552436,54,6,15,43,'Jefta, Asna a Nesib;'),
(1552437,54,6,15,44,'Ceila, Achzib a Maresa, měst devět i vsi jejich;'),
(1552438,54,6,15,45,'Akaron a městečka, i vsi jeho;'),
(1552439,54,6,15,46,'Od Akaron až k moři všecka města, kteráž se chýlí k Azotu, i vsi jejich;'),
(1552440,54,6,15,47,'Azot, městečka jeho i vsi jeho; Gáza, městečka jeho i vsi jeho až ku potoku Egyptskému, i moře veliké s pomezím svým.'),
(1552441,54,6,15,48,'A na horách: Samir, Jeter a Socho;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552442,54,6,15,49,'Danna a město Sanna, jenž jest Dabir;'),
(1552443,54,6,15,50,'Anab, Estemo a Anim;'),
(1552444,54,6,15,51,'Gosen, Holon a Gilo, měst jedenácte i vsi jejich;'),
(1552445,54,6,15,52,'Arab, Duma a Esan;'),
(1552446,54,6,15,53,'Janum, Bettafua a Afeka;'),
(1552447,54,6,15,54,'Též Atmata a Kariatarbe, jenž jest Hebron, a Sior, měst devět a vsi jejich.'),
(1552448,54,6,15,55,'Maon, Karmel a Zif, a Juta;'),
(1552449,54,6,15,56,'Jezreel a Jukadam, a Zanoe;'),
(1552450,54,6,15,57,'Kain, Gabaa a Tamna, měst deset i vsi jejich;'),
(1552451,54,6,15,58,'Alul, Betsur a Gedor;'),
(1552452,54,6,15,59,'Maret, Betanot a Eltekon, měst šest i vsi jejich;'),
(1552453,54,6,15,60,'Kariatbaal, kteréž jest Kariatjeharim, a Rebba, města dvě i vsi jejich;'),
(1552454,54,6,15,61,'Na poušti: Betaraba, Middin a Sechacha;'),
(1552455,54,6,15,62,'A Nibsam, a město solné, a Engadi, měst šest i vsi jejich.'),
(1552456,54,6,15,63,'Jebuzejských pak obyvatelů Jeruzaléma nemohli synové Juda vypléniti, protož bydlil Jebuzejský s syny Judskými v Jeruzalémě až do tohoto dne.'),
(1552457,54,6,16,1,'Potom padl los synům Jozefovým, od Jordánu proti Jerichu při vodách Jerišských k východu, poušť, kteráž se začíná od Jericha přes hory Bethel.'),
(1552458,54,6,16,2,'A od Bethel vychází do Lůza, a přichází ku pomezí Archi do Atarot.'),
(1552459,54,6,16,3,'Potom jde k moři ku pomezí Jefleti, až ku pomezí Betoron dolního, a až k Gázer, a skonává se při moři.'),
(1552460,54,6,16,4,'I vzali dědictví své synové Jozefovi, Manasses a Efraim.'),
(1552461,54,6,16,5,'Byla pak meze synů Efraimových po čeledech jejich, ta byla meze dědictví jejich na východ, od Atarot Addar až do Betoron vrchního.'),
(1552462,54,6,16,6,'A vychází meze ta k moři při Michmetat od půlnoční strany, a obchází meze k východu Tanatsilo, a přechází ji od východu k Janoe.'),
(1552463,54,6,16,7,'A sstupuje z Janoe do Atarot a Nárat, a přichází do Jericha, a vychází k Jordánu.'),
(1552464,54,6,16,8,'Od Tafue meze jde k moři ku potoku Kána, a skonává se při moři. To jest dědictví pokolení synů Efraim po čeledech jejich.'),
(1552465,54,6,16,9,'Města pak oddělená synům Efraimovým byla u prostřed dědictví synů Manassesových, všecka města s vesnicemi svými.'),
(1552466,54,6,16,10,'A nevyplénili Kananea bydlícího v Gázer. I bydlil Kananejský u prostřed Efraima až do dnes, dávaje plat.'),
(1552467,54,6,17,1,'A tento byl los Manassesův (nebo on jest prvorozený Jozefův): Machirovi prvorozenému Manassesovu, otci Gálad, proto že byl muž bojovný, dostal se Galád a Bázan.'),
(1552468,54,6,17,2,'Dostalo se také jiným synům Manassesovým po čeledech jejich, synům Abiezer, a synům Helek, a synům Asriel, i synům Sechem, a synům Hefer, a synům Semida. (Nebo ti jsou synové Manassesovi, syna Jozefova, muži po rodech svých.'),
(1552469,54,6,17,3,'Ale Salfad, syn Hefer, syna Galád, syna Machir, syna Manasse, neměl synů, než dcery toliko, jejichž jsou tato jména: Mahla a Noa, Hegla, Melcha a Tersa.'),
(1552470,54,6,17,4,'Kteréžto přistoupivše před Eleazara kněze, a před Jozue, syna Nun, i před knížata, řekly: Hospodin přikázal Mojžíšovi, aby nám dal dědictví u prostřed bratří našich. I dal jim Jozue podlé rozkázaní Hospodinova dědictví u prostřed bratří otce jejich.)'),
(1552471,54,6,17,5,'Dostalo se provazců Manassesovi deset, krom země Galád a Bázan, kteráž byla před Jordánem.'),
(1552472,54,6,17,6,'Nebo dcery Manassesovy obdržely dědictví mezi syny jeho, země pak Galád přišla jiným synům Manassesovým.'),
(1552473,54,6,17,7,'A byla meze Manassesova od Asser, Michmetat, jenž jest před Sichem, a táhne se na pravou stranu k obyvatelům Entafue.'),
(1552474,54,6,17,8,'(Manassesova zajisté byla země Tafue, ale Tafue podlé pomezí Manassesova jest synů Efraimových.)'),
(1552475,54,6,17,9,'Odkudž sstupuje pomezí ku potoku Kána, na poledne tomu potoku, a tu jsou města Efraimova u prostřed měst Manassesových; pomezí pak Manassesovo jest na půlnoci toho potoka, a skonává se při moři.'),
(1552476,54,6,17,10,'Na poledne jest díl Efraimův, a na půlnoci Manassesův, moře pak jest pomezí jejich; a v pokolení Asser sbíhají se na půlnoci, v pokolení pak Izachar na východ.'),
(1552477,54,6,17,11,'Nebo dědictví Manassesovo jest mezi Izacharovým a Asserovým, Betsan i městečka jeho, a Jibleam a městečka jeho; též obyvatelé Dor a městečka jeho, a obyvatelé Endor a městečka jeho; také obyvatelé Tanach a městečka jeho, i obyvatelé Mageddo a městečka jeho; tři ty krajiny.'),
(1552478,54,6,17,12,'Ale synové Manassesovi nemohli vypléniti obyvatelů těch měst; protož směleji počal Kananejský bydliti v zemi té.'),
(1552479,54,6,17,13,'Když se pak zsilili synové Izraelští, uvedli sobě Kananejské pod plat, a nevyhladili jich do konce.'),
(1552480,54,6,17,14,'Tedy mluvili synové Jozefovi k Jozue, řkouce: Proč jsi nám dal dědictví toliko los jeden a provazec jeden, poněvadž jsme lid mnohý; nebo až dosavad žehnal nám Hospodin.'),
(1552481,54,6,17,15,'I řekl jim Jozue: Poněvadž jsi lid tak mnohý, vejdi do lesa, a vyplaň sobě tam v zemi Ferezejské a Refaimské, jestližeť jest malá hora Efraim.'),
(1552482,54,6,17,16,'Jemuž odpověděli synové Jozefovi: I tak nám nepostačí ta hora; přes to vozy železné mají všickni Kananejští, kteříž bydlejí v luzích těch, i ti, kteříž jsou v Betsan a v městečkách jeho, i ti, kteříž jsou v údolí Jezreel.'),
(1552483,54,6,17,17,'I řekl Jozue domu Jozefovu, Efraimovu a Manassesovu, řka: Lid mnohý a silný jsi, nebudeš míti toliko dílu jednoho,'),
(1552484,54,6,17,18,'Ale horu budeš míti. Jestližeť překáží les, tedy vysekáš jej, a obdržíš končiny její; nebo vyhladíš Kananejského, ačkoli má vozy železné a jest silný.'),
(1552485,54,6,18,1,'Shromáždilo se pak všecko množství synů Izraelských do Sílo, a tu postavili stánek úmluvy, když již země od nich podmaněna byla.'),
(1552486,54,6,18,2,'Pozůstalo pak z synů Izraelských, jimž ještě nebylo rozděleno dědictví jejich, sedmero pokolení.'),
(1552487,54,6,18,3,'I řekl Jozue synům Izraelským: I dokudž zanedbáváte vjíti, abyste se uvázali v zemi, kterouž vám dal Hospodin Bůh otců vašich?'),
(1552488,54,6,18,4,'Vydejte z sebe z každého pokolení tři muže, ať je pošli, aby vstanouce, zchodili zemi, a popsali ji vedlé dědictví svých; potom navrátí se ke mně.'),
(1552489,54,6,18,5,'I rozdělí ji na sedm dílů. Juda zůstane v končinách svých od poledne, a čeledi Jozefovy zůstanou v končinách svých od půlnoci.'),
(1552490,54,6,18,6,'Vy pak, když popíšete zemi na sedm dílů, přinesete sem ke mně; tedy uvrhu vám losy zde před Hospodinem Bohem naším.'),
(1552491,54,6,18,7,'Nebo nemají dílu Levítové u prostřed vás, proto že kněžství Hospodinovo jest dědictví jejich; Gád pak a Ruben, a polovice pokolení Manassesova, vzali dědictví své před Jordánem na východ, kteréž dal jim Mojžíš, služebník Hospodinův.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552492,54,6,18,8,'Protož vstavše muži ti, odešli. A přikázal Jozue těm, kteříž šli, aby popsali zemi, řka: Jděte a projděte zemi, a popište ji; potom navraťte se ke mně, a uvrhu zde losy před Hospodinem v Sílo.'),
(1552493,54,6,18,9,'Tedy odešli muži, a prošedše zemi, popsali ji po městech na sedm dílů na knize, a navrátili se k Jozue do stanů v Sílo.'),
(1552494,54,6,18,10,'I uvrhl jim losy Jozue v Sílo před Hospodinem, a rozdělil tu Jozue zemi synům Izraelským vedlé dílů jejich.'),
(1552495,54,6,18,11,'Padl pak los pokolení synů Beniaminových po čeledech jejich, a přišla meze dílu jejich mezi syny Juda a syny Jozefovy.'),
(1552496,54,6,18,12,'A byla meze jejich k straně půlnoční od Jordánu, a šla při straně půlnoční Jericha, a táhla se na hory k moři, a skonávala se při poušti Betaven.'),
(1552497,54,6,18,13,'A odtud přechází ta meze do Lůz, při straně Lůz polední, (jenž jest Bethel,) a chýlí se ta meze do Atarot Addar vedlé hory, kteráž jest od poledne Betoron dolního.'),
(1552498,54,6,18,14,'Odkudž obchází vůkol k straně moře na poledne od hory, kteráž jest proti Betoron ku polední, a konec její jest Kariatbaal, (jenž jest Kariatjeharim), město synů Juda. Ta jest strana západní.'),
(1552499,54,6,18,15,'Strana pak ku poledni od konce Kariatjeharim, a vychází ta meze k moři, a přichází až k studnici vod Neftoa.'),
(1552500,54,6,18,16,'A táhne se táž meze k konci hory, kteráž jest naproti údolí synů Hinnom, a jest v údolí Refaim na půlnoci, a běží skrze údolí Hinnom po straně Jebuzea na poledne, a přichází k studnici Rogel.'),
(1552501,54,6,18,17,'Potom točí se od půlnoci, a dochází k Ensemes, a vychází do Gelilot, kteréž jest naproti místu, kudy se jde do Adomim, a sstupuje k kameni Bohana, syna Rubenova.'),
(1552502,54,6,18,18,'Odtud přechází k straně, kteráž jest naproti rovinám strany půlnoční, a táhne se do Araba.'),
(1552503,54,6,18,19,'Odtud jde k straně Betogla na půlnoci, a skonává se meze ta při zátoce moře slaného od půlnoční strany, tu kdež vpadá Jordán do moře na polední straně. To jest pomezí ku poledni.'),
(1552504,54,6,18,20,'Jordán také je odděluje k straně východní. To jest dědictví synů Beniaminových s mezemi svými vůkol a vůkol po čeledech jejich.'),
(1552505,54,6,18,21,'A byla města tato pokolení synů Beniaminových po čeledech jejich: Jericho, Betogla a údolí Kasis;'),
(1552506,54,6,18,22,'A Betaraba, Semaraim a Bethel;'),
(1552507,54,6,18,23,'A Avim, též Afara a Ofra;'),
(1552508,54,6,18,24,'A Cefer, Hamona, Ofni a Gaba, měst dvanácta vsi jejich;'),
(1552509,54,6,18,25,'Gabaon, Ráma a Berot;'),
(1552510,54,6,18,26,'Masfa, Kafira a Mosa;'),
(1552511,54,6,18,27,'Rekem, Jarefel a Tarela;'),
(1552512,54,6,18,28,'A Sela, Elef a Jebus, (jenž jest Jeruzalém,) Gibat, Kariat, měst čtrnácte i vsi jejich. To jest dědictví synů Beniaminových po čeledech jejich.'),
(1552513,54,6,19,1,'Potom padl los druhý Simeonovi, pokolení synů Simeonových, po čeledech jejich, a bylo dědictví jejich u prostřed dědictví synů Juda.'),
(1552514,54,6,19,2,'A přišlo jim v dědictví jejich Bersabé, Seba a Molada;'),
(1552515,54,6,19,3,'Azarsual a Bala, též Esem;'),
(1552516,54,6,19,4,'Eltolad a Betul, a Horma;'),
(1552517,54,6,19,5,'Sicelech a Betmarchabot, a Azarsusa;'),
(1552518,54,6,19,6,'Betlebaot a Sarohem, měst třinácte i vsi jejich;'),
(1552519,54,6,19,7,'Ain, Remmon, též Eter a Asan, města čtyři i vsi jejich;'),
(1552520,54,6,19,8,'I všecky vsi, kteréž byly vůkolí měst těch, až do Balatber a Rámat poledního. To jest dědictví pokolení synů Simeonových po čeledech jejich.'),
(1552521,54,6,19,9,'Z podílu synů Judových bylo dědictví synů Simeonových; nebo díl synů Judových byl jim příliš veliký, protož u prostřed dědictví jejich vzali dědictví synové Simeonovi.'),
(1552522,54,6,19,10,'Potom přišel třetí los synům Zabulon po čeledech jejich, a jest meze dědictví jejich až do Sarid.'),
(1552523,54,6,19,11,'Odkudž vstupuje meze jejich podlé moře k Merala, a přichází až do Debaset, a běží až ku potoku, kterýž jest proti Jekonam.'),
(1552524,54,6,19,12,'Obrací se pak od Sarid nazpátek k východu slunce, ku pomezí Chazelet Tábor, a odtud táhne se k Daberet, a vstupuje do Jafie.'),
(1552525,54,6,19,13,'Odtud přechází zase k východu, do Gethefer a do Itakasin, odkudž vychází do Remmon, a točí se k Nea.'),
(1552526,54,6,19,14,'Točí se také táž meze od půlnoci do Anaton, a dochází až k údolí Jeftael;'),
(1552527,54,6,19,15,'A Katet, Naalol, Simron, Idala a Betlém, měst dvanácte i vsi jejich.'),
(1552528,54,6,19,16,'To jest dědictví synů Zabulonových po čeledech jejich, ta města i vsi jejich.'),
(1552529,54,6,19,17,'Izacharovi také padl los čtvrtý, totiž synům Izacharovým po čeledech jejich.'),
(1552530,54,6,19,18,'A meze jejich: Jezreel, Kasalat a Sunem;'),
(1552531,54,6,19,19,'Hafaraim, Sion, též Anaharat;'),
(1552532,54,6,19,20,'Rabbot, Kesion a Abez,'),
(1552533,54,6,19,21,'Ramet, Engannim a Enhada, i Betfeses.'),
(1552534,54,6,19,22,'Odkudž přibíhá meze k Táboru a k Sehesima a k Betsemes, a dochází až k Jordánu, měst šestnácte i vsi jejich.'),
(1552535,54,6,19,23,'To jest dědictví pokolení synů Izacharových po čeledech jejich, ta města i vsi jejich.'),
(1552536,54,6,19,24,'Padl také los pátý pokolení synů Asser po čeledech jejich.'),
(1552537,54,6,19,25,'A byla meze jejich: Helkat a Chali, a Beten, a Achzaf;'),
(1552538,54,6,19,26,'Elmelech, též Amaad a Mesal, a přibíhá až na Karmel k moři, a do Sichor Libnat;'),
(1552539,54,6,19,27,'A obrací se k východu slunce do Betdagon, a dosahá k losu Zabulonovu, a do údolí Jeftael k půlnoci, a do Betemek a Nehiel, a táhne se do Kábul na levou stranu,'),
(1552540,54,6,19,28,'A do Ebron a Rohob, a Hamon a Kána až do Sidonu velikého.'),
(1552541,54,6,19,29,'Odtud se navrací ta meze do Ráma až k městu hrazenému Zor; tu se obrací do Chosa, a skonává se při moři podlé vyměření v Achziba.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552542,54,6,19,30,'K tomu přísluší Afek a Rohob, měst dvamecítma i vsi jejich.'),
(1552543,54,6,19,31,'To jest dědictví pokolení synů Asser po čeledech jejich, ta města i vsi jejich.'),
(1552544,54,6,19,32,'Synům Neftalímovým padl los šestý, po čeledech jejich.'),
(1552545,54,6,19,33,'A byla meze jejich od Helef a od Elon do Sananim, a Adami, Nekeb a Jebnael, až do Lekum, a skonává se u Jordánu.'),
(1552546,54,6,19,34,'Potom navracuje se meze na západ k Azanot Tábor, a odtud jde do Hukuka, a vpadá k Zabulonovu od poledne, a k Asserovu přibíhá od západu, a k Judovu při Jordánu na východ slunce.'),
(1552547,54,6,19,35,'Města pak hrazená jsou: Assedim, Ser a Emat, Rechat a Ceneret;'),
(1552548,54,6,19,36,'Adama, Ráma a Azor;'),
(1552549,54,6,19,37,'Kedes, Edrei a Enazor;'),
(1552550,54,6,19,38,'Jeron, Magdalel, Horem, Betanat a Betsemes, měst devatenácte i vsi jejich.'),
(1552551,54,6,19,39,'To jest dědictví pokolení synů Neftalím po čeledech jejich, ta města s vesnicemi svými.'),
(1552552,54,6,19,40,'Na pokolení synů Dan po čeledech jejich padl los sedmý.'),
(1552553,54,6,19,41,'A byla meze dědictví jejich: Zaraha a Estaol, a Hirsemes;'),
(1552554,54,6,19,42,'Salbin, Aialon a Jetela;'),
(1552555,54,6,19,43,'Elon, Tamna a Ekron;'),
(1552556,54,6,19,44,'Elteke, Gebbeton a Baalat;'),
(1552557,54,6,19,45,'Jehud, Beneberak a Getremmon;'),
(1552558,54,6,19,46,'Mehaiarkon a Rakon s pomezím, kteréž jest naproti Joppe.'),
(1552559,54,6,19,47,'Přišlo pak pomezí synům Dan příliš malé. Protož vstoupili synové Dan, a bojovali proti Lesen, a dobyvše ho, pobili obyvatele ostrostí meče, a vzavše je v dědictví, bydlili tam, a přezděli Lesenu Dan, vedlé jména Dan otce svého.'),
(1552560,54,6,19,48,'To jest dědictví pokolení synů Dan po čeledech jejich, ta města i vsi jejich.'),
(1552561,54,6,19,49,'Když pak přestali děliti se zemí po mezech jejích, dali synové Izraelští dědictví Jozue, synu Nun, mezi sebou.'),
(1552562,54,6,19,50,'Podlé rozkázaní Hospodinova dali jemu město, kteréhož žádal, Tamnatsára, na hoře Efraim. I vystavěl město, a přebýval v něm.'),
(1552563,54,6,19,51,'Ta jsou dědictví, kteráž dali k vládařství Eleazar kněz a Jozue syn Nun, i přední z otců pokolení synů Izraelských, losem v Sílo před Hospodinem, u dveří stánku úmluvy, a tak dokonali rozdělování země.'),
(1552564,54,6,20,1,'I mluvil Hospodin k Jozue, řka:'),
(1552565,54,6,20,2,'Mluv k synům Izraelským, a rci jim:Oddejte z těch měst vašich města útočišťná, o nichž jsem mluvil vám skrze Mojžíše,'),
(1552566,54,6,20,3,'Aby tam utekl vražedlník, kterýž by zabil člověka nechtě a z nevědomí. I budou vám útočiště před přítelem zabitého.'),
(1552567,54,6,20,4,'A když by utekl do jednoho z těch měst, stane u vrat v bráně města, a oznámí starším města toho při svou; i přijmou ho do města k sobě, a dají mu místo, i bydliti bude u nich.'),
(1552568,54,6,20,5,'Když by jej pak honil přítel toho zabitého, nevydají vražedlníka v ruce jeho; nebo nechtě udeřil bližního svého, neměv ho prvé v nenávisti.'),
(1552569,54,6,20,6,'A bydliti bude v městě tom, dokudž nestane před shromážděním k soudu, až do smrti kněze velikého, kterýž by byl toho času; nebo tehdáž navrátí se vražedlník, a přijde do města svého a do domu svého, do města, odkudž utekl.'),
(1552570,54,6,20,7,'I oddělili Kádes v Galilei na hoře Neftalím, a Sichem na hoře Efraim, a město Arbe, (jenž jest Hebron,) na hoře Juda.'),
(1552571,54,6,20,8,'Před Jordánem pak proti Jerichu k východu oddělili Bozor, kteréž leží na poušti v rovině pokolení Rubenova, a Rámot v Galád z pokolení Gádova, a Golan v Bázan z pokolení Manassesova.'),
(1552572,54,6,20,9,'Ta města byla útočišťná všechněm synům Izraelským, i příchozímu, kterýž pohostinu jest mezi nimi, aby utekl tam, kdo by koli zabil někoho nechtě, a nesešel od ruky přítele toho zabitého prvé, než by stál před shromážděním.'),
(1552573,54,6,21,1,'Přistoupili pak přední z otců Levítského pokolení k Eleazarovi knězi, a k Jozue, synu Nun, a k předním z otců pokolení synů Izraelských,'),
(1552574,54,6,21,2,'A mluvili k nim v Sílo, v zemi Kananejské, řkouce: Hospodin přikázal skrze Mojžíše, abyste nám dali města k přebývání, i podměstí jejich pro dobytky naše.'),
(1552575,54,6,21,3,'Dali tedy synové Izraelští Levítům z dědictví svého, vedlé rozkázaní Hospodinova, města tato i podměstí jejich.'),
(1552576,54,6,21,4,'Padl pak los čeledem Kahat, i dáno losem synům Arona kněze, Levítům, z pokolení Juda, a z pokolení Simeon, i z pokolení Beniaminova měst třinácte.'),
(1552577,54,6,21,5,'A jiným synům Kahat, z čeledí pokolení Efraimova, a z pokolení Danova, a z polovice pokolení Manassesova losem dáno měst deset.'),
(1552578,54,6,21,6,'Synům pak Gerson, z čeledí pokolení Izacharova, a z pokolení Asserova, též z pokolení Neftalímova, a z polovice pokolení Manassesova v Bázan losem dáno měst třinácte.'),
(1552579,54,6,21,7,'Synům Merari po čeledech jejich, z pokolení Rubenova a z pokolení Gádova, též z pokolení Zabulonova měst dvanácte.'),
(1552580,54,6,21,8,'Dali tedy synové Izraelští Levítům ta města i předměstí jejich, (jakož přikázal Hospodin skrze Mojžíše,) losem.'),
(1552581,54,6,21,9,'A tak z pokolení synů Judových, a z pokolení synů Simeonových dána jsou města, kterýchž tuto jména jsou položena.'),
(1552582,54,6,21,10,'A dostal se první díl synům Aronovým, z čeledí Kahat, z synů Léví; nebo jim padl los první.'),
(1552583,54,6,21,11,'Dáno jest tedy jim město Arbe, otce Enakova, (jenž jest Hebron,) na hoře Juda, a předměstí jeho vůkol něho.'),
(1552584,54,6,21,12,'Ale pole města toho i vsi jeho dali Kálefovi synu Jefone k vládařství jeho.'),
(1552585,54,6,21,13,'Synům tedy Arona kněze dali město útočišťné vražedlníku, Hebron i předměstí jeho, a Lebno i předměstí jeho;'),
(1552586,54,6,21,14,'A Jeter s předměstím jeho, též Estemo a předměstí jeho;'),
(1552587,54,6,21,15,'Holon i předměstí jeho, a Dabir s podměstím jeho;'),
(1552588,54,6,21,16,'Také Ain s předměstím jeho, a Juta s podměstím jeho, i Betsemes a předměstí jeho, měst devět z toho dvojího pokolení.'),
(1552589,54,6,21,17,'Z pokolení pak Beniaminova dali Gabaon a předměstí jeho, a Gaba s předměstím jeho;'),
(1552590,54,6,21,18,'Též Anatot a podměstí jeho, i Almon s předměstím jeho, města čtyři.'),
(1552591,54,6,21,19,'Všech měst synů Aronových kněží třinácte měst s předměstími jejich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552592,54,6,21,20,'Čeledem pak synů Kahat, Levítům, kteříž pozůstali z synů Kahat, (byla pak města losu jejich z pokolení Efraim,)'),
(1552593,54,6,21,21,'Dali jim město útočišťné vražedlníku, Sichem i předměstí jeho, na hoře Efraim, a Gázer s předměstím jeho.'),
(1552594,54,6,21,22,'Též Kibsaim a předměstí jeho, a Betoron s předměstím jeho, města čtyři.'),
(1552595,54,6,21,23,'Z pokolení pak Dan: Elteke a předměstí jeho, a Gebbeton s předměstím jeho;'),
(1552596,54,6,21,24,'Též Aialon a předměstí jeho, a Getremmon s podměstím jeho, města čtyři.'),
(1552597,54,6,21,25,'Z polovice pak pokolení Manassesova: Tanach a podměstí jeho, a Getremmon s předměstím jeho, města dvě.'),
(1552598,54,6,21,26,'Všech měst deset s předměstími jejich čeledem synům Kahat ostatním.'),
(1552599,54,6,21,27,'Synům také Gersonovým, z čeledí Levítských, z polovice pokolení Manassesova dali město útočišťné vražedlníku, Golan v Bázan a předměstí jeho, a Bozran s předměstím jeho, města dvě.'),
(1552600,54,6,21,28,'Z pokolení Izacharova: Kesion a podměstí jeho, a Daberet s předměstím jeho;'),
(1552601,54,6,21,29,'Jarmut a předměstí jeho, a Engannim s předměstím jeho, města čtyři.'),
(1552602,54,6,21,30,'Z pokolení pak Asserova: Mesal a předměstí jeho, též Abdon a podměstí jeho;'),
(1552603,54,6,21,31,'Helkat s předměstím jeho, a Rohob s podměstím jeho, města čtyři.'),
(1552604,54,6,21,32,'Z pokolení také Neftalímova: Město útočišťné vražedlníku, Kedes v Galilei a předměstí jeho, a Hamotdor s předměstím jeho, a Kartam s předměstím jeho, města tři.'),
(1552605,54,6,21,33,'Všech měst Gersonitských po čeledech jejich, třinácte měst s předměstími jejich.'),
(1552606,54,6,21,34,'Čeledem pak synů Merari, Levítům ostatním, dali z pokolení Zabulonova Jekonam a předměstí jeho, Karta a předměstí jeho;'),
(1552607,54,6,21,35,'Damna a předměstí jeho, Naalol a předměstí jeho, města čtyři.'),
(1552608,54,6,21,36,'Z pokolení pak Rubenova: Bozor a předměstí jeho, a Jasa a předměstí jeho;'),
(1552609,54,6,21,37,'Kedemot a předměstí jeho, a Mefat s podměstím jeho, města čtyři.'),
(1552610,54,6,21,38,'A z pokolení Gádova: Město útočišťné vražedlníku, Rámot v Galád a předměstí jeho, a Mahanaim s předměstím jeho;'),
(1552611,54,6,21,39,'Ezebon a podměstí jeho, Jazer s podměstím jeho, města čtyři.'),
(1552612,54,6,21,40,'Všech měst synů Merari po čeledech jejich, kteříž ostatní byli z čeledí Levítských, bylo podlé losu jejich měst dvanácte.'),
(1552613,54,6,21,41,'A tak všech měst Levítských u prostřed vládařství synů Izraelských měst čtyřidceti osm s předměstími svými.'),
(1552614,54,6,21,42,'Mělo pak to město jedno každé obzvláštně svá předměstí vůkol sebe, a taková byla všecka ta města.'),
(1552615,54,6,21,43,'Dal tedy Hospodin Izraelovi všecku tu zemi, kterouž s přísahou zaslíbil dáti otcům jejich; i opanovali ji dědičně, a bydlili v ní.'),
(1552616,54,6,21,44,'Dal také Hospodin jim odpočinutí se všech stran podlé všeho, jakž byl s přísahou zaslíbil otcům jejich, aniž kdo byl, ješto by ostál proti nim ze všech nepřátel jejich; všecky nepřátely jejich dal Hospodin v ruku jejich.'),
(1552617,54,6,21,45,'Nepominulo ani jedno slovo ze všelikého slova dobrého, kteréž mluvil Hospodin k domu Izraelskému, ale všecko se tak stalo.'),
(1552618,54,6,22,1,'Toho času povolav Jozue Rubenitských, Gáditských a polovice pokolení Manassesova,'),
(1552619,54,6,22,2,'Řekl jim: Vy jste ostříhali všeho, což přikázal vám Mojžíš, služebník Hospodinův, a poslouchali jste hlasu mého ve všem, což jsem přikázal vám.'),
(1552620,54,6,22,3,'Neopustili jste bratří svých již za dlouhý čas až do dne tohoto, ale bedlivě jste ostříhali přikázaní Hospodina Boha vašeho.'),
(1552621,54,6,22,4,'Nyní pak již odpočinutí dal Hospodin Bůh váš bratřím vašim, jakož mluvil jim; již tedy navraťte se a beřte se do stanů svých, do země vládařství svého, kteréž vám dal Mojžíš, služebník Hospodinův, před Jordánem.'),
(1552622,54,6,22,5,'Toliko hleďte pilně zachovávati a plniti přikázaní a zákon, kterýž přikázal vám Mojžíš, služebník Hospodinův, a milovati Hospodina Boha svého a choditi po všech cestách jeho, a zachovávajíce přikázaní jeho, přídržeti se ho, a sloužiti jemu celým srdcem svým a celou duší svou.'),
(1552623,54,6,22,6,'A požehnav jim Jozue, propustil je; i odešli do stanů svých.'),
(1552624,54,6,22,7,'(Polovici pak pokolení Manassesova dal byl Mojžíš dědictví v Bázan, a druhé polovici jeho dal Jozue s bratřími jejich za Jordánem k západu.) A když je propouštěl Jozue do stanů jejich, požehnal jim,'),
(1552625,54,6,22,8,'A mluvil k nim, řka: S bohatstvím velikým navracujete se do stanů svých a s dobytky velmi mnohými, s stříbrem a zlatem, s mědí a železem a rouchem velmi mnohým; rozděltež se loupeží nepřátel svých s bratřími svými.'),
(1552626,54,6,22,9,'Tedy navracujíce se, odešli synové Rubenovi a synové Gádovi a polovice pokolení Manassesova od synů Izraelských z Sílo, jenž jest v zemi Kananejské, aby šli do země Galád, do země vládařství svého, v kteréž dědictví obdrželi, vedlé řeči Hospodinovy skrze Mojžíše.'),
(1552627,54,6,22,10,'A přišedše ku pomezí při Jordánu, kteréž jest v zemi Kananejské, i vzdělali tu synové Rubenovi, a synové Gádovi, a polovice pokolení Manassesova oltář nad Jordánem, oltář veliký ku podivení.'),
(1552628,54,6,22,11,'Uslyšeli pak synové Izraelští, že praveno bylo: Aj, vystavěli synové Rubenovi a synové Gádovi, a polovice pokolení Manassesova oltář naproti zemi Kananejské, při pomezi u Jordánu, kdež přešli synové Izraelští.'),
(1552629,54,6,22,12,'Uslyševše, pravím, synové Izraelští, sešlo se všecko množství jejich do Sílo, aby táhli proti nim k boji.'),
(1552630,54,6,22,13,'I poslali synové Izraelští k synům Rubenovým a k synům Gádovým a ku polovici pokolení Manassesova do země Galád Fínesa, syna Eleazara kněze,'),
(1552631,54,6,22,14,'A deset knížat s ním, po jednom knížeti z každého domu otcovského, ze všech pokolení Izraelských. (Každý pak z nich byl přední v domě otců svých v tisících Izraele.)'),
(1552632,54,6,22,15,'Ti přišli k synům Rubenovým a k synům Gádovým a ku polovici pokolení Manassesova do země Galád, a mluvili s nimi, řkouce:'),
(1552633,54,6,22,16,'Toto praví všecko shromáždění Hospodinovo: Jaké jest to přestoupení, jímž jste přestoupili proti Bohu Izraelskému, odvrátivše se dnes, abyste nešli za Hospodinem, vzdělavše sobě oltář, abyste se protivili dnes Hospodinu?'),
(1552634,54,6,22,17,'Ještě-liž se nám malá zdá nepravost modly Fegor, od níž nejsme očištěni až do dnes, pročež byla rána v shromáždění Hospodinovu,'),
(1552635,54,6,22,18,'Že vy přes to odvracujete se dnes, abyste nešli za Hospodinem? I stane se, poněvadž vy dnes odporujete Hospodinu, že on zítra na všecko shromáždění Izraelské rozhěvá se.'),
(1552636,54,6,22,19,'Jestližeť jest nečistá země vládařství vašeho, přejděte do země vládařství Hospodinova, v níž přebývá stánek Hospodinův, a dědictví vezměte mezi námi; toliko proti Hospodinu se nepostavujte, a nebuďte odporní nám, stavějíce sobě oltář mimo oltář Hospodina Boha našeho.'),
(1552637,54,6,22,20,'Zdali Achan syn Záre nedopustil se přestoupení při věci proklaté? A přišlo rozhněvání na všecko shromáždění Izraelské, a on sám jeden zhřešiv, nezahynul pro svou nepravost sám.'),
(1552638,54,6,22,21,'I odpověděli synové Rubenovi a synové Gádovi a polovice pokolení Manassesova, a mluvili s knížaty tisíců Izraelských:'),
(1552639,54,6,22,22,'Silný Bůh Hospodin, silný Bůh Hospodin, onť ví, ano sám Izrael pozná, žeť jsme ne z zpoury a všetečnosti proti Hospodinu to učinili, jináč nezachovávejž nás ani dne tohoto.'),
(1552640,54,6,22,23,'Jistě žeť jsme nestavěli sobě oltáře k tomu, abychom se odvrátiti měli a nejíti za Hospodinem, ani k obětování na něm zápalů a obětí suchých, a k obětování na něm obětí pokojných, sic jináč Hospodin sám ať to vyhledává.'),
(1552641,54,6,22,24,'Anobrž raději obávajíce se té věci, učinili jsme to, myslíce: Potom mluviti budou synové vaši synům našim, řkouce: Co vám do Hospodina Boha Izraelského?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552642,54,6,22,25,'Poněvadž meze položil Hospodin mezi námi a vámi, ó synové Rubenovi a synové Gádovi, Jordán tento, nemáte vy dílu v Hospodinu. I odvrátí synové vaši syny naše od bázně Hospodinovy.'),
(1552643,54,6,22,26,'Protož jsme řekli: Přičiňme se a vzdělejme oltář, ne pro zápaly a oběti,'),
(1552644,54,6,22,27,'Ale aby byl svědkem mezi námi a vámi, a mezi potomky našimi po nás, k vykonávání služby Hospodinu před ním zápaly našimi, a obětmi našimi a pokojnými obětmi našimi, a aby neřekli potom synové vaši synům našim: Nemáte dílu v Hospodinu.'),
(1552645,54,6,22,28,'Protož jsme řekli: Jestliže by potom mluvili nám neb potomkům našim, tedy odpovíme: Vizte podobenství oltáře Hospodinova, kterýž učinili otcové naši, ne pro zápaly ani oběti, ale aby byl na svědectví mezi námi a vámi.'),
(1552646,54,6,22,29,'Odstup to od nás, abychom odporovati měli Hospodinu, a odvraceti se dnes a nejíti za Hospodinem, stavějíce oltář k zápalům, k obětem suchým a jiným obětem, mimo oltář Hospodina Boha našeho, kterýž jest před stánkem jeho.'),
(1552647,54,6,22,30,'Uslyšev pak Fínes kněz a knížata shromáždění a přední z tisíců Izraelských, kteříž s ním byli, slova, kteráž mluvili synové Rubenovi a synové Gádovi a synové Manassesovi, líbilo se jim.'),
(1552648,54,6,22,31,'I řekl Fínes, syn Eleazara kněze, synům Rubenovým a synům Gádovým, i synům Manassesovým: Nyní jsme poznali, že u prostřed nás jest Hospodin, a že jste se nedopustili proti Hospodinu přestoupení toho, a tak vysvobodili jste syny Izraelské z ruky Hospodinovy.'),
(1552649,54,6,22,32,'Tedy navrátil se Fínes, syn Eleazara kněze, i ta knížata od synů Rubenových a od synů Gádových z země Galád do země Kananejské k synům Izraelským a oznámili jim tu věc.'),
(1552650,54,6,22,33,'I líbilo se to synům Izraelským, a dobrořečili Boha synové Izraelští, a již více nemluvili o to, aby táhli proti nim k boji a zkazili zemi, v kteréž synové Rubenovi a synové Gádovi bydlili.'),
(1552651,54,6,22,34,'Nazvali pak synové Rubenovi a synové Gádovi oltář ten Ed, řkouce: Nebo svědkem bude mezi námi, že Hospodin jest Bůh.'),
(1552652,54,6,23,1,'I stalo se po mnohých dnech, když dal Hospodin odpočinutí Izraelovi ode všech nepřátel jejich vůkol, a Jozue se sstaral a sešel věkem,'),
(1552653,54,6,23,2,'Že povolav Jozue všeho Izraele, starších jeho i předních jeho soudců i správců jeho, řekl jim: Já jsem se sstaral a sešel věkem.'),
(1552654,54,6,23,3,'A vy jste viděli všecko to, co jest učinil Hospodin Bůh váš všechněm národům těm před oblíčejem vaším; nebo Hospodin Bůh váš onť bojoval za vás.'),
(1552655,54,6,23,4,'Pohleďte, losem rozdělil jsem vám ty národy pozůstalé v dědictví po pokoleních vašich od Jordánu, i všecky národy, kteréž jsem vyplénil až k moři velikému na západ slunce.'),
(1552656,54,6,23,5,'Hospodin pak Bůh váš onť je vyžene od tváři vaší, a vypudí je před oblíčejem vaším, a vy dědičně obdržíte zemi jejich, jakož mluvil vám Hospodin Bůh váš.'),
(1552657,54,6,23,6,'Protož zmužile se mějte, abyste ostříhali a činili všecko, což psáno jest v knize zákona Mojžíšova, a neodstupovali od něho na pravo ani na levo.'),
(1552658,54,6,23,7,'Nesměšujte se s těmi národy, kteříž pozůstávají s vámi, a jména bohů jejich nepřipomínejte, ani skrze ně přisahejte, aniž jim služte, ani se jim klanějte.'),
(1552659,54,6,23,8,'Ale přídržte se Hospodina Boha svého, jakož jste činili až do tohoto dne.'),
(1552660,54,6,23,9,'I budeť, že jakož jest vyhnal Hospodin od tváři vaší národy veliké a silné, aniž ostál kdo před oblíčejem vaším až do tohoto dne:'),
(1552661,54,6,23,10,'Tak jeden z vás honiti bude tisíc, nebo Hospodin Bůh váš onť bojuje za vás, jakož mluvil vám.'),
(1552662,54,6,23,11,'Toho tedy nejpilnější buďte, abyste milovali Hospodina Boha svého.'),
(1552663,54,6,23,12,'Nebo jestliže předce se odvrátíte, a připojíte se k těm pozůstalým národům, k těm, kteříž zůstávají mezi vámi, a vejdete s nimi v příbuzenství a smísíte se s nimi a oni s vámi:'),
(1552664,54,6,23,13,'Tedy jistotně vězte, že Hospodin Bůh váš nebude více vyháněti všech národů těch od tváři vaší, ale budou vám osídlem a úrazem i bičem na bocích vašich, a trním v očích vašich, dokudž nezahynete z země této výborné, kterouž vám dal Hospodin Bůh váš.'),
(1552665,54,6,23,14,'A hle, já nyní odcházím podlé způsobu všech lidí, poznejtež tedy vším srdcem svým a celou duší svou, že nepochybilo ani jedno slovo ze všech slov nejlepších, kteráž mluvil Hospodin Bůh váš o vás; všecko se naplnilo vám, ani jediné slovo z nich nepominulo.'),
(1552666,54,6,23,15,'Jakož tedy naplnilo se vám dnes každé slovo dobré, kteréž mluvil k vám Hospodin Bůh váš, takť uvede na vás každé slovo zlé, dokudž nevyhladí vás z země této výborné, kterouž dal vám Hospodin Bůh váš,'),
(1552667,54,6,23,16,'Jestliže přestoupíte smlouvu Hospodina Boha svého, kterouž přikázal vám, a jdouce, sloužiti budete bohům cizím, a klaněti se jim. I rozhěvá se prchlivost Hospodinova na vás, a zahynete rychle z země této výborné, kterouž vám dal.'),
(1552668,54,6,24,1,'Shromáždil pak Jozue všecka pokolení Izraelská v Sichem a svolal starší Izraelské a přední z nich, i soudce a správce jejich, i postavili se před oblíčejem Božím.'),
(1552669,54,6,24,2,'I řekl Jozue všemu lidu: Toto praví Hospodin Bůh Izraelský: Za řekou bydlili otcové vaši za starodávna, jmenovitě Táre, otec Abrahamův a otec Náchorův, a sloužili bohům cizím.'),
(1552670,54,6,24,3,'I vzal jsem otce vašeho Abrahama z místa, kteréž jest za řekou, a provedl jsem jej skrze všecku zemi Kananejskou, a rozmnožil jsem símě jeho, dav jemu Izáka.'),
(1552671,54,6,24,4,'A Izákovi dal jsem Jákoba a Ezau. I dal jsem Ezau horu Seir, aby vládl jí; Jákob pak a synové jeho sstoupili do Egypta.'),
(1552672,54,6,24,5,'I poslal jsem Mojžíše a Arona, a zbil jsem Egypt, a když jsem to učinil u prostřed něho, potom vyvedl jsem vás.'),
(1552673,54,6,24,6,'A vyvedl jsem otce vaše z Egypta, i přišli jste k moři, a honili Egyptští otce vaše s vozy a jezdci až k moři Rudému.'),
(1552674,54,6,24,7,'Tedy volali k Hospodinu, kterýž postavil mrákotu mezi vámi a Egyptskými, a uvedl na ně moře, i zatopilo je; anobrž viděly oči vaše i to, co jsem učinil při Egyptu, a bydlili jste na poušti za dlouhý čas.'),
(1552675,54,6,24,8,'Potom uvedl jsem vás do země Amorejského, kterýž bydlil za Jordánem, a bojovali s vámi; i dal jsem je v ruku vaši, a opanovali jste zemi jejich, a zahladil jsem je před tváří vaší.'),
(1552676,54,6,24,9,'Povstal pak Balák syn Seforův, král Moábský, a bojoval s Izraelem; i poslav, povolal Baláma syna Beorova, aby zlořečil vám.'),
(1552677,54,6,24,10,'Ale nechtěl jsem slyšeti Baláma, pročež stále dobrořečil vám, a tak vysvobodil jsem vás z ruky jeho.'),
(1552678,54,6,24,11,'A když jste přešli Jordán, přišli jste k Jerichu; i bojovali proti vám muži Jericha, Amorejští, a Ferezejští, a Kananejští, a Hetejští, a Gergezejští, a Hevejští, a Jebuzejští, a dal jsem je v ruku vaši.'),
(1552679,54,6,24,12,'Poslal jsem před vámi i sršně, kteřížto vyhnali je od tváři vaší, dva krále Amorejské; ne mečem ani lučištěm svým tys je vyhnal.'),
(1552680,54,6,24,13,'A dal jsem vám zemi, v níž jste nepracovali, a města, kterýchž jste nestavěli, v nichž bydlíte; vinic a olivoví, kteréhož jste neštípili, užíváte.'),
(1552681,54,6,24,14,'Protož nyní bojte se Hospodina, a služte jemu v dokonalosti a v pravdě, a odvrzte bohy, jimž sloužili otcové vaši za řekou a v Egyptě, a služte Hospodinu.'),
(1552682,54,6,24,15,'Pakli se vám zdá zle sloužiti Hospodinu, vyvolte sobě dnes, komu byste sloužili, buď bohy, jimž sloužili otcové vaši, kteříž byli za řekou, buď bohy Amorejských, v jichž zemi bydlíte; jáť pak a dům můj sloužiti budeme Hospodinu.'),
(1552683,54,6,24,16,'Jemuž odpověděl lid, řka: Odstup to od nás, abychom opustiti měli Hospodina a sloužiti bohům cizím.'),
(1552684,54,6,24,17,'Nebo Hospodin Bůh náš onť jest, kterýž vyvedl nás i otce naše z země Egyptské, z domu služebnosti, a kterýž činil před očima našima znamení ta veliká, a choval nás na vší cestě, po níž jsme šli, a mezi všemi národy, skrze něž jsme prošli.'),
(1552685,54,6,24,18,'A vypudil Hospodin všecky národy, zvláště Amorejského, obyvatele země této, před tváří naší; my také sloužiti budeme Hospodinu, nebo on jest Bůh náš.'),
(1552686,54,6,24,19,'I řekl Jozue lidu: Nebudete moci sloužiti Hospodinu, nebo Bůh svatý jest, Bůh silný horlivý jest, nesnese nepravostí vašich a hříchů vašich.'),
(1552687,54,6,24,20,'Jestliže byste opustíce Hospodina, sloužili bohům cizozemců, obrátí se a zle učiní vám, a zkazí vás, poněvadž prvé dobře učinil vám.'),
(1552688,54,6,24,21,'Jemuž odpověděl lid: Nikoli, ale Hospodinu sloužiti budeme.'),
(1552689,54,6,24,22,'I řekl Jozue lidu: Svědkové budete sami proti sobě, že jste sobě vyvolili Hospodina, abyste jemu sloužili. Tedy odpověděli: Svědkové jsme.'),
(1552690,54,6,24,23,'Jimž on řekl: Odvrztež tedy nyní bohy cizozemců, kteříž jsou u prostřed vás, a nakloňte srdcí svých k Hospodinu Bohu Izraelskému.'),
(1552691,54,6,24,24,'Odpověděl lid Jozue: Hospodinu Bohu našemu sloužiti a hlasu jeho poslouchati budeme.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552692,54,6,24,25,'A tak učinil Jozue toho dne smlouvu s lidem, a předložil jim ustanovení a soudy v Sichem.'),
(1552693,54,6,24,26,'A zapsal Jozue slova ta do knihy zákona Božího; vzav také kámen veliký, postavil jej tu pod dubem, kterýž byl u svatyně Hospodinovy.'),
(1552694,54,6,24,27,'I řekl Jozue všemu lidu: Aj, kámen tento bude mezi námi na svědectví, nebo on slyšel všecka slova Hospodinova, kteráž mluvil s námi, a bude na svědectví proti vám, abyste snad neklamali proti Bohu svému.'),
(1552695,54,6,24,28,'A rozpustil Jozue lid, jednoho každého do dědictví jeho.'),
(1552696,54,6,24,29,'I stalo se po vykonání těch věcí, že umřel Jozue syn Nun, služebník Hospodinův, jsa ve stu a desíti letech.'),
(1552697,54,6,24,30,'A pochovali ho v krajině dědictví jeho, v Tamnatsáre, kteréž jest na hoře Efraim k straně půlnoční hory Gás.'),
(1552698,54,6,24,31,'I sloužil Izrael Hospodinu po všecky dny Jozue, i po všecky dny starších, kteříž dlouho živi byli po Jozue, a kteříž povědomi byli všech skutků Hospodinových, kteréž učinil Izraelovi.'),
(1552699,54,6,24,32,'Kosti pak Jozefovy, kteréž byli vynesli synové Izraelští z Egypta, pochovali v Sichem, v dílu pole, kteréž koupil Jákob od synů Emora otce Sichemova za sto peněz; i byly u synů Jozefových v dědictví jejich.'),
(1552700,54,6,24,33,'Eleazar také, syn Aronův, umřel, a pochovali jej na pahrbku Fínesa syna jeho, kterýž dán byl jemu na hoře Efraim.'),
(1552701,54,7,1,1,'Stalo se pak po smrti Jozue, otázali se synové Izraelští Hospodina, řkouce: Kdo z nás potáhne proti Kananejskému napřed, aby bojoval s ním?'),
(1552702,54,7,1,2,'Jimž řekl Hospodin: Juda nechť táhne, aj, dal jsem tu zemi v ruku jeho.'),
(1552703,54,7,1,3,'(Řekl pak byl Juda Simeonovi bratru svému: Potáhni se mnou k dobývání losu mého, abychom bojovali proti Kananejskému, a já také potáhnu s tebou k dobývání losu tvého. I táhl s ním Simeon.'),
(1552704,54,7,1,4,'Tedy vytáhl Juda, i dal Hospodin Kananejského a Ferezejského v ruce jejich, a porazili z nich v Bezeku deset tisíc mužů.'),
(1552705,54,7,1,5,'Nebo nalezše Adonibezeka v Bezeku, bojovali proti němu, a porazili Kananejského i Ferezejského.'),
(1552706,54,7,1,6,'Když pak utíkal Adonibezek, honili ho, a chytivše jej, zutínali mu palce u rukou i noh.'),
(1552707,54,7,1,7,'Tedy řekl Adonibezek: Sedmdesáte králů s uťatými palci u rukou i noh svých sbírali drobty pod stolem mým; jakž jsem činil, tak odplatil mi Bůh. I přivedli jej do Jeruzaléma, a tam umřel.'),
(1552708,54,7,1,8,'Nebo byli vybojovali synové Juda Jeruzalém, a vzavše jej, zbili obyvatele jeho ostrostí meče a město vypálili.'),
(1552709,54,7,1,9,'Potom také vytáhli synové Judovi, aby bojovali proti Kananejskému, bydlícímu na horách při straně polední i na rovinách.'),
(1552710,54,7,1,10,'Nebo byl vytáhl Juda proti Kananejskému, kterýž bydlil v Hebronu, (jméno pak Hebronu prvé bylo Kariatarbe,) a pobil Sesaie, a Achimana, a Tolmaie.'),
(1552711,54,7,1,11,'A odtud byl táhl na obyvatele Dabir, (jméno pak Dabir prvé bylo Kariatsefer).'),
(1552712,54,7,1,12,'Kdežto řekl Kálef: Kdo by dobyl Kariatsefer a vzal by je, dám jemu Axu dceru svou za manželku.'),
(1552713,54,7,1,13,'Tedy dobyl ho Otoniel, syn Cenezův, bratra Kálefova mladšího, i dal jemu Axu dceru svou za manželku.'),
(1552714,54,7,1,14,'Stalo se pak, že když přišla k němu, ponukla ho, aby prosil otce jejího za pole; i ssedla s osla. A řekl jí Kálef: Cožť jest?'),
(1552715,54,7,1,15,'A ona odpověděla: Dej mi dar; poněvadžs mi dal zemi suchou, dej mi také studnice vod. I dal jí Kálef studnice v horních i dolních končinách.'),
(1552716,54,7,1,16,'Synové také Cinejského, tchána Mojžíšova, odebrali se z města palmového s syny Juda na poušť Judovu, jenž jest k straně polední městu Arad; a odšedše, bydlili s lidem tím.'),
(1552717,54,7,1,17,'Potom táhl Juda s Simeonem, bratrem svým, a porazili Kananejské přebývající v Sefat, a zkazili je. I nazváno jest jméno města toho Horma.'),
(1552718,54,7,1,18,'Dobyl také Juda Gázy a pomezí jeho, i Aškalonu s pomezím jeho, též Akaronu a pomezí jeho.'),
(1552719,54,7,1,19,'Nebo byl Hospodin s Judou, a vyhnal obyvatele hor, ale nevyhnal obyvatelů údolí, proto že vozy železné měli.'),
(1552720,54,7,1,20,'I dali Kálefovi Hebron, jakož byl mluvil Mojžíš, a vyhnal odtud tři syny Enakovy.'),
(1552721,54,7,1,21,'Jebuzejského pak, bydlícího v Jeruzalémě, nevyhnali synové Beniamin; protož bydlil Jebuzejský v Jeruzalémě s syny Beniamin až do tohoto dne.'),
(1552722,54,7,1,22,'Vytáhla také i čeled Jozefova do Bethel, a Hospodin byl s nimi.'),
(1552723,54,7,1,23,'Nebo shlédla čeled Jozefova Bethel, kteréhožto města jméno prvé bylo Lůza.'),
(1552724,54,7,1,24,'Uzřevše pak ti špehéři muže vycházejícího z města, řekli jemu: Medle ukaž nám, kudy bychom mohli vjíti do města, a učinímeť milost.'),
(1552725,54,7,1,25,'Kterýžto ukázal jim, kudy by mohli vjíti do města; i vyhubili to město mečem, muže pak toho se vší čeledí jeho propustili.'),
(1552726,54,7,1,26,'I šel muž ten do země Hetejských, kdež vystavěl město, a nazval jméno jeho Lůza; to jest jméno jeho až do tohoto dne.'),
(1552727,54,7,1,27,'Manasses také nevyhnal obyvatelů Betsan a městeček jeho, ani Tanach a městeček jeho, ani obyvatelů Dor a Jibleam, a Mageddo a městeček jejich; i počal Kananejský svobodně bydliti v zemi té.'),
(1552728,54,7,1,28,'Když se pak zsilil Izrael, uvedl Kananejského pod plat, a maje jej vyhnati, nevyhnal.'),
(1552729,54,7,1,29,'Efraim také nevyhnal Kananejského bydlícího v Gázer, protož bydlil Kananejský u prostřed něho v Gázer.'),
(1552730,54,7,1,30,'Zabulon též nevyhnal obyvatelů Cetron, a obyvatelů Naalol, protož bydlil Kananejský u prostřed něho, a dával jemu plat.'),
(1552731,54,7,1,31,'Asser také nevyhnal obyvatelů Acho a obyvatelů Sidonu, ani Ahalab, ani Achzib, ani Helba, ani Afek, ani Rohob.'),
(1552732,54,7,1,32,'I bydlil Asser mezi Kananejskými obyvateli země té, nebo nevyhnal jich.'),
(1552733,54,7,1,33,'Též Neftalím nevyhnal obyvatelů Betsemes, ani obyvatelů Betanat, protož bydlil mezi Kananajeskými přebývajícími v zemi té; a však obyvatelé Betsemes a Betanat dávali jim plat.'),
(1552734,54,7,1,34,'Ssužovali pak Amorejští syny Dan na horách, tak že nedali jim scházeti do údolí.'),
(1552735,54,7,1,35,'Nebo počal Amorejský svobodně bydliti na hoře Heres, v Aialon a v Salbim, ale když se zsilila ruka čeledi Jozefovy, uvedeni jsou pod plat.'),
(1552736,54,7,1,36,'Pomezí pak Amorejského bylo od začátku hor Akrabim, od skály jejich i výše.'),
(1552737,54,7,2,1,'Vstoupil pak anděl Hospodinův z Galgala do Bochim a řekl: Vyvedl jsem vás z Egypta a uvedl jsem vás do země, kterouž jsem s přísahou zaslíbil otcům vašim, a řekl jsem: Nezruším smlouvy své s vámi na věky.'),
(1552738,54,7,2,2,'Vy také nečiňte smlouvy s obyvateli země této, oltáře jejich rozkopejte; ale neposlechli jste hlasu mého. Co jste to učinili?'),
(1552739,54,7,2,3,'Pročež také jsem řekl: Nevyhladím jich před tváří vaší, ale budou vám jako trní, a bohové jejich budou vám osídlem.'),
(1552740,54,7,2,4,'I stalo se, když mluvil anděl Hospodinův slova tato všechněm synům Izraelským, že pozdvihl hlasu svého lid a plakal.'),
(1552741,54,7,2,5,'I nazvali jméno místa toho Bochim, a obětovali tu Hospodinu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552742,54,7,2,6,'Rozpustil pak byl Jozue lid, a rozešli se synové Izraelští, jeden každý do dědictví svého, aby vládli zemí.'),
(1552743,54,7,2,7,'I sloužil lid Hospodinu po všecky dny Jozue, a po všecky dny starších, kteříž dlouho živi byli po Jozue, jenž viděli všecky skutky veliké Hospodinovy, kteréž učinil Izraelovi.'),
(1552744,54,7,2,8,'Ale když umřel Jozue syn Nun, služebník Hospodinův, jsa ve stu a desíti letech,'),
(1552745,54,7,2,9,'A pochovali ho v krajině dědictví jeho, v Tamnatheres, na hoře Efraim, k straně půlnoční hory Gás;'),
(1552746,54,7,2,10,'Také když všecken věk ten připojen jest k otcům svým, a povstal jiný věk po nich, kteříž neznali Hospodina, ani skutků, kteréž učinil Izraelovi:'),
(1552747,54,7,2,11,'Tedy činili synové Izraelští to, což jest zlého před očima Hospodinovýma, a sloužili modlám,'),
(1552748,54,7,2,12,'Opustivše Hospodina Boha otců svých, kterýž je vyvedl z země Egyptské, a odešli za bohy cizími, bohy těch národů, kteříž byli vůkol nich, a klaněli se jim; pročež popudili Hospodina.'),
(1552749,54,7,2,13,'Nebo opustivše Hospodina, sloužili Bálovi i Astarotům.'),
(1552750,54,7,2,14,'I rozpálila se prchlivost Hospodinova na Izraele, a vydal je v ruku loupežníků, kteříž je zloupili; vydal je, pravím, v ruku nepřátel jejich vůkol, tak že nemohli více ostáti před nepřátely svými.'),
(1552751,54,7,2,15,'Kamžkoli vycházeli, ruka Hospodinova byla proti nim ke zlému, jakož byl mluvil Hospodin, a jakož byl zapřisáhl jim Hospodin; i ssouženi byli náramně.'),
(1552752,54,7,2,16,'Vzbuzoval pak Hospodin soudce, kteříž vysvobozovali je z rukou zhoubců jejich.'),
(1552753,54,7,2,17,'Ale ani soudců svých neposlouchali, nebo smilnili, odcházejíce za bohy cizími, a klaněli se jim. Odcházeli rychle s cesty, po kteréž chodili otcové jejich, tak že poslouchati majíce přikázaní Hospodinových, nečinili toho.'),
(1552754,54,7,2,18,'A když vzbuzoval jim Hospodin soudce, býval Hospodin s každým soudcím, a vysvobozoval je z ruky nepřátel jejich po všecky dny soudce; (nebo želel Hospodin naříkání jejich, k němuž je přivodili ti, kteříž je ssužovali a utiskali).'),
(1552755,54,7,2,19,'Po smrti pak soudce navracejíce se zase, pohoršovali cest svých více nežli otcové jejich, odcházejíce za bohy cizími, a sloužíce i klanějíce se jim; nic neulevili z skutků jejich zlých a cesty jejich převrácené.'),
(1552756,54,7,2,20,'Protož rozpálila se prchlivost Hospodinova proti Izraelovi, a řekl: Proto že přestoupil národ tento smlouvu mou, kterouž jsem učinil s otci jejich, a neposlouchali hlasu mého:'),
(1552757,54,7,2,21,'Já také více nevyhladím žádného od tváři jejich z národů, kterýchž zanechal Jozue, když umřel,'),
(1552758,54,7,2,22,'Abych skrze ně zkušoval Izraele, budou-li ostříhati cesty přikázaní Hospodinových, chodíce v nich, jakož ostříhali otcové jejich, čili nic.'),
(1552759,54,7,2,23,'I zanechal Hospodin národů těch, a nevyhnal jich rychle, aniž dal jich v ruku Jozue.'),
(1552760,54,7,3,1,'Tito pak jsou národové, kterýchž zanechal Hospodin, aby skrze ně zkušoval Izraele,totiž všech, kteříž nevěděli o žádných válkách Kananejských,'),
(1552761,54,7,3,2,'Aby aspoň zvěděli věkové synů Izraelských, a poznali, co jest to válka, čehož první něvěděli:'),
(1552762,54,7,3,3,'Patero knížat Filistinských, a všickni Kananejští a Sidonští a Hevejští bydlící na hoře Libánské od hory Balhermon až tam, kudy se vchází do Emat.'),
(1552763,54,7,3,4,'Ti pozůstali, aby zkušován byl skrze ně Izrael, a aby známé bylo, budou-li poslouchati přikázaní Hospodinových, kteráž přikázal otcům jejich skrze Mojžíše.'),
(1552764,54,7,3,5,'Bydlili tedy synové Izraelští u prostřed Kananejských, Hetejských a Amorejských, a Ferezejských a Hevejských a Jebuzejských,'),
(1552765,54,7,3,6,'A brali sobě dcery jejich za manželky, a dcery své dávali synům jejich, a sloužili bohům jejich.'),
(1552766,54,7,3,7,'Činili tedy synové Izraelští to, což jest zlého před očima Hospodinovýma, a zapomenuvše se na Hospodina Boha svého, sloužili Bálům a Asserotům.'),
(1552767,54,7,3,8,'Protož rozpálila se prchlivost Hospodinova na Izraele, a vydal jej v ruku Chusana Risataimského, krále Syrského v Mezopotamii; i sloužili synové Izraelští Chusanovi Risataimskému osm let.'),
(1552768,54,7,3,9,'Volali pak synové Izraelští k Hospodinu, i vzbudil Hospodin vysvoboditele synům Izraelským, aby je vysvobodil, Otoniele syna Cenezova bratra Kálefova mladšího,'),
(1552769,54,7,3,10,'Na němž byl duch Hospodinův, a soudil lid Izraelský. Když pak vytáhl k boji, dal Hospodin v ruce jeho Chusana Risataimského, krále Syrského, a zmocnila se ruka jeho nad Chusanem Risataimským.'),
(1552770,54,7,3,11,'A tak v pokoji byla země za čtyřidceti let; i umřel Otoniel, syn Cenezův.'),
(1552771,54,7,3,12,'Takž opět činili synové Izraelští to, což jest zlého před očima Hospodinovýma. I zsilil Hospodin Eglona, krále Moábského, proti Izraelovi, proto že činili zlé věci před očima Hospodinovýma.'),
(1552772,54,7,3,13,'Nebo shromáždil k sobě syny Ammonovy a Amalechovy, a vytáh, porazil Izraele, a opanovali město palmové.'),
(1552773,54,7,3,14,'I sloužili synové Izraelští Eglonovi králi Moábskému osmnácte let.'),
(1552774,54,7,3,15,'Potom volali synové Izraelští k Hospodinu. I vzbudil jim Hospodin vysvoboditele Ahoda, syna Gery Beniaminského, muže rukou pravou nevládnoucího. I poslali synové Izraelští po něm dar Eglonovi králi Moábskému.'),
(1552775,54,7,3,16,'(Připravil pak sobě Ahod meč na obě straně ostrý, lokte zdélí, a připásal jej sobě pod šaty svými po pravé straně.)'),
(1552776,54,7,3,17,'I přinesl dar Eglonovi králi Moábskému. Eglon pak byl člověk velmi tlustý.'),
(1552777,54,7,3,18,'A když dodal daru, propustil lid, kterýž byl přinesl dar.'),
(1552778,54,7,3,19,'Sám pak vrátiv se od lomů blízko Galgala, řekl: Tajnou věc mám k tobě, ó králi. I řekl král: Mlč. A vyšli od něho všickni, kteříž stáli při něm.'),
(1552779,54,7,3,20,'Tehdy Ahod přistoupil k němu, (on pak seděl na paláci letním sám). I řekl mu Ahod: Řeč Boží mám k tobě. I vstal z stolice své.'),
(1552780,54,7,3,21,'Tedy sáhna Ahod rukou svou levou, vzal meč u pravého boku svého a vrazil jej do břicha jeho,'),
(1552781,54,7,3,22,'Tak že i jilce za ostřím vešly tam, a zavřel se tukem meč, (nebo nevytáhl meče z břicha jeho;) i vyšla lejna.'),
(1552782,54,7,3,23,'Potom vyšel Ahod přes síň, a zavřel dvéře paláce po sobě, a zamkl.'),
(1552783,54,7,3,24,'Když pak on odšel, služebníci jeho přišedše, uzřeli, a hle, dvéře palácu zamčíny. Tedy řekli: Jest na potřebě v pokoji letním.'),
(1552784,54,7,3,25,'A když očekávali dlouho, až se styděli, a aj, neotvíral dveří paláce, tedy vzali klíč a otevřeli, a hle, pán jejich leží na zemi mrtvý.'),
(1552785,54,7,3,26,'Ahod pak mezi tím, když oni prodlévali, ušel, a přešed lomy, přišel do Seirat.'),
(1552786,54,7,3,27,'A přišed k svým, troubil v troubu na hoře Efraim; i sstoupili s ním synové Izraelští s hory, a on napřed šel.'),
(1552787,54,7,3,28,'Nebo řekl jim: Poďte za mnou, dalť jest zajisté Hospodin Moábské, nepřátely vaše, v ruku vaši. Tedy táhli za ním, a vzavše Moábským brody Jordánské, nedali žádnému přejíti.'),
(1552788,54,7,3,29,'I pobili tehdáž Moábských okolo desíti tisíc mužů, každého bohatého a všelikého silného muže, aniž kdo ušel.'),
(1552789,54,7,3,30,'I snížen jest Moáb v ten den pod mocí Izraele, a pokoj měla země za osmdesáte let.'),
(1552790,54,7,3,31,'Po něm pak byl Samgar, syn Anatův, a pobil Filistinských šest set mužů ostnem volů, a vysvobodil i on Izraele.'),
(1552791,54,7,4,1,'Po smrti pak Ahoda činili opět synové Izraelští to, což jest zlého před očima Hospodinovýma.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552792,54,7,4,2,'I vydal je Hospodin v ruce Jabína krále Kananejského, kterýž kraloval v Azor; (a kníže vojska jeho byl Zizara), sám pak bydlil v Haroset pohanském.'),
(1552793,54,7,4,3,'Tedy volali synové Izraelští k Hospodinu; nebo devět set vozů železných měl, a on násilně ssužoval Izraele za dvadceti let.'),
(1552794,54,7,4,4,'Debora pak žena prorokyně, manželka Lapidotova, soudila lid Izraelský toho času.'),
(1552795,54,7,4,5,'(A bydlila Debora pod palmou, mezi Ráma a mezi Bethel na hoře Efraim), i chodili k ní synové Izraelští k soudu.'),
(1552796,54,7,4,6,'Kterážto poslavši, povolala Baráka, syna Abinoemova, z Kádes Neftalímova, a řekla jemu: Zdaližť nerozkázal Hospodin Bůh Izraelský: Jdi, a shromáždě lid na horu Tábor, vezmi s sebou deset tisíc mužů z synů Neftalím a z synů Zabulon.'),
(1552797,54,7,4,7,'Nebo přitáhnu k tobě ku potoku Císon Zizaru kníže vojska Jabínova, a vozy jeho i množství jeho, a dám jej v ruku tvou.'),
(1552798,54,7,4,8,'I řekl jí Barák: Půjdeš-li se mnou, půjdu; pakli nepůjdeš se mnou, nepůjdu.'),
(1552799,54,7,4,9,'Kteráž odpověděla: Jáť zajisté půjdu s tebou, ale nebudeť s slávou tvou cesta, kterouž půjdeš, nebo v ruku ženy dá Hospodin Zizaru. Tedy vstavši Debora, šla s Barákem do Kádes.'),
(1552800,54,7,4,10,'Svolav pak Barák Zabulonské a Neftalímské do Kádes, vyvedl za sebou deset tisíc mužů; a šla s ním i Debora.'),
(1552801,54,7,4,11,'Heber pak Cinejský oddělil se od Kaina, od synů Chobab, tchána Mojžíšova, a rozbil stany své až k Elon v Sananim, jenž jest v Kádes.'),
(1552802,54,7,4,12,'Oznámeno pak bylo Zizarovi, že vytáhl Barák syn Abinoemův na horu Tábor.'),
(1552803,54,7,4,13,'Protož shromáždil Zizara všecky vozy své, devět set vozů železných, a všecken lid, kterýž měl s sebou z Haroset pohanského, ku potoku Císon.'),
(1552804,54,7,4,14,'I řekla Debora Barákovi: Vstaň, nebo tento jest den, v němž dal Hospodin Zizaru v ruku tvou. Zdali Hospodin nevyšel před tebou? I sstoupil Barák s hory Tábor, a deset tisíc mužů za ním.'),
(1552805,54,7,4,15,'A porazil Hospodin Zizaru a všecky ty vozy, i všecka ta vojska ostrostí meče před Barákem; a sskočiv Zizara s vozu, utíkal pěšky.'),
(1552806,54,7,4,16,'Ale Barák honil ty vozy a vojsko až do Haroset pohanského; i padlo všecko vojsko Zizarovo od ostrosti meče, tak že nezůstalo ani jednoho.'),
(1552807,54,7,4,17,'Zizara pak utíkal pěšky k stanu Jáhel, manželky Hebera Cinejského; nebo pokoj byl mezi Jabínem králem Azor a mezi čeledí Hebera Cinejského.'),
(1552808,54,7,4,18,'I vyšedši Jáhel v cestu Zizarovi, řekla jemu: Uchyl se, pane můj, uchyl se ke mně, neboj se. I uchýlil se k ní do stanu, a přistřela jej huní.'),
(1552809,54,7,4,19,'Kterýž řekl jí: Dej mi, prosím, píti maličko vody, nebo žízním. A otevřevši nádobu mléčnou, dala mu píti a přikryla ho.'),
(1552810,54,7,4,20,'Řekl také jí: Stůj u dveří stanu, a při-šel-li by kdo, a ptal se tebe, řka: Jest-li zde kdo? odpovíš: Není.'),
(1552811,54,7,4,21,'Potom vzala Jáhel manželka Heberova hřeb od stanu, vzala též kladivo v ruku svou, a všedši k němu tiše, vrazila hřeb do židovin jeho, až uvázl v zemi; (nebo ustav, tvrdě byl usnul), a tak umřel.'),
(1552812,54,7,4,22,'A aj, Barák honil Zizaru. I vyšla Jáhel vstříc jemu, a řekla mu: Poď, a ukážiť muže, kteréhož hledáš. I všel k ní, a aj, Zizara ležel mrtvý na zemi, a hřeb v židovinách jeho.'),
(1552813,54,7,4,23,'A tak ponížil Bůh toho dne Jabína krále Kananejského před syny Izraelskými.'),
(1552814,54,7,4,24,'I dotírala ruka synů Izraelských vždy více, a silila se proti Jabínovi králi Kananejskému, až i vyhladili téhož Jabína krále Kananejského.'),
(1552815,54,7,5,1,'Zpívala pak písničku Debora a Barák syn Abinoemův v ten den, řkouc:'),
(1552816,54,7,5,2,'Pro pomstu učiněnou v Izraeli, a pro lid, kterýž se k tomu dobrovolně měl, dobrořečte Hospodinu.'),
(1552817,54,7,5,3,'Slyštež králové, a ušima pozorujte knížata, já, já zpívati budu Hospodinu, žalmy zpívati budu Hospodinu Bohu Izraelskému.'),
(1552818,54,7,5,4,'Hospodine, když jsi vyšel z Seir, když jsi se bral z pole Edomského, třásla se země, nebesa dštila, a oblakové déšť vydali.'),
(1552819,54,7,5,5,'Hory se rozplynuly od tváři Hospodinovy, i ta hora Sinai třásla se před tváří Hospodina Boha Izraelského.'),
(1552820,54,7,5,6,'Za dnů Samgara syna Anatova, a za dnů Jáhel spustly silnice, kteříž pak šli stezkami, zacházeli cestami křivými.'),
(1552821,54,7,5,7,'Spustly vsi v Izraeli, spustly, pravím, až jsem povstala já Debora, povstala jsem matka v Izraeli.'),
(1552822,54,7,5,8,'Kterýžto kdyžkoli sobě zvoloval bohy nové, tedy bývala válka v branách, pavézy pak ani kopí nebylo vidíno mezi čtyřidcíti tisíci v Izraeli.'),
(1552823,54,7,5,9,'Srdce mé nakloněno jest k správcům Izraelským a k těm, kteříž tak ochotní byli mezi jinými. Dobrořečtež Hospodinu.'),
(1552824,54,7,5,10,'Kteříž jezdíte na bílých oslicích, kteříž bydlíte při Middin, a kteříž chodíte po cestách, vypravujtež,'),
(1552825,54,7,5,11,'Že vzdálen hluk střelců na místech, kdež se voda váží; i tam vypravujte hojnou spravedlnost Hospodinovu, hojnou spravedlnost k obyvatelům vsí jeho v Izraeli; tehdážť vstupovati bude k branám lid Hospodinův.'),
(1552826,54,7,5,12,'Povstaň, povstaň, Deboro, povstaniž, povstaniž a vypravuj píseň, povstaň, Baráku, a zajmi jaté své, synu Abinoemův.'),
(1552827,54,7,5,13,'Tehdážtě potlačenému dopomoženo k opanování silných reků z lidu; Hospodintě mi ku panování dopomohl nad silnými.'),
(1552828,54,7,5,14,'Z Efraima kořen jejich bojoval proti Amalechitským; za tebou, Efraime, Beniamin s lidem tvým; z Machira táhli vydavatelé zákona, a z Zabulona písaři.'),
(1552829,54,7,5,15,'Knížata také z Izachar s Deborou, ano i všecko pokolení Izacharovo, jako i Barák do údolí poslán jest pěšky, ale veliké hrdiny u sebe jsou v podílu Rubenovu.'),
(1552830,54,7,5,16,'Jak jsi mohl mlče seděti mezi dvěma ohradami, poslouchaje řvání stád? Veliké hrdiny u sebe jsou v podílu Rubenovu.'),
(1552831,54,7,5,17,'Zdali i Galád před Jordánem nebydlil? Ale Dan proč zůstal při lodech? Asser seděl na břehu mořském, a v lomích svých bydlil.'),
(1552832,54,7,5,18,'Zabulon, lid udatný, vynaložil duši svou na smrt, též i Neftalím na vysokých místech pole.'),
(1552833,54,7,5,19,'Králové přitáhše, bojovali, tehdáž bojovali králové Kananejští v Tanach při vodách Mageddo, a však kořisti stříbra nevzali.'),
(1552834,54,7,5,20,'S nebe bojováno, hvězdy z míst svých bojovaly proti Zizarovi.'),
(1552835,54,7,5,21,'Potok Císon smetl je, potok Kedumim, potok Císon; všecko to pošlapala jsi, duše má, udatně.'),
(1552836,54,7,5,22,'Tehdáž otloukla se kopyta koňů od dupání velikého pod jezdci silnými.'),
(1552837,54,7,5,23,'Zlořečte Merozu, praví anděl Hospodinův, zlořečte velice obyvatelům jeho, nebo nepřišli na pomoc Hospodinu, ku pomoci Hospodinu proti silným.'),
(1552838,54,7,5,24,'Požehnaná buď nad jiné ženy Jáhel, manželka Hebera Cinejského, nad ženy v staních bydlící buď požehnaná.'),
(1552839,54,7,5,25,'On vody žádal, ona mléka dala, v koflíku knížecím podala másla.'),
(1552840,54,7,5,26,'Levou ruku svou k hřebu vztáhla, a pravou ruku svou k kladivu dělníků, i udeřila Zizaru, a ztloukla hlavu jeho, probodla a prorazila židoviny jeho.'),
(1552841,54,7,5,27,'U noh jejích skrčil se, padl, ležel, u noh jejích skrčil se, padl; kdež se skrčil, tu padl zabitý.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552842,54,7,5,28,'Vyhlídala z okna skrze mříži, a naříkala matka Zizarova, řkuci: Proč se tak dlouho vůz jeho nevrací? Proč prodlévají vraceti se domů vozové jeho?'),
(1552843,54,7,5,29,'Moudřejší pak z předních služebnic jejích odpovídaly, i ona sama také sobě odpovídala:'),
(1552844,54,7,5,30,'Zdali ale dosáhli něčeho, a dělí kořisti? Děvečku jednu neb dvě na každého muže, loupeže rozdílných barev samému Zizarovi, kořisti rozdílných barev krumpovaným dílem, roucho rozdílných barev krumpovaným dílem na hrdlo loupežníků.'),
(1552845,54,7,5,31,'Tak ať zahynou všickni nepřátelé tvoji, ó Hospodine, tebe pak milující ať jsou jako slunce vzcházející v síle své. I byla v pokoji země za čtyřidceti let.'),
(1552846,54,7,6,1,'Činili pak synové Izraelští to, což jest zlého před očima Hospodinovýma, i vydal je Hospodin v ruku Madianským za sedm let.'),
(1552847,54,7,6,2,'A zmocnila se velmi ruka Madianských nad Izraelem, tak že synové Izraelští před Madianskými zdělali sobě jámy, kteréž jsou na horách, a jeskyně a pevnosti.'),
(1552848,54,7,6,3,'A bývalo, že jakž co oseli Izraelští, přitáhl Madian a Amalech a národ východní, povstávaje proti nim.'),
(1552849,54,7,6,4,'Kteřížto rozbijeli stany proti nim, a kazili úrody země, až kudy se vchází do Gázy, a nenechávali potravy v Izraeli, ani ovce, ani vola, ani osla.'),
(1552850,54,7,6,5,'Nebo i sami i s stády svými i s stany přitáhli, a jako kobylky ve množství přicházívali, aniž jich neb velbloudů jejich byl počet; tak přicházejíce do země, hubili ji.'),
(1552851,54,7,6,6,'Tedy znuzen byl velmi Izrael od Madianských, protož volali synové Izraelští k Hospodinu.'),
(1552852,54,7,6,7,'Když pak volali synové Izraelští k Hospodinu příčinou Madianských,'),
(1552853,54,7,6,8,'Poslal Hospodin muže proroka k synům Izraelským, a řekl jim: Takto praví Hospodin Bůh Izraelský: Já jsem vás vyvedl z Egypta, a vyvedl jsem vás z domu služby,'),
(1552854,54,7,6,9,'A vytrhl jsem vás z rukou Egyptských a z rukou všech, jenž vás ssužovali, kteréž jsem vyhnal před tváří vaší, a dal jsem vám zemi jejich.'),
(1552855,54,7,6,10,'I řekl jsem vám: Já jsem Hospodin Bůh váš, nebojte se bohů Amorejských, v jejichž zemi bydlíte. Ale neposlechli jste hlasu mého.'),
(1552856,54,7,6,11,'Tedy přišel anděl Hospodinův a posadil se pod dubem, jenž byl v Ofra, kteréž bylo Joasa Abiezeritského. Gedeon pak syn jeho mlátil obilí na humně, aby vezma, utekl s tím před Madianskými.'),
(1552857,54,7,6,12,'I ukázal se jemu anděl Hospodinův, a řekl jemu: Hospodin s tebou, muži udatný.'),
(1552858,54,7,6,13,'Odpověděl jemu Gedeon: Ó Pane můj, jestliže Hospodin s námi jest, pročež pak na nás přišlo všecko toto? A kde jsou všickni divové jeho, o kterýchž vypravovali nám otcové naši, řkouce: Zdaliž nás z Egypta nevyvedl Hospodin? A nyní opustil nás Hospodin a vydal v ruku Madianských.'),
(1552859,54,7,6,14,'A pohleděv na něj Hospodin, řekl: Jdi v této síle své, a vysvobodíš Izraele z ruky Madianských. Zdaliž jsem tě neposlal?'),
(1552860,54,7,6,15,'Kterýž odpověděl jemu: Poslyš mne, Pane můj, čím já vysvobodím Izraele? Hle, rod můj chaterný jest v pokolení Manassesovu, a já nejmenší v domě otce svého.'),
(1552861,54,7,6,16,'Tedy řekl jemu Hospodin: Poněvadž já budu s tebou, protož zbiješ Madianské jako muže jednoho.'),
(1552862,54,7,6,17,'Jemuž on řekl: Prosím, jestliže jsem nalezl milost před očima tvýma, dej mi znamení, že ty mluvíš se mnou.'),
(1552863,54,7,6,18,'Prosím, neodcházej odsud, až zase přijdu k tobě, a vynesu obět svou a položím před tebou. Odpověděl on: Jáť posečkám, až se navrátíš.'),
(1552864,54,7,6,19,'Tedy Gedeon všed do domu, připravil kozelce, a po měřici mouky přesných chlebů. I vložil maso do koše, a polívku vlil do hrnce, i vynesl to k němu pod dub a obětoval.'),
(1552865,54,7,6,20,'I řekl jemu anděl Boží: Vezmi to maso a chleby ty nekvašené, a polož na tuto skálu, a polívkou polej. I učinil tak.'),
(1552866,54,7,6,21,'Potom zdvihl anděl Hospodinův konec holi, kterouž měl v rukou svých, a dotekl se masa a chlebů přesných; i vystoupil oheň z skály té, a spálil to maso i chleby přesné. A v tom anděl Hospodinův odšel od očí jeho.'),
(1552867,54,7,6,22,'A vida Gedeon, že by anděl Hospodinův byl, řekl: Ach, Panovníče Hospodine, proto-liž jsem viděl anděla Hospodinova tváří v tvář, abych umřel?'),
(1552868,54,7,6,23,'I řekl jemu Hospodin: Měj pokoj, neboj se, neumřeš.'),
(1552869,54,7,6,24,'Protož vzdělal tu Gedeon oltář Hospodinu, a nazval jej: Hospodin pokoje, a až do tohoto dne ještě jest v Ofra Abiezeritského.'),
(1552870,54,7,6,25,'Stalo se pak té noci, že řekl jemu Hospodin: Vezmi volka vyspělého, kterýž jest otce tvého, totiž volka toho druhého sedmiletého, a zboříš oltář Bálův, kterýž jest otce tvého, háj také, kterýž jest vedlé něho, posekáš.'),
(1552871,54,7,6,26,'A vzděláš oltář Hospodinu Bohu svému na vrchu skály této, na rovině její, a vezma volka toho druhého, obětovati budeš obět zápalnou s dřívím háje, kterýž posekáš.'),
(1552872,54,7,6,27,'Tedy vzal Gedeon deset mužů z služebníků svých, a učinil, jakž mluvil jemu Hospodin; a boje se čeledi otce svého a mužů města, neučinil toho ve dne, ale v noci.'),
(1552873,54,7,6,28,'Když pak vstali muži města ráno, uzřeli zbořený oltář Bálův, a háj, kterýž byl vedlé něho, že byl posekaný, a volka toho druhého obětovaného v obět zápalnou na oltáři v nově vzdělaném.'),
(1552874,54,7,6,29,'I mluvili jeden k druhému: Kdo to udělal? A vyhledávajíce, vyptávali se a pravili: Gedeon syn Joasův to učinil.'),
(1552875,54,7,6,30,'Tedy řekli muži města k Joasovi: Vyveď syna svého, ať umře, proto že zbořil oltář Bálův, a že posekal háj, kterýž byl vedlé něho.'),
(1552876,54,7,6,31,'Odpověděl Joas všechněm stojícím před sebou: A což se vy nesnadniti chcete o Bále? Zdali vy jej vysvobodíte? Kdož by se zasazoval o něj, ať jest zabit hned jitra tohoto. Jestližeť jest bohem, nechať se sám zasazuje o to, že jest rozbořen oltář jeho.'),
(1552877,54,7,6,32,'I nazval jej toho dne Jerobálem, řka: Nechť se zasadí Bál proti němu, že zbořil oltář jeho.'),
(1552878,54,7,6,33,'Tedy všickni Madianští a Amalechitští a národové východní shromáždili se spolu, a přešedše Jordán, položili se v údolí Jezreel.'),
(1552879,54,7,6,34,'Duch pak Hospodinův posilnil Gedeona, kterýžto zatroubiv v troubu, svolal Abiezeritské k sobě.'),
(1552880,54,7,6,35,'A poslal posly ke všemu pokolení Manassesovu, a svoláno jest k němu; poslal též posly k Asserovi, k Zabulonovi a k Neftalímovi, i přitáhli jim na pomoc.'),
(1552881,54,7,6,36,'Tedy mluvil Gedeon k Bohu: Vysvobodíš-li skrze ruku mou Izraele, jakož jsi mluvil,'),
(1552882,54,7,6,37,'Aj, já položím rouno toto na humně. Jestliže rosa bude toliko na rouně, a na vší zemi vůkol sucho, tedy věděti budu, že vysvobodíš skrze ruku mou Izraele, jakož jsi mluvil.'),
(1552883,54,7,6,38,'I stalo se tak. Nebo vstav nazejtří, stlačil rouno, a vyžďal rosu z něho, i byl plný koflík vody.'),
(1552884,54,7,6,39,'Řekl také Gedeon Bohu: Nerozpaluj se prchlivost tvá proti mně, že promluvím ještě jednou. Prosím, nechažť zkusím ještě jednou na rouně. Nechť jest, prosím, samo rouno suché, a na vší zemi rosa.'),
(1552885,54,7,6,40,'I učinil Bůh té noci tak, a bylo samo rouno suché, a na vší zemi byla rosa.'),
(1552886,54,7,7,1,'Tedy vstav ráno Jerobál, (jenž jest Gedeon), i všecken lid, kterýž byl s ním, položili se při studnici Charod, vojska pak Madianských byla jim na půlnoci před vrchem More v údolí.'),
(1552887,54,7,7,2,'I řekl Hospodin Gedeonovi: Příliš mnoho jest lidu s tebou, protož nedám Madianských v ruce jejich, aby se nechlubil Izrael proti mně, řka: Ruka má spomohla mi.'),
(1552888,54,7,7,3,'A protož provolej hned, ať slyší lid, a řekni: Kdo jest strašlivý a lekavý, navrať se zase, a odejdi ráno pryč k hoře Galád. I navrátilo se z lidu dvamecítma tisíců, a deset tisíc zůstalo.'),
(1552889,54,7,7,4,'Řekl opět Hospodin Gedeonovi: Ještě jest mnoho lidu; kaž jim sstoupiti k vodám, a tam jej tobě zkusím. I bude, že o komžkoli řeknu: Tento půjde s tebou, ten ať s tebou jde, a o komžkoli řeknu tobě: Tento nepůjde s tebou, ten ať nechodí.'),
(1552890,54,7,7,5,'I kázal sstoupiti lidu k vodám, a řekl Hospodin k Gedeonovi: Každého, kdož chlemtati bude jazykem svým z vody, jako chlemce pes, postavíš obzvláštně, tolikéž každého, kdož se přisehne na kolena svá ku pití.'),
(1552891,54,7,7,6,'I byl počet těch, kteříž chlemtali, rukama svýma k ústům svým vodu nosíce, tři sta mužů, ostatek pak všeho lidu sehnuli se na kolena svá ku pití vody.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552892,54,7,7,7,'I řekl Hospodin Gedeonovi: Ve třech stech mužů, kteříž chlemtali, vysvobodím vás, a vydám Madianské v ruku tvou, ale ostatek všeho lidu nechť se vrátí, jeden každý k místu svému.'),
(1552893,54,7,7,8,'A protož nabral ten lid v ruce své potravy a trouby své; jiné pak muže Izraelské všecky propustil, jednoho každého do stanů jejich, toliko tři sta těch mužů zanechal při sobě. Vojska pak Madianských ležela pod ním v údolí.'),
(1552894,54,7,7,9,'I stalo se, že noci té řekl jemu Hospodin: Vstana, sstup k vojsku, nebo dal jsem je v ruku tvou.'),
(1552895,54,7,7,10,'Pakli nesmíš sjíti sám, sejdi s Půrou služebníkem svým do vojska,'),
(1552896,54,7,7,11,'A uslyšíš, co mluviti budou; i posilní se z toho ruce tvé, tak že směle půjdeš proti vojsku tomu. Sstoupil tedy on a Půra služebník jeho k kraji oděnců, kteříž byli v vojště.'),
(1552897,54,7,7,12,'Madian pak a Amalech i všecken lid východní leželi v údolí, jako kobylky u velikém množství, ani velbloudů jejich počtu nebylo, jako písek, kterýž jest na břehu mořském v nesčíslném množství.'),
(1552898,54,7,7,13,'A když přišel Gedeon, aj, jeden vypravoval bližnímu svému sen, a řekl: Hle, zdálo mi se, že pecen chleba ječmenného valil se do vojska Madianského, a přivaliv se na každý stan, udeřil na něj, až padl, a podvrátil jej svrchu, a tak ležel každý stan.'),
(1552899,54,7,7,14,'Jemužto odpovídaje bližní jeho, řekl: Není to nic jiného, jediné meč Gedeona syna Joasova, muže Izraelského; dalť jest Bůh v ruku jeho Madianské i všecka tato vojska.'),
(1552900,54,7,7,15,'Stalo se pak, že když uslyšel Gedeon vypravování snu i vyložení jeho, poklonil se Bohu, a vrátiv se k vojsku Izraelskému, řekl: Vstaňte, nebo dal Hospodin v ruku vaši vojska Madianská.'),
(1552901,54,7,7,16,'Rozdělil tedy tři sta mužů na tři houfy, a dal trouby v ruku každému z nich a báně prázdné, a v prostředku těch bání byly pochodně.'),
(1552902,54,7,7,17,'I řekl jim: Jakž na mně uzříte, tak učiníte; nebo hle, já vejdu na kraj vojska, a jakž já tehdáž budu dělati, tak uděláte.'),
(1552903,54,7,7,18,'Nebo troubiti budu já v troubu i všickni, jenž se mnou budou, tehdy vy také troubiti budete v trouby vůkol všeho vojska, a řeknete: Meč Hospodinův a Gedeonův.'),
(1552904,54,7,7,19,'Všel tedy Gedeon a sto mužů, kteříž s ním byli, na kraj vojska při začátku bdění prostředního, jen že byli proměnili stráž; i troubili v trouby, a roztřískali báně, kteréž měli v rukou svých.'),
(1552905,54,7,7,20,'Tedy ti tři houfové troubili v trouby, rozstřískavše báně, a drželi v ruce své levé pochodně, v pravé pak ruce své trouby, aby troubili, i křičeli: Meč Hospodinův a Gedeonův.'),
(1552906,54,7,7,21,'A postavili se každý na místě svém vůkol ležení; i zděšena jsou všecka vojska, a křičíce, utíkali.'),
(1552907,54,7,7,22,'Když pak troubilo v trouby těch tři sta mužů, obrátil Hospodin meč jednoho proti druhému, a to po všem ležení. Utíkalo tedy vojsko až k Betseta do Zererat, a až ku pomezí Abelmehula u Tebat.'),
(1552908,54,7,7,23,'Shromáždivše se pak muži Izraelští z Neftalím a z Asser a ze všeho pokolení Manassesova, honili Madianské.'),
(1552909,54,7,7,24,'I rozeslal Gedeon posly na všecky hory Efraimské, řka: Vyjděte v cestu Madianským, a zastupte jim vody až k Betabaře a Jordánu. Tedy shromáždivše se všickni muži Efraim, zastoupili vody až k Betabaře a Jordánu.'),
(1552910,54,7,7,25,'A chytili dvé knížat Madianských, Goréba a Zéba. I zabili Goréba na skále Goréb a Zéba zabili v lisu Zéb, a honili Madianské, hlavu pak Gorébovu a Zébovu přinesli k Gedeonovi za Jordán.'),
(1552911,54,7,8,1,'Muži pak Efraim řekli jemu: Co jsi nám to učinil, že jsi nepovolal nás, když jsi táhl k boji proti Madianským? A tuze se na něj domlouvali.'),
(1552912,54,7,8,2,'Jimž odpověděl: Zdaž jsem co takového provedl, jako vy? Zdaliž není lepší paběrování Efraimovo, než vinobraní Abiezerovo?'),
(1552913,54,7,8,3,'V ruce vaše dal Bůh knížata Madianská Goréba a Zéba, a co jsem já mohl takového učiniti, jako vy? I spokojil se duch jejich k němu, když mluvil ta slova.'),
(1552914,54,7,8,4,'Když pak přišel Gedeon k Jordánu, přešel jej, a tři sta mužů, kteříž byli s ním, ustalí, honíce nepřátely.'),
(1552915,54,7,8,5,'Protož řekl mužům Sochot: Dejte, prosím, po pecníku chleba lidu, kterýž za mnou jde, nebo ustali, a já honím Zebaha a Salmuna, krále ty Madianské.'),
(1552916,54,7,8,6,'I řekl jemu jeden z knížat Sochot: Což již moc Zebahova a Salmunova jest v ruce tvé, abychom dali vojsku tvému chleba?'),
(1552917,54,7,8,7,'Jimž řekl Gedeon: Z té příčiny, když dá Hospodin Zebaha a Salmuna v ruku mou, tehdy zmrskám těla vaše trním a bodláčím z pouště té.'),
(1552918,54,7,8,8,'I táhl odtud do Fanuel, a podobně mluvil k nim, ale obyvatelé Fanuel odpověděli jemu tolikéž, jako muži Sochot.'),
(1552919,54,7,8,9,'I řekl obyvatelům Fanuel: Když se navrátím v pokoji, zbořím věži tuto.'),
(1552920,54,7,8,10,'Zebah pak a Salmun byli v Karkara spolu s vojsky svými, takměř patnácte tisíců, všickni, což jich bylo pozůstalo ze všeho vojska národů východních, zbitých pak bylo sto a dvadceti tisíc mužů bojovníků.'),
(1552921,54,7,8,11,'I táhna Gedeon cestou bydlících v staních od východní strany Nobe a Jegbaa, udeřil na to vojsko, kteréžto vojsko sobě počínalo bezpečně.'),
(1552922,54,7,8,12,'Když pak utíkali Zebah a Salmun, honil je, a jal oba dva ty krále Madianské, Zebaha a Salmuna, a všecko vojsko jejich předěsil.'),
(1552923,54,7,8,13,'I navracel se Gedeon syn Joasův z bitvy před východem slunce.'),
(1552924,54,7,8,14,'I jav mládence z obyvatelů Sochotských, vyptával se ho; kterýž sepsal mu knížata Sochot a starší jeho, sedmdesáte sedm mužů.'),
(1552925,54,7,8,15,'Přišed pak k obyvatelům Sochot, řekl: Aj, Zebah a Salmun, pro něž jste mi utrhali, řkouce: Zdali moc Zebaha a Salmuna jest v ruce tvé, abychom dali ustalým mužům tvým chleba?'),
(1552926,54,7,8,16,'Protož vzav starší města a trní s bodláčím z pouště té, dal na nich příklad jiným mužům Sochot.'),
(1552927,54,7,8,17,'I věži Fanuel rozbořil, a pobil muže města.'),
(1552928,54,7,8,18,'Potom řekl Zebahovi a Salmunovi: Jací to byli muži, kteréž jste pobili na hoře Tábor? Odpověděli oni: Takoví jako ty, jeden každý na pohledění byl jako syn královský.'),
(1552929,54,7,8,19,'I dí: Bratří moji, synové matky mé byli. Živť jest Hospodin, byste byli živili je, nepobil bych vás.'),
(1552930,54,7,8,20,'Tedy řekl k Jeter prvorozenému svému: Vstaň, pobí je. Ale mládenček nevytáhl meče svého, proto že se bál, nebo byl ještě mládenček.'),
(1552931,54,7,8,21,'I řekl Zebah a Salmun: Vstaň ty a oboř se na nás, nebo jaký jest muž, taková i síla jeho. Vstav tedy Gedeon, zabil Zebaha a Salmuna, a vzal halže, kteréž byly na hrdlech velbloudů jejich.'),
(1552932,54,7,8,22,'Potom řekli muži Izraelští Gedeonovi: Panuj nad námi i ty i syn tvůj, také syn syna tvého, nebo vysvobodil jsi nás z ruky Madianských.'),
(1552933,54,7,8,23,'I odpověděl jim Gedeon: Nebuduť já panovati nad vámi, aniž panovati bude nad vámi syn můj, Hospodin panovati bude nad vámi.'),
(1552934,54,7,8,24,'Řekl jim také Gedeon: Žádost tuto vzložím toliko na vás, abyste mi dali jeden každý náušnici z loupeží svých; (nebo náušnice zlaté měli, proto že Izmaelitští byli.)'),
(1552935,54,7,8,25,'I odpověděli: Rádi dáme. A prostřevše roucho, metali na ně každý náušnici z loupeží svých.'),
(1552936,54,7,8,26,'Byla pak váha náušnic zlatých, kteréž vyžádal, tisíc a sedm set lotů zlata, kromě halží a zlatých jableček, i roucha šarlatového, kteréž na sobě měli králové Madianští, a kromě halží, kteréž byly na hrdlech velbloudů jejich.'),
(1552937,54,7,8,27,'I udělal z toho Gedeon efod, a složil jej v městě svém Ofra. I smilnil tam všecken Izrael, chodě za ním, a byl Gedeonovi i domu jeho osídlem.'),
(1552938,54,7,8,28,'Madianští pak sníženi jsou před syny Izraelskými, aniž potom pozdvihli hlavy své; a tak byla v pokoji země za čtyřidceti let ve dnech Gedeonových.'),
(1552939,54,7,8,29,'A odšed Jerobál syn Joasův, přebýval v domě svém.'),
(1552940,54,7,8,30,'Měl pak Gedeon sedmdesáte synů, kteříž pošli z bedr jeho; nebo měl žen mnoho.'),
(1552941,54,7,8,31,'Ženina také jeho, kterouž měl v Sichem, i ta porodila jemu syna, a dala mu jméno Abimelech.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552942,54,7,8,32,'A když umřel Gedeon syn Joasův v starosti dobré, pochován jest v hrobě Joasa otce svého v Ofra Abiezeritského.'),
(1552943,54,7,8,33,'Stalo se pak po smrti Gedeonově, že se odvrátili synové Izraelští a smilnili, jdouce za modlami, a vzali sobě Bále Berit za boha.'),
(1552944,54,7,8,34,'A nerozpomenuli se synové Izraelští na Hospodina Boha svého, kterýž je vytrhl z ruky všech nepřátel jejich vůkol.'),
(1552945,54,7,8,35,'A neučinili milosrdenství s domem Jerobále Gedeona, jako on všecko dobré činil Izraelovi.'),
(1552946,54,7,9,1,'Nebo odšed Abimelech syn Jerobálův do Sichem k bratřím matky své, mluvil k nim i ke vší čeledi domu otce matky své, řka:'),
(1552947,54,7,9,2,'Mluvte, prosím, ke všechněm mužům Sichemským: Co jest lépe vám, to-li, aby panovalo nad vámi sedmdesáte mužů, totiž všickni synové Jerobálovi, čili aby panoval nad vámi muž jeden? Pamatujte pak, že jsem já kost vaše a tělo vaše.'),
(1552948,54,7,9,3,'Tedy mluvili bratří matky jeho o něm ke všechněm mužům Sichemským všecka slova tato, a naklonilo se srdce jejich k Abimelechovi, nebo řekli: Bratr náš jest.'),
(1552949,54,7,9,4,'I dali jemu sedmdesáte lotů stříbra z domu Bále Berit, na něž sobě najal Abimelech služebníky, povaleče a tuláky, aby chodili za ním.'),
(1552950,54,7,9,5,'A přišed do domu otce svého do Ofra, zmordoval bratří své, syny Jerobálovy, sedmdesáte mužů, na jednom kameni; toliko zůstal Jotam syn Jerobálův nejmladší, nebo se byl skryl.'),
(1552951,54,7,9,6,'Tedy shromáždili se všickni muži Sichemští i všecken dům Mello, i šli, a ustanovili sobě Abimelecha za krále na rovinách u sloupu, kterýž jest u Sichem.'),
(1552952,54,7,9,7,'To když pověděli Jotamovi, odejda, postavil se na vrchu hory Garizim, a pozdvihna hlasu svého, volal, a řekl jim: Poslyšte mne muži Sichemští, a uslyš vás Bůh.'),
(1552953,54,7,9,8,'Sešlo se některého času dříví, aby pomazalo nad sebou krále. I řekli olivě: Kraluj nad námi.'),
(1552954,54,7,9,9,'Jimžto odpověděla oliva: Zdali já, opustě svou tučnost, kterouž ctěn bývá Bůh i lidé, půjdu, abych byla postavena nad stromy?'),
(1552955,54,7,9,10,'I řeklo dříví fíku: Poď ty a kraluj nad námi.'),
(1552956,54,7,9,11,'Jimž odpověděl fík: Zdali já, opustě sladkost svou a ovoce své výborné, půjdu, abych postaven byl nad stromy?'),
(1552957,54,7,9,12,'Řeklo opět dříví vinnému kořenu: Poď ty a kraluj nad námi.'),
(1552958,54,7,9,13,'Jimž odpověděl vinný kořen: Zdali já, opustě své víno, kteréž obveseluje Boha i lidi, půjdu, abych postaven byl nad stromy?'),
(1552959,54,7,9,14,'Naposledy řeklo všecko dříví bodláku: Poď ale ty a kraluj nad námi.'),
(1552960,54,7,9,15,'I odpověděl bodlák dříví: Jestliže v pravdě béřete vy mne sobě za krále, poďte, odpočívejte pod stínem mým; pakli nic, vyjdi oheň z bodláku a spal cedry Libánské.'),
(1552961,54,7,9,16,'Tak i nyní, jestliže jste právě a upřímě učinili, ustavivše Abimelecha za krále, a jestliže jste dobře učinili Jerobálovi a domu jeho, a jestliže podlé dobrodiní rukou jeho odplatili jste se jemu;'),
(1552962,54,7,9,17,'(Nebo otec můj bojoval za vás a opovážil se života svého, aby vás vysvobodil z ruky Madianských,'),
(1552963,54,7,9,18,'Vy pak teď povstali jste proti domu otce mého, a zmordovali jste syny jeho, sedmdesáte mužů na jednom kameni, a ustanovili jste krále Abimelecha, syna děvky jeho, nad muži Sichemskými, proto že bratr váš jest);'),
(1552964,54,7,9,19,'Jestliže, řku, právě a upřímě udělali jste Jerobálovi i domu jeho dne tohoto, veselte se z Abimelecha, a on také nechť se veselí z vás;'),
(1552965,54,7,9,20,'Pakli nic, nechť vyjde oheň z Abimelecha a sžíře muže Sichemské i dům Mello, nechť vyjde také oheň od mužů Sichemských a z domu Mello a sžíře Abimelecha.'),
(1552966,54,7,9,21,'Tedy utekl Jotam, a utíkaje, odšel do Beera, a zůstal tam, boje se Abimelecha bratra svého.'),
(1552967,54,7,9,22,'I panoval Abimelech nad Izraelem tři léta.'),
(1552968,54,7,9,23,'Poslal pak Bůh ducha zlého mezi Abimelecha a mezi muže Sichemské, a zpronevěřili se muži Sichemští Abimelechovi,'),
(1552969,54,7,9,24,'Aby pomštěna byla křivda sedmdesáti synů Jerobálových, a aby krev jejich přišla na Abimelecha bratra jejich, kterýž zmordoval je, a na muže Sichemské, kteříž posilnili rukou jeho, aby zmordoval bratří své.'),
(1552970,54,7,9,25,'Nebo učinili muži Sichemští jemu zálohy na vrších hor, a loupili všecky chodíci mimo ně tou cestou; kterážto věc povědína jest Abimelechovi.'),
(1552971,54,7,9,26,'Syn pak Ebedův Gál, jda s bratřími svými, přišel do Sichem, i těšili se z něho muži Sichemští.'),
(1552972,54,7,9,27,'A vyšedše na pole, sbírali víno své a tlačili i veselili se; a všedše do chrámu bohů svých, jedli a pili, a zlořečili Abimelechovi.'),
(1552973,54,7,9,28,'Řekl pak Gál syn Ebedův: Kdo jest Abimelech? A jaké jest Sichem, abychom sloužili jemu? Zdaliž není syn Jerobálův, a Zebul úředník jeho? Služte raději mužům Emora, otce Sichemova; nebo proč my máme sloužiti tomuto?'),
(1552974,54,7,9,29,'Ale ó kdyby tento lid byl v ruce mé, abych shladil Abimelecha! I řekl Abimelechovi: Sbeř sobě vojsko, a vyjdi.'),
(1552975,54,7,9,30,'Uslyšav pak Zebul, úředník města toho, slova Gále syna Ebedova, rozhněval se náramně.'),
(1552976,54,7,9,31,'I poslal posly k Abimelechovi tajně, řka: Hle, Gál syn Ebedův i bratří jeho přišli do Sichem, a hle, bojovati budou s městem proti tobě.'),
(1552977,54,7,9,32,'Protož nyní vstana nočně, ty i lid, kterýž jest s tebou, zdělej zálohy v poli.'),
(1552978,54,7,9,33,'A ráno, když bude slunce vycházeti, vstana, udeříš na město, a když on i lid, kterýž jest s ním, vyjde proti tobě, učiníš jemu to, což se naskytne ruce tvé.'),
(1552979,54,7,9,34,'A protož vstal Abimelech i všecken lid, kterýž s ním byl v noci, a učinili zálohy u Sichem na čtyřech místech.'),
(1552980,54,7,9,35,'I vyšel Gál syn Ebedův, a postavil se v bráně města; vyvstal pak Abimelech i lid, kterýž s ním byl, z záloh.'),
(1552981,54,7,9,36,'A uzřev Gál ten lid, řekl Zebulovi: Hle, lid sstupuje s vrchu hor. Jemuž odpověděl Zebul: Stín hor vidíš, jako nějaké lidi.'),
(1552982,54,7,9,37,'Tedy opět promluvil Gál, řka:Hle, lid sstupuje s vrchu, nebo houf jeden táhne cestou rovin Monenim.'),
(1552983,54,7,9,38,'Řekl pak jemu Zebul: Kde jsou nyní ústa tvá, jimižs mluvil: Kdo jest Abimelech, abychom sloužili jemu? Zdaliž toto není lid ten, kterýmž jsi pohrdal? Vytáhniž nyní, a bojuj proti němu.'),
(1552984,54,7,9,39,'I vytáhl Gál před lidmi Sichemskými, a bojoval proti Abimelechovi.'),
(1552985,54,7,9,40,'Ale Abimelech honil ho utíkajícího před tváří svou, a padlo raněných mnoho až k bráně.'),
(1552986,54,7,9,41,'Zůstal pak Abimelech v Aruma, a Zebul vyhnal Gále i bratří jeho, aby nezůstávali v Sichem.'),
(1552987,54,7,9,42,'Nazejtří pak vytáhl lid do pole, i oznámeno jest to Abimelechovi.'),
(1552988,54,7,9,43,'Tedy on pojal lid svůj, a rozdělil jej na tři houfy, zdělav zálohy v polích, a vida, an lid vychází z města, vyskočil na ně a zbil je.'),
(1552989,54,7,9,44,'Nebo Abimelech a houf, kterýž byl s ním, udeřili na ně a postavili se u brány města, druzí pak dva houfové obořili se na všecky ty, kteříž byli v poli, a zbili je.'),
(1552990,54,7,9,45,'Abimelech pak dobýval města celý ten den, až ho i dobyl, a lid, kterýž v něm byl, pobil, a zbořiv město, posál je solí.'),
(1552991,54,7,9,46,'Uslyševše pak všickni muži věže Sichemské, vešli do hradu svého, chrámu boha Berit.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1552992,54,7,9,47,'A oznámeno jest Abimelechovi, že se tam shromáždili všickni muži věže Sichemské.'),
(1552993,54,7,9,48,'Tedy vstoupil Abimelech na horu Salmon, on i všecken lid, kterýž byl s ním, a nabrav seker s sebou, nasekal ratolestí s stromů, kterýchž nabral a vložil na rameno své. I řekl lidu, kterýž byl s ním: Což jste viděli, že jsem učinil, spěšně učiňte tak jako já.'),
(1552994,54,7,9,49,'I uťal sobě jeden každý ze všeho lidu ratolest, a jdouce za Abimelechem, skladli je u hradu, a zapálili jimi hrad. I zemřeli tam všickni muži věže Sichemské téměř tisíc mužů a žen.'),
(1552995,54,7,9,50,'Odšel pak Abimelech do Tébes, a položil se u Tébes, i dobyl ho.'),
(1552996,54,7,9,51,'Byla pak věže pevná u prostřed města, a utekli tam všickni muži i ženy, i všickni přední města toho, a zavřeli po sobě, vstoupivše na vrch věže.'),
(1552997,54,7,9,52,'Tehdy přišed Abimelech až k věži, dobýval jí, a přistoupil až ke dveřím věže, aby je zapálil ohněm.'),
(1552998,54,7,9,53,'V tom žena nějaká svrhla kus žernovu na hlavu Abimelechovu, a prorazila hlavu jeho.'),
(1552999,54,7,9,54,'A on rychle zavolav mládence, kterýž nosil zbroj jeho, řekl jemu: Vytrhni meč svůj a zabí mne, aby potom nepravili o mně: Žena zabila ho. I probodl jej služebník jeho, a umřel.'),
(1553000,54,7,9,55,'Uzřevše pak synové Izraelští, že by umřel Abimelech, odešli jeden každý k místu svému.'),
(1553001,54,7,9,56,'A tak odměnil Bůh zlým Abimelechovi za nešlechetnost, kterouž páchal proti otci svému, zmordovav sedmdesáte bratří svých.'),
(1553002,54,7,9,57,'Tolikéž i všecku nešlechetnost mužů Sichemských vrátil Bůh na hlavu jejich, a přišlo na ně zlořečení Jotama syna Jerobálova.'),
(1553003,54,7,10,1,'Povstal pak po Abimelechovi k obhajování Izraele Tola, syn Fua, syna Dodova, muž z pokolení Izachar, a ten bydlil v Samir na hoře Efraim.'),
(1553004,54,7,10,2,'I soudil Izraele za třimecítma let, a umřev, pochován jest v Samir.'),
(1553005,54,7,10,3,'Po něm povstal Jair Galádský, a soudil Izraele za dvamecítma let.'),
(1553006,54,7,10,4,'A měl třidceti synů, kteříž jezdili na třidcíti mezcích; a měli třidceti měst, kteráž sloula vsi Jairovy až do dnešního dne, a ty jsou v zemi Galád.'),
(1553007,54,7,10,5,'I umřel Jair, a pochován jest v Kamon.'),
(1553008,54,7,10,6,'Opět pak synové Izraelští činili to, což jest zlého před očima Hospodinovýma; nebo sloužili Bálům a Astarot, to jest, bohům Syrským, bohům Sidonským a bohům Moábským, tolikéž i bohům synů Ammon, i bohům Filistinským, tak že opustili Hospodina, a nesloužili jemu.'),
(1553009,54,7,10,7,'Protož roznítila se prchlivost Hospodinova na Izraele, a vydal je v ruku Filistinských a v ruku Ammonitských,'),
(1553010,54,7,10,8,'Kteříž stírali a potlačovali syny Izraelské toho roku, i potom za osmnácte let, všecky syny Izraelské, kteříž byli před Jordánem v zemi Amorejského, kteráž jest v Galád.'),
(1553011,54,7,10,9,'Přešli pak Ammonitští i Jordán, aby bojovali také proti Judovi, a proti Beniaminovi, i proti domu Efraimovu; i byl Izrael náramně ssoužen.'),
(1553012,54,7,10,10,'Tedy volali synové Izraelští k Hospodinu, řkouce: Zhřešiliť jsme tobě, tak že jsme opustili tě Boha svého, a sloužili jsme Bálům.'),
(1553013,54,7,10,11,'Ale Hospodin řekl synům Izraelským: Zdaliž jsem od Egyptských a od Amorejských a od Ammonitských a Filistinských,'),
(1553014,54,7,10,12,'Tolikéž od Sidonských, a Amalechitských, i od Maonitských, vás ssužujících, když jste volali ke mně, nevysvobodil vás z ruky jejich?'),
(1553015,54,7,10,13,'A vy opustili jste mne a sloužili jste bohům cizím, protož nevysvobodím vás více.'),
(1553016,54,7,10,14,'Jděte a volejte k bohům, kteréž jste sobě zvolili; oni nechť vás vysvobodí v čas ssoužení vašeho.'),
(1553017,54,7,10,15,'I řekli synové Izraelští Hospodinu: Zhřešili jsme; učiň s námi, cožť se dobře líbí, a však vysvoboď nás, prosíme, v tento čas.'),
(1553018,54,7,10,16,'Protož vyvrhše bohy cizí z prostředku svého, sloužili Hospodinu, a zželelo se duši jeho nad trápením Izraele.'),
(1553019,54,7,10,17,'Svolali se pak Ammonitští, a položili se v Galád; shromáždili se také synové Izraelští, a položili se v Masfa.'),
(1553020,54,7,10,18,'I řekli lid s knížaty Galád jedni druhým: Kdokoli počne bojovati proti Ammonitským, bude vůdce všech obyvatelů Galád.'),
(1553021,54,7,11,1,'Jefte pak Galádský byl muž udatný a byl syn ženy nevěstky, z níž zplodil Galád řečeného Jefte.'),
(1553022,54,7,11,2,'Ale i manželka Galádova naplodila mu synů, a když dorostli synové manželky té, vyhnali Jefte. Nebo řekli jemu: Nebudeš děditi v domě otce našeho, nebo jsi postranní ženy syn.'),
(1553023,54,7,11,3,'Protož utekl Jefte od tváři bratří svých, a bydlil v zemi Tob; a sběhli se k Jefte lidé povaleči, a vycházeli s ním.'),
(1553024,54,7,11,4,'Stalo se pak po těch dnech, že bojovali Ammonitští proti Izraelským.'),
(1553025,54,7,11,5,'A když počali bojovati Ammonitští proti nim, odešli starší Galádští, aby zase přivedli Jefte z země Tob.'),
(1553026,54,7,11,6,'I řekli k Jefte: Poď a buď vůdce náš, abychom bojovali proti Ammonitským.'),
(1553027,54,7,11,7,'Odpověděl Jefte starším Galádským: Zdaliž jste vy mne neměli v nenávisti, a nevyhnali jste mne z domu otce mého? Pročež tedy nyní přišli jste ke mně, když ssouženi jste?'),
(1553028,54,7,11,8,'I řekli starší Galádští k Jefte: Proto jsme se nyní navrátili k tobě, abys šel s námi a bojoval proti Ammonitským, a byl nám všechněm obyvatelům Galádským za vůdce.'),
(1553029,54,7,11,9,'Tedy odpověděl Jefte starším Galádským: Poněvadž mne zase uvodíte, abych bojoval proti Ammonitským, když by mi je dal Hospodin v moc, budu-li vám za vůdce?'),
(1553030,54,7,11,10,'I řekli starší Galádští k Jefte: Hospodin bude svědkem mezi námi, jestliže neučiníme vedlé slova tvého.'),
(1553031,54,7,11,11,'A tak šel Jefte s staršími Galádskými, a představil jej sobě lid za vůdci a kníže, a mluvil Jefte všecka slova svá před Hospodinem v Masfa.'),
(1553032,54,7,11,12,'Potom poslal Jefte posly k králi Ammonitskému s tímto poručením: Co máš ke mně, že jsi vytáhl na mne, abys bojoval proti zemi mé?'),
(1553033,54,7,11,13,'I odpověděl král Ammonitský poslům Jefte: Že vzal Izrael zemi mou, když vyšel z Egypta, od Arnon až k Jaboku a až k Jordánu; protož nyní vrať mi ji pokojně.'),
(1553034,54,7,11,14,'Opět pak poslal Jefte posly k králi Ammonitskému,'),
(1553035,54,7,11,15,'A řekl jemu: Takto praví Jefte: Nevzalť Izrael země Moábské, ani země synů Ammonových.'),
(1553036,54,7,11,16,'Ale když vyšli z Egypta, šel Izrael přes poušť až k moři Rudému, a přišel do Kádes.'),
(1553037,54,7,11,17,'Odkudž poslal Izrael posly k králi Edomskému, řka: Prosím, nechť projdu skrze zemi tvou. A nechtěl ho slyšeti král Edomský. Poslal také k králi Moábskému, a nechtěl povoliti. A tak zůstal Izrael v Kádes.'),
(1553038,54,7,11,18,'Potom když šel přes poušť, obcházel zemi Edomskou a zemi Moábskou, a přišed od východu slunce zemi Moábské, položil se před Arnon, a nevešli na pomezí Moábské; nebo Arnon jest meze Moábských.'),
(1553039,54,7,11,19,'Protož poslal Izrael posly k Seonovi králi Amorejskému, to jest, k králi Ezebon, a řekl jemu Izrael: Prosím, nechť projdu skrze zemi tvou až k místu svému.'),
(1553040,54,7,11,20,'Ale Seon nedověřoval Izraelovi, aby přejíti měl pomezí jeho. Protož shromáždil Seon všecken lid svůj, a položili se v Jasa, a bojoval proti Izraelovi.'),
(1553041,54,7,11,21,'I dal Hospodin Bůh Izraelský Seona i všecken lid jeho v ruku Izraelských, a porazili je. I opanoval dědičně Izrael všecku zemi Amorejského, té země obyvatele.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553042,54,7,11,22,'A tak opanovali všecko pomezí Amorejského od Arnon až k Jaboku a od pouště až k Jordánu.'),
(1553043,54,7,11,23,'Když tedy Hospodin Bůh Izraelský vyhladil Amorejského od tváři lidu svého Izraelského, proč ty chceš panovati nad ním?'),
(1553044,54,7,11,24,'Zdaliž tím, což tobě dal Chámos bůh tvůj k vládařství, vládnouti nemáš? Takž, kterékoli vyhladil Hospodin Bůh náš od tváři naší, jejich dědictvím my vládneme.'),
(1553045,54,7,11,25,'K tomu pak, zdali jsi ty čím lepší Baláka syna Seforova, krále Moábského? Zdali se kdy vadil s Izraelem? Zdali kdy bojoval proti nim?'),
(1553046,54,7,11,26,'Ješto již bydlí Izrael v Ezebon a ve vsech jeho, i v Aroer, a ve vsech jeho, i ve všech městech, kteráž jsou při pomezí Arnon, za tři sta let. Proč jste jí neodjali v tak dlouhém času?'),
(1553047,54,7,11,27,'Protož ne já provinil jsem proti tobě, ale ty mně zle činíš, bojuje proti mně. Nechť soudí Hospodin soudce dnes mezi syny Izraelskými a mezi syny Ammonovými.'),
(1553048,54,7,11,28,'Král pak Ammonitský neuposlechl slov Jefte, kteráž vzkázal jemu.'),
(1553049,54,7,11,29,'V tom nadšen byl Jefte duchem Hospodinovým, i táhl skrze Galád a Manasse, prošel i Masfa v Galád, a z Masfy v Galád táhl proti Ammonitským.'),
(1553050,54,7,11,30,'(Učinil pak Jefte slib Hospodinu, a řekl: Jestliže jistotně dáš mi Ammonitské v ruku mou:'),
(1553051,54,7,11,31,'I stane se, že což by koli vyšlo ze dveří domu mého mně vstříc, když se vrátím v pokoji od Ammonitských, bude Hospodinovo, abych to obětoval v obět zápalnou.)'),
(1553052,54,7,11,32,'Přitáhl tedy Jefte na Ammonitské, aby bojoval proti nim, a dal je Hospodin v ruku jeho.'),
(1553053,54,7,11,33,'I pobil je od Aroer, až kudy se jde do Mennit, dvadceti měst, a až do Abel vinic porážkou velikou velmi; a sníženi jsou Ammonitští před syny Izraelskými.'),
(1553054,54,7,11,34,'Když se pak navracoval Jefte do Masfa k domu svému, aj, dcera jeho vyšla jemu vstříc s bubny a s houfem plésajících; kterouž měl toliko jedinou, aniž měl kterého syna aneb jiné dcery.'),
(1553055,54,7,11,35,'Stalo se pak, že když uzřel ji, roztrhl roucha svá a řekl: Ach, dcero má, velices mne ponížila; nebo jsi z těch, jenž mne kormoutí, poněvadž jsem tak řekl Hospodinu, aniž budu moci odvolati toho.'),
(1553056,54,7,11,36,'Jemuž ona odpověděla: Můj otče, jestliže jsi tak řekl Hospodinu, učiň mi podlé toho, jakžs mluvil; kdyžť jen dal Hospodin pomstu nad nepřátely tvými, Ammonitskými.'),
(1553057,54,7,11,37,'Řekla také otci svému: Nechť toliko toto obdržím: Odpusť mne na dva měsíce, ať jdu a vejdu na hory a opláči panenství svého, já i družičky mé.'),
(1553058,54,7,11,38,'Kterýž řekl: Jdi. I propustil ji na dva měsíce. Odešla tedy ona i družičky její, a plakala panenství svého na horách.'),
(1553059,54,7,11,39,'A při dokonání dvou měsíců navrátila se k otci svému, a vykonal při ní slib svůj, kterýž byl učinil. Ona pak nepoznala muže. I byl ten obyčej v Izraeli,'),
(1553060,54,7,11,40,'Že každého roku scházívaly se dcery Izraelské, aby plakaly nad dcerou Jefte Galádského za čtyři dni v roce.'),
(1553061,54,7,12,1,'Shromáždili se pak muži Efraim, a přešedše k straně půlnoční, řekli k Jefte: Proč jsi vyšel k boji proti Ammonitským, a nepovolal jsi nás, abychom šli s tebou? Dům tvůj i tebe ohněm spálíme.'),
(1553062,54,7,12,2,'K nimž řekl Jefte: Nesnáz jsem měl já a lid můj s Ammonitskými velikou; tedy povolal jsem vás, ale nevysvobodili jste mne z ruky jejich.'),
(1553063,54,7,12,3,'Protož vida, že jste mne nevysvobodili, odvážil jsem se života svého, a táhl jsem proti Ammonitským, i dal je Hospodin v ruku mou. Ale proč jste dnes přišli ke mně? Zdali abyste bojovali proti mně?'),
(1553064,54,7,12,4,'Tedy shromáždil Jefte všecky muže Galádské, a bojoval s Efraimem. I porazili muži Galád Efraimské, nebo pravili poběhlci Efraimští: Vy Galádští jste u prostřed Efraima a u prostřed Manassesa.'),
(1553065,54,7,12,5,'Odjali Galádští též i brody Jordánské Efraimským. A bylo, že když kdo z utíkajících Efraimských řekl: Nechať přejdu, řekli jemu muži Galádští: Jsi-li Efratejský? Jestliže řekl: Nejsem,'),
(1553066,54,7,12,6,'Tedy řekli jemu: Rci hned Šibolet. I řekl: Sibolet, aniž dobře mohl vyřknouti toho. Tedy pochytíce jej, zamordovali ho u brodu Jordánského. I padlo toho času z Efraima čtyřidceti a dva tisíce.'),
(1553067,54,7,12,7,'Soudil pak Jefte Izraele šest let; a umřel Jefte Galádský, a pochován jest v jednom z měst Galádských.'),
(1553068,54,7,12,8,'Potom soudil po něm Izraele Abesam z Betléma.'),
(1553069,54,7,12,9,'A měl třidceti synů a třidceti dcer, kteréž rozevdal od sebe, a třidceti žen přivedl od jinud synům svým. I soudil Izraele sedm let.'),
(1553070,54,7,12,10,'A umřev Abesam, pochován jest v Betlémě.'),
(1553071,54,7,12,11,'Po něm pak soudil Izraele Elon Zabulonský; ten soudil Izraele deset let.'),
(1553072,54,7,12,12,'I umřel Elon Zabulonský, a pochován jest v Aialon, v zemi Zabulon.'),
(1553073,54,7,12,13,'Potom soudil Izraele Abdon syn Hellelův Faratonský.'),
(1553074,54,7,12,14,'Ten měl čtyřidceti synů a třidceti vnuků, kteříž jezdili na sedmdesáti mezcích; i soudil Izraele osm let.'),
(1553075,54,7,12,15,'Umřev pak Abdon syn Hellelův Faratonský, pohřben jest v Faraton, v zemi Efraim na hoře Amalechitské.'),
(1553076,54,7,13,1,'Tedy opět synové Izraelští činili to, což jest zlého před očima Hospodinovýma, i vydal je Hospodin v ruce Filistinských za čtyřidceti let.'),
(1553077,54,7,13,2,'Byl pak muž jeden z Zaraha, z čeledi Dan, jménem Manue, jehož manželka byla neplodná a nerodila.'),
(1553078,54,7,13,3,'I ukázal se anděl Hospodinův ženě té a řekl jí: Aj, nyní jsi neplodná, aniž jsi rodila; počneš pak a porodíš syna.'),
(1553079,54,7,13,4,'Protož nyní vystříhej se, abys vína nepila aneb nápoje opojného, a abys nejedla nic nečistého.'),
(1553080,54,7,13,5,'Nebo aj, počneš a porodíš syna, a břitva ať nevchází na hlavu jeho, nebo bude to dítě od života Nazarejský Boží, a tenť počne vysvobozovati Izraele z ruky Filistinských.'),
(1553081,54,7,13,6,'I přišla žena a pověděla to muži svému, řkuci: Muž Boží přišel ke mně, jehož oblíčej byl jako oblíčej anděla Božího, hrozný velmi, a neotázala jsem se jeho, odkud by byl, ani mi svého jména neoznámil.'),
(1553082,54,7,13,7,'Ale řekl mi: Aj, počneš a porodíš syna, protož nyní nepí vína aneb nápoje opojného, aniž jez co nečistého, nebo to dítě od života bude Nazarejský Boží až do dne smrti své.'),
(1553083,54,7,13,8,'Tedy Manue modlil se Hospodinu a řekl: Vyslyš mne, můj Pane, prosím, nechť muž Boží, kteréhož jsi byl poslal, zase přijde k nám, a naučí nás, co máme dělati s dítětem, kteréž se má naroditi.'),
(1553084,54,7,13,9,'I vyslyšel Bůh hlas Manue; nebo přišel anděl Boží opět k ženě té, když seděla na poli. Manue pak muž její nebyl s ní.'),
(1553085,54,7,13,10,'A protož s chvátáním běžela žena ta, a oznámila muži svému, řkuci jemu: Hle, ukázal se mi muž ten, kterýž byl ke mně prvé přišel.'),
(1553086,54,7,13,11,'Vstav pak Manue, šel za manželkou svou, a přišed k muži tomu, řekl jemu: Ty-li jsi ten muž, kterýž jsi mluvil k manželce mé? Odpověděl: Jsem.'),
(1553087,54,7,13,12,'I řekl Manue: Nechť se nyní stane slovo tvé, ale jaká péče o to dítě a správa při něm býti má?'),
(1553088,54,7,13,13,'Odpověděl anděl Hospodinův Manue: Ode všeho toho, o čemž jsem oznámil ženě, ať se ona vystříhá.'),
(1553089,54,7,13,14,'Ničeho, což pochází z vinného kmene, ať neužívá, to jest, vína aneb nápoje opojného ať nepije, a nic nečistého ať nejí; cožkoli jsem jí přikázal, ať ostříhá.'),
(1553090,54,7,13,15,'Tedy řekl Manue andělu Hospodinovu: Medle, nechť tě pozdržíme, a připravímeť kozlíka.'),
(1553091,54,7,13,16,'I odpověděl anděl Hospodinův Manue: Bys mne i pozdržel, nebuduť jísti pokrmu tvého, ale jestliže připravíš obět zápalnou, Hospodinu ji obětuj. Nebo nevěděl Manue, že byl anděl Hospodinův.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553092,54,7,13,17,'Řekl opět Manue andělu Hospodinovu: Jaké jest jméno tvé, abychom, když se naplní řeč tvá, poctili tebe?'),
(1553093,54,7,13,18,'Jemuž odpověděl anděl Hospodinův: Proč se ptáš na jméno mé, kteréž jest divné?'),
(1553094,54,7,13,19,'Vzav tedy Manue kozlíka a obět suchou, obětoval to na skále Hospodinu, a on divnou věc učinil, an na to hledí Manue a manželka jeho.'),
(1553095,54,7,13,20,'Nebo když vstupoval plamen s oltáře k nebi, vznesl se anděl Hospodinův v plameni s oltáře, Manue pak a manželka jeho vidouce to, padli na tvář svou na zemi.'),
(1553096,54,7,13,21,'A již se více neukázal anděl Hospodinův Manue ani manželce jeho. Tedy porozuměl Manue, že byl anděl Hospodinův.'),
(1553097,54,7,13,22,'I řekl Manue manželce své: Jistě my zemřeme, nebo jsme Boha viděli.'),
(1553098,54,7,13,23,'Jemuž odpověděla manželka jeho: Kdyby nás chtěl Hospodin usmrtiti, nebyl by přijal z rukou našich oběti zápalné a suché, aniž by nám byl ukázal čeho toho, aniž by na tento čas byl nám ohlásil věcí takových.'),
(1553099,54,7,13,24,'A tak žena ta porodila syna a nazvala jméno jeho Samson. I rostlo dítě, a žehnal jemu Hospodin.'),
(1553100,54,7,13,25,'I počal ho Duch Hospodinův ponoukati v Mahane Dan, mezi Zaraha a Estaol.'),
(1553101,54,7,14,1,'Šel pak Samson do Tamnata, a uzřel tam ženu ze dcer Filistinských.'),
(1553102,54,7,14,2,'A navrátiv se, oznámil otci svému a mateři své, řka: Viděl jsem ženu v Tamnata ze dcer Filistinských, protož nyní vezměte mi ji za manželku.'),
(1553103,54,7,14,3,'I řekl mu otec jeho a matka jeho: Zdali není mezi dcerami bratří tvých a ve všem lidu mém ženy, že sobě vzíti chceš manželku z Filistinských neobřezaných? Odpověděl Samson otci svému: Tuto vezměte mi, nebť mi se líbí.'),
(1553104,54,7,14,4,'Otec pak jeho a matka jeho nevěděli, by to od Hospodina bylo, a že příčiny hledá od Filistinských; nebo toho času panovali Filistinští nad Izraelem.'),
(1553105,54,7,14,5,'Tedy šel Samson a otec jeho i matka jeho do Tamnata. Když pak přišli k vinicím Tamnatským, a aj, lev mladý řvoucí potkal se s ním.'),
(1553106,54,7,14,6,'I sstoupil na něj Duch Hospodinův, a roztrhl lva, jako by roztrhl kozelce, ačkoli nic neměl v rukou svých. A neoznámil otci ani mateři své, co učinil.'),
(1553107,54,7,14,7,'Přišed tedy, mluvil s ženou tou, a líbila se Samsonovi.'),
(1553108,54,7,14,8,'Navracuje se pak po několika dnech, aby ji pojal, uchýlil se, aby pohleděl na mrtvého lva, a aj, v těle jeho byl roj včel a med.'),
(1553109,54,7,14,9,'A vybrav jej na ruce své, šel cestou a jedl; a přišed k otci svému a mateři své, dal jim, i jedli. Ale nepověděl jim, že z mrtvého lva vyňal ten med.'),
(1553110,54,7,14,10,'Tedy šel otec jeho k ženě té, a učinil tam Samson hody, nebo tak činívali mládenci.'),
(1553111,54,7,14,11,'Když pak jej viděli tam, vybrali z sebe třidceti tovaryšů, aby byli při něm.'),
(1553112,54,7,14,12,'I řekl jim Samson: Vydám vám pohádku, kterouž jestliže mi právě vysvětlíte za sedm dní těchto hodů a uhodnete, dám vám třidceti čechlů a třidcatero roucho proměnné.'),
(1553113,54,7,14,13,'Jestliže mi pak nebudete moci uhodnouti, dáte vy mně třidceti čechlů a třidcatero roucho proměnné. Kteříž odpověděli jemu: Vydej pohádku svou, ať ji slyšíme.'),
(1553114,54,7,14,14,'I řekl jim: Z zžírajícího vyšel pokrm, a z silného vyšla sladkost. I nemohli uhodnouti pohádky té za tři dni.'),
(1553115,54,7,14,15,'Stalo se pak dne sedmého, (nebo byli řekli ženě Samsonově: Namluv muže svého, ať nám vyloží tu pohádku, ať nespálíme tě i domu otce tvého ohněm. Proto-liž, abyste našeho statku dostali, pozvali jste nás? Či co?'),
(1553116,54,7,14,16,'I plakala žena Samsonova na něj, řkuci: Jistě nenávidíš mne a nemiluješ mne; pohádku jsi vydal synům lidu mého, a mně jí nechceš povědíti. Kterýž řekl jí: Hle, otci mému a mateři neoznámil jsem, a tobě mám povědíti?'),
(1553117,54,7,14,17,'I plakala na něj do sedmého dne,v nichž měli hody). Dne tedy sedmého pověděl jí, nebo trápila jej; kterážto oznámila pohádku synům lidu svého.'),
(1553118,54,7,14,18,'Muži tedy města toho dne sedmého, prvé než slunce zapadlo, řekli jemu: Co sladšího nad med, a co silnějšího nad lva? Kterýž řekl jim: Byste byli neorali mou jalovičkou, neuhodli byste pohádky mé.'),
(1553119,54,7,14,19,'I sstoupil na něj Duch Hospodinův, a šel do Aškalon, a pobil z nich třidceti mužů. A vzav loupeže jejich, dal šaty proměnné těm, jenž uhodli pohádku, a rozhněvav se velmi, odšel do domu otce svého.'),
(1553120,54,7,14,20,'Žena pak Samsonova dostala se jednomu z tovaryšů jeho, kteréhož on byl k sobě připojil.'),
(1553121,54,7,15,1,'Stalo se pak po několika dnech, v čas žně pšeničné, že chtěje navštíviti Samson ženu svou, a přinésti s sebou kozlíka, řekl: Vejdu k ženě své do pokoje. A nedopustil mu otec její vjíti.'),
(1553122,54,7,15,2,'I řekl otec její: Domníval jsem se zajisté, že ji máš v nenávisti, protož dal jsem ji tovaryši tvému. Zdaliž není sestra její mladší pěknější než ona? Nechať jest tedy tvá místo oné.'),
(1553123,54,7,15,3,'I řekl jim Samson: Nebuduť já potom vinen Filistinským, když jim zle učiním.'),
(1553124,54,7,15,4,'Odšed tedy Samson, nalapal tři sta lišek, a vzav pochodně, obrátil jeden ocas k druhému, a dal vše jednu pochodni mezi dva ocasy do prostředka.'),
(1553125,54,7,15,5,'Potom zapálil ty pochodně, a pustil do obilí Filistinských, a popálil, jakž sžaté tak nesžaté, i vinice i olivoví.'),
(1553126,54,7,15,6,'I řekli Filistinští: Kdo je to učinil? Jimž odpovědíno: Samson zeť Tamnejského, proto že vzal ženu jeho a dal ji tovaryši jeho. Tedy přišedše Filistinští, spálili ji ohněm i otce jejího.'),
(1553127,54,7,15,7,'Tedy řekl jim Samson: Ač jste učinili tak, však až se lépe vymstím nad vámi, teprv přestanu.'),
(1553128,54,7,15,8,'I zbil je na hnátích i na bedrách porážkou velikou, a odšed, usadil se na vrchu skály Etam.'),
(1553129,54,7,15,9,'Pročež vytáhli Filistinští, a rozbivše stany proti Judovi, rozložili se až do Lechi.'),
(1553130,54,7,15,10,'Muži pak Juda řekli: Proč jste vytáhli proti nám? I odpověděli: Vytáhli jsme, abychom svázali Samsona, a učinili jemu tak, jako on nám učinil.'),
(1553131,54,7,15,11,'Tedy vyšlo tři tisíce mužů Juda k vrchu skály Etam, a řekli Samsonovi: Nevíš-liž, že panují nad námi Filistinští? Pročež jsi tedy nám to učinil? I odpověděl jim: Jakž mi učinili, tak jsem jim učinil.'),
(1553132,54,7,15,12,'Řekli také jemu: Přišli jsme, abychom tě svázali a vydali v ruku Filistinským. Tedy odpověděl jim Samson: Přisáhněte mi , že vy se na mne neoboříte.'),
(1553133,54,7,15,13,'Tedy mluvili jemu, řkouce: Nikoli, jediné tuze svížíce, vydáme tě v ruku jejich, ale nezabijeme tě. I svázali ho dvěma provazy novými, a svedli jej s skály.'),
(1553134,54,7,15,14,'Kterýž když přišel až do Lechi, Filistinští radostí křičeli proti němu. Přišel pak na něj Duch Hospodinův, a učiněni jsou provazové, kteříž byli na rukou jeho, jako niti lněné, když v ohni hoří, i spadli svazové s rukou jeho.'),
(1553135,54,7,15,15,'Tedy našel čelist osličí ještě vlhkou, a vztáh ruku svou, vzal ji a pobil ní tisíc mužů.'),
(1553136,54,7,15,16,'Protož řekl Samson: Čelistí osličí hromadu jednu, nýbrž dvě hromady, čelistí osličí zbil jsem tisíc mužů.'),
(1553137,54,7,15,17,'A když přestal mluviti, povrhl čelist z ruky své, a nazval to místo Ramat Lechi.'),
(1553138,54,7,15,18,'Žíznil pak velice, i volal k Hospodinu a řekl: Ty jsi učinil skrze ruce služebníka svého vysvobození toto veliké, nyní pak již žízní umru, aneb upadnu v ruku těch neobřezaných.'),
(1553139,54,7,15,19,'Tedy otevřel Bůh skálu v Lechi, i vyšly z ní vody, a napil se; i okřál, a jako ožil. Protož nazval jméno její studnice vzývajícího, kteráž jest v Lechi až do dnešního dne.'),
(1553140,54,7,15,20,'Soudil pak Izraele za času Filistinských dvadceti let.'),
(1553141,54,7,16,1,'Odšel pak Samson do Gázy, a uzřev tam ženu nevěstku, všel k ní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553142,54,7,16,2,'I povědíno obyvatelům Gázy: Samson přišel sem. Kteříž obeslavše se, střáhli na něj v bráně města přes celou noc, a stavěli se tiše té celé noci, řkouce: Až ráno zabijeme jej.'),
(1553143,54,7,16,3,'Spal pak Samson až do půl noci, a o půl noci vstal, a pochytiv vrata brány městské s oběma veřejemi a s závorou, vložil na ramena svá a vnesl je na vrch hory, kteráž byla naproti Hebronu.'),
(1553144,54,7,16,4,'Potom pak zamiloval ženu v údolí Sorek, jejíž jméno bylo Dalila.'),
(1553145,54,7,16,5,'I přišli knížata Filistinská k ní a řekli jí: Oklamej ho a zvěz, v čem jest síla jeho tak veliká, a jak bychom přemohli jej, abychom svížíce, skrotili jej; tobě pak jeden každý z nás dáme tisíc a sto lotů stříbra.'),
(1553146,54,7,16,6,'Tedy řekla Dalila Samsonovi: Prosím, oznam mi, v čem jest tak veliká síla tvá, a čím bys svázán a zemdlen býti mohl?'),
(1553147,54,7,16,7,'Odpověděl jí Samson: Kdyby mne svázali sedmi houžvemi surovými, kteréž ještě neuschly, tedy zemdlím, a budu jako jiný člověk.'),
(1553148,54,7,16,8,'I přinesli jí knížata Filistinská sedm houžví surových, kteréž ještě neuschly, a svázala ho jimi.'),
(1553149,54,7,16,9,'(V zálohách pak nastrojeni byli někteří u ní v komoře.) I řekla jemu: Filistinští na tě, Samsone. A on roztrhl houžve, jako by přetrhl nit koudelnou, přistrče k ohni, a není poznána síla jeho.'),
(1553150,54,7,16,10,'Tedy řekla Dalila Samsonovi: Aj, oklamals mne a lživě jsi mi mluvil. Prosím, oznam mi nyní, čím bys mohl svázán býti?'),
(1553151,54,7,16,11,'Kterýž odpověděl jí: Kdyby mne tuze svázali novými provazy, jimiž by ještě nic děláno nebylo, tedy zemdlím a budu jako kdokoli jiný z lidí.'),
(1553152,54,7,16,12,'I vzala Dalila provazy nové a svázala ho jimi, a řekla jemu: Filistinští na tě, Samsone. (Zálohy pak nastrojeny byly v komoře.) I roztrhl je na rukou svých jako nitku.'),
(1553153,54,7,16,13,'Tedy řekla Dalila Samsonovi: Až dosavad jsi mne svodil, a mluvils mi lež. Pověziž mi, čím bys svázán býti mohl. Odpověděl jí: Kdybys přivila sedm pramenů z vlasů hlavy mé k vratidlu tkadlcovskému.'),
(1553154,54,7,16,14,'Což učinivši, zarazila hřebem, a řekla jemu: Filistinští na tě, Samsone. A procítiv ze sna svého, vytrhl hřeb, osnovu i s vratidlem.'),
(1553155,54,7,16,15,'Opět řekla jemu: Kterak ty pravíš: Miluji tě, poněvadž srdce tvé není se mnou? Již jsi mne potřikrát oklamal a neoznámils mi, v čem jest tak veliká síla tvá.'),
(1553156,54,7,16,16,'Když tedy trápila jej slovy svými každého dne, a obtěžovala jej, umdlena jest duše jeho, jako by již měl umříti.'),
(1553157,54,7,16,17,'I otevřel jí cele srdce své a řekl jí: Břitva nevešla nikdy na hlavu mou, nebo Nazarejský Boží jsem od života matky své. Kdybych oholen byl, odešla by ode mne síla má, a zemdlel bych a byl jako jiný člověk.'),
(1553158,54,7,16,18,'Viduci pak Dalila, že by cele otevřel jí srdce své, poslala a zavolala knížat Filistinských těmi slovy: Poďte ještě jednou, nebo otevřel mi cele srdce své. Tedy přišli knížata Filistinská k ní, nesouce stříbro v rukou svých.'),
(1553159,54,7,16,19,'I uspala ho na klíně svém a povolala holiče, i dala oholiti sedm pramenů vlasů hlavy jeho. I počala jím strkati, když odešla od něho síla jeho.'),
(1553160,54,7,16,20,'A řekla: Filistinští na tě, Samsone. Procítiv pak ze sna svého, řekl: Vyjdu jako i prvé, a probiji se skrze ně. Nevěděl však, že Hospodin odstoupil od něho.'),
(1553161,54,7,16,21,'Tedy javše ho Filistinští, vyloupili mu oči, a dovedše ho do Gázy, svázali jej dvěma řetězy železnými. A mlel v domě vězňů.'),
(1553162,54,7,16,22,'Potom počaly mu vlasy na hlavě odrostati po oholení.'),
(1553163,54,7,16,23,'Knížata pak Filistinská shromáždili se, aby obětovali obět velikou bohu svému Dágonovi a aby se veselili; nebo řekli: Dalť jest bůh náš v ruce naše Samsona nepřítele našeho.'),
(1553164,54,7,16,24,'A když uzřel jej lid, chválili boha svého; nebo pravili: Dalť jest bůh náš v ruce naše nepřítele našeho a zhoubce země naší, kterýž mnohé z našich zmordoval.'),
(1553165,54,7,16,25,'I stalo, když se rozveselilo srdce jejich, že řekli: Zavolejte Samsona, aby kratochvílil před námi. Tedy povolali Samsona z domu vězňů, aby hral před nimi; i postavili ho mezi sloupy.'),
(1553166,54,7,16,26,'Nebo řekl Samson pacholeti, kteréž ho za ruku vodilo: Přiveď mne, ať mohu omakati sloupy, na nichž dům stojí, a zpodepříti se na ně.'),
(1553167,54,7,16,27,'Dům pak plný byl mužů a žen, a byla tam všecka knížata Filistinská, ano i na vrchu okolo tří tisíc mužů a žen, kteříž dívali se, když Samson hral.'),
(1553168,54,7,16,28,'I volal Samson k Hospodinu, a řekl: Panovníče Hospodine, prosím, rozpomeň se na mne, a posilni mne, žádám, toliko aspoň jednou, ó Bože, abych se jednou pomstíti mohl za své obě oči nad Filistinskými.'),
(1553169,54,7,16,29,'Objav tedy Samson oba sloupy prostřední, na nichž dům ten stál, zpolehl na ně, na jeden pravou a na druhý levou rukou svou.'),
(1553170,54,7,16,30,'Potom řekl Samson: Nechť umře život můj s Filistinskými. A nalehl silně, i padl dům na knížata a na všecken lid, kterýž byl v něm; i bylo mrtvých, kteréž pobil on umíraje, více než těch, kteréž pobil, živ jsa.'),
(1553171,54,7,16,31,'Tedy přišli přátelé jeho, a všecken dům otce jeho, a vzavše jej, odešli, a pochovali jej mezi Zaraha a Estaol v hrobě Manue otce jeho. A on soudil lid Izraelský dvadceti let.'),
(1553172,54,7,17,1,'Byl pak muž nějaký s hory Efraim, jehož jméno bylo Mícha.'),
(1553173,54,7,17,2,'Kterýž řekl matce své: Ten tisíc a sto stříbrných, kteříž vzati byli tobě, pro něž jsi zlořečila a mluvilas přede mnou, hle, stříbro to u mne jest, já jsem je vzal. I řekla matka jeho: Požehnaný jsi, synu můj, od Hospodina.'),
(1553174,54,7,17,3,'Navrátil tedy ten tisíc a sto stříbrných matce své. I řekla matka jeho: Jižť jsem zajisté posvětila stříbro to Hospodinu z ruky své, a tobě synu svému, aby udělán byl obraz rytý a slitý. Protož nyní dám je tobě.'),
(1553175,54,7,17,4,'On pak navrátil to stříbro matce své, z něhož vzala matka jeho dvě stě stříbrných, a dala zlatníku. I udělal z nich obraz rytý a slitý, kterýž byl v domě Míchově.'),
(1553176,54,7,17,5,'Měl pak ten Mícha chrám bohů, i udělal efod a terafim, a naplnil ruce jednoho z synů svých, aby mu byl knězem.'),
(1553177,54,7,17,6,'Toho času nebylo krále v Izraeli; jeden každý, což se mu za dobré vidělo, to činil.'),
(1553178,54,7,17,7,'Byl pak mládenec z Betléma Judova, totiž z čeledi Judovy, kterýž, jsa Levíta, byl tam pohostinu.'),
(1553179,54,7,17,8,'Odšel tedy člověk ten z města Betléma Judova, aby byl pohostinu, kdež by se mu koli nahodilo. I přišel na horu Efraim, až k domu Míchovu, jda cestou svou.'),
(1553180,54,7,17,9,'Jemuž řekl Mícha: Odkud jdeš? Odpověděl mu: Já jsem Levíta, z Betléma Judova beru se, abych byl pohostinu, kdež by mi se koli nahodilo.'),
(1553181,54,7,17,10,'I řekl jemu Mícha: Zůstaň u mne, a buď mi za otce a za kněze, a buduť dávati deset stříbrných na každý rok, a dvoje roucho i stravu tvou. I šel Levíta.'),
(1553182,54,7,17,11,'Líbilo se pak Levítovi zůstati u muže toho, a byl u něho mládenec ten, jako jeden z synů jeho.'),
(1553183,54,7,17,12,'I posvětil Mícha rukou Levíty, a byl mu mládenec ten za kněze; i bydlil v domě jeho.'),
(1553184,54,7,17,13,'Řekl pak Mícha: Nyníť vím, že mi dobře učiní Hospodin, proto že mám toho Levítu za kněze.'),
(1553185,54,7,18,1,'V těch dnech nebylo krále v Izraeli, a toho času pokolení Dan hledalo sobě dědičného místa k bydlení, nebo se mu ještě nebylo dostalo dílu u prostřed synů Izraelských až do dne toho.'),
(1553186,54,7,18,2,'Tedy poslali synové Dan z čeledi své pět mužů z končin svých, mužů silných z Zaraha a Estaol, aby spatřili zemi a pilně prohlédli ji, a řekli jim: Jděte, shlédněte zemi. Kteřížto když přišli na horu Efraim až do domu Míchova, přenocovali tam.'),
(1553187,54,7,18,3,'Když pak byli blízko domu Míchova, poznali hlas toho mládence Levíty, a uchýlivše se tam, řekli jemu: Kdo tě sem přivedl? Co ty zde děláš? A co ty zde máš?'),
(1553188,54,7,18,4,'Odpověděl jim: Toto mi a toto učinil Mícha, a ze mzdy najal mne, abych byl jeho knězem.'),
(1553189,54,7,18,5,'I řekli jemu: Poraď se, prosíme, s Bohem, abychom věděli, zdaří-li se nám cesta naše, kterouž jdeme.'),
(1553190,54,7,18,6,'Odpověděl jim kněz: Jděte v pokoji, Hospodinť spravuje cestu vaši, po níž jdete.'),
(1553191,54,7,18,7,'Tedy odešlo pět mužů těch, a přišli do Lais, a viděli lid, kterýž tam byl, bezpečně bydlící, vedlé obyčeje Sidonských v zahálce a bezpečnosti, a že nebylo, co by je kormoutiti mělo v té zemi, ani kdo by dědičně ujíti chtěl království. K tomu i od Sidonských vzdáleni byli, aniž spříznění jaké s kým měli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553192,54,7,18,8,'Když se pak navrátili k bratřím svým do Zaraha a Estaol, řekli jim bratří jejich: Což vy?'),
(1553193,54,7,18,9,'I odpověděli: Vstaňte a táhněme na ně, nebo shlédli jsme tu zemi, a aj, velmi dobrá jest; a vy mlčíte? Nelenujtež se táhnouti, a vjíti k opanování té země.'),
(1553194,54,7,18,10,'(Když přijdete, vejdete k lidu bezpečnému, a do země prostranné;) nebo dal ji Bůh v ruku vaši, místo, v němž není žádného nedostatku jakýchkoli věcí, kteréž na zemi býti mohou.'),
(1553195,54,7,18,11,'Tedy vyšlo z čeledi Dan odtud, totiž z Zaraha a Estaol, šest set mužů oděných v odění válečné.'),
(1553196,54,7,18,12,'A vytáhše, položili se u Kariatjeharim Judova; pročež nazvali to místo Mahane Dan až do dnešního dne, a jest za Kariatjeharim.'),
(1553197,54,7,18,13,'A odtud táhnouce na horu Efraim, přišli až k domu Míchovu.'),
(1553198,54,7,18,14,'I mluvilo těch pět mužů, kteříž chodili k shlédnutí země Lais, a řekli bratřím svým: Víte-liž, že v domích těchto jest efod a terafim, a rytina a slitina? Protož nyní vězte, co máte činiti.'),
(1553199,54,7,18,15,'A uchýlivše se tam, vešli do domu mládence Levíty v domě Míchově, a pozdravili ho pokojně.'),
(1553200,54,7,18,16,'Ale šest set mužů oděných v zbroj svou válečnou, kteříž byli z pokolení Dan, stáli přede dveřmi.'),
(1553201,54,7,18,17,'A šedše pět mužů, kteříž chodili k shlédnutí země, vešli tam a vzali rytinu a efod a terafim a slitinu; kněz pak stál u vrat brány s šesti sty muži oděnými v zbroji.'),
(1553202,54,7,18,18,'A ti, kteříž vešli do domu Míchova, vzali rytinu, efod a terafim, a slitinu. I řekl jim kněz: Což to děláte?'),
(1553203,54,7,18,19,'Kteříž odpověděli: Mlč, vlož ruku svou na ústa svá a poď s námi, a budeš nám za otce a za kněze. Což jest lépe tobě, knězem-li býti v domě jednoho člověka, či býti knězem pokolení a čeledi v Izraeli?'),
(1553204,54,7,18,20,'I zradovalo se srdce kněze, a vzav efod a terafim a rytinu, šel u prostřed lidu toho.'),
(1553205,54,7,18,21,'A obrátivše se odešli, a pustili napřed děti a dobytek, a což měli dražšího.'),
(1553206,54,7,18,22,'Když pak opodál byli od domu Míchova, tedy muži, kteříž bydlili v domích blízkých domu Míchova, shromáždili se a honili syny Dan.'),
(1553207,54,7,18,23,'I volali za syny Dan. Kteříž ohlédše se, řekli Míchovi: Cožtě, že jsi jich tolik shromáždil?'),
(1553208,54,7,18,24,'Odpověděl: Bohy mé, kteréž jsem udělal, vzali jste, i kněze, a odcházíte. Což pak již budu míti? A ještě se ptáte: Coť jest?'),
(1553209,54,7,18,25,'Jemuž odpověděli synové Dan: Hlediž, ať více neslyšíme hlasu tvého za sebou, sic jináč oboří se na vás muži hněviví, a ztratíš duši svou i duše domu svého.'),
(1553210,54,7,18,26,'I brali se muži Dan cestou svou. A vida Mícha, že by silnější byli nežli on, obrátiv se, šel do domu svého.'),
(1553211,54,7,18,27,'Oni pak vzavše, což byl udělal Mícha, i kněze, kteréhož měl, přitáhli do Lais k lidu zahálivému a bezpečnému; i pobili je ostrostí meče, a město vypálili ohněm.'),
(1553212,54,7,18,28,'A nebylo žádného, kdo by jim spomohl; nebo daleko byl Sidon, aniž měli spříznění s kterými lidmi. Město pak bylo v údolí, kteréž jest v Betrohob. A vystavěvše zase město, bydlili v něm.'),
(1553213,54,7,18,29,'A nazvali jméno města toho Dan, od jména otce svého, kterýž narozen byl Izraelovi, ješto prvé jméno města toho bylo Lais.'),
(1553214,54,7,18,30,'Postavili pak sobě synové Dan tu rytinu, a Jonatan syn Gersonův, syna Mojžíšova, on i synové jeho byli kněžími v pokolení Dan, až do dne zajetí obyvatelů země.'),
(1553215,54,7,18,31,'Vystavili tedy sobě tu rytinu, kterouž udělal Mícha, a byla tam po všecky dny,v nichž dům Boží byl v Sílo.'),
(1553216,54,7,19,1,'Stalo se také toho času, když krále nebylo v Izraeli, že muž nějaký Levíta, jsa pohostinu při straně hory Efraimské, pojal sobě ženu ženinu z Betléma Judova.'),
(1553217,54,7,19,2,'Kterážto ženina smilnila u něho. I odešla od něho do domu otce svého do Betléma Judova, a byla tam plné čtyři měsíce.'),
(1553218,54,7,19,3,'Vstav pak muž její, šel za ní, aby namluvě ji, zase ji přivedl, maje s sebou mládence svého a dva osly. Tedy ona uvedla jej do domu otce svého. Kteréhož když uzřel otec té děvky, zradoval se z příchodu jeho.'),
(1553219,54,7,19,4,'I zdržel jej tchán jeho, otec té děvky, tak že pozůstal u něho za tři dni. Tu také jídali i píjeli i nocovali.'),
(1553220,54,7,19,5,'Dne pak čtvrtého, když tím raněji vstali, vstal i on, aby odšel. Tedy řekl otec té děvky k zeti svému: Posilni se kouskem chleba, a potom půjdete.'),
(1553221,54,7,19,6,'Sedli tedy a pojedli oba spolu, a napili se. Potom řekl otec děvky k muži: Posediž medle, nýbrž pobuď přes noc, a buď mysli veselé.'),
(1553222,54,7,19,7,'Když pak vstal ten muž, chtěje předce jíti, mocí jej zdržel test jeho. A tak se vrátil a zůstal tu přes noc.'),
(1553223,54,7,19,8,'Potom dne pátého vstal tím raněji, aby se bral. I řekl otec té děvky: Posilň se, prosím. I prodlili, až se den nachýlil, nebo jedli oba.'),
(1553224,54,7,19,9,'Tedy vstal muž ten, aby šel, on i ženina jeho i mládenec jeho. I řekl mu tchán jeho, otec děvky: Aj, již se den nachýlil k večerou, medle zůstaňte přes noc; aj, dokonává se den, pobuď přes noc zde, a buď mysli veselé, a zítra tím raněji vypravíte se na cestu svou, a půjdeš k příbytku svému.'),
(1553225,54,7,19,10,'On pak nechtěl zůstati přes noc, ale vstav, odšel, a přišel proti Jebus, jenž jest Jeruzalém, a s ním dva oslové s břemeny i ženina jeho.'),
(1553226,54,7,19,11,'Když pak byli blízko Jebus, a den se velmi nachýlil, řekl mládenec pánu svému: Poď, prosím, obraťme se do města toho Jebuzejského, abychom v něm přenocovali.'),
(1553227,54,7,19,12,'Jemuž odpověděl pán jeho: Neobrátíme se do města cizozemců, kteréž není synů Izraelských, ale půjdeme až do Gabaa.'),
(1553228,54,7,19,13,'Řekl ještě mládenci svému: Poď, abychom přišli k některému z těch míst, a zůstali přes noc v Gabaa aneb v Ráma.'),
(1553229,54,7,19,14,'Pomíjejíce tedy, odešli, a zapadlo jim slunce blízko Gabaa, kteréž jest Beniaminských.'),
(1553230,54,7,19,15,'I obrátili se tam, aby vejdouce, zůstali přes noc v Gabaa. A když tam všel, posadil se na ulici města, proto že nebyl, kdo by je přijal do domu a dal jim nocleh.'),
(1553231,54,7,19,16,'A aj, muž starý vracoval se od práce své s pole u večer, kterýž také byl s hory Efraimovy, a bydlil pohostinu v Gabaa; ale lidé místa toho byli synové Jemini.'),
(1553232,54,7,19,17,'A když pozdvihl očí svých, uzřel muže toho pocestného na ulici města. I řekl jemu ten stařec: Kam se béřeš, a odkud jdeš?'),
(1553233,54,7,19,18,'Jemuž odpověděl: Jdeme z Betléma Judova až k stranám hory Efraimovy, odkudž jsem; nebo jsem byl odšel do Betléma Judova. Jduť pak do domu Hospodinova, a není žádného, kdo by mne přijal do domu;'),
(1553234,54,7,19,19,'Ješto mám i slámu a obrok pro osly své, tolikéž i chléb, ano i víno pro sebe a děvku tvou, a mládence, kterýž jest s služebníkem tvým, tak že v ničemž nemáme nedostatku.'),
(1553235,54,7,19,20,'I řekl muž ten starý: Měj ty pokoj. Čehoť se koli nedostává, nechť já to opatřím, ty toliko na ulici nezůstávej přes noc.'),
(1553236,54,7,19,21,'Tedy uvedl jej do domu svého, a obrok dal oslům; potom umyvše nohy své, jedli a pili.'),
(1553237,54,7,19,22,'A když očerstvili srdce své, aj, muži města toho, muži nešlechetní, obklíčivše dům, tloukli na dvéře a mluvili tomu muži starci, hospodáři domu, řkouce: Vyveď muže toho, kterýž všel do domu tvého, abychom ho poznali.'),
(1553238,54,7,19,23,'K nimžto vyšed muž ten, hospodář domu, řekl jim: Nikoli, bratří moji, nečiňte, prosím, zlého, poněvadž všel ten muž do domu mého, neprovoďte nešlechetnosti té.'),
(1553239,54,7,19,24,'Aj, dceru svou, kteráž pannou jest, a ženinu jeho, ty hned vyvedu, i ponížíte jich, aneb učiníte jim, což se vám za dobré vidí; jen muži tomu nečiňte věci té hanebné.'),
(1553240,54,7,19,25,'Ale nechtěli ho uposlechnouti muži ti. Pojav tedy muž ten ženinu svou, vyvedl ji k nim ven, i poznali ji, a zle jí požívali přes celou noc až do jitra; potom pustili ji, když počínalo zasvitávati.'),
(1553241,54,7,19,26,'V svitání pak přišla žena ta, a padši, ležela u dveří domu toho muže, kdež byl pán její, až se rozednilo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553242,54,7,19,27,'Když pak vstal pán její ráno, otevřev dvéře domu, vycházel, aby se bral dále cestou svou. A aj, žena ta, ženina jeho, ležela u dveří domu, a ruce její byly na prahu.'),
(1553243,54,7,19,28,'Jížto řekl: Vstaň, a poďme. A nic neodpověděla. Vzav tedy ji na osla, a vstav muž ten, odšel k místu svému.'),
(1553244,54,7,19,29,'Když pak přišel do domu svého, vzal meč, a pochytiv ženinu svou, rozsekal ji s kostmi jejími na dvanácte kusů, a rozeslal ji po všech končinách Izraelských.'),
(1553245,54,7,19,30,'A bylo, že kdožkoli uzřel, pravil: Nikdy se nestalo ani vidíno bylo co podobného od toho času, jakž vyšli synové Izraelští z země Egyptské, až do tohoto dne. Posuďte toho pilně, poraďte se a promluvte o to.'),
(1553246,54,7,20,1,'I vyšli všickni synové Izraelští, a shromáždilo se všecko množství jednomyslně od Dan až do Bersabé, i země Galád, k Hospodinu do Masfa.'),
(1553247,54,7,20,2,'Kdežto postavili se přední všeho lidu, všecka pokolení Izraelská v shromáždění lidu Božího, čtyřikrát sto tisíc lidu pěšího válečného.'),
(1553248,54,7,20,3,'(Uslyšeli pak synové Beniamin, že by sešli se synové Izraelští v Masfa.) I řekli synové Izraelští: Povězte, kterak se stala nešlechetnost ta?'),
(1553249,54,7,20,4,'I odpověděv muž Levíta, manžel ženy zamordované, řekl: Do Gabaa kteréž jest Beniaminovo, přišel jsem s ženinou svou, abych tam přenocoval.'),
(1553250,54,7,20,5,'Tedy povstavše proti mně muži Gabaa, obklíčili mne v domě v noci, myslíce mne zamordovati, ženinu pak mou trápili, tak že umřela.'),
(1553251,54,7,20,6,'Pročež vzav ženinu svou, rozsekal jsem ji na kusy, a rozeslal jsem ji do všech krajin dědictví Izraelského; nebo nešlechetnosti a mrzkosti se dopustili v Izraeli.'),
(1553252,54,7,20,7,'Aj, všickni vy synové Izraelští jste; považte toho mezi sebou, a raďte se o to.'),
(1553253,54,7,20,8,'A povstav všecken lid jednomyslně, řekli: Nenavrátí se žádný z nás do příbytku svého, aniž odejde kdo do domu svého.'),
(1553254,54,7,20,9,'Ale nyní toto učiníme Gabaa, losujíce proti němu.'),
(1553255,54,7,20,10,'Vezmeme deset mužů ze sta po všech pokoleních Izraelských, a sto z tisíce, a tisíc z desíti tisíců, aby dodávali potravy lidu, kterýž by přitáhna do Gabaa Beniaminova, pomstil všech nešlechetností jeho, kterýchž se dopustilo v Izraeli.'),
(1553256,54,7,20,11,'I sebrali se všickni muži Izraelští na to město, snesše se za jednoho člověka.'),
(1553257,54,7,20,12,'Poslala pak pokolení Izraelská muže do všech čeledí synů Beniamin, řkouce: Jaký to zlý skutek stal se mezi vámi?'),
(1553258,54,7,20,13,'Nyní tedy vydejte ty muže bezbožné, kteříž jsou v Gabaa, ať je zbijeme a odejmeme zlé z Izraele. Ale nechtěli Beniaminští slyšeti hlasu bratří svých, synů Izraelských.'),
(1553259,54,7,20,14,'Nýbrž shromáždili se synové Beniamin z měst svých do Gabaa, aby vytáhli k boji proti synům Izraelským.'),
(1553260,54,7,20,15,'Toho dne načteno jest synů Beniamin z měst jejich dvadceti šest tisíc mužů bojovných, kromě obyvatelů Gabaa, jichž načteno bylo šest set mužů vybraných.'),
(1553261,54,7,20,16,'Mezi kterýmžto vším lidem bylo sedm set mužů vybraných, neužívajících pravé ruky své, z nichž každý z praku kamením házeli k vlasu, a nechybovali se.'),
(1553262,54,7,20,17,'Mužů pak Izraelských načteno jest kromě Beniaminských čtyřikrát sto tisíc mužů bojovných; všickni tito byli muži udatní.'),
(1553263,54,7,20,18,'Vstavše pak, brali se do domu Boha silného, a tázali se Boha, a řekli synové Izraelští: Kdo z nás půjde napřed k boji proti synům Beniamin? I řekl Hospodin: Juda půjde napřed.'),
(1553264,54,7,20,19,'A tak ráno vstavše synové Izraelští, položili se proti Gabaa.'),
(1553265,54,7,20,20,'I táhli muži Izraelští k boji proti synům Beniamin, a sšikovali se muži Izraelští k bitvě proti Gabaa.'),
(1553266,54,7,20,21,'Vyšedše pak synové Beniamin z Gabaa, porazili z Izraele toho dne dvamecítma tisíc mužů na zem.'),
(1553267,54,7,20,22,'A posilnivše se muži lidu Izraelského, spořádali se zase k boji na místě, na kterémž se prvního dne zřídili.'),
(1553268,54,7,20,23,'Prvé pak šli synové Izraelští, a plakali před Hospodinem až do večera. I tázali se Hospodina těmi slovy: Půjdeme-li ještě k boji proti synům Beniamina bratra našeho? Odpověděl Hospodin: Jděte proti nim.'),
(1553269,54,7,20,24,'Tedy potýkali se synové Izraelští s syny Beniamin druhého dne.'),
(1553270,54,7,20,25,'A vyšedše synové Beniamin z Gabaa na ně druhého dne, porazili z synů Izraelských opět osmnácte tisíc mužů na zem, vše mužů bojovných.'),
(1553271,54,7,20,26,'Protož vstoupili všickni synové Izraelští a všecken lid, a přišli do domu Boha silného. I plakali, usadivše se tam před Hospodinem, a postili se toho dne až do večera; obětovali též oběti zápalné a pokojné před Hospodinem.'),
(1553272,54,7,20,27,'I tázali se synové Izraelští Hospodina, (nebo tu byla truhla smlouvy Boží v těch dnech,'),
(1553273,54,7,20,28,'A Fínes syn Eleazara, syna Aronova, stál před ní v ten čas), řkouce: Půjdeme-li ještě k boji proti synům Beniamina bratra našeho, čili tak necháme? Odpověděl Hospodin: Jděte, nebo zítra dám je v ruku vaši.'),
(1553274,54,7,20,29,'Tedy Izraelští zdělali zálohy proti Gabaa všudy vůkol.'),
(1553275,54,7,20,30,'I šli synové Izraelští proti synům Beniamin dne třetího, a sšikovali se proti Gabaa, jako prvé jednou i podruhé.'),
(1553276,54,7,20,31,'Vyšedše pak synové Beniamin proti lidu, odtrhli se od města, a počali bíti a mordovati lidu, jako prvé jednou i druhé po stezkách, (z nichž jedna šla k Bethel a druhá do Gabaa), i po poli, a okolo třidcíti mužů z Izraele.'),
(1553277,54,7,20,32,'A řekli synové Beniamin: Padají před námi jako i prvé. Synové pak Izraelští řekli byli: Utíkejme, abychom je odtrhli od města až k stezkám.'),
(1553278,54,7,20,33,'A v tom všickni synové Izraelští vstavše z místa svého, sšikovali se v Baltamar; zálohy také Izraelovy vyskočily z místa svého z trávníků Gabaa.'),
(1553279,54,7,20,34,'Tedy vyšlo proti Gabaa deset tisíc mužů vybraných ze všeho Izraele, a bitva se rozmáhala; oni pak nevěděli o tom, že je potkati mělo zlé.'),
(1553280,54,7,20,35,'I porazil Hospodin Beniamina před Izraelem, a zbili synové Izraelští z Beniaminských dne toho pětmecítma tisíc a sto mužů, vše bojovných.'),
(1553281,54,7,20,36,'A vidouce synové Beniamin, že by poraženi byli, (nebo muži Izraelští ustupovali z místa Beniaminským, ubezpečivše se na zálohy, kteréž zdělali proti Gabaa.'),
(1553282,54,7,20,37,'Zálohy pak pospíšily a obořily se na Gabaa, a rozvláčně troubivše zálohy, zbily všecko město ostrostí meče.'),
(1553283,54,7,20,38,'Měli pak muži Izraelští s zálohami jistý čas uložený, aby když by oni zapálili město,'),
(1553284,54,7,20,39,'Obrátili se synové Izraelští k boji. Beniaminští pak počali bíti a mordovati, a zbili z synů Izraelských okolo třidcíti mužů; nebo řekli: Jistě že padají před námi jako v první bitvě.'),
(1553285,54,7,20,40,'Oheň pak počal vzhůru jíti z města, a sloup dymový. A ohlédše se Beniaminští zpět, uzřeli, an vstupuje oheň města k nebi.)'),
(1553286,54,7,20,41,'A že muži Izraelští obrátili se, i zděšeni jsou muži Beniamin, nebo viděli, že zahynutí jim nastává.'),
(1553287,54,7,20,42,'I utíkali před muži Izraelskými cestou ku poušti, a bojovníci postihali je, a kteří z měst vyšli, mordovali je mezi sebou.'),
(1553288,54,7,20,43,'A tak obklíčili Beniaminské, a honili i porazili je, od Manuha až naproti Gabaa k východu slunce.'),
(1553289,54,7,20,44,'Tedy padlo Beniaminských osmnácte tisíc mužů; všickni ti byli muži silní.'),
(1553290,54,7,20,45,'Těch pak, kteříž obrátivše se, utíkali na poušť k skále Remmon, zpaběrovali po cestách pět tisíc mužů; potom honili je až k Gidom, a zbili z nich dva tisíce mužů.'),
(1553291,54,7,20,46,'A tak bylo všech, kteříž padli v ten den z Beniaminských, pětmecítma tisíc mužů bojovných, vše mužů silných.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553292,54,7,20,47,'I obrátilo se na poušť a uteklo k skále Remmon šest set mužů, kteříž zůstali v skále Remmon za čtyři měsíce.'),
(1553293,54,7,20,48,'Potom muži Izraelští navrátili se k synům Beniamin, a zbili je ostrostí meče, tak lidi v městech jako hovada, i všecko, což nalezeno bylo; také i všecka města, kteráž ještě pozůstávala, ohněm vypálili.'),
(1553294,54,7,21,1,'Nadto každý z mužů Izraelských přísahou se byli zavázali v Masfa, řkouce: Žádný z nás nedá dcery své Beniaminským za manželku.'),
(1553295,54,7,21,2,'Protož všel lid do domu Boha silného, a seděli tam až do večera před Bohem, a pozdvihše hlasu svého, plakali pláčem velikým.'),
(1553296,54,7,21,3,'A řekli: Proč Hospodine, Bože Izraelský, stalo se toto v Izraeli, aby dnes ubylo jedno pokolení z Izraele?'),
(1553297,54,7,21,4,'Nazejtří pak ráno vstal lid, a vzdělali tam oltář, a obětovali oběti zápalné a pokojné.'),
(1553298,54,7,21,5,'Řekli pak synové Izraelští: Jest-li kdo, ješto nepřišel do shromáždění tohoto ze všech pokolení Izraelských k Hospodinu? (Nebo se byli velice zapřisáhli proti tomu, kdož by nepřišel k Hospodinu do Masfa, řkouce: Bez milosti ať umře.'),
(1553299,54,7,21,6,'Nebo litujíce synové Izraelští Beniamina bratra svého, řekli: Dnes vyhlazeno jest jedno pokolení z Izraele.'),
(1553300,54,7,21,7,'Jakž tedy učiníme s těmi ostatky, aby ženy měli, poněvadž jsme se přísahou zavázali skrze Hospodina, že jim nedáme dcer svých za manželky?)'),
(1553301,54,7,21,8,'Řekli tedy: Jest-li kdo z pokolení Izraelských, ješto nepřišel k Hospodinu do Masfa? A aj, nepřišel byl žádný do vojska z Jábes Galád do shromáždění.'),
(1553302,54,7,21,9,'Nebo když sečten byl lid, a aj, nebylo tam žadného z obyvatelů Jábes Galád.'),
(1553303,54,7,21,10,'Protož poslalo tam shromáždění to dvanácte tisíc mužů nejsilnějších, a přikázali jim, řkouce: Jděte a pobíte obyvatele Jábes Galád ostrostí meče, ženy i děti.'),
(1553304,54,7,21,11,'Toto pak učiníte: Všecky mužského pohlaví, a každou ženu, kteráž muže poznala, zamordujete.'),
(1553305,54,7,21,12,'Nalezli tedy mezi obyvateli Jábes Galád čtyři sta děveček panen, kteréž nepoznaly muže, a přivedli je do vojska v Sílo, kteréž bylo v zemi Kananejské.'),
(1553306,54,7,21,13,'Tedy poslalo všecko to shromáždění, a mluvili k synům Beniamin, kteříž byli v skále Remmon, a povolali jich v pokoji.'),
(1553307,54,7,21,14,'Protož navrátili se Beniaminští toho času. I dali jim ženy, kteréž živé zachovali z žen Jábes Galád, ale ani tak se jim nedostávalo jich.'),
(1553308,54,7,21,15,'Lidu pak líto bylo Beniamina, proto že učinil Hospodin mezeru v pokoleních Izraelských.'),
(1553309,54,7,21,16,'Řekli tedy starší shromáždění toho: Jak učiníme s těmi pozůstalými, aby měli ženy? Nebo vyhlazeny jsou ženy z pokolení Beniamin.'),
(1553310,54,7,21,17,'Řekli také: Dědictví Beniaminovo pozůstalým náleží, aby nezahynulo pokolení z Izraele.'),
(1553311,54,7,21,18,'My pak nemůžeme jim dáti dcer svých za manželky; (nebo se byli přísahou zavázali synové Izraelští, řkouce: Zlořečený buď, kdož by dal manželku synům Beniamin.)'),
(1553312,54,7,21,19,'Potom řekli: Aj, slavnost Hospodinova bývá v Sílo každého roku na místě, kteréž jest s půlnoční strany domu Boha silného, k východu slunce cestě, kterouž se chodí od domu Boha silného do Sichem, a Lebnu jest na poledne.'),
(1553313,54,7,21,20,'Přikázali tedy synům Beniamin, řkouce: Jděte a skrejte se v vinicích.'),
(1553314,54,7,21,21,'A šetřte, a aj, když vyjdou dcery Sílo plésati v houfích, tedy vyskočíte z vinic a pochytíte sobě každý manželku svou ze dcer Sílo, a odejdete do země Beniamin.'),
(1553315,54,7,21,22,'Když pak přijdou otcové jejich aneb bratří jejich, aby se před námi soudili, tedy řekneme jim: Slitujte se nad námi místo nich, nebo v té válce nevzali jsme pro každého z nich manželky; také jste vy jim nedali jich, a tak nebudete nic vinni.'),
(1553316,54,7,21,23,'Tedy učinili tak synové Beniamin, a přivedli sobě manželky vedlé počtu svého z těch plésajících, kteréž uchvátili; a odšedše, navrátili se k dědictví svému, a vzdělavše zase města svá, bydlili v nich.'),
(1553317,54,7,21,24,'A tak odešli odtud synové Izraelští toho času, jeden každý k svému pokolení a k čeledi své; a vrátili se odtud jeden každý k dědictví svému.'),
(1553318,54,7,21,25,'Těch dnů nebylo krále v Izraeli, ale každý, což se mu vidělo, to činil.'),
(1553319,54,8,1,1,'Stalo se pak za času soudců, že byl hlad v zemi. I odšel člověk z Betléma Judova, a bydlil pohostinu v krajině Moábské s manželkou svou a se dvěma syny svými.'),
(1553320,54,8,1,2,'Jméno pak muže toho Elimelech, a jméno ženy jeho Noémi, jméno také dvou synů jeho Mahalon a Chelion, Efratejští z Betléma Judova; a přišedše do krajiny Moábské, bydlili tam.'),
(1553321,54,8,1,3,'Umřel pak Elimelech, muž Noémi; i pozůstala ona s oběma syny svými.'),
(1553322,54,8,1,4,'Kteříž pojali sobě ženy Moábské; jméno jedné bylo Orfa a jméno druhé Rut. I bydlili tam téměř deset let.'),
(1553323,54,8,1,5,'Umřeli také oni oba dva, Mahalon i Chelion, a zůstala žena ta po dvou synech svých a manželu svém.'),
(1553324,54,8,1,6,'Tedy vstavši ona s nevěstami svými, navracela se z krajiny Moábské; nebo slyšela v krajině Moábské, že Hospodin navštívil lid svůj, dav jemu chléb.'),
(1553325,54,8,1,7,'Vyšedši tedy z místa, na němž bydlila, a obě nevěsty její s ní, daly se na cestu, aby se navrátily do země Judské.'),
(1553326,54,8,1,8,'Řekla pak Noémi oběma nevěstám svým: Jděte, navraťte se jedna každá do domu matky své. Učiniž Hospodin s vámi milosrdenství, jakož jste i vy činili s mrtvými syny mými i se mnou.'),
(1553327,54,8,1,9,'Dejž vám Hospodin, abyste nalezly odpočinutí, jedna každá v domě muže svého. I políbila jich, ony pak pozdvihše hlasu svého, plakaly.'),
(1553328,54,8,1,10,'A řekly jí: Obrátíme se raději s tebou k lidu tvému.'),
(1553329,54,8,1,11,'I řekla Noémi: Navraťte se, dcerky mé. Proč chcete jíti se mnou? Zdaliž ještě budu míti syny, aby byli vaši muži?'),
(1553330,54,8,1,12,'Navraťte se, dcerky mé, a odejděte, neboť jsem již stará k vdání; nýbrž bych i řekla, že mám naději, bych i noci této se vdala a syny zrodila,'),
(1553331,54,8,1,13,'Zdaž byste na ně čekaly, až by dorostli? Zdaliž tou příčinou meškati se budete, abyste se neměly vdáti? Ne tak, mé dcerky, nebo mé trápení větší jest nežli vaše, proto že ruka Hospodinova jest proti mně.'),
(1553332,54,8,1,14,'Ony pak pozdvihše hlasu, opět plakaly. A Orfa políbivši svegruši svou, odešla, Rut pak přídržela se jí.'),
(1553333,54,8,1,15,'Kteréžto řekla Noémi: Aj, přítelkyně tvá navrátila se k lidu svému a k bohům svým, navratiž se také za ní.'),
(1553334,54,8,1,16,'Ale Rut řekla: Nenuť mne, abych tě opustiti a od tebe odjíti měla. Nebo kamž se koli obrátíš, půjdu, a kdekoli bydliti budeš, i já bydliti budu; lid tvůj lid můj, a Bůh tvůj Bůh můj.'),
(1553335,54,8,1,17,'Kdekoli umřeš, umru, a tu pochována budu. Toto mi učiň Hospodin, a toto přidej, že toliko smrt rozdělí mne s tebou.'),
(1553336,54,8,1,18,'Tedy viduci, že se na tom ustavila, aby šla s ní, přestala k ní mluviti.'),
(1553337,54,8,1,19,'I šly obě dvě spolu, až přišly k Betlému. I stalo se, že když přišly do Betléma, roznesla se pověst o nich po všem městě, a pravili: To-li jest ta Noémi?'),
(1553338,54,8,1,20,'Jimž ona řekla: Nenazývejte mne Noémi, říkejte mi Mara; nebo hořkostí velikou naplnil mne Všemohoucí.'),
(1553339,54,8,1,21,'Vyšla jsem plná, teď pak prázdnou mne zase Hospodin přivedl. Pročež tedy nazýváte mne Noémi, poněvadž mne Hospodin ssoužil, a Všemohoucí mne znuzil?'),
(1553340,54,8,1,22,'A navrátila se Noémi s Rut Moábskou, nevěstou svou; navrátila se pak z krajiny Moábské. I přišly do Betléma, když počínali žíti ječmene.'),
(1553341,54,8,2,1,'Měla pak Noémi přítele po manželu svém, muže mocného z čeledi Elimelechovy, jménem Bóza.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553342,54,8,2,2,'I řekla Rut Moábská Noémi: Nechť medle jdu na pole sbírati klasů za tím, kdož by mi toho přál. Jížto ona řekla: Jdi, dcero má.'),
(1553343,54,8,2,3,'Šla tedy, a přišedši, sbírala klasy na poli za ženci. Přihodilo se pak, že přišla na díl pole toho, kteréž přináleželo Bózovi, jenž byl z čeledi Elimelechovy.'),
(1553344,54,8,2,4,'A v tom přišel Bóz z Betléma, a řekl žencům: Hospodin s vámi. Kteříž odpověděli jemu: Požehnejž tobě Hospodin.'),
(1553345,54,8,2,5,'I řekl Bóz služebníku svému, kterýž postaven byl nad ženci: Čí jest tato mladice?'),
(1553346,54,8,2,6,'Odpověděl služebník ten, kterýž postaven byl nad ženci, a řekl: Jest mladice Moábská, kteráž přišla s Noémi z země Moábské.'),
(1553347,54,8,2,7,'A řekla mi: Prosím, nechť sbírám a shromažďuji klasy mezi snopy za ženci. A přišedši, trvá od jitra až dosavad, kromě že na chvilku doma pobyla.'),
(1553348,54,8,2,8,'Tedy řekl Bóz k Rut: Slyš, dcero má, nechoď sbírati na jiné pole, aniž odcházej odsud, ale přídrž se teď děvek mých.'),
(1553349,54,8,2,9,'Zůstávej na tom poli, na němž budou žíti, a choď za nimi, nebo jsem přikázal služebníkům svým, aby se tebe žádný nedotýkal. Bude-liť se chtíti píti, jdi k nádobám, a napí se té vody, kteréž by navážili služebníci moji.'),
(1553350,54,8,2,10,'Tedy ona padla na tvář svou, a schýlivši se k zemi, řekla jemu: Odkudž mi to, že jsem nalezla milost před tebou, abys se známil ke mně, kteráž jsem cizozemka.'),
(1553351,54,8,2,11,'Odpověděl Bóz a řekl: O všemť mi oznámeno jest, co jsi koli činila svegruši své po smrti muže svého, a že opustivši otce svého a matku svou, i zemi, v kteréžs se narodila, šla jsi mezi lid, kteréhožs prvé neznala.'),
(1553352,54,8,2,12,'Odplatiž tobě Hospodin za skutek tvůj, a budiž mzda tvá dokonalá od Hospodina Boha Izraelského, poněvadž jsi přišla, abys pod křídly jeho doufala.'),
(1553353,54,8,2,13,'Kterážto řekla: Nalezla jsem milost před tebou, pane můj, poněvadž jsi mne potěšil, a mluvils k srdci děvky své, ješto nejsem podobná jedné z děvek tvých.'),
(1553354,54,8,2,14,'Tedy řekl jí Bóz: Když bude čas jísti, přistup sem, a pojez chleba, a omoč skyvu svou v octě. I posadila se při žencích, a podal jí pražmy; ona pak jedla až do sytosti, a ještě jí zbylo.'),
(1553355,54,8,2,15,'I vstala, aby sbírala. Přikázal pak Bóz služebníkům svým, řka: Byť pak i mezi snopy sbírala, nezbraňujte jí.'),
(1553356,54,8,2,16,'Nýbrž naschvál jí upouštějte z snopů a nechávejte, ať sbírá, a nedomlouvejte jí.'),
(1553357,54,8,2,17,'Sbírala tedy na poli tom až do večera, a což sebrala, to vymlátila; i byla téměř míra efi ječmene.'),
(1553358,54,8,2,18,'Kterýž vzavši, přišla do města, a viděla svegruše její to, což nasbírala. Vyňala také a dala jí to, což pozůstalo po nasycení jejím.'),
(1553359,54,8,2,19,'I řekla jí svegruše její: Kdes sbírala dnes, a kdes pracovala? Budiž požehnaný ten, kterýž tě přijal. Tedy oznámila svegruši své, u koho pracovala, řkuci: Jméno muže, u kteréhož jsem pracovala dnes, jest Bóz.'),
(1553360,54,8,2,20,'I řekla Noémi nevěstě své: Požehnanýť jest od Hospodina, že nepřestal milosrdenství svého nad živými i mrtvými. I to ještě k ní řekla Noémi: Blízký přítel náš a z příbuzných našich jest muž ten.'),
(1553361,54,8,2,21,'Řekla jí také Rut Moábská: I to mi ještě řekl: Čeládky mé přídrž se, dokavadž by všeho, což mého jest, nedožali.'),
(1553362,54,8,2,22,'Tedy řekla Noémi Rut nevěstě své: Dobré jest tedy, dcero má, abys vycházela s děvečkami jeho, ať by na jiném poli něco nepřekazili.'),
(1553363,54,8,2,23,'A tak se přídržela Rut děvek Bózových, a sbírala klasy, dokudž nesžali ječmene a pšenice, a bydlela u svegruše své.'),
(1553364,54,8,3,1,'Řekla jí potom Noémi svegruše její: Má dcero, nemám-liž pohledati tobě odpočinutí, aby tobě dobře bylo?'),
(1553365,54,8,3,2,'Anobrž zdaliž Bóz ten příbuzný náš, s jehož jsi děvečkami byla, nebude víti ječmene na humně noci této?'),
(1553366,54,8,3,3,'Protož umej se a pomaž, roucho své také oblec, a jdi na humno, však tak, aby nebylo známé muži tomu, prvé než by přestal jísti a píti.'),
(1553367,54,8,3,4,'A když půjde ležeti, znamenej místo, na kterémž lehne, a přijduc, pozdvihneš pláště u noh jeho, a tu se položíš; on pak oznámí tobě, co bys měla činiti.'),
(1553368,54,8,3,5,'Jížto Rut řekla: Cokoli mi rozkážeš, učiním.'),
(1553369,54,8,3,6,'Šla tedy na to humno, a učinila všecko, což jí rozkázala svegruše její.'),
(1553370,54,8,3,7,'Když pak pojedl Bóz a napil se, a rozveselilo se srdce jeho, šel spáti vedlé stohu; přišla i ona tiše, a pozdvihši pláště u noh jeho, položila se.'),
(1553371,54,8,3,8,'A když bylo o půl noci, ulekl se muž ten a zchopil se, a aj, žena leží u noh jeho.'),
(1553372,54,8,3,9,'I řekl: Kdo jsi ty? A ona odpověděla: Já jsem Rut, děvka tvá. Vztáhni křídlo pláště svého na děvku svou, nebo příbuzný jsi.'),
(1553373,54,8,3,10,'A on řekl: Požehnaná jsi ty od Hospodina, dcero má. Větší jsi nyní pobožnosti dokázala, nežli prvé, že jsi nehledala mládenců bohatých aneb chudých.'),
(1553374,54,8,3,11,'Protož nyní, dcero má, neboj se; vše, čehož žádáš, učiním tobě, nebo víť všecko město lidu mého, že jsi ty žena šlechetná.'),
(1553375,54,8,3,12,'A také jest to pravé, že jsem příbuzný tvůj, ale jestiť příbuzný bližší nežli já.'),
(1553376,54,8,3,13,'Odpočiniž tu přes noc, a když bude ráno, jestližeť on bude chtíti práva příbuznosti k tobě užiti, dobře, nechť užive. Pakliť nebude chtíti práva užiti k tobě, já právem příbuznosti pojmu tebe, živť jest Hospodin. Spiž tu až do jitra.'),
(1553377,54,8,3,14,'A tak spala u noh jeho až do jitra. Potom vstala prvé, nežli by kdo poznati mohl bližního svého; nebo pečoval Bóz, aby někdo nezvěděl, že přišla žena ta na humno.'),
(1553378,54,8,3,15,'A řekl: Přines loktušku, kterouž se odíváš, a drž ji. A když ji držela, naměřiv jí šest měr ječmene, vložil na ni. I vešla do města.'),
(1553379,54,8,3,16,'A přišla k svegruši své. Kteráž řekla: Kdo jsi ty, dcero má? I vypravovala jí všecko, což jí učinil muž ten.'),
(1553380,54,8,3,17,'A řekla: Šest měr těchto ječmene dal mi, nebo řekl ke mně: Nenavrátíš se prázdná k svegruši své.'),
(1553381,54,8,3,18,'I řekla jí Noémi: Počekej, dcero má, až porozumíš, jak to padne; neboť neobleví muž ten, až tu věc dnes k místu přivede.'),
(1553382,54,8,4,1,'Tedy Bóz všed do brány, posadil se tam. A aj, příbuzný ten, o němž on byl mluvil, šel tudy. I řekl jemu: Poď sem, a poseď tuto. Kterýž zastaviv se, sedl.'),
(1553383,54,8,4,2,'A vzav Bóz deset mužů z starších města toho, řekl: Posaďte se tuto. I posadili se.'),
(1553384,54,8,4,3,'Tedy řekl příbuznému tomu: Díl pole, kteréž bylo bratra našeho Elimelecha, prodala Noémi, kteráž se navrátila z krajiny Moábské.'),
(1553385,54,8,4,4,'A já jsem umínil netajiti toho před tebou, a pravímť: Ujmi pole to před přísedícími těmito a staršími lidu mého. Jestliže chceš koupiti, kup; pakli nekoupíš, oznam mi. Nebo vím, že kromě tebe není žádného, kterýž by měl právo koupiti je, a já jsem po tobě. Tedy on řekl: Já koupím.'),
(1553386,54,8,4,5,'I řekl Bóz: Když ujmeš pole to od Noémi, tedy i Rut Moábskou, manželku mrtvého, sobě pojmeš, abys vzbudil jméno mrtvého v dědictví jeho.'),
(1553387,54,8,4,6,'Odpověděl příbuzný ten: Nemohuť koupiti, abych snad nezahladil dědictví svého. Uživ ty práva příbuznosti mé, nebo já ho nemohu užiti.'),
(1553388,54,8,4,7,'(Byl pak ten obyčej od starodávna v Izraeli při koupi a směnách, ku potvrzení všelijakého jednání, že szul jeden obuv svou, a dal ji druhému. A to bylo na svědectví té věci v Izraeli.)'),
(1553389,54,8,4,8,'Protož řekl příbuzný Bózovi: Ujmi ty. I szul obuv svou.'),
(1553390,54,8,4,9,'Tedy řekl Bóz starším těm a všemu lidu: Vy svědkové jste dnes, že jsem ujal všecko, což bylo Elimelechovo, i všecko to, což bylo Chelionovo a Mahalonovo, od Noémi.'),
(1553391,54,8,4,10,'Ano i Rut Moábskou, ženu Mahalonovu, vzal jsem sobě za manželku, abych vzbudil jméno mrtvého v dědictví jeho, a aby nebylo zahlazeno jméno mrtvého z bratří jeho, a z brány místa jeho. Vy svědkové jste dnes toho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553392,54,8,4,11,'I řekl všecken lid, kterýž byl v bráně města, i starší: Svědkové jsme. Dejž Hospodin, aby žena vcházející do domu tvého byla jako Ráchel a jako Lía, kteréžto dvě vzdělaly dům Izraelský. Počínejž sobě zmužile v Efratě, a dosáhni jména v Betlémě.'),
(1553393,54,8,4,12,'A ať jest dům tvůj jako dům Fáresa, (kteréhož porodila Támar Judovi,) z semene toho, kteréž by dal tobě Hospodin s mladicí touto.'),
(1553394,54,8,4,13,'A tak Bóz pojal sobě Rut, a byla manželkou jeho. A když všel k ní, dal jí to Hospodin, že počala a porodila syna.'),
(1553395,54,8,4,14,'I řekly ženy Noémi: Požehnaný Hospodin, kterýž nedopustil toho, abys měla zbavena býti příbuzného v tento čas, tak aby trvalo v Izraeli jméno jeho.'),
(1553396,54,8,4,15,'Onť očerství duši tvou, a chovati tě bude v starosti tvé; nebo nevěsta tvá, kteráž tě miluje, porodila ho, kteráž tobě lepší jest, nežli sedm synů.'),
(1553397,54,8,4,16,'Tedy vzavši Noémi dítě, položila je na klín svůj, a byla pěstounkou jeho.'),
(1553398,54,8,4,17,'Daly mu pak jméno sousedy, kteréž pravily: Narodil se syn Noémi, a nazvaly ho jménem Obéd. Onť jest otec Izai, otce Davidova.'),
(1553399,54,8,4,18,'A tito jsou rodové Fáresovi: Fáres zplodil Ezrona;'),
(1553400,54,8,4,19,'Ezron pak zplodil Rama, Ram pak zplodil Aminadaba;'),
(1553401,54,8,4,20,'Aminadab pak zplodil Názona, Názon pak zplodil Salmona;'),
(1553402,54,8,4,21,'Salmon pak zplodil Bóza, Bóz pak zplodil Obéda;'),
(1553403,54,8,4,22,'Obéd pak zplodil Izai, Izai pak zplodil Davida.'),
(1553404,54,9,1,1,'Byl muž nějaký z Ramataim Zofim, s hory Efraim, jehož jméno bylo Elkána, syn Jerochama, syna Elihu, syna Tohu, syna Zuf Efratejského.'),
(1553405,54,9,1,2,'A ten měl dvě ženy, jméno jedné Anna, a jméno druhé Penenna. Měla pak Penenna děti, ale Anna neměla dětí.'),
(1553406,54,9,1,3,'I chodíval muž ten z města svého každého roku, aby se klaněl a obětoval Hospodinu zástupů, do Sílo, kdež byli dva synové Elí, Ofni a Fínes, kněží Hospodinovi.'),
(1553407,54,9,1,4,'Když pak přišel den, v němž obětoval Elkána, dal Penenně manželce své, a všechněm synům i dcerám jejím díly.'),
(1553408,54,9,1,5,'Anně pak dal díl jeden výborný, nebo Annu miloval, ale Hospodin zavřel byl život její.'),
(1553409,54,9,1,6,'Přesto kormoutila ji také velmi protivnice její, toliko aby ji popouzela, proto že Hospodin zavřel byl život její.'),
(1553410,54,9,1,7,'To když činíval každého roku, a Anna též chodívala do domu Hospodinova, tak ji kormoutívala protivnice; ona pak plakávala a nic nejídala.'),
(1553411,54,9,1,8,'Tedy řekl jí Elkána muž její: Anna, proč pláčeš? A proč nejíš? Proč tak truchlí srdce tvé? Zdaliž já nejsem tobě lepší nežli deset synů?'),
(1553412,54,9,1,9,'Vstala tedy Anna, když pojedli v Sílo a napili se; a Elí kněz seděl na stolici u veřeje chrámu Hospodinova.'),
(1553413,54,9,1,10,'Ona pak jsuci v hořkosti srdce, modlila se Hospodinu a plakala velmi.'),
(1553414,54,9,1,11,'A učinila slib, řkuci: Hospodine zástupů, jestliže vzhlédneš na trápení děvky své a rozpomeneš se na mne, a nezapomeneš na děvku svou, ale dáš služebnici své plod pohlaví mužského: tedy dám jej tobě, Hospodine, po všecky dny života jeho, a břitva nevejde na hlavu jeho.'),
(1553415,54,9,1,12,'I stalo se, když se dlouho modlila před Hospodinem, že Elí pozor měl na ústa její.'),
(1553416,54,9,1,13,'Ale Anna mluvila v srdci svém; toliko rtové její se hýbali, hlasu pak jejího nebylo slyšeti. I domníval se Elí, že by opilá byla.'),
(1553417,54,9,1,14,'Protož řekl jí Elí: Dlouho-liž budeš opilá? Vystřízvěj z vína svého.'),
(1553418,54,9,1,15,'Odpověděla Anna, řkuci: Nikoli, pane můj, žena jsem ducha truchlivého, ani vína ani nápoje opojného jsem nepila, ale vylila jsem duši svou před Hospodinem.'),
(1553419,54,9,1,16,'Nepřirovnávejž děvky své k ženě bezbožné, nebo z velikého myšlení a hořkosti své mluvila jsem až dosavad.'),
(1553420,54,9,1,17,'Jíž odpověděl Elí, řka: Jdiž u pokoji, a Bůh Izraelský dejž tobě k prosbě tvé, zač jsi ho prosila.'),
(1553421,54,9,1,18,'I řekla: Ó by nalezla děvka tvá milost před očima tvýma! Tedy odšedši žena cestou svou, pojedla, a tvář její nebyla více smutná.'),
(1553422,54,9,1,19,'I vstali velmi ráno, a poklonu učinivše před Hospodinem, navrátili se, a přišli do domu svého do Ramata. Poznal pak Elkána Annu manželku svou, a Hospodin rozpomenul se na ni.'),
(1553423,54,9,1,20,'I stalo se po vyplnění dnů, jakž počala Anna, že porodila syna, a nazvala jméno jeho Samuel; nebo řekla: Vyprosila jsem ho na Hospodinu.'),
(1553424,54,9,1,21,'Šel pak muž ten Elkána se vší čeledí svou, aby obětoval Hospodinu obět výroční a slib svůj.'),
(1553425,54,9,1,22,'Ale Anna nešla, nebo řekla muži svému: Až odchovám dítě, tehdy povedu je, aby ukáže se před Hospodinem, zůstalo tam na věky.'),
(1553426,54,9,1,23,'I řekl jí Elkána muž její: Učiň, cožť se dobrého vidí, zůstaň, dokudž neodchováš jeho. Ó by toliko utvrdil Hospodin slovo své! A tak zůstala žena, a krmila syna svého, až jej i odchovala.'),
(1553427,54,9,1,24,'Potom, když ho odchovala, vedla jej s sebou, se třmi volky a jednou efi mouky a nádobou vína, i uvedla jej do domu Hospodinova v Sílo; dítě pak ještě bylo malé.'),
(1553428,54,9,1,25,'Tedy zabili volka a přivedli dítě k Elí.'),
(1553429,54,9,1,26,'Ona pak řekla: Poslyš mne, pane můj. Jako jest živa duše tvá, pane můj, já jsem žena ta, kteráž jsem stála tuto s tebou, modleci se Hospodinu.'),
(1553430,54,9,1,27,'Za toto dítě jsem prosila, a dal mi Hospodin k prosbě mé to, čehož jsem prosila od něho.'),
(1553431,54,9,1,28,'Protož já také oddávám jej Hospodinu; po všecky dny, v nichž živ bude, oddanýť jest Hospodinu. A učinil tu poklonu Hospodinu.'),
(1553432,54,9,2,1,'I modlila se Anna a řekla: Zplésalo srdce mé v Hospodinu, a vyzdvižen jest roh můj v Hospodinu; rozšířila se ústa má proti nepřátelům mým, nebo rozveselila jsem se v spasení tvém.'),
(1553433,54,9,2,2,'Neníť žádný tak svatý jako Hospodin; nýbrž žádného není kromě tebe, neníť žádný tak silný jako Bůh náš.'),
(1553434,54,9,2,3,'Nemluvtež již více hrdě, a nevycházej z úst vašich slovo pyšné; nebo Bůh silný vševědoucí jest Hospodin, a usilování jeho jemu nepochybují.'),
(1553435,54,9,2,4,'Lučiště i silní potříni jsou, a mdlí opásáni jsou silou.'),
(1553436,54,9,2,5,'Sytí z chleba jednají se k dílu, a hladovití přestali lačněti, tak že neplodná porodila sedmero, a kteráž mnoho dětí měla, zemdlena jest.'),
(1553437,54,9,2,6,'Hospodin umrtvuje i obživuje, uvodí do pekla i vyvodí.'),
(1553438,54,9,2,7,'Hospodin ochuzuje i zbohacuje, ponižuje i povyšuje.'),
(1553439,54,9,2,8,'Nuzného vyzdvihuje z prachu, a z hnoje vyvyšuje chudého, aby je posadil s knížaty, a stolici slávy dědičně jim dal; nebo Hospodinovy jsou stěžeje země, na nichž založil okršlek.'),
(1553440,54,9,2,9,'Onť ostříhá noh svatých svých, ale bezbožní ve tmě umlknou; nebo ne v síle záleží síla člověka.'),
(1553441,54,9,2,10,'Kteříž se protiví Hospodinu, setříni budou, na takové s nebe hřímati bude. Hospodin souditi bude končiny země, a dá sílu králi svému, a vyvýší roh pomazaného svého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553442,54,9,2,11,'I navrátil se Elkána do Ramaty, do domu svého, a pacholátko přisluhovalo Hospodinu při knězi Elí.'),
(1553443,54,9,2,12,'Synové pak Elí byli bezbožní, a neznali Hospodina.'),
(1553444,54,9,2,13,'Nebo těch kněží obyčej při lidu byl: Kdokoli obětoval obět, přicházel kněžský mládenec, když se maso vařilo, maje v ruce své hák třízubý,'),
(1553445,54,9,2,14,'A vrazil jej do nádoby neb do kotlíku, neb do pánve, aneb do hrnce, a cokoli zachytil hák, to sobě bral kněz. Tak činívali všemu lidu Izraelskému, kteříž tam přicházeli do Sílo.'),
(1553446,54,9,2,15,'Nýbrž, prvé než tuk zapalovali, přicházel mládenec kněžský a říkal člověku, kterýž obětoval: Dej masa, ať upeku knězi, nebo nevezme od tebe masa vařeného, ale surové.'),
(1553447,54,9,2,16,'Jemuž odpověděl-li člověk ten: Nechť jest prvé zapálen tuk, a potom vezmeš sobě, čehož žádá duše tvá, on říkal: Nikoli, ale dej hned; jestliže pak nedáš, mocí vezmu.'),
(1553448,54,9,2,17,'I byl to hřích mládenců těch před Hospodinem velmi veliký; nebo pohrdali lidé obětmi Hospodinovými.'),
(1553449,54,9,2,18,'Samuel pak přisluhoval před Hospodinem, mládenček, oděný jsa efodem lněným.'),
(1553450,54,9,2,19,'A matka jeho dělávala mu sukničku malou, a přinášela jemu každého roku, když přicházela s mužem svým k obětování oběti výroční.'),
(1553451,54,9,2,20,'I požehnal Elí Elkánovi a manželce jeho, řka: Dejž tobě Hospodin símě z ženy této za oddaného, kteréhož jsi vyžádal na Hospodinu. I odešli na místo své.'),
(1553452,54,9,2,21,'Tedy navštívil Hospodin Annu, kteráž počala a porodila tři syny a dvě dcery. Ale mládenček Samuel rostl před Hospodinem.'),
(1553453,54,9,2,22,'Elí pak byl starý velmi a slyšel všecky věci, kteréž činili synové jeho všemu Izraeli, a kterak obývali s ženami, kteréž přisluhovaly u dveří stánku úmluvy.'),
(1553454,54,9,2,23,'I řekl jim: Proč činíte takové věci? Nebo já slyším zlé slovo o vás ode všeho lidu tohoto.'),
(1553455,54,9,2,24,'Nikoli, synové moji, neboť není dobrá pověst, kterouž já slyším, že odvracíte lid Hospodinův.'),
(1553456,54,9,2,25,'Zhřeší-li člověk proti člověku, souditi ho bude soudce; pakli kdo zhřeší proti Hospodinu, kdo se zasadí o něho? Ale neuposlechli hlasu otce svého, nebo je chtěl zbíti Hospodin.'),
(1553457,54,9,2,26,'Ale mládenček Samuel prospíval a rostl, a milý byl, jakož před Hospodinem, tak i před lidmi.'),
(1553458,54,9,2,27,'I přišel muž Boží k Elí a řekl jemu: Takto praví Hospodin: Zdaliž jsem se patrně nezjevil domu otce tvého, když byli v Egyptě, v domě Faraonově?'),
(1553459,54,9,2,28,'A vyvolil jsem ho sobě ze všech pokolení Izraelských za kněze, aby obětoval na oltáři mém, a aby kadil vonnými věcmi a nosil efod přede mnou; dal jsem také domu otce tvého všecky ohnivé oběti synů Izraelských.'),
(1553460,54,9,2,29,'Proč pošlapáváte obět mou, i suchou obět mou, kterouž jsem přikázal v příbytku tomto? A víces ctil syny své nežli mne, abyste tyli prvotinami všech obětí suchých Izraele lidu mého.'),
(1553461,54,9,2,30,'Protož praví Hospodin Bůh Izraelský: Řeklť jsem byl zajisté, dům tvůj a dům otce tvého přisluhovati měl přede mnou až na věky, ale nyní praví Hospodin: Odstup to ode mne; nebo těch, kteříž mne ctí, poctím, kteříž pak mnou pohrdají, v pohrdání přijdou.'),
(1553462,54,9,2,31,'Aj, dnové přicházejí, že odetnu rámě tvé a rámě domu otce tvého, aby nebylo starce v domě tvém.'),
(1553463,54,9,2,32,'A viděti budeš protivníka v příbytku Páně, ve všem, čehož Bůh štědře udíleti bude Izraelovi, aniž bude starce v domě tvém po všecky dny.'),
(1553464,54,9,2,33,'A ačkoli nevyhladím do konce muže od oltáře svého, abych trápil oči tvé a bolestí ssužoval duši tvou, všecko však množství domu tvého zemrou v věku vyspělém.'),
(1553465,54,9,2,34,'A to měj za znamení, což přijde na dva syny tvé, Ofni a Fínesa: oba jednoho dne umrou.'),
(1553466,54,9,2,35,'Vzbudím pak sobě kněze věrného, kterýž vedlé srdce mého a vedlé duše mé vše konati bude, a vzdělám jemu dům stálý, aby přisluhoval před pomazaným mým po všecky dny.'),
(1553467,54,9,2,36,'A budeť, že kdožkoli pozůstane z domu tvého, přijde, aby se poklonil jemu, pro peníz stříbrný a pro skyvu chleba, a řekne: Připusť mne, prosím, k jedné třídě kněžské, abych jedl chléb.'),
(1553468,54,9,3,1,'Mládenček pak Samuel přisluhoval Hospodinu při Elí, a řeč Hospodinova byla vzácná v těch dnech, aniž bývalo vidění zjevného.'),
(1553469,54,9,3,2,'Stalo se pak jednoho dne, když Elí ležel na místě svém, (a již byl počal scházeti na oči, a nemohl viděti),'),
(1553470,54,9,3,3,'Samuel také spal, a světlo Boží ještě zhašeno nebylo v chrámě Hospodinově, v němž byla truhla Boží,'),
(1553471,54,9,3,4,'Že zavolal Hospodin Samuele. Kterýž řekl: Teď jsem.'),
(1553472,54,9,3,5,'I běžel k Elí a řekl: Teď jsem, nebo jsi mne volal. I odpověděl: Nevolal jsem, jdi zase spáti. Kterýž odšed, spal.'),
(1553473,54,9,3,6,'Opět pak Hospodin zavolal Samuele. A vstav Samuel, šel k Elí a řekl: Teď jsem, nebo jsi mne volal. I odpověděl: Nevolalť jsem, synu můj; jdi zase, spi.'),
(1553474,54,9,3,7,'Samuel pak ještě neznal Hospodina, a ještě nebyla mu zjevena řeč Hospodinova.'),
(1553475,54,9,3,8,'Tedy opět Hospodin zavolal Samuele po třetí. Kterýžto vstav, šel k Elí a řekl: Teď jsem, nebo jsi mne volal. Tedy srozuměl Elí, že byl Hospodin volal mládence.'),
(1553476,54,9,3,9,'I řekl Elí k Samuelovi: Jdi, spi, a bude-li tě volati, řekneš: Mluv, Hospodine, nebo slyší služebník tvůj. Odšel tedy Samuel, a spal na místě svém.'),
(1553477,54,9,3,10,'I přišel Hospodin, a stál a zavolal, jako i prvé, a řekl: Samueli, Samueli! Odpověděl Samuel: Mluv, nebo slyší služebník tvůj.'),
(1553478,54,9,3,11,'I řekl Hospodin Samuelovi: Aj, já učiním věc takovou v Izraeli, kterouž kdokoli uslyší, zníti jemu bude v obou uších jeho.'),
(1553479,54,9,3,12,'V ten den uvedu na Elí všecko to, což jsem mluvil proti domu jeho; počnuť i dokonám.'),
(1553480,54,9,3,13,'A ukáži jemu, že já soudím dům jeho až na věky pro nepravost, o níž věděl; nebo znaje, že na se zlořečenství uvodí synové jeho, a však nezbránil jim.'),
(1553481,54,9,3,14,'A protož jsem zapřisáhl domu Elí, že nebude vyčištěna nepravost domu Elí žádnou obětí, ani obětí suchou až na věky.'),
(1553482,54,9,3,15,'I spal Samuel až do jitra, a otevřel dvéře domu Hospodinova; ostýchal se pak Samuel oznámiti Elí toho vidění.'),
(1553483,54,9,3,16,'Tedy povolal Elí Samuele a řekl: Samueli, synu můj. Kterýž odpověděl: Teď jsem.'),
(1553484,54,9,3,17,'I řekl: Jaká jest to řeč, kterouž mluvil tobě? Netaj medle přede mnou. Toto učiň tobě Bůh a toto přidej, jestliže co zatajíš přede mnou ze všech slov, kteráž mluvil tobě.'),
(1553485,54,9,3,18,'A tak oznámil jemu Samuel všecka slova, a ničeho nezatajil před ním. A on řekl: Hospodinť jest, nechť učiní, což ráčí.'),
(1553486,54,9,3,19,'Rostl pak Samuel, a Hospodin byl s ním, tak že nedopustil padnouti žádnému slovu jeho na zem.'),
(1553487,54,9,3,20,'Z čehož poznal všecken Izrael od Dan až do Bersabé, že Samuel jest věrný prorok Hospodinův.'),
(1553488,54,9,3,21,'Nebo se jemu i potom ukazoval Hospodin v Sílo, jakož se byl prvé zjevil Hospodin Samuelovi v Sílo, skrze řeč Hospodinovu.'),
(1553489,54,9,4,1,'I stalo se vedlé řeči Samuelovy všemu lidu Izraelskému. Nebo když vytáhl Izrael proti Filistinským k boji, a položili se při Eben-Ezer, Filistinští pak položili se v Afeku;'),
(1553490,54,9,4,2,'A když se sšikovali Filistinští proti Izraelovi, a již se potýkali: poražen jest Izrael od Filistinských, tak že jich zbito v té bitvě na poli takměř čtyři tisíce mužů.'),
(1553491,54,9,4,3,'I navrátil se lid do stanů, a řekli starší Izraelští: Proč nás dnes Hospodin porazil před Filistinskými? Vezměme k sobě z Sílo truhlu smlouvy Hospodinovy, ať přijde mezi nás, a vysvobodí nás z rukou nepřátel našich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553492,54,9,4,4,'Poslal tedy lid do Sílo, a vzali odtud truhlu smlouvy Hospodina zástupů, sedícího na cherubínech. Byli také tam dva synové Elí s truhlou smlouvy Boží, Ofni a Fínes.'),
(1553493,54,9,4,5,'Když pak přinesena byla truhla smlouvy Hospodinovy do vojska, zkřikl všecken Izrael s velikým plésáním, až země vzněla.'),
(1553494,54,9,4,6,'Uslyševše pak Filistinští hluk plésání, řekli: Jaký jest to hlas výskání velikého tohoto v vojště Hebrejském? I poznali, že truhla Hospodinova přišla do vojska.'),
(1553495,54,9,4,7,'Protož báli se Filistinští, když praveno bylo: Přišel Bůh do vojska jejich; a řekli: Běda nám, nebo nebylo prvé nic k tomu podobného.'),
(1553496,54,9,4,8,'Běda nám! Kdo nás vysvobodí z ruky těch bohů silných? Tiť jsou bohové, kteříž zbili Egypt všelikou ranou i na poušti.'),
(1553497,54,9,4,9,'Posilňte se a buďte muži, ó Filistinští, abyste nesloužili těm Hebrejským, jako oni sloužili vám; buďtež tedy muži a bojujte.'),
(1553498,54,9,4,10,'Bojovali tedy Filistinští, a poražen jest Izrael, a utíkali jeden každý do stanu svého. I byla ta porážka veliká velmi, nebo padlo z Izraele třidceti tisíc pěších;'),
(1553499,54,9,4,11,'Také truhla Boží vzata, a dva synové Elí zabiti, Ofni a Fínes.'),
(1553500,54,9,4,12,'Běže pak jeden Beniaminský z bitvy, přišel do Sílo téhož dne, maje roucho roztržené a hlavu prstí posypanou.'),
(1553501,54,9,4,13,'Přišel tedy, a aj, Elí seděl na stolici při cestě, hledě, nebo srdce jeho lekalo se za truhlu Boží; a když všel muž ten, a oznámil v městě, kvílilo všecko město.'),
(1553502,54,9,4,14,'A uslyšev Elí hlas křiku toho, řekl: Jaký jest to hlas hřmotu tohoto? Muž pak ten pospíchaje, přiběhl, aby oznámil Elí.'),
(1553503,54,9,4,15,'(A byl Elí v devadesáti a osmi letech; oči také jeho byly již pošly, a nemohl viděti.)'),
(1553504,54,9,4,16,'I řekl muž ten k Elí: Já jdu z bitvy, z bitvy zajisté utekl jsem dnes. I dí jemu on: Co se tam stalo, můj synu?'),
(1553505,54,9,4,17,'Odpověděl ten posel a řekl: Utekl Izrael před Filistinskými, také i porážka veliká stala se v lidu, ano i oba synové tvoji zabiti jsou, Ofni a Fínes, a truhla Boží jest vzata.'),
(1553506,54,9,4,18,'I stalo se, že jakž jmenoval truhlu Boží, spadl Elí s stolice nazpět při úhlu brány, a tak zlomiv šíji, umřel; nebo byl muž starý a těžký. On soudil Izraele čtyřidceti let.'),
(1553507,54,9,4,19,'Nevěsta pak jeho, manželka Fínesova, jsuc těhotná a blízká porodu, uslyševši také tu pověst, že by truhla Boží vzata byla, a že umřel tchán její i muž její, sklonila se a porodila; nebo se obořily na ni úzkosti její.'),
(1553508,54,9,4,20,'A v ten čas, když ona umírala, řekly, kteréž stály při ní: Neboj se, však jsi porodila syna. Kteráž nic neodpověděla, aniž toho připustila k srdci svému.'),
(1553509,54,9,4,21,'I nazvala dítě Ichabod, řkuci: Přestěhovala se sláva z Izraele; proto že vzata byla truhla Boží, a umřel tchán i muž její.'),
(1553510,54,9,4,22,'Protož řekla: Přestěhovala se sláva z Izraele, nebo vzata jest truhla Boží.'),
(1553511,54,9,5,1,'Filistinští pak vzali truhlu Boží, a zanesli ji z Eben-Ezer do Azotu.'),
(1553512,54,9,5,2,'Vzali tedy Filistinští truhlu Boží, a vnesli ji do domu modly Dágon, a postavili ji vedlé Dágona.'),
(1553513,54,9,5,3,'A když Azotští na zejtří ráno vstali, aj, Dágon povalený ležel tváří svou na zemi před truhlou Hospodinovou. I vzali Dágona a postavili jej na místo jeho.'),
(1553514,54,9,5,4,'A když opět ráno nazejtří vstali, aj, Dágon, jakž upadl, ležel tváří svou na zemi před truhlou Hospodinovou; hlava pak Dágonova a obě dlaně rukou jeho odražené byly na prahu, jen ho špalek zůstal.'),
(1553515,54,9,5,5,'Protož kněží Dágonovi a všickni, kteříž vcházejí do domu Dágonova, nešlapají na prah Dágonův v Azotu až do tohoto dne.'),
(1553516,54,9,5,6,'Tedy ztížena jest ruka Hospodinova nad Azotskými, a pohubila je, (nebo ranila je neduhy na zadku), Azot i končiny jeho.'),
(1553517,54,9,5,7,'Vidouce pak muži Azotští, co se děje, řekli: Nechť nezůstává truhla Boha Izraelského u nás, nebo těžká jest ruka jeho proti nám, a proti Dágonovi bohu našemu.'),
(1553518,54,9,5,8,'I obeslali a shromáždili všecka knížata Filistinská k sobě, a řekli: Co učiníme s truhlou Boha Izraelského? Odpověděli: Nechť jest doprovozena do Gát truhla Boha Izraelského. I zprovodili tam truhlu Boha Izraelského.'),
(1553519,54,9,5,9,'Stalo se pak, když ji vyprovázeli, že ruka Hospodinova přikročila k městu trápením velikým velmi, a ranila muže města od malého až do velikého, a nametalo se jim v tajných místech plno vředů.'),
(1553520,54,9,5,10,'Z té příčiny poslali truhlu Boží do Akaron. A když přišla truhla Boží do Akaron, zkřikli Akaronští, řkouce: Zprovodili k nám truhlu Boha Izraelského, aby nás pomořili i náš lid.'),
(1553521,54,9,5,11,'Protož poslavše, shromáždili všecka knížata Filistinská, a řekli: Odešlete truhlu Boha Izraelského, ať se navrátí na místo své, a nezmoří nás i lidu našeho. Nebo bylo trápení smrtelné po všem tom městě, a velmi těžká byla ruka Boží tam.'),
(1553522,54,9,5,12,'Muži pak, kteříž nezemřeli, raněni byli neduhy na zadku, tak že křik města vstupoval až k nebi.'),
(1553523,54,9,6,1,'Byla pak truhla Hospodinova v krajině Filistinské za sedm měsíců.'),
(1553524,54,9,6,2,'Tedy Filistinští povolavše kněží a hadačů, řekli: Co učiníme s truhlou Hospodinovou? Oznamte nám, kterak bychom ji odeslali na místo její?'),
(1553525,54,9,6,3,'Kteříž odpověděli: Jestliže odešlete truhlu Boha Izraelského, neodsílejte jí prázdné, ale všelijak dejte jí obět za provinění; tehdy uzdraveni budete, a poznáte, proč ruka jeho neodešla od vás.'),
(1553526,54,9,6,4,'I řekli: Jakáž jest to obět za hřích, kterouž jí dáti máme? Odpověděli: Vedlé počtu knížat Filistinských pět zadků zlatých a pět myší zlatých; nebo rána jednostejná jest na všechněch, i na knížatech vašich.'),
(1553527,54,9,6,5,'Uděláte tedy podobenství zadků svých a podobenství myší svých, kteréž pokazily zemi, i dáte slávu Bohu Izraelskému; snad pozlehčí ruky své nad vámi, i nad bohy vašimi a nad zemí vaší.'),
(1553528,54,9,6,6,'A proč obtěžujete srdce svá, jako jsou obtížili Egyptští a Farao srdce své? Zdaliž, když divné věci prokázal při nich, nepropustili jich, a oni odešli?'),
(1553529,54,9,6,7,'A protož udělejte vůz nový jeden a vezměte dvě krávy otelené, na kteréž jha nebylo vzkládáno, a zapřáhněte ty krávy do vozu, a zavřete telata jejich doma, aby za nimi nešla.'),
(1553530,54,9,6,8,'A vezmouce truhlu Hospodinovu, vstavte ji na vůz; nádoby pak zlaté, kteréž jste dali jí za provinění, položte v škřiňce po boku jejím, a propusťte ji, ať odejde.'),
(1553531,54,9,6,9,'A šetřte: Jestližeť cestou k cíli svému půjde do Betsemes, onť jest nám způsobil všecko toto zlé přenáramné; pakli nic, poznáme, že ne ruka jeho dotkla se nás, ale náhodou nám to přišlo.'),
(1553532,54,9,6,10,'Učinili tedy ti muži tak, a vzavše dvě krávy otelené, zapřáhli je do toho vozu, a telata jejich zavřeli doma.'),
(1553533,54,9,6,11,'A vstavili truhlu Hospodinovu na vůz, i škřiňku i myši zlaté, a podobizny zadků svých.'),
(1553534,54,9,6,12,'I šly upřímo krávy cestou, kteráž vede do Betsemes, silnicí jednou předce jdouce a řičíce, aniž se uchýlily na pravo aneb na levo. Knížata také Filistinská šla za nimi až ku pomezí Betsemes.'),
(1553535,54,9,6,13,'Betsemští pak žali tehdáž pšenici v údolí, a pozdvihše očí svých, uzřeli truhlu; i veselili se, vidouce ji.'),
(1553536,54,9,6,14,'A když přijel vůz na pole Jozue Betsemského, tu se zastavil. I byl tu kámen veliký. Tedy zsekavše dříví vozu toho i ty krávy, obětovali je v obět zápalnou Hospodinu.'),
(1553537,54,9,6,15,'Levítové pak složili truhlu Hospodinovu i škřiňku, kteráž byla při ní, v níž byly nádoby zlaté, a postavili na ten kámen veliký. Muži pak Betsemští dodávali obětí zápalných, a obětovali oběti v ten den Hospodinu.'),
(1553538,54,9,6,16,'Což viděvše knížata Filistinská, navrátili se do Akaron téhož dne.'),
(1553539,54,9,6,17,'Tito jsou pak zadkové zlatí, kteréž dali Filistinští za své provinění Hospodinu, za Azot jeden, za Gázu jeden, za Aškalon jeden, za Gát jeden, za Akaron jeden.'),
(1553540,54,9,6,18,'Myši také zlaté, vedlé počtu všech měst Filistinských, za patero knížetství, od města hrazeného až do vsi nehrazené, a až k kameni tomu velikému, na němž postavili truhlu Hospodinovu, kterýž jest až do tohoto dne na poli Jozue Betsemského.'),
(1553541,54,9,6,19,'Pobil pak Hospodin z mužů Betsemských, kteříž hleděli do truhly Hospodinovy, pobil, pravím, z lidu padesát tisíců a sedmdesáte mužů. I kvílil lid, proto že učinil Hospodin v lidu porážku velikou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553542,54,9,6,20,'Protož řekli muži Betsemští: Kdož bude moci ostáti před Hospodinem Bohem svatým tímto? A k komu odejde od nás?'),
(1553543,54,9,6,21,'I poslali posly k obyvatelům Kariatjeharim, řkouce: Vrátili zase Filistinští truhlu Hospodinovu; přiďte, vezměte ji k sobě.'),
(1553544,54,9,7,1,'Tedy přišli muži Kariatjeharim a vzali odtud truhlu Hospodinovu, a vnesli ji do domu Abinadabova na pahrbek, a Eleazara syna jeho posvětili, aby ostříhal truhly Hospodinovy.'),
(1553545,54,9,7,2,'Stalo se pak, že od toho času, jakž zůstala truhla v Kariatjeharim, když bylo přeběhlo mnoho dní, a byl již rok dvadcátý, teprv se roztoužil všecken dům Izraelský po Hospodinu.'),
(1553546,54,9,7,3,'Nebo byl mluvil Samuel ke všemu domu Izraelskému, řka: Jestliže celým srdcem svým obracíte se k Hospodinu, odejměte bohy cizí z prostředku sebe i Astarota, a ustavte srdce své při Hospodinu, a služte jemu samému, a vysvobodí vás z ruky Filistinských.'),
(1553547,54,9,7,4,'A tak zavrhli synové Izraelští Bálim i Astarota, a sloužili Hospodinu samému.'),
(1553548,54,9,7,5,'Byl také řekl Samuel: Shromažďte všecken lid Izraelský do Masfa, a modliti se budu za vás Hospodinu.'),
(1553549,54,9,7,6,'I shromáždili se do Masfa, a vážíce vodu, vylévali před Hospodinem, a postíce se v ten den, řekli tam: Zhřešili jsme proti Hospodinu. A soudil Samuel syny Izraelské v Masfa.'),
(1553550,54,9,7,7,'Uslyšavše pak Filistinští, že synové Izraelští shromáždili se do Masfa, vytáhla knížata Filistinská proti Izraelovi. Což když uslyšeli synové Izraelští, báli se příchodu Filistinských.'),
(1553551,54,9,7,8,'Pročež řekli synové Izraelští Samuelovi: Nepřestávej volati za nás k Hospodinu Bohu našemu, aby nás vysvobodil z ruky Filistinských.'),
(1553552,54,9,7,9,'Vzav tedy Samuel beránka jednoho, kterýž ještě ssal, obětoval ho celého v obět zápalnou Hospodinu. I modlil se Samuel Hospodinu za Izraele, a uslyšel jej Hospodin.'),
(1553553,54,9,7,10,'I bylo, že když Samuel obětoval obět zápalnou, Filistinští přiblížili se, aby bojovali proti Izraelovi, ale zahřměl Hospodin hřímáním náramným v ten den nad Filistinskými, a potřel je, i poraženi jsou před tváří Izraele.'),
(1553554,54,9,7,11,'Vytáhše pak muži Izraelští z Masfa, stihali Filistinské, a bili je až pod Betchar.'),
(1553555,54,9,7,12,'Tehdy vzav Samuel kámen jeden, položil jej mezi Masfa a mezi Sen, a nazval jméno jeho Eben-Ezer; nebo řekl: Až potud pomáhal nám Hospodin.'),
(1553556,54,9,7,13,'A tak sníženi jsou Filistinští, a netáhli více na pomezí Izraelské; a byla ruka Hospodinova proti Filistinským po všecky dny Samuelovy.'),
(1553557,54,9,7,14,'Navrácena jsou také města Izraelovi, kteráž byli Filistinští odtrhli od Izraele, počna od Akaron až do Gát; i pomezí jejich vysvobodil Izrael z ruky Filistinských. A byl pokoj mezi Izraelem a Amorejskými.'),
(1553558,54,9,7,15,'I soudil Samuel Izraele po všecky dny života svého.'),
(1553559,54,9,7,16,'A chodě každého roku, obcházel Bethel a Galgala i Masfa, a soudil Izraele na všech těch místech.'),
(1553560,54,9,7,17,'(Potom navracoval se do Ramata, nebo tam byl dům jeho, a tam soudil Izraele.) Tam také vzdělal oltář Hospodinu.'),
(1553561,54,9,8,1,'Když se pak zstaral Samuel, ustanovil syny své za soudce v Izraeli.'),
(1553562,54,9,8,2,'A bylo jméno syna jeho prvorozeného Joel, a jméno druhého Abia; ti byli soudcové v Bersabé.'),
(1553563,54,9,8,3,'Nechodili pak synové jeho po cestách jeho, ale uchýlili se po lakomství, a berouce dary, převraceli soud.'),
(1553564,54,9,8,4,'Shromáždili se tedy všickni starší Izraelští, a přišli k Samuelovi do Ramata.'),
(1553565,54,9,8,5,'A řekli jemu: Aj, tys se již zstaral, a synové tvoji nechodí po cestách tvých; protož nyní ustanov nám krále, aby soudil nás, jakož jest u všech národů.'),
(1553566,54,9,8,6,'I nelíbila se ta řeč Samuelovi, že řekli: Dej nám krále, aby nás soudil. Protož modlil se Samuel Hospodinu.'),
(1553567,54,9,8,7,'Tedy řekl Hospodin Samuelovi: Uposlechni hlasu lidu ve všem, což mluví tobě; nebo ne tebouť jsou pohrdli, ale mnou pohrdli, abych nekraloval nad nimi.'),
(1553568,54,9,8,8,'Podlé všech skutků těch, kteréž činili od onoho dne, v němž jsem je vyvedl z Egypta až do tohoto dne, kdyžto opustili mne, a sloužili bohům cizím, takť oni činí i tobě.'),
(1553569,54,9,8,9,'Protož nyní uposlechni hlasu jejich, a však nejprv osvědč pilně před nimi, a oznam jim obyčej krále, kterýž nad nimi kralovati bude.'),
(1553570,54,9,8,10,'I mluvil Samuel všecky řeči Hospodinovy k lidu, kteříž krále žádali od něho.'),
(1553571,54,9,8,11,'A řekl: Tento bude obyčej krále, kterýž kralovati bude nad vámi: Bráti bude syny vaše, a dá je k vozům svým, a zdělá sobě z nich jezdce, a běhati budou před vozem jeho.'),
(1553572,54,9,8,12,'Také ustanoví je sobě za hejtmany nad tisíci a za padesátníky, a aby jemu orali rolí jeho, a žali obilé jeho, též aby jemu dělali nástroje válečné a přípravy k vozům jeho.'),
(1553573,54,9,8,13,'Dcery také vaše bráti bude, aby dělaly masti, a byly kuchařky a pekařky.'),
(1553574,54,9,8,14,'Nadto pole vaše a vinice vaše, i olivoví vaše nejvýbornější pobéře a rozdá služebníkům svým.'),
(1553575,54,9,8,15,'Také z toho, což vsejete, a z vinic vašich desátky bráti bude, a dá komorníkům a služebníkům svým.'),
(1553576,54,9,8,16,'Též služebníky vaše a děvky vaše, a mládence vaše nejzpůsobnější, i osly vaše vezme, aby jimi dělal dílo své.'),
(1553577,54,9,8,17,'Z stád vašich desátky bráti bude, a vy budete jemu za služebníky.'),
(1553578,54,9,8,18,'I budete volati v ten den příčinou krále vašeho, kteréhož byste sobě vyvolili, a nevyslyší vás Hospodin dne toho.'),
(1553579,54,9,8,19,'Nechtěl však lid uposlechnouti řeči Samuelovy, a řekli: Nikoli, ale král bude nad námi,'),
(1553580,54,9,8,20,'Abychom i my také byli, jako všickni jiní národové, a souditi nás bude král náš, a vycházeje před námi, bojovati bude za nás.'),
(1553581,54,9,8,21,'Vyslyšev tedy Samuel všecka slova lidu, oznámil je Hospodinu.'),
(1553582,54,9,8,22,'I řekl Hospodin Samuelovi: Uposlechni hlasu jejich, a ustanov jim krále. Protož řekl Samuel mužům Izraelským: Jdětež jeden každý do města svého.'),
(1553583,54,9,9,1,'Byl pak muž z pokolení Beniamin, jménem Cis, syn Abiele syna Seror, syna Bechorat, syna Afia, syna muže Jemini, muž udatný.'),
(1553584,54,9,9,2,'Ten měl syna jménem Saule, mládence krásného, tak že žádného z synů Izraelských nebylo pěknějšího nad něj; od ramene svého vzhůru převyšoval všecken lid.'),
(1553585,54,9,9,3,'Byly se pak ztratily oslice Cis, otce Saulova. I řekl Cis Saulovi synu svému: Vezmi i hned s sebou jednoho z služebníků, a vstana, jdi, hledej oslic.'),
(1553586,54,9,9,4,'A tak šel přes horu Efraim, a prošel až do země Salisa, a nic nenalezli; prošli také zemi Sálim, a nic nenalezli. Ještě přešli i zemi Jemini, a nenalezli.'),
(1553587,54,9,9,5,'Když pak přišli do země Zuf, řekl Saul služebníku svému, kterýž byl s ním: Poď, a navraťme se, aby otec můj nechaje těch oslic, neměl starosti o nás.'),
(1553588,54,9,9,6,'Kterýž řekl jemu: Aj, nyní muž Boží jest v městě tomto, a muž ten jest znamenitý; cožkoli praví, všecko se tak stává. Medle, jděme tam, zdali by oznámil nám cestu naši, kterouž bychom jíti měli.'),
(1553589,54,9,9,7,'Odpověděl Saul služebníku svému: Aj, půjdeme. Co pak přineseme muži tomu? Nebo jsme chléb vytrávili z pytlíků našich, ani daru nemáme, kterýž bychom přinesli muži Božímu. Což máme?'),
(1553590,54,9,9,8,'I doložil služebník, odpovídaje Saulovi, a řekl: Hle, nalezl jsem u sebe čtvrt lotu stříbra; to dám muži Božímu, aby nám oznámil cestu naši.'),
(1553591,54,9,9,9,'(Za starodávna v Izraeli tak říkával každý, kdož jíti měl raditi se s Bohem: Poďte, a půjdeme až k vidoucímu. Nebo ten, kterýž nyní slove prorok, za starodávna sloul vidoucí.)');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553592,54,9,9,10,'Řekl tedy Saul služebníku svému: Dobrá jest řeč tvá, nu, jděmež. I šli do města, v kterémž byl muž Boží.'),
(1553593,54,9,9,11,'A když vcházeli na horu města, potkali se s děvečkami, vycházejícími vážit vody. I řekli jim: Jest-li zde vidoucí?'),
(1553594,54,9,9,12,'Kteréž odpověděly jim a řekly: Jest. Hle, a on před tebou, pospěš tedy; nebo dnes přišel do města, proto že obětuje dnes lid na té hoře.'),
(1553595,54,9,9,13,'Hned jakž vejdete do města, tedy naleznete ho, prvé než vstoupí na horu k jídlu. Lid zajisté nebude jísti, dokudž on nepřijde, nebo on požehná obětí, a potom pozvaní jísti budou. A protož jděte, nebo v tuto chvíli naleznete ho.'),
(1553596,54,9,9,14,'I šli do města. A když vcházeli do prostřed města, aj, Samuel vycházel proti nim, aby vstoupil na tu horu.'),
(1553597,54,9,9,15,'Hospodin pak zjevil Samuelovi o jeden den prvé, nežli přišel Saul, řka:'),
(1553598,54,9,9,16,'V tuto chvíli zítra pošli k tobě muže z země Beniamin, kteréhož pomažeš, aby byl vůdce lidu mého Izraelského, a vysvobodíť lid můj z ruky Filistinských; vzhlédlť jsem zajisté na lid svůj, nebo přišlo volání jeho ke mně.'),
(1553599,54,9,9,17,'A když Samuel uzřel Saule, řekl jemu Hospodin: Aj, teď ten muž, o kterémž pravil jsem tobě: tenť spravovati bude lid můj.'),
(1553600,54,9,9,18,'Tedy přistoupil Saul k Samuelovi v bráně, a řekl: Ukaž mi, prosím, kde jest tuto dům vidoucího?'),
(1553601,54,9,9,19,'I odpověděl Samuel Saulovi: Já jsem vidoucí. Vstupiž přede mnou na horu, a budete dnes jísti se mnou; potom ráno propustím tě, a cožkoli jest v srdci tvém, oznámím tobě.'),
(1553602,54,9,9,20,'O oslice pak, kteréžť se ztratily dnes třetí den, nic se nestarej, nebo nalezeny jsou. Ale na koho žádost všeho Izraele? Zdali ne na tebe a na všecken dům otce tvého?'),
(1553603,54,9,9,21,'I odpověděl Saul a řekl: Zdaliž já nejsem syn Jemini, z nejmenšího pokolení Izraelského? Ano i čeled má jest nejchaternejší ze všech čeledí pokolení Beniaminova. Pročež jsi tedy ke mně mluvil taková slova?'),
(1553604,54,9,9,22,'A pojav Samuel Saule i služebníka jeho, uvedl je do pokoje, a dal jim místo nejpřednější mezi pozvanými, jichž bylo okolo třidcíti mužů.'),
(1553605,54,9,9,23,'I řekl Samuel kuchaři: Dej sem ten díl, kterýž jsem dal tobě, o kterémžť jsem řekl: Schovej jej obzvláštně.'),
(1553606,54,9,9,24,'Když tedy přinesl kuchař plece i s tím, což se ho přídrželo, položil Samuel před Saule, a řekl: Teď, což pozůstalo, vezmi sobě, jez; až k této chvíli zajisté zachováno jest to pro tebe, jakž jsem řekl: Lidu jsem pozval. I jedl Saul s Samuelem v ten den.'),
(1553607,54,9,9,25,'A když sešli s hory do města, mluvil s Saulem na vrchní podlaze.'),
(1553608,54,9,9,26,'Potom vstali velmi ráno. I stalo se, když záře vzcházela, že zavolal Samuel Saule na hůru, řka: Vstaň, a propustím tě. Vstal tedy Saul, a vyšli oba ven, on i Samuel.'),
(1553609,54,9,9,27,'A když přicházeli na konec města, řekl Samuel Saulovi: Rci služebníku, ať jde napřed, (i šel); ty pak pozastav se málo, ažť oznámím řeč Boží.'),
(1553610,54,9,10,1,'Tedy vzal Samuel nádobku oleje, a vylil na hlavu jeho, a políbil ho, i řekl: Aj, teď pomazal tě Hospodin nad dědictvím svým za vůdce.'),
(1553611,54,9,10,2,'Když půjdeš dnes ode mne, nalezneš dva muže u hrobu Ráchel v končinách Beniamin v Zelzachu. Kteříž řeknou tobě: Nalezeny jsou oslice, jichž jsi chodil hledati. A aj, otec tvůj nechav péče o oslice, stará se o vás, pravě: Kterak udělám o syna svého?'),
(1553612,54,9,10,3,'A odejda odtud dále, přijdeš až k rovině Tábor. I potkají se s tebou tam tři muži vstupující k Bohu do Bethel, jeden nesa tři kozelce, druhý nesa tři pecníky chleba, a třetí nesa láhvici vína.'),
(1553613,54,9,10,4,'Kteřížto když tě pozdraví, dadíť dva chleby, kteréž přijmeš z rukou jejich.'),
(1553614,54,9,10,5,'Potom přijdeš na pahrbek Boží, na kterémž jest stráž Filistinská. A když tam vejdeš do města, potká se s tebou zástup proroků sstupujících s hory, a před nimi loutna, buben i píšťalka a harfa, a oni prorokovati budou.'),
(1553615,54,9,10,6,'I sstoupí na tě Duch Hospodinův, a prorokovati budeš s nimi, a proměněn budeš v muže jiného.'),
(1553616,54,9,10,7,'Když tedy zběhnou se tato znamení při tobě, učiň, cožkoli najde ruka tvá, nebo Bůh s tebou jest.'),
(1553617,54,9,10,8,'Potom sstoupíš přede mnou do Galgala, a aj, já sstoupím k tobě, abych obětoval oběti zápalné, též abych obětoval oběti pokojné. Za sedm dní čekati budeš, až přijdu k tobě, a ukážiť, co bys měl činiti.'),
(1553618,54,9,10,9,'A bylo, když se obrátil, aby šel od Samuele, že Bůh proměnil srdce jeho v jiné, a zběhla se všecka ta znamení dne toho.'),
(1553619,54,9,10,10,'I přišli tam ku pahrbku, a aj, zástup proroků proti němu, i sstoupil na něj Duch Boží, a prorokoval u prostřed nich.'),
(1553620,54,9,10,11,'Stalo se tedy, že všickni, kdož ho znali prvé, viděli, an prorokuje s proroky. Pročež mluvil každý, jeden k druhému: Což se to stalo synu Cis? Zdali také Saul mezi proroky?'),
(1553621,54,9,10,12,'I odpověděl jeden odtud a řekl: A kdo jest otec jejich? Protož přišlo to v přísloví: Zdali také Saul mezi proroky?'),
(1553622,54,9,10,13,'A přestav prorokovati, přišel na horu.'),
(1553623,54,9,10,14,'Řekl pak strýc Saulův jemu a k služebníku jeho: Kam jste chodili? Odpověděl: Hledati oslic; když jsme pak poznali, že jich není, přišli jsme k Samuelovi.'),
(1553624,54,9,10,15,'I řekl strýc Saulův: Pověz mi medle, co vám řekl Samuel?'),
(1553625,54,9,10,16,'Odpověděl Saul strýci svému: Oznámil nám místně, že by nalezeny byly oslice. Ale s strany království nic mu neoznámil, co mluvil Samuel.'),
(1553626,54,9,10,17,'Svolal pak Samuel lid k Hospodinu do Masfa,'),
(1553627,54,9,10,18,'A řekl synům Izraelským: Takto praví Hospodin Bůh Izraelský: Já jsem vyvedl Izraele z Egypta, a vysvobodil jsem vás z ruky Egyptských, nýbrž z ruky všech království ssužujících vás.'),
(1553628,54,9,10,19,'Ale vy dnes zavrhli jste Boha svého, kterýž sám vyprošťuje vás ze všech zlých věcí vašich a z úzkostí vašich, a řekli jste jemu: Krále ustanov nad námi. Protož nyní postavtež se před Hospodinem po pokoleních svých a po tisících svých.'),
(1553629,54,9,10,20,'A když Samuel kázal přistupovati všechněm pokolením Izraelským, přišlo na pokolení Beniamin.'),
(1553630,54,9,10,21,'Potom kázal přistupovati pokolení Beniamin po čeledech jich, i přišlo na čeled Matri, a přišlo na Saule, syna Cis. I hledali ho, a není nalezen.'),
(1553631,54,9,10,22,'Protož ptali se opět Hospodina: Přijde-li ještě sem ten muž? I odpověděl Hospodin: Aj, skryl se mezi nádobím.'),
(1553632,54,9,10,23,'Tedy běželi a vzali ho odtud. I postavil se u prostřed lidu, a převyšoval všecken lid od ramene svého vzhůru.'),
(1553633,54,9,10,24,'I řekl Samuel všemu lidu: Vidíte-li, koho vyvolil Hospodin, žeť mu není podobného ve všem lidu? Protož zkřikl všecken lid, a řekli: Živ buď král!'),
(1553634,54,9,10,25,'I oznamoval Samuel lidu o správě království, a vepsal to do knihy, kterouž položil před Hospodinem. Potom propustil Samuel všecken lid, jednoho každého do domu jeho.'),
(1553635,54,9,10,26,'Také i Saul odšel do domu svého do Gabaa; a odešla s ním vojska, jichžto srdcí Bůh se dotekl.'),
(1553636,54,9,10,27,'Ale lidé nešlechetní řekli: Tento-liž nás vysvobodí? I pohrdali jím, ani mu pocty nepřinesli. On pak činil se neslyše.'),
(1553637,54,9,11,1,'Tedy přitáhl Náhas Ammonitský, a položil se proti Jábes v Gálad. I řekli všickni muži Jábes k Náhasovi: Učiň s námi smlouvu, a budemeť sloužiti.'),
(1553638,54,9,11,2,'Jimž odpověděl Náhas Ammonitský: Na ten způsob učiním s vámi smlouvu, jestliže každému z vás vyloupím oko pravé, a uvedu to pohanění na všecken Izrael.'),
(1553639,54,9,11,3,'I řekli jemu starší Jábes: Propůjč nám sedm dní, ať rozešleme posly po všech končinách Izraelských, a nebude-li žádného, kdo by nás vysvobodil, tedy vyjdeme k tobě.'),
(1553640,54,9,11,4,'Když pak přišli ti poslové do Gabaa Saulova, a mluvili ta slova v uši lidu, pozdvihli všickni hlasu svého a plakali.'),
(1553641,54,9,11,5,'A aj, Saul šel za voly s pole. I řekl Saul: Co je lidu, že pláče? I vypravovali jemu slova mužů Jábes.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553642,54,9,11,6,'Tedy sstoupil Duch Boží na Saule, když uslyšel slova ta, a rozhněvala se prchlivost jeho náramně.'),
(1553643,54,9,11,7,'A vzav pár volů, rozsekal je na kusy, a rozeslal po všech krajinách Izraelských po týchž poslích, řka: Kdo by koli nešel za Saulem a za Samuelem, tak se stane s voly jeho. I připadl strach Hospodinův na lid, a vyšli jako muž jeden.'),
(1553644,54,9,11,8,'I sečtl je v Bezeku; a bylo synů Izraelských třikrát sto tisíc, a mužů Juda třidceti tisíců.'),
(1553645,54,9,11,9,'I řekli těm poslům, kteříž byli přišli: Takto povíte mužům Jábes v Galád: Zítra budete vysvobozeni, když slunce obejde. I přišli poslové, a oznámili mužům Jábes, kteřížto zradovali se.'),
(1553646,54,9,11,10,'Tedy řekli muži Jábes Ammonitským: Ráno vyjdeme k vám, abyste nám učinili, cožkoli se vám za dobré viděti bude.'),
(1553647,54,9,11,11,'Nazejtří pak rozdělil Saul lid na tři houfy; i vskočili do prostřed vojska v čas jitřního bdění, a bili Ammonitské, až slunce dobře vzešlo; kteříž pak byli pozůstali, rozprchli se, tak že nezůstalo z nich ani dvou pospolu.'),
(1553648,54,9,11,12,'I řekl lid Samuelovi: Kdo jest ten, jenž pravil: Zdali Saul kralovati bude nad námi? Vydejte ty muže, ať je zbijeme.'),
(1553649,54,9,11,13,'Ale Saul řekl: Nebudeť dnes žádný zabit, poněvadž dnes učinil Hospodin vysvobození v Izraeli.'),
(1553650,54,9,11,14,'I řekl Samuel lidu: Přiďte, a poďme do Galgala, obnovíme tam království.'),
(1553651,54,9,11,15,'Šel tedy všecken lid do Galgala, a ustanovili tam Saule za krále před Hospodinem v Galgala, a obětovali také tam oběti pokojné před Hospodinem. I veselil se tam Saul a všickni muži Izraelští velmi velice.'),
(1553652,54,9,12,1,'Mluvil pak Samuel ke všemu Izraelovi: Aj, uposlechl jsem hlasu vašeho ve všem, což jste mluvili ke mně, a ustanovil jsem nad vámi krále.'),
(1553653,54,9,12,2,'A nyní aj, král jde před vámi, já pak zstaral jsem se a ošedivěl, a synové moji, aj, mezi vámi jsou. Já také chodil jsem před vámi od své mladosti až do dnešního dne.'),
(1553654,54,9,12,3,'A však aj, teď jsem. Vydejte svědectví proti mně před Hospodinem a před pomazaným jeho, vzal-li jsem čího vola, aneb vzal-li jsem čího osla, utiskl-li jsem koho, ublížil-li jsem komu, aneb vzal-li jsem od koho úplatek, abych na něm přehlédl něco, a navrátím vám.'),
(1553655,54,9,12,4,'Odpověděli: Neutiskl jsi nás, aniž jsi ublížil nám, aniž jsi co vzal z ruky kterého člověka.'),
(1553656,54,9,12,5,'Řekl ještě jim: Svědek jest Hospodin proti vám, svědek jest i pomazaný jeho v tento den, že jste nenalezli při mně ničehož. I řekl lid: Svědek jest.'),
(1553657,54,9,12,6,'Tedy řekl Samuel lidu: Hospodin jest svědek, kterýž učinil Mojžíše a Arona, a kterýž vyvedl otce vaše z země Egyptské.'),
(1553658,54,9,12,7,'Protož nyní postavte se, ať s vámi v soud vejdu před Hospodinem o všecky spravedlivé skutky Hospodinovy, kteréž učinil s vámi i s otci vašimi.'),
(1553659,54,9,12,8,'Když byl všel Jákob do Egypta, volali otcové vaši k Hospodinu; i poslal Hospodin Mojžíše a Arona, kteříž vyvedli otce vaše z Egypta, a osadili je na tomto místě.'),
(1553660,54,9,12,9,'A když se zapomenuli na Hospodina Boha svého, vydal je v ruku Zizary, knížete vojska Azor, a v ruku Filistinských, též v ruku krále Moábského, kteříž bojovali proti nim.'),
(1553661,54,9,12,10,'Ale když volali k Hospodinu a řekli: Zhřešili jsme, nebo jsme opustili Hospodina, a sloužili jsme Bálim a Astarot, protož nyní vysvoboď nás z ruky nepřátel našich, a sloužiti budeme tobě:'),
(1553662,54,9,12,11,'I poslal Hospodin Jerobále a Bedana a Jefte a Samuele, a vytrhl vás z ruky nepřátel vašich okolních, a bydlili jste bezpečně.'),
(1553663,54,9,12,12,'Potom vidouce, že Náhas král synů Ammon přitáhl proti vám, řekli jste mi: Nikoli, ale král bude kralovati nad námi; ješto Hospodin Bůh váš jest králem vaším.'),
(1553664,54,9,12,13,'Nyní tedy, aj, král, kteréhož jste zvolili, za něhož jste žádali, a aj, Hospodin ustanovil ho nad vámi králem.'),
(1553665,54,9,12,14,'Budete-li se báti Hospodina, a jemu sloužiti a poslouchati hlasu jeho, a nebudete-li se zpěčovati řeči Hospodinově, tak i vy i král, kterýž kraluje nad vámi, ostojíte, jdouce za Hospodinem Bohem vaším.'),
(1553666,54,9,12,15,'Pakli nebudete poslouchati hlasu Hospodinova, ale odporni budete řeči jeho, bude ruka Hospodinova proti vám, jako i proti otcům vašim.'),
(1553667,54,9,12,16,'Ještě se teď pozastavte, a vizte věc tuto velikou, kterouž učiní Hospodin před očima vašima.'),
(1553668,54,9,12,17,'Zdaliž není dnes žeň pšeničná? Volati budu k Hospodinu, i vydá hřímání a déšť, tak že poznati a viděti musíte, jak jest to velmi zlá věc, kteréž jste se dopustili před očima Hospodinovýma, žádavše sobě krále.'),
(1553669,54,9,12,18,'Protož volal Samuel k Hospodinu, a vydal Hospodin hřímání a déšť v ten den. I bál se všecken lid Hospodina velmi i Samuele.'),
(1553670,54,9,12,19,'A řekl všecken lid Samuelovi: Modl se za služebníky své Hospodinu Bohu svému, abychom nezemřeli; nebo jsme přidali ke všem hříchům našim i toto zlé, že jsme sobě žádali krále.'),
(1553671,54,9,12,20,'I řekl Samuel lidu: Nebojte se. Učiniliť jste sic všecko to zlé, však proto neodstupujte zpět od Hospodina, ale služte Hospodinu celým srdcem svým.'),
(1553672,54,9,12,21,'Neodstupujte, pravím, následujíce marnosti, totiž cizích bohů, kteříž nic neprospívají, aniž vysvobozují, nebo jsou marnost.'),
(1553673,54,9,12,22,'Neopustíť zajisté Hospodin lidu svého pro jméno své veliké; nebo zalíbilo se Hospodinu, aby vás sobě vzdělal v lid.'),
(1553674,54,9,12,23,'Ode mne také odstup to, abych měl hřešiti proti Hospodinu, a přestávati modliti se za vás, nýbrž navoditi vás budu na cestu dobrou a přímou.'),
(1553675,54,9,12,24,'A však bojte se Hospodina a služte jemu v pravdě celým srdcem svým; nebo vidíte, jak veliké věci učinil s vámi.'),
(1553676,54,9,12,25,'Jestliže pak předce zle činiti budete, i vy i král váš zahynete.'),
(1553677,54,9,13,1,'Saul tedy prvního léta kralování svého, (kraloval pak dvě létě nad Izraelem),'),
(1553678,54,9,13,2,'Vybral sobě tři tisíce z Izraele. I bylo jich s Saulem dva tisíce v Michmas a na hoře Bethel, a tisíc bylo s Jonatou v Gabaa Beniaminově; ostatek pak lidu rozpustil jednoho každého do příbytku jeho.'),
(1553679,54,9,13,3,'I pobil Jonata stráž Filistinských, kterouž měli na pahrbku, a uslyšeli to Filistinští. Tedy Saul troubil v troubu po vší zemi, řka: Ať to slyší Hebrejští.'),
(1553680,54,9,13,4,'A tak slyšel všecken Izrael, že bylo praveno: Pobil Saul stráž Filistinských, pročež také zoškliven byl Izrael mezi Filistinskými. I svolán jest lid za Saulem do Galgala.'),
(1553681,54,9,13,5,'Filistinští pak sebrali se k boji proti Izraelovi, třidceti tisíc vozů, a šest tisíc jezdců, a lidu ve množství, jako jest písku na břehu mořském. I vytáhli a položili se v Michmas na východ Betaven.'),
(1553682,54,9,13,6,'A protož muži Izraelští vidouce, že jim úzko, (nebo byl ssoužen lid), skryl se lid v jeskyních a v ohradách, a v skalách a v horách, i v jamách.'),
(1553683,54,9,13,7,'Hebrejští také přepravili se přes Jordán do země Gád a Galád. Saul pak ještě byl v Galgala, a všecken lid zastrašil se, jda za ním.'),
(1553684,54,9,13,8,'I očekával tu za sedm dní vedlé času uloženého od Samuele; a když nepřicházel Samuel do Galgala, rozešel se lid od něho.'),
(1553685,54,9,13,9,'Tedy řekl Saul: Přineste ke mně obět zápalnou a oběti pokojné. I obětoval oběti zápalné.'),
(1553686,54,9,13,10,'Když pak již dokonal obětování oběti zápalné, aj, Samuel přicházel, a Saul vyšel proti němu, aby ho přivítal.'),
(1553687,54,9,13,11,'I řekl Samuel: Co jsi učinil? Odpověděl Saul: Když jsem viděl, že se lid rozchází ode mne, a ty nepřicházíš k uloženému dni, a Filistinští byli shromážděni v Michmas:'),
(1553688,54,9,13,12,'I řekl jsem: Nyní připadnou Filistinští na mne v Galgala, a tváři Hospodinově nemodlil jsem se. Takž jsem se opovážil a obětoval jsem oběti zápalné.'),
(1553689,54,9,13,13,'Tedy řekl Samuel Saulovi: Bláznivě jsi učinil, nezachovals přikázaní Hospodina Boha svého, kteréž přikázal tobě; nebo nyní byl by utvrdil Hospodin království tvé nad Izraelem až na věky.'),
(1553690,54,9,13,14,'Ale již nyní království tvé neostojí. Vyhledalť jest Hospodin sobě muže vedlé srdce svého, jemuž rozkázal Hospodin, aby byl vůdce nad lidem jeho; nebo jsi nezachoval, cožť přikázal Hospodin.'),
(1553691,54,9,13,15,'Vstav pak Samuel, vstoupil z Galgala do Gabaa Beniaminova. A Saul načetl lidu, kterýž zůstával při něm, okolo šesti set mužů.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553692,54,9,13,16,'Saul tedy a Jonata syn jeho, i lid, kterýž zůstával s nimi, byli v Gabaa Beniaminově, Filistinští pak leželi v Michmas.'),
(1553693,54,9,13,17,'I vyšli zhoubcové z vojska Filistinského na tré rozdělení. Houf jeden obrátil se k cestě Ofra, k zemi Sual;'),
(1553694,54,9,13,18,'A houf druhý obrátil se na cestu Betoron; houf pak třetí pustil se cestou krajiny, kteráž patří k údolí Seboim na poušť.'),
(1553695,54,9,13,19,'Kováře pak žádného nenalézalo se ve vší zemi Izraelské; nebo byli řekli Filistinští: Aby sobě Hebrejští nenadělali mečů a kopí.'),
(1553696,54,9,13,20,'Protož chodívali všickni Izraelští k Filistinským, aby ostřil sobě jeden každý radlici svou, a motyku svou, sekeru svou i vidly své,'),
(1553697,54,9,13,21,'Sic jinak byly štěrbiny na radlicích, motykách, vidlách třírohých a sekerách; také i o zaostření ostnu bývalo těžko.'),
(1553698,54,9,13,22,'I bylo, že v čas boje nenalézalo se meče ani kopí u žádného z lidu toho, kterýž byl s Saulem a s Jonatou, toliko u Saule a u Jonaty syna jeho.'),
(1553699,54,9,13,23,'Vyšla pak stráž Filistinských k cestám Michmas.'),
(1553700,54,9,14,1,'Stalo se pak jednoho dne, že řekl Jonata syn Saulův služebníku, kterýž nosil zbroj jeho: Poď, půjdeme k stráži Filistinských, kteráž jest na oné straně. Ale otci svému toho nepověděl.'),
(1553701,54,9,14,2,'Saul však zůstával na kraji pahrbku pod jabloní zrnatou, kteráž byla v Migron; a lidu, kterýž byl s ním, bylo okolo šesti set mužů,'),
(1553702,54,9,14,3,'Tolikéž Achiáš syn Achitobův, bratra Ichabodova, syna Fínesova, syna Elí, kněze Hospodinova v Sílo, kterýž nosil efod. Ale lid nevěděl, že by odšel Jonata.'),
(1553703,54,9,14,4,'Mezi těmi pak průchody, jimiž pokoušel se Jonata přejíti k stráži Filistinských, byla skála příkrá k přecházení s této strany, též skála příkrá k přecházení s oné strany; jméno jedné Bóses, a jméno druhé Seneh.'),
(1553704,54,9,14,5,'Jedna skála byla na půlnoci proti Michmas, a druhá na poledne proti Gabaa.'),
(1553705,54,9,14,6,'I řekl Jonata služebníku, kterýž nosil zbroj jeho: Poď, přejděme k stráži těch neobřezaných, snad bude Hospodin s námi; neboť není nesnadné Hospodinu zachovati ve mnoze aneb v mále.'),
(1553706,54,9,14,7,'Odpověděl oděnec jeho: Učiň, cožkoli jest v srdci tvém, obrať se, kam chceš; aj, budu s tebou podlé vůle tvé.'),
(1553707,54,9,14,8,'I řekl Jonata: Aj, my jdeme k mužům těm, a ukážeme se jim.'),
(1553708,54,9,14,9,'Jestliže řeknou nám takto: Počkejte, až přijdeme k vám, stůjme na místě svém, a nechoďme k nim.'),
(1553709,54,9,14,10,'Pakli by řekli takto: Vstupte k nám, jděme, nebo vydal je Hospodin v ruku naši. To zajisté nám bude za znamení.'),
(1553710,54,9,14,11,'Ukázali se tedy oba dva stráži Filistinských. I řekli Filistinští: Hle, Hebrejští lezou z děr, v nichž se byli skryli.'),
(1553711,54,9,14,12,'I mluvili někteří z stráže té k Jonatovi a k oděnci jeho, a řekli: Vstupte k nám, a povíme vám něco. Pročež řekl Jonata k oděnci svému: Podiž za mnou, nebo je vydal Hospodin v ruku Izraele.'),
(1553712,54,9,14,13,'A tak lezl čtvermo Jonata a oděnec jeho za ním. I padali před Jonatou, a oděnec jeho mordoval je, jda za ním.'),
(1553713,54,9,14,14,'A to byla porážka první, v níž zbil Jonata a oděnec jeho okolo dvadcíti mužů, jako v půl honech rolí dvěma volům s zápřež.'),
(1553714,54,9,14,15,'Protož byl strach v tom ležení a na tom poli, i na všem tom lidu; strážní i oni loupežníci děsili se též, až se země třásla, nebo byla v strachu Božím.'),
(1553715,54,9,14,16,'A vidouce strážní Saulovi v Gabaa Beniaminově, oznámili, jak množství to narůzno prchá, a vždy více se potírá.'),
(1553716,54,9,14,17,'Saul pak řekl lidu, kterýž s ním byl: Vyhledejte i hned a zvězte, kdo jest z našich odšel. A když vyhledávali, hle, Jonaty nebylo a oděnce jeho.'),
(1553717,54,9,14,18,'I řekl Saul Achiášovi: Postav sem truhlu Boží. (Truhla pak Boží toho času byla s syny Izraelskými.)'),
(1553718,54,9,14,19,'I stalo se, když ještě mluvil Saul k knězi, že hřmot, kterýž byl v vojště Filistinských, více se rozcházel a rozmáhal. Protož řekl Saul knězi: Spusť ruku svou.'),
(1553719,54,9,14,20,'Shromáždili se tedy Saul i všecken lid, kterýž s ním byl, a přišli až k té bitvě; a aj, byl meč jednoho proti druhému s hřmotem velmi velikým.'),
(1553720,54,9,14,21,'Hebrejští pak někteří byli s Filistinskými prvé, kteříž táhli s nimi polem sem i tam; i ti také obrátili se a stáli při lidu Izraelském, kterýž byl s Saulem a s Jonatou.'),
(1553721,54,9,14,22,'Všickni také muži Izraelští, kteříž se skryli na hoře Efraim, když uslyšeli, že by utíkali Filistinští, honili je i oni v té bitvě.'),
(1553722,54,9,14,23,'I vysvobodil Hospodin toho dne Izraele. Boj pak protáhl se až do Betaven.'),
(1553723,54,9,14,24,'A ačkoli muži Izraelští utrápili se toho dne, však Saul zavázal lid s přísahou, řka: Zlořečený muž, kterýž by jedl chléb prvé, než bude večer, a než se pomstím nad nepřátely svými. A tak neokusil všecken lid chleba.'),
(1553724,54,9,14,25,'Všecken pak lid té krajiny šli do lesa, kdež bylo hojnost medu po zemi.'),
(1553725,54,9,14,26,'A když všel lid do lesa, viděl tekoucí med; žádný však nepřičinil k ústům svým ruky své, nebo se bál lid té přísahy.'),
(1553726,54,9,14,27,'Ale Jonata neslyšev, že otec jeho zavazoval lid přísahou, vztáhl hůl, kterouž měl v ruce své, a omočil konec její v plástu medu, a obrátil ruku svou k ústům svým; i osvítily se oči jeho.'),
(1553727,54,9,14,28,'Odpovídaje pak jeden z lidu, řekl: Velikou přísahou zavázal otec tvůj lid, řka: Zlořečený muž, kterýž by jedl chléb dnes, ačkoli zemdlel lid.'),
(1553728,54,9,14,29,'Tedy řekl Jonata: Zkormoutil otec můj lid země. Pohleďte, prosím, jak se osvítily oči mé, hned jakž jsem okusil maličko medu toho.'),
(1553729,54,9,14,30,'Čím více kdyby se byl směle najedl dnes lid z loupeží nepřátel svých, kterýchž dosáhl? Nebyla-liž by se nyní stala větší porážka Filistinských?'),
(1553730,54,9,14,31,'A tak bili toho dne Filistinské od Michmas až do Aialon; i ustal lid náramně.'),
(1553731,54,9,14,32,'Protož obrátil se lid k loupeži, a nabravše ovcí a volů i telat, zbili je na zemi; i jedl lid se krví.'),
(1553732,54,9,14,33,'I pověděli Saulovi, řkouce: Aj, lid hřeší proti Hospodinu, jeda se krví. Kterýž řekl: Přestoupili jste přikázaní. Přivaltež i hned ke mně kámen veliký.'),
(1553733,54,9,14,34,'Opět řekl Saul: Rozejděte se mezi lid a rcete jim: Přiveďte ke mně jeden každý vola svého a jeden každý dobytče své, a bíte tuto a jezte, i nebudete hřešiti proti Hospodinu, jedouce se krví. Přivedli tedy všecken lid jeden každý vola svého rukou svou té noci a zabíjeli tu.'),
(1553734,54,9,14,35,'Vzdělal také Saul oltář Hospodinu; to nejprvnější oltář udělal Hospodinu.'),
(1553735,54,9,14,36,'Potom řekl Saul: Pusťme se po Filistinských v noci, a budeme je loupiti až do jitra, aniž zůstavujme z nich koho. Kteříž řekli: Cožť se koli vidí za dobré, učiň. Ale kněz řekl: Přistupme sem k Bohu.'),
(1553736,54,9,14,37,'I tázal se Saul Boha: Pustím-li se za Filistinskými? Dáš-li je v ruku Izraelovu? I neodpověděl mu v ten den.'),
(1553737,54,9,14,38,'Protož řekl Saul: Přistupujte sem všecka knížata lidu, a vyzvězte a vyhledejte, kdo se jest dopustil dnes hříchu nějakého?'),
(1553738,54,9,14,39,'Nebo živť jest Hospodin, kterýž vysvobozuje Izraele, že byť pak i na Jonatovi synu mém to bylo, smrtí umře. I neodpověděl jemu žádný ze všeho lidu.'),
(1553739,54,9,14,40,'Řekl také všemu Izraelovi: Buďte vy na jedné straně, já pak a Jonata syn můj budeme na druhé straně. Odpověděl lid Saulovi: Učiň, cožť se za dobré vidí.'),
(1553740,54,9,14,41,'Protož řekl Saul Hospodinu Bohu Izraelskému: Ukaž spravedlivě. I přišlo na Jonatu a Saule, lid pak z toho vyšel.'),
(1553741,54,9,14,42,'I řekl Saul: Vrzte los mezi mnou a mezi Jonatou synem mým. A postižen jest Jonata.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553742,54,9,14,43,'Řekl tedy Saul Jonatovi: Pověz mi, co jsi učinil? I pověděl mu Jonata a řekl: Toliko jsem okusil maličko medu koncem holi, kterouž jsem měl v ruce své, a aj, proto-liž mám umříti?'),
(1553743,54,9,14,44,'Odpověděl Saul: Toto učiň mi Bůh a toto přidej, že smrtí umřeš, Jonato.'),
(1553744,54,9,14,45,'I řekl lid Saulovi: Což tedy umříti má Jonata, kterýž učinil vysvobození toto veliké v Izraeli? Odstup to, živť jest Hospodin, že nespadne vlas s hlavy jeho na zemi, poněvadž s pomocí Boží učinil to dnes. I vyprostil lid Jonatu, tak aby nebyl usmrcen.'),
(1553745,54,9,14,46,'Tedy odtáhl Saul od Filistinských; Filistinští také navrátili se k místu svému.'),
(1553746,54,9,14,47,'Saul pak uvázav se v království nad Izraelem, bojoval vůkol se všemi nepřátely svými, s Moábskými a s syny Ammon, a s Edomem, i s králi Soba, a s Filistinskými; a kamž se koli obracel, ukrutnost provodil.'),
(1553747,54,9,14,48,'Sebrav také vojska, porazil Amalecha, a vysvobodil Izraele z ruky zhoubců jeho.'),
(1553748,54,9,14,49,'Byli pak synové Saulovi: Jonata a Jesui a Melchisua; a jména dvou dcer jeho, jméno prvorozené Merob, jméno pak mladší Míkol.'),
(1553749,54,9,14,50,'A jméno manželky Saulovy Achinoam, dcera Achimaasova; jméno pak hejtmana vojska jeho Abner, syn Ner, strýce Saulova.'),
(1553750,54,9,14,51,'Nebo Cis byl otec Saulův, a Ner otec Abnerův, syn Abielův.'),
(1553751,54,9,14,52,'Byla pak válka veliká s Filistinskými po všecky dny Saulovy, protož kohožkoli Saul viděl muže silného, a kohokoli udatného, bral ho k sobě.'),
(1553752,54,9,15,1,'Řekl pak Samuel Saulovi: Hospodin poslal mne, abych tě pomazal za krále nad lidem jeho, nad Izraelem, pozorujž tedy nyní hlasu slov Hospodinových.'),
(1553753,54,9,15,2,'Takto praví Hospodin zástupů: Rozpomenul jsem se na to, co jest činil Amalech Izraelovi, že se položil proti němu na cestě, když se bral z Egypta.'),
(1553754,54,9,15,3,'Protož i hned táhni a zkaz Amalecha, a zahlaďte jako proklaté všecko, což má. Neslitovávejž se nad ním, ale zahub od muže až do ženy, od malého až do toho, kterýž prsí požívá, od vola také až do ovce, a od velblouda až do osla.'),
(1553755,54,9,15,4,'Sebral tedy Saul lid, a sečtl je v Telaim, dvakrát sto tisíc pěších, a deset tisíc mužů Judských.'),
(1553756,54,9,15,5,'A přitáhl Saul až k městu Amalechovu, aby bojoval v údolí jeho.'),
(1553757,54,9,15,6,'I řekl Saul Cinejským: Jděte, oddělte se, vyjděte z prostředku Amalechitských, abych vás s nimi nezahladil; nebo vy jste učinili milosrdenství se všemi syny Izraelskými, když šli z Egypta. A tak odšel Cinejský z prostředku Amalecha.'),
(1553758,54,9,15,7,'I porazil Saul Amalecha od Hevilah, kudy se chodí do Sur, kteréž jest naproti Egyptu.'),
(1553759,54,9,15,8,'Jal také Agaga krále Amalechitského živého, lid pak všecken vyhladil ostrostí meče.'),
(1553760,54,9,15,9,'I zachoval Saul a lid jeho Agaga, a nejlepší bravy a skoty a krmný dobytek, a berany i všecko, což lepšího bylo, a nechtěli vyhubiti jich; což pak bylo ničemného a churavého, to zahubili.'),
(1553761,54,9,15,10,'A protož stalo se slovo Hospodinovo k Samuelovi, řkoucí:'),
(1553762,54,9,15,11,'Žel mi, že jsem Saule ustanovil za krále, nebo odvrátil se ode mne, a slov mých nevyplnil. I rozhorlil se Samuel náramně a volal k Hospodinu celou noc.'),
(1553763,54,9,15,12,'Vstav pak Samuel, šel vstříc Saulovi ráno. I oznámili Samuelovi, řkouce: Saul přišel na Karmel, a aj, připravil sobě místo, a odtud hnuv se, táhl a sstoupil do Galgala.'),
(1553764,54,9,15,13,'A když přišel Samuel k Saulovi, řekl jemu Saul: Požehnaný ty od Hospodina, vyplnil jsem slovo Hospodinovo.'),
(1553765,54,9,15,14,'Samuel pak řekl: Jaké pak jest to bečení ovcí těch v uších mých, a řvání volů, kteréž já slyším?'),
(1553766,54,9,15,15,'Odpověděl Saul: Od Amalechitských přihnali je; nebo zachoval lid, což nejlepšího bylo z bravů a skotů, aby to obětoval Hospodinu Bohu tvému, ostatek pak jsme zahladili jako proklaté.'),
(1553767,54,9,15,16,'I řekl Samuel Saulovi: Dopusť, ať oznámím tobě, co jest mi mluvil Hospodin noci této. Dí jemu: Oznam.'),
(1553768,54,9,15,17,'Tedy řekl Samuel: Zdali jsi nebyl maličký sám u sebe? A předce učiněn jsi hlavou pokolení Izraelských, a pomazal tě Hospodin za krále nad Izraelem.'),
(1553769,54,9,15,18,'A poslal tě Hospodin na cestu a řekl tobě: Jdi, zahub jako proklaté hříšníky ty Amalechitské, a bojuj proti nim, dokudž byste nevyhladili jich.'),
(1553770,54,9,15,19,'Pročež jsi tedy neuposlechl hlasu Hospodinova, ale obrátil jsi se k loupeži, a učinils zlou věc před očima Hospodinovýma?'),
(1553771,54,9,15,20,'Odpověděl Saul Samuelovi: Však jsem uposlechl hlasu Hospodinova, a šel jsem cestou, kterouž poslal mne Hospodin, a přivedl jsem Agaga krále Amalechitského, i Amalechitské jako proklaté vyhubil jsem.'),
(1553772,54,9,15,21,'Ale lid vzal z loupeží bravy a skoty přední z věcí proklatých, k obětování Hospodinu Bohu tvému v Galgala.'),
(1553773,54,9,15,22,'I řekl Samuel: Zdaliž líbost takovou má Hospodin v zápalích a v obětech, jako když se poslušenství koná hlasu Hospodinova? Aj, poslouchati lépe jest, nežli obětovati, a ku poslušenství státi, nežli tuk skopců přinášeti.'),
(1553774,54,9,15,23,'Nebo zpoura jest takový hřích jako čarodějnictví, a přestoupiti přikázaní jako modlářství a obrazové. Poněvadž jsi pak zavrhl řeč Hospodinovu, i on také zavrhl tě, abys nebyl králem.'),
(1553775,54,9,15,24,'Tedy řekl Saul Samuelovi: Zhřešil jsem, že jsem přestoupil rozkaz Hospodinův a slova tvá, nebo jsem se bál lidu, a povolil jsem hlasu jejich.'),
(1553776,54,9,15,25,'Protož nyní odpusť, prosím, hřích můj, a navrať se se mnou, ať se pomodlím Hospodinu.'),
(1553777,54,9,15,26,'I řekl Samuel Saulovi: Nenavrátím se s tebou; nebo jsi zavrhl řeč Hospodinovu, tebe také zavrhl Hospodin, abys nebyl králem nad Izraelem.'),
(1553778,54,9,15,27,'A když se obrátil Samuel, aby odšel, Saul uchytil křídlo pláště jeho, i odtrhlo se.'),
(1553779,54,9,15,28,'Tedy řekl jemu Samuel: Odtrhlť jest Hospodin království Izraelské dnes od tebe, a dal je bližnímu tvému, lepšímu, než jsi ty.'),
(1553780,54,9,15,29,'Však proto vítěz Izraelský klamati nebude, ani želeti; nebo není člověkem, aby měl čeho želeti.'),
(1553781,54,9,15,30,'On pak řekl: Zhřešilť jsem, ale vždy mne cti, prosím, před staršími lidu mého a před Izraelem, a navrať se se mnou, abych se pomodlil Hospodinu Bohu tvému.'),
(1553782,54,9,15,31,'I navrátiv se Samuel, šel za Saulem, a pomodlil se Saul Hospodinu.'),
(1553783,54,9,15,32,'Řekl pak Samuel: Přiveďte ke mně Agaga, krále Amalechitského. I šel k němu Agag nádherně; nebo řekl Agag: Jistě odešla hořkost smrti.'),
(1553784,54,9,15,33,'Ale Samuel řekl: Jakož uvedl sirobu na ženy meč tvůj, takť osiří matka tvá nad jiné ženy. I rozsekal Samuel Agaga na kusy před Hospodinem v Galgala.'),
(1553785,54,9,15,34,'Potom odšel Samuel do Ráma, Saul pak vstoupil do domu svého, do Gabaa Saulova.'),
(1553786,54,9,15,35,'A již potom více Samuel neviděl Saule až do dne smrti své; však plakal Samuel Saule. Hospodin pak želel toho, že učinil Saule králem nad Izraelem.'),
(1553787,54,9,16,1,'Řekl pak Hospodin Samuelovi: I dokudž ty budeš plakati Saule, poněvadž jsem já ho zavrhl, aby nekraloval nad Izraelem? Naplň roh svůj olejem a poď, pošli tě k Izai Betlémskému; nebo jsem vybral sobě z synů jeho krále.'),
(1553788,54,9,16,2,'I řekl jemu Samuel: Kterak mám jíti? Nebo Saul uslyše, zabije mne. Odpověděl Hospodin: Jalovici z stáda vezmeš s sebou, a díš: Přišel jsem, abych obětoval Hospodinu.'),
(1553789,54,9,16,3,'A pozveš Izai k oběti, jáť pak ukáži, co bys měl činiti; i pomažeš mi toho, o kterémž já tobě povím.'),
(1553790,54,9,16,4,'A tak učinil Samuel, jakž mu byl mluvil Hospodin, a přišel do Betléma. A ulekše se starší města, vyšli proti němu a řekli:Pokojný-li jest příchod tvůj?'),
(1553791,54,9,16,5,'Odpověděl:Pokojný. Abych obětoval Hospodinu, přišel jsem. Posvěťte se, a poďte k oběti se mnou. Posvětil také Izai a synů jeho, a pozval jich k oběti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553792,54,9,16,6,'Když pak přišli, vida Eliába, řekl:Jistě před Hospodinem jest pomazaný jeho.'),
(1553793,54,9,16,7,'Ale Hospodin řekl Samuelovi:Nehleď na tvárnost jeho a na zrůst postavy jeho, nebo jsem ho zavrhl; neboť nepatřím, nač patří člověk. Člověk zajisté hledí na to, což jest před očima, ale Hospodin hledí k srdci.'),
(1553794,54,9,16,8,'I povolal Izai Abinadaba, a kázal mu jíti před Samuele. Kterýž řekl:Také ani toho nevyvolil Hospodin.'),
(1553795,54,9,16,9,'Rozkázal též Izai jíti Sammovi. I řekl:Ani toho nevyvolil Hospodin.'),
(1553796,54,9,16,10,'Takž rozkázal Izai jíti sedmi synům svým před Samuele. Ale Samuel řekl Izai:Ani těch nevyvolil Hospodin.'),
(1553797,54,9,16,11,'Potom řekl Samuel Izai:Jsou-li to již všickni synové? Odpověděl: Ještěť zůstává nejmladší, a aj, pase ovce. Tedy řekl Samuel Izai:Pošli a vezmi jej; nebo aniž sedneme za stůl, dokudž on sem nepřijde.'),
(1553798,54,9,16,12,'I poslal a přivedl ho. (Byl pak on ryšavý, krásných očí a libého vzezření.) I řekl Hospodin:Vstana, pomaž ho, nebo to jest ten.'),
(1553799,54,9,16,13,'Protož vzal Samuel roh s olejem, a pomazal ho u prostřed bratří jeho. I odpočinul Duch Hospodinův na Davidovi od toho dne i potom. A Samuel vstav, odšel do Ráma.'),
(1553800,54,9,16,14,'Takž Duch Hospodinův odšel od Saule, a nepokojil ho duch zlý od Hospodina.'),
(1553801,54,9,16,15,'Služebníci pak Saulovi řekli jemu:Aj, teď duch Boží zlý nepokojí tě.'),
(1553802,54,9,16,16,'Nechť, medle, rozkáže pán náš služebníkům svým, kteříž stojí před tebou, ať hledají muže, kterýž by uměl hráti na harfu, aby, když by přišel na tě duch Boží zlý, hral rukou svou, a tobě aby lehčeji bylo.'),
(1553803,54,9,16,17,'Tedy řekl Saul služebníkům svým:Medle, vyhledejte mi muže, kterýž by uměl dobře hráti, a přiveďte ke mně.'),
(1553804,54,9,16,18,'I odpověděl jeden z služebníků a řekl:Aj, viděl jsem syna Izai Betlémského, kterýž umí hráti, muže udatného a bojovného, též správného a krásného, a jest s ním Hospodin.'),
(1553805,54,9,16,19,'Protož poslal Saul posly k Izai, řka:Pošli mi Davida syna svého, kterýž jest při stádu.'),
(1553806,54,9,16,20,'Tedy Izai vzal osla, chléb a nádobu vína a kozelce jednoho, a poslal po Davidovi synu svém Saulovi.'),
(1553807,54,9,16,21,'Když pak přišel David k Saulovi, stál před ním; i zamiloval ho velmi, a učiněn jest jeho oděncem.'),
(1553808,54,9,16,22,'Potom poslal opět Saul k Izai, řka:Medle, nechť David stojí přede mnou, neboť jest našel milost před očima mýma.'),
(1553809,54,9,16,23,'I bývalo, že kdyžkoli napadal duch Boží Saule, David, bera harfu, hrával rukou svou; i míval Saul polehčení, a lépe mu bývalo, nebo ten duch zlý odstupoval od něho.'),
(1553810,54,9,17,1,'I sebrali Filistinští vojska svá k boji, a shromáždili se u Socho, kteréž jest Judovo, a položili se mezi Socho a Azeka na pomezí Dammim.'),
(1553811,54,9,17,2,'Ale Saul a muži Izraelští sebravše se, položili se v údolí Elah, a sšikovali se k bitvě proti Filistinským.'),
(1553812,54,9,17,3,'I stáli Filistinští na hoře s strany jedné, a Izraelští stáli na hoře s strany druhé, a údolí bylo mezi nimi.'),
(1553813,54,9,17,4,'I vyšel muž bojovník z vojska Filistinského, Goliáš jménem, z Gát, zvýší šesti loket a dlani.'),
(1553814,54,9,17,5,'Lebka pak ocelivá na hlavě jeho, a v pancíř brněný byl oblečen, kterýžto pancíř vážil pět tisíc lotů oceli.'),
(1553815,54,9,17,6,'Též plechovice ocelivé byly na nohách jeho, a pavéza ocelivá mezi rameny jeho.'),
(1553816,54,9,17,7,'A dřevo u kopí jeho jako vratidlo tkadlcovské, železo pak ostré kopí jeho vážilo šest set lotů železa; a ten, kterýž nosil braň jeho, šel před ním.'),
(1553817,54,9,17,8,'I postavil se, a volal na vojska Izraelská, řka k nim: Nač jste to vyšli, vojensky se sšikovavše? Zdaliž já nejsem Filistinský, a vy služebníci Saulovi? Vybeřte z sebe muže, kterýž by sstoupil ke mně.'),
(1553818,54,9,17,9,'Jestližeť mi bude moci odolati a zabije mne, tedy budeme služebníci vaši; pakliť já přemohu jej a zabiji ho, budete vy služebníci naši, a sloužiti budete nám.'),
(1553819,54,9,17,10,'Pravil také ten Filistinský: Já jsem dnes zhaněl vojska Izraelská. Vydejtež mi muže, abychom se bili spolu.'),
(1553820,54,9,17,11,'A když uslyšel Saul i všecken Izrael slova Filistinského taková, ulekli se a báli se velmi.'),
(1553821,54,9,17,12,'David pak ten syn muže Efratejského z Betléma Judova, (jehož jméno Izai, kterýž měl osm synů, a již se byl sstaral za dnů Saule, přiblíživ se k lidem sešlým.'),
(1553822,54,9,17,13,'Tři také synové Izai starší šedše, táhli na vojnu s Saulem. Jména těch tří synů jeho, kteříž byli šli k boji: Eliáb prvorozený, a druhý po něm Abinadab, třetí pak Samma.'),
(1553823,54,9,17,14,'Ale David byl nejmladší. A tak ti tři synové starší odešli s Saulem).'),
(1553824,54,9,17,15,'David tedy odšel od Saule a navrátil se, aby pásl stádo otce svého v Betlémě.'),
(1553825,54,9,17,16,'I přicházel ten Filistinský ráno a večer, a stavěl se po čtyřidceti dní.'),
(1553826,54,9,17,17,'Tedy řekl Izai Davidovi synu svému: Vezmi i hned pro bratří své efi pražmy této a deset chlebů těchto, a běž do vojska k bratřím svým.'),
(1553827,54,9,17,18,'A deset syřečků mladých těchto doneseš hejtmanu, a navštívě bratří své, pozdravíš jich, a základ jejich vyzdvihneš.'),
(1553828,54,9,17,19,'Saul pak i oni, i všickni muži Izraelští byli v údolí Elah, bojujíce proti Filistinským.'),
(1553829,54,9,17,20,'A tak vstav David tím raněji a zanechav stáda při strážném, vzal to a šel, jakž mu byl přikázal Izai. I přišel až k šancům, a aj, vojsko vycházelo do šiku a křičelo k bitvě.'),
(1553830,54,9,17,21,'I sšikovali se Izraelští, ano i Filistinští, vojsko proti vojsku.'),
(1553831,54,9,17,22,'Protož David zanechav břemene, kteréž s sebe složil u strážného při břemeních, běžel do vojska; a když přišel, tázal se bratří svých, jak se mají.'),
(1553832,54,9,17,23,'A když on s nimi mluvil, aj, muž bojovník jménem Goliáš, Filistinský z Gát, vycházel z vojska Filistinských a mluvil jako i prvé; což slyšel i David.'),
(1553833,54,9,17,24,'Všickni pak muži Izraelští, jakž uzřeli toho muže, utíkali před tváří jeho, a báli se náramně.'),
(1553834,54,9,17,25,'I mluvili Izraelští mezi sebou: Viděli-li jste toho muže, kterýž vyšel? Nebo aby pohanění uvedl na Izraele, vyšel. Kdož by ho zabil, zbohatí ho král bohatstvím velikým, a dceru svou dá jemu, i dům otce jeho osvobodí v Izraeli.'),
(1553835,54,9,17,26,'I mluvil David mužům, kteříž stáli u něho, a řekl: Co bude dáno muži tomu, kterýž by zabil toho Filistinského a odjal pohanění od Izraele? Nebo kdo jest Filistinský neobřezaný ten, že pohanění uvodí na vojsko Boha živého?'),
(1553836,54,9,17,27,'Odpověděl jemu lid v táž slova, řka: To bude dáno muži, kterýž by ho zabil.'),
(1553837,54,9,17,28,'A uslyšev Eliáb, bratr jeho nejstarší, že mluví s těmi muži, rozhněval se Eliáb velmi na Davida, a řekl: Proč jsi sem přišel? A komus nechal kolikasi těch ovec na poušti? Známť já pýchu tvou a zlost srdce tvého, žes přišel dívati se bitvě.'),
(1553838,54,9,17,29,'I řekl David: Což jsem pak učinil? Zdaž mi nebylo poručeno?'),
(1553839,54,9,17,30,'Tedy šel od něho k jinému, jehož se tázal jako i prvé. I odpověděl jemu lid tak jako i prvé.'),
(1553840,54,9,17,31,'A tak roznesla se slova, kteráž mluvil David, a oznámili je Saulovi. Kterýžto povolal ho.'),
(1553841,54,9,17,32,'I řekl David Saulovi: Nechť se neleká srdce člověka pro něho; služebník tvůj půjde a bude se bíti s Filistinským tímto.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553842,54,9,17,33,'Ale Saul řekl Davidovi: Nebudeš moci jíti proti Filistinskému tomu, abys se potýkal s ním; nebo mládenček jsi, on pak jest muž bojovný od mladosti své.'),
(1553843,54,9,17,34,'Odpověděl David Saulovi: Služebník tvůj pastýřem byl stáda otce svého, a když přicházel lev aneb nedvěd, a bral dobytče z stáda,'),
(1553844,54,9,17,35,'Já dostihal jsem ho a bil jsem jej, a vydíral jsem je z hrdla jeho. Pakli se na mne obořil, tedy ujma ho za čelist, bil jsem jej, až jsem ho i zabil.'),
(1553845,54,9,17,36,'I lva i nedvěda zabil služebník tvůj; budeť tedy Filistinský neobřezanec ten jako který z nich, nebo zhaněl vojska Boha živého.'),
(1553846,54,9,17,37,'Řekl také David: Hospodin, kterýž vytrhl mne z moci lva a z moci nedvěda, onť mne vytrhne z ruky Filistinského tohoto. Tedy řekl Saul Davidovi: Jdi, a Hospodin budiž s tebou.'),
(1553847,54,9,17,38,'I dal Saul obléci Davida v šaty své, a vstavil lebku ocelivou na hlavu jeho, a oblékl ho v pancíř.'),
(1553848,54,9,17,39,'Připásal také David meč jeho na ty šaty jeho, a chtěl jíti, ale že tomu nezvykl, protož řekl David Saulovi: Nemohuť v tom jíti, nebo jsem nepřivykl. I složil to David s sebe.'),
(1553849,54,9,17,40,'A vzav hůl svou do ruky své, vybral sobě pět kamenů hladkých z potoku, a vložil je do mošničky pastýřské, kterouž měl, totiž do pytlíku, a prak svůj v ruce nesl, a přiblížil se k Filistinskému.'),
(1553850,54,9,17,41,'Bral se také i Filistinský, jda a přibližuje se k Davidovi, a muž ten, kterýž nesl braň jeho, šel před ním.'),
(1553851,54,9,17,42,'A když pohleděl Filistinský a uzřel Davida, pohrdal jím, proto že byl mládenček, a ryšavý, a krásného vzezření.'),
(1553852,54,9,17,43,'I řekl Filistinský Davidovi: Což jsem pes, že jdeš proti mně s holí? A zlořečil Filistinský Davidovi skrze bohy své.'),
(1553853,54,9,17,44,'Řekl také Filistinský Davidovi: Poď ke mně, a dámť tělo tvé ptákům nebeským a šelmám zemským.'),
(1553854,54,9,17,45,'Odpověděl David Filistinskému: Ty jdeš ke mně s mečem a s kopím a s pavézou, ale já k tobě jdu ve jménu Hospodina zástupů, Boha vojsk Izraelských, kterémuž jsi ty utrhal.'),
(1553855,54,9,17,46,'Dnešního dne zavře tě Hospodin v ruku mou, a zabiji tě, a setnu hlavu tvou s tebe, a vydám těla vojska Filistinského dnes ptákům nebeským a šelmám zemským, a pozná všecka země, žeť jest Bůh v Izraeli.'),
(1553856,54,9,17,47,'A zvíť všecko shromáždění toto, že ne mečem ani kopím vysvobozuje Hospodin; (nebo Hospodinův jest boj), protož vydáť vás v ruce naše.'),
(1553857,54,9,17,48,'Stalo se pak, že když vstal ten Filistinský, a šel, přibližuje se proti Davidovi, pospíšil i David a běžel proti Filistinskému, aby se s ním potýkal.'),
(1553858,54,9,17,49,'V tom David vztáh ruku svou k mošničce, vyňal z ní kámen, kterýmž hodil z praku, a udeřil Filistinského v čelo jeho tak, že kámen uvázl v čele jeho. I padl tváří svou na zem.'),
(1553859,54,9,17,50,'A tak přemohl David Filistinského prakem a kamenem, a udeřiv Filistinského, zabil jej, ačkoli David žádného meče v ruce neměl.'),
(1553860,54,9,17,51,'A přiběh David, stál nad Filistinským. Potom pochytiv meč jeho, dobyl ho z pošvy a zabil jej, a sťal jím hlavu jeho. To vidouce Filistinští, že umřel nejsilnější jejich, utíkali.'),
(1553861,54,9,17,52,'A protož vstavše muži Izraelští a Judští, zkřikli a honili Filistinské, až kde se vchází do údolí, a až k branám Akaron. I padali, raněni jsouce, Filistinští po cestě k Saraim, až do Gát a až do Akaron.'),
(1553862,54,9,17,53,'A navrátivše se synové Izraelští od honění Filistinských, vzebrali tábor jejich.'),
(1553863,54,9,17,54,'Potom David vzav hlavu toho Filistinského, přinesl ji do Jeruzaléma, a odění jeho složil v stanu svém.'),
(1553864,54,9,17,55,'Tehdáž pak, když viděl Saul Davida jdoucího proti tomu Filistinskému, řekl Abnerovi hejtmanu vojska: Abner, čí jest syn ten mládenček? Odpověděl Abner: Jako jest živa duše tvá, králi, že nevím.'),
(1553865,54,9,17,56,'Ale král řekl: Zeptej ty se, čí jest syn mládenec ten.'),
(1553866,54,9,17,57,'Když se pak vracoval David od zabití Filistinského toho, pojav ho Abner, přivedl jej před Saule, an drží hlavu Filistinského v ruce své.'),
(1553867,54,9,17,58,'I řekl jemu Saul: Čí jsi syn, mládenče? Odpověděl David: Syn služebníka tvého Izai Betlémského.'),
(1553868,54,9,18,1,'I stalo se, že když přestal mluviti k Saulovi, duše Jonatova spojila se s duší Davidovou, tak že ho zamiloval Jonata jako sebe samého.'),
(1553869,54,9,18,2,'A tak Saul vzal jej k sobě toho dne, a nedopustil mu navrátiti se do domu otce jeho.'),
(1553870,54,9,18,3,'I učinil Jonata s Davidem smlouvu, proto že ho miloval jako duši svou.'),
(1553871,54,9,18,4,'A složiv Jonata s sebe plášť, kterýmž byl odín, dal jej Davidovi, i roucho své, až do meče svého, a až do lučiště svého, i do pasu svého.'),
(1553872,54,9,18,5,'Vycházel pak David, k čemuž ho koli posílal Saul, opatrně sobě počínaje. I ustanovil ho Saul nad vojáky, a líbil se všemu lidu, též i služebníkům Saulovým.'),
(1553873,54,9,18,6,'Stalo se pak, když se oni domů brali, a David též se navracoval od zabití Filistinského, že vyšly ženy z každého města Izraelského, zpívajíce a plésajíce, vstříc Saulovi králi s bubny, s veselím a s husličkami.'),
(1553874,54,9,18,7,'A prozpěvovaly jedny po druhých ženy ty, hrajíce, a řekly: Porazilť jest Saul svůj tisíc, ale David svých deset tisíců.'),
(1553875,54,9,18,8,'I rozhněval se Saul náramně, nebo nelíbila se mu ta řeč. Pročež řekl: Dali Davidovi deset tisíc, a mně dali toliko tisíc. Co mu ještě přes to přivlastní, leč království?'),
(1553876,54,9,18,9,'Protož Saul zlobivě hleděl na Davida od toho dne i vždycky.'),
(1553877,54,9,18,10,'Stalo se pak druhého dne, že duch Boží zlý napadl Saule, a prorokoval u prostřed domu svého, a David hral rukou svou jako i jindy vždycky. Saul pak měl kopí v ruce své.'),
(1553878,54,9,18,11,'I vyhodil Saul kopí,řka: Prohodím Davida až do stěny. Ale David uhnul se jemu po dvakrát.'),
(1553879,54,9,18,12,'A bál se Saul Davida, proto že Hospodin byl s ním, a od Saule odstoupil.'),
(1553880,54,9,18,13,'Protož vybyl ho Saul od sebe, a učinil jej sobě hejtmanem nad tisíci; kterýžto vycházel i vcházel před lidem.'),
(1553881,54,9,18,14,'David pak ve všech cestách svých opatrně sobě počínal, nebo Hospodin byl s ním.'),
(1553882,54,9,18,15,'A když to viděl Saul, že sobě velmi opatrně počíná, bál se ho.'),
(1553883,54,9,18,16,'Ale všecken Izrael i Juda miloval Davida, nebo vycházel i vcházel před nimi.'),
(1553884,54,9,18,17,'Tedy řekl Saul Davidovi: Aj, dceru svou starší Merob dámť za manželku, toliko mi buď muž silný, a veď boje Hospodinovy. (Saul pak myslil: Nechť neschází od mé ruky, ale od ruky Filistinských.)'),
(1553885,54,9,18,18,'I řekl David Saulovi: Kdo jsem já, a jakýž jest rod můj a čeled otce mého v Izraeli, abych byl zetěm královým?'),
(1553886,54,9,18,19,'I stalo se, že když již Merob dcera Saulova měla dána býti Davidovi, dána jest Adrielovi Molatitskému za manželku.'),
(1553887,54,9,18,20,'Milovala pak Míkol dcera Saulova Davida; což když oznámili Saulovi, líbilo se to jemu.'),
(1553888,54,9,18,21,'(Nebo řekl Saul: Dámť mu ji, aby mu byla osídlem, a aby proti němu byla ruka Filistinských.) A tak řekl Saul Davidovi: Po této druhé budeš mi již zetěm.'),
(1553889,54,9,18,22,'I rozkázal Saul služebníkům svým: Mluvte k Davidovi tajně, řkouce: Aj, libuje tě sobě král, a všickni služebníci jeho laskavi jsou na tebe; nyní tedy budiž zetěm královým.'),
(1553890,54,9,18,23,'A když mluvili služebníci Saulovi v uši Davidovy slova ta, odpověděl David: Zdaliž se vám malá věc zdá, býti zetěm královým? A já jsem člověk chudý a opovržený.'),
(1553891,54,9,18,24,'Tedy služebníci Saulovi oznámili jemu, řkouce: Taková slova mluvil David.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553892,54,9,18,25,'I řekl Saul: Takto rcete Davidovi: Není žádostiv král věna, toliko sto obřízek Filistinských, aby byla pomsta nad nepřátely královskými. (Saul pak to obmýšlel, aby David upadl v ruku Filistinských.)'),
(1553893,54,9,18,26,'Protož oznámili služebníci jeho Davidovi slova ta, a líbilo se to Davidovi, aby byl zetěm královým. Ještě se pak nebyli vyplnili dnové ti,'),
(1553894,54,9,18,27,'Když vstav David, odšel, on i muži jeho, a zbil z Filistinských dvě stě mužů, jejichž obřízky přinesl David, a z úplna je dali králi, aby byl zetěm královým. I dal jemu Saul Míkol dceru svou za manželku.'),
(1553895,54,9,18,28,'A vida Saul, nýbrž zkušené maje, že jest Hospodin s Davidem, a že Míkol dcera jeho miluje ho,'),
(1553896,54,9,18,29,'Ještě tím více Saul obával se Davida. I byl Saul nepřítelem Davidovým po všecky dny.'),
(1553897,54,9,18,30,'Vtrhovali pak do země knížata Filistinská; i bývalo, že kdyžkoli vycházeli, opatrněji sobě počínal David proti nim nade všecky služebníky Saulovy, pročež i jméno jeho bylo velmi slavné.'),
(1553898,54,9,19,1,'Mluvil pak Saul k Jonatovi synu svému a ke všechněm služebníkům svým, aby zamordovali Davida, ale Jonata syn Saulův liboval sobě Davida velmi.'),
(1553899,54,9,19,2,'I oznámil to Jonata Davidovi, řka: Usiluje Saul otec můj, aby tě zabil; protož nyní šetř se, prosím, až do jitra, a usadě se v skrytě, schovej se.'),
(1553900,54,9,19,3,'Ale jáť vyjdu a státi budu při boku otci svému na poli, kdež ty budeš, a budu mluviti o tobě s otcem svým, a čemuž vyrozumím, oznámím tobě.'),
(1553901,54,9,19,4,'I mluvil Jonata o Davidovi dobře Saulovi otci svému, a řekl: Nechť nehřeší král proti služebníku svému Davidovi, nebť jest nic tobě neprovinil, nýbrž správa jeho jest tobě velmi užitečná.'),
(1553902,54,9,19,5,'Nebo se opovážil života svého a zabil Filistinského, a učinil Hospodin vysvobození veliké všemu Izraeli. Viděls to a radoval jsi se. Pročež bys tedy hřešil proti krvi nevinné, chtěje zabiti Davida bez příčiny?'),
(1553903,54,9,19,6,'I uposlechl Saul řeči Jonatovy a přisáhl Saul, řka: Živť jest Hospodin, žeť nebude zabit.'),
(1553904,54,9,19,7,'Tedy Jonata povolal Davida, a oznámil jemu Jonata všecka slova tato. A přivedl Jonata Davida k Saulovi, i byl před ním jako i prvé.'),
(1553905,54,9,19,8,'Vznikla pak opět válka; a vytáh David, bojoval proti Filistinským, a porazil je porážkou velikou, a utekli před ním.'),
(1553906,54,9,19,9,'V tom duch Hospodinův zlý napadl Saule, kterýž v domě svém seděl, maje kopí své v ruce své, a David hrál rukou před ním.'),
(1553907,54,9,19,10,'Ale Saul chtěl prohoditi Davida kopím až do stěny; kterýž uhnul se mu, a udeřilo kopí v stěnu. A tak David utekl a vynikl z nebezpečenství té noci.'),
(1553908,54,9,19,11,'Potom poslal Saul posly k domu Davidovu, aby ho střáhli a zabili jej ráno. I oznámila to Davidovi Míkol manželka jeho, řkuci: Jestliže se neopatříš noci této, zítra zabit budeš.'),
(1553909,54,9,19,12,'A protož spustila Míkol Davida oknem, kterýž odšed, utekl a vynikl z nebezpečenství.'),
(1553910,54,9,19,13,'Vzala pak Míkol obraz a vložila na lůže, a polštář kozí položila v hlavách jeho a přikryla šaty.'),
(1553911,54,9,19,14,'Tedy Saul poslal posly, aby vzali Davida. I řekla: Jest nemocen.'),
(1553912,54,9,19,15,'Opět poslal Saul posly, aby pohleděli na Davida, řka: Přineste ho na lůži ke mně, ať ho zabiji.'),
(1553913,54,9,19,16,'A když přišli poslové, a aj, obraz ležel na lůži a polštář kozí v hlavách jeho.'),
(1553914,54,9,19,17,'I řekl Saul k Míkol: Proč jsi mne tak podvedla a pustilas nepřítele mého, aby ušel? Odpověděla Míkol Saulovi: On mi řekl: Propusť mne, sic jinak zabiji tě.'),
(1553915,54,9,19,18,'David tedy utíkaje, vynikl z nebezpečenství, a přišed k Samuelovi do Ráma, oznámil jemu všecko, co mu Saul učinil. I odšel on i Samuel, a bydlili v Náiot.'),
(1553916,54,9,19,19,'Oznámeno pak bylo Saulovi, řka: Aj, David jest v Náiot v Ráma.'),
(1553917,54,9,19,20,'I poslal Saul posly, aby jali Davida. Kteříž když viděli zástup proroků prorokujících, a Samuele jim představeného, an stojí, sstoupil také na posly Saulovy Duch Boží, a prorokovali i oni.'),
(1553918,54,9,19,21,'To když oznámili Saulovi, poslal jiné posly, a prorokovali také i oni; a opět poslal Saul třetí posly, a i ti prorokovali.'),
(1553919,54,9,19,22,'Šel tedy již sám do Ráma a přišel až k čisterni veliké, kteráž jest v Socho, a zeptal se, řka: Kde jest Samuel a David? I řekl někdo: Aj, jsou v Náiot v Ráma.'),
(1553920,54,9,19,23,'I šel tam do Náiot v Ráma; a sstoupil i na něj Duch Boží, a jda dále, prorokoval, až i přišel do Náiot v Ráma.'),
(1553921,54,9,19,24,'Kdežto svlékl také sám roucho své a prorokoval i on před Samuelem, a padna, ležel svlečený celý ten den a noc. Odkudž se říká: Zdali také Saul mezi proroky?'),
(1553922,54,9,20,1,'V tom utíkaje David z Náiot, kteréž jest v Ráma, přišel a mluvil před Jonatou: Což jsem učinil? Jaká jest nepravost má? A jaký jest hřích můj před otcem tvým, že hledá bezživotí mého?'),
(1553923,54,9,20,2,'Kterýž řekl jemu: Odstup to, neumřeš. Aj, nečiníť otec můj ničeho ani velikého ani malého, čehož by se mi nesvěřil. Jak by tedy otec můj tajil to přede mnou! Neníť toho.'),
(1553924,54,9,20,3,'Nadto přisáhl také David, (to promluviv: Dobřeť ví otec tvůj, že jsi laskav na mne, protož myslí: Nechť neví o tom Jonata, aby neměl zámutku). Nýbrž jistě, živť jest Hospodin, a živať jest duše tvá, že sotva jest kročej mezi mnou a mezi smrtí.'),
(1553925,54,9,20,4,'Odpověděl Jonata Davidovi: Pověz, čehokoli žádáš, a učiním tobě.'),
(1553926,54,9,20,5,'I řekl David Jonatovi: Aj, zítra bude novměsíce, kdyžto já mám obyčej sedati s králem k jídlu; protož propusť mne, a skryji se na poli až do třetího večera.'),
(1553927,54,9,20,6,'Jestliže by se zvláštně na mne ptal otec tvůj, řekneš: Prosil mne velice David, aby sběhl do Betléma města svého; nebo obět výroční tam míti má všecka jeho rodina.'),
(1553928,54,9,20,7,'Řekne-liť: Dobře, pokoj služebníku tvému; pakliť se rozzlobí, věz, žeť se doplnila zlost jeho.'),
(1553929,54,9,20,8,'A tak učiníš milosrdenství s služebníkem svým, poněvadž jsi v smlouvu Hospodinovu uvedl služebníka svého s sebou. Pakliť jest na mně nepravost, zabí mne sám; nebo k otci svému proč bys mne vodil?'),
(1553930,54,9,20,9,'I řekl Jonata: Odstup to od tebe; nebo zvím-liť to jistotně, že by se doplnila zlost otce mého, aby přišla na tě, zdaliž neoznámím tobě toho?'),
(1553931,54,9,20,10,'Řekl také David Jonatovi: Kdož mi oznámí, jestliže odpoví tobě otec tvůj něco tvrdě?'),
(1553932,54,9,20,11,'Odpověděl Jonata Davidovi: Poď, vyjděme na pole. I vyšli oba na pole.'),
(1553933,54,9,20,12,'Opět řekl Jonata Davidovi: Hospodin Bůh Izraelský, (hned jakž porozumím na otci svém, okolo tohoto času zítra neb pozejtří, an bude dobře s Davidem, jestliže nepošli tehdáž k tobě, a neoznámím-liť),'),
(1553934,54,9,20,13,'Toto učiň Hospodin Jonatovi a toto přidej. Pakliť se bude líbiti otci mému uvésti zlé na tebe, takéť i to zjevím tobě a propustím tě; i půjdeš v pokoji, a Hospodin budiž s tebou, jakož byl s otcem mým.'),
(1553935,54,9,20,14,'A zdaliž i ty, dokud jsem živ, neučiníš se mnou milosrdenství Hospodinova, ano bychť i umřel,'),
(1553936,54,9,20,15,'Tak že neodvrátíš milosrdenství svého od domu mého až na věky, zvláště tehdáž, když Hospodin vypléní nepřátely Davidovy, jednoho každého se svrchku země.'),
(1553937,54,9,20,16,'A tak učinil Jonata smlouvu s domem Davidovým, řka: Vyhledávejž Hospodin toho z ruky nepřátel Davidových.'),
(1553938,54,9,20,17,'Ještě i přísahou zavázal Jonata v lásce odměnné k sobě Davida; nebo jakož miloval duši svou, tak jej miloval.'),
(1553939,54,9,20,18,'I řekl mu Jonata: Zítra bude novměsíce, a bude se ptáti na tebe, když prázdné bude místo tvé.'),
(1553940,54,9,20,19,'Do třetího tedy dne skrývaje se, sstoupíš rychle a přijdeš k tomu místu, na kterémžs se byl skryl, když se to jednalo, a pobudeš u kamene pocestných.'),
(1553941,54,9,20,20,'A já tři střely vystřelím po straně k němu, směřuje sobě k cíli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553942,54,9,20,21,'Potom hned pošli pachole a dím: Jdi, shledej střely. Jestliže prostě řeknu služebníku: Hle, střely za tebou blíže sem, přines je, tedy přiď, nebo jest pokoj tobě, a neníť žádného nebezpečenství, živť jest Hospodin.'),
(1553943,54,9,20,22,'Pakli takto řeknu pacholeti: Hle, střely jsou před tebou dále, tedy odejdi, nebo propustil tě Hospodin.'),
(1553944,54,9,20,23,'Řeči pak této, kterouž jsme mluvili já a ty, aj, Hospodin svědek bude mezi mnou a mezi tebou až na věky.'),
(1553945,54,9,20,24,'A tak skryl se David na poli. Byl pak novměsíce, i sedl král za stůl k jídlu.'),
(1553946,54,9,20,25,'A seděl král na stolici své, jakž obyčej měl, na stolici u stěny, ale Jonata povstal. Sedl také Abner podlé Saule, a místo Davidovo zůstalo prázdné.'),
(1553947,54,9,20,26,'A však toho dne Saul nic neříkal, nebo myslil: Něco se mu přihodilo, buď že čistý jest neb nečistý.'),
(1553948,54,9,20,27,'Stalo se pak nazejtří, druhého dne novměsíce, že opět prázdné bylo místo Davidovo. I řekl Saul Jonatovi synu svému: Proč nepřišel syn Izai ani včera ani dnes k jídlu?'),
(1553949,54,9,20,28,'Odpověděl Jonata Saulovi: Velice mne prosil David, aby šel do Betléma.'),
(1553950,54,9,20,29,'A řekl: Odpusť mne, prosím, nebo obět má míti rodina naše v městě, a bratr můj sám rozkázal mi přijíti; nyní tedy, nalezl-li jsem milost před očima tvýma, nechť se odtrhnu, prosím, abych navštívil bratří své. Tou příčinou nepřišel k stolu královskému.'),
(1553951,54,9,20,30,'I rozhněval se Saul náramně na Jonatu, a řekl jemu: Synu převrácený a urputný, zdaliž nevím, že jsi zvolil sobě syna Izai k hanbě své, i k hanbě a lehkosti matky své?'),
(1553952,54,9,20,31,'Nebo po všecky dny, v nichž bude živ syn Izai na zemi, nebudeš upevněn ty, ani království tvé. Protož hned pošli a přiveď jej ke mně, nebť jest hoden smrti.'),
(1553953,54,9,20,32,'Odpověděl Jonata Saulovi otci svému, a řekl jemu: Proč má umříti? Což jest učinil?'),
(1553954,54,9,20,33,'I hodil Saul kopím na něj, aby ho zabil. Tedy seznav Jonata, že uložil otec jeho zabiti Davida,'),
(1553955,54,9,20,34,'Vstal od stolu Jonata, rozpálen jsa hněvem, a nejedl toho druhého dne novuměsíce pokrmu, nebo bolestil pro Davida, a že ho tak zlehčil otec jeho.'),
(1553956,54,9,20,35,'Protož stalo se ráno, že vyšel Jonata na pole k času uloženému Davidovi, a pachole malé s ním.'),
(1553957,54,9,20,36,'Tedy řekl pacholeti svému: Běž a shledej střely, kteréž já vystřelím. I běželo pachole, a on střílel daleko před něj.'),
(1553958,54,9,20,37,'Když pak přišlo pachole až k cíli, k němuž střílel Jonata, volal Jonata za pacholetem a řekl: Zdaliž není střely před tebou tam dále?'),
(1553959,54,9,20,38,'Opět volal Jonata za pacholetem: Rychle pospěš, nestůj. A tak sebravši pachole Jonatovo střely, vrátilo se k svému pánu.'),
(1553960,54,9,20,39,'(Pachole pak nic nevědělo, toliko Jonata a David věděli, co se jedná.)'),
(1553961,54,9,20,40,'I dal Jonata braň svou pacholeti, kteréž s ním bylo, a řekl jemu: Jdi, dones do města.'),
(1553962,54,9,20,41,'A když odešlo pachole, vstal David s strany polední, a padna na tvář svou k zemi, poklonil se třikrát; a políbivše jeden druhého plakali oba, až Jonata Davida pozdvihl.'),
(1553963,54,9,20,42,'I řekl Jonata Davidovi: Jdiž u pokoji, a což jsme sobě oba přisáhli ve jménu Hospodinovu, řkouce: Hospodin budiž svědkem mezi mnou a tebou, i mezi semenem mým a mezi semenem tvým, nechť trvá až na věky.'),
(1553964,54,9,20,43,'A tak vstav David, odšel, Jonata pak navrátil se do města.'),
(1553965,54,9,21,1,'Tedy přišel David do Nobe k Achimelechovi knězi. I ulek se Achimelech, vyšel vstříc Davidovi a řekl jemu: Cože to, že jsi sám, a není žádného s tebou?'),
(1553966,54,9,21,2,'Odpověděl David Achimelechovi knězi: Král mi poručil nějakou věc, a řekl mi: Ať žádný nezvídá toho, proč tě posílám, a coť jsem poručil. Služebníkům pak uložil jsem jisté místo.'),
(1553967,54,9,21,3,'Protož nyní, co máš tu před rukama, dej v ruku mou, asi pět chlebů, aneb což na hotově máš.'),
(1553968,54,9,21,4,'Odpověděl kněz Davidovi a řekl: Nemámť chleba obecného před rukama, než toliko chléb svatý, však jestliže se toliko od žen zdrželi služebníci.'),
(1553969,54,9,21,5,'Odpověděl David knězi a řekl: Jistě ženy vzdáleny byly od nás, jakož včera tak i před včerejškem, když jsem vyšel; protož těla služebníků svatá jsou. Ač pak toto předsevzetí jest proti slušnosti, však i to dnes posvěceno bude pro tělo.'),
(1553970,54,9,21,6,'A tak dal jemu kněz chleby svaté; nebo nebylo tam chleba, jediné chlebové předložení, kteříž odloženi byli od tváři Hospodinovy, aby položeni byli chlebové teplí toho dne, když ti vzati byli.'),
(1553971,54,9,21,7,'(Byl pak tu jeden z služebníků Saulových v týž den, kterýž se tam pozadržel před Hospodinem, jehož jméno bylo Doeg Idumejský, nejpřednější mezi pastýři Saulovými.)'),
(1553972,54,9,21,8,'I řekl David Achimelechovi: Nemáš-liž zde kopí aneb meče? Nebo ani meče svého ani braně své nevzal jsem v ruku svou, proto že rozkaz královský dotíral.'),
(1553973,54,9,21,9,'Jemuž řekl kněz: Meč Goliáše Filistinského, kteréhož jsi zabil v údolí Elah, aj, ten jest zde obvinutý v roucho za efodem. Jestliže jej chceš sobě vzíti, vezmi, nebo zde jiného není kromě toho. I řekl David: Neníť přes ten, dejž mi jej.'),
(1553974,54,9,21,10,'Tedy vstal David, a utekl toho dne před Saulem, a přišel k Achisovi králi Gát.'),
(1553975,54,9,21,11,'Služebníci pak Achisovi řekli jemu: Zdaliž tento není David, král země? Zdaliž neprozpěvovali tomuto po houfích, řkouce: Porazil Saul svůj tisíc, David pak svých deset tisíců.'),
(1553976,54,9,21,12,'I složil David ta slova v srdci svém, a bál se velmi Achisa krále Gát.'),
(1553977,54,9,21,13,'Protož změnil způsob svůj před očima jejich, a bláznem se dělal, jsa v rukou jejich; psal také po vratech u brány, a pouštěl sliny po bradě své.'),
(1553978,54,9,21,14,'Tedy řekl Achis služebníkům svým: Hle, viděvše člověka blázna, pročež jste ho ke mně přivedli?'),
(1553979,54,9,21,15,'Nedostává-liž se mi bláznů, že jste uvedli tohoto, aby bláznil přede mnou? Ten-liž má vjíti do mého domu?'),
(1553980,54,9,22,1,'A tak odšel odtud David, skryl se v jeskyni Adulam. To když uslyšeli bratří jeho i všecken dům otce jeho, sešli se tam k němu.'),
(1553981,54,9,22,2,'A shromáždili se k němu, kteřížkoli byli v ssoužení, a kteřížkoli byli zadlužilí, a kteřížkoli byli v hořkosti ducha, a byl nad nimi knížetem, tak že jich bylo s ním okolo čtyř set mužů.'),
(1553982,54,9,22,3,'Potom odšel odtud David do Masfa Moábského a řekl králi Moábskému: Prosím, nechť vcházejí k vám i vycházejí otec můj a matka má, dokudž nezvím, co se mnou učiní Bůh.'),
(1553983,54,9,22,4,'I přivedl je před krále Moábského, a bydlili s ním po všecky dny, v nichž zůstával David na tom hradě.'),
(1553984,54,9,22,5,'Ale prorok Gád řekl Davidovi: Nebývejž déle na tom hradě, jdi, navrať se do země Judské. I odšel David, a přišel do lesa Haret.'),
(1553985,54,9,22,6,'V tom uslyšel Saul, že by se zjevil David i muži, kteříž byli s ním. Saul pak bydlil v Gabaa pod hájem v Ráma, maje kopí své v rukou svých, a všickni služebníci jeho stáli před ním.'),
(1553986,54,9,22,7,'I řekl Saul služebníkům svým, kteříž stáli před ním: Slyšte medle, synové Jemini: Všechněm-li vám dá syn Izai pole a vinice? Všecky-li vás postaví za správce nad tisíci a sty,'),
(1553987,54,9,22,8,'Že jste se všickni spikli proti mně, aniž jest, kdo by mi oznámil? Již i syn můj učinil smlouvu s synem Izai, a však žádný z vás nelituje mne, aniž mi kdo oznámí, že pozdvihl syn můj služebníka mého proti mně, aby mi zálohy strojil, jakož se to již děje.'),
(1553988,54,9,22,9,'Odpověděl pak Doeg Idumejský, kterýž též stál s služebníky Saulovými, a řekl: Viděl jsem syna Izai, an přišel do Nobe k Achimelechovi synu Achitobovu.'),
(1553989,54,9,22,10,'Kterýž radil se o něho s Hospodinem a dal jemu potravy, také i meč Goliáše Filistinského dal jemu.'),
(1553990,54,9,22,11,'I poslal král, aby zavolali Achimelecha syna Achitobova, kněze, i vší čeledi otce jeho, totiž kněží, kteříž byli v Nobe. I přišli všickni před krále.'),
(1553991,54,9,22,12,'Tedy řekl Saul: Slyš nyní, synu Achitobův. Kterýž odpověděl: Ej, pane můj.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1553992,54,9,22,13,'I dí k němu Saul: Proč jste se spikli proti mně, ty a syn Izai, když jsi jemu dal chléb a meč, a radils se s Bohem o něj, aby povstal proti mně k strojení mi záloh, jakož se to již děje?'),
(1553993,54,9,22,14,'Odpovídaje Achimelech králi, řekl: A kdo jest tak věrný ze všech služebníků tvých jako David, kterýž i zetěm královým jest, kterýž kráčí v poslušenství tvém, a vzácný jest v domě tvém?'),
(1553994,54,9,22,15,'Zdaliž jsem se nyní počal tázati Boha o něj? Odstup to ode mne. Nesčítejž král takové věci na služebníka svého, ani na koho z čeledi otce mého, neboť neví služebník tvůj o ničemž o tom ani nejmenší věci.'),
(1553995,54,9,22,16,'Ale král řekl: Smrtí umřeš Achimelechu, ty i všecken dům otce tvého.'),
(1553996,54,9,22,17,'I řekl král drabantům, kteříž stáli před ním: Obraťte se a zbíte kněží Hospodinovy, nebo i jejich ruka jest s Davidem; přes to vědouce, že utíká, nedali mi znáti. Služebníci však královští nechtěli vztáhnouti rukou svých, ani se obořiti na kněží Hospodinovy.'),
(1553997,54,9,22,18,'A protož řekl král Doegovi: Obrať ty se, a pobí ty kněží. Takž Doeg Idumejský obrátiv se, obořil se na kněží, a zbil toho dne osmdesáte a pět mužů, kteříž nosili efod lněný.'),
(1553998,54,9,22,19,'Nobe také město kněžské vyhubil ostrostí meče, od muže až do ženy, od malého až do požívajícího prsí, voly i osly, i dobytky pobil ostrostí meče.'),
(1553999,54,9,22,20,'Jediný toliko syn Achimelechův, syna Achitobova, jehož jméno bylo Abiatar, ušel a utekl k Davidovi.'),
(1554000,54,9,22,21,'Tedy oznámil Abiatar Davidovi, že Saul zmordoval kněží Hospodinovy.'),
(1554001,54,9,22,22,'I řekl David Abiatarovi: Vědělť jsem toho dne, když tam byl Doeg Idumejský, že jistotně oznámí Saulovi; jáť jsem přičinu dal k zhubení všech duší domu otce tvého.'),
(1554002,54,9,22,23,'Zůstaň u mne, neboj se; nebo kdož hledati bude bezživotí mého, hledati bude bezživotí tvého, ale ochráněn budeš u mne.'),
(1554003,54,9,23,1,'Tedy oznámili Davidovi, řkouce: Aj, Filistinští dobývají Cejly a loupí dvory.'),
(1554004,54,9,23,2,'Protož tázal se David Hospodina, řka: Mám-li jíti a udeřiti na ty Filistinské? I odpověděl Hospodin Davidovi: Jdi a porazíš Filistinské, i Cejlu vysvobodíš.'),
(1554005,54,9,23,3,'Muži pak Davidovi řekli jemu: Aj, my zde v Judstvu bojíme se, čím více, když půjdeme k Cejle proti vojskům Filistinských.'),
(1554006,54,9,23,4,'A tak opět David tázal se Hospodina. Jemuž odpověděl Hospodin a řekl: Vstana, vytáhni k Cejle, neboť dám Filistinské v ruce tvé.'),
(1554007,54,9,23,5,'I táhl David a muži jeho k Cejle, a bojoval s Filistinskými, a zajal dobytky jejich. I porazil je ranou velikou, a tak vysvobodil David obyvatele Cejly.'),
(1554008,54,9,23,6,'Stalo se pak, že když utíkal Abiatar syn Achimelechův k Davidovi do Cejly, dostal se efod v ruce jeho.'),
(1554009,54,9,23,7,'Potom oznámeno bylo Saulovi, že přitáhl David do Cejly. I řekl Saul: Dalť ho Bůh v ruku mou, nebo zavřel se, všed do města hrazeného a zavřitého.'),
(1554010,54,9,23,8,'I svolal Saul všecken lid k boji, aby táhl k Cejle, a oblehl Davida i muže jeho.'),
(1554011,54,9,23,9,'A zvěděv David, že Saul tajně ukládá o něm zle, řekl Abiatarovi knězi: Vezmi na se efod.'),
(1554012,54,9,23,10,'I řekl David: Hospodine, Bože Izraelský, za jistou věc slyšel služebník tvůj, že strojí Saul přitáhnouti k Cejle, aby zkazil město pro mne.'),
(1554013,54,9,23,11,'Vydali-li by mne muži Cejly v ruce jeho? A přitáhl-li by Saul, jakž slyšel služebník tvůj? Hospodine, Bože Izraelský, oznam, prosím, služebníku svému. Odpověděl Hospodin: Přitáhl by.'),
(1554014,54,9,23,12,'Řekl ještě David: Vydali-li by mne obyvatelé Cejly i muže mé v ruce Saulovy? Odpověděl Hospodin: Vydali by.'),
(1554015,54,9,23,13,'Vstav tedy David a muži jeho, téměř šest set mužů, vytáhli z Cejly a šli ustavičně, kamž jíti mohli. Saulovi pak povědíno, že ušel David z Cejly; i nechal tažení.'),
(1554016,54,9,23,14,'Byl pak David na poušti v místech bezpečných, a bydlil na hoře, na poušti Zif. A ačkoli hledal ho Saul po všecky ty dny, však nevydal ho Bůh v ruku jeho.'),
(1554017,54,9,23,15,'Vida tedy David, že Saul vytáhl hledati bezživotí jeho, byl na poušti Zif v lese.'),
(1554018,54,9,23,16,'Vstav pak Jonata syn Saulův, přišel k Davidovi do lesa, a posilnil ruky jeho v Bohu.'),
(1554019,54,9,23,17,'A řekl jemu: Neboj se, neboť nenalezne tebe ruka Saule otce mého, ale ty kralovati budeš nad Izraelem, a já budu druhý po tobě. Však i Saul otec můj zná to.'),
(1554020,54,9,23,18,'I učinili smlouvu oba před Hospodinem; a David zůstal v lese, Jonata pak navrátil se do domu svého.'),
(1554021,54,9,23,19,'Tedy přišli Zifejští k Saulovi do Gabaa, řkouce: Zdaliž David nepokrývá se u nás v horách, v lese, na pahrbku Hachile, kterýž jest na pravé straně pouště.'),
(1554022,54,9,23,20,'Protož nyní podlé vší žádosti duše své, ó králi, přitáhni stěží, my se pak přičiníme, abychom jej vydali v ruce královy.'),
(1554023,54,9,23,21,'I řekl Saul: Požehnaní vy od Hospodina, že mne litujete.'),
(1554024,54,9,23,22,'Jdětež medle, ujisťte se tím ještě lépe, přezvězte a shlédněte místo jeho, kam se obrátí, kdo ho tam viděl; nebo mi praveno, že divných chytrostí užívá.'),
(1554025,54,9,23,23,'Vyšpehujtež tedy a vyzvězte všecky skrejše, v nichž se kryje, a navraťte se ke mně s věcí jistou, i potáhnu s vámi, a jestliže v zemi jest, hledati ho budu ve všech tisících Judských.'),
(1554026,54,9,23,24,'Kteřížto vstavše, navrátili se do Zif před Saulem; David pak a muži jeho byli na poušti Maon, na rovinách po pravé straně pouště.'),
(1554027,54,9,23,25,'Nebo jakž vytáhl Saul s lidem svým hledati ho, oznámeno bylo to Davidovi, kterýž sstoupil s skály a bydlil na poušti Maon. O čemž Saul uslyšav, honil Davida po poušti Maon.'),
(1554028,54,9,23,26,'A tak Saul táhl s jedné strany hory, David pak a muži jeho po druhé straně hory. A pospíšil David, aby mohl utéci od tváři Saulovy; nebo Saul s lidem svým obkličovali Davida i muže jeho, aby je zjímali.'),
(1554029,54,9,23,27,'V tom přišel posel k Saulovi, řka: Pospěš a přiď, nebo Filistinští vtrhli do země.'),
(1554030,54,9,23,28,'A protož navrátil se Saul od honění Davida, táhl proti Filistinským. Pročež nazvali to místo: Skála rozdělující.'),
(1554031,54,9,24,1,'Odšed pak David odtud, bydlil v místech bezpečných Engadi.'),
(1554032,54,9,24,2,'I stalo se, že když se navrátil Saul od honění Filistinských, oznámili jemu, řkouce: Hle, David jest na poušti Engadi.'),
(1554033,54,9,24,3,'Tedy vzav Saul tři tisíce mužů vybraných ze všeho Izraele, odšel hledati Davida a mužů jeho na skalách kamsíků.'),
(1554034,54,9,24,4,'I přišel k stájím ovcí blízko cesty, kdež byla jeskyně, do níž všel Saul na potřebu; David pak a muži jeho seděli po stranách v té jeskyni.'),
(1554035,54,9,24,5,'Protož řekli muži Davidovi jemu: Aj, tento jest den, o němž tobě mluvil Hospodin, řka: Aj, já dám nepřítele tvého v ruku tvou, abys mu učinil, jakť se koli líbiti bude. Tedy vstav David, uřezal tiše kus pláště Saulova.'),
(1554036,54,9,24,6,'Potom pak padlo to těžce na srdce Davidovi, že uřezal křídlo pláště Saulova.'),
(1554037,54,9,24,7,'Pročež řekl mužům svým: Uchovejž mne Hospodin, abych to učiniti měl pánu mému, pomazanému Hospodinovu, abych vztáhnouti měl ruku svou na něj, poněvadž jest pomazaný Hospodinův.'),
(1554038,54,9,24,8,'A tak zabránil David mužům svým těmi slovy, a nedal jim povstati proti Saulovi. Saul také vyšed z té jeskyně, bral se cestou svou.'),
(1554039,54,9,24,9,'Potom vstal i David, a vyšed z jeskyně, volal za Saulem, řka: Pane můj králi! I ohlédl se Saul zpět, David pak sehnuv se tváří k zemi, poklonil se jemu.'),
(1554040,54,9,24,10,'A řekl David Saulovi: I proč posloucháš řečí lidských, kteříž praví: Hle, David hledá tvého zlého.'),
(1554041,54,9,24,11,'Aj, dnešního dne viděti mohly oči tvé, že tě byl vydal Hospodin dnes v ruku mou v jeskyni. A byloť mi řečeno, abych tě zabil, ale šanoval jsem tě; nebo řekl jsem: Nevztáhnuť ruky své na pána svého, poněvadž jest pomazaný Hospodinův.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554042,54,9,24,12,'Nýbrž, otče můj, pohleď a viz kus pláště svého v ruce mé, a žeť jsem nechtěl, odřezuje křídlo pláště tvého, zabiti tebe. Poznejž tedy a viz, žeť není v úmysle mém nic zlého, ani jaké převrácenosti, a žeť jsem nezhřešil proti tobě; ty pak číháš na duši mou, abys mi ji odjal.'),
(1554043,54,9,24,13,'Sudiž Hospodin mezi mnou a mezi tebou, a pomstiž mne Hospodin nad tebou, ale ruka má nebude proti tobě.'),
(1554044,54,9,24,14,'Jakož vzní ono přísloví starých: Od bezbožných vychází bezbožnost; protož nebudeť ruka má proti tobě.'),
(1554045,54,9,24,15,'Na koho to jen vytáhl král Izraelský? Koho to honíš? Psa mrtvého, blechu jednu.'),
(1554046,54,9,24,16,'Ale budeť Hospodin soudce; on nechť rozsoudí mezi mnou a tebou, a nechť pohledí a vyvede při mou, a vysvobodí mne z ruky tvé.'),
(1554047,54,9,24,17,'Když pak přestal David mluviti slov těch Saulovi, odpověděl Saul: Není-liž to hlas tvůj, synu můj Davide? A pozdvih Saul hlasu svého, plakal.'),
(1554048,54,9,24,18,'A řekl Davidovi: Spravedlivější jsi nežli já; nebo ty jsi mi odplatil se dobrým, já pak zlým tobě jsem se odplatil.'),
(1554049,54,9,24,19,'Ty zajisté ukázal jsi dnes, že mi činíš dobře; nebo ačkoli mne byl Hospodin zavřel v ruce tvé, však jsi mne nezabil.'),
(1554050,54,9,24,20,'Zdali kdo nalezna nepřítele svého, propustí ho po cestě dobré? Ale Hospodin odplatiž tobě dobrým za to, co jsi mi dnešního dne učinil.'),
(1554051,54,9,24,21,'Protož nyní, (vím, že jistotně kralovati budeš, a že stálé bude v ruce tvé království Izraelské),'),
(1554052,54,9,24,22,'Nyní, pravím, přisáhni mi skrze Hospodina, že nevypléníš semene mého po mně, a nevyhladíš jména mého z domu otce mého.'),
(1554053,54,9,24,23,'A tak přisáhl David Saulovi. I odšel Saul do domu svého, David pak a muži jeho vstoupili na bezpečné místo.'),
(1554054,54,9,25,1,'Mezi tím umřel Samuel. A shromáždil se všecken Izrael, i plakali ho, a pochovali jej v domě jeho v Ráma. Ale David vstav, šel na poušť Fáran.'),
(1554055,54,9,25,2,'Člověk pak nějaký byl v Maon, kterýž statek svůj měl na Karmeli. A byl člověk ten možný velmi, nebo měl tři tisíce ovec a tisíc koz, a tehdáž rovně střihl ovce své na Karmeli.'),
(1554056,54,9,25,3,'Muže pak toho jméno Nábal, a jméno ženy jeho Abigail. A byla žena ta opatrná a krásné tváři, ale muž její byl tvrdý a zlých povah, a byl z rodu Kálefova.'),
(1554057,54,9,25,4,'Protož uslyšav David na poušti, že by Nábal střihl ovce své,'),
(1554058,54,9,25,5,'Poslal deset služebníků, a řekl David těm služebníkům: Vstupte na Karmel, a jděte k Nábalovi, a pozdravte ho slovem mým přátelsky.'),
(1554059,54,9,25,6,'A rcete jemu takto: Zdráv buď, a pokoj tobě, pokoj domu tvému, i všemu, což máš, pokoj.'),
(1554060,54,9,25,7,'Slyšel jsem, že máš střižce, a pastýři tvoji bývali s námi; neučinili jsme jim žádné křivdy, aniž jim co zhynulo po všecky dny, v nichž byli na Karmeli.'),
(1554061,54,9,25,8,'Ptej se služebníků svých, a povědí tobě. Nyní tedy nechť naleznou mládenci milost před očima tvýma, nebo v den veselý přišli jsme; dej, prosím, což máš před rukama, služebníkům svým a synu svému Davidovi.'),
(1554062,54,9,25,9,'Přišedše tedy mládenci ti Davidovi, mluvili Nábalovi podlé všech slov těchto jménem Davidovým, a umlkli.'),
(1554063,54,9,25,10,'Odpověděl pak Nábal služebníkům Davidovým a řekl: Kdo jest David? A kdo syn Izai? Mnohotě nyní služebníků, kteříž se odtrhují jeden každý od pána svého.'),
(1554064,54,9,25,11,'Ano, vezmu já chléb svůj, a vodu svou a pokrmy své, kteréž jsem připravil střižcům svým, a dám je těm lidem, kterýchž neznám, ani vím, odkud jsou?'),
(1554065,54,9,25,12,'A obrátivše se služebníci Davidovi na cestu svou, navrátili se, a přišedše, oznámili jemu všecka slova ta.'),
(1554066,54,9,25,13,'I řekl David mužům svým: Připaš každý meč svůj. Kteříž když připásali jeden každý meč svůj, připásal také David meč svůj, a šlo za Davidem okolo čtyř set mužů, dvě stě pak pozůstalo u břemen.'),
(1554067,54,9,25,14,'A v tom Abigail, ženě Nábalově, oznámil mládenec jeden z služebníků, řka: Aj, poslal David posly s pouště, aby pozdravili pána našeho, ale on je ukřikal;'),
(1554068,54,9,25,15,'Ješto muži ti prospěšní nám byli velice, ani nám neučinili křivdy, aniž nám co zhynulo, když jsme bývali s nimi na poli.'),
(1554069,54,9,25,16,'Místo zdi byli nám v noci i ve dne po všecky dny, dokudž jsme s nimi byli, pasouce stáda.'),
(1554070,54,9,25,17,'Protož nyní pomysl a viz, co bys měla činiti, neboť již zlé věci hotové jsou na pána našeho i na všecken dům jeho; on pak jest tak zlobivý, že s ním nelze ani mluviti.'),
(1554071,54,9,25,18,'Tedy pospíšila Abigail, a vzala dvě stě chlebů, a dvě kožené láhvice vína, a pět ovcí připravených, a pět měr pražmy, a sto sušených hroznů, a dvě stě hrud fíků sušených, a vložila to na osly.'),
(1554072,54,9,25,19,'I řekla služebníkům svým: Jdětež napřed, a já za vámi půjdu. Ale muži svému Nábalovi neoznámila.'),
(1554073,54,9,25,20,'I stalo se, že vsedši na osla, sjížděla po stráni s hory, a aj, David a muži jeho sstupovali proti ní, a potkala se s nimi.'),
(1554074,54,9,25,21,'(David pak byl řekl: Jistě nadarmo jsem ostříhal všeho, což on měl na poušti, tak že nic nezahynulo ze všeho, což má; nebo mi se odplatil zlým za dobré.'),
(1554075,54,9,25,22,'Toto učiň Bůh nepřátelům Davidovým a toto přidej, jestliže zanechám do jitra ze všeho, což má, až do toho, kterýž močí na stěnu.)'),
(1554076,54,9,25,23,'Tedy uzřevši Abigail Davida, rychle ssedla s osla, a padla před Davidem na tvář svou, a poklonila se až k zemi.'),
(1554077,54,9,25,24,'A padši k nohám jeho, řekla: Na mně, pane můj, ta nepravost. Protož nechť mluví, prosím, služebnice tvá v uši tvé, a vyslyš slova děvky své.'),
(1554078,54,9,25,25,'Nechť se neobrací, prosím, pán můj myslí svou za mužem tím bezbožným Nábalem; nebo jakéž jest jméno jeho, takovýž jest. Nábal jméno jeho jest, a bláznovství jest při něm. Já pak služebnice tvá neviděla jsem služebníků pána mého, kteréž jsi byl poslal.'),
(1554079,54,9,25,26,'Protož nyní, pane můj, živť jest Hospodin, a živať jest duše tvá, že tě tobě zbránil Hospodin vylíti krve, a abys nemstil sám sebe. A protož nyní buďtež jako Nábal nepřátelé tvoji, a ti, kteříž hledají zlého pánu mému.'),
(1554080,54,9,25,27,'Teď pak dar tento, kterýž přinesla děvka tvá pánu svému, nechť jest dán služebníkům, kteříž chodí za pánem mým.'),
(1554081,54,9,25,28,'Odpusť, prosím, provinění děvce své, neboť jistě vzdělá Hospodin pánu mému dům stálý, poněvadž boje Hospodinovy pán můj vede, a nic zlého se nenalézá při tobě až posavad.'),
(1554082,54,9,25,29,'A byť i povstal člověk, aby tě stihal a hledal bezhrdlí tvého, budeť však duše pána mého svázána v svazku živých u Hospodina Boha tvého, duši pak nepřátel tvých jako z praku pryč zahodí.'),
(1554083,54,9,25,30,'A když učiní Hospodin pánu mému dobře podlé toho všeho, jakž zaslíbil tobě, a přikážeť, abys byl vůdcím nad Izraelem:'),
(1554084,54,9,25,31,'Tedy nebude to k zviklání ani k urážce srdce pánu mému, jako když by vylil krev bez příčiny, aneb když by se mstil pán můj. Když tedy učiní dobře Hospodin pánu mému, rozpoměň se na děvku svou.'),
(1554085,54,9,25,32,'I řekl David k Abigail: Požehnaný Hospodin Bůh Izraelský, že tě poslal dne tohoto mně v cestu;'),
(1554086,54,9,25,33,'A požehnaná řeč tvá, i ty požehnaná, že jsi zdržela mne dnes, abych nevylil krve a nemstil sám sebe.'),
(1554087,54,9,25,34,'A jistě, jako živ jest Hospodin Bůh Izraelský, kterýž mi zbránil, ať bych zle nečinil, že kdybys nebyla pospíšila a nevyšla mi v cestu, nebyl by zůstal Nábalovi do jitra ani močící na stěnu.'),
(1554088,54,9,25,35,'I přijal David z ruky její, což byla přinesla jemu, a řekl jí: Jdiž v pokoji do domu svého. Pohleď, uslyšel jsem prosbu tvou, a vážil jsem sobě osoby tvé.'),
(1554089,54,9,25,36,'A tak navrátila se Abigail k Nábalovi, an měl hody v domě svém jako hody královské; a srdce Nábalovo rozveselilo se bylo v něm, a byl opilý velmi. Pročež ona neoznámila jemu nejmenšího slova až do jitra.'),
(1554090,54,9,25,37,'Nazejtří pak, když z vína vystřízlivěl Nábal, tedy oznámila jemu žena jeho ty věci. I zmrtvělo v něm srdce jeho, a učiněn jest jako kámen.'),
(1554091,54,9,25,38,'A když pominulo takměř deset dní, porazil Hospodin Nábale,i umřel.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554092,54,9,25,39,'Uslyšev pak David, že by Nábal umřel, řekl: Požehnaný Hospodin, kterýž hodně pomstil pohanění mého nad Nábalem, a služebníka svého zdržel ode zlého, zlost pak Nábalovu shrnul Hospodin na hlavu jeho. Tedy poslal David a mluvil k Abigail, aby ji sobě vzal za manželku.'),
(1554093,54,9,25,40,'I přišli služebníci Davidovi k Abigail na Karmel, a mluvili s ní, řkouce: David poslal nás k tobě, aby tě vzal sobě za manželku.'),
(1554094,54,9,25,41,'Kterážto vstavši, poklonila se na tvář až k zemi, řkuci: Aj, služebnice tvá za děvku bude, aby umývala nohy služebníkům pána svého.'),
(1554095,54,9,25,42,'Protož rychle vstavši Abigail a vsedši na osla svého, (pět pak děveček jejích šlo za ní), jela za posly Davidovými, a byla manželkou jeho.'),
(1554096,54,9,25,43,'Též i Achinoam pojal David z Jezreel, a byly i tyto dvě manželky jeho.'),
(1554097,54,9,25,44,'Nebo Saul Míkol dceru svou, manželku Davidovu, dal byl Faltiovi, synu Lais, kterýž byl z Gallim.'),
(1554098,54,9,26,1,'Opět přišli Zifejští k Saulovi do Gabaa, řkouce: Nevíš-liž, že se David kryje na pahrbku Hachila proti poušti?'),
(1554099,54,9,26,2,'Protož povstal Saul a táhl na poušť Zif, a s ním tři tisíce mužů vybraných z Izraele, aby hledal Davida na poušti Zif.'),
(1554100,54,9,26,3,'I položil se Saul na pahrbku Hachila, kterýž jest proti Jesimon při cestě. David pak trvaje na poušti, srozuměl, že Saul za ním přitáhl na poušť.'),
(1554101,54,9,26,4,'Nebo poslav David špehéře, vyzvěděl jistotně, že Saul přitáhl.'),
(1554102,54,9,26,5,'Tedy vstav David, šel k místu, na němž se položil Saul s vojskem. I spatřil David místo, na kterémž ležel Saul a Abner syn Nerův, hejtman vojska jeho. Saul pak spal, jsa vozy otočen, lid také ležení svá měl vůkol něho.'),
(1554103,54,9,26,6,'I mluvil David a řekl Achimelechovi Hetejskému a Abizai synu Sarvie, bratru Joábovu, řka: Kdo sstoupí se mnou k Saulovi do ležení? Odpověděl Abizai: Já sstoupím s tebou.'),
(1554104,54,9,26,7,'A tak přišel David a Abizai k lidu v noci, a aj, Saul leže, spal, jsa vozy otočen, a kopí jeho vetknuté bylo v zemi u hlavy jeho, Abner pak i lid spali vůkol něho.'),
(1554105,54,9,26,8,'Tedy řekl Abizai Davidovi: Dalť Bůh dnes nepřítele tvého v ruku tvou. Protož nyní, medle nechť jej probodnu pojednou kopím až do země, tak že nebude potřebí podruhé.'),
(1554106,54,9,26,9,'Ale David řekl k Abizai: Nezabíjej ho; nebo kdo vztáhna ruku svou na pomazaného Hospodinova, byl by bez viny?'),
(1554107,54,9,26,10,'Řekl také David: Živť jest Hospodin, leč Hospodin raní jej, aneb den jeho přijde, aby umřel, aneb na vojnu vytáhna, zahyne:'),
(1554108,54,9,26,11,'Mně nedej Hospodin, abych vztáhnouti měl ruku svou na pomazaného Hospodinova. Ale nyní vezmi medle to kopí, kteréž jest u hlavy jeho, a tu číši vodnou, a odejděme.'),
(1554109,54,9,26,12,'I vzal David kopí a číši vodnou u hlavy Saulovy, a odešli, tak že žádný neviděl, ani nezvěděl, ani neprocítil, ale všickni spali; nebo sen tvrdý Hospodinův připadl byl na ně.'),
(1554110,54,9,26,13,'A přešed David na druhou stranu, postavil se na vrchu hory zdaleka; nebo bylo mezi nimi nemalé místo.'),
(1554111,54,9,26,14,'I zavolal David na lid a na Abnera syna Ner, řka: Což se neozveš, Abner? Odpovídaje pak Abner, řekl: Kdo jsi ty, kterýž voláš na krále?'),
(1554112,54,9,26,15,'I řekl David Abnerovi: Zdaliž ty nejsi muž? A kdo jest tobě rovný v Izraeli? Proč jsi tedy neostříhal krále, pána svého? Nebo přišel jeden z lidu, aby zabil krále, pána tvého.'),
(1554113,54,9,26,16,'Neníť to dobře, co jsi učinil. Živť jest Hospodin, že jste hodni smrti, proto že neostříháte pána svého, pomazaného Hospodinova. Ale nyní pohleď, kde jest kopí královo a číše vodná, kteráž byla u hlavy jeho.'),
(1554114,54,9,26,17,'Tedy poznal Saul hlas Davidův a řekl: Není-liž to hlas tvůj, synu můj Davide? Odpověděl David: Jest můj hlas, pane můj králi.'),
(1554115,54,9,26,18,'Řekl také: Proč je to, že pán můj honí služebníka svého? Nebo co jsem učinil? A co jest zlého v ruce mé?'),
(1554116,54,9,26,19,'Protož nyní poslyš, prosím, pane můj králi, slov služebníka svého: Jestliže tě Hospodin vzbudil proti mně, nechť zachutná obět, pakli lidé, zlořečení jsou před Hospodinem; nebo mne vyhnali dnes, abych nemohl obcovati dědictví Hospodinovu, jako by řekli: Jdi, služ bohům cizím.'),
(1554117,54,9,26,20,'Ale již aspoň nechť není vylita krev má na zemi bez rozsouzení Hospodinova; nebo vytáhl král Izraelský hledati blechy jedné, rovně jako by honil koroptvu na horách.'),
(1554118,54,9,26,21,'I řekl Saul: Zhřešilť jsem, navratiž se, synu můj Davide. Neboť nebudu více zle činiti tobě, proto že jsi draze sobě vážil života mého dnešní den. Aj, bláznivě jsem dělal a bloudil přenáramně.'),
(1554119,54,9,26,22,'A odpovídaje David, řekl: Teď hle kopí královo. Nechť přijde někdo z služebníků, a vezme je.'),
(1554120,54,9,26,23,'Hospodin pak navratiž jednomu každému za spravedlnost jeho a věrnost jeho. Daltě byl zajisté Hospodin tebe dnes v ruku mou, ale nechtělť jsem vztáhnouti ruky své na pomazaného Hospodinova.'),
(1554121,54,9,26,24,'A protož jakož jsem já dnes sobě draze vážil života tvého, tak budiž draze vážen život můj před Hospodinem, aby mne vysvobodil ze vší úzkosti.'),
(1554122,54,9,26,25,'Tedy řekl Saul Davidovi: Požehnaný jsi, synu můj Davide. Tak čině, dokážeš ctnosti, a v tom se zmocňuje, zkvetneš. V tom odšel David cestou svou, Saul také navrátil se k místu svému.'),
(1554123,54,9,27,1,'Řekl pak David v srdci svém: Když tedyž sejdu od ruky Saulovy, nic mi lepšího není, než abych naprosto utekl do země Filistinské. I pustí o mně Saul, a nebude mne více hledati v žádných končinách Izraelských, a tak ujdu ruky jeho.'),
(1554124,54,9,27,2,'Tedy vstav David, odebral se sám i těch šest set mužů, kteříž byli s ním, k Achisovi synu Maoch, králi Gát.'),
(1554125,54,9,27,3,'I bydlil David s Achisem v Gát, on i muži jeho, jeden každý s čeledí svou, David i dvě ženy jeho, Achinoam Jezreelská, a Abigail Karmelská někdy žena Nábalova.'),
(1554126,54,9,27,4,'A když bylo oznámeno Saulovi, že utekl David do Gát, přestal ho hledati více.'),
(1554127,54,9,27,5,'Řekl pak David Achisovi: Prosím, jestliže jsem nalezl milost před očima tvýma, ať mi dají místo v některém městě krajiny této, abych tam bydlil; nebo proč má bydliti služebník tvůj s tebou v městě královském?'),
(1554128,54,9,27,6,'I dal mu Achis v ten den Sicelech, odkudž Sicelech bylo králů Judských až do dne tohoto.'),
(1554129,54,9,27,7,'Byl pak počet dnů, v nichž bydlil David v krajině Filistinské, den a čtyři měsíce.'),
(1554130,54,9,27,8,'I vycházel David s muži svými, vpády činíce na Gessurské a Gerzitské a Amalechitské, (nebo ti bydlili v zemi té od starodávna), kudy se chodí přes Sur až do země Egyptské.'),
(1554131,54,9,27,9,'A hubil David krajinu tu, nenechávaje živého muže ani ženy; bral také ovce i voly, i osly i velbloudy, i šaty, a navracoval se a přicházel k Achisovi.'),
(1554132,54,9,27,10,'A když se ptal Achis: Kam jste dnes vpadli? odpověděl David: K straně polední Judově, a k straně polední Jerachmeelově, a k straně polední Cinejského.'),
(1554133,54,9,27,11,'Neživil pak David ani muže ani ženy, aby koho přivoditi měl do Gát; nebo myslil: Aby na nás nežalovali, řkouce: Tak učinil David. A ten obyčej jeho byl po všecky dny, dokudž zůstával v krajině Filistinské.'),
(1554134,54,9,27,12,'I věřil Achis Davidovi, řka: Jižtě se velice zošklivil lidu svému Izraelskému, protož budeť mi za služebníka na věky.'),
(1554135,54,9,28,1,'I stalo se za dnů těch, že Filistinští sebrali vojska svá k boji, aby bojovali s Izraelem. I řekl Achis Davidovi: Věz nepochybně, že potáhneš se mnou na vojnu, ty i muži tvoji.'),
(1554136,54,9,28,2,'Odpověděl David Achisovi: Teprv ty poznáš, co učiní služebník tvůj. I řekl Achis Davidovi: Touť příčinou strážným života svého tě ustanovím po všecky dny.'),
(1554137,54,9,28,3,'(Samuel pak již byl umřel; pročež plakal ho všecken Izrael, a pochovali jej v Ráma, totiž v městě jeho. A Saul byl vyplénil věšťce a hadače z země.)'),
(1554138,54,9,28,4,'Tedy shromáždivše se Filistinští, přitáhli a položili se u Sunem. Shromáždil i Saul všeho Izraele, a položili se v Gelboe.'),
(1554139,54,9,28,5,'Vida pak Saul vojsko Filistinské, bál se, a uleklo se srdce jeho velmi.'),
(1554140,54,9,28,6,'I dotazoval se Saul Hospodina, ale Hospodin neodpovídal jemu ani skrze sny, ani skrze urim, ani skrze proroky.'),
(1554141,54,9,28,7,'Protož řekl Saul služebníkům svým: Pohledejte mi ženy mající ducha věštího, i půjdu k ní a poradím se skrze ni. Jemuž odpověděli služebníci jeho: Aj, žena mající ducha věštího v Endor.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554142,54,9,28,8,'Tedy změniv Saul oděv, oblékl se v roucho jiné, a šel sám a dva muži s ním, a přišli k ženě té v noci. I řekl: Medle hádej mi skrze ducha věštího, a způsob to, ať ke mně vyjde ten, kohož bych jmenoval tobě.'),
(1554143,54,9,28,9,'Ale žena řekla jemu: Aj, ty víš, co učinil Saul, kterak vyhladil věšťce a hadače z země. Pročež tedy ty pokládáš osídlo duši mé, abys mne o hrdlo připravil?'),
(1554144,54,9,28,10,'I přisáhl jí Saul skrze Hospodina, řka: Živť jest Hospodin, že nepřijde na tě trestání pro tu věc.'),
(1554145,54,9,28,11,'Tedy řekla žena: Kohožť mám vyvésti? Kterýž řekl: Samuele mi vyveď.'),
(1554146,54,9,28,12,'A když uzřela žena Samuele, zkřikla hlasem velikým, a řekla žena Saulovi takto: Pročež jsi mne oklamal! Nebo ty jsi Saul.'),
(1554147,54,9,28,13,'I řekl jí král: Neboj se. Což jsi pak viděla? Odpověděla žena Saulovi: Bohy jsem viděla vystupující z země.'),
(1554148,54,9,28,14,'Řekl jí opět: Jaký jest způsob jeho? Odpověděla jemu: Muž starý vystupuje a jest oděný pláštěm. Tedy srozuměl Saul, že by Samuel byl, a sehnuv se tváří k zemi, poklonil se jemu.'),
(1554149,54,9,28,15,'I řekl Samuel Saulovi: Proč mne nepokojíš, že jsi mne zavolati rozkázal? Odpověděl Saul: Úzkostmi sevřín jsem velice; nebo Filistinští bojují proti mně, a Bůh odstoupil ode mne, a neodpovídá mi více, ani skrze proroky, ani skrze sny. Protož povolal jsem tě, abys mi oznámil, co bych měl činiti.'),
(1554150,54,9,28,16,'I řekl Samuel: Proč tedy se mne dotazuješ, poněvadž Hospodin odstoupil od tebe, a jest s nepřítelem tvým?'),
(1554151,54,9,28,17,'Učiniltě zajisté jemu Hospodin, jakož mluvil skrze mne, a odtrhl Hospodin království od ruky tvé, a dal je bližnímu tvému, Davidovi.'),
(1554152,54,9,28,18,'Nebo že jsi neuposlechl hlasu Hospodinova, a nevykonals hněvu prchlivosti jeho nad Amalechem, protož učinil tobě to dnes Hospodin.'),
(1554153,54,9,28,19,'Nadto vydá Hospodin i Izraele s tebou v ruku Filistinských, a zítra budeš ty i synové tvoji se mnou. I vojska Izraelská vydá Hospodin v ruku Filistinských.'),
(1554154,54,9,28,20,'I padl Saul náhle tak, jak dlouhý byl, na zem, nebo se byl ulekl náramně slov Samuelových. K tomu ani síly v něm nebylo, nebo nic nejedl celý ten den a celou tu noc.'),
(1554155,54,9,28,21,'Přistoupivši pak ta žena k Saulovi a uzřevši, že jest předěšen náramně, řekla jemu: Aj, uposlechla děvka tvá hlasu tvého, a opovážila jsem se života svého, že jsem uposlechla slov tvých, kteráž jsi mluvil ke mně.'),
(1554156,54,9,28,22,'Nyní tedy uposlechni i ty, prosím, hlasu děvky své, a položím před tebe kousek chleba, abys jedl a posilil se, a tak jíti mohl cestou svou.'),
(1554157,54,9,28,23,'Kterýž odepřel a řekl: Nebuduť jísti. I přinutili ho služebníci jeho, ano i ta žena, tak že uposlechl hlasu jejich, a vstav s země, sedl na lůžko.'),
(1554158,54,9,28,24,'Měla pak ta žena tele tučné v domě, kteréž spěšně zabila, a vzavši mouky, zadělala, a napekla z ní chlebů přesných.'),
(1554159,54,9,28,25,'Potom přinesla před Saule a služebníky jeho, kteříž jedli, a vstavše v touž noc, odešli.'),
(1554160,54,9,29,1,'A tak shromáždili Filistinští všecka vojska svá u Afeku, Izrael pak položil se u studnice, kteráž byla v Jezreel.'),
(1554161,54,9,29,2,'I táhla knížata Filistinská po stu a po tisících, David pak a muži jeho táhli nazad s Achisem.'),
(1554162,54,9,29,3,'Tedy řekla knížata Filistinská: K čemu jsou Židé tito? Odpověděl Achis knížatům Filistinským: Zdaliž toto není David služebník Saule, krále Izraelského, kterýž byl při mně dnů těchto, nýbrž těchto let, a neshledal jsem na něm ničeho ode dne, jakž odpadl od Saule, až do tohoto dne?'),
(1554163,54,9,29,4,'I rozhněvala se na něj knížata Filistinská, a řekli jemu ta knížata Filistinská: Odešli zase muže toho, ať se navrátí k místu svému, kteréž jsi mu ukázal, a nechť netáhne s námi k boji, aby se nám nepostavil za nepřítele v bitvě. Nebo čím se zalíbiti může pánu svému tento? Zdali ne hlavami mužů těchto?'),
(1554164,54,9,29,5,'Zdaliž tento není ten David, o kterémž zpívali v houfích plésajících, říkajíce: Porazil Saul svůj tisíc, ale David svých deset tisíců?'),
(1554165,54,9,29,6,'I povolal Achis Davida, a řekl jemu: Živť jest Hospodin, že jsi upřímý, a líbí mi se vycházení tvé i vcházení tvé se mnou do vojska. Nebo neshledal jsem na tobě nic zlého ode dne, v kterýž jsi přišel ke mně, až do dne tohoto, ale před očima knížat nejsi vzácný.'),
(1554166,54,9,29,7,'Protož nyní navrať se a jdi v pokoji, a nebudeš těžký v očích knížat Filistinských.'),
(1554167,54,9,29,8,'I řekl David Achisovi: Co jsem pak učinil, a co jsi shledal na služebníku svém ode dne, v kterýž jsem počal býti u tebe, až do tohoto dne, abych nešel a nebojoval proti nepřátelům pána svého krále?'),
(1554168,54,9,29,9,'A odpovídaje Achis, řekl Davidovi: Vímť, že jsi vzácný před očima mýma jako anděl Boží, ale knížata Filistinská řekla: Nechť netáhne s námi k boji.'),
(1554169,54,9,29,10,'Nyní tedy vstaň tím raněji a služebníci pána tvého, kteříž přišli s tebou, a vstanouce tím spíše ráno, hned jakž by zasvitávalo, odejděte.'),
(1554170,54,9,29,11,'I vstal David, on i muži jeho, aby odšel tím raněji, a navrátil se do země Filistinské. Filistinští pak táhli do Jezreel.'),
(1554171,54,9,30,1,'Byl pak, když se navrátil David a muži jeho do Sicelechu, den třetí, jakž Amalechitští byli vpád učinili k straně polední i k Sicelechu, a vyhubili Sicelech, a vypálili jej.'),
(1554172,54,9,30,2,'A zajali ženy, kteréž byly v něm. Nezabili žadného, ani malého ani velikého, ale szajímali a odešli cestou svou.'),
(1554173,54,9,30,3,'A když přišel David a muži jeho k městu, aj, vypáleno bylo ohněm, a ženy jejich, též synové a dcery jejich zajati byli.'),
(1554174,54,9,30,4,'Tedy David i lid jeho, kterýž s ním byl, pozdvihše hlasu svého, plakali, až již více plakati nemohli.'),
(1554175,54,9,30,5,'Obě také manželky Davidovy zajaty jsou, Achinoam Jezreelitská, a Abigail žena někdy Nábale Karmelského.'),
(1554176,54,9,30,6,'I ssoužen jest David náramně, nebo se smlouval lid, aby ho ukamenovali, (hořkostí zajisté naplněna byla duše všeho lidu, jednoho každého pro syny jeho a pro dcery jeho). Však posilnil se David v Hospodinu Bohu svém.'),
(1554177,54,9,30,7,'I řekl David Abiatarovi knězi, synu Achimelechovu: Medle, vezmi na sebe efod. I vzal Abiatar efod pro Davida.'),
(1554178,54,9,30,8,'Tázal se pak David Hospodina, řka: Mám-li honiti lotříky ty? A dohoním-li se jich? I řekl jemu: Hoň, nebo se jich jistě dohoníš, a své mocně vysvobodíš.'),
(1554179,54,9,30,9,'A tak odšed David sám i těch šest set mužů, kteříž byli s ním, přišli až ku potoku Bezor; někteří pak tu pozůstali.'),
(1554180,54,9,30,10,'I honil je David se čtyřmi sty mužů; nebo bylo pozůstalo dvě stě mužů, kteříž ustavše, nemohli přejíti potoka Bezor.'),
(1554181,54,9,30,11,'A nalezše muže Egyptského v poli, přivedli jej k Davidovi. I dali jemu chleba, aby pojedl; dali jemu také i vody píti.'),
(1554182,54,9,30,12,'Dali jemu též kus hrudy fíků a dva hrozny suché. A tak pojedl a okřál zase, (nebo byl nic nejedl ani nepil tři dni a tři noci).'),
(1554183,54,9,30,13,'Zatím řekl jemu David: Čí jsi ty? A odkud jsi? Kterýž odpověděl: Rodem jsem z Egypta, služebník muže Amalechitského, a opustil mne pán můj, proto že jsem stonal, dnes třetí den.'),
(1554184,54,9,30,14,'Byli jsme zajisté vpád učinili k straně polední Ceretejského, a v tu stranu, kteráž jest Judova, a ku poledni, kteráž jest Kálefova, a Sicelech jsme vypálili ohněm.'),
(1554185,54,9,30,15,'Tedy řekl jemu David: Mohl-li bys dovésti mne k těm lotříkům? Kterýž řekl: Přisáhni mi skrze Boha, že mne nezabiješ, a že mne nevydáš v ruku pána mého, a přivedu tě na ty lotříky.'),
(1554186,54,9,30,16,'I přivedl ho. (A aj, byli se rozprostřeli po vší té zemi, jedouce a pijíce a provyskujíce nade všemi kořistmi tak velikými, kteréž pobrali z země Filistinské a z země Judovy.)'),
(1554187,54,9,30,17,'Protož bil je David od večera až do večera druhého dne, aniž kdo z nich ušel, kromě čtyř set mládenců, kteříž vsedše na velbloudy, utekli.'),
(1554188,54,9,30,18,'A tak odjal David všecko, což byli pobrali Amalechitští; také obě ženy své vysvobodil David.'),
(1554189,54,9,30,19,'A nezhynulo jim nic, ani malého ani velikého, i z synů i ze dcer, i z loupeže a ze všeho, což jim vzato bylo; všecko zase David přivedl.'),
(1554190,54,9,30,20,'Nadto szajímal David všecka stáda bravů i skotů, kteráž hnali před dobytkem svým, a pravili: Totoť jsou kořisti Davidovy.'),
(1554191,54,9,30,21,'Přišel pak David k těm dvěma stům mužů, kteříž byli ustali, tak že nemohli jíti za Davidem, jimž byli kázali zůstati při potoku Bezor; tedy vyšli vstříc Davidovi a lidu, kterýž byl s ním. A přistoupiv David k tomu lidu, pozdravil jich přátelsky.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554192,54,9,30,22,'Ale všickni, což jich koli bylo zlých a bezbožných mezi těmi muži, kteříž chodili s Davidem, mluvili, řkouce: Poněvadž nešli s námi, nedáme jim z kořistí, kteréž jsme odjali, toliko každému manželku jeho a syny jeho, aby vezmouce je, odešli.'),
(1554193,54,9,30,23,'David pak řekl: Nečiňte tak, bratří moji, s tím, což nám dal Hospodin, kterýž nás ostříhal a dal vojsko, jenž vytáhlo proti nám, v ruku naši.'),
(1554194,54,9,30,24,'A kdož vás uposlechne v té věci? Nebo jakýž bude díl toho, kterýž vyšel k bitvě, takovýž bude díl i toho, kterýž hlídal břemen; rovně se děliti budou.'),
(1554195,54,9,30,25,'A tak bývalo od toho dne i potom, nebo to za právo a obyčej uložil v Izraeli až do tohoto dne.'),
(1554196,54,9,30,26,'A když přišel David do Sicelechu, poslal z těch kořistí starším Juda, přátelům svým, řka: Teď máte dar z loupeží nepřátel Hospodinových.'),
(1554197,54,9,30,27,'Těm, kteříž byli v Bethel, a kteříž v Rámat ku poledni, a kteříž byli v Jeter;'),
(1554198,54,9,30,28,'Též kteříž v Aroer, a kteříž v Sefama, a kteříž v Estemo;'),
(1554199,54,9,30,29,'A kteříž v Rachal, a kteříž v městech Jerachmeelových, a kteříž v městech Cinejského;'),
(1554200,54,9,30,30,'I těm, kteříž v Horma, a kteříž v Korasan, a kteříž v Atach;'),
(1554201,54,9,30,31,'A kteříž byli v Hebronu, i po všech místech, na nichž býval David s lidem svým.'),
(1554202,54,9,31,1,'A tak potýkali se Filistinští s Izraelem. Muži pak Izraelští utíkali před Filistinskými a padli, zbiti jsouce na hoře Gelboe.'),
(1554203,54,9,31,2,'I stihali Filistinští Saule a syny jeho, a zabili Filistinští Jonatu a Abinadaba a Melchisua, syny Saulovy.'),
(1554204,54,9,31,3,'Když se pak zsilila bitva proti Saulovi, trefili na něj střelci, muži s luky; i postřelen jest velmi od těch střelců.'),
(1554205,54,9,31,4,'I řekl Saul oděnci svému: Vytrhni meč svůj a probodni mne jím, aby přijdouce ti neobřezanci, neprobodli mne, a neučinili sobě ze mne posměchu. Ale nechtěl oděnec jeho, nebo se bál velmi. A pochytiv Saul meč, nalehl na něj.'),
(1554206,54,9,31,5,'Tedy vida oděnec jeho, že umřel Saul, nalehl i on na meč svůj a umřel s ním.'),
(1554207,54,9,31,6,'A tak umřel Saul a tři synové jeho, a oděnec jeho, ano i všickni muži jeho v ten den spolu.'),
(1554208,54,9,31,7,'Když pak uzřeli synové Izraelští, kteříž bydlili za tím údolím, a kteříž bydlili za Jordánem, že zutíkali muži Izraelští, nadto že Saul i synové jeho zahynuli, opustivše města, také utíkali. I přišli Filistinští a bydlili v nich.'),
(1554209,54,9,31,8,'A když bylo nazejtří, přišli Filistinští, aby zloupili pobité; i nalezli Saule a tři syny jeho ležící na hoře Gelboe.'),
(1554210,54,9,31,9,'I sťali hlavu jeho a svlékli odění jeho, a poslali po zemi Filistinské vůkol, aby to ohlášeno bylo v chrámě modl jejich i lidu.'),
(1554211,54,9,31,10,'I složili odění jeho v chrámě Astarot, tělo pak jeho přibili na zdi Betsan.'),
(1554212,54,9,31,11,'Tedy uslyšavše o tom obyvatelé Jábes Galád, co učinili Filistinští Saulovi,'),
(1554213,54,9,31,12,'Zdvihli se všickni muži silní, a jdouce celou noc, sňali tělo Saulovo i těla synů jeho se zdi Betsanské; a když se navrátili do Jábes, spálili je tam.'),
(1554214,54,9,31,13,'A vzavše kosti jejich, pochovali je pod stromem v Jábes, a postili se sedm dní.'),
(1554215,54,10,1,1,'Stalo se pak po smrti Saulově, když se navrátil David od porážky Amalechitských, že pobyl v Sicelechu za dva dni.'),
(1554216,54,10,1,2,'A aj, dne třetího přišel jeden z vojska Saulova, maje roucho roztržené a prach na hlavě své. Kterýž když přišel k Davidovi, padl na zemi a poklonil se.'),
(1554217,54,10,1,3,'I řekl jemu David: Odkud jdeš? Jemuž odpověděl: Z vojska Izraelského utekl jsem.'),
(1554218,54,10,1,4,'Opět řekl jemu David: Cože se stalo? Medle, pověz mi. Kterýž odpověděl: To, že utekl lid z boje, a množství lidu padlo a zbito jest; též i Saul i Jonata syn jeho zbiti jsou.'),
(1554219,54,10,1,5,'Řekl ještě David mládenci, kterýž mu to oznámil: Kterak ty víš, že umřel Saul i Jonata syn jeho?'),
(1554220,54,10,1,6,'Odpověděl mládenec, kterýž to oznamoval jemu: Náhodou přišel jsem na horu Gelboe, a aj, Saul nalehl byl na kopí své, a vozové i jezdci postihali ho.'),
(1554221,54,10,1,7,'Kterýžto ohlédna se zpátkem, uzřel mne a zavolal na mne. I řekl jsem: Aj, teď jsem.'),
(1554222,54,10,1,8,'Tedy řekl mi: Kdo jsi ty? Odpověděl jsem jemu: Amalechitský jsem.'),
(1554223,54,10,1,9,'I řekl mi: Přistup medle sem a zabí mne, nebo mne obklíčila úzkost, a ještě všecka duše má jest ve mně.'),
(1554224,54,10,1,10,'Protož stoje nad ním, zabil jsem ho, nebo jsem věděl, že nebude živ po svém pádu. A vzal jsem korunu, kteráž byla na hlavě jeho, i záponu, kteráž byla na rameni jeho, a teď jsem to přinesl ku pánu svému.'),
(1554225,54,10,1,11,'Tedy David uchytiv roucho své, roztrhl je; tolikéž i všickni muži, kteříž s ním byli.'),
(1554226,54,10,1,12,'A nesouce smutek, plakali a postili se až do večera pro Saule a pro Jonatu syna jeho, i pro lid Hospodinův a pro dům Izraelský, že padli od meče.'),
(1554227,54,10,1,13,'Řekl pak David mládenci, kterýž mu to oznámil: Odkud jsi ty? Odpověděl: Syn muže příchozího Amalechitského jsem.'),
(1554228,54,10,1,14,'Opět mu řekl David: Kterak jsi směl vztáhnouti ruku svou, abys zahubil pomazaného Hospodinova?'),
(1554229,54,10,1,15,'A zavolav David jednoho z mládenců, řekl jemu: Přistoupě, oboř se na něj. Kterýžto udeřil ho, tak že umřel.'),
(1554230,54,10,1,16,'I řekl jemu David: Krev tvá budiž na hlavu tvou, neboť jsou ústa tvá svědčila na tebe, řkouce: Já jsem zabil pomazaného Hospodinova.'),
(1554231,54,10,1,17,'Tedy naříkal David naříkáním tímto nad Saulem a nad Jonatou synem jeho,'),
(1554232,54,10,1,18,'(Přikázav však, aby synové Judovi učeni byli stříleti z luku, jakož psáno v knize Upřímého.):'),
(1554233,54,10,1,19,'Ó kráso Izraelská, na výsostech tvých zraněni, jakť jsou padli udatní!'),
(1554234,54,10,1,20,'Neoznamujtež v Gát, ani toho ohlašujte na ulicích Aškalon, aby se neveselily dcery Filistinských, a neplésaly dcery neobřezaných.'),
(1554235,54,10,1,21,'Ó hory Gelboe, ani rosa, ani déšť nespadej na vás, ani tu buď pole úrodné; nebo tam jest povržen štít udatných, štít Saulův, jako by nebyl pomazán olejem.'),
(1554236,54,10,1,22,'Od krve raněných a od tuku udatných lučiště Jonatovo nikdy zpět neodskočilo, a meč Saulův nenavracoval se prázdný.'),
(1554237,54,10,1,23,'Saul a Jonata milí a utěšení v životě svém, také při smrti své nejsou rozloučeni. Nad orlice bystřejší, nad lvy silnější byli.'),
(1554238,54,10,1,24,'Dcery Izraelské, plačte Saule, kterýž vás odíval červcem dvakrát barveným rozkošně, kterýž dával ozdoby zlaté na roucha vaše.'),
(1554239,54,10,1,25,'Ach, jakť jsou padli udatní u prostřed boje? Jonata na výsostech tvých zabit jest.'),
(1554240,54,10,1,26,'Velice jsem po tobě teskliv, bratře můj Jonato. Byl jsi mi příjemný náramně; vzácnější u mne byla milost tvá nežli milost žen.'),
(1554241,54,10,1,27,'Ach, jakť jsou padli udatní, a zahynula odění válečná.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554242,54,10,2,1,'I stalo se potom, že se David tázal Hospodina, řka: Mám-li jíti do některého města Judského? Jemuž odpověděl Hospodin: Jdi. I řekl David: Kam mám jíti? Odpověděl: Do Hebronu.'),
(1554243,54,10,2,2,'A protož bral se tam David, ano i obě manželky jeho, Achinoam Jezreelská, a Abigail žena někdy Nábale Karmelského.'),
(1554244,54,10,2,3,'Muže také své, kteříž s ním byli, pojal David, jednoho každého s čeledí jeho, a bydlili v městech Hebronských.'),
(1554245,54,10,2,4,'I přišli muži Judští, a pomazali tam Davida za krále nad domem Judským. Oznámili také Davidovi, řkouce: Muži Jábes Galád, oni pochovali Saule.'),
(1554246,54,10,2,5,'Tedy poslav David posly k mužům Jábes Galád, řekl jim: Požehnaní jste vy před Hospodinem, že jste učinili to milosrdenství pánu svému Saulovi, pochovavše ho.'),
(1554247,54,10,2,6,'Protož nyní učiniž s vámi Hospodin milosrdenství a pravdu; ano i jáť s vámi učiním milost, kteříž jste to učinili.'),
(1554248,54,10,2,7,'A tak tedy posilňtež rukou svých a buďtež stateční; nebo ač umřel pán váš Saul, však již mne pomazali dům Judův za krále nad sebou.'),
(1554249,54,10,2,8,'Abner pak syn Nerův, hejtman vojska Saulova, vzal Izbozeta syna Saulova a uvedl ho do Mahanaim.'),
(1554250,54,10,2,9,'A ustavil ho králem nad Galád a nad Assur, a nad Jezreel, a nad Efraimem, a nad Beniaminem, i nade vším Izraelem.'),
(1554251,54,10,2,10,'Ve čtyřidcíti letech byl Izbozet syn Saulův, když počal kralovati nad Izraelem, a kraloval dvě létě. (Toliko dům Judův přídržel se Davida.'),
(1554252,54,10,2,11,'A byl počet dnů, v nichž byl David králem v Hebronu nad domem Judovým, sedm let a šest měsíců.)'),
(1554253,54,10,2,12,'Potom vytáhl Abner syn Nerův, a služebníci Izbozeta syna Saulova z Mahanaim do Gabaon.'),
(1554254,54,10,2,13,'Joáb také syn Sarvie a služebníci Davidovi vytáhše, potkali se s nimi právě u rybníka Gabaon. I pozůstali tito u rybníka s strany jedné, oni pak u rybníka s druhé strany.'),
(1554255,54,10,2,14,'Tedy řekl Abner Joábovi: Nechť vystoupí nyní mládenci a pohrají před námi. I řekl Joáb: Nechť vystoupí.'),
(1554256,54,10,2,15,'A tak vystoupili a vyšli v rovném počtu, dvanácte z Beniamina, z strany Izbozeta syna Saulova, a dvanácte z služebníků Davidových.'),
(1554257,54,10,2,16,'Kteřížto ujavše jeden každý za hlavu bližního svého, vrazil meč svůj v bok tovaryše svého, i padli spolu. Protož nazváno jest místo to Helkat Hassurim, a jest v Gabaon.'),
(1554258,54,10,2,17,'I byla bitva velmi veliká v ten den, a poražen jest Abner i muži Izraelští od služebníků Davidových.'),
(1554259,54,10,2,18,'Byli tu také tři synové Sarvie: Joáb, Abizai a Azael. Azael pak byl čerstvý na nohy své jako srna v poli.'),
(1554260,54,10,2,19,'I honil Azael Abnera, a neuhnul se na pravo ani na levo, běže za Abnerem.'),
(1554261,54,10,2,20,'Ohlédl se pak Abner zpátkem a řekl: Ty-li jsi Azael? Odpověděl: Jsem.'),
(1554262,54,10,2,21,'Tedy řekl mu Abner: Uchyl se na pravo aneb na levo, a jmi sobě jednoho z mládenců těch, a vezmi sobě kořisti jeho. Ale nechtěl Azael uchýliti se od něho.'),
(1554263,54,10,2,22,'Ještě znovu Abner řekl Azaelovi: Uchyl se ode mne, sic jináč přirazím tě až k zemi, a jak bych směl pohleděti na Joába bratra tvého?'),
(1554264,54,10,2,23,'Když pak nechtěl ustoupiti, uhodil ho Abner kopím pod páté žebro, tak že vyniklo kopí hřbetem jeho; a padl tu na tom místě, na kterémž i umřel. A kdožkoli přicházeli k místu, na němž padl Azael a umřel, zastavovali se.'),
(1554265,54,10,2,24,'Ale Joáb a Abizai honili Abnera. Slunce pak již bylo zapadlo, když oni přišli ku pahrbku Amma, jenž jest naproti Giach, cestou k poušti Gabaon.'),
(1554266,54,10,2,25,'Tedy sešli se synové Beniamin za Abnerem, a jsouce spolu v houfu, postavili se na vrchu pahrbku jednoho.'),
(1554267,54,10,2,26,'Odkudž zavolal Abner na Joába, řka: Zdaliž bez přestání sžírati bude meč tvůj? Nevíš-liž, že hořkost bývá naposledy? Dokudž tedy nerozkážeš lidu navrátiti se od honění bratří svých?'),
(1554268,54,10,2,27,'I řekl Joáb: Živť jest Bůh, že kdybys byl nemluvil, hned ráno byl by odšel lid, jeden každý nechaje honění bratra svého.'),
(1554269,54,10,2,28,'Tedy zatroubil Joáb v troubu, a zastavil se všecken lid, a nehonili více Izraele, aniž více bojovali.'),
(1554270,54,10,2,29,'A tak Abner i lid jeho šli přes pole celou tu noc, a přepravili se přes Jordán, a prošedše všecku Betoron, přišli do Mahanaim.'),
(1554271,54,10,2,30,'Ale Joáb navrátiv se od honění Abnera, shromáždil všecken lid, a nedostávalo se z služebníků Davidových devatenácti mužů a Azaele.'),
(1554272,54,10,2,31,'Služebníci pak Davidovi zbili z Beniaminských a z mužů Abnerových tři sta a šedesáte mužů, kteříž tu zahynuli.'),
(1554273,54,10,2,32,'A vzavše Azaele, pohřbili jej v hrobě otce jeho, kterýž byl v Betlémě. Potom šli celou tu noc Joáb a muži jeho; i rozednilo se, když přicházeli do Hebronu.'),
(1554274,54,10,3,1,'I trvala dlouho válka mezi domem Saulovým a domem Davidovým. David pak čím dále tím více se silil, ale dům Saulův čím dále tím se více umenšoval.'),
(1554275,54,10,3,2,'I zrodili se Davidovi synové v Hebronu, z nichž prvorozený jeho byl Amnon z Achinoam Jezreelské;'),
(1554276,54,10,3,3,'A druhý po něm Cheleab z Abigail, ženy někdy Nábale Karmelského; třetí pak Absolon, syn z Maachy dcery Tolmai krále Gessur;'),
(1554277,54,10,3,4,'A čtvrtý Adoniáš syn Haggit, a pátý Sefatiáš syn Abitál;'),
(1554278,54,10,3,5,'Šestý pak Jetram z Egly manželky Davidovy. Ti se zrodili Davidovi v Hebronu.'),
(1554279,54,10,3,6,'I stalo se, když byla válka mezi domem Saulovým a mezi domem Davidovým, a Abner statečně zastával domu Saulova,'),
(1554280,54,10,3,7,'(Měl pak byl Saul ženinu, jejíž jméno bylo Rizpa, dcera Aja), že řekl Izbozet Abnerovi: I proč jsi všel k ženině otce mého?'),
(1554281,54,10,3,8,'Tedy rozhněvav se Abner velmi pro slova Izbozetova, řekl: I zdali já jsem psí hlava, kterýž jsem proti Judovi dnes učinil milosrdenství s domem Saule otce tvého, s bratřími jeho i příbuznými jeho, a nevydal jsem tě v ruku Davidovu, a však vyhledáváš na mně dnes nepravosti té ženy.'),
(1554282,54,10,3,9,'Toto učiň Bůh Abnerovi a toto mu přidej, jestliže nedopomohu k tomu Davidovi, jakož jemu přisáhl Hospodin,'),
(1554283,54,10,3,10,'Aby přeneseno bylo království od domu Saulova, a upevněn byl trůn Davidův nad Izraelem i nad Judou, od Dan až do Bersabé.'),
(1554284,54,10,3,11,'A nemohl k tomu nic více odpovědíti Abnerovi, proto že se ho bál.'),
(1554285,54,10,3,12,'A tak poslal Abner posly k Davidovi na místě svém, řka: Čí jest země? A aby řekli: Učiň smlouvu se mnou, a aj, ruka má bude s tebou, abych obrátil k tobě všecken Izrael.'),
(1554286,54,10,3,13,'Jemuž odpověděl: Dobře. Jáť učiním s tebou smlouvu, a však jedné věci od tebe žádám, totiž, abys neviděl tváři mé, leč prvé dáš přivésti Míkol dceru Saulovu, když bys chtěl přijíti, abys viděl tvář mou.'),
(1554287,54,10,3,14,'I poslal David posly k Izbozetovi synu Saulovu, aby řekli: Dej mi ženu mou Míkol, kterouž jsem sobě zasnoubil ve stu obřízek Filistinských.'),
(1554288,54,10,3,15,'Poslav tedy Izbozet, vzal ji od muže Faltiele syna Lais.'),
(1554289,54,10,3,16,'Šel pak s ní muž její, a jda za ní až do Bahurim, plakal. Tedy řekl jemu Abner: Jdi, navrať se zase. I navrátil se.'),
(1554290,54,10,3,17,'Potom Abner učinil řeč k starším Izraelským, řka: Předešle stáli jste o to, aby David byl králem nad vámi.'),
(1554291,54,10,3,18,'Protož nyní vykonejtež to; neboť jest Hospodin mluvil o Davidovi, řka: Skrze ruku Davida služebníka svého vysvobodím lid svůj Izraelský z ruky Filistinských, a z ruky všech nepřátel jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554292,54,10,3,19,'To též mluvil Abner i k Beniaminským. Potom odšel Abner, aby mluvil k Davidovi v Hebronu všecko, což se za dobré vidělo Izraelovi a všemu domu Beniamin.'),
(1554293,54,10,3,20,'Když tedy přišel Abner k Davidovi do Hebronu a s ním dvadceti mužů, učinil David Abnerovi i mužům, kteříž s ním byli, hody.'),
(1554294,54,10,3,21,'I řekl Abner Davidovi: Vstanu a půjdu, abych shromáždil ku pánu svému králi všecken lid Izraelský, kteříž vejdou s tebou v smlouvu, a budeš kralovati nade všemi, jakož toho žádá duše tvá. I propustil David Abnera, kterýž odšel v pokoji.'),
(1554295,54,10,3,22,'A aj, služebníci Davidovi a Joáb vraceli se z vojny, kořisti veliké s sebou nesouce. Ale Abnera již nebylo s Davidem v Hebronu, nebo byl ho propustil, a již odšel v pokoji.'),
(1554296,54,10,3,23,'Joáb tedy i všecko vojsko, kteréž bylo s ním, přišli tam. I oznámili Joábovi, řkouce: Byl zde Abner syn Nerův u krále, ale propustil jej, a odšel v pokoji.'),
(1554297,54,10,3,24,'Protož všed Joáb k králi, řekl: Co jsi učinil? Aj, přišel byl Abner k tobě; proč jsi ho pustil, aby zase odšel?'),
(1554298,54,10,3,25,'Znáš Abnera syna Nerova. Proto, aby podvedl tebe, přišel, a aby vyšpehoval vycházení tvé i vcházení tvé, a zvěděl všecko, co ty činíš.'),
(1554299,54,10,3,26,'Tedy vyšed Joáb od Davida, poslal posly za Abnerem, kteříž ho přivedli zase od čisterny Sírach, o čemž David nic nevěděl.'),
(1554300,54,10,3,27,'A když se navrátil Abner do Hebronu, uvedl ho Joáb do prostřed brány, aby s ním mluvil tiše. I udeřil ho v páté žebro, a umřel pro krev Azaele bratra jeho.'),
(1554301,54,10,3,28,'To když potom David uslyšel, řekl: Čist jsem já i království mé před Hospodinem až na věky od krve Abnera syna Nerova.'),
(1554302,54,10,3,29,'Nechať přijde na hlavu Joábovu i na všecken dům otce jeho, a nechť není prázden dům Joábův toho, jenž by trpěl tok, aneb malomocného a na hůl se podpírajícího, aneb padajícího od meče a nemajícího chleba.'),
(1554303,54,10,3,30,'A tak Joáb a Abizai bratr jeho zamordovali Abnera, proto že byl zabil Azaele bratra jejich v Gabaon v bitvě.'),
(1554304,54,10,3,31,'I řekl David Joábovi a ke všemu lidu, kterýž byl s ním: Roztrhněte roucha svá, a přepašte se pytli, a plačte před Abnerem. Král pak David šel za márami.'),
(1554305,54,10,3,32,'A když pochovávali Abnera v Hebronu, pozdvih král hlasu svého, plakal nad hrobem Abnerovým, plakal také všecken lid.'),
(1554306,54,10,3,33,'V tom naříkaje král pro Abnera, řekl: Tak-liž jest měl umříti Abner, jako umírá nějaký ničemný člověk?'),
(1554307,54,10,3,34,'Ruce tvé nebyly svázány a nohy tvé měděnými poutami nebyly sevříny, ale padl jsi jako ten, kdož padá od lidí nešlechetných. Tedy ještě více všecken lid plakal nad ním.'),
(1554308,54,10,3,35,'Potom přišel všecken lid, a měli k tomu Davida, aby jedl chléb ještě záhy. Ale David přisáhl, řka: Toto ať mi učiní Bůh a toto přidá, jestliže prvé, než slunce zapadne, okusím chleba aneb čehokoli jiného.'),
(1554309,54,10,3,36,'Což když poznal všecken lid, líbilo se jim to; a všecko, což činil král, líbilo se všemu lidu.'),
(1554310,54,10,3,37,'I poznal všecken lid a všecken Izrael v ten den, že nepošlo to od krále, aby zabili Abnera syna Nerova.'),
(1554311,54,10,3,38,'Řekl pak král služebníkům svým: Nevíte-liž, že kníže, a veliké, padlo dnes v Izraeli?'),
(1554312,54,10,3,39,'A já ještě nyní mdlý jsem, jakožto pomazaný král, muži pak tito, synové Sarvie, jsou mi nepovolní. Odplatiž Hospodin tomu, kdož zle činí, vedlé zlosti jeho.'),
(1554313,54,10,4,1,'A když uslyšel Izbozet syn Saulův, že umřel Abner v Hebronu, zemdlely ruce jeho, a všecken lid Izrael byl předěšen.'),
(1554314,54,10,4,2,'Měl pak syn Saulův dva muže hejtmany nad dráby, jméno jednoho Baana, a jméno druhého Rechab, synové Remmona Berotského z synů Beniamin; nebo i Berot počítá se v Beniaminovi.'),
(1554315,54,10,4,3,'Utekli pak byli Berotští do Gittaim, a byli tam pohostinu až do toho dne.'),
(1554316,54,10,4,4,'Měl také byl Jonata syn Saulův syna chromého na nohy, (nebo když byl v pěti letech a přišla pověst o Saulovi a Jonatovi z Jezreel, vzavši ho chůva jeho, utíkala, a když pospíchala utíkajici, on upadl a okulhavěl), jehož jméno Mifibozet.'),
(1554317,54,10,4,5,'A odšedše synové Remmona Berotského, Rechab a Baana, vešli o poledni do domu Izbozetova. On pak spal na lůžku poledním.'),
(1554318,54,10,4,6,'A aj, když vešli až do domu, jako by bráti měli obilé, ranili ho v páté žebro, Rechab a Baana bratr jeho, a utekli.'),
(1554319,54,10,4,7,'Nebo když byli vešli do domu, a on spal na lůžku svém v pokojíku svém, kdež léhal, probodli jej a zabili, a sťavše hlavu jeho, vzali ji, a šli cestou po pustinách celou tu noc.'),
(1554320,54,10,4,8,'I přinesli hlavu Izbozetovu k Davidovi do Hebronu a řekli králi: Aj, hlava Izbozeta syna Saulova, nepřítele tvého, kterýž hledal bezživotí tvého. Hle, pomstil dnes Hospodin pána mého krále nad Saulem i semenem jeho.'),
(1554321,54,10,4,9,'Tedy odpovídaje David Rechabovi a Baanovi bratru jeho, synům Remmona Berotského, řekl jim: Živť jest Hospodin, kterýž vysvobodil duši mou ze všech úzkostí,'),
(1554322,54,10,4,10,'Kdyžť jsem toho, kterýž mi oznámil, řka: Aj, Saul zahynul, (ješto se jemu zdálo, že veselé noviny zvěstuje), vzal a zabil jsem ho v Sicelechu, jemuž se zdálo, že ho budu darovati za poselství:'),
(1554323,54,10,4,11,'Čím pak více lidi bezbožné, kteříž zamordovali muže spravedlivého v domě jeho na ložci jeho? A nyní, zdaliž nebudu vyhledávati krve jeho z ruky vaší, a nevyhladím vás z země?'),
(1554324,54,10,4,12,'I rozkázal David služebníkům, aby je zbili. I zutínali jim ruce i nohy jejich, a pověsili u rybníka při Hebronu. Hlavu pak Izbozetovu vzavše, pochovali v hrobě Abnerově v Hebronu.'),
(1554325,54,10,5,1,'Tehdy přišla všecka pokolení Izraelská k Davidovi do Hebronu, a mluvili, řkouce: Aj, my kost tvá a tělo tvé jsme.'),
(1554326,54,10,5,2,'A předešlých časů, když byl Saul králem nad námi, ty jsi vyvodil i zase přivodil lid Izraelský. A nadto řekl Hospodin tobě: Ty pásti budeš lid můj Izraelský, a ty budeš vývoda nad Izraelem.'),
(1554327,54,10,5,3,'Přišli také všickni starší Izraelští k králi do Hebronu, a učinil s nimi král David smlouvu v Hebronu před Hospodinem. I pomazali Davida za krále nad Izraelem.'),
(1554328,54,10,5,4,'Ve třidcíti letech byl David, když počal kralovati, a kraloval čtyřidceti let.'),
(1554329,54,10,5,5,'V Hebronu kraloval nad Judou sedm let a šest měsíců, a v Jeruzalémě kraloval třidceti a tři léta nade vším Izraelem a Judou.'),
(1554330,54,10,5,6,'Táhl pak král s lidem svým k Jeruzalému proti Jebuzejskému, obyvateli té země; kterýž mluvil Davidovi, řka: Nevejdeš sem, leč odejmeš slepé a kulhavé, pravíce: Nevejdeť sem David.'),
(1554331,54,10,5,7,'A však vzal David hrad Sion, toť jest město Davidovo.'),
(1554332,54,10,5,8,'Nebo řekl David v ten den: Kdož by koli porazil Jebuzea, a zlezl by žlaby jeho, a pobil by ty slepé i chromé, kteréž má v nenávisti duše Davidova, knížetem bude. Protož pravili: Slepý a kulhavý nevejde do toho domu.'),
(1554333,54,10,5,9,'I bydlil David na tom hradě, a nazval jej městem Davidovým; nebo vystavěl je David vůkol od Mello až do vnitřku.'),
(1554334,54,10,5,10,'A tak David čím dále tím více prospíval a rostl, Hospodin zajisté, Bůh zástupů, byl s ním.'),
(1554335,54,10,5,11,'Poslal také Chíram král Tyrský posly k Davidovi a dříví cedrového, i tesaře, kameníky a zedníky umělé, kteříž vystavěli dům Davidovi.'),
(1554336,54,10,5,12,'I poznal David, že ho potvrdil Hospodin za krále nad Izraelem, a že zvýšil království jeho pro lid svůj Izraelský.'),
(1554337,54,10,5,13,'Nabral pak sobě David ještě více ženin i žen z Jeruzaléma, když byl přišel z Hebronu, a naplodilo se Davidovi ještě více synů a dcer.'),
(1554338,54,10,5,14,'A tato jsou jména těch, kteříž se jemu zrodili v Jeruzalémě: Sammua, Sobab, Nátan a Šalomoun;'),
(1554339,54,10,5,15,'Též Ibchar a Elisua, a Nefeg a Jafia;'),
(1554340,54,10,5,16,'A Elisama a Eliada a Elifelet.'),
(1554341,54,10,5,17,'Uslyšavše pak Filistinští, že pomazali Davida za krále nad Izraelem, vytáhli všickni Filistinští hledati ho. Což když zvěděl David, sstoupil na místo hrazené.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554342,54,10,5,18,'Protož Filistinští přitáhše, položili se v údolí Refaim.'),
(1554343,54,10,5,19,'Tedy tázal se David Hospodina, řka: Potáhnu-li proti Filistinským? Vydáš-li je v ruku mou? Odpověděl Hospodin Davidovi: Táhni, neboť vydám jistotně Filistinské v ruku tvou.'),
(1554344,54,10,5,20,'I přitáhl David do Balperazim, a porazil je tam, a řekl: Protrhlť jest Hospodin nepřátely mé přede mnou, jako vody protrhují břehy. Protož nazval jméno místa toho Balperazim.'),
(1554345,54,10,5,21,'Nebo zanechali tu rytin svých, kteréž pobral David i muži jeho.'),
(1554346,54,10,5,22,'Opět znovu vytáhli Filistinští, a rozprostřeli se v údolí Refaim.'),
(1554347,54,10,5,23,'I tázal se David Hospodina. Kterýž odpověděl: Netáhni, ale obejda je po zadu, teprv dotřeš na ně naproti moruším.'),
(1554348,54,10,5,24,'A když uslyšíš, že šustí vrchové moruší, hneš se také; nebo tehdáž vyjde Hospodin před tebou, aby zbil vojska Filistinských.'),
(1554349,54,10,5,25,'I učinil David tak, jakž mu přikázal Hospodin, a porazil Filistinské od Gabaa, až kudy se jde do Gázer.'),
(1554350,54,10,6,1,'Tedy sebral opět David výborného lidu z Izraele třidceti tisíc.'),
(1554351,54,10,6,2,'A vstav, šel David i všecken lid, kterýž byl s ním, z Bála Judova, aby přinesli odtud truhlu Boží, při kteréž se vzývá jméno, jméno Hospodina zástupů, sedícího nad cherubíny.'),
(1554352,54,10,6,3,'I vstavili truhlu Boží na nový vůz, vzavše ji z domu Abinadabova, kterýž byl na pahrbku. Uza pak a Achio, synové Abinadabovi, spravovali ten vůz nový.'),
(1554353,54,10,6,4,'A tak vzali ji z domu Abinadabova, kterýž byl na pahrbku, jdouce s truhlou Boží; Achio pak šel před truhlou.'),
(1554354,54,10,6,5,'Ale David i všecken dům Izraelský hrali před Hospodinem na všelijaké nástroje z dříví cedrového, totiž na harfy, loutny, bubny, husličky, a na cymbály.'),
(1554355,54,10,6,6,'A když přišli k humnu Náchonovu, vztáhl ruku svou Uza k truhle Boží a pozdržel jí, nebo uchýlili se volové.'),
(1554356,54,10,6,7,'Protož rozhněval se Hospodin na Uzu, a zabil ho Bůh pro neprozřetelnost; i umřel tu u truhly Boží.'),
(1554357,54,10,6,8,'Tedy zkormoutil se David, proto že se Hospodin tak přísně obořil na Uzu. I nazváno to místo Peres Uza až do tohoto dne.'),
(1554358,54,10,6,9,'A boje se David Hospodina v ten den, řekl: Kterakž má vjíti ke mně truhla Hospodinova?'),
(1554359,54,10,6,10,'Pročež David nechtěl přenésti k sobě truhly Hospodinovy do města svého, ale způsobil to, aby se obrátila do domu Obededoma Gittejského.'),
(1554360,54,10,6,11,'I pobyla truhla Hospodinova v domě Obededoma Gittejského za tři měsíce, a požehnal Hospodin Obededomovi i všemu domu jeho.'),
(1554361,54,10,6,12,'V tom povědíno jest králi Davidovi, že požehnal Hospodin domu Obededomovu i všemu, což má, pro truhlu Boží. Tedy odšed David, přenesl truhlu Boží z domu Obededomova do města Davidova s veselím.'),
(1554362,54,10,6,13,'A když poodešli ti, kteříž nesli truhlu Hospodinovu, na šest kroků, obětoval voly a tučný dobytek.'),
(1554363,54,10,6,14,'David pak poskakoval ze vší síly před Hospodinem, a byl oblečen David v efod lněný.'),
(1554364,54,10,6,15,'A tak David i všecken dům Izraelský provázeli truhlu Hospodinovu s plésáním a zvukem trouby.'),
(1554365,54,10,6,16,'Stalo se pak, když truhla Hospodinova vcházela do města Davidova, že Míkol dcera Saulova vyhlídala z okna, a viduci krále Davida plésajícího a poskakujícího před Hospodinem, pohrdla jím v srdci svém.'),
(1554366,54,10,6,17,'A když přinesli truhlu Hospodinovu, postavili ji na místě jejím u prostřed stanu, kterýž jí byl David rozbil; a obětoval David před Hospodinem oběti zápalné i pokojné.'),
(1554367,54,10,6,18,'Zatím když přestal David obětovati obětí zápalných a pokojných, dal požehnání lidu ve jménu Hospodina zástupů.'),
(1554368,54,10,6,19,'Dal také všemu lidu a všemu množství Izraelskému, od muže až do ženy, jednomu každému jeden pecník chleba a kus masa, a vína láhvici jednu. I odšel všecken lid, jeden každý do domu svého.'),
(1554369,54,10,6,20,'Potom navracoval se David, aby dal požehnání domu svému. I vyšla Míkol dcera Saulova vstříc Davidovi, a řekla: Jak slavný byl dnes král Izraelský, kterýž se odkrýval dnes před děvkami služebníků svých, tak jako se odkrývá jeden z lehkomyslných!'),
(1554370,54,10,6,21,'I řekl David k Míkol: Před Hospodinem, (kterýž mne vyvolil nad otce tvého a nad všecken dům jeho, přikázav mi, abych byl vývodou lidu Hospodinova, totiž Izraele), plésal jsem a plésati budu před Hospodinem.'),
(1554371,54,10,6,22,'Anobrž čím se ještě více opovrhu nežli tuto, a ponížím se u sebe sám, tím i u těch děvek, o nichž jsi mluvila, i u těch, pravím, slavnější budu.'),
(1554372,54,10,6,23,'Protož Míkol dcera Saulova neměla žádného plodu až do dne smrti své.'),
(1554373,54,10,7,1,'I stalo se, že když král seděl v domě svém, a Hospodin jemu dal odpočinutí vůkol přede všemi nepřátely jeho,'),
(1554374,54,10,7,2,'Řekl král Nátanovi proroku: Pohleď medle, já bydlím v domě cedrovém, truhla pak Boží přebývá mezi kortýnami.'),
(1554375,54,10,7,3,'I dí Nátan králi: Cožkoli jest v srdci tvém, jdi, učiň, nebo Hospodin s tebou jest.'),
(1554376,54,10,7,4,'Potom té noci stalo se slovo Hospodinovo k Nátanovi, řkoucí:'),
(1554377,54,10,7,5,'Jdi a pověz služebníku mému Davidovi: Takto praví Hospodin: Zdaliž ty mi stavěti budeš dům, v kterémž bych přebýval?'),
(1554378,54,10,7,6,'Poněvadž jsem nebydlil v domě od toho dne, jakž jsem vyvedl syny Izraelské z Egypta, až do dne tohoto, ale přecházel jsem s stánkem a příbytkem sem i tam.'),
(1554379,54,10,7,7,'Nadto kudyž jsem koli chodil se všechněmi syny Izraelskými, zdali jsem jedno slovo řekl kterému z soudců Izraelských, kterémuž jsem přikázal pásti lid svůj Izraelský, řka: Proč jste mi neustavěli domu cedrového?'),
(1554380,54,10,7,8,'Protož nyní toto díš služebníku mému Davidovi: Takto praví Hospodin zástupů: Jáť jsem tě vzal z ovčince od stáda, abys byl vývodou lidu mého Izraelského.'),
(1554381,54,10,7,9,'A býval jsem s tebou všudy, kamž jsi koli se obracel; všecky také nepřátely tvé vyhladil jsem před tváří tvou, a učinil jsem tobě jméno veliké, jako jméno vyvýšených na zemi.'),
(1554382,54,10,7,10,'Způsobím tolikéž místo lidu svému Izraelskému, a vštípím jej, a bydliti bude v místě svém a nepohne se více, aniž ho budou více trápiti lidé nešlechetní jako prvé,'),
(1554383,54,10,7,11,'Hned od toho dne, jakž jsem ustanovil soudce nad lidem svým Izraelským, až jsem teď dal odpočinutí tobě přede všemi nepřátely tvými. Přesto oznamujeť Hospodin, že on sám tobě dům vzdělá.'),
(1554384,54,10,7,12,'Když se vyplní dnové tvoji, a usneš s otci svými, vzbudím símě tvé po tobě, kteréž vyjde z života tvého, a utvrdím království jeho.'),
(1554385,54,10,7,13,'Onť ustaví dům jménu mému, a já utvrdím trůn království jeho až na věky.'),
(1554386,54,10,7,14,'Já budu jemu otcem, a on mi bude synem. Kterýž když zhřeší, trestati ho budu metlou lidskou a ranami synů lidských.'),
(1554387,54,10,7,15,'Ale milosrdenství mé nebude odjato od něho, tak jako jsem je odjal od Saule, kteréhož jsem zahnal od tváři tvé.'),
(1554388,54,10,7,16,'A tak utvrzen bude dům tvůj a království tvé až na věky před tebou, a trůn tvůj bude stálý až na věky.'),
(1554389,54,10,7,17,'Vedlé všech slov těchto, a podlé všeho vidění tohoto, tak mluvil Nátan Davidovi.'),
(1554390,54,10,7,18,'Tedy všed král David, posadil se před Hospodinem a řekl: Kdo jsem já, Panovníče Hospodine, a jaký jest dům můj, že jsi mne přivedl v ta místa.'),
(1554391,54,10,7,19,'Nýbrž ještěť se to málo vidělo, Panovníče Hospodine, že jsi také mluvil i o domu služebníka svého na dlouhé časy, ješto jest to povaha lidská, Panovníče Hospodine.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554392,54,10,7,20,'Ale což již více má mluviti David před tebou? Však ty znáš služebníka svého, Panovníče Hospodine.'),
(1554393,54,10,7,21,'Pro slovo své a podlé srdce svého činíš všecky tyto věci veliké, v známost je uvodě služebníku svému.'),
(1554394,54,10,7,22,'(Protož zveleben jsi Hospodine Bože, nebo není tobě rovného, anobrž není žádného Boha kromě tebe), podlé toho všeho, jakž jsme slýchali ušima svýma.'),
(1554395,54,10,7,23,'Kdo tedy jest jako lid tvůj, jako Izrael, který národ na zemi, jehož by Bůh šel, aby jej sobě vykoupil za lid, a dobyl sobě jména, a učinil tobě, ó Izraeli, tyto veliké věci a hrozné v zemi tvé, před oblíčejem lidu svého, kterýž jsi sobě vysvobodil z Egypta, z pohanstva bohů jejich?'),
(1554396,54,10,7,24,'A vzdělal jsi sobě lid svůj Izraelský, sobě v lid až na věky, a protož, Hospodine, jsi jejich Bohem.'),
(1554397,54,10,7,25,'Nyní tedy, Hospodine Bože, slovo to, jímž jsi se zamluvil služebníku svému a domu jeho, naplniž je až na věky, a učiň tak, jakž jsi mluvil,'),
(1554398,54,10,7,26,'Tak aby zvelebováno bylo jméno tvé až na věky, když se říkati bude: Hospodin zástupů jest Bůh nad Izraelem, a dům služebníka tvého Davida aby byl stálý před oblíčejem tvým.'),
(1554399,54,10,7,27,'Nebo ty, Hospodine zástupů, Bože Izraelský, zjevil jsi mně služebníku svému, řka: Dům ustavím tobě. Protož usoudil služebník tvůj v srdci svém, aby se modlil tobě modlitbou touto.'),
(1554400,54,10,7,28,'A tak již, Panovníče Hospodine, ty sám jsi Bůh, a slova tvá jsou pravda, jimiž jsi zaslíbil služebníku svému dobré věci tyto.'),
(1554401,54,10,7,29,'Již tedy rač požehnati domu služebníka svého, aby trval na věky před oblíčejem tvým. Nebo ty jsi, Hospodine Bože, mluvil, že požehnáním tvým požehnán bude dům služebníka tvého na věky.'),
(1554402,54,10,8,1,'Stalo se potom, že porazil David Filistinské, a zemdlil je; i vzal David Meteg Amma z ruky Filistinských.'),
(1554403,54,10,8,2,'Porazil také Moábské a změřil je provazcem, na zemi je rozprostíraje; a odměřil jich dva provazce k zbití a celý provazec k živení. I učiněni jsou Moábští Davidovi služebníci, a dávali jemu plat.'),
(1554404,54,10,8,3,'Porazil též David Hadadezera syna Rohobova, krále Soba, když byl vytáhl, aby rozšířil končiny své až k řece Eufraten.'),
(1554405,54,10,8,4,'A pobral mu David tisíc vozů a sedm set jezdců, a dvadceti tisíc mužů pěších, a zpodřezoval David žily všechněm koňům vozníkům; toliko zanechal z nich ke stu vozům.'),
(1554406,54,10,8,5,'Přitáhli pak byli Syrští od Damašku na pomoc Hadadezerovi králi Soba, ale David porazil z Syrských dvamecítma tisíc mužů.'),
(1554407,54,10,8,6,'Tedy osadil David stráží Syrii Damašskou, a byli Syrští služebníci Davidovi, dávajíce plat; nebo zachovával Hospodin Davida, kamžkoli se obrátil.'),
(1554408,54,10,8,7,'Pobral také David štíty zlaté, kteréž měli služebníci Hadadezerovi, a přinesl je do Jeruzaléma.'),
(1554409,54,10,8,8,'Z Betach též a z Berot, měst Hadadezerových, nabral král David velmi mnoho mědi.'),
(1554410,54,10,8,9,'A když uslyšel Tohi král Emat, že porazil David všecko vojsko Hadadezerovo,'),
(1554411,54,10,8,10,'Poslal Tohi Jorama syna svého k králi Davidovi, aby ho pozdravil přátelsky, a spolu s ním se radoval z toho, že šťastně bojoval s Hadadezerem, a porazil ho; (nebo Hadadezer vedl válku proti Tohi). Kterýžto přinesl s sebou nádoby stříbrné, též nádoby zlaté a nádoby měděné.'),
(1554412,54,10,8,11,'Ty také obětoval král David Hospodinu s stříbrem a zlatem posvěceným ze všech národů, kteréž podmanil,'),
(1554413,54,10,8,12,'Totiž z Syrských a Moábských, též z synů Ammon a z Filistinských, i z Amalechitských a z kořistí Hadadezera syna Rohobova, krále Soba.'),
(1554414,54,10,8,13,'Zvelebil také David své jméno, když se navracoval od pobití osmnácti tisíců Syrských v údolí solnatém.'),
(1554415,54,10,8,14,'Protož i nad Idumejskými stráž postavil, všecku krajinu Idumejskou stráží osadiv. I učiněni jsou všickni Idumejští služebníci Davidovi; nebo zachovával Hospodin Davida, kamž se koli obrátil.'),
(1554416,54,10,8,15,'I kraloval David nade vším Izraelem, a činil David soud a spravedlnost všemu lidu svému.'),
(1554417,54,10,8,16,'Joáb pak syn Sarvie byl nad vojskem, a Jozafat syn Achiludův kancléřem;'),
(1554418,54,10,8,17,'Sádoch také syn Achitobův a Achimelech syn Abiatarův kněžími, a Saraiáš písařem.'),
(1554419,54,10,8,18,'Benaiáš pak syn Joiadův byl nad Cheretejskými a Peletejskými, a synové Davidovi knížaty.'),
(1554420,54,10,9,1,'Tedy řekl David: Jest-li ještě kdo pozůstalý z domu Saulova, abych jemu učinil milosrdenství pro Jonatu?'),
(1554421,54,10,9,2,'Byl pak služebník domu Saulova, jehož jméno bylo Síba. I zavolali ho k Davidovi. I řekl král jemu: Ty-li jsi Síba? Odpověděl: Jsem služebník tvůj.'),
(1554422,54,10,9,3,'Řekl jemu král: Jest-liž ještě kdo z domu Saulova, abych jemu učinil milosrdenství Boží? Odpověděl Síba králi: Ještě jest syn Jonatův chromý na nohy.'),
(1554423,54,10,9,4,'I řekl jemu král: Kdež jest? Odpověděl Síba králi: Tam jest v domě Machiry, syna Amielova v Lodebar.'),
(1554424,54,10,9,5,'Protož poslav král David, vzal ho z domu Machiry, syna Amielova z Lodebar.'),
(1554425,54,10,9,6,'A když přišel Mifibozet syn Jonaty, syna Saulova, k Davidovi, padl na tvář svou a poklonil se. I řekl David: Mifibozete. Kterýž odpověděl: Aj, služebník tvůj.'),
(1554426,54,10,9,7,'Řekl jemu David: Neboj se, nebo jistě učiním s tebou milosrdenství pro Jonatu otce tvého, a navrátím tobě všecka pole Saule otce tvého, a ty jídati budeš za stolem mým vždycky.'),
(1554427,54,10,9,8,'Kterýž pokloniv se, řekl: Co jest služebník tvůj, že jsi se ohlédl na psa mrtvého, jakýž jsem já?'),
(1554428,54,10,9,9,'Zatím povolal král Síby, služebníka Saulova a řekl jemu: Cožkoli měl Saul i všecka čeled jeho, to jsem dal synu pána tvého.'),
(1554429,54,10,9,10,'Budeš tedy jemu spravovati rolí, ty i synové tvoji i služebníci tvoji, a snášeti budeš, aby měl syn pána tvého pokrm, kterýž by jedl, ale Mifibozet syn pána tvého jídati bude vždycky za stolem mým. (Měl pak Síba patnácte synů a dvadceti služebníků.)'),
(1554430,54,10,9,11,'Odpověděl Síba králi: Vedlé všeho, jakž přikázal pán můj král služebníku svému, tak učiní služebník tvůj, ačkoli i Mifibozet mohl by jídati za stolem mým jako jeden z synů královských.'),
(1554431,54,10,9,12,'Měl také Mifibozet syna malého, jemuž jméno bylo Mícha; a všickni, kteříž bydlili v domě Síbově, byli za služebníky Mifibozetovi.'),
(1554432,54,10,9,13,'A tak Mifibozet zůstával v Jeruzalémě, proto že vždycky za stolem královským jídal; a byl kulhavý na obě noze.'),
(1554433,54,10,10,1,'Stalo se také potom, že umřel král Ammonitský, a kraloval Chanun syn jeho po něm.'),
(1554434,54,10,10,2,'I řekl David: Učiním milosrdenství s Chanunem synem Náhasovým, jakož otec jeho učinil milosrdenství nade mnou. Tedy poslal David, aby ho potěšil skrze služebníky své pro otce jeho. I přišli služebníci Davidovi do země Ammonitských.'),
(1554435,54,10,10,3,'I řekla knížata Ammonitská k Chanunovi, pánu svému: Cožť se zdá, že David činí poctivost otci tvému, že poslal k tobě, kteříž by tě potěšili? Zdaliž ne proto, aby shlédl město a vyšpehoval je, a potom je podvrátil, poslal David služebníky své k tobě?'),
(1554436,54,10,10,4,'A tak Chanun vzav služebníky Davidovy, oholil každému půl brady, a zustřihoval roucha jejich až do polovice, totiž až do zadků jejich, a propustil je.'),
(1554437,54,10,10,5,'To když oznámili Davidovi, poslal proti nim, (nebo muži ti zohaveni byli velice), a řekl jim král: Pobuďte v Jerichu, dokudž neobrostou brady vaše, potom se navrátíte.'),
(1554438,54,10,10,6,'Vidouce pak Ammonitští, že se zošklivili Davidovi, poslavše, najali ze mzdy z Syrie z domu Rohob, a z Syrie Soba dvadcet tisíců pěších, a od krále Maacha tisíc mužů, a od Istoba dvanácte tisíc mužů.'),
(1554439,54,10,10,7,'Což uslyšev David, poslal Joába se vším vojskem udatných.'),
(1554440,54,10,10,8,'A tak vytáhše Ammonitští, šikovali se k boji u brány, Syrští také, Soba a Rohob, a Istob i Maacha zvláště byli na poli.'),
(1554441,54,10,10,9,'A protož vida Joáb proti sobě sšikovaný boj s předu i s zadu, vybrav některé ze všech výborných Izraelských, sšikoval je také proti Syrským.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554442,54,10,10,10,'Ostatek pak lidu dal pod správu Abizai bratra svého, a sšikoval jej proti Ammonitským.'),
(1554443,54,10,10,11,'A řekl: Jestliže Syrští budou silnější mne, přispěješ mi na pomoc; jestliže pak Ammonitští silnější budou tebe, také přispěji, abych pomohl tobě.'),
(1554444,54,10,10,12,'Posiliž se, a buďme udatní, bojujíce za lid náš a za města Boha našeho, Hospodin pak učiní, což se jemu dobře líbiti bude.'),
(1554445,54,10,10,13,'I přistoupil Joáb s lidem svým k bitvě proti Syrským, a oni utekli před ním.'),
(1554446,54,10,10,14,'Tedy Ammonitští vidouce, že utíkají Syrští, utekli i oni před Abizai a vešli do města. I navrátil se Joáb od Ammonitských a přišel do Jeruzaléma.'),
(1554447,54,10,10,15,'Ale Syrští vidouce, že by poraženi byli od Izraele, sebrali se vespolek.'),
(1554448,54,10,10,16,'Poslal také Hadarezer a vyvedl Syrské, kteříž bydlejí za řekou, a přišli k Helam; Sobach pak, hejtman vojska Hadarezerova, vedl je.'),
(1554449,54,10,10,17,'I oznámeno to Davidovi. Kterýžto shromáždiv všecken lid Izraelský, přepravil se přes Jordán, a přitáhli k Helam. I sšikovali se Syrští proti Davidovi, a bojovali proti němu.'),
(1554450,54,10,10,18,'Tedy utekli Syrští před Izraelem, a porazil David z Syrských sedm set vozů a čtyřidceti tisíc jezdců. Sobacha také hejtmana vojska toho ranil, i umřel tu.'),
(1554451,54,10,10,19,'Když pak viděli všickni králové, kteříž byli při Hadarezerovi, že jsou poraženi od Izraele, vešli v pokoj s Izraelem a sloužili jemu. A nesměli již více Syrští táhnouti na pomoc Ammonitským.'),
(1554452,54,10,11,1,'I stalo se po roce, když králové vyjíždívají na vojnu, že poslal David Joába a služebníky své s ním, též i všecken Izrael, aby hubili Ammonitské; i oblehli Rabba. David pak zůstal v Jeruzalémě.'),
(1554453,54,10,11,2,'Tedy stalo se k večerou, když vstal David s ložce svého, procházeje se po paláci domu královského, že uzřel s paláce ženu, ana se myje; kterážto žena byla vzezření velmi krásného.'),
(1554454,54,10,11,3,'A poslav David, vyptal se o té ženě a řekl: Není-liž to Betsabé dcera Eliamova, manželka Uriáše Hetejského?'),
(1554455,54,10,11,4,'Opět poslal David posly a vzal ji. Kterážto když vešla k němu, obýval s ní; (nebo se byla očistila od nečistoty své). Potom navrátila se do domu svého.'),
(1554456,54,10,11,5,'I počala žena ta. Protož poslavši, oznámila Davidovi, řkuci: Těhotná jsem.'),
(1554457,54,10,11,6,'Poslav pak David, vzkázal Joábovi: Pošli ke mně Uriáše Hetejského. I poslal Joáb Uriáše k Davidovi.'),
(1554458,54,10,11,7,'A když přišel Uriáš k němu, otázal se ho, jak se má Joáb, a jak se má lid, a kterak se vede v vojště?'),
(1554459,54,10,11,8,'Řekl také David Uriášovi: Jdiž do domu svého, a umyj sobě nohy. I vyšel Uriáš z domu králova, a poslán za ním dar královský.'),
(1554460,54,10,11,9,'Ale Uriáš spal u vrat domu královského se všemi služebníky pána svého, a nešel do domu svého.'),
(1554461,54,10,11,10,'Což když oznámili Davidovi, řkouce: Nešel Uriáš do domu svého, řekl David Uriášovi: Však jsi z cesty přišel. Pročež jsi nešel do domu svého?'),
(1554462,54,10,11,11,'Odpověděl Uriáš Davidovi: Truhla Boží a Izrael i Juda zůstávají v staních, a pán můj Joáb i služebníci pána mého na poli zůstávají, já pak mám vjíti do domu svého, abych jedl a pil, a spal s manželkou svou? Jakož jsi živ ty, a jako jest živa duše tvá, žeť toho neučiním.'),
(1554463,54,10,11,12,'Tedy řekl David Uriášovi: Pobuď zde ještě dnes, a zítra propustím tebe. I zůstal Uriáš v Jeruzalémě toho dne i nazejtří.'),
(1554464,54,10,11,13,'V tom pozval ho David, aby jedl před ním a pil, a opojil ho. A však on šel večer spáti na ložce své s služebníky pána svého, a nešel do domu svého.'),
(1554465,54,10,11,14,'A když bylo ráno, napsal David list Joábovi, kterýž poslal po Uriášovi.'),
(1554466,54,10,11,15,'Psal pak v listu těmi slovy: Postavte Uriáše proti bojovníkům nejsilnějším; mezi tím odstupte nazpět od něho, aby raněn jsa, umřel.'),
(1554467,54,10,11,16,'I stalo se, když oblehl Joáb město, že postavil Uriáše proti místu, kdež věděl, že jsou nejsilnější muži.'),
(1554468,54,10,11,17,'A vyskočivše muži z města, bojovali proti Joábovi. I padli někteří z lidu, z služebníků Davidových, také i Uriáš Hetejský zabit.'),
(1554469,54,10,11,18,'Tedy poslav Joáb, oznámil Davidovi všecko, což se zběhlo v bitvě.'),
(1554470,54,10,11,19,'A přikázal tomu poslu, řka: Když vypravíš králi všecky věci, které se zběhly v bitvě,'),
(1554471,54,10,11,20,'Při čemž jestliže se popudí prchlivost královská a řekne-liť: Proč jste přistoupili k městu, bojujíce? Zdaliž jste nevěděli, že házejí se zdi?'),
(1554472,54,10,11,21,'Kdo zabil Abimelecha syna Jerobosetova? Zdali ne žena, svrhši na něj kus žernovu se zdi, tak že umřel v Tébes? Proč jste přistupovali ke zdi? tedy díš: Také služebník tvůj Uriáš Hetejský umřel.'),
(1554473,54,10,11,22,'A tak šel posel, a přišed, oznámil Davidovi všecko to, pročež ho byl poslal Joáb.'),
(1554474,54,10,11,23,'A řekl posel ten Davidovi: Zmocnili se nás muži ti, a vytrhli proti nám do pole, a honili jsem je až k bráně.'),
(1554475,54,10,11,24,'V tom stříleli střelci na služebníky tvé se zdi, a zbiti jsou někteří z služebníků králových, také i služebník tvůj Uriáš Hetejský zabit.'),
(1554476,54,10,11,25,'Tedy řekl David poslu: Tak pověz Joábovi: Nic tě to nerozpakuj, že tak i jinak sehlcuje meč. Ztuž boj svůj proti městu a zkaz je, a potěš drábů.'),
(1554477,54,10,11,26,'Uslyševši pak manželka Uriášova, že umřel Uriáš muž její, plakala manžela svého.'),
(1554478,54,10,11,27,'A když pominul pláč, poslav David, vzal ji do domu svého, a měl ji za manželku; i porodila mu syna. Ale nelíbilo se to Hospodinu, co učinil David.'),
(1554479,54,10,12,1,'Protož poslal Hospodin Nátana k Davidovi. Kterýž přišed k němu, řekl jemu: Dva muži byli v městě jednom, jeden bohatý a druhý chudý.'),
(1554480,54,10,12,2,'Bohatý měl ovec i volů velmi mnoho,'),
(1554481,54,10,12,3,'Chudý pak neměl nic, kromě jednu ovečku malou, kterouž byl koupil a choval, až i odrostla při něm a při dětech jeho tolikéž. Chléb jeho jedla a z číše jeho pila, a v lůnu jeho spávala, a tak byla mu jako za dceru.'),
(1554482,54,10,12,4,'Když pak přišel pocestný k tomu bohatému člověku, líto mu bylo vzíti z ovcí aneb z volů svých, což by připravil pocestnému, kterýž k němu přišel, ale vzav ovečku toho chudého člověka, připravil ji muži, kterýž byl přišel k němu.'),
(1554483,54,10,12,5,'Tedy rozhněval se David na muže toho náramně a řekl Nátanovi: Živť jest Hospodin, že hoden jest smrti muž, kterýž to učinil.'),
(1554484,54,10,12,6,'Ovečku také tu zaplatí čtvernásobně, proto že učinil věc tu, a nelitoval ho.'),
(1554485,54,10,12,7,'I řekl Nátan Davidovi: Ty jsi ten muž! Takto praví Hospodin Bůh Izraelský: Já jsem tě pomazal, abys králem byl nad Izraelem, a vytrhl jsem tebe z ruky Saulovy.'),
(1554486,54,10,12,8,'A dal jsem tobě dům pána tvého, i ženy pána tvého v lůno tvé, dalť jsem také dům Izraelský a Judský, a bylo-liť by to málo, byl bych přidal mnohem více.'),
(1554487,54,10,12,9,'Pročež jsi sobě zlehčil slovo Hospodinovo, čině to, což se nelíbí jemu? Uriáše Hetejského zabil jsi mečem, a manželku jeho pojals sobě za ženu, samého pak zamordoval jsi mečem Ammonitských.'),
(1554488,54,10,12,10,'Protož nyní neodejdeť meč z domu tvého až na věky, proto že jsi pohrdl mnou, a vzal jsi manželku Uriáše Hetejského, aby byla žena tvá.'),
(1554489,54,10,12,11,'Takto praví Hospodin: Aj, já vzbudím proti tobě zlé z domu tvého, a vezma ženy tvé před očima tvýma, dám je bližnímu tvému, kterýž spáti bude s ženami tvými, an na to každý hledí.'),
(1554490,54,10,12,12,'A ačkoli ty učinil jsi to tajně, já však učiním to zjevně přede vším Izraelem a všechněm známě.'),
(1554491,54,10,12,13,'Tedy řekl David Nátanovi: Zhřešilť jsem Hospodinu. Zase řekl Nátan Davidovi: Tentýž Hospodin přenesl hřích tvůj, neumřeš.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554492,54,10,12,14,'Ale však, poněvadž jsi tou věcí dal příčinu nepřátelům Hospodinovým, aby se rouhali, protož ten syn, kterýž se narodil tobě, jistotně umře.'),
(1554493,54,10,12,15,'Potom odšel Nátan do domu svého. V tom Hospodin ranil dítě, kteréž byla porodila manželka Uriášova Davidovi, tak že pochybili o něm.'),
(1554494,54,10,12,16,'I modlil se David Bohu za to dítě a postil se, a všed, ležel přes noc na zemi.'),
(1554495,54,10,12,17,'A ačkoli starší domu jeho přišli k němu, aby ho zdvihli z země, on však nechtěl, aniž s nimi co jedl.'),
(1554496,54,10,12,18,'Stalo se pak dne sedmého, že umřelo dítě. I nesměli služebníci Davidovi toho oznámiti jemu, že by umřelo dítě; nebo pravili: Aj, když ještě bylo dítě živo, mluvili jsme jemu, a nechtěl slyšeti hlasu našeho, což pak když jemu díme: Umřelo dítě. Ovšem to tíže ponese.'),
(1554497,54,10,12,19,'Ale vida David, an služebníci jeho k sobě šepcí, srozuměl, že by umřelo dítě. I řekl David služebníkům svým: Co již umřelo dítě? Kteříž řekli: Umřelo.'),
(1554498,54,10,12,20,'Tedy vstav David s země, umyl se a pomazal se, a změnil roucho své, a všed do domu Hospodinova, pomodlil se. Potom vrátiv se do domu svého, rozkázal sobě dáti jísti a jedl.'),
(1554499,54,10,12,21,'Služebníci pak jeho řekli jemu: Co jsi to učinil? Pro dítě, když živo bylo, postils se a plakal, ale jakž dítě umřelo, vstal jsi a přijal jsi pokrm.'),
(1554500,54,10,12,22,'Kterýžto řekl: Pokudž ještě dítě živo bylo, postil jsem se a plakal, nebo jsem řekl: Kdo ví? Můžeť se smilovati nade mnou Hospodin, aby živo bylo dítě.'),
(1554501,54,10,12,23,'Nyní pak, poněvadž umřelo, proč se mám postiti? Zdaliž budu moci zase je vzkřísiti? Jáť půjdu k němu, ale ono se nenavrátí ke mně.'),
(1554502,54,10,12,24,'Potom David potěšiv Betsabé manželky své, všel k ní a spal s ní. I porodila syna, a nazval jméno jeho Šalamoun, a Hospodin miloval jej.'),
(1554503,54,10,12,25,'Protož poslal byl Nátana proroka, a nazval jméno jeho Jedidiah pro Hospodina.'),
(1554504,54,10,12,26,'Bojoval pak Joáb proti Rabba Ammonitských, a vzal město královské.'),
(1554505,54,10,12,27,'A poslav posly k Davidovi, řekl: Dobýval jsem Rabba a vzal jsem město vod.'),
(1554506,54,10,12,28,'Protož nyní sebera ostatek lidu, polož se proti městu a vezmi je, abych já nevzal města toho, a bylo by mně připisováno vítězství nad ním.'),
(1554507,54,10,12,29,'Tedy sebrav David všecken lid, vytáhl proti Rabba, kteréhož dobýval a vzal je.'),
(1554508,54,10,12,30,'A sňal korunu krále jejich s hlavy jeho, kteráž vážila centnéř zlata, a bylo v ní kamení drahé, a vstavena byla na hlavu Davidovu. Vyvezl též kořisti města velmi veliké.'),
(1554509,54,10,12,31,'Lid pak, kterýž v něm byl, vyvedl a dal jej pod pily a pod brány železné a pod sekery železné, a vehnal je do peci cihelné. A tak činil všechněm městům Ammonitským. Potom navrátil se David se vším lidem do Jeruzaléma.'),
(1554510,54,10,13,1,'I stalo se potom, že Absolon syn Davidův měl sestru krásnou, jménem Támar; i zamiloval ji Amnon syn Davidův.'),
(1554511,54,10,13,2,'A tak se o to trápil Amnon, že i v nemoc upadl pro Támar sestru svou; nebo panna byla, a viděl Amnon, že nesnadně bude jí moci co učiniti.'),
(1554512,54,10,13,3,'Měl pak Amnon přítele, jehož jméno bylo Jonadab, syn Semmaa bratra Davidova, kterýžto Jonadab byl muž velmi chytrý.'),
(1554513,54,10,13,4,'I řekl jemu: Proč tak chřadneš, synu králův, den ode dne? Neoznámíš-liž mi? I řekl mu Amnon: Támar sestru Absolona bratra svého miluji.'),
(1554514,54,10,13,5,'Tedy řekl jemu Jonadab: Polož se na lůže své a udělej se nemocným, a když přijde otec tvůj, aby tě navštívil, díš jemu: Nechť přijde, prosím, Támar sestra má a dá mi jísti, připravíc před očima mýma pokrm, abych viděl a jedl z ruky její.'),
(1554515,54,10,13,6,'A tak složil se Amnon, dělaje se nemocným. A když přišel král, aby ho navštívil, řekl Amnon králi: Nechť přijde, prosím, Támar sestra má a připraví před očima mýma asi dvě krmičky, abych pojedl z ruky její.'),
(1554516,54,10,13,7,'Protož poslal David k Támar do domu, řka: Jdi hned do domu Amnona bratra svého a připrav mu krmičku.'),
(1554517,54,10,13,8,'I šla Támar do domu Amnona bratra svého; on pak ležel. A vzavši mouky, zadělala ji, a připravivši krmičku před očima jeho, uvařila ji.'),
(1554518,54,10,13,9,'Potom vzavši pánvici, vyložila před něj, a on nechtěl jísti. (I řekl Amnon: Spravte to, ať vyjdou všickni ven. I vyšli od něho všickni.'),
(1554519,54,10,13,10,'Řekl pak Amnon k Támar: Přines tu krmičku do pokojíka, abych pojedl z ruky tvé. A vzavši Támar krmičku, kterouž připravila, přinesla ji před Amnona bratra svého do pokojíka.)'),
(1554520,54,10,13,11,'Ale když mu podávala, aby jedl, uchopil ji a řekl jí: Poď, lež se mnou, sestro má.'),
(1554521,54,10,13,12,'Kterážto řekla jemu: Nikoli, bratře můj, nečiň mi násilí, nebo ne tak se má díti v Izraeli. Neprovoď nešlechetnosti této.'),
(1554522,54,10,13,13,'Nebo já na koho svedu pohanění své? Ty pak budeš jako jeden z nejnešlechetnějších v Izraeli. Raději tedy mluv medle s králem, nebo neodepřeť mne tobě.'),
(1554523,54,10,13,14,'Ale nechtěl uposlechnouti hlasu jejího, nýbrž zmocniv se jí, učinil jí násilí a ležel s ní.'),
(1554524,54,10,13,15,'Potom vzal ji Amnon v nenávist velikou velmi, tak že větší byla nenávist, kterouž nenáviděl jí, než milost, kterouž ji miloval. I řekl jí Amnon: Vstaň a jdi pryč.'),
(1554525,54,10,13,16,'Kterážto odpověděla jemu: Za příčinou převelmi zlé věci té, kterouž jsi při mně spáchal, druhé horší se dopouštíš, že mne vyháníš. On pak nechtěl jí slyšeti.'),
(1554526,54,10,13,17,'Ale zavolav mládence, kterýž mu přisluhoval, řekl: Vyveď hned tuto ode mne ven, a zamkni dvéře po ní.'),
(1554527,54,10,13,18,'(Měla pak na sobě sukni proměnných barev, nebo v takových sukních chodívaly dcery královské panny.) A tak vyvedl ji ven služebník jeho a zamkl dvéře po ní.'),
(1554528,54,10,13,19,'Tedy posypala Támar hlavu svou popelem, a sukni proměnných barev, kterouž měla na sobě, roztrhla; a vložila ruku na hlavu svou, a jduc, křičela s naříkáním.'),
(1554529,54,10,13,20,'I řekl jí Absolon bratr její: Nebyl-liž Amnon bratr tvůj s tebou? Ale nyní, sestro má mlč; bratr tvůj jest, nepřipouštěj toho k srdci. A tak zůstala Támar, jsuc opuštěná, v domě Absolona bratra svého.'),
(1554530,54,10,13,21,'A uslyšev král David o těch všech věcech, rozhněval se náramně.'),
(1554531,54,10,13,22,'Absolon pak nic nemluvil s Amnonem, ani dobrého ani zlého; nebo nenáviděl Absolon Amnona, proto že učinil násilí Támar sestře jeho.'),
(1554532,54,10,13,23,'I stalo se po celých dvou letech, když střihli ovce Absolonovi v Balazor, jenž jest podlé Efraim, že pozval Absolon všech synů královských.'),
(1554533,54,10,13,24,'Nebo přišel Absolon k králi a řekl: Aj, nyní služebník tvůj má střižce; nechť, prosím, jde král a služebníci jeho s služebníkem tvým.'),
(1554534,54,10,13,25,'I řekl král Absolonovi: Nechť, synu můj, nechť nyní nechodíme všickni, abychom tě neobtěžovali. A ačkoli nutkal ho, však nechtěl jíti, ale požehnal mu.'),
(1554535,54,10,13,26,'Řekl ještě Absolon: Nechť aspoň s námi jde, prosím, Amnon bratr můj. Odpověděl jemu král: Proč by s tebou šel?'),
(1554536,54,10,13,27,'A když vždy dotíral Absolon, poslal s ním Amnona i všecky syny královské.'),
(1554537,54,10,13,28,'Přikázal pak byl Absolon služebníkům svým, řka: Šetřte medle, když se rozveselí srdce Amnonovo vínem, a řeknu vám: Bíte Amnona, tedy zabíte jej. Nebojte se nic, nebo zdaliž jsem já nerozkázal vám? Posilňte se a mějte se zmužile.'),
(1554538,54,10,13,29,'I učinili Amnonovi služebníci Absolonovi, jakž jim byl přikázal Absolon. Pročež vstavše všickni synové královi, vsedli jeden každý na mezka svého a utekli.'),
(1554539,54,10,13,30,'V tom když ještě byli na cestě, přišla taková pověst k Davidovi: Pobil Absolon všecky syny královské, tak že z nich ani jednoho nezůstalo.'),
(1554540,54,10,13,31,'Tedy vstav král, roztrhl roucha svá a ležel na zemi; všickni také služebníci jeho stáli, roztrhše roucha.'),
(1554541,54,10,13,32,'Ozval se pak Jonadab, syn Semmaa bratra Davidova, a řekl: Nepraviž toho, pane můj, jako by všecky mládence syny královy zbili, ale Amnon toliko zabit; nebo tak v úmysle Absolonově složeno bylo od toho dne, jakž on byl učinil násilí Támar sestře jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554542,54,10,13,33,'Protož nechať nepřipouští toho nyní pán můj král k srdci svému, mysle, že by všickni synové královi zbiti byli; nebo Amnon toliko umřel.'),
(1554543,54,10,13,34,'Absolon pak utekl. Tedy pozdvih služebník hlásný očí svých, uzřel, an mnoho lidu jde odtud, kudyž se chodilo k němu cestou pod horami.'),
(1554544,54,10,13,35,'I řekl Jonadab králi: Aj, synové královští přijíždějí. Vedlé řeči služebníka tvého tak se stalo.'),
(1554545,54,10,13,36,'A když přestal mluviti, aj, synové královští přišli, a pozdvihše hlasu svého, plakali; též také král i všickni služebníci jeho plakali pláčem velmi velikým.'),
(1554546,54,10,13,37,'Absolon pak utekl a ušel k Tolmai synu Amiudovu, králi Gessur. I plakal David syna svého po všecky ty dny.'),
(1554547,54,10,13,38,'Absolon tedy utíkaje, přišel do Gessur, a byl tam tři léta.'),
(1554548,54,10,13,39,'Potom žádal David vyjíti k Absolonovi, nebo již byl oželel smrti Amnonovy.'),
(1554549,54,10,14,1,'Srozuměv pak Joáb syn Sarvie, že by naklonilo se srdce královo k Absolonovi,'),
(1554550,54,10,14,2,'Poslav do Tekoa, a povolav odtud ženy moudré, řekl jí: Medle, udělej se, jako bys zámutek měla, a oblec se, prosím, v roucho smutku, a nepomazuj se olejem, ale buď jako žena již za mnoho dní zámutek mající nad mrtvým.'),
(1554551,54,10,14,3,'I půjdeš k králi a mluviti mu budeš vedlé řeči této. A naučil ji Joáb, co by měla mluviti.'),
(1554552,54,10,14,4,'Protož mluvila žena ta Tekoitská králi, padši na tvář svou k zemi, a poklonu učinivši, řekla: Spomoz, ó králi.'),
(1554553,54,10,14,5,'I řekl jí král: Což jest tobě? Odpověděla ona: Zajisté žena vdova jsem, a umřel mi muž můj.'),
(1554554,54,10,14,6,'Měla pak služebnice tvá dva syny, kteříž svadili se spolu na poli, a když nebyl, kdo by je rozvadil, udeřil jeden druhého a zabil ho.'),
(1554555,54,10,14,7,'Aj, teď povstala všecka rodina proti služebnici tvé, a řekli: Vydej toho, jenž zabil bratra svého, ať ho zabijeme za život bratra jeho, kteréhož zamordoval, nýbrž zahubíme i dědice. A tak uhasí jiskru mou, kteráž pozůstala, aby nezanechali muži mému jména a ostatku na zemi.'),
(1554556,54,10,14,8,'Tedy řekl král ženě: Navrať se do domu svého, a jáť poručím o tobě.'),
(1554557,54,10,14,9,'I odpověděla žena Tekoitská králi: Nechť jest, pane můj králi, na mne ta nepravost, a na dům otce mého, král pak a stolice jeho ať jest bez viny.'),
(1554558,54,10,14,10,'Řekl také král: Bude-li kdo mluviti co proti tobě, přiveď ho ke mně, a nedotkneť se tebe více.'),
(1554559,54,10,14,11,'Tedy ona řekla: Rozpoměň se, prosím, králi, na Hospodina Boha svého, aby se nerozmnožili mstitelé krve k zhoubě a nezahladili syna mého. I odpověděl: Živť jest Hospodin, žeť nespadne vlas syna tvého na zemi.'),
(1554560,54,10,14,12,'K tomu řekla žena: Nechť promluví, prosím, služebnice tvá pánu svému králi slovo. Kterýžto odpověděl: Mluv.'),
(1554561,54,10,14,13,'I řekla žena: Proč jsi tedy myslil podobnou věc proti lidu Božímu? Nebo mluví král řeč tuto jako ten, kterýž sebe vinného činí, poněvadž nechce zase povolati vyhnaného svého.'),
(1554562,54,10,14,14,'Všickniť jsme zajisté nepochybně smrtelní a jako vody, kteréž rozlity jsouce po zemi, zase sebrány býti nemohou, aniž se Bůh na něčí osobu ohlédá; ovšemť i myšlení svá vynesl, aby vyhnaného nevyháněl od sebe.'),
(1554563,54,10,14,15,'Nyní pak, že jsem přišla ku pánu svému králi mluviti řeči tyto, příčina jest, že mne strašil lid. Protož řekla služebnice tvá: Budu nyní mluviti králi, snad naplní král žádost služebnice své.'),
(1554564,54,10,14,16,'Neboť vyslyší král a vysvobodí služebnici svou z ruky muže, chtějícího vyhladiti mne i syna mého spolu z dědictví Božího.'),
(1554565,54,10,14,17,'Řekla také služebnice tvá: Vždyť mi bude slovo pána mého krále k odtušení; (nebo jako anděl Boží, tak jest pán můj král, když slyší dobré aneb zlé), a Hospodin Bůh tvůj bude s tebou.'),
(1554566,54,10,14,18,'A odpovídaje král, řekl ženě: Medle, netaj přede mnou toho, nač se já tebe vzeptám. I řekla žena: Mluv, prosím, pane můj králi.'),
(1554567,54,10,14,19,'Tedy řekl král: Není-liž Joáb jednatel všeho tohoto? I odpověděla žena a řekla: Jako jest živa duše tvá, pane můj králi, žeť se nelze uchýliti na pravo aneb na levo ode všeho toho, což mluvil pán můj král; nebo služebník tvůj Joáb, onť jest mi rozkázal, a on naučil služebnici tvou všechněm slovům těmto,'),
(1554568,54,10,14,20,'A abych tak příkladně vedla řeč tuto, způsobil to služebník tvůj Joáb. Ale pán můj moudrý jest jako anděl Boží, věda, což se koli děje na zemi.'),
(1554569,54,10,14,21,'A protož řekl král Joábovi: Aj, již jsem to učinil. Jdiž tedy, přiveď mládence Absolona.'),
(1554570,54,10,14,22,'I padl Joáb na tvář svou k zemi, a pokloniv se, poděkoval králi, a řekl Joáb: Dnes jest poznal služebník tvůj, že jsem nalezl milost před očima tvýma, pane můj králi, poněvadž jest král naplnil žádost služebníka svého.'),
(1554571,54,10,14,23,'Tedy vstav Joáb, odšel do Gessur, a přivedl Absolona do Jeruzaléma.'),
(1554572,54,10,14,24,'I řekl král: Nechť se navrátí do domu svého, ale tváři mé ať nevidí. A tak navrátil se Absolon do domu svého, ale tváři královské neviděl.'),
(1554573,54,10,14,25,'Nebylo pak žádného muže tak krásného jako Absolon ve všem Izraeli, aby takovou chválu měl. Od paty nohy jeho až do vrchu hlavy jeho nebylo na něm poškvrny.'),
(1554574,54,10,14,26,'A když střihával vlasy hlavy své, (měl pak obyčej každého roku je střihati, protože jej obtěžovaly, i střihával je), tedy vážíval vlasy hlavy své, a bývalo jich dvě stě lotů váhy obecné.'),
(1554575,54,10,14,27,'Zrodili se pak Absolonovi tři synové a jedna dcera, jejíž jméno bylo Támar, kteráž byla žena vzezření krásného.'),
(1554576,54,10,14,28,'I byl Absolon v Jeruzalémě dvě létě, a tváři královské neviděl.'),
(1554577,54,10,14,29,'A protož poslal Absolon k Joábovi, chtěje ho poslati k králi. Kterýžto nechtěl přijíti k němu. I poslal ještě podruhé, a nechtěl přijíti.'),
(1554578,54,10,14,30,'Tedy řekl služebníkům svým: Shlédněte dědinu Joábovu vedlé pole mého, kdežto má ječmen; jděte a spalte jej. I zapálili služebníci Absolonovi dědinu tu.'),
(1554579,54,10,14,31,'A vstav Joáb, přišel k Absolonovi do domu jeho, a řekl jemu: Proč jsou služebníci tvoji zapálili dědinu mou?'),
(1554580,54,10,14,32,'Odpověděl Absolon Joábovi: Aj, poslal jsem k tobě, řka: Přiď sem, a pošli tě k králi, abys řekl jemu: I proč jsem přišel z Gessur? Lépe mi bylo ještě tam zůstati. Protož nyní nechať uzřím tvář královu. Pakliť jest na mně nepravost, nechť mne rozkáže zabiti.'),
(1554581,54,10,14,33,'Tedy přišel Joáb k králi a oznámil to jemu. I povolal Absolona. Kterýž přišed k králi, poklonil se na tvář svou až k zemi před ním. I políbil král Absolona.'),
(1554582,54,10,15,1,'I stalo se potom, že sobě najednal Absolon vozů a koní a padesáte mužů, kteříž by běhali před ním.'),
(1554583,54,10,15,2,'A vstávaje ráno Absolon, stával u cesty při bráně, a každého muže, kterýž, maje při, šel k králi pro rozsouzení, povolával Absolon, říkaje: Z kterého jsi ty města? A když mu odpověděl: Z toho a z toho pokolení Izraelského jest služebník tvůj,'),
(1554584,54,10,15,3,'Řekl jemu Absolon: Hle, tvá pře výborná jest a pravá, ale kdo by tě vyslyšel, není žádného u krále.'),
(1554585,54,10,15,4,'Říkal také Absolon: Ó kdyby mne kdo ustanovil soudcím v zemi této, aby ke mně chodil každý, kdož by měl nesnáz a při, a dopomáhal bych jemu k spravedlnosti.'),
(1554586,54,10,15,5,'Ano i když někdo přicházel, klaněje se jemu, vztáhl ruku svou, a uchopě ho, políbil jej.'),
(1554587,54,10,15,6,'Činíval pak Absolon tím způsobem všemu Izraelovi, kterýž pro rozsudek přicházel k králi; a tak obracel k sobě Absolon srdce mužů Izraelských.'),
(1554588,54,10,15,7,'Stalo se také po čtyřidcíti letech, že řekl Absolon k králi: Nechť jdu, prosím, a splním slib svůj v Hebronu, který jsem učinil Hospodinu.'),
(1554589,54,10,15,8,'Nebo byl učinil slib služebník tvůj, když jsem bydlil v Gessur v Syrii, řka: Jestliže mne zase kdy přivede Hospodin do Jeruzaléma, tedy službu jemu učiním.'),
(1554590,54,10,15,9,'Jemuž řekl král: Jdi u pokoji. Kterýžto vstav, odšel do Hebronu.'),
(1554591,54,10,15,10,'I poslal Absolon špehéře do všech pokolení Izraelských, aby řekli: Když uslyšíte zvuk trouby, rcete: Kralujeť Absolon v Hebronu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554592,54,10,15,11,'S Absolonem pak šlo dvě stě mužů z Jeruzaléma pozvaných, ale šli v upřímnosti své, aniž co o tom věděli.'),
(1554593,54,10,15,12,'Poslal také Absolon pro Achitofele Gilonského, rádce Davidova, aby přišel z města svého Gilo, když měl obětovati oběti. I stalo se spiknutí veliké, nebo lidu ustavičně přibývalo Absolonovi.'),
(1554594,54,10,15,13,'V tom přišel posel k Davidovi, řka: Srdce Izraelských obrátilo se po Absolonovi.'),
(1554595,54,10,15,14,'Tedy řekl David všechněm služebníkům svým, kteříž byli s ním v Jeruzalémě: Vstaňte a utecme, sic jinak nemohli bychom ujíti tváři Absolonovy. Pospěšte, ať odejdeme, aby se neuspíšil, a nezastihl nás, a neuvalil na nás zlého a nepohubil města ostrostí meče.'),
(1554596,54,10,15,15,'I řekli služebníci královští králi: Což by koli zvolil pán náš král, teď jsme služebníci tvoji.'),
(1554597,54,10,15,16,'A tak vyšel král se vší svou čeledí pěšky; toliko zanechal král desíti ženin, aby doma hlídaly.'),
(1554598,54,10,15,17,'Když pak vyšel král a všecken lid pěšky, postavili se na jednom místě zdaleka.'),
(1554599,54,10,15,18,'I šli všickni služebníci při něm; též všickni Cheretejští a všickni Peletejští, i všickni Gittejští, šest set mužů, kteříž přišli pěšky z Gát, šli před králem.'),
(1554600,54,10,15,19,'Tedy řekl král k Ittai Gittejskému: Proč ty také jdeš s námi? Navrať se a zůstaň při králi; nebo cizozemec jsi, kterýž se tudíž zase odbéřeš k místu svému.'),
(1554601,54,10,15,20,'Nedávnos přišel, a již bych dnes tebou pohnouti měl, abys s námi chodil? Jáť zajisté půjdu, kdež mi se nahodí. Navratiž se a zprovoď zase bratří své, a budiž s tebou milosrdenství a pravda.'),
(1554602,54,10,15,21,'Odpovídaje pak Ittai králi, řekl: Živť jest Hospodin a živť jest pán můj král, že na kterémkoli místě bude pán můj král, buď mrtev aneb živ, tuť bude i služebník tvůj.'),
(1554603,54,10,15,22,'I řekl David k Ittai: Podiž a přejdi. I přešel Ittai Gittejský a všickni muži jeho, i všecky dítky, kteréž byly s ním.'),
(1554604,54,10,15,23,'Tedy plakala všecka země hlasem velikým, i všecken lid přecházející. A tak přešel král potok Cedron; i všecken lid přešel proti cestě vedoucí na poušť.'),
(1554605,54,10,15,24,'A aj, byl také Sádoch a všickni Levítové s ním, nesouce truhlu smlouvy Boží; i postavili truhlu Boží. Šel pak i Abiatar, a stál, dokudž všecken ten lid nepřešel z města.'),
(1554606,54,10,15,25,'I řekl král Sádochovi: Dones zase truhlu Boží do města. Jestližeť najdu milost před očima Hospodinovýma, přivedeť mne zase, a ukážeť mi ji i příbytek svůj.'),
(1554607,54,10,15,26,'Pakliť řekne takto: Nelíbíš mi se, aj, teď jsem, nechť mi učiní, což se mu dobrého vidí.'),
(1554608,54,10,15,27,'Řekl ještě král Sádochovi knězi: Zdaliž ty nejsi vidoucí? Navratiž se do města u pokoji, Achimaas pak syn tvůj, a Jonata syn Abiatarův, dva synové vaši, budou s vámi.'),
(1554609,54,10,15,28,'Hle, já pobudu na rovinách pouště, dokudž nepřijde poselství od vás, skrze něž by mi oznámeno bylo.'),
(1554610,54,10,15,29,'A tak donesl zase Sádoch a Abiatar truhlu Boží do Jeruzaléma, a zůstali tam.'),
(1554611,54,10,15,30,'Ale David šel vzhůru k vrchu hory Olivetské, vstupuje a pláče, maje přikrytou hlavu svou; šel pak bos. Všecken také lid, kterýž byl s ním, přikryl jeden každý hlavu svou, a šli, ustavičně plačíce.'),
(1554612,54,10,15,31,'Tedy povědíno Davidovi, že Achitofel jest s těmi, kteříž se spikli s Absolonem. I řekl David: Zruš, prosím, ó Hospodine, radu Achitofelovu.'),
(1554613,54,10,15,32,'I stalo se, jakž přišel David na vrch hory, aby se tam pomodlil Bohu, aj, potkal se s ním Chusai Architský, maje roztržené roucho své a hlavu prstí posypanou.'),
(1554614,54,10,15,33,'I řekl jemu David: Půjdeš-li se mnou, budeš mi břemenem.'),
(1554615,54,10,15,34,'Pakli se navrátíš do města a díš k Absolonovi: Služebníkem tvým budu, ó králi, služebníkem zajisté otce tvého byl jsem již zdávna, již pak budu služebníkem tvým, tedy zrušíš radu Achitofelovu.'),
(1554616,54,10,15,35,'Však tam budou s tebou Sádoch a Abiatar kněží. Protož cožkoli uslyšíš z domu králova, oznámíš Sádochovi a Abaitarovi kněžím.'),
(1554617,54,10,15,36,'Aj, tam s nimi jsou dva synové jejich, Achimaas Sádochův a Jonata Abiatarův, po nichž mi vzkážete, což byste koli uslyšeli.'),
(1554618,54,10,15,37,'Šel tedy Chusai, přítel Davidův do města; Absolon také přijel do Jeruzaléma.'),
(1554619,54,10,16,1,'A když David sešel maličko s vrchu, aj Síba služebník Mifibozetův vyšel proti němu se dvěma osly osedlanými, na nichž nesl dvě stě chlebů, a sto hroznů suchých, a sto hrud fíků, a nádobu vína.'),
(1554620,54,10,16,2,'I řekl král Síbovi: K čemu jsou tyto věci? Odpověděl Síba: Oslové pro čeled královskou k jízdě, chléb pak a fíky, aby jedli služebníci, a víno, aby se napil, kdož by ustal na poušti.'),
(1554621,54,10,16,3,'Opět král řekl: Kdež jest pak syn pána tvého? Odpověděl Síba králi: Aj, zůstal v Jeruzalémě, nebo řekl: Dnes navrátí mi dům Izraelský království otce mého.'),
(1554622,54,10,16,4,'Řekl ještě král Síbovi: Aj, tvéť jsou všecky věci, kteréž má Mifibozet. Jemuž řekl Síba s poklonou: Nechať vždycky tak nalézám milost před očima tvýma, pane můj králi.'),
(1554623,54,10,16,5,'Tedy bral se král David do Bahurim, a aj, vyšel odtud muž z čeledi domu Saulova, jehož jméno bylo Semei, syn Gerův, kterýžto vždy jda, zlořečil.'),
(1554624,54,10,16,6,'Ano i kamením házel na Davida, a na všecky služebníky krále Davida, ačkoli všecken lid a všickni udatní byli po pravici jeho i po levici jeho.'),
(1554625,54,10,16,7,'A takto mluvil Semei, když mu zlořečil: Vyjdi, vyjdi, vražedlníče a nešlechetníče.'),
(1554626,54,10,16,8,'Obrátilť jest na tebe Hospodin všelikou krev domu Saulova, na jehož jsi místě kraloval, a dal Hospodin království v ruku Absolona syna tvého. A aj, již se vidíš v svém neštěstí, nebo jsi vražedlník.'),
(1554627,54,10,16,9,'I řekl Abizai syn Sarvie králi: I proč zlořečí tento mrtvý pes pánu mému králi? Nechť jdu medle a setnu mu hlavu.'),
(1554628,54,10,16,10,'Ale král řekl: Co vám do toho, synové Sarvie, že zlořečí? Poněvadž Hospodin jemu rozkázal: Zlořeč Davidovi, i kdož by směl říci: Proč tak činíš?'),
(1554629,54,10,16,11,'Řekl ještě David k Abizai i ke všechněm služebníkům svým: Aj, syn můj, kterýž pošel z života mého, hledá bezživotí mého, čím více nyní tento syn Jemini? Nechte ho, ať zlořečí, nebo jemu rozkázal Hospodin.'),
(1554630,54,10,16,12,'Snad popatří Hospodin na ssoužení mé, a odplatí mi Hospodin dobrým za zlořečenství jeho dnes.'),
(1554631,54,10,16,13,'A tak šel David a muži jeho cestou. Semei také šel po stráni hory naproti němu, a jda, zlořečil a házel kamením proti němu a zmítal prachem.'),
(1554632,54,10,16,14,'I přišel král a všecken lid, kterýž byl s ním, ustalý, a odpočinul tu.'),
(1554633,54,10,16,15,'Absolon pak i všecken lid Izraelský přišli do Jeruzaléma, a Achitofel s ním.'),
(1554634,54,10,16,16,'A když přišel Chusai Architský, přítel Davidův k Absolonovi, řekl Chusai Absolonovi: Živ buď král, živ buď král.'),
(1554635,54,10,16,17,'Tedy řekl Absolon k Chusai: Toliž jest vděčnost tvá k příteli tvému? Pročež jsi nešel s přítelem svým?'),
(1554636,54,10,16,18,'Odpověděl Chusai Absolonovi: Nikoli, ale kohož vyvolil Hospodin a lid tento i všickni muži Izraelští, toho budu a s tím zůstanu.'),
(1554637,54,10,16,19,'Přesto komuž bych já sloužiti měl? Zdali ne synu jeho? Jakož jsem sloužil otci tvému, tak sloužiti budu tobě.'),
(1554638,54,10,16,20,'Řekl pak Absolon Achitofelovi: Raďtež, co máme činiti?'),
(1554639,54,10,16,21,'Odpověděl Achitofel Absolonovi: Vejdi k ženinám otce svého, kterýchž zanechal, aby hlídaly doma. I uslyší všecken Izrael, žes se zošklivil otci svému, a zsilí se ruce všech, kteříž jsou s tebou.'),
(1554640,54,10,16,22,'A protož rozbili Absolonovi stan na paláci. I všel Absolon k ženinám otce svého před očima všeho Izraele.'),
(1554641,54,10,16,23,'Rada pak Achitofelova, kterouž dával toho času, byla, jako by se kdo doptával na řeč Boží. Taková byla každá rada Achitofelova, jakož u Davida tak u Absolona.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554642,54,10,17,1,'Řekl ještě Achitofel Absolonovi: Nechť medle vyberu dvanácte tisíc mužů, abych vstana, honil Davida noci této.'),
(1554643,54,10,17,2,'A dostihna ho, dokudž jest ustalý a zemdlené má ruce, předěsím jej, a uteče všecken lid, kterýž jest s ním, i zamorduji krále samého.'),
(1554644,54,10,17,3,'A tak obrátím všecken lid k tobě; nebo jako bych je všecky obrátil, když zhyne ten muž, kteréhož ty hledáš. O lid ty se nic nestarej.'),
(1554645,54,10,17,4,'I líbila se ta řeč Absolonovi i všechněm starším Izraelským.'),
(1554646,54,10,17,5,'A však řekl Absolon: Zavolej sem hned Chusai Architského, abychom slyšeli, co i on mluviti bude.'),
(1554647,54,10,17,6,'Když pak přišel Chusai k Absolonovi, mluvil k němu Absolon, řka: Takto mluvil Achitofel. Máme-li učiniti vedlé řeči jeho, čili nic? Pověz ty.'),
(1554648,54,10,17,7,'Tedy řekl Chusai Absolonovi: Neníť dobrá rada, kterouž dal Achitofel nyní.'),
(1554649,54,10,17,8,'Dále mluvil Chusai: Ty víš o otci svém i mužích jeho, že jsou udatní, k tomu zjitření na mysli, jako nedvědice osiřelá v poli. Nadto otec tvůj jest muž válečný, kterýž nebude nocovati s lidem.'),
(1554650,54,10,17,9,'Nýbrž nyní spíše v záloze stojí v nějaké jeskyni, aneb v některém jiném místě. I stalo by se, jestliže by kteří padli z těch tvých při začátku, že každý, kdož by o tom uslyšel, řekl by: Stala se porážka v lidu, kterýž postoupil po Absolonovi.'),
(1554651,54,10,17,10,'A tak by i silných reků srdce, kteréž jest jako srdce lva, škodlivě osláblo; nebo ví všecken Izrael, že jest zmužilý otec tvůj, a silní ti, kteříž jsou s ním.'),
(1554652,54,10,17,11,'Ale radím, abys, shromáždě k sobě všecken Izrael od Dan až do Bersabé, kterýž v množství jest jako písek při moři, ty sám životně vytáhl k boji.'),
(1554653,54,10,17,12,'A tak potáhneme proti němu, na kterém by koli místě nalezen býti mohl, a připadneme na něj, jako padá rosa na zemi; i nepozůstaneť z něho, totiž ze všech mužů, kteříž jsou při něm, ani jednoho.'),
(1554654,54,10,17,13,'Jestliže by se pak shrnul do města, snesou všecken lid Izraelský k tomu městu provazy, a vtrhneme je až do potoka, tak aby tam ani kaménka nebylo lze najíti.'),
(1554655,54,10,17,14,'I řekl Absolon a všickni muži Izraelští: Lepšíť jest rada Chusai Architského, než rada Achitofelova. Hospodin zajisté to způsobil, aby zrušena byla rada Achitofelova, kteráž sic dobrá byla, aby tak uvedl Hospodin na Absolona zlé věci.'),
(1554656,54,10,17,15,'Oznámil pak to Chusai Sádochovi a Abiatarovi kněžím: Tak a tak radil Achitofel Absolonovi a starším Izraelským, ale já takto a takto jsem radil.'),
(1554657,54,10,17,16,'Nyní tedy pošlete rychle a oznamte Davidovi, řkouce: Nezůstavej přes noc na rovinách pouště, ale přeprav se bez meškání, aby snad nebyl sehlcen král i všecken lid, kterýž jest s ním.'),
(1554658,54,10,17,17,'Jonata pak a Achimaas stáli u studnice Rogel. I šla tam děvečka a pověděla jim, aby oni jdouce, oznámili to králi Davidovi; nebo nesměli se ukázati aneb vjíti do města.'),
(1554659,54,10,17,18,'A však uzřel je služebník, a oznámil Absolonovi. Pročež odšedše oba rychle, vešli do domu muže v Bahurim, kterýž měl studnici na dvoře svém. I spustili se do ní.'),
(1554660,54,10,17,19,'A žena vzavši plachtu, rozestřela ji na vrch studnice, a nasypala na ni krup. A tak nebyla ta věc spatřína.'),
(1554661,54,10,17,20,'Nebo když přišli služebníci Absolonovi k ženě do domu a řekli: Kde jest Achimaas a Jonata? odpověděla jim žena: Přešliť jsou ten potok. Hledavše tedy a nic nenalezše, navrátili se do Jeruzaléma.'),
(1554662,54,10,17,21,'A když oni odešli, tito vystoupivše z studnice, šli a oznámili králi Davidovi a řekli jemu: Vstaňte a přepravte se rychle přes vodu, nebo toto radil proti vám Achitofel.'),
(1554663,54,10,17,22,'Protož vstav David a všecken lid, kterýž byl s ním, přepravili se přes Jordán, prvé než se rozednilo; a nezůstal ani jeden, ješto by se nepřepravil přes Jordán.'),
(1554664,54,10,17,23,'Tedy Achitofel vida, že se nestalo vedlé rady jeho, osedlal osla, a vstav, odjel do domu svého, do města svého. A učiniv pořízení v čeledi své, oběsil se a umřel; i pochován jest v hrobě otce svého.'),
(1554665,54,10,17,24,'David pak byl již přišel do Mahanaim, když se Absolon přepravil přes Jordán, on i všecken lid Izraelský s ním.'),
(1554666,54,10,17,25,'A tu ustanovil Absolon Amazu místo Joába nad vojskem. (Byl pak Amaza syn muže, jehož jméno bylo Jetra Izraelský, kterýž všel k Abigail dceři Náchas, sestře Sarvie matky Joábovy.)'),
(1554667,54,10,17,26,'I položil se Izrael a Absolon v zemi Galád.'),
(1554668,54,10,17,27,'Stalo se pak, když přišel David do Mahanaim, že Sobi syn Náchas z Rabbat synů Ammon, a Machir syn Amielův z Lodebar, a Barzillai Galádský z Rogelim,'),
(1554669,54,10,17,28,'Lůže, číše a nádoby hliněné, též pšenice, ječmene, mouky, krup, bobu, šocovice a pražmy,'),
(1554670,54,10,17,29,'Ano i medu, másla a ovcí i syrů kravských přinesli Davidovi a lidu, kterýž s ním byl, aby jedli. Nebo řekli: Lid ten jest hladovitý a ustalý, i žíznivý na té poušti.'),
(1554671,54,10,18,1,'Sečtl pak David lid, kterýž měl s sebou, a ustanovil nad nimi hejtmany a setníky.'),
(1554672,54,10,18,2,'I uvedl David třetinu lidu v správu Joábovu, a třetinu v správu Abizai syna Sarvie, bratra Joábova, a třetinu v správu Ittai Gittejského. A řekl král lidu: I jáť také potáhnu s vámi.'),
(1554673,54,10,18,3,'Ale lid řekl: Nikoli nepotáhneš; nebo jestliže bychom i utíkali, nebudouť na to velmi dbáti, aniž, by nás i polovici zbili, budou toho velmi vážiti. Ty sám zajisté jsi jako z nás deset tisíců, protož lépe bude, abys nám byl v městě ku pomoci.'),
(1554674,54,10,18,4,'I řekl jim král: Což se vám za dobré vidí, učiním. Tedy stál král u brány, a všecken lid vycházel po stu a po tisíci.'),
(1554675,54,10,18,5,'Přikázal pak král Joábovi a Abizai a Ittai, řka: Zacházejtež mi pěkně s synem Absolonem. A všecken lid slyšel, když přikazoval král všechněm hejtmanům o Absolonovi.'),
(1554676,54,10,18,6,'A tak vytáhl lid do pole proti lidu Izraelskému, a byla bitva v lese Efraim.'),
(1554677,54,10,18,7,'I poražen jest tu lid Izraelský od služebníků Davidových, a stala se tu porážka veliká v ten den až do dvadceti tisíců.'),
(1554678,54,10,18,8,'Nebo když ta bitva rozšířila se po vší krajině, více pohubil lidu les, nežli jich požral meč toho dne.'),
(1554679,54,10,18,9,'Potkal se pak Absolon s služebníky Davidovými. Kterýžto Absolon jel na mezku, (i podšel mezek pod hustý dub veliký), a uvázl za hlavu v stromu tom, tak že visel mezi nebem a zemí. Ale mezek, kterýž pod ním byl, odběhl pryč.'),
(1554680,54,10,18,10,'To uzřev jeden, oznámil Joábovi, řka: Hle, viděl jsem Absolona, an visí na dubě.'),
(1554681,54,10,18,11,'I řekl Joáb muži, kterýž mu to oznámil: Aj, viděls. Pročež jsi ho tam nesrazil na zem? A já bylť bych povinen dáti deset lotů stříbra a pás rytířský jeden.'),
(1554682,54,10,18,12,'Odpověděl muž ten Joábovi: A já, bych i odečtených měl na ruce své tisíc lotů stříbra, nevztáhl bych ruky své na syna králova; nebo jsme slyšeli, kterak přikazoval král tobě a Abizai a Ittai, řka: Šetřte všickni syna mého Absolona;'),
(1554683,54,10,18,13,'Leč bych se dopustiti chtěl sám proti duši své nepravosti. Ale nebýváť nic tajno před králem, a ty bys sám proti mně stál.'),
(1554684,54,10,18,14,'I řekl Joáb: Nebuduť se tu meškati s tebou. Protož vzav tři kopí do ruky své, vrazil je do Absolona, an ještě živ byl na dubě.'),
(1554685,54,10,18,15,'A obskočivše Absolona deset služebníků, oděnců Joábových, bili jej a zabili.'),
(1554686,54,10,18,16,'V tom zatroubil Joáb v troubu. I vrátil se lid od honění Izraele; nebo zdržel Joáb lid.'),
(1554687,54,10,18,17,'A vzavše Absolona, uvrhli jej v tom lese do jámy veliké, a nametali na něj hromadu kamení velmi velikou. Ale všecken Izrael zutíkali jeden každý do stanů svých.'),
(1554688,54,10,18,18,'( Absolon pak vzal byl a vyzdvihl sobě za života svého sloup v údolí královském; nebo byl řekl: Nemám syna, aby zůstala pamět jména mého. Protož nazval ten sloup jménem svým, kterýž slove místo Absolonovo až do dnešního dne.)'),
(1554689,54,10,18,19,'Tedy Achimaas syn Sádochův řekl: Medle, nechť běžím, abych zvěstoval králi, že ho vysvobodil Hospodin z ruky nepřátel jeho.'),
(1554690,54,10,18,20,'I řekl jemu Joáb: Nebyl bys dnes dobrým poslem, ale oznámíš to jiného dne; dnes však neoznamuj, proto že syn králův umřel.'),
(1554691,54,10,18,21,'Potom řekl Joáb k Chuzi: Jdiž, zvěstuj králi, co jsi viděl. A pokloniv se Chuzi Joábovi, běžel.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554692,54,10,18,22,'Mluvil pak ještě Achimaas syn Sádochův, a řekl Joábovi: Buď, jak buď, medle, nechť já také běžím za Chuzi. Odpověděl Joáb: Proč bys ty běžel, synu můj, když nemáš, co bys dobrého zvěstoval?'),
(1554693,54,10,18,23,'I řekl: Buď, jak buď, poběhnu. Odpověděl mu: Běž. A tak běžel Achimaas cestou přímější a předběhl Chuzi.'),
(1554694,54,10,18,24,'David pak seděl mezi dvěma branami. I vyšel strážný na vrch brány na zed, kterýž pozdvih očí svých, uzřel, a hle, muž běžel sám.'),
(1554695,54,10,18,25,'Tedy volaje strážný, oznámil králi. I řekl král: Jest-liť sám, dobré poselství nese. A když ten šel předce a přibližoval se,'),
(1554696,54,10,18,26,'Uzřel ještě strážný muže druhého běžícího. I zavolal strážný na branného a řekl: Hle, opět muž běží sám.Tedy řekl král: I tenť v poselství běží.'),
(1554697,54,10,18,27,'Řekl ještě strážný: Vidím běh prvního, jako běh Achimaasa syna Sádochova. I řekl král: Dobrýtě to muž, protož s dobrým poselstvím jde.'),
(1554698,54,10,18,28,'Tedy volaje Achimaas, řekl králi: Pokoj tobě. A pokloniv se králi tváří svou k zemi, řekl: Požehnaný Hospodin Bůh tvůj, kterýž podmanil muže ty, kteříž pozdvihli rukou svých proti pánu mému králi.'),
(1554699,54,10,18,29,'I řekl král: Dobře-li se má syn můj Absolon? Odpověděl Achimaas: Viděl jsem hluk veliký, když posílal služebníka králova Joáb, a mne služebníka tvého, ale nevím nic, co bylo.'),
(1554700,54,10,18,30,'Jemuž řekl král: Odstup a stůj tamto. I odstoupil a stál.'),
(1554701,54,10,18,31,'A v tom Chuzi přišed, řekl: Zvěstuje se pánu mému králi, že vysvobodil tě dnes Hospodin z ruky všech povstávajících proti tobě.'),
(1554702,54,10,18,32,'Ale král řekl k Chuzi: Jest-liž živ syn můj Absolon? Odpověděl Chuzi: Nechť jsou tak, jako syn králův, nepřátelé pána mého krále, i všickni, kteříž povstávají proti tobě ke zlému.'),
(1554703,54,10,18,33,'I zarmoutil se král, a vstoupiv do horního pokoje na bráně, plakal a jda, mluvil takto: Synu můj Absolone, synu můj, synu můj Absolone! Ó kdybych byl umřel za tebe, Absolone synu můj, synu můj!'),
(1554704,54,10,19,1,'I oznámeno jest Joábovi: Aj, král pláče a naříká pro Absolona.'),
(1554705,54,10,19,2,'Pročež obrátilo se to vysvobození toho dne v kvílení všemu lidu; nebo slyšel lid v ten den, že bylo praveno: Zámutek má král pro syna svého.'),
(1554706,54,10,19,3,'A tak kradl se lid toho dne, vcházeje do města, jako se krade lid, když se stydí, utíkaje z boje.'),
(1554707,54,10,19,4,'Král pak zakryl tvář svou, a křičel král hlasem velikým: Synu můj Absolone, Absolone synu můj, synu můj!'),
(1554708,54,10,19,5,'Tedy všed Joáb k králi do domu, řekl: Zahanbil jsi dnes tváři všech služebníků svých, kteříž vysvobodili život tvůj dnes, a život synů tvých i dcer tvých, a život žen tvých i život ženin tvých,'),
(1554709,54,10,19,6,'Miluje ty, kteříž tě mají v nenávisti, a v nenávisti maje ty, kteříž tě milují; nebos dokázal dnes, že sobě nevážíš hejtmanů a služebníků. Shledalť jsem to zajisté dnes, že kdyby byl Absolon živ zůstal, bychom pak všickni dnes byli pobiti, tedy dobře by se tobě to líbilo.'),
(1554710,54,10,19,7,'Protož nyní vstana, vyjdi, a mluv ochotně k služebníkům svým; nebo přisahámť skrze Hospodina, jestliže nevyjdeš, žeť nezůstane žádný s tebou této noci, a toť bude tobě horší, nežli všecky zlé věci, kteréž na tebe přišly od mladosti tvé až dosavad.'),
(1554711,54,10,19,8,'A tak vstav král, posadil se v bráně. I povědíno bylo všemu lidu těmito slovy: Aj, král sedí v bráně. I přišel všecken lid před oblíčej krále, ale lid Izraelský byl zutíkal jeden každý do svých stanů.'),
(1554712,54,10,19,9,'Tedy všecken lid hádal se vespolek ve všech pokoleních Izraelských, a pravili: Král vytrhl nás z ruky nepřátel našich, a tentýž vytrhl nás z ruky Filistinských, a teď nyní utekl z země před Absolonem.'),
(1554713,54,10,19,10,'Absolon pak, kteréhož jsme pomazali sobě, zahynul v boji. Nyní tedy, proč zanedbáváte přivésti zase krále?'),
(1554714,54,10,19,11,'Protož král David poslal k Sádochovi a Abiatarovi kněžím, s těmito slovy: Mluvte k starším Judským, řkouce: Proč máte býti poslední v uvedení zase krále do domu jeho? (Nebo řeč všeho lidu Izraelského donesla se krále o uvedení jeho do domu jeho.)'),
(1554715,54,10,19,12,'Bratří moji jste, kost má a tělo mé jste; proč tedy máte býti poslední v uvedení zase krále?'),
(1554716,54,10,19,13,'A Amazovi také rcete: Zdaliž ty nejsi kost má a tělo mé? Toto ať mi učiní Bůh a toto přidá, jestliže nebudeš hejtmanem vojska přede mnou po všecky dny na místo Joába.'),
(1554717,54,10,19,14,'I naklonil srdce všech mužů Judských, jako muže jednoho, aby poslali k králi, řkouce: Navratiž se ty i všickni služebníci tvoji.'),
(1554718,54,10,19,15,'Tedy navrátil se král, a přišel až k Jordánu. Lid pak Judský byl přišel do Galgala, aby se bral vstříc králi, a převedl jej přes Jordán.'),
(1554719,54,10,19,16,'Pospíšil také Semei syn Gery, syna Jemini, kterýž byl z Bahurim, a vyšel s lidem Judským vstříc králi Davidovi.'),
(1554720,54,10,19,17,'A tisíc mužů bylo s ním z Beniamin. Síba také služebník domu Saulova, s patnácti syny svými, a dvadceti služebníků jeho s ním, přepravili se přes Jordán před krále.'),
(1554721,54,10,19,18,'I přeplavili lodí, aby převezli čeled královskou a učinili, což by se jemu líbilo. Semei pak syn Gerův padl před králem, když se přepraviti měl přes Jordán.'),
(1554722,54,10,19,19,'A řekl králi: Nepočítej mi pán můj nepravosti, a nezpomínej, co neprávě učinil služebník tvůj toho dne, když vyšel pán můj král z Jeruzaléma, aby to měl skládati král v srdci svém.'),
(1554723,54,10,19,20,'Neboť zná služebník tvůj, že zhřešil, a aj, přišel jsem dnes prvé, než kdo ze vší čeledi Jozefovy, abych vyšel vstříc pánu svému králi.'),
(1554724,54,10,19,21,'I odpověděl Abizai syn Sarvie a řekl: A což nebude zabit Semei, proto že zlořečil pomazanému Hospodinovu?'),
(1554725,54,10,19,22,'Ale David řekl: Co vám do toho, synové Sarvie, že jste mi dnes odporní? Dnes-liž má zabit býti někdo v Izraeli? Nebo zdaliž nevím, že dnes jsem králem nad Izraelem.'),
(1554726,54,10,19,23,'Tedy řekl král k Semei: Neumřeš. I přisáhl mu král.'),
(1554727,54,10,19,24,'Mifibozet také vnuk Saulův vyjel vstříc králi. (Neošetřoval pak byl noh svých, ani brady nespravoval, ani šatů svých nepral od toho dne, jakž byl odšel král, až do dne, když se navrátil v pokoji.)'),
(1554728,54,10,19,25,'A když přišel do Jeruzaléma, vyšel vstříc králi. I řekl jemu král: Proč jsi neodšel se mnou, Mifibozete?'),
(1554729,54,10,19,26,'Kterýž odpověděl: Pane můj králi, služebník můj oklamal mne. Řekltě byl zajisté služebník tvůj: Osedlám sobě osla, abych vsedna na něj, bral se s králem, proto že jest kulhavý služebník tvůj.'),
(1554730,54,10,19,27,'I osočil služebníka tvého u pána mého krále, ale pán můj král jest jako anděl Boží, učiniž tedy, cožť se dobrého vidí.'),
(1554731,54,10,19,28,'Nebo všickni z domu otce mého byli jsme hodni smrti před pánem mým králem, a však jsi zasadil služebníka svého mezi ty, kteříž jedí chléb stolu tvého. K čemuž bych více právo měl, a oč se více na krále domlouval?'),
(1554732,54,10,19,29,'Jemuž řekl král: Proč šíříš řeč svou? Vyřklť jsem. Ty a Síba rozdělte se statkem.'),
(1554733,54,10,19,30,'Ještě řekl Mifibozet králi: Třebas nechť všecko vezme, když se jen navrátil pán můj král v pokoji do domu svého.'),
(1554734,54,10,19,31,'Ano i Barzillai Galádský vyšel z Rogelim, a přepravil se s králem přes Jordán, aby ho zprovodil za Jordán.'),
(1554735,54,10,19,32,'Byl pak Barzillai velmi starý, maje osmdesáte let, kterýž opatroval krále stravou, když obýval v Mahanaim; nebo byl člověk bohatý velmi.'),
(1554736,54,10,19,33,'I řekl král k Barzillai: Poď se mnou, a chovati tě budu při sobě v Jeruzalémě.'),
(1554737,54,10,19,34,'Ale Barzillai odpověděl králi: Jacíž jsou dnové věku mého, abych šel s králem do Jeruzaléma?'),
(1554738,54,10,19,35,'V osmdesáti letech jsem dnes. Zdaliž mohu rozeznati mezi dobrým a zlým? Zdaliž okušením rozezná služebník tvůj, co bych jedl a co bych pil? Zdaliž poslouchati mohu již hlasu zpěváků a zpěvakyní? Proč by tedy služebník tvůj déle býti měl břemenem pánu svému králi?'),
(1554739,54,10,19,36,'Maličko ještě půjde služebník tvůj za Jordán s králem; nebo proč by mi se takovou odplatou král odplacovati měl?'),
(1554740,54,10,19,37,'Nechť se navrátí, prosím, služebník tvůj, ať umru v městě svém, kdež jest hrob otce mého a matky mé. Aj, služebník tvůj Chimham půjde se pánem mým králem, jemuž učiníš, cožť se dobrého viděti bude.'),
(1554741,54,10,19,38,'I řekl král: Dobře, nechť jde se mnou Chimham, a učiním jemu, což se tobě za dobré viděti bude; nadto čehožkoli požádáš ode mne, toť učiním.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554742,54,10,19,39,'A když se přepravil všecken lid přes Jordán, král také přepravil se. I políbil král Barzillai a požehnal ho, kterýžto navrátil se na místo své.'),
(1554743,54,10,19,40,'A tak bral se král do Galgala a Chimham s ním; všecken také lid Judský provázeli krále, též i polovice lidu Izraelského.'),
(1554744,54,10,19,41,'A aj, všickni muži Izraelští přišedše k králi, řekli jemu: Proč jsou tě ukradli bratří naši, muži Juda, a převedli krále a čeled jeho přes Jordán, i všecky muže Davidovy s ním?'),
(1554745,54,10,19,42,'I odpověděli všickni muži Judští mužům Izraelským: Proto že král jest příbuzný náš. A proč se hněváte o to? Zdaliž nás za to král pokrmy opatroval? Zdaliž nám jaké dary dal?'),
(1554746,54,10,19,43,'Odpovídajíce pak muži Izraelští mužům Judským, řekli: Deset dílů máme v králi, a protož i v Davidovi máme více nežli vy. Pročež tedy málo jste nás sobě vážili? Zdaliž jsme my prvé o to nemluvili, abychom zase přivedli krále svého? Ale tvrdší byla řeč mužů Judských nad řeč mužů Izraelských.'),
(1554747,54,10,20,1,'Přišel pak tu náhodou člověk nešlechetný, jehož jméno bylo Seba, syn Bichri, muž Jemini. Ten zatroubil v troubu a řekl: Nemámeť my dílu v Davidovi, ani dědictví v synu Izai;obrať se jeden každý k stanům svým, ó Izraeli.'),
(1554748,54,10,20,2,'A tak všickni muži Izraelští odstoupili od Davida za Sebou synem Bichri, ale muži Judští přídrželi se krále svého od Jordánu až do Jeruzaléma.'),
(1554749,54,10,20,3,'David pak přišel do domu svého do Jeruzaléma. A vzal král deset ženin, kterýchž byl nechal, aby hlídaly doma, a dal je pod stráž, a choval je, ale nevcházel k nim. A zůstaly zavřené až do dne smrti své v vdovství.'),
(1554750,54,10,20,4,'Potom řekl král Amazovi: Svolej mi muže Judské do třetího dne, ty také se tu postav.'),
(1554751,54,10,20,5,'A tak odšel Amaza, aby svolal lid Judský, ale prodlil mimo určitý čas, kterýž mu byl uložil.'),
(1554752,54,10,20,6,'Protož řekl David Abizai: Již nyní hůře nám činiti bude Seba syn Bichri, nežli Absolon. Vezmi služebníky pána svého, a hoň jej, aby sobě nenalezl měst hrazených, a tak ušel by nám s očí.'),
(1554753,54,10,20,7,'Tedy táhli za ním muži Joábovi, i Cheretejští, i Peletejští, a všickni udatní vytáhli z Jeruzaléma, aby honili Sebu syna Bichri.'),
(1554754,54,10,20,8,'A když byli u kamene toho velikého, kterýž jest v Gabaon, Amaza potkal se s nimi. Joáb pak byl opásán po sukni, v kterouž byl oblečen, na níž také měl připásaný meč k bedrám v pošvě své, kterýž snadně vytrhnouti i zase vstrčiti mohl.'),
(1554755,54,10,20,9,'I řekl Joáb Amazovi: Dobře-li se máš, bratře můj? A ujal Joáb pravou rukou Amazu za bradu, aby ho políbil.'),
(1554756,54,10,20,10,'Ale Amaza nešetřil se meče, kterýž byl v ruce Joábově. I ranil ho jím pod páté žebro, a vykydl střeva jeho na zem jednou ranou, a umřel. I honili Joáb a Abizai, bratr jeho, Sebu syna Bichri.'),
(1554757,54,10,20,11,'Tedy stoje tu jeden podlé něho z služebníků Joábových, řekl: Kdokoli přeje Joábovi, a kdokoli drží s Davidem, jdi za Joábem.'),
(1554758,54,10,20,12,'Amaza pak válel se ve krvi prostřed cesty. A vida onen, že se zastavoval všecken lid, odvlékl Amazu s cesty do pole, a uvrhl na něj roucho, vida, že každý, kdož šel mimo něj, zastavoval se.'),
(1554759,54,10,20,13,'A když byl odvlečen z cesty, šel jeden každý za Joábem, aby honili Sebu syna Bichri.'),
(1554760,54,10,20,14,'(Kterýžto prošel všecka pokolení Izraelská do Abel Betmaacha se všechněmi Berejskými, kteříž se byli shromáždili a šli za ním.)'),
(1554761,54,10,20,15,'A přitáhše, oblehli jej v Abel Betmaacha, a udělali násyp proti městu, kteréž se bránilo z bašt; všecken pak lid, kterýž byl s Joábem, usiloval podvrátiti zed.'),
(1554762,54,10,20,16,'V tom zvolala jedna rozumná žena z města: Slyšte, slyšte! Rcete medle Joábovi: Přistup sem, a budu s tebou mluviti.'),
(1554763,54,10,20,17,'Kterýž když k ní přistoupil, řekla žena: Ty-li jsi Joáb? Odpověděl: Jsem. I řekla jemu: Poslyš slov služebnice své. Odpověděl: Slyším.'),
(1554764,54,10,20,18,'Protož mluvila, řkuci: Takť jsou rozmlouvali hned s počátku, řkouce: Bez pochyby žeť se ptáti budou Abelských, a tak se spraví.'),
(1554765,54,10,20,19,'Jáť jsem jedno z pokojných a věrných Izraelských, ty pak usiluješ zkaziti město, a to ještě hlavní město v Izraeli. I pročež usiluješ sehltiti dědictví Hospodinovo?'),
(1554766,54,10,20,20,'Tedy odpověděl Joáb a řekl: Odstup, odstup to ode mne, abych sehltiti a zkaziti chtěl.'),
(1554767,54,10,20,21,'Neníť toho, ale muž z hory Efraim, jménem Seba, syn Bichri, pozdvihl ruky své proti králi Davidovi. Vydejte ho samého, a odtrhnemť od města. I řekla žena Joábovi: Hle, hlava jeho vyvržena bude tobě přes zed.'),
(1554768,54,10,20,22,'A tak zjednala to žena ta u všeho lidu moudrostí svou, že sťavše hlavu Seby syna Bichri, vyhodili ji Joábovi. Kterýžto když zatroubil v troubu, rozešli se od města jeden každý do stanů svých. Joáb také vrátil se do Jeruzaléma k králi.'),
(1554769,54,10,20,23,'Byl pak Joáb představen všemu vojsku Izraelskému, a Banaiáš syn Joiadův nad Cheretejskými a Peletejskými.'),
(1554770,54,10,20,24,'Též Aduram byl nad platy, a Jozafat syn Achiludův byl kanclířem,'),
(1554771,54,10,20,25,'A Seiáš písařem, Sádoch pak a Abiatar byli kněžími.'),
(1554772,54,10,20,26,'Híra také Jairský byl knížetem Davidovým.'),
(1554773,54,10,21,1,'Byl pak hlad za dnů Davidových tři léta pořád. I hledal David tváři Hospodinovy. Jemuž řekl Hospodin: Pro Saule a pro dům jeho vražedlný, nebo zmordoval Gabaonitské.'),
(1554774,54,10,21,2,'Tedy povolav král Gabaonitských, mluvil k nim. (Gabaonitští pak nebyli z synů Izraelských, ale z ostatků Amorejských, jimž ačkoli byli synové Izraelští přísahou se zavázali, však Saul usiloval je vypléniti, v horlivosti své pro syny Izraelské a Judské.)'),
(1554775,54,10,21,3,'A řekl David Gabaonitským: Což vám učiním a čím vás spokojím, abyste dobrořečili dědictví Hospodinovu?'),
(1554776,54,10,21,4,'Odpověděli jemu Gabaonitští: Není nám o stříbro ani o zlato činiti s Saulem a domem jeho, ani o bezživotí někoho z Izraele. I řekl: Cožkoli díte, učiním vám.'),
(1554777,54,10,21,5,'Kteříž řekli králi: Muže toho, kterýž vyhubil nás, a kterýž ukládal o nás, vyhladíme, aby nezůstal v žádných končinách Izraelských.'),
(1554778,54,10,21,6,'Nechť jest nám dáno sedm mužů z jeho synů, a zvěsíme je Hospodinu u Gabaa Saulova, kteréhož byl vyvolil Hospodin. I řekl král: Já dám.'),
(1554779,54,10,21,7,'Odpustil pak král Mifibozetovi synu Jonaty, syna Saulova, pro přísahu Hospodinovu, kteráž byla mezi nimi, mezi Davidem a Jonatou synem Saulovým.'),
(1554780,54,10,21,8,'Ale vzal král dva syny Rizpy dcery Aja, kteréž porodila Saulovi, Armona a Mifibozeta, a pět synů sestry Míkol dcery Saulovy, kteréž byla porodila Adrielovi synu Barzillai Molatitského.'),
(1554781,54,10,21,9,'I vydal je v ruku Gabaonitských, kteréž zvěšeli na hoře před Hospodinem. A tak kleslo těch sedm spolu, a zbiti jsou při začátku žně, když počínali žíti ječmene.'),
(1554782,54,10,21,10,'Rizpa pak, dcera Aja, vzavši žíni, prostřela ji sobě na skále při začátku žně, dokudž nepršel na ně déšť s nebe, a nedala ptákům nebeským sedati na ně ve dne, ani přicházeti zvěři polní v noci.'),
(1554783,54,10,21,11,'Tedy oznámeno jest Davidovi, co učinila Rizpa dcera Aja, ženina Saulova.'),
(1554784,54,10,21,12,'Protož odšed David, vzal kosti Saulovy a kosti Jonaty syna jeho od starších Jábes Galád, kteříž byli je ukradli na ulici Betsan, kdežto byli je zvěšeli Filistinští v ten den, když porazili Filistinští Saule v Gelboe.'),
(1554785,54,10,21,13,'Vzal, pravím, odtud kosti Saulovy a kosti Jonaty syna jeho; i kosti těch, kteříž zvěšeni byli, sebrali.'),
(1554786,54,10,21,14,'A pochovali je s kostmi Saulovými a Jonaty syna jeho, v zemi Beniamin, v Sela, v hrobě Cis otce jeho; a učinili všecko, což byl přikázal král, a potom slitoval se Bůh nad zemí.'),
(1554787,54,10,21,15,'Vznikla pak opět válka Filistinských proti Izraelovi. I vytáhl David a služebníci jeho s ním, a bili se s Filistinskými, tak že ustal David.'),
(1554788,54,10,21,16,'Tedy Izbibenob, kterýž byl z synů jednoho obra, (jehož kopí hrot vážil tři sta lotů oceli, a měl připásaný k sobě meč nový), myslil zabiti Davida.'),
(1554789,54,10,21,17,'Ale retoval ho Abizai syn Sarvie, a raniv toho Filistinského, zabil jej. Protož muži Davidovi přisáhli, řkouce jemu: Nepůjdeš více s námi do boje, abys nezhasil svíce Izraelské.'),
(1554790,54,10,21,18,'Opět byla válka v Gob s Filistinskými. Tehdáž Sibbechai Chusatský zabil Sáfu, kterýž byl z synů téhož obra.'),
(1554791,54,10,21,19,'Byla ještě i jiná válka s Filistinskými v Gob, kdež Elchánan syn Járe Oregim Betlémský zabil bratra Goliáše Gittejského, u jehož kopí bylo dřevo jako vratidlo tkadlcovské.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554792,54,10,21,20,'Potom byla také válka v Gát. A byl tam muž veliké postavy, kterýž měl u rukou a u noh po šesti prstech, všech čtyřmecítma, a byl také syn toho obra.'),
(1554793,54,10,21,21,'Ten když haněl Izraele, zabil ho Jonata, syn Semmaa bratra Davidova.'),
(1554794,54,10,21,22,'Ti čtyři byli synové jednoho obra v Gát, kteříž padli od ruky Davidovy a od ruky služebníků jeho.'),
(1554795,54,10,22,1,'Mluvil pak David Hospodinu slova písně této v ten den, když ho vysvobodil Hospodin z ruky všech nepřátel jeho, i z ruky Saulovy.'),
(1554796,54,10,22,2,'A řekl: Hospodin skála má a hrad můj, i vysvoboditel můj se mnou.'),
(1554797,54,10,22,3,'Bůh skála má, doufati budu v něho; štít můj a roh spasení mého, vyvýšení mé a útočiště mé, spasitel můj, kterýž od násilí vysvobozuje mne.'),
(1554798,54,10,22,4,'Chvály hodného vzýval jsem Hospodina, a od nepřátel svých vysvobozen jsem.'),
(1554799,54,10,22,5,'Nebo obklíčily mne byly úzkosti smrti, a proudové bezbožných předěsili mne.'),
(1554800,54,10,22,6,'Bolesti smrtelné obstoupily mne, a osídla smrti zachvátila mne.'),
(1554801,54,10,22,7,'V úzkosti své vzýval jsem Hospodina, a k Bohu svému volal jsem, i vyslyšel z chrámu svého hlas můj, a křik můj přišel v uši jeho.'),
(1554802,54,10,22,8,'Tedy pohnula se a zatřásla země, základové nebes pohnuli se, a třásli se pro rozhněvání jeho.'),
(1554803,54,10,22,9,'Dým vycházel z chřípí jeho, a oheň zžírající z úst jeho, od něhož se uhlí roznítilo.'),
(1554804,54,10,22,10,'Nakloniv nebes, sstoupil, a mrákota byla pod nohami jeho.'),
(1554805,54,10,22,11,'I vsedl na cherubín a letěl, a spatřín jest na peří větrovém.'),
(1554806,54,10,22,12,'Položil temnosti vůkol sebe jako stany, shrnutí vod, oblaky husté.'),
(1554807,54,10,22,13,'Od blesku oblíčeje jeho rozpálilo se uhlí řeřavé.'),
(1554808,54,10,22,14,'Hřímal s nebes Hospodin, a Nejvyšší vydal zvuk svůj.'),
(1554809,54,10,22,15,'Vystřelil i střely, kterýmiž je rozptýlil, a blýskání, jímž je porazil.'),
(1554810,54,10,22,16,'I ukázaly se hlubiny mořské, a odkryti jsou základové okršlku, pro zůřivé kárání Hospodinovo, pro dmýchání větru chřípí jeho.'),
(1554811,54,10,22,17,'Poslav s výsosti, přijal mne, vytáhl mne z vod velikých.'),
(1554812,54,10,22,18,'Vysvobodil mne od nepřítele mého silného, od těch, kteříž mne nenáviděli, ačkoli silnější mne byli.'),
(1554813,54,10,22,19,'Předstihli mne v den trápení mého, ale Hospodin byl mi podpora.'),
(1554814,54,10,22,20,'Kterýž vyvedl mne na prostranství, vysvobodil mne, nebo sobě oblíbil mne.'),
(1554815,54,10,22,21,'Odplatil mi Hospodin podlé spravedlnosti mé, podlé čistoty rukou mých odplatil mi.'),
(1554816,54,10,22,22,'Nebo jsem ostříhal cest Hospodinových, aniž jsem se bezbožně strhl Boha svého.'),
(1554817,54,10,22,23,'Všickni zajisté soudové jeho jsou před oblíčejem mým, aniž jsem od kterých ustanovení jeho odstoupil.'),
(1554818,54,10,22,24,'A tak byv dokonalý před ním, šetřil jsem, abych se nedopustil nepravosti.'),
(1554819,54,10,22,25,'Protož odplatil mi Hospodin podlé spravedlnosti mé, vedlé čistoty mé před očima jeho.'),
(1554820,54,10,22,26,'Ty, Pane, s milosrdným milosrdně nakládáš, a k upřímému upřímě se máš.'),
(1554821,54,10,22,27,'K sprostnému sprostně se ukazuješ, a s převráceným převráceně zacházíš.'),
(1554822,54,10,22,28,'Lid pak ssoužený vysvobozuješ, ale před vysokomyslnými oči své sklopuješ.'),
(1554823,54,10,22,29,'Ty zajisté jsi svíce má, ó Hospodine. Hospodin jistě osvěcuje temnosti mé.'),
(1554824,54,10,22,30,'Nebo v tobě proběhl jsem vojska, v Bohu svém přeskočil jsem zed.'),
(1554825,54,10,22,31,'Toho Boha silného cesta jest dokonalá, výmluvnosti Hospodinovy přečištěné; onť jest štít všech, kteříž doufají v něho.'),
(1554826,54,10,22,32,'Nebo kdo jest Bohem kromě Hospodina? A kdo jest skalou kromě Boha našeho?'),
(1554827,54,10,22,33,'Bůh jest síla má i vojska mého, onť působí volnou cestu mou.'),
(1554828,54,10,22,34,'Činí nohy mé jako laní, a na vysokých místech mých postavuje mne.'),
(1554829,54,10,22,35,'Cvičí ruce mé k boji, tak že lámi lučiště ocelivá rukama svýma.'),
(1554830,54,10,22,36,'Nebo dal mi štít spasení svého, a dobrotivost jeho zvelebila mne.'),
(1554831,54,10,22,37,'Rozšířil kroky mé pode mnou, aby se nepodvrtly nohy mé.'),
(1554832,54,10,22,38,'Honil jsem nepřátely své a zahladil jsem je, aniž jsem se navrátil, dokudž jsem jich nevyplénil.'),
(1554833,54,10,22,39,'Docela jsem je vyhubil a sprobodal jsem je, tak že nepovstanou; i padli pod nohy mé.'),
(1554834,54,10,22,40,'Ty zajisté, Bože, přepásals mne udatností k boji, porazils pode mne ty, kteříž povstávají proti mně.'),
(1554835,54,10,22,41,'Nýbrž dals mi šíji nepřátel mých, těch, kteříž v nenávisti měli mne, a vyplénil jsem je.'),
(1554836,54,10,22,42,'Ohlédali se, ale nebyl, kdo by vysvobodil, k Hospodinu, ale nevyslyšel jich.'),
(1554837,54,10,22,43,'I potřel jsem je jako prach země, jako bláto na ulicích potlačil a rozptýlil jsem je.'),
(1554838,54,10,22,44,'Ty jsi mne vytrhl z různic lidu mého, zachovals mne, abych byl za hlavu národům; lid neznámý mně sloužil.'),
(1554839,54,10,22,45,'Cizozemci lhali mi, a jakž zaslechli, uposlechli mne.'),
(1554840,54,10,22,46,'Cizozemci svadli, a třásli se i v ohradách svých.'),
(1554841,54,10,22,47,'Živť jest Hospodin, a požehnaná skála má; protož ať jest vyvyšován Bůh, skála spasení mého,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554842,54,10,22,48,'Bůh silný, kterýž dává mi pomsty a podmaňuje mi lidi.'),
(1554843,54,10,22,49,'Vyvodíš mne z prostřed nepřátel mých, a nad povstávajícími proti mně vyvyšuješ mne, člověka nepravého mne zbavuješ.'),
(1554844,54,10,22,50,'Protož chváliti tě budu, Hospodine, mezi národy, a jménu tvému žalmy zpívati budu.'),
(1554845,54,10,22,51,'Onť jest hrad jistého spasení krále svého, a ten, kterýž činí milosrdenství pomazanému svému Davidovi, i semeni jeho až na věky.'),
(1554846,54,10,23,1,'Tato jsou pak poslední slova Davidova: Řekl David syn Izai, řekl, pravím, muž, kterýž jest velice zvýšený, pomazaný Boha Jákobova, a libý v zpěvích Izraelských:'),
(1554847,54,10,23,2,'Duch Hospodinův mluvil skrze mne, a řeč jeho jazykem mým vynesena.'),
(1554848,54,10,23,3,'Řekl mi Bůh Izraelský, mluvila skála Izraelská: Kdo panovati bude nad lidem, budeť spravedlivý, panující v bázni Boží.'),
(1554849,54,10,23,4,'Rovně jako bývá světlo jitřní, když slunce vychází ráno bez oblaků, a jako mocí tepla a deště roste bylina z země:'),
(1554850,54,10,23,5,'Tak zajisté dům můj před Bohem; nebo smlouvu věčnou učinil se mnou, kteráž všelijak upevněna a ostříhána bude. A toť jest všecko mé spasení a všeliká útěcha, že nic tak vzdělávati se nebude.'),
(1554851,54,10,23,6,'Bezbožní pak všickni vypléněni budou jako trní, kteréž rukou bráno nebývá.'),
(1554852,54,10,23,7,'Ale kdož by se ho chtěl dotknouti, vezme železo a žerď, aneb ohněm docela spálí je tu, kdež zrostlo.'),
(1554853,54,10,23,8,'Tato jsou jména nejudatnějších Davidových: Jošeb Bašebet Tachmonský, přední z vůdců, jehož rozkoš byla s kopím pojednou udeřiti na osm set ku pobití jich.'),
(1554854,54,10,23,9,'A po něm Eleazar syn Dodi, syna Achochi, mezi třmi silnými, kteříž byli s Davidem, když se opovážili proti Filistinským shromážděným tam k boji, když již byli odtáhli muži Izraelští.'),
(1554855,54,10,23,10,'Ten vstav, bil Filistinské, až ustala ruka jeho a ostála se při meči. V ten den zajisté učinil Hospodin vysvobození veliké, tak že se lid za ním navrátil, toliko aby kořisti vzebral.'),
(1554856,54,10,23,11,'Po něm pak byl Samma syn Age Hararský. Nebo když se byli shromáždili Filistinští v hromadu tu, kdež bylo díl rolí poseté šocovicí, a lid utekl před Filistinskými:'),
(1554857,54,10,23,12,'Tedy postavil se u prostřed dílu toho, a vysvobodil jej, a porazil Filistinské. I učinil Hospodin vysvobození veliké.'),
(1554858,54,10,23,13,'Sstoupili také ti tři z třidcíti předních, a přišli ve žni k Davidovi do jeskyně Adulam, když vojsko Filistinské leželo v údolí Refaim.'),
(1554859,54,10,23,14,'(Nebo David tehdáž byl v pevnosti své, a osazený lid Filistinských byl u Betléma.)'),
(1554860,54,10,23,15,'Zechtělo se pak Davidovi vody, a řekl: Ó by mi někdo dal píti vody z čisterny Betlémské, kteráž jest u brány!'),
(1554861,54,10,23,16,'A protož probivše se ti tři udatní skrze vojsko Filistinských, navážili vody z čisterny Betlémské, kteráž byla u brány, kterouž nesli a donesli k Davidovi. On pak nechtěl jí píti, ale obětoval ji Hospodinu,'),
(1554862,54,10,23,17,'A řekl: Nedejž mi toho, ó Hospodine, abych to učiniti měl. Zdaliž to není krev mužů těch, kteříž šli, opováživše se života svého? I nechtěl jí píti. To učinili ti tři silní.'),
(1554863,54,10,23,18,'Potom Abizai bratr Joábův, syn Sarvie, byl přední mezi třmi, kterýž pozdvihl kopí svého proti třem stům, kteréž i pobil, a byl z těch tří nejslovoutnější.'),
(1554864,54,10,23,19,'Z těch tří on jsa nejslavnější, byl knížetem jejich, a však oněm třem nebyl rovný.'),
(1554865,54,10,23,20,'Banaiáš také syn Joiadův, syn muže udatného, velikých činů, z Kabsael, ten porazil dva reky Moábské. Tentýž sstoupiv, zabil lva v jámě, když byl sníh.'),
(1554866,54,10,23,21,'Ten také zabil muže Egyptského, muže ku podivení, a měl Egyptský v rukou kopí. I šel k němu s holí, a vytrh kopí z ruky toho Egyptského, zabil ho kopím jeho.'),
(1554867,54,10,23,22,'To učinil Banaiáš syn Joiadův, kterýž také slovoutný byl mezi těmi třmi silnými.'),
(1554868,54,10,23,23,'A ač byl mezi třidcíti nejslavnější, však oněm třem se nevrovnal. I ustanovil ho David nad drabanty svými.'),
(1554869,54,10,23,24,'Azael také bratr Joábův byl mezi třidcíti těmito: Elchanan syn Dodův Betlémský,'),
(1554870,54,10,23,25,'Samma Charodský, Elika Charodský,'),
(1554871,54,10,23,26,'Chelez Faltický, Híra syn Ikeš Tekoitský,'),
(1554872,54,10,23,27,'Abiezer Anatotský, Mebunnai Chusatský,'),
(1554873,54,10,23,28,'Salmon Achochský, Maharai Netofatský,'),
(1554874,54,10,23,29,'Cheleb syn Baany Netofatský, Ittai syn Ribai z Gabaa synů Beniamin,'),
(1554875,54,10,23,30,'Banaiáš Faratonský, Haddai od potoku Gás,'),
(1554876,54,10,23,31,'Abialbon Arbatský, Azmavet Barechumský,'),
(1554877,54,10,23,32,'Eliachba Salbonský, z synů Jasen Jonata,'),
(1554878,54,10,23,33,'Samma Hararský, Achiam syn Sárar Ararský,'),
(1554879,54,10,23,34,'Elifelet syn Achasbai Machatského, Eliam syn Achitofelův Gilonský,'),
(1554880,54,10,23,35,'Chezrai Karmelský, Farai Arbitský,'),
(1554881,54,10,23,36,'Igal syn Nátanův z Soba, Báni Gádský,'),
(1554882,54,10,23,37,'Zelek Ammonský, Nacharai Berotský, oděnec Joába syna Sarvie,'),
(1554883,54,10,23,38,'Híra Itrejský, Gareb Itrejský,'),
(1554884,54,10,23,39,'Uriáš Hetejský. Všech třidceti a sedm.'),
(1554885,54,10,24,1,'Tedy opět prchlivost Hospodinova popudila se proti Izraelovi; nebo byl ponukl satan Davida na ně, řka: Jdi, sečti lid Izraelský a Judský.'),
(1554886,54,10,24,2,'Protož řekl král Joábovi, hejtmanu vojska svého: Projdi i hned všecka pokolení Izraelská od Dan až k Bersabé, a sečtěte lid, abych věděl počet jeho.'),
(1554887,54,10,24,3,'Ale Joáb řekl králi: Přidejž Hospodin Bůh tvůj k lidu, jakž ho koli mnoho, stokrát více, a to aby oči pána mého krále viděly. Ale proč pán můj král jest toho tak žádostiv?'),
(1554888,54,10,24,4,'A však přemohla řeč králova Joába i knížata vojska. Protož vyšel Joáb a knížata vojska od tváři královy, aby sečtli lid Izraelský.'),
(1554889,54,10,24,5,'A přepravivše se přes Jordán, položili se při Aroer po pravé straně města, kteréž jest u prostřed potoka Gád, a při Jazer.'),
(1554890,54,10,24,6,'Potom přišli do Galád a do země dolejší nové, odkudž šli do Dan Jáhan a do okolí Sidonského.'),
(1554891,54,10,24,7,'Přišli také ku pevnosti Týru, a ke všem městům Hevejských a Kananejských; odkudž šli na poledne země Judské do Bersabé.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554892,54,10,24,8,'A když schodili všecku zemi, přišli po přeběhnutí devíti měsíců a dvadcíti dní do Jeruzaléma.'),
(1554893,54,10,24,9,'I dal Joáb počet sečteného lidu králi. Bylo pak lidu Izraelského osmkrát sto tisíc mužů silných, kteříž mohli vytrhnouti meč k bitvě. Mužů také Judských pětkrát sto tisíc.'),
(1554894,54,10,24,10,'Potom padlo to těžce na srdce Davidovi, když již sečtl lid. I řekl David Hospodinu: Zhřešilť jsem těžce, že jsem to učinil, ale nyní, ó Hospodine, odejmi, prosím, nepravost služebníka svého, nebť jsem velmi bláznivě učinil.'),
(1554895,54,10,24,11,'Když pak vstal David ráno, stalo se slovo Hospodinovo k Gádovi proroku, vidoucímu Davidovu, řkoucí:'),
(1554896,54,10,24,12,'Jdi a rci Davidovi: Toto praví Hospodin: Trojíť věci podávám, vyvol sobě jednu z nich, kteroužť bych učinil.'),
(1554897,54,10,24,13,'Protož přišed Gád k Davidovi, oznámil mu to, a řekl jemu: Chceš-li, aby přišel na tebe hlad za sedm let v zemi tvé? čili abys za tři měsíce utíkal před nepřátely svými, a oni aby tě honili? čili aby za tři dni byl mor v zemi tvé? Pomysliž spěšně, a viz, jakou mám odpověd dáti tomu, kterýž mne poslal.'),
(1554898,54,10,24,14,'I řekl David k Gádovi: Úzkostmi sevřín jsem náramně; nechať, prosím, upadneme v ruku Hospodinovu, neboť jsou mnohá slitování jeho, jediné ať v ruce lidské neupadám.'),
(1554899,54,10,24,15,'A tak uvedl Hospodin mor na Izraele od jitra až do času uloženého, a zemřelo jich z lidu od Dan až do Bersabé sedmdesáte tisíc mužů.'),
(1554900,54,10,24,16,'A když vztáhl anděl ruku svou na Jeruzalém, aby hubil jej, litoval Hospodin toho zlého, a řekl andělu, kterýž hubil lid: Dostiť jest, již přestaň. Anděl pak Hospodinův byl u humna Aravny Jebuzejského.'),
(1554901,54,10,24,17,'I mluvil David Hospodinu, když uzřel anděla, an bije lid, a řekl: Aj, já jsem zhřešil, a já jsem neprávě učinil, ale tito, jsouce jako ovce, co učinili? Nechť jest, prosím, ruka tvá proti mně a proti domu otce mého.'),
(1554902,54,10,24,18,'Potom navrátiv se Gád k Davidovi v ten den, řekl jemu: Vstup a vzdělej Hospodinu oltář na humně Aravny Jebuzejského.'),
(1554903,54,10,24,19,'I šel David vedlé řeči Gádovy, jakož byl přikázal Hospodin.'),
(1554904,54,10,24,20,'A vyhlédaje Aravna, uzřel krále s služebníky jeho, an jdou k němu; protož vyšed Aravna, poklonil se králi tváří svou až k zemi.'),
(1554905,54,10,24,21,'I řekl Aravna: Proč přišel pán můj král k služebníku svému? Odpověděl David: Abych koupil od tebe humno toto, na němž bych vzdělal oltář Hospodinu, aby přestala rána tato v lidu.'),
(1554906,54,10,24,22,'Opět řekl Aravna Davidovi: Nechť vezme a obětuje pán můj král, což se mu za dobré vidí. Aj, teď volové k oběti zápalné, a smyky vozové i přípravy volů na drva.'),
(1554907,54,10,24,23,'Všecky ty věci dával králík Aravna králi. Řekl ještě Aravna králi: Hospodin Bůh tvůj zalibiž tě sobě.'),
(1554908,54,10,24,24,'Řekl pak král Aravnovi: Nikoli, ale raději koupím od tebe, a zaplatím, aniž budu obětovati Hospodinu Bohu svému oběti zápalné darem dané. A tak koupil David humno a voly za padesáte lotů stříbra.'),
(1554909,54,10,24,25,'A vzdělav tu David oltář Hospodinu, obětoval oběti zápalné a pokojné. I byl milostiv Hospodin zemi, a přestala zhouba v Izraeli.'),
(1554910,54,11,1,1,'Král pak David sstaral se a sešel věkem, a ačkoli jej šaty přikrývali, však nemohl se zahřívati.'),
(1554911,54,11,1,2,'I řekli jemu služebníci jeho: Nechť pohledají pánu našemu králi děvečky panny, kteráž by byla při králi a opatrovala jej, a aby spala v lůnu jeho, a zahřívala pána našeho krále.'),
(1554912,54,11,1,3,'A protož hledajíce děvečky krásné ve všech končinách Izraelských, nalezli Abizag Sunamitskou, a přivedli ji k králi.'),
(1554913,54,11,1,4,'Kterážto děvečka byla velmi krásná. I opatrovala krále a přisluhovala jemu, ale král jí nepoznal.'),
(1554914,54,11,1,5,'Adoniáš pak syn Haggity pozdvihoval se, říkaje: Jáť budu kralovati. I najednal sobě vozů a jezdců, a padesáte mužů, kteříž by běhali před ním.'),
(1554915,54,11,1,6,'A nikdy ho nezarmoutil otec jeho, aby řekl: Proč jsi to učinil? Nebo byl i on velmi krásné postavy, kteréhož porodila po Absolonovi.'),
(1554916,54,11,1,7,'I mluvíval s Joábem synem Sarvie a s Abiatarem knězem, kteříž napomáhali Adoniášovi.'),
(1554917,54,11,1,8,'Ale Sádoch kněz a Banaiáš syn Joiadův, též Nátan prorok a Simei i Rehi, a jiní přednější, kteréž měl David, nebyli s Adoniášem.'),
(1554918,54,11,1,9,'Tedy nabil Adoniáš ovcí a volů a krmného dobytka u kamene Zohelet, kterýž byl u studnice Rogel, a pozval všech bratří svých synů královských, i všech mužů Judských, služebníků králových.'),
(1554919,54,11,1,10,'Nátana však proroka a Banaiáše a jiných přednějších mužů, ani Šalomouna bratra svého nepozval.'),
(1554920,54,11,1,11,'I mluvil Nátan k Betsabé matce Šalomounově, řka: Neslyšela-lis, že kraluje Adoniáš syn Haggity, a pán náš David nic neví o tom?'),
(1554921,54,11,1,12,'Protož nyní poď, prosím, a dámť radu, kterouž vysvobodíš život svůj, i život syna svého Šalomouna.'),
(1554922,54,11,1,13,'Jdiž, a vejda k králi Davidovi, rci jemu: Zdaliž jsi ty, pane můj králi, nepřisáhl služebnici své, řka: Šalomoun syn tvůj kralovati bude po mně, a onť seděti bude na stolici mé? Pročež tedy kraluje Adoniáš?'),
(1554923,54,11,1,14,'A aj, když ty ještě tam mluviti budeš s králem, přijduť za tebou a doplním řeč tvou.'),
(1554924,54,11,1,15,'A tak vešla Betsabé k králi do pokoje. Král pak již byl velmi starý, a Abizag Sunamitská přisluhovala králi.'),
(1554925,54,11,1,16,'Tedy Betsabé naklonivši hlavy, poklonila se králi. Jížto řekl král: Což chceš?'),
(1554926,54,11,1,17,'I odpověděla jemu: Pane můj, ty jsi přisáhl skrze Hospodina Boha svého služebnici své, řka: Šalomoun syn tvůj kralovati bude po mně, a on seděti bude na stolici mé.'),
(1554927,54,11,1,18,'A nyní, hle, Adoniáš kraluje, ty pak nyní, pane můj králi, nic nevíš o tom.'),
(1554928,54,11,1,19,'Nebo nabiv volů a krmného dobytka a ovec množství, pozval všech synů královských, i Abiatara kněze a Joába hejtmana vojska, Šalomouna pak služebníka tvého nepozval.'),
(1554929,54,11,1,20,'Ješto ty, pane můj králi, víš, že oči všeho Izraele na tebe jsou obráceny, abys jim oznámil, kdo by seděti měl na stolici pána mého krále po tobě.'),
(1554930,54,11,1,21,'Sic jinak bude to, když usne pán můj král s otci svými, že já a syn můj Šalomoun budeme jako hříšníci.'),
(1554931,54,11,1,22,'A aj, když ještě ona mluvila s králem, přišel Nátan prorok.'),
(1554932,54,11,1,23,'I oznámili králi, řkouce: Aj, teď Nátan prorok. A tak všel před krále, a poklonil se jemu tváří svou až k zemi.'),
(1554933,54,11,1,24,'Zatím řekl Nátan: Pane můj králi, ty-lis pověděl: Adoniáš kralovati bude po mně, a on seděti bude na stolici mé?'),
(1554934,54,11,1,25,'Nebo odšed dnes, nabil volů a krmného dobytka, i ovec množství, a sezval všecky syny královy a hejtmany vojska, i Abiatara kněze. A hle, oni jedí a pijí před ním, a praví: Živ buď král Adoniáš.'),
(1554935,54,11,1,26,'Mne pak služebníka tvého, a Sádocha kněze, a Banaiáše syna Joiadova, a Šalomouna služebníka tvého nepozval.'),
(1554936,54,11,1,27,'Tak-liž jest ode pána mého krále nařízeno? Mně jsi zajisté neoznámil služebníku svému, kdo bude seděti na stolici pána mého krále po tobě?'),
(1554937,54,11,1,28,'A odpovídaje král David, řekl: Zavolejte mi Betsabé. Kteráž všedši před krále, stála před ním.'),
(1554938,54,11,1,29,'I přisáhl král, řka: Živť jest Hospodin, kterýž vysvobodil duši mou ze všelikých úzkostí,'),
(1554939,54,11,1,30,'Že jakož jsem přisáhl tobě skrze Hospodina Boha Izraelského, řka, že syn tvůj Šalomoun kralovati bude po mně, a on seděti bude na stolici mé místo mně, takť učiním dnes.'),
(1554940,54,11,1,31,'A naklonivši hlavy Betsabé tváří k zemi, poklonu učinila králi a řekla: Živ buď pán můj král David na věky.'),
(1554941,54,11,1,32,'Řekl ještě král David: Zavolejte ke mně Sádocha kněze a Nátana proroka, a Banaiáše syna Joiadova. Kteřížto vešli před krále.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554942,54,11,1,33,'I řekl jim král: Vezměte s sebou služebníky pána svého, a vsaďte Šalomouna syna mého na mezkyni mou, a veďte ji k Gihonu.'),
(1554943,54,11,1,34,'I pomaže ho tam Sádoch kněz a Nátan prorok za krále nad Izraelem, a troubiti budete troubou, a díte: Živ buď král Šalomoun.'),
(1554944,54,11,1,35,'Potom vstoupíte zase, jdouce za ním. Kterýž přijda, seděti bude na stolici mé, a on kralovati bude místo mne; nebť jsem jemu přikázal, aby byl vůdcí nad Izraelem i nad Judou.'),
(1554945,54,11,1,36,'A odpovídaje Banaiáš syn Joiadův králi, řekl: Amen. Způsobiž to Hospodin, Bůh pána mého krále.'),
(1554946,54,11,1,37,'A jakož byl Hospodin se pánem mým králem, tak budiž i s Šalomounem, a zvelebiž stolici jeho více, než stolici pána mého krále Davida.'),
(1554947,54,11,1,38,'A tak šli dolů Sádoch kněz a Nátan prorok, a Banaiáš syn Joiadův, Cheretejští také i Peletejští, a vsadili Šalomouna na mezkyni krále Davida, a dovedli jej k Gihonu.'),
(1554948,54,11,1,39,'Vzal také Sádoch kněz roh oleje z stánku, a pomazal Šalomouna. Potom troubili trubou, a řekl všecken lid: Živ buď král Šalomoun.'),
(1554949,54,11,1,40,'I vstoupil všecken lid za ním; kterýžto lid prozpěvoval s plésáním, a veselil se radostí velikou, tak až se všudy rozléhalo od zvuku jejich.'),
(1554950,54,11,1,41,'Což slyše Adoniáš i všickni pozvaní, kteříž byli s ním, (byli pak již pojedli), slyše také i Joáb zvuk trouby, řekl: Jaký to zvuk v městě hlučících?'),
(1554951,54,11,1,42,'A když on ještě mluvil, aj, Jonata syn Abiatara kněze přišel, jemuž řekl Adoniáš: Přistup sem, nebo jsi muž udatný a dobré poselství neseš.'),
(1554952,54,11,1,43,'Tedy odpovídaje Jonata, řekl Adoniášovi: Právě jižtě pán náš král David ustanovil Šalomouna za krále.'),
(1554953,54,11,1,44,'Nebo poslal s ním král Sádocha kněze a Nátana proroka a Banaiáše syna Joiadova, ano i Cheretejské a Peletejské, a vsadili jej na mezkyni královskou.'),
(1554954,54,11,1,45,'I pomazali jej Sádoch kněz a Nátan prorok za krále u Gihonu, a vstupovali odtud s radostí, tak že hlučelo město. Toť jest zvuk ten, kterýž jste slyšeli.'),
(1554955,54,11,1,46,'Ano již i dosedl Šalomoun na stolici královskou.'),
(1554956,54,11,1,47,'Nýbrž i služebníci královští přišli, aby dobrořečili pánu našemu, králi Davidovi, řkouce: Učiniž slavné Bůh tvůj jméno Šalomounovo nad jméno tvé, a zvelebiž stolici jeho nad stolici tvou. I poklonil se král na ložci svém.'),
(1554957,54,11,1,48,'Ano i král takto řekl: Požehnaný Hospodin Bůh Izraelský, kterýž dal dnes sedícího na trůnu mém, a abych na to očima svýma hleděl.'),
(1554958,54,11,1,49,'I předěšeni jsou, a vstavše všickni ti pozvaní, kteříž byli při Adoniášovi, odešli jeden každý cestou svou.'),
(1554959,54,11,1,50,'Adoniáš také boje se Šalomouna, vstav, odšel a chytil se rohů oltáře.'),
(1554960,54,11,1,51,'I pověděli Šalomounovi, řkouce: Aj, Adoniáš bojí se krále Šalomouna, a hle, drží se rohů oltáře a praví: Nechť mi přisáhne dnes král Šalomoun, že nezabije mne služebníka svého mečem.'),
(1554961,54,11,1,52,'I řekl Šalomoun: Bude-li muž statečný, nespadneť vlas s něho na zem; pakliť co zlého na něm nalezeno bude, umřeť.'),
(1554962,54,11,1,53,'Poslal tedy král Šalomoun, aby jej odvedli od oltáře. Kterýž přišed, poklonil se králi Šalomounovi. Jemuž řekl Šalomoun: Jdiž do domu svého.'),
(1554963,54,11,2,1,'Když se pak čas smrti Davidovy přiblížil, dával přikázaní Šalomounovi synu svému, řka:'),
(1554964,54,11,2,2,'Jáť již odcházím podlé způsobu všech lidí. Proto posilniž se a měj se zmužile,'),
(1554965,54,11,2,3,'A ostříhej přikázaní Hospodina Boha svého, chodě po cestách jeho, a zachovávaje ustanovení jeho, rozkázaní jeho, i soudy jeho i svědectví jeho, jakož psáno jest v zákoně Mojžíšově, ať by se šťastně vedlo, což bys koli činil, i všecko, k čemuž bys se obrátil,'),
(1554966,54,11,2,4,'A aby naplnil Hospodin slovo své, kteréž mi zaslíbil, mluvě: Budou-li ostříhati synové tvoji cesty své, chodíce přede mnou v pravdě z celého srdce svého a z celé duše své, tak mluvě: Že nebude vypléněn po tobě muž z stolice Izraelské.'),
(1554967,54,11,2,5,'Také i tom víš, co jest mi učinil Joáb syn Sarvie, totiž, co učinil dvěma hejtmanům vojsk Izraelských, Abnerovi synu Ner, a Amazovi synu Jeter, že je zamordoval, dopustiv se vraždy lstivé v čas pokoje, a zmazal krví zrádně vylitou pás svůj rytířský, kterýž měl na bedrách svých, a obuv svou, kterouž měl na nohách svých.'),
(1554968,54,11,2,6,'Protož zachováš se podlé moudrosti své, a nedáš sstoupiti šedinám jeho v pokoji do hrobu.'),
(1554969,54,11,2,7,'S syny pak Barzillai Galádského učiníš milosrdenství, tak aby jídali spolu s jinými při stole tvém; nebo tak podobně ke mně přišli, když jsem utíkal před Absolonem bratrem tvým.'),
(1554970,54,11,2,8,'Hle, máš také v moci své Semei syna Gery Beniaminského z Bahurim, kterýž mi zlořečil zlořečením velikým v ten den, když jsem šel do Mahanaim, ačkoli potom vyšel mi vstříc k Jordánu, jemuž jsem přisáhl skrze Hospodina, řka: Nezabiji tě mečem.'),
(1554971,54,11,2,9,'Nyní však neodpouštěj jemu. A poněvadž jsi muž opatrný, víš, jak bys k němu přistoupiti měl, abys uvedl šediny jeho se krví do hrobu.'),
(1554972,54,11,2,10,'A tak usnul David s otci svými, a pohřben jest v městě Davidově.'),
(1554973,54,11,2,11,'Dnů pak, v nichž kraloval David nad Izraelem, bylo čtyřidceti let. V Hebronu kraloval sedm let, a v Jeruzalémě kraloval třidceti a tři léta.'),
(1554974,54,11,2,12,'I dosedl Šalomoun na stolici Davida otce svého, a utvrzeno jest království jeho velmi.'),
(1554975,54,11,2,13,'Tedy přišel Adoniáš syn Haggity k Betsabé matce Šalomounově. Kterážto řekla: Pokojný-li jest příchod tvůj? I odpověděl: Pokojný.'),
(1554976,54,11,2,14,'Řekl dále: Mám k tobě řeč. I řekla: Mluv.'),
(1554977,54,11,2,15,'Tedy řekl: Ty víš, že mé bylo království, a na mne obrátili všickni Izraelští tvář svou, abych kraloval, ale přeneseno jest království na bratra mého, nebo od Hospodina usouzeno mu bylo.'),
(1554978,54,11,2,16,'Nyní pak jediné věci žádám od tebe, nechť nejsem oslyšán. Kteráž řekla jemu: Mluv.'),
(1554979,54,11,2,17,'A on řekl: Rci, prosím, Šalomounovi králi, (neboť neoslyší tebe), ať mi dá Abizag Sunamitskou za manželku.'),
(1554980,54,11,2,18,'Odpověděla Betsabé: Dobře, jáť budu mluviti o tebe s králem.'),
(1554981,54,11,2,19,'Protož vešla Betsabé k králi Šalomounovi, aby mluvila s ním o Adoniáše. I povstal král proti ní, a pokloniv se jí, posadil se na stolici své; rozkázal také postaviti stolici matce své. I posadila se po pravici jeho,'),
(1554982,54,11,2,20,'A řekla: Jediné věci neveliké já žádám od tebe, nechť nejsem oslyšána. I řekl jí král: Žádej, matko má, neboť neoslyším tebe.'),
(1554983,54,11,2,21,'Kteráž řekla: Nechť jest dána Abizag Sunamitská Adoniášovi bratru tvému za manželku.'),
(1554984,54,11,2,22,'A odpovídaje král Šalomoun, řekl matce své: Proč ty jen žádáš za Abizag Sunamitskou Adoniášovi? Žádej jemu království, poněvadž on jest bratr můj starší nežli já, a má po sobě Abiatara kněze a Joába syna Sarvie.'),
(1554985,54,11,2,23,'I přisáhl král Šalomoun skrze Hospodina, řka: Toto ať mi učiní Bůh a toto přidá, že sám proti sobě mluvil Adoniáš řeč tuto.'),
(1554986,54,11,2,24,'Protož nyní, živť jest Hospodin, kterýž mne utvrdil, a posadil na stolici Davida otce mého, a kterýž mi vzdělal dům, jakož byl mluvil, že dnes umříti musí Adoniáš.'),
(1554987,54,11,2,25,'A tak poslal král Šalomoun Banaiáše syna Joiadova, kterýž udeřil na něj, tak že umřel.'),
(1554988,54,11,2,26,'Abiatarovi knězi také řekl král: Jdi do Anatot k rolí své, nebo jsi hoden smrti. Ale nyní nezabiji tebe, poněvadž jsi nosil truhlu Hospodinovu před Davidem otcem mým, a snášel jsi všecka ta ssoužení, kteráž snášel otec můj.'),
(1554989,54,11,2,27,'I svrhl Šalomoun Abiatara s kněžství Hospodinova, aby naplnil řeč Hospodinovu, kterouž byl mluvil proti domu Elí v Sílo.'),
(1554990,54,11,2,28,'Donesla se pak pověst ta Joába, (nebo Joáb postoupil po Adoniášovi, ačkoli po Absolonovi byl nepostoupil). Protož utekl Joáb k stánku Hospodinovu, a chytil se rohů oltáře.'),
(1554991,54,11,2,29,'I oznámeno králi Šalomounovi, že utekl Joáb k stánku Hospodinovu, a že jest u oltáře. Tedy poslal Šalomoun Banaiáše syna Joiadova, řka: Jdi, oboř se na něj.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1554992,54,11,2,30,'A když přišel Banaiáš k stánku Hospodinovu a řekl jemu: Takto praví král: Vyjdi, odpověděl jemu: Nikoli, ale tuto umru. V tom oznámil zase Banaiáš králi řeč tu, řka: Takto mluvil Joáb, a tak mi odpověděl.'),
(1554993,54,11,2,31,'Na to řekl jemu král: Učiň, jakž mluvil, a udeř na něj, a pochovej jej, a odejmeš krev nevinnou, kterouž vylil Joáb, ode mne i od domu otce mého.'),
(1554994,54,11,2,32,'A navrátí Hospodin krev jeho na hlavu jeho; nebo obořiv se na dva muže spravedlivější a lepší, než jest sám, zamordoval je mečem bez vědomí otce mého Davida, Abnera syna Ner, hejtmana vojska Izraelského, a Amazu syna Jeter, hejtmana vojska Judského.'),
(1554995,54,11,2,33,'A tak navrátí se krev jejich na hlavu Joábovu, a na hlavu semene jeho na věky, Davidovi pak a semeni jeho, domu jeho a stolici jeho buď pokoj až na věky od Hospodina.'),
(1554996,54,11,2,34,'A protož vyšed Banaiáš syn Joiadův, obořil se na něj, a zabil jej. A pochován jest v domě svém na poušti.'),
(1554997,54,11,2,35,'I ustanovil král Banaiáše syna Joiadova místo něho nad vojskem, a Sádocha kněze ustanovil král místo Abiatara.'),
(1554998,54,11,2,36,'Zatím poslav král, povolal Semei, a řekl jemu: Ustavěj sobě dům v Jeruzalémě, a tu zůstávej a nevycházej odtud ani sem ani tam.'),
(1554999,54,11,2,37,'Nebo v kterýkoli den vyjdeš, a přejdeš přes potok Cedron, věz jistotně, že umřeš; krev tvá bude na hlavu tvou.'),
(1555000,54,11,2,38,'I dí Semei k králi: Dobráť jest ta řeč. Jakož mluvil pán můj král, takť učiní služebník tvůj. A tak bydlil Semei v Jeruzalémě po mnohé dny.'),
(1555001,54,11,2,39,'Stalo se pak po třech letech, že utekli dva služebníci Semei k Achisovi synu Maachy, králi Gát. I pověděli to Semei, řkouce: Hle, služebníci tvoji jsou v Gát.'),
(1555002,54,11,2,40,'Pročež vstav Semei, osedlal osla svého, a jel do Gát k Achisovi, aby hledal služebníků svých. I navrátil se Semei, a přivedl zase služebníky své z Gát.'),
(1555003,54,11,2,41,'Povědíno pak Šalomounovi, že odšel Semei z Jeruzaléma do Gát, a že se navrátil.'),
(1555004,54,11,2,42,'Tedy poslav král, povolal Semei a řekl jemu: Zdaliž jsem tě přísahou nezavázal skrze Hospodina, a osvědčil jsem proti tobě, řka: V kterýkoli den vyjdeš, a sem i tam choditi budeš, věz jistotně, že smrtí umřeš? A řekl jsi mi: Dobrá jest ta řeč, kterouž jsem slyšel.'),
(1555005,54,11,2,43,'Pročež jsi tedy neostříhal přísahy Hospodinovy a přikázaní, kteréž jsem přikázal tobě?'),
(1555006,54,11,2,44,'Řekl také král k Semei: Ty víš všecko zlé, kteréhož povědomo jest srdce tvé, co jsi učinil Davidovi otci mému, ale Hospodin uvedl zase to tvé zlé na hlavu tvou.'),
(1555007,54,11,2,45,'Král pak Šalomoun bude požehnaný, a stolice Davidova stálá před Hospodinem až na věky.'),
(1555008,54,11,2,46,'I přikázal král Banaiášovi synu Joiadovu, kterýž vyšed, obořil se na něj, tak že umřel. A tak utvrzeno jest království v ruce Šalomounově.'),
(1555009,54,11,3,1,'Spříznil se pak Šalomoun s Faraonem králem Egyptským, nebo pojal dceru Faraonovu a uvedl ji do města Davidova, dokudž nedostavěl domu svého, a domu Hospodinova i zdi Jeruzalémské vůkol.'),
(1555010,54,11,3,2,'Toliko lid obětoval na výsostech, proto že nebyl vystaven dům jménu Hospodinovu až do těch dnů.'),
(1555011,54,11,3,3,'Nebo miloval Šalomoun Hospodina, chodě v přikázaních Davida otce svého, a toliko na těch výsostech obětoval a kadil.'),
(1555012,54,11,3,4,'Protož šel král do Gabaon, aby tam obětoval; ta výsost zajisté byla největší. Tisíc obětí zápalných obětoval Šalomoun na tom oltáři.'),
(1555013,54,11,3,5,'Ukázal se pak Hospodin v Gabaon Šalomounovi ve snách noci té, a řekl Bůh: Žádej začkoli, a dám tobě.'),
(1555014,54,11,3,6,'I řekl Šalomoun: Ty jsi učinil s služebníkem svým Davidem, otcem mým, milosrdenství veliké, když chodil před tebou v pravdě a v spravedlnosti, a v upřímnosti srdce stál při tobě. Ovšem zachoval jsi jemu zvláštní toto milosrdenství, že jsi dal jemu syna, kterýž by seděl na stolici jeho, jakž se to dnes vidí.'),
(1555015,54,11,3,7,'Ačkoli pak nyní, ó Hospodine Bože můj, ty jsi ustanovil služebníka svého králem místo Davida otce mého, já však jsa velmi mladý, neumím vycházeti ani vcházeti.'),
(1555016,54,11,3,8,'Služebník, pravím, tvůj jest u prostřed lidu tvého, kterýž jsi vyvolil, lidu velikého, kterýž nemůže ani sečten ani sepsán býti pro množství.'),
(1555017,54,11,3,9,'Dejž tedy služebníku svému srdce rozumné, aby soudil lid tvůj, a aby rozeznal mezi dobrým a zlým; nebo kdo bude moci souditi tento lid tvůj tak mnohý?'),
(1555018,54,11,3,10,'I líbilo se to Hospodinu, že žádal Šalomoun za tu věc.'),
(1555019,54,11,3,11,'A řekl jemu Bůh: Proto že jsi žádal věci takové, a neprosils sobě za dlouhý věk, aniž jsi žádal sobě bohatství, aniž jsi žádal bezživotí nepřátel svých, ale žádal jsi sobě rozumnosti, abys slýchati uměl rozepře,'),
(1555020,54,11,3,12,'Aj, učinil jsem vedlé řeči tvé, aj, dalť jsem srdce moudré a rozumné, tak že rovného tobě nebylo před tebou, ani po tobě aby nepovstal rovný tobě.'),
(1555021,54,11,3,13,'K tomu i to, začež jsi nežádal, dal jsem tobě, totiž bohatství a slávu, tak aby nebylo rovného tobě žádného mezi králi po všecky dny tvé.'),
(1555022,54,11,3,14,'Přes to jestliže choditi budeš po cestách mých, ostříhaje ustanovení mých a přikázaní mých, jako chodil David otec tvůj, prodlím i dnů tvých.'),
(1555023,54,11,3,15,'A když procítil Šalomoun, a aj, byl sen. I přišel do Jeruzaléma a stál před truhlou smlouvy Hospodinovy, a obětoval oběti zápalné a oběti pokojné; udělal také hody všechněm služebníkům svým.'),
(1555024,54,11,3,16,'Tedy přišly dvě ženy hokyně k králi, a stály před ním.'),
(1555025,54,11,3,17,'I řekla jedna z těch žen: Prosím, pane můj, já a žena tato bydlíme v jednom domě. I porodila jsem u ní v témž domě.'),
(1555026,54,11,3,18,'Potom stalo se dne třetího po porodu mém, že porodila také žena tato, a byly jsme spolu. Nebylo žádného cizího s námi v domě, kromě nás dvou v témž domě.'),
(1555027,54,11,3,19,'Umřel pak syn ženy této v noci, nebo spěci, udávila ho.'),
(1555028,54,11,3,20,'A vstavši o půl noci, vzala syna mého ode mne, když spala služebnice tvá, a položila jej v lůnu svém, a syna svého mrtvého položila do lůna mého.'),
(1555029,54,11,3,21,'Ale když jsem vstala ráno, abych přikojila syna svého, a aj, mrtvý. Na kteréhož když jsem ráno pilněji pohleděla, a aj, nebyl syn můj, kteréhož jsem porodila.'),
(1555030,54,11,3,22,'I řekla žena druhá: Není tak, ale syn můj jest ten živý, a ten mrtvý jest syn tvůj. Ona pak řekla: Nikoli, ale syn tvůj jest ten mrtvý, a syn můj jest ten živý. A tak se hádaly před králem.'),
(1555031,54,11,3,23,'I řekl král: Tato praví: Ten živý jest syn můj, a syn tvůj jest ten mrtvý. Tato zase praví: Neníť tak, ale syn tvůj jest ten mrtvý, a syn můj jest ten živý.'),
(1555032,54,11,3,24,'Protož řekl král: Přineste mi meč. I přinesli meč před krále.'),
(1555033,54,11,3,25,'Tedy řekl král: Rozetněte to dítě živé na dvé, a dejte jednu polovici jedné, a polovici druhou druhé.'),
(1555034,54,11,3,26,'Ale žena, jejíž syn byl ten, kterýž živ zůstal, mluvila králi, (nebo pohnula se střeva její nad synem jejím), a řekla: Prosím, pane můj, dejte jí nemluvňátko to živé, a nikoli nezabijejte ho. Druhá pak řekla: Nechť není ani mně ani tobě, rozetněte.'),
(1555035,54,11,3,27,'K čemuž odpovídaje král, řekl: Dejtež této dítě to živé, a nikoli nezabijejte ho, onať jest matka jeho.'),
(1555036,54,11,3,28,'Tedy uslyšavše všickni Izraelští soud tento, kterýž vynesl král, báli se krále; nebo viděli, že moudrost Boží jest v srdci jeho k vykonávání soudu.'),
(1555037,54,11,4,1,'A tak král Šalomoun byl králem nade vším Izraelem.'),
(1555038,54,11,4,2,'Tato pak byla knížata jeho: Azariáš syn Sádochův knížetem,'),
(1555039,54,11,4,3,'Elichoref a Achiáš synové Sísovi byli písaři, Jozafat syn Achiludův kancléřem,'),
(1555040,54,11,4,4,'A Banaiáš syn Joiadův nad vojskem, Sádoch pak a Abiatar kněžími,'),
(1555041,54,11,4,5,'A Azariáš syn Nátanův nad úředníky, a Zábud syn Nátanův nejvyšší rada královská,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555042,54,11,4,6,'A Achisar vládař domu, Adoniram pak syn Abdy nad vybraným lidem.'),
(1555043,54,11,4,7,'Měl také Šalomoun dvanácte vládařů nade vším Izraelem, kteříž opatrovali potravou krále i dům jeho. Každého roku za měsíc jeden každý měl opatrovati krále.'),
(1555044,54,11,4,8,'A tato jsou jména jejich: Syn Chur na hoře Efraim;'),
(1555045,54,11,4,9,'Syn Deker v Makaz a v Salbim, a v Betsemes a v Elon Betchanan;'),
(1555046,54,11,4,10,'Syn Chesed v Arubot, jehož bylo Socho i všecka země Chefer;'),
(1555047,54,11,4,11,'Syn Abinadabův, jehož byly všecky končiny Dor, a měl Tafat dceru Šalomounovu za manželku;'),
(1555048,54,11,4,12,'Baana syn Achiludův, jehož byl Tanach a Mageddo, i všecken Betsan, kterýž jest vedlé Sartan pod Jezreelem, od Betsan až do Abelmehula a až za Jekmaam;'),
(1555049,54,11,4,13,'Syn Geber v Rámot Galád, jehož byly vsi Jair, syna Manassesova, kteréž jsou v Galád, jehož byla krajina Argob, kteráž jest v Bázan, šedesáte měst velikých hrazených a závřitých;'),
(1555050,54,11,4,14,'Achinadab syn Iddo v Mahanaim;'),
(1555051,54,11,4,15,'Achimaas v Neftalím, on také pojal Basemat dceru Šalomounovu za manželku;'),
(1555052,54,11,4,16,'Baana syn Chusai v Asser a v Alot;'),
(1555053,54,11,4,17,'Jozafat syn Paruach v Izachar;'),
(1555054,54,11,4,18,'Semei syn Ela v Beniamin;'),
(1555055,54,11,4,19,'Geber syn Uri v zemi Galád, v zemi Seona, krále Amorejského, a Oga krále Bázan; ten sám vládařem jedním představen byl té zemi.'),
(1555056,54,11,4,20,'Tehdáž Juda a Izrael rozmnoženi jsouce jako písek při moři v množství, jedli a pili, a veselili se.'),
(1555057,54,11,4,21,'Nebo Šalomoun panoval nade všemi královstvími od řeky až k zemi Filistinské, a až k končinám Egyptským. I přinášeli dary a sloužili Šalomounovi po všecky dny života jeho.'),
(1555058,54,11,4,22,'Vycházelo pak ku potravě Šalomounovi na každý den třidceti měr běli, a šedesáte měr mouky obecné,'),
(1555059,54,11,4,23,'Deset volů krmných a dvadceti volů pastevných, a sto ovec, kromě jelenů, srn, bůvolů a ptactva vykrmeného.'),
(1555060,54,11,4,24,'On zajisté panoval všudy s této strany řeky od Tipsach až do Gázy nade všemi králi, kteříž byli před řekou, a měl pokoj se všech stran vůkol.'),
(1555061,54,11,4,25,'I bydlil Juda a Izrael bezpečně, jeden každý pod svým vinným kmenem a pod svým fíkem, od Dan až do Bersabé, po všecky dny Šalomounovy.'),
(1555062,54,11,4,26,'Měl také Šalomoun čtyřidceti tisíc koní na stání k vozům svým, a dvanácte tisíc jízdných.'),
(1555063,54,11,4,27,'A tak opatrovali ti úředníci krále Šalomouna i všecky, kteříž přicházeli k stolu krále Šalomouna, jeden každý za měsíc svůj, nedopouštějíce, aby v čem nedostatek býti měl.'),
(1555064,54,11,4,28,'Ječmene také a slámy pro koně a pro mezky dodávali k tomu místu, kdež byl král, jeden každý, jakž mu uloženo bylo.'),
(1555065,54,11,4,29,'Nadto dal Bůh moudrost Šalomounovi a prozřetelnost velikou náramně, a širokost mysli, jako jest písku na břehu mořském.'),
(1555066,54,11,4,30,'Nebo větší byla moudrost Šalomounova, než moudrost všech národů východních, a než všeliká moudrost Egyptských.'),
(1555067,54,11,4,31,'Nýbrž moudřejší byl nad všecky lidi, až i nad Etana Ezrachitského, též nad Hémana, a Kalkole i Darda, syny Máchol, a rozneslo se jméno jeho po všech národech vůkol.'),
(1555068,54,11,4,32,'Složil také tři tisíce přísloví, a písniček jeho bylo tisíc a pět.'),
(1555069,54,11,4,33,'Vypsal též i o stromích, počna od cedru, kterýž jest na Libánu, až do mchu, kterýž roste na zdi; psal i o hovadech a o ptácích, a zeměplazích a o rybách.'),
(1555070,54,11,4,34,'Protož přicházeli ze všech národů poslouchati moudrosti Šalomounovy, i ode všech králů země, kteříž slyšeli o moudrosti jeho.'),
(1555071,54,11,5,1,'Poslal pak Chíram král Tyrský služebníky své k Šalomounovi, uslyšav, že ho pomazali za krále na místo otce jeho; nebo miloval Chíram Davida po všecky dny.'),
(1555072,54,11,5,2,'Zase poslal Šalomoun k Chíramovi, řka:'),
(1555073,54,11,5,3,'Ty víš, že David otec můj nemohl vystavěti domu jménu Hospodina Boha svého pro války, kteréž jej obkličovaly, dokudž Hospodin nepodložil nepřátel pod nohy jeho.'),
(1555074,54,11,5,4,'Ale nyní Hospodin Bůh můj dal mi odpočinutí všudy vůkol, není žádného protivníka, ani outoku nebezpečného.'),
(1555075,54,11,5,5,'Z té příčiny, aj, úmysl mám stavěti dům jménu Hospodina Boha svého, jakož mluvil Hospodin Davidovi otci mému, řka: Syn tvůj, kteréhož posadím místo tebe na stolici tvé, onť vystaví dům ten jménu mému.'),
(1555076,54,11,5,6,'A protož nyní rozkaž, ať mi nasekají cedrů na Libánu. Budou pak služebníci moji s služebníky tvými, a mzdu služebníků tvých dám tobě, tak jakž díš. Nebo sám víš, že mezi námi není žádného, kdož by uměl sekati dříví, jako jsou Sidonští.'),
(1555077,54,11,5,7,'Stalo se tedy, když uslyšel Chíram ta slova Šalomounova, že se zradoval náramně, a řekl: Požehnaný Hospodin budiž nyní,kterýž dal Davidovi syna moudrého nad tím lidem tak mnohým.'),
(1555078,54,11,5,8,'I poslal Chíram k Šalomounovi, řka: Vyrozuměl jsem, oč jsi poslal ke mně; jáť učiním všecku vůli tvou z strany dříví cedrového i jedlového.'),
(1555079,54,11,5,9,'Služebníci moji svezou je s Libánu až k moři, a dám je v vořích splaviti po moři až k místu tomu, kteréž mi ukážeš, a tu je složím; ty pak pobéřeš je a naplníš také vůli mou, dodávaje potravy čeledi mé.'),
(1555080,54,11,5,10,'A tak dával Chíram Šalomounovi dříví cedrového a dříví jedlového, jakkoli mnoho chtěl.'),
(1555081,54,11,5,11,'Šalomoun také dával Chíramovi dvadceti tisíc měr pšenice ku pokrmu čeledi jeho, a dvadceti tisíc měr oleje vytlačeného. To dával Šalomoun Chíramovi každého roku.'),
(1555082,54,11,5,12,'Když tedy dal Hospodin moudrost Šalomounovi, jakož mu byl zaslíbil, a byl pokoj mezi Chíramem a mezi Šalomounem, tak že mezi sebou učinili smlouvu:'),
(1555083,54,11,5,13,'Rozkázal král Šalomoun vybírati osoby ze všeho Izraele, a bylo vybraných třidceti tisíc mužů.'),
(1555084,54,11,5,14,'Z nichž posílal na Libán deset tisíců na každý měsíc, jedny po druhých. Jeden měsíc bývali na Libánu, a dva měsíce doma, Adoniram pak byl ustaven nad těmi vybranými.'),
(1555085,54,11,5,15,'Měl také Šalomoun sedmdesáte tisíc nosičů, a osmdesáte tisíc těch, kteříž tesali na hoře,'),
(1555086,54,11,5,16,'Kromě předních vládařů Šalomounových, kterýchž bylo nad dílem tři tisíce a tři sta. Ti představeni byli lidem, kteříž dělali.'),
(1555087,54,11,5,17,'I přikázal král, aby navozili kamení velikého, kamení nákladného k založení toho domu, a kamení tesaného,'),
(1555088,54,11,5,18,'Kteréž tesali kameníci Šalomounovi a kameníci Chíramovi a Gibličtí. A tak připravovali dříví i kamení k stavení domu toho.'),
(1555089,54,11,6,1,'I stalo se léta čtyřstého osmdesátého po vyjití synů Izraelských z země Egyptské, že Šalomoun měsíce Ziv, (jenž jest měsíc druhý), čtvrtého léta kralování svého nad Izraelem, počal stavěti domu Hospodinova.'),
(1555090,54,11,6,2,'Dům pak, kterýž stavěl král Šalomoun Hospodinu, byl zdélí šedesáti loktů, a zšíří dvadcíti, a zvýší třidcíti loktů.'),
(1555091,54,11,6,3,'Síňce také byla před chrámem dvadcíti loktů zdélí vedlé širokosti domu, a desíti loktů zšíří před domem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555092,54,11,6,4,'Udělal také v domě okna porozšířená vnitř, ale possoužená zevnitř.'),
(1555093,54,11,6,5,'Vzdělal též při zdi domu pavlače všudy vůkol vedlé zdi domu, okolo chrámu a svatyně svatých, a nadělal pokojíků všudy vůkol.'),
(1555094,54,11,6,6,'Pavlače spodní širokost byla pěti loket, prostřední širokost šesti loket, a třetí širokost sedmi loket; nebo byl zdělal ústupky ve zdi domu zevnitř všudy vůkol, aby trámové nebyli vpouštíni do zdi domu.'),
(1555095,54,11,6,7,'Když pak ten dům staven byl, z kamení hotového, tak přivezeného stavěli. Ani kladiva ani sekery, ani jakého nástroje železného nebylo slyšeti v domě, když byl staven.'),
(1555096,54,11,6,8,'Dvéře k prostředním pokojům byly po pravé straně domu, jimiž po šneku se chodilo k těm prostředním, a z prostředních k třetím.'),
(1555097,54,11,6,9,'A tak vystavěl dům ten, a dokonal jej, a přikryl jej krokvemi ohnutými a prkny cedrovými.'),
(1555098,54,11,6,10,'Vystavěl i pavlače ty vůkol všeho domu. Pěti loket zvýši byla každá z nich, a připojeny byly k domu trámy cedrovými.'),
(1555099,54,11,6,11,'Stala se pak řeč Hospodinova k Šalomounovi, řkoucí:'),
(1555100,54,11,6,12,'Toť jest ten dům, kterýž ty stavíš. Jestliže budeš choditi v ustanoveních mých, a soudy mé vykonávati, a ostříhati všech přikázaní mých, chodě v nich, tedy upevním slovo své s tebou, kteréž jsem mluvil Davidovi otci tvému.'),
(1555101,54,11,6,13,'A budu bydliti u prostřed synů Izraelských, a neopustím lidu svého Izraelského.'),
(1555102,54,11,6,14,'A tak vystavěl Šalomoun ten dům, a dokonal jej.'),
(1555103,54,11,6,15,'A otafloval zdi domu vnitř prkny cedrovými, od podlahy domu až k stropu obložil dřívím vnitř; položil také podlahu domu prkny jedlovými.'),
(1555104,54,11,6,16,'Udělal také přehražení na dvadceti loket od jedné strany domu k druhé, z prken cedrových, od podlahy až do stropu. A tak udělal u vnitřku příbytek, aby byl svatyně svatých.'),
(1555105,54,11,6,17,'Pročež čtyřidcíti loktů byl dům, jenž jest chrám přední.'),
(1555106,54,11,6,18,'A na tom cedrovém domu vnitř otaflování byly řezby, nápodobné tykvím planým a květům otevřeným. Všecko z cedru bylo, tak že ani kamene nebylo viděti.'),
(1555107,54,11,6,19,'Svatyni pak svatých v domě vnitř připravil, aby tam postavena byla truhla smlouvy Hospodinovy.'),
(1555108,54,11,6,20,'Kterážto svatyně svatých vnitř byla dvadcíti loktů zdélí, a dvadcíti loktů zšíří, též dvadcíti loktů zvýší, a obložil ji zlatem nejčistším. Oltář také cedrový obložil.'),
(1555109,54,11,6,21,'Tak obložil Šalomoun příbytek ten zlatem nejčistším, a učinil rozdělující stěnu a provazy zlaté před svatyní svatých, kterouž také obložil zlatem.'),
(1555110,54,11,6,22,'Anobrž všecken dům obložil zlatem, žádné strany nepomíjeje; též všecken oltář, kterýž byl před svatyní svatých, obložil zlatem.'),
(1555111,54,11,6,23,'Udělal také v svatyni svatých dva cherubíny z dříví olivového desíti loket zvýší.'),
(1555112,54,11,6,24,'A bylo na pět loket křídlo cherubína jedno, a na pět loket křídlo cherubína druhé; deset loket bylo od konce křídla jednoho až k konci křídla druhého.'),
(1555113,54,11,6,25,'Tak na deset loket byl i cherubín druhý; míru jednostejnou a řezbu jednostejnou měli oba cherubínové.'),
(1555114,54,11,6,26,'Vysokost cherubína jednoho byla desíti loket, a tolikéž cherubína druhého.'),
(1555115,54,11,6,27,'I postavil ty cherubíny u prostřed domu vnitřního, tak že roztáhli křídla svá, a dotýkalo se křídlo jednoho jedné stěny, též křídlo cherubína druhého dotýkalo se druhé stěny; křídla pak jejich u prostřed domu spolu se dotýkala.'),
(1555116,54,11,6,28,'Obložil také ty cherubíny zlatem.'),
(1555117,54,11,6,29,'Přesto i všecky stěny domu vůkol ozdobil řezbami cherubínů a palm a rozvitých květů, vnitř i zevnitř.'),
(1555118,54,11,6,30,'I podlahu domu položil zlatem vnitř i zevnitř.'),
(1555119,54,11,6,31,'Udělal též, kudy vcházeli do svatyně svatých, dvéře z dříví olivového, a podvoje i s veřejemi byly pětihrané.'),
(1555120,54,11,6,32,'Oboje pak ty dvéře byly z dříví olivového, kteréž ozdobil řezbami cherubínů a palm a rozvitých květů, a obložil zlatem; potáhl také i cherubíny a palmy zlatem.'),
(1555121,54,11,6,33,'Podobně udělal i u vrat chrámových dvéře z dříví olivového čtverhrané.'),
(1555122,54,11,6,34,'A oboje dvéře byly z dříví jedlového. Na dvě strany jedny dvéře otvíraly se, též na dvě strany druhé dvéře se otvíraly.'),
(1555123,54,11,6,35,'I vyřezal na nich cherubíny a palmy a rozvité květy, a obložil zlatem taženým to, což bylo vyřezáno.'),
(1555124,54,11,6,36,'Potom vystavěl síň prostřední ze tří řadů kamení tesaného, a jednoho řadu dříví cedrového hoblovaného.'),
(1555125,54,11,6,37,'Léta čtvrtého založen byl dům Hospodinův, měsíce Ziv,'),
(1555126,54,11,6,38,'A léta jedenáctého, měsíce Bul, (jenž jest měsíc osmý), dokonán jest dům se všemi přípravami svými, a se vším tím, což k němu přináleželo; kterýž stavěl sedm let.'),
(1555127,54,11,7,1,'Potom stavěl Šalomoun dům svůj za třinácte let, až jej všelijak dostavěl.'),
(1555128,54,11,7,2,'Vystavěl též dům z lesu Libánského, sto loket zdélí a padesáte loket zšíří a třidceti loket zvýší na čtyřech řadích sloupů cedrových, a trámové cedroví byli na těch sloupích.'),
(1555129,54,11,7,3,'A přikryt byl cedrovím na hoře na těch trámích, kteříž byli na čtyřidcíti pěti sloupích, po patnácti v každém řadu.'),
(1555130,54,11,7,4,'Oken také byly tři řady, okno proti oknu třmi řady.'),
(1555131,54,11,7,5,'A všecky dvéře i veřeje čtverhrané byly, i okna, a zpořádaná byla okna proti oknům třmi řady.'),
(1555132,54,11,7,6,'Udělal i síňci na sloupích. Padesáti loket byla dlouhost její a třidcíti loket širokost její, a byla ta síňce napřed, i sloupové i trámové její před tím domem.'),
(1555133,54,11,7,7,'Opět vzdělal jinou síňci, v níž byl trůn, kdež soudil, totiž síňci soudnou, kteráž přikryta byla cedrovím od jedné podlahy až do druhé.'),
(1555134,54,11,7,8,'Potom při domu svém, v kterémž bydlil, udělal síň druhou za tou síní; dílo podobné onomu bylo. Udělal také dům dceři Faraonově, kterouž byl pojal Šalomoun, podobný té síňci.'),
(1555135,54,11,7,9,'Všecko to bylo z kamení nákladného, vedlé míry tesaného a pilou řezaného, vnitř i zevnitř, a to od gruntu až k stropu, i zevnitř až k síni veliké.'),
(1555136,54,11,7,10,'Základ také byl z kamení nákladného, z kamení velikého, z kamení na deset loket, a z kamení na osm loket.'),
(1555137,54,11,7,11,'Tak i výš bylo kamení nákladné, příslušně vedlé míry tesané, a cedrové dsky.'),
(1555138,54,11,7,12,'Síň také veliká měla všudy vůkol třmi řady kamení tesané, a jedním řadem dříví cedrové, podobně jako síň vnitřní domu Hospodinova, i síňce téhož domu.'),
(1555139,54,11,7,13,'Poslav pak král Šalomoun, povolal Chírama z Týru,'),
(1555140,54,11,7,14,'(Ten byl syn ženy vdovy z pokolení Neftalímova, jehož otec byl obyvatel Tyrský, řemeslník díla z mědi), proto že byl plný moudrosti a rozumnosti i umění k dělání všelikého díla z mědi. Kterýžto když přišel k králi Šalomounovi, dělal všeliké dílo jeho.'),
(1555141,54,11,7,15,'Nejprv sformoval dva sloupy měděné. Osmnácti loket byla výsost sloupu jednoho, kterýž okolek měl dvanácti loktů. Tak i sloup druhý.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555142,54,11,7,16,'Potom udělal dvě makovice, kteréž by vstaveny byly na vrch těch sloupů, slité z mědi. Pěti loktů byla zvýší makovice jedna, a pěti loktů zvýší makovice druhá.'),
(1555143,54,11,7,17,'Mřežování také dílem pleteným, a šňůry jako řetízky udělal k těm makovicím, kteréž byly na vrchu sloupů, sedm na makovici jednu a sedm na makovici druhou.'),
(1555144,54,11,7,18,'A udělav sloupy, přidal k mřežování jednomu dva řady jablek zrnatých vůkol, aby makovice, kteréž byly na vrchu, přikrývaly. A tak učinil makovici druhé.'),
(1555145,54,11,7,19,'Na těch pak makovicích na vrchu sloupů, kteříž v síňci státi měli, bylo dílo květem liliovým na čtyři lokty.'),
(1555146,54,11,7,20,'I měly makovice ty na dvou těch sloupích, jakož svrchu tak i proti vydutí pod zamřežováním jablka zrnatá, kterýchž bylo dvě stě, dvěma řady vůkol, na jedné i na druhé makovici.'),
(1555147,54,11,7,21,'A tak postavil ty sloupy v síňci chrámové. A postaviv sloup na pravé straně, nazval jméno jeho Jachin; a když postavil sloup na levé straně, nazval jméno jeho Boaz.'),
(1555148,54,11,7,22,'A na vrchu sloupů těch bylo dílo liliové. I dokonáno jest dílo sloupů.'),
(1555149,54,11,7,23,'Udělal také moře slité, desíti loket od jednoho kraje k druhému, okrouhlé vůkol, a pět loket byla vysokost jeho, a okolek jeho třidcíti loket vůkol.'),
(1555150,54,11,7,24,'Pod jehožto krajem pukly tykvím polním podobné všudy vůkol, po desíti do lokte, obkličovaly moře vůkol; dva řady tykví litých bylo s ním slito.'),
(1555151,54,11,7,25,'A stálo na dvanácti volích. Tři obráceni byli na půlnoci, a tři patřili k západu, tři zase postaveni byli ku poledni, a tři obráceni byli k východu, a moře svrchu na nich stálo, ale všech jich zadkové byli pod mořem.'),
(1555152,54,11,7,26,'A bylo ztlouští na dlaň. Kraj jeho byl, jakýž bývá u koflíku aneb květu liliového; dva tisíce tun v se bralo.'),
(1555153,54,11,7,27,'Udělal také deset podstavků měděných. Čtyř loket zdélí byl podstavek jeden každý, a čtyř loket zšíří, a tří loket zvýší.'),
(1555154,54,11,7,28,'Bylo pak takové dílo každého podstavku; lištování bylo vůkol na nich, kteréžto lištování bylo po krajích jeho.'),
(1555155,54,11,7,29,'A na tom lištování, kteréž bylo po krajích, lvové, volové a cherubínové byli, a nad těmi kraji byl sloupec svrchu, a pod lvy a voly obruba dílem taženým.'),
(1555156,54,11,7,30,'Bylo také po čtyřech kolách měděných pod každým podstavkem, a dsky měděné, a na čtyřech úhlech svých měli raménka;tolikéž i pod každou medenicí byla ta raménka slitá při každé obrubě.'),
(1555157,54,11,7,31,'Zřídlo pak jeho mezi obrubou po vrchu bylo zhloubí lokte, a však okrouhlé, řemeslně jako i podstavek udělané, zšíří půl druhého lokte. Na kterémžto zřídle byly řezby, ale lištování jejich bylo čverhrané, neokrouhlé.'),
(1555158,54,11,7,32,'A tak po čtyřech kolách bylo pod tím lištováním, a osy kol vycházely z podstavků; vysokost kola každého byla půl druhého lokte.'),
(1555159,54,11,7,33,'Dílo těch kol bylo jako dílo kol u vozu; osy jejich i písty jejich, loukoti jejich i špice jejich, všecko bylo slité.'),
(1555160,54,11,7,34,'Tolikéž čtyři raménka na čtyřech úhlech podstavku každého, z něhož ta raménka vynikala.'),
(1555161,54,11,7,35,'Na vrchu pak podstavku byl sloupek na půl lokte zvýší, okrouhlý vůkol, a na vrchu sloupku toho byli krajové vypuštění, a lištování na nich.'),
(1555162,54,11,7,36,'I zdělal řezby na dskách po krajích jejich, a po lištování jejich, cherubíny, lvy a palmoví, jedno podlé druhého po obrubě všudy vůkol.'),
(1555163,54,11,7,37,'Na ten způsob udělal deset podstavků jednostejným slitím, na jednostejnou míru, a jednostejná řezba na všech byla.'),
(1555164,54,11,7,38,'Udělal také deset umyvadel měděných. Čtyřidceti měr bralo v se jedno umyvadlo; čtyř loket bylo to každé umyvadlo, jedno umyvadlo na jednom podstavku, a tak na desíti podstavcích.'),
(1555165,54,11,7,39,'I postavil podstavků pět po pravé straně domu, a pět po levé straně domu, moře pak postavil na pravé straně domu, k východu na poledne.'),
(1555166,54,11,7,40,'Nadělav tedy Chíram umyvadel, a lopat a kotlíků, dokonal všecko dílo, kteréž dělal králi Šalomounovi k domu Hospodinovu:'),
(1555167,54,11,7,41,'Dva sloupy a makovice okrouhlé, kteréž byly na vrchu dvou sloupů, a mřežování dvoje, aby přikrývalo ty dvě makovice okrouhlé, kteréž byly na vrchu sloupů;'),
(1555168,54,11,7,42,'A jablek zrnatých čtyři sta na dvojím mřežování; dva řady jablek zrnatých byly na mřežování jednom, aby přikrývaly dvě makovice okrouhlé, kteréž byly na vrchu sloupů;'),
(1555169,54,11,7,43,'Tolikéž podstavků deset, a umyvadel deset na podstavcích;'),
(1555170,54,11,7,44,'A moře jedno a volů dvanácte pod mořem;'),
(1555171,54,11,7,45,'Též hrnce a lopaty, a kotlíky. A všecko nádobí, kteréhož nadělal Chíram králi Šalomounovi do domu Hospodinova, bylo z mědi pulerované.'),
(1555172,54,11,7,46,'Ty věci na rovinách Jordánských slíval král v jilovaté zemi, mezi Sochot a Sartan.'),
(1555173,54,11,7,47,'Zanechal pak Šalomoun vážení všeho nádobí, pro množství veliké není vyhledáváno váhy mědi.'),
(1555174,54,11,7,48,'Nadělal také Šalomoun všeho jiného nádobí do domu Hospodinova: Oltář zlatý a stůl zlatý, na němž byli chlebové předložení,'),
(1555175,54,11,7,49,'A svícnů pět na pravé a pět na levé straně před svatyní svatých z zlata nejčistšího, též květy a lampy i utěradla z zlata,'),
(1555176,54,11,7,50,'I báně a žaltáře, kotlíky, kadidlnice a nádoby k oharkům z zlata čistého, i panty zlaté ke dveřím domu vnitřního, totiž svatyně svatých, a ke dveřím chrámovým.'),
(1555177,54,11,7,51,'A tak dokonáno jest všecko dílo, kteréž dělal král Šalomoun k domu Hospodinovu, a vnesl tam Šalomoun věci posvěcené od Davida otce svého, stříbro a zlato i nádobí, složiv je mezi poklady domu Hospodinova.'),
(1555178,54,11,8,1,'Tedy shromáždil Šalomoun k sobě do Jeruzaléma starší lidu Izraelského, a všecky přední z pokolení, totiž knížata čeledí otcovských s syny Izraelskými, aby přenesli truhlu smlouvy Hospodinovy z města Davidova, jenž jest Sion.'),
(1555179,54,11,8,2,'I sešli se k králi Šalomounovi všickni muži Izraelští měsíce Etanim, v čas slavnosti; a ten měsíc jest sedmý.'),
(1555180,54,11,8,3,'A když přišli všickni starší Izraelští, vzali kněží truhlu.'),
(1555181,54,11,8,4,'I přenesli truhlu Hospodinovu a stánek úmluvy, i všecka nádobí posvátná, kteráž byla v stánku; a tak přenesli to kněží a Levítové.'),
(1555182,54,11,8,5,'Král pak Šalomoun i všecko shromáždění Izraelské, kteréž se k němu sešlo, obětovali s ním před truhlou ovce i voly, kteříž ani popisováni ani počítáni nebyli pro množství.'),
(1555183,54,11,8,6,'I vnesli kněží truhlu smlouvy Hospodinovy na místo její, do vnitřního domu, totiž do svatyně svatých pod křídla cherubínů.'),
(1555184,54,11,8,7,'Nebo cherubínové měli roztažená křídla nad místem truhly, a přikrývali cherubínové truhlu i sochory její svrchu.'),
(1555185,54,11,8,8,'A povytáhli sochorů, tak že vidíni byli koncové jejich v svatyni k předku svatyně svatých, avšak vně nebylo jich viděti; a byli tam až do tohoto dne.'),
(1555186,54,11,8,9,'Nic nebylo v truhle kromě dvou tabulí kamenných, kteréž tam složil Mojžíš na Orébě, když všel Hospodin v smlouvu s syny Izraelskými, a oni šli z země Egyptské.'),
(1555187,54,11,8,10,'I stalo se, když vycházeli kněží z svatyně, že oblak naplnil dům Hospodinův,'),
(1555188,54,11,8,11,'Tak že nemohli kněží ostáti a sloužiti pro ten oblak; nebo sláva Hospodinova naplnila dům Hospodinův.'),
(1555189,54,11,8,12,'Tedy řekl Šalomoun: Hospodin řekl, že bude přebývati v mrákotě.'),
(1555190,54,11,8,13,'Jižť jsem vystavěl dům k přebývání tvému, místo, v němž bys přebýval na věky.'),
(1555191,54,11,8,14,'A obrátiv král tvář svou, požehnání dával všemu shromáždění Izraelskému, všecko pak shromáždění Izraelské stálo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555192,54,11,8,15,'A řekl: Požehnaný Hospodin Bůh Izraelský, kterýž mluvil ústy svými Davidovi otci mému, a skutečně naplnil to, řka:'),
(1555193,54,11,8,16,'Od toho dne, kteréhož jsem vyvedl lid svůj Izraelský z Egypta, nevyvolil jsem města z žádného pokolení Izraelského k vystavení v něm domu, kdež by přebývalo jméno mé, ale Davida jsem vyvolil, aby spravoval lid můj Izraelský.'),
(1555194,54,11,8,17,'Uložil tě byl zajisté v srdci svém David otec můj stavěti dům jménu Hospodina Boha Izraelského,'),
(1555195,54,11,8,18,'Ale Hospodin řekl Davidovi otci mému: Ačkoli jsi uložil v srdci svém stavěti dům jménu mému, a dobře jsi učinil, žes to myslil v srdci svém:'),
(1555196,54,11,8,19,'A však ty nebudeš stavěti toho domu, ale syn tvůj, kterýž vyjde z bedr tvých, on vystaví dům ten jménu mému.'),
(1555197,54,11,8,20,'A tak splnil Hospodin slovo své, kteréž byl mluvil. Nebo jsem povstal na místo Davida otce svého, a dosedl jsem na stolici Izraelskou, jakož byl mluvil Hospodin, a ustavěl jsem dům tento jménu Hospodina Boha Izraelského,'),
(1555198,54,11,8,21,'A připravil jsem tu místo truhle, v níž jest smlouva Hospodinova, kterouž učinil s otci našimi, když je vyvedl z země Egyptské.'),
(1555199,54,11,8,22,'Postavil se pak Šalomoun před oltářem Hospodinovým, přede vším shromážděním Izraelským, a pozdvihl rukou svých k nebi,'),
(1555200,54,11,8,23,'A řekl: Hospodine, Bože Izraelský, neníť podobného tobě Boha na nebi svrchu, ani na zemi dole, kterýž ostříháš smlouvy a milosrdenství služebníkům svým, chodícím před tebou v celém srdci svém,'),
(1555201,54,11,8,24,'Kterýž jsi splnil služebníku svému, Davidovi otci mému, to, co jsi mluvil jemu; nebo jsi mluvil ústy svými, a skutečně jsi to naplnil, jakož se dnes vidí.'),
(1555202,54,11,8,25,'Nyní tedy, ó Hospodine, Bože Izraelský, naplniž služebníku svému, Davidovi otci mému, což jsi mluvil jemu, řka: Nebudeť vyhlazen muž z rodu tvého od tváři mé, kterýž by seděl na stolici Izraelské, jestliže toliko ostříhati budou synové tvoji cesty své, aby chodili přede mnou, jakž jsi ty chodil přede mnou.'),
(1555203,54,11,8,26,'Protož nyní, ó Bože Izraelský, prosím, nechť jest upevněno slovo tvé, kteréž jsi mluvil služebníku svému, Davidovi otci mému.'),
(1555204,54,11,8,27,'(Ač zdali v pravdě bydliti bude Bůh na zemi? Aj, nebesa, nýbrž nebesa nebes tě neobsahují, mnohem méně dům tento, kterýž jsem vystavěl.)'),
(1555205,54,11,8,28,'A popatř k modlitbě služebníka svého a k úpění jeho, Hospodine, Bože můj, slyše volání a modlitbu, kterouž služebník tvůj modlí se dnes před tebou,'),
(1555206,54,11,8,29,'Aby oči tvé byly otevřené na dům tento v noci i ve dne, na místo toto, o němž jsi řekl: Tuť bude jméno mé, abys vyslýchal modlitbu, kterouž se modlívati bude služebník tvůj na místě tomto.'),
(1555207,54,11,8,30,'Vyslýchejž tedy modlitbu služebníka svého i lidu svého Izraelského, kterouž se modlívati budou na místě tomto; ty vždy vyslýchej v místě přebývání svého na nebesích, a vyslýchaje, buď milostiv.'),
(1555208,54,11,8,31,'Když by zhřešil člověk proti bližnímu svému, a nutil by ho k přísaze, tak že by přisahati musil, a přišla by ta přísaha před oltář tvůj do domu tohoto:'),
(1555209,54,11,8,32,'Ty vyslýchej na nebi a rozeznej, i rozsuď služebníky své, mstě nad bezbožným a obraceje skutky jeho na hlavu jeho, a ospravedlňuje spravedlivého, odplacuje mu vedlé spravedlnosti jeho.'),
(1555210,54,11,8,33,'Když by poražen byl lid tvůj Izraelský od nepřátel, proto že zhřešili proti tobě, jestliže by obrátíce se k tobě, vyznávali jméno tvé, a modléce se, poníženě prosili by tebe v domě tomto:'),
(1555211,54,11,8,34,'Ty vyslýchej na nebi a odpusť hřích lidu svému Izraelskému, a uveď je zase do země, kterouž jsi dal otcům jejich.'),
(1555212,54,11,8,35,'Když by zavříno bylo nebe, a nepršel déšť, proto že zhřešili proti tobě, a modléce se na místě tomto, vyznávali by se jménu tvému, a od hříchů svých odvrátili by se po tvém trestání:'),
(1555213,54,11,8,36,'Ty vyslýchej na nebi, a odpusť hřích služebníků svých a lidu svého Izraelského, vyuče je cestě výborné, po níž by chodili, a dej déšť na zemi svou, kterouž jsi dal lidu svému za dědictví.'),
(1555214,54,11,8,37,'Byl-li by hlad na zemi, byl-li by mor, sucho, rez, kobylky, a brouci byli-li by; ssoužil-li by jej nepřítel jeho v zemi obývání jeho, aneb jakákoli rána, jakákoli nemoc:'),
(1555215,54,11,8,38,'Všelikou modlitbu a každé úpění, kteréž by činěno bylo od kteréhokoli člověka, aneb ode všeho lidu tvého Izraelského, kdož by jen poznal ránu srdce svého, a pozdvihl by rukou svých v domě tomto,'),
(1555216,54,11,8,39,'Ty vyslýchej na nebesích v místě přebývání svého, a slituj se i učiň a odplať jednomu každému vedlé všech cest jeho, kteréž ty znáš v srdci jeho, (nebo ty sám znáš srdce všech lidí),'),
(1555217,54,11,8,40,'Aby se báli tebe po všecky dny, v nichž by živi byli na zemi, kterouž jsi dal otcům našim.'),
(1555218,54,11,8,41,'Nýbrž také cizozemec, kterýž není z lidu tvého Izraelského, přišel-li by z země daleké pro jméno tvé,'),
(1555219,54,11,8,42,'(Neboť uslyší o jménu tvém velikém a ruce tvé přesilné, a rameni tvém vztaženém), přišel-li by tedy, a modlil by se v domě tomto:'),
(1555220,54,11,8,43,'Ty vyslýchej na nebi v místě přebývání svého, a učiň všecko to, o čež volati bude k tobě cizozemec ten, aťby poznali všickni národové země jméno tvé, a báli se tebe jako lid tvůj Izraelský, a aby věděli, že jméno tvé vzýváno jest nad domem tímto, kterýž jsem vystavěl.'),
(1555221,54,11,8,44,'Když by vytáhl lid tvůj k boji proti nepříteli svému, cestou, kterouž bys poslal je, jestliže by se modlili Hospodinu naproti městu tomuto, kteréž jsi vyvolil, a naproti domu, kterýž jsem vystavěl jménu tvému:'),
(1555222,54,11,8,45,'Tolikéž vyslýchej na nebi modlitbu jejich a úpění jejich, a vyveď při jejich.'),
(1555223,54,11,8,46,'Když by zhřešili proti tobě, (jakož není člověka, kterýž by nehřešil), a rozhněvaje se na ně, vydal bys je v moc nepříteli, tak že by je jaté vedli ti, kteříž by je zjímali, do země nepřátelské, daleké neb blízké,'),
(1555224,54,11,8,47,'A usmyslili by sobě v zemi té, do kteréž by zajati byli, a obrátíce se, modlili by se tobě v zemi těch, kteříž je zzajímali, řkouce: Zhřešiliť jsme a neprávě jsme činili, bezbožně jsme činili,'),
(1555225,54,11,8,48,'A tak navrátili by se k tobě celým srdcem svým a celou duší svou v zemi nepřátel svých, kteříž je zzajímali, a modlili by se tobě naproti zemi své, kterouž jsi dal otcům jejich, naproti městu tomu, kteréž jsi vyvolil, a domu, kterýž jsem vzdělal jménu tvému:'),
(1555226,54,11,8,49,'Vyslýchejž tedy na nebesích, v místě přebývání svého, modlitbu jejich a úpění jejich, a vyveď při jejich,'),
(1555227,54,11,8,50,'A odpusť lidu svému, cožkoli zhřešil proti tobě, i všecka přestoupení jejich, jimiž přestoupili proti tobě, a nakloň k nim lítostí ty, kteříž je zjímali, aby se smilovali nad nimi.'),
(1555228,54,11,8,51,'Neboť jsou lid tvůj a dědictví tvé, kteréž jsi vyvedl z Egypta, z prostřed peci železné.'),
(1555229,54,11,8,52,'Nechať jsou tedy oči tvé otevřené k modlitbě služebníka tvého a k modlitbě lidu tvého Izraelského, abys je vyslýchal vždycky, když by tě koli vzývali.'),
(1555230,54,11,8,53,'Nebo jsi ty oddělil je sobě za dědictví ode všech národů země, jakož jsi mluvil skrze Mojžíše služebníka svého, když jsi vyvedl otce naše z Egypta, Panovníče Hospodine.'),
(1555231,54,11,8,54,'Stalo se pak, když se přestal Šalomoun modliti Hospodinu vší modlitbou a prosbou touto, že vstal od oltáře Hospodinova, a přestal klečeti a pozdvihovati rukou svých k nebi.'),
(1555232,54,11,8,55,'A stoje, dobrořečil všemu shromáždění Izraelskému hlasem velikým, řka:'),
(1555233,54,11,8,56,'Požehnaný Hospodin, kterýž dal odpočinutí lidu svému Izraelskému vedlé všeho, což mluvil. Nepochybilo ani jedno slovo ze všelikého slova jeho dobrého, kteréž mluvil skrze služebníka svého Mojžíše.'),
(1555234,54,11,8,57,'Budiž Hospodin Bůh náš s námi, jako byl s otci našimi; nezamítejž nás, ani opouštěj.'),
(1555235,54,11,8,58,'Ale nakloniž srdce naše k sobě, abychom chodili po všech cestách jeho, a ostříhali přikázaní jeho, i ustanovení jeho, a soudů jeho, kteréž přikázal otcům našim.'),
(1555236,54,11,8,59,'A ať jsou má tato slova, kterýmiž jsem se modlil před Hospodinem, blízko Hospodina Boha našeho dnem i nocí, tak aby vyvodil při služebníka svého, a při lidu svého Izraelského každého času a dne,'),
(1555237,54,11,8,60,'Aťby poznali všickni národové země, že Hospodin sám jest Bůh, a že není kromě něho žádný.'),
(1555238,54,11,8,61,'Budiž tedy srdce vaše celé k Hospodinu Bohu našemu, tak abyste chodili v ustanoveních jeho, ostříhajíce přikázaní jeho, tak jako dnešního dne.'),
(1555239,54,11,8,62,'Král pak a s ním všecken Izrael obětovali oběti před Hospodinem.'),
(1555240,54,11,8,63,'A obětoval Šalomoun v obět pokojnou, kterouž obětoval Hospodinu, volů dvamecítma tisíců, a ovec sto dvadceti tisíců, a posvěcovali domu Hospodinova král i všickni synové Izraelští.'),
(1555241,54,11,8,64,'Téhož dne posvětil král prostředku síně, kteráž byla před domem Hospodinovým; nebo obětoval tu oběti zápalné a oběti suché, a tuky pokojných obětí, proto že oltář měděný, kterýž byl před Hospodinem, byl malý, aniž mohly se na něm směstknati oběti zápalné a oběti suché, a tukové pokojných obětí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555242,54,11,8,65,'A tak držel Šalomoun toho času slavnost, a všecken Izrael s ním, shromáždění veliké odtud, kudyž se chodí do Emat, až ku potoku Egyptskému, před Hospodinem Bohem naším, za sedm dní a opět za sedm dní, to jest za čtrnácte dní.'),
(1555243,54,11,8,66,'Dne pak osmého propustil lid. Kteříž požehnavše krále, odešli do obydlí svých, radujíce se a veselíce se v srdci ze všech dobrých věcí, kteréž učinil Hospodin Davidovi služebníku svému a Izraelovi lidu svému.'),
(1555244,54,11,9,1,'Stalo se pak, když dokonal Šalomoun stavení domu Hospodinova a domu královského, podlé vší líbosti své, jakž vykonati umínil,'),
(1555245,54,11,9,2,'Že se ukázal Hospodin Šalomounovi podruhé, jakož se mu byl ukázal v Gabaon.'),
(1555246,54,11,9,3,'I řekl jemu Hospodin: Vyslyšelť jsem modlitbu tvou a prosbu tvou, kteroužs se modlil přede mnou; posvětil jsem domu toho, kterýž jsi vystavěl, aby přebývalo tam jméno mé až na věky, a byly tu oči mé i srdce mé po všecky dny.'),
(1555247,54,11,9,4,'A ty jestliže choditi budeš přede mnou, jako chodil David otec tvůj, v dokonalosti srdce a v upřímnosti, čině všecko to, což jsem přikázal tobě, ustanovení mých i soudů mých ostříhaje:'),
(1555248,54,11,9,5,'Utvrdím zajisté stolici království tvého nad Izraelem na věky, jakož jsem mluvil Davidovi otci tvému, řka: Nebudeť odjat muž z rodu tvého od trůnu Izraelského.'),
(1555249,54,11,9,6,'Pakli se nazpět odvrátíte vy i synové vaši ode mne, a nebudete ostříhati přikázaní mých a ustanovení mých, kteráž jsem vydal vám, ale odejdouce, sloužiti budete bohům cizím a klaněti se jim:'),
(1555250,54,11,9,7,'Vypléním docela Izraele se svrchku země, kterouž jsem jim dal, a dům tento, kteréhož jsem posvětil jménu svému, zavrhu od tváři své, i budeť Izrael za přísloví a za rozprávku mezi všemi národy.'),
(1555251,54,11,9,8,'Ano i dům tento, jakkoli bude slavný, kdokoli mimo něj půjde, užasne se a ckáti bude, i řekne: Proč tak učinil Hospodin zemi této a domu tomuto?'),
(1555252,54,11,9,9,'Tedy odpovědí: Proto že opustili Hospodina Boha svého, kterýž vyvedl otce jejich z země Egyptské, a chytili se bohů cizích, a klaněli se jim i sloužili jim, protož uvedl na ně Hospodin všecky tyto zlé věci.'),
(1555253,54,11,9,10,'Stalo se také po přeběhnutí dvadcíti let, v nichž vzdělal Šalomoun oba dva ty domy, dům Hospodinův a dům královský,'),
(1555254,54,11,9,11,'K čemuž byl Chíram král Tyrský daroval Šalomounovi hojně dříví cedrového a jedlového, i zlata vedlé vší vůle jeho, že dal také král Šalomoun Chíramovi dvadceti měst v zemi Galilejské.'),
(1555255,54,11,9,12,'I vyjel Chíram z Týru, aby viděl ta města, kteráž mu daroval Šalomoun, ale nelíbila se jemu.'),
(1555256,54,11,9,13,'Protož řekl: Jakáž jsou ta města, kteráž mi dáváš, bratře můj? I nazval je zemí Kabul až do tohoto dne.'),
(1555257,54,11,9,14,'Nebo byl poslal Chíram králi sto a dvadceti centnéřů zlata.'),
(1555258,54,11,9,15,'Příčina pak platu, kterýž byl uložil král Šalomoun, byla, aby stavěl dům Hospodinův a dům svůj, a Mello i zdi Jeruzalémské, též Azor a Mageddo i Gázer.'),
(1555259,54,11,9,16,'(Farao zajisté král Egyptský vytáh, dobyl Gázeru a vypálil je, Kananejské pak, kteříž byli v tom městě, pobil a dal město za věno dceři své, manželce Šalomounově.)'),
(1555260,54,11,9,17,'A tak vystavěl zase Šalomoun Gázer a Betoron dolní,'),
(1555261,54,11,9,18,'Též Baalat a Tadmor na poušti v též zemi,'),
(1555262,54,11,9,19,'I všecka města, v nichž Šalomoun měl své sklady, i města vozů, i města jezdců, vše vedlé žádosti své, cožkoli chtěl stavěti v Jeruzalémě, a na Libánu i po vší zemi panování svého.'),
(1555263,54,11,9,20,'Všecken také lid, kterýž byl pozůstal z Amorejských, Hetejských, Ferezejských, Hevejských a Jebuzejských, kteříž nebyli z synů Izraelských,'),
(1555264,54,11,9,21,'Totiž syny jejich, kteříž byli pozůstali po nich v zemi, jichž nemohli synové Izraelští vyhladiti, uvedl Šalomoun pod plat a v službu až do tohoto dne.'),
(1555265,54,11,9,22,'Z synů pak Izraelských žádného nepodrobil v službu Šalomoun, ale byli muži váleční, a služebníci jeho, a knížata jeho, vůdcové jeho a úředníci nad vozy a jezdci jeho.'),
(1555266,54,11,9,23,'Bylo těch předních vládařů, kteříž byli nad dílem Šalomounovým, pět set a padesát. Ti spravovali lidi, kteříž dělali.'),
(1555267,54,11,9,24,'Dcera pak Faraonova přestěhovala se z města Davidova do domu svého, kterýž jí byl vystavěl Šalomoun. Tehdáž také vystavěl Mello.'),
(1555268,54,11,9,25,'I obětoval Šalomoun každého roku třikrát oběti zápalné a pokojné na oltáři, kterýž byl vzdělal Hospodinu, ale kadíval na tom, kterýž byl před Hospodinem, když dokonal dům.'),
(1555269,54,11,9,26,'Nadělal také král Šalomoun lodí velikých v Aziongaber, kteréž jest podlé Elat, na břehu moře Rudého v zemi Idumejské.'),
(1555270,54,11,9,27,'A poslal Chíram na těch lodech služebníky své, plavce umělé na moři, s služebníky Šalomounovými.'),
(1555271,54,11,9,28,'Kteříž přeplavivše se do Ofir, nabrali tam zlata čtyři sta a dvadceti centnéřů, a přivezli králi Šalomounovi.'),
(1555272,54,11,10,1,'Uslyševši pak královna z Sáby pověst o Šalomounovi a jménu Hospodinovu, přijela, aby zkusila jeho v pohádkách.'),
(1555273,54,11,10,2,'A přijevši do Jeruzaléma s počtem velmi velikým, s velbloudy nesoucími vonné věci a zlata velmi mnoho i kamení drahého, přišla k Šalomounovi, a mluvila s ním o všecko, což měla v srdci svém.'),
(1555274,54,11,10,3,'Jížto odpověděl Šalomoun na všecka slova její. Nebylo nic skrytého před králem, nač by jí neodpověděl.'),
(1555275,54,11,10,4,'Protož uzřevši královna z Sáby všecku moudrost Šalomounovu i dům, kterýž byl ustavěl,'),
(1555276,54,11,10,5,'Též pokrmy stolu jeho, i sedání a stávání služebníků přisluhujících jemu, i roucha jejich, šeňkýře také jeho, i stupně, kterýmiž vstupoval k domu Hospodinovu, zděsila se náramně.'),
(1555277,54,11,10,6,'A řekla králi: Praváť jest řeč, kterouž jsem slyšela v zemi své, o věcech tvých a o moudrosti tvé,'),
(1555278,54,11,10,7,'Ješto jsem nechtěla věřiti řečem, až jsem přijela a uzřela očima svýma. Ale aj, není mi praveno ani polovice; převýšil jsi moudrostí a dobrotou pověst tu, kterouž jsem slyšela.'),
(1555279,54,11,10,8,'Blahoslavení muži tvoji, a blahoslavení služebníci tvoji, kteříž stojí před tebou vždycky, a slyší moudrost tvou.'),
(1555280,54,11,10,9,'Budiž Hospodin Bůh tvůj požehnaný, kterýž tě sobě oblíbil, aby tě posadil na stolici Izraelské, proto že miluje Hospodin Izraele na věky, a ustanovil tě králem, abys činil soud a spravedlnost.'),
(1555281,54,11,10,10,'I dala králi sto a dvadceti centnéřů zlata, a vonných věcí velmi mnoho, i kamení drahého, aniž bylo kdy více přivezeno takových vonných věcí tak mnoho, jako darovala královna z Sáby králi Šalomounovi.'),
(1555282,54,11,10,11,'(Lodí také Chíramova, kteráž přinášela zlato z Ofir, přivezla z Ofir dříví almugim velmi mnoho i kamení drahého.'),
(1555283,54,11,10,12,'I nadělal král z toho dříví almugim zábradel k domu Hospodinovu, i k domu královu, též harf a louten zpěvákům, aniž jest kdy přivezeno takového dříví almugim, ani vidíno do dnešního dne.)'),
(1555284,54,11,10,13,'Král také Šalomoun dal královně z Sáby vedlé vší vůle její, čehož požádala, nad to, což jí Šalomoun daroval darem královským. Potom se navrátila do země své ona i služebníci její.'),
(1555285,54,11,10,14,'Byla pak váha toho zlata, kteréž přicházelo Šalomounovi na každý rok, šest set šedesáte šest centnéřů zlata,'),
(1555286,54,11,10,15,'Kromě toho, co přicházelo od kupců a prodavačů vonných věcí, a ode všech králů Arabských i vývod země.'),
(1555287,54,11,10,16,'A protož nadělal král Šalomoun dvě stě štítů z zlata taženého, šest set zlatých dával na každý štít,'),
(1555288,54,11,10,17,'A tři sta pavéz z taženého zlata, tři libry zlata dal na každou pavézu. I složil je král v domě lesu Libánského.'),
(1555289,54,11,10,18,'Udělal také král stolici z kostí slonových velikou, a obložil ji zlatem ryzím.'),
(1555290,54,11,10,19,'Šest stupňů bylo k té stolici, a vrch okrouhlý byl na stolici od zadní strany její, a zpolehadla rukám s obou stran té stolice, a dva lvové stáli u zpolehadel.'),
(1555291,54,11,10,20,'A dvanácte lvů stálo tu na šesti stupních s obou stran. Nebylo nic takového učiněno v žádných královstvích.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555292,54,11,10,21,'Nadto všecky nádoby krále Šalomouna, jichž ku pití užívali, byly zlaté, a všecky nádoby v domě lesu Libánského byly z zlata nejčistšího. Nic nebylo od stříbra, aniž ho sobě co vážili ve dnech Šalomounových.'),
(1555293,54,11,10,22,'Nebo měl král lodí mořské s lodími krále Chírama. Jednou ve třech letech vracely se ty lodí mořské, přinášející zlato a stříbro, kosti slonové, a opice a pávy.'),
(1555294,54,11,10,23,'I zveleben jest král Šalomoun nad všecky krále zemské v bohatství a v moudrosti.'),
(1555295,54,11,10,24,'Pročež všickni obyvatelé země žádostivi byli viděti tvář Šalomounovu, aby slyšeli moudrost jeho, kterouž složil Bůh v srdci jeho.'),
(1555296,54,11,10,25,'A přinášeli jeden každý dary své, nádoby stříbrné a nádoby zlaté, roucha a zbroj, i vonné věci, koně a mezky, a to každého roku,'),
(1555297,54,11,10,26,'Tak že nashromáždil Šalomoun vozů a jezdců, a měl tisíc a čtyři sta vozů a dvanácte tisíc jezdců, kteréž rozsadil v městech vozů, a při králi v Jeruzalémě.'),
(1555298,54,11,10,27,'I složil král stříbra v Jeruzalémě jako kamení, a cedrového dříví jako planého fíkoví, kteréž roste v údolí u velikém množství.'),
(1555299,54,11,10,28,'Přivodili také Šalomounovi koně z Egypta a koupě rozličné; nebo kupci královští brávali koupě rozličné za slušnou mzdu,'),
(1555300,54,11,10,29,'A vodívali spřež vozníků z Egypta za šest set lotů stříbra, koně pak jednoho za sto a padesáte, a tak všechněm králům Hetejským a králům Syrským oni dodávali.'),
(1555301,54,11,11,1,'V tom král Šalomoun zamiloval ženy cizozemky mnohé, i dceru Faraonovu, i Moábské, Ammonitské, Idumejské, Sidonské a Hetejské,'),
(1555302,54,11,11,2,'Z národů těch, kteréž zapověděl Hospodin synům Izraelským, řka: Nebudete se směšovati s nimi, aniž se oni budou směšovati s vámi, neboť by naklonili srdce vaše k bohům svým. K těm přilnul Šalomoun milostí,'),
(1555303,54,11,11,3,'Tak že měl žen královen sedm set a ženin tři sta. I odvrátily ženy jeho srdce jeho.'),
(1555304,54,11,11,4,'Stalo se tedy, že když se zstaral Šalomoun, ženy jeho naklonily srdce jeho k bohům cizím, tak že nebylo srdce jeho celé při Hospodinu Bohu jeho, jako bylo srdce Davida otce jeho.'),
(1555305,54,11,11,5,'Ale obrátil se Šalomoun k Astarot, bohyni Sidonské, a k Moloch, ohavnosti Ammonské.'),
(1555306,54,11,11,6,'I činil Šalomoun to, což se nelíbilo Hospodinu, a nenásledoval cele Hospodina, jako David otec jeho.'),
(1555307,54,11,11,7,'Tedy vystavěl Šalomoun výsost Chámosovi, ohavnosti Moábské, na hoře, kteráž jest naproti Jeruzalému, a Molochovi, ohavnosti synů Ammon.'),
(1555308,54,11,11,8,'A tak vzdělal všechněm ženám svým z cizího národu, kteréž kadily a obětovaly bohům svým.'),
(1555309,54,11,11,9,'I rozhněval se Hospodin na Šalamouna, proto že se uchýlilo srdce jeho od Hospodina Boha Izraelského, kterýž se jemu byl ukázal po dvakrát,'),
(1555310,54,11,11,10,'A zapověděl jemu tu věc, aby nechodil po bozích cizích. Ale neostříhal toho, což byl přikázal Hospodin.'),
(1555311,54,11,11,11,'Protož řekl Hospodin Šalomounovi:Poněvadž se to nalezlo při tobě, a neostříhal jsi smlouvy mé ani ustanovení mých, kterážť jsem přikázal, věz, že odtrhnu království toto od tebe, a dám je služebníku tvému.'),
(1555312,54,11,11,12,'A však za dnů tvých neučiním toho pro Davida otce tvého, než z ruky syna tvého odtrhnu je.'),
(1555313,54,11,11,13,'Všeho pak království neodtrhnu, ale pokolení jednoho zanechám synu tvému pro Davida služebníka svého a pro Jeruzalém, kterýž jsem vyvolil.'),
(1555314,54,11,11,14,'A tak vzbudil Hospodin protivníka Šalomounovi, Adada Idumejského z semene královského, kterýž byl v zemi Idumejské.'),
(1555315,54,11,11,15,'Nebo stalo se, když bojoval David proti Idumejským, a Joáb kníže vojska vytáhl, aby pochoval zmordované, a pobil všecky pohlaví mužského v zemi Idumejské,'),
(1555316,54,11,11,16,'(Za šest zajisté měsíců byl tam Joáb se vším lidem Izraelským, dokudž nevyplénil všech pohlaví mužského v zemi Idumejské),'),
(1555317,54,11,11,17,'Že tehdáž utekl Adad sám, a někteří muži Idumejští z služebníků otce jeho s ním, aby šli do Egypta. Adad pak byl pachole neveliké.'),
(1555318,54,11,11,18,'Kteříž jdouce z Madian, přišli do Fáran, a vzavše s sebou některé muže z Fáran, přišli do Egypta k Faraonovi, králi Egyptskému, kterýž dal jemu dům, i stravou opatřil ho, dal jemu také i zemi.'),
(1555319,54,11,11,19,'A tak nalezl Adad milost velikou před Faraonem, tak že jemu dal za manželku sestru ženy své, sestru Tafnes královny.'),
(1555320,54,11,11,20,'I porodila jemu sestra Tafnes syna Genubata, a odchovala ho Tafnes v domu Faraonovu. I byl Genubat v domě Faraonově mezi syny Faraonovými.'),
(1555321,54,11,11,21,'Když pak uslyšel Adad v Egyptě, že by usnul David s otci svými, a že umřel i Joáb kníže vojska, tedy řekl Adad Faraonovi: Propusť mne, ať jdu do země své.'),
(1555322,54,11,11,22,'Jemuž řekl Farao: Čehožť se nedostává u mne, že chceš odjíti do země své? I řekl: Ničeho, a však vždy mne propusť.'),
(1555323,54,11,11,23,'Vzbudil ještě Bůh proti němu protivníka, Rázona syna Eliadova, kterýž byl utekl od Hadarezera krále Soby, pána svého,'),
(1555324,54,11,11,24,'A shromáždiv k sobě muže, byl knížetem roty, když je David hubil. Protož odšedše do Damašku, bydlili v něm a kralovali v Damašku.'),
(1555325,54,11,11,25,'I byl protivníkem Izraelovým po všecky dny Šalomounovy; a to bylo nad to zlé, kteréž mu činil Adad. I měl v ošklivosti Izraele, když kraloval v Syrii.'),
(1555326,54,11,11,26,'Jeroboám také syn Nebatův Efratejský z Sareda, (a jméno matky jeho ženy vdovy bylo Serua), služebník Šalomounův, pozdvihl ruky proti králi.'),
(1555327,54,11,11,27,'A tato byla příčina, pro kterouž pozdvihl ruky proti králi Šalomounovi: Že vystavěv Šalomoun Mello, zavřel mezeru města Davidova otce svého.'),
(1555328,54,11,11,28,'Jeroboám pak byl muž silný a udatný. Protož vida Šalomoun mládence, že by pracovitý byl, ustanovil ho nade všemi platy z domu Jozefa.'),
(1555329,54,11,11,29,'I stalo se téhož času, že když vyšel Jeroboám z Jeruzaléma, našel jej prorok Achiáš Silonský na cestě, jsa odín rouchem novým. A byli sami dva na poli.'),
(1555330,54,11,11,30,'Tedy ujav Achiáš roucho nové, kteréž měl na sobě, roztrhal je na dvanácte kusů.'),
(1555331,54,11,11,31,'A řekl Jeroboámovi: Vezmi sobě deset kusů; nebo takto praví Hospodin Bůh Izraelský: Aj, já roztrhnu království z ruky Šalomounovy, a dám tobě desatero pokolení.'),
(1555332,54,11,11,32,'Jedno toliko pokolení zůstane jemu pro služebníka mého Davida, a pro město Jeruzalém, kteréž jsem vyvolil ze všech pokolení Izraelských,'),
(1555333,54,11,11,33,'Proto že opustili mne, a klaněli se Astarot bohyni Sidonské, a Chámos bohu Moábskému, i Moloch bohu Ammonskému, a nechodili po cestách mých, aby činili to, což mi se líbí, totiž ustanovení má a soudy mé, jako David otec jeho.'),
(1555334,54,11,11,34,'A však neodejmu ničeho z království z rukou jemu; nebo vůdcím zanechám ho po všecky dny života jeho pro Davida služebníka svého, kteréhož jsem vyvolil, kterýž ostříhal přikázaní mých a ustanovení mých.'),
(1555335,54,11,11,35,'Ale potom vezma království z ruky syna jeho, dám tobě z něho desatero pokolení,'),
(1555336,54,11,11,36,'Synu pak jeho dám jedno pokolení, aby zůstala svíce Davidovi služebníku mému po všecky dny přede mnou v městě Jeruzalémě, kteréž jsem sobě vyvolil, aby tam jméno mé přebývalo.'),
(1555337,54,11,11,37,'A tak tebe vezmu, abys kraloval ve všech věcech, kterýchž by žádala duše tvá, a budeš králem nad Izraelem.'),
(1555338,54,11,11,38,'Protož jestliže uposlechneš všeho toho, což přikáži tobě, a choditi budeš po cestách mých, a činiti to, což mi se líbí, ostříhaje ustanovení mých a přikázaní mých, jako činil David služebník můj: budu s tebou a vzdělám tobě dům stálý, jako jsem vzdělal Davidovi, a dám tobě lid Izraelský.'),
(1555339,54,11,11,39,'Potrápímť zajisté semene Davidova pro tu věc, a však ne po všecky dny.'),
(1555340,54,11,11,40,'Pro tu příčinu chtěl Šalomoun zabiti Jeroboáma. Kterýž vstav, utekl do Egypta k Sesákovi králi Egyptskému, a byl v Egyptě, dokudž neumřel Šalomoun.'),
(1555341,54,11,11,41,'Jiné pak věci Šalomounovy, kteréž činil, i moudrost jeho vypsány jsou v knize činů Šalomounových.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555342,54,11,11,42,'Dnů pak, v nichž kraloval Šalomoun v Jeruzalémě nade vším Izraelem, bylo čtyřidceti let.'),
(1555343,54,11,11,43,'I usnul Šalomoun s otci svými, a pochován jest v městě Davida otce svého. Kraloval pak Roboám syn jeho místo něho.'),
(1555344,54,11,12,1,'Tedy přibral se Roboám do Sichem; nebo tam sešel se byl všecken Izrael, aby ho ustanovili za krále.'),
(1555345,54,11,12,2,'Stalo se pak, když uslyšel Jeroboám syn Nebatův, jsa ještě v Egyptě, kamž byl utekl před Šalomounem králem, (bydlel zajisté Jeroboám v Egyptě),'),
(1555346,54,11,12,3,'Že poslali a povolali ho; protož přišed Jeroboám i všecko shromáždění Izraelské, mluvili k Roboámovi, řkouce:'),
(1555347,54,11,12,4,'Otec tvůj ztížil jho naše; protož nyní polehč služby otce svého tvrdé a břemena jeho těžkého, kteréž vzložil na nás, a budeme tobě sloužiti.'),
(1555348,54,11,12,5,'Kterýž řekl jim: Odejděte, a třetího dne navraťte se ke mně. I odšel lid.'),
(1555349,54,11,12,6,'Tedy radil se král Roboám s starci, kteříž stávali před Šalomounem otcem jeho ještě za života jeho, řka: Kterak vy radíte, jakou odpověd mám dáti lidu tomuto?'),
(1555350,54,11,12,7,'I odpověděli jemu, řkouce: Jestliže dnes povolný budeš lidu tomuto a ochotně se jim ukážeš, a odpověd dávaje, mluviti budeš přívětivě, budouť služebníci tvoji po všecky dny.'),
(1555351,54,11,12,8,'Ale on opustil radu starců, kterouž dali jemu, a radil se s mládenci, kteříž s ním zrostli a stávali před ním.'),
(1555352,54,11,12,9,'A řekl k nim: Co vy radíte, jakou bychom dali odpověd lidu tomuto, kteříž mluvili ke mně, řkouce: Polehč břemene, kteréž vzložil otec tvůj na nás?'),
(1555353,54,11,12,10,'I odpověděli jemu mládenci, kteříž zrostli s ním, řkouce: Takto odpovíš lidu tomu, kteříž mluvili k tobě a řekli: Otec tvůj ztížil jho naše, ty pak polehč nám. Takto díš jim: Nejmenší prst můj tlustší jest nežli bedra otce mého.'),
(1555354,54,11,12,11,'Nyní tedy otec můj těžké břímě vložil na vás, já pak přidám břemene vašeho; otec můj trestal vás bičíky, ale já trestati vás budu biči uzlovatými.'),
(1555355,54,11,12,12,'Přišel tedy Jeroboám i všecken lid k Roboámovi dne třetího, jakž byl rozkázal král, řka: Navraťte se ke mně dne třetího.'),
(1555356,54,11,12,13,'I odpověděl král lidu tvrdě, opustiv radu starců, kterouž dali jemu.'),
(1555357,54,11,12,14,'A mluvil k nim vedlé rady mládenců, řka: Otec můj ztížil jho vaše, já pak přidám břemene vašeho; otec můj trestal vás bičíky, ale já trestati vás budu biči uzlovatými.'),
(1555358,54,11,12,15,'I neuposlechl král lidu. Nebo byla příčina od Hospodina, aby se naplnila řeč jeho, kterouž mluvil Hospodin skrze Achiáše Silonského k Jeroboámovi synu Nebatovu.'),
(1555359,54,11,12,16,'Protož vida všecken Izrael, že by je král oslyšel, odpověděl lid králi v tato slova: Jakýž máme díl v Davidovi? Ani dědictví nemáme v synu Izai. K stanům svým, ó Izraeli! Nyní opatř dům svůj, Davide. Odšel tedy Izrael k stanům svým,'),
(1555360,54,11,12,17,'Tak že nad syny Izraelskými toliko, kteříž bydlili v městech Judských, kraloval Roboám.'),
(1555361,54,11,12,18,'I poslal král Roboám Adurama, kterýž byl nad platy, a uházel ho všecken Izrael kamením až do smrti, čímž král Roboám přinucen byl, aby vsedna na vůz, utekl do Jeruzaléma.'),
(1555362,54,11,12,19,'A tak odstoupili synové Izraelští od domu Davidova až do dnešního dne.'),
(1555363,54,11,12,20,'I stalo se, když uslyšeli všickni Izraelští, že by se navrátil Jeroboám, poslavše, povolali ho do shromáždění, a ustanovili ho králem nade vším Izraelem. Nezůstávalo při domu Davidovu než samo pokolení Judovo.'),
(1555364,54,11,12,21,'Když pak přijel Roboám do Jeruzaléma, shromáždil všecken dům Judský a pokolení Beniamin, totiž sto a osmdesáte tisíců výborných bojovníků, aby bojovali proti domu Izraelskému, a aby zase přivedeno bylo království k Roboámovi synu Šalomounovu.'),
(1555365,54,11,12,22,'Tedy stala se řeč Boží k Semaiášovi muži Božímu, řkoucí:'),
(1555366,54,11,12,23,'Pověz Roboámovi synu Šalomounovu, králi Judskému a všemu domu Judovu i Beniaminovu, a ostatku lidu těmito slovy:'),
(1555367,54,11,12,24,'Takto praví Hospodin: Netáhněte a nebojujte proti bratřím svým synům Izraelským. Navraťte se jeden každý do domu svého, nebo ode mne stala se věc tato. I uposlechli rozkazu Hospodinova a navrátili se, aby odešli vedlé řeči Hospodinovy.'),
(1555368,54,11,12,25,'Potom vystavěl Jeroboám Sichem na hoře Efraim, a bydlil v něm, a vyšed odtud, vystavěl Fanuel.'),
(1555369,54,11,12,26,'Řekl pak Jeroboám v srdci svém: Tudíž by se navrátilo království toto k domu Davidovu,'),
(1555370,54,11,12,27,'Když by chodíval lid tento k obětování obětí v domě Hospodinově do Jeruzaléma; i obrátilo by se srdce lidu tohoto ku pánu jeho Roboámovi králi Judskému, a tak zabijíce mne, navrátili by se k Roboámovi králi Judskému.'),
(1555371,54,11,12,28,'Protož poradiv se král, udělal dvé telat zlatých a řekl lidu: Dosti jste již chodili do Jeruzaléma. Aj, teď bohové tvoji, ó Izraeli, kteříž tě vyvedli z země Egyptské.'),
(1555372,54,11,12,29,'I postavil jedno v Bethel, a druhé postavil v Dan.'),
(1555373,54,11,12,30,'Kterážto věc byla příčinou k hřešení, nebo chodíval lid k jednomu z těch až do Dan.'),
(1555374,54,11,12,31,'Vzdělal zajisté dům výsostí, a ustanovil kněží z lidu obecného, kteříž nebyli z synů Léví.'),
(1555375,54,11,12,32,'Ustanovil také Jeroboám svátek měsíce osmého, v patnáctý den téhož měsíce, ku podobenství svátku, kterýž byl v Judstvu, a obětoval na oltáři. Takž učinil i v Bethel, obětuje telatům, kteréž byl udělal; také i v Bethel ustanovil kněží výsostí, kteréž byl zdělal.'),
(1555376,54,11,12,33,'A obětoval na oltáři, kterýž byl udělal v Bethel, v patnáctý den měsíce osmého, toho měsíce, kterýž byl sobě smyslil v srdci svém, a slavil svátek s syny Izraelskými, a přistoupil k oltáři, aby kadil.'),
(1555377,54,11,13,1,'A aj, muž Boží přišel z Judstva s slovem Hospodinovým do Bethel, tehdáž když Jeroboám, stoje u oltáře, kadil.'),
(1555378,54,11,13,2,'I zvolal proti oltáři slovem Hospodinovým, řka: Oltáři, oltáři, toto praví Hospodin: Hle, syn narodí se domu Davidovu, jménem Joziáš, kterýž obětovati bude na tobě kněží výsostí, jenž zapalují kadidlo na tobě; i kosti lidské páliti budou na tobě.'),
(1555379,54,11,13,3,'I dal téhož dne znamení, řka: Totoť jest znamení, že mluvil Hospodin: Aj, oltář roztrhne se a vysype se popel, kterýž jest na něm.'),
(1555380,54,11,13,4,'V tom uslyšev král Jeroboám slovo muže Božího, že zvolal proti oltáři v Bethel, vztáhl ruku svou od oltáře a řekl: Jměte ho. I uschla ruka jeho, kterouž vztáhl proti němu, a nemohl ji zase přitáhnouti k sobě.'),
(1555381,54,11,13,5,'Oltář také se roztrhl, a vysypal se popel z oltáře podlé znamení, kteréž byl předpověděl muž Boží slovem Hospodinovým.'),
(1555382,54,11,13,6,'Protož mluvil král a řekl tomu muži Božímu: Pomodl se medle Hospodinu Bohu svému a pros za mne, abych mohl přitáhnouti ruku svou k sobě. I modlil se muž Boží Hospodinu, a přitáhl král ruku zase k sobě, a byla jako prvé.'),
(1555383,54,11,13,7,'Tedy řekl král muži Božímu: Poď se mnou domů a posilň se, a dámť dar.'),
(1555384,54,11,13,8,'I řekl muž Boží králi: Bys mi dal polovici domu svého, nešel bych s tebou, aniž bych jedl chleba, aniž bych pil vody na místě tomto.'),
(1555385,54,11,13,9,'Nebo tak mi přikázal slovem svým Hospodin, řka: Nebudeš jísti chleba, ani píti vody, aniž se navrátíš tou cestou, kterouž jsi přišel.'),
(1555386,54,11,13,10,'A tak odšel jinou cestou, a nenavrátil se tou cestou, kterouž byl přišel do Bethel.'),
(1555387,54,11,13,11,'Prorok pak jeden starý bydlil v Bethel, jehož syn přišed, vypravoval mu všecky věci, kteréž učinil muž Boží toho dne v Bethel; i slova, kteráž mluvil králi, vypravovali otci svému.'),
(1555388,54,11,13,12,'Tedy řekl jim otec jejich: Kterou cestou šel? I ukázali mu synové jeho cestu, kterouž šel ten muž Boží, kterýž byl z Judstva přišel.'),
(1555389,54,11,13,13,'Zatím řekl synům svým: Osedlejte mi osla. Kteříž osedlali mu osla, a on vsedl na něj.'),
(1555390,54,11,13,14,'A jel za mužem Božím a nalezl jej, an sedí pod dubem. I řekl jemu: Ty-li jsi ten muž Boží, kterýž jsi přišel z Judstva? A on odpověděl: Jsem.'),
(1555391,54,11,13,15,'Kterýž řekl jemu: Poď se mnou domů, a pojíš chleba.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555392,54,11,13,16,'Ale on odpověděl: Nemohuť se navrátiti, ani jíti s tebou, aniž budu jísti chleba, ani píti vody s tebou na místě tomto.'),
(1555393,54,11,13,17,'Nebo stala se ke mně řeč slovem Hospodinovým: Nebudeš tam jísti chleba, ani píti vody; nenavrátíš se, jda touž cestou, kterouž jsi šel.'),
(1555394,54,11,13,18,'Jemuž odpověděl: Takéť já prorok jsem jako i ty, a mluvil ke mně anděl slovem Hospodinovým, řka: Navrať ho s sebou do domu svého, ať pojí chleba a napije se vody. To pak sklamal jemu.'),
(1555395,54,11,13,19,'Takž se navrátil s ním, a jedl chléb v domě jeho a pil vodu.'),
(1555396,54,11,13,20,'Když pak oni seděli za stolem, stalo se slovo Hospodinovo k proroku tomu, kterýž onoho byl zase navrátil.'),
(1555397,54,11,13,21,'A zvolal na muže Božího, kterýž byl přišel z Judstva, řka: Toto praví Hospodin: Proto že jsi na odpor učinil řeči Hospodinově, a neostříhal jsi přikázaní, kteréžť vydal Hospodin Bůh tvůj,'),
(1555398,54,11,13,22,'Ale navrátils se a jedls chléb, a pils vodu na místě, o kterémžť řekl: Nebudeš jísti chleba, ani píti vody: nebudeť pochováno tělo tvé v hrobě otců tvých.'),
(1555399,54,11,13,23,'Tedy když pojedl chleba a napil se, osedlal mu osla, totiž tomu proroku, kteréhož byl navrátil.'),
(1555400,54,11,13,24,'A když odšel, trefil na něj lev na cestě a udávil jej. I leželo tělo jeho na cestě, a osel stál podlé něho; lev také stál vedlé těla mrtvého.'),
(1555401,54,11,13,25,'A aj, muži někteří jdouce tudy, uzřeli tělo mrtvé ležící na cestě, a lva, an stojí vedlé něho. Kteříž přišedše, pověděli v městě, v kterémž ten starý prorok bydlil.'),
(1555402,54,11,13,26,'Což když uslyšel ten prorok, kterýž ho byl navrátil s cesty, řekl: Muž Boží jest, kterýž na odpor učinil řeči Hospodinově; protož vydal jej Hospodin lvu, kterýž potřev ho, udávil jej vedlé řeči Hospodinovy, kterouž mluvil jemu.'),
(1555403,54,11,13,27,'Zatím mluvě k synům svým, řekl: Osedlejte mi osla. I osedlali.'),
(1555404,54,11,13,28,'A odjev, nalezl mrtvé tělo jeho ležící na cestě, a osla i lva, an stojí u toho těla; a nejedl lev těla toho, aniž co uškodil oslu.'),
(1555405,54,11,13,29,'Protož vzav prorok tělo muže Božího, vložil je na osla, a přinesl je. I přišel do města svého, aby ho plakal a pochoval.'),
(1555406,54,11,13,30,'Položil pak tělo jeho v hrobě svém, a plakali ho: Ach, bratře můj.'),
(1555407,54,11,13,31,'A pochovav ho, mluvil k synům svým, řka: Když já umru, pochovejte mne v témž hrobě, v němž muž Boží jest pochován, vedlé kostí jeho položte kosti mé.'),
(1555408,54,11,13,32,'Neboť se jistě stane to, což ohlásil slovem Hospodinovým proti oltáři, kterýž jest v Bethel, a proti všechněm domům výsostí, kteréž jsou v městech Samařských.'),
(1555409,54,11,13,33,'Po těchto příbězích neodvrátil se Jeroboám od cesty své zlé, ale opět nadělal z lidu obecného kněží výsostí. Kdo jen chtěl, posvětil ruky jeho, a ten byl knězem výsostí.'),
(1555410,54,11,13,34,'I byla ta věc domu Jeroboámovu příčinou k hřešení, aby vypléněn a vyhlazen byl se svrchku země.'),
(1555411,54,11,14,1,'Toho času roznemohl se Abiáš, syn Jeroboámův.'),
(1555412,54,11,14,2,'I řekl Jerobám ženě své: Vstaň medle a změň se, aby nepoznali, že jsi žena Jeroboámova, a jdi do Sílo. Hle, tam jest Achiáš prorok, kterýž mi byl předpověděl, že mám býti králem nad lidem tímto.'),
(1555413,54,11,14,3,'A vezma v ruce své deset chlebů a koláčů, a láhvici medu, jdi k němu; onť oznámí tobě, co se stane pacholeti tomuto.'),
(1555414,54,11,14,4,'I učinila tak žena Jeroboámova; nebo vstavši, šla do Sílo, a přišla do domu Achiášova. Ale Achiáš nemohl již hleděti, nebo pošly mu byly oči pro starost jeho.'),
(1555415,54,11,14,5,'Hospodin pak řekl Achiášovi: Aj, žena Jeroboámova jde, aby se tebe něco zeptala o synu svém, proto že jest nemocen. Toto a toto budeš jí mluviti. Budeť pak, že když přijde, činiti se bude jinou.'),
(1555416,54,11,14,6,'Protož uslyšev Achiáš šust noh jejích, když vcházela do dveří, řekl: Poď, ženo Jeroboámova, proč se jinou činíš? Já zajisté poslán jsem k tobě s řečí tvrdou.'),
(1555417,54,11,14,7,'Jdi, pověz Jeroboámovi: Toto praví Hospodin Bůh Izraelský: Poněvadž jsem tě vyvýšil z prostředku lidu, a postavil jsem tě za vůdce nad lidem svým Izraelským,'),
(1555418,54,11,14,8,'A odtrhl jsem království od domu Davidova, a dal jsem je tobě, ty však nebyl jsi jako služebník můj David, kterýž ostříhal přikázaní mých, a následoval mne v celém srdci svém, čině toliko to, což jest pravého přede mnou,'),
(1555419,54,11,14,9,'Ale zlost jsi páchal hojněji nade všecky, kteříž byli před tebou; nebo odšed, učinils sobě bohy cizí a slité, abys mne dráždil, mne pak zavrhl jsi za hřbet svůj:'),
(1555420,54,11,14,10,'Protož aj, já uvedu zlé věci na dům Jeroboámův, a vyhladím z Jeroboáma, i toho, jenž močí na stěnu, i zajatého i zanechaného v Izraeli, a vyvrhu ostatky domu Jeroboámova, jako hnůj vymítán bývá až dočista.'),
(1555421,54,11,14,11,'Toho, kdož z domu Jeroboámova umře v městě, psi žráti budou, a toho, kdož umře na poli, ptáci nebeští jísti budou; neboť jest mluvil Hospodin.'),
(1555422,54,11,14,12,'Ty pak vstana, jdi do domu svého, a když vcházeti budeš do města, tehdy umře pachole.'),
(1555423,54,11,14,13,'I budou ho plakati všecken lid Izraelský, a pochovají jej; nebo ten sám z domu Jeroboámova dostane se do hrobu, proto že o něm z domu Jeroboámova jest slovo dobré u Hospodina Boha Izraelského.'),
(1555424,54,11,14,14,'Vyzdvihneť však sobě Hospodin krále nad Izraelem, kterýž vyhladí dům Jeroboámův toho dne. Ale co? Nýbrž již vyzdvihl.'),
(1555425,54,11,14,15,'A zaklátí Hospodin Izraelem tak, jako se klátí třtina u vodách, a vykoření Izraele z země výborné této, kterouž dal otcům jejich, a rozptýlí je daleko za řeku, proto že sobě zdělali háje, popouzejíce Hospodina.'),
(1555426,54,11,14,16,'A tak vydá Izraele pro hříchy Jeroboámovy, kterýž i sám hřešil, i v hřích uvodil Izraele.'),
(1555427,54,11,14,17,'Tedy vstavši žena Jeroboámova, odešla a přišla do Tersa, a když vstupovala na prah domu, umřelo pachole.'),
(1555428,54,11,14,18,'I pochovali je, a plakal ho všecken lid Izraelský vedlé řeči Hospodinovy, kterouž mluvil skrze služebníka svého, Achiáše proroka.'),
(1555429,54,11,14,19,'Jiné pak věci Jeroboámovy, jaké boje vedl a kterak kraloval, aj, sepsány jsou v knize o králích Izraelských.'),
(1555430,54,11,14,20,'Všech dnů, v nichž kraloval Jeroboám, bylo dvamecítma let. I usnul s otci svými, a kraloval Nádab syn jeho místo něho.'),
(1555431,54,11,14,21,'Roboám také syn Šalomounův kraloval nad Judou. V jednom a ve čtyřidcíti letech byl Roboám, když počal kralovati, a sedmnácte let kraloval v Jeruzalémě městě, kteréž vyvolil Hospodin ze všech pokolení Izraelských, aby tam přebývalo jméno jeho. Bylo pak jméno matky jeho Naama Ammonitská.'),
(1555432,54,11,14,22,'Činil také lid Judský to, což zlého jest před Hospodinem, a k zůřivosti ho popudili hříchy svými, kterýmiž hřešili, více nežli otcové jejich všemi věcmi, kteréž činili.'),
(1555433,54,11,14,23,'Nebo i oni vystavěli sobě výsosti a sloupy, i háje na každém pahrbku vysokém a pod každým stromem zeleným.'),
(1555434,54,11,14,24,'Přesto byli ohyzdní sodomáři v zemi té, činíce vedlé všech ohavností pohanských, kteréž byl vyplénil Hospodin před tváří synů Izraelských.'),
(1555435,54,11,14,25,'I stalo se léta pátého království Roboámova, že vytáhl Sesák král Egyptský proti Jeruzalému,'),
(1555436,54,11,14,26,'A pobral poklady domu Hospodinova a poklady domu královského, všecko to pobral. Vzal také všecky pavézy zlaté, kterýchž byl nadělal Šalomoun.'),
(1555437,54,11,14,27,'Místo kterýchž nadělal král Roboám pavéz měděných, a poručil je úředníkům nad drabanty, kteříž ostříhali brány domu královského.'),
(1555438,54,11,14,28,'A když král chodíval do domu Hospodinova, nosili je drabanti, a zase je přinášeli do pokoje drabantů.'),
(1555439,54,11,14,29,'Jiné pak věci Roboámovy, a všecko, což činil, zdaliž není zapsáno v knize o králích Judských.'),
(1555440,54,11,14,30,'Ano i válka, kteráž byla mezi Roboámem a Jeroboámem po všecky dny.'),
(1555441,54,11,14,31,'I usnul Roboám s otci svými, a pochován jest s nimi v městě Davidově. A jméno matky jeho bylo Naama Ammonitská. I kraloval Abiam syn jeho místo něho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555442,54,11,15,1,'Léta pak osmnáctého království Jeroboáma syna Nebatova, kraloval Abiam nad Judou.'),
(1555443,54,11,15,2,'Tři léta kraloval v Jeruzalémě. A jméno matky jeho bylo Maacha, dcera Abissalomova.'),
(1555444,54,11,15,3,'Ten chodil ve všech hříších otce svého, kteréž páchal před oblíčejem jeho; a nebylo srdce jeho celé při Hospodinu Bohu jeho, jako srdce Davida otce jeho.'),
(1555445,54,11,15,4,'A však pro Davida dal jemu Hospodin Bůh jeho svíci v Jeruzalémě, vzbudiv syna jeho po něm, a utvrdiv Jeruzalém,'),
(1555446,54,11,15,5,'Proto že David činil to, což bylo dobrého před Hospodinem, a neuchýlil se od žádné věci z těch, kteréž jemu byl přikázal, po všecky dny života svého, kromě skutku při Uriášovi Hetejském.'),
(1555447,54,11,15,6,'A byl boj mezi Roboámem a Jeroboámem po všecky dny života jeho.'),
(1555448,54,11,15,7,'Jiné pak věci Abiamovy, a všecko což činil, popsáno jest v knize o králích Judských, ano i o boji mezi Abiamem a Jeroboámem.'),
(1555449,54,11,15,8,'A když usnul Abiam s otci svými, pochovali ho v městě Davidově. I kraloval Aza syn jeho místo něho.'),
(1555450,54,11,15,9,'A tak léta dvadcátého Jeroboáma, krále Izraelského, kraloval Aza nad Judou.'),
(1555451,54,11,15,10,'Jedno a čtyřidceti let kraloval v Jeruzalémě. A jméno matky jeho bylo Maacha, dcera Abissalomova.'),
(1555452,54,11,15,11,'I činil Aza, což dobrého bylo před Hospodinem, jako David otec jeho.'),
(1555453,54,11,15,12,'Nebo ohyzdné sodomáře vyplénil z země, a odjal všecky modly, kterýchž nadělali otcové jeho.'),
(1555454,54,11,15,13,'Nadto i Maachu matku svou ssadil, aby nebyla královnou; nebo byla udělala hroznou modlu v háji. Protož podťal Aza modlu tu ohyzdnou, a spálil při potoku Cedron.'),
(1555455,54,11,15,14,'A ačkoli výsosti nebyly zkaženy, a však srdce Azovo bylo celé při Bohu po všecky dny jeho.'),
(1555456,54,11,15,15,'Vnesl také ty věci, kteréž posvěceny byly od otce jeho, i ty věci, kterýchž sám posvětil, do domu Hospodinova, stříbro a zlato i nádoby.'),
(1555457,54,11,15,16,'Pročež byla válka mezi Azou a Bázou, králem Izraelským, po všecky dny jejich.'),
(1555458,54,11,15,17,'Nebo Báza král Izraelský vytáhl proti Judovi, a stavěl Ráma, aby nedal žádnému vyjíti ani jíti k Azovi králi Judskému.'),
(1555459,54,11,15,18,'Ale vzav Aza všecko stříbro i zlato, kteréž pozůstalo v pokladích domu Hospodinova, a v pokladích domu královského, dal je v ruce služebníků svých, a poslal je král Aza k Benadadovi synu Tabremmon, syna Hezion, králi Syrskému, kterýž bydlil v Damašku, řka:'),
(1555460,54,11,15,19,'Smlouva jest mezi mnou a mezi tebou, mezi otcem mým a mezi otcem tvým. Aj, teď posílám tobě dar, stříbro a zlato; jdi, zruš smlouvu svou s Bázou králem Izraelským, ať odtrhne ode mne.'),
(1555461,54,11,15,20,'I uposlechl Benadad krále Azy, a poslav knížata s vojsky svými proti městům Izraelským, dobyl Jon a Dan, též Abelbetmaachy, i všeho Ceneretu, a vší země Neftalím.'),
(1555462,54,11,15,21,'To když uslyšel Báza, přestal stavěti Ráma, a zůstal v Tersa.'),
(1555463,54,11,15,22,'Tedy král Aza provolal po všem Judstvu, žádného nevyměňuje. I pobrali to kamení z Ráma, i dříví jeho, z něhož stavěl Báza, a vystavěl z toho král Aza Gabaa Beniaminovo a Masfa.'),
(1555464,54,11,15,23,'Jiné pak všecky věci Azovy, i všecka síla jeho a cokoli dělal, i jaká města vystavěl, zapsáno jest v knize o králích Judských. Jen že v věku starosti své byl nemocný na nohy.'),
(1555465,54,11,15,24,'I usnul Aza s otci svými, a pochován jest s nimi v městě Davida otce svého. A kraloval místo něho Jozafat syn jeho.'),
(1555466,54,11,15,25,'Nádab pak syn Jeroboámův, počal kralovati nad Izraelem léta druhého Azy, krále Judského, a kraloval nad Izraelem dvě létě.'),
(1555467,54,11,15,26,'A činil to, což zlého jest před očima Hospodinovýma, chodě po cestě otce svého, v hříších jeho, jimiž k hřešení přivodil lid Izraelský.'),
(1555468,54,11,15,27,'I činil mu úklady Báza syn Achiášův z domu Izachar, a porazil ho Báza u Gebbeton, kteréž bylo Filistinských. Nádab zajisté a všickni Izraelští oblehli byli Gebbeton.'),
(1555469,54,11,15,28,'A tak zabil ho Báza léta třetího Azy, krále Judského, a kraloval místo něho.'),
(1555470,54,11,15,29,'I stalo se, když počal kralovati, že zahubil všecken dům Jeroboámův, a nepozůstavil žádné duše z Jeroboáma, až je i vyhladil vedlé řeči Hospodinovy, kterouž byl mluvil skrze služebníka svého Achiáše Silonského,'),
(1555471,54,11,15,30,'Pro hříchy Jeroboámovy, jimiž hřešil, a jimiž k hřešení přivodil lid Izraelský, pro dráždění jeho, kterýmž dráždil Hospodina Boha Izraelského.'),
(1555472,54,11,15,31,'Jiné pak věci Nádabovy a všecko, což činil, zapsáno jest v knize o králích Izraelských.'),
(1555473,54,11,15,32,'Byla tedy válka mezi Azou, a mezi Bázou králem Izraelským, po všecky dny jejich.'),
(1555474,54,11,15,33,'Léta třetího Azy, krále Judského, kraloval Báza syn Achiášův nade vším Izraelem v Tersa za čtyřmecítma let.'),
(1555475,54,11,15,34,'A činil to, což zlého jest před Hospodinem, chodě po cestě Jeroboámově a v hříších jeho, jimiž k hřešení přivodil Izraele.'),
(1555476,54,11,16,1,'Stala se pak řeč Hospodinova k Jéhu, synu Chanani, proti Bázovi, řkoucí:'),
(1555477,54,11,16,2,'Proto že jsem tě vyzdvihl z prachu, a postavil za vůdci lidu mého Izraelského, ty jsi pak chodil po cestě Jeroboámově, a přivedls k hřešení lid můj Izraelský, aby mne popouzeli hříchy svými:'),
(1555478,54,11,16,3,'Aj, já vyhladím potomky Bázovy a potomky domu jeho, a učiním domu tvému, jako domu Jeroboáma, syna Nebatova.'),
(1555479,54,11,16,4,'Toho, kdož z rodiny Bázovy umře v městě, psi žráti budou, a kdož z nich umře na poli, ptáci nebeští jísti budou.'),
(1555480,54,11,16,5,'Jiné pak věci Bázovy a všecko, což činil, i síla jeho, o tom zapsáno jest v knize o králích Izraelských.'),
(1555481,54,11,16,6,'Když pak usnul Báza s otci svými, pochován jest v Tersa, a Ela syn jeho kraloval místo něho.'),
(1555482,54,11,16,7,'A tak skrze Jéhu syna Chanani, proroka, stala se řeč Hospodinova proti Bázovi a proti domu jeho, i proti všemu zlému, kteréž činil před oblíčejem Hospodinovým, popouzeje ho dílem rukou svých, že má býti podobný domu Jeroboámovu, a proto že jej zabil.'),
(1555483,54,11,16,8,'Léta dvadcátého šestého Azy, krále Judského, kraloval Ela syn Bázův nad Izraelem v Tersa dvě létě.'),
(1555484,54,11,16,9,'I zprotivil se jemu služebník jeho Zamri, hejtman nad polovicí vozů, když on v Tersa kvasil a opilý byl v domě Arsy, vládaře města Tersa.'),
(1555485,54,11,16,10,'V tom Zamri přišed, ranil ho, a zabil jej léta dvadcátého sedmého Azy krále Judského, a kraloval místo něho.'),
(1555486,54,11,16,11,'Když pak kraloval a seděl na stolici jeho, pobil všecken dům Bázův, i příbuzné jeho, i přátely jeho, nepozůstaviv z něho ani močícího na stěnu.'),
(1555487,54,11,16,12,'A tak vyhladil Zamri všecken dům Bázův vedlé řeči Hospodinovy, kterouž byl mluvil proti Bázovi skrze Jéhu proroka,'),
(1555488,54,11,16,13,'Pro všecky hříchy Bázovy, i hříchy Ela syna jeho, kteříž hřešili, i v hříchy uvodili Izraele, popouzejíce Hospodina Boha Izraelského marnostmi svými.'),
(1555489,54,11,16,14,'Jiné pak věci Ela a všecko, což činil, vypsáno jest v knize o králích Izraelských.'),
(1555490,54,11,16,15,'Léta dvadcátého sedmého Azy, krále Judského, kraloval Zamri v Tersa sedm dní, když lid vojenský ležel proti Gebbeton Filistinských.'),
(1555491,54,11,16,16,'Nebo uslyšev lid, kterýž byl v ležení,takové věci, že by se Zamri zprotivil a že krále zabil, tedy všecken Izrael ustanovili sobě krále Amri, hejtmana nad vojskem Izraelským toho času v vojště.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555492,54,11,16,17,'Protož táhl Amri a s ním všecken Izrael od Gebbeton, a oblehli Tersu.'),
(1555493,54,11,16,18,'A když viděl Zamri, že již město jest vzato, všed na palác domu královského, zapálil nad sebou dům královský, i umřel,'),
(1555494,54,11,16,19,'Pro hříchy své, kterýmiž hřešil, čině, což zlého jest před oblíčejem Hospodinovým, a chodě po cestě Jeroboámově a v hříších jeho, kteréž páchal, přivozuje k hřešení lid Izraelský.'),
(1555495,54,11,16,20,'Jiné pak věci Zamri i jeho úkladové, kteréž činil, zapsáni jsou v knize o králích Izraelských.'),
(1555496,54,11,16,21,'Tedy rozdělil se lid Izraelský na dvé. Polovice lidu postoupilo po Tebni synu Ginet, aby ho učinili králem, a druhá polovice postoupila po Amri.'),
(1555497,54,11,16,22,'Ale přemohl lid, kterýž postoupil po Amri, lid ten, kterýž postoupil po Tebni synu Ginet. I umřel Tebni, a kraloval Amri.'),
(1555498,54,11,16,23,'Léta třidcátého prvního Azy, krále Judského, kraloval Amri nad Izraelem dvanácte let. V Tersa kraloval šest let.'),
(1555499,54,11,16,24,'I koupil horu Someron od Semera za dvě hřivny stříbra, a když vystavěl tu horu, nazval jméno města toho, kteréž vzdělal, od jména Semery, pána té hory, totiž Samaří.'),
(1555500,54,11,16,25,'Činil pak Amri to, což jest zlého před oblíčejem Hospodinovým; nýbrž horší věci činil, než kdo ze všech, kteříž před ním byli.'),
(1555501,54,11,16,26,'Nebo chodil po všeliké cestě Jeroboáma syna Nebatova, a ve všech hříších jeho, kterýmiž přivodil k hřešení Izraele, popouzeje Hospodina Boha Izraelského marnostmi svými.'),
(1555502,54,11,16,27,'Jiné pak věci Amri i všecko, což činil, i síla jeho, kterouž prokazoval, o tom zapsáno jest v knize o králích Izraelských.'),
(1555503,54,11,16,28,'I usnul Amri s otci svými, a pochován jest v Samaří, a kraloval místo něho Achab syn jeho.'),
(1555504,54,11,16,29,'Achab tedy syn Amri kraloval nad Izraelem léta třidcátého osmého Azy, krále Judského, a kraloval Achab syn Amri nad Izraelem v Samaří dvamecítma let.'),
(1555505,54,11,16,30,'I činil Achab syn Amri před oblíčejem Hospodinovým horší věci než kdo ze všech, kteříž před ním byli.'),
(1555506,54,11,16,31,'V tom stalo se, (nebo málo mu to bylo, že chodil v hříších Jeroboáma syna Nebatova), že sobě pojal ženu Jezábel dceru Etbál, krále Sidonského, a odšed, sloužil Bálovi a klaněl se jemu.'),
(1555507,54,11,16,32,'A vzdělal oltář Bálovi v chrámě Bálově, kterýž byl ustavěl v Samaří.'),
(1555508,54,11,16,33,'Udělal také Achab i háj, a tak přičinil toho, čím by popouzel Hospodina Boha Izraelského, nade všecky jiné krále Izraelské, kteříž byli před ním.'),
(1555509,54,11,16,34,'Za dnů jeho Hiel Bethelský vystavěl Jericho. V Abiramovi prvorozeném svém založil je, a v Segubovi nejmladším svém postavil brány jeho, vedlé řeči Hospodinovy, kterouž byl mluvil skrze Jozue syna Nun.'),
(1555510,54,11,17,1,'Tedy Eliáš Tesbitský, obyvatel Galádský, mluvil k Achabovi: Živť jest Hospodin Bůh Izraelský, před jehož oblíčejem stojím, že nebude těchto let rosy ani deště, jediné vedlé řeči mé.'),
(1555511,54,11,17,2,'I stalo se slovo Hospodinovo k němu, řkoucí:'),
(1555512,54,11,17,3,'Odejdi odsud a obrať se k východu, a skrej se u potoka Karit, kterýž jest naproti Jordánu.'),
(1555513,54,11,17,4,'A budeš z toho potoka píti, krkavcům pak jsem přikázal, aby tě tam krmili.'),
(1555514,54,11,17,5,'Kterýž odšed, učinil, jakž mu přikázal Hospodin. Nebo odšed, usadil se při potoku Karit, kterýž byl proti Jordánu.'),
(1555515,54,11,17,6,'A krkavci přinášeli jemu chléb a maso každého jitra, též chléb a maso každého večera, a z potoka pil.'),
(1555516,54,11,17,7,'Tedy po přeběhnutí dnů některých vysechl ten potok, nebo nebylo žádného deště v té zemi.'),
(1555517,54,11,17,8,'I stalo se slovo Hospodinovo k němu, řkoucí:'),
(1555518,54,11,17,9,'Vstaň a jdi do Sarepty Sidonské, a buď tam. Aj, přikázal jsem ženě vdově, aby tě živila.'),
(1555519,54,11,17,10,'Kterýž vstav, šel do Sarepty, a přišel k bráně města, a aj, žena vdova sbírala tu dříví. A zavolav jí, řekl: Medle, přines mi trochu vody v nádobě, abych se napil.'),
(1555520,54,11,17,11,'A když šla, aby přinesla, zavolal jí zase a řekl: Medle, přines mi také kousek chleba v ruce své.'),
(1555521,54,11,17,12,'I odpověděla: Živť jest Hospodin Bůh tvůj, žeť nemám žádného chleba, ani podpopelného, kromě hrsti mouky v kbelíku a maličko oleje v nádobce, a aj, sbírám dvě dřevě, abych šla a připravila to sobě a synu svému, abychom snědouce to, za tím zemříti musili.'),
(1555522,54,11,17,13,'I řekl jí Eliáš: Neboj se. Jdi a učiň, jakž jsi řekla, a však udělej mi prvé z toho malý chléb podpopelný a přines mi; potom sobě a synu svému uděláš.'),
(1555523,54,11,17,14,'Neboť toto praví Hospodin Bůh Izraelský: Mouka z kbelíka toho nebude strávena, aniž oleje v nádobce té ubude až do toho dne, když dá Hospodin déšť na zemi.'),
(1555524,54,11,17,15,'I šla a učinila vedlé řeči Eliášovy, a jedla ona i on i čeled její až do těch dní.'),
(1555525,54,11,17,16,'Z kbelíka toho mouka nebyla strávena, aniž oleje v nádobce ubylo, vedlé řeči Hospodinovy, kterouž mluvil skrze Eliáše.'),
(1555526,54,11,17,17,'A když to přeběhlo, stalo se, že se roznemohl syn ženy, paní toho domu, a byla nemoc jeho velmi těžká, tak že nezůstalo v něm dýchání.'),
(1555527,54,11,17,18,'Protož řekla Eliášovi: Co mně a tobě, muži Boží? Přišel jsi ke mně, abys mi připomenul nepravost mou, a umořil syna mého?'),
(1555528,54,11,17,19,'Kterýž odpověděl jí: Dej sem syna svého. A vzav ho z lůna jejího, vnesl jej na síň, kdež sám přebýval, a položil ho na lůžko své.'),
(1555529,54,11,17,20,'Tedy volal k Hospodinu a řekl: Hospodine Bože můj, také-liž s tou vdovou, u kteréž pohostinu jsem, tak zle nakládáš, že jsi umořil syna jejího?'),
(1555530,54,11,17,21,'A roztáh se nad dítětem po třikrát, zvolal k Hospodinu a řekl: Hospodine Bože můj, prosím, nechť se navrátí duše dítěte tohoto do vnitřností jeho.'),
(1555531,54,11,17,22,'I vyslyšel Hospodin hlas Eliášův, a navrátila se duše dítěte do vnitřností jeho, i ožilo.'),
(1555532,54,11,17,23,'A vzav Eliáš dítě, snesl je z síně do domu, a dal je matce jeho. I řekl Eliáš: Pohleď, syn tvůj živ jest.'),
(1555533,54,11,17,24,'Tedy řekla žena Eliášovi: Jižť jsem nyní poznala, že jsi muž Boží, a že řeč Hospodinova v ústech tvých jest pravá.'),
(1555534,54,11,18,1,'Potom po mnohých dnech, po třetím tom létě, stalo se slovo Hospodinovo k Eliášovi, řkoucí: Jdi, ukaž se Achabovi, neboť dám déšť na zemi.'),
(1555535,54,11,18,2,'Odšel tedy Eliáš, aby se ukázal Achabovi. Byl pak hlad veliký v Samaří.'),
(1555536,54,11,18,3,'I povolal Achab Abdiáše, kterýž byl představen domu jeho. (Abdiáš pak bál se Hospodina velmi.'),
(1555537,54,11,18,4,'Nebo když Jezábel mordovala proroky Hospodinovy, vzal Abdiáš sto proroků a skryl je po padesáti v jeskyni, a krmil je chlebem a vodou.)'),
(1555538,54,11,18,5,'A řekl Achab Abdiášovi: Jdi skrze tu zemi ke všechněm studnicím vod, a ke všechněm potokům, zdali bychom kde nalezli trávu, abychom živé zachovali koně a mezky, a nezmořili dobytka.'),
(1555539,54,11,18,6,'I rozdělili sobě zemi, kterouž by prošli. Achab šel jednou cestou sám, Abdiáš také šel cestou druhou sám.'),
(1555540,54,11,18,7,'A když Abdiáš byl na cestě, aj, Eliáš potkal se s ním. Kterýž když ho poznal, padl na tvář svou a řekl: Nejsi-liž ty, pane můj, Eliáš?'),
(1555541,54,11,18,8,'Odpověděl jemu: Jsem. Jdi, pověz pánu svému: Aj, Eliáš přišel.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555542,54,11,18,9,'Jemuž řekl: Což jsem zhřešil, že služebníka svého vydati chceš v ruku Achabovu, aby mne zamordoval?'),
(1555543,54,11,18,10,'Živť jest Hospodin Bůh tvůj, žeť není národu ani království, kamž by neposlal pán můj hledati tě, a když řekli, že tebe není, přísahy požádal od království a národu, že tě nemohou nalezti.'),
(1555544,54,11,18,11,'A ty nyní pravíš: Jdi, pověz pánu svému: Aj, Eliáš přišel.'),
(1555545,54,11,18,12,'I stalo by se, že jakž bych odšel od tebe, tedy duch Hospodinův zanesl by tě nevím kam, já pak jda, oznámil bych Achabovi, a když by tě nenalezl, zabil by mne. Služebník zajisté tvůj bojí se Hospodina od mladosti své.'),
(1555546,54,11,18,13,'Zdaliž není oznámeno pánu mému, co jsem učinil, když Jezábel mordovala proroky Hospodinovy, že jsem skryl z proroků Hospodinových sto mužů, po padesáti mužích v jeskyni, a krmil jsem je chlebem a vodou?'),
(1555547,54,11,18,14,'Ty pak nyní pravíš: Jdi, pověz pánu svému: Aj, Eliáš přišel. A zamordujeť mne.'),
(1555548,54,11,18,15,'Odpověděl Eliáš: Živť jest Hospodin zástupů, před jehož oblíčejem stojím, žeť se jemu dnes ukáži.'),
(1555549,54,11,18,16,'A tak šel Abdiáš vstříc Achabovi, a oznámil jemu. Pročež šel i Achab v cestu Eliášovi.'),
(1555550,54,11,18,17,'A když uzřel Achab Eliáše, řekl Achab k němu: Zdaliž ty nejsi ten, kterýž kormoutíš lid Izraelský?'),
(1555551,54,11,18,18,'Kterýž odpověděl: Jáť nekormoutím lidu Izraelského, ale ty a dům otce tvého, když opouštíte přikázaní Hospodinova a následujete Bálů.'),
(1555552,54,11,18,19,'Protož nyní pošli a shromažď ke mně všecken lid Izraelský na horu Karmel, a proroků Bálových čtyři sta a padesáte, i proroků toho háje čtyři sta, kteříž jedí z stolu Jezábel.'),
(1555553,54,11,18,20,'Obeslal tedy Achab všecky syny Izraelské, a shromáždil ty proroky na horu Karmel.'),
(1555554,54,11,18,21,'A přistoupiv Eliáš ke všemu lidu, řekl: I dokudž kulhati budete na obě straně? Jestližeť jest Hospodin Bohem, následujtež ho; pakli jest Bál, jdětež za ním. A neodpověděl jemu lid žádného slova.'),
(1555555,54,11,18,22,'Opět řekl Eliáš lidu: Já sám toliko pozůstal jsem prorok Hospodinův, proroků pak Bálových jest čtyři sta a padesáte mužů.'),
(1555556,54,11,18,23,'Nechť jsou nám dáni dva volkové, a ať vyberou sobě volka jednoho, kteréhož nechť rozsekají na kusy a vkladou na dříví, ale ohně ať nepodkládají. Jáť také připravím volka druhého, kteréhož vložím na dříví, a ohně nepodložím.'),
(1555557,54,11,18,24,'Tedy vzývejte jméno bohů vašich, já pak vzývati budu jméno Hospodinovo, a budeť to, že Bůh, kterýž se ohlásí skrze oheň, ten jest Bůh. A odpověděl všecken lid, řka: Dobráť jest řeč tato.'),
(1555558,54,11,18,25,'I řekl Eliáš prorokům Bálovým: Vybeřte sobě volka jednoho a připravte ho nejprvé, poněvadž jest vás více, a vzývejte jméno bohů vašich, ale ohně nepodkládejte.'),
(1555559,54,11,18,26,'A tak vzali volka, kteréhož jim dal, a připravili a vzývali jméno Bálovo od jitra až do poledne, říkajíce: Ó Báli, uslyš nás. Ale nebylo hlasu, ani kdo by odpověděl. I skákali u oltáře, kterýž byli udělali.'),
(1555560,54,11,18,27,'Když pak bylo poledne, posmíval se jim Eliáš a řekl: Křičte vysokým hlasem, poněvadž bůh jest. Neb snad rozmlouvání má, neb jinou práci, neb jest na cestě, anebť spí, ať procítí.'),
(1555561,54,11,18,28,'Takž křičeli hlasem velikým, a bodli se vedlé obyčeje svého nožíky a špicemi, tak až se krví polívali.'),
(1555562,54,11,18,29,'I stalo se, když již bylo s poledne, že prorokovali až dotud, když se obětuje obět suchá, ale nebylo žádného se ohlášení, ani kdo by odpověděl, ani kdo by vyslyšel.'),
(1555563,54,11,18,30,'Zatím řekl Eliáš všemu lidu: Přistuptež ke mně. I přistoupil všecken lid k němu. Tedy opravil oltář Hospodinův, kterýž byl zbořený.'),
(1555564,54,11,18,31,'Nebo vzal Eliáš dvanácte kamenů, (vedlé počtu pokolení synů Jákobových, k němuž se byla stala řeč Hospodinova, že Izrael bude jméno jeho),'),
(1555565,54,11,18,32,'A vzdělal z těch kamenů oltář ve jménu Hospodinovu; udělal také struhu vůkol oltáře zšíří, co by mohl dvě míry obilé vsíti.'),
(1555566,54,11,18,33,'Narovnal i dříví, a rozsekav volka na kusy, vkladl na dříví.'),
(1555567,54,11,18,34,'A řekl: Naplňte čtyři stoudve vodou, a vylíte na obět zápalnou i na dříví. Řekl opět: Učiňtež to po druhé. I učinili po druhé.Řekl ještě: Po třetí učiňte. I učinili po třetí,'),
(1555568,54,11,18,35,'Tak že tekly vody okolo oltáře; také i struhu naplnila voda.'),
(1555569,54,11,18,36,'Stalo se pak, když se obětuje obět suchá, přistoupil Eliáš prorok a řekl: Hospodine Bože Abrahamův, Izákův a Izraelův, nechť dnes poznají, že jsi ty Bůh v Izraeli, a já služebník tvůj, a že jsem vedlé slova tvého činil všecky věci tyto.'),
(1555570,54,11,18,37,'Vyslyš mne, Hospodine, vyslyš mne, aťby poznal lid tento, že jsi ty, Hospodine, Bohem, když bys obrátil srdce jejich zase.'),
(1555571,54,11,18,38,'V tom spadl oheň Hospodinův, a spálil obět zápalnou, dříví i kamení i prsť; též vodu, kteráž byla v struze, vypil.'),
(1555572,54,11,18,39,'Což když uzřel všecken ten lid, padli na tváři své a řekli: Hospodinť jest Bohem, Hospodin jest Bohem.'),
(1555573,54,11,18,40,'I řekl jim Eliáš: Zjímejte ty proroky Bálovy, žádný ať z nich neujde. I zjímali je. Kteréž svedl Eliáš ku potoku Císon, a tam je zmordoval.'),
(1555574,54,11,18,41,'Tedy řekl Eliáš Achabovi: Jdi, pojez a napí se, nebo aj, zvuk velikého deště.'),
(1555575,54,11,18,42,'I jel Achab, aby pojedl a napil se. Eliáš pak vstoupil na vrch Karmele, a rozprostřel se na zemi a sklonil tvář svou k kolenům svým.'),
(1555576,54,11,18,43,'Potom řekl mládenci svému: Vystup nyní, a pohleď tam k moři. Kterýž vystoupiv, pohleděl a řekl: Nic není. Řekl opět: Vrať se po sedmkrát.'),
(1555577,54,11,18,44,'I stalo se po sedmé, řekl: Aj, oblak maličký jako dlaň člověčí vystupuje z moře. Ještě řekl: Jdi, rci Achabovi: Zapřáhej a jeď, aby tě nezastihl déšť.'),
(1555578,54,11,18,45,'Stalo se mezi tím, když se nebesa zamračila oblakem a větrem, odkudž byl déšť veliký, že jel Achab a přišel do Jezreel.'),
(1555579,54,11,18,46,'Ruka pak Hospodinova byla s Eliášem, tak že přepásav bedra svá, běžel před Achabem, až přišel do Jezreel.'),
(1555580,54,11,19,1,'Tedy oznámil Achab Jezábel všecko to, což učinil Eliáš, a že naprosto všecky proroky její pobil mečem.'),
(1555581,54,11,19,2,'A protož poslala Jezábel posla k Eliášovi, řkuci: Toto ať mi učiní bohové a toto přidadí, jestliže v tuto hodinu zítra neučiním tobě, jako ty kterému z nich.'),
(1555582,54,11,19,3,'Což když zvěděl, vstana, odšel pro zachování života svého, a přišel do Bersabé, jenž jest v Judstvu, kdež nechal mládence svého.'),
(1555583,54,11,19,4,'Sám pak šel předce po poušti cestou dne jednoho, a přišed, usadil se pod jedním jalovcem, a žádal sobě smrti a řekl: Jižť jest dosti, ó Hospodine, vezmi duši mou, nebť nejsem lepší otců svých.'),
(1555584,54,11,19,5,'I lehl a usnul pod tím jalovcem. A aj, v touž chvíli anděl dotekl se ho a řekl jemu: Vstaň, pojez.'),
(1555585,54,11,19,6,'A když pohleděl vůkol, a aj, u hlavy jeho chléb na uhlí pečený a číše vody. I pojedl a napil se, a lehl zase.'),
(1555586,54,11,19,7,'Opět vrátiv se anděl Hospodinův po druhé, dotekl se ho a řekl: Vstaň, pojez, nebo velmi dlouhou máš cestu před sebou.'),
(1555587,54,11,19,8,'A vstav, jedl a pil, a šel v síle pokrmu toho čtyřidceti dní a čtyřidceti nocí, až na horu Boží Oréb.'),
(1555588,54,11,19,9,'Kdežto všed do jakési jeskyně, nocoval tam. A aj, řeč Hospodinova k němu, a řekl jemu: Co tu děláš, Eliáši?'),
(1555589,54,11,19,10,'Kterýž odpověděl: Velice jsem horlil pro Hospodina Boha zástupů; nebo opustili smlouvu tvou synové Izraelští, oltáře tvé zbořili a proroky tvé zmordovali mečem. I zůstal jsem já sám, teď pak hledají života mého, aby mi jej odjali.'),
(1555590,54,11,19,11,'Řekl Bůh: Vyjdi a stůj na hoře před Hospodinem. A aj, Hospodin šel tudy, a vítr veliký a silný, podvracující hory a rozrážející skály před Hospodinem, ale nebyl v tom větru Hospodin. Za tím pak větrem země třesení, ale nebyl v tom třesení Hospodin.'),
(1555591,54,11,19,12,'A za třesením oheň, ale nebyl v ohni Hospodin. A za ohněm hlas tichý a temný.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555592,54,11,19,13,'Což když uslyšel Eliáš, zavinul tvář svou pláštěm svým, a vyšed, stál u dveří jeskyně, a aj, hlas k němu, řkoucí: Co tu děláš, Eliáši?'),
(1555593,54,11,19,14,'Kterýž odpověděl: Náramně horlil jsem pro Hospodina Boha zástupů; nebo opustili smlouvu tvou synové Izraelští, oltáře tvé zbořili, a proroky tvé pomordovali mečem. I zůstal jsem já sám, teď pak hledají života mého, aby mi jej odjali.'),
(1555594,54,11,19,15,'Ale Hospodin řekl jemu: Jdi, navrať se cestou svou k Damašské poušti, kdežto přijda, pomažeš Hazaele za krále nad Syrií.'),
(1555595,54,11,19,16,'Jéhu také syna Namsi pomažeš za krále nad Izraelem, a Elizea syna Safatova z Abelmehula pomažeš za proroka místo sebe.'),
(1555596,54,11,19,17,'I stane se, že toho, kdož by ušel meče Hazaelova, zamorduje Jéhu, a toho, kdož by ušel meče Jéhu, zamorduje Elizeus.'),
(1555597,54,11,19,18,'Zachovalť jsem pak v Izraeli sedm tisíců, jichžto všech kolena neskláněla se Bálovi, a jichžto všech ústa nelíbala ho.'),
(1555598,54,11,19,19,'A tak odšed odtud, nalezl Elizea syna Safatova, an oře, a dvanáctero spřežení před ním, sám také byl při dvanáctém. A jda mimo něj Eliáš, uvrhl plášť svůj na něj.'),
(1555599,54,11,19,20,'Kterýž zanechav volů, běžel za Eliášem a řekl: Prosím, nechť políbím otce svého a matky své, i půjdu za tebou. Jemuž řekl: Jdi, vrať se zase, nebo vidíš, coť jsem učinil.'),
(1555600,54,11,19,21,'Navrátil se tedy od něho, a vzav pár volů, zabil je a dřívím z pluhu uvařil maso jejich, kteréž dal lidu, i jedli. A vstav, šel za Eliášem a přisluhoval jemu.'),
(1555601,54,11,20,1,'Tedy Benadad král Syrský, shromáždiv všecka vojska svá, a maje s sebou třidceti a dva krále, též koně i vozy, vytáhl a oblehl Samaří a dobýval ho.'),
(1555602,54,11,20,2,'I poslal posly k Achabovi králi Izraelskému do města,'),
(1555603,54,11,20,3,'A vzkázal jemu: Takto praví Benadad: Stříbro tvé a zlato tvé mé jest, též ženy tvé i synové tvoji nejzdárnější moji jsou.'),
(1555604,54,11,20,4,'I odpověděl král Izraelský a řekl: Vedlé řeči tvé, pane můj králi, tvůj jsem i všecko, což mám.'),
(1555605,54,11,20,5,'Opět navrátivše se poslové, řekli: Takto praví Benadad: Poslal jsem k tobě, aťby řekli: Stříbro své a zlato své, ženy své i syny své dáš mi.'),
(1555606,54,11,20,6,'Ale však o tomto čase zítra pošli služebníky své k tobě, aby přehledali dům tvůj i domy služebníků tvých, a oniť všecko, cožkoli máš nejlepšího, vezmouce v ruce své, poberou.'),
(1555607,54,11,20,7,'A tak povolav král Izraelský všech starších země té, řekl: Posuďte medle,a vizte, jakť ten zlého hledá; nebo poslal ke mně pro ženy mé a pro syny mé, též pro stříbro mé i pro zlato mé, a neodepřel jsem jemu.'),
(1555608,54,11,20,8,'I řekli jemu všickni starší a všecken lid: Neposlouchejž ho, ani mu povoluj.'),
(1555609,54,11,20,9,'Protož odpověděl poslům Benadadovým: Povězte pánu mému králi: Všecko to, o čež jsi poslal k služebníku svému prvé, učiním, ale této věci učiniti nemohu. Takž odešli poslové, a donesli mu tu odpověd.'),
(1555610,54,11,20,10,'Ještě poslal k němu Benadad a řekl: Toto ať mi učiní bohové a toto ať přidadí, dostane-li se prachu Samařského do hrstí všeho lidu, kterýž jest se mnou.'),
(1555611,54,11,20,11,'Zase odpověděl král Izraelský a řekl: Povězte, ať se nechlubí ten, kterýž se strojí do zbroje, jako ten, kterýž svláčí zbroj.'),
(1555612,54,11,20,12,'I stalo se, když uslyšel tu řeč, (nebo pil on i králové v staních), že řekl služebníkům svým: Přitrhněte. I přitrhli k městu.'),
(1555613,54,11,20,13,'A hle, prorok nějaký přišed k Achabovi králi Izraelskému, řekl: Toto praví Hospodin: Zdaliž jsi neviděl všeho množství tohoto velikého? Hle, já dám je dnes v ruku tvou, abys poznal, že já jsem Hospodin.'),
(1555614,54,11,20,14,'A když řekl Achab: Skrze koho? odpověděl on: Tak praví Hospodin: Skrze služebníky knížat krajů. Řekl ještě: Kdo svede tu bitvu? Odpověděl: Ty.'),
(1555615,54,11,20,15,'A protož sečtl služebníky knížat krajů, jichž bylo dvě stě třidceti a dva; po nich sečtl i všecken lid všech synů Izraelských, sedm tisíců.'),
(1555616,54,11,20,16,'I vytáhli o poledni. Benadad pak pil a ožral se v staních, on i třidceti a dva králové pomocníci jeho.'),
(1555617,54,11,20,17,'A tak vytáhli služebníci knížat krajů nejprvé. I poslal Benadad, (když mu pověděli, řkouce: Muži vytáhli z Samaří),'),
(1555618,54,11,20,18,'A řekl: Buď že vytáhli o pokoj, zjímejte je živé, buď že k bitvě vytáhli, zjímejte je živé.'),
(1555619,54,11,20,19,'Tak, pravím, vytáhli z města ti služebníci knížat krajů, a vojsko za nimi táhlo.'),
(1555620,54,11,20,20,'A porazili jeden každý muže svého, tak že utíkali Syrští, Izraelští pak honili je. Ale Benadad král Syrský utekl na koni s jízdnými.'),
(1555621,54,11,20,21,'Potom vytáhl král Izraelský, a pobil koně i vozy zkazil, a tak porazil Syrské ranou velikou.'),
(1555622,54,11,20,22,'Opět přišel prorok ten k králi Izraelskému, a řekl jemu: Jdiž, zmužile se měj a věz i viz, co bys měl činiti; nebo zase po roce král Syrský vytáhne proti tobě.'),
(1555623,54,11,20,23,'Tedy služebníci krále Syrského řekli jemu: Bohové hor jsouť bohové jejich, protož nás přemohli; ale bojujme proti nim na rovinách, zvíš, nepřemůžeme-li jich.'),
(1555624,54,11,20,24,'Protož učiň toto: Odbuď těch králů, jednoho každého z místa jeho, a postav vývody místo nich.'),
(1555625,54,11,20,25,'Ty pak sečti sobě vojsko z svých jako vojsko oněch, kteříž padli, a koně jako ony koně, a vozy jako ony vozy; i budeme bojovati proti nim na rovinách, a zvíš, nepřemůžeme-liť jich. I uposlechl hlasu jejich a učinil tak.'),
(1555626,54,11,20,26,'I stalo se po roce, že sečtl Benadad Syrské a vytáhl do Afeku, aby bojoval proti Izraelovi.'),
(1555627,54,11,20,27,'Izraelští také sečteni jsou, a opatřivše se stravou, vytáhli jim v cestu. I položili se Izraelští proti nim jako dvě malá stáda koz, Syrští pak přikryli tu zemi.'),
(1555628,54,11,20,28,'V tom přišel týž muž Boží, a mluvil králi Izraelskému a řekl: Takto praví Hospodin: Proto že pravili Syrští: Bohem hor jest Hospodin a ne Bohem rovin, dám všecko množství toto veliké v ruce tvé, abyste věděli, že já jsem Hospodin.'),
(1555629,54,11,20,29,'A tak leželi oni proti nim za sedm dní; i stalo se dne sedmého, že svedli bitvu. I porazili synové Izraelští z Syrských sto tisíc pěších dne jednoho.'),
(1555630,54,11,20,30,'Jiní pak zutíkali do města Afeku, kdež padla zed na dvadceti a sedm tisíc mužů, kteříž byli pozůstali. Ale Benadad utíkaje, přišel do města, do nejtajnějšího pokoje.'),
(1555631,54,11,20,31,'I řekli jemu služebníci jeho: Aj, toto jsme slýchali, že králové domu Izraelského jsou králové milosrdní. Medle, nechť vezmeme pytle na bedra svá a provazy na hlavy své, a vejdeme k králi Izraelskému; snad při životu zachová tebe.'),
(1555632,54,11,20,32,'A protož přepásali pytli bedra svá, a provazy vzali na hlavy své, a přišli k králi Izraelskému a řekli: Služebník tvůj Benadad praví: Prosím, nechť jsem zachován při životu. Kterýž řekl: Což jest ještě živ? Bratr tě můj.'),
(1555633,54,11,20,33,'Muži pak ti soudíc to za dobré znamení, rychle chytili ta slova od něho a řekli: Bratrť jest tvůj Benadad. I řekl: Jděte, přiveďte ho sem. Takž vyšel k němu Benadad, i kázal mu vstoupiti na svůj vůz.'),
(1555634,54,11,20,34,'Tedy řekl jemu Benadad: Města, kteráž otec můj pobral otci tvému, navrátímť, a ulice zděláš sobě v Damašku, jako byl udělal otec můj v Samaří. I odpověděl: Já vedlé smlouvy této propustím tě. A tak učinil s ním smlouvu a propustil ho.'),
(1555635,54,11,20,35,'Muž pak nějaký z synů prorockých řekl bližnímu svému z rozkazu Božího: Ubí mne medle. Ale muž ten nechtěl ho bíti.'),
(1555636,54,11,20,36,'Kterýž řekl jemu: Proto že jsi neuposlechl hlasu Hospodinova, aj teď, když půjdeš ode mne, udáví tě lev. A když šel od něho, trefil na něj lev a udávil ho.'),
(1555637,54,11,20,37,'Opět nalezl muže druhého, jemuž řekl: Medle, ubí mne. Kterýž ubil ho velice a ranil.'),
(1555638,54,11,20,38,'I odšed prorok ten, postavil se králi v cestě, a změnil se, zavěsiv sobě oči.'),
(1555639,54,11,20,39,'A když král pomíjel, zvolal na něj a řekl: Služebník tvůj vyšel do bitvy, a hle, jeden odšed, přivedl ke mně muže a řekl: Ostříhej toho muže, jestliže se pak ztratí, budeť život tvůj za život jeho, aneb centnéř stříbra položíš.'),
(1555640,54,11,20,40,'V tom když služebník tvůj toho i onoho hleděl, tožť se ztratil. Pročež řekl jemu král Izraelský: Takový buď soud tvůj, jakýž jsi sám vypověděl.'),
(1555641,54,11,20,41,'Tedy rychle odhradil tvář svou, a poznal ho král Izraelský, že by z proroků byl.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555642,54,11,20,42,'I řekl jemu: Takto praví Hospodin: Poněvadž jsi z ruky pustil muže k smrti odsouzeného, budeť život tvůj za život jeho, a lid tvůj za lid jeho.'),
(1555643,54,11,20,43,'Protož odjel král Izraelský do domu svého, smutný jsa a hněvaje se, a přišel do Samaří.'),
(1555644,54,11,21,1,'Stalo se pak po těch věcech, měl Nábot Jezreelský vinici, kteráž byla v Jezreel podlé paláce Achaba krále Samařského.'),
(1555645,54,11,21,2,'I mluvil Achab k Nábotovi, řka: Dej mi vinici svou, ať ji mám místo zahrady k zelinám, poněvadž jest blízko podlé domu mého, a dámť za ni vinici lepší, než ta jest, aneb jestližeť se vidí, dámť stříbra cenu její.'),
(1555646,54,11,21,3,'Odpověděl Nábot Achabovi: Nedejž mi toho Hospodin, abych měl dáti dědictví otců mých tobě.'),
(1555647,54,11,21,4,'Tedy přišel Achab do domu svého, smutný jsa a hněvaje se pro řeč, kterouž mluvil jemu Nábot Jezreelský, řka: Nedám tobě dědictví otců svých. I lehl na lůžko své, a odvrátiv tvář svou, ani chleba nejedl.'),
(1555648,54,11,21,5,'V tom přišedši k němu Jezábel žena jeho, řekla jemu: Proč tak smutný jest duch tvůj, že ani nejíš chleba?'),
(1555649,54,11,21,6,'Kterýž odpověděl jí: Proto že jsem mluvil s Nábotem Jezreelským, a řekl jsem jemu: Dej mi vinici svou za peníze, aneb jestliže raději chceš, dámť jinou vinici za ni. On pak odpověděl: Nedám tobě své vinice.'),
(1555650,54,11,21,7,'I řekla mu Jezábel žena jeho: Takliž bys ty nyní spravoval království Izraelské? Vstaň, pojez chleba a buď dobré mysli, já tobě dám vinici Nábota Jezreelského.'),
(1555651,54,11,21,8,'Zatím napsala list jménem Achabovým, kterýž zapečetila jeho pečetí, a poslala ten list k starším a předním města jeho, spoluobyvatelům Nábotovým.'),
(1555652,54,11,21,9,'Napsala pak v tom listu takto: Vyhlaste půst, a posaďte Nábota mezi předními z lidu,'),
(1555653,54,11,21,10,'A postavte dva muže nešlechetné proti němu, kteříž by svědčili na něj, řkouce: Zlořečil jsi Bohu a králi. Potom vyveďte ho a ukamenujte jej, ať umře.'),
(1555654,54,11,21,11,'Učinili tedy muži města toho, starší a přední, kteříž bydlili v městě jeho, jakž rozkázala jim Jezábel, tak jakž psáno bylo v listu, kterýž jim byla poslala.'),
(1555655,54,11,21,12,'Vyhlásili půst, a posadili Nábota mezi předními z lidu.'),
(1555656,54,11,21,13,'Potom přišli ti dva muži nešlechetní, a posadivše se naproti němu, svědčili proti němu muži ti nešlechetní, proti Nábotovi před lidem, řkouce: Zlořečil Nábot Bohu a králi. I vyvedli ho za město a kamenovali jej, až umřel.'),
(1555657,54,11,21,14,'A poslali k Jezábel, řkouce: Ukamenovánť jest Nábot a umřel.'),
(1555658,54,11,21,15,'I stalo se, jakž uslyšela Jezábel, že by ukamenován byl Nábot, a že by umřel, řekla Achabovi: Vstaň, vládni vinicí Nábota Jezreelského, kteréžť nechtěl dáti za peníze; neboť není živ Nábot, ale umřel.'),
(1555659,54,11,21,16,'A tak uslyšev Achab, že by umřel Nábot, vstal, aby šel do vinice Nábota Jezreelského, a aby ji ujal.'),
(1555660,54,11,21,17,'Tedy stala se řeč Hospodinova k Eliášovi Tesbitskému, řkoucí:'),
(1555661,54,11,21,18,'Vstana, vyjdi vstříc Achabovi králi Izraelskému, kterýž bydlí v Samaří, a hle, jest na vinici Nábotově, do níž všel, aby ji ujal.'),
(1555662,54,11,21,19,'A mluviti budeš k němu těmito slovy: Takto praví Hospodin: Zdaliž jsi nezabil, ano sobě i nepřivlastnil? Mluv tedy k němu, řka: Takto praví Hospodin: Proto že lízali psi krev Nábotovu, i tvou krev také lízati budou.'),
(1555663,54,11,21,20,'I řekl Achab Eliášovi: Což jsi mne našel, nepříteli můj? Kterýž odpověděl: Našel, nebo jsi prodal se, abys činil to, což zlého jest před oblíčejem Hospodinovým.'),
(1555664,54,11,21,21,'Aj, já uvedu na tebe zlé, a odejmu potomky tvé, a vypléním z domu Achabova močícího na stěnu, i zajatého i zanechaného v Izraeli.'),
(1555665,54,11,21,22,'A učiním s domem tvým jako s domem Jeroboáma syna Nebatova, a jako s domem Bázy syna Achiášova, pro zdráždění, kterýmž jsi mne popudil, a že jsi k hřešení přivodil Izraele.'),
(1555666,54,11,21,23,'Ano i proti Jezábel mluvil Hospodin, řka: Psi žráti budou Jezábel mezi zdmi Jezreelskými.'),
(1555667,54,11,21,24,'Toho, kdož umře z domu Achabova v městě, psi žráti budou, a kdož umře na poli, ptáci nebeští jísti budou.'),
(1555668,54,11,21,25,'Nebo nebylo podobného Achabovi, kterýž by se prodal, aby činil to, což zlého jest před oblíčejem Hospodinovým, proto že ho ponoukala Jezábel žena jeho.'),
(1555669,54,11,21,26,'Dopouštěl se zajisté věcí velmi ohavných, následuje modl vedlé všeho toho, čehož se dopouštěli Amorejští, kteréž vyplénil Hospodin od tváři synů Izraelských.'),
(1555670,54,11,21,27,'I stalo se, když uslyšel Achab slova tato, že roztrhl roucho své, a vzav žíni na tělo své, postil se a léhal na pytli, a chodil krotce.'),
(1555671,54,11,21,28,'Tedy stala se řeč Hospodinova k Eliášovi Tesbitskému, řkoucí:'),
(1555672,54,11,21,29,'Viděl-lis, jak se ponížil Achab před tváří mou? Poněvadž se tak ponížil před tváří mou, neuvedu toho zlého za dnů jeho, ale za dnů syna jeho uvedu to zlé na dům jeho.'),
(1555673,54,11,22,1,'Nebylo pak za tři léta války mezi Syrskými a Izraelskými.'),
(1555674,54,11,22,2,'I stalo se léta třetího, přijel Jozafat král Judský k králi Izraelskému.'),
(1555675,54,11,22,3,'Mluvil pak byl král Izraelský služebníkům svým: Víte-li, že naše bylo Rámot Galád, a my zanedbáváme vzíti ho zase z moci krále Syrského?'),
(1555676,54,11,22,4,'Pročež řekl Jozafatovi: Potáhneš-li se mnou na vojnu proti Rámot Galád? Odpověděl Jozafat králi Izraelskému: Jako jsem já, tak jsi ty, jako lid můj, tak lid tvůj, jako koni moji, tak koni tvoji.'),
(1555677,54,11,22,5,'Řekl také Jozafat králi Izraelskému: Vzeptej se dnes medle na slovo Hospodinovo.'),
(1555678,54,11,22,6,'I shromáždil král Izraelský proroků okolo čtyř set mužů a řekl jim: Mám-li táhnouti na vojnu proti Rámot Galád, či tak nechati? I řekli: Táhni, nebo dá je Pán v ruku krále.'),
(1555679,54,11,22,7,'Tedy řekl Jozafat: Což není zde již žádného proroka Hospodinova, abychom se ho zeptali?'),
(1555680,54,11,22,8,'Na to řekl král Izraelský Jozafatovi: Ještěť jest muž jeden, skrze něhož bychom se mohli poraditi s Hospodinem, ale já ho nenávidím, proto že mi dobrého neprorokuje, než zlé, Micheáš syn Jemlův. Ale Jozafat řekl: Nechť tak nemluví král.'),
(1555681,54,11,22,9,'Protož povolav král Izraelský komorníka jednoho, řekl: Přiveď sem rychle Micheáše syna Jemlova.'),
(1555682,54,11,22,10,'(Mezi tím král Izraelský a Jozafat král Judský, jeden každý na stolici své, odění jsouce rouchem, seděli v placu u vrat brány Samařské, a všickni proroci prorokovali před nimi.'),
(1555683,54,11,22,11,'Sedechiáš pak syn Kenanův udělal sobě byl rohy železné a řekl: Takto praví Hospodin: Těmito trkati budeš Syrské, dokudž nepohubíš jich.'),
(1555684,54,11,22,12,'Takž podobně i jiní všickni proroci prorokovali, řkouce: Jeď do Rámot Galád, a šťastněť se povede; nebo dá je Hospodin v ruku královu.)'),
(1555685,54,11,22,13,'V tom posel ten, kterýž šel, aby zavolal Micheáše, mluvil jemu, řka: Aj, nyní slova proroků jedněmi ústy předpovídají dobré věci králi. Medle, buď řeč tvá jako řeč kterého z nich, a mluv dobré věci.'),
(1555686,54,11,22,14,'Tedy řekl Micheáš: Živť jest Hospodin, že což mi koli řekne Hospodin, to mluviti budu.'),
(1555687,54,11,22,15,'A když přišel k králi, řekl jemu král: Micheáši, máme-li jeti na vojnu proti Rámot Galád, či tak nechati? Kterýž řekl jemu: Jeď a šťastněť se povede, nebo dá je Hospodin v ruku krále.'),
(1555688,54,11,22,16,'I řekl jemu král: I kolikrátž tě mám přísahou zavazovati, abys mi nemluvil než pravdu ve jménu Hospodinovu?'),
(1555689,54,11,22,17,'Protož řekl: Viděl jsem všecken lid Izraelský rozptýlený po horách jako ovce, kteréž nemají pastýře; nebo řekl Hospodin: Nemají pána tito, navrať se jeden každý do domu svého v pokoji.'),
(1555690,54,11,22,18,'I řekl král Izraelský Jozafatovi: Zdaližť jsem neřekl, že mi nebude prorokovati dobrého, ale zlé?'),
(1555691,54,11,22,19,'Řekl dále: Z té příčiny slyš slovo Hospodinovo: Viděl jsem Hospodina sedícího na stolici své, a všecko vojsko nebeské stojící po pravici jeho i po levici jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555692,54,11,22,20,'I řekl Hospodin: Kdo oklamá Achaba, aby vytáhl a padl u Rámot Galád? A když pravil ten toto, a jiný pravil jiné,'),
(1555693,54,11,22,21,'Tožť vyšel jakýsi duch, a postaviv se před Hospodinem, řekl: Já ho oklamám. Hospodin pak řekl jemu: Jakým způsobem?'),
(1555694,54,11,22,22,'Odpověděl: Vyjdu a budu duchem lživým v ústech všech proroků jeho. Kterýžto řekl: Oklamáš a dovedeš toho; vyjdiž a učiň tak.'),
(1555695,54,11,22,23,'Protož, aj, jižtě dal Hospodin ducha lživého v ústa všech proroků tvých těchto, ješto však Hospodin mluvil zlé proti tobě.'),
(1555696,54,11,22,24,'Tedy přistoupiv Sedechiáš syn Kenanův, dal Micheášovi poliček a řekl: Kudyže odšel duch Hospodinův ode mne, aby mluvil tobě?'),
(1555697,54,11,22,25,'Odpověděl Micheáš: Aj, uzříš v ten den, když vejdeš do nejtajnějšího pokoje, abys se skryl.'),
(1555698,54,11,22,26,'I řekl král Izraelský: Jmi Micheáše, a doveď ho k Amonovi knížeti města, a k Joasovi synu královu.'),
(1555699,54,11,22,27,'A řekneš: Takto praví král: Dejte tohoto do žaláře, a dávejte mu jísti maličko chleba a maličko vody, dokudž se nenavrátím v pokoji.'),
(1555700,54,11,22,28,'Ale Micheáš řekl: Jestliže ty se navrátíš v pokoji, tedyť nemluvil skrze mne Hospodin. Přes to řekl: Slyštež to všickni lidé!'),
(1555701,54,11,22,29,'A tak táhl král Izraelský, a Jozafat král Judský proti Rámot Galád.'),
(1555702,54,11,22,30,'I řekl král Izraelský Jozafatovi: Změním já se, když půjdu k bitvě, ale ty oblec se v roucho své. I změnil se král Izraelský a jel k bitvě.'),
(1555703,54,11,22,31,'Král pak Syrský přikázal třidcíti dvěma svým hejtmanům nad vozy, a řekl: Nebojujte proti malému ani proti velikému, než proti samému králi Izraelskému.'),
(1555704,54,11,22,32,'I stalo se, když uzřeli hejtmané nad vozy Jozafata, řekli: Jistě král Izraelský jest. I obrátili se proti němu, aby bojovali. Tedy zkřikl Jozafat.'),
(1555705,54,11,22,33,'V tom když uzřeli hejtmané nad vozy, že on není král Izraelský, obrátili se od něho.'),
(1555706,54,11,22,34,'Muž pak jeden střelil z lučiště náhodou, a postřelil krále Izraelského, kdež se pancíř spojuje. Pročež řekl vozkovi svému: Obrať se a vyvez mne z vojska, nebo jsem nemocen.'),
(1555707,54,11,22,35,'I rozmohla se bitva v ten den. Král pak stál na voze proti Syrským; potom umřel u večer, a tekla krev z rány do vozu.'),
(1555708,54,11,22,36,'I volal biřic po vojště, když již slunce zapadlo, řka: Jeden každý do města svého, a jeden každý do země své navrať se.'),
(1555709,54,11,22,37,'Umřel tedy král a dovezen jest do Samaří, i pochovali ho v Samaří.'),
(1555710,54,11,22,38,'A když pohřížen byl vůz v rybníku Samařském, střebali psi krev jeho, též když umývali zbroj jeho, vedlé řeči Hospodinovy, kterouž byl mluvil.'),
(1555711,54,11,22,39,'Jiné pak věci Achabovy, a cožkoli činil, i jaký dům z kostí slonových vystavěl, i všecka města, kteráž vzdělal, o tom zapsáno jest v knize o králích Izraelských.'),
(1555712,54,11,22,40,'A tak usnul Achab s otci svými, a kraloval Ochoziáš syn jeho místo něho.'),
(1555713,54,11,22,41,'Jozafat pak syn Azy počal kralovati nad Judou léta čtvrtého Achaba, krále Izraelského.'),
(1555714,54,11,22,42,'A byl Jozafat ve třidcíti pěti letech, když počal kralovati, a dvadceti pět let kraloval nad Jeruzalémem, jehož matky jméno bylo Azuba, dcera Silchi.'),
(1555715,54,11,22,43,'I chodil po vší cestě Azy otce svého, aniž se od ní uchýlil, čině, což dobrého bylo před oblíčejem Hospodinovým.'),
(1555716,54,11,22,44,'Toliko poněvadž výsostí nezkazili, ještě lid obětoval a kadil na těch výsostech.'),
(1555717,54,11,22,45,'Všel také v pokoj král Jozafat s králem Izraelským.'),
(1555718,54,11,22,46,'Jiné pak věci Jozafatovy, i síla jeho, kterouž prokazoval a kterouž bojoval, zapsány jsou v knize o králích Judských.'),
(1555719,54,11,22,47,'Ten ostatky ohyzdných sodomářů, kteříž ještě pozůstali za dnů Azy otce jeho, vyplénil z země.'),
(1555720,54,11,22,48,'Tehdáž nebylo žádného krále v zemi Idumejské, hejtmana měli místo krále.'),
(1555721,54,11,22,49,'I nadělal Jozafat lodí mořských, aby jeli do Ofir pro zlato. Ale nejeli, nebo polámaly se lodí v Aziongaber.'),
(1555722,54,11,22,50,'Řekl byl také Ochoziáš syn Achabův Jozafatovi: Nechť jedou služebníci moji s služebníky tvými na lodech. Ale Jozafat nechtěl.'),
(1555723,54,11,22,51,'I usnul Jozafat s otci svými, a pochován jest s otci svými v městě Davida otce svého; kraloval pak Joram syn jeho místo něho.'),
(1555724,54,11,22,52,'Ochoziáš syn Achabův počal kralovati nad Izraelem v Samaří, léta sedmnáctého Jozafata krále Judského, a kraloval nad Izraelem dvě létě.'),
(1555725,54,11,22,53,'Nebo činil zlé věci před oblíčejem Hospodinovým, a chodil po cestě otce svého a po cestě matky své, i po cestě Jeroboáma syna Nebatova, kterýž přivodil k hřešení lid Izraelský.'),
(1555726,54,11,22,54,'Sloužil také Bálovi a klaněl se jemu, čímž popudil k hněvu Hospodina Boha Izraelského vedlé toho všeho, což činil otec jeho.'),
(1555727,54,12,1,1,'V tom zprotivil se Moáb Izraelovi po smrti Achabově.'),
(1555728,54,12,1,2,'A Ochoziáš spadl skrze mříži paláce svého letního, kterýž byl v Samaří, a stonal. I poslal posly, řka jim: Jděte, pilně se ptejte Belzebuba, boha Akaron, povstanu-li z nemoci této?'),
(1555729,54,12,1,3,'Ale anděl Hospodinův řekl Eliášovi Tesbitskému: Vstana, jdi vstříc poslům krále Samařského a mluv k nim: Zdali není Boha v Izraeli, že jdete dotazovati se Belzebuba, boha Akaron?'),
(1555730,54,12,1,4,'Protož takto praví Hospodin: S ložce, na kterémžs se složil, nesejdeš, ale jistotně umřeš. I odšel Eliáš.'),
(1555731,54,12,1,5,'A když se navrátili poslové k němu, řekl jim: Pročež jste se zase vrátili?'),
(1555732,54,12,1,6,'Odpověděli jemu: Muž nějaký vyšel nám v cestu a řekl nám: Jděte, navraťte se k králi, kterýž vás poslal, a rcete jemu: Takto praví Hospodin: Zdali není Boha v Izraeli, že ty posíláš tázati se Belzebuba, boha Akaron? Protož s ložce, na kterémžs se složil, nesejdeš, ale jistotně umřeš.'),
(1555733,54,12,1,7,'I řekl jim: Jaký jest způsob muže toho, kterýž vám vstříc vyšel a mluvil vám ty řeči?'),
(1555734,54,12,1,8,'Kteříž odpověděli jemu: Jest člověk chlupatý, a pasem koženým přepásán na bedrách svých. Tedy řekl: Eliáš Tesbitský jest.'),
(1555735,54,12,1,9,'Protož poslal pro něj padesátníka s padesáti jeho. Kterýž šel k němu, a aj, seděl na vrchu hory. I řekl jemu: Muži Boží, král rozkázal, abys sstoupil dolů.'),
(1555736,54,12,1,10,'Odpovídaje Eliáš, řekl padesátníku: Jestliže jsem muž Boží, nechť sstoupí oheň s nebe, a sžíře tě i tvých padesát. A tak sstoupil oheň s nebe, a sežral jej i padesát jeho.'),
(1555737,54,12,1,11,'Opět poslal k němu král padesátníka jiného s padesáti jeho. Kterýž mluvil a řekl jemu: Muži Boží, takto rozkázal král: Rychle sstup dolů.'),
(1555738,54,12,1,12,'I odpověděl Eliáš a řekl jim: Jestliže jsem muž Boží, nechť sstoupí oheň s nebe, a sžíře tě i tvých padesát. A tak sstoupil oheň Boží s nebe, a sežral jej i padesát jeho.'),
(1555739,54,12,1,13,'Ještě poslal padesátníka třetího s padesáti jeho. Pročež vstoupiv, přišel ten třetí padesátník, a klekl na kolena svá před Eliášem, a prose ho pokorně, řekl jemu: Muži Boží,prosím, nechť jest drahá duše má i duše služebníků tvých padesáti těchto před očima tvýma.'),
(1555740,54,12,1,14,'Aj, oheň sstoupiv s nebe, sežral dva první padesátníky s padesáti jejich, ale nyní nechť jest drahá duše má před očima tvýma.'),
(1555741,54,12,1,15,'Řekl pak anděl Hospodinův Eliášovi: Sstup s ním, neboj se nic tváři jeho. Tedy vstav, šel s ním k králi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555742,54,12,1,16,'A mluvil jemu: Takto praví Hospodin: Proto že jsi poslal posly tázati se Belzebuba, boha Akaron, (jako by nebylo Boha v Izraeli, abys se tázal slova jeho), protož s ložce, na kterémžs se složil, nesejdeš, ale jistotně umřeš.'),
(1555743,54,12,1,17,'I umřel podlé řeči Hospodinovy, kterouž mluvil Eliáš, a kraloval Joram místo něho léta druhého Jehorama syna Jozafatova, krále Judského; nebo on neměl syna.'),
(1555744,54,12,1,18,'O jiných pak věcech Ochoziášových, kteréž činil, zapsáno jest v knize o králích Izraelských.'),
(1555745,54,12,2,1,'Stalo se potom, když měl již vzíti Hospodin Eliáše u vichru do nebe, že vyšel Eliáš s Elizeem z Galgala.'),
(1555746,54,12,2,2,'I řekl Eliáš Elizeovi: Medle, poseď tuto, nebo Hospodin poslal mne až do Bethel. Jemuž řekl Elizeus: Živť jest Hospodin, a živať jest duše tvá, žeť se tebe nespustím. I přišli do Bethel.'),
(1555747,54,12,2,3,'Tedy vyšli synové proročtí, kteříž byli v Bethel, k Elizeovi a řekli jemu: Víš-liž, že dnes Hospodin vezme pána tvého od tebe? Kterýž odpověděl: A já vím, mlčte.'),
(1555748,54,12,2,4,'Opět řekl jemu Eliáš: Elizee, medle poseď tuto, nebo Hospodin poslal mne do Jericha. Kterýž odpověděl: Živť jest Hospodin, a živať jest duše tvá, žeť se tebe nespustím. I přišli do Jericha.'),
(1555749,54,12,2,5,'Přistoupivše pak synové proročtí, kteříž byli v Jerichu, k Elizeovi, řekli jemu: Víš-liž, že dnes vezme Hospodin pána tvého od tebe? I řekl: A já vím, mlčte.'),
(1555750,54,12,2,6,'Řekl mu ještě Eliáš: Poseď medle tuto, nebo Hospodin poslal mne k Jordánu. Kterýž odpověděl: Živť jest Hospodin, a živať jest duše tvá, žeť se tebe nespustím. Šli tedy oba.'),
(1555751,54,12,2,7,'Padesáte pak mužů z synů prorockých šli, a postavili se naproti zdaleka, ale oni oba zastavili se u Jordánu.'),
(1555752,54,12,2,8,'A vzav Eliáš plášť svůj, svinul jej a udeřil na vodu. I rozdělila se sem i tam, tak že přešli oba po suše.'),
(1555753,54,12,2,9,'V tom když přešli, řekl Eliáš Elizeovi: Žádej sobě, co chceš, prvé než vzat budu od tebe. I řekl Elizeus: Nechť jest, prosím, dvojnásobní díl ducha tvého na mně.'),
(1555754,54,12,2,10,'Jemuž řekl: Nesnadnés věci požádal, a však jestliže uzříš mne, když budu vzat od tebe, staneť se tak; pakli nic, nestane se.'),
(1555755,54,12,2,11,'Takž stalo se, že když předce jdouce, rozmlouvali, aj, vůz ohnivý a koni ohniví rozdělili je na různo. I vstoupil Eliáš u vichru do nebe.'),
(1555756,54,12,2,12,'To vida Elizeus, volal: Otče můj, otče můj! Vozové Izraelští i jezdci jeho! A neviděl ho více. Potom uchopiv roucho své, roztrhl je na dva kusy.'),
(1555757,54,12,2,13,'A zdvih plášť Eliášův, kterýž byl spadl s něho, navrátil se a stál na břehu Jordánském.'),
(1555758,54,12,2,14,'Tedy vzav plášť Eliášův, kterýž byl spadl s něho, udeřil na vodu a řekl: Kdež jest Hospodin Bůh Eliášův i on sám? A udeřil, pravím, na vodu, kteráž rozstoupila se sem i tam. I přešel Elizeus.'),
(1555759,54,12,2,15,'Což vidouce synové proročtí z Jericha, naproti stojíce, řekli: Odpočinul duch Eliášův na Elizeovi. I šli proti němu a poklonili se mu až k zemi.'),
(1555760,54,12,2,16,'A řekli jemu: Aj, nyní jest s služebníky tvými padesáte mužů silných, medle nechť jdou a hledají pána tvého. Snad ho zanesl duch Hospodinův, a povrhl jej na některé hoře aneb v některém údolí. Kterýž řekl: Neposílejte.'),
(1555761,54,12,2,17,'Ale když na něj vždy dotírali, tak že mu to obtížné bylo, řekl: Pošlete. I poslali padesáte mužů, a hledajíce za tři dni, nenalezli ho.'),
(1555762,54,12,2,18,'A když se k němu navrátili, (on pak bydlil v Jerichu), řekl jim: Zdaliž jsem vám neřekl: Nechoďte?'),
(1555763,54,12,2,19,'Muži pak města toho řekli Elizeovi: Hle, nyní byt v městě tomto jest výborný, jakož, pane můj, vidíš, ale vody jsou zlé a země neúrodná.'),
(1555764,54,12,2,20,'Tedy řekl: Přineste mi nádobu novou, a dejte do ní soli. I přinesli mu.'),
(1555765,54,12,2,21,'A vyšed k pramenu těch vod, vsypal tam sůl a řekl: Takto praví Hospodin: Uzdravuji vody tyto; nebudeť více odtud smrti, ani nedochůdčete.'),
(1555766,54,12,2,22,'A tak uzdraveny jsou ty vody až do dnešního dne, vedlé řeči Elizeovy, kterouž byl mluvil.'),
(1555767,54,12,2,23,'Potom šel odtud do Bethel. A když šel cestou, pacholata malá vyšedše z města, posmívali se jemu, říkajíce: Jdi lysý, jdi lysý!'),
(1555768,54,12,2,24,'Kterýž ohlédna se, uzřel je a zlořečil jim ve jménu Hospodinovu. Protož vyskočivše dvě nedvědice z lesa, roztrhaly z nich čtyřidcatero a dvé dětí.'),
(1555769,54,12,2,25,'I šel odtud na horu Karmel, odkudž navrátil se do Samaří.'),
(1555770,54,12,3,1,'Joram pak syn Achabův počal kralovati nad Izraelem v Samaří léta osmnáctého Jozafata krále Judského, a kraloval dvanácte let.'),
(1555771,54,12,3,2,'A činil to, což jest zlého před očima Hospodinovýma, ač ne tak jako otec jeho a jako matka jeho; nebo odjal modly Bál, kterýchž byl nadělal otec jeho.'),
(1555772,54,12,3,3,'A však v hříších Jeroboáma syna Nebatova, kterýž k hřešení přivodil Izraele, vždy vězel, a neodstoupil od nich.'),
(1555773,54,12,3,4,'Mésa pak král Moábský měl hojnost dobytka, a dával králi Izraelskému sto tisíc beranů, a sto tisíc skopců i s vlnou.'),
(1555774,54,12,3,5,'I stalo se, když umřel Achab, že se zprotivil král Moábský králi Izraelskému.'),
(1555775,54,12,3,6,'Tedy vytáhl v ten čas král Joram z Samaří, a sečtl všecken Izrael.'),
(1555776,54,12,3,7,'A když táhl, poslal k Jozafatovi králi Judskému, aby mu řekli: Král Moábský zprotivil mi se. Potáhneš-li se mnou proti Moábovi na vojnu? Odpověděl: Potáhnu. Jako jsem já, tak jsi ty, jako lid můj, tak lid tvůj, jakž koni moji, tak koni tvoji.'),
(1555777,54,12,3,8,'Zatím řekl: Kterouž pak cestou potáhneme? Odpověděl: Cestou pouště Idumejské.'),
(1555778,54,12,3,9,'A tak vytáhl král Izraelský a král Judský i král Idumejský. A když objížděli cestou za sedm dní, nedostávalo se vody vojsku a hovadům jejich, kteráž měli s sebou.'),
(1555779,54,12,3,10,'I řekl král Izraelský: Ach, běda! Nebo povolal Hospodin tří králů těchto, aby je vydal v ruku Moábovu.'),
(1555780,54,12,3,11,'Ale Jozafat řekl: Není-liž zde proroka Hospodinova, abychom se otázali Hospodina skrze něho? Odpovídaje pak jeden z služebníků krále Izraelského, řekl: Jestiť zde Elizeus syn Safatův, kterýž líval vodu na ruce Eliášovy.'),
(1555781,54,12,3,12,'Tedy řekl Jozafat: U tohoť jest slovo Hospodinovo. I šli k němu, král Izraelský a Jozafat, i král Idumejský.'),
(1555782,54,12,3,13,'I řekl Elizeus králi Izraelskému: Co mně do tebe? Jdi k prorokům otce svého a k prorokům matky své. Řekl jemu král Izraelský: Nikoli, nebo povolal Hospodin tří králů těchto, aby je vydal v ruku Moábovu.'),
(1555783,54,12,3,14,'K tomu řekl Elizeus: Živť jest Hospodin zástupů, před jehož oblíčejem stojím, bychť sobě nevážil Jozafata krále Judského, nepohleděl bych na tě, ani popatřil.'),
(1555784,54,12,3,15,'Ale nyní přiveďte mi toho, kterýž by uměl hráti na harfu. A když on hral, byla nad ním ruka Hospodinova.'),
(1555785,54,12,3,16,'I řekl: Takto praví Hospodin: Nadělej v tomto potoku množství dolů.'),
(1555786,54,12,3,17,'Nebo toto dí Hospodin: Neuzříte větru, aniž uzříte přívalu, však potok tento naplněn bude vodou, tak že píti budete i vy i množství vaše, i hovada vaše.'),
(1555787,54,12,3,18,'A i to málo jest před oblíčejem Hospodinovým, nebo i Moábské dá v ruku vaši.'),
(1555788,54,12,3,19,'A zkazíte všeliké město hrazené, i všeliké město výborné, též všecko stromoví dobré zporážíte, a všecky studnice vod zasypete, a všeliké pole dobré kamením přiházíte.'),
(1555789,54,12,3,20,'I stalo se ráno, když obětována bývá obět suchá, a aj, vody přicházely cestou od strany Idumejské, a naplněna jest země vodami.'),
(1555790,54,12,3,21,'Všecken pak Moáb uslyšev, že by vytáhli králové, aby bojovali proti nim, svolali se všickni, od toho, kterýž se pasem opásati může, a výše, a postavili se na pomezí.'),
(1555791,54,12,3,22,'Potom ráno vstavše, když slunce vzešlo nad těmi vodami, uzřeli Moábští naproti ty vody rdějící se jako krev.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555792,54,12,3,23,'A řekli: Krev jest. Jistě žeť jsou se pohubili ti králové, a zabil jeden každý bližního svého; protož nyní k loupežem, ó Moábští! A přišli až k ležení Izraelskému.'),
(1555793,54,12,3,24,'Tedy povstavše Izraelští, porazili Moábské, kteříž utíkali před nimi, a oni porazili je porážkou velikou, také i v jejich krajině.'),
(1555794,54,12,3,25,'Nebo města jejich zbořili, a na všeliké pole výborné házejíce jeden každý kamením svým, naplnili je, i všecky studnice vod zasypali, a všecko stromoví dobré zporáželi, tak že toliko nechali u Kirchareset zdi jeho. Protož shlukše se prakovníci, dobývali ho.'),
(1555795,54,12,3,26,'A vida král Moábský, že jsou mu silní bojovníci ti, vzal s sebou sedm set mužů bojovných, chtě se probiti skrze vojska krále Idumejského. Ale nemohli.'),
(1555796,54,12,3,27,'Pročež jav syna jeho prvorozeného, kterýž měl kralovati místo něho, obětoval jej v obět zápalnou na zdi. I stalo se rozhněvání veliké proti Izraelovi; protož odtrhše od něho, navrátili se do země své.'),
(1555797,54,12,4,1,'Tedy žena jedna z manželek synů prorockých volala k Elizeovi, řkuci: Služebník tvůj, muž můj, umřel, ty pak víš, že služebník tvůj bál se Hospodina. A teď věřitel přišel, aby vzal dva syny mé sobě za služebníky.'),
(1555798,54,12,4,2,'Řekl jí Elizeus: Což chceš, ať učiním? Oznam mi, co máš v domě? Ona řekla: Nemáť služebnice tvá nic v domě, jediné báni oleje.'),
(1555799,54,12,4,3,'I řekl: Jdi, vyžádej sobě nádob vně ode všech sousedů svých, nádob prázdných tím více.'),
(1555800,54,12,4,4,'A vejda, zavři za sebou dvéře i za syny svými, a nalévej do všech těch nádob, a kteráž bude plná, rozkážeš ji odstaviti.'),
(1555801,54,12,4,5,'A tak odešla od něho a zavřela dvéře za sebou a za syny svými. Oni podávali jí, a ona nalévala.'),
(1555802,54,12,4,6,'I stalo se, že když naplnila ty nádoby, řekla synu svému: Podej mi ještě nádoby. Kterýž odpověděl: Již není více nádob. I přestal olej.'),
(1555803,54,12,4,7,'Tedy ona přišedši, oznámila to muži Božímu. On pak řekl: Jdi, prodej ten olej, a spokoj věřitele svého, ty pak s syny svými budeš se živiti z ostatku.'),
(1555804,54,12,4,8,'Potom stalo se některého času, že šel Elizeus skrze Sunem, kdež byla jedna žena vzácná, kteráž ho pozdržela, aby jedl u ní. A od toho času chodívaje tudy, stavoval se tam, a jídal chléb.'),
(1555805,54,12,4,9,'Nebo řekla byla muži svému: Aj, nyní vím, že ten muž Boží svatý jest, kterýž často tudyto chodívá.'),
(1555806,54,12,4,10,'Medle, udělejme pokojík malý, a postavme tam jemu ložce, stůl, stolici a svícen, aby, když by koli k nám přišel, obrátil se tam.'),
(1555807,54,12,4,11,'Některého tedy času přišel tam, a všed do toho pokojíku, odpočinul tu.'),
(1555808,54,12,4,12,'I řekl Gézi služebníku svému: Zavolej té Sunamitské. Kterýž zavolal jí. I postavila se před ním.'),
(1555809,54,12,4,13,'Přitom řekl jemu: Rci jí nyní: Hle, pečuješ a staráš se o nás všelijak. Co chceš, ať učiním? Máš-li jakou potřebu před králem aneb před hejtmanem vojska? Kteráž řekla: U prostřed lidu svého bydlím.'),
(1555810,54,12,4,14,'Řekl on: Což tedy mám pro ni učiniti? Odpověděl Gézi: Hle, syna nemá, a muž její starý jest.'),
(1555811,54,12,4,15,'Protož řekl: Zavolej jí. Takž jí zavolal, a ona stála u dveří.'),
(1555812,54,12,4,16,'I řekl: V času jistém vedlé času života chovati budeš syna. Řekla ona: Nechtěj, pane můj, muži Boží, nechtěj se posmívati služebnici své.'),
(1555813,54,12,4,17,'Zatím počala žena a porodila syna v času jistém vedlé času života, kterýž předpověděl jí Elizeus.'),
(1555814,54,12,4,18,'I rostlo dítě. Stalo se pak některého času, že vyšedši k otci svému k žencům,'),
(1555815,54,12,4,19,'Řeklo otci svému: Hlava má, hlava má! I řekl služebníku: Dones jej k matce jeho.'),
(1555816,54,12,4,20,'Kterýž když ho vzal a přinesl k matce jeho, seděl na klíně jejím až do poledne a umřel.'),
(1555817,54,12,4,21,'Tedy ona vstoupivši, položila jej na ložce muže Božího, a zavřevši ho, vyšla.'),
(1555818,54,12,4,22,'Potom zavolala muže svého a řekla: Medle, pošli mi jednoho z služebníků a jednu oslici, ať doběhnu až k muži Božímu, a zase se navrátím.'),
(1555819,54,12,4,23,'Kterýž řekl: Proč chceš jíti k němu? Dnes není novměsíce, ani sobota. Odpověděla ona: Měj o to pokoj.'),
(1555820,54,12,4,24,'Osedlavši tedy oslici, řekla služebníku svému: Pobádej a běž, a nemeškej se pro mne v jízdě, leč bych rozkázala tobě.'),
(1555821,54,12,4,25,'A tak jela, až přijela k muži Božímu na horu Karmel. A když ji uzřel muž Boží zdaleka, řekl Gézi služebníku svému: Hle, Sunamitská tamto.'),
(1555822,54,12,4,26,'Protož nyní běž jí v cestu a rci jí: Dobře-li se máš? Dobře-li se má muž tvůj? Dobře-li se má syn? Ona řekla: Dobře.'),
(1555823,54,12,4,27,'V tom přišla k muži Božímu na horu, a chopila se noh jeho. I přistoupil Gézi, aby ji odehnal. Ale muž Boží řekl: Nechej jí; nebo v hořkosti jest duše její, a Hospodin zatajil to přede mnou, aniž mi oznámil.'),
(1555824,54,12,4,28,'Ona pak řekla: Zdaliž jsem žádala syna od pána mého? Zdaliž jsem neřekla, abys mne nešálil?'),
(1555825,54,12,4,29,'Tedy řekl k Gézi: Přepaš bedra svá, a vezmi hůl mou v ruku svou a jdi. Jestliže potkáš koho, nepozdravuj ho, a jestliže tě kdo pozdraví, neodpovídej jemu, a přijda, polož hůl mou na tvář dítěte.'),
(1555826,54,12,4,30,'I řekla matka dítěte: Živť jest Hospodin a živať jest duše tvá, žeť se tebe nespustím. Protož vstav, bral se za ní.'),
(1555827,54,12,4,31,'Gézi pak byl předšel je, a položil hůl na tvář dítěte, ale nebylo hlasu, ani čitelnosti. Pročež vracuje se jemu vstříc, pověděl mu, řka: Neprobudilo se dítě.'),
(1555828,54,12,4,32,'Všel tedy Elizeus do domu, a aj, dítě mrtvé leželo na ložci jeho.'),
(1555829,54,12,4,33,'A když všel tam, zavřel dvéře před oběma, a modlil se Hospodinu.'),
(1555830,54,12,4,34,'Zatím vstoupiv na lože, zpolehl na dítě, vloživ ústa svá na ústa jeho, a oči své na oči jeho, a ruce své na ruce jeho, a rozprostřel se nad ním. I zahřelo se tělo dítěte.'),
(1555831,54,12,4,35,'A odvrátiv se, procházel se po domě jednak sem jednak tam; potom vstoupiv, rozprostřel se opět nad ním. I kýchalo dítě až do sedmikrát, a otevřelo to dítě oči své.'),
(1555832,54,12,4,36,'Tedy zavolav Gézi, řekl: Zavolej Sunamitské. I zavolal jí. A když přišla k němu, řekl jí: Vezmiž syna svého.'),
(1555833,54,12,4,37,'Kteráž jakž vešla, padla k nohám jeho a poklonila se k zemi. I vzala syna svého a vyšla.'),
(1555834,54,12,4,38,'Potom Elizeus navrátil se do Galgala. Byl pak hlad v té zemi, a synové proročtí seděli před ním. I řekl mládenci svému: Přistav hrnec veliký, a navař kaše synům prorockým.'),
(1555835,54,12,4,39,'Protož vyšel jeden na pole, aby nasbíral zelin, a nalezl rév polní, a nasbíral z něho tykví polních plnou sukni svou, a přišed, skrájel to do hrnce, aby navařil kaše; nebo neznali toho.'),
(1555836,54,12,4,40,'I vylili mužům těm, aby jedli. Stalo se pak, když jedli tu kaši, že zkřikli a řekli: Smrt v hrnci, muži Boží! A nemohli jísti.'),
(1555837,54,12,4,41,'Kterýžto řekl: Vezměte mouky. Kteréž nasypav do hrnce, rozkázal vyliti lidu. I jedli, aniž co zlého bylo v hrnci.'),
(1555838,54,12,4,42,'V tom muž přišel z Balsalisa, kterýž přinesl muži Božímu chleby z prvotin, totiž dvadceti chlebů ječných, a klasů nových nevymnutých. I řekl: Dej lidu, ať jedí.'),
(1555839,54,12,4,43,'Odpověděl služebník jeho: Což to mám předložiti sto mužům? Opět řekl: Dej lidu, ať pojedí. Nebo tak praví Hospodin: Jísti budou, a ještě zůstane.'),
(1555840,54,12,4,44,'A tak předložil jim, i jedli, a zůstalo ještě vedlé řeči Hospodinovy.'),
(1555841,54,12,5,1,'Náman hejtman vojska krále Syrského, jsa muž veliký u pána svého, a osoba vzácná, skrze něho zajisté dal Hospodin vysvobození zemi Syrské, ten, pravím, muž tak udatný byl malomocný.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555842,54,12,5,2,'Byli pak vyšli z země Syrské lotříkové, kteříž zajali z země Izraelské děvečku malou, a ta sloužila manželce Námanově.'),
(1555843,54,12,5,3,'Kteráž řekla paní své: Ó by pán můj dostal se k proroku, kterýž jest v Samaří, tedy on by ho uzdravil od malomocenství jeho.'),
(1555844,54,12,5,4,'A on všed, oznámil pánu svému, řka: Takto a takto pravila děvečka, kteráž jest z země Izraelské.'),
(1555845,54,12,5,5,'Tedy řekl král Syrský: Jdi, vyprav se, a já pošli list králi Izraelskému. A odcházeje, vzal s sebou deset centnéřů stříbra a šest tisíců zlatých, nad to desatero roucho proměnné.'),
(1555846,54,12,5,6,'I přinesl list králi Izraelskému v tato slova: Hned, jakž tě dojde list tento, aj, poslal jsem k tobě Námana služebníka svého, abys ho uzdravil od malomocenství jeho.'),
(1555847,54,12,5,7,'I stalo se, že když přečetl král Izraelský ten list, roztrhl roucho své a řekl: Zdali jsem já Bohem, abych mohl umrtviti a obživiti, že tento poslal ke mně, abych uzdravil muže od malomocenství jeho? Nýbrž posuďte, prosím, a pohleďte, že příčiny hledá proti mně.'),
(1555848,54,12,5,8,'A když uslyšel Elizeus muž Boží, že roztrhl král Izraelský roucho své, poslal k králi, řka: Proč jsi roztrhl roucho své? Nechť nyní přijde ke mně a zvíť, že jest prorok v Izraeli.'),
(1555849,54,12,5,9,'A tak přibral se Náman s jízdou svou a s vozy svými, a stál u dveří domu Elizeova.'),
(1555850,54,12,5,10,'Poslal pak k němu Elizeus posla, řka: Jdi a umej se sedmkrát v Jordáně, a uzdraveno bude tělo tvé, a čist budeš.'),
(1555851,54,12,5,11,'Tedy rozhněvav se Náman, bral se odtud a mluvil: Hle, řekl jsem u sebe, že jistotně vyjde, a stoje, vzývati bude jméno Hospodina Boha svého, a vznášeje ruku svou nad místem neduživým, tak uzdraví malomocenství mé.'),
(1555852,54,12,5,12,'Zdali nejsou lepší Abana a Farfar, řeky Damašské, nad všecky vody Izraelské? Zdaliž bych se nemohl v nich zmýti, abych čist byl? A obrátiv se, jel s hněvem.'),
(1555853,54,12,5,13,'Ale přistoupivše služebníci jeho, mluvili k němu a řekli: Otče můj, jakkoli velikou věc prorok ten rozkázal by tobě, což bys neměl učiniti toho? Čím tedy více, kdyžť řekl: Umej se, a budeš čist.'),
(1555854,54,12,5,14,'A protož sstoupiv, pohřížil se v Jordáně sedmkrát vedlé řeči muže Božího. I učiněno jest tělo jeho jako tělo dítěte malého, a očištěn jest.'),
(1555855,54,12,5,15,'A hned navrátil se k muži Božímu se vším komonstvem svým, a přišed, stál před ním a řekl: Aj, již jsem poznal, žeť není Boha na vší zemi, jediné v Izraeli. Protož nyní vezmi, prosím, dary tyto od služebníka svého.'),
(1555856,54,12,5,16,'On pak řekl: Živť jest Hospodin, před jehož oblíčejem stojím, žeť nic nevezmu. A ač ho nutil, aby vzal, však nikoli nechtěl.'),
(1555857,54,12,5,17,'I řekl Náman: Tedy nic? Ale nechť jest dáno, prosím, mně služebníku tvému břímě země na dva mezky; neboť nebude více obětovati služebník tvůj zápalů aneb obětí bohům cizím, ale Hospodinu.'),
(1555858,54,12,5,18,'V této však věci odpusť Hospodin služebníku tvému: Když vchází pán můj do chrámu Remmon, aby se tam modlil, a on podpírá se na mou ruku, že i já skláním se v chrámě Remmon. Toho sklánění mého v chrámě Remmon nechť neváží, prosím, Hospodin služebníku tvému při té věci.'),
(1555859,54,12,5,19,'I řekl jemu: Jdi v pokoji. A když odjel od něho nedaleko,'),
(1555860,54,12,5,20,'V tom řekl Gézi služebník Elizea muže Božího: Hle, nedopustil pán můj Námanovi Syrskému tomuto, aby dáti měl z ruky své to, což přivezl. Živť jest Hospodin, žeť poběhnu za ním, a vezmu něco od něho.'),
(1555861,54,12,5,21,'Protož běžel Gézi za Námanem. A vida Náman běžícího za sebou, rychle skočil s vozu vstříc jemu a řekl: Dobře-li se děje?'),
(1555862,54,12,5,22,'A on odpověděl: Dobře. Pán můj poslal mne, aťbych řekl: Aj, teď nyní přišli ke mně dva mládenci s hory Efraim z synů prorockých; dej jim medle centnéř stříbra a dvoje roucho proměnné.'),
(1555863,54,12,5,23,'I řekl Náman: Raději vezmi dva centnéře. I přinutil ho. A svázav dva centnéře stříbra do dvou pytlů, a dvoje roucho proměnné, vložil to na dva pacholky své, kteříž nesli před ním.'),
(1555864,54,12,5,24,'A když přišel na vrch, vzal to z rukou jejich, a složil v jednom domě, propustiv muže ty, kteřížto odešli.'),
(1555865,54,12,5,25,'Sám pak všed, stál před pánem svým. I řekl mu Elizeus: Odkudžto, Gézi? Odpověděl: Nechodil služebník tvůj nikam.'),
(1555866,54,12,5,26,'Kterýž řekl jemu: Zdaliž srdce mé nebylo při tom, když obrátil se muž s vozu svého vstříc tobě? Zdaliž čas byl bráti stříbro aneb roucho, aneb olivoví a vinice, aneb stáda a voly, neb služebníky aneb děvky?'),
(1555867,54,12,5,27,'Protož malomocenství Námanovo přichytí se tebe i semene tvého na věky. I vyšel od tváři jeho malomocný jako sníh.'),
(1555868,54,12,6,1,'Řekli pak synové proročtí Elizeovi: Ej, teď místo toto, v němž bydlíme s tebou, jest nám těsné.'),
(1555869,54,12,6,2,'Medle, nechť jdeme až k Jordánu, abychom vzali odtud jeden každý jedno dřevo, a uděláme sobě tu místo, v němž bychom bydlili. Jimž řekl: Jděte.'),
(1555870,54,12,6,3,'I řekl jeden: Prosím, poď také s služebníky svými. Kterýž odpověděl: A já půjdu.'),
(1555871,54,12,6,4,'Takž šel s nimi. A když přišli k Jordánu, sekali dříví.'),
(1555872,54,12,6,5,'I stalo se, když jeden z nich podtínal dřevo, že sekera spadla mu do vody. Tedy zkřikl a řekl: Ach, pane můj, a ta ještě byla vypůjčená.'),
(1555873,54,12,6,6,'Jemuž řekl muž Boží: Kamž jest upadla? I ukázal mu to místo. Kterýž uťav dřevo, uvrhl je tam, a učinil, aby zplynula sekera.'),
(1555874,54,12,6,7,'A řekl: Vezmi ji sobě. Kterýž vztáh ruku svou, vzal ji.'),
(1555875,54,12,6,8,'Když pak král Syrský bojoval proti Izraelovi, a vešel v radu s služebníky svými, řka: Na tom a na tom místě položí se vojsko mé:'),
(1555876,54,12,6,9,'Tedy poslal muž Boží k králi Izraelskému, řka: Viz, abys netáhl přes to místo, nebo tam Syrští jsou v zálohách.'),
(1555877,54,12,6,10,'Protož posílal král Izraelský na to místo, o kterémž mu byl řekl muž Boží, a vystříhal ho, aby se ho šetřil a to nejednou ani dvakrát.'),
(1555878,54,12,6,11,'A tak zkormoutil se v srdci svém král Syrský pro tu věc, a svolav služebníky své, řekl jim: Proč mi neoznámíte, kdo z našich králi Izraelskému donáší?'),
(1555879,54,12,6,12,'Jemuž řekl jeden z služebníků jeho: Nikoli, pane můj králi, ale Elizeus prorok, kterýž jest v Izraeli, oznamuje králi Izraelskému slova, kteráž ty mluvíš v nejtajnějším pokoji svém.'),
(1555880,54,12,6,13,'Kterýž řekl: Jděte a vizte, kde jest, abych poslal a jal jej. I oznámeno jemu těmito slovy: Hle, jest v Dotain.'),
(1555881,54,12,6,14,'Protož poslal tam koně a vozy a vojsko veliké. Kteříž přitáhše v noci, oblehli město.'),
(1555882,54,12,6,15,'Vstav pak ráno služebník muže Božího, vyšel, a aj, vojsko obklíčilo město, koni i vozové. I řekl služebník ten jeho k němu: Ach, pane můj, což budeme dělati?'),
(1555883,54,12,6,16,'Kterýž odpověděl: Neboj se, nebo mnohem více jich s námi jest, než s nimi.'),
(1555884,54,12,6,17,'I modlil se Elizeus a řekl: Ó Hospodine, otevři, prosím, oči jeho, aby viděl. A tak otevřel Hospodin oči služebníka toho, a viděl, a aj, hora ta plná koňů, a vozové ohniví okolo Elizea.'),
(1555885,54,12,6,18,'A když nepřátelé táhli k němu, modlil se Elizeus Hospodinu a řekl: Poraz, prosím, národ tento slepotou. I porazil je slepotou vedlé řeči Elizeovy.'),
(1555886,54,12,6,19,'V tom řekl jim Elizeus: Neníť to ta cesta, ani to město. Poďte za mnou, a dovedu vás k muži, kteréhož hledáte. Takž je vedl do Samaří.'),
(1555887,54,12,6,20,'I stalo se, když vešli do Samaří, že řekl Elizeus: Ó Hospodine, otevři oči těchto, ať vidí. Tedy otevřel Hospodin oči jejich, a viděli, že jsou u prostřed Samaří.'),
(1555888,54,12,6,21,'Řekl pak král Izraelský Elizeovi, když je uzřel: Mám-liž je zmordovati, otče můj?'),
(1555889,54,12,6,22,'Odpověděl on: Nemorduj. Zdaliž jsi je zjímal mečem svým a lučištěm svým, abys je zmordoval? Dej jim chleba a vody, ať jedí a pijí, a navrátí se ku pánu svému.'),
(1555890,54,12,6,23,'A tak připravil jim hojnost velikou, a když pojedli a napili se, propustil je. Oni pak navrátili se ku pánu svému, aniž kdy více potom lotříkové Syrští vskakovali do země Izraelské.'),
(1555891,54,12,6,24,'Stalo se potom, že shromáždil Benadad král Syrský všecka vojska svá, a přitáh, oblehl Samaří.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555892,54,12,6,25,'Pročež byl hlad veliký v Samaří; nebo aj, tak dlouho obleženo bylo, až hlava oslová byla za osmdesáte stříbrných, a čtvrtý díl míry káb trusů holubích za pět stříbrných.'),
(1555893,54,12,6,26,'I přihodilo se, když král Izraelský šel po zdi, žena jedna zvolala k němu, řkuci: Spomoz mi, pane můj králi.'),
(1555894,54,12,6,27,'Kterýž řekl: Jestliť nespomůže Hospodin, odkud já mám pomoci tobě? Zdali z humna aneb z presu?'),
(1555895,54,12,6,28,'Řekl jí ještě král: Cožtě pak? Kteráž odpověděla: Žena tato řekla mi: Dej syna svého, abychom ho dnes snědly, zítra také sníme syna mého.'),
(1555896,54,12,6,29,'I uvařily jsme syna mého, a snědly jsme jej. Potom druhého dne řekla jsem jí: Dej syna svého, abychom ho snědly. Ale ona skryla syna svého.'),
(1555897,54,12,6,30,'A když uslyšel král slova ženy té, roztrhl roucha svá. (Když pak on šel po zdi, viděl lid, an pytel byl na těle jeho zespod.)'),
(1555898,54,12,6,31,'Protož řekl král: Toto mi učiň Bůh a toto přidej, jestliže zůstane hlava Elizea syna Safatova na něm dnes.'),
(1555899,54,12,6,32,'(Elizeus pak seděl v domě svém, a starší s ním seděli.) I poslal jednoho z přístojících svých, a prvé než přišel posel ten k němu, již byl řekl starším: Nevíte-liž, že poslal ten syn vražedlníkův, aby sťal hlavu mou? Šetřtež, když by vcházel ten posel, zavřete dvéře a odstrčte jej ode dveří. Zdaliž i dusání noh pána jeho není za ním?'),
(1555900,54,12,6,33,'A když on ještě mluvil s nimi, hle, posel přicházel k němu, a řekl: Aj, toto zlé jest od Hospodina, což mám déle čekati na něj?'),
(1555901,54,12,7,1,'Řekl pak Elizeus: Slyšte slovo Hospodinovo. Toto praví Hospodin: O tomto času zítra míra mouky bělné bude za lot stříbra, a dvě míry ječmene za lot stříbra v bráně Samařské.'),
(1555902,54,12,7,2,'I odpověděl muži Božímu jeden z knížat, na jehož ruku král zpoléhal, a řekl: Kdyby otevřel Hospodin průduchy nebeské, zdali by to býti mohlo? Kterýž řekl: Aj, uzříš očima svýma, ale nebudeš jísti z toho.'),
(1555903,54,12,7,3,'Byli pak u vrat brány čtyři muži malomocní, kteříž řekli jeden druhému: Co tu sedíme, až bychom zemříti musili?'),
(1555904,54,12,7,4,'Díme-li: Poďme do města, hlad jest v městě, i zemřeme tam; pakli zde zůstaneme, také zemřeme. Protož nyní poďte, a utecme do vojska Syrských. Budou-li nás živiti, zůstaneme živi; pakli nás zbijí, též zemřeme.'),
(1555905,54,12,7,5,'Vstavše tedy v soumrak, aby šli k vojsku Syrských, přišli až k kraji ležení Syrského, a hle, nebylo tu žádného.'),
(1555906,54,12,7,6,'Nebo Pán učinil to, aby slyšelo vojsko Syrské hřmot vozů a zvuk koňů, a tak hluk vojska velikého. I řekli jeden druhému: Hle, ze mzdy najal proti nám král Izraelský krále Hetejské a krále Egyptské, aby připadli na nás.'),
(1555907,54,12,7,7,'A vstavše, utekli v soumrak a nechali tu stanů svých, a koňů svých i oslů svých, a ležení, tak jakž bylo, a utekli pro zachování života svého.'),
(1555908,54,12,7,8,'Když tedy přišli malomocní ti na kraj ležení, všedše do jednoho stanu, jedli a pili, a pobravše v něm stříbro a zlato i roucha, odešli a schovali. Opět navrátivše se, vešli do jiného stanu a pobrali v něm, a odšedše, schovali.'),
(1555909,54,12,7,9,'I řekli vespolek: Nedobře děláme. Den tento jest den dobrých novin, a my mlčíme. Budeme-li čekati až do svitání, postihne nás nepravost; protož nyní poďte, vejdouce, oznamme to domu královskému.'),
(1555910,54,12,7,10,'A přišedše, volali na branné města, a pověděli jim, řkouce: Přišli jsme do ležení Syrského, a aj, nebylo tam žádného, ani hlasu lidského, kromě koní přivázaných a oslů přivázaných, a stanů, jakž prvé byli.'),
(1555911,54,12,7,11,'I volal ten na jiné branné, a ti ohlásili to po všem domě královském.'),
(1555912,54,12,7,12,'Vstav tedy král v noci, řekl služebníkům svým: Povím vám nyní, co jsou nám udělali Syrští. Vědí, že jsme hladovití, protož vyšli z ležení, aby se skryli v poli, řkouce: Když vyjdou z města, zjímáme je živé a vejdeme do města.'),
(1555913,54,12,7,13,'K tomu odpovídaje jeden z služebníků jeho, řekl: Nechť, prosím, vezmou pět koní z těch, kteříž pozůstali v městě. (Hle, oniť jsou jako i všecko množství Izraelské, jenž zůstali v něm, hle, jsou jako všecko množství Izraelské, kteréž již hyne.) Ty pošleme a přezvíme.'),
(1555914,54,12,7,14,'A tak vzali dva koně vozní, kteréž poslal král za vojskem Syrským, řka: Jděte a vizte.'),
(1555915,54,12,7,15,'I jeli za nimi až k Jordánu, a aj, po vší té cestě plno bylo šatů a nádob, kteréž metali od sebe Syrští, splašeni jsouce. Tedy navrátivše se poslové, oznámili to králi.'),
(1555916,54,12,7,16,'Protož vyšed lid, vzebral ležení Syrské. A byla míra mouky bělné za lot, a dvě míry ječmene za lot vedlé řeči Hospodinovy.'),
(1555917,54,12,7,17,'Král pak byl ustanovil to kníže, na jehož ruku zpoléhal, u brány. Kteréhož pošlapal lid v bráně, tak že umřel, vedlé řeči muže Božího, kterouž mluvil, když král k němu byl sešel.'),
(1555918,54,12,7,18,'A stalo se tak, jakž mluvil muž Boží králi, řka: Dvě míry ječmene budou za lot stříbra, a míra mouky bělné za lot stříbra zítra o tomto času v bráně Samařské.'),
(1555919,54,12,7,19,'K čemuž bylo odpovědělo kníže muži Božímu, a řeklo: Kdyby otevřel Hospodin průduchy nebeské, zdali by to podlé řeči této býti mohlo? Jemuž on řekl: Aj, ty uzříš očima svýma, ale z toho jísti nebudeš.'),
(1555920,54,12,7,20,'A tak se stalo jemu; nebo pošlapal ho lid v bráně, tak že umřel.'),
(1555921,54,12,8,1,'Mluvil pak Elizeus k ženě té, jejíhož byl syna vzkřísil, řka: Vstaň a jdi, ty i čeled tvá, a buď pohostinu, kdežkoli budeš moci byt míti; nebo zavolal Hospodin hladu, a přijdeť na zemi za sedm let.'),
(1555922,54,12,8,2,'Vstavši tedy žena, učinila vedlé řeči muže Božího, a odešla s čeledí svou, a bydlila pohostinu v zemi Filistinských sedm let.'),
(1555923,54,12,8,3,'I stalo se, že když pominulo těch sedm let, navrátila se ta žena z země Filistinské, a šla, aby prosila krále za dům svůj a za pole své.'),
(1555924,54,12,8,4,'Mezi tím král mluvil s Gézi, služebníkem muže Božího, řka: Vypravuj mi medle o všech věcech velikých, kteréž činil Elizeus.'),
(1555925,54,12,8,5,'A když on vypravoval králi, kterak obživil mrtvého, aj žena, jejíhož syna vzkřísil, prosila krále za dům svůj a za pole své. I řekl Gézi: Pane můj králi, to jest ta žena, a tento syn její, kteréhož vzkřísil Elizeus.'),
(1555926,54,12,8,6,'Tedy tázal se král ženy, kteráž vypravovala jemu. I poručil král komorníku jednomu, řka: Ať jsou navráceny všecky věci, kteréž byly její, i všecky užitky pole, ode dne, v němž opustila zemi, až po dnes.'),
(1555927,54,12,8,7,'Potom přišel Elizeus do Damašku, král pak Syrský Benadad stonal. I oznámeno jemu těmito slovy: Přišel muž Boží sem.'),
(1555928,54,12,8,8,'I řekl král Hazaelovi: Vezmi v ruce své dar, a jdi vstříc muži Božímu, a zeptej se Hospodina skrze něho, řka: Povstanu-li z nemoci této?'),
(1555929,54,12,8,9,'A tak šel Hazael vstříc jemu, vzav s sebou dar, a všeliké věci výborné Damašské, břemena na čtyřidcíti velbloudích, a přišed, stál před ním a řekl: Syn tvůj Benadad, král Syrský, poslal mne k tobě, řka: Povstanu-li z nemoci této?'),
(1555930,54,12,8,10,'Odpověděl mu Elizeus: Jdi, pověz jemu: Zajisté mohl bys živ zůstati. Ale Hospodin mi ukázal, že jistotně umře.'),
(1555931,54,12,8,11,'V tom proměniv muž Boží tvář svou, ukázal se k němu neochotně a plakal.'),
(1555932,54,12,8,12,'Jemuž řekl Hazael: Proč pán můj pláče? Odpověděl: Proto že vím, co zlého ty učiníš synům Izraelským. Pevnosti jejich spálíš a mládence jejich zmorduješ mečem, a nemluvňátka jejich rozrážeti budeš, a těhotné jejich zroztínáš.'),
(1555933,54,12,8,13,'I řekl Hazael: I což jest služebník tvůj pes, aby učiniti mohl věc tak velikou? Odpověděl Elizeus: Ukázal tě mi Hospodin, že budeš králem Syrským.'),
(1555934,54,12,8,14,'A odšed od Elizea, přišel ku pánu svému. Kterýž řekl jemu: Cožť řekl Elizeus? Odpověděl: Pravil mi, že bys mohl živ zůstati.'),
(1555935,54,12,8,15,'I stalo se nazejtří, že vzal koberec, a namočiv jej v vodě, prostřel jej na tvář jeho. I umřel, a kraloval Hazael místo něho.'),
(1555936,54,12,8,16,'Léta pak pátého Jorama, syna Achabova krále Izraelského, a Jozafata krále Judského, počal kralovati Jehoram, syn Jozafatův král Judský.'),
(1555937,54,12,8,17,'Ve dvou a třidcíti letech byl, když počal kralovati, a kraloval osm let v Jeruzalémě.'),
(1555938,54,12,8,18,'A chodil po cestě králů Izraelských, tak jako činil dům Achabův; nebo měl dceru Achabovu za manželku. Takž činil zlé věci před očima Hospodinovýma.'),
(1555939,54,12,8,19,'Hospodin však nechtěl zahladiti Judy pro Davida služebníka svého, jakž mu byl zaslíbil, že dá jemu svíci i synům jeho po všecky dny.'),
(1555940,54,12,8,20,'Ve dnech jeho odstoupil Edom od království Judského, a ustanovili nad sebou krále.'),
(1555941,54,12,8,21,'Tou příčinou táhl Jehoram do Seir, i všickni vozové s ním. A vstav v noci, porazil Idumejské, kteříž jej byli obklíčili, i hejtmany vozů, a lid utekl do stanů svých.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555942,54,12,8,22,'Však předce odstoupil Edom od království Judského až do tohoto dne. Takž odstoupilo i Lebno téhož času.'),
(1555943,54,12,8,23,'O jiných pak věcech Jehoramových, a o všem, cožkoli činil, psáno jest v knize o králích Judských.'),
(1555944,54,12,8,24,'I usnul Jehoram s otci svými, a pochován jest s otci svými v městě Davidově, kraloval pak Ochoziáš syn jeho místo něho.'),
(1555945,54,12,8,25,'Léta dvanáctého Jorama syna Achabova, krále Izraelského, počal kralovati Ochoziáš syn Jehorama, krále Judského.'),
(1555946,54,12,8,26,'Ve dvamecítma letech byl Ochoziáš, když počal kralovati, a kraloval jeden rok v Jeruzalémě. Jméno matky jeho bylo Atalia, dcera Amri krále Izraelského.'),
(1555947,54,12,8,27,'A chodil cestou domu Achabova, čině, což jest zlého před očima Hospodinovýma, jako i dům Achabův, nebo byl zetěm domu Achabova.'),
(1555948,54,12,8,28,'Pročež vycházel s Joramem synem Achabovým, na vojnu proti Hazaelovi králi Syrskému, do Rámot Galád; ale porazili Syrští Jorama.'),
(1555949,54,12,8,29,'A tak navrátil se král Joram, aby se hojil v Jezreel na rány, kterýmiž ho ranili Syrští v Ráma, když bojoval s Hazaelem králem Syrským. Ochoziáš pak syn Jehorama, krále Judského, přijel, aby navštívil Jorama syna Achabova v Jezreel; nebo tam nemocen byl.'),
(1555950,54,12,9,1,'Prorok pak Elizeus povolal jednoho z synů prorockých, a řekl jemu: Přepaš bedra svá, a vezmi tuto nádobku oleje do ruky své, a jdi do Rámot Galád.'),
(1555951,54,12,9,2,'A když tam přijdeš, uzříš tam Jéhu, syna Jozafata syna Namsi. K němuž když přijdeš, vyvoláš ho z prostředku bratří jeho, a uvedeš ho do nejtajnějšího pokojíku.'),
(1555952,54,12,9,3,'A vezma nádobku oleje, vyleješ na hlavu jeho a díš: Toto praví Hospodin: Pomazuji tebe za krále nad Izraelem. A hned otevra dvéře, utec a nemeškej se.'),
(1555953,54,12,9,4,'I odšel mládenec ten služebník prorokův do Rámot Galád.'),
(1555954,54,12,9,5,'A když přišel, aj, knížata vojska seděli. I řekl: Mámť něco povědíti, ó kníže. I řekl Jéhu: Komu ze všech nás? Odpověděl: Tobě, ó kníže.'),
(1555955,54,12,9,6,'Vyvstav tedy, všel do vnitřku. I vylil olej na hlavu jeho a řekl jemu: Toto praví Hospodin, Bůh Izraelský: Pomazuji tebe za krále nad lidem Hospodinovým, nad Izraelem.'),
(1555956,54,12,9,7,'A zmorduješ dům Achaba pána svého; neboť pomstím krve služebníků svých proroků, a krve všech služebníků Hospodinových z ruky Jezábel.'),
(1555957,54,12,9,8,'A tak zahyne všecken dům Achabův, a vypléním z domu Achabova močícího na stěnu, a zajatého i zanechaného v Izraeli.'),
(1555958,54,12,9,9,'Učiním zajisté domu Achabovu, jako domu Jeroboámovu syna Nebatova, a jako domu Bázy syna Achiášova.'),
(1555959,54,12,9,10,'Jezábel pak sežerou psi na poli Jezreel, a nebude, kdo by ji pochoval. A rychle otevřev dvéře, utekl.'),
(1555960,54,12,9,11,'A když Jéhu vyšel k služebníkům pána svého, řekl mu jeden: Dobře-li se děje? Proč přišel ten blázen k tobě? Odpověděl jim: Vy znáte člověka i řeč jeho.'),
(1555961,54,12,9,12,'I řekli: Klamť jest, pověz nám medle. Kterýž řekl: Takto a takto mluvil mi, řka: Toto praví Hospodin: Pomazuji tě za krále nad Izraelem.'),
(1555962,54,12,9,13,'Tedy rychle vzali jeden každý roucho své, a prostřeli pod něj na nejvyšším stupni, a troubíce v troubu, pravili: Kralujeť Jéhu.'),
(1555963,54,12,9,14,'Zatím spuntoval se Jéhu syn Jozafata, syna Namsi, proti Joramovi, (když Joram ostříhaje Rámot Galád spolu se vším Izraelem, před Hazaelem králem Syrským,'),
(1555964,54,12,9,15,'Navrátil se byl Joram král, aby se hojil v Jezreel na rány, kterýmiž ho ranili Syrští, když bojoval proti Hazaelovi králi Syrskému). A řekl Jéhu: Vidí-li se vám, nechť nevychází žádný z města, kterýž by šel a oznámil to v Jezreel.'),
(1555965,54,12,9,16,'I vsedl na vůz Jéhu a jel do Jezreel, nebo Joram ležel tam. Ochoziáš také král Judský přijel byl, aby navštívil Jorama.'),
(1555966,54,12,9,17,'V tom strážný, kterýž stál na věži v Jezreel, když viděl houf Jéhu přicházející, řekl: Vidím jakýsi houf. I řekl Joram: Povolej jízdného, a pošli vstříc jim, aby se otázal: Jest-li pokoj?'),
(1555967,54,12,9,18,'I vyjel jízdný proti nim a řekl: Takto praví král: Jest-li pokoj? Odpověděl Jéhu: Co tobě do pokoje? Jeď za mnou. Protož oznámil to strážný, řka: Přijel posel až k nim, ale nevracuje se.'),
(1555968,54,12,9,19,'Ještě poslal druhého jízdného. Kterýž přijel k nim a řekl: Takto praví král: Jest-li pokoj? Odpověděl Jéhu: Co tobě do pokoje? Jeď za mnou.'),
(1555969,54,12,9,20,'Opět oznámil to strážný, řka: Přijel až k nim, ale nevrací se. Příjezd pak jest jako příjezd Jéhu syna Namsi; nebo vztekle jede.'),
(1555970,54,12,9,21,'Tedy řekl Joram: Zapřáhni. I zapřáhl k vozu jeho. Takž vyjel Joram král Izraelský a Ochoziáš král Judský, každý na voze svém, a vyjevše proti Jéhu, potkali se s ním na poli Nábota Jezreelského.'),
(1555971,54,12,9,22,'I stalo se, když uzřel Joram Jéhu, že řekl: Jest-liž pokoj, Jéhu? Odpověděl: Jaký pokoj, poněvadž ještě smilství Jezábel matky tvé a kouzelnictví její velmi mnohá trvají?'),
(1555972,54,12,9,23,'Pročež obrátiv se Joram, utíkal a řekl Ochoziášovi: Zrada, Ochoziáši!'),
(1555973,54,12,9,24,'Ale Jéhu pochytiv lučiště, postřelil Jorama mezi ramenem jeho, tak že střela pronikla srdce jeho. I padl na voze svém.'),
(1555974,54,12,9,25,'Zatím řekl Jéhu Badakerovi, hejtmanu svému: Vezma, povrz jej na pole Nábota Jezreelského; nebo pamatuješ, když jsme já a ty jeli spolu za Achabem otcem jeho, že Hospodin vynesl proti němu pohrůžku tuto, řka:'),
(1555975,54,12,9,26,'Zajisté krve Nábotovy a krve synů jeho, kterouž jsem viděl včera, řekl Hospodin, pomstím na tobě na poli tomto. Hospodin to řekl, nyní tedy vezma, povrz jej na pole, vedlé řeči Hospodinovy.'),
(1555976,54,12,9,27,'Ochoziáš pak král Judský uzřev to, utíkal cestou k domu zahradnímu. Ale honil ho Jéhu a řekl: I toho zabíte na voze jeho. Takž ho ranili, když vyjížděl k Guru, kteréž jest podlé Jibleam. I utekl do Mageddo a tam umřel.'),
(1555977,54,12,9,28,'Kteréhož vloživše na vůz služebníci jeho, vezli jej do Jeruzaléma, a pochovali jej v hrobě jeho s otci jeho v městě Davidově.'),
(1555978,54,12,9,29,'Léta jedenáctého Jorama syna Achabova počal kralovati Ochoziáš nad Judou.'),
(1555979,54,12,9,30,'Potom Jéhu přijel do Jezreel. O čemž když uslyšela Jezábel, ulíčila tvář svou, a ozdobila hlavu svou, a vyhlédala z okna.'),
(1555980,54,12,9,31,'A když Jéhu jel skrze bránu, řekla: Jest-li pokoj, ó Zamri, mordéři pána svého?'),
(1555981,54,12,9,32,'On pak pozdvih tváři své k oknu, řekl: Kdo drží se mnou, kdo? I vyhlédli na něj dva či tři komorníci její.'),
(1555982,54,12,9,33,'Jimž řekl: Svrzte ji. Kteřížto svrhli ji. I pokropena jest krví její stěna i koni; a tak pošlapal ji.'),
(1555983,54,12,9,34,'A když přijel, jedl a pil, a řekl: Pohleďte již na tu zlořečenou a pochovejte ji, nebť jest dcera královská.'),
(1555984,54,12,9,35,'Protož odšedše, aby ji pochovali, nenalezli z ní než leb a nohy a dlaně rukou.'),
(1555985,54,12,9,36,'A navrátivše se, pověděli jemu. Kterýž řekl: Slovo Hospodinovo jest, kteréž mluvil skrze služebníka svého, Eliáše Tesbitského, řka: Na poli Jezreel žráti budou psi tělo Jezábel.'),
(1555986,54,12,9,37,'Budiž tedy tělo Jezábel na poli Jezreel, jako hnůj na svrchku pole, tak aby žádný neřekl: Tato jest Jezábel.'),
(1555987,54,12,10,1,'Měl pak Achab sedmdesáte synů v Samaří. I napsal Jéhu list, a poslal jej do Samaří k knížatům Jezreelským, starším, a kteříž chovali syny Achabovy, s tímto poručením:'),
(1555988,54,12,10,2,'Hned jakž vás dojde list tento, poněvadž u vás jsou synové pána vašeho, jsou i vozové u vás, i koni, i město hrazené a zbroj,'),
(1555989,54,12,10,3,'Vybeřte nejlepšího a nejzpůsobnějšího z synů pána svého, a posaďte na stolici otce jeho, a bojujte za dům pána svého.'),
(1555990,54,12,10,4,'Kteříž bojíce se náramně, pravili: Aj, dva králové neostáli před ním, a kterak my ostojíme?'),
(1555991,54,12,10,5,'A tak poslal ten, kterýž byl ustanoven nad domem, a kterýž ustanoven byl nad městem, i starší, a kteříž chovali syny Achabovy, k Jéhu, řkouce: Služebníci tvoji jsme, a všecko, což nám rozkážeš, učiníme. Neustanovíme žádného krále; což se tobě dobře líbí, učiň.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1555992,54,12,10,6,'I napsal k nim list po druhé, řka: Jste-li moji a hlasu mého posloucháte-li, vezmouce hlavy všech synů pána svého, přiďte ke mně zítra o tomto času do Jezreel. (Synů pak králových bylo sedmdesáte mužů u nejpřednějších v městě, kteříž chovali je.)'),
(1555993,54,12,10,7,'Tedy stalo se, jakž jich došel list ten, že zjímali syny královské, a zbili sedmdesáte mužů, a vkladše hlavy jejich do košů, poslali je k němu do Jezreel.'),
(1555994,54,12,10,8,'A přišed posel, oznámil jemu, řka: Přinesli hlavy synů královských. A on řekl: Sklaďte je na dvě hromady u vrat brány až do jitra.'),
(1555995,54,12,10,9,'Potom ráno vyšed, postavil se a řekl všemu lidu: Spravedliví jste vy. Aj, já spuntoval jsem se proti pánu svému a zabil jsem jej; kdo by pobil tyto všecky?'),
(1555996,54,12,10,10,'Věztež nyní, žeť nepochybilo nižádné slovo Hospodinovo, kteréž mluvil Hospodin proti domu Achabovu, ale vykonal Hospodin to, což byl mluvil skrze služebníka svého Eliáše.'),
(1555997,54,12,10,11,'A tak pobil Jéhu všecky, kteříž pozůstali z domu Achabova v Jezreel, i všecky nejpřednější jeho, i známé jeho, i kněží jeho, tak že nezůstalo z nich žádného živého.'),
(1555998,54,12,10,12,'Potom vstav, odebral se a jel do Samaří, a již byl v Betekedu pastýřů na cestě.'),
(1555999,54,12,10,13,'I nalezl tam Jéhu bratří Ochoziáše, krále Judského, a řekl: Kdo jste vy? Odpověděli: Jsme bratří Ochoziášovi a jdeme, abychom pozdravili synů králových a synů královny.'),
(1556000,54,12,10,14,'Tedy řekl: Zjímejte je živé. I zjímali je živé, a pobili je u čisterny v Betekedu, čtyřidceti a dva muže, a nezůstal z nich žádný.'),
(1556001,54,12,10,15,'Potom bera se odtud, nalezl Jonadaba syna Rechabova, kterýž se s ním potkal, a pozdravil ho. I řekl jemu: Jest-liž srdce tvé přímé, jako jest srdce mé s srdcem tvým? Odpověděl Jonadab: Jest, arci jest. Řekl Jéhu: Podejž mi ruky své. I podal mu ruky své. A on kázal mu vsednouti k sobě na vůz,'),
(1556002,54,12,10,16,'A řekl: Pojeď se mnou, a viz horlivost mou pro Hospodina. A tak vezli jej na voze jeho.'),
(1556003,54,12,10,17,'Když pak přijel do Samaří, pobil všecky, kteříž byli pozůstali z domu Achabova v Samaří, a vyhladil jej vedlé řeči Hospodinovy, kterouž byl mluvil k Eliášovi.'),
(1556004,54,12,10,18,'Zatím shromáždiv Jéhu všecken lid, řekl jim: Achab málo sloužil Bálovi, Jéhu bude mu více sloužiti.'),
(1556005,54,12,10,19,'Protož nyní všecky proroky Bálovy, všecky služebníky jeho, a všecky kněží jeho svolejte ke mně, ať žádný tam nezůstává; nebo velikou obět budu obětovati Bálovi. Kdož by koli nebyl přítomen, nezůstane živ. Ale Jéhu činil to chytře, aby vyhladil ctitele Bálovy.'),
(1556006,54,12,10,20,'Řekl také Jéhu: Zasvěťte svátek Bálovi. I prohlásili jej.'),
(1556007,54,12,10,21,'Rozeslal zajisté Jéhu po vší zemi Izraelské. I sešli se všickni ctitelé Bálovi, tak že nezůstalo ani jednoho, ješto by nepřišel. A když vešli do domu Bálova, naplněn jest dům Bálův, od jednoho konce až do druhého.'),
(1556008,54,12,10,22,'Tedy řekl tomu, kterýž vládl rouchem: Vynes roucha všechněm ctitelům Bálovým. I přinesl jim roucha.'),
(1556009,54,12,10,23,'Potom všel i Jéhu a Jonadab syn Rechabův do domu Bálova, a řekl ctitelům Bálovým: Vyhledejte a vizte, ať není zde s vámi někdo z ctitelů Hospodinových, kromě samých ctitelů Bálových.'),
(1556010,54,12,10,24,'A tak vešli, aby obětovali oběti a zápaly. Jéhu pak postavil sobě vně osmdesáte mužů, jimž byl řekl: Jestliže kdo uteče z lidí těch, kteréž já uvozuji vám v ruce vaše, život váš za život jeho.'),
(1556011,54,12,10,25,'I stalo se, když kněz dokonal obětování zápalu, řekl Jéhu drabantům a hejtmanům: Vejdětež a zbíte je, ať žádný neuchází. Kteřížto pobili je ostrostí meče, a rozmetali těla jejich drabanti a hejtmané. Potom šli dále do každého města, kdež byl dům Bálův,'),
(1556012,54,12,10,26,'A vymítajíce modly z domu Bálova, pálili je.'),
(1556013,54,12,10,27,'Zkazili také modlu Bálovu, a zbořivše dům jeho, nadělali z něho záchodů až do dnešního dne.'),
(1556014,54,12,10,28,'A tak vyplénil Jéhu Bále z lidu Izraelského.'),
(1556015,54,12,10,29,'A však proto od hříchů Jeroboáma syna Nebatova, kterýž přivedl k hřešení Izraele, neodstoupil Jéhu, totiž od těch telat zlatých, kteráž byla v Bethel a v Dan.'),
(1556016,54,12,10,30,'Tedy řekl Hospodin Jéhu: Poněvadž jsi snažně vykonal to, což dobrého jest před očima mýma, a všecky věci, kteréž jsem měl v srdci svém, učinil jsi domu Achabovu, synové tvoji až do čtvrtého pokolení seděti budou na stolici Izraelské.'),
(1556017,54,12,10,31,'Ale Jéhu nebyl toho pilen, aby chodil v zákoně Hospodina, Boha Izraelského, celým srdcem svým, aniž odstoupil od hříchů Jeroboáma, kterýž byl uvedl v hříchy lid Izraelský.'),
(1556018,54,12,10,32,'Za těch dnů počal Hospodin zmenšovati Izraele; nebo je porazil Hazael po všech končinách Izraelských,'),
(1556019,54,12,10,33,'Od Jordánu, proti východu slunce, všecku zemi Galád, Gádovu a Rubenovu i Manassesovu, od Aroer, kteréž jest při potoku Arnon, tak Galád jako Bázan.'),
(1556020,54,12,10,34,'O jiných věcech Jéhu, a cožkoli činil, i o vší síle jeho, sepsáno jest v knize o králích Izraelských.'),
(1556021,54,12,10,35,'I usnul Jéhu s otci svými, a pochovali jej v Samaří, a kraloval Joachaz syn jeho místo něho.'),
(1556022,54,12,10,36,'Dnů pak, v nichž kraloval Jéhu nad lidem Izraelským v Samaří, bylo let osmmecítma.'),
(1556023,54,12,11,1,'Atalia pak matka Ochoziášova viduci, že umřel syn její, vstavši, pomordovala všecko símě královské.'),
(1556024,54,12,11,2,'Ale Jozaba dcera krále Jehorama, sestra Ochoziášova, vzala Joasa syna Ochoziášova, a ukradši ho z prostředku synů královských, kteříž mordováni byli, skryla jej i s chůvou jeho v pokoji, kdež lůže byla. A tak skryli ho před Atalií, a není zamordován.'),
(1556025,54,12,11,3,'I byl s ní v domě Hospodinově tajně za šest let, v nichž Atalia kralovala nad zemí.'),
(1556026,54,12,11,4,'Léta sedmého poslav Joiada, povolal setníků, hejtmanů a drabantů. I uvedl je k sobě do domu Hospodinova, a učinil s nimi smlouvu, a zavázav je přísahou v domě Hospodinově, ukázal jim syna králova.'),
(1556027,54,12,11,5,'A přikázal jim, řka: Tato jest věc, kterouž učiníte: Třetí díl vás, kteříž přicházíte v sobotu, a držíte stráž, bude při domě králově,'),
(1556028,54,12,11,6,'A díl třetí bude u brány Sur, a třetí díl bude u brány za drabanty, a budete stráž držeti, ostříhajíce domu tohoto před outokem.'),
(1556029,54,12,11,7,'Vy pak všickni, kteříž byste odjíti měli v sobotu, po vykonání povinnosti při domě Hospodinově, ve dvě poboční stráže rozdělení, buďte při králi.'),
(1556030,54,12,11,8,'A tak obstoupíte krále vůkol, jeden každý majíce braň svou v rukou svých. Kdož by pak šel do šiku vašeho, ať umře; a budete při králi, když bude vycházeti i když bude vcházeti.'),
(1556031,54,12,11,9,'Protož učinili setníci ti všecky věci tak, jakž byl rozkázal Joiada kněz, a vzavše jeden každý muže své, kteříž přicházeli v sobotu a kteříž odcházeli v sobotu, přišli k Joiadovi knězi.'),
(1556032,54,12,11,10,'I dal kněz setníkům kopí a pavézy, kteréž byly Davida krále, a kteréž byly v domě Hospodinově.'),
(1556033,54,12,11,11,'Stáli pak ti drabanti, jeden každý držíce braň svou v ruce své, od pravé strany domu až do levé strany domu, proti oltáři a proti domu při králi vůkol.'),
(1556034,54,12,11,12,'Tedy vyvedl syna králova, a vstavil na něj korunu a ozdobu. I ustanovili jej králem a pomazali ho, a plésajíce rukama, říkali: Živ buď král!'),
(1556035,54,12,11,13,'V tom uslyševši Atalia hluk plésajícího lidu, vešla k lidu do domu Hospodinova.'),
(1556036,54,12,11,14,'A když pohleděla, a aj, král stál na místě vyšším, vedlé obyčeje s knížaty, a trouby byly před králem, a všecken lid země byl vesel, i troubili v trouby. Tedy roztrhla Atalia roucho své a zkřikla: Spiknutí, spiknutí!'),
(1556037,54,12,11,15,'Protož rozkázal Joiada kněz těm setníkům ustaveným nad vojskem, řka jim: Pusťte ji prostředkem řadu, a i toho, kdož by za ní šel, zabíte mečem. Nebo byl řekl kněz: Ať není zabita v domě Hospodinově.'),
(1556038,54,12,11,16,'I pustili ji. Ale když přišla na cestu, kudy koni vcházejí do domu královského, tu jest zabita.'),
(1556039,54,12,11,17,'Tedy učinil Joiada smlouvu mezi Hospodinem a mezi králem, i mezi lidem, aby byli lid Hospodinův; též mezi králem a mezi lidem.'),
(1556040,54,12,11,18,'Potom šel všecken lid země do domu Bálova, a zbořili jej, i oltáře jeho a obrazy jeho v kusy stroskotali; Matana také kněze Bálova zabili před oltáři. Kněz pak znovu nařídil přisluhující v domě Hospodinově.'),
(1556041,54,12,11,19,'A pojav ty setníky a hejtmany, i drabanty se vším lidem země, provázeli krále z domu Hospodinova, a přišli cestou k bráně drabantů do domu královského. Kdežto posadil se na stolici královské.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556042,54,12,11,20,'I veselil se všecken lid země, a město se upokojilo. Atalii pak zabili mečem u domu královského.'),
(1556043,54,12,11,21,'A byl Joas v sedmi letech, když počal kralovati.'),
(1556044,54,12,12,1,'Léta sedmého Jéhu počal kralovati Joas, a kraloval čtyřidceti let v Jeruzalémě. Jméno matky jeho bylo Sebia z Bersabé.'),
(1556045,54,12,12,2,'I činil Joas, což dobrého jest před očima Hospodinovýma po všecky dny své, pokudž ho vyučoval Joiada kněz.'),
(1556046,54,12,12,3,'A však výsosti nebyly zkaženy, ještě lid obětoval a kadil na těch výsostech.'),
(1556047,54,12,12,4,'Řekl pak Joas kněžím: Všecky peníze svaté, kteréž se vnášejí do domu Hospodinova, totiž peníze těch, kteříž jdou v počet, a peníze ceny za osobu jednoho každého, a všecky peníze, kteréž by kdo dobrovolně uložil dáti do domu Hospodinova,'),
(1556048,54,12,12,5,'Vezmou kněží k sobě, jeden každý od známého svého, a oni opraví zbořeniny domu všudy, kdež by bylo zboření.'),
(1556049,54,12,12,6,'Stalo se potom léta dvadcátého třetího krále Joasa, když ještě neopravili kněží zbořenin chrámových,'),
(1556050,54,12,12,7,'Že povolal král Joas Joiady kněze i jiných kněží, a řekl jim: Proč neopravujete zbořenin chrámových? Protož nyní nepřijímejte peněz od známých svých, ale na zbořeniny domu dávejte je.'),
(1556051,54,12,12,8,'Jemuž povolivše kněží, nebrali peněz od lidu, ani neopravovali domu.'),
(1556052,54,12,12,9,'Protož Joiada kněz vzav jednu truhlici, udělal díru v víku jejím, a postavil ji vedlé oltáře po pravé straně, kudy se vchází do domu Hospodinova. I postavili tu kněží ostříhající prahu i všech peněz, kteréž vnášíny byly do domu Hospodinova.'),
(1556053,54,12,12,10,'A když rozuměli, že by mnoho peněz bylo v truhlici, tedy přicházel kancléř královský a kněz nejvyšší, a sčetše, schovávali ty peníze, kteréž se nalézaly v domě Hospodinově.'),
(1556054,54,12,12,11,'Odkudž vydávali peníze hotové v ruce řemeslníků postavených nad dílem domu Hospodinova, a ti obraceli je na tesaře a dělníky, kteříž opravovali dům Hospodinův,'),
(1556055,54,12,12,12,'Totiž na zedníky a kameníky, a k jednání dříví i tesaného kamení, aby opraveny byly zbořeniny domu Hospodinova, i na všecko to, což obráceno mělo býti na dům k opravě jeho.'),
(1556056,54,12,12,13,'A však nebylo děláno do domu Hospodinova číší stříbrných, žaltářů, kotlíků, trub a žádné nádoby zlaté, ani nádoby stříbrné z peněz, kteréž přinášíny byly do domu Hospodinova,'),
(1556057,54,12,12,14,'Ale těm, kteříž představeni byli nad dílem, dávali je, a opravovali na ně dům Hospodinův.'),
(1556058,54,12,12,15,'Aniž žádali počtu od mužů těch, jimž v ruce peníze dávali, aby platili dělníkům; nebo věrně dělali.'),
(1556059,54,12,12,16,'Peněz za vinu, a peněz za hříchy nebylo vnášíno do domu Hospodinova; kněžím se dostávaly.'),
(1556060,54,12,12,17,'Tedy vytáhl Hazael král Syrský, a bojoval proti Gát a dobyl ho. Potom obrátil Hazael tvář svou, aby táhl proti Jeruzalému.'),
(1556061,54,12,12,18,'Protož pobral Joas král Judský všecky věci svaté, kterýchž byli nadali Jozafat a Jehoram a Ochoziáš, otcové jeho, králové Judští, i to, čehož sám posvětil, i všecko zlato, kteréž se nalezlo v pokladích domu Hospodinova a domu královského, a poslal k Hazaelovi králi Syrskému. I odtáhl od Jeruzaléma.'),
(1556062,54,12,12,19,'O jiných pak činech Joasových, a cožkoli činil, psáno jest v knize o králích Judských.'),
(1556063,54,12,12,20,'Potom povstavše služebníci jeho, spikli se spolu, a zabili Joasa v Betmillo, kudy se chodí do Silla,'),
(1556064,54,12,12,21,'Totiž Jozachar syn Simatův, a Jozabad syn Somerův. Ti služebníci jeho zabili ho, a umřel. I pochovali jej s otci jeho v městě Davidově, a kraloval Amaziáš syn jeho místo něho.'),
(1556065,54,12,13,1,'Léta třimecítmého Joasa syna Ochoziáše, krále Judského, kraloval Joachaz syn Jéhu nad Izraelem v Samaří sedmnácte let.'),
(1556066,54,12,13,2,'A činil to, což jest zlého před očima Hospodinovýma; nebo následoval hříchů Jeroboáma syna Nebatova, kterýž přivedl k hřešení Izraele, a neuchýlil se od nich.'),
(1556067,54,12,13,3,'I rozhněvala se prchlivost Hospodinova na Izraele, a vydal je v ruku Hazaele krále Syrského, a v ruku Benadada syna Hazaelova po všecky ty dny.'),
(1556068,54,12,13,4,'Ale když se modlil Joachaz Hospodinu, vyslyšel jej Hospodin. Viděl zajisté trápení Izraelské, že je ssužoval král Syrský.'),
(1556069,54,12,13,5,'Protož dal Hospodin Izraelovi vysvoboditele, a vyšli z ruky Syrských, i bydlili synové Izraelští v příbytcích svých jako kdy prvé.'),
(1556070,54,12,13,6,'Však proto neodstoupili od hříchů domu Jeroboámova, kterýž přivedl k hřešení Izraele, nýbrž v nich chodili, ano i háj ještě zůstával v Samaří,'),
(1556071,54,12,13,7,'Ačkoli nezanechal Joachazovi lidu, kromě padesáti jízdných a desíti vozů a desíti tisíců pěších; nebo je pohubil král Syrský, a setřel je jako prach při mlácení.'),
(1556072,54,12,13,8,'O jiných pak činech Joachazových, a cožkoli činil, i o síle jeho zapsáno jest v knize o králích Izraelských.'),
(1556073,54,12,13,9,'I usnul Joachaz s otci svými, a pochovali ho v Samaří. Kraloval pak Joas syn jeho místo něho.'),
(1556074,54,12,13,10,'Léta třidcátého sedmého Joasa krále Judského kraloval Joas syn Joachazův nad Izraelem v Samaří šestnácte let.'),
(1556075,54,12,13,11,'A činil to, což jest zlého před očima Hospodinovýma, neuchýliv se od žádných hříchů Jeroboáma syna Nebatova, kterýž přivedl k hřešení Izraele, ale chodil v nich.'),
(1556076,54,12,13,12,'O jiných pak činech Joasových, i cožkoli činil, i o síle jeho, kterouž bojoval proti Amaziášovi králi Judskému, zapsáno jest v knize o králích Izraelských.'),
(1556077,54,12,13,13,'I usnul Joas s otci svými, a sedl Jeroboám na stolici jeho. I pochován jest Joas v Samaří s králi Izraelskými.'),
(1556078,54,12,13,14,'Elizeus pak roznemohl se nemocí těžkou, v kteréž i umřel. A přišel byl k němu Joas král Izraelský, a pláče nad ním, řekl: Otče můj, otče můj, vozové Izraelští a jízdo jeho!'),
(1556079,54,12,13,15,'Ale Elizeus řekl jemu: Vezmi lučiště a střely. I vzav, přinesl k němu lučiště a střely.'),
(1556080,54,12,13,16,'Řekl dále králi Izraelskému: Vezmi v ruku svou lučiště. I vzal je v ruku svou. Vložil také Elizeus ruce své na ruce královy.'),
(1556081,54,12,13,17,'A řekl: Otevři to okno k východu. A když otevřel, řekl Elizeus: Střeliž. I střelil. Tedy řekl: Střela spasení Hospodinova a střela vysvobození proti Syrským; nebo porazíš Syrské v Afeku, až i do konce vyhladíš je.'),
(1556082,54,12,13,18,'Opět řekl: Vezmi střely. I vzal. Tedy řekl králi Izraelskému: Střílej k zemi. I střelil po třikrát, potom tak nechal.'),
(1556083,54,12,13,19,'Pročež rozhněvav se na něj muž Boží, řekl: Měls pětkrát neb šestkrát střeliti, ješto bys byl porazil Syrské, ažbys je i do konce byl vyhladil; nyní pak jen po třikrát porazíš Syrské.'),
(1556084,54,12,13,20,'Potom umřel Elizeus, a pochovali ho. Lotříkové pak Moábští vtrhli do země nastávajícího roku.'),
(1556085,54,12,13,21,'I stalo se, když pochovávali jednoho, že uzřevše ty lotříky, uvrhli muže toho do hrobu Elizeova. Kterýžto muž, jakž tam padl, a dotekl se kostí Elizeových, ožil a vstal na nohy své.'),
(1556086,54,12,13,22,'Hazael pak král Syrský, ssužoval Izraele po všecky dny Joachaza.'),
(1556087,54,12,13,23,'A milostiv jsa jim Hospodin, slitoval se nad nimi, a popatřil na ně, pro smlouvu svou s Abrahamem, s Izákem a s Jákobem, a nechtěl jich zahladiti, aniž zavrhl jich od tváři své až do tohoto času.'),
(1556088,54,12,13,24,'I umřel Hazael král Syrský, a kraloval Benadad syn jeho místo něho.'),
(1556089,54,12,13,25,'Protož Joas syn Joachazův pobral zase města z ruky Benadada syna Hazaelova, kteráž byl vzal z ruky Joachaza otce jeho válečně; nebo po třikrát porazil ho Joas, a navrátil města Izraelská.'),
(1556090,54,12,14,1,'Léta druhého Joasa syna Joachaza, krále Izraelského, kraloval Amaziáš syn Joasa, krále Judského.'),
(1556091,54,12,14,2,'V pětmecítma letech byl, když počal kralovati, a kraloval dvadceti devět let v Jeruzalémě. Jméno matky jeho Joadan z Jeruzaléma.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556092,54,12,14,3,'Ten činil to, což dobrého jest před očima Hospodinovýma, ačkoli ne tak jako David otec jeho. Všecko, což činil Joas otec jeho, tak činil.'),
(1556093,54,12,14,4,'A však výsostí nezkazili, ještě lid obětoval a kadil na výsostech.'),
(1556094,54,12,14,5,'I stalo se, když upevněno bylo království v ruce jeho, že pobil služebníky své, kteříž byli zabili krále otce jeho.'),
(1556095,54,12,14,6,'Synů pak těch vražedlníků nepobil, jakož jest psáno v knize zákona Mojžíšova, kdež přikázal Hospodin, řka: Nebudouť na hrdle trestáni otcové za syny, aniž synové trestáni budou na hrdle za otce, ale jeden každý za svůj hřích umře.'),
(1556096,54,12,14,7,'On také porazil Idumejských v údolí solnatém deset tisíců, a dobyl Sela bojem. I nazval jméno jeho Jektehel až do tohoto dne.'),
(1556097,54,12,14,8,'Tedy poslal Amaziáš posly k Joasovi synu Joachaza, syna Jéhu krále Izraelského, řka: Nuže, pohleďme sobě v oči.'),
(1556098,54,12,14,9,'Zase poslal Joas král Izraelský k Amaziášovi králi Judskému a řekl: Bodlák, kterýž byl na Libánu, poslal k cedru Libánskému, řka: Dej dceru svou synu mému za manželku. V tom šlo tudy zvíře polní, kteréž bylo na Libánu, a pošlapalo ten bodlák.'),
(1556099,54,12,14,10,'Že jsi mocně porazil Idumejské, protož pozdvihlo tě srdce tvé. Chlub se a seď v domě svém. I proč se máš plésti v neštěstí, abys padl ty i Juda s tebou?'),
(1556100,54,12,14,11,'Ale Amaziáš neuposlechl. Protož vytáhl Joas král Izraelský, a pohleděli sobě v oči, on s Amaziášem králem Judským u Betsemes Judova.'),
(1556101,54,12,14,12,'I poražen jest Juda od Izraele, a utíkali jeden každý do příbytků svých.'),
(1556102,54,12,14,13,'Amaziáše pak krále Judského, syna Joasa syna Ochoziášova, jal Joas král Izraelský u Betsemes, a přitáh do Jeruzaléma, zbořil zed Jeruzalémskou, od brány Efraim až k bráně úhlu, na čtyři sta loktů.'),
(1556103,54,12,14,14,'A pobral všecko zlato i stříbro, a všecky nádoby, kteréž se nalézaly v domě Hospodinově a v pokladích domu královského, také i mládence zastavené, a navrátil se do Samaří.'),
(1556104,54,12,14,15,'O jiných pak činech Joasa, kteréž činil, i síle jeho, a kterak bojoval proti Amaziášovi králi Judskému, psáno jest v knize o králích Izraelských.'),
(1556105,54,12,14,16,'I usnul Joas s otci svými, a pochován jest v Samaří s králi Izraelskými, i kraloval Jeroboám syn jeho místo něho.'),
(1556106,54,12,14,17,'Živ pak byl Amaziáš syn Joasův, král Judský, po smrti Joasa syna Joachaza, krále Izraelského, patnácte let.'),
(1556107,54,12,14,18,'O jiných pak věcech Amaziášových psáno jest v knize o králích Judských.'),
(1556108,54,12,14,19,'Potom spuntovali se proti němu v Jeruzalémě, a on utekl do Lachis. Protož poslali za ním do Lachis, a zamordovali ho tam.'),
(1556109,54,12,14,20,'Odkudž odnesli jej na koních, a pochován jest v Jeruzalémě s otci svými v městě Davidově.'),
(1556110,54,12,14,21,'Tedy všecken lid Judský vzali Azariáše, kterýž byl v šestnácti letech, a ustanovili ho za krále na místě otce jeho Amaziáše.'),
(1556111,54,12,14,22,'Onť jest vzdělal Elat a dobyl ho Judovi, když byl již usnul král s otci svými.'),
(1556112,54,12,14,23,'Léta patnáctého Amaziáše syna Joasa, krále Judského, kraloval Jeroboám syn Joasa, krále Izraelského, v Samaří čtyřidceti a jedno léto.'),
(1556113,54,12,14,24,'A činil to, což jest zlého před očima Hospodinovýma, neuchýliv se od žádných hříchů Jeroboáma syna Nebatova, kterýž k hřešení přivedl Izraele.'),
(1556114,54,12,14,25,'On zase dobyl končin Izraelských od toho místa, kudy se jde do Emat, až k moři pustému, vedlé řeči Hospodina Boha Izraelského, kterouž byl mluvil skrze služebníka svého Jonáše syna Amaty proroka, kterýž byl z Gethefer.'),
(1556115,54,12,14,26,'Nebo viděl Hospodin trápení Izraele těžké náramně, a že jakož zajatý, tak i zanechaný s nic býti nemůže, aniž jest, kdo by spomohl Izraelovi.'),
(1556116,54,12,14,27,'A nemluvil Hospodin, že by chtěl zahladiti jméno Izraele, aby ho nebylo pod nebem; protož vysvobodil je skrze Jeroboáma syna Joasova.'),
(1556117,54,12,14,28,'O jiných pak věcech Jeroboámových, a cožkoli činil, i o síle jeho, a kterak bojoval, jak zase dobyl Damašku a Emat Judova Izraelovi, psáno jest v knize o králích Izraelských.'),
(1556118,54,12,14,29,'I usnul Jeroboám s otci svými, s králi Izraelskými, a kraloval Zachariáš syn jeho místo něho.'),
(1556119,54,12,15,1,'Léta sedmmecítmého Jeroboáma krále Izraelského kraloval Azariáš syn Amaziáše, krále Judského.'),
(1556120,54,12,15,2,'V šestnácti letech byl, když počal kralovati, a kraloval padesáte dvě létě v Jeruzalémě. Jméno matky jeho bylo Jecholia z Jeruzaléma.'),
(1556121,54,12,15,3,'Ten činil, což dobrého jest před očima Hospodinovýma vedlé všech věcí, kteréž činil Amaziáš otec jeho.'),
(1556122,54,12,15,4,'A však výsostí nezkazili, ještě lid obětoval a kadil na výsostech.'),
(1556123,54,12,15,5,'Ranil pak Hospodin krále, tak že byl malomocný až do dne smrti své, a bydlil v domě obzvláštním. Pročež Jotam syn královský držel správu nad domem, soudě lid země.'),
(1556124,54,12,15,6,'O jiných pak činech Azariášových, i cožkoli činil, psáno jest v knize o králích Judských.'),
(1556125,54,12,15,7,'I usnul Azariáš s otci svými, a pochovali jej s otci jeho v městě Davidově, a kraloval Jotam syn jeho místo něho.'),
(1556126,54,12,15,8,'Léta třidcátého osmého Azariáše krále Judského kraloval Zachariáš syn Jeroboamův nad Izraelem v Samaří šest měsíců.'),
(1556127,54,12,15,9,'A činil to, což jest zlého před očima Hospodinovýma, jakž činívali otcové jeho, neuchýliv se od hříchů Jeroboáma syna Nebatova, kterýž přivedl k hřešení Izraele.'),
(1556128,54,12,15,10,'I spikl se proti němu Sallum syn Jábes a bil ho před lidem, i zabil jej a kraloval místo něho.'),
(1556129,54,12,15,11,'O jiných pak věcech Zachariášových zapsáno jest v knize o králích Izraelských.'),
(1556130,54,12,15,12,'Toť jest slovo Hospodinovo, kteréž mluvil k Jéhu, řka: Synové tvoji do čtvrtého kolena seděti budou na stolici Izraelské. A tak se stalo.'),
(1556131,54,12,15,13,'Sallum syn Jábesův kraloval léta třidcátého devátého Uziáše krále Judského, a kraloval jeden měsíc v Samaří.'),
(1556132,54,12,15,14,'Nebo přitáhl Manahem syn Gádi z Tersa, a přišed do Samaří, porazil Sallum syna Jábes v Samaří, a zabiv jej, kraloval na místě jeho.'),
(1556133,54,12,15,15,'O jiných pak činech Sallum i spiknutí jeho, kteréž učinil, zapsáno jest v knize o králích Izraelských.'),
(1556134,54,12,15,16,'Tehdy pohubil Manahem město Tipsach, a všecky, kteříž byli v něm, i všecky končiny jeho od Tersa, proto že mu ho neotevřeli. I pomordoval je, a všecky těhotné jejich zroztínal.'),
(1556135,54,12,15,17,'Léta třidcátého devátého Azariáše krále Judského kraloval Manahem syn Gádi nad Izraelem v Samaří za deset let.'),
(1556136,54,12,15,18,'A činil to, což jest zlého před očima Hospodinovýma, neodvrátiv se od hříchů Jeroboáma syna Nebatova, (kterýž přivedl Izraele k hřešení), po všecky dny své.'),
(1556137,54,12,15,19,'Když pak vytáhl Ful král Assyrský proti zemi té, dal Manahem Fulovi deset tisíc centnéřů stříbra, aby mu byl nápomocen k utvrzení království v rukou jeho.'),
(1556138,54,12,15,20,'I uložil Manahem daň na Izraele, na všecky bohaté, aby dávali králi Assyrskému jeden každý po padesáti lotech stříbra. Takž obrátiv se král Assyrský, nemeškal se více tu v zemi.'),
(1556139,54,12,15,21,'O jiných pak činech Manahemových, a cožkoli činil, zapsáno jest v knize o králích Izraelských.'),
(1556140,54,12,15,22,'I usnul Manahem s otci svými, a kraloval Pekachia syn jeho místo něho.'),
(1556141,54,12,15,23,'Léta padesátého Azariáše, krále Judského, kraloval Pekachia syn Manahemův nad Izraelem v Samaří dvě létě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556142,54,12,15,24,'A činil to, což jest zlého před očima Hospodinovýma, neuchýliv se od hříchů Jeroboáma syna Nebatova, kterýž k hřešení přivedl Izraele.'),
(1556143,54,12,15,25,'Tedy spuntoval se proti němu Pekach syn Romeliův, hejtman jeho, s Argobem i s Ariášem, a zabil jej v Samaří na paláci domu královského, maje s sebou padesáte mužů Galádských. A zabiv jej, kraloval místo něho.'),
(1556144,54,12,15,26,'Jiní pak skutkové Pekachia a všecko, což činil, zapsáno jest v knize o králích Izraelských.'),
(1556145,54,12,15,27,'Léta padesátého druhého Azariáše krále Judského kraloval Pekach syn Romeliův nad Izraelem v Samaří dvadceti let.'),
(1556146,54,12,15,28,'A činil to, což jest zlého před očima Hospodinovýma, aniž odstoupil od hříchů Jeroboáma syna Nebatova, kterýž k hřešení přivedl Izraele.'),
(1556147,54,12,15,29,'Za dnů Pekacha krále Izraelského přitáhl Tiglatfalazar král Assyrský, a vzal Jon a Abel, dům Maacha a Janoe, Kedes a Azor, i Galád a Galilei, i všecku zemi Neftalím, a přenesl obyvatele jejich do Assyrie.'),
(1556148,54,12,15,30,'Tedy spuntoval se Ozee syn Ela, proti Pekachovi synu Romeliovu, a raniv ho, zabil jej, a kraloval na místě jeho léta dvadcátého Jotama syna Uziášova.'),
(1556149,54,12,15,31,'O jiných pak činech Pekachových, a cožkoli činil, zapsáno jest v knize o králích Izraelských.'),
(1556150,54,12,15,32,'Léta druhého Pekacha syna Romelia, krále Izraelského, kraloval Jotam syn Uziáše, krále Judského.'),
(1556151,54,12,15,33,'V pětmecítma letech byl, když počal kralovati, a šestnácte let kraloval v Jeruzalémě. Jméno matky jeho Jerusa, dcera Sádochova.'),
(1556152,54,12,15,34,'A činil to, což pravého jest před očima Hospodinovýma. Všecko, jakž činil Uziáš otec jeho, tak činil.'),
(1556153,54,12,15,35,'A však výsosti nebyly zkaženy, ještě lid obětoval a kadil na výsostech. On vystavěl bránu hořejší domu Hospodinova.'),
(1556154,54,12,15,36,'O jiných pak činech Jotamových, a cožkoli činil, zapsáno jest v knize o králích Judských.'),
(1556155,54,12,15,37,'Za dnů těch počal Hospodin posílati na Judu Rezina krále Syrského a Pekacha syna Romeliova.'),
(1556156,54,12,15,38,'I usnul Jotam s otci svými, a pochován jest s otci svými v městě Davida otce svého. I kraloval Achas syn jeho místo něho.'),
(1556157,54,12,16,1,'Sedmnáctého léta Pekacha syna Romeliova kraloval Achas syn Jotama, krále Judského.'),
(1556158,54,12,16,2,'Ve dvadcíti letech byl Achas, když kralovati počal, a šestnácte let kraloval v Jeruzalémě, ale nečinil toho, což pravého jest, před Hospodinem Bohem svým, jako David otec jeho.'),
(1556159,54,12,16,3,'Nýbrž chodil po cestě králů Izraelských; nadto i syna svého dal provésti skrze oheň vedlé ohavností pohanských, kteréž byl Hospodin vyplénil před oblíčejem synů Izraelských.'),
(1556160,54,12,16,4,'Obětoval také a kadil na výsostech a na pahrbcích, i pod každým stromem zeleným.'),
(1556161,54,12,16,5,'Tedy vytáhl Rezin král Syrský a Pekach syn Romeliášův, král Izraelský, proti Jeruzalému k boji, a oblehli Achasa. Ale nemohli ho dobyti.'),
(1556162,54,12,16,6,'(Toho času Rezin král Syrský odtrhl zase město Elat k Syrii, a vyplénil Židy z Elot; Syrští pak přišedše do Elat, bydlili tam až do dnešního dne.)'),
(1556163,54,12,16,7,'I poslal Achas posly k Tiglatfalazarovi králi Assyrskému, řka: Služebník tvůj a syn tvůj jsem, přitáhni a vysvoboď mne z ruky krále Syrského, a z ruky krále Izraelského, kteříž povstali proti mně.'),
(1556164,54,12,16,8,'A pobrav Achas stříbro a zlato, kteréž se nalézti mohlo v domě Hospodinově a v pokladích domu královského, poslal králi Assyrskému dar.'),
(1556165,54,12,16,9,'Tedy povolil jemu král Assyrský, a přitáhl k Damašku a dobyl ho, a přenesl obyvatele jeho do Kir, Rezina pak zabil.'),
(1556166,54,12,16,10,'I vypravil se král Achas vstříc Tiglatfalazarovi králi Assyrskému do Damašku. A uzřev král Achas oltář v Damašku, poslal k Uriášovi knězi podobenství toho oltáře, a formu jeho vedlé všelikého díla jeho.'),
(1556167,54,12,16,11,'I vzdělal Uriáš kněz oltář vedlé všeho toho, což byl poslal král Achas z Damašku. Tak učinil kněz Uriáš, prvé než se vrátil král Achas z Damašku.'),
(1556168,54,12,16,12,'Když se pak navrátil král z Damašku, uzřev ten oltář přistoupil k němu a obětoval na něm.'),
(1556169,54,12,16,13,'A tak zapálil zápal svůj i suchou obět svou, a obětoval obět mokrou svou, a pokropil krví oltáře z pokojných obětí svých.'),
(1556170,54,12,16,14,'Oltář pak měděný, kterýž byl před Hospodinem, přenesl z přední strany domu, aby nestál mezi oltářem jeho a mezi domem Hospodinovým, a postavil jej po boku oltáře svého k půlnoci.'),
(1556171,54,12,16,15,'I přikázal král Achas knězi Uriášovi, řka: Na větším oltáři obětuj zápaly jitřní, a obět suchou večerní, a obět zápalnou královskou s obětí suchou její, i obět zápalnou všeho lidu země, a oběti suché jejich, i oběti mokré jejich, a všelikou krví zápalu a všelikou krví oběti kropiti budeš na něj, oltář pak měděný bude mi k doptávání se Boha.'),
(1556172,54,12,16,16,'Tedy učinil Uriáš kněz všecko, jakž mu přikázal Achas.'),
(1556173,54,12,16,17,'Osekal také král Achas přepásaní podstavků, a odjal od nich pánve, a moře složil s volů měděných, kteříž byli pod ním, a položil je na dlážení kamenné.'),
(1556174,54,12,16,18,'Zastření také sobotní, kteréž byli udělali v domě, a vcházení královské z zevnitř odjal od domu Hospodinova, boje se krále Assyrského.'),
(1556175,54,12,16,19,'Jiní pak skutkové krále Achasa, kteréž činil, zapsáni jsou v knize o králích Judských.'),
(1556176,54,12,16,20,'I usnul Achas s otci svými, a pochován jest s nimi v městě Davidově, a kraloval Ezechiáš syn jeho místo něho.'),
(1556177,54,12,17,1,'Léta dvanáctého Achasa krále Judského kraloval Ozee syn Ela v Samaří nad Izraelem devět let.'),
(1556178,54,12,17,2,'A činil to, což jest zlého před očima Hospodinovýma, ač ne tak jako jiní králové Izraelští, kteříž byli před ním.'),
(1556179,54,12,17,3,'Proti němuž přitáhl Salmanazar král Assyrský. I učiněn jest Ozee služebníkem jeho, a dával mu plat.'),
(1556180,54,12,17,4,'Shledal pak král Assyrský při Ozee puntování; nebo poslal posly k Sua králi Egyptskému, a neposílal králi Assyrskému ročního platu. Protož oblehl ho král Assyrský, a svázaného dal do žaláře.'),
(1556181,54,12,17,5,'I táhl král Assyrský po vší zemi; přitáhl také do Samaří, a ležel u ní tři léta.'),
(1556182,54,12,17,6,'Léta pak devátého Ozee vzal král Assyrský Samaří, a přenesl Izraele do Assyrie, a osadil je v Chelach a v Chabor při řece Gozan, a v městech Médských.'),
(1556183,54,12,17,7,'To se stalo, proto že hřešili synové Izraelští proti Hospodinu Bohu svému, kterýž je vyvedl z země Egyptské, aby nebyli pod mocí Faraona krále Egyptského, a ctili bohy cizí,'),
(1556184,54,12,17,8,'Chodíce v ustanoveních pohanů, (kteréž byl vyvrhl Hospodin od tváři synů Izraelských), a králů Izraelských, kteráž nařídili.'),
(1556185,54,12,17,9,'Přesto pokrytě se měli synové Izraelští, činíce to, což není dobrého před Hospodinem Bohem svým, a vzdělali sobě výsosti ve všech městech svých, od věže strážných až do města hrazeného.'),
(1556186,54,12,17,10,'A nastavěli sobě obrazů i hájů na všelikém pahrbku vysokém, a pod každým stromem zeleným,'),
(1556187,54,12,17,11,'Zapalujíce tam vonné věci na všech výsostech, rovně jako pohané, kteréž vyhnal Hospodin od tváři jejich. A činili věci nejhorší, popouzejíce Hospodina.'),
(1556188,54,12,17,12,'A sloužili bohům nečistým, o nichž byl Hospodin řekl jim, aby nečinili toho.'),
(1556189,54,12,17,13,'I osvědčoval Hospodin proti Izraelovi a proti Judovi skrze všecky proroky i všecky vidoucí, řka: Odvraťte se od cest svých zlých, a ostříhejte přikázaní mých a ustanovení mých vedlé všeho zákona, kterýž jsem vydal otcům vašim, a kterýž jsem poslal k vám skrze služebníky své proroky.'),
(1556190,54,12,17,14,'Však neposlechli, ale zatvrdili šíji svou, jako i otcové jejich šíje své, kteříž nevěřili v Hospodina Boha svého.'),
(1556191,54,12,17,15,'A opovrhli ustanovení jeho i smlouvu jeho, kterouž učinil s otci jejich, i osvědčování jeho, kterýmiž se jim osvědčoval, a odešli po marnosti, a marní učiněni jsou, následujíce pohanů, kteříž byli vůkol nich, o nichž jim byl přikázal Hospodin, aby nečinili jako oni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556192,54,12,17,16,'A opustivše všecka přikázaní Hospodina Boha svého, udělali sobě slitinu, dvé telat a háj, a klaněli se všemu vojsku nebeskému; sloužili také Bálovi.'),
(1556193,54,12,17,17,'A vodili syny své a dcery své skrze oheň, a obírali se s hádáním a kouzly, a tak vydali se v činění toho, což jest zlé před očima Hospodinovýma, popouzejíce ho.'),
(1556194,54,12,17,18,'Protož rozhněval se Hospodin náramně na Izraele, a zahnal je od tváři své, nezanechav z nich nic, kromě samého pokolení Judova.'),
(1556195,54,12,17,19,'Ano i Juda neostříhal přikázaní Hospodina Boha svého, ale chodili v ustanoveních Izraelských, kteráž byli nařídili.'),
(1556196,54,12,17,20,'A protož opovrhl Hospodin všecko símě Izraelské a ssužoval je, a vydal je v ruku loupežníků, až je i zavrhl od tváři své.'),
(1556197,54,12,17,21,'Nebo odtrhl Izraele od domu Davidova, a krále ustanovili Jeroboáma syna Nebatova, Jeroboám pak odvrátil Izraele od následování Hospodina, a přivedl je k hřešení hříchem velikým.'),
(1556198,54,12,17,22,'A chodili synové Izraelští ve všech hříších Jeroboámových, kteréž on činil, a neodstoupili od nich,'),
(1556199,54,12,17,23,'Až zavrhl Hospodin Izraele od tváři své, jakož byl mluvil skrze všecky služebníky své proroky. I vyhnán jest Izrael z země své do Assyrie až do tohoto dne.'),
(1556200,54,12,17,24,'Potom král Assyrský přivedl lidi z Babylona, a z Kut a z Ava, a z Emat a z Sefarvaim, a osadil je v městech Samařských místo synů Izraelských, kteříž opanovavše Samaří, bydlili v městech jejich.'),
(1556201,54,12,17,25,'I stalo se, když tam bydliti počali, a nesloužili Hospodinu, že poslal na ně Hospodin lvy, kteříž je dávili.'),
(1556202,54,12,17,26,'Protož mluvili králi Assyrskému, řkouce: Národové ti, kteréž jsi přenesl a osadil v městech Samařských, neznají obyčeje Boha země té; protož poslal na ně lvy, kteříž je hubí, proto že neznají obyčeje Boha země té.'),
(1556203,54,12,17,27,'I přikázal král Assyrský, řka: Doveďte tam jednoho z těch kněží, kteréž jste odtud přivedli, a odejdouce, nechť tam bydlí, a učí je obyčeji Boha země té.'),
(1556204,54,12,17,28,'Přišel tedy jeden z kněží, kteréž byli přivedli z Samaří, a bydlil v Bethel, a učil je, jak by měli sloužiti Hospodinu.'),
(1556205,54,12,17,29,'A však nadělali sobě jeden každý národ bohů svých, kteréž stavěli v domě výsostí, jichž byli nadělali Samařští, jeden každý národ v městech svých, v nichž bydlili.'),
(1556206,54,12,17,30,'Muži zajisté Babylonští udělali Sukkot Benot, muži pak Kutští udělali Nergale, a muži Ematští udělali Asima.'),
(1556207,54,12,17,31,'Hevejští tolikéž udělali Nibchaz a Tartak, a Sefarvaimští pálili syny své ohněm Adramelechovi a Anamelechovi, bohům Sefarvaimským.'),
(1556208,54,12,17,32,'A tak sloužili Hospodinu, nadělavše sobě z počtu svého kněží výsostí, kteříž přisluhovali jim v domích výsostí.'),
(1556209,54,12,17,33,'Hospodina ctili, však předce bohům svým sloužili vedlé obyčeje těch národů, odkudž převedeni byli.'),
(1556210,54,12,17,34,'A do dnes činí vedlé obyčejů starých; nebojí se Hospodina, a nečiní vedlé ustanovení a úsudků jeho, ani vedlé zákona a přikázaní, kteráž vydal Hospodin synům Jákobovým, jehož nazval Izraelem.'),
(1556211,54,12,17,35,'Učinil také byl Hospodin s nimi smlouvu, a přikázal jim, řka: Nebudete ctíti bohů cizích, ani se jim klaněti, ani jim sloužiti, ani jim obětovati.'),
(1556212,54,12,17,36,'Ale Hospodina, kterýž vás vyvedl z země Egyptské v síle veliké a v rameni vztaženém, toho ctíti budete, a jemu se klaněti, a jemu obětovati.'),
(1556213,54,12,17,37,'Také ustanovení a úsudků, i zákona a přikázaní, kteráž napsal vám, ostříhati budete, plníce je po všecky dny, a nebudete ctíti bohů cizích.'),
(1556214,54,12,17,38,'Nadto na smlouvu, kterouž jsem učinil s vámi, nezapomínejte, aniž ctěte bohů cizích.'),
(1556215,54,12,17,39,'Ale Hospodina Boha vašeho se bojte; onť vás vysvobodí z ruky všech nepřátel vašich.'),
(1556216,54,12,17,40,'A však neposlechli, ale vedlé obyčeje svého starého činili.'),
(1556217,54,12,17,41,'A tak ti národové ctili Hospodina, a však proto rytinám svým sloužili. Takž i synové jejich a synové synů jejich vedlé toho, což činili otcové jejich, také činí až do dnešního dne.'),
(1556218,54,12,18,1,'Stalo se pak léta třetího Ozee syna Ela, krále Izraelského, kraloval Ezechiáš syn Achasa, krále Judského.'),
(1556219,54,12,18,2,'V pětmecítma letech byl, když počal kralovati, a dvadceti devět let kraloval v Jeruzalémě. Jméno matky jeho bylo Abi, dcera Zachariášova.'),
(1556220,54,12,18,3,'Ten činil, což jest dobrého před očima Hospodinovýma, všecko tak, jakž činil David otec jeho.'),
(1556221,54,12,18,4,'On zkazil výsosti a stroskotal obrazy, a háje posekal, a ztloukl hada měděného, jehož byl udělal Mojžíš; nebo až do těch dnů synové Izraelští kadívali jemu, a nazval jej Nechustam.'),
(1556222,54,12,18,5,'V Hospodinu Bohu Izraelském doufal, a nebylo po něm jemu rovného mezi všemi králi Judskými, i z těch, kteříž byli před ním.'),
(1556223,54,12,18,6,'Nebo se přídržel Hospodina, aniž se uchýlil od něho, a ostříhal přikázaní jeho,kteráž byl přikázal Hospodin Mojžíšovi.'),
(1556224,54,12,18,7,'A byl Hospodin s ním; k čemuž se koli obrátil, šťastně se mu vedlo. Zprotivil se pak králi Assyrskému, a nesloužil jemu.'),
(1556225,54,12,18,8,'On porazil Filistinské až do Gázy a končin jeho, od věže strážných až do města hrazeného.'),
(1556226,54,12,18,9,'Stalo se pak léta čtvrtého krále Ezechiáše, (jenž byl sedmý rok Ozee syna Ela, krále Izraelského), vytáhl Salmanazar král Assyrský proti Samaří a oblehl ji.'),
(1556227,54,12,18,10,'I vzali ji při konci léta třetího; léta šestého Ezechiášova, (jenž byl rok devátý Ozee krále Izraelského), vzata jest Samaří.'),
(1556228,54,12,18,11,'I zavedl král Assyrský Izraele do Assyrie, a osadil jej v Chelach a v Chabor při potoku Gozan, a v městech Médských,'),
(1556229,54,12,18,12,'Proto že neposlouchali hlasu Hospodina Boha svého, ale přestupovali smlouvu jeho, i všecko to, což přikázal Mojžíš služebník Hospodinův, tak že ani poslechnouti ani činiti nechtěli.'),
(1556230,54,12,18,13,'Potom čtrnáctého léta krále Ezechiáše přitáhl Senacherib král Assyrský proti všechněm městům Judským hrazeným, a zdobýval jich.'),
(1556231,54,12,18,14,'Tedy poslal Ezechiáš král Judský k králi Assyrskému do Lachis, řka: Zhřešilť jsem, odtáhni ode mne; cožkoli na mne vzložíš, ponesu. I uložil král Assyrský Ezechiášovi králi Judskému tři sta centnéřů stříbra a třidceti centnéřů zlata.'),
(1556232,54,12,18,15,'I dal Ezechiáš všecky peníze, kteréž jsou nalezeny v domě Hospodinově a v pokladích domu královského.'),
(1556233,54,12,18,16,'Toho času obloupal Ezechiáš dvéře chrámu Hospodinova, i sloupy, kteréž byl obložil Ezechiáš král Judský, a dal je králi Assyrskému.'),
(1556234,54,12,18,17,'A však poslal král Assyrský Tartana a Rabsara a Rabsace z Lachis k králi Ezechiášovi s vojskem velikým k Jeruzalému. Kteříž vytáhše, přijeli k Jeruzalému, a přitáhše, přitrhli a položili se u struhy rybníka hořejšího, kteráž jest podlé cesty dlážené při poli valchářovu.'),
(1556235,54,12,18,18,'A když volali na krále, vyšel k nim Eliakim syn Helkiášův, kterýž byl správce domu, a Sobna písař, a Joach syn Azafův kancléř.'),
(1556236,54,12,18,19,'I mluvil k nim Rabsace: Povězte medle Ezechiášovi: Toto praví král veliký, král Assyrský: Jakéž jest to doufání, na kterémž se zakládáš?'),
(1556237,54,12,18,20,'Mluvils, (ale slova rtů svých), že jest rady i síly k válce dosti. V kohož tedy nyní doufáš, že mi se protivíš?'),
(1556238,54,12,18,21,'Aj, nyní zpolehl jsi na hůl třtinovou, a to ještě nalomenou, na Egypt, na niž zpodepřel-li by se kdo, pronikne ruku jeho a probodne ji. Takovýť jest Farao král Egyptský všechněm, kteříž doufají v něho.'),
(1556239,54,12,18,22,'Pakli mi díte: V Hospodina Boha svého doufáme: zdaliž on není ten, jehož Ezechiáš pobořil výsosti i oltáře, a přikázal Judovi i Jeruzalému, řka: Před tímto oltářem klaněti se budete v Jeruzalémě.'),
(1556240,54,12,18,23,'Nyní tedy, založ se medle se pánem mým, králem Assyrským, a dámť dva tisíce koní, budeš-li moci míti, kdo by na nich jeli?'),
(1556241,54,12,18,24,'I jakž bys tedy odolati mohl jednomu knížeti z nejmenších služebníků pána mého, ačkoli máš doufání v Egyptu pro vozy a jezdce?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556242,54,12,18,25,'Přesto, zdali bez Hospodina přitáhl jsem proti místu tomuto, abych je zkazil? Hospodin řekl mi: Táhni proti zemi té a zkaz ji.'),
(1556243,54,12,18,26,'I řekl Eliakim syn Helkiášův a Sobna a Joach Rabsacovi: Mluv medle k služebníkům svým Syrsky, však rozumíme, a nemluv k nám Židovsky před lidem tímto, kterýž jest na zdech.'),
(1556244,54,12,18,27,'I odpověděl jim Rabsace: Zdaliž ku pánu tvému a k tobě poslal mne pán můj, abych mluvil slova tato? Však k mužům těm, kteříž jsou na zdech, aby lejna svá jedli, a moč svůj spolu s vámi pili.'),
(1556245,54,12,18,28,'A tak stoje Rabsace , volal hlasem velikým, Židovsky mluvě a řka: Slyšte slovo krále velikého, krále Assyrského.'),
(1556246,54,12,18,29,'Toto praví král: Nechť vás nesvodí Ezechiáš, neboť nebude moci vás vysvoboditi z ruky mé.'),
(1556247,54,12,18,30,'A nechť vám nevelí Ezechiáš doufati v Hospodina, řka: Zajisté vysvobodí nás Hospodin, a nebudeť dáno město toto v ruku krále Assyrského.'),
(1556248,54,12,18,31,'Neposlouchejtež Ezechiáše, nebo takto praví král Assyrský: Učiňte se mnou smlouvu, a vyjděte ke mně, a jezte jeden každý z vinice své a z fíku svého, a píte jeden každý vodu z čisterny své,'),
(1556249,54,12,18,32,'Dokudž nepřijdu a nepřenesu vás do země podobné zemi vaší, do země úrodné, země chleba a vinic, země olivoví, oleje a medu, a budete živi a nezemřete. Neposlouchejtež Ezechiáše, neboť vás svodí, řka: Hospodin vysvobodí nás.'),
(1556250,54,12,18,33,'Zdaliž mohli vysvoboditi bohové národů jeden každý zemi svou z ruky krále Assyrského?'),
(1556251,54,12,18,34,'Kdež jsou bohové Emat a Arfad? Kde jsou bohové Sefarvaim, Ana a Ava? Zdaliž jsou vysvobodili Samaří z ruky mé?'),
(1556252,54,12,18,35,'Kteří jsou mezi všemi bohy těch zemí, ješto by vysvobodili zemi svou z ruky mé? Aby pak Hospodin vysvoboditi mohl Jeruzalém z ruky mé?'),
(1556253,54,12,18,36,'Lid pak mlčel, a neodpověděl mu žádného slova; nebo takové bylo rozkázaní královo, řkoucí: Neodpovídejte jemu.'),
(1556254,54,12,18,37,'Přišli tedy Eliakim syn Helkie, kterýž byl správcím domu, a Sobna písař, a Joach syn Azafův kancléř k Ezechiášovi, majíce roucho roztržené, a oznámili jemu slova Rabsacova.'),
(1556255,54,12,19,1,'To když uslyšel král Ezechiáš, roztrhl roucho své, a oděv se žíní, všel do domu Hospodinova.'),
(1556256,54,12,19,2,'I poslal Eliakima správce domu, a Sobnu písaře, i starší z kněží, oblečené v žíně, k Izaiášovi proroku, synu Amosovu.'),
(1556257,54,12,19,3,'Kteříž řekli jemu: Toto praví Ezechiáš: Den úzkosti a útržek i rouhání jest den tento; přiblížilť se plod k vyjití, ale není síly při rodičce.'),
(1556258,54,12,19,4,'Ó by slyšel Hospodin Bůh tvůj všecka slova Rabsacova, jehož poslal král Assyrský pán jeho, aby utrhal Bohu živému, aby pomstil Hospodin Bůh tvůj těch slov, kteráž by slyšel. Protož pozdvihni modlitby své za tento ostatek, kterýž se nalézá.'),
(1556259,54,12,19,5,'A tak přišli služebníci krále Ezechiáše k Izaiášovi.'),
(1556260,54,12,19,6,'Jimž odpověděl Izaiáš: Toto povíte pánu svému: Takto praví Hospodin: Nestrachuj se slov těch, kteráž jsi slyšel, jimiž se mi rouhali služebníci krále Assyrského.'),
(1556261,54,12,19,7,'Aj, já pustím naň vítr, aby uslyše pověst, navrátil se do země své, a učiním to, že padne od meče v zemi své.'),
(1556262,54,12,19,8,'Rabsace pak navrátiv se, nalezl krále Assyrského, an dobývá Lebna; nebo uslyšel, (pročež odtrhl od Lachis),'),
(1556263,54,12,19,9,'Uslyšel, pravím, o Tirhákovi králi Mouřenínském, ano pravili: Aj, teď táhne, aby bojoval s tebou. I navrátil se, a však poslal jiné posly k Ezechiášovi s těmito slovy:'),
(1556264,54,12,19,10,'Takto povíte Ezechiášovi králi Judskému, řkouce: Nechť tebe nesvodí Bůh tvůj, v němž ty doufáš, říkaje: Nebudeť dán Jeruzalém v ruku krále Assyrského.'),
(1556265,54,12,19,11,'Aj, slyšels, co jsou činili králové Assyrští všechněm zemím, pohubivše je, a ty bys měl býti vysvobozen?'),
(1556266,54,12,19,12,'Zdaliž jsou je vysvobodili bohové těch národů, kteréž zahladili otcové moji, totiž Gozana, Charana, Resefa a syny Eden, kteříž byli v Telasar?'),
(1556267,54,12,19,13,'Kde jest král Emat, a král Arfad, a král města Sefarvaim, Ana i Ava?'),
(1556268,54,12,19,14,'Protož vzav Ezechiáš list z ruky poslů, přečetl jej, a vstoupiv do domu Hospodinova, rozvinul jej Ezechiáš před Hospodinem.'),
(1556269,54,12,19,15,'A modlil se Ezechiáš před Hospodinem, řka: Hospodine Bože Izraelský, kterýž sedíš nad cherubíny, ty jsi sám Bůh všech království země, ty jsi učinil nebe i zemi.'),
(1556270,54,12,19,16,'Nakloniž, Hospodine, ucha svého a uslyš; otevři, Hospodine, oči své a pohleď; slyš slova Senacheribova, kterýž poslal k činění útržek Bohu živému.'),
(1556271,54,12,19,17,'Takť jest, Hospodine, žeť jsou zkazili králové Assyrští národy ty i země jejich.'),
(1556272,54,12,19,18,'A uvrhli bohy jejich do ohně. Nebo nebyli bohové, ale dílo rukou lidských, dřevo a kámen, protož zahladili je.'),
(1556273,54,12,19,19,'A nyní, Hospodine Bože náš, vysvoboď nás, prosím, z ruky jeho, ať by poznala všecka království země, že jsi ty sám, Hospodine, Bohem.'),
(1556274,54,12,19,20,'Tedy poslal Izaiáš syn Amosův k Ezechiášovi, řka: Toto praví Hospodin Bůh Izraelský: Zač jsi mi se modlil strany Senacheriba krále Assyrského, vyslyšel jsem tě.'),
(1556275,54,12,19,21,'Totoť jest slovo, kteréž mluvil Hospodin o něm: Pohrdá tebou, a posmívá se tobě, králi, panna dcera Sionská, potřásá za tebou hlavou dcera Jeruzalémská.'),
(1556276,54,12,19,22,'Kohož jsi zhaněl? A komus se rouhal? Proti komu jsi povýšil hlasu a pozdvihls vzhůru očí svých? Však proti svatému Izraelskému.'),
(1556277,54,12,19,23,'Skrze posly své utrhal jsi Pánu, a řekl jsi: Ve množství vozů svých vytáhl jsem na hory vysoké, na stráně Libánské, a zpodtínám vysoké cedry jeho, i spanilé jedle jeho, a vejdu do nejdalších příbytků jeho, do lesů a výborných rolí jeho.'),
(1556278,54,12,19,24,'Já jsem vykopal a pil jsem vody cizí, a vysušil jsem nohama svýma všecky potoky podmaněných.'),
(1556279,54,12,19,25,'Zdaliž jsi neslyšel, že již dávno jsem jej učinil, a ode dnů starých jej sformoval? Což tedy nyní přivedl bych jej k zkažení a v hromady rumu, jako jiná města hrazená?'),
(1556280,54,12,19,26,'Jejichž obyvatelé mdlí byli, předěšení a zahanbení, byvše jako bylina polní a zelina vzcházející, jako tráva na střechách, a jako osení rzí zkažené, prvé než by dorostlo obilí.'),
(1556281,54,12,19,27,'Sedání pak tvé, vycházení tvé i vcházení tvé znám, i vzteklost tvou proti mně.'),
(1556282,54,12,19,28,'Poněvadž jsi se rozzlobil proti mně, a tvé zpouzení přišlo v uši mé, protož vpustím udici svou v chřípě tvé, a udidla svá do úst tvých, a odvedu tě zase tou cestou, kterouž jsi přišel.'),
(1556283,54,12,19,29,'Toto pak měj, Ezechiáši, za znamení: Že jíte roku prvního to, což se samo rodí, též druhého roku, což samo vzchází, třetího teprv roku sejte a žněte, a štěpujte vinice, a jezte ovoce z nich.'),
(1556284,54,12,19,30,'Ostatek zajisté domu Judova, kterýž pozůstal, vpustí zase kořeny své hluboce, a vydá užitek nahoru.'),
(1556285,54,12,19,31,'Nebo z Jeruzaléma vyjdou ostatkové, a ti, kteříž jsou zachováni, z hory Siona. Horlivost Hospodina zástupů učiní to.'),
(1556286,54,12,19,32,'A protož toto praví Hospodin o králi Assyrském: Nevejdeť do města tohoto, aniž sem střely vstřelí, aniž se ho zmocní pavézníci, aniž udělají u něho náspu.'),
(1556287,54,12,19,33,'Cestou, kterouž přitáhl, zase navrátí se, a do města tohoto nevejde, praví Hospodin.'),
(1556288,54,12,19,34,'Nebo chrániti budu města tohoto, abych je zachoval pro sebe a pro Davida služebníka svého.'),
(1556289,54,12,19,35,'Tedy stalo se té noci, že vyšel anděl Hospodinův, a zbil v vojště Assyrském sto osmdesáte pět tisíců. I vstali ráno, a aj, všickni mrtví.'),
(1556290,54,12,19,36,'Pročež odjel a utekl Senacherib král Assyrský, a navrátiv se, bydlil v Ninive.'),
(1556291,54,12,19,37,'I stalo se, když se klaněl v chrámě Nizrocha boha svého, že Adramelech a Sarasar, synové jeho, zabili jej mečem, a sami utekli do země Ararat. I kraloval Esarchaddon syn jeho místo něho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556292,54,12,20,1,'V těch dnech roznemohl se Ezechiáš až k smrti. I přišel k němu Izaiáš syn Amosův prorok, a řekl jemu: Toto praví Hospodin: Zřeď dům svůj, nebo umřeš, a nebudeš živ.'),
(1556293,54,12,20,2,'I obrátil tvář svou k stěně, a modlil se Hospodinu, řka:'),
(1556294,54,12,20,3,'Prosím, ó Hospodine, rozpomeň se nyní, že jsem stále chodil před tebou v pravdě a v srdci upřímém, a že jsem to činil, což dobrého jest před očima tvýma. I plakal Ezechiáš pláčem velikým.'),
(1556295,54,12,20,4,'Ještě pak Izaiáš nebyl vyšel do půl síně, když se k němu stalo slovo Hospodinovo, řkoucí:'),
(1556296,54,12,20,5,'Navrať se a rci Ezechiášovi vůdci lidu mého: Toto praví Hospodin Bůh Davida otce tvého: Slyšelť jsem modlitbu tvou, a viděl jsem slzy tvé; aj, já uzdravím tě, třetího dne vstoupíš do domu Hospodinova.'),
(1556297,54,12,20,6,'A přidám ke dnům tvým patnácte let, a z ruky krále Assyrského vysvobodím tě, i město toto, a chrániti budu města tohoto, pro sebe a pro Davida služebníka svého.'),
(1556298,54,12,20,7,'I řekl Izaiáš: Vezměte hrudu suchých fíků. Kterouž vzavše, přiložili na vřed, i uzdraven jest.'),
(1556299,54,12,20,8,'Řekl pak Ezechiáš Izaiášovi: Jaké bude znamení toho, že mne uzdraví Hospodin, a že půjdu třetího dne do domu Hospodinova?'),
(1556300,54,12,20,9,'Odpověděl Izaiáš: Toto bude tobě znamení od Hospodina, že Hospodin učiní věc tuto, kterouž mluvil: Chceš-li, aby postoupil dále stín o deset stupňů, aneb navrátil se zpátkem o deset stupňů?'),
(1556301,54,12,20,10,'Odpověděl Ezechiáš: Snázeť může stín postoupiti dolů o deset stupňů. Nechci, ale nechť zase postoupí stín zpátkem o deset stupňů.'),
(1556302,54,12,20,11,'Volal tedy Izaiáš prorok k Hospodinu, a navrátil stín po stupních, po nichž sešel na hodinách slunečných Achasových, zpátkem o deset stupňů.'),
(1556303,54,12,20,12,'Toho času poslal Berodach Baladan syn Baladanův, král Babylonský, list a dary Ezechiášovi; nebo slyšel, že nemocen byl Ezechiáš.'),
(1556304,54,12,20,13,'I vyslyšel je Ezechiáš a ukázal jim všecky schrany klénotů svých, stříbra a zlata i vonných věcí, a olej nejvýbornější, tolikéž dům zbroje své, a cožkoli mohlo nalezeno býti v pokladích jeho. Ničeho nebylo, čehož by jim neukázal Ezechiáš v domě svém i ve všem panství svém.'),
(1556305,54,12,20,14,'Protož přišel prorok Izaiáš k králi Ezechiášovi, a řekl jemu: Co pravili ti muži? A odkud přišli k tobě? Odpověděl Ezechiáš:Z země daleké přišli, z Babylona.'),
(1556306,54,12,20,15,'I řekl: Co viděli v domě tvém? Odpověděl Ezechiáš: Všecko, což jest v domě mém, viděli. Ničeho není v pokladích mých, čehož bych jim neukázal.'),
(1556307,54,12,20,16,'Ale Izaiáš řekl Ezechiášovi: Slyšiž slovo Hospodinovo.'),
(1556308,54,12,20,17,'Aj, dnové přijdou, v nichž odneseno bude do Babylona, cožkoli jest v domě tvém, a cožkoli nachovali otcové tvoji až do tohoto dne; nezůstaneť ničeho, praví Hospodin.'),
(1556309,54,12,20,18,'Syny také tvé, kteříž pojdou z tebe, kteréž ty zplodíš, poberou a budou komorníci při dvoru krále Babylonského.'),
(1556310,54,12,20,19,'Tedy řekl Ezechiáš Izaiášovi: Dobréť jest slovo Hospodinovo, kteréž jsi mluvil. Řekl ještě: Ovšem, žeť jest dobré, jestliže pokoj a pravda bude za dnů mých.'),
(1556311,54,12,20,20,'O jiných pak činech Ezechiášových, i vší síle jeho, a kterak udělal rybník, a vodu po trubách uvedl do města, zapsáno jest v knize o králích Judských.'),
(1556312,54,12,20,21,'I usnul Ezechiáš s otci svými, a kraloval Manasses syn jeho místo něho.'),
(1556313,54,12,21,1,'Ve dvanácti letech byl Manasses, když počal kralovati, a kraloval padesáte a pět let v Jeruzalémě. Jméno matky jeho bylo Chefziba.'),
(1556314,54,12,21,2,'I činil to, což jest zlého před očima Hospodinovýma, vedlé ohavností těch národů, kteréž Hospodin vyplénil před syny Izraelskými.'),
(1556315,54,12,21,3,'Nebo převrátiv se, vzdělal zase výsosti, kteréž byl zkazil Ezechiáš otec jeho, a vystavěl oltáře Bálovi, a vysadil háj, tak jako byl učinil Achab král Izraelský. A klaněje se všemu vojsku nebeskému, ctil je.'),
(1556316,54,12,21,4,'Vzdělal také oltáře v domě Hospodinově, o němž byl řekl Hospodin: V Jeruzalémě položím jméno své.'),
(1556317,54,12,21,5,'Nadto nadělal oltářů všemu vojsku nebeskému, v obou síních domu Hospodinova.'),
(1556318,54,12,21,6,'Syna také svého provedl skrze oheň, a šetřil časů, s hadačstvím zacházel, zaklinače a čarodějníky zřídil, a velmi mnoho zlého činil před očima Hospodinovýma, popouzeje ho.'),
(1556319,54,12,21,7,'Postavil také rytinu háje, kterouž byl udělal v domě, o kterémž byl řekl Hospodin k Davidovi a Šalomounovi synu jeho: V domě tomto a v Jeruzalémě, kterýž jsem vyvolil ze všech pokolení Izraelských, položím jméno své na věky,'),
(1556320,54,12,21,8,'Aniž více dopustím, aby se pohnula noha Izraele z země, kterouž jsem dal otcům jejich, jen toliko budou-li skutečně ostříhati všeho, což jsem jim přikázal, a všeho zákona, kterýž jim vydal Mojžíš služebník můj.'),
(1556321,54,12,21,9,'Ale neuposlechli; nebo je svedl Manasses, tak že činili horší věci, nežli ti národové, kteréž vyplénil Hospodin od tváři synů Izraelských,'),
(1556322,54,12,21,10,'Ačkoli mluvíval Hospodin skrze služebníky své proroky, řka:'),
(1556323,54,12,21,11,'Proto že činil Manasses král Judský ohavnosti tyto, a páchal horší věci nad všecko, což činili Amorejští, kteříž byli před ním, a že přivedl i Judu k hřešení skrze ukydané bohy své,'),
(1556324,54,12,21,12,'Protož řekl Hospodin Bůh Izraelský: Aj, já uvedu zlé věci na Jeruzalém a na Judu, aby každému slyšícímu o tom znělo v obou uších jeho.'),
(1556325,54,12,21,13,'Nebo vztáhnu na Jeruzalém šňůru Samařskou, a závaží domu Achabova, a vytru Jeruzalém, jako vytírá někdo misku, a vytra, poklopí ji.'),
(1556326,54,12,21,14,'A opustím ostatky dědictví svého, a vydám je v ruku nepřátel jejich, i budou v loupež a v rozchvátání všechněm nepřátelům svým,'),
(1556327,54,12,21,15,'Proto že činili to, což jest zlého před očima mýma, a popouzeli mne od toho dne, jakž vyšli otcové jejich z Egypta, až do dnešního dne.'),
(1556328,54,12,21,16,'Ano i krve nevinné vylil Manasses velmi mnoho, tak že naplnil Jeruzalém od jednoho konce k druhému, kromě hříchu svého, kterýmž přivedl k hřešení Judu, aby činili, což zlého jest před očima Hospodinovýma.'),
(1556329,54,12,21,17,'O jiných pak činech Manassesových, a cožkoli činil, i hřích jeho, kterýmž zhřešil, zapsáno jest v knize o králích Judských.'),
(1556330,54,12,21,18,'I usnul Manasses s otci svými, a pohřben jest v zahradě domu svého, v zahradě Uzy, a kraloval Amon syn jeho místo něho.'),
(1556331,54,12,21,19,'Ve dvamecítma letech byl Amon, když počal kralovati, a kraloval dvě létě v Jeruzalémě. Jméno matky jeho bylo Mesullemet, dcera Charus z Jateba.'),
(1556332,54,12,21,20,'I ten činil to, což jest zlého před očima Hospodinovýma, jako činil Manasses otec jeho.'),
(1556333,54,12,21,21,'A chodil po vší cestě, po níž chodil otec jeho. Sloužil také ukydaným bohům, jimž sloužíval otec jeho, a klaněl se jim,'),
(1556334,54,12,21,22,'Opustiv Hospodina Boha otců svých, aniž chodil po cestě Hospodinově.'),
(1556335,54,12,21,23,'Spuntovali se pak služebníci Amonovi proti němu, a zamordovali jej v domě jeho.'),
(1556336,54,12,21,24,'Tedy pobil lid země všecky ty, kteříž se byli spuntovali proti králi Amonovi, a ustanovil lid země krále Joziáše syna jeho místo něho.'),
(1556337,54,12,21,25,'O jiných pak činech Amonových, kteréž činil, zapsáno jest v knize o králích Judských.'),
(1556338,54,12,21,26,'I pochoval ho lid v hrobě jeho v zahradě Uzy, a kraloval Joziáš syn jeho místo něho.'),
(1556339,54,12,22,1,'V osmi letech byl Joziáš, když počal kralovati, a kraloval jedno a třidceti let v Jeruzalémě. Jméno matky jeho bylo Jedida, dcera Adaiášova z Baskat.'),
(1556340,54,12,22,2,'Ten činil to, což pravého jest před očima Hospodinovýma, chodě po vší cestě Davida otce svého, a neuchyluje se na pravo ani na levo.'),
(1556341,54,12,22,3,'Stalo se pak osmnáctého léta krále Joziáše, že poslal král Safana syna Azaliášova, syna Mesullamova, písaře, do domu Hospodinova, řka:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556342,54,12,22,4,'Jdi k Helkiášovi knězi nejvyššímu, ať sečtou peníze, kteréž jsou vneseny do domu Hospodinova, kteréž sebrali strážní prahu od lidu.'),
(1556343,54,12,22,5,'A ať je dadí v ruce řemeslníků představených nad dílem domu Hospodinova, aby je obraceli na dělníky, kteříž dělají dílo v domě Hospodinově, k opravení zbořenin domu,'),
(1556344,54,12,22,6,'Totiž na tesaře a stavitele a zedníky, též aby jednali dříví a tesané kamení k opravování domu.'),
(1556345,54,12,22,7,'A však ať počtu nečiní z peněz, kteréž se dávají v ruce jejich; nebo věrně dělati budou.'),
(1556346,54,12,22,8,'I řekl Helkiáš kněz nejvyšší Safanovi písaři: Knihu zákona nalezl jsem v domě Hospodinově. I dal Helkiáš knihu tu Safanovi, kterýž četl v ní.'),
(1556347,54,12,22,9,'Přišel pak Safan písař k králi, a oznamuje králi tu věc, řekl: Sebrali služebníci tvoji peníze, kteréž se nalezly v domě Páně, a dali je v ruce řemeslníků představených nad dílem domu Hospodinova.'),
(1556348,54,12,22,10,'Oznámil také Safan písař králi, řka: Knihu mi dal Helkiáš kněz. I četl ji Safan před králem.'),
(1556349,54,12,22,11,'A když slyšel král slova knihy zákona, roztrhl roucho své.'),
(1556350,54,12,22,12,'A rozkázal král Helkiášovi knězi, a Achikamovi synu Safanovu, a Achborovi synu Michaia, a Safanovi písaři, a Asaiášovi služebníku královskému,řka:'),
(1556351,54,12,22,13,'Jděte, poraďte se s Hospodinem o mne i o lid, a o všeho Judu z strany slov knihy této, kteráž jest nalezena; nebo veliký jest hněv Hospodinův, kterýž rozpálen jest proti nám, proto že otcové naši neposlouchali slov knihy této, aby činili všecko tak, jakž jest nám zapsáno.'),
(1556352,54,12,22,14,'Tedy šli Helkiáš kněz a Achikam, a Achbor, a Safan a Asaia k Chuldě prorokyni, manželce Salluma, syna Tekue, syna Charchas, strážného nad rouchem; nebo bydlila v Jeruzalémě na druhé straně. A mluvili s ní.'),
(1556353,54,12,22,15,'Kteráž řekla jim: Toto praví Hospodin Bůh Izraelský: Povězte muži, kterýž vás poslal ke mně:'),
(1556354,54,12,22,16,'Takto praví Hospodin: Aj, já uvedu zlé věci na místo toto a na obyvatele jeho, všecka slova knihy té, kterouž četl král Judský,'),
(1556355,54,12,22,17,'Proto že mne opustili a kadili bohům cizím, aby mne popouzeli všelikým dílem rukou svých. Z té příčiny rozpálila se prchlivost má na místo toto, aniž bude uhašena.'),
(1556356,54,12,22,18,'Králi pak Judskému, kterýž vás poslal, abyste se tázali Hospodina, takto povíte: Toto praví Hospodin Bůh Izraelský o slovích těch, kteráž jsi slyšel:'),
(1556357,54,12,22,19,'Poněvadž obměkčeno jest srdce tvé, a ponížils se před tváří Hospodinovou, když jsi slyšel, které věci jsem mluvil proti místu tomuto, a proti obyvatelům jeho, že má přijíti v zpuštění a v zlořečení, a roztrhl jsi roucho své, a plakals přede mnou, i já také uslyšel jsem tě, praví Hospodin.'),
(1556358,54,12,22,20,'Protož, aj, já připojím tě k otcům tvým, a pochován budeš v hrobích svých v pokoji, aby neviděly oči tvé ničeho z toho zlého, kteréž přivedu na místo toto. I oznámili králi tu řeč.'),
(1556359,54,12,23,1,'Tedy poslav král, aby se shromáždili k němu všickni starší Judští a Jeruzalémští,'),
(1556360,54,12,23,2,'Vstoupil král do domu Hospodinova a všickni muži Judští, i všickni obyvatelé Jeruzalémští s ním, i kněží a proroci, a všecken lid od malého až do velikého, i četl, aby všickni slyšeli všecka slova knihy smlouvy, kteráž byla nalezena v domě Hospodinově.'),
(1556361,54,12,23,3,'Potom stoje král na místě vyšším, učinil smlouvu před Hospodinem, že bude následovati Hospodina, a ostříhati přikázaní jeho, i svědectví jehoa ustanovení jeho, vším srdcem svým a vší duší svou, a plniti slova smlouvy té, kteráž jsou zapsána v knize té. K kteréžto smlouvě i všecken lid přistoupil.'),
(1556362,54,12,23,4,'A přikázal král Helkiášovi knězi nejvyššímu a kněžím nižším i strážným prahu, aby vymetali z chrámu Hospodinova všecky nádoby, kteréž udělány byly Bálovi a háji, i všemu vojsku nebeskému. Kterýž popáliv je vně za Jeruzalémem na poli Cedron, vnesl prach jejich do Bethel.'),
(1556363,54,12,23,5,'Složil také kněží , kteréž byli ustanovili králové Judští, aby kadívali na výsostech v městech Judských a vůkol Jeruzaléma; takž podobně i ty, kteříž kadívali Bálovi, slunci, měsíci a planétám, i všemu vojsku nebeskému.'),
(1556364,54,12,23,6,'Vyvezl také háj z domu Hospodinova ven z Jeruzaléma ku potoku Cedron, a spálil jej u potoka Cedron a setřel na prach; ten pak prach vysypal na hroby synů toho lidu.'),
(1556365,54,12,23,7,'Domky také sodomářů hanebných zkazil, kteříž byli při domě Hospodinově, v nichž ženy tkaly kortýny k háji.'),
(1556366,54,12,23,8,'A kázal přivésti všecky kněží z měst Judských, a poškvrnil výsostí, na nichž kadívali kněží, od Gabaa až do Bersabé. Zkazil také výsostí u bran, kteréž byly u vrat brány Jozue, knížete města, a byly po levé straně vcházejícímu do brány městské.'),
(1556367,54,12,23,9,'A však nepřistupovali ti kněží výsostí k oltáři Hospodinovu v Jeruzalémě, ale jídali chleby přesné mezi bratřími svými.'),
(1556368,54,12,23,10,'Poškvrnil také i Tofet, jenž jest v údolí syna Hinnom, aby více žádný nevodil syna svého aneb dcery své skrze oheň Molochovi.'),
(1556369,54,12,23,11,'Zahladil také ty koně, kteréž byli postavili králové Judští slunci, kdež se vchází do domu Hospodinova, k domu Netanmelecha komorníka, kterýž byl v Parvarim; a vozy slunce spálil ohněm.'),
(1556370,54,12,23,12,'Ano i oltáře, kteříž byli na vrchním paláci Achasovu, jichž byli nadělali králové Judští, a oltáře, jichž nadělal Manasses v obou síních domu Hospodinova, pobořil král, a pospíšiv s nimi odtud, dal vysypati prach jejich do potoka Cedron.'),
(1556371,54,12,23,13,'Výsosti také, kteréž byly před Jeruzalémem, a kteréž byly po pravé straně hory Olivetské, jichž byl nadělal Šalomoun král Izraelský Astarotovi, ohavnosti Sidonských, a Chámosovi, ohavnosti Moábských, a Melchomovi, ohavnosti synů Ammon, poškvrnil král,'),
(1556372,54,12,23,14,'A potřískal obrazy, háje posekal, a místa jejich naplnil kostmi lidskými.'),
(1556373,54,12,23,15,'Nadto i oltář, jenž byl v Bethel, a výsost, kterouž udělal Jeroboám syn Nebatův, kterýž přivedl k hřešení Izraele, i ten oltář i výsost zkazil, a spáliv výsost, setřel ji na prach; spálil i háj.'),
(1556374,54,12,23,16,'A obrátiv se Joziáš, uzřel hroby, kteříž tu na hoře byli, a poslav, pobral kosti z těch hrobů a spálil je na tom oltáři. A tak poškvrnil ho vedlé řeči Hospodinovy, kterouž mluvil muž Boží ten, kterýž to předpověděl.'),
(1556375,54,12,23,17,'I řekl: Jaký jest onenno nápis, kterýž vidím? Odpověděli jemu muži města: Hrob muže Božího jest, kterýž přišed z Judstva, předpověděl tyto věci, kteréž jsi učinil při oltáři v Bethel.'),
(1556376,54,12,23,18,'Tedy řekl: Nechtež ho, aniž kdo hýbej kostmi jeho. I vysvobodili kosti jeho s kostmi proroka toho, kterýž byl přišel z Samaří.'),
(1556377,54,12,23,19,'Též všecky domy výsostí, kteříž byli v městech Samařských, jichž byli nadělali králové Izraelští, aby popouzeli Hospodina, zkazil Joziáš, a učinil jim rovně tak, jakž byl učinil v Bethel.'),
(1556378,54,12,23,20,'Zbil také všecky kněží výsostí, kteříž tu byli, na oltářích, a pálil kosti lidské na nich. Potom navrátil se do Jeruzaléma.'),
(1556379,54,12,23,21,'Přikázal pak král všemu lidu, řka: Slavte velikunoc Hospodinu Bohu svému, jakož psáno jest v knize smlouvy této.'),
(1556380,54,12,23,22,'Nebo nebyla slavena taková velikanoc od času soudců, kteříž soudili Izraele, a po všecky dny králů Izraelských a králů Judských.'),
(1556381,54,12,23,23,'Osmnáctého léta krále Joziáše slavena jest ta velikanoc Hospodinu v Jeruzalémě.'),
(1556382,54,12,23,24,'Ano i věšťce a hadače, obrazy i ukydané bohy, a všecky ty ohavnosti, což jich bylo viděti v zemi Judské a v Jeruzalémě, vyplénil Joziáš, aby naplnil slova zákona zapsaná v knize, kterouž nalezl Helkiáš kněz v domě Hospodinově.'),
(1556383,54,12,23,25,'A nebylo jemu podobného krále před ním, kterýž by obrátil se k Hospodinu celým srdcem svým, a celou duší svou, i všemi mocmi svými vedlé všeho zákona Mojžíšova, ani po něm nepovstal podobný jemu.'),
(1556384,54,12,23,26,'A však neodvrátil se Hospodin od prchlivosti hněvu svého velikého, kterouž vzbuzen byl hněv jeho proti Judovi, pro všecka popouzení, kterýmiž popouzel ho Manasses.'),
(1556385,54,12,23,27,'Protož řekl Hospodin: Také i Judu zavrhu od tváři své, jako jsem zavrhl Izraele, a opovrhu to město, kteréž jsem vyvolil, Jeruzalém, i ten dům, o němž jsem byl řekl: Jméno mé tam bude.'),
(1556386,54,12,23,28,'O jiných pak činech Joziášových, a cožkoli činil, zapsáno jest v knize o králích Judských.'),
(1556387,54,12,23,29,'Za dnů jeho přitáhl Farao Nécho král Egyptský proti králi Assyrskému k řece Eufraten. I vytáhl král Joziáš proti němu, a on zabil jej v Mageddo, když ho uzřel.'),
(1556388,54,12,23,30,'Tedy služebníci jeho vloživše jej mrtvého na vůz, přivezli ho z Mageddo do Jeruzaléma, a pochovali jej v hrobě jeho. I vzal lid země Joachaza syna Joziášova, a pomazali ho, i ustanovili králem na místě otce jeho.'),
(1556389,54,12,23,31,'Ve třímecítma letech byl Joachaz, když počal kralovati, a kraloval tři měsíce v Jeruzalémě. Jméno matky jeho bylo Chamutal, dcera Jeremiášova z Lebna.'),
(1556390,54,12,23,32,'A činil to, což jest zlého před očima Hospodinovýma, všecko tak, jakž činili otcové jeho.'),
(1556391,54,12,23,33,'I svázal ho Farao Nécho v Ribla, v zemi Emat, když kraloval v Jeruzalémě, a uložil daň na tu zemi, sto centnéřů stříbra a centnéř zlata.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556392,54,12,23,34,'A ustanovil Farao Nécho za krále Eliakima syna Joziášova, na místo Joziáše otce jeho, a proměnil jméno jeho, aby sloul Joakim. Ale Joachaza vzal, kterýž, když se dostal do Egypta, umřel tam.'),
(1556393,54,12,23,35,'To pak zlato i stříbro dával Joakim Faraonovi; pročež šacoval obyvatele země, aby mohl dáti stříbro k rozkázaní Faraonovu. Od jednoho každého vedlé toho, jakž byl šacován, bral stříbro i zlato od lidu země, aby dal Faraonovi Néchovi.'),
(1556394,54,12,23,36,'V pětmecítma letech byl Joakim, když počal kralovati, a jedenácte let kraloval v Jeruzalémě. Jméno matky jeho bylo Zebuda, dcera Pedaiova z Ruma.'),
(1556395,54,12,23,37,'I činil to, což jest zlého před očima Hospodinovýma, podlé všeho, což činili otcové jeho.'),
(1556396,54,12,24,1,'Za dnů jeho přitáhl Nabuchodonozor král Babylonský, i učiněn jest Joakim služebníkem jeho za tři léta. Potom odvrátiv se, zprotivil se jemu.'),
(1556397,54,12,24,2,'Protož poslal Hospodin na něj lotříky Kaldejské a lotříky Syrské, i lotříky Moábské a lotříky synů Ammon, poslal je, pravím, na Judu, aby ho zkazili vedlé řeči Hospodinovy, kterouž byl mluvil skrze služebníky své proroky.'),
(1556398,54,12,24,3,'A jistě podlé řeči Hospodinovy to se dálo proti Judovi, aby jej zavrhl od tváři své pro hříchy Manassesovy, vedlé toho všeho, což byl činil,'),
(1556399,54,12,24,4,'Ano i pro krev nevinnou, kterouž vylil, naplniv Jeruzalém krví nevinnou, čehož nechtěl Hospodin prominouti.'),
(1556400,54,12,24,5,'O jiných pak věcech Joakimových, a cožkoli činil, psáno jest v knize o králích Judských.'),
(1556401,54,12,24,6,'A tak usnul Joakim s otci svými, a kraloval Joachin syn jeho místo něho.'),
(1556402,54,12,24,7,'Král pak Egyptský nikdy více nevytáhl z země své; nebo král Babylonský pobral od řeky Egyptské až k řece Eufraten všecko, cožkoli měl král Egyptský.'),
(1556403,54,12,24,8,'V osmnácti letech byl Joachin, když počal kralovati, a tři měsíce kraloval v Jeruzalémě. Jméno matky jeho Nechusta, dcera Elnatanova z Jeruzaléma.'),
(1556404,54,12,24,9,'I činil to, což jest zlého před očima Hospodinovýma, všecko tak, jakž byl činil otec jeho.'),
(1556405,54,12,24,10,'Toho času vytáhli služebníci Nabuchodonozora krále Babylonského proti Jeruzalému, a obleženo jest město.'),
(1556406,54,12,24,11,'Ano i Nabuchodonozor král Babylonský přitáhl proti městu, když služebníci jeho leželi vůkol něho.'),
(1556407,54,12,24,12,'Tedy vyšel Joachin král Judský k králi Babylonskému, i s matkou svou i s služebníky, knížaty i komorníky svými, kteréhož vzal král Babylonský léta osmého kralování svého.'),
(1556408,54,12,24,13,'A vynesl odtud všecky poklady domu Hospodinova, a poklady domu královského, a ztloukl všecky nádoby zlaté, jichž byl nadělal Šalomoun král Izraelský do domu Hospodinova, jakož byl mluvil Hospodin.'),
(1556409,54,12,24,14,'Při tom přenesl všecken Jeruzalém a všecka knížata i všecky muže udatné, deset tisíců zajatých, i všecky tesaře a kováře. Žádného nezanechal, kromě chaterných lidí země.'),
(1556410,54,12,24,15,'Zavedl také i Joachina do Babylona, a matku jeho i ženy královské i komorníky jeho; silné také země zavedl do vězení z Jeruzaléma do Babylona.'),
(1556411,54,12,24,16,'Všech také mužů udatných sedm tisíců, tesařů také a kovářů tisíc, všecky též zmužilé bojovníky zavedl jaté král Babylonský do Babylona.'),
(1556412,54,12,24,17,'Ustanovil pak král Babylonský Mataniáše, strýce jeho, králem místo něho, a změnil mu jméno, aby sloul Sedechiáš.'),
(1556413,54,12,24,18,'V jedenmecítma letech byl Sedechiáš, když počal kralovati a jedenácte let kraloval v Jeruzalémě. Jméno matky jeho bylo Chamutal, dcera Jeremiášova z Lebna.'),
(1556414,54,12,24,19,'I činil to, což jest zlého před očima Hospodinovýma, všecko tak, jakž byl dělal Joakim.'),
(1556415,54,12,24,20,'Nebo se to dálo pro rozhněvání Hospodinovo proti Jeruzalému a Judovi, až je i zavrhl od tváři své. V tom opět zprotivil se Sedechiáš králi Babylonskému.'),
(1556416,54,12,25,1,'Stalo se pak léta devátého kralování jeho, měsíce desátého, v desátý den téhož měsíce, že přitáhl Nabuchodonozor král Babylonský se vším vojskem svým k Jeruzalému, a položil se u něho, a vzdělali proti němu hradbu vůkol.'),
(1556417,54,12,25,2,'A bylo město obleženo, až do jedenáctého léta krále Sedechiáše.'),
(1556418,54,12,25,3,'V kterémžto, devátého dne čtvrtého měsíce, rozmohl se hlad v městě, a neměl chleba lid země.'),
(1556419,54,12,25,4,'I protrženo jest město, a všickni muži bojovní utekli noci té skrze bránu mezi dvěma zdmi u zahrady královské; Kaldejští pak leželi okolo města. Ušel také král cestou pouště.'),
(1556420,54,12,25,5,'I honilo vojsko Kaldejské krále, a postihli ho na rovinách Jerišských, a všecko vojsko jeho rozprchlo se od něho.'),
(1556421,54,12,25,6,'A tak javše krále, přivedli jej k králi Babylonskému do Ribla, kdež učinili o něm soud.'),
(1556422,54,12,25,7,'Syny pak Sedechiášovy zmordovali před očima jeho. Potom Sedechiáše oslepili, a svázavše ho řetězy ocelivými, zavedli jej do Babylona.'),
(1556423,54,12,25,8,'Potom měsíce pátého, sedmý den téhož měsíce, léta devatenáctého kralování Nabuchodonozora krále Babylonského, přitáhl Nebuzardan hejtman nad žoldnéři, služebník krále Babylonského, do Jeruzaléma.'),
(1556424,54,12,25,9,'A zapálil dům Hospodinův i dům královský, i všecky domy v Jeruzalémě, a tak všecky domy veliké vypálil.'),
(1556425,54,12,25,10,'Zdi také Jeruzalémské vůkol pobořilo všecko vojsko Kaldejské, kteréž bylo s tím hejtmanem nad žoldnéři.'),
(1556426,54,12,25,11,'Ostatek pak lidu, kterýž byl zůstal v městě, i poběhlce, kteříž se byli obrátili k králi Babylonskému, a jiný obecný lid, zavedl Nebuzardan hejtman nad žoldnéři.'),
(1556427,54,12,25,12,'Toliko něco chaterného lidu země zanechal hejtman nad žoldnéři, aby byli vinaři a oráči.'),
(1556428,54,12,25,13,'Nadto sloupy měděné, kteříž byli v domě Hospodinově, i podstavky, i moře měděné, kteréž bylo v domě Hospodinově, ztloukli Kaldejští, a měď z nich odvezli do Babylona.'),
(1556429,54,12,25,14,'Též hrnce, lopaty a nástroje hudebné, a kadidlnice i všecky nádoby měděné, jimiž sloužili, pobrali.'),
(1556430,54,12,25,15,'I nádoby k oharkům a kotlíky, a cokoli zlatého a stříbrného bylo, pobral hejtman nad žoldnéři,'),
(1556431,54,12,25,16,'Sloupy dva, moře jedno a podstavky, jichž byl nadělal Šalomoun do domu Hospodinova. Nebylo váhy mědi všech těch nádob.'),
(1556432,54,12,25,17,'Osmnácti loket byla výška sloupu jednoho, a makovice na něm měděná, kterážto makovice tří loket zvýší byla, a mřežování i jablka zrnatá na té makovici vůkol; všecko bylo měděné. Takovýž byl i druhý sloup s mřežováním.'),
(1556433,54,12,25,18,'Vzal také týž hejtman nad žoldnéři Saraiáše kněze předního, a Sofoniáše kněze nižšího, a tři strážné prahu.'),
(1556434,54,12,25,19,'A z města vzal komorníka jednoho, kterýž byl hejtmanem nad muži bojovnými, a pět mužů z těch, jenž bývali při králi, kteříž nalezeni byli v městě, a předního spisovatele vojska, kterýž popisoval vojsko z lidu země, a šedesáte mužů z lidu země, kteříž se nalezli v městě.'),
(1556435,54,12,25,20,'Zjímav tedy je Nebuzardan hejtman nad žoldnéři, přivedl je k králi Babylonskému do Ribla.'),
(1556436,54,12,25,21,'I pobil je král Babylonský, a zmordoval je v Ribla, v zemi Emat, a tak zaveden jest Juda z země své.'),
(1556437,54,12,25,22,'Lidu pak, kterýž zůstal v zemi Judské, jehož byl zanechal Nabuchodonozor král Babylonský, představil Godoliáše syna Achikama, syna Safanova.'),
(1556438,54,12,25,23,'I uslyšeli všickni hejtmané vojska, oni i lid jejich, že postavil za správce král Babylonský Godoliáše, a přišli k Godoliášovi do Masfa, totiž Izmael syn Netaniášův, a Jochanan syn Kareachův, a Saraiáš syn Tanchumeta Netofatského, a Jazaniáš syn Machatův, oni i lid jejich.'),
(1556439,54,12,25,24,'Tedy přisáhl jim Godoliáš i lidu jejich, a řekl jim: Nebojte se služby Kaldejských, zůstaňte v zemi, a služte králi Babylonskému, a dobře vám bude.'),
(1556440,54,12,25,25,'I stalo se měsíce sedmého, přišel Izmael syn Netaniáše, syna Elisamova, z semene královského, a deset mužů s ním. I zabili Godoliáše, a umřel; takž i Židy i Kaldejské, kteříž s ním byli v Masfa.'),
(1556441,54,12,25,26,'Pročež zdvih se všecken lid, od malého až do velikého, i hejtmané vojsk, ušli do Egypta; nebo se báli Kaldejských.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556442,54,12,25,27,'Stalo se také léta třidcátého sedmého po zajetí Joachina krále Judského, dvanáctého měsíce, dvadcátého sedmého dne téhož měsíce, povýšil Evilmerodach král Babylonský toho léta, když počal kralovati, Joachina krále Judského, pustiv ho z žaláře.'),
(1556443,54,12,25,28,'A mluvil s ním dobrotivě, i stolici jeho postavil nad stolice jiných králů, kteříž s ním byli v Babyloně.'),
(1556444,54,12,25,29,'Změnil též roucho jeho, kteréž měl v žaláři. I jídal vždycky před ním po všecky dny života svého.'),
(1556445,54,12,25,30,'Nebo vyměřený pokrm ustavičně dáván byl jemu od krále, a to na každý den po všecky dny života jeho.'),
(1556446,54,13,1,1,'Adam, Set, Enos,'),
(1556447,54,13,1,2,'Kainan, Mahalaleel, Járed,'),
(1556448,54,13,1,3,'Enoch, Matuzalém, Lámech,'),
(1556449,54,13,1,4,'Noé, Sem, Cham a Jáfet.'),
(1556450,54,13,1,5,'Synové Jáfetovi: Gomer, Magog, Madai, Javan, Tubal, Mešech a Tiras.'),
(1556451,54,13,1,6,'Synové pak Gomerovi: Ascenez, Difat a Togorma.'),
(1556452,54,13,1,7,'Synové pak Javanovi: Elisa, Tarsis, Cetim a Rodanim.'),
(1556453,54,13,1,8,'Synové Chamovi: Chus, Mizraim, Put a Kanán.'),
(1556454,54,13,1,9,'A synové Chusovi: Sába, Evila, Sabata, Regma, Sabatacha. Synové pak Regmovi: Sába a Dedan.'),
(1556455,54,13,1,10,'Zplodil také Chus Nimroda; ten počal mocným býti na zemi.'),
(1556456,54,13,1,11,'Mizraim pak zplodil Ludim, Anamim, Laabim a Neftuim,'),
(1556457,54,13,1,12,'Fetruzim také a Chasluim, (odkudž pošli Filistinští), a Kafturim.'),
(1556458,54,13,1,13,'Kanán pak zplodil Sidona, prvorozeného svého, a Het,'),
(1556459,54,13,1,14,'A Jebuzea, Amorea a Gergezea,'),
(1556460,54,13,1,15,'A Hevea, Aracea a Sinea,'),
(1556461,54,13,1,16,'A Aradia, Samarea a Amatea.'),
(1556462,54,13,1,17,'Synové Semovi: Elam, Assur, Arfaxad, Lud, Aram, Hus a Hul, Geter a Mas.'),
(1556463,54,13,1,18,'A Arfaxad zplodil Sále, Sále pak zplodil Hebera.'),
(1556464,54,13,1,19,'Heberovi pak narodili se dva synové, z nichž jednoho jméno Peleg, proto že za dnů jeho rozdělena byla země, jméno pak bratra jeho Jektan.'),
(1556465,54,13,1,20,'Kterýžto Jektan zplodil Elmodada, Salefa, Azarmota a Járe,'),
(1556466,54,13,1,21,'A Adoráma, Uzala a Dikla,'),
(1556467,54,13,1,22,'A Ebale, Abimahele a Sebai,'),
(1556468,54,13,1,23,'A Ofira, Evila a Jobaba. Všickni ti byli synové Jektanovi.'),
(1556469,54,13,1,24,'Sem, Arfaxad, Sále,'),
(1556470,54,13,1,25,'Heber, Peleg, Réhu,'),
(1556471,54,13,1,26,'Sárug, Náchor, Táre,'),
(1556472,54,13,1,27,'Abram, ten jest Abraham.'),
(1556473,54,13,1,28,'Synové Abrahamovi: Izák a Izmael.'),
(1556474,54,13,1,29,'Tito jsou rodové jejich: Prvorozený Izmaelův Nabajot, Cedar, Adbeel a Mabsan,'),
(1556475,54,13,1,30,'Masma, Dumah, Massa, Hadad a Tema,'),
(1556476,54,13,1,31,'Jetur, Nafis a Cedma. Ti jsou synové Izmaelovi.'),
(1556477,54,13,1,32,'Synové pak Cetury, ženiny Abrahamovy: Ta porodila Zamrana, Jeksana, Madana, Madiana, Jezbocha a Suecha. Synové pak Jeksanovi: Sába a Dedan.'),
(1556478,54,13,1,33,'Synové pak Madianovi: Efa, Efer, Enoch, Abida a Helda. Všickni ti synové Cetury.'),
(1556479,54,13,1,34,'Zplodil tedy Abraham Izáka. Synové pak Izákovi: Ezau a Izrael.'),
(1556480,54,13,1,35,'Synové Ezau: Elifaz, Rahuel, Jehus, Jhelom a Kore.'),
(1556481,54,13,1,36,'Synové Elifazovi: Teman, Omar, Sefi, Gatam, Kenaz a syn Tamny, totiž Amalech.'),
(1556482,54,13,1,37,'Synové Rahuelovi: Nahat, Zára, Samma a Méza.'),
(1556483,54,13,1,38,'Synové pak Seir: Lotan, Sobal, Sebeon, Ana, Dison, Eser a Dízan.'),
(1556484,54,13,1,39,'Synové pak Lotanovi: Hori a Homam. Sestra pak Lotanova: Tamna.'),
(1556485,54,13,1,40,'Synové Sobalovi: Alian, Manáhat, Ebal, Sefi a Onam. Synové pak Sebeonovi: Aia a Ana.'),
(1556486,54,13,1,41,'Synové Anovi: Dison. A synové Disonovi: Hamran, Eseban, Jetran a Charan.'),
(1556487,54,13,1,42,'Synové Eser: Balaan, Závan a Jakan. Synové Dízonovi: Hus a Aran.'),
(1556488,54,13,1,43,'Tito pak jsou králové, kteříž kralovali v zemi Idumejské, prvé než kraloval který král z synů Izraelských: Béla syn Beorův, jehožto město jméno mělo Denaba.'),
(1556489,54,13,1,44,'A když umřel Béla, kraloval na místě jeho Jobab, syn Záre z Bozra.'),
(1556490,54,13,1,45,'A když umřel Jobab, kraloval místo něho Husam z země Temanské.'),
(1556491,54,13,1,46,'A když umřel Husam, kraloval místo něho Adad syn Badadův, kterýž porazil Madianské v krajině Moábské; jehož město jméno mělo Avith.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556492,54,13,1,47,'A když umřel Adad, kraloval na místě jeho Semla z Masreka.'),
(1556493,54,13,1,48,'A když umřel Semla, kraloval místo něho Saul z Rohobot řeky.'),
(1556494,54,13,1,49,'A když umřel Saul, kraloval místo něho Bálanan, syn Achoborův.'),
(1556495,54,13,1,50,'A když umřel Bálanan, kraloval místo něho Adad, jehož město řečené Pahu; jméno pak ženy jeho Mehetabel, dcera Matredy, dcery Mezábovy.'),
(1556496,54,13,1,51,'A když umřel Adad, byli vývodové Idumejští: Vývoda Tamna, vývoda Alja, vývoda Jetet,'),
(1556497,54,13,1,52,'Vývoda Olibama, vývoda Ela, vývoda Finon,'),
(1556498,54,13,1,53,'Vývoda Kenaz, vývoda Teman, vývoda Mabsar,'),
(1556499,54,13,1,54,'Vývoda Magdiel, vývoda Híram. Ti byli vývodové Idumejští.'),
(1556500,54,13,2,1,'Tito jsou synové Izraelovi: Ruben, Simeon, Léví, Juda, Izachar a Zabulon,'),
(1556501,54,13,2,2,'Dan, Jozef, Beniamin, Neftalím, Gád a Asser.'),
(1556502,54,13,2,3,'Synové Judovi: Her, Onan a Séla. Ti tři narodili se jemu z dcery Suovy Kananejské. Ale Her, prvorozený Judův, byl zlý před očima Hospodinovýma, protož zabil ho.'),
(1556503,54,13,2,4,'Támar pak nevěsta jeho porodila mu Fáresa a Záru. Všech synů Judových pět.'),
(1556504,54,13,2,5,'Synové Fáresovi: Ezron a Hamul.'),
(1556505,54,13,2,6,'Synové pak Záre: Zamri, Etan, Héman, Kalkol a Dára, všech těch pět.'),
(1556506,54,13,2,7,'A synové Zamri: Charmi, vnuk Achar, kterýž zkormoutil Izraele, zhřešiv při věci proklaté.'),
(1556507,54,13,2,8,'Synové pak Etanovi: Azariáš.'),
(1556508,54,13,2,9,'Synové pak Ezronovi, kteříž se mu zrodili: Jerachmeel, Ram a Chelubai.'),
(1556509,54,13,2,10,'Ram pak zplodil Aminadaba, a Aminadab zplodil Názona, kníže synů Juda.'),
(1556510,54,13,2,11,'Názon pak zplodil Salmona, a Salmon zplodil Bóza.'),
(1556511,54,13,2,12,'A Bóz zplodil Obéda, a Obéd zplodil Izai.'),
(1556512,54,13,2,13,'Izai pak zplodil prvorozeného svého Eliaba, a Abinadaba druhého, a Sammu třetího,'),
(1556513,54,13,2,14,'Natanaele čtvrtého, Raddaia pátého,'),
(1556514,54,13,2,15,'Ozema šestého, Davida sedmého,'),
(1556515,54,13,2,16,'A sestry jejich: Sarvii a Abigail. Synové pak Sarvie byli: Abizai, Joáb, Azael, tři.'),
(1556516,54,13,2,17,'Abigail pak porodila Amazu, otec pak Amazův byl Jeter Izmaelitský.'),
(1556517,54,13,2,18,'Kálef pak syn Ezronův zplodil s Azubou manželkou a s Jeriotou syny. Jehož tito synové byli: Jeser, Sobab a Ardon.'),
(1556518,54,13,2,19,'Když pak umřela Azuba, pojal sobě Kálef Efratu, kteráž mu porodila Hura.'),
(1556519,54,13,2,20,'A Hur zplodil Uri, a Uri zplodil Bezeleele.'),
(1556520,54,13,2,21,'Potom všel Ezron k dceři Machira otce Galádova, kterouž on pojal, když byl v šedesáti letech. I porodila jemu Seguba.'),
(1556521,54,13,2,22,'Segub pak zplodil Jaira, kterýž měl třimecítma měst v zemi Galád.'),
(1556522,54,13,2,23,'Nebo vzal Gessurejským a Assyrským vsi Jairovy, i Kanat s městečky jeho, šedesáte měst.To všecko pobrali synové Machirovi, otce Galádova.'),
(1556523,54,13,2,24,'Též i po smrti Ezronově, když již pojal byl Kálef Efratu, manželka Ezronova Abia porodila jemu také Ashura, otce Tekoa.'),
(1556524,54,13,2,25,'Byli pak synové Jerachmeele prvorozeného Ezronova: Prvorozený Ram, po něm Buna a Oren, a Ozem s Achia.'),
(1556525,54,13,2,26,'Měl také manželku druhou Jerachmeel, jménem Atara. Ta jest matka Onamova.'),
(1556526,54,13,2,27,'Byli pak synové Ramovi prvorozeného Jerachmeele: Maaz a Jamin a Eker.'),
(1556527,54,13,2,28,'Též synové Onamovi byli: Sammai a Jáda. A synové Sammai: Nádab a Abisur.'),
(1556528,54,13,2,29,'Jméno pak manželky Abisurovy Abichail; ktéráž porodila jemu Achbana a Molida.'),
(1556529,54,13,2,30,'A synové Nádabovi: Seled a Appaim. Ale umřel Seled bez dětí.'),
(1556530,54,13,2,31,'Synové pak Appaimovi: Jesi; a synové Jesi: Sesan; a dcera Sesanova: Achlai.'),
(1556531,54,13,2,32,'Synové pak Jády, bratra Sammaiova: Jeter a Jonatan. Ale umřel Jeter bez dětí.'),
(1556532,54,13,2,33,'Synové pak Jonatanovi: Felet a Záza. Ti byli synové Jerachmeelovi.'),
(1556533,54,13,2,34,'Neměl pak Sesan synů, ale dceru. A měl Sesan služebníka Egyptského jménem Jarchu.'),
(1556534,54,13,2,35,'Protož dal Sesan dceru svou Jarchovi služebníku svému za manželku, kteráž porodila mu Attaie.'),
(1556535,54,13,2,36,'Attai pak zplodil Nátana, a Nátan zplodil Zabada.'),
(1556536,54,13,2,37,'Zabad pak zplodil Eflale, a Eflal zplodil Obéda.'),
(1556537,54,13,2,38,'Obéd pak zplodil Jéhu, a Jéhu zplodil Azariáše.'),
(1556538,54,13,2,39,'Azariáš pak zplodil Cheleza, a Chelez zplodil Elasu.'),
(1556539,54,13,2,40,'Elasa pak zplodil Sismaie, a Sismai zplodil Salluma.'),
(1556540,54,13,2,41,'Sallum pak zplodil Jekamiáše, a Jekamiáš zplodil Elisama.'),
(1556541,54,13,2,42,'Synové pak Kálefa, bratra Jerachmeelova: Mésa prvorozený jeho. On byl otec Zifejských i synů Marese, otce Hebronova.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556542,54,13,2,43,'Synové pak Hebronovi: Chóre a Tapuach, a Rekem a Sema.'),
(1556543,54,13,2,44,'Sema pak zplodil Rachama otce Jorkeamova, a Rekem zplodil Sammaie.'),
(1556544,54,13,2,45,'Syn pak Sammai byl Maon; kterýžto Maon byl otec Betsurských.'),
(1556545,54,13,2,46,'Efa také, ženina Kálefova, porodila Chárana a Mozu a Gazeza. A Cháran zplodil Gazeza.'),
(1556546,54,13,2,47,'Synové pak Johedai: Regem, Jotam, Gesan, Felet, Efa a Saaf.'),
(1556547,54,13,2,48,'S ženinou Maachou Kálef zplodil Sebera a Tirchana.'),
(1556548,54,13,2,49,'Porodila pak Saafa otce Madmanejských, Sévu otce Makbenejských a otce Gibejských. Též dcera Kálefova Axa.'),
(1556549,54,13,2,50,'Ti byli synové Kálefovi, syna Hur prvorozeného Efraty: Sobal otec Kariatjeharimských,'),
(1556550,54,13,2,51,'Salma otec Betlémských, Charef otec čeledi Betgaderských.'),
(1556551,54,13,2,52,'Měl pak syny Sobal otec Kariatjeharimských: Haroe otce obyvatelů dílu Menuchotských.'),
(1556552,54,13,2,53,'A čeledi Kariatjeharimských, Jeterských, Putských, Sumatských a Misraiských. Z těch pošli Zaratští a Estaolští.'),
(1556553,54,13,2,54,'Synové Salmy: Betlémští, Netofatští, Atarotští z čeledi Joábovy, a Zarští, kteříž užívali dílu Menuchotských,'),
(1556554,54,13,2,55,'A čeledi písařů obývajících v Jábezu, Tiratských, Simatských, Suchatských. Ti jsou Cinejští příchozí z Amata, otce čeledi Rechabovy.'),
(1556555,54,13,3,1,'Tito jsou pak synové Davidovi, kteříž se jemu zrodili v Hebronu: Prvorozený Amnon z Achinoam Jezreelské, druhý Daniel z Abigail Karmelské;'),
(1556556,54,13,3,2,'Třetí Absolon syn Maachy, dcery Tolmai, krále Gessur, čtvrtý Adoniáš, syn Haggit;'),
(1556557,54,13,3,3,'Pátý Sefatiáš z Abitál, šestý Jetram, z Egly manželky jeho.'),
(1556558,54,13,3,4,'Šest se mu jich zrodilo v Hebronu, kdež kraloval sedm let a šest měsíců; třidceti pak a tři kraloval v Jeruzalémě.'),
(1556559,54,13,3,5,'Potom tito se jemu zrodili v Jeruzalémě: Sammua, Sobab, Nátan a Šalomoun, čtyři, z Betsabé, dcery Amielovy;'),
(1556560,54,13,3,6,'Též Ibchar, Elisama a Elifelet;'),
(1556561,54,13,3,7,'A Noga, Nefeg a Jafia;'),
(1556562,54,13,3,8,'A Elisama, Eliada a Elifelet, těch devět.'),
(1556563,54,13,3,9,'Všickni ti synové Davidovi krom synů ženin, a Támar sestra jejich.'),
(1556564,54,13,3,10,'Syn pak Šalomounův Roboám, Abiam syn jeho, Aza syn jeho, Jozafat syn jeho,'),
(1556565,54,13,3,11,'Joram syn jeho, Ochoziáš syn jeho, Joas syn jeho,'),
(1556566,54,13,3,12,'Amaziáš syn jeho, Azariáš syn jeho, Jotam syn jeho,'),
(1556567,54,13,3,13,'Achas syn jeho, Ezechiáš syn jeho, Manasses syn jeho,'),
(1556568,54,13,3,14,'Amon syn jeho, Joziáš syn jeho.'),
(1556569,54,13,3,15,'Synové pak Joziášovi: Prvorozený Jochanan, druhý Joakim, třetí Sedechiáš, čtvrtý Sallum.'),
(1556570,54,13,3,16,'Synové pak Joakimovi: Jekoniáš syn jeho, Sedechiáš syn jeho.'),
(1556571,54,13,3,17,'Synové pak Jekoniáše vězně: Salatiel syn jeho.'),
(1556572,54,13,3,18,'Toho pak Malkiram, Pedai, Senazar, Jekamia, Hosama a Nedabia.'),
(1556573,54,13,3,19,'Synové pak Pedaiovi: Zorobábel a Semei. A syn Zorobábelův: Mesullam, Chananiáš, a Selomit sestra jejich.'),
(1556574,54,13,3,20,'Toho pak Chasuba, Ohel, Berechiáš, Chasadiáš a Jusabchesed, těch pět.'),
(1556575,54,13,3,21,'Syn pak Chananiášův: Pelatia a Izaiáš. Synové Refaie, synové Arnanovi, synové Abdiášovi, synové Sechaniovi.'),
(1556576,54,13,3,22,'A synové Sechaniovi: Semaiáš. A synové Semaiášovi: Chattus, Igal, Bariach, Neariáš a Safat, šest.'),
(1556577,54,13,3,23,'A syn Neariáše: Elioenai, Ezechiáš a Azrikam, ti tři.'),
(1556578,54,13,3,24,'Též synové Elioenai: Hodaviáš, Eliasib, Pelaiáš, Akkub, Jochanan, Delaiáš a Anani, těch sedm.'),
(1556579,54,13,4,1,'Synové Judovi: Fáres, Ezron, Charmi, Hur a Sobal.'),
(1556580,54,13,4,2,'Reaiáš pak syn Sobalův zplodil Jachata, Jachat pak zplodil Ahumai a Laad. Ti jsou rodové Zarati.'),
(1556581,54,13,4,3,'A tito z otce Etama: Jezreel, Isma a Idbas; a jméno sestry jejich Zelelfoni.'),
(1556582,54,13,4,4,'Fanuel pak otec Gedor, a Ezer otec Chusův. Ti jsou synové Hur prvorozeného Efraty, otce Betlémských.'),
(1556583,54,13,4,5,'Ashur pak otec Tekoe měl dvě manželky, Chélu a Naaru.'),
(1556584,54,13,4,6,'I porodila jemu Naara Achuzama, Hefera, Temana a Achastara. Ti jsou synové Naary.'),
(1556585,54,13,4,7,'Synové pak Chéle: Zeret, Jezochar a Etnan.'),
(1556586,54,13,4,8,'Kóz pak zplodil Anuba, Hazobeba, a rodiny Acharchele syna Harumova.'),
(1556587,54,13,4,9,'Byl pak Jábez slavnější nad bratří své, a matka jeho nazvala jméno jeho Jábez, řkuci: Nebo jsem ho porodila s bolestí.'),
(1556588,54,13,4,10,'Kterýžto Jábez vzýval Boha Izraelského, řka: Jestliže štědře požehnáš mi, a rozšíříš meze mé, a bude ruka tvá se mnou, a vysvobodíš mne od zlého, abych bolesti netrpěl. I učinil Bůh, začež žádal.'),
(1556589,54,13,4,11,'Chelub pak, bratr Sucha, zplodil Mechiru. Onť jest otec Estonův.'),
(1556590,54,13,4,12,'Eston pak zplodil Betrafa, Paseacha a Techinna, otce města Náchas. Ti jsou muži Rechy.'),
(1556591,54,13,4,13,'Synové pak Cenezovi: Otoniel a Saraiáš. Synové pak Otonielovi: Chatat.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556592,54,13,4,14,'Meonatai pak zplodil Ofru, Saraiáš pak zplodil Joába, otce bydlících v údolí řemeslníků; nebo tam řemeslníci byli.'),
(1556593,54,13,4,15,'Synové pak Kálefa, syna Jefonova: Iru, Ela a Naam. Syn pak Ela: Cenez.'),
(1556594,54,13,4,16,'Synové pak Jehalleleelovi: Zif, Zifa, Tiriáš a Asarel.'),
(1556595,54,13,4,17,'A synové Ezry: Jeter, Mered, Efer a Jalon. Porodila také Miriama, Sammai a Jezba otce Estemo.'),
(1556596,54,13,4,18,'Manželka pak jeho Jehudia porodila Jereda otce Gedor, a Hebera otce Socho, a Jekutiele otce Zanoe. A ti jsou synové Betie dcery Faraonovy, kterouž pojal Mered.'),
(1556597,54,13,4,19,'Synové pak manželky Hodia sestry Nachamovy, otce Cejly: Garmi a Estemo Maachatský.'),
(1556598,54,13,4,20,'Synové pak Simonovi: Amnon, Rinna, Benchanan a Tilon. A synové Jesi: Zochet a Benzochet.'),
(1556599,54,13,4,21,'Synové Séla syna Judova: Her otec Lechův, a Lada otec Maresův, a čeledi domu těch, jenž dělali díla kmentová v domě Asbea,'),
(1556600,54,13,4,22,'A Jokim a muži Chozeby, Joas a Saraf, kteříž panovali v Moáb, a Jasubi Lechem. Ale ty věci jsou starodávní.'),
(1556601,54,13,4,23,'Toť jsou ti hrnčíři obyvatelé v štěpnicích a ohradách u krále, příčinou díla jeho tam bydlíce.'),
(1556602,54,13,4,24,'Synové Simeonovi: Namuel, Jamin, Jarib, Zára a Saul.'),
(1556603,54,13,4,25,'Sallum syn jeho, Mabsam syn jeho, Masma syn jeho.'),
(1556604,54,13,4,26,'Synové pak Masmovi: Hamuel syn jeho, Zakur syn jeho, Semei syn jeho.'),
(1556605,54,13,4,27,'Ten Semei měl synů šestnácte a dcer šest. Bratří pak jejich neměli mnoho synů, tak že vší rodiny jejich nebylo tak mnoho, jako synů Judových.'),
(1556606,54,13,4,28,'Bydlili pak v Bersabé a Molada a v Azarsual,'),
(1556607,54,13,4,29,'A v Bála, v Esem a v Tolad,'),
(1556608,54,13,4,30,'A v Betueli, v Horma a v Sicelechu,'),
(1556609,54,13,4,31,'A v Betmarchabot, a v Azarsusim, v Betberi a v Saraim. Ta byla města jejich, dokudž kraloval David.'),
(1556610,54,13,4,32,'Vsi také jejich při Etam, Ain, Remmon, Tochen, Asan, pěti městech.'),
(1556611,54,13,4,33,'A tak všecky vesnice jejich, kteréž byly vůkol těch měst až do Baal, ta byla obydlé jejich vedlé rodu jejich.'),
(1556612,54,13,4,34,'A Mesobab, Jamlech a Josa syn Amazův;'),
(1556613,54,13,4,35,'A Joel, a Jéhu syn Jozabiáše, syna Saraiášova, syna Azielova;'),
(1556614,54,13,4,36,'A Elioenai, Jákoba, Jesochaiáš, Asaiáš, Adiel a Jesimeel a Benaiáš;'),
(1556615,54,13,4,37,'A Ziza syn Sifi, syna Allonova, syna Jedaiášova, syna Simri, syna Semaiášova.'),
(1556616,54,13,4,38,'Tito ze jména vyčtení ustaveni jsou za knížata v čeledech svých, a čeledi otcovské jejich rozmnožily se náramně.'),
(1556617,54,13,4,39,'A protož brali se, kudyž se vchází k Gedor, až k východu po údolí tom, aby hledali pastev dobytku svému.'),
(1556618,54,13,4,40,'I nalezli pastvu hojnou a výbornou, zemi pak prostrannou, bezpečnou a pokojnou, a že z Chama byli ti, kteříž bydlili tam před tím.'),
(1556619,54,13,4,41,'Protož přišedše ti napsaní ze jména ve dnech Ezechiáše krále Judského, pobořili stany jejich a příbytky, kteříž tam nalezeni byli, a zmordovali je, tak že jich do tohoto dne není, a sami osedli místo nich; nebo měli tu pastvu dobytku svému.'),
(1556620,54,13,4,42,'Někteří pak z těch synů Simeonových odebrali se na horu Seir, mužů pět set, jichž Pelatia, Neariáš, Refaiáš a Uziel, synové Jesi, byli vůdcové.'),
(1556621,54,13,4,43,'I vyplénili ostatek těch, kteříž ušli z Amalechitských, a bydlili tam až do tohoto dne.'),
(1556622,54,13,5,1,'Synové pak Rubenovi prvorozeného Izraelova: (nebo on byl prvorozený, ale když poškvrnil lože otce svého, dáno jest prvorozenství jeho synům Jozefovým, syna Izraelova, však jemu není přičteno prvorozenství.'),
(1556623,54,13,5,2,'Nebo Judas byl nejsilnější z bratří svých, a kníže mezi nimi, ale prvorozenství Jozefovi náleželo).'),
(1556624,54,13,5,3,'Synové, pravím, Rubenovi, prvorozeného Izraelova: Enoch, Fallu, Ezron a Charmi.'),
(1556625,54,13,5,4,'Synové Joelovi: Semaiáš syn jeho, Gog syn jeho, Semei syn jeho;'),
(1556626,54,13,5,5,'Mícha syn jeho, Reaiáš syn jeho, Bál syn jeho;'),
(1556627,54,13,5,6,'Béra syn jeho, jehož zavedl Tiglatfalazar král Assyrský. Ten byl knížetem pokolení Rubenova.'),
(1556628,54,13,5,7,'Bratří pak jeho po čeledech jejich, když vyčteni byli po rodinách svých, knížetem byl Jehiel a Zachariáš.'),
(1556629,54,13,5,8,'A Béla syn Azaza, syna Semy, syna Joelova. Ten bydlil v Aroer až do Nébo a Balmeon.'),
(1556630,54,13,5,9,'Potom i na východ bydlil, až kudy se vchází na poušť od řeky Eufrates; nebo stáda jejich rozmnožila se v zemi Galádské.'),
(1556631,54,13,5,10,'Pročež ve dnech Saulových bojovali s Agarenskými, kteříž poraženi jsou od ruky jejich. A tak bydlili v staních jejich po vší krajině východní země Galádské.'),
(1556632,54,13,5,11,'Synové pak Gádovi naproti nim bydlili v zemi Bázan, až do Sálechy.'),
(1556633,54,13,5,12,'Joel byl kníže jejich, a Safan druhý. Ale Janai a Safat v Bázan zůstali.'),
(1556634,54,13,5,13,'Bratří pak jejich po domích otců svých: Michael, Mesullam, Seba, Jorai, Jachan, Zia, Heber, těch sedm.'),
(1556635,54,13,5,14,'(Ti byli synové Abichailovi, synové Hurovi, synové Jaroachovi, synové Galádovi, synové Michaelovi, synové Jesisovi, synové Jachdovi, synové Buzovi.)'),
(1556636,54,13,5,15,'Též Ahi syn Abdiele, syna Gunova, kníže v domě otců jich.'),
(1556637,54,13,5,16,'I bydlili v Galád, v Bázan a v vesnicech jeho, a ve všech předměstích Sáron, až do hranic jejich.'),
(1556638,54,13,5,17,'Všickni tito vyčteni byli ve dnech Jotama krále Judského, a ve dnech Jeroboáma krále Izraelského.'),
(1556639,54,13,5,18,'Synů Rubenových a Gádových a polovice pokolení Manassesova, mužů silných, nosících štít a meč, a natahujících lučiště, a umělých v bitvě, čtyřidceti a čtyři tisíce, sedm set a šedesát vycházejících k boji.'),
(1556640,54,13,5,19,'I bojovali s Agarenskými, Iturejskými, Nafejskými a Nodabskými.'),
(1556641,54,13,5,20,'A měli pomoc proti nim. I dáni jsou v ruku jich Agarenové i všecko, což měli. Nebo k Bohu volali v boji, a vyslyšel je, nebo doufali v něho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556642,54,13,5,21,'I zajali stáda jejich, velbloudů jejich padesáte tisíců, a dobytka dvě stě a padesáte tisíců, a oslů dva tisíce, a lidí sto tisíc osob.'),
(1556643,54,13,5,22,'Zraněných také množství padlo, nebo od Boha byla porážka ta. I bydlili na místě jejich až do přestěhování svého.'),
(1556644,54,13,5,23,'Synové pak polovice pokolení Manassesova bydlili v té zemi od Bázanu až do Balhermon i Sanir, totiž hory Hermon; nebo i oni rozmnoženi byli.'),
(1556645,54,13,5,24,'Tato pak byla knížata v domě otců jejich: Efer, Jesi, Eliel, Azriel, Jeremiáš, Hodaviáš a Jachdiel, muži udatní a silní, muži slovoutní, knížata domu otců svých.'),
(1556646,54,13,5,25,'Ale když přestoupili proti Bohu otců svých, a smilnili, následujíce bohů národů země té, kteréž shladil Bůh od tváři jejich:'),
(1556647,54,13,5,26,'Vzbudil Bůh Izraelský ducha Fule krále Assyrského, a ducha Tiglatfalazara krále Assyrského, kterýž přenesl pokolení Rubenovo a Gádovo a polovici pokolení Manassesova, a dovedl je do Chelach a do Chabor, až do Hara a k řece Gozan až do dnešního dne.'),
(1556648,54,13,6,1,'Synové Léví: Gerson, Kahat a Merari.'),
(1556649,54,13,6,2,'Synové pak Kahat: Amram, Izar, Hebron a Uziel.'),
(1556650,54,13,6,3,'Synové pak Amramovi: Aron, Mojžíš, a Maria. Synové pak Aronovi: Nádab, Abiu, Eleazar a Itamar.'),
(1556651,54,13,6,4,'Eleazar zplodil Fínesa, Fínes zplodil Abisua.'),
(1556652,54,13,6,5,'Abisua pak zplodil Bukki, Bukki pak zplodil Uzi.'),
(1556653,54,13,6,6,'Uzi pak zplodil Zerachiáše, Zerachiáš pak zplodil Meraiota.'),
(1556654,54,13,6,7,'Meraiot zplodil Amariáše, Amariáš pak zplodil Achitoba.'),
(1556655,54,13,6,8,'Achitob pak zplodil Sádocha, Sádoch pak zplodil Achimaasa.'),
(1556656,54,13,6,9,'Achimaas pak zplodil Azariáše, Azariáš pak zplodil Jochanana.'),
(1556657,54,13,6,10,'Jochanan pak zplodil Azariáše. Onť jest užíval kněžství v domě, jejž ustavěl Šalomoun v Jeruzalémě.'),
(1556658,54,13,6,11,'Zplodil pak Azariáš Amariáše, Amariáš pak zplodil Achitoba.'),
(1556659,54,13,6,12,'Achitob zplodil Sádocha, Sádoch pak zplodil Salluma.'),
(1556660,54,13,6,13,'Sallum pak zplodil Helkiáše, Helkiáš pak zplodil Azariáše.'),
(1556661,54,13,6,14,'Azariáš pak zplodil Saraiáše, Saraiáš pak zplodil Jozadaka.'),
(1556662,54,13,6,15,'Jozadak pak odšel, když převedl Hospodin Judu a Jeruzalém skrze Nabuchodonozora.'),
(1556663,54,13,6,16,'Synové Léví: Gersom, Kahat a Merari.'),
(1556664,54,13,6,17,'Tato pak jsou jména synů Gersomových: Lebni a Semei.'),
(1556665,54,13,6,18,'Synové pak Kahat: Amram, Izar, Hebron a Uziel.'),
(1556666,54,13,6,19,'Synové Merari: Moholi a Musi. A tak ty jsou čeledi Levítů po otcích jejich.'),
(1556667,54,13,6,20,'Gersomovi: Lebni syn jeho, Jachat syn jeho, Zimma syn jeho,'),
(1556668,54,13,6,21,'Joach syn jeho, Iddo syn jeho, Zára syn jeho, Jetrai syn jeho.'),
(1556669,54,13,6,22,'Synové Kahat: Aminadab syn jeho, Chóre syn jeho, Assir syn jeho,'),
(1556670,54,13,6,23,'Elkána syn jeho, a Abiazaf syn jeho, Assir syn jeho,'),
(1556671,54,13,6,24,'Tachat syn jeho, Uriel syn jeho, Uziáš syn jeho, Saul syn jeho.'),
(1556672,54,13,6,25,'Synové pak Elkánovi: Amasai a Achimot.'),
(1556673,54,13,6,26,'Elkána: Synové Elkánovi: Zofai syn jeho, a Nachat syn jeho,'),
(1556674,54,13,6,27,'Eliab syn jeho, Jerocham syn jeho, Elkána syn jeho.'),
(1556675,54,13,6,28,'Synové pak Samuelovi: Prvorozený Vasni a Abia.'),
(1556676,54,13,6,29,'Synové Merari: Moholi, Lebni syn jeho, Semei syn jeho, Uza syn jeho,'),
(1556677,54,13,6,30,'Sima syn jeho, Aggia syn jeho, Azaiáš syn jeho.'),
(1556678,54,13,6,31,'Tito jsou pak, kteréž ustanovil David k zpívání v domě Hospodinově, když tam postavena truhla,'),
(1556679,54,13,6,32,'Kteříž přisluhovali před příbytkem stánku úmluvy zpíváním, dokudž neustavěl Šalomoun domu Hospodinova v Jeruzalémě, a stáli podlé pořádku svého v přisluhování svém.'),
(1556680,54,13,6,33,'Tito jsou pak, kteříž stáli, i synové jejich, z synů Kahat: Héman kantor, syn Joele, syna Samuelova,'),
(1556681,54,13,6,34,'Syna Elkánova, syna Jerochamova, syna Elielova, syna Tohu,'),
(1556682,54,13,6,35,'Syna Sufova, syna Elkánova, syna Machatova, syna Amasai,'),
(1556683,54,13,6,36,'Syna Elkánova, syna Joelova, syna Azariášova, syna Sofoniášova,'),
(1556684,54,13,6,37,'Syna Tachatova, syna Assirova, syna Abiazafova, syna Chóre,'),
(1556685,54,13,6,38,'Syna Izarova, syna Kahatova, syna Léví, syna Izraelova.'),
(1556686,54,13,6,39,'A bratr jeho Azaf, kterýž stával po pravici jeho. Azaf pak byl syn Berechiáše, syna Simova,'),
(1556687,54,13,6,40,'Syna Michaelova, syna Baaseiášova, syna Malkiášova,'),
(1556688,54,13,6,41,'Syna Etni, syna Záry, syna Adaiova,'),
(1556689,54,13,6,42,'Syna Etanova, syna Zimmova, syna Semeiova,'),
(1556690,54,13,6,43,'Syna Jachatova, syna Gersomova, syna Léví.'),
(1556691,54,13,6,44,'Synové pak Merari, bratří jejich, stávali po levici: Etan, syn Kísi, syna Abdova, syna Malluchova,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556692,54,13,6,45,'Syna Chasabiášova, syna Amaziášova, syna Helkiášova,'),
(1556693,54,13,6,46,'Syna Amzova, syna Bánova, syna Semerova,'),
(1556694,54,13,6,47,'Syna Moholi, syna Musi, syna Merari, syna Léví.'),
(1556695,54,13,6,48,'Bratří pak jejich Levítové jiní oddáni jsou ke všelikému přisluhování příbytku domu Božího.'),
(1556696,54,13,6,49,'Ale Aron a synové jeho pálili na oltáři zápalu a na oltáři kadění, při všelikém přisluhování svatyně svatých, a k očišťování Izraele podlé všeho toho, jakož přikázal Mojžíš služebník Boží.'),
(1556697,54,13,6,50,'Tito pak jsou synové Aronovi: Eleazar syn jeho, Fínes syn jeho, Abisua syn jeho,'),
(1556698,54,13,6,51,'Bukki syn jeho, Uzi syn jeho, Zerachiáš syn jeho,'),
(1556699,54,13,6,52,'Meraiot syn jeho, Amariáš syn jeho, Achitob syn jeho,'),
(1556700,54,13,6,53,'Sádoch syn jeho, Achimaas syn jeho.'),
(1556701,54,13,6,54,'A tato obydlé jejich, po příbytcích jejich, v mezech jejich, synů Aronových po čeledi Kahatských; nebo jejich byl los.'),
(1556702,54,13,6,55,'A protož dali jim Hebron v zemi Judské, a předměstí jeho vůkol něho.'),
(1556703,54,13,6,56,'Pole však městská a vsi jejich dali Kálefovi synu Jefonovu.'),
(1556704,54,13,6,57,'Synům pak Aronovým dali z měst Judských města útočišťná: Hebron a Lebno a předměstí jeho, a Jeter i Estemo a předměstí jeho,'),
(1556705,54,13,6,58,'A Holon i předměstí jeho, a Dabir i předměstí jeho,'),
(1556706,54,13,6,59,'Též Asan a předměstí jeho, a Betsemes a předměstí jeho.'),
(1556707,54,13,6,60,'Z pokolení pak Beniamin: Gaba a předměstí jeho, a Allemet i předměstí jeho, i Anatot a předměstí jeho, všech měst jejich třinácte měst po čeledech jejich.'),
(1556708,54,13,6,61,'Synům též Kahatovým ostatním z čeledi toho pokolení dáno v polovici pokolení Manassesova losem měst deset.'),
(1556709,54,13,6,62,'Synům pak Gersonovým po čeledech jejich v pokolení Izachar a v pokolení Asser, a v pokolení Neftalím, a v pokolení Manassesovu v Bázan měst třináct.'),
(1556710,54,13,6,63,'Synům Merari po čeledech jejich v pokolení Ruben, a v pokolení Gád, a v pokolení Zabulon losem měst dvanáct.'),
(1556711,54,13,6,64,'Dali synové Izraelští Levítům ta města a předměstí jejich.'),
(1556712,54,13,6,65,'A dali je losem v pokolení synů Judových, a v pokolení synů Simeonových, a v pokolení synů Beniaminových, města ta, kteráž jmenovali ze jména.'),
(1556713,54,13,6,66,'A kteříž byli z čeledi synů Kahat, (byla pak města a hranice jejich v pokolení Efraimovu),'),
(1556714,54,13,6,67,'Těm dali města útočišťná: Sichem a předměstí jeho na hoře Efraim, a Gázer a předměstí jeho,'),
(1556715,54,13,6,68,'A Jekmaam i předměstí jeho, a Betoron i předměstí jeho,'),
(1556716,54,13,6,69,'Též i Aialon a předměstí jeho, a Getremmon s předměstím jeho.'),
(1556717,54,13,6,70,'A v polovici pokolení Manassesova: Aner a předměstí jeho, Balám a předměstí jeho, čeledem synů Kahat ostatním.'),
(1556718,54,13,6,71,'Synům pak Gersonovým v čeledi polovice pokolení Manassesova dali Golan v Bázan s předměstím jeho, a Astarot i předměstí jeho.'),
(1556719,54,13,6,72,'V pokolení pak Izachar: Kádes s předměstím jeho, Daberet a předměstí jeho,'),
(1556720,54,13,6,73,'Rámot také s předměstím jeho, a Anem i předměstí jeho.'),
(1556721,54,13,6,74,'V pokolení pak Asser: Masal s předměstím jeho, a Abdon i předměstí jeho,'),
(1556722,54,13,6,75,'Též Hukok s předměstím jeho, Rohob také i předměstí jeho.'),
(1556723,54,13,6,76,'V pokolení pak Neftalímovu: Kádes v Galilei a předměstí jeho, Hamon a předměstí jeho, a Kariataim i předměstí jeho.'),
(1556724,54,13,6,77,'Synům Merari ostatním v pokolení Zabulonovu dali Remmon s předměstím jeho, Tábor a předměstí jeho.'),
(1556725,54,13,6,78,'A za Jordánem u Jericha, k východní straně Jordánu, v pokolení Rubenovu: Bozor na poušti s předměstím jeho, a Jasa i předměstí jeho.'),
(1556726,54,13,6,79,'Kedemot také s předměstím jeho, a Mefat i předměstí jeho.'),
(1556727,54,13,6,80,'V pokolení pak Gád: Rámot v Galád s předměstím jeho, a Mahanaim i předměstí jeho,'),
(1556728,54,13,6,81,'I Ezebon s předměstím jeho, a Jazer i předměstí jeho.'),
(1556729,54,13,7,1,'Synové pak Izacharovi: Tola, Fua, Jasub a Simron, čtyři.'),
(1556730,54,13,7,2,'Synové pak Tolovi: Uzi, Refaia, Jeriel, Jachmai, Jipsam, Samuel, knížata po domích otců jejich, pošlí od Toly, muži udatní v pokoleních svých. Počet jejich ve dnech Davidových byl dvamecítma tisíců a šest set.'),
(1556731,54,13,7,3,'Synové Uzovi: Izrachiáš. Synové pak Izrachiášovi: Michael, Abdiáš, Joel a Isia, všech pět knížat.'),
(1556732,54,13,7,4,'A s nimi v pokoleních jejich, po čeledech jejich otcovských, mužů válečných třidceti šest tisíců; nebo mnoho měli žen a synů.'),
(1556733,54,13,7,5,'Bratří také jejich po všech čeledech Izachar, mužů udatných osmdesáte sedm tisíců, všech vyčtených.'),
(1556734,54,13,7,6,'Synové Beniaminovi: Béla, Becher, Jediael, tři.'),
(1556735,54,13,7,7,'Synové pak Bélovi: Ezbon, Uzi, Uziel, Jerimot a Iri, pět knížat čeledí otcovských, muži udatní; načteno jich dvamecítma tisíců, třidceti a čtyři.'),
(1556736,54,13,7,8,'Potom synové Becherovi: Zemira, Joas, Eliezer, Elioenai, Amri, Jeremot, Abiáš, Anatot a Alemet, všickni synové Becherovi.'),
(1556737,54,13,7,9,'Kterýchž počet po pokoleních jejich, a po knížatech v domě čeledí otcovských, mužů udatných, dvadceti tisíců a dvě stě.'),
(1556738,54,13,7,10,'Synové také Jediaelovi: Bilan. Synové pak Bilanovi: Jeus, Beniamin, Ahod, Kenan, Zetan, Tarsis a Achisachar.'),
(1556739,54,13,7,11,'Všech těch synů Jediaelových po knížatech čeledí, mužů udatných, sedmnáct tisíc a dvě stě, vycházejících na vojnu k bitvě,'),
(1556740,54,13,7,12,'Kromě Suppim a Chuppim, synů doma zrozených, a Chusim, synů vně zplozených.'),
(1556741,54,13,7,13,'Synové Neftalímovi: Jasiel, Guni, Jezer a Sallum, synové Bály.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556742,54,13,7,14,'Synové Manassesovi: Asriel, kteréhož mu manželka porodila. (Ženina též jeho Syrská porodila Machira, otce Galád.'),
(1556743,54,13,7,15,'Machir pak vzal manželku Chuppimovu a Suppimovu, a jméno sestry jeho Maacha.) Jméno pak druhého Salfad, a měl Salfad dcery.'),
(1556744,54,13,7,16,'Porodila pak Maacha manželka Machirova syna, kteréhož nazvala Fáres, a jméno bratra jeho Sáres, synové pak jeho Ulam a Rekem.'),
(1556745,54,13,7,17,'Synové pak Ulamovi: Bedan. Tiť jsou synové Galád syna Machirova, syna Manassesova.'),
(1556746,54,13,7,18,'Sestra pak jeho Molechet porodila Ishoda a Abiezera a Machla.'),
(1556747,54,13,7,19,'Byli pak synové Semidovi: Achian, Sechem, Likchi a Aniam.'),
(1556748,54,13,7,20,'Synové pak Efraimovi: Sutelach, a Bered syn jeho, Tachat syn jeho, Elada syn jeho, Tachat syn jeho,'),
(1556749,54,13,7,21,'Též Zabad syn jeho, Sutelach syn jeho, Ezer a Elad. I zbili je muži Gát, kteříž zrozeni byli v zemi té; nebo sstoupili byli, aby zajali dobytky jejich.'),
(1556750,54,13,7,22,'Protož kvílil Efraim otec jejich za mnohé dny, a přišli bratří jeho, aby ho těšili.'),
(1556751,54,13,7,23,'Potom všel k manželce své, kteráž počala a porodila syna, a nazval jméno jeho Beria, že byl v zámutku pro rodinu svou.'),
(1556752,54,13,7,24,'Dceru také Seeru, kteráž vystavěla Betoron dolní i horní, a Uzen Seera.'),
(1556753,54,13,7,25,'A Refacha syna jeho, Resefa, Telecha, a Tachana syna jeho,'),
(1556754,54,13,7,26,'Ladana syna jeho, Amiuda syna jeho, Elisama syna jeho,'),
(1556755,54,13,7,27,'Non syna jeho, Jozue syna jeho.'),
(1556756,54,13,7,28,'Vládařství pak jejich a bydlení jejich Bethel s vesnicemi svými, a k východu Náran, a k západu Gázer a vesnice jeho, Sichem s vesnicemi svými, až do Gázy a vesnic jeho.'),
(1556757,54,13,7,29,'A v místech naproti synům Manassesovým: Betsan s vesnicemi svými, Tanach s vesnicemi svými, Mageddo s vesnicemi svými, Dor s vesnicemi svými. V těch bydlili synové Jozefa syna Izraelova.'),
(1556758,54,13,7,30,'Synové Asser: Jemna, Jesua, Jesui, Beria, a Serach sestra jejich.'),
(1556759,54,13,7,31,'Synové pak Beriovi: Heber, Melchiel. Onť jest otec Birzavitův.'),
(1556760,54,13,7,32,'Heber pak zplodil Jafleta, Somera, Chotama, a Suu sestru jejich.'),
(1556761,54,13,7,33,'Synové pak Jafletovi: Pasach, Bimhal, a Asvat. Ti jsou synové Jafletovi.'),
(1556762,54,13,7,34,'Synové pak Somerovi: Achi, Rohaga, Jehubba a Aram.'),
(1556763,54,13,7,35,'Synové pak Helema, bratra jeho: Zofach, Jimna, Seles a Amal.'),
(1556764,54,13,7,36,'Synové Zofachovi: Suach, Charnefer, Sual, Beri a Jimra,'),
(1556765,54,13,7,37,'Bezer, Hod, Samma, Silsa, Jitran a Béra.'),
(1556766,54,13,7,38,'Synové Jeterovi: Jefunne, Fispa a Ara.'),
(1556767,54,13,7,39,'Synové pak Ulla: Arach, Haniel a Riziáš.'),
(1556768,54,13,7,40,'Všickni ti synové Asser, knížata domů otcovských, vybraní, udatní, přední z knížat, kteříž vyčteni do vojska k bitvě, v počtu šest a dvadceti tisíc mužů.'),
(1556769,54,13,8,1,'Beniamin pak zplodil Bélu, prvorozeného svého, Asbele druhého, Achracha třetího,'),
(1556770,54,13,8,2,'Nocha čtvrtého, Rafa pátého.'),
(1556771,54,13,8,3,'Béla pak měl syny: Addara, Geru, Abiuda,'),
(1556772,54,13,8,4,'Abisua, Námana, Achoacha,'),
(1556773,54,13,8,5,'A Geru, Sefufana a Churama.'),
(1556774,54,13,8,6,'Ti jsou synové Echudovi, ti jsou knížata čeledí otcovských, bydlících v Gabaa, kteříž je uvedli do Manáhat,'),
(1556775,54,13,8,7,'Totiž: Náman, a Achia a Gera. On přestěhoval je; zplodil pak Uza a Achichuda.'),
(1556776,54,13,8,8,'Sacharaim pak zplodil v krajině Moábské, když onen byl propustil je, s Chusimou a Bárou manželkami svými.'),
(1556777,54,13,8,9,'Zplodil s Chodes manželkou svou Jobaba, Sebia, Mésa a Malkama,'),
(1556778,54,13,8,10,'Jehuza, Sachia a Mirma. Ti jsou synové jeho, knížata čeledí otcovských.'),
(1556779,54,13,8,11,'S Chusimou pak byl zplodil Abitoba a Elpále.'),
(1556780,54,13,8,12,'Synové pak Elpálovi: Heber, Misam a Semer. Ten vystavěl Ono a Lod, i vsi jeho.'),
(1556781,54,13,8,13,'A Beria a Sema. Ti jsou knížata čeledí otcovských, bydlících v Aialon; ti zahnali obyvatele Gát.'),
(1556782,54,13,8,14,'Achio pak, Sasák a Jeremot,'),
(1556783,54,13,8,15,'Zebadiáš, Arad a Ader,'),
(1556784,54,13,8,16,'Michael, Ispa a Jocha synové Beria.'),
(1556785,54,13,8,17,'A Zebadiáš, Mesullam, Chiski, Heber,'),
(1556786,54,13,8,18,'Ismerai, Izliáš a Jobab synové Elpálovi.'),
(1556787,54,13,8,19,'A Jakim, Zichri a Zabdi.'),
(1556788,54,13,8,20,'Elienai, Ziletai a Eliel,'),
(1556789,54,13,8,21,'Adaiáš, Baraiáš a Simrat synové Simei.'),
(1556790,54,13,8,22,'Ispan a Heber a Eliel,'),
(1556791,54,13,8,23,'Abdon, Zichri a Chanan,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556792,54,13,8,24,'Chananiáš, Elam a Anatotiáš,'),
(1556793,54,13,8,25,'Ifdaiáš a Fanuel synové Sasákovi.'),
(1556794,54,13,8,26,'Samserai, Sechariáš a Ataliáš,'),
(1556795,54,13,8,27,'Jaresiáš, Eliáš a Zichri synové Jerochamovi.'),
(1556796,54,13,8,28,'Ta jsou knížata otcovských čeledí po rodinách svých, kterážto knížata bydlila v Jeruzalémě.'),
(1556797,54,13,8,29,'V Gabaon pak bydlilo kníže Gabaon, a jméno manželky jeho Maacha.'),
(1556798,54,13,8,30,'A syn jeho prvorozený Abdon, Zur, Cis, Bál a Nádab,'),
(1556799,54,13,8,31,'Ale Gedor, Achio, Zecher.'),
(1556800,54,13,8,32,'A Miklot zplodil Simea. I ti také naproti bratřím svým bydlili v Jeruzalémě s bratřími svými.'),
(1556801,54,13,8,33,'Ner pak zplodil Cisa, a Cis zplodil Saule. Saul pak zplodil Jonatu, Melchisua, Abinadaba a Ezbále.'),
(1556802,54,13,8,34,'Syn pak Jonatův Meribbál, Meribbál pak zplodil Mícha.'),
(1556803,54,13,8,35,'Synové pak Míchovi: Piton, Melech, Tarea a Achaz.'),
(1556804,54,13,8,36,'Achaz pak zplodil Jehoadu, Jehoada pak zplodil Alemeta, Azmaveta a Zimru. Zimri pak zplodil Mozu.'),
(1556805,54,13,8,37,'Moza pak zplodil Bina. Ráfa syn jeho, Elasa syn jeho, Azel syn jeho.'),
(1556806,54,13,8,38,'Azel pak měl šest synů, jichž tato jsou jména: Azrikam, Bochru, Izmael, Seariáš a Abdiáš a Chanan. Všickni ti synové Azelovi.'),
(1556807,54,13,8,39,'Synové pak Ezeka, bratra jeho: Ulam prvorozený jeho, Jehus druhý, a Elifelet třetí.'),
(1556808,54,13,8,40,'A byli synové Ulamovi muži udatní a střelci umělí, kteříž měli mnoho synů a vnuků až do sta a padesáti. Všickni ti byli z synů Beniaminových.'),
(1556809,54,13,9,1,'A tak všickni Izraelští sečteni byli, a aj, zapsáni jsou v knize králů Izraelských a Judských, a přeneseni jsou do Babylona pro přestoupení své.'),
(1556810,54,13,9,2,'Ti pak, kteříž bydlili prvé v vládařství svém v městech svých, totiž Izraelští, kněží, Levítové a Netinejští,'),
(1556811,54,13,9,3,'Bydlili v Jeruzalémě, z synů Judových, z synů Beniaminových, ano i z synů Efraimových a Manassesových:'),
(1556812,54,13,9,4,'Uttai syn Amiuda, syna Amri, syna Imri, syna Bani, z synů Fáresových, syna Judova.'),
(1556813,54,13,9,5,'A z čeledi Silonovy: Azaiáš prvorozený a synové jeho.'),
(1556814,54,13,9,6,'A z synů Zerachových: Jehuel, a příbuzných jejich šest set a devadesát.'),
(1556815,54,13,9,7,'Z synů pak Beniaminových: Sallu syn Mesullama, syna Hodavia, syna Hasenuova,'),
(1556816,54,13,9,8,'A Ibneiáš syn Jerochamův, Ela syn Uzi, syna Michri, a Mesullam syn Sefatiáše, syna Rehuelova, syna Ibniášova.'),
(1556817,54,13,9,9,'Bratří také jejich po pokoleních jejich, devět set padesáte a šest; všickni ti muži knížata čeledí po domích otců svých.'),
(1556818,54,13,9,10,'Z kněží také Jedaiáš, Jehoiarib a Jachin,'),
(1556819,54,13,9,11,'Azariáš syn Helkiáše, syna Mesullamova, syna Sádochova, syna Meraiotova, syna Achitobova, kníže v domě Božím.'),
(1556820,54,13,9,12,'A Adaiáš syn Jerochama, syna Paschurova, syna Malchiášova, a Masai syn Adiele, syna Jachzery, syna Mesullamova, syna Mesillemitova, syna Immerova.'),
(1556821,54,13,9,13,'A bratří jejich knížata po domích otců svých, tisíc sedm set a šedesát mužů udatných v práci přisluhování domu Božího.'),
(1556822,54,13,9,14,'A z Levítů: Semaiáš syn Chasuba, syna Azrikamova, syna Chasabiášova, z synů Merari.'),
(1556823,54,13,9,15,'A Bakbakar Cheres, a Galal, a Mataniáš syn Míchy, syna Zichri, syna Azafova.'),
(1556824,54,13,9,16,'A Abdiáš syn Semaiáše, syna Galalova, syna Jedutunova, a Berechiáš syn Asy, syna Elkánova, kterýž přebýval ve vsech Netofatských.'),
(1556825,54,13,9,17,'Též vrátní: Sallum a Akkub, a Talmon, Achiman, i bratří jejich, z nichž byl Sallum kníže.'),
(1556826,54,13,9,18,'Kterýž až po dnes v bráně královské stával k východu, onino pak vrátnými byli po houfích synů Léví.'),
(1556827,54,13,9,19,'Ale Sallum syn Chóre, syna Abiazafova, syna Chóre, a bratří jeho z domu otce jeho, Chorejští, nad pracemi přisluhování, ostříhali prahů při stánku, tak jako otcové jejich nad vojskem Hospodinovým, kteříž ostříhali vcházení.'),
(1556828,54,13,9,20,'Nad kterýmiž Fínes syn Eleazarův byl někdy knížetem, a Hospodin byl s ním.'),
(1556829,54,13,9,21,'Zachariáš pak syn Meselemiášův vrátným byl u dveří stánku úmluvy.'),
(1556830,54,13,9,22,'Všickni ti voleni za vrátné k veřejím, osob dvě stě a dvanáct. Ti ve vsech svých vyčteni jsou, kteréž nařídil David a Samuel vidoucí, pro jejich věrnost,'),
(1556831,54,13,9,23,'Aby oni i synové jejich byli při branách domu Hospodinova, v domě stánku po strážích.'),
(1556832,54,13,9,24,'Po čtyřech stranách byli vrátní, k východu, k západu, k půlnoci a ku poledni.'),
(1556833,54,13,9,25,'A bratří jejich, po vsech svých bydlící, aby každého sedmého dne časy svými přicházeli s nimi.'),
(1556834,54,13,9,26,'Nebo Levítové byli pod spravou těch čtyř předních vrátných, a byli nad komorami a nad poklady domu Božího,'),
(1556835,54,13,9,27,'A aby vůkol domu Božího ponocovali; nebo jim poručena stráž, a otvírati každý den ráno.'),
(1556836,54,13,9,28,'Z těch také ustaveni nad nádobami přisluhování; nebo v počtu vnášeli je, a v jistém počtu též vynášeli.'),
(1556837,54,13,9,29,'Z nichž opět někteří postaveni byli nad nádobami jinými a nade všemi nádobami posvátnými, a nad bělí, vínem, olejem, kadidlem a vonnými věcmi.'),
(1556838,54,13,9,30,'Někteří také synové kněžští strojili masti z těch vonných věcí.'),
(1556839,54,13,9,31,'Matatiáš pak z Levítů, prvorozený Salluma Choritského, správcí byl těch věcí, kteréž se na pánvi smažily.'),
(1556840,54,13,9,32,'A z synů Kahat, z bratří jejich, byli ustanoveni nad chlebem předložení, aby jej připravovali na každou sobotu.'),
(1556841,54,13,9,33,'Z těch také byli zpěváci, přednější z čeledí otcovských mezi Levíty bydlíce, nejsouce zaměstknaní něčím jiným; nebo ve dne i v noci k své povinnosti státi musili.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556842,54,13,9,34,'Ti jsou přední z čeledí otcovských mezi Levíty v čeledech svých, a ti přední jsouce, bydlili v Jeruzalémě.'),
(1556843,54,13,9,35,'V Gabaon pak bydlili, otec Gabaonitských Jehiel, a jméno manželky jeho Maacha.'),
(1556844,54,13,9,36,'Syn pak jeho prvorozený Abdon, Zur, Cis, Bál, Ner a Nádab.'),
(1556845,54,13,9,37,'Ale Gedor, Achio, Zachariáš a Miklot,'),
(1556846,54,13,9,38,'(Miklot pak zplodil Simam), ti také naproti bratřím svým bydlili v Jeruzalémě s bratřími svými.'),
(1556847,54,13,9,39,'Ner pak zplodil Cisa, a Cis zplodil Saule, Saul pak zplodil Jonatu, Melchisua, Abinadaba a Ezbále.'),
(1556848,54,13,9,40,'Syn pak Jonatův Meribbál, a Meribbál zplodil Mícha.'),
(1556849,54,13,9,41,'Synové pak Míchovi: Piton, Melech, Tarea.'),
(1556850,54,13,9,42,'Achaz pak zplodil Járu, Jára pak zplodil Alemeta, Azmaveta a Zimri. Zimri pak zplodil Mozu.'),
(1556851,54,13,9,43,'Moza pak zplodil Bina. Refaiáš syn jeho, Elasa syn jeho, Azel syn jeho.'),
(1556852,54,13,9,44,'Azel pak měl šest synů, jichžto tato jsou jména: Azrikam, Bochru, Izmael, Seariáš, Abdiáš a Chanan. Ti jsou synové Azelovi.'),
(1556853,54,13,10,1,'Když pak bojovali Filistinští s Izraelem, utíkali muži Izraelští před Filistinskými, a padli, zbiti jsouce na hoře Gelboe.'),
(1556854,54,13,10,2,'I stihali Filistinští Saule a syny jeho, a zabili Filistinští Jonatu, Abinadaba a Melchisua, syny Saulovy.'),
(1556855,54,13,10,3,'A když se zsilila bitva proti Saulovi, trefili na něj střelci s luky, a postřelen jest od střelců.'),
(1556856,54,13,10,4,'Protož řekl Saul oděnci svému: Vytrhni meč svůj a probodni mne jím, aby přijdouce ti neobřezanci, nečinili sobě ze mne posměchu. Ale nechtěl oděnec jeho, nebo se bál velmi. A pochytiv Saul meč, nalehl na něj.'),
(1556857,54,13,10,5,'Tedy vida oděnec jeho, že umřel Saul, nalehl i on na meč a umřel.'),
(1556858,54,13,10,6,'A tak umřel Saul i tři synové jeho, a všecka čeled jeho spolu zemřeli.'),
(1556859,54,13,10,7,'Když pak uzřeli všickni muži Izraelští, kteříž bydlili za tím údolím, že utekli Izraelští, a že zemřeli Saul i synové jeho, opustivše města svá, též utíkali. I přišli Filistinští a bydlili v nich.'),
(1556860,54,13,10,8,'Potom nazejtří přišli Filistinští, aby zloupili pobité. I nalezli Saule a syny jeho, ležící na hoře Gelboe.'),
(1556861,54,13,10,9,'A svlékše ho, vzali hlavu jeho i odění jeho, a poslali po zemi Filistinské vůkol, aby to ohlášeno bylo modlám jejich i lidu.'),
(1556862,54,13,10,10,'Složili také i odění jeho v chrámě boha svého, hlavu pak jeho přibili v chrámě Dágon.'),
(1556863,54,13,10,11,'Tedy uslyšavše všickni v Jábes Galád všecko, což učinili Filistinští Saulovi,'),
(1556864,54,13,10,12,'Zdvihli se všickni muži silní a vzali tělo Saulovo, a těla synů jeho, a přinesli je doJábes. A pochovavše kosti jejich pod jedním dubem v Jábes, postili se sedm dní.'),
(1556865,54,13,10,13,'A tak umřel Saul pro přestoupení své, jímž byl přestoupil proti Hospodinu, totiž proti slovu Hospodinovu, jehož neostříhal, a že se také radil s duchem věštím, doptávaje se ho,'),
(1556866,54,13,10,14,'A nedoptával se Hospodina. Protož zabil jej, a přenesl království na Davida syna Izai.'),
(1556867,54,13,11,1,'Nebo shromáždivše se všickni Izraelští k Davidovi do Hebronu, řekli: Aj, my kost tvá a tělo tvé jsme.'),
(1556868,54,13,11,2,'Ano předešlých časů, když byl Saul králem, ty jsi vyvodil i přivodil Izraele, a nadto řekl Hospodin Bůh tvůj tobě: Ty pásti budeš lid můj Izraelský, a ty budeš vývoda nad lidem mým Izraelským.'),
(1556869,54,13,11,3,'Přišli také všickni starší Izraelští k králi do Hebronu, a učinil s nimi David smlouvu v Hebronu před Hospodinem. I pomazali Davida za krále nad Izraelem, podlé slova Hospodinova skrze Samuele.'),
(1556870,54,13,11,4,'Táhl pak David a všecken lid Izraelský k Jeruzalému, (jenž bylo Jebus, nebo tam byli Jebuzejští obyvatelé té země).'),
(1556871,54,13,11,5,'I mluvili obyvatelé Jebus Davidovi: Nevejdeš sem. Ale David vzal hrad Sion, to jest město Davidovo.'),
(1556872,54,13,11,6,'Nebo byl řekl David: Kdož by koli nejprvé porazil Jebuzea, bude předním a knížetem. Protož vstoupil nejprvé Joáb syn Sarvie, a učiněn předním.'),
(1556873,54,13,11,7,'Potom bydlil David na tom hradě, pročež nazvali jej městem Davidovým.'),
(1556874,54,13,11,8,'I vystavěl město vůkol a vůkol, od Mello až do okolku, Joáb pak opravil ostatek města.'),
(1556875,54,13,11,9,'A tak David čím dále tím více prospíval a rostl; nebo Hospodin zástupů byl s ním.'),
(1556876,54,13,11,10,'Tito pak jsou přední z udatných, kteréž měl David, ježto se zmužile přičinili s ním o království jeho se vším Izraelem, aby ho za krále vyzdvihli podlé slova Hospodinova nad Izraelem.'),
(1556877,54,13,11,11,'Tento jest počet silných, kteréž měl David: Jasobam syn Chachmonův, přední z vůdců. Ten pozdvihl kopí svého proti třem stům, a zbil je pojednou.'),
(1556878,54,13,11,12,'Po něm též Eleazar syn Dodi Achochitského. On byl jeden z těch tří udatných.'),
(1556879,54,13,11,13,'Ten byl s Davidem v Pasdammim, když se Filistinští sebrali k boji. A byl tu díl rolí poseté ječmenem, a lid byl utekl před Filistinskými.'),
(1556880,54,13,11,14,'I zastavili se u prostřed toho dílu, a obdrželi jej, porazivše Filistinské. A vysvobodil Hospodin lid vysvobozením velikým.'),
(1556881,54,13,11,15,'Ti také tři ze třidcíti předních sstoupili k skále k Davidovi do jeskyně Adulam, když vojsko Filistinských leželo v údolí Refaim.'),
(1556882,54,13,11,16,'(Nebo David tehdáž bydlil v pevnosti své, a osazený lid Filistinských byl tehdáž u Betléma.)'),
(1556883,54,13,11,17,'Pohnul se pak David žádostí, a řekl: Ó by mi někdo dal píti vody z čisterny Betlémské, kteráž jest u brány.'),
(1556884,54,13,11,18,'A protož probivše se ti tři skrze vojsko Filistinských, navážili vody z čisterny Betlémské, kteráž jest u brány, a nabravše, přinesli k Davidovi. David pak nechtěl jí píti, ale vylil ji v obět Hospodinu,'),
(1556885,54,13,11,19,'A řekl: Nedejž mi toho, Bože můj, abych to učiniti měl. Zdali krev mužů těch píti budu, kteříž se opovážili života svého? Nebo s opovážením života svého přinesli ji. I nechtěl jí píti. To učinili ti tři silní.'),
(1556886,54,13,11,20,'Potom Abizai bratr Joábův byl přední mezi třmi, a ten také pozdvihl kopí svého proti třem stům, i pobil je, a byl z těch tří nejslovoutnější.'),
(1556887,54,13,11,21,'Z těch tří nad druhé dva jsa nejvzácnější, byl knížetem jejich, a však oněm prvním nebyl rovný.'),
(1556888,54,13,11,22,'Banaiáš také syn Joiadův, syn muže udatného, velikých činů, z Kabsael, ten zabil dva reky Moábské. Tentýž sstoupiv, zabil lva v jámě, když byl sníh.'),
(1556889,54,13,11,23,'Ten také zabil muže Egyptského zvýší pěti loket. A ačkoli měl Egyptský ten v ruce kopí, jako vratidlo tkadlcovské, však šel k němu s holí, a vytrh kopí z ruky Egyptského, zabil jej kopím jeho.'),
(1556890,54,13,11,24,'To učinil Banaiáš syn Joiadův, kterýž také slovoutný byl mezi těmi třmi silnými.'),
(1556891,54,13,11,25,'A ač byl mezi třidcíti slavný, však oněm třem se nevrovnal. I ustanovil ho David nad drabanty svými.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556892,54,13,11,26,'Udatní rytíři také i tito: Azael bratr Joábův, Elchanan syn Dodův Betlémský,'),
(1556893,54,13,11,27,'Sammot Charodský, Chelez Pelonský,'),
(1556894,54,13,11,28,'Híra syn Ikeš Tekoitský, Abiezer Anatotský,'),
(1556895,54,13,11,29,'Sibbechai Chusatský, Ilai Achochský,'),
(1556896,54,13,11,30,'Maharai Netofatský, Cheleb syn Baany Netofatský,'),
(1556897,54,13,11,31,'Ittai syn Ribai z Gabaa synů Beniaminových, Banaiáš Faratonský,'),
(1556898,54,13,11,32,'Churai od potoku Gás, Abiel Arbatský,'),
(1556899,54,13,11,33,'Azmavet Bacharomský, Eliachba Salbonský,'),
(1556900,54,13,11,34,'Synové Chasem Gizonského, Jonatan syn Sage Hararského,'),
(1556901,54,13,11,35,'Achiam syn Sacharův Hararský, Elifal syn Urův,'),
(1556902,54,13,11,36,'Hefer Mecheratský, Achiáš Pelonský,'),
(1556903,54,13,11,37,'Chezro Karmelský, Narai syn Ezbai,'),
(1556904,54,13,11,38,'Joel bratr Nátanův, Mibchar syn Geri,'),
(1556905,54,13,11,39,'Zelek Ammonský, Nacharai Berotský, oděnec Joába syna Sarvie,'),
(1556906,54,13,11,40,'Híra Itrejský, Gareb Itrejský,'),
(1556907,54,13,11,41,'Uriáš Hetejský, Zabad syn Achlai,'),
(1556908,54,13,11,42,'Adina syn Sizův Rubenský, kníže nad Rubenskými, a s ním jiných třidceti,'),
(1556909,54,13,11,43,'Chanan syn Maachův, a Jozafat Mitnejský,'),
(1556910,54,13,11,44,'Uziáš Asteratský, Sama a Johiel, synové Chotama Aroerského,'),
(1556911,54,13,11,45,'Jediael, syn Simri, a Jocha bratr jeho Tizejský,'),
(1556912,54,13,11,46,'Eliel Machavimský, a Jeribai a Josaviáš synové Elnámovi, a Itma Moábský,'),
(1556913,54,13,11,47,'Eliel, a Obéd, a Jaasiel z Mezobaia.'),
(1556914,54,13,12,1,'Tito pak jsou, kteříž přišli k Davidovi do Sicelechu, když se ještě kryl před Saulem synem Cis, a ti byli mezi udatnými, pomocníci boje,'),
(1556915,54,13,12,2,'Nosíce lučiště, a bojujíce pravicí i levicí kamením i střelami z lučiště, a byli z bratří Saulových, z pokolení Beniaminova:'),
(1556916,54,13,12,3,'Kníže Achiezer a Joas, synové Semmaa Gabatského, a Jeziel a Felet, synové Azmavetovi, Beracha, a Jéhu Anatotský,'),
(1556917,54,13,12,4,'A Ismaiáš Gabaonitský, silný mezi třidcíti, kterýž byl nad třidcíti, Jeremiáš, Jachaziel, Jochanan a Jozabad Gederatský,'),
(1556918,54,13,12,5,'A Eluzai, Jerimot, Bealiáš, Semariáš, a Sefatiáš Charufský,'),
(1556919,54,13,12,6,'Elkána, Isiáš, Azareel, Joezer a Jasobam, Chorejští,'),
(1556920,54,13,12,7,'A Joela a Zebadiáš synové Jerochamovi z Gedor.'),
(1556921,54,13,12,8,'Též i z pokolení Gádova utekli k Davidovi k pevnosti na poušť, muži udatní, muži způsobní k boji, užívajíce štítu a pavézy, jichžto tváři jako tváři lvové, a podobní srnám na horách v rychlosti:'),
(1556922,54,13,12,9,'Ezer první, Abdiáš druhý, Eliab třetí,'),
(1556923,54,13,12,10,'Mismanna čtvrtý, Jeremiáš pátý,'),
(1556924,54,13,12,11,'Attai šestý, Eliel sedmý,'),
(1556925,54,13,12,12,'Jochanan osmý, Elzabad devátý,'),
(1556926,54,13,12,13,'Jeremiáš desátý, Machbannai jedenáctý.'),
(1556927,54,13,12,14,'Ti byli z synů Gádových, knížata vojska, jeden nad stem menší, a větší nad tisícem.'),
(1556928,54,13,12,15,'Ti jsou, kteříž přepravili se přes Jordán měsíce prvního, ačkoli se byl vylil ze všech břehů svých, a zahnali všecky z údolí na východ i na západ.'),
(1556929,54,13,12,16,'Přišli také někteří z synů Beniaminových a Judových k pevnosti Davidově.'),
(1556930,54,13,12,17,'I vyšel jim David vstříc, a mluvě, řekl jim: Jestliže z příčiny pokoje jdete ke mně, abyste mi pomáhali, i mé srdce také s vámi se sjednotí; pakli k vyzrazení mne nepřátelům mým, (ješto není nepravosti při mně), popatřiž Bůh otců našich a tresci.'),
(1556931,54,13,12,18,'Duch pak posilnil Amazu předního mezi hejtmany, i řekl: Tobě, ó Davide, a těm, jenž s tebou jsou, synu Izai, pokoj; pokoj tobě, pokoj i pomocníkům tvým. Toběť zajisté pomáhá Bůh tvůj. A tak přijal je David, a postavil je mezi knížaty houfů.'),
(1556932,54,13,12,19,'Nadto i z pokolení Manassesova odstoupili k Davidovi, když táhl s Filistinskými k boji proti Saulovi, ale nepomáhali jim. Nebo uradivše se, propustili ho zase knížata Filistinská, řkouce: S nebezpečenstvím hrdel našich odstoupil by ku pánu svému Saulovi.'),
(1556933,54,13,12,20,'Takž když táhl do Sicelechu, odstoupili k němu někteří z pokolení Manassesova:Adnach, Jozabad, Jediael, Michael, Jozabad, Elihu, a Zilletai, hejtmané nad tisíci v pokolení Manassesovu.'),
(1556934,54,13,12,21,'Ti také pomáhali Davidovi s houfy jeho; nebo udatní byli všickni, pročež byli knížaty v jeho vojště.'),
(1556935,54,13,12,22,'Anobrž každého dne přibývalo jich Davidovi ku pomoci, až bylo vojsko veliké, jako vojsko Boží.'),
(1556936,54,13,12,23,'Tento pak jest počet vývod způsobných k boji, kteříž přišli k Davidovi do Hebronu, aby obrátili království Saulovo k němu podlé slova Hospodinova.'),
(1556937,54,13,12,24,'Z synů Judových, nosících pavézy a kopí, šest tisíc a osm set způsobných k boji.'),
(1556938,54,13,12,25,'Z synů Simeonových, udatných mužů k boji, sedm tisíc a sto.'),
(1556939,54,13,12,26,'Z synů Léví čtyři tisíce a šest set.'),
(1556940,54,13,12,27,'Joiada také vývoda synů Aronových, a s ním tři tisíce a sedm set.'),
(1556941,54,13,12,28,'A Sádoch mládenec rek udatný, a z domu otce jeho knížat dvamecítma.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556942,54,13,12,29,'A z synů Beniaminových, bratří Saulových tři tisíce; nebo ještě množství jiných drželi stráž domu Saulova.'),
(1556943,54,13,12,30,'Z synů též Efraimových dvadceti tisíc a osm set. Ti byli rekové udatní, muži slovoutní v čeledech otců svých.'),
(1556944,54,13,12,31,'Z polovice pak pokolení Manassesova osmnáct tisíc, kteříž vyčteni byli ze jména, aby přišli a ustanovili Davida za krále.'),
(1556945,54,13,12,32,'Z synů také Izacharových, znajících a rozumějících časům, tak že věděli, co by měl činiti lid Izraelský, knížat jejich dvě stě, a všickni bratří jejich činili podlé rčení jejich.'),
(1556946,54,13,12,33,'Z synů Zabulon vycházejících na vojnu, vycvičených v bitvě všelijakými nástroji válečnými, padesáte tisíc, a ku potýkání se v šiku bez choulostivosti srdce.'),
(1556947,54,13,12,34,'Z Neftalímova pak pokolení knížat tisíc, a s nimi pavézníků a kopidlníků třidceti a sedm tisíc.'),
(1556948,54,13,12,35,'Z pokolení Dan, způsobných k boji, osm a dvadceti tisíc a šest set.'),
(1556949,54,13,12,36,'A z pokolení Asserova, kteříž způsobní byli k boji, a umělí v šikování se k bitvě, čtyřidceti tisíc.'),
(1556950,54,13,12,37,'A z Zajordání, totiž z Rubenských a Gádských, a z polovice pokolení Manassesova,přišli se všemi nástroji válečnými sto a dvadceti tisíc.'),
(1556951,54,13,12,38,'Všickni ti muži bojovní, umělí v šiku, úmyslem upřímým přišli do Hebronu, aby ustanovili Davida za krále nade vším lidem Izraelským. Nýbrž i všickni ostatní Izraelští srdce jednoho byli, aby za krále ustanovili Davida.'),
(1556952,54,13,12,39,'I byli tu s Davidem tři dni, jedouce a pijíce, nebo jim byli připravili bratří jejich.'),
(1556953,54,13,12,40,'Ano i ti, kteříž jim blízcí byli až k Izachar a Zabulon a Neftalím, přinášeli chleba na oslích a na velbloudích, i na mezcích a na volích, potravy, mouky, fíků a hroznů sušených, vína, oleje, volů, a ovcí v hojnosti. Nebo radost byla v lidu Izraelském.'),
(1556954,54,13,13,1,'David pak poradil se s hejtmany nad tisíci, s setníky a se všemi vývodami.'),
(1556955,54,13,13,2,'A řekl David všemu shromáždění Izraelskému: Jestliže se vám líbí, a jestli to od Hospodina Boha našeho, rozešleme posly k bratřím našim pozůstalým do všech zemí Izraelských, a též kněžím a Levítům do měst a předměstí jejich, a nechť se shromáždí k nám,'),
(1556956,54,13,13,3,'Abychom zase k nám přivezli truhlu Boha našeho; nebo jsme jí nehledali ve dnech Saulových.'),
(1556957,54,13,13,4,'I řeklo všecko množství, aby se tak stalo; nebo líbila se ta věc všemu lidu.'),
(1556958,54,13,13,5,'Protož shromáždil David všecken lid Izraelský od Nílu Egyptského, až kudy se vchází do Emat, aby přivezli truhlu Hospodinovu z Kariatjeharim.'),
(1556959,54,13,13,6,'A tak vstoupil David a všecken lid Izraelský do Bála, v Kariatjeharim, kteréž jest v Judstvu, aby přenesli odtud truhlu Boha Hospodina, sedícího nad cherubíny, jehož se jméno vzývá.'),
(1556960,54,13,13,7,'I vstavili truhlu Boží na nový vůz, vzavše ji z domu Abinadabova, Uza pak a Achio spravovali vůz.'),
(1556961,54,13,13,8,'Ale David a všecken lid Izraelský hrali před Bohem ze vší síly, v zpěvích na harfy, na loutny, na bubny, na cymbály a na trouby.'),
(1556962,54,13,13,9,'A když přišli až k humnu Kídon, vztáhl Uza ruku svou, aby pozdržel truhly; nebo uchýlili se volové.'),
(1556963,54,13,13,10,'Protož rozhněval se Hospodin na Uzu a zabil jej, proto že vztáhl ruku svou k truhle; a umřel tu před Bohem.'),
(1556964,54,13,13,11,'Tedy zkormoutil se David, proto že se Hospodin tak přísně obořil na Uzu. I nazval to místo Perez Uza až do tohoto dne.'),
(1556965,54,13,13,12,'A boje se David Boha v ten den, řekl: Kterakž mám k sobě přivezti truhlu Boží?'),
(1556966,54,13,13,13,'Pročež nepřenesl David truhly k sobě do města Davidova, ale obrátil ji do domu Obededoma Gittejského.'),
(1556967,54,13,13,14,'I pozůstala truhla Boží mezi čeledí Obededomovou, v domě jeho za tři měsíce, a požehnal Hospodin domu Obededomovu a všem věcem jeho.'),
(1556968,54,13,14,1,'Potom poslal Chíram král Tyrský posly k Davidovi, a dříví cedrového a zedníky i tesaře, aby stavěli jemu dům.'),
(1556969,54,13,14,2,'I poznal David, že ho potvrdil Hospodin za krále nad Izraelem, a že zvýšil království jeho pro lid svůj Izraelský.'),
(1556970,54,13,14,3,'Pojal pak David ještě ženy v Jeruzalémě, a zplodil David více synů a dcer.'),
(1556971,54,13,14,4,'A tato jsou jména těch, kteříž se jemu zrodili v Jeruzalémě: Sammua, Sobab, Nátan a Šalomoun,'),
(1556972,54,13,14,5,'Též Ibchar, Elisua, Elfelet,'),
(1556973,54,13,14,6,'Za tím Noga, Nefeg, Jafia,'),
(1556974,54,13,14,7,'Elisama, Beeliada a Elifelet.'),
(1556975,54,13,14,8,'V tom uslyšavše Filistinští, že by pomazán byl David za krále nade vším Izraelem, vytáhli všickni Filistinští hledati Davida. O čemž uslyšav David, vytáhl proti nim.'),
(1556976,54,13,14,9,'Nebo když Filistinští přišli, a rozprostřeli se v údolí Refaim,'),
(1556977,54,13,14,10,'Radil se David s Bohem, řka: Potáhnu-li proti Filistinským, a dáš-li je v ruku mou? Odpověděl jemu Hospodin: Táhni, a dám je v ruku tvou.'),
(1556978,54,13,14,11,'Tedy vtrhli do Balperazim. I porazil je tam David a řekl: Protrhlť jest Bůh nepřátely mé rukou mou, jako vody protrhují břehy. A protož nazváno jméno místa toho Balperazim.'),
(1556979,54,13,14,12,'Nebo nechali tam bohů svých. I přikázal David, aby je spálili.'),
(1556980,54,13,14,13,'Ale Filistinští sebravše se znovu, rozprostřeli se v tom údolí.'),
(1556981,54,13,14,14,'Pročež David radil se opět s Bohem. I řekl jemu Bůh: Nepřistupuj k nim po zadu; odvrať se od nich, abys na ně trefil naproti moruším.'),
(1556982,54,13,14,15,'A když uslyšíš, že šustí vrchové moruší, tedy vytáhneš k bitvě; nebo vyšel Bůh před tebou, aby porazil vojska Filistinská.'),
(1556983,54,13,14,16,'I učinil David tak, jakž mu byl přikázal Bůh, a porazili vojska Filistinská od Gabaon až do Gázera.'),
(1556984,54,13,14,17,'A tak rozešla se pověst o Davidovi do všech zemí, a způsobil Hospodin to, že se ho báli všickni národové.'),
(1556985,54,13,15,1,'Když pak sobě nastavěl domů v městě Davidově, a připravil místo pro truhlu Boží, a roztáhl jí stánek,'),
(1556986,54,13,15,2,'Tehdy řekl David: Nemáť nositi žádný truhly Boží kromě Levítů, ty zajisté vyvolil Hospodin, aby nosili truhlu Boží, a aby přisluhovali jemu až na věky.'),
(1556987,54,13,15,3,'Protož shromáždil David všecken lid Izraelský do Jeruzaléma, aby přenesl truhlu Hospodinovu na místo její, kteréž jí byl připravil.'),
(1556988,54,13,15,4,'Shromáždil také David syny Aronovy a Levíty.'),
(1556989,54,13,15,5,'Z synů Kahat byli Uriel kníže, a bratří jeho sto a dvadceti.'),
(1556990,54,13,15,6,'Z synů Merari Asaiáš kníže, a bratří jeho dvě stě a dvadceti.'),
(1556991,54,13,15,7,'Z synů Gersomových Joel kníže, a bratří jeho sto a třidceti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1556992,54,13,15,8,'Z synů Elizafanových Semaiáš kníže, a bratří jeho dvě stě.'),
(1556993,54,13,15,9,'Z synů Hebronových Eliel kníže, a bratří jeho osmdesát.'),
(1556994,54,13,15,10,'Z synů Uzielových Aminadab kníže, a bratří jeho sto a dvanáct.'),
(1556995,54,13,15,11,'Tedy povolal David Sádocha a Abiatara, kněží, též i Levítů: Uriele, Asaiáše, Joele, Semaiáše, Eliele a Aminadaba,'),
(1556996,54,13,15,12,'A řekl jim: Vy jste přední z otcovských čeledí mezi Levíty, posvěťte sebe i bratří svých, abyste vnesli truhlu Hospodina Boha Izraelského tu, kdež jsem jí připravil.'),
(1556997,54,13,15,13,'Nebo že spočátku ne vy jste spravovali toho, obořil se Hospodin Bůh náš na nás; nebo jsme ho nehledali náležitě.'),
(1556998,54,13,15,14,'I posvětili se kněží i Levítové, aby přenesli truhlu Hospodina Boha Izraelského.'),
(1556999,54,13,15,15,'A nesli synové Levítů truhlu Boží, jakož byl přikázal Mojžíš, podlé slova Hospodinova, na ramenou svých na sochořích.'),
(1557000,54,13,15,16,'Řekl také David předním z Levítů, aby ustanovili z bratří svých zpěváky s nástroji muzickými, loutnami, harfami a cymbály, aby zvučeli, povyšujíce hlasu s radostí.'),
(1557001,54,13,15,17,'Takž ustanovili Levítové Hémana syna Joelova, a z bratří jeho Azafa syna Berechiášova, a z synů Merari bratří jejich Etana syna Kusaiova.'),
(1557002,54,13,15,18,'A s nimi bratří jejich z druhého pořádku: Zachariáše, Béna, Jaaziele, Semiramota, Jechiele, Unni, Eliaba, Benaiáše, Maaseiáše, Mattitiáše, Elifele, Mikneiáše, Obededoma a Jehiele, vrátné.'),
(1557003,54,13,15,19,'Nebo zpěváci Héman, Azaf a Etan hrali hlasitě na cymbálích měděných,'),
(1557004,54,13,15,20,'A Zachariáš, Aziel, Semiramot, Jechiel, Unni, Eliab, Maaseiáš a Benaiáš na loutnách, při zpěvu vysokém.'),
(1557005,54,13,15,21,'A Mattitiáš, Elifele, Mikneiáš, Obededom, Jehiel a Azaziáš hrali na harfách při zpěvu nízkém.'),
(1557006,54,13,15,22,'Chenaniáš pak, přední z Levítů nesoucích truhlu, spravoval, jak by nésti měli; nebo byl umělý.'),
(1557007,54,13,15,23,'Berechiáš pak a Elkána byli vrátní u truhly.'),
(1557008,54,13,15,24,'Sebaniáš také a Jozafat, Natanael, Amazai, Zachariáš, Benaiáš a Eliezer kněží, troubili na trouby před truhlou Boží; ale Obededom a Jechiáš byli též vrátní u truhly.'),
(1557009,54,13,15,25,'A tak vypravil se David a starší Izraelští a hejtmané, aby přenesli truhlu smlouvy Hospodinovy z domu Obededomova s veselím.'),
(1557010,54,13,15,26,'I stalo se, poněvadž Bůh pomáhal Levítům nesoucím truhlu smlouvy Hospodinovy, že obětovali sedm volů a sedm beranů.'),
(1557011,54,13,15,27,'David pak odín byl pláštěm kmentovým, tolikéž všickni Levítové, kteříž nesli truhlu, i zpěváci, i Chenaniáš, správce nesoucích, mezi zpěváky. Měl také David na sobě efod lněný.'),
(1557012,54,13,15,28,'Takž všecken lid Izraelský provázeli truhlu smlouvy Hospodinovy s plésáním a zvukem trouby, a pozaunů a cymbálů, a hrali na loutny a na harfy.'),
(1557013,54,13,15,29,'Když pak truhla smlouvy Hospodinovy vcházela do města Davidova, Míkol dcera Saulova vyhlédla z okna, a viduci krále Davida poskakujícího a plésajícího, pohrdla jím v srdci svém.'),
(1557014,54,13,16,1,'A když přinesli truhlu Boží a postavili ji u prostřed stánku, kterýž jí byl rozbil David, tedy obětovali oběti zápalné a oběti pokojné před Bohem.'),
(1557015,54,13,16,2,'Zatím dokonav David obětování obětí zápalných a pokojných, dal požehnání lidu ve jménu Hospodinovu.'),
(1557016,54,13,16,3,'Rozdělil také všechněm mužům Izraelským, od muže až do ženy, jednomu každému po pecnu chleba a kusu masa, a í láhvici.'),
(1557017,54,13,16,4,'Potom postavil před truhlou Hospodinovou služebníky z Levítů k připomínání, k vyznávání a k chválení Hospodina Boha Izraelského.'),
(1557018,54,13,16,5,'Azaf byl přední, a druhý po něm Zachariáš, Jehiel, Semiramot, Jechiel, Mattitiáš, Eliab, Benaiáš, Obededom a Jehiel. Ti na nástrojích, na loutnách a harfách, ale Azaf na cymbálích hral.'),
(1557019,54,13,16,6,'Benaiáš pak a Jachaziel kněží s trubami byli ustavičně před truhlou smlouvy Boží.'),
(1557020,54,13,16,7,'Teprv toho dne ponejprvé nařídil David, aby slaven byl Hospodin zpěvem tímto od Azafa a bratří jeho:'),
(1557021,54,13,16,8,'Slavte Hospodina, zvěstujte jméno jeho, a oznamujte mezi národy skutky jeho.'),
(1557022,54,13,16,9,'Zpívejte a žalmy prozpěvujte jemu, rozmlouvejte o všech divných skutcích jeho.'),
(1557023,54,13,16,10,'Chlubte se v svatém jménu jeho, vesel se srdce těch, jenž hledají Hospodina.'),
(1557024,54,13,16,11,'Hledejte Hospodina i síly jeho, hledejte tváři jeho ustavičně.'),
(1557025,54,13,16,12,'Rozpomínejte se na divné skutky jeho, kteréž činil, na zázraky jeho, i na soudy úst jeho.'),
(1557026,54,13,16,13,'Ó símě Izraele, služebníka jeho, ó synové Jákobovi, vyvolení jeho,'),
(1557027,54,13,16,14,'Onť jest Hospodin Bůh náš, na vší zemi soudové jeho.'),
(1557028,54,13,16,15,'Rozpomínejte se ustavičně na smlouvu jeho, na slovo, kteréž přikázal až do tisíce pokolení,'),
(1557029,54,13,16,16,'Kterouž učinil s Abrahamem, a na přísahu jeho Izákovi.'),
(1557030,54,13,16,17,'A vystavil ji Jákobovi za ustanovení, Izraelovi za smlouvu věčnou,'),
(1557031,54,13,16,18,'Pravě: Tobě dám zemi Kananejskou za provazec vládařství vašeho,'),
(1557032,54,13,16,19,'Ačkoli vás byl malý počet, a maličko byli jste v ní pohostinu.'),
(1557033,54,13,16,20,'A přecházeli od národu do národu, a z království k jinému lidu.'),
(1557034,54,13,16,21,'Nedopustil žádnému ublížiti jim, ano i krále pro ně trestal, řka:'),
(1557035,54,13,16,22,'Nedotýkejte se pomazaných mých, a prorokům mým nečiňte nic zlého.'),
(1557036,54,13,16,23,'Zpívejte Hospodinu všecka země, zvěstujte den po dni spasení jeho.'),
(1557037,54,13,16,24,'Vypravujte mezi pohany slávu jeho, a mezi všemi národy divy jeho.'),
(1557038,54,13,16,25,'Nebo veliký jest Hospodin, a chvalitebný náramně, hroznější nade všecky bohy.'),
(1557039,54,13,16,26,'Všickni zajisté bohové národů jsou modly, Hospodin pak nebesa učinil.'),
(1557040,54,13,16,27,'Sláva a jasnost před ním, síla a veselé na místě jeho.'),
(1557041,54,13,16,28,'Vzdejte Hospodinu čeledi národů, vzdejte Hospodinu slávu i moc.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557042,54,13,16,29,'Vzdejte Hospodinu čest jména jeho,přineste dary a přiďte před oblíčej jeho,a sklánějte se před Hospodinem v okrase svatosti.'),
(1557043,54,13,16,30,'Bojte se oblíčeje jeho všickni obyvatelé země, a budeť upevněn okršlek země, aby se nepohnul.'),
(1557044,54,13,16,31,'Veseliti se budou nebesa, a plésati bude země, a řeknou mezi pohany: Hospodin kraluje.'),
(1557045,54,13,16,32,'Zvuk vydá moře, i což v něm jest, veseliti se bude pole i vše, což jest na něm.'),
(1557046,54,13,16,33,'Tedy prozpěvovati bude dříví lesní před Hospodinem, neboť se béře, aby soudil zemi.'),
(1557047,54,13,16,34,'Oslavujte Hospodina, neb dobrý jest, nebo na věky milosrdenství jeho.'),
(1557048,54,13,16,35,'A rcete: Zachovej nás, Bože spasení našeho, a shromažď nás, a vytrhni nás z pohanů, abychom slavili svaté jméno tvé, a chlubili se v chvále tvé.'),
(1557049,54,13,16,36,'Požehnaný Hospodin Bůh Izraelský od věků a až na věky. I řekl všecken lid: Amen, i Halelujah.'),
(1557050,54,13,16,37,'I nechal tu David před truhlou smlouvy Hospodinovy Azafa a bratří jeho, aby přisluhovali před truhlou ustavičně podlé povinnosti dne každého.'),
(1557051,54,13,16,38,'Též i Obededoma s bratřími jejich, osob šedesáte osm, Obededoma, pravím, syna Jedutunova, a Chosi, aby vrátní byli.'),
(1557052,54,13,16,39,'Sádocha také kněze a bratří jeho za kněží nechal před příbytkem Hospodinovým na výsosti, kteráž byla v Gabaon,'),
(1557053,54,13,16,40,'Aby obětovali zápaly Hospodinu na oltáři zápalu ustavičně, ráno i večer, podlé všeho, což psáno jest v zákoně Hospodinově, jejž vydal Izraelovi.'),
(1557054,54,13,16,41,'A s nimi nechal Hémana a Jedutuna a jiných vybraných, kteříž vyčteni byli zejména, aby vzdávali chválu Hospodinu, proto že na věky trvá milosrdenství jeho.'),
(1557055,54,13,16,42,'Těm také, totiž Hémanovi a Jedutunovi, nechal trub a cymbálů, aby zvučeli, i jiných nástrojů muziky Boží, syny pak Jedutunovy postavil u vrat.'),
(1557056,54,13,16,43,'A tak rozešel se všecken lid, jeden každý do domu svého; David též navrátil se, aby požehnání dal domu svému.'),
(1557057,54,13,17,1,'I stalo se, když bydlil David v domě svém, že řekl Nátanovi proroku: Aj, já přebývám v domě cedrovém, truhla pak smlouvy Hospodinovy jest pod kortýnami.'),
(1557058,54,13,17,2,'I řekl Nátan Davidovi: Cožkoli jest v srdci tvém, učiň; nebo Bůh s tebou jest.'),
(1557059,54,13,17,3,'Potom té noci stalo se slovo Boží k Nátanovi, řkoucí:'),
(1557060,54,13,17,4,'Jdi a rci Davidovi služebníku mému: Toto dí Hospodin: Ne ty stavěti mi budeš dům k bydlení,'),
(1557061,54,13,17,5,'Poněvadž jsem nebydlil v žádném domě od toho dne, jakž jsem vyvedl syny Izraelské, až do dne tohoto, ale procházel jsem se z stánku do stánku, také i vně kromě příbytku.'),
(1557062,54,13,17,6,'Nadto kudyž jsem koli chodil se vším Izraelem, zdali jsem slovo řekl kterému z soudců Izraelských, (jimž jsem přikázal, aby pásli lid můj), řka: Proč jste mi neustavěli domu cedrového?'),
(1557063,54,13,17,7,'Protož nyní toto díš služebníku mému Davidovi: Takto praví Hospodin zástupů: Já jsem tě vzal z ovčince, když jsi chodil za stádem, abys byl vývodou lidu mého Izraelského.'),
(1557064,54,13,17,8,'A býval jsem s tebou všudy, kamž jsi koli se obrátil, všecky také nepřátely tvé vyhladil jsem před tváří tvou, a učinilť jsem jméno veliké, jako jméno vznešených na zemi.'),
(1557065,54,13,17,9,'Ano i lidu svému Izraelskému způsobil jsem místo, a vštípil jej tu. I bude bydliti na místě svém, a nepohne se více, aniž na něj dotírati budou lidé nešlechetní, jako prvé,'),
(1557066,54,13,17,10,'Hned od toho času, jakž jsem ustanovil soudce nad lidem svým Izraelským, až jsem ponížil všech nepřátel tvých; nýbrž oznamujiť, že Hospodin sám vystaví tobě dům.'),
(1557067,54,13,17,11,'Nebo když se vyplní dnové tvoji, abys šel za otci svými, vzbudím símě tvé po tobě, kteréž bude z synů tvých, a utvrdím království jeho.'),
(1557068,54,13,17,12,'Onť mi ustaví dům, a já utvrdím trůn jeho až na věky.'),
(1557069,54,13,17,13,'Já budu jemu otcem, a on mi bude synem, a milosrdenství svého neodejmu od něho, jako jsem je odjal od toho, kterýž byl před tebou.'),
(1557070,54,13,17,14,'Ale postavím jej v domě svém a v království svém až na věky, a trůn jeho bude nepohnutelný až na věky.'),
(1557071,54,13,17,15,'Podlé všech slov těchto, a podlé všeho vidění tohoto, tak mluvil Nátan Davidovi.'),
(1557072,54,13,17,16,'Tedy všed král David, posadil se před Hospodinem, a řekl: Kdož jsem já, ó Hospodine Bože, a jaký jest dům můj, že jsi mne tak zvýšil?'),
(1557073,54,13,17,17,'Anobrž i to jsi za málo u sebe položil, ó Bože, pročež jsi zamluvil se o domu služebníka svého i na dlouhé časy, a popatřil jsi na mne, jako na osobu člověka vzácného, Hospodine Bože.'),
(1557074,54,13,17,18,'Což ještě více mluviti má David před tebou o zvelebení služebníka tvého? Ty zajisté znáš služebníka svého.'),
(1557075,54,13,17,19,'Hospodine, pro služebníka svého a podlé srdce svého činíš velikou věc tuto, abys v známost uvedl všecky převeliké věci.'),
(1557076,54,13,17,20,'Hospodine, neníť tobě rovného, anobrž není žádného Boha kromě tebe, podlé toho všeho, jakž jsme slýchali ušima svýma.'),
(1557077,54,13,17,21,'Nebo kde jest který národ na zemi, jako lid tvůj Izraelský, jehož by Bůh šel, aby vykoupil sobě lid a dobyl sobě jména, čině veliké a hrozné věci, vyháněje před tváří lidu svého, kterýž jsi vykoupil z Egypta, pohany?'),
(1557078,54,13,17,22,'Zvolil jsi zajisté lid svůj Izraelský sobě za lid až na věky, a ty, Hospodine, sám jsi jejich Bohem.'),
(1557079,54,13,17,23,'Nyní tedy, Hospodine, slovo to, jímž jsi zamluvil se služebníku svému a domu jeho, budiž jisté až na věky, a učiň tak, jakž jsi mluvil.'),
(1557080,54,13,17,24,'Budiž, pravím, jisté, tak aby velebeno bylo jméno tvé až na věky, a říkáno: Hospodin zástupů, Bůh Izraelský, jest Bůh nad Izraelem, a dům Davida služebníka tvého ať jest nepohnutelný před oblíčejem tvým.'),
(1557081,54,13,17,25,'Nebo ty, Bože můj, zjevil jsi služebníku svému, že mu ustavíš dům, a protož směl služebník tvůj modliti se před tebou.'),
(1557082,54,13,17,26,'A tak, ó Hospodine, ty jsi sám Bůh, a mluvil jsi o služebníku svém dobré věci tyto.'),
(1557083,54,13,17,27,'Nyní tedy ráčil jsi požehnati domu služebníka svého, aby trval na věky před oblíčejem tvým; nebo jsi ty, Hospodine, požehnal, i budeť požehnaný na věky.'),
(1557084,54,13,18,1,'Stalo se potom, že porazil David Filistinské, a zemdlil je, a vzal Gát i vesnice jeho z ruky Filistinských.'),
(1557085,54,13,18,2,'Porazil také i Moábské, a učiněni jsou Moábští služebníci Davidovi, a dávali jemu plat.'),
(1557086,54,13,18,3,'Porazil též David Hadarezera krále Soba v Emat, když byl vytáhl, aby opanoval řeku Eufrates.'),
(1557087,54,13,18,4,'A pobral mu David tisíc vozů, a sedm tisíc jízdných, a dvadceti tisíc mužů pěších, a zpodřezoval David žily všechněm koňům vozníkům. Toliko zanechal z nich ke stu vozům.'),
(1557088,54,13,18,5,'Přitáhli pak byli Syrští od Damašku na pomoc Hadarezerovi králi Soba, ale David porazil z Syrských dvamecítma tisíc mužů.'),
(1557089,54,13,18,6,'Tedy osadil David Syrii Damašskou. I učiněni jsou Syrští služebníci Davidovi, dávajíce plat; nebo zachovával Hospodin Davida, kamž se koli obrátil.'),
(1557090,54,13,18,7,'Pobral také David štíty zlaté, kteréž měli služebníci Hadarezerovi, a přinesl je do Jeruzaléma.'),
(1557091,54,13,18,8,'Z Tibchat též a z Chun, měst Hadarezerových, nabral David mědi velmi mnoho, z kteréž potom slil Šalomoun moře měděné, a sloupy i nádobí měděné.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557092,54,13,18,9,'A když uslyšel Tohu král Emat, že porazil David všecko vojsko Hadarezera krále Soba,'),
(1557093,54,13,18,10,'Poslal Adorama syna svého k králi Davidovi, aby ho pozdravil přátelsky, a spolu se s ním radoval z toho, že bojoval s Hadarezerem, a porazil ho; (nebo válčil Tohu s Hadarezerem). Kterýžto přinesl všelijaké nádoby zlaté a stříbrné i měděné.'),
(1557094,54,13,18,11,'Ty také obětoval král David Hospodinu s stříbrem a zlatem, kteréhož byl nabral ze všech národů, z Idumejských, z Moábských, z synů Ammon, z Filistinských, i z Amalechitských.'),
(1557095,54,13,18,12,'Abizai také syn Sarvie porazil Idumejských v údolí solnatém osmnácte tisíc.'),
(1557096,54,13,18,13,'Protož i nad Idumejskými postavil stráž, a učiněni jsou všickni Idumejští služebníci Davidovi; nebo zachovával Hospodin Davida, kamž se koli obrátil.'),
(1557097,54,13,18,14,'A tak kraloval David nade vším Izraelem, a činil soud a spravedlnost všemu lidu svému.'),
(1557098,54,13,18,15,'Joáb pak syn Sarvie byl nad vojskem, a Jozafat syn Achiludův byl kancléřem.'),
(1557099,54,13,18,16,'Sádoch také syn Achitobův a Abimelech syn Abiatarův byli kněžími, a Susa byl písařem.'),
(1557100,54,13,18,17,'Banaiáš pak syn Joiadův byl nad Cheretejskými a Peletejskými, a synové Davidovi knížaty při králi.'),
(1557101,54,13,19,1,'Stalo se zatím, že umřel Náhas král Ammonitský, a kraloval syn jeho místo něho.'),
(1557102,54,13,19,2,'I řekl David: Učiním milosrdenství s Chanunem synem Náhasovým, nebo učinil otec jeho milosrdenství nade mnou. Tedy poslal David posly, aby ho potěšili pro otce jeho. I přišli služebníci Davidovi do země synů Ammon k Chanunovi, aby ho těšili.'),
(1557103,54,13,19,3,'Tedy řekla knížata Ammonitská Chanunovi: Cožť se zdá, že David činí poctivost otci tvému, že poslal k tobě, kteříž by tě potěšili? Zdali ne proto, aby shlédli a vyšpehovali, i podvrátili zemi tuto, přišli služebníci jeho k tobě?'),
(1557104,54,13,19,4,'Pročež Chanun vzav služebníky Davidovy, oholil je a zustřihoval roucha jejich polovici až do rozkroků, a propustil je.'),
(1557105,54,13,19,5,'Tedy odešli někteří, a oznámili Davidovi o těch mužích. I poslal proti nim, (nebo byli muži ti zlehčeni velice), a rozkázal jim král: Pobuďte v Jerichu, dokudž neobrostou brady vaše; potom se navrátíte.'),
(1557106,54,13,19,6,'Vidouce pak Ammonitští, že se zošklivili Davidovi, poslal Chanun a synové Ammon tisíc hřiven stříbra, aby sobě najali ze mzdy z Mezopotamie a z Syrie Maacha a z Soba vozů a jezdců.'),
(1557107,54,13,19,7,'A najali sobě ze mzdy třidceti a dva tisíce vozů, a krále Maachu i lid jeho. Kteřížto přitáhše, položili se s vojskem naproti Medaba. Ammonitští také shromáždivše se z měst svých, přitáhli k té bitvě.'),
(1557108,54,13,19,8,'Což uslyšav David, poslal Joába se vším vojskem udatných.'),
(1557109,54,13,19,9,'A tak vytáhše Ammonitští, sšikovali se k boji u brány města toho. Králové pak, kteříž byli přitáhli, byli zvláště na poli.'),
(1557110,54,13,19,10,'A protož vida Joáb proti sobě sšikovaný lid z předu i z zadu, vybrav některé ze všech výborných Izraelských, sšikoval je také proti Syrským.'),
(1557111,54,13,19,11,'Ostatek pak lidu dal pod správu Abizaie bratra svého, a sšikovali se proti Ammonitským.'),
(1557112,54,13,19,12,'I řekl Joáb: Jestliže Syrští budou mne silnější, přispěješ mi na pomoc; pakli Ammonitští silnější budou tebe, já pomohu tobě.'),
(1557113,54,13,19,13,'Posiliž se, a zmužile se mějme, bojujíce za lid náš a za města Boha našeho, Hospodin však, což mu se dobře líbí, nechť učiní.'),
(1557114,54,13,19,14,'Takž přistoupil Joáb i lid, kterýž při něm byl, k bitvě proti Syrským. Ale oni utekli před ním.'),
(1557115,54,13,19,15,'V tom Ammonitští vidouce, že utíkají Syrští, utekli také i oni před Abizaiem bratrem jeho, a ušli do města. Joáb též navrátil se do Jeruzaléma.'),
(1557116,54,13,19,16,'A tak vidouce Syrští, že jsou poraženi od Izraelských, poslali posly, a vyvedli Syrské, kteříž bydlejí za řekou, a Sofach kníže vojska Hadarezerova vedl je.'),
(1557117,54,13,19,17,'I oznámeno to Davidovi. Kterýžto shromáždiv všecken lid Izraelský, přepravil se přes Jordán, a přitáhl k nim, a sšikoval vojsko proti nim. A když sšikoval David vojsko proti Syrským k bitvě, bojovali s ním.'),
(1557118,54,13,19,18,'Tedy utekli Syrští před Izraelem. I porazil David z Syrských sedm tisíc vozů, a čtyřidceti tisíc lidu pěšího, až i Sofacha hejtmana vojska toho zabil.'),
(1557119,54,13,19,19,'Pročež když viděli služebníci Hadarezerovi, že jsou poraženi od Izraele, vešli v pokoj s Davidem, a sloužili jemu. A nechtěli více Syrští táhnouti na pomoc Ammonitským.'),
(1557120,54,13,20,1,'I stalo se po roce, když králové vyjíždívají na vojnu, že vedl Joáb lid válečný, a hubil zemi synů Ammon. A když přitáhl, oblehl Rabbu; (ale David zůstal v Jeruzalémě). I dobyl Joáb Rabby, a rozbořil ji.'),
(1557121,54,13,20,2,'Tedy sňal David korunu krále jejich s hlavy jeho, a našel, že vážila hřivnu zlata. A bylo v ní kamení drahé, i vstavena byla na hlavu Davidovu. Vyvezl též kořisti města velmi veliké.'),
(1557122,54,13,20,3,'Lid pak, kterýž v něm byl, vyvedl, a dal je pod pily a brány železné i sekery. A tak učinil David všechněm městům Ammonitským. I navrátil se David se vším lidem do Jeruzaléma.'),
(1557123,54,13,20,4,'Potom pak když trvala válka v Gázer s Filistinskými, tehdy zabil Sibbechai Chusatský Sippaje, kterýž byl zplozený z obrů, i sníženi jsou.'),
(1557124,54,13,20,5,'Byla ještě i jiná válka s Filistinskými, kdežto zabil Elchanan, syn Jairův, Lachmi bratra Goliáše Gittejského, u jehož kopí bylo dřevo jako vratidlo tkadlcovské.'),
(1557125,54,13,20,6,'Opět byla jiná válka v Gát, a byl tam muž veliké postavy, kterýž měl po šesti prstech, všech čtyřmecítma, a byl i on zplozený z téhož obra.'),
(1557126,54,13,20,7,'Ten když haněl Izraele, zabil ho Jonata syn Semmaa, bratra Davidova.'),
(1557127,54,13,20,8,'Ti byli synové jednoho obra v Gát, kteříž padli od ruky Davidovy a od ruky služebníků jeho.'),
(1557128,54,13,21,1,'Satan pak povstal proti Izraelovi, a ponukl Davida, aby sečtl lid Izraelský.'),
(1557129,54,13,21,2,'Protož řekl David Joábovi a knížatům lidu: Jděte, sečtěte lid Izraelský od Bersabé až do Dan, a oznamte mi, abych věděl počet jich.'),
(1557130,54,13,21,3,'Ale Joáb řekl: Přidejž Hospodin lidu svého, což ho koli, stokrát více. I zdaliž, pane můj králi, nejsou všickni oni pána mého služebníci? Proč toho vyhledává pán můj? Proč má býti uvedena pokléska na Izraele?'),
(1557131,54,13,21,4,'Ale řeč královská přemohla Joába. A tak vyšed Joáb, prošel všecken lid Izraelský; potom navrátil se do Jeruzaléma.'),
(1557132,54,13,21,5,'I dal Joáb počet lidu sečteného Davidovi. A bylo všeho lidu Izraelského jedenáctekrát sto tisíc mužů bojovných, lidu pak Judského čtyřikrát sto tisíc, a sedmdesáte tisíc mužů bojovných.'),
(1557133,54,13,21,6,'Pokolení pak Léví a Beniaminova nepočítal mezi ně; nebo v ošklivosti měl Joáb rozkázaní královo.'),
(1557134,54,13,21,7,'Ovšem nelíbila se Bohu ta věc, protož ranil Izraele.'),
(1557135,54,13,21,8,'I řekl David Bohu: Zhřešil jsem těžce, že jsem to učinil, ale nyní odejmi, prosím, nepravost služebníka svého, nebo jsem velmi bláznivě učinil.'),
(1557136,54,13,21,9,'V tom mluvil Hospodin k Gádovi, proroku Davidovu, řka:'),
(1557137,54,13,21,10,'Jdi a rci Davidovi: Toto praví Hospodin: Trojíť věci podávám, vyvol sobě jednu z nich, kteroužť bych učinil.'),
(1557138,54,13,21,11,'Tedy přišel Gád k Davidovi a řekl jemu: Toto praví Hospodin: Vol sobě,'),
(1557139,54,13,21,12,'Buďto hlad za tři léta, buď abys za tři měsíce kažen byl od protivníků svých, když by meč nepřátel tvých dotekl se tebe, aneb aby za tři dni meč Hospodinův a mor byl v zemi, a anděl Hospodinův aby hubil po všech končinách Izraelských. Již tedy viz, co mám odpovědíti tomu, kterýž mne poslal.'),
(1557140,54,13,21,13,'I řekl David Gádovi: Úzko mi náramně; nechť prosím, upadnu v ruce Hospodinovy, neboť jsou mnohá slitování jeho, jediné ať v ruce lidské neupadám.'),
(1557141,54,13,21,14,'A tak uvedl Hospodin mor na lid Izraelský, a padlo jich z Izraele sedmdesáte tisíc mužů.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557142,54,13,21,15,'Poslal také Bůh anděla i na Jeruzalém, aby hubil jej. A když hubil, popatřil Hospodin, a zželelo mu se toho zlého. I řekl andělu, kterýž hubil: Dostiť jest, zdrž ruku svou. Anděl pak stál podlé humna Ornana Jebuzejského.'),
(1557143,54,13,21,16,'Mezi tím pozdvih David očí svých, uzřel anděla Hospodinova, stojícího mezi zemí a nebem, a meč dobytý v ruce jeho, vztažený proti Jeruzalému. I padl David, ano i starší, odíni jsouce žíněmi, na tváři své.'),
(1557144,54,13,21,17,'A řekl David Bohu: Zdaliž jsem já nerozkázal čísti lidu? A jáť jsem sám ten, kterýž jsem zhřešil, a převelmi jsem zle učinil, tyto pak ovce co učinily? Hospodine, Bože můj, nechť jest, prosím, ruka tvá proti mně, a proti domu otce mého, ale proti lidu tvému nechť není rána.'),
(1557145,54,13,21,18,'Zatím anděl Hospodinův mluvil k Gádovi, aby řekl Davidovi, aby vstoupě, vzdělal oltář Hospodinu na humně Ornana Jebuzejského.'),
(1557146,54,13,21,19,'I vstoupil David podlé řeči Gádovy, kterouž byl mluvil ve jménu Hospodinovu.'),
(1557147,54,13,21,20,'A obrátiv se Ornan, uzřel toho anděla, a čtyři synové jeho s ním skryli se. Ornan pak mlátil pšenici.'),
(1557148,54,13,21,21,'V tom přišel David k Ornanovi. A pohleděv Ornan, uzřel Davida, a vyšed z humna toho, klaněl se Davidovi až k zemi.'),
(1557149,54,13,21,22,'Tedy řekl David Ornanovi: Dej mi to místo humna, ať vzdělám na něm oltář Hospodinu; za slušné peníze dej mi je, i přestane rána v lidu.'),
(1557150,54,13,21,23,'I řekl Ornan Davidovi: Nechť sobě vezme, a učiní pán můj král, což se mu za dobré vidí. Hle, přidám i voly tyto k oběti zápalné, a smyky na drva, i pšenici k oběti suché, to všecko dávám.'),
(1557151,54,13,21,24,'Král pak David řekl Ornanovi: Nikoli, ale raději koupím je od tebe za slušné peníze; neboť nevezmu, což tvého jest, Hospodinu, aniž budu obětovati oběti zápalné darem dané.'),
(1557152,54,13,21,25,'I dal David Ornanovi za to místo zlata ztíží šesti set lotů.'),
(1557153,54,13,21,26,'A vzdělal tu David oltář Hospodinu, a obětoval zápaly a oběti pokojné, a vzýval Hospodina. Kterýžto vyslyšel ho, spustiv oheň s nebe na oltář zápalu.'),
(1557154,54,13,21,27,'I řekl Hospodin andělu, aby obrátil meč svůj do pošvy jeho.'),
(1557155,54,13,21,28,'Toho času když uzřel David, že jej vyslyšel Hospodin na humně Ornana Jebuzejského, obětovával tu oběti.'),
(1557156,54,13,21,29,'Nebo stánek Hospodinův, kterýž byl učinil Mojžíš na poušti, a oltář k zápalu toho času byl na výsosti v Gabaon.'),
(1557157,54,13,21,30,'David pak nemohl tam choditi k němu, aby hledal Boha, proto že se zhrozil meče anděla Hospodinova.'),
(1557158,54,13,22,1,'I řekl David: Totoť jest místo domu Hospodina Boha, a toto jest místo oltáři k zápalu Izraelovi.'),
(1557159,54,13,22,2,'Protož přikázal David, aby shromáždili cizozemce přebývající v zemi Izraelské, a ustanovil z nich kameníky, aby tesali kamení k stavení domu Božího.'),
(1557160,54,13,22,3,'Železa také mnoho na hřeby, a na dvéře k branám i k spojováním, připravil David, i mědi mnoho bez váhy.'),
(1557161,54,13,22,4,'Též i dříví cedrového bez počtu; nebo přiváželi Sidonští a Tyrští dříví cedrového množství Davidovi.'),
(1557162,54,13,22,5,'Nebo řekl byl David: Šalomoun syn můj mládenček jest malý, dům pak vystaven býti má Hospodinu veliký, znamenitý a slovoutný po všech zemích, a protož připravím mu nyní potřeb. A tak připravil David množství toho před smrtí svou.'),
(1557163,54,13,22,6,'Potom povolav Šalomouna syna svého, přikázal mu, aby vystavěl dům Hospodinu Bohu Izraelskému.'),
(1557164,54,13,22,7,'A řekl David Šalomounovi: Synu můj, uložil jsem byl v srdci svém vystavěti dům jménu Hospodina Boha svého.'),
(1557165,54,13,22,8,'Ale stala se ke mně řeč Hospodinova, řkoucí: Mnohou jsi krev vylil, a boje veliké jsi vedl; nebudeš stavěti domu jménu mému, proto že jsi mnoho krve vylil na zem přede mnou.'),
(1557166,54,13,22,9,'Aj, syn narodí se tobě, tenť bude muž pokojný. Odpočinutí zajisté dám jemu vůkol přede všemi nepřátely jeho, pročež Šalomoun slouti bude; nebo pokoj a odpočinutí dám Izraelovi za dnů jeho.'),
(1557167,54,13,22,10,'Onť ustaví dům jménu mému, a on bude mi za syna, a já jemu za otce, a upevním trůn království jeho nad Izraelem až na věky.'),
(1557168,54,13,22,11,'Protož, synu můj, Hospodin bude s tebou, a šťastněť se povede, a vystavíš dům Hospodina Boha svého, jakož mluvil o tobě.'),
(1557169,54,13,22,12,'A však dejž tobě Hospodin rozum a moudrost, a ustanoviž tě nad Izraelem, abys ostříhal zákona Hospodina Boha svého.'),
(1557170,54,13,22,13,'A tehdyť se šťastně povede, když ostříhati a činiti budeš ustanovení a soudy, kteréž přikázal Hospodin skrze Mojžíše lidu Izraelskému. Posilniž se a zmocni, neboj se, ani lekej.'),
(1557171,54,13,22,14,'A aj, já v nevolech svých připravil jsem k domu Hospodinovu sto tisíců centnéřů zlata, a stříbra tisíc tisíců centnéřů, mědi pak a železa bez váhy; nebo toho mnoho jest. Dříví také i kamení připravil jsem, a k tomu ostatek přidáš.'),
(1557172,54,13,22,15,'Přes to máš u sebe hojně dělníků, kameníků a zedníků, i tesařů i jiných zběhlých ve všelijakém díle.'),
(1557173,54,13,22,16,'Zlata, stříbra, mědi a železa není počtu; snažiž se a dělej, a Hospodin budiž s tebou.'),
(1557174,54,13,22,17,'Přikázal také David všechněm knížatům Izraelským, aby pomáhali Šalomounovi synu jeho, řka:'),
(1557175,54,13,22,18,'Zdaliž Hospodin Bůh váš není s vámi, kterýž vám způsobil vůkol a vůkol odpočinutí? Nebo dal v ruku mou obyvatele země této, a podmaněna jest země Hospodinu a lidu jeho.'),
(1557176,54,13,22,19,'Nyní tedy vydejte se srdcem svým a duší svou k hledání Hospodina Boha svého, a přičiníce se, vystavějte svatyni Hospodinu Bohu, abyste tam vnesli truhlu smlouvy Hospodinovy, a nádobí Bohu posvěcená do domu vystaveného jménu Hospodinovu.'),
(1557177,54,13,23,1,'Sstarav se pak David, a jsa pln dnů, ustanovil králem Šalomouna syna svého nad Izraelem,'),
(1557178,54,13,23,2,'A shromáždil všecka knížata Izraelská, i kněží a Levíty.'),
(1557179,54,13,23,3,'I sečteni jsou Levítové od třidcítiletých a výše, a byl počet jich, vedlé jmen a osob jejich, třidceti a osm tisíců.'),
(1557180,54,13,23,4,'Z kterýchž postaveno bylo nad dílem domu Hospodinova čtyřmecítma tisíců, vladařů pak a soudců šest tisíců,'),
(1557181,54,13,23,5,'A vrátných čtyři tisíce, a čtyři tisíce chválících Hospodina na nástrojích, kterýchž nadělal k chválení Boha.'),
(1557182,54,13,23,6,'I nařídil David pořádku mezi syny Léví, totiž mezi syny Gerson, Kahat a Merari.'),
(1557183,54,13,23,7,'Z Gersona byli Ladan a Semei.'),
(1557184,54,13,23,8,'Synové Ladan: Kníže Jehiel, Zetam a Joel, ti tři.'),
(1557185,54,13,23,9,'Synové Semei: Selomit, Oziel a Háran, ti tři. Ta jsou knížata otcovských čeledí Ladanských.'),
(1557186,54,13,23,10,'Synové pak Semei: Jachat, Zina, Jehus a Beria. Ti čtyři jsou synové Semei.'),
(1557187,54,13,23,11,'Byl pak Jachat kníže, a Ziza druhý, ale Jehus a Beria ne mnoho měli synů, a protož v čeledi otcovské za jedny byli počítáni.'),
(1557188,54,13,23,12,'Synové Kahat: Amram, Izar, Hebron a Uziel, ti čtyři.'),
(1557189,54,13,23,13,'Synové Amramovi: Aron a Mojžíš. Byl pak oddělen Aron, aby sloužil v svatyni svatých, on i synové jeho na věky, a aby kadili před Hospodinem, a sloužili jemu, i dobrořečili ve jménu jeho až na věky.'),
(1557190,54,13,23,14,'Ale synové Mojžíše, muže Božího, počteni jsou v pokolení Léví.'),
(1557191,54,13,23,15,'Synové Mojžíšovi: Gersom a Eliezer.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557192,54,13,23,16,'Synové Gersomovi: Sebuel kníže.'),
(1557193,54,13,23,17,'A synové Eliezerovi: Rechabiáš kníže. Neměl pak Eliezer více synů, ale synové Rechabiášovi rozmnožili se velmi.'),
(1557194,54,13,23,18,'Synové Izarovi: Selomit kníže.'),
(1557195,54,13,23,19,'Synové Hebronovi: Jeriáš kníže, Amariáš druhé, Jachaziel třetí, a Jekmaam čtvrté.'),
(1557196,54,13,23,20,'Synové Uzielovi: Mícha kníže, a Jezia druhý.'),
(1557197,54,13,23,21,'Synové Merari: Moholi a Musi. Synové Moholi: Eleazar a Cis.'),
(1557198,54,13,23,22,'Umřel pak Eleazar, a neměl synů, než toliko dcery, kteréž pojali synové Cis, bratří jejich.'),
(1557199,54,13,23,23,'Synové Musi: Moholi a Eder a Jerimot, ti tři.'),
(1557200,54,13,23,24,'Ti jsou synové Léví po čeledech svých, knížata čeledí, kteříž vyčteni byli vedlé počtu jmen a osob, konající dílo v přisluhování domu Hospodinova od dvadcítiletých a výše.'),
(1557201,54,13,23,25,'Nebo řekl David: Odpočinutí dal Hospodin Bůh Izraelský lidu svému, a bydliti bude v Jeruzalémě až na věky.'),
(1557202,54,13,23,26,'Ano i Levítové nebudou více nositi stánku, ani kterých nádob jeho k přisluhování jeho.'),
(1557203,54,13,23,27,'A tak podlé nařízení Davidova nejposlednějšího byvše sečteni synové Léví, počna od dvadcítiletých a výše,'),
(1557204,54,13,23,28,'Postaveni byli, aby byli ku pomoci synů Aronových, v přisluhování domu Hospodinova v síňcích, v pokojích a při očišťování všeliké věci svaté, i při práci služebnosti domu Božího,'),
(1557205,54,13,23,29,'Též při chlebích posvátných, a při běli k obětem suchým, při koláčích přesných, a při pánvicích a rendlících, i při všeliké míře a měření,'),
(1557206,54,13,23,30,'A aby stáli každého jitra k slavení a chválení Hospodina, tolikéž i u večer,'),
(1557207,54,13,23,31,'A při všeliké oběti zápalů Hospodinových ve dny sobotní, a na novměsíce a v svátky výroční v jistém počtu, vedlé řádu jejich ustavičně před Hospodinem,'),
(1557208,54,13,23,32,'A tak aby drželi stráž stánku úmluvy, a stráž svatyně, i stráž synů Aronových, bratří svých v službě domu Hospodinova.'),
(1557209,54,13,24,1,'Synů pak Aronových tato jsou zpořádaní: Synové Aronovi: Nádab, Abiu, Eleazar a Itamar.'),
(1557210,54,13,24,2,'Ale že umřel Nádab a Abiu před otcem svým, a neměli synů, protož konali úřad kněžský Eleazar a Itamar.'),
(1557211,54,13,24,3,'Kteréž zpořádal David, totiž Sádocha z synů Eleazarových, a Achimelecha z synů Itamarových, vedlé počtu a řádu jejich v přisluhováních jejich.'),
(1557212,54,13,24,4,'Nalezeno pak synů Eleazarových více předních mužů, než synů Itamarových, a rozdělili je. Z synů Eleazarových bylo předních po domích otcovských šestnáct, a z synů Itamarových po čeledech otcovských osm.'),
(1557213,54,13,24,5,'I rozděleni jsou losem jedni od druhých, ačkoli byli knížata nad věcmi svatými, a knížata Boží z synů Eleazarových a z synů Itamarových.'),
(1557214,54,13,24,6,'I popsal je Semaiáš syn Natanaelův, písař z pokolení Léví před králem a knížaty, a Sádochem knězem a Achimelechem synem Abiatarovým i knížaty čeledí otcovských mezi kněžími a Levíty, tak že dům otcovský jeden zaznamenán Eleazarovi, tolikéž druhý zaznamenán Itamarovi.'),
(1557215,54,13,24,7,'Padl pak los první na Jehoiariba, na Jedaiáše druhý,'),
(1557216,54,13,24,8,'Na Charima třetí, na Seorima čtvrtý,'),
(1557217,54,13,24,9,'Na Malkiáše pátý, na Miamin šestý,'),
(1557218,54,13,24,10,'Na Hakkoza sedmý, na Abiáše osmý,'),
(1557219,54,13,24,11,'Na Jesua devátý, na Sechaniáše desátý,'),
(1557220,54,13,24,12,'Na Eliasiba jedenáctý, na Jakima dvanáctý,'),
(1557221,54,13,24,13,'Na Chuppa třináctý, na Jesebaba čtrnáctý,'),
(1557222,54,13,24,14,'Na Bilgu patnáctý, na Immera šestnáctý,'),
(1557223,54,13,24,15,'Na Chezira sedmnáctý, na Happizeza osmnáctý,'),
(1557224,54,13,24,16,'Na Petachiáše devatenáctý, na Ezechiele dvadcátý,'),
(1557225,54,13,24,17,'Na Jachina jedenmecítmý, na Gamule dvamecítmý,'),
(1557226,54,13,24,18,'Na Delaiáše třímecítmý, na Maaseiáše čtyřmecítmý.'),
(1557227,54,13,24,19,'Ti jsou, jenž zřízeni byli v přisluhováních svých, aby vcházeli do domu Hospodinova podlé řádu svého, pod spravou Arona otce jejich, jakož mu byl přikázal Hospodin Bůh Izraelský.'),
(1557228,54,13,24,20,'Z synů Léví ostatních, z synů Amramových Subael, z synů Subael Jechdeiáš.'),
(1557229,54,13,24,21,'Z Rechabiáše, z synů Rechabiášových kníže Iziáš.'),
(1557230,54,13,24,22,'Z Izara Selomot, z synů Selomotových Jachat.'),
(1557231,54,13,24,23,'Synové pak Jeriášovi: Amariáš druhý, Jachaziel třetí, Jekamam čtvrtý.'),
(1557232,54,13,24,24,'Syn Uzielův Mícha, z synů Míchy Samir.'),
(1557233,54,13,24,25,'Bratr Míchův Iziáš, a syn Iziášův Zachariáš.'),
(1557234,54,13,24,26,'Synové Merari: Moholi a Musi, synové Jaaziášovi: Beno.'),
(1557235,54,13,24,27,'Synové Merari z Jaaziáše: Beno, Soham, Zakur a Ibri.'),
(1557236,54,13,24,28,'Z Moholi Eleazar, kterýž neměl synů.'),
(1557237,54,13,24,29,'Z Cisa synové Cisovi: Jerachmeel.'),
(1557238,54,13,24,30,'Synové pak Musi: Moholi, Eder a Jerimot. Ti jsou synové Levítů po domích otců svých.'),
(1557239,54,13,24,31,'I ti také metali losy naproti bratřím svým, synům Aronovým, před Davidem králem, Sádochem a Achimelechem, i knížaty otcovských čeledí z kněží a Levítů, z čeledí otcovských, každý přednější naproti bratru svému mladšímu.'),
(1557240,54,13,25,1,'I oddělil David a knížata vojska k službě syny Azafovy a Hémanovy a Jedutunovy, kteříž by prorokovali při harfách, při loutnách a při cimbálích. Byl pak počet jejich, totiž mužů těch, jenž práci vedli v přisluhování svém,'),
(1557241,54,13,25,2,'Z synů Azafových: Zakur, Jozef, Netaniáš a Asarela, synové Azafovi, pod spravou Azafavou byli, kterýž prorokoval k rozkazu královu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557242,54,13,25,3,'Z Jedutuna synů Jedutunových bylo šest: Godoliáš, Zeri, Izaiáš, Chasabiáš, Mattitiáš a Simei, pod spravou otce jejich Jedutuna, kterýž prorokoval při harfě k slavení a chválení Hospodina.'),
(1557243,54,13,25,4,'Z Hémana synové Hémanovi: Bukkiáš, Mataniáš, Uziel, Sebuel, Jerimot, Chananiáš, Chanani, Eliata, Giddalti, Romantiezer, Jazbekasa, Malloti, Hotir a Machaziot.'),
(1557244,54,13,25,5,'Všickni ti synové Hémanovi, proroka králova v slovích Božských, k vyvyšování moci. A dal Bůh Hémanovi synů čtrnácte a dcery tři.'),
(1557245,54,13,25,6,'Všickni ti byli pod spravou otce svého, při zpívání v domě Hospodinově na cymbálích, loutnách a harfách, k službě v domě Božím vedlé poručení králova Azafovi, Jedutunovi a Hémanovi.'),
(1557246,54,13,25,7,'Byl pak počet jich s bratřími jejich, těmi, kteříž byli vycvičení v zpěvích Hospodinových, všech mistrů dvě stě osmdesát osm.'),
(1557247,54,13,25,8,'Tedy metali losy, houf držících stráž naproti druhému, jakž malý, tak veliký, mistr i učedlník.'),
(1557248,54,13,25,9,'I padl první los v čeledi Azaf na Jozefa, na Godoliáše s bratřími a syny jeho druhý, jichž bylo dvanáct.'),
(1557249,54,13,25,10,'Třetí na Zakura, synům jeho a bratřím jeho dvanácti.'),
(1557250,54,13,25,11,'Čtvrtý na Izara, synům jeho a bratřím jeho dvanácti.'),
(1557251,54,13,25,12,'Pátý na Netaniáše, synům jeho a bratřím jeho dvanácti.'),
(1557252,54,13,25,13,'Šestý na Bukkiáše, synům jeho a bratřím jeho dvanácti.'),
(1557253,54,13,25,14,'Sedmý na Jesarele, synům jeho a bratřím jeho dvanácti.'),
(1557254,54,13,25,15,'Osmý na Izaiáše, synům jeho a bratřím jeho dvanácti.'),
(1557255,54,13,25,16,'Devátý na Mataniáše, synům a bratřím jeho dvanácti.'),
(1557256,54,13,25,17,'Desátý na Simei, synům a bratřím jeho dvanácti.'),
(1557257,54,13,25,18,'Jedenáctý na Azarele, synům a bratřím jeho dvanácti.'),
(1557258,54,13,25,19,'Dvanáctý na Chasabiáše, synům a bratřím jeho dvanácti.'),
(1557259,54,13,25,20,'Třináctý na Subaele, synům a bratřím jeho dvanácti.'),
(1557260,54,13,25,21,'Čtrnáctý na Mattitiáše, synům a bratřím jeho dvanácti.'),
(1557261,54,13,25,22,'Patnáctý na Jerimota, synům a bratřím jeho dvanácti.'),
(1557262,54,13,25,23,'Šestnáctý na Chananiáše, synům a bratřím jeho dvanácti.'),
(1557263,54,13,25,24,'Sedmnáctý na Jazbekasa, synům a bratřím jeho dvanácti.'),
(1557264,54,13,25,25,'Osmnáctý na Chanani, synům a bratřím jeho dvanácti.'),
(1557265,54,13,25,26,'Devatenáctý na Malloti, synům a bratřím jeho dvanácti.'),
(1557266,54,13,25,27,'Dvadcátý na Eliatu, synům a bratřím jeho dvanácti.'),
(1557267,54,13,25,28,'Jedenmecítmý na Hotira, synům a bratřím jeho dvanácti.'),
(1557268,54,13,25,29,'Dvamecítmý na Giddalta, synům a bratřím jeho dvanácti.'),
(1557269,54,13,25,30,'Třímecítmý na Machaziota, synům a bratřím jeho dvanácti.'),
(1557270,54,13,25,31,'Čtyřmecítmý na Romantiezera, synům a bratřím jeho dvanácti.'),
(1557271,54,13,26,1,'Zpořádání pak vrátných takové bylo: Z Chorejských Meselemiáš syn Chóre, z synů Azafových.'),
(1557272,54,13,26,2,'A z Meselemiášových synů: Zachariáš prvorozený, Jediael druhý, Zebadiáš třetí, Jatniel čtvrtý,'),
(1557273,54,13,26,3,'Elam pátý, Jochanan šestý, Elioenai sedmý.'),
(1557274,54,13,26,4,'A z Obededomových synů: Semaiáš prvorozený, Jozabad druhý, Joach třetí, Sachar čtvrtý a Natanael pátý,'),
(1557275,54,13,26,5,'Amiel šestý, Izachar sedmý, Pehulletai osmý; nebo požehnal mu Bůh.'),
(1557276,54,13,26,6,'Semaiášovi pak synu jeho zrodili se synové, kteříž panovali v domě otce svého; nebo muži udatní byli.'),
(1557277,54,13,26,7,'Synové Semaiášovi: Otni a Refael, Obéd a Elzabad, jehož bratří byli muži udatní; též Elihu a Semachiáš.'),
(1557278,54,13,26,8,'Všickni ti z potomků Obededomových, oni sami i synové jejich a bratří jejich, jeden každý muž udatný a způsobný k službě, šedesáte a dva všech z Obededoma.'),
(1557279,54,13,26,9,'Též synů a bratří Meselemiášových, mužů silných, osmnáct.'),
(1557280,54,13,26,10,'Z Chosových pak, kterýž byl z synů Merari, synové byli: Simri kníže. Ačkoli nebyl prvorozený, však postavil ho otec jeho za předního.'),
(1557281,54,13,26,11,'Helkiáš druhý, Tebaliáš třetí, Zachariáš čtvrtý. Všech synů a bratří Chosových třinácte.'),
(1557282,54,13,26,12,'Těm rozděleny jsou povinnosti, aby byli vrátnými po mužích předních, držíce stráž naproti bratřím svým při službě v domě Hospodinově.'),
(1557283,54,13,26,13,'Nebo metali losy, jakož malý, tak veliký, po domích svých otcovských, k jedné každé bráně.'),
(1557284,54,13,26,14,'I padl los k východu Selemiášovi. Zachariášovi také synu jeho, rádci opatrnému, uvrhli losy, i padl los jeho na půlnoci.'),
(1557285,54,13,26,15,'Obededomovi pak na poledne, ale synům jeho na dům pokladů.'),
(1557286,54,13,26,16,'Suppimovi a Chosovi na západ s branou Salléchet, na cestě podlážené vzhůru jdoucí. Stráž byla naproti stráži.'),
(1557287,54,13,26,17,'K východu Levítů šest, k půlnoci na den čtyři, ku poledni na den čtyři, a při domě pokladů dva a dva,'),
(1557288,54,13,26,18,'V straně zevnitřní k západu, po čtyřech k příkopu, po dvou k straně zevnitřní.'),
(1557289,54,13,26,19,'Ta jsou zpořádání vrátných synů Chóre a synů Merari.'),
(1557290,54,13,26,20,'Tito také Levítové: Achiáš byl nad poklady domu Božího, totiž nad poklady věcí posvátných.'),
(1557291,54,13,26,21,'Z synů Ladanových synové Gersunských, z Ladana knížata otcovských čeledí, z Ladana totiž Gersunského Jechiel.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557292,54,13,26,22,'Synové Jechielovi, Zetam a Joel bratr jeho, byli nad poklady domu Hospodinova.'),
(1557293,54,13,26,23,'Z Amramských, z Izarských z Hebronských a z Ozielských.'),
(1557294,54,13,26,24,'Sebuel pak syn Gersoma, syna Mojžíšova, přední nad poklady.'),
(1557295,54,13,26,25,'Ale bratří jeho z Eliezera: Rechabiáš syn jeho, a Izaiáš syn jeho, a Joram syn jeho, a Zichri syn jeho, a Selomit syn jeho.'),
(1557296,54,13,26,26,'Ten Selomit a bratří jeho byli nade všemi poklady věcí posvátných, kterýchž byl posvětil David král a knížata čeledí otcovských, i hejtmané a setníci s vývodami vojska.'),
(1557297,54,13,26,27,'Nebo z bojů a z kořistí obětovávali k opravě domu Hospodinova,'),
(1557298,54,13,26,28,'A čehožkoli byl posvětil Samuel prorok, a Saul syn Cis, a Abner syn Nerův, a Joáb syn Sarvie. Kdokoli posvěcoval čeho, dával do rukou Selomita a bratří jeho.'),
(1557299,54,13,26,29,'Z Izarských Chenaniáš a synové jeho, nad dílem, kteréž vně děláno, byli v Izraeli za úředníky a soudce.'),
(1557300,54,13,26,30,'Z Hebronských Chasabiáš a bratří jeho, mužů silných tisíc a sedm set bylo v přednosti nad Izraelem, za Jordánem k západu, ve všelikém díle Hospodinově a v službě královské.'),
(1557301,54,13,26,31,'Mezi kterýmiž Hebronskými Jeriáš kníže byl nad Hebronskými v pokolení jejich, po čeledech otcovských; nebo léta čtyřidcátého kralování Davidova vyhledáváni byli, a nalezeni jsou mezi nimi muži udatní v Jazar Galádské,'),
(1557302,54,13,26,32,'A bratří jeho, mužů silných, dva tisíce a sedm set, knížat otcovských čeledí. Kteréž ustanovil David král nad Rubenskými a Gádskými, a nad polovicí pokolení Manassesova, ve všech věcech Božských i věcech královských.'),
(1557303,54,13,27,1,'Synové pak Izraelští podlé počtu svého, knížata čeledí otcovských a hejtmané a setníci a úředníci nad těmi, kteříž přisluhovali králi ve všech věcech jedni po druhých, vcházejíce a vycházejíce na každý měsíc, přes všecky měsíce roku: V jednom každém houfě bylo jich čtyřmecítma tisíců.'),
(1557304,54,13,27,2,'Nad houfem prvním první měsíc byl Jasobam, syn Zabdielův, a v houfě jeho bylo čtyřmecítma tisíců.'),
(1557305,54,13,27,3,'Z synů Fáresových bylo to kníže všech knížat nad vojsky, měsíce prvního.'),
(1557306,54,13,27,4,'Zatím nad houfem na měsíc druhý byl Dodai Achochitský i s houfem svým, potom Miklot vývoda, a v houfě jeho čtyřmecítma tisíců.'),
(1557307,54,13,27,5,'Kníže vojska třetího na třetí měsíc Banaiáš syn Joiady, nejvyššího kněze, a v houfě jeho čtyřmecítma tisíců.'),
(1557308,54,13,27,6,'Ten Banaiáš byl silný mezi třidcíti a nad třidcíti, a v houfě jeho Amizabad syn jeho.'),
(1557309,54,13,27,7,'Čtvrtého houfu kníže na čtvrtý měsíc Azael, bratr Joábův, a Zebadiáš syn jeho po něm, a v houfě jeho čtyřmecítma tisíců.'),
(1557310,54,13,27,8,'Pátého na pátý měsíc kníže Samhut Izrachitský, a v houfě jeho čtyřmecítma tisíců.'),
(1557311,54,13,27,9,'Šestého na šestý měsíc Híra, syn Ikeše Tekoitského, a v houfě jeho čtyřmecítma tisíců.'),
(1557312,54,13,27,10,'Sedmého na sedmý měsíc Chelez Pelonský z synů Efraimových, a v houfě jeho čtyřmecítma tisíců.'),
(1557313,54,13,27,11,'Osmého na osmý měsíc Sibbechai Chusatský z Zarchejských, a v houfě jeho čtyřmecítma tisíců.'),
(1557314,54,13,27,12,'Devátého na devátý měsíc Abiezer Anatotský z Beniaminských, a v houfě jeho čtyřmecítma tisíců.'),
(1557315,54,13,27,13,'Desátého na měsíc desátý Maharai Netofatský z Zarchejských, a v houfě jeho čtyřmecítma tisíců.'),
(1557316,54,13,27,14,'Jedenáctého na jedenáctý měsíc Banaiáš Faratonský z synů Efraimových, a v houfě jeho čtyřmecítma tisíců.'),
(1557317,54,13,27,15,'Dvanáctého na dvanáctý měsíc Cheldai Netofatský z Otoniele, a v houfě jeho čtyřmecítma tisíců.'),
(1557318,54,13,27,16,'Mimo to byli nad pokoleními Izraelskými, nad Rubenskými vývoda Eliezer syn Zichrův, nad Simeonskými Sefatiáš syn Maachův,'),
(1557319,54,13,27,17,'Nad pokolením Léví Chasabiáš syn Kemuelův, nad Aronovým Sádoch,'),
(1557320,54,13,27,18,'Nad Judovým Elihu z bratří Davidových, nad Izacharovým Amri syn Michaelův,'),
(1557321,54,13,27,19,'Nad Zabulonovým Izmaiáš syn Abdiášův, nad Neftalímovým Jerimot syn Azrielův,'),
(1557322,54,13,27,20,'Nad syny Efraimovými Ozeáš syn Azaziášův, nad polovicí pokolení Manasse Joel syn Pedaiášův,'),
(1557323,54,13,27,21,'Nad druhou pak polovicí Manasse v Gálad Iddo syn Zachariášův, nad Beniaminovým Jaasiel syn Abnerův,'),
(1557324,54,13,27,22,'Nad Danovým Azarel syn Jerochamův. Ta jsou knížata pokolení Izraelských.'),
(1557325,54,13,27,23,'Nesečtl jich pak David všech od dvadcítiletých a níže; nebo byl řekl Hospodin, že rozmnoží Izraele jako hvězdy nebeské.'),
(1557326,54,13,27,24,'A ačkoli Joáb syn Sarvie počal jich počítati, však nedokonal; nebo proto přišel hněv Boží na Izraele, aniž jest vložen počet ten v knihu o králi Davidovi.'),
(1557327,54,13,27,25,'Nad poklady pak královskými byl Azmavet syn Adielův, a nad důchody z polí, z měst a ze vsí i z zámků byl Jonatan syn Uziášův.'),
(1557328,54,13,27,26,'A nad dělníky na poli, při dělání rolí, Ezri syn Chelubův.'),
(1557329,54,13,27,27,'A nad vinicemi Semeiáš Ramatský, a nad úrodami z vinic i nad sklepy vinnými Zabdi Sifmejský.'),
(1557330,54,13,27,28,'A nad olivovím a planým fíkovím, kteréž jest na polích, Baalchanan Gederský, a nad špižírnami olejnými Joas.'),
(1557331,54,13,27,29,'A nad skoty, kteříž se pásli v Sáron, Sitrai Sáronský, a nad skoty v údolích Safat syn Adlai.'),
(1557332,54,13,27,30,'A nad velbloudy Obil Izmaelský, nad oslicemi Jechdeiáš Meronotský,'),
(1557333,54,13,27,31,'Nad bravy pak Jazim Agarejský. Všickni ti úředníci byli nad statkem krále Davida.'),
(1557334,54,13,27,32,'Ale Jonatan strýc Davidův byl rada, muž rozumný a kancléř. On a Jechiel syn Chachmonův býval s syny královskými.'),
(1557335,54,13,27,33,'Achitofel též rada králova, a Chusai Architský přítel králův.'),
(1557336,54,13,27,34,'Po Achitofelovi potom byl Joiada syn Banaiášův, a Abiatar, a kníže vojska králova Joáb.'),
(1557337,54,13,28,1,'Shromáždil pak David všecka knížata Izraelská, knížata jednoho každého pokolení, a knížata houfů sloužících králi, i hejtmany a setníky, i úředníky nade vším statkem a jměním královým i synů jeho s komorníky, i se všemi vzácnými a udatnými lidmi, do Jeruzaléma.'),
(1557338,54,13,28,2,'A povstav David král na nohy své, řekl: Slyšte mne, bratří moji a lide můj. Já jsem uložil v srdci svém vystavěti dům k odpočinutí truhle úmluvy Hospodinovy, a ku podnoži noh Boha našeho, a připravil jsem byl potřeby k stavení.'),
(1557339,54,13,28,3,'Ale Bůh mi řekl: Nebudeš stavěti domu jménu mému, proto že jsi muž válkami zaměstknaný a krev jsi vyléval.'),
(1557340,54,13,28,4,'Vyvolil pak Hospodin Bůh Izraelský mne ze vší čeledi otce mého, abych byl králem nad Izraelem na věky; nebo z Judy vybral vývodu a z domu Judova čeled otce mého, a z synů otce mého mne ráčil za krále ustanoviti nade vším Izraelem.'),
(1557341,54,13,28,5,'Tolikéž ze všech synů mých, (nebo mnoho synů dal mi Hospodin), vybral Šalomouna syna mého, aby seděl na stolici království Hospodinova nad Izraelem,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557342,54,13,28,6,'A řekl mi: Šalomoun syn tvůj, ten mi vzdělá dům můj a síně mé; nebo jsem jej sobě zvolil za syna, a já budu jemu za otce.'),
(1557343,54,13,28,7,'I utvrdím království jeho až na věky, bude-li stálý v ostříhání přikázaní mých a soudů mých, jako i nynějšího času.'),
(1557344,54,13,28,8,'Nyní tedy při přítomnosti všeho Izraele, shromáždění Hospodinova, an slyší Bůh náš, napomínám vás: Zachovávejte a dotazujte se na všecka přikázaní Hospodina Boha svého, abyste vládli zemí dobrou, a v dědictví její uvedli i syny své po sobě až na věky.'),
(1557345,54,13,28,9,'Ty také, Šalomoune, synu můj, znej Boha otce svého, a služ jemu celým srdcem a myslí ochotnou. Nebo všecka srdce zpytuje Hospodin a všeliká mysli tanutí zná. Budeš-li ho hledati, nalezneš jej; pakli ho opustíš, zavrže tě na věky.'),
(1557346,54,13,28,10,'A tak viziž, že tě Hospodin zvolil, abys vystavěl dům svatyně; posilniž se a dělej.'),
(1557347,54,13,28,11,'Dal pak David Šalomounovi synu svému formu síňce i pokojů jejích, a sklepů i paláců a komor jejích vnitřních, i domu pro slitovnici,'),
(1557348,54,13,28,12,'A formu všeho toho, což byl složil v mysli své o síních domu Hospodinova, i o všech komorách vůkol chrámu pro poklady domu Božího, i pro poklady věcí posvátných,'),
(1557349,54,13,28,13,'I pro houfy kněží a Levítů, a pro všecko dílo služby domu Hospodinova, a pro všecko nádobí k přisluhování v domě Hospodinově.'),
(1557350,54,13,28,14,'Dal též zlata v jisté váze na nádobí zlaté, na všelijaké nádobí k jedné každé službě, též stříbra na všecky nádoby stříbrné v jisté váze na všelijaké nádobí k jedné každé službě,'),
(1557351,54,13,28,15,'Totiž váhu na svícny zlaté, a lampy jejich zlaté podlé váhy jednoho každého svícnu i lamp jeho, na svícny pak stříbrné podlé váhy svícnu každého a lamp jeho, jakž potřebí bylo každému svícnu.'),
(1557352,54,13,28,16,'Zlata též váhu na stoly předložení na jeden každý stůl, i stříbra na stoly stříbrné,'),
(1557353,54,13,28,17,'I na vidličky a na kotlíky, i na přikryvadla zlata ryzího, a na medenice zlaté váhu na jednu každou medenici, tolikéž na medenice stříbrné jistou váhu na jednu každou medenici.'),
(1557354,54,13,28,18,'Také na oltář k kadění zlata ryzího váhu, zlata i k udělání vozů cherubínů, kteříž by roztaženými křídly zastírali truhlu úmluvy Hospodinovy.'),
(1557355,54,13,28,19,'Všecko to skrze vypsání z ruky Hospodinovy mne došlo, kterýž mi to dal, abych vyrozuměl všemu dílu formy té.'),
(1557356,54,13,28,20,'A tak řekl David Šalomounovi synu svému: Posilniž se a zmocni a dělej; neboj se, ani lekej. Nebo Hospodin Bůh, Bůh můj s tebou bude, nenecháť tebe samého, aniž tě opustí, až i dokonáno bude všecko dílo služby domu Hospodinova.'),
(1557357,54,13,28,21,'Hle, i houfové kněží a Levítů ke všeliké službě domu Božího s tebou také budou při všelikém díle, jsouce všickni ochotní a prozřetelní v moudrosti při všeliké práci, knížata také i všecken lid ke všechněm slovům tvým.'),
(1557358,54,13,29,1,'Potom řekl David král všemu shromáždění: Šalomouna syna mého jediného vyvolil Bůh ještě maličkého a mladého, dílo pak toto veliké jest; nebo ne člověku palác ten, ale Hospodinu Bohu býti má.'),
(1557359,54,13,29,2,'Já zajisté podlé své nejvyšší možnosti nachystal jsem potřeb k domu Boha svého, zlata k nádobám zlatým, a stříbra k stříbrným, mědi k měděným, železa k železným a dříví k dřevěným, kamení onychinového i kamení k vsazování, i karbunkulového, a rozličných barev, a všelijakého kamení drahého, i kamení mramorového hojně.'),
(1557360,54,13,29,3,'Nadto z veliké lásky k domu Boha svého, maje zvláštní poklad zlata a stříbra, i ten dávám k domu Boha svého mimo všecko to, což jsem připravil k domu svatyně,'),
(1557361,54,13,29,4,'Totiž tři tisíce centnéřů zlata, zlata z Ofir, a sedm tisíc centnéřů stříbra přečištěného k potažení stěn domů svatých,'),
(1557362,54,13,29,5,'Zlata k nádobám zlatým a stříbra k stříbrným i ke všelikému dílu řemeslnému. A jestliže jest kdo více, ješto by co chtěl dobrovolně obětovati dnes Hospodinu?'),
(1557363,54,13,29,6,'Tedy knížata čeledí otcovských a knížata pokolení Izraelských, i hejtmané a setníci i úředníci nad dílem královským dobrovolně obětovali.'),
(1557364,54,13,29,7,'A dali k službě domu Božího zlata pět tisíc centnéřů, a deset tisíc zlatých, stříbra pak deset tisíc centnéřů, a mědi osmnácte tisíc centnéřů, a železa sto tisíc centnéřů.'),
(1557365,54,13,29,8,'Kdožkoli měli kamení drahé, dávali do pokladu domu Hospodinova do rukou Jechiele Gersunského.'),
(1557366,54,13,29,9,'I veselil se lid, že tak ochotně obětovali; nebo celým srdcem dobrovolně obětovali Hospodinu. Nýbrž i král David radoval se radostí velikou.'),
(1557367,54,13,29,10,'A protož dobrořečil David Hospodinu před oblíčejem všeho shromáždění, a řekl David: Požehnaný jsi ty Hospodine, Bože Izraele otce našeho, od věků až na věky.'),
(1557368,54,13,29,11,'Tváť jest, ó Hospodine, velebnost i moc i sláva, i vítězství i čest, ano i všecko, což jest v nebi i v zemi. Tvé jest, ó Hospodine, království, a ty jsi vyšší nad všelikou vrchnost.'),
(1557369,54,13,29,12,'I bohatství i sláva od tebe jest, a ty panuješ nade vším, a v ruce tvé jest moc a síla, a v ruce tvé také jest i to, kohož chceš zvelebiti a upevniti.'),
(1557370,54,13,29,13,'Nyní tedy, Bože náš, děkujeme tobě, a chválíme jméno slávy tvé.'),
(1557371,54,13,29,14,'Nebo kdo jsem já, a co jest lid můj, abychom mohli míti moc k tak dobrovolnému obětování tobě? Od tebeť jest zajisté všecko, a i to z ruky tvé dali jsme tobě.'),
(1557372,54,13,29,15,'Nebo my příchozí jsme před tebou a hosté, jako i všickni otcové naši; dnové naši jsou jako stín běžící po zemi beze vší zástavy.'),
(1557373,54,13,29,16,'Hospodine, Bože náš, všecka ta hojnost, kterouž jsme připravili k stavení domu tvého, jménu svatému tvému, z ruky tvé jest, a tvé jsou všecky věci.'),
(1557374,54,13,29,17,'Známť pak, Bože můj, že ty zpytuješ srdce, a upřímnost oblibuješ; protož já z upřímnosti srdce svého ochotně obětoval jsem toto všecko. Ano i lid tvůj, kterýž se teď shledal, viděl jsem, jak s radostí chtivě obětuje tobě.'),
(1557375,54,13,29,18,'Hospodine, Bože Abrahama, Izáka a Izraele, otců našich, zachovejž to na věky,totiž snažnost takovou srdce lidu svého,a nastrojuj srdce jejich sobě.'),
(1557376,54,13,29,19,'Šalomounovi také synu mému dej srdce upřímé, aby ostříhal přikázaní tvých, svědectví tvých a ustanovení tvých, a aby činil všecko, a vystavěl dům ten, k němuž jsem potřeby připravil.'),
(1557377,54,13,29,20,'Potom řekl David všemu shromáždění: Dobrořečte nyní Hospodinu Bohu svému. I dobrořečilo všecko shromáždění Hospodinu Bohu otců svých, a přisehnuvše hlavy, poklonili se Hospodinu i králi.'),
(1557378,54,13,29,21,'Zatím obětovali Hospodinu oběti, obětovali také zápaly Hospodinu nazejtří, volů tisíc, skopců tisíc, beranů tisíc, s mokrými obětmi jejich, a jiných obětí množství za všecken lid Izraelský.'),
(1557379,54,13,29,22,'I jedli a pili před Hospodinem v ten den s radostí velikou. Potom za krále ustanovili po druhé Šalomouna syna Davidova, a pomazali jej Hospodinu za vývodu, a Sádocha za kněze.'),
(1557380,54,13,29,23,'A tak dosedl Šalomoun na stolici Hospodinovu, aby byl králem místo Davida otce svého. I vedlo se mu šťastně, a poslouchal ho všecken Izrael.'),
(1557381,54,13,29,24,'Tolikéž i všecka knížata a znamenití, i všickni synové krále Davida poddali se Šalomounovi králi.'),
(1557382,54,13,29,25,'I zvelebil Hospodin Šalomouna náramně před očima všeho Izraele, a dal mu slávu královskou, jakéž neměl před ním žádný král v Izraeli.'),
(1557383,54,13,29,26,'Kraloval pak byl David syn Izai nade vším Izraelem.'),
(1557384,54,13,29,27,'A dnů, v nichž kraloval David nad Izraelem, bylo čtyřidceti let. V Hebronu kraloval sedm let, a v Jeruzalémě kraloval třidceti a tři léta.'),
(1557385,54,13,29,28,'I umřel v starosti dobré, pln jsa dnů, bohatství a slávy, a kraloval Šalomoun syn jeho místo něho.'),
(1557386,54,13,29,29,'Činové pak Davida krále první i poslední popsáni jsou v knize Samuele proroka, a v knize Nátana proroka, též v knize Gáda proroka,'),
(1557387,54,13,29,30,'Se vším kralováním i silou jeho, i se všemi příběhy časů při něm i při lidu Izraelském, i při všech královstvích zemských.'),
(1557388,54,14,1,1,'Když se pak zmocnil Šalomoun syn Davidův v království svém, a Hospodin Bůh jeho byl s ním, a zvelebil ho náramně:'),
(1557389,54,14,1,2,'Tedy rozkázal Šalomoun všemu Izraelovi i hejtmanům, setníkům i soudcům, i všechněm knížatům nade vším Izraelem, i přednějším v čeledech otcovských.'),
(1557390,54,14,1,3,'I bral se Šalomoun a všecko to shromáždění s ním na výsost, kteráž byla v Gabaon; nebo tam byl stánek shromáždění Božího, kterýž byl udělal Mojžíš služebník Hospodinův na poušti.'),
(1557391,54,14,1,4,'(Truhlu pak Boží přivezl byl David z Kariatjeharim, připraviv jí místo; nebo byl rozbil jí stan v Jeruzalémě.)');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557392,54,14,1,5,'A oltář měděný, kterýž byl udělal Bezeleel syn Uri, syna Hur, byl tam před stánkem Hospodinovým, kdež hledal ho Šalomoun i všecko to shromáždění.'),
(1557393,54,14,1,6,'I obětoval tam Šalomoun před Hospodinem na oltáři měděném, kterýž byl před stánkem úmluvy, a obětoval na něm tisíc zápalů.'),
(1557394,54,14,1,7,'Té noci ukázal se Bůh Šalomounovi, a řekl jemu: Žádej, zač chceš, a dám tobě.'),
(1557395,54,14,1,8,'I řekl Šalomoun Bohu: Ty jsi učinil otci mému Davidovi milosrdenství veliké, mne jsi též ustanovil králem místo něho.'),
(1557396,54,14,1,9,'Již tedy, Hospodine Bože, budiž stálé slovo tvé mluvené s Davidem otcem mým; nebo ty jsi mne ustanovil za krále nad lidem tak mnohým, jako jest prachu zemského.'),
(1557397,54,14,1,10,'Protož dej mi moudrost a umění, aťbych vycházeti mohl před lidem tímto i vcházeti. Nebo kdož by mohl souditi tento lid tvůj tak mnohý?'),
(1557398,54,14,1,11,'Tedy odpověděl Bůh Šalomounovi: Proto že bylo to v srdci tvém, a nežádal jsi bohatství, ani zboží, ani slávy, ani bezživotí těch, jenž tebe nenávidí, aniž jsi také za dlouhý věk žádal, ale žádal jsi sobě moudrosti a umění, abys soudil lid můj, nad nímž jsem tě ustanovil za krále:'),
(1557399,54,14,1,12,'Moudrost a umění dáno jest tobě, k čemužť přidám i bohatství a zboží, i slávy, tak že žádný z králů, kteříž byli před tebou, nebyl tobě rovný, aniž bude po tobě takového.'),
(1557400,54,14,1,13,'I navrátil se Šalomoun s výsosti, kteráž byla v Gabaon, do Jeruzaléma, od stánku úmluvy, a tak kraloval nad Izraelem.'),
(1557401,54,14,1,14,'Nashromáždil pak Šalomoun vozů a jezdců, a měl tisíc a čtyři sta vozů, a dvanácte tisíc jezdců, kteréž rozsadil do měst vozů, a při králi v Jeruzalémě.'),
(1557402,54,14,1,15,'I složil král stříbra a zlata v Jeruzalémě jako kamení, a dříví cedrového jako planého fíkoví, kteréž roste v údolí u velikém množství.'),
(1557403,54,14,1,16,'Přivodili také Šalomounovi koně z Egypta a koupě rozličné; nebo kupci královští brávali koupě rozličné za slušnou mzdu.'),
(1557404,54,14,1,17,'A vycházejíce, vodívali spřež vozníků z Egypta za šest set lotů stříbra, koně pak za půl druhého sta. A tak všechněm králům Hetejským i králům Syrským oni dodávali.'),
(1557405,54,14,2,1,'A umíniv Šalomoun stavěti dům jménu Hospodinovu, a dům svůj královský,'),
(1557406,54,14,2,2,'Odečtl Šalomoun sedmdesát tisíc nosičů a osmdesát tisíc těch, kteříž tesali na hoře, a úředníků nad nimi tři tisíce a šest set.'),
(1557407,54,14,2,3,'Poslal také Šalomoun k Chíramovi králi Tyrskému, řka: Jakž jsi se choval k Davidovi otci mému, posílaje mu dříví cedrové, aby sobě stavěl dům k bydlení, tak čiň i mně.'),
(1557408,54,14,2,4,'Nebo aj, já stavěti chci dům jménu Hospodina Boha svého, aby posvěcen byl jemu k tomu, aby se před ním kadilo vonnými věcmi, a k ustavičnému předkládání chlebů, i k zápalným obětem, ranním i večerním, ve dny sobotní a novoměsíčné, i na slavnosti Hospodina Boha našeho, což v Izraeli na věky trvati má.'),
(1557409,54,14,2,5,'Dům pak, kterýž stavěti chci, veliký býti má; nebo Bůh náš větší jest nade všecky bohy.'),
(1557410,54,14,2,6,'Ač kdo jest, ješto by mohl dům jemu vystavěti, poněvadž ho nebe i nebesa nebes obsáhnouti nemohou? Ano i já kdo jsem, abych jemu dům vystavěti měl, než toliko k tomu, aby se kadilo před ním?'),
(1557411,54,14,2,7,'Protož nyní pošli mi muže umělého, kterýž by uměl dělati na zlatě, na stříbře, na mědi, na železe, i z zlatohlavu a z červce, a z postavce modrého, a kterýž by uměl řezati řezby s jinými umělými, kteříž jsou u mne v Judstvu a v Jeruzalémě, kteréž zjednal David otec můj.'),
(1557412,54,14,2,8,'Přes to pošli mi také dříví cedrového a jedlového, a algumim z Libánu; nebo vím, že služebníci tvoji umějí sekati dříví Libánské. A hle, služebníci moji budou s služebníky tvými,'),
(1557413,54,14,2,9,'Aby mi připravili dostatek dříví; nebo dům, kterýž já stavěti chci, veliký býti má a slavný.'),
(1557414,54,14,2,10,'A aj, dám na dělníky, kteříž sekati mají dříví, pšenice semlené služebníkům tvým dvadcet tisíc měr, a dvadcet tisíc měr ječmene, a dvadcet tisíc lák vína, a dvadcet tisíc tun oleje.'),
(1557415,54,14,2,11,'I odpověděl Chíram král Tyrský psáním, kteréž poslal k Šalomounovi: Jistě, žeť miluje Hospodin lid svůj, protož tě ustanovil nad nimi za krále.'),
(1557416,54,14,2,12,'Řekl dále Chíram: Požehnaný Hospodin Bůh Izraelský, kterýž učinil nebe i zemi, a kterýž dal králi Davidovi syna moudrého, umělého, rozumného a opatrného, aby vystavěl dům Hospodinu a dům svůj královský.'),
(1557417,54,14,2,13,'Protož posílámť teď muže moudrého, umělého a opatrného, kterýž byl u Chírama otce mého,'),
(1557418,54,14,2,14,'Syna jedné ženy ze dcer Dan, otce pak měl Tyrského, kterýž umí dělati na zlatě, na stříbře, na mědi, železe, kamení a na dříví, i z šarlatu, z postavce modrého, z kmentu a z červce, tolikéž řezati všelijaké řezby, a vymysliti všelijaké dílo, kteréž dáno mu bude s moudrými tvými, a s moudrými pána mého Davida otce tvého.'),
(1557419,54,14,2,15,'Pšenice však toliko a ječmene, oleje a vína, což řekl pán můj, nechť pošle služebníkům svým.'),
(1557420,54,14,2,16,'My pak nasekáme dříví z Libánu, což ho koli bude potřebí tobě, a připlavíme je tobě v vořích po moři k Joppe, a ty dáš je voziti do Jeruzaléma.'),
(1557421,54,14,2,17,'A tak sečtl Šalomoun všecky cizozemce, kteříž byli v zemi Izraelské po sečtení tom, kterýmž sečtl je David otec jeho, a nalezeno jich sto a padesát tisíc, tři tisíce a šest set.'),
(1557422,54,14,2,18,'I vybral z nich sedmdesát tisíc nosičů, a osmdesát tisíc těch, kteříž sekali na hoře, tři pak tisíce a šest set úředníků, kteříž lid k dílu přídrželi.'),
(1557423,54,14,3,1,'I začal stavěti Šalomoun domu Hospodinova v Jeruzalémě na hoře Moria, kteráž byla ukázána Davidovi otci jeho, na místě, kteréž byl připravil David, na humně Ornana Jebuzejského.'),
(1557424,54,14,3,2,'A počal stavěti druhého měsíce, dne druhého, království svého léta čtvrtého.'),
(1557425,54,14,3,3,'A toto jest vyměření Šalomounovo při stavení domu Božího: Dlouhost loktů podlé první míry bylo šedesáti loket, a šíř dvadcíti loket.'),
(1557426,54,14,3,4,'A síň, kteráž byla v čele, jakž široký dům, byla na dvadceti loktů, vysokost pak sto a dvadcíti, a obložil ji vnitř zlatem čistým.'),
(1557427,54,14,3,5,'Dům pak veliký opažil dřívím jedlovým, kteréž obložil zlatem nejčistším, na němž po vrchu dal nadělati palm a řetízků.'),
(1557428,54,14,3,6,'Přikryl také dům ten kamenem drahým ozdobně; zlato pak to bylo zlato Parvaimské.'),
(1557429,54,14,3,7,'Obložil, pravím, dům, trámy, veřeje i stěny jeho, i dvéře jeho zlatem, a vyryl cherubíny na stěnách.'),
(1557430,54,14,3,8,'Udělal i dům svatyně svatých, jehož dýlka byla jako šířka domu, dvadcíti loktů, a šířka loktů dvadcíti, a obložil ji zlatem výborným šesti sty centnéři.'),
(1557431,54,14,3,9,'Hřebíkové též vážili padesát lotů zlata, ano i síňce obložil zlatem.'),
(1557432,54,14,3,10,'Udělal také v domě svatyně svatých dva cherubíny dílem řemeslným, a obložil je zlatem.'),
(1557433,54,14,3,11,'Dlouhost křídel těch cherubínů byla na dvadceti loket. Křídlo jedno na pět loket, a dotýkalo se stěny domu, a druhé křídlo na pět loket dotýkalo se křídla cherubína druhého.'),
(1557434,54,14,3,12,'A tak křídlo cherubína jednoho na pět loket dotýkalo se stěny domu, a křídlo druhé na pět loket dosahovalo křídla cherubína druhého.'),
(1557435,54,14,3,13,'A tak křídla cherubínů těch roztažená byla na dvadceti loktů, a stáli na nohách svých, tváří svou obráceni do domu.'),
(1557436,54,14,3,14,'Udělal také i oponu z postavce modrého, z šarlatu, z červce a z kmentu, a udělal na ní cherubíny.'),
(1557437,54,14,3,15,'Udělal též před domem sloupy dva na třidceti a pět loktů zvýší, a makovice, kteréž byly na každém svrchu, na pět loket.'),
(1557438,54,14,3,16,'Zdělal též i řetízky jako v svatyni svatých, a otočil je okolo makovic těch sloupů, a udělav jablek zrnatých sto, dal mezi řetízky.'),
(1557439,54,14,3,17,'A tak postavil ty sloupy před chrámem, jeden po pravé a druhý po levé straně, a dal jméno tomu, kterýž byl po pravici Jachin, a jméno tomu, kterýž byl po levici, Boaz.'),
(1557440,54,14,4,1,'Udělal také i oltář měděný, zdélí dvadcíti loktů, a dvadcíti loktů zšíří, desíti pak loktů zvýší.'),
(1557441,54,14,4,2,'Udělal též moře slité, desíti loket od jednoho kraje k druhému, okrouhlé vůkol, zvýší na pět loktů, a okolek jeho třidcíti loket vůkol.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557442,54,14,4,3,'Podobenství také volů pod ním, kterýchž všudy vůkol bylo deset do lokte, obkličujících moře vůkol; a tak byly dva řady volů slitých, spolu s mořem.'),
(1557443,54,14,4,4,'A stálo na dvanácti volích. Tři obráceni byli na půlnoci, a tři patřili k západu, tři zase postaveni byli ku poledni, a tři obráceni byli k východu, a moře svrchu na nich stálo, ale všech jich zadkové byli pod mořem.'),
(1557444,54,14,4,5,'A bylo ztlouští na dlaň. Kraj jeho byl, jakýž bývá u koflíku aneb květu liliového, tři tisíce tun v se beroucí.'),
(1557445,54,14,4,6,'Udělal také deset umyvadel, a postavil jich pět po pravé straně, a pět po levé, k obmývání z nich. Všecko, což se strojilo k zápalům, obmývali z nich, ale moře, aby se z něho kněží umývali.'),
(1557446,54,14,4,7,'Nadto udělal i svícnů zlatých deset vedlé slušnosti jejich, a postavil v chrámě, pět po pravé straně a pět po levé.'),
(1557447,54,14,4,8,'Udělal i stolů deset, kteréž postavil v chrámě, pět po pravé a pět po levé straně. K tomu udělal číší zlatých sto.'),
(1557448,54,14,4,9,'Udělal potom síň kněžskou, též síň velikou, a dvéře u též síně okoval mědí.'),
(1557449,54,14,4,10,'Moře pak postavil na pravé straně k východu, naproti polední straně.'),
(1557450,54,14,4,11,'Nadělal také Chíram hrnců, lopat a kotlíků, a dokonal Chíram dílo, kteréž byl dělal králi Šalomounovi k domu Božímu.'),
(1557451,54,14,4,12,'Dva sloupy a kruhy, makovice také na vrchu těch dvou sloupů, a mřežování dvoje, aby přikrývalo ty dvě makovice okrouhlé, kteréž byly na vrchu sloupů,'),
(1557452,54,14,4,13,'A jablek zrnatých čtyři sta na dvojím mřežování. Dvěma řady jablka zrnatá byla na mřežování jednom, aby přikrývala ty dvě makovice okrouhlé, kteréž byly na vrchu sloupů.'),
(1557453,54,14,4,14,'Podstavky také zdělal, a umyvadla na těch podstavcích.'),
(1557454,54,14,4,15,'Moře jedno, a volů dvanácte pod ním.'),
(1557455,54,14,4,16,'Též hrnce a lopaty a vidličky třírohé, a všecko nádobí jejich zdělal Chíram s otcem svým králi Šalomounovi k domu Hospodinovu z mědi přečisté.'),
(1557456,54,14,4,17,'Na rovinách Jordánských sléval to král v zemi jilovaté, mezi Sochot a Saredata.'),
(1557457,54,14,4,18,'A tak nadělal Šalomoun všech těch nádob velmi mnoho, tak že váhy té mědi vyhledáváno nebylo.'),
(1557458,54,14,4,19,'Zdělal také Šalomoun i jiná všelijaká nádobí k domu Božímu, jako oltář zlatý a stoly, na nichž kladeni byli chlebové předložení,'),
(1557459,54,14,4,20,'Tolikéž svícny i lampy jejich z zlata nejčistšího, aby je rozsvěcovali příslušně před svatyní svatých,'),
(1557460,54,14,4,21,'Květy také a lampy i utěradla z zlata, a to bylo zlato nejvýbornější.'),
(1557461,54,14,4,22,'I žaltáře a kotlíky, kadidlnice a nádoby k oharkům z zlata čistého, k tomu i bránu domu, dvéře vnitřní svatyně svatých, i dvéře domu, totiž v chrámě, byly z zlata.'),
(1557462,54,14,5,1,'A tak dokonáno jest všecko dílo, kteréž dělal Šalomoun k domu Hospodinovu, a vnesl tam Šalomoun věci posvěcené od Davida otce svého, též stříbro a zlato, a všecko nádobí, složiv je mezi poklady domu Božího.'),
(1557463,54,14,5,2,'Tedy shromáždil Šalomoun starší Izraelské, a všecky přední z pokolení, totiž knížata čeledí otcovských s syny Izraelskými do Jeruzaléma, aby přenesli truhlu smlouvy Hospodinovy z města Davidova, jenž jest Sion.'),
(1557464,54,14,5,3,'I shromáždili se k králi všickni muži Izraelští na slavnost, kteráž bývá měsíce sedmého.'),
(1557465,54,14,5,4,'Když pak přišli všickni starší Izraelští, vzali Levítové truhlu,'),
(1557466,54,14,5,5,'A nesli ji zhůru, též stánek úmluvy, i všecka nádobí posvátná, kteráž byla v stánku, přenesli to kněží a Levítové.'),
(1557467,54,14,5,6,'Zatím král Šalomoun i všecko shromáždění Izraelské, kteréž se k němu sešlo, obětovali před truhlou ovce a voly, kteříž ani popisováni, ani vyčítáni nebyli pro množství.'),
(1557468,54,14,5,7,'A tak vnesli kněží truhlu smlouvy Hospodinovy na místo její, do vnitřního domu, do svatyně svatých, pod křídla cherubínů.'),
(1557469,54,14,5,8,'Nebo cherubínové měli roztažená křídla nad místem truhly, a přikrývali cherubínové truhlu i sochory její svrchu.'),
(1557470,54,14,5,9,'A povytáhli sochorů, tak že vidíni byli koncové jejich z truhly, k předku svatyně svatých, vně však nebylo jich viděti. A byla tam až do tohoto dne.'),
(1557471,54,14,5,10,'Nic nebylo v truhle, kromě dvou tabulí, kteréž tam složil Mojžíš na Orébě tehdáž, když učinil Hospodin smlouvu s syny Izraelskými, a oni vyšli z Egypta.'),
(1557472,54,14,5,11,'I stalo se, když vycházeli kněží z svatyně, (nebo všickni kněží, kteříž se koli našli, byli se posvětili, aniž šetřili pořádku.'),
(1557473,54,14,5,12,'Tak i Levítové zpěváci všickni, kteříž byli při Azafovi, Hémanovi a Jedutunovi, i synové jejich i bratří jejich, odíni jsouce kmentem, stáli s cymbály a loutnami a harfami k východní straně oltáře, a s nimi kněží sto a dvadceti, troubících v trouby.'),
(1557474,54,14,5,13,'Nebo měli ti, kteříž spolu troubili v trouby, a zpěváci vydávati jeden zvuk k chválení a oslavování Hospodina); a když povyšovali hlasu na trouby a cymbály i jiné nástroje hudebné, chválíce Hospodina a řkouce, že dobrý jest, a že na věky trvá milosrdenství jeho: tedy oblak naplnil dům ten, dům totiž Hospodinův,'),
(1557475,54,14,5,14,'Tak že nemohli kněží ostáti a sloužiti pro ten oblak; nebo sláva Hospodinova byla naplnila dům Boží.'),
(1557476,54,14,6,1,'Tehdy řekl Šalomoun: Hospodin řekl, že bude přebývati v mrákotě.'),
(1557477,54,14,6,2,'Aj, jižť jsem vystavěl tobě, Pane, dům k přebývání, a místo, v němž bys přebýval na věky.'),
(1557478,54,14,6,3,'A obrátiv král tvář svou, dával požehnání všemu shromáždění Izraelskému. (Všecko pak shromáždění Izraelské stálo.)'),
(1557479,54,14,6,4,'A řekl: Požehnaný Hospodin Bůh Izraelský, kterýž mluvil ústy svými Davidovi otci mému, a to teď skutečně naplnil, řka:'),
(1557480,54,14,6,5,'Od toho dne, jakž jsem vyvedl lid svůj z země Egyptské, nevyvolil jsem města z žádného pokolení Izraelského k vystavení domu, kdež by přebývalo jméno mé, aniž jsem vyvolil kterého muže, aby byl vývodou nad lidem mým Izraelským.'),
(1557481,54,14,6,6,'Ale vyvolil jsem Jeruzalém, aby tu přebývalo jméno mé, a vyvolil jsem Davida, aby byl nad lidem mým Izraelským.'),
(1557482,54,14,6,7,'Uložil tě byl zajisté David otec můj stavěti dům jménu Hospodina Boha Izraelského.'),
(1557483,54,14,6,8,'Ale Hospodin řekl Davidovi otci mému: Ačkoli jsi uložil v srdci svém stavěti dům jménu mému, a dobřes učinil, žes to myslil v srdci svém,'),
(1557484,54,14,6,9,'A však ty nebudeš stavěti toho domu, ale syn tvůj, kterýž vyjde z bedr tvých, on vystaví dům ten jménu mému.'),
(1557485,54,14,6,10,'A tak splnil Hospodin slovo své, kteréž byl mluvil. Nebo jsem povstal na místo Davida otce svého, a dosedl jsem na stolici Izraelskou, jakož byl mluvil Hospodin, a ustavěl jsem dům tento jménu Hospodina Boha Izraelského.'),
(1557486,54,14,6,11,'A postavil jsem tam truhlu, v níž jest smlouva Hospodinova, kterouž učinil s syny Izraelskými.'),
(1557487,54,14,6,12,'I postavil se před oltářem Hospodinovým, přede vším shromážděním Izraelským, a pozdvihl rukou svých.'),
(1557488,54,14,6,13,'Udělal pak byl Šalomoun výstupek měděný ku podobenství pánve, a postavil jej u prostřed síně, pěti loktů zdélí, a pěti loket zšíří, a tří loket zvýší, i vstoupil na něj, a poklekl na kolena svá přede vším shromážděním Izraelským, a pozdvihl rukou svých k nebi,'),
(1557489,54,14,6,14,'A řekl: Hospodine Bože Izraelský, neníť podobného tobě Boha na nebi ani na zemi, kterýž by ostříhal smlouvy a milosrdenství služebníkům svým, chodícím před tebou v celém srdci svém,'),
(1557490,54,14,6,15,'Kterýž jsi splnil služebníku svému, Davidovi otci mému, to, což jsi mluvil jemu. Jakž jsi mluvil ústy svými, tak jsi to skutečně naplnil, jakž se to dnes vidí.'),
(1557491,54,14,6,16,'Nyní tedy, ó Hospodine Bože Izraelský, naplniž služebníku svému, Davidovi otci mému, což jsi mluvil jemu, řka: Nebudeť vyhlazen muž z rodu tvého od tváři mé, aby neměl seděti na stolici Izraelské, jestliže toliko ostříhati budou synové tvoji cesty své, chodíce v zákoně mém, tak jakož jsi ty chodil přede mnou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557492,54,14,6,17,'Protož nyní, ó Hospodine Bože Izraelský, nechť jest upevněno slovo tvé, kteréž jsi mluvil služebníku svému Davidovi.'),
(1557493,54,14,6,18,'(Ač zdali v pravdě bydliti bude Bůh s člověkem na zemi? Aj, nebesa, nýbrž nebesa nebes neobsahují tě, mnohem méně dům tento, kterýž jsem vystavěl.)'),
(1557494,54,14,6,19,'A popatř k modlitbě služebníka svého a k úpění jeho, Hospodine Bože můj, slyše volání a modlitbu, kterouž služebník tvůj modlí se před tebou,'),
(1557495,54,14,6,20,'Aby oči tvé byly otevřené na dům tento dnem i nocí, na místo toto, o němž jsi mluvil, že tu přebývati bude jméno tvé, abys vyslýchal modlitbu, kterouž se modlívati bude služebník tvůj na místě tomto.'),
(1557496,54,14,6,21,'Vyslýchejž tedy modlitbu služebníka svého, i lidu svého Izraelského, kterouž se modlívati budou na místě tomto, ty vždy vyslýchej z místa přebývání svého, s nebe, a vyslýchaje, buď milostiv.'),
(1557497,54,14,6,22,'Když by zhřešil člověk proti bližnímu svému, a nutil by ho k přísaze, tak že by přisahati musil, a přišla by ta přísaha před oltář do domu tohoto:'),
(1557498,54,14,6,23,'Ty vyslýchej s nebe, a rozeznej i rozsuď služebníky své, mstě nad bezbožným, obraceje usilování jeho na hlavu jeho, a ospravedlňuje spravedlivého, odplacuje mu podlé spravedlnosti jeho.'),
(1557499,54,14,6,24,'Tolikéž když by poražen byl lid tvůj Izraelský od nepřátel, proto že zhřešili proti tobě, jestliže by obrátíce se, vyznávali jméno tvé, a modléce se, poníženě by prosili tebe v domě tomto:'),
(1557500,54,14,6,25,'Ty vyslýchej s nebe, a odpusť hřích lidu svému Izraelskému, a přiveď je zase do země, kterouž jsi jim dal i otcům jejich.'),
(1557501,54,14,6,26,'Podobně když by zavříno bylo nebe, a nepršel by déšť, proto že zhřešili proti tobě, a modléce se na místě tomto, vyznávali by jméno tvé, a od hříchu svého by se odvrátili po tvém trestání:'),
(1557502,54,14,6,27,'Ty vyslýchej na nebi, a odpusť hřích služebníků svých a lidu svého Izraelského, vyučuje je cestě výborné, po níž by chodili, a dej déšť na zemi svou, kterouž jsi dal lidu svému za dědictví.'),
(1557503,54,14,6,28,'Byl-li by hlad na zemi, byl-li by mor, sucho neb rez, kobylky neb brouci jestliže by byli, ssoužil-li by jej nepřítel jeho v zemi obývání jeho, aneb jakákoli rána a jakákoli nemoc:'),
(1557504,54,14,6,29,'Všelikou modlitbu a každé úpění, kteréž by pocházelo od kteréhokoli člověka, aneb ode všeho lidu tvého Izraelského, když by jen poznajíce jeden každý ránu svou a bolest svou, pozdvihl by rukou svých v domě tomto,'),
(1557505,54,14,6,30,'Ty vyslýchej s nebe, z místa přebývání svého, a slituj se, a odplať jednomu každému podlé skutků jeho, vedlé toho, jakž znáš srdce jeho, (ty zajisté sám znáš srdce lidská),'),
(1557506,54,14,6,31,'Aby se báli tebe, a chodili po všech cestách tvých, po všecky dny, v nichž by živi byli na zemi, kterouž jsi dal otcům našim.'),
(1557507,54,14,6,32,'Nýbrž také i cizozemec, kterýž není z lidu tvého Izraelského, přišel-li by z země daleké pro jméno tvé veliké a ruku tvou silnou, a rámě tvé vztažené, když by přišli a modlili se v domě tomto:'),
(1557508,54,14,6,33,'Ty vyslýchej s nebe, z místa přebývání svého, a učiň všecko to, o čež volati bude k tobě cizozemec ten, aby poznali všickni národové země jméno tvé, a báli se tebe jako lid tvůj Izraelský, a aby poznali, že jméno tvé vzýváno jest nad domem tímto, kterýž jsem vystavěl.'),
(1557509,54,14,6,34,'Když by vytáhl lid tvůj k boji proti nepřátelům svým cestou, kterouž bys je poslal, a modlili by se tobě naproti městu tomuto, kteréž jsi vyvolil, a domu tomuto, kterýž jsem ustavěl jménu tvému:'),
(1557510,54,14,6,35,'Ty vyslýchej s nebe modlitbu a úpění jejich, a vyvoď při jejich.'),
(1557511,54,14,6,36,'Když by zhřešili proti tobě, (jakož není člověka, ješto by nehřešil), a rozhněvaje se na ně, vydal bys je v moc nepříteli, tak že by je jaté vedli ti, kteříž by je zjímali, do země daleké neb blízké;'),
(1557512,54,14,6,37,'A usmyslili by sobě v zemi, do níž by zajati byli, a obrátíce se, modlili by se tobě v zemi zajetí svého, řkouce: Zhřešili jsme, převráceně jsme činili, a bezbožně jsme se chovali;'),
(1557513,54,14,6,38,'A tak navrátili by se k tobě celým srdcem svým a celou duší svou v zemi zajetí svého, do kteréž by zajati byli, a modlili by se naproti zemi své, kterouž jsi dal otcům jejich, a naproti městu, kteréž jsi vyvolil, a domu, kterýž jsem vzdělal jménu tvému:'),
(1557514,54,14,6,39,'Vyslýchej s nebe, z místa příbytku svého, modlitbu jejich a úpění jejich, a vyvoď při jejich, a odpusť lidu svému, kterýž by zhřešil proti tobě.'),
(1557515,54,14,6,40,'Nyní tedy, Bože můj, nechť jsou, prosím, oči tvé otevřené, a uši tvé nakloněné k modlitbě na místě tomto.'),
(1557516,54,14,6,41,'Aj, nyní povstaň, ó Hospodine Bože, k odpočinutí svému, ty i truhla síly tvé; kněží tvoji, Hospodine Bože, nechť jsou oblečeni v spasení, a svatí tvoji ať se veselí v dobrých věcech.'),
(1557517,54,14,6,42,'Hospodine Bože, neodvracejž tváři od pomazaného svého, pamatuj na milosrdenství zaslíbená Davidovi služebníku svému.'),
(1557518,54,14,7,1,'A když přestal Šalomoun modliti se, rychle oheň sstoupil s nebe, a sehltil zápal i jiné oběti, a sláva Hospodinova naplnila dům ten,'),
(1557519,54,14,7,2,'Tak že nemohli kněží vjíti do domu Hospodinova, proto že naplnila sláva Hospodinova dům Hospodinův.'),
(1557520,54,14,7,3,'Všickni pak synové Izraelští viděli, když sstupoval oheň a sláva Hospodinova na dům, a padše tváří k zemi na dlážení, klaněli se a chválili Hospodina, že dobrý jest, a že na věky trvá milosrdenství jeho.'),
(1557521,54,14,7,4,'Při tom král a všecken lid obětovali oběti před Hospodinem.'),
(1557522,54,14,7,5,'Obětoval zajisté král Šalomoun obět dvamecítma tisíc volů, a ovec sto a dvadceti tisíců, když posvěcovali domu Božího král i všecken lid.'),
(1557523,54,14,7,6,'Ale kněží stáli při svých úřadích, též i Levítové s nástroji hudebnými Hospodinovými, kterýchž byl nadělal David král k oslavování Hospodina, (nebo na věky milosrdenství jeho), žalmem Davidovým, kterýž jim vydal. Jiní pak kněží troubili v trouby naproti nim, a všecken lid Izraelský stál.'),
(1557524,54,14,7,7,'Posvětil také Šalomoun prostředku té síně, kteráž byla před domem Hospodinovým; nebo obětoval tu oběti zápalné a tuky obětí, pokojných, proto že na oltáři měděném, kterýž byl udělal Šalomoun, nemohli se směstknati zápalové a oběti suché i tukové jejich.'),
(1557525,54,14,7,8,'I držel Šalomoun slavnost toho času za sedm dní, a všecken Izrael s ním, shromáždění velmi veliké odtud, kudyž se vchází do Emat, až ku potoku Egyptskému.'),
(1557526,54,14,7,9,'I světili dne osmého svátek; nebo posvěcení oltáře slavili za sedm dní, tolikéž slavnost tu za sedm dní.'),
(1557527,54,14,7,10,'Třimecítmého pak dne měsíce sedmého propustil lid k příbytkům jejich s radostí a veselím srdce z toho, což dobrého učinil Hospodin Davidovi a Šalomounovi a Izraelovi lidu svému.'),
(1557528,54,14,7,11,'I dokonal Šalomoun dům Hospodinův a dům královský, a všecko, cožkoli byl uložil v srdci svém, aby učinil v domě Hospodinově a v domě svém, šťastně se mu vedlo.'),
(1557529,54,14,7,12,'V tom ukázal se Hospodin Šalomounovi v noci, a řekl jemu: Uslyšel jsem modlitbu tvou, a vyvolil jsem sobě to místo za dům obětí.'),
(1557530,54,14,7,13,'Jestliže zavru nebe, tak že by nebylo deště, a jestliže přikáži kobylkám, aby pohubily zemi, též jestliže pošli morovou ránu na lid svůj,'),
(1557531,54,14,7,14,'A ponižujíce se lid můj, nad nímž jest vzýváno jméno mé, modlili by se, a hledali by tváři mé, a odvrátili by se od cest svých zlých: i já také vyslyším je s nebe, a odpustím hřích jejich, a uzdravím zemi jejich.'),
(1557532,54,14,7,15,'Budouť již i oči mé otevřené, a uši mé nakloněné k modlitbě z místa tohoto.'),
(1557533,54,14,7,16,'Nebo nyní vyvolil jsem a posvětil domu tohoto, aby tu přebývalo jméno mé až na věky, a aby tu byly oči mé a srdce mé po všecky dny.'),
(1557534,54,14,7,17,'A ty budeš-li choditi přede mnou, jako chodil David otec tvůj, tak abys činil všecko to, což jsem přikázal tobě, ustanovení i soudů mých ostříhaje:'),
(1557535,54,14,7,18,'Utvrdím zajisté stolici království tvého, jakož jsem učinil smlouvu s Davidem otcem tvým, řka: Nebude vyhlazen muž z rodu tvého, aby nepanoval nad Izraelem.'),
(1557536,54,14,7,19,'Jestliže pak se odvrátíte a opustíte ustanovení má a přikázání má, kteráž jsem vám vydal, a odejdouce, sloužiti budete bohům cizím a klaněti se jim:'),
(1557537,54,14,7,20,'Vypléním takové z země své, kterouž jsem jim dal, a dům tento, kteréhož jsem posvětil jménu svému, zavrhu od tváři své, a vydám jej v přísloví a v rozprávku mezi všemi národy.'),
(1557538,54,14,7,21,'A tak dům ten, kterýž byl zvýšený každému jdoucímu mimo něj, bude k užasnutí, a dí: Proč tak učinil Hospodin zemi této a domu tomuto?'),
(1557539,54,14,7,22,'Tedy odpovědí: Proto že opustili Hospodina Boha otců svých, kterýž je vyvedl z země Egyptské, a chopili se bohů cizích, a klanějíce se jim, sloužili jim, protož uvedl na ně všecky tyto zlé věci.'),
(1557540,54,14,8,1,'Stalo se potom po přeběhnutí dvadcíti let, v nichž stavěl Šalomoun dům Hospodinův a dům svůj,'),
(1557541,54,14,8,2,'Že vystavěl Šalomoun města, kteráž byl dal Chíram Šalomounovi, a osadil tam syny Izraelské.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557542,54,14,8,3,'Zatím táhl Šalomoun do Emat Soby, a zmocnil se jí.'),
(1557543,54,14,8,4,'I ustavěl Tadmor na poušti, a všecka města skladů vystavěl v Emat.'),
(1557544,54,14,8,5,'Vystavěl i Betoron hořejší, též i Betoron dolejší, města ohrazená zdmi, branami i závorami.'),
(1557545,54,14,8,6,'Ano i Baalat a všecka města, v nichž měl sklady Šalomoun, a všecka města vozů, i města jízdných, všecko vedlé žádosti své, cožkoli chtěl stavěti v Jeruzalémě a na Libánu, i po vší zemi panování svého.'),
(1557546,54,14,8,7,'Všecken také lid, kterýž byl pozůstal z Hetejských, a Amorejských a Ferezejských, a Hevejských a Jebuzejských, kteříž nebyli z Izraele,'),
(1557547,54,14,8,8,'Z synů jejich, kteříž byli pozůstali po nich v zemi té, jichž byli nevyhubili synové Izraelští, uvedl Šalomoun pod plat až do tohoto dne.'),
(1557548,54,14,8,9,'Ale z synů Izraelských, jichž nepodrobil Šalomoun v službu při díle svém, (nebo oni byli muži bojovní a přední knížata jeho, úředníci nad vozy a jezdci jeho),'),
(1557549,54,14,8,10,'Z těch, pravím, bylo předních vládařů, kteréž měl král Šalomoun, dvě stě a padesáte, kteříž panovali nad lidem.'),
(1557550,54,14,8,11,'Dceru pak Faraonovu přestěhoval Šalomoun z města Davidova do domu, kterýž jí byl vystavěl. Nebo řekl: Nemohlať by bydliti manželka má v domě Davida krále Izraelského, nebo svatý jest, proto že vešla do něho truhla Hospodinova.'),
(1557551,54,14,8,12,'Tedy obětoval Šalomoun zápaly Hospodinu na oltáři Hospodinovu, kterýž byl vzdělal před síní,'),
(1557552,54,14,8,13,'Cokoli náležitě každého dne obětováno býti mělo podlé přikázaní Mojžíšova, ve dny sobotní, na novměsíce a na slavnosti, po třikrát do roka, na slavnost přesnic, na slavnost téhodnů, a na slavnost stánků.'),
(1557553,54,14,8,14,'Ustanovil také podlé nařízení Davida otce svého pořádky kněžské k úřadům jejich, a Levíty ku povinnostem jejich, aby chválili Boha, a přisluhovali při kněžích náležitě každého dne, a vrátné v pořádcích jejich u jedné každé brány; nebo tak byl rozkaz Davida muže Božího.'),
(1557554,54,14,8,15,'Aniž se uchýlili od rozkázaní králova kněžím a Levítům při všeliké věci i při pokladích.'),
(1557555,54,14,8,16,'A když dostrojeno bylo všecko dílo Šalomounovo od toho dne, v němž založen byl dům Hospodinův, až do vystavení jeho, a tak dokonán byl dům Hospodinův,'),
(1557556,54,14,8,17,'Tedy jel Šalomoun do Aziongaber a do Elat při břehu mořském v zemi Idumejské.'),
(1557557,54,14,8,18,'I poslal jemu Chíram po služebnících svých lodí, a služebníky umělé na moři, kteříž plavivše se s služebníky Šalomounovými do Ofir, nabrali odtud čtyři sta a padesáte centnéřů zlata, a přinesli je králi Šalomounovi.'),
(1557558,54,14,9,1,'Královna pak z Sáby uslyševši pověst o Šalomounovi, přijela do Jeruzaléma, aby zkusila Šalomouna v pohádkách, s vojskem velmi velikým a s velbloudy, na nichž přinesla vonných věcí, a zlata velmi mnoho i kamení drahého. Přišla tedy k Šalomounovi, a mluvila s ním o všecko, což měla v srdci svém.'),
(1557559,54,14,9,2,'Jížto odpověděl Šalomoun na všecka slova její. Nebylo nic skrytého před Šalomounem, nač by jí neodpověděl.'),
(1557560,54,14,9,3,'Protož uzřevši královna z Sáby moudrost Šalomounovu, a dům, kterýž byl ustavěl,'),
(1557561,54,14,9,4,'I pokrmy stolu jeho, též sedání a stávání služebníků jeho přisluhujících jemu, i roucha jejich, šeňkýře také jeho a oděv jejich, i stupně, kterýmiž vstupoval k domu Hospodinovu: zděsila se náramně,'),
(1557562,54,14,9,5,'A řekla králi: Praváť jest řeč, kterouž jsem slyšela v zemi své o věcech tvých a o moudrosti tvé.'),
(1557563,54,14,9,6,'Však jsem nechtěla věřiti řečem jejich, až jsem přijela a uzřela očima svýma, a aj, není mi praveno ani polovice o velikosti moudrosti tvé. Převýšil jsi pověst tu, kterouž jsem slyšela.'),
(1557564,54,14,9,7,'Blahoslavení muži tvoji, a blahoslavení služebníci tvoji tito, kteříž stojí před tebou vždycky, a slyší moudrost tvou.'),
(1557565,54,14,9,8,'Budiž Hospodin Bůh tvůj požehnaný, kterýž tě sobě oblíbil, aby tě posadil na stolici své, abys byl králem na místě Hospodina Boha tvého. Proto že miluje Bůh tvůj Izraele, aby jej utvrdil na věky, ustanovil tě nad nimi králem, abys činil soud a spravedlnost.'),
(1557566,54,14,9,9,'I dala králi sto a dvadceti centnéřů zlata, a vonných věcí velmi mnoho, i kamení drahého, aniž bylo kdy přivezeno takových vonných věcí, jakéž darovala královna z Sáby Šalomounovi.'),
(1557567,54,14,9,10,'K tomu také i služebníci Chíramovi, a služebníci Šalomounovi, kteříž byli přivezli zlata z Ofir, přivezli dříví algumim a kamení drahého.'),
(1557568,54,14,9,11,'I nadělal král z toho dříví algumim stupňů k domu Hospodinovu i k domu královu, též harf a louten zpěvákům, aniž kdy prvé vídány takové věci v zemi Judské.'),
(1557569,54,14,9,12,'Král také Šalomoun dal královně z Sáby vedlé vší vůle její, čehož požádala, kromě toho, což byla přinesla k králi. Potom se navrátila a odjela do země své, ona i služebníci její.'),
(1557570,54,14,9,13,'Byla pak váha toho zlata, kteréž přicházelo Šalomounovi na každý rok, šest set šedesáte a šest centnéřů zlata,'),
(1557571,54,14,9,14,'Kromě toho, což kupci a prodavači přinášeli, a všickni králové Arabští. A vývodové té země přiváželi zlato a stříbro Šalomounovi.'),
(1557572,54,14,9,15,'A protož nadělal král Šalomoun dvě stě štítů z zlata taženého; šest set lotů zlata taženého dával na každý štít.'),
(1557573,54,14,9,16,'A tři sta pavéz z zlata taženého; tři sta lotů zlata dal na každou pavézu. I složil je král v domě lesu Libánského.'),
(1557574,54,14,9,17,'Udělal také král stolici z kostí slonových velikou, a obložil ji zlatem čistým.'),
(1557575,54,14,9,18,'A bylo šest stupňů k té stolici, a podnože té stolice také byly z zlata, držící se stolice, ano i spolehadla rukám s obou stran, tu kdež se sedalo, a dva lvové stáli u spolehadel.'),
(1557576,54,14,9,19,'Dvanácte též lvů stálo tu na šesti stupních s obou stran. Nebylo nic uděláno takového v žádném království.'),
(1557577,54,14,9,20,'Nadto všecky nádoby krále Šalomouna, jichž ku pití užívali, byly zlaté, a všecky nádoby v domě lesu Libánského byly z zlata nejčistšího. Nic nebylo z stříbra, aniž ho sobě co vážili za dnů Šalomounových.'),
(1557578,54,14,9,21,'Nebo měl král lodí, kteréž přecházely přes moře s služebníky Chíramovými. Jednou ve třech letech vracovaly se ty lodí mořské, přinášející zlato a stříbro, kosti slonové a opice a pávy.'),
(1557579,54,14,9,22,'I zveleben jest král Šalomoun nad všecky krále zemské v bohatství a v moudrosti.'),
(1557580,54,14,9,23,'Pročež všickni králové země žádostivi byli viděti tvář Šalomounovu, aby slyšeli moudrost jeho, kterouž složil Bůh v srdci jeho.'),
(1557581,54,14,9,24,'Z nichž jeden každý přinášeli také dar svůj, nádoby stříbrné a nádoby zlaté, roucha a zbroj, i vonné věci, koně a mezky, každého roku,'),
(1557582,54,14,9,25,'Tak že měl Šalomoun čtyři tisíce stájí koní a vozů, a dvanácte tisíc jezdců, kteréž rozsadil v městech vozů a při králi v Jeruzalémě.'),
(1557583,54,14,9,26,'I panoval nade všemi králi od řeky Eufrates až k zemi Filistinské, a až k končinám Egyptským.'),
(1557584,54,14,9,27,'A složil král stříbra v Jeruzalémě jako kamení, a cedrového dříví jako planého fíkoví, kteréž roste v údolí u velikém množství.'),
(1557585,54,14,9,28,'Přivodili také Šalomounovi koně z Egypta i ze všech zemí.'),
(1557586,54,14,9,29,'Jiné pak věci Šalomounovy, první i poslední, vypsány jsou v knize Nátana proroka, a v proroctví Achiáše Silonského, a u viděních Jaaddy proroka o Jeroboámovi synu Nebatovu.'),
(1557587,54,14,9,30,'A kraloval Šalomoun v Jeruzalémě nade vším Izraelem čtyřidceti let.'),
(1557588,54,14,9,31,'I usnul Šalomoun s otci svými, a pochovali jej v městě Davida otce jeho. Kraloval pak Roboám syn jeho místo něho.'),
(1557589,54,14,10,1,'Tedy odšel Roboám do Sichem; nebo tam sešel se byl všecken Izrael, aby ho ustanovili za krále.'),
(1557590,54,14,10,2,'Stalo se pak, když o tom uslyšel Jeroboám syn Nebatův, jsa v Egyptě, kamž byl utekl před králem Šalomounem, navrátil se Jeroboám z Egypta.'),
(1557591,54,14,10,3,'Nebo poslali a povolali ho. Tedy přišed Jeroboám i všecken Izrael, mluvili k Roboámovi, řkouce:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557592,54,14,10,4,'Otec tvůj stížil jho naše, protož nyní polehč služby otce svého tvrdé a břemene jeho těžkého, kteréž vložil na nás, a budeme tobě sloužiti.'),
(1557593,54,14,10,5,'Kterýž řekl jim: Po třech dnech navraťte se ke mně. I odšel lid.'),
(1557594,54,14,10,6,'V tom radil se král Roboám s starci, kteříž stávali před Šalomounem otcem jeho, ještě za života jeho, řka: Kterak vy radíte, jakou odpověd mám dáti lidu tomu?'),
(1557595,54,14,10,7,'I odpověděli jemu, řkouce: Jestliže se dobrotivě ukážeš lidu tomuto a povolíš jim, a mluviti budeš přívětivě, budou služebníci tvoji po všecky dny.'),
(1557596,54,14,10,8,'Ale on opustil radu starců, kterouž dali jemu, a radil se s mládenci, kteříž odrostli s ním, a stávali před ním.'),
(1557597,54,14,10,9,'A řekl jim: Co vy radíte, jakou máme dáti odpověd lidu tomuto, kteříž mluvili ke mně, řkouce: Polehč břemene, kteréž vložil otec tvůj na nás?'),
(1557598,54,14,10,10,'Jemuž odpověděli mládenci, kteříž zrostli s ním, řkouce: Takto odpovíš lidu tomu, kteříž mluvili k tobě a řekli: Otec tvůj stížil jho naše, ty pak polehč nám, takto díš jim: Nejmenší prst můj tlustší jest, nežli bedra otce mého.'),
(1557599,54,14,10,11,'Nyní tedy, otec můj těžké břímě vzložil na vás, já pak přidám břemene vašeho; otec můj trestal vás bičíky, ale já biči uzlovatými.'),
(1557600,54,14,10,12,'Potom přišel Jeroboám i všecken lid k Roboámovi dne třetího, jakž byl vyřkl král, řka: Navraťte se ke mně dne třetího.'),
(1557601,54,14,10,13,'I odpověděl jim král tvrdě. Nebo opustil král Roboám radu starců,'),
(1557602,54,14,10,14,'A mluvil k nim vedlé rady mládenců, řka: Otec můj stížil jho vaše, já pak k němu přidám; otec můj trestal vás bičíky, ale já biči uzlovatými.'),
(1557603,54,14,10,15,'A tak neuposlechl král lidu. (Příčina zajisté byla od Boha, aby naplnil Hospodin řeč svou, kterouž mluvil skrze Achiáše Silonského k Jeroboámovi synu Nebatovu.)'),
(1557604,54,14,10,16,'Protož vida všecken Izrael, že by je král oslyšel, odpověděl lid králi, řkouce: Jakýž máme díl v Davidovi? Ani dědictví nemáme v synu Izai. Jeden každý k stanům svým, ó Izraeli! Nyní opatř dům svůj, Davide. Odšel tedy všecken Izrael k stanům svým,'),
(1557605,54,14,10,17,'Tak že nad syny Izraelskými toliko, kteříž bydlili v městech Judských, kraloval Roboám.'),
(1557606,54,14,10,18,'A když poslal král Roboám Adurama, kterýž byl nad platy, uházeli ho synové Izraelští kamením až do smrti, čímž král Roboám přinucen byl, aby vsedna na vůz, utekl do Jeruzaléma.'),
(1557607,54,14,10,19,'A tak odstoupili synové Izraelští od domu Davidova až do dnešního dne.'),
(1557608,54,14,11,1,'Když pak přijel Roboám do Jeruzaléma, shromáždil dům Judův a Beniaminův, sto a osmdesáte tisíc výborných bojovníků, aby bojovali proti Izraelovi, a aby zase obráceno bylo království k Roboámovi.'),
(1557609,54,14,11,2,'Tedy stala se řeč Hospodinova k Semaiášovi, muži Božímu, řkoucí:'),
(1557610,54,14,11,3,'Pověz Roboámovi synu Šalomounovu, králi Judskému, a všemu lidu Izraelskému, kterýž jest v pokolení Judově a Beniaminově, řka:'),
(1557611,54,14,11,4,'Takto praví Hospodin: Netáhněte a nebojujte proti bratřím svým, navraťte se jeden každý do domu svého; nebo ode mne stala se věc tato. I uposlechli rozkazu Hospodinova, a navrátili se, aby netáhli proti Jeroboámovi.'),
(1557612,54,14,11,5,'I bydlil Roboám v Jeruzalémě, a vzdělal města hrazená v Judstvu.'),
(1557613,54,14,11,6,'A vzdělal Betlém, Etam. a Tekoe,'),
(1557614,54,14,11,7,'Betsur, Socho a Adulam,'),
(1557615,54,14,11,8,'Gát, Maresa a Zif,'),
(1557616,54,14,11,9,'Adoraim, Lachis a Azeka,'),
(1557617,54,14,11,10,'Zaraha, Aialon a Hebron, kteráž byla v pokolení Judově a Beniaminově města hrazená.'),
(1557618,54,14,11,11,'A když upevnil města hrazená, osadil v nich knížata, a zdělal špižírny k potravám, k oleji a vínu.'),
(1557619,54,14,11,12,'A v jednom každém městě složil štíty a kopí, a opatřil ta města velmi dobře, a tak kraloval nad Judou a Beniaminem.'),
(1557620,54,14,11,13,'Kněží také a Levítové, kteříž byli ve všem Izraeli, postavili se k němu ze všech končin svých.'),
(1557621,54,14,11,14,'Opustili byli zajisté Levítové předměstí svá i vládařství svá, a odebrali se do Judstva a do Jeruzaléma, (proto, že je zavrhl Jeroboám a synové jeho, aby v úřadu kněžském nesloužili Hospodinu.'),
(1557622,54,14,11,15,'A nařídil sobě kněží k sloužení po výsostech ďáblům a telatům, kterýchž byl nadělal).'),
(1557623,54,14,11,16,'A za nimi ze všech pokolení Izraelských ti, kteříž oddali srdce své k hledání Hospodina Boha Izraelského, přišli do Jeruzaléma, aby obětovali Hospodinu Bohu otců svých.'),
(1557624,54,14,11,17,'A tak utvrdili království Judské, a zsilili Roboáma syna Šalomounova za tři léta, a po ta tři léta chodili po cestě Davidově a Šalomounově.'),
(1557625,54,14,11,18,'Potom pojal sobě Roboám ženu, Mahalat, dceru Jerimota syna Davidova, a Abichail, dceru Eliaba syna Izai.'),
(1557626,54,14,11,19,'Kteráž mu zplodila syny: Jeusa a Semariáše a Zahama.'),
(1557627,54,14,11,20,'A po té pojal Maachu dceru Absolonovu, kteráž mu porodila Abiáše, Attaie, Zizu a Selomita.'),
(1557628,54,14,11,21,'Ale miloval Roboám Maachu dceru Absolonovu, nade všecky ženy i ženiny své; nebo byl pojal žen osmnáct, a ženin šedesát, a zplodil dvadceti a osm synů a šedesáte dcer.'),
(1557629,54,14,11,22,'Ustanovil pak Roboám Abiáše syna Maachy za kníže a vývodu mezi bratřími jeho; nebo myslil ho ustanoviti králem.'),
(1557630,54,14,11,23,'A opatrnosti užívaje, rozsadil všecky jiné syny své po všech krajích Judových a Beniaminových, ve všech městech ohrazených, i dal jim potravy hojně, a nabral jim mnoho žen.'),
(1557631,54,14,12,1,'I stalo se, když utvrdil království Roboám a zmocnil je, opustil zákon Hospodinův, i všecken Izrael s ním.'),
(1557632,54,14,12,2,'Stalo se, pravím, léta pátého království Roboámova, že vytáhl Sesák král Egyptský proti Jeruzalému, (nebo byli zhřešili proti Hospodinu),'),
(1557633,54,14,12,3,'S tisícem a dvěma sty vozů, a s šedesáti tisíci jízdných, a nebylo počtu lidu, kterýž přitáhl s ním z Egypta, Lubimských, Sukkimských a Chussimských.'),
(1557634,54,14,12,4,'A pobral města hrazená, kteráž byla v Judstvu, a přitáhl až k Jeruzalému.'),
(1557635,54,14,12,5,'Tedy Semaiáš prorok přišel k Roboámovi a k knížatům Judským, kteříž se byli sebrali do Jeruzaléma, bojíce se Sesáka, a řekl jim: Toto praví Hospodin: Vy jste mne opustili, i já také opouštím vás v rukou Sesákových.'),
(1557636,54,14,12,6,'I ponížili se knížata Izraelská i král, a řekli: Spravedlivýť jest Hospodin.'),
(1557637,54,14,12,7,'A když viděl Hospodin, že se ponížili, stalo se slovo Hospodinovo k Semaiášovi, řkoucí: Ponížiliť jsou se, neshladím jich, ale dám jim tudíž vysvobození, aniž se vyleje prchlivost má na Jeruzalém skrze Sesáka.'),
(1557638,54,14,12,8,'A však sloužiti jemu budou, aby zkusili, co jest to mně sloužiti, a sloužiti králům zemským.'),
(1557639,54,14,12,9,'A tak vstoupiv Sesák král Egytský do Jeruzaléma, pobral poklady domu Hospodinova, i poklady domu královského, všecko to pobral. Vzal i pavézy zlaté, kterýchž byl nadělal Šalomoun.'),
(1557640,54,14,12,10,'I nadělal král Roboám místo nich pavéz měděných, a poručil je úředníkům nad drabanty, kteříž ostříhali brány domu královského.'),
(1557641,54,14,12,11,'A když král chodíval do domu Hospodinova, přicházívali drabanti a nosili je; potom též zase přinášeli je do pokoje drabantů.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557642,54,14,12,12,'Když se pak ponížil, odvrátila se od něho prchlivost Hospodinova, a neshladil ho do cela, tak jakož se k Judovi v dobrých věcech ohlašoval.'),
(1557643,54,14,12,13,'Tedy zmocnil se král Roboám v Jeruzalémě a kraloval; nebo ve čtyřidcíti a v jednom létě byl Roboám, když počal kralovati, a sedmnácte let kraloval v Jeruzalémě, městě, kteréž vyvolil Hospodin ze všech pokolení Izraelských, aby tam přebývalo jméno jeho. Jméno matky jeho bylo Naama Ammonitská.'),
(1557644,54,14,12,14,'Kterýž činil zlé věci; nebo neustavil srdce svého, aby hledal Hospodina.'),
(1557645,54,14,12,15,'Věci pak Roboámovy, první i poslední, zdaž zapsány nejsou v knihách Semaiáše proroka, a Iddo proroka, kdež se vyčítá pořádek rodů, ano i války mezi Roboámem a Jeroboámem, po všecky dny?'),
(1557646,54,14,12,16,'I usnul Roboám s otci svými, a pochován jest v městě Davidově, a kraloval Abiáš syn jeho místo něho.'),
(1557647,54,14,13,1,'Léta osmnáctého krále Jeroboáma kraloval Abiáš nad Judou.'),
(1557648,54,14,13,2,'Tři léta kraloval v Jeruzalémě, (a jméno matky jeho Michaia, dcera Urielova z Gabaa), a byla válka mezi Abiášem a Jeroboámem.'),
(1557649,54,14,13,3,'Pročež sšikoval Abiáš vojsko udatných bojovníků, čtyřikrát sto tisíc mužů výborných, Jeroboám pak sšikoval se proti němu, maje osmkrát sto tisíc mužů výborných, velmi udatných.'),
(1557650,54,14,13,4,'I postavil se Abiáš na vrchu hory Semaraim, kteráž byla mezi horami Efraimskými, a řekl: Slyšte mne, Jeroboáme i všecken Izraeli.'),
(1557651,54,14,13,5,'Zdaliž jste neměli věděti, že Hospodin Bůh Izraelský dal království Davidovi nad Izraelem na věky, jemu i synům jeho smlouvou trvánlivou?'),
(1557652,54,14,13,6,'Ale povstal Jeroboám syn Nebatův, služebník Šalomouna syna Davidova, a zprotivil se pánu svému.'),
(1557653,54,14,13,7,'A sebrali se k němu lidé nevážní a bezbožní a zsilili se proti Roboámovi synu Šalomounovu, Roboám pak byv dítě a srdce choulostivého, neodepřel jim zmužile.'),
(1557654,54,14,13,8,'Tak vy nyní myslíte zsiliti se proti království Hospodinovu, kteréž jest v ruce synů Davidových, a jest vás veliké množství; máte také při sobě telata zlatá, kterýchž vám nadělal Jeroboám, za bohy.'),
(1557655,54,14,13,9,'Zdaliž jste nezavrhli kněží Hospodinových, synů Aronových a Levítů, a nadělali jste sobě kněží, tak jako národové jiných zemí? Kdožkoli přichází, aby posvěceny byly ruce jeho volčetem mladým a sedmi skopci, hned je knězem těch, jenž nejsou bohové.'),
(1557656,54,14,13,10,'Ale my jsme Hospodina Boha našeho, aniž jsme se ho spustili, kněží pak přisluhující Hospodinu jsou synové Aronovi a Levítové, kteříž konají práci svou,'),
(1557657,54,14,13,11,'A pálí Hospodinu zápaly každého jitra a každého večera, kadí také vonnými věcmi, zpořádaní také chlebů na stole čistém, a svícen zlatý s lampami jeho spravují, aby hořely každého večera. A tak my ostříháme nařízení Hospodina Boha svého, ale vy strhli jste se jeho.'),
(1557658,54,14,13,12,'Protož aj, s námi jest Bůh vůdce náš, a kněží jeho a trouby zvučné, aby zněly proti vám. Synové Izraelští, nebojujte s Hospodinem Bohem otců svých, nebo nepovede se vám šťastně.'),
(1557659,54,14,13,13,'Mezi tím Jeroboám obvedl zálohy, aby po zadu na ně připadli, a tak byli Izraelští před Judskými, a zálohy ty byly jim pozadu.'),
(1557660,54,14,13,14,'Tedy spatřiv Juda, an válka jim s předu i s zadu, zvolali k Hospodinu, a kněží troubili v trouby.'),
(1557661,54,14,13,15,'Učinili také pokřik muži Judští. I stalo se v tom pokřiku mužů Judských, ranil Bůh Jeroboáma i všecken Izrael před Abiášem a Judou.'),
(1557662,54,14,13,16,'A tak utíkali synové Izraelští před Judou, ale dal je Bůh v ruku jejich.'),
(1557663,54,14,13,17,'Nebo porazili je Abiáš a lid jeho ranou velikou, tak že padlo zbitých z Izraele pětkrát sto tisíc mužů výborných.'),
(1557664,54,14,13,18,'Protož sníženi jsou synové Izraelští v ten čas, a zmocnili se synové Judovi, nebo zpolehli na Hospodina Boha otců svých.'),
(1557665,54,14,13,19,'I honil Abiáš Jeroboáma, a vzal mu města, Bethel i vsi jeho, Jesana i vsi jeho, a Efron i vsi jeho.'),
(1557666,54,14,13,20,'Aniž se mohl zase zsiliti více Jeroboám po všecky dny Abiášovy. I ranil jej Hospodin, tak že umřel.'),
(1557667,54,14,13,21,'Ale Abiáš zmocnil se, kterýž byl sobě pojal žen čtrnáct, a zplodil dvamecítma synů a šestnácte dcer.'),
(1557668,54,14,13,22,'Ostatek pak činů Abiášových, a života jeho i řečí jeho, sepsáno jest v knize proroka Iddo.'),
(1557669,54,14,14,1,'Když pak usnul Abiáš s otci svými, a pochovali jej v městě Davidově, kraloval Aza syn jeho místo něho. Za jeho dnů v pokoji byla země deset let.'),
(1557670,54,14,14,2,'I činil Aza to, což se dobře líbilo Hospodinu Bohu jeho.'),
(1557671,54,14,14,3,'Nebo zbořil oltáře cizí i výsosti, a stroskotal obrazy jejich, a posekal háje jejich.'),
(1557672,54,14,14,4,'A přikázal Judovi, aby hledali Hospodina Boha otců svých, a ostříhali zákona a přikázaní jeho.'),
(1557673,54,14,14,5,'Zkazil, pravím, po všech městech Judských výsosti a slunečné obrazy, a bylo v pokoji království za času jeho.'),
(1557674,54,14,14,6,'Zatím vzdělal města hrazená v Judstvu, proto že v pokoji byla země, aniž jaká proti němu válka povstala těch let; nebo Hospodin dal jemu odpočinutí.'),
(1557675,54,14,14,7,'I řekl lidu Judskému: Vzdělejme ta města, a ohraďme je zdmi a věžemi, branami i závorami, dokudž země jest v moci naší. Aj, že jsme hledali Hospodina Boha svého, hledali jsme ho, a dal nám odpočinutí odevšad. A tak stavěli a šťastně se jim zvedlo.'),
(1557676,54,14,14,8,'Měl pak Aza vojsko těch, kteříž nosili štíty a kopí, z pokolení Judova třikrát sto tisíců, a z Beniaminova pavézníků a střelců dvě stě a osmdesáte tisíců. Všickni ti byli muži udatní.'),
(1557677,54,14,14,9,'I vytáhl proti nim Zerach Mouřenín, maje v vojště desetkrát sto tisíců, a vozů tři sta, a přitáhl až k Maresa.'),
(1557678,54,14,14,10,'Vytáhl též i Aza proti němu. I sšikovali vojska v údolí Sefata u Maresa.'),
(1557679,54,14,14,11,'Tedy volal Aza k Hospodinu Bohu svému, a řekl: Hospodine, neníť potřebí tobě velikého množství, když ty chceš pomoci mdlejším. Pomoziž nám, Hospodine Bože náš, neboť v tebe doufáme, a ve jménu tvém jdeme proti množství tomuto. Hospodine, ty jsi Bůh náš; nechť nemá moci proti tobě bídný člověk.'),
(1557680,54,14,14,12,'I ranil Hospodin Mouřeníny před Azou a před lidem Judským, tak že utíkali Mouřenínové.'),
(1557681,54,14,14,13,'A honil je Aza i lid, kterýž byl s ním, až do Gerar. I padli Mouřenínové, že se nijakž otaviti nemohli; nebo potříni jsou před Hospodinem a před vojskem jeho. I odnesli onino kořistí velmi mnoho.'),
(1557682,54,14,14,14,'Pohubili také všecka města vůkol Gerar; strach zajisté Hospodinův připadl na ně. I vzebrali všecka města; nebo mnoho kořistí v nich bylo.'),
(1557683,54,14,14,15,'Též i obyvatele v staních při dobytcích zbili, a zajavše ovec velmi mnoho a velbloudů, navrátili se do Jeruzaléma.'),
(1557684,54,14,15,1,'Tehdy na Azariáše syna Odedova sstoupil duch Boží.'),
(1557685,54,14,15,2,'Pročež vyšed vstříc Azovi, řekl jemu: Slyšte mne, Azo i všecko pokolení Judovo a Beniaminovo. Hospodin byl s vámi, dokudž jste byli s ním, a budete-li ho hledati, najdete ho; pakli ho opustíte, opustíť vás.'),
(1557686,54,14,15,3,'Po mnohé zajisté dny Izrael jest bez pravého Boha a bez kněží, učitelů i bez zákona,'),
(1557687,54,14,15,4,'Ješto, kdyby se v úzkosti své k Hospodinu Bohu Izraelskému byli obrátili a hledali ho, byliť by ho nalezli.'),
(1557688,54,14,15,5,'Ale časů těchto není bezpečno vycházeti ani vcházeti; nebo nepokoj veliký jest mezi všemi obyvateli země,'),
(1557689,54,14,15,6,'Tak že šlapá národ po národu, a město po městu, proto že Bůh kormoutí je všelijakými úzkostmi.'),
(1557690,54,14,15,7,'Protož vy posilňte se, a neopouštějte rukou svých; nebo má mzdu práce vaše.'),
(1557691,54,14,15,8,'A když slyšel Aza slova ta a proroctví Odeda proroka, posilil se, a vyplénil ohavnosti ze vší země Judské a Beniaminské, i z měst, kteráž byl vzal na hoře Efraim, a obnovil oltář Hospodinův, kterýž byl před síní Hospodinovou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557692,54,14,15,9,'Potom shromáždil všecko pokolení Judovo i Beniaminovo, a příchozí s nimi z Efraima, Manassesa a Simeona; nebo jich bylo uteklo k němu z lidu Izraelského velmi mnoho, vidouce, že Hospodin Bůh jeho jest s ním.'),
(1557693,54,14,15,10,'I sebrali se do Jeruzaléma třetího měsíce, patnáctého léta kralování Azova,'),
(1557694,54,14,15,11,'A obětovali Hospodinu v ten den z kořistí přihnaných, volů sedm set a ovcí sedm tisíc.'),
(1557695,54,14,15,12,'A vešli v smlouvu, aby hledali Hospodina Boha otců svých, z celého srdce svého a ze vší duše své,'),
(1557696,54,14,15,13,'A kdož by koli nehledal Hospodina Boha Izraelského, aby byl usmrcen, buď malý neb veliký, buď muž neb žena.'),
(1557697,54,14,15,14,'I přisáhli Hospodinu hlasem velikým, s zvukem na trouby i na pozouny.'),
(1557698,54,14,15,15,'Všecken zajisté lid Judský radoval se z přísahy té; nebo celým srdcem svým přisáhli, a se vší ochotností hledali ho, a nalezli jej. I dal jim odpočinutí Hospodin se všech stran.'),
(1557699,54,14,15,16,'Nadto i Maachu matku ssadil Aza král, aby nebyla královnou, proto že byla vzdělala v háji hroznou modlu. I podťal Aza modlu tu hroznou, a zdrobil i spálil ji při potoku Cedron.'),
(1557700,54,14,15,17,'Ačkoli výsosti nebyly zkaženy v lidu Izraelském, srdce však Azovo bylo celé po všecky dny jeho.'),
(1557701,54,14,15,18,'Vnesl také ty věci, kteréž posvěceny byly od otce jeho, i to, čehož sám posvětil, do domu Božího, stříbro, zlato i nádoby.'),
(1557702,54,14,15,19,'A nebylo války až do léta třidcátého pátého kralování Azova.'),
(1557703,54,14,16,1,'Léta třidcátého šestého kralování Azova vytáhl Báza král Izraelský proti Judovi, a stavěl Ráma, aby nedal vyjíti ani jíti k Azovi králi Judskému.'),
(1557704,54,14,16,2,'Tedy vzav Aza stříbro i zlato z pokladů domu Hospodinova i domu královského, poslal k Benadadovi králi Syrskému, kterýž bydlil v Damašku, řka:'),
(1557705,54,14,16,3,'Smlouva jest mezi mnou a mezi tebou, mezi otcem mým a mezi otcem tvým. Aj, posílámť teď stříbro a zlato, jdi, zruš smlouvu svou s Bázou králem Izraelským, ať odtrhne ode mne.'),
(1557706,54,14,16,4,'I uposlechl Benadad krále Azy, a poslal knížata s vojsky svými proti městům Izraelským. I dobyli Jon a Dan, též Abelmaim i všech měst Neftalímových, v nichž měli sklady.'),
(1557707,54,14,16,5,'To když uslyšel Báza, přestal stavěti Ráma, a zanechal díla svého.'),
(1557708,54,14,16,6,'V tom Aza král pojal všecken lid Judský, a pobrali kamení z Ráma i dříví, z něhož stavěl Báza, a vystavěl z něho Gabaa a Masfa.'),
(1557709,54,14,16,7,'V ten pak čas přišel Chanani prorok k Azovi králi Judskému, a řekl jemu: Že jsi zpolehl na krále Syrského, a nezpolehl jsi na Hospodina Boha svého, proto ušlo vojsko krále Syrského z ruky tvé.'),
(1557710,54,14,16,8,'Zdaliž jsou Chussimští a Lubimští neměli vojsk velmi velikých, s vozy a jezdci náramně mnohými? A když jsi zpolehl na Hospodina, vydal je v ruku tvou.'),
(1557711,54,14,16,9,'Oči zajisté Hospodinovy spatřují všecku zemi, aby dokazoval síly své při těch, kteříž jsou k němu srdce upřímého. Bláznivě jsi učinil v té věci, protož od toho času budou proti tobě války.'),
(1557712,54,14,16,10,'Tedy rozhněvav se Aza na proroka, dal ho do vězení; nebo se byl rozhněval na něj pro tu věc. A utiskal Aza některé z lidu toho času.'),
(1557713,54,14,16,11,'O jiných pak věcech Azových, prvních i posledních, zapsáno jest v knize o králích Judských a Izraelských.'),
(1557714,54,14,16,12,'Potom léta třidcátého devátého kralování svého nemocen byl Aza na nohy své těžkou nemocí, a však v nemoci své nehledal Boha, ale lékařů.'),
(1557715,54,14,16,13,'A tak usnul Aza s otci svými, a umřel léta čtyřidcátého prvního kralování svého.'),
(1557716,54,14,16,14,'A pochovali jej v hrobě jeho, kterýž byl vytesal sobě v městě Davidově, a položili ho na lůžku, kteréž byl naplnil vonnými věcmi a mastmi dílem apatykářským připravenými. I pálili to jemu ohněm velmi velikým.'),
(1557717,54,14,17,1,'I kraloval Jozafat syn jeho místo něho, a zmocnil se Izraele.'),
(1557718,54,14,17,2,'I osadil lidem válečným všecka města hrazená v Judstvu, a postavil stráž v zemi Judské a v městech Efraim, kteráž byl zdobýval Aza otec jeho.'),
(1557719,54,14,17,3,'A byl Hospodin s Jozafatem; nebo chodil po cestách Davida otce svého prvních, aniž hledal modl.'),
(1557720,54,14,17,4,'Ale Boha otce svého hledal, a v přikázaních jeho chodil, aniž následoval skutků lidu Izraelského.'),
(1557721,54,14,17,5,'I utvrdil Hospodin království v ruce jeho, a dal všecken lid Judský dary Jozafatovi, tak že měl bohatství a slávy hojně.'),
(1557722,54,14,17,6,'A nabyv udatného srdce k cestám Hospodinovým, zkazil přesto také i výsosti a háje v Judstvu.'),
(1557723,54,14,17,7,'Léta pak třetího království svého poslal knížata svá: Benchaile, Abdiáše, Zachariáše, Natanaele a Micheáše, aby učili v městech Judských.'),
(1557724,54,14,17,8,'A s nimi Levíty: Semaiáše, Netaniáše, Zebadiáše, Azaele, Semiramota, Jonatana, Adoniáše, Tobiáše a Tobadoniáše, Levíty, a s nimi Elisama a Jehorama, kněží,'),
(1557725,54,14,17,9,'Kteříž učili v Judstvu, majíce s sebou knihu zákona Hospodinova. Chodili pak vůkol po všech městech Judských, vyučujíce lid.'),
(1557726,54,14,17,10,'I byl strach Hospodinův na všech královstvích zemí, kteréž byly vůkol Judstva, tak že nebojovali proti Jozafatovi.'),
(1557727,54,14,17,11,'Nýbrž i Filistinští přinášeli Jozafatovi dary a berni uloženou. Arabští také přiháněli jemu dobytky, skopců po sedmi tisících a sedmi stech, též kozlů po sedmi tisících a sedmi stech.'),
(1557728,54,14,17,12,'I prospíval Jozafat, a rostl až na nejvyšší, a vystavěl v Judstvu zámky a města k skladům.'),
(1557729,54,14,17,13,'A práci mnohou vedl při městech Judských, muže pak válečné a slovoutné měl v Jeruzalémě.'),
(1557730,54,14,17,14,'A tento jest počet jich po domích otců jejich: Z Judy knížata nad tisíci: Adna kníže, a s ním udatných rytířů třikrát sto tisíc.'),
(1557731,54,14,17,15,'A po něm Jochanan kníže, a s ním dvě stě a osmdesát tisíc.'),
(1557732,54,14,17,16,'Po něm Amaziáš syn Zichrův, kterýž se dobrovolně byl oddal Hospodinu, a při něm dvakrát sto tisíc mužů udatných.'),
(1557733,54,14,17,17,'Z Beniamina pak muž udatný Eliada, a s ním lidu zbrojného s lučišti a pavézami dvakrát sto tisíc.'),
(1557734,54,14,17,18,'A po něm Jozabad, a s ním sto a osmdesát tisíc způsobných k boji.'),
(1557735,54,14,17,19,'Ti sloužili králi, kromě těch, kteréž byl osadil král po městech hrazených po všem Judstvu.'),
(1557736,54,14,18,1,'I měl Jozafat bohatství a slávu velmi velikou, a spříznil se s Achabem.'),
(1557737,54,14,18,2,'Přijel pak po letech k Achabovi do Samaří, a nabil Achab ovcí a volů hojně pro něj a pro lid, kterýž byl s ním, a namlouval ho, aby táhl do Rámot Galád.'),
(1557738,54,14,18,3,'Nebo řekl Achab král Izraelský Jozafatovi králi Judskému: Potáhneš-li se mnou do Rámot Galád? Odpověděl jemu: Jakž jsem já, tak jsi ty, jako lid tvůj, tak lid můj, a s tebouť budu v tom boji.'),
(1557739,54,14,18,4,'Řekl také Jozafat králi Izraelskému: Vzeptej se medle dnes na slovo Hospodinovo.'),
(1557740,54,14,18,5,'I shromáždil král Izraelský proroků svých čtyři sta mužů, a řekl jim: Máme-li jeti do Rámot Galád na vojnu, čili tak nechati? I řekli: Táhni, nebo dá je Bůh v ruku královu.'),
(1557741,54,14,18,6,'Tedy řekl Jozafat: Což již není zde proroka Hospodinova žádného, abychom se ho zeptali?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557742,54,14,18,7,'Odpověděl král Izraelský Jozafatovi: Ještěť jest muž jeden, skrze něhož bys se mohl poraditi s Hospodinem, ale já ho nenávidím, proto že mi nikdy nic dobrého neprorokuje, ale vždycky zlé. Ten jest Micheáš syn Jemlův. Ale Jozafat řekl: Nechť tak nemluví král.'),
(1557743,54,14,18,8,'Protož povolav král Izraelský komorníka jednoho, řekl: Přiveď sem rychle Micheáše syna Jemlova.'),
(1557744,54,14,18,9,'(Mezi tím král Izraelský a Jozafat král Judský seděli jeden každý na stolici své, odíni jsouce rouchem. Seděli pak v placu u vrat brány Samařské, a všickni proroci prorokovali před nimi.'),
(1557745,54,14,18,10,'Kdežto Sedechiáš syn Kenanův udělal sobě byl i rohy železné, a řekl: Takto praví Hospodin: Těmito trkati budeš Syrské, dokudž jich nepohubíš.'),
(1557746,54,14,18,11,'Tak podobně všickni proroci prorokovali, řkouce: Jeď do Rámot Galád, a šťastněť se povede; nebo dá je Hospodin v ruku královu.)'),
(1557747,54,14,18,12,'V tom posel ten, kterýž šel, aby zavolal Micheáše, mluvil jemu, řka: Aj, řeči proroků těch jednostejné jsou a dobré před králem. Medle, buď řeč tvá, jako řeč kterého z nich, a mluv dobré věci.'),
(1557748,54,14,18,13,'Jemuž řekl Micheáš: Živť jest Hospodin, že cožkoli vyřkne Bůh můj, to mluviti budu.'),
(1557749,54,14,18,14,'A když přišel k králi, řekl jemu král: Micheáši, máme-li jeti proti Rámot Galád na vojnu, čili tak nechati? Kterýž řekl: Táhněte a šťastněť se vám povede, i budou dáni v ruku vaši.'),
(1557750,54,14,18,15,'Ještě řekl jemu král: I kolikrátž tě mám přísahou zavazovati, abys mi nemluvil než pravdu ve jménu Hospodinovu?'),
(1557751,54,14,18,16,'Protož řekl: Viděl jsem všecken lid Izraelský rozptýlený po horách jako ovce, kteréž nemají pastýře; nebo řekl Hospodin: Nemají pána tito, navrať se jeden každý do domu svého v pokoji.'),
(1557752,54,14,18,17,'I řekl král Izraelský Jozafatovi: Zdaližť jsem neřekl, že mi nebude prorokovati nic dobrého, ale zlé?'),
(1557753,54,14,18,18,'Řekl dále: Protož slyšte slovo Hospodinovo: Viděl jsem Hospodina sedícího na trůnu svém, a všecko vojsko nebeské stojící po pravici jeho i po levici jeho.'),
(1557754,54,14,18,19,'I řekl Hospodin: Kdo oklamá Achaba krále Izraelského, aby vytáhl a padl u Rámot Galád? A když pravil ten toto, a jiný pravil jiné,'),
(1557755,54,14,18,20,'Tožť vyšel duch, a postaviv se před Hospodinem, řekl: Já ho oklamám. Hospodin pak řekl jemu: Jakým způsobem?'),
(1557756,54,14,18,21,'Odpověděl: Vyjdu a budu duchem lživým v ústech všech proroků jeho. Kterýžto řekl: Oklamáš a dovedeš toho; jdiž a učiň tak.'),
(1557757,54,14,18,22,'Protož aj, jižtě dal Hospodin ducha lživého v ústa proroků tvých těchto, ješto však Hospodin mluvil zlé proti tobě.'),
(1557758,54,14,18,23,'Tedy přistoupiv Sedechiáš syn Kenanův, dal políček Micheášovi a řekl: Kterouž jest cestou odšel duch Hospodinův ode mne, aby mluvil tobě?'),
(1557759,54,14,18,24,'Odpověděl Micheáš: Aj, uzříš v ten den, když vejdeš do nejtajnějšího pokoje, abys se skryl.'),
(1557760,54,14,18,25,'I řekl král Izraelský: Jměte Micheáše, a doveďte ho k Amonovi hejtmanu města, a k Joasovi synu královu.'),
(1557761,54,14,18,26,'A díte: Takto praví král: Dejte tohoto do žaláře a dávejte mu jísti maličko chleba a maličko vody, dokudž se nenavrátím v pokoji.'),
(1557762,54,14,18,27,'Ale Micháš řekl: Jestliže se ty navrátíš v pokoji, tedyť nemluvil Hospodin skrze mne. Přesto řekl: Slyštež to všickni lidé.'),
(1557763,54,14,18,28,'A tak táhl král Izraelský a Jozafat král Judský proti Rámot Galád.'),
(1557764,54,14,18,29,'I řekl král Izraelský Jozafatovi: Změním já se, když půjdu k bitvě, ale ty oblec se v roucho své. I změnil se král Izraelský, a jeli k bitvě.'),
(1557765,54,14,18,30,'Král pak Syrský přikázal byl hejtmanům nad vozy svými, řka: Nebojujte proti malému ani proti velikému, než proti samému králi Izraelskému.'),
(1557766,54,14,18,31,'I stalo se, když hejtmané nad vozy uzřeli Jozafata, řekli: Král Izraelský jest. Takž se obrátili proti němu, aby bojovali. Tedy zkřikl Jozafat, a Hospodin spomohl jemu, a odvrátil je Bůh od něho.'),
(1557767,54,14,18,32,'Nebo uzřevše hejtmané nad vozy, že on není král Izraelský, obrátili se od něho.'),
(1557768,54,14,18,33,'Muž pak střelil z lučiště náhodou, a postřelil krále Izraelského, kdež se pancíř spojuje. Pročež řekl vozkovi: Obrať se, a vyvez mne z vojska; nebo jsem nemocen.'),
(1557769,54,14,18,34,'I rozmohla se bitva v ten den. Král pak Izraelský stál na voze proti Syrským až do večera, i umřel v západ slunce.'),
(1557770,54,14,19,1,'Když se pak navracoval Jozafat král Judský do domu svého v pokoji do Jeruzaléma,'),
(1557771,54,14,19,2,'Vyšel jemu vstříc Jéhu syn Chananův, prorok, a řekl králi Jozafatovi: Zdaliž jsi bezbožnému měl pomáhati, a ty, jenž nenávidí Hospodina, milovati? Z té příčiny proti tobě jest hněv Hospodinův.'),
(1557772,54,14,19,3,'Ale však nalezly se věci dobré při tobě, že jsi vysekal háje z země, a nastrojil srdce své, abys hledal Boha.'),
(1557773,54,14,19,4,'I bydlil Jozafat v Jeruzalémě, a zase projel lid od Bersabé až k hoře Efraim, a navrátil je k Hospodinu Bohu otců jejich.'),
(1557774,54,14,19,5,'A ustanovil soudce v zemi po všech městech Judských hrazených, v jednom každém městě.'),
(1557775,54,14,19,6,'Tedy řekl soudcům: Vizte, jak co činíte; nebo nevedete soudu za člověka, ale za Hospodina, kterýž vám přítomen jest při vykonávání soudu.'),
(1557776,54,14,19,7,'A protož budiž bázeň Hospodinova při vás. Ostříhejte toho a čiňte tak, neboť není u Hospodina Boha našeho nepravosti, tak aby šetřiti měl osob, aneb přijímati dary.'),
(1557777,54,14,19,8,'Tak i v Jeruzalémě ustanovil Jozafat některé z Levítů a z kněží, a z knížat otcovských, čeledí Izraelských, k soudu Hospodinovu a k rozepřem těch, kteříž by se obraceli o to do Jeruzaléma.'),
(1557778,54,14,19,9,'A přikázal jim, řka: Takž dělejte v bázni Hospodinově, u víře a v srdci upřímém.'),
(1557779,54,14,19,10,'A při všeliké rozepři, kteráž by přišla před vás od bratří vašich, kteříž bydlí v městech svých, buď mezi krví a krví, mezi zákonem a přikázaním, ustanoveními a soudy, napomenete jich, aby nehřešili proti Hospodinu, tak aby nepřišla prchlivost na vás, ani na bratří vaše. Tak čiňte, a neuběhnete v hřích.'),
(1557780,54,14,19,11,'A aj, Amariáš, kněz nejvyšší, mezi vámi bude ve všech věcech Hospodinových, a Zebadiáš syn Izmaelův, vývoda domu Judova, ve všeliké věci královské. Máte také Levíty správce mezi sebou; posilňtež se a zmužile sobě počínejte, a budeť Hospodin s tím, kdož bude dobrý.'),
(1557781,54,14,20,1,'I stalo se potom, že přitáhli synové Moáb a synové Ammon, a s nimi někteří od Ammonitských, proti Jozafatovi na vojnu.'),
(1557782,54,14,20,2,'A přišedše, oznámili Jozafatovi, řkouce: Přitáhlo proti tobě množství veliké z zámoří, z země Syrské, a aj, jsou v Hasesontamar, jenž jest Engadi.'),
(1557783,54,14,20,3,'I ulekl se, a obrátil Jozafat tvář svou k hledání Hospodina, a vyhlásil půst všemu lidu Judskému.'),
(1557784,54,14,20,4,'A tak shromáždil se lid Judský, aby hledali Hospodina. Také i ze všech měst Judských sešli se hledati Hospodina.'),
(1557785,54,14,20,5,'Tedy stál Jozafat v shromáždění Judském a Jeruzalémském, v domě Hospodinově před síní novou,'),
(1557786,54,14,20,6,'A řekl: Hospodine, Bože otců našich, zdaliž ty sám nejsi Bohem na nebi? Zdaliž ty nepanuješ nade všemi královstvími národů? Zdaliž v ruce tvé není síly a moci, tak že není, kdo by se mohl postaviti proti tobě?'),
(1557787,54,14,20,7,'Zdaliž jsi ty, Bože náš, nevyhnal obyvatelů země této před tváří lidu svého Izraelského, a dal jsi ji semeni Abrahama, milovníka svého na věky?'),
(1557788,54,14,20,8,'Kteřížto bydlili v ní, a vzdělali tobě v ní svatyni, jménu tvému, řkouce:'),
(1557789,54,14,20,9,'Jestliže by na nás přišly zlé věci, meč pomsty, buď morová rána, buď hlad, postavíme se před tímto domem a před tebou, (poněvadž jméno tvé jest v domě tomto), a budeme volati k tobě v úzkostech svých, i vyslyšíš a vysvobodíš.'),
(1557790,54,14,20,10,'A nyní, aj, synové Ammon a Moáb, a hora Seir, skrze něž jsi nedopustil jíti Izraelovi, když se brali z země Egyptské, ale uhnuli se od nich, a nepohubili jich,'),
(1557791,54,14,20,11,'Aj hle, oni odplacejí se nám, přitáhše, aby nás vyhnali z dědictví tvého, kteréž jsi právem dědičným dal nám.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557792,54,14,20,12,'Bože náš, zdali jich souditi nebudeš? V násť zajisté není žádné síly proti množství tomuto velikému, kteréž táhne proti nám, aniž my víme, co bychom činiti měli, toliko na tě patří oči naše.'),
(1557793,54,14,20,13,'Všecken také lid Judský stáli před Hospodinem, též i dítky jich, ženy i synové jejich.'),
(1557794,54,14,20,14,'Jachaziel pak syn Zachariáše syna Benaiášova, syna Jehielova, syna Mataniášova, Levíta z synů Azafových, nadšen jsa duchem Hospodinovým, u prostřed toho shromáždění,'),
(1557795,54,14,20,15,'Řekl: Pozorujte všecken Judo a obyvatelé Jeruzalémští, i ty králi Jozafate. Takto vám praví Hospodin: Nebojte se vy, ani se lekejte množství tohoto velikého; nebo ne váš bude boj, ale Boží.'),
(1557796,54,14,20,16,'Zítra vytáhněte proti nim, aj, oni potáhnou po stráni Ziz, a naleznete je při konci údolí naproti poušti Jeruel.'),
(1557797,54,14,20,17,'Nebudete vy bojovati tuto. Postavte se, stůjte a vizte vysvobození Hospodinovo při sobě, ó Judo a Jeruzaléme. Nebojte se, aniž se strachujte; zítra vyjděte proti nim, a Hospodin bude s vámi.'),
(1557798,54,14,20,18,'I sklonil se Jozafat tváří k zemi, a všecken lid Judský i obyvatelé Jeruzalémští padli před Hospodinem, klanějíce se Hospodinu.'),
(1557799,54,14,20,19,'Vstali pak Levítové z synů Kahat a z synů Chóre, aby chválili Hospodina Boha Izraelského hlasem velikým a vysokým.'),
(1557800,54,14,20,20,'Potom vstavše ráno, vytáhli na poušť Tekoe. A když vycházeli, stál Jozafat a řekl: Slyšte mne, Judo a obyvatelé Jeruzalémští. Věřte v Hospodina Boha svého, a stane se vám věrně; věřte prorokům jeho, a šťastně se vám povede.'),
(1557801,54,14,20,21,'A tak poradiv se s lidem, postavil zpěváky Hospodinu, aby chválili okrasu svatosti, a když by vycházeli sšikovaní k boji, aby oni napřed šli a říkali: Oslavujte Hospodina, nebo na věky milosrdenství jeho.'),
(1557802,54,14,20,22,'Tu chvíli pak, když oni začali zpěv a chválení, obrátil Hospodin ty, kteříž byli v zálohách, na syny Ammon, Moáb a obyvatele hory Seir, ješto však byli přitáhli proti Judovi, a tak sami se bili.'),
(1557803,54,14,20,23,'Nebo povstali synové Ammon a Moábští proti obyvatelům hory Seir, aby zmordovali a shladili je. A když dokonali boj proti obyvatelům hory Seir, pomáhali sobě a hubili jedni druhé.'),
(1557804,54,14,20,24,'Mezi tím lid Judský přitáhl k stráži, kteráž jest na poušti, a uzřeli to množství, a aj, mrtví leží na zemi, aniž kdo ušel.'),
(1557805,54,14,20,25,'Pročež přistoupil Jozafat s lidem svým, aby rozebrali loupeže jejich, a nalezli u nich hojnost zboží i klénotů na tělích zbitých. I rozbitovali toho mezi sebou, tak že unesti nemohli; za tři dni dělili ty loupeže, proto že jich mnoho bylo.'),
(1557806,54,14,20,26,'V den pak čtvrtý shromáždili se do údolí Beracha, a že tu dobrořečili Hospodinu, protož nazvali jméno místa toho údolí Beracha až do dnešního dne.'),
(1557807,54,14,20,27,'Zatím obrátili se všickni muži Judští a Jeruzalémští, a Jozafat před nimi, aby se navrátili do Jeruzaléma s veselím; nebo byl obveselil je Hospodin nad nepřátely jejich.'),
(1557808,54,14,20,28,'I vešli do Jeruzaléma s loutnami a harfami a s trubami do domu Hospodinova.'),
(1557809,54,14,20,29,'Tedy připadl strach Boží na všecka království zemská, když uslyšeli, že Hospodin bojoval proti nepřátelům lidu Izraelského.'),
(1557810,54,14,20,30,'A tak v pokoji bylo království Jozafatovo; nebo odpočinutí dal jemu Bůh jeho odevšad.'),
(1557811,54,14,20,31,'Kraloval pak Jozafat nad Judou. Ve třidcíti pěti letech byl, když kralovati začal, a pětmecítma let kraloval v Jeruzalémě. Jméno matky jeho Azuba, dcera Silchi.'),
(1557812,54,14,20,32,'A chodil po cestě Azy otce svého, aniž se uchýlil od ní, čině to, což pravého jest před očima Hospodinovýma.'),
(1557813,54,14,20,33,'A však výsosti nebyly zkaženy, nebo ještě lid byl nenastrojil srdce svého k Bohu otců svých.'),
(1557814,54,14,20,34,'O jiných pak věcech Jozafatových,prvních i posledních, sepsáno jest v knihách Jéhu syna Chanani, kterémuž bylo poručeno, aby to vložil do knihy o králích Izraelských.'),
(1557815,54,14,20,35,'Potom stovaryšil se Jozafat král Judský s Ochoziášem králem Izraelským, kterýž sobě bezbožně počínal.'),
(1557816,54,14,20,36,'Stovaryšil se pak s ním proto, aby nadělal lodí, kteréž by přecházely přes moře. I nadělali lodí v Aziongaber.'),
(1557817,54,14,20,37,'Protož prorokoval Eliezer syn Dodavahův z Maresa proti Jozafatovi, řka: Jakž jsi se stovaryšil s Ochoziášem, roztrhl Hospodin skutky tvé. I stroskotány jsou lodí, a tak nemohly se doplaviti přes moře.'),
(1557818,54,14,21,1,'Potom usnul Jozafat s otci svými, a pochován jest s nimi v městě Davidově. I kraloval Jehoram syn jeho místo něho.'),
(1557819,54,14,21,2,'Měl pak bratří, syny Jozafatovy, Azariáše, Jechiele, Zachariáše, Azariáše, Michaele a Sefatiáše. Všickni ti byli synové Jozafata krále Izraelského.'),
(1557820,54,14,21,3,'Kterýmž byl dal otec jejich darů mnoho, stříbra a zlata, a věcí drahých, s městy hrazenými v Judstvu, království pak dal Jehoramovi, proto že on byl prvorozený.'),
(1557821,54,14,21,4,'I uvázal se Jehoram v království otce svého, a zmocniv se, zmordoval všecky bratří své mečem, ano i některé z knížat Izraelských.'),
(1557822,54,14,21,5,'Ve dvou a třidcíti letech byl Jehoram, když počal kralovati, a osm let kraloval v Jeruzalémě.'),
(1557823,54,14,21,6,'A chodil po cestě králů Izraelských, tak jako činil dům Achabův; nebo dceru Achabovu měl za manželku, a činil zlé věci před očima Hospodinovýma.'),
(1557824,54,14,21,7,'Hospodin však nechtěl zahladiti domu Davidova, pro smlouvu, kterouž byl učinil s Davidem, a poněvadž byl řekl, že dá jemu svíci i synům jeho po všecky dny.'),
(1557825,54,14,21,8,'Ve dnech jeho odstoupili Idumejští, aby nebyli poddáni Judovi, a ustanovili nad sebou krále.'),
(1557826,54,14,21,9,'Pročež přitáhl Jehoram s knížaty svými, i se všemi vozy svými, a vstav v noci porazil Idumejské, kteříž jej byli obklíčili, i hejtmany vozů jeho.'),
(1557827,54,14,21,10,'Však předce vytáhli se Idumejští z manství Judova až do tohoto dne. Téhož času zprotivilo se i Lebno, aby nebylo pod jeho mocí, proto že opustil Hospodina Boha otců svých.'),
(1557828,54,14,21,11,'Přesto nadělal výsostí po horách Judských, a uvedl v smilství obyvatele Jeruzalémské, nýbrž dostrčil, jako i Judské.'),
(1557829,54,14,21,12,'I přišlo k němu psání od Eliáše proroka, řkoucího: Toto praví Hospodin Bůh Davida otce tvého: Proto že jsi nechodil po cestách Jozafata otce svého, a po cestách Azy krále Judského,'),
(1557830,54,14,21,13,'Ale chodil jsi po cestě králů Izraelských, a uvedl jsi v smilství Judu i obyvatele Jeruzalémské, tak jako jest v smilství uvedl dům Achabův Izraele, nadto i bratří své, rodinu otce svého, lepší než jsi sám, zmordoval jsi:'),
(1557831,54,14,21,14,'Aj, Hospodin uvede ránu velikou na lid tvůj a na syny tvé, na ženy tvé a na všecko jmění tvé,'),
(1557832,54,14,21,15,'Ty pak nemocen budeš těžce nemocí střev svých, až z tebe vyjdou střeva tvá pro nemoc rozmáhající se den ode dne.'),
(1557833,54,14,21,16,'A tak vzbudil Hospodin proti Jehoramovi ducha Filistinských a Arabských, kteříž jsou při končinách Chussimských.'),
(1557834,54,14,21,17,'Kteříž vytáhše proti zemi Judské, vtrhli do ní, a rozchvátali všecko jmění, kteréž se nalezlo v domě královském, ano i syny jeho a ženy jeho, tak že mu nezůstalo žádného syna kromě Joachaza, nejmladšího z synů jeho.'),
(1557835,54,14,21,18,'Potom pak po všem ranil jej Hospodin na střevách jeho nemocí nezhojitelnou.'),
(1557836,54,14,21,19,'A když se to den po dni rozmáhalo, a již čas vycházel přeběhnutí dvou let, vyšla střeva jeho pro nemoc jeho, i umřel na hrozné bolesti. A nepálil mu lid jeho vonných věcí, jako pálívali otcům jeho.'),
(1557837,54,14,21,20,'Ve třidcíti a ve dvou letech byl, když kralovati počal, a osm let kraloval v Jeruzalémě, a sešel tak, že po něm netoužili. A však jej pochovali v městě Davidově, ale ne v hrobích královských.'),
(1557838,54,14,22,1,'Tedy ustanovili krále obyvatelé Jeruzalémští Ochoziáše, syna jeho nejmladšího, místo něho; nebo všecky starší byl pobil houf lotříků, kteříž přitáhli s Arabskými do ležení. A tak kraloval Ochoziáš syn Jehorama krále Judského.'),
(1557839,54,14,22,2,'Ve čtyřidcíti a dvou letech byl Ochoziáš, když kralovati počal, a jediný rok kraloval v Jeruzalémě. Jméno pak matky jeho Atalia dcera Amri.'),
(1557840,54,14,22,3,'I on také chodil po cestách domu Achabova, nebo matka jeho nabádala jej k nepobožnosti.'),
(1557841,54,14,22,4,'Protož činil zlé věci před očima Hospodinovýma, jako dům Achabův; ty on měl zajisté rádce po smrti otce svého, k zahynutí svému.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557842,54,14,22,5,'Nebo radou jejich se spravoval, a táhl s Joramem synem Achabovým, králem Izraelským, na vojnu proti Hazaelovi králi Syrskému do Rámot Galád, kdežto ranili Syrští Jorama.'),
(1557843,54,14,22,6,'Kterýž navrátil se, aby se hojil v Jezreel; nebo měl rány, kteréž mu učinili v Ráma, když bojoval s Hazaelem králem Syrským. V tom Azariáš syn Jehorama krále Judského sstoupil, aby navštívil Jorama syna Achabova v Jezreel, kterýž tam nemocen byl.'),
(1557844,54,14,22,7,'Bylo pak to ku pádu od Boha Ochoziášovi, že přišel k Joramovi. Nebo jakž přišel, vyjel s Joramem proti Jéhu synu Namsi, kteréhož byl pomazal Hospodin, aby vyplénil dům Achabův.'),
(1557845,54,14,22,8,'Tedy stalo se, když mstil Jéhu nad domem Achabovým, že našel knížata Judská, a syny bratří Ochoziášových, kteříž sloužili Ochoziášovi, i zmordoval je.'),
(1557846,54,14,22,9,'Potom hledajíce i Ochoziáše, jali jej, an se pokrýval v Samaří, a přivedše ho k Jéhu, zabili jej a pochovali; nebo řekli: Synť jest Jozafatův, kterýž hledal Hospodina celým srdcem svým. A tak nebylo žádného více z domu Ochoziášova, kterýž by měl moc k obdržení království.'),
(1557847,54,14,22,10,'Pročež Atalia matka Ochoziášova viduci, že umřel syn její, vstavši, pomordovala všecko símě královské domu Judského.'),
(1557848,54,14,22,11,'Ale Jozabat dcera králova vzala Joasa syna Ochoziášova, a tajně ho uchvátivši z prostředku synů královských, kteříž mordováni byli, schovala jej s chůvou jeho v pokoji, kdež lůže byla. I skryla ho Jozabat dcera krále Jorama, manželka Joiady kněze, (nebo ona byla sestra Ochoziášova), před Atalií, aby ho nezamordovala.'),
(1557849,54,14,22,12,'I byl s nimi v domě Božím, skryt jsa za šest let, v nichž Atalia kralovala v té zemi.'),
(1557850,54,14,23,1,'Léta pak sedmého posilnil se Joiada, a pojal s sebou v smlouvu setníky, Azariáše syna Jerochamova, a Izmaele syna Jochananova, a Azariáše syna Obédova, a Maaseiáše syna Adaiášova, a Elizafata syna Zichri,'),
(1557851,54,14,23,2,'Kteříž obcházejíce zemi Judskou, shromáždili Levíty ze všech měst Judských, a přední z otcovských čeledí Izraelských, a přišli do Jeruzaléma.'),
(1557852,54,14,23,3,'I učinilo všecko to shromáždění smlouvu v domě Božím s králem. Byl pak jim řekl Joiada: Aj, syn králův kralovati bude, jakož mluvil Hospodin o synech Davidových.'),
(1557853,54,14,23,4,'Tatoť jest věc, kterouž učiníte: Třetí díl vás, kteříž přicházíte v sobotu z kněží a z Levítů, budou vrátnými.'),
(1557854,54,14,23,5,'Třetí pak díl bude při domě královu, a třetí díl u brány přední, ale všecken lid bude v síních domu Hospodinova.'),
(1557855,54,14,23,6,'Aniž kdo vcházej do domu Hospodinova kromě kněží a těch Levítů, kteříž konají služby. Ti ať vcházejí, nebo svatí jsou, všecken pak lid ať drží stráž Hospodinovu.'),
(1557856,54,14,23,7,'I obstoupí Levítové krále vůkol, jeden každý maje braň svou v rukou svých, a kdož by koli všel do domu, ať umře. A buďte při králi, když bude vcházeti, i když bude vycházeti.'),
(1557857,54,14,23,8,'Tedy učinili Levítové a všecken Juda všecko, cožkoli přikázal Joiada kněz, a vzali jeden každý muže své, kteříž přicházeli v sobotu, a kteříž odcházeli v sobotu; nebo byl nepropustil Joiada kněz žádné střídy.'),
(1557858,54,14,23,9,'I dal Joiada kněz setníkům kopí a pavézy i štíty, kteříž byli krále Davida, jenž byli v domě Božím.'),
(1557859,54,14,23,10,'A postavil všecken lid, (a jeden každý měl braň v ruce své), od pravé strany domu až do levé strany domu, proti oltáři a proti domu, při králi všudy vůkol.'),
(1557860,54,14,23,11,'A tak vyvedli syna králova, a vstavili na něj korunu královskou a ozdobu. I ustanovili jej králem, a pomazali ho Joiada a synové jeho, a říkali: Živ buď král!'),
(1557861,54,14,23,12,'V tom uslyševši Atalia hřmot sbíhajícího se lidu, a chválícího krále, vešla k lidu do domu Hospodinova.'),
(1557862,54,14,23,13,'A když pohleděla, a aj, král stál na místě vyšším, kudyž se vchází, a knížata i trubači podlé krále, a všecken lid země veselící se, a zvučící na trouby, a zpěváci s nástroji hudebnými, a ti, kteříž předčili v zpívání. Tedy roztrhla Atalia roucho své, a řekla: Spiknutí, spiknutí!'),
(1557863,54,14,23,14,'Ale Joiada kněz rozkázal vyjíti setníkům, hejtmanům vojska, řka jim: Vyveďte ji prostředkem řadů, a kdož by za ní šel, ať jest zabit mečem. Nebo byl řekl kněz: Nezabijejte jí v domě Hospodinově.'),
(1557864,54,14,23,15,'A když se jí rozstoupili s obou stran, šla, kudy se chodí k bráně koňské k domu královskému, a tu ji zabili.'),
(1557865,54,14,23,16,'Tedy Joiada učinil smlouvu mezi Hospodinem a mezi vším lidem, i mezi králem, aby byli lid Hospodinův.'),
(1557866,54,14,23,17,'Potom šel všecken lid do domu Bálova a zbořili jej i oltáře jeho, a obrazy stroskotali. Matana pak kněze Bálova zabili před oltáři.'),
(1557867,54,14,23,18,'I uvedl zase Joiada úředníky domu Hospodinova pod moc kněží a Levítů, kteréž byl rozdělil David v domě Hospodinově, aby obětovali zápaly Hospodinu, (jakož psáno jest v zákoně Mojžíšově), s veselím a zpíváním podlé nařízení Davidova.'),
(1557868,54,14,23,19,'Postavil také vrátné u vrat domu Hospodinova, aby tam nevcházel poškvrněný jakoužkoli věcí.'),
(1557869,54,14,23,20,'A pojav setníky a znamenitější, a ty, kteříž správu drželi nad lidem, i všecken lid země, provázel krále z domu Hospodinova. I šli branou hořejší do domu královského, a posadili krále na stolici královské.'),
(1557870,54,14,23,21,'I veselil se všecken lid země, a město se upokojilo, jakž Atalii zabili mečem.'),
(1557871,54,14,24,1,'V sedmi letech byl Joas, když počal kralovati, a čtyřidceti let kraloval v Jeruzalémě. Jméno pak matky jeho Sebia z Bersabé.'),
(1557872,54,14,24,2,'A činil Joas to, což pravého bylo před očima Hospodinovýma po všecky dny kněze Joiady.'),
(1557873,54,14,24,3,'Mezi tím vzal mu Joiada dvě ženě, i plodil syny i dcery.'),
(1557874,54,14,24,4,'Potom pak uložil v srdci Joas, aby opravil dům Hospodinův.'),
(1557875,54,14,24,5,'I shromáždil kněží a Levíty, a řekl jim: Vyjděte do měst Judských, a vybírejte ode všeho Izraele peníze, na opravu domu Boha vašeho na každý rok, vy pak pospěšte s tou věcí. Ale nepospíchali Levítové.'),
(1557876,54,14,24,6,'Protož povolav král Joiady, předního kněze, řekl jemu: Proč nepřídržíš Levítů, aby snesli z Judstva a z Jeruzaléma sbírku Mojžíše služebníka Hospodinova a shromáždění všeho Izraele k stánku svědectví?'),
(1557877,54,14,24,7,'Nebo Atalia bezbožná a synové její vlámali se do domu Božího, a všecky věci posvěcené domu Hospodinova obrátili na modly.'),
(1557878,54,14,24,8,'A tak poručil král, aby udělali jednu truhlu, a postavili ji u brány domu Hospodinova vně.'),
(1557879,54,14,24,9,'I dali provolati v Judstvu a v Jeruzalémě, aby snesli Hospodinu sbírku Mojžíše služebníka Božího, uloženou na Izraele na poušti.'),
(1557880,54,14,24,10,'Tedy veselila se všecka knížata i všecken lid, a přinášejíce, metali do truhly, až se zpořádali.'),
(1557881,54,14,24,11,'Bývalo pak to, že když přinášeli truhlu k úředníkům královským skrze ruce Levítů, (nebo když viděli, že mnoho jest peněz, tedy přicházel kanclíř královský a úředník nejvyššího kněze), aby vyprázdnili truhlu, potom ji zase donášeli a postavovali na místo její. A tak činívali den po dni, a sebrali peněz velmi mnoho.'),
(1557882,54,14,24,12,'Kteréž vydával král a Joiada správcům nad dílem domu Hospodinova, a oni najímali kameníky a řemeslníky k opravování domu Hospodinova, ano i kováře a kotláře k utvrzení domu Hospodinova.'),
(1557883,54,14,24,13,'Takž dělali dělníci, a spraveno jest dílo to skrze ruce jejich, tak že přivedli zase dům Boží k způsobu jeho, a upevnili jej.'),
(1557884,54,14,24,14,'A když dokonali, přinesli před krále a Joiadu ostatek peněz. I dal nadělati z nich nádob do domu Hospodinova, nádob k službě a obětování, a kadidlnic, i jiných nádob zlatých a stříbrných. A tak obětovávali oběti zápalné v domě Hospodinově ustavičně, po všecky dny Joiadovy.'),
(1557885,54,14,24,15,'Potom sstaral se Joiada, pln jsa dnů, a umřel. Ve stu a ve třidcíti letech byl, když umřel.'),
(1557886,54,14,24,16,'I pochovali ho v městě Davidově s králi, proto že činil, což dobrého jest Izraelovi, Bohu i domu jeho.'),
(1557887,54,14,24,17,'Po smrti pak Joiadově přišla knížata Judská, a padše, klaněli se králi. Tedy uposlechl jich král.'),
(1557888,54,14,24,18,'Pročež opustivše dům Hospodina Boha otců svých, sloužili hájům a modlám. I rozhněval se Bůh na lid Judský a na Jeruzalém pro ten hřích jejich.'),
(1557889,54,14,24,19,'I posílal k nim proroky, aby je zase obrátili k Hospodinu. Kteřížto svědčili jim, oni však neuposlechli.'),
(1557890,54,14,24,20,'Nýbrž, když Duch Boží vzbudil Zachariáše syna Joiady kněze, (kterýž vystoupiv před lid, mluvil jim: Takto praví Bůh: Proč přestupujete přikázaní Hospodinova? Nepovedeť se vám šťastně. Proto že jste opustili Hospodina, i on také opustí vás);'),
(1557891,54,14,24,21,'Oni spikše se proti němu, ukamenovali jej z rozkazu králova v síni domu Hospodinova.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557892,54,14,24,22,'(Aniž se rozpomenul Joas král na milosrdenství, kteréž byl učinil jemu Joiada otec jeho, ale zamordoval syna jeho.) Kterýž když umíral, řekl: Nechť popatří Hospodin, a vyhledá to.'),
(1557893,54,14,24,23,'I stalo se po roce, vytáhlo proti němu vojsko Syrské a přitáhlo proti Judovi a Jeruzalému, a vyhladili z lidu všecka knížata jejich, a všecky loupeže jich poslali králi Damašskému.'),
(1557894,54,14,24,24,'Nebo ač v malém počtu lidu bylo přitáhlo vojsko Syrské, však Hospodin dal v ruku jejich vojsko velmi veliké, proto že opustili Hospodina Boha otců svých. Ano i samého Joasa trápili.'),
(1557895,54,14,24,25,'A jakž ti odešli od něho, (opustivše jej v těžkých nemocech), spikli se proti němu služebníci jeho pro krev synů Joiady kněze, a zamordovali jej na loži jeho. I umřel. Tedy pochovali jej v městě Davidově, ale nepochovali ho v hrobích královských.'),
(1557896,54,14,24,26,'A tito jsou, kteříž se spikli proti němu: Zabad syn Simaty Ammonitského, a Jozabad syn Simrity Moábského.'),
(1557897,54,14,24,27,'O synech pak jeho, a o veliké dani od něho uložené, i o stavení domu Božího, to vše sepsáno jest v knize královské. Kraloval pak Amaziáš syn jeho místo něho.'),
(1557898,54,14,25,1,'V pětmecítma letech kralovati počal Amaziáš, a kraloval dvadceti devět let v Jeruzalémě. Jméno matky jeho Joadan z Jeruzaléma.'),
(1557899,54,14,25,2,'A činil to, což pravého bylo před očima Hospodinovýma, ale však ne srdcem upřímým.'),
(1557900,54,14,25,3,'I stalo se, když bylo upevněno království jeho, že zmordoval služebníky své, kteříž zabili krále otce jeho.'),
(1557901,54,14,25,4,'A však synů jejich nekázal mordovati, ale učinil tak, jakž psáno jest v zákoně, v knize Mojžíšově, kdež přikázal Hospodin, řka: Nebudou na hrdle trestáni otcové za syny, aniž synové trestáni budou na hrdle za otce, ale jeden každý za svůj hřích umře.'),
(1557902,54,14,25,5,'Zatím shromáždil Amaziáš lid Judský, a ustanovil po domích otcovských čeledí jejich hejtmany a setníky, po všem Judstvu a pokolení Beniaminovu, a sečtl je od dvadcítiletých a výše, a našel jich třikrát sto tisíc vybraných mužů bojovných, kopidlníků a pavézníků.'),
(1557903,54,14,25,6,'Najal také ze mzdy z Izraele sto tisíc mužů udatných ze sta hřiven stříbra.'),
(1557904,54,14,25,7,'Muž pak Boží přišel k němu, řka: Ó králi, nechť netáhne s tebou vojsko Izraelské; nebo Hospodin není s Izraelem, a všechněmi syny Efraimovými.'),
(1557905,54,14,25,8,'Ale táhni ty. Učiniž tak, a posilň se k boji; jinak porazí tě Bůh před nepřátely, neboť může Bůh i pomoci i poraziti.'),
(1557906,54,14,25,9,'Tedy řekl Amaziáš muži Božímu: Jakž pak udělám s stem hřiven stříbra, kteréž jsem dal vojsku Izraelskému? Odpověděl muž Boží: Máť Hospodin mnohem více nad to, což by dal tobě.'),
(1557907,54,14,25,10,'A tak oddělil Amaziáš vojsko to, kteréž bylo přitáhlo k němu z Efraim, aby odešli na místo své. Pročež rozhněvali se náramně na Judské a navrátili se k místu svému s velikým hněvem.'),
(1557908,54,14,25,11,'Mezi tím Amaziáš posiliv se, vedl lid svůj, a táhl do údolí solnatého, a porazil synů Seir deset tisíců.'),
(1557909,54,14,25,12,'Deset také tisíců živých jali synové Judští, a vedli na vrch skály, a sházeli je s vrchu té skály, tak že se všickni zrozráželi.'),
(1557910,54,14,25,13,'Vojsko pak to, kteréž zase odeslal Amaziáš, aby netáhlo s ním na vojnu, vtrhlo do měst Judských od Samaří až do Betoron, a pobivše z nich tři tisíce, nabrali loupeží mnoho.'),
(1557911,54,14,25,14,'I stalo se, když se vracel Amaziáš od porážky Idumejských, že přivezl s sebou bohy synů Seir, a vyzdvihl je sobě za bohy, a skláněl se před nimi, a kadil jim.'),
(1557912,54,14,25,15,'A protož rozhněval se náramně Hospodin na Amaziáše, a poslal k němu proroka,kterýž jemu řekl: Proč hledáš bohů lidu toho, kteříž nevytrhli lidu svého z ruky tvé?'),
(1557913,54,14,25,16,'Stalo se pak, když on k němu mluvil, řekl mu král: Co tě postavili, abys byl rádcím královským? Přestaniž, nechceš-li bit býti. A tak přestal prorok, však řekl: Seznávám, že tě usoudil Bůh zahladiti, poněvadž učiniv to, neuposlechl jsi rady mé.'),
(1557914,54,14,25,17,'Tedy poradiv se Amaziáš král Judský, poslal k Joasovi synu Joachaza syna Jéhu, králi Izraelskému, řka: Nuže, pohleďme sobě v oči.'),
(1557915,54,14,25,18,'I poslal Joas král Izraelský k Amaziášovi králi Judskému, a řekl: Bodlák, kterýž byl na Libánu, poslal k cedru Libánskému, řka: Dej dceru svou synu mému za manželku. V tom šlo tudy zvíře polní, kteréž bylo na Libánu, a pošlapalo ten bodlák.'),
(1557916,54,14,25,19,'Myslil jsi: Aj, porazil jsem Idumejské, protož pozdvihlo tě srdce tvé, tak že se tím honosíš. Medle, zůstaň v domě svém. Proč se máš zapletati v takové zlé, až bys padl i ty i Juda s tebou?'),
(1557917,54,14,25,20,'Ale neuposlechl Amaziáš; nebo od Boha to bylo, aby je vydal v ruku oněchno, proto že hledali bohů Idumejských.'),
(1557918,54,14,25,21,'Takž vytáhl Joas král Izraelský, a pohleděli sobě v oči s Amaziášem králem Judským v Betsemes, kteréž jest Judovo.'),
(1557919,54,14,25,22,'I poražen jest Juda před Izraelem, a utíkali jeden každý do příbytků svých.'),
(1557920,54,14,25,23,'Amaziáše pak krále Judského, syna Joasova, jenž byl syn Joachazův, jal Joas král Izraelský u Betsemes, a přivedl jej do Jeruzaléma, a zbořil zdi Jeruzalémské odbrány Efraim až k bráně úhlu na čtyři sta loktů.'),
(1557921,54,14,25,24,'A pobrav všecko zlato a stříbro i všecko nádobí, kteréž se nalezlo v domě Božím u Obededoma, a v pokladích domu královského, také i ty, kteříž byli v zástavě, navrátil se do Samaří.'),
(1557922,54,14,25,25,'Byl pak živ Amaziáš syn Joasův, král Judský, po smrti Joasa syna Joachaza, krále Izraelského, patnácte let.'),
(1557923,54,14,25,26,'Ale o jiných činech Amaziášových, prvních i posledních, vypsáno jest v knize o králích Judských a Izraelských.'),
(1557924,54,14,25,27,'Od toho zajisté času, jakž se spustil Amaziáš Hospodina, spikli se jedovatě proti němu v Jeruzalémě. A když utekl do Lachis, poslali za ním do Lachis, a zabili jej tam.'),
(1557925,54,14,25,28,'A přinesše ho na koních, pochovali jej s otci jeho v městě Judově.'),
(1557926,54,14,26,1,'Tedy všecken lid Judský vzali Uziáše, kterýž byl v šestnácti letech, a ustanovili jej za krále na místě otce jeho Amaziáše.'),
(1557927,54,14,26,2,'Onť jest vzdělal Elot, a dobyl ho zase Judovi, když již umřel král s otci svými.'),
(1557928,54,14,26,3,'V šestnácti letech byl Uziáš, když kralovati počal, a kraloval padesáte a dvě létěv Jeruzalémě. Jméno pak matky jeho Jecholia z Jeruzaléma.'),
(1557929,54,14,26,4,'Ten činil to, což pravého bylo před očima Hospodinovýma, podlé všeho, což byl činil Amaziáš otec jeho.'),
(1557930,54,14,26,5,'A hledal s pilností Boha ve dnech Zachariáše, rozumějícího vidění Božímu, a po ty dny, v nichž hledal Hospodina, šťastný prospěch dal jemu Bůh.'),
(1557931,54,14,26,6,'Nebo vytáh, bojoval proti Filistinským, a probořil zed města Gát, a zed města Jabne, i zed města Azotu, a vystavěl města okolo Azotu, i v zemi Filistinské.'),
(1557932,54,14,26,7,'Bůh zajisté pomáhal jemu proti Filistinským a proti Arabským, kteříž bydlili v Gurbal, i proti Maonitským.'),
(1557933,54,14,26,8,'I dávali Ammonitští dary Uziášovi, a rozneslo se jméno jeho až do Egypta; nebo zsilil se na nejvyšší.'),
(1557934,54,14,26,9,'A vzdělal Uziáš věže v Jeruzalémě u brány úhlové, a u brány údolí, a u Mikzoa, i upevnil je.'),
(1557935,54,14,26,10,'Vystavěl také věže na poušti, a vykopal studnic mnoho, proto že měl stád mnoho, jakož při údolí tak i na rovinách, oráče tolikéž a vinaře po horách i na místech úrodných; nebo laskav byl na rolí.'),
(1557936,54,14,26,11,'Měl také Uziáš vojsko bojovníků, vycházejících k boji po houfích v jistém počtu, jakž vyčteni byli od Jehiele kanclíře, a Maaseiáše úředníka, uvedené pod správu Chananiášovi knížeti královskému.'),
(1557937,54,14,26,12,'Všecken počet knížat čeledí otcovských, mužů udatných, dva tisíce a šest set.'),
(1557938,54,14,26,13,'A pod spravou jejich lidu válečného třikrát sto tisíc, sedm tisíc a pět set bojovníků udatných, aby pomáhali králi proti nepříteli.'),
(1557939,54,14,26,14,'Připravil pak Uziáš všemu tomu vojsku pavézy, kopí, lebky, pancíře, lučiště i kamení prakové.'),
(1557940,54,14,26,15,'Nadělal také v Jeruzalémě vtipně vymyšlených nástrojů válečných, aby byli na věžech a na úhlech k střílení střelami a kamením velikým. I rozneslo se jméno jeho daleko, proto že divné pomoci měl, až se i zmocnil.'),
(1557941,54,14,26,16,'Ale když se zmocnil, pozdvihlo se srdce jeho k zahynutí jeho, a zhřešil proti Hospodinu Bohu svému; nebo všel do chrámu Hospodinova, aby kadil na oltáři, na němž se kadívalo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557942,54,14,26,17,'I všel za ním Azariáš kněz, a s ním jiných kněží Hospodinových osmdesáte, mužů udatných.'),
(1557943,54,14,26,18,'Kteříž postavili se proti Uziášovi králi, a mluvili jemu: Ne tobě, Uziáši, náleží kaditi Hospodinu, ale kněžím, synům Aronovým, kteříž posvěceni jsou, aby kadili. Vyjdiž z svatyně, nebo jsi zhřešil, aniž to bude tobě ke cti před Hospodinem Bohem.'),
(1557944,54,14,26,19,'Pročež rozhněval se Uziáš, (v ruce pak své měl kadidlnici, aby kadil). A když se spouzel na kněží, ukázalo se malomocenství na čele jeho před kněžími v domě Hospodinově u oltáře, na němž se kadilo.'),
(1557945,54,14,26,20,'A pohleděv na něj Azariáš, nejvyšší kněz, a všickni kněží, a aj, byl malomocný na čele svém. Protož rychle jej vyvedli ven, nýbrž i sám se nutil vyjíti, proto že ho ranil Hospodin.'),
(1557946,54,14,26,21,'A tak byl Uziáš král malomocný až do dne smrti své, a bydlil v domě obzvláštním, jsa malomocný; nebo byl vyobcován z domu Hospodinova. Mezi tím Jotam syn jeho byl nad domem královským, soudě lid země.'),
(1557947,54,14,26,22,'O jiných pak věcech Uziášových, prvních i posledních, psal Izaiáš prorok, syn Amosův.'),
(1557948,54,14,26,23,'I usnul Uziáš s otci svými, a pochovali jej s otci jeho na poli hrobů královských; nebo řekli: Malomocný jest. I kraloval Jotam syn jeho místo něho.'),
(1557949,54,14,27,1,'V pětmecítma letech byl Jotam, když počal kralovati, a šestnáct let kraloval v Jeruzalémě. Jméno matky jeho Jerusa dcera Sádochova.'),
(1557950,54,14,27,2,'Kterýž činil to, což pravého bylo před očima Hospodinovýma, podlé všeho, což činil Uziáš otec jeho, kromě že nevšel do chrámu Hospodinova, a lid ještě porušený byl.'),
(1557951,54,14,27,3,'On ustavěl bránu domu Hospodinova hořejší, a na zdi Ofel mnoho stavěl.'),
(1557952,54,14,27,4,'Nadto vystavěl i města na horách Judských, a v lesích zdělal zámky a věže.'),
(1557953,54,14,27,5,'On také bojoval s králem synů Ammon, a zmocnil se jich. I dali mu synové Ammon toho roku sto centnéřů stříbra, a deset tisíc měr pšenice, a ječmene deset tisíců. Tolikéž dali mu synové Ammon i léta druhého i třetího.'),
(1557954,54,14,27,6,'A tak zsilil se Jotam; nebo nastrojil cesty své před Hospodinem Bohem svým.'),
(1557955,54,14,27,7,'O jiných pak věcech Jotamových, a o všech válkách i cestách jeho, zapsáno jest v knize o králích Izraelských a Judských.'),
(1557956,54,14,27,8,'V pětmecítma letech byl, když kralovati začal, a šestnáct let kraloval v Jeruzalémě.'),
(1557957,54,14,27,9,'I usnul Jotam s otci svými, a pochovali jej v městě Davidově, a kraloval Achas syn jeho místo něho.'),
(1557958,54,14,28,1,'Ve dvadcíti letech byl Achas, když počal kralovati, a šestnácte let kraloval v Jeruzalémě, a nečinil toho, což pravého bylo před očima Hospodinovýma, jako David otec jeho.'),
(1557959,54,14,28,2,'Ale chodil po cestách králů Izraelských, nýbrž nadělal také slitin modlářských.'),
(1557960,54,14,28,3,'Přesto i sám kadíval v údolí Benhinnom, a pálil syny své ohněm podlé ohavností pohanů, kteréž vyhnal Hospodin před syny Izraelskými.'),
(1557961,54,14,28,4,'A obětoval i kadíval na výsostech a na pahrbcích, i pod každým stromem zeleným.'),
(1557962,54,14,28,5,'Protož dal jej Hospodin Bůh jeho v ruku krále Syrského. Kteříž porazivše jej, zajali odtud množství veliké, a přivedli je do Damašku. Nad to i v ruku krále Izraelského dán jest, kterýž porazil jej porážkou velikou.'),
(1557963,54,14,28,6,'Nebo pomordoval Pekach syn Romeliášův v Judstvu sto a dvadcet tisíců dne jednoho, vše mužů udatných, proto že opustili Hospodina Boha otců svých.'),
(1557964,54,14,28,7,'Zabil také Zichri, rytíř Efraimský Maaseiáše syna králova, a Azrikama, správce domu jeho, a Elkána, druhého po králi.'),
(1557965,54,14,28,8,'Nadto zajali též synové Izraelští z bratří svých dvakrát sto tisíc žen, synů a dcer, ano i kořistí mnoho nabrali od nich, a vezli loupež do Samaří.'),
(1557966,54,14,28,9,'Byl pak tu prorok Hospodinův, jménem Oded, kterýž vyšed proti vojsku přicházejícímu do Samaří, řekl jim: Hle, rozhněvav se Hospodin Bůh otců vašich na Judské, vydal je v ruku vaši, a vy jste je pomordovali v prchlivosti, kteráž až k nebi dosáhla.'),
(1557967,54,14,28,10,'A ještě Judské a Jeruzalémské myslíte sobě podrobiti za pacholky a děvky. Zdaliž i vy, i vy, jste bez hříchů proti Hospodinu Bohu vašemu?'),
(1557968,54,14,28,11,'A protož nyní poslechněte mne, a doveďte zase zajaté, kteréž jste zajali z bratří svých; nebo jinak hněv prchlivosti Hospodinovy bude proti vám.'),
(1557969,54,14,28,12,'Tedy povstali někteří z předních synů Efraimových: Azariáš syn Jochananův, Berechiáš syn Mesillemotův, Ezechiáš syn Sallumův, a Amaza syn Chadlaiův proti těm, kteříž se vracovali z té vojny.'),
(1557970,54,14,28,13,'A řekli jim: Nepřivedete sem těch zajatých; nebo vinu proti Hospodinu myslíte na nás uvesti, přivětšujíce hříchů našich a provinění našich. Veliký tě zajisté hřích náš a prchlivost hněvu proti Izraelovi.'),
(1557971,54,14,28,14,'Takž nechali vojáci těch zajatých i kořistí svých před knížaty a vším shromážděním.'),
(1557972,54,14,28,15,'A přičinivše se muži někteří ze jména znamenaní, vzali ty zajaté, a všecky, kteřížkoli z nich nebyli odění, přiodíli je z těch kořistí. A když je zobláčeli a zobouvali, nakrmili i napojili, ano i pomazali, a zprovodili na oslích, každého nemocného z nich, a dovedli ho do Jericha města palmového k bratřím jejich, potom navrátili se do Samaří.'),
(1557973,54,14,28,16,'Toho času poslal král Achas k králům Assyrským, aby mu pomoc dali.'),
(1557974,54,14,28,17,'Nebo ještě přitáhli i Idumejští, a zbili některé z Judských, a jiné zajali.'),
(1557975,54,14,28,18,'Nadto i Filistinští učinili vpád do měst, na rovinách k straně polední Judstva, a vzali Betsemes a Aialon, a Gederot a Socho i vsi jeho, a Tamna i vsi jeho, a Gimzo i vsi jeho, a bydlili v nich.'),
(1557976,54,14,28,19,'Tak zajisté ponižoval Hospodin Judy pro Achasa krále Izraelského, proto že odvrátil Judu, aby naprosto převráceně činil proti Hospodinu.'),
(1557977,54,14,28,20,'A tak přitáhl k němu Tiglatfalazar král Assyrský, a více ho ssužoval, nežli mu pomáhal.'),
(1557978,54,14,28,21,'A ačkoli Achas vzal z domu Hospodinova a domu královského, i od knížat, a dal králi Assyrskému, však nedal jemu pomoci.'),
(1557979,54,14,28,22,'V který pak koli čas byl ssužován, tím větší převrácenost páchal proti Hospodinu. Takový byl král Achas.'),
(1557980,54,14,28,23,'Nebo obětoval bohům Damašským, kteříž ho porazili, a řekl: Poněvadž bohové králů Syrských pomáhají jim, těm obětovati budu, aby mně pomáhali. Ale oni byli ku pádu jemu, ano i všemu Izraeli.'),
(1557981,54,14,28,24,'Pročež shromáždiv Achas nádoby domu Božího, osekal je, a zamkl dvéře domu Hospodinova, a nadělal sobě oltářů při každém úhlu v Jeruzalémě.'),
(1557982,54,14,28,25,'Ano i v každém městě Judském zdělal výsosti, aby kadil bohům cizím, a tak popouzel k hněvu Hospodina Boha otců svých.'),
(1557983,54,14,28,26,'O jiných pak věcech jeho, a o všech cestách jeho, prvních i posledních zapsáno jest v knize králů Judských a Izraelských.'),
(1557984,54,14,28,27,'I usnul Achas s otci svými, a pochovali jej v městě Jeruzalémě; nebo nevložili ho do hrobů králů Izraelských. I kraloval Ezechiáš syn jeho místo něho.'),
(1557985,54,14,29,1,'Ezechiáš kralovati počal, když byl v pětmecítma letech, a dvadceti devět let kraloval v Jeruzalémě. Jméno matky jeho bylo Abia dcera Zachariášova.'),
(1557986,54,14,29,2,'A činil to, což pravého bylo před očima Hospodinovýma, podlé všech věcí, kteréž činil David otec jeho.'),
(1557987,54,14,29,3,'On prvního léta kralování svého měsíce prvního otevřel dvéře domu Hospodinova, a opravil je.'),
(1557988,54,14,29,4,'Uvedl také kněží a Levíty, shromáždiv je do ulice východní,'),
(1557989,54,14,29,5,'A řekl jim: Slyšte mne, Levítové. Nyní posvěťte se, posvěťte také i domu Hospodina Boha otců vašich, a vyneste nečistotu z svatyně.'),
(1557990,54,14,29,6,'Neboť zhřešili otcové naši, a činili zlé věci před očima Hospodina Boha našeho, opouštějíce jej, a odvracujíce tvář svou od stánku Hospodinova, obracejíce se hřbetem k němu.'),
(1557991,54,14,29,7,'Zavřeli také dvéře síně, a zhasili lampy, a kadidlem nekadili, aniž zápalu obětovali v svatyni Bohu Izraelskému.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1557992,54,14,29,8,'Protož rozhněval se Hospodin na Judu a na Jeruzalém, a vydal je v posmýkání, zpuštění a ku podivení, jakož sami očima svýma vidíte.'),
(1557993,54,14,29,9,'A aj, padli otcové naši od meče, a synové naši i dcery naše a manželky naše zajaty jsou pro tu příčinu.'),
(1557994,54,14,29,10,'Nyní tedy umínil jsem učiniti smlouvu s Hospodinem Bohem Izraelským, aby odvrátil od nás hněv prchlivosti své.'),
(1557995,54,14,29,11,'Synové moji, nebluďtež již. Vásť jest zajisté vyvolil Hospodin, abyste stojíce před ním, sloužili jemu, a byli služebníci jeho, a kadili.'),
(1557996,54,14,29,12,'Tedy povstali Levítové tito: Machat syn Amazai, a Joel syn Azariášův z synů Kahat; z synů pak Merari: Cis syn Abdi, a Azariáš syn Jehalleelův; a z Gersonitských: Joach syn Zimma, a Eden syn Joachův;'),
(1557997,54,14,29,13,'Též z synů Elizafanových: Simri a Jehiel; z synů pak Azafových: Zachariáš a Mataniáš;'),
(1557998,54,14,29,14,'A z synů Hémanových: Jechiel a Simei; z synů pak Jedutunových: Semaiáš a Uziel.'),
(1557999,54,14,29,15,'I shromáždili bratří své, kteříž posvětivše se, přišli podlé rozkázaní králova a slov Hospodinových, aby vyčistili dům Hospodinův.'),
(1558000,54,14,29,16,'A všedše kněží do domu Hospodinova, aby jej vyčistili, vynesli všelikou nečistotu, kterouž našli v chrámě Hospodinově, do síně domu Hospodinova. Levítové pak probravše to, vynesli ven ku potoku Cedron.'),
(1558001,54,14,29,17,'Začali pak prvního dne měsíce prvního posvěcovati, a dne osmého téhož měsíce vešli do síně Hospodinovy, a posvěcovali domu Hospodinova za osm dní, a dne šestnáctého měsíce prvního dokonali.'),
(1558002,54,14,29,18,'Tedy vešli k Ezechiášovi králi, a řekli: Vyčistili jsme všecken dům Hospodinův, i oltář zápalu, i všecky nádoby jeho, i stůl předložení a všecky nádoby jeho.'),
(1558003,54,14,29,19,'Všecky také nádoby, kteréž byl zavrhl král Achas za kralování svého, když převráceně činil, připravili jsme a posvětili, a aj, jsou před oltářem Hospodinovým.'),
(1558004,54,14,29,20,'Potom vstav ráno Ezechiáš král, shromáždil úředníky města, a vstoupil do domu Hospodinova.'),
(1558005,54,14,29,21,'A přivedli volků sedm, a skopců sedm, a beránků sedm, a kozlů sedm za hřích, za království, a za svatyni, a za Judu; a rozkázal synům Aronovým kněžím, aby obětovali na oltáři Hospodinovu.'),
(1558006,54,14,29,22,'Takž zbili voly ty, a kněží berouce krev jejich, kropili na oltář. Zbili též i skopce a pokropovali krví jejich oltáře; zbili také i beránky, a krví jejich kropili na oltář.'),
(1558007,54,14,29,23,'Přivedli i kozly k oběti za hřích před krále i shromáždění, kteřížto vložili ruce své na ně.'),
(1558008,54,14,29,24,'I zbili je kněží a vyčistili krví jejich oltář k očištění všeho Izraele; nebo za všecken lid Izraelský rozkázal král obětovati zápal a oběti za hřích.'),
(1558009,54,14,29,25,'Postavil zase i Levíty v domě Hospodinově s cymbály, loutnami a harfami podlé rozkázaní Davidova, a Gáda proroka královského, a Nátana proroka; nebo od Hospodina bylo to přikázáno skrze proroky jeho.'),
(1558010,54,14,29,26,'A tak stáli Levítové s nástroji Davidovými a kněží s trubami.'),
(1558011,54,14,29,27,'I rozkázal Ezechiáš, aby obětovali zápal na oltáři. A když se začala obět zápalná, začal se zpěv Hospodinův a troubení i zpěvové na nástroje Davida, krále Izraelského.'),
(1558012,54,14,29,28,'Všecko pak shromáždění klanělo se, když zpěváci zpívali, a trubači troubili, a to vše, až se dokonal zápal.'),
(1558013,54,14,29,29,'A když dokonali obětování zápalu, sklonili se král a všickni, kteříž byli s ním, a poklonu učinili.'),
(1558014,54,14,29,30,'Tedy přikázal Ezechiáš král i knížata Levítům, aby chválili Hospodina slovy Davidovými a Azafa proroka. I chválili s velikým veselím, a sklánějíce se, poklonu činili.'),
(1558015,54,14,29,31,'Potom mluvil Ezechiáš, řka: Nyní jste posvětili rukou svých Hospodinu. Přistupte, a přiveďte oběti vítězné a oběti chvály do domu Hospodinova. Protož přivodilo shromáždění to oběti vítězné a oběti chvály, ano i každý z srdce ochotného k zápalným obětem,'),
(1558016,54,14,29,32,'Tak že počet obětí zápalných, kteréž přivedlo shromáždění to, byl volů sedmdesáte, skopců sto, beránků dvě stě, všecko to na obět zápalnou Hospodinu.'),
(1558017,54,14,29,33,'Jiných pak věcí posvěcených bylo volů šest set, a ovec tři tisíce.'),
(1558018,54,14,29,34,'Kněží však bylo málo, tak že nemohli postačiti vytahovati z koží všech obětí zápalných. Pročež pomáhali jim bratří jejich Levítové, až i dokonali dílo to, a dokudž se neposvětili jiní kněží; nebo Levítové byli hotovější ku posvěcení se, nežli kněží.'),
(1558019,54,14,29,35,'K tomu k zápalům bylo množství veliké tuků z obětí pokojných a obětí mokrých, kromě jiných zápalů. A tak vykonána byla služba domu Hospodinova.'),
(1558020,54,14,29,36,'A veselil se Ezechiáš i všecken lid, že Bůh byl nastrojil lid, tak aby se ta věc rychle spravila.'),
(1558021,54,14,30,1,'Potom poslal Ezechiáš ke všemu lidu Izraelskému a Judskému, psal také listy k Efraimovi a Manassesovi, aby přišli do domu Hospodinova do Jeruzaléma, a slavili velikunoc Hospodinu Bohu Izraelskému.'),
(1558022,54,14,30,2,'Snesli se pak byli na tom král i knížata jeho, i všecko shromáždění v Jeruzalémě, aby slavili velikunoc měsíce druhého.'),
(1558023,54,14,30,3,'Nebo nemohli slaviti toho času, proto že kněží posvěcených se nedostávalo, aniž se lid byl shromáždil do Jeruzaléma.'),
(1558024,54,14,30,4,'I vidělo se to za dobré králi i všemu množství,'),
(1558025,54,14,30,5,'A usoudili, aby provolati dali po všem Izraeli, od Bersabé až do Dan, aby přišli k slavení velikonoci Hospodinu Bohu Izraelskému do Jeruzaléma; nebo již byli dávno neslavili tak, jakž psáno jest.'),
(1558026,54,14,30,6,'Protož šli poslové s listy od krále a od knížat jeho po vší zemi Izraelské a Judské s rozkazem královským tímto: Synové Izraelští, obraťte se k Hospodinu Bohu Abrahamovu, Izákovu a Izraelovu, i obrátí se k ostatkům, kteříž jste koli znikli ruky králů Assyrských.'),
(1558027,54,14,30,7,'A nebývejte jako otcové vaši a bratří vaši, kteříž převráceně činili proti Hospodinu Bohu otců svých, pročež dal je v zpuštění, jakž sami vidíte.'),
(1558028,54,14,30,8,'Nyní tedy nezatvrzujte šijí svých tak, jako otcové vaši. Podejte ruky Hospodinu, a poďte do svatyně jeho, kteréž posvětil na věky, a služte Hospodinu Bohu svému, a odvrátí se od vás hněv prchlivosti jeho.'),
(1558029,54,14,30,9,'Nebo obrátíte-li se k Hospodinu, bratří vaši i synové vaši milosrdenství obdrží u těch, kteříž je zjímali, tak že se navrátí do země této. Milosrdný zajisté a dobrotivý jest Hospodin Bůh váš, aniž odvrátí tváři od vás, jestliže se obrátíte k němu.'),
(1558030,54,14,30,10,'Když pak ti poslové chodili z města do města po kraji Efraim a Manasse až do Zabulon, posmívali se a utrhali jim.'),
(1558031,54,14,30,11,'Ale však někteří z Asser, Manasses a Zabulon, poníživše se, přišli do Jeruzaléma.'),
(1558032,54,14,30,12,'V Judstvu tolikéž byla ruka Boží, tak že jim dal srdce jedno k vykonání rozkazu králova a knížat, podlé slova Hospodinova.'),
(1558033,54,14,30,13,'I sešlo se do Jeruzaléma lidu mnoho, aby drželi slavnost přesnic měsíce druhého, shromáždění velmi veliké.'),
(1558034,54,14,30,14,'Tedy povstavše, pobořili oltáře, kteříž byli v Jeruzalémě; též i všecky oltáře, na kterýchž se kadívalo, rozbořili a vmetali do potoka Cedron.'),
(1558035,54,14,30,15,'Potom pak obětovali beránka velikonočního, čtrnáctého dne měsíce druhého. Kněží pak a Levítové zastyděvše se, posvětili se, a přivedli oběti do domu Hospodinova.'),
(1558036,54,14,30,16,'A stáli v řadu svém vedlé povinnosti své podlé zákona Mojžíše muže Božího, a kněží kropili krví, berouce ji z rukou Levítů.'),
(1558037,54,14,30,17,'Nebo mnozí byli v shromáždění, kteříž se neposvětili. Protož Levítové zabíjeli beránky velikonoční za každého nečistého, k tomu, aby jich posvětili Hospodinu.'),
(1558038,54,14,30,18,'Veliký zajisté díl toho lidu, množství z Efraima, Manassesa, Izachara a Zabulona, neočistili se, a však jedli beránka velikonočního jinak než psáno jest. Ale modlil se Ezechiáš za ně, řka: Dobrotivý Hospodin očistiž toho,'),
(1558039,54,14,30,19,'Kdožkoli celým srdcem svým se ustavil, aby hledal Boha, Hospodina Boha otců svých, byť pak i očištěn nebyl vedlé očišťování svatého.'),
(1558040,54,14,30,20,'I vyslyšel Hospodin Ezechiáše, a uzdravil lid.'),
(1558041,54,14,30,21,'A tak drželi synové Izraelští, kteříž byli v Jeruzalémě, slavnost přesnic za sedm dní s veselím velikým, a chválili Hospodina každého dne Levítové a kněží na nástrojích sílu Hospodinovu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558042,54,14,30,22,'Mluvil pak byl Ezechiáš přívětivě ke všechněm Levítům vyučujícím známosti pravé Hospodina. I jedli oběti slavnosti té za sedm dní, obětujíce oběti pokojné, a oslavujíce Hospodina Boha otců svých.'),
(1558043,54,14,30,23,'Tedy sneslo se na tom všecko shromáždění, aby učinili tolikéž za druhých sedm dní. Takž slavili jiných sedm dní s radostí.'),
(1558044,54,14,30,24,'Nebo Ezechiáš král Judský dal shromáždění tomu tisíc volků, a sedm tisíc ovec. Knížata také dala shromáždění volků tisíc, a ovec deset tisíců. A posvětilo se kněží velmi mnoho.'),
(1558045,54,14,30,25,'A tak veselilo se všecko shromáždění Judské, i kněží a Levítové a všecko shromáždění, kteréž přišlo z Izraele, i příchozí, kteříž byli přišli z země Izraelské, i obyvatelé Judští.'),
(1558046,54,14,30,26,'A bylo veselí veliké v Jeruzalémě; nebo ode dnů Šalomouna syna Davida, krále Izraelského, nic takového nebylo v Jeruzalémě.'),
(1558047,54,14,30,27,'Potom pak vstali kněží i Levítové, a dali požehnání lidu. I vyslyšán jest hlas jejich, a přišla modlitba jejich k příbytku svatosti Hospodinovy v nebe.'),
(1558048,54,14,31,1,'A když se to všecko dokonalo, vyšed všecken lid Izraelský, což ho koli bylo v městech Judských, stroskotali modly a posekali háje, a pobořili výsosti a oltáře po vší zemi Judské a Beniamin, i v Efraim a Manasses, až vše dokonali. Potom navrátili se všickni synové Izraelští, jeden každý k vládařství svému do města svého.'),
(1558049,54,14,31,2,'Ezechiáš pak zase zřídil třídy kněží a Levítů podlé tříd jejich, jednoho každého podlé povinnosti přisluhování jeho, kněží a Levíty k obětem zápalným a pokojným, aby přisluhovali, a oslavovali i chválili Hospodina v branách vojska jeho.'),
(1558050,54,14,31,3,'Též i částka z statku královského dávána k obětování zápalů, k zápalům jitřním i večerním, též k zápalům sobotním, a na novměsíce i na slavnosti výroční, jakož psáno jest v zákoně Hospodinově.'),
(1558051,54,14,31,4,'Přikázal také lidu přebývajícímu v Jeruzalémě, dávati díl kněžím a Levítům, aby tím ochotnější byli v zákoně Hospodinově.'),
(1558052,54,14,31,5,'A jakž vyšel tento rozkaz, snesli synové Izraelští mnoho prvotin obilé, mstu, oleje, ovoce palmového i všech úrod polních, a desátek ze všech věcí hojný přinesli.'),
(1558053,54,14,31,6,'Synové také Izraelští a Judští, kteříž bydlili v městech Judských, i oni desátky z skotů a bravů, a desátky svaté, posvěcené Hospodinu Bohu svému, snášeli a skládali po hromadách.'),
(1558054,54,14,31,7,'Třetího měsíce počali zakládati těch hromad, a měsíce sedmého dokonali.'),
(1558055,54,14,31,8,'Přišed pak Ezechiáš s knížaty, a vidouce hromady ty, dobrořečili Hospodinu a lidu jeho Izraelskému.'),
(1558056,54,14,31,9,'I tázal se Ezechiáš kněží a Levítů o těch hromadách.'),
(1558057,54,14,31,10,'Jemuž odpověděl Azariáš kněz nejvyšší z domu Sádochova, řka: Jakž počali těch obětí přinášeti do domu Hospodinova, jedli jsme a nasyceni jsme, a ještě zůstává hojně; nebo Hospodin požehnal lidu svému, že toho tak mnoho pozůstalo.'),
(1558058,54,14,31,11,'Tedy rozkázal Ezechiáš nadělati špižírní při domu Hospodinovu. I nadělali,'),
(1558059,54,14,31,12,'A snášeli tam věrně oběti a desátky, i věci posvěcené, a nad tím byl za správce Konaniáš Levíta, a Simei bratr jeho, druhý.'),
(1558060,54,14,31,13,'Jechiel pak a Azaziáš , Nachat a Azael, a Jerimot a Jozabad, Eliel, Izmachiáš, Machat a Benaiáš, přivzati za úředníky od Konaniáše a Simei bratra jeho, podlé poručení Ezechiáše krále, a Azariáše knížete domu Božího.'),
(1558061,54,14,31,14,'Chóre pak syn Imny, Levíta, vrátný brány východní, byl nad tím, což dobrovolně obětovali Bohu, aby rozděloval oběti Hospodinovy a věci svatosvaté.'),
(1558062,54,14,31,15,'Jemuž ku pomoci byli Eden, Miniamin, Jesua, Semaiáš, Amariáš a Sechaniáš po městech kněžských, muži hodnověrní, aby rozdělovali bratřím svým díly, jakž velikému, tak malému,'),
(1558063,54,14,31,16,'(Mimo ty, kteříž z pokolení jejich byli pohlaví mužského, od tříletých a výše), každému vcházejícímu do domu Hospodinova ku povinnostem denním, podlé úřadů jejich, a podlé služby jich i podlé třídy jejich,'),
(1558064,54,14,31,17,'A těm, kteříž počteni byli v rodině kněžské po čeledech otců jejich, i Levítům, ode dvadcítiletého a výše, podlé služby jich v třídách jejich,'),
(1558065,54,14,31,18,'Též i rodině jejich, na všecky maličké jich, ženy jejich, syny jejich i dcery jejich, a všemu množství; nebo dověrně posvětili se v svatosti.'),
(1558066,54,14,31,19,'Synům také Aronovým kněžím v předměstích měst jejich po všech městech ti muži, kteříž zejména zaznamenáni jsou, dávali díly každému pohlaví mužského z kněží i každému z rodiny Levítů.'),
(1558067,54,14,31,20,'A tak učinil Ezechiáš ve všem Judstvu, a činil, což dobrého, přímého a pravého jest před Hospodinem Bohem svým.'),
(1558068,54,14,31,21,'A ve všelikém díle, kteréžkoli začal při službě domu Božího, a v zákoně i v přikázaní, hledaje Boha svého, celým srdcem svým to činil, a šťastně se mu vedlo.'),
(1558069,54,14,32,1,'Po těch věcech a stálém nařízení jejich, přitáh Senacherib král Assyrský, vtrhl do Judstva, a položil se proti městům hrazeným, a uložil jich zdobývati sobě.'),
(1558070,54,14,32,2,'Vida pak Ezechiáš, že přitáhl Senacherib, a že tvář jeho obrácena jest k boji proti Jeruzalému,'),
(1558071,54,14,32,3,'Uradil se s knížaty a rytíři svými, aby zasypali vody studnic, kteréž byly vně za městem. I pomáhali jemu.'),
(1558072,54,14,32,4,'Nebo shromáždilo se lidu množství, a zasypali všecky studnice i potok rozvodňující se u prostřed země, řkouce: Proč přijdouce králové Assyrští, mají najíti vody tak mnoho?'),
(1558073,54,14,32,5,'A posiliv se, vystavěl všecku zed zbořenou, a zopravoval věže, a vně zed druhou. Upevnil i Mello města Davidova, k tomu také nadělal braně velmi mnoho i pavéz.'),
(1558074,54,14,32,6,'Zřídil též hejtmany válečné nad lidem, a shromáždil je k sobě do ulice u brány městské, a mluvil jim přívětivě, řka:'),
(1558075,54,14,32,7,'Posilňte se a zmužile sobě počínejte, nebojte se, ani strachujte tváři krále Assyrského, ani všeho množství, kteréž jest s ním; nebo větší jest s námi, než s ním.'),
(1558076,54,14,32,8,'S nímť jest rámě člověka, s námi pak jest Hospodin Bůh náš, ku pomoci naší a k bojování za nás. I zpolehl lid na slova Ezechiáše krále Judského.'),
(1558077,54,14,32,9,'Potom poslal Senacherib král Assyrský služebníky své do Jeruzaléma, (sám pak ležel u Lachis, a všecko království jeho bylo s ním), k Ezechiášovi králi Judskému, i ke všemu lidu Judskému, kterýž byl v Jeruzalémě, řka:'),
(1558078,54,14,32,10,'Takto praví Senacherib král Assyrský: V čem vy doufáte, že zůstáváte v ohradě v Jeruzalémě?'),
(1558079,54,14,32,11,'Zdaliž Ezechiáš nenavodí vás, aby vás zmořil hladem a žízní, pravě: Hospodin Bůh náš vytrhne nás z ruky krále Assyrského?'),
(1558080,54,14,32,12,'Zdaliž jest sám Ezechiáš nepobořil výsostí jeho a oltářů jeho, a přikázal Judovi a obyvatelům Jeruzalémským, řka: Před jedním oltářem klaněti se budete, a na něm kaditi.'),
(1558081,54,14,32,13,'Nevíte-liž, co jsem učinil já i otcové moji všechněm národům zemí? Zdaliž jak mohli bohové národů a zemí vytrhnouti země své z ruky mé?'),
(1558082,54,14,32,14,'Kdo byl mezi všemi bohy národů těch, kteréž jsou vyplénili otcové moji, kterýž by mohl vytrhnouti lid svůj z ruky mé? Aby pak mohl Bůh váš vytrhnouti vás z ruky mé?'),
(1558083,54,14,32,15,'Protož tedy nechť vás nesvodí Ezechiáš, ani vás namlouvá, aniž mu věřte. Kdyžtě nemohl žádný bůh všech národů a království vytrhnouti lidu svého z ruky mé, jako i z ruky otců mých, nadtoť ovšem bohové vaši nevytrhnou vás z ruky mé.'),
(1558084,54,14,32,16,'Přes to ještě mluvili služebníci jeho i proti Hospodinu Bohu, i proti Ezechiášovi služebníku jeho.'),
(1558085,54,14,32,17,'Psal také listy, rouhaje se Hospodinu Bohu Izraelskému, a mluvě proti němu, řka: Jakož bohové národů zemských nevytrhli lidu svého z ruky mé, tak nevytrhne Bůh Ezechiášův lidu svého z ruky mé.'),
(1558086,54,14,32,18,'Křičeli pak hlasem velikým Židovsky proti lidu Jeruzalémskému, kterýž byl na zdi, aby strach na ně pustili a předěsili je, aby tak vzali město.'),
(1558087,54,14,32,19,'A tak mluvili o Bohu Jeruzalémském, jako o jiných bozích národů země, dílu rukou lidských.'),
(1558088,54,14,32,20,'Tedy modlil se Ezechiáš král, a Izaiáš prorok syn Amosův z příčiny té, a volali k nebi.'),
(1558089,54,14,32,21,'I poslal Hospodin anděla, kterýž vyhladil každého udatného i vývodu i kníže v vojště krále Assyrského, tak že se s hanbou velikou navrátil do země své. A když všel do chrámu boha svého, ti, kteříž vyšli z života jeho, zamordovali ho tam mečem.'),
(1558090,54,14,32,22,'A tak vysvobodil Hospodin Ezechiáše a obyvatele Jeruzalémské z ruky Senacheriba krále Assyrského, a z ruky všech, a provázel je všudy vůkol.'),
(1558091,54,14,32,23,'Tedy mnozí přinášeli oběti Hospodinu do Jeruzaléma, ano i dary drahé Ezechiášovi králi Judskému, tak že potom vznešen jest u všech národů.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558092,54,14,32,24,'V těch dnech roznemohl se Ezechiáš až k smrti, i modlil se Hospodinu. Kterýž promluvil k němu, a ukázal mu zázrak.'),
(1558093,54,14,32,25,'Ale Ezechiáš nebyl vděčen dobrodiní sobě učiněného, nebo pozdvihlo se srdce jeho. Pročež povstala proti němu prchlivost, i proti Judovi a Jeruzalému.'),
(1558094,54,14,32,26,'Ale když se pokořil Ezechiáš pro to pozdvižení srdce svého i s obyvateli Jeruzalémskými, nepřišla na ně prchlivost Hospodinova za dnů Ezechiášových.'),
(1558095,54,14,32,27,'Měl pak Ezechiáš bohatství a slávu velmi velikou; nebo nashromáždil sobě pokladů stříbra a zlata i kamení drahého a vonných věcí, i pavéz i všelijakých klénotů.'),
(1558096,54,14,32,28,'A měl špižírny pro úrody obilí, mstu, oleje, i stáje pro všeliká hovada a chlévy pro dobytek.'),
(1558097,54,14,32,29,'Města také zdělal sobě, a měl bravů a skotů množství; nebo Bůh dal jemu zboží náramně veliké.'),
(1558098,54,14,32,30,'Tentýž Ezechiáš zasypal tok vody Gihonu hořejší, a přímo vedl jej dolů k západní straně města Davidova, a šťastně se vedlo Ezechiášovi ve všech skutcích jeho.'),
(1558099,54,14,32,31,'Toliko při poselství knížat Babylonských poslaných k němu, aby se vyptali na zázrak, kterýž se byl stal v zemi, opustil ho Bůh, aby ho zkusil, aby známé bylo všecko, co bylo v srdci jeho.'),
(1558100,54,14,32,32,'Jiné pak věci Ezechiášovy i pobožnost jeho zapsány jsou v proroctví Izaiáše proroka syna Amosova, a v knize o králích Judských a Izraelských.'),
(1558101,54,14,32,33,'I usnul Ezechiáš s otci svými, a pochovali jej výše nad hroby potomků Davidových, a učinili jemu poctivost při smrti jeho všecken Juda i obyvatelé Jeruzalémští. A kraloval Manasses syn jeho místo něho.'),
(1558102,54,14,33,1,'Ve dvanácti letech byl Manasses, když počal kralovati, a padesáte pět let kraloval v Jeruzalémě.'),
(1558103,54,14,33,2,'Činil pak to, což jest zlého před očima Hospodinovýma, vedlé ohavností těch národů, kteréž Hospodin vyhnal před syny Izraelskými.'),
(1558104,54,14,33,3,'Nebo vzdělal zase výsosti, kteréž byl rozbořil Ezechiáš otec jeho, a vystavěl oltáře Bálům, a vysadil háje, a klaněje se všemu vojsku nebeskému, sloužil jim.'),
(1558105,54,14,33,4,'Vzdělal také oltáře v domě Hospodinově, o němž byl řekl Hospodin: V Jeruzalémě bude jméno mé na věky.'),
(1558106,54,14,33,5,'Vzdělal, pravím, oltáře všemu vojsku nebeskému ve dvou síních domu Hospodinova.'),
(1558107,54,14,33,6,'Přesto dal provoditi syny své skrze oheň v údolí Benhinnom, a šetřil času, s hadačstvím a s kouzly se obíral, a nařídil zaklinače a čarodějníky, a mnoho zlého páchal před očima Hospodinovýma, popouzeje ho.'),
(1558108,54,14,33,7,'Postavil také obraz rytý, kterýž byl udělal, v domě Božím, o kterémž byl řekl Bůh Davidovi a Šalomounovi synu jeho: V domě tomto a v Jeruzalémě, kterýž jsem vyvolil ze všech pokolení Izraelských, oslavím jméno své na věky.'),
(1558109,54,14,33,8,'Aniž více pohnu nohou lidu Izraelského z země, kterouž jsem oddělil otcům vašim, jen toliko budou-li šetřiti, aby plnili všecko to, což jsem jim přikázal, všecken zákon, ustanovení a soudy skrze Mojžíše vydané.'),
(1558110,54,14,33,9,'Ale Manasses uvedl v blud Judské i obyvatele Jeruzalémské, tak že činili horší věci nežli ti národové, kteréž vyplénil Hospodin před tváří synů Izraelských.'),
(1558111,54,14,33,10,'A ačkoli mluvil Hospodin k Manassesovi a k lidu jeho, oni však nepozorovali.'),
(1558112,54,14,33,11,'Pročež přivedl na ně Hospodin hejtmany vojska krále Assyrského, kteříž jali Manassesa v trní, a svázavše ho dvěma řetězy ocelivými, dovedli jej do Babylona.'),
(1558113,54,14,33,12,'Tam pak jsa sevřín, modlil se Hospodinu Bohu svému, a ponižoval se velmi před oblíčejem Boha otců svých,'),
(1558114,54,14,33,13,'A modlil se jemu. I naklonil se k němu, a vyslyšel modlitbu jeho, a uvedl jej zase do Jeruzaléma do království jeho. Tehdy poznal Manasses, že sám Hospodin jest Bohem.'),
(1558115,54,14,33,14,'A potom vystavěl zed zevnitřní města Davidova k západní straně Gihonu potoku, až kudy se chodí k bráně rybné, a obehnal Ofel, a vyhnal ji velmi vysoko. Rozsadil také hejtmany vojska po všech městech hrazených v Judstvu.'),
(1558116,54,14,33,15,'Vymetal také bohy cizí a rytinu z domu Hospodinova, a všecky oltáře, kterýchž byl nadělal na hoře domu Hospodinova i v Jeruzalémě, a vyházel za město.'),
(1558117,54,14,33,16,'Opravil zase i oltář Hospodinův, a obětoval na něm oběti pokojné a díkčinění, a přikázal Judským, aby sloužili Hospodinu Bohu Izraelskému.'),
(1558118,54,14,33,17,'A však vždy ještě lid obětoval na výsostech, ale toliko Hospodinu Bohu svému.'),
(1558119,54,14,33,18,'Jiné pak věci Manassesovy, i modlitba jeho k Bohu jeho, a slova proroků, kteříž mluvívali k němu ve jménu Hospodina Boha Izraelského, to vše zapsáno v knize o králích Izraelských.'),
(1558120,54,14,33,19,'Modlitba pak jeho i to, že vyslyšán jest, a každý hřích jeho, i přestoupení jeho, i místa, na kterýchž byl postavil výsosti, a zdělal háje a rytiny, ještě prvé než se pokořil, to vše zapsáno jest v knihách Chozai.'),
(1558121,54,14,33,20,'I usnul Manasses s otci svými, a pochovali jej v domě jeho, a kraloval Amon syn jeho místo něho.'),
(1558122,54,14,33,21,'Ve dvamecítma letech byl Amon, když počal kralovati, a dvě létě kraloval v Jeruzalémě.'),
(1558123,54,14,33,22,'I činil to, což jest zlého před očima Hospodinovýma, tak jako byl činil Manasses otec jeho; nebo všechněm rytinám, kterýchž byl nadělal Manasses otec jeho, obětoval Amon a sloužil jim.'),
(1558124,54,14,33,23,'Aniž se ponížil před Hospodinem, jako se ponížil Manasses otec jeho, nýbrž on Amon mnohem více hřešil.'),
(1558125,54,14,33,24,'Spuntovali se pak proti němu služebníci jeho, a zamordovali jej v domě jeho.'),
(1558126,54,14,33,25,'Tedy pobil lid země všecky ty, kteříž se byli spuntovali proti králi Amonovi, a ustanovil lid země krále Joziáše syna jeho místo něho.'),
(1558127,54,14,34,1,'V osmi letech byl Joziáš, když kralovati počal, a kraloval jedno a třidceti let v Jeruzalémě.'),
(1558128,54,14,34,2,'Ten činil to, což jest pravého před očima Hospodinovýma, chodě po cestách Davida otce svého, a neuchýlil se na pravo ani na levo.'),
(1558129,54,14,34,3,'Léta zajisté osmého kralování svého, když ještě mládenček byl, počal hledati Boha Davida otce svého, dvanáctého pak léta počal vyčišťovati Judy a Jeruzaléma od výsostí, hájů, rytin a slitin.'),
(1558130,54,14,34,4,'Nebo u přítomnosti jeho rozbořili oltáře Bálů, i obrazy slunečné, kteříž byli na nich, zpodtínal. Též i háje a rytiny, i slitiny zdrobil a setřel, a rozsypal po hrobích těch, kteříž jim obětovávali.'),
(1558131,54,14,34,5,'Kosti pak kněží popálil na oltářích jejich, a vyčistil Judu a Jeruzalém,'),
(1558132,54,14,34,6,'Též i města v pokolení Manasses, Efraim a Simeon, až i Neftalím i pustiny jejich vůkol.'),
(1558133,54,14,34,7,'A tak zkazil oltáře a háje, a rytiny stroskotal na kusy, a všecky obrazy slunečné vysekal po vší zemi Izraelské. Potom navrátil se do Jeruzaléma.'),
(1558134,54,14,34,8,'Léta pak osmnáctého kralování svého, když vyčistil zemi a dům Boží, poslal Safana syna Azaliášova, a Maaseiáše úředníka města, aJoacha syna Joachazova kanclíře, aby opraven byl dům Hospodina Boha jeho.'),
(1558135,54,14,34,9,'Kteříž přišedše k Helkiášovi knězi nejvyššímu, dali peníze snesené do domu Božího, kteréž byli Levítové vrátní vybrali od Manassesa a Efraima, i ode všech ostatků Izraelských, i od všeho Judy a Beniamina, a navrátili se do Jeruzaléma.'),
(1558136,54,14,34,10,'Dali je pak v ruce správců toho díla, kteříž představeni byli nad domem Hospodinovým, a ti vydávali je dělníkům, jenž dělali v domě Hospodinově, opravujíce a utvrzujíce jej.'),
(1558137,54,14,34,11,'I dali tesařům a stavitelům, aby najednali kamení tesaného, a dříví k vazbám i k trámům domů, kteréž byli zbořili králové Judští.'),
(1558138,54,14,34,12,'Muži pak ti věrně se měli při té práci, nad nimiž ustanoveni Jachat a Abdiáš Levítové z synů Merari, Zachariáš a Mesullam z synů Kahat, aby s pilností přídrželi k práci. A z těch Levítů každý uměl hráti na nástroje muzické.'),
(1558139,54,14,34,13,'Ale nad nosiči, i kteříž přídrželi dělníky ke všeliké práci, byli z Levítů písaři, úředníci a vrátní.'),
(1558140,54,14,34,14,'A když vynášeli peníze, kteréž byli sneseny do domu Hospodinova, našel Helkiáš kněz knihu zákona Hospodinova vydaného skrze Mojžíše.'),
(1558141,54,14,34,15,'I řekl Helkiáš k Safanovi písaři: Knihu zákona nalezl jsem v domě Hospodinově. I dal Helkiáš tu knihu Safanovi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558142,54,14,34,16,'Safan pak přinesl tu knihu králi, a při tom jemu oznámil, řka: Všecko, cožkoli bylo poručeno služebníkům tvým, dělají.'),
(1558143,54,14,34,17,'Nebo sebravše peníze, což se jich koli nalezlo v domě Hospodinově, vydali je v ruce úředníkům a dělníkům.'),
(1558144,54,14,34,18,'Oznámil také Safan písař králi, řka: Knihu mi dal Helkiáš kněz. I četl v ní Safan před králem.'),
(1558145,54,14,34,19,'Pročež když slyšel král slova zákona, roztrhl roucho své.'),
(1558146,54,14,34,20,'A rozkázal král Helkiášovi, též Achikamovi synu Safanovu, a Abdonovi synu Míchovu, a Safanovi písaři, a Asaiášovi služebníku královskému, řka:'),
(1558147,54,14,34,21,'Jděte, poraďte se s Hospodinem o mne i o pozůstalý lid Izraelský a Judský, z strany slov knihy této, kteráž jest nalezena; nebo veliký jest hněv Hospodinův, kterýž jest vylit na nás, proto že neostříhali otcové naši slova Hospodinova, aby činili všecko, což psáno jest v knize této.'),
(1558148,54,14,34,22,'Tedy šli, Helkiáš a kteříž byli při králi, k Chuldě prorokyni, manželce Salluma syna Tekue, syna Chasrova, strážného nad rouchem, nebo bydlila v Jeruzalémě na druhé straně, a mluvili k ní ty věci.'),
(1558149,54,14,34,23,'Kteráž řekla jim: Toto praví Hospodin Bůh Izraelský: Povězte muži tomu, kterýž poslal vás ke mně,'),
(1558150,54,14,34,24,'Takto praví Hospodin: Aj, já uvedu zlé věci na toto místo a na obyvatele jeho, všecka zlořečení napsaná v knize té, kterouž čtli před králem Judským,'),
(1558151,54,14,34,25,'Proto že opustili mne a kadili bohům cizím, aby mne popouzeli všemi skutky rukou svých. Z té příčiny vylita bude prchlivost má na toto místo, aniž bude uhašena.'),
(1558152,54,14,34,26,'Králi pak Judskému, kterýž poslal vás, abyste se tázali Hospodina, takto povíte: Toto praví Hospodin Bůh Izraelský o slovích těch, kteráž jsi slyšel:'),
(1558153,54,14,34,27,'Poněvadž obměkčeno jest srdce tvé, a ponížil jsi se před tváří Boží, kdyžs slyšel slova jeho proti místu tomuto a proti obyvatelům jeho, a ponižuje se přede mnou, roztrhl jsi roucho své, a plakals přede mnou, i já vyslyšel jsem tě, praví Hospodin.'),
(1558154,54,14,34,28,'Aj, já připojím tě k otcům tvým, a pochován budeš v hrobích svých v pokoji, aby neviděly oči tvé ničeho z toho zlého, kteréž já uvedu na místo toto a na obyvatele jeho. I oznámili králi tu řeč.'),
(1558155,54,14,34,29,'Tedy poslav král, shromáždil všecky starší Judské a Jeruzalémské.'),
(1558156,54,14,34,30,'A vstoupil král do domu Hospodinova, a všickni muži Judští i obyvatelé Jeruzalémští, kněží, Levítové a všecken lid od velikého až do malého, i četl, aby všickni slyšeli všecka slova knihy smlouvy, kteráž byla nalezena v domě Hospodinově.'),
(1558157,54,14,34,31,'Potom stoje král na místě svém, učinil smlouvu před Hospodinem, že bude následovati Hospodina, a ostříhati přikázaní jeho i svědectví jeho a ustanovení jeho z celého srdce svého a ze vší duše své, a plniti slova smlouvy té, kteráž jsou v té knize zapsána.'),
(1558158,54,14,34,32,'I rozkázal, aby k témuž každý stál, kdož by koli nalezen byl v Jeruzalémě a v Beniaminovi. I činili obyvatelé Jeruzalémští podlé smlouvy Boží, Boha otců svých.'),
(1558159,54,14,34,33,'Tehdáž také vyprázdnil Joziáš všecky ohavnosti ze všech zemí synů Izraelských, a přídržel všecky, kteřížkoli byli v Izraeli, k tomu, aby sloužili Hospodinu Bohu svému. Po všecky dny jeho neodstoupili od následování Hospodina Boha otců svých.'),
(1558160,54,14,35,1,'Slavil také Joziáš v Jeruzalémě velikunoc Hospodinu, a zabili beránka velikonočního čtrnáctého dne měsíce prvního.'),
(1558161,54,14,35,2,'A postaviv kněží v strážech jejich, utvrdil je v přisluhování domu Hospodinova.'),
(1558162,54,14,35,3,'I řekl Levítům, kteříž připravovali za všecken lid Izraelský věci svaté Hospodinu: Vneste truhlu svatosti do domu, kterýž ustavěl Šalomoun syn Davidův, král Izraelský. Nebudeť vám břemenem na ramenou. A tak nyní služte Hospodinu Bohu svému a lidu jeho Izraelskému.'),
(1558163,54,14,35,4,'A připravte se po čeledech otců svých, po třídách svých, tak jakž nařídil David král Izraelský, a podlé nařízení Šalomouna syna jeho.'),
(1558164,54,14,35,5,'A stůjte v svatyni podlé rozdílu čeledí otcovských, bratří národu svého, a podlé rozdělení každé čeledi otcovské Levítů.'),
(1558165,54,14,35,6,'A tak zabíte beránka, a posvěťte se, a připravte bratřím svým, chovajíce se vedlé slova Hospodinova vydaného skrze Mojžíše.'),
(1558166,54,14,35,7,'Daroval pak Joziáš všemu množství z stáda beránků a kozelců, vše k obětem velikonočním, podlé toho všeho, jakž postačovalo, v počtu třidcet tisíců, a skotů tři tisíce, to vše z statku královského.'),
(1558167,54,14,35,8,'Knížata jeho také k lidu, kněžím i Levítům štědře se ukázali: Helkiáš, Zachariáš a Jechiel, přední v domě Božím, dali kněžím k obětem velikonočním dva tisíce a šest set bravů a skotů tři sta.'),
(1558168,54,14,35,9,'Konaniáš pak s Semaiášem a Natanaelem bratřími svými, též Chasabiáš, Jehiel, Jozabad, přední z Levítů, darovali jiným Levítům k obětem velikonočním pět tisíc bravů a skotů pět set.'),
(1558169,54,14,35,10,'A když připraveno bylo všecko k službě, stáli kněží na místě svém, a Levítové v třídách svých, podlé rozkazu královského.'),
(1558170,54,14,35,11,'I zabíjeli beránky velikonoční, kněží pak kropili krví, berouce z rukou jejich, a Levítové vytahovali z koží.'),
(1558171,54,14,35,12,'Tedy oddělili zápal, aby dali lidu podlé rozdělení domů čeledí otcovských, tak aby obětováno bylo Hospodinu, jakž psáno jest v knize Mojžíšově. Tolikéž i s voly učinili.'),
(1558172,54,14,35,13,'I pekli beránky velikonoční ohněm podlé obyčeje, ale jiné věci posvěcené vařili v hrncích, v kotlících a v pánvicích, a rozdávali rychle všemu lidu.'),
(1558173,54,14,35,14,'Potom pak připravili sobě a kněžím. Nebo kněží, synové Aronovi, zápaly a tuky až do noci obětovali, protož Levítové připravili sobě i kněžím, synům Aronovým.'),
(1558174,54,14,35,15,'Též i zpěváci, synové Azafovi, stáli na místě svém podlé rozkázaní Davidova Azafovi, Hémanovi i Jedutunovi, proroku královskému, vydaného. Vrátní také při jedné každé bráně neměli odcházeti od své povinnosti, pročež bratří jejich Levítové jiní strojili jim.'),
(1558175,54,14,35,16,'A tak nastrojena byla všecka služba Hospodinova v ten den, v slavení hodu beránka a obětování oběti zápalné na oltáři Hospodinovu, podlé rozkázaní krále Joziáše.'),
(1558176,54,14,35,17,'I slavili synové Izraelští, což se jich našlo, hod beránka v ten čas a slavnost přesnic za sedm dní.'),
(1558177,54,14,35,18,'Nebyla pak slavena velikanoc té podobná v Izraeli ode dnů Samuele proroka, aniž který z králů Izraelských slavil hodu beránka podobného tomu, kterýž slavil Joziáš s kněžími a Levíty, i se vším lidem Judským a Izraelským, což se ho našlo, i s obyvateli Jeruzalémskými.'),
(1558178,54,14,35,19,'Osmnáctého léta kralování Joziášova slaven byl ten hod beránka.'),
(1558179,54,14,35,20,'Potom po všem, když již spravil Joziáš dům Boží, přitáhl Nécho král Egyptský, aby bojoval proti Charkemis podlé Eufraten, Joziáš pak vytáhl proti němu.'),
(1558180,54,14,35,21,'Kterýž ač poslal k němu posly, řka: Já nic nemám s tebou činiti, králi Judský. Ne proti tobě, slyš ty, dnes táhnu, ale proti domu, kterýž se mnou bojuje, kamž mi rozkázal Bůh, abych pospíšil. Nebojuj s Bohem, kterýž se mnou jest, ať tě neshladí:'),
(1558181,54,14,35,22,'Joziáš však neodvrátil tváři své od něho, ale aby bojoval s ním, změnil oděv svůj, aniž uposlechl slov Néchových, pošlých z úst Božích. A tak přitáhl, aby se s ním potýkal na poli Mageddo.'),
(1558182,54,14,35,23,'I postřelili střelci krále Joziáše. Tedy řekl král služebníkům svým: Odvezte mne, neboť jsem velmi nemocen.'),
(1558183,54,14,35,24,'Takž přenesli jej služebníci jeho z toho vozu, a vložili ho na druhý vůz, kterýž měl, a dovezli jej do Jeruzaléma. I umřel a pochován jest v hrobích otců svých. I plakal všecken Juda a Jeruzalém nad Joziášem.'),
(1558184,54,14,35,25,'Naříkal také i Jeremiáš nad Joziášem, a zpívávali všickni zpěváci a zpěvakyně v naříkáních svých o Joziášovi až do dnešního dne, kteráž uvedli v obyčej Izraeli. A ta jsou zapsána v pláči Jeremiášovu.'),
(1558185,54,14,35,26,'Jiné pak věci Joziášovy, i pobožnost jeho, jakž napsáno jest v zákoně Hospodinově,'),
(1558186,54,14,35,27,'I skutkové jeho první i poslední, to vše zapsáno jest v knize o králích Izraelských a Judských.'),
(1558187,54,14,36,1,'Tedy vzal lid země Joachaza syna Joziášova, a ustanovili ho králem na místě otce jeho v Jeruzalémě.'),
(1558188,54,14,36,2,'Ve třimecítma letech byl Joachaz, když počal kralovati, a tři měsíce kraloval v Jeruzalémě.'),
(1558189,54,14,36,3,'Nebo vzal jej král Egyptský z Jeruzaléma, a uložil na zemi pokutu sto centnéřů stříbra a centnéř zlata.'),
(1558190,54,14,36,4,'A ustanovil král Egyptský Eliakima bratra jeho nad Judou a Jeruzalémem za krále, a proměnil mu jméno jeho, aby sloul Joakim. Joachaza pak bratra jeho vzal Nécho, a zavedl ho do Egypta.'),
(1558191,54,14,36,5,'V pětmecítma letech byl Joakim, když počal kralovati, a jedenáct let kraloval v Jeruzalémě. A když činil to, což jest zlého před očima Hospodina Boha svého,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558192,54,14,36,6,'Přitáhl proti němu Nabuchodonozor král Babylonský, a svázal jej řetězy ocelivými, aby jej zavedl do Babylona.'),
(1558193,54,14,36,7,'Nádoby také domu Hospodinova zavezl Nabuchodonozor do Babylona, a dal je do chrámu svého v Babyloně.'),
(1558194,54,14,36,8,'Jiné pak věci Joakimovy i ohavnosti jeho, kteréž páchal, i což se nalézalo při něm, to vše zapsáno jest v knize o králích Izraelských a Judských. I kraloval Joachin syn jeho místo něho.'),
(1558195,54,14,36,9,'V osmi letech byl Joachin, když kralovati počal, a kraloval tři měsíce a deset dní v Jeruzalémě, a činil to, což bylo zlého před očima Hospodinovýma.'),
(1558196,54,14,36,10,'Potom pak po roce poslal král Nabuchodonozor, a dal ho zavésti do Babylona s klénoty domu Hospodinova, a ustanovil králem Sedechiáše, příbuzného jeho, nad Judou a Jeruzalémem.'),
(1558197,54,14,36,11,'V jedenmecítma letech byl Sedechiáš, když počal kralovati, a jedenáct let kraloval v Jeruzalémě.'),
(1558198,54,14,36,12,'I činil to, což jest zlého před očima Hospodina Boha svého, aniž se pokořil před Jeremiášem prorokem mluvícím řeč Hospodinovu.'),
(1558199,54,14,36,13,'Nýbrž i Nabuchodonozorovi králi se zprotivil, jenž ho byl přísahou zavázal skrze Boha, a zatvrdiv šíji svou, urputně uložil v srdci svém, aby se nenavracoval k Hospodinu Bohu Izraelskému.'),
(1558200,54,14,36,14,'Ano i všecka knížata, kněží i lid v mnohá přestoupení se vydali, podlé všech ohavností pohanských, a poškvrnili domu Hospodinova, jehož byl posvětil v Jeruzalémě.'),
(1558201,54,14,36,15,'A když posílal Hospodin Bůh otců jejich k nim posly své, ráno vstávaje a posílaje, proto že se přívětivě měl k lidu svému a k příbytku svému:'),
(1558202,54,14,36,16,'Posmívali se poslům Božím, a pohrdali slovy jeho, a za svůdce měli proroky jeho, až se rozpálila prchlivost Hospodinova na lid jeho, tak aby nebylo žádného uléčení.'),
(1558203,54,14,36,17,'I přivedl na ně krále Kaldejského, kterýž zmordoval mládence jejich mečem v domě svatyně jejich, a neodpustil mládenci ani panně, starci ani kmeti. Všecky dal v ruku jeho.'),
(1558204,54,14,36,18,'K tomu i všecky nádoby domu Božího, veliké i malé, i poklady domu Hospodinova, i poklady královské i knížat jeho, všecko zavezl do Babylona.'),
(1558205,54,14,36,19,'A vypálili dům Boží, a zbořili zed Jeruzalémskou, též i všecky paláce v něm popálili, ano i všelijaké klénoty drahé v něm zkazili.'),
(1558206,54,14,36,20,'A což jich pozůstalo po meči, to převedl do Babylona, a byli služebníci jeho i synů jeho, dokudž nekraloval král Perský,'),
(1558207,54,14,36,21,'Aby se naplnila řeč Hospodinova skrze ústa Jeremiášova, dokudž země nevykonala sobot svých; po všecky dny, pokudž byla pustá, odpočívala, až se vyplnilo sedmdesáte let.'),
(1558208,54,14,36,22,'Potom léta prvního Cýra krále Perského, aby se naplnila řeč Hospodinova skrze ústa Jeremiášova, vzbudil Hospodin ducha Cýrova krále Perského. Kterýž dal provolati po všem království svém, ano také i rozepsal, řka:'),
(1558209,54,14,36,23,'Toto praví Cýrus král Perský: Všecka království země dal mi Hospodin Bůh nebeský, a ten mi poručil, abych mu vystavěl dům v Jeruzalémě, kterýž jest v Judstvu. Kdo jest mezi vámi ze všeho lidu jeho, Hospodin Bůh jeho budiž s ním, a ať jde.'),
(1558210,54,15,1,1,'Léta prvního Cýra krále Perského, aby se naplnila řeč Hospodinova skrze ústa Jeremiášova, vzbudil Hospodin ducha Cýrova krále Perského, aby dal provolati po všem království svém, ano také i rozepsal, řka:'),
(1558211,54,15,1,2,'Toto praví Cýrus král Perský: Všecka království země dal mi Hospodin Bůh nebeský, a on mi poručil, abych mu vystavěl dům v Jeruzalémě, kterýž jest v Judstvu.'),
(1558212,54,15,1,3,'Kdo jest mezi vámi ze všeho lidu jeho, budiž Bůh jeho s ním, a nechať jde do Jeruzaléma, kterýž jest v Judstvu, a staví dům Hospodina Boha Izraelského, toho Boha, kterýž jest v Jeruzalémě.'),
(1558213,54,15,1,4,'Kdož by pak zůstal na kterémkoli místě, kdež jest pohostinu, lidé místa toho ať mu pomohou stříbrem a zlatem, statkem i hovady, mimo oběti dobrovolné k domu Božímu, kterýž jest v Jeruzalémě.'),
(1558214,54,15,1,5,'I povstali přední z čeledí otců z pokolení Judova a Beniaminova, kněží také a Levítové i každý, číhož ducha vzbudil Bůh, aby šli k stavení domu Hospodinova, kterýž jest v Jeruzalémě.'),
(1558215,54,15,1,6,'Jimž všickni ti, kteříž bydlili okolo nich, pomáhali nádobami stříbrnými a zlatými, statkem i hovady, a věcmi drahými, mimo všecko, což dobrovolně obětováno bylo.'),
(1558216,54,15,1,7,'Král také Cýrus vydal nádoby domu Hospodinova, kteréž byl pobral Nabuchodonozor z Jeruzaléma, a dal je byl do domu Boha svého.'),
(1558217,54,15,1,8,'Vydal je pak Cýrus král Perský skrze Mitridata správce nad poklady, kterýž je vyčtl Sesbazarovi knížeti Judskému.'),
(1558218,54,15,1,9,'A tento jest počet jejich: Medenic zlatých třidceti, medenic stříbrných tisíc, nožů devětmecítma.'),
(1558219,54,15,1,10,'Koflíků zlatých třidceti, koflíků stříbrných prostějších čtyři sta a deset, nádob jiných na tisíce.'),
(1558220,54,15,1,11,'Všech nádob zlatých i stříbrných pět tisíc a čtyři sta. Všecko to odnesl Sesbazar, když se stěhoval lid zajatý z Babylona do Jeruzaléma.'),
(1558221,54,15,2,1,'Tito pak jsou lidé té krajiny, kteříž se z zajetí a přestěhování toho brali, jakž je byl přestěhoval Nabuchodonozor král Babylonský do Babylona, a navrátili se do Jeruzaléma a do Judstva, jeden každý do města svého,'),
(1558222,54,15,2,2,'Kteříž přišli s Zorobábelem, s Jesua, s Nehemiášem, Saraiášem, Reelaiášem, Mardocheem, Bilsanem, Misparem, Bigvajem, Rechumem a Baanou. Počet mužů z lidu Izraelského:'),
(1558223,54,15,2,3,'Synů Farosových dva tisíce, sto sedmdesáte dva.'),
(1558224,54,15,2,4,'Synů Sefatiášových tři sta sedmdesáte dva.'),
(1558225,54,15,2,5,'Synů Arachových sedm set sedmdesát pět.'),
(1558226,54,15,2,6,'Synů Pachat Moábových, synů Jesue a Joábových dva tisíce, osm set a dvanácte.'),
(1558227,54,15,2,7,'Synů Elamových tisíc, dvě stě padesáte čtyři.'),
(1558228,54,15,2,8,'Synů Zattuových devět set čtyřidceti pět.'),
(1558229,54,15,2,9,'Synů Zakkai sedm set a šedesát.'),
(1558230,54,15,2,10,'Synů Báni šest set čtyřidceti dva.'),
(1558231,54,15,2,11,'Synů Bebai šest set třimecítma.'),
(1558232,54,15,2,12,'Synů Azgadových tisíc, dvě stě dvamecítma.'),
(1558233,54,15,2,13,'Synů Adonikamových šest set šedesáte šest.'),
(1558234,54,15,2,14,'Synů Bigvai dva tisíce, padesáte šest.'),
(1558235,54,15,2,15,'Synů Adinových čtyři sta padesáte čtyři.'),
(1558236,54,15,2,16,'Synů Aterových z Ezechiáše devadesát osm.'),
(1558237,54,15,2,17,'Synů Bezai tři sta třimecítma.'),
(1558238,54,15,2,18,'Synů Jorahových sto a dvanácte.'),
(1558239,54,15,2,19,'Synů Chasumových dvě stě třimecítma.'),
(1558240,54,15,2,20,'Synů Gibbarových devadesáte pět.'),
(1558241,54,15,2,21,'Synů Betlémských sto třimecítma.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558242,54,15,2,22,'Mužů Netofatských padesáte šest.'),
(1558243,54,15,2,23,'Mužů Anatotských sto osmmecítma.'),
(1558244,54,15,2,24,'Synů Azmavetských čtyřidceti dva.'),
(1558245,54,15,2,25,'Synů Kariatarimských, Kafirských a Berotských sedm set čtyřidceti a tři.'),
(1558246,54,15,2,26,'Synů Ráma a Gabaa šest set jedenmecítma.'),
(1558247,54,15,2,27,'Mužů Michmas sto dvamecítma.'),
(1558248,54,15,2,28,'Mužů z Bethel a Hai dvě stě třimecítma.'),
(1558249,54,15,2,29,'Synů z Nébo padesáte dva.'),
(1558250,54,15,2,30,'Synů Magbisových sto padesáte šest.'),
(1558251,54,15,2,31,'Synů Elama druhého tisíc, dvě stě padesáte čtyři.'),
(1558252,54,15,2,32,'Synů Charimových tři sta dvadceti.'),
(1558253,54,15,2,33,'Synů Lodových, Chadidových a Onových sedm set dvadceti pět.'),
(1558254,54,15,2,34,'Synů Jerecho tři sta čtyřidceti pět.'),
(1558255,54,15,2,35,'Synů Senaa tři tisíce, šest set a třidceti.'),
(1558256,54,15,2,36,'Kněží, synů Jedaiášových z domu Jesua, devět set sedmdesáte tři.'),
(1558257,54,15,2,37,'Synů Immerových tisíc, padesáte dva.'),
(1558258,54,15,2,38,'Synů Paschurových tisíc, dvě stě čtyřidceti sedm.'),
(1558259,54,15,2,39,'Synů Charimových tisíc a sedmnácte.'),
(1558260,54,15,2,40,'Levítů, synů Jesua a Kadmiele, synů Hodaviášových, sedmdesáte čtyři.'),
(1558261,54,15,2,41,'Zpěváků, synů Azafových, sto dvadceti osm.'),
(1558262,54,15,2,42,'Synů vrátných, synů Sallumových, synů Aterových, synů Talmonových, synů Akkubových, synů Chatita, synů Sobai, všech sto třidceti devět.'),
(1558263,54,15,2,43,'Netinejských, synů Zicha, synů Chasufa, synů Tabbaot,'),
(1558264,54,15,2,44,'Synů Keros, synů Siaha, synů Fádon,'),
(1558265,54,15,2,45,'Synů Lebana, synů Chagaba, synů Akkub,'),
(1558266,54,15,2,46,'Synů Chagab, synů Samlai, synů Chanan,'),
(1558267,54,15,2,47,'Synů Giddel, synů Gachar, synů Reaia,'),
(1558268,54,15,2,48,'Synů Rezin, synů Nekoda, synů Gazam,'),
(1558269,54,15,2,49,'Synů Uza, synů Paseach, synů Besai,'),
(1558270,54,15,2,50,'Synů Asna, synů Meunim, synů Nefusim,'),
(1558271,54,15,2,51,'Synů Bakbuk, synů Chakufa, synů Charchur,'),
(1558272,54,15,2,52,'Synů Bazlut, synů Mechida, synů Charsa,'),
(1558273,54,15,2,53,'Synů Barkos, synů Sisera, synů Tamach,'),
(1558274,54,15,2,54,'Synů Neziach, synů Chatifa,'),
(1558275,54,15,2,55,'Synů služebníků Šalomounových, synů Sotai, synů Soferet, synů Feruda,'),
(1558276,54,15,2,56,'Synů Jaala, synů Darkon, synů Giddel,'),
(1558277,54,15,2,57,'Synů Sefatiášových, synů Chattil, synů Pocheret Hazebaim, synů Ami,'),
(1558278,54,15,2,58,'Všech Netinejských a synů služebníků Šalomounových tři sta devadesáte dva.'),
(1558279,54,15,2,59,'Tito také byli, kteříž šli z Telmelach, Telcharsa, Cherub, Addan a Immer, ale nemohli ukázati domu otců svých a semene svého, že by z Izraele byli:'),
(1558280,54,15,2,60,'Synů Delaiášových, synů Tobiášových, synů Nekodových šest set padesáte dva.'),
(1558281,54,15,2,61,'A z synů kněžských synové Chabaiášovi, synové Kózovi, synové Barzillai, kterýž pojav sobě ze dcer Barzillai Galádského manželku, nazván jest jménem jejich.'),
(1558282,54,15,2,62,'Ti vyhledávali zapsání o sobě, chtíce prokázati rod svůj, ale nenašlo se. Protož zbaveni jsou kněžství.'),
(1558283,54,15,2,63,'A zapověděl jim Tirsata, aby nejedli z věcí svatosvatých, dokudž by nestál kněz s urim a thumim.'),
(1558284,54,15,2,64,'Všeho toho shromáždění pospolu čtyřidceti a dva tisíce, tři sta šedesáte,'),
(1558285,54,15,2,65,'Kromě služebníků jejich, a děvek jejich, jichž bylo sedm tisíc, tři sta třidceti sedm. A mezi nimi bylo zpěváků a zpěvakyní dvě stě.'),
(1558286,54,15,2,66,'Koní jejich sedm set třidceti šest, mezků jejich dvě stě čtyřidceti pět.'),
(1558287,54,15,2,67,'Velbloudů jejich čtyři sta třidceti pět, oslů šest tisíc, sedm set a dvadceti.'),
(1558288,54,15,2,68,'Z knížat pak čeledí otcovských, někteří, když přišli k domu Hospodinovu, kterýž byl v Jeruzalémě, dobrovolně se oddavše, aby stavěli dům Boží na gruntech jeho,'),
(1558289,54,15,2,69,'Vedlé možnosti své dali náklad k dílu: Zlata jeden a šedesáte tisíc drachem, stříbra pak pět tisíc liber, a sukní kněžských sto.'),
(1558290,54,15,2,70,'A tak osadili se kněží i Levítové a někteří z lidu, i zpěváci i vrátní a Netinejští v městech svých, i všecken Izrael v městech svých.'),
(1558291,54,15,3,1,'Když pak nastal měsíc sedmý, a byli synové Izraelští v městech, shromáždil se lid jednomyslně do Jeruzaléma.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558292,54,15,3,2,'Tedy vstav Jesua syn Jozadakův s bratřími svými kněžími, a Zorobábel syn Salatielův s bratřími svými, vzdělali oltář Boha Izraelského, aby obětovali na něm oběti zápalné, jakož psáno jest v zákoně Mojžíše muže Božího.'),
(1558293,54,15,3,3,'A když postavili oltář ten na základích jeho, ačkoli se obávali národů jiných zemí, však obětovali na něm oběti zápalné Hospodinu, oběti zápalné ráno i večer.'),
(1558294,54,15,3,4,'Drželi také slavnost stánků, jakož psáno jest, obětujíce zápal na každý den, vedlé počtu a vedlé obyčeje každého dne,'),
(1558295,54,15,3,5,'A potom obět zápalnou ustavičnou, i na novměsíce i na každou slavnost Hospodinu posvěcenou, i od každého dobrovolně obětujícího dobrovolnou obět Hospodinu.'),
(1558296,54,15,3,6,'Od prvního dne toho měsíce sedmého počali obětovati zápalů Hospodinu, ačkoli chrám Hospodinův ještě nebyl založen.'),
(1558297,54,15,3,7,'I dali peníze kameníkům a řemeslníkům, též potravy a nápoje i oleje Sidonským a Tyrským, aby vezli dříví cedrové z Libánu k moři Joppen, podlé povolení jim Cýra krále Perského.'),
(1558298,54,15,3,8,'Léta pak druhého po jejich se navrácení k domu Božímu do Jeruzaléma, měsíce druhého, začali Zorobábel syn Salatielův, a Jesua syn Jozadakův, i jiní bratří jejich kněží a Levítové a všickni, kteříž byli přišli z toho zajetí do Jeruzaléma, a ustanovili Levíty od dvadcítiletých a výše, aby přihlédali k dílu domu Hospodinova.'),
(1558299,54,15,3,9,'A tak postaven jest Jesua, synové jeho i bratří jeho, Kadmiel i synové jeho, synové Judovi spolu, aby přihlédali k dílu při domě Božím, potomci Chenadadovi, synové jejich i bratří jejich Levítové.'),
(1558300,54,15,3,10,'A když zakládali grunty stavitelé chrámu Hospodinova, postavili kněží zobláčené s trubami, a Levíty, syny Azafovy s cymbály, aby chválili Hospodina vedlé nařízení Davida krále Izraelského.'),
(1558301,54,15,3,11,'I prozpěvovali jedni po druhých, chválíce a oslavujíce Hospodina, nebo dobrý jest, a že na věky trvá milosrdenství jeho nad Izraelem. Všecken také lid prokřikoval hlasem velikým, chválíce Hospodina, proto že založen byl dům Hospodinův.'),
(1558302,54,15,3,12,'Mnozí pak z kněží a z Levítů i z knížat čeledí otcovských, starci, kteříž byli viděli prvnější dům, když zakládali tento dům před očima jejich, plakali hlasem velikým. Mnozí nazpět prokřikovali s radostí hlasem velikým,'),
(1558303,54,15,3,13,'Tak že lid nemohl rozeznati hlasu prokřikování radostného od hlasu plačícího lidu; nebo lid ten prokřikoval hlasem velikým, a hlas ten slyšán byl daleko.'),
(1558304,54,15,4,1,'Uslyšavše pak nepřátelé Judovi a Beniaminovi, že by ti, kteříž přestěhováni byli, stavěli chrám Hospodinu Bohu Izraelskému,'),
(1558305,54,15,4,2,'Přistoupili k Zorobábelovi a k knížatům čeledí otcovských, a řekli jim: Budeme s vámi stavěti; nebo jako i vy hledati budeme Boha vašeho, jemuž i oběti obětujeme ode dnů Esarchaddona krále Assyrského, kterýž nás sem uvedl.'),
(1558306,54,15,4,3,'Tedy řekl jim Zorobábel a Jesua i jiná knížata čeledí otcovských z Izraele: Ne vám, ale nám náleží stavěti dům Bohu našemu; nebo my sami stavěti budeme Hospodinu Bohu Izraelskému, jakž přikázal nám král Cýrus, král Perský.'),
(1558307,54,15,4,4,'A však lid té krajiny zemdléval ruce lidu Judského, a odhrožovali je, aby nestavěli.'),
(1558308,54,15,4,5,'Anobrž i najímali proti nim rádce, aby rušili rady jejich, po všecky dny Cýra krále Perského, až do kralování Daria krále Perského.'),
(1558309,54,15,4,6,'Nebo když kraloval Asverus, při začátku kralování jeho sepsali žalobu proti obyvatelům Judským a Jeruzalémským.'),
(1558310,54,15,4,7,'(Tak jako za dnů Artaxerxa psal Bislam, Mitridates, Tabel a jiní tovaryši jeho k Artaxerxovi králi Perskému.) Písmo pak listu toho psáno bylo Syrsky, i vykládáno Syrsky.'),
(1558311,54,15,4,8,'Rechum totiž kancléř a Simsai písař napsali jeden list proti Jeruzalému Artaxerxovi králi, takový:'),
(1558312,54,15,4,9,'Rechum kancléř a Simsai písař i jiní tovaryši jejich, Dinaiští a Afarsatchaiští, Tarpelaiští, Afarzaiští, Arkevaiští, Babylonští, Susanechaiští, Dehavejští a Elmaiští,'),
(1558313,54,15,4,10,'I jiní národové, kteréž byl převedl Asnapar veliký a slavný, a rozsadil v městech Samařských, a jiní za řekou, i Cheenetští,'),
(1558314,54,15,4,11,'(Tento jest přípis listu, kterýž poslali k Artaxerxovi králi), služebníci tvoji, lidé za řekou a Cheenetští.'),
(1558315,54,15,4,12,'Známo buď králi, že Židé, kteříž se vrátili od tebe, přišedše k nám do Jeruzaléma, město odporné a škodlivé stavějí, i zdi dělají, a základy spojují.'),
(1558316,54,15,4,13,'Protož nyní buď vědomo králi, bude-li to město vystaveno, a zdi dodělány, platuť, cla a úroku dávati nebudou, a tak komoře královské újma bude.'),
(1558317,54,15,4,14,'Nyní tedy poněvadž dobrodiní paláce užíváme, na obnažování krále neslušelo se nám dívati. Tou příčinou poslali jsme a oznámili to králi,'),
(1558318,54,15,4,15,'Aby dal hledati v knihách kronik otců svých, a najdeš v nich, i zvíš, že město to jest město odporné a škodlivé králům i krajinám, a že se v něm puntovávají od starodávna, pročež to město prvé zkaženo bylo.'),
(1558319,54,15,4,16,'Nadto známoť činíme králi, že bude-li to město vystaveno, a zdi dodělány, tedy vládařství za řekou míti nebudeš.'),
(1558320,54,15,4,17,'Tedy odeslal odpověd král Rechumovi kancléři a Simsaiovi písaři i jiným tovaryšům jejich, kteříž bydlili v Samaří, a jiným za řekou v Selam i v Cheet:'),
(1558321,54,15,4,18,'Psání, kteréž jste k nám poslali, zjevně čteno jest přede mnou.'),
(1558322,54,15,4,19,'Protož rozkázal jsem, aby hledali. I nalezli, že to město zdávna povstává proti králům, a zprotivování i puntování bývají v něm.'),
(1558323,54,15,4,20,'Nadto i králové mocní že bývali v Jeruzalémě, a panovali nade vším, co jest za řekou, jimž platové, cla a úrok dáván býval.'),
(1558324,54,15,4,21,'Protož nyní přikažte, ať jest zastaveno mužům těm, aby to město nebylo staveno, dokudž by ode mne poručeno nebylo.'),
(1558325,54,15,4,22,'Hleďtež pak, abyste se v té věci nemýlili, a ať skrze to nezroste něco zlého na škodu králům.'),
(1558326,54,15,4,23,'Když pak ten přípis listu Artaxerxa krále čten byl před Rechumem a Simsaiem písařem a tovaryši jejich, odešli rychle do Jeruzaléma k Židům, a zastavili jim mocí a silou.'),
(1558327,54,15,4,24,'A tak přetrženo jest dílo domu Božího, kterýž byl v Jeruzalémě, a stálo tak až do druhého léta kralování Daria krále Perského.'),
(1558328,54,15,5,1,'Toho času prorokoval Aggeus prorok a Zachariáš syn Iddo, proroci, Židům, kteříž byli v Judstvu a v Jeruzalémě, ve jménu Boha Izraelského mluvíce k nim.'),
(1558329,54,15,5,2,'Tedy povstavše Zorobábel syn Salatielův, a Jesua syn Jozadakův, počali zase stavěti domu Božího, kterýž jest v Jeruzalémě, a byli s nimi proroci Boží, pomáhajíce jim.'),
(1558330,54,15,5,3,'Téhož času přišel k nim Tattenai, vývoda za řekou, a Setarbozenai, i tovaryši jejich, kteříž takto k nim řekli: Kdo vám poručil dům tento stavěti a zdi tyto dělati?'),
(1558331,54,15,5,4,'Tedy jsme jim řekli takto, ano i ty muže, kteří to stavení dělali, jmenovali.'),
(1558332,54,15,5,5,'Nad staršími pak Židovskými byla ochrana Boha jejich, tak že nepřekazili jim, dokudž ta věc nepřišla před Daria, jehož tehdáž odpověd přinesli o té věci.'),
(1558333,54,15,5,6,'Přípis listu, kterýž poslal Tattenai vývoda za řekou, a Setarbozenai s tovaryši svými, i Afarsechaiští, kteříž byli za řekou, k Dariovi králi.'),
(1558334,54,15,5,7,'List poslali jemu, a takto bylo psáno v něm: Dariovi králi pokoj všeliký.'),
(1558335,54,15,5,8,'Známo buď králi, že jsme přišli do Judské krajiny k domu Boha velikého. Kterýžto stavějí kamením velikým, a dříví kladou do stěn, a dílo to spěšně se staví, a daří se v rukou jejich.'),
(1558336,54,15,5,9,'Tedy otázali jsme se těch starších, a takto jsme jim řekli: Kdo vám poručil stavěti dům tento, a zdi tyto dělati?'),
(1558337,54,15,5,10,'Ano i na jména jejich ptali jsme se jich, abychom oznámili tobě, a napsali jména mužů těch, kteříž jsou přední mezi nimi.'),
(1558338,54,15,5,11,'Těmito pak slovy nám odpověděli, řkouce: My jsme služebníci Boha nebe a země, a stavíme dům, kterýž byl ustaven prvé před mnohými lety, jejž byl veliký král Izraelský stavěl i dokonal.'),
(1558339,54,15,5,12,'Ale potom, když popudili otcové naši Boha nebeského, vydal je v ruku Nabuchodonozora krále v Babyloně, Kaldejského, kterýž dům tento zbořil, a lid převedl do Babylona.'),
(1558340,54,15,5,13,'A však léta prvního Cýra krále Babylonského, Cýrus král rozkázal, aby tento Boží dům byl staven.'),
(1558341,54,15,5,14,'Nadto i nádoby domu Božího zlaté a stříbrné, kteréž byl Nabuchodonozor vynesl z chrámu, jenž byl v Jeruzalémě, a vnesl je do chrámu Babylonského, i ty vynesl Cýrus král z chrámu Babylonského, a dány jsou Sesbazarovi, jehož byl vývodou ustanovil.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558342,54,15,5,15,'A poručil mu, řka: Nádoby tyto vezma, odejdi a slož je v chrámě, kterýž jest v Jeruzalémě, a dům Boží ať stavějí na místě jeho.'),
(1558343,54,15,5,16,'Tedy Sesbazar ten přišed, založil grunty domu Božího, kterýž jest v Jeruzalémě, a od toho času až po dnes staví se, a ještě není dokonán.'),
(1558344,54,15,5,17,'Nyní tedy jestli se za dobré králi vidí, nechť se pohledá mezi poklady královskými, kteříž jsou tam v Babyloně, jest-li tak, že by Cýrus král poručil, aby staven byl dům Boží tento, kterýž jest v Jeruzalémě. Potom vůli královskou nechť nám pošle o té věci.'),
(1558345,54,15,6,1,'Tedy král Darius rozkázal, aby hledali v bibliotéce, mezi poklady složenými v Babyloně.'),
(1558346,54,15,6,2,'I nalezena jest v Achmeta na hradě, kterýž jest v Médské krajině, jedna kniha, a takto zapsána byla v ní pamět:'),
(1558347,54,15,6,3,'Léta prvního Cýra krále Cýrus král rozkázal: Dům Boží, kterýž byl v Jeruzalémě, ať jest v městě staven na místě, kdež se obětují oběti, a grunty jeho ať vzhůru ženou, zvýší loktů šedesáti, a zšíří loktů šedesáti,'),
(1558348,54,15,6,4,'Třmi řady z kamení velikého, a řad z dříví nového, náklad pak z domu královského bude dáván.'),
(1558349,54,15,6,5,'Nadto nádobí domu Božího zlaté i stříbrné, kteréž Nabuchodonozor byl pobral z chrámu, jenž byl v Jeruzalémě, a byl je přenesl do Babylona, ať zase navrátí, aby se dostalo do chrámu Jeruzalémského na místo své, a složeno bylo v domě Božím.'),
(1558350,54,15,6,6,'Protož nyní, ty Tattenai, vývodo za řekou, Setarbozenai s tovaryši svými, i Afarsechaiští, kteříž jste za řekou, ustupte odtud.'),
(1558351,54,15,6,7,'Nechte jich při díle toho domu Božího. Vůdce Židovský a starší jejich nechať ten dům Boží stavějí na místě jeho.'),
(1558352,54,15,6,8,'Ode mne také poručeno jest o tom, co byste měli činiti s staršími Židovskými při stavení toho domu Božího, totiž, aby z zboží královského, z důchodů, jenž jsou za řekou, bez meškání náklad dáván byl mužům těm, aby dílo nemělo překážky.'),
(1558353,54,15,6,9,'A to, čehož by bylo potřebí, buď volků aneb skopců i beránků k zápalným obětem Boha nebeského, obilé, soli, vína i oleje, jakž by rozkázali kněží Jeruzalémští, nechť se jim dává na každý den, a to beze všeho podvodu,'),
(1558354,54,15,6,10,'Aby měli z čeho obětovati vůni příjemnou Bohu nebeskému, a aby se modlili za život krále i za syny jeho.'),
(1558355,54,15,6,11,'Nadto ode mne jest rozkázáno: Kdož by koli zrušil přikázaní toto, aby vybořeno bylo z domu jeho dřevo, a zdviženo bylo, na němž by oběšen byl, a dům jeho ať jest hnojištěm pro takovou věc.'),
(1558356,54,15,6,12,'Bůh pak, jehož jméno tam přebývá, zkaziž všelikého krále i lid, kterýž by vztáhl ruku svou k změnění toho, a zkáze toho domu Božího, jenž jest v Jeruzalémě. Já Darius přikazuji sám, bez meškání ať se stane.'),
(1558357,54,15,6,13,'Tedy Tattenai, vývoda za řekou, a Setarbozenai s tovaryši svými vedlé toho, jakž rozkázal Darius král, tak učinili bez meškání.'),
(1558358,54,15,6,14,'I stavěli starší Židovští, a šťastně se jim vedlo vedlé proroctví Aggea proroka, a Zachariáše syna Iddova. Stavěli tedy a dokonali z rozkázaní Boha Izraelského, a z rozkázaní Cýra a Daria, a Artaxerxa krále Perského.'),
(1558359,54,15,6,15,'A dokonán jest ten dům k třetímu dni měsíce Adar, a ten byl rok šestý kralování Daria krále.'),
(1558360,54,15,6,16,'Tedy synové Izraelští, kněží a Levítové, i jiní, kteříž byli přišli z převedení, posvětili toho domu Božího s radostí.'),
(1558361,54,15,6,17,'A obětovali při posvěcení toho Božího domu sto telat, skopců dvě stě, beránků čtyři sta, a kozlů k oběti za hřích za všecken Izrael dvanáct, vedlé počtu pokolení Izraelského.'),
(1558362,54,15,6,18,'I postavili kněží v třídách jejich, a Levíty v pořádcích jejich při službě Boží v Jeruzalémě, jakož psáno jest v knize Mojžíšově.'),
(1558363,54,15,6,19,'Slavili také ti, kteříž se vrátili z přestěhování, velikunoc čtrnáctého dne měsíce prvního.'),
(1558364,54,15,6,20,'Nebo očistili se byli kněží a Levítové jednomyslně. Všickni čistí byli, a obětovali beránka velikonočního za všecky, jenž zajati byli, i za bratří své kněží, i sami za sebe.'),
(1558365,54,15,6,21,'A jedli synové Izraelští, kteříž se byli navrátili z přestěhování, i každý, kdož odděliv se od poškvrnění pohanů země, připojil se k nim, aby hledal Hospodina Boha Izraelského.'),
(1558366,54,15,6,22,'Drželi také slavnost přesnic za sedm dní s veselím, proto že je rozveselil Hospodin, a obrátil srdce krále Assyrského k nim, aby jich posilnil v díle domu Božího, Boha Izraelského.'),
(1558367,54,15,7,1,'Po těch pak věcech, za kralování Artaxerxa krále Perského, Ezdráš syn Saraiáše, syna Azariášova, syna Helkiášova,'),
(1558368,54,15,7,2,'Syna Sallumova, syna Sádochova, syna Achitobova,'),
(1558369,54,15,7,3,'Syna Amariášova, syna Azariášova, syna Meraiotova,'),
(1558370,54,15,7,4,'Syna Zerachiášova, syna Uzi, syna Bukki,'),
(1558371,54,15,7,5,'Syna Abisuova, syna Fínesova, syna Eleazarova, syna Aronova, kněze nejvyššího,'),
(1558372,54,15,7,6,'Tento Ezdráš vyšel z Babylona, a byl člověk zběhlý v zákoně Mojžíšově, kterýž dal Hospodin Bůh Izraelský, a dal mu král podlé toho, jakž ruka Hospodina Boha jeho byla s ním, všecko, zač ho koli žádal.'),
(1558373,54,15,7,7,'Vyšli také synové Izraelští a kněží, i Levítové a zpěváci, vrátní a Netinejští do Jeruzaléma, léta sedmého Artaxerxa krále.'),
(1558374,54,15,7,8,'A přišel do Jeruzaléma pátého měsíce. Tenť jest rok sedmý krále Daria.'),
(1558375,54,15,7,9,'Prvního zajisté dne měsíce prvního vyšel z Babylona, a prvního dne měsíce pátého přišel do Jeruzaléma s pomocí Boha svého.'),
(1558376,54,15,7,10,'Nebo Ezdráš byl uložil v srdci svém, aby zpytoval zákon Hospodinův i plnil jej, a aby učil lid Izraelský ustanovením a soudům.'),
(1558377,54,15,7,11,'Tento pak jest přípis listu, kterýž dal král Artaxerxes Ezdrášovi knězi umělému v zákoně, zběhlému v těch věcech, kteréž přikázal Hospodin, a v ustanoveních jeho v Izraeli:'),
(1558378,54,15,7,12,'Artaxerxes, král nad králi, Ezdrášovi knězi umělému v zákoně Boha nebeského, muži zachovalému i Cheenetským.'),
(1558379,54,15,7,13,'Ode mne jest přikázáno, kdož by koli v království mém z lidu Izraelského, a z kněží jeho i z Levítů, dobrovolně jíti chtěl s tebou do Jeruzaléma, aby šel.'),
(1558380,54,15,7,14,'Poněvadž jsi od krále a sedmi rad jeho poslán, abys dohlédal k Judstvu a k Jeruzalému podlé zákona Boha svého, kterýž máš v ruce své,'),
(1558381,54,15,7,15,'A abys donesl stříbro a zlato, kteréž král a rady jeho dobrovolně obětovali Bohu Izraelskému, jehož příbytek jest v Jeruzalémě,'),
(1558382,54,15,7,16,'A všecko stříbro a zlato, kteréhož bys dostal ve vší krajině Babylonské u těch, kteříž by z lidu dobrovolně co obětovati chtěli, i s kněžími, kteříž by dobrovolně obětovali k domu Boha svého, kterýž jest v Jeruzalémě,'),
(1558383,54,15,7,17,'Abys rychle nakoupil za to stříbro telat, skopců, beránků s suchými i mokrými obětmi jejich, a obětoval je na oltáři domu Boha vašeho v Jeruzalémě.'),
(1558384,54,15,7,18,'A což se koli tobě a bratřím tvým za dobré viděti bude, s ostatkem stříbra a zlata učiniti, vedlé vůle Boha vašeho učiňte.'),
(1558385,54,15,7,19,'Nádoby pak, kteréžť jsou dány k službě domu Boha tvého, navrať před Bohem v Jeruzalémě,'),
(1558386,54,15,7,20,'I jiné věci přináležející k domu Boha tvého. A což by bylo potřebí dáti, dáš z komory královské.'),
(1558387,54,15,7,21,'A já, já Artaxerxes král poručil jsem všechněm výběrčím, kteříž jste za řekou, aby všecko, čehož by koli žádal od vás Ezdráš kněz, učitel zákona Boha nebeského, rychle se stalo,'),
(1558388,54,15,7,22,'Až do sta centnéřů stříbra, a až do sta měr pšenice, a až do sta sudů vína, a až do sta tun oleje, a soli bez míry.'),
(1558389,54,15,7,23,'Což by koli bylo z rozkazu Boha nebeského, nechť rychle spraví k domu Boha nebeského. Nebo proč má býti prchlivost jeho proti království královu i synům jeho?'),
(1558390,54,15,7,24,'Také vám oznamujeme, aby na žádného z kněží a Levítů, zpěváků, vrátných, Netinejských a služebníků v domě Boha toho, platu, cla a úroku žádný úředník nevzkládal.'),
(1558391,54,15,7,25,'Přesto, ty Ezdráši, podlé moudrosti Boha svého, kterouž jsi obdařen, nařídíš soudce a rádce, kteříž by soudili všecken lid, jenž jest za řekou, ze všech, kteříž povědomi jsou zákona Boha tvého. A kdo by neuměl, budete učiti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558392,54,15,7,26,'Kdož by pak koli neplnil zákona Boha tvého a zákona králova, ať se i hned soud vynese o něm, buď k smrti, buďto k vypovědění jeho, neb aby na statku pokutován byl, aneb vězením trestán.'),
(1558393,54,15,7,27,'Požehnaný Hospodin Bůh otců našich, kterýž dal to srdce královo, aby zvelebil dům Hospodinův, kterýž jest v Jeruzalémě,'),
(1558394,54,15,7,28,'A naklonil ke mně milosrdenstvím krále i rad jeho, i všech mocných knížat královských. Protož já posilněn jsa rukou Hospodina Boha svého nade mnou, shromáždil jsem z lidu Izraelského přednější, kteříž by šli se mnou.'),
(1558395,54,15,8,1,'Tito jsou pak přednější po čeledech svých otcovských, a rod těch, kteříž vyšli se mnou za kralování Artaxerxa krále z Babylona:'),
(1558396,54,15,8,2,'Z synů Fínesových Gersom, z synů Itamarových Daniel, z synů Davidových Chattus.'),
(1558397,54,15,8,3,'Z synů Sechaniášových, jenž byl z synů Farosových, Zachariáš, a s ním počet mužů sto a padesáte.'),
(1558398,54,15,8,4,'Z synů Pachat Moábových Eliehoenai syn Zerachiášův, a s ním dvě stě mužů.'),
(1558399,54,15,8,5,'Z synů Sechaniášových syn Jachazielův, a s ním tři sta mužů.'),
(1558400,54,15,8,6,'Z synů Adinových Ebed syn Jonatanův, a s ním padesát mužů.'),
(1558401,54,15,8,7,'Z synů pak Elamových Izaiáš syn Ataliášův, a s ním sedmdesát mužů.'),
(1558402,54,15,8,8,'Z synů Sefatiášových Zebadiáš syn Michaelův, a s ním osmdesáte mužů.'),
(1558403,54,15,8,9,'Z synů Joábových Abdiáš syn Jechielův, a s ním dvě stě a osmnácte mužů.'),
(1558404,54,15,8,10,'Z synů Selomitových syn Josifiášův, a s ním sto a šedesáte mužů.'),
(1558405,54,15,8,11,'Z synů Bebai Zachariáš syn Bebai, a s ním osmmecítma mužů.'),
(1558406,54,15,8,12,'Z synů Azgadových Jochanan syn Hakatanův, a s ním sto a deset mužů.'),
(1558407,54,15,8,13,'Z synů Adonikamových poslednějších, jichž jména jsou tato: Elifelet, Jehiel, Semaiáš, a s ním šedesáte mužů.'),
(1558408,54,15,8,14,'Z synů Bigvai Utai a Zabbud, a s nimi sedmdesáte mužů.'),
(1558409,54,15,8,15,'Shromáždil jsem je pak u potoku, kterýž vpadá do Ahavy, a leželi jsme tu tři dni. Potom přehlédal jsem lid a kněží, a z synů Léví nenašel jsem tu žádného.'),
(1558410,54,15,8,16,'Protož poslal jsem Eliezera, Ariele, Semaiáše, Elnatana, Jariba, Elnatana, Nátana, Zachariáše a Mesullama, přednější, a Joiariba a Elnatana, muže učené,'),
(1558411,54,15,8,17,'A rozkázal jsem jim k Iddovi, knížeti v Chasifia místě, a naučil sem je, jak by měli mluviti k Iddovi, Achivovi a Netinejským v Chasifia místě, aby nám přivedli služebníky domu Boha našeho.'),
(1558412,54,15,8,18,'I přivedli nám s pomocí Boží muže rozumného z synů Moholi, syna Léví, syna Izraelova, a Serebiáše s syny jeho, a bratří jeho osmnácte,'),
(1558413,54,15,8,19,'A Chasabiáše, a s ním Izaiáše z synů Merari, bratří jeho a synů jejich dvadceti.'),
(1558414,54,15,8,20,'Z Netinejských pak, kteréž byl zřídil David a knížata k službě Levítům, dvě stě a dvadceti Netinejských. A ti všickni ze jména vyčteni byli.'),
(1558415,54,15,8,21,'Tedy vyhlásil jsem tu půst u řeky Ahava, abychom se ponižovali před Bohem svým, a hledali od něho cesty přímé sobě a dítkám svým, i všemu jmění našemu.'),
(1558416,54,15,8,22,'Nebo styděl jsem se žádati od krále vojska a jízdných, aby nás bránili před nepřátely na cestě; nebo jsme byli pravili králi, řkouce: Ruka Boha našeho jest nade všemi, kteříž ho hledají upřímě, ale moc a prchlivost jeho proti všechněm, kteříž ho opouštějí.'),
(1558417,54,15,8,23,'A když jsme se postili a hledali v tom Boha svého, tedy vyslyšel nás.'),
(1558418,54,15,8,24,'Oddělil jsem pak přednějších kněží dvanácte: Serebiáše, Chasabiáše, a s nimi z bratří jejich deset.'),
(1558419,54,15,8,25,'I odvážil jsem jim stříbro a zlato, a to nádobí, obět domu Boha našeho, kterouž obětovali král i rady jeho, i knížata jeho a všecken lid Izraelský, což se ho našlo.'),
(1558420,54,15,8,26,'Odvážil jsem, pravím, do rukou jejich stříbra šest set centnéřů a padesát, a nádobí stříbrného sto centnéřů, a zlata sto centnéřů,'),
(1558421,54,15,8,27,'A koflíků zlatých dvadceti, každý v tisíc drachem, a dvě nádoby z mosazi nejlepší, tak vzácné jako zlato.'),
(1558422,54,15,8,28,'Potom jsem jim řekl: Vy jste posvěceni Hospodinu, i tyto nádoby posvěceny jsou, a to stříbro i zlato jest obět dobrovolná Hospodinu Bohu otců vašich.'),
(1558423,54,15,8,29,'Pilni toho buďte a ostříhejte, až to i odvážíte před kněžími přednějšími a Levíty, i předními z čeledí otcovských z Izraele v Jeruzalémě v pokojích domu Hospodinova.'),
(1558424,54,15,8,30,'A tak přijali kněží a Levítové váhu stříbra, zlata a nádobí, aby donesli do Jeruzaléma, do domu Boha našeho.'),
(1558425,54,15,8,31,'Zatím hnuli jsme se od řeky Ahava, dvanáctého dne měsíce prvního, abychom se brali do Jeruzaléma, a ruka Boha našeho byla s námi, a vytrhla nás z ruky nepřátel a úkladníků na cestě.'),
(1558426,54,15,8,32,'I přišli jsme do Jeruzaléma, a pobyli jsme tu tři dni.'),
(1558427,54,15,8,33,'Čtvrtého pak dne odváženo jest stříbro a zlato, a nádobí to v domě Boha našeho k ruce Meremota syna Uriáše kněze, s nímž byl Eleazar syn Fínesův, a pomocníci jejich Jozabad syn Jesua, a Noadiáš syn Binnui, Levítové,'),
(1558428,54,15,8,34,'Vše v počtu a váze, a zapsána jest všecka ta váha toho času.'),
(1558429,54,15,8,35,'Vrátivše se pak z zajetí ti, kteříž byli přestěhováni, obětovali zápaly Bohu Izraelskému, volků dvanáct za všecken lid Izraelský, skopců devadesát a šest, beránků sedmdesát a sedm, kozlů za hřích dvanáct, vše v obět zápalnou Hospodinu.'),
(1558430,54,15,8,36,'I dali výpovědi královy vládařům královským i vývodám za řekou. Kteříž pomocni byli lidu i domu Božímu.'),
(1558431,54,15,9,1,'A když se to vykonalo, přistoupili ke mně knížata, řkouce: Neoddělil se lid Izraelský, ani kněží a Levítové od národů zemí, ale činí podlé ohavností Kananejských, Hetejských, Ferezejských, Jebuzejských, Ammonitských, Moábských, Egyptských a Amorejských.'),
(1558432,54,15,9,2,'Nebo nabrali sobě a synům svým dcer jejich, a smísili se símě svaté s národy zemí, a knížata a vrchnost první byla v tom přestoupení.'),
(1558433,54,15,9,3,'Kteroužto věc když jsem uslyšel, roztrhl jsem roucho své i plášť, a trhal jsem vlasy s hlavy své i z brady, a seděl jsem zděšený.'),
(1558434,54,15,9,4,'I shromáždili se ke mně všickni, třesoucí se před řečmi Boha Izraelského pro přestoupení lidu přestěhovaného, já pak seděl jsem zděšený, až do oběti večerní.'),
(1558435,54,15,9,5,'Ale v čas oběti večerní vstal jsem od trápení svého, maje na sobě roucho roztržené i plášť svůj, a klekl jsem na kolena svá, rozprostíraje ruce své k Hospodinu Bohu svému.'),
(1558436,54,15,9,6,'A řekl jsem: Bože můj, stydím se a hanbím pozdvihnouti, Bože můj, tváři své k tobě; nebo nepravosti naše rozmnožily se nad hlavou, a provinění naše vzrostlo až k nebi.'),
(1558437,54,15,9,7,'Ode dnů otců našich u veliké jsme vině až do tohoto dne, a pro nepravosti naše vydáni jsme my, králové naši i kněží naši v ruku králů zemí pod meč, v zajetí a v loupež, a v zahanbení tváři, tak jakž se to nyní děje.'),
(1558438,54,15,9,8,'Teď pak rychle stala se nám milost od Hospodina Boha našeho, že zanechal nám ostatků, a dal nám obydlí na místě svatém, aby osvítil oči naše Bůh náš, a dal nám maličké povydchnutí od služby naší.'),
(1558439,54,15,9,9,'Nebo ač jsme byli služebníci, však nenechal nás Bůh náš v porobě naší, ale naklonil k nám milostí krále Perské, dav nám život, abychom vyzdvihli dům Boha našeho, a zase obnovili pustiny jeho, nýbrž ohradil nás v Judstvu a v Jeruzalémě.'),
(1558440,54,15,9,10,'Nyní tedy což díme, ó Bože náš, po těch věcech, poněvadž jsme opustili přikázaní tvá,'),
(1558441,54,15,9,11,'Kteráž jsi vydal skrze služebníky své proroky, řka: Země ta, do kteréž jdete, abyste jí dědičně vládli, jest země nečistá, pro nečistotu národů těch zemí, pro ohavnosti jejich, kterýmiž ji naplnili všudy naskrze v nečistotě své.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558442,54,15,9,12,'Protož nyní dcer vašich nedávejte synům jejich, a dcer jejich nebeřte synům vašim, a nehledejte pokoje jejich a dobrého jejich, až na věky, abyste se zmocnili, a jedli dobré věci země, a k dědičnému vládařství zanechali ji synům svým až na věky.'),
(1558443,54,15,9,13,'Po všech pak těch věcech, kteréž na nás přišly pro zlé skutky naše, a pro veliké naše provinění, poněvadž ty, Bože náš, netrestal jsi nás podlé nepravostí našich, a dal jsi nám vysvobození takové,'),
(1558444,54,15,9,14,'Opět-liž bychom rušiti měli tvá přikázaní, a přízniti se s národy těmito ohavnými? Zdaliž bys se zůřivě nehněval na nás, až bys nás do konce vyhladil, tak že by žádný nezůstal a neušel?'),
(1558445,54,15,9,15,'Hospodine Bože Izraelský, ty jsi spravedlivý; nebo jsme pozůstali ostatkové, jakž se to vidí dnešního dne. Aj, my jsme před tebou s proviněním svým, ač bychom neměli postavovati se před tváří tvou pro věci takové.'),
(1558446,54,15,10,1,'Když se pak Ezdráš, padna před domem Božím, tak modlil a vyznával s pláčem, sešel se k němu z lidu Izraelského zástup velmi veliký mužů i žen i dětí. A když plakal lid pláčem velikým,'),
(1558447,54,15,10,2,'Tedy mluvil Sechaniáš syn Jechielův z synů Elamových, a řekl Ezdrášovi: Myť jsme zhřešili proti Bohu svému, že jsme pojímali ženy cizozemky z národů zemí, a však vždy Izrael může míti naději při té věci.'),
(1558448,54,15,10,3,'Nyní tedy vejděme v smlouvu s Bohem svým, zapudíce všecky ženy i syny jejich podlé rady Páně a těch, jenž se třesou před přikázaním Boha našeho, a tak podlé zákona ať se stane.'),
(1558449,54,15,10,4,'Vstaň, nebo na tobě jest ta věc, a my budeme při tobě. Posilň se a učiň tak.'),
(1558450,54,15,10,5,'I vstal Ezdráš a zavázal přísahou přednější kněží a Levíty a všecken lid Izraelský, aby tak učinili. I přisáhli.'),
(1558451,54,15,10,6,'A vstav Ezdráš od domu Božího, odšel do pokojíka Jochananova, syna Eliasibova, i všel tam, a nejedl chleba, ani vody nepil; nebo zámutek měl pro přestoupení těch, jenž se přestěhovali.'),
(1558452,54,15,10,7,'Zatím dali provolati v Judstvu a v Jeruzalémě všechněm přestěhovaným, aby se shromáždili do Jeruzaléma,'),
(1558453,54,15,10,8,'Kdo by pak koli nepřišel ve třech dnech, podlé rady knížat a starších, aby všecken statek svůj propadl, a sám odloučen byl od shromáždění přestěhovaných.'),
(1558454,54,15,10,9,'A protož shromáždili se všickni muži Judští i Beniamin do Jeruzaléma ke dni třetímu, dvadcátého dne měsíce, (a ten měsíc byl devátý). I seděl všecken lid na ulici domu Božího, třesouce se pro tu věc i pro déšť.'),
(1558455,54,15,10,10,'Tedy vyvstal Ezdráš kněz a řekl k nim: Vy jste zhřešili, že jste pojímali ženy cizozemky, abyste přidali k provinění lidu Izraelského.'),
(1558456,54,15,10,11,'Protož již vyznejte se Hospodinu Bohu otců svých, a čiňte vůli jeho, a oddělte se od národů cizích, i od žen cizozemek.'),
(1558457,54,15,10,12,'I odpovědělo všecko to shromáždění, a řekli hlasem velikým: Podlé slova tvého povinni jsme tak učiniti.'),
(1558458,54,15,10,13,'Ale lidu mnoho jest, a prška, a nemůžeme vně státi. K tomu není ta práce jednoho dne ani dvou, nebo mnoho jest nás, kteříž jsme v tom přestoupili.'),
(1558459,54,15,10,14,'Nechť jsou postavena, prosíme, knížata naše ze všeho shromáždění, a kdož koli jest v městech našich, kterýž pojal ženy cizozemky, ať přijde v čas uložený, a s nimi starší z jednoho každého města i soudcové jejich, až bychom tak odvrátili hněv prchlivosti Boha našeho od sebe pro tu věc.'),
(1558460,54,15,10,15,'Takž Jonatan syn Azahelův, a Jachziáš syn Tekue, postaveni byli nad tím, Mesullam pak a Sabbetai, Levítové, pomáhali jim.'),
(1558461,54,15,10,16,'Tedy učinili tak při těch, jenž přestěhováni byli. I odděleni jsou Ezdráš kněz a muži přední čeledí otcovských po domích otců svých, všickni ti ze jména, a zasedli prvního dne měsíce desátého, aby to vyhledali.'),
(1558462,54,15,10,17,'Což i konali při všech mužích, kteříž byli pojali ženy cizozemky, až do prvního dne prvního měsíce.'),
(1558463,54,15,10,18,'Našli se pak z synů kněžských, jenž zpojímali ženy cizozemky tito: Z synů Jesua syna Jozadakova, a z bratří jeho: Maaseiáš, Eliezer, Jarib a Gedaliáš.'),
(1558464,54,15,10,19,'Ale povolili, aby zapudili ženy své. A ti, kteříž provinili, obětovali skopce z stáda za vinu svou.'),
(1558465,54,15,10,20,'A z synů Immer: Chanani a Zebadiáš.'),
(1558466,54,15,10,21,'Z synů Charim: Maaseiáš, Eliah, Semaiáš, Jechiel a Uziáš.'),
(1558467,54,15,10,22,'Z synů Paschur: Elioenai, Maaseiáš, Izmael, Natanael, Jozabad a Elasa.'),
(1558468,54,15,10,23,'A z Levítů: Jozabad, Simei, Kelaiáš, (jenž jest Kelita), Petachiáš, Juda a Eliezer.'),
(1558469,54,15,10,24,'Z zpěváků pak Eliasib, a z vrátných Sallum, Telem a Uri.'),
(1558470,54,15,10,25,'A z lidu Izraelského, z synů Faresových: Ramiáš, Jeziáš, Malkiáš, Miamin, Eleazar, Malkiáš a Benaiáš.'),
(1558471,54,15,10,26,'Z synů Elamových: Mataniáš, Zachariáš, Jechiel, Abdi, Jeremot a Eliah.'),
(1558472,54,15,10,27,'Z synů Zattu: Elioenai, Eliasib, Mataniáš, Jeremot, Zabad, a Aziza.'),
(1558473,54,15,10,28,'Též z synů Bebai: Jochanan, Chananiáš, Zabbai, Atlai.'),
(1558474,54,15,10,29,'Z synů Báni: Mesullam, Malluch, Adaiáš, Jasub, Seal, Jeramot.'),
(1558475,54,15,10,30,'Z synů Pachat Moábových: Adna a Chélal, Benaiáš, Maaseiáš, Mataniáš, Bezaleel, Binnui a Manasse.'),
(1558476,54,15,10,31,'Z synů Charimových: Eliezer, Isiáš, Malkiáš, Semaiáš, Simeon,'),
(1558477,54,15,10,32,'Beniamin, Malluch, Semariáš.'),
(1558478,54,15,10,33,'Z synů Chasumových: Mattenai, Mattata, Zabad, Elifelet, Jeremai, Manasses, Simei.'),
(1558479,54,15,10,34,'Z synů Báni: Maadai, Amram, Uel,'),
(1558480,54,15,10,35,'Benaiáš, Bediáš, Keluhu,'),
(1558481,54,15,10,36,'Vaniáš, Meremot, Eliasib,'),
(1558482,54,15,10,37,'Mattaniáš, Mattenai, Jaasav,'),
(1558483,54,15,10,38,'Báni, Binnui, Simei,'),
(1558484,54,15,10,39,'Selemiáš, Nátan a Adaiáš,'),
(1558485,54,15,10,40,'Machnadbai, Sasai, Sarai,'),
(1558486,54,15,10,41,'Azarel, Selemiáš, Semariáš,'),
(1558487,54,15,10,42,'Sallum, Amariáš a Jozef.'),
(1558488,54,15,10,43,'Z synů Nébových: Jehiel, Mattitiáš, Zabad, Zebina, Jaddav, Joel a Benaiáš.'),
(1558489,54,15,10,44,'Ti všickni pojali byli ženy cizozemky, a byly z těch žen některé, že i děti zplodily.'),
(1558490,54,16,1,1,'Slova Nehemiáše syna Chachaliášova. I stalo se měsíce Kislev léta dvadcátého, když jsem byl na hradě Susan,'),
(1558491,54,16,1,2,'Že přišel Chanani, jeden z bratří mých, s některými muži z Judstva. Kterýchžto vzeptal jsem se na Židy, na ostatky pozůstalé z zajetí a na Jeruzalém.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558492,54,16,1,3,'I řekli mi: Ostatkové ti, kteříž pozůstali z zajetí tam v té krajině, jsou u velikém nátisku a v pohanění, nadto i zed Jeruzalémská rozbořena jest, a brány jeho ohněm zkaženy.'),
(1558493,54,16,1,4,'Kterážto slova když jsem uslyšel, sedna plakal jsem a kvílil za několik dní, a postil jsem se, i modlil před Bohem nebeským.'),
(1558494,54,16,1,5,'A řekl jsem: Prosím, Hospodine Bože nebeský, silný, veliký a hrozný, ostříhající smlouvy a milosrdenství těm, jenž tě milují, a ostříhají přikázaní tvých,'),
(1558495,54,16,1,6,'Budiž, prosím, ucho tvé nakloněné, a oči tvé otevřené, abys slyšel modlitbu služebníka svého, kterouž já se modlím před tebou nyní dnem i nocí za syny Izraelské, služebníky tvé, a vyznávám hříchy synů Izraelských, jimiž jsme hřešili proti tobě. Já také i dům otce mého hřešili jsme.'),
(1558496,54,16,1,7,'Zpronevěřili jsme se tobě, a neostříhali jsme přikázaní a ustanovení a soudů, kteréž jsi vydal skrze Mojžíše služebníka svého.'),
(1558497,54,16,1,8,'Budiž pamětliv, prosím, na slovo, kteréž jsi přikázal Mojžíšovi služebníku svému, řka: Vy přestoupíte, já pak rozptýlím vás mezi národy.'),
(1558498,54,16,1,9,'Ale když se obrátíte ke mně, a budete ostříhati přikázaní mých, a plniti je, by pak někteří z vás až na kraj světa zahnáni byli, i odtud shromáždím je, a přivedu je zase na místo, kteréž jsem vyvolil, aby tam přebývalo jméno mé.'),
(1558499,54,16,1,10,'Však tito jsou služebníci tvoji a lid tvůj, kteréž jsi vykoupil mocí svou převelikou, a rukou svou přesilnou.'),
(1558500,54,16,1,11,'Prosím, ó Hospodine, nechť jest nakloněné ucho tvé k modlitbě služebníka tvého, a k modlitbě služebníků tvých, kteříž žádají báti se jména tvého, a dej šťastný prospěch, prosím, služebníku svému dnes, nakloně k němu lítostí člověka toho. Já pak byl jsem šeňkéřem královským.'),
(1558501,54,16,2,1,'Tedy stalo se měsíce Nísan léta dvadcátého Artaxerxa krále, když víno stálo před ním, že vzav víno, podal jsem ho králi. Nebýval jsem pak smuten před ním.'),
(1558502,54,16,2,2,'Pročež mi řekl král: Proč oblíčej tvůj smutný jest, poněvadž nestůněš? Jiného není, než sevření srdce. Pročež ulekl jsem se velmi velice.'),
(1558503,54,16,2,3,'A řekl jsem králi: Král na věky buď živ. Kterak nemá býti smutný oblíčej můj, když město to, kdež jsou hrobové otců mých, zpuštěno jest, a brány jeho ohněm zkaženy?'),
(1558504,54,16,2,4,'Opět mi řekl král: Čeho žádáš? Mezi tím modlil jsem se Bohu nebeskému.'),
(1558505,54,16,2,5,'Potom řekl jsem králi: Zdá-liť se za dobré králi, a jestliže má lásku služebník tvůj u tebe, žádám, abys mne poslal do Judstva, do města, kdež jsou hrobové otců mých, abych je zase vystavěl.'),
(1558506,54,16,2,6,'Ještě mi řekl král (královna pak seděla podlé něho): Dlouho-li budeš na té cestě, a kdy se zas navrátíš? I líbilo se to králi, a propustil mne, hned jakž jsem mu oznámil jistý čas.'),
(1558507,54,16,2,7,'Zatím řekl jsem králi: Vidí-li se za dobré králi, nechť mi dadí listy k vývodám za řekou, aby mne provedli, až bych přišel do Judstva,'),
(1558508,54,16,2,8,'Tolikéž psání k Azafovi, vládaři lesu královského, aby mi dal dříví na trámy, k branám paláce, při domě Božím, a ke zdem městským, a k domu, do něhož bych vjíti mohl. I dal mi král vedlé štědré ruky Boha mého ke mně.'),
(1558509,54,16,2,9,'Tedy přišed k vývodám za řekou, dal jsem jim psání královské. Poslal pak byl se mnou král hejtmany vojska a jezdce.'),
(1558510,54,16,2,10,'To když uslyšel Sanballat Choronský, a Tobiáš služebník Ammonitský, velmi je to mrzelo, že přišel člověk, kterýž by obmýšlel dobré synů Izraelských.'),
(1558511,54,16,2,11,'A tak přišed do Jeruzaléma, pobyl jsem tam za tři dni.'),
(1558512,54,16,2,12,'V noci pak vstal jsem, a kolikosi mužů se mnou, a neoznámil jsem žádnému, co mi dal Bůh můj v srdce, abych činil v Jeruzalémě, aniž jsem měl hovada jakého s sebou, kromě hovádka, na němž jsem jel.'),
(1558513,54,16,2,13,'I vyjel jsem branou při údolí v noci k studnici drakové a k bráně hnojné, a ohledoval jsem zdí Jeruzalémských, kteréž byly pobořené, a bran jeho zkažených ohněm.'),
(1558514,54,16,2,14,'Odtud jsem jel k bráně studničné, a k rybníku královskému, kdež nebylo brodu hovádku, na němž jsem jel, aby přejíti mohlo.'),
(1558515,54,16,2,15,'Pročež bral jsem se zhůru podlé potoka v noci, a ohledoval jsem zdi. Odkudž vraceje se, vjel jsem branou při údolí, a tak jsem se navrátil.'),
(1558516,54,16,2,16,'Ale knížata nic nevěděli, kam jsem jezdil, a co jsem činil; nebo jsem Židům, ani kněžím, ani přednějším, ani knížatům, ani jiným úředníkům až do té chvíle neoznámil.'),
(1558517,54,16,2,17,'Protož řekl jsem jim: Vy vidíte, v jakém jsme zlém, a Jeruzalém zpuštěný, a brány jeho ohněm zkaženy. Poďtež, a stavějme zed Jeruzalémskou, abychom nebyli více v pohanění.'),
(1558518,54,16,2,18,'A když jsem jim oznámil, že pomoc Boha mého jest se mnou, ano i slova králova, kteráž ke mně mluvil, teprv řekli: Přičiňmež se a stavějme. I posilnili rukou svých k dobrému.'),
(1558519,54,16,2,19,'Což když uslyšel Sanballat Choronský, a Tobiáš služebník Ammonitský, a Gesem Arabský, posmívali se, a utrhali nám, pravíce: Což to děláte? Co se králi protivíte?'),
(1558520,54,16,2,20,'Jimž odpovídaje, řekl jsem: Bůh nebeský, tenť nám dá prospěch, a my služebníci jeho přičiníce se, stavěti budeme, vy pak nemáte žádného dílu, ani práva, ani památky v Jeruzalémě.'),
(1558521,54,16,3,1,'Tedy povstal Eliasib, kněz nejvyšší, a příbuzní jeho kněží, a stavěli bránu bravnou, (tiť jsou ji vystavěli, a zavěsili vrata její, až k věži Mea vystavěli ji), až k věži Chananeel.'),
(1558522,54,16,3,2,'A podlé něho stavěli muži Jerecha, též podlé něho stavěl Zakur syn Imrův.'),
(1558523,54,16,3,3,'Bránu pak rybnou stavěli synové Senaa. Ti položili trámy její, a vstavili vrata její s zámky i závorami jejími.'),
(1558524,54,16,3,4,'Podlé těch také opravoval Meremot syn Uriáše, syna Kózova, a podlé nich opravoval Mesullam syn Berechiáše, syna Mesezabelova, a podlé těch opravoval Sádoch syn Baanův.'),
(1558525,54,16,3,5,'A podlé nich opravovali Tekoitští. Ale ti, kteříž byli znamenitější z nich, nepodklonili šíje své k dílu pána svého.'),
(1558526,54,16,3,6,'Bránu pak starou opravovali Joiada syn Paseachův, a Mesullam syn Besodiášův. Ti položili trámy její a vstavili vrata její s zámky a závorami jejími.'),
(1558527,54,16,3,7,'Podlé nich opravoval Melatiáš Gabaonitský, a Jádon Meronotský, muži z Gabaon a z Masfa, až k stolici knížecí z této strany řeky.'),
(1558528,54,16,3,8,'Podlé nich pak opravoval Uziel syn Charhaiášův s zlatníky, a podlé něho opravoval Chananiáš, syn apatekářův. A nechali Jeruzaléma až do zdi široké.'),
(1558529,54,16,3,9,'Dále podlé nich opravoval Refaiáš syn Churův, hejtman nad polovicí kraje Jeruzalémského.'),
(1558530,54,16,3,10,'A podlé nich opravoval Jedaiáš Charumafův proti domu svému. Podlé něhož opravoval Chattus syn Chasabneiášův.'),
(1558531,54,16,3,11,'Druhý pak díl opravoval Malkiáš syn Charimův, a Chasub syn Pachat Moábův, a věži Tannurim.'),
(1558532,54,16,3,12,'Podlé něhož opravoval Sallum syn Lochesův, hejtman nad polovicí kraje Jeruzalémského, se dcerami svými.'),
(1558533,54,16,3,13,'Bránu při údolí opravil Chanun s obyvateli Zanoe. Oni ji stavěli, a vstavili vrata její s zámky i závorami jejími, a zdi na tisíc loket až do brány hnojné.'),
(1558534,54,16,3,14,'Bránu pak hnojnou opravil Malkiáš syn Rechabův, hejtman kraje Betkarem. On ji ustavěl, a vstavil vrata s zámky i závorami jejími.'),
(1558535,54,16,3,15,'Bránu pak studnice opravoval Sallun syn Kolchozův, hejtman kraje Masfa. On ji vystavěl a přikryl ji, a vstavil vrata její s zámky i závorami jejími, a zed rybníka Selach, od zahrady královské až k stupňům sstoupajícím z města Davidova.'),
(1558536,54,16,3,16,'Za ním opravoval Nehemiáš syn Azbukův, hejtman nad polovici kraje Betsur, až naproti hrobům Davidovým, a až k rybníku udělanému, až k domu silných.'),
(1558537,54,16,3,17,'Za ním opravovali Levítové, Rechum syn Báni, podlé něhož opravoval Chasabiáš, hejtman nad polovicí kraje Ceily s krajem svým.'),
(1558538,54,16,3,18,'Za ním opravovali bratří jejich, Bavai syn Chenadadův, hejtman nad polovicí kraje Ceily.'),
(1558539,54,16,3,19,'Podlé něho pak opravoval Ezer syn Jesua, hejtman Masfa, díl druhý naproti, kudyž se chodí k skladu zbroje Mikzoa.'),
(1558540,54,16,3,20,'Za ním rozhorliv se, opravoval Báruch syn Zabbai, díl druhý od Mikzoa až ke dveřům domu Eliasiba, kněze nejvyššího.'),
(1558541,54,16,3,21,'Za ním opravoval Meremot syn Uriáše, syna Kózi, díl druhý ode dveří domu Eliasibova až do konce domu jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558542,54,16,3,22,'Za ním opravovali kněží, kteříž bydlili v rovině.'),
(1558543,54,16,3,23,'Za ním opravoval Beniamin a Chasub proti domům svým. Za ním opravoval Azariáš syn Maaseiáše, syna Ananiášova vedlé domu svého.'),
(1558544,54,16,3,24,'Za ním opravoval Binnui syn Chenadadův díl druhý, od domu Azariášova až do Mikzoa a až k úhlu.'),
(1558545,54,16,3,25,'Pálal syn Uzai proti Mikzoa a věži vysoké, kteráž vyhlédala z domu králova, jenž byla v placu u žaláře. Za ním Pedaiáš syn Farosův.'),
(1558546,54,16,3,26,'Netinejští pak, jenž bydlili v Ofel, až naproti bráně vodné k východu, a věži vysoké.'),
(1558547,54,16,3,27,'Za ním opravovali Tekoitští díl druhý, naproti věži veliké a vysoké, až ke zdi při Ofel.'),
(1558548,54,16,3,28,'Od brány koňské opravovali kněží, jeden každý naproti domu svému.'),
(1558549,54,16,3,29,'Za tím opravoval Sádoch syn Immerův naproti domu svému. Za ním pak opravoval Semaiáš syn Sechaniášův, strážný brány východní.'),
(1558550,54,16,3,30,'Za ním opravoval Chananiáš syn Selemiášův, a Chanun syn Zalafův šestý, díl druhý. Za ním opravoval Mesullam syn Berechiášův proti pokoji svému.'),
(1558551,54,16,3,31,'Za ním opravoval Malkiáš syn zlatníkův až k domu Netinejských a kupců, naproti bráně Mifkad, až do paláce úhlového.'),
(1558552,54,16,3,32,'A mezi palácem úhlovým až do brány bravné opravovali zlatníci a kupci.'),
(1558553,54,16,4,1,'I stalo se, když uslyšel Sanballat, že stavíme zed, rozpálil se hněvem, a rozzlobiv se velmi, posmíval se Židům.'),
(1558554,54,16,4,2,'Nebo mluvil před bratřími svými a před vojskem Samařským, řka: Co ti bídní Židé berou před sebe? Tak-liž mají býti zanecháni? Což budou obětovati? Za jeden-liž den to dodělati mají? Také-liž i kamení z hromad rumu křísiti budou, kteréž spáleno jest?'),
(1558555,54,16,4,3,'Tobiáš pak Ammonitský podlé něho řekl: Nechať stavějí, však liška přiběhna, prorazí zed jejich kamennou.'),
(1558556,54,16,4,4,'Slyš, ó Bože náš, že jsme v pohrdání, a obrať pohanění jejich na hlavu jejich, a dej je v loupež v zemi, do níž by zajati byli.'),
(1558557,54,16,4,5,'A nepřikrývej nepravosti jejich, a hřích jejich od tváři tvé ať není shlazen, proto že jsou tě popouzeli v stavitelích.'),
(1558558,54,16,4,6,'A tak stavěli jsme tu zed, a spojili všecku až do polu, a měl lid srdce k tomu dílu.'),
(1558559,54,16,4,7,'Což když uslyšel Sanballat, a Tobiáš a Arabští, Ammonitští i Azotští, že by na dýl přibývalo zdi Jeruzalémské, a že se již byly počaly mezery zavírati, rozpálili se hněvem velice.'),
(1558560,54,16,4,8,'Protož spuntovali se všickni společně, aby táhli k boji proti Jeruzalému a aby jemu překážku učinili.'),
(1558561,54,16,4,9,'(My pak modlili jsem se Bohu svému, a postavili jsme stráž proti nim ve dne i v noci, bojíce se jich.'),
(1558562,54,16,4,10,'Nebo řekli Judští: Zemdlelať jest síla nosičů, a rumu ještě mnoho jest, neodolaliť bychom jim, stavějíce zed.)'),
(1558563,54,16,4,11,'Anobrž i řekli nepřátelé naši: Nezvědíť, ani spatří, až vpadneme mezi ně, a pomordujeme je, aneb zastavíme to dílo.'),
(1558564,54,16,4,12,'Když pak přišli Židé, kteříž s nimi bydlili, a pravili nám na desetkrát: Mějte pozor na všecka místa, kudyž se chodí k nám:'),
(1558565,54,16,4,13,'Tedy postavil jsem na dolních místech za zdí, i na místech příkrých, a osadil jsem lidem po čeledech s meči, s kopími a lučišti jejich.'),
(1558566,54,16,4,14,'A když jsem to spatřil, vstana, řekl jsem k přednějším a knížatům i k jinému lidu: Nebojte se jich, ale na Pána velikého a hrozného pamatujte, a bojujte za bratří své, za syny své a dcery své, za manželky své a domy své.'),
(1558567,54,16,4,15,'I stalo se, když uslyšeli nepřátelé naši, že jest nám to oznámeno, tožť Bůh rozptýlil radu jejich, a my navrátili jsme se všickni ke zdem, každý k dílu svému.'),
(1558568,54,16,4,16,'Ale však od toho dne polovice služebníků mých dělali, a polovice jich držela kopí, pavézy a lučiště, a pancíře, a knížata stála za vší čeledí Judskou.'),
(1558569,54,16,4,17,'Ti také, kteříž dělali na zdi, i nosiči břemen, i nakladači, každý jednou rukou dělal, a v druhé držel braň.'),
(1558570,54,16,4,18,'Z těch pak, kteříž stavěli, měl jeden každý meč svůj připásaný na bedrách svých, a tak stavěli, a trubač stál podlé mne.'),
(1558571,54,16,4,19,'Nebo jsem řekl k přednějším a knížatům i k jinému lidu: Dílo veliké a široké jest, a my porůznu jsme na zdi, podál jeden od druhého.'),
(1558572,54,16,4,20,'Na kterém byste koli místě uslyšeli hlas trouby, tu se shromažďte k nám. Bůh náš bude bojovati za nás.'),
(1558573,54,16,4,21,'A tak my dělali jsme dílo, a polovice jich držela kopí od svitání až do soumraku.'),
(1558574,54,16,4,22,'Tehdáž také řekl jsem lidu: Každý s služebníkem svým nocuj u prostřed Jeruzaléma, ať je máme k stráži v noci, a ve dne k dílu.'),
(1558575,54,16,4,23,'Pročež i já, i bratří moji, i služebníci moji, i strážní, kteříž chodí za mnou, nebudeme svláčeti oděvu svého. Žádný ho nesloží, leč u vody.'),
(1558576,54,16,5,1,'Byl pak pokřik veliký lidu i žen jejich na bratří jich Židy.'),
(1558577,54,16,5,2,'Nebo někteří pravili: Synů a dcer máme tak mnoho, že za ně obilé jednáme, abychom jísti a živi býti mohli.'),
(1558578,54,16,5,3,'Jiní opět pravili: Pole svá i vinice své, a domy své zzastavovati musíme, abychom obilé jednati mohli v hladu tomto.'),
(1558579,54,16,5,4,'Jiní ještě pravili: Musíme vypůjčiti peněz, abychom dali plat králi, na svá pole i vinice své,'),
(1558580,54,16,5,5,'Ješto aj, jakož tělo bratří našich, tak těla naše, jakož synové jejich, tak i synové naši. A však my musíme podrobovati syny své a dcery své v službu, a některé již ze dcer našich podrobeny jsou, a nemůžeme s nic býti, poněvadž pole naše a vinice naše drží jiní.'),
(1558581,54,16,5,6,'Protož rozhněval jsem se velmi, když jsem slyšel křik jejich a slova taková.'),
(1558582,54,16,5,7,'I uložil jsem v srdci svém, abych domlouval přednějším a knížatům, řka jim: Vy jste ti, jenž obtěžujete jeden každý bratra svého. I svolal jsem proti nim shromáždění veliké.'),
(1558583,54,16,5,8,'A řekl jsem jim: My vyplacujeme bratří své Židy, kteříž prodáni byli pohanům, podlé možnosti naší. Což vy zase prodávati máte bratří vaše, anobrž což je sobě prodávati budete? Kteřížto umlkli a nenalezli odpovědi.'),
(1558584,54,16,5,9,'Řekl jsem dále: Není to dobře, což děláte. Zdali v bázni Boha našeho nemáte choditi raději než v pohanění pohanů, nepřátel našich?'),
(1558585,54,16,5,10,'I já také s bratřími svými a s služebníky svými mohl bych bráti od nich peníze aneb obilé, a však odpusťme jim medle ten dluh.'),
(1558586,54,16,5,11,'Navraťte jim, prosím, ještě dnes pole jejich, vinice jejich, zahrady olivové jejich i domy jejich, i ten stý díl peněz, obilé, vína i oleje, kterýž od nich béřete.'),
(1558587,54,16,5,12,'Odpověděli: Navrátíme, aniž čeho od nich vyhledávati budeme; tak učiníme, jakž ty pravíš. Tedy svolav kněží, zavázal jsem je přísahou, aby tak učinili.'),
(1558588,54,16,5,13,'Vytřásl jsem také podolek svůj, a řekl jsem: Tak vytřes Bůh každého muže, kdož by nenaplnil slova tohoto, z domu jeho, z úsilí jeho, a tak buď vytřesený a prázdný. I řeklo všecko shromáždění: Amen, a chválili Hospodina. I učinil lid tak.'),
(1558589,54,16,5,14,'Anobrž také ode dne, v němž jsem postaven, abych byl vývodou jejich v zemi Judské, od léta dvadcátého až do léta třidcátého druhého Artaxerxa krále, za dvanácte let, ani já ani bratří moji pokrmu knížecího jsme nejedli,'),
(1558590,54,16,5,15,'Ješto vývodové prvnější, kteříž byli přede mnou, obtěžovali lid, berouce od nich chléb a víno mimo čtyřidceti lotů stříbra. Nadto i služebníci jejich ssužovali lid, čehož jsem já nečinil, boje se Boha.'),
(1558591,54,16,5,16,'Alebrž také i při opravování zdi pracoval jsem, aniž jsme skupovali rolí, ano i všickni služebníci moji byli tu shromážděni k dílu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558592,54,16,5,17,'Přesto Židé a knížat půl druhého sta osob, a kteříž přicházeli k nám z národů okolních, jídali u stolu mého.'),
(1558593,54,16,5,18,'Pročež strojívalo se toho na každý den jeden vůl, šest ovec výborných, též i ptáci byli mi strojeni, a v jednom z desíti dnů všelijakého vína dávalo se dosti. Však s tím se vším pokrmu knížecího nežádal jsem, nebo těžká poroba vzložena byla na lid ten.'),
(1558594,54,16,5,19,'Budiž pamětliv na mne, Bože můj, k dobrému, což jsem pak koli činil při lidu tomto.'),
(1558595,54,16,6,1,'I stalo se, když uslyšel Sanballat a Tobiáš, a Gesem Arabský i jiní nepřátelé naši, že bych vystavěl zed, a že nezůstalo v ní mezery, ačkoli jsem ještě až do toho času nevstavil vrat do bran,'),
(1558596,54,16,6,2,'Že poslal Sanballat a Gesem ke mně, řka: Přiď, a rozmluvíme spolu ve vsi na rovinách Ono. Ale oni mé zlé obmýšleli.'),
(1558597,54,16,6,3,'Takž jsem poslal k nim posly, řka: Dílo veliké dělám, protož nemohu odjíti. Což se má meškati dílo, když bych je opustě, k vám sjíti měl?'),
(1558598,54,16,6,4,'I posílali ke mně na týž způsob čtyřikrát, a odpověděl jsem jim týmiž slovy.'),
(1558599,54,16,6,5,'Potom poslal ke mně Sanballat na tentýž způsob po páté služebníka svého s listem otevřeným.'),
(1558600,54,16,6,6,'V kterémž bylo psáno: Slyší se mezi národy, jakž Gasmu praví, že ty a Židé myslíte se zprotiviti, a že ty proto stavíš zed, abys králem jejich byl, jakž se to dokoná.'),
(1558601,54,16,6,7,'Také žes i proroky postavil, aby hlásali o tobě v Jeruzalémě, řkouce: Král v Judstvu. Nyní tedy uslyší král ty věci. Protož přiď, a poradíme se spolu.'),
(1558602,54,16,6,8,'Tedy poslal jsem k němu, řka: Neníť toho nic, což ty pravíš, ale sám sobě to vymýšlíš.'),
(1558603,54,16,6,9,'Nebo všickni ti nás ustrašiti se snažovali, myslíce: Oslábnou ruce jejich při díle, a nedokoná se to. Ale však ty, ó Bože, posilň rukou mých.'),
(1558604,54,16,6,10,'A když jsem všel do domu Semaiáše syna Delaiášova, syna Mehetabelova, kterýž se byl zavřel, řekl mi: Sejděme se do domu Božího, do vnitřku chrámu, a zavřeme dvéře chrámové; nebo přijdou, chtíc tě zamordovati. A to v noci přijdou, aby tě zamordovali.'),
(1558605,54,16,6,11,'Jemuž jsem řekl: Takový-liž by muž, jako jsem já, utíkati měl? Aneb kdo jest tak, jako jsem já, ješto by vejda do chrámu, živ byl? Nevejduť.'),
(1558606,54,16,6,12,'I poznal jsem, a aj, Bůh neposlal ho, ale proroctví to mluvil proti mně, že ho Tobiáš a Sanballat byli ze mzdy najali.'),
(1558607,54,16,6,13,'Proto pak ze mzdy byl najat, abych já ustrašen jsa, učinil to a zhřešil, aby mi to bylo u nich k zlé pověsti, čímž by mi utrhali.'),
(1558608,54,16,6,14,'Budiž pamětliv, můj Bože, na Tobiáše a Sanballata, podlé těch skutků jejich, i na Noadii prorokyni, a na jiné proroky, kteříž strašili mne.'),
(1558609,54,16,6,15,'A tak dodělána jest zed ta pětmecítmého dne měsíce Elul v padesáti a dvou dnech.'),
(1558610,54,16,6,16,'To když uslyšeli všickni nepřátelé naši, a viděli všickni národové, kteříž byli vůkol nás, ulekli se velmi; nebo poznali, že od Boha našeho působeno bylo dílo to.'),
(1558611,54,16,6,17,'Také v těch dnech i listy často posílali přednější Judští k Tobiášovi, tolikéž od Tobiáše docházely k nim.'),
(1558612,54,16,6,18,'Nebo mnozí v Judstvu měli s ním přísahu, proto že byl zetěm Sechaniáše syna Arachova, a Jochanan syn jeho pojal byl dceru Mesullama syna Berechiášova.'),
(1558613,54,16,6,19,'K tomu i dobré činy jeho vypravovali přede mnou, a řeči mé vynášeli k němu. Listy pak posílal Tobiáš, aby mne ustrašil.'),
(1558614,54,16,7,1,'A když byla dostavena zed, a zavěsil jsem vrata, a ustanoveni byli vrátní i zpěváci i Levítové,'),
(1558615,54,16,7,2,'Poručil jsem Chananovi bratru svému, a Chananiášovi hejtmanu hradu Jeruzalémského, (proto že on byl muž věrný a bohabojný nad mnohé),'),
(1558616,54,16,7,3,'A řekl jsem jim: Nechť nebývají otvírány brány Jeruzalémské, až obejde slunce, a když ti, jenž tu stávají, zavrou brány, vy ohledejte. A tak postavil jsem stráž z obyvatelů Jeruzalémských, každého v stráži jeho, a každého naproti domu jeho.'),
(1558617,54,16,7,4,'Město pak to bylo široké a veliké, ale lidu málo v ohradě jeho, a domové nebyli vystaveni.'),
(1558618,54,16,7,5,'Protož dal mi to Bůh můj v srdce mé, že jsem shromáždil přednější, a knížata i lid, aby byli vyčteni podlé pořádku rodů. I nalezl jsem knihu o rodu těch, kteříž se byli prvé přestěhovali, a našel jsem v ní napsáno:'),
(1558619,54,16,7,6,'Tito jsou lidé té krajiny, kteříž šli z zajetí a přestěhování toho, jakž je byl přestěhoval Nabuchodonozor král Babylonský, a navrátili se do Jeruzaléma a do Judstva, jeden každý do města svého.'),
(1558620,54,16,7,7,'Kteříž přišli s Zorobábelem, s Jesua, s Nehemiášem, Azariášem, Raamiášem, Nachamanem, Mardocheem, Bilsanem, Misperetem, Bigvajem, Nechumem, Baanou, počet mužů z lidu Izraelského:'),
(1558621,54,16,7,8,'Synů Farosových dva tisíce, sto sedmdesát dva;'),
(1558622,54,16,7,9,'Synů Sefatiášových tři sta sedmdesát dva;'),
(1558623,54,16,7,10,'Synů Arachových šest set padesát dva;'),
(1558624,54,16,7,11,'Synů Pachat Moábových, synů Jesua a Joábových, dva tisíce, osm set a osmnáct;'),
(1558625,54,16,7,12,'Synů Elamových tisíc, dvě stě padesát čtyři;'),
(1558626,54,16,7,13,'Synů Zattuových osm set čtyřidceti pět;'),
(1558627,54,16,7,14,'Synů Zakkai sedm set a šedesát;'),
(1558628,54,16,7,15,'Synů Binnui šest set čtyřidceti osm;'),
(1558629,54,16,7,16,'Synů Bebai šest set dvadceti osm;'),
(1558630,54,16,7,17,'Synů Azgadových dva tisíce, tři sta dvamecítma;'),
(1558631,54,16,7,18,'Synů Adonikamových šest set šedesáte sedm;'),
(1558632,54,16,7,19,'Synů Bigvai dva tisíce, šedesáte sedm;'),
(1558633,54,16,7,20,'Synů Adinových šest set padesát pět;'),
(1558634,54,16,7,21,'Synů Aterových z Ezechiáše devadesát osm;'),
(1558635,54,16,7,22,'Synů Chasumových tři sta dvadceti osm;'),
(1558636,54,16,7,23,'Synů Bezai tři sta dvadceti čtyři;'),
(1558637,54,16,7,24,'Synů Charifových sto a dvanáct;'),
(1558638,54,16,7,25,'Synů Gabaonitských devadesát pět;'),
(1558639,54,16,7,26,'Mužů Betlémských a Netofatských sto osmdesát osm;'),
(1558640,54,16,7,27,'Mužů Anatotských sto dvadceti osm;'),
(1558641,54,16,7,28,'Mužů Betazmavetských čtyřidceti dva;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558642,54,16,7,29,'Mužů Kariatjeharimských, Kafirských a Berotských sedm set čtyřidceti a tři;'),
(1558643,54,16,7,30,'Mužů Ráma a Gabaa šest set dvadceti jeden;'),
(1558644,54,16,7,31,'Mužů Michmas sto dvadceti dva;'),
(1558645,54,16,7,32,'Mužů z Bethel a Hai sto dvadceti tři;'),
(1558646,54,16,7,33,'Mužů z Nébo druhého padesáte dva;'),
(1558647,54,16,7,34,'Synů Elama druhého tisíc, dvě stě padesát čtyři;'),
(1558648,54,16,7,35,'Synů Charimových tři sta dvadceti;'),
(1558649,54,16,7,36,'Synů Jerecho tři sta čtyřidceti pět;'),
(1558650,54,16,7,37,'Synů Lodových, Chadidových a Onových sedm set dvadceti jeden;'),
(1558651,54,16,7,38,'Synů Senaa tři tisíce, devět set a třidceti.'),
(1558652,54,16,7,39,'Kněží: Synů Jedaiášových z domu Jesua devět set sedmdesát tři;'),
(1558653,54,16,7,40,'Synů Immerových tisíc, padesát dva;'),
(1558654,54,16,7,41,'Synů Paschurových tisíc, dvě stě čtyřidceti sedm;'),
(1558655,54,16,7,42,'Synů Charimových tisíc a sedmnáct.'),
(1558656,54,16,7,43,'Levítů: Synů Jesua a Kadmiele, synů Hodevášových sedmdesát čtyři.'),
(1558657,54,16,7,44,'Zpěváků: Synů Azafových sto čtyřidceti osm.'),
(1558658,54,16,7,45,'Vrátných: Synů Sallumových, synů Aterových, synů Talmonových, synů Akkubových, synů Chatita, synů Sobai, sto třidceti osm.'),
(1558659,54,16,7,46,'Netinejských: Synů Zicha, synů Chasufa, synů Tabbaot,'),
(1558660,54,16,7,47,'Synů Keros, synů Sia, synů Fadon,'),
(1558661,54,16,7,48,'Synů Lebana, synů Chagaba, synů Salmai,'),
(1558662,54,16,7,49,'Synů Chanan, synů Giddel, synů Gachar,'),
(1558663,54,16,7,50,'Synů Reaia, synů Rezin, synů Nekoda,'),
(1558664,54,16,7,51,'Synů Gazam, synů Uza, synů Paseach,'),
(1558665,54,16,7,52,'Synů Besai, synů Meunim, synů Nefisesim,'),
(1558666,54,16,7,53,'Synů Bakbuk, synů Chakufa, synů Charchur,'),
(1558667,54,16,7,54,'Synů Bazlit, synů Mechida, synů Charsa,'),
(1558668,54,16,7,55,'Synů Barkos, synů Sisera, synů Tamach,'),
(1558669,54,16,7,56,'Synů Neziach, synů Chatifa,'),
(1558670,54,16,7,57,'Synů služebníků Šalomounových, synů Sotai, synů Soferet, synů Ferida,'),
(1558671,54,16,7,58,'Synů Jaala, synů Darkon, synů Giddel,'),
(1558672,54,16,7,59,'Synů Sefatiášových, synů Chattil, synů Pocheret Hazebaim, synů Amon,'),
(1558673,54,16,7,60,'Všech Netinejských a synů služebníků Šalomounových tři sta devadesát dva.'),
(1558674,54,16,7,61,'Tito také byli, kteříž vyšli z Telmelach a Telcharsa: Cherub, Addon a Immer. Ale nemohli prokázati rodu otců svých a semene svého, že by z Izraele byli.'),
(1558675,54,16,7,62,'Synů Delaiášových, synů Tobiášových, synů Nekodových šest set čtyřidceti dva.'),
(1558676,54,16,7,63,'A z kněží: Synové Chabaiášovi, synové Kózovi, synové Barzillai toho, kterýž pojav sobě z dcer Barzillai Galádského manželku, nazván jest jménem jejich.'),
(1558677,54,16,7,64,'Ti vyhledávali jeden každý zapsání o sobě, chtíce prokázati rod svůj, ale nenašlo se. A protož zbaveni jsou kněžství.'),
(1558678,54,16,7,65,'A zapověděl jim Tirsata, aby nejedli z věcí svatosvatých, dokudž by nestál kněz s urim a tumim.'),
(1558679,54,16,7,66,'Všeho toho shromáždění pospolu čtyřidceti a dva tisíce, tři sta a šedesát,'),
(1558680,54,16,7,67,'Kromě služebníků jejich a děvek jejich, jichž bylo sedm tisíc, tři sta třidceti sedm. A mezi nimi bylo zpěváků a zpěvakyní dvě stě čtyřidceti pět.'),
(1558681,54,16,7,68,'Koní jejich sedm set třidceti šest, mezků jejich dvě stě čtyřidceti pět,'),
(1558682,54,16,7,69,'Velbloudů čtyři sta třidceti pět, oslů šest tisíc, sedm set a dvadceti.'),
(1558683,54,16,7,70,'Tehdy někteří z knížat čeledí otcovských dávali ku potřebám. Tirsata dal na poklad tisíc drachem zlata, bání padesát, sukní kněžských pět set a třidceti.'),
(1558684,54,16,7,71,'Knížata také čeledí otcovských dali na poklad ku potřebám dvadceti tisíc drachem zlata, a stříbra liber dva tisíce a dvě stě.'),
(1558685,54,16,7,72,'Což pak dali jiní z lidu, bylo zlata dvadcet tisíc drachem, a stříbra dva tisíce liber, a sukní kněžských šedesát sedm.'),
(1558686,54,16,7,73,'A tak osadili se kněží a Levítové, a vrátní i zpěváci, lid a Netinejští, i všecken Izrael v městech svých. I nastal měsíc sedmý, a synové Izraelští byli v městech svých.'),
(1558687,54,16,8,1,'I shromáždil se všecken lid jednomyslně do ulice, kteráž jest proti bráně vodné, a řekli Ezdrášovi učiteli, aby přinesl knihu zákona Mojžíšova, kterýž vydal Hospodin lidu Izraelskému.'),
(1558688,54,16,8,2,'Tedy přinesl Ezdráš kněz zákon před to shromáždění mužů i žen i všech, kteříž by rozumně poslouchati mohli, prvního dne měsíce sedmého.'),
(1558689,54,16,8,3,'I četl v něm na té ulici, kteráž jest proti bráně vodné, od jitra až do poledne, při přítomnosti mužů i žen, i kteřížkoli rozuměti mohli. A uši všeho lidu obráceny byly k knize zákona.'),
(1558690,54,16,8,4,'Stál pak Ezdráš učitel na kazatelnici dřevěné, kterouž byli udělali k té věci, a stál podlé něho Mattitiáš, Sema, Anaiáš, Uriáš, Helkiáš a Maaseiáš, po pravé ruce jeho, po levé pak Pedaiáš, Misael, Malkiáš, Chasum, Chasbaddana, Zachariáš a Mesullam.'),
(1558691,54,16,8,5,'Otevřel tedy Ezdráš knihu před očima všeho lidu, (nebo výše stál než všecken lid). Kterouž jakž otevřel, povstal všecken lid.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558692,54,16,8,6,'I dobrořečil Ezdráš Hospodinu Bohu velikému, a všecken lid odpovídal: Amen, amen, pozdvihujíce rukou svých, a skloňujíce hlavy, poklonu učinili Hospodinu tváří k zemi.'),
(1558693,54,16,8,7,'Tak i Jesua, Báni, Serebiáš, Jamin, Akkub, Sabbetai, Hodiáš, Maaseiáš, Kelita, Azariáš, Jozabad, Chanan, Pelaiáš, a Levítové vyučovali lid zákonu. Lid pak byl na místě svém.'),
(1558694,54,16,8,8,'Nebo čtli v té knize v zákoně Božím srozumitelně, a vykládajíce smysl, vysvětlovali to, což čtli.'),
(1558695,54,16,8,9,'Potom řekl Nehemiáš, jinak Tirsata, a Ezdráš kněz, učitel, a Levítové, kteříž lid vyučovali, všemu lidu: Den tento posvěcený jest Hospodinu Bohu vašemu, nekvěltež, ani plačte. (Nebo plakal všecken lid, když slyšeli slova zákona.)'),
(1558696,54,16,8,10,'Ale jděte, řekl jim, a jezte tučné věci, a píte sladké, sdílejíce se s těmi, kteříž nemají nic připraveno. Den zajisté tento svatý jest Pánu našemu, protož nermuťtež se, nýbrž radost Hospodinova budiž síla vaše.'),
(1558697,54,16,8,11,'A když tak Levítové pospokojili všeho lidu, mluvíce: Mlčte, nebo den svatý jest, a nermuťte se,'),
(1558698,54,16,8,12,'Odšel všecken lid, aby jedli a pili, a aby se sdíleli. I veselili se velmi, proto že srozuměli slovům těm, kteráž jim v známost uvedli.'),
(1558699,54,16,8,13,'Potom nazejtří sešla se knížata čeledí otcovských ze všeho lidu, kněží i Levítové k Ezdrášovi učiteli, aby vyrozuměli slovům zákona.'),
(1558700,54,16,8,14,'Našli pak napsáno v zákoně, že přikázal Hospodin skrze Mojžíše, aby bydlili synové Izraelští v stáncích na slavnost měsíce sedmého,'),
(1558701,54,16,8,15,'A aby dali prohlásiti a provolati po všech městech svých i v Jeruzalémě, řkouce: Vyjděte na hory, a přineste ratolestí olivových a ratolestí dříví borového, a ratolestí myrtových, i ratolestí palmových, a ratolestí dříví hustého, abyste nadělali stánků, tak jakž psáno jest.'),
(1558702,54,16,8,16,'Protož vyšed lid, přinesli a nadělali sobě stánků, jeden každý na střeše své, i v síních svých, i v síních domu Božího, i v ulici brány vodné, i v ulici brány Efraim.'),
(1558703,54,16,8,17,'A tak nadělali stánků všecko shromáždění těch, jenž se vrátili z zajetí, a bydlili v nich, (ačkoli nečinili tak synové Izraelští ode dnů Jozue syna Nun, až do dne toho). I byla radost velmi veliká.'),
(1558704,54,16,8,18,'Četl pak v knize zákona Božího na každý den, od prvního dne až do posledního, a drželi slavnost za sedm dní. Osmého pak dne byl svátek podlé obyčeje.'),
(1558705,54,16,9,1,'Potom dvadcátého čtvrtého dne téhož měsíce shromáždili se synové Izraelští, a postíce se v žíních, posypali se prstí,'),
(1558706,54,16,9,2,'(Oddělilo se pak bylo símě Izraelské ode všech cizozemců), a stojíce, vyznávali hříchy své i nepravosti otců svých.'),
(1558707,54,16,9,3,'I stáli na místech svých, a čtli v knize zákona Hospodina Boha svého čtyřikrát za den, a čtyřikrát vyznávali a klaněli se Hospodinu Bohu svému.'),
(1558708,54,16,9,4,'Za tím vystoupivše na výstupek Levítský Jesua a Báni, Kadmiel, Sebaniáš, Bunni, Serebiáš, Báni a Chenani, volali hlasem velikým k Hospodinu Bohu svému.'),
(1558709,54,16,9,5,'A řekli Levítové ti, Jesua, Kadmiel, Báni, Chasabniáš, Serebiáš, Hodiáš, Sebaniáš a Petachiáš: Vstaňte, dobrořečte Hospodinu Bohu svému, od věků až na věky, a ať dobrořečí slavnému jménu jeho, a vyššímu nad každé dobrořečení i chválu.'),
(1558710,54,16,9,6,'Ty jsi, Hospodine, sám ten jediný, ty jsi učinil nebesa, nebesa nebes i všecko vojsko jejich, zemi i všecko, což jest na ní, moře i všecko, což jest v nich, obživuješ také všecko, ano i vojska nebeská před tebou se sklánějí.'),
(1558711,54,16,9,7,'Ty jsi, Hospodine, Bůh ten, kterýž jsi vyvolil Abrama, a vyvedl jej z Ur Kaldejských, a dal jsi jemu jméno Abraham.'),
(1558712,54,16,9,8,'A nalezl jsi srdce jeho věrné před sebou, a učinil jsi s ním smlouvu, že dáš zemi Kananejského, Hetejského, Amorejského, Ferezejského, Jebuzejského a Gergezejského, že dáš ji semeni jeho, a naplnils slova svá, nebo spravedlivý jsi ty.'),
(1558713,54,16,9,9,'Popatřil jsi zajisté na trápení otců našich v Egyptě, a křik jejich vyslyšel jsi při moři Rudém.'),
(1558714,54,16,9,10,'A ukazovals znamení a zázraky na Faraonovi i na všech služebnících jeho, i na všem lidu země jeho; nebo věděl jsi, že jsou pýchu provodili nad nimi. Čímž jsi dobyl sobě jména, jakž se to podnes vidí.'),
(1558715,54,16,9,11,'Nadto i moře jsi před nimi rozdělil, tak že přešli prostředkem moře po suše, a ty, jenž je stihali, uvrhl jsi do hlubin, jako kámen do vody veliké.'),
(1558716,54,16,9,12,'A sloupem oblakovým vodils je ve dne, a sloupem ohnivým v noci, osvěcuje jim cestu, kudy by jíti měli.'),
(1558717,54,16,9,13,'Potom jsi sstoupil na horu Sinai, a mluvil jsi s nimi s nebe, a vydal jsi jim soudy přímé a zákony pravé, ustanovení a přikázaní dobrá.'),
(1558718,54,16,9,14,'Též i sobotu svou svatou známu jsi jim učinil, a přikázaní, ustanovení i zákon vydals jim skrze Mojžíše, služebníka svého.'),
(1558719,54,16,9,15,'Také i chléb s nebe dal jsi jim v hladu jejich, a vodu z skály vyvedl jsi jim v žízni jejich, a rozkázal jsi jim, aby šli a dědičně vládli zemí, kterouž jsi zdvihna ruku svou, přisáhl dáti jim.'),
(1558720,54,16,9,16,'Oni pak a otcové naši pyšně sobě počínali, a zatvrdivše šíji svou, neposlouchali přikázaní tvých.'),
(1558721,54,16,9,17,'Nýbrž hned nechtěli slyšeti, aniž se rozpomenuli na divné činy tvé, kteréž jsi působil při nich, a zatvrdivše šíji svou, ustavovali sobě vůdce, chtíce se navrátiti k porobení svému z zarputilosti své. Ty však, Bože, snadný k odpuštění, milostivý a lítostivý, dlouho shovívající a hojný v milosrdenství, neopustils jich.'),
(1558722,54,16,9,18,'Ano i tehdáž, když sobě udělali tele slité a řekli: Tito jsou bohové tvoji, kteříž tě vyvedli z Egypta, a dopustili se velikého rouhání.'),
(1558723,54,16,9,19,'Ty však pro svá mnohá slitování neopustil jsi jich na poušti. Sloup oblakový neodcházel od nich ve dne, veda je po cestě, ani sloup ohnivý v noci, osvěcuje je a cestu, po níž jíti měli.'),
(1558724,54,16,9,20,'Nadto Ducha svého dobrého dal jsi k vyučování jich, manny své také neodjals od úst jejich, a vodu dal jsi jim v žízni jejich.'),
(1558725,54,16,9,21,'A tak za čtyřidceti let krmil jsi je na poušti. V ničemž nedostatku neměli, oděv jejich nezvetšel, a nohy jejich se neodhnetly.'),
(1558726,54,16,9,22,'Potom dal jsi jim království a národy, kteréž jsi rozehnal do koutů, tak že dědičně obdrželi zemi Seonovu, a zemi krále Ezebon, i zemi Oga krále Bázan.'),
(1558727,54,16,9,23,'Syny pak jejich rozmnožil jsi jako hvězdy nebeské, a uvedl jsi je do země, o kteréž jsi byl řekl otcům jejich, že do ní vejdou, aby jí vládli.'),
(1558728,54,16,9,24,'Nebo všedše synové, dědičně obdrželi zemi tu, když jsi snížil před nimi obyvatele té země Kananejské, a dals je v ruku jejich, i krále jejich, i národy té země, aby s nimi nakládali podlé vůle své.'),
(1558729,54,16,9,25,'A tak vzali města hrazená i pole úrodná, a dědičně ujali domy plné všeho dobrého, studnice vykopané, vinice a olivoví, i stromoví ovoce nesoucí velmi mnohé. I jedli, a nasyceni jsouce, vytyli, a v dobrodiní tvém hojném rozkoší oplývali.'),
(1558730,54,16,9,26,'Když pak popouzejíce tě, zprotivili se tobě, zavrhše zákon tvůj za hřbet svůj, a proroky tvé zmordovali, kteříž jim osvědčovali, aby je obrátili k tobě, a dopouštěli se velikého rouhání,'),
(1558731,54,16,9,27,'Dával jsi je v ruku nepřátel jejich, kteříž je ssužovali. A když v čas ssoužení svého volali k tobě, tys je s nebe vyslýchal, a podlé mnohých slitování svých dával jsi jim vysvoboditele, kteříž je vysvobozovali z ruky nepřátel jejich.'),
(1558732,54,16,9,28,'Mezitím, jakž jen oddechnutí měli, zase znovu činili zlé před tebou, a protož pouštěl jsi je v ruku nepřátel jejich, aby panovali nad nimi. Když se pak opět obrátili, a křičeli k tobě, tys je s nebe vyslýchal a vysvobozoval podlé slitování svých po mnohé časy.'),
(1558733,54,16,9,29,'A napomínals jich, abys je obrátil k zákonu svému, ale oni pyšně sobě počínali, a neposlouchali přikázaní tvých, a proti soudům tvým hřešili, v nichžto, činil-li by je člověk, byl by živ. Nýbrž plece svého uchylujíce, šíji svou zatvrzovali, a neposlouchali.'),
(1558734,54,16,9,30,'A však shovíval jsi jim po mnohá léta, osvědčuje jim duchem svým skrze proroky své, a když neposlouchali, dal jsi je v ruku národům zemí.'),
(1558735,54,16,9,31,'Ale pro slitování svá mnohá nedals jim do konce zahynouti, aniž jsi jich opustil, proto že jsi Bůh milostivý a lítostivý.'),
(1558736,54,16,9,32,'Nyní tedy, ó Bože náš, silný, veliký, mocný a hrozný, kterýž ostříháš smlouvy a milosrdenství, nechť to není u tebe za málo, že ty všecky těžkosti na nás přišly, na krále naše, knížata naše, kněží naše, proroky naše i na otce naše, a na všecken lid tvůj, hned ode dnů králů Assyrských, až do tohoto dne,'),
(1558737,54,16,9,33,'Ačkoli ty jsi spravedlivý ve všech těch věcech, kteréž přišly na nás. Nebo jsi spravedlivě to učinil, ale my jsme bezbožně činili.'),
(1558738,54,16,9,34,'I králové naši, knížata naše, kněží naši i otcové naši neplnili zákona tvého, aniž šetřili přikázaní tvých a svědectví tvých, jimiž se jim osvědčoval.'),
(1558739,54,16,9,35,'Nebo oni v království svém a v dobrodiní tvém hojném, kteréž jsi jim ukazoval, a v zemi široké a úrodné, kterouž jsi jim dal, nesloužili tobě, aniž se odvrátili od činů svých zlých.'),
(1558740,54,16,9,36,'Aj, my jsme dnes manové, a to v zemi, kterouž jsi dal otcům našim, aby jedli ovoce její a dobré věci její, aj, jsme v ní manové.'),
(1558741,54,16,9,37,'Jižť úrody své vydává v hojnosti králům, kteréž jsi postavil nad námi pro hříchy naše, a oniť i nad těly našimi se potřásají, i nad hovady našimi podlé vůle své, tak že jsme u veliké úzkosti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558742,54,16,9,38,'Se vším však tím činíme smlouvu nepohnutelnou, i zapisujeme, kteréž potvrzují knížata naše, Levítové naši, i kněží naši.'),
(1558743,54,16,10,1,'Kteříž pak potvrzovali, byli tito: Nehemiáš Tirsata, syn Chachaliášův, a Sedechiáš,'),
(1558744,54,16,10,2,'Saraiáš, Azariáš, Jeremiáš,'),
(1558745,54,16,10,3,'Paschur, Amariáš, Malkiáš,'),
(1558746,54,16,10,4,'Chattus, Sebaniáš, Malluch,'),
(1558747,54,16,10,5,'Charim, Meremot, Abdiáš,'),
(1558748,54,16,10,6,'Daniel, Ginneton, Báruch,'),
(1558749,54,16,10,7,'Mesullam, Abiáš, Miamin,'),
(1558750,54,16,10,8,'Maaseiáš, Bilkai, Semaiáš. To kněží.'),
(1558751,54,16,10,9,'Levítové pak: Jesua syn Azaniášův, Binnui z synů Chenadad, Kadmiel.'),
(1558752,54,16,10,10,'Bratří pak jejich: Sebaniáš, Hodiáš, Kelita, Pelaiáš, Chanan,'),
(1558753,54,16,10,11,'Mícha, Rechob, Chasabiáš,'),
(1558754,54,16,10,12,'Zakur, Serebiáš, Sebaniáš,'),
(1558755,54,16,10,13,'Hodiáš, Báni, Beninu.'),
(1558756,54,16,10,14,'Přední z lidu: Paros, Pachat Moáb, Elam, Zattu, Báni,'),
(1558757,54,16,10,15,'Bunni, Azgad, Bebai,'),
(1558758,54,16,10,16,'Adoniáš, Bigvai, Adin,'),
(1558759,54,16,10,17,'Ater, Ezechiáš, Azur,'),
(1558760,54,16,10,18,'Hodiáš, Chasum, Bezai,'),
(1558761,54,16,10,19,'Charif, Anatot, Nebai,'),
(1558762,54,16,10,20,'Magpias, Mesullam, Chezir,'),
(1558763,54,16,10,21,'Mesezabel, Sádoch, Jaddua,'),
(1558764,54,16,10,22,'Pelatiáš, Chanan, Anaiáš,'),
(1558765,54,16,10,23,'Ozeáš, Chananiáš, Chasub,'),
(1558766,54,16,10,24,'Loches, Pilcha, Sobek,'),
(1558767,54,16,10,25,'Rechum, Chasabna, Maaseiáš,'),
(1558768,54,16,10,26,'Achiáš, Chanan, Anan,'),
(1558769,54,16,10,27,'Malluch, Charim, Baana.'),
(1558770,54,16,10,28,'Tak i jiní z lidu, kněží, Levítů, vrátných, zpěváků, Netinejských i všickni, kteříž se oddělili od národů zemí k zákonu Božímu, ženy jejich, synové jejich i dcery jejich, každý umělý a rozumný,'),
(1558771,54,16,10,29,'Chopivše se téhož s bratřími svými a těmi, kteříž byli přednější, přistupovali, prokletím a přísahou se zavazujíce: Že budeme choditi v zákoně Božím, kterýž vydán jest skrze Mojžíše služebníka Božího, a ostříhati i plniti všecka přikázaní Hospodina Pána našeho, i soudy jeho, i ustanovení jeho;'),
(1558772,54,16,10,30,'Také že nebudeme dávati dcer svých národům zemí, ani dcer jejich bráti synům svým,'),
(1558773,54,16,10,31,'Ani od cizozemců, kteříž by nám přinášeli jaké koupě a jakékoli potravy v den sobotní na prodaj, přijímati v sobotu aneb v sváteční den, a že necháme rolí sedmého léta, i všelikého dobývání dluhu.'),
(1558774,54,16,10,32,'I to nařídili jsme mezi sebou, abychom dávali třetí díl lotu na každý rok k službě domu Boha našeho,'),
(1558775,54,16,10,33,'Na chleby zpořádaní, i obět ustavičnou, i na zápal ustavičný k sobotám, novměsícům a slavnostem, i na věci svaté, i oběti za hříchy k očištění Izraele, i na všecko přisluhování domu Boha našeho.'),
(1558776,54,16,10,34,'Metali jsme i losy s strany kněží, Levítů i lidu, příčinou dříví nošení, aby ho dodávali do domu Boha našeho, čeledem otců našich časy vyměřenými, rok po roku, aby hořelo na oltáři Hospodina Boha našeho, jakž psáno jest v zákoně.'),
(1558777,54,16,10,35,'Také, že chceme přinášeti prvotiny země své, i prvotiny všelikého ovoce každého stromu, rok po roku do domu Hospodinova.'),
(1558778,54,16,10,36,'K tomu i prvorozené syny své, i hovádka svá, (jakož psáno jest v zákoně), i prvorozené z skotů i bravů svých, že přinášeti budeme do domu Boha svého, kněžím přisluhujícím v domě Boha našeho.'),
(1558779,54,16,10,37,'A prvotiny těsta svého i obětí svých, i ovoce všelijakého stromu, mstu i oleje nového, aby přinášeli kněžím do pokojů domu Boha našeho, a desátky země naší Levítům. A Levítové desátky ty vybírati budou po všech městech, v nichž pracovati budeme.'),
(1558780,54,16,10,38,'Bude pak při tom kněz, syn Aronův, s Levíty, když Levítové ty desátky vyberou, a Levítové sami vnesou desátek z desátků do domu Boha našeho, do pokojů v domě skladu.'),
(1558781,54,16,10,39,'Nebo do těch pokojů donášeti budou synové Izraelští i synové Léví oběti obilé, mstu a oleje nového, (kdež jsou nádoby svatyně), i kněží přisluhující, vrátní i zpěváci, abychom neopouštěli domu Boha svého.'),
(1558782,54,16,11,1,'I přebývala knížata lidu v Jeruzalémě. Jiný pak lid metali losy, aby vzali desátého člověka k bydlení v Jeruzalémě městě svatém, ale devět dílů v jiných městech,'),
(1558783,54,16,11,2,'Ačkoli dobrořečil lid všechněm mužům těm, kteříž se sami dobrovolně podali k bydlení v Jeruzalémě.'),
(1558784,54,16,11,3,'A tito jsou přednější té krajiny, kteříž se osadili v Jeruzalémě. (V jiných pak městech Judských bydlili jeden každý v vládařství svém, po městech svých, lid Izraelský, kněží a Levítové, i Netinejští, též i synové služebníků Šalomounových.)'),
(1558785,54,16,11,4,'A tak v Jeruzalémě bydlili někteří z synů Judových i z synů Beniaminových. Z Judových: Ataiáš syn Uziáše, syna Zachariášova, syna Amariášova, syna Sefatiášova, syna Mahalaleelova z synů Fáresových.'),
(1558786,54,16,11,5,'Též Maaseiáš syn Bárucha, syna Kolchozy, syna Chazaiášova, syna Adaiášova, syna Joiaribova, syna Zachariášova, syna Silonského.'),
(1558787,54,16,11,6,'Všech synů Fáresových, bydlících v Jeruzalémě, čtyři sta šedesáte osm, mužů udatných.'),
(1558788,54,16,11,7,'Synové Beniaminovi tito: Sallu syn Mesullama, syna Joedova, syna Pedaiášova, syna Kolaiášova, syna Maaseiášova, syna Itielova, syna Izaiášova.'),
(1558789,54,16,11,8,'A po něm Gabai, Sallai. Všech devět set dvadceti osm.'),
(1558790,54,16,11,9,'Joel pak syn Zichri byl jim představen, a Juda syn Senua nad městem druhý po něm.'),
(1558791,54,16,11,10,'Z kněží: Jedaiáš syn Joiaribův a Jachin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558792,54,16,11,11,'Saraiáš syn Helkiáše, syna Mesullamova, syna Sádochova, syna Meraiotova, syna Achitobova, přední v domě Božím.'),
(1558793,54,16,11,12,'Bratří pak jejich, přisluhujících v tom domě, osm set dvadceti dva. A Adaiáš syn Jerochama, syna Pelaliášova, syna Amzi, syna Zachariášova, syna Paschurova, syna Malkiášova,'),
(1558794,54,16,11,13,'A bratří jeho, knížat čeledí otcovských, dvě stě čtyřidceti dva. A Amassai syn Azarele, syna Achzai, syna Mesillemotova, syna Immerova.'),
(1558795,54,16,11,14,'Bratří pak jejich, mužů udatných, sto dvadceti osm, jimž představen byl Zabdiel syn Gedolimův.'),
(1558796,54,16,11,15,'Z Levítů tito: Semaiáš syn Chasuby, syna Azrikamova, syna Chasabiášova, syna Bunni.'),
(1558797,54,16,11,16,'A Sabbetai s Jozabadem byli nad dílem při domě Božím vně, z předních Levítů.'),
(1558798,54,16,11,17,'A Mataniáš syn Míchy, syna Zabdi, syna Azafova, přední, začínal chvály a modlitbu. A Bakbukiáš druhý z bratří jeho, a Abda syn Sammua, syna Galalova, syna Jedutunova.'),
(1558799,54,16,11,18,'Všech Levítů v městě svatém dvě stě osmdesát a čtyři.'),
(1558800,54,16,11,19,'Z vrátných: Akkub, Talmon a bratří jejich, strážní u bran, sto sedmdesát a dva.'),
(1558801,54,16,11,20,'Ostatek pak lidu Izraelského, kněží a Levítů, bydlili ve všech městech Judských, jeden každý v dědictví svém.'),
(1558802,54,16,11,21,'Ale Netinejští bydlili v Ofel, Zicha pak a Gispa byli představeni Netinejským.'),
(1558803,54,16,11,22,'Představený pak Levítům v Jeruzalémě byl Uzi syn Báni, syna Chasabiášova, syna Mataniášova, syna Míchova z synů Azafových, jenž byli zpěváci při službě domu Božího.'),
(1558804,54,16,11,23,'Nebo poručení královské bylo o nich, a stálé odměření pro zpěváky na každý den.'),
(1558805,54,16,11,24,'A Petachiáš syn Mesezabelův, z synů Záry syna Judova, místo královské držící v každém jednání k lidu.'),
(1558806,54,16,11,25,'Ve vsech pak s poli jejich, z synů Judových bydlili v Kariatarbe a v vesnicích jeho, v Dibon a vesnicích jeho, v Jekabsael i ve vsech jeho,'),
(1558807,54,16,11,26,'A v Jesua, v Molada, v Betfelet,'),
(1558808,54,16,11,27,'A v Azarsual, v Bersabé i v vesnicích jeho.'),
(1558809,54,16,11,28,'A v Sicelechu, v Mechona, i v vesnicích jeho,'),
(1558810,54,16,11,29,'V Enremmon, v Zaraha, v Jarmut,'),
(1558811,54,16,11,30,'V Zanoe, v Adulam i ve vsech jeho, v Lachis s poli jeho, v Azeka a vesnicích jeho. A tak bydlili od Bersabé až do Gehinnom.'),
(1558812,54,16,11,31,'Synové pak Beniaminovi z Gabaa v Michmas, v Aia, v Bethel i v vesnicích jeho,'),
(1558813,54,16,11,32,'V Anatot, v Nobe, v Anania,'),
(1558814,54,16,11,33,'V Azor, v Ráma, v Gittaim,'),
(1558815,54,16,11,34,'V Chadid, v Seboim, v Neballat,'),
(1558816,54,16,11,35,'V Lod, v Ono a v údolí řemeslníků.'),
(1558817,54,16,11,36,'Z Levítů pak někteří bydlili v dílích Judských a Beniaminských.'),
(1558818,54,16,12,1,'Tito pak jsou kněží a Levítové, kteříž se byli navrátili s Zorobábelem synem Salatielovým, a s Jesua: Saraiáš, Jeremiáš, Ezdráš,'),
(1558819,54,16,12,2,'Amariáš, Malluch, Chattus,'),
(1558820,54,16,12,3,'Sechaniáš, Rechum, Meremot,'),
(1558821,54,16,12,4,'Iddo, Ginnetoi, Abiáš,'),
(1558822,54,16,12,5,'Miamin, Maadiáš, Bilga,'),
(1558823,54,16,12,6,'Semaiáš, Joiarib, Jedaiáš,'),
(1558824,54,16,12,7,'Sallu, Amok, Helkiáš, Jedaiáš. Ti byli přednější z kněží a bratří svých za času Jesua.'),
(1558825,54,16,12,8,'Levítové pak: Jesua, Binnui, Kadmiel, Serebiáš, Juda; Mattaniáš, postavený nad zpěvy chvalitebnými s bratřími svými.'),
(1558826,54,16,12,9,'A Bakbukiáš a Unni, bratří jejich, byli naproti nim v pořádcích svých.'),
(1558827,54,16,12,10,'Jesua pak zplodil Joiakima, a Joiakim zplodil Eliasiba, Eliasib pak zplodil Joiadu.'),
(1558828,54,16,12,11,'A Joiada zplodil Jonatana, Jonatan pak zplodil Jaddua.'),
(1558829,54,16,12,12,'Za času pak Joiakima byli přední kněží z čeledí otcovských: Z Saraiášovy Meraiáš, z Jeremiášovy Chananiáš,'),
(1558830,54,16,12,13,'Z Ezdrášovy Mesullam, z Amariášovy Jochanan,'),
(1558831,54,16,12,14,'Z Melichovy Jonatan, z Sebaniášovy Jozef,'),
(1558832,54,16,12,15,'Z Charimovy Adna, z Meraiotovy Chelkai,'),
(1558833,54,16,12,16,'Z Iddovy Zachariáš, z Ginnetonovy Mesullam,'),
(1558834,54,16,12,17,'Z Abiášovy Zichri, z Miniaminovy a z Moadiášovy Piltai,'),
(1558835,54,16,12,18,'Z Bilgovy Sammua, z Semaiášovy Jonatan,'),
(1558836,54,16,12,19,'Z Joiaribovy Mattenai, z Jedaiášovy Uzi,'),
(1558837,54,16,12,20,'Z Sallaiovy Kallai, z Amokovy Heber,'),
(1558838,54,16,12,21,'Z Helkiášovy Chasabiáš, z Jedaiášovy Natanael.'),
(1558839,54,16,12,22,'Levítové pak přednější z čeledí otcovských za dnů Eliasiba, Joiady, Jochanana a Jaddua, zapsáni jsou až do kralování Daria Perského.'),
(1558840,54,16,12,23,'Synové, pravím, Léví, přední v čeledech otcovských, zapsáni jsou v knize Paralipomenon, až do času Jochanana syna Eliasibova.'),
(1558841,54,16,12,24,'Potom přední Levítové: Chasabiáš, Serebiáš, a Jesua syn Kadmielův, a bratří jejich naproti nim k chválení a oslavování Boha, podlé nařízení Davida muže Božího, třída proti třídě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558842,54,16,12,25,'Mataniáš, Bakbukiáš, Abdiáš, Mesullam, Talmon, Akkub, držící stráž vrátných při domu pokladů u bran.'),
(1558843,54,16,12,26,'Ti byli za času Joiakima , syna Jesua, syna Jozadakova, a za času Nehemiáše vůdce, a Ezdráše kněze a učitele.'),
(1558844,54,16,12,27,'Ku posvěcování pak zdí Jeruzalémských shlédávali Levíty ze všech míst jejich, aby je přivedli do Jeruzaléma, aby vykonali posvěcení a veselí, a to s oslavováním a zpěvy, cymbály, loutnami a harfami.'),
(1558845,54,16,12,28,'Protož shromážděni jsou synové zpěváků, i z rovin okolo Jeruzaléma, i ze vsí Netofatských,'),
(1558846,54,16,12,29,'Též z domu Galgal, a z polí Gaba i Azmavet; nebo vsi stavěli sobě zpěváci okolo Jeruzaléma.'),
(1558847,54,16,12,30,'A očistivše se kněží a Levítové, očistili také lid, brány i zed.'),
(1558848,54,16,12,31,'Za tím rozkázal jsem vstoupiti knížatům Judským na zed, a postavil jsem dva houfy veliké oslavujících, z nichž jedni šli na pravo, od horní strany zdi k bráně hnojné.'),
(1558849,54,16,12,32,'A za těmi šel Hosaiáš a polovice knížat Judských,'),
(1558850,54,16,12,33,'Též Azariáš, Ezdráš, a Mesullam,'),
(1558851,54,16,12,34,'Juda, Beniamin, Semaiáš a Jeremiáš.'),
(1558852,54,16,12,35,'Potom za syny kněžskými s trubami Zachariáš syn Jonatana, syna Semaiášova, syna Mattaniášova, syna Michaiášova, syna Zakurova, syna Azafova.'),
(1558853,54,16,12,36,'A bratří jeho: Semaiáš, Azarel, Milalai, Gilalai, Maai, Natanael a Juda, Chanani s nástroji hudebnými Davida muže Božího, Ezdráš pak učitel před nimi.'),
(1558854,54,16,12,37,'Potom k bráně u studnice, kteráž naproti nim byla, vstupovali po stupních města Davidova, kudy se chodí na zed, a ode zdi při domě Davidově, až k bráně vodné k východu.'),
(1558855,54,16,12,38,'Houf pak druhý oslavujících bral se naproti oněmno, a já za nimi, a polovice lidu po zdi od věže Tannurim až ke zdi široké,'),
(1558856,54,16,12,39,'A od brány Efraim k bráně staré, a k bráně rybné, a věži Chananeel, a věži Mea, až k bráně bravné. I zastavili se v bráně stráže.'),
(1558857,54,16,12,40,'Potom zastavili se oba houfové oslavujících v domě Božím, i já, a polovice knížat se mnou.'),
(1558858,54,16,12,41,'Ano i kněží: Eliakim, Maaseiáš, Miniamin, Michaiáš, Elioenai, Zachariáš, Chananiáš, s trubami,'),
(1558859,54,16,12,42,'A Maaseiáš, Semaiáš, Eleazar, Uzi, Jochanan, Malkiáš, Elam a Ezer. Zpěváci pak zvučně zpívali s Izrachiášem představeným svým.'),
(1558860,54,16,12,43,'Obětovali také v ten den oběti veliké, a veselili se; nebo Bůh obveselil je veselím velikým. Ano i ženy a děti veselily se, tak že bylo slyšáno veselí Jeruzaléma opodál.'),
(1558861,54,16,12,44,'Mezi tím zřízeni jsou v ten den muži nad komorami k pokladům a k obětem, i k prvotinám a k desátkům, aby shromažďovali do nich s polí městských díly, zákonem vyměřené kněžím a Levítům; nebo veselil se Juda z kněží a Levítů přístojících,'),
(1558862,54,16,12,45,'Kteříž držeti měli stráž Boha svého, a stráž očišťování, a zpěváků i vrátných, podlé nařízení Davidova a Šalomouna syna jeho.'),
(1558863,54,16,12,46,'Nebo za času Davidova a Azafova od starodávna přední zpěváci k zpívání, chválení a oslavování Boha stáli před ním.'),
(1558864,54,16,12,47,'Pročež všecken Izrael za dnů Zorobábele a za času Nehemiáše dávali díly pro zpěváky a vrátné, na každý den stálé odměření, a odvodili je Levítům, Levítové pak dávali synům Aronovým.'),
(1558865,54,16,13,1,'V ten den čteno jest v knize Mojžíšově, tak že lid slyšeti mohl. I nalezeno v ní napsáno, že nemá vjíti Ammonitský a Moábský do shromáždění Božího až na věky,'),
(1558866,54,16,13,2,'Proto že nevyšli proti synům Izraelským s chlebem a s vodou, ale najali ze mzdy proti nim Baláma, aby jim zlořečil, ačkoli obrátil Bůh náš to zlořečení v požehnání.'),
(1558867,54,16,13,3,'Stalo se pak, když slyšeli zákon, že odmísili všecky přimíšené od Izraele.'),
(1558868,54,16,13,4,'Ale před tím Eliasib kněz, správce komory domu Boha našeho, spříznil se s Tobiášem.'),
(1558869,54,16,13,5,'Kterémuž udělal pokoj veliký, kdež prvé skládali dary, kadidlo a nádoby, a desátky z obilé, mstu a oleje nového, nařízené Levítům a zpěvákům i vrátným, též i obět kněžím.'),
(1558870,54,16,13,6,'Ale když se to vše dálo, nebyl jsem v Jeruzalémě. Nebo léta třidcátého druhého Artaxerxa krále Babylonského přišel jsem k králi, a po přeběhnutí let, vyžádán jsem na králi.'),
(1558871,54,16,13,7,'Když jsem pak přišel do Jeruzaléma, srozuměl jsem tomu zlému, co učinil Eliasib pro Tobiáše, udělav mu pokoj v síních domu Božího.'),
(1558872,54,16,13,8,'Což mi se velmi nelíbilo. Protož vyházel jsem všecko nádobí domu Tobiášova ven z toho pokoje.'),
(1558873,54,16,13,9,'A rozkázal jsem očistiti ty pokoje. I vnesl jsem tam zase nádoby domu Božího, dary a kadidlo.'),
(1558874,54,16,13,10,'Potom dověděv se, že dílové Levítům nebyli dáváni, a že rozběhli se jeden každý na svou rolí, Levítové i zpěváci vedoucí práci,'),
(1558875,54,16,13,11,'Protož domlouval jsem se na starší, řka: Proč jest opuštěn dům Boží? A shromáždiv je, postavil jsem je na místě jejich.'),
(1558876,54,16,13,12,'A všecken Juda přinášeli desátky obilé, mstu a oleje nového do skladů.'),
(1558877,54,16,13,13,'A ustanovil jsem úředníky nad sklady: Selemiáše kněze, a Sádocha učitele, a Pedaiáše z Levítů, přidav k nim Chanana syna Zakurova, syna Mattaniášova; nebo za věrné jmíni byli. A ti měli rozdělovati bratřím svým.'),
(1558878,54,16,13,14,'Budiž pamětliv na mne, Bože můj, pro to, a nevyhlazuj dobrodiní mých, kteráž jsem prokázal k domu Boha svého i k službám jeho.'),
(1558879,54,16,13,15,'V těch dnech viděl jsem v Judstvu, ani tlačí presem v sobotu, a přinášejí snopy, kteréž nakládali na osly, též víno, hrozny, fíky i všeliká břemena, a snášejí v den sobotní do Jeruzaléma. I domlouval jsem jim v ten den, když prodávali potravu.'),
(1558880,54,16,13,16,'Tyrští také, kteříž bydlili v něm, nosili ryby i všelijaké koupě, a prodávali v sobotu synům Juda, a to v Jeruzalémě.'),
(1558881,54,16,13,17,'Protož jsem domlouval starším Judským, a řekl jsem jim: Jaká jest to nepravost, kterouž činíte, poškvrňujíce dne sobotního?'),
(1558882,54,16,13,18,'Zdaliž jsou tak nečinili otcové vaši? Pročež Bůh náš přivedl na nás všecko toto zlé, i na toto město, a vy přidáváte hněvivosti na Izraele, poškvrňujíce soboty.'),
(1558883,54,16,13,19,'Když tedy byly v stínu brány Jeruzalémské před sobotou, rozkázal jsem zavříti brány, a rozkázal jsem, aby jich neotvírali až po sobotě. K tomu i z služebníků svých některé postavil jsem v bráně, aby náklad nebyl vezen do města v sobotu.'),
(1558884,54,16,13,20,'Protož zůstali kupci a prodavači všelijakých věcí prodajných vně před Jeruzalémem, jednou i podruhé.'),
(1558885,54,16,13,21,'I osvědčil jsem se jim, řka jim: Proč zůstáváte přes noc naproti zdi? Učiníte-li to více, vztáhnu ruku na vás. Od té chvíle nepřicházeli v sobotu.'),
(1558886,54,16,13,22,'Rozkázal jsem pak Levítům, aby se očistili, a přijdouce, ostříhali bran, a světili den sobotní. Také i v tom pamatuj na mne, Bože můj, a buď mi milostiv podlé množství milosrdenství svého.'),
(1558887,54,16,13,23,'V těch dnech spatřil jsem také Židy, kteříž byli pojali ženy Azotské, Ammonitské a Moábské,'),
(1558888,54,16,13,24,'An synové jejich mluvili od polu Azotsky, a neuměli mluviti Židovsky, ale podlé jazyku každého toho lidu.'),
(1558889,54,16,13,25,'Protož domlouval jsem jim, a zlořečil jsem jim, a některé z nich bil jsem a rval, přísahou je zavazuje skrze Boha, řka: Budete-li dávati dcery své synům jejich, aneb bráti dcery jejich synům svým neb sobě, zlořečení budete.'),
(1558890,54,16,13,26,'Zdaliž tím nezhřešil Šalomoun král Izraelský? Ješto ve mnohých národech nebylo krále jemu podobného, kterýž byl milý Bohu svému, tak že ustanovil jej Bůh králem nade vším Izraelem, však i toho k hříchu přivedly ženy cizozemky.'),
(1558891,54,16,13,27,'A vám zdali povolíme, abyste se dopouštěli všeho toho zlého velikého, a přestupovali proti Bohu svému, pojímajíce ženy cizozemky?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558892,54,16,13,28,'Z synů pak Joiady syna Eliasiba, kněze nejvyššího, jeden byl zeť Sanballata Choronského, kteréhož jsem zahnal od sebe.'),
(1558893,54,16,13,29,'Budiž pamětliv na to, Bože můj, proti těm, kteříž poškvrňují kněžství, a smlouvy kněžské i Levítské.'),
(1558894,54,16,13,30,'Protož jsem je vyčistil od všelikého cizozemce, a ustanovil jsem zase třídy kněžím a Levítům, jednomu každému v práci jeho,'),
(1558895,54,16,13,31,'I nošení dříví k obětem časy uloženými, též i prvotin. Budiž pamětliv na mne, Bože můj, k mému dobrému.'),
(1558896,54,17,1,1,'Stalo se pak za času krále Asvera, (to jest ten Asverus, jenž kraloval od Indie až k Mouřenínské zemi nad sto dvadcíti a sedmi krajinami),'),
(1558897,54,17,1,2,'Že toho času, když seděl král Asverus na stolici království svého, jenž byla v Susan, městě královském,'),
(1558898,54,17,1,3,'Léta třetího kralování svého, učinil u sebe hody všechněm knížatům svým a služebníkům svým, nejznamenitějším Perským a Médským, hejtmanům a vládařům nad krajinami,'),
(1558899,54,17,1,4,'Ukazuje bohatství, slávu království svého a čest, i ozdobu důstojnosti své za mnoho dnů, totiž za sto a osmdesáte dnů.'),
(1558900,54,17,1,5,'(A když se vyplnili dnové ti, učinil král všemu lidu, což ho koli bylo v Susan městě královském, od největšího až do nejmenšího, hody za sedm dní na paláci v zahradě při domě královském.)'),
(1558901,54,17,1,6,'Též čalouny bílé, zelené a z postavce modrého, zavěšené na provázcích kmentových a šarlatových u kroužků stříbrných, na sloupích mramorových, lůžka zlatá a stříbrná na podlaze porfyretové a mramorové, pariové a socharetové.'),
(1558902,54,17,1,7,'Nápoj pak dávali v nádobách zlatých, a to v nádobách jiných a jiných, i vína královského v hojnosti, jakž slušelo na krále.'),
(1558903,54,17,1,8,'Ale ku pití, podlé nařízení, žádný nenutil. Nebo tak poručil král všechněm správcům domu svého, aby činili podlé vůle jednoho každého.'),
(1558904,54,17,1,9,'Také i královna Vasti učinila hody ženám v domě královském krále Asvera.'),
(1558905,54,17,1,10,'Dne pak sedmého, když se podveselil král vínem, rozkázal Mehumanovi, Biztovi, Charbonovi, Bigtovi a Abagtovi, Zetarovi a Karkasovi, sedmi komorníkům, kteříž sloužili před oblíčejem krále Asvera,'),
(1558906,54,17,1,11,'Aby přivedli Vasti královnu před oblíčej krále v koruně královské, aby okázal národům i knížatům krásu její; nebo velmi krásná byla.'),
(1558907,54,17,1,12,'Ale odepřela královna Vasti přijíti k rozkazu královskému, skrze ty komorníky vzkázanému. Pročež král rozhněval se velmi a rozpálil se hněvem sám v sobě.'),
(1558908,54,17,1,13,'I řekl král mudrcům znajícím časy, (nebo tak každé věci podával král na všecky zběhlé v právích a soudech),'),
(1558909,54,17,1,14,'A nejbližšímu sebe Charsenovi, Setarovi, Admatovi, Tarsisovi, Meresovi, Marsenovi, Memuchanovi, sedmi vývodám Perským a Médským, jenž vídali tvář královskou, a sedali první po králi:'),
(1558910,54,17,1,15,'Co se má podlé práva státi s královnou Vasti, proto že nevyplnila rozkazu krále Asvera, stalého skrze komorníky?'),
(1558911,54,17,1,16,'Tedy řekl Memuchan před králem i knížaty: Ne proti samému králi zavinila královna Vasti, ale proti všechněm knížatům, a proti všechněm národům všech krajin Asvera krále.'),
(1558912,54,17,1,17,'Nebo když se donese to, co učinila královna, všech žen, zlehčí sobě muže své a řeknou: An král Asverus rozkázal přivésti královnu Vasti před oblíčej svůj, a však nepřišla.'),
(1558913,54,17,1,18,'Nýbrž ještě tohoto dne budou to mluviti kněžny Perské a Médské, (kteréž slyšely, co učinila královna), všechněm knížatům královským, i naplodí se hojně pýchy a zpoury.'),
(1558914,54,17,1,19,'Jestliže se tedy králi za dobré vidí, nechť se stane výpověď královská od oblíčeje jeho, a nechť jest vepsána mezi práva Perská a Médská, kteráž by nemohla změněna býti, že nechtěla přijíti Vasti před oblíčej krále Asvera, pročež království její dá král jiné, lepší nežli ona.'),
(1558915,54,17,1,20,'Tak když uslyší výpověd královskou, kterouž vyhlásiti dá po všem království svém, jakkoli veliké jest, všecky ženy v poctivosti míti budou manžely své, od největšího až do nejmenšího.'),
(1558916,54,17,1,21,'I líbila se ta rada králi i knížatům, a učinil král podlé rady Memuchanovy.'),
(1558917,54,17,1,22,'A rozeslal listy do všech krajin královských, do jedné každé krajiny písmem jejím, a do každého národu jazykem jeho, aby každý muž byl pánem domu svého. Což oznámil každý hejtman lidu jazykem jeho.'),
(1558918,54,17,2,1,'Ty věci když se zběhly, a když se upokojila prchlivost krále Asvera, zpomenul na Vasti a na to, což byla učinila, též i na to, jaká se výpověd stala proti ní.'),
(1558919,54,17,2,2,'I řekli mládenci královští, služebníci jeho: Nechť hledají králi mladic, panen krásných.'),
(1558920,54,17,2,3,'A nechť zřídí král úředníky ve všech krajinách království svého, kteříž by shromáždili všecky mladice, panny krásné, do Susan města královského, do domu ženského, pod stráž Hegai komorníka královského, strážce žen, a ať jim vydává okrasy jejich.'),
(1558921,54,17,2,4,'A mladice, kteráž by se zalíbila králi, aby kralovala místo Vasti. I líbila se ta věc králi, a učinil tak.'),
(1558922,54,17,2,5,'Byl pak jeden Žid v Susan, městě královském, jménem Mardocheus syn Jairův, syna Simei, syna Cis, z pokolení Beniamin.'),
(1558923,54,17,2,6,'A ten byl přestěhován z Jeruzaléma s přestěhovanými, kteříž přestěhováni byli s Jekoniášem králem Judským, kteréhož přestěhoval Nabuchodonozor král Babylonský.'),
(1558924,54,17,2,7,'Ten choval Hadassu, jinak Esteru, dceru strýce svého, proto že neměla otce ani matky. A děvečka ta byla pěkné postavy a krásné tváři, kterouž po smrti otce a matky její vzal sobě Mardocheus za dceru.'),
(1558925,54,17,2,8,'Stalo se tedy, když vyšlo slovo královské a rozkaz jeho, a když shromážďováno bylo panen mnoho do Susan, města královského, pod stráž Hegai, že i Ester vzata byla do domu královského pod stráž Hegai, strážného nad ženami.'),
(1558926,54,17,2,9,'I líbila se jemu ta mladice, a našla milost u něho. Pročež i hned dal jí okrasu její a díl její, a sedm panen způsobných z domu královského; k tomu opatření její i jejích panen proměnil v lepší v domě ženském.'),
(1558927,54,17,2,10,'Neoznámila pak Ester lidu svého, ani rodiny své; nebo přikázal jí byl Mardocheus, aby nepravila.'),
(1558928,54,17,2,11,'Ale Mardocheus každého dne chodíval před síní domu ženského, aby zvěděl, jak se má Ester, a co se s ní děje.'),
(1558929,54,17,2,12,'Když pak přišel jistý čas jedné každé panny, aby vešla před krále Asvera, když se vyplnilo při ní podlé práva žen, za dvanácte měsíců, (nebo za tolik dnů ozdobovaly se, šest měsíců olejem mirrovým, a šest měsíců věcmi vonnými a ozdobami ženskými),'),
(1558930,54,17,2,13,'A tak přicházela panna před krále. Cožkoli řekla, dávalo se jí, aby s tím šla z domu žen až k domu královskému.'),
(1558931,54,17,2,14,'U večer vcházela k králi, a ráno zase odcházela do druhého domu ženského, pod stráž Saasgazy, komorníka královského, strážce ženin. Nepřicházela více k králi, ale jestliže se líbila králi, povolána bývala ze jména.'),
(1558932,54,17,2,15,'Tedy když přišel čas jistý Estery, dcery Abichaile, strýce Mardocheova, kterouž byl vzal sobě za dceru, aby vešla k králi, nežádala ničeho, než což řekl Hegai komorník královský, strážce žen. I líbila se Ester všechněm, kteříž ji viděli.'),
(1558933,54,17,2,16,'A tak vzata jest Ester k králi Asverovi do domu jeho královského, měsíce desátého, (jenž jest měsíc Tebet), léta sedmého kralování jeho.'),
(1558934,54,17,2,17,'I zamiloval král Ester nade všecky jiné ženy, a nalezla milost a lásku u něho nade všecky panny, tak že vstavil korunu královskou na hlavu její, a učinil ji královnou místo Vasti.'),
(1558935,54,17,2,18,'K tomu také učinil král hody veliké všechněm knížatům svým a služebníkům svým, totiž hody Estery, a dal odpočinutí krajinám, a daroval je tak, jakž slušelo na krále.'),
(1558936,54,17,2,19,'A když podruhé shromažďovány byly panny, a Mardocheus seděl u brány královské,'),
(1558937,54,17,2,20,'Ester pak neoznámila byla rodiny své a národu svého, jakž jí byl přikázal Mardocheus; nebo rozkázaní Mardocheovo Ester činila, jako i když chována byla u něho:'),
(1558938,54,17,2,21,'V těch dnech, (když Mardocheus sedal u brány královské), rozhněval se Bigtan a Teres, dva komorníci královští z strážných prahu, a smýšleli o to, aby vztáhli ruce na krále Asvera.'),
(1558939,54,17,2,22,'Čehož dověděv se Mardocheus, oznámil to Ester královně, Ester pak oznámila králi jménem Mardocheovým.'),
(1558940,54,17,2,23,'A když bylo toho vyhledáváno, našlo se tak. I oběšeni jsou ti oba na šibenici, a zapsáno jest to do kronik před králem.'),
(1558941,54,17,3,1,'Po těch věcech zvelebil král Asverus Amana syna Hammedatova Agagského, a vyvýšil ho, tak že vyzdvihl stolici jeho nade všecka jiná knížata, kteříž byli při něm.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558942,54,17,3,2,'A všickni služebníci královští, kteříž vcházeli do brány královské, klaněli se a padali před Amanem; nebo tak přikázal o něm král. Ale Mardocheus se neklaněl, ani padal.'),
(1558943,54,17,3,3,'Protož řekli služebníci královští, kteříž byli v bráně královské, Mardocheovi: Proč přestupuješ přikázaní královské?'),
(1558944,54,17,3,4,'I stalo se, když o to s ním mluvívali každého dne, a neposlechl jich, že to oznámili Amanovi, aby viděli, bude-li stálý v svých slovích Mardocheus; nebo oznámil jim, že jest Žid.'),
(1558945,54,17,3,5,'Vida pak Aman, že se Mardocheus neklaní, ani padá před ním, naplněn jest Aman prchlivostí.'),
(1558946,54,17,3,6,'Ale za malou věc sobě položil, vztáhnouti ruku na Mardochea samého, (nebo byli oznámili jemu, z kterého by lidu byl Mardocheus). Protož smýšlel Aman, aby zahubil národ Mardocheův, totiž všecky Židy, kteříž byli ve všem království Asverovu.'),
(1558947,54,17,3,7,'Takž měsíce prvního, totiž měsíce Nísan, léta dvanáctého kralování Asverova, rozkázal uvrci pur, totiž los, před sebou ode dne ke dni, a od měsíce až do měsíce dvanáctého, jenž jest měsíc Adar.'),
(1558948,54,17,3,8,'Nebo byl řekl Aman králi Asverovi: Jest lid jakýsi rozptýlený a roztroušený mezi lidem ve všech krajinách království tvého, jejichž práva rozdílná jsou ode všech národů, práv pak královských neostříhají. Protož králi není užitečné, nechati jich.'),
(1558949,54,17,3,9,'Jestliže se králi za dobré vidí, nechť se napíše, aby je zahladili, a já deset tisíc centnéřů stříbra odvážím do rukou představeným té práci, aby je vnesli do komory královské.'),
(1558950,54,17,3,10,'Tedy král sňav prsten svůj s ruky své, dal jej Amanovi synu Hammedatovu Agagskému, nepříteli Židovskému.'),
(1558951,54,17,3,11,'A řekl král Amanovi: Stříbro to daruji tobě i lid ten, abys naložil s ním, jakť se koli líbí.'),
(1558952,54,17,3,12,'Protož povoláni jsou písaři královští téhož měsíce prvního třináctého dne, a psáno jest všecko tak, jakž přikázal Aman, k knížatům královským i vývodám, kteříž byli v jedné každé krajině, i hejtmanům jednoho každého národu, každé krajině vedlé písma jejího, a každému národu vedlé jazyku jeho; jménem krále Asvera psáno, a zapečetěno prstenem královským.'),
(1558953,54,17,3,13,'I jsou posláni listové po poslích do všech krajin královských, aby hubili, mordovali a vyhladili všecky Židy, od mladého až do starce, děti i ženy, jednoho dne, totiž třináctého, měsíce dvanáctého, (jenž jest měsíc Adar), a loupeže jejich aby rozbitovali.'),
(1558954,54,17,3,14,'Summa toho psání byla: Aby vyhlášeno bylo v jedné každé krajině a oznámeno všechněm národům, aby hotovi byli ke dni tomu.'),
(1558955,54,17,3,15,'Tedy vyjeli poslové stěží s poručením královským, a vyhlášeno jest to v Susan, městě královském. Král pak a Aman seděli, kvasíce, ale měšťané Susan zkormouceni byli.'),
(1558956,54,17,4,1,': Mardocheus pak zvěděv všecko to, což se bylo stalo, roztrhl roucho své, a vzal na sebe žíni a popel, a jda po městě, křičel křikem velikým a žalostným.'),
(1558957,54,17,4,2,'A přišel až před bránu královskou; nebo žádný neměl vcházeti do brány královské v oděvu žíněném.'),
(1558958,54,17,4,3,'V každé také krajině i místě, kamžkoli slovo královské a výpověd jeho došla, kvílení veliké bylo od Židů, a půst, pláč i úpění, a žíni s popelem podestřeli sobě mnozí.'),
(1558959,54,17,4,4,'Pročež přišedše děvečky Estery a komorníci její, oznámili jí to. I zarmoutila se královna velmi, a poslala šaty, aby oblékli Mardochea, a aby vzali žíni jeho od něho. Ale on jich nepřijal.'),
(1558960,54,17,4,5,'Tedy zavolavši Ester Hatacha, jednoho z komorníků královských, kteréhož jí byl dal za služebníka, poručila mu o Mardocheovi, aby přezvěděl, co a proč by to bylo.'),
(1558961,54,17,4,6,'Takž vyšel Hatach k Mardocheovi na ulici města, kteráž jest před branou královskou.'),
(1558962,54,17,4,7,'I oznámil jemu Mardocheus všecko, co se mu přihodilo, i o té summě peněz, kterouž připověděl Aman dáti do komory královské proti Židům, k vyhlazení jich.'),
(1558963,54,17,4,8,'K tomu i přípis psané výpovědi, kteráž vyhlášena byla v Susan, aby zhubeni byli, dal jemu, aby ukázal Ester a oznámil jí, a aby jí rozkázal jíti k králi, a milosti hledati u něho, a prositi před tváří jeho za lid svůj.'),
(1558964,54,17,4,9,'Tedy přišel Hatach, a oznámil Ester slova Mardocheova.'),
(1558965,54,17,4,10,'I řekla Ester Hatachovi, a poručila mu oznámiti Mardocheovi:'),
(1558966,54,17,4,11,'Všickni služebníci královští i lid krajin královských vědí, že kterýž by koli muž neb žena všel před krále do síně vnitřní, nejsa povolán, jedno právo o něm jest, aby hrdlo propadl, kromě toho, k komuž by král vztáhl berlu zlatou, že živ zůstane. Já pak nebyla jsem povolána, abych vešla k králi již třidceti dnů.'),
(1558967,54,17,4,12,'Ale když oznámili Mardocheovi slova Estery,'),
(1558968,54,17,4,13,'Řekl Mardocheus, aby zase oznámeno bylo Esteře: Nemysl sobě, abys zachována býti mohla v domě královském ze všech Židů.'),
(1558969,54,17,4,14,'Nebo jestliže se umlčíš v tento čas, oddechnutí a vysvobození Židům přijde odjinud, ty pak a dům otce tvého zahynete. A kdo ví, ne pro tento-lis čas přišla k tomu království?'),
(1558970,54,17,4,15,'I řekla Ester, aby zase oznámili Mardocheovi:'),
(1558971,54,17,4,16,'Jdi a shromažď všecky Židy, což jest jich v Susan, a posťte se za mne, a nejezte ani píte za tři dni, v noci ani ve dne. Já podobně, i panny mé postiti se budou, a teprv vejdu k králi, což však neobyčejné jest, a jestližeť zahynu, nechť zahynu.'),
(1558972,54,17,4,17,'Tedy šel Mardocheus, a učinil všecko tak, jakž mu poručila Ester.'),
(1558973,54,17,5,1,'Stalo se potom dne třetího, oblékši se Ester v roucho královské, postavila se v síni vnitřní domu královského, naproti pokoji královskému. Král pak seděl na stolici své královské, v pokoji královském naproti dveřím domu.'),
(1558974,54,17,5,2,'Stalo se, pravím, když uzřel král Ester královnu, ana stojí v síni, že milostí jsa k ní nakloněn, vztáhl král k Ester berlu zlatou, kterouž držel v ruce své. Tedy přistoupivši Ester, dotkla se konce berly.'),
(1558975,54,17,5,3,'I řekl jí král: Co jest tobě, královno Ester? A jaká jest prosba tvá? Až do polovice království dáno bude tobě.'),
(1558976,54,17,5,4,'Odpověděla Ester: Jestliže se králi za dobré vidí, nechať přijde král s Amanem dnes na hody, kteréž jsem jemu připravila.'),
(1558977,54,17,5,5,'I řekl král: Zavolejte rychle Amana, ať naplní žádost Estery. A tak přišel král s Amanem na hody, kteréž byla připravila Ester.'),
(1558978,54,17,5,6,'Potom řekl král k Ester, napiv se vína. Jaká jest žádost tvá? A budeť dáno. Aneb jaká jest prosba tvá? Bys pak žádala až do polovice království, staneť se.'),
(1558979,54,17,5,7,'I odpověděla Ester: Žádost má a prosba má jest:'),
(1558980,54,17,5,8,'Nalezla-li jsem milost u krále, a jestliže se králi za dobré vidí povoliti žádosti mé, a naplniti prosbu mou, aby ještě přišel král i Aman na hody, kteréž jim připravím, a zítra učiním podlé slova královského.'),
(1558981,54,17,5,9,'A tak vyšel Aman dne toho, vesel jsa a dobré mysli. Ale když viděl Aman Mardochea v bráně královské, že ani nepovstal, ani se nehnul před ním, naplněn jest Aman hněvem proti Mardocheovi.'),
(1558982,54,17,5,10,'A však zdržel se Aman, až přišel do domu svého, a poslav, povolal přátel svých a Zeres ženy své.'),
(1558983,54,17,5,11,'I vypravoval jim Aman o slávě bohatství svého, i o množství synů svých, i o všem, čímž ho zvelebil král, a jak ho vyvýšil nad knížata i služebníky královské.'),
(1558984,54,17,5,12,'A doložil Aman: Nadto nepozvala Ester královna s králem na hody, kteréž byla připravila jen mne, a ještě i k zejtří pozván jsem od ní s králem.'),
(1558985,54,17,5,13,'Ale všecko to nic mi neprospívá, pokudžkoli vídám Mardochea, toho Žida, sedati u brány královské.'),
(1558986,54,17,5,14,'Řekla jemu Zeres žena jeho, i všickni přátelé jeho: Nechť udělají šibenici zvýši padesáti loket, a ráno rci králi, aby na ní oběsili Mardochea, a vejdi s králem na hody vesele. I líbila se ta rada Amanovi, a rozkázal postaviti šibenici.'),
(1558987,54,17,6,1,'Té noci král nemoha spáti, rozkázal přinésti knihy pamětné, kroniky, kteréž čteny byly před králem.'),
(1558988,54,17,6,2,'I našli zapsáno, že pověděl Mardocheus na Bigtana a Teresa, dva komorníky královské z těch, jenž ostříhali prahu, že ukládali vztáhnouti ruku na krále Asvera.'),
(1558989,54,17,6,3,'Tedy řekl král: Čím jest poctěn, neb jak zveleben Mardocheus za to? Odpověděli služebníci královští, dvořané jeho: Není jemu nic dáno.'),
(1558990,54,17,6,4,'I řekl král: Kdo jest v síni? (Aman pak byl přišel do síně domu královského zevnitřní, mluviti s králem, aby oběšen byl Mardocheus na šibenici, kterouž jemu připravil.)'),
(1558991,54,17,6,5,'Odpověděli králi služebníci jeho: Aj, Aman stojí v síni. Řekl král: Nechť vejde sem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1558992,54,17,6,6,'Takž všel Aman. Jemuž řekl král: Co sluší učiniti muži tomu, kteréhož by chtěl král ctíti? (Aman řekl sám v sobě: Kohož by jiného chtěl král více ctíti, nežli mne?)'),
(1558993,54,17,6,7,'Odpověděl Aman králi: Muži tomu,jehož král ctíti chce,'),
(1558994,54,17,6,8,'Ať přinesou roucho královské, do kteréhož se král obláčí, a přivedou koně, na kterémž jezdí král, a vstaví korunu královskou na hlavu jeho.'),
(1558995,54,17,6,9,'A dadouce roucho to i koně toho v ruku některého z nejznamenitějších knížat královských, ať oblekou muže toho, jehož král chce ctíti, a ať jej vodí na koni po ulici města, a volají před ním: Tak se má státi muži tomu, jehož král ctíti chce.'),
(1558996,54,17,6,10,'Tedy řekl král Amanovi: Pospěš, vezmi to roucho a koně, jakž jsi řekl, a učiň to Mardocheovi Židu, kterýž sedí v bráně královské. Nepomíjejž ničeho ze všeho toho, což jsi mluvil.'),
(1558997,54,17,6,11,'Protož vzav Aman roucho i koně, oblékl Mardochea, a vedl jej na koni po ulici města, volaje před ním: Tak se má státi muži tomu, jehož král ctíti chce.'),
(1558998,54,17,6,12,'Potom navrátil se Mardocheus k bráně královské. Aman pak rychle pospíšil do domu svého, smuten jsa, s zakrytou hlavou.'),
(1558999,54,17,6,13,'I vypravoval Aman Zeres ženě své a všechněm přátelům svým všecko, což se mu přihodilo. I řekli jemu mudrci jeho i Zeres žena jeho: Poněvadž z národu Židovského jest Mardocheus, před jehož oblíčejem počal jsi klesati, neodoláš jemu, ale jistě padneš před oblíčejem jeho.'),
(1559000,54,17,6,14,'A když oni ještě mluvili s ním, komorníci královští přišli, a rychle vzali Amana na hody, kteréž připravila Ester.'),
(1559001,54,17,7,1,'A tak přišel král i Aman, aby hodovali s Ester královnou.'),
(1559002,54,17,7,2,'I řekl král k Ester opět druhého dne, napiv se vína: Jaká jest žádost tvá, Ester královno? A budeť dáno. Aneb jaká jest prosba tvá? Až do polovice království staneť se.'),
(1559003,54,17,7,3,'Tedy odpověděla Ester královna a řekla: Jestliže jsem nalezla milost před očima tvýma, ó králi, a jestliže se králi za dobré vidí, nechť mi jest darován život můj k mé žádosti, a národu mému k prosbě mé.'),
(1559004,54,17,7,4,'Nebo prodáni jsme, já i národ můj, abychom zbiti, pomordováni a vyhlazeni byli, ješto kdybychom za služebníky a děvky prodáni byli, mlčela bych, ač by i tak ten nepřítel nijakž nemohl nahraditi králi té škody.'),
(1559005,54,17,7,5,'Opět odpovídaje král Asverus, řekl Ester královně: I kdož jest to ten, a kde jest ten, jehož srdce tak jest naduté, aby to činil?'),
(1559006,54,17,7,6,'I řekla Ester: Muž protivník a nepřítel nejhorší jest Aman tento. Takž Aman zhrozil se před oblíčejem krále a královny.'),
(1559007,54,17,7,7,'Tedy král vstal v prchlivosti své od pití vína, a vyšel na zahradu při paláci. Aman pak pozůstal tu, aby prosil za život svůj Estery královny; nebo viděl, že jest o něm zle uloženo od krále.'),
(1559008,54,17,7,8,'Potom král navrátil se z zahrady palácu do domu, kdež pil víno, a Aman padl na lůžko, na kterémž seděla Ester. I řekl král: Což ještě násilé učiniti chce královně u mne v domě? A hned jakž slovo to vyšlo z úst krále, tvář Amanovu zakryli.'),
(1559009,54,17,7,9,'Mezi tím řekl Charbona, jeden z komorníků, před králem: Aj, ještě šibenice, kterouž připravil Aman Mardocheovi, kterýž mluvil králi k dobrému, stojí při domě Amanově, zvýší padesáti loket. I řekl král: Oběstež ho na ní.'),
(1559010,54,17,7,10,'Tedy oběsili Amana na té šibenici, kterouž byl připravil Mardocheovi. A tak prchlivost královská ukojila se.'),
(1559011,54,17,8,1,'Téhož dne dal král Asverus Ester královně dům Amana nepřítele Židovského, a Mardocheus přišel před krále, (nebo oznámila Ester, co by jí on byl).'),
(1559012,54,17,8,2,'Kdežto král sňav prsten svůj, kterýž vzal od Amana, dal jej Mardocheovi. Ester pak ustanovila Mardochea nad domem Amanovým.'),
(1559013,54,17,8,3,'Potom ještě Ester mluvila před králem, padši k nohám jeho, a s pláčem pokorně ho prosila, aby zrušil nešlechetnost Amana Agagského a jeho úklady, kteréž smyslil proti Židům.'),
(1559014,54,17,8,4,'(Tedy vztáhl král k Esteře berlu zlatou, a Ester vstavši, postavila se před králem.)'),
(1559015,54,17,8,5,'A řekla: Jestliže se králi za dobré vidí, a nalezla-li jsem milost před tváří jeho, a jestliže se ta věc králi slušná býti vidí, a já jsem-li příjemná před očima jeho: nechť jest psáno, aby byli zrušeni listové ti, a tak úkladové Amana syna Hammedatova Agagského, kteréž rozepsal, aby vyhladili Židy, což jest jich ve všech krajinách královských.'),
(1559016,54,17,8,6,'Nebo jak bych se mohla dívati na to zlé, kteréž by potkalo lid můj? A jak bych mohla hleděti na zhoubu rodiny své?'),
(1559017,54,17,8,7,'I řekl král Asverus Ester královně a Mardocheovi Židu: Ej, dům Amanův dal jsem Esteře, jeho pak oběsili na šibenici, proto že vztáhnouti chtěl ruku svou na Židy.'),
(1559018,54,17,8,8,'Vy tedy pište Židům, jakž se vám za dobré zdá, jménem královským, a zapečeťte prstenem královským. (Nebo což se píše jménem krále, a zapečetí prstenem královským, nemůže zpátkem jíti.)'),
(1559019,54,17,8,9,'Takž svolali písaře královské v ten čas měsíce třetího, jenž jest měsíc Siban, dvadcátého třetího dne téhož měsíce, a psáno jest všecko tak, jakž přikázal Mardocheus, k Židům a knížatům, i vývodám a hejtmanům krajin, kteréž jsou od Indie až do země Mouřenínské, sto dvadceti sedm krajin, do každé krajiny písmem jejím, každému národu jazykem jeho, též i Židům písmem jejich a jazykem jejich.'),
(1559020,54,17,8,10,'A když napsal jménem krále Asvera a zapečetil prstenem královským, rozeslal listy po poslích, kteříž jezdívali na koních rychlých a mezcích mladých:'),
(1559021,54,17,8,11,'Že jest povolil král Židům, kteřížby v kterémkoli městě byli, aby shromáždíce se, zastávali života svého, a aby hubili, mordovali a plénili všecka vojska národu i krajiny, útok činících na ně, na děti jejich i ženy jejich, a kořisti jejich aby rozbitovali.'),
(1559022,54,17,8,12,'Jednoho a téhož dne ve všech krajinách krále Asvera, totiž třináctého, měsíce dvanáctého, jenž jest měsíc Adar.'),
(1559023,54,17,8,13,'Summa toho psání: Aby vyhlášeno bylo v jedné každé krajině, a oznámeno všechněm národům, aby Židé byli hotovi ke dni tomu ku pomstě nad nepřátely svými.'),
(1559024,54,17,8,14,'Tedy poslové, kteříž jezdívali na koních prudkých a na mezcích, vyjeli snažným a rychlým během s poručením královským, a vyhlášeno jest to v Susan, městě královském.'),
(1559025,54,17,8,15,'Mardocheus pak vycházel od oblíčeje královského v rouše královském z postavce modrého a bílého, v koruně zlaté veliké a v plášti kmentovém a šarlatovém, a město Susan plésalo a veselilo se.'),
(1559026,54,17,8,16,'Nebo Židům vzešlo světlo a radost, i veselé a sláva.'),
(1559027,54,17,8,17,'Ano i v každé krajině i v každém městě, na kteréžkoli místo poručení královské a výpověd jeho došla, veselé a radost měli Židé, hody a dobrou vůli, a mnozí z národů jiných přistupovali k Židům; nebo připadl na ně strach Židovský.'),
(1559028,54,17,9,1,'Potom dvanáctého měsíce, (jenž jest měsíc Adar), třináctého dne téhož měsíce, když přišel čas poručení královského a výpovědi jeho, aby se vyplnila, v ten den, v kterýž se nadáli nepřátelé Židovští, že budou panovati nad nimi, stalo se na odpor, že panovali Židé nad těmi, kteříž je v nenávisti měli.'),
(1559029,54,17,9,2,'Nebo se byli shromáždili Židé v městech svých, po všech krajinách krále Asvera, aby vztáhli ruku na ty, kteříž hledali jejich zlého. A žádný před nimi neostál, nebo připadl strach jejich na všecky národy.'),
(1559030,54,17,9,3,'A všickni hejtmané krajin, i knížata a vývodové, i správcové díla královského v poctivosti měli Židy; nebo strach Mardocheův na ně připadl.'),
(1559031,54,17,9,4,'Byl zajisté Mardocheus veliký v domě královském, a rozcházela se pověst o něm po všech krajinách; nebo muž ten Mardocheus vždy více rostl.'),
(1559032,54,17,9,5,'A tak zbili Židé všecky nepřátely své, mečem hubíce, mordujíce a vyhlazujíce je, a nakládajíce s těmi, kteříž je v nenávisti měli, podlé líbosti své.'),
(1559033,54,17,9,6,'Ano i v Susan městě královském zmordovali Židé a vyhladili pět set mužů.'),
(1559034,54,17,9,7,'A Parsandata, Dalfona i Aspata,'),
(1559035,54,17,9,8,'A Porata, Adalia i Aridata,'),
(1559036,54,17,9,9,'I Parimasta, Arisai i Aridai a Vajezata,'),
(1559037,54,17,9,10,'Deset synů Amana syna Hammedatova, nepřítele Židovského, zmordovali. Ale k loupeži nevztáhli ruky své.'),
(1559038,54,17,9,11,'Dne toho, když se donesl krále počet zmordovaných v Susan městě královském,'),
(1559039,54,17,9,12,'Řekl král Esteře královně: V Susan městě královském zmordovali Židé a vyhladili pět set mužů, a deset synů Amanových. Co pak učinili v jiných krajinách královských? Již tedy jaká jest žádost tvá? A dánoť bude. Aneb která prosba tvá ještě? A staneť se.'),
(1559040,54,17,9,13,'Odpověděla Ester: jestliže se králi za dobré vidí, nechť jest dopuštěno ještě zítra Židům, kteříž jsou v Susan, učiniti podlé výpovědi dnešní, a deset synů Amanových zvěšeti na šibenici.'),
(1559041,54,17,9,14,'I přikázal král, aby se tak stalo. Tedy vyhlášena jest výpověd v Susan, a tak deset synů Amanových zvěšeli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559042,54,17,9,15,'A shromáždivše se Židé, kteříž byli v Susan, také i čtrnáctého dne měsíce Adar, zmordovali v Susan tři sta mužů. Ale k loupeži nevztáhli ruky své.'),
(1559043,54,17,9,16,'Jiní také Židé, kteříž byli v krajinách královských, shromáždivše se, a zastávajíce života svého, tak odpočinuli od nepřátel svých. Zmordovali pak těch, jenž je v nenávisti měli, sedmdesáte pět tisíc. Ale k loupeži nevztáhli ruky své.'),
(1559044,54,17,9,17,'Stalo se to dne třináctého měsíce Adar. I odpočinuli čtrnáctého dne téhož měsíce, a učinili sobě v ten den hody a veselé.'),
(1559045,54,17,9,18,'Ale Židé, kteříž byli v Susan, shromáždili se třináctého dne téhož měsíce a též čtrnáctého, a odpočinuli patnáctého, a učinili sobě na ten den hody a veselé.'),
(1559046,54,17,9,19,'Protož Židé, kteříž bydlí ve vsech a v městečkách nehrazených, světí den čtrnáctý měsíce Adar, majíce veselé, hody a dobrou vůli, a posílajíce částky pokrmů jedni druhým.'),
(1559047,54,17,9,20,'Nebo rozepsal Mardocheus ty věci, a rozeslal listy ke všem Židům, kteříž byli ve všech krajinách krále Asvera, blízkým i dalekým,'),
(1559048,54,17,9,21,'Ustavuje jim, aby slavili den čtrnáctý měsíce Adar, a den patnáctý téhož měsíce každého roku,'),
(1559049,54,17,9,22,'Podlé dnů těch, v nichž odpočinuli Židé od nepřátel svých, a měsíce toho, kterýž se jim obrátil z zámutku v radost, a z kvílení v dobrou vůli, aby ty dni slavili, hodujíce a veselíce se, a posílajíce částky pokrmů jeden druhému, i dary chudým.'),
(1559050,54,17,9,23,'I přijali to všickni Židé, že budou činiti to, což začali, a což jim psal Mardocheus:'),
(1559051,54,17,9,24,'Jak Aman syn Hammedatův Agagský, protivník všech Židů, ukládal o Židech, aby je vyhubil a uvrhl pur, totiž los, k setření a zahlazení jejich.'),
(1559052,54,17,9,25,'Ale jak ona vešla před oblíčej krále, poručil král v listech, aby obráceni byli úkladové jeho nešlechetní, kteréž vymyslil proti Židům, na hlavu jeho, a aby ho oběsili i syny jeho na šibenici.'),
(1559053,54,17,9,26,'I nazvali ty dny Purim, totiž losů, od jména toho pur. A tak z příčiny všech slov listu toho, a což viděli při tom, i což přišlo k nim,'),
(1559054,54,17,9,27,'Ustavili a přijali Židé na sebe i na símě své, i na všecky připojené k sobě, aby to nepominulo, že budou slaviti ty dva dni podlé vypsání jejich, a podlé určitého času jejich každého roku.'),
(1559055,54,17,9,28,'A že ti dnové budou pamětní a slavní v každém věku, rodině, krajině a městě; k tomu, že ti dnové Purim nepominou z prostředku Židů, a památka jejich nepřestane u potomků jejich.'),
(1559056,54,17,9,29,'Psala také Ester královna, dcera Abichailova, i Mardocheus Žid pro větší upevnění psání z strany dnů Purim po druhé.'),
(1559057,54,17,9,30,'A on rozeslal to psání ke všem Židům, do sta dvadcíti sedmi krajin království Asverova, vzkazuje jim pozdravení,'),
(1559058,54,17,9,31,'Aby tuze drželi dny ty Purim v určité časy jich, jakž je nařídil jim Mardocheus Žid a Ester královna, a jakž to přijali na sebe a na símě své, na pamět postů a křiku jejich.'),
(1559059,54,17,9,32,'A tak výpověd Estery potvrdila ustanovení dnů Purim, což zapsáno jest v knize této.'),
(1559060,54,17,10,1,'Potom uložil král Asverus daň na zemi i na ostrovy mořské.'),
(1559061,54,17,10,2,'Všickni pak činové síly jeho a moci jeho, i vypsání důstojnosti Mardocheovy, kterouž ho zvelebil král, to vše zapsáno jest v knize o králích Médských a Perských.'),
(1559062,54,17,10,3,'Nebo Mardocheus Žid byl druhý po králi Asverovi, a veliký u Židů, i vzácný u všeho množství bratří svých, pečuje o dobré lidu svého, a způsobuje pokoj všemu semeni svému.'),
(1559063,54,18,1,1,'Byl muž v zemi Uz, jménem Job, a muž ten byl sprostný a upřímý, boje se Boha, a vystříhaje se zlého.'),
(1559064,54,18,1,2,'Kterémuž se narodilo sedm synů a tři dcery.'),
(1559065,54,18,1,3,'A měl dobytka sedm tisíc ovec, tři tisíce velbloudů, pět set spřežení volů, a pět set oslic, a čeledi služebné velmi mnoho, a byl muž ten vznešenější nade všecky lidi východní.'),
(1559066,54,18,1,4,'I scházívali se synové jeho, a strojívali hody po domích, každý ve dni svém. Posílávali také, a zvávali své tři sestry, aby jedly a pily s nimi.'),
(1559067,54,18,1,5,'A když vypořádali dny hodů, posílával Job, a posvěcoval jich, a vstávaje ráno, obětoval zápaly podlé počtu všech jich. Nebo říkával Job: Snad zhřešili synové moji, aneb zlořečili Bohu v srdci svém. Tak činíval Job po všecky ty dny.'),
(1559068,54,18,1,6,'Jednoho pak dne, když přišli synové Boží, aby se postavili před Hospodinem, přišel také i Satan mezi ně.'),
(1559069,54,18,1,7,'Tedy řekl Hospodin Satanovi: Odkud jdeš? I odpověděl Satan Hospodinu, řka: Procházel jsem zemi, a obcházel jsem ji.'),
(1559070,54,18,1,8,'I řekl Hospodin Satanovi: Spatřil-lis služebníka mého Joba, že není jemu rovného na zemi, a že jest muž sprostný a upřímý, bojící se Boha a varující se zlého.'),
(1559071,54,18,1,9,'A odpovídaje Satan Hospodinu, řekl: Zdaliž se Job darmo bojí Boha?'),
(1559072,54,18,1,10,'Zdaž jsi ty ho neohradil i domu jeho a všeho, což má, se všech stran? Dílu rukou jeho požehnal jsi, a dobytek jeho rozmnožil se na zemi.'),
(1559073,54,18,1,11,'Ale vztáhni nyní ruku svou, a dotkni se všeho, což má, nebude-liť zlořečiti v oči.'),
(1559074,54,18,1,12,'Tedy řekl Hospodin Satanovi: Aj, cožkoli má, v moci tvé buď, toliko na něj nevztahuj ruky své. I vyšel Satan od tváři Hospodinovy.'),
(1559075,54,18,1,13,'Jednoho pak dne synové a dcery jeho jedli, a pili víno v domě bratra svého prvorozeného.'),
(1559076,54,18,1,14,'I přišel posel k Jobovi, a řekl: Když volové orali, a oslice se pásly podlé nich,'),
(1559077,54,18,1,15,'Vpád učinivše Sabejští, zajali je, a služebníky zbili ostrostí meče, a utekl jsem toliko já sám, abych oznámil tobě.'),
(1559078,54,18,1,16,'A když on ještě mluvil, přišed druhý, řekl: Oheň Boží spadl s nebe, a rozpáliv se na dobytek i na služebníky, sehltil je, já pak utekl jsem toliko sám, abych oznámil tobě.'),
(1559079,54,18,1,17,'A když ten ještě mluvil, jiný přišed, řekl: Kaldejští sšikovavše tři houfy, připadli na velbloudy, a zajali je, a služebníky zbili ostrostí meče, a utekl jsem toliko já sám, abych oznámil tobě.'),
(1559080,54,18,1,18,'A když ten ještě mluvil, jiný přišel a řekl: Synové tvoji a dcery tvé jedli, a pili víno v domě bratra svého prvorozeného.'),
(1559081,54,18,1,19,'A aj, vítr veliký strhl se z té strany od pouště, a udeřil na čtyři úhly domu, tak že se obořil na děti, i zemřeli, a utekl jsem toliko já sám, abych oznámil tobě.'),
(1559082,54,18,1,20,'Tedy Job vstav, roztrhl roucho své, a oholil hlavu svou, a padna na zem, poklonu učinil.'),
(1559083,54,18,1,21,'A řekl: Nahý jsem vyšel z života matky své, nahý se také zase tam navrátím. Hospodin dal, Hospodin též odjal. Buď požehnáno jméno Hospodinovo.'),
(1559084,54,18,1,22,'V tom ve všem nezhřešil Job, a nepřivlastnil Bohu nic nemoudrého.'),
(1559085,54,18,2,1,'I stalo se opět jednoho dne, že když přišli synové Boží, aby se postavili před Hospodinem, přišel také i Satan mezi ně, aby se postavil před Hospodinem.'),
(1559086,54,18,2,2,'Tedy řekl Hospodin Satanovi: Odkud jdeš? I odpověděl Satan Hospodinu, řka: Procházel jsem zemi, a obcházel jsem ji.'),
(1559087,54,18,2,3,'I řekl Hospodin Satanovi: Spatřil-lis služebníka mého Joba, že není jemu rovného na zemi, že jest muž sprostný a upřímý, bojící se Boha, a varující se zlého, a že po dnes trvá v upřímnosti své, ačkoli jsi ty mne popudil proti němu, abych jej hubil bez příčiny.'),
(1559088,54,18,2,4,'A odpovídaje Satan Hospodinu, řekl: Kůži za kůži, a všecko, což má člověk, dá za sebe samého.'),
(1559089,54,18,2,5,'Ale vztáhni nyní ruku svou, a dotkni se kostí jeho, a masa jeho, nebude-liť v oči zlořečiti tobě.'),
(1559090,54,18,2,6,'Tedy řekl Hospodin Satanovi: Aj, v moci tvé buď, a však zachovej ho při životu.'),
(1559091,54,18,2,7,'Protož vyšed Satan od tváři Hospodinovy, ranil Joba nežitem nejhorším, od zpodku nohy jeho až do vrchu hlavy jeho,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559092,54,18,2,8,'Tak že vzal střepinu, aby se jí drbal, usadiv se v popele.'),
(1559093,54,18,2,9,'I řekla jemu žena jeho: Ještě vždy trváš v své upřímnosti? Zlořeč Bohu a umři.'),
(1559094,54,18,2,10,'Jížto řekl: Mluvíš, jako jedna z bláznivých mluvívá. Dobré-liž jen věci bráti budeme od Boha, zlých pak nebudeme přijímati? V tom ve všem nezhřešil Job rty svými.'),
(1559095,54,18,2,11,'Když pak uslyšeli tři přátelé Jobovi o všem tom zlém, kteréž přišlo na něj, přišli jeden každý z místa svého: Elifaz Temanský, a Bildad Suchský a Zofar Naamatský, na tom zůstavše spolu, aby přijdouce k němu, politovali ho a těšili jej.'),
(1559096,54,18,2,12,'Kteříž pozdvihše očí svých zdaleka, nepoznali ho. Potom pozdvihše hlasu svého, plakali, a roztrhše jeden každý roucho své, házeli prachem nad hlavy své zhůru.'),
(1559097,54,18,2,13,'A seděli s ním na zemi sedm dní a sedm nocí, a žádný k němu nepromluvil slova; nebo viděli, že se velmi rozmohla bolest jeho.'),
(1559098,54,18,3,1,'Potom otevřev Job ústa svá, zlořečil dni svému.'),
(1559099,54,18,3,2,'Nebo mluvě Job, řekl:'),
(1559100,54,18,3,3,'Ó by byl zahynul ten den, v němž jsem se naroditi měl, i noc, v níž bylo řečeno: Počat jest pacholík.'),
(1559101,54,18,3,4,'Ten den ó by byl obrácen v temnost, aby ho byl nevyhledával Bůh shůry, a nebyl osvícen světlem.'),
(1559102,54,18,3,5,'Ó by jej byly zachvátily tmy a stín smrti, a aby jej byla přikvačila mračna, a předěsila horkost denní.'),
(1559103,54,18,3,6,'Ó by noc tu mrákota byla opanovala, aby nebyla připojena ke dnům roku, a v počet měsíců nepřišla.'),
(1559104,54,18,3,7,'Ó by noc ta byla osaměla, a zpěvu aby nebylo v ní.'),
(1559105,54,18,3,8,'Ó by jí byli zlořečili ti, kteříž proklínají den, hotovi jsouce vzbuditi velryba.'),
(1559106,54,18,3,9,'Ó by se byly hvězdy zatměly v soumraku jejím, a očekávajíc světla, aby ho nebyla dočekala, ani spatřila záře jitřní.'),
(1559107,54,18,3,10,'Nebo nezavřela dveří života mého, ani skryla trápení od očí mých.'),
(1559108,54,18,3,11,'Proč jsem neumřel v matce, aneb vyšed z života, proč jsem nezahynul?'),
(1559109,54,18,3,12,'Proč jsem vzat byl na klín, a proč jsem prsí požíval?'),
(1559110,54,18,3,13,'Nebo bych nyní ležel a odpočíval, spal bych a měl bych pokoj,'),
(1559111,54,18,3,14,'S králi a radami země, kteříž sobě vzdělávali místa pustá,'),
(1559112,54,18,3,15,'Aneb s knížaty, kteříž měli zlato, a domy své naplňovali stříbrem.'),
(1559113,54,18,3,16,'Aneb jako nedochůdče nezřetelné proč jsem nebyl, a jako nemluvňátka, kteráž světla neviděla?'),
(1559114,54,18,3,17,'Tamť bezbožní přestávají bouřiti, a tamť odpočívají ti, jenž v práci ustali.'),
(1559115,54,18,3,18,'Také i vězňové pokoj mají, a neslyší více hlasu násilníka.'),
(1559116,54,18,3,19,'Malý i veliký tam jsou rovni sobě, a služebník jest prost pána svého.'),
(1559117,54,18,3,20,'Proč Bůh dává světlo zbědovanému a život těm, kteříž jsou ducha truchlivého?'),
(1559118,54,18,3,21,'Kteříž očekávají smrti, a není jí, ačkoli jí hledají pilněji než skrytých pokladů?'),
(1559119,54,18,3,22,'Kteříž by se veselili s plésáním a radovali, když by nalezli hrob?'),
(1559120,54,18,3,23,'Člověku, jehož cesta skryta jest, a jehož Bůh přistřel?'),
(1559121,54,18,3,24,'Nebo před pokrmem mým vzdychání mé přichází, a rozchází se jako voda řvání mé.'),
(1559122,54,18,3,25,'To zajisté, čehož jsem se lekal, stalo se mi, a čehož jsem se obával, přišlo na mne.'),
(1559123,54,18,3,26,'Neměl jsem pokoje, aniž jsem se ubezpečil, ani odpočíval, až i přišlo pokušení toto.'),
(1559124,54,18,4,1,'Jemuž odpovídaje Elifaz Temanský, řekl:'),
(1559125,54,18,4,2,'Počneme-li mluviti s tebou, neponeseš-liž toho těžce? Ale kdož by se zdržeti mohl, aby neměl mluviti?'),
(1559126,54,18,4,3,'Aj, učívals mnohé, a rukou opuštěných jsi posiloval.'),
(1559127,54,18,4,4,'Padajícího pozdvihovals řečmi svými, a kolena zemdlená jsi zmocňoval.'),
(1559128,54,18,4,5,'Nyní pak, jakž toto přišlo na tebe, těžce to neseš, a jakž tě dotklo, předěšen jsi.'),
(1559129,54,18,4,6,'Nebylo-liž náboženství tvé nadějí tvou, a upřímost cest tvých očekáváním tvým?'),
(1559130,54,18,4,7,'Rozpomeň se, prosím, kdo jest kdy nevinný zahynul? Aneb kde upřímí vyhlazeni jsou?'),
(1559131,54,18,4,8,'Jakož jsem já vídal ty, kteříž orali nepravost, a rozsívali převrácenost, že ji i žali.'),
(1559132,54,18,4,9,'Od dchnutí Božího hynou, a duchem prchlivosti jeho v nic obracíni bývají.'),
(1559133,54,18,4,10,'Řvání lva a hlas lvice a zubové mladých lvíčat setříni bývají.'),
(1559134,54,18,4,11,'Hyne lev, že nemá loupeže, a lvíčata mladá rozptýlena bývají.'),
(1559135,54,18,4,12,'Nebo i tajně doneslo se mne slovo, a pochopilo ucho mé něco maličko toho.'),
(1559136,54,18,4,13,'V přemyšlováních z vidění nočních, když připadá tvrdý sen na lidi,'),
(1559137,54,18,4,14,'Strach připadl na mne a lekání, kteréž předěsilo všecky kosti mé.'),
(1559138,54,18,4,15,'Duch zajisté před tváří mou šel, tak že vlasové vstávali na těle mém.'),
(1559139,54,18,4,16,'Zastavil se, ale neznal jsem tváři jeho; tvárnost jen byla před očima mýma. Mezi tím mlče, slyšel jsem hlas:'),
(1559140,54,18,4,17,'Zdaliž může člověk spravedlivějším býti než Bůh, aneb muž čistším nad toho, kterýž ho učinil?'),
(1559141,54,18,4,18,'Ano mezi služebníky jeho není dokonalosti, a při andělích svých zanechal nedostatku.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559142,54,18,4,19,'Čím více při těch, kteříž bydlejí v domích hliněných, jejichž základ jest na prachu, a setříni bývají snáze než mol.'),
(1559143,54,18,4,20,'Od jitra až do večera stíráni bývají, a kdož toho nerozvažují, na věky zahynou.'),
(1559144,54,18,4,21,'Zdaliž nepomíjí sláva jejich s nimi? Umírají, ale ne v moudrosti.'),
(1559145,54,18,5,1,'Zavolejž tedy, dá-liť kdo odpověd? A k kterému se z svatých obrátíš?'),
(1559146,54,18,5,2,'Pakli k bláznu, zahubí ho rozhněvání, a nesmyslného zabije prchlivost.'),
(1559147,54,18,5,3,'Jáť jsem viděl blázna, an se vkořenil, ale hned jsem zle tušil příbytku jeho, řka:'),
(1559148,54,18,5,4,'Vzdáleniť jsou synové jeho od spasení; nebo potříni budou v bráně, aniž bude, kdo by je vytrhl.'),
(1559149,54,18,5,5,'Obilé jeho zžíře hladovitý, a i z prostřed trní je vychvátí; nadto sehltí násilník statek takových.'),
(1559150,54,18,5,6,'Neboť nepochází z prachu trápení, aniž se z země pučí bída.'),
(1559151,54,18,5,7,'Ale člověk rodí se k bídě, tak jako jiskry z uhlí zhůru létají.'),
(1559152,54,18,5,8,'Jistě žeť bych já hledal Boha silného, a jemu bych předložil při svou,'),
(1559153,54,18,5,9,'Kterýž činí věci veliké, nezpytatelné, divné, a jimž počtu není,'),
(1559154,54,18,5,10,'Kterýž dává déšť na zemi, a spouští vody na pole,'),
(1559155,54,18,5,11,'Kterýž sází opovržené na místě vysokém, a žalostící vyvyšuje spasením,'),
(1559156,54,18,5,12,'Kterýž v nic obrací myšlení chytráků, tak aby nemohli k skutku přivésti ruce jejich ničeho,'),
(1559157,54,18,5,13,'Kterýž lapá moudré v chytrosti jejich; nebo rada převrácených bláznová bývá.'),
(1559158,54,18,5,14,'Ve dne motají se jako ve tmách, a jako v noci šámají o poledni.'),
(1559159,54,18,5,15,'Kterýž zachovává od meče a od úst jejich, a chudého od ruky násilníka.'),
(1559160,54,18,5,16,'Máť zajisté nuzný naději, ale nepravost musí zacpati ústa svá.'),
(1559161,54,18,5,17,'Aj, jak blahoslavený jest člověk, kteréhož tresce Bůh! A protož káráním Všemohoucího nepohrdej.'),
(1559162,54,18,5,18,'Onť zajisté uráží, on i obvazuje; raní, ruka jeho také léčí.'),
(1559163,54,18,5,19,'Z šesti úzkostí vysvobodil by tebe, ano i v sedmi nedotklo by se tebe zlé.'),
(1559164,54,18,5,20,'V hladu vykoupil by tě od smrti, a v boji od moci meče.'),
(1559165,54,18,5,21,'Když utrhá jazyk, byl bys skryt, aniž bys se bál zhouby, když by přišla.'),
(1559166,54,18,5,22,'Zhouba a hlad buď tobě za smích, a nestrachuj se ani líté zvěři zemské.'),
(1559167,54,18,5,23,'Nebo s kamením polním příměří tvé, a zvěř lítá polní pokoj zachová k tobě.'),
(1559168,54,18,5,24,'A shledáš, žeť stánek tvůj bude bezpečný, a navrátíš se zase k příbytku svému, a nezhřešíš.'),
(1559169,54,18,5,25,'Shledáš také, žeť se rozmnoží símě tvé, a potomci tvoji jako bylina zemská.'),
(1559170,54,18,5,26,'Vejdeš v šedinách do hrobu, tak jako odnášíno bývá zralé obilí časem svým.'),
(1559171,54,18,5,27,'Aj, toť jsme vyhledali, a takť jest; poslechniž toho, a schovej sobě to.'),
(1559172,54,18,6,1,'Odpovídaje pak Job, řekl:'),
(1559173,54,18,6,2,'Ó kdyby pilně zváženo bylo hořekování mé, a bída má na váze aby spolu vyzdvižena byla.'),
(1559174,54,18,6,3,'Jistě že by se nad písek mořský těžší ukázala, pročež mi se i slov nedostává.'),
(1559175,54,18,6,4,'Nebo střely Všemohoucího vězí ve mně, jejichž jed vysušil ducha mého, a hrůzy Boží bojují proti mně.'),
(1559176,54,18,6,5,'Zdaliž řve divoký osel nad mladistvou travou? Řve-liž vůl nad picí svou?'),
(1559177,54,18,6,6,'Zdaliž jedí to, což neslaného jest, bez soli? Jest-liž chut v věci slzké?'),
(1559178,54,18,6,7,'Ach, kterýchž se ostýchala dotknouti duše má, ty jsou již bolesti těla mého.'),
(1559179,54,18,6,8,'Ó by se naplnila žádost má, a aby to, čehož očekávám, dal Bůh,'),
(1559180,54,18,6,9,'Totiž, aby se líbilo Bohu setříti mne, vztáhnouti ruku svou, a zahladiti mne.'),
(1559181,54,18,6,10,'Neboť mám ještě, čím bych se potěšoval, (ačkoli hořím bolestí, aniž mne Bůh co lituje), že jsem netajil řečí Nejsvětějšího.'),
(1559182,54,18,6,11,'Nebo jaká jest síla má, abych potrvati mohl? Aneb jaký konec můj, abych prodlel života svého?'),
(1559183,54,18,6,12,'Zdali síla má jest síla kamenná? Zdali tělo mé ocelivé?'),
(1559184,54,18,6,13,'Zdaliž pak obrany mé není při mně? Aneb zdravý soud vzdálen jest ode mne,'),
(1559185,54,18,6,14,'Proti tomu, jehož lítostivost k bližnímu mizí, a kterýž bázeň Všemohoucího opustil?'),
(1559186,54,18,6,15,'Bratří moji zmýlili mne jako potok, pominuli jako prudcí potokové,'),
(1559187,54,18,6,16,'Kteříž kalní bývají od ledu, a v nichž se kryje sníh.'),
(1559188,54,18,6,17,'V čas horka vysychají; když sucho bývá, mizejí z místa svého.'),
(1559189,54,18,6,18,'Sem i tam roztěkají se od toku svého obecného, v nic se obracejí a hynou.'),
(1559190,54,18,6,19,'To vidouce houfové jdoucích z Tema, zástupové Sabejských, jenž naději měli v nich,'),
(1559191,54,18,6,20,'Zastyděli se, že v nich doufali; nebo přišedše až k nim, oklamáni jsou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559192,54,18,6,21,'Tak zajisté i vy byvše, nejste; vidouce potření mé, děsíte se.'),
(1559193,54,18,6,22,'Zdali jsem řekl: Přineste mi, aneb z zboží svého udělte darů pro mne?'),
(1559194,54,18,6,23,'Aneb: Vysvoboďte mne z ruky nepřítele, a z ruky násilníků vykupte mne?'),
(1559195,54,18,6,24,'Poučte mne, a budu mlčeti, a v čem bych bloudil, poslužte mi k srozumění.'),
(1559196,54,18,6,25,'Ó jak jsou pronikavé řeči upřímé! Ale co vzdělá obviňování vaše?'),
(1559197,54,18,6,26,'Zdali jen z slov mne viniti myslíte, a převívati řeči choulostivého?'),
(1559198,54,18,6,27,'Také i na sirotka se obořujete, anobrž jámu kopáte příteli svému.'),
(1559199,54,18,6,28,'A protož nyní chtějtež popatřiti na mne, a suďte, klamám-liť před oblíčejem vaším.'),
(1559200,54,18,6,29,'Napravte se, prosím, nechť není nepravostí; napravte se, pravím, a tak poznáte, žeť jest spravedlnost v té řeči mé.'),
(1559201,54,18,6,30,'A jest-li na jazyku mém nepravost, neměl-liž bych, čitedlen býti bíd?'),
(1559202,54,18,7,1,'Zdaliž nemá vyměřeného času člověk na zemi? A dnové jeho jako dnové nájemníka.'),
(1559203,54,18,7,2,'Jako služebník, kterýž touží po stínu, a jako nájemník, jenž očekává skonání díla svého:'),
(1559204,54,18,7,3,'Tak jsou mi dědičně přivlastněni měsícové marní, a noci plné trápení jsou mi odečteny.'),
(1559205,54,18,7,4,'Jestliže ležím, říkám: Kdy vstanu? A pomine noc? Tak pln bývám myšlení až do svitání.'),
(1559206,54,18,7,5,'Tělo mé odíno jest červy a strupem i prachem, kůže má puká se a rozpouští.'),
(1559207,54,18,7,6,'Dnové moji rychlejší byli nežli člunek tkadlce, nebo stráveni jsou bez prodlení.'),
(1559208,54,18,7,7,'Rozpomeň se, ó Pane, že jako vítr jest život můj, a oko mé že více neuzří dobrých věcí,'),
(1559209,54,18,7,8,'Aniž mne spatří oko, jenž mne vídalo. Oči tvé budou ke mně, a mne již nebude.'),
(1559210,54,18,7,9,'Jakož oblak hyne a mizí, tak ten, kterýž sstupuje do hrobu, nevystoupí zase,'),
(1559211,54,18,7,10,'Aniž se opět navrátí do domu svého, aniž ho již více pozná místo jeho.'),
(1559212,54,18,7,11,'Protož nemohuť já zdržeti úst svých, mluvím v ssoužení ducha svého, naříkám v hořkosti duše své.'),
(1559213,54,18,7,12,'Zdali jsem já mořem čili velrybem, že jsi mne stráží osadil?'),
(1559214,54,18,7,13,'Když myslím: Potěší mne lůže mé, poodejme naříkání mého postel má:'),
(1559215,54,18,7,14,'Tedy mne strašíš sny, a viděními děsíš mne,'),
(1559216,54,18,7,15,'Tak že sobě zvoluje zaškrcení duše má, a smrt nad život.'),
(1559217,54,18,7,16,'Mrzí mne, nebuduť déle živ. Poodstupiž ode mne, nebo marní jsou dnové moji.'),
(1559218,54,18,7,17,'Co jest člověk, že ho sobě tak vážíš, a že tak o něj pečuješ?'),
(1559219,54,18,7,18,'A že ho navštěvuješ každého jitra, a každé chvíle jej zkušuješ?'),
(1559220,54,18,7,19,'Dokudž se neodvrátíš ode mne, a nedáš mi aspoň polknouti mé sliny?'),
(1559221,54,18,7,20,'Zhřešil jsem, což mám učiniti, ó strážce lidský? Proč jsi mne položil za cíl sobě, tak abych sám sobě byl břemenem?'),
(1559222,54,18,7,21,'Nýbrž proč neodejmeš přestoupení mého, a neodpustíš nepravosti mé? Nebo již v zemi lehnu. Potom bys mne i pilně hledal, nebude mne.'),
(1559223,54,18,8,1,'Tedy odpovídaje Bildad Suchský, řekl:'),
(1559224,54,18,8,2,'Dokudž mluviti budeš takové věci, a slova úst tvých budou jako vítr násilný?'),
(1559225,54,18,8,3,'Což by Bůh silný neprávě soudil,a Všemohoucí což by převracel spravedlnost?'),
(1559226,54,18,8,4,'Synové zajisté tvoji že zhřešili proti němu, proto pustil je po nepravosti jejich.'),
(1559227,54,18,8,5,'Kdybys ty opravdově hledal Boha silného, a Všemohoucímu se modlil,'),
(1559228,54,18,8,6,'A byl čistý a upřímý: jistě žeť by se hned probudil k tobě, a napravil by příbytek spravedlnosti tvé.'),
(1559229,54,18,8,7,'A byly by první věci tvé špatné, poslední pak rozmnožily by se náramně.'),
(1559230,54,18,8,8,'Nebo vzeptej se, prosím, věku starého, a nastroj se k zpytování otců jejich.'),
(1559231,54,18,8,9,'(Myť zajisté včerejší jsme, aniž jsme čeho povědomi; k tomu dnové naši jsou jako stín na zemi.)'),
(1559232,54,18,8,10,'Zdaliž tě oni nenaučí, a nepovědí tobě, a z srdce svého nevynesou-liž slov?'),
(1559233,54,18,8,11,'Zdali roste třtí bez bahna? Roste-liž rákosí bez vody?'),
(1559234,54,18,8,12,'Nýbrž ještě za zelena, dříve než vytrháno bývá, ano prvé než jaká jiná tráva, usychá.'),
(1559235,54,18,8,13,'Tak stezky všech zapomínajících se na Boha silného, tak, pravím, naděje pokrytce zahyne.'),
(1559236,54,18,8,14,'Klesne naděje jeho, a doufání jeho jako dům pavouka.'),
(1559237,54,18,8,15,'Spolehne-li na dům svůj, neostojí; chytí-li se ho, nezdrží.'),
(1559238,54,18,8,16,'Vláhu má před sluncem, tak že z zahrady jeho výstřelkové jeho vynikají.'),
(1559239,54,18,8,17,'Při vrchovišti kořenové jeho hustě rostou, i na místech skalnatých rozkládá se.'),
(1559240,54,18,8,18,'A však bývá-li zachvácen z místa svého, až by se ho i odečtlo, řka: Nevidělo jsem tě:'),
(1559241,54,18,8,19,'Tožť ta radost života jeho, a z země jiný vykvetá.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559242,54,18,8,20,'Aj, Bůh silný nepohrdá upřímým, ale nešlechetným ruky nepodává:'),
(1559243,54,18,8,21,'Až i naplní smíchem ústa tvá, a rty tvé plésáním,'),
(1559244,54,18,8,22,'Když nenávidící tebe v hanbu oblečeni budou, a stánku lidí bezbožných nikdež nebude.'),
(1559245,54,18,9,1,'Odpověděv pak Job, řekl:'),
(1559246,54,18,9,2,'I ovšem vím, žeť tak jest; nebo jak by mohl člověk spravedliv býti před Bohem silným?'),
(1559247,54,18,9,3,'A chtěl-li by se hádati s ním, nemohl by jemu odpovědíti ani na jedno z tisíce slov.'),
(1559248,54,18,9,4,'Moudrého jest srdce a silný v moci. Kdo zatvrdiv se proti němu, pokoje užil?'),
(1559249,54,18,9,5,'On přenáší hory, než kdo shlédne, a podvrací je v prchlivosti své.'),
(1559250,54,18,9,6,'On pohybuje zemí z místa jejího, tak že se třesou sloupové její.'),
(1559251,54,18,9,7,'On když zapovídá slunci, nevychází, a hvězdy zapečeťuje.'),
(1559252,54,18,9,8,'On roztahuje nebe sám, a šlapá po vlnách mořských.'),
(1559253,54,18,9,9,'On učinil Arktura, Oriona, Kuřátka a hvězdy skryté na poledne.'),
(1559254,54,18,9,10,'On činí věci veliké, a to nevystižitelné a divné, jimž není počtu.'),
(1559255,54,18,9,11,'Ano jde-li mimo mne, tedy nevidím; ovšem když pomíjí, neznamenám ho.'),
(1559256,54,18,9,12,'Tolikéž jestliže co uchvátí, kdo mu to rozkáže navrátiti? Kdo dí jemu: Co činíš?'),
(1559257,54,18,9,13,'Nezdržel-li by Bůh hněvu svého, klesli by před ním spolu spuntovaní, jakkoli mocní.'),
(1559258,54,18,9,14,'Jakž bych já tedy jemu odpovídati, a jaká slova svá proti němu vyhledati mohl?'),
(1559259,54,18,9,15,'Kterémuž, bych i spravedliv byl, nebudu odpovídati, ale před soudcím svým pokořiti se budu.'),
(1559260,54,18,9,16,'Ač bych pak i volal, a on mi se ozval, neuvěřím, aby vyslyšel hlas můj,'),
(1559261,54,18,9,17,'Poněvadž vichřicí setřel mne, rozmnožil rány mé bez příčiny.'),
(1559262,54,18,9,18,'Aniž mi dá oddechnouti, ale sytí mne hořkostmi.'),
(1559263,54,18,9,19,'Obrátil-li bych se k moci, aj, onť jest nejsilnější; pakli k soudu, kdo mi rok složí?'),
(1559264,54,18,9,20,'Jestliže se za spravedlivého stavěti budu, ústa má potupí mne; pakli za upřímého, převráceného mne býti ukáží.'),
(1559265,54,18,9,21,'Jsem-li upřímý, nebudu věděti toho; nenáviděti budu života svého.'),
(1559266,54,18,9,22,'Jediná jest věc, pročež jsem to mluvil, že upřímého jako bezbožného on zahlazuje.'),
(1559267,54,18,9,23,'Jestliže bičem náhle usmrcuje, zkušování nevinných se posmívá;'),
(1559268,54,18,9,24,'Země dána bývá v ruku bezbožného, tvář soudců jejich zakrývá: jestliže ne on, kdož jiný jest?'),
(1559269,54,18,9,25,'Dnové pak moji rychlejší byli nežli posel; utekli, aniž viděli dobrých věcí.'),
(1559270,54,18,9,26,'Pominuli jako prudké lodí, jako orlice letící na pastvu.'),
(1559271,54,18,9,27,'Dím-li: Zapomenu se na své naříkání, zanechám horlení svého, a posilím se:'),
(1559272,54,18,9,28,'Lekám se všech bolestí svých, vida, že mne jich nezprostíš.'),
(1559273,54,18,9,29,'Jestli jsem bezbožný, pročež bych nadarmo pracoval?'),
(1559274,54,18,9,30,'Ano bych se i umyl vodou sněžnou, a očistil mýdlem ruce své,'),
(1559275,54,18,9,31,'Tedy v jámě pohřížíš mne, tak že se ode mne zprzní i to roucho mé.'),
(1559276,54,18,9,32,'Nebo Bůh není člověkem jako já, jemuž bych odpovídati mohl, a abychom vešli spolu v soud.'),
(1559277,54,18,9,33,'Aniž máme prostředníka mezi sebou, kterýž by rozhodl nás oba.'),
(1559278,54,18,9,34,'Kdyby odjal ode mne prut svůj, a strach jeho aby mne nekormoutil,'),
(1559279,54,18,9,35,'Tehdáž bych mluvil, a nebál bych se, poněvadž není toho tak při mně.'),
(1559280,54,18,10,1,'Stýště se duši mé v životě mém, vypustím nad sebou naříkání své, mluviti budu v hořkosti duše své.'),
(1559281,54,18,10,2,'Dím Bohu: Neodsuzuj mne, oznam mi, proč se nesnadníš se mnou?'),
(1559282,54,18,10,3,'Jaký máš na tom užitek, že mne ssužuješ, že pohrdáš dílem rukou svých, a radu bezbožných osvěcuješ?'),
(1559283,54,18,10,4,'Zdali oči tělesné máš? Zdali tak, jako hledí člověk, ty hledíš?'),
(1559284,54,18,10,5,'Zdaž jsou jako dnové člověka dnové tvoji, a léta tvá podobná dnům lidským,'),
(1559285,54,18,10,6,'Že vyhledáváš nepravosti mé, a na hřích můj se vyptáváš?'),
(1559286,54,18,10,7,'Ty víš, žeť nejsem bezbožný, ačkoli není žádného, kdo by mne vytrhl z ruky tvé.'),
(1559287,54,18,10,8,'Ruce tvé sformovaly mne, a učinily mne, a teď pojednou všudy vůkol hubíš mne.'),
(1559288,54,18,10,9,'Pamětliv buď, prosím, že jsi mne jako hlinu učinil, a že v prach zase obrátíš mne.'),
(1559289,54,18,10,10,'Zdalis mne jako mléka neslil, a jako syření neshustil?'),
(1559290,54,18,10,11,'Kůží a masem přioděl jsi mne, a kostmi i žilami spojils mne.'),
(1559291,54,18,10,12,'Života z milosrdenství udělil jsi mi, přesto navštěvování tvé ostříhalo dýchání mého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559292,54,18,10,13,'Ale toto skryl jsi v srdci svém; vím, žeť jest to při tobě.'),
(1559293,54,18,10,14,'Jakž zhřeším, hned mne šetříš, a od nepravosti mé neočišťuješ mne.'),
(1559294,54,18,10,15,'Jestliže jsem bezbožný, běda mně; pakliť jsem spravedlivý, ani tak nepozdvihnu hlavy, nasycen jsa hanbou, a vida trápení své,'),
(1559295,54,18,10,16,'Kteréhož vždy více přibývá. Honíš mne jako lev, a jedno po druhém divně se mnou zacházíš.'),
(1559296,54,18,10,17,'Obnovuješ svědky své proti mně, a rozmnožuješ rozhněvání své na mne; vojska jedna po druhých jsou proti mně.'),
(1559297,54,18,10,18,'Proč jsi jen z života vyvedl mne? Ó bych byl zahynul, aby mne bylo ani oko nevidělo,'),
(1559298,54,18,10,19,'A abych byl, jako by mne nikdy nebylo, z života do hrobu abych byl vnesen.'),
(1559299,54,18,10,20,'Zdaliž jest mnoho dnů mých? Ponechejž tedy a popusť mne, abych maličko pookřál,'),
(1559300,54,18,10,21,'Prvé než odejdu tam, odkudž se zase nenavrátím, do krajiny tmavé, anobrž stínu smrti,'),
(1559301,54,18,10,22,'Do krajiny, pravím, tmavé, kdež jest sama mrákota stínu smrti, a kdež není žádných proměn, ale sama pouhá mrákota.'),
(1559302,54,18,11,1,'A odpovídaje Zofar Naamatský, řekl:'),
(1559303,54,18,11,2,'Zdaliž k mnohým slovům nemá odpovědíno býti? Aneb zdali člověk mnohomluvný práv zůstane?'),
(1559304,54,18,11,3,'Žváním svým lidi zaměstknáváš, a posmíváš se, aniž jest, kdo by tě zahanbil.'),
(1559305,54,18,11,4,'Nebo jsi řekl: Čisté jest učení mé, a čist jsem, ó Bože, před očima tvýma.'),
(1559306,54,18,11,5,'Ješto, ó kdyby Bůh mluvil, a otevřel rty své proti tobě,'),
(1559307,54,18,11,6,'Aťby oznámil tajemství moudrosti, že dvakrát většího trestání zasloužil jsi. A věz, že se Bůh zapomněl na tebe pro nepravost tvou.'),
(1559308,54,18,11,7,'Zdaliž ty stižitelnosti Boží dosáhneš, aneb dokonalost Všemohoucího vystihneš?'),
(1559309,54,18,11,8,'Vyšší jest nebes, což učiníš? Hlubší než peklo, jakž porozumíš?'),
(1559310,54,18,11,9,'Delší jest míra její než země, a širší než moře.'),
(1559311,54,18,11,10,'Bude-li pléniti neb zavírati aneb ssužovati, kdo se na něj bude domlouvati?'),
(1559312,54,18,11,11,'Poněvadž zná lidskou marnost, a vidí nepravost, což by tomu rozuměti neměl?'),
(1559313,54,18,11,12,'Tak aby muž nesmyslný nabyl rozumu, ačkoli člověk jest jako hřebec z divokého osla zplozený.'),
(1559314,54,18,11,13,'Jestliže ty nastrojíš srdce své, a ruce své k němu vztáhneš;'),
(1559315,54,18,11,14,'Byla-li by nepravost v ruce tvé, vzdal ji od sebe, aniž dopouštěj bydliti v staních svých nešlechetnosti:'),
(1559316,54,18,11,15,'Tedy jistě pozdvihneš tváři své z poškvrny, a budeš nepohnutý, aniž se báti budeš.'),
(1559317,54,18,11,16,'Nebo se na těžkost zapomeneš, na niž jako na vody, kteréž pominuly, zpomínati budeš.'),
(1559318,54,18,11,17,'K tomu nad poledne jasný nastaneť čas; zatmíš-li se pak, jitru podobný budeš.'),
(1559319,54,18,11,18,'Budeš i mysli doufanlivé, maje naději; stánek roztáhneš, i bezpečně spáti budeš.'),
(1559320,54,18,11,19,'A tak v pokoji budeš, aniž tě kdo předěsí, a mnozí tváři tvé kořiti se budou.'),
(1559321,54,18,11,20,'Oči pak bezbožných zkaženy budou, a utíkání jim zhyne; nadto naděje jejich bude jako dchnutí člověka.'),
(1559322,54,18,12,1,'Odpověděv pak Job, řekl:'),
(1559323,54,18,12,2,'V pravdě, že jste vy lidé, a že s vámi umře moudrost.'),
(1559324,54,18,12,3,'I jáť mám srdce jako vy, aniž jsem zpozdilejší než vy, anobrž při komž toho není?'),
(1559325,54,18,12,4,'Za posměch příteli svému jsem, kteréhož, když volá, vyslýchá Bůh; v posměchuť jest spravedlivý a upřímý.'),
(1559326,54,18,12,5,'Pochodně zavržená jest (podlé smýšlení člověka pokoje užívajícího) ten, kterýž jest blízký pádu.'),
(1559327,54,18,12,6,'Pokojné a bezpečné příbytky mají loupežníci ti, kteříž popouzejí Boha silného, jimž on uvodí dobré věci v ruku jejich.'),
(1559328,54,18,12,7,'Ano zeptej se třebas hovad, a naučí tě, aneb ptactva nebeského, a oznámí tobě.'),
(1559329,54,18,12,8,'Aneb rozmluv s zemí, a poučí tě, ano i ryby mořské vypravovati budou tobě.'),
(1559330,54,18,12,9,'Kdo nezná ze všeho toho, že ruka Hospodinova to učinila?'),
(1559331,54,18,12,10,'V jehož ruce jest duše všelikého živočicha, a duch každého těla lidského.'),
(1559332,54,18,12,11,'Zdaliž ucho slov rozeznávati nebude, tak jako dásně pokrmu okoušejí?'),
(1559333,54,18,12,12,'Při starcích jest moudrost, a při dlouhověkých rozumnost.'),
(1559334,54,18,12,13,'Nadto pak u Boha moudrost a síla, jehoť jest rada a rozumnost.'),
(1559335,54,18,12,14,'Jestliže on boří, nemůže zase stavíno býti; zavírá-li člověka, nemůže býti otevříno.'),
(1559336,54,18,12,15,'Hle, tak zastavuje vody, až i vysychají, a tak je vypouští, že podvracejí zemi.'),
(1559337,54,18,12,16,'U něho jest síla a bytnost, jeho jest ten, kterýž bloudí, i kterýž v blud uvodí.'),
(1559338,54,18,12,17,'On uvodí rádce v nemoudrost, a z soudců blázny činí.'),
(1559339,54,18,12,18,'Svazek králů rozvazuje, a pasem přepasuje bedra jejich.'),
(1559340,54,18,12,19,'On uvodí knížata v nemoudrost, a mocné vyvrací.'),
(1559341,54,18,12,20,'On odjímá řeč výmluvným, a soud starcům béře.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559342,54,18,12,21,'On vylévá potupu na urozené, a sílu mocných zemdlívá.'),
(1559343,54,18,12,22,'On zjevuje hluboké věci z temností, a vyvodí na světlo stín smrti.'),
(1559344,54,18,12,23,'On rozmnožuje národy i hubí je, rozšiřuje národy i zavodí je.'),
(1559345,54,18,12,24,'On odjímá srdce předním z lidu země, a v blud je uvodí na poušti bezcestné,'),
(1559346,54,18,12,25,'Aby šámali ve tmě bez světla. Summou, činí, aby bloudili jako opilý.'),
(1559347,54,18,13,1,'Aj, všecko to vidělo oko mé, slyšelo ucho mé, a srozumělo tomu.'),
(1559348,54,18,13,2,'Jakož vy znáte to, znám i já, nejsem zpozdilejší než vy.'),
(1559349,54,18,13,3,'Jistě žeť já s Všemohoucím mluviti, a s Bohem silným o svou při jednati budu.'),
(1559350,54,18,13,4,'Nebo vy jste skladatelé lži, a lékaři marní všickni vy.'),
(1559351,54,18,13,5,'Ó kdybyste aspoň mlčeli, a bylo by vám to za moudrost.'),
(1559352,54,18,13,6,'Slyštež medle odpory mé, a důvodů rtů mých pozorujte.'),
(1559353,54,18,13,7,'Zdali zastávajíce Boha silného, mluviti máte nepravost? Aneb za něho mluviti máte lest?'),
(1559354,54,18,13,8,'Zdaliž osobu jeho přijímati budete, a o Boha silného se zasazovati?'),
(1559355,54,18,13,9,'Zdaž vám to k dobrému bude, když na průbu vezme vás, že jakož člověk oklamán bývá, oklamati jej chcete?'),
(1559356,54,18,13,10,'V pravdě žeť vám přísně domlouvati bude, budete-li povrchně osoby jeho šetřiti.'),
(1559357,54,18,13,11,'Což ani důstojnost jeho vás nepředěšuje, ani strach jeho nepřikvačuje vás?'),
(1559358,54,18,13,12,'Všecka vzácnost vaše podobná jest popelu, a hromadám bláta vyvýšení vaše.'),
(1559359,54,18,13,13,'Postrptež mne, nechať já mluvím, přiď na mne cokoli.'),
(1559360,54,18,13,14,'Pročež bych trhati měl maso své zuby svými, a duši svou klásti v ruku svou?'),
(1559361,54,18,13,15,'By mne i zabil, což bych v něho nedoufal? A však cesty své před oblíčej jeho předložím.'),
(1559362,54,18,13,16,'Onť sám jest spasení mé; nebo před oblíčej jeho pokrytec nepřijde.'),
(1559363,54,18,13,17,'Poslouchejte pilně řeči mé, a zprávu mou pusťte v uši své.'),
(1559364,54,18,13,18,'Aj, jižť začínám pře své vésti, vím, že zůstanu spravedliv.'),
(1559365,54,18,13,19,'Kdo jest, ješto by mi odpíral, tak abych nyní umlknouti a umříti musil?'),
(1559366,54,18,13,20,'Toliko té dvoji věci, ó Bože, nečiň mi, a tehdy před tváří tvou nebudu se skrývati:'),
(1559367,54,18,13,21,'Ruku svou vzdal ode mne, a hrůza tvá nechť mne neděsí.'),
(1559368,54,18,13,22,'Zatím povolej mne, a buduť odpovídati; aneb nechať já mluvím, a odpovídej mi.'),
(1559369,54,18,13,23,'Jak mnoho jest mých nepravostí a hříchů? Přestoupení mé a hřích můj ukaž mi.'),
(1559370,54,18,13,24,'Proč tvář svou skrýváš, a pokládáš mne sobě za nepřítele?'),
(1559371,54,18,13,25,'Zdaliž list větrem se zmítající potříti chceš, a stéblo suché stihati budeš?'),
(1559372,54,18,13,26,'Že zapisuješ proti mně hořkosti, a dáváš mi v dědictví nepravosti mladosti mé,'),
(1559373,54,18,13,27,'A dáváš do klady nohy mé, a šetříš všech stezek mých, na paty noh mých našlapuješ;'),
(1559374,54,18,13,28,'Ješto člověk jako hnis kazí se, a jako roucho, kteréž jí mol.'),
(1559375,54,18,14,1,'Člověk narozený z ženy jest krátkého věku a plný lopotování.'),
(1559376,54,18,14,2,'Jako květ vychází a podťat bývá, a utíká jako stín, a netrvá.'),
(1559377,54,18,14,3,'A však i na takového otvíráš oko své, a mne uvodíš k soudu s sebou.'),
(1559378,54,18,14,4,'Kdo toho dokáže, aby čistý z nečistého pošel? Ani jeden.'),
(1559379,54,18,14,5,'Poněvadž vyměřeni jsou dnové jeho, počet měsíců jeho u tebe, a cíles jemu položil, kterýchž by nepřekračoval:'),
(1559380,54,18,14,6,'Odvrať se od něho, ať oddechne sobě, a zatím aby přečekal jako nájemník den svůj.'),
(1559381,54,18,14,7,'O stromu zajisté jest naděje, by i podťat byl, že se zase zotaví, a výstřelek jeho nevyhyne,'),
(1559382,54,18,14,8,'By se pak i sstaral v zemi kořen jeho, a v prachu již jako umřel peň jeho:'),
(1559383,54,18,14,9,'Avšak jakž počije vláhy, zase se pučí, a zahustí jako keř.'),
(1559384,54,18,14,10,'Ale člověk umírá, mdlobou přemožen jsa, a když vypustí duši člověk, kam se poděl?'),
(1559385,54,18,14,11,'Jakož ucházejí vody z jezera, a řeka opadá a vysychá:'),
(1559386,54,18,14,12,'Tak člověk, když lehne, nevstává zase dotud, dokudž nebes stává. Nebývajíť vzbuzeni lidé, aniž se probuzují ze sna svého.'),
(1559387,54,18,14,13,'Ó kdybys mne v hrobě schoval, a skryl mne, dokudž by nebyl odvrácen hněv tvůj, ulože mi cíl, abys se rozpomenul na mne.'),
(1559388,54,18,14,14,'Když umře člověk, zdaliž zase ožive? Po všecky tedy dny vyměřeného času svého očekávati budu, až přijde proměna při mně.'),
(1559389,54,18,14,15,'Zavoláš, a já se ohlásím tobě, díla rukou svých budeš žádostiv,'),
(1559390,54,18,14,16,'Ačkoli nyní kroky mé počítáš, aniž shovíváš hříchům mým,'),
(1559391,54,18,14,17,'Ale zapečetěné maje jako v pytlíku přestoupení mé, ještě přikládáš k nepravosti mé.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559392,54,18,14,18,'Jistě že jako hora padnuc, rozdrobuje se, a skála odsedá z místa svého,'),
(1559393,54,18,14,19,'Jako kamení stírá voda, a povodní zachvacuje, což z prachu zemského samo od sebe roste: tak i ty naději člověka v nic obracíš.'),
(1559394,54,18,14,20,'Přemáháš jej ustavičně, tak aby odjíti musil; proměňuješ tvář jeho, a propouštíš jej.'),
(1559395,54,18,14,21,'Budou-li slavní synové jeho, nic neví; pakli v potupě, nic o ně nepečuje.'),
(1559396,54,18,14,22,'Toliko tělo jeho, dokudž živ jest, bolestí okouší, a duše jeho v něm kvílí.'),
(1559397,54,18,15,1,'Tedy odpovídaje Elifaz Temanský, řekl:'),
(1559398,54,18,15,2,'Zdali moudrý vynášeti má umění povětrné, aneb naplňovati východním větrem břicho své,'),
(1559399,54,18,15,3,'Hádaje se slovy neprospěšnými, aneb řečmi neužitečnými?'),
(1559400,54,18,15,4,'Anobrž vyprazdňuješ i bázeň Boží, a modliteb k Bohu činiti se zbraňuješ.'),
(1559401,54,18,15,5,'Osvědčujíť zajisté nepravost tvou ústa tvá, ač jsi koli sobě zvolil jazyk chytrých.'),
(1559402,54,18,15,6,'Potupují tě ústa tvá, a ne já, a rtové tvoji svědčí proti tobě.'),
(1559403,54,18,15,7,'Zdaliž ty nejprv z lidí zplozen jsi, aneb prvé než pahrbkové sformován?'),
(1559404,54,18,15,8,'Zdaliž jsi tajemství Boží slyšel, že u sebe zavíráš moudrost?'),
(1559405,54,18,15,9,'Co víš, čehož bychom nevěděli? Čemu rozumíš, aby toho při nás nebylo?'),
(1559406,54,18,15,10,'I šedivýť i stařec mezi námi jest, ano i starší věkem než otec tvůj.'),
(1559407,54,18,15,11,'Zdali malá jsou tobě potěšování Boha silného, čili něco je zastěňuje tobě?'),
(1559408,54,18,15,12,'Tak-liž tě jalo srdce tvé, a tak-liž blíkají oči tvé,'),
(1559409,54,18,15,13,'Že smíš odpovídati Bohu silnému tak pyšně, a vypouštěti z úst svých ty řeči?'),
(1559410,54,18,15,14,'Nebo což jest člověk, aby se mohl očistiti, aneb spravedliv býti narozený z ženy?'),
(1559411,54,18,15,15,'An při svatých jeho není dokonalosti, a nebesa nejsou čistá před očima jeho,'),
(1559412,54,18,15,16,'Nadto ohavný a neužitečný člověk, kterýž pije nepravost jako vodu.'),
(1559413,54,18,15,17,'Já oznámím tobě, poslyš mne; to zajisté, což jsem viděl, vypravovati budu,'),
(1559414,54,18,15,18,'Což moudří vynesli a nezatajili, slýchavše od předků svých.'),
(1559415,54,18,15,19,'Jimž samým dána byla země, aniž přejíti mohl cizí prostředkem jejich.'),
(1559416,54,18,15,20,'Po všecky své dny bezbožný sám se bolestí trápí, po všecka, pravím léta, skrytá před ukrutníkem.'),
(1559417,54,18,15,21,'Zvuk strachu jest v uších jeho, že i v čas pokoje zhoubce připadne na něj.'),
(1559418,54,18,15,22,'Nevěří, by se měl navrátiti z temností, ustavičně očekávaje na sebe meče.'),
(1559419,54,18,15,23,'Bývá i tulákem, chleba hledaje, kde by byl, cítě, že pro něj nastrojen jest den temností.'),
(1559420,54,18,15,24,'Děsí jej nátisk a ssoužení, kteréž se silí proti němu, jako král s vojskem sšikovaným.'),
(1559421,54,18,15,25,'Nebo vztáhl proti Bohu silnému ruku svou, a proti Všemohoucímu postavil se.'),
(1559422,54,18,15,26,'Útok učinil na něj, na šíji jeho s množstvím zdvižených štítů svých.'),
(1559423,54,18,15,27,'Nebo přiodíl tvář svou tukem svým, tak že se mu nadělalo faldů na slabinách.'),
(1559424,54,18,15,28,'A bydlil v městech zkažených, a v domích, v nichž žádný nebydlil, kteráž v hromady rumu obrácena byla.'),
(1559425,54,18,15,29,'Avšak nezbohatneť, aniž stane moc jeho, aniž se rozšíří na zemi dokonalost takových.'),
(1559426,54,18,15,30,'Nevyjde z temností, mladistvou ratolest jeho usuší plamen, a tak zahyne od ducha úst svých.'),
(1559427,54,18,15,31,'Ale nevěří, že v marnosti jest ten, jenž bloudí, a že marnost bude směna jeho.'),
(1559428,54,18,15,32,'Před časem svým vyťat bude, a ratolest jeho nebude se zelenati.'),
(1559429,54,18,15,33,'Zmaří, jako vinný kmen nezralý hrozen svůj, a svrže květ svůj jako oliva.'),
(1559430,54,18,15,34,'Nebo shromáždění pokrytce spustne, a oheň spálí stany oslepených dary.'),
(1559431,54,18,15,35,'Kteřížto když počali ssužování, a porodili nepravost, hned břicho jejich strojí jinou lest.'),
(1559432,54,18,16,1,'A odpovídaje Job, řekl:'),
(1559433,54,18,16,2,'Slyšel jsem již podobných věcí mnoho; všickni vy nepříjemní jste těšitelé.'),
(1559434,54,18,16,3,'Bude-liž kdy konec slovům povětrným? Aneb co tě popouzí, že tak mluvíš?'),
(1559435,54,18,16,4,'Zdaliž bych já tak mluviti mohl, jako vy, kdybyste byli na místě mém? Shromažďoval-li bych proti vám slova, aneb potřásal na vás hlavou svou?'),
(1559436,54,18,16,5,'Nýbrž posiloval bych vás ústy svými, a otvírání rtů mých krotilo by bolest.'),
(1559437,54,18,16,6,'Buď že mluvím, neumenšuje se bolesti mé, buď že tak nechám, neodchází ode mne.'),
(1559438,54,18,16,7,'Ale ustavičně zemdlívá mne; nebo jsi mne, ó Bože, zbavil všeho shromáždění mého.'),
(1559439,54,18,16,8,'A vrásky jsi mi zdělal; což mám za svědka, ano patrná na mně hubenost má na tváři mé to osvědčuje.'),
(1559440,54,18,16,9,'Prchlivost jeho zachvátila mne, a vzal mne v nenávist, škřipě na mne zuby svými; jako nepřítel můj zaostřil oči své na mne.'),
(1559441,54,18,16,10,'Rozedřeli na mne ústa svá, potupně mne poličkujíce, proti mně se shromáždivše.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559442,54,18,16,11,'Vydal mne Bůh silný nešlechetníku, a v ruce bezbožných uvedl mne.'),
(1559443,54,18,16,12,'Pokoje jsem užíval, však potřel mne, a uchopiv mne za šíji mou, roztříštil mne, a vystavil mne sobě za cíl.'),
(1559444,54,18,16,13,'Obklíčili mne střelci jeho, rozťal ledví má beze vší lítosti, a vylil na zem žluč mou.'),
(1559445,54,18,16,14,'Ranil mne ranou na ránu, outok učinil na mne jako silný.'),
(1559446,54,18,16,15,'Žíni jsem ušil na zjízvenou kůži svou, a zohavil jsem v prachu sílu svou.'),
(1559447,54,18,16,16,'Tvář má oduřavěla od pláče, a na víčkách mých stín smrti jest.'),
(1559448,54,18,16,17,'Ne pro nějaké bezpraví v rukou mých; nebo i modlitba má čistá jest.'),
(1559449,54,18,16,18,'Ó země, nepřikrývej krve mé, a nechť nemá místa volání mé.'),
(1559450,54,18,16,19,'Aj, nyní jestiť i v nebesích svědek můj, svědek můj, pravím, jest na výsostech.'),
(1559451,54,18,16,20,'Ó mudráci moji, přátelé moji, k Bohuť slzí oko mé.'),
(1559452,54,18,16,21,'Ó by lze bylo muži v hádku s ním se vydati, jako synu člověka s přítelem svým.'),
(1559453,54,18,16,22,'Nebo léta mně odečtená přicházejí, a cestou, kterouž se zase nenavrátím, již se beru.'),
(1559454,54,18,17,1,'Dýchání mé ruší se, dnové moji hynou, hrobu blízký jsem.'),
(1559455,54,18,17,2,'Jistě posměvači jsou u mne, a pro jejich mne kormoucení nepřichází ani sen na oči mé.'),
(1559456,54,18,17,3,'Postav mi, prosím, rukojmě za sebe; kdo jest ten, nechť mi na to ruky podá.'),
(1559457,54,18,17,4,'Nebo srdce jejich přikryl jsi, aby nerozuměli, a protož jich nepovýšíš.'),
(1559458,54,18,17,5,'Kdož pochlebuje bližním, oči synů jeho zhynou.'),
(1559459,54,18,17,6,'Jistě vystavil mne za přísloví lidem, a za divadlo všechněm,'),
(1559460,54,18,17,7,'Tak že pro žalost pošly oči mé, a oudové moji všickni stínu jsou podobni.'),
(1559461,54,18,17,8,'Užasnouť se nad tím upřímí, a však nevinný proti pokrytci vždy se zsilovati bude.'),
(1559462,54,18,17,9,'Přídržeti se bude, pravím, spravedlivý cesty své, a ten, jenž jest čistých rukou, posilní se více.'),
(1559463,54,18,17,10,'Tolikéž i vy všickni obraťte se, a poďte, prosím; neboť nenacházím mezi vámi moudrého.'),
(1559464,54,18,17,11,'Dnové moji pomíjejí, myšlení má mizejí, přemyšlování, pravím, srdce mého.'),
(1559465,54,18,17,12,'Noc mi obracejí v den, a světla denního ukracují pro přítomnost temností.'),
(1559466,54,18,17,13,'Abych pak čeho i očekával, hrob bude dům můj, ve tmě usteli ložce své.'),
(1559467,54,18,17,14,'Jámu nazovu otcem svým, matkou pak a sestrou svou červy.'),
(1559468,54,18,17,15,'Kdež jest tedy očekávání mé? A kdo to, čím bych se troštoval, spatří?'),
(1559469,54,18,17,16,'Do skrýší hrobu sstoupí, poněvadž jest všechněm v prachu země odpočívati.'),
(1559470,54,18,18,1,'Odpovídaje pak Bildad Suchský, řekl:'),
(1559471,54,18,18,2,'Dokudž neučiníte konce řečem? Pomyslte na to, a potom mluviti budeme.'),
(1559472,54,18,18,3,'Proč jsme počteni za hovada? Oškliví jsme jemu, jakž sami vidíte.'),
(1559473,54,18,18,4,'Ó ty, jenž hubíš život svůj zůřením svým, zdaliž pro tebe opuštěna bude země, a odsedne skála z místa svého?'),
(1559474,54,18,18,5,'Anobrž světlo bezbožných uhašeno bude, aniž se blyštěti bude jiskra ohně jejich.'),
(1559475,54,18,18,6,'Světlo se zatmí v stánku jeho, a lucerna jeho v něm zhasne.'),
(1559476,54,18,18,7,'Ssouženi budou krokové síly jeho, a porazí jej rada jeho.'),
(1559477,54,18,18,8,'Nebo zapleten jest do síti nohami svými, a v zamotání chodí.'),
(1559478,54,18,18,9,'Chytí ho za patu osídlo, a zmocní se ho násilník.'),
(1559479,54,18,18,10,'Skrytať jest při zemi smečka jeho, a léčka jeho na stezce.'),
(1559480,54,18,18,11,'Odevšad hrůzy jej děsiti budou a dotírati na nohy jeho.'),
(1559481,54,18,18,12,'Hladovitá bude síla jeho, a bída pohotově při boku jeho.'),
(1559482,54,18,18,13,'Zžíře žily kůže jeho, zžíře oudy jeho kníže smrti.'),
(1559483,54,18,18,14,'Uchváceno bude z stánku jeho doufání jeho, a to jej přivede k králi strachů.'),
(1559484,54,18,18,15,'V stánku jeho hrůza bydleti bude, ač nebyl jeho; posypáno bude obydlí jeho sirou.'),
(1559485,54,18,18,16,'Od zpodku kořenové jeho uschnou, a svrchu osekány budou ratolesti jeho.'),
(1559486,54,18,18,17,'Památka jeho zahyne z země, aniž jméno jeho slýcháno bude na ulicích.'),
(1559487,54,18,18,18,'Vyženou ho z světla do tmy, anobrž z okršlku zemského vypudí jej.'),
(1559488,54,18,18,19,'Nepozůstaví ani syna ani vnuka v lidu svém, ani jakého ostatku v příbytcích svých.'),
(1559489,54,18,18,20,'Nade dnem jeho zděsí se potomci, a přítomní strachem podjati budou.'),
(1559490,54,18,18,21,'Takovýť jest zajisté způsob nešlechetného, a takový cíl toho, kterýž nezná Boha silného.'),
(1559491,54,18,19,1,'Tedy odpověděv Job, řekl:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559492,54,18,19,2,'Dokudž trápiti budete duši mou, a dotírati na mne řečmi svými?'),
(1559493,54,18,19,3,'Již na desetkrát zhaněli jste mne, aniž se stydíte, že se zatvrzujete proti mně.'),
(1559494,54,18,19,4,'Ale nechť jest tak, že jsem zbloudil, při mně zůstane blud můj.'),
(1559495,54,18,19,5,'Jestliže se pak vždy proti mně siliti chcete, a obviňujíc mne, za pomoc sobě bráti proti mně potupu mou:'),
(1559496,54,18,19,6,'Tedy vězte, že Bůh podvrátil mne, a sítí svou otáhl mne.'),
(1559497,54,18,19,7,'Nebo aj, volám-li pro nátisk, nemám vyslyšení; křičím-li, není rozsouzení.'),
(1559498,54,18,19,8,'Cestu mou zapletl tak, abych nikoli projíti nemohl, a stezky mé temnostmi zastřel.'),
(1559499,54,18,19,9,'Slávu mou se mne strhl, a sňal korunu s hlavy mé.'),
(1559500,54,18,19,10,'Zpodvracel mne všudy vůkol, abych zahynul, a vyvrátil jako strom naději mou.'),
(1559501,54,18,19,11,'Nadto zažžel proti mně prchlivost svou, a přičtl mne mezi nepřátely své.'),
(1559502,54,18,19,12,'Pročež přitáhše houfové jeho, učinili sobě ke mně cestu, a vojensky se položili okolo stanu mého.'),
(1559503,54,18,19,13,'Bratří mé ode mne vzdálil, a známí moji všelijak se mne cizí.'),
(1559504,54,18,19,14,'Opustili mne příbuzní moji, a známí moji zapomenuli se na mne.'),
(1559505,54,18,19,15,'Podruhové domu mého a děvky mé za cizího mne mají, cizozemec jsem před očima jejich.'),
(1559506,54,18,19,16,'Na služebníka svého volám, ale neozývá se, i když ho ústy svými pěkně prosím.'),
(1559507,54,18,19,17,'Dýchání mého štítí se manželka má, ačkoli pokorně jí prosím, pro dítky života mého.'),
(1559508,54,18,19,18,'Nadto i ti nejšpatnější pohrdají mnou; i když povstanu, utrhají mi.'),
(1559509,54,18,19,19,'V ošklivost mne sobě vzali všickni rádcové moji, a ti, kteréž miluji, obrátili se proti mně.'),
(1559510,54,18,19,20,'K kůži mé jako k masu mému přilnuly kosti mé, kůže při zubích mých toliko v cele zůstala.'),
(1559511,54,18,19,21,'Slitujte se nade mnou, slitujte se nade mnou, vy přátelé moji; nebo ruka Boží se mne dotkla.'),
(1559512,54,18,19,22,'Proč mi se protivíte tak jako Bůh silný, a masem mým nemůžte se nasytiti?'),
(1559513,54,18,19,23,'Ó kdyby nyní sepsány byly řeči mé, ó kdyby v knihu vepsány byly,'),
(1559514,54,18,19,24,'Anobrž rafijí železnou a olovem na věčnost na skále aby vyryty byly.'),
(1559515,54,18,19,25,'Ačkoli já vím, že vykupitel můj živ jest, a že v den nejposlednější nad prachem se postaví.'),
(1559516,54,18,19,26,'A ač by kůži mou i tělo červi zvrtali, však vždy v těle svém uzřím Boha.'),
(1559517,54,18,19,27,'Kteréhož já uzřím sobě, a oči mé spatří jej, a ne jiný, jakkoli zhynula ledví má u vnitřnosti mé.'),
(1559518,54,18,19,28,'Ješto byste říci měli: I pročež ho trápíme? poněvadž základ dobré pře při mně se nalézá.'),
(1559519,54,18,19,29,'Bojte se meče, nebo pomsta za nepravosti jest meč, a vězte, žeť bude soud.'),
(1559520,54,18,20,1,'Odpovídaje pak Zofar Naamatský, řekl:'),
(1559521,54,18,20,2,'Z příčiny té myšlení má k odpovídání tobě nutí mne, a to abych rychle učinil,'),
(1559522,54,18,20,3,'Že kárání k zahanbení svému slyším, pročež duch můj osvícený nutí mne, aťbych odpovídal.'),
(1559523,54,18,20,4,'Zdaž nevíš o tom, že od věků, a jakž postavil Bůh člověka na zemi,'),
(1559524,54,18,20,5,'Plésání bezbožných krátké jest, a veselí pokrytce jen na chvílku?'),
(1559525,54,18,20,6,'Byť pak vstoupila až k nebi pýcha jeho, a hlava jeho oblaku by se dotkla,'),
(1559526,54,18,20,7,'Však jako lejno jeho na věky zahyne. Ti, kteříž jej vídali, řeknou: Kam se poděl?'),
(1559527,54,18,20,8,'Jako sen pomine, aniž ho naleznou; nebo uteče jako vidění noční.'),
(1559528,54,18,20,9,'Oko, kteréž ho vídalo, již ho nikdy neuzří, aniž více patřiti bude na něj místo jeho.'),
(1559529,54,18,20,10,'Synové jeho budou přízně u nuzných hledati, a ruce jeho musejí zase vraceti loupež svou.'),
(1559530,54,18,20,11,'Kosti jeho naplněny jsou hříchy mladosti jeho, a s ním v prachu lehnou.'),
(1559531,54,18,20,12,'A ačkoli zlost sladne v ústech jeho, a chová ji pod jazykem svým;'),
(1559532,54,18,20,13,'Kochá se v ní, a nepouští jí, ale zdržuje ji u prostřed dásní svých:'),
(1559533,54,18,20,14,'Však pokrm ten ve střevách jeho promění se; bude jako žluč hadů nejlítějších u vnitřnostech jeho.'),
(1559534,54,18,20,15,'Zboží nahltané vyvrátí, z břicha jeho Bůh silný je vyžene.'),
(1559535,54,18,20,16,'Jed hadů lítých ssáti bude, zabije ho jazyk ještěrčí.'),
(1559536,54,18,20,17,'Neuzří pramenů potoků a řek medu a másla.'),
(1559537,54,18,20,18,'Navrátí úsilé cizí, a nezažive ho, vedlé nátisku svého rozličného; nebude na ně vesel.'),
(1559538,54,18,20,19,'Nebo utiskal a opouštěl nuzné, dům zloupil a nestavěl ho.'),
(1559539,54,18,20,20,'Pročež nesezná nic pokojného v životě svém, aniž které nejrozkošnější své věci bude moci zachovati.'),
(1559540,54,18,20,21,'Nic mu nepozůstane z pokrmu jeho, tak že nebude míti, čím by se troštoval.'),
(1559541,54,18,20,22,'Byť pak i dovršena byla hojnost jeho, ssoužení míti bude; každá ruka trapiče oboří se na něj.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559542,54,18,20,23,'By měl čím naplniti břicho své, dopustí na něj Bůh prchlivost hněvu svého, kterouž na něj dštíti bude i na pokrm jeho.'),
(1559543,54,18,20,24,'Když utíkati bude před zbrojí železnou, prostřelí ho lučiště ocelivé.'),
(1559544,54,18,20,25,'Střela vyňata bude z toulu a vystřelena, nadto meč pronikne žluč jeho; a když odcházeti bude, přikvačí jej hrůzy.'),
(1559545,54,18,20,26,'Všeliká neštěstí jsou polečena v skrýších jeho, zžíře jej oheň nerozdmýchaný, zle se povede i pozůstalému v stanu jeho.'),
(1559546,54,18,20,27,'Odkryjí nebesa nepravost jeho, a země povstane proti němu.'),
(1559547,54,18,20,28,'Rozptýlena bude úroda domu jeho, rozplyne se v den hněvu jeho.'),
(1559548,54,18,20,29,'Tenť jest podíl člověka bezbožného od Boha, to, pravím, dědictví vyrčené jemu od Boha silného.'),
(1559549,54,18,21,1,'A odpovídaje Job, řekl:'),
(1559550,54,18,21,2,'Poslouchejte pilně řeči mé, a bude mi to za potěšení od vás.'),
(1559551,54,18,21,3,'Postrpte mne, abych i já mluvil, a když odmluvím, posmívejž se.'),
(1559552,54,18,21,4,'Zdaliž já před člověkem naříkám? A poněvadž jest proč, jakž nemá býti ssoužen duch můj?'),
(1559553,54,18,21,5,'Pohleďte na mne, a užasněte se, a položte prst na ústa.'),
(1559554,54,18,21,6,'Ano já sám, když rozvažuji své bídy, tedy se děsím, a spopadá tělo mé hrůza.'),
(1559555,54,18,21,7,'Proč bezbožní živi jsou, k věku starému přicházejí, též i bohatnou?'),
(1559556,54,18,21,8,'Símě jejich stálé jest před oblíčejem jejich s nimi, a rodina jejich před očima jejich.'),
(1559557,54,18,21,9,'Domové jejich bezpečni jsou před strachem, aniž metla Boží na nich.'),
(1559558,54,18,21,10,'Býk jejich připouštín bývá, ale ne na prázdno; kráva jejich rodí, a nepotracuje plodu.'),
(1559559,54,18,21,11,'Vypouštějí jako stádo maličké své, a synové jejich poskakují.'),
(1559560,54,18,21,12,'Povyšují hlasu při bubnu a harfě, a veselí se k zvuku muziky.'),
(1559561,54,18,21,13,'Tráví v štěstí dny své, a v okamžení do hrobu sstupují.'),
(1559562,54,18,21,14,'Kteříž říkají Bohu silnému: Odejdi od nás, nebo známosti cest tvých neoblibujeme.'),
(1559563,54,18,21,15,'Kdo jest Všemohoucí, abychom sloužili jemu? A jaký toho zisk, že bychom se modlili jemu?'),
(1559564,54,18,21,16,'Ale pohleď, že není v moci jejich štěstí jejich, pročež rada bezbožných vzdálena jest ode mne.'),
(1559565,54,18,21,17,'Často-liž svíce bezbožných hasne? Přichází-liž na ně bída jejich? Poděluje-liž je bolestmi Bůh v hněvě svém?'),
(1559566,54,18,21,18,'Bývají-liž jako plevy před větrem, a jako drtiny, kteréž zachvacuje vicher?'),
(1559567,54,18,21,19,'Odkládá-liž Bůh synům bezbožníka nepravost jeho? Odplacuje-liž jemu tak, aby to znáti mohl,'),
(1559568,54,18,21,20,'A aby viděly oči jeho neštěstí jeho, a prchlivost Všemohoucího že by pil?'),
(1559569,54,18,21,21,'O dům pak jeho po něm jaká jest péče jeho, když počet měsíců jeho bude umenšen?'),
(1559570,54,18,21,22,'Zdali Boha silného kdo učiti bude umění, kterýž sám vysokosti soudí?'),
(1559571,54,18,21,23,'Tento umírá v síle dokonalosti své, všelijak bezpečný a pokojný.'),
(1559572,54,18,21,24,'Prsy jeho plné jsou mléka, a mozk kostí jeho svlažován bývá.'),
(1559573,54,18,21,25,'Jiný pak umírá v hořkosti ducha, kterýž nikdy nejídal s potěšením.'),
(1559574,54,18,21,26,'Jednostejně v prachu lehnou, a červy se rozlezou.'),
(1559575,54,18,21,27,'Aj, známť myšlení vaše, a chytrosti, kteréž proti mně neprávě vymýšlíte.'),
(1559576,54,18,21,28,'Nebo pravíte: Kde jest dům urozeného? A kde stánek příbytků bezbožných?'),
(1559577,54,18,21,29,'Což jste se netázali jdoucích cestou? Zkušení-liž aspoň jejich nepovolíte,'),
(1559578,54,18,21,30,'Že v den neštěstí ochranu mívá bezbožný, v den, pravím, rozhněvání přistřín bývá?'),
(1559579,54,18,21,31,'Kdo jemu oznámí zjevně cestu jeho? Aneb za to, co činil, kdo jemu odplatí?'),
(1559580,54,18,21,32,'A však i on k hrobu vyprovozen bude, a tam zůstane.'),
(1559581,54,18,21,33,'Sladnou jemu hrudy údolí, nadto za sebou všecky lidi táhne, těch pak, kteříž ho předešli, není počtu.'),
(1559582,54,18,21,34,'Hle, jak vy mne marně troštujete, nebo v odpovědech vašich nezůstává než faleš.'),
(1559583,54,18,22,1,'A odpovídaje Elifaz Temanský, řekl:'),
(1559584,54,18,22,2,'Zdaliž Bohu silnému co prospěšný býti může člověk, když sobě nejmoudřeji počíná?'),
(1559585,54,18,22,3,'Zdaliž se kochá Všemohoucí v tom, že ty se ospravedlňuješ? Aneb má-liž zisk, když bys dokonalé ukázal býti cesty své?'),
(1559586,54,18,22,4,'Zdali, že by se tebe bál, tresce tě, mstě nad tebou?'),
(1559587,54,18,22,5,'Zdali zlost tvá není mnohá? Anobrž není konce nepravostem tvým.'),
(1559588,54,18,22,6,'Nebo jsi brával základ od bratří svých bez příčiny, a roucha z nahých jsi svláčel.'),
(1559589,54,18,22,7,'Vody ustalému jsi nepodal, a hladovitému zbraňovals chleba.'),
(1559590,54,18,22,8,'Ale muži boháči přál jsi země, tak aby ten, jehož osoba vzácná, v ní seděl.'),
(1559591,54,18,22,9,'Vdovy pak pouštěl jsi prázdné, ačkoli ramena sirotků potřína byla.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559592,54,18,22,10,'A protož obkličuji tě osídla, a děsí tě strach nenadálý,'),
(1559593,54,18,22,11,'Aneb tma, abys neviděl, anobrž rozvodnění přikrývá tě.'),
(1559594,54,18,22,12,'Říkáš: Zdaž Bůh není na výsosti nebeské? Ano shlédni vrch hvězd, jak jsou vysoké.'),
(1559595,54,18,22,13,'Protož pravíš: Jak by věděl Bůh silný? Skrze mrákotu-liž by soudil?'),
(1559596,54,18,22,14,'Oblakové jsou skrýše jeho, tak že nevidí; nebo okršlek nebeský obchází.'),
(1559597,54,18,22,15,'Šetříš-liž stezky věku předešlého, kterouž kráčeli lidé marní?'),
(1559598,54,18,22,16,'Kteříž vypléněni jsou před časem, potok vylit jest na základ jejich.'),
(1559599,54,18,22,17,'Kteříž říkali Bohu silnému: Odejdi od nás. Což by tedy jim učiniti měl Všemohoucí?'),
(1559600,54,18,22,18,'On zajisté domy jejich naplnil dobrými věcmi, (ale rada bezbožných vzdálena jest ode mne).'),
(1559601,54,18,22,19,'Což vidouce spravedliví, veselí se, a nevinný posmívá se jim,'),
(1559602,54,18,22,20,'Zvlášť když není vypléněno jmění naše, ostatky pak jejich sežral oheň.'),
(1559603,54,18,22,21,'Přivykejž medle s ním choditi, a pokojněji se míti, skrze to přijde tobě všecko dobré.'),
(1559604,54,18,22,22,'Přijmi, prosím, z úst jeho zákon, a slož řeči jeho v srdci svém.'),
(1559605,54,18,22,23,'Navrátíš-li se k Všemohoucímu, vzdělán budeš, a vzdálíš-li nepravost od stanů svých,'),
(1559606,54,18,22,24,'Tedy nakladeš na zemi zlata, a místo kamení potočního zlata z Ofir.'),
(1559607,54,18,22,25,'Nebo bude Všemohoucí nejčistším zlatem tvým, a stříbrem i silou tvou.'),
(1559608,54,18,22,26,'A tehdáž v Všemohoucím kochati se budeš, a pozdvihna k Bohu tváři své,'),
(1559609,54,18,22,27,'Pokorně modliti se budeš jemu, a vyslyší tě; pročež sliby své plniti budeš.'),
(1559610,54,18,22,28,'Nebo cožkoli začneš, budeť se dařiti, anobrž na cestách tvých svítiti bude světlo.'),
(1559611,54,18,22,29,'Když jiní sníženi budou, tedy díš: Jáť jsem povýšen. Nebo toho, kdož jest očí ponížených, Bůh spasena učiní.'),
(1559612,54,18,22,30,'Vysvobodí i toho, kterýž není bez viny, vysvobodí, pravím, čistotou rukou tvých.'),
(1559613,54,18,23,1,'Tedy odpověděl Job a řekl:'),
(1559614,54,18,23,2,'Což vždy předce naříkání mé za zpouru jmíno bude, ješto bída má těžší jest nežli lkání mé?'),
(1559615,54,18,23,3,'Ó bych věděl, kde ho najíti, šel bych až k trůnu jeho.'),
(1559616,54,18,23,4,'Pořádně bych před ním vedl při, a ústa svá naplnil bych důvody.'),
(1559617,54,18,23,5,'Zvěděl bych, jakými slovy by mně odpověděl, a porozuměl bych, co by mi řekl.'),
(1559618,54,18,23,6,'Zdaliž by podlé veliké síly své rozepři vedl se mnou? Nikoli, nýbrž on sám dal by mi sílu.'),
(1559619,54,18,23,7,'Tuť by upřímý hádati se mohl s ním, a byl bych osvobozen všelijak od soudce svého.'),
(1559620,54,18,23,8,'Ale aj, půjdu-li upřímo dále, tam ho není; pakli nazpět, nepostihnu ho.'),
(1559621,54,18,23,9,'By i čím zaměstknán byl na levo, předce ho nespatřím; zastře-li se na pravo, ovšem ho neuzřím.'),
(1559622,54,18,23,10,'Nebo on zná cestu, kteráž jest při mně; bude-li mne zkušovati, jako zlato se ukáži.'),
(1559623,54,18,23,11,'Šlepějí zajisté jeho přídržela se noha má, cesty jeho šetřil jsem, abych se s ní neuchyloval.'),
(1559624,54,18,23,12,'Aniž od přikázaní rtů jeho uchýlil jsem se, nýbrž ustaviv se na tom, schované jsem měl řeči úst jeho.'),
(1559625,54,18,23,13,'On pak jestliže při čem stojí, kdo jej odvrátí? Ano duše jeho čehož jen žádá, toho hned dovodí.'),
(1559626,54,18,23,14,'A vykoná uložení své o mně; nebo takových příkladů mnoho jest při něm.'),
(1559627,54,18,23,15,'Pročež před tváří jeho děsím se; když to rozvažuji, lekám se ho.'),
(1559628,54,18,23,16,'Bůh zajisté zemdlil srdce mé, a Všemohoucí předěsil mne,'),
(1559629,54,18,23,17,'Tak že sotva jsem nezahynul v těch temnostech; nebo před tváří mou nezakryl mrákoty.'),
(1559630,54,18,24,1,'Proč by od Všemohoucího neměli býti skryti časové, a ti, kteříž jej znají, neměli neviděti dnů jeho?'),
(1559631,54,18,24,2,'Bezbožníť nyní mezníky přenášejí, a stádo, kteréž mocí zajali, pasou.'),
(1559632,54,18,24,3,'Osla sirotků zajímají, v zástavě berou vola od vdovy.'),
(1559633,54,18,24,4,'Strkají nuznými s cesty, musejí se vůbec skrývati chudí na světě.'),
(1559634,54,18,24,5,'Aj, oni jako divocí oslové na poušti, vycházejí jako ku práci své, ráno přivstávajíce k loupeži; poušť jest chléb jejich i dětí jejich.'),
(1559635,54,18,24,6,'Na cizím poli žnou, a z vinic bezbožníci sbírají.'),
(1559636,54,18,24,7,'Nahé přivodí k tomu, aby nocovati musili bez roucha, nemajíce se čím přiodíti na zimě.'),
(1559637,54,18,24,8,'A přívalem v horách moknouce, nemajíce obydlí, k skále se přivinouti musejí.'),
(1559638,54,18,24,9,'Loupí sirotky, kteříž jsou při prsích, a od chudého základ berou.'),
(1559639,54,18,24,10,'Nahého opouštějí , že musí choditi bez oděvu, a ti, kteříž snášejí snopy, v hladu zůstávati.'),
(1559640,54,18,24,11,'Ti, jenž mezi zdmi jejich olej vytlačují, a presy tlačí, žíznějí.'),
(1559641,54,18,24,12,'Lidé v městech lkají, a duše zraněných volají, Bůh pak přítrže tomu nečiní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559642,54,18,24,13,'Oniť jsou ti, kteříž odporují světlu, a neznají cest jeho, aniž chodí po stezkách jeho.'),
(1559643,54,18,24,14,'Na úsvitě povstávaje vražedlník, morduje chudého a nuzného, a v noci jest jako zloděj.'),
(1559644,54,18,24,15,'Tolikéž oko cizoložníka šetří soumraku, říkaje: Nespatříť mne žádný, a tvář zakrývá.'),
(1559645,54,18,24,16,'Podkopávají potmě i domy, kteréž sobě ve dne znamenali; nebo nenávidí světla.'),
(1559646,54,18,24,17,'Ale hned v jitře přichází na ně stín smrti; když jeden druhého poznati může, strachu stínu smrti okoušejí.'),
(1559647,54,18,24,18,'Lehcí jsou na svrchku vody, zlořečené jest jmění jejich na zemi, aniž odcházejí cestou svobodnou.'),
(1559648,54,18,24,19,'Jako sucho a horko uchvacuje vody sněžné, tak hrob ty, jenž hřešili.'),
(1559649,54,18,24,20,'Zapomíná se na něj život matky, sladne červům, nebývá více připomínán, a tak polámána bývá nepravost jako strom.'),
(1559650,54,18,24,21,'Připojuje mu neplodnou, kteráž nerodí, a vdově dobře nečiní.'),
(1559651,54,18,24,22,'Zachvacuje silné mocí svou; ostojí-li kdo z nich, bojí se o život svůj.'),
(1559652,54,18,24,23,'Dává jemu, na čemž by bezpečně spolehnouti mohl, však oči jeho šetří cest jejich.'),
(1559653,54,18,24,24,'Bývají zvýšeni poněkud, ale hned jich není; tak jako jiní všickni sníženi, vypléněni, a jako vrškové klasů stínáni bývají.'),
(1559654,54,18,24,25,'Zdaliž není tak? Kdo na mne dokáže klamu, a v nic obrátí řeč mou?'),
(1559655,54,18,25,1,'Tedy odpovídaje Bildad Suchský, řekl:'),
(1559656,54,18,25,2,'Panování a hrůza Boží působí pokoj na výsostech jeho.'),
(1559657,54,18,25,3,'Zdaliž jest počet vojskům jeho? A nad kým nevzchází světlo jeho?'),
(1559658,54,18,25,4,'Jakž by tedy spravedliv býti mohl bídný člověk před Bohem silným, aneb jak čist býti narozený z ženy?'),
(1559659,54,18,25,5,'Hle, ani měsíc nesvítil by, ani hvězdy nebyly by čisté před očima jeho,'),
(1559660,54,18,25,6,'Nadto pak smrtelný člověk, jsa jako červ, a syn člověka, jako hmyz.'),
(1559661,54,18,26,1,'A odpovídaje Job, řekl:'),
(1559662,54,18,26,2,'Komu jsi napomohl? Tomu-li, kterýž nemá síly? Toho-lis retoval, kterýž jest bez moci?'),
(1559663,54,18,26,3,'Komu jsi rady udělil? Nemoudrému-li? Hned jsi základu dostatečně poučil?'),
(1559664,54,18,26,4,'Komužs ty řeči zvěstoval? A čí duch vyšel z tebe?'),
(1559665,54,18,26,5,'Však i mrtvé věci pod vodami a obyvateli jejich sformovány bývají.'),
(1559666,54,18,26,6,'Odkryta jest propast před ním, i zahynutí není zakryto.'),
(1559667,54,18,26,7,'Ontě roztáhl půlnoční stranu nad prázdnem, zavěsil zemi na ničemž.'),
(1559668,54,18,26,8,'Zavazuje vody v oblacích svých, aniž se trhá oblak pod nimi.'),
(1559669,54,18,26,9,'On sám zdržuje stále trůn svůj, a roztahuje na něm oblaky své.'),
(1559670,54,18,26,10,'Cíl vyměřil rozlévání se vodám, až do skonání světla a tmy.'),
(1559671,54,18,26,11,'Sloupové nebeští třesou se a pohybují od žehrání jeho.'),
(1559672,54,18,26,12,'Mocí svou rozdělil moře, a rozumností svou dutí jeho.'),
(1559673,54,18,26,13,'Duchem svým nebesa ozdobil, a ruka jeho sformovala hada dlouhého.'),
(1559674,54,18,26,14,'Aj, toť jsou jen částky cest jeho, a jak nestižitelné jest i to maličko, což jsme slyšeli o něm. Hřímání pak moci jeho kdo srozumí?'),
(1559675,54,18,27,1,'Potom dále Job vedl řeč svou a řekl:'),
(1559676,54,18,27,2,'Živť jest Bůh silný, kterýž zavrhl při mou, a Všemohoucí, kterýž hořkostí naplnil duši mou,'),
(1559677,54,18,27,3,'Že nikoli, dokudž duše má ve mně bude a duch Boží v chřípích mých,'),
(1559678,54,18,27,4,'Nebudou mluviti rtové moji nepravosti, a jazyk můj vynášeti lsti.'),
(1559679,54,18,27,5,'Odstup ode mne, abych vás za spravedlivé vysvědčil; dokudž dýchati budu, neodložím upřímosti své od sebe.'),
(1559680,54,18,27,6,'Spravedlnosti své držím se, aniž se jí pustím; nezahanbíť mne srdce mé nikdy.'),
(1559681,54,18,27,7,'Bude jako bezbožník nepřítel můj, a povstávající proti mně jako nešlechetník.'),
(1559682,54,18,27,8,'Nebo jaká jest naděje pokrytce, by pak lakoměl, když Bůh vytrhne duši jeho?'),
(1559683,54,18,27,9,'Zdaliž volání jeho vyslyší Bůh silný, když na něj přijde ssoužení?'),
(1559684,54,18,27,10,'Zdaliž v Všemohoucím kochati se bude? Bude-liž vzývati Boha každého času?'),
(1559685,54,18,27,11,'Ale já učím vás, v kázni Boha silného jsa, a jak se mám k Všemohoucímu, netajím.'),
(1559686,54,18,27,12,'Aj, vy všickni to vidíte, pročež vždy tedy takovou marnost vynášíte?'),
(1559687,54,18,27,13,'Ten má podíl člověk bezbožný u Boha silného, a to dědictví ukrutníci od Všemohoucího přijímají:'),
(1559688,54,18,27,14,'Rozmnoží-li se synové jeho, rozmnoží se pod meč, a rodina jeho nenasytí se chlebem.'),
(1559689,54,18,27,15,'Pozůstalí po něm v smrti pohřbeni budou, a vdovy jeho nebudou ho plakati.'),
(1559690,54,18,27,16,'Nashromáždí-li jako prachu stříbra, a jako bláta najedná-li šatů:'),
(1559691,54,18,27,17,'Co najedná, to spravedlivý obleče, a stříbro nevinný rozdělí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559692,54,18,27,18,'Vystaví-li jako Arktura dům svůj, bude však jako bouda, kterouž udělal strážný.'),
(1559693,54,18,27,19,'Bohatý když umře, nebude pochován; pohledí někdo, anť ho není.'),
(1559694,54,18,27,20,'Postihnou jej hrůzy jako vody, v noci kradmo zachvátí ho vicher.'),
(1559695,54,18,27,21,'Pochytí jej východní vítr, a odejde, nebo vichřicí uchvátí jej z místa jeho.'),
(1559696,54,18,27,22,'Takové věci na něj dopustí Bůh bez lítosti, ačkoli před rukou jeho prudce utíkati bude.'),
(1559697,54,18,27,23,'Tleskne nad ním každý rukama svýma, a ckáti bude z místa svého.'),
(1559698,54,18,28,1,'Máť zajisté stříbro prameny své, a zlato místo k přehánění.'),
(1559699,54,18,28,2,'Železo z země vzato bývá, a kámen rozpuštěný dává měď.'),
(1559700,54,18,28,3,'Cíl ukládá temnostem, a všelikou dokonalost člověk vystihá, kámen mrákoty a stínu smrti.'),
(1559701,54,18,28,4,'Protrhuje se řeka na obyvatele, tak že ji nemůže žádný přebřesti, a svozována bývá uměním smrtelného člověka, i odchází.'),
(1559702,54,18,28,5,'Z země vychází chléb, ačkoli pod ní jest něco rozdílného, podobného k ohni.'),
(1559703,54,18,28,6,'V některé zemi jest kamení zafirové a prach zlatý,'),
(1559704,54,18,28,7,'K čemuž stezky nezná žádný pták, aniž ji spatřilo oko luňáka,'),
(1559705,54,18,28,8,'Kteréž nešlapala mladá zvěř, aniž šel po ní lev.'),
(1559706,54,18,28,9,'K škřemeni vztahuje ruku svou, a z kořene převrací hory.'),
(1559707,54,18,28,10,'Z skálí vyvodí potůčky, a všecko, což jest drahého, spatřuje oko jeho.'),
(1559708,54,18,28,11,'Vylévati se řekám zbraňuje, a tak cožkoli skrytého jest, na světlo vynáší.'),
(1559709,54,18,28,12,'Ale moudrost kde nalezena bývá? A kde jest místo rozumnosti?'),
(1559710,54,18,28,13,'Neví smrtelný člověk ceny její, aniž bývá nalezena v zemi živých.'),
(1559711,54,18,28,14,'Propast praví: Není ve mně, moře také dí: Není u mne.'),
(1559712,54,18,28,15,'Nedává se zlata čistého za ni, aniž odváženo bývá stříbro za směnu její.'),
(1559713,54,18,28,16,'Nemůže býti ceněna za zlato z Ofir, ani za onychin drahý a zafir.'),
(1559714,54,18,28,17,'Nevrovná se jí zlato ani drahý kámen, aniž směněna býti může za nádobu z ryzího zlata.'),
(1559715,54,18,28,18,'Korálů pak a perel se nepřipomíná; nebo nabytí moudrosti dražší jest nad klénoty.'),
(1559716,54,18,28,19,'Není jí rovný v ceně smaragd z Mouřenínské země, aniž za čisté zlato může ceněna býti.'),
(1559717,54,18,28,20,'Odkudž tedy moudrost přichází? A kde jest místo rozumnosti?'),
(1559718,54,18,28,21,'Poněvadž skryta jest před očima všelikého živého, i před nebeským ptactvem ukryta jest.'),
(1559719,54,18,28,22,'Zahynutí i smrt praví: Ušima svýma slyšely jsme pověst o ní.'),
(1559720,54,18,28,23,'Sám Bůh rozumí cestě její, a on ví místo její.'),
(1559721,54,18,28,24,'Nebo on končiny země spatřuje, a všecko, což jest pod nebem, vidí,'),
(1559722,54,18,28,25,'Tak že větru váhu dává, a vody v míru odvažuje.'),
(1559723,54,18,28,26,'On též vyměřuje dešti právo, i cestu blýskání hromů.'),
(1559724,54,18,28,27,'Hned tehdáž viděl ji, a rozhlásil ji,připravil ji, a vystihl ji.'),
(1559725,54,18,28,28,'Člověku pak řekl: Aj, bázeň Páně jest moudrost, a odstoupiti od zlého rozumnost.'),
(1559726,54,18,29,1,'Ještě dále Job vedl řeč svou, a řekl:'),
(1559727,54,18,29,2,'Ó bych byl jako za časů předešlých, za dnů, v nichž mne Bůh zachovával,'),
(1559728,54,18,29,3,'Dokudž svítil svící svou nad hlavou mou, při jehož světle chodíval jsem v temnostech,'),
(1559729,54,18,29,4,'Tak jako jsem byl za dnů mladosti své, dokudž přívětivost Boží byla v stanu mém,'),
(1559730,54,18,29,5,'Dokudž ještě Všemohoucí byl se mnou, a všudy vůkol mne dítky mé,'),
(1559731,54,18,29,6,'Když šlepěje mé máslem oplývaly, a skála vylévala mi prameny oleje,'),
(1559732,54,18,29,7,'Když jsem vycházel k bráně skrze město, a na ulici strojíval sobě stolici svou.'),
(1559733,54,18,29,8,'Jakž mne spatřovali mládenci, skrývali se, starci pak povstávali a stáli.'),
(1559734,54,18,29,9,'Knížata choulili se v řečech, anobrž ruku kladli na ústa svá.'),
(1559735,54,18,29,10,'Hlas vývod se tratil, a jazyk jejich lnul k dásním jejich.'),
(1559736,54,18,29,11,'Nebo ucho slyše, blahoslavilo mne, a oko vida, posvědčovalo mi,'),
(1559737,54,18,29,12,'Že vysvobozuji chudého volajícího, a sirotka, i toho, kterýž nemá spomocníka.'),
(1559738,54,18,29,13,'Požehnání hynoucího přicházelo na mne, a srdce vdovy k plésání jsem vzbuzoval.'),
(1559739,54,18,29,14,'V spravedlnost jsem se obláčel, a ona ozdobovala mne; jako plášť a koruna byl soud můj.'),
(1559740,54,18,29,15,'Místo očí býval jsem slepému, a místo noh kulhavému.'),
(1559741,54,18,29,16,'Byl jsem otcem nuzných, a na při, jíž jsem nebyl povědom, vyptával jsem se.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559742,54,18,29,17,'A tak vylamoval jsem třenovní zuby nešlechetníka, a z zubů jeho vyrážel jsem loupež.'),
(1559743,54,18,29,18,'A protož jsem říkal: V hnízdě svém umru, a jako písek rozmnožím dny.'),
(1559744,54,18,29,19,'Kořen můj rozloží se při vodách, a rosa nocovati bude na ratolestech mých.'),
(1559745,54,18,29,20,'Sláva má mladnouti bude při mně, a lučiště mé v ruce mé obnovovati se.'),
(1559746,54,18,29,21,'Poslouchajíce, čekali na mne, a přestávali na radě mé.'),
(1559747,54,18,29,22,'Po slovu mém nic neměnili, tak na ně dštila řeč má.'),
(1559748,54,18,29,23,'Nebo očekávali mne jako deště, a ústa svá otvírali jako k přívalu žádostivému.'),
(1559749,54,18,29,24,'Žertoval-li jsem s nimi, nevěřili; pročež u vážnosti mne míti neoblevovali.'),
(1559750,54,18,29,25,'Přišel-li jsem kdy k nim, sedal jsem na předním místě, a tak bydlil jsem jako král v vojště, když smutných potěšuje.'),
(1559751,54,18,30,1,'Nyní pak posmívají se mi mladší mne, jejichž bych otců nechtěl byl postaviti se psy stáda svého.'),
(1559752,54,18,30,2,'Ač síla rukou jejich k čemu by mi byla? Zmařena jest při nich starost jejich.'),
(1559753,54,18,30,3,'Nebo chudobou a hladem znuzeni, utíkali na planá, tmavá, soukromná a pustá místa.'),
(1559754,54,18,30,4,'Kteříž trhali zeliny po chrastinách, ano i koření, a jalovec za pokrm byl jim.'),
(1559755,54,18,30,5,'Z prostřed lidí vyháníni byli; povolávali za nimi, jako za zlodějem,'),
(1559756,54,18,30,6,'Tak že musili bydliti v výmolích potoků, v děrách země a skálí.'),
(1559757,54,18,30,7,'V chrastinách řvali, pod trní se shromažďovali,'),
(1559758,54,18,30,8,'Lidé nejnešlechetnější, nýbrž lidé bez poctivosti, menší váhy i než ta země.'),
(1559759,54,18,30,9,'Nyní, pravím, jsem jejich písničkou, jsa jim učiněn za přísloví.'),
(1559760,54,18,30,10,'V ošklivosti mne mají, vzdalují se mne, a na tvář mou nestydí se plvati.'),
(1559761,54,18,30,11,'Nebo Bůh mou vážnost odjal, a ssoužil mne; pročež uzdu před přítomností mou svrhli.'),
(1559762,54,18,30,12,'Po pravici mládež povstává, nohy mi podrážejí, tak že šlapáním protřeli ke mně stezky nešlechetnosti své.'),
(1559763,54,18,30,13,'Mou pak stezku zkazili, k bídě mé přidali, ač jim to nic nepomůže.'),
(1559764,54,18,30,14,'Jako širokou mezerou vskakují, a k vyplénění mému valí se.'),
(1559765,54,18,30,15,'Obrátily se na mne hrůzy, stihají jako vítr ochotnost mou, nebo jako oblak pomíjí zdraví mé.'),
(1559766,54,18,30,16,'A již ve mně rozlila se duše má, pochytili mne dnové trápení mého,'),
(1559767,54,18,30,17,'Kteréž v noci vrtá kosti mé ve mně; pročež ani nervové moji neodpočívají.'),
(1559768,54,18,30,18,'Oděv můj mění se pro násilnou moc bolesti, kteráž mne tak jako obojek sukně mé svírá.'),
(1559769,54,18,30,19,'Uvrhl mne do bláta, tak že jsem již podobný prachu a popelu.'),
(1559770,54,18,30,20,'Volám k tobě, ó Bože, a neslyšíš mne; postavuji se, ale nehledíš na mne.'),
(1559771,54,18,30,21,'Obrátils mi se v ukrutného nepřítele, silou ruky své mi odporuješ.'),
(1559772,54,18,30,22,'Vznášíš mne u vítr, sázíš mne na něj, a k rozplynutí mi přivodíš zdravý soud.'),
(1559773,54,18,30,23,'Nebo vím, že mne k smrti odkážeš, a do domu, do něhož se shromažďuje všeliký živý.'),
(1559774,54,18,30,24,'Jistě žeť nevztáhne Bůh do hrobu ruky, by pak, když je stírá, i volali.'),
(1559775,54,18,30,25,'Zdaliž jsem neplakal nad tím, kdož okoušel zlých dnů? Duše má kormoutila se nad nuzným.'),
(1559776,54,18,30,26,'Když jsem dobrého čekal, přišlo mi zlé; nadál jsem se světla, ale přišla mrákota.'),
(1559777,54,18,30,27,'Vnitřností mé zevřely, tak že se ještě neupokojily; předstihli mne dnové trápení.'),
(1559778,54,18,30,28,'Chodím osmahlý, ne od slunce, povstávaje, i mezi mnohými křičím.'),
(1559779,54,18,30,29,'Bratrem učiněn jsem draků, a tovaryšem mladých pstrosů.'),
(1559780,54,18,30,30,'Kůže má zčernala na mně, a kosti mé vyprahly od horkosti.'),
(1559781,54,18,30,31,'A protož v kvílení obrátila se harfa má, a píšťalka má v hlas plačících.'),
(1559782,54,18,31,1,'Smlouvu jsem učinil s očima svýma, a proč bych hleděl na pannu?'),
(1559783,54,18,31,2,'Nebo jaký jest díl od Boha s hůry, aneb dědictví od Všemohoucího s výsosti?'),
(1559784,54,18,31,3,'Zdaliž zahynutí nešlechetnému a pomsta zázračná činitelům nepravosti připravena není?'),
(1559785,54,18,31,4,'Zdaliž on nevidí cest mých, a všech kroků mých nepočítá?'),
(1559786,54,18,31,5,'Obíral-li jsem se s neupřímostí, a chvátala-li ke lsti noha má:'),
(1559787,54,18,31,6,'Nechť mne zváží na váze spravedlnosti, a přezví Bůh upřímost mou.'),
(1559788,54,18,31,7,'Uchýlil-li se krok můj s cesty, a za očima mýma odešlo-li srdce mé, a rukou mých chytila-li se jaká poškvrna:'),
(1559789,54,18,31,8,'Tedy co naseji, nechť jiný sní, a výstřelkové moji ať jsou vykořeněni.'),
(1559790,54,18,31,9,'Jestliže se dalo přivábiti srdce mé k ženě, a u dveří bližního svého činil-li jsem úklady:'),
(1559791,54,18,31,10,'Nechť mele jinému žena má, a nad ní ať se schylují jiní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559792,54,18,31,11,'Neboť jest to nešlechetnost, a nepravost odsudku hodná.'),
(1559793,54,18,31,12,'Oheň ten zajisté by až do zahynutí žral, a všecku úrodu mou vykořenil.'),
(1559794,54,18,31,13,'Nechtěl-li jsem státi k soudu s služebníkem svým aneb děvkou svou v rozepři jejich se mnou?'),
(1559795,54,18,31,14,'Nebo co bych činil, kdyby povstal Bůh silný? A kdyby vyhledával, co bych odpověděl jemu?'),
(1559796,54,18,31,15,'Zdali ten, kterýž mne v břiše učinil, neučinil i jeho? A nesformoval nás hned v životě jeden a týž?'),
(1559797,54,18,31,16,'Odepřel-li jsem žádosti nuzných, a oči vdovy jestliže jsem kormoutil?'),
(1559798,54,18,31,17,'A jedl-li jsem skyvu svou sám, a nejedl-li i sirotek z ní?'),
(1559799,54,18,31,18,'Poněvadž od mladosti mé rostl se mnou jako u otce, a od života matky své býval jsem vdově za vůdce.'),
(1559800,54,18,31,19,'Díval-li jsem se na koho, že by hynul, nemaje šatů, a nuzný že by neměl oděvu?'),
(1559801,54,18,31,20,'Nedobrořečila-li mi bedra jeho, že rounem beranů mých se zahřel?'),
(1559802,54,18,31,21,'Opřáhl-li jsem na sirotka rukou svou, když jsem v bráně viděl pomoc svou:'),
(1559803,54,18,31,22,'Lopatka má od svých plecí nechť odpadne, a ruka má z kloubu svého ať se vylomí.'),
(1559804,54,18,31,23,'Nebo jsem se bál, aby mne Bůh nesetřel, jehož bych velebnosti nikoli neznikl.'),
(1559805,54,18,31,24,'Skládal-li jsem v zlatě naději svou, aneb hrudě zlata říkal-li jsem: Doufání mé?'),
(1559806,54,18,31,25,'Veselil-li jsem se z toho, že bylo rozmnoženo zboží mé, a že ho množství nabyla ruka má?'),
(1559807,54,18,31,26,'Hleděl-li jsem na světlost slunce svítícího, a na měsíc spanile chodící,'),
(1559808,54,18,31,27,'Tak že by se tajně dalo svésti srdce mé, a že by líbala ústa má ruku mou?'),
(1559809,54,18,31,28,'I toť by byla nepravost odsudku hodná; neboť bych tím zapíral Boha silného nejvyššího.'),
(1559810,54,18,31,29,'Radoval-li jsem se z neštěstí toho, kterýž mne nenáviděl, a plésal-li jsem, když se mu zle vedlo?'),
(1559811,54,18,31,30,'Nedopustilť jsem zajisté hřešiti ani ústům svým, abych zlořečení žádal duši jeho.'),
(1559812,54,18,31,31,'Jestliže neříkala čeládka má: Ó by nám dal někdo masa toho; nemůžeme se ani najísti?'),
(1559813,54,18,31,32,'Nebo vně nenocoval host, dvéře své pocestnému otvíral jsem.'),
(1559814,54,18,31,33,'Přikrýval-li jsem jako jiní lidé přestoupení svá, skrývaje v skrýši své nepravost svou?'),
(1559815,54,18,31,34,'A ač bych byl mohl škoditi množství velikému, ale pohanění rodů děsilo mne; protož jsem mlčel, nevycházeje ani ze dveří.'),
(1559816,54,18,31,35,'Ó bych měl toho, kterýž by mne vyslyšel. Ale aj, totoť jest znamení mé: Všemohoucí sám bude odpovídati za mne, a kniha, kterouž sepsal odpůrce můj.'),
(1559817,54,18,31,36,'Víť Bůh, nenosil-li bych ji na rameni svém, neotočil-li bych ji sobě místo koruny.'),
(1559818,54,18,31,37,'Počet kroků svých oznámil bych jemu, jako kníže přiblížil bych se k němu.'),
(1559819,54,18,31,38,'Jestliže proti mně země má volala, tolikéž i záhonové její plakali,'),
(1559820,54,18,31,39,'Jídal-li jsem úrody její bez peněz, a duši držitelů jejich přivodil-li jsem k vzdychání:'),
(1559821,54,18,31,40,'Místo pšenice nechť vzejde trní, a místo ječmene koukol.'),
(1559822,54,18,31,41,'Skonávají se slova Jobova.'),
(1559823,54,18,32,1,'A když přestali ti tři muži odpovídati Jobovi, proto že se spravedlivý sobě zdál,'),
(1559824,54,18,32,2,'Tedy rozpáliv se hněvem Elihu, syn Barachele Buzitského z rodu Syrského, na Joba, rozhněval se, proto že spravedlivější pravil býti duši svou nad Boha.'),
(1559825,54,18,32,3,'Ano i na ty tři z přátel jeho roznítil se hněv jeho, proto že nenalézajíce odpovědi, však potupovali Joba.'),
(1559826,54,18,32,4,'Nebo Elihu očekával na Joba a na ně s řečí, proto že starší byli věkem než on.'),
(1559827,54,18,32,5,'Ale vida Elihu, že nebylo žádné odpovědi v ústech těch tří mužů, zažhl se v hněvě svém.'),
(1559828,54,18,32,6,'I mluvil Elihu syn Barachele Buzitského, řka: Já jsem nejmladší, vy pak jste starci, pročež ostýchaje se, nesměl jsem vám oznámiti zdání svého.'),
(1559829,54,18,32,7,'Myslil jsem: Staří mluviti budou, a mnoho let mající v známost uvedou moudrost.'),
(1559830,54,18,32,8,'Ale vidím, že Duch Boží v člověku a nadšení Všemohoucího činí lidi rozumné.'),
(1559831,54,18,32,9,'Slavní ne vždycky jsou moudří, aniž starci vždycky rozumějí soudu.'),
(1559832,54,18,32,10,'A protož pravím: Poslouchejte mne, oznámím i já také zdání své.'),
(1559833,54,18,32,11,'Aj, očekával jsem na slova vaše, poslouchal jsem důvodů vašich dotud, dokudž jste vyhledávali řeči,'),
(1559834,54,18,32,12,'A bedlivě vás soudě, spatřil jsem, že žádného není, kdo by Joba přemohl, není z vás žádného, ješto by odpovídal řečem jeho.'),
(1559835,54,18,32,13,'Ale díte snad: Nalezli jsme moudrost, Bůh silný stihá jej, ne člověk.'),
(1559836,54,18,32,14,'Odpovím: Ač Job neobracel proti mně řeči, a však slovy vašimi nebudu jemu odpovídati.'),
(1559837,54,18,32,15,'Bojí se, neodpovídají více, zavrhli od sebe slova.'),
(1559838,54,18,32,16,'Čekal jsem zajisté, však poněvadž nemluví, ale mlčí, a neodpovídají více,'),
(1559839,54,18,32,17,'Odpovím i já také za sebe, oznámím zdání své i já.'),
(1559840,54,18,32,18,'Nebo pln jsem řečí, těsno ve mně duchu života mého.'),
(1559841,54,18,32,19,'Aj, břicho mé jest jako mest nemající průduchu, jako sudové noví rozpuklo by se.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559842,54,18,32,20,'Mluviti budu, a vydchnu sobě, otevru rty své, a odpovídati budu.'),
(1559843,54,18,32,21,'Nebuduť pak šetřiti osoby žádného, a k člověku bez proměňování jména mluviti budu.'),
(1559844,54,18,32,22,'Nebo neumím jmen proměňovati, nebo tudíž by mne zachvátil stvořitel můj.'),
(1559845,54,18,33,1,'Slyšiž tedy, prosím, Jobe, řeči mé, a všech slov mých ušima svýma pozoruj.'),
(1559846,54,18,33,2,'Aj, jižť otvírám ústa svá, mluví jazyk můj v ústech mých.'),
(1559847,54,18,33,3,'Upřímost srdce mého a umění vynesou rtové moji.'),
(1559848,54,18,33,4,'Duch Boha silného učinil mne, a dchnutí Všemohoucího dalo mi život.'),
(1559849,54,18,33,5,'Můžeš-li, odpovídej mi, připrav se proti mně, a postav se.'),
(1559850,54,18,33,6,'Aj, já podlé žádosti tvé buduť místo Boha silného; z bláta sformován jsem i já.'),
(1559851,54,18,33,7,'Pročež strach ze mne nepředěsí tě, a ruka má nebudeť k obtížení.'),
(1559852,54,18,33,8,'Řekl jsi pak přede mnou, a hlas ten řečí tvých slyšel jsem:'),
(1559853,54,18,33,9,'Čist jsem, bez přestoupení, nevinný jsem, a nepravosti při mně není.'),
(1559854,54,18,33,10,'Aj, příčiny ku potření mne shledal Bůh, klade mne sobě za nepřítele,'),
(1559855,54,18,33,11,'Svírá poutami nohy mé, střeže všech stezek mých.'),
(1559856,54,18,33,12,'Aj, tím nejsi spravedliv, odpovídám tobě, nebo větší jest Bůh nežli člověk.'),
(1559857,54,18,33,13,'Oč se s ním nesnadníš? Žeť všech svých věcí nezjevuje?'),
(1559858,54,18,33,14,'Ano jednou mluví Bůh silný, i dvakrát, a nešetří toho člověk.'),
(1559859,54,18,33,15,'Skrze sny u vidění nočním, když připadá hluboký sen na lidi ve spaní na ložci,'),
(1559860,54,18,33,16,'Tehdáž odkrývá ucho lidem, a čemu je učí, to zpečeťuje,'),
(1559861,54,18,33,17,'Aby odtrhl člověka od skutku zlého, a pýchu od muže vzdálil,'),
(1559862,54,18,33,18,'A zachoval duši jeho od jámy, a život jeho aby netrefil na meč.'),
(1559863,54,18,33,19,'Tresce i bolestí na lůži jeho, a všecky kosti jeho násilnou nemocí,'),
(1559864,54,18,33,20,'Tak že sobě život jeho oškliví pokrm, a duše jeho krmi nejlahodnější.'),
(1559865,54,18,33,21,'Hyne tělo jeho patrně, a vyhlédají kosti jeho, jichž prvé nebylo vídati.'),
(1559866,54,18,33,22,'A tak bývá blízká hrobu duše jeho, a život jeho smrtelných ran.'),
(1559867,54,18,33,23,'Však bude-li míti anděla vykladače jednoho z tisíce, kterýž by za člověka oznámil pokání jeho:'),
(1559868,54,18,33,24,'Tedy smiluje se nad ním, a dí: Vyprosť jej, ať nesstoupí do porušení, oblíbilť jsem mzdu vyplacení.'),
(1559869,54,18,33,25,'I odmladne tělo jeho nad dítěcí, a navrátí se ke dnům mladosti své.'),
(1559870,54,18,33,26,'Kořiti se bude Bohu, a zamiluje jej, a patřiti bude na něj tváří ochotnou; nadto navrátí člověku spravedlnost jeho.'),
(1559871,54,18,33,27,'Kterýž hledě na lidi, řekne: Zhřešilť jsem byl, a to, což pravého bylo, převrátil jsem, ale nebylo mi to prospěšné.'),
(1559872,54,18,33,28,'Bůh však vykoupil duši mou, aby nešla do jámy, a život můj, aby světlo spatřoval.'),
(1559873,54,18,33,29,'Aj, všeckoť to dělá Bůh silný dvakrát i třikrát při člověku,'),
(1559874,54,18,33,30,'Aby odvrátil duši jeho od jámy, a aby osvícen byl světlem živých.'),
(1559875,54,18,33,31,'Pozoruj, Jobe, poslouchej mne, mlč, ať já mluvím.'),
(1559876,54,18,33,32,'Jestliže máš slova, odpovídej mi, nebo bych chtěl ospravedlniti tebe.'),
(1559877,54,18,33,33,'Pakli nic, ty mne poslouchej; mlč, a poučím tě moudrosti.'),
(1559878,54,18,34,1,'Ještě mluvil Elihu, a řekl:'),
(1559879,54,18,34,2,'Poslouchejte, moudří, řečí mých, a rozumní, ušima pozorujte.'),
(1559880,54,18,34,3,'Nebo ucho řečí zkušuje, tak jako dásně okoušejí pokrmu.'),
(1559881,54,18,34,4,'Soud sobě zvolme, a vyhledejme mezi sebou, co by bylo dobrého.'),
(1559882,54,18,34,5,'Nebo řekl Job: Spravedliv jsem, a Bůh silný zavrhl při mou.'),
(1559883,54,18,34,6,'Své-liž bych pře ukrývati měl? Přeplněna jest bolestí rána má bez provinění.'),
(1559884,54,18,34,7,'Který muž jest podobný Jobovi, ješto by pil posměch jako vodu?'),
(1559885,54,18,34,8,'A že by všel v tovaryšství s činiteli nepravosti, a chodil by s lidmi nešlechetnými?'),
(1559886,54,18,34,9,'Nebo řekl: Neprospívá to člověku líbiti se Bohu.'),
(1559887,54,18,34,10,'A protož, muži rozumní, poslouchejte mne. Odstup od Boha silného nešlechetnost a od Všemohoucího nepravost.'),
(1559888,54,18,34,11,'Nebo on podlé skutků člověka odplací, a podlé toho, jaká jest čí cesta, působí, aby to nalézal.'),
(1559889,54,18,34,12,'A naprosto Bůh silný nečiní nic nešlechetně, a Všemohoucí nepřevrací soudu.'),
(1559890,54,18,34,13,'Kdo svěřil jemu zemi? A kdo zpořádal všecken okršlek?'),
(1559891,54,18,34,14,'Kdyby se na něj obrátil, a ducha jeho i duši jeho k sobě vzal,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559892,54,18,34,15,'Umřelo by všeliké tělo pojednou, a tak by člověk do prachu se navrátil.'),
(1559893,54,18,34,16,'Máš-li tedy rozum, poslyš toho, pusť v uši své hlas řečí mých.'),
(1559894,54,18,34,17,'Ješto ten, kterýž by v nenávisti měl soud, zdaliž by panovati mohl? Čili toho, jenž jest svrchovaně spravedlivý, za nešlechetného vyhlásíš?'),
(1559895,54,18,34,18,'Zdaliž sluší králi říci: Ó nešlechetný, a šlechticům: Ó bezbožní?'),
(1559896,54,18,34,19,'Mnohem méně tomu, kterýž nepřijímá osob knížat, aniž u něho má přednost urozený před nuzným; nebo dílo rukou jeho jsou všickni.'),
(1559897,54,18,34,20,'V okamžení umírají, třebas o půl noci postrčeni bývají lidé, a pomíjejí, a zachvácen bývá silný ne rukou lidskou.'),
(1559898,54,18,34,21,'Nebo oči jeho hledí na cesty člověka, a všecky kroky jeho on spatřuje.'),
(1559899,54,18,34,22,'Neníť žádných temností, ani stínu smrti, kdež by se skryli činitelé nepravosti.'),
(1559900,54,18,34,23,'Aniž zajisté vzkládá na koho více, tak aby se s Bohem silným souditi mohl.'),
(1559901,54,18,34,24,'Pyšné stírá bez počtu, a postavuje jiné na místa jejich.'),
(1559902,54,18,34,25,'Nebo zná skutky jejich; pročež na ně obrací noc, a potříni bývají.'),
(1559903,54,18,34,26,'Jakožto bezbožné rozráží je na místě patrném,'),
(1559904,54,18,34,27,'Proto že odstoupili od něho, a žádných cest jeho nešetřili,'),
(1559905,54,18,34,28,'Aby dokázal, že připouští k sobě křik nuzného, a volání chudých že vyslýchá.'),
(1559906,54,18,34,29,'(Nebo když on spokojí, kdo znepokojí? A když skryje tvář svou, kdo jej spatří?)Tak celý národ, jako i každého člověka jednostejně,'),
(1559907,54,18,34,30,'Aby nekraloval člověk pokrytý, aby nebylo lidem ourazu.'),
(1559908,54,18,34,31,'Jistě žeť k Bohu silnému raději toto mluveno býti má: Ponesuť, nezruším.'),
(1559909,54,18,34,32,'Mimo to, nevidím-li čeho, ty vyuč mne; jestliže jsem nepravost páchal, neučiním toho víc.'),
(1559910,54,18,34,33,'Nebo zdali vedlé tvého zdání odplacovati má, že bys ty toho neliboval, že bys ono zvoloval, a ne on? Pakli co víš jiného, mluv.'),
(1559911,54,18,34,34,'Muži rozumní se mnou řeknou, i každý moudrý poslouchaje mne,'),
(1559912,54,18,34,35,'Že Job hloupě mluví, a slova jeho nejsou rozumná.'),
(1559913,54,18,34,36,'Ó by zkušen byl Job dokonale, pro odmlouvání nám jako lidem nepravým,'),
(1559914,54,18,34,37,'Poněvadž k hříchu svému přidává i nešlechetnost, mezi námi také jen chloubu svou vynáší, a rozmnožuje řeči své proti Bohu.'),
(1559915,54,18,35,1,'Ještě mluvil Elihu, a řekl:'),
(1559916,54,18,35,2,'Domníváš-liž se, že jsi to s soudem řekl: Spravedlnost má převyšuje Boží?'),
(1559917,54,18,35,3,'Nebo jsi řekl: Co mi prospěje, jaký užitek budu míti, bych i nehřešil?'),
(1559918,54,18,35,4,'Já odpovím tobě místně, i tovaryšům tvým s tebou.'),
(1559919,54,18,35,5,'Pohleď na nebe a viz, anobrž spatř oblaky, vyšší, než-lis ty.'),
(1559920,54,18,35,6,'Jestliže bys hřešil, co svedeš proti němu? A byť se i rozmnožily nešlechetnosti tvé, co mu uškodíš?'),
(1559921,54,18,35,7,'Budeš-li spravedlivý, čeho mu udělíš? Aneb co z ruky tvé vezme?'),
(1559922,54,18,35,8,'Každémuť člověku bezbožnost jeho uškodí, a synu člověka spravedlnost jeho prospěje.'),
(1559923,54,18,35,9,'Z množství nátisk trpících, kteréž k tomu přivodí, aby úpěli a křičeli pro ukrutnost povýšených,'),
(1559924,54,18,35,10,'Žádný neříká: Kde jest Bůh stvořitel můj? Ješto on dává zpěv i v noci.'),
(1559925,54,18,35,11,'On vyučuje nás nad hovada zemská, a nad ptactvo nebeské moudřejší nás činí.'),
(1559926,54,18,35,12,'Tehdáž volají-li pro pýchu zlých, nebývají vyslyšáni.'),
(1559927,54,18,35,13,'A jistě žeť ošemetnosti nevyslýchá Bůh silný, a Všemohoucí nepatří na ni.'),
(1559928,54,18,35,14,'Mnohem méně, jestliže díš: Nepatříš na to. Sám s sebou vejdi v soud před ním, a doufej v něho.'),
(1559929,54,18,35,15,'Ale nyní poněvadž nic není těch věcí, navštívil jej hněv jeho; nebo nechce znáti hojnosti této veliké.'),
(1559930,54,18,35,16,'A protož marně Job otvírá ústa svá, hloupě rozmnožuje řeči své.'),
(1559931,54,18,36,1,'Zatím přidal Elihu, a řekl:'),
(1559932,54,18,36,2,'Postrp mne maličko, a oznámímť šíře; neboť mám ještě, co bych za Boha mluvil.'),
(1559933,54,18,36,3,'Vynesu smysl svůj zdaleka, a stvořiteli svému přivlastním spravedlnost.'),
(1559934,54,18,36,4,'V pravdě, žeť nebudou lživé řeči mé; zdravě smýšlejícího máš mne s sebou.'),
(1559935,54,18,36,5,'Aj, Bůh silný mocný jest, aniž svých zamítá; silný jest, a srdce udatného.'),
(1559936,54,18,36,6,'Neobživuje bezbožného, chudým pak k soudu dopomáhá.'),
(1559937,54,18,36,7,'Neodvrací od spravedlivého očí svých, nýbrž s králi na stolici sází je na věky, i bývají zvýšeni.'),
(1559938,54,18,36,8,'Pakli by poutami sevříni byli, zapleteni jsouce provazy ssoužení:'),
(1559939,54,18,36,9,'Tudy jim v známost uvodí hřích jejich, a že přestoupení jejich se ssilila.'),
(1559940,54,18,36,10,'A tak otvírá sluch jejich, aby se napravili, anobrž mluví jim, aby se navrátili od nepravosti.'),
(1559941,54,18,36,11,'Uposlechnou-li a budou-li jemu sloužiti, stráví dny své v dobrém, a léta svá v potěšení.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559942,54,18,36,12,'Pakli neuposlechnou, od meče sejdou, a pozdychají bez umění.'),
(1559943,54,18,36,13,'Nebo kteříž jsou nečistého srdce, přivětšují hněvu, aniž k němu volají, když by je ssoužil.'),
(1559944,54,18,36,14,'Protož umírá v mladosti duše jejich, a život jejich s smilníky.'),
(1559945,54,18,36,15,'Vytrhuje, pravím, ssouženého z jeho ssoužení, a ty, jejichž sluch otvírá, v trápení.'),
(1559946,54,18,36,16,'A tak by i tebe přenesl z prostředku úzkosti na širokost, kdež není stěsnění, a byl by pokojný stůl tvůj tukem oplývající.'),
(1559947,54,18,36,17,'Ale ty zasloužils, abys jako bezbožný souzen byl; soud a právo na tě dochází.'),
(1559948,54,18,36,18,'Jistě strach, aby tě neuvrhl Bůh u větší ránu, tak že by jakkoli veliká výplaty mzda, tebe nevyprostila.'),
(1559949,54,18,36,19,'Zdaliž by sobě co vážil bohatství tvého? Jistě ani nejvýbornějšího zlata, ani jakékoli síly neb moci tvé.'),
(1559950,54,18,36,20,'Nechvátejž tedy k noci, v kterouž odcházejí lidé na místo své.'),
(1559951,54,18,36,21,'Hleď, abys se neohlédal na marnost, zvoluje ji raději, nežli ssoužení.'),
(1559952,54,18,36,22,'Aj, Bůh silný nejvyšší jest mocí svou. Kdo jemu podobný učitel?'),
(1559953,54,18,36,23,'Kdo jemu vyměřil cestu jeho? Kdo jemu smí říci: Činíš nepravost?'),
(1559954,54,18,36,24,'Pamětliv buď raději, abys vyvyšoval dílo jeho, kteréž spatřují lidé,'),
(1559955,54,18,36,25,'Kteréž, pravím, všickni lidé vidí, na něž člověk patří zdaleka.'),
(1559956,54,18,36,26,'Nebo Bůh silný tak jest veliký, že ho nemůžeme poznati, počet let jeho jest nevystižitelný.'),
(1559957,54,18,36,27,'On zajisté vyvodí krůpěje vod, kteréž vylévají déšť z oblaků jeho,'),
(1559958,54,18,36,28,'Když se rozpouštějí oblakové, a kropí na mnohé lidi.'),
(1559959,54,18,36,29,'(Anobrž vyrozumí-li kdo roztažení oblaků, a zvuku stánku jeho,'),
(1559960,54,18,36,30,'Jak rozprostírá nad ním světlo své, aneb všecko moře přikrývá?'),
(1559961,54,18,36,31,'Skrze ty věci zajisté tresce lidi, a též dává pokrmu hojnost.'),
(1559962,54,18,36,32,'Oblaky zakrývá světlo, a přikazuje mu ukrývati se za to, co je potkává.)'),
(1559963,54,18,36,33,'Ohlašuje o něm zvuk jeho, též dobytek, a to hned, když pára zhůru vstupuje.'),
(1559964,54,18,36,34,'Takéť se i nad tím děsí srdce mé, až se pohybuje z místa svého.'),
(1559965,54,18,37,1,'Poslouchejte pilně hřmotného hlasu jeho, a zvuku z úst jeho pocházejícího.'),
(1559966,54,18,37,2,'Pode všecka nebesa jej rozprostírá, a světlo své k krajům země.'),
(1559967,54,18,37,3,'Za nímž zvučí hlukem, a hřímá hlasem důstojnosti své, aniž mešká s jinými věcmi, když se slýchá hlas jeho.'),
(1559968,54,18,37,4,'Bůh silný hřímá hlasem svým předivně, činí veliké věci, a však nemůžeme rozuměti, jak.'),
(1559969,54,18,37,5,'Sněhu zajisté říká: Buď na zemi, tolikéž pršce dešťové, ano i přívalu násilnému.'),
(1559970,54,18,37,6,'Zavírá ruku všelikého člověka, aby žádný z lidí nemohl konati díla svého.'),
(1559971,54,18,37,7,'Tehdáž i zvěř vchází do skrýše, a v peleších svých obývá.'),
(1559972,54,18,37,8,'Z skrýše vychází vichřice, a od půlnoční strany zima.'),
(1559973,54,18,37,9,'Dchnutím Bůh silný dává mráz, až se široké vody zavírají.'),
(1559974,54,18,37,10,'Také i při svlažování země pohybuje oblakem, a rozhání mračno světlem svým.'),
(1559975,54,18,37,11,'A tentýž sem i tam obrací se moudrostí jeho, aby činil, což by mu koli přikázal na tváři okršlku zemského.'),
(1559976,54,18,37,12,'Buď k trestání, neb pro zemi svou, buď k prokazování dobrotivosti, spraví to, že se postaví.'),
(1559977,54,18,37,13,'Pozorujž toho, Jobe, zastav se a podívej se divům Boha silného.'),
(1559978,54,18,37,14,'Víš-li, kdy Bůh ukládá co o těch věcech, aneb kdy chce osvěcovati světlem oblaky své?'),
(1559979,54,18,37,15,'Znáš-li, jak se vznášejí oblakové, a jiné divy dokonalého v uměních?'),
(1559980,54,18,37,16,'A že tě roucho tvé zahřívati bude, když Bůh zemi pokojnou činí větry poledními?'),
(1559981,54,18,37,17,'Roztahoval-li jsi s ním nebesa trvánlivá, k zrcadlu slitému podobná?'),
(1559982,54,18,37,18,'Poukaž nám, co bychom řekli jemu; nebo nemůžeme ani řeči zpořádati pro temnost.'),
(1559983,54,18,37,19,'Zdaž jemu kdo oznámí, co bych já mluvil? Pakli by kdo za mne mluvil, jistě že by byl sehlcen.'),
(1559984,54,18,37,20,'Ano nyní nemohou patřiti lidé na světlo, když jest jasné na oblacích, když je vítr prochází a vyčišťuje,'),
(1559985,54,18,37,21,'Od půlnoční strany s jasnem jako zlato přicházeje, ale v Bohu hroznější jest sláva.'),
(1559986,54,18,37,22,'Všemohoucí, jehož vystihnouti nemůžeme, ač jest veliký v moci, však soudem a přísnou spravedlností netrápí.'),
(1559987,54,18,37,23,'Protož bojí se ho lidé; neohlédá se na žádného z těch, kdož jsou moudrého srdce.'),
(1559988,54,18,38,1,'Tedy odpověděl Hospodin Jobovi z vichru, a řekl:'),
(1559989,54,18,38,2,'Kdož jest to, jenž zatemňuje radu řečmi neumělými?'),
(1559990,54,18,38,3,'Přepaš nyní jako muž bedra svá, a nač se tebe tázati budu, oznam mi.'),
(1559991,54,18,38,4,'Kdes byl, když jsem zakládal zemi? Pověz, jestliže máš rozum.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1559992,54,18,38,5,'Kdo rozměřil ji, víš-li? Aneb kdo vztáhl pravidlo na ni?'),
(1559993,54,18,38,6,'Na čem podstavkové její upevněni jsou? Aneb kdo založil úhelný kámen její,'),
(1559994,54,18,38,7,'Když prozpěvovaly spolu hvězdy jitřní, a plésali všickni synové Boží?'),
(1559995,54,18,38,8,'Aneb kdo zavřel jako dveřmi moře, když vyšlo z života, a zjevilo se?'),
(1559996,54,18,38,9,'Když jsem mu položil oblak za oděv, a mrákotu místo plének jeho,'),
(1559997,54,18,38,10,'Když jsem jemu uložil úsudek svůj, přistaviv závory a dvéře,'),
(1559998,54,18,38,11,'I řekl jsem: Až potud vycházeti budeš, a dále nic, tu, pravím, skládati budeš dutí vlnobití svého.'),
(1559999,54,18,38,12,'Zdaž jsi kdy za dnů svých rozkázal jitru? Ukázal-lis záři jitřní místo její,'),
(1560000,54,18,38,13,'Aby uchvacovala kraje země, a bezbožní aby z ní vymítáni byli?'),
(1560001,54,18,38,14,'Tak aby proměnu přijímala jako vosk pečetní, oni pak aby nedlouho stáli jako roucho,'),
(1560002,54,18,38,15,'A aby bezbožným zbraňováno bylo světla jejich, a rámě vyvýšené zlámáno bylo?'),
(1560003,54,18,38,16,'Přišel-lis až k hlubinám mořským? A u vnitřnosti propasti chodil-lis?'),
(1560004,54,18,38,17,'Jsou-li tobě zjeveny brány smrti? A brány stínu smrti viděl-lis?'),
(1560005,54,18,38,18,'Shlédl-lis širokosti země? Oznam, jestliže ji znáš všecku.'),
(1560006,54,18,38,19,'Která jest cesta k obydlí světla, a které místo temností,'),
(1560007,54,18,38,20,'Že bys je pojal v meze jeho, poněvadž bys srozumíval stezkám domu jeho?'),
(1560008,54,18,38,21,'Věděl-lis tehdáž, že jsi měl se naroditi, a počet dnů tvých jak veliký býti má?'),
(1560009,54,18,38,22,'Přišel-lis až ku pokladům sněhu? A poklady krupobití viděl-lis,'),
(1560010,54,18,38,23,'Kteréž chovám k času ssoužení, ke dni bitvy a boje?'),
(1560011,54,18,38,24,'Kterými se cestami rozděluje světlo, kteréž rozhání východní vítr po zemi?'),
(1560012,54,18,38,25,'Kdo rozdělil povodní tok, a cestu blýskání hromovému,'),
(1560013,54,18,38,26,'Tak aby pršel déšť i na tu zemi, kdež není lidí, na poušť, kdež není člověka,'),
(1560014,54,18,38,27,'Aby zapájel místa planá a pustá, a k zrůstu přivodil trávu mladistvou?'),
(1560015,54,18,38,28,'Má-liž déšť otce? A kdo plodí krůpěje rosy?'),
(1560016,54,18,38,29,'Z čího života vychází mráz? A jíní nebeské kdo plodí?'),
(1560017,54,18,38,30,'Až i vody jako v kámen se proměňují, a svrchek propasti zamrzá.'),
(1560018,54,18,38,31,'Zdali zavázati můžeš rozkoše Kuřátek, aneb stahování Orionovo rozvázati?'),
(1560019,54,18,38,32,'Můžeš-li vyvoditi hvězdy polední v čas jistý, aneb Arktura s syny jeho povedeš-li?'),
(1560020,54,18,38,33,'Znáš-li řád nebes? Můžeš-li spravovati panování jejich na zemi?'),
(1560021,54,18,38,34,'Můžeš-li pozdvihnouti k oblaku hlasu svého, aby hojnost vod přikryla tebe?'),
(1560022,54,18,38,35,'Ty-liž vypustíš blýskání, aby vycházela? Zdaliž řeknou tobě: Aj teď jsme?'),
(1560023,54,18,38,36,'Kdo složil u vnitřnostech lidských moudrost? Aneb kdo dal rozumu stižitelnost?'),
(1560024,54,18,38,37,'Kdo vypravovati bude o nebesích moudře? A láhvice nebeské kdo nastrojuje,'),
(1560025,54,18,38,38,'Aby svlažená země zase stuhnouti mohla, a hrudy se v hromadě držely?'),
(1560026,54,18,38,39,'Honíš-liž ty lvu loupež? A hltavost lvíčat naplňuješ-liž,'),
(1560027,54,18,38,40,'Když se stulují v peleších svých, ustavičně z skrýší čihajíce?'),
(1560028,54,18,38,41,'Kdo připravuje krkavci pokrm jeho, když mladí jeho k Bohu silnému volají, a toulají se sem i tam pro nedostatek pokrmu?'),
(1560029,54,18,39,1,'Víš-li, kterého času rodí kamsíkové, a laň ku porodu pracující spatřil-lis?'),
(1560030,54,18,39,2,'Máš-li v počtu měsíce, kteréž vyplňují? Znáš-li, pravím, čas porodu jejich?'),
(1560031,54,18,39,3,'Jak se kladou, plod svůj utiskají, a s bolestí ho pozbývají?'),
(1560032,54,18,39,4,'Jak se zmocňují mladí jejich, i odchovávají picí polní, a vycházejíce, nenavracují se k nim?'),
(1560033,54,18,39,5,'Kdo propustil zvěř, aby byla svobodná? A řemení divokého osla kdo rozvázal?'),
(1560034,54,18,39,6,'Jemuž jsem dal pustinu místo domu jeho, a místo příbytku jeho zemi slatinnou.'),
(1560035,54,18,39,7,'Posmívá se hluku městskému, a na křikání toho, kdož by jej honil, nic nedbá.'),
(1560036,54,18,39,8,'To, což nachází v horách, jest pastva jeho; nebo toliko zeliny hledá.'),
(1560037,54,18,39,9,'Svolí-liž jednorožec, aby tobě sloužil, a u jeslí tvých aby nocoval?'),
(1560038,54,18,39,10,'Připřáhneš-liž provazem jednorožce k orání? Bude-liž vláčeti brázdy za tebou?'),
(1560039,54,18,39,11,'Zdaž se na něj ubezpečíš, proto že jest veliká síla jeho, a poručíš jemu svou práci?'),
(1560040,54,18,39,12,'Zdaž se jemu dověříš, že sveze semeno tvé, a na humno tvé shromáždí?'),
(1560041,54,18,39,13,'Ty-lis dal pávům křídlo pěkné, aneb péro čápu neb pstrosu?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560042,54,18,39,14,'A že opouští na zemi vejce svá, ačkoli je v prachu osedí,'),
(1560043,54,18,39,15,'Nic nemysle, že by je noha potlačiti, aneb zvěř polní pošlapati mohla?'),
(1560044,54,18,39,16,'Tak se zatvrzuje k mladým svým, jako by jich neměl; jako by neužitečná byla práce jeho, tak jest bez starosti.'),
(1560045,54,18,39,17,'Nebo nedal jemu Bůh moudrosti, aniž mu udělil rozumnosti.'),
(1560046,54,18,39,18,'Časem svým zhůru se vznášeje, posmívá se koni i jezdci jeho.'),
(1560047,54,18,39,19,'Zdaž ty dáti můžeš koni sílu? Ty-li ozdobíš šíji jeho řehtáním?'),
(1560048,54,18,39,20,'Zdali jej zastrašíš jako kobylku? Anobrž frkání chřípí jeho strašlivé jest.'),
(1560049,54,18,39,21,'Kopá důl, a pléše v síle své, vycházeje vstříc i zbroji.'),
(1560050,54,18,39,22,'Směje se strachu, aniž se leká, aniž ustupuje zpátkem před ostrostí meče,'),
(1560051,54,18,39,23,'Ač i toul na něm chřestí, a blyští se dřevce a kopí.'),
(1560052,54,18,39,24,'S hřmotem a s hněvem kopá zemi, aniž pokojně stojí k zvuku trouby.'),
(1560053,54,18,39,25,'Anobrž k zvuku trouby řehce, a zdaleka cítí boj, hluk knížat a prokřikování.'),
(1560054,54,18,39,26,'Zdali podlé rozumu tvého létá jestřáb, roztahuje křídla svá na poledne?'),
(1560055,54,18,39,27,'Zdali k rozkazu tvému zhůru se vznáší orlice, a vysoko se hnízdí?'),
(1560056,54,18,39,28,'Na skále přebývá, přebývá na špičaté skále jako na hradě,'),
(1560057,54,18,39,29,'Odkudž hledá pokrmu, kterýž z daleka očima svýma spatřuje.'),
(1560058,54,18,39,30,'Ano i mladí její střebí krev, a kde těla mrtvá, tu i ona jest.'),
(1560059,54,18,39,31,'A tak odpovídaje Hospodin Jobovi, řekl:'),
(1560060,54,18,39,32,'Zdali hádající se s Všemohoucím obviní jej? Kdo chce viniti Boha, nechť odpoví na to.'),
(1560061,54,18,39,33,'Tehdy odpověděl Job Hospodinu a řekl:'),
(1560062,54,18,39,34,'Aj, chaternýť jsem, což bych odpovídal tobě? Ruku svou kladu na ústa svá.'),
(1560063,54,18,39,35,'Jednou jsem mluvil, ale nebudu již odmlouvati, nýbrž i podruhé, ale nebudu více přidávati.'),
(1560064,54,18,40,1,'Ještě odpovídaje Hospodin z vichru Jobovi, i řekl:'),
(1560065,54,18,40,2,'Přepaš nyní jako muž bedra svá, a nač se tebe tázati budu, oznam mi.'),
(1560066,54,18,40,3,'Zdaliž pak i soud můj zrušiti chceš? Což mne odsoudíš, jen abys se sám ospravedlnil?'),
(1560067,54,18,40,4,'Čili máš rámě jako Bůh silný, a hlasem jako on hřímáš?'),
(1560068,54,18,40,5,'Ozdobiž se nyní vyvýšeností a důstojností, v slávu a okrasu oblec se.'),
(1560069,54,18,40,6,'Rozprostři prchlivost hněvu svého, a pohleď na všelikého pyšného, a sniž ho.'),
(1560070,54,18,40,7,'Pohleď, pravím, na všelikého pyšného, a sehni jej, anobrž setři bezbožné na místě jejich.'),
(1560071,54,18,40,8,'Skrej je v prachu spolu, tvář jejich zavěž v skrytě.'),
(1560072,54,18,40,9,'A tak i já budu tě oslavovati, že tě zachovává pravice tvá.'),
(1560073,54,18,40,10,'Aj, hle slon, jejž jsem jako i tebe učinil, trávu jí jako vůl.'),
(1560074,54,18,40,11,'Aj, hle moc jeho v bedrách jeho, a síla jeho v pupku břicha jeho.'),
(1560075,54,18,40,12,'Jak chce, ohání ocasem svým, ačkoli jest jako cedr; žily lůna jeho jako ratolesti jsou spletené.'),
(1560076,54,18,40,13,'Kosti jeho jako trouby měděné, hnátové jeho jako sochor železný.'),
(1560077,54,18,40,14,'Onť jest přední z účinků Boha silného, učinitel jeho sám na něj doložiti může meč svůj.'),
(1560078,54,18,40,15,'Hory zajisté přinášejí mu pastvu, a všecka zvěř polní hrá tam.'),
(1560079,54,18,40,16,'V stínu léhá, v soukromí mezi třtím a bahnem.'),
(1560080,54,18,40,17,'Dříví stín dávající stínem svým jej přikrývá, a vrbí potoční obkličuje jej.'),
(1560081,54,18,40,18,'Aj, zadržuje řeku tak, že nemůže pospíchati; tuší sobě, že požře Jordán v ústa svá.'),
(1560082,54,18,40,19,'Zdaž kdo před očima jeho polapí jej, aneb provazy protáhne chřípě jeho?'),
(1560083,54,18,40,20,'Vytáhneš-liž velryba udicí, aneb provazem pohříženým až k jazyku jeho?'),
(1560084,54,18,40,21,'Zdali dáš kroužek na chřípě jeho, aneb hákem probodneš čelist jeho?'),
(1560085,54,18,40,22,'Zdaž se obrátí k tobě s prosbami, aneb mluviti bude tobě lahodně?'),
(1560086,54,18,40,23,'Učiní-liž smlouvu s tebou? Přijmeš-liž jej za služebníka věčného?'),
(1560087,54,18,40,24,'Zdaž budeš s ním hráti jako s ptáčkem, aneb přivážeš jej dětem svým?'),
(1560088,54,18,40,25,'Přistrojí-liž sobě hody z něho společníci, a rozdělí-liž jej mezi kupce?'),
(1560089,54,18,40,26,'Zdaž naplníš háky kůži jeho, a vidlicemi rybářskými hlavu jeho?'),
(1560090,54,18,40,27,'Vztáhni jen na něj ruku svou, a neučiníš zmínky o boji.'),
(1560091,54,18,40,28,'Aj, naděje o polapení jeho mylná jest. Zdaž i k spatření jeho člověk nebývá poražen?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560092,54,18,41,1,'Není žádného tak smělého, kdo by jej zbudil, kdož tedy postaví se přede mnou?'),
(1560093,54,18,41,2,'Kdo mne čím předšel, abych se jemu odplacel? Cožkoli jest pode vším nebem, mé jest.'),
(1560094,54,18,41,3,'Nebudu mlčeti o údech jeho, a o síle výborného sformování jeho.'),
(1560095,54,18,41,4,'Kdo odkryl svrchek oděvu jeho? S dvojitými udidly svými kdo k němu přistoupí?'),
(1560096,54,18,41,5,'Vrata úst jeho kdo otevře? Okolo zubů jeho jest hrůza.'),
(1560097,54,18,41,6,'Šupiny jeho pevné jako štítové sevřené velmi tuze.'),
(1560098,54,18,41,7,'Jedna druhé tak blízko jest, že ani vítr nevchází mezi ně.'),
(1560099,54,18,41,8,'Jedna druhé se přídrží, a nedělí se.'),
(1560100,54,18,41,9,'Od kýchání jeho zažžehá se světlo, a oči jeho jsou jako záře svitání.'),
(1560101,54,18,41,10,'Z úst jeho jako pochodně vycházejí, a jiskry ohnivé vyskakují.'),
(1560102,54,18,41,11,'Z chřípí jeho vychází dým, jako z kotla vroucího aneb hrnce.'),
(1560103,54,18,41,12,'Dýchání jeho uhlí rozpaluje, a plamen z úst jeho vychází.'),
(1560104,54,18,41,13,'V šíji jeho přebývá síla, a před ním utíká žalost.'),
(1560105,54,18,41,14,'Kusové masa jeho drží se spolu; celistvé jest v něm, aniž se rozdrobuje.'),
(1560106,54,18,41,15,'Srdce jeho tuhé jest jako kámen, tak tuhé, jako úlomek zpodního žernovu.'),
(1560107,54,18,41,16,'Vyskýtání jeho bojí se nejsilnější, až se strachem i vyčišťují.'),
(1560108,54,18,41,17,'Meč stihající jej neostojí, ani kopí, šíp neb i pancíř.'),
(1560109,54,18,41,18,'Pokládá železo za plevy, ocel za dřevo shnilé.'),
(1560110,54,18,41,19,'Nezahání ho střela, v stéblo obrací se jemu kamení prakové.'),
(1560111,54,18,41,20,'Za stéblo počítá střelbu, a posmívá se šermování kopím.'),
(1560112,54,18,41,21,'Pod ním ostré střepiny, stele sobě na věci špičaté jako na blátě.'),
(1560113,54,18,41,22,'Působí, aby vřelo v hlubině jako v kotle, a kormoutilo se moře jako v moždíři.'),
(1560114,54,18,41,23,'Za sebou patrnou činí stezku, až sezdá, že propast má šediny.'),
(1560115,54,18,41,24,'Žádného není na zemi jemu podobného, aby tak učiněn byl bez strachu.'),
(1560116,54,18,41,25,'Cokoli vysokého jest, za nic pokládá, jest králem nade všemi šelmami.'),
(1560117,54,18,42,1,'Tedy odpovídaje Job Hospodinu, řekl:'),
(1560118,54,18,42,2,'Vím, že všecko můžeš, a že nemůže překaženo býti tvému myšlení.'),
(1560119,54,18,42,3,'Kdo jest to ten, ptáš se, ješto zatemňuje radu Boží tak hloupě? Protož přiznávám se, že jsem tomu nerozuměl. Divnějšíť jsou ty věci nad mou stižitelnost, anižť jich mohu poznati.'),
(1560120,54,18,42,4,'Vyslýchejž, prosím, když bych koli mluvil; když bych se tebe tázal, oznamuj mi.'),
(1560121,54,18,42,5,'Tolikoť jsem slýchal o tobě, nyní pak i oko mé tě vidí.'),
(1560122,54,18,42,6,'Pročež mrzí mne to, a želím toho v prachu a v popele.'),
(1560123,54,18,42,7,'Stalo se pak, když odmluvil Hospodin slova ta k Jobovi, že řekl Hospodin Elifazovi Temanskému: Rozpálil se hněv můj proti tobě, a proti dvěma přátelům tvým, proto že jste nemluvili o mně toho, což pravého jest, tak jako služebník můj Job.'),
(1560124,54,18,42,8,'Protož nyní vezměte sobě sedm volků, a sedm skopců, a jděte k služebníku mému Jobovi, abyste dali obětovati obět za sebe, a služebník můj Job, aby se modlil za vás. Nebo jistě oblíčej jeho přijmu, abych neučinil s vámi podlé bláznovství vašeho; nebo nemluvili jste toho, což pravého jest, o mně, tak jako služebník můj Job.'),
(1560125,54,18,42,9,'A tak odšedše Elifaz Temanský a Bildad Suchský a Zofar Naamatský, učinili, jakž jim byl přikázal Hospodin, a přijal Hospodin oblíčej Jobův.'),
(1560126,54,18,42,10,'Navrátil také Hospodin to, což odjato bylo Jobovi, když se modlil za přátely své, tak že což měl Job, rozmnožil to Hospodin dvénásobně.'),
(1560127,54,18,42,11,'A sšedše se k němu všickni příbuzní, a všecky příbuzné jeho, a všickni známí jeho prvnější, jedli s ním chléb v domě jeho, a lítost majíce nad ním, potěšovali ho nade vším tím zlým, kteréž byl uvedl Hospodin na něj. A dali jemu jeden každý peníz jeden, a jeden každý náušnici zlatou jednu.'),
(1560128,54,18,42,12,'A tak požehnal Hospodin Jobovi k posledku více nežli v počátku jeho. Nebo měl čtrnácte tisíc ovcí, a šest tisíc velbloudů, a tisíc spřežení volů, a tisíc oslic.'),
(1560129,54,18,42,13,'Měl také sedm synů a tři dcery,'),
(1560130,54,18,42,14,'Z nichž první dal jméno Jemima, jméno pak druhé Keciha, a jméno třetí Kerenhappuch.'),
(1560131,54,18,42,15,'Aniž se nacházely ženy tak krásné, jako dcery Jobovy, ve vší té krajině; kterýmž dal otec jejich dědictví mezi bratřími jejich.'),
(1560132,54,18,42,16,'Byl pak živ Job potom sto a čtyřidceti let, a viděl syny své, a syny synů svých, až do čtvrtého pokolení.'),
(1560133,54,18,42,17,'I umřel Job, stár jsa a pln dnů.'),
(1560134,54,19,1,1,'Blahoslavený ten muž, kterýž nechodí po radě bezbožných, a na cestě hříšníků nestojí, a na stolici posměvačů nesedá.'),
(1560135,54,19,1,2,'Ale v zákoně Hospodinově jest líbost jeho, a v zákoně jeho přemýšlí dnem i nocí.'),
(1560136,54,19,1,3,'Nebo bude jako strom štípený při tekutých vodách, kterýž ovoce své vydává časem svým, jehožto list nevadne, a cožkoli činiti bude, šťastně mu se povede.'),
(1560137,54,19,1,4,'Ne takť budou bezbožní, ale jako plevy, kteréž rozmítá vítr.'),
(1560138,54,19,1,5,'A protož neostojí bezbožní na soudu, ani hříšníci v shromáždění spravedlivých.'),
(1560139,54,19,1,6,'Neboť zná Hospodin cestu spravedlivých, ale cesta bezbožných zahyne.'),
(1560140,54,19,2,1,'Proč se bouří národové, a lidé daremné věci přemyšlují?'),
(1560141,54,19,2,2,'Sstupují se králové zemští, a knížata se spolu radí proti Hospodinu, a proti pomazanému jeho,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560142,54,19,2,3,'Říkajíce: Roztrhejme svazky jejich, a zavrzme od sebe provazy jejich.'),
(1560143,54,19,2,4,'Ale ten, jenž přebývá v nebesích, směje se, Pán posmívá se jim.'),
(1560144,54,19,2,5,'Tehdáž mluviti bude k nim v hněvě svém, a v prchlivosti své předěsí je, řka:'),
(1560145,54,19,2,6,'Jáť jsem ustanovil krále svého nad Sionem, horou svatou mou.'),
(1560146,54,19,2,7,'Vypravovati budu úsudek. Hospodin řekl ke mně: Syn můj ty jsi, já dnes zplodil jsem tě.'),
(1560147,54,19,2,8,'Požádej mne, a dámť národy, dědictví tvé, a končiny země, vládařství tvé.'),
(1560148,54,19,2,9,'Roztlučeš je prutem železným, a jako nádobu hrnčířskou roztříštíš je.'),
(1560149,54,19,2,10,'A protož, králové, nyní srozumějte, vyučujte se, soudcové zemští.'),
(1560150,54,19,2,11,'Služte Hospodinu v bázni, a veselte se s třesením.'),
(1560151,54,19,2,12,'Líbejte syna, aby se nerozhněval, a zhynuli byste na cestě, jakž by se jen málo zapálil hněv jeho. Blahoslavení jsou všickni, kteříž doufají v něho.'),
(1560152,54,19,3,1,'Žalm Davidův, když utíkal před Absolonem synem svým.'),
(1560153,54,19,3,2,'Hospodine, jakť jsou mnozí nepřátelé moji! Mnozí povstávají proti mně.'),
(1560154,54,19,3,3,'Mnozí mluví o duši mé: Nemáť tento žádné pomoci v Bohu.'),
(1560155,54,19,3,4,'Ale ty, Hospodine, jsi štítem vůkol mne, slávou mou, a kterýž povyšuješ hlavy mé.'),
(1560156,54,19,3,5,'Hlasem svým volal jsem k Hospodinu, a vyslyšel mne s hory svaté své. Sélah.'),
(1560157,54,19,3,6,'Já jsem lehl, a spal jsem, i zas procítil; nebo mne zdržoval Hospodin.'),
(1560158,54,19,3,7,'Nebuduť se báti mnoha tisíců lidí, kteříž se vůkol kladou proti mně.'),
(1560159,54,19,3,8,'Povstaniž, Hospodine, zachovej mne, Bože můj, kterýž jsi zbil všech nepřátel mých líce, a zuby bezbožníků zvyrážel.'),
(1560160,54,19,3,9,'Tvéť, ó Hospodine, jest spasení, a nad lidem tvým požehnání tvé. Sélah.'),
(1560161,54,19,4,1,'Přednímu zpěváku na neginot, žalm Davidův.'),
(1560162,54,19,4,2,'Když volám, vyslyš mne, Bože spravedlnosti mé. Ty jsi mi v úzkosti prostranství způsoboval, smiluj se nade mnou, a vyslyš modlitbu mou.'),
(1560163,54,19,4,3,'Synové lidští, dokudž sláva má v potupě bude? Dlouho-liž marnost milovati a lži hledati budete? Sélah.'),
(1560164,54,19,4,4,'Vězte, žeť jest oddělil Hospodin sobě milého. Vyslyšíť mne Hospodin, když k němu volati budu.'),
(1560165,54,19,4,5,'Uleknětež se a nehřešte, přemyšlujte o tom v srdci svém, na ložci svém, a umlkněte. Sélah.'),
(1560166,54,19,4,6,'Obětujte oběti spravedlnosti, a doufejte v Hospodina.'),
(1560167,54,19,4,7,'Mnozí říkají: Ó bychom viděti mohli dobré věci. Hospodine, pozdvihni nad námi jasného oblíčeje svého,'),
(1560168,54,19,4,8,'I způsobíš radost v srdci mém větší, než oni mívají, když obilé a víno jejich se obrodí.'),
(1560169,54,19,4,9,'Jáť u pokoji i lehnu i spáti budu; nebo ty, Hospodine, sám způsobíš mi bydlení bezpečné.'),
(1560170,54,19,5,1,'Přednímu zpěváku na nechilot, žalm Davidův.'),
(1560171,54,19,5,2,'Slova má slyš, Hospodine, porozuměj tužebnému úpění mému.'),
(1560172,54,19,5,3,'Pozoruj hlasu volání mého, králi můj a Bože můj; nebo se tobě modlím.'),
(1560173,54,19,5,4,'Hospodine, v jitře vyslyšíš hlas můj, v jitře předložím tobě žádost, a šetřiti budu.'),
(1560174,54,19,5,5,'Nebo ty, ó Bože silný, neoblibuješ bezbožnosti, nemá místa u tebe nešlechetník.'),
(1560175,54,19,5,6,'Neostojí blázniví před očima tvýma, v nenávisti máš všecky činitele nepravosti.'),
(1560176,54,19,5,7,'Zatratíš mluvící lež. Člověka ukrutného a lstivého v ohavnosti má Hospodin.'),
(1560177,54,19,5,8,'Já pak ve množství milosrdenství tvého vejdu do domu tvého, klaněti se budu k svatému chrámu tvému v bázni tvé.'),
(1560178,54,19,5,9,'Hospodine, proveď mne v spravedlnosti své, pro ty, jenž mne střehou; spravuj přede mnou cestu svou.'),
(1560179,54,19,5,10,'Neboť není v ústech jejich žádné upřímnosti, vnitřnosti jejich plné nešlechetnosti, hrob otevřený hrdlo jejich, jazykem svým lahodně mluví.'),
(1560180,54,19,5,11,'Zkaz je, ó Bože, nechať padnou od rad svých; pro množství nešlechetností jejich rozptyl je, poněvadž odporní jsou tobě.'),
(1560181,54,19,5,12,'A ať se všickni v tě doufající radují, na věky ať plésají, když je zastírati budeš; ať se v tobě veselí, kteřížkoli milují jméno tvé.'),
(1560182,54,19,5,13,'Nebo ty, Hospodine, požehnáš spravedlivému, a jako štítem přívětivostí svou vůkol zastřeš jej.'),
(1560183,54,19,6,1,'Přednímu kantoru na neginot, k nízkému zpěvu, žalm Davidův.'),
(1560184,54,19,6,2,'Hospodine, netresci mne v hněvě svém, ani v prchlivosti své kárej mne.'),
(1560185,54,19,6,3,'Smiluj se nade mnou, Hospodine, neboť jsem zemdlený; uzdrav mne, Hospodine, nebo ztrnuly kosti mé.'),
(1560186,54,19,6,4,'Ano i duše má předěšena jest náramně, ty pak, Hospodine, až dokavad?'),
(1560187,54,19,6,5,'Navratiž se, Hospodine, a vytrhni duši mou; spomoz mi pro milosrdenství své.'),
(1560188,54,19,6,6,'Nebo mrtví nezpomínají na tebe, a v hrobě kdo tě bude oslavovati?'),
(1560189,54,19,6,7,'Ustávám v úpění svém, ložce své každé noci svlažuji, slzami svými postel svou smáčím.'),
(1560190,54,19,6,8,'Sškvrkla se zámutkem tvář má, sstarala se příčinou všech nepřátel mých.'),
(1560191,54,19,6,9,'Odstuptež ode mne všickni činitelé nepravosti; neboť jest vyslyšel Hospodin hlas pláče mého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560192,54,19,6,10,'Vyslyšel Hospodin pokornou modlitbu mou, Hospodin modlitbu mou přijal.'),
(1560193,54,19,6,11,'Nechažť se zastydí a předěsí zřejmě všickni nepřátelé moji, nechažť jsou zpět obráceni a rychle zahanbeni.'),
(1560194,54,19,7,1,'Osvědčení neviny Davidovy, o čemž zpíval Hospodinu z příčiny slov Chusi syna Jeminova.'),
(1560195,54,19,7,2,'Hospodine Bože můj, v toběť doufám, vysvoboď mne ode všech protivníků mých, a vytrhni mne,'),
(1560196,54,19,7,3,'Aby neuchvátil jako lev duše mé, a neroztrhal, když by nebyl, kdo by vysvobodil.'),
(1560197,54,19,7,4,'Hospodine Bože můj, učinil-li jsem to, jest-li nepravost při mně,'),
(1560198,54,19,7,5,'Činil-li jsem zle tomu, kdož se ke mně pokojně choval, (nýbrž spomáhal jsem protivícímu se mi bez příčiny),'),
(1560199,54,19,7,6,'Nechať stihá nepřítel duši mou, i popadne, a pošlapá na zemi život můj, a slávu mou v prach uvede. Sélah.'),
(1560200,54,19,7,7,'Povstaň, Hospodine, v hněvě svém, vyvyš se proti vzteklostem mých nepřátel, a prociť ke mně, nebo jsi soud nařídil.'),
(1560201,54,19,7,8,'I shrne se k tobě shromáždění lidí; pro ně tedy u výsost navrať se zase.'),
(1560202,54,19,7,9,'Hospodin souditi bude lidi. Sudiž mne, Hospodine, podlé spravedlnosti mé, a podlé nevinnosti mé, kteráž při mně jest.'),
(1560203,54,19,7,10,'Ó by již k skončení přišla nešlechetnost bezbožných, spravedlivého pak abys utvrdil ty, kterýž zkušuješ srdce a ledví, Bože spravedlivý.'),
(1560204,54,19,7,11,'Bůh jest štít můj, kterýž spaseny činí upřímé srdcem.'),
(1560205,54,19,7,12,'Bůh jest soudce spravedlivý, Bůh silný hněvá se na bezbožného každý den.'),
(1560206,54,19,7,13,'Neobrátí-li se, naostříť meč svůj; lučiště své natáhl, a naměřil je.'),
(1560207,54,19,7,14,'Připravil sobě i zbroj smrtelnou, střely své proti škůdcím přistrojil.'),
(1560208,54,19,7,15,'Aj, rodí nepravost; nebo počav těžkou bolest, urodí lež.'),
(1560209,54,19,7,16,'Jámu kopal, i vykopal ji, ale padne do dolu, kterýž přistrojil.'),
(1560210,54,19,7,17,'Obrátíť se usilování jeho na hlavu jeho, a na vrch hlavy jeho nepravost jeho sstoupí.'),
(1560211,54,19,7,18,'Slaviti budu Hospodina podlé spravedlnosti jeho, a žalmy zpívati jménu Hospodina nejvyššího.'),
(1560212,54,19,8,1,'Přednímu zpěváku na gittejský nástroj, žalm Davidův.'),
(1560213,54,19,8,2,'Hospodine Pane náš, jak důstojné jest jméno tvé na vší zemi! Nebo jsi vyvýšil slávu svou nad nebesa.'),
(1560214,54,19,8,3,'Z úst nemluvňátek a těch, jenž prsí požívají, mocně dokazuješ síly z příčiny svých nepřátel, abys přítrž učinil protivníku a vymstívajícímu se.'),
(1560215,54,19,8,4,'Když spatřuji nebesa tvá, dílo prstů tvých, měsíc a hvězdy, kteréž jsi tak upevnil, říkám:'),
(1560216,54,19,8,5,'Co jest člověk, že jsi naň pamětliv, a syn člověka, že jej navštěvuješ?'),
(1560217,54,19,8,6,'Nebo učinil jsi ho málo menšího andělů, slávou a ctí korunoval jsi jej.'),
(1560218,54,19,8,7,'Pánem jsi ho učinil nad dílem rukou svých, všecko jsi podložil pod nohy jeho:'),
(1560219,54,19,8,8,'Ovce i voly všecky, také i zvěř polní,'),
(1560220,54,19,8,9,'Ptactvo nebeské, i ryby mořské, a cožkoli chodí stezkami mořskými.'),
(1560221,54,19,8,10,'Hospodine Pane náš, jak důstojné jest jméno tvé na vší zemi!'),
(1560222,54,19,9,1,'Přednímu zpěváku na al mutlabben, žalm Davidův.'),
(1560223,54,19,9,2,'Oslavovati tě budu, Hospodine, celým srdcem svým, vypravovati budu všecky divné skutky tvé.'),
(1560224,54,19,9,3,'Radovati a veseliti se budu v tobě, žalmy zpívati budu jménu tvému, ó Nejvyšší,'),
(1560225,54,19,9,4,'Proto že nepřátelé moji jsou nazpět obráceni, že klesli, a zahynuli od tváři tvé.'),
(1560226,54,19,9,5,'Nebo jsi vyvedl soud můj a při mou, posadils se na stolici soudce spravedlivý.'),
(1560227,54,19,9,6,'Ohromil jsi národy, zatratils bezbožníka, jméno jejich vyhladil jsi na věčné věky.'),
(1560228,54,19,9,7,'Ó nepříteli, již-li jsou dokonány zhouby tvé na věky? Již-li jsi města podvrátil? Zahynula památka jejich s nimi.'),
(1560229,54,19,9,8,'Ale Hospodin na věky kraluje, připravil k soudu trůn svůj.'),
(1560230,54,19,9,9,'Onť soudí sám okršlek v spravedlnosti, a výpověd činí národům v pravosti.'),
(1560231,54,19,9,10,'Hospodin zajisté jest útočiště chudého, útočiště v čas ssoužení.'),
(1560232,54,19,9,11,'I budou v tebe doufati, kteříž znají jméno tvé; nebo neopouštíš hledajících tě, Hospodine.'),
(1560233,54,19,9,12,'Žalmy zpívejte Hospodinu, přebývajícímu na Sionu, zvěstujte mezi národy skutky jeho.'),
(1560234,54,19,9,13,'Nebo on vyhledává krve, rozpomíná se na ni, aniž se zapomíná na křik utištěných.'),
(1560235,54,19,9,14,'Smiluj se nade mnou, Hospodine, viz ssoužení mé od těch, kteříž mne nenávidí, ty, kterýž mne vyzdvihuješ z bran smrti,'),
(1560236,54,19,9,15,'Abych vypravoval všecky chvály tvé v branách dcery Sionské, a veselil se v spasení tvém.'),
(1560237,54,19,9,16,'Pohříženiť jsou národové v jámě, kterouž udělali; v osídle, kteréž polékli, uvázla noha jejich.'),
(1560238,54,19,9,17,'Přišelť jest v známost Hospodin, pomstu učiniv; v díle rukou svých zapletl se bezbožník. Higgaion Sélah.'),
(1560239,54,19,9,18,'Obráceni buďte bezbožníci do pekla, všickni národové, kteříž se zapomínají nad Bohem.'),
(1560240,54,19,9,19,'Neboť nebude dán chudý u věčné zapomenutí; očekávání ssoužených nezahyneť na věky.'),
(1560241,54,19,9,20,'Povstaniž, Hospodine, ať se nesilí člověk; národové buďte souzeni před tebou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560242,54,19,9,21,'Pusť na ně strach, ó Hospodine, ať tomu porozumějí národové, že smrtelní jsou. Sélah.'),
(1560243,54,19,10,1,'Proč, ó Hospodine, stojíš zdaleka, a skrýváš se v čas ssoužení?'),
(1560244,54,19,10,2,'Z pychu bezbožník protivenství činí chudému. Ó by jati byli v zlých radách, kteréž vymýšlejí.'),
(1560245,54,19,10,3,'Neboť se honosí bezbožník v líbostech života svého, a lakomý sobě pochlebuje, a Hospodina popouzí.'),
(1560246,54,19,10,4,'Bezbožník pro pýchu, kterouž na sobě prokazuje, nedbá na nic; všecka myšlení jeho jsou, že není Boha.'),
(1560247,54,19,10,5,'Dobře mu se daří na cestách jeho všelikého času, soudové tvoji vzdáleni jsou od něho, i na všecky nepřátely své fouká,'),
(1560248,54,19,10,6,'Říkaje v srdci svém: Nepohnuť se od národu až do pronárodu, nebo nebojím se zlého.'),
(1560249,54,19,10,7,'Ústa jeho plná jsou zlořečenství, i chytrosti a lsti; pod jazykem jeho trápení a starost.'),
(1560250,54,19,10,8,'Sedí v zálohách ve vsech a v skrýších, aby zamordoval nevinného; očima svýma po chudém špehuje.'),
(1560251,54,19,10,9,'Číhá v skrytě jako lev v jeskyni své, číhá, aby pochytil chudého, uchvacujeť jej, a táhne pod sítku svou.'),
(1560252,54,19,10,10,'Připadá a stuluje se, dokudž by nevpadlo v silné pazoury jeho shromáždění chudých.'),
(1560253,54,19,10,11,'Říká v srdci svém: Zapomenulť jest Bůh silný, skryl tvář svou, nepohledíť na věky.'),
(1560254,54,19,10,12,'Povstaniž, Hospodine Bože silný, vznes ruku svou, nezapomínejž se nad chudými.'),
(1560255,54,19,10,13,'Proč má bezbožník Boha popouzeti, říkaje v srdci svém, že toho vyhledávati nebudeš?'),
(1560256,54,19,10,14,'Díváš se do času, nebo ty nátisk a bolest spatřuješ, abys jim odplatil rukou svou; na tebeť se spouští chudý, sirotku ty jsi spomocník.'),
(1560257,54,19,10,15,'Potři rámě bezbožného, a vyhledej nepravosti zlostného, tak aby neostál.'),
(1560258,54,19,10,16,'Hospodin jest králem věčných věků, národové z země své hynou.'),
(1560259,54,19,10,17,'Žádost ponížených vyslýcháš, Hospodine, utvrzuješ srdce jejich, ucha svého k nim nakloňuješ,'),
(1560260,54,19,10,18,'Abys soud činil sirotku a ssouženému, tak aby jich nessužoval více člověk bídný a zemský.'),
(1560261,54,19,11,1,'Přednímu zpěváku, žalm Davidův. Hospodina doufám, kterakž tedy říkáte duši mé: Uleť s hory své jako ptáče?'),
(1560262,54,19,11,2,'Nebo aj, bezbožníci napínají lučiště, přikládají šípy své na tětivo, aby stříleli skrytě na upřímé srdcem.'),
(1560263,54,19,11,3,'Ale těmi usilováními zkaženi budou; nebo spravedlivý co učinil?'),
(1560264,54,19,11,4,'Hospodin jest v chrámě svatém svém, trůn Hospodinův v nebi jest; oči jeho hledí, víčka jeho zkušují synů lidských.'),
(1560265,54,19,11,5,'Hospodin zkušuje spravedlivého, bezbožníka pak a milujícího nepravost nenávidí duše jeho.'),
(1560266,54,19,11,6,'Dštíti bude na bezbožníky uhlím řeřavým, ohněm a sirou, a duch vichřice bude částka kalicha jejich.'),
(1560267,54,19,11,7,'Nebo Hospodin spravedlivý jest, spravedlnost miluje, na upřímého oči jeho patří.'),
(1560268,54,19,12,1,'Přednímu kantoru k nízkému zpěvu, žalm Davidův.'),
(1560269,54,19,12,2,'Spomoz, ó Hospodine; nebo se již nenalézá milosrdného, a vyhynuli věrní z synů lidských.'),
(1560270,54,19,12,3,'Lež mluví jeden každý s bližním svým, rty úlisnými z srdce dvojitého řeči vynášejí.'),
(1560271,54,19,12,4,'Ó by vyplénil Hospodin všeliké rty úlisné, a jazyk velikomluvný,'),
(1560272,54,19,12,5,'Kteříž říkají: Jazykem svým přemůžeme, mámeť ústa svá s sebou, kdo jest pánem naším?'),
(1560273,54,19,12,6,'Pro zhoubu chudých, pro úpění nuzných jižť povstanu, praví Hospodin, v bezpečnosti postavím toho, na nějž polečeno bylo.'),
(1560274,54,19,12,7,'Výmluvnosti Hospodinovy jsou výmluvnosti čisté, jako stříbro v hliněné peci přehnané a sedmkrát zprubované.'),
(1560275,54,19,12,8,'Ty, Hospodine, jim spomáhati budeš, a ostříhati každého od národu tohoto až na věky.'),
(1560276,54,19,12,9,'Vůkol a vůkol bezbožní se protulují, když takoví ničemní vyvýšeni bývají mezi syny lidskými.'),
(1560277,54,19,13,1,'Přednímu zpěváku, žalm Davidův.'),
(1560278,54,19,13,2,'Až dokud, Hospodine? Což se na věky zapomeneš na mne? Dokudž tvář svou skrývati budeš přede mnou?'),
(1560279,54,19,13,3,'Dokud rady vyhledávati budu v mysli své, a den ode dne svírati se v srdci svém? Až dokud se zpínati bude nepřítel můj nade mnou?'),
(1560280,54,19,13,4,'Vzhlédni, vyslyš mne, Hospodine Bože můj, osvěť oči mé, abych neusnul snem smrti,'),
(1560281,54,19,13,5,'A aby neřekl nepřítel můj: Svítězil jsem nad ním, a nepřátelé moji aby neplésali, jestliže bych se poklesl.'),
(1560282,54,19,13,6,'Jáť zajisté v milosrdenství tvém doufám, plésati bude srdce mé v spasení tvém; zpívati budu Hospodinu, že jest mi tak dobře učinil.'),
(1560283,54,19,14,1,'Přednímu zpěváku, píseň Davidova. Říká blázen v srdci svém: Není Boha. Porušeni jsou, a ohavní v snažnostech; není, kdo by činil dobré.'),
(1560284,54,19,14,2,'Hospodin s nebe popatřil na syny lidské, aby viděl, byl-li by kdo rozumný a hledající Boha.'),
(1560285,54,19,14,3,'Všickni se odvrátili, napořád neužiteční učiněni jsou; není, kdo by činil dobré, není ani jednoho.'),
(1560286,54,19,14,4,'Zdaliž nevědí všickni činitelé nepravosti, že zžírají lid můj, jako by chléb jedli? Hospodina pak nevzývají.'),
(1560287,54,19,14,5,'Tehdáž se náramně strašiti budou; nebo Bůh jest v rodině spravedlivého.'),
(1560288,54,19,14,6,'Radu chudého potupujete, ale Hospodin jest naděje jeho.'),
(1560289,54,19,14,7,'Ó by z Siona dáno bylo spasení Izraelovi. Když Hospodin zase přivede zajaté lidu svého, plésati bude Jákob, a veseliti se Izrael.'),
(1560290,54,19,15,1,'Žalm Davidův. Hospodine, kdo bude přebývati v stánku tvém? Kdo bydliti bude na hoře svaté tvé?'),
(1560291,54,19,15,2,'Ten, kdož chodí v upřímnosti, a činí spravedlnost, a mluví pravdu z srdce svého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560292,54,19,15,3,'Kdož neutrhá jazykem svým, bližnímu svému nečiní zlého, a potupy neuvodí na bližního svého.'),
(1560293,54,19,15,4,'Ten, před jehož očima v nevážnosti jest zavržený, v poctivosti pak bojící se Hospodina; a přisáhl-li by i se škodou, však toho nemění.'),
(1560294,54,19,15,5,'Kdož peněz svých nedává na lichvu, a daru proti nevinnému nebéře. Kdož tyto věci činí, nepohneť se na věky.'),
(1560295,54,19,16,1,'Zlatý zpěv Davidův. Ostříhej mne, Bože silný, neboť v tebe doufám.'),
(1560296,54,19,16,2,'Rciž, duše má, Hospodinu: Ty jsi Pán můj, dobrota má nic tobě neprospěje.'),
(1560297,54,19,16,3,'Ale svatým, kteříž jsou na zemi, a znamenitým, v nichž všecka líbost má.'),
(1560298,54,19,16,4,'Rozmnožují bolesti své ti, kteříž k cizímu bohu chvátají; neokusím obětí jejich ze krve, aniž vezmu jména jejich ve rty své.'),
(1560299,54,19,16,5,'Hospodin jest částka dílu mého a kalicha mého; ty zdržuješ los můj.'),
(1560300,54,19,16,6,'Provazcové padli mi na místech veselých, a dědictví rozkošné dostalo se mi.'),
(1560301,54,19,16,7,'Dobrořečiti budu Hospodinu, kterýž mi radí; nebo i v noci vyučují mne ledví má.'),
(1560302,54,19,16,8,'Představuji Hospodina před oblíčej svůj vždycky, a kdyžť jest mi po pravici, nikoli se nepohnu.'),
(1560303,54,19,16,9,'Z té příčiny rozveselilo se srdce mé, a zplésala sláva má, ano i tělo mé v bezpečnosti přebývati bude.'),
(1560304,54,19,16,10,'Nebo nenecháš duše mé v pekle, aniž dopustíš svatému svému viděti porušení.'),
(1560305,54,19,16,11,'Známou učiníš mi cestu života; sytost hojného veselí jest před oblíčejem tvým, a dokonalé utěšení po pravici tvé až na věky.'),
(1560306,54,19,17,1,'Modlitba Davidova. Vyslyš, Hospodine, spravedlnost, a pozoruj volání mého; nakloň uší k modlitbě mé, kteráž jest beze vší rtů ošemetnosti.'),
(1560307,54,19,17,2,'Od tváři tvé vyjdiž soud můj, oči tvé nechať patří na upřímnost.'),
(1560308,54,19,17,3,'Zkusils srdce mého, navštívils je v noci; ohněm jsi mne zpruboval, aniž jsi co shledal; to, což myslím, nepředstihá úst mých.'),
(1560309,54,19,17,4,'Z strany pak skutků lidských, já podlé slova rtů tvých vystříhal jsem se stezky zhoubce.'),
(1560310,54,19,17,5,'Zdržuj kroky mé na cestách svých, aby se neuchylovaly nohy mé.'),
(1560311,54,19,17,6,'Já volám k tobě, nebo vyslýcháš mne, ó Bože silný; nakloň ke mně ucha svého, a slyš řeč mou.'),
(1560312,54,19,17,7,'Prokaž milosrdenství svá, naději majících ochránce před těmi, kteříž povstávají proti pravici tvé.'),
(1560313,54,19,17,8,'Ostříhej mne jako zřítelnice oka, v stínu křídel svých skrej mne,'),
(1560314,54,19,17,9,'Od tváři bezbožných těch, kteříž mne hubí, od nepřátel mých úhlavních obkličujících mne,'),
(1560315,54,19,17,10,'Kteříž tukem svým zarostli, mluví pyšně ústy svými.'),
(1560316,54,19,17,11,'Jižť i kroky naše předstihají, oči své obrácené mají, aby nás porazili na zem.'),
(1560317,54,19,17,12,'Každý z nich podoben jest lvu žádostivému loupeže, a lvíčeti sedícímu v skrýši.'),
(1560318,54,19,17,13,'Povstaniž, Hospodine, předejdi tváři jeho, sehni jej, a vytrhni duši mou od bezbožníka mečem svým,'),
(1560319,54,19,17,14,'Rukou svou od lidí, ó Hospodine, od lidí světských, jichžto oddíl jest v tomto životě, a jejichž břicho ty z špižírny své naplňuješ. Čímž i synové jejich nasyceni bývají, a ostatků zanechávají maličkým svým.'),
(1560320,54,19,17,15,'Já pak v spravedlnosti spatřovati budu tvář tvou; nasycen budu obrazem tvým, když procítím.'),
(1560321,54,19,18,1,'Přednímu zpěváku, služebníka Hospodinova Davida, kterýž mluvil Hospodinu slova písně této v ten den, v němž ho vysvobodil Hospodin z ruky všech nepřátel jeho i z ruky Saulovy, a řekl:'),
(1560322,54,19,18,2,'Z vnitřnosti srdce miluji tě, Hospodine, sílo má.'),
(1560323,54,19,18,3,'Hospodin skála má a hrad můj, i vysvoboditel můj, Bůh silný můj, skála má, v němž naději skládám, štít můj a roh spasení mého, mé útočiště.'),
(1560324,54,19,18,4,'Chvály hodného vzýval jsem Hospodina, a od nepřátel svých byl jsem vyproštěn.'),
(1560325,54,19,18,5,'Obklíčilyť mne byly bolesti smrti, a proudové nešlechetných předěsili mne.'),
(1560326,54,19,18,6,'Bylyť jsou mne obklíčily bolesti hrobu, osídla smrti zachvátila mne.'),
(1560327,54,19,18,7,'V úzkosti své vzýval jsem Hospodina, a k Bohu svému volal jsem, i vyslyšel z chrámu svého hlas můj, a volání mé před oblíčejem jeho přišlo v uši jeho.'),
(1560328,54,19,18,8,'Tehdy pohnula se a zatřásla země, základové hor pohnuli se, a třásli se pro rozhněvání jeho.'),
(1560329,54,19,18,9,'Dým vystupoval z chřípí jeho, a oheň zžírající z úst jeho, od něhož se uhlí rozpálilo.'),
(1560330,54,19,18,10,'Nakloniv nebes, sstoupil, a mrákota byla pod nohami jeho.'),
(1560331,54,19,18,11,'A sedě na cherubínu, letěl, letěl na peří větrovém.'),
(1560332,54,19,18,12,'Udělal sobě z temností skrýši,vůkol sebe stánek svůj z temných vod a hustých oblaků.'),
(1560333,54,19,18,13,'Od blesku před ním oblakové jeho rozehnáni jsou, krupobití i uhlí řeřavé.'),
(1560334,54,19,18,14,'I hřímal na nebi Hospodin, a Nejvyšší vydal zvuk svůj, i krupobití a uhlí řeřavé.'),
(1560335,54,19,18,15,'Vystřelil i střely své, a rozptýlil je, a blýskáním častým porazil je.'),
(1560336,54,19,18,16,'I ukázaly se hlubiny vod, a odkryti jsou základové okršlku pro žehrání tvé, Hospodine, pro dchnutí větru chřípí tvých.'),
(1560337,54,19,18,17,'Poslav s výsosti, uchopil mne, vytáhl mne z velikých vod.'),
(1560338,54,19,18,18,'Vytrhl mne od nepřítele mého silného, a od těch, kteříž mne nenáviděli, ačkoli silnější mne byli.'),
(1560339,54,19,18,19,'Předstihliť jsou mne byli v den trápení mého, ale Hospodin byl mi podpora.'),
(1560340,54,19,18,20,'Kterýž vyvedl mne na prostranno, vytrhl mne, nebo mne sobě oblíbil.'),
(1560341,54,19,18,21,'Odplatil mi Hospodin podlé spravedlnosti mé, podlé čistoty rukou mých nahradil mi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560342,54,19,18,22,'Nebo jsem ostříhal cest Hospodinových, aniž jsem se bezbožně strhl Boha svého.'),
(1560343,54,19,18,23,'Všickni zajisté soudové jeho jsou přede mnou, a ustanovení jeho neodložil jsem od sebe.'),
(1560344,54,19,18,24,'Nýbrž upřímě choval jsem se k němu, a vystříhal jsem se nepravosti své.'),
(1560345,54,19,18,25,'Protož odplatil mi Hospodin podlé spravedlnosti mé, podlé čistoty rukou mých, kteráž jest před očima jeho.'),
(1560346,54,19,18,26,'Ty, Pane, s milosrdným milosrdně nakládáš, a k člověku upřímému upřímě se máš.'),
(1560347,54,19,18,27,'K sprostnému sprostně se ukazuješ, a s převráceným převráceně zacházíš.'),
(1560348,54,19,18,28,'Lid pak ssoužený vysvobozuješ, a oči vysoké snižuješ.'),
(1560349,54,19,18,29,'Ty zajisté rozsvěcuješ svíci mou; Hospodin Bůh můj osvěcuje temnosti mé.'),
(1560350,54,19,18,30,'Nebo v tobě proběhl jsem vojsko, a v Bohu svém přeskočil jsem i zed.'),
(1560351,54,19,18,31,'Boha tohoto silného cesta jest dokonalá, výmluvnosti Hospodinovy jsou přečištěné, onť jest štít všech, kteříž v něho doufají.'),
(1560352,54,19,18,32,'Nebo kdo jest Bohem kromě Hospodina, a kdo skalou kromě Boha našeho?'),
(1560353,54,19,18,33,'Ten Bůh silný přepasuje mne udatností, a činí dokonalou cestu mou.'),
(1560354,54,19,18,34,'Činí nohy mé jako laní, a na vysokostech mých postavuje mne.'),
(1560355,54,19,18,35,'Učí ruce mé boji, tak že lámi i lučiště ocelivé rukama svýma.'),
(1560356,54,19,18,36,'Tys mi také dodal štítu spasení svého, a pravice tvá podpírala mne, a dobrotivost tvá mne zvelebila.'),
(1560357,54,19,18,37,'Rozšířil jsi krokům mým místo pode mnou, a nepodvrtly se nohy mé.'),
(1560358,54,19,18,38,'Honil jsem nepřátely své, a postihl jsem je, aniž jsem se navrátil, až jsem je vyhubil.'),
(1560359,54,19,18,39,'Tak jsem je zranil, že nemohli povstati, padše pod nohy mé.'),
(1560360,54,19,18,40,'Ty jsi zajisté mne přepásal udatností k boji, povstávající proti mně sehnul jsi pode mne.'),
(1560361,54,19,18,41,'Nýbrž dals mi šíji nepřátel mých, abych ty, kteříž mne nenáviděli, vyplénil.'),
(1560362,54,19,18,42,'Volaliť jsou, ale nebylo spomocníka k Hospodinu, ale nevyslyšel jich.'),
(1560363,54,19,18,43,'I potřel jsem je jako prach u povětří, jako bláto na ulicích rozšlapal jsem je.'),
(1560364,54,19,18,44,'Ty jsi mne vyprostil z různic lidu, a postavils mne v hlavu národům; lid, kteréhož jsem neznal, sloužil mi.'),
(1560365,54,19,18,45,'Jakž jen zaslechli, uposlechli mne, cizozemci lhali mi.'),
(1560366,54,19,18,46,'Cizozemci svadli a třásli se v ohradách svých.'),
(1560367,54,19,18,47,'Živť jest Hospodin, a požehnaná skála má; protož buď vyvyšován Bůh spasení mého,'),
(1560368,54,19,18,48,'Bůh silný, kterýž mi pomsty poroučí, a podmaňuje mi lidi.'),
(1560369,54,19,18,49,'Ty jsi vysvoboditel můj z moci nepřátel mých, také i nad povstávající proti mně vyvýšils mne, a od člověka ukrutného vyprostils mne.'),
(1560370,54,19,18,50,'A protož chváliti tě budu mezi národy, ó Hospodine, a jménu tvému žalmy prozpěvovati,'),
(1560371,54,19,18,51,'Kterýž tak důstojně vysvobozuješ krále svého, a činíš milosrdenství pomazanému svému Davidovi, i semeni jeho až na věky.'),
(1560372,54,19,19,1,'Přednímu z kantorů, žalm Davidův.'),
(1560373,54,19,19,2,'Nebesa vypravují slávu Boha silného, a dílo rukou jeho obloha zvěstuje.'),
(1560374,54,19,19,3,'Den po dni vynáší řeč, a noc po noci ukazuje umění.'),
(1560375,54,19,19,4,'Neníť řeči ani slov, kdež by nemohl slyšán býti hlas jejich.'),
(1560376,54,19,19,5,'Po vší zemi rozchází se zpráva jejich, a až do končin okršlku slova jich, slunci pak rozbil stánek na nich.'),
(1560377,54,19,19,6,'Kteréž jako ženich vychází z pokoje svého, veselí se jako udatný rek, cestou běžeti maje.'),
(1560378,54,19,19,7,'Od končin nebes východ jeho, a obcházení jeho až zase do končin jejich, a ničeho není, což by se ukryti mohlo před horkostí jeho.'),
(1560379,54,19,19,8,'Zákon Hospodinův jest dokonalý, očerstvující duši, Hospodinovo svědectví pravé, moudrost dávající neumělým.'),
(1560380,54,19,19,9,'Rozkazové Hospodinovi přímí, obveselující srdce, přikázaní Hospodinovo čisté, osvěcující oči.'),
(1560381,54,19,19,10,'Bázeň Hospodinova čistá, zůstávající na věky, soudové Hospodinovi praví, a k tomu i spravedliví.'),
(1560382,54,19,19,11,'Mnohem žádostivější jsou než zlato, a než mnoho ryzího zlata, sladší než med a stred z plástů.'),
(1560383,54,19,19,12,'Služebník tvůj zajisté jimi osvěcován bývá, a kdož jich ostříhá, užitek hojný má.'),
(1560384,54,19,19,13,'Ale poblouzením kdo vyrozumí? Protož i od tajných očisť mne.'),
(1560385,54,19,19,14,'I od zúmyslných zdržuj služebníka svého, aby nade mnou nepanovali, a tehdyť dokonalý budu, a očištěný od přestoupení velikého.'),
(1560386,54,19,19,15,'Ó ať jsou slova úst mých tobě příjemná, i přemyšlování srdce mého před tebou, Hospodine skálo má, a vykupiteli můj.'),
(1560387,54,19,20,1,'Přednímu zpěváku, žalm Davidův.'),
(1560388,54,19,20,2,'Vyslyšiž tě Hospodin v den ssoužení, k zvýšení tě přiveď jméno Boha Jákobova.'),
(1560389,54,19,20,3,'Sešliž tobě pomoc z svatyně, a z Siona utvrzuj tě.'),
(1560390,54,19,20,4,'Rozpomeniž se na všecky oběti tvé, a zápaly tvé v popel obrať. Sélah.'),
(1560391,54,19,20,5,'Dejž tobě vše podlé srdce tvého, a všelikou radu tvou vyplň.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560392,54,19,20,6,'I budeme prozpěvovati o spasení tvém, a ve jménu Boha našeho korouhve vyzdvihneme; naplniž Hospodin všecky prosby tvé.'),
(1560393,54,19,20,7,'Nyníť jsme poznali, že Hospodin zachoval svého pomazaného, a že jej vyslyšel s nebe svatého svého; nebo v jeho přesilné pravici jest spasení.'),
(1560394,54,19,20,8,'Tito v vozích, jiní v koních doufají, ale my jméno Hospodina Boha našeho sobě připomínáme.'),
(1560395,54,19,20,9,'A protož oni sehnuti jsou, a padli, ale my povstali jsme, a zmužile stojíme.'),
(1560396,54,19,20,10,'Hospodine, zachovávejž nás, i král ať slyší nás, když k němu volati budeme.'),
(1560397,54,19,21,1,'Přednímu z kantorů, žalm Davidův.'),
(1560398,54,19,21,2,'Hospodine, v síle tvé raduje se král, a v spasení tvém veselí se přenáramně.'),
(1560399,54,19,21,3,'Žádost srdce jeho dal jsi jemu, a prosbě rtů jeho neodepřel jsi. Sélah.'),
(1560400,54,19,21,4,'Předšel jsi jej zajisté hojným požehnáním, vstavil jsi na hlavu jeho korunu z ryzího zlata.'),
(1560401,54,19,21,5,'Života požádal od tebe, a dal jsi mu prodlení dnů na věky věků.'),
(1560402,54,19,21,6,'Veliká jest sláva jeho v spasení tvém, důstojností a krásou přioděl jsi jej.'),
(1560403,54,19,21,7,'Nebo jsi jej vystavil za příklad hojného požehnání až na věky, rozveselil jsi jej radostí oblíčeje svého.'),
(1560404,54,19,21,8,'A poněvadž král doufá v Hospodina, a v milosrdenství Nejvyššího, nepohneť se.'),
(1560405,54,19,21,9,'Najdeť ruka tvá všecky nepřátely své, dosáhne pravice tvá těch, kteříž tě nenávidí.'),
(1560406,54,19,21,10,'Uvržeš je jako do peci ohnivé v čas rozhněvání svého; Hospodin v prchlivosti své sehltí je, a oheň sžíře je.'),
(1560407,54,19,21,11,'Plémě jejich z země vyhladíš, a símě jejich z synů lidských,'),
(1560408,54,19,21,12,'Nebo jsou proti tobě ukládali zlost, myslili na nešlechetnost, ač ji dovesti nemohli.'),
(1560409,54,19,21,13,'Protož je vystavíš za cíl, na tětiva svá přikládati budeš proti tváři jejich.'),
(1560410,54,19,21,14,'Zjeviž se, ó Hospodine, v síle své, a budemeť zpívati a oslavovati udatnost tvou.'),
(1560411,54,19,22,1,'Přednímu zpěváku k času jitřnímu, žalm Davidův.'),
(1560412,54,19,22,2,'Bože můj, Bože můj, pročež jsi mne opustil? Vzdálils se od spasení mého a od slov naříkání mého.'),
(1560413,54,19,22,3,'Bože můj, přes celý den volám, a neslyšíš, i v noci, a nemohu se utajiti.'),
(1560414,54,19,22,4,'Ty zajisté jsi svatý, zůstávající vždycky k veliké chvále Izraelovi.'),
(1560415,54,19,22,5,'V toběť doufali otcové naši, doufali, a vysvobozovals je.'),
(1560416,54,19,22,6,'K tobě volávali, a spomáhals jim; v tobě doufali, a nebývali zahanbeni.'),
(1560417,54,19,22,7,'Já pak červ jsem, a ne člověk, útržka lidská a povrhel vůbec.'),
(1560418,54,19,22,8,'Všickni, kteříž mne vidí, posmívají se mi, ošklebují se, a hlavami potřásají, říkajíce:'),
(1560419,54,19,22,9,'Spustiltě se na Hospodina, nechť ho vysvobodí; nechať jej vytrhne, poněvadž se mu v něm zalíbilo.'),
(1560420,54,19,22,10,'Ješto ty jsi, kterýž jsi mne vyvedl z života, ustaviv mne v doufání při prsích matky mé.'),
(1560421,54,19,22,11,'Na tebeť jsem uvržen od narození svého, od života matky mé Bůh můj ty jsi.'),
(1560422,54,19,22,12,'Nevzdalujž se ode mne, nebo ssoužení blízké jest, a nemám spomocníka.'),
(1560423,54,19,22,13,'Obkličujíť mne býkové mnozí, silní volové z Bázan obstupují mne.'),
(1560424,54,19,22,14,'Otvírají na mne ústa svá, jako lev rozsapávající a řvoucí.'),
(1560425,54,19,22,15,'Jako voda rozplynul jsem se, a rozstoupily se všecky kosti mé, a srdce mé jako vosk rozpustilo se u prostřed vnitřností mých.'),
(1560426,54,19,22,16,'Vyprahla jako střepina síla má, a jazyk můj přilnul k dásním mým, anobrž v prachu smrti položils mne.'),
(1560427,54,19,22,17,'Nebo psi obskočili mne, rota zlostníků oblehla mne, zprobijeli ruce mé i nohy mé.'),
(1560428,54,19,22,18,'Mohl bych sčísti všecky kosti své, oni pak hledí na mne, a dívají se mi.'),
(1560429,54,19,22,19,'Dělí mezi sebou roucha má, a o můj oděv mecí los.'),
(1560430,54,19,22,20,'Ale ty, Hospodine, nevzdalujž se, sílo má, přispěj k spomožení mému.'),
(1560431,54,19,22,21,'Vychvať od meče duši mou, a z moci psů jedinkou mou.'),
(1560432,54,19,22,22,'Zachovej mne od úst lva, a od rohů jednorožcových vyprosť mne.'),
(1560433,54,19,22,23,'I budu vypravovati bratřím svým o jménu tvém, u prostřed shromáždění chváliti tě budu, řka:'),
(1560434,54,19,22,24,'Kteříž se bojíte Hospodina, chvalte jej, všecko símě Jákobovo ctěte jej, a boj se ho všecka rodino Izraelova.'),
(1560435,54,19,22,25,'Nebo nepohrdá, ani se odvrací od trápení ztrápeného, aniž skrývá tváři své od něho, nýbrž když k němu volá, vyslýchá jej.'),
(1560436,54,19,22,26,'O tobě chvála má v shromáždění velikém, sliby své plniti budu před těmi, kteříž se bojí tebe.'),
(1560437,54,19,22,27,'Jísti budou tiší a nasyceni budou, chváliti budou Hospodina ti, kteříž ho hledají, živo bude srdce vaše na věky.'),
(1560438,54,19,22,28,'Rozpomenou a obrátí se k Hospodinu všecky končiny země, a skláněti se budou před ním všecky čeledi národů.'),
(1560439,54,19,22,29,'Nebo Hospodinovo jest království, a onť panuje nad národy.'),
(1560440,54,19,22,30,'Jísti budou a skláněti se před ním všickni tuční země, jemu se klaněti budou všickni sstupující do prachu, a kteříž duše své nemohou při životu zachovati.'),
(1560441,54,19,22,31,'Símě jejich sloužiti mu bude, a přičteno bude ku Pánu v každém věku.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560442,54,19,22,32,'Přijdouť, a lidu, kterýž z nich vyjde, vypravovati budou spravedlnost jeho; nebo ji skutkem vykonal.'),
(1560443,54,19,23,1,'Žalm Davidův. Hospodin jest můj pastýř, nebudu míti nedostatku.'),
(1560444,54,19,23,2,'Na pastvách zelených pase mne, k vodám tichým mne přivodí.'),
(1560445,54,19,23,3,'Duši mou očerstvuje, vodí mne po stezkách spravedlnosti pro jméno své.'),
(1560446,54,19,23,4,'Byť mi se dostalo jíti přes údolí stínu smrti, nebuduť se báti zlého, nebo ty se mnou jsi; prut tvůj a hůl tvá, toť mne potěšuje.'),
(1560447,54,19,23,5,'Strojíš stůl před oblíčejem mým naproti mým nepřátelům, pomazuješ olejem hlavy mé, kalich můj naléváš, až oplývá.'),
(1560448,54,19,23,6,'Nadto i dobrota a milosrdenství následovati mne budou po všecky dny života mého, a přebývati budu v domě Hospodinově za dlouhé časy.'),
(1560449,54,19,24,1,'Žalm Davidův. Hospodinova jest země, a plnost její, okršlek země, i ti, kteříž obývají na něm.'),
(1560450,54,19,24,2,'Nebo on ji na moři založil, a na řekách upevnil ji.'),
(1560451,54,19,24,3,'Kdo vstoupí na horu Hospodinovu? A kdo stane na místě svatém jeho?'),
(1560452,54,19,24,4,'Ten, kdož jest rukou nevinných, a srdce čistého, kdož neobrací duše své k marnosti, a nepřisahá lstivě.'),
(1560453,54,19,24,5,'Ten přijme požehnání od Hospodina, a spravedlnost od Boha spasitele svého.'),
(1560454,54,19,24,6,'Toť jest národ hledajících jeho, hledajících tváři tvé, ó Bože Jákobův. Sélah.'),
(1560455,54,19,24,7,'Pozdvihnětež, ó brány, svrchků svých, pozdvihnětež se vrata věčná, aby vjíti mohl král slávy.'),
(1560456,54,19,24,8,'Kdož jest to ten král slávy? Hospodin silný a mocný, Hospodin udatný válečník.'),
(1560457,54,19,24,9,'Pozdvihnětež, ó brány, svrchků svých, pozdvihněte se vrata věčná, aby vjíti mohl král slávy.'),
(1560458,54,19,24,10,'Kdož jest to ten král slávy? Hospodin zástupů, onť jest král slávy. Sélah.'),
(1560459,54,19,25,1,'Žalm Davidův. K toběť, Hospodine, duše své pozdvihuji.'),
(1560460,54,19,25,2,'Bože můj, v toběť naději skládám, nechť nejsem zahanben, aby se neradovali nepřátelé moji nade mnou.'),
(1560461,54,19,25,3,'A takť i všickni, kteříž na tě očekávají, zahanbeni nebudou; zahanbeni budou, kteříž se převráceně mají bez příčiny.'),
(1560462,54,19,25,4,'Cesty své, Hospodine, uveď mi v známost, a stezkám svým vyuč mne.'),
(1560463,54,19,25,5,'Dejž, ať chodím v pravdě tvé, a poučuj mne; nebo ty jsi Bůh spasitel můj, na tebeť očekávám dne každého.'),
(1560464,54,19,25,6,'Rozpomeň se na slitování svá, Hospodine, a na milosrdenství svá, kteráž jsou od věků.'),
(1560465,54,19,25,7,'Hříchů mladosti mé a přestoupení mých nezpomínej, ale podlé milosrdenství svého pamětliv buď na mne pro dobrotu svou, Hospodine.'),
(1560466,54,19,25,8,'Dobrý a přímý jest Hospodin, a protož vyučuje hříšníky cestě své.'),
(1560467,54,19,25,9,'Působí to, aby tiší chodili v soudu, a vyučuje tiché cestě své.'),
(1560468,54,19,25,10,'Všecky stezky Hospodinovy jsou milosrdenství a pravda těm, kteříž ostříhají smlouvy jeho a svědectví jeho.'),
(1560469,54,19,25,11,'Pro jméno své, Hospodine, odpusť nepravost mou, neboť jest veliká.'),
(1560470,54,19,25,12,'Který jest člověk, ješto se bojí Hospodina, jehož vyučuje, kterou by cestu vyvoliti měl?'),
(1560471,54,19,25,13,'Duše jeho v dobrém přebývati bude, a símě jeho dědičně obdrží zemi.'),
(1560472,54,19,25,14,'Tajemství Hospodinovo zjevné jest těm, kteříž se jeho bojí, a v známost jim uvodí smlouvu svou.'),
(1560473,54,19,25,15,'Oči mé vždycky patří k Hospodinu, on zajisté z leči vyvodí nohy mé.'),
(1560474,54,19,25,16,'Popatřiž na mne, a smiluj se nade mnou, neboť jsem opuštěný a strápený.'),
(1560475,54,19,25,17,'Ssoužení srdce mého rozmnožují se, z úzkostí mých vyveď mne.'),
(1560476,54,19,25,18,'Viz trápení mé a bídu mou, a odpusť všecky hříchy mé.'),
(1560477,54,19,25,19,'Viz nepřátely mé, jak mnozí jsou, a nenávistí nešlechetnou nenávidí mne.'),
(1560478,54,19,25,20,'Ostříhej duše mé, a vytrhni mne, ať nejsem zahanben, neboť v tebe doufám.'),
(1560479,54,19,25,21,'Sprostnost a upřímnost nechať mne ostříhají, nebo na tě očekávám.'),
(1560480,54,19,25,22,'Vykup, ó Bože, Izraele ze všelijakých úzkostí jeho.'),
(1560481,54,19,26,1,'Žalm Davidův. Suď mne, Hospodine, nebo já v upřímnosti své chodím, a v tě Hospodina doufám, nepohnuť se.'),
(1560482,54,19,26,2,'Zprubujž mne, Hospodine, a zkus mne, přepal ledví má i srdce mé.'),
(1560483,54,19,26,3,'Milosrdenství tvé zajisté před očima mýma jest, a chodím stále v pravdě tvé.'),
(1560484,54,19,26,4,'S lidmi marnými nesedám, a s pokrytci v spolek nevcházím.'),
(1560485,54,19,26,5,'V nenávisti mám shromáždění zlostníků, a s bezbožnými se neusazuji.'),
(1560486,54,19,26,6,'Umývám v nevinnosti ruce své, postavuji se při oltáři tvém, Hospodine,'),
(1560487,54,19,26,7,'Abych tě hlasitě chválil, a vypravoval všecky divné skutky tvé.'),
(1560488,54,19,26,8,'Hospodine, jáť miluji obydlí domu tvého, a místo příbytku slávy tvé.'),
(1560489,54,19,26,9,'Nezahrnujž s hříšnými duše mé, a s lidmi vražedlnými života mého,'),
(1560490,54,19,26,10,'V jejichž rukou jest nešlechetnost, a pravice jejich vzátků plná.'),
(1560491,54,19,26,11,'Já pak v upřímnosti své chodím, vykupiž mne, a smiluj se nade mnou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560492,54,19,26,12,'Noha má stojí na rovině, v shromážděních svatých dobrořečiti budu Hospodinu.'),
(1560493,54,19,27,1,'Davidův. Hospodin světlo mé a spasení mé, kohož se budu báti? Hospodin síla života mého, kohož se budu strašiti?'),
(1560494,54,19,27,2,'Útok učinivše na mne zlostníci, k sežrání těla mého, protivníci moji a nepřátelé moji, sami se potkli a padli.'),
(1560495,54,19,27,3,'Protož byť i stany své proti mně rozbili, nebude se lekati srdce mé; byť se pozdvihla proti mně i válka, na toť se já spouštím.'),
(1560496,54,19,27,4,'Jedné věci žádal jsem od Hospodina, téť vždy hledati budu: Abych přebýval v domě Hospodinově po všecky dny života svého,a spatřoval okrasu Hospodinovu, a zpytoval v chrámě jeho.'),
(1560497,54,19,27,5,'Nebo tu mne ukryje v stánku svém, v den zlý schová mne v skrýši stanu svého, a na skálu vyzdvihne mne.'),
(1560498,54,19,27,6,'A tak vyvýšena bude hlava má nad nepřátely mými, kteříž mne obklíčili; i budu obětovati v stánku jeho oběti plésání, prozpěvovati a chvály vzdávati budu Hospodinu.'),
(1560499,54,19,27,7,'Slyš mne, Hospodine, hlasem volajícího, a smiluj se nade mnou, i vyslyš mne.'),
(1560500,54,19,27,8,'O tobě přemýšlí srdce mé, že velíš, řka: Hledejte tváři mé, a protož tváři tvé, Hospodine, hledati budu.'),
(1560501,54,19,27,9,'Neskrývejž tváři své přede mnou, aniž zamítej v hněvě služebníka svého; spomožení mé býval jsi, neopouštěj mne, aniž se mne zhošťuj, Bože spasení mého.'),
(1560502,54,19,27,10,'Ačkoli otec můj a matka má mne opustili, Hospodin však mne k sobě přivine.'),
(1560503,54,19,27,11,'Vyuč mne, Hospodine, cestě své, a veď mne po stezce přímé pro ty, jenž mne střehou.'),
(1560504,54,19,27,12,'Nevydávejž mne líbosti protivníků mých, neboť by ostáli proti mně svědkové lživí, i ten, jenž dýše ukrutností.'),
(1560505,54,19,27,13,'Bychť nevěřil, že užívati budu dobroty Hospodinovy v zemi živých, nikoli bych neostál.'),
(1560506,54,19,27,14,'Očekávejž na Hospodina, posilň se, a onť posilní srdce tvého; protož očekávej na Hospodina.'),
(1560507,54,19,28,1,'Davidův. K toběť, Hospodine, volám, skálo má, neodmlčujž mi se, abych, neozval-li bys mi se, nebyl podobný učiněn těm, kteříž sstupují do hrobu.'),
(1560508,54,19,28,2,'Vyslýchej hlas pokorných modliteb mých, kdyžkoli k tobě volám, když pozdvihuji rukou svých k svatyni svatosti tvé.'),
(1560509,54,19,28,3,'Nezahrnuj mne s bezbožníky, a s těmi, kteříž páší nepravost, kteříž mluvívají pokoj s bližními svými, ale převrácenost jest v srdcích jejich.'),
(1560510,54,19,28,4,'Dejž jim podlé skutků jejich, a podlé zlosti nešlechetností jejich; podlé práce rukou jejich dej jim, zaplať jim zaslouženou mzdu jejich.'),
(1560511,54,19,28,5,'Nebo nechtí mysli přiložiti k skutkům Hospodinovým, a k dílu rukou jeho; protož podvrátí je, a nebude jich vzdělávati.'),
(1560512,54,19,28,6,'Požehnaný Hospodin, nebo vyslyšel hlas pokorných modliteb mých.'),
(1560513,54,19,28,7,'Hospodin jest síla má a štít můj, v němť jest složilo naději srdce mé, a dána mi pomoc; protož se veselí srdce mé, a písničkou svou oslavovati jej budu.'),
(1560514,54,19,28,8,'Hospodin jest síla svých, a síla hojného spasení pomazaného svého on jest.'),
(1560515,54,19,28,9,'Spas lid svůj, Hospodine, a požehnej dědictví svému, a pas je, i vyvyš je až na věky.'),
(1560516,54,19,29,1,'Žalm Davidův. Vzdejte Hospodinu, velikomocní, vzdejte Hospodinu čest a sílu.'),
(1560517,54,19,29,2,'Vzdejte Hospodinu slávu jména jeho, sklánějte se Hospodinu v ozdobě svatosti.'),
(1560518,54,19,29,3,'Hlas Hospodinův nad vodami, Bůh silný slávy hřímání vzbuzuje, Hospodin to činí nad vodami mnohými.'),
(1560519,54,19,29,4,'Hlas Hospodinův přichází s mocí, hlas Hospodinův s velebností.'),
(1560520,54,19,29,5,'Hlas Hospodinův láme cedry, rozrážíť Hospodin cedry Libánské.'),
(1560521,54,19,29,6,'A činí, aby skákali jako telata, Libán a Sirion, jako mladý jednorožec.'),
(1560522,54,19,29,7,'Hlas Hospodinův rozkřesává plamen ohně.'),
(1560523,54,19,29,8,'Hlas Hospodinův k bolesti přivodí poušť, k bolesti přivodí Hospodin poušť Kádes.'),
(1560524,54,19,29,9,'Hlas Hospodinův to činí, že laně plodu pozbývají, obnažuje i lesy, ale v chrámě svém všecku svou slávu vypravuje.'),
(1560525,54,19,29,10,'Hospodin nad potopou seděl, a budeť seděti Hospodin, jsa králem i na věky.'),
(1560526,54,19,29,11,'Hospodin silou lid svůj daří, Hospodin požehná lidu svému v pokoji.'),
(1560527,54,19,30,1,'Žalm písně, při posvěcení domu Davidova.'),
(1560528,54,19,30,2,'Vyvyšovati tě budu, Hospodine, nebo jsi vyvýšil mne, aniž jsi obradoval nepřátel mých nade mnou.'),
(1560529,54,19,30,3,'Hospodine Bože můj, k toběť jsem volal, a uzdravil jsi mne.'),
(1560530,54,19,30,4,'Hospodine, vyvedl jsi z pekla duši mou, obživil jsi mne, abych s jinými nesstoupil do hrobu.'),
(1560531,54,19,30,5,'Žalmy zpívejte Hospodinu svatí jeho, a oslavujte památku svatosti jeho.'),
(1560532,54,19,30,6,'Nebo na kratičko trvá v hněvě svém, všecken pak život v dobré líbeznosti své; z večera potrvá pláč, ale z jitra navrátí se prozpěvování.'),
(1560533,54,19,30,7,'I jáť jsem řekl, když mi se šťastně vedlo: Nepohnu se na věky.'),
(1560534,54,19,30,8,'Nebo ty, Hospodine, podlé dobře líbezné vůle své silou upevnil jsi horu mou, ale jakž jsi skryl tvář svou, byl jsem přestrašen.'),
(1560535,54,19,30,9,'I volal jsem k tobě, Hospodine, Pánu pokorně jsem se modlil, řka:'),
(1560536,54,19,30,10,'Jaký bude užitek z mé krve, jestliže sstoupím do jámy? Zdaliž tě prach oslavovati bude? Zdaliž zvěstovati bude pravdu tvou?'),
(1560537,54,19,30,11,'Vyslyšiž, Hospodine, a smiluj se nade mnou, Hospodine, budiž můj spomocník.'),
(1560538,54,19,30,12,'I obrátil jsi mi pláč můj v plésání, odvázal jsi pytel můj, a přepásals mne veselím.'),
(1560539,54,19,30,13,'Protož tobě žalmy zpívati bude jazyk můj, a nebude mlčeti. Hospodine Bože můj, na věky tě oslavovati budu.'),
(1560540,54,19,31,1,'Přednímu zpěváku, žalm Davidův.'),
(1560541,54,19,31,2,'V tebe, Hospodine, doufám, nedejž mi zahanbenu býti na věky, pro spravedlnost svou vysvoboď mne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560542,54,19,31,3,'Nakloň ke mně ucha svého, rychle vytrhni mne; budiž mi pevnou skalou a domem ohraženým, abys mne zachoval.'),
(1560543,54,19,31,4,'Nebo skála má a hrad můj ty jsi, protož pro jméno své veď i doveď mne.'),
(1560544,54,19,31,5,'Vyveď mne z leči, kterouž polékli na mne; nebo síla má ty jsi.'),
(1560545,54,19,31,6,'V ruce tvé poroučím ducha svého, nebo jsi mne vykoupil, Hospodine, Bože silný a věrný.'),
(1560546,54,19,31,7,'Nenávidím těch, kteříž následují pouhých marností, nebo já v Hospodinu naději skládám.'),
(1560547,54,19,31,8,'Plésati a radovati se budu v milosrdenství tvém, že jsi vzezřel na mé trápení, a poznal jsi v ssoužení duši mou.'),
(1560548,54,19,31,9,'Aniž jsi mne zavřel v ruce nepřítele, ale postavil jsi na širokosti nohy mé.'),
(1560549,54,19,31,10,'Smiluj se nade mnou, Hospodine, nebo jsem ssoužen, tak že usvadla zámutkem tvář má, duše má, i život můj.'),
(1560550,54,19,31,11,'Žalostí zajisté zhynulo zdraví mé, a léta má od úpění, zemdlena bídou mou síla má, a kosti mé vyprahly.'),
(1560551,54,19,31,12,'U všech nepřátel svých jsem v pohanění, a nejvíce u sousedů, známým pak svým jsem strašidlem; kteříž mne vídají vně, utíkají přede mnou.'),
(1560552,54,19,31,13,'Vyšel jsem z paměti tak, jako mrtvý, učiněn jsem jako nádoba rozražená.'),
(1560553,54,19,31,14,'Nebo slýchám utrhání mnohých, strach odevšad, když se proti mně spolu puntují, lstivě přemýšlejíce, jak by odjali duši mou.'),
(1560554,54,19,31,15,'Ale já v tobě naději skládám, Hospodine; řekl jsem: Bůh můj jsi ty.'),
(1560555,54,19,31,16,'V rukou tvých jsou časové moji, vytrhni mne z ruky nepřátel mých a těch, kteříž mne stihají.'),
(1560556,54,19,31,17,'Osvěť tvář svou nad služebníkem svým, zachovej mne pro milosrdenství své.'),
(1560557,54,19,31,18,'Hospodine, ať nejsem zahanben, nebo jsem tě vzýval; nechať jsou zahanbeni bezbožníci, a skroceni v pekle.'),
(1560558,54,19,31,19,'Oněmějte rtové lživí, kteříž mluví proti spravedlivému tvrdě, pyšně a s potupou.'),
(1560559,54,19,31,20,'Ó jak veliká jest dobrotivost tvá, kterouž jsi odložil těm, jenž se bojí tebe, a kterouž jsi činíval doufajícím v tebe před syny lidskými.'),
(1560560,54,19,31,21,'Ty je skrýváš v skrýši oblíčeje svého před vysokomyslností člověka, skrýváš je jako v stanu před jazyky svárlivými.'),
(1560561,54,19,31,22,'Požehnaný buď Hospodin, nebo prokázal ke mně divné milosrdenství své jako v městě ohraženém.'),
(1560562,54,19,31,23,'Já zajisté když jsem pospíchal, řekl jsem: Zavrženť jsem od očí tvých, ale ty jsi vyslyšel hlas pokorných modliteb mých, když jsem k tobě volal.'),
(1560563,54,19,31,24,'Milujtež Hospodina všickni svatí jeho, neboť ostříhá věřících Hospodin, a též odplací vrchovatě tomu, kdož pýchu provodí.'),
(1560564,54,19,31,25,'Zmužile sobě čiňte, (a posilní Bůh srdce vašeho), všickni, kteříž naději máte v Hospodinu.'),
(1560565,54,19,32,1,'Žalm Davidův vyučující. Blahoslavený jest ten, jemuž odpuštěno přestoupení, a jehož hřích přikryt jest.'),
(1560566,54,19,32,2,'Blahoslavený člověk, jemuž nepočítá Hospodin nepravosti, a v jehož duchu lsti není.'),
(1560567,54,19,32,3,'Já když jsem mlčel, prahly kosti mé v úpění mém každého dne.'),
(1560568,54,19,32,4,'Nebo dnem i nocí obtížena byla nade mnou ruka tvá, tak že přirozená vlhkost má obrátila se v sucho letní. Sélah.'),
(1560569,54,19,32,5,'Protož hřích svůj oznámil jsem tobě, a nepravosti své jsem neukryl. Řekl jsem: Vyznám na sebe Hospodinu přestoupení svá, a ty jsi odpustil nepravost hříchu mého. Sélah.'),
(1560570,54,19,32,6,'Za to se tobě bude modliti každý svatý, v času příhodném k nalezení tebe; pročež vody mnohé v rozvodnění k němu nedosáhnou.'),
(1560571,54,19,32,7,'Ty jsi skrýše má, od ssoužení zachováš mne, a plésáním vítězným obdaříš. Sélah.'),
(1560572,54,19,32,8,'Já tobě k srozumění posloužím, a vyučím tě cestě, po níž bys choditi měl; dámť radu, oči své na tě obrátě.'),
(1560573,54,19,32,9,'Nebývejte jako kůň a jako mezek, kteříž rozumu nemají, jejichž ústa uzdou a udidly sevříti musíš, aby tobě neškodili.'),
(1560574,54,19,32,10,'Mnohé bolesti jsou bezbožníka, ale toho, jenž naději skládá v Hospodinu, milosrdenství obklíčí.'),
(1560575,54,19,32,11,'Radujte se v Hospodinu, a plésejte spravedliví, a prozpěvujte všickni srdce upřímého.'),
(1560576,54,19,33,1,'Veselte se spravedliví v Hospodinu, na upříméť přísluší chválení.'),
(1560577,54,19,33,2,'Oslavujte Hospodina na harfě, na loutně, a na nástroji o desíti strunách, žalmy zpívejte jemu.'),
(1560578,54,19,33,3,'Zpívejte jemu píseň novou, a huďte dobře a zvučně.'),
(1560579,54,19,33,4,'Nebo pravé jest slovo Hospodinovo, a všeliké dílo jeho stálé.'),
(1560580,54,19,33,5,'Milujeť spravedlnost a soud, milosrdenství Hospodinova plná jest země.'),
(1560581,54,19,33,6,'Slovem Hospodinovým nebesa učiněna jsou, a duchem úst jeho všecko vojsko jejich.'),
(1560582,54,19,33,7,'Onť shrnul jako na hromadu vody mořské, a složil na poklad propasti.'),
(1560583,54,19,33,8,'Boj se Hospodina všecka země, děstež se před ním všickni obyvatelé okršlku zemského.'),
(1560584,54,19,33,9,'Nebo on řekl, a stalo se, on rozkázal, a postavilo se.'),
(1560585,54,19,33,10,'Hospodin ruší rady národů, a v nic obrací přemyšlování lidská.'),
(1560586,54,19,33,11,'Rada pak Hospodinova na věky trvá, myšlení srdce jeho od národu do pronárodu.'),
(1560587,54,19,33,12,'Blahoslavený národ, kteréhož Hospodin jest Bohem jeho, lid ten, kterýž sobě on vyvolil za dědictví.'),
(1560588,54,19,33,13,'Hospodin patře s nebe, vidí všecky syny lidské,'),
(1560589,54,19,33,14,'Z příbytku trůnu svého dohlédá ke všechněm obyvatelům země.'),
(1560590,54,19,33,15,'Ten, kterýž stvořil srdce jednoho každého z nich, spatřuje všecky skutky jejich.'),
(1560591,54,19,33,16,'Nebývá král zachován skrze mnohý zástup, ani udatný rek vysvobozen skrze velikou moc svou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560592,54,19,33,17,'Oklamavatelný jest kůň k spomožení, aniž ve množství síly své vytrhuje.'),
(1560593,54,19,33,18,'Aj, oči Hospodinovy patří na ty, kteříž se ho bojí, a na ty, kteříž očekávají milosrdenství jeho,'),
(1560594,54,19,33,19,'Aby vyprostil od smrti duše jejich, a živil je v čas hladu.'),
(1560595,54,19,33,20,'Duše naše očekává na Hospodina, on jest spomožení naše, a pavéza naše.'),
(1560596,54,19,33,21,'V něm zajisté rozveselí se srdce naše, nebo ve jménu jeho svatém naději skládáme.'),
(1560597,54,19,33,22,'Budiž milosrdenství tvé nad námi, Hospodine, jakož naději máme v tobě.'),
(1560598,54,19,34,1,'Davidův, když proměnil oblíčej svůj před Abimelechem; pročež jsa od něho vyhnán, odšel.'),
(1560599,54,19,34,2,'Dobrořečiti budu Hospodinu každého času, vždycky chvála jeho v ústech mých.'),
(1560600,54,19,34,3,'V Hospodinu chlubiti se bude duše má, což uslyšíc tiší, budou se veseliti.'),
(1560601,54,19,34,4,'Zvelebujtež se mnou Hospodina, a jméno jeho společně vyvyšujme.'),
(1560602,54,19,34,5,'Hledal jsem Hospodina, a vyslyšel mne, a ze všech přístrachů mých vytrhl mne.'),
(1560603,54,19,34,6,'Pročež k němu patřiti budou, a sbíhati se, a nebudou zahanbeny tváři jejich, ale řkou:'),
(1560604,54,19,34,7,'Tento chudý volal a Hospodin vyslyšel, i ze všech úzkostí jeho vysvobodil jej.'),
(1560605,54,19,34,8,'Vojensky se klade anděl Hospodinův okolo těch, kteříž se ho bojí, a zastává jich.'),
(1560606,54,19,34,9,'Okuste a vizte, jak dobrý jest Hospodin. Blahoslavený člověk, kterýž doufá v něho.'),
(1560607,54,19,34,10,'Bojtež se Hospodina svatí jeho; neboť nemívají nedostatku ti, kdož se ho bojí.'),
(1560608,54,19,34,11,'Lvíčátka nedostatek a hlad trpívají, ale ti, kteříž hledají Hospodina, nemívají nedostatku ve všem dobrém.'),
(1560609,54,19,34,12,'Poďtež, dítky, poslouchejte mne, bázni Hospodinově vyučovati vás budu.'),
(1560610,54,19,34,13,'Který člověk žádostiv jest života, a miluje dny, aby užíval dobrých věcí?'),
(1560611,54,19,34,14,'Zdržuj jazyk svůj od zlého, a rty své od mluvení lsti.'),
(1560612,54,19,34,15,'Odstup od zlého, a čiň dobré, hledej pokoje, a stíhej jej.'),
(1560613,54,19,34,16,'Oči Hospodinovy obrácené jsou k spravedlivým, a uši jeho k volání jejich:'),
(1560614,54,19,34,17,'Ale zůřivý oblíčej Hospodinův proti těm, kteříž páší zlé věci, aby vyplénil z země památku jejich.'),
(1560615,54,19,34,18,'Volají-li spravedliví, Hospodin vyslýchá, a ze všech jejich úzkostí je vytrhuje.'),
(1560616,54,19,34,19,'Nebo blízko jest Hospodin těm, kteříž jsou srdce skroušeného, a potřeným v duchu spomáhá.'),
(1560617,54,19,34,20,'Mnohé úzkosti jsou spravedlivého, ale Hospodin ze všech jej vytrhuje.'),
(1560618,54,19,34,21,'Onť ostříhá všech kostí jeho, žádná z nich nebývá zlámána.'),
(1560619,54,19,34,22,'Bezbožníka zahubí zlost, a ti, kteříž nenávidí spravedlivého, zkaženi budou.'),
(1560620,54,19,34,23,'Služebníků pak svých duše vykoupí Hospodin, a nebudou zkaženi, kteříž doufají v něho.'),
(1560621,54,19,35,1,'Žalm Davidův. Suď se, Hospodine, s těmi, kteříž se se mnou soudí; bojuj proti těm, kteříž proti mně bojují.'),
(1560622,54,19,35,2,'Pochyť štít a pavézu, a povstaň mi ku pomoci.'),
(1560623,54,19,35,3,'Vezmi i kopí, a vyjdi vstříc těm, kteříž táhnou proti mně. Rciž duši mé: Spasení tvé jáť jsem.'),
(1560624,54,19,35,4,'Nechať se zahanbí a zapýří ti, kteříž hledají duše mé; zpět ať jsou obráceni a zahanbeni ti, kteříž mi zlé obmýšlejí.'),
(1560625,54,19,35,5,'Ať jsou jako plevy před větrem, a anděl Hospodinův rozptylujž je.'),
(1560626,54,19,35,6,'Cesta jejich budiž temná a plzká, a anděl Hospodinův stihej je.'),
(1560627,54,19,35,7,'Nebo jsou bez příčiny polékli v jámě osídlo své, bez příčiny vykopali jámu duši mé.'),
(1560628,54,19,35,8,'Připadniž na ně setření, jehož se nenadáli, a sít jejich, kterouž ukryli, ať je uloví; s hřmotem ať do ní vpadnou.'),
(1560629,54,19,35,9,'Duše má pak ať se veselí v Hospodinu, a ať raduje se v spasení jeho.'),
(1560630,54,19,35,10,'A tuť všecky kosti mé řeknou: Hospodine, kdo jest podobný tobě, ješto vytrhuješ ztrápeného z moci toho, kterýž nad něj silnější jest, tolikéž chudého a nuzného od toho, kterýž ho násilně loupí?'),
(1560631,54,19,35,11,'Povstávají svědkové lživí, a na to, o čemž nevím, dotazují se mne.'),
(1560632,54,19,35,12,'Zlým za dobré mi se odplacují, duše mé zbaviti mne chtíce,'),
(1560633,54,19,35,13,'Ježto já v nemoci jejich pytlem jsem se přiodíval, duši svou postem trápil, a sám u sebe za ně často se modlil.'),
(1560634,54,19,35,14,'Jako k příteli, jako k bratru vlastnímu jsem chodíval; jakožto ten, kterýž po matce kvílí, smutek nesa, tak jsem se ponižoval.'),
(1560635,54,19,35,15,'Ale oni z mého zlého radovali se, a rotili se; shromažďovali se proti mně i ti nejnevážnější, o čemž jsem nevěděl; utrhali mi, a nemlčeli.'),
(1560636,54,19,35,16,'S pokrytci, posměvači, fatkáři škřipěli na mne zuby svými.'),
(1560637,54,19,35,17,'Pane, dlouho-liž se dívati budeš? Vytrhni duši mou od zhouby jejich, od lvů jedinkou mou.'),
(1560638,54,19,35,18,'I budu tě oslavovati v shromáždění velikém, ve množství lidu tebe chváliti budu.'),
(1560639,54,19,35,19,'Nechažť se nade mnou neradují ti, kteříž bezprávně ke mně se nepřátelsky mají; ti, kteříž mne nenávidí bez příčiny, ať nemhourají očima.'),
(1560640,54,19,35,20,'Neboť nemluví ku pokoji, ale proti pokojným na zemi slova lstivá vymýšlejí.'),
(1560641,54,19,35,21,'Anobrž rozdírají proti mně ústa svá, a říkají: Hahá, hahá, jižť vidí oko naše.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560642,54,19,35,22,'Vidíš ty to, Hospodine, neodmlčujž se, Pane, nevzdalujž se ode mne.'),
(1560643,54,19,35,23,'Probudiž se a prociť k soudu mému, Bože můj a Pane můj, k obhájení pře mé.'),
(1560644,54,19,35,24,'Suď mne podlé spravedlnosti své, Hospodine Bože můj, ať se neradují nade mnou.'),
(1560645,54,19,35,25,'Ať neříkají v srdci svém: Měhoděk duši naší; ať neříkají: Sehltili jsme jej.'),
(1560646,54,19,35,26,'Ale ať se zahanbí a zapýří všickni radující se mému zlému, v stud a hanbu ať jsou oblečeni ti, kteříž se zpínají proti mně.'),
(1560647,54,19,35,27,'Ti pak, kteříž mi přejí mé spravedlnosti, ať plésají, a radují se, a ať říkají vždycky: Veleslaven budiž Hospodin, kterýž přeje pokoje služebníku svému.'),
(1560648,54,19,35,28,'I můj jazyk ohlašovati bude spravedlnost tvou, a na každý den chválu tvou.'),
(1560649,54,19,36,1,'Přednímu z kantorů, služebníka Hospodinova Davida.'),
(1560650,54,19,36,2,'Převrácenost bezbožníka pojišťuje u vnitřnosti srdce mého, že není žádné bázně Boží před očima jeho.'),
(1560651,54,19,36,3,'Nebo mu ona pochlebuje před očima jeho, aby vykonal nepravost svou až do zošklivení.'),
(1560652,54,19,36,4,'Slova úst jeho jsou nepravá a lstivá, přestal srozumívati, aby dobře činil.'),
(1560653,54,19,36,5,'Nepravost smýšlí i na ložci svém, ustavuje se na cestě nedobré, zlého se nevaruje.'),
(1560654,54,19,36,6,'Hospodine, až do nebes milosrdenství tvé, pravda tvá až do nejvyšších oblaků.'),
(1560655,54,19,36,7,'Spravedlnost tvá jako nejvyšší hory, soudové tvoji jako hlubokost nesmírná; lidi i hovada sám zachováváš, Hospodine.'),
(1560656,54,19,36,8,'Jak převelmi drahé jest milosrdenství tvé, Bože, a protož synové lidští v stínu křídel tvých doufají.'),
(1560657,54,19,36,9,'Tučností domu tvého rozvlažováni bývají, a potokem rozkoší svých napájíš je.'),
(1560658,54,19,36,10,'Nebo u tebe jest studnice života, a v světle tvém světlo vidíme.'),
(1560659,54,19,36,11,'Rozprostři milosrdenství své na ty, kteříž tebe znají, a spravedlnost tvou na upřímé srdcem.'),
(1560660,54,19,36,12,'Nechažť nedotírá na mne noha pyšných, a ruka bezbožníků ať mne nezavozuje.'),
(1560661,54,19,36,13,'Tam, kdež padají činitelé nepravosti, poraženi bývají, a nemohou povstati.'),
(1560662,54,19,37,1,'Žalm Davidův. Nehněvej se příčinou zlostníků, nechtěj záviděti těm, kteříž páší nepravost.'),
(1560663,54,19,37,2,'Nebo jako tráva v náhle podťati budou, a jako zelená bylina uvadnou.'),
(1560664,54,19,37,3,'Doufej v Hospodina, a'),
(1560665,54,19,37,4,'Těš se v Hospodinu, a dá tobě žádosti srdce tvého.'),
(1560666,54,19,37,5,'Uval na Hospodina cestu svou, a slož v něm naději, onť zajisté všecko spraví.'),
(1560667,54,19,37,6,'A vyvedeť spravedlnost tvou jako světlo, a nevinu tvou jako poledne.'),
(1560668,54,19,37,7,'Mlčelivě se měj k Hospodinu, a očekávej na něj pečlivě. Nekormuť se příčinou toho, jemuž se daří na cestě jeho, příčinou člověka, kterýž provodí, cožkoli umyslil.'),
(1560669,54,19,37,8,'Pusť mimo sebe hněv, a zanech prchlivosti; nezpouzej se tak, abys zle činiti chtěl.'),
(1560670,54,19,37,9,'Nebo zlostníci vypléněni budou, ale ti, kteříž očekávají na Hospodina, dědičně zemí vládnouti budou.'),
(1560671,54,19,37,10,'Po malé chvíli zajisté, anť bezbožníka nebude, a pohledíš na místo jeho, anť ho již není.'),
(1560672,54,19,37,11,'Ale tiší dědičně obdrží zemi, a rozkoš míti budou ve množství pokoje.'),
(1560673,54,19,37,12,'Zle myslí bezbožník o spravedlivém, a škřipí na něj zuby svými,'),
(1560674,54,19,37,13,'Ale Hospodin směje se jemu; nebo vidí, že se přibližuje den jeho.'),
(1560675,54,19,37,14,'Vytrhujíť bezbožníci meč, a natahují lučiště své, aby porazili chudého a nuzného, aby hubili ty, kteříž jsou ctného obcování;'),
(1560676,54,19,37,15,'Ale meč jejich vejde v jejich srdce, a lučiště jejich budou polámána.'),
(1560677,54,19,37,16,'Lepší jest málo, což má spravedlivý, než veliká bohatství bezbožníků mnohých.'),
(1560678,54,19,37,17,'Nebo ramena bezbožných polámána budou, spravedlivé pak zdržuje Hospodin.'),
(1560679,54,19,37,18,'Znáť Hospodin dny upřímých, protož dědictví jejich na věky zůstane.'),
(1560680,54,19,37,19,'Nebudouť zahanbeni v čas zlý, a ve dnech hladu nasyceni budou;'),
(1560681,54,19,37,20,'Ale bezbožníci zahynou, a nepřátelé Hospodinovi, jak tuk beranů s dymem mizí, tak zmizejí.'),
(1560682,54,19,37,21,'Vypůjčuje bezbožník, a nemá co oplatiti, ale spravedlivý milost činí, a rozdává.'),
(1560683,54,19,37,22,'Nebo požehnaní ode Pána zemí vládnouti budou, ale zlořečení od něho budou vypléněni.'),
(1560684,54,19,37,23,'Krokové člověka spravedlivého od Hospodina spravováni bývají, a cestu jeho libuje.'),
(1560685,54,19,37,24,'Jestliže by upadl, neurazí se; nebo Hospodin drží jej za ruku jeho.'),
(1560686,54,19,37,25,'Mlad jsem byl, a sstaral jsem se, a neviděl jsem spravedlivého opuštěného, ani semene jeho žebrati chleba.'),
(1560687,54,19,37,26,'Každého dne milost činí, i půjčuje, a však símě jeho jest v požehnání.'),
(1560688,54,19,37,27,'Odstup od zlého, a čiň dobré, a bydliti budeš na věky.'),
(1560689,54,19,37,28,'Nebo Hospodin miluje soud, a neopouští svatých svých, na věky v stráži jeho budou; símě pak bezbožníků bude vypléněno.'),
(1560690,54,19,37,29,'Ale spravedliví ujmou zemi dědičně, a na věky v ní přebývati budou.'),
(1560691,54,19,37,30,'Ústa spravedlivého mluví moudrost, a jazyk jeho vynáší soud.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560692,54,19,37,31,'Zákon Boha jeho jest v srdci jeho, pročež nepodvrtnou se nohy jeho.'),
(1560693,54,19,37,32,'Špehujeť bezbožník po spravedlivém, a hledá ho zahubiti;'),
(1560694,54,19,37,33,'Ale Hospodin ho nenechá v ruce jeho, aniž ho dopustí potupiti, když by souzen byl.'),
(1560695,54,19,37,34,'Očekávejž tedy na Hospodina, a ostříhej cesty jeho, a on tě povýší, abys dědičně obdržel zemi, z níž že vykořeněni budou bezbožníci, uhlédáš.'),
(1560696,54,19,37,35,'Viděl jsem bezbožníka hrozné síly, an se rozložil jako zelený samorostlý strom.'),
(1560697,54,19,37,36,'Ale tudíž pominul, a aj nebylo ho; nebo hledal jsem ho, a není nalezen.'),
(1560698,54,19,37,37,'Pozor měj na pobožného, a viz upřímého, žeť takového člověka poslední věci jsou potěšené,'),
(1560699,54,19,37,38,'Přestupníci pak že tolikéž vyhlazeni budou, a bezbožníci naposledy vyťati.'),
(1560700,54,19,37,39,'Ale spasení spravedlivých jest od Hospodina, onť jest síla jejich v času ssoužení.'),
(1560701,54,19,37,40,'Spomáháť jim Hospodin, a je vytrhuje, vytrhuje je od bezbožníků, a zachovává je; nebo doufají v něho.'),
(1560702,54,19,38,1,'Žalm Davidův k připomínání.'),
(1560703,54,19,38,2,'Hospodine, v prchlivosti své netresci mne, ani v hněvě svém kárej mne.'),
(1560704,54,19,38,3,'Nebo střely tvé uvázly ve mně, a ruka tvá na mne těžce dolehla.'),
(1560705,54,19,38,4,'Nic není celého v těle mém pro tvou hněvivost, nemají pokoje kosti mé pro hřích můj.'),
(1560706,54,19,38,5,'Nebo nepravosti mé vzešly nad hlavu mou, jako břímě těžké nemožné jsou mi k unesení.'),
(1560707,54,19,38,6,'Zahnojily se, a kyší rány mé pro bláznovství mé.'),
(1560708,54,19,38,7,'Pohrbený a sklíčený jsem náramně, každého dne v smutku chodím.'),
(1560709,54,19,38,8,'Nebo ledví má plná jsou mrzkosti, a nic není celého v těle mém.'),
(1560710,54,19,38,9,'Zemdlen jsem a potřín převelice, řvu pro úzkost srdce svého.'),
(1560711,54,19,38,10,'Pane, před tebou jest všecka žádost má, a vzdychání mé není před tebou skryto.'),
(1560712,54,19,38,11,'Srdce mé zmítá se, opustila mne síla má, i to světlo očí mých není se mnou.'),
(1560713,54,19,38,12,'Ti, kteříž mne milovali, a tovaryši moji, štítí se ran mých, a příbuzní moji zdaleka stojí.'),
(1560714,54,19,38,13,'Ti pak, kteříž stojí o bezživotí mé, osídla lécejí, a kteříž mého zlého hledají, mluví převráceně, a přes celý den lest a chytrost smýšlejí.'),
(1560715,54,19,38,14,'Ale já jako hluchý neslyším, a jako němý, kterýž neotvírá úst svých;'),
(1560716,54,19,38,15,'Tak jsem, jako člověk, kterýž neslyší, a v jehož ústech není žádného odporu.'),
(1560717,54,19,38,16,'Nebo na tě, Hospodine, očekávám, ty za mne odpovíš, Pane Bože můj.'),
(1560718,54,19,38,17,'Nebo jsem řekl: Ať se neradují ze mne, poklesla-li by se noha má, ať se pyšně nepozdvihují nade mnou,'),
(1560719,54,19,38,18,'Poněvadž k snášení bíd hotov jsem, anobrž bolest má vždycky jest přede mnou.'),
(1560720,54,19,38,19,'A že nepravosti své vyznávám, a pro hřích svůj tesklím.'),
(1560721,54,19,38,20,'Pročež nepřátelé moji veseli jsouce, silí se, a rozmnožují se ti, kteříž mne bez příčiny nenávidí.'),
(1560722,54,19,38,21,'A zlým za dobré mi se odplacujíce, činí mi protivenství, proto že dobrého následuji.'),
(1560723,54,19,38,22,'Neopouštějž mne, Hospodine Bože můj, nevzdalujž se ode mne.'),
(1560724,54,19,38,23,'Přispěj k spomožení mému, Pane spasení mého.'),
(1560725,54,19,39,1,'Přednímu zpěváku Jedutunovi, žalm Davidův.'),
(1560726,54,19,39,2,'Řekl jsem: Ostříhati budu cest svých, abych nezhřešil jazykem svým; pojmu v uzdu ústa svá, dokudž bude bezbožník přede mnou.'),
(1560727,54,19,39,3,'Mlčením byl jsem k němému podobný, umlčel jsem se i spravedlivého odporu, ale bolest má více zbouřena jest.'),
(1560728,54,19,39,4,'Hořelo ve mně srdce mé, roznícen jest oheň v přemyšlování mém, tak že jsem mluvil jazykem svým, řka:'),
(1560729,54,19,39,5,'Dej mi znáti, Hospodine, konec života mého, a odměření dnů mých jaké jest, abych věděl, jak dlouho trvati mám.'),
(1560730,54,19,39,6,'Aj, na dlaň odměřil jsi mi dnů, a věk můj jest jako nic před tebou, a jistě žeť není než pouhá marnost každý člověk, jakkoli pevně stojící. Sélah.'),
(1560731,54,19,39,7,'Jistě tak pomíjí člověk jako stín, nadarmo zajisté kvaltuje se; shromažďuje, a neví, kdo to pobéře.'),
(1560732,54,19,39,8,'Načež bych tedy nyní očekával, Pane? Očekávání mé jest na tebe.'),
(1560733,54,19,39,9,'A protož ode všech přestoupení mých vysvoboď mne, za posměch bláznu nevystavuj mne.'),
(1560734,54,19,39,10,'Oněměl jsem, a neotevřel úst svých, proto že jsi ty učinil to.'),
(1560735,54,19,39,11,'Odejmi ode mne metlu svou, nebo od švihání ruky tvé docela zhynul jsem.'),
(1560736,54,19,39,12,'Ty, když žehráním pro nepravost tresceš člověka, hned jako mol k zetlení přivodíš zdárnost jeho; marnost zajisté jest všeliký člověk. Sélah.'),
(1560737,54,19,39,13,'Vyslyšiž modlitbu mou, Hospodine, a volání mé přijmi v uši své; neodmlčujž se kvílení mému, nebo jsem příchozí a podruh u tebe, jako i všickni otcové moji.'),
(1560738,54,19,39,14,'Ponechej mne, ať se posilím, prvé než bych se odebral, a již zde více nebyl.'),
(1560739,54,19,40,1,'Přednímu zpěváku, Davidův žalm.'),
(1560740,54,19,40,2,'Žádostivě očekával jsem na Hospodina, i naklonil se ke mně, a vyslyšel mé volání.'),
(1560741,54,19,40,3,'A vytáhl mne z čisterny hlučící, i z bláta bahnivého, a postavil na skále nohy mé, a kroky mé utvrdil.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560742,54,19,40,4,'A tak vložil v ústa má píseň novou, chválu Bohu našemu, což když uhlédají mnozí, i báti se, i doufání skládati budou v Hospodinu.'),
(1560743,54,19,40,5,'Blahoslavený ten člověk, kterýž skládá v Hospodinu svou naději, a neohlédá se na pyšné, ani na ty, kteříž se ke lži uchylují.'),
(1560744,54,19,40,6,'Mnohé věci činíš ty, Hospodine Bože můj, a divní jsou skutkové tvoji i myšlení tvá o nás; není, kdo by je pořád vyčísti mohl před tebou. Já chtěl-li bych je vymluviti a vypraviti, mnohem více jich jest, nežli vypraveno býti může.'),
(1560745,54,19,40,7,'Oběti a daru neoblíbils, ale uši jsi mi otevřel; zápalu a oběti za hřích nežádal jsi.'),
(1560746,54,19,40,8,'Tehdy řekl jsem: Aj, jduť, jakož v knihách psáno jest o mně.'),
(1560747,54,19,40,9,'Abych činil vůli tvou, Bože můj, líbost mám; nebo zákon tvůj jest u prostřed vnitřností mých.'),
(1560748,54,19,40,10,'Ohlašoval jsem spravedlnost v shromáždění velikém; aj, rtů svých že jsem nezdržoval, ty znáš, Hospodine.'),
(1560749,54,19,40,11,'Spravedlnosti tvé neukryl jsem u prostřed srdce svého, pravdu tvou a spasení tvé vypravoval jsem, nezatajil jsem milosrdenství tvého a pravdy tvé v shromáždění velikém.'),
(1560750,54,19,40,12,'Ty pak, Hospodine, nevzdaluj slitování svých ode mne; milosrdenství tvé a pravda tvá vždycky ať mne ostříhají.'),
(1560751,54,19,40,13,'Neboť jsou mne obklíčily zlé věci, jimž počtu není; dostihly mne mé nepravosti, tak že prohlédnouti nemohu; rozmnožily se nad počet vlasů hlavy mé, a srdce mé opustilo mne.'),
(1560752,54,19,40,14,'Račiž ty mne, Hospodine, vysvoboditi; Hospodine, pospěšiž ku pomoci mé.'),
(1560753,54,19,40,15,'Zahanbeni buďte, a zapyřte se všickni, kteříž hledají duše mé, aby ji zahladili; zpět obráceni a v potupu dáni buďte, kteříž líbost mají v neštěstí mém.'),
(1560754,54,19,40,16,'Přijdiž na ně spuštění za to, že mne k hanbě přivésti usilují, říkajíce: Hahá, hahá.'),
(1560755,54,19,40,17,'Ale ať radují a veselí se v tobě všickni hledající tebe, a milující spasení tvé ať říkají vždycky: Veleslaven budiž Hospodin.'),
(1560756,54,19,40,18,'Já pak ačkoli chudý a nuzný jsem, Pán však pečuje o mne. Pomoc má a vysvoboditel můj ty jsi. Bože můj, neprodlévejž.'),
(1560757,54,19,41,1,'Přednímu zpěváku, žalm Davidův.'),
(1560758,54,19,41,2,'Blahoslavený, kdož prozřetelný soud činí o chudém; v den zlý vysvobodí jej Hospodin.'),
(1560759,54,19,41,3,'Hospodin ho ostřeže, a obživí jej; blažený bude na zemi, aniž ho vydá líbosti nepřátel jeho.'),
(1560760,54,19,41,4,'Hospodin ho na ložci ve mdlobě posilí, všecko ležení jeho v nemoci jeho promění.'),
(1560761,54,19,41,5,'Já řekl jsem: Hospodine, smiluj se nade mnou, uzdrav duši mou, nebo jsem tobě zhřešil.'),
(1560762,54,19,41,6,'Nepřátelé moji mluvili zle o mně, řkouce: Skoro-liž umřel, a zahyne jméno jeho?'),
(1560763,54,19,41,7,'A jestliže kdo z nich přichází, aby mne navštívil, pochlebenství mluví; srdce jeho sbírá sobě nepravost, a vyjda ven, roznáší ji.'),
(1560764,54,19,41,8,'Sšeptávají se spolu proti mně všickni, kteříž mne nenávidí, a přičítají mi zlé věci, říkajíce:'),
(1560765,54,19,41,9,'Pomsta pro nešlechetnost přichytila se ho, a kdyžtě se složil nepovstaneť zase.'),
(1560766,54,19,41,10,'Také i ten, s nímž jsem byl v přátelství, jemuž jsem se dověřoval, a kterýž jídal chléb můj, pozdvihl paty proti mně.'),
(1560767,54,19,41,11,'Ale ty, Hospodine, smiluj se nade mnou, a pozdvihni mne, a odplatím jim;'),
(1560768,54,19,41,12,'Abych odtud poznal, že mne sobě libuješ, když by se neradoval nade mnou nepřítel můj.'),
(1560769,54,19,41,13,'Mne pak v upřímnosti mé zachováš, a postavíš před oblíčejem svým na věky.'),
(1560770,54,19,41,14,'Požehnaný Hospodin Bůh Izraelský, od věků až na věky, Amen i Amen.'),
(1560771,54,19,42,1,'Přednímu zpěváku z synů Chóre, žalm vyučující.'),
(1560772,54,19,42,2,'Jakož jelen řve, dychtě po tekutých vodách, tak duše má řve k tobě, ó Bože.'),
(1560773,54,19,42,3,'Žízní duše má Boha, Boha živého, a říká: Skoro-liž půjdu, a ukáži se před oblíčejem Božím?'),
(1560774,54,19,42,4,'Slzy mé jsou mi místo chleba dnem i nocí, když mi říkají každého dne: Kdež jest Bůh tvůj?'),
(1560775,54,19,42,5,'Na to když se rozpomínám, téměř duši svou sám v sobě vylévám, že jsem chodíval s mnohými, a ubírával jsem se s nimi do domu Božího s hlasitým zpíváním, a díkčiněním v zástupu plésajících.'),
(1560776,54,19,42,6,'Proč jsi smutná, duše má, a proč se kormoutíš? Posečkej na Boha, neboť ještě vyznávati jej budu, i hojné spasení tváři jeho.'),
(1560777,54,19,42,7,'Můj Bože, jak tesklí duše má! Protož se na tě rozpomínám v krajině Jordánské a Hermonské, na hoře Mitsar.'),
(1560778,54,19,42,8,'Propast propasti se ozývá k hlučení trub tvých, všecka vlnobití tvá a rozvodnění tvá na mne se svalila.'),
(1560779,54,19,42,9,'Věřím však, žeť mi udělí ve dne Hospodin milosrdenství svého, a v noci písnička jeho se mnou, a modlitba má k Bohu života mého.'),
(1560780,54,19,42,10,'Dím k Bohu silnému, skále své: Pročež jsi zapomenul se nade mnou? Proč pro ssoužení od nepřítele v smutku mám choditi?'),
(1560781,54,19,42,11,'Jako rána v kostech mých jest to, když mi utrhají nepřátelé moji, říkajíce mi každého dne: Kdež jest Bůh tvůj?'),
(1560782,54,19,42,12,'Proč jsi smutná, duše má, a proč se kormoutíš ve mně? Posečkej na Boha, neboť ještě vyznávati jej budu; onť jest hojné spasení tváři mé a Bůh můj.'),
(1560783,54,19,43,1,'Suď mne, ó Bože, a zasaď se o mou při; od národu nemilosrdného, a od člověka lstivého a nepravého vytrhni mne.'),
(1560784,54,19,43,2,'Nebo ty jsi Bůh mé síly. Proč jsi mne zapudil? Proč pro ssoužení od nepřítele v smutku mám ustavičně choditi?'),
(1560785,54,19,43,3,'Sešliž světlo své a pravdu svou, to ať mne vodí a zprovodí na horu svatosti tvé a do příbytků tvých,'),
(1560786,54,19,43,4,'Abych přistoupil k oltáři Božímu, k Bohu radostného plésání mého, a budu tě oslavovati na harfě, ó Bože, Bože můj.'),
(1560787,54,19,43,5,'Proč jsi smutná, duše má, a proč se kormoutíš ve mně? Posečkej na Boha, neboť ještě vyznávati jej budu; onť jest hojné spasení tváři mé a Bůh můj.'),
(1560788,54,19,44,1,'Přednímu zpěváku z synů Chóre, vyučující.'),
(1560789,54,19,44,2,'Bože, ušima svýma slýchali jsme, a otcové naši vypravovali nám o skutcích, kteréž jsi činíval za dnů jejich, za dnů starodávních.'),
(1560790,54,19,44,3,'Tys sám rukou svou vyhnal pohany, a vštípil jsi je; potřel jsi lidi, a je jsi rozplodil.'),
(1560791,54,19,44,4,'Neboť jsou neopanovali země mečem svým, aniž jim rámě jejich spomohlo, ale pravice tvá a rámě tvé, a světlost oblíčeje tvého, proto že jsi je zamiloval.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560792,54,19,44,5,'Ty jsi sám král můj, ó Bože, udílejž hojného spasení Jákobova.'),
(1560793,54,19,44,6,'V toběť jsme protivníky naše potírali, a ve jménu tvém pošlapávali jsme povstávající proti nám.'),
(1560794,54,19,44,7,'Neboť jsem v lučišti svém naděje neskládal, aniž mne kdy obránil meč můj.'),
(1560795,54,19,44,8,'Ale ty jsi nás vysvobozoval od nepřátel našich, a kteříž nás nenávidí, ty jsi zahanboval.'),
(1560796,54,19,44,9,'A protož chválíme tě Boha na každý den, a jméno tvé ustavičně oslavujeme. Sélah.'),
(1560797,54,19,44,10,'Ale nyní jsi nás zahnal i zahanbil, a nevycházíš s vojsky našimi.'),
(1560798,54,19,44,11,'Obrátil jsi nás nazpět, a ti, kteříž nás nenávidí, rozchvátali mezi sebou jmění naše.'),
(1560799,54,19,44,12,'Oddal jsi nás, jako ovce k snědení, i mezi pohany rozptýlil jsi nás.'),
(1560800,54,19,44,13,'Prodal jsi lid svůj bez peněz, a nenadsadils mzdy jejich.'),
(1560801,54,19,44,14,'Vydal jsi nás k utrhání sousedům našim, ku posměchu a ku potupě těm, kteříž jsou vůkol nás.'),
(1560802,54,19,44,15,'Uvedl jsi nás v přísloví mezi národy, a mezi lidmi, aby nad námi hlavou zmítáno bylo.'),
(1560803,54,19,44,16,'Na každý den styděti se musím, a hanba tváři mé přikrývá mne,'),
(1560804,54,19,44,17,'A to z příčiny řeči utrhajícího a hanějícího, z příčiny nepřítele a vymstívajícího se.'),
(1560805,54,19,44,18,'Všecko to přišlo na nás, a však jsme se nezapomenuli na tě, aniž jsme zrušili smlouvy tvé.'),
(1560806,54,19,44,19,'Neobrátilo se nazpět srdce naše, aniž se uchýlil krok náš od stezky tvé,'),
(1560807,54,19,44,20,'Ačkoli jsi nás byl potřel na místě draků, a přikryl jsi nás stínem smrti.'),
(1560808,54,19,44,21,'Kdybychom se byli zapomenuli na jméno Boha svého, a pozdvihli rukou svých k bohu cizímu,'),
(1560809,54,19,44,22,'Zdaliž by toho Bůh byl nevyhledával? Nebo on zná skrytosti srdce.'),
(1560810,54,19,44,23,'Anobrž pro tebe mordováni býváme každého dne, jmíni jsme jako ovce k zabití oddané.'),
(1560811,54,19,44,24,'Procitiž, proč spíš, ó Pane? Probudiž se, a nezaháněj nás na věky.'),
(1560812,54,19,44,25,'I pročež tvář svou skrýváš, a zapomínáš se na trápení a ssoužení naše?'),
(1560813,54,19,44,26,'Nebotě se již sklonila až k prachu duše naše, přilnul k zemi život náš.'),
(1560814,54,19,44,27,'Povstaniž k našemu spomožení, a vykup nás pro své milosrdenství.'),
(1560815,54,19,45,1,'Přednímu kantoru z synů Chóre, na šošannim, vyučující. Píseň o lásce.'),
(1560816,54,19,45,2,'Vyneslo srdce mé slovo dobré, vypravovati budu písně své o králi, jazyk můj jako péro hbitého písaře.'),
(1560817,54,19,45,3,'Krásnější jsi nad všecky syny lidské, rozlita jest i milost ve rtech tvých, proto že jest tobě požehnal Bůh až na věky.'),
(1560818,54,19,45,4,'Připaš meč svůj na bedra, ó reku udatný, prokaž důstojnost a slávu svou.'),
(1560819,54,19,45,5,'A v té slávě své šťastně vyjížděj s slovem pravdy, tichosti a spravedlnosti, a dokáže pravice tvá hrozných věcí.'),
(1560820,54,19,45,6,'Střely tvé jsou ostré, padati budou od nich před tebou národové, proniknou až k srdci nepřátel královských.'),
(1560821,54,19,45,7,'Trůn tvůj, ó Bože, jest věčný a stálý, berla království tvého jestiť berla nejupřímější.'),
(1560822,54,19,45,8,'Miluješ spravedlnost, a nenávidíš bezbožnosti, protož pomazal tě, Bože, Bůh tvůj olejem veselé nad účastníky tvé.'),
(1560823,54,19,45,9,'Mirra, aloe a kassia, všecka roucha tvá voní z paláců, z kostí slonových vzdělaných, nad ty, jenž tě obveselují.'),
(1560824,54,19,45,10,'Dcery králů jsou mezi vzácnými tvými, přístojíť i manželka tobě po pravici v ryzím zlatě.'),
(1560825,54,19,45,11,'Slyšiž, dcerko, a viz, a nakloň ucha svého, a zapomeň na lid svůj a na dům otce svého.'),
(1560826,54,19,45,12,'I zalíbí se králi tvá krása; onť jest zajisté Pán tvůj, protož skláněj se před ním.'),
(1560827,54,19,45,13,'Tuť i Tyrští s dary, před oblíčejem tvým kořiti se budou bohatí národové.'),
(1560828,54,19,45,14,'Všecka slavná jest dcera královská u vnitřku, roucho zlatem vytkávané jest oděv její.'),
(1560829,54,19,45,15,'V rouše krumpovaném přivedena bude králi, i panny za ní, družičky její, přivedeny budou k tobě.'),
(1560830,54,19,45,16,'Přivedeny budou s radostí velikou a plésáním, a vejdou na palác královský.'),
(1560831,54,19,45,17,'Místo otců svých budeš míti syny své, kteréž postavíš za knížata po vší zemi.'),
(1560832,54,19,45,18,'V pamět uvoditi budu jméno tvé po všecky věky, pročež oslavovati tě budou národové na věky věků.'),
(1560833,54,19,46,1,'Přednímu kantoru z synů Chóre, píseň na alamot.'),
(1560834,54,19,46,2,'Bůh jest naše útočiště i síla, ve všelikém ssoužení pomoc vždycky hotová.'),
(1560835,54,19,46,3,'A protož nebudeme se báti, byť se pak i země podvrátila, a zpřevracely se hory do prostřed moře.'),
(1560836,54,19,46,4,'Byť i ječely, a kormoutily se vody jeho, a hory se rozrážely od dutí jeho. Sélah.'),
(1560837,54,19,46,5,'Potok a pramenové jeho obveselují město Boží, nejsvětější z příbytků Nejvyššího.'),
(1560838,54,19,46,6,'Bůh jest u prostřed něho, nepohneť se; přispějeť jemu Bůh na pomoc hned v jitře.'),
(1560839,54,19,46,7,'Když hlučeli národové, a pohnula se království, vydal hlas svůj, a rozplynula se země.'),
(1560840,54,19,46,8,'Hospodin zástupů jest s námi, hradem vysokým jest nám Bůh Jákobův. Sélah.'),
(1560841,54,19,46,9,'Poďte, vizte skutky Hospodinovy, jakýchť jest pustin nadělal na zemi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560842,54,19,46,10,'Přítrž činí bojům až do končin země, lučiště láme, kopí posekává, a vozy spaluje ohněm,'),
(1560843,54,19,46,11,'Mluvě: Upokojtež se, a vězte, žeť jsem já Bůh, kterýž vyvýšen budu mezi národy, vyvýšen budu na zemi.'),
(1560844,54,19,46,12,'Hospodin zástupů jest s námi, hradem vysokým jest nám Bůh Jákobův. Sélah.'),
(1560845,54,19,47,1,'Přednímu zpěváku z synů Chóre, žalm.'),
(1560846,54,19,47,2,'Všickni národové plésejte rukama, trubte Bohu s hlasitým prozpěvováním.'),
(1560847,54,19,47,3,'Nebo Hospodin nejvyšší, hrozný, jest král veliký nade vší zemi.'),
(1560848,54,19,47,4,'Uvozuje lidi v moc naši, a národy pod nohy naše.'),
(1560849,54,19,47,5,'Oddělil nám za dědictví naše slávu Jákobovu, kteréhož miloval. Sélah.'),
(1560850,54,19,47,6,'Vstoupil Bůh s troubením, Hospodin s zvukem trouby.'),
(1560851,54,19,47,7,'Žalmy zpívejte Bohu, zpívejte; zpívejte žalmy králi našemu, zpívejte.'),
(1560852,54,19,47,8,'Nebo král vší země Bůh jest, zpívejte žalmy rozumně.'),
(1560853,54,19,47,9,'Kralujeť Bůh nad národy, Bůh sedí na trůnu svém svatém.'),
(1560854,54,19,47,10,'Knížata národů připojili se k lidu Boha Abrahamova; nebo pavézy země Boží jsou, pročež on náramně vyvýšen jest.'),
(1560855,54,19,48,1,'Píseň žalmu synů Chóre.'),
(1560856,54,19,48,2,'Veliký jest Hospodin, a převelmi chvalitebný v městě Boha našeho, na hoře svatosti své.'),
(1560857,54,19,48,3,'Ozdoba krajiny, útěcha vší země jestiť hora Sion, k straně půlnoční, město krále velikého.'),
(1560858,54,19,48,4,'Bůh na palácích jeho, a znají ho býti vysokým hradem.'),
(1560859,54,19,48,5,'Nebo aj, králové když se shromáždili a spolu táhli,'),
(1560860,54,19,48,6,'Sami to uzřevše, velmi se divili, a předěšeni byvše, náhle utíkali.'),
(1560861,54,19,48,7,'Tuť jest je strach popadl, a bolest jako ženu rodící.'),
(1560862,54,19,48,8,'Větrem východním rozrážíš lodí Tarské.'),
(1560863,54,19,48,9,'Jakž jsme slýchali, tak jsme spatřili, v městě Hospodina zástupů, v městě Boha našeho. Bůh upevní je až na věky.'),
(1560864,54,19,48,10,'Rozjímáme, ó Bože, milosrdenství tvé u prostřed chrámu tvého.'),
(1560865,54,19,48,11,'Jakož jméno tvé, Bože, tak i chvála tvá až do končin země; pravice tvá zajisté plná jest spravedlnosti.'),
(1560866,54,19,48,12,'Raduj se, horo Sione, plésejte, dcery Judské, z příčiny soudů Božích.'),
(1560867,54,19,48,13,'Obejděte Sion, a obstupte jej, sečtěte věže jeho.'),
(1560868,54,19,48,14,'Přiložte mysl svou k ohradě, popatřte na paláce jeho, abyste uměli vypravovati věku potomnímu,'),
(1560869,54,19,48,15,'Že tento Bůh jest Bůh náš na věčné věky, a že on vůdce náš bude až do smrti.'),
(1560870,54,19,49,1,'Přednímu kantoru z synů Chóre, žalm.'),
(1560871,54,19,49,2,'Slyšte to všickni národové, pozorujte všickni obyvatelé zemští.'),
(1560872,54,19,49,3,'Tak z lidu obecného, jako z povýšených, tak bohatý, jako chudý.'),
(1560873,54,19,49,4,'Ústa má mluviti budou moudrost, a přemyšlování srdce mého rozumnost.'),
(1560874,54,19,49,5,'Nakloním k přísloví ucha svého, a při harfě vykládati budu přípovídku svou.'),
(1560875,54,19,49,6,'I proč se báti mám ve dnech zlých, aby nepravost těch, kteříž mi na paty šlapají, mne obklíčiti měla?'),
(1560876,54,19,49,7,'Kteříž doufají v svá zboží, a množstvím bohatství svého se chlubí.'),
(1560877,54,19,49,8,'Žádný bratra svého nijakž vykoupiti nemůže, ani Bohu za něj dáti mzdy vyplacení,'),
(1560878,54,19,49,9,'(Neboť by velmi drahé musilo býti vyplacení duše jejich, protož nedovedeť toho na věky),'),
(1560879,54,19,49,10,'Aby živ byl věčně, a neviděl porušení.'),
(1560880,54,19,49,11,'Nebo se vídá, že i moudří umírají, blázen a hovadný člověk zaroveň hynou, zboží svého i cizím zanechávajíce.'),
(1560881,54,19,49,12,'Myšlení jejich jest, že domové jejich věční jsou, a příbytkové jejich od národu do pronárodu; pročež je po krajinách nazývají jmény svými.'),
(1560882,54,19,49,13,'Ale člověk v slávě netrvá, jsa podobný hovadům, kteráž hynou.'),
(1560883,54,19,49,14,'Taková snažnost jejich jest bláznovstvím při nich, však potomci jejich ústy svými to schvalují. Sélah.'),
(1560884,54,19,49,15,'Jako hovada v pekle skladeni budou, smrt je žráti bude, ale upřímí panovati budou nad nimi v jitře; způsob pak oněchno aby zvetšel, z příbytku svého octnou se v hrobě.'),
(1560885,54,19,49,16,'Ale Bůh vykoupí duši mou z moci pekla, když mne přijme. Sélah.'),
(1560886,54,19,49,17,'Neboj se, když by někdo zbohatl, a když by se rozmnožila sláva domu jeho.'),
(1560887,54,19,49,18,'Při smrti zajisté ničeho nevezme, aniž sstoupí za ním sláva jeho.'),
(1560888,54,19,49,19,'Ačťkoli duši své, pokudž jest živ, lahodí; k tomu chválí jej i jiní, když sobě čistě povoluje:'),
(1560889,54,19,49,20,'A však musí se odebrati za věkem otců svých, a na věky světla neuzří.'),
(1560890,54,19,49,21,'Summou: Člověk jsa ve cti, neusrozumí-li sobě, bývá učiněn podobný hovadům, kteráž hynou.'),
(1560891,54,19,50,1,'Žalm Azafovi. Bůh silný, Bůh Hospodin mluvil, a přivolal zemi od východu slunce i od západu jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560892,54,19,50,2,'Z Siona v dokonalé kráse Bůh zastkvěl se.'),
(1560893,54,19,50,3,'Béřeť se Bůh náš, a nebude mlčeti; oheň před ním vše zžírati bude, a vůkol něho vichřice náramná.'),
(1560894,54,19,50,4,'Zavolal nebes s hůry i země, aby soudil lid svůj, řka:'),
(1560895,54,19,50,5,'Shromažďte mi svaté mé, kteříž smlouvu se mnou učinili při obětech.'),
(1560896,54,19,50,6,'I budou vypravovati nebesa spravedlnost jeho; nebo sám Bůh soudce jest. Sélah.'),
(1560897,54,19,50,7,'Slyš, lide můj, a buduť mluviti, Izraeli, a buduť tebou osvědčovati. Já zajisté Bůh, Bůh tvůj jsem.'),
(1560898,54,19,50,8,'Nechci tě obviňovati z příčiny obětí tvých, ani zápalů tvých, že by vždycky přede mnou nebyli.'),
(1560899,54,19,50,9,'Nevezmuť z domu tvého volka, ani z chlévů tvých kozlů.'),
(1560900,54,19,50,10,'Nebo má jest všecka zvěř lesní, i hovada na tisíci horách.'),
(1560901,54,19,50,11,'Já znám všecko ptactvo po horách, a zvěř polní před sebou mám.'),
(1560902,54,19,50,12,'Zlačním-li, nic tobě o to nedím; nebo můj jest okršlek zemský i plnost jeho.'),
(1560903,54,19,50,13,'Zdaliž jídám maso z volů, a pijím krev kozlovou?'),
(1560904,54,19,50,14,'Obětuj Bohu obět chvály, a plň Nejvyššímu své sliby;'),
(1560905,54,19,50,15,'A vzývej mne v den ssoužení, vytrhnu tě, a ty mne budeš slaviti.'),
(1560906,54,19,50,16,'Sic jinak bezbožníku praví Bůh: Což tobě do toho, že ty vypravuješ ustanovení má, a béřeš smlouvu mou v ústa svá,'),
(1560907,54,19,50,17,'Poněvadž jsi vzal v nenávist kázeň, a zavrhl jsi za sebe slova má.'),
(1560908,54,19,50,18,'Vidíš-li zloděje, hned s ním běžíš, a s cizoložníky díl svůj máš.'),
(1560909,54,19,50,19,'Ústa svá pouštíš ke zlému, a jazyk tvůj skládá lest.'),
(1560910,54,19,50,20,'Usazuješ se, a mluvíš proti bratru svému, a na syna matky své lehkost uvodíš.'),
(1560911,54,19,50,21,'To jsi činil, a já mlčel jsem. Měl-liž jsi ty se domnívati, že já tobě podobný budu? Nýbrž trestati tě budu, a představímť to před oči tvé.'),
(1560912,54,19,50,22,'Srozumějtež tomu již aspoň vy, kteříž se zapomínáte na Boha, abych snad nepochytil, a nebyl by, kdo by vytrhl.'),
(1560913,54,19,50,23,'Kdož obětuje obět chvály, tenť mne uctí, a tomu, kdož napravuje cestu svou, ukáži spasení Boží.'),
(1560914,54,19,51,1,'Přednímu z kantorů, žalm Davidův,'),
(1560915,54,19,51,2,'Když k němu přišel Nátan prorok, po jeho vjití k Betsabé.'),
(1560916,54,19,51,3,'Smiluj se nade mnou, Bože, podlé milosrdenství svého, podlé množství slitování svých shlaď přestoupení má.'),
(1560917,54,19,51,4,'Dokonale obmej mne od nepravosti mé, a od hříchu mého očisť mne.'),
(1560918,54,19,51,5,'Nebo já znám přestoupení svá, a hřích můj přede mnou jest ustavičně.'),
(1560919,54,19,51,6,'Tobě, tobě samému, zhřešil jsem, a zlého se před očima tvýma dopustil, abys spravedlivý zůstal v řečech svých, a bez úhony v soudech svých.'),
(1560920,54,19,51,7,'Aj, v nepravosti zplozen jsem, a v hříchu počala mne matka má.'),
(1560921,54,19,51,8,'Aj, ty libuješ pravdu u vnitřnostech, nadto skrytou moudrost zjevil jsi mi.'),
(1560922,54,19,51,9,'Vyčisť mne yzopem, a očištěn budu, umej mne, a nad sníh bělejší budu.'),
(1560923,54,19,51,10,'Dej mi slyšeti radost a potěšení, tak ať zpléší kosti mé, kteréž jsi potřel.'),
(1560924,54,19,51,11,'Odvrať tvář svou přísnou od hříšností mých, a vymaž všecky nepravosti mé.'),
(1560925,54,19,51,12,'Srdce čisté stvoř mi, ó Bože, a ducha přímého obnov u vnitřnostech mých.'),
(1560926,54,19,51,13,'Nezamítej mne od tváři své, a Ducha svatého svého neodjímej ode mne.'),
(1560927,54,19,51,14,'Navrať mi radost spasení svého, a duchem dobrovolným utvrď mne.'),
(1560928,54,19,51,15,'I budu vyučovati přestupníky cestám tvým, aby hříšníci k tobě se obraceli.'),
(1560929,54,19,51,16,'Vytrhni mne z pomsty pro vylití krve, ó Bože, Bože spasiteli můj, a budeť s veselím prozpěvovati jazyk můj o spravedlnosti tvé.'),
(1560930,54,19,51,17,'Pane, rty mé otevři, i budou ústa má zvěstovati chválu tvou.'),
(1560931,54,19,51,18,'Nebo neoblíbil bys oběti, bychť ji i dal, aniž bys zápalu přijal.'),
(1560932,54,19,51,19,'Oběti Boží duch skroušený; srdcem skroušeným a potřebným, Bože, nezhrzíš.'),
(1560933,54,19,51,20,'Dobrotivě nakládej z milosti své s Sionem, vzdělej zdi Jeruzalémské.'),
(1560934,54,19,51,21,'A tehdáž sobě zalíbíš oběti spravedlnosti, zápaly a pálení celých obětí, tehdážť voly na oltáři tvém obětovati budou.'),
(1560935,54,19,52,1,'Přednímu z kantorů, vyučující žalm Davidův.'),
(1560936,54,19,52,2,'Když přišel Doeg Idumejský, a zvěstoval Saulovi, a pověděl mu, že David všel do domu Achimelechova.'),
(1560937,54,19,52,3,'Proč se chlubíš nešlechetností, ty mocný? Milosrdenstvíť Boha silného trvá každého dne.'),
(1560938,54,19,52,4,'Těžkosti obmýšlí jazyk tvůj, tak jako břitva nabroušená lest provodí.'),
(1560939,54,19,52,5,'Miluješ zlé více než dobré, raději lež mluvíš než spravedlnost. Sélah.'),
(1560940,54,19,52,6,'Miluješ všelijaké řeči k sehlcení, a jazyk ošemetný.'),
(1560941,54,19,52,7,'I tebeť Bůh silný zkazí na věky, pochytí tě, a vytrhne tě z stánku, a vykoření z země živých. Sélah.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560942,54,19,52,8,'Což spravedliví vidouce, budou se báti a jemu posmívati:'),
(1560943,54,19,52,9,'Aj, toť jest ten člověk, kterýž neskládal v Bohu síly své, ale doufaje ve množství bohatství svých, zmocňoval se v zlosti své.'),
(1560944,54,19,52,10,'Já pak budu jako oliva zelenající se v domě Božím; neboť jsem naději složil v milosrdenství Božím na věky věků.'),
(1560945,54,19,52,11,'Oslavovati tě budu, Pane, na věky, že jsi to učinil, a poshovím na jméno tvé, neboť jest vzácné před oblíčejem svatých tvých.'),
(1560946,54,19,53,1,'Přednímu z kantorů na machalat, vyučující žalm Davidův.'),
(1560947,54,19,53,2,'Říká blázen v srdci svém: Není Boha. Porušeni jsou, a ohavnou páší nepravost; není, kdo by činil dobré.'),
(1560948,54,19,53,3,'Bůh s nebe popatřil na syny lidské, aby viděl, byl-li by kdo rozumný a hledající Boha.'),
(1560949,54,19,53,4,'Aj, každý z nich nazpět odšel, napořád neužiteční učiněni jsou; není, kdo by činil dobré, není ani jednoho.'),
(1560950,54,19,53,5,'Zdaliž nevědí všickni činitelé nepravosti, lid můj sžírajíce, jako by chléb jedli? Boha pak nevzývají.'),
(1560951,54,19,53,6,'Tuť se náramně strašiti budou, kdež není strachu. Bůh zajisté rozptýlí kosti těch, kteříž tě vojensky oblehli; zahanbíš je, nebo Bůh pohrdl jimi.'),
(1560952,54,19,53,7,'Ó by z Siona dáno bylo spasení Izraelovi. Když Bůh zase přivede zajaté lidu svého, plésati bude Jákob, a veseliti se Izrael.'),
(1560953,54,19,54,1,'Přednímu z kantorů na neginot, vyučující žalm Davidův,'),
(1560954,54,19,54,2,'Když přišli Zifejští, a řekli Saulovi: Nevíš-liž, že se David pokrývá u nás?'),
(1560955,54,19,54,3,'Bože, spasena mne učiň pro jméno své, a v moci své veď při mou.'),
(1560956,54,19,54,4,'Bože, slyš modlitbu mou, pozoruj řeči úst mých.'),
(1560957,54,19,54,5,'Neboť jsou cizí povstali proti mně, a ukrutníci hledají duše mé, nepředstavujíce sobě Boha před oblíčej svůj. Sélah.'),
(1560958,54,19,54,6,'Aj, Bůhť jest spomocník můj; Pán s těmi jest, kteříž jsou podpůrcové života mého.'),
(1560959,54,19,54,7,'Odplať zlým nepřátelům mým, v pravdě své vypleň je, ó Pane.'),
(1560960,54,19,54,8,'I buduť dobrovolně oběti obětovati, slaviti budu jméno tvé, Hospodine, proto že jest dobré.'),
(1560961,54,19,54,9,'Nebo z ssoužení všelikého vytrhl mne Bůh, nýbrž i pomstu nad nepřátely mými vidělo oko mé.'),
(1560962,54,19,55,1,'Přednímu kantoru na neginot, vyučující žalm Davidův.'),
(1560963,54,19,55,2,'Slyš, ó Bože, modlitbu mou, a neskrývej se před prosbou mou.'),
(1560964,54,19,55,3,'Pozoruj a vyslyš mne, neboť naříkám v úpění svém, a kormoutím se,'),
(1560965,54,19,55,4,'A to pro křik nepřítele, pro nátisk bezbožníka; neboť sčítají na mne lživé věci, a s vzteklostí se proti mně postavují.'),
(1560966,54,19,55,5,'Srdce mé bolestí ve mně, a strachové smrti připadli na mne.'),
(1560967,54,19,55,6,'Bázeň a strach přišel na mne, a hrůza přikvačila mne.'),
(1560968,54,19,55,7,'I řekl jsem: Ó bych měl křídla jako holubice, zaletěl bych a poodpočinul.'),
(1560969,54,19,55,8,'Aj, daleko bych se vzdálil, a přebýval bych na poušti. Sélah.'),
(1560970,54,19,55,9,'Pospíšil bych ujíti větru prudkému a vichřici.'),
(1560971,54,19,55,10,'Zkaz je, ó Pane, změť jazyk jejich, neboť jsem spatřil bezpráví a rozbroj v městě.'),
(1560972,54,19,55,11,'Dnem i nocí ty věci je obkličují po zdech jeho, a v prostředku jeho jest nepravost a převrácenost.'),
(1560973,54,19,55,12,'Těžkosti jsou u prostřed něho, aniž vychází chytrost a lest z ulic jeho.'),
(1560974,54,19,55,13,'Nebo ne nějaký nepřítel útržky mi činil, sic jinak snesl bych to; ani ten, kdož mne nenávidí, pozdvihl se proti mně, nebo skryl bych se před ním:'),
(1560975,54,19,55,14,'Ale ty, člověče mně rovný, vůdce můj a domácí můj;'),
(1560976,54,19,55,15,'Ješto jsme spolu mile tajné rady držívali, a do domu Božího společně chodívali.'),
(1560977,54,19,55,16,'Ó by je smrt náhle přikvačila, tak aby za živa sstoupiti musili do pekla; nebo jest nešlechetnost v příbytcích jejich a u prostřed nich.'),
(1560978,54,19,55,17,'Já pak k Bohu volati budu, a Hospodin vysvobodí mne.'),
(1560979,54,19,55,18,'U večer, i ráno, též o poledni modliti se, a nezbedně volati budu, až i vyslyší hlas můj.'),
(1560980,54,19,55,19,'Vykoupíť duši mou, tak aby v pokoji byla před válkou proti mně; nebo veliké množství bylo jich při mně.'),
(1560981,54,19,55,20,'Vyslyšíť Bůh silný, a je ssouží, (neboť sedí od věčnosti, Sélah), proto že nenapravují, aniž se bojí Boha.'),
(1560982,54,19,55,21,'Vztáhl ruce své na ty, kteříž s ním pokoj měli, a zrušil smlouvu svou.'),
(1560983,54,19,55,22,'Libější než máslo byla slova úst jeho, ale v srdci boj; měkčejší nad olej řeči jeho, a však byly jako mečové.'),
(1560984,54,19,55,23,'Uvrz na Hospodina břímě své, a onť opatrovati tě bude, aniž dopustí, aby na věky pohnut byl spravedlivý.'),
(1560985,54,19,55,24,'Ale onyno, ty Bože, svedeš do jámy zatracení; lidé zajisté vražedlní a lstiví nedojdou polovice dnů svých, já pak v tebe doufati budu.'),
(1560986,54,19,56,1,'Přednímu z kantorů, o němé holubici v místech vzdálených, zlatý žalm Davidův, když ho jali Filistinští v Gát.'),
(1560987,54,19,56,2,'Smiluj se nade mnou, ó Bože, nebo mne sehltiti chce člověk; každého dne boj veda, ssužuje mne.'),
(1560988,54,19,56,3,'Sehltiti mne usilují na každý den moji nepřátelé; jistě žeť jest mnoho válčících proti mně, ó Nejvyšší.'),
(1560989,54,19,56,4,'Kteréhokoli dne strach mne obkličuje, v tebe doufám.'),
(1560990,54,19,56,5,'Boha chváliti budu z slova jeho, v Boha doufati budu, aniž se budu báti, aby mi co mohlo učiniti tělo.'),
(1560991,54,19,56,6,'Na každý den slova má převracejí, proti mně jsou všecka myšlení jejich ke zlému.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1560992,54,19,56,7,'Spolu se scházejí, skrývají se, a šlepějí mých šetří, číhajíce na duši mou.'),
(1560993,54,19,56,8,'Za nešlechetnost-liž zniknou pomsty? V prchlivosti, ó Bože, smeceš lidi ty.'),
(1560994,54,19,56,9,'Ty má utíkání v počtu máš, schovej slzy mé do láhvice své, a což bys jich v počtu neměl?'),
(1560995,54,19,56,10,'A tehdyť obráceni budou zpět nepřátelé moji v ten den, když volati budu; toť vím, že Bůh při mně stojí.'),
(1560996,54,19,56,11,'Jáť budu Boha chváliti z slova, Hospodina oslavovati budu z slova jeho.'),
(1560997,54,19,56,12,'V Boha doufám, nebudu se báti, aby mi co učiniti mohl člověk.'),
(1560998,54,19,56,13,'Tobě jsem, Bože, učinil sliby, a protož tobě vzdám chvály.'),
(1560999,54,19,56,14,'Nebo jsi vytrhl z smrti duši mou, a nohy mé od poklesnutí, tak abych stále chodil před Bohem v světle živých.'),
(1561000,54,19,57,1,'Přednímu kantoru, jako: Nevyhlazuj, zlatý žalm Davidův, když utekl před Saulem do jeskyně.'),
(1561001,54,19,57,2,'Smiluj se nade mnou, ó Bože, smiluj se nade mnou; neboť v tebe doufá duše má, a v stínu křídel tvých schráním se, až přejde ssoužení.'),
(1561002,54,19,57,3,'Volati budu k Bohu nejvyššímu, k Bohu silnému, kterýž dokonává za mne.'),
(1561003,54,19,57,4,'Onť pošle s nebe, a zachová mne od potupy usilujícího mne sehltiti. Sélah. Pošle Bůh milosrdenství své a pravdu svou.'),
(1561004,54,19,57,5,'Duše má jest u prostřed lvů, bydlím mezi paliči, mezi lidmi, jejichž zubové kopí a střely, a jazyk jejich jako ostrý meč.'),
(1561005,54,19,57,6,'Vyvyšiž se nad nebesa, ó Bože, a nade všecku zemi sláva tvá.'),
(1561006,54,19,57,7,'Tenata roztáhli nohám mým, sklíčili duši mou, vykopali přede mnou jámu, ale sami upadli do ní. Sélah.'),
(1561007,54,19,57,8,'Hotovo jest srdce mé, Bože, hotovo jest srdce mé, zpívati a oslavovati tě budu.'),
(1561008,54,19,57,9,'Probuď se, slávo má, probuď se, loutno a harfo, když v svitání povstávám.'),
(1561009,54,19,57,10,'Slaviti tě budu mezi lidmi, Pane, žalmy prozpěvovati tobě budu mezi národy.'),
(1561010,54,19,57,11,'Nebo veliké jest až k nebi milosrdenství tvé, a až k nejvyšším oblakům pravda tvá.'),
(1561011,54,19,57,12,'Vyvyšiž se nad nebesa, ó Bože, a nade všecku zemi sláva tvá.'),
(1561012,54,19,58,1,'Přednímu z kantorů, jako: Nevyhlazuj, Davidův žalm zlatý.'),
(1561013,54,19,58,2,'Právě-liž vy, ó shromáždění, spravedlnost vypovídáte? Upřímě-liž soudy činíte, vy synové lidští?'),
(1561014,54,19,58,3,'Anobrž raději nepravosti v srdci ukládáte, a násilí rukou svých v zemi této odvažujete.'),
(1561015,54,19,58,4,'Uchýlili se bezbožníci hned od narození, pobloudili hned od života matky, mluvíce lež.'),
(1561016,54,19,58,5,'Jed v sobě mají jako jedovatý had, jako lítý had hluchý, kterýž zacpává ucho své,'),
(1561017,54,19,58,6,'Aby neslyšel hlasu zaklinačů, a čarodějníka v čářích vycvičeného.'),
(1561018,54,19,58,7,'Ó Bože, potři jim zuby v ústech jejich, střenovní zuby lvíčat těch polámej, Hospodine.'),
(1561019,54,19,58,8,'Nechť se rozplynou jako voda, a zmizejí; ať jsou jako ten, kterýž napíná luk, jehož však střely se lámí,'),
(1561020,54,19,58,9,'Jako hlemejžď, kterýž tratí se a mizí, jako nedochůdče ženy, ješto nespatřilo slunce.'),
(1561021,54,19,58,10,'Prvé než lidé pocítí trní jejich a bodláku, hned za živa zapálením jako vichřicí zachváceni budou.'),
(1561022,54,19,58,11,'I bude se veseliti spravedlivý, když uzří pomstu, nohy své umyje ve krvi bezbožníka.'),
(1561023,54,19,58,12,'Ano dí každý: V pravdě, žeť má užitek spravedlivý, jistě, žeť jest Bůh soudce na zemi.'),
(1561024,54,19,59,1,'Přednímu z kantorů, jako: Nevyhlazujž, Davidův žalm zlatý, když poslal Saul, aby střehouc domu, zabili ho.'),
(1561025,54,19,59,2,'Vytrhni mne od nepřátel mých, Bože můj; před těmi, kteříž povstávají proti mně, bezpečna mne učiň.'),
(1561026,54,19,59,3,'Vytrhni mne od těch, kteříž páší nepravost, a od mužů vražedlných zachovej mne.'),
(1561027,54,19,59,4,'Neb aj, zálohy činí duši mé, sbírají se proti mně mocní, bez mého provinění a bez hříchu mého, ó Hospodine.'),
(1561028,54,19,59,5,'Beze vší mé nepravosti sbíhají se, a strojí; povstaniž mně vstříc, a popatř.'),
(1561029,54,19,59,6,'Sám ty, Hospodine Bože zástupů, Bože Izraelský, prociť, abys navštívil všecky národy, aniž se smilovávej nad kterým z těch převrácenců nešlechetných. Sélah.'),
(1561030,54,19,59,7,'Navracejí se k večerou, štěkají jako psi, a běhají okolo města.'),
(1561031,54,19,59,8,'Aj, coť vynášejí ústy svými! Mečové jsou ve rtech jejich, nebo říkají: Zdaliž kdo slyší?'),
(1561032,54,19,59,9,'Ale ty, Hospodine, směješ se jim, posmíváš se všechněm národům.'),
(1561033,54,19,59,10,'Když on moc provozuje, na tebe pozor míti budu, nebo ty, Bože, jsi hrad můj vysoký.'),
(1561034,54,19,59,11,'Bůh mně milosrdný předejdeť mne, Bůh dá mi viděti pomstu nad nepřátely mými.'),
(1561035,54,19,59,12,'Nezbijej jich, aby nezapomněl lid můj, ale zmítej jimi mocí svou, a sházej je, pavézo naše, ó Pane.'),
(1561036,54,19,59,13,'Hřích úst svých, slova rtů svých, (postiženi jsouce v pýše své, pro prokletí a chřadnutí), ať vypravují.'),
(1561037,54,19,59,14,'Zahlaď v prchlivosti, zahlaď je, ať jich není, ať poznají, že Bůh panuje v Jákobovi i do končin země. Sélah.'),
(1561038,54,19,59,15,'I nechažť se pak zase navracejí k večerou, štěkají jako psi, a běhají okolo města.'),
(1561039,54,19,59,16,'Nechať těkají, a potravy hledají, však hladovití jsouce, uložiti se musejí.'),
(1561040,54,19,59,17,'Já pak zpívati budu o síle tvé, hned z jitra hlasitě slaviti budu milosrdenství tvé, nebo jsi byl hrad můj vysoký, a útočiště v den ssoužení mého.'),
(1561041,54,19,59,18,'A posilen jsa, žalmy tobě zpívati budu; nebo jsi Bůh, vysoký hrad můj, Bůh mně milosrdný.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561042,54,19,60,1,'Přednímu z kantorů na šušan eduth, zlatý žalm Davidův, k vyučování,'),
(1561043,54,19,60,2,'Když válku vedl proti Syrii Naharaim, a proti Syrii Soba, kdyžto navrátil se Joáb, pobiv Idumejských v údolí slaném dvanácte tisíců.'),
(1561044,54,19,60,3,'Bože, zavrhl jsi byl nás, roztrhls nás a hněvals se, navratiž se zase k nám.'),
(1561045,54,19,60,4,'Zatřásl jsi byl zemí a roztrhls ji, uzdraviž rozsedliny její, neboť se chvěje.'),
(1561046,54,19,60,5,'Ukazoval jsi lidu svému tvrdé věci, napájels nás vínem zkormoucení.'),
(1561047,54,19,60,6,'Ale nyní dal jsi těm, kteříž se tebe bojí, korouhev, aby ji vyzdvihli pro pravdu tvou. Sélah.'),
(1561048,54,19,60,7,'Ať jsou vysvobozeni milí tvoji, zachovávejž jich pravicí svou, a vyslyš mne.'),
(1561049,54,19,60,8,'Bůh mluvil skrze svatost svou, veseliti se budu, budu děliti Sichem, a údolí Sochot rozměřím.'),
(1561050,54,19,60,9,'Můjť jest Galád, můj i Manasses, a Efraim síla hlavy mé, Juda učitel můj.'),
(1561051,54,19,60,10,'Moáb medenice k umývání mému, na Edoma uvrhu obuv svou, proti mně, Palestino, trub.'),
(1561052,54,19,60,11,'Kdo mne uvede do města ohraženého? Kdo mne zprovodí až do Idumee?'),
(1561053,54,19,60,12,'Zdali ne ty, ó Bože, kterýž jsi nás byl zavrhl, a nevycházels, Bože, s vojsky našimi?'),
(1561054,54,19,60,13,'Uděliž nám pomoci před nepřítelem, nebo marná jest pomoc lidská.'),
(1561055,54,19,60,14,'V Bohu udatně sobě počínati budeme, a onť pošlapá nepřátely naše.'),
(1561056,54,19,61,1,'Přednímu z kantorů na neginot, Davidův.'),
(1561057,54,19,61,2,'Slyš, ó Bože, volání mé, pozoruj modlitby mé.'),
(1561058,54,19,61,3,'Od konce země v sevření srdce svého k tobě volám, na skálu nade mne vyšší uvediž mne.'),
(1561059,54,19,61,4,'Nebo jsi býval mé útočiště, a pevná věže před tváří nepřítele.'),
(1561060,54,19,61,5,'Buduť bydliti v stánku tvém na věky, schráním se v skrýši křídel tvých. Sélah.'),
(1561061,54,19,61,6,'Ty jsi zajisté, Bože, vyslyšel žádosti mé, dal jsi dědictví bojícím se jména tvého.'),
(1561062,54,19,61,7,'Ke dnům krále více dnů přidej, ať jsou léta jeho od národu do pronárodu,'),
(1561063,54,19,61,8,'Ať bydlí na věky před tváří Boží; milosrdenství a pravdu nastroj, ať ho ostříhají.'),
(1561064,54,19,61,9,'A tak žalmy zpívati budu jménu tvému na věky, a sliby své plniti budu den po dni.'),
(1561065,54,19,62,1,'Přednímu z kantorů Jedutunovi, žalm Davidův.'),
(1561066,54,19,62,2,'Vždy předce k Bohu má se mlčelivě duše má, od něhoť jest spasení mé.'),
(1561067,54,19,62,3,'Vždyť předce on jest skála má, mé spasení, vysoký hrad můj, nepohnuť se škodlivě.'),
(1561068,54,19,62,4,'Až dokud zlé obmýšleti budete proti člověku? Všickni vy zahubeni budete, jako zed navážená a stěna nachýlená jste.'),
(1561069,54,19,62,5,'Však nic méně radí se o to, jak by jej odstrčili, aby nebyl vyvýšen; lež oblibují, ústy svými dobrořečí, ale u vnitřnosti své proklínají. Sélah.'),
(1561070,54,19,62,6,'Vždy předce měj se k Bohu mlčelivě, duše má, nebo od něho jest očekávání mé.'),
(1561071,54,19,62,7,'Onť jest zajisté skála má, mé spasení, vysoký hrad můj, nepohnuť se.'),
(1561072,54,19,62,8,'V Bohu jest spasení mé a sláva má; skála síly mé, doufání mé v Bohu jest.'),
(1561073,54,19,62,9,'Naději v něm skládejte všelikého času, ó lidé, vylévejte před oblíčejem jeho srdce vaše, Bůh útočiště naše. Sélah.'),
(1561074,54,19,62,10,'Jistě žeť jsou marnost synové lidští,a synové mocných lživí. Budou-li spolu na váhu vloženi, lehčejší budou nežli marnost.'),
(1561075,54,19,62,11,'Nedoufejtež v utiskování, ani v loupeži, a nebývejte marní; statku přibývalo-li by, nepřikládejte srdce.'),
(1561076,54,19,62,12,'Jednou mluvil Bůh, dvakrát jsem to slyšel, že Boží jest moc,'),
(1561077,54,19,62,13,'A že tvé, Pane, jest milosrdenství, a že ty odplatíš jednomu každému podlé skutků jeho.'),
(1561078,54,19,63,1,'Žalm Davidův, když byl na poušti Judské.'),
(1561079,54,19,63,2,'Bože, Bůh silný můj ty jsi, tebeť hned v jitře hledám, tebe žízní duše má, po tobě touží tělo mé, v zemi žíznivé a vyprahlé, v níž není vody,'),
(1561080,54,19,63,3,'Abych tě v svatyni tvé spatřoval, a viděl sílu tvou a slávu tvou,'),
(1561081,54,19,63,4,'(Neboť jest lepší milosrdenství tvé,nežli život), aby tě chválili rtové moji,'),
(1561082,54,19,63,5,'A tak abych tobě dobrořečil, pokudž jsem živ, a ve jménu tvém pozdvihoval rukou svých.'),
(1561083,54,19,63,6,'Jako tukem a sádlem sytila by se tu duše má, a s radostným rtů prozpěvováním chválila by tě ústa má.'),
(1561084,54,19,63,7,'Jistě žeť na tě pamětliv jsem i na ložci svém, každého bdění nočního přemýšlím o tobě.'),
(1561085,54,19,63,8,'Nebo jsi mi býval ku pomoci, protož v stínu křídel tvých prozpěvovati budu.'),
(1561086,54,19,63,9,'Přilnula duše má k tobě, pravice tvá zdržuje mne.'),
(1561087,54,19,63,10,'Pročež ti, kteříž hledají pádu duše mé, sami vejdou do největší hlubokosti země.'),
(1561088,54,19,63,11,'Zabijí každého z nich ostrostí meče, i budou liškám za podíl.'),
(1561089,54,19,63,12,'Král pak veseliti se bude v Bohu, i každý, kdož skrze něho přisahá, chlubiti se bude; nebo ústa mluvících lež zacpána budou.'),
(1561090,54,19,64,1,'Přednímu z kantorů, žalm Davidův.'),
(1561091,54,19,64,2,'Slyš, ó Bože, hlas můj, když naříkám, před hrůzou nepřítele ostříhej života mého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561092,54,19,64,3,'Skrej mne před úklady zlostníků, před zbouřením těch, kteříž páší nepravost,'),
(1561093,54,19,64,4,'Kteříž naostřili jako meč jazyk svůj, naměřili střelu svou, řeč přehořkou.'),
(1561094,54,19,64,5,'Aby stříleli z skrýší na upřímého; nenadále naň vystřelují, aniž se koho bojí.'),
(1561095,54,19,64,6,'Zatvrzují se ve zlém, smlouvají se, jak by poléci mohli osídla, a říkají: Kdo je spatří?'),
(1561096,54,19,64,7,'Vyhledávají snažně nešlechetnosti, hyneme od ran přelstivých; takť vnitřnost a srdce člověka hluboké jest.'),
(1561097,54,19,64,8,'Ale jakž Bůh vystřelí na ně prudkou střelu, poraženi budou.'),
(1561098,54,19,64,9,'A ku pádu je přivede vlastní jazyk jejich; vzdálí se jich každý, kdož by je viděl.'),
(1561099,54,19,64,10,'I budou se báti všickni lidé, a ohlašovati skutek Boží, a k srozumívání dílu jeho příčinu dadí.'),
(1561100,54,19,64,11,'Spravedlivý pak veseliti se bude v Hospodinu, a v něm doufati, anobrž chlubiti se budou všickni, kteříž jsou upřímého srdce.'),
(1561101,54,19,65,1,'Přednímu z kantorů žalm, Davidova píseň.'),
(1561102,54,19,65,2,'Na tobě přestávati sluší, ó Bože, tebe na Sionu chváliti, a tu tobě slib vyplňovati.'),
(1561103,54,19,65,3,'Tu k tobě modlitbu vyslýchajícímu všeliké tělo přicházeti bude.'),
(1561104,54,19,65,4,'Mnohé nepravosti, kteréž se zmocnily nás, a přestoupení naše ty očistíš.'),
(1561105,54,19,65,5,'Blahoslavený, kohož vyvoluješ, a přivodíš, aby obýval v síňcích tvých. Tuť nasyceni budeme dobrým domu tvého, v svatyni chrámu tvého.'),
(1561106,54,19,65,6,'Předivné věci podlé spravedlnosti nám mluvíš, Bože spasení našeho, naděje všech končin země i moře dalekého,'),
(1561107,54,19,65,7,'Kterýž upevňuješ hory mocí svou,silou jsa přepásán,'),
(1561108,54,19,65,8,'Kterýž skrocuješ zvuk moře, ječení vlnobití jeho, i bouření se národů,'),
(1561109,54,19,65,9,'Tak že se báti musejí obyvatelé končin zázraků tvých, kteréž nastáváním jitra a večera k plésání přivodíš.'),
(1561110,54,19,65,10,'Navštěvuješ zemi a svlažuješ ji, hojně ji obohacuješ. Potok Boží naplňován bývá vodami, i nastrojuješ obilé jejich, když ji tak spravuješ.'),
(1561111,54,19,65,11,'Záhony její svlažuješ, brázdy její snižuješ, dešti ji obměkčuješ, a zrostlinám jejím požehnání dáváš.'),
(1561112,54,19,65,12,'Korunuješ rok dobrotivostí svou, a šlepěje tvé kropí tučností;'),
(1561113,54,19,65,13,'Skropují pastviště po pustinách, tak že i pahrbkové plésáním přepasováni bývají.'),
(1561114,54,19,65,14,'Přiodíny bývají roviny dobytkem, a údolí přistřína obilím, tak že radostí prokřikují, a prozpěvují.'),
(1561115,54,19,66,1,'Přednímu z kantorů, píseň žalmu. Plésej Bohu všecka země.'),
(1561116,54,19,66,2,'Zpívejte žalmy k slávě jména jeho, ohlašujte slávu a chválu jeho.'),
(1561117,54,19,66,3,'Rcete Bohu: Jak hrozný jsi v skutcích svých! Pro velikost síly tvé lháti budou tobě nepřátelé tvoji.'),
(1561118,54,19,66,4,'Všecka země skláněti se tobě a prozpěvovati bude, žalmy zpívati bude jménu tvému. Sélah.'),
(1561119,54,19,66,5,'Poďte a vizte skutky Boží, jak hrozný jest v správě při synech lidských.'),
(1561120,54,19,66,6,'Obrátil moře v suchost, řeku přešli nohou po suše, tuť jsme se veselili v něm.'),
(1561121,54,19,66,7,'Panuje v síle své nade vším světem, oči jeho spatřují národy, zpurní nebudou míti zniku. Sélah.'),
(1561122,54,19,66,8,'Dobrořečte národové Bohu našemu, a ohlašujte hlas chvály jeho.'),
(1561123,54,19,66,9,'Zachoval při životu duši naši, aniž dopustil, aby se poklesla noha naše.'),
(1561124,54,19,66,10,'Nebo jsi nás zpruboval, ó Bože, přečistil jsi nás, tak jako přečištěno bývá stříbro.'),
(1561125,54,19,66,11,'Uvedl jsi nás byl do leči, krutě jsi bedra naše ssoužil,'),
(1561126,54,19,66,12,'Vsadils člověka na hlavu naši, vešli jsme byli do ohně i do vody, a však jsi nás vyvedl do rozvlažení.'),
(1561127,54,19,66,13,'A protož vejdu do domu tvého s zápalnými obětmi, a plniti tobě budu sliby své,'),
(1561128,54,19,66,14,'Kteréž vyřkli rtové moji, a vynesla ústa má, když jsem byl v ssoužení.'),
(1561129,54,19,66,15,'Zápaly tučných beranů obětovati budu tobě s kaděním, volů i kozlů nastrojím tobě. Sélah.'),
(1561130,54,19,66,16,'Poďte, slyšte, a vypravovati budu, kteříž se koli bojíte Boha, co jest učinil duši mé.'),
(1561131,54,19,66,17,'Ústy svými k němu jsem volal, a vyvyšoval jsem ho jazykem svým.'),
(1561132,54,19,66,18,'Bychť byl patřil k nepravosti srdcem svým, nebyl by vyslyšel Pán.'),
(1561133,54,19,66,19,'Ale vyslyšelť Bůh, a pozoroval hlasu modlitby mé.'),
(1561134,54,19,66,20,'Požehnaný Bůh, kterýž neodstrčil modlitby mé, a milosrdenství svého ode mne neodjal.'),
(1561135,54,19,67,1,'Přednějšímu z kantorů na neginot, žalm k zpívání.'),
(1561136,54,19,67,2,'Bože, smiluj se nad námi, a požehnej nám, zasvěť oblíčej svůj nad námi, Sélah,'),
(1561137,54,19,67,3,'Tak aby poznali na zemi cestu tvou, mezi všemi národy spasení tvé.'),
(1561138,54,19,67,4,'I budou tě oslavovati národové, ó Bože, oslavovati tě budou všickni lidé.'),
(1561139,54,19,67,5,'Veseliti se a prozpěvovati budou národové; nebo ty souditi budeš lidi v pravosti, a národy spravovati budeš na zemi. Sélah.'),
(1561140,54,19,67,6,'I budou tě oslavovati národové, ó Bože, oslavovati tě budou všickni lidé.'),
(1561141,54,19,67,7,'Země také vydá úrodu svou. Požehnání svého uděliž nám Bůh, Bůh náš;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561142,54,19,67,8,'Požehnej nás Bůh, a bojtež se jeho všecky končiny země.'),
(1561143,54,19,68,1,'Přednímu z kantorů, Davidův žalm k zpívání.'),
(1561144,54,19,68,2,'Povstane Bůh, a rozprchnou se nepřátelé jeho, a utekou od tváři jeho ti, kteříž ho mají v nenávisti.'),
(1561145,54,19,68,3,'Jakož rozehnán bývá dým, tak je rozženeš; jakož se rozplývá vosk před ohněm, tak bezbožní zahynou před tváří Boží.'),
(1561146,54,19,68,4,'Spravedliví pak veselíce se, poskakovati budou před Bohem, a plésati budou radostí.'),
(1561147,54,19,68,5,'Prozpěvujte Bohu, žalmy zpívejte jménu jeho, vyrovnejte cestu tomu, kterýž se vznáší na oblacích. Hospodin jest jméno jeho, plésejtež před ním.'),
(1561148,54,19,68,6,'Otec jest sirotků a ochránce vdov, Bůh v příbytku svatém svém.'),
(1561149,54,19,68,7,'Bůh samotné rozmnožuje v domy, vyvodí vězně z okovů, zpurní pak bydliti musejí v zemi vyprahlé.'),
(1561150,54,19,68,8,'Bože, když jsi předcházel lid svůj, když jsi kráčel po poušti, Sélah,'),
(1561151,54,19,68,9,'Země se třásla, též i nebesa rozplývala se před tváří Boží, i ta hora Sinai před přítomností Boží, Boha Izraelského.'),
(1561152,54,19,68,10,'Deštěm štědrosti hojné skropoval jsi, Bože, dědictví své, a když zemdlívalo, ty jsi je zase očerstvoval.'),
(1561153,54,19,68,11,'Zástupové tvoji přebývají v něm, kteréžs ty nastrojil dobrotivostí svou pro chudého, ó Bože.'),
(1561154,54,19,68,12,'Pán dal slovo své, i těch, kteréž potěšeně zvěstovaly, zástup veliký, řkoucích:'),
(1561155,54,19,68,13,'Králové s vojsky utíkali, utíkali, a doma hlídající dělily kořisti.'),
(1561156,54,19,68,14,'Ačkoli jste mezi kotly ležeti musili, však jste jako holubice, mající křídla postříbřená, a brky z ryzího zlata.'),
(1561157,54,19,68,15,'Když Všemohoucí rozptýlí krále v této zemi, zbělíš jako sníh na hoře Salmon.'),
(1561158,54,19,68,16,'Hoře veliké, hoře v Bázan, hoře pahrbkovaté, hoře v Bázan.'),
(1561159,54,19,68,17,'Pročež vyskakujete, hory pahrbkovaté? Na tétoť hoře zalíbilo se Bohu přebývati,jistě žeť na ní Hospodin na věky přebývati bude.'),
(1561160,54,19,68,18,'Vozů Božích jest dvadceti tisíců, mnoho tisíců andělů, Pán pak mezi nimi jako na Sinai v svatyni přebývá.'),
(1561161,54,19,68,19,'Vstoupil jsi na výsost, jaté jsi vedl vězně, vzal jsi dary pro lidi. I nejzpurnější k přebývání s námi, Hospodine Bože, přivozuješ.'),
(1561162,54,19,68,20,'Požehnaný Pán, každého dne nás osýpá dary svými, Bůh silný spasení našeho. Sélah.'),
(1561163,54,19,68,21,'Onť jest Bůh silný náš, Bůh silný k hojnému spasení. Hospodin Pán z smrti vyvodí.'),
(1561164,54,19,68,22,'Raní zajisté Bůh hlavu nepřátel svých, a vrch hlavy vlasatý chodícího v hříších svých.'),
(1561165,54,19,68,23,'Řekltě Pán: Zaseť vyvedu své, jako z Bázan, zase vyvedu z hlubokosti mořské.'),
(1561166,54,19,68,24,'A protož noha tvá zbrocena bude ve krvi, i jazyk psů tvých krví nepřátelskou.'),
(1561167,54,19,68,25,'Spatřili slavné jití tvé, Bože, jití silného Boha mého a krále mého v svatyni.'),
(1561168,54,19,68,26,'Napřed šli zpěváci, z zadu hrající na nástroje hudebné, u prostřed pak děvečky bubnující.'),
(1561169,54,19,68,27,'V shromážděních dobrořečte Bohu Pánu, kteříž jste z národu Izraelského.'),
(1561170,54,19,68,28,'Tu ať jest Beniamin maličký, kterýž je opanoval, tu knížata z Judy a houfové jejich, knížata z Zabulona, i knížata z Neftalíma.'),
(1561171,54,19,68,29,'Obdařil tě Bůh tvůj silou. Potvrdiž, Bože, což jsi mezi námi vzdělal,'),
(1561172,54,19,68,30,'Z chrámu svého nad Jeruzalémem, do něhož tobě přinášeti budou králové dary.'),
(1561173,54,19,68,31,'Zahub zástup kopidlníků, sebrání mocných vůdců i lidu bujného, pyšně vykračující s kusy stříbra; rozptyl lidi žádostivé válek.'),
(1561174,54,19,68,32,'Přijdouť nejvzácnější z Egypta, Mouřenínská země rychle vztáhne ruku svou k Bohu.'),
(1561175,54,19,68,33,'Království země zpívejte Bohu, žalmy zpívejte Pánu, Sélah,'),
(1561176,54,19,68,34,'Tomu, kterýž se vznáší nad nebem nebes starodávních; aj, vydává hlas svůj, hlas přemocný.'),
(1561177,54,19,68,35,'Dejte čest síly Bohu, jehož důstojnost nad Izraelem, a velikomocnost jeho na oblacích.'),
(1561178,54,19,68,36,'Přehrozný jsi, ó Bože, z svatých příbytků svých. Bůh silný Izraelský, onť dává moc a sílu lidu svému, Bůh požehnaný.'),
(1561179,54,19,69,1,'Přednímu z kantorů na šošannim, žalm Davidův.'),
(1561180,54,19,69,2,'Vysvoboď mne, ó Bože, neboť jsou dosáhly vody až k duši mé.'),
(1561181,54,19,69,3,'Pohřížen jsem v hlubokém bahně, v němž dna není; všel jsem do hlubokosti vod, jejichž proud zachvátil mne.'),
(1561182,54,19,69,4,'Ustal jsem, volaje, vyschlo hrdlo mé, zemdlely oči mé od ohlídání se na tě Boha svého.'),
(1561183,54,19,69,5,'Více jest těch, kteříž mne nenávidí bez příčiny, než vlasů hlavy mé; zmocnili se ti, kteříž mne vyhladiti usilují, a jsou nepřátelé moji bez mého provinění; to, čehož jsem nevydřel, nahražovati jsem musil.'),
(1561184,54,19,69,6,'Bože, ty znáš sám nemoudrost mou, a výstupkové moji nejsou skryti před tebou.'),
(1561185,54,19,69,7,'Nechť nebývají zahanbeni příčinou mou ti, kteříž na tě očekávají, Pane, Hospodine zástupů; nechť nepřicházejí skrze mne k hanbě ti, kteříž tě hledají, ó Bože Izraelský.'),
(1561186,54,19,69,8,'Neboť pro tebe snáším pohanění, a stud přikryl tvář mou.'),
(1561187,54,19,69,9,'Cizí učiněn jsem bratřím svým, a cizozemec synům matky své,'),
(1561188,54,19,69,10,'Proto že horlivost domu tvého snědla mne, a hanění hanějících tě na mne připadla.'),
(1561189,54,19,69,11,'Když jsem plakal, postem trápiv duši svou, bylo mi to ku potupě obráceno.'),
(1561190,54,19,69,12,'Když jsem bral na se pytel místo roucha, tehdy jsem jim byl za přísloví.'),
(1561191,54,19,69,13,'Pomlouvali mne, sedíce v bráně, a písničkou byl jsem těm, kteříž pili víno.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561192,54,19,69,14,'Já pak modlitbu svou k tobě odsílám, Hospodine, časť jest dobré líbeznosti tvé. Ó Bože, vedlé množství milosrdenství svého vyslyš mne, pro pravdu svou spasitelnou.'),
(1561193,54,19,69,15,'Vytrhni mne z bláta, abych nebyl pohřížen; nechť jsem vytržen od těch, kteříž mne nenávidí, jako z hlubokostí vod,'),
(1561194,54,19,69,16,'Aby mne nezachvátili proudové vod, a nesehltila hlubina, ani se nade mnou zavřela prohlubně.'),
(1561195,54,19,69,17,'Vyslyšiž mne, Hospodine, neboť jest dobré milosrdenství tvé; vedlé množství slitování svých vzhlédniž na mne.'),
(1561196,54,19,69,18,'A neskrývej tváři své od služebníka svého, neboť mám úzkost; rychle vyslyš mne.'),
(1561197,54,19,69,19,'Přibliž se k duši mé, a vyprosť ji; pro nepřátely mé vykup mne.'),
(1561198,54,19,69,20,'Ty znáš pohanění mé, a zahanbení mé, i potupu mou, před tebouť jsou všickni nepřátelé moji.'),
(1561199,54,19,69,21,'Pohanění potřelo srdce mé, pročež jsem byl v žalosti. Očekával jsem, zdali by mne kdo politoval, ale žádného nebylo, zdali by kdo potěšiti chtěli, ale nedočkal jsem.'),
(1561200,54,19,69,22,'Nýbrž místo pokrmu poskytli mi žluči, a v žízni mé napájeli mne octem.'),
(1561201,54,19,69,23,'Budiž jim stůl jejich před nimi za osídlo, a pokojný způsob jejich místo síti.'),
(1561202,54,19,69,24,'Ať se zatmí oči jejich, aby viděti nemohli, a bedra jejich k stálému přiveď zemdlení.'),
(1561203,54,19,69,25,'Vylí na ně rozhněvání své, a prchlivost hněvu tvého ať je zachvátí.'),
(1561204,54,19,69,26,'Budiž příbytek jejich pustý, v staních jejich kdo by obýval, ať není žádného.'),
(1561205,54,19,69,27,'Nebo se tomu, jehož jsi ty zbil, protiví, a o bolesti zraněných tvých rozmlouvají.'),
(1561206,54,19,69,28,'Přilož nepravost k nepravosti jejich, a ať nepřicházejí k spravedlnosti tvé.'),
(1561207,54,19,69,29,'Nechť jsou vymazáni z knihy živých, a s spravedlivými ať nejsou zapsáni.'),
(1561208,54,19,69,30,'Já pak ztrápený jsem, a bolestí sevřený, ale spasení tvé, ó Bože, na místě bezpečném postaví mne.'),
(1561209,54,19,69,31,'I buduť chváliti jméno Boží s prozpěvováním, a velebiti je s děkováním.'),
(1561210,54,19,69,32,'A bude to příjemnější Hospodinu nežli vůl, neb volek rohatý s rozdělenými kopyty.'),
(1561211,54,19,69,33,'To když uhlédají tiší, radovati se budou, hledajíce Boha, a ožive srdce jejich.'),
(1561212,54,19,69,34,'Neboť vyslýchá chudé Hospodin, a vězni svými nezhrzí.'),
(1561213,54,19,69,35,'Chvaltež ho nebesa a země, moře i všeliký hmyz jejich.'),
(1561214,54,19,69,36,'Bůhť zajisté zachová Sion, a vzdělá města Judská, i budou tu bydliti, a zemi tu dědičně obdrží.'),
(1561215,54,19,69,37,'Tolikéž i símě služebníků jeho dědičně jí vládnouti budou, a milující jméno jeho v ní přebývati.'),
(1561216,54,19,70,1,'Přednímu z kantorů, žalm Davidův, k připomínání.'),
(1561217,54,19,70,2,'Bože, abys mne vytrhl, Hospodine, abys mi spomohl, pospěš.'),
(1561218,54,19,70,3,'Zahanbeni buďte, a zapyřte se, kteříž hledají duše mé; zpět obráceni a v potupu dáni buďte, kteříž se kochají v neštěstí mém.'),
(1561219,54,19,70,4,'Zpět obráceni buďte za to, že mne k hanbě přivesti usilují ti, kteříž na mne povolávají: Hahá, hahá.'),
(1561220,54,19,70,5,'Ale ať se radují a veselí v tobě všickni ti, kteříž tě hledají, a ti, kteříž milují spasení tvé, ať říkají vždycky: Veleslaven budiž Bůh náš.'),
(1561221,54,19,70,6,'Já pak chudý a nuzný jsem, ó Bože, pospěšiž ke mně; pomoc má, a vysvoboditel můj ty jsi, neprodlévejž, Hospodine.'),
(1561222,54,19,71,1,'V tebeť, Hospodine, doufám, nechť nejsem zahanben na věky.'),
(1561223,54,19,71,2,'Vedlé spravedlnosti své vytrhni mne, a vyprosť mne; nakloň ke mně ucha svého, a spas mne.'),
(1561224,54,19,71,3,'Budiž mi skalou obydlí, na niž bych ustavičně utíkal; přikázal jsi ostříhati mne, nebo skála má i pevnost má ty jsi.'),
(1561225,54,19,71,4,'Bože můj, vytrhni mne z ruky bezbožníka, z ruky převráceného a násilníka.'),
(1561226,54,19,71,5,'Nebo ty jsi má naděje, Pane; Hospodine, v tebeť doufám od své mladosti.'),
(1561227,54,19,71,6,'Na tebe jsem zpolehl hned od života, z břicha matky mé ty jsi mne vyvedl, v tobě jest chvála má vždycky.'),
(1561228,54,19,71,7,'Jako zázrak byl jsem mnohým, a však ty jsi mé silné doufání.'),
(1561229,54,19,71,8,'Ó ať jsou naplněna ústa má chválením tebe, přes celý den slavením tebe.'),
(1561230,54,19,71,9,'Nezamítejž mne v věku starosti; když zhyne síla má, neopouštějž mne.'),
(1561231,54,19,71,10,'Nebo mluvili nepřátelé moji proti mně, a ti, jenž střehou duše mé, radili se spolu,'),
(1561232,54,19,71,11,'Pravíce: Bůh jej opustil, hoňte a popadněte jej, nebo kdo by ho vytrhl, není žádného.'),
(1561233,54,19,71,12,'Bože, nevzdalujž se ode mne, Bože můj, přispějž mi na pomoc.'),
(1561234,54,19,71,13,'Nechť jsou zahanbeni, a zhynou protivníci duše mé; přikryti buďte lehkostí a hanbou, kteříž hledají pádu mého.'),
(1561235,54,19,71,14,'Já pak ustavičně čekati, a vždy víc a víc tě chváliti budu.'),
(1561236,54,19,71,15,'Ústa má budou vypravovati spravedlnost tvou, každého dne spasení tvé, ačkoli mu počtu nevím.'),
(1561237,54,19,71,16,'Přistoupě k všelijaké moci Panovníka Hospodina, připomínati budu tvou vlastní spravedlnost.'),
(1561238,54,19,71,17,'Bože, učinil jsi mne od mladosti mé, a až po dnes vypravuji o divných činech tvých.'),
(1561239,54,19,71,18,'Protož také i do starosti a šedin, Bože, neopouštěj mne, až v známost uvedu rámě tvé tomuto věku, a všechněm potomkům sílu tvou.'),
(1561240,54,19,71,19,'Nebo spravedlnost tvá, Bože, vyvýšená jest, provodíš zajisté věci veliké. Bože, kdo jest podobný tobě?'),
(1561241,54,19,71,20,'Kterýž ač jsi mi dal okusiti úzkostí velikých a hrozných, však zase k životu navrátíš mne, a z propastí země zase mne vyzdvihneš.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561242,54,19,71,21,'Rozmnožíš důstojnost mou, a zase utěšíš mne.'),
(1561243,54,19,71,22,'I jáť také budu tě slaviti na nástroji hudebném, i pravdu tvou, Bože můj; žalmy tobě zpívati budu na harfě, ó svatý Izraelský.'),
(1561244,54,19,71,23,'Plésati budou rtové moji, když žalmy zpívati budu tobě, i duše má, kterouž jsi vykoupil.'),
(1561245,54,19,71,24,'Nadto i jazyk můj každý den vypravovati bude spravedlnost tvou; nebo se zastyděti a zahanbiti musili ti, jenž mého pádu hledali.'),
(1561246,54,19,72,1,'Šalomounovi. Bože, soudy své králi dej, a spravedlnost svou synu královu,'),
(1561247,54,19,72,2,'Aby soudil lid tvůj v spravedlnosti a chudé tvé v pravosti.'),
(1561248,54,19,72,3,'Hory přinesou pokoj lidu i pahrbkové v spravedlnosti.'),
(1561249,54,19,72,4,'Souditi bude chudé z lidu, a vysvobodí syny nuzného, násilníka pak potře.'),
(1561250,54,19,72,5,'Báti se budou tebe, dokudž slunce a měsíc trvati bude, od národu až do pronárodu.'),
(1561251,54,19,72,6,'Jako když sstupuje déšť na přisečenou trávu, a jako tiší déšťové skrápějící zemi:'),
(1561252,54,19,72,7,'Tak zkvete ve dnech jeho spravedlivý, a bude hojnost pokoje, dokud měsíce stává.'),
(1561253,54,19,72,8,'Panovati bude od moře až k moři, a od řeky až do končin země.'),
(1561254,54,19,72,9,'Před ním skláněti se budou obyvatelé pustin vyprahlých, a nepřátelé jeho prach lízati budou.'),
(1561255,54,19,72,10,'Králové při moři a z ostrovů pocty mu přinesou, králové Šebejští a Sabejští dary obětovati budou.'),
(1561256,54,19,72,11,'Nadto klaněti se jemu budou všickni králové, všickni národové jemu sloužiti budou.'),
(1561257,54,19,72,12,'Nebo vytrhne nuzného, volajícího a nátisk trpícího, kterýž nemá spomocníka.'),
(1561258,54,19,72,13,'Smiluje se nad bídným a potřebným, a duše nuzných spasí.'),
(1561259,54,19,72,14,'Od lsti a násilí vysvobodí duši jejich; neboť jest drahá krev jejich před očima jeho.'),
(1561260,54,19,72,15,'Budeť dlouhověký, a dávati mu budou zlato Arabské, a ustavně za něj se modliti, na každý den jemu dobrořečiti budou.'),
(1561261,54,19,72,16,'Když se vrže hrst obilí do země na vrchu hor, klátiti se budou jako Libán klasové jeho, a kvésti budou měšťané jako byliny země.'),
(1561262,54,19,72,17,'Jméno jeho bude na věky; dokudž slunce trvá, děditi bude jméno jeho. A požehnání sobě dávajíce v něm všickni národové, budou ho blahoslaviti.'),
(1561263,54,19,72,18,'Požehnaný Hospodin Bůh, Bůh Izraelský, kterýž sám činí divné věci,'),
(1561264,54,19,72,19,'A požehnané jméno slávy jeho na věky. Budiž také naplněna slávou jeho všecka země, Amen i Amen.'),
(1561265,54,19,72,20,'Skonávají se modlitby Davidovy, syna Izai.'),
(1561266,54,19,73,1,'Žalm Azafovi. Jistě žeť jest Bůh dobrý Izraelovi, těm, kteříž jsou čistého srdce.'),
(1561267,54,19,73,2,'Ale nohy mé téměř se byly ušinuly, o málo, že by byli sklouzli krokové moji,'),
(1561268,54,19,73,3,'Když jsem horlil proti bláznivým, vida štěstí nešlechetných.'),
(1561269,54,19,73,4,'Nebo nebývají vázáni až k smrti, ale zůstává v cele síla jejich.'),
(1561270,54,19,73,5,'V práci lidské nejsou, a s lidmi trestáni nebývají.'),
(1561271,54,19,73,6,'Protož otočeni jsou pýchou jako halží, a ukrutností jako rouchem ozdobným přiodíni.'),
(1561272,54,19,73,7,'Vysedlo tukem oko jejich; majíce hojnost nad pomyšlení srdce,'),
(1561273,54,19,73,8,'Rozpustilí jsou, a mluví zlostně, o nátisku velmi pyšně mluví.'),
(1561274,54,19,73,9,'Stavějí proti nebi ústa svá, a jazyk jejich po zemi se vozí.'),
(1561275,54,19,73,10,'A protož na to přichází lid jeho, když se jim vody až do vrchu nalívá,'),
(1561276,54,19,73,11,'Že říkají: Jakť má o tom věděti Bůh silný? Aneb zdaž jest to známé Nejvyššímu?'),
(1561277,54,19,73,12,'Nebo aj, ti bezbožní jsouce, mají pokoj v světě, a dosahují zboží.'),
(1561278,54,19,73,13,'Nadarmo tedy v čistotě chovám srdce své, a v nevinnosti ruce své umývám.'),
(1561279,54,19,73,14,'Poněvadž každý den trestán bývám, a kázeň přichází na mne každého jitra.'),
(1561280,54,19,73,15,'Řeknu-li: Vypravovati budu věci takové, hle, rodina synů tvých dí, že jsem jim křiv.'),
(1561281,54,19,73,16,'Chtěl jsem to rozumem vystihnouti, ale vidělo mi se pracno.'),
(1561282,54,19,73,17,'Až jsem všel do svatyní Boha silného, tu jsem srozuměl poslední věci jejich.'),
(1561283,54,19,73,18,'Jistě že jsi je na místech plzkých postavil, a uvržeš je v spustliny.'),
(1561284,54,19,73,19,'Aj, jakť přicházejí na spuštění jako v okamžení! Mizejí a hynou hrůzami,'),
(1561285,54,19,73,20,'Jako snové tomu, kdož procítí; Pane, když je probudíš, obraz ten jejich za nic položíš.'),
(1561286,54,19,73,21,'Když zhořklo srdce mé, a ledví má bodena byla,'),
(1561287,54,19,73,22,'Nesmyslný jsem byl, aniž jsem co znal, jako hovádko byl jsem před tebou.'),
(1561288,54,19,73,23,'A však vždycky jsem byl s tebou, nebo jsi mne ujal za mou pravici.'),
(1561289,54,19,73,24,'Podlé rady své veď mne, a potom v slávu přijmeš mne.'),
(1561290,54,19,73,25,'Kohož bych měl na nebi? A mimo tebe v žádném líbosti nemám na zemi.'),
(1561291,54,19,73,26,'Ač tělo i srdce mé hyne, skála srdce mého, a díl můj Bůh jest na věky.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561292,54,19,73,27,'Nebo aj, ti, kteříž se vzdalují tebe, zahynou; vytínáš ty, kteříž cizoloží odcházením od tebe.'),
(1561293,54,19,73,28,'Ale mně nejlépe jest přídržeti se Boha; pročež skládám v Panovníku Hospodinu doufání své, abych vypravoval všecky skutky jeho.'),
(1561294,54,19,74,1,'Vyučující, Azafův. Proč, ó Bože, nás tak do konce zamítáš? Proč roznícena jest prchlivost tvá proti stádci pastvy tvé?'),
(1561295,54,19,74,2,'Rozpomeň se na shromáždění své, jehož jsi od starodávna dobyl a vykoupil, na proutek dědictví svého, na Sion horu tuto, na níž přebýváš.'),
(1561296,54,19,74,3,'Přispějž k hrozným pustinám. Jak všecko pohubil nepřítel v svatyni!'),
(1561297,54,19,74,4,'Řvali nepřátelé tvoji u prostřed shromáždění tvých, a na znamení toho zanechali množství korouhví svých.'),
(1561298,54,19,74,5,'Za hrdinu jmín byl ten, kterýž co nejvýše zdvihl sekeru, roubaje vazbu dříví jeho.'),
(1561299,54,19,74,6,'A nyní již řezby jeho napořád sekerami a palicemi otloukají.'),
(1561300,54,19,74,7,'Uvrhli oheň do svatyně tvé, na zem zřítivše, poškvrnili příbytku jména tvého.'),
(1561301,54,19,74,8,'Řekli v srdci svém: Vyhubme je napořád. Takž vypálili všecky stánky Boha silného v zemi.'),
(1561302,54,19,74,9,'Znamení svých nevidíme, jižť není proroka, aniž jest mezi námi, kdo by věděl, dokud to stane.'),
(1561303,54,19,74,10,'I dokudž, ó Bože, útržky činiti bude odpůrce? A nepřítel ustavičně-liž rouhati se bude jménu tvému?'),
(1561304,54,19,74,11,'Proč zdržuješ ruku svou, a pravice své z lůna svého nevzneseš?'),
(1561305,54,19,74,12,'Však jsi ty, Bože, král můj od starodávna, působíš hojné spasení u prostřed země.'),
(1561306,54,19,74,13,'Ty silou svou rozdělil jsi moře, a potřels hlavy draků u vodách.'),
(1561307,54,19,74,14,'Ty jsi potřel hlavu Leviatanovi, dal jsi jej za pokrm lidu na poušti.'),
(1561308,54,19,74,15,'Ty jsi otevřel vrchoviště a potoky, ty jsi osušil i řeky prudké.'),
(1561309,54,19,74,16,'Tvůjť jest den, tvá jest také i noc, světlo i slunce ty jsi učinil.'),
(1561310,54,19,74,17,'Ty jsi založil všecky končiny země, léto i zimy ty jsi sformoval.'),
(1561311,54,19,74,18,'Rozpomeniž se na to, že útržky činil ten odpůrce Hospodinu, a lid bláznivý jak se jménu tvému rouhal.'),
(1561312,54,19,74,19,'Nevydávejž té zběři duše hrdličky své,na stádce chudých svých nezapomínej se na věky.'),
(1561313,54,19,74,20,'Ohlédni se na smlouvu; nebo plní jsou i nejtmavější koutové země peleší ukrutnosti.'),
(1561314,54,19,74,21,'Nechažť bídní neodcházejí s hanbou, chudý a nuzný ať chválí jméno tvé.'),
(1561315,54,19,74,22,'Povstaniž, ó Bože, a veď při svou, rozpomeň se na pohanění, kteréžť se děje od nesmyslných na každý den.'),
(1561316,54,19,74,23,'Nezapomínej se na vykřikování svých nepřátel, a na hluk proti tobě povstávajících, kterýž se silí ustavičně.'),
(1561317,54,19,75,1,'Přednímu z kantorů, jako: Nezahlazuj, žalm Azafův, a píseň.'),
(1561318,54,19,75,2,'Oslavujeme tě, Bože, oslavujeme; nebo že jest blízké jméno tvé, vypravují to předivní skutkové tvoji.'),
(1561319,54,19,75,3,'Když přijde čas uložený, já právě souditi budu.'),
(1561320,54,19,75,4,'Rozplynula se země i všickni obyvatelé její, já utvrdím sloupy její. Sélah.'),
(1561321,54,19,75,5,'Dím bláznům: Neblázněte, a bezbožným: Nevyzdvihujte rohů.'),
(1561322,54,19,75,6,'Nevyzdvihujte proti Nejvyššímu rohů svých, aniž mluvte tvrdošijně.'),
(1561323,54,19,75,7,'Nebo ne od východu, ani západu, ani od pouště přichází zvýšení;'),
(1561324,54,19,75,8,'Ale Bůh soudce jednoho ponižuje, a druhého povyšuje.'),
(1561325,54,19,75,9,'Kalich zajisté jest v rukou Hospodinových, a to vína kalného plný nalitý, z něhož nalévati bude, tak že i kvasnice jeho vyváží, a vypijí všickni bezbožníci země.'),
(1561326,54,19,75,10,'Já pak zvěstovati budu skutky Páně na věčnost, žalmy zpívati budu Bohu Jákobovu.'),
(1561327,54,19,75,11,'A všecky rohy bezbožníků srážím, rohové pak spravedlivého vyvýšeni budou.'),
(1561328,54,19,76,1,'Přednímu z kantorů na neginot, žalm Azafův a píseň.'),
(1561329,54,19,76,2,'Znám jest Bůh v Judstvu, a v Izraeli veliké jméno jeho.'),
(1561330,54,19,76,3,'V Sálem jest stánek jeho, a obydlé jeho na Sionu.'),
(1561331,54,19,76,4,'Tamť jest polámal ohnivé šípy lučišť, pavézu a meč, i válku. Sélah.'),
(1561332,54,19,76,5,'Slavný jsi učiněn a důstojný horami loupeže.'),
(1561333,54,19,76,6,'V loupež dáni jsou udatní srdcem, zesnuli snem svým, aniž nalezly zmužilé hrdiny síly v rukou svých.'),
(1561334,54,19,76,7,'Od žehrání tvého, ó Bože Jákobův, i vůz i kůň tvrdě zesnuli.'),
(1561335,54,19,76,8,'Ty jsi, ty velmi hrozný, a kdo jest, ješto by před tebou ostál v rozhněvání tvém?'),
(1561336,54,19,76,9,'Když s nebe dáváš slyšeti výpověd svou, země se bojí a tichne,'),
(1561337,54,19,76,10,'Když povstává k soudu Bůh, aby zachoval všecky pokorné na zemi. Sélah.'),
(1561338,54,19,76,11,'Zajisté i hněv člověka chváliti tě musí, a ostatek zůřivosti skrotíš.'),
(1561339,54,19,76,12,'Sliby čiňte a plňte Hospodinu Bohu vašemu; kteřížkoli jste vůkol něho, přinášejte dary Přehroznému.'),
(1561340,54,19,76,13,'Onť odjímá ducha knížatům, a k hrůze jest králům zemským.'),
(1561341,54,19,77,1,'Přednímu kantoru z potomků Jedutunových, s Azafem, žalm.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561342,54,19,77,2,'Hlas můj k Bohu, když volám, hlas můj k Bohu, aby ucha naklonil ke mně.'),
(1561343,54,19,77,3,'V den ssoužení svého Pána hledal jsem, v noci ruce své rozprostíral jsem bez přestání, a nedala se potěšiti duše má.'),
(1561344,54,19,77,4,'Na Boha zpomínal jsem a kormoutil se, přemyšloval jsem, a úzkostmi svírán byl duch můj. Sélah.'),
(1561345,54,19,77,5,'Zdržoval jsi oči mé, aby bděly; potřín jsem byl, aniž jsem mluviti mohl.'),
(1561346,54,19,77,6,'I přicházeli mi na pamět dnové předešlí, a léta dávní.'),
(1561347,54,19,77,7,'Rozpomínal jsem se v noci na zpěvy své, v srdci svém přemyšloval jsem, a zpytoval to duch můj, pravě:'),
(1561348,54,19,77,8,'Zdali na věky zažene Bůh? Nikdy-liž již více lásky neukáže?'),
(1561349,54,19,77,9,'Zdali do konce přestane milosrdenství jeho? A konec vezme slovo od pokolení až do pokolení?'),
(1561350,54,19,77,10,'Zdali se zapomněl smilovávati Bůh silný? Zdaž zadržel v hněvě milosrdenství svá? Sélah.'),
(1561351,54,19,77,11,'I řekl jsem: Toť jest má smrt. Ale učiníť proměnu pravice Nejvyššího.'),
(1561352,54,19,77,12,'Rozpomínati se budu na skutky Hospodinovy, a připomínati sobě divné činy tvé, od starodávna.'),
(1561353,54,19,77,13,'A přemyšlovati o všelikém díle tvém, a o skutcích tvých mluviti.'),
(1561354,54,19,77,14,'Bože, svatá jest cesta tvá. Kdo jest silný, veliký, jako Bůh?'),
(1561355,54,19,77,15,'Ty jsi ten Bůh silný, jenž činíš divné věci; uvedl jsi v známost mezi národy sílu svou.'),
(1561356,54,19,77,16,'Vysvobodil jsi ramenem lid svůj, syny Jákobovy a Jozefovy. Sélah.'),
(1561357,54,19,77,17,'Vidělyť jsou tě vody, Bože, viděly tě vody, a zstrašily se; pohnuly se také i hlubiny.'),
(1561358,54,19,77,18,'Vydali povodně oblakové, vydala hřmot nebesa, ano i kameníčko tvé skákalo.'),
(1561359,54,19,77,19,'Vznělo hřímání tvé po obloze, blýskání osvěcovalo okršlek zemský, pohybovala se a třásla země.'),
(1561360,54,19,77,20,'Skrze moře byla cesta tvá, a stezky tvé skrze vody veliké, a však šlepějí tvých nebylo znáti.'),
(1561361,54,19,77,21,'Vedl jsi jako stádo lid svůj skrze Mojžíše a Arona.'),
(1561362,54,19,78,1,'Vyučující, Azafovi. Pozoruj, lide můj, zákona mého, nakloňte uší svých k slovům úst mých.'),
(1561363,54,19,78,2,'Otevru v podobenství ústa svá, vypravovati budu přípovídky starobylé.'),
(1561364,54,19,78,3,'Co jsme slýchali i poznali, a co nám otcové naši vypravovali,'),
(1561365,54,19,78,4,'Nezatajíme toho před syny jejich, kteříž budoucím potomkům svým vypravovati budou chvály Hospodinovy, ano i moc jeho a divné skutky jeho, kteréž činil.'),
(1561366,54,19,78,5,'Neboť jest vyzdvihl svědectví v Jákobovi, a zákon vydal v Izraeli, což přikázal otcům našim, aby v známost uvodili synům svým,'),
(1561367,54,19,78,6,'Aby to poznal věk potomní, synové, kteříž se zroditi měli, a ti povstanouce, aby vypravovali dítkám svým,'),
(1561368,54,19,78,7,'Aby pokládali v Bohu naději svou, a nezapomínali se na skutky Boha silného, ale ostříhali přikázaní jeho,'),
(1561369,54,19,78,8,'Aby nebývali jako otcové jejich, pokolení zpurné a protivné, národ, kterýž nenapravil srdce svého, a nebyl věrný Bohu silnému duch jeho.'),
(1561370,54,19,78,9,'Jako synové Efraim zbrojní, ač uměle z lučiště stříleli, však v čas boje zpět se obrátili,'),
(1561371,54,19,78,10,'Nebo neostříhali smlouvy Boží, a v zákoně jeho zpěčovali se choditi.'),
(1561372,54,19,78,11,'Zapomenuli se na činy jeho, a na divné skutky jeho, kteréž jim ukázal.'),
(1561373,54,19,78,12,'Před otci jejich činil divy v zemi Egyptské, na poli Soan.'),
(1561374,54,19,78,13,'Rozdělil moře, a převedl je; učinil, aby stály vody jako hromada.'),
(1561375,54,19,78,14,'Vedl je ve dne v oblace, a každé noci v jasném ohni.'),
(1561376,54,19,78,15,'Protrhl skály na poušti, a napájel je jako z propastí velikých.'),
(1561377,54,19,78,16,'Vyvedl potoky z skály, a učinil, aby vody tekly jako řeky.'),
(1561378,54,19,78,17,'A však vždy přičíněli hříchů proti němu, a popouzeli Nejvyššího na poušti.'),
(1561379,54,19,78,18,'A pokoušeli Boha silného v srdci svém, žádajíce pokrmu podlé líbosti své.'),
(1561380,54,19,78,19,'A mluvili proti Bohu, řkouce: Zdaliž bude moci Bůh silný připraviti stůl na této poušti?'),
(1561381,54,19,78,20,'Aj, udeřilť jest v skálu, a tekly vody, a řeky se rozvodnily. Zdali také bude moci dáti chleba? Zdali nastrojí masa lidu svému?'),
(1561382,54,19,78,21,'A protož uslyšav Hospodin, rozhněval se, a oheň zažžen jest proti Jákobovi, a prchlivost vstoupila na Izraele,'),
(1561383,54,19,78,22,'Proto že se nedověřili Bohu, a neměli naděje v spasení jeho,'),
(1561384,54,19,78,23,'Ačkoli rozkázal oblakům shůry, a průduchy nebeské otevřel,'),
(1561385,54,19,78,24,'A dštil na ně mannou ku pokrmu, a obilé nebeské dával jim.'),
(1561386,54,19,78,25,'Chléb mocných jedl člověk, seslal jim pokrmů do sytosti.'),
(1561387,54,19,78,26,'Obrátil vítr východní u povětří, a přivedl mocí svou vítr polední.'),
(1561388,54,19,78,27,'I dštil na ně masem jako prachem, a ptactvem pernatým jako pískem mořským.'),
(1561389,54,19,78,28,'Spustil je do prostřed vojska jejich, a všudy vůkol stanů jejich.'),
(1561390,54,19,78,29,'I jedli, a nasyceni jsou hojně, a dal jim to, čehož žádali.'),
(1561391,54,19,78,30,'Ještě nevyplnili žádosti své, ještě pokrm byl v ústech jejich,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561392,54,19,78,31,'A v tom prchlivost Boží připadla na ně, a zbil tučné jejich, a přední Izraelské porazil.'),
(1561393,54,19,78,32,'S tím se vším vždy ještě hřešili, a nevěřili předivným skutkům jeho.'),
(1561394,54,19,78,33,'A protož dopustil na ně, že marně skonali dny své, a léta svá s chvátáním.'),
(1561395,54,19,78,34,'Když je hubil, jestliže ho hledali, a zase k Bohu silnému hned na úsvitě se navraceli,'),
(1561396,54,19,78,35,'Rozpomínajíce se na to, že Bůh byl skála jejich, a Bůh silný nejvyšší vykupitel jejich:'),
(1561397,54,19,78,36,'(Ačkoli mu s pochlebenstvím mluvili ústy svými, a jazykem svým lhali jemu.'),
(1561398,54,19,78,37,'A srdce jejich nebylo upřímé před ním, aniž se věrně měli v smlouvě jeho),'),
(1561399,54,19,78,38,'On jsa milosrdný, odpouštěl nepravosti jejich, a nezahladil jich; častokrát odvracel hněv svůj, a nevzbuzoval vší zůřivosti své.'),
(1561400,54,19,78,39,'Nebo pamatoval, že jsou tělo, vítr, kterýž odchází, a nenavracuje se zase.'),
(1561401,54,19,78,40,'Kolikrát jsou ho dráždili na poušti, a k bolesti přivodili na pustinách.'),
(1561402,54,19,78,41,'Týž i týž navracujíce se, pokoušeli Boha silného, a svatému Izraelskému cíle vyměřovali.'),
(1561403,54,19,78,42,'Nepamatovali na moc jeho, a na ten den, v kterémž je vysvobodil z ssoužení,'),
(1561404,54,19,78,43,'Když činil v Egyptě znamení svá, a zázraky své na poli Soan,'),
(1561405,54,19,78,44,'Když obrátil v krev řeky a potoky jejich, tak že jich píti nemohli.'),
(1561406,54,19,78,45,'Dopustil na ně směsici žížal, aby je žraly, a žáby, aby je hubily.'),
(1561407,54,19,78,46,'A dal chroustům úrody jejich, a úsilí jejich kobylkám.'),
(1561408,54,19,78,47,'Stloukl krupami réví jejich, a stromy fíkové jejich ledem.'),
(1561409,54,19,78,48,'Vydal krupobití na hovada jejich, a na dobytek jejich uhlí řeřavé.'),
(1561410,54,19,78,49,'Poslal na ně prchlivost hněvu svého, rozpálení, zůřivost i ssoužení, dopustiv na ně anděly zlé.'),
(1561411,54,19,78,50,'Uprostrannil stezku prchlivosti své, neuchoval od smrti duše jejich, ano i na hovada jejich mor dopustil.'),
(1561412,54,19,78,51,'A pobil všecko prvorozené v Egyptě, prvotiny síly v staních Chamových.'),
(1561413,54,19,78,52,'Ale lid svůj vyvedl jako ovce, a vodil se s nimi jako s stádem po poušti.'),
(1561414,54,19,78,53,'Vodil je v bezpečnosti, tak že nestrašili, nepřátely pak jejich přikrylo moře,'),
(1561415,54,19,78,54,'Až je přivedl ku pomezí svatosti své, na horu tu, kteréž dobyla pravice jeho.'),
(1561416,54,19,78,55,'Vyhnav před tváří jejich národy, způsobil to, aby jim na provazec dědictví jejich přišli, a aby přebývala v staních jejich pokolení Izraelská.'),
(1561417,54,19,78,56,'Však vždy předce pokoušeli a dráždili Boha nejvyššího, a svědectví jeho neostříhali.'),
(1561418,54,19,78,57,'Ale zpět odšedše, převráceně činili, jako i předkové jejich; uchýlili se jako mylné lučiště.'),
(1561419,54,19,78,58,'Nebo popouzeli ho výsostmi svými, a rytinami svými k horlení přivedli jej.'),
(1561420,54,19,78,59,'Slyšel Bůh, a rozhněval se, a u velikou ošklivost vzal Izraele,'),
(1561421,54,19,78,60,'Tak že opustiv příbytek v Sílo, stánek, kterýž postavil mezi lidmi,'),
(1561422,54,19,78,61,'Vydal v zajetí sílu svou, a slávu svou v ruce nepřítele.'),
(1561423,54,19,78,62,'Dal pod meč lid svůj, a na dědictví své se rozhněval.'),
(1561424,54,19,78,63,'Mládence jeho sežral oheň, a panny jeho nebyly chváleny.'),
(1561425,54,19,78,64,'Kněží jejich od meče padli, a vdovy jejich neplakaly.'),
(1561426,54,19,78,65,'Potom pak procítil Pán jako ze sna, jako silný rek, kterýž po víně sobě vykřikuje.'),
(1561427,54,19,78,66,'A ranil nepřátely své po zadu, a u věčné pohanění je vydal.'),
(1561428,54,19,78,67,'Ačkoli pak pohrdl stánkem Jozefovým, a pokolení Efraimova nevyvolil,'),
(1561429,54,19,78,68,'Však vyvolil pokolení Judovo, horu Sion, kterouž zamiloval.'),
(1561430,54,19,78,69,'A vystavěl sobě, jako hrad vysoký, svatyni svou, jako zemi, kterouž utvrdil na věky.'),
(1561431,54,19,78,70,'A vyvolil Davida služebníka svého, vzav jej od chlévů stáda.'),
(1561432,54,19,78,71,'Když chodil za ovcemi březími, zavedl jej, aby pásl Jákoba, lid jeho, a Izraele, dědictví jeho.'),
(1561433,54,19,78,72,'Kterýž pásl je v upřímnosti srdce svého, a zvláštní opatrností rukou svých vodil je.'),
(1561434,54,19,79,1,'Žalm Azafovi. Bože, vtrhli pohané do dědictví tvého, poškvrnili chrámu svatosti tvé, obrátili Jeruzalém v hromady.'),
(1561435,54,19,79,2,'Dali těla mrtvá služebníků tvých za pokrm ptákům nebeským, těla svatých tvých šelmám zemským.'),
(1561436,54,19,79,3,'Vylili krev jejich jako vodu okolo Jeruzaléma, a nebyl, kdo by je pochovával.'),
(1561437,54,19,79,4,'Vydáni jsme v pohanění sousedům našim, v posměch a žert těm, kteříž jsou vůkol nás.'),
(1561438,54,19,79,5,'Až dokud, ó Hospodine? Na věky-liž se hněvati budeš, a hořeti bude jako oheň horlení tvé?'),
(1561439,54,19,79,6,'Vylí hněv svůj na národy, kteříž tě neznají, a na království, kteráž jména tvého nevzývají.'),
(1561440,54,19,79,7,'Neboť jsou sežrali Jákoba, a obydlí jeho v poustku obrátili.'),
(1561441,54,19,79,8,'Nezpomínejž nám dřevních nepravostí našich, rychle ať předejdou nás milosrdenství tvá, neboť jsme velmi znuzeni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561442,54,19,79,9,'Pomoz nám, ó Bože spasení našeho, pro slávu jména svého; vytrhni nás, a buď milostiv hříchům našim pro jméno své.'),
(1561443,54,19,79,10,'Proč mají říkati pohané: Kdež jest Bůh jejich? Budiž znám mezi pohany, před očima našima, skrze pomstu krve služebníků svých, kteráž jest vylita.'),
(1561444,54,19,79,11,'Vstupiž před oblíčej tvůj lkání vězňů, a podlé velikosti síly své zanechej ostatků k smrti oddaných.'),
(1561445,54,19,79,12,'A odplať sousedům našim sedmernásobně do lůna jejich za pohanění, kteréž jsou tobě činili, ó Pane.'),
(1561446,54,19,79,13,'My pak, lid tvůj a ovce pastvy tvé, slaviti tě budeme na věky; od národu do pronárodu vypravovati budeme chválu tvou.'),
(1561447,54,19,80,1,'Přednímu z kantorů na šošannim, žalm svědectví, Azafovi.'),
(1561448,54,19,80,2,'Ó pastýři Izraelský, pozoruj, kterýž vodíš Jozefa jako stádo, kterýž sedíš nad cherubíny, ó zastkvějž se.'),
(1561449,54,19,80,3,'Před Efraimem, Beniaminem a Manasse vzbuď moc svou, a přispěj k spasení našemu.'),
(1561450,54,19,80,4,'Ó Bože, navrať nás, a dejž, ať nám svítí oblíčej tvůj, a spaseni budeme.'),
(1561451,54,19,80,5,'Hospodine Bože zástupů, dokudž se přísně stavěti budeš k modlitbám lidu svého?'),
(1561452,54,19,80,6,'Nakrmil jsi je chlebem pláče, a dals jim vypiti slz míru velikou.'),
(1561453,54,19,80,7,'Postavils nás k sváru sousedům našim, a nepřátelé naši aby sobě posměch z nás činili.'),
(1561454,54,19,80,8,'Ó Bože zástupů, navrať nás, a dej, ať nám svítí oblíčej tvůj, a spaseni budeme.'),
(1561455,54,19,80,9,'Ty jsi kmen vinný z Egypta přenesl, vyhnal jsi pohany, a vsadils jej.'),
(1561456,54,19,80,10,'Uprázdnil jsi mu, a učinils, aby se vkořenil, i zemi naplnil.'),
(1561457,54,19,80,11,'Přikryty jsou hory stínem jeho, a réví jeho jako nejvyšší cedrové.'),
(1561458,54,19,80,12,'Vypustil ratolesti své až k moři, a až do řeky rozvody své.'),
(1561459,54,19,80,13,'I pročež jsi rozbořil hradbu vinice, tak aby každý, kdož by tudy šel, trhati z ní mohl?'),
(1561460,54,19,80,14,'Vepř divoký zryl ji, a zvěř polní spásla ji.'),
(1561461,54,19,80,15,'Ó Bože zástupů, obrať se již, popatř s nebe, viz a navštěv kmen vinný tento,'),
(1561462,54,19,80,16,'Vinici tu, kterouž štípila pravice tvá, a mladistvé réví, kteréž jsi zmocnil sobě.'),
(1561463,54,19,80,17,'Popálenať jest ohněm a poroubána, od žehrání oblíčeje tvého hyne.'),
(1561464,54,19,80,18,'Budiž ruka tvá nad mužem pravice tvé, nad synem člověka, kteréhož jsi zmocnil sobě,'),
(1561465,54,19,80,19,'A neodstoupímeť od tebe; zachovej nás při životu, ať jméno tvé vzýváme.'),
(1561466,54,19,80,20,'Hospodine Bože zástupů, navratiž nás zase, a dej, ať nám svítí oblíčej tvůj, a spaseni budeme.'),
(1561467,54,19,81,1,'Přednímu z kantorů na gittit, Azafovi.'),
(1561468,54,19,81,2,'Plésejte Bohu, síle naší, prokřikujte Bohu Jákobovu.'),
(1561469,54,19,81,3,'Vezměte žaltář, přidejte buben, harfu libou a loutnu.'),
(1561470,54,19,81,4,'Trubte trubou na novměsíce, v uložený čas, v den slavnosti naší.'),
(1561471,54,19,81,5,'Nebo toť jest ustavení v Izraeli, řád Boha Jákobova.'),
(1561472,54,19,81,6,'Na svědectví v Jozefovi vyzdvihl jej, když byl vyšel proti zemi Egyptské, kdež jsme jazyk neznámý slýchati musili.'),
(1561473,54,19,81,7,'Osvobodil jsem, dí Bůh, od břemene rameno jeho, a ruce jeho nádob zednických zproštěny byly.'),
(1561474,54,19,81,8,'V ssoužení tom, když jsi volal, vytrhl jsem tě, vyslyšel jsem tě z skrýše hromu, zkušoval jsem tě při vodách sváru. Sélah.'),
(1561475,54,19,81,9,'Řeklť jsem: Slyš, lide můj, a osvědčím se tobě, ó Izraeli, budeš-li mne poslouchati,'),
(1561476,54,19,81,10,'A nebude-li mezi vámi Boha jiného, a nebudeš-li se klaněti bohu cizímu.'),
(1561477,54,19,81,11,'Já jsem Hospodin Bůh tvůj, kterýž jsem tě vyvedl z země Egyptské, otevři jen ústa svá, a naplnímť je.'),
(1561478,54,19,81,12,'Ale neuposlechl lid můj hlasu mého, a Izrael nepřestal na mně,'),
(1561479,54,19,81,13,'A protož pustil jsem je v žádost srdce jejich, i chodili po radách svých.'),
(1561480,54,19,81,14,'Ó byť mne byl lid můj poslouchal, a Izrael po cestách mých chodil,'),
(1561481,54,19,81,15,'Tudíž bych já byl nepřátely jejich snížil, a na protivníky jejich obrátil ruku svou.'),
(1561482,54,19,81,16,'A ti, kteříž v nenávisti mají Hospodina, úlisně by se jim poddávati musili, i byl by čas jejich až na věky.'),
(1561483,54,19,81,17,'A krmil bych je byl jádrem pšenice, a medem z skály sytil bych je.'),
(1561484,54,19,82,1,'Žalm Azafův. Bůh stojí v shromáždění Božím, u prostřed bohů soud čině, a dí:'),
(1561485,54,19,82,2,'Dokudž souditi budete nespravedlivě, a osoby nešlechetných přijímati? Sélah.'),
(1561486,54,19,82,3,'Zastávejte bídného a sirotka, utištěného a chudého spravedliva vyhlašujte.'),
(1561487,54,19,82,4,'Vytrhněte bídného a nuzného, z ruky nešlechetných vytrhněte ho.'),
(1561488,54,19,82,5,'Ale nevědí nic, nerozumějí nic; ve tmách ustavně chodí, až se proto všickni základové země pohybují.'),
(1561489,54,19,82,6,'Řeklť jsem já byl: Bohové jste, a synové Nejvyššího vy všickni;'),
(1561490,54,19,82,7,'A však jako i jiní lidé zemřete, a jako jeden z knížat padnete.'),
(1561491,54,19,82,8,'Povstaniž, ó Bože, suď zemi; nebo ty dědičně vládneš všemi národy.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561492,54,19,83,1,'Píseň a žalm Azafův.'),
(1561493,54,19,83,2,'Bože, neodmlčujž se, nečiň se neslyše, aniž se upokojuj, ó Bože silný.'),
(1561494,54,19,83,3,'Nebo aj, nepřátelé tvoji se bouří, a ti, kteříž tě v nenávisti mají, pozdvihují hlavy.'),
(1561495,54,19,83,4,'Chytře tajné rady proti lidu tvému skládají, a radí se proti těm, kteréž ty skrýváš,'),
(1561496,54,19,83,5,'Říkajíce: Poďte, a vyhlaďme je, ať nejsou národem, tak aby ani zpomínáno nebylo více jména Izraelova.'),
(1561497,54,19,83,6,'Jednomyslněť se na tom spolu snesli, i smlouvou se proti tobě zavázali,'),
(1561498,54,19,83,7,'Stánkové Idumejští a Izmaelitští, Moábští a Agarenští,'),
(1561499,54,19,83,8,'Gebálští a Ammonitští, a Amalechitští, Filistinští s obyvateli Tyrskými.'),
(1561500,54,19,83,9,'Ano i Assyrští spojili se s nimi, jsouce na ruku synům Lotovým. Sélah.'),
(1561501,54,19,83,10,'Učiniž jim jako Madianským, jako Zizarovi, a jako Jabínovi při potoku Císon,'),
(1561502,54,19,83,11,'Kteříž jsou do konce vyhlazeni v Endor, a učiněni hnůj země.'),
(1561503,54,19,83,12,'Nalož s nimi a s vůdci jejich jako s Gorébem, jako s Zébem, jako s Zebahem, a jako s Salmunou, se všemi knížaty jejich.'),
(1561504,54,19,83,13,'Neboť jsou řekli: Uvažme se dědičně v příbytky Boží.'),
(1561505,54,19,83,14,'Můj Bože, učiň to, ať jsou jako chumelice, a jako stéblo před větrem.'),
(1561506,54,19,83,15,'Jakož oheň spaluje les, a jako plamen zapaluje hory,'),
(1561507,54,19,83,16,'Tak ty je vichřicí svou stihej, a bouří svou ohrom je.'),
(1561508,54,19,83,17,'Naplň tváře jejich zahanbením, tak aby hledali jména tvého, Hospodine.'),
(1561509,54,19,83,18,'Nechať se hanbí a děsí na věčné časy, a ať potupu nesou a zahynou.'),
(1561510,54,19,83,19,'A tak ať poznají, že ty, kterýž sám jméno máš Hospodin, jsi nejvyšší nade vší zemí.'),
(1561511,54,19,84,1,'Přednímu z kantorů na gittit, synů Chóre, žalm.'),
(1561512,54,19,84,2,'Jak jsou milí příbytkové tvoji, Hospodine zástupů!'),
(1561513,54,19,84,3,'Žádostiva jest a velice touží duše má po síňcích Hospodinových; srdce mé, i tělo mé pléše k Bohu živému.'),
(1561514,54,19,84,4,'Ano i ten vrabec nalezl sobě místo a vlaštovice hnízdo, v němž by schránila mladé své, při oltářích tvých, Hospodine zástupů, králi můj a Bože můj.'),
(1561515,54,19,84,5,'Blahoslavení, kteříž přebývají v domě tvém, tiť tebe na věky chváliti budou. Sélah.'),
(1561516,54,19,84,6,'Blahoslavený člověk, jehož síla jest Hospodin, a v jejichž srdci jsou stezky kroků jejich,'),
(1561517,54,19,84,7,'Ti, kteříž jdouce přes údolí moruší, za studnici jej sobě pokládají, na něž i déšť požehnání přichází.'),
(1561518,54,19,84,8,'Berou se houf za houfem, a ukazují se před Bohem na Sionu.'),
(1561519,54,19,84,9,'Hospodine Bože zástupů, vyslyš modlitbu mou, pozoruj, ó Bože Jákobův. Sélah.'),
(1561520,54,19,84,10,'Pavézo naše, popatř, ó Bože, a viz tvář pomazaného svého.'),
(1561521,54,19,84,11,'Nebo lepší jest den v síňcích tvých, než jinde tisíc; zvolil jsem sobě raději u prahu seděti v domě Boha svého, nežli přebývati v stáncích bezbožníků.'),
(1561522,54,19,84,12,'Nebo Hospodin Bůh jest slunce a pavéza; tuť milosti i slávy udílí Hospodin, aniž odepře čeho dobrého chodícím v upřímnosti.'),
(1561523,54,19,84,13,'Hospodine zástupů, blahoslavený člověk, kterýž naději skládá v tobě.'),
(1561524,54,19,85,1,'Přednímu z kantorů, synů Chóre, žalm.'),
(1561525,54,19,85,2,'Laskavěs se, Hospodine, někdy ukazoval k zemi své, přivedls zase z vězení Jákoba.'),
(1561526,54,19,85,3,'Odpustil jsi nepravost lidu svého, přikryls všeliký hřích jejich. Sélah.'),
(1561527,54,19,85,4,'Zdržels všecken hněv svůj, odvrátils od zůřivosti prchlivost svou.'),
(1561528,54,19,85,5,'Navratiž se zase k nám, ó Bože spasení našeho, a učiň přítrž hněvu svému proti nám.'),
(1561529,54,19,85,6,'Zdaliž na věky hněvati se budeš na nás? A protáhneš zůřivost svou od národu do pronárodu?'),
(1561530,54,19,85,7,'Zdaliž ty obrátě se, neobživíš nás, tak aby se lid tvůj veselil v tobě?'),
(1561531,54,19,85,8,'Ukaž nám, Hospodine, milosrdenství své, a spasení své dej nám.'),
(1561532,54,19,85,9,'Ale poslechnu, co říká Bůh ten silný, Hospodin. Jistě žeť mluví pokoj k lidu svému, a k svatým svým, než aby se nenavracovali zase k bláznovství.'),
(1561533,54,19,85,10,'Zajisté žeť jest blízké těm, kteříž se ho bojí, spasení jeho, a přebývati bude sláva v zemi naší.'),
(1561534,54,19,85,11,'Milosrdenství a víra potkají se spolu, spravedlnost a pokoj dadí sobě políbení.'),
(1561535,54,19,85,12,'Víra z země pučiti se bude, a spravedlnost s nebe vyhlédati.'),
(1561536,54,19,85,13,'Dáť také Hospodin i časné dobré, tak že země naše vydá úrody své.'),
(1561537,54,19,85,14,'Způsobí to, aby spravedlnost před ním šla, když obrátí k cestě nohy své.'),
(1561538,54,19,86,1,'Modlitba Davidova. Nakloň, Hospodine, ucha svého, a vyslyš mne, neboť jsem chudý a nuzný.'),
(1561539,54,19,86,2,'Ostříhejž duše mé, neboť jsem ten, jehož miluješ; zachovej služebníka svého, ty Bože můj, v tobě naději majícího.'),
(1561540,54,19,86,3,'Smiluj se nade mnou, Hospodine, k toběť zajisté každého dne volám.'),
(1561541,54,19,86,4,'Potěš duše služebníka svého, neboť k tobě, ó Pane, duše své pozdvihuji.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561542,54,19,86,5,'Nebo ty jsi, Pane, dobrotivý a lítostivý, a hojný v milosrdenství ke všechněm, kteříž tě vzývají.'),
(1561543,54,19,86,6,'Slyš, Hospodine, modlitbu mou, a pozoruj hlasu žádostí mých.'),
(1561544,54,19,86,7,'V den ssoužení svého vzývám tě, nebo mne vyslýcháš.'),
(1561545,54,19,86,8,'Neníť žádného tobě podobného mezi bohy, ó Pane, a není takových skutků, jako jsou tvoji.'),
(1561546,54,19,86,9,'Všickni národové, kteréž jsi učinil, přicházejíce, skláněti se budou před tebou, Pane, a ctíti jméno tvé.'),
(1561547,54,19,86,10,'Nebo jsi ty veliký, a činíš divné věci, ty jsi Bůh sám.'),
(1561548,54,19,86,11,'Vyuč mne, Hospodine, cestě své, abych chodil v pravdě tvé; ustav srdce mé v bázni jména svého.'),
(1561549,54,19,86,12,'I budu tě oslavovati, Pane Bože můj, z celého srdce svého a ctíti jméno tvé na věky,'),
(1561550,54,19,86,13,'Poněvadž milosrdenství tvé veliké jest nade mnou, a vytrhls duši mou z jámy nejhlubší.'),
(1561551,54,19,86,14,'Ó Bože, povstaliť jsou pyšní proti mně, a rota násilníků hledají bezživotí mého, ti, kteříž tě sobě nepředstavují.'),
(1561552,54,19,86,15,'Ale ty Pane, Bože silný, lítostivý a milostivý, shovívající a hojný v milosrdenství, i pravdomluvný,'),
(1561553,54,19,86,16,'Vzhlédniž na mne, a smiluj se nade mnou, obdař silou svou služebníka svého, a zachovávej syna děvky své.'),
(1561554,54,19,86,17,'Prokaž ke mně znamení dobrotivosti, tak aby vidouce to ti, kteříž mne nenávidí, zahanbeni byli, že jsi ty mi, Hospodine, spomohl, a mne potěšil.'),
(1561555,54,19,87,1,'Synům Chóre, žalm a píseň. Základ svůj na horách svatých.'),
(1561556,54,19,87,2,'Milujeť Hospodin, totiž brány Sionské, nade všecky příbytky Jákobovy.'),
(1561557,54,19,87,3,'Přeslavnéť jsou to věci, kteréž se o tobě hlásají, ó město Boží. Sélah.'),
(1561558,54,19,87,4,'Připomínati budu Egypt a Babylon před svými známými, ano i Filistinské a Tyrské i Mouřeníny, že se tu každý z nich narodil.'),
(1561559,54,19,87,5,'An i o Sionu praveno bude: Ten i onen jest rodem z něho, sám pak Nejvyšší utvrdí jej.'),
(1561560,54,19,87,6,'Sečteť Hospodin při popisu národy, a dí, že tento se tu narodil. Sélah.'),
(1561561,54,19,87,7,'Tou příčinou zpívají s plésáním o tobě všecky moci života mého.'),
(1561562,54,19,88,1,'Píseň a žalm synů Chóre, přednímu zpěváku na machalat k zpívání, vyučující, složený od Hémana Ezrachitského.'),
(1561563,54,19,88,2,'Hospodine, Bože spasení mého, ve dne i v noci k tobě volám.'),
(1561564,54,19,88,3,'Vstupiž před oblíčej tvůj modlitba má, nakloň ucha svého k volání mému.'),
(1561565,54,19,88,4,'Neboť jest naplněna trápeními duše má, a život můj až k hrobu se přiblížil.'),
(1561566,54,19,88,5,'Počten jsem mezi ty, kteříž se dostávají do jámy; připodobněn jsem člověku beze vší síly.'),
(1561567,54,19,88,6,'Mezi mrtvé jsem odložen, jako zmordovaní ležící v hrobě, na něž nezpomínáš více, kteříž od ruky tvé vyhlazeni jsou.'),
(1561568,54,19,88,7,'Spustils mne do jámy nejzpodnější, do nejtemnějšího a nejhlubšího místa.'),
(1561569,54,19,88,8,'Dolehla na mne prchlivost tvá, a vším vlnobitím svým přikvačil jsi mne. Sélah.'),
(1561570,54,19,88,9,'Daleko jsi vzdálil mé známé ode mne, jimž jsi mne velice zošklivil, a tak jsem sevřín, že mi nelze nijakž vyjíti.'),
(1561571,54,19,88,10,'Zrak můj hyne trápením; na každý den vzývám tě, Hospodine, ruce své před tebou rozprostíraje.'),
(1561572,54,19,88,11,'Zdali před mrtvými učiníš zázrak? Aneb vstanou-liž mrtví, aby tě oslavovali?Sélah.'),
(1561573,54,19,88,12,'I zdali bude ohlašováno v hrobě milosrdenství tvé, a pravda tvá v zahynutí?'),
(1561574,54,19,88,13,'Zdaliž v známost přichází ve tmách div tvůj, a spravedlnost tvá v zemi zapomenutí?'),
(1561575,54,19,88,14,'Já pak, Hospodine, k tobě volám, a každého jitra předchází tě modlitba má.'),
(1561576,54,19,88,15,'Pročež, ó Hospodine, zamítáš mne, a tvář svou skrýváš přede mnou?'),
(1561577,54,19,88,16,'Ztrápený jsem, jako hned maje umříti od násilí; snáším hrůzy tvé, a děsím se.'),
(1561578,54,19,88,17,'Hněv tvůj přísný na mne se obořil, a hrůzy tvé krutě sevřely mne.'),
(1561579,54,19,88,18,'Obkličují mne jako voda, na každý den obstupují mne hromadně.'),
(1561580,54,19,88,19,'Vzdálil jsi ode mne přítele a tovaryše, a známým svým jsem ve tmě.'),
(1561581,54,19,89,1,'Vyučující, složený od Etana Ezrachitského.'),
(1561582,54,19,89,2,'O milosrdenstvích Hospodinových na věky zpívati budu, od národu do pronárodu zvěstovati budu pravdu tvou ústy svými.'),
(1561583,54,19,89,3,'Nebo jsem řekl: Na věky milosrdenství vzdělávati se bude, na nebi utvrdíš pravdu svou, o nížs řekl:'),
(1561584,54,19,89,4,'Učinil jsem smlouvu s vyvoleným svým, přisáhl jsem Davidovi služebníku svému,'),
(1561585,54,19,89,5,'Že až na věky utvrdím símě tvé, a vzdělám od národu do národu trůn tvůj. Sélah.'),
(1561586,54,19,89,6,'Protož oslavují nebesa div tvůj, Hospodine, i pravdu tvou v shromáždění svatých.'),
(1561587,54,19,89,7,'Nebo kdo na nebi přirovnán býti může Hospodinu? Kdo jest podobný Hospodinu mezi syny silných?'),
(1561588,54,19,89,8,'Bůh i v shromáždění svatých strašlivý jest náramně, a hrozný nade všecky vůkol něho.'),
(1561589,54,19,89,9,'Hospodine Bože zástupů, kdo jest jako ty, silný Hospodin? Nebo pravda tvá tobě přístojí všudy vůkol.'),
(1561590,54,19,89,10,'Ty panuješ nad dutím moře; když se zdvihají vlny jeho, ty je skrocuješ.'),
(1561591,54,19,89,11,'Ty jsi jako raněného potřel Egypt, a silným ramenem svým rozptýlil jsi nepřátely své.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561592,54,19,89,12,'Tváť jsou nebesa, tvá také i země, okršlek i plnost jeho ty jsi založil.'),
(1561593,54,19,89,13,'Půlnoční i polední strana, kteréž jsi ty stvořil, i Tábor a Hermon o tvém jménu zpívají.'),
(1561594,54,19,89,14,'Tvé rámě jest přemocné, silná ruka tvá, a vyvýšená pravice tvá.'),
(1561595,54,19,89,15,'Spravedlnost a soud jsou základem trůnu tvého, milosrdenství a pravda předcházejí tvář tvou.'),
(1561596,54,19,89,16,'Blahoslavený lid, kterýž zná zvuk tvůj; tiť, Hospodine, v světle oblíčeje tvého choditi budou.'),
(1561597,54,19,89,17,'Ve jménu tvém plésati budou každého dne, a v spravedlnosti tvé vyvýší se.'),
(1561598,54,19,89,18,'Nebo sláva síly jejich ty jsi, a z milosti tvé k zvýšení přijde roh náš.'),
(1561599,54,19,89,19,'Nebo štít náš jest Hospodinův, a svatého Izraelského král náš.'),
(1561600,54,19,89,20,'Tehdy mluvě u vidění k svatému svému, řekl jsi: Složil jsem pomoc v reku udatném, zvýšil jsem vybraného z lidu.'),
(1561601,54,19,89,21,'Nalezl jsem Davida služebníka svého, olejem svým svatým pomazal jsem ho.'),
(1561602,54,19,89,22,'A protož budeť s ním stále ruka má, ano i ramenem svým posilovati ho budu.'),
(1561603,54,19,89,23,'Nebudeť ho moci nuziti nepřítel, ani člověk nešlechetný trápiti.'),
(1561604,54,19,89,24,'Nebo potru před tváří jeho protivníky jeho, a ty, kteříž ho nenávidí, porazím.'),
(1561605,54,19,89,25,'Nadto pravda má a milosrdenství mé s ním bude, a ve jménu mém vyvýšen bude roh jeho.'),
(1561606,54,19,89,26,'A vložím na moře ruku jeho, a na řeky pravici jeho.'),
(1561607,54,19,89,27,'On volaje ke mně, dí: Ty jsi otec můj, Bůh silný můj a skála spasení mého.'),
(1561608,54,19,89,28,'Já také za prvorozeného vystavím jej, a za vyššího králů zemských.'),
(1561609,54,19,89,29,'Na věky zachovám jemu milosrdenství své, a smlouva s ním stálá bude.'),
(1561610,54,19,89,30,'Učiním i to, aby na věky trvalo símě jeho, a trůn jeho jako dnové nebes.'),
(1561611,54,19,89,31,'Jestliže by pak synové jeho opustili zákon můj, a v soudech mých nechodili,'),
(1561612,54,19,89,32,'Jestliže by ustanovení mých poškvrnili, a přikázaní mých neostříhali:'),
(1561613,54,19,89,33,'Tedy navštívím metlou přestoupení jejich, a trestáním nepravost jejich,'),
(1561614,54,19,89,34,'Ale milosrdenství svého neodejmu od něho, aniž klamati budu proti pravdě své.'),
(1561615,54,19,89,35,'Nepoškvrnímť smlouvy své, a toho, což vyšlo z úst mých, nezměním.'),
(1561616,54,19,89,36,'Jednou jsem přisáhl skrze svatost svou, nesklamámť Davidovi,'),
(1561617,54,19,89,37,'Že símě jeho na věky bude, a trůn jeho jako slunce přede mnou,'),
(1561618,54,19,89,38,'Jako měsíc utvrzeno bude na věky, a jako svědkové na obloze hodnověrní.'),
(1561619,54,19,89,39,'Ale ty jsi jej zavrhl a potupil, rozhněvals se na pomazaného svého.'),
(1561620,54,19,89,40,'Zavrhl jsi smlouvu s služebníkem svým, povrhls korunu jeho na zem.'),
(1561621,54,19,89,41,'Roztrhal jsi všecky ohrady jeho, a bašty jeho jsi rozválel.'),
(1561622,54,19,89,42,'Derou jej všickni, kteříž tudy jdou; jest ku posměchu i sousedům svým.'),
(1561623,54,19,89,43,'Vyvýšil jsi pravici protivníků jeho, obveselils všecky nepřátely jeho.'),
(1561624,54,19,89,44,'Ztupils i ostří meče jeho, aniž jsi dal jemu, aby ostáti mohl v boji.'),
(1561625,54,19,89,45,'Učinils přítrž okrase jeho, a trůn jeho svrhl jsi na zem.'),
(1561626,54,19,89,46,'Ukrátil jsi dnů mladosti jeho, a hanbous jej přiodíl. Sélah.'),
(1561627,54,19,89,47,'Až dokud, Hospodine? Na věky-liž se skrývati budeš? Tak-liž hořeti bude jako oheň prchlivost tvá?'),
(1561628,54,19,89,48,'Rozpomeniž se na mne, jak kratičký jest věk můj. Zdaliž jsi pak nadarmo stvořil všecky syny lidské?'),
(1561629,54,19,89,49,'Kdo z lidí může tak živ býti, aby neokusil smrti? Kdo vytrhne život svůj z hrobu? Sélah.'),
(1561630,54,19,89,50,'Kdež jsou milosrdenství tvá první, ó Pane? Přísahuť jsi učinil Davidovi, v pravdě své.'),
(1561631,54,19,89,51,'Pamatuj, Pane, na útržky činěné služebníkům tvým, a jak jsem já nosil v lůně svém potupu ode všech nejmocnějších národů,'),
(1561632,54,19,89,52,'Jak jsou utrhali nepřátelé tvoji, Hospodine, jak jsou utrhali šlepějím pomazaného tvého.'),
(1561633,54,19,89,53,'Budiž pochválen Hospodin na věky, Amen i Amen.'),
(1561634,54,19,90,1,'Modlitba Mojžíše, muže Božího. Pane, ty jsi býval příbytek náš od národu do pronárodu.'),
(1561635,54,19,90,2,'Prvé, než hory stvořeny byly, nežlis sformoval zemi, a okršlek světa, ano hned od věků a až na věky, ty jsi Bůh silný.'),
(1561636,54,19,90,3,'Ty přivodíš člověka na to, aby setřín byl, říkaje: Navraťtež se zase, synové lidští.'),
(1561637,54,19,90,4,'Nebo by tisíc let přetrval, jest to před očima tvýma jako den včerejší, a bdění noční.'),
(1561638,54,19,90,5,'Povodní zachvacuješ je; jsou sen, a jako bylina hned v jitře pomíjející.'),
(1561639,54,19,90,6,'Toho jitra, kteréhož vykvetne, mění se, u večer pak jsuc podťata, usychá.'),
(1561640,54,19,90,7,'Ale my hyneme od hněvu tvého, a prochlivostí tvou jsme zděšeni.'),
(1561641,54,19,90,8,'Nebo jsi položil nepravosti naše před sebe, a tajnosti naše na světlo oblíčeje svého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561642,54,19,90,9,'Pročež všickni dnové naši v náhle přebíhají pro tvé rozhněvání; k skončení let svých docházíme jako řeč.'),
(1561643,54,19,90,10,'Všech dnů let našich jest let sedmdesáte, aneb jest-li kdo silnějšího přirození, osmdesát let, a i to, což nejzdárnějšího v nich, jest práce a bída, a když to pomine, tožť ihned rychle zaletíme.'),
(1561644,54,19,90,11,'Ale kdo jest, ješto by znal přísnost hněvu tvého, a ostýchal se zůřivosti tvé?'),
(1561645,54,19,90,12,'Naučiž nás počítati dnů našich, abychom uvodili moudrost v srdce.'),
(1561646,54,19,90,13,'Navrať se zase, Hospodine, až dokud prodléváš? Mějž lítost nad služebníky svými.'),
(1561647,54,19,90,14,'Nasyť nás hned v jitře svým milosrdenstvím, tak abychom prozpěvovati, a veseliti se mohli po všecky dny naše.'),
(1561648,54,19,90,15,'Obveseliž nás podlé dnů, v nichž jsi nás ssužoval, a let, v nichž jsme okoušeli zlého.'),
(1561649,54,19,90,16,'Budiž zřejmé při služebnících tvých dílo tvé, a okrasa tvá při synech jejich.'),
(1561650,54,19,90,17,'Budiž nám přítomná i ochotnost Hospodina Boha našeho, a díla rukou našich potvrď mezi námi, díla, pravím, rukou našich potvrď.'),
(1561651,54,19,91,1,'Ten, kdož v skrýši Nejvyššího přebývá, v stínu Všemohoucího odpočívati bude.'),
(1561652,54,19,91,2,'Dím Hospodinu: Útočiště mé a hrad můj, Bůh můj, v němž naději skládati budu.'),
(1561653,54,19,91,3,'Onť zajisté vysvobodí tě z osídla lovce, a od nejjedovatějšího nakažení morního.'),
(1561654,54,19,91,4,'Brky svými přikryje tě, a pod křídly jeho bezpečen budeš; místo štítu a pavézy budeš míti pravdu jeho.'),
(1561655,54,19,91,5,'Nebudeš se báti přístrachu nočního, ani střely létající ve dne.'),
(1561656,54,19,91,6,'Ani nakažení morního, vlekoucího se v mrákotě, ani povětří morního, v polední čas hubícího.'),
(1561657,54,19,91,7,'Padne jich po boku tvém tisíc, a deset tisíců po pravici tvé, ale k tobě se to nepřiblíží.'),
(1561658,54,19,91,8,'Očima toliko svýma to spatříš, a odplatě bezbožných se podíváš.'),
(1561659,54,19,91,9,'Poněvadž jsi Hospodina, kterýž útočiště mé jest, a Nejvyššího za svůj příbytek položil,'),
(1561660,54,19,91,10,'Nepřihodí se tobě nic zlého, aniž se přiblíží jaká rána k stánku tvému.'),
(1561661,54,19,91,11,'Nebo andělům svým přikázal o tobě, aby tě ostříhali na všech cestách tvých.'),
(1561662,54,19,91,12,'Na rukou ponesou tě, abys neurazil o kámen nohy své.'),
(1561663,54,19,91,13,'Po lvu a bazališku choditi budeš, a pošlapáš lvíče i draka.'),
(1561664,54,19,91,14,'Poněvadž mne, dí Bůh, zamiloval, vysvobodím jej, a vyvýším; nebo poznal jméno mé.'),
(1561665,54,19,91,15,'Vzývati mne bude, a vyslyším jej; já s ním budu v ssoužení, vytrhnu a oslavím jej.'),
(1561666,54,19,91,16,'Dlouhostí dnů jej nasytím, a ukáži jemu spasení své.'),
(1561667,54,19,92,1,'Žalm a píseň, ke dni sobotnímu.'),
(1561668,54,19,92,2,'Dobré jest oslavovati Hospodina, a žalmy zpívati jménu tvému, ó Nejvyšší,'),
(1561669,54,19,92,3,'Zvěstovati každé jitro milosrdenství tvé, a pravdu tvou každé noci,'),
(1561670,54,19,92,4,'Při nástroji o desíti strunách, při loutně, a při harfě s písničkou.'),
(1561671,54,19,92,5,'Nebo jsi mne rozveselil, Hospodine, skutky svými, o skutcích rukou tvých zpívati budu.'),
(1561672,54,19,92,6,'Jak velicí jsou skutkové tvoji, Hospodine! Velmi hluboká jsou myšlení tvá.'),
(1561673,54,19,92,7,'Člověk hovadný nezná toho, aniž blázen rozumí tomu,'),
(1561674,54,19,92,8,'Že vyrostají bezbožní jako bylina, a kvetou všickni činitelé nepravosti, aby vyhlazeni byli na věky.'),
(1561675,54,19,92,9,'Ty pak, ó Nejvyšší, že na věky jsi Hospodin.'),
(1561676,54,19,92,10,'Nebo aj, nepřátelé tvoji, Hospodine, nebo aj, nepřátelé tvoji zahynou; rozptýleni budou všickni činitelé nepravosti.'),
(1561677,54,19,92,11,'Můj pak roh vyzdvihneš jako jednorožcův, pokropen budu olejem novým.'),
(1561678,54,19,92,12,'I podívá se oko mé na ty, jenž mne špehují, a o těch nešlechetnících, jenž proti mně povstávají, ušima svýma uslyším.'),
(1561679,54,19,92,13,'Spravedlivý jako palma kvésti bude, a jako cedr na Libánu rozloží se.'),
(1561680,54,19,92,14,'Štípení v domě Hospodinově v síňcích Boha našeho kvésti budou.'),
(1561681,54,19,92,15,'Ještě i v šedinách ovoce ponesou, spanilí a zelení budou,'),
(1561682,54,19,92,16,'Aby to zvěstováno bylo, že přímý jest Hospodin, skála má, a že nepravosti žádné při něm není.'),
(1561683,54,19,93,1,'Hospodin kraluje, v důstojnost se oblékl, oblékl se Hospodin v sílu, a přepásal se; také okršlek země upevnil, aby se nepohnul.'),
(1561684,54,19,93,2,'Utvrzenť jest trůn tvůj přede všemi časy, od věčnosti ty jsi.'),
(1561685,54,19,93,3,'Pozdvihují se řeky, ó Hospodine, pozdvihují řeky zvuku svého, pozdvihují řeky vlnobití svých.'),
(1561686,54,19,93,4,'Nad zvuk mnohých vod, nad sílu vln mořských mnohem silnější jest na výsostech Hospodin.'),
(1561687,54,19,93,5,'Svědectví tvá jsou velmi jistá, domu tvému ušlechtilá svatost, Hospodine, až na věky.'),
(1561688,54,19,94,1,'Bože silný pomst, Hospodine, Bože silný pomst, zastkvěj se.'),
(1561689,54,19,94,2,'Zdvihni se, ó soudce vší země, a dej odplatu pyšným.'),
(1561690,54,19,94,3,'Až dokud bezbožní, Hospodine, až dokud bezbožní budou plésati,'),
(1561691,54,19,94,4,'Žváti a hrdě mluviti, honosíce se, všickni činitelé nepravosti?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561692,54,19,94,5,'Lid tvůj, Hospodine, potírati a dědictví tvé bědovati?'),
(1561693,54,19,94,6,'Vdovy a příchozí mordovati, a sirotky hubiti,'),
(1561694,54,19,94,7,'Říkajíce: Nehledíť na to Hospodin, aniž tomu rozumí Bůh Jákobův?'),
(1561695,54,19,94,8,'Rozumějte, ó vy hovadní v lidu, a vy blázni, kdy srozumíte?'),
(1561696,54,19,94,9,'Zdali ten, jenž učinil ucho, neslyší? A kterýž stvořil oko, zdali nespatří?'),
(1561697,54,19,94,10,'Zdali ten, jenž tresce národy, nebude kárati, kterýž učí lidi umění?'),
(1561698,54,19,94,11,'Hospodinť zná myšlení lidská, že jsou pouhá marnost.'),
(1561699,54,19,94,12,'Blahoslavený jest ten muž, kteréhož ty cvičíš, Hospodine, a z zákona svého jej vyučuješ.'),
(1561700,54,19,94,13,'Abys mu způsobil pokoj před časy zlými, až by za tím vykopána byla bezbožníku jáma.'),
(1561701,54,19,94,14,'Neboť neopustí Hospodin lidu svého, a dědictví svého nezanechá,'),
(1561702,54,19,94,15,'Ale až k spravedlnosti navrátí se soud, a za ním všickni upřímého srdce.'),
(1561703,54,19,94,16,'Kdož by se byl o mne zasadil proti zlostníkům? Kdo by se byl za mne postavil proti těm, jenž páší nepravost?'),
(1561704,54,19,94,17,'Kdyby mi Hospodin nebyl ku pomoci, tudíž by se byla octla duše má v mlčení.'),
(1561705,54,19,94,18,'Již jsem byl řekl: Klesla noha má, ale milosrdenství tvé, ó Hospodine, zdrželo mne.'),
(1561706,54,19,94,19,'Ve množství přemyšlování mých u vnitřnosti mé, tvá potěšování obveselovala duši mou.'),
(1561707,54,19,94,20,'Zdaliž se k tobě přitovaryší stolice převráceností těch, jenž vynášejí nátisk mimo spravedlnost,'),
(1561708,54,19,94,21,'Jenž se shlukují proti duši spravedlivého, a krev nevinnou odsuzují?'),
(1561709,54,19,94,22,'Ale Hospodin jest mým hradem vysokým, a Bůh můj skalou útočiště mého.'),
(1561710,54,19,94,23,'Onť obrátí na ně nepravost jejich, a zlostí jejich zahladí je, zahladí je Hospodin Bůh náš.'),
(1561711,54,19,95,1,'Poďte, zpívejme Hospodinu, prokřikujme skále spasení našeho.'),
(1561712,54,19,95,2,'Předejděme oblíčej jeho s díkčiněním, žalmy prozpěvujme jemu.'),
(1561713,54,19,95,3,'Nebo Hospodin jest Bůh veliký, a král veliký nade všecky bohy,'),
(1561714,54,19,95,4,'V jehož rukou základové země, a vrchové hor jeho jsou.'),
(1561715,54,19,95,5,'Jehož jest i moře, nebo on je učinil, i země, kterouž ruce jeho sformovaly.'),
(1561716,54,19,95,6,'Poďte, sklánějme se, a padněme před ním, klekejme před Hospodinem stvořitelem naším.'),
(1561717,54,19,95,7,'Onť jest zajisté Bůh náš, a my jsme lid pastvy jeho, a stádo rukou jeho. Dnes uslyšíte-li hlas jeho,'),
(1561718,54,19,95,8,'Nezatvrzujte srdce svého, jako při popuzení, a v den pokušení na poušti,'),
(1561719,54,19,95,9,'Kdežto pokoušeli mne otcové vaši, zkusiliť jsou mne, a viděli skutky mé.'),
(1561720,54,19,95,10,'Za čtyřidceti let měl jsem nesnáz s národem tím, a řekl jsem: Lid tento bloudí srdcem, a nepoznali cest mých.'),
(1561721,54,19,95,11,'Jimž jsem přisáhl v hněvě svém, že nevejdou v odpočinutí mé.'),
(1561722,54,19,96,1,'Zpívejte Hospodinu píseň novou, zpívej Hospodinu všecka země.'),
(1561723,54,19,96,2,'Zpívejte Hospodinu, dobrořečte jménu jeho, zvěstujte den po dni spasení jeho.'),
(1561724,54,19,96,3,'Vypravujte mezi národy slávu jeho, mezi všemi lidmi divy jeho.'),
(1561725,54,19,96,4,'Nebo veliký Hospodin, a vší chvály hodný, i hrozný jest nade všecky bohy.'),
(1561726,54,19,96,5,'Všickni zajisté bohové národů jsou modly, ale Hospodin nebesa učinil.'),
(1561727,54,19,96,6,'Sláva a důstojnost před ním, síla i okrasa v svatyni jeho.'),
(1561728,54,19,96,7,'Vzdejte Hospodinu čeledi národů, vzdejte Hospodinu čest i moc.'),
(1561729,54,19,96,8,'Vzdejte Hospodinu čest jména jeho, přineste dary, a vejděte do síňcí jeho.'),
(1561730,54,19,96,9,'Sklánějte se Hospodinu v okrase svatoti, boj se oblíčeje jeho všecka země.'),
(1561731,54,19,96,10,'Rcete mezi pohany: Hospodin kraluje, a že i okršlek zemský upevněn bude, tak aby se nepohnul, a že souditi bude lidi spravedlivě.'),
(1561732,54,19,96,11,'Rozveseltež se nebesa, a plésej země, zvuč moře, i což v něm jest.'),
(1561733,54,19,96,12,'Plésej pole a vše, což na něm, tehdáž ať prozpěvuje všecko dříví lesní,'),
(1561734,54,19,96,13,'Před tváří Hospodina; neboť se béře, béře se zajisté, aby soudil zemi. Budeť souditi okršlek světa v spravedlnosti, a národy v pravdě své.'),
(1561735,54,19,97,1,'Hospodin kraluje, plésej země, a vesel se ostrovů všecko množství.'),
(1561736,54,19,97,2,'Oblak a mrákota jest vůkol něho, spravedlnost a soud základ trůnu jeho.'),
(1561737,54,19,97,3,'Oheň předchází jej, a zapaluje vůkol nepřátely jeho.'),
(1561738,54,19,97,4,'Zasvěcujíť se po okršlku světa blýskání jeho; to viduc země, děsí se.'),
(1561739,54,19,97,5,'Hory jako vosk rozplývají se před oblíčejem Hospodina, před oblíčejem Panovníka vší země.'),
(1561740,54,19,97,6,'Nebesa vypravují o jeho spravedlnosti, a slávu jeho spatřují všickni národové.'),
(1561741,54,19,97,7,'Zastyďte se všickni, kteříž sloužíte rytinám, kteříž se chlubíte modlami; sklánějte se před ním všickni bohové.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561742,54,19,97,8,'To uslyše Sion, rozveselí se, a zpléší dcery Judské z příčiny soudů tvých, Hospodine.'),
(1561743,54,19,97,9,'Nebo ty, Hospodine, jsi nejvyšší na vší zemi, a velice jsi vyvýšený nade všecky bohy.'),
(1561744,54,19,97,10,'Vy, kteříž milujete Hospodina, mějte v nenávisti to, což zlého jest; onť ostříhá duší svatých svých, a z ruky bezbožníků je vytrhuje.'),
(1561745,54,19,97,11,'Světlo vsáto jest spravedlivým, a radost těm, kteříž jsou upřímého srdce.'),
(1561746,54,19,97,12,'Veselte se, spravedliví v Hospodinu, a oslavujte památku svatosti jeho.'),
(1561747,54,19,98,1,'Žalm. Zpívejte Hospodinu píseň novou, neboť jest divné věci učinil; spomohla mu pravice jeho, a rámě svatosti jeho.'),
(1561748,54,19,98,2,'V známost uvedl Hospodin spasení své, před očima národů zjevil spravedlnost svou.'),
(1561749,54,19,98,3,'Rozpomenul se na milosrdenství své, a na pravdu svou k domu Izraelskému; všecky končiny země vidí spasení Boha našeho.'),
(1561750,54,19,98,4,'Prokřikuj Hospodinu všecka země; zvuk vydejte, prozpěvujte, a žalmy zpívejte.'),
(1561751,54,19,98,5,'Žalmy zpívejte Hospodinu na citaře, k citaře i hlasem přizpěvujte.'),
(1561752,54,19,98,6,'Trubami a zvučnými pozouny hlas vydejte před králem Hospodinem.'),
(1561753,54,19,98,7,'Zvuč moře i to, což v něm jest, okršlek světa i ti, kteříž na něm bydlí.'),
(1561754,54,19,98,8,'Řeky rukama plésejte, spolu i hory prozpěvujte,'),
(1561755,54,19,98,9,'Před Hospodinem; neboť se béře, aby soudil zemi. Budeť souditi okršlek světa v spravedlnosti, a národy v pravosti.'),
(1561756,54,19,99,1,'Hospodin kraluje, užasněte se národové; sedí nad cherubíny, pohniž se země.'),
(1561757,54,19,99,2,'Hospodin na Sionu veliký, a vyvýšený jest nade všecky lidi.'),
(1561758,54,19,99,3,'Oslavujte jméno tvé veliké a hrozné, nebo svaté jest.'),
(1561759,54,19,99,4,'Moc zajisté králova miluje soud; ty jsi ustanovil práva, soud a spravedlnost v Jákobovi ty konáš.'),
(1561760,54,19,99,5,'Vyvyšujte Hospodina Boha našeho, a sklánějte se u podnoží noh jeho, svatýť jest.'),
(1561761,54,19,99,6,'Mojžíš a Aron mezi kněžími jeho, a Samuel mezi vzývajícími jméno jeho; volávali k Hospodinu, a on je vyslýchal.'),
(1561762,54,19,99,7,'V sloupu oblakovém mluvíval k nim; kteřížto když ostříhali svědectví jeho, i ustanovení jim vydal.'),
(1561763,54,19,99,8,'Hospodine Bože náš, tys je vyslýchal, Bože, bývals jim milostiv, i když jsi je trestal pro výstupky jejich.'),
(1561764,54,19,99,9,'Vyvyšujte Hospodina Boha našeho, a sklánějte se na hoře svaté jeho; neboť jest svatý Hospodin Bůh náš.'),
(1561765,54,19,100,1,'Žalm k díků činění. Prokřikuj Hospodinu všecka země.'),
(1561766,54,19,100,2,'Služte Hospodinu s veselím, předstupte před oblíčej jeho s prozpěvováním.'),
(1561767,54,19,100,3,'Vězte, že Hospodin jest Bůh; on učinil nás, a ne my sami sebe, abychom byli lid jeho, a ovce pastvy jeho.'),
(1561768,54,19,100,4,'Vcházejte do bran jeho s díkčiněním, a do síní jeho s chvalami; oslavujte jej, a dobrořečte jménu jeho.'),
(1561769,54,19,100,5,'Nebo dobrý jest Hospodin, na věky milosrdenství jeho, a od národu až do pronárodu pravda jeho.'),
(1561770,54,19,101,1,'Žalm Davidův. O milosrdenství a soudu zpívati budu, tobě, ó Hospodine, žalmy budu zpívati.'),
(1561771,54,19,101,2,'Opatrně se míti budu na cestě přímé, až přijdeš ke mně; choditi budu ustavičně v upřímnosti srdce svého i v domě svém.'),
(1561772,54,19,101,3,'Nepředstavímť sobě před oči věci nešlechetné; skutek uchylujících se v nenávisti mám, nepřichytíť se mne.'),
(1561773,54,19,101,4,'Srdce převrácené odstoupí ode mne, zlého nebudu oblibovati.'),
(1561774,54,19,101,5,'Škodícího jazykem bližnímu svému tajně, tohoť vytnu; očí vysokých a mysli naduté nikoli nebudu moci trpěti.'),
(1561775,54,19,101,6,'Oči mé na pravdomluvné v zemi, aby sedali se mnou; kdož chodí po cestě upřímé, tenť mi sloužiti bude.'),
(1561776,54,19,101,7,'Nebude bydliti v domě mém činící lest, a mluvící lež nebude míti místa u mne.'),
(1561777,54,19,101,8,'Každého jitra pléniti budu všecky nešlechetné z země, abych tak vyplénil z města Hospodinova všecky, kdož páší nepravost.'),
(1561778,54,19,102,1,'Modlitba chudého, když sevřín jsa, před Hospodinem vylévá žádosti své.'),
(1561779,54,19,102,2,'Hospodine, slyš modlitbu mou, a volání mé přijdiž k tobě.'),
(1561780,54,19,102,3,'Neskrývej tváři své přede mnou, v den ssoužení mého nakloň ke mně ucha svého; když k tobě volám, rychle vyslyš mne.'),
(1561781,54,19,102,4,'Nebo mizejí jako dým dnové moji, a kosti mé jako ohniště vypáleny jsou.'),
(1561782,54,19,102,5,'Poraženo jest jako bylina, a usvadlo srdce mé, tak že jsem chleba svého jísti zapomenul.'),
(1561783,54,19,102,6,'Od hlasu lkání mého přilnuly kosti mé k kůži mé.'),
(1561784,54,19,102,7,'Podobný jsem učiněn pelikánu na poušti, jsem jako výr na pustinách.'),
(1561785,54,19,102,8,'Bdím, a jsem jako vrabec osamělý na střeše.'),
(1561786,54,19,102,9,'Každý den utrhají mi nepřátelé moji, a posměvači moji proklínají mnou.'),
(1561787,54,19,102,10,'Nebo jídám popel jako chléb, a k nápoji svému slz přiměšuji,'),
(1561788,54,19,102,11,'Pro rozhněvání tvé a zažžený hněv tvůj; nebo zdvihna mne, hodils mnou.'),
(1561789,54,19,102,12,'Dnové moji jsou jako stín nachýlený, a já jako tráva usvadl jsem.'),
(1561790,54,19,102,13,'Ale ty, Hospodine, na věky zůstáváš, a památka tvá od národu až do pronárodu.'),
(1561791,54,19,102,14,'Ty povstana, smiluješ se nad Sionem, nebo čas jest učiniti milost jemu, a čas uložený přišel.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561792,54,19,102,15,'Nebo líbost mají služebníci tvoji v kamení jeho, a nad prachem jeho slitují se,'),
(1561793,54,19,102,16,'Aby se báli pohané jména Hospodinova, a všickni králové země slávy tvé,'),
(1561794,54,19,102,17,'Když by Hospodin vzdělal Sion, a ukázal se v slávě své,'),
(1561795,54,19,102,18,'Když by popatřil k modlitbě poníženého lidu, nepohrdaje modlitbou jejich.'),
(1561796,54,19,102,19,'Budeť to zapsáno pro budoucí potomky, a lid, kterýž má stvořen býti, chváliti bude Hospodina,'),
(1561797,54,19,102,20,'Že shlédl s výsosti svatosti své. Hospodin s nebe na zemi že popatřil,'),
(1561798,54,19,102,21,'Aby vyslyšel vzdychání vězňů, a rozvázal ty, kteříž již k smrti oddání byli,'),
(1561799,54,19,102,22,'Aby vypravovali na Sionu jméno Hospodinovo, a chválu jeho v Jeruzalémě,'),
(1561800,54,19,102,23,'Když se spolu shromáždí národové a království, aby sloužili Hospodinu.'),
(1561801,54,19,102,24,'Ztrápilť jest na cestě sílu mou, ukrátil dnů mých,'),
(1561802,54,19,102,25,'Až jsem řekl: Můj Bože, nebeř mne u prostřed dnů mých; od národu zajisté až do pronárodu jsou léta tvá,'),
(1561803,54,19,102,26,'I prvé nežlis založil zemi, a dílo rukou svých, nebesa.'),
(1561804,54,19,102,27,'Onať pominou, ty pak zůstáváš; všecky ty věci jako roucho zvetšejí, jako oděv změníš je, a změněny budou.'),
(1561805,54,19,102,28,'Ty pak jsi tentýž, a léta tvá nikdy nepřestanou.'),
(1561806,54,19,102,29,'Synové služebníků tvých bydliti budou, a símě jejich zmocní se před tebou.'),
(1561807,54,19,103,1,'Davidův. Dobrořeč duše má Hospodinu, a všecky vnitřnosti mé jménu svatému jeho.'),
(1561808,54,19,103,2,'Dobrořeč duše má Hospodinu, a nezapomínej se na všecka dobrodiní jeho,'),
(1561809,54,19,103,3,'Kterýž odpouští tobě všecky nepravosti, kterýž uzdravuje všecky nemoci tvé,'),
(1561810,54,19,103,4,'Kterýž vysvobozuje od zahynutí život tvůj, kterýž tě korunuje milosrdenstvím a mnohým slitováním,'),
(1561811,54,19,103,5,'Kterýž nasycuje dobrými věcmi ústa tvá, tak že se obnovuje jako orlice mladost tvá.'),
(1561812,54,19,103,6,'Činí, což spravedlivého jest, Hospodin, a soudy všechněm utištěným.'),
(1561813,54,19,103,7,'Známé učinil Mojžíšovi cesty své, synům Izraelským skutky své.'),
(1561814,54,19,103,8,'Lítostivý a milostivý jest Hospodin, dlouhoshovívající a mnohého milosrdenství.'),
(1561815,54,19,103,9,'Nebudeť ustavičně žehrati, ani na věky hněvu držeti.'),
(1561816,54,19,103,10,'Ne podlé hříchů našich nakládá s námi, ani vedlé nepravostí našich odplacuje nám.'),
(1561817,54,19,103,11,'Nebo jakož jsou vysoko nebesa nad zemí, tak jest vyvýšené milosrdenství jeho nad těmi, kteříž se ho bojí.'),
(1561818,54,19,103,12,'A jak daleko jest východ od západu, tak daleko vzdálil od nás přestoupení naše.'),
(1561819,54,19,103,13,'Jakož se slitovává otec nad dítkami,tak se slitovává Hospodin nad těmi, kteříž se hobojí.'),
(1561820,54,19,103,14,'Onť zajisté zná slepení naše, v paměti má, že prach jsme.'),
(1561821,54,19,103,15,'Dnové člověka jsou jako tráva, a jako květ polní, tak kvete.'),
(1561822,54,19,103,16,'Jakž vítr na něj povane, anť ho není, aniž ho již více pozná místo jeho.'),
(1561823,54,19,103,17,'Milosrdenství pak Hospodinovo od věků až na věky nad těmi, kteříž se ho bojí, a spravedlnost jeho nad syny synů,'),
(1561824,54,19,103,18,'Kteříž ostříhají smlouvy jeho, a pamatují na přikázaní jeho, aby je činili.'),
(1561825,54,19,103,19,'Hospodin na nebesích utvrdil trůn svůj, a kralování jeho nade vším panuje.'),
(1561826,54,19,103,20,'Dobrořečte Hospodinu andělé jeho, kteříž jste mocní v síle, a činíte slovo jeho, poslušní jsouc hlasu slova jeho.'),
(1561827,54,19,103,21,'Dobrořečte Hospodinu všickni zástupové jeho, služebníci jeho, kteříž činíte vůli jeho.'),
(1561828,54,19,103,22,'Dobrořečte Hospodinu všickni skutkové jeho, na všech místech panování jeho. Dobrořeč duše má Hospodinu.'),
(1561829,54,19,104,1,'Dobrořeč duše má Hospodinu. Hospodine Bože můj, velmi jsi veliký, velebnost a krásu jsi oblékl.'),
(1561830,54,19,104,2,'Přioděls se světlem jako rouchem, roztáhls nebesa jako kortýnu.'),
(1561831,54,19,104,3,'Kterýž sklenul na vodách paláce své, kterýž užívá hustých oblaků místo vozů, a vznáší se na peří větrovém.'),
(1561832,54,19,104,4,'Kterýž činí posly své duchy, služebníky své oheň plápolající.'),
(1561833,54,19,104,5,'Založil zemi na sloupích jejich, tak že se nepohne na věky věků.'),
(1561834,54,19,104,6,'Propastí jako rouchem byl jsi ji přioděl, i nad horami stály vody.'),
(1561835,54,19,104,7,'K žehrání tvému rozběhly se, před hřmotem hromu tvého pospíšily,'),
(1561836,54,19,104,8,'(Vystoupily hory, snížilo se údolí), na místo, kteréž jsi jim založil.'),
(1561837,54,19,104,9,'Meze jsi položil, aby jich nepřestupovaly, ani se navracovaly k přikrývání země.'),
(1561838,54,19,104,10,'Kterýž vypouštíš potoky přes údolé, aby tekli mezi horami,'),
(1561839,54,19,104,11,'A nápoj dávali všechněm živočichům polním. Tuť uhašují oslové divocí žízeň svou.'),
(1561840,54,19,104,12,'Při nich hnízdí se ptactvo nebeské, a z prostřed ratolestí hlas svůj vydává.'),
(1561841,54,19,104,13,'Kterýž svlažuješ hory z výsostí svých, aby ovocem činů tvých sytila se země.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561842,54,19,104,14,'Dáváš, aby rostla tráva dobytku, a bylina ku potřebě člověku, abys tak vyvodil chléb z země,'),
(1561843,54,19,104,15,'A víno, jenž obveseluje srdce člověka. Činí, aby se stkvěla tvář od oleje, ano i pokrmem zdržuje život lidský.'),
(1561844,54,19,104,16,'Nasyceno bývá i dříví Hospodinovo, cedrové Libánští, kteréž štípil.'),
(1561845,54,19,104,17,'Na nichž se ptáci hnízdí, i čáp příbytek svůj má na jedlí.'),
(1561846,54,19,104,18,'Hory vysoké jsou kamsíků, skály útočiště králíků.'),
(1561847,54,19,104,19,'Učinil měsíc k jistým časům, a slunce zná západ svůj.'),
(1561848,54,19,104,20,'Uvodíš tmu, a bývá noc, v níž vybíhají všickni živočichové lesní:'),
(1561849,54,19,104,21,'Lvíčata řvoucí po loupeži, aby hledali od Boha silného pokrmu svého.'),
(1561850,54,19,104,22,'Když slunce vychází, zase shromažďují se, a v doupatech svých se ukládají.'),
(1561851,54,19,104,23,'Člověk vychází ku práci své, a k dílu svému až do večera.'),
(1561852,54,19,104,24,'Jak mnozí a velicí jsou skutkové tvoji, Hospodine! Všeckys je moudře učinil, plná jest země bohatství tvého.'),
(1561853,54,19,104,25,'V moři pak velikém a přeširokém, tamť jsou hmyzové nesčíslní, a živočichové malí i velicí.'),
(1561854,54,19,104,26,'Tuť bárky přecházejí i velryb, kteréhož jsi stvořil, aby v něm hrál.'),
(1561855,54,19,104,27,'Všecko to na tě očekává, abys jim dával pokrm časem svým.'),
(1561856,54,19,104,28,'Když jim dáváš, sbírají; když otvíráš ruku svou, nasyceni bývají dobrými věcmi.'),
(1561857,54,19,104,29,'Když skrýváš tvář svou, rmoutí se; když odjímáš ducha jejich, hynou, a v prach svůj se navracejí.'),
(1561858,54,19,104,30,'Vysíláš ducha svého, a zase stvořeni bývají, a obnovuješ tvář země.'),
(1561859,54,19,104,31,'Budiž sláva Hospodinova na věky, rozveselujž se Hospodin v skutcích svých.'),
(1561860,54,19,104,32,'On když pohledí na zemi, anať se třese; když se dotkne hor, anť se kouří.'),
(1561861,54,19,104,33,'Zpívati budu Hospodinu, dokudž jsem živ; žalmy Bohu svému zpívati budu, pokudž mne stává.'),
(1561862,54,19,104,34,'Libé bude přemyšlování mé o něm, jáť rozveselím se v Hospodinu.'),
(1561863,54,19,104,35,'Ó by hříšníci vyhynuli z země, a bezbožných aby již nebylo. Dobrořeč duše má Hospodinu. Halelujah.'),
(1561864,54,19,105,1,'Oslavujte Hospodina, ohlašujte jméno jeho, oznamujte mezi národy skutky jeho.'),
(1561865,54,19,105,2,'Zpívejte jemu, žalmy prozpěvujte jemu, rozmlouvejte o všech divných skutcích jeho.'),
(1561866,54,19,105,3,'Chlubte se jménem svatým jeho; vesel se srdce těch, kteříž hledají Hospodina.'),
(1561867,54,19,105,4,'Hledejte Hospodina a síly jeho, hledejte tváři jeho ustavičně.'),
(1561868,54,19,105,5,'Rozpomínejte se na divné skutky jeho, kteréž činil, na zázraky jeho a na soudy úst jeho,'),
(1561869,54,19,105,6,'Símě Abrahamovo, služebníka jeho, synové Jákobovi, vyvolení jeho.'),
(1561870,54,19,105,7,'Onť jest Hospodin Bůh náš, na vší zemi soudové jeho.'),
(1561871,54,19,105,8,'Pamatuje věčně na smlouvu svou, na slovo, kteréž přikázal až do tisíce pokolení,'),
(1561872,54,19,105,9,'Kteréž upevnil s Abrahamem, a na přísahu svou učiněnou Izákovi.'),
(1561873,54,19,105,10,'Nebo ji utvrdil Jákobovi za ustanovení, Izraelovi za smlouvu věčnou,'),
(1561874,54,19,105,11,'Pravě: Tobě dám zemi Kananejskou za podíl dědictví vašeho,'),
(1561875,54,19,105,12,'Ješto jich byl malý počet, malý počet, a ještě v ní byli pohostinu.'),
(1561876,54,19,105,13,'Přecházeli zajisté z národu do národu, a z království k jinému lidu.'),
(1561877,54,19,105,14,'Nedopustil žádnému ublížiti jim, ano i krále pro ně trestal, řka:'),
(1561878,54,19,105,15,'Nedotýkejte se pomazaných mých, a prorokům mým nečiňte nic zlého.'),
(1561879,54,19,105,16,'Když přivolav hlad na zemi, všecku hůl chleba polámal,'),
(1561880,54,19,105,17,'Poslal před nimi muže znamenitého, jenž za služebníka prodán byl, totiž Jozefa.'),
(1561881,54,19,105,18,'Jehož nohy sevřeli pouty, železa podniknouti musil,'),
(1561882,54,19,105,19,'Až do toho času, když se zmínka stala o něm; řeč Hospodinova zkusila ho.'),
(1561883,54,19,105,20,'Poslav král, propustiti ho rozkázal, panovník lidu svobodna ho učinil.'),
(1561884,54,19,105,21,'Ustanovil ho pánem domu svého, a panovníkem všeho vládařství svého,'),
(1561885,54,19,105,22,'Aby vládl i knížaty jeho podlé své líbosti, a starce jeho vyučoval moudrosti.'),
(1561886,54,19,105,23,'Potom všel Izrael do Egypta, a Jákob pohostinu byl v zemi Chamově.'),
(1561887,54,19,105,24,'Kdež rozmnožil Bůh lid svůj náramně, a učinil, aby silnější byl nad nepřátely své.'),
(1561888,54,19,105,25,'Změnil mysl těchto, aby v nenávisti měli lid jeho, a aby ukládali lest o služebnících jeho.'),
(1561889,54,19,105,26,'I poslal Mojžíše slouhu svého, a Arona, kteréhož vyvolil.'),
(1561890,54,19,105,27,'Kteříž předložili jim slova znamení jeho a zázraků v zemi Chamově.'),
(1561891,54,19,105,28,'Poslal tmu, a zatmělo se, aniž odporná byla slovu jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561892,54,19,105,29,'Obrátil vody jejich v krev, a zmořil ryby v nich.'),
(1561893,54,19,105,30,'Vydala země jejich množství žab, i v pokoleních králů jejich.'),
(1561894,54,19,105,31,'Řekl, i přišla směsice žížal, a stěnice na všecky končiny jejich.'),
(1561895,54,19,105,32,'Dal místo deště krupobití, oheň hořící na zemi jejich,'),
(1561896,54,19,105,33,'Tak že potloukl réví jejich i fíkoví jejich, a zpřerážel dříví v krajině jejich.'),
(1561897,54,19,105,34,'Řekl, i přišly kobylky a chroustů nesčíslné množství.'),
(1561898,54,19,105,35,'I sežrali všelikou bylinu v krajině jejich, a pojedli úrody země jejich.'),
(1561899,54,19,105,36,'Nadto pobil všecko prvorozené v zemi jejich, počátek všeliké síly jejich.'),
(1561900,54,19,105,37,'Tedy vyvedl své s stříbrem a zlatem, aniž byl v pokoleních jejich, ješto by se poklesl.'),
(1561901,54,19,105,38,'Veselili se Egyptští, když tito vycházeli; nebo byl připadl na ně strach Izraelských.'),
(1561902,54,19,105,39,'Roztáhl oblak k zastírání jich, a oheň k osvěcování noci.'),
(1561903,54,19,105,40,'K žádosti přivedl křepelky, a chlebem nebeským sytil je.'),
(1561904,54,19,105,41,'Otevřel skálu, i tekly vody, a odcházely přes vyprahlá místa jako řeka.'),
(1561905,54,19,105,42,'Nebo pamětliv byl na slovo svatosti své, k Abrahamovi služebníku svému mluvené.'),
(1561906,54,19,105,43,'Protož vyvedl lid svůj s radostí, s prozpěvováním vyvolené své.'),
(1561907,54,19,105,44,'A dal jim země pohanů, a tak úsilí národů dědičně obdrželi,'),
(1561908,54,19,105,45,'Aby zachovávali ustanovení jeho, a práv jeho ostříhali. Halelujah.'),
(1561909,54,19,106,1,'Halelujah. Oslavujte Hospodina, nebo dobrý jest, nebo na věky milosrdenství jeho.'),
(1561910,54,19,106,2,'Kdo může vymluviti nesmírnou moc Hospodinovu, a vypraviti všecku chválu jeho?'),
(1561911,54,19,106,3,'Blahoslavení, kteříž ostříhají soudu, a činí spravedlnost každého času.'),
(1561912,54,19,106,4,'Pamatuj na mne, Hospodine, pro milost k lidu svému, navštěv mne spasením svým,'),
(1561913,54,19,106,5,'Abych užíval dobrých věcí s vyvolenými tvými, a veselil se veselím národu tvého, a chlubil se spolu s dědictvím tvým.'),
(1561914,54,19,106,6,'Zhřešili jsme i s otci svými, neprávě jsme činili, a bezbožnost páchali.'),
(1561915,54,19,106,7,'Otcové naši v Egyptě nerozuměli předivným skutkům tvým, aniž pamatovali na množství milosrdenství tvých, ale odporni byli při moři, při moři Rudém.'),
(1561916,54,19,106,8,'A však vysvobodil je pro jméno své, aby v známost uvedl moc svou.'),
(1561917,54,19,106,9,'Nebo přimluvil moři Rudému, a vyschlo; i provedl je skrze hlubiny, jako po poušti.'),
(1561918,54,19,106,10,'A tak zachoval je od ruky toho, jenž jich nenáviděl, a vyprostil je z ruky nepřítele.'),
(1561919,54,19,106,11,'V tom přikryly vody ty, kteříž je ssužovali, nezůstalo ani jednoho z nich.'),
(1561920,54,19,106,12,'A ačkoli věřili slovům jeho, a zpívali chválu jeho,'),
(1561921,54,19,106,13,'Však rychle zapomenuli na skutky jeho, a nečekali na radu jeho;'),
(1561922,54,19,106,14,'Ale jati jsouce žádostí na poušti, pokoušeli Boha silného na pustinách.'),
(1561923,54,19,106,15,'I dal jim, čehož se jim chtělo, a však dopustil hubenost na život jejich.'),
(1561924,54,19,106,16,'Potom, když horlili proti Mojžíšovi v vojště, a Aronovi, svatému Hospodinovu,'),
(1561925,54,19,106,17,'Otevřevši se země, požřela Dátana, a přikryla zběř Abironovu.'),
(1561926,54,19,106,18,'A roznícen byl oheň na rotu jejich, plamen spálil bezbožníky.'),
(1561927,54,19,106,19,'Udělali i tele na Orébě, a skláněli se slitině.'),
(1561928,54,19,106,20,'A změnivše slávu svou v podobiznu vola, jenž jí trávu,'),
(1561929,54,19,106,21,'Zapomněli na Boha silného, spasitele svého, kterýž činil veliké věci v Egyptě.'),
(1561930,54,19,106,22,'A předivné v zemi Chamově, přehrozné při moři Rudém.'),
(1561931,54,19,106,23,'Pročež řekl, že je vypléní, kdyby se byl Mojžíš, vyvolený jeho, nepostavil v té mezeře před ním, a neodvrátil prchlivosti jeho, aby nehubil.'),
(1561932,54,19,106,24,'Za tím zošklivili sobě zemi žádanou, nevěříce slovu jeho.'),
(1561933,54,19,106,25,'A repcíce v staních svých, neposlouchali hlasu Hospodinova.'),
(1561934,54,19,106,26,'A protož pozdvihl ruky své proti nim, aby je rozmetal po poušti,'),
(1561935,54,19,106,27,'A aby rozptýlil símě jejich mezi pohany, a rozehnal je do zemí.'),
(1561936,54,19,106,28,'Spřáhli se také byli s modlou Belfegor, a jedli oběti mrch.'),
(1561937,54,19,106,29,'A tak dráždili Boha skutky svými, až se na ně obořila rána,'),
(1561938,54,19,106,30,'Až se postavil Fínes, a pomstu vykonal, i přetržena jest rána ta.'),
(1561939,54,19,106,31,'Což jest mu počteno za spravedlnost od národu do pronárodu, a až na věky.'),
(1561940,54,19,106,32,'Opět ho byli popudili při vodách sváru, až se i Mojžíšovi zle stalo pro ně.'),
(1561941,54,19,106,33,'Nebo k hořkosti přivedli ducha jeho, a pronesl ji rty svými.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561942,54,19,106,34,'K tomu nevyplénili ani národů těch, o kterýchž jim byl Hospodin poručil,'),
(1561943,54,19,106,35,'Ale směšujíce se s těmi národy, naučili se skutkům jejich,'),
(1561944,54,19,106,36,'A sloužili modlám jejich, kteréž jim byly osídlem.'),
(1561945,54,19,106,37,'Obětovali zajisté syny své a dcery své ďáblům.'),
(1561946,54,19,106,38,'A vylili krev nevinnou, krev synů svých a dcer svých, kteréž obětovali trapidlům Kananejským, tak že poškvrněna jest země těmi vraždami.'),
(1561947,54,19,106,39,'I zmazali se skutky svými, a smilnili činy svými.'),
(1561948,54,19,106,40,'Protož rozpáliv se v prchlivosti Hospodin na lid svůj, v ošklivost vzal dědictví své.'),
(1561949,54,19,106,41,'A vydal je v ruce pohanů. I panovali nad nimi ti, jenž je v nenávisti měli,'),
(1561950,54,19,106,42,'A utiskali je nepřátelé jejich, tak že sníženi jsou pod ruku jejich.'),
(1561951,54,19,106,43,'Mnohokrát je vysvobozoval, oni však popouzeli ho radou svou, pročež potlačeni jsou pro nepravost svou.'),
(1561952,54,19,106,44,'A však patřil na úzkost jejich, a slyšel křik jejich.'),
(1561953,54,19,106,45,'Nebo se rozpomenul na smlouvu svou s nimi, a želel toho podlé množství milosrdenství svých,'),
(1561954,54,19,106,46,'Tak že naklonil k nim lítostí všecky, kteříž je u vězení drželi.'),
(1561955,54,19,106,47,'Zachovej nás, Hospodine Bože náš, a shromažď nás z těch pohanů, abychom slavili jméno tvé svaté, a chlubili se v chvále tvé.'),
(1561956,54,19,106,48,'Požehnaný Hospodin Bůh Izraelský od věků až na věky. Na to rciž všecken lid: Amen, Halelujah.'),
(1561957,54,19,107,1,'Oslavujte Hospodina, nebo jest dobrý, nebo na věky milosrdenství jeho.'),
(1561958,54,19,107,2,'Nechť o tom vypravují ti, kteříž jsou vykoupeni skrze Hospodina, jak je on vykoupil z ruky těch, kteříž je ssužovali,'),
(1561959,54,19,107,3,'A shromáždil je z zemí, od východu a od západu, od půlnoci i od moře.'),
(1561960,54,19,107,4,'Bloudili po poušti, po cestách pustých, města k přebývání nenacházejíce.'),
(1561961,54,19,107,5,'Hladovití a žízniví byli, až v nich svadla duše jejich.'),
(1561962,54,19,107,6,'Když volali k Hospodinu v ssoužení svém, z úzkostí jejich vytrhl je,'),
(1561963,54,19,107,7,'A vedl je po cestě přímé, aby přišli do města k bydlení.'),
(1561964,54,19,107,8,'Nechať oslavují před Hospodinem milosrdenství jeho, a divné skutky jeho před syny lidskými,'),
(1561965,54,19,107,9,'Poněvadž napájí duši žíznivou, a duši hladovitou naplňuje dobrými věcmi.'),
(1561966,54,19,107,10,'Kteříž sedí ve tmě a v stínu smrti, sevříni jsouce bídou i železy,'),
(1561967,54,19,107,11,'Protože odporni byli řečem Boha silného, a radou Nejvyššího pohrdli.'),
(1561968,54,19,107,12,'Pročež ponížil bídou srdce jejich, padli, a nebylo pomocníka.'),
(1561969,54,19,107,13,'Když volají k Hospodinu v ssoužení svém, z úzkostí je vysvobozuje.'),
(1561970,54,19,107,14,'Vyvodí je z temností a stínu smrti, a svazky jejich trhá.'),
(1561971,54,19,107,15,'Nechať oslavují před Hospodinem milosrdenství jeho, a divné skutky jeho před syny lidskými,'),
(1561972,54,19,107,16,'Poněvadž láme brány měděné, a závory železné posekává.'),
(1561973,54,19,107,17,'Blázni pro cestu převrácenosti své, a pro nepravosti své v trápení bývají.'),
(1561974,54,19,107,18,'Oškliví se jim všeliký pokrm, až se i k branám smrti přibližují.'),
(1561975,54,19,107,19,'Když volají k Hospodinu v ssoužení svém, z úzkostí jejich je vysvobozuje.'),
(1561976,54,19,107,20,'Posílá slovo své, a uzdravuje je, a vysvobozuje je z hrobu.'),
(1561977,54,19,107,21,'Nechať oslavují před Hospodinem milosrdenství jeho, a divné skutky jeho před syny lidskými,'),
(1561978,54,19,107,22,'A obětujíce oběti chvály, ať vypravují skutky jeho s prozpěvováním.'),
(1561979,54,19,107,23,'Kteří se plaví po moři na lodech, pracujíce na velikých vodách,'),
(1561980,54,19,107,24,'Tiť vídají skutky Hospodinovy, a divy jeho v hlubokosti.'),
(1561981,54,19,107,25,'Jakž jen dí, hned se strhne vítr bouřlivý, a dme vlny mořské.'),
(1561982,54,19,107,26,'Vznášejí se k nebi, sstupují do propasti, duše jejich v nebezpečenství rozplývá se.'),
(1561983,54,19,107,27,'Motají se a nakloňují jako opilý, a všecko umění jejich mizí.'),
(1561984,54,19,107,28,'Když volají k Hospodinu v ssoužení svém, z úzkostí jejich je vysvobozuje.'),
(1561985,54,19,107,29,'Proměňuje bouři v utišení, tak že umlkne vlnobití jejich.'),
(1561986,54,19,107,30,'I veselí se, že utichlo; a tak přivodí je k břehu žádostivému.'),
(1561987,54,19,107,31,'Nechať oslavují před Hospodinem milosrdenství jeho, a divné skutky jeho před syny lidskými.'),
(1561988,54,19,107,32,'Nechť ho vyvyšují v shromáždění lidu, a v radě starců chválí jej.'),
(1561989,54,19,107,33,'Obrací řeky v poušť, a prameny vod v suchost,'),
(1561990,54,19,107,34,'Zemi úrodnou v slatinnou, pro zlost obyvatelů jejích.'),
(1561991,54,19,107,35,'Pustiny obrací v jezera, a zemi vyprahlou v prameny vod.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1561992,54,19,107,36,'I osazuje na ní hladovité, aby stavěli města k bydlení.'),
(1561993,54,19,107,37,'Kteříž osívají pole, a dělají vinice, a shromažďují sobě užitek úrody.'),
(1561994,54,19,107,38,'Takť on jim žehná, že se rozmnožují velmi, a dobytka jejich neumenšuje.'),
(1561995,54,19,107,39,'A někdy pak umenšeni a sníženi bývají ukrutenstvím, bídou a truchlostí,'),
(1561996,54,19,107,40,'Když vylévá pohrdání na knížata, dopouštěje, aby bloudili po poušti bezcestné.'),
(1561997,54,19,107,41,'Onť vyzdvihuje nuzného z trápení, a rozmnožuje rodinu jako stádo.'),
(1561998,54,19,107,42,'Nechť to spatřují upřímí, a rozveselí se, ale všeliká nepravost ať zacpá ústa svá.'),
(1561999,54,19,107,43,'Ale kdo jest tak moudrý, aby toho šetřil, a vyrozumíval mnohému milosrdenství Hospodinovu?'),
(1562000,54,19,108,1,'Píseň a žalm Davidův.'),
(1562001,54,19,108,2,'Hotovo jest srdce mé, Bože, zpívati a oslavovati tě budu, také i sláva má.'),
(1562002,54,19,108,3,'Probuď se loutno a harfo, když v svitání povstávám.'),
(1562003,54,19,108,4,'Slaviti tě budu mezi lidmi, Hospodine, a tobě žalmy prozpěvovati mezi národy.'),
(1562004,54,19,108,5,'Nebo nad nebesa větší jest milosrdenství tvé, a až k nejvyšším oblakům pravda tvá.'),
(1562005,54,19,108,6,'Vyvyšiž se nad nebesa, ó Bože, a nade všecku zemi sláva tvá.'),
(1562006,54,19,108,7,'Ať jsou vysvobozeni milí tvoji, zachovávejž je pravicí svou, a vyslyš mne.'),
(1562007,54,19,108,8,'Bůh mluvil skrze svatost svou; veseliti se budu, že budu děliti Sichem, a údolí Sochot že rozměřím.'),
(1562008,54,19,108,9,'Můjť jest Galád, můj i Manasses, a Efraim síla hlavy mé, Juda učitel můj.'),
(1562009,54,19,108,10,'Moáb medenice k umývání mému, na Edoma uvrhu obuv svou, proti Palestině troubiti budu.'),
(1562010,54,19,108,11,'Kdo mne uvede do města hrazeného? Kdo mne zprovodí až do Idumejské země?'),
(1562011,54,19,108,12,'Zdali ne ty, ó Bože, kterýž jsi nás byl zavrhl, a nevycházels, ó Bože, s vojsky našimi?'),
(1562012,54,19,108,13,'Uděliž nám pomoci proti nepříteli, nebo marná jest pomoc lidská.'),
(1562013,54,19,108,14,'V Bohu udatně sobě počínati budeme, a on pošlapá nepřátely naše.'),
(1562014,54,19,109,1,'Přednímu zpěváku, žalm Davidův. Ó Bože chvály mé, nečiň se neslyše.'),
(1562015,54,19,109,2,'Nebo ústa nešlechetného a ústa lstivá proti mně se otevřela, mluvili proti mně jazykem lživým.'),
(1562016,54,19,109,3,'A slovy jizlivými osočili mne, válčí proti mně beze vší příčiny.'),
(1562017,54,19,109,4,'Protivili mi se za mé milování, ješto jsem se za ně modlíval.'),
(1562018,54,19,109,5,'Odplacují se mi zlým za dobré, a nenávistí za milování mé.'),
(1562019,54,19,109,6,'Postav nad ním bezbožníka, a protivník ať mu stojí po pravici.'),
(1562020,54,19,109,7,'Když před soudem stane, ať zůstane za nešlechetného, a prosba jeho budiž jemu k hříchu.'),
(1562021,54,19,109,8,'Budiž dnů jeho málo, a úřad jeho vezmi jiný.'),
(1562022,54,19,109,9,'Buďtež děti jeho sirotci, a žena jeho vdovou.'),
(1562023,54,19,109,10,'Buďtež běhouni a tuláci synové jeho, žebřete, vyhnáni jsouce z poustek svých.'),
(1562024,54,19,109,11,'Přitáhni k sobě lichevník všecko, cožkoli má, a úsilé jeho rozchvátejte cizí.'),
(1562025,54,19,109,12,'Nebudiž, kdo by mu chtěl milosrdenství prokázati, aniž buď, kdo by se smiloval nad sirotky jeho.'),
(1562026,54,19,109,13,'Potomci jeho z kořen vyťati buďte, v druhém kolenu vyhlazeno buď jméno jejich.'),
(1562027,54,19,109,14,'Přijdiž na pamět nepravost předků jeho před Hospodinem, a hřích matky jeho nebuď shlazen.'),
(1562028,54,19,109,15,'Buďtež před Hospodinem ustavičně, až by vyhladil z země památku jejich,'),
(1562029,54,19,109,16,'Proto že nepamatoval, aby činil milosrdenství, ale protivenství činil člověku chudému a nuznému a sevřenému bolestí srdce, aby jej zamordoval.'),
(1562030,54,19,109,17,'Poněvadž miloval zlořečení, nechať přijde na něj; neměl líbosti v požehnání, nechať se vzdálí od něho.'),
(1562031,54,19,109,18,'A tak budiž oblečen v zlořečenství jako v svůj oděv, a ať vejde do vnitřností jeho jako voda, a jako olej do kostí jeho.'),
(1562032,54,19,109,19,'Budiž jemu to jako plášť k přiodívání, a jako pás k ustavičnému opasování.'),
(1562033,54,19,109,20,'Taková mzda přijdiž mým protivníkům od Hospodina, a mluvícím zlé věci proti duši mé.'),
(1562034,54,19,109,21,'Ty pak, Hospodine Pane, nalož se mnou laskavě pro jméno své, nebo dobré jest milosrdenství tvé; vytrhni mne.'),
(1562035,54,19,109,22,'Jsemť zajisté chudý a nuzný, a srdce mé raněno jest u vnitřnostech mých.'),
(1562036,54,19,109,23,'Jako stín, když se nachyluje, ucházeti musím; honí se za mnou jako za kobylkou.'),
(1562037,54,19,109,24,'Kolena má klesají postem, a tělo mé vyschlo z tučnosti.'),
(1562038,54,19,109,25,'Nadto jsem jim za posměch; když mne uhlédají, potřásají hlavami svými.'),
(1562039,54,19,109,26,'Spomoz mi, ó Hospodine Bože můj, zachovej mne podlé milosrdenství svého,'),
(1562040,54,19,109,27,'Tak aby poznati mohli, že jest to ruka tvá, a že jsi ty, Hospodine, učinil to.'),
(1562041,54,19,109,28,'Nechť oni jakkoli zlořečí, ty dobrořeč; kteříž povstali, nechť se zastydí, aby se veselil služebník tvůj.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562042,54,19,109,29,'Buďtež oblečeni protivníci moji v zahanbení, a nechť se odějí jako pláštěm hanbou svou.'),
(1562043,54,19,109,30,'Slaviti budu Hospodina velice ústy svými, a u prostřed mnohých chváliti jej budu,'),
(1562044,54,19,109,31,'Proto že stojí po pravici nuznému, aby ho zachoval od těch, kteříž odsuzují život jeho.'),
(1562045,54,19,110,1,'Davidův žalm. Řekl Hospodin Pánu mému: Seď na pravici mé, dokudž nepoložím nepřátel tvých za podnože noh tvých.'),
(1562046,54,19,110,2,'Berlu moci tvé vyšle Hospodin z Siona, řka: Panuj u prostřed nepřátel svých.'),
(1562047,54,19,110,3,'Lid tvůj dobrovolný v den boje tvého v ozdobě svatosti, z života hned v svitání jako rosa plod tvůj bude.'),
(1562048,54,19,110,4,'Přisáhl Hospodin, a nebude želeti toho, řka: Ty jsi kněz na věky podlé řádu Melchisedechova.'),
(1562049,54,19,110,5,'Pán po pravici tvé potře v den hněvu svého krále.'),
(1562050,54,19,110,6,'Soud činiti bude mezi národy, porážku hroznou učiní, potře i hlavu panující nad mnohými krajinami.'),
(1562051,54,19,110,7,'Z potoka na cestě píti bude, a protož povýší hlavy.'),
(1562052,54,19,111,1,'Halelujah. Slaviti budu Hospodina z celého srdce, v radě přímých i v shromáždění;'),
(1562053,54,19,111,2,'Veliké skutky Hospodinovy, a patrné všechněm, kteříž v nich líbost mají;'),
(1562054,54,19,111,3,'Slavné a překrásné dílo jeho, a spravedlnost jeho zůstávající na věky.'),
(1562055,54,19,111,4,'Památku způsobil předivnými skutky svými milostivý a milosrdný Hospodin.'),
(1562056,54,19,111,5,'Pokrm dal těm, kteříž se ho bojí, pamětliv jsa věčně na smlouvu svou.'),
(1562057,54,19,111,6,'Mocné skutky své oznámil lidu svému, dav jim dědictví pohanů.'),
(1562058,54,19,111,7,'Skutkové rukou jeho pravda a soud, a nepohnutelní všickni rozkazové jeho.'),
(1562059,54,19,111,8,'Upevnění na věčnou věčnost; učiněni jsou v pravdě a v pravosti.'),
(1562060,54,19,111,9,'Vykoupení poslav lidu svému, přikázal na věky smlouvu svou; svaté a hrozné jest jméno jeho.'),
(1562061,54,19,111,10,'Počátek moudrosti jest bázeň Hospodina; rozumu výborného nabývají všickni, kteříž činí ty věci; chvála jeho zůstává na věky.'),
(1562062,54,19,112,1,'Halelujah. Blahoslavený muž, kterýž se bojí Hospodina, a v přikázaních jeho má velikou líbost.'),
(1562063,54,19,112,2,'Mocné na zemi bude símě jeho, rodina upřímých požehnání dojde.'),
(1562064,54,19,112,3,'Zboží a bohatství v domě jeho, a spravedlnost jeho zůstává na věky.'),
(1562065,54,19,112,4,'Vzchází ve tmách světlo upřímým, milostivý jest, milosrdný a spravedlivý.'),
(1562066,54,19,112,5,'Dobrý člověk slitovává se i půjčuje, a řídí své věci s soudem.'),
(1562067,54,19,112,6,'Nebo nepohne se na věky, v paměti věčné bude spravedlivý.'),
(1562068,54,19,112,7,'Slyše zlé noviny, nebojí se; stálé jest srdce jeho, a doufá v Hospodina.'),
(1562069,54,19,112,8,'Utvrzené srdce jeho nebojí se, až i uzří pomstu na svých nepřátelích.'),
(1562070,54,19,112,9,'Rozděluje štědře, a dává nuzným; spravedlnost jeho zůstává na věky, roh jeho bude vyvýšen v slávě.'),
(1562071,54,19,112,10,'Bezbožný vida to, zlobiti se, zuby svými škřipěti a schnouti bude; žádost bezbožníků zahyne.'),
(1562072,54,19,113,1,'Halelujah. Chvalte služebníci Hospodinovi, chvalte jméno Hospodinovo.'),
(1562073,54,19,113,2,'Budiž jméno Hospodinovo požehnáno od tohoto času až na věky.'),
(1562074,54,19,113,3,'Od východu slunce až do západu jeho chváleno buď jméno Hospodinovo.'),
(1562075,54,19,113,4,'Vyvýšenť jest nade všecky národy Hospodin, a nad nebesa sláva jeho.'),
(1562076,54,19,113,5,'Kdo jest rovný Hospodinu Bohu našemu, kterýž vysoko bydlí?'),
(1562077,54,19,113,6,'Kterýž snižuje se, aby všecko spatřoval, což jest na nebi i na zemi.'),
(1562078,54,19,113,7,'Vyzdvihuje z prachu nuzného, a z hnoje vyvyšuje chudého,'),
(1562079,54,19,113,8,'Aby jej posadil s knížaty, s knížaty lidu svého.'),
(1562080,54,19,113,9,'Kterýž vzdělává neplodnou v čeled, a matku veselící se z dítek. Halelujah.'),
(1562081,54,19,114,1,'Když vycházel Izrael z Egypta, a rodina Jákobova z národu jazyka cizího,'),
(1562082,54,19,114,2,'Byl Juda posvěcením jeho, Izrael panováním jeho.'),
(1562083,54,19,114,3,'To když vidělo moře, uteklo, Jordán nazpět se obrátil.'),
(1562084,54,19,114,4,'Hory poskakovaly jako skopci, pahrbkové jako jehňata.'),
(1562085,54,19,114,5,'Coť bylo, ó moře, že jsi utíkalo? Jordáne, že jsi nazpět se obrátil?'),
(1562086,54,19,114,6,'Ó hory, že jste poskakovaly jako skopci, pahrbkové jako jehňata?'),
(1562087,54,19,114,7,'Pro přítomnost Panovníka třásla jsem se já země, pro přítomnost Boha Jákobova,'),
(1562088,54,19,114,8,'Kterýž obrací i tu skálu v jezero vod, a škřemen v studnici vod.'),
(1562089,54,19,115,1,'Ne nám, Hospodine, ne nám, ale jménu svému dej čest, pro milosrdenství své a pro pravdu svou.'),
(1562090,54,19,115,2,'Proč mají říkati pohané: Kdež jest nyní Bůh jejich?'),
(1562091,54,19,115,3,'Ješto Bůh náš jest na nebi, čině všecko, což se mu líbí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562092,54,19,115,4,'Modly pak jejich jsou stříbro a zlato, dílo rukou lidských.'),
(1562093,54,19,115,5,'Ústa mají, a nemluví, oči mají, a nevidí.'),
(1562094,54,19,115,6,'Uši mají, a neslyší, nos mají, a nečijí.'),
(1562095,54,19,115,7,'Ruce mají, a nemakají, nohy mají, a nechodí, aniž volati mohou hrdlem svým.'),
(1562096,54,19,115,8,'Nechať jsou jim podobni, kteříž je dělají, a kdožkoli v nich doufají.'),
(1562097,54,19,115,9,'Izraeli, doufej v Hospodina, nebo spomocníkem a štítem takových on jest.'),
(1562098,54,19,115,10,'Dome Aronův, doufej v Hospodina, spomocníkem a štítem takových on jest.'),
(1562099,54,19,115,11,'Kteříž se bojíte Hospodina, doufejte v Hospodina, spomocníkem a štítem takových on jest.'),
(1562100,54,19,115,12,'Hospodin rozpomena se na nás, požehná; požehná domu Izraelovu, požehná i domu Aronovu.'),
(1562101,54,19,115,13,'Požehná bojícím se Hospodina, malým, i velikým.'),
(1562102,54,19,115,14,'Rozmnoží Hospodin vás, vás i syny vaše.'),
(1562103,54,19,115,15,'Požehnaní vy od Hospodina, kterýž učinil nebesa i zemi.'),
(1562104,54,19,115,16,'Nebesa jsou nebesa Hospodinova, zemi pak dal synům lidským.'),
(1562105,54,19,115,17,'Ne mrtví chváliti budou Hospodina, ani kdo ze všech těch, kteříž sstupují do místa mlčení,'),
(1562106,54,19,115,18,'Ale my dobrořečiti budeme Hospodinu od tohoto času až na věky. Halelujah.'),
(1562107,54,19,116,1,'Miluji Hospodina, proto že vyslýchá hlas můj a pokorné modlitby mé.'),
(1562108,54,19,116,2,'Nebo naklonil ucha svého ke mně, když jsem ho vzýval ve dnech svých.'),
(1562109,54,19,116,3,'Obklíčilyť mne byly bolesti smrti, a úzkosti hrobu potkaly mne; sevření a truchlost přišla na mne.'),
(1562110,54,19,116,4,'I vzýval jsem jméno Hospodinovo, řka: Prosím, ó Hospodine, vysvoboď duši mou.'),
(1562111,54,19,116,5,'Milostivý Hospodin a spravedlivý, Bůh náš lítostivý.'),
(1562112,54,19,116,6,'Ostříhá sprostných Hospodin; znuzen jsem byl, a spomohl mi.'),
(1562113,54,19,116,7,'Navratiž se, duše má, do odpočinutí svého, poněvadž Hospodin jest dobrodince tvůj.'),
(1562114,54,19,116,8,'Nebo jsi vytrhl duši mou od smrti, oči mé od slz, nohu mou od poklesnutí.'),
(1562115,54,19,116,9,'Ustavičně choditi budu před Hospodinem v zemi živých.'),
(1562116,54,19,116,10,'Uvěřil jsem, protož i mluvil jsem, ačkoli jsem byl velmi ztrápený.'),
(1562117,54,19,116,11,'Já jsem byl řekl v pospíchání: Všeliký člověk jest lhář.'),
(1562118,54,19,116,12,'Čím se odplatím Hospodinu za všecka dobrodiní jeho mně učiněná?'),
(1562119,54,19,116,13,'Kalich mnohého spasení vezmu, a jméno Hospodinovo vzývati budu.'),
(1562120,54,19,116,14,'Sliby své Hospodinu splním, teď přede vším lidem jeho.'),
(1562121,54,19,116,15,'Drahá jest před očima Hospodinovýma smrt svatých jeho.'),
(1562122,54,19,116,16,'Ó Hospodine, že jsem služebník tvůj, služebník, pravím, tvůj, syn děvky tvé, rozvázal jsi svazky mé.'),
(1562123,54,19,116,17,'Tobě obětovati budu obět díků činění, a jméno Hospodinovo vzývati budu.'),
(1562124,54,19,116,18,'Sliby své Hospodinu splním, teď přede vším lidem jeho,'),
(1562125,54,19,116,19,'V síňcích domu Hospodinova, u prostřed tebe, Jeruzaléme. Halelujah.'),
(1562126,54,19,117,1,'Chvalte Hospodina všickni národové, velebtež ho všickni lidé.'),
(1562127,54,19,117,2,'Neboť jest rozšířeno nad námi milosrdenství jeho, a pravda Hospodinova na věky. Halelujah.'),
(1562128,54,19,118,1,'Oslavujte Hospodina, nebo jest dobrý, nebo na věky trvá milosrdenství jeho.'),
(1562129,54,19,118,2,'Rciž nyní, Izraeli, že na věky milosrdenství jeho.'),
(1562130,54,19,118,3,'Rciž nyní, dome Aronův, že na věky milosrdenství jeho.'),
(1562131,54,19,118,4,'Rcetež nyní bojící se Hospodina, že na věky milosrdenství jeho.'),
(1562132,54,19,118,5,'V úzkosti vzýval jsem Hospodina, a vyslyšev, uprostrannil mi Hospodin.'),
(1562133,54,19,118,6,'Hospodin se mnou, nebudu se báti. Co mi může učiniti člověk?'),
(1562134,54,19,118,7,'Hospodin se mnou jest mezi pomocníky mými, pročež já podívám se těm, kteříž mne mají v nenávisti.'),
(1562135,54,19,118,8,'Lépe jest doufati v Hospodina, než naději skládati v člověku.'),
(1562136,54,19,118,9,'Lépe jest doufati v Hospodina, nežli naději skládati v knížatech.'),
(1562137,54,19,118,10,'Všickni národové obklíčili mne, ale ve jménu Hospodinovu vyplénil jsem je.'),
(1562138,54,19,118,11,'Mnohokrát obklíčili mne, ale ve jménu Hospodinovu vyplénil jsem je.'),
(1562139,54,19,118,12,'Ssuli se na mne jako včely, však zhasli jako oheň z trní: nebo ve jménu Hospodinovu vyplénil jsem je.'),
(1562140,54,19,118,13,'Velmi jsi ztuha na mne dotíral, abych padl, ale Hospodin spomohl mi.'),
(1562141,54,19,118,14,'Síla má a písnička má jest Hospodin, on byl můj vysvoboditel.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562142,54,19,118,15,'Hlas prokřikování a spasení v staních spravedlivých. Pravice Hospodinova dokázala síly,'),
(1562143,54,19,118,16,'Pravice Hospodinova vyvýšila se, pravice Hospodinova dokázala síly.'),
(1562144,54,19,118,17,'Neumruť, ale živ budu, abych vypravoval skutky Hospodinovy.'),
(1562145,54,19,118,18,'Trestaltě mne přísně Hospodin, ale smrti mne nevydal.'),
(1562146,54,19,118,19,'Otevřetež mi brány spravedlnosti,a vejda do nich, oslavovati budu Hospodina.'),
(1562147,54,19,118,20,'Tať jest brána Hospodinova, kterouž spravedliví vcházejí.'),
(1562148,54,19,118,21,'Tuť já tě oslavovati budu, nebo jsi mne vyslyšel, a byls můj vysvoboditel.'),
(1562149,54,19,118,22,'Kámen, kterýž zavrhli stavitelé, učiněn jest v hlavu úhelní.'),
(1562150,54,19,118,23,'Od Hospodina stalo se to, a jest divné před očima našima.'),
(1562151,54,19,118,24,'Tentoť jest den, kterýž učinil Hospodin, a protož radujme se a veselme se v něm.'),
(1562152,54,19,118,25,'Prosím, Hospodine, zachovávejž již; prosím, Hospodine, dávej již šťastný prospěch.'),
(1562153,54,19,118,26,'Požehnaný, jenž se béře ve jménu Hospodinovu; dobrořečíme vám z domu Hospodinova.'),
(1562154,54,19,118,27,'Bůh silný Hospodin, onť se zasvítil nám, važte beránky až k rohům oltáře.'),
(1562155,54,19,118,28,'Bůh silný můj ty jsi, protož slaviti tě budu, Bože můj, vyvyšovati tě budu.'),
(1562156,54,19,118,29,'Oslavujtež Hospodina, neboť jest dobrý, nebo na věky milosrdenství jeho.'),
(1562157,54,19,119,1,'Aleph. Blahoslavení ti, kteříž jsou ctného obcování, kteříž chodí v zákoně Hospodinově.'),
(1562158,54,19,119,2,'Blahoslavení, kteříž ostříhají svědectví jeho, a kteříž ho celým srdcem hledají.'),
(1562159,54,19,119,3,'Nečiní zajisté nepravosti, ale kráčejí po cestách jeho.'),
(1562160,54,19,119,4,'Ty jsi přikázal, aby pilně bylo ostříháno rozkazů tvých.'),
(1562161,54,19,119,5,'Ó by spraveny byly cesty mé k ostříhání ustanovení tvých.'),
(1562162,54,19,119,6,'Tehdážť nebudu zahanben, když budu patřiti na všecka přikázaní tvá.'),
(1562163,54,19,119,7,'Oslavovati tě budu v upřímnosti srdce, když se vyučovati budu právům spravedlnosti tvé.'),
(1562164,54,19,119,8,'Ustanovení tvých budu ostříhati s pilností, toliko neopouštěj mne.'),
(1562165,54,19,119,9,'Beth. Jakým způsobem očistí mládenec stezku svou? Takovým, aby se choval vedlé slova tvého.'),
(1562166,54,19,119,10,'Celým srdcem svým hledám tebe, nedopouštějž mi blouditi od přikázaní tvých.'),
(1562167,54,19,119,11,'V srdci svém skládám řeč tvou, abych nehřešil proti tobě.'),
(1562168,54,19,119,12,'Ty chvály hodný Hospodine, vyuč mne ustanovením svým.'),
(1562169,54,19,119,13,'Rty svými vypravuji o všech soudech úst tvých.'),
(1562170,54,19,119,14,'Z cesty svědectví tvých raduji se více, než z největšího zboží.'),
(1562171,54,19,119,15,'O přikázaních tvých přemyšluji, a patřím na stezky tvé.'),
(1562172,54,19,119,16,'V ustanoveních tvých se kochám, aniž se zapomínám na slovo tvé.'),
(1562173,54,19,119,17,'Gimel Tu milost učiň s služebníkem svým, abych, dokudž jsem živ, ostříhal slova tvého.'),
(1562174,54,19,119,18,'Otevři oči mé, abych spatřoval divné věci z zákona tvého.'),
(1562175,54,19,119,19,'Příchozí jsem na tom světě, neukrývejž přede mnou přikázaní svých.'),
(1562176,54,19,119,20,'Umdlévá duše má pro žádost soudů tvých všelikého času.'),
(1562177,54,19,119,21,'Vyhlazuješ pyšné, zlořečené, kteříž bloudí od přikázaní tvých.'),
(1562178,54,19,119,22,'Odejmi ode mne útržku a potupu, neboť ostříhám svědectví tvých.'),
(1562179,54,19,119,23,'Také i knížata se zasazují, a mluví proti mně, služebník pak tvůj přemýšlí o ustanoveních tvých.'),
(1562180,54,19,119,24,'Svědectví tvá zajisté jsou mé rozkoše a moji rádcové.'),
(1562181,54,19,119,25,'Daleth Přilnula k prachu duše má; obživiž mne podlé slova svého.'),
(1562182,54,19,119,26,'Cesty své předložilť jsem, a vyslýchals mne; vyuč mne ustanovením svým.'),
(1562183,54,19,119,27,'Cestě rozkazů tvých dej ať vyrozumívám, a ať přemýšlím o divných skutcích tvých.'),
(1562184,54,19,119,28,'Rozplývá se zámutkem duše má, očerstviž mne podlé slova svého.'),
(1562185,54,19,119,29,'Cestu lživou odvrať ode mne, a zákon svůj z milosti dej mi.'),
(1562186,54,19,119,30,'Cestu pravou jsem vyvolil, soudy tvé sobě předkládám.'),
(1562187,54,19,119,31,'Svědectví tvých se přídržím, Hospodine, nedejž mi zahanbenu býti.'),
(1562188,54,19,119,32,'Cestou rozkazů tvých poběhnu, když ty rozšíříš srdce mé.'),
(1562189,54,19,119,33,'He Vyuč mne, Hospodine, cestě ustanovení svých, kteréž bych ostříhal do konce.'),
(1562190,54,19,119,34,'Dej mi ten rozum, ať šetřím zákona tvého, a ať ho ostříhám celým srdcem.'),
(1562191,54,19,119,35,'Dej, ať chodím cestou přikázaní tvých; nebo v tom svou rozkoš skládám.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562192,54,19,119,36,'Nakloň srdce mého k svědectvím svým, a ne k lakomství.'),
(1562193,54,19,119,37,'Odvrať oči mé, ať nehledí marnosti; na cestě své obživ mne.'),
(1562194,54,19,119,38,'Potvrď služebníku svému řeči své, kterýž se oddal k službě tvé.'),
(1562195,54,19,119,39,'Odvrať ode mne pohanění, jehož se bojím; nebo soudové tvoji dobří jsou.'),
(1562196,54,19,119,40,'Aj, toužím po rozkázaních tvých; dej, ať jsem živ v spravedlnosti tvé.'),
(1562197,54,19,119,41,'Vav Ó ať se přiblíží ke mně milosrdenství tvá, Hospodine, a spasení tvé vedlé řeči tvé,'),
(1562198,54,19,119,42,'Tak abych odpovědíti uměl utrhači svému skutkem, že doufání skládám v slovu tvém.'),
(1562199,54,19,119,43,'A nevynímej z úst mých slova nejpravějšího; neboť na soudy tvé očekávám.'),
(1562200,54,19,119,44,'I budu ostříhati zákona tvého ustavičně, od věků až na věky,'),
(1562201,54,19,119,45,'A bez přestání choditi na širokosti, neboť jsem se dotázal rozkazů tvých.'),
(1562202,54,19,119,46,'Nýbrž mluviti budu o svědectvích tvých i před králi, a nebudu se hanbiti.'),
(1562203,54,19,119,47,'Nebo rozkoš svou skládám v přikázaních tvých, kteráž jsem zamiloval.'),
(1562204,54,19,119,48,'Přičinímť i ruce své k přikázaním tvým, kteráž miluji, a přemýšleti budu o ustanoveních tvých.'),
(1562205,54,19,119,49,'Zajin Rozpomeň se na slovo k služebníku svému, kterýmž jsi mne ubezpečil.'),
(1562206,54,19,119,50,'Toť jest má útěcha v ssoužení mém, že mne slovo tvé obživuje.'),
(1562207,54,19,119,51,'Pyšní mi se velmi posmívají, však od zákona tvého se neuchyluji.'),
(1562208,54,19,119,52,'Neboť se rozpomínám na soudy tvé věčné, Hospodine, kterýmiž se potěšuji.'),
(1562209,54,19,119,53,'Děsím se nad bezbožnými, kteříž opouštějí zákon tvůj.'),
(1562210,54,19,119,54,'Ustanovení tvá jsou mé písničky na místě mého putování.'),
(1562211,54,19,119,55,'Rozpomínám se i v noci na jméno tvé, Hospodine, a ostříhám zákona tvého.'),
(1562212,54,19,119,56,'Toť mám odtud, abych ostříhal rozkazů tvých.'),
(1562213,54,19,119,57,'Cheth Díl můj, řekl jsem, Hospodine, ostříhati výmluvnosti tvé.'),
(1562214,54,19,119,58,'Modlívám se milosti tvé v celém srdci: Smiluj se nade mnou podlé slova svého.'),
(1562215,54,19,119,59,'Rozvážil jsem na mysli cesty své, a obrátil jsem nohy své k tvým svědectvím.'),
(1562216,54,19,119,60,'Pospíchámť a neodkládám ostříhati rozkazů tvých.'),
(1562217,54,19,119,61,'Rota bezbožníků zloupila mne, na zákon tvůj se nezapomínám.'),
(1562218,54,19,119,62,'O půlnoci vstávám, abych tě oslavoval v soudech spravedlnosti tvé.'),
(1562219,54,19,119,63,'Účastník jsem všech, kteříž se bojí tebe, a těch, kteříž ostříhají přikázaní tvých.'),
(1562220,54,19,119,64,'Milosrdenství tvého, Hospodine, plná jest země, ustanovením svým vyuč mne.'),
(1562221,54,19,119,65,'Teth Dobrotivě jsi nakládal s služebníkem svým, Hospodine, podlé slova svého.'),
(1562222,54,19,119,66,'Pravému soudu a umění vyuč mne, nebo jsem přikázaním tvým uvěřil.'),
(1562223,54,19,119,67,'Prvé než jsem snížen byl, bloudil jsem, ale nyní výmluvnosti tvé ostříhám.'),
(1562224,54,19,119,68,'Dobrý jsi ty a dobrotivý, vyuč mne ustanovením svým.'),
(1562225,54,19,119,69,'Složiliť jsou lež proti mně pyšní, ale já celým srdcem ostříhám přikázaní tvých.'),
(1562226,54,19,119,70,'Zbřidlo jako tuk srdce jejich, já zákonem tvým se potěšuji.'),
(1562227,54,19,119,71,'K dobrémuť jest mi to, že jsem pobyl v trápení, abych se naučil ustanovením tvým.'),
(1562228,54,19,119,72,'Za lepší sobě pokládám zákon úst tvých, nežli na tisíce zlata a stříbra.'),
(1562229,54,19,119,73,'Jod Ruce tvé učinily a sformovaly mne, dej mi ten rozum, abych se naučil přikázaním tvým,'),
(1562230,54,19,119,74,'Tak aby bojící se tebe mne vidouce, radovali se, že na slovo tvé očekávám.'),
(1562231,54,19,119,75,'Seznávámť, Hospodine, že jsou spravedliví soudové tvoji, a že jsi mne hodně potrestal.'),
(1562232,54,19,119,76,'Nechať jest již zřejmé milosrdenství tvé ku potěšení mému, podlé řeči tvé mluvené služebníku tvému.'),
(1562233,54,19,119,77,'Přiďtež na mne slitování tvá, abych živ býti mohl; nebo zákon tvůj rozkoš má jest.'),
(1562234,54,19,119,78,'Zahanbeni buďte pyšní, proto že lstivě chtěli mne podvrátiti, já pak přemyšluji o přikázaních tvých.'),
(1562235,54,19,119,79,'Obraťtež se ke mně, kteříž se bojí tebe, a kteříž znají svědectví tvá.'),
(1562236,54,19,119,80,'Budiž srdce mé upřímé při ustanoveních tvých, tak abych nebyl zahanben.'),
(1562237,54,19,119,81,'Kaph Touží duše má po spasení tvém, na slovo tvé očekávám.'),
(1562238,54,19,119,82,'Hynou i oči mé žádostí výmluvností tvých, když říkám: Skoro-liž mne potěšíš?'),
(1562239,54,19,119,83,'Ačkoli jsem jako nádoba kožená v dymu, na ustanovení tvá však jsem nezapomenul.'),
(1562240,54,19,119,84,'Mnoho-liž bude dní služebníka tvého? Skoro-liž soud vykonáš nad těmi, kteříž mi protivenství činí?'),
(1562241,54,19,119,85,'Vykopali mi pyšní jámy, kterážto věc není podlé zákona tvého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562242,54,19,119,86,'Všecka přikázaní tvá jsou pravda; bez příčiny mi se protiví, spomoziž mi.'),
(1562243,54,19,119,87,'Téměřť jsou mne již v nic obrátili na zemi, já jsem však neopustil přikázaní tvých.'),
(1562244,54,19,119,88,'Podlé milosrdenství svého obživ mne, abych ostříhal svědectví úst tvých.'),
(1562245,54,19,119,89,'Lamed Na věky, ó Hospodine, slovo tvé trvánlivé jest v nebesích.'),
(1562246,54,19,119,90,'Od národu do pronárodu pravda tvá, utvrdil jsi zemi, a tak stojí.'),
(1562247,54,19,119,91,'Vedlé úsudků tvých stojí to vše do dnešního dne, všecko to zajisté jsou služebníci tvoji.'),
(1562248,54,19,119,92,'Byť zákon tvůj nebyl mé potěšení, dávno bych byl zahynul v svém trápení.'),
(1562249,54,19,119,93,'Na věky se nezapomenu na rozkazy tvé; jimi zajisté obživil jsi mne.'),
(1562250,54,19,119,94,'Tvůjť jsem já, zachovávejž mne; nebo přikázaní tvá zpytuji.'),
(1562251,54,19,119,95,'Očekávajíť na mne bezbožní, aby mne zahubili, já pak svědectví tvá rozvažuji.'),
(1562252,54,19,119,96,'Každé věci dokonalé vidím skončení; rozkaz tvůj jest přeširoký náramně.'),
(1562253,54,19,119,97,'Mem Ó jak miluji zákon tvůj, tak že každého dne on jest mé přemyšlování.'),
(1562254,54,19,119,98,'Nad nepřátely mé moudřejšího mne činíš přikázaními svými; nebo mám je ustavičně před sebou.'),
(1562255,54,19,119,99,'Nade všecky své učitele rozumnější jsem učiněn; nebo svědectví tvá jsou má přemyšlování.'),
(1562256,54,19,119,100,'I nad starce opatrnější jsem, nebo přikázaní tvých ostříhám.'),
(1562257,54,19,119,101,'Od každé cesty zlé zdržuji nohy své, abych ostříhal slova tvého.'),
(1562258,54,19,119,102,'Od soudů tvých se neodvracuji, proto že ty mne vyučuješ.'),
(1562259,54,19,119,103,'Ó jak jsou sladké dásním mým výmluvnosti tvé, nad med ústům mým.'),
(1562260,54,19,119,104,'Z přikázaní tvých rozumnosti jsem nabyl, a protož všeliké cesty bludné nenávidím.'),
(1562261,54,19,119,105,'Nun Svíce nohám mým jest slovo tvé, a světlo stezce mé.'),
(1562262,54,19,119,106,'Přisáhl jsem, což i splním, že chci ostříhati soudů spravedlnosti tvé.'),
(1562263,54,19,119,107,'Ztrápenýť jsem přenáramně, Hospodine, obživiž mne vedlé slova svého.'),
(1562264,54,19,119,108,'Dobrovolné oběti úst mých, žádám, oblib, Hospodine, a právům svým vyuč mne.'),
(1562265,54,19,119,109,'Duše má jest v ustavičném nebezpečenství, a však na zákon tvůj se nezapomínám.'),
(1562266,54,19,119,110,'Polékli jsou mi bezbožní osídlo, ale já od rozkazů tvých se neodvracím.'),
(1562267,54,19,119,111,'Za dědictví věčné ujal jsem svědectví tvá, neboť jsou radost srdce mého.'),
(1562268,54,19,119,112,'Naklonil jsem srdce svého k vykonávání ustanovení tvých ustavičně, až i do konce.'),
(1562269,54,19,119,113,'Samech Výmyslků nenávidím, zákon pak tvůj miluji.'),
(1562270,54,19,119,114,'Skrýše má a pavéza má ty jsi, na slovo tvé očekávám.'),
(1562271,54,19,119,115,'Odstuptež ode mne nešlechetníci, abych ostříhal přikázaní Boha svého.'),
(1562272,54,19,119,116,'Zdržujž mne podlé slova svého, tak abych živ byl, a nezahanbuj mne v mém očekávání.'),
(1562273,54,19,119,117,'Posiluj mne, abych zachován byl, a patřil k ustanovením tvým ustavičně.'),
(1562274,54,19,119,118,'Potlačuješ všecky ty, kteříž odstupují od ustanovení tvých; neboť jest lživá opatrnost jejich.'),
(1562275,54,19,119,119,'Jako trůsku odmítáš všecky bezbožníky země, a protož miluji svědectví tvá.'),
(1562276,54,19,119,120,'Děsí se strachem před tebou tělo mé; nebo soudů tvých bojím se.'),
(1562277,54,19,119,121,'Ajin Činím soud a spravedlnost, nevydávejž mne mým násilníkům.'),
(1562278,54,19,119,122,'Zastup sám služebníka svého k dobrému, tak aby mne pyšní nepotlačili.'),
(1562279,54,19,119,123,'Oči mé hynou čekáním na spasení tvé, a na výmluvnost spravedlnosti tvé.'),
(1562280,54,19,119,124,'Nalož s služebníkem svým vedlé milosrdenství svého, a ustanovením svým vyuč mne.'),
(1562281,54,19,119,125,'Služebník tvůj jsem já, dejž mi rozumnost, abych uměl svědectví tvá.'),
(1562282,54,19,119,126,'Časť jest, abys se přičinil, Hospodine; zrušili zákon tvůj.'),
(1562283,54,19,119,127,'Z té příčiny miluji přikázaní tvá více nežli zlato, i to, kteréž jest nejlepší.'),
(1562284,54,19,119,128,'A proto, že všecky rozkazy tvé o všech věcech pravé býti poznávám, všeliké stezky bludné nenávidím.'),
(1562285,54,19,119,129,'Pe Předivnáť jsou svědectví tvá, a protož jich ostříhá duše má.'),
(1562286,54,19,119,130,'Začátek učení tvého osvěcuje, a vyučuje sprostné rozumnosti.'),
(1562287,54,19,119,131,'Ústa svá otvírám, a dychtím, nebo přikázaní tvých jsem žádostiv.'),
(1562288,54,19,119,132,'Popatřiž na mne, a smiluj se nade mnou podlé práva těch, kteříž milují jméno tvé.'),
(1562289,54,19,119,133,'Kroky mé utvrzuj v slovu svém, a nedej, aby nade mnou panovati měla jaká nepravost.'),
(1562290,54,19,119,134,'Vysvoboď mne z nátisků lidských, abych ostříhal rozkazů tvých.'),
(1562291,54,19,119,135,'Zasvěť tvář svou nad služebníkem svým, a ustanovením svým vyuč mne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562292,54,19,119,136,'Potůčkové vod vyplývají z očí mých příčinou těch, kteříž neostříhají zákona tvého.'),
(1562293,54,19,119,137,'Tsade Spravedlivý jsi, Hospodine, a upřímý v soudech svých.'),
(1562294,54,19,119,138,'Ty jsi vydal spravedlivá svědectví svá, a vší víry hodná.'),
(1562295,54,19,119,139,'Až svadnu, tak horlím, že se zapomínají na slovo tvé nepřátelé moji.'),
(1562296,54,19,119,140,'Zprubovanáť jest řeč tvá dokonale, tou příčinou ji miluje služebník tvůj.'),
(1562297,54,19,119,141,'Maličký a opvržený jsem já, však na rozkazy tvé se nezapomínám.'),
(1562298,54,19,119,142,'Spravedlnost tvá jest spravedlnost věčná, a zákon tvůj pravda.'),
(1562299,54,19,119,143,'Ssoužení a nátisk mne stihají, přikázaní tvá jsou mé rozkoše.'),
(1562300,54,19,119,144,'Spravedlnost svědectví tvých trvá na věky; dej mi z ní rozumnosti nabýti, tak abych živ býti mohl.'),
(1562301,54,19,119,145,'Koph Z celého srdce volám, vyslyšiš mne, ó Hospodine, abych ostříhal ustanovení tvých.'),
(1562302,54,19,119,146,'K tobě volám, vysvoboď mne, abych šetřil svědectví tvých.'),
(1562303,54,19,119,147,'Předstihám svitání a volám, na tvéť slovo očekávám.'),
(1562304,54,19,119,148,'Předstihají oči mé bdění proto, abych přemýšlel o výmluvnostech tvých.'),
(1562305,54,19,119,149,'Hlas můj slyš podlé svého milosrdenství, Hospodine, podlé soudů svých obživ mne.'),
(1562306,54,19,119,150,'Přibližují se následovníci nešlechetnosti, ti, kteříž se od zákona tvého vzdálili.'),
(1562307,54,19,119,151,'Ty blíže jsi, Hospodine; nebo všecka přikázaní tvá jsou pravda.'),
(1562308,54,19,119,152,'Jižť to dávno vím o svědectvích tvých, že jsi je stvrdil až na věky.'),
(1562309,54,19,119,153,'Reš Popatřiž na mé trápení, a vysvoboď mne; neboť se na zákon tvůj nezapomínám.'),
(1562310,54,19,119,154,'Zasaď se o mou při, a ochraň mne; pro řeč svou obživ mne.'),
(1562311,54,19,119,155,'Dalekoť jest od bezbožných spasení, nebo nedotazují se na ustanovení tvá.'),
(1562312,54,19,119,156,'Slitování tvá mnohá jsou, Hospodine; podlé soudů svých obživ mne.'),
(1562313,54,19,119,157,'Jakžkoli jsou mnozí protivníci moji a nepřátelé moji, však od svědectví tvých se neuchyluji.'),
(1562314,54,19,119,158,'Viděl jsem ty, kteříž se převráceně měli, velmi to těžce nesa, že řeči tvé neostříhali.'),
(1562315,54,19,119,159,'Popatřiž, žeť rozkazy tvé miluji, Hospodine; podlé milosrdenství svého obživ mne.'),
(1562316,54,19,119,160,'Nejpřednější věc slova tvého jest pravda, a na věky trvá všeliký úsudek spravedlnosti tvé.'),
(1562317,54,19,119,161,'Šin Knížata mi se protiví bez příčiny, však slova tvého děsí se srdce mé.'),
(1562318,54,19,119,162,'Já raduji se z řeči tvé tak jako ten, kterýž dochází hojné kořisti.'),
(1562319,54,19,119,163,'Falše pak nenávidím, a jí v ohavnosti mám; zákon tvůj miluji.'),
(1562320,54,19,119,164,'Sedmkrát za den chválím tě z soudů tvých spravedlivých.'),
(1562321,54,19,119,165,'Pokoj mnohý těm, kteříž milují zákon tvůj, a nemají žádné urážky.'),
(1562322,54,19,119,166,'Očekávám na spasení tvé, Hospodine,a přikázaní tvá vykonávám.'),
(1562323,54,19,119,167,'Ostříhá duše má svědectví tvých, nebo je velice miluji.'),
(1562324,54,19,119,168,'Ostříhám rozkazů tvých a svědectví tvých; nebo všecky cesty mé jsou před tebou.'),
(1562325,54,19,119,169,'Thav Předstupiž úpění mé před oblíčej tvůj, Hospodine, a podlé slova svého uděl mi rozumnosti.'),
(1562326,54,19,119,170,'Vejdiž pokorná prosba má před tvář tvou, a vedlé řeči své vytrhni mne.'),
(1562327,54,19,119,171,'I vynesou rtové moji chválu, když ty mne vyučíš ustanovením svým.'),
(1562328,54,19,119,172,'Zpívati bude i jazyk můj slovo tvé, a že všecka přikázaní tvá jsou spravedlnost.'),
(1562329,54,19,119,173,'Budiž mi ku pomoci ruka tvá; neboť jsem sobě zvolil přikázaní tvá.'),
(1562330,54,19,119,174,'Toužím po spasení tvém, Hospodine,a zákon tvůj jest rozkoš má.'),
(1562331,54,19,119,175,'Živa bude duše má, a bude tě chváliti,a soudové tvoji budou mi na pomoc.'),
(1562332,54,19,119,176,'Bloudím jako ovce ztracená, hledejž služebníka svého, neboť se na přikázaní tvá nezapomínám.'),
(1562333,54,19,120,1,'Píseň stupňů. K Hospodinu v ssoužení svém volal jsem,a vyslyšel mne.'),
(1562334,54,19,120,2,'Hospodine, vysvoboď duši mou od rtů lživých, a od jazyka lstivého.'),
(1562335,54,19,120,3,'Coť prospěje, aneb coť přidá jazyk lstivý,'),
(1562336,54,19,120,4,'Podobný k střelám přeostrým silného,a k uhlí jalovcovému?'),
(1562337,54,19,120,5,'Běda mně, že pohostinu býti musím v Mešech, a přebývati v saláších Cedarských.'),
(1562338,54,19,120,6,'Dlouho bydlí duše má mezi těmi, kteříž nenávidí pokoje.'),
(1562339,54,19,120,7,'Já ku pokoji, ale když mluvím, oni k boji.'),
(1562340,54,19,121,1,'Píseň stupňů. Pozdvihuji očí svých k horám, odkudž by mi přišla pomoc.'),
(1562341,54,19,121,2,'Pomoc má jest od Hospodina, kterýž učinil nebe i zemi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562342,54,19,121,3,'Nedopustíť, aby se pohnouti měla noha tvá, nedřímeť strážný tvůj.'),
(1562343,54,19,121,4,'Aj, nedřímeť, ovšem nespí ten, kterýž ostříhá Izraele.'),
(1562344,54,19,121,5,'Hospodin strážce tvůj, Hospodin zastínění tvé tobě po pravici.'),
(1562345,54,19,121,6,'Nebudeť bíti na tě slunce ve dne, ani měsíc v noci.'),
(1562346,54,19,121,7,'Hospodin tě ostříhati bude ode všeho zlého, ostříhati bude duše tvé.'),
(1562347,54,19,121,8,'Hospodin ostříhati tě bude, když vycházeti i vcházeti budeš, od tohoto času až na věky.'),
(1562348,54,19,122,1,'Píseň stupňů, Davidova. Veselím se z toho, že mi říkáno bývá: Poďme do domu Hospodinova,'),
(1562349,54,19,122,2,'A že se postavují nohy naše v branách tvých, ó Jeruzaléme.'),
(1562350,54,19,122,3,'Jižtě Jeruzalém ušlechtile vystaven, a jako v město k sobě vespolek připojen.'),
(1562351,54,19,122,4,'Do něhož vstupují pokolení, pokolení Hospodinova, k svědectví Izraelovu, aby oslavovali jméno Hospodinovo.'),
(1562352,54,19,122,5,'Nebo tamť jsou postaveny stolice soudu, stolice domu Davidova.'),
(1562353,54,19,122,6,'Žádejtež pokoje Jeruzalému, řkouce: Dějž se pokojně těm, kteříž tě milují.'),
(1562354,54,19,122,7,'Budiž pokoj v předhradí tvém, a upokojení na palácích tvých.'),
(1562355,54,19,122,8,'Pro bratří své a přátely své žádati budu pokoje tobě.'),
(1562356,54,19,122,9,'Pro dům Hospodina Boha našeho budu tvého dobrého hledati.'),
(1562357,54,19,123,1,'Píseň stupňů. K toběť pozdvihuji očí svých, ó ty, kterýž na nebesích přebýváš.'),
(1562358,54,19,123,2,'Aj hle, jakož oči služebníků k rukám pánů jejich, jakož oči děvky k rukám paní její: tak oči naše k Hospodinu Bohu našemu, až by se smiloval nad námi.'),
(1562359,54,19,123,3,'Smiluj se nad námi, Hospodine, smiluj se nad námi, neboť jsme již příliš potupou nasyceni.'),
(1562360,54,19,123,4,'Jižť jest příliš nasycena duše naše posmíšky bezbožných, a potupou pyšných.'),
(1562361,54,19,124,1,'Píseň stupňů, Davidova. Byť Hospodina s námi nebylo, rciž nyní, Izraeli,'),
(1562362,54,19,124,2,'Byť Hospodina s námi nebylo, když lidé povstali proti nám:'),
(1562363,54,19,124,3,'Tehdáž by nás byli za živa sehltili v rozpálení hněvu svého proti nám;'),
(1562364,54,19,124,4,'Tehdáž by nás byly přikvačily vody, proud zachvátil by byl duši naši;'),
(1562365,54,19,124,5,'Tehdáž zachvátily by byly duši naši ty vody zduté.'),
(1562366,54,19,124,6,'Požehnaný Hospodin, kterýž nás nevydal v loupež zubům jejich.'),
(1562367,54,19,124,7,'Duše naše jako ptáče znikla osídla ptáčníků; osídlo se ztrhalo, i vynikli jsme.'),
(1562368,54,19,124,8,'Pomoc naše jest ve jménu Hospodinovu, kterýž učinil nebe i zemi.'),
(1562369,54,19,125,1,'Píseň stupňů. Ti, kteříž doufají v Hospodina, podobni jsou k hoře Sionu, kteráž se nepohybuje, ale na věky zůstává.'),
(1562370,54,19,125,2,'Okolo Jeruzaléma jsou hory, Hospodin jest vůkol lidu svého, od tohoto času až na věky.'),
(1562371,54,19,125,3,'Neboť nebude státi sceptrum bezbožníků nad losem spravedlivých, aby nevztáhli spravedliví k nepravosti rukou svých.'),
(1562372,54,19,125,4,'Dobře učiň, Hospodine, dobrým, a těm, kteříž jsou upřímého srdce.'),
(1562373,54,19,125,5,'Ty pak, kteříž se uchylují k cestám svým křivým, zapudiž Hospodin s činiteli nepravosti. Pokoj přijdiž na Izraele.'),
(1562374,54,19,126,1,'Píseň stupňů. Když zase vedl Hospodin zajaté Sionské, zdálo se nám to jako ve snách.'),
(1562375,54,19,126,2,'Tehdážť byla plná radosti ústa naše,a jazyk náš plésání; tehdáž pravili mezi národy: Veliké věci s nimi učinil Hospodin.'),
(1562376,54,19,126,3,'Učinilť jest s námi veliké věci Hospodin, a protož veselili jsme se.'),
(1562377,54,19,126,4,'Uvediž zase, ó Hospodine, zajaté naše, tak jako potoky na vyprahlou krajinu.'),
(1562378,54,19,126,5,'Ti, kteříž se slzami rozsívali, s prozpěvováním žíti budou.'),
(1562379,54,19,126,6,'Sem i tam chodící lid s pláčem rozsívá drahé símě, ale potom přijda, s plésáním snášeti bude snopy své.'),
(1562380,54,19,127,1,'Píseň stupňů, Šalomounova. Nebude-li Hospodin stavěti domu, nadarmo usilují ti, kteříž stavějí jej; nebude-li Hospodin ostříhati města, nadarmo bdí strážný.'),
(1562381,54,19,127,2,'Daremnéť jest vám ráno vstávati, dlouho sedati, a jísti chléb bolesti, poněvadž Bůh dává milému svému i sen.'),
(1562382,54,19,127,3,'Aj, dědictví od Hospodina jsou dítky, a plod života jest mzda.'),
(1562383,54,19,127,4,'Jako střely v ruce udatného, tak jsou dítky zdárné.'),
(1562384,54,19,127,5,'Blahoslavený muž, kterýž by jimi naplnil toul svůj; nebudouť zahanbeni, když v rozepři budou s nepřátely v branách.'),
(1562385,54,19,128,1,'Píseň stupňů. Blahoslavený každý, kdo se bojí Hospodina, a chodí po cestách jeho.'),
(1562386,54,19,128,2,'Nebo z práce rukou svých živnost míti budeš, blahoslavený budeš, a štastněť se povede.'),
(1562387,54,19,128,3,'Manželka tvá jako vinný kmen plodný po bocích domu tvého, dítky tvé jako mladistvé olivoví vůkol stolu tvého.'),
(1562388,54,19,128,4,'Aj, takovéť bude míti požehnání muž bojící se Hospodina.'),
(1562389,54,19,128,5,'Požehnání tobě uděliž Hospodin z Siona, a ty spatřuj dobré věci Jeruzaléma po všecky dny života svého;'),
(1562390,54,19,128,6,'A viz syny synů svých, a pokoj nad Izraelem.'),
(1562391,54,19,129,1,'Píseň stupňů. Veliceť jsou mne ssužovali hned od mladosti mé, rciž nyní Izraeli,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562392,54,19,129,2,'Veliceť jsou mne ssužovali hned od mladosti mé, a však mne nepřemohli.'),
(1562393,54,19,129,3,'Po hřbetě mém orali oráči, a dlouhé proháněli brázdy své.'),
(1562394,54,19,129,4,'Ale Hospodin jsa spravedlivý, zpřetínal prostranky bezbožných.'),
(1562395,54,19,129,5,'Zahanbeni a zpět obráceni budou všickni, kteříž nenávidí Siona.'),
(1562396,54,19,129,6,'Budou jako tráva na střechách, kteráž prvé než odrostá, usychá.'),
(1562397,54,19,129,7,'Z níž nemůže hrsti své naplniti žnec, ani náručí svého ten, kterýž váže snopy.'),
(1562398,54,19,129,8,'Aniž řeknou tudy jdoucí: Požehnání Hospodinovo budiž s vámi, aneb: Dobrořečíme vám ve jménu Hospodinovu.'),
(1562399,54,19,130,1,'Píseň stupňů. Z hlubokosti volám k tobě, Hospodine.'),
(1562400,54,19,130,2,'Pane, vyslyš hlas můj, nakloň uší svých k hlasu pokorných proseb mých.'),
(1562401,54,19,130,3,'Budeš-li nepravosti šetřiti, Hospodine Pane, kdo ostojí?'),
(1562402,54,19,130,4,'Ale u tebe jest odpuštění, tak aby uctivost k tobě zachována byla.'),
(1562403,54,19,130,5,'Očekávám na Hospodina, očekává duše má, a ještě očekává na slovo jeho.'),
(1562404,54,19,130,6,'Duše má čeká Pána, víc než ponocní svitání, kteříž ponocují až do jitra.'),
(1562405,54,19,130,7,'Očekávejž, Izraeli, na Hospodina; nebo u Hospodina jest milosrdenství, a hojné u něho vykoupení.'),
(1562406,54,19,130,8,'Onť zajisté vykoupí Izraele ze všech nepravostí jeho.'),
(1562407,54,19,131,1,'Píseň stupňů, Davidova. Hospodine, nepozdvihlotě se srdce mé, ani se povýšily oči mé, aniž jsem se vydal v věci veliké, aneb vyšší nad to, než mi náleží.'),
(1562408,54,19,131,2,'Zdali jsem nepoložil a neupokojil duše své, jako dítě ostavené od matky své? Ostavenému podobná byla ve mně duše má.'),
(1562409,54,19,131,3,'Doufej, ó Izraeli, v Hospodina, od tohoto času až na věky.'),
(1562410,54,19,132,1,'Píseň stupňů. Pamětliv buď, Hospodine, na Davida i na všecka trápení jeho,'),
(1562411,54,19,132,2,'Jak se přísahou zavázal Hospodinu, a slib učinil Nejmocnějšímu Jákobovu, řka:'),
(1562412,54,19,132,3,'Jistě že nevejdu do stánku domu svého, a nevstoupím na postel ložce svého,'),
(1562413,54,19,132,4,'Aniž dám očím svým usnouti, ani víčkám svým zdřímati,'),
(1562414,54,19,132,5,'Dokudž nenajdu místa Hospodinu, k příbytkům Nejmocnějšímu Jákobovu.'),
(1562415,54,19,132,6,'Aj, uslyšavše o ní, že byla v kraji Efratském, našli jsme ji na polích Jaharských.'),
(1562416,54,19,132,7,'Vejdemeť již do příbytků jeho, a skláněti se budeme u podnoží noh jeho.'),
(1562417,54,19,132,8,'Povstaniž, Hospodine, a vejdi do odpočinutí svého, ty i truhla velikomocnosti tvé.'),
(1562418,54,19,132,9,'Kněží tvoji ať se zobláčejí v spravedlnost, a svatí tvoji ať vesele prozpěvují.'),
(1562419,54,19,132,10,'Pro Davida služebníka svého neodvracejž tváři pomazaného svého.'),
(1562420,54,19,132,11,'Učinilť jest Hospodin pravdomluvnou přísahu Davidovi, aniž se od ní uchýlí, řka: Z plodu života tvého posadím na trůn tvůj.'),
(1562421,54,19,132,12,'Budou-li ostříhati synové tvoji smlouvy mé a svědectví mých, kterýmž je vyučovati budu, také i synové jejich až na věky seděti budou na stolici tvé.'),
(1562422,54,19,132,13,'Neboť jest vyvolil Hospodin Sion, oblíbil jej sobě za svůj příbytek, řka:'),
(1562423,54,19,132,14,'Toť bude obydlí mé až na věky, tuť přebývati budu, nebo jsem sobě to oblíbil.'),
(1562424,54,19,132,15,'Potravu jeho hojným požehnáním rozmnožím, chudé jeho chlebem nasytím,'),
(1562425,54,19,132,16,'A kněží jeho v spasení zobláčím, a svatí jeho vesele prozpěvovati budou.'),
(1562426,54,19,132,17,'Tuť způsobím, aby zkvetl roh Davidův; připravím svíci pomazanému svému.'),
(1562427,54,19,132,18,'Nepřátely jeho v hanbu zobláčím, nad ním pak kvésti bude koruna jeho.'),
(1562428,54,19,133,1,'Píseň stupňů, Davidova. Aj, jak dobré a jak utěšené, když bratří v jednomyslnosti přebývají!'),
(1562429,54,19,133,2,'Jako mast výborná na hlavě, sstupující na bradu, bradu Aronovu, tekoucí až i na podolek roucha jeho.'),
(1562430,54,19,133,3,'A jako rosa Hermon, kteráž sstupuje na hory Sionské. Nebo tu udílí Hospodin požehnání i života až na věky.'),
(1562431,54,19,134,1,'Píseň stupňů. Ej nuž dobrořečte Hospodinu všickni služebníci Hospodinovi, kteříž stáváte v domě Hospodinově každé noci.'),
(1562432,54,19,134,2,'Pozdvihujte rukou svých k svatyni, a dobrořečte Hospodinu, říkajíce:'),
(1562433,54,19,134,3,'Požehnejž tobě Hospodin z Siona, kterýž učinil nebe i zemi.'),
(1562434,54,19,135,1,'Halelujah. Chvalte jméno Hospodinovo, chvalte služebníci Hospodinovi,'),
(1562435,54,19,135,2,'Kteříž stáváte v domě Hospodinově, v síňcích domu Boha našeho.'),
(1562436,54,19,135,3,'Chvalte Hospodina, nebo jest dobrý Hospodin; žalmy zpívejte jménu jeho, nebo rozkošné jest.'),
(1562437,54,19,135,4,'Jákoba zajisté sobě vyvolil Hospodin, a Izraele za svůj lid zvláštní.'),
(1562438,54,19,135,5,'Jáť jsem jistě seznal, že veliký jest Hospodin, a Pán náš nade všecky bohy.'),
(1562439,54,19,135,6,'Cožkoli chce Hospodin, to činí na nebi i na zemi, v moři i ve všech propastech.'),
(1562440,54,19,135,7,'Kterýž způsobuje to, že páry vystupují od krajů země; blýskání s deštěm přivodí, a vyvodí vítr z pokladů svých.'),
(1562441,54,19,135,8,'Kterýž zbil prvorozené v Egyptě, od člověka až do hovada.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562442,54,19,135,9,'Poslal znamení a zázraky u prostřed tebe, Egypte, na Faraona i na všecky služebníky jeho.'),
(1562443,54,19,135,10,'Kterýž pobil národy mnohé, a zbil krále mocné,'),
(1562444,54,19,135,11,'Seona krále Amorejského, a Oga krále Bázan, i všecka království Kananejská.'),
(1562445,54,19,135,12,'A dal zemi jejich v dědictví, v dědictví Izraelovi lidu svému.'),
(1562446,54,19,135,13,'Hospodine, jméno tvé na věky, Hospodine, památka tvá od národu až do pronárodu.'),
(1562447,54,19,135,14,'Souditi zajisté bude Hospodin lid svůj, a služebníkům svým bude milostiv.'),
(1562448,54,19,135,15,'Ale modly pohanské stříbro a zlato, dílo rukou lidských,'),
(1562449,54,19,135,16,'Ústa mají a nemluví, oči mají a nevidí.'),
(1562450,54,19,135,17,'Uši mají a neslyší, nýbrž ani ducha není v ústech jejich.'),
(1562451,54,19,135,18,'Buďtež jim podobní, kteříž je dělají, a kdožkoli naději svou v nich skládají.'),
(1562452,54,19,135,19,'Dome Izraelský, dobrořečte Hospodinu; dome Aronův, dobrořečte Hospodinu.'),
(1562453,54,19,135,20,'Dome Léví, dobrořečte Hospodinu; kteříž se bojíte Hospodina, dobrořečte Hospodinu.'),
(1562454,54,19,135,21,'Požehnaný Hospodin z Siona, kterýž přebývá v Jeruzalémě. Halelujah.'),
(1562455,54,19,136,1,'Oslavujte Hospodina, nebo jest dobrý, nebo věčné jest milosrdenství jeho.'),
(1562456,54,19,136,2,'Oslavujte Boha bohů, nebo jest věčné milosrdenství jeho.'),
(1562457,54,19,136,3,'Oslavujte Pána pánů, nebo jest věčné milosrdenství jeho.'),
(1562458,54,19,136,4,'Toho, kterýž sám činí divy veliké, nebo jest věčné milosrdenství jeho.'),
(1562459,54,19,136,5,'Kterýž učinil nebesa moudře, nebo jest věčné milosrdenství jeho.'),
(1562460,54,19,136,6,'Kterýž roztáhl zemi na vodách, nebo jest věčné milosrdenství jeho.'),
(1562461,54,19,136,7,'Kterýž učinil světla veliká, nebo jest věčné milosrdenství jeho.'),
(1562462,54,19,136,8,'Slunce, aby panovalo ve dne, nebo jest věčné milosrdenství jeho.'),
(1562463,54,19,136,9,'Měsíc a hvězdy, aby panovaly v noci, nebo jest věčné milosrdenství jeho.'),
(1562464,54,19,136,10,'Kterýž ranil Egyptské v prvorozených jejich, nebo jest věčné milosrdenství jeho.'),
(1562465,54,19,136,11,'A vyvedl Izraele z prostředku jejich, nebo jest věčné milosrdenství jeho.'),
(1562466,54,19,136,12,'V ruce silné a v rameni vztaženém, nebo jest věčné milosrdenství jeho.'),
(1562467,54,19,136,13,'Kterýž rozdělil moře Rudé na díly, nebo jest věčné milosrdenství jeho.'),
(1562468,54,19,136,14,'A převedl Izraele prostředkem jeho, nebo jest věčné milosrdenství jeho.'),
(1562469,54,19,136,15,'A uvrhl Faraona s vojskem jeho do moře Rudého, nebo jest věčné milosrdenství jeho.'),
(1562470,54,19,136,16,'Kterýž vedl lid svůj přes poušť, nebo jest věčné milosrdenství jeho.'),
(1562471,54,19,136,17,'Kterýž pobil krále veliké, nebo jest věčné milosrdenství jeho.'),
(1562472,54,19,136,18,'A zbil krále znamenité, nebo jest věčné milosrdenství jeho.'),
(1562473,54,19,136,19,'Seona krále Amorejského, nebo jest věčné milosrdenství jeho.'),
(1562474,54,19,136,20,'Též Oga krále Bázan, nebo jest věčné milosrdenství jeho.'),
(1562475,54,19,136,21,'A dal zemi jejich v dědictví, nebo jest věčné milosrdenství jeho.'),
(1562476,54,19,136,22,'V dědictví Izraelovi, služebníku svému, nebo jest věčné milosrdenství jeho.'),
(1562477,54,19,136,23,'Kterýž v snížení našem pamatuje na nás, nebo jest věčné milosrdenství jeho.'),
(1562478,54,19,136,24,'A vytrhl nás z nepřátel našich, nebo jest věčné milosrdenství jeho.'),
(1562479,54,19,136,25,'Kterýž dává pokrm všelikému tělu, nebo jest věčné milosrdenství jeho.'),
(1562480,54,19,136,26,'Oslavujte Boha silného nebes, neboť jest věčné milosrdenství jeho.'),
(1562481,54,19,137,1,'Při řekách Babylonských tam jsme sedávali, a plakávali, rozpomínajíce se na Sion.'),
(1562482,54,19,137,2,'Na vrbí v té zemi zavěšovali jsme citary své.'),
(1562483,54,19,137,3,'A když se tam dotazovali nás ti, kteříž nás zajali, na slova písničky, (ješto jsme zavěsili byli veselí), říkajíce: Zpívejte nám některou píseň Sionskou:'),
(1562484,54,19,137,4,'Kterakž bychom měli zpívati píseň Hospodinovu v zemi cizozemců?'),
(1562485,54,19,137,5,'Jestliže se zapomenu na tebe, ó Jeruzaléme, zapomeniž i pravice má.'),
(1562486,54,19,137,6,'Přilniž i jazyk můj k dásním mým, nebudu-li se rozpomínati na tebe, jestliže v samém Jeruzalémě nebudu míti svého největšího potěšení.'),
(1562487,54,19,137,7,'Rozpomeň se, Hospodine, na Idumejské, a na den Jeruzaléma, kteříž pravili: Rozbořte, rozbořte až do základů v něm.'),
(1562488,54,19,137,8,'Ó dcero Babylonská, zkažena býti máš. Blahoslavený ten, kdož odplatí tobě za to, což jsi nám zlého učinila.'),
(1562489,54,19,137,9,'Blahoslavený, kdož pochytí dítky tvé a o skálu je rozrážeti bude.'),
(1562490,54,19,138,1,'Davidův. Oslavovati tě budu, Pane, celým srdcem svým, a před mocnými žalmy tobě zpívati.'),
(1562491,54,19,138,2,'Skláněti se budu k chrámu svatému tvému, a oslavovati jméno tvé pro milosrdenství tvé a pro pravdu tvou; nebo jsi zvelebil nade všecko jméno své a slovo své.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562492,54,19,138,3,'Kteréhokoli dne vzýval jsem tě, vyslyšels mne, a obdařils silou duši mou.'),
(1562493,54,19,138,4,'Oslavovati tě budou, Hospodine, i všickni králové země, když uslyší řeč úst tvých.'),
(1562494,54,19,138,5,'A zpívati budou o cestách Hospodinových, a že veliká jest sláva Hospodinova,'),
(1562495,54,19,138,6,'A ač vyvýšený jest Hospodin, však že na poníženého patří, a vysokomyslného zdaleka zná.'),
(1562496,54,19,138,7,'Bych pak chodil u prostřed ssoužení, obživíš mne; proti vzteklosti nepřátel mých vztáhneš ruku svou, a tak vysvobodí mne pravice tvá.'),
(1562497,54,19,138,8,'Hospodin dokoná za mne; nebo milosrdenství tvé, Hospodine, na věky, aniž díla rukou svých kdy opustíš.'),
(1562498,54,19,139,1,'Přednímu zpěváku, žalm Davidův. Hospodine, ty jsi mne zkusil a seznal.'),
(1562499,54,19,139,2,'Ty znáš sednutí mé i povstání mé, rozumíš myšlení mému zdaleka.'),
(1562500,54,19,139,3,'Chození mé i ležení mé ty obsahuješ, a všech mých cest svědom jsi.'),
(1562501,54,19,139,4,'Než ještě mám na jazyku slovo, aj, Hospodine, ty to všecko víš.'),
(1562502,54,19,139,5,'Z zadu i z předu obklíčils mne, a vzložils na mne ruku svou.'),
(1562503,54,19,139,6,'Divnější jest umění tvé nad můj vtip; vysoké jest, nemohu k němu.'),
(1562504,54,19,139,7,'Kamž bych zašel od ducha tvého? Aneb kam bych před tváří tvou utekl?'),
(1562505,54,19,139,8,'Jestliže bych vstoupil na nebe, tam jsi ty; pakli bych sobě ustlal v hrobě, aj, přítomen jsi.'),
(1562506,54,19,139,9,'Vzal-li bych křídla záře jitřní, abych bydlil při nejdalším moři:'),
(1562507,54,19,139,10,'I tamť by mne ruka tvá provedla, a pravice tvá by mne popadla.'),
(1562508,54,19,139,11,'Dím-li pak: Aspoň tmy, jako v soumrak, přikryjí mne, ale i noc jest světlem vůkol mne.'),
(1562509,54,19,139,12,'Aniž ty tmy před tebou ukryti mohou, anobrž noc jako den tobě svítí, rovně tma jako světlo.'),
(1562510,54,19,139,13,'Ty zajisté v moci máš ledví má, přioděl jsi mne v životě matky mé.'),
(1562511,54,19,139,14,'Oslavuji tě, proto že se hrozným a divným skutkům tvým divím, a duše má zná je výborně.'),
(1562512,54,19,139,15,'Neníť ukryta žádná kost má před tebou, jakž jsem učiněn v skrytě, a řemeslně složen, v nejhlubších místech země.'),
(1562513,54,19,139,16,'Trupel můj viděly oči tvé, v knihu tvou všickni oudové jeho zapsáni jsou, i dnové,v nichž formováni byli, když ještě žádného z nich nebylo.'),
(1562514,54,19,139,17,'Protož u mne ó jak drahá jsou myšlení tvá, Bože silný, a jak jest jich nesčíslná summa!'),
(1562515,54,19,139,18,'Chtěl-li bych je sčísti, více jest jich než písku; procítím-li, a já jsem vždy s tebou.'),
(1562516,54,19,139,19,'Zabil-li bys, ó Bože, bezbožníka, tehdážť by muži vražedlní odstoupili ode mne,'),
(1562517,54,19,139,20,'Kteříž mluví proti tobě nešlechetně; marně vyvyšují nepřátely tvé.'),
(1562518,54,19,139,21,'Zdaliž těch, kteříž tě v nenávisti mají, ó Hospodine, v nenávisti nemám? A ti, kteříž proti tobě povstávají, zdaž mne nemrzejí?'),
(1562519,54,19,139,22,'Úhlavní nenávistí jich nenávidím, a mám je za nepřátely.'),
(1562520,54,19,139,23,'Vyzpytuj mne, Bože silný, a poznej srdce mé; zkus mne, a poznej myšlení má.'),
(1562521,54,19,139,24,'A popatř, chodím-liť já cestou odpornou tobě, a veď mne cestou věčnou.'),
(1562522,54,19,140,1,'Přednímu z kantorů, žalm Davidův.'),
(1562523,54,19,140,2,'Vysvoboď mne, Hospodine, od člověka zlého, a od muže ukrutného ostříhej mne,'),
(1562524,54,19,140,3,'Kteříž myslí zlé věci v srdci, a na každý den sbírají se k válce.'),
(1562525,54,19,140,4,'Naostřují jazyk svůj jako had, jed lítého hada jest ve rtech jejich. Sélah.'),
(1562526,54,19,140,5,'Ostříhej mne, Hospodine, od rukou bezbožníka, od muže ukrutného zachovej mne, kteříž myslí podraziti nohy mé.'),
(1562527,54,19,140,6,'Polékli pyšní na mne osídlo a provazy, roztáhli teneta u cesty, a léčky své mi položili. Sélah.'),
(1562528,54,19,140,7,'Řekl jsem Hospodinu: Bůh silný můj jsi, pozoruj, Hospodine, hlasu pokorných modliteb mých.'),
(1562529,54,19,140,8,'Hospodine Pane, sílo spasení mého, kterýž přikrýváš hlavu mou v čas boje,'),
(1562530,54,19,140,9,'Nedávej, Hospodine, bezbožnému, čehož žádostiv jest, ani předsevzetí zlého vykonati jemu dopouštěj, aby se nepovýšil. Sélah.'),
(1562531,54,19,140,10,'Vůdce těch, jenž obkličují mne, nepravost rtů jejich ať přikryje.'),
(1562532,54,19,140,11,'Padej na ně uhlé řeřavé, a na oheň uvrz je, do jam hlubokých, aby nemohli povstati.'),
(1562533,54,19,140,12,'Člověk utrhač nebude upevněn na zemi, a muž ukrutný, zlostí polapen jsa, padne.'),
(1562534,54,19,140,13,'Vím, žeť se Hospodin zasadí o při chudého, a pomstí nuzných.'),
(1562535,54,19,140,14,'A tak spravedliví slaviti budou jméno tvé, a upřímí přebývati před oblíčejem tvým.'),
(1562536,54,19,141,1,'Žalm Davidův. Hospodine, k toběť volám, pospěš ke mně; pozoruj hlasu mého, když tebe vzývám.'),
(1562537,54,19,141,2,'Budiž příjemná modlitba má, jako kadění před oblíčejem tvým, pozdvižení rukou mých, jako obět večerní.'),
(1562538,54,19,141,3,'Polož, Hospodine, stráž ústům mým, ostříhej dveří rtů mých.'),
(1562539,54,19,141,4,'Nedopouštěj srdci mému uchýliti se ke zlé věci, k činění skutků bezbožných, s muži činícími nepravost, a abych nebyl přelouzen líbostmi jejich.'),
(1562540,54,19,141,5,'Nechť mne bije spravedlivý, přijmu to za dobrodiní, a nechť tresce mne, bude mi to olej nejčistší, kterýž neprorazí hlavy mé, ale ještěť modlitba má platná bude proti zlosti jejich.'),
(1562541,54,19,141,6,'Smetáni jsou do míst skalnatých soudcové jejich, aby slyšeli slova má, nebo jsou libá.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562542,54,19,141,7,'Jako když někdo roubá a štípá dříví na zemi, tak se rozletují kosti naše až k ústům hrobovým.'),
(1562543,54,19,141,8,'Ale k toběť, Hospodine Pane, oči mé; v tebe doufám, nevylévej duše mé.'),
(1562544,54,19,141,9,'Zachovej mne od osídla, kteréž mi roztáhli, a od sítek činících nepravost.'),
(1562545,54,19,141,10,'Nechť padnou hromadně do sítek svých bezbožní, a já zatím přejdu.'),
(1562546,54,19,142,1,'Vyučující Davidův, když byl v jeskyni, modlitba jeho.'),
(1562547,54,19,142,2,'Hlasem svým k Hospodinu volám, hlasem svým Hospodinu pokorně se modlím.'),
(1562548,54,19,142,3,'Vylévám před oblíčejem jeho žádost svou, a ssoužení své před ním oznamuji.'),
(1562549,54,19,142,4,'Když se úzkostmi svírá ve mně duch můj, ty znáš stezku mou; na cestě, po kteréžkoli chodím, osídlo mi ukryli.'),
(1562550,54,19,142,5,'Ohlédám-li se na pravo, a patřím, není, kdo by mne znáti chtěl; zhynulo útočiště mé, není, kdo by se ujal o život můj.'),
(1562551,54,19,142,6,'K tobě volám, Hospodine, říkaje: Ty jsi doufání mé a díl můj v zemi živých.'),
(1562552,54,19,142,7,'Pozorujž volání mého, neboť jsem zemdlen přenáramně; vysvoboď mne od těch, jenž stihají mne, nebo jsou silnější nežli já.'),
(1562553,54,19,142,8,'Vyveď z žaláře duši mou, abych oslavoval jméno tvé; obstoupí mne spravedliví, když mi dobrodiní učiníš.'),
(1562554,54,19,143,1,'Žalm Davidův. Hospodine, slyš modlitbu mou, pozoruj pokorné prosby mé; pro pravdu svou vyslyš mne, i pro spravedlnost svou.'),
(1562555,54,19,143,2,'A nevcházej v soud s služebníkem svým, neboť by nebyl spravedliv před tebou nižádný živý.'),
(1562556,54,19,143,3,'Nebo stihá nepřítel duši mou, potírá až k zemi život můj; na to mne přivodí, abych bydlil v mrákotě, jako ti, kteříž již dávno zemřeli,'),
(1562557,54,19,143,4,'Tak že se svírá úzkostmi duch můj ve mně, u vnitřnosti mé hyne srdce mé.'),
(1562558,54,19,143,5,'Rozpomínaje se na dny předešlé, a rozvažuje všecky skutky tvé, a dílo rukou tvých rozjímaje,'),
(1562559,54,19,143,6,'Vztahuji ruce své k tobě, duše má jako země vyprahlá žádá tebe. Sélah.'),
(1562560,54,19,143,7,'Pospěšiž a vyslyš mne, Hospodine, hyne duch můj; neukrývejž tváři své přede mnou, neboť jsem podobný těm, kteříž sstupují do hrobu.'),
(1562561,54,19,143,8,'Učiň to, ať v jitře slyším milosrdenství tvé, neboť v tobě naději mám; oznam mi cestu, po kteréž bych choditi měl, neboť k tobě pozdvihuji duše své.'),
(1562562,54,19,143,9,'Vytrhni mne z nepřátel mých, Hospodine, u tebeť se skrývám.'),
(1562563,54,19,143,10,'Nauč mne činiti vůle tvé, nebo ty jsi Bůh můj; duch tvůj dobrý vediž mne jako po rovné zemi.'),
(1562564,54,19,143,11,'Pro jméno své, Hospodine, obživ mne, pro spravedlnost svou vyveď z úzkosti duši mou.'),
(1562565,54,19,143,12,'A pro milosrdenství své vypleň nepřátely mé, a vyhlaď všecky, kteříž trápí duši mou; nebo já jsem služebník tvůj.'),
(1562566,54,19,144,1,'Davidův. Požehnaný Hospodin skála má, kterýž učí ruce mé boji, a prsty mé bitvě.'),
(1562567,54,19,144,2,'Milosrdenství mé a hrad můj, útočiště mé, vysvoboditel můj, a štít můj, protož v něhoť já doufám; onť mi podmaňuje lidi.'),
(1562568,54,19,144,3,'Hospodine, co jest člověk, že se znáš k němu, a syn člověka, že ho sobě tak vážíš?'),
(1562569,54,19,144,4,'Člověk marnosti podobný jest, dnové jeho jako stín pomíjející.'),
(1562570,54,19,144,5,'Hospodine, nakloň svých nebes a sstup, dotkni se hor, a kouřiti se budou.'),
(1562571,54,19,144,6,'Sešli hromobití a rozptyl je, vypusť střely své a poraz je.'),
(1562572,54,19,144,7,'Vztáhni ruku svou s výsosti, vysvoboď mne, a vytrhni mne z vod mnohých, z ruky cizozemců.'),
(1562573,54,19,144,8,'Jejichž ústa mluví marnost, a pravice jejich jest pravice lživá.'),
(1562574,54,19,144,9,'Bože, píseň novou zpívati budu tobě na loutně, a na desíti strunách žalmy tobě prozpěvovati,'),
(1562575,54,19,144,10,'Dávajícímu vítězství králům, a vysvobozujícímu Davida, služebníka svého od meče vražedlného.'),
(1562576,54,19,144,11,'Vysvoboď mne, a vytrhni mne z ruky cizozemců, jejichž ústa mluví marnost, a pravice jejich pravice lživá.'),
(1562577,54,19,144,12,'Aby synové naši byli jako štípkové zdárně rostoucí v mladosti své, a dcery naše jako úhelní kamenové, tesaní ku podobenství chrámu.'),
(1562578,54,19,144,13,'Špižírny naše plné ať vydávají všelijaké potravy; dobytek náš ať rodí na tisíce, a na deset tisíců v stájích našich.'),
(1562579,54,19,144,14,'Volové naši ať jsou vytylí; ať není vpádu ani zajetí, ani naříkání na ulicích našich.'),
(1562580,54,19,144,15,'Blahoslavený lid, jemuž se tak děje, blahoslavený ten lid, jehož Hospodin Bohem jest.'),
(1562581,54,19,145,1,'Chvalitebná píseň Davidova. Vyvyšovati tě budu, Bože můj králi, a dobrořečiti jménu tvému na věky věků.'),
(1562582,54,19,145,2,'Na každý den dobrořečiti budu tobě, a chváliti jméno tvé na věky věků.'),
(1562583,54,19,145,3,'Hospodin veliký jest, a vší chvály hodný, a velikost jeho nemůž vystižena býti.'),
(1562584,54,19,145,4,'Rodina rodině vychvalovati bude skutky tvé, a předivnou moc tvou zvěstovati.'),
(1562585,54,19,145,5,'O slávě a kráse velebnosti tvé, i o věcech tvých předivných mluviti budu.'),
(1562586,54,19,145,6,'A moc přehrozných skutků tvých rozhlašovati budou; i já důstojnost tvou budu vypravovati.'),
(1562587,54,19,145,7,'Pamět mnohé dobroty tvé hlásati budou, a o spravedlnosti tvé zpívati, řkouce:'),
(1562588,54,19,145,8,'Milostivý a lítostivý jest Hospodin, dlouhoshovívající a velikého milosrdenství.'),
(1562589,54,19,145,9,'Dobrotivý Hospodin všechněm, a slitování jeho nade všecky skutky jeho.'),
(1562590,54,19,145,10,'Oslavujtež tebe, Hospodine, všickni skutkové tvoji, a svatí tvoji tobě dobrořečte.'),
(1562591,54,19,145,11,'Slávu království tvého ať vypravují, a o síle tvé mluví,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562592,54,19,145,12,'Aby v známost uvedli synům lidským moci jeho, a slávu i ozdobu království jeho.'),
(1562593,54,19,145,13,'Království tvé jest království všech věků, a panování tvé nad jedním každým pokolením.'),
(1562594,54,19,145,14,'Zdržujeť Hospodin všecky padající, a pozdvihuje všechněch sklíčených.'),
(1562595,54,19,145,15,'Oči všechněch v tebe doufají, a ty dáváš jim pokrm jejich v čas příhodný.'),
(1562596,54,19,145,16,'Otvíráš ruku svou, a nasycuješ každý živočich podlé dobře líbezné vůle své.'),
(1562597,54,19,145,17,'Spravedlivý jest Hospodin ve všech cestách svých, a milosrdný ve všech skutcích svých.'),
(1562598,54,19,145,18,'Blízký jest Hospodin všechněm, kteříž ho vzývají, všechněm, kteříž ho vzývají v pravdě.'),
(1562599,54,19,145,19,'Vůli těch, kteříž se ho bojí, činí, a křik jejich slyší, a spomáhá jim.'),
(1562600,54,19,145,20,'Ostříhá Hospodin všech, kdož jej milují, ale všecky bezbožné zatratí.'),
(1562601,54,19,145,21,'Chválu Hospodinovu vypravovati budou ústa má, a dobrořečiti bude všeliké tělo jménu svatému jeho od věků až na věky.'),
(1562602,54,19,146,1,'Halelujah. Chval, duše má, Hospodina.'),
(1562603,54,19,146,2,'Chváliti budu Hospodina, dokud jsem živ, žalmy zpívati Bohu svému, dokud mne stává.'),
(1562604,54,19,146,3,'Nedoufejtež v knížatech, v synech lidských, v nichž není vysvobození.'),
(1562605,54,19,146,4,'Vychází duch jejich, navracují se do země své, v tentýž den mizejí myšlení jejich.'),
(1562606,54,19,146,5,'Blahoslavený ten, jehož spomocník jest Bůh silný Jákobův, jehož naděje jest v Hospodinu Bohu jeho,'),
(1562607,54,19,146,6,'Kterýž učinil nebe, zemi, moře, i vše, což v nich jest, kterýž ostříhá pravdy až na věky,'),
(1562608,54,19,146,7,'Kterýž činí soud utištěným, dává chléb lačným. Hospodin vysvobozuje vězně.'),
(1562609,54,19,146,8,'Hospodin otvírá oči slepých, Hospodin pozdvihuje snížených, Hospodin miluje spravedlivé.'),
(1562610,54,19,146,9,'Hospodin ostříhá příchozích, sirotku a vdově pomáhá, ale cestu bezbožných podvrací.'),
(1562611,54,19,146,10,'Kralovati bude Hospodin na věky, Bůh tvůj, ó Sione, od národu až do pronárodu. Halelujah.'),
(1562612,54,19,147,1,'Chvalte Hospodina, nebo dobré jest zpívati žalmy Bohu našemu, nebo rozkošné jest, a ozdobná jest chvála.'),
(1562613,54,19,147,2,'Stavitel Jeruzaléma Hospodin, rozptýlený lid Izraelský shromažďuje,'),
(1562614,54,19,147,3,'Kterýž uzdravuje skroušené srdcem, a uvazuje bolesti jejich,'),
(1562615,54,19,147,4,'Kterýž sčítá počet hvězd, a každé z nich ze jména povolává.'),
(1562616,54,19,147,5,'Velikýť jest Pán náš, a nesmírný v síle; rozumnosti jeho není počtu.'),
(1562617,54,19,147,6,'Pozdvihuje pokorných Hospodin, ale bezbožné snižuje až k zemi.'),
(1562618,54,19,147,7,'Zpívejte Hospodinu s díkčiněním, zpívejte žalmy Bohu našemu na citaře,'),
(1562619,54,19,147,8,'Kterýž zastírá nebesa hustými oblaky, nastrojuje zemi déšť, a vyvodí trávu na horách.'),
(1562620,54,19,147,9,'Kterýž dává hovadům potravu jejich, i mladým krkavcům, kteříž volají k němu.'),
(1562621,54,19,147,10,'Nemáť v síle koně zalíbení, aniž se kochá v lejtkách muže udatného.'),
(1562622,54,19,147,11,'Líbost má Hospodin v těch, kteříž se ho bojí, a kteříž doufají v milosrdenství jeho.'),
(1562623,54,19,147,12,'Chval, Jeruzaléme, Hospodina, chval Boha svého, Sione.'),
(1562624,54,19,147,13,'Nebo on utvrzuje závory bran tvých, požehnání udílí synům tvým u prostřed tebe.'),
(1562625,54,19,147,14,'On působí v končinách tvých pokoj, a bělí pšeničnou nasycuje tě.'),
(1562626,54,19,147,15,'On když vysílá na zemi rozkaz svůj, velmi rychle k vykonání běží slovo jeho.'),
(1562627,54,19,147,16,'Onť dává sníh jako vlnu, jíním jako popelem posýpá.'),
(1562628,54,19,147,17,'Hází ledem svým jako skyvami; před zimou jeho kdo ostojí?'),
(1562629,54,19,147,18,'Vysílaje slovo své, rozpouští je; hned jakž povane větrem svým, anť tekou vody.'),
(1562630,54,19,147,19,'Zvěstuje slovo své Jákobovi, ustanovení svá a soudy své Izraelovi.'),
(1562631,54,19,147,20,'Neučinilť tak žádnému národu, a protož soudů jeho nepoznali. Halelujah.'),
(1562632,54,19,148,1,'Halelujah. Chvalte hospodina stvoření nebeská, chvaltež ho na výsostech.'),
(1562633,54,19,148,2,'Chvalte jej všickni andělé jeho, chvalte jej všickni zástupové jeho.'),
(1562634,54,19,148,3,'Chvalte jej slunce i měsíc, chvalte jej všecky jasné hvězdy.'),
(1562635,54,19,148,4,'Chvalte jej nebesa nebes, i vody, kteréž jsou nad nebem tímto.'),
(1562636,54,19,148,5,'Chvalte jméno Hospodinovo všecky věci, kteréž, jakž on řekl, pojednou stvořeny jsou.'),
(1562637,54,19,148,6,'A utvrdil je na věčné věky, uložil cíle, z nichž by nevykračovaly.'),
(1562638,54,19,148,7,'Chvalte Hospodina tvorové zemští, velrybové a všecky propasti,'),
(1562639,54,19,148,8,'Oheň a krupobití, sníh i pára, vítr bouřlivý, vykonávající rozkaz jeho,'),
(1562640,54,19,148,9,'I hory a všickni pahrbkové, stromoví ovoce nesoucí, i všickni cedrové,'),
(1562641,54,19,148,10,'Zvěř divoká i všeliká hovada, zeměplazové i ptactvo létavé,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562642,54,19,148,11,'Králové zemští i všickni národové, knížata i všickni soudcové země,'),
(1562643,54,19,148,12,'Mládenci, též i panny, starci s dítkami,'),
(1562644,54,19,148,13,'Chvalte jméno Hospodinovo; nebo vyvýšeno jest jméno jeho samého, a sláva jeho nade všecku zemi i nebe.'),
(1562645,54,19,148,14,'A vyzdvihl roh lidu svého, chválu všech svatých jeho, synů Izraelských, lidu s ním spojeného. Halelujah.'),
(1562646,54,19,149,1,'Halelujah. Zpívejte Hospodinu píseň novou, chválu jeho v shromáždění svatých.'),
(1562647,54,19,149,2,'Vesel se Izrael v tom, kterýž ho učinil, synové Sionští plésejte v králi svém.'),
(1562648,54,19,149,3,'Chvalte jméno jeho na píšťalu, na buben a na citaru prozpěvujte jemu.'),
(1562649,54,19,149,4,'Nebo zalíbilo se Hospodinu v lidu jeho; onť ozdobuje pokorné spasením.'),
(1562650,54,19,149,5,'Plésati budou svatí v Boží slávě, a zpívati v pokojích svých.'),
(1562651,54,19,149,6,'Oslavování Boha silného bude ve rtech jejich, a meč na obě straně ostrý v rukou jejich,'),
(1562652,54,19,149,7,'K vykonávání pomsty nad pohany, a k strestání národů,'),
(1562653,54,19,149,8,'K svazování králů jejich řetězy, a šlechticů jejich pouty železnými,'),
(1562654,54,19,149,9,'K nakládání s nimi podlé práva zapsaného, k slávě všechněm svatým jeho. Halelujah.'),
(1562655,54,19,150,1,'Halelujah. Chvalte Boha silného pro svatost jeho, chvalte jej pro rozšíření síly jeho.'),
(1562656,54,19,150,2,'Chvalte jej ze všelijaké moci jeho, chvalte jej podlé veliké důstojnosti jeho.'),
(1562657,54,19,150,3,'Chvalte jej zvukem trouby, chvalte jej na loutnu a citaru.'),
(1562658,54,19,150,4,'Chvalte jej na buben a píšťalu, chvalte jej na husle a varhany.'),
(1562659,54,19,150,5,'Chvalte jej na cymbály hlasité, chvalte jej na cymbály zvučné.'),
(1562660,54,19,150,6,'Všeliký duch chval Hospodina. Halelujah.'),
(1562661,54,20,1,1,'Přísloví Šalomouna syna Davidova, krále Izraelského,'),
(1562662,54,20,1,2,'Ku poznání moudrosti a cvičení, k vyrozumívání řečem rozumnosti,'),
(1562663,54,20,1,3,'K dosažení vycvičení v opatrnosti, spravedlnosti, soudu a toho, což pravého jest,'),
(1562664,54,20,1,4,'Aby dána byla hloupým důmyslnost, mládenečku umění a prozřetelnost.'),
(1562665,54,20,1,5,'Když poslouchati bude moudrý, přibude mu umění, a rozumný bude vtipnější,'),
(1562666,54,20,1,6,'K srozumění podobenství, a výmluvnosti řeči moudrých a pohádkám jejich.'),
(1562667,54,20,1,7,'Bázeň Hospodinova jest počátek umění, moudrostí a cvičením pohrdají blázni.'),
(1562668,54,20,1,8,'Poslouchej, synu můj, cvičení otce svého, a neopouštěj naučení matky své.'),
(1562669,54,20,1,9,'Neboť to přidá příjemnosti hlavě tvé, a bude zlatým řetězem hrdlu tvému.'),
(1562670,54,20,1,10,'Synu můj, jestliže by tě namlouvali hříšníci, nepřivoluj.'),
(1562671,54,20,1,11,'Jestliže by řekli: Poď s námi, úklady čiňme krvi, skryjeme se proti nevinnému bez ostýchání se;'),
(1562672,54,20,1,12,'Sehltíme je jako hrob za živa, a v cele jako ty, jenž sstupují do jámy;'),
(1562673,54,20,1,13,'Všelijakého drahého zboží dosáhneme, naplníme domy své loupeží;'),
(1562674,54,20,1,14,'Vrz los svůj mezi nás, měšec jeden budeme míti všickni:'),
(1562675,54,20,1,15,'Synu můj, nevycházej na cestu s nimi, zdrž nohu svou od stezky jejich;'),
(1562676,54,20,1,16,'Nebo nohy jejich ke zlému běží, a pospíchají k vylévání krve.'),
(1562677,54,20,1,17,'Jistě, že jakož nadarmo roztažena bývá sít před očima jakéhokoli ptactva,'),
(1562678,54,20,1,18,'Tak tito proti krvi své ukládají, skrývají se proti dušem svým.'),
(1562679,54,20,1,19,'Takovéť jsou cesty každého dychtícího po zisku, duši pána svého uchvacuje.'),
(1562680,54,20,1,20,'Moudrost vně volá, na ulicech vydává hlas svůj.'),
(1562681,54,20,1,21,'V největším hluku volá, u vrat brány, v městě, a výmluvnosti své vypravuje, řka:'),
(1562682,54,20,1,22,'Až dokud hloupí milovati budete hloupost, a posměvači posměch sobě libovati, a blázni nenáviděti umění?'),
(1562683,54,20,1,23,'Obraťtež se k domlouvání mému. Hle, vynáším vám ducha svého, a v známost vám uvodím slova svá.'),
(1562684,54,20,1,24,'Poněvadž jsem volala, a odpírali jste; vztahovala jsem ruku svou, a nebyl, kdo by pozoroval,'),
(1562685,54,20,1,25,'Anobrž strhli jste se všeliké rady mé, a trestání mého jste neoblíbili:'),
(1562686,54,20,1,26,'Pročež i já v bídě vaší smáti se budu, posmívati se budu, když přijde to, čehož se bojíte,'),
(1562687,54,20,1,27,'Když přijde jako hrozné zpuštění to, čehož se bojíte, a bída vaše jako bouře nastane, když přijde na vás trápení a ssoužení.'),
(1562688,54,20,1,28,'Tehdy volati budou ke mně, a nevyslyším; ráno hledati mne budou, a nenaleznou mne.'),
(1562689,54,20,1,29,'Proto že nenáviděli umění, a bázně Hospodinovy nevyvolili,'),
(1562690,54,20,1,30,'Aniž povolili radě mé, ale pohrdali všelikým domlouváním mým.'),
(1562691,54,20,1,31,'Protož jísti budou ovoce skutků svých, a radami svými nasyceni budou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562692,54,20,1,32,'Nebo pokoj hloupých zmorduje je, a štěstí bláznů zahubí je.'),
(1562693,54,20,1,33,'Ale kdož mne poslouchá, bydliti bude bezpečně, pokoj maje před strachem zlých věcí.'),
(1562694,54,20,2,1,'Synu můj, přijmeš-li slova má, a přikázaní má schováš-li u sebe;'),
(1562695,54,20,2,2,'Nastavíš-li moudrosti ucha svého, a nakloníš-li srdce svého k opatrnosti;'),
(1562696,54,20,2,3,'Ovšem, jestliže na rozumnost zavoláš, a na opatrnost zvoláš-li;'),
(1562697,54,20,2,4,'Budeš-li jí hledati jako stříbra, a jako pokladů pilně vyhledávati jí:'),
(1562698,54,20,2,5,'Tehdy porozumíš bázni Hospodinově, a známosti Boží nabudeš;'),
(1562699,54,20,2,6,'Nebo Hospodin dává moudrost, z úst jeho umění a opatrnost.'),
(1562700,54,20,2,7,'Chová upřímým dlouhověkosti, pavézou jest chodícím v sprostnosti,'),
(1562701,54,20,2,8,'Ostříhaje stezek soudu; on cesty svatých svých ostříhá.'),
(1562702,54,20,2,9,'Tehdy porozumíš spravedlnosti a soudu, a upřímosti i všeliké cestě dobré,'),
(1562703,54,20,2,10,'Když vejde moudrost v srdce tvé, a umění duši tvé se zalíbí.'),
(1562704,54,20,2,11,'Prozřetelnost ostříhati bude tebe, a opatrnost zachová tě,'),
(1562705,54,20,2,12,'Vysvobozujíc tě od cesty zlé, a od lidí mluvících věci převrácené,'),
(1562706,54,20,2,13,'Kteříž opouštějí stezky přímé, aby chodili po cestách tmavých,'),
(1562707,54,20,2,14,'Kteříž se veselí ze zlého činění, plésají v převrácenostech nejhorších,'),
(1562708,54,20,2,15,'Jejichž stezky křivolaké jsou, anobrž zmotaní jsou na cestách svých;'),
(1562709,54,20,2,16,'Vysvobozujíc tě i od ženy postranní, od cizí, kteráž řečmi svými lahodí,'),
(1562710,54,20,2,17,'Kteráž opouští vůdce mladosti své, a na smlouvu Boha svého se zapomíná;'),
(1562711,54,20,2,18,'K smrti se zajisté nachyluje dům její, a k mrtvým stezky její;'),
(1562712,54,20,2,19,'Kteřížkoli vcházejí k ní, nenavracují se zase, aniž trefují na cestu života;'),
(1562713,54,20,2,20,'Abys chodil po cestě dobrých, a stezek spravedlivých abys ostříhal.'),
(1562714,54,20,2,21,'Nebo upřímí bydliti budou v zemi, a pobožní zůstanou v ní;'),
(1562715,54,20,2,22,'Bezbožní pak z země vyťati budou, a přestupníci vykořeněni budou z ní.'),
(1562716,54,20,3,1,'Synu můj, na učení mé nezapomínej, ale přikázaní mých nechať ostříhá srdce tvé.'),
(1562717,54,20,3,2,'Dlouhosti zajisté dnů, i let života i pokoje přidadí tobě.'),
(1562718,54,20,3,3,'Milosrdenství a pravda nechť neopouštějí tě, přivaž je k hrdlu svému, napiš je na tabuli srdce svého,'),
(1562719,54,20,3,4,'A nalezneš milost a prospěch výborný před Bohem i lidmi.'),
(1562720,54,20,3,5,'Doufej v Hospodina celým srdcem svým, na rozumnost pak svou nezpoléhej.'),
(1562721,54,20,3,6,'Na všech cestách svých snažuj se jej poznávati, a onť spravovati bude stezky tvé.'),
(1562722,54,20,3,7,'Nebývej moudrý sám u sebe; boj se Hospodina, a odstup od zlého.'),
(1562723,54,20,3,8,'Toť bude zdraví životu tvému, a rozvlažení kostem tvým.'),
(1562724,54,20,3,9,'Cti Hospodina z statku svého, a z nejpřednějších věcí všech úrod svých,'),
(1562725,54,20,3,10,'A naplněny budou stodoly tvé hojností, a presové tvoji mstem oplývati budou.'),
(1562726,54,20,3,11,'Kázně Hospodinovy, synu můj, nezamítej, aniž sobě oškliv domlouvání jeho.'),
(1562727,54,20,3,12,'Nebo kohož miluje Hospodin, tresce, a to jako otec syna, jejž libuje.'),
(1562728,54,20,3,13,'Blahoslavený člověk nalézající moudrost, a člověk vynášející opatrnost.'),
(1562729,54,20,3,14,'Lépeť jest zajisté těžeti jí, nežli těžeti stříbrem, anobrž nad výborné zlato užitek její.'),
(1562730,54,20,3,15,'Dražší jest než drahé kamení, a všecky nejžádostivější věci tvé nevrovnají se jí.'),
(1562731,54,20,3,16,'Dlouhost dnů v pravici její, a v levici její bohatství a sláva.'),
(1562732,54,20,3,17,'Cesty její cesty utěšené, a všecky stezky její pokojné.'),
(1562733,54,20,3,18,'Stromem života jest těm, kteříž jí dosahují, a kteříž ji mají, blahoslavení jsou.'),
(1562734,54,20,3,19,'Hospodin moudrostí založil zemi, utvrdil nebesa opatrností.'),
(1562735,54,20,3,20,'Uměním jeho propasti protrhují se, a oblakové vydávají rosu.'),
(1562736,54,20,3,21,'Synu můj, nechť neodcházejí ty věci od očí tvých, ostříhej zdravého naučení a prozřetelnosti.'),
(1562737,54,20,3,22,'I budeť to životem duši tvé, a ozdobou hrdlu tvému.'),
(1562738,54,20,3,23,'Tehdy choditi budeš bezpečně cestou svou, a v nohu svou neurazíš se.'),
(1562739,54,20,3,24,'Když lehneš, nebudeš se strašiti, ale odpočívati budeš, a bude libý sen tvůj.'),
(1562740,54,20,3,25,'Nelekneš se strachu náhlého, ani zpuštění bezbožníků, když přijde.'),
(1562741,54,20,3,26,'Nebo Hospodin bude doufání tvé, a ostříhati bude nohy tvé, abys nebyl lapen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562742,54,20,3,27,'Nezadržuj dobrodiní potřebujícím, když s to býti můžeš, abys je činil.'),
(1562743,54,20,3,28,'Neříkej bližnímu svému: Odejdi, potom navrať se, a zítrať dám, maje to u sebe.'),
(1562744,54,20,3,29,'Neukládej proti bližnímu svému zlého, kterýž s tebou dověrně bydlí.'),
(1562745,54,20,3,30,'Nevaď se s člověkem bez příčiny, jestližeť neučinil zlého.'),
(1562746,54,20,3,31,'Nechtěj záviděti muži dráči, aniž zvoluj které cesty jeho.'),
(1562747,54,20,3,32,'Nebo ohavností jest Hospodinu převrácenec, ale s upřímými tajemství jeho.'),
(1562748,54,20,3,33,'Zlořečení Hospodinovo jest v domě bezbožníka, ale příbytku spravedlivých žehná:'),
(1562749,54,20,3,34,'Poněvadž posměvačům on se posmívá, pokorným pak dává milost.'),
(1562750,54,20,3,35,'Slávu moudří dědičně obdrží, ale blázny hubí pohanění.'),
(1562751,54,20,4,1,'Poslouchejte, synové, učení otcova, a pozorujte, abyste poznali rozumnost.'),
(1562752,54,20,4,2,'Nebo naučení dobré dávám vám, neopouštějtež zákona mého.'),
(1562753,54,20,4,3,'Když jsem byl syn u otce svého mladičký, a jediný při matce své,'),
(1562754,54,20,4,4,'On vyučoval mne a říkal mi: Ať se chopí výmluvností mých srdce tvé, ostříhej přikázaní mých, a živ budeš.'),
(1562755,54,20,4,5,'Nabuď moudrosti, nabuď rozumnosti; nezapomínej, ani se uchyluj od řečí úst mých.'),
(1562756,54,20,4,6,'Neopouštějž jí, a bude tě ostříhati; miluj ji, a zachová tě.'),
(1562757,54,20,4,7,'Předně moudrosti, moudrosti nabývej, a za všecko jmění své zjednej rozumnost.'),
(1562758,54,20,4,8,'Vyvyšuj ji, a zvýšíť tě; poctí tě, když ji přijmeš.'),
(1562759,54,20,4,9,'Přidá hlavě tvé příjemnosti, korunou krásnou obdaří tě.'),
(1562760,54,20,4,10,'Slyš, synu můj, a přijmi řeči mé, a tak rozmnoží se léta života tvého.'),
(1562761,54,20,4,11,'Cestě moudrosti učím tě, vedu tě stezkami přímými.'),
(1562762,54,20,4,12,'Když choditi budeš, nebude ssoužen krok tvůj, a poběhneš-li, neustrčíš se.'),
(1562763,54,20,4,13,'Chopiž se učení, nepouštěj, ostříhej ho, nebo ono jest život tvůj.'),
(1562764,54,20,4,14,'Na stezku bezbožných nevcházej, a nekráčej cestou zlostníků.'),
(1562765,54,20,4,15,'Opusť ji, nechoď po ní, uchyl se od ní, a pomiň jí.'),
(1562766,54,20,4,16,'Neboť nespí, leč zlost provedou; anobrž zahánín bývá sen jejich, dokudž ku pádu nepřivodí,'),
(1562767,54,20,4,17,'Proto že jedí chléb bezbožnosti, a víno loupeží pijí.'),
(1562768,54,20,4,18,'Ale stezka spravedlivých jako světlo jasné, kteréž rozmáhá se, a svítí až do pravého dne.'),
(1562769,54,20,4,19,'Cesta pak bezbožných jako mrákota; nevědí, na čem se ustrčiti mohou.'),
(1562770,54,20,4,20,'Synu můj, slov mých pozoruj, k řečem mým nakloň ucha svého.'),
(1562771,54,20,4,21,'Nechať neodcházejí od očí tvých, ostříhej jich u prostřed srdce svého.'),
(1562772,54,20,4,22,'Nebo životem jsou těm, kteříž je nalézají, i všemu tělu jejich lékařstvím.'),
(1562773,54,20,4,23,'Přede vším, čehož se stříci sluší, ostříhej srdce svého, nebo z něho pochází život.'),
(1562774,54,20,4,24,'Odlož od sebe převrácenost úst, a zlost rtů vzdal od sebe.'),
(1562775,54,20,4,25,'Oči tvé ať k dobrým věcem patří, a víčka tvá ať přímě hledí před tebou.'),
(1562776,54,20,4,26,'Zvaž stezku noh svých, a všecky cesty tvé ať jsou spraveny.'),
(1562777,54,20,4,27,'Neuchyluj se na pravo ani na levo, odvrať nohu svou od zlého.'),
(1562778,54,20,5,1,'Synu můj, pozoruj moudrosti mé, k opatrnosti mé nakloň ucha svého,'),
(1562779,54,20,5,2,'Abys ostříhal prozřetelnosti, a rtové tvoji šetřili umění.'),
(1562780,54,20,5,3,'Nebo rtové cizí ženy strdí tekou, a měkčejší nad olej ústa její.'),
(1562781,54,20,5,4,'Poslední pak věci její hořké jsou jako pelyněk, ostré jako meč na obě straně ostrý.'),
(1562782,54,20,5,5,'Nohy její sstupují k smrti, krokové její hrob uchvacují.'),
(1562783,54,20,5,6,'Stezku života snad bys zvážiti chtěl? Vrtkéť jsou cesty její, neseznáš.'),
(1562784,54,20,5,7,'Protož, synové, poslechněte mne, a neodstupujte od řečí úst mých.'),
(1562785,54,20,5,8,'Vzdal od ní cestu svou, a nepřibližuj se ke dveřím domu jejího,'),
(1562786,54,20,5,9,'Abys snad nedal jiným slávy své, a let svých ukrutnému,'),
(1562787,54,20,5,10,'Aby se nenasytili cizí úsilím tvým, a práce tvá nezůstala v domě cizím.'),
(1562788,54,20,5,11,'I řval bys naposledy, když bys zhubil tělo své a čerstvost svou,'),
(1562789,54,20,5,12,'A řekl bys: Jak jsem nenáviděl cvičení, a domlouváním pohrdalo srdce mé,'),
(1562790,54,20,5,13,'A neposlouchal jsem hlasu vyučujících mne, a k učitelům svým nenaklonil jsem ucha svého!'),
(1562791,54,20,5,14,'O málo, že jsem nevlezl ve všecko zlé u prostřed shromáždění a zástupu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562792,54,20,5,15,'Pí vodu z čisterny své, a prameny z prostředku vrchoviště svého.'),
(1562793,54,20,5,16,'Nechť se rozlévají studnice tvé ven, a potůčkové vod na ulice.'),
(1562794,54,20,5,17,'Měj je sám sobě, a ne cizí s tebou.'),
(1562795,54,20,5,18,'Budiž požehnaný pramen tvůj, a vesel se z manželky mladosti své.'),
(1562796,54,20,5,19,'Laně milostné a srny utěšené; prsy její ať tě opojují všelikého času, v milování jejím kochej se ustavičně.'),
(1562797,54,20,5,20,'Nebo proč bys se kochal, synu můj, v cizí, a objímal život postranní,'),
(1562798,54,20,5,21,'Poněvadž před očima Hospodinovýma jsou cesty člověka, a on všecky stezky jeho váží?'),
(1562799,54,20,5,22,'Nepravosti vlastní jímají bezbožníka takového, a v provazích hříchu svého uvázne.'),
(1562800,54,20,5,23,'Takovýť umře, proto že nepřijímal cvičení, a ve množství bláznovství svého blouditi bude.'),
(1562801,54,20,6,1,'Synu můj, slíbil-lis za přítele svého, podal-lis cizímu ruky své,'),
(1562802,54,20,6,2,'Zapleten jsi slovy úst svých, jat jsi řečmi úst svých.'),
(1562803,54,20,6,3,'Učiniž tedy toto, synu můj, a vyprosť se, poněvadžs se dostal v ruku přítele svého. Jdi, pokoř se, a probuď přítele svého.'),
(1562804,54,20,6,4,'Nedej usnouti očím svým, a zdřímati víčkám svým.'),
(1562805,54,20,6,5,'Vydři se jako srna z ruky, a jako pták z ruky čižebníka.'),
(1562806,54,20,6,6,'Jdi k mravenci, lenochu, shlédni cesty jeho, a nabuď moudrosti.'),
(1562807,54,20,6,7,'Kterýž nemaje vůdce, ani správce, ani pána,'),
(1562808,54,20,6,8,'Připravuje v létě pokrm svůj, shromažďuje ve žni potravu svou.'),
(1562809,54,20,6,9,'Dokudž lenochu ležeti budeš? Skoro-liž vstaneš ze sna svého?'),
(1562810,54,20,6,10,'Maličko pospíš, maličko zdřímeš, maličko složíš ruce, abys poležel,'),
(1562811,54,20,6,11,'V tom přijde jako pocestný chudoba tvá, a nouze tvá jako muž zbrojný.'),
(1562812,54,20,6,12,'Člověk nešlechetný, muž nepravý chodí v převrácenosti úst.'),
(1562813,54,20,6,13,'Mhourá očima svýma, mluví nohama svýma, ukazuje prsty svými.'),
(1562814,54,20,6,14,'Převrácenost všeliká jest v srdci jeho, smýšlí zlé všelikého času, sváry rozsívá.'),
(1562815,54,20,6,15,'A protož v náhle přijde bída jeho, rychle setřín bude, a nebudeť uléčení.'),
(1562816,54,20,6,16,'Těchto šesti věcí nenávidí Hospodin, a sedmá ohavností jest duši jeho:'),
(1562817,54,20,6,17,'Očí vysokých, jazyka lživého, a rukou vylévajících krev nevinnou,'),
(1562818,54,20,6,18,'Srdce, kteréž ukládá myšlení nepravá, noh kvapných běžeti ke zlému,'),
(1562819,54,20,6,19,'Svědka lživého, mluvícího lež, a toho, jenž rozsívá různice mezi bratřími.'),
(1562820,54,20,6,20,'Ostříhejž, synu můj, přikázaní otce svého, a neopouštěj naučení matky své.'),
(1562821,54,20,6,21,'Přivazuj je k srdci svému ustavičně, a k hrdlu svému je připínej.'),
(1562822,54,20,6,22,'Kamžkoli půjdeš, ono tě zprovodí, když spáti budeš, bude tě ostříhati, a když procítíš, bude s tebou rozmlouvati,'),
(1562823,54,20,6,23,'(Nebo přikázaní jest svíce, a naučení světlo, a cesta života jsou domlouvání vyučující),'),
(1562824,54,20,6,24,'Aby tě ostříhalo od ženy zlé, od úlisnosti jazyka ženy cizí.'),
(1562825,54,20,6,25,'Nežádejž krásy její v srdci svém, a nechať tě nejímá víčky svými.'),
(1562826,54,20,6,26,'Nebo příčinou ženy cizoložné zchudl bys až do kusu chleba, anobrž žena cizoložná drahou duši ulovuje.'),
(1562827,54,20,6,27,'Může-liž kdo skrýti oheň v klíně svém, aby roucho jeho se nepropálilo?'),
(1562828,54,20,6,28,'Může-liž kdo choditi po uhlí řeřavém, aby nohy jeho se neopálily?'),
(1562829,54,20,6,29,'Tak kdož vchází k ženě bližního svého, nebudeť bez viny, kdož by se jí koli dotkl.'),
(1562830,54,20,6,30,'Neuvozují potupy na zloděje, jestliže by ukradl, aby nasytil život svůj, když lační,'),
(1562831,54,20,6,31,'Ač postižen jsa, navracuje to sedmernásobně, vším statkem domu svého nahražuje:'),
(1562832,54,20,6,32,'Ale cizoložící s ženou blázen jest; kdož hubí duši svou, tenť to činí;'),
(1562833,54,20,6,33,'Trápení a lehkosti dochází, a útržka jeho nebývá shlazena.'),
(1562834,54,20,6,34,'Nebo zůřivý jest hněv muže, a neodpouštíť v den pomsty.'),
(1562835,54,20,6,35,'Neohlídá se na žádnou záplatu, aniž přijímá, by i množství darů dával.'),
(1562836,54,20,7,1,'Synu můj, ostříhej řečí mých, a přikázaní má schovej u sebe.'),
(1562837,54,20,7,2,'Ostříhej přikázaní mých, a živ budeš, a naučení mého jako zřítelnice očí svých.'),
(1562838,54,20,7,3,'Přivaž je na prsty své, napiš je na tabuli srdce svého.'),
(1562839,54,20,7,4,'Rci moudrosti: Sestra má jsi ty, a rozumnost přítelkyní jmenuj,'),
(1562840,54,20,7,5,'Aby tě ostříhala od ženy cizí, od postranní, jenž řečmi svými lahodí.'),
(1562841,54,20,7,6,'Nebo z okna domu svého okénkem vyhlédaje,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562842,54,20,7,7,'Viděl jsem mezi hloupými, spatřil jsem mezi mládeží mládence bláznivého.'),
(1562843,54,20,7,8,'Kterýž šel po ulici vedlé úhlu jejího, a cestou k domu jejímu kráčel,'),
(1562844,54,20,7,9,'V soumrak, u večer dne, ve tmách nočních a v mrákotě.'),
(1562845,54,20,7,10,'A aj, žena potkala ho v ozdobě nevěstčí a chytrého srdce,'),
(1562846,54,20,7,11,'Štěbetná a opovážlivá, v domě jejím nezůstávají nohy její,'),
(1562847,54,20,7,12,'Jednak vně, jednak na ulici u každého úhlu úklady činící.'),
(1562848,54,20,7,13,'I chopila jej, a políbila ho, a opovrhši stud, řekla jemu:'),
(1562849,54,20,7,14,'Oběti pokojné jsou u mne, dnes splnila jsem slib svůj.'),
(1562850,54,20,7,15,'Protož vyšla jsem vstříc tobě, abych pilně hledala tváři tvé, i nalezla jsem tě.'),
(1562851,54,20,7,16,'Koberci jsem obestřela lůže své, s řezbami a prostěradly Egyptskými,'),
(1562852,54,20,7,17,'Vykadila jsem pokojík svůj mirrou a aloe a skořicí.'),
(1562853,54,20,7,18,'Poď, opojujme se milostí až do jitra, obveselíme se v milosti.'),
(1562854,54,20,7,19,'Nebo není muže doma, odšel na cestu dalekou.'),
(1562855,54,20,7,20,'Pytlík peněz vzal s sebou, v jistý den vrátí se do domu svého.'),
(1562856,54,20,7,21,'I naklonila ho mnohými řečmi svými, a lahodností rtů svých přinutila jej.'),
(1562857,54,20,7,22,'Šel za ní hned, jako vůl k zabití chodívá, a jako blázen v pouta, jimiž by trestán byl.'),
(1562858,54,20,7,23,'Dokudž nepronikla střela jater jeho, pospíchal jako pták k osídlu, nevěda, že ono bezživotí jeho jest.'),
(1562859,54,20,7,24,'Protož nyní, synové, slyšte mne, a pozorujte řečí úst mých.'),
(1562860,54,20,7,25,'Neuchyluj se k cestám jejím srdce tvé, aniž se toulej po stezkách jejích.'),
(1562861,54,20,7,26,'Nebo mnohé zranivši, porazila, a silní všickni zmordováni jsou od ní.'),
(1562862,54,20,7,27,'Cesty pekelné dům její, vedoucí do skrýší smrti.'),
(1562863,54,20,8,1,'Zdaliž moudrost nevolá, a rozumnost nevydává hlasu svého?'),
(1562864,54,20,8,2,'Na vrchu vysokých míst, u cesty, na rozcestí stojí,'),
(1562865,54,20,8,3,'U bran, kudy se chodí do města, a kudy se chodí dveřmi, volá, řkuci:'),
(1562866,54,20,8,4,'Na vásť, ó muži, volám, a hlas můj jest k synům lidským.'),
(1562867,54,20,8,5,'Poučte se hloupí opatrnosti, a blázni srozumějte srdcem.'),
(1562868,54,20,8,6,'Poslouchejtež, nebo znamenité věci mluviti budu, a otevření rtů mých pouhou pravdu.'),
(1562869,54,20,8,7,'Jistě žeť pravdu zvěstují ústa má, a ohavností jest rtům mým bezbožnost.'),
(1562870,54,20,8,8,'Spravedlivé jsou všecky řeči úst mých, není v nich nic křivého ani převráceného.'),
(1562871,54,20,8,9,'Všecky pravé jsou rozumějícímu, a přímé těm, kteříž nalézají umění.'),
(1562872,54,20,8,10,'Přijmětež cvičení mé raději než stříbro, a umění raději než zlato nejvýbornější.'),
(1562873,54,20,8,11,'Nebo lepší jest moudrost než drahé kamení, tak že jakékoli věci žádostivé vrovnati se jí nemohou.'),
(1562874,54,20,8,12,'Já moudrost bydlím s opatrností, a umění pravé prozřetelnosti přítomné mám.'),
(1562875,54,20,8,13,'Bázeň Hospodinova jest v nenávisti míti zlé, pýchy a vysokomyslnosti, i cesty zlé a úst převrácených nenávidím.'),
(1562876,54,20,8,14,'Má jest rada i šťastný prospěch, jáť jsem rozumnost, a má jest síla.'),
(1562877,54,20,8,15,'Skrze mne králové kralují, a knížata ustanovují věci spravedlivé.'),
(1562878,54,20,8,16,'Skrze mne knížata panují, páni i všickni soudcové zemští.'),
(1562879,54,20,8,17,'Já milující mne miluji, a kteříž mne pilně hledají, nalézají mne.'),
(1562880,54,20,8,18,'Bohatství a sláva při mně jest, zboží trvánlivé i spravedlnost.'),
(1562881,54,20,8,19,'Lepší jest ovoce mé než nejlepší zlato, i než ryzí, a užitek můj než stříbro výborné.'),
(1562882,54,20,8,20,'Stezkou spravedlnosti vodím, prostředkem stezek soudu,'),
(1562883,54,20,8,21,'Abych těm, kteříž mne milují, přidědila zboží věčné, a poklady jejich naplnila.'),
(1562884,54,20,8,22,'Hospodin měl mne při počátku cesty své, před skutky svými, přede všemi časy.'),
(1562885,54,20,8,23,'Před věky ustanovena jsem, před počátkem, prvé než byla země.'),
(1562886,54,20,8,24,'Když ještě nebylo propasti, zplozena jsem, když ještě nebylo studnic oplývajících vodami.'),
(1562887,54,20,8,25,'Prvé než hory založeny byly, než byli pahrbkové, zplozena jsem;'),
(1562888,54,20,8,26,'Ještě byl neučinil země a rovin, ani začátku prachu okršlku zemského.'),
(1562889,54,20,8,27,'Když připravoval nebesa, byla jsem tu, když vyměřoval okrouhlost nad propastí;'),
(1562890,54,20,8,28,'Když upevňoval oblaky u výsosti, když utvrzoval studnice propasti;'),
(1562891,54,20,8,29,'Když ukládal moři cíl jeho, a vodám, aby nepřestupovaly rozkázaní jeho, když vyměřoval základy země:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562892,54,20,8,30,'Tehdáž byla jsem od něho pěstována, a byla jsem jeho potěšení na každý den, anobrž hrám před ním každého času;'),
(1562893,54,20,8,31,'Hrám i na okršlku země jeho, a rozkoše mé s syny lidskými.'),
(1562894,54,20,8,32,'A tak tedy, synové, poslechněte mne, nebo blahoslavení jsou ostříhající cest mých.'),
(1562895,54,20,8,33,'Poslouchejte cvičení, a nabuďte rozumu, a nerozpakujte se.'),
(1562896,54,20,8,34,'Blahoslavený člověk, kterýž mne slýchá, bdě u dveří mých na každý den, šetře veřejí dveří mých.'),
(1562897,54,20,8,35,'Nebo kdož mne nalézá, nalézá život, a dosahuje lásky od Hospodina.'),
(1562898,54,20,8,36,'Ale kdož hřeší proti mně, ukrutenství provodí nad duší svou; všickni, kteříž mne nenávidí, milují smrt.'),
(1562899,54,20,9,1,'Moudrost vystavěla dům svůj, vytesavši sloupů svých sedm.'),
(1562900,54,20,9,2,'Zbila dobytek svůj, smísila víno své, stůl také svůj připravila.'),
(1562901,54,20,9,3,'A poslavši děvečky své, volá na vrchu nejvyšších míst v městě:'),
(1562902,54,20,9,4,'Kdožkoli jest hloupý, uchyl se sem. Až i bláznivým říká:'),
(1562903,54,20,9,5,'Poďte, jezte chléb můj, a píte víno, kteréž jsem smísila.'),
(1562904,54,20,9,6,'Opusťte hloupost a živi buďte, a choďte cestou rozumnosti.'),
(1562905,54,20,9,7,'Kdo tresce posměvače, dochází hanby, a kdo přimlouvá bezbožnému, pohanění.'),
(1562906,54,20,9,8,'Nedomlouvej posměvači, aby tě nevzal v nenávist; přimlouvej moudrému, a bude tě milovati.'),
(1562907,54,20,9,9,'Učiň to moudrému, a bude moudřejší; pouč spravedlivého, a bude umělejší.'),
(1562908,54,20,9,10,'Počátek moudrosti jest bázeň Hospodinova, a umění svatých rozumnost.'),
(1562909,54,20,9,11,'Nebo skrze mne rozmnoží se dnové tvoji, a přidánoť bude let života.'),
(1562910,54,20,9,12,'Budeš-li moudrý, sobě moudrý budeš; pakli posměvač, sám vytrpíš.'),
(1562911,54,20,9,13,'Žena bláznivá štěbetná, nesmyslná, a nic neumí.'),
(1562912,54,20,9,14,'A sedí u dveří domu svého na stolici, na místech vysokých v městě,'),
(1562913,54,20,9,15,'Aby volala jdoucích cestou, kteříž přímo jdou stezkami svými, řkuci:'),
(1562914,54,20,9,16,'Kdo jest hloupý, uchyl se sem. A bláznivému říká:'),
(1562915,54,20,9,17,'Voda kradená sladší jest, a chléb pokoutní chutnější.'),
(1562916,54,20,9,18,'Ale neví hlupec, že mrtví jsou tam, a v hlubokém hrobě ti, kterýchž pozvala.'),
(1562917,54,20,10,1,'Syn moudrý obveseluje otce, ale syn bláznivý zámutkem jest matce své.'),
(1562918,54,20,10,2,'Neprospívají pokladové bezbožně nabytí, ale spravedlnost vytrhuje od smrti.'),
(1562919,54,20,10,3,'Nedopustí lačněti Hospodin duši spravedlivého, statek pak bezbožných rozptýlí.'),
(1562920,54,20,10,4,'K nouzi přivodí ruka lstivá, ruka pak pracovitých zbohacuje.'),
(1562921,54,20,10,5,'Kdo shromažďuje v létě, jest syn rozumný; kdož vyspává ve žni, jest syn, kterýž hanbu činí.'),
(1562922,54,20,10,6,'Požehnání jest nad hlavou spravedlivého, ale ústa bezbožných přikrývají ukrutnost.'),
(1562923,54,20,10,7,'Památka spravedlivého požehnaná, ale jméno bezbožných smrdí.'),
(1562924,54,20,10,8,'Moudré srdce přijímá přikázaní, ale blázen od rtů svých padne.'),
(1562925,54,20,10,9,'Kdo chodí upřímě, chodí doufanlivě; kdož pak převrací cesty své, vyjeven bude.'),
(1562926,54,20,10,10,'Kdo mhourá okem, uvodí nesnáz; a kdož jest bláznivých rtů, padne.'),
(1562927,54,20,10,11,'Pramen života jsou ústa spravedlivého, ale ústa bezbožných přikrývají ukrutnost.'),
(1562928,54,20,10,12,'Nenávist vzbuzuje sváry, ale láska přikrývá všecka přestoupení.'),
(1562929,54,20,10,13,'Ve rtech rozumného nalézá se moudrost, ale kyj na hřbetě blázna.'),
(1562930,54,20,10,14,'Moudří skrývají umění, úst pak blázna blízké jest setření.'),
(1562931,54,20,10,15,'Zboží bohatého jest město pevné jeho, ale nouze jest chudých setření.'),
(1562932,54,20,10,16,'Práce spravedlivého jest k životu, nábytek pak bezbožných jest k hříchu.'),
(1562933,54,20,10,17,'Stezkou života jde, kdož přijímá trestání; ale kdož pohrdá domlouváním, bloudí.'),
(1562934,54,20,10,18,'Kdož přikrývá nenávist rty lživými, i kdož uvodí v lehkost, ten blázen jest.'),
(1562935,54,20,10,19,'Mnohé mluvení nebývá bez hříchu, kdož pak zdržuje rty své, opatrný jest.'),
(1562936,54,20,10,20,'Stříbro výborné jest jazyk spravedlivého, ale srdce bezbožných za nic nestojí.'),
(1562937,54,20,10,21,'Rtové spravedlivého pasou mnohé, blázni pak pro bláznovství umírají.'),
(1562938,54,20,10,22,'Požehnání Hospodinovo zbohacuje, a to beze všeho trápení.'),
(1562939,54,20,10,23,'Za žert jest bláznu činiti nešlechetnost, ale muž rozumný moudrosti se drží.'),
(1562940,54,20,10,24,'Čeho se bojí bezbožný, to přichází na něj; ale čehož žádají spravedliví, dává Bůh.'),
(1562941,54,20,10,25,'Jakož pomíjí vichřice, tak nestane bezbožníka, spravedlivý pak jest základ stálý.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562942,54,20,10,26,'Jako ocet zubům, a jako dým očima, tak jest lenivý těm, kteříž jej posílají.'),
(1562943,54,20,10,27,'Bázeň Hospodinova přidává dnů, léta pak bezbožných ukrácena bývají.'),
(1562944,54,20,10,28,'Očekávání spravedlivých jest potěšení, naděje pak bezbožných zahyne.'),
(1562945,54,20,10,29,'Silou jest upřímému cesta Hospodinova, a strachem těm, kteříž činí nepravost.'),
(1562946,54,20,10,30,'Spravedlivý na věky se nepohne, bezbožní pak nebudou bydliti v zemi.'),
(1562947,54,20,10,31,'Ústa spravedlivého vynášejí moudrost, ale jazyk převrácený vyťat bude.'),
(1562948,54,20,10,32,'Rtové spravedlivého znají, což jest Bohu libého, ústa pak bezbožných převrácené věci.'),
(1562949,54,20,11,1,'Váha falešná ohavností jest Hospodinu, ale závaží pravé líbí se jemu.'),
(1562950,54,20,11,2,'Za pýchou přichází zahanbení, ale při pokorných jest moudrost.'),
(1562951,54,20,11,3,'Sprostnost upřímých vodí je, převrácenost pak přestupníků zatracuje je.'),
(1562952,54,20,11,4,'Neprospíváť bohatství v den hněvu, ale spravedlnost vytrhuje z smrti.'),
(1562953,54,20,11,5,'Spravedlnost upřímého spravuje cestu jeho, ale pro bezbožnost svou padá bezbožný.'),
(1562954,54,20,11,6,'Spravedlnost upřímých vytrhuje je, ale přestupníci v zlosti zjímáni bývají.'),
(1562955,54,20,11,7,'Když umírá člověk bezbožný, hyne naděje, i očekávání rekovských činů mizí.'),
(1562956,54,20,11,8,'Spravedlivý z úzkosti bývá vysvobozen, bezbožný pak přichází na místo jeho.'),
(1562957,54,20,11,9,'Pokrytec ústy kazí bližního svého, ale spravedliví uměním vytrženi bývají.'),
(1562958,54,20,11,10,'Z štěstí spravedlivých veselí se město, když pak hynou bezbožní, bývá prozpěvování.'),
(1562959,54,20,11,11,'Požehnáním spravedlivých zvýšeno bývá město, ústy pak bezbožných vyvráceno.'),
(1562960,54,20,11,12,'Pohrdá bližním svým blázen, ale muž rozumný mlčí.'),
(1562961,54,20,11,13,'Utrhač toulaje se, pronáší tajnost, věrný pak člověk tají věc.'),
(1562962,54,20,11,14,'Kdež není dostatečné rady, padá lid, ale spomožení jest ve množství rádců.'),
(1562963,54,20,11,15,'Velmi sobě škodí, kdož slibuje za cizího, ješto ten, kdož nenávidí rukojemství, bezpečen jest.'),
(1562964,54,20,11,16,'Žena šlechetná má čest, a ukrutní mají zboží.'),
(1562965,54,20,11,17,'Člověk účinný dobře činí životu svému, ale ukrutný kormoutí tělo své.'),
(1562966,54,20,11,18,'Bezbožný dělá dílo falešné, ale kdož rozsívá spravedlnost, má mzdu jistou.'),
(1562967,54,20,11,19,'Tak spravedlivý rozsívá k životu, a kdož následuje zlého, k smrti své.'),
(1562968,54,20,11,20,'Ohavností jsou Hospodinu převrácení srdcem, ale ctného obcování líbí se jemu.'),
(1562969,54,20,11,21,'Zlý, by sobě i na pomoc přivzal, neujde pomsty, símě pak spravedlivých uchází toho.'),
(1562970,54,20,11,22,'Zápona zlatá na pysku svině jest žena pěkná bez rozumu.'),
(1562971,54,20,11,23,'Žádost spravedlivých jest toliko dobrých věcí, ale očekávání bezbožných hněv.'),
(1562972,54,20,11,24,'Mnohý rozdává štědře, a však přibývá mu více; jiný skoupě drží nad slušnost, ale k chudobě.'),
(1562973,54,20,11,25,'Člověk štědrý bývá bohatší, a kdož svlažuje, také sám bude zavlažen.'),
(1562974,54,20,11,26,'Kdo zadržuje obilí, zlořečí mu lid; ale požehnání na hlavě toho, kdož je prodává.'),
(1562975,54,20,11,27,'Kdo pilně hledá dobrého, nalézá přízeň; kdož pak hledá zlého, potká jej.'),
(1562976,54,20,11,28,'Kdo doufá v bohatství své, ten spadne, ale spravedliví jako ratolest zkvetnou.'),
(1562977,54,20,11,29,'Kdo kormoutí dům svůj, za dědictví bude míti vítr, a blázen sloužiti musí moudrému.'),
(1562978,54,20,11,30,'Ovoce spravedlivého jest strom života, a kdož vyučuje duše, jest moudrý.'),
(1562979,54,20,11,31,'Aj, spravedlivému na zemi odplacováno bývá, čím více bezbožnému a hříšníku?'),
(1562980,54,20,12,1,'Kdo miluje cvičení, miluje umění; kdož pak nenávidí domlouvání, nemoudrý jest.'),
(1562981,54,20,12,2,'Dobrý nalézá lásku u Hospodina, ale muže nešlechetného potupí Bůh.'),
(1562982,54,20,12,3,'Nebývá trvánlivý člověk v bezbožnosti, kořen pak spravedlivých nepohne se.'),
(1562983,54,20,12,4,'Žena statečná jest koruna muže svého, ale jako hnis v kostech jeho ta, kteráž k hanbě přivodí.'),
(1562984,54,20,12,5,'Myšlení spravedlivých jsou pravá, rady pak bezbožných lstivé.'),
(1562985,54,20,12,6,'Slova bezbožných úklady činí krvi, ústa pak spravedlivých vytrhují je.'),
(1562986,54,20,12,7,'Vyvráceni bývají bezbožní tak, aby jich nebylo, ale dům spravedlivých ostojí.'),
(1562987,54,20,12,8,'Podlé toho, jakž rozumný jest, chválen bývá muž, převráceného pak srdce bude v pohrdání.'),
(1562988,54,20,12,9,'Lepší jest nevzácný, kterýž má služebníka, nežli ten, kterýž sobě slavně počíná, a nemá chleba.'),
(1562989,54,20,12,10,'Pečuje spravedlivý o život hovádka svého, srdce pak bezbožných ukrutné jest.'),
(1562990,54,20,12,11,'Kdo dělá zemi svou, nasycen bývá chlebem; ale kdož následuje zahalečů, blázen jest.'),
(1562991,54,20,12,12,'Žádostiv jest bezbožný obrany proti zlému, ale kořen spravedlivých způsobuje ji.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1562992,54,20,12,13,'Do přestoupení rtů zapletá se zlostník, ale spravedlivý vychází z ssoužení.'),
(1562993,54,20,12,14,'Z ovoce úst každý nasycen bude dobrým, a odplatu za skutky člověka dá jemu Bůh.'),
(1562994,54,20,12,15,'Cesta blázna přímá se zdá jemu, ale kdo poslouchá rady, moudrý jest.'),
(1562995,54,20,12,16,'Hněv blázna v tentýž den poznán bývá, ale opatrný hanbu skrývá.'),
(1562996,54,20,12,17,'Kdož mluví pravdu, ohlašuje spravedlnost, svědek pak falešný lest.'),
(1562997,54,20,12,18,'Někdo vynáší řeči podobné meči probodujícímu, ale jazyk moudrých jest lékařství.'),
(1562998,54,20,12,19,'Rtové pravdomluvní utvrzeni budou na věky, ale na kratičko jazyk lživý.'),
(1562999,54,20,12,20,'V srdci těch, kteříž zlé obmýšlejí, bývá lest, v těch pak, kteříž radí ku pokoji, veselí.'),
(1563000,54,20,12,21,'Nepotká spravedlivého žádná těžkost, bezbožní pak naplněni budou zlým.'),
(1563001,54,20,12,22,'Ohavností jsou Hospodinu rtové lživí, ale ti, jenž činí pravdu, líbí se jemu.'),
(1563002,54,20,12,23,'Člověk opatrný tají umění, ale srdce bláznů vyvolává bláznovství.'),
(1563003,54,20,12,24,'Ruka pracovitých panovati bude, lstivá pak musí dávati plat.'),
(1563004,54,20,12,25,'Starost v srdci člověka snižuje ji, ale věc dobrá obveseluje ji.'),
(1563005,54,20,12,26,'Vzácnější jest nad bližního svého spravedlivý, cesta pak bezbožných svodí je.'),
(1563006,54,20,12,27,'Nebude péci fortelný, což ulovil, ale člověk bedlivý statku drahého nabude.'),
(1563007,54,20,12,28,'Na stezce spravedlnosti jest život, a cesta stezky její nesmrtelná jest.'),
(1563008,54,20,13,1,'Syn moudrý přijímá cvičení otcovo, ale posměvač neposlouchá domlouvání.'),
(1563009,54,20,13,2,'Z ovoce úst každý jísti bude dobré, ale duše převrácených nátisky.'),
(1563010,54,20,13,3,'Kdo ostříhá úst svých, ostříhá duše své; kdo rozdírá rty své, setření na něj přijde.'),
(1563011,54,20,13,4,'Žádá, a nic nemá duše lenivého, duše pak pracovitých zbohatne.'),
(1563012,54,20,13,5,'Slova lživého nenávidí spravedlivý, bezbožníka pak v ošklivost uvodí a zahanbuje.'),
(1563013,54,20,13,6,'Spravedlnost ostříhá přímě chodícího po cestě, bezbožnost pak vyvrací hříšníka.'),
(1563014,54,20,13,7,'Někdo bohatým se dělaje, nemá nic: zase někdo dělaje se chudým, má však statku mnoho.'),
(1563015,54,20,13,8,'Výplata života člověku jest bohatství jeho, ale chudý neslyší domlouvání.'),
(1563016,54,20,13,9,'Světlo spravedlivých rozsvětluje se, svíce pak bezbožných zhasne.'),
(1563017,54,20,13,10,'Samou toliko pýchou působí člověk svár, ale při těch, jenž užívají rady, jest moudrost.'),
(1563018,54,20,13,11,'Statek zle dobytý umenšovati se bude, kdož pak shromažďuje rukou, přivětší ho.'),
(1563019,54,20,13,12,'Očekávání dlouhé zemdlívá srdce, ale žádost splněná jest strom života.'),
(1563020,54,20,13,13,'Kdož pohrdá slovem Božím, sám sobě škodí; ale kdož se bojí přikázaní, odplaceno mu bude.'),
(1563021,54,20,13,14,'Naučení moudrého jest pramen života, k vyhýbání se osídlům smrti.'),
(1563022,54,20,13,15,'Rozum dobrý dává milost, cesta pak převrácených jest tvrdá.'),
(1563023,54,20,13,16,'Každý důmyslný dělá uměle, ale blázen rozprostírá bláznovství.'),
(1563024,54,20,13,17,'Posel bezbožný upadá v neštěstí, jednatel pak věrný jest lékařství.'),
(1563025,54,20,13,18,'Chudoba a lehkost potká toho, jenž se vytahuje z kázně; ale kdož ostříhá naučení, zveleben bude.'),
(1563026,54,20,13,19,'Žádost naplněná sladká jest duši, ale ohavnost jest bláznům odstoupiti od zlého.'),
(1563027,54,20,13,20,'Kdo chodí s moudrými, bude moudrý; ale kdo tovaryší s blázny, setřín bude.'),
(1563028,54,20,13,21,'Hříšníky stihá neštěstí, ale spravedlivým odplatí Bůh dobrým.'),
(1563029,54,20,13,22,'Dobrý zanechává dědictví vnukům, ale zboží hříšného zachováno bývá spravedlivému.'),
(1563030,54,20,13,23,'Hojnost jest pokrmů na rolí chudých, někdo pak hyne skrze nerozšafnost.'),
(1563031,54,20,13,24,'Kdo zdržuje metlu svou, nenávidí syna svého; ale kdož ho miluje, za času jej tresce.'),
(1563032,54,20,13,25,'Spravedlivý jí až do nasycení duše své, břicho pak bezbožných nedostatek trpí.'),
(1563033,54,20,14,1,'Moudrá žena vzdělává dům svůj, bláznice pak rukama svýma boří jej.'),
(1563034,54,20,14,2,'Kdo chodí v upřímnosti své, bojí se Hospodina, ale převrácený v cestách svých pohrdá jím.'),
(1563035,54,20,14,3,'V ústech blázna jest hůl pýchy, rtové pak moudrých ostříhají jich.'),
(1563036,54,20,14,4,'Když není volů, prázdné jsou jesle, ale hojná úroda jest v síle volů.'),
(1563037,54,20,14,5,'Svědek věrný neklamá, ale svědek falešný mluví lež.'),
(1563038,54,20,14,6,'Hledá posměvač moudrosti, a nenalézá, rozumnému pak umění snadné jest.'),
(1563039,54,20,14,7,'Odejdi od muže bláznivého, když neseznáš při něm rtů umění.'),
(1563040,54,20,14,8,'Moudrost opatrného jest, aby rozuměl cestě své, bláznovství pak bláznů ke lsti.'),
(1563041,54,20,14,9,'Blázen přikrývá hřích, ale mezi upřímými dobrá vůle.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563042,54,20,14,10,'Srdce ví o hořkosti duše své, a k veselí jeho nepřimísí se cizí.'),
(1563043,54,20,14,11,'Dům bezbožných vyhlazen bude, ale stánek upřímých zkvetne.'),
(1563044,54,20,14,12,'Cesta zdá se přímá člověku, a však dokonání její jest cesta k smrti.'),
(1563045,54,20,14,13,'Také i v smíchu bolí srdce, a cíl veselí jest zámutek.'),
(1563046,54,20,14,14,'Cestami svými nasytí se převrácený srdcem, ale muž dobrý štítí se jeho.'),
(1563047,54,20,14,15,'Hloupý věří každému slovu, ale opatrný šetří kroku svého.'),
(1563048,54,20,14,16,'Moudrý bojí se a odstupuje od zlého, ale blázen dotře a smělý jest.'),
(1563049,54,20,14,17,'Náhlý se dopouští bláznovství, a muž myšlení zlých v nenávisti bývá.'),
(1563050,54,20,14,18,'Dědičně vládnou hlupci bláznovstvím, ale opatrní bývají korunováni uměním.'),
(1563051,54,20,14,19,'Sklánějí se zlí před dobrými, a bezbožní u bran spravedlivého.'),
(1563052,54,20,14,20,'Také i příteli svému v nenávisti bývá chudý, ale milovníci bohatého mnozí jsou.'),
(1563053,54,20,14,21,'Pohrdá bližním svým hříšník, ale kdož se slitovává nad chudými, blahoslavený jest.'),
(1563054,54,20,14,22,'Zajisté žeť bloudí, kteříž ukládají zlé; ale milosrdenství a pravda těm, kteříž smýšlejí dobré.'),
(1563055,54,20,14,23,'Všeliké práce bývá zisk, ale slovo rtů jest jen k nouzi.'),
(1563056,54,20,14,24,'Koruna moudrých jest bohatství jejich, bláznovství pak bláznivých bláznovstvím.'),
(1563057,54,20,14,25,'Vysvobozuje duše svědek pravdomluvný, ale lstivý mluví lež.'),
(1563058,54,20,14,26,'V bázni Hospodinově jestiť doufání silné, kterýž synům svým útočištěm bude.'),
(1563059,54,20,14,27,'Bázeň Hospodinova jest pramen života, k vyhýbání se osídlům smrti.'),
(1563060,54,20,14,28,'Ve množství lidu jest sláva krále, ale v nedostatku lidu zahynutí vůdce.'),
(1563061,54,20,14,29,'Zpozdilý k hněvu hojně má rozumu,ale náhlý pronáší bláznovství.'),
(1563062,54,20,14,30,'Život těla jest srdce zdravé, ale hnis v kostech jest závist.'),
(1563063,54,20,14,31,'Kdo utiská chudého, útržku činí Učiniteli jeho; ale ctí jej, kdož se slitovává nad chudým.'),
(1563064,54,20,14,32,'Pro zlost svou odstrčen bývá bezbožný, ale naději má i při smrti své spravedlivý.'),
(1563065,54,20,14,33,'V srdci rozumného odpočívá moudrost, co pak jest u vnitřnosti bláznů, nezatají se.'),
(1563066,54,20,14,34,'Spravedlnost zvyšuje národ, ale hřích jest ku pohanění národům.'),
(1563067,54,20,14,35,'Laskav bývá král na služebníka rozumného, ale hněviv na toho, kterýž hanbu činí.'),
(1563068,54,20,15,1,'Odpověd měkká odvracuje hněv, ale řeč zpurná vzbuzuje prchlivost.'),
(1563069,54,20,15,2,'Jazyk moudrých ozdobuje umění, ale ústa bláznů vylévají bláznovství.'),
(1563070,54,20,15,3,'Na všelikém místě oči Hospodinovy spatřují zlé i dobré.'),
(1563071,54,20,15,4,'Zdravý jazyk jest strom života, převrácenost pak z něho ztroskotání od větru.'),
(1563072,54,20,15,5,'Blázen pohrdá cvičením otce svého, ale kdož ostříhá naučení, opatrnosti nabude.'),
(1563073,54,20,15,6,'V domě spravedlivého jest hojnost veliká, ale v úrodě bezbožného zmatek.'),
(1563074,54,20,15,7,'Rtové moudrých rozsívají umění, srdce pak bláznů ne tak.'),
(1563075,54,20,15,8,'Obět bezbožných ohavností jest Hospodinu, ale modlitba upřímých líbí se jemu.'),
(1563076,54,20,15,9,'Ohavností jest Hospodinu cesta bezbožného, toho pak, kdož následuje spravedlnosti, miluje.'),
(1563077,54,20,15,10,'Trestání přísné opouštějícímu cestu, a kdož nenávidí domlouvání, umře.'),
(1563078,54,20,15,11,'Peklo i zatracení jest před Hospodinem, čím více srdce synů lidských?'),
(1563079,54,20,15,12,'Nemiluje posměvač toho, kterýž ho tresce, aniž k moudrým přistoupí.'),
(1563080,54,20,15,13,'Srdce veselé obveseluje tvář, ale pro žalost srdce duch zkormoucen bývá.'),
(1563081,54,20,15,14,'Srdce rozumného hledá umění, ale ústa bláznů pasou se bláznovstvím.'),
(1563082,54,20,15,15,'Všickni dnové chudého zlí jsou, ale dobromyslného hody ustavičné.'),
(1563083,54,20,15,16,'Lepší jest maličko s bázní Hospodinovou než poklad veliký s nepokojem.'),
(1563084,54,20,15,17,'Lepší jest krmě z zelí, kdež jest láska, nežli z krmného vola, kdež jest nenávist.'),
(1563085,54,20,15,18,'Muž hněvivý vzbuzuje sváry, ale zpozdilý k hněvu upokojuje svadu.'),
(1563086,54,20,15,19,'Cesta lenivého jest jako plot z trní, ale stezka upřímých jest vydlážená.'),
(1563087,54,20,15,20,'Syn moudrý obveseluje otce, bláznivý pak člověk pohrdá matkou svou.'),
(1563088,54,20,15,21,'Bláznovství jest veselím bláznu, ale člověk rozumný upřímo kráčeti směřuje.'),
(1563089,54,20,15,22,'Kdež není rady, zmařena bývají usilování, ale množství rádců ostojí.'),
(1563090,54,20,15,23,'Vesel bývá člověk z odpovědi úst svých; nebo slovo v čas příhodný ó jak jest dobré!'),
(1563091,54,20,15,24,'Cesta života vysoko jest rozumnému proto, aby se uchýlil od pekla dole.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563092,54,20,15,25,'Dům pyšných vyvrací Hospodin, meze pak vdovy upevňuje.'),
(1563093,54,20,15,26,'Ohavností jsou Hospodinu myšlení zlého, ale čistých řeči vzácné.'),
(1563094,54,20,15,27,'Kdož dychtí po lakomství, kormoutí dům svůj; ale kdož nenávidí darů, živ bude.'),
(1563095,54,20,15,28,'Srdce spravedlivého přemyšluje, co má mluviti, ale ústa bezbožných vylévají všelijakou zlost.'),
(1563096,54,20,15,29,'Vzdálen jest Hospodin od bezbožných, ale modlitbu spravedlivých vyslýchá.'),
(1563097,54,20,15,30,'To, což se zraku naskýtá, obveseluje srdce; pověst dobrá tukem naplňuje kosti.'),
(1563098,54,20,15,31,'Ucho, kteréž poslouchá trestání života, u prostřed moudrých bydliti bude.'),
(1563099,54,20,15,32,'Kdo se vyhýbá cvičení, zanedbává duše své; ale kdož přijímá domlouvání, má rozum.'),
(1563100,54,20,15,33,'Bázeň Hospodinova jest cvičení se moudrosti, a slávu předchází ponížení.'),
(1563101,54,20,16,1,'Při člověku bývá spořádání myšlení, ale od Hospodina jest řeč jazyka.'),
(1563102,54,20,16,2,'Všecky cesty člověka čisté se jemu zdají, ale kterýž zpytuje duchy, Hospodin jest.'),
(1563103,54,20,16,3,'Uval na Hospodina činy své, a budou upevněna předsevzetí tvá.'),
(1563104,54,20,16,4,'Hospodin všecko učinil pro sebe samého, také i bezbožného ke dni zlému.'),
(1563105,54,20,16,5,'Ohavností jest Hospodinu každý pyšného srdce; by sobě na pomoc i jiné přivzal, neujde pomsty.'),
(1563106,54,20,16,6,'Milosrdenstvím a pravdou očištěna bývá nepravost, a v bázni Hospodinově uchází se zlého.'),
(1563107,54,20,16,7,'Když se líbí Hospodinu cesty člověka, také i nepřátely jeho spokojuje k němu.'),
(1563108,54,20,16,8,'Lepší jest maličko s spravedlností, než množství důchodů nespravedlivých.'),
(1563109,54,20,16,9,'Srdce člověka přemýšlí o cestě své, ale Hospodin spravuje kroky jeho.'),
(1563110,54,20,16,10,'Rozhodnutí jest ve rtech královských, v soudu neuchylují se ústa jeho.'),
(1563111,54,20,16,11,'Váha a závaží jsou úsudek Hospodinův, a všecka závaží v pytlíku jeho nařízení.'),
(1563112,54,20,16,12,'Ohavností jest králům činiti bezbožně; nebo spravedlností upevňován bývá trůn.'),
(1563113,54,20,16,13,'Rtové spravedliví líbezní jsou králům, a ty, kteříž upřímě mluví, milují.'),
(1563114,54,20,16,14,'Rozhněvání královo jistý posel smrti, ale muž moudrý ukrotí je.'),
(1563115,54,20,16,15,'V jasné tváři královské jest život, a přívětivost jeho jako oblak s deštěm jarním.'),
(1563116,54,20,16,16,'Mnohem lépe jest nabyti moudrosti než zlata nejčistšího, a nabyti rozumnosti lépe než stříbra.'),
(1563117,54,20,16,17,'Cesta upřímých jest odstoupiti od zlého; ostříhá duše své ten, kdož ostříhá cesty své.'),
(1563118,54,20,16,18,'Před setřením bývá pýcha, a před pádem pozdvižení ducha.'),
(1563119,54,20,16,19,'Lépe jest poníženého duchu býti s pokornými, než děliti kořist s pyšnými.'),
(1563120,54,20,16,20,'Ten, kdož pozoruje slova, nalézá dobré; a kdož doufá v Hospodina, blahoslavený jest.'),
(1563121,54,20,16,21,'Ten, kdož jest moudrého srdce, slove rozumný, a sladkost rtů přidává naučení.'),
(1563122,54,20,16,22,'Rozumnost těm, kdož ji mají, jest pramen života, ale umění bláznů jest bláznovství.'),
(1563123,54,20,16,23,'Srdce moudrého rozumně spravuje ústa svá, tak že rty svými přidává naučení.'),
(1563124,54,20,16,24,'Plást medu jsou řeči utěšené, sladkost duši, a lékařství kostem.'),
(1563125,54,20,16,25,'Cesta zdá se přímá člověku, ale dokonání její jistá cesta smrti.'),
(1563126,54,20,16,26,'Člověk pracovitý pracuje sobě, nebo ponoukají ho ústa jeho.'),
(1563127,54,20,16,27,'Muž nešlechetný vykopává zlé, v jehožto rtech jako oheň spalující.'),
(1563128,54,20,16,28,'Muž převrácený rozsívá sváry, a klevetník rozlučuje přátely.'),
(1563129,54,20,16,29,'Muž ukrutný přeluzuje bližního svého, a uvodí jej na cestu nedobrou.'),
(1563130,54,20,16,30,'Zamhuřuje oči své, smýšleje věci převrácené, a zmítaje pysky svými, vykonává zlé.'),
(1563131,54,20,16,31,'Koruna ozdobná jsou šediny na cestě spravedlnosti se nalézající.'),
(1563132,54,20,16,32,'Lepší jest zpozdilý k hněvu než silný rek, a kdož panuje nad myslí svou nežli ten, kterýž dobyl města.'),
(1563133,54,20,16,33,'Do klínu umítán bývá los, ale od Hospodina všecko řízení jeho.'),
(1563134,54,20,17,1,'Lepší jest kus chleba suchého s pokojem,nežli dům plný nabitých hovad s svárem.'),
(1563135,54,20,17,2,'Služebník rozumný panovati bude nad synem, kterýž jest k hanbě, a mezi bratřími děliti bude dědictví.'),
(1563136,54,20,17,3,'Teglík stříbra a pec zlata zkušuje, ale srdcí Hospodin.'),
(1563137,54,20,17,4,'Zlý člověk pozoruje řečí nepravých, a lhář poslouchá jazyka převráceného.'),
(1563138,54,20,17,5,'Kdo se posmívá chudému, útržku činí Učiniteli jeho; a kdo se z bídy raduje, nebude bez pomsty.'),
(1563139,54,20,17,6,'Koruna starců jsou vnukové, a ozdoba synů otcové jejich.'),
(1563140,54,20,17,7,'Nesluší na blázna řeči znamenité, ovšem na kníže řeč lživá.'),
(1563141,54,20,17,8,'Jako kámen drahý, tak bývá vzácný dar před očima toho, kdož jej béře; k čemukoli směřuje, daří se jemu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563142,54,20,17,9,'Kdo přikrývá přestoupení, hledá lásky; ale kdo obnovuje věc, rozlučuje přátely.'),
(1563143,54,20,17,10,'Více se chápá rozumného jedno domluvení, nežli by blázna stokrát ubil.'),
(1563144,54,20,17,11,'Zpurný toliko zlého hledá, pročež přísný posel na něj poslán bývá.'),
(1563145,54,20,17,12,'Lépe člověku potkati se s nedvědicí osiřalou, nežli s bláznem v bláznovství jeho.'),
(1563146,54,20,17,13,'Kdo odplacuje zlým za dobré, neodejdeť zlé z domu jeho.'),
(1563147,54,20,17,14,'Začátek svady jest, jako když kdo protrhuje vodu; protož prvé než by se zsilil svár, přestaň.'),
(1563148,54,20,17,15,'Kdož ospravedlňuje nepravého, i kdož odsuzuje spravedlivého, ohavností jsou Hospodinu oba jednostejně.'),
(1563149,54,20,17,16,'K čemu jest zboží v ruce blázna, když k nabytí moudrosti rozumu nemá?'),
(1563150,54,20,17,17,'Všelikého času miluje, kdož jest přítelem, a bratr v ssoužení ukáže se.'),
(1563151,54,20,17,18,'Člověk bláznivý ruku dávaje, činí slib před přítelem svým.'),
(1563152,54,20,17,19,'Kdož miluje svadu, miluje hřích; a kdo vyvyšuje ústa svá, hledá potření.'),
(1563153,54,20,17,20,'Převrácené srdce nenalézá toho, což jest dobrého; a kdož má vrtký jazyk, upadá v těžkost.'),
(1563154,54,20,17,21,'Kdo zplodil blázna, k zámutku svému zplodil jej, aniž se bude radovati otec nemoudrého.'),
(1563155,54,20,17,22,'Srdce veselé očerstvuje jako lékařství, ale duch zkormoucený vysušuje kosti.'),
(1563156,54,20,17,23,'Bezbožný tajně béře dar, aby převrátil stezky soudu.'),
(1563157,54,20,17,24,'Na oblíčeji rozumného vidí se moudrost, ale oči blázna těkají až na konec země.'),
(1563158,54,20,17,25,'K žalosti jest otci svému syn blázen, a k hořkosti rodičce své.'),
(1563159,54,20,17,26,'Jistě že pokutovati spravedlivého není dobré, tolikéž, aby knížata bíti měli pro upřímost.'),
(1563160,54,20,17,27,'Zdržuje řeči své muž umělý; drahého ducha jest muž rozumný.'),
(1563161,54,20,17,28,'Také i blázen, mlče, za moudrého jmín bývá, a zacpávaje rty své, za rozumného.'),
(1563162,54,20,18,1,'Svémyslný hledá toho, což se jemu líbí, a ve všelijakou věc plete se.'),
(1563163,54,20,18,2,'Nezalibuje sobě blázen v rozumnosti, ale v tom, což zjevuje srdce jeho.'),
(1563164,54,20,18,3,'Když přijde bezbožný, přichází také pohrdání, a s lehkomyslným útržka.'),
(1563165,54,20,18,4,'Slova úst muže vody hluboké, potok rozvodnilý pramen moudrosti.'),
(1563166,54,20,18,5,'Přijímati osobu bezbožného není dobré, abys převrátil spravedlivého v soudu.'),
(1563167,54,20,18,6,'Rtové blázna směřují k svadě, a ústa jeho bití se domluví.'),
(1563168,54,20,18,7,'Ústa blázna k setření jemu, a rtové jeho osídlem duši jeho.'),
(1563169,54,20,18,8,'Slova utrhače jsou jako ubitých, ale však sstupují do vnitřností života.'),
(1563170,54,20,18,9,'Také ten, kdož jest nedbalý v práci své, bratr jest mrhače.'),
(1563171,54,20,18,10,'Věže pevná jest jméno Hospodinovo; k němu se uteče spravedlivý, a bude povýšen.'),
(1563172,54,20,18,11,'Zboží bohatého jest město pevné jeho, a jako zed vysoká v mysli jeho.'),
(1563173,54,20,18,12,'Před setřením vyvyšuje se srdce člověka, ale před povýšením bývá ponížení.'),
(1563174,54,20,18,13,'Kdož odpovídá něco, prvé než vyslyší, počítá se to za bláznovství jemu a za lehkost.'),
(1563175,54,20,18,14,'Duch muže snáší nemoc svou, ducha pak zkormouceného kdo snese?'),
(1563176,54,20,18,15,'Srdce rozumného dosahuje umění, a ucho moudrých hledá umění.'),
(1563177,54,20,18,16,'Dar člověka uprostranňuje jemu, a před oblíčej mocných přivodí jej.'),
(1563178,54,20,18,17,'Spravedlivý zdá se ten, kdož jest první v své při, ale když přichází bližní jeho, tedy stihá jej.'),
(1563179,54,20,18,18,'Los pokojí svady, a mezi silnými rozeznává.'),
(1563180,54,20,18,19,'Bratr křivdou uražený tvrdší jest než město nedobyté, a svárové jsou jako závora u hradu.'),
(1563181,54,20,18,20,'Ovocem úst jednoho každého nasyceno bývá břicho jeho, úrodou rtů svých nasycen bude.'),
(1563182,54,20,18,21,'Smrt i život jest v moci jazyka, a ten, kdož jej miluje, bude jísti ovoce jeho.'),
(1563183,54,20,18,22,'Kdo nalezl manželku, nalezl věc dobrou, a navážil lásky od Hospodina.'),
(1563184,54,20,18,23,'Poníženě mluví chudý, ale bohatý odpovídá tvrdě.'),
(1563185,54,20,18,24,'Ten, kdož má přátely, má se míti přátelsky, poněvadž přítel bývá vlastnější než bratr.'),
(1563186,54,20,19,1,'Lepší jest chudý, jenž chodí v upřímnosti své, nežli převrácený ve rtech svých, kterýž jest blázen.'),
(1563187,54,20,19,2,'Jistě že bez umění duši není dobře, a kdož jest kvapných noh, hřeší.'),
(1563188,54,20,19,3,'Bláznovství člověka převrací cestu jeho, ačkoli proti Hospodinu zpouzí se srdce jeho.'),
(1563189,54,20,19,4,'Statek přidává přátel množství, ale chudý od přítele svého odloučen bývá.'),
(1563190,54,20,19,5,'Svědek falešný nebude bez pomsty, a kdož mluví lež, neuteče.'),
(1563191,54,20,19,6,'Mnozí pokoří se před knížetem, a každý jest přítel muži štědrému.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563192,54,20,19,7,'Všickni bratří chudého v nenávisti jej mají; čím více přátelé jeho vzdalují se od něho! Když volá za nimi, není jich.'),
(1563193,54,20,19,8,'Ten, kdož miluje duši svou, nabývá moudrosti, a ostříhá opatrnosti, aby nalezl dobré.'),
(1563194,54,20,19,9,'Svědek falešný nebude bez pomsty, a kdož mluví lež, zahyne.'),
(1563195,54,20,19,10,'Nesluší na blázna rozkoš, a ovšem, aby služebník nad knížaty panoval.'),
(1563196,54,20,19,11,'Rozum člověka zdržuje hněv jeho, a čest jeho jest prominouti provinění.'),
(1563197,54,20,19,12,'Prchlivost královská jako řvání mladého lva jest, a ochotnost jeho jako rosa na bylinu.'),
(1563198,54,20,19,13,'Trápení otci svému jest syn bláznivý, a ustavičné kapání žena svárlivá.'),
(1563199,54,20,19,14,'Dům a statek jest po rodičích, ale od Hospodina manželka rozumná.'),
(1563200,54,20,19,15,'Lenost přivodí tvrdý sen, a duše váhavá lačněti bude.'),
(1563201,54,20,19,16,'Ten, kdož ostříhá přikázaní, ostříhá duše své; ale kdož pohrdá cestami svými, zahyne.'),
(1563202,54,20,19,17,'Kdo uděluje chudému, půjčuje Hospodinu, a onť za dobrodiní jeho odplatí jemu.'),
(1563203,54,20,19,18,'Tresci syna svého, dokudž jest o něm naděje, a k zahynutí jeho neodpouštěj jemu duše tvá.'),
(1563204,54,20,19,19,'Veliký hněv ukazuj, odpouštěje trestání, proto že poněvadž odpouštíš, potom více trestati budeš.'),
(1563205,54,20,19,20,'Poslouchej rady, a přijímej kázeň, abys vždy někdy moudrý byl.'),
(1563206,54,20,19,21,'Mnozí úmyslové jsou v srdci člověka, ale uložení Hospodinovo toť ostojí.'),
(1563207,54,20,19,22,'Žádaná věc člověku jest dobře činiti jiným, ale počestnější jest chudý než muž lživý.'),
(1563208,54,20,19,23,'Bázeň Hospodinova k životu. Takový jsa nasycen, bydlí, aniž neštěstím navštíven bývá.'),
(1563209,54,20,19,24,'Lenivý schovává ruku svou za ňadra, ani k ústům svým jí nevztáhne.'),
(1563210,54,20,19,25,'Ubí posměvače, ať se hlupec dovtípí; a potresci rozumného, ať porozumí umění.'),
(1563211,54,20,19,26,'Syn, kterýž hanbu a lehkost činí, hubí otce, a zahání matku.'),
(1563212,54,20,19,27,'Přestaň, synu můj, poslouchati učení, kteréž od řečí rozumných odvozuje.'),
(1563213,54,20,19,28,'Svědek nešlechetný posmívá se soudu, a ústa bezbožných přikrývají nepravost.'),
(1563214,54,20,19,29,'Nebo na posměvače hotoví jsou nálezové, a rány na hřbet bláznů.'),
(1563215,54,20,20,1,'Víno činí posměvače, a nápoj opojný nepokojného; pročež každý, kdož se kochá v něm, nebývá moudrý.'),
(1563216,54,20,20,2,'Hrůza královská jako řvání mladého lva; kdož ho rozhněvá, hřeší proti životu svému.'),
(1563217,54,20,20,3,'Přestati od sváru jest to každému ku poctivosti, ale kdožkoli se do nich zapletá, blázen jest.'),
(1563218,54,20,20,4,'Lenoch neoře pro zimu, pročež žebrati bude ve žni, ale nadarmo.'),
(1563219,54,20,20,5,'Rada v srdci muže voda hluboká, muž však rozumný dosáhne jí.'),
(1563220,54,20,20,6,'Větší díl lidí honosí se účinností svou, ale v pravdě takového kdo nalezne?'),
(1563221,54,20,20,7,'Spravedlivý ustavičně chodí v upřímnosti své; blažení synové jeho po něm.'),
(1563222,54,20,20,8,'Král sedě na soudné stolici, rozhání očima svýma všecko zlé.'),
(1563223,54,20,20,9,'Kdo může říci: Očistil jsem srdce své? Čist jsem od hříchu svého?'),
(1563224,54,20,20,10,'Závaží rozdílná a míra rozdílná, obé to ohavností jest Hospodinu.'),
(1563225,54,20,20,11,'Po skutcích svých poznáno bývá také i pachole, jest-li upřímé a pravé dílo jeho.'),
(1563226,54,20,20,12,'Ucho, kteréž slyší, a oko, kteréž vidí, obé to učinil Hospodin.'),
(1563227,54,20,20,13,'Nemiluj snu, abys nezchudl, otevři oči své, a nasytíš se chlebem.'),
(1563228,54,20,20,14,'Zlé, zlé, říká ten, kdož kupuje, a odejda, tedy se chlubí.'),
(1563229,54,20,20,15,'Zlato a množství perel, a nejdražší klínot jsou rtové umělí.'),
(1563230,54,20,20,16,'Vezmi roucho toho, kterýž slíbil za cizího, a kdo za cizozemku, základ jeho.'),
(1563231,54,20,20,17,'Chutný jest někomu chléb falše, ale potom ústa jeho pískem naplněna bývají.'),
(1563232,54,20,20,18,'Myšlení radou upevňuj, a s opatrnou radou veď boj.'),
(1563233,54,20,20,19,'Kdo vynáší tajnost, chodí neupřímě, pročež k lahodícímu rty svými nepřiměšuj se.'),
(1563234,54,20,20,20,'Kdo zlořečí otci svému neb matce své, zhasne svíce jeho v temných mrákotách.'),
(1563235,54,20,20,21,'Dědictví rychle z počátku nabytému naposledy nebývá dobrořečeno,'),
(1563236,54,20,20,22,'Neříkej: Odplatím se zlým; očekávej na Hospodina, a vysvobodí tě.'),
(1563237,54,20,20,23,'Ohavností jsou Hospodinu závaží rozdílná, a váhy falešné neoblibuje.'),
(1563238,54,20,20,24,'Od Hospodina jsou krokové muže, ale člověk jak vyrozumívá cestě jeho?'),
(1563239,54,20,20,25,'Osídlo jest člověku pohltiti věc posvěcenou, a po slibu zase toho vyhledávati.'),
(1563240,54,20,20,26,'Král moudrý rozptyluje bezbožné, a uvodí na ně pomstu.'),
(1563241,54,20,20,27,'Duše člověka jest svíce Hospodinova, kteráž zpytuje všecky vnitřnosti srdečné.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563242,54,20,20,28,'Milosrdenství a pravda ostříhají krále, a milosrdenstvím podpírá se trůn jeho.'),
(1563243,54,20,20,29,'Ozdoba mládenců jest síla jejich, a okrasa starců šediny.'),
(1563244,54,20,20,30,'Modřiny ran jsou lékařství při zlém, a bití vnitřnostem života.'),
(1563245,54,20,21,1,'Jako potůčkové vod jest srdce královo v ruce Hospodinově; kamžkoli chce, nakloňuje ho.'),
(1563246,54,20,21,2,'Všeliká cesta člověka přímá se zdá jemu, ale kterýž zpytuje srdce, Hospodin jest.'),
(1563247,54,20,21,3,'Vykonávati spravedlnost a soud více se líbí Hospodinu nežli obět.'),
(1563248,54,20,21,4,'Vysokost očí, širokost srdce, a orání bezbožných jest hříchem.'),
(1563249,54,20,21,5,'Myšlení bedlivého všelijak ku prospěchu přicházejí, ale každého toho, kdož kvapný jest, toliko k nouzi.'),
(1563250,54,20,21,6,'Pokladové jazykem lživým shromáždění jsou marnost pomíjející hledajících smrti.'),
(1563251,54,20,21,7,'Zhouba, kterouž činí bezbožníci, bydliti bude u nich; nebo se zpěčují činiti soudu.'),
(1563252,54,20,21,8,'Muž, jehož cesta převrácená jest, cizí jest, čistého pak dílo přímé jest.'),
(1563253,54,20,21,9,'Lépe jest bydliti v koutě na střeše,nežli s ženou svárlivou v domě společném.'),
(1563254,54,20,21,10,'Duše bezbožného žádá zlého, ani přítel jeho jemu příjemný nebývá.'),
(1563255,54,20,21,11,'Posměvač když bývá trestán, hloupý bývá moudřejší; a když se uměle nakládá s moudrým, přijímá umění.'),
(1563256,54,20,21,12,'Vyučuje Bůh spravedlivého na domě bezbožného, kterýž vyvrací bezbožné pro zlost.'),
(1563257,54,20,21,13,'Kdo zacpává ucho své k volání chudého, i on sám volati bude, a nebude vyslyšán.'),
(1563258,54,20,21,14,'Dar skrytý ukrocuje prchlivost, a pocta v klíně hněv prudký.'),
(1563259,54,20,21,15,'Radostí jest spravedlivému činiti soud, ale hrůzou činitelům nepravosti.'),
(1563260,54,20,21,16,'Člověk bloudící z cesty rozumnosti v shromáždění mrtvých odpočívati bude.'),
(1563261,54,20,21,17,'Muž milující veselost nuzníkem bývá, a kdož miluje víno a masti, nezbohatne.'),
(1563262,54,20,21,18,'Výplatou za spravedlivého bude bezbožný, a za upřímé ošemetný.'),
(1563263,54,20,21,19,'Lépe jest bydliti v zemi pusté než s ženou svárlivou a zlostnou.'),
(1563264,54,20,21,20,'Poklad žádostivý a olej jest v příbytku moudrého, bláznivý pak člověk zžírá jej.'),
(1563265,54,20,21,21,'Kdo snažně následuje spravedlnosti a milosrdenství, nalézá život, spravedlnost i slávu.'),
(1563266,54,20,21,22,'Do města silných vchází moudrý, a boří pevnost doufání jeho.'),
(1563267,54,20,21,23,'Kdo ostříhá úst svých a jazyka svého, ostříhá od úzkosti duše své.'),
(1563268,54,20,21,24,'Hrdého a pyšného jméno jest posměvač, kterýž vše s neochotností a pýchou dělá.'),
(1563269,54,20,21,25,'Žádost lenivého zabijí jej, nebo nechtí ruce jeho dělati.'),
(1563270,54,20,21,26,'Každého dne žádostí hoří, spravedlivý pak dává a neskoupí se.'),
(1563271,54,20,21,27,'Obět bezbožných ohavností jest, ovšem pak jestliže by ji s nešlechetností obětovali.'),
(1563272,54,20,21,28,'Svědek lživý zahyne, ale muž, kterýž co slyší, stále mluviti bude.'),
(1563273,54,20,21,29,'Muž bezbožný zatvrzuje tvář svou, upřímý pak měří cestu svou.'),
(1563274,54,20,21,30,'Není žádné moudrosti, ani opatrnosti, ani rady proti Hospodinu.'),
(1563275,54,20,21,31,'Kůň strojen bývá ke dni boje, ale Hospodinovo jest vysvobození.'),
(1563276,54,20,22,1,'Vzácnější jest jméno dobré než bohatství veliké, a přízeň lepší než stříbro a zlato.'),
(1563277,54,20,22,2,'Bohatý a chudý potkávají se, učinitel obou jest Hospodin.'),
(1563278,54,20,22,3,'Opatrný vida zlé, vyhne se, ale hloupí předce jdouce, těžkosti docházejí.'),
(1563279,54,20,22,4,'Pokory a bázně Hospodinovy odplata jest bohatství a sláva i život.'),
(1563280,54,20,22,5,'Trní a osídla jsou na cestě převráceného; kdož ostříhá duše své, vzdálí se od nich.'),
(1563281,54,20,22,6,'Vyučuj mladého podlé způsobu cesty jeho; nebo když se i zstará, neuchýlí se od ní.'),
(1563282,54,20,22,7,'Bohatý nad chudými panuje, a vypůjčující bývá služebníkem toho, jenž půjčuje.'),
(1563283,54,20,22,8,'Kdo rozsívá nepravost, žíti bude trápení; prut zajisté prchlivosti jeho přestane.'),
(1563284,54,20,22,9,'Oko dobrotivé, onoť požehnáno bude; nebo udílí z chleba svého chudému.'),
(1563285,54,20,22,10,'Vyvrz posměvače, a odejdeť svada, anobrž přestane svár a lehkost.'),
(1563286,54,20,22,11,'Kdo miluje čistotu srdce, a v čích rtech jest příjemnost, takového král přítelem bývá.'),
(1563287,54,20,22,12,'Oči Hospodinovy ostříhají umění, ale snažnosti ošemetného převrací.'),
(1563288,54,20,22,13,'Říká lenoch: Lev jest vně, naprostřed ulic byl bych zabit.'),
(1563289,54,20,22,14,'Jáma hluboká ústa postranních; ten, na kohož se hněvá Hospodin, vpadne tam.'),
(1563290,54,20,22,15,'Bláznovství přivázáno jest k srdci mladého, ale metla kázně vzdálí je od něho.'),
(1563291,54,20,22,16,'Kdo utiská nuzného, aby rozmnožil své, a dává bohatému, jistotně bude v nouzi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563292,54,20,22,17,'Nakloň ucha svého, a slyš slova moudrých, a mysl svou přilož k učení mému.'),
(1563293,54,20,22,18,'Nebo to bude utěšenou věcí, jestliže je složíš v srdci svém, budou-li spolu nastrojena ve rtech tvých.'),
(1563294,54,20,22,19,'Aby bylo v Hospodinu doufání tvé, oznamujiť to dnes. I ty také ostříhej toho.'),
(1563295,54,20,22,20,'Zdaližť jsem nenapsal znamenitých věcí z strany rad a umění,'),
(1563296,54,20,22,21,'Aťbych v známost uvedl jistotu řečí pravých, tak abys vynášeti mohl slova pravdy těm, kteříž by k tobě poslali?'),
(1563297,54,20,22,22,'Nelup nuzného, proto že nuzný jest, aniž potírej chudého v bráně.'),
(1563298,54,20,22,23,'Nebo Hospodin povede při jejich, a vydře duši těm, kteříž vydírají jim.'),
(1563299,54,20,22,24,'Nebývej přítelem hněvivého, a s mužem prchlivým neobcuj,'),
(1563300,54,20,22,25,'Abys se nenaučil stezkám jeho, a nevložil osídla na duši svou.'),
(1563301,54,20,22,26,'Nebývej mezi rukojměmi, mezi slibujícími za dluhy.'),
(1563302,54,20,22,27,'Nemáš-li, čím bys zaplatil, proč má kdo bráti lůže tvé pod tebou?'),
(1563303,54,20,22,28,'Nepřenášej mezníku starodávního, kterýž učinili otcové tvoji.'),
(1563304,54,20,22,29,'Vídáš-li, že muž snažný v díle svém před králi stává? Nestává před nepatrnými.'),
(1563305,54,20,23,1,'Když sedneš k jídlu se pánem, pilně šetř, co jest před tebou.'),
(1563306,54,20,23,2,'Jinak vrazil bys nůž do hrdla svého, byl-li bys lakotný.'),
(1563307,54,20,23,3,'Nežádej lahůdek jeho, nebo jsou pokrm oklamavatelný.'),
(1563308,54,20,23,4,'Neusiluj, abys zbohatl; od opatrnosti své přestaň.'),
(1563309,54,20,23,5,'K bohatství-liž bys obrátil oči své? Poněvadž v náhle mizí; nebo sobě zdělalo křídla podobná orličím, a zaletuje k nebi.'),
(1563310,54,20,23,6,'Nejez chleba člověka závistivého, a nežádej lahůdek jeho.'),
(1563311,54,20,23,7,'Nebo jak on sobě tebe váží v mysli své, tak ty pokrmu toho. Díť: Jez a pí, ale srdce jeho není s tebou.'),
(1563312,54,20,23,8,'Skyvu svou, kterouž jsi snědl, vyvrátíš, a zmaříš slova svá utěšená.'),
(1563313,54,20,23,9,'Před bláznem nemluv, nebo pohrdne opatrností řečí tvých.'),
(1563314,54,20,23,10,'Nepřenášej mezníku starodávního, a na pole sirotků nevcházej.'),
(1563315,54,20,23,11,'Silnýť jest zajisté ochránce jejich; onť povede při jejich proti tobě.'),
(1563316,54,20,23,12,'Zaveď k učení mysl svou, a uši své k řečem umění.'),
(1563317,54,20,23,13,'Neodjímej od mladého kázně; nebo umrskáš-li jej metlou, neumřeť.'),
(1563318,54,20,23,14,'Ty metlou jej mrskávej, a tak duši jeho z pekla vytrhneš.'),
(1563319,54,20,23,15,'Synu můj, bude-li moudré srdce tvé, veseliti se bude srdce mé všelijak ve mně;'),
(1563320,54,20,23,16,'A plésati budou ledví má, když mluviti budou rtové tvoji pravé věci.'),
(1563321,54,20,23,17,'Nechť nezávidí srdce tvé hříšníku, ale raději choď v bázni Hospodinově celý den.'),
(1563322,54,20,23,18,'Nebo poněvadž jest odplata, naděje tvá nebude podťata.'),
(1563323,54,20,23,19,'Slyš ty, synu můj, a buď moudrý, a naprav na cestu srdce své.'),
(1563324,54,20,23,20,'Nebývej mezi pijány vína, ani mezi žráči masa.'),
(1563325,54,20,23,21,'Nebo opilec a žráč zchudne, a ospánlivost v hadry obláčí.'),
(1563326,54,20,23,22,'Poslouchej otce svého, kterýž tě zplodil, aniž pohrdej matkou svou, když se zstará.'),
(1563327,54,20,23,23,'Pravdy nabuď, a neprodávej jí, též moudrosti, umění a rozumnosti.'),
(1563328,54,20,23,24,'Náramně bývá potěšen otec spravedlivého, a ten, kdož zplodil moudrého, veselí se z něho.'),
(1563329,54,20,23,25,'Nechať se tedy veselí otec tvůj a matka tvá, a ať pléše rodička tvá.'),
(1563330,54,20,23,26,'Dej mi, synu můj, srdce své, a oči tvé cest mých ať ostříhají.'),
(1563331,54,20,23,27,'Nebo nevěstka jest jáma hluboká, a studnice těsná žena cizí.'),
(1563332,54,20,23,28,'Onať také jako loupežník úklady činí, a zoufalce na světě rozmnožuje.'),
(1563333,54,20,23,29,'Komu běda? komu ouvech? komu svady? komu křik? komu rány darmo? komu červenost očí?'),
(1563334,54,20,23,30,'Těm, kteříž se zdržují na víně; těm, kteříž chodí, aby vyhledali strojené víno.'),
(1563335,54,20,23,31,'Nehleď na víno rdící se, že vydává v koflíku záři svou, a přímo vyskakuje.'),
(1563336,54,20,23,32,'Naposledy jako had uštípne, a jako štír ušťkne.'),
(1563337,54,20,23,33,'Oči tvé hleděti budou na cizí, a srdce tvé mluviti bude převrácené věci,'),
(1563338,54,20,23,34,'A budeš jako ten, kterýž spí u prostřed moře, a jako ten, kterýž spí na vrchu sloupu bárky.'),
(1563339,54,20,23,35,'Díš: Zbili mne, a nestonal jsem, tloukli mne, a nečil jsem; když procítím, dám se zase v to.'),
(1563340,54,20,24,1,'Nenásleduj lidí zlých, aniž žádej bývati s nimi.'),
(1563341,54,20,24,2,'Nebo o zhoubě přemýšlí srdce jejich, a rtové jejich o trápení mluví.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563342,54,20,24,3,'Moudrostí vzdělán bývá dům, a rozumností upevněn.'),
(1563343,54,20,24,4,'Skrze umění zajisté pokojové naplněni bývají všelijakým zbožím drahým a utěšeným.'),
(1563344,54,20,24,5,'Muž moudrý jest silný, a muž umělý přidává síly.'),
(1563345,54,20,24,6,'Nebo skrze rady opatrné svedeš bitvu, a vysvobození skrze množství rádců.'),
(1563346,54,20,24,7,'Vysoké jsou bláznu moudrosti; v bráně neotevře úst svých.'),
(1563347,54,20,24,8,'Kdo myslí zle činiti, toho nešlechetným nazovou.'),
(1563348,54,20,24,9,'Zlé myšlení blázna jest hřích, a ohavnost lidská posměvač.'),
(1563349,54,20,24,10,'Budeš-li se lenovati ve dni ssoužení, špatná bude síla tvá.'),
(1563350,54,20,24,11,'Vytrhuj jaté k smrti; nebo od těch, ješto se chýlí k zabití, což bys se zdržel?'),
(1563351,54,20,24,12,'Díš-li: Aj, nevěděli jsme o tom: zdaliž ten, jenž zpytuje srdce, nerozumí, a ten, kterýž jest strážce duše tvé, nezná, a neodplatí každému podlé skutků jeho?'),
(1563352,54,20,24,13,'Synu můj, jez med, nebo dobrý jest, a plást sladký dásním tvým.'),
(1563353,54,20,24,14,'Tak umění moudrosti duši tvé. Jestliže ji najdeš, onať bude mzda, a naděje tvá nebude vyťata.'),
(1563354,54,20,24,15,'Nečiniž úkladů, ó bezbožníče, příbytku spravedlivého, a nekaz odpočinutí jeho.'),
(1563355,54,20,24,16,'Nebo ač sedmkrát padá spravedlivý, však zase povstává, bezbožníci pak padají ve zlém.'),
(1563356,54,20,24,17,'Když by padl nepřítel tvůj, neraduj se, a když by klesl, nechať nepléše srdce tvé,'),
(1563357,54,20,24,18,'Aby snad nepopatřil Hospodin, a nelíbilo by se to jemu, a odvrátil by od něho hněv svůj.'),
(1563358,54,20,24,19,'Nehněvej se příčinou zlostníků, aniž následuj bezbožných.'),
(1563359,54,20,24,20,'Nebo zlý nebude míti odplaty; svíce bezbožných zhasne.'),
(1563360,54,20,24,21,'Boj se Hospodina, synu můj, i krále, a k neustavičným se nepřiměšuj.'),
(1563361,54,20,24,22,'Nebo v náhle nastane bída jejich, a pomstu obou těch kdo zná?'),
(1563362,54,20,24,23,'Také i toto moudrým náleží: Přijímati osobu v soudu není dobré.'),
(1563363,54,20,24,24,'Toho, kdož říká bezbožnému: Spravedlivý jsi, klnouti budou lidé, a v ošklivost jej vezmou národové.'),
(1563364,54,20,24,25,'Ale kteříž kárají, budou potěšeni, a přijde na ně požehnání dobrého.'),
(1563365,54,20,24,26,'Bude líbati rty toho, kdož mluví slova pravá.'),
(1563366,54,20,24,27,'Nastroj vně dílo své, a sprav je sobě na poli; potom také vystavíš dům svůj.'),
(1563367,54,20,24,28,'Nebývej svědkem všetečným proti bližnímu svému, aniž lahodně namlouvej rty svými.'),
(1563368,54,20,24,29,'Neříkej: Jakž mi učinil, tak mu učiním; odplatím muži tomu podlé skutku jeho.'),
(1563369,54,20,24,30,'Přes pole muže lenivého šel jsem, a přes vinici člověka nemoudrého,'),
(1563370,54,20,24,31,'A aj, porostlo všudy trním, přikryly všecko kopřivy, a ohrada kamenná její byla zbořená.'),
(1563371,54,20,24,32,'A vida to, posoudil jsem toho; vida, vzal jsem to k výstraze.'),
(1563372,54,20,24,33,'Maličko pospíš, maličko zdřímeš, maličko složíš ruce, abys poležel,'),
(1563373,54,20,24,34,'V tom přijde jako pocestný chudoba tvá, a nouze tvá jako muž zbrojný.'),
(1563374,54,20,25,1,'Jaké i tato jsou přísloví Šalomounova, kteráž shromáždili muži Ezechiáše, krále Judského:'),
(1563375,54,20,25,2,'Sláva Boží jest skrývati věc, ale sláva králů zpytovati věc.'),
(1563376,54,20,25,3,'Vysokosti nebes, a hlubokosti země, a srdce králů není žádného vystižení.'),
(1563377,54,20,25,4,'Jako když bys odjal trůsku od stříbra, ukáže se slevači nádoba čistá:'),
(1563378,54,20,25,5,'Tak když odejmeš bezbožného od oblíčeje králova, tedy utvrzen bude v spravedlnosti trůn jeho.'),
(1563379,54,20,25,6,'Nestavěj se za znamenitého před králem, a na místě velikých nestůj.'),
(1563380,54,20,25,7,'Nebo lépe jest, aťby řečeno bylo: Vstup sem, nežli abys snížen byl před knížetem; což vídávají oči tvé.'),
(1563381,54,20,25,8,'Nevcházej v svár kvapně, tak abys naposledy něčeho se nedopustil, kdyby tě zahanbil bližní tvůj.'),
(1563382,54,20,25,9,'Srovnej při svou s bližním svým, a tajné věci jiného nevyjevuj,'),
(1563383,54,20,25,10,'Aťby lehkosti neučinil ten, kdož by to slyšel, až by i zlá pověst tvá nemohla jíti nazpět.'),
(1563384,54,20,25,11,'Jablka zlatá s řezbami stříbrnými jest slovo propověděné případně.'),
(1563385,54,20,25,12,'Náušnice zlatá a ozdoba z ryzího zlata jest trestatel moudrý u toho, jenž poslouchá.'),
(1563386,54,20,25,13,'Jako studenost sněžná v čas žně, tak jest posel věrný těm, kteříž jej posílají; nebo duši pánů svých očerstvuje.'),
(1563387,54,20,25,14,'Jako oblakové a vítr bez deště, tak člověk, kterýž se chlubí darem lživým.'),
(1563388,54,20,25,15,'Snášelivostí nakloněn bývá vývoda, a jazyk měkký láme kosti.'),
(1563389,54,20,25,16,'Nalezneš-li med, jez, pokudž by dosti bylo tobě, abys snad nasycen jsa jím, nevyvrátil ho.'),
(1563390,54,20,25,17,'Zdržuj nohu svou od domu bližního svého, aby syt jsa tebe, neměl tě v nenávisti.'),
(1563391,54,20,25,18,'Kladivo a meč a střela ostrá jest každý, kdož mluví falešné svědectví proti bližnímu svému.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563392,54,20,25,19,'Zub vylomený a noha vytknutá jest doufání v převráceném v den úzkosti.'),
(1563393,54,20,25,20,'Jako ten, kdož svláčí oděv v čas zimy, a ocet lije k sanitru, tak kdož zpívá písničky srdci smutnému.'),
(1563394,54,20,25,21,'Jestliže by lačněl ten, jenž tě nenávidí, nakrm jej chlebem, a žíznil-li by, napoj jej vodou.'),
(1563395,54,20,25,22,'Nebo uhlí řeřavé shromáždíš na hlavu jeho, a Hospodin odplatí tobě.'),
(1563396,54,20,25,23,'Vítr půlnoční zplozuje déšť, a tvář hněvivá jazyk tajně utrhající.'),
(1563397,54,20,25,24,'Lépe jest bydliti v koutě na střeše,nežli s ženou svárlivou v domě společném.'),
(1563398,54,20,25,25,'Voda studená duši ustalé jest novina dobrá z země daleké.'),
(1563399,54,20,25,26,'Studnice nohami zakalená a pramen zkažený jest spravedlivý z místa svého před bezbožným vystrčený.'),
(1563400,54,20,25,27,'Jísti mnoho medu není dobře; tak zpytování slávy jejich není slavné.'),
(1563401,54,20,25,28,'Město rozbořené beze zdi jest muž, kterýž nemá moci nad duchem svým.'),
(1563402,54,20,26,1,'Jako sníh v létě, a jako déšť ve žni, tak nepřipadá na blázna čest.'),
(1563403,54,20,26,2,'Jako vrabec přenáší se, a vlaštovice létá, tak zlořečení bez příčiny nedojde.'),
(1563404,54,20,26,3,'Bič na koně, uzda na osla, a kyj na hřbet blázna.'),
(1563405,54,20,26,4,'Neodpovídej bláznu podlé bláznovství jeho, abys i ty jemu nebyl podobný.'),
(1563406,54,20,26,5,'Odpověz bláznu podlé bláznovství jeho, aby sám u sebe nebyl moudrý.'),
(1563407,54,20,26,6,'Jako by nohy osekal, bezpráví se dopouští ten, kdož svěřuje poselství bláznu.'),
(1563408,54,20,26,7,'Jakož nejednostejní jsou hnátové kulhavého, tak řeč v ústech bláznů.'),
(1563409,54,20,26,8,'Jako vložiti kámen do praku, tak jest, když kdo ctí blázna.'),
(1563410,54,20,26,9,'Trn, kterýž se dostává do rukou opilého, jest přísloví v ústech bláznů.'),
(1563411,54,20,26,10,'Veliký pán stvořil všecko, a dává odplatu bláznu, i odměnu přestupníkům.'),
(1563412,54,20,26,11,'Jakož pes navracuje se k vývratku svému, tak blázen opětuje bláznovství své.'),
(1563413,54,20,26,12,'Spatřil-li bys člověka, an jest moudrý sám u sebe, naděje o bláznu lepší jest než o takovém.'),
(1563414,54,20,26,13,'Říká lenoch: Lev lítý jest na cestě, lev jest v ulici.'),
(1563415,54,20,26,14,'Dvéře se obracejí na stežejích svých, a lenoch na lůži svém.'),
(1563416,54,20,26,15,'Schovává lenivý ruku svou za ňadra; těžko mu vztáhnouti ji k ústům svým.'),
(1563417,54,20,26,16,'Moudřejší jest lenivý u sebe sám, nežli sedm odpovídajících s soudem.'),
(1563418,54,20,26,17,'Psa za uši lapá, kdož odcházeje, hněvá se ne v své při.'),
(1563419,54,20,26,18,'Jako nesmyslný vypouští jiskry a šípy smrtelné,'),
(1563420,54,20,26,19,'Tak jest každý, kdož oklamává bližního, a říká: Zdaž jsem nežertoval?'),
(1563421,54,20,26,20,'Když není drev, hasne oheň; tak když nebude klevetníka, utichne svár.'),
(1563422,54,20,26,21,'Uhel mrtvý k roznícení, a drva k ohni, tak člověk svárlivý k roznícení svady.'),
(1563423,54,20,26,22,'Slova utrhače jako ubitých, ale však sstupují do vnitřností života.'),
(1563424,54,20,26,23,'Stříbrná trůska roztažená po střepě jsou rtové protivní a srdce zlé.'),
(1563425,54,20,26,24,'Rty svými za jiného se staví ten, jenž nenávidí, ale u vnitřnosti své skládá lest.'),
(1563426,54,20,26,25,'Když se ochotný ukáže řečí svou, nevěř mu; nebo sedmera ohavnost jest v srdci jeho.'),
(1563427,54,20,26,26,'Přikrývána bývá nenávist chytře, ale zlost její zjevena bývá v shromáždění.'),
(1563428,54,20,26,27,'Kdo jámu kopá, do ní upadá, a kdo valí kámen, na něj se obrací.'),
(1563429,54,20,26,28,'Člověk jazyka ošemetného v nenávisti má ponížené, a ústy úlisnými způsobuje pád.'),
(1563430,54,20,27,1,'Nechlub se dnem zítřejším, nebo nevíš, coť ten den přinese.'),
(1563431,54,20,27,2,'Nechať tě chválí jiní, a ne ústa tvá, cizí, a ne rtové tvoji.'),
(1563432,54,20,27,3,'Tíž má kamen, a váhu písek, ale hněv blázna těžší jest nad to obé.'),
(1563433,54,20,27,4,'Ukrutnátě věc hněv a prudká prchlivost, ale kdo ostojí před závistí?'),
(1563434,54,20,27,5,'Lepší jest domlouvání zjevné, než milování tajné.'),
(1563435,54,20,27,6,'Bezpečnější rány od přítele, než lahodná líbání nenávidícího.'),
(1563436,54,20,27,7,'Duše sytá pohrdá i medem, ale duši lačné každá hořkost sladká.'),
(1563437,54,20,27,8,'Jako pták zaletuje od hnízda svého, tak muž odchází od místa svého.'),
(1563438,54,20,27,9,'Mast a kadění obveseluje srdce; tak sladkost přítele víc než rada vlastní.'),
(1563439,54,20,27,10,'Přítele svého a přítele otce svého neopouštěj, a do domu bratra svého nechoď v čas bídy své; lepšíť jest soused blízký, než bratr daleký.'),
(1563440,54,20,27,11,'Buď moudrý, synu můj, a obvesel srdce mé, ať mám co odpovědíti tomu, kdož mi utrhá.'),
(1563441,54,20,27,12,'Opatrný vida zlé, vyhne se, ale hloupí předce jdouce, těžkosti docházejí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563442,54,20,27,13,'Vezmi roucho toho, kterýž slíbil za cizího, a od toho, kdo za cizozemku slíbil, základ jeho.'),
(1563443,54,20,27,14,'Tomu, kdož dobrořečí příteli svému hlasem velikým, ráno vstávaje, za zlořečení počteno bude.'),
(1563444,54,20,27,15,'Kapání ustavičné v čas přívalu, a žena svárlivá rovní jsou sobě;'),
(1563445,54,20,27,16,'Kdož ji schovává, schovává vítr, a jako mast v pravici voněti bude.'),
(1563446,54,20,27,17,'Železo železem se ostří; tak muž zostřuje tvář přítele svého.'),
(1563447,54,20,27,18,'Kdo ostříhá fíku, jídá ovoce jeho; tak kdo ostříhá pána svého, poctěn bude.'),
(1563448,54,20,27,19,'Jakož u vodě tvář proti tváři se ukazuje, tak srdce člověka člověku.'),
(1563449,54,20,27,20,'Propast a zahynutí nebývají nasyceni, tak oči člověka nasytiti se nemohou.'),
(1563450,54,20,27,21,'Teglík stříbra a pec zlata zkušuje, tak člověka pověst chvály jeho.'),
(1563451,54,20,27,22,'Bys blázna i v stupě mezi krupami píchem zopíchal, neodejde od něho bláznovství jeho.'),
(1563452,54,20,27,23,'Pilně přihlídej k dobytku svému, pečuj o stáda svá.'),
(1563453,54,20,27,24,'Nebo ne na věky trvá bohatství, ani koruna do pronárodu.'),
(1563454,54,20,27,25,'Když zroste tráva, a ukazuje se bylina, tehdáž ať se shromažďuje seno s hor.'),
(1563455,54,20,27,26,'Beránkové budou k oděvu tvému, a záplata pole kozelci.'),
(1563456,54,20,27,27,'Nadto dostatek mléka kozího ku pokrmu tvému, ku pokrmu domu tvého, a živnosti děvek tvých.'),
(1563457,54,20,28,1,'Utíkají bezbožní, ač jich žádný nehoní, ale spravedliví jako mladý lev smělí jsou.'),
(1563458,54,20,28,2,'Pro přestoupení země mnoho knížat jejích, ale pro člověka rozumného a umělého trvánlivé bývá panování.'),
(1563459,54,20,28,3,'Muž chudý, kterýž utiská nuzné, podoben jest přívalu zachvacujícímu, za čímž nebývá chleba.'),
(1563460,54,20,28,4,'Kteří opouštějí zákon, chválí bezbožného, ale kteříž ostříhají zákona, velmi jsou jim na odpor.'),
(1563461,54,20,28,5,'Lidé zlí nesrozumívají soudu, ti pak, kteříž hledají Hospodina, rozumějí všemu.'),
(1563462,54,20,28,6,'Lepší jest chudý, kterýž chodí v upřímnosti své, než převrácený na kterékoli cestě, ačkoli jest bohatý.'),
(1563463,54,20,28,7,'Kdo ostříhá zákona, jest syn rozumný; kdož pak s žráči tovaryší, hanbu činí otci svému.'),
(1563464,54,20,28,8,'Kdo rozmnožuje statek svůj lichvou a úrokem, shromažďuje tomu, kdož by jej z milosti chudým rozděloval.'),
(1563465,54,20,28,9,'Kdo odvrací ucho své, aby neslyšel zákona, i modlitba jeho jest ohavností.'),
(1563466,54,20,28,10,'Kdo zavodí upřímé na cestu zlou, do jámy své sám vpadne, ale upřímí dědičně obdrží dobré.'),
(1563467,54,20,28,11,'Moudrý jest u sebe sám muž bohatý, ale chudý rozumný vystihá jej.'),
(1563468,54,20,28,12,'Když plésají spravedliví, velmi to pěkně sluší; ale když povstávají bezbožní, vyhledáván bývá člověk.'),
(1563469,54,20,28,13,'Kdo přikrývá přestoupení svá, nepovede se jemu šťastně; ale kdož je vyznává a opouští, milosrdenství důjde.'),
(1563470,54,20,28,14,'Blahoslavený člověk, kterýž se strachuje vždycky; ale kdož zatvrzuje srdce své, upadne ve zlé.'),
(1563471,54,20,28,15,'Lev řvoucí a nedvěd hladovitý jest panovník bezbožný nad lidem nuzným.'),
(1563472,54,20,28,16,'Kníže bez rozumu bývá veliký dráč, ale kdož v nenávisti má mrzký zisk, prodlí dnů.'),
(1563473,54,20,28,17,'Člověka, kterýž násilí činí krvi lidské, ani nad jamou, když utíká, žádný ho nezadrží.'),
(1563474,54,20,28,18,'Kdo chodí upřímě, zachován bude, převrácený pak na kterékoli cestě padne pojednou.'),
(1563475,54,20,28,19,'Kdo dělá zemi svou, nasycen bývá chlebem; ale kdož následuje zahalečů, nasycen bývá chudobou.'),
(1563476,54,20,28,20,'Muž věrný přispoří požehnání, ale kdož chvátá zbohatnouti, nebývá bez viny.'),
(1563477,54,20,28,21,'Přijímati osobu není dobré; nebo mnohý pro kus chleba neprávě činí.'),
(1563478,54,20,28,22,'Člověk závistivý chvátá k statku, nic nevěda, že nouze na něj přijde.'),
(1563479,54,20,28,23,'Kdo domlouvá člověku, potom spíše milost nalézá nežli ten, kterýž lahodí jazykem.'),
(1563480,54,20,28,24,'Kdo loupí otce svého a matku svou, a říká, že to není žádný hřích, tovaryš jest vražedlníka.'),
(1563481,54,20,28,25,'Vysokomyslný vzbuzuje svár, ale kdo doufá v Hospodina, hojnost míti bude.'),
(1563482,54,20,28,26,'Kdo doufá v srdce své, blázen jest; ale kdož chodí moudře, pomůže sobě.'),
(1563483,54,20,28,27,'Kdo dává chudému, nebude míti žádného nedostatku; kdož pak zakrývá oči své, bude míti množství zlořečení.'),
(1563484,54,20,28,28,'Když povstávají bezbožní, skrývá se člověk; ale když hynou, rozmnožují se spravedliví.'),
(1563485,54,20,29,1,'Člověk, kterýž často kárán bývaje, zatvrzuje šíji, rychle potřín bude, tak že neprospěje žádné lékařství.'),
(1563486,54,20,29,2,'Když se množí spravedliví, veselí se lid; ale když panuje bezbožník, vzdychá lid.'),
(1563487,54,20,29,3,'Muž, kterýž miluje moudrost, obveseluje otce svého; ale kdož se přitovaryšuje k nevěstkám, mrhá statek.'),
(1563488,54,20,29,4,'Král soudem upevňuje zemi, muž pak, kterýž béře dary, boří ji.'),
(1563489,54,20,29,5,'Člověk, kterýž pochlebuje příteli svému, rozprostírá sít před nohama jeho.'),
(1563490,54,20,29,6,'Výstupek bezbožného jest jemu osídlem, spravedlivý pak prozpěvuje a veselí se.'),
(1563491,54,20,29,7,'Spravedlivý vyrozumívá při nuzných, ale bezbožník nemá s to rozumnosti ani umění.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563492,54,20,29,8,'Muži posměvači zavozují město, ale moudří odvracují hněv.'),
(1563493,54,20,29,9,'Muž moudrý, kterýž se nesnadní s mužem bláznivým, buď že se pohne, buď že se směje, nemá pokoje.'),
(1563494,54,20,29,10,'Vražedlníci v nenávisti mají upřímého, ale upřímí pečují o duši jeho.'),
(1563495,54,20,29,11,'Všecken duch svůj vypouští blázen, ale moudrý na potom zdržuje jej.'),
(1563496,54,20,29,12,'Pána toho, kterýž rád poslouchá slov lživých, všickni služebníci jsou bezbožní.'),
(1563497,54,20,29,13,'Chudý a dráč potkávají se, obou dvou však oči osvěcuje Hospodin.'),
(1563498,54,20,29,14,'Krále toho, kterýž soudí právě nuzné, trůn na věky bývá utvrzen.'),
(1563499,54,20,29,15,'Metla a kárání dává moudrost, ale dítě sobě volné k hanbě přivodí matku svou.'),
(1563500,54,20,29,16,'Když se rozmnožují bezbožní, rozmnožuje se převrácenost, a však spravedliví spatřují pád jejich.'),
(1563501,54,20,29,17,'Tresci syna svého, a přineseť odpočinutí, a způsobí rozkoš duši tvé.'),
(1563502,54,20,29,18,'Když nebývá vidění, rozptýlen bývá lid; kdož pak ostříhá zákona, blahoslavený jest.'),
(1563503,54,20,29,19,'Slovy nebývá napraven služebník; nebo rozuměje, však neodpoví.'),
(1563504,54,20,29,20,'Spatřil-li bys člověka, an jest kvapný v věcech svých, lepší jest naděje o bláznu, než o takovém.'),
(1563505,54,20,29,21,'Kdo rozkošně chová z dětinství služebníka svého, naposledy bude syn.'),
(1563506,54,20,29,22,'Člověk hněvivý vzbuzuje svár, a prchlivý mnoho hřeší.'),
(1563507,54,20,29,23,'Pýcha člověka snižuje jej, ale chudý duchem dosahuje slávy.'),
(1563508,54,20,29,24,'Kdo má spolek s zlodějem, v nenávisti má duši svou; zlořečení slyší, však neoznámí.'),
(1563509,54,20,29,25,'Strašlivý člověk klade sobě osídlo, ale kdo doufá v Hospodina, bývá povýšen.'),
(1563510,54,20,29,26,'Mnozí hledají tváři pánů, ješto od Hospodina jest soud jednoho každého.'),
(1563511,54,20,29,27,'Ohavností spravedlivým jest muž nepravý, ohavností pak bezbožnému, kdož upřímě kráčí.'),
(1563512,54,20,30,1,'Slova Agura, syna Jáke. Sepsání řečí muže toho k Itielovi, k Itielovi a Uchalovi.'),
(1563513,54,20,30,2,'Jistě žeť jsem hloupější nad jiné, tak že rozumnosti člověka obecného nemám,'),
(1563514,54,20,30,3,'Aniž jsem se naučil moudrosti, a umění svatých neumím.'),
(1563515,54,20,30,4,'Kdo vstoupil v nebe, i sstoupil? Kdo sebral vítr do hrstí svých? Kdo shrnul vody v roucho své? Kdo upevnil všecky končiny země? Které jméno jeho, a jaké jméno syna jeho, víš-li?'),
(1563516,54,20,30,5,'Všeliká výmluvnost Boží přečištěná jest; onť jest štít doufajících v něho.'),
(1563517,54,20,30,6,'Nepřidávej k slovům jeho, aby tě nekáral, a byl bys ve lži postižen.'),
(1563518,54,20,30,7,'Dvou věcí žádám od tebe, neoslýchejž mne, prvé než umru:'),
(1563519,54,20,30,8,'Marnost a slovo lživé vzdal ode mne, chudoby neb bohatství nedávej mi, živ mne pokrmem vedlé potřeby mé,'),
(1563520,54,20,30,9,'Abych snad nasycen jsa, tě nezapřel, a neřekl: Kdo jest Hospodin? a abych zchudna, nekradl, a nebral naprázdno jména Hospodina Boha svého.'),
(1563521,54,20,30,10,'Nesoč na služebníka před pánem jeho, aťby nezlořečil, a ty abys nehřešil.'),
(1563522,54,20,30,11,'Jest pokolení, kteréž otci svému zlořečí, a matce své nedobrořečí.'),
(1563523,54,20,30,12,'Jest pokolení čisté samo u sebe, ačkoli od nečistot svých není obmyto.'),
(1563524,54,20,30,13,'Jest pokolení, jehož vysoké jsou oči, a víčka jeho jsou vyzdvižená.'),
(1563525,54,20,30,14,'Jest pokolení, jehož zubové jsou mečové, a třenovní zubové jeho nožové, k zžírání chudých na zemi a nuzných na světě.'),
(1563526,54,20,30,15,'Pijavice má dvě dcery říkající: Dej, dej. Tři věci nebývají nasyceny, anobrž čtyry, kteréž nikdy neřeknou: Dosti:'),
(1563527,54,20,30,16,'Peklo a život neplodné, země též nebývá nasycena vodou, a oheň neříká: Dosti.'),
(1563528,54,20,30,17,'Oko, kteréž se posmívá otci, a pohrdá poslušenstvím matky, vyklubí krkavci potoční, aneb snědí je orličata.'),
(1563529,54,20,30,18,'Tři tyto věci skryty jsou přede mnou, nýbrž čtyry, kterýchž neznám:'),
(1563530,54,20,30,19,'Cesty orlice v povětří, cesty hada na skále, cesty lodí u prostřed moře, a cesty muže při panně.'),
(1563531,54,20,30,20,'Takováž jest cesta ženy cizoložné: Jí, a utře ústa svá, a dí: Nepáchala jsem nepravosti.'),
(1563532,54,20,30,21,'Pode třmi věcmi pohybuje se země, anobrž pod čtyřmi, jichž nemůž snésti:'),
(1563533,54,20,30,22,'Pod služebníkem, když kraluje, a bláznem, když se nasytí chleba;'),
(1563534,54,20,30,23,'Pod omrzalou, když se vdá, a děvkou, když dědičkou bývá paní své.'),
(1563535,54,20,30,24,'Čtyry tyto věci jsou malé na zemi, a však jsou moudřejší nad mudrce:'),
(1563536,54,20,30,25,'Mravenci, lid nesilný, kteříž však připravují v létě pokrm svůj;'),
(1563537,54,20,30,26,'Králíkové, lid nesilný, kteříž však stavějí v skále dům svůj;'),
(1563538,54,20,30,27,'Krále nemají kobylky, a však vycházejí po houfích všecky;'),
(1563539,54,20,30,28,'Pavouk rukama dělá, a bývá na palácích královských.'),
(1563540,54,20,30,29,'Tři tyto věci udatně vykračují, anobrž čtyry, kteréž zmužile chodí:'),
(1563541,54,20,30,30,'Lev nejsilnější mezi zvířaty, kterýž neustupuje před žádným;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563542,54,20,30,31,'Přepásaný na bedrách kůň neb kozel, a král, proti němuž žádný nepovstává.'),
(1563543,54,20,30,32,'Jestliže jsi bláznil, vynášeje se, a myslil-lis zle, ruku na ústa polož.'),
(1563544,54,20,30,33,'Kdo tluče smetanu, stlouká máslo, a stiskání nosu vyvodí krev, tak popouzení k hněvu vyvodí svár.'),
(1563545,54,20,31,1,'Slova proroctví Lemuele krále, kterýmž vyučovala jej matka jeho.'),
(1563546,54,20,31,2,'Co dím, synu můj, co, synu života mého? Co, řku, dím, synu slibů mých?'),
(1563547,54,20,31,3,'Nedávej ženám síly své, ani cest svých těm, kteréž k zahynutí přivodí krále.'),
(1563548,54,20,31,4,'Ne králům, ó Lemueli, ne králům náleží píti víno, a ne pánům žádost nápoje opojného,'),
(1563549,54,20,31,5,'Aby pije, nezapomněl na ustanovení, a nezměnil pře všech lidí ssoužených.'),
(1563550,54,20,31,6,'Dejte nápoj opojný hynoucímu, a víno těm, kteříž jsou truchlivého ducha,'),
(1563551,54,20,31,7,'Ať se napije, a zapomene na chudobu svou, a na trápení své nezpomíná více.'),
(1563552,54,20,31,8,'Otevři ústa svá za němého, v při všech oddaných k smrti,'),
(1563553,54,20,31,9,'Otevři, řku, ústa svá, suď spravedlivě, a veď při chudého a nuzného.'),
(1563554,54,20,31,10,'Ženu statečnou kdo nalezne? Nebo daleko nad perly cena její.'),
(1563555,54,20,31,11,'Dověřuje se jí srdce muže jejího; nebo tu kořistí nebude nedostatku.'),
(1563556,54,20,31,12,'Dobře činí jemu a ne zle, po všecky dny života svého.'),
(1563557,54,20,31,13,'Hledá pilně vlny a lnu, a dělá šťastně rukama svýma.'),
(1563558,54,20,31,14,'Jest podobná lodi kupecké, zdaleka přiváží pokrm svůj.'),
(1563559,54,20,31,15,'Kterážto velmi ráno vstávajíc, dává pokrm čeledi své, a podíl náležitý děvkám svým.'),
(1563560,54,20,31,16,'Rozsuzuje pole, a ujímá je; z výdělku rukou svých štěpuje i vinici.'),
(1563561,54,20,31,17,'Přepasuje silou bedra svá, a zsiluje ramena svá.'),
(1563562,54,20,31,18,'Zakouší, jak jest užitečné zaměstknání její; ani v noci nehasne svíce její.'),
(1563563,54,20,31,19,'Rukama svýma sahá k kuželi, a prsty svými drží vřeteno.'),
(1563564,54,20,31,20,'Ruku svou otvírá chudému, a ruce své vztahuje k nuznému.'),
(1563565,54,20,31,21,'Nebojí se za čeled svou v čas sněhu; nebo všecka čeled její obláčí se v roucho dvojnásobní.'),
(1563566,54,20,31,22,'Koberce dělá sobě z kmentu, a z zlatohlavu jest oděv její.'),
(1563567,54,20,31,23,'Patrný jest v branách manžel její, když sedá s staršími země.'),
(1563568,54,20,31,24,'Plátno drahé dělá, a prodává; též i pasy prodává kupci.'),
(1563569,54,20,31,25,'Síla a krása oděv její, nestará se o časy potomní.'),
(1563570,54,20,31,26,'Ústa svá otvírá k moudrosti, a naučení dobrotivosti v jazyku jejím.'),
(1563571,54,20,31,27,'Spatřuje obcování čeledi své, a chleba zahálky nejí.'),
(1563572,54,20,31,28,'Povstanouce synové její, blahoslaví ji; manžel její také chválí ji,'),
(1563573,54,20,31,29,'Říkaje: Mnohé ženy statečně sobě počínaly, ty pak převyšuješ je všecky.'),
(1563574,54,20,31,30,'Oklamavatelná jest příjemnost a marná krása; žena, kteráž se bojí Hospodina, tať chválena bude.'),
(1563575,54,20,31,31,'Dejtež takové z ovoce rukou jejích, a nechať ji chválí v branách skutkové její.'),
(1563576,54,21,1,1,'Slova kazatele syna Davidova, krále v Jeruzalémě.'),
(1563577,54,21,1,2,'Marnost nad marnostmi, řekl kazatel, marnost nad marnostmi, a všecko marnost.'),
(1563578,54,21,1,3,'Jaký užitek má člověk ze všelijaké práce své, kterouž vede pod sluncem?'),
(1563579,54,21,1,4,'Věk pomíjí, a jiný věk nastává, ačkoli země na věky trvá.'),
(1563580,54,21,1,5,'Vychází slunce, i zapadá slunce, a k místu svému chvátá, kdež vychází.'),
(1563581,54,21,1,6,'Jde ku poledni, a obrací se na půlnoci, sem i tam se toče, chodí vítr, a okolky svými navracuje se vítr.'),
(1563582,54,21,1,7,'Všecky řeky jdou do moře, a však se moře nepřeplňuje; do místa, do něhož tekou řeky, navracují se, aby zase odtud vycházely.'),
(1563583,54,21,1,8,'Všecky věci jsou plné zaneprázdnění, aniž může člověk vymluviti; nenasytí se oko hleděním, aniž se naplní ucho slyšením.'),
(1563584,54,21,1,9,'Což bylo, jest to, což býti má; a což se nyní děje, jest to, což se díti bude; aniž jest co nového pod sluncem.'),
(1563585,54,21,1,10,'Jest-liž jaká věc, o níž by říci mohl: Pohleď, toť jest cosi nového? Ano již to bylo před věky, kteříž byli před námi.'),
(1563586,54,21,1,11,'Není paměti prvních věcí, aniž také potomních, kteréž budou, památka zůstane u těch, jenž potom nastanou.'),
(1563587,54,21,1,12,'Já kazatel byl jsem králem nad Izraelem v Jeruzalémě,'),
(1563588,54,21,1,13,'A přiložil jsem mysl svou k tomu, jak bych vyhledati a vystihnouti mohl rozumností svou všecko to, což se děje pod nebem. (Takové bídné zaměstknání dal Bůh synům lidským, aby se jím bědovali.)'),
(1563589,54,21,1,14,'Viděl jsem všecky skutky, dějící se pod sluncem, a aj, všecko jest marnost a trápení ducha.'),
(1563590,54,21,1,15,'Což křivého jest, nemůže se zpřímiti, a nedostatkové nemohou sečteni býti.'),
(1563591,54,21,1,16,'Protož tak jsem myslil v srdci svém, řka: Aj, já zvelebil jsem a rozšířil moudrost nade všecky, kteříž byli přede mnou v Jeruzalémě, a srdce mé dosáhlo množství moudrosti a umění.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563592,54,21,1,17,'I přiložil jsem mysl svou, abych poznal moudrost a umění, nemoudrost i bláznovství, ale shledal jsem, že i to jest trápení ducha.'),
(1563593,54,21,1,18,'Nebo kde jest mnoho moudrosti, tu mnoho hněvu; a kdož rozmnožuje umění, rozmnožuje bolest.'),
(1563594,54,21,2,1,'Řekl jsem opět srdci svému: Nuže nyní zkusím tě v veselí, užívejž tedy dobrých věcí. A hle, i to marnost.'),
(1563595,54,21,2,2,'Smíchu jsem řekl: Blázníš, a veselí: Co to děláš?'),
(1563596,54,21,2,3,'Přemyšloval jsem v srdci svém, abych povoloval u víně tělu svému, srdce však své spravuje moudrostí, a přídržel se bláznovství dotud, až bych zkusil, co by lepšího bylo synům lidským, aby činili pod nebem v počtu dnů života svého.'),
(1563597,54,21,2,4,'Veliké jsem skutky činil, vystavěl jsem sobě domy, štípil jsem sobě vinice.'),
(1563598,54,21,2,5,'Vzdělal jsem sobě zahrady a štěpnice, a štípil jsem v nich stromy všelijakého ovoce.'),
(1563599,54,21,2,6,'Nadělal jsem sobě rybníků, abych svlažoval jimi les plodící dříví.'),
(1563600,54,21,2,7,'Najednal jsem sobě služebníků a děvek, a měl jsem čeled v domě svém; k tomu i stáda skotů a bravů veliká měl jsem nade všecky, kteříž byli přede mnou v Jeruzalémě.'),
(1563601,54,21,2,8,'Nahromáždil jsem sobě také stříbra a zlata a klínotů od králů a krajin; způsobil jsem sobě zpěváky a zpěvakyně i jiné rozkoše synů lidských a nástroje muzické rozličné.'),
(1563602,54,21,2,9,'A tak velikým jsem učiněn, a zrostl jsem nade všecky, kteříž přede mnou byli v Jeruzalémě; nadto moudrost má zůstávala při mně.'),
(1563603,54,21,2,10,'A čehožkoli žádaly oči mé, nezbránil jsem jim, aniž jsem zbraňoval srdci svému jakého veselí; srdce mé zajisté veselilo se ze vší práce mé, a to byl podíl můj ze vší práce mé.'),
(1563604,54,21,2,11,'Ale jakž jsem se ohlédl na všecky skutky své, kteréž činily ruce mé, a na práci úsilně vedenou, a aj, všecko marnost a trápení ducha, a že nic není užitečného pod sluncem.'),
(1563605,54,21,2,12,'Pročež obrátil jsem se, abych spatřoval moudrost a nemoudrost, i bláznovství. (Nebo co by člověk spravil, chtěje následovati krále? To, což již jiní spravili.)'),
(1563606,54,21,2,13,'I viděl jsem, že jest užitečnější moudrost než bláznovství, tak jako jest užitečnější světlo nežli temnost.'),
(1563607,54,21,2,14,'Moudrý má oči v hlavě své, blázen pak ve tmách chodí; a však poznal jsem, že jednostejné příhody všechněm se přiházejí.'),
(1563608,54,21,2,15,'Protož jsem řekl v srdci svém: Máliť mi se tak díti, jako se děje bláznu, pročež jsem tedy moudrostí předčil? A tak řekl jsem v srdci svém: I to jest marnost.'),
(1563609,54,21,2,16,'Nebo není památka moudrého jako i blázna na věky, proto že to, což nyní jest, ve dnech budoucích všecko v zapomenutí přichází, a že jakož umírá moudrý, tak i blázen.'),
(1563610,54,21,2,17,'Pročež mrzí mne tento život; nebo semi nelíbí nic, což se děje pod sluncem, poněvadž všecky věci jsou marnost a trápení ducha.'),
(1563611,54,21,2,18,'Ano mrzí mne i všecka práce má, kterouž jsem vedl pod sluncem proto že jí zanechati musím člověku, kterýž bude po mně.'),
(1563612,54,21,2,19,'A kdo ví, bude-li moudrý, či blázen? A však panovati bude nade vší prací mou,kterouž jsem vedl, a v níž jsem moudrý byl pod sluncem. A i to marnost.'),
(1563613,54,21,2,20,'I přišel jsem na to, abych pochybil v srdci svém o vší práci, kterouž jsem konal, a v níž jsem moudrý byl pod sluncem.'),
(1563614,54,21,2,21,'Mnohý zajisté člověk pracuje moudře, uměle a spravedlivě, a však jinému, kterýž nepracoval o tom, nechává toho za podíl jemu, ješto i to jest marnost a bídná věc.'),
(1563615,54,21,2,22,'Nebo co má člověk ze vší práce své a z kvaltování srdce svého, kteréž snáší pod sluncem,'),
(1563616,54,21,2,23,'Poněvadž všickni dnové jeho bolestní, a zaměstknání jeho hněv, tak že ani v noci neodpočívá srdce jeho? A i to marnost.'),
(1563617,54,21,2,24,'Zdaliž není to chvalitebné při člověku, jísti a píti, a učiniti životu svému pohodlí z práce své? Ač i to také viděl jsem, že z ruky Boží pochází.'),
(1563618,54,21,2,25,'Nebo kdož by jísti a užívati měl toho nežli já?'),
(1563619,54,21,2,26,'Člověku zajisté, kterýž se líbí jemu, dává moudrost, umění a veselí; hříšníku pak dává trápení, aby shromažďoval a hrnul, čehož by zanechal tomu, kterýž se líbí Bohu. I to také jest marnost a trápení ducha.'),
(1563620,54,21,3,1,'Všeliká věc má jistý čas, a každé předsevzetí pod nebem svou chvíli.'),
(1563621,54,21,3,2,'Jest čas rození i čas umírání, čas sázení a čas vykopání, což vsazeno bývá;'),
(1563622,54,21,3,3,'Čas mordování a čas hojení, čas boření a čas stavení;'),
(1563623,54,21,3,4,'Čas pláče a čas smíchu, čas smutku a čas proskakování;'),
(1563624,54,21,3,5,'Čas rozmítání kamení a čas shromažďování kamení, čas objímání a čas vzdálení se od objímání;'),
(1563625,54,21,3,6,'Čas hledání a čas ztracení, čas chování a čas zavržení;'),
(1563626,54,21,3,7,'Čas roztrhování a čas sšívání, čas mlčení a čas mluvení;'),
(1563627,54,21,3,8,'Čas milování a čas nenávidění, čas boje a čas pokoje.'),
(1563628,54,21,3,9,'Co tedy má ten, kdo práci vede, z toho, o čemž pracuje?'),
(1563629,54,21,3,10,'Viděl jsem zaměstknání, kteréž dal Bůh synům lidským, aby se jím trápili.'),
(1563630,54,21,3,11,'Sám všecko činí ušlechtile časem svým, nýbrž i žádost světa dal v srdce jejich, aby nestihal člověk díla toho, kteréž dělá Bůh, ani počátku ani konce.'),
(1563631,54,21,3,12,'Odtud seznávám, že nic lepšího nemají, než aby se veselili, a činili dobře v životě svém,'),
(1563632,54,21,3,13,'Ač i to, když všeliký člověk jí a pije, a užívá dobrých věcí ze všelijaké práce své, jest dar Boží.'),
(1563633,54,21,3,14,'Znám, že cožkoli činí Bůh, to trvá na věky; nemůže se k tomu nic přidati, ani od toho co odjíti. A činí to Bůh, aby se báli oblíčeje jeho.'),
(1563634,54,21,3,15,'To, což bylo, i nyní jest, a což bude, již bylo; nebo Bůh obnovuje to, což pominulo.'),
(1563635,54,21,3,16,'Přesto viděl jsem ještě pod sluncem na místě soudu bezbožnost, a na místě spravedlnosti nespravedlnost.'),
(1563636,54,21,3,17,'I řekl jsem v srdci svém: Budeť Bůh spravedlivého i bezbožného souditi; nebo tam bude čas každému předsevzetí i každému skutku.'),
(1563637,54,21,3,18,'Řekl jsem v srdci svém o způsobu synů lidských, že jim ukázal Bůh, aby viděli, že jsou podobni hovadům.'),
(1563638,54,21,3,19,'Případnost synů lidských a případnost hovad jest případnost jednostejná. Jakož umírá ono, tak umírá i on, a dýchání jednostejné všickni mají, aniž co napřed má člověk před hovadem; nebo všecko jest marnost.'),
(1563639,54,21,3,20,'Obé to jde k místu jednomu; obé jest z prachu, obé také zase navracuje se do prachu.'),
(1563640,54,21,3,21,'Kdo to zná, že duch synů lidských vstupuje zhůru, a duch hovadí že sstupuje pod zemi?'),
(1563641,54,21,3,22,'Protož spatřil jsem, že nic není lepšího, než veseliti se člověku v skutcích svých, poněvadž to jest podíl jeho. Nebo kdo jej k tomu přivede, aby poznati mohl to, což jest budoucího po něm?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563642,54,21,4,1,'Opět obrátiv se, i viděl jsem všeliká ssoužení, kteráž se dějí pod sluncem, a aj, slzy křivdu trpících, ješto nemají potěšitele, ani moci k vyjití z ruky těch, kteříž je ssužují, a nemají potěšitele.'),
(1563643,54,21,4,2,'Protož já chválil jsem mrtvé, kteříž již zemřeli, více nežli živé, kteříž jsou živi až po dnes.'),
(1563644,54,21,4,3,'Nýbrž nad oba tyto šťastnější jest ten, kterýž ještě nebyl, a neviděl skutku zlého, dějícího se pod sluncem.'),
(1563645,54,21,4,4,'Nebo spatřil jsem všelikou práci a každé dobré dílo, že jest k závisti jedněch druhým. I to také jest marnost a trápení ducha.'),
(1563646,54,21,4,5,'Blázen skládá ruce své, a jí maso své, říkaje:'),
(1563647,54,21,4,6,'Lepší jest plná hrst s odpočinutím,nežli přehršlí plné s prací a trápením ducha.'),
(1563648,54,21,4,7,'Opět obrátiv se, viděl jsem jinou marnost pod sluncem:'),
(1563649,54,21,4,8,'Jest samotný někdo, nemaje žádného, ani syna, ani bratra, a však není konce všeliké práci jeho, ani oči jeho nemohou se nasytiti bohatství. Nepomyslí: Komu já pracuji, tak že i životu svému ujímám pohodlí? I to také jest marnost a bídné zaneprázdnění.'),
(1563650,54,21,4,9,'Lépeť jest dvěma než jednomu; mají zajisté dobrý užitek z práce své.'),
(1563651,54,21,4,10,'Nebo padne-li který z nich, druhý pozdvihne tovaryše svého. Běda tedy samotnému, když by padl; nebo nemá druhého, aby ho pozdvihl.'),
(1563652,54,21,4,11,'Také budou-li dva spolu ležeti, zahřejí se, ale jeden jak se zahřeje?'),
(1563653,54,21,4,12,'Ovšem, jestliže by se kdo jednoho zmocniti chtěl, dva postaví se proti němu; ano trojnásobní provázek nesnadně se přetrhne.'),
(1563654,54,21,4,13,'Lepší jest dítě chudé a moudré, než král starý a blázen, kterýž neumí již ani napomenutí přijímati,'),
(1563655,54,21,4,14,'Ačkoli z žaláře vychází, aby kraloval, nýbrž i v království svém může na chudobu přijíti.'),
(1563656,54,21,4,15,'Viděl jsem všecky živé, kteříž chodí pod sluncem, ani se přídrželi pacholete, potomka onoho, kterýž měl kralovati místo něho.'),
(1563657,54,21,4,16,'Nebývalo konce té vrtkosti všeho lidu, jakž toho, kterýž byl před nimi, takž ani potomci nebudou se těšiti z něho. Protož i to jest marnost a trápení ducha.'),
(1563658,54,21,5,1,'Ostříhej nohy své, když jdeš do domu Božího, a buď hotovější k slyšení nežli k dávání obětí bláznů; nebo oni neznají toho, že zle činí.'),
(1563659,54,21,5,2,'Nebývej rychlý k mluvení, ani srdce tvé kvapné k vynášení slova před oblíčejem Božím, poněvadž Bůh jest na nebi, a ty na zemi; protož nechť jsou slova tvá nemnohá.'),
(1563660,54,21,5,3,'Nebo jakož přichází sen z velikého pracování, tak hlas blázna z množství slov.'),
(1563661,54,21,5,4,'Když bys učinil slib Bohu, neprodlévej ho splniti, nebo nemá líbosti v blázních. Cožkoli slíbíš, splň.'),
(1563662,54,21,5,5,'Lépe jest, abys nesliboval, než abys slibě, neplnil.'),
(1563663,54,21,5,6,'Nedopouštěj ústům svým, aby k hříchu přivodila tělo tvé, aniž říkej před andělem, že to jest poblouzení. Proč máš hněvati Boha řečí svou, kterýž by na zkázu přivedl dílo rukou tvých?'),
(1563664,54,21,5,7,'Nebo kdež jest mnoho snů, tu i marnosti a slova mnohá, ale ty Boha se boj.'),
(1563665,54,21,5,8,'Jestliže bys nátisk chudého a zadržení soudu a spravedlnosti spatřil v krajině, nediv se té věci; nebo vyšší vysokého šetří, a ještě vyšší nad nimi.'),
(1563666,54,21,5,9,'Zemský pak obchod u všech přední místo má; i král rolí slouží.'),
(1563667,54,21,5,10,'Kdo miluje peníze, nenasytí se penězi; a kdo miluje hojnost, nebude míti užitku. I to jest marnost.'),
(1563668,54,21,5,11,'Kde jest mnoho statku, mnoho bývá i těch, kteříž jedí jej. Jakýž tedy má užitek pán jeho? Jediné, že očima svýma hledí na něj.'),
(1563669,54,21,5,12,'Sladký jest sen pracovitému, jez on málo neb mnoho, ale sytost bohatého nedopouští mu spáti.'),
(1563670,54,21,5,13,'Jest přebídná věc, kterouž jsem viděl pod sluncem: Bohatství nachované tomu, kdož je má, k jeho zlému.'),
(1563671,54,21,5,14,'Nebo hyne bohatství takové pro zlou správu; syn, kteréhož zplodí, nebude míti v ruce své ničeho.'),
(1563672,54,21,5,15,'Jakž vyšel z života matky své nahý, tak zase odchází, jakž přišel, aniž čeho odnáší z práce své, což by vzal v ruku svou.'),
(1563673,54,21,5,16,'A toť jest také přebídná věc, že rovně, jakž přišel, tak odjíti musí. Protož jaký užitek míti bude toho, že pracoval u vítr?'),
(1563674,54,21,5,17,'K tomu, že po všecky dny své v temnostech jídal, s mnohým zůřením, nemocí a hněvem?'),
(1563675,54,21,5,18,'Aj, toť jsem já spatřil, že dobrá a čistá jest věc jísti a píti a užívati pohodlí ze vší práce své, kterouž kdo vede pod sluncem v počtu dnů života svého, kteréž dal jemu Bůh, nebo to jest podíl jeho;'),
(1563676,54,21,5,19,'A že kterémukoli člověku dal Bůh bohatství a zboží, a dopustil, aby užíval jich, a bral díl svůj, a veselil se z práce své, to jest dar Boží.'),
(1563677,54,21,5,20,'Nebo nebude mnoho pamatovati na dny života svého, proto že Bůh jemu přeje veselí srdce jeho.'),
(1563678,54,21,6,1,'Jest bídná věc, kterouž jsem viděl pod sluncem, a lidem obyčejná:'),
(1563679,54,21,6,2,'Kterému člověku dal Bůh bohatství a zboží i slávu, tak že nemá nedostatku duše jeho v ničemž, čehokoli žádá, a však nedopouští mu Bůh užívati těch věcí, ale jiný leckdos sžíře to, a toť jest marnost a bídná věc.'),
(1563680,54,21,6,3,'Zplodil-li by kdo sto synů, a byl by živ mnoho let, jakkoli rozmnoženi jsou dnové let jeho, nebyl-li život jeho nasycen dobrými věcmi, a neměl by ani pohřbu, pravím, že šťastnější jest nedochůdče nežli on.'),
(1563681,54,21,6,4,'Nebo ono v zmaření přicházeje, do temností odchází, a jméno jeho temnostmi přikryto bývá.'),
(1563682,54,21,6,5,'Nýbrž ani slunce nevídá, aniž čeho poznává, a tak odpočinutí má lepší nežli onen.'),
(1563683,54,21,6,6,'A byť pak byl živ dva tisíce let, a pohodlí by neužil, zdaliž k jednomu místu všickni neodcházejí?'),
(1563684,54,21,6,7,'Všecka práce člověka jest pro ústa jeho, a však duše jeho nemůže se nasytiti.'),
(1563685,54,21,6,8,'Nebo co má více moudrý nežli blázen? A co chudý, kterýž se umí chovati mezi lidmi?'),
(1563686,54,21,6,9,'Lépe jest viděti nežli žádati, ale i to jest marnost a trápení ducha.'),
(1563687,54,21,6,10,'Čímžkoli jest, dávno jest tím nazván, a známé bylo, že člověk býti měl, a že se nebude moci souditi s silnějším, nežli jest sám.'),
(1563688,54,21,6,11,'A poněvadž předsevzetí mnohá rozmnožují marnost, co na tom má člověk?'),
(1563689,54,21,6,12,'Nebo kdo ví, co by bylo dobrého člověku v tomto životě, v počtu dnů marného života jeho, kteříž pomíjejí jako stín? Aneb kdo oznámí člověku, co se díti bude po něm pod sluncem?'),
(1563690,54,21,7,1,'Lepší jest jméno dobré nežli mast výborná, a den smrti než den narození člověka.'),
(1563691,54,21,7,2,'Lépe jest jíti do domu zámutku, nežli jíti do domu hodování, pro dokonání každého člověka, a kdož jest živ, složí to v srdci svém.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563692,54,21,7,3,'Lepší jest horlení nežli smích; nebo zůřivá tvář polepšuje srdce.'),
(1563693,54,21,7,4,'Srdce moudrých v domě zámutku, ale srdce bláznů v domě veselí.'),
(1563694,54,21,7,5,'Lépe jest slyšeti žehrání moudrého,nežli aby někdo poslouchal písně bláznů.'),
(1563695,54,21,7,6,'Nebo jako praštění trní pod hrncem, tak smích blázna. A i to jest marnost.'),
(1563696,54,21,7,7,'Ssužování zajisté k bláznovství přivodí moudrého, a dar oslepuje srdce.'),
(1563697,54,21,7,8,'Lepší jest skončení věci nežli počátek její; lepší jest dlouho čekající nežli vysokomyslný.'),
(1563698,54,21,7,9,'Nebuď kvapný v duchu svém k hněvu; nebo hněv v lůnu bláznů odpočívá.'),
(1563699,54,21,7,10,'Neříkej: Čím jest to, že dnové první lepší byli nežli tito? Nebo bys se nemoudře na to vytazoval.'),
(1563700,54,21,7,11,'Dobrá jest moudrost s statkem, a velmi užitečná těm, kteříž vidí slunce;'),
(1563701,54,21,7,12,'Nebo v stínu moudrosti a v stínu stříbra odpočívají. A však přednější jest umění moudrosti, přináší život těm, kdož ji mají.'),
(1563702,54,21,7,13,'Hleď na skutky Boží. Nebo kdo může zpřímiti to, což on zkřivil?'),
(1563703,54,21,7,14,'V den dobrý užívej dobrých věcí, a v den zlý buď bedliv; nebo i to naproti onomu učinil Bůh z té příčiny, aby nenalezl člověk po něm ničeho.'),
(1563704,54,21,7,15,'Všecko to viděl jsem za dnů marnosti své: Bývá spravedlivý, kterýž hyne s spravedlností svou; tolikéž bývá bezbožný, kterýž dlouho živ jest v zlosti své.'),
(1563705,54,21,7,16,'Nebývej příliš spravedlivý, aniž buď příliš moudrý. Proč máš na zkázu přicházeti?'),
(1563706,54,21,7,17,'Nebuď příliš starostlivý, aniž bývej bláznem. Proč máš umírati dříve času svého?'),
(1563707,54,21,7,18,'Dobréť jest, abys se onoho přídržel, a tohoto se nespouštěl; nebo kdo se bojí Boha, ujde všeho toho.'),
(1563708,54,21,7,19,'Moudrost posiluje moudrého nad desatero knížat, kteříž jsou v městě.'),
(1563709,54,21,7,20,'Není zajisté člověka spravedlivého na zemi, kterýž by činil dobře a nehřešil.'),
(1563710,54,21,7,21,'Také ne ke všechněm slovům, kteráž mluví lidé, přikládej mysli své, poněvadž nemáš dbáti, by i služebník tvůj zlořečil tobě.'),
(1563711,54,21,7,22,'Neboť ví srdce tvé, že jsi i ty častokrát zlořečil jiným.'),
(1563712,54,21,7,23,'Všeho toho zkusil jsem moudrostí, a řekl jsem: Budu moudrým, ale moudrost vzdálila se ode mne.'),
(1563713,54,21,7,24,'Což pak vzdálené a velmi hluboké jest, kdož to najíti může?'),
(1563714,54,21,7,25,'Všecko jsem přeběhl myslí svou, abych poznal a vyhledal, i vynalezl moudrost a rozumnost, a abych poznal bezbožnost, bláznovství a nemoudrost i nesmyslnost.'),
(1563715,54,21,7,26,'I našel jsem věc hořčejší nad smrt, ženu, jejíž srdce tenata, a ruce její okovy. Kdož se líbí Bohu, zachován bývá od ní, ale hříšník bývá od ní jat.'),
(1563716,54,21,7,27,'Pohleď, to jsem shledal, (praví kazatel), jedno proti druhému stavěje, abych nalezl umění,'),
(1563717,54,21,7,28,'Čeho pak přesto hledala duše má, však jsem nenalezl: Muže jednoho z tisíce našel jsem, ale ženy mezi tolika jsem nenalezl.'),
(1563718,54,21,7,29,'Obzvláštně pohleď i na to, což jsem nalezl: Že učinil Bůh člověka dobrého, ale oni následovali smyšlínek rozličných.'),
(1563719,54,21,7,30,'Kdo se může vrovnati moudrému, a kdo může vykládati všelikou věc?'),
(1563720,54,21,8,1,'Moudrost člověka osvěcuje oblíčej jeho, a nestydatost tváři jeho proměňuje.'),
(1563721,54,21,8,2,'Jáť radím: Výpovědi královské ostříhej, a však podlé přísahy Boží.'),
(1563722,54,21,8,3,'Nepospíchej odjíti od tváři jeho, aniž trvej v zpouře; nebo cožť by koli chtěl, učinil by.'),
(1563723,54,21,8,4,'Nebo kde slovo královské, tu i moc jeho, a kdo dí jemu: Co děláš?'),
(1563724,54,21,8,5,'Kdo ostříhá přikázaní, nezví o ničem zlém. I čas i příčiny zná srdce moudrého.'),
(1563725,54,21,8,6,'Nebo všeliké předsevzetí má čas a příčiny. Ale i to neštěstí veliké člověka se přídrží,'),
(1563726,54,21,8,7,'Že neví, co budoucího jest. Nebo jak se stane, kdo mu oznámí?'),
(1563727,54,21,8,8,'Není člověka, kterýž by moci měl nad životem, aby zadržel duši, aniž má moc nade dnem smrti; nemá ani braně v tom boji, aniž vysvobodí bezbožnost bezbožného.'),
(1563728,54,21,8,9,'Ve všem tom viděl jsem, přiloživ mysl svou ke všemu tomu, co se děje pod sluncem, že časem panuje člověk nad člověkem k jeho zlému.'),
(1563729,54,21,8,10,'A tehdáž viděl jsem bezbožné pohřbené, že se zase navrátili, ale kteříž z místa svatého odešli, v zapomenutí dáni jsou v městě tom, v kterémž dobře činili. I to také jest marnost.'),
(1563730,54,21,8,11,'Nebo že ne i hned ortel dochází pro skutek zlý, protož vroucí jest k tomu srdce synů lidských, aby činili zlé věci.'),
(1563731,54,21,8,12,'A ačkoli hříšník činí zle na stokrát, a vždy se mu odkládá, já však vím, že dobře bude bojícím se Boha, kteříž se bojí oblíčeje jeho.'),
(1563732,54,21,8,13,'S bezbožným pak nedobře se díti bude, aniž se prodlí dnové jeho; minou jako stín, proto že jest bez bázně před oblíčejem Božím.'),
(1563733,54,21,8,14,'Jest marnost, kteráž se děje na zemi: Že bývají spravedliví, jimž se však vede, jako by činili skutky bezbožných; zase bývají bezbožní, kterýmž se však vede, jako by činili skutky spravedlivých. Protož jsem řekl: I to také jest marnost.'),
(1563734,54,21,8,15,'A tak chválil jsem veselí, proto že nic nemá lepšího člověk pod sluncem, jediné aby jedl a pil, a veselil se, a že to pozůstává jemu z práce jeho ve dnech života jeho, kteréž dal jemu Bůh pod sluncem.'),
(1563735,54,21,8,16,'A ač jsem se vydal srdcem svým na to, abych moudrost vystihnouti mohl, a vyrozuměti bídě, kteráž bývá na zemi, pro kterouž ani ve dne ani v noci nespí,'),
(1563736,54,21,8,17,'A však viděl jsem při každém skutku Božím, že nemůže člověk vystihnouti skutku dějícího se pod sluncem. O čež pracuje člověk, vyhledati chtěje, ale nenalézá; nýbrž byť i myslil moudrý, že se doví, nebude moci nic najíti.'),
(1563737,54,21,9,1,'Všecko to zajisté rozvažoval jsem v srdci svém, abych vysvětlil všecko to, že spravedliví a moudří, i skutkové jejich jsou v rukou Božích. Jakož milosti, tak ani nenávisti nezná člověk ze všech věcí, kteréž jsou před oblíčejem jeho.'),
(1563738,54,21,9,2,'Všecko se děje jednostejně při všech; jedna a táž případnost jest spravedlivého jako bezbožného, dobrého a čistého jako nečistého, obětujícího jako toho, kterýž neobětuje, tak dobrého jako hříšníka, přisahajícího jako toho, kterýž se přísahy bojí.'),
(1563739,54,21,9,3,'A toť jest přebídná věc mezi vším tím, což se děje pod sluncem, že případnost jednostejná jest všechněch, ovšem pak že srdce synů lidských plné jest zlého, a že bláznovství přídrží se srdce jejich, pokudž živi jsou, potom pak umírají,'),
(1563740,54,21,9,4,'Ačkoli ten, kterýž tovaryší se všechněmi živými, má naději, an psu živému lépe jest nežli lvu mrtvému.'),
(1563741,54,21,9,5,'Nebo živí vědí, že umříti mají, mrtví pak nevědí nic, aniž více mají odplaty, proto že v zapomenutí přišla památka jejich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563742,54,21,9,6,'Anobrž i milování jejich, i nenávist jejich, i závist jejich zahynula, a již více nemají dílu na věky v žádné věci, kteráž se děje pod sluncem.'),
(1563743,54,21,9,7,'Nuže tedy jez s radostí chléb svůj, a pí s veselou myslí víno své, nebo již oblibuje Bůh skutky tvé.'),
(1563744,54,21,9,8,'Každého času ať jest roucho tvé bílé, a oleje na hlavě tvé nechť není nedostatku.'),
(1563745,54,21,9,9,'Živ buď s manželkou, kterouž jsi zamiloval, po všecky dny života marnosti své, kterýžť dán pod sluncem po všecky dny marnosti tvé; nebo to jest podíl tvůj v životě tomto a při práci tvé, kterouž vedeš pod sluncem.'),
(1563746,54,21,9,10,'Všecko, což by před se vzala ruka tvá k činění, podlé možnosti své konej; nebo není práce ani důmyslu ani umění ani moudrosti v hrobě, do něhož se béřeš.'),
(1563747,54,21,9,11,'A obrátiv se, spatřil jsem pod sluncem, že nezáleží běh na rychlých, ani boj na udatných, nýbrž ani živnost na moudrých, ani bohatství na opatrných, ani přízeň na umělých, ale podlé času a příhody přihází se všechněm.'),
(1563748,54,21,9,12,'Nebo tak nezná člověk času svého jako ryby, kteréž loveny bývají sítí škodlivou, a jako ptáci polapeni bývají osídlem; tak zlapáni bývají synové lidští v čas zlý, když na ně připadá v náhle.'),
(1563749,54,21,9,13,'Také i tuto moudrost viděl jsem pod sluncem, kteráž za velikou byla u mne:'),
(1563750,54,21,9,14,'Bylo město malé, a v něm lidí málo, k němuž přitáhl král mocný, a obehnav je, zdělal proti němu náspy veliké.'),
(1563751,54,21,9,15,'I nalezen jest v něm muž chudý moudrý, kterýž vysvobodil to město moudrostí svou, ačkoli žádný nevzpomenul na muže toho chudého.'),
(1563752,54,21,9,16,'Protož řekl jsem já: Lepší jest moudrost než síla, ačkoli moudrost chudého toho byla v pohrdání, a slov jeho neposlouchali.'),
(1563753,54,21,9,17,'Slov moudrých pokojně poslouchati sluší, raději než křiku panujícího mezi blázny.'),
(1563754,54,21,9,18,'Lepší jest moudrost než nástrojové váleční, ale nemoudrý jeden kazí mnoho dobrého.'),
(1563755,54,21,10,1,'Muchy mrtvé nasmrazují a nakažují mast apatekářskou; tak pro moudrost a slávu vzácného maličko bláznovství zohyžďuje.'),
(1563756,54,21,10,2,'Srdce moudrého jest po pravici jeho, ale srdce blázna po levici jeho.'),
(1563757,54,21,10,3,'I tehdáž, když blázen cestou jde, srdce jeho nedostatek trpí; nebo všechněm znáti dává, že blázen jest.'),
(1563758,54,21,10,4,'Jestliže by duch toho, jenž panuje, povstal proti tobě, neopouštěj místa svého; nebo krotkost přítrž činí hříchům velikým.'),
(1563759,54,21,10,5,'Jest zlá věc, kterouž jsem viděl pod sluncem, totiž neprozřetelnost, kteráž pochází od vrchnosti,'),
(1563760,54,21,10,6,'Že blázen postaven bývá v důstojnosti veliké, a bohatí že v nízkosti sedávají.'),
(1563761,54,21,10,7,'Viděl jsem služebníky na koních, knížata pak, ana chodí pěšky jako služebníci.'),
(1563762,54,21,10,8,'Kdo kopá jámu, upadá do ní; a kdo boří plot, ušťkne jej had.'),
(1563763,54,21,10,9,'Kdo přenáší kamení, urazí se jím; a kdo štípá dříví, nebezpečenství bude míti od něho.'),
(1563764,54,21,10,10,'Jestliže se ztupí železo, a nenabrousí-li ostří jeho, tedy síly přičiniti musí; ale mnohem lépe může to spraviti moudrost.'),
(1563765,54,21,10,11,'Ušťkne-li had, než by zaklet byl, nic neprospějí slova zaklinače.'),
(1563766,54,21,10,12,'Slova úst moudrého jsou příjemná, ale rtové blázna sehlcují jej.'),
(1563767,54,21,10,13,'Počátek slov úst jeho jest nemoudrost, a ostatek mluvení jeho pouhé bláznovství.'),
(1563768,54,21,10,14,'Nebo blázen mnoho mluví, ješto neví člověk ten, co budoucího jest. To zajisté, co bude po něm, kdo mu oznámí?'),
(1563769,54,21,10,15,'Práce bláznů k ustání je přivodí, nebo neumí ani do města trefiti.'),
(1563770,54,21,10,16,'Běda tobě, země, když král tvůj dítě jest, a knížata tvá ráno hodují.'),
(1563771,54,21,10,17,'Blahoslavená jsi ty země, když král tvůj jest syn šlechetných, a knížata tvá, když čas jest, jídají pro posilnění, a ne pro opilství.'),
(1563772,54,21,10,18,'Ano pro lenost schází krov, a pro opuštění rukou kapává do domu.'),
(1563773,54,21,10,19,'Pro obveselení strojívají hody, a víno obveseluje život, peníze pak ke všemu dopomáhají.'),
(1563774,54,21,10,20,'Ani sám u sebe králi nezlořeč, ani v skrýších pokoje svého nezlořeč mocnějšímu; nebo pták nebeský donesl by hlas ten, a to, což křídla má, vyjevilo by řeč tvou.'),
(1563775,54,21,11,1,'Pouštěj chléb svůj po vodě, nebo po mnohých dnech najdeš jej.'),
(1563776,54,21,11,2,'Dej částku sedmi aneb i osmi, nebo nevíš, co zlého bude na zemi.'),
(1563777,54,21,11,3,'Když se naplňují oblakové, déšť na zem vydávají; a když padá dřevo na poledne aneb na půlnoci, na kteréž místo padá to dřevo, tu zůstává.'),
(1563778,54,21,11,4,'Kdo šetří větru, nebude síti; a kdo hledí na husté oblaky, nebude žíti.'),
(1563779,54,21,11,5,'Jakož ty nevíš, která jest cesta větru, a jak rostou kosti v životě těhotné, tak neznáš díla Božího, kterýž činí všecko.'),
(1563780,54,21,11,6,'Hned z jitra rozsívej símě své, a u večer nedávej odpočinutí ruce své; nebo ty nevíš, co jest lepšího, to-li či ono, čili obé jednostejně dobré jest.'),
(1563781,54,21,11,7,'Příjemnéť jest zajisté světlo, a milá věc očima viděti slunce;'),
(1563782,54,21,11,8,'A však, by mnoho let živ jsa člověk, ve všech těch veselil by se, tedy rozpomenul-li by se na dny temnosti, jak jich mnoho bude, cožkoli přeběhlo, počte za marnost.'),
(1563783,54,21,11,9,'Radujž se tedy, mládenče, v mladosti své, a nechť tě obveseluje srdce tvé ve dnech mladosti tvé, a choď po cestách srdce svého, a podlé žádosti očí svých, než věz, že tě s tím se vším přivede Bůh na soud.'),
(1563784,54,21,11,10,'Anobrž odejmi hněv od srdce svého, a odvrať zlost od těla svého; nebo dětinství a mladost jest marnost.'),
(1563785,54,21,12,1,'A pamatuj na stvořitele svého ve dnech mladosti své, prvé než nastanou dnové zlí, a přiblíží se léta, o nichž díš: Nemám v nich zalíbení;'),
(1563786,54,21,12,2,'Prvé než se zatmí slunce a světlo, a měsíc i hvězdy, a navrátí se hustí oblakové po dešti;'),
(1563787,54,21,12,3,'V ten den, v kterémž se třísti budou strážní domu, a nakřiví se muži silní, a ustanou melící, proto že jich málo bude, a zatmí se ti, kteříž vyhlédají z oken,'),
(1563788,54,21,12,4,'A zavříny budou dvéře od ulice s slabým zvukem mlení, a povstanou k hlasu ptačímu, a přestanou všecky slibnosti zpěvu;'),
(1563789,54,21,12,5,'Ano i vysokosti báti se budou, a úrazu na cestě, a kvésti bude mandlový strom, tak že i kobylka těžká bude, a poruší se žádost; nebo béře se člověk do domu věčného, a choditi budou po ulici kvílící;'),
(1563790,54,21,12,6,'Prvé než se přetrhne provaz stříbrný, a než se rozrazí číše zlatá, a roztříští se věderce nad vrchovištěm, a roztrhne se kolo nad studnicí,'),
(1563791,54,21,12,7,'A navrátí se prach do země, jakž prvé byl, duch pak navrátí se k Bohu, kterýž jej dal.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563792,54,21,12,8,'Marnost nad marnostmi, řekl kazatel, a všecko marnost.'),
(1563793,54,21,12,9,'Čím pak byl kazatel moudřejší, tím více vyučoval lid umění, a rozvažoval, zpytoval, i složil množství přísloví.'),
(1563794,54,21,12,10,'Snažovaltě se kazatel vyhledati věci nejžádostivější, a napsal, což pravého jest, a slova věrná.'),
(1563795,54,21,12,11,'Slova moudrých podobná ostnům a hřebíkům vbitým, slova skladatelů, kteráž jsou vydána od pastýře jednoho.'),
(1563796,54,21,12,12,'A tak tedy jimi, synu můj, hojně dosti osvícen býti můžeš. Dělání knih mnohých žádného konce není, a čísti mnoho jest zemdlení těla.'),
(1563797,54,21,12,13,'Summa všeho, což jsi slyšel: Boha se boj, a přikázaní jeho ostříhej, nebo na tom všecko člověku záleží.'),
(1563798,54,21,12,14,'Poněvadž všeliký skutek Bůh přivede na soud, i každou věc tajnou, buďto dobrou, buďto zlou.'),
(1563799,54,22,1,1,'Píseň nejpřednější z písní Šalomounových.'),
(1563800,54,22,1,2,'Ó by mne políbil políbením úst svých; nebo lepší jsou milosti tvé nežli víno.'),
(1563801,54,22,1,3,'Pro vůni masti tvé jsou výborné, mast rozlitá jméno tvé; protož tě mladice milují.'),
(1563802,54,22,1,4,'Táhniž mne, a poběhnem za tebou. Uvedltě mne král do pokojů svých, plésati a veseliti se v tobě budeme, a vychvalovati milosti tvé více než víno; upřímí milují tě.'),
(1563803,54,22,1,5,'Jsemť černá, ale milostná, ó dcery Jeruzalémské, tak jako stanové Cedarští, jako opony Šalomounovy.'),
(1563804,54,22,1,6,'Nehleďte na mne, žeť jsem snědá, nebo jsem obhořela od slunce. Synové matky mé rozpálivše se proti mně, postavili mne, abych ostříhala vinic, a vinice své nehlídala jsem.'),
(1563805,54,22,1,7,'Oznam mi ty, kteréhož miluje duše má, kde paseš? Kde dáváš odpočinutí o poledni? Nebo proč mám býti tak jako poběhlá při stádích tovaryšů tvých?'),
(1563806,54,22,1,8,'Jestliže nevíš, ó nejkrašší mezi ženami, vyjdi po šlepějích ovcí, a pas kozlátka svá podlé obydlí pastýřů.'),
(1563807,54,22,1,9,'Jízdě v vozích Faraonových připodobňuji tě, ó milostnice má.'),
(1563808,54,22,1,10,'Líce tvá okrášlena jsou ozdobami, a hrdlo tvé halžemi.'),
(1563809,54,22,1,11,'Ozdob zlatých naděláme tobě s proměnami stříbrnými.'),
(1563810,54,22,1,12,'Dotud, dokudž král stolí, nardus můj vydává vůni svou.'),
(1563811,54,22,1,13,'Svazček mirry jest mi milý můj, na prsech mých odpočívaje.'),
(1563812,54,22,1,14,'Milý můj jest mi hrozen cyprový na vinicích v Engadi.'),
(1563813,54,22,1,15,'Aj, jak jsi ty krásná, přítelkyně má, aj, jak jsi krásná! Oči tvé jako holubičí.'),
(1563814,54,22,1,16,'Aj, jak jsi ty krásný, milý můj, jak utěšený! I to lůže naše zelená se.'),
(1563815,54,22,1,17,'Trámové domů našich jsou z cedrů, a pavlače naše z boroví.'),
(1563816,54,22,2,1,'Já jsem růže Sáronská, a lilium při dolinách.'),
(1563817,54,22,2,2,'Jako lilium mezi trním, tak přítelkyně má mezi pannami.'),
(1563818,54,22,2,3,'Jako jabloň mezi dřívím lesním, tak milý můj mezi mládenci. V stínu jeho žádostiva jsem byla seděti, a sedímť; nebo ovoce jeho sladké jest ústům mým.'),
(1563819,54,22,2,4,'Uvedl mne na hody, maje za korouhev lásku ke mně.'),
(1563820,54,22,2,5,'Očerstvětež mne těmi flašemi, posilňte mne těmi jablky, nebo umdlévám milostí,'),
(1563821,54,22,2,6,'Levice jeho pod hlavou mou, a pravicí svou objímá mne.'),
(1563822,54,22,2,7,'Zavazujiť vás přísahou, dcery Jeruzalémské, skrze srny a laně polní, abyste nebudily a nevyrážely ze sna milého mého, dokudž by nechtěl.'),
(1563823,54,22,2,8,'Hlas milého mého, aj, onť se béře, skáče po těch horách, poskakuje na těch pahrbcích.'),
(1563824,54,22,2,9,'Podobný jest milý můj srně aneb mladému jelenu; aj, on stojí za stěnou naší, vyhlédá z oken, patří skrze mříži.'),
(1563825,54,22,2,10,'Ozval se milý můj, a řekl mi: Vstaň, přítelkyně má, krásná má, a poď.'),
(1563826,54,22,2,11,'Nebo aj, zima pominula, prška přestala a odešla.'),
(1563827,54,22,2,12,'Kvítíčko se ukazuje po zemi, čas prozpěvování přišel, a hlas hrdličky slyší se v krajině naší.'),
(1563828,54,22,2,13,'Fík vypustil holičky své, a réví rozkvetlé vydalo vůni. Vstaniž, přítelkyně má, krásná má, a poď.'),
(1563829,54,22,2,14,'Holubičko má, v rozsedlinách skalních, v skrýši příkré, ukaž mi oblíčej svůj, nechať slyším hlas tvůj; nebo hlas tvůj libý jest, a oblíčej tvůj žádostivý.'),
(1563830,54,22,2,15,'Zlapejte nám lišky, lišky maličké, ješto škodu dělají na vinicích, poněvadž vinice naše kvete.'),
(1563831,54,22,2,16,'Milý můj jest můj, a já jeho, jenž pase mezi lilium.'),
(1563832,54,22,2,17,'Ažby zavítal ten den, a utekli by stínové ti, navratiž se, připodobni se, milý můj, srně neb mladému jelenu na horách Beter.'),
(1563833,54,22,3,1,'Na ložci svém v noci hledala jsem toho, kteréhož miluje duše má. Hledala jsem ho, ale nenašla jsem ho.'),
(1563834,54,22,3,2,'Již tedy vstanu, a zchodím město; po ryncích i po ulicech hledati budu toho, kteréhož miluje duše má. Hledala jsem ho, ale nenašla jsem ho.'),
(1563835,54,22,3,3,'Našli mne ponocní, kteříž chodí po městě. Viděli-liž jste toho, kteréhož miluje duše má?'),
(1563836,54,22,3,4,'A jakž jsem jich jen pominula, takž jsem našla toho, kteréhož miluje duše má. Chopila jsem ho, aniž ho pustím, až ho uvedu do domu matky své, a do pokojíka rodičky své.'),
(1563837,54,22,3,5,'Přísahou vás zavazuji, dcery Jeruzalémské, skrze srny a laně polní, abyste nebudily a nevyrážely ze sna milého mého, dokudž by sám nechtěl.'),
(1563838,54,22,3,6,'Která jest to, jenž vstupuje z pouště jako sloupové dymu, okouřena jsuc mirrou a kadidlem, dražším nad všelijaký prach apatekářský?'),
(1563839,54,22,3,7,'Aj, lože Šalomounovo, okolo něhož šedesáte udatných z nejsilnějších Izraelských,'),
(1563840,54,22,3,8,'Vše vládnoucích mečem, vycvičených v boji, z nichž jeden každý má svůj meč při boku svém z příčiny strachu nočního.'),
(1563841,54,22,3,9,'Schranu vystavěl sobě král Šalomoun z dříví Libánského,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563842,54,22,3,10,'Při níž udělal sloupy stříbrné, dno zlaté a ponebí šarlatové, vnitřek pak jeho postlaný milostí dcer Jeruzalémských.'),
(1563843,54,22,3,11,'Vyjděte a pohleďte, dcery Sionské, na krále Šalomouna v koruně, kterouž ho korunovala matka jeho v den oddávání jeho a v den veselí srdce jeho.'),
(1563844,54,22,4,1,'Aj, jak jsi ty krásná, přítelkyně má, aj, jak jsi krásná! Oči tvé jako holubičí mezi kadeři tvými, vlasy tvé jako stáda koz, kteréž vídati na hoře Galád.'),
(1563845,54,22,4,2,'Zubové tvoji podobní stádu ovcí jednostejných, když vycházejí z kupadla, z nichž každá mívá po dvém, a mezi nimiž není žádné neplodné.'),
(1563846,54,22,4,3,'Jako provázek z hedbáví červeného dvakrát barveného rtové tvoji, a řeč tvá ozdobná; jako kus jablka zrnatého židoviny tvé mezi kadeři tvými.'),
(1563847,54,22,4,4,'Hrdlo tvé jest jako věže Davidova, vystavená k chování zbroje, v níž na tisíce pavéz visí, vše štítů mužů udatných.'),
(1563848,54,22,4,5,'Oba tvé prsy jako dvé telátek bliženců srních, jenž se pasou v kvítí.'),
(1563849,54,22,4,6,'Ažby zavítal ten den, a utekli by stínové, poodejdu k hoře mirrové a pahrbku kadidlovému.'),
(1563850,54,22,4,7,'Všecka jsi krásná, přítelkyně má, a není na tobě poškvrny.'),
(1563851,54,22,4,8,'Se mnou z Libánu, ó choti má, se mnou z Libánu půjdeš, a pohledíš s vrchu hory Amana, s vrchu Senir a Hermon, z peleší lvových a s hor pardových.'),
(1563852,54,22,4,9,'Jala jsi srdce mé, sestro má choti, jala jsi srdce mé jedním okem svým, a jedinou točenicí hrdla svého.'),
(1563853,54,22,4,10,'Jak utěšené jsou milosti tvé, sestro má choti! Jak vzácnější jsou milosti tvé než víno, a vůně mastí tvých nade všecky vonné věci.'),
(1563854,54,22,4,11,'Strdí tekou rtové tvoji, ó choti, med a mléko pod jazykem tvým, a vůně roucha tvého jako vůně Libánu.'),
(1563855,54,22,4,12,'Zahrada zamčená jsi, sestro má choti, vrchoviště zamčené, studnice zapečetěná.'),
(1563856,54,22,4,13,'Výstřelkové tvoji jsou zahrada stromů jablek zrnatých s ovocem rozkošným cypru a nardu,'),
(1563857,54,22,4,14,'Nardu s šafránem, prustvorce s skořicí, a s každým stromovím kadidlo vydávajícím, mirry a aloes, i s všelijakými zvláštními věcmi vonnými.'),
(1563858,54,22,4,15,'Ó ty sám vrchoviště zahradní, studnice vod živých, a tekoucích z Libánu.'),
(1563859,54,22,4,16,'Věj, větříčku půlnoční, a přiď, větříčku polední, prověj zahradu mou, ať tekou vonné věci její, a ať příjde milý můj do zahrady své, a jí rozkošné ovoce své.'),
(1563860,54,22,5,1,'Přišelť jsem do zahrady své, sestro má choti, sbírám mirru svou i vonné věci své, jím plást svůj i med svůj, pijí víno své a mléko své. Jezte, přátelé, píte a hojně se napíte, moji milí.'),
(1563861,54,22,5,2,'Spávámť, a však srdce mé bdí. Hlas milého mého, tlukoucího: Otevři mi, sestro má, přítelkyně má, holubičko má, upřímá má; nebo hlava má plná jest rosy, a kadeře mé krůpějí nočních.'),
(1563862,54,22,5,3,'Svlékla jsem sukni svou, kterakž ji obleku? Umyla jsem nohy své, což je mám káleti?'),
(1563863,54,22,5,4,'Milý můj sáhl rukou svou skrze dvéře, a vnitřnosti mé pohnuly se ve mně.'),
(1563864,54,22,5,5,'I vstala jsem, abych otevřela milému svému, a aj, z rukou mých kapala mirra, i z prstů mých, mirra tekutá na rukovětech závory.'),
(1563865,54,22,5,6,'Otevřelať jsem byla milému svému, ale milý můj již byl ušel, a pominul. Duše má byla vyšla, když on promluvil. Hledala jsem ho, ale nenašla jsem ho; volala jsem ho, ale neozval se mi.'),
(1563866,54,22,5,7,'Nalezše mne strážní, kteříž chodí po městě, zbili mne, ranili mne, vzali i rouchu mou se mne strážní zdí městských.'),
(1563867,54,22,5,8,'Zavazuji vás přísahou dcery Jeruzalémské, jestliže byste našly milého mého, co jemu povíte? Že jsem nemocná milostí.'),
(1563868,54,22,5,9,'Což má milý tvůj mimo jiné milé, ó nejkrásnější z žen? Co má milý tvůj nad jiné milé, že nás tak přísahou zavazuješ?'),
(1563869,54,22,5,10,'Milý můj jest bílý a červený, znamenitější nežli deset tisíců jiných.'),
(1563870,54,22,5,11,'Hlava jeho jako ryzí zlato, vlasy jeho kadeřavé, černé jako havran.'),
(1563871,54,22,5,12,'Oči jeho jako holubic nad stoky vod, jako v mléce umyté, stojící v slušnosti.'),
(1563872,54,22,5,13,'Líce jeho jako záhonkové vonných věcí, jako květové vonných věcí; rtové jeho jako lilium prýštící mirru tekutou.'),
(1563873,54,22,5,14,'Ruce jeho prstenové zlatí, vysazení kamením drahým jako postavcem modrým; břicho jeho stkvělost slonové kosti zafiry obložené.'),
(1563874,54,22,5,15,'Hnátové jeho sloupové mramoroví, na podstavcích zlata nejčistšího založení; oblíčej jeho jako Libán, výborný jako cedrové.'),
(1563875,54,22,5,16,'Ústa jeho přesladká, a všecken jest přežádostivý. Takovýť jest milý můj, takový jest přítel můj, ó dcery Jeruzalémské.'),
(1563876,54,22,5,17,'Kamže odšel milý tvůj, ó nejkrásnější z žen? Kam se obrátil milý tvůj? A hledati ho budeme s tebou.'),
(1563877,54,22,6,1,'Milý můj sstoupil do zahrady své, k záhonkům věci vonných, aby pásl v zahradách, a aby zbíral lilium.'),
(1563878,54,22,6,2,'Já jsem milého mého, a milý můj jest můj, kterýž pase mezi lilium.'),
(1563879,54,22,6,3,'Krásná jsi, přítelkyně má, jako Tersa, pěkná jako Jeruzalém, hrozná jako vojsko s praporci.'),
(1563880,54,22,6,4,'Odvrať oči své od patření na mne, nebo ony mne posilují. Vlasy tvé jsou jako stáda koz, kteréž vídati v Galád.'),
(1563881,54,22,6,5,'Zubové tvoji jsou podobní stádu ovcí, když vycházejí z kupadla, z nichž každá mívá po dvém, a mezi nimiž není žádné neplodné.'),
(1563882,54,22,6,6,'Jako kus jablka zrnatého židoviny tvé mezi kadeři tvými.'),
(1563883,54,22,6,7,'Šedesáte jest královen, a osmdesáte ženin, a mladic bez počtu;'),
(1563884,54,22,6,8,'Jediná jest však má holubice, má upřímá, jedinká při matce své, nepoškvrněná při své rodičce. Spatřivše ji dcery, blahoslavily ji, královny a ženiny chválily ji, řkouce:'),
(1563885,54,22,6,9,'Která jest to, kterouž viděti jako dennici, krásná jako měsíc, čistá jako slunce, hrozná jako vojsko s praporci?'),
(1563886,54,22,6,10,'Do zahrady vypravené sstoupila jsem, abych spatřila ovoce údolí, abych viděla, kvete-li vinný kmen, a pučí-li se jabloně zrnaté.'),
(1563887,54,22,6,11,'Nezvěděla jsem, a žádost má ponukla mne na vůz přednějších z lidu mého.'),
(1563888,54,22,6,12,'Navrať se, navrať, ó Sulamitská, navrať se, navrať, ať na tě patříme. Co uzříte na Sulamitské? Jako zástup vojenský.'),
(1563889,54,22,7,1,'Jak jsou krásné nohy tvé v střevících, dcero knížecí! Okolek bedr tvých jako zápony, dílo ruku výborného řemeslníka.'),
(1563890,54,22,7,2,'Pupek tvůj koflík okrouhlý, ne bez nápoje; břicho tvé jako stoh pšenice obrostlý kvítím.'),
(1563891,54,22,7,3,'Oba tvé prsy jako dvé telátek bliženců srních.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563892,54,22,7,4,'Hrdlo tvé jako věže z kostí slonových, oči tvé rybníci v Ezebon podlé brány Batrabbim, nos tvůj věže Libánská patřící k Damašku.'),
(1563893,54,22,7,5,'Hlava tvá na tobě jako Karmel, a vlasy hlavy tvé jako šarlat; i král přivázán by byl na pavlačích.'),
(1563894,54,22,7,6,'Jak jsi ty krásná, a jak utěšená, ó milosti přerozkošná!'),
(1563895,54,22,7,7,'Ta postava tvá podobna jest palmě, a prsy tvé hroznům.'),
(1563896,54,22,7,8,'Řekl jsem: Vstoupím na palmu, dosáhnu vrchů jejích. Nechažť tedy jsou prsy tvé jako hroznové vinného kmene, a vůně chřípí tvých jako jablek vonných.'),
(1563897,54,22,7,9,'Ústa tvá jako víno výborné, milá pro upřímnost, působící, aby i těch, jenž spí, rtové mluvili.'),
(1563898,54,22,7,10,'Já jsem milého svého, a ke mně jest žádost jeho.'),
(1563899,54,22,7,11,'Poď, milý můj, vyjděme na pole, přenocujme ve vsech.'),
(1563900,54,22,7,12,'Ráno přivstaneme, na vinice pohledíme, kvete-li vinný kmen, již-li se ukázal začátek hroznů, kvetou-li jablka zrnatá, a tuť dám tobě milosti své.'),
(1563901,54,22,7,13,'Pěkná jablečka vydala vůni, a na dveřech našich všecky rozkoše nové i staré, milý můj, zachovala jsem tobě.'),
(1563902,54,22,8,1,'Ó bys byl jako bratr můj požívající prsí matky mé, abych tě naleznuc vně, políbila, a nebyla zahanbena.'),
(1563903,54,22,8,2,'Vedla bych tě, a uvedla do domu matky své, a tu bys mne vyučoval; a jáť bych dala píti vína strojeného, a mstu z jablek zrnatých.'),
(1563904,54,22,8,3,'Levice jeho pod hlavou mou, a pravicí svou objímá mne.'),
(1563905,54,22,8,4,'Přísahou vás zavazuji, dcery Jeruzalémské, abyste nebudily a nevyrážely ze sna milého mého, dokudž by sám nechtěl.'),
(1563906,54,22,8,5,'Která jest to, jenž vstupuje z pouště, zpolehši na milého svého? Pod jabloní vzbudila jsem tě; tuť tebe počala matka tvá, tuť tě počala rodička tvá.'),
(1563907,54,22,8,6,'Položiž mne jako pečet na srdce své, jako pečetní prsten na ruku svou. Nebo silné jest jako smrt milování, tvrdá jako hrob horlivost; uhlí její uhlí řeřavé, plamen nejprudší.'),
(1563908,54,22,8,7,'Vody mnohé nemohly by uhasiti tohoto milování, aniž ho řeky zatopí. Kdyby někdo dáti chtěl všecken statek domu svého za takovou milost, se vším tím pohrdnut by byl.'),
(1563909,54,22,8,8,'Sestru máme maličkou, kteráž ještě nemá prsí. Co učiníme s sestrou svou v den, v kterýž bude řeč o ní?'),
(1563910,54,22,8,9,'Jestliže jest zed, vzděláme na ní palác stříbrný; pakli jest dveřmi, obložíme je dskami cedrovými.'),
(1563911,54,22,8,10,'Já jsem zed, a prsy mé jako věže; takž jsem byla před očima jeho, jako nacházející pokoj.'),
(1563912,54,22,8,11,'Vinici měl Šalomoun v Balhamon, kteroužto pronajal strážným, aby jeden každý přinášel za ovoce její tisíc stříbrných.'),
(1563913,54,22,8,12,'Ale vinice má, kterouž mám, přede mnou jest. Mějž sobě ten tisíc, ó Šalomoune, a dvě stě ti, kteříž ostříhají ovoce jejího.'),
(1563914,54,22,8,13,'Ó ty, kteráž bydlíš v zahradách, přáteléť pozorují hlasu tvého, ohlašujž mi se.'),
(1563915,54,22,8,14,'Pospěš, milý můj, a připodobni se k srně nebo mladému jelenu, na horách vonných věcí.'),
(1563916,54,23,1,1,'Vidění Izaiáše syna Amosova, kteréž viděl o Judovi a Jeruzalému, za dnů Uziáše, Jotama, Achasa a Ezechiáše, králů Judských.'),
(1563917,54,23,1,2,'Slyšte nebesa, a ušima pozoruj země, nebo Hospodin mluví: Syny jsem vychoval a vyvýšil, oni pak strhli se mne.'),
(1563918,54,23,1,3,'Vůl zná hospodáře svého, a osel jesle pánů svých; Izrael nezná, lid můj nesrozumívá.'),
(1563919,54,23,1,4,'Ach, národe hříšný, lide obtížený nepravostí, símě zlostníků, synové nešlechetní, opustili Hospodina, pohrdli svatým Izraelským, odvrátili se zpět.'),
(1563920,54,23,1,5,'Proč, čím více biti býváte, tím více se odvracujete? Všecka hlava jest neduživá, a všecko srdce zemdlené.'),
(1563921,54,23,1,6,'Od zpodku nohy až do vrchu hlavy není na něm místa celého, jen rána a zsinalost, a zbití zahnojené, aniž se vytlačuje, ani uvazuje, ani olejem změkčuje.'),
(1563922,54,23,1,7,'Země vaše spustla, města vaše vypálena ohněm; zemi vaši před vámi cizozemci zžírají, a v poušť obracejí, tak jakž vše kazí cizozemci.'),
(1563923,54,23,1,8,'I zůstala dcera Sionská jako boudka na vinici, jako chaloupka v zahradě tykevné, a jako město zkažené.'),
(1563924,54,23,1,9,'Byť nám byl Hospodin zástupů jakkoli malička ostatků nezanechal, byli bychom jako Sodoma, byli bychom Gomoře podobni.'),
(1563925,54,23,1,10,'Slyšte slovo Hospodinovo, knížata Sodomská, ušima pozorujte zákona Boha našeho, lide Gomorský:'),
(1563926,54,23,1,11,'K čemu jest mi množství obětí vašich? dí Hospodin. Syt jsem zápalných obětí skopců a tuků krmných hovad, a krve volků a beránků a kozlů nejsem žádostiv.'),
(1563927,54,23,1,12,'Že přicházíte, abyste se ukazovali přede mnou, kdož toho z ruky vaší hledal, abyste šlapali síně mé?'),
(1563928,54,23,1,13,'Nepřinášejte více oběti oklamání. Kadění v ohavnosti mám, novměsíců a sobot a svolávání nemohu trpěti, (nepravost jest), ani shromáždění.'),
(1563929,54,23,1,14,'Novměsíců vašich a slavností vašich nenávidí duše má; jsou mi břemenem, ustal jsem, nesa je.'),
(1563930,54,23,1,15,'Protož, když rozprostíráte ruce vaše, skrývám oči své před vámi, a když množíte modlitbu, neslyším; ruce vaše krve plné jsou.'),
(1563931,54,23,1,16,'Umejte se, očisťte se, odvrzte zlost skutků vašich od očí mých, přestaňte zle činiti.'),
(1563932,54,23,1,17,'Učte se dobře činiti, hledejte soudu, pozdvihněte potlačeného, dopomozte k spravedlnosti sirotku, zastaňte vdovy.'),
(1563933,54,23,1,18,'Poďtež nu, a poukažme sobě, praví Hospodin: Budou-li hříchové vaši jako červec dvakrát barvený, jako sníh zbělejí; budou-li červení jako šarlat, jako vlna budou.'),
(1563934,54,23,1,19,'Budete-li povolní a poslušní, dobré věci země jísti budete.'),
(1563935,54,23,1,20,'Pakli nebudete povolní, ale zpurní, od meče sežráni budete; nebo ústa Hospodinova mluvila.'),
(1563936,54,23,1,21,'Jak tě nevěstkou učiněno to město věrné, plné soudu! Spravedlnost přebývala v něm, nyní pak vražedlníci.'),
(1563937,54,23,1,22,'Stříbro tvé obrátilo se v trůsky, víno tvé smíšeno s vodou.'),
(1563938,54,23,1,23,'Knížata tvá zpurná a tovaryši zlodějů, jeden každý z nich miluje dary, a dychtí po úplatcích; sirotku k spravedlnosti nedopomáhají, a pře vdovy před ně nepřichází.'),
(1563939,54,23,1,24,'Protož dí Pán, Hospodin zástupů, silný Izraelský: Aj, jáť se potěším nad protivníky svými, a vymstím se nad nepřátely svými,'),
(1563940,54,23,1,25,'Když zase obrátím ruku svou na tě, až přepálím dočista trůsky tvé, a odejmu všecken cín tvůj,'),
(1563941,54,23,1,26,'A obnovím soudce tvé tak jako na počátku, a rádce tvé jako s prvu. A tu potom slouti budeš městem spravedlnosti, městem věrným.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563942,54,23,1,27,'Sion v soudu vykoupen bude, a kteříž zase uvedeni budou do něho, v spravedlnosti.'),
(1563943,54,23,1,28,'Setření pak přestupníků a nešlechetných v náhle přijde, a kteříž opouštějí Hospodina, docela zahynou.'),
(1563944,54,23,1,29,'Nebo zahanbeni budete pro háje, po nichž jste toužili, a zastydíte se pro zahrady, kteréž jste sobě zvolili.'),
(1563945,54,23,1,30,'Budete zajisté jako dub, s něhož lístí prší, a jako zahrada, v níž vody není.'),
(1563946,54,23,1,31,'I bude nejsilnější jako koudel, a učinitel jeho jako jiskra; i bude to obé hořeti spolu, a nebude žádného, ješto by uhasiti mohl.'),
(1563947,54,23,2,1,'Slovo, kteréž viděl Izaiáš syn Amosův o Judovi a Jeruzalému.'),
(1563948,54,23,2,2,'I stane se v posledních dnech, že utvrzena bude hora domu Hospodinova na vrchu hor, a vyvýšena nad pahrbky, i pohrnou se k ní všickni národové.'),
(1563949,54,23,2,3,'A půjdou lidé mnozí, říkajíce: Poďte, a vstupme na horu Hospodinovu, do domu Boha Jákobova, a bude nás vyučovati cestám svým, i budeme choditi po stezkách jeho. Nebo z Siona vyjde zákon, a slovo Hospodinovo z Jeruzaléma.'),
(1563950,54,23,2,4,'Onť bude souditi mezi národy, a trestati bude lidi mnohé. I zkují meče své v motyky, a oštípy své v srpy. Nepozdvihne národ proti národu meče, a nebudou se více učiti boji.'),
(1563951,54,23,2,5,'Dome Jákobův, poďtež, a choďme v světle Hospodinově.'),
(1563952,54,23,2,6,'Ale ty jsi opustil lid svůj, dům Jákobův, proto že jsou naplněni ohavnostmi národů východních, a jsou pověrní jako Filistinští, a smyšlínky cizozemců že sobě libují.'),
(1563953,54,23,2,7,'K tomu naplněna jest země jejich stříbrem a zlatem, tak že není konce pokladům jejich; naplněna jest země jejich i koňmi, vozům pak jejich počtu není.'),
(1563954,54,23,2,8,'Naplněna jest také země jejich modlami; klanějí se dílu rukou svých, kteréž učinili prstové jejich.'),
(1563955,54,23,2,9,'Klaní se obecný člověk, a ponižuje se i přední muž; protož neodpouštěj jim.'),
(1563956,54,23,2,10,'Vejdi do skály, a skrej se v prachu před hrůzou Hospodinovou, před slávou důstojnosti jeho.'),
(1563957,54,23,2,11,'Tuť oči vysoké člověka sníženy budou, a skloněna bude vysokost lidská, ale Hospodin sám vyvýšen bude v ten den.'),
(1563958,54,23,2,12,'Nebo den Hospodina zástupů se blíží na každého pyšného a zpínajícího se, i na každého vyvýšeného, i bude ponížen,'),
(1563959,54,23,2,13,'I na všecky cedry Libánské vysoké a vyvýšené, i na všecky duby Bázanské,'),
(1563960,54,23,2,14,'I na všecky hory vysoké, i na všecky pahrbky vyvýšené,'),
(1563961,54,23,2,15,'I na všelikou věži vysokou, i na všelikou zed pevnou,'),
(1563962,54,23,2,16,'I na všecky lodí mořské, i na všecka malování slibná.'),
(1563963,54,23,2,17,'A sehnuta bude pýcha člověka, a snížena bude vysokost lidská, ale vyvýšen bude Hospodin sám v ten den,'),
(1563964,54,23,2,18,'Modly pak docela vymizejí.'),
(1563965,54,23,2,19,'Tehdy půjdou do jeskyní skal a do roklí země, před hrůzou Hospodinovou a slávou důstojnosti jeho, když povstane, aby potřel zemi.'),
(1563966,54,23,2,20,'V ten den zavrže člověk modly své stříbrné a modly své zlaté, kterýchž mu nadělali, aby se klaněl, totiž krtům a netopýřům.'),
(1563967,54,23,2,21,'I vejde do slují skal a do vysedlin jejich před hrůzou Hospodinovou, a před slávou důstojnosti jeho, když povstane, aby potřel zemi.'),
(1563968,54,23,2,22,'Přestaňtež doufati v člověku, jehož dýchání v chřípích jeho jest. Nebo zač má jmín býti?'),
(1563969,54,23,3,1,'Nebo aj, Pán, Hospodin zástupů, odejme od Jeruzaléma a Judy hůl a podporu, všelijakou hůl chleba a všelikou podporu vody,'),
(1563970,54,23,3,2,'Silného i muže válečného, soudce i proroka, mudrce i starce,'),
(1563971,54,23,3,3,'Padesátníka i počestného, i rádci, i vtipného řemeslníka, i výmluvného,'),
(1563972,54,23,3,4,'A dám jim děti za knížata; děti, pravím, panovati budou nad nimi.'),
(1563973,54,23,3,5,'I bude ssužovati v lidu jeden druhého, a bližní bližního svého; zpurně se postaví dítě proti starci, a chaterný proti vzácnému.'),
(1563974,54,23,3,6,'Pročež se chopí jeden každý bratra svého z domu otce svého, a dí: Máš oděv, knížetem naším budeš, a pád tento zdrž rukou svou.'),
(1563975,54,23,3,7,'Ale on přisáhne v ten den, řka: Nebuduť vázati těch ran, nebo v domě mém není chleba ani oděvu; neustanovujtež mne knížetem lidu.'),
(1563976,54,23,3,8,'Nebo se obořil Jeruzalém, a Juda padl, proto že jazyk jejich a skutkové jejich jsou proti Hospodinu, k dráždění očí slávy jeho.'),
(1563977,54,23,3,9,'Nestydatost tváři jejich svědčí proti nim; hřích zajisté svůj jako Sodomští ohlašují, a netají. Běda duši jejich, nebo sami na sebe uvodí zlé.'),
(1563978,54,23,3,10,'Rcete spravedlivému: Dobře bude; nebo ovoce skutků svých jísti bude.'),
(1563979,54,23,3,11,'Ale běda bezbožnému, zle bude; nebo odplata rukou jeho dána jemu bude.'),
(1563980,54,23,3,12,'Lidu mého knížata jsou děti, a ženy panují nad ním. Lide můj, kteříž tě vodí, svodí tě, a cestu stezek tvých ukrývají.'),
(1563981,54,23,3,13,'Stojíť Hospodin k rozsudku, stojí, pravím, k rozsudku s lidmi.'),
(1563982,54,23,3,14,'Hospodin k soudu přijde proti starším lidu svého a knížatům jejich, a dí: Vy jste pohubili vinici mou, loupež chudého jest v domích vašich.'),
(1563983,54,23,3,15,'Proč vy nuzíte lid můj, a tváře chudých zahanbujete? praví Pán, Hospodin zástupů.'),
(1563984,54,23,3,16,'I dí Hospodin: Proto že se pozdvihují dcery Sionské, a chodí s vytaženým krkem, a pasou očima, protulujíce se, a zdrobna kráčejíce, i nohama svýma lákají,'),
(1563985,54,23,3,17,'Protož okydne Pán prašivinou vrch hlavy dcer Sionských, a Hospodin hanbu jejich obnaží.'),
(1563986,54,23,3,18,'V ten den odejme Pán okrasu těch nástrah, totiž paučníky a halže,'),
(1563987,54,23,3,19,'Jablka zlatá a spinadla a čepce,'),
(1563988,54,23,3,20,'Biréty a zápony, tkanice, punty a náušnice,'),
(1563989,54,23,3,21,'Prsteny a náčelníky,'),
(1563990,54,23,3,22,'Proměnná roucha, i plášťky, i roušky, i vačky,'),
(1563991,54,23,3,23,'I zrcadla, i čechlíky, i věnce, i šlojíře.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1563992,54,23,3,24,'A budeť místo vonných věcí hnis, a místo pasů roztržení, a místo strojení kadeří lysina, a místo širokého podolku bude přepásání pytlem, obhoření pak místo krásy.'),
(1563993,54,23,3,25,'Muži tvoji od meče padnou, a silní tvoji v boji.'),
(1563994,54,23,3,26,'I budou plakati a kvíliti brány jeho, a spustlý na zemi seděti bude.'),
(1563995,54,23,4,1,'I chopí se sedm žen muže jednoho v ten den, a řeknou: Chléb svůj jísti budeme, a rouchem svým se odívati, toliko ať po tobě se jmenujeme; odejmi pohanění naše.'),
(1563996,54,23,4,2,'V ten den bude výstřelek Hospodinův ušlechtilý a slavný, a plod země výtečný a krásný, totiž ti, kteříž zachováni budou z Izraele.'),
(1563997,54,23,4,3,'I stane se, že kdož bude zanechán na Sionu, a pozůstaven bude v Jeruzalémě, svatý slouti bude, každý, kdož jest zapsán k životu v Jeruzalémě,'),
(1563998,54,23,4,4,'Když Pán smyje nečistotu dcer Sionských, a krev Jeruzaléma vyplákne z něho v duchu soudu a v duchu horlivosti.'),
(1563999,54,23,4,5,'A stvoří Hospodin nad každým obydlím hory Sion, a nad každým shromážděním jejím oblak ve dne, a dým a blesk plápolajícího ohně v noci; nebo nad všecku slávu bude zastření.'),
(1564000,54,23,4,6,'A bude stánkem k zastěňování ve dne před horkem, a za útočiště a skrýši před přívalem a deštěm.'),
(1564001,54,23,5,1,'Zpívati již budu milému svému píseň milého svého o vinici jeho: Vinici má milý můj na vrchu úrodném.'),
(1564002,54,23,5,2,'Kterouž ohradil, a kamení z ní vybral, a vysadil ji vinným kmenem výborným, a ustavěl věži u prostřed ní, také i pres udělal v ní, a očekával, aby nesla hrozny, ale vydala plané víno.'),
(1564003,54,23,5,3,'Nyní tedy, obyvatelé Jeruzalémští a muži Judští, suďte medle mezi mnou a vinicí mou.'),
(1564004,54,23,5,4,'Což ještě činěno býti mělo vinici mé, ješto bych jí neučinil? Proč, když jsem očekával, aby nesla hrozny, plodila plané víno?'),
(1564005,54,23,5,5,'A protož oznámím vám, co já učiním vinici své: Odejmu plot její, a přijde na spuštění; rozbořím hradbu její, i přijde na pošlapání.'),
(1564006,54,23,5,6,'Zapustím ji, nebude řezána, ani kopána, i vzroste na ní bodláčí a trní; oblakům také zapovím, aby nevydávali více na ni deště.'),
(1564007,54,23,5,7,'Vinice zajisté Hospodina zástupů dům Izraelský jest, a muži Judští révové milí jemu. Očekával pak soudu, a aj, nátisk; spravedlnosti, a aj, křik.'),
(1564008,54,23,5,8,'Běda vám, kteříž připojujete dům k domu, a pole s polem spojujete, tak že místa jiným není, jako byste sami rozsazeni byli k přebývání u prostřed země.'),
(1564009,54,23,5,9,'V uši mé řekl Hospodin zástupů: Jistě žeť domové mnozí zpustnou, velicí a krásní bez obyvatele budou.'),
(1564010,54,23,5,10,'Nadto deset dílců viničných vydá láhvici jednu, a semena chomer vydá efi.'),
(1564011,54,23,5,11,'Běda těm, kteříž ráno vstávajíce, chodí po opilství, a trvají při tom do večera, až je víno i rozpaluje.'),
(1564012,54,23,5,12,'A harfa, loutna a buben, a píšťalka,a víno bývá na hodech jejich; na skutky pak Hospodinovy nehledí, a díla rukou jeho nespatřují.'),
(1564013,54,23,5,13,'Protož v zajetí půjde lid můj, nebo jest bez umění; a slavní jeho budou hladovití, a množství jeho žízní usvadne.'),
(1564014,54,23,5,14,'Pročež rozšířilo i peklo hrdlo své, a rozedřelo nad míru ústa svá, i sstoupí do něho slavní její a množství její, i hluk její, i ti, kteříž se veselí v ní.'),
(1564015,54,23,5,15,'A tak sehnut bude člověk, a ponížen muž, a oči pyšných sníženy budou,'),
(1564016,54,23,5,16,'Hospodin pak zástupů vyvýšen bude v soudu, a Bůh silný a svatý ukáže se svatý v spravedlnosti.'),
(1564017,54,23,5,17,'I pásti se budou beránkové podlé obyčeje svého, a ostatky těch tučných, navrátíce se, jísti budou.'),
(1564018,54,23,5,18,'Běda těm, kteříž táhnou nepravost za provazy marnosti, a jako provazem u vozu hřích;'),
(1564019,54,23,5,19,'Kteříž říkají: Nechať pospíší, a nemešká dílem svým, abychom viděli, a nechať se přiblíží, a přijde rada toho Svatého Izraelského, abychom zvěděli.'),
(1564020,54,23,5,20,'Běda těm, kteříž říkají zlému dobré, a dobrému zlé, kladouce tmu za světlo, a světlo za tmu, pokládajíce hořké za sladké, a sladké za hořké.'),
(1564021,54,23,5,21,'Běda těm, kteříž jsou moudří sami u sebe, a vedlé zdání svého opatrní.'),
(1564022,54,23,5,22,'Běda těm, kteříž jsou silní ku pití vína, a muži udatní k smíšení nápoje opojného;'),
(1564023,54,23,5,23,'Kteříž ospravedlňují bezbožného pro dary, spravedlnost pak spravedlivých odjímají od nich.'),
(1564024,54,23,5,24,'Z té příčiny, jakož plamen ohně zžírá strniště, a plevy plamen v nic obrací, tak kořen jejich bude jako shnilina, a květ jejich jako prach vzejde; nebo zavrhli zákon Hospodina zástupů, a řečí svatého Izraelského pohrdli.'),
(1564025,54,23,5,25,'Pročež rozpáliv se prchlivostí Hospodin na lid svůj, a vztáh ruku svou na něj, porazil jej, tak že se hory zatřásly, a těla mrtvá jejich jako hnůj u prostřed ulic. V tom však ve všem neodvrátila se prchlivost jeho, ale předce ruka jeho jest vztažená.'),
(1564026,54,23,5,26,'Nebo vyzdvihne korouhev národu dalekému, a zahvízdne naň od končin země, a aj, rychle a prudce přijde.'),
(1564027,54,23,5,27,'Žádného ustalého ani klesajícího nebude mezi nimi; nebude dřímati ani spáti, aniž se rozepne pás bedr jeho, aniž se strhá řemen obuví jeho.'),
(1564028,54,23,5,28,'Střely jeho ostré, a všecka lučiště jeho natažená; kopyta koňů jeho jako škřemen souzena budou, a kola jeho jako vichřice.'),
(1564029,54,23,5,29,'Řvání jeho jako řvání lva, a řváti bude jako lvíčata; a mumlati bude, a pochytí loupež a uteče, aniž bude, kdo by vydřel.'),
(1564030,54,23,5,30,'A zvučeti bude nad ním v ten den, jako zvučí moře. Tehdy pohledíme na zemi, a aj, mrákota a úzkost; nebo se i světlo zatmí při pohubení jejím.'),
(1564031,54,23,6,1,'Léta, kteréhož umřel král Uziáš, viděl jsem Pána sedícího na trůnu vysokém a vyzdviženém, a podolek jeho naplňoval chrám.'),
(1564032,54,23,6,2,'Serafínové stáli nad ním. Šest křídel měl každý z nich: dvěma zakrýval tvář svou, a dvěma přikrýval nohy své, a dvěma létal.'),
(1564033,54,23,6,3,'A volal jeden k druhému, říkaje: Svatý, svatý, svatý Hospodin zástupů, plná jest všecka země slávy jeho.'),
(1564034,54,23,6,4,'A pohnuly se podvoje veřejí od hlasu volajícího, a dům plný byl dymu.'),
(1564035,54,23,6,5,'I řekl jsem: Běda mně, jižť zahynu, proto že jsem člověk poškvrněné rty maje, k tomu u prostřed lidu rty poškvrněné majícího bydlím, a že krále Hospodina zástupů viděly oči mé.'),
(1564036,54,23,6,6,'I přiletěl ke mně jeden z serafínů, maje v ruce své uhel řeřavý, kleštěmi vzatý z oltáře,'),
(1564037,54,23,6,7,'A dotekl se úst mých, a řekl: Aj hle,dotekl se uhel tento úst tvých; nebo odešla nepravost tvá, a hřích tvůj shlazen jest.'),
(1564038,54,23,6,8,'Potom slyšel jsem hlas Pána řkoucího: Koho pošli? A kdo nám půjde? I řekl jsem: Aj já, pošli mne.'),
(1564039,54,23,6,9,'On pak řekl: Jdi, a rci lidu tomu: Slyšte slyšíce, a nerozumějte, a hleďte hledíce, a nepoznávejte.'),
(1564040,54,23,6,10,'Zatvrď srdce lidu toho, a uši jeho zacpej, a oči jeho zavři, aby neviděl očima svýma, a ušima svýma neslyšel, a srdcem svým nerozuměl, a neobrátil se, a nebyl uzdraven.'),
(1564041,54,23,6,11,'A když jsem řekl: Až dokud, Pane? i odpověděl: Dokudž nezpustnou města, tak aby nebylo žádného obyvatele, a domové, aby nebylo v nich žádného člověka, a země docela nezpustne,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564042,54,23,6,12,'A nevzdálí Hospodin všelikého člověka, a nebude dokonalého zpuštění u prostřed země;'),
(1564043,54,23,6,13,'Dokudž ještě v ní nebude desateré zhouby, a teprv zkažena bude. Ale jakož ono jilmoví, a jako doubí onoho náspu podporou jest, tak símě svaté jest podpora její.'),
(1564044,54,23,7,1,'I stalo se za dnů Achasa syna Jotamova, syna Uziáše, krále Judského, že přitáhl Rezin král Syrský, a Pekach syn Romeliáše, krále Izraelského, k Jeruzalému, aby bojoval proti němu, ale nemohl ho dobyti.'),
(1564045,54,23,7,2,'I oznámeno jest domu Davidovu v tato slova: Spikla se země Syrská s Efraimem. Pročež pohnulo se srdce jeho, i srdce lidu jeho, tak jako se pohybuje dříví v lese od větru.'),
(1564046,54,23,7,3,'Tedy řekl Hospodin Izaiášovi: Vyjdi nyní vstříc Achasovi, ty a Sear Jašub syn tvůj, až na konec struhy rybníka hořejšího, k silnici pole valchářova,'),
(1564047,54,23,7,4,'A díš jemu: Šetř se, abys se nekormoutil. Neboj se, a srdce tvé nechať se neděsí dvou ostatků hlavní těch kouřících se, před rozpáleným hněvem Rezinovým s Syrskými, a syna Romeliášova,'),
(1564048,54,23,7,5,'Proto že zlou radu složili proti tobě Syrský, Efraim a syn Romeliášův, řkouce:'),
(1564049,54,23,7,6,'Táhněme proti zemi Judské, a vyležme ji, a odtrhněme ji k sobě, a ustavme krále u prostřed ní syna Tabealova.'),
(1564050,54,23,7,7,'Toto praví Panovník Hospodin: Nestaneť se a nebude toho.'),
(1564051,54,23,7,8,'Nebo hlava Syrské země jest Damašek, a hlava Damašku Rezin, a po šedesáti pěti letech potřín bude Efraim, tak že nebude lidem.'),
(1564052,54,23,7,9,'Mezi tím hlava Efraimova Samaří, a hlava Samaří syn Romeliášův. Jestliže nevěříte, jistě že neostojíte.'),
(1564053,54,23,7,10,'I mluvil ještě Hospodin k Achasovi, řka:'),
(1564054,54,23,7,11,'Požádej sobě znamení od Hospodina Boha svého, buď dole hluboko, aneb na hoře vysoko.'),
(1564055,54,23,7,12,'I řekl Achas: Nebudu prositi, aniž budu pokoušeti Hospodina.'),
(1564056,54,23,7,13,'Tedy řekl prorok: Slyšte nyní, dome Davidův, ještě-liž jest vám málo, lidem býti k obtížení, že i Bohu mému k obtížení jste?'),
(1564057,54,23,7,14,'Protož sám Pán dá vám znamení: Aj, panna počne, a porodí syna, a nazůve jméno jeho Immanuel.'),
(1564058,54,23,7,15,'Máslo a med jísti bude, až by uměl zavrci zlé, a vyvoliti dobré.'),
(1564059,54,23,7,16,'Nýbrž prvé než bude uměti dítě to zavrci zlé a vyvoliti dobré, opuštěna bude země, kteréž nenávidíš pro dva krále její.'),
(1564060,54,23,7,17,'Na tebe pak přivede Hospodin, a na lid tvůj, i na dům otce tvého dny, jakýchž nebylo ode dne, v němž odstoupil Efraim od Judy, a to skrze krále Assyrského.'),
(1564061,54,23,7,18,'Nebo stane se v ten den, že pošepce Hospodin muchám, kteréž jsou při nejdalších řekách Egyptských, a včelám, kteréž jsou v zemi Assyrské.'),
(1564062,54,23,7,19,'I přijdou, a usadí se všickni ti v údolích pustých a v děrách skalních, i na všech chrastinách i na všech stromích užitečných.'),
(1564063,54,23,7,20,'V ten den oholí Pán tou břitvou najatou, (skrze ty, kteříž za řekou jsou, skrze krále Assyrského), hlavu a vlasy noh, ano také i bradu do čista sholí.'),
(1564064,54,23,7,21,'I bude tehdáž, že sotva člověk zachová kravičku neb dvě ovce,'),
(1564065,54,23,7,22,'Avšak pro množství mléka, kteréhož nadojí, jísti bude máslo. Máslo zajisté a med jísti bude, kdožkoli v zemi bude zanechán.'),
(1564066,54,23,7,23,'Bude také v ten čas, že každé místo, na němž jest tisíc kmenů vinných za tisíc stříbrných, trním a hložím poroste.'),
(1564067,54,23,7,24,'S střelami a lučištěm tudy jíti musí; hložím zajisté a trním zaroste všecka země.'),
(1564068,54,23,7,25,'Všecky pak hory, kteréž motykou kopány býti mohou, nebudou se báti hloží a trní; nebo budou za pastviště volům, a bravům ku pošlapání.'),
(1564069,54,23,8,1,'I řekl mi Hospodin: Vezmi sobě knihu velikou, a napiš na ní písmem lidským: K rychlé kořisti pospíchá loupežník.'),
(1564070,54,23,8,2,'I vzal jsem sobě za svědky věrné Uriáše kněze, a Zachariáše syna Jeberechiášova.'),
(1564071,54,23,8,3,'V tom přistoupil jsem k prorokyni, kteráž počala, a porodila syna. I řekl mi Hospodin: Dej mu jméno: K rychlé kořisti pospíchá loupežník.'),
(1564072,54,23,8,4,'Nebo prvé než bude uměti dítě to volati: Otče můj, matko má, odejme zboží Damašské a loupeže Samařské lid krále Assyrského.'),
(1564073,54,23,8,5,'I to ještě mluvil Hospodin ke mně, řka:'),
(1564074,54,23,8,6,'Poněvadž pohrdl lid ten vodami Siloe tiše tekoucími, raduje se z Rezina a syna Romeliášova,'),
(1564075,54,23,8,7,'Protož aj, Pán uvede na ně vody, řeky násilné a mnohé, totiž krále Assyrského, a všecku slávu jeho, tak že vystoupí ze všech toků svých, a půjde nad všecky břehy své.'),
(1564076,54,23,8,8,'Půjde i přes Judu, rozleje se a rozejde, až k hrdlu dosáhne, a roztažená křídla jeho naplní širokost země tvé, ó Immanueli.'),
(1564077,54,23,8,9,'Puntujtež se lidé, však potříni budete, (nýbrž pozorujte všickni v daleké zemi), přepašte se, však potříni budete, přepašte se, však potříni budete.'),
(1564078,54,23,8,10,'Vejděte v radu, a zrušena bude, mluvte slovo, a neostojíť; nebo s námi jest Bůh silný.'),
(1564079,54,23,8,11,'Tak zajisté mluvil Hospodin ke mně, ujav mne za ruku, a dav mi výstrahu, abych nechodil cestou lidu tohoto, řka:'),
(1564080,54,23,8,12,'Neříkejte: Spuntování, když lid ten praví: Spuntování; aniž se jako oni strachujte, nerci-li, abyste se děsiti měli.'),
(1564081,54,23,8,13,'Hospodina zástupů samého posvěcujte; on budiž bázeň vaše i strach váš.'),
(1564082,54,23,8,14,'A budeť vám i svatyní, kamenem pak urážky a skalou pádu oběma domům Izraelským, osídlem a léčkou i obyvatelům Jeruzalémským.'),
(1564083,54,23,8,15,'I urazí se o to mnozí, a padnou, a potříni budou, aneb zapletouce se, popadeni budou.'),
(1564084,54,23,8,16,'Zavaž osvědčení, zapečeť zákon mezi učedlníky mými.'),
(1564085,54,23,8,17,'Pročež očekávati budu na Hospodina, kterýž skryl tvář svou od domu Jákobova; na něj, pravím, čekati budu.'),
(1564086,54,23,8,18,'Aj, já a dítky, kteréž mi dal Hospodin, na znamení a zázraky v Izraeli od Hospodina zástupů, kterýž přebývá na hoře Sion.'),
(1564087,54,23,8,19,'Jestliže by vám pak řekli: Dotazujte se na hadačích a věšťcích, kteříž šepcí a šveholí, rcete: Nemá-liž se lid na Bohu svém dotazovati? K mrtvým-liž místo živých má se utíkati?'),
(1564088,54,23,8,20,'K zákonu a svědectví! Pakli nechtí, nechať mluví vedlé slova toho, v němž není žádné záře,'),
(1564089,54,23,8,21,'Až by každý toulati se musil, zbědovaný jsa a hladovitý. I stane se, že se bude, hladovitý jsa, sám v sobě zlobiti, a zlořečiti králi svému a Bohu svému, buď že zhůru pohledí,'),
(1564090,54,23,8,22,'Buď že na zemi popatří, a aj, všudy ssoužení a tma, mrákota, bída i nátisk v temnostech.'),
(1564091,54,23,9,1,'A však ne tak obklíčí mrákota té země, kteráž ssoužena bude, jako když se ponejprv nepřítel dotkl země Zabulon a země Neftalím, ani jako potom, když více obtíží, naproti moři, při Jordánu Galilei lidnou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564092,54,23,9,2,'Nebo lid tento chodě v temnostech, uzří světlo veliké, a bydlícím v zemi stínu smrti světlo zastkví se.'),
(1564093,54,23,9,3,'Rozmnožil jsi tento národ, ale nezveličils veselé. A však veseliti se budou před tebou, tak jako se veselí ve žni, jako se radují, když dělí kořisti,'),
(1564094,54,23,9,4,'Když jho břemene jeho a prut ramene jeho, hůl násilníka jeho polámeš, jako za dnů Madianských,'),
(1564095,54,23,9,5,'Kdyžto všickni bojovníci předěšeni, a roucha ve krvi zbrocena, ano což hořeti mohlo, i ohněm spáleno.'),
(1564096,54,23,9,6,'Nebo dítě narodilo se nám, syn dán jest nám, i bude knížetství na rameni jeho, a nazváno bude jméno jeho: Předivný, Rádce, Bůh silný, Rek udatný, Otec věčnosti, Kníže pokoje.'),
(1564097,54,23,9,7,'K rozmnožování pak toho knížetství a pokoje, jemuž nebude konce, sedne na stolici Davidově, a na království jeho, až je i v řád uvede, a utvrdí v soudu a v spravedlnosti, od tohoto času až na věky. Horlivost Hospodina zástupů to učiní.'),
(1564098,54,23,9,8,'Slovo poslal Pán Jákobovi, a padlo v Izraeli.'),
(1564099,54,23,9,9,'A zvíť všecken lid, Efraim, i obyvatelé Samařští, kteříž v pýše a vysokomyslnosti srdce říkají:'),
(1564100,54,23,9,10,'Padly cihly, ale my tesaným kamenem stavěti budeme; planí fíkové podťati jsou, a my to v cedry směníme.'),
(1564101,54,23,9,11,'Ale zvýší Hospodin protivníky Rezinovy nad něj, a nepřátely jeho svolá,'),
(1564102,54,23,9,12,'Syrské po předu, a Filistinské po zadu. I budou žráti Izraele celými ústy, aniž ve všem tom odvrátí se prchlivost jeho, ale ruka jeho předce bude vztažená.'),
(1564103,54,23,9,13,'Protože se lid ten nenavrací k tomu, kterýž jej bije, a Hospodina zástupů nehledají,'),
(1564104,54,23,9,14,'Protož odetne Hospodin od Izraele hlavu i ocas, ratolest i sítí jednoho dne.'),
(1564105,54,23,9,15,'(Stařec a vzácný člověk, onť jest hlava, prorok pak, kterýž učí lži, onť jest ocas.)'),
(1564106,54,23,9,16,'Nebo vůdcové lidu tohoto jsou svůdcové, a kteříž se jim vésti dadí, zhynuli.'),
(1564107,54,23,9,17,'Protož z mládenců jeho nepotěší se Pán, a nad sirotky a vdovami jeho neslituje se; nebo všickni jsou pokrytci a zločinci, a každá ústa mluví nešlechetnost. Aniž ve všem tom odvrátí se prchlivost jeho, ale předce ruka jeho bude vztažená.'),
(1564108,54,23,9,18,'Nebo roznícena jsouc jako oheň bezbožnost, bodláčí a trní pálí, potom zapálí i houště lesu; pročež rozptýleni budou jako dým u povětří.'),
(1564109,54,23,9,19,'Pro hněv Hospodina zástupů zatmí se země, a ten lid bude jako pokrm ohně. Žádný ani bratra svého šanovati nebude,'),
(1564110,54,23,9,20,'Ale krájeje sobě po pravé straně, však lačněti bude, a zžíraje po levé, však nenasytí se. Jeden každý maso ramene svého žráti bude,'),
(1564111,54,23,9,21,'Manasses Efraima a Efraim Manessesa, oba pak spolu proti Judovi budou. Ve všem tom však neodvrátí se prchlivost jeho, ale předce ruka jeho bude vztažená.'),
(1564112,54,23,10,1,'Běda těm, kteříž ustanovují práva nepravá, a spisovatelům, kteříž těžkosti spisují,'),
(1564113,54,23,10,2,'Aby odstrkovali nuzné od soudu, a vydírali spravedlnost chudých lidu mého, vdovy aby byly kořist jejich, a sirotky aby loupili.'),
(1564114,54,23,10,3,'I což učiníte v den navštívení a zpuštění, kteréž zdaleka přijde? K komu se o pomoc utečete? A kde zanecháte slávy své,'),
(1564115,54,23,10,4,'By nemusila skloniti se mezi vězni, a mezi zbitými klesnouti? Ve všem tom neodvrátí se prchlivost jeho, ale předce ruka jeho bude vztažená.'),
(1564116,54,23,10,5,'Běda Assurovi, metle hněvu mého, ačkoli hůl rozhněvání mého jest v rukou jeho,'),
(1564117,54,23,10,6,'A na národ ošemetný pošli jej, a o lidu hněvu mého přikáži jemu, aby směle bral kořisti, a loupil bez milosti, a položil jej v pošlapání jako bláto na ulicích.'),
(1564118,54,23,10,7,'Ale on ne tak se bude domnívati, ani srdce jeho tak mysliti bude; nebo srdce jeho jest hubiti a pléniti národy mnohé.'),
(1564119,54,23,10,8,'Nebo řekne: Zdaliž knížata má nejsou také i králové?'),
(1564120,54,23,10,9,'Zdaliž jako Charkemis není Chalno? Zdali není jako Arfad Emat? Zdali není jako Damašek Samaří?'),
(1564121,54,23,10,10,'Jakož nalezla ruka má království bohů, ješto rytiny jejich byly nad Jeruzalémských a Samařských,'),
(1564122,54,23,10,11,'Zdaliž jako jsem učinil Samaří a modlám jeho, tak neučiním Jeruzalému a obrazům jeho?'),
(1564123,54,23,10,12,'I staneť se, když dokoná Pán všecko dílo své na hoře Sion a v Jeruzalémě, že navštívím ovoce pyšného srdce krále Assyrského, a nádhernost vysokých očí jeho.'),
(1564124,54,23,10,13,'Nebo řekne: V síle ruky své to jsem vykonal, a v moudrosti své; nebo jsem rozumný byl, a odjal jsem meze národů, a poklady jejich jsem vzebral, a strhl jsem dolů, jako mocný, obyvatele.'),
(1564125,54,23,10,14,'Anobrž jako hnízdo nalezla ruka má zboží národů, a jako zbírána bývají vejce opuštěná, tak všecku zemi já jsem sebral, aniž byl, kdo by křídlem hnul, aneb otevřel ústa a siptěl.'),
(1564126,54,23,10,15,'Zdaliž se bude sekera velebiti nad toho, kdož ní seká? Zdaliž se honositi bude pila nad toho, kdož ní tře? Jako by se zpínala metla proti tomu, kdož by ji zdvihl; jako by se chlubila hůl, že není dřevem.'),
(1564127,54,23,10,16,'Protož pošle Pán, Hospodin zástupů, na vytylé jeho vyzáblost, a po zpodku slávu jeho prudce zapálí, jako silný oheň.'),
(1564128,54,23,10,17,'Nebo světlo Izraelovo bude ohněm, a Svatý jeho plamenem, i spálí a sžíře trní i bodláčí jeho jednoho dne.'),
(1564129,54,23,10,18,'Též spanilost lesu jeho, i úrodných polí jeho, od duše až do těla, všecko vyhubí. I stane se, že předěšený jsa, bude utíkati.'),
(1564130,54,23,10,19,'A pozůstalého dříví lesu jeho malý počet bude, tak že by je mohlo dítě popsati.'),
(1564131,54,23,10,20,'I stane se v ten den, nebudou více ostatkové Izraelští a pozůstalí z domu Jákobova zpoléhati na toho, kdož je tepe, ale zpoléhati budou na Hospodina, Svatého Izraelského v pravdě.'),
(1564132,54,23,10,21,'Ostatkové obrátí se, ostatkové Jákobovi k Bohu silnému, reku udatnému.'),
(1564133,54,23,10,22,'Nebo byť bylo lidu tvého, Izraeli, jako písku mořského, ostatkové jeho obrátí se. Pohubení uložené rozhojní spravedlnost.'),
(1564134,54,23,10,23,'Pohubení, pravím, a to jisté, Pán, Hospodin zástupů, učiní u prostřed vší této země.'),
(1564135,54,23,10,24,'Protož takto praví Pán, Hospodin zástupů: Neboj se Assyrského, lide můj, kterýž přebýváš na Sionu. Prutem umrská tě, a holí svou opřáhne na tebe na cestě Egyptské.'),
(1564136,54,23,10,25,'Po maličkém zajisté času dokoná se hněv a prchlivost má k vyhlazení jich.'),
(1564137,54,23,10,26,'Nebo vzbudí na něj Hospodin zástupů bič, jako porážku Madianských na skále Goréb, a jakož pozdvihl holi své na moře, tak jí pozdvihne na něj, na cestě Egyptské.'),
(1564138,54,23,10,27,'I stane se v ten den, že složeno bude břímě jeho s ramene tvého, a jho jeho s šíje tvé, nýbrž zkaženo bude jho od přítomnosti pomazaného.'),
(1564139,54,23,10,28,'Přitáhne do Aiat, přejde přes Migron, v Michmas složí nádobí svá.'),
(1564140,54,23,10,29,'Projdou průchod, v Gabaa budou míti hospodu k přenocování; ulekne se Ráma, Gabaa Saulovo uteče.'),
(1564141,54,23,10,30,'Naříkej hlasem svým, město Gallim, ať se slyší v Lais: Ach, ubohá Anatot.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564142,54,23,10,31,'Pohne se Madmena, obyvatelé Gábim schopí se.'),
(1564143,54,23,10,32,'Ještě téhož dne zastavě se v Nobe, pohrozí rukou svou hoře dcery Sionské, pahrbku Jeruzalémskému.'),
(1564144,54,23,10,33,'Aj, Panovník Hospodin zástupů oklestí vší silou ratolesti, ty pak, kteříž jsou vysokého zrostu, podetne; i budou vysocí sníženi.'),
(1564145,54,23,10,34,'Vyseká též houšť lesů sekerou, i Libán od velikomocného padne.'),
(1564146,54,23,11,1,'Ale vyjdeť proutek z pařezu Izai, a výstřelek z kořenů jeho vyroste, a ovoce ponese.'),
(1564147,54,23,11,2,'Na němž odpočine Duch Hospodinův, Duch moudrosti a rozumnosti, Duch rady a síly. Duch umění a bázně Hospodinovy.'),
(1564148,54,23,11,3,'A bude stižitelný v bázni Hospodinově, a nebudeť podlé vidění očí svých souditi, ani podlé slyšení uší svých trestati.'),
(1564149,54,23,11,4,'Ale souditi bude chudé podlé spravedlnosti, a v pravosti trestati tiché v zemi. Bíti zajisté bude zemi holí úst svých, a duchem rtů svých zabije bezbožného.'),
(1564150,54,23,11,5,'Nebo spravedlnost bude pasem bedr jeho, a pravda přepásaním ledví jeho.'),
(1564151,54,23,11,6,'I bude bydliti vlk s beránkem a pardus s kozlátkem ležeti; tolikéž tele a lvíče i krmný dobytek spolu budou, a malé pacholátko je povede.'),
(1564152,54,23,11,7,'Také i kráva a nedvědice spolu pásti se budou, a plod jejich spolu ležeti, lev pak jako vůl plevy jísti bude.'),
(1564153,54,23,11,8,'A lítý had nad děrou pohrávati bude s dítětem prsí požívajícím, a to, kteréž ostaveno jest, směle sáhne rukou svou do díry bazališkovy.'),
(1564154,54,23,11,9,'Neuškodí, aniž zahubí na vší mé hoře svaté; nebo země naplněna bude známostí Hospodina, tak jako vodami moře naplněno jest.'),
(1564155,54,23,11,10,'A budeť v ten den, že na kořen Izai, kterýž stane za korouhev národům, pohané pilně ptáti se budou; nebo odpočívání jeho bude slavné.'),
(1564156,54,23,11,11,'I bude v ten den, že přičiní Pán po druhé ruky své, aby shledal ostatky lidu svého, což jich zanecháno bude od Assura, a od Egypta, a od Patros, a od Chus, a od Elam, a od Sinear, a od Emat, a od ostrovů mořských.'),
(1564157,54,23,11,12,'A vyzdvihne korouhev mezi pohany, a sbéře zahnané Izraelské, a rozptýlené Judovy shromáždí ode čtyř stran země.'),
(1564158,54,23,11,13,'I přestane nenávist Efraimova, a nepřátelé Judovi vyhlazeni budou. Efraim nebude nenáviděti Judy, a Juda nebude ssužovati Efraima.'),
(1564159,54,23,11,14,'Ale vletí na rameno Filistinských k západu, a spolu loupiti budou národy východní. Na Idumejské a Moábské sáhnou rukou svou, a synové Ammon poslouchati jich budou.'),
(1564160,54,23,11,15,'Zkazí též Hospodin zátoku moře Egyptského, a vztáhne ruku svou na řeku v prudkosti větru svého, a rozrazí ji na sedm potůčků, a učiní, aby je v obuvi přejíti mohli.'),
(1564161,54,23,11,16,'I bude silnice ostatkům lidu toho, kterýž zanechán bude od Assyrských, jako byla Izraelovi v ten den, když vycházel z země Egyptské.'),
(1564162,54,23,12,1,'I díš v ten den: Oslavovati tě budu, Hospodine, proto že byv hněviv na mne, odvrátil jsi prchlivost svou, a utěšil jsi mne.'),
(1564163,54,23,12,2,'Aj, Bůh silný spasení mé, doufati budu, a nebudu se strašiti; nebo síla má a píseň a spasení mé jest Bůh Hospodin.'),
(1564164,54,23,12,3,'I budete vážiti vody s radostí z studnic toho spasení,'),
(1564165,54,23,12,4,'A řeknete v ten den: Oslavujte Hospodina, vzývejte jméno jeho, známé čiňte mezi lidmi skutky jeho, připomínejte, že vyvýšené jest jméno jeho.'),
(1564166,54,23,12,5,'Žalmy zpívejte Hospodinu, nebo veliké věci učinil; a to známé buď po vší zemi.'),
(1564167,54,23,12,6,'Prokřikni a zpívej, obyvatelkyně Sionská, nebo veliký jest u prostřed tebe Svatý Izraelský.'),
(1564168,54,23,13,1,'Břímě Babylona, kteréž viděl Izaiáš syn Amosův.'),
(1564169,54,23,13,2,'Na hoře vysoké vyzdvihněte korouhev, povyšte hlasu k nim, dejte návěští rukou, ať vejdou do bran knížecích.'),
(1564170,54,23,13,3,'Já jsem přikázal posvěceným svým, povolal jsem také i udatných reků svých k vykonání hněvu svého, veselících se z vyvýšení mého.'),
(1564171,54,23,13,4,'Hlas množství na horách, jakožto lidu mnohého, hlas a zvuk království a národů shromážděných: Hospodin zástupů sbírá vojsko k válce.'),
(1564172,54,23,13,5,'Táhnou z země daleké od končin nebes. Hospodin a osudí prchlivosti jeho, aby poplénil všecku zemi.'),
(1564173,54,23,13,6,'Kvělte, nebo blízko jest den Hospodinův, jako zpuštění od Všemohoucího přijde.'),
(1564174,54,23,13,7,'A protož všeliké ruce oslábnou, a všeliké srdce člověka rozplyne se.'),
(1564175,54,23,13,8,'I budou předěšeni, svírání a bolesti je zachvátí, jako rodička stonati budou; každý nad bližním svým užasne se, tváře jejich k plameni podobné budou.'),
(1564176,54,23,13,9,'Aj, den Hospodinův přichází přísný, a zůřivost a rozpálení hněvu, aby obrátil tu zemi v poušť, a hříšníky její z ní vyhladil.'),
(1564177,54,23,13,10,'Nebo hvězdy nebeské a planéty jejich nedopustí svítiti světlu svému; zatmí se slunce při vycházení svém, a měsíc nevydá světla svého.'),
(1564178,54,23,13,11,'A navštívím na okršlku země zlost, a na bezbožných nepravost jejich; a káži přestati pýše pyšných, a vysokomyslnost tyranů snížím.'),
(1564179,54,23,13,12,'Způsobím to, že dražší bude člověk nad zlato čisté, člověk, pravím, nad zlato z Ofir.'),
(1564180,54,23,13,13,'Z té příčiny zatřesu nebesy, a pohne se země z místa svého, v prchlivosti Hospodina zástupů, a ve dni rozpálení hněvu jeho.'),
(1564181,54,23,13,14,'I bude jako srna zplašená, a jako stádo, když není, kdo by je shromáždil; jeden každý k lidu svému se obrátí, a každý do země své uteče.'),
(1564182,54,23,13,15,'Kdožkoli nalezen bude, bude proboden, a kteříž by se koli shlukli, od meče padnou.'),
(1564183,54,23,13,16,'Nadto i dítky jejich rozrážíny budou před očima jejich, domové jejich zloupeni, a ženy jejich poškvrněny.'),
(1564184,54,23,13,17,'Aj, já vzbudím proti nim Médské, kteříž sobě stříbra nebudou vážiti, a v zlatě nebudou se kochati,'),
(1564185,54,23,13,18,'Ale z luků dítky rozrážeti, aniž se nad plodem života slitují, aniž synům odpustí oko jejich.'),
(1564186,54,23,13,19,'I budeť Babylon, někdy ozdoba království a okrasa důstojnosti Kaldejské, podobný podvrácené Sodomě a Gomoře.'),
(1564187,54,23,13,20,'Nebudou se v něm osazovati na věky, ani bydliti od pokolení až do pokolení; aniž rozbije tam stanu svého Arab, ani pastýři tam odpočívati budou.'),
(1564188,54,23,13,21,'Ale lítá zvěř tam odpočívati bude, a domové jejich šelmami naplněni budou; bydliti budou tam i sovy, a příšery tam skákati budou.'),
(1564189,54,23,13,22,'Ozývati se také budou sobě hrozné potvory na palácích jejich, a draci na hradích rozkošných. A blízkoť jest, že přijde čas jeho, a dnové jeho prodlévati nebudou.'),
(1564190,54,23,14,1,'Nebo slituje se Hospodin nad Jákobem, a vyvolí zase Izraele, a dá jim odpočinutí v zemi jejich; a připojí se k nim cizozemec, a přídržeti se budou domu Jákobova.'),
(1564191,54,23,14,2,'Nebo pojmou ty národy, a přivedou je k místu svému, i uvedou je v dědictví dům Izraelský v zemi Hospodinově, za služebníky a za děvky; a jímati budou ty, kteříž je zjímali, a panovati budou nad násilníky svými.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564192,54,23,14,3,'I staneť se v ten den, v němž tobě odpočinutí dá Hospodin od těžkosti tvé a strachu tvého, a od poroby těžké, v kterouž jsi byl podroben,'),
(1564193,54,23,14,4,'Že uživeš přísloví tohoto o králi Babylonském, a řekneš: Aj, jak přestal násilník! Přestalo dychtění po zlatě.'),
(1564194,54,23,14,5,'Potřískal Hospodin hůl bezbožných, prut panujících,'),
(1564195,54,23,14,6,'Mrskajícího lidi v prchlivosti mrskáním ustavičným, panujícího v hněvě nad národy, kteříž ssužováni bývali bez lítosti.'),
(1564196,54,23,14,7,'Odpočívá, jest v pokoji všecka země, zvučně prozpěvují.'),
(1564197,54,23,14,8,'I jedloví veselí se nad tebou, i cedroví Libánské, řkouce: Jakž jsi klesl, nepovstal, kdo by nás podtínal.'),
(1564198,54,23,14,9,'I peklo zespod zbouřilo se pro tebe, k vyjití vstříc přicházejícímu tobě vzbudilo pro tě mrtvé, všecka knížata země; kázalo vyvstati z stolic jejich i všechněm králům národů.'),
(1564199,54,23,14,10,'Všickni tito odpovídajíce, mluví tobě: Což ty také jsi zemdlen jako i my, a nám podobný učiněn?'),
(1564200,54,23,14,11,'Svrženať jest do pekla pýcha tvá, i zvuk hudebných nástrojů tvých; moli tobě podestláno, a červi tě přikrývají.'),
(1564201,54,23,14,12,'Jakž to, že jsi spadl s nebe, ó lucifeře v jitře vycházející? Poražen jsi až na zem, ještos zemdlíval národy.'),
(1564202,54,23,14,13,'Však jsi ty říkával v srdci svém: Vstoupím do nebe, nad hvězdy Boha silného vyvýším stolici svou, a posadím se na hoře shromáždění k straně půlnoční.'),
(1564203,54,23,14,14,'Vstoupím nad výsosti oblaku, budu rovný Nejvyššímu.'),
(1564204,54,23,14,15,'A ty pak stržen jsi až do pekla, pryč na stranu do jámy.'),
(1564205,54,23,14,16,'Ti, kdož tě uzří, za tebou se ohlédati, a tebe spatřovati budou, říkajíce: To-liž jest ten muž, kterýž nepokojil zemi, a pohyboval královstvími,'),
(1564206,54,23,14,17,'Obracel jako v pustinu okršlek země, a města jeho bořil, vězňů svých nepropouštěl domů?'),
(1564207,54,23,14,18,'Všickni králové národů, což jich koli bylo, pochováni slavně doma jeden každý z nich;'),
(1564208,54,23,14,19,'Ty pak zavržen jsi od hrobu svého jako ratolest ohyzdná, a roucho zbitých, ukrutně zraněných, kteříž se dostávají do jámy mezi kamení, a jako mrcha pošlapaná.'),
(1564209,54,23,14,20,'Nebudeš k oněmno v pohřbu přiúčastněn, nebo jsi poplénil zemi svou, lid svůj jsi pomordoval; nebudeť připomínáno na věky símě zlostníků.'),
(1564210,54,23,14,21,'Připravte se k zmordování synů jeho pro nepravosti otců jejich, aby nepovstali, a dědičně neujali země, a nenaplnili svrchku okršlku zemského městy.'),
(1564211,54,23,14,22,'Nebo povstanu proti nim, praví Hospodin zástupů, a zahladím jméno Babylona i ostatky syna i vnuka, praví Hospodin.'),
(1564212,54,23,14,23,'A obrátím jej v dědictví bukačů, a v jezera vod, a vymetu jej pometlem zahynutí, praví Hospodin zástupů.'),
(1564213,54,23,14,24,'Přisáhl Hospodin zástupů, řka: Jistě že jakž jsem myslil, tak bude, a jakž jsem uložil, stane se,'),
(1564214,54,23,14,25,'Že potru Assyrského v zemi své, a na horách svých pošlapám jej, a odejde z nich jho jeho, břímě také jeho s ramene jejich sňato bude.'),
(1564215,54,23,14,26,'Toť jest ta rada, kteráž zavřína jest o vší té zemi, a to jest ta ruka vztažená proti všechněm těm národům.'),
(1564216,54,23,14,27,'Poněvadž pak Hospodin zástupů usoudil, kdo to tedy zruší? A ruku jeho vztaženou kdo odvrátí?'),
(1564217,54,23,14,28,'Léta kteréhož umřel král Achas, stalo se proroctví toto:'),
(1564218,54,23,14,29,'Neraduj se všecka ty země Filistinská, že zlámán jest prut toho, kterýž tě mrskal; nebo z plemene hadího vyjde bazališkus, jehož plod bude drak ohnivý létající.'),
(1564219,54,23,14,30,'I budou se pásti prvorození chudých, a nuzní bezpečně odpočívati budou; kořen pak tvůj umořím hladem, a ostatky tvé zmorduje.'),
(1564220,54,23,14,31,'Kvěl, ó bráno, křič město, již jsi rozplynula se všecka ty země Filistinská; nebo od půlnoci oheň přijde aniž bude, kdo by stranil z obcí jeho.'),
(1564221,54,23,14,32,'Co pak odpovědí poslové národů? To, že Hospodin upevnil Sion, v němž útočiště mají chudí z lidu jeho.'),
(1564222,54,23,15,1,'Břímě Moábských. Když v noci Ar Moábské popléněno a zkaženo bude, když i Kir Moábské v noci popléněno a zkaženo bude,'),
(1564223,54,23,15,2,'Vstoupí do Baít, a do Dibon a do Bamot s pláčem, nad Nébo a nad Medaba Moáb kvíliti bude, na všech hlavách jeho bude lysina, a každá brada oholena bude.'),
(1564224,54,23,15,3,'Na ulicích jeho přepáší se žíní, na střechách jeho i na ryncích jeho každý kvíliti bude, s pláčem se vraceje.'),
(1564225,54,23,15,4,'A křičeti bude Ezebon a Eleale, až v Jasa slyšán bude hlas jejich, nýbrž i zbrojní Moábští křičeti budou. Duše každého z nich žalostiti bude, a řekne:'),
(1564226,54,23,15,5,'Srdce mé řve nad Moábem a pevnostmi jeho, až slyšeti v Ségor, jako jalovice tříletá; nebo cestou Luchitskou s pláčem půjde, a kudyž se chodí k Choronaim, křik hrozný vydávati budou,'),
(1564227,54,23,15,6,'Proto že vody Nimrim vymizejí, že uschne bylina, usvadne tráva, aniž co zeleného bude.'),
(1564228,54,23,15,7,'A protož zboží nachované a statky jejich odnesou ku potoku Arabim.'),
(1564229,54,23,15,8,'Nebo křik obejde vůkol meze Moábské, až do Eglaim kvílení jeho, a až do Beer Elim kvílení jeho,'),
(1564230,54,23,15,9,'Poněvadž i vody Dimon naplněny budou krví. Přidám zajisté Dimonu přídavků, a pošli na ty, kteříž ujdou z Moábských, lvy, i na pozůstalé v té zemi.'),
(1564231,54,23,16,1,'Pošlete beránky panovníku země, počnouc od Sela až do pouště, k hoře dcery Sionské.'),
(1564232,54,23,16,2,'Sic jinak bude Moáb jako pták místa nemající, a s hnízda sehnaný; budou dcery Moábské při brodech Arnon.'),
(1564233,54,23,16,3,'Svolej radu, učiň soud, připrav stín svůj u prostřed poledne jako noc; skrej vyhnané, místa nemajícího nevyzrazuj.'),
(1564234,54,23,16,4,'Nechať u tebe pobudou vyhnaní moji, ó Moábe, buď skrýší jejich před zhoubcím; nebo přestane násilník, přestane zhoubce, pošlapávající vyhlazen bude z země.'),
(1564235,54,23,16,5,'A upevněn bude milosrdenstvím trůn, a seděti bude na něm stále v stánku Davidovu ten, kterýž by soudil a vyhledával soudu a pospíchal k spravedlnosti.'),
(1564236,54,23,16,6,'Ale slýchaliť jsme o pýše Moábově, že velmi pyšný jest, o pýše jeho, a chloubě jeho i spouzení se jeho, ale nepřijdouť k vykonání myšlénky jeho.'),
(1564237,54,23,16,7,'Protož kvíliti bude Moáb před Moábem, jeden každý kvíliti bude; nad grunty Kirchareset úpěti budete, a říkati: Jižť jsou zkaženi.'),
(1564238,54,23,16,8,'Nýbrž i réví Ezebon usvadlo, i vinní kmenové Sibma. Páni národů potřeli výborné réví jeho, kteréž až do Jazer dosahalo, a bylo se rozšířilo při poušti; rozvodové jeho rozložili se, a dosahali až za moře.'),
(1564239,54,23,16,9,'Protož pláči pro pláč Jazerských a pro vinici Sibma; svlažuji tě slzami svými, ó Ezebon a Eleale, nebo provyskování nad ovocem tvým letním a nad žní tvou kleslo.'),
(1564240,54,23,16,10,'A přestalo veselé a plésání nad polem úrodným, na vinicích se nezpívá, ani prokřikuje, vína v presích netlačí ten, kterýž tlačívá. Takž i já provyskování přestávám.'),
(1564241,54,23,16,11,'Protože střeva má nad Moábem jako harfa znějí, a vnitřnosti mé pro Kircheres.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564242,54,23,16,12,'I stane se, když zřejmé bude, an ustává Moáb nad výsostmi, že vejde do svatyně své, aby se modlil, však nic nespraví.'),
(1564243,54,23,16,13,'Toť jest to slovo, kteréž mluvil Hospodin o Moábovi již dávno.'),
(1564244,54,23,16,14,'Nyní pak praví Hospodin, řka: Po třech letech, jakáž jsou léta nájemníka, v potupu uvedena bude sláva Moábova se vším množstvím velikým, tak že ostatkové jeho budou skrovní, přemaličcí a mdlí.'),
(1564245,54,23,17,1,'Břímě Damašku. Aj, Damašek přestane býti městem, a bude hromadou rumu.'),
(1564246,54,23,17,2,'Zpuštěná města Aroer pro stáda budou, a odpočívati tam budou, a nebude žádného, kdo by je strašil.'),
(1564247,54,23,17,3,'I bude odjata pevnost od Efraima, a království od Damašku i ostatků Syrských; jako i sláva synů Izraelských na nic přijdou, praví Hospodin zástupů.'),
(1564248,54,23,17,4,'I bude v ten den, že opadne sláva Jákobova, a tuk těla jeho vymizí.'),
(1564249,54,23,17,5,'Nebo bude Assur jako ten, jenž shromažďuje ve žni obilé, a rámě jeho žne klasy, anobrž bude jako ten, jenž zbírá klasy v údolí Refaim.'),
(1564250,54,23,17,6,'Paběrkové však zanecháni v něm budou, jako po očesání olivy dvě neb tři olivky na vrchu větve, a čtyry neb pět na ratolestech jejích plodistvých, praví Hospodin Bůh Izraelský.'),
(1564251,54,23,17,7,'V ten den patřiti bude člověk k Učiniteli svému, a oči jeho k Svatému Izraelskému hleděti budou.'),
(1564252,54,23,17,8,'A nebude patřiti k oltářům, dílu rukou svých; ani k tomu, což učinili prstové jeho, hleděti bude, ani k hájům, ani k obrazům slunečným.'),
(1564253,54,23,17,9,'V ten den budou města síly jeho opuštěna jako chrastinka a růžťka, kteráž opuštěna budou od synů Izraelských, i spustneš, ó země.'),
(1564254,54,23,17,10,'Nebos se zapomněla na Boha spasení svého, a na skálu síly své nezpomenulas. Protož ačkoli štěpy rozkošné štěpuješ, a kmen vinný přespolní sázíš,'),
(1564255,54,23,17,11,'V čas štěpování tvého štípí, aby rostlo, opatruješ, nýbrž téhož jitra o to, což seješ, aby se pučilo, pečuješ: v den však užitku odejde žeň, na žalost tvou přetěžkou.'),
(1564256,54,23,17,12,'Běda množství lidí mnohých, kteříž jako zvuk mořský ječí, a hlučícím národům, kteříž jako zvuk vod násilných hlučí,'),
(1564257,54,23,17,13,'Národům jako zvuk vod mnohých zvučícím; nebo je Bůh okřikne. Pročež daleko utíkati budou, a honěni budou jako plevy po vrších od větru, a jako chumel od vichřice.'),
(1564258,54,23,17,14,'Nebo u večer aj, předěšení, a než jitro přijde, anť ho není. Tenť jest podíl těch, kteříž nás potlačují, a los těch, kteříž nás loupí.'),
(1564259,54,23,18,1,'Běda zemi zastěňující se křídly, kteráž jest při řekách země Mouřenínské,'),
(1564260,54,23,18,2,'Posílající po moři posly, v nástrojích z sítí po vodách, řka: Jděte, poslové rychlí, k národu rozptýlenému a zloupenému, k lidu hroznému zdávna i posavad, k národu všelijak potlačenému, jehož zemi řeky roztrhaly.'),
(1564261,54,23,18,3,'Všickni obyvatelé světa, a přebývající na zemi, když bude korouhev vyzdvižena na horách, uzříte, a když troubiti se bude trubou, uslyšíte.'),
(1564262,54,23,18,4,'Nebo takto praví Hospodin ke mně: Spokojímť se, a podívám z příbytku svého, a budu jako teplo vysušující po dešti, a jako oblak dešťový v čas horké žně.'),
(1564263,54,23,18,5,'Před vinobraním zajisté, když se vypučí pupenec, a květ vydá hrozen trpký, ještě rostoucí, tedy podřeže révíčko noži, a rozvody odejme a zpodtíná.'),
(1564264,54,23,18,6,'I budou zanecháni všickni spolu ptactvu z hor, a šelmám zemským, a bude na nich přes léto ptactvo, a všeliké šelmy zemské na nich přes zimu zůstanou.'),
(1564265,54,23,18,7,'V ten čas přinesen bude dar Hospodinu zástupů (od lidu rozptýleného a zloupeného, od lidu hrozného zdávna i posavad, národu všelijak potlačeného, jehožto zemi řeky rozchvátaly), k místu jména Hospodina zástupů, hoře Sion.'),
(1564266,54,23,19,1,'Břímě Egyptských. Aj, Hospodin béře se na oblaku lehkém, a přitáhne na Egypt. I pohnou se modly Egyptské před tváří jeho, a srdce Egyptských rozplyne se u prostřed něho.'),
(1564267,54,23,19,2,'Nebo spustím Egyptské s Egyptskými, tak že bojovati budou jeden každý proti bratru svému, a přítel proti příteli svému, město proti městu, království proti království.'),
(1564268,54,23,19,3,'A na nic přijde duch Egyptských u prostřed něho, a radu jeho sehltím. I raditi se budou modl a kouzedlníků a zaklinačů a hadačů.'),
(1564269,54,23,19,4,'Dám zajisté Egypt v ruku pánů ukrutných, a král přísný panovati bude nad nimi, praví Pán, Hospodin zástupů.'),
(1564270,54,23,19,5,'A vymizejí vody z moře, i řeka osákne a vyschne.'),
(1564271,54,23,19,6,'I vzdálí se řeky, opadnou a vyschnou potokové Egyptští, třtí i rákosí usvadne.'),
(1564272,54,23,19,7,'Tráva okolo potoka a při pramenu potoka, i vše, což se seje při potoku, uschne, zmizí a ztratí se.'),
(1564273,54,23,19,8,'I budou žalostiti rybáři, a kvíliti všickni, kteříž mecí do potoka udici; a kteříž rozstírají síti na vody, na nouzi přijdou.'),
(1564274,54,23,19,9,'Zahanbeni budou i ti, kteříž dělají věci lněné a hedbávné, a kteříž tkají kment.'),
(1564275,54,23,19,10,'Nebo síti jeho budou zkaženy, i všickni dělající rybníky pro ryby.'),
(1564276,54,23,19,11,'Jistě žeť jsou blázni knížata Soan, moudrých rádců Faraonových rada zhlupěla. Jakž říkati můžete Faraonovi: Syn moudrých já jsem, syn králů starožitných?'),
(1564277,54,23,19,12,'Kdež jsou, kde ti moudří tvoji? Nechať oznámí nyní tobě, vědí-li, co uložil Hospodin zástupů o Egyptu.'),
(1564278,54,23,19,13,'Zbláznila se knížata Soan, podvedena jsou knížata Nof, svedli Egypt přednější v pokolení jeho.'),
(1564279,54,23,19,14,'Hospodin pustil mezi ně ducha závrativého, i spraví to, že zbloudí Egypt při všelikém předsevzetí svém, tak jako bloudí ožralec při vývratku svém.'),
(1564280,54,23,19,15,'Aniž bude dílo v Egyptě, kteréž by učinila hlava neb ocas, ratolest aneb sítí.'),
(1564281,54,23,19,16,'V ten den bude Egypt podobný ženám; nebo strašiti se a děsiti bude před zdvižením ruky Hospodina zástupů, kterouž on zdvihne proti němu.'),
(1564282,54,23,19,17,'A budeť země Judská Egyptu k hrůzi; každý, kdož zpomene na ni, strašiti se bude, pro radu Hospodina zástupů, kterouž zavřel o něm.'),
(1564283,54,23,19,18,'V ten den bude pět měst v zemi Egyptské, mluvících jazykem Kananejským, a přisahajících skrze Hospodina zástupů, jedno pak nazváno bude město zpuštění.'),
(1564284,54,23,19,19,'V ten den bude oltář Hospodinův u prostřed země Egyptské, a sloup při pomezí jejím Hospodinu;'),
(1564285,54,23,19,20,'Bude, pravím, na znamení a na svědectví Hospodinu zástupů v zemi Egyptské. A když volati budou k Hospodinu příčinou těch, kteříž by je ssužovali, tedy pošle jim spasitele a kníže, i vysvobodí je.'),
(1564286,54,23,19,21,'I bude známý Hospodin Egyptským; nebo poznají Egyptští Hospodina v ten den, a ctíti jej budou obětmi a dary, a činiti budou sliby Hospodinu, i plniti.'),
(1564287,54,23,19,22,'A tak bíti bude Hospodin Egypt, aby zbije, uzdravil jej; nebo obrátí se k Hospodinu, a on je vyslyší a uzdraví.'),
(1564288,54,23,19,23,'V ten den bude silnice z Egypta do Assyrie, i budou choditi Assyrští do Egypta, a Egyptští do Assyrie, a sloužiti budou Egyptští s Assyrskými Hospodinu.'),
(1564289,54,23,19,24,'V ten den bude Izrael Egyptským a Assyrským jako třetí z nich, i budou požehnaní u prostřed země.'),
(1564290,54,23,19,25,'Nebo požehná jim Hospodin zástupů, řka: Požehnaný lid můj Egyptský, a dílo rukou mých Assur, i dědictví mé Izrael.'),
(1564291,54,23,20,1,'Léta, kteréhož přitáhl Tartan do Azotu, poslán jsa od Sargona, krále Assyrského, a když bojoval proti Azotu, a vzal jej,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564292,54,23,20,2,'Času toho mluvil Hospodin skrze Izaiáše syna Amosova, řka: Jdi a slož žíni z bedr svých, a obuv svou zzuj s noh svých. I učinil tak, a chodil nahý a bosý.'),
(1564293,54,23,20,3,'I řekl Hospodin: Jakož chodí služebník můj Izaiáš nahý a bosý, na znamení a zázrak, třetího roku Egypta a Mouřenínské země,'),
(1564294,54,23,20,4,'Tak povede král Assyrský jaté Egyptské a jaté Mouřenínské, mladé i staré, nahé a bosé, s obnaženými zadky, k hanbě Egyptských.'),
(1564295,54,23,20,5,'I užasnou se a zahanbí nad Mouřeníny, útočištěm svým, a nad Egyptskými, chloubou svou.'),
(1564296,54,23,20,6,'Tedy řekne obyvatel ostrovu tohoto v ten den: Aj hle, toť naše útočiště, k němuž jsme se utíkali o pomoc, abychom vysvobozeni byli z moci krále Assyrského. Jakž bychom my tedy ušli?'),
(1564297,54,23,21,1,'Břímě pustého moře. Jako vichřice na poledne se žene, tak přijde z pouště, z země hrozné.'),
(1564298,54,23,21,2,'Vidění tvrdé jest mi ukázáno. Nešlechetník nešlechetnost páše, a zhoubce hubí. Přitáhniž Elame, Médský oblehni. Všelikému úpění jeho přestati rozkáži.'),
(1564299,54,23,21,3,'Z té příčiny naplněna jsou bedra má bolestí, úzkosti postihly mne jako úzkosti rodičky; sklíčen jsem, slyše to, strnul jsem, vida to.'),
(1564300,54,23,21,4,'Zkormoutilo se srdce mé, hrůza předěsila mne, noc mých rozkoší obrátila se mi v strach.'),
(1564301,54,23,21,5,'Přistroj na stůl, nechť stráž drží strážný, jez, pí. Vstaňte knížata, mažte pavézy.'),
(1564302,54,23,21,6,'Nebo tak řekl ke mně Pán: Jdi, postav strážného, kterýž by to, což uhlédá, oznámil.'),
(1564303,54,23,21,7,'I viděl vozy, a dvěma řady jízdu, vozy, kteréž oslové, a vozy, kteréž velbloudové táhli; šetřil zajisté pilně s velikou bedlivostí.'),
(1564304,54,23,21,8,'A volal jako lev: Jáť, Pane můj, stojím na stráži ustavičně ve dne, nýbrž na stráži své já stávám v každičkou noc.'),
(1564305,54,23,21,9,'(A aj, v tom přijeli na vozích muži a dvěma řady jízda.) Zvolal tedy a řekl: Padl, padl Babylon, a všecky rytiny bohů jeho o zem roztřískány.'),
(1564306,54,23,21,10,'Méť jest humno, a obilé humna mého. Což jsem slyšel od Hospodina zástupů, Boha Izraelského, oznámil jsem vám.'),
(1564307,54,23,21,11,'Břímě Dumy. Slyším hlas z Seir: Strážný, co bylo v noci? Strážný, co se stalo v noci?'),
(1564308,54,23,21,12,'Řekl strážný: Přišlo jitro, a tolikéž noc; chcete-li hledati, hledejte. Navraťte se, přiďte.'),
(1564309,54,23,21,13,'Břímě na Arabii. Po lesích v Arabii nocleh mívati budete, ó pocestní Dedanských.'),
(1564310,54,23,21,14,'Obyvatelé země Tema nechať vynesou vody vstříc žíznivému; s chlebem jeho nechať vyjdou proti utíkajícímu.'),
(1564311,54,23,21,15,'Nebo před mečem utíkati budou, před mečem vytaženým, před lučištěm nataženým, před těžkostí boje.'),
(1564312,54,23,21,16,'Tak zajisté řekl Pán ke mně: Že po roce, jakýž jest rok nájemníka, přestane všecka sláva Cedar,'),
(1564313,54,23,21,17,'A pozůstalý počet střelců udatných synů Cedar zmenšen bude; nebo Hospodin Bůh Izraelský to mluvil.'),
(1564314,54,23,22,1,'Břímě údolí vidění. Cožť se stalo, že jsi vystoupilo všecko na střechy,'),
(1564315,54,23,22,2,'Město plné hřmotu a hluku, město veselící se? Zbití tvoji nejsou zbiti mečem, ani zhynuli v boji.'),
(1564316,54,23,22,3,'Všecka knížata tvá rozprchla se napořád, od střelců svázána jsou. Což jich koli nalezeno jest v tobě, napořád svázáni jsou, zdaleka utíkají.'),
(1564317,54,23,22,4,'Protož jsem řekl: Ponechejte mne, ať hořekuji s pláčem, a neusilujte mne těšiti nad popléněním dcerky lidu mého.'),
(1564318,54,23,22,5,'Nebo jest den ssoužení, a pošlapání, a v mysli sevření ode Pána, Hospodina zástupů, v údolí vidění, den boření zdi, a křiku k horám.'),
(1564319,54,23,22,6,'Byltě zajisté Elam pochytil toul s vozy lidu vojenského, a Kir ukázal pavézu.'),
(1564320,54,23,22,7,'I stalo se, že nejvýbornější údolí tvá naplněna byla vozy, a vojáci silně položili se u brány,'),
(1564321,54,23,22,8,'A odkryto bylo zastření Judovo; však obrátilo jsi zřetel v ten den k zbrojné komoře.'),
(1564322,54,23,22,9,'I k zbořeninám města Davidova dohlédli jste, nebo mnohé byly, a shromáždili jste vody rybníka dolního.'),
(1564323,54,23,22,10,'Domy též Jeruzalémské sečtli jste, i pobořili, abyste utvrdili zed.'),
(1564324,54,23,22,11,'Udělali jste také stav mezi dvěma zdmi pro vody rybníka starého, aniž jste popatřili k Učiniteli jeho, a toho, kdo jej vzdělal od starodávna, neviděli jste.'),
(1564325,54,23,22,12,'Nadto když volal Pán, Hospodin zástupů, v ten den k pláči a k kvílení, a k lysině a k přepásání se žíní.'),
(1564326,54,23,22,13,'A aj, radost a veselí vaše zabijeti voly, a bíti ovce, jísti maso, a píti víno, a říkati: Jezme, píme, nebo zítra zemřeme.'),
(1564327,54,23,22,14,'Ale známéť jest to v uších mých, praví Hospodin zástupů. Protož nikoli vám nebude odpuštěna ta nepravost, až i zemřete, praví Pán, Hospodin zástupů.'),
(1564328,54,23,22,15,'Takto praví Pán, Hospodin zástupů: Jdi, vejdi k Sochitskému tomu, k Sobnovi správci domu, a řekni:'),
(1564329,54,23,22,16,'Co ty zde máš? A koho zde máš, že jsi vytesal sobě zde hrob? Vytesals sobě na vysokém místě hrob svůj, a vystavěls na skále příbytek svůj.'),
(1564330,54,23,22,17,'Aj, Hospodin, kterýž tě přistřel, jakž na muže znamenitého náleží, a kterýž tě výborně přioděl,'),
(1564331,54,23,22,18,'Prudce tě zakulí jako kuli do země všelijak prostranné. Tam umřeš, tam i vozové slávy tvé, ó ohyzdo domu Pána svého.'),
(1564332,54,23,22,19,'A tak seženu tě s místa tvého, a s úřadu tvého svrhu tě.'),
(1564333,54,23,22,20,'I stane se v ten den, že povolám služebníka svého Eliakima syna Helkiášova,'),
(1564334,54,23,22,21,'A obleku jej v sukni tvou, a pasem tvým potvrdím ho, panování tvé také dám v ruku jeho. I bude za otce obyvatelům Jeruzalémským a domu Judovu,'),
(1564335,54,23,22,22,'A vložím klíč domu Davidova na rameno jeho. Když otevře, žádný nezavře, a když zavře, žádný neotevře.'),
(1564336,54,23,22,23,'A vbiji jej jako hřebík v místě pevném, a bude stolicí slávy domu otce svého.'),
(1564337,54,23,22,24,'I zavěsí na něm synové a dcery všecku slávu domu otce jeho, všecko nádobí, i to nejmenší, od nádobí, z něhož se pije, až do všech nádob vinných.'),
(1564338,54,23,22,25,'V ten den, praví Hospodin zástupů, pohne se hřebík, kterýž vbit byl v místě pevném, a vyťat bude, a spadne, odťato bude i břímě, kteréž jest na něm; nebo Hospodin mluvil.'),
(1564339,54,23,23,1,'Břímě Týru. Kvělte lodí mořské; nebo popléněn jest, tak že není ani domu. Aniž kdo přichází z země Citim; známé učiněno jest jim.'),
(1564340,54,23,23,2,'Umlknětež obyvatelé ostrovu, kterýž kupci Sidonští, plavíce se přes moře, naplňovali,'),
(1564341,54,23,23,3,'A jehož úrody na velikých vodách, símě Sichor, žeň jeho, užitek potoka, a kterýž byl skladem národů.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564342,54,23,23,4,'Zastyď se, Sidone, nebo praví moře, pevnost mořská, řkuc: Nepracuji ku porodu, a nerodím, a nevychovávám mládenců, aniž odchovávám panen.'),
(1564343,54,23,23,5,'Jakož nad pověstí o Egyptu, tak žalostiti budou nad pověstí o Týru.'),
(1564344,54,23,23,6,'Přepravte se do Tarsu, kvělte obyvatelé ostrovu.'),
(1564345,54,23,23,7,'To-liž by se vždycky veselilo? Jestiť starožitnost jeho ode dnů starodávních, ale zavedouť je daleko nohy jeho.'),
(1564346,54,23,23,8,'Kdo že to usoudil proti Týru, korunujícímu jiné, jehož kupci jsou jako knížata, a kramáři jeho znamenití v zemi?'),
(1564347,54,23,23,9,'Hospodin zástupů usoudil to, aby zohavil pýchu všelikého slavného, a za nic položil všecky znamenité země.'),
(1564348,54,23,23,10,'Navrať se do země své jako řeka, ó dcero Tarská, neníť tam více ani pasu.'),
(1564349,54,23,23,11,'Vztáhl ruku svou na moře, pohnul královstvími; Hospodin přikázal o tržišti, aby zkaženy byly pevnosti jeho.'),
(1564350,54,23,23,12,'A řekl: Nebudeš se více veseliti, trpěc nátisk, panno, dcero Sidonská. Povstaň, beř se do Citim, ale i tam nebudeš míti odpočinutí.'),
(1564351,54,23,23,13,'Aj, země Kaldejská, ten lid nebyl lidem. Assur vzdělal ji pro obyvatele pustin, vystavěli věže jejich, vzdělali paláce její, tak že i Assyrii vyvrátil.'),
(1564352,54,23,23,14,'Kvělte lodí mořské, nebo zpuštěna jest pevnost vaše.'),
(1564353,54,23,23,15,'I stane se v ten den, že v zapomenutí bude Týrus za sedmdesáte let, jako za věk krále jednoho. Do skonání sedmdesáti let bude míti Týrus jako písničku nevěstky.'),
(1564354,54,23,23,16,'Vezmi harfu, obcházej město, ó nevěstko v zapomenutí daná, hrej dobře, zpívej dlouho, abys v pamět uvedena byla.'),
(1564355,54,23,23,17,'I bude po dokonání sedmdesáti let, že navštíví Hospodin Týr, ale on navrátí se zase k nevěstčí mzdě své, a smilniti bude se všemi královstvími země na okršlku světa.'),
(1564356,54,23,23,18,'Však kupectví jeho a mzda jeho svatá bude Hospodinu. Nebude na poklad skládána, ani schovávána, ale pro ty, kteříž přebývají před Hospodinem, bude kupectví jeho, aby jedli do sytosti, a měli roucho dobré.'),
(1564357,54,23,24,1,'Aj, Hospodin vyprázdní zemi, a pustou učiní; promění zajisté způsob její, a rozptýlí obyvatele její.'),
(1564358,54,23,24,2,'I budeť jakož lid tak kníže, jakož služebník tak pán jeho, jakož děvka tak paní její, jakož kupující tak prodávající, jakož půjčující tak vypůjčující, jakož lichevník tak ten, jenž lichvu dává.'),
(1564359,54,23,24,3,'Náramně vyprázděna bude země, a velice zloupena; nebo Hospodin mluvil slovo toto.'),
(1564360,54,23,24,4,'Kvíliti bude a padne země, zemdlí a padne okršlek země, zemdlejí vysocí národové zemští,'),
(1564361,54,23,24,5,'Proto že i ta země poškvrněna jest pod obyvateli svými; nebo přestoupili zákony, změnili ustanovení, zrušili smlouvu věčnou.'),
(1564362,54,23,24,6,'Protož prokletí zžíře zemi, a vypléněni budou obyvatelé její; protož hořeti budou obyvatelé země, a pozůstane lidí maličko.'),
(1564363,54,23,24,7,'Žalostiti bude mest, usvadne vinný kmen, úpěti budou všickni veselého srdce.'),
(1564364,54,23,24,8,'Odpočine radost bubnů, přestane hluk veselících se, utichne veselí harfy.'),
(1564365,54,23,24,9,'Nebudou píti vína s prozpěvováním, zhořkne opojný nápoj pitelům jeho.'),
(1564366,54,23,24,10,'Potříno bude město marnosti; zavřín bude každý dům, aby do něho nechodili.'),
(1564367,54,23,24,11,'Naříkání bude na ulicích pro víno, zatemněno bude všeliké veselí, odstěhuje se radost země.'),
(1564368,54,23,24,12,'Zůstane v městě poušť, i brány zbořeny budou.'),
(1564369,54,23,24,13,'Nebo tak bude u prostřed země, u prostřed národů, jako očesání olivy, jako paběrkování, když se dokoná vinobraní.'),
(1564370,54,23,24,14,'Tiť pozdvihnou hlasu svého, prozpěvovati budou v důstojnosti Hospodinově, prokřikovati budou i při moři.'),
(1564371,54,23,24,15,'Protož v údolích oslavujte Hospodina, na ostrovích mořských jméno Hospodina Boha Izraelského.'),
(1564372,54,23,24,16,'Od končin země slyšíme písničky o slávě spravedlivého. Ale já řekl jsem: Zchuravěl jsem, zchuravěl jsem. Ach, na mé hoře, že nešlechetní nešlechetnost provodí, nešlechetnost, pravím, že tak nestydatě páší.'),
(1564373,54,23,24,17,'Hrůza a jáma a osídlo tě očekává, ó obyvateli země.'),
(1564374,54,23,24,18,'I stane se, že kdož uteče před pověstí strachu, upadne do jámy, a kdož vyleze z jámy, v osídle uvázne; nebo průduchové s výsosti otevříni budou, a zatřesou se základové země.'),
(1564375,54,23,24,19,'Velmi se rozstoupí země, velice se rozpadne země, náramně pohybovati se bude země.'),
(1564376,54,23,24,20,'Motaje, motati se bude země jako opilý, a přenešena bude jako chaloupka; nebo těžce na ni dolehne nepravost její, i padne tak, že nepovstane více.'),
(1564377,54,23,24,21,'I stane se v ten den, navštíví Hospodin vojsko vysoké na výsosti, též i krále zemské na zemi.'),
(1564378,54,23,24,22,'Kteřížto shromážděni budou, tak jako shromažďováni bývají vězňové do žaláře, a zavříni budou u vězení; po mnohých, pravím, dnech navštíveni budou.'),
(1564379,54,23,24,23,'I zahanbí se měsíc, a zastydí slunce, když kralovati bude Hospodin zástupů na hoře Sion, a v Jeruzalémě, a před starci svými slavně.'),
(1564380,54,23,25,1,'Hospodine, ty jsi Bůh můj, vyvyšovati tě budu, a oslavovati budu jméno tvé; nebo jsi učinil předivné věci. Rady tvé zdávna uložené jsou věrná pravda.'),
(1564381,54,23,25,2,'Nebo jsi obrátil město v hromadu, město hrazené v zříceninu, paláce cizozemců, aby nebyli městem, a na věky aby nebyli zase staveni.'),
(1564382,54,23,25,3,'Protož ctíti tě budou lid silný, města národů hrozných báti se tebe budou.'),
(1564383,54,23,25,4,'Nebo jsi byl hradem chudému, hradem nuznému v úzkosti jeho, útočištěm před povodní, zastíněním před horkem; (nebo vzteklost ukrutníků podvrátila by zed).'),
(1564384,54,23,25,5,'Hlučení cizozemců jsi přetrhl jako horkost v sucho, horkost stínem oblaku; zhouba ukrutných přetržena.'),
(1564385,54,23,25,6,'I učiní Hospodin zástupů všechněm národům na hoře této hody z věcí tučných, hody z vína vystálého, z věcí tučných, mozk v sobě majících, z vína vystálého a učištěného.'),
(1564386,54,23,25,7,'A zkazí na hoře této zastření, kteréž zastírá všecky lidi, a přikrytí, jímž přikryti jsou všickni národové.'),
(1564387,54,23,25,8,'Sehltí i smrt u vítězství, a setře Panovník Hospodin slzu s všeliké tváři, a pohanění lidu svého odejme ze vší země; (nebo Hospodin mluvil).'),
(1564388,54,23,25,9,'Pročež řekne v ten den: Aj, Bůh náš tento jest, očekávaliť jsme na něj, a vysvobodil nás. Onť jest Hospodin, jehož jsme očekávali; plésati a veseliti se budeme v spasení jeho.'),
(1564389,54,23,25,10,'Nebo odpočine ruka Hospodinova na hoře této, a mlácen bude Moáb na místě svém, jako vymlacována bývá pleva do hnoje.'),
(1564390,54,23,25,11,'A roztáhneť ruce své u prostřed něho, jako roztahuje ten, kterýž plyne k plování, a poníží pýchy jeho rameny rukou svých.'),
(1564391,54,23,25,12,'A tak pevnost i výsost zdí tvých sehne, poníží a srazí na zem až do prachu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564392,54,23,26,1,'V ten den zpívána bude píseň tato v zemi Judské: Město máme pevné, sám Bůh spasením obdařil zdi a valy jeho.'),
(1564393,54,23,26,2,'Otevřete brány, ať vejde národ spravedlivý, ostříhající všeliké pravdy.'),
(1564394,54,23,26,3,'Člověka spoléhajícího na tě ostříháš v pokoji; v pokoji, nebo v tebe doufá.'),
(1564395,54,23,26,4,'Doufejtež v Hospodina až na věky; nebo v Hospodinu, v Hospodinu jest skála věčná.'),
(1564396,54,23,26,5,'Ale obyvatele vysokých míst snižuje, města vyvýšeného ponižuje, ponižuje ho až k zemi, sráží je až do prachu.'),
(1564397,54,23,26,6,'Pošlapává je noha, nohy chudého, krokové nuzných.'),
(1564398,54,23,26,7,'Cesta spravedlivého jest upřímá; stezku spravedlivého vyrovnáváš.'),
(1564399,54,23,26,8,'Také na cestě soudů tvých, Hospodine, očekáváme na tě; ke jménu tvému a k rozpomínání se na tě patří žádost duše.'),
(1564400,54,23,26,9,'Duše má touží po tobě v noci, nýbrž i duchem svým ve mně ráno tě hledám. Nebo když soudové tvoji dějí se na zemi, obyvatelé okršlku zemského učí se spravedlnosti.'),
(1564401,54,23,26,10,'Když se milost činí bezbožnému, neučí se spravedlnosti; v zemi pravosti neprávě činí, a nehledí na důstojnost Hospodinovu.'),
(1564402,54,23,26,11,'Hospodine, ačkoli vyvýšena jest ruka tvá, však toho nevidí. Uzříť a zahanbeni budou, závidíce lidu tvému; nadto i ohněm ty nepřátely své sehltíš.'),
(1564403,54,23,26,12,'Nám, Hospodine, způsobíš pokoj; nebo i všecko, cožkoli se dálo při nás, dělal jsi pro dobré naše.'),
(1564404,54,23,26,13,'Hospodine, Bože náš, panovaliť jsou nad námi páni jiní než ty, (my však toliko v tebe doufajíce, rozpomínali jsme se na jméno tvé).'),
(1564405,54,23,26,14,'Ale již zemřevše, neoživouť, mrtví jsouc, nevstanouť, proto že jsi je navštívil, a vyplénil, i zahladil všecku památku jejich.'),
(1564406,54,23,26,15,'Rozmnožil jsi národ, ó Hospodine, rozmnožil jsi národ, a oslaven jsi, ač jsi jej byl vzdálil do všech končin země.'),
(1564407,54,23,26,16,'Hospodine, v úzkosti hledali tebe, vylévali prosby, když jsi je trestával.'),
(1564408,54,23,26,17,'Jako těhotná, blížíc se ku porodu, svírá se, křičí v bolestech svých, tak jsme byli před tváří tvou, Hospodine.'),
(1564409,54,23,26,18,'Počali jsme, svírali jsme se, jako bychom rodili vítr: však jsme žádného vysvobození nezpůsobili zemi, aniž padli obyvatelé okršlku zemského.'),
(1564410,54,23,26,19,'Oživouť mrtví tvoji, těla mrtvá má vstanou. Prociťte a prozpěvujte, obyvatelé prachu. Nebo rosa tvá jako rosa na bylinách, ale bezbožné k zemi zporážíš.'),
(1564411,54,23,26,20,'Ej lide můj, vejdi do pokojů svých, a zavři dvéře své za sebou; schovej se na maličkou chvilku, dokudž nepřejde hněv.'),
(1564412,54,23,26,21,'Nebo aj, Hospodin béře se z místa svého, aby navštívil nepravost na obyvatelích země, a odkryje země zbité své, a nebude přikrývati více zmordovaných svých.'),
(1564413,54,23,27,1,'V ten den navštíví Hospodin mečem svým přísným, velikým a mocným Leviatana, hada dlouhého, a Leviatana, hada stočilého, a zabije draka, kterýž jest v moři.'),
(1564414,54,23,27,2,'V ten den o vinici výborné víno vydávající zpívejte.'),
(1564415,54,23,27,3,'Já Hospodin, kterýž ji ostříhám, každé chvilky budu ji svlažovati, a aby jí někdo neuškodil, v noci i ve dne ji ostříhati.'),
(1564416,54,23,27,4,'Prchlivosti při mně žádné není. Kdož mi dá bodlák a trn, abych proti ní válčil, a spálil ji docela?'),
(1564417,54,23,27,5,'Zdali sváže sílu mou, aby učinil se mnou pokoj, aby pravím, učinil se mnou pokoj?'),
(1564418,54,23,27,6,'Vždyť na to přijde, že se vkoření Jákob, zkvetne a zroste Izrael, a naplní okršlek zemský ovocem.'),
(1564419,54,23,27,7,'Nebo zdaliž jej tak ubil, jako ubil nepřítele jeho? Zdali jej zamordoval, jako jsou jiní zmordováni od něho?'),
(1564420,54,23,27,8,'Vedlé míry trestal jej i tehdáž, když jej zavesti dal, ješto nepřítele zachvátil větrem svým tuhým východním.'),
(1564421,54,23,27,9,'A protož tím způsobem očištěna bude nepravost Jákobova, a toť bude veliký užitek, že odejme hřích jeho, když rozmece všecko kamení oltáře jako kamení vápenné rozsypané, neostojí hájové, ani sluneční obrazové;'),
(1564422,54,23,27,10,'Když město hrazené zpustne, a bude příbytkem zavrženým a opuštěným jako poušť, tam pásti se bude tele, a tam léhati, a pokazí docela výstřelky jeho.'),
(1564423,54,23,27,11,'Když počne zráti žeň jeho, potřína bude; ženy přijdouce, zapálí ji. Nebo ten lid nemá žádného rozumu; protož neslituje se nad ním učinitel jeho, a stvořitel jeho neučiní jemu milosti.'),
(1564424,54,23,27,12,'I stane se v ten den, když pomstu uvoditi bude Hospodin od toku řeky až do potoka Egyptského, že vy, synové Izraelští, po jednom sebráni budete.'),
(1564425,54,23,27,13,'Stane se také v ten den, že troubeno bude trubou velikou, i přijdou, kteříž byli zahynuli v zemi Assyrské, a zahnáni byli do země Egyptské, a klaněti se budou Hospodinu na hoře svaté v Jeruzalémě.'),
(1564426,54,23,28,1,'Běda koruně pýchy, ožralcům Efraimským, květu nestálému v kráse a slávě své, těm,kteříž jsou při vrchu údolí velmi úrodného, a ztupeným od vína.'),
(1564427,54,23,28,2,'Aj, silný a mocný Páně jako příval s krupobitím, jako povětří vyvracející, jako povodeň vod prudkých a rozvodnilých prudce až k zemi porazí.'),
(1564428,54,23,28,3,'Nohami pošlapána bude koruna pýchy, ožralci Efraimští.'),
(1564429,54,23,28,4,'Tehdáž stane se, že květ ten nestálý v kráse a slávě své těch, kteříž jsou při vrchu údolí velmi úrodného, bude jako ranní ovoce, prvé než léto bývá; kteréž vida někdo, nepustil by ho z ruky, až by je snědl.'),
(1564430,54,23,28,5,'V ten den bude Hospodin zástupů korunou ozdoby, a korunou okrasy ostatkům lidu svého,'),
(1564431,54,23,28,6,'A duchem soudu sedícímu na soudu, a silou těm, kteříž zapuzují válku až k bráně.'),
(1564432,54,23,28,7,'Ale i ti od vína bloudí, a od opojného nápoje se potácejí. Kníže i prorok bloudí, přeplňujíce se nápojem opojným, pohlceni jsou od vína, potácejí se od nápoje opojného, bloudí u vidění, chybují v soudu.'),
(1564433,54,23,28,8,'Nebo všickni stolové plní jsou vývratků a lejn, tak že žádného místa čistého není.'),
(1564434,54,23,28,9,'Kohož by vyučoval umění? A komu by posloužil, aby vyrozuměl naučení? Zdali ostaveným od mléka, odtrženým od prsí?'),
(1564435,54,23,28,10,'Poněvadž měli naučení za naučením, naučení za naučením, správu za správou, správu za správou, trošku odtud, trošku od onud.'),
(1564436,54,23,28,11,'A však jako by neznámou řečí a cizím jazykem mluvil lidu tomuto,'),
(1564437,54,23,28,12,'Kdyžto jim řekl: Totoť jest odpočinutí, způsobte odpočinutí ustalému, toť jest, pravím, odpočinutí. Ale nechtěli slyšeti.'),
(1564438,54,23,28,13,'I bude jim slovo Hospodinovo naučení za naučením, naučení za naučením, správa za správou, správa za správou, troška odtud, troška od onud; k tomu aby šli a padajíce nazpět, setříni byli, a zapleteni jsouce, aby polapeni byli.'),
(1564439,54,23,28,14,'Protož slyšte slovo Hospodinovo, muži posměvači, panující nad lidem tímto, kterýž jest v Jeruzalémě:'),
(1564440,54,23,28,15,'Proto že říkáte: Učinili jsme smlouvu s smrtí, a s peklem máme srozumění, pomsta rozvodnilá, ač přecházeti bude, nepřijde na nás, jakžkoli jsme položili svod za útočiště své, a pod falší jsme se ukryli:'),
(1564441,54,23,28,16,'Z té příčiny takto praví Panovník Hospodin: Aj, já zakládám na Sionu kámen, kámen zkušený, úhelný drahý, základ pevný; kdo věří, nebudeť kvapiti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564442,54,23,28,17,'A vykonám soud podlé pravidla, a spravedlnost podlé závaží, i zamete to omylné útočiště krupobití, a skrýši povodeň zatopí.'),
(1564443,54,23,28,18,'A tak zrušena bude smlouva vašes smrtí, a srozumění vaše s peklem neostojí; a když přecházeti bude pomsta rozvodnilá, budete od ní pošlapáni.'),
(1564444,54,23,28,19,'Jakž jen počne přecházeti, zachvátí vás; každého zajisté jitra přecházeti bude, ve dne i v noci. I stane se, že sám strach tomu, což jste slýchali, k srozumění poslouží,'),
(1564445,54,23,28,20,'Zvlášť když bude tak krátké lůže, že se nebude lze stáhnouti, a přikrýti úzké, by se i skrčil.'),
(1564446,54,23,28,21,'Nebo jako na hoře Perazim povstane Hospodin, jako v údolí Gabaon hněvati se bude, aby dělal dílo své, neobyčejné dílo své, aby vykonal skutek svůj, neobyčejný skutek svůj.'),
(1564447,54,23,28,22,'A protož nebuďtež již posměvači, aby se nezadrhla osídla vaše; nebo o zkažení, a to jistém, vší země slyšel jsem ode Pána, Hospodina zástupů.'),
(1564448,54,23,28,23,'Nastavte uší, a slyšte hlas můj; pozorujte, a poslechněte řeči mé.'),
(1564449,54,23,28,24,'Zdaliž každého dne oře oráč, aby sel, prohání brázdy, a vláčí rolí svou?'),
(1564450,54,23,28,25,'Zdali když srovná svrchek její, nerozsívá viky, a nerozmítá kmínu a neseje pšenice přední a ječmene výborného, i špaldy v místě příhodném?'),
(1564451,54,23,28,26,'Nebo učí jej rozšafnosti, Bůh jeho vyučuje jej.'),
(1564452,54,23,28,27,'Nebýváť pak okovaným smykem mlácena vika, aniž kolem vozním po kmínu se vůkol jezdí; nebo holí vytlouká se vika, a kmín prutem.'),
(1564453,54,23,28,28,'Pšenice mlácena bývá; však i té ne vždycky mlátiti bude, aniž ji potře kolem vozu svého, ani o zuby jeho rozdrobí.'),
(1564454,54,23,28,29,'I to od Hospodina zástupu vyšlo, kterýž jest divný v radě, a veleslavný v skutku.'),
(1564455,54,23,29,1,'Běda Arieli, Arieli městu, v kterémž bydlil David. Přidejte rok po roku, nechať zařezují beránky.'),
(1564456,54,23,29,2,'Však předce ssoužím Ariele. I nastane žalost a zámutek, nebo mi bude jako Ariel.'),
(1564457,54,23,29,3,'Položím se zajisté vůkol proti tobě vojensky, a ssoužím tě bez lítosti, a vzdělám proti tobě šance.'),
(1564458,54,23,29,4,'Tehdy sníženo jsuc, z země mluviti budeš, a z prachu šeptati bude řeč tvá; bude, pravím, jako hadače z země hlas tvůj, a z prachu řeč tvá siptěti.'),
(1564459,54,23,29,5,'Nebo jako prášku drobného bude množství nepřátel tvých, a jako plev létajících množství ukrutníků, a stane se to hned v okamžení.'),
(1564460,54,23,29,6,'Od Hospodina zástupů navštíveno bude hromem a země třesením, a zvukem velikým, vichřicí a bouří a plamenem ohně sžírajícího.'),
(1564461,54,23,29,7,'I budeť jako zdání vidění nočního množství všech národů bojujících proti Arieli, a všech válčících proti němu a pevnostem jeho, a ssužujících jej.'),
(1564462,54,23,29,8,'Bude, pravím, jako když se lačnému ve snách zdá, an jí, ale když procítí, prázdný jest život jeho; a jako když se žíznivému ve snách zdá, an pije, a když procítí, žíznivým zůstává, a duše jeho vždy žádá: tak bude množství všech národů, bojujících proti hoře Sion.'),
(1564463,54,23,29,9,'Jak zpozdilí jste, ješto byste se měli užasnouti; rozkoš provodíte, ješto byste měli na pomoc volati. Zpili se, ale ne vínem; potácejí se, ale ne od nápoje opojného.'),
(1564464,54,23,29,10,'Nebo naplnil vás Hospodin duchem chropotu, a zavřel oči vaše; proroků i knížat vašich nejopatrnějších oči zastřel.'),
(1564465,54,23,29,11,'Protož jest vám všeliké vidění podobné slovům knihy zapečetěné, kterouž dadí-li tomu, kterýž zná písmo, řkouce: Čti ji medle, i řekne: Nemohu, nebo zapečetěná jest.'),
(1564466,54,23,29,12,'Pakli dadí knihu tomu, kterýž nezná písma, řkouce: Čti ji medle, tedy dí: Neznám písma.'),
(1564467,54,23,29,13,'Nebo praví Pán: Proto že lid tento přibližuje se ústy svými, a rty svými ctí mne, srdce pak své vzdaluje a bázeň jejich, již se mne bojí, jest z přikázaní lidských pošlá:'),
(1564468,54,23,29,14,'Z té příčiny, aj, já také divně zajdu s lidem tímto, divně, pravím, a zázračně. I zahyne moudrost moudrých jeho, a opatrnost opatrných jeho vymizí.'),
(1564469,54,23,29,15,'Běda těm, kteříž hluboko před Hospodinem skrývají radu, jejichž každý skutek děje se v temnostech, a říkají: Kdo nás vidí? A kdo nás šetří?'),
(1564470,54,23,29,16,'Převrácená myšlení vaše zdali nejsou podobná hlině hrnčířově? Zdali říká dílo o dělníku svém: Neučinil mne? A účinek říká-liž o učiniteli svém: Nerozuměl?'),
(1564471,54,23,29,17,'Zdaliž po maličkém a kratičkém času neobrátí se Libán v pole, a pole za les nebude počteno?'),
(1564472,54,23,29,18,'I uslyší v ten den hluší slova knihy, a z mrákoty a tmy oči slepých prohlédnou.'),
(1564473,54,23,29,19,'Ale tiší rozveselí se náramně v Hospodinu, a chudí lidé v Svatém Izraelském plésati budou,'),
(1564474,54,23,29,20,'Kdyžto přestane ukrutník, a zahyne posměvač, a všickni, kteříž jsou pilni marnosti, vypléněni budou,'),
(1564475,54,23,29,21,'Kteříž obviňují z hříchu člověka pro slovo, a na toho, kterýž je tresce, v bráně lécejí, a pro nic utiskují spravedlivého.'),
(1564476,54,23,29,22,'Protož takto dí o domu Jákobovu Hospodin, kterýž vykoupil Abrahama: Nebudeť již zahanben Jákob, aniž více tvář jeho zbledne.'),
(1564477,54,23,29,23,'Nebo když uzří syny své, dílo rukou mých u prostřed sebe, an posvěcují jména mého, tedy posvěcovati budou Svatého Jákobova, a k bázni Boha Izraelského sloužiti,'),
(1564478,54,23,29,24,'Aby bloudící duchem nabyli rozumnosti, a reptáci naučili se umění.'),
(1564479,54,23,30,1,'Běda synům zpurným, dí Hospodin, skládajícím radu, kteráž není ze mne, a přikrývajícím ji přikrytím, ale ne z ducha mého, aby hřích k hříchu přidávali;'),
(1564480,54,23,30,2,'Kteříž chodí a sstupují do Egypta, nedotazujíce se úst mých, aby se zmocňovali v síle Faraonově, a doufali v stínu Egyptském.'),
(1564481,54,23,30,3,'Nebo síla Faraonova bude vám k hanbě, a to odpočívání v stínu Egyptském k lehkosti,'),
(1564482,54,23,30,4,'Proto že knížata jeho byli v Soan, a poslové jeho do Chanes chodili.'),
(1564483,54,23,30,5,'Všeckyť k zahanbení přivede skrze lid, kterýž jim nic neprospěje, aniž bude ku pomoci, ani k užitku, ale k hanbě toliko a k útržce.'),
(1564484,54,23,30,6,'Břímě hovad poledních v zemi nátisku a ssoužení, odkudž lev a lvíče, ještěrka a drak ohnivý létající, odnesou na hřbetě hovádek bohatství svá, a na hrbu velbloudů poklady své k lidu, kterýž jim nic neprospěje.'),
(1564485,54,23,30,7,'Nebo Egyptští nadarmo a na prázdno pomáhati budou. Pročež ohlašuji to, že by síla jejich byla s pokojem seděti.'),
(1564486,54,23,30,8,'Nyní jdi, napiš to na tabuli před očima jejich, a na knize vyrej to, aby to zůstávalo do nejposlednějšího dne, a až na věky věků,'),
(1564487,54,23,30,9,'Že lid tento zpurný jest, synové lháři, synové, kteříž nechtí poslouchati zákona Hospodinova;'),
(1564488,54,23,30,10,'Kteříž říkají vidoucím: Nemívejte vidění, a prorokům: Neprorokujte nám toho, což pravého jest; mluvte nám pochlebenství, prorokujte oklamání.'),
(1564489,54,23,30,11,'Sejděte s cesty, svozujte od stezky, nechať se vzdálí od tváří naší Svatý Izraelský.'),
(1564490,54,23,30,12,'Protož takto praví Svatý Izraelský: Proto že pohrdáte slovem tím, a doufáte ve lsti a v převrácenosti, a spoléháte na ni:'),
(1564491,54,23,30,13,'Z té příčiny bude vám tato nepravost jako zed tržená padající, a vydutí na zdi vysoké, jejíž brzké a náhlé bývá oboření.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564492,54,23,30,14,'A rozrazí ji, jako rozrážejí nádobu hrnčířskou rozbitou; neodpustíť, tak že nebude nalezena po rozražení jejím ani střepina k nabrání ohně z ohniště, anebo k nabrání vody z louže.'),
(1564493,54,23,30,15,'Nebo tak řekl Panovník Hospodin, Svatý Izraelský: Obrátíte-li se, a spokojíte-li se, zachováni budete. V utišení se a v doufání bude síla vaše. Ale nechcete.'),
(1564494,54,23,30,16,'Nýbrž říkáte: Nikoli, ale na koních utečeme. Protož utíkati budete. Na rychlých ujedeme. Ale rychlejší budou stihající vás.'),
(1564495,54,23,30,17,'Jeden tisíc před okřiknutím jednoho, a před okřiknutím pěti utíkati budete, až (jestliže však vás co pozůstane), budete zanecháni jako okleštěné dřevo na vrchu hory, a jako korouhev na pahrbku.'),
(1564496,54,23,30,18,'Protoť pak shovívá Hospodin, milost vám čině, a protoť se vyvýší, aby se smiloval nad vámi; nebo Hospodin jest Bůh spravedlivý. Blahoslavení všickni, kteříž očekávají na něj.'),
(1564497,54,23,30,19,'Lid zajisté na Sionu a v Jeruzalémě bydliti bude. Nikoli plakati nebudeš; k hlasu volání tvého bude všelijak milost činiti s tebou. Hned jakž uslyší, ohlásíť se.'),
(1564498,54,23,30,20,'A ačkoli Pán dá vám chleba úzkosti a vody ssoužení, však nebudou více odjati tobě učitelé tvoji, ale očima svýma vídati budeš učitele své,'),
(1564499,54,23,30,21,'A ušima svýma slýchati slovo tobě po zadu řkoucích: Toť jest ta cesta, choďte po ní, buď že byste se na pravo neb na levo uchýlili.'),
(1564500,54,23,30,22,'Tedy zavržete obestření rytin svých stříbrných, a oděv slitin svých zlatých; odloučíš je jako nemoc svou trpící, řka jim: Táhněte tam.'),
(1564501,54,23,30,23,'Dáť i déšť na rozsívání tvé, kterýmž bys osíval zemi, a chléb z úrody země, kterýž bude jadrný a zdárný; v ten den pásti se bude i dobytek tvůj na pastvišti širokém.'),
(1564502,54,23,30,24,'Volové také i oslové, dělající zemi, píci čistou jísti budou, kteráž opálkou a věječkou vyčištěna bývá.'),
(1564503,54,23,30,25,'Budou také na všeliké hoře vysoké, a na všelikém pahrbku vyvýšeném pramenové a potokové vod, v den porážky veliké, když padnou věže.'),
(1564504,54,23,30,26,'Bude i světlo měsíce jako světlo slunce, světlo pak slunce bude sedmernásobní, jako světlo sedmi dnů, v den, v kterýž uváže Hospodin zlámání lidu svého, a ránu zbití jeho uzdraví.'),
(1564505,54,23,30,27,'Aj, jméno Hospodinovo přichází z daleka, jehožto hněv hořící a těžká pomsta; rtové jeho naplněni jsou prchlivostí, a jazyk jeho jako oheň sžírající.'),
(1564506,54,23,30,28,'Duch pak jeho jako potok rozvodnilý, kterýž až do hrdla dosáhne, aby tříbil národy, až by v nic obráceni byli, a uzdou svíral čelisti národů.'),
(1564507,54,23,30,29,'I budete zpívati, jako když se v noci zasvěcuje slavnost, a veseliti se srdečně, jako ten, kterýž jde s píšťalkou, bera se na horu Hospodinovu, k skále Izraelově,'),
(1564508,54,23,30,30,'Když dá slyšeti Hospodin hlas důstojnosti své, a ukáže vztaženou ruku svou s hněvem prchlivosti a plamenem ohně sžírajícího, an vše rozráží i přívalem i kamenným krupobitím.'),
(1564509,54,23,30,31,'Hlasem zajisté Hospodinovým potřín bude Assur, kterýž jiné kyjem bijíval.'),
(1564510,54,23,30,32,'Ale stane se, že každé udeření holí, kterouž doloží na něj Hospodin, silně dolehne; s bubny a harfami a bitvou veselou bojovati bude proti němu.'),
(1564511,54,23,30,33,'Nebo připraveno jest již dávno peklo, také i samému králi připraveno jest. Hluboké a široké je učinil, hranic jeho, ohně a dříví mnoho; dmýchání Hospodinovo jako potoksiry je zapaluje.'),
(1564512,54,23,31,1,'Běda těm, kteříž se utíkají do Egypta o pomoc, a v koních zpoléhají, a doufají v vozích, že jich mnoho, a v jezdcích, že jich množství veliké, a nepatří k Svatému Izraelskému, aniž Hospodina hledají,'),
(1564513,54,23,31,2,'Ještoť i on jest moudrý. Protož uvede pomstu, a nezměníť slov svých, ale povstane proti domu zlostníků a proti pomoci těch, kteříž páší nepravost.'),
(1564514,54,23,31,3,'Egyptští pak jsou lidé, a ne Bůh silný, a koni jejich tělo, a ne duch. A protož jakž jen Hospodin vztáhne ruku svou, padne i pomocník, padne i ten, jemuž byl ku pomoci; a tak jednostejně všickni ti na nic přijdou.'),
(1564515,54,23,31,4,'Nebo tak řekl Hospodin ke mně: Jako když lev řve aneb lvíče nad loupeží svou, proti němuž byl-li by svolán houf pastýřů, křiku jejich se neděsí, aniž se pro hluk jejich koří: tak sstoupí Hospodin zástupů, aby bojoval o horu Sion, a o pahrbek její.'),
(1564516,54,23,31,5,'Jako ptáci létajíce, tak hájiti bude Hospodin zástupů Jeruzaléma, anobrž obhajuje vysvobodí, pomíjeje zachová.'),
(1564517,54,23,31,6,'Navraťtež se k tomu, od něhož hluboko zabředli synové Izraelští.'),
(1564518,54,23,31,7,'Nebo v ten den zavržete jeden každý modly své stříbrné a modly své zlaté, kterýchž vám nadělaly ruce vaše, abyste hřešili.'),
(1564519,54,23,31,8,'I padne Assur od meče ne muže, a meč ne člověka zžíře jej; a utíkati bude před mečem, a nejudatnější jeho pod plat uvedeni budou.'),
(1564520,54,23,31,9,'A tak skála jeho pro strach zmizí, a knížata jeho korouhve děsiti se budou, praví Hospodin, jehož jest oheň na Sionu a pec v Jeruzalémě.'),
(1564521,54,23,32,1,'Aj, v spravedlnosti kralovati bude král, a knížata v soudu panovati budou.'),
(1564522,54,23,32,2,'Nebo bude muž ten jako skrýše před větrem, a schrana před přívalem, jako potokové vod na místě suchém, jako stín skály veliké v zemi vyprahlé.'),
(1564523,54,23,32,3,'A oči vidoucích nebudou blíkati, a uši slyšících pozorovati budou.'),
(1564524,54,23,32,4,'Pročež srdce bláznů nabude umění, a jazyk zajikavých prostranně a světle mluviti bude.'),
(1564525,54,23,32,5,'Nebudeť více nazýván nešlechetný šlechetným, a skrbný nebude slouti štědrým.'),
(1564526,54,23,32,6,'Proto že nešlechetný o nešlechetnosti mluví, a srdce jeho skládá nepravost, jak by provodil ošemetnost, a mluvil proti Hospodinu scestné věci, jak by znuzil duši lačného, a nápoj žíznivému odjal.'),
(1564527,54,23,32,7,'Také i usilování skrbného jsou škodlivá; nebo nešlechetnosti obmýšlí, jak by k záhubě přivedl ponížené slovy lživými, a mluvil proti nuznému před soudem.'),
(1564528,54,23,32,8,'Ješto šlechetný obmýšlí šlechetné věci, a takovýť při tom, což šlechetného jest, státi bude.'),
(1564529,54,23,32,9,'Ženy lhostejné, vstaňte, slyšte hlas můj; dcery bezpečně sobě počínající, ušima pozorujte řeči mé.'),
(1564530,54,23,32,10,'Za mnohé dny a léta vichrovány budete, ó vy v bezpečnosti bydlící; nebo přestane vinobraní, a klizení úrod nepřijde.'),
(1564531,54,23,32,11,'Třestež se strachem, ó lhostejné, pohnětež se, bezpečně sobě počínající; svlecte se, a obnažte se, a přepašte se po bedrách.'),
(1564532,54,23,32,12,'Kvílíce nad prsy, nad poli výbornými a nad kmeny úrodnými.'),
(1564533,54,23,32,13,'Na zemi lidu mého trní a hloží vzejde, anobrž na všech domích veselých a městě plésajícím.'),
(1564534,54,23,32,14,'Nebo rozkošný palác opuštěn bude, hluk města přestane, hrad vysoký a věže obráceny budou v jeskyně na věčnost, k radosti divokým oslům, a ku pastvišti stádům.'),
(1564535,54,23,32,15,'Dokudž nebude vylit na nás duch s výsosti, a nebude obrácena poušť v pole úrodné, a pole úrodné za les počítáno.'),
(1564536,54,23,32,16,'I bude na poušti soud bydliti, a spravedlnost na poli úrodném přebývati.'),
(1564537,54,23,32,17,'A zjeví se skutek spravedlnosti, pokoj, ovoce, pravím, spravedlnosti, pokoj a bezpečnost až na věky.'),
(1564538,54,23,32,18,'Nebo bydliti bude lid můj v obydlí pokojném, totiž v příbytcích nejbezpečnějších a v odpočívání nejpokojnějším,'),
(1564539,54,23,32,19,'Byť pak i krupobití spadlo na les, a velmi sníženo bylo město.'),
(1564540,54,23,32,20,'Blaze vám, kteříž sejete na všelikých místech úrodných, vypouštějíc tam vola i osla.'),
(1564541,54,23,33,1,'Běda tobě, zhoubce, ješto sám nebýváš huben, a kterýž nevěrně děláš, ješto tobě nečinili nevěrně. Když přestaneš býti zhoubcím, pohuben budeš; když přestaneš nevěrně činiti, nevěrněť činiti budou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564542,54,23,33,2,'Hospodine, učiň nám milost, na tebeť očekáváme; budiž ramenem svých každého jitra, a vysvobozením naším v čas ssoužení.'),
(1564543,54,23,33,3,'Před zvukem hřmotu rozprchnou se národové, před vyvýšením tvým budou rozptýleni pohané.'),
(1564544,54,23,33,4,'A sebrána bude loupež vaše, tak jako sbíráni bývají chroustové; jako připadají kobylky, tak připadnou na ni.'),
(1564545,54,23,33,5,'Vyvýšíť se Hospodin, nebo na výsosti přebývá, a naplní Sion soudem a spravedlností.'),
(1564546,54,23,33,6,'I bude upevněním časů tvých, silou i hojným spasením; moudrost a umění, a bázeň Hospodinova poklad tvůj.'),
(1564547,54,23,33,7,'Aj, rekové jejich naříkali vně, jednatelé pokoje hořce plakali.'),
(1564548,54,23,33,8,'Zpustly silnice, přestali choditi cestou; zrušil příměří, nevážil sobě měst, za nic položil sobě člověka.'),
(1564549,54,23,33,9,'Kvílila a zemdlela země, styděti se musil Libán a usvadl; Sáron učiněn jako poušť, Bázan pak a Karmel oklácen.'),
(1564550,54,23,33,10,'Jižť povstanu, praví Hospodin, již vyvýšen, již vyzdvižen budu.'),
(1564551,54,23,33,11,'Počnouce slámu, porodíte strniště; oheň dýchání vašeho sžíře vás.'),
(1564552,54,23,33,12,'I budou národové vypálené vápno, trní podťaté, ohněm spáleni budou.'),
(1564553,54,23,33,13,'Slyšte dalecí, co jsem učinil, a poznejte blízcí sílu mou.'),
(1564554,54,23,33,14,'Zděsili se na Sionu hříšníci, podjala hrůza pokrytce, řkoucí: Kdož by z nás mohl ostáti před ohněm sžírajícím? Kdož by z nás mohl ostáti před plamenem věčným?'),
(1564555,54,23,33,15,'Ten, kterýž chodí v spravedlnosti, a mluví pravé věci, kterýž pohrdá ziskem z útisku, kterýž otřásá ruce své, aby darů nepřijímal, kterýž zacpává uši své, aby neslyšel rady o vraždě, a zavírá oči své, aby se na zlé nedíval:'),
(1564556,54,23,33,16,'Ten na vysokých místech přebývati bude, hradové na skalách útočiště jeho, tomu chléb dán bude, vody jeho stálé budou.'),
(1564557,54,23,33,17,'Krále v okrase jeho uzří oči tvé, spatří i zemi dalekou.'),
(1564558,54,23,33,18,'Srdce tvé přemyšlovati bude o strachu, řka: Kdež jest písař, kde výběrčí, kde spisovatel velikých domů?'),
(1564559,54,23,33,19,'Lidu ukrutného neuhledáš, lidu hluboké řeči, jíž bys neslýchal, a jazyku cizího, jemuž bys nerozuměl.'),
(1564560,54,23,33,20,'Patř na Sion, město slavností našich, oči tvé nechať hledí na Jeruzalém, obydlí pokojné, stánek, kterýž nebude přenešen, kolíkové jeho na věky se nepohnou, a žádný provaz jeho se neztrhá;'),
(1564561,54,23,33,21,'Proto že velikomocný Hospodin jest nám na místě tom řekami toků širokých, po němž nepůjde lodí s vesly, aniž bárka veliká po něm přecházeti bude.'),
(1564562,54,23,33,22,'Nebo Hospodin jest soudce náš, Hospodin ustanovitel práv našich, Hospodin král náš, onť spasí nás.'),
(1564563,54,23,33,23,'Oslábliť jsou provazové tvoji, aniž budou moci utvrditi sloupu bárky své, ani roztáhnouti plachty, anť již rozdělena bude kořist loupeže mnohé; i chromí rozchvátají kořist.'),
(1564564,54,23,33,24,'Aniž dí kdo z obyvatelů: Nemocen jsem. Lid osedlý v něm zproštěn bude nepravosti.'),
(1564565,54,23,34,1,'Přistuptež národové, abyste slyšeli, a lidé pozorujte. Nechať slyší země i plnost její, okršlek zemský i všeliký plod jeho.'),
(1564566,54,23,34,2,'Proto že hněv Hospodinův jest proti všechněm národům, a prchlivost proti všemu vojsku jejich: vyhubí je jako proklaté, a vydá je k zabití.'),
(1564567,54,23,34,3,'I budou povrženi zbití jejich, a z těl mrtvých jejich vzejde smrad, a rozplynou se hory od krve jejich.'),
(1564568,54,23,34,4,'Chřadnouti bude i všecko vojsko nebeské, a svinuta budou nebesa jako kniha, a všecko vojsko jejich sprchne, jako prší list s vinného kmene, a jako nezralé ovoce s fíku.'),
(1564569,54,23,34,5,'Nebo opojen jest na nebi meč můj; na Idumejské sstoupí, a na lid, na nějž jsem klatbu vydal, aby trestán byl.'),
(1564570,54,23,34,6,'Meč Hospodinův bude plný krve, umastí se tukem a krví beranů a kozlů, tukem ledvin skopových; obět zajisté bude míti Hospodin v Bozra, a zabijení veliké v zemi Idumejské.'),
(1564571,54,23,34,7,'Sstoupí s nimi i jednorožcové a volčata s voly, i opije se země jejich krví, a prach jejich tukem se omastí.'),
(1564572,54,23,34,8,'Nebo den pomsty Hospodinovy, léto odplacování se, aby mštěno bylo Siona.'),
(1564573,54,23,34,9,'A obráceni budou potokové její v smolu, a prach její v siru, a země její obrátí se v smolu hořící.'),
(1564574,54,23,34,10,'V noci ani ve dne neuhasne, na věky vystupovati bude dým její, od národu až do pronárodu pustá zůstane, na věky věků nebude, kdo by šel přes ni.'),
(1564575,54,23,34,11,'Ale osednou ji pelikán a výr, kalous také a krkavec budou bydliti v ní, a roztáhne po ní šňůru zahanbení a závaží marnosti.'),
(1564576,54,23,34,12,'Šlechticů jejích volati budou k království, ale nebude tam žádného, nebo všecka knížata její zhynou.'),
(1564577,54,23,34,13,'A vzroste na palácích jejích trní, kopřivy a bodláčí na hradích jejích, a bude příbytkem draků a obydlím sov.'),
(1564578,54,23,34,14,'Tam se budou potkávati spolu zvěř s ptactvem, a příšera jedna druhé se ozývati; tam toliko noční přeluda se usadí, a odpočinutí sobě nalezne.'),
(1564579,54,23,34,15,'Tam se zhnízdí sup, a škřečeti bude, a když vysedí, shromáždí je pod stín svůj; tam také shledají se luňáci jeden s druhým.'),
(1564580,54,23,34,16,'Hledejte v knize Hospodinově, a čtěte. Ani jedno z těch nechybí, a jeden každý bez své druže nebude; nebo to ústa Páně přikázala, a duch jeho shromáždí je.'),
(1564581,54,23,34,17,'Onť zajisté vrže jim losy, a ruka jeho jim rozdělí ji provazcem; až na věky dědičně ji osednou, od národu až do pronárodu v ní přebývati budou.'),
(1564582,54,23,35,1,'Veseliti se budou z toho poušť a pustina, plésati, pravím, bude poušť, a zkvetne jako růže.'),
(1564583,54,23,35,2,'Ušlechtile zkvetne, ano i radostně plésati bude s prozpěvováním. Sláva Libánská dána jí bude, okrasa Karmelská a Sáronská. Tyť věci uzří slávu Hospodinovu, důstojnost Boha našeho.'),
(1564584,54,23,35,3,'Posilňtež rukou opuštěných, a kolena klesající utvrďte.'),
(1564585,54,23,35,4,'Rcete těm, kteříž jsou bázlivého srdce: Posilňte se, nebojte se. Aj, Bůh váš s pomstou přijde, s odplatou Bůh sám přijde, a spasí vás.'),
(1564586,54,23,35,5,'Tehdáž otevrou se oči slepých, otevrou se též i uši hluchých.'),
(1564587,54,23,35,6,'Tehdáž poskočí kulhavý jako jelen, a jazyk němého prozpěvovati bude; nebo se vyprýští vody na poušti, a potokové na pustinách.'),
(1564588,54,23,35,7,'A obrátí se místo vyprahlé v jezero, a žíznivé v prameny vod; v doupatech draků, v pelešech jejich tráva, třtí a sítí.'),
(1564589,54,23,35,8,'Bude také tam silnice a cesta, kteráž cestou svatou slouti bude. Nepůjde po ní nečistý, ale bude samých těchto; tou cestou jdoucí i nejhloupější nezbloudí.'),
(1564590,54,23,35,9,'Nebude tam lva, a lítá zvěř nebude choditi po ní, aniž tam nalezena bude, ale půjdou po ní ti, jenž budou vysvobozeni.'),
(1564591,54,23,35,10,'Vykoupení, pravím, Hospodinovi navrátí se, a přijdou na Sion s prozpěvováním, a veselé věčné bude na hlavě jejich; radosti a veselé dojdou, zámutek pak a úpění uteče od nich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564592,54,23,36,1,'Stalo se pak čtrnáctého léta kralování Ezechiášova, přitáhl Senacherib král Assyrský proti všechněm městům Judským hrazeným, a zdobýval jich.'),
(1564593,54,23,36,2,'I poslal král Assyrský Rabsaka z Lachis do Jeruzaléma k králi Ezechiášovi s vojskem velikým. Kterýž se postavil u struhy rybníka hořejšího, při silnici pole valchářova.'),
(1564594,54,23,36,3,'Tedy vyšel k němu Eliakim syn Helkiášův, kterýž byl správce domu, a Sobna písař, a Joach syn Azafův, kancléř.'),
(1564595,54,23,36,4,'I mluvil k nim Rabsaces: Povězte medle Ezechiášovi: Toto praví král veliký, král Assyrský: Jakéž jest to doufání, na kterémž se zakládáš?'),
(1564596,54,23,36,5,'Řekl jsem: Jistě žeť jest věc daremní; radyť jest a síly k válce potřebí. A protož v koho doufáš, že mi se protivíš?'),
(1564597,54,23,36,6,'Aj, spolehl jsi na hůl třtiny té nalomené, na Egypt, na niž zpodepřel-li by se kdo, pronikne ruku jeho, a probodne ji. Takovýť jest Farao král Egyptský všechněm, kteříž v něm doufají.'),
(1564598,54,23,36,7,'Pakli mi díš: V Hospodinu Bohu svém doufáme: zdaliž on není ten, jehož pobořil Ezechiáš výsosti i oltáře, a přikázal Judovi a Jeruzalému, řka: Před tímto oltářem klaněti se budete?'),
(1564599,54,23,36,8,'Ale nu, potkej se medle se pánem mým králem Assyrským. Přidámť ještě dva tisíce koní, můžeš-li jen míti, kdo by na nich jeli.'),
(1564600,54,23,36,9,'Jakž tedy odoláš jednomu knížeti z nejmenších služebníků pána mého, ačkoli máš doufání v Egyptu pro vozy a jezdce?'),
(1564601,54,23,36,10,'Přesto, zdali jsem bez Hospodina přitáhl do země této, abych ji zkazil? Hospodin řekl mi: Táhni na tu zemi, a zkaz ji.'),
(1564602,54,23,36,11,'I řekl Eliakim a Sobna a Joach Rabsakovi: Mluv medle k služebníkům svým Syrsky, však rozumíme, a nemluv k nám Židovsky před lidem tímto, kterýž jest na zdech.'),
(1564603,54,23,36,12,'I odpověděl Rabsaces: Zdaliž ku pánu tvému a k tobě poslal mne pán můj, abych mluvil slova tato? Však k mužům těm, kteříž jsou na zdech, aby lejna svá jedli, a moč svůj spolu s vámi pili.'),
(1564604,54,23,36,13,'A tak stoje Rabsaces, volal hlasem velikým Židovsky, a řekl: Slyšte slova krále velikého, krále Assyrského:'),
(1564605,54,23,36,14,'Toto praví král: Nechť vás nesvodí Ezechiáš, neboť nebude moci vyprostiti vás.'),
(1564606,54,23,36,15,'A nechť vám nevelí Ezechiáš doufati v Hospodina, řka: Zajisté vysvobodí nás Hospodin, a nebudeť dáno město toto v ruku krále Assyrského.'),
(1564607,54,23,36,16,'Neposlouchejte Ezechiáše. Nebo takto praví král Assyrský: Učiňte mi to k líbosti, a vyjděte ke mně, i bude moci jísti jeden každý z vinice své, a jeden každý z fíku svého, a píti jeden každý vodu z čisterny své,'),
(1564608,54,23,36,17,'Dokudž nepřijdu, a nepoberu vás do země podobné zemi vaší, do země úrodné, země chleba a vinic.'),
(1564609,54,23,36,18,'Nechť vás nesvodí Ezechiáš, řka: Hospodin vysvobodí nás. Zdaliž mohli vysvoboditi bohové národů jeden každý zemi svou z ruky krále Assyrského?'),
(1564610,54,23,36,19,'Kde jsou bohové Emat a Arfad? Kde jsou bohové Sefarvaim? Zdaliž jsou vysvobodili i Samaří z ruky mé?'),
(1564611,54,23,36,20,'Kteří jsou mezi všemi bohy těch zemí, ješto by vysvobodili zemi svou z ruky mé? Aby pak Hospodin měl vysvoboditi Jeruzalém z ruky mé?'),
(1564612,54,23,36,21,'Oni pak mlčeli, a neodpověděli jemu slova. Nebo takové bylo rozkázaní královo, řkoucí: Neodpovídejte jemu.'),
(1564613,54,23,36,22,'I přišel Eliakim syn Helkiášův, kterýž byl správcím domu, a Sobna písař, a Joach syn Azafův, kancléř, k Ezechiášovi, majíce roucha roztržená, a oznámili jemu slova Rabsakova.'),
(1564614,54,23,37,1,'I stalo se, když to uslyšel král Ezechiáš, že roztrhl roucho své, a oděl se žíní, a všel do domu Hospodinova.'),
(1564615,54,23,37,2,'I poslal Eliakima správce domu, a Sobnu písaře, a starší z kněží, oblečené v žíně k Izaiášovi proroku, synu Amosovu.'),
(1564616,54,23,37,3,'Kteříž řekli jemu: Toto praví Ezechiáš: Den úzkosti a útržky i rouhání jest den tento, proto že se přiblížil plod k vyjití, ale není síly ku porodu.'),
(1564617,54,23,37,4,'Ó by slyšel Hospodin Bůh tvůj slova Rabsakova, jehož poslal král Assyrský pán jeho, aby utrhal Bohu živému, a pomstil Hospodin Bůh tvůj těch slov, kteráž slyšel. Protož pozdvihni modlitby za tento ostatek lidu, kterýž se nalézá.'),
(1564618,54,23,37,5,'I přišli služebníci krále Ezechiáše k Izaiášovi.'),
(1564619,54,23,37,6,'Jimž odpověděl Izaiáš: Toto povíte pánu svému: Takto praví Hospodin: Nestrachuj se slov těch, kteráž jsi slyšel, jimiž se mně rouhali služebníci krále Assyrského.'),
(1564620,54,23,37,7,'Aj, já pustím naň vítr, aby uslyše pověst, navrátil se do země své, a učiním to, že padne od meče v zemi své.'),
(1564621,54,23,37,8,'Navrátiv se pak Rabsaces, nalezl krále Assyrského, an dobývá Lebna. Nebo uslyšel, (pročež odtrhl od Lachis),'),
(1564622,54,23,37,9,'Uslyšel, pravím, o Tirhákovi králi Mouřenínském, ano pravili: Táhne, aby bojoval s tebou. A však uslyšev to, vždy poslal posly své k Ezechiášovi s těmito slovy:'),
(1564623,54,23,37,10,'Takto povíte Ezechiášovi králi Judskému, řkouce: Nechť tebe nesvodí Bůh tvůj, v němž ty doufáš, říkaje: Nebude dán Jeruzalém v ruku krále Assyrského.'),
(1564624,54,23,37,11,'Aj, slyšels, co jsou učinili králové Assyrští všechněm zemím, pohubivše je, a ty bys měl býti vysvobozen?'),
(1564625,54,23,37,12,'Zdaliž jsou je vysvobodili bohové těch národů, kteréž zahladili předkové moji, Gozana, Charana, Resefa a syny z Eden, kteříž byli v Telasar?'),
(1564626,54,23,37,13,'Kde jest král Emat, a král Arfad, a král města Sefarvaim, Ana i Ava?'),
(1564627,54,23,37,14,'Protož vzav Ezechiáš list z ruky poslů, přečtl jej a vstoupiv do domu Hospodinova, rozvinul jej Ezechiáš před Hospodinem.'),
(1564628,54,23,37,15,'A modlil se Ezechiáš Hospodinu, řka:'),
(1564629,54,23,37,16,'Hospodine zástupů, Bože Izraelský, kterýž sedíš nad cherubíny, ty jsi sám Bůh všech království země, ty jsi učinil nebe i zemi.'),
(1564630,54,23,37,17,'Nakloniž, Hospodine, ucha svého a uslyš; otevři, Hospodine, oči své a pohleď; slyš, pravím, všecka slova Senacheribova, kterýž poslal k činění útržek Bohu živému.'),
(1564631,54,23,37,18,'Takť jest, Hospodine, žeť jsou pohubili králové Assyrští všecky ty krajiny i zemi jejich,'),
(1564632,54,23,37,19,'A uvrhli bohy jejich do ohně; nebo nebyli bohové, ale dílo ruku lidských, dřevo a kámen, protož zahladili je.'),
(1564633,54,23,37,20,'A nyní, Hospodine Bože náš, vysvoboď nás z ruky jeho, aťby poznala všecka království země, že jsi ty Hospodin sám.'),
(1564634,54,23,37,21,'Tedy poslal Izaiáš syn Amosův k Ezechiášovi, řka: Toto praví Hospodin Bůh Izraelský: Zač jsi mi se modlil strany Senacheriba krále Assyrského,'),
(1564635,54,23,37,22,'Totoť jest slovo, kteréž mluvil Hospodin o něm: Pohrdá tebou, a posmívá se tobě panna, dcera Sionská, potřásá hlavou za tebou dcera Jeruzalémská.'),
(1564636,54,23,37,23,'Kohož jsi zhaněl? A komus se rouhal? A proti komus povýšil hlasu, a pozdvihl zhůru očí svých? Proti Svatému Izraelskému.'),
(1564637,54,23,37,24,'Skrze služebníky své utrhal jsi Pánu, a řekl jsi: Ve množství vozů svých já jsem vytáhl na hory vysoké, na stráně Libánské, a zpodtínám vysoké cedry jeho, i spanilé jedle jeho, a vejdu na nejvyšší kraj jeho do lesů a výborných rolí jeho.'),
(1564638,54,23,37,25,'Já jsem vykopal a pil vody; nebo jsem vysušil nohama svýma všecky potoky míst obležených.'),
(1564639,54,23,37,26,'Zdalis neslyšel, že jsem již to dávno učinil, a ode dnů starých to sformoval? Nyní pak k tomu přivozuji, aby v poušť a v hromady rumu města hrazená obrácena byla,'),
(1564640,54,23,37,27,'A jejich obyvatelé ruce oslablé majíc, předěšeni a zahanbeni jsouc, byli jako bylina polní, a zelina vzcházející, jako tráva na střechách, a osení rzí zkažené, prvé než by dorostlo.'),
(1564641,54,23,37,28,'Sedání pak tvé, a vycházení tvé i vcházení tvé znám, i vzteklost tvou proti sobě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564642,54,23,37,29,'Poněvadž ty se vztěkáš proti mně, a tvé zpouzení přišlo v uši mé, protož vpustím udici svou v chřípě tvé, a udidla svá v ústa tvá, a odvedu tě zase tou cestou, kterouž jsi přišel.'),
(1564643,54,23,37,30,'A toto měj za znamení: Budete jísti roku prvního, co samo od sebe zroste, též druhého roku, což se samo od sebe zrodí, třetího pak roku budete síti a žíti a štěpovati vinice, a jísti ovoce jejich.'),
(1564644,54,23,37,31,'Ostatek zajisté domu Judova, kterýž pozůstal, vpustí zase kořeny své hluboce, a vydá užitek zhůru.'),
(1564645,54,23,37,32,'Nebo z Jeruzaléma vyjdou ostatkové, a zachovaní z hory Siona. Horlivost Hospodina zástupů učiní to.'),
(1564646,54,23,37,33,'A protož toto praví Hospodin o králi Assyrském: Nevejdeť do města tohoto, aniž sem střely vstřelí, aniž na ně dotrou pavézníci, aniž udělají u něho náspu.'),
(1564647,54,23,37,34,'Cestou, kterouž přitáhl, zase navrátí se, a do města tohoto nevejde, praví Hospodin.'),
(1564648,54,23,37,35,'Nebo chrániti budu města tohoto, abych je zachoval pro sebe a pro Davida služebníka svého.'),
(1564649,54,23,37,36,'Tedy vyšel anděl Hospodinův, a zbil v vojště Assyrském sto osmdesáte a pět tisíců. I vstali velmi ráno, a aj, všickni mrtví.'),
(1564650,54,23,37,37,'A tak odjel, anobrž utekl, a navrátil se Senacherib král Assyrský, a bydlil v Ninive.'),
(1564651,54,23,37,38,'I stalo se, když se klaněl v chrámě Nizrocha boha svého, že Adramelech a Sarasar, synové jeho, zabili jej mečem, a utekli do země Ararat. I kraloval Esarchaddon syn jeho místo něho.'),
(1564652,54,23,38,1,'V těch dnech roznemohl se Ezechiáš až k smrti. I přišel k němu Izaiáš syn Amosův, prorok, a řekl jemu: Toto praví Hospodin: Zřeď dům svůj, nebo umřeš, a nebudeš živ.'),
(1564653,54,23,38,2,'I obrátil Ezechiáš tvář svou k stěně, a modlil se Hospodinu.'),
(1564654,54,23,38,3,'A řekl: Prosím, ó Hospodine, rozpomeň se nyní, že jsem stále chodil před tebou v pravdě a v srdci upřímém, a že jsem to činil, což dobrého jest před očima tvýma. I plakal Ezechiáš pláčem velikým.'),
(1564655,54,23,38,4,'Tedy stalo se slovo Hospodinovo k Izaiášovi, řkoucí:'),
(1564656,54,23,38,5,'Jdi a rci Ezechiášovi: Toto praví Hospodin Bůh Davida otce tvého: Slyšelť jsem modlitbu tvou, viděl jsem slzy tvé; aj, já přidám ke dnům tvým patnácte let.'),
(1564657,54,23,38,6,'A z ruky krále Assyrského vysvobodím tě i město toto, a chrániti budu města tohoto.'),
(1564658,54,23,38,7,'A toto budeš míti znamení od Hospodina, že Hospodin učiní věc tuto, kterouž mluvil:'),
(1564659,54,23,38,8,'Aj, já navrátím zpátkem stín po stupních, po nichž sešel na hodinách slunečných Achasových, o deset stupňů. I navrátilo se slunce o deset stupňů, po týchž stupních, po nichž bylo sešlo.'),
(1564660,54,23,38,9,'Zapsání Ezechiáše krále Judského, když nemocen byl, a ozdravěl po nemoci své:'),
(1564661,54,23,38,10,'Jáť jsem byl řekl v přestřižení dnů svých, že vejdu do bran hrobu, zbaven budu ostatku let svých.'),
(1564662,54,23,38,11,'Řekl jsem byl, že neuzřím Hospodina, Hospodina v zemi živých, nebudu vídati člověka více mezi přebývajícími na světě.'),
(1564663,54,23,38,12,'Přebývání mé pomíjí, a stěhuje se ode mne jako stánek pastýřský; přestřihl jsem jako tkadlec život svůj, od třísní odřeže mne. Dnes dříve než noc přijde, učiníš mi konec.'),
(1564664,54,23,38,13,'Předkládal jsem sobě v jitře, že jako lev tak potře všecky kosti mé, dnes dříve než noc přijde, že mi učiníš konec.'),
(1564665,54,23,38,14,'Jako řeřáb a vlaštovice pištěl jsem, lkal jsem jako holubice, oči mé zhůru pozdvižené byly. Pane, násilé trpím, ó prodliž mi života.'),
(1564666,54,23,38,15,'Ale coť mám více mluviti? I předpověděl mi, i učinil, že živ pobudu mimo všecka léta svá po hořkosti duše své.'),
(1564667,54,23,38,16,'Pane, kdo po nich i v nich živi budou, všechněm znám bude život dýchání mého, žes mi zdraví navrátil, a mne při životu zachoval.'),
(1564668,54,23,38,17,'Aj, v čas pokoje potkala mne byla hořkost nejhořčejší, ale tobě zalíbilo se vytrhnouti duši mou z propasti zkažení, proto že jsi zavrhl za hřbet svůj všecky hříchy mé.'),
(1564669,54,23,38,18,'Nebo ne hrob oslavuje tebe, ani smrt tě chválí, aniž očekávají ti, jenž do jámy sstupují, pravdy tvé.'),
(1564670,54,23,38,19,'Ale živý, živý, tenť oslavovati bude tebe, jako já dnes, a otec synům v známost uvodí pravdu tvou.'),
(1564671,54,23,38,20,'Hospodin vysvobodil mne, a protož písně mé zpívati budeme po všecky dny života našeho v domě Hospodinově.'),
(1564672,54,23,38,21,'Řekl pak byl Izaiáš: Nechať vezmou hrudu suchých fíků, a přiloží na vřed, a zdráv bude.'),
(1564673,54,23,38,22,'I řekl byl Ezechiáš: Jaké jest znamení, že vstoupím do domu Hospodinova?'),
(1564674,54,23,39,1,'Toho času poslal Merodach Baladan syn Baladanův, král Babylonský, list a dary Ezechiášovi, když uslyšel, že nemocen byv, zase ozdravěl.'),
(1564675,54,23,39,2,'I zradoval se z toho Ezechiáš, a ukázal jim dům klénotů svých, stříbra a zlata a vonných věcí, a olej nejvýbornější, tolikéž dům zbroje své, a cožkoli mohlo nalezeno býti v pokladích jeho. Ničeho nebylo, čehož by jim neukázal Ezechiáš v domě svém i ve všem panství svém.'),
(1564676,54,23,39,3,'V tom přišel prorok Izaiáš k králi Ezechiášovi, a řekl jemu: Co pravili ti muži? A odkud přišli k tobě? I odpověděl Ezechiáš: Z země daleké přišli ke mně, z Babylona.'),
(1564677,54,23,39,4,'Řekl ještě: Co jsou viděli v domě tvém? Odpověděl Ezechiáš: Všecko, což jest v domě mém, viděli. Ničeho není v pokladích mých, čehož bych jim neukázal.'),
(1564678,54,23,39,5,'Tedy řekl Izaiáš Ezechiášovi: Slyšiž slovo Hospodina zástupů:'),
(1564679,54,23,39,6,'Aj, dnové přijdou, že odneseno bude do Babylona, cožkoli jest v domě tvém, a cožkoli nachovali otcové tvoji, až do tohoto dne; nezůstaneť ničeho, (praví Hospodin).'),
(1564680,54,23,39,7,'I syny tvé také, kteříž pojdou z tebe,kteréž zplodíš, poberou, a budou komorníci při dvoře krále Babylonského.'),
(1564681,54,23,39,8,'Tedy řekl Ezechiáš Izaiášovi: Dobréť jest slovo Hospodinovo, kteréž jsi mluvil. (A doložil): Proto že pokoj a pravda bude za dnů mých.'),
(1564682,54,23,40,1,'Potěšujte, potěšujte lidu mého, dí Bůh váš.'),
(1564683,54,23,40,2,'Mluvte k srdci Jeruzaléma, a ohlašujte jemu, že se již doplnil čas uložený jeho, že jest odpuštěna nepravost jeho, a že vzal z ruky Hospodinovy dvojnásobně za všecky hříchy své.'),
(1564684,54,23,40,3,'Hlas volajícího: Připravtež na poušti cestu Hospodinovu, přímou učiňte na pustině stezku Boha našeho.'),
(1564685,54,23,40,4,'Každé údolí ať jest vyvýšeno, a všeliká hora i pahrbek ať jest snížen; což jest křivého, ať jest přímé, a místa nerovná ať jsou rovinou.'),
(1564686,54,23,40,5,'Nebo se zjeví sláva Hospodinova, a uzří všeliké tělo spolu, že ústa Hospodinova mluvila.'),
(1564687,54,23,40,6,'Hlas řkoucího: Volej. I řekl: Co mám volati? To, že všeliké tělo jest tráva, a všeliká vzácnost jeho jako květ polní.'),
(1564688,54,23,40,7,'Usychá tráva, květ prší, jakž vítr Hospodinův povane na něj. V pravděť jsou lidé ta tráva.'),
(1564689,54,23,40,8,'Usychá tráva, květ prší, ale slovo Boha našeho zůstává na věky.'),
(1564690,54,23,40,9,'Na horu vysokou vystup sobě, Sione, zvěstovateli věcí potěšených, povyš mocně hlasu svého, Jeruzaléme, zvěstovateli věcí potěšených, povyš, aniž se boj. Rci městům Judským: Aj, Bůh váš.'),
(1564691,54,23,40,10,'Aj, Panovník Hospodin proti silnému přijde, a rámě jeho panovati bude nad ním;aj, mzda jeho s ním, a dílo jeho před ním.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564692,54,23,40,11,'Jako pastýř stádo své pásti bude, do náručí svého shromáždí jehňátka, a v klíně svém je ponese, březí pak poznenáhlu povede.'),
(1564693,54,23,40,12,'Kdo změřil hrstí svou vody, a nebesa pídí rozměřil? A kdo změřil měrou prach země, a zvážil na váze hory, a pahrbky na závaží?'),
(1564694,54,23,40,13,'Kdo vystihl ducha Hospodinova, a rádcím jeho byl, že by mu oznámil?'),
(1564695,54,23,40,14,'S kým se radil, že by mu přidal srozumění, a naučil jej stezce soudu, a vyučil jej umění, a cestu všelijaké rozumnosti jemu v známost uvedl?'),
(1564696,54,23,40,15,'Aj, národové jako krůpě od okova, a jako prášek na vážkách se počítají, ostrovy jako nejmenší věc zachvacuje.'),
(1564697,54,23,40,16,'Ani Libán nepostačil by k zanícení ohně, a živočichové jeho nepostačili by k zápalné oběti.'),
(1564698,54,23,40,17,'Všickni národové jsou jako nic před ním, za nic a za marnost pokládají se u něho.'),
(1564699,54,23,40,18,'K komu tedy připodobníte Boha silného? A jaké podobenství přirovnáte jemu?'),
(1564700,54,23,40,19,'Jakžkoli rytinu líčí řemeslník, a zlatník zlatem ji potahuje, a řetízky stříbrné k ní slévá;'),
(1564701,54,23,40,20,'A ten, kterýž pro chudobu nemá co obětovati, dřevo, kteréž by nepráchnivělo, vybírá, a řemeslníka umělého sobě hledá k přistrojení rytiny, aby se nepohnula.'),
(1564702,54,23,40,21,'Zdaliž nevíte? Zdaliž neslýcháte? Zdaliž se vám nezvěstuje od počátku? Zdaliž nesrozumíváte z základů země?'),
(1564703,54,23,40,22,'Ten, kterýž sedí nad okršlkem země, jejížto obyvatelé jako kobylky, kterýž rozprostřel jako kortýnu nebesa, a roztáhl je jako stánek k přebývání,'),
(1564704,54,23,40,23,'Onť přivodí knížata na nic, soudce zemské jako nic rozptyluje,'),
(1564705,54,23,40,24,'Tak že nebývají štípeni ani sáti, aniž kořene pouští do země pařez jejich. Nebo jakž jen zavane na ně, hned usychají, a vicher jako plevu zanáší je.'),
(1564706,54,23,40,25,'K komu tedy připodobníte mne, abych podobný byl jemu, praví Svatý?'),
(1564707,54,23,40,26,'Pozdvihněte zhůru očí svých, a vizte, kdo to stvořil? Kdo vyvodí v počtu vojsko jejich, a všeho toho zejména povolává? Vedlé množství síly a veliké moci ani jedno z nich nehyne.'),
(1564708,54,23,40,27,'Pročež tedy říkáš, Jákobe, a mluvíš, Izraeli: Skrytať jest cesta má před Hospodinem, a pře má před Boha mého nepřichází?'),
(1564709,54,23,40,28,'Zdaliž nevíš, zdaž jsi neslýchal, že Bůh věčný Hospodin, kterýž stvořil končiny země, neustává ani zemdlívá, a že vystižena býti nemůže moudrost jeho?'),
(1564710,54,23,40,29,'On dává ustalému sílu, a tomu, ješto žádné síly nemá, moci hojně udílí.'),
(1564711,54,23,40,30,'Ustává a umdlévá mládež, a mládenci těžce klesají,'),
(1564712,54,23,40,31,'Ale ti, jenž očekávají na Hospodina, nabývají nové síly. Vznášejí se peřím jako orlice; běží, a však neumdlévají, chodí, a neustávají.'),
(1564713,54,23,41,1,'Umlknětež přede mnou ostrovové, a národové nechať se ssilí, nechať přistoupí, a tu ať mluví. Přistupmež spolu k soudu.'),
(1564714,54,23,41,2,'Kdo vzbudil od východu spravedlivého, aby ho následoval? Kdo jemu podmanil národy, a způsobil, aby nad králi panoval, vydav je jako prach meči jeho, a jako plevy rozptýlené lučišti jeho?'),
(1564715,54,23,41,3,'Sháněje se s nimi, prošel pokojně cestou, po níž nohama svýma nechodíval.'),
(1564716,54,23,41,4,'Kdo to spravil a učinil, povolávaje rodin od počátku? Já Hospodin, první i poslední, já sám.'),
(1564717,54,23,41,5,'Viděli ostrovové, a ulekli se, končiny země předěsily se, shromáždili se a sešli.'),
(1564718,54,23,41,6,'Jeden druhému pomáhal, a bratru svému říkal: Posilň se.'),
(1564719,54,23,41,7,'A tak posilňoval tesař zlatníka, vyhlazujícího kladivo tlučením na nákovadlí, říkaje: K sletování toto dobré jest. I utvrdil to hřebíky, aby se nepohnulo.'),
(1564720,54,23,41,8,'Ale ty, Izraeli služebníče můj, ty Jákobe, kteréhož jsem vyvolil, símě Abrahama, přítele mého,'),
(1564721,54,23,41,9,'Ty, kteréhož jsem vychvátil od končin země, nýbrž pominuv přednějších jejich, povolal jsem tě, řka tobě: Služebník můj jsi, vyvolil jsem tě, aniž jsem zavrhl tebe.'),
(1564722,54,23,41,10,'Nebojž se, nebo jsem já s tebou; nestrachujž se, nebo já jsem Bůh tvůj. Posilním tě, a pomáhati budu tobě, a podpírati tě budu pravicí spravedlnosti své.'),
(1564723,54,23,41,11,'Aj, zastydí se, a zahanbeni budou všickni, kteříž se zlobí proti tobě; v nic obráceni budou, a zahynou ti, kteříž tobě odporují.'),
(1564724,54,23,41,12,'Hledal-li bys jich, nenalezneš jich. Ti, kteříž se s tebou nesnadní, v nic obráceni budou, a na nic přijdou ti, jenž s tebou válčí.'),
(1564725,54,23,41,13,'Nebo já, Hospodin Bůh tvůj, ujal jsem tě za tvou pravici, a pravímť: Neboj se, já tobě pomáhati budu.'),
(1564726,54,23,41,14,'Neboj se, červíčku Jákobův, hrstko Izraelova, já spomáhati budu tobě, praví Hospodin, a vykupitel tvůj, Svatý Izraelský.'),
(1564727,54,23,41,15,'Aj, učinil jsem tě jako smyk i s zuby novými po obou stranách; pomlátíš hory, a zetřeš je, a s pahrbky jako s plevami naložíš.'),
(1564728,54,23,41,16,'Převěješ je, v tom je vítr zachvátí, a vicher rozptýlí, ty pak plésati budeš v Hospodinu, v Svatém Izraelském chlubiti se budeš.'),
(1564729,54,23,41,17,'Chudé a nuzné, kteříž hledají vody, an jí není, jejichž jazyk žízní prahne, já Hospodin vyslyším, já Bůh Izraelský neopustím jich.'),
(1564730,54,23,41,18,'Vyvedu na vysokých místech řeky, a u prostřed rovin studnice; obrátím poušť v jezero vod, a zemi vyprahlou v prameny vod.'),
(1564731,54,23,41,19,'Nasadím na poušti cedrů, výborných cedrů, myrtoví, a olivoví; vysadím poušť jedlovím, jilmem, též i pušpanem,'),
(1564732,54,23,41,20,'Aby viděli, a poznali, a rozvažujíce, srozuměli, že to ruka Hospodinova učinila, a Svatý Izraelský že to stvořil.'),
(1564733,54,23,41,21,'Veďte při svou, praví Hospodin, ukažte mocné důvody své, dí král Jákobův.'),
(1564734,54,23,41,22,'Nechať přistoupí, a nechť nám oznámí to, což se státi má. Věci prvé stalé oznamte, abychom povážili v srdci svém, a poznali cíl jejich, aneb aspoň co jest budoucího, povězte nám.'),
(1564735,54,23,41,23,'Oznamte, co se budoucně státi má, a poznáme, že bohové jste. Pakli, učiňte něco dobrého neb zlého, abychom se děsili, když bychom to viděli spolu.'),
(1564736,54,23,41,24,'Aj, vy naprosto nic nejste, a dílo vaše tolikéž nic není; protož ohavnýť jest, kdo vás zvoluje.'),
(1564737,54,23,41,25,'Vzbudím od půlnoci, ten přitáhne, od východu slunce, ten svolá ve jménu mém, a oboří se na knížata jako na bláto, a pošlapá je jako hrnčíř hlinu.'),
(1564738,54,23,41,26,'Kdo oznámí od počátku, abychom věděli, aneb od starodávna, abychom řekli: Práv jest? Naprosto žádného není, kdo by oznámil, aniž jest kdo, ješto by se dal slyšeti, aneb ješto by slyšel řeči vaše.'),
(1564739,54,23,41,27,'Já jsem první, kterýž Sionu předpovídám: Aj, aj, teď jsou; a Jeruzalému: Zvěstovatele potěšených věcí dám.'),
(1564740,54,23,41,28,'Nebo vidím, že není žádného,není žádného mezi nimi rozumného; ač se jich otazuji, však neodpovídají slova.'),
(1564741,54,23,41,29,'Aj, všickni ti jsou marnost, za nic nestojí dílo jejich, vítr a daremní věc jsou slitiny jejich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564742,54,23,42,1,'Aj, služebník můj, na kteréhož se zpodepru, vyvolený můj, jehož libuje duše má. Ducha svého dám jemu, onť soud národům vynášeti bude.'),
(1564743,54,23,42,2,'Nebude křičeti, ani se vyvyšovati, ani slyšán bude vně hlas jeho.'),
(1564744,54,23,42,3,'Třtiny nalomené nedolomí, a lnu kouřícího se neuhasí, ale soud podlé pravdy vynášeti bude.'),
(1564745,54,23,42,4,'Nebude neochotný, ani přísný, dokudž soudu na zemi nevykoná, a učení jeho ostrovové očekávati budou.'),
(1564746,54,23,42,5,'Tak praví Bůh silný Hospodin, kterýž stvořil nebesa, a roztáhl je, kterýž rozšířil zemi, i to, což z ní pochází, kterýž dává dýchání lidu na ní, a ducha těm, jenž chodí po ní.'),
(1564747,54,23,42,6,'Já Hospodin povolal jsem tě v spravedlnosti, a ujal jsem tě za ruku tvou; protož ostříhati tě budu, a dám tě v smlouvu lidu, a za světlo národům,'),
(1564748,54,23,42,7,'Abys otvíral oči slepé, a vyvodil z žaláře vězně, a z vězení ty, kteříž sedí ve tmách.'),
(1564749,54,23,42,8,'Já jsem Hospodin, toť jest jméno mé, a slávy své jinému nedám, ani chvály své rytinám.'),
(1564750,54,23,42,9,'Aj, prvnější věci přišly, a i nové předpovídaje, dříve než se začnou, dám o nich slyšeti vám.'),
(1564751,54,23,42,10,'Zpívejte Hospodinu píseň novou, chvála jeho jest od končin země, kteříž se plavíte po moři, i všecko, což v něm jest, ostrovové i obyvatelé jejich.'),
(1564752,54,23,42,11,'Pozdvihněte hlasu pustiny i města její, i vsi, v nichž bydlí Cedar, prokřikujte obyvatelé skal, s vrchu hor volejte.'),
(1564753,54,23,42,12,'Vzdejte slávu Hospodinu, a chválu jeho na ostrovích zvěstujte.'),
(1564754,54,23,42,13,'Hospodin jako silný rek vyjde, jako muž válečný rozhorlí se, troubiti, anobrž i prokřikovati bude, a proti nepřátelům svým zmužile sobě počínati, řka:'),
(1564755,54,23,42,14,'Mlčel jsem dosti dlouho, činil jsem se neslyše, zdržoval jsem se, ale již jako pracující ku porodu křičeti budu, pohubím a sehltím vše pojednou.'),
(1564756,54,23,42,15,'V pustinu obrátím hory i pahrbky, a všelikou bylinu jejich usuším, a obrátím řeky v ostrovy, a jezera vysuším.'),
(1564757,54,23,42,16,'I povedu slepé po cestě, kteréž neznali, a po stezkách, kterýchž neuměli, provedu je; obrátím před nimi tmu v světlo, a co nerovného, v rovinu. Toť jest, což jim učiním, a neopustím jich.'),
(1564758,54,23,42,17,'Obrátí se zpět, zahanbeni budou ti, kteříž doufají v rytinu, kteříž říkají slitinám: Vy jste bohové naši.'),
(1564759,54,23,42,18,'Ó hluší, slyštež, a vy slepí, prohlédněte, abyste viděli.'),
(1564760,54,23,42,19,'Kdo jest to slepý, jediné služebník můj? A hluchý, než posel můj, kteréhož posílám? Kdo slepý tak jako dokonalý? Slepý, pravím, jako služebník Hospodinův?'),
(1564761,54,23,42,20,'Hledě na mnohé věci, však nesrozumívá; otevřené maje uši, však neslyší.'),
(1564762,54,23,42,21,'Mělť jest Hospodin líbost v něm pro spravedlnost svou, zvelebil jej zákonem, a slavného učinil.'),
(1564763,54,23,42,22,'Že pak lid tento obloupený jest a potlačený, jehožto mládence, což jich koli, jímají a do žalářů skrývají, že jsou dáni v loupež, aniž jest, kdo by je vytrhl, v rozchvátání, aniž jest, kdo by řekl: Navrať zase,'),
(1564764,54,23,42,23,'Kdo z vás ušima pozoruje toho, srozumívá tomu, aby se bedlivěji chtěl míti napotom?'),
(1564765,54,23,42,24,'Kdo vydal v potlačení Jákoba, a Izraele loupežníkům? Zdali ne Hospodin, proti němuž jsme zhřešili? Nebo nechtěli po cestách jeho choditi, aniž poslouchali zákona jeho.'),
(1564766,54,23,42,25,'A protož vylil na něj s prchlivostí hněv svůj, a násilé boje, a zapálil jej vůkol, a však nepoznal toho. Zapálil jej, pravím, a však nepřipustil toho k srdci.'),
(1564767,54,23,43,1,'Ale nyní takto praví Hospodin stvořitel tvůj, ó Jákobe, a učinitel tvůj, ó Izraeli: Neboj se, nebo vykoupil jsem tě, a povolal jsem tě jménem tvým. Můj jsi ty.'),
(1564768,54,23,43,2,'Když půjdeš přes vody, s tebou budu, pakli přes řeky, nepřikvačí tě; půjdeš-li přes oheň, nespálíš se, aniž plamen chytí se tebe.'),
(1564769,54,23,43,3,'Nebo já Hospodin Bůh tvůj, Svatý Izraelský, jsem spasitel tvůj. Dal jsem na výplatu za tebe Egypt, zemi Mouřenínskou a Sábu místo tebe.'),
(1564770,54,23,43,4,'Hned jakž jsi drahým učiněn před očima mýma, zveleben jsi, a já jsem tě miloval; protož dal jsem lidi za tebe, a národy za život tvůj.'),
(1564771,54,23,43,5,'Nebojž se, nebo já s tebou jsem. Od východu zase přivedu símě tvé, a od západu shromáždím tě.'),
(1564772,54,23,43,6,'Dím půlnoční straně: Navrať, a polední: Nezbraňuj. Přiveď zase syny mé zdaleka, a dcery mé od končin země,'),
(1564773,54,23,43,7,'Každého toho, jenž se nazývá jménem mým, a kteréhož jsem k slávě své stvořil, jejž jsem sformoval, a kteréhož jsem učinil.'),
(1564774,54,23,43,8,'Vyveď lid slepý, kterýž již má oči, a hluché, kteříž již mají uši.'),
(1564775,54,23,43,9,'Všickni národové nechať se spolu shromáždí, a sberou se lidé. Kdo jest mezi nimi, ješto by to zvěstoval, a to, což se předně státi má, aby oznámil nám? Nechť vystaví svědky své, a spravedlivi budou, aneb ať slyší, a řeknou: Pravdať jest.'),
(1564776,54,23,43,10,'Vy svědkové moji jste, praví Hospodin, a služebník můj, kteréhož jsem vyvolil, tak že můžete věděti, a mně věřiti, i rozuměti, že já jsem, a že přede mnou nebyl sformován Bůh silný, aniž po mně bude.'),
(1564777,54,23,43,11,'Já, já jsem Hospodin, a žádného není kromě mne spasitele.'),
(1564778,54,23,43,12,'Já oznamuji, i vysvobozuji, jakž předpovídám, a ne někdo mezi vámi z cizích bohů, a vy mi toho svědkové jste, praví Hospodin, že já Bůh silný jsem.'),
(1564779,54,23,43,13,'Ještě prvé nežli den byl, já jsem, a není žádného, kdož by vytrhl z ruky mé. Když co dělám, kdo ji odvrátí?'),
(1564780,54,23,43,14,'Takto praví Hospodin vykupitel váš, Svatý Izraelský: Pro vás pošli do Babylona, a sházím závory všecky, i Kaldejské s lodimi veselými jejich.'),
(1564781,54,23,43,15,'Já jsem Hospodin svatý váš, stvořitel Izraele, král váš.'),
(1564782,54,23,43,16,'Takto praví Hospodin, kterýž způsobuje na moři cestu, a na prudkých vodách stezku,'),
(1564783,54,23,43,17,'Kterýž vyvodí vozy a koně, vojsko i sílu, činí, že v náhle padají, až i povstati nemohou, hasnou, jako knot hasne:'),
(1564784,54,23,43,18,'Nezpomínejte na první věci, a na starodávní se neohlédejte.'),
(1564785,54,23,43,19,'Aj, já učiním věc novou, a tudíž se zjeví. Zdaliž o tom nezvíte? Nadto způsobím na poušti cestu, a na pustinách řeky.'),
(1564786,54,23,43,20,'I slaviti mne bude zvěř polní, drakové i sovy, že jsem vyvedl na poušti vody a řeky na pustinách, abych dal nápoj lidu svému, vyvolenému svému.'),
(1564787,54,23,43,21,'Lid, kterýž nastrojím sobě, chválu mou vypravovati bude,'),
(1564788,54,23,43,22,'Poněvadž jsi mne nevzýval, ó Jákobe, nýbrž steskloť se se mnou, ó Izraeli.'),
(1564789,54,23,43,23,'Nepřivedl jsi mi hovádka k zápalům svým, a obětmi svými neuctils mne; nenutil jsem tě, abys mi sloužil obětmi suchými, aniž jsem tě tím obtěžoval, abys mi kadil.'),
(1564790,54,23,43,24,'Nekoupil jsi mi za peníze vonných věcí, ani tukem obětí svých zavlažil jsi mne, ale zaměstknal jsi mne hříchy svými, a obtížils mne nepravostmi svými.'),
(1564791,54,23,43,25,'Já, já sám shlazuji přestoupení tvá pro sebe, a na hříchy tvé nezpomínám.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564792,54,23,43,26,'Přiveď mi ku paměti, suďme se spolu; oznam ty, podlé čeho bys mohl spravedliv býti.'),
(1564793,54,23,43,27,'Otec tvůj první zhřešil, a učitelé tvoji přestoupili proti mně.'),
(1564794,54,23,43,28,'A protož smeci knížata z míst svatých, a vydám v prokletí Jákoba, a Izraele v pohanění.'),
(1564795,54,23,44,1,'A však nyní slyš, Jákobe, služebníče můj, a Izraeli, kteréhož jsem vyvolil.'),
(1564796,54,23,44,2,'Toto dí Hospodin, kterýž tě učinil, a sformoval hned od života matky, a spomáhá tobě: Neboj se, služebníče můj, Jákobe, a upřímý, kteréhož jsem vyvolil.'),
(1564797,54,23,44,3,'Nebo vyleji vody na žíznivého, a potoky na vyprahlost; vyleji Ducha svého na símě tvé, a požehnání své na potomky tvé.'),
(1564798,54,23,44,4,'I porostou jako mezi bylinami, jako vrbí vedlé tekutých vod.'),
(1564799,54,23,44,5,'Tento dí: Hospodinův já jsem, a onen nazůve se jménem Jákobovým, a jiný zapíše se rukou svou Hospodinu, a jménem Izraelským jmenovati se bude.'),
(1564800,54,23,44,6,'Takto praví Hospodin, král Izraelův a vykupitel jeho, Hospodin zástupů: Já jsem první, a já poslední, a kromě mne není žádného Boha.'),
(1564801,54,23,44,7,'Nebo kdo tak jako já ohlašuje a oznamuje to, aneb spořádá mi to hned od toho času, jakž jsem rozsadil lidi na světě? A kdo to, což přijíti má, oznámiti jim mohou?'),
(1564802,54,23,44,8,'Nebojtež se, ani lekejte. Zdali hned zdávna nepověděl jsem tobě a neoznámil, čehož vy sami mně svědkové jste? Zdaliž jest Bůh kromě mne? Neníť jistě žádné skály, jáť o žádné nevím.'),
(1564803,54,23,44,9,'Ti, kteříž formují rytiny, všickni nic nejsou; tolikéž ty milostné jejich nic neprospívají. Čehož ony sobě samy svědectvím jsou; nic nevidí, aniž čeho znají, aby se styděti mohly.'),
(1564804,54,23,44,10,'Kdo formuje Boha silného a rytinu slévá, k ničemu se to nehodí.'),
(1564805,54,23,44,11,'Aj, všickni, i ti, kteříž se k němu přiúčastňují, zahanbeni budou, ovšem řemeslníci ti nad jiné lidi; byť se pak všickni shromáždili a postavili, strašiti se musejí, a spolu zahanbeni budou.'),
(1564806,54,23,44,12,'Kovář pochytě železo, dělá při uhlí, a kladivy formuje modlu. Když ji dělá vší silou svou, ještě k tomu lační až do zemdlení, aniž se vody napije, až i ustává.'),
(1564807,54,23,44,13,'Tesař roztáhna šňůru, znamenává ji hrudkou, spravuje ji úhelnicemi, a kružidlem rozměřuje ji, až ji udělá tvárnost muže mající a podobnost krásy člověka, aby seděla doma.'),
(1564808,54,23,44,14,'Nasekaje sobě cedrů, vezme také cypřiš a dub aneb to, kteréž jest nejcelistvější mezi dřívím lesním; i javor štěpuje, a déšť jej k zrostu přivozuje.'),
(1564809,54,23,44,15,'I bývá člověku k topení; nebo vezma z něho, zhřívá se. Rozněcuje také oheň, aby napekl chleba. Mimo to udělá sobě boha, a klaní se jemu; udělá z něho rytinu, a kleká před ní.'),
(1564810,54,23,44,16,'Částku jeho pálí ohněm, při druhé částce jeho maso jí, peče pečeni, a nasycen bývá. Zhřívá se také, a říká: Aha, zhřel jsem se, viděl jsem oheň.'),
(1564811,54,23,44,17,'Z ostatku pak jeho udělá boha, rytinu svou, před níž kleká, a klaní se, a modlí se jí, řka: Vysvoboď mne, nebo Bůh silný můj jsi.'),
(1564812,54,23,44,18,'Neznají ani soudí, proto že zaslepil oči jejich, aby neviděli, a srdce jejich, aby nerozuměli.'),
(1564813,54,23,44,19,'Aniž považují toho v srdci svém. Není umění, není rozumu, aby kdo řekl: Díl z něho spálil jsem ohněm, a při uhlí jeho napekl jsem chleba, pekl jsem maso, a jedl jsem, a mám z ostatku jeho ohavnost udělati, a před špalkem dřevěným klekati?'),
(1564814,54,23,44,20,'Popelem se pase takový, srdce svedené skloňuje jej, aby nemohl osvoboditi duše své, ani říci: Není-liž omylu v předsevzetí mém?'),
(1564815,54,23,44,21,'Pamatujž na to, Jákobe a Izraeli, proto že jsi ty služebník můj. Já jsem tě sformoval, služebník můj jsi, Izraeli, nebudeš u mne v zapomenutí.'),
(1564816,54,23,44,22,'Zahladím jako hustý oblak přestoupení tvá, a jako mrákotu hříchy tvé; navratiž se ke mně, nebo jsem tě vykoupil.'),
(1564817,54,23,44,23,'Prozpěvujte nebesa, nebo Hospodin to učinil; zvučte nižiny země, zvučně prozpěvujte hory, les i všeliké dříví v něm, nebo vykoupil Hospodin Jákoba, a v Izraeli sebe oslavil.'),
(1564818,54,23,44,24,'Takto praví Hospodin vykupitel tvůj, a ten, kterýž tě sformoval hned od života matky: Já Hospodin činím všecko, roztahuji nebesa sám, rozprostírám zemi mocí svou.'),
(1564819,54,23,44,25,'Rozptyluji znamení lhářů, a z hadačů blázny dělám; obracím moudré nazpět, a umění jejich v bláznovství.'),
(1564820,54,23,44,26,'Potvrzuji slova služebníka svého, a radu poslů svých vykonávám. Kterýž dím o Jeruzalému: Bydleno bude v něm, a o městech Judských: Vystavena budou, nebo pustiny jejich vzdělám.'),
(1564821,54,23,44,27,'Kterýž dím hlubině: Vyschni, nebo potoky tvé vysuším.'),
(1564822,54,23,44,28,'Kterýž dím o Cýrovi: Pastýř můj, nebo všelikou vůli mou vykoná, a řekne Jeruzalému: Zase vystaven buď, a chrámu: Založen buď.'),
(1564823,54,23,45,1,'Takto praví Hospodin pomazanému svému Cýrovi, jehož pravici zmocním, a národy před ním porazím, a bedra králů rozpáši, a zotvírám před ním vrata, a brány nebudou zavírány:'),
(1564824,54,23,45,2,'Já před tebou půjdu, a cesty křivé zpřímím, vrata měděná potru, a závory železné posekám.'),
(1564825,54,23,45,3,'A dám tobě poklady skryté, a klénoty schované, abys poznal, že já jsem Hospodin Bůh Izraelský, kterýž tě ze jména volám.'),
(1564826,54,23,45,4,'Pro služebníka svého Jákoba a Izraele vyvoleného svého jmenoval jsem tě jménem tvým, i příjmím tvým, ačkoli mne neznáš.'),
(1564827,54,23,45,5,'Já jsem Hospodin, a není žádného více, kromě mne není žádného Boha. Přepásal jsem tě, ačkoli mne neznáš,'),
(1564828,54,23,45,6,'Aby poznali od východu slunce i od západu, že není žádného kromě mne. Jáť jsem Hospodin, a není, žádného více.'),
(1564829,54,23,45,7,'Kterýž formuji světlo, a tvořím tmu, působím pokoj, a tvořím zlé, já Hospodin činím to všecko.'),
(1564830,54,23,45,8,'Rosu dejte nebesa s hůry, a nejvyšší oblakové dštěte spravedlnost; otevři se země, a ať vzejde spasení, a spravedlnost ať spolu vykvete. Já Hospodin způsobím to.'),
(1564831,54,23,45,9,'Běda tomu, kdož se v odpory dává s tím, jenž jej sformoval, jsa střep jako jiné střepiny hliněné. Zdaliž dí hlina hrnčíři svému: Což děláš? Dílo tvé zajisté ničemné jest.'),
(1564832,54,23,45,10,'Běda tomu, kterýž říká otci: Co zplodíš? A ženě: Co porodíš?'),
(1564833,54,23,45,11,'Takto praví Hospodin, Svatý Izraelský, a kterýž jej sformoval: Budoucí-liž věci na mně vyzvídati chcete, o synech mých a díle rukou mých mně vyměřovati?'),
(1564834,54,23,45,12,'Já jsem učinil zemi, a člověka na ní stvořil; já jsem, jehož ruce roztáhly nebesa, a všemu vojsku jejich rozkazuji.'),
(1564835,54,23,45,13,'Já vzbudím jej v spravedlnosti, a všecky cesty jeho zpřímím. Onť vzdělá město mé, a zajaté mé propustí, ne ze mzdy, ani pro dar, praví Hospodin zástupů.'),
(1564836,54,23,45,14,'Takto praví Hospodin: Práce Egyptská, a kupectví Mouřenínská, a Sabejští, muži veliké postavy, k tobě přijdou, a tvoji budou. Za tebou se poberou, v poutech půjdou, tobě se klaněti, a tobě se kořiti budou, říkajíce: Toliko u tebe jest Bůh silný, a neníť žádného více kromě toho Boha.'),
(1564837,54,23,45,15,'(Jistě ty jsi Bůh silný, skrývající se, Bůh Izraelský, spasitel.)'),
(1564838,54,23,45,16,'Všickni onino se zastydí, a zahanbeni budou, spolu odejdou s hanbou činitelé obrazů;'),
(1564839,54,23,45,17,'Ale Izrael spasen bude skrze Hospodina spasením věčným. Nebudete zahanbeni, ani v lehkost uvedeni na věky věků.'),
(1564840,54,23,45,18,'Nebo tak praví Hospodin stvořitel nebes, (ten Bůh, kterýž sformoval zemi a učinil ji, kterýž utvrdil ji, ne na prázdno stvořil ji, k bydlení sformoval ji): Já jsem Hospodin, a není žádného více.'),
(1564841,54,23,45,19,'Nemluvím tajně v místě zemském tmavém, neříkám semeni Jákobovu nadarmo: Hledejte mne. Já Hospodin mluvím spravedlnost, a zvěstuji věci pravé.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564842,54,23,45,20,'Shromažďte se a přiďte, přibližte se spolu vy, kteříž jste pozůstali mezi pohany. Nic neznají ti, kteříž se s dřevem rytiny své nosí; nebo se modlí bohu, kterýž nemůže vysvoboditi.'),
(1564843,54,23,45,21,'Oznamte a přiveďte i jiné, a nechať spolu v radu vejdou, a ukáží, kdo to od starodávna předpověděl, a hned zdávna oznámil? Zdali ne já Hospodin? Neboť není žádného jiného Boha kromě mne, není Boha silného, spravedlivého, a spasitele žádného kromě mne.'),
(1564844,54,23,45,22,'Obraťtež zřetel ke mně, abyste spaseny byly všecky končiny země; nebo já jsem Bůh silný, a není žádného více.'),
(1564845,54,23,45,23,'Skrze sebe přisáhl jsem, vyšlo z úst mých slovo spravedlnosti, kteréž nepůjde na zpět: Že se mně skláněti bude všeliké koleno, a přisahati každý jazyk,'),
(1564846,54,23,45,24,'Říkaje: Toliko v Hospodinu mám všelijakou spravedlnost a sílu, a až k samému přijde; ale zahanbeni budou všickni, kteříž se koli zlobí proti němu.'),
(1564847,54,23,45,25,'V Hospodinu ospravedlněni budou, a chlubiti se všecko símě Izraelovo.'),
(1564848,54,23,46,1,'Klesl Bél, padl Nébo, modly jejich octnou se na hovadech a na dobytku. Tím zajisté, což vy nosíváte, budou náramně obtížena až do ustání.'),
(1564849,54,23,46,2,'Klesly, padly spolu, aniž budou moci retovati břemene, nýbrž i oni sami v zajetí odejdou.'),
(1564850,54,23,46,3,'Slyšte mne, dome Jákobův, a všickni ostatkové domu Izraelova, kteréž pěstuji hned od života, kteréž nosím hned od narození:'),
(1564851,54,23,46,4,'Až i do starosti já sám, nýbrž až do šedin já ponesu; já jsem vás učinil, a já nositi budu, já, pravím, ponesu a vysvobodím.'),
(1564852,54,23,46,5,'K komu mne připodobníte a přirovnáte, aneb podobna učiníte, abychom sobě podobní byli?'),
(1564853,54,23,46,6,'Ti, kteříž marně vynakládají zlato z měšce, a stříbro na vážkách váží, najímají ze mzdy zlatníka, aby udělal z něho boha, před nímž padají a sklánějí se.'),
(1564854,54,23,46,7,'Nosí jej na rameni, pěstují se s ním, a stavějí ho na místě jeho, i stojí, z místa svého se nehýbaje. Volá-li kdo k němu, neozývá se, aniž jej z úzkosti jeho vysvobozuje.'),
(1564855,54,23,46,8,'Pamatujtež na to, a zastyďte se; připusťte to, ó zpronevěřilí, k srdci.'),
(1564856,54,23,46,9,'Rozpomeňte se na první věci od věků stalé, nebo já jsem Bůh silný, a není žádného více Boha, aniž jest mně podobného.'),
(1564857,54,23,46,10,'Kterýž oznamuji při počátku dokonání, a hned zdaleka to, což se ještě nestalo; řeknu-li co, rada má se koná, a vše, což mi se líbí, činím.'),
(1564858,54,23,46,11,'Kterýž zavolám od východu ptáka, z země daleké toho, kterýž by vykonal uložení mé. Řekl jsem, a dovedu toho, umínil jsem, a vykonám to.'),
(1564859,54,23,46,12,'Slyšte mne, vy urputného srdce, kteříž jste dalecí od spravedlnosti.'),
(1564860,54,23,46,13,'Jáť způsobím, aby se přiblížila spravedlnost má. Nebudeť prodlévati, aniž spasení mé bude meškati; nebo složím v Sionu spasení, a v Izraeli slávu svou.'),
(1564861,54,23,47,1,'Sstup a seď v prachu, panno dcero Babylonská, seď na zemi, a ne na trůnu, dcero Kaldejská; nebo nebudou tě více nazývati milostnou a rozkošnou.'),
(1564862,54,23,47,2,'Chyť se žernovu, a mel mouku; odkrej kadeře své, obnaž nohy, odkrej hnáty, břeď přes řeky.'),
(1564863,54,23,47,3,'Odkryta bude hanba tvá, a ukáže se mrzkost tvá. Mstíti budu, a nedám sobě žádnému překaziti,'),
(1564864,54,23,47,4,'Praví vykupitel náš, jehož jméno jest Hospodin zástupů, Svatý Izraelský.'),
(1564865,54,23,47,5,'Sediž mlče, a vejdi do tmy, dcero Kaldejská; nebo nebudou tě více nazývati paní království.'),
(1564866,54,23,47,6,'Rozhněval jsem se na lid svůj, v lehkost jsem uvedl dědictví své, a vydal jsem je v ruku tvou, a neprokázalas k nim milosrdenství. Starce jsi obtížila velmi jhem svým,'),
(1564867,54,23,47,7,'A říkalas: Na věky budu paní, a nikdy jsi nesložila těch věcí v srdci svém, aniž jsi pamatovala na cíl jeho.'),
(1564868,54,23,47,8,'Protož nyní slyšiž toto, ó rozkošná, (kteráž sedíš bezpečně, a říkáš v srdci svém: Já jsem, a není kromě mne žádné; nebuduť vdovou, aniž zvím o sirobě),'),
(1564869,54,23,47,9,'Že obé to přijde na tě pojednou dne jednoho, i siroba i vdovství. Všecko zúplna přijde na tě, i na množství kouzlů tvých, a na velikou moc čárů tvých.'),
(1564870,54,23,47,10,'Nebo doufáš v zlost svou, a říkáš: Žádný mne nevidí. Moudrost tvá a umění tvé, to tě převrátilo, abys říkala v srdci svém: Já jsem, a není kromě mne žádné.'),
(1564871,54,23,47,11,'A protož přijde na tě zlé, jehož východu neznáš, a připadne na tě bída, kteréž nebudeš moci se odžehnati, a přijde na tě pojednou hrozné zpuštění, než zvíš.'),
(1564872,54,23,47,12,'Postav se nyní s čáry svými, a s množstvím kouzlů svých, jimiž jsi se zaměstknávala od mladosti své, budeš-li moci co prospěti, aneb snad zmocniti se.'),
(1564873,54,23,47,13,'Ustáváš s množstvím rad svých. Nechať se nyní postaví hvězdáři, kteříž spatřují hvězdy, a oznamují na každý měsíc, a vysvobodí tě z toho, což přijíti má na tě.'),
(1564874,54,23,47,14,'Aj, jako pleva jsou, oheň popálí je, nevychvátí ani sami sebe z prudkosti plamene; žádného uhlí nezůstane k zhřívání se, ani ohně, aby se mohlo poseděti u něho.'),
(1564875,54,23,47,15,'Takť se stane i kupcům tvým, jimiž jsi se zaměstknávala od mladosti své. Jeden každý svou stranou půjde, aniž bude, kdo by tě vysvobodil.'),
(1564876,54,23,48,1,'Slyštež to, dome Jákobův, kteříž se nazýváte jménem Izraelovým, a z vod Judových jste pošli, kteříž přisaháte ve jménu Hospodinovu, a Boha Izraelského připomínáte, však ne v pravdě, ani v spravedlnosti,'),
(1564877,54,23,48,2,'Ačkoli od města svatého se jmenujete, a na Boha Izraelského, jehož jméno jest Hospodin zástupů, zpoléháte.'),
(1564878,54,23,48,3,'Předešlé věci zdávna jsem oznamoval, a což vyšlo z úst mých, i což jsem ohlašoval, brzce jsem činíval, a stávalo se.'),
(1564879,54,23,48,4,'Věděl jsem, že jsi zatvrdilý, a houžev železná šíje tvá, a čelo tvé ocelivé.'),
(1564880,54,23,48,5,'A protožť jsem oznamoval z dávna, prvé než přicházelo, ohlašovalť jsem, abys neříkal: Modla má učinila ty věci, a rytina má neb slitina má přikázala to.'),
(1564881,54,23,48,6,'Slýchals o tom, pohlediž na to na všecko, vy pak, nebudete-liž toho oznamovati? Již nyní ohlašujiť nové a tajné věci, o nichž jsi ty nic nevěděl.'),
(1564882,54,23,48,7,'Nyní stvořeny jsou, a ne předešlého času, o nichž jsi před tímto dnem nic neslyšel, abys neřekl: Aj, věděl jsem o tom.'),
(1564883,54,23,48,8,'Anobrž aniž jsi slyšel, ani věděl, aniž se to tehdáž doneslo ucha tvého; nebo jsem věděl, že sobě velmi nevážně počínati budeš, a že jsi převrácenec hned od života matky.'),
(1564884,54,23,48,9,'Pro jméno své poshovím s prchlivostí svou, a pro chválu svou poukrotím hněvu proti tobě, abych tě nevyplénil.'),
(1564885,54,23,48,10,'Aj, přepálím tě, ačkoli ne jako stříbro, přeberu tě v peci ssoužení.'),
(1564886,54,23,48,11,'Pro sebe, pro sebe učiním to. Nebo jakž by mohlo v lehkost vydáno býti? Slávy své zajisté jinému nedám.'),
(1564887,54,23,48,12,'Slyš mne, Jákobe a Izraeli, povolaný můj: Já jsem, já první, já jsem i poslední.'),
(1564888,54,23,48,13,'Má zajisté ruka založila zemi, a pravice má dlaní rozměřila nebesa; povolal jsem jich, a hned se postavily.'),
(1564889,54,23,48,14,'Shromažďte se vy všickni, a slyšte. Kdo z nich oznámil tyto věci: Hospodin miluje jej, onť vykoná vůli jeho proti Babylonu, a rámě jeho proti Kaldejským?'),
(1564890,54,23,48,15,'Já, já mluvil jsem, protož povolám ho; přivedu jej, a šťastnou bude míti cestu svou.'),
(1564891,54,23,48,16,'Přistupte ke mně, slyšte to: Nemluvíval jsem z počátku v skrytě; od toho času, v kterémž se to dálo, přítomen jsem byl. A nyní Panovník Hospodin poslal mne a duch jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564892,54,23,48,17,'Toto praví Hospodin vykupitel tvůj, Svatý Izraelský: Já Hospodin Bůh tvůj učím tě, abys prospěch bral, a vodím tě po cestě, po kteréž bys chodil.'),
(1564893,54,23,48,18,'Ó kdybys byl šetřil přikázaní mých, bylť by jako potok pokoj tvůj, a spravedlnost tvá jako vlny mořské.'),
(1564894,54,23,48,19,'A bylo by jako písku semene tvého, a plodu života tvého jako štěrku jeho, aniž by vyťato, ani vyhlazeno bylo jméno jeho před oblíčejem mým.'),
(1564895,54,23,48,20,'Vyjděte z Babylona, utecte od Kaldejských, hlasem zvučným zvěstujte, ohlašujte to, rozneste to až do končin země. Rcete: Vykoupil Hospodin služebníka svého Jákoba.'),
(1564896,54,23,48,21,'Nebudouť žízniti, když je po pustinách povede, vody z skály vyvede jim; nebo rozetne skálu, aby tekly vody.'),
(1564897,54,23,48,22,'Nemajíť žádného pokoje, praví Hospodin, bezbožní.'),
(1564898,54,23,49,1,'Poslouchejte mne ostrovové, a pozorujte národové dalecí: Hospodin hned z života povolal mne, od života matky mé v pamět uvedl jméno mé,'),
(1564899,54,23,49,2,'A učinil ústa má podobná meči ostrému. V stínu ruky své skryl mne, a učiniv ze mne střelu vypulerovanou, v toule svém schoval mne.'),
(1564900,54,23,49,3,'A řekl mi: Služebník můj jsi, v Izraeli skrze tebe oslaven budu.'),
(1564901,54,23,49,4,'Já pak řekl jsem: Nadarmo jsem pracoval, daremně a marně sílu svou jsem strávil. Ale však soud můj jestiť u Hospodina, a práce má u Boha mého.'),
(1564902,54,23,49,5,'A nyní dí Hospodin, kterýž mne sformoval hned od života za služebníka svého, abych zase přivedl k němu Jákoba; (byť pak i nebyl sebrán Izrael, slávu však mám před očima Hospodinovýma; nebo Bůh můj jest síla má);'),
(1564903,54,23,49,6,'I to řekl Hospodin: Máloť by to bylo, abys mi byl služebníkem ku pozdvižení pokolení Jákobových, a k navrácení ostatků Izraelských; protož dal jsem tě za světlo pohanům, abys byl spasení mé až do končin země.'),
(1564904,54,23,49,7,'Toto praví Hospodin vykupitel Izraelův, Svatý jeho, tomu, jímž pohrdá každý, a jehož sobě oškliví národové, služebníku panujících: Králové, vidouce tě, povstanou, a knížata klaněti se budou pro Hospodina, kterýž věrný jest, Svatého Izraelského, jenž tě vyvolil.'),
(1564905,54,23,49,8,'Toto praví Hospodin: V čas milosti vyslyším tě, a ve dni spasení spomohu tobě. Nadto ostříhati tě budu, a dám tě v smlouvu lidu, abys utvrdil zemi, a v dědictví uvedl dědictví zpuštěná;'),
(1564906,54,23,49,9,'Abys řekl vězňům: Vyjděte, těm, kteříž jsou ve tmách: Zjevte se. I budou se pásti podlé cest, a na všech místech vysokých bude pastva jejich.'),
(1564907,54,23,49,10,'Nebudou lačněti ani žízniti, nebude na ně bíti horko ani slunce; nebo slitovník jejich zprovodí je, a podlé pramenů vod povede je.'),
(1564908,54,23,49,11,'Přes to způsobím na všech horách svých cesty, a silnice mé vyvýšeny budou.'),
(1564909,54,23,49,12,'Aj, tito zdaleka přijdou, aj, onino od půlnoci a od moře, a jiní z země Sinim.'),
(1564910,54,23,49,13,'Prozpěvujte nebesa, a plésej země, a zvučně prokřikujte hory; neboť jest potěšil Hospodin lidu svého, a nad chudými svými slitoval se.'),
(1564911,54,23,49,14,'Ale řekl Sion: Opustiltě mne Hospodin, a Pán zapomenul se na mne.'),
(1564912,54,23,49,15,'I zdaliž se může zapomenouti žena nad nemluvňátkem svým, aby se neslitovala nad plodem života svého? A byť se pak ony zapomněly, já však nezapomenu se na tě.'),
(1564913,54,23,49,16,'Aj, na dlaních vyryl jsem tě, zdi tvé jsou vždycky přede mnou.'),
(1564914,54,23,49,17,'Pospíšíť k tobě synové tvoji, ti pak, kteříž tě bořili a kazili, odejdou od tebe.'),
(1564915,54,23,49,18,'Pozdvihni vůkol očí svých, a pohleď, všickni ti shromáždíce se, přijdou k tobě. Živť jsem já, praví Hospodin, že se jimi všemi jako okrasou přioděješ, a otočíš se jimi jako halží nevěsta,'),
(1564916,54,23,49,19,'Proto že pustiny tvé, a pouště tvé, a zbořeniny země tvé že tehdáž těsné budou, příčinou obyvatelů, když vzdáleni budou ti, kteříž tě zžírali;'),
(1564917,54,23,49,20,'Tak že řeknou před tebou synové siroby tvé: Těsné mi jest toto místo, ustup mi, abych bydliti mohl.'),
(1564918,54,23,49,21,'I díš v srdci svém: Kdo mi naplodil těchto? Nebo jsem já byla osiřelá a osamělá, sem i tam přecházející a odcházející. Tyto, pravím, kdo vychoval? Aj, pozůstala jsem byla sama jediná. Kdež tito byli?'),
(1564919,54,23,49,22,'Toto praví Panovník Hospodin: Aj, já pozdvihnu k národům ruky své, a k lidem vyzdvihnu korouhev svou, aby přinesli syny tvé na rukou, a dcery tvé aby na plecech neseny byly.'),
(1564920,54,23,49,23,'I budou králové pěstounové tvoji, a královny jejich chovačky tvé. Tváří k zemi skláněti se budou před tebou, a prach noh tvých lízati budou, a poznáš, že jsem já Hospodin, a že nebývají zahanbeni, kteříž na mne očekávají.'),
(1564921,54,23,49,24,'Ale díš: Zdaliž odjato bude reku udatnému to, což uchvátil? A zdaž zajatý lid spravedlivého vyproštěn bude?'),
(1564922,54,23,49,25,'Anobrž tak praví Hospodin: I zajatý lid reku udatnému odjat bude, a to, což uchvátil násilník, vyproštěno bude; nebo s tím, kterýž se s tebou nesnadní, já se nesnadniti budu, a syny tvé já vysvobodím.'),
(1564923,54,23,49,26,'A nakrmím ty, kteříž tě utiskují, vlastním masem jejich, a jako mstem krví svou se zpijí. I poznáť všeliké tělo, že já Hospodin jsem spasitel tvůj, a vykupitel tvůj Bůh silný Jákobův.'),
(1564924,54,23,50,1,'Takto praví Hospodin: Kdež jest lístek zapuzení matky vaší, kterýmž jsem ji propustil? Aneb kdo jest z věřitelů mých, jemuž jsem vás prodal? Aj, nepravostmi svými prodali jste sebe, a pro převrácenosti vaše propuštěna jest matka vaše.'),
(1564925,54,23,50,2,'Proč, když přicházím, není žádného, když volám, žádný se neozývá? Zdaliž jest naprosto ukrácena ruka má, aby nemohla vykoupiti? A žádné-liž není ve mně moci k vysvobození? Aj, žehráním svým vysušuji moře, obracím řeky v poušť, až se smrazují ryby jejich, proto že nebývá vody, a mrou žízní.'),
(1564926,54,23,50,3,'Obláčím nebesa v smutek, a žíni dávám jim za oděv.'),
(1564927,54,23,50,4,'Panovník Hospodin dal mi jazyk umělý, abych uměl příhodně ustalému mluviti slova. Probuzuje každého jitra, probuzuje mi uši, abych slyšel, tak jako pilně se učící.'),
(1564928,54,23,50,5,'Panovník Hospodin otvírá mi uši, a já se nepostavuji zpurně, aniž se nazpět odvracím.'),
(1564929,54,23,50,6,'Těla svého nastavuji bijícím, a líce svého rvoucím mne, tváři své neskrývám od pohanění a plvání.'),
(1564930,54,23,50,7,'Nebo Panovník Hospodin spomáhá mi, pročež nebývám zahanben. Pro touž příčinu nastavuji tváři své jako škřemene; nebo vím, že nebudu zahanben.'),
(1564931,54,23,50,8,'Blízkoť jest ten, kterýž mne ospravedlňuje. Kdož se nesnadniti bude se mnou? Postavme se spolu; kdo jest odpůrce můj, nechť přistoupí ke mně.'),
(1564932,54,23,50,9,'Aj, Panovník Hospodin spomáhati mi bude. Kdož jest, ješto by mne potupil? Aj, všickni takoví jako roucho zvetšejí, mol sžíře je.'),
(1564933,54,23,50,10,'Kdo jest mezi vámi, ješto se bojí Hospodina, poslouchej hlasu služebníka jeho. Kdo jest, ješto chodí v temnostech, a nemá žádného světla, doufej ve jméno Hospodinovo, a zpolehni na Boha svého.'),
(1564934,54,23,50,11,'Aj, vy všickni, kteříž zaněcujete oheň, a jiskrami se přepasujete, choďtež v blesku ohně svého, a v jiskrách, kteréž jste roznítili. Od ruky mé toto se vám stane, že v bolesti ležeti budete.'),
(1564935,54,23,51,1,'Poslouchejte mne, následovníci spravedlnosti, kteříž hledáte Hospodina, pohleďte na skálu, odkudž vyťati jste, a na hlubokost jámy, z níž vykopáni jste.'),
(1564936,54,23,51,2,'Pohleďte na Abrahama otce vašeho, a na Sáru, kteráž vás porodila, že jsem jej jediného povolal, a požehnal jsem jemu, i rozmnožil jej.'),
(1564937,54,23,51,3,'Nebo potěší Hospodin Siona, potěší všech pustin jeho, a učiní poušť jeho přerozkošnou, a pustinu jeho podobnou zahradě Hospodinově. Radost a veselí bude nalezeno v něm, díkčinění, a hlas žalmů zpívání.'),
(1564938,54,23,51,4,'Pozorujte mne, lide můj, a rodino má, nastavte mi uší; nebo zákon ode mne vyjde, a soud svůj za světlo národům vystavím.'),
(1564939,54,23,51,5,'Blízko jest spravedlnost má, vyjdeť spasení mé, a ramena má národy souditi budou. Na mneť ostrovové čekají, a po mém rameni touží.'),
(1564940,54,23,51,6,'Pozdvihněte k nebi očí svých, a popatřte na zem dolů. Nebesa zajisté jako dým zmizejí, a země jako roucho zvetší, a obyvatelé její též podobně zemrou: ale spasení mé na věky zůstane, a spravedlnost má nezahyne.'),
(1564941,54,23,51,7,'Poslouchejte mne, kteříž znáte spravedlnost, lide, v jehož srdci jest zákon můj; nebojte se útržky lidí bídných, a hanění jejich neděste se.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564942,54,23,51,8,'Nebo jako roucho zžíře je mol, a jako vlnu zžíře je červ, ale spravedlnost má na věky zůstane, a spasení mé od národu do pronárodu.'),
(1564943,54,23,51,9,'Probuď se, probuď se, oblec se v sílu, ó rámě Hospodinovo, probuď se, jako za dnů starodávních a národů předešlých. Zdaliž ty nejsi to, kteréžs poplénilo Egypt, a ranilo draka?'),
(1564944,54,23,51,10,'Zdaliž ty nejsi to, kteréžs vysušilo moře, vody propasti veliké, kteréžs obrátilo hlubiny mořské v cestu, aby přešli ti, jenž byli vysvobozeni?'),
(1564945,54,23,51,11,'A tak ti, kteréž vykoupil Hospodin, ať se navrátí, a přijdou na Sion s prozpěvováním, a veselé věčné ať jest na hlavě jejich; radosti a veselé ať dojdou, zámutek pak a úpění ať utekou.'),
(1564946,54,23,51,12,'Já, já jsem utěšitel váš. Jakáž jsi ty, že se bojíš člověka smrtelného, a syna člověka trávě podobného?'),
(1564947,54,23,51,13,'Že se zapomínáš na Hospodina učinitele svého, kterýž roztáhl nebesa, a založil zemi, a že se děsíš ustavičně každého dne prchlivosti ssužujícího, jakž se jen postrojí, aby hubil? Ale kdež jest pak ta prchlivost toho,kterýž ssužuje?'),
(1564948,54,23,51,14,'Pospíšíť, aby zajatý propuštěn byl; neboť neumře v jámě, aniž bude míti jaký nedostatek chleba svého.'),
(1564949,54,23,51,15,'Jáť jsem zajisté Hospodin Bůh tvůj, kterýž rozděluje moře, jehož vlny zvuk vydávají. Hospodin zástupů jest jméno mé,'),
(1564950,54,23,51,16,'Kterýž jsem vložil slova svá v ústa tvá, a stínem ruky své přikryl jsem tě, abys štípil nebesa, a založil zemi, a řekl Sionu: Lid můj jsi ty.'),
(1564951,54,23,51,17,'Probuď se, probuď, povstaň, Jeruzaléme, kterýž jsi pil z ruky Hospodinovy kalich prchlivosti jeho, kvasnice z kalicha hrůzy vypil jsi, i vyvážil.'),
(1564952,54,23,51,18,'Žádný jí nevedl ze všech synů, kterýchž naplodila, a žádný jí neujal za ruku její ze všech synů, kteréž vychovala.'),
(1564953,54,23,51,19,'Toto dvé tě potkalo, (kdo tě politoval?) zpuštění a setření, hlad a meč. Kdo tě potěšoval?'),
(1564954,54,23,51,20,'Synové tvoji omráčeni jsouc, leží na rozcestí všech ulic, jako bůvol v leči, plni jsouce prchlivosti Hospodinovy, žehrání Boha tvého.'),
(1564955,54,23,51,21,'A protož slyš nyní toto, ztrápená a opilá, ale ne vínem:'),
(1564956,54,23,51,22,'Takto praví Pán tvůj, Hospodin a Bůh tvůj, vedoucí při lidu svého: Aj, beru z ruky tvé kalich hrůzy, i kvasnice kalicha prchlivosti mé, nebudeš ho píti více.'),
(1564957,54,23,51,23,'Ale dám jej do ruky těch, jenž tě ssužují, kteříž říkali duši tvé: Sehni se, ať přes tě přejdeme, jimž jsi podkládala jako zemi hřbet svůj, a jako ulici přecházejícím.'),
(1564958,54,23,52,1,'Probuď se, probuď se, oblec se v sílu svou, Sione, oblec se v roucho okrasy své, ó Jeruzaléme, město svaté; neboť nebude již více na tě dotírati neobřezaný a nečistý.'),
(1564959,54,23,52,2,'Otřes se z prachu, povstaň, posaď se,Jeruzaléme; dobuď se z okovů hrdla svého, ó jatá dcerko Sionská.'),
(1564960,54,23,52,3,'Takto zajisté dí Hospodin: Darmo jste sebe prodali, protož bez peněz budete vykoupeni.'),
(1564961,54,23,52,4,'Nebo takto praví Panovník Hospodin: Do Egypta sstoupil lid můj předešle, aby tam byl pohostinu, ale Assur bez příčiny jej ssužuje.'),
(1564962,54,23,52,5,'Nyní tedy což mám činiti? praví Hospodin. Poněvadž jest lid můj zajat darmo, a panovníci jeho k úpění jej přivodí, praví Hospodin. Nad to ustavičně každého dne jménu mému útržka se činí.'),
(1564963,54,23,52,6,'Protož poznáť lid můj jméno mé, protož poznáť, pravím, v ten den, že já tentýž, kterýž mluvím, aj, přítomen budu.'),
(1564964,54,23,52,7,'Ó jak krásné na horách nohy toho, ješto potěšené věci zvěstuje, a ohlašuje pokoj, toho, ješto zvěstuje dobré, ješto káže spasení, a mluví k Sionu: Kralujeť Bůh tvůj.'),
(1564965,54,23,52,8,'Strážní tvoji hlasu, hlasu pozdvihnou, a spolu prokřikovati budou; neboť okem v oko uzří, že Hospodin zase přivede Sion.'),
(1564966,54,23,52,9,'Zvučte, prozpěvujte spolu pustiny Jeruzalémské; neboť jest potěšil Hospodin lidu svého, vykoupil Jeruzalém.'),
(1564967,54,23,52,10,'Ohrnul Hospodin rámě svatosti své před očima všech národů, aby viděly všecky končiny země spasení Boha našeho.'),
(1564968,54,23,52,11,'Odejděte, odejděte, vyjděte z Babylona, nečistého se nedotýkejte; vyjděte z prostředku jeho, očisťte se vy, kteříž nosíte nádobí Hospodinovo.'),
(1564969,54,23,52,12,'Nebo ne s chvátáním vyjdete, aniž s utíkáním půjdete; předcházeti zajisté bude vás Hospodin, a zbéře vás Bůh Izraelský.'),
(1564970,54,23,52,13,'Aj, služebníku mému šťastně se povede, vyvýšen, vznešen a zveleben bude velmi.'),
(1564971,54,23,52,14,'A jakož mnozí se nad ním užasnou, že tak zohavena jest nad jiné lidi osoba jeho, způsob jeho nad syny lidské:'),
(1564972,54,23,52,15,'Tak zase skropí národy mnohé, i králové před ním zacpají ústa svá, proto že což jim nebylo vypravováno, to uzří, a tomu, o čemž neslýchali, porozumějí.'),
(1564973,54,23,53,1,'Kdo uvěřil kázaní našemu? A rámě Hospodinovo komu jest zjeveno?'),
(1564974,54,23,53,2,'Nebo před ním vyrostl jako proutek, a jako kořen z země vyprahlé, nemaje podoby ani krásy. Viděliť jsme jej, ale nic nebylo viděti toho, proč bychom ho žádostivi byli.'),
(1564975,54,23,53,3,'Nejpohrdanější zajisté a nejopovrženější byl z lidí, muž bolestí, a kterýž zkusil nemocí, a jako ukrývající tvář svou; nejpohrdanější, pročež jsme ho za nic nevážili.'),
(1564976,54,23,53,4,'Ještotě on nemoci naše vzal, a bolesti naše vlastní on nesl, my však domnívali jsme se, že jest raněn, a ubit od Boha, i strápen.'),
(1564977,54,23,53,5,'On pak raněn jest pro přestoupení naše, potřín pro nepravosti naše; kázeň pokoje našeho na něj vzložena, a zsinalostí jeho lékařství nám způsobeno.'),
(1564978,54,23,53,6,'Všickni my jako ovce zbloudili jsme, jeden každý na cestu svou obrátili jsme se, a Hospodin uvalil na něj nepravosti všech nás.'),
(1564979,54,23,53,7,'Pokutován jest i strápen, však neotevřel úst svých. Jako beránek k zabití veden byl, a jako ovce před těmi, kdož ji střihou, oněměl, aniž otevřel úst svých.'),
(1564980,54,23,53,8,'Z úzkosti a z soudu vyňat jest, a protož rod jeho kdo vypraví, ačkoli vyťat jest z země živých, a zraněn pro přestoupení lidu mého?'),
(1564981,54,23,53,9,'Kterýžto vydal bezbožným hrob jeho, a bohatému, aby byl usmrcen, ješto však nepravosti neučinil, aniž jest nalezena lest v ústech jeho.'),
(1564982,54,23,53,10,'Taktě se líbilo Hospodinu jej stírati, a nemocí trápiti, aby polože duši svou v oběť za hřích,viděl símě své, byl dlouhověký, a to, což se líbí Hospodinu, skrze něho šťastně konáno bylo.'),
(1564983,54,23,53,11,'Z práce duše své uzří užitek, jímž nasycen bude. Známostí svou ospravedlní spravedlivý služebník můj mnohé; nebo nepravosti jejich on sám ponese.'),
(1564984,54,23,53,12,'A protož dám jemu díl pro mnohé, aby s nesčíslnými dělil se o kořist, proto že vylil na smrt duši svou, a s přestupníky počten jest. Onť sám nesl hřích mnohých, a přestupníků zástupcím byl.'),
(1564985,54,23,54,1,'Prozpěvuj,neplodná, kteráž nerodíš, zvučně prozpěvuj a prokřikni, kteráž ku porodu nepracuješ, nebo více bude synů opuštěné, nežli synů té, kteráž má muže, praví Hospodin.'),
(1564986,54,23,54,2,'Rozšiř místo stanu svého, a čalounů příbytků svých roztáhnouti nezbraňuj; natáhni i provazů svých, a kolíky své utvrď.'),
(1564987,54,23,54,3,'Nebo na pravo i na levo se rozmůžeš, a símě tvé národy dědičně vládnouti bude, a města pustá osadí.'),
(1564988,54,23,54,4,'Nebojž se, nebo nebudeš zahanbena, aniž se zapyřuj, nebo nebudeš v potupu uvedena; nýbrž na potupu mladosti své zapomeneš, a na pohanění vdovství svého nezpomeneš více.'),
(1564989,54,23,54,5,'Nebo manželem tvým jest Učinitel tvůj, jehož jméno Hospodin zástupů, a vykupitel tvůj Svatý Izraelský Bohem vší země slouti bude.'),
(1564990,54,23,54,6,'Nebo jako ženy propuštěné a v duchu sevřené povolá tě Hospodin, a jako ženy mladice, když v pohrdnutí budeš, praví Bůh tvůj.'),
(1564991,54,23,54,7,'Na maličkou chvilku poopustil jsem tě, ale v slitování převelikém shromáždím tě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1564992,54,23,54,8,'V maličkém hněvě skryl jsem tvář svou na maličko před tebou, ale v milosrdenství věčném slituji se nad tebou, praví vykupitel tvůj Hospodin.'),
(1564993,54,23,54,9,'Neboť jest to u mne, co při potopě Noé. Jakož jsem přisáhl, že se nebudou více rozlévati vody Noé po zemi, tak jsem přisáhl, že se nerozhněvám na tě, aniž tobě přísně domlouvati budu.'),
(1564994,54,23,54,10,'A byť se i hory pohybovaly, a pahrbkové ustupovali, milosrdenství mé však od tebe neodstoupí, a smlouva pokoje mého se nepohne, praví slitovník tvůj Hospodin.'),
(1564995,54,23,54,11,'Ó ssoužená, vichřicí zmítaná, potěšení zbavená, aj, já položím na karbunkulích kamení tvé, a založím tě na zafiřích.'),
(1564996,54,23,54,12,'A vzdělám z křištálu skla tvá, a brány tvé z kamení třpytícího se, i všecka pomezí tvá z kamení drahého.'),
(1564997,54,23,54,13,'Synové pak tvoji všickni vyučení budou od Hospodina, a hojnost pokoje budou míti synové tvoji.'),
(1564998,54,23,54,14,'Na spravedlnosti upevněna budeš. Vzdálíš se od ssoužení, protož se ho nebudeš báti, a od setření, nebo nepřiblíží se k tobě.'),
(1564999,54,23,54,15,'Aj, budouť nejedni bydliti s tebou, kteříž nejsou moji, ale kdož by bydleje s tebou, byl proti tobě, padne.'),
(1565000,54,23,54,16,'Aj, já stvořil jsem kováře dýmajícího při ohni na uhlí, a vynášejícího nádobí k dílu svému, já také stvořil jsem zhoubce, aby hubil.'),
(1565001,54,23,54,17,'Žádný nástroj proti tobě udělaný nepodaří se, a každý jazyk, povstávající proti tobě na soudu, potupíš. Toť jest dědictví služebníků Hospodinových, a spravedlnost jejich ode mne, praví Hospodin.'),
(1565002,54,23,55,1,'Ej, všickni žízniví, poďte k vodám, i vy,kteříž nemáte žádných peněz. Poďte, kupujte a jezte, poďte, pravím, kupujte bez peněz a bez záplaty víno a mléko.'),
(1565003,54,23,55,2,'Proč vynakládáte peníze ne za chléb, a práci svou za to, což nenasycuje? Poslechněte mne raději, a jezte to, což jest dobrého, a nechť se kochá v tuku duše vaše.'),
(1565004,54,23,55,3,'Nakloňte ucha svého, a poďte ke mně, poslechněte, a budeť živa duše vaše; učiním zajisté s vámi smlouvu věčnou, milosrdenství Davidova přepevná.'),
(1565005,54,23,55,4,'Aj, za svědka národům dal jsem jej, za vůdce a učitele národům.'),
(1565006,54,23,55,5,'Aj, národu, k němužs se neznal, povoláš, a národové, kteříž tě neznali, k tobě se sběhnou, pro Hospodina Boha tvého, a Svatého Izraelského, nebo tě oslaví.'),
(1565007,54,23,55,6,'Hledejte Hospodina, pokudž může nalezen býti; vzývejte ho, pokudž blízko jest.'),
(1565008,54,23,55,7,'Opusť bezbožný cestu svou, a člověk nepravý myšlení svá, a nechť se navrátí k Hospodinu, i slitujeť se nad ním, a k Bohu našemu, nebť jest hojný k odpuštění.'),
(1565009,54,23,55,8,'Nejsouť zajisté myšlení má jako myšlení vaše, ani cesty vaše jako cesty mé, praví Hospodin.'),
(1565010,54,23,55,9,'Ale jakož vyšší jsou nebesa než země, tak převyšují cesty mé cesty vaše, a myšlení má myšlení vaše.'),
(1565011,54,23,55,10,'Nebo jakož prší déšť neb sníh s nebe, a zase se tam nenavracuje, ale napájí zemi, a činí ji plodistvou a úrodnou, tak že vydává símě rozsívajícímu, a chléb jedoucímu,'),
(1565012,54,23,55,11,'Tak bude slovo mé, kteréž vyjde z úst mých. Nenavrátí se ke mně prázdné, ale učiní to, což mi se líbí, a prospěšně to vykoná, k čemuž je posílám.'),
(1565013,54,23,55,12,'A protož s veselím vyjdete, a v pokoji sprovozeni budete. Hory i pahrbkové zvučně naproti vám prozpěvovati budou, a všecko dříví polní rukama plésati bude.'),
(1565014,54,23,55,13,'Místo chrastiny vzejde jedlé, a místo hloží vyroste myrtus, a bude to Hospodinu k slávě, na znamení věčné, kteréž nebude vyhlazeno.'),
(1565015,54,23,56,1,'Toto praví Hospodin: Ostříhejte soudu, a čiňte spravedlnost; nebo brzo spasení mé přijde, a spravedlnost má zjevena bude.'),
(1565016,54,23,56,2,'Blahoslavený člověk, kterýž činí to, a syn člověka, kterýž se přídrží toho, ostříhaje soboty, aby jí nepoškvrňoval, a ostříhaje ruky své, aby nic zlého neučinila.'),
(1565017,54,23,56,3,'Nechť tedy nemluví cizozemec, kterýž se připojuje k Hospodinu, říkaje: Jistě odloučil mne Hospodin od lidu svého. Též ať neříká kleštěnec: Aj, já jsem dřevo suché.'),
(1565018,54,23,56,4,'Nebo toto praví Hospodin o kleštěncích, kteříž by ostříhali sobot mých, a zvolili to, což mi se líbí, a drželi smlouvu mou:'),
(1565019,54,23,56,5,'Že dám jim v domě svém a mezi zdmi svými místo, a jméno lepší nežli synů a dcer. Jméno věčné dám jim, kteréž nebude vyhlazeno.'),
(1565020,54,23,56,6,'Cizozemce pak, kteříž by se připojili k Hospodinu, aby sloužili jemu, a milovali jméno Hospodinovo, jsouce u něho za služebníky, všecky ostříhající soboty, aby jí nepoškvrňovali, a držící smlouvu mou,'),
(1565021,54,23,56,7,'Ty přivedu k hoře svatosti své, a obveselím je v domě svém modlitebném. Zápalové jejich a oběti jejich příjemné mi budou na oltáři mém; nebo dům můj dům modlitby slouti bude u všech národů.'),
(1565022,54,23,56,8,'Pravíť Panovník Hospodin, kterýž shromažďuje rozehnané Izraelovy: Ještěť shromáždím k němu a k shromážděným jeho.'),
(1565023,54,23,56,9,'Všecka zvířata polní poďte žráti, i všecka zvířata lesní.'),
(1565024,54,23,56,10,'Strážní jeho jsou slepí, všickni napořád nic neznají, všickni jsou psi němí, aniž mohou štěkati; jsou ospalci, leží, milujíce dřímotu.'),
(1565025,54,23,56,11,'Nadto jsou psi obžerní, nevědí, kdy jsou syti; pročež sami se pasou. Neumějí učiti, všickni k cestám svým patří, jeden každý k zisku svému po své straně.'),
(1565026,54,23,56,12,'Poďte, naberu vína, a opojíme se nápojem opojným, a bude rovně zítřejší jako dnešní den, nýbrž větší a mnohem hojnější.'),
(1565027,54,23,57,1,'Spravedlivý hyne, a žádný nepřipouští toho k srdci, a muži pobožní odcházejí, a žádný nerozvažuje toho, že před příchodem zlého vychvácen bývá spravedlivý,'),
(1565028,54,23,57,2,'Že dochází pokoje, a odpočívá na ložci svém, kdožkoli chodí v upřímosti své.'),
(1565029,54,23,57,3,'Ale vy přistupte sem, synové kouzedlnice, símě cizoložníka a smilnice.'),
(1565030,54,23,57,4,'Komu se to s takovou chutí posmíváte? Proti komu rozdíráte ústa, vyplazujete jazyk? Zdaliž nejste synové neřádní, símě postranní?'),
(1565031,54,23,57,5,'Kteříž smilníte v hájích pod každým dřevem zeleným, zabíjejíce syny své při potocích, pod vysokými skalami.'),
(1565032,54,23,57,6,'Mezi hladkými kameny potočními jest díl tvůj. Tiť jsou, ti los tvůj, na něž také vyléváš mokrou obět, obětuješ suchou obět. V těch-liž bych věcech se kochal?'),
(1565033,54,23,57,7,'Na hoře vysoké a vyvýšené stavíš lože své, a tam vstupuješ k obětování oběti.'),
(1565034,54,23,57,8,'Pamětné pak znamení své za dvéře a za veřeje stavíš, když ode mne, odkryvši se, vstupuješ, a rozšiřuješ lože své, činíc je prostrannější víc než pohané; miluješ lože jejich, kdež místo oblíbíš.'),
(1565035,54,23,57,9,'Chodíš i k králi s olejem, a s mnohými vonnými mastmi svými; posíláš zajisté posly své daleko, a ponižuješ se až do hrobu.'),
(1565036,54,23,57,10,'Pro množství cest svých ustáváš, aniž říkáš: Daremnéť jest to. Nalezla jsi sobě zběř ku pomoci, protož neželíš práce.'),
(1565037,54,23,57,11,'A kohož jsi se děsila a bála, že jsi klamala, a na mne se nerozpomínala, ani připustila k srdci svému? Zdali proto, že jsem já mlčel, a to zdávna, nebojíš se mne?'),
(1565038,54,23,57,12,'Já tvou spravedlnost oznámím, a skutky tvé, kteřížť nic neprospějí.'),
(1565039,54,23,57,13,'Když křičeti budeš, nechať tě vysvobodí zběř tvá. Ano pak všecky je zanese vítr, a zachvátí marnost, ale kdož doufá ve mne, vládnouti bude zemí, a dědičně obdrží horu svatou mou.'),
(1565040,54,23,57,14,'Nebo řečeno bude: Vyrovnejte, vyrovnejte, spravte cestu, odkliďte překážky z cesty lidu mého.'),
(1565041,54,23,57,15,'Nebo takto dí ten důstojný a vyvýšený, kterýž u věčnosti přebývá, jehož jméno jest Svatý: Na výsosti a v místě svatém bydlím, ano i s tím, kterýž jest skroušeného a poníženého ducha přebývám, obživuje ducha ponížených, obživuje také srdce skroušených.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565042,54,23,57,16,'Nebuduť se zajisté na věky nesnadniti, aniž se budu věčně hněvati, neboť by duch před oblíčejem mým zmizel, i dchnutí, kteréž jsem já učinil.'),
(1565043,54,23,57,17,'Pro nepravost lakomství jeho rozhněval jsem se, a ubil jsem jej; skryl jsem se a rozhněval proto, že odvrátiv se, odšel cestou srdce svého.'),
(1565044,54,23,57,18,'Vidím cesty jeho, a však uzdravím jej; zprovodím jej, a jemu potěšení navrátím, i těm, kteříž kvílí s ním.'),
(1565045,54,23,57,19,'Stvořím ovoce rtů, hojný pokoj, dalekému jako blízkému, praví Hospodin, a tak uzdravím jej.'),
(1565046,54,23,57,20,'Bezbožní pak budou jako moře zbouřené, když se spokojiti nemůže, a jehož vody vymítají nečistotu a bláto.'),
(1565047,54,23,57,21,'Nemajíť žádného pokoje, praví Bůh můj, bezbožní.'),
(1565048,54,23,58,1,'Volej vším hrdlem, nezadržuj, jako trouba povýš hlasu svého, a oznam lidu mému převrácenost jejich, a domu Jákobovu hříchy jejich.'),
(1565049,54,23,58,2,'Jakkoli každého dne mne hledají, a znáti cesty mé jsou chtiví, jako by byli národ, kterýž spravedlnost činí, a soudu Boha svého neopouští. Dotazují se mne na soudy spravedlnosti, blízcí Boha býti chtějí,'),
(1565050,54,23,58,3,'A říkají: Proč se postíváme, poněvadž nepatříš? Trápíváme duše své, a nechceš věděti o tom? Aj, v den postu vašeho líbost provodíte, a ke všem robotám svým přísně doháníte.'),
(1565051,54,23,58,4,'Aj, k sváru a různici se postíváte, a abyste bili pěstí nemilostivě; nepostíte se tak dnů těch, aby slyšán byl na výsosti hlas váš.'),
(1565052,54,23,58,5,'Zdaliž to jest takový půst, jakýž oblibuji, a den, v němž by trápil člověk duši svou? Zdali, aby svěsil jako třtina hlavu svou, a podstíral žíni a popel? To-liž nazůveš postem a dnem vzácným Hospodinu?'),
(1565053,54,23,58,6,'Není-liž toto půst, kterýž oblibuji: Rozvázati svazky bezbožnosti; roztrhnouti snopky obtěžující, a potřené propustiti svobodné, a tak všelijaké jho abyste roztrhli?'),
(1565054,54,23,58,7,'Není-liž: Abys lámal lačnému chléb svůj, a chudé vypověděné abys uvedl do domu? Viděl-li bys nahého, abys jej přioděl, a před tělem svým abys se neskrýval.'),
(1565055,54,23,58,8,'Tehdáž se vyrazí jako jitřní záře světlo tvé, a zdraví tvé rychle zkvetne; předcházeti tě zajisté bude spravedlnost tvá, a sláva Hospodinova zbéře tě.'),
(1565056,54,23,58,9,'Tehdy volati budeš, a Hospodin vyslyší tě; zavoláš, a řekneť: Teď jsem. Jestliže vyvržeš z prostřed sebe jho, a vztahování prstů, a mluvení nepravostí,'),
(1565057,54,23,58,10,'A vyleješ-li lačnému duši svou, a strápenou duši nasytíš-li: vzejde v temnostech světlo tvé, a mrákota tvá bude jako poledne.'),
(1565058,54,23,58,11,'Nebo povede tě Hospodin ustavičně, a nasytí i v náramné sucho duši tvou, a kosti tvé tukem naplní. I budeš jako zahrada svlažená, a jako pramen vod, jehož vody nevysychají.'),
(1565059,54,23,58,12,'A vzdělají od tebe zplození pustiny starodávní; základy od národu do pronárodu vyzdvihneš. I slouti budeš vzdělavatel zbořeniny, a napravovatel stezek k bydlení.'),
(1565060,54,23,58,13,'Jestliže odvrátíš od soboty nohu svou, abys nevykonával líbosti své v den svatý můj, anobrž nazůveš-li sobotu rozkoší, a svatou Hospodinu slavnou, a budeš-li ji slaviti tak, abys nečinil cest svých, ani vykonával, co by se líbilo, ani nemluvil slova:'),
(1565061,54,23,58,14,'Tehdy rozkoš míti budeš v Hospodinu, a uvedu tě na vysoká místa země, a způsobím to, abys užíval dědictví Jákoba otce svého; nebo ústa Hospodinova mluvila.'),
(1565062,54,23,59,1,'Aj, neníť ukrácena ruka Hospodinova, aby nemohla zachovati, aniž jest obtíženo ucho jeho, aby nemohlo slyšeti.'),
(1565063,54,23,59,2,'Ale nepravosti vaše rozloučily vás s Bohem vaším, a hříchové vaši to způsobili, že skryl tvář před vámi, aby neslyšel.'),
(1565064,54,23,59,3,'Nebo ruce vaše jsou poškvrněné krví, a prstové vaši nepravostí; rtové vaši mluví lež, jazyk váš vynáší převrácenost.'),
(1565065,54,23,59,4,'Není žádného, ješto by se zasadil o spravedlnost, aniž jest kdo, ješto by zastával pravdy. Doufají v marnost, a mluví daremné věci; počínají nátisk, a rodí nepravost.'),
(1565066,54,23,59,5,'Vejce bazališková vyseděli, a plátna pavoukového natkali. Kdož by jedl vejce jejich, umře; pakli je roztlačí, vynikne ještěrka.'),
(1565067,54,23,59,6,'Plátna jejich nehodí se na roucho, aniž se odějí dílem svým; skutkové jejich skutkové nepravosti, a dílo ukrutnosti jest v rukou jejich.'),
(1565068,54,23,59,7,'Nohy jejich k zlému běží, a pospíchají k vylévání krve nevinné. Myšlení jejich jsou myšlení nepravá, zpuštění a setření jest na cestách jejich.'),
(1565069,54,23,59,8,'Cesty pokoje neznají, a není žádné spravedlnosti v šlepějích jejich. Stezky své převracejí tajně; kdožkoli po nich chodí, nemívá pokoje.'),
(1565070,54,23,59,9,'Protož vzdálil se od nás soud, a nedochází nás spravedlnost. Čekáme-li na světlo, aj, tma, pakli na blesk, v mrákotách chodíme.'),
(1565071,54,23,59,10,'Makáme jako slepí stěnu, a jako bychom žádných očí neměli, šámáme. Urážíme se o poledni jako v soumrak, u veliké hojnosti podobni jsme mrtvým.'),
(1565072,54,23,59,11,'Mumleme všickni my jako nedvědi, a jako holubice ustavičně lkáme. Očekáváme na soud, ale není ho, na vysvobození, ale daleké jest od nás.'),
(1565073,54,23,59,12,'Nebo rozmnožena jsou přestoupení naše před tebou, a hříchové naši svědčí proti nám, poněvadž přestoupení naše jsou při nás, i nepravosti naše. Známeť to,'),
(1565074,54,23,59,13,'Že jsme se zpronevěřili, a lhali Hospodinu, a odvrátili se od následování Boha svého, že jsme mluvili o nátisku a odvrácení, že jsme ukládali a vynášeli z srdce slova lživá,'),
(1565075,54,23,59,14,'Tak že odvrácen jest nazpět soud, a spravedlnost zdaleka stojí; nebo klesla na ulici pravda, a pravost nemá průchodu.'),
(1565076,54,23,59,15,'Nýbrž zhynula pravda, a ten, kdož se uchyluje od zlého, loupeži bývá vydán; což vidí Hospodin, a nelíbí se to jemu, že není žádného soudu.'),
(1565077,54,23,59,16,'Když tedy viděl, že není žádného muže, až se užasl, že není žádného prostředníka. A protož vysvobození jemu způsobilo rámě jeho, a spravedlnost jeho sama jej zpodepřela.'),
(1565078,54,23,59,17,'Nebo oblékl spravedlnost jako pancíř, a lebka spasení na hlavě jeho. Oblékl se v roucho pomsty jako v sukni, a oděl se horlivostí jako pláštěm,'),
(1565079,54,23,59,18,'Aby podlé skutků, aby podlé nich odplacel prchlivostí protivníkům svým, odměnu nepřátelům svým, i ostrovům odplatu aby dával.'),
(1565080,54,23,59,19,'I budou se báti na západ jména Hospodinova, a na východu slunce slávy jeho, když se přivalí jako řeka nepřítel, jejž duch Hospodinův preč zažene.'),
(1565081,54,23,59,20,'Neboť přijde k Sionu vykupitel, a k těm, kteříž se odvracují od přestoupení v Jákobovi, praví Hospodin.'),
(1565082,54,23,59,21,'Tatoť pak bude smlouva má s nimi, praví Hospodin: Duch můj, kterýž jest v tobě, a slova má, kteráž jsem vložil v ústa tvá, neodejdouť od úst tvých, ani od úst semene tvého, ani od úst potomků semene tvého, praví Hospodin, od tohoto času až na věky.'),
(1565083,54,23,60,1,'Povstaniž, zastkvěj se, poněvadž přišlo světlo tvé, a sláva Hospodinova vzešla nad tebou.'),
(1565084,54,23,60,2,'Nebo aj, tmy přikryjí zemi, a mrákota národy, ale nad tebou vzejde Hospodin, a sláva jeho nad tebou vidína bude.'),
(1565085,54,23,60,3,'I budou choditi národové v světle tvém, a králové v blesku, jenž vzejde nad tebou.'),
(1565086,54,23,60,4,'Pozdvihni vůkol očí svých, a popatř. Všickni tito shromáždíce se, k tobě se poberou, synové tvoji zdaleka přijdou, a dcery tvé při boku tvém chovány budou.'),
(1565087,54,23,60,5,'Tehdáž uzříš to, a rozveselíš se, tehdáž podiví se, a rozšíří se srdce tvé; nebo se obrátí k tobě množství mořské, síla pohanů přijde k tobě.'),
(1565088,54,23,60,6,'Stádo velbloudů přikryje tě, a dromedáři Madianští a Efejští, všickni ti z Sáby přijdou, zlato a kadidlo přinesou, a chvály Hospodinovy zvěstovati budou.'),
(1565089,54,23,60,7,'Všecka stáda Cedarská shromáždí se k tobě, skopcové Nabajotští přisluhovati budou tobě, a obětováni jsouce na mém oltáři, příjemní budou. A takť dům okrasy své ozdobím.'),
(1565090,54,23,60,8,'I díš: Kdo jsou ti, kteříž se jako hustý oblak sletují, a jako holubice k děrám svým?'),
(1565091,54,23,60,9,'Na mneť zajisté ostrovové očekávají, a lodí mořské hned zdávna, aby přivedli syny tvé zdaleka, též stříbro své a zlato své s sebou, k slávě Hospodina, Boha tvého a Svatého Izraelského; nebo tě oslaví.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565092,54,23,60,10,'I vystavějí cizozemci zdi tvé, a králové jejich přisluhovati budou tobě, když v prchlivosti své ubiji tě, a v dobré líbeznosti své slituji se nad tebou.'),
(1565093,54,23,60,11,'A otevříny budou brány tvé ustavičně, ve dne ani v noci nebudou zavírány, aby přivedli k tobě sílu pohanů, i králové jejich aby přivedeni byli.'),
(1565094,54,23,60,12,'Národ zajisté ten a království, kteréž by nesloužilo tobě, zahyne; národové, pravím, ti docela pohubeni budou.'),
(1565095,54,23,60,13,'Sláva Libánská přijde k tobě, jedle, jilm, též i pušpan k ozdobě místa svatyně mé, abych místo noh svých oslavil.'),
(1565096,54,23,60,14,'Také přijdou k tobě s ponížením synové těch, kteříž tě trápili, a klaněti se budou k zpodku noh tvých, kteřížkoli pohrdali tebou, a nazývati tě budou městem Hospodinovým, Sionem Svatého Izraelského.'),
(1565097,54,23,60,15,'Místo toho, že jsi byla opuštěná a v nenávisti, tak že žádný skrze tě nechodil, způsobímť důstojnost věčnou, a veselí od národu do pronárodu.'),
(1565098,54,23,60,16,'Nebo ssáti budeš mléko národů, a prsy králů ssáti budeš; i poznáš, že jsem já Hospodin vysvoboditel tvůj, a vykupitel tvůj silný Jákobův.'),
(1565099,54,23,60,17,'Místo mědi dodávati budu zlata, a místo železa dodávati budu stříbra, a místo dříví mědi, a místo kamení železa, a představímť správce pokojné a úředníky spravedlivé.'),
(1565100,54,23,60,18,'Nebude více slyšáno o bezpraví v zemi tvé, o zpuštění a zhoubě na hranicích tvých, ale hlásati budeš spasení na zdech svých, a v branách svých chválu.'),
(1565101,54,23,60,19,'Nebudeš míti více slunce za světlo denní, a blesk měsíce nebude tě osvěcovati, ale budeť Hospodin světlem tvým věčným, a Bůh tvůj okrasou tvou.'),
(1565102,54,23,60,20,'Nezajdeť více slunce tvé, a měsíc tvůj neschová se, nebo Hospodin bude světlem tvým věčným, a tak dokonáni budou dnové smutku tvého.'),
(1565103,54,23,60,21,'Lid také tvůj, kteříž by koli byli spravedliví, na věky dědičně obdrží zemi, výstřelek štípení mého, dílo rukou mých, abych v něm oslavován byl.'),
(1565104,54,23,60,22,'Samotný rozmnoží se v tisíce, a nejšpatnější v národ nesčíslný, já Hospodin časem svým brzo způsobím to.'),
(1565105,54,23,61,1,'Duch Panovníka Hospodina jest nade mnou, proto že pomazal mne Hospodin, abych kázal evangelium tichým. Poslal mne, abych uvázal rány skroušených srdcem, abych vyhlásil jatým svobodu, a vězňům otevření žaláře,'),
(1565106,54,23,61,2,'Abych vyhlásil léto milostivé Hospodinovo, a den pomsty Boha našeho, abych těšil všecky kvílící,'),
(1565107,54,23,61,3,'Abych způsobil radost kvílícím Sionským, a dal jim okrasu místo popela, olej veselé místo smutku, oděv chvály místo ducha sevřeného. I nazvání budou stromové spravedlnosti, štípení Hospodinovo, abych oslavován byl.'),
(1565108,54,23,61,4,'Tedy vzdělají pustiny starodávní, pouště staré spraví, a obnoví města zpuštěná, pustá po mnohé národy.'),
(1565109,54,23,61,5,'Nebo postaví se cizozemci, a pásti budou stáda vaše, a synové cizozemců oráči vaši a vinaři vaši budou.'),
(1565110,54,23,61,6,'Vy pak kněží Hospodinovi nazváni budete, služebníci Boha našeho slouti budete, zboží pohanů užívati budete, a v slávě jejich zvýšeni budete.'),
(1565111,54,23,61,7,'Za dvojnásobní zahanbení vaše a pohanění prozpěvovati budete, z podílu jejich a v zemi jejich dvojnásobní dědictví obdržíte, a tak veselé věčné míti budete.'),
(1565112,54,23,61,8,'Já zajisté Hospodin miluji soud, a nenávidím loupeže při oběti, a protož způsobím, aby skutkové jejich dáli se v pravdě, a smlouvu věčnou s nimi učiním.'),
(1565113,54,23,61,9,'I vejdeť v známost mezi pohany símě jejich, a potomci jejich u prostřed národů. Všickni, kteříž je uzří, poznají je, že jsou símě, jemuž požehnal Hospodin.'),
(1565114,54,23,61,10,'Velice se budu radovati v Hospodinu, a plésati bude duše má v Bohu mém; nebo mne oblékl v roucho spasení, a pláštěm spravedlnosti přioděl mne jako ženicha, kterýž se strojí ozdobně, a jako nevěstu okrašlující se ozdobami svými.'),
(1565115,54,23,61,11,'Nebo jakož země vydává zrostlinu svou, a jakož zahrada símě své vyvodí, tak Panovník Hospodin vyvede spravedlnost a chválu přede všemi národy.'),
(1565116,54,23,62,1,'Pro Sion nebudu mlčeti, a pro Jeruzalém neupokojím se, dokudž nevyjde jako blesk spravedlnost jeho, a spasení jeho jako pochodně hořeti nebude.'),
(1565117,54,23,62,2,'I uzří národové spravedlnost tvou, a všickni králové slávu tvou, a nazovou tě jménem novým, kteréž ústa Hospodinova vyřknou.'),
(1565118,54,23,62,3,'Nadto budeš korunou ozdobnou v ruce Hospodinově, a korunou královskou v ruce Boha svého.'),
(1565119,54,23,62,4,'Nebudeš více slouti opuštěná, a země tvá nebude více slouti pustinou, ale ty nazývána budeš rozkoší, a země tvá vdanou; nebo rozkoš míti bude Hospodin v tobě, a země tvá bude vdaná.'),
(1565120,54,23,62,5,'Nebo jakož pojímá mládenec pannu, tak tě sobě pojmou synové tvoji, a jakou má radost ženich z nevěsty, tak radovati se bude z tebe Bůh tvůj.'),
(1565121,54,23,62,6,'Na zdech tvých, Jeruzaléme, postavím strážné, kteříž přes celý den i přes celou noc nikdy nebudou mlčeti. Kteříž tedy připomínáte Hospodina, nemlčtež,'),
(1565122,54,23,62,7,'A nedávejte jemu pokoje, dokudž neutvrdí, a dokudž nezpůsobí, aby Jeruzalém byl slavný na zemi.'),
(1565123,54,23,62,8,'Přisáhltě Hospodin skrze pravici svou, a skrze rámě síly své, řka: Nikoli nedám obilí tvého více za pokrm nepřátelům tvým, aniž píti budou cizozemci vína tvého, o němž jsi pracoval.'),
(1565124,54,23,62,9,'Ale ti, kteříž je shromažďují, budou je jísti, a chváliti Hospodina, a kteříž je zbírají, budou je píti v síňcích svatosti mé.'),
(1565125,54,23,62,10,'Vejdětež, vejdětež branami, spravte cestu lidu, vyrovnejte, vyrovnejte silnici, vybeřte kamení, vyzdvihněte korouhev k národům.'),
(1565126,54,23,62,11,'Aj, Hospodin rozkáže provolati až do končin země: Rcetež dceři Sionské: Aj, Spasitel tvůj béře se, aj, mzda jeho s ním, a dílo jeho před ním.'),
(1565127,54,23,62,12,'I nazovou syny tvé lidem svatým, vykoupenými Hospodinovými, ty pak slouti budeš městem vzácným a neopuštěným.'),
(1565128,54,23,63,1,'Kdož jest to, ješto se béře z Edom, v ubroceném rouše z Bozra, ten ozdobený rouchem svým, kráčeje u velikosti síly své? Jáť jsem, kterýž mluvím spravedlivě, dostatečný k vysvobození.'),
(1565129,54,23,63,2,'Proč jest červené roucho tvé, a oděv tvůj jako toho, kterýž tlačí v presu?'),
(1565130,54,23,63,3,'Pres jsem tlačil sám, aniž kdo z lidí byl se mnou. Tlačil jsem nepřátely v hněvě svém, a pošlapal jsem je v prchlivosti své, až stříkala krev i nejsilnějších jejich na roucho mé, a tak všecken oděv svůj zkálel jsem.'),
(1565131,54,23,63,4,'Den zajisté pomsty v srdci mém, a léto, v němž mají vykoupeni býti moji, přišlo.'),
(1565132,54,23,63,5,'Když jsem pak viděl, že není žádného spomocníka, až jsem se užasl, že žádného nebylo, kdo by podpíral. A protož mi vysvobození způsobilo rámě mé, a prchlivost má, ta mne podepřela.'),
(1565133,54,23,63,6,'I pošlapal jsem národy v hněvě svém, a opojil jsem je prchlivostí svou, a porazil jsem na zem nejsilnější reky jejich.'),
(1565134,54,23,63,7,'Milosrdenství Hospodinova připomínati budu, a chvály Hospodinovy ze všeho, což učinil nám Hospodin, i množství dobroty, kteréž dokazoval k domu Izraelskému z veliké lítosti své, a z velikého milosrdenství svého.'),
(1565135,54,23,63,8,'Nebo řekl: Vždyť jsou lidem mým, jsou synové, neučiníť mi nevěrně. A protož byl jejich spasitelem.'),
(1565136,54,23,63,9,'Ve všelikém ssoužení jejich i on měl ssoužení, a anděl přístojící jemu vysvobozval je. Z milování svého a z lítosti své on sám vykoupil je, a pěstoval je, i nosil je po všecky dny věků.'),
(1565137,54,23,63,10,'Ale oni zpurní byli, a zarmucovali Ducha svatého jeho; pročež obrátil se jim v nepřítele, a sám bojoval proti nim.'),
(1565138,54,23,63,11,'I rozpomínal se lid jeho na dny starodávní, i na Mojžíše: Kdež jest ten, kterýž je vyvedl z moře s pastýřem stáda svého? Kde jest ten, kterýž položil u prostřed něho Ducha svatého svého?'),
(1565139,54,23,63,12,'Kterýž je vedl ramenem velebnosti své po pravici Mojžíšově, kterýž rozdělil vody před nimi, aby sobě způsobil jméno věčné,'),
(1565140,54,23,63,13,'Kterýž je provedl skrze hlubiny jako koně po poušti, ani se nepoklesli.'),
(1565141,54,23,63,14,'Jako když hovádko do údolí sstupuje,tak Duch Hospodinův poznenáhlu vedl z nich každého. Tak jsi vedl lid svůj, abys sobě způsobil jméno slavné.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565142,54,23,63,15,'Popatřiž s nebe, a pohleď z příbytku svatosti své a okrasy své. Kdež jest horlivost tvá a veliká síla tvá? Kde množství milosrdenství tvých a slitování tvých? Mně-liž se zadržovati budou?'),
(1565143,54,23,63,16,'Ty jsi zajisté otec náš; nebo Abraham nic neví o nás, a Izrael nezná nás. Ty jsi, Hospodine, otec náš, vykupitel náš, toť jest od věčnosti jméno tvé.'),
(1565144,54,23,63,17,'Pročež jsi nám dal zblouditi, Hospodine, od cest svých, zatvrdil jsi srdce naše, abychom se nebáli tebe? Navratiž se zase pro služebníky své, pokolení dědictví svého.'),
(1565145,54,23,63,18,'Nejšpatnější vládne lidem svatosti tvé, nepřátelé naši pošlapali svatyni tvou.'),
(1565146,54,23,63,19,'My tvoji jsme od věků; nad nimi jsi nikdy nepanoval, aniž nad nimi jméno tvé vzýváno jest.'),
(1565147,54,23,64,1,'Ó bys protrhl nebesa a sstoupil, aby se od přítomnosti tvé hory rozplynouti musily,'),
(1565148,54,23,64,2,'(Jako od rozníceného ohně rozpouštějícího voda vře), abys v známost uvedl jméno své nepřátelům svým, a aby se před tváří tvou národové třásli;'),
(1565149,54,23,64,3,'Jako když jsi činil hrozné věci, jichž jsme se nenadáli, sstoupil jsi, před oblíčejem tvým hory se rozplývaly;'),
(1565150,54,23,64,4,'Čehož se od věků neslýchalo, a ušima nepochopilo, oko nevídalo Boha kromě tebe, aby tak činil tomu, kterýž naň očekává.'),
(1565151,54,23,64,5,'Vyšel jsi vstříc tomu, kdož ochotně činí spravedlnost, a na cestách tvých na tě se rozpomínali. Aj, ty rozhněvals se, proto že jsme hřešili na nich ustavičně, a však zachováni budeme,'),
(1565152,54,23,64,6,'Ačkoli jsme jako nečistý my všickni, a jako roucho ohyzdné všecky spravedlnosti naše. Pročež pršíme jako list my všickni, a nepravosti naše jako vítr zachvacují nás.'),
(1565153,54,23,64,7,'Nadto není žádného, ješto by vzýval jméno tvé, a probudil se k tomu, aby se chopil tebe, aspoň když jsi skryl tvář svou před námi, a způsobil to, abychom mizeli pro nepravosti naše.'),
(1565154,54,23,64,8,'Ale již, ó Hospodine, ty jsi otec náš, my hlina, ty pak učinitel náš, a tak jsme všickni dílo ruky tvé.'),
(1565155,54,23,64,9,'Nehněvejž se tak velmi, Hospodine, aniž se na věky rozpomínej na nepravost. Ó vzhlédniž, prosíme, všickni my lid tvůj jsme.'),
(1565156,54,23,64,10,'Města svatosti tvé obrácena jsou v poušť, Sion v poušť, i Jeruzalém v pustinu obrácen.'),
(1565157,54,23,64,11,'Dům svatosti naší a okrasy naší, v kterémž tě chválívali otcové naši, ohněm zkažen, a cožkoli jsme měli nejvzácnějšího, jest popléněno.'),
(1565158,54,23,64,12,'I zdaliž pro ty věci, Hospodine, se zdržíš? Mlčeti a nás tak velmi trápiti budeš?'),
(1565159,54,23,65,1,'Dal jsem se najíti těm, kteříž se na mne neptávali, nalezen jsem od těch, kteříž mne nehledali, a národu, kterýž se nenazýval jménem mým, řekl jsem: Teď jsem, teď jsem.'),
(1565160,54,23,65,2,'Rozprostíral jsem ruce své na každý den k lidu zpurnému, kteříž chodí cestou nedobrou za myšlénkami svými,'),
(1565161,54,23,65,3,'K lidu, kteříž zjevně popouzejí mne ustavičně, obětujíce v zahradách, a kadíce na cihlách,'),
(1565162,54,23,65,4,'Kteříž sedají při hrobích, a při svých modlách nocují, kteříž jedí maso sviňské, a polívku nečistého z nádob svých,'),
(1565163,54,23,65,5,'Říkajíce: Táhni preč, nepřistupuj ke mně, nebo světější jsem nežli ty. Tiť jsou dymem v chřípích mých a ohněm hořícím přes celý den.'),
(1565164,54,23,65,6,'Aj, zapsáno jest to přede mnou: Nebuduť mlčeti, nýbrž nahradím a odplatím do lůna jejich,'),
(1565165,54,23,65,7,'Za nepravosti vaše, a spolu za nepravosti otců vašich, praví Hospodin, kteříž kadívali na horách, a na pahrbcích v lehkost uvodili mne; pročež odměřím za dílo jejich předešlé do lůna jejich.'),
(1565166,54,23,65,8,'Takto praví Hospodin: Jako někdo nalezna víno v hroznu, i řekl by: Nekaz ho, proto že požehnání jest v něm, tak i já učiním pro služebníky své, že nevyhladím všech těchto.'),
(1565167,54,23,65,9,'Nebo vyvedu z Jákoba símě, a z Judy toho, kterýž by dědičně obdržel hory mé, i budou ji dědičně držeti vyvolení moji, a služebníci moji bydliti budou tam.'),
(1565168,54,23,65,10,'Lid pak můj, kteříž by mne hledali,budou míti Sáron za pastviště ovcím, a údolí Achor za odpočivadlo skotům.'),
(1565169,54,23,65,11,'Ale vás, kteříž opouštíte Hospodina, kteříž se zapomínáte na horu svatosti mé, kteříž strojíte vojsku tomu stůl, a kteříž vykonáváte tomu počtu oběti,'),
(1565170,54,23,65,12,'Vás, pravím, sečtu pod meč, tak že všickni vy k zabití na kolena padati budete, proto že, když jsem volal, neohlásili jste se, mluvil jsem, a neslyšeli jste, ale činili jste to, což zlého jest před očima mýma, a to, čehož neoblibuji, vyvolili jste.'),
(1565171,54,23,65,13,'A protož takto dí Panovník Hospodin: Aj, služebníci moji jísti budou, vy pak hlad trpěti budete: aj, služebníci moji píti budou, vy pak žízniti budete; aj, služebníci moji veseliti se budou, vy pak zahanbeni budete.'),
(1565172,54,23,65,14,'Aj, služebníci moji prozpěvovati budou pro radost srdce, vy pak křičeti budete pro bolest srdce, a pro setření ducha kvíliti budete,'),
(1565173,54,23,65,15,'A zanecháte jména svého k proklínání vyvoleným mým, když vás pomorduje Panovník Hospodin, služebníky pak své nazůve jménem jiným.'),
(1565174,54,23,65,16,'Ten, kterýž bude sobě požehnání dávati na zemi, požehnání dávati sobě bude v Bohu pravém, a kdož přisahati bude na zemi, přisahati bude skrze Boha pravého; v zapomenutí zajisté dána budou ta ssoužení první, a budou skryta od očí mých.'),
(1565175,54,23,65,17,'Nebo aj, já stvořím nebesa nová a zemi novou, a nebudou připomínány první věci, aniž vstoupí na srdce.'),
(1565176,54,23,65,18,'Anobrž radujte se a veselte se na věky věků z toho, což já stvořím; nebo aj, já stvořím Jeruzalém k plésání, a lid jeho k radosti.'),
(1565177,54,23,65,19,'I já plésati budu v Jeruzalémě, a radovati se v lidu svém, aniž se více bude slýchati v něm hlasu pláče, aneb hlasu křiku.'),
(1565178,54,23,65,20,'Nebude tam více žádného v věku dětinském, ani starce, kterýž by dnů svých nevyplnil; nebo dítě ve stu letech umře, hříšníku pak, by došel i sta let, zlořečeno bude.'),
(1565179,54,23,65,21,'Nastavějí též domů, a bydliti budou v nich, i vinice štěpovati budou, a jísti budou ovoce jejich.'),
(1565180,54,23,65,22,'Nebudou stavěti tak, aby jiný bydlil, nebudou štěpovati, aby jiný jedl; nebo jako dnové dřeva budou dnové lidu mého, a díla rukou svých do zvetšení užívati budou vyvolení moji.'),
(1565181,54,23,65,23,'Nebudouť pracovati nadarmo, aniž ploditi budou k strachu; nebo budou símě požehnaných od Hospodina, i potomkové jejich s nimi.'),
(1565182,54,23,65,24,'Nadto stane se, že prvé než volati budou, já se ohlásím; ještě mluviti budou, a já vyslyším.'),
(1565183,54,23,65,25,'Vlk s beránkem budou se pásti spolu, a lev jako vůl bude jísti plevy, hadu pak za pokrm bude prach. Neuškodíť, aniž zahubí na vší mé hoře svaté, praví Hospodin.'),
(1565184,54,23,66,1,'Takto praví Hospodin: Nebe jest mi stolice, a země podnože noh mých. Kdež ten dům bude, kterýž mi vzděláte? Aneb kde bude místo odpočívání mého?'),
(1565185,54,23,66,2,'Nebo všecko to ruka má učinila, a jí stojí všecko, praví Hospodin. I však na toho patřím, kdož jest chudý a skroušeného ducha, a třese se před slovem mým.'),
(1565186,54,23,66,3,'Sic jinak ten,kdož zabijí vola, zabil člověka; kdo zabijí hovádko, psa sťal; kdo obětuje obět suchou, krev sviňskou obětoval; kdo kadí kadidlem, dary dával modle. To oni vyvolili na cestách svých, proto že, v ohavnostech svých duše jejich se kochá.'),
(1565187,54,23,66,4,'I jáť také vyvolím za nešlechetnosti jejich, a to, čehož se strachují, na ně uvedu, proto že, když jsem volal, žádný se neohlásil, když jsem mluvil, neslyšeli, ale činili to, což zlého jest před očima mýma, a to, čehož neoblibuji, vyvolili.'),
(1565188,54,23,66,5,'Slyšte slovo Hospodinovo, kteříž se třesete před slovem jeho: Říkávají bratří vaši, v nenávisti majíce vás, a vypovídajíce vás pro jméno mé: Nechť se zjeví sláva Hospodinova. Ukážeť se zajisté ku potěšení vašemu, ale oni zahanbeni budou.'),
(1565189,54,23,66,6,'Hlas hřmotu z města, hlas z chrámu, hlas Hospodinův, an odplatu dává nepřátelům svým.'),
(1565190,54,23,66,7,'Prvé než pracovala ku porodu, porodila; prvé než přišla na ni bolest, porodila pacholátko.'),
(1565191,54,23,66,8,'Kdo slýchal co takového? Kdo vídal co podobného? Zdaliž může způsobeno býti, aby země zplodila lid dne jednoho? Zdaliž zplozen bývá národ pojednou? Ale Sion jen počal pracovati ku porodu, a porodil syny své.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565192,54,23,66,9,'Což bych já, kterýž otvírám život matky, neplodil? praví Hospodin. Což bych já, kterýž činím to, aby rodily, zavřín byl? praví Bůh tvůj.'),
(1565193,54,23,66,10,'Veselte se s Jeruzalémem, a plésejte v něm všickni, kteříž jej milujete. Radujte se s ním velice, kteříž jste koli kvílili nad ním,'),
(1565194,54,23,66,11,'Proto že ssáti budete, a sytiti se z prs potěšení jeho, ssáti budete, a rozkoš míti v blesku slávy jeho.'),
(1565195,54,23,66,12,'Nebo takto praví Hospodin: Aj, já obrátím na něj jako řeku pokoj, a jako potok rozvodnilý slávu národů. I budete ssáti, na rukou pěstováni a na klíně rozkošně chováni budete.'),
(1565196,54,23,66,13,'Jako ten, kteréhož matka jeho těší, tak já vás těšiti budu, a tak v Jeruzalémě potěšováni budete.'),
(1565197,54,23,66,14,'Uzříte zajisté, a radovati se bude srdce vaše, a kosti vaše jako bylinka zkvetnou. I seznána bude ruka Hospodinova při služebnících jeho, a prchlivost proti nepřátelům jeho.'),
(1565198,54,23,66,15,'Nebo aj, Hospodin v ohni přijde, a jako vichřice budou vozové jeho, aby vypustil v prchlivosti hněv svůj, a žehrání své v plameni ohně.'),
(1565199,54,23,66,16,'Hospodin, pravím, ohněm mstíti bude, a mečem svým nad všelikým tělem, tak že mnoho bude zbitých od Hospodina.'),
(1565200,54,23,66,17,'I ti, kteříž se posvěcují a očišťují v zahradách, jeden po druhém zjevně, kteříž jedí maso sviňské, a věc ohavnou i myši, též konec vezmou, praví Hospodin.'),
(1565201,54,23,66,18,'Nebo já, když skutkové a myšlení jejich přijdou, shromáždím všecky národy a jazyky. I přijdou, a uzří slávu mou.'),
(1565202,54,23,66,19,'A položím na ně znamení, a pošli z nich, kteříž zachováni budou, k národům do Tarsu, Pul a Lud, jenž natahují lučiště, do Tubal a Javan, na ostrovy daleké, kteříž neslýchali pověsti o mně, aniž vídali slávy mé. I budou zvěstovati slávu mou mezi národy.'),
(1565203,54,23,66,20,'A přivedou všecky bratří vaše ze všech národů za dar Hospodinu, na koních a na vozích, a na nůších a na mezcích, a na dromedářích, na horu svatosti mé do Jeruzaléma, praví Hospodin, tak jako přinášejí synové Izraelští dar v nádobě čisté do domu Hospodinova.'),
(1565204,54,23,66,21,'A z těchť také vezmu za kněží a za Levíty, praví Hospodin.'),
(1565205,54,23,66,22,'Nebo jakož ta nebesa nová, a země ta nová, kterouž já učiním, stane přede mnou, praví Hospodin, tak stane símě vaše a jméno vaše.'),
(1565206,54,23,66,23,'I stane se, že od novměsíce do novměsíce, od soboty do soboty přicházeti bude všeliké tělo, aby se klanělo přede mnou, praví Hospodin.'),
(1565207,54,23,66,24,'A vyjdouce, uzří těla mrtvá lidí těch, kteříž se mi zpronevěřili; nebo červ jejich neumře, a oheň jejich neuhasne. I budouť v ošklivosti všelikému tělu.'),
(1565208,54,24,1,1,'Slova Jeremiáše syna Helkiášova, z kněží, kteříž byli v Anatot, v zemi Beniamin,'),
(1565209,54,24,1,2,'K němuž se stalo slovo Hospodinovo za dnů Joziáše syna Amonova, krále Judského, třináctého léta kralování jeho.'),
(1565210,54,24,1,3,'Byl i za dnů Joakima syna Joziášova, krále Judského, až do vyplnění jedenáctého léta Sedechiáše syna Joziášova, krále Judského, až do zajetí Jeruzaléma měsíce pátého.'),
(1565211,54,24,1,4,'Stalo se, pravím, slovo Hospodinovo ke mně, řkoucí:'),
(1565212,54,24,1,5,'Dříve než jsem tě sformoval v životě, znal jsem tebe, a dříve nežlis vyšel z života, posvětil jsem tě, za proroka národům dal jsem tebe.'),
(1565213,54,24,1,6,'I řekl jsem: Ach, Panovníče Hospodine, aj, neumím mluviti, nebo dítě jsem.'),
(1565214,54,24,1,7,'Ale Hospodin řekl mi: Neříkej, dítě jsem, nýbrž k čemuž tě koli pošli, jdi, a vše, cožť přikáži, mluv.'),
(1565215,54,24,1,8,'Neboj se jich, neboť jsem s tebou, abych tě vysvobozoval, dí Hospodin.'),
(1565216,54,24,1,9,'A vztáhna ruku svou Hospodin, dotekl se úst mých, a řekl mi Hospodin: Aj, vložil jsem slova svá v ústa tvá.'),
(1565217,54,24,1,10,'Hle, ustanovuji tě dnešního dne nad národy a nad královstvími, abys plénil a kazil, a hubil a bořil, abys stavěl a štěpoval.'),
(1565218,54,24,1,11,'Potom se stalo slovo Hospodinovo ke mně, řkoucí: Co vidíš, Jeremiáši? I řekl jsem: Prut mandlový vidím.'),
(1565219,54,24,1,12,'Tedy řekl mi Hospodin: Dobře vidíš; nebo pospíchám já s slovem svým, abych je vykonal.'),
(1565220,54,24,1,13,'Opět stalo se slovo Hospodinovo ke mně po druhé, řkoucí: Co vidíš? I řekl jsem: Vidím hrnec, an vře, a přední strana jeho k straně půlnoční.'),
(1565221,54,24,1,14,'Tedy řekl mi Hospodin: Od půlnoci přivalí se to zlé na všecky obyvatele této země.'),
(1565222,54,24,1,15,'Nebo aj, já svolám všecky rodiny království půlnočních, dí Hospodin, aby přitáhnouce, postavili jeden každý stolici svou v branách Jeruzalémských, a při všech zdech jeho vůkol, a při všech městech Judských.'),
(1565223,54,24,1,16,'A tak vypovím úsudky své proti nim, pro všelikou nešlechetnost těch, kteříž opustili mne, a kadili bohům cizím, a skláněli se dílu rukou svých.'),
(1565224,54,24,1,17,'Protož ty přepaš bedra svá, a vstana, mluv k nim, cožkoli já přikazuji tobě. Nelekej se jich, abych tě nepotřel před oblíčejem jejich.'),
(1565225,54,24,1,18,'Nebo aj, já postavuji tě dnes jako město hrazené, a jako sloup železný, a jako zdi měděné proti vší této zemi, proti králům Judským, proti knížatům jejím, proti kněžím jejím, a lidu země této.'),
(1565226,54,24,1,19,'Kteříž bojovati budou proti tobě, ale neodolají proti tobě. Nebo já jsem s tebou, praví Hospodin, abych tě vysvobozoval.'),
(1565227,54,24,2,1,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1565228,54,24,2,2,'Jdi a volej, tak aby slyšel Jeruzalém, řka: Takto praví Hospodin: Rozpomínám se na tě pro milosrdenství mladosti tvé, a pro lásku snětí tvého, když jsi za mnou chodila po poušti v zemi, kteráž nebývá osívána.'),
(1565229,54,24,2,3,'Tehdáž svatost Hospodinova byl Izrael, prvotiny úrod jeho. Všickni, kteříž jej zžírali, obviněni byli; zlé věci na ně přišly, praví Hospodin.'),
(1565230,54,24,2,4,'Slyšte slovo Hospodinovo, dome Jákobův, a všecky čeledi domu Izraelského.'),
(1565231,54,24,2,5,'Takto praví Hospodin: Jakou shledali otcové vaši při mně nepravost, že se vzdálili ode mne, a chodíce za marností, marní učiněni jsou,'),
(1565232,54,24,2,6,'Tak že ani neřekli: Kde jest Hospodin, kterýž nás vyvedl z země Egyptské, kterýž nás vodil po poušti, po zemi pusté a strašlivé, po zemi vyprahlé a stínu smrti, po zemi, skrze niž nechodil žádný, a kdež žádný člověk nebydlil?'),
(1565233,54,24,2,7,'Nýbrž, když jsem vás uvedl do země úrodné, abyste jedli ovoce její i dobré věci její, všedše tam, poškvrnili jste země mé, a dědictví mé zohavili jste.'),
(1565234,54,24,2,8,'Kněží neřekli: Kde jest Hospodin? a ti, kteříž se obírají s zákonem, nepoznali mne, pastýři pak odstoupili ode mne, a proroci prorokovali skrze Bále, a za věcmi neužitečnými chodili.'),
(1565235,54,24,2,9,'Pročež vždy nesnáz mám s vámi, praví Hospodin, i s syny synů vašich nesnáz míti musím.'),
(1565236,54,24,2,10,'Projděte ale ostrovy Citim, a pohleďte, i do Cedar pošlete, a pošetřte pilně, a pohleďte, stalo-li se co takového.'),
(1565237,54,24,2,11,'Zdali změnil který národ bohy, ačkoli nejsou bohové? Lid pak můj změnil slávu svou v věc neužitečnou.'),
(1565238,54,24,2,12,'Užasněte se nebesa nad tím, a děste se, chřadněte velmi, praví Hospodin.'),
(1565239,54,24,2,13,'Nebo dvojí zlost spáchal lid můj: Mne opustili pramen vod živých, aby sobě vykopali čisterny, čisterny děravé, kteréž nedrží vody.'),
(1565240,54,24,2,14,'Zdali otrok jest Izrael? Zdali man doma zplozený? Pročež vydán jest v loupež?'),
(1565241,54,24,2,15,'Lvíčata řvou na něj, a vydávají hlas svůj, a obracejí zemi jeho v pustinu; města jeho vypálena jsou, tak že není žádného obyvatele.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565242,54,24,2,16,'Obyvatelé také Nof a Tachpanes pasou na vrchu hlavy tvé.'),
(1565243,54,24,2,17,'Zdaliž toho sobě nepůsobíš, opouštějíc Hospodina Boha svého v ten čas, když tě vodí po cestě své?'),
(1565244,54,24,2,18,'A nyní co tobě do cesty Egyptské, že piješ vodu z Níle? Aneb co tobě do cesty Assyrské, že piješ vodu z řeky?'),
(1565245,54,24,2,19,'Trestati tě bude zlost tvá, a odvrácení tvá domlouvati budou tobě. Poznejž tedy a viz, že zlá a hořká věc jest, že opouštíš Hospodina Boha svého, a není bázně mé při tobě, dí Panovník Hospodin zástupů.'),
(1565246,54,24,2,20,'Ačkoli dávno polámal jsem jho tvé, potrhal jsem to, čím jsi svázána byla, a řeklas: Nebuduť sloužiti modlám, však po každém pahrbku vysokém, a pod každým dřevem zeleným touláš se, ó nevěstko.'),
(1565247,54,24,2,21,'Ješto jsem já tě vysadil vinným kmenem výborným, všecku napořád semenem čistotným, i kterakž jsi mi proměnila se v plané réví cizího kmene?'),
(1565248,54,24,2,22,'Nebo bys ty se pak umyla sanitrem, a mnoho na sebe mýdla vypotřebovala, předceť patrná jest nepravost tvá před oblíčejem mým, praví Panovník Hospodin.'),
(1565249,54,24,2,23,'Kterakž můžeš říci: Nepoškvrňovala jsem se, za Báli jsem nechodila? Pohleď na cestu svou v tomto údolí, poznej, cos činila, dromedářko rychlá, kteráž znamení necháváš na cestách svých.'),
(1565250,54,24,2,24,'Jsi divoká oslice, zvyklá na poušti, kteráž podlé líbosti duše své hltá vítr, když se jí příčina dá. Kdo jí překážku učiní? Všickni ti, kteříž jí hledají, nepotřebí se jim kvaltovati, naleznouť ji v měsíci jejím.'),
(1565251,54,24,2,25,'Dí-liť kdo: Zdržuj nohu svou, aby bosá nebyla, a hrdlo své od žízně, tedy říkáš: To nic, nikoli; nebo jsem zamilovala cizí, a za nimi choditi budu.'),
(1565252,54,24,2,26,'Jakož k hanbě přichází zloděj, když postižen bývá, tak zahanben bude dům Izraelský, oni, králové jejich, knížata jejich, a kněží jejich, i proroci jejich,'),
(1565253,54,24,2,27,'Kteříž říkají dřevu: Otec můj jsi, a kameni: Ty jsi mne zplodil. Nebo se hřbetem ke mně obracejí a ne tváří, ale v čas trápení svého říkají: Vstaň a vysvoboď nás.'),
(1565254,54,24,2,28,'I kdež jsou bohové tvoji, kterýchž jsi nadělal sobě? Nechť vstanou, budou-li tě moci vysvoboditi v čas trápení tvého, poněvadž podlé počtu měst svých máš bohy své, ó Judo.'),
(1565255,54,24,2,29,'Co se vaditi budete se mnou? Vy všickni odstoupili jste ode mne, dí Hospodin.'),
(1565256,54,24,2,30,'Nadarmo jsem bil syny vaše, kázně nepřijali; sežral meč váš proroky vaše jako lev, kterýž dáví.'),
(1565257,54,24,2,31,'Ó národe, vy posuďte slova Hospodinova, zdali jsem byl pouští Izraelovi, zdali zemí tmavou? Proč říká lid můj: Panujeme, nepřijdeme více k tobě?'),
(1565258,54,24,2,32,'Zdali se zapomíná panna na ozdoby své, a nevěsta na tkanice své? Lid pak můj zapomněl se na mne za dny nesčíslné.'),
(1565259,54,24,2,33,'Proč zastáváš cesty své, hledajíc toho, což miluješ? Pročež i jiné nešlechetnice učíš cestám svým.'),
(1565260,54,24,2,34,'Nad to, na podolcích tvých nalézá se krev duší chudých nevinných. Nenesnadně nalézám to, nebo viděti to na těch všech podolcích.'),
(1565261,54,24,2,35,'A vždy říkáš: Poněvadž nevinná jsem, jistě odvrácena jest prchlivost jeho ode mne. Aj, já v soud vejdu s tebou, proto že pravíš: Nehřešila jsem.'),
(1565262,54,24,2,36,'Proč tak běháš, proměňujíc cestu svou? Jakož jsi zahanbena od Assyrských, tak i od Egyptských zahanbena budeš.'),
(1565263,54,24,2,37,'Také odtud vyjdeš, a ruce tvé budou nad hlavou tvou; nebo zamítá Hospodin troštování tvá, a nepovedeť se šťastně v nich.'),
(1565264,54,24,3,1,'Dí dále: Propustil-li by muž ženu svou, a ona odejduc od něho, vdala by se za jiného muže, zdaliž se navrátí k ní více? Zdaliž by hrozně nebyla poškvrněna země ta? Ale ty, ač jsi smilnila s milovníky mnohými, a však navratiž se ke mně, dí Hospodin.'),
(1565265,54,24,3,2,'Pozdvihni očí svých k vysokým místům, a pohleď, kdes necizoložila? Na cestách usazovalas se jim jako Arab na poušti, a poškvrnila jsi země smilstvím svým a nešlechetností svou.'),
(1565266,54,24,3,3,'A ačkoli zadržáni jsou podzimní dešťové, a deště jarního nebývalo, však čelo ženy nevěstky majíc, nechtělas se styděti.'),
(1565267,54,24,3,4,'Zdali od nynějšího času volati budeš ke mně: Otče můj, ty jsi vůdce mladosti mé?'),
(1565268,54,24,3,5,'Zdaliž Bůh držeti bude hněv na věčnost? Zdali chovati jej bude na věky? Aj, mluvíš i pášeš zlé věci, jakž jen můžeš.'),
(1565269,54,24,3,6,'Tedy řekl mi Hospodin za dnů Joziáše krále: Viděl-lis, co činila zpurná dcera Izraelská? Chodívala na každou horu vysokou, i pod každé dřevo zelené, a tam smilnila.'),
(1565270,54,24,3,7,'A ačkoli jsem řekl, když ty všecky věci ona činila: Nechť se navrátí ke mně, však se nenavrátila. Načež hleděla zpronevěřilá sestra její, dcera Judská.'),
(1565271,54,24,3,8,'Pročež vidělo mi se pro ty všecky příčiny, poněvadž cizoložila zpurná dcera Izraelská, propustiti ji, a dáti jí lístek zapuzení jejího. Však se vždy neulekla zpronevěřilá sestra její, dcera Judská, ale šedši, smilnila také sama.'),
(1565272,54,24,3,9,'I stalo se, že hanebným smilstvím svým poškvrnila země; nebo cizoložila s kamenem i s dřevem.'),
(1565273,54,24,3,10,'A však s tím se vším neobrátila se ke mně zpronevěřilá sestra její, dcera Judská, celým srdcem svým, ale pokrytě, praví Hospodin.'),
(1565274,54,24,3,11,'Protož řekl Hospodin ke mně: Ospravedlnila duši svou zpurná dcera Izraelská, více nežli zpronevěřilá Judská.'),
(1565275,54,24,3,12,'Jdi a volej slovy těmito ku půlnoci, a rci: Navrať se, zpurná dcero Izraelská, dí Hospodin, a neoboří se tvář má zůřivá na vás; nebo já dobrotivý jsem, dí Hospodin, aniž držím hněvu na věčnost.'),
(1565276,54,24,3,13,'Jen toliko poznej nepravost svou, že jsi od Hospodina Boha svého odstoupila, a sem i tam běhala cestami svými k cizím pod každé dřevo zelené, a hlasu mého neposlouchali jste, dí Hospodin.'),
(1565277,54,24,3,14,'Navraťte se synové zpurní, dí Hospodin; nebo já jsem manžel váš, a přijmu vás, jednoho z města, a dva z čeledi, abych vás uvedl na Sion.'),
(1565278,54,24,3,15,'Kdežto dám vám pastýře podlé srdce svého, kteříž pásti vás budou uměle a rozumně.'),
(1565279,54,24,3,16,'I stane se, když se rozmnožíte a rozplodíte v této zemi za dnů těch, dí Hospodin, že nebudou říkati více: Truhla smlouvy Hospodinovy, aniž jim vstoupí na srdce, aniž zpomenou na ni, ani k ní choditi, aniž bude více u vážnosti.'),
(1565280,54,24,3,17,'V ten čas nazývati budou Jeruzalém stolicí Hospodinovou, a shromáždí se tam všickni národové ke jménu Hospodinovu do Jeruzaléma, a nebudou choditi více podlé zdání srdce svého zlého.'),
(1565281,54,24,3,18,'V těch dnech přijdou dům Judský s domem Izraelským, a přiberou se spolu z země půlnoční do země, kterouž jsem v dědictví uvedl otcům vašim;'),
(1565282,54,24,3,19,'Ač já pravím: Kterakž bych tě počísti mohl mezi syny, a dáti tobě zemi žádostivou, dědictví slavné zástupů pohanských, leč abys mne vzýval, říkaje: Otče můj, a od následování mne abys se neodvracel?'),
(1565283,54,24,3,20,'Poněvadž jakož žena zpronevěřuje se manželu svému, tak jste se zpronevěřili mně, dome Izraelský, dí Hospodin.'),
(1565284,54,24,3,21,'Hlas po místech vysokých buď slyšán, pláč pokorné modlitby synů Izraelských. Nebo převrátivše cesty své, zapomněli se na Hospodina Boha svého, řkoucího:'),
(1565285,54,24,3,22,'Navraťte se, synové zpurní, a uzdravím odvrácení vaše. Rcete: Aj, my jdeme k tobě, nebo ty, Hospodine, jsi Bůh náš.'),
(1565286,54,24,3,23,'Právě marné jest v pahrbcích a v množství hor doufání; zajisté v Hospodinu Bohu našem jest spasení Izraelovo.'),
(1565287,54,24,3,24,'Nebo ohavnost ta zžírala práci otců našich od dětinství našeho, bravy jejich i skoty jejich, syny jejich i dcery jejich.'),
(1565288,54,24,3,25,'Ležíme v hanbě své, a přikrývá nás pohanění naše, že jsme proti Hospodinu Bohu svému hřešili, my i otcové naši, od dětinství svého až do dne tohoto, a neposlouchali jsme hlasu Hospodina Boha svého.'),
(1565289,54,24,4,1,'Budeš-li se míti navrátiti, Izraeli, dí Hospodin, ke mně se navrať. Nebo odejmeš-li ohavnosti své od tváři mé a nebudeš-li se toulati,'),
(1565290,54,24,4,2,'A budeš-li přisahati právě, náležitě a spravedlivě, říkaje: Živť jest Hospodin,tedy požehnání dávati sobě v něm budou národové, a v něm se chlubiti.'),
(1565291,54,24,4,3,'Nebo takto praví Hospodin mužům Judským a Jeruzalémským: Zořte sobě ouhor, a nerozsívejte do trní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565292,54,24,4,4,'Obřežte se Hospodinu, a odejměte neobřízky srdce vašeho, muži Judští a obyvatelé Jeruzalémští, aby nevyšla jako oheň prchlivost má, a nehořela, tak že by nebyl kdo uhasiti, pro nešlechetnost předsevzetí vašich.'),
(1565293,54,24,4,5,'Oznamte v Judstvu, a v Jeruzalémě ohlaste, a rcete: Trubte trubou v zemi, svolejte a sbeřte lid, a rcete: Shromažďte se, a vejděme do měst hrazených.'),
(1565294,54,24,4,6,'Vyzdvihněte korouhev na Sionu, zmužile se mějte, nepostávejte; nebo já zlé věci uvedu od půlnoci, a potření veliké.'),
(1565295,54,24,4,7,'Vychází lev z houště své, a ten, kterýž hubí národy, vyšed z místa svého, táhne, aby obrátil zemi tvou v pustinu, a města tvá aby zbořena byla, tak aby nebylo žádného obyvatele.'),
(1565296,54,24,4,8,'Protož přepašte se žíněmi, kvělte a naříkejte; nebo není odvrácen hněv prchlivosti Hospodinovy od nás.'),
(1565297,54,24,4,9,'Stane se zajisté v ten den, dí Hospodin, že zhyne srdce královo a srdce knížat, užasnou se i kněží, a proroci diviti se budou.'),
(1565298,54,24,4,10,'I řekl jsem: Ach, Panovníče Hospodine, jistě že jsi velice podvedl lid tento, i Jeruzalém, říkaje: Pokoj míti budete, a však pronikl meč až k duši.'),
(1565299,54,24,4,11,'V ten čas řečeno bude lidu tomuto i Jeruzalému: Vítr tuhý z míst vysokých na poušti jde upřímo na lid můj, ne aby převíval, ani přečišťoval.'),
(1565300,54,24,4,12,'Vítr silnější než oni přijde mi, nyní já také vypovím jim úsudky.'),
(1565301,54,24,4,13,'Aj, jako oblakové vystupuje, a jako vicher vozové jeho, rychlejší jsou nežli orlice koni jeho. Běda nám, nebo popléněni jsme.'),
(1565302,54,24,4,14,'Obmej od nešlechetnosti srdce své, Jeruzaléme, abys vysvobozen byl. Dokudž zůstávati budou u prostřed tebe myšlení marnosti tvé?'),
(1565303,54,24,4,15,'Nebo hlas oznamujícího přichází od Dan, a toho, kterýž ohlašuje nepravost, s hory Efraim.'),
(1565304,54,24,4,16,'Připomínejte těmto národům, aj, ohlašujte Jeruzalémským, že strážní táhnou z země daleké, a vydávají proti městům Judským hlas svůj.'),
(1565305,54,24,4,17,'Jako ti, kteříž hlídají polí, položí se proti němu vůkol; nebo jest mi odporný, dí Hospodin.'),
(1565306,54,24,4,18,'Cesta tvá a skutkové tvoji to způsobili tobě; toť nešlechetnost tvá, žeť to hořké jest, a že dosahá až do srdce tvého.'),
(1565307,54,24,4,19,'Ó, střeva má, střeva má, bolest trpím, ó osrdí mé, kormoutí se ve mně srdce mé, nemohuť mlčeti. Nebo hlas trouby slyšíš, duše má, a prokřikování vojenské.'),
(1565308,54,24,4,20,'Potření za potřením provolává se, popléněna zajisté bude všecka země, náhle popléněni budou stanové moji, v okamžení kortýny mé.'),
(1565309,54,24,4,21,'Až dokud vídati budu korouhev, slýchati hlas trouby?'),
(1565310,54,24,4,22,'Nebo bláznivý lid můj nezná mne, synové nemoudří a nerozumní jsou. Moudří jsou k činění zlého, ale činiti dobře neumějí.'),
(1565311,54,24,4,23,'Hledím-li na zemi, a aj, nesličná jest a prázdná; pakli na nebe, není na něm žádného světla.'),
(1565312,54,24,4,24,'Hledím-li na hory, a aj, třesou se, a všickni pahrbkové pohybují se.'),
(1565313,54,24,4,25,'Hledím-li, a aj, není žádného člověka, a všeliké ptactvo nebeské zaletělo.'),
(1565314,54,24,4,26,'Hledím-li, a aj, pole úrodné jest pouští, a všecka města jeho zbořena jsou od Hospodina a od hněvu prchlivosti jeho.'),
(1565315,54,24,4,27,'Nebo takto praví Hospodin: Spustne všecka země, a však konce ještě neučiním.'),
(1565316,54,24,4,28,'Kvíliti bude nad tím země, a zasmuší se na hoře nebe, proto že jsem mluvil, co jsem myslil, a nelituji, aniž se odvrátím od toho.'),
(1565317,54,24,4,29,'Před hřmotem jezdců a těch, kteříž střílejí z lučiště, uteče všecko město. Vejdou do hustých oblaků, a na skálí vylezou; všecka města opuštěna budou, a žádný nebude bydliti v nich.'),
(1565318,54,24,4,30,'Ty pak pohubena jsuc, což činiti budeš? Ačkoli obláčíš se v šarlat, ačkoli se ozdobuješ ozdobou zlatou, ačkoli líčíš tvář svou líčidlem, darmo se okrašluješ. Pohrdají tebou frejíři, bezživotí tvého hledají.'),
(1565319,54,24,4,31,'Nebo slyším hlas jako rodičky, svírání jako té, kteráž po nejprvé ku porodu pracuje, hlas dcery Sionské, ustavičně vzdychající, a lomící rukama svýma, říkající: Běda mně nyní, nebo ustala duše má pro vrahy.'),
(1565320,54,24,5,1,'Zběhejte ulice Jeruzalémské, pohleďte nyní, a zvězte, a hledejte v ulicích jeho, naleznete-li muže, jest-li kdo, ješto by činil soud, a vyhledával toho, což pravého jest, a odpustím jemu.'),
(1565321,54,24,5,2,'Ale i když říkají: Živť jest Hospodin, takovým způsobem křivě přisahají.'),
(1565322,54,24,5,3,'Ó Hospodine, zdaliž oči tvé nepatří na pravdu? Biješ je, ale necítí bolesti; hubíš je, ale nechtí přijímati kázně. Tvrdší jsou tváře jejich než skála, nechtí se navrátiti.'),
(1565323,54,24,5,4,'I řekl jsem já: Snad tito prostí jsou, nerozumně sobě počínají; nebo nejsou povědomi cesty Hospodinovy, soudu Boha svého.'),
(1565324,54,24,5,5,'Půjdu aspoň k přednějším, a mluviti budu k nim; nebo oni povědomi jsou cesty Hospodinovy, soudu Boha svého. Ale i ti spolu polámali jho, roztrhali svazky.'),
(1565325,54,24,5,6,'Protož je podáví lev z lesa, vlk večerní pohubí je, pardus číhati bude u měst jejich. Kdožkoli vyjde z nich, roztrhán bude; nebo mnohá jsou přestoupení jejich, rozmohly se převrácenosti jejich.'),
(1565326,54,24,5,7,'Kdež jest to, pročež bych měl odpustiti tobě? Synové tvoji opouštějí mne, a přisahají skrze ty, kteříž nejsou bohové. Jakž jsem jen nasytil je, hned cizoloží, a do domu nevěstky houfem se valí.'),
(1565327,54,24,5,8,'Ráno vstávajíce, jsou jako koni vytylí; každý k ženě bližního svého řehce.'),
(1565328,54,24,5,9,'Zdaliž pro takové věci nemám navštíviti? dí Hospodin. A zdali nad národem takovým nemá mstíti duše má?'),
(1565329,54,24,5,10,'Vstupte na zdi jeho, a zkazte je, a nepřestávejte; svrzte štítky zdí jeho, nebo nejsou Hospodinovy.'),
(1565330,54,24,5,11,'Velice zajisté zpronevěřili se mi dům Izraelský a dům Judský, dí Hospodin.'),
(1565331,54,24,5,12,'Sčítali klam na Hospodina, a říkali: Není tak, nikoli nepřijde na nás zlé, a meče ani hladu nepocítíme.'),
(1565332,54,24,5,13,'Ti pak proroci pominou s větrem, a žádného slova není v nich. Takť se stane jim.'),
(1565333,54,24,5,14,'Protož takto praví Hospodin Bůh zástupů: Proto že tak mluvíte, aj, já způsobím, aby slova tvá v ústech tvých byla jako oheň, a lid tento dřívím, kteréž on zžíře.'),
(1565334,54,24,5,15,'Aj, já přivedu na vás národ zdaleka, ó dome Izraelský, dí Hospodin, národ silný, národ starodávní, národ, jehož jazyka nebudeš uměti, ani rozuměti, co mluví.'),
(1565335,54,24,5,16,'Jehož toul jako hrob otevřený, všickni jsou silní.'),
(1565336,54,24,5,17,'A vytráví obilé tvé a chléb tvůj, požerou syny tvé a dcery tvé, pojí bravy tvé i skot tvůj, pojí vinné kmeny tvé i fíkoví tvé, města tvá hrazená, v nichž ty doufáš, znuzí mečem.'),
(1565337,54,24,5,18,'A však ani těch časů, dí Hospodin, neučiním s vámi konce.'),
(1565338,54,24,5,19,'Nebo stane se, když řeknete: Proč nám činí Hospodin Bůh náš všecko toto? že řekneš jim: Jakož jste opustili mne, a sloužili bohům cizozemců v zemi své, tak sloužiti budete cizozemcům v zemi ne své.'),
(1565339,54,24,5,20,'Oznamtež to v domě Jákobově, a rozhlaste v Judstvu, řkouce:'),
(1565340,54,24,5,21,'Slyštež nyní toto, lide bláznivý a nesmyslný, kteříž oči mají a nevidí, kteříž uši mají a neslyší:'),
(1565341,54,24,5,22,'Což se mne nebudete báti? dí Hospodin. Což před oblíčejem mým nebudete se třásti? Kterýž jsem položil písek za cíl moři ustanovením věčným, jehož nepřekračuje. Ačkoli zmítají se, však neodolají, ačkoli zvučí vlnobití jeho, však ho nepřecházejí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565342,54,24,5,23,'Ale lid tento má srdce zarputilé a zpurné, odstoupili a odešli.'),
(1565343,54,24,5,24,'Ani neřekli v srdci svém: Bojme se již Hospodina Boha našeho, kterýž dává déšť jarní i podzimní časem svým, téhodnů nařízených ke žni ostříhá nám.'),
(1565344,54,24,5,25,'Nepravostiť vaše překážku činí těm věcem, a hříchové vaši připravují vás o to dobré.'),
(1565345,54,24,5,26,'Nebo nalézají se v lidu mém bezbožníci; střeže jako čižebníci, kteříž lécejí, stavějí osídla, lidi lapají.'),
(1565346,54,24,5,27,'Jako klece plná ptáků, tak domové jejich plní jsou lsti. Protož zrostli a zbohatli,'),
(1565347,54,24,5,28,'Vytylí jsou, lsknou se, nadto umějí se vyhýbati bídám. Pře nesoudí, ani pře sirotka, a však šťastně se jim vede, ačkoli k spravedlnosti chudým nedopomáhají.'),
(1565348,54,24,5,29,'Zdaliž pro takové věci nemám navštíviti jich? dí Hospodin. Zdali nad národem takovým nemá mstíti duše má?'),
(1565349,54,24,5,30,'Věc užasnutí hodná a hrozná děje se v zemi této.'),
(1565350,54,24,5,31,'Proroci prorokují lživě, a kněží panují skrze ně, a lid můj miluje to. Čeho byste pak neučinili naposledy?'),
(1565351,54,24,6,1,'Shromažďte se, synové Beniaminovi, z prostředku Jeruzaléma, a v Tekoa trubte trubou, a nad Betkarem vyzdvihněte korouhev; nebo viděti zlé od půlnoci, a potření veliké.'),
(1565352,54,24,6,2,'Panně krásné a rozkošné připodobnil jsem byl dceru Sionskou.'),
(1565353,54,24,6,3,'Ale přitáhnou k ní pastýři s stády svými, rozbijí proti ní stany vůkol, spase každý místo své.'),
(1565354,54,24,6,4,'Vyzdvihněte proti ní válku, vstaňte a přitrhněme o poledni. Běda nám, že pomíjí den, že se roztáhli stínové večerní.'),
(1565355,54,24,6,5,'Vstaňte a přitrhněme v noci, a zkazme paláce její.'),
(1565356,54,24,6,6,'Takto zajisté praví Hospodin zástupů: Nasekejte dříví, a zdělejte proti Jeruzalému náspy. Toť jest to město, kteréž navštíveno býti musí; což ho koli, jen nátisk jest u prostřed něho.'),
(1565357,54,24,6,7,'Jakož studnice vypryšťuje vodu svou, tak ono vypryšťuje zlost svou. Nátisk a zhoubu slyšeti v něm před oblíčejem mým ustavičně, bolest i bití.'),
(1565358,54,24,6,8,'Usmysl sobě, ó Jeruzaléme, aby se neodloučila duše má od tebe, abych tě neobrátil v pustinu, v zemi nebydlitelnou.'),
(1565359,54,24,6,9,'Takto praví Hospodin zástupů: Jistě paběrovati budou jako vinný kmen ostatek Izraele, říkajíce: Sahej rukou svou jako ten,kterýž víno zbírá do putny.'),
(1565360,54,24,6,10,'Komuž mluviti budu, a kým osvědčovati, aby slyšeli? Aj, neobřezané jsou uši jejich, tak že nemohou pozorovati; aj, slovo Hospodinovo mají v posměchu, a nemají líbosti v něm.'),
(1565361,54,24,6,11,'Protož plný jsem prchlivosti Hospodinovy, ustal jsem, drže ji v sobě. Vylita bude i na maličké vně, spolu i na shromáždění mládenců, ovšem pak muž s ženou jat bude, stařec s kmetem.'),
(1565362,54,24,6,12,'A dostanou se domové jejich jiným, též pole i ženy, když vztáhnu ruku svou na obyvatele této země, dí Hospodin.'),
(1565363,54,24,6,13,'Od nejmenšího zajisté z nich, až do největšího z nich, všickni napořád vydali se v lakomství, anobrž od proroka až do kněze všickni napořád provodí faleš.'),
(1565364,54,24,6,14,'A hojí potření dcery lidu mého povrchu, říkajíce: Pokoj, pokoj, ješto není žádného pokoje.'),
(1565365,54,24,6,15,'Styděli-liž se pak co proto, že ohavnost páchali? Aniž se lid co styděl, aniž jich proroci k zahanbení přivesti uměli. Protož padnou mezi padajícími; v čas, v němž je navštívím, klesnou, praví Hospodin.'),
(1565366,54,24,6,16,'Když takto říkával Hospodin: Zastavte se na cestách, a pohleďte, a vyptejte se na stezky staré, která jest cesta dobrá, i choďte po ní, a naleznete odpočinutí duši své, tedy říkávali: Nebudeme choditi.'),
(1565367,54,24,6,17,'Když jsem pak ustanovil nad vámi strážné, řka: Mějtež pozor na zvuk trouby, tedy říkávali: Nebudeme pozorovati.'),
(1565368,54,24,6,18,'Protož slyšte, ó národové, a poznej, ó shromáždění, co se děje mezi nimi.'),
(1565369,54,24,6,19,'Slyš, ó země: Aj, já uvedu zlé na lid tento, ovoce myšlení jejich, proto že nepozorují slov mých, ani zákona mého, ale jím pohrdají.'),
(1565370,54,24,6,20,'K čemuž mi kadidlo z Sáby přichází, a vonná třtina výborná z země daleké? Zápalů vašich nelibuji sobě, aniž oběti vaše jsou mi příjemné.'),
(1565371,54,24,6,21,'Protož takto praví Hospodin: Aj, já nakladu lidu tomuto úrazů, a zurážejí se o ně otcové, tolikéž i synové, soused i bližní jeho, a zahynou.'),
(1565372,54,24,6,22,'Takto praví Hospodin: Aj, lid přitáhne z země půlnoční, a národ veliký povstane od končin země.'),
(1565373,54,24,6,23,'Lučiště i kopí pochytí, každý ukrutný bude, a neslitují se. Hlas jejich jako moře zvučeti bude, a na koních jezditi budou, zšikovaní jako muž k boji, proti tobě, ó dcero Sionská.'),
(1565374,54,24,6,24,'Jakž uslyšíme pověst o něm, opadnou ruce naše; ssoužení zachvátí nás, a bolest jako rodičku.'),
(1565375,54,24,6,25,'Nevycházejte na pole, a na cestu nechoďte; nebo meč nepřítele a strach jest vůkol.'),
(1565376,54,24,6,26,'Ó dcero lidu mého, přepaš se žíní, a válej se v popele. Vydej se v kvílení, jako po synu jednorozeném, v kvílení přehořké; nebo náhle přitáhne zhoubce na nás.'),
(1565377,54,24,6,27,'Dal jsem tě za věži v lidu tvém, a za baštu, abys spatřoval a zkušoval cesty jejich.'),
(1565378,54,24,6,28,'Všickni jsou z zarputilých nejzarputilejší, chodí jako utrhač, jsou ocel a železo, všickni napořád zhoubcové jsou.'),
(1565379,54,24,6,29,'Prahnou měchy, od ohně mizí olovo, nadarmo ustavičně přepaluje zlatník; nebo zlé věci nemohou býti odděleny.'),
(1565380,54,24,6,30,'Stříbrem falešným nazovou je, nebo Hospodin zavrhl je.'),
(1565381,54,24,7,1,'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, řkoucí:'),
(1565382,54,24,7,2,'Postav se v braně domu Hospodinova, a ohlašuj tam slovo toto, a rci: Slyšte slovo Hospodinovo všickni Judští, kteříž vcházíte do bran těchto, abyste se klaněli Hospodinu.'),
(1565383,54,24,7,3,'Takto praví Hospodin zástupů, Bůh Izraelský: Polepšte cest svých i předsevzetí svých, a způsobím to, abyste bydlili na místě tomto.'),
(1565384,54,24,7,4,'Neskládejte naděje své v slovích lživých, říkajíce: Chrám Hospodinův, chrám Hospodinův, chrám Hospodinův jest.'),
(1565385,54,24,7,5,'Ale jestliže všelijak polepšíte cest svých, a předsevzetí svých, jestliže spravedlivě soud konati budete mezi mužem a mezi bližním jeho;'),
(1565386,54,24,7,6,'Přichozího, sirotka a vdovy neutisknete, a krve nevinné nevylejete na místě tomto, a za bohy cizími nebudete-li choditi k svému zlému:'),
(1565387,54,24,7,7,'Tedy způsobím, abyste bydlili na místě tomto, v zemi, kterouž jsem dal otcům vašim, od věků až na věky.'),
(1565388,54,24,7,8,'Aj, vy skládáte naději svou v slovích lživých, kteráž neprospívají.'),
(1565389,54,24,7,9,'Zdaliž kradouce, mordujíce a cizoložíce i křivě přisahajíce a kadíce Bálovi; též chodíce za bohy cizími, jichž neznáte,'),
(1565390,54,24,7,10,'Předce choditi a postavovati se budete před oblíčejem mým v domě tomto, kterýž nazván jest od jména mého, a říkati: Vyproštěni jsme, abyste páchali ty všecky ohavnosti?'),
(1565391,54,24,7,11,'Což peleší lotrovskou jest dům tento před očima vašima, kterýž nazván jest od jména mého? Aj, takéť já vidím, dí Hospodin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565392,54,24,7,12,'Ale jděte aspoň na místo mé, kteréž bylo v Sílo, kdež jsem byl způsobil příbytek jménu svému z počátku, a vizte, co jsem učinil jemu pro nešlechetnost lidu svého Izraelského.'),
(1565393,54,24,7,13,'Protož nyní, že činíte všecky skutky tyto, dí Hospodin, a když mluvím k vám, ráno vstávaje, a to ustavičně, tedy neposloucháte, a když volám na vás, tedy neozýváte se:'),
(1565394,54,24,7,14,'Protož učiním domu tomuto, kterýž nazván jest od jména mého, v němž vy doufáte, i místu tomuto, kteréž jsem dal vám a otcům vašim, jako jsem učinil Sílo;'),
(1565395,54,24,7,15,'A zavrhu vás od tváři své, jako jsem zavrhl bratří vaše, všecko símě Efraimovo.'),
(1565396,54,24,7,16,'Ty tedy nemodl se za lid tento, aniž pozdvihuj za ně hlasu a modlitby, aniž se přimlouvej ke mně; nebo tě nikoli nevyslyším.'),
(1565397,54,24,7,17,'Zdaliž sám nevidíš, co oni činí v městech Judských a po ulicích Jeruzalémských?'),
(1565398,54,24,7,18,'Synové zbírají dříví, a otcové zaněcují oheň, ženy pak zadělávají těsto, aby pekly koláče tvoru nebeskému, a obětovali oběti mokré bohům cizím, aby mne popouzeli.'),
(1565399,54,24,7,19,'Zdaliž to proti mně jest, že mne oni popouzejí? dí Hospodin. Zdali není proti nim k zahanbení tváři jejich?'),
(1565400,54,24,7,20,'Pročež takto praví Panovník Hospodin: Aj, hněv můj a prchlivost má vylita bude na místo toto, na lidi i na hovada, i na dříví polní, i na úrody země, a hořeti bude, tak že neuhasne.'),
(1565401,54,24,7,21,'Takto praví Hospodin zástupů, Bůh Izraelský: Zápaly své přidejte k obětem svým, a jezte maso.'),
(1565402,54,24,7,22,'Nebo jsem nemluvil s otci vašimi, aniž jsem přikázal jim v ten den, v kterýž jsem je vyvedl z země Egyptské, o zápalích a obětech.'),
(1565403,54,24,7,23,'Ale toto přikázal jsem jim, řka: Poslouchejte hlasu mého, a budu vaším Bohem, a vy budete mým lidem, a choďte po vší cestě, kterouž jsem vám přikázal, aby vám dobře bylo.'),
(1565404,54,24,7,24,'Však neposlechli, aniž naklonili ucha svého, ale chodili po radách, a podlé zdání srdce svého zlého. Obrátili se ke mně hřbetem a ne tváří svou.'),
(1565405,54,24,7,25,'Od toho času, jakž vyšli otcové vaši z země Egyptské, až do tohoto dne posílal jsem k vám všecky služebníky své proroky, každý den ráno vstávaje, a to ustavičně.'),
(1565406,54,24,7,26,'Však neposlechli mne, aniž naklonili ucha svého, ale zatvrdivše šíji svou, hůře činili nežli otcové jejich.'),
(1565407,54,24,7,27,'Když jim mluvíš všecka slova tato, ani tebe neposlouchají, a když voláš na ně, neohlašují se tobě.'),
(1565408,54,24,7,28,'Protož rciž jim: Tento jest národ, kteříž neposlouchají hlasu Hospodina Boha svého, aniž přijímají naučení. Zhynula pravda, a vymizela z úst jejich.'),
(1565409,54,24,7,29,'Ohol vlasy své a zavrz, a naříkej hlasem na místech vysokých; nebo zavrhl Hospodin a opustil rodinu, na kterouž se velmi hněvá.'),
(1565410,54,24,7,30,'Činili zajisté synové Judovi, což zlého jest před očima mýma, dí Hospodin. Nastavěli ohavností svých v domě tom, kterýž nazván jest od jména mého, aby poškvrnili jej.'),
(1565411,54,24,7,31,'Nadto vzdělali výsosti Tofet, kteréž jest v údolí syna Hinnom, aby pálili syny své i dcery své ohněm, čehož jsem nepřikázal, aniž vstoupilo na srdce mé.'),
(1565412,54,24,7,32,'Protož aj, dnové jdou, dí Hospodin, kdyžto nebude slouti více Tofet, ani údolí syna Hinnom, ale údolí mordu, a pochovávati budou v Tofet, nebo nebude dostávati místa.'),
(1565413,54,24,7,33,'I budou mrtvá těla lidu tohoto za pokrm ptactvu nebeskému a šelmám zemským, a nebude žádného, kdo by odstrašil.'),
(1565414,54,24,7,34,'Způsobím také, aby přestal v městech Judských a v ulicích Jeruzalémských hlas radosti a hlas veselé, hlas ženicha a hlas nevěsty; nebo pustinou učiněna bude země.'),
(1565415,54,24,8,1,'V ten čas, dí Hospodin, vyberou kosti králů Judských, i kosti knížat jejich, i kosti kněží, i kosti proroků, ano i kosti obyvatelů Jeruzalémských z hrobů jejich,'),
(1565416,54,24,8,2,'A rozmecí je proti slunci a měsíci, i proti všemu vojsku nebeskému, kteréž milují, a kterýmž slouží, a za kterýmiž chodí, a kterýchž hledají, a kterýmž se klanějí. Nebudou sebrány, ani pochovány, budou místo hnoje na svrchku země.'),
(1565417,54,24,8,3,'I bude žádostivější smrt nežli život všechněm ostatkům těm, kteříž pozůstanou z rodiny této nešlechetné na všech místech, kdež by koli pozůstali, tam kamž je zaženu, dí Hospodin zástupů.'),
(1565418,54,24,8,4,'Protož díš jim: Takto praví Hospodin: Tak-liž padli, aby nemohli povstati? Tak-liž se odvrátil, aby se nemohl zase navrátiti?'),
(1565419,54,24,8,5,'Proč se odvrátil lid tento Jeruzalemský odvrácením věčným? Chytají se lsti, a nechtí se navrátiti.'),
(1565420,54,24,8,6,'Pozoroval jsem a poslouchal. Nemluví, což pravého jest; není, kdo by želel zlosti své, říkaje: Což jsem učinil? Každý obrácen jest k běhu svému jako kůň, kterýž prudce běží k boji.'),
(1565421,54,24,8,7,'Ješto čáp u povětří zná nařízené časy své, a hrdlička i řeřáb i vlaštovice šetří času příletu svého, lid pak můj nezná soudu Hospodinova.'),
(1565422,54,24,8,8,'Jakž můžete říci: Moudří jsme a zákon Hospodinův máme? Aj, jistě nadarmo dělá písař péro, nadarmo jsou v zákoně zběhlí.'),
(1565423,54,24,8,9,'Kohož zahanbili ti moudří? Kdo jsou předěšeni a jati? Aj, slovem Hospodinovým pohrdají, jakáž tedy jest moudrost jejich?'),
(1565424,54,24,8,10,'A protož dám ženy jejich jiným, pole jejich těm, kteříž by je opanovali; nebo od nejmenšího až do největšího všickni napořád vydali se v lakomství, od proroka až do kněze všickni napořád provodí faleš.'),
(1565425,54,24,8,11,'Nebo hojí potření dcery lidu mého po vrchu, říkajíce: Pokoj, pokoj, ješto není žádného pokoje.'),
(1565426,54,24,8,12,'Jsou-liž zahanbováni, proto že ohavnost páchali? Ba ani se co ustydli, ani zahanbiti uměli. Protož padnou, když oni padati budou; v čas, v němž je navštívím, klesnou, praví Hospodin.'),
(1565427,54,24,8,13,'Do konce vykořením je, dí Hospodin. Nebude žádného hroznu na vinném kmenu, ani žádných fíků na fíku, ano i list sprchne, a což dám jim, odjato bude.'),
(1565428,54,24,8,14,'Proč my tu sedíme? Shromažďte se, a vejděme do měst hrazených, a odpočineme tam. Ale Hospodin Bůh náš káže odpočívati nám, když vodou jedovatou napojí nás, proto že jsme hřešili proti Hospodinu.'),
(1565429,54,24,8,15,'Čekej pokoje, ale nic dobrého, času uzdravení, ale aj, hrůza.'),
(1565430,54,24,8,16,'Od Dan slyšeti frkání koní jeho, od hlasu prokřikování silných jeho všecka země se třese, kteříž táhnou, aby zžírali zemi i všecko, což jest na ní, město i ty, kteříž bydlejí v něm.'),
(1565431,54,24,8,17,'Nebo aj, já pošli na vás hady nejjedovatější, proti nimž nic neprospívá zaklínání, a štípati vás budou, dí Hospodin.'),
(1565432,54,24,8,18,'Srdce mé ve mně, kteréž by mne mělo občerstvovati v zármutku, mdlé jest.'),
(1565433,54,24,8,19,'Aj, hlas křiku dcery lidu mého z země velmi daleké: Zdali Hospodina není na Sionu? Zdali krále jeho není na něm? Proč mne popouzeli rytinami svými, marnostmi cizozemců?'),
(1565434,54,24,8,20,'Pominula žeň, dokonalo se léto, a my nejsme vyproštěni.'),
(1565435,54,24,8,21,'Pro potření dcery lidu mého potřín jsem, smutek nesu, užasnutí podjalo mne.'),
(1565436,54,24,8,22,'Což není žádného lékařství v Galád? Což není žádného lékaře tam? Proč tedy není zhojena dcera lidu mého?'),
(1565437,54,24,9,1,'Ó kdo mi to dá, aby hlava má byla vodou, a oči mé pramenem slzí, abych dnem i nocí oplakati mohl zmordovaných dcerky lidu svého.'),
(1565438,54,24,9,2,'Ó kdo mne postaví na poušti v hospodě pocestných, abych opustil lid svůj, a odešel od nich; nebo všickni jsou cizoložníci, zběř zpronevěřilých,'),
(1565439,54,24,9,3,'A natahují jazyka svého ke lži jako lučiště své. Zmocnili se na zemi, ale ne k pravdě; nebo ze zlého ve zlé jdou, a mne neznají, praví Hospodin.'),
(1565440,54,24,9,4,'Každý střez se bližního svého, a ne každému bratru se dověřuj; nebo každý bratr hledí všelijak podtrhnouti, a každý bližní jako utrhač chodí.'),
(1565441,54,24,9,5,'A jeden každý bližního svého oklamává, a pravdy nemluví; učí jazyk svůj mluviti lež, neprávě činíce, ustávají.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565442,54,24,9,6,'Tvůj byt jest u prostřed lidu přelstivého; pro lest nechtějí mne poznati, dí Hospodin.'),
(1565443,54,24,9,7,'Z té příčiny takto praví Hospodin zástupů: Aj, já přeháněje, pruboval jsem je. Jakž tedy již naložiti mám s dcerou lidu svého?'),
(1565444,54,24,9,8,'Střela zabíjející jest jazyk jejich, lest mluví. Ústy svými pokojně s bližním svým mluví, ale v srdci svém skládá úklady své.'),
(1565445,54,24,9,9,'Zdali pro takové věci nemám jich navštíviti? dí Hospodin. Zdaliž nad národem takovým nemá mstíti duše má?'),
(1565446,54,24,9,10,'Pro tyto hory dám se v pláč a v naříkání, a pro pastviště, kteráž jsou na poušti, v kvílení; nebo popálena budou, tak že nebude žádného, kdo by skrze ně šel, aniž bude slyšán hlas dobytka. Od ptactva nebeského až do hovada všecko se odbéře a odejde.'),
(1565447,54,24,9,11,'A obrátím Jeruzalém v hromady, příbytek draků, a města Judská obrátím v pustinu, tak že nebude obyvatele.'),
(1565448,54,24,9,12,'Kdo jest ten muž moudrý, ješto by rozuměl tomu? A k komu mluvila ústa Hospodinova, ješto by oznamoval to, proč zahynouti má tato země, a vypálena býti jako poušť, tak aby nebylo, kdo by skrze ni šel?'),
(1565449,54,24,9,13,'Nebo praví Hospodin: Proto že opustili zákon můj, kterýž jsem jim předložil, a neposlouchali hlasu mého, aniž chodili za ním,'),
(1565450,54,24,9,14,'Ale chodili za myšlénkami srdce svého a za Báli, čemuž je naučili otcové jejich:'),
(1565451,54,24,9,15,'Protož takto praví Hospodin zástupů, Bůh Izraelský: Aj, já nakrmím je, totiž lid tento, pelynkem, a napojím je vodou jedovatou.'),
(1565452,54,24,9,16,'Nebo rozptýlím je mezi národy,kterýchž neznali oni, ani otcové jejich, a posílati budu za nimi meč, až je do konce vyhladím.'),
(1565453,54,24,9,17,'Takto praví Hospodin zástupů: Pilně považte, a svolejte ty, kteréž naříkávají, ať přijdou, a k těm, kteréž jsou vycvičené, pošlete, aby přišly.'),
(1565454,54,24,9,18,'Nechť pospíší, a dadí se nad námi v naříkání, aby slzy tekly z očí našich, a víčka naše oplývala vodou.'),
(1565455,54,24,9,19,'Hlas zajisté naříkání slyšeti z Siona: Jak jsme pohubeni! Stydíme se náramně, že jsme ztratili zemi, že boří příbytky naše.'),
(1565456,54,24,9,20,'Anobrž slyšte, ženy, slovo Hospodinovo, a nechť přijme ucho vaše slovo úst jeho, abyste učily dcerky své naříkání, a jedna každá tovaryšku svou kvílení.'),
(1565457,54,24,9,21,'Nebo vlezla smrt okny našimi, vešla na paláce naše, aby vyhubila děti z rynků a mládence z ulic.'),
(1565458,54,24,9,22,'(Mluv i to: Takto dí Hospodin:) A padla mrtvá těla lidská jako hnůj po poli, a jako snopové za žencem, a není žádného, kdo by pochoval.'),
(1565459,54,24,9,23,'Takto praví Hospodin: Nechlub se moudrý v moudrosti své, ani se chlub silný v síle své, aniž se chlub bohatý v bohatství svém.'),
(1565460,54,24,9,24,'Ale v tom nechť se chlubí, kdo se chlubí, že rozumí a zná mne, že já jsem Hospodin, kterýž činím milosrdenství, soud i spravedlnost na zemi; nebo v těch věcech líbost mám, dí Hospodin.'),
(1565461,54,24,9,25,'Aj, dnové jdou, praví Hospodin, v nichž navštívím každého, obřezaného i neobřezaného,'),
(1565462,54,24,9,26,'Egyptské i Judské, a Idumejské i Ammonitské, a Moábské, i všecky, kteříž v nejzadnějším koutě bydlí na poušti. Nebo ti všickni národové jsou neobřezaní, tolikéž všecken dům Izraelský jest neobřezaného srdce.'),
(1565463,54,24,10,1,'Slyšte slovo toto, kteréž mluví k vám Hospodin, ó dome Izraelský.'),
(1565464,54,24,10,2,'Takto praví Hospodin: Cestě pohanů neučte se, aniž se znamení nebeských děste, neboť se jich děsí pohané.'),
(1565465,54,24,10,3,'Ustanovení zajisté těch národů jsou pouhá marnost. Nebo setna dřevo sekerou v lese, dílo rukou řemeslníka,'),
(1565466,54,24,10,4,'Stříbrem a zlatem ozdobí je, hřebíky a kladivy utvrzují je, aby se neviklalo.'),
(1565467,54,24,10,5,'Jsou jako palmový špalek tvrdý, ani nemluví; nošeni býti musejí, nebo choditi nemohou. Nebojtež se jich, nebo zle učiniti nemohou, aniž také dobře učiniti mohou.'),
(1565468,54,24,10,6,'Z nichž není žádného tobě podobného, ó Hospodine; veliký jsi, i jméno tvé veliké jest v moci.'),
(1565469,54,24,10,7,'Kdož by se nebál tebe, králi národů? Na tebeť zajisté to sluší, poněvadž mezi všemi mudrci národů, i ve všem království jejich nikdá nebylo podobného tobě.'),
(1565470,54,24,10,8,'A však ze spolka zhlupěli, a blázni jsou; z dřeva učiti se jest pouhá marnost.'),
(1565471,54,24,10,9,'Stříbro tažené z zámoří přivážíno bývá, a zlato z Ufaz, dílo řemeslníka a rukou zlatníka; z postavce modrého a šarlatový jest oděv jejich, všecko to jest dílo umělých.'),
(1565472,54,24,10,10,'Ale Hospodin jest Bůh pravý, jest Bůh živý a král věčný, před jehož prchlivostí země se třese, aniž mohou snésti národové rozhněvání jeho.'),
(1565473,54,24,10,11,'(Takto říkejte jim: Bohové ti, kteříž nebe ani země neučinili, nechť zahynou z země, a nechť jich není pod nebem.)'),
(1565474,54,24,10,12,'Kterýž učinil zemi mocí svou, kterýž utvrdil okršlek světa moudrostí svou, a opatrností svou roztáhl nebesa.'),
(1565475,54,24,10,13,'Kterýžto když vydává hlas, ječení vod bývá na nebi, a kterýž působí to, aby vystupovaly páry od kraje země, blýskání s deštěm přivodí, a vyvodí vítr z pokladů svých.'),
(1565476,54,24,10,14,'Tak zhlupěl každý člověk, že nezná toho, že zahanben bývá každý zlatník pro rytinu; nebo slitina jeho jest faleš, a není ducha v nich.'),
(1565477,54,24,10,15,'Marnost jsou a dílo podvodů; v čas, v němž je navštívím, zahynou.'),
(1565478,54,24,10,16,'Neníť podobný těmto díl Jákobův, nebo on jest stvořitel všeho; Izrael tolikéž jest pokolení dědictví toho, jehož jméno jest Hospodin zástupů.'),
(1565479,54,24,10,17,'Sbeř z země koupi svou, ty kteráž bydlíš v pevnosti této.'),
(1565480,54,24,10,18,'Nebo takto praví Hospodin: Aj, já vyhodím z praku obyvatele země této pojednou, a ssoužím je, aby shledali toto:'),
(1565481,54,24,10,19,'Běda mně pro setření mé, přebolestná jest rána má, ješto jsem já byl řekl: Jistě tuto nemoc budu moci snésti.'),
(1565482,54,24,10,20,'Stan můj popléněn jest, a všickni provazové moji potrháni jsou. Synové moji odebrali se ode mne, a není žádného; není žádného, kdo by více rozbíjel stan můj, a roztáhl kortýny mé.'),
(1565483,54,24,10,21,'Nebo zhlupěli pastýři, a Hospodina se nedotazovali; protož nevede se jim šťastně, a všecko stádo pastvy jejich rozptýleno jest.'),
(1565484,54,24,10,22,'Aj, pověst jistá přichází, a pohnutí veliké z země půlnoční, aby obrácena byla města Judská v pustinu a v příbytek draků.'),
(1565485,54,24,10,23,'Vím, Hospodine, že není v moci člověka cesta jeho, aniž jest v moci muže toho, kterýž chodí, aby spravoval krok svůj.'),
(1565486,54,24,10,24,'Kárej mne, Hospodine, však milostivě, ne v hněvě svém, abys nesetřel mne.'),
(1565487,54,24,10,25,'Vylí hněv svůj na ty národy, kteříž tebe neznají, a na rodiny, kteréž jména tvého nevzývají; nebo zžírají Jákoba, a tak zžírají jej, aby jej všeho sežrali, a obydlí jeho v poustku obrátili.'),
(1565488,54,24,11,1,'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, řkoucí:'),
(1565489,54,24,11,2,'Slyšte slova smlouvy této, kteráž byste mluvili mužům Judským, a obyvatelům Jeruzalémským,'),
(1565490,54,24,11,3,'A rci jim: Takto praví Hospodin Bůh Izraelský: Zlořečený ten člověk, kterýž by neposlechl slov smlouvy této,'),
(1565491,54,24,11,4,'Kterouž jsem vydal otcům vašim tehdáž, když jsem je vyvedl z země Egyptské, z peci železné, řka: Poslouchejte hlasu mého, a čiňte to všecko, tak jakž přikazuji vám, i budete lidem mým, a já budu Bohem vaším,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565492,54,24,11,5,'Abych splnil přísahu, kterouž jsem učinil otcům vašim, že jim dám zemi oplývající mlékem a strdí, jakž dnešní den jest. Jemuž odpověděv, řekl jsem: Amen, Hospodine.'),
(1565493,54,24,11,6,'Potom řekl mi Hospodin: Ohlašuj všecka slova tato po městech Judských, a po ulicích Jeruzalémských, řka: Slyšte slova smlouvy této, a čiňte je.'),
(1565494,54,24,11,7,'Nebo častokrát osvědčoval jsem se otcům vašim, od toho dne, jakž jsem je vyvedl z země Egyptské, až do dne tohoto; ráno přivstávaje a osvědčuje se, říkával jsem: Poslouchejte hlasu mého.'),
(1565495,54,24,11,8,'Ale neposlouchali, aniž naklonili ucha svého, nýbrž chodil jeden každý po zdání srdce svého zlého. Pročež uvedl jsem na ně všecka slova smlouvy této, kterouž jsem přikázal plniti, ale neplnili.'),
(1565496,54,24,11,9,'Tehdy řekl mi Hospodin: Nalézá se spiknutí mezi muži Judskými, a mezi obyvateli Jeruzalémskými.'),
(1565497,54,24,11,10,'Obrátili se k nepravostem otců svých starých, kteříž nechtěli poslouchati slov mých. Tolikéž tito chodí za bohy cizími, sloužíce jim; dům Izraelský a dům Judský zrušili smlouvu mou, kterouž jsem učinil s otci jejich.'),
(1565498,54,24,11,11,'Protož takto praví Hospodin: Aj, já uvedu na ně zlé, z něhož nebudou moci vyjíti. By pak volali ke mně, nevyslyším jich.'),
(1565499,54,24,11,12,'I půjdou města Judská i obyvatelé Jeruzalémští, a budou volati k bohům těm, kterýmž kadí, ale nikoli nevysvobodí jich v čas bídy jejich,'),
(1565500,54,24,11,13,'Ačkoli podlé počtu měst máš bohy své, ó Judo, a podlé počtu ulic Jeruzalémských nastavěli jste oltářů ohavnosti té, oltářů, na nichž byste kadili Bálovi.'),
(1565501,54,24,11,14,'Protož ty nemodl se za lid tento, aniž pozdvihuj za ně hlasu a modlitby; neboť nikoli nevyslyším jich v ten čas, když by volali ke mně příčinou svého zlého.'),
(1565502,54,24,11,15,'Co jest milému mému do mého domu, poněvadž nestydatě páše nešlechetnosti s mnohými, a oběti svaté odešly od tebe, a že v zlosti své pléšeš?'),
(1565503,54,24,11,16,'Byltě Hospodin nazval jméno tvé olivou zelenající se, pěknou pro ovoce ušlechtilé, ale s zvukem bouře veliké zapálí ji s hůry, když polámí ratolesti její.'),
(1565504,54,24,11,17,'Nebo Hospodin zástupů, kterýž tě byl štípil, vyřkl zlé proti tobě, pro nešlechetnost domu Izraelského a domu Judského, kterouž mezi sebou páchali, aby mne popouzeli, kadíce Bálovi.'),
(1565505,54,24,11,18,'Hospodin zajisté oznámil mi, i dověděl jsem se. Tehdáž jsi mi ukázal předsevzetí jejich,'),
(1565506,54,24,11,19,'Když jsem já byl jako beránek a volček, kterýž veden bývá k zabití. Nebo nevěděl jsem, by proti mně rady skládali: Zkazme strom s ovocem jeho, a vyhlaďme jej z země živých, aby jméno jeho nebylo připomínáno více.'),
(1565507,54,24,11,20,'Ale ó Hospodine zástupů, soudce spravedlivý, kterýž zkušuješ ledví i srdce, nechť se podívám na pomstu tvou nad nimi; nebo jsem tobě zjevil při svou.'),
(1565508,54,24,11,21,'Protož takto praví Hospodin o Anatotských, kteříž hledají bezživotí tvého, říkajíce: Neprorokuj ve jménu Hospodinovu, abys neumřel v ruce naší:'),
(1565509,54,24,11,22,'Protož takto praví Hospodin zástupů: Aj, já navštívím je. Mládenci zbiti budou mečem, synové jejich i dcery jejich zemrou hladem,'),
(1565510,54,24,11,23,'A nebudou míti potomků, když uvedu zlé na Anatotské, času toho, v němž je navštívím.'),
(1565511,54,24,12,1,'Spravedlivý zůstaneš, Hospodine, povedu-li odpor proti tobě, a však o soudech tvých mluviti budu s tebou. Proč se cestě bezbožníků šťastně vede? Mají pokoj všickni, kteříž se pyšně zpronevěřili.'),
(1565512,54,24,12,2,'Štěpuješ je, ano i vkořeňují se; rostou, ano i ovoce nesou ti, jejichžto úst blízko jsi, ale daleko od ledví jejich.'),
(1565513,54,24,12,3,'Ale ty, Hospodine, znáš mne, prohlédáš mne, a zkusils srdce mého, že s tebou jest, onyno pak táhneš jako ovce k zabíjení, a připravuješ je ke dni zabití.'),
(1565514,54,24,12,4,'Dokudž by žalostila země, a bylina všeho pole svadla pro zlost přebývajících v ní, a hynulo každé hovado i ptactvo? Nebo říkají: Nevidíť Bůh skončení našeho.'),
(1565515,54,24,12,5,'Poněvadž tebe s pěšími běžícího k ustání přivodí, kterakž bys tedy stačil při koních? A poněvadž v zemi pokojné, jíž jsi se dověřil, ustáváš, což pak spravíš při tom zdutém Jordánu?'),
(1565516,54,24,12,6,'Nebo i bratří tvoji i dům otce tvého zpronevěřili se tobě, a ti také povolávají za tebou plnými ústy. Nevěř jim, byť pak mluvili s tebou přátelsky.'),
(1565517,54,24,12,7,'Opustil jsem dům svůj, zavrhl jsem dědictví své, dal jsem to, což velice milovala duše má, v ruce nepřátel jeho.'),
(1565518,54,24,12,8,'Učiněno jest mi dědictví mé podobné lvu v lese, vydává proti mně hlas svůj, pročež ho nenávidím.'),
(1565519,54,24,12,9,'A což ptákem dravým jest mi dědictví mé? Což ptactvo vůkol bude proti němu? Jdětež nu, shromažďte se všecka zvířata polní, sejděte se k jídlu.'),
(1565520,54,24,12,10,'Mnozí pastýři zkazí vinici mou, pošlapají podíl můj, podíl mně velmi milý obrátí v poušť nejhroznější,'),
(1565521,54,24,12,11,'Obrátí jej v pustinu. Kvíliti bude, spustošen jsa ode mne; spustne všecka tato země, nebo není žádného, kdo by to v srdci skládal.'),
(1565522,54,24,12,12,'Na všecka místa vysoká po poušti potáhnou zhoubcové, meč zajisté Hospodinův zžíře od jednoho kraje země až do druhého, nebude míti pokoje žádné tělo.'),
(1565523,54,24,12,13,'Nasejí pšenice, ale trní žíti budou; bolestně to ponesou, že užitku nevezmou, a styděti se budou za úrody své pro prchlivost hněvu Hospodinova.'),
(1565524,54,24,12,14,'Takto praví Hospodin o všech mých sousedech zlých, jenž se dotýkají dědictví, kteréž jsem uvedl v dědictví lidu svému Izraelskému: Aj, já vypléním je z země jejich, když dům Judský vypléním z prostředku jejich.'),
(1565525,54,24,12,15,'Stane se však, když je vypléním, že se navrátím a smiluji se nad nimi, a přivedu zase jednoho každého z nich k dědictví jeho, a jednoho každého do země jeho.'),
(1565526,54,24,12,16,'Stane se také, jestliže by se pilně učili cestám lidu mého, a přisahali by ve jménu mém, říkajíce: Živť jest Hospodin, jakž oni učívali lid můj přisahati skrze Bále, že vzděláni budou u prostřed lidu mého.'),
(1565527,54,24,12,17,'Jestliže by pak neposlouchali, tedy pléniti budu národ ten ustavičně a hubiti, dí Hospodin.'),
(1565528,54,24,13,1,'Takto řekl Hospodin ke mně: Jdi a zjednej sobě pás lněný, a opaš jím bedra svá, do vody pak nedávej ho.'),
(1565529,54,24,13,2,'Tedy zjednal jsem ten pás podlé slova Hospodinova, a opásal jsem bedra svá.'),
(1565530,54,24,13,3,'Potom stalo se slovo Hospodinovo ke mně podruhé, řkoucí:'),
(1565531,54,24,13,4,'Vezmi ten pás, kterýž jsi zjednal, kterýž jest na bedrách tvých, a vstana, jdi k Eufrates, a skrej jej tam do díry skalní.'),
(1565532,54,24,13,5,'I šel jsem, a skryl jsem jej u Eufrates, jakž mi byl přikázal Hospodin.'),
(1565533,54,24,13,6,'Stalo se pak po přeběhnutí dnů mnohých, že řekl Hospodin ke mně: Vstana, jdi k Eufrates, a vezmi odtud ten pás, kterýžť jsem přikázal skrýti tam.'),
(1565534,54,24,13,7,'I šel jsem k Eufrates, a vykopav, vzal jsem ten pás z místa toho, kdež jsem jej byl skryl. A aj, zkažený byl ten pás, aniž se k čemu hodil.'),
(1565535,54,24,13,8,'Tehdy stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1565536,54,24,13,9,'Takto praví Hospodin: Takť zkazím pýchu Judských i pýchu Jeruzalémských velikou.'),
(1565537,54,24,13,10,'Lidu toho přenešlechetného, kteříž nechtí poslouchati slov mých, kteříž chodí podlé zdání srdce svého, a chodí za bohy cizími, sloužíce jim, a klanějíce se jim. I bude podoben pasu tomu, kterýž se nehodí k ničemu.'),
(1565538,54,24,13,11,'Nebo jakož se drží pás na bedrách muže, tak jsem byl připojil k sobě všecken dům Izraelský i všecken dům Judský, dí Hospodin, aby byli lidem mým, a to k slávě, a k chvále, i k ozdobě, ale nebyli poslušni.'),
(1565539,54,24,13,12,'Protož rci jim slovo toto: Takto praví Hospodin Bůh Izraelský: Všeliká nádoba vinná naplňována bývá vínem. Kdyžť pak řeknou: Zdaliž nevíme dobře, že všeliká nádoba vinná naplňována bývá vínem?'),
(1565540,54,24,13,13,'I díš jim: Takto praví Hospodin: Aj, já naplním všecky obyvatele země této i krále, kteříž sedí místo Davida na stolici jeho, i kněží i proroky, a tolikéž všecky obyvatele Jeruzalémské opilstvím,'),
(1565541,54,24,13,14,'A rozrazím jednoho o druhého, jakož otce, tak také syny, dí Hospodin. Nebudu šanovati, aniž odpustím, aniž se smiluji, abych zkaziti jich neměl.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565542,54,24,13,15,'Poslouchejte a ušima pozorujte, nepovyšujte se, neboť Hospodin mluví.'),
(1565543,54,24,13,16,'Dejte Hospodinu Bohu svému čest, dřív než by tmu uvedl, a dříve nežli by se zurážely nohy vaše o hory tmavé. I čekali byste světla, ale obrátil by je v stín smrti, proměnil by je v mrákotu.'),
(1565544,54,24,13,17,'Jestliže pak toho neuposlechnete, v skrýších plakati bude duše má pro pýchu vaši, a náramně kvíliti bude. Potekou, pravím, z očí mých slzy, nebo zajato bude stádce Hospodinovo.'),
(1565545,54,24,13,18,'Rci králi i královně: Seďte na zemi; nebo odjata bude přednost vaše, koruna ozdoby vaší.'),
(1565546,54,24,13,19,'Města polední uzavírána budou, tak že nebude žádného, kdo by otevříti mohl. Zastěhováno bude všecko Judstvo, zastěhováno bude docela.'),
(1565547,54,24,13,20,'Pozdvihněte očí svých, a vizte ty, kteříž táhnou od půlnoci. Kdež jest to stádo, kteréžť dáno bylo, stádce ozdoby tvé?'),
(1565548,54,24,13,21,'Co díš, když tě navštíví, ještos ty naučila je, aby byli nad tebou vůdcové přední? Zdaliž bolesti tebe nezachvátí jako ženu rodící?'),
(1565549,54,24,13,22,'Díš-li v srdci svém: Proč by mne to potkati mělo? Pro množství nepravosti tvé odkryti budou podolkové tvoji, násilně odjata bude obuv tvá.'),
(1565550,54,24,13,23,'Může-li změniti Mouřenín kůži svou, aneb pardus peřestost svou, také vy budete moci dobře činiti, naučivše se zle činiti.'),
(1565551,54,24,13,24,'Protož rozptýlím je, jako vítr pouště rozptyluje plevy.'),
(1565552,54,24,13,25,'Ten bude los tvůj a díl odměřený tobě ode mne, praví Hospodin, proto žes se zapomněla nade mnou, a úfalas v lež.'),
(1565553,54,24,13,26,'A tak i já také odkryji podolek tvůj nad hlavu tvou, aby spatřína byla hanba tvá,'),
(1565554,54,24,13,27,'Cizoložství tvá, a řehtání tvá, nešlechetná smilství tvá, na pahrbcích i na poli. Vidělť jsem ty ohavnosti tvé; běda tobě, Jeruzaléme. A což se ještě neočistíš? I až dokud pak?'),
(1565555,54,24,14,1,'Slovo, kteréž se stalo k Jeremiášovi o suchu.'),
(1565556,54,24,14,2,'Kvíliti bude země Judská, a brány její zemdlejí, smutek ponesou na zemi, a naříkání Jeruzaléma vzejde.'),
(1565557,54,24,14,3,'Také nejznamenitější z nich rozsílati budou i nejšpatnější své pro vodu. Přijdouce k čisternám, a nenaleznouce vody, navrátí se s nádobami svými prázdnými, hanbíce a stydíce se; protož přikryjí hlavu svou.'),
(1565558,54,24,14,4,'I oráči stydíce se, přikryjí hlavu svou příčinou země vyprahlé, proto že deště nebude na zemi.'),
(1565559,54,24,14,5,'Anobrž i laň na poli, což porodí, opustí; nebo mladistvé trávy nebude.'),
(1565560,54,24,14,6,'A divocí oslové stojíce na vysokých místech, hltati budou vítr jako draci; přehledí se oči jejich, nebo nebude žádné trávy.'),
(1565561,54,24,14,7,'Ó Hospodine, poněvadž nepravosti naše svědčí proti nám, slituj se pro jméno své. Nebo mnohá jsou odvrácení naše, toběť jsme zhřešili.'),
(1565562,54,24,14,8,'Ó naděje Izraelova, vysvoboditeli jeho v čas ssoužení, proč býti máš jako příchozí v této zemi, a jako pocestný stavující se na noclehu?'),
(1565563,54,24,14,9,'Proč se ukazuješ jako muž ustalý, jako silný, kterýž nemůže vysvoboditi? Všaks ty u prostřed nás, Hospodine, a jméno tvé nad námi vzýváno jest; neopouštějž nás.'),
(1565564,54,24,14,10,'Takto praví Hospodin o lidu tomto: Tak milují toulky, noh svých nezdržují, až Hospodin nemá v nich líbosti, a nyní zpomíná nepravost jejich, a navštěvuje hříchy jejich.'),
(1565565,54,24,14,11,'Potom řekl ke mně Hospodin: Nemodl se za lid tento k dobrému.'),
(1565566,54,24,14,12,'Když se postiti budou, já nikoli nevyslyším volání jejich, a když obětovati budou obět zápalnou a suchou, já nikoli neoblíbím sobě těch věcí, ale mečem a hladem a morem já do konce zhubím je.'),
(1565567,54,24,14,13,'Tedy řekl jsem: Ach, Panovníče Hospodine, aj, tito proroci říkají jim: Neuzříte meče, a hlad nepřijde na vás, ale pokoj pravý dám vám na místě tomto.'),
(1565568,54,24,14,14,'I řekl Hospodin ke mně: Lež prorokují ti proroci ve jménu mém. Neposlalť jsem jich, aniž jsem přikázal jim, anobrž aniž jsem mluvil k nim. Vidění lživé a hádání, a marné věci i lest srdce svého oni prorokují vám.'),
(1565569,54,24,14,15,'Protož takto praví Hospodin o prorocích, kteříž prorokují ve jménu mém, ješto jsem já jich neposlal, a kteříž říkají: Meče ani hladu nebude v zemi této: Mečem a hladem i ti sami proroci zhynou.'),
(1565570,54,24,14,16,'Lid pak ten, jemuž oni prorokují, rozmetán bude po ulicích Jeruzalémských hladem a mečem, aniž bude, kdo by je pochovával, je, manželky jejich, a syny jejich, a dcery jejich. Tak vyleji na ně nešlechetnost jejich.'),
(1565571,54,24,14,17,'Protož rciž jim slovo toto: Z očí mých tekou slzy dnem i nocí bez přestání; nebo potřína bude velmi velice panna dcera lidu mého ranou náramně bolestnou.'),
(1565572,54,24,14,18,'Vyjdu-li na pole, aj, tam zbití mečem; pakli vejdu do města, aj, tam nemocní hladem. Nebo jakož prorok tak kněz obcházejíce, kupčí zemí, a lidé toho neznají.'),
(1565573,54,24,14,19,'Zdaliž do konce zamítáš Judu? Zdali Sion oškliví sobě duše tvá? Proč nás biješ, tak abychom již nebyli uzdraveni? Čekáme-li pokoje, a aj, nic dobrého pakli času uzdravení, a aj, hrůza.'),
(1565574,54,24,14,20,'Poznávámeť, Hospodine, bezbožnost svou i nepravost otců svých, že jsme hřešili proti tobě.'),
(1565575,54,24,14,21,'Nezamítejž pro jméno své, nezlehčuj stolice slávy své; rozpomeň se, neruš smlouvy své s námi.'),
(1565576,54,24,14,22,'Zdaliž jsou mezi marnostmi pohanskými ti, kteříž by déšť dávali? A zdaliž nebesa dávají přívaly? Zdaliž ty nejsi sám, Hospodine, Bůh náš? Protož na tebeť očekáváme, nebo ty působíš všecko to.'),
(1565577,54,24,15,1,'Tedy řekl Hospodin ke mně: Byť se postavil Mojžíš i Samuel před oblíčejem mým, nikoli srdce nemohu míti k lidu tomuto. Pusť je ode mne, a nechť jdou pryč.'),
(1565578,54,24,15,2,'A řeknou-liť: Kam bychom šli? tedy díš jim: Takto praví Hospodin: Kdo k smrti, na smrt, a kdo k meči, pod meč, a kdo k hladu, k hladu, a kdo k zajetí, do zajetí.'),
(1565579,54,24,15,3,'Představím zajisté jim to čtvero, dí Hospodin: Meč k zmordování, a psy, aby je rozsmýkali, a ptactvo nebeské i zvěř zemskou, aby je sežrala a zkazila.'),
(1565580,54,24,15,4,'A musejí se smýkati po všech královstvích země příčinou Manassesa syna Ezechiášova, krále Judského, pro ty věci, kteréž páchal v Jeruzalémě.'),
(1565581,54,24,15,5,'Nebo kdo by se slitoval nad tebou, Jeruzaléme? A kdo by tě politoval? Aneb kdo by přišel, aby se zeptal, jakť se vede?'),
(1565582,54,24,15,6,'Tys opustil mne, dí Hospodin, odšels nazpět; protož vztáhnu ruku svou na tebe, abych tě zkazil. Ustal jsem, želeje.'),
(1565583,54,24,15,7,'Protož přetříbím je věječkou skrze brány země této, na sirobu přivedu a zkazím lid svůj, nebo se od cest svých nenavracují.'),
(1565584,54,24,15,8,'Větší bude počet vdov jeho než písku mořského. Přivedu na ně, na matky, na mládence zhoubce i v poledne; způsobím to, aby náhle připadli na to město, i budou zděšeni.'),
(1565585,54,24,15,9,'Zemdlí i ta, kteráž rodívala po sedmerém; vypustí duši svou, zapadne jí slunce ještě ve dne, hanbiti a styděti se bude. Ostatek pak jich vydám pod meč před oblíčejem nepřátel jejich, dí Hospodin.'),
(1565586,54,24,15,10,'Běda mně, matko má, že jsi mne porodila, muže sváru a muže různice vší zemi. Nepůjčoval jsem jim, aniž mi oni půjčovali, a každý mi zlořečí.'),
(1565587,54,24,15,11,'I řekl Hospodin: Zdaliž tobě, kterýž pozůstaneš, nebude dobře? Zdaliž nebudu tvým zástupcím u nepřítele v čas trápení a v čas ssoužení?'),
(1565588,54,24,15,12,'Zdaliž železo poláme půlnoční železo a ocel?'),
(1565589,54,24,15,13,'Jmění tvé, ó Judo, i poklady tvé vydám v rozchvátání darmo, po všech končinách tvých, a to pro všelijaké hříchy tvé.'),
(1565590,54,24,15,14,'A způsobím to, že musíš jíti s nepřátely svými do země cizí, když oheň zanícený v prchlivosti mé na vás pálati bude.'),
(1565591,54,24,15,15,'Ty znáš mne, Hospodine, rozpomeň se na mne, a navštěv mne, a pomsti mne nad těmi, kteříž dotírají na mne. Shovívaje jim, nezachvacuj mne; věz, že snáším pro tebe pohanění.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565592,54,24,15,16,'Když se naskytly řeči tvé, snědl jsem je, a měl jsem slovo tvé za radost a potěšení srdce svého, poněvadž jsi ty mne povolal sám, ó Hospodine Bože zástupů.'),
(1565593,54,24,15,17,'Nesedám v radě posměvačů, aniž pléši; pro přísnost tvou samotný sedám, nebo prchlivostí naplnils mne.'),
(1565594,54,24,15,18,'Proč má býti bolest má věčná, a rána má smrtelná, kteráž se nechce zhojiti? Proč mi býti máš naprosto jako oklamavatelný, jako vody nestálé?'),
(1565595,54,24,15,19,'Protož takto praví Hospodin: Jestliže se obrátíš, také tě zase obrátím, abys stál před oblíčejem mým; oddělíš-li věc drahou od ničemné, jako ústa má budeš. Nechť se oni obrátí k tobě, ty pak neobracej se k nim.'),
(1565596,54,24,15,20,'Nebo jsem tě postavil proti lidu tomuto jako zed měděnou pevnou. Kteříž bojovati budou proti tobě, ale neodolají tobě; nebo já jsem s tebou, abych tě vysvobozoval a vytrhoval, dí Hospodin.'),
(1565597,54,24,15,21,'Vytrhnu tě zajisté z rukou nešlechetníků, a vykoupím tě z ruky násilníků.'),
(1565598,54,24,16,1,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1565599,54,24,16,2,'Nepojímej sobě ženy, aniž měj synů neb dcer na místě tomto.'),
(1565600,54,24,16,3,'Nebo takto praví Hospodin o synech i dcerách zplozených v místě tomto, a o matkách jejich, kteréž zrodily je, i o jejich otcích, kteříž zplodili je v zemi této:'),
(1565601,54,24,16,4,'Smrtmi přebolestnými pomrou, nebudou oplakáni, ani pochováni; místo hnoje na svrchku země budou, a mečem i hladem do konce zhubeni budou. I budou mrtvá těla jejich za pokrm ptactvu nebeskému a šelmám zemským.'),
(1565602,54,24,16,5,'Nebo takto praví Hospodin: Nevcházej do domu smutku, aniž choď kvíliti, aniž jich lituj; odjal jsem zajisté pokoj svůj od lidu tohoto, dobrotivost i slitování, dí Hospodin.'),
(1565603,54,24,16,6,'Když pomrou velicí i malí v zemi této, nebudou pochováni, aniž kvíliti budou nad nimi, aniž se zřeží, aniž sobě lysiny zdělají pro ně.'),
(1565604,54,24,16,7,'Aniž jim dadí jísti, aby v truchlosti potěšovali jich nad mrtvým, aniž jich napojí z číše potěšení po otci jejich neb matce jejich.'),
(1565605,54,24,16,8,'Tolikéž do domu hodování nechoď, abys sedati měl s nimi při jídle a pití.'),
(1565606,54,24,16,9,'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Aj, já způsobím, aby nebývalo na místě tomto před očima vašima a za dnů vašich hlasu radosti, ani hlasu veselé, hlasu ženicha, ani hlasu nevěsty.'),
(1565607,54,24,16,10,'Když pak oznámíš lidu tomuto všecka slova tato, a řeknou-liť: Proč vyřkl Hospodin proti nám všecko zlé veliké toto, a jaká jest nepravost naše, aneb jaký hřích náš, jímž jsme hřešili proti Hospodinu Bohu svému?'),
(1565608,54,24,16,11,'Tedy rci jim: Proto že opustili mne otcové vaši, dí Hospodin, a chodíce za bohy cizími, sloužili jim, a klaněli se jim, mne pak opustili, a zákona mého neostříhali.'),
(1565609,54,24,16,12,'Vy pak mnohem jste hůře činili nežli otcové vaši; nebo aj, vy chodíte jeden každý podlé zdání srdce svého zlého, neposlouchajíce mne.'),
(1565610,54,24,16,13,'Pročež hodím vámi z země této do země, o níž nevíte vy, ani otcové vaši, a sloužiti budete tam bohům cizím dnem i nocí, dokudž neučiním vám milosti.'),
(1565611,54,24,16,14,'Protož aj, dnové jdou, dí Hospodin, v nichž nebude říkáno více: Živť jest Hospodin, kterýž vyvedl syny Izraelské z země Egyptské,'),
(1565612,54,24,16,15,'Ale: Živť jest Hospodin, kterýž vyvedl syny Izraelské z země půlnoční a ze všech zemí, do nichž je byl rozehnal, když je zase přivedu do země jejich, kterouž jsem dal otcům jejich.'),
(1565613,54,24,16,16,'Aj, já pošli k rybářům mnohým, dí Hospodin, aby je vylovili; potom pošli i k mnohým lovcům, aby je zlapali na všeliké hoře, a na všelikém pahrbku, i v děrách skalních.'),
(1565614,54,24,16,17,'Hledím na všecky cesty jejich, nejsouť tajné přede mnou, aniž jest skryta nepravost jejich před očima mýma.'),
(1565615,54,24,16,18,'I odplatím jim prvé dvojnásobně za nepravost jejich a hřích jejich, proto že zemi mnou poškvrnili těly mrtvými ohyzdnými, a ohavnostmi svými naplnili dědictví mé.'),
(1565616,54,24,16,19,'Hospodine, sílo má a hrade můj, i útočiště mé v den ssoužení, k toběť přijdou národové od končin země, a řeknou: Jistě žeť se falše drželi otcové naši, marnosti a právě neužitečných věcí.'),
(1565617,54,24,16,20,'Zdaliž udělá sobě člověk bohy, poněvadž sami nejsou bohové?'),
(1565618,54,24,16,21,'Protož aj, já způsobím to, aby poznali té chvíle, způsobím, aby poznali ruku mou i moc mou, a zvědít, že jméno mé jest Hospodin.'),
(1565619,54,24,17,1,'Hřích Judův napsán jest pérem železným, rafijí kamene přetvrdého, vyryt jest na tabuli srdce jejich, a na rozích oltářů vašich,'),
(1565620,54,24,17,2,'Tak když zpomínají synové jejich na oltáře jejich i háje jejich, pod dřívím zeleným, na pahrbcích vysokých.'),
(1565621,54,24,17,3,'Ó horo, s tím polem jmění tvé i všecky poklady tvé vydám v rozchvátání, pro hřích výsostí tvých, ve všech končinách tvých.'),
(1565622,54,24,17,4,'A ty musíš lhůtu dáti z strany sebe dědictví svému, kteréž jsem byl dal tobě, a podrobím tě v službu nepřátelům tvým v zemi, o níž nevíš; nebo jste oheň zanítili v prchlivosti mé, kterýž až na věky hořeti bude.'),
(1565623,54,24,17,5,'Takto praví Hospodin: Zlořečený ten muž, kterýž doufá v člověka, a kterýž klade tělo za rámě své, od Hospodina pak odstupuje srdce jeho.'),
(1565624,54,24,17,6,'Nebo bude podobný vřesu na pustině, kterýž necítí, když co přichází dobrého, ale bývá na vyprahlých místech na poušti v zemi slatinné, a v níž se nebydlí.'),
(1565625,54,24,17,7,'Požehnaný ten muž, kterýž doufá v Hospodina, a jehož naděje jest Hospodin.'),
(1565626,54,24,17,8,'Nebo podobný bude stromu štípenému při vodách, a při potoku pouštějícímu kořeny své, kterýž necítí, když přichází vedro, ale list jeho bývá zelený, a v rok suchý nestará se, aniž přestává nésti ovoce.'),
(1565627,54,24,17,9,'Nejlstivější jest srdce nade všecko, a nejpřevrácenější. Kdo vyrozumí jemu?'),
(1565628,54,24,17,10,'Já Hospodin, kterýž zpytuji srdce, a zkušuji ledví, tak abych odplatil jednomu každému podlé cesty jeho, podlé ovoce skutků jeho.'),
(1565629,54,24,17,11,'Koroptva škřečí, ale nevysedí. Tak kdož dobývá statku však s křivdou, v polovici dnů svých musí opustiti jej, a naposledy bude bláznem.'),
(1565630,54,24,17,12,'Místo svatyně naší, stolice slavná Nejvyššího, věčně trvá.'),
(1565631,54,24,17,13,'Ó naděje Izraelova, Hospodine, všickni, kteříž tě opouštějí, nechť jsou zahanbeni. Kárání má v zemi této nechť jsou zapsána; nebo opustili pramen vod živých, Hospodina.'),
(1565632,54,24,17,14,'Uzdrav mne, Hospodine, a zdráv budu; vysvoboď mne, a vysvobozen budu, ty jsi zajisté chvála má.'),
(1565633,54,24,17,15,'Aj, oni říkají mi: Kdež jest to, což předpovídal Hospodin? Nechť již přijde.'),
(1565634,54,24,17,16,'Ješto jsem já se nevetřel, abych pastýřem byl tvým, a dne bolesti nebylť jsem žádostiv, ty víš. Cožkoli vyšlo z rtů mých, před oblíčejem tvým jest.'),
(1565635,54,24,17,17,'Nebudiž mi k strachu, útočiště mé jsi v čas trápení.'),
(1565636,54,24,17,18,'Nechť jsou zahanbeni, kteříž mne stihají, já pak ať nejsem zahanben; nechť se oni děsí, já pak ať se neděsím. Uveď na ně den trápení, a dvojím setřením setři je.'),
(1565637,54,24,17,19,'Takto řekl Hospodin ke mně: Jdi a postav se v bráně lidu tohoto, skrze kterouž chodívají králové Judští, a skrze kterouž vycházívají, anobrž ve všech branách Jeruzalémských,'),
(1565638,54,24,17,20,'A rci jim: Slyšte slovo Hospodinovo, králové Judští, i všecken Judo, a všickni obyvatelé Jeruzaléma, kteříž chodíváte skrze brány tyto:'),
(1565639,54,24,17,21,'Takto praví Hospodin: Vystříhejte se s pilností, abyste nenosili břemen v den sobotní, ani vnášeli skrze brány Jeruzalémské.'),
(1565640,54,24,17,22,'Ani nevynášejte břemen z domů svých v den sobotní, a žádného díla nedělejte, ale svěťte den sobotní, jakž jsem přikázal otcům vašim.'),
(1565641,54,24,17,23,'(Však neuposlechli, aniž naklonili ucha svého, ale zatvrdili šíji svou, neposlouchajíce a nepřijímajíce naučení.)');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565642,54,24,17,24,'Stane se zajisté, jestliže s ochotností mne uposlechnete, dí Hospodin, abyste nenosili břemen skrze brány města tohoto v den sobotní, ale světili den sobotní, nedělajíce v něm žádného díla,'),
(1565643,54,24,17,25,'Že poberou se skrze brány města tohoto králové i knížata sedící na stolici Davidově, jezdíce na vozích i na koních, oni i knížata jejich, muži Judští a obyvatelé Jeruzalémští, a státi bude toto město až na věčnost.'),
(1565644,54,24,17,26,'I budou přicházeti z měst Judských a z okolí Jeruzaléma, jakož z země Beniaminovy, tak z roviny, i z té hory, i od poledne, nesouce zápal, a obět i dar s kadidlem, také i díků činění nesouce do domu Hospodinova.'),
(1565645,54,24,17,27,'Jestliže pak neuposlechnete mne, abyste světili den sobotní, a nenosili břemen, chodíce skrze brány Jeruzalémské v den sobotní, tedy zanítím oheň v branách jeho, kterýžto zžíře paláce Jeruzalémské, a neuhasne.'),
(1565646,54,24,18,1,'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, řkoucí:'),
(1565647,54,24,18,2,'Vstaň a sejdi do domu hrnčířova, a tam způsobím to, abys slyšel slova má.'),
(1565648,54,24,18,3,'I sešel jsem do domu hrnčířova, a aj, on dělal dílo na kruzích.'),
(1565649,54,24,18,4,'Když se pak zkazila nádoba v ruce hrnčířově, kterouž on dělal z hliny, tehdy zase udělal z ní nádobu jinou, jakouž se dobře líbilo hrnčíři udělati.'),
(1565650,54,24,18,5,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1565651,54,24,18,6,'Zdaliž jako hrnčíř tento nemohl bych nakládati s vámi, ó dome Izraelský? dí Hospodin. Aj, jakož hlina v ruce hrnčíře, tak jste vy v ruce mé, ó dome Izraelský.'),
(1565652,54,24,18,7,'Mluvil-li bych proti národu a proti království, že je v okamžení vypléním a zkazím, i vyhubím,'),
(1565653,54,24,18,8,'Však odvrátil-li by se národ ten od nešlechetnosti své, proti němuž bych mluvil: i já litoval bych toho zlého, kteréž jsem myslil učiniti jemu.'),
(1565654,54,24,18,9,'Zase mluvil-li bych o národu a o království, že je v okamžení vzdělám a vštípím,'),
(1565655,54,24,18,10,'Však činil-li by, což zlého jest před očima mýma, neposlouchaje hlasu mého: i já litoval bych dobrodiní toho, kteréž bych řekl učiniti jemu.'),
(1565656,54,24,18,11,'Protož nyní rci mužům Judským i obyvatelům Jeruzalémským, řka: Takto praví Hospodin: Aj, já strojím na vás zlou věc, a obrátím na vás pohromu; navraťtež se již jeden každý od cesty své zlé, a polepšte cest svých i předsevzetí svých.'),
(1565657,54,24,18,12,'Kteřížto řekli: To nic, nebo za myšlénkami svými půjdeme, a jeden každý zdání srdce svého nešlechetného vykonávati budeme.'),
(1565658,54,24,18,13,'Protož takto praví Hospodin: Vyptejte se nyní mezi pohany, slýchal-li kdo takové věci? Mrzkosti veliké dopustila se panna Izraelská.'),
(1565659,54,24,18,14,'Zdaliž kdo pohrdá čerstvou vodou Libánskou z skály? Zdaž pohrdají vodami studenými odjinud běžícími?'),
(1565660,54,24,18,15,'Lid pak můj zapomenuvše se na mne, kadí marnosti. Nebo k úrazu je přivodí na cestách jejich, na stezkách starobylých, chodíce stezkami cesty neprotřené,'),
(1565661,54,24,18,16,'Tak abych musil obrátiti zemi jejich v poušť na odivu věčnou; každý, kdož by šel skrze ni, aby se užasl, a pokynul hlavou svou.'),
(1565662,54,24,18,17,'Větrem východním rozptýlím je před nepřítelem; hřbetem a ne tváří pohledím na ně v čas bídy jejich.'),
(1565663,54,24,18,18,'I řekli: Poďte a vymyslme proti Jeremiášovi nějakou chytrost; neboť nezhyne zákon od kněze, ani rada od moudrého, ani slovo od proroka. Poďte a zarazme jej jazykem, a nemějme pozoru na žádná slova jeho.'),
(1565664,54,24,18,19,'Pozoruj mne, Hospodine, a slyš hlas těch, kteříž se vadí se mnou.'),
(1565665,54,24,18,20,'Zdaliž má odplacováno býti za dobré zlým, že mi jámu kopají? Rozpomeň se, že jsem se postavoval před oblíčejem tvým, abych se přimlouval k jejich dobrému, a odvrátil prchlivost tvou od nich.'),
(1565666,54,24,18,21,'Protož dopusť na syny jejich hlad, a způsob to, ať jsou násilně zmordování mečem, a nechť jsou ženy jejich osiřelé a ovdovělé, a muži jejich ať jsou ukrutně zmordováni, a mládenci jejich zbiti mečem v boji.'),
(1565667,54,24,18,22,'Nechť jest slýchati křik z domů jejich, když přivedeš na ně vojsko náhle. Nebo vykopali jámu, aby popadli mne, a osídla polékli nohám mým;'),
(1565668,54,24,18,23,'Ješto ty, Hospodine, povědom jsi vší rady jejich o mém usmrcení. Nebuď milostiv nepravosti jejich, a hříchu jejich před tváří svou neshlazuj, ale nechť jsou k úrazu dostrčeni před oblíčejem tvým, a v čas prchlivosti své s nimi zacházej.'),
(1565669,54,24,19,1,'Takto řekl Hospodin: Jdi a zjednej báni záhrdlitou od hrnčíře, hliněnou, a pojma některé z starších lidu a z starších kněží,'),
(1565670,54,24,19,2,'Vejdi do údolí Benhinnom, kteréž jest u vrat brány východní, a ohlašuj tam slova ta, kteráž mluviti budu tobě.'),
(1565671,54,24,19,3,'A rci: Slyšte slovo Hospodinovo, králové Judští i obyvatelé Jeruzalémští: Takto praví Hospodin zástupů, Bůh Izraelský: Aj, já uvedu bídu na místo toto, o kteréž kdokoli uslyší, zníti mu bude v uších jeho,'),
(1565672,54,24,19,4,'Proto že mne opustili, a poškvrnili místa tohoto, kadíce na něm bohům cizím, jichž neznali oni, ani otcové jejich, ani králové Judští, a naplnili toto místo krví nevinných.'),
(1565673,54,24,19,5,'Vzdělali také výsosti Bálovi, aby pálili syny své ohněm v zápaly Bálovi, čehož jsem nepřikázal, aniž jsem o tom mluvil, nýbrž ani nevstoupilo na mé srdce.'),
(1565674,54,24,19,6,'Protož aj, dnové jdou, dí Hospodin, v nichž nebude slouti více toto místo Tofet, ani údolí Benhinnom, ale údolí mordu.'),
(1565675,54,24,19,7,'Nebo v nic obrátím radu Judovu i Jeruzalémských v místě tomto, způsobě to, aby padli od meče před nepřátely svými, a od ruky těch, kteříž hledají bezživotí jejich, i dám mrtvá těla jejich za pokrm ptactvu nebeskému a šelmám zemským.'),
(1565676,54,24,19,8,'Obrátím také město toto v poušť na odivu. Každý, kdožkoli půjde mimo ně, užasne se, a ckáti bude pro všelijaké rány jeho.'),
(1565677,54,24,19,9,'A způsobím to, že žráti budou maso synů svých a maso dcer svých, tolikéž jeden každý maso bližního svého žráti bude, v obležení a v ssoužení, kterýmž ssouží je nepřátelé jejich, a ti, kteříž hledají bezživotí jejich.'),
(1565678,54,24,19,10,'Potom roztluc tu záhrdlitou báni před očima těch lidí, kteříž půjdou s tebou,'),
(1565679,54,24,19,11,'A rci jim: Takto praví Hospodin zástupů: Tak potluku lid tento i město toto, jako ten, kdož rozráží nádobu hrnčířskou, kteráž nemůže opravena býti více, a v Tofet pochovávati budou, proto že nebude žádného místa ku pohřbu.'),
(1565680,54,24,19,12,'Tak učiním místu tomuto, dí Hospodin, i obyvatelům jeho, a naložím s městem tímto tak jako s Tofet.'),
(1565681,54,24,19,13,'Nebo budou domové Jeruzalémských i domové králů Judských tak jako toto místo Tofet zanečištěni se všechněmi domy těmi, na jejichž střechách kadili všemu vojsku nebeskému, a obětovali oběti mokré bohům cizím.'),
(1565682,54,24,19,14,'Tedy navrátiv se Jeremiáš z Tofet, kamž jej byl poslal Hospodin, aby prorokoval tam, postavil se v síňci domu Hospodinova, a řekl ke všemu lidu:'),
(1565683,54,24,19,15,'Takto praví Hospodin zástupů, Bůh Izraelský: Aj, já uvedu na město toto i na všecka města jeho všecko to zlé, kteréž jsem vyřkl proti němu; nebo zatvrdili šíji svou, aby neposlouchali slov mých.'),
(1565684,54,24,20,1,'Tedy slyšev Paschur syn Immerův, kněz, kterýž byl přední správce v domě Hospodinově, Jeremiáše prorokujícího o těch věcech,'),
(1565685,54,24,20,2,'Ubil Paschur Jeremiáše proroka, a dal jej do vězení v bráně Beniaminově hořejší, kteráž byla při domě Hospodinově.'),
(1565686,54,24,20,3,'Stalo se pak nazejtří, když vyvedl Paschur Jeremiáše z vězení, že řekl jemu Jeremiáš: Nenazval Hospodin jména tvého Paschur, ale Magor missabib.'),
(1565687,54,24,20,4,'Nebo takto praví Hospodin: Aj, já pustím na tebe strach, na tebe i na všecky přátely tvé, kteříž padnou od meče nepřátel svých, načež oči tvé hleděti budou, když všecken lid Judský vydám v ruku krále Babylonského, kterýž zavede je do Babylona, a mečem je pobije.'),
(1565688,54,24,20,5,'Vydám i všelijaké bohatství města tohoto, a všecko úsilé jeho, i všelijakou věc drahou jeho, i všecky poklady králů Judských vydám v ruku nepřátel jejich, a rozchvátají je, i poberou je, a dovezou je do Babylona.'),
(1565689,54,24,20,6,'Ty pak Paschur i všickni, kteříž bydlí v domě tvém, půjdete do zajetí, a do Babylona se dostaneš, a tam umřeš, i tam pochován budeš ty i všickni milující tebe, jimž jsi prorokoval lživě.'),
(1565690,54,24,20,7,'Namlouvals mne, Hospodine, a dalť jsem se přemluviti; silnějšís byl nežli já, protož zmocnils se mne. Jsem v posměchu každý den, každý se mi posmívá.'),
(1565691,54,24,20,8,'Nebo jakž jsem začal mluviti, úpím, pro ukrutenství a zhoubu křičím; slovo zajisté Hospodinovo jest mi ku potupě a ku posměchu každého dne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565692,54,24,20,9,'I řekl jsem: Nebuduť ho připomínati, ani mluviti více ve jménu jeho. Ale jest v srdci mém jako oheň hořící, zavřený v kostech mých, jehož snažuje se zdržeti, však nemohu,'),
(1565693,54,24,20,10,'Ačkoli slýchám utrhání mnohých, i Magor missabiba, říkajících: Povězte něco na něj, a oznámíme to králi. Všickni, kteříž by měli býti přátelé moji, číhají na poklesnutí mé, říkajíce: Snad někde podveden bude, a zmocníme se ho, a pomstíme se nad ním.'),
(1565694,54,24,20,11,'Ale Hospodin jest se mnou jakožto rek udatný, protož ti, kteříž mne stihají, zurážejí se, a neodolají; styděti se budou náramně, nebo se jim šťastně nezvede, aniž potupa věčná v zapomenutí dána bude.'),
(1565695,54,24,20,12,'Protož ó Hospodine zástupů, kterýž zkušuješ spravedlivého, kterýž spatřuješ ledví a srdce, nechť se podívám na pomstu tvou nad nimi, tobě zajisté zjevil jsem při svou.'),
(1565696,54,24,20,13,'Zpívejte Hospodinu, chvalte Hospodina, že vytrhl duši nuzného z ruky nešlechetných.'),
(1565697,54,24,20,14,'Zlořečený ten den, v němžto zplozen jsem, den, v němž porodila mne matka má, ať není požehnaný.'),
(1565698,54,24,20,15,'Zlořečený ten muž, kterýž zvěstoval otci mému, chtěje zvláštně obradovati jej, řka: Narodiloť se dítě pohlaví mužského.'),
(1565699,54,24,20,16,'A nechť jest ten muž podobný městům, kteráž podvrátil Hospodin, a neželel; nebo slyšel křik v jitře, a provyskování v čas polední.'),
(1565700,54,24,20,17,'Ó že mne neusmrtil od života, ješto by mi matka má byla hrobem mým, a život její věčně těhotný.'),
(1565701,54,24,20,18,'Proč jsem jen z života vyšel, abych okoušel těžkosti a zámutku, a aby stráveni byli v pohanění dnové moji?'),
(1565702,54,24,21,1,'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, když poslal k němu král Sedechiáš Paschura syna Malkiášova a Sofoniáše syna Maaseiášova, kněze, aby řekli:'),
(1565703,54,24,21,2,'Poraď se medle o nás s Hospodinem, nebo Nabuchodonozor král Babylonský bojuje proti nám, zdali by snad naložil Hospodin s námi podlé všech divných skutků svých, aby on odtáhl od nás.'),
(1565704,54,24,21,3,'Tedy řekl Jeremiáš k nim: Tak rcete Sedechiášovi:'),
(1565705,54,24,21,4,'Takto praví Hospodin Bůh Izraelský: Aj, já odvrátím nástroje válečné, kteréž jsou v rukou vašich, jimiž vy bojujete proti králi Babylonskému a Kaldejským, kteříž oblehli vás vně za zdí, a shromáždím je do prostřed města tohoto.'),
(1565706,54,24,21,5,'Bojovati zajisté budu já proti vám rukou vztaženou a ramenem silným, a to v hněvě a v rozpálení i v prchlivosti veliké.'),
(1565707,54,24,21,6,'A raním obyvatele města tohoto, tak že lidé i hovada morem velikým pomrou.'),
(1565708,54,24,21,7,'Potom pak (dí Hospodin), dám Sedechiáše krále Judského a služebníky jeho i lid, totiž ty, kteříž pozůstanou v městě tomto po moru, po meči a po hladu, v ruku Nabuchodonozora krále Babylonského, a v ruku nepřátel jejich, a tak v ruku hledajících bezživotí jejich. Kterýžto je zbije ostrostí meče, neodpustí jim, aniž jich šanovati bude, aniž se smiluje.'),
(1565709,54,24,21,8,'Protož rci lidu tomuto: Takto praví Hospodin: Aj, já kladu před vás cestu života i cestu smrti.'),
(1565710,54,24,21,9,'Kdokoli zůstane v městě tomto, zahyne od meče, neb hladem, neb morem, ale kdož vyjde a poddá se Kaldejským, kteříž oblehli vás, jistotně živ zůstane, a bude míti život svůj místo kořisti.'),
(1565711,54,24,21,10,'Nebo postavil jsem zůřivou tvář svou proti městu tomuto k zlému, a ne k dobrému, dí Hospodin. V ruku krále Babylonského vydáno bude, i vypálí je ohněm.'),
(1565712,54,24,21,11,'Domu pak krále Judského rci: Slyšte slovo Hospodinovo,'),
(1565713,54,24,21,12,'Ó dome Davidův, takto praví Hospodin: Držívejte každého jitra soud, a vychvacujte obloupeného z ruky násilníka, aby nevyšla jako oheň prchlivost má, a nehořela, tak že by nebylo žádného, kdo by uhasiti mohl, pro nešlechetnost předsevzetí vašich.'),
(1565714,54,24,21,13,'Aj já, dí Hospodin, na tebe, kteráž přebýváš v údolí tomto, skálo roviny této, kteříž říkáte: Kdo by přitáhl na nás, aneb kdo by všel do příbytků našich?'),
(1565715,54,24,21,14,'Nebo trestati vás budu podlé skutků vašich, dí Hospodin, a zanítím oheň v lese tvém, kterýž zžíře všecko vůkol něho.'),
(1565716,54,24,22,1,'Takto řekl Hospodin: Sejdi do domu krále Judského, a mluv tam slovo toto,'),
(1565717,54,24,22,2,'A rci: Slyš slovo Hospodinovo, králi Judský, kterýž sedíš na stolici Davidově, ty i služebníci tvoji i lid tvůj, kteříž chodíte skrze brány tyto.'),
(1565718,54,24,22,3,'Takto praví Hospodin: Konejte soud a spravedlnost, a vychvacujte obloupeného z ruky násilníka; příchozímu tolikéž, sirotku, ani vdově nečiňte křivdy, aniž jich utiskujte, a krve nevinné nevylévejte na místě tomto.'),
(1565719,54,24,22,4,'Nebo budete-li to pilně vykonávati, jistě že poberou se skrze brány domu tohoto králové, sedící místo Davida na stolici jeho, jezdíce na vozích, neb na koních, král s služebníky svými i s lidem svým.'),
(1565720,54,24,22,5,'Jestliže pak neuposlechnete slov těchto, skrze sebe přisahám, dí Hospodin, že poušť bude dům tento.'),
(1565721,54,24,22,6,'Nebo takto praví Hospodin o domu krále Judského: Byl jsi mi jako Galád a vrch Libánský, ale obrátím tě jistotně v poušť jako města, v nichž se bydliti nemůže.'),
(1565722,54,24,22,7,'A přistrojím na tebe zhoubce, jednoho každého se zbrojí jeho, kteřížto zpodtínají nejvýbornější cedry tvé, a vmecí na oheň.'),
(1565723,54,24,22,8,'A když půjdou národové mnozí mimo město toto, a řekne jeden druhému: Proč tak učinil Hospodin městu tomuto velikému?'),
(1565724,54,24,22,9,'Tedy řeknou: Proto že opustili smlouvu Hospodina Boha svého, a klaněli se bohům cizím a sloužili jim.'),
(1565725,54,24,22,10,'Neplačtež mrtvého, aniž ho litujte, ale ustavičně plačte příčinou toho, kterýž odchází; neboť se nenavrátí více, aby pohleděl na zemi, v níž se narodil.'),
(1565726,54,24,22,11,'Nebo takto praví Hospodin o Sallumovi synu Joziáše, krále Judského, kterýž kraluje místo Joziáše otce svého: Když vyjde z místa tohoto, nenavrátí se sem více.'),
(1565727,54,24,22,12,'Ale tam v tom místě, kamž jej zastěhují, umře, a tak země této neuzří více.'),
(1565728,54,24,22,13,'Běda tomu, kdož staví dům svůj s útiskem, a paláce své s křivdou, kterýž bližního svého v službu podrobuje darmo, mzdy pak jeho nedává jemu;'),
(1565729,54,24,22,14,'Kterýž říká: Vystavím sobě dům veliký a paláce prostranné, kterýž prolamuje sobě okna, a tafluje cedrovím, a maluje barvou.'),
(1565730,54,24,22,15,'Zdaliž kralovati budeš, že se pleteš v to cedrové stavení? Otec tvůj zdaliž nejídal a nepíjel? Když konal soud a spravedlnost, tedy dobře bylo jemu.'),
(1565731,54,24,22,16,'Když soudíval při chudého a nuzného, tedy dobře bylo. Zdaliž mně to není známé? dí Hospodin.'),
(1565732,54,24,22,17,'Ale oči tvé i srdce tvé nehledí než lakomství tvého, a abys krev nevinnou proléval, a nátisk a křivdu činil.'),
(1565733,54,24,22,18,'Protož takto praví Hospodin o Joakimovi synu Joziáše, krále Judského: Nebudouť ho kvíliti: Ach, bratře můj, aneb ach, sestro. Nebudou ho kvíliti: Ach, pane, aneb ach, kdež důstojnost jeho?'),
(1565734,54,24,22,19,'Pohřbem osličím pohřben bude, vyvlečen a vyvržen jsa za brány Jeruzalémské.'),
(1565735,54,24,22,20,'Vstup na Libán a křič, i na hoře Bázan vydej hlas svůj; křič také přes brody, když potříni budou všickni milovníci tvoji.'),
(1565736,54,24,22,21,'Mluvíval jsem s tebou v největším štěstí tvém, říkávalas: Nebuduť poslouchati. Tať jest cesta tvá od dětinství tvého; neuposlechlas zajisté hlasu mého.'),
(1565737,54,24,22,22,'Všecky pastýře tvé zpase vítr, a milovníci tvoji v zajetí půjdou. Tehdáž jistě hanbiti a styděti se budeš za všelikou nešlechetnost svou.'),
(1565738,54,24,22,23,'Ó ty, kteráž jsi usadila se na Libánu, jenž se hnízdíš na cedroví, jak milostná budeš, když na tě přijdou svírání a bolest jako rodičky!'),
(1565739,54,24,22,24,'Živť jsem já, dí Hospodin, že byť pak byl Koniáš syn Joakima, krále Judského, prstenem pečetním na mé ruce pravé, však tě i odtud strhnu.'),
(1565740,54,24,22,25,'A vydám tě v ruku těch, kteříž hledají bezživotí tvého, a v ruku těch, jejichž ty se oblíčeje lekáš, totiž v ruku Nabuchodonozora krále Babylonského, a v ruku Kaldejských.'),
(1565741,54,24,22,26,'A hodím tebou i matkou tvou, kteráž tě porodila, do země cizí, tam, kdež jste se nezrodili, a tam zemřete.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565742,54,24,22,27,'Do země pak, po níž toužiti budete, abyste se navrátili tam, tam se nenavrátíte.'),
(1565743,54,24,22,28,'Zdaliž modlou ničemnou, kteráž roztřískána bývá, bude muž tento Koniáš? Zdali nádobou, v níž není žádné líbosti? Proč by vyházíni byli on i símě jeho, a uvrženi do země, o níž nevědí?'),
(1565744,54,24,22,29,'Ó země, země, země, slyš slovo Hospodinovo.'),
(1565745,54,24,22,30,'Takto praví Hospodin: Zapište to, že muž tento bez dětí bude, a že se jemu nepovede šťastně za dnů jeho. Anobrž nepovede se šťastně i tomu muži, kterýž by z semene jeho seděl na stolici Davidově, a panoval ještě nad Judou.'),
(1565746,54,24,23,1,'Běda pastýřům hubícím a rozptylujícím stádce pastvy mé, dí Hospodin.'),
(1565747,54,24,23,2,'Protož takto praví Hospodin Bůh Izraelský o pastýřích, kteříž pasou lid můj: Vy rozptylujete ovce mé, anobrž rozháníte je, a nenavštěvujete jich; aj, já navštívím vás pro nešlechetnost předsevzetí vašich, dí Hospodin.'),
(1565748,54,24,23,3,'Ostatek pak ovcí svých já shromáždím ze všech zemí, do nichž jsem je rozehnal, a přivedu je zase do ovčinců jejich, kdežto ploditi a množiti se budou.'),
(1565749,54,24,23,4,'Nadto ustanovím nad nimi pastýře, kteříž by je pásli, aby se nebály více, ani strachovaly, ani hynuly, dí Hospodin.'),
(1565750,54,24,23,5,'Aj, dnové jdou, dí Hospodin, v nichž vzbudím Davidovi výstřelek spravedlivý, i kralovati bude král, a šťastně se jemu povede; soud zajisté a spravedlnost na zemi konati bude.'),
(1565751,54,24,23,6,'Za dnů jeho spasen bude Juda, a Izrael bydliti bude bezpečně, a toť jest jméno jeho, kterýmž ho nazývati bude: Hospodin spravedlnost naše.'),
(1565752,54,24,23,7,'Protož aj, dnové jdou, dí Hospodin,v nichž nebude říkáno více: Živť jest Hospodin, kterýž vyvedl syny Izraelské z země Egyptské,'),
(1565753,54,24,23,8,'Ale: Živť jest Hospodin, kterýž vyvedl a kterýž zprovodil símě domu Izraelského z země půlnoční i ze všech zemí, do nichž jsem byl je rozehnal, když se osadí v zemi své.'),
(1565754,54,24,23,9,'Příčinou proroků potříno jest srdce mé ve mně, pohnuly se všecky kosti mé; jsem jako člověk opilý, a jako muž, kteréhož rozešlo víno, pro Hospodina a pro slova svatosti jeho.'),
(1565755,54,24,23,10,'Nebo cizoložníků plná jest tato země, a příčinou křivých přísah kvílí země, usvadla pastviska na poušti; jest zajisté utiskování těchto nešlechetné, a moc jejich nepravá.'),
(1565756,54,24,23,11,'Nebo jakož prorok, tak kněz pokrytství páchají. Také v domě svém nacházím nešlechetnost jejich, dí Hospodin.'),
(1565757,54,24,23,12,'Pročež budou míti cestu svou podobnou plzkosti v mrákotě, na níž postrčeni budou a padnou, když uvedu na ně bídu v čas navštívení jejich, dí Hospodin.'),
(1565758,54,24,23,13,'Při prorocích zajisté Samařských viděl jsem nesmyslnost; prorokovali skrze Bále, a svodili lid můj Izraelský.'),
(1565759,54,24,23,14,'Ale při prorocích Jeruzalémských vidím hroznou věc, že cizoložíce a se lží se obcházejíce, posilňují také rukou nešlechetníků, aby se neobrátil žádný od nešlechetnosti své. Mám všecky za podobné Sodomě, a obyvatele jeho za podobné Gomoře.'),
(1565760,54,24,23,15,'Protož takto praví Hospodin zástupů o prorocích těchto: Aj, já nakrmím je pelynkem, a napojím je vodami jedovatými; nebo od proroků Jeruzalémských vyšla poškvrna na všecku tuto zemi.'),
(1565761,54,24,23,16,'Takto praví Hospodin zástupů: Neposlouchejtež slov těch proroků, jenž prorokují vám, prázdných vás zanechávajíce. Vidění srdce svého mluví, ne z úst Hospodinových.'),
(1565762,54,24,23,17,'Ustavičně říkají těm, kteříž mnou pohrdají: Pravil Hospodin: Pokoj míti budete, a každému chodícímu podlé zdání srdce svého říkají: Nepřijdeť na vás nic zlého.'),
(1565763,54,24,23,18,'Nebo kdož jest stál v radě Hospodinově, a viděl neb slyšel slovo jeho? Kdo pozoroval slova jeho, neb vyslechl je?'),
(1565764,54,24,23,19,'Aj, vichřice Hospodinova s prchlivostí vyjde, a to vichřice trvající; nad hlavou nešlechetných trvati bude.'),
(1565765,54,24,23,20,'Neodvrátíť se hněv Hospodinův, dokudž neučiní a nevykoná úmyslu srdce svého. A tehdáž porozumíte tomu cele,'),
(1565766,54,24,23,21,'Žeť jsem neposílal těch proroků, ale sami běželi, že jsem nemluvil k nim, a však oni prorokovali.'),
(1565767,54,24,23,22,'Nebo byť byli stáli v radě mé, jistě že by byli ohlašovali slova má lidu mému, a byliť by je odvraceli od cesty jejich zlé, a od nešlechetnosti předsevzetí jejich.'),
(1565768,54,24,23,23,'Zdaliž jsem já Bůh jen z blízka? dí Hospodin. A nejsem Bůh i z daleka?'),
(1565769,54,24,23,24,'Zdaž se ukryje kdo v skrýších, abych já ho neshlédl? dí Hospodin. Zdaliž nebe i země já nenaplňuji? dí Hospodin.'),
(1565770,54,24,23,25,'Slýchávámť, co říkají ti proroci, kteříž prorokují lež ve jménu mém, říkajíce: Měl jsem sen, měl jsem sen.'),
(1565771,54,24,23,26,'I dokudž to bude? Zdaliž v srdci těch proroků, kteříž prorokují, není lež? Anobrž jsou proroci lsti srdce svého,'),
(1565772,54,24,23,27,'Kteříž obmýšlejí to, jak by vyrazili z paměti lidu mému jméno mé sny svými, kteréž vypravují jeden každý bližnímu svému, jako se zapomněli otcové jejich na jméno mé za příčinou Bále.'),
(1565773,54,24,23,28,'Prorok, kterýž má sen, nechť vypravuje sen, ale kterýž má slovo mé, nechť mluví slovo mé právě. Co jest té plevě do pšenice? dí Hospodin.'),
(1565774,54,24,23,29,'Zdaliž není slovo mé takové jako oheň, dí Hospodin, a jako kladivo rozrážející skálu?'),
(1565775,54,24,23,30,'Protož aj já, dí Hospodin, proti těm prorokům, kteříž ukrádají slova má jeden každý před bližním svým.'),
(1565776,54,24,23,31,'Aj já, dí Hospodin, proti těm prorokům, kteříž chlubně mluví, říkajíce: Praví Hospodin.'),
(1565777,54,24,23,32,'Aj já, dí Hospodin, proti těm, kteříž prorokují sny lživé, a vypravujíce je, svodí lid můj lžmi svými a žvavostí svou, ješto jsem já jich neposlal, aniž jsem jim přikázal. Pročež naprosto nic neprospívají lidu tomuto, dí Hospodin.'),
(1565778,54,24,23,33,'Protož, když by se tázal tebe lid tento, neb některý prorok neb kněz, řka: Jaké jest břímě Hospodinovo? tedy rci jim: Jaké břímě? I to: Opustím vás, dí Hospodin.'),
(1565779,54,24,23,34,'Nebo proroka a kněze toho i lid ten, kterýž by řekl: Břímě Hospodinovo, jistě trestati budu muže toho i dům jeho.'),
(1565780,54,24,23,35,'Ale takto říkejte jeden každý bližnímu svému a jeden každý bratru svému: Co odpověděl Hospodin? aneb: Co mluvil Hospodin?'),
(1565781,54,24,23,36,'Břemene pak Hospodinova nepřipomínejte více, sic by břemenem bylo jednomu každému slovo jeho, když byste převraceli slova Boha živého, Hospodina zástupů, Boha našeho.'),
(1565782,54,24,23,37,'Takto říkati budeš proroku: Coť odpověděl Hospodin? aneb: Co mluvil Hospodin?'),
(1565783,54,24,23,38,'Ale poněvadž říkáte: Břímě Hospodinovo, tedy takto praví Hospodin: Poněvadž říkáte slovo to: Břímě Hospodinovo, ješto jsem posílal k vám, říkaje: Neříkejte: Břímě Hospodinovo,'),
(1565784,54,24,23,39,'Protož aj, já jistě zapomenu se na vás do konce, a zavrhu vás i to město, kteréž jsem byl dal vám i otcům vašim, od tváři své,'),
(1565785,54,24,23,40,'A uvedu na vás pohanění věčné i potupu věčnou, kteráž nepřijde v zapomenutí.'),
(1565786,54,24,24,1,'Ukázal mi Hospodin, a aj, dva košové fíků postaveni byli před chrámem Hospodinovým, když byl přestěhoval Nabuchodonozor král Babylonský Jekoniáše syna Joakimova, krále Judského, a knížata Judská, i tesaře a kováře z Jeruzaléma, a přivedl je do Babylona.'),
(1565787,54,24,24,2,'Jeden koš byl fíků velmi dobrých, jacíž bývají fíkové ranní, druhý pak koš fíků velmi zlých, jakýchž nelze jísti pro trpkost.'),
(1565788,54,24,24,3,'Tedy řekl mi Hospodin: Co vidíš, Jeremiáši? I řekl jsem: Fíky, dobré fíky, a to velmi dobré, zlé pak, a to velmi zlé, jichž nelze jísti pro trpkost.'),
(1565789,54,24,24,4,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1565790,54,24,24,5,'Takto praví Hospodin, Bůh Izraelský: Jako fíkové tito dobří, tak mně příjemní budou zajatí Judští, kteréž jsem zaslal z místa tohoto do země Kaldejské k dobrému.'),
(1565791,54,24,24,6,'Obrátím zajisté oči své k nim k dobrému, a přivedu je zase do země této, kdežto vzdělám je, a nezkazím, štípím je, a nevypléním.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565792,54,24,24,7,'Nebo dám jim srdce, aby znali mne, že já jsem Hospodin. I budou mým lidem, a já budu jejich Bohem, když se obrátí ke mně celým srdcem svým.'),
(1565793,54,24,24,8,'Naodpor, jako fíky zlé, kterýchž nelze jísti pro trpkost, tak zavrhu (toť zajisté praví Hospodin), Sedechiáše krále Judského s knížaty jeho, a ostatek Jeruzalémských pozůstalých v zemi této, i ty, kteříž bydlí v zemi Egyptské.'),
(1565794,54,24,24,9,'Vydám je, pravím, v posmýkání k zlému po všech královstvích země, v pohanění a v přísloví, v rozprávku a v proklínání po všech těch místech, kamž je rozženu.'),
(1565795,54,24,24,10,'A budu posílati na ně meč, hlad a mor, dokudž by do konce vyhlazeni nebyli z země, kterouž jsem byl dal jim i otcům jejich.'),
(1565796,54,24,25,1,'Slovo, kteréž se stalo k Jeremiášovi proti všemu lidu Judskému, léta čtvrtého Joakima syna Joziášova, krále Judského, (jenž jest první rok Nabuchodonozora krále Babylonského),'),
(1565797,54,24,25,2,'Kteréž mluvil Jeremiáš prorok ke všemu lidu Judskému, i ke všechněm obyvatelům Jeruzalémským, řka:'),
(1565798,54,24,25,3,'Od třináctého léta Joziáše syna Amonova, krále Judského, až do tohoto dne, po těchto třimecítma let, bývalo slovo Hospodinovo ke mně, kteréž jsem vám mluvíval, ráno přivstávaje, a to ustavičně, ale neposlouchali jste.'),
(1565799,54,24,25,4,'Posílal také Hospodin k vám všecky slouhy své proroky, ráno přivstávaje, a to ustavičně, (jichžto neposlouchali jste, aniž jste naklonili ucha svého, abyste slyšeli).'),
(1565800,54,24,25,5,'Kteříž říkali: Navraťtež se již jeden každý z cesty své zlé a od nešlechetnosti předsevzetí svých, a tak osazujte se v té zemi, kterouž dal Hospodin vám i otcům vašim od věků až na věky.'),
(1565801,54,24,25,6,'A nechoďte za bohy cizími, abyste sloužiti měli jim, aniž se jim klanějte, aniž hněvejte mne dílem rukou svých, a neučinímť vám zle.'),
(1565802,54,24,25,7,'Ale neposlouchali jste mne, dí Hospodin, abyste jen hněvali mne dílem rukou svých k svému zlému.'),
(1565803,54,24,25,8,'Protož takto praví Hospodin zástupů: Proto že jste neuposlechli slov mých,'),
(1565804,54,24,25,9,'Aj, já pošli, a pojmu všecky národy půlnoční, dí Hospodin, i k Nabuchodonozorovi králi Babylonskému, služebníku svému, a přivedu je na zemi tuto i na obyvatele její, i na všecky národy tyto okolní, kteréž jako proklaté vyhladím, a způsobím to, aby byli k užasnutí, na odivu, a poustkou věčnou.'),
(1565805,54,24,25,10,'Také způsobím to, aby zahynul jim hlas radosti i hlas veselé, hlas ženicha i hlas nevěsty, hluk žernovu i světlo svíce.'),
(1565806,54,24,25,11,'I bude všecka země tato pustinou a pouští, a sloužiti budou národové tito králi Babylonskému sedmdesáte let.'),
(1565807,54,24,25,12,'Potom pak po vyplnění sedmdesáti let trestati budu na králi Babylonském a na tom národu, dí Hospodin, nepravost jejich, totiž na zemi Kaldejské, tak že obrátím ji v pustiny věčné.'),
(1565808,54,24,25,13,'A uvedu na zemi tu všecka slova svá, kteráž jsem mluvil o ní, všecko, což psáno jest v knize této, cožkoli prorokoval Jeremiáš o všech národech.'),
(1565809,54,24,25,14,'Když je v službu podrobí, i jiné národy mnohé a krále veliké, tehdáž odplatím jim podlé skutků jejich a podlé činů rukou jejich.'),
(1565810,54,24,25,15,'Nebo takto mi řekl Hospodin, Bůh Izraelský: Vezmi kalich vína prchlivosti této z ruky mé, a napájej jím všecky ty národy, k kterýmž já pošli tebe,'),
(1565811,54,24,25,16,'Aby pili a potáceli se, anobrž bláznili příčinou meče, kterýž já pošli mezi ně.'),
(1565812,54,24,25,17,'I vzal jsem kalich z ruky Hospodinovy, a napájel jsem všecky ty národy, k nimž mne poslal Hospodin,'),
(1565813,54,24,25,18,'Jeruzalémské i města země Judské, a krále její i knížata její, abych je oddal v pustinu a v zpuštění, na odivu, i k proklínání tohoto dnešního dne,'),
(1565814,54,24,25,19,'Faraona krále Egyptského i služebníky jeho, i knížata jeho, i všecken lid jeho,'),
(1565815,54,24,25,20,'I všecku tu směsici, totiž všecky krále země Uz, všecky také krále země Filistinské, i Aškalon, i Gázy, i Akaron, i ostatek Azotu,'),
(1565816,54,24,25,21,'Idumejské, i Moábské, i syny Ammon,'),
(1565817,54,24,25,22,'I všecky krále Tyrské, i všecky krále Sidonské, i krále krajiny té, kteráž jest při moři,'),
(1565818,54,24,25,23,'Dedana a Temu, a Buzu i všecky přebývající v koutech nejzadnějších,'),
(1565819,54,24,25,24,'I všecky krále Arabské, i všecky krále té směsice, kteříž bydlí na poušti,'),
(1565820,54,24,25,25,'Všecky také krále Zamritské, i všecky krále Elamitské, též všecky krále Médské,'),
(1565821,54,24,25,26,'Anobrž všecky krále půlnoční, blízké i daleké, jednoho jako druhého, všecka také království země, kterážkoli jsou na svrchku země. Král pak Sesák píti bude po nich.'),
(1565822,54,24,25,27,'A rci jim: Takto praví Hospodin zástupů, Bůh Izraelský: Pítež a opojte se, anobrž vyvracejte z sebe, a padejte, tak abyste nepovstali pro meč, kterýž já pošli mezi vás.'),
(1565823,54,24,25,28,'Jestliže by pak nechtěli vzíti kalichu z ruky tvé, aby pili, tedy díš jim: Takto praví Hospodin zástupů: Konečně že píti musíte.'),
(1565824,54,24,25,29,'Nebo poněvadž na to město, kteréž nazváno jest od jména mého, já začínám uvozovati zlé věci, a vy abyste bez hodné pomsty byli? Nebudete bez pomsty, nebo já zavolám meče na všecky obyvatele té země, dí Hospodin zástupů.'),
(1565825,54,24,25,30,'Protož ty prorokuj proti nim všecka slova tato, a rci jim: Hospodin s výsosti řváti bude, a z příbytku svatosti své vydá hlas svůj, mocně řváti bude z obydlí svého. Křik ponoukajících se, jako presovníků, rozléhati se bude proti všechněm obyvatelům té země,'),
(1565826,54,24,25,31,'I průjde hřmot až do konce země. Nebo rozepři má Hospodin s těmi národy, v soud vchází sám se všelikým tělem; bezbožníky vydá pod meč, dí Hospodin.'),
(1565827,54,24,25,32,'Takto praví Hospodin zástupů: Aj, bída půjde z národu na národ, a vichřice veliká strhne se od končin země.'),
(1565828,54,24,25,33,'I budou zbiti od Hospodina v ten čas od konce země až do konce země; nebudou oplakáni, ani sklizeni, ani pochováni, místo hnoje na svrchku země budou.'),
(1565829,54,24,25,34,'Kvělte pastýři a křičte, anobrž válejte se v popele, vy nejznamenitější toho stáda; nebo naplnili se dnové vaši, abyste zbiti byli, a abyste rozptýleni byli, i budete padati jako nádoba drahá.'),
(1565830,54,24,25,35,'I zahyne útočiště pastýřům a utíkání nejznamenitějším toho stáda.'),
(1565831,54,24,25,36,'Hlas žalostný pastýřů a kvílení nejznamenitějších toho stáda; nebo zkazí Hospodin pastvu jejich.'),
(1565832,54,24,25,37,'Zkažena budou i pastviska pokoj mající, pro prchlivost hněvu Hospodinova,'),
(1565833,54,24,25,38,'Jako lev opustí jeskyni svou; nebo přijde země jejich na spuštění, pro prchlivost zhoubce a pro prchlivost hněvu jeho.'),
(1565834,54,24,26,1,'Na počátku kralování Joakima syna Joziášova, krále Judského, stalo se slovo toto od Hospodina, řkoucí:'),
(1565835,54,24,26,2,'Takto praví Hospodin: Postav se v síňci domu Hospodinova, a mluv ke všechněm městům Judským, přicházejícím klaněti se v domě Hospodinově, všecka slova, kteráž tobě přikazuji mluviti k nim, neujímejž slova,'),
(1565836,54,24,26,3,'Zdali by aspoň uposlechli, a odvrátili se jeden každý od cesty své zlé, abych litoval zlého kteréž myslím učiniti jim pro nešlechetnost předsevzetí jejich.'),
(1565837,54,24,26,4,'Rciž tedy jim: Takto praví Hospodin: Neuposlechnete-li mne, abyste chodili v zákoně mém, kterýž jsem předložil vám,'),
(1565838,54,24,26,5,'Poslouchajíce slov služebníků mých proroků, kteréž já posílám k vám, jakož jste, když jsem je, ráno přivstávaje posílal, neposlouchali:'),
(1565839,54,24,26,6,'Jistě žeť naložím s domem tímto jako s Sílo, a město toto vydám v proklínání všechněm národům země.'),
(1565840,54,24,26,7,'Slyšeli pak kněží a proroci, i všecken lid Jeremiáše mluvícího slova ta v domu Hospodinovu.'),
(1565841,54,24,26,8,'I stalo se, že hned, jakž přestal Jeremiáš mluviti všeho, cožkoli přikázal Hospodin mluviti ke všemu lidu, jali jej ti kněží a proroci i všecken lid ten, řkouce: Smrtí umřeš.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565842,54,24,26,9,'Proč jsi prorokoval ve jménu Hospodinovu, řka: Stane se jako Sílo domu tomuto, a město toto tak spustne, že nebude v něm žádného obyvatele? Shromažďoval se pak všecken lid k Jeremiášovi do domu Hospodinova.'),
(1565843,54,24,26,10,'Tedy uslyšavše knížata Judská ty věci, přišli z domu královského do domu Hospodinova, a posadili se u dveří brány Hospodinovy nové.'),
(1565844,54,24,26,11,'I řekli kněží a proroci těm knížatům a všemu lidu, řkouce:Hoden jest smrti muž tento; nebo prorokoval proti městu tomuto, jakž jste slyšeli v své uši.'),
(1565845,54,24,26,12,'Tedy promluvil Jeremiáš ke všechněm knížatům těm i ke všemu lidu, řka: Hospodin poslal mne, abych prorokoval o domu tomto i o městě tomto všecky ty věci, kteréž jste slyšeli.'),
(1565846,54,24,26,13,'Protož nyní polepšte cest svých a předsevzetí svých, a poslouchejte hlasu Hospodina Boha svého, i bude litovati Hospodin toho zlého, kteréž vyřkl proti vám.'),
(1565847,54,24,26,14,'Já pak aj, v rukou vašich jsem, učiňte mi, což se vám za dobré a spravedlivé vidí.'),
(1565848,54,24,26,15,'Ale však jistotně vězte, usmrtíte-li mne, že krev nevinnou na sebe uvedete, i na město toto, i na obyvatele jeho; nebo v pravdě poslal mne Hospodin k vám, abych mluvil v uši vaše všecka slova tato.'),
(1565849,54,24,26,16,'I řekli knížata i všecken lid kněžím a těm prorokům: Nemáť nikoli muž tento odsuzován býti na smrt, poněvadž ve jménu Hospodina Boha našeho mluvil nám.'),
(1565850,54,24,26,17,'Tedy povstali někteří z starších té země, a promluvili ke všemu shromáždění lidu, řkouce:'),
(1565851,54,24,26,18,'Micheáš Moraštický prorokoval za času Ezechiáše krále Judského, a pravil všemu lidu Judskému, řka: Takto praví Hospodin zástupů: Sion jako pole orán bude, a Jeruzalém jako hromady, hora pak domu tohoto jako lesové vysocí.'),
(1565852,54,24,26,19,'Zdaliž hned proto usmrtil jej Ezechiáš král Judský a všecken Juda? Zdaliž neulekl se Hospodina, a nemodlil se Hospodinu? I litoval Hospodin toho zlého, kteréž vyřkl proti nim. Protož my činíme velmi zlou věc proti dušem svým.'),
(1565853,54,24,26,20,'A byl také muž prorokující ve jménu Hospodinovu, Uriáš syn Semaiášův z Kariatjeharim, kterýž prorokoval o městě tomto i o zemi této v táž všecka slova jako Jeremiáš.'),
(1565854,54,24,26,21,'A když uslyšel král Joakim a všickni udatní jeho, i všecka knížata slova jeho, hned usiloval král usmrtiti jej. O čemž uslyšev Uriáš, bál se, a utíkaje, přišel do Egypta.'),
(1565855,54,24,26,22,'Ale poslal král Joakim některé do Egypta, Elnatana syna Achborova i jiné s ním do Egypta.'),
(1565856,54,24,26,23,'Kteříž vyvedše Uriáše z Egypta, přivedli jej k králi Joakimovi. I zabil jej mečem, a vhodil tělo jeho do hrobů lidu obecného.'),
(1565857,54,24,26,24,'A však ruka Achikamova syna Safanova byla při Jeremiášovi, aby ho nevydával v ruku lidu k usmrcení jeho.'),
(1565858,54,24,27,1,'Na počátku kralování Joakima syna Joziášova, krále Judského, stalo se slovo toto k Jeremiášovi od Hospodina, řkoucí:'),
(1565859,54,24,27,2,'Takto řekl Hospodin ke mně: Zdělej sobě oboječky a jha, a dej je na šíji svou.'),
(1565860,54,24,27,3,'Potom je pošli k králi Idumejskému, a k králi Moábskému, a k králi synů Ammonových, a k králi Tyrskému, a k králi Sidonskému po těch poslích, kteříž přijedou do Jeruzaléma k Sedechiášovi králi Judskému.'),
(1565861,54,24,27,4,'A přikaž jim, ať pánům svým řeknou: Takto praví Hospodin zástupů, Bůh Izraelský: Tak rcete pánům svým:'),
(1565862,54,24,27,5,'Já jsem učinil zemi, člověka i hovada, kterážkoli jsou na svrchku země, mocí svou velikou a ramenem svým vztaženým. Protož dávám ji, komuž se mi dobře líbí.'),
(1565863,54,24,27,6,'Jako nyní já dal jsem všecky země tyto v ruku Nabuchodonozora krále Babylonského, služebníka svého, ano i živočichy polní dal jsem jemu, aby sloužili jemu.'),
(1565864,54,24,27,7,'Protož budouť sloužiti jemu všickni ti národové, i synu jeho, i synu syna jeho, dokudž by nepřišel čas země jeho i jeho samého, když v službu podrobí jej sobě národové znamenití a králově velicí.'),
(1565865,54,24,27,8,'Stane se pak, že národ ten i království to, kteréž by nesloužilo jemu, Nabuchodonozorovi králi Babylonskému, a kterýž by nepoddal šíje své pod jho krále Babylonského, mečem a hladem i morem navštívím národ ten, dí Hospodin, dokudž bych do konce nevyplénil jich rukou jeho.'),
(1565866,54,24,27,9,'Protož vy neposlouchejte proroků svých, ani hadačů svých, ani snů svých, ani planetářů svých, ani kouzedlníků svých, kteříž mluvívají k vám, říkajíce: Nebudete sloužiti králi Babylonskému.'),
(1565867,54,24,27,10,'Nebo oni vám lež prorokují, abych vzdálil vás od země vaší, a vyhnal vás, abyste zahynuli.'),
(1565868,54,24,27,11,'Národu pak, kterýž skloní šíji svou pod jho krále Babylonského a sloužiti bude jemu, toho zajisté nechám v zemi jeho, dí Hospodin, aby dělal ji, a bydlil v ní.'),
(1565869,54,24,27,12,'Sedechiášovi také, králi Judskému, mluvil jsem naskrze ta všecka slova, řka: Skloňte šíje své pod jho krále Babylonského, a služte jemu i lidu jeho, a buďte živi.'),
(1565870,54,24,27,13,'Proč máte zahynouti, ty i lid tvůj, mečem, hladem a morem, jakž mluvil Hospodin o národu, kterýž by nesloužil králi Babylonskému?'),
(1565871,54,24,27,14,'Neposlouchejtež tedy slov proroků těch, kteříž mluvíce k vám, říkají: Nebudete sloužiti králi Babylonskému. Nebo oni vám lež prorokují.'),
(1565872,54,24,27,15,'Neposlalť jsem jich zajisté, dí Hospodin, a však oni prorokují ve jménu mém lživě, abych zahnal vás, kdež byste zahynuli vy i ti proroci, kteříž prorokují vám.'),
(1565873,54,24,27,16,'Kněžím také i všemu lidu tomu mluvil jsem, řka: Takto praví Hospodin: Neposlouchejte slov proroků svých, kteříž prorokují vám, říkajíce: Aj, nádobí domu Hospodinova navrácena budou z Babylona již brzo. Neboť lež oni prorokují vám.'),
(1565874,54,24,27,17,'Neposlouchejtež jich, služte králi Babylonskému a živi buďte. Proč má býti toto město pouští?'),
(1565875,54,24,27,18,'Jestliže pak oni jsou proroci, a jestliže slovo Hospodinovo jest v nich, nechť se medle přimluví k Hospodinu zástupů, ať nádobí to, pozůstávající v domě Hospodinově a v domě krále Judského a v Jeruzalémě, nedostává se do Babylona.'),
(1565876,54,24,27,19,'Nebo takto praví Hospodin zástupů o těch sloupích, a o tom moři, a o těch podstavcích, i o ostatku nádobí pozůstávajícím v městě tomto,'),
(1565877,54,24,27,20,'Kteréhož nepobral Nabuchodozor král Babylonský, když přestěhoval Jekoniáše syna Joakimova, krále Judského, z Jeruzaléma do Babylona, a všecky nejpřednější Judské i Jeruzalémské,'),
(1565878,54,24,27,21,'Takto zajisté dí Hospodin zástupů, Bůh Izraelský, o těch nádobách, pozůstávajících v domě Hospodinově a v domě krále Judského i v Jeruzalémě:'),
(1565879,54,24,27,22,'Do Babylona zavezeny budou, a tam budou až do dne toho, v němž je navštívím, dí Hospodin, a rozkáži je přivezti, a zase navrátím je na místo toto.'),
(1565880,54,24,28,1,'Stalo se pak léta toho, na počátku kralování Sedechiáše krále Judského, léta totiž čtvrtého, měsíce pátého, mluvil ke mně Chananiáš syn Azurův, prorok, kterýž byl z Gabaon, v domě Hospodinově, před očima kněží i všeho lidu, řka:'),
(1565881,54,24,28,2,'Takto praví Hospodin zástupů, Bůh Izraelský, řka: Polámal jsem jho krále Babylonského.'),
(1565882,54,24,28,3,'Po dvou letech já navrátím zase na místo toto všecka nádobí domu Hospodinova, kteráž pobral Nabuchodonozor král Babylonský z místa tohoto, a zavezl je do Babylona.'),
(1565883,54,24,28,4,'Jekoniáše také syna Joakimova, krále Judského, i všecky zajaté Judské, kteříž se dostali do Babylona, já zase přivedu na místo toto, dí Hospodin; nebo polámi jho krále Babylonského.'),
(1565884,54,24,28,5,'Tedy řekl Jeremiáš prorok Chananiášovi proroku tomu před očima kněží a před očima všeho lidu, kteříž stáli v domě Hospodinově,'),
(1565885,54,24,28,6,'Řekl, pravím, Jeremiáš prorok: Amen, učiniž tak Hospodin. Potvrdiž Hospodin slov tvých, kteráž jsi prorokoval o navrácení nádobí domu Hospodinova, a všech zajatých z Babylona na místo toto.'),
(1565886,54,24,28,7,'Ale však poslechni medle slova tohoto, kteréž já mluvím při tvé přítomnosti a při přítomnosti všeho tohoto lidu.'),
(1565887,54,24,28,8,'Proroci, kteříž bývali přede mnou i před tebou od věků, ti prorokovali proti zemím znamenitým a proti královstvím velikým o válce a o ssoužení a o moru.'),
(1565888,54,24,28,9,'Prorok ten, kterýž prorokuje o pokoji, když dojde slovo toho proroka, ten prorok znám bývá, že jej poslal Hospodin v pravdě.'),
(1565889,54,24,28,10,'Tedy sňal Chananiáš prorok to jho z šíje Jeremiáše proroka, a polámal je.'),
(1565890,54,24,28,11,'A mluvil Chananiáš před očima všeho lidu, řka: Takto praví Hospodin: Tak polámi jho Nabuchodonozora krále Babylonského po dvou letech z šíje všech národů. I počal jíti Jeremiáš prorok cestou svou.'),
(1565891,54,24,28,12,'Ale stalo se slovo Hospodinovo k Jeremiášovi, když polámal Chananiáš prorok to jho z šíje Jeremiáše proroka, řkoucí:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565892,54,24,28,13,'Jdi a mluv k Chananiášovi, řka: Takto praví Hospodin: Jha dřevěná jsi polámal, protož zdělej místo nich jha železná.'),
(1565893,54,24,28,14,'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Jho železné vložím na šíji všech národů těchto, aby sloužili Naduchodonozorovi králi Babylonskému, a budouť sloužiti jemu. Také i živočichy polní dám jemu.'),
(1565894,54,24,28,15,'Zatím řekl Jeremiáš prorok Chananiášovi proroku: Slyšiž nyní, Chananiáši: Neposlal tebe Hospodin, ale ty jsi k tomu přivedl, aby lid tento ve lži skládal doufání.'),
(1565895,54,24,28,16,'Protož takto praví Hospodin: Aj, já sklidím tě se svrchku země, tento rok ty umřeš; nebo jsi mluvil to, čímž bys odvrátil lid od Hospodina.'),
(1565896,54,24,28,17,'I umřel Chananiáš prorok roku toho měsíce sedmého.'),
(1565897,54,24,29,1,'Tato jsou slova listu, kterýž poslal Jeremiáš prorok z Jeruzaléma k ostatku starších zajatých a k kněžím i k prorokům i ke všemu lidu, kterýž přestěhoval Nabuchodonozor z Jeruzaléma do Babylona,'),
(1565898,54,24,29,2,'Když vyšel Jekoniáš král a královna, i komorníci, knížata Judská i Jeruzalémská, tolikéž tesaři i kováři z Jeruzaléma,'),
(1565899,54,24,29,3,'Po Elasovi synu Safanovu, a Gemariášovi synu Helkiášovu, (kteréž byl poslal Sedechiáš král Judský k králi Babylonskému do Babylona), řka:'),
(1565900,54,24,29,4,'Takto praví Hospodin zástupů, Bůh Izraelský, všechněm zajatým, kteréž jsem přestěhoval z Jeruzaléma do Babylona:'),
(1565901,54,24,29,5,'Stavějte domy, a osazujte se, štěpujte také štěpnice, a jezte ovoce jejich.'),
(1565902,54,24,29,6,'Pojímejte ženy, a ploďte syny i dcery, dávejte také synům svým ženy, dcery též své dávejte za muže, ať rodí syny a dcery; množte se tam, a nebeřte umenšení.'),
(1565903,54,24,29,7,'A hledejte pokoje města toho, do kteréhož jsem zastěhoval vás, a modlívejte se za ně Hospodinu; nebo v pokoji jeho budete míti pokoj.'),
(1565904,54,24,29,8,'Takto zajisté praví Hospodin zástupů, Bůh Izraelský: Nechť vás nesvodí proroci vaši, kteříž jsou mezi vámi, ani hadači vaši, a nespravujte se sny svými, jichž vy příčinou jste, aby je mívali.'),
(1565905,54,24,29,9,'Nebo vám oni lživě prorokují ve jménu mém; neposlalť jsem jich, dí Hospodin.'),
(1565906,54,24,29,10,'Takto zajisté praví Hospodin: Že jakž se jen vyplní Babylonu sedmdesáte let, navštívím vás, a potvrdím vám slova svého výborného o navrácení vás na místo toto.'),
(1565907,54,24,29,11,'Nebo já nejlépe znám myšlení, kteráž myslím o vás, dí Hospodin, myšlení o pokoji, a ne o trápení, abych učinil vašemu očekávání konec přežádostivý.'),
(1565908,54,24,29,12,'Když mne vzývati budete, a půjdete, a modliti se mně budete, tedy vyslyším vás.'),
(1565909,54,24,29,13,'A hledajíce mne, naleznete, když mne hledati budete celým srdcem svým.'),
(1565910,54,24,29,14,'Dám se zajisté nalezti vám, dí Hospodin, a přivedu zase zajaté vaše, a shromáždím vás ze všech národů i ze všech míst, kamžkoli jsem zahnal vás, dí Hospodin, a uvedu vás zase na místo toto, odkudž jsem vás zastěhoval,'),
(1565911,54,24,29,15,'Když řeknete: Vzbuzovalť nám Hospodin proroky v Babyloně.'),
(1565912,54,24,29,16,'Nebo takto praví Hospodin o králi sedícím na stolici Davidově, a o všem lidu obývajícím v městě tomto, bratřích vašich, kteříž nevyšli s vámi v tom zajetí,'),
(1565913,54,24,29,17,'Takto dí Hospodin zástupů: Aj, já pošli na ně meč, hlad a mor, a naložím s nimi jako s fíky trpkými, kterýchž nelze jísti pro trpkost.'),
(1565914,54,24,29,18,'Nebo stihati je budu mečem, hladem i morem, a vydám je ku posmýkání po všech královstvích země, k proklínání, a k užasnutí, anobrž na odivu, a k utrhání mezi všemi národy, tam kdež je vypudím,'),
(1565915,54,24,29,19,'Proto že neposlouchají slov mých, dí Hospodin, když posílám k nim služebníky své proroky, ráno přivstávaje, a to ustavičně, a neposlouchali jste, dí Hospodin.'),
(1565916,54,24,29,20,'Protož slyštež vy slovo Hospodinovo, všickni zajatí, kteréž jsem vyslal z Jeruzaléma do Babylona.'),
(1565917,54,24,29,21,'Takto praví Hospodin zástupů, Bůh Izraelský, o Achabovi synu Kolaiášovu, a o Sedechiášovi synu Maaseiášovu, kteříž prorokují vám ve jménu mém lež: Aj, já vydám je v ruku Nabuchodonozora krále Babylonského, aby je zbil před očima vašima.'),
(1565918,54,24,29,22,'I bude vzato na nich klnutí mezi všecky zajaté Judské, kteříž jsou v Babyloně, aby říkali: Nechť nakládá Hospodin s tebou, jako s Sedechiášem a jako s Echabem, kteréž upekl král Babylonský na ohni,'),
(1565919,54,24,29,23,'Proto že páchali nešlechetnost v Izraeli, cizoložíce s ženami bližních svých, a mluvíce slovo ve jménu mém lživě, čehož jsem nepřikázal jim. Já pak o tom vím, a jsem toho i svědkem, dí Hospodin.'),
(1565920,54,24,29,24,'Semaiášovi Nechelamitskému mluv, řka:'),
(1565921,54,24,29,25,'Takto praví Hospodin zástupů, Bůh Izraelský, řka: Proto že jsi poslal jménem svým listy ke všemu lidu, kterýž jest v Jeruzalémě, a Sofoniášovi synu Maaseiášovu knězi i ke všechněm kněžím, řka:'),
(1565922,54,24,29,26,'Hospodin dal tě za kněze na místo Joiady kněze, abyste pozor měli v domě Hospodinově na každého muže pošetilého a vystavujícího se za proroka, a abys dal takového do žaláře a do klady.'),
(1565923,54,24,29,27,'Pročež jsi pak nyní neokřikl Jeremiáše Anatotského, kterýž se vám vystavuje za proroka?'),
(1565924,54,24,29,28,'Nebo posílal k nám do Babylona, řka: Protáhneť se to dlouho, stavějte domy, a osazujte se, štěpujte také štěpnice, a jezte ovoce jejich.'),
(1565925,54,24,29,29,'Nebo Sofoniáš kněz četl ten list před Jeremiášem prorokem.'),
(1565926,54,24,29,30,'I stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:'),
(1565927,54,24,29,31,'Pošli ke všechněm zajatým, řka: Takto praví Hospodin o Semaiášovi Nechelamitském: Proto že prorokuje vám Semaiáš, ješto jsem já ho neposlal, a přivodí vás k tomu, abyste doufání skládali ve lži,'),
(1565928,54,24,29,32,'Protož takto praví Hospodin: Aj, já trestati budu Semaiáše Nechelamitského i símě jeho. Nebude míti žádného, kdo by bydlil u prostřed lidu tohoto, aniž uzří toho dobrého, kteréž já učiním lidu svému, dí Hospodin; nebo mluvil to, čímž by odvrátil lid od Hospodina.'),
(1565929,54,24,30,1,'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, řkoucí:'),
(1565930,54,24,30,2,'Takto praví Hospodin, Bůh Izraelský, řka: Spiš sobě do knihy všecka slova, kterážť jsem mluvil.'),
(1565931,54,24,30,3,'Aj, dnové zajisté jdou, dí Hospodin, přivedu zase zajaté lidu svého Izraelského i Judského, praví Hospodin, a uvedu je do země, kterouž jsem byl dal otcům jejich, a dědičně ji obdrží,'),
(1565932,54,24,30,4,'Tatoť pak jsou slova, kteráž mluvil Hospodin o Izraelovi a Judovi:'),
(1565933,54,24,30,5,'Takto zajisté praví Hospodin: Hlas předěšení a hrůzy slyšíme, a že není žádného pokoje.'),
(1565934,54,24,30,6,'Ptejte se nyní, a vizte rodívá-li samec. Pročež tedy vidím, an každý muž rukama svýma drží se za bedra svá jako rodička, a obrácené všechněch oblíčeje v zsinalost?'),
(1565935,54,24,30,7,'Ach, nebo veliký jest den tento, tak že nebylo žádného jemu podobného. Ale jakť koli čas jest ssoužení Jákobova, předceť z něho vysvobozen bude.'),
(1565936,54,24,30,8,'Stane se zajisté v ten den, dí Hospodin zástupů, že polámi jho jeho z šíje tvé, a svazky tvé potrhám, i nebudou ho více v službu podrobovati cizozemci.'),
(1565937,54,24,30,9,'Ale sloužiti budou Hospodinu Bohu svému, a Davidovi králi svému, kteréhož jim vzbudím.'),
(1565938,54,24,30,10,'Protož ty neboj se, služebníče můj Jákobe, dí Hospodin, aniž se strachuj, ó Izraeli, nebo aj, já vysvobodím tě zdaleka, i símě tvé z země zajetí jejich. I navrátí se Jákob, aby odpočíval, a pokoj měl, a nebude žádného, kdo by jej předěsil.'),
(1565939,54,24,30,11,'Neboť já s tebou jsem, dí Hospodin, abych tě vysvobodil, když učiním konec všechněm národům, mezi kteréž tě rozptýlím. Tobě však neučiním konce, ale budu tě trestati v soudu, ačkoli tě bez trestání naprosto nenechám.'),
(1565940,54,24,30,12,'Takto zajisté praví Hospodin: Přetěžké bude potření tvé, přebolestná rána tvá.'),
(1565941,54,24,30,13,'Nebude, kdo by přisoudil při tvou k uléčení; lékařství platného žádného míti nebudeš.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565942,54,24,30,14,'Všickni, kteříž tě milují, zapomenou se nad tebou, aniž tě navštíví, když tě raním ranou nepřítele, a trestáním přísným pro mnohou nepravost tvou a nesčíslné hříchy tvé.'),
(1565943,54,24,30,15,'Proč křičíš nad svým potřením a těžkou bolestí svou? Pro mnohou nepravost tvou a nesčíslné hříchy tvé to činím tobě.'),
(1565944,54,24,30,16,'A však všickni, kteříž zžírají tebe, sežráni budou, a všickni, kteříž utiskají tebe, všickni, pravím, do zajetí půjdou, a kteříž tě pošlapávají, pošlapáni budou, a všecky, kteříž tě loupí, v loupež vydám,'),
(1565945,54,24,30,17,'Tehdáž když tobě navrátím zdraví, a na rány tvé zhojím tě, dí Hospodin, proto že zahnanou nazývali tebe, říkajíce: Tato jest Sion, není žádného, kdo by ji navštívil.'),
(1565946,54,24,30,18,'Takto praví Hospodin: Aj, já zase přivedu zajaté stánků Jákobových, a nad příbytky jeho slituji se, i budeť zase vzděláno město na prvním místě svém, a palác podlé způsobu svého vystaven.'),
(1565947,54,24,30,19,'A bude pocházeti od nich díků činění a hlas veselících se; nebo je rozmnožím, a nebudou umenšení bráti, zvelebím je, a nebudou sníženi.'),
(1565948,54,24,30,20,'A budou synové jeho tak jako i prvé, a shromáždění jeho přede mnou utvrzeno bude, trestati pak budu všecky, kteříž jej ssužují.'),
(1565949,54,24,30,21,'A povstane z něho nejdůstojnější jeho, a panovník jeho z prostředku jeho vyjde, kterémuž rozkáži přiblížiti se, aby předstoupil přede mne. Nebo kdo jest ten, ješto by slíbil za sebe, že předstoupí přede mne? dí Hospodin.'),
(1565950,54,24,30,22,'I budete mým lidem, a já budu vaším Bohem.'),
(1565951,54,24,30,23,'Aj, vicher Hospodinův s prchlivostí vyjde, vicher trvající nad hlavou nešlechetných trvati bude.'),
(1565952,54,24,30,24,'Neodvrátíť se prchlivost hněvu Hospodinova, dokudž neučiní toho, a dokudž nevykoná úmyslu srdce svého. Tehdáž porozumíte tomu.'),
(1565953,54,24,31,1,'Toho času, dí Hospodin, budu Bohem všech čeledí Izraelových, a oni budou mým lidem.'),
(1565954,54,24,31,2,'Takto praví Hospodin: Lid z těch pozůstalých po meči nalezl milost na poušti, když jsem chodil před ním, abych odpočinutí způsobil Izraelovi.'),
(1565955,54,24,31,3,'Za starodávnať se mi ukazoval Hospodin. I však milováním věčným miluji tě, pročež ustavičně činím tobě milosrdenství.'),
(1565956,54,24,31,4,'Ještě vždy vzdělávati tě budu, a vzdělána budeš, panno Izraelská; ještě se obveselovati budeš bubny svými, a vycházeti s houfem plésajících.'),
(1565957,54,24,31,5,'Ještě štěpovati budeš vinice v horách Samařských, štěpovati budou štěpaři i jísti.'),
(1565958,54,24,31,6,'Nebo nastane den, v němž volati budou strážní na hoře Efraimově: Vstaňte a vstupme na Sion k Hospodinu Bohu svému.'),
(1565959,54,24,31,7,'Takto zajisté praví Hospodin: Prozpěvujte Jákobovi o věcech veselých, prokřikujte zjevně před těmi národy; dejte se slyšeti, chválu vzdávejte, a rcete: Vysvoboď, Hospodine, ostatek lidu svého Izraelského.'),
(1565960,54,24,31,8,'Aj, já přivedu je z země půlnoční, a shromáždím je ze všech stran země, s nimi spolu slepého i kulhavého, těhotnou i rodící; shromáždění veliké sem se navrátí.'),
(1565961,54,24,31,9,'Kteréžto s pláčem jdoucí a s pokornými modlitbami zase přivedu, a povedu je podlé tekutých vod cestou přímou, na níž by se nepoklesli; neboť jsem Izraelův otec, a Efraim jest prvorozený můj.'),
(1565962,54,24,31,10,'Slyšte slovo Hospodinovo, ó národové, a zvěstujte na ostrovích dalekých, a rcete: Ten, kterýž rozptýlil Izraele, shromáždí jej, a ostříhati ho bude jako pastýř stáda svého.'),
(1565963,54,24,31,11,'Neboť vykoupil Hospodin Jákoba, protož vysvobodí jej z ruky toho, kterýž silnější jest nad něj.'),
(1565964,54,24,31,12,'I přijdou, a prozpěvovati budou na výsosti Siona, a pohrnou se k dobrotě Hospodinově s obilím, a s vínem, a s olejem, a s plodem skotů a bravů, duše pak jejich bude podobná zahradě svlažené, a nebudouť se rmoutiti více.'),
(1565965,54,24,31,13,'Tehdáž veseliti se bude panna s plésáním, a mládenci i starci spolu; obrátím zajisté kvílení jejich v radost, a potěším jich, a obveselím je po zámutku jejich.'),
(1565966,54,24,31,14,'Rozvlažím i duši kněží tukem, a lid můj dobroty mé nasytí se, dí Hospodin.'),
(1565967,54,24,31,15,'Takto praví Hospodin: Hlas v Ráma slyšán jest, naříkání a pláč přehořký. Ráchel plačeci synů svých, nedala se potěšiti po synech svých, proto že žádného není.'),
(1565968,54,24,31,16,'Takto praví Hospodin: Zdrž hlas svůj od pláče, a oči své od slz, nebo budeš míti mzdu za práci svou, praví Hospodin, že se navrátí z země nepřátelské.'),
(1565969,54,24,31,17,'Jest, pravím, čáka, žeť se potom, dí Hospodin, navrátí synové do svého kraje.'),
(1565970,54,24,31,18,'V pravdě slyším Efraima, an sobě stýště, pravě: Trestals mne, abych strestán byl jako telátko neupřáhané; obrať mne, abych obrácen byl, ty jsi zajisté, Hospodine, Bůh můj.'),
(1565971,54,24,31,19,'Nebo po obrácení svém pokání činiti budu, a když mi k známosti sebe poslouženo bude, udeřím se v bedra. Stydímť se, anobrž i pýřím, že snáším útržku dětinství svého.'),
(1565972,54,24,31,20,'Zdali Efraim jest mým synem milým, aneb dítě velmi milostné? A však jakž jsem mluvil proti němu, ustavičně se vždy na něj rozpomínám. Pročež pohybují se vnitřnosti mé příčinou jeho; jistě žeť se slituji nad ním, dí Hospodin.'),
(1565973,54,24,31,21,'Nastavěj sobě pamětných znamení, naklaď sobě hromad kamení, pamatuj na tu silnici a cestu, kterouž jsi šla; navrať se, panno Izraelská, navrať se k městům svým těmto.'),
(1565974,54,24,31,22,'Dokudž se toulati budeš, ó dcero zpurná? Neboť učiní Hospodin novou věc na zemi: Žena bude vůkol obcházeti muže.'),
(1565975,54,24,31,23,'Takto praví Hospodin zástupů, Bůh Izraelský: Ještěť říkati budou slovo toto v zemi Judově a v městech jeho, když zase přivedu zajaté jejich: Požehnejž tobě Hospodin, ó příbytku spravedlnosti, horo svatosti.'),
(1565976,54,24,31,24,'Nebo osazovati se budou v zemi Judské, ve všech městech jeho spolu oráči, a kteříž zacházejí s stádem.'),
(1565977,54,24,31,25,'Rozvlažím zajisté duši ustalou, a všelikou duši truchlou nasytím.'),
(1565978,54,24,31,26,'V tom jsem procítil, a ohlédl se, a ten můj sen byl mi vděčný.'),
(1565979,54,24,31,27,'Aj, dnové jdou, dí Hospodin, v nichžto oseji dům Izraelský a dům Judský semenem lidským a semenem hovad.'),
(1565980,54,24,31,28,'I stane se, že jakož jsem se snažoval, abych je plénil, a bořil, a kazil a hubil, a trápil, tak se snažím, abych je vzdělal a rozsazoval, dí Hospodin.'),
(1565981,54,24,31,29,'Těch časů nebudou říkati více: Otcové jedli hrozen trpký, pročež zubové synů laskominy mají,'),
(1565982,54,24,31,30,'Nýbrž raději: Jeden každý pro nepravost svou umře. Každého člověka, kterýž by jedl hrozen trpký, laskominy míti budou zubové jeho.'),
(1565983,54,24,31,31,'Aj, dnové jdou, dí Hospodin, v nichž učiním s domem Izraelským a s domem Judským smlouvu novou.'),
(1565984,54,24,31,32,'Ne takovou smlouvu, jakouž jsem učinil s otci jejich v ten den, v kterýž jsem je ujal za ruku jejich, abych je vyvedl z země Egyptské. Kteroužto smlouvu mou oni zrušili, a já abych zůstati měl manželem jejich? dí Hospodin.'),
(1565985,54,24,31,33,'Ale tatoť jest smlouva, kterouž učiním s domem Izraelským po těchto dnech, dí Hospodin: Dám zákon svůj do vnitřnosti jejich, a na srdci jejich napíši jej; i budu Bohem jejich, a oni budou mým lidem.'),
(1565986,54,24,31,34,'A nebudou učiti více jeden každý bližního svého, a jeden každý bratra svého, říkajíce: Poznejte Hospodina. Všickni zajisté napořád znáti mne budou, od nejmenšího z nich až do největšího z nich, dí Hospodin; milostiv zajisté budu nepravosti jejich, a na hřích jejich nezpomenu více.'),
(1565987,54,24,31,35,'Takto praví Hospodin, kterýž dává slunce za světlo ve dne, zřízení měsíce a hvězd za světlo v noci, kterýž rozděluje moře, a zvučí vlnobití jeho, jehož jméno jest Hospodin zástupů:'),
(1565988,54,24,31,36,'Jestliže se pohnou ta nařízení před oblíčejem mým, dí Hospodin, takéť símě Izraelovo přestane býti národem před oblíčejem mým po všecky dny.'),
(1565989,54,24,31,37,'Takto praví Hospodin: Budou-li moci býti změřena nebesa zhůru, a vyhledáni základové země dolů, takéť já zavrhu docela símě Izraelovo pro všecko to, což činili, dí Hospodin.'),
(1565990,54,24,31,38,'Aj, dnové jdou, dí Hospodin, v nichž vystaveno bude město toto Hospodinu, od věže Chananeel až k bráně úhlu.'),
(1565991,54,24,31,39,'A půjde ještě šňůra měřící naproti ní, ku pahrbku Gareb, a přitočí se k Gou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1565992,54,24,31,40,'A všecko údolí těl mrtvých a popela, i všecko to pole až ku potoku Cedron, až k úhlu brány východní koňské posvěcené bude Hospodinu; nebudeť pléněno, ani kaženo více na věky.'),
(1565993,54,24,32,1,'Slovo, kteréž se stalo k Jeremiášovi od Hospodina léta desátého Sedechiáše krále Judského, kterýžto rok jest osmnáctý Nabuchodonozorův.'),
(1565994,54,24,32,2,'(Bylo pak tehdáž vojsko krále Babylonského oblehlo Jeruzalém, a Jeremiáš prorok byl zavřín v síni stráže, kteráž byla v domě krále Judského.'),
(1565995,54,24,32,3,'Nebo dal jej byl vsaditi Sedechiáš král Judský, řka: Proč ty prorokuješ, právě: Takto praví Hospodin: Aj, já dám město toto v ruku krále Babylonského, aby je vzal.'),
(1565996,54,24,32,4,'Sedechiáš také král Judský neznikne ruky Kaldejských, ale jistotně vydán bude v ruku krále Babylonského, a budou mluviti ústa jeho s ústy jeho, a oči jeho uzří oči jeho.'),
(1565997,54,24,32,5,'Nýbrž do Babylona zavede Sedechiáše, aby tam byl, až ho navštívím, dí Hospodin. Poněvadž bojujete s Kaldejskými, nepovede se vám šťastně.)'),
(1565998,54,24,32,6,'Tehdy řekl Jeremiáš: Stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1565999,54,24,32,7,'Aj, Chanameel syn Salluma, strýce tvého, jde k tobě, aťby řekl: Kup sobě dvůr můj, kterýž jest v Anatot; nebo tobě právem příbuznosti náleží koupiti jej.'),
(1566000,54,24,32,8,'Když pak přišel ke mně Chanameel syn strýce mého, podlé slova Hospodinova, do síně stráže, a řekl ke mně: Kup medle dvůr můj, kterýž jest v Anatot, jenž jest v zemi Beniaminově; nebo tvůj jest právem dědičným, a právem příbuznosti, kupiž jej sobě: tedy porozuměv, že jest to slovo Hospodinovo,'),
(1566001,54,24,32,9,'I koupil jsem od Chanameele syna strýce svého ten dvůr, kterýž jest v Anatot, a odvážil jsem jemu peněz sedmnácte lotů stříbra.'),
(1566002,54,24,32,10,'A zapsav to do cedule, zapečetil jsem, a osvědčil jsem svědky, odváživ peníze na váze.'),
(1566003,54,24,32,11,'Potom vzal jsem, podlé přikázaní a ustanovení, cedule té koupě zapečetěnou i otevřenou,'),
(1566004,54,24,32,12,'A dal jsem ceduli té koupě Báruchovi synu Neriášovu, synu Maaseiášovu, před očima Chanameele strýce svého, a před očima svědků, kteříž se podepsali v ceduli té koupě, před očima všech Judských, kteříž se byli posadili v síni stráže.'),
(1566005,54,24,32,13,'A přikázal jsem Báruchovi před očima jejich, řka:'),
(1566006,54,24,32,14,'Takto praví Hospodin zástupů, Bůh Izraelský: Vezmi cedule tyto, tuto ceduli té koupě, jakož zapečetěnou, tak ceduli otevřenou tuto, a vlož je do nádoby hliněné, aby trvaly za mnohá léta.'),
(1566007,54,24,32,15,'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Ještěť kupováni budou domové, a rolí, i vinice v zemi této.'),
(1566008,54,24,32,16,'Potom modlil jsem se Hospodinu, když jsem dal ceduli té koupě Báruchovi synu Neriášovu, řka:'),
(1566009,54,24,32,17,'Ach, Panovníče Hospodine, aj, ty jsi učinil nebe i zemi mocí svou velikou a ramenem svým vztaženým, nemůžeť skryta býti před tebou žádná věc.'),
(1566010,54,24,32,18,'Činíš milosrdenství nad tisíci, a odplacíš za nepravost otců do lůna synů jejich po nich, Bůh veliký, silný, mocný, jehož jméno Hospodin zástupů,'),
(1566011,54,24,32,19,'Veliký v radě a znamenitý v správě, poněvadž oči tvé otevřené jsou na všecky cesty synů lidských, abys odplatil jednomu každému podlé cest jeho, a podlé ovoce předsevzetí jeho.'),
(1566012,54,24,32,20,'Kterýž jsi činil divy a zázraky v zemi Egyptské až do tohoto dne, jakož v Izraelovi tak mezi jinými lidmi, a dobyls sobě jména, jakéž jest po dnešní den.'),
(1566013,54,24,32,21,'Nebo vyvedl jsi lid svůj Izraelský z země Egyptské v divích a v zázracích, a rukou silnou, a ramenem vztaženým, a v strachu velikém,'),
(1566014,54,24,32,22,'A dals jim zemi tuto, kterouž jsi přisáhl dáti otcům jejich, zemi oplývající mlékem a strdí.'),
(1566015,54,24,32,23,'Ale že všedše do ní, a dědičně ujavše ji, neposlouchali hlasu tvého, a v zákoně tvém nechodili, všeho, což jsi koli přikázal jim činiti, nečinili, protož způsobils to, aby je potkalo všecko toto zlé.'),
(1566016,54,24,32,24,'Aj, střelci přitáhli na město, aby je vzali, a město skrze meč a hlad a mor dáno jest v ruku Kaldejských, bojujících proti němu; a tak, což jsi koli promluvil, děje se, jakž to sám vidíš.'),
(1566017,54,24,32,25,'Ty pak pravíš mi, Panovníče Hospodine: Zjednej sobě dvůr tento za peníze, a osvědč to svědky, ano již město toto dáno jest v ruku Kaldejských.'),
(1566018,54,24,32,26,'I stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:'),
(1566019,54,24,32,27,'Aj, já jsem Hospodin Bůh všelikého těla, zdaliž přede mnou může býti skryta která věc?'),
(1566020,54,24,32,28,'Protož takto praví Hospodin: Aj, já dávám toto město v ruku Kaldejských a v ruku Nabuchodonozora krále Babylonského, aby je vzal.'),
(1566021,54,24,32,29,'A vejdouce Kaldejští, kteříž bojují proti městu tomuto, zapálí ohněm toto město, a vypálí je, i domy ty, na jejichž střechách kadívali Bálovi, a obětovali oběti mokré bohům cizím, aby mne hněvali.'),
(1566022,54,24,32,30,'Nebo synové Izraelští a synové Judští od dětinství svého jen toliko činí to, což jest zlého před očima mýma; synové, pravím, Izraelští jen toliko hněvají mne dílem rukou svých, dí Hospodin.'),
(1566023,54,24,32,31,'Toto zajisté město od toho dne, jakž je vystavěli, až do tohoto dne k hněvu mému a prchlivosti mé popouzí mne, tak že je sklidím od tváři své,'),
(1566024,54,24,32,32,'Pro všelikou nešlechetnost synů Izraelských a synů Judských, kterouž páchali, aby mne k hněvu popouzeli, oni, králové jejich, knížata jejich, kněží jejich i proroci jejich, jakož muži Judští, tak obyvatelé Jeruzalémští,'),
(1566025,54,24,32,33,'Obracejíce se ke mně hřbetem, a ne tváří. A když je učím, ráno přivstávaje, a to ustavičně, však nikoli neposlouchají, aby přijímali naučení.'),
(1566026,54,24,32,34,'Nadto nastavěli ohavností svých v domě tom, kterýž nazván jest od jména mého, aby jej zanečistili.'),
(1566027,54,24,32,35,'Nastavěli, pravím, výsostí Bálovi, kteréž jsou v údolí Benhinnom, aby vodili syny své a dcery své Molochovi, ješto jsem jim toho nepřikázal, aniž vstoupilo na srdce mé, aby páchati měli tu ohavnost, a Judu k hřešení přivodili.'),
(1566028,54,24,32,36,'A nyní z příčiny té takto dí Hospodin. Bůh Izraelský, o městě tomto, o kterémž vy říkáte: Dánoť jest v ruku krále Babylonského skrze meč a hlad a mor:'),
(1566029,54,24,32,37,'Aj, já shromáždím je ze všech zemí, do nichž jsem je rozehnal v hněvě svém, a v rozpálení svém, i v prchlivosti veliké, a přivedu je zase na toto místo, a způsobím to, aby bydlili bezpečně.'),
(1566030,54,24,32,38,'I budou lidem mým, a já budu jejich Bohem.'),
(1566031,54,24,32,39,'Dám zajisté jim srdce jedno a cestu jednu, aby se mne báli po všecky dny, tak aby jim dobře bylo i synům jejich po nich.'),
(1566032,54,24,32,40,'A učiním s nimi smlouvu věčnou, že se neodvrátím od nich, abych jim neměl dobře činiti; nadto bázeň svou dám v srdce jejich, aby neodstupovali ode mne.'),
(1566033,54,24,32,41,'I veseliti se budu z nich, dobře jim čině, když je štípím v zemi této pevně, celým srdcem svým a vší duší svou.'),
(1566034,54,24,32,42,'Nebo takto praví Hospodin: Jakož jsem uvedl všecko toto zlé veliké na lid tento, tak uvedu na ně všecko to dobré, o němž jim mluvím.'),
(1566035,54,24,32,43,'Tehdáž kupováno bude pole v zemi této, o níž vy říkáte: Pustá jest, tak že není v ní žádného člověka ani hovada, dánať jest v ruku Kaldejských.'),
(1566036,54,24,32,44,'Pole za peníze kupovati budou, a zapisovati do cedulí, a zpečetíce, svědky osvědčovati v zemi Beniaminově a vůkol Jeruzaléma v městech Judských, jakož v městech, kteráž jsou při horách, tak v městech na rovinách, a v městech poledních, když zase přivedu zajaté jejich, dí Hospodin.'),
(1566037,54,24,33,1,'Potom stalo se slovo Hospodinovo k Jeremiášovi po druhé, když ještě zavřín byl v síni stráže, řkoucí:'),
(1566038,54,24,33,2,'Takto praví Hospodin, kterýž učiní to, Hospodin, kterýž sformuje to, potvrdí toho, Hospodin jméno jeho:'),
(1566039,54,24,33,3,'Volej ke mně, a ohlásímť se, a oznámímť věci veliké a tajné, o nichž nevíš.'),
(1566040,54,24,33,4,'Nebo takto praví Hospodin, Bůh Izraelský, o domích města tohoto, a o domích králů Judských, kteříž zkaženi býti mají berany válečnými a mečem:'),
(1566041,54,24,33,5,'Potáhnouť k boji proti Kaldejským, ale aby naplnili tyto domy mrtvými těly lidskými, kteréž zbiji v hněvě svém a v prchlivosti své, pro jejichž všelikou nešlechetnost skryl jsem tvář svou od města tohoto.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566042,54,24,33,6,'Aj, já zopravuji je a vzdělám, a uzdravím obyvatele, a zjevím jim hojnost pokoje, a to stálého.'),
(1566043,54,24,33,7,'Nebo přivedu zase zajaté Judské a zajaté Izraelské, a vzdělám je jako prvé,'),
(1566044,54,24,33,8,'A očistím je od všeliké nepravosti jejich, kterouž hřešili proti mně, a odpustím všecky nepravosti jejich, kterýmiž hřešili proti mně, a jimiž zpronevěřovali se mně.'),
(1566045,54,24,33,9,'A toť mi bude k jménu, k radosti, k chvále, a k zvelebení mezi všemi národy země, kteříž uslyší o všem tom dobrém, kteréž já jim učiním, a děsíce se, třásti se budou nade vším tím dobrým a nade vším pokojem tím, kterýž já jim způsobím.'),
(1566046,54,24,33,10,'Takto praví Hospodin: Na tomto místě, o kterémž vy říkáte: Popléněno jest, tak že není ani člověka ani žádného hovada v městech Judských a na ulicích Jeruzalémských zpustlých, tak že není žádného člověka, ani žádného obyvatele, ani žádného hovada,'),
(1566047,54,24,33,11,'Ještěť bude slýchán hlas radosti a hlas veselé, hlas ženicha a hlas nevěsty, hlas řkoucích: Oslavujte Hospodina zástupů, nebo dobrý jest Hospodin, nebo na věky milosrdenství jeho, a obětujících díkčinění v domě Hospodinově, když zase přivedu zajaté země této jako na počátku, praví Hospodin.'),
(1566048,54,24,33,12,'Takto praví Hospodin zástupů: Na místě tomto popléněném, tak že není žádného člověka ani hovada, i ve všech městech jeho bude ještě obydlé pastýřů, kdež by chovali stáda.'),
(1566049,54,24,33,13,'V městech při horách, v městech na rovinách a v městech v straně polední, tolikéž v zemi Beniaminově a vůkol Jeruzaléma, i v městech Judských, ještě procházívati budou stáda skrze ruce počítajícího, praví Hospodin.'),
(1566050,54,24,33,14,'Aj, dnové jdou, dí Hospodin, v nichž vykonám slovo to výborné, kteréž jsem mluvil o domu Izraelovu a o domu Judovu.'),
(1566051,54,24,33,15,'V těch dnech a za času toho způsobím to, aby zrostl Davidovi výstřelek spravedlivý, kterýž konati bude soud a spravedlnost na zemi.'),
(1566052,54,24,33,16,'V těch dnech spasen bude Juda, a Jeruzalém bydliti bude bezpečně, a toť jest, což jemu přivolá Hospodin, spravedlnost naše.'),
(1566053,54,24,33,17,'Nebo takto praví Hospodin: Nebudeť vypléněn muž z rodu Davidova, ješto by neseděl na stolici domu Judského.'),
(1566054,54,24,33,18,'Z kněží také Levítských nebude vypléněn muž od tváři mé, ješto by neobětoval zápalu, a zapaloval suchou obět, a obětoval obět po všecky dny.'),
(1566055,54,24,33,19,'Potom stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:'),
(1566056,54,24,33,20,'Takto praví Hospodin: Jestliže budete moci zrušiti smlouvu mou se dnem, a smlouvu mou s nocí, aby nebývalo dne ani noci časem svým:'),
(1566057,54,24,33,21,'Takéť smlouva má zrušena bude s Davidem služebníkem mým, aby neměl syna, kterýž by kraloval na stolici jeho, a s Levítskými kněžími, aby nebyli služebníky mými.'),
(1566058,54,24,33,22,'A jakož nemůže sečteno býti vojsko nebeské, ani změřen býti písek mořský, tak rozmnožím símě Davida služebníka svého, a Levítů mně přisluhujících.'),
(1566059,54,24,33,23,'Opět stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:'),
(1566060,54,24,33,24,'Což nesoudíš, co lid tento mluví, říkaje: Že dvojí čeled, kterouž byl vyvolil Hospodin, již ji zavrhl, a lidem mým že pohrdají, jako by nebyl více národem před oblíčejem jejich.'),
(1566061,54,24,33,25,'Takto praví Hospodin: Nebude-liť smlouva má se dnem a nocí, a ustanovení nebes i země zdržáno,'),
(1566062,54,24,33,26,'Také símě Jákobovo a Davida služebníka svého zavrhu, abych nebral z semene jeho těch, kteříž by panovati měli nad semenem Abrahamovým, Izákovým a Jákobovým, když zase přivedu zajaté jejich, a smiluji se nad nimi.'),
(1566063,54,24,34,1,'Slovo,kteréž se stalo k Jeremiášovi od Hospodina, (když Nabuchodonozor král Babylonský, a všecko vojsko jeho, i všecka království země pod moc jeho přináležející, všickni také národové bojovali proti Jeruzalému a proti všechněm městům jeho), řkoucí:'),
(1566064,54,24,34,2,'Takto praví Hospodin Bůh Izraelský: Jdi a rci Sedechiášovi králi Judskému, rci, pravím, jemu: Takto dí Hospodin: Aj, já dám toto město v ruku krále Babylonského, aby je vypálil ohněm.'),
(1566065,54,24,34,3,'I ty neznikneš ruky jeho, ale jistotně jat a v ruku jeho vydán budeš, a oči tvé uzří oči krále Babylonského, i ústa jeho s ústy tvými mluviti budou, a do Babylona se dostaneš.'),
(1566066,54,24,34,4,'A však slyš slovo Hospodinovo, Sedechiáši králi Judský: Takto praví Hospodin o tobě: Neumřeš od meče,'),
(1566067,54,24,34,5,'V pokoji umřeš. A jakož pálívali otcům tvým, králům předešlým, kteříž byli před tebou, tak páliti budou tobě, a říkajíce: Ach, pane, kvíliti budou nad tebou; nebo slovo toto já mluvil jsem, dí Hospodin.'),
(1566068,54,24,34,6,'I mluvil Jeremiáš prorok Sedechiášovi, králi Judskému, všecka slova ta v Jeruzalémě,'),
(1566069,54,24,34,7,'Když vojsko krále Babylonského bojovalo proti Jeruzalému a proti všechněm městům Judským ostatním, proti Lachis a proti Azeku; nebo ta byla pozůstala z měst Judských města hrazená.'),
(1566070,54,24,34,8,'Slovo, kteréž se stalo k Jeremiášovi od Hospodina, když učinil král Sedechiáš smlouvu se vším lidem, kterýž byl v Jeruzalémě, o vyhlášení jim svobody,'),
(1566071,54,24,34,9,'Aby propustil jeden každý služebníka svého a jeden každý děvku svou, Hebrejského neb Hebrejskou, svobodné, aby nepodroboval sobě v službu Žida, bratra svého, nižádný.'),
(1566072,54,24,34,10,'Tedy uposlechla všecka knížata a všecken lid, kterýž byl v smlouvu všel, aby propustil jeden každý služebníka svého a jeden každý děvku svou svobodné, aby nepodroboval jich v službu více; uposlechli, pravím, a propustili.'),
(1566073,54,24,34,11,'Potom pak rozmyslivše se, zase pobrali služebníky své a děvky své, kteréž byli propustili svobodné, a podrobili je sobě za služebníky a děvky.'),
(1566074,54,24,34,12,'I stalo se slovo Hospodinovo k Jeremiášovi od Hospodina, řkoucí:'),
(1566075,54,24,34,13,'Takto praví Hospodin Bůh Izraelský: Já jsem učinil smlouvu s otci vašimi toho dne, když jsem je vyvedl z země Egyptské, z domu služebníků, řka:'),
(1566076,54,24,34,14,'Po vyplnění sedmi let propouštívejte jeden každý bratra svého Žida, kterýž by prodán byl tobě, a sloužilť by šest let, propusť, pravím, jej svobodného od sebe. Ale neuposlechli otcové vaši mne, aniž naklonili ucha svého.'),
(1566077,54,24,34,15,'Vy zajisté usmyslivše sobě dnes, učinili jste to, což jest spravedlivého před očima mýma, že jste vyhlásili svobodu jeden každý bližnímu svému, učinivše smlouvu před oblíčejem mým v domě tom, kterýž nazván jest od jména mého.'),
(1566078,54,24,34,16,'Ale zase zpáčivše se, zlehčili jste jméno mé, že jste vzali zase jeden každý služebníka svého a jeden každý děvku svou, kteréž jste byli propustili svobodné podlé žádosti jejich, a podrobili jste je, aby byli vaši služebníci a děvky.'),
(1566079,54,24,34,17,'Protož takto praví Hospodin: Vy neuposlechli jste mne, abyste vyhlásili svobodu jeden každý bratru svému, a jeden každý bližnímu svému, aj, já vyhlašuji proti vám svobodu, dí Hospodin, meči, moru a hladu, a vydám vás ku posmýkání po všech královstvích země.'),
(1566080,54,24,34,18,'Vydám zajisté ty lidi, jenž přestoupili smlouvu mou, kteříž nevykonali slov smlouvy té, kterouž učinili před oblíčejem mým, když tele rozťali na dvé, a prošli mezi díly jeho,'),
(1566081,54,24,34,19,'Totiž knížata Judská a knížata Jeruzalémská, komorníci, a kněží, i všecken lid té země, kteříž prošli mezi díly toho telete.'),
(1566082,54,24,34,20,'Vydám je, pravím, v ruku nepřátel jejich, a v ruku hledajících bezživotí jejich, i budou těla mrtvá jejich za pokrm ptactvu nebeskému, a šelmám zemským.'),
(1566083,54,24,34,21,'Sedechiáše také krále Judského, i knížata jeho vydám v ruku nepřátel jejich, a v ruku hledajících bezživotí jejich, v ruku, pravím, vojska krále Babylonského, kteříž odtáhli od vás.'),
(1566084,54,24,34,22,'Aj, já přikáži, dí Hospodin, a přivedu je zase na město toto, aby bojovali proti němu, a vezmouce je, vypálili je ohněm; města také Judská obrátím v poušť, tak že nebude žádného obyvatele.'),
(1566085,54,24,35,1,'Slovo, kteréž se stalo k Jeremiášovi od Hospodina za dnů Joakima syna Joziášova, krále Judského, řkoucí:'),
(1566086,54,24,35,2,'Jdi mezi Rechabitské, a promluvě s nimi, doveď je k domu Hospodinovu do jednoho z pokojů, a dej jim píti vína.'),
(1566087,54,24,35,3,'Tedy pojav Jazaniáše syna Jeremiášova, syna Chabaciniášova, a bratří jeho i všecky syny jeho se vší rodinou Rechabitských,'),
(1566088,54,24,35,4,'Dovedl jsem je k domu Hospodinovu do pokoje synů Chanana syna Igdaliášova, muže Božího, kterýž byl při pokoji knížat, jenž byl nad pokojem Maaseiáše syna Sallumova, ostříhajícího prahu.'),
(1566089,54,24,35,5,'Potom postavě před syny domu Rechabitských koflíky plné vína a číše, i řekl jsem jim: Píte víno.'),
(1566090,54,24,35,6,'Kteříž řekli: Nepíjíme vína. Nebo Jonadab syn Rechabův, otec náš, zapověděl nám, řka: Nepíjejte vína, vy, ani synové vaši na věky.'),
(1566091,54,24,35,7,'A domu nestavějte, ani semene nerozsívejte, vinice také neštěpujte, ani mívejte, ale v staních přebývejte po všecky dny vaše, abyste živi byli mnoho dnů na tváři země, v níž pohostinu jste.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566092,54,24,35,8,'Protož uposlechli jsme hlasu Jonadaba syna Rechabova, otce našeho, ve všem, což přikázal nám, abychom nepili vína po všecky dny své, my, manželky naše, synové naši, i dcery naše,'),
(1566093,54,24,35,9,'Abychom nestavěli domů k bydlení svému, a vinice, ani rolí, ani nic osátého nemívali.'),
(1566094,54,24,35,10,'Ale abychom bydlili v staních. Uposlechli jsme, pravím, a děláme všecko, jakž přikázal nám Jonadab otec náš.'),
(1566095,54,24,35,11,'Stalo se pak, když vtrhl Nabuchodonozor král Babylonský do země, že jsme řekli: Poďte, a ujděme do Jeruzaléma před vojskem Kaldejským, a před vojskem Syrským. Takž bydlíme v Jeruzalémě.'),
(1566096,54,24,35,12,'Tedy stalo se slovo Hospodinovo k Jeremiášovi, řkoucí:'),
(1566097,54,24,35,13,'Takto praví Hospodin zástupů, Bůh Izraelský: Jdi a rci mužům Judským a obyvatelům Jeruzalémským: Což nepřijmete naučení, abyste poslouchali slov mých? dí Hospodin.'),
(1566098,54,24,35,14,'K vykonání přichází všeliké slovo Jonadaba syna Rechabova, kterýž přikázal synům svým, aby nepili vína. Nepili zajisté až do tohoto dne, nebo poslouchají přikázaní otce svého. Já pak mluvím k vám, ráno přivstávaje, a to ustavičně, a však neposloucháte mne.'),
(1566099,54,24,35,15,'Nadto posílám k vám všecky služebníky své proroky, ráno přivstávaje, a to ustavičně, říkaje: Navraťte se již jeden každý z cesty své zlé, a polepšte předsevzetí svých, a nechoďte za bohy cizími, sloužíce jim, a tak přebývejte v zemi této, kterouž jsem dal vám i otcům vašim: však nenakloňujete uší svých, aniž mne posloucháte.'),
(1566100,54,24,35,16,'Ješto synové Jonadabovi syna Rechabova plní přikázaní otce svého, kteréž přikázal jim, lid pak tento neposlouchají mne.'),
(1566101,54,24,35,17,'Protož takto praví Hospodin Bůh zástupů, Bůh Izraelský: Aj, já uvedu na Judu a na všecky obyvatele Jeruzalémské všecko to zlé, kteréž jsem vyřkl proti nim, proto že jsem mluvíval k nim, a neposlouchali, a volával jsem na ně, ale neohlásili se.'),
(1566102,54,24,35,18,'Rodině pak Rechabitských řekl Jeremiáš: Takto praví Hospodin zástupů, Bůh Izraelský: Protože posloucháte přikázaní Jonadaba otce vašeho, a ostříháte všech přikázaní jeho, anobrž děláte všecko, jakž přikázal vám,'),
(1566103,54,24,35,19,'Protož takto praví Hospodin zástupů, Bůh Izraelský: Nebudeť vypléněn muž z rodu Jonadabova syna Rechabova, ješto by nestál před oblíčejem mým po všecky dny.'),
(1566104,54,24,36,1,'Stalo se pak léta čtvrtého Joakima syna Joziášova, krále Judského, stalo se slovo toto k Jeremiášovi od Hospodina, řkoucí:'),
(1566105,54,24,36,2,'Vezmi sobě knihu, a zapiš do ní všecka slova, kteráž jsem mluvil tobě proti Izraelovi, a proti Judovi, i všechněm národům od toho dne, jakž jsem mluvíval s tebou, ode dnů Joziášových, až do dne tohoto,'),
(1566106,54,24,36,3,'Zdali aspoň uslyšíce dům Judský o všem tom zlém, kteréž já myslím učiniti jim, navrátí se jeden každý z cesty své zlé, abych odpustil nepravost jejich a hřích jejich.'),
(1566107,54,24,36,4,'Protož zavolal Jeremiáš Bárucha syna Neriášova, i sepsal Báruch do knihy z úst Jeremiášových všecka slova Hospodinova, kteráž mluvil jemu.'),
(1566108,54,24,36,5,'Potom přikázal Jeremiáš Báruchovi, řka: Já zápověd maje, nemohu jíti do domu Hospodinova.'),
(1566109,54,24,36,6,'Protož jdi ty, a čti v knize této, což jsi napsal z úst mých, slova Hospodinova, při přítomnosti lidu v domě Hospodinově, v den postu, též také při přítomnosti všech Judských, kteříž by se z měst svých sešli, čti je,'),
(1566110,54,24,36,7,'Zda by snad poníženě a pokorně modléce se před Hospodinem, i navrátili by se jeden každý z cesty své zlé; neboť jest veliký hněv a prchlivost, v níž mluvil Hospodin proti lidu tomuto.'),
(1566111,54,24,36,8,'I učinil Báruch syn Neriášův všecko, jakž přikázal jemu Jeremiáš prorok, čta v knize té slova Hospodinova v domě Hospodinově.'),
(1566112,54,24,36,9,'Stalo se pak léta pátého za Joakima syna Joziášova, krále Judského, měsíce devátého, že vyhlásili půst před Hospodinem všemu lidu v Jeruzalémě, a všemu lidu, kteříž se byli sešli z měst Judských do Jeruzaléma.'),
(1566113,54,24,36,10,'I četl Báruch z knihy slova Jeremiášova v domě Hospodinově, v pokoji Gemariáše syna Safanova, písaře, na síni hořejší, u dveří brány domu Hospodinova nové, při přítomnosti všeho lidu.'),
(1566114,54,24,36,11,'Když pak vyslyšel Micheáš syn Gemariášův, syna Safanova, všecka slova Hospodinova z té knihy,'),
(1566115,54,24,36,12,'Hned šel do domu královského, do pokoje kancléřova, a aj, tam všecka knížata seděla: Elisama ten kancléř, a Delaiáš syn Semaiášův, a Elnatan syn Achborův, a Gemariáš syn Safanův, a Sedechiáš syn Chananiášův, i všecka knížata.'),
(1566116,54,24,36,13,'A oznámil jim Micheáš všecka slova, kteráž slyšel, když četl Báruch v knize při přítomnosti lidu.'),
(1566117,54,24,36,14,'Protož poslala všecka knížata k Báruchovi Judu syna Netaniášova, syna Selemiášova, syna Chuzova, aby řekl: Tu knihu, v níž jsi četl při přítomnosti lidu, vezmi do ruky své a poď. I vzal Báruch syn Neriášův tu knihu do ruky své, a přišel k nim.'),
(1566118,54,24,36,15,'Kteříž řekli jemu: Seď medle a čti ji před námi. I četl Báruch před nimi.'),
(1566119,54,24,36,16,'Stalo se pak, když uslyšeli všecka slova ta, že předěšeni byli všickni, a řekli Báruchovi: Jistotně oznámíme králi všecka slova tato.'),
(1566120,54,24,36,17,'Potom otázali se Bárucha, řkouce: Oznam již nám, jak jsi všecka slova ta sepsal z úst jeho?'),
(1566121,54,24,36,18,'Jimž řekl Báruch: Z úst svých pravil mi všecka slova tato, a já psal jsem na knihách černidlem.'),
(1566122,54,24,36,19,'Tedy řekla ta knížata Báruchovi: Jdi schovej se ty i Jeremiáš, ať žádný neví, kde jste.'),
(1566123,54,24,36,20,'Potom vešli k králi na síň, když tu knihu schovati dali v pokoji Elisama kancléře, a oznámili králi všecka slova ta.'),
(1566124,54,24,36,21,'I poslal král Judu, aby vzal tu knihu. Kterýžto vzal ji z pokoje Elisama kancléře, a četl ji Juda při přítomnosti krále, a při přítomnosti všech knížat stojících před králem.'),
(1566125,54,24,36,22,'Král pak seděl v domě, v němž v zimě býval, měsíce devátého, a na ohništi před ním hořelo.'),
(1566126,54,24,36,23,'Tedy stalo se, jakž jen přečtl Juda tři listy neb čtyři, že pořezal ji škriptorálem, a házel na oheň, kterýž byl na ohništi, až shořela všecka kniha ta ohněm tím, kterýž byl na ohništi.'),
(1566127,54,24,36,24,'Ale neulekli se, aniž roztrhl roucha svá král a všickni služebníci jeho, kteříž slyšeli všecka slova ta.'),
(1566128,54,24,36,25,'Nýbrž ještě když Elnatan a Delaiáš a Gemariáš přimlouvali se k králi, aby nepálil té knihy, tedy neuposlechl jich.'),
(1566129,54,24,36,26,'Ale přikázal král Jerachmeelovi synu královu, a Saraiášovi synu Azrielovu, a Selemiášovi synu Abdeelovu, aby jali Bárucha písaře a Jeremiáše proroka. Ale skryl je Hospodin.'),
(1566130,54,24,36,27,'Stalo se pak slovo Hospodinovo k Jeremiášovi, když spálil král tu knihu a slova, kteráž byl sepsal Báruch z úst Jeremiášových, řkoucí:'),
(1566131,54,24,36,28,'Vezmi sobě zase knihu jinou, a napiš na ní všecka slova první, kteráž byla v té knize prvnější, kterouž spálil Joakim král Judský.'),
(1566132,54,24,36,29,'O Joakimovi pak králi Judském rci: Takto praví Hospodin: Ty jsi spálil knihu tuto, pravě: Proč jsi psal v ní, řka: Jistotně přitáhne král Babylonský, a zkazí zemi tuto, a vyhladí z ní lidi i hovada?'),
(1566133,54,24,36,30,'Protož takto praví Hospodin o Joakimovi králi Judském: Nebude míti, kdo by seděl na stolici Davidově, a tělo jeho mrtvé bude vyvrženo na horko ve dne a na mráz v noci.'),
(1566134,54,24,36,31,'Nebo trestati budu na něm, a na semeni jeho, i na služebnících jeho nepravost jejich, a uvedu na ně, a na obyvatele Jeruzalémské, i na muže Judské všecko to zlé, o kterémž jsem mluvíval jim, a neposlouchali.'),
(1566135,54,24,36,32,'I vzal Jeremiáš knihu jinou, a dal ji Báruchovi synu Neriášovu, písaři, kterýž sepsal do ní z úst Jeremiášových všecka slova té knihy, kterouž byl spálil Joakim král Judský ohněm. A ještě přidáno jest k těm slovům mnoho těm podobných.'),
(1566136,54,24,37,1,'Potom kraloval král Sedechiáš syn Joziášův místo Koniáše syna Joakimova, kteréhož ustanovil králem Nabuchodonozor král Babylonský v zemi Judské.'),
(1566137,54,24,37,2,'Ale neposlouchal on, ani služebníci jeho, ani lid té země slov Hospodinových, kteráž mluvil skrze Jeremiáše proroka.'),
(1566138,54,24,37,3,'Ač byl poslal Sedechiáš Jehuchale syna Selemiášova a Sofoniáše syna Maaseiášova, kněze, k Jeremiášovi proroku, aby řekli: Modl se medle za nás Hospodinu Bohu našemu.'),
(1566139,54,24,37,4,'Nebo Jeremiáš ještě bydlil svobodně u prostřed lidu, aniž ho ještě byli dali do žaláře.'),
(1566140,54,24,37,5,'A vojsko Faraonovo bylo vytáhlo z Egypta; (nebo uslyšavše Kaldejští, kteříž oblehli byli Jeruzalém, pověst o nich, odtrhli od Jeruzaléma).'),
(1566141,54,24,37,6,'Stalo se pak slovo Hospodinovo k Jeremiášovi proroku, řkoucí:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566142,54,24,37,7,'Toto praví Hospodin Bůh Izraelský: Takto rcete králi Judskému, kterýž vás poslal ke mně, abyste se radili se mnou: Aj, vojsko Faraonovo, kteréž potáhne vám na pomoc, navrátí se zase do země své Egyptské.'),
(1566143,54,24,37,8,'Kaldejští pak navrátí se zase, a bojovati budou proti městu tomuto, a vezmouce je, vypálí je ohněm.'),
(1566144,54,24,37,9,'Takto praví Hospodin: Nesvoďte sami sebe, říkajíce: Konečně odtrhnou od nás Kaldejští, neboť neodtrhnou.'),
(1566145,54,24,37,10,'Nýbrž byste pobili všecko vojsko Kaldejských bojujících s vámi, tak že by pozůstali z nich toliko ranění, tiť z stanů svých povstanou, a toto město ohněm vypálí.'),
(1566146,54,24,37,11,'Stalo se pak, když odtrhlo vojsko Kaldejské od Jeruzaléma před vojskem Faraonovým,'),
(1566147,54,24,37,12,'Že vycházel Jeremiáš z Jeruzaléma, jíti chtěje do země Beniaminovy, aby tak vynikl z prostředku lidu.'),
(1566148,54,24,37,13,'Když pak byl v bráně Beniaminské, byl tu hejtman nad stráží, jménem Jiriáš syn Selemiáše, syna Chananiášova, kterýž jal Jeremiáše proroka, řka: K Kaldejským ty ustupuješ.'),
(1566149,54,24,37,14,'Jemuž řekl Jeremiáš: Není pravda, neustupujiť já k Kaldejským. Ale nechtěl ho slyšeti, nýbrž jal Jiriáš Jeremiáše, a dovedl jej k knížatům.'),
(1566150,54,24,37,15,'Tedy rozhněvavše se knížata na Jeremiáše, ubili jej, a dali jej do vězení, do domu Jonatana písaře; nebo z něho byli udělali žalář.'),
(1566151,54,24,37,16,'Když pak vešel Jeremiáš do té jámy a do sklípků jejích, a seděl tam Jeremiáš mnoho dní.'),
(1566152,54,24,37,17,'Teprv poslav král Sedechiáš, vzal jej, a tázal se ho král v domě svém tajně, řka: Stalo-li se slovo od Hospodina? Jemuž řekl Jeremiáš: Stalo. Potom řekl: V ruku krále Babylonského vydán budeš.'),
(1566153,54,24,37,18,'Při tom řekl Jeremiáš králi Sedechiášovi: Coť jsem zavinil aneb služebníkům tvým, aneb lidu tomuto, že jste mne dali do žaláře tohoto?'),
(1566154,54,24,37,19,'A kdež jsou proroci vaši, kteříž prorokují vám, říkajíce: Nepřitáhneť král Babylonský na vás, ani na zemi tuto?'),
(1566155,54,24,37,20,'Nyní tedy slyš, žádám, pane můj králi, nechť, prosím, místo má před tebou pokorná prosba má; nedopouštěj mne zase voditi do domu Jonatana písaře, abych tam neumřel.'),
(1566156,54,24,37,21,'I přikázal král Sedechiáš, aby vsadili Jeremiáše do síně stráže, a dávali jemu pecník chleba na den z ulice pekařů, dokudž by nebyl vytráven všecken chléb v městě. A tak seděl Jeremiáš v síni stráže.'),
(1566157,54,24,38,1,'Slyšel pak Sefatiáš syn Matanův, a Gedaliáš syn Paschurův, a Juchal syn Selemiášův, a Paschur syn Malkiášův slova, kteráž Jeremiáš mluvil ke všemu lidu, řka:'),
(1566158,54,24,38,2,'Takto praví Hospodin: Kdo by zůstal v městě tomto, zahyne mečem, hladem aneb morem, ale kdož by vyšel k Kaldejským, že bude živ, a že bude míti život svůj místo kořisti, a živ zůstane.'),
(1566159,54,24,38,3,'Takto praví Hospodin: Jistotně vydáno bude město toto v ruku vojska krále Babylonského, a vezme je.'),
(1566160,54,24,38,4,'Protož řekla ta knížata králi: Nechť jest usmrcen muž ten, poněvadž zemdlívá ruce mužů bojovných, pozůstalých v městě tomto, i ruce všeho lidu, mluvě jim slova taková; nebo muž ten nikoli neobmýšlí pokoje lidu tomuto, ale zlé.'),
(1566161,54,24,38,5,'Tedy řekl král Sedechiáš: Aj, v ruce vaší jest, neboť král zhola nic nemůže proti vám.'),
(1566162,54,24,38,6,'I vzali Jeremiáše, kterýž byl v síni stráže, a uvrhli jej do jámy Malkiášovy, syna králova, a spustili Jeremiáše po provazích. V té pak jámě nebylo nic vody, ale bláto, tak že Jeremiáš tonul v tom blátě.'),
(1566163,54,24,38,7,'Ale jakž uslyšel Ebedmelech Mouřenín, dvořan, kterýž byl v domě královském, že dali Jeremiáše do té jámy, (král pak seděl v bráně Beniaminské),'),
(1566164,54,24,38,8,'Hned vyšel Ebedmelech z domu královského, a mluvil s králem, řka:'),
(1566165,54,24,38,9,'Pane můj, králi, zle učinili muži tito všecko, což učinili Jeremiášovi proroku, že jej uvrhli do té jámy; neboť by byl umřel i na prvním místě hladem, poněvadž již není žádného chleba v městě.'),
(1566166,54,24,38,10,'Protož poručil král Ebedmelechovi Mouřenínu, řka: Vezmi s sebou odsud třidceti mužů, a vytáhni Jeremiáše proroka z té jámy, prvé než by umřel.'),
(1566167,54,24,38,11,'Tedy vzal Ebedmelech ty muže s sebou, a všel do domu královského pod pokladnici, a nabral starých hadrů strhaných, hadrů, pravím, zkažených, kteréž spustil k Jeremiášovi do té jámy po provazích.'),
(1566168,54,24,38,12,'A řekl Ebedmelech Mouřenín Jeremiášovi: Nu, podlož ty staré, strhané hadry a zkažené pod paže rukou svých s provazy. I učinil tak Jeremiáš.'),
(1566169,54,24,38,13,'Takž vytáhli Jeremiáše po provazích, a dobyli jej z té jámy. I seděl Jeremiáš v síni stráže.'),
(1566170,54,24,38,14,'Potom poslav král Sedechiáš, vzal Jeremiáše proroka k sobě do třetího průchodu, kterýž byl při domu Hospodinovu, a řekl král Jeremiášovi: Zeptám se tebe na něco, netaj přede mnou ničehož.'),
(1566171,54,24,38,15,'I řekl Jeremiáš Sedechiášovi: Oznámím-liť, zdaliž mne konečně neusmrtíš? A poradím-liť, neuposlechneš mne.'),
(1566172,54,24,38,16,'Tedy přisáhl král Sedechiáš Jeremiášovi tajně, řka: Živť jest Hospodin, kterýž učinil nám život tento, že tě neusmrtím, aniž tě vydám v ruku mužů těch, kteříž hledají bezživotí tvého.'),
(1566173,54,24,38,17,'I řekl Jeremiáš Sedechiášovi: Takto praví Hospodin Bůh zástupů, Bůh Izraelský: Jestliže dobrovolně vyjdeš k knížatům krále Babylonského, i duše tvá živa bude, i město toto nebude vypáleno ohněm, a tak živ zůstaneš ty i dům tvůj.'),
(1566174,54,24,38,18,'Jestliže pak nevyjdeš k knížatům krále Babylonského, jistě že vydáno bude město toto v ruku Kaldejských, a vypálí je ohněm, ano i ty neznikneš ruky jejich.'),
(1566175,54,24,38,19,'Tedy řekl král Sedechiáš Jeremiášovi: Velmi se bojím Židů, kteříž ustoupili k Kaldejským, aby mne snad nevydali v ruku jejich, i učinili by sobě ze mne posměch.'),
(1566176,54,24,38,20,'Ale Jeremiáš řekl: Nevydadí. Uposlechni, prosím, hlasu Hospodinova, o kterémž já mluvím tobě, a bude dobře tobě, i duše tvá živa bude.'),
(1566177,54,24,38,21,'Jestliže pak nebudeš chtíti vyjíti, toto jest slovo to, kteréž mi ukázal Hospodin,'),
(1566178,54,24,38,22,'Že aj, všecky ženy, kteréž pozůstaly v domě krále Judského, přivedeny budou knížatům krále Babylonského, a samyť říkati budou: Nabádaliť jsou tě, a obdrželi na tobě ti, kteříž tě troštovali pokojem; uvázlyť v bahně nohy tvé, a nazpět obráceny.'),
(1566179,54,24,38,23,'Všecky také manželky tvé i syny tvé dovedou k Kaldejským, i ty sám neznikneš ruky jejich, ale rukou krále Babylonského jat budeš, a město toto vypálíš ohněm,'),
(1566180,54,24,38,24,'Tedy řekl Sedechiáš Jeremiášovi: Žádný ať neví o věcech těchto, abys neumřel.'),
(1566181,54,24,38,25,'Pakli uslyšíce knížata, že jsem mluvil s tebou, přišli by k tobě, a řekliť by: Oznam medle nám, cos mluvil s králem, netaj před námi, a neusmrtíme tě, a co mluvil s tebou král?'),
(1566182,54,24,38,26,'Tedy rci jim: Předkládal jsem poníženou a pokornou prosbu svou před krále, aby mne nedal zase voditi do domu Jonatanova, abych tam neumřel.'),
(1566183,54,24,38,27,'I sešla se všecka knížata k Jeremiášovi, aby se ho tázali. Kterýžto oznámil jim podlé toho všeho, jakž přikázal král. Takž mlčkem odešli od něho, když nebylo slyšeti o té věci.'),
(1566184,54,24,38,28,'Jeremiáš pak seděl v síni stráže až do toho dne, v němž dobyt jest Jeruzalém, kdežto byl, když dobýván byl Jeruzalém.'),
(1566185,54,24,39,1,'Léta devátého Sedechiáše krále Judského, měsíce desátého, přitáhl Nabuchodonozor král Babylonský se vším vojskem svým k Jeruzalému, a oblehli jej.'),
(1566186,54,24,39,2,'Jedenáctého pak léta Sedechiášova, měsíce čtvrtého, devátého dne měsíce, prolomeno jest město.'),
(1566187,54,24,39,3,'I vešla tam všecka knížata krále Babylonského, a posadila se v bráně prostřední: Nergalšaretser, Samgarnebu, Sarsechim, Rabsaris, Nergalšaretser, Rabmag, a všecka jiná knížata krále Babylonského.'),
(1566188,54,24,39,4,'Stalo se pak, když je uzřel Sedechiáš král Judský, a že všickni muži bojovní utekli, a vyšli v noci z města cestou zahrady královské skrze bránu mezi dvěma zdmi, ušel také cestou pouště.'),
(1566189,54,24,39,5,'I honilo je vojsko Kaldejské, a postihli Sedechiáše na rovinách Jerišských, a jali jej a přivedli ho k Nabuchodonozorovi králi Babylonskému do Ribla, do země Emat. Kdežto učinil soud.'),
(1566190,54,24,39,6,'Nebo zmordoval král Babylonský syny Sedechiášovy v Ribla před očima jeho, i všecky nejpřednější Judské zmordoval král Babylonský.'),
(1566191,54,24,39,7,'Oči pak Sedechiášovy oslepil, a svázav ho řetězy ocelivými, dovedl jej do Babylona.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566192,54,24,39,8,'Dům také královský i domy toho lidu vypálili Kaldejští ohněm, a zdi Jeruzalémské pobořili.'),
(1566193,54,24,39,9,'Ostatek pak lidu, kterýž byl zůstal v městě, i poběhlce, kteříž byli ustoupili k němu, a jiný lid pozůstalý zavedl Nebuzardan, hejtman nad žoldnéři, do Babylona.'),
(1566194,54,24,39,10,'Toliko nejchaternějších z lidu, kteříž nikdež neměli nic, zanechal Nebuzardan, hejtman nad žoldnéři, v zemi Judské, jimž rozdal vinice a rolí v ten den.'),
(1566195,54,24,39,11,'Přikázal pak Nabuchodonozor král Babylonský o Jeremiášovi Nebuzardanovi, hejtmanu nad žoldnéři, řka:'),
(1566196,54,24,39,12,'Vezmi jej, a pilně ho opatruj, aniž jemu čiň co zlého, ale jakž tobě řekne, tak nalož s ním.'),
(1566197,54,24,39,13,'Protož poslav Nebuzardan, hejtman nad žoldnéři, a Nebušazban, Rabsaris, a Nergalšaretser, Rabmag, a všickni hejtmané krále Babylonského,'),
(1566198,54,24,39,14,'Poslavše, pravím, vzali Jeremiáše z síně stráže, a dali jej Godoliášovi synu Achikamovu, syna Safanova, aby jej domů dovedl. Takž bydlil u prostřed lidu.'),
(1566199,54,24,39,15,'Stalo se pak k Jeremiášovi slovo Hospodinovo, když ještě byl zavřín v síni stráže, řkoucí:'),
(1566200,54,24,39,16,'Jdi a rci Ebedmelechovi Mouřenínu, řka: Takto praví Hospodin zástupů, Bůh Izraelský: Aj, já způsobím to, aby došla slova má na město toto ke zlému a ne k dobrému, a splní se před oblíčejem tvým v ten den.'),
(1566201,54,24,39,17,'Ale vysvobodím tě v ten den, dí Hospodin, aniž budeš vydán v ruku mužů těch, jejichž oblíčeje se lekáš.'),
(1566202,54,24,39,18,'Nebo jistotně vychvátím tě, abys od meče nepadl, a budeš míti život svůj místo kořisti, proto že jsi naději složil ve mně, dí Hospodin.'),
(1566203,54,24,40,1,'Slovo to, kteréž se stalo k Jeremiášovi od Hospodina, když jej propustil Nebuzardan, hejtman nad žoldnéři, z Ráma, vzav jej, když byl svázaný řetězy u prostřed všech zajatých Jeruzalémských a Judských, zajatých do Babylona.'),
(1566204,54,24,40,2,'Tedy vzal hejtman nad žoldnéři Jeremiáše, a řekl jemu: Hospodin Bůh tvůj byl vyřkl zlé toto proti místu tomuto.'),
(1566205,54,24,40,3,'Protož je uvedl a učinil Hospodin, jakž mluvil; nebo jste hřešili proti Hospodinu, a neposlouchali jste hlasu jeho, pročež stala se vám věc tato.'),
(1566206,54,24,40,4,'Již tedy, aj, rozvazuji tě dnes z řetězů těch, kteříž jsou na rukou tvých. Vidí-liť se za dobré jíti se mnou do Babylona, poď, a budu tě pilně opatrovati; jestližeť se pak nevidí za dobré jíti se mnou do Babylona, nech tak. Aj, všecka tato země jest před tebou; kamžť se za dobré a slušné vidí jíti, tam jdi.'),
(1566207,54,24,40,5,'Pakli, (poněvadž se nenavracuje), obrať se k Godoliášovi synu Achikamovu, syna Safanova, kteréhož ustanovil král Babylonský nad městy Judskými, a zůstaň s ním u prostřed lidu, aneb kamžť se koli dobře líbí jíti, jdi. I dal jemu hejtman nad žoldnéři na cestu, a dar, a propustil jej.'),
(1566208,54,24,40,6,'Takž přišel Jeremiáš k Godoliášovi synu Achikamovu do Masfa, a bydlil s ním u prostřed lidu pozůstalého v zemi.'),
(1566209,54,24,40,7,'Uslyšeli pak všickni hejtmané vojsk, kteříž byli na poli, oni i všecken lid jejich, že ustanovil král Babylonský Godoliáše syna Achikamova nad tou zemí, a že jemu poručil muže a ženy i děti, a to z nejchaternějších té země, z těch kteříž nebyli zajati do Babylona.'),
(1566210,54,24,40,8,'Protož přišli k Godoliášovi do Masfa, totiž Izmael syn Netaniášův, též Jochanan a Jonatan, synové Kareachovi, a Saraiáš syn Tanchumetův, a synové Efai Netofatského, a Jazaniáš syn Machatův, oni i lid jejich.'),
(1566211,54,24,40,9,'Tedy přisáhl jim Godoliáš syn Achikamův, syna Safanova, i lidu jejich, řka: Nebojte se služby Kaldejských, zůstaňte v zemi, a služte králi Babylonskému, a dobře vám bude.'),
(1566212,54,24,40,10,'Nebo aj, já bydlím v Masfa, abych sloužil Kaldejským, kteříž přicházejí k nám, vy pak slízejte víno a letní ovoce i olej, a skládejte do nádob svých, a zůstaňte v městech svých, kteráž držíte.'),
(1566213,54,24,40,11,'Tak i všickni Judští, kteříž byli u Moábských a mezi Ammonitskými, a mezi Idumejskými, a kteříž byli ve všech zemích, uslyšavše, že by pozůstavil král Babylonský ostatek Judských, a že by ustanovil nad nimi Godoliáše syna Achikamova, syna Safanova,'),
(1566214,54,24,40,12,'Navrátili se všickni Judští ze všech míst, kamž rozehnaní byli, a přišli do země Judské k Godoliášovi do Masfa. I nazbírali vína a letního ovoce velmi mnoho.'),
(1566215,54,24,40,13,'Jochanan pak syn Kareachův, a všecka knížata vojsk, kteráž byla v poli, přišli k Godoliášovi do Masfa,'),
(1566216,54,24,40,14,'A řekli jemu: Víš-li co o tom, že Baalis král Ammonitský poslal Izmaele syna Netaniášova, aby tě zabil? Ale nevěřil jim Godoliáš syn Achikamův.'),
(1566217,54,24,40,15,'Nadto Jochanan syn Kareachův řekl Godoliášovi tajně v Masfa, řka: Nechť jdu medle, a zabiji Izmaele syna Netaniášova, však žádný nezví. Proč má zabiti tebe, a mají rozptýleni býti všickni Judští, kteříž shromážděni jsou k tobě, a zahynouti ostatek Judských?'),
(1566218,54,24,40,16,'Ale řekl Godoliáš syn Achikamův Jochananovi synu Kareachovu: Nečiň toho, nebo lež ty mluvíš o Izmaelovi.'),
(1566219,54,24,41,1,'Stalo se pak měsíce sedmého, že přišel Izmael syn Netaniášův, syna Elisamova z semene královského, a hejtmané královští, totiž deset mužů s ním, k Godoliášovi synu Achikamovu do Masfa, a jedli tam chléb spolu v Masfa.'),
(1566220,54,24,41,2,'Potom vstav Izmael syn Netaniášův, a deset mužů, kteříž byli s ním, zabili Godoliáše syna Achikamova, syna Safanova, mečem; zamordoval, pravím, toho, kteréhož ustanovil král Babylonský nad tou zemí.'),
(1566221,54,24,41,3,'Všecky také Židy, kteříž byli s ním, s Godoliášem, v Masfa, i ty Kaldejské, kteříž postiženi byli tam, muže bojovné, pobil Izmael.'),
(1566222,54,24,41,4,'Stalo se pak druhého dne, jakž zamordoval Godoliáše, (o čemž žádný nezvěděl),'),
(1566223,54,24,41,5,'Že přišli někteří z Sichem, z Sílo a z Samaří, mužů osmdesáte, oholivše bradu, a roztrhše roucha, a řežíce se, kteřížto suchou obět a kadidlo v rukou svých měli, aby je nesli do domu Hospodinova.'),
(1566224,54,24,41,6,'Tedy Izmael syn Netaniášův vyšel jim vstříc z Masfa, ustavičně jda a plače. Stalo se pak, když je potkal, že řekl jim: Poďte k Godoliášovi synu Achikamovu.'),
(1566225,54,24,41,7,'Ale stalo se, když přišli do prostřed města, že pobiv je Izmael syn Netaniášův, vmetal je do prostřed jámy, on i muži, kteříž s ním byli.'),
(1566226,54,24,41,8,'Deset pak mužů nalezlo se mezi nimi, kteříž řekli Izmaelovi: Nemorduj nás; nebo máme sklady skryté v poli, pšenice a ječmene, též oleje a medu. I nechal tak, a nemordoval jich u prostřed bratří jejich.'),
(1566227,54,24,41,9,'Jáma pak, do níž Izmael vmetal k Godoliášovi všecka těla mužů těch, kteréž pobil, ta jest, kterouž udělal král Aza, boje se Bázy krále Izraelského. Kterouž naplnil Izmael syn Netaniášův zbitými.'),
(1566228,54,24,41,10,'A zajal Izmael všecken ostatek lidu, kteříž byli v Masfa, dcery královské a všecken lid, kteříž byli pozůstali v Masfa, nad nimiž byl ustanovil Nebuzardan, hejtman nad žoldnéři, Godoliáše syna Achikamova. Kteréžto zajav Izmael syn Netaniášův, šel, aby se dopravil k Ammonitským.'),
(1566229,54,24,41,11,'V tom uslyšel Jochanan syn Kareachův, i všickni hejtmané těch vojsk, kteříž s ním byli, o všem tom zlém, kteréž učinil Izmael syn Netaniášův.'),
(1566230,54,24,41,12,'I vzali všecken svůj lid, a táhli k boji proti Izmaelovi synu Netaniášovu, jehož nalezli při vodách velikých, kteréž jsou v Gabaon.'),
(1566231,54,24,41,13,'Stalo se pak, že když uzřel všecken lid, kterýž byl s Izmaelem, Jochanana syna Kareachova a všecka knížata vojsk, kteříž s ním byli, zradovali se.'),
(1566232,54,24,41,14,'A obrátiv se všecken ten lid, kterýž byl zajal Izmael z Masfa, navrátil se zase, a přišel k Jochananovi synu Kareachovu.'),
(1566233,54,24,41,15,'Izmael pak syn Netaniášův ušel před Jochananem s osmi muži, a přišel k Ammonitským.'),
(1566234,54,24,41,16,'Protož vzal Jochanan syn Kareachův, a všecka knížata vojsk, kteříž s ním byli, všecken ostatek lidu, kterýž zase přivedl od Izmaele syna Netaniášova z Masfa, když zabil Godoliáše syna Achikamova, muže bojovné, též ženy a děti i komorníky, kteréž zase přivedl z Gabaon,'),
(1566235,54,24,41,17,'A odšedše, pobyli v hospodě Chimhamově, kteráž jest u Betléma, aby jdouce, vešli do Egypta,'),
(1566236,54,24,41,18,'Před Kaldejskými. Nebo báli se jich, proto že zabil Izmael syn Netaniášův Godoláše syna Achikamova, kteréhož byl ustanovil král Babylonský nad tou zemí.'),
(1566237,54,24,42,1,'Potom přistoupili všecka knížata vojsk, i Jochanan syn Kareachův i Jazaniáš syn Hosaiášův, i všecken lid, od nejmenšího až do největšího,'),
(1566238,54,24,42,2,'A řekli Jeremiášovi proroku: Uslyš medle nás v ponížené prosbě naší, a modl se za nás Hospodinu Bohu svému, za všecken ostatek tento, nebo nás maličko zůstalo z mnohých, jakž oči tvé nás vidí,'),
(1566239,54,24,42,3,'Ať nám oznámí Hospodin Bůh tvůj cestu, po níž bychom jíti, a co činiti měli.'),
(1566240,54,24,42,4,'Jimž řekl Jeremiáš prorok: Uslyšel jsem. Aj, já modliti se budu Hospodinu Bohu vašemu podlé slov vašich, a cožkoli vám odpoví Hospodin, oznámím vám; nezatajím před vámi slova.'),
(1566241,54,24,42,5,'Oni zase řekli Jeremiášovi: Nechť jest Hospodin mezi námi svědkem pravým a věrným, jestliže podlé každého slova, pro něž poslal tě Hospodin Bůh tvůj k nám, tak se chovati nebudeme.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566242,54,24,42,6,'Buď dobré aneb zlé, hlasu Hospodina Boha našeho, pro nejž tě vysíláme k němu, uposlechneme, aby nám dobře bylo, když uposlechneme hlasu Hospodina Boha našeho.'),
(1566243,54,24,42,7,'Stalo se pak po přeběhnutí desíti dnů, když se stalo slovo Hospodinovo k Jeremiášovi,'),
(1566244,54,24,42,8,'Že povolal Jochanana syna Kareachova, a všech knížat vojsk, kteříž s ním byli, i všeho lidu, od nejmenšího až do největšího,'),
(1566245,54,24,42,9,'A řekl jim: Takto praví Hospodin Bůh Izraelský, k němuž jste mne poslali, abych rozprostíral poníženou prosbu vaši před oblíčejem jeho:'),
(1566246,54,24,42,10,'Jestliže navrátíce se, zůstanete v zemi této, zajisté že vzdělám vás, a nezkazím, anobrž vštípím vás, a nevypléním; neboť lituji toho zlého, kteréž jsem učinil vám.'),
(1566247,54,24,42,11,'Nebojtež se krále Babylonského, jehož se bojíte, nebojte se ho, dí Hospodin; neboť s vámi jsem, abych vás vysvobozoval, a vytrhoval vás z ruky jeho.'),
(1566248,54,24,42,12,'Nadto způsobím vám milost, aby se slitoval nad vámi, a dal se vám navrátiti do země vaší.'),
(1566249,54,24,42,13,'Ale řeknete-li: Nezůstaneme v zemi této, neposlouchajíce hlasu Hospodina Boha svého,'),
(1566250,54,24,42,14,'A říkajíce: Nikoli, ale do země Egyptské vejdeme, kdež neuzříme boje, ani zvuku trouby neuslyšíme, a chleba lačněti nebudeme, pročež tam se osadíme:'),
(1566251,54,24,42,15,'Protož nyní slyštež slovo Hospodinovo, ostatkové Judští: Takto praví Hospodin zástupů, Bůh Izraelský: Jestliže vy zarputile na tom zůstanete, abyste vešli do Egypta, a vejdete-li, abyste tam pobyli,'),
(1566252,54,24,42,16,'Jistě stane se to, že meč, kteréhož se bojíte, tam v zemi Egyptské vás postihne, a hlad, jehož se obáváte, přijde na vás v Egyptě, a tam pomřete.'),
(1566253,54,24,42,17,'Tak se stane všechněm těm mužům, kteříž uložili předce jíti do Egypta, aby tam byli pohostinu, že zhynou mečem, hladem a morem, a nezůstane z nich žádného, aniž kdo znikne toho zlého, kteréž já uvedu na ně.'),
(1566254,54,24,42,18,'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Jakož vylit jest hněv můj a prchlivost má na obyvatele Jeruzalémské, tak vylita bude prchlivost má na vás, když vejdete do Egypta, a budete k proklínání, a k užasnutí, a k zlořečení, a za útržku; nadto neuzříte více místa tohoto.'),
(1566255,54,24,42,19,'K vámť mluví Hospodin, ó ostatkové Judští: Nevcházejte do Egypta. Jistotně vězte, (neboť se vám dnes osvědčuji),'),
(1566256,54,24,42,20,'Poněvadž jste se neupřímě ke mně měli v myšleních svých, poslavše mne k Hospodinu Bohu vašemu, řkouce: Modl se za nás Hospodinu Bohu našemu, a všecko, jakžť koli dí Hospodin Bůh náš, tak nám oznam, a učiníme,'),
(1566257,54,24,42,21,'Když pak oznamuji vám dnes, však neposloucháte hlasu Hospodina Boha vašeho hned v ničemž, pročež mne k vám poslal:'),
(1566258,54,24,42,22,'Protož pravím, vězte jistotně, že mečem, hladem a morem pomřete v tom místě, kamž se vám zachtělo jíti, abyste tam byli pohostinu.'),
(1566259,54,24,43,1,'Stalo se pak, když přestal Jeremiáš mluviti ke všemu lidu všech slov Hospodina Boha jejich, s nimiž poslal jej Hospodin Bůh jejich k nim, všech, pravím, slov těch,'),
(1566260,54,24,43,2,'Že řekl Azariáš syn Hosaiášův, a Jochanan syn Kareachův, i všickni muži ti pyšní, řkouce Jeremiášovi: Lež ty mluvíš, neposlalť tebe Hospodin Bůh náš, abys řekl: Nevcházejte do Egypta, abyste tam byli pohostinu.'),
(1566261,54,24,43,3,'Ale Báruch syn Neriášův ponouká tě proti nám, aby vydal nás v ruku Kaldejských k usmrcení nás, aneb zajetí nás do Babylona.'),
(1566262,54,24,43,4,'I neuposlechl Jochanan syn Kareachův, i všecka knížata vojsk, též i všecken lid hlasu Hospodinova, aby zůstal v zemi Judské.'),
(1566263,54,24,43,5,'Ale Jochanan syn Kareachův, a všecka knížata vojsk vzali všecken ostatek Judských, kteříž se byli navrátili ze všech národů, kamž byli rozehnáni, k obývání v zemi Judské,'),
(1566264,54,24,43,6,'Muže i ženy, též dítky a dcery královské, i všelikou duši, kterýchž Nebuzardan, hejtman nad žoldnéři, s Godoliášem synem Achikamovým, syna Safanova, zanechal, i s Jeremiášem prorokem a Báruchem synem Neriášovým,'),
(1566265,54,24,43,7,'A šli do země Egyptské, (nebo neuposlechli hlasu Hospodinova), a přišli až do Tachpanches.'),
(1566266,54,24,43,8,'Stalo se pak slovo Hospodinovo k Jeremiášovi v Tachpanches, řkoucí:'),
(1566267,54,24,43,9,'Nabeř do ruky své kamení velikého, a schovej je v hlině v cihelni, kteráž jest u brány domu Faraonova v Tachpanches, před očima mužů Judských.'),
(1566268,54,24,43,10,'A rci jim: Takto praví Hospodin zástupů, Bůh Izraelský: Aj, já pošli, a vezmu Nabuchodonozora krále Babylonského, služebníka svého, a postavím stolici jeho na tomto kamení, kteréž jsem schoval, i rozbije majestát svůj na něm.'),
(1566269,54,24,43,11,'Nebo přitáhne a popléní zemi Egyptskou: Kteříž k smrti, k smrti, a kteříž k zajetí, do zajetí, a kteříž pod meč,'),
(1566270,54,24,43,12,'A zanítím oheň v domích bohů Egyptských, aby je popálil, a zajal je. A přioděje se zemí Egyptskou, tak jako se odívá pastýř rouchem svým, a vyjde odtud s pokojem,'),
(1566271,54,24,43,13,'Když poláme sochy Betsemes, kteréž jest v zemi Egyptské, a domy bohů Egyptských popálí ohněm.'),
(1566272,54,24,44,1,'Slovo, kteréž se stalo k Jeremiášovi proti všechněm Judským bydlícím v zemi Egyptské, kteříž bydlili v Magdol a v Tachpanches, a v Nof, a v zemi Patros, řkoucí:'),
(1566273,54,24,44,2,'Takto praví Hospodin zástupů, Bůh Izraelský: Vy jste viděli všecko to zlé, kteréž jsem uvedl na Jeruzalém a na všecka města Judská, že aj, pustá jsou podnes, tak že v nich není žádného obyvatele,'),
(1566274,54,24,44,3,'Pro nešlechetnost jejich, kterouž páchali, aby jen popouzeli mne, chodíce kaditi a sloužiti bohům cizím, jichž neznali sami, vy, ani otcové vaši,'),
(1566275,54,24,44,4,'Ješto posílal jsem k vám všecky služebníky své proroky, ráno přivstávaje, a to ustavičně, říkaje: Nečiňte medle této věci ohavné, kteréž nenávidím.'),
(1566276,54,24,44,5,'Ale neuposlechli, aniž naklonili ucha svého, aby se navrátili od nešlechetnosti své, a aby nekadili bohům cizím.'),
(1566277,54,24,44,6,'Protož vylita jest prchlivost má i hněv můj, a rozpálil se v městech Judských i po ulicích Jeruzalémských, tak že obrácena jsou v poušť a v pustinu, jakž viděti v dnešní den.'),
(1566278,54,24,44,7,'Nyní pak takto praví Hospodin Bůh zástupů, Bůh Izraelský: Proč vy činíte zlé převeliké proti dušem svým, abyste vyplénili z sebe muže i ženu, dítě i prsí požívajícího z prostředku Judy, abyste nepozůstavili sobě ostatků,'),
(1566279,54,24,44,8,'Popouzejíce mne dílem ruku svých, kadíce bohům cizím v zemi Egyptské, do níž jste vešli, abyste tam byli pohostinu, abyste vyplénili sebe, a byli k zlořečení a za útržku u všech národů země?'),
(1566280,54,24,44,9,'Zdali jste zapomenuli na nešlechetnosti otců svých, a na nešlechetnosti králů Judských, a na nešlechetnosti manželek jejich, a na nešlechetnosti své, i na nešlechetnosti manželek svých, kteréž páchali v zemi Judské a po ulicích Jeruzalémských?'),
(1566281,54,24,44,10,'Nekořili se až do tohoto dne, aniž se báli, aniž chodili v zákoně mém a v ustanoveních mých, kteráž předkládám vám jako i otcům vašim.'),
(1566282,54,24,44,11,'Protož takto praví Hospodin zástupů, Bůh Izraelský: Aj, já obracím tvář svou proti vám k zlému, totiž abych vyplénil všecky Judské.'),
(1566283,54,24,44,12,'Zhubím zajisté ostatek Judských, kteříž svévolně vešli do země Egyptské, aby tam byli pohostinu, tak že zhynou docela všickni v zemi Egyptské. Padnou od meče, hladem docela zhynou, od nejmenšího až do největšího, mečem a hladem pomrou; nadto budou k proklínání a k užasnutí, a k zlořečení a za útržku.'),
(1566284,54,24,44,13,'Nebo navštívím ty, kteříž bydlí v zemi Egyptské, jako jsem navštívil Jeruzalém mečem, hladem a morem,'),
(1566285,54,24,44,14,'Tak že nebude, kdo by ušel, neb pozůstal z ostatků Judských, kteříž přišli do země Egyptské, aby tam byli pohostinu, aby se zase navrátiti mohli do země Judské. Čímž se však troštují, že se zase navrátí, aby přebývali tam, ale nenavrátíť se, než ti, kteříž sami ujdou.'),
(1566286,54,24,44,15,'Tedy odpověděli Jeremiášovi všickni ti muži, věděvše, že kadívaly manželky jejich bohům cizím, ty všecky ženy, jichž stál veliký zástup, i všecken lid přebývající v zemi Egyptské v Patros, řkouce:'),
(1566287,54,24,44,16,'V té věci, o kteréž jsi nám mluvil ve jménu Hospodinovu, neuposlechneme tebe.'),
(1566288,54,24,44,17,'Ale dosti činiti chceme každému slovu, kteréž by pošlo z úst našich, kadíce tvoru nebeskému, a obětujíce jemu oběti mokré, jakž jsme činívali my i otcové naši, králové naši i knížata naše po městech Judských a po ulicích Jeruzalémských; nebo nasyceni jsme bývali chlebem, a bývali jsme veseli, zlého pak neokoušeli jsme.'),
(1566289,54,24,44,18,'Ale jakž jsme přestali kaditi tvoru nebeskému, a obětovati jemu oběti mokré, nedostatek trpíme ve všem, a mečem i hladem hyneme.'),
(1566290,54,24,44,19,'Že pak kadíme tvoru nebeskému, a obětujeme jemu oběti mokré, zdaliž bez znamenitých mužů našich pečeme jemu koláče, službu jemu konajíce, a obětujíce jemu oběti mokré?'),
(1566291,54,24,44,20,'Tedy řekl Jeremiáš všemu lidu, mužům i ženám a všemu lidu, kteříž jemu to odpověděli, řka:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566292,54,24,44,21,'Zdaliž na kadidlo, jímž jste kadívali po městech Judských a po ulicích Jeruzalémských vy i otcové vaši, králové vaši i knížata vaše i lid země, nerozpomenul se Hospodin, a zdaž jím to nepohnulo,'),
(1566293,54,24,44,22,'Tak že nemohl Hospodin více snášeti nešlechetnosti předsevzetí vašich a ohavností, kteréž jste činili? Pročež obrácena jest země vaše v poušť a v pustinu a v zlořečenství, tak že není v ní žádného obyvatele, jakž dnešní den jest.'),
(1566294,54,24,44,23,'Proto že jste kadívali, a že jste hřešili proti Hospodinu, a neposlouchali jste hlasu Hospodinova, a tak v zákoně jeho a v ustanoveních jeho ani v svědectvích jeho nechodili jste, protož potkalo vás zlé toto, jakž viděti dnešní den.'),
(1566295,54,24,44,24,'Nadto řekl Jeremiáš všemu tomu lidu i všechněm těm ženám: Slyšte slovo Hospodinovo všickni Judští, kteříž jste v zemi Egyptské:'),
(1566296,54,24,44,25,'Takto praví Hospodin zástupů, Bůh Izraelský, řka: Vy i ženy vaše ústy svými jste mluvili, a rukami doplnili, říkajíce: Konečněť budeme plniti sliby své, kteréž jsme slíbili, kadíce tvoru nebeskému, a obětujíce jemu oběti mokré, a tak vší snažností vyplňujete sliby vaše, a všelijak slibům vašim dosti činíte.'),
(1566297,54,24,44,26,'Protož slyšte slovo Hospodinovo všickni Judští, kteříž bydlíte v zemi Egyptské: Aj, já přisahám skrze jméno své veliké, praví Hospodin, že nebude více vzýváno jméno mé ústy žádného muže Judského po vší zemi Egyptské, kterýž by řekl: Živť jest Panovník Hospodin.'),
(1566298,54,24,44,27,'Aj, já bdíti budu nad nimi k zlému a ne k dobrému, i budou pléněni všickni muži Judští, kteříž jsou v zemi Egyptské, mečem a hladem, dokudž by docela nezhynuli.'),
(1566299,54,24,44,28,'Kteříž pak ujdou meče, navrátí se z země Egyptské do země Judské, lidu malý počet. I zvědíť všickni ostatkové Judští, kteříž přišli do země Egyptské, aby tam byli pohostinu, čí slovo ostojí, mé-li čili jejich.'),
(1566300,54,24,44,29,'A toto mějte za znamení, dí Hospodin, že já trestati budu vás v místě tomto, abyste věděli, že jistotně ostojí slova má proti vám k zlému.'),
(1566301,54,24,44,30,'Takto praví Hospodin: Aj, já vydám Faraona Chofra krále Egyptského v ruku nepřátel jeho a v ruku hledajících bezživotí jeho, jako jsem vydal Sedechiáše krále Judského v ruku Nabuchodonozora krále Babylonského, nepřítele jeho, a hledajícího bezživotí jeho.'),
(1566302,54,24,45,1,'Slovo, kteréž promluvil Jeremiáš prorok k Báruchovi synu Neriášovu, když spisoval slova tato do knihy z úst Jeremiášových, léta čtvrtého Joakima syna Joziášova, krále Judského, řka:'),
(1566303,54,24,45,2,'Takto praví Hospodin Bůh Izraelský o tobě, ó Báruchu.'),
(1566304,54,24,45,3,'Řekls: Jižtě mi běda, nebo přičiní Hospodin zámutku k bolesti mé. Ustávám v úpění svém, a odpočinutí nenalézám.'),
(1566305,54,24,45,4,'Takto rci jemu: Takto praví Hospodin: Aj, což jsem vystavěl, já bořím, a což jsem vštípil, já pléním, totiž všecku zemi tuto.'),
(1566306,54,24,45,5,'A ty bys hledal sobě velikých věcí? Nehledej. Nebo aj, já uvedu bídu na všeliké tělo, dí Hospodin, ale dám tobě život tvůj místo kořisti na všech místech, kamž půjdeš.'),
(1566307,54,24,46,1,'Slovo Hospodinovo, kteréž se stalo k Jeremiášovi proroku proti národům těmto:'),
(1566308,54,24,46,2,'O Egyptských. Proti vojsku Faraona Néchy krále Egyptského, (jenž bylo při řece Eufrates u Charkemis, kteréž zbil Nabuchodonozor král Babylonský), léta čtvrtého Joakima syna Joziášova, krále Judského:'),
(1566309,54,24,46,3,'Připravtež štít a pavézu, a jděte k boji.'),
(1566310,54,24,46,4,'Zapřáhejte koně, a vsedejte jezdci, postavte se s lebkami, vytírejte kopí, zobláčejte se v pancíře.'),
(1566311,54,24,46,5,'Proč vidím tyto zděšené, zpět obrácené, a nejsilnější jejich potřené, anobrž prudce utíkající, tak že se ani neohlédnou? Strach jest vůkol, dí Hospodin,'),
(1566312,54,24,46,6,'Aby neutekl čerstvý, a neušel silný, aby na půlnoci o břeh řeky Eufrates zavadili a padli.'),
(1566313,54,24,46,7,'Kdo se to valí jako potok, jako řeky, jejichž vody sebou zmítají?'),
(1566314,54,24,46,8,'Egypt jako potok se valí a jako řeky, když se vody hýbají, tak pravě: Potáhnu, přikryji zemi, zkazím město i přebývající v něm.'),
(1566315,54,24,46,9,'Křepčtež, ó koni, a běžte s hřmotem, ó vozové; nechť vytáhnou i silní, Mouřenínové a Putští, kteříž užívají pavézy, i Ludimští, kteříž užívají a natahují lučiště.'),
(1566316,54,24,46,10,'A však ten den Panovníka Hospodina zástupů bude den pomsty, aby uvedl pomstu na nepřátely své, kteréžto zžíře meč a nasytí se, anobrž opojí se krví jejich; nebo obět Panovníka Hospodina zástupů bude v zemi půlnoční u řeky Eufrates.'),
(1566317,54,24,46,11,'Vyprav se do Galád, a nabeř masti, panno dcero Egyptská, nadarmo však užíváš mnohého lékařství, nebo ty zhojena býti nemůžeš.'),
(1566318,54,24,46,12,'Slyšíť národové o zlehčení tvém, a naříkání tvého plná jest země, proto že silný na silném se ustrkuje, tak že spolu zaroveň padají.'),
(1566319,54,24,46,13,'Slovo, kteréž mluvil Hospodin k Jeremiášovi proroku o přitažení Nabuchodonozora krále Babylonského, aby zkazil zemi Egyptskou.'),
(1566320,54,24,46,14,'Oznamte v Egyptě, a ohlaste v Magdol, rozhlaste také v Nof, i v Tachpanches rcete: Postůj a připrav se, ale však zžíře meč všecko, což vůkol tebe jest.'),
(1566321,54,24,46,15,'Proč poražen jest každý z nejsilnějších tvých? Nemůže ostáti, proto že Hospodin pudí jej.'),
(1566322,54,24,46,16,'Mnohoť bude těch, kteříž klesnou a padnou jeden na druhého, a řeknou: Vstaň, a navraťme se k lidu svému, a do země, v níž jsme se zrodili, před mečem toho zhoubce.'),
(1566323,54,24,46,17,'Budou křičeti tam: Faraona krále Egyptského není než sám chřest, jižť pominul volný jeho čas.'),
(1566324,54,24,46,18,'Živť jsem já, (dí král ten, jehož jméno Hospodin zástupů), že jakž jest Tábor mezi horami, a jako Karmel při moři, tak toto přijde.'),
(1566325,54,24,46,19,'Připraviž sobě to, co bys s sebou vystěhovati měla, ó ty, kteráž jsi usadila se, dcero Egyptská; neboť Nof v poušť obrácen a vypálen bude, tak že nebude tam žádného obyvatele.'),
(1566326,54,24,46,20,'Velmi pěkná jalovice jest Egypt, ale zabití její od půlnoci jistotně přijde.'),
(1566327,54,24,46,21,'Ano i nájemníci jeho u prostřed něho jsou jako telata vytylá, ale takéť i ti obrátíce se, utekou. Neostojí, když den bídy jejich přijde na ně, v čas navštívení jejich.'),
(1566328,54,24,46,22,'Hlas jeho jako hadí siptěti bude, když s vojskem přitáhnou, a s sekerami přijdou na něj jako ti, kteříž sekají dříví.'),
(1566329,54,24,46,23,'Posekají les jeho, dí Hospodin, ačkoli mu konce není; více jest jich než kobylek, aniž mají počtu.'),
(1566330,54,24,46,24,'Zahanbenať bude dcera Egyptská, vydána bude v ruku lidu půlnočního.'),
(1566331,54,24,46,25,'Praví Hospodin zástupů, Bůh Izraelský: Aj, já navštívím lidné město No, též Faraona i Egypt s bohy jeho a králíky jeho, Faraona, pravím, a ty, kteříž v něm doufají.'),
(1566332,54,24,46,26,'A vydám je v ruku těch, kteříž hledají bezživotí jejich, totiž v ruku Nabuchodonozora krále Babylonského, a v ruku služebníků jeho; potom však bydleno bude v něm, jako za dnů starodávních, dí Hospodin.'),
(1566333,54,24,46,27,'Ale ty neboj se, služebníče můj Jákobe, aniž se strachuj, ó Izraeli; nebo aj, já vysvobodím tě zdaleka, i símě tvé z země zajetí jejich. I navrátí se Jákob, aby odpočíval a pokoj měl, a aby nebylo žádného, kdo by předěsil.'),
(1566334,54,24,46,28,'Ty, pravím, neboj se, služebníče můj Jákobe, dí Hospodin; neboť jsem s tebou. Učiním zajisté konec všechněm národům, mezi kteréž tě zaženu, tobě pak neučiním konce, ale budu tě trestati v soudu, ačkoli tě naprosto bez trestání nenechám.'),
(1566335,54,24,47,1,'Slovo Hospodinovo, kteréž se stalo k Jeremiášovi proroku proti Filistinským, prvé než dobyl Farao Gázy.'),
(1566336,54,24,47,2,'Takto praví Hospodin: Aj, vody vystupují od půlnoci, a obrátí se v potok rozvodnilý, tak že zatopí zemi, i cožkoli jest na ní, město i ty, kteříž bydlí v něm; pročež křičeti budou lidé, a kvíliti všeliký obyvatel té země;'),
(1566337,54,24,47,3,'Pro zvuk dusání kopyt silných jeho, pro hřmot vozů jeho, a hrčení kol jeho, neohlédnou se otcové na syny, majíce opuštěné ruce;'),
(1566338,54,24,47,4,'Pro ten den, kterýž přijíti má, aby pohubil všecky Filistinské, aby zahladil Týr a Sidon, i všelikou pozůstávající pomoc, když hubiti bude Hospodin Filistinské, ostatek krajiny Kaftor.'),
(1566339,54,24,47,5,'Přijde lysina na Gázu, vypléněn bude Aškalon i ostatek údolí jejich. Dokudž se řezati budeš?'),
(1566340,54,24,47,6,'Ach, meči Hospodinův, dokudž se nespokojíš? Navrať se do pošvy své, utiš se, a zastav se.'),
(1566341,54,24,47,7,'I jakž by se spokojil? Však Hospodin přikázal jemu. Proti Aškalon a proti břehu mořskému, tam postavil jej.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566342,54,24,48,1,'Proti Moábovi. Takto praví Hospodin zástupů, Bůh Izraelský: Běda městu Nébo, neboť popléněno bude; zahanbeno a vzato bude Kariataim, zahanbeno bude Misgab a děsiti se bude.'),
(1566343,54,24,48,2,'Nebudeť míti více žádné pochvaly Moáb z Ezebon, obmýšlejí proti němu zlé: Poďte, a vyhlaďme je z národu. I ty, ó Madmen, vypléněno budeš, půjde za tebou meč.'),
(1566344,54,24,48,3,'Hlas žalostný z Choronaim: Ó poplénění a potření veliké.'),
(1566345,54,24,48,4,'Potřín bude Moáb, slyšán bude křik maličkých jeho.'),
(1566346,54,24,48,5,'Proto že na cestě Luchitské ustavičný bude pláč, a že kudyž se chodí k Choronaim, nepřátelé křik hrozný slyšeti budou:'),
(1566347,54,24,48,6,'Utecte, vysvoboďte život svůj, a buďte jako vřes na poušti.'),
(1566348,54,24,48,7,'Nebo proto, že doufáš v statku svém a v pokladích svých, také ty jat budeš; i půjde Chámos do zajetí, kněží jeho, též i knížata jeho.'),
(1566349,54,24,48,8,'Přitáhne zajisté zhoubce na každé město, aniž ho které město znikne; zahyne i údolí, a zahlazena bude rovina, jakž praví Hospodin.'),
(1566350,54,24,48,9,'Dejte brky Moábovi, ať rychle uletí; nebo města jeho v poušť obrácena budou, tak že nebude žádného obyvatele v nich.'),
(1566351,54,24,48,10,'Zlořečený ten, kdož dělá dílo Hospodinovo lstivě, a zlořečený ten, kdož zdržuje meč svůj od krve.'),
(1566352,54,24,48,11,'Mělť jest pokoj Moáb od dětinství svého, a usadil se na kvasnicích svých, aniž býval přelíván z nádoby do nádoby, totiž do zajetí nechodíval; pročež zůstala v něm chuť jeho, a vůně jeho není proměněna.'),
(1566353,54,24,48,12,'Protož aj, dnové jdou, dí Hospodin, že pošli na něj ty, kteříž vpády činí, a zajmou jej, sudy pak jeho vyprázdní, a nádoby jeho roztříští.'),
(1566354,54,24,48,13,'I zahanben bude Moáb od Chámos, jako zahanbeni jsou dům Izraelský od Bethel naděje své.'),
(1566355,54,24,48,14,'Kterakž říkáte: Silní jsme a muži stateční k boji?'),
(1566356,54,24,48,15,'Pohuben bude Moáb a z měst svých vyjde, a nejvýbornější mládenci jeho půjdou k zabití, dí král, jehož jméno Hospodin zástupů.'),
(1566357,54,24,48,16,'Blízkoť jest bída Moábova, aby přišla, a trápení jeho pospíchá velice.'),
(1566358,54,24,48,17,'Litujte ho všickni okolní jeho, a všickni, kteříž víte o jménu jeho, rcete: Jak polámána jest hůl nejpevnější, prut nejozdobnější?'),
(1566359,54,24,48,18,'Sejdi z slávy své, a seď v žíni, ó ty, kterážs se usadila, dcero Dibonská; neboť zhoubce Moábův přitáhne proti tobě, zkazí ohrady tvé.'),
(1566360,54,24,48,19,'Postav se na cestě, a ohlédni se pilně, obyvatelkyně Aroer; vyptej se toho, kdož utíká, a té, kteráž uchází, rci: Co se děje?'),
(1566361,54,24,48,20,'Stydí se Moáb, že jest potřín. Kvělte a křičte, oznamte u Arnon, že hubí Moába.'),
(1566362,54,24,48,21,'Nebo soud přišel na zemi té roviny, na Holon a na Jasa a na Mefat,'),
(1566363,54,24,48,22,'I na Dibon a Nébo, a na Betdiblataim,'),
(1566364,54,24,48,23,'I na Kariataim a na Betgamul, a na Betmeon,'),
(1566365,54,24,48,24,'A na Kariot, a na Bozru i na všecka města země Moábské, daleká i blízká.'),
(1566366,54,24,48,25,'Odťat bude roh Moábův, a rámě jeho zlámáno bude, dí Hospodin.'),
(1566367,54,24,48,26,'Opojte jej, poněvadž se proti Hospodinu zpínal, až by se válel Moáb v vývratku svém, a byl za smích i on také.'),
(1566368,54,24,48,27,'Nebo zdali v posměchu nebyl u tebe Izrael? Zdali mezi zloději zastižen jest, že jakž jen promluvíš o něm, poskakuješ?'),
(1566369,54,24,48,28,'Zanechte měst, a přebývejte v skále, ó obyvatelé Moábští, a buďte podobni holubici hnízdící se daleko v rozsedlinách.'),
(1566370,54,24,48,29,'Slýchaliť jsme o pýše Moábově, že velmi pyšný jest, o vysokomyslnosti jeho a pýše jeho, i o nadutosti jeho, a povyšování se srdce jeho.'),
(1566371,54,24,48,30,'Známť já, dí Hospodin, vzteklost jeho, ale špatnáť jest ona k tomu; lži jeho nedovedouť toho.'),
(1566372,54,24,48,31,'Protož nad Moábskými kvílím, a nade vším Moábem křičím, pro obyvatele Kircheres úpí srdce.'),
(1566373,54,24,48,32,'Více než plakáno bylo Jazerských, plači tebe, ó vinný kmene Sibma. Rozvodové tvoji dostanouť se za moře, až k moři Jazerskému dosáhnou; na letní ovoce tvé a na vinobraní tvé zhoubce připadne.'),
(1566374,54,24,48,33,'I přestane veselé a plésání nad polem úrodným v zemi Moábské, a vínu z presu přítrž učiním; nebudou ho tlačívati s prokřikováním. Prokřikování nebudeť prokřikováním.'),
(1566375,54,24,48,34,'Více křičeti budou než Ezebonští, až do Eleale, až do Jasa vydávati budou hlas svůj, od Ségor až do Choronaim jako jalovice tříletá; nebo také i vody Nimrim vymizejí.'),
(1566376,54,24,48,35,'A tak učiním, dí Hospodin, přítrž Moábovi, obětujícímu na výsosti a kadícímu bohům jeho.'),
(1566377,54,24,48,36,'Protož srdce mé nad Moábem jako píšťalky zníti bude, srdce mé i nad obyvateli Kircheres jako píšťalky zníti bude, proto že i zboží nashromážděná se v nic obrátí.'),
(1566378,54,24,48,37,'Nebo na každé hlavě bude lysina, a každá brada oholena, na všech rukou řezání, a na bedrách žíně.'),
(1566379,54,24,48,38,'Na všech střechách Moábových i po ulicích jeho všudy jen kvílení; nebo rozrazím Moába jako nádobu neužitečnou, dí Hospodin.'),
(1566380,54,24,48,39,'Kvíliti budou: Jakť jest potřín, jak se obrátil zpět Moáb s hanbou! A jest Moáb v posměchu a k předěšení všechněm, kteříž jsou vůkol něho.'),
(1566381,54,24,48,40,'Nebo takto praví Hospodin: Aj, jako orlice přiletí a roztáhne křídla svá na Moába.'),
(1566382,54,24,48,41,'Vzato bude Kariot, i pevnosti pobrány budou, a bude srdce silných Moábských v ten den podobné srdci ženy svírající se.'),
(1566383,54,24,48,42,'I vyhlazen bude Moáb z lidu, proto že se proti Hospodinu zpínal.'),
(1566384,54,24,48,43,'Strach a jáma a osídlo nad tebou, ó obyvateli Moábský, praví Hospodin.'),
(1566385,54,24,48,44,'Kdo uteče před strachem, vpadne do jámy, a kdo vyleze z jámy, osídlem lapen bude; nebo uvedu na něj, totiž na Moába, rok navštívení jejich, dí Hospodin.'),
(1566386,54,24,48,45,'Stávaliť jsou v stínu Ezebon ti, kteříž utíkávali před násilím, ale oheň vyjde z Ezebon, a plamen z prostřed Seon, a zžíře kout Moábův a vrch hlavy těch, kteříž jen bouří.'),
(1566387,54,24,48,46,'Běda tobě, Moábe, zahyneť lid Chámosův; nebo pobráni budou synové tvoji do zajetí, i dcery tvé do zajetí.'),
(1566388,54,24,48,47,'A však zase přivedu zajaté Moábské v posledních dnech, dí Hospodin. Až potud soud o Moábovi.'),
(1566389,54,24,49,1,'Proti Ammonitským. Takto praví Hospodin: Což nemá žádných synů Izrael? Což dědice žádného nemá? Proč dědičně opanoval král jejich Gádu, a lid jeho v městech tohoto bydlí?'),
(1566390,54,24,49,2,'Protož aj, dnové jdou, dí Hospodin, že způsobím, aby slyšáno bylo proti Rabba Ammonitských troubení válečné, a aby bylo obráceno v hromadu rumu, a jiná města jeho ohněm vypálena. I opanuje Izrael ty, kteříž jej byli opanovali, praví Hospodin.'),
(1566391,54,24,49,3,'Kvěl Ezebon, když popléněno bude Hai, křičte, ó dcery Rabba, přepašte se žíněmi, plačte, a běžte přes ploty; nebo král váš do zajetí půjde, kněží jeho i knížata jeho spolu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566392,54,24,49,4,'Což se chlubíš údolími, když oplývá údolí tvé, ó dcero zpurná, kteráž doufáš v pokladech svých, říkajíc: Kdo by táhl na mne?'),
(1566393,54,24,49,5,'Aj, já uvedu na tebe strach, praví Panovník Hospodin zástupů, ze všeho vůkolí tvého, jímž rozehnáni budete všickni, a nebude žádného, kdo by shromáždil toulající se.'),
(1566394,54,24,49,6,'A však potom zase přivedu zajaté Ammonitské, dí Hospodin.'),
(1566395,54,24,49,7,'Proti Idumejským. Takto praví Hospodin zástupů: Což není více moudrosti v Teman? Zahynula rada od rozumných? Zmařena moudrost jejich?'),
(1566396,54,24,49,8,'Utíkejte, obraťe se, a hluboko se schovejte, obyvatelé Dedan; nebo bídu uvedu na Ezau v čas navštívení jeho.'),
(1566397,54,24,49,9,'Kdyby ti, kteříž zbírají víno, přišli na tebe, zdaž by nepozůstavili paběrků? Pakli zloději v noci, zdaž by škodili více nad potřebu svou?'),
(1566398,54,24,49,10,'Ale já obnažím Ezau, zodkrývám skrýše jeho, tak že se nebude moci ukryti. Pohubenoť bude símě jeho i bratří jeho i sousedé jeho, tak že nebude naprosto, kdo by řekl:'),
(1566399,54,24,49,11,'Zanech sirotků svých, já živiti je budu, a vdov svých mně se dověřte.'),
(1566400,54,24,49,12,'Takto zajisté praví Hospodin: Aj, ti, kteříž nemají žádného práva píti kalichu tohoto, předce pijí, ty pak sám abys toho naprosto prázen byl? Nebudeš prázen, ale jistotně píti budeš.'),
(1566401,54,24,49,13,'Nebo skrze sebe přisahám, dí Hospodin, že pustinou, útržkou, pouští a prokletím bude Bozra, a všecka města jeho budou pouští věčnou.'),
(1566402,54,24,49,14,'Pověst slyšel jsem od Hospodina, že posel k národům poslán jest: Shromažďte se, a táhněte proti němu; nuže, vstaňte k boji.'),
(1566403,54,24,49,15,'Nebo aj, způsobím to, abys byl za nejšpatnějšího mezi národy, v nevážnosti mezi lidmi.'),
(1566404,54,24,49,16,'To, že jsi hrozný, zklamá tě, i pýcha srdce tvého, ó ty, kterýž bydlíš v rozsedlinách skalních, kterýž se držíš vysokých pahrbků. Bys pak vysoko udělal hnízdo své jako orlice, i odtud tě strhnu, dí Hospodin.'),
(1566405,54,24,49,17,'I bude země Idumejská pustinou. Každý, kdož půjde skrze ni, užasne se, a diviti se bude nade všemi ranami jejími;'),
(1566406,54,24,49,18,'Jako podvrácení Sodomy a Gomory a sousedů jejich, praví Hospodin. Neosadí se tam žádný, aniž bydliti bude v ní syn člověka.'),
(1566407,54,24,49,19,'Aj, jako lev vystupuje i více než zdutí Jordána proti příbytku Nejsilnějšího, a však v okamžení zaženu jej z této země, a toho, kterýž jest vyvolený, ustanovím nad ní. Nebo kdo jest mně rovný? A kdo mi složí rok? A kdo jest ten pastýř, kterýž by se postavil proti mně?'),
(1566408,54,24,49,20,'Protož slyšte radu Hospodinovu, kterouž zavřel o Idumejských, a to, což myslil proti obyvatelům Temanským: Zajisté žeť je vyvlekou nejmenší tohoto stáda, zajisté že je popléní i příbytky jejich.'),
(1566409,54,24,49,21,'Od hřmotu pádu jejich třásti se bude ta země, hlas a křik jejich slyšán bude u moře Rudého.'),
(1566410,54,24,49,22,'Aj, jako orlice přitáhne a přiletí, a roztáhne křídla svá na Bozru, i bude srdce silných Idumejských v ten den podobné srdci ženy svírající se.'),
(1566411,54,24,49,23,'Proti Damašku. Zastydí se Emat i Arfad, nebo novinu zlou uslyší, a užasnou se, tak že se i moře zkormoutí, aniž se bude moci upokojiti.'),
(1566412,54,24,49,24,'Oslábne Damašek, obrátí se k utíkání, a hrůza podejme jej, svírání a bolesti zachvátí jej jako rodičku.'),
(1566413,54,24,49,25,'Ale řkou: Jakž by nemělo ostáti město slovoutné, město radosti mé?'),
(1566414,54,24,49,26,'Protož padnou mládenci jeho na ulicích jeho, a všickni muži bojovní vypléněni budou v ten den, dí Hospodin zástupů.'),
(1566415,54,24,49,27,'A zanítím oheň ve zdi Damašské, kterýž do konce zkazí paláce Benadadovy.'),
(1566416,54,24,49,28,'Proti Cedar a královstvím Azor, kteráž pohubiti má Nabuchodonozor král Babylonský. Takto praví Hospodin: Vstaňte, táhněte proti Cedar, a vypleňte národy východní.'),
(1566417,54,24,49,29,'Stany jejich i stáda jejich vezmou, kortýny jejich se vším nádobím jejich, i velbloudy jejich poberou sobě, a volati budou na ně: Strach jest vůkol.'),
(1566418,54,24,49,30,'Utecte, rozprchněte se rychle, skrejte se hluboce, obyvatelé Azor, dí Hospodin, neboť Nabuchodonozor král Babylonský složil proti vám radu, a vymyslil proti vám chytrost.'),
(1566419,54,24,49,31,'Vstaňte, táhněte proti národu upokojenému, kterýž sedí bezpečně, praví Hospodin. Nemá ani vrat ani závory, a samotní bydlejí.'),
(1566420,54,24,49,32,'Budou zajisté velbloudi jejich v loupež, a množství dobytků jejich v kořist, a rozptýlím na všeliký vítr ty, kteříž i v nejzadnějších koutech bydlejí, a ze všech stran uvedu bídu na ně, dí Hospodin.'),
(1566421,54,24,49,33,'I bude Azor příbytkem draků, pustinou až na věky; neosadí se tam žádný, aniž bude bydleti v něm syn člověka.'),
(1566422,54,24,49,34,'Slovo Hospodinovo, kteréž se stalo k Jeremiášovi proroku proti Elamitským, na počátku kralování Sedechiáše krále Judského, řkoucí:'),
(1566423,54,24,49,35,'Takto praví Hospodin zástupů: Aj, já polámi lučiště Elamitských, největší sílu jejich.'),
(1566424,54,24,49,36,'Uvedu zajisté na Elamitské čtyři větry ode čtyř stran světa, a rozptýlím je na všecky ty větry, tak že nebude národu, do něhož by se nedostal někdo z vyhnaných Elamitských.'),
(1566425,54,24,49,37,'A předěsím Elamitské před nepřátely jejich a před těmi, kteříž hledají bezživotí jejich. Uvedu, pravím, na ně zlé, prchlivost hněvu svého, dí Hospodin, a budu posílati za nimi meč, dokudž jim konce neučiním.'),
(1566426,54,24,49,38,'I postavím stolici svou mezi Elamitskými, a vypléním odtud krále i knížata, praví Hospodin.'),
(1566427,54,24,49,39,'A však stane se v posledních dnech, že zase přivedu zajaté Elamitské, dí Hospodin.'),
(1566428,54,24,50,1,'Slovo, kteréž mluvil Hospodin proti Babylonu a proti zemi Kaldejské skrze Jeremiáše proroka:'),
(1566429,54,24,50,2,'Oznamujte mezi národy a rozhlašujte, zdvihněte korouhev, rozhlašujte, netajte, rcete: Vzat bude Babylon, zahanben bude Bél, potřín bude Merodach, zahanbeny budou modly jeho, potříni budou ukydaní bohové jeho.'),
(1566430,54,24,50,3,'Nebo přitáhne na něj národ od půlnoci, kterýž obrátí zemi jeho v pustinu, tak že nebude obyvatele v ní. Od člověka až do hovada vystěhují se, odejdou.'),
(1566431,54,24,50,4,'V těch dnech a toho času, dí Hospodin, přijdou synové Izraelští, oni i synové Judští spolu; plačíce, ochotně půjdou, a Hospodina Boha svého hledati budou.'),
(1566432,54,24,50,5,'Na cestu k Sionu ptáti se budou, a obrátíce se tam, řeknou: Poďte a připojte se k Hospodinu smlouvou věčnou, nepřicházející v zapomenutí.'),
(1566433,54,24,50,6,'Ovce hynoucí jsou lid můj, pastýři jejich působí to, aby bloudily, a po horách se toulaly, s hůry na pahrbek chodily, zapomenuvše na příbytky své.'),
(1566434,54,24,50,7,'Všickni, kteříž je nalézají, zžírají je, a nepřátelé jejich říkají: Nebudeme nic vinni, proto že hřeší proti Hospodinu. Příbytek spravedlnosti a otců jejich naděje jest Hospodin.'),
(1566435,54,24,50,8,'Vystěhujte se z prostředku Babylona, a z země Kaldejské vyjděte, a buďte jako kozlové před stádem.'),
(1566436,54,24,50,9,'Nebo aj, já vzbudím a přivedu na Babylon shromáždění národů velikých z země půlnoční, kteřížto sšikují se proti němu, i bude dobyt odtud. Kterýchžto střely jsou jako silného, jenž sirobu uvodí; žádnáť se nenavrátí na prázdno.'),
(1566437,54,24,50,10,'I bude země Kaldejských v loupež; všickni, kteříž ji loupiti budou, nasytí se, dí Hospodin.'),
(1566438,54,24,50,11,'Proto že se veselíte, proto že pléšete, ó dráči dědictví mého, proto že jste zbujněli jako jalovice vytylá, a provyskujete jako rekové,'),
(1566439,54,24,50,12,'Zahanbena bude matka vaše velice, a zapýří se rodička vaše: Aj, nejzadnější z národů, poušť, země vyprahlá a pustina.'),
(1566440,54,24,50,13,'Pro prchlivost Hospodinovu nebude v ní bydleno, ale velmi spustne všecko. Každý, kdož půjde mimo Babylon, užasne se, a diviti se bude nade všemi ranami jeho.'),
(1566441,54,24,50,14,'Sšikujte se proti Babylonu vůkol všickni, kteříž natahujete lučiště, střílejte proti němu, nelitujte střely; nebo hřešil proti Hospodinu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566442,54,24,50,15,'Křičte proti němu vůkol: Poddal se, padli základové jeho, pobořeny jsou zdi jeho. Nebo pomsta Hospodinova jest, uveďte pomstu na něj; jakž činíval, učiňte jemu.'),
(1566443,54,24,50,16,'Vypleňte rozsevače z Babylona, i držícího srp v čas žně; před mečem hubícím každý nechť se k lidu svému obrátí, a každý do země své nechť uteče.'),
(1566444,54,24,50,17,'Hovádko zahnané jest Izrael, kteréž lvové splašili. Nejprvé zžíral je král Assyrský, tento pak poslednější, Nabuchodonozor král Babylonský, kosti jeho potřel.'),
(1566445,54,24,50,18,'Protož toto praví Hospodin zástupů, Bůh Izraelský: Aj, já navštívím krále Babylonského i zemi jeho, jako jsem navštívil krále Assyrského.'),
(1566446,54,24,50,19,'A přivedu zase Izraele do příbytku jeho, aby se pásl na Karmeli a Bázan, a na hoře Efraim, a v Galád aby se sytila duše jeho.'),
(1566447,54,24,50,20,'V těch dnech a toho času, dí Hospodin, byla-li by vyhledávána nepravost Izraelova, nebude žádné, a hříchové Judovi, však nebudou nalezení; nebo odpustím těm, kteréž pozůstavím.'),
(1566448,54,24,50,21,'Proti té zemi zpurných táhni, a proti obyvatelům pomsty; zhub je a zahlaď jako proklaté i utíkající, dí Hospodin. Učiniž, pravím, všecko, jakž přikazuji tobě,'),
(1566449,54,24,50,22,'Ať jest hluk boje v té zemi a potření veliké.'),
(1566450,54,24,50,23,'Jakž by posekáno a polámáno býti mohlo kladivo vší země? Jak by k užasnutí Babylon býti mohl mezi národy?'),
(1566451,54,24,50,24,'Polékl jsem na tě, ó Babylone, pročež vzat budeš, než zvíš. Nalezen, ano i polapen budeš, proto že jsi směl potýkati se s Hospodinem.'),
(1566452,54,24,50,25,'Otevřel Hospodin poklad svůj, a vynesl nástroje hněvu svého; nebo dílo toto jest Panovníka Hospodina zástupů v zemi Kaldejské.'),
(1566453,54,24,50,26,'Přitáhněte na ni od konce země, zotvírejte obilnice její, šlapejte po ní jako po stozích, a zahlaďte ji jako proklatou, tak aby z ní ničeho nepozůstalo.'),
(1566454,54,24,50,27,'Zbíte mečem všecky volky její, nechť sstoupí k zabití; běda jim, když přijde den jejich, čas navštívení jejich.'),
(1566455,54,24,50,28,'Hlas utíkajících a ucházejících z země Babylonské, aby oznámili na Sionu pomstu Hospodina Boha našeho, pomštění chrámu jeho.'),
(1566456,54,24,50,29,'Shromažďte proti Babylonu nejudatnější, všickni natahující lučiště, položte se proti němu vůkol, ať nelze jemu ujíti. Odplaťte jemu podlé skutků jeho, všecko, jakž dělával, učiňte jemu; nebo proti Hospodinu pýchal, proti Svatému Izraelskému.'),
(1566457,54,24,50,30,'Protož padnou mládenci jeho na ulicích jeho, a všickni muži bojovní jeho vypléněni budou v ten den, dí Hospodin.'),
(1566458,54,24,50,31,'Aj, já jsem proti tobě, ó pýcho, praví Panovník Hospodin zástupů; neboť přišel den tvůj, čas, abych tě navštívil.'),
(1566459,54,24,50,32,'Poklesne se zajisté ten pyšný a padne, a nebude žádného, kdo by jej zdvihl; a zanítím oheň v městech jeho, kterýžto zžíře všecka vůkolí jeho.'),
(1566460,54,24,50,33,'Takto praví Hospodin zástupů: Utištěni jsou synové Izraelští, i s syny Judskými, a všickni, kteříž je zjímali, drží je, nechtí propustiti jich.'),
(1566461,54,24,50,34,'Ale vykupitel jejich silný, jehož jméno jest Hospodin zástupů, jistotně povede při jejich, aby pokoj způsobil této zemi, a pohnul obyvateli Babylonskými.'),
(1566462,54,24,50,35,'Meč na Kaldejské, dí Hospodin, a na obyvatele Babylonské, i na knížata jeho i na mudrce jeho.'),
(1566463,54,24,50,36,'Meč na lháře, aby se zbláznili, meč na silné jeho, aby potříni byli.'),
(1566464,54,24,50,37,'Meč na koně jeho a na vozy jeho, i na všecku tu směsici, kteráž jest u prostřed něho, aby byli jako ženy; meč na poklady jeho, aby rozchvátáni byli.'),
(1566465,54,24,50,38,'Sucho na vody jeho, aby vyschly; nebo země plná jest rytin, a při modlách bláznívají.'),
(1566466,54,24,50,39,'Protož bydliti budou tam šelmy s hroznými potvorami, bydliti budou v ní i mladé sovy; a nebude tam bydleno na věky, ani přebýváno od národu až do pronárodu.'),
(1566467,54,24,50,40,'Podobná bude k podvrácení hroznému Sodomy a Gomory i sousedů jejich, dí Hospodin; neosadí se tam žádný, aniž bydliti bude v ní syn člověka.'),
(1566468,54,24,50,41,'Aj, lid přitáhne od půlnoci, a národ veliký, i králové znamenití, vzbuzeni jsouce od stran země.'),
(1566469,54,24,50,42,'Lučiště a kopí pochytí, ukrutní budou, a neslitují se; hlas jejich jako moře zvučeti bude, a na koních pojedou, sšikovaní jako muž udatný k boji proti tobě, ó dcero Babylonská.'),
(1566470,54,24,50,43,'Král Babylonský jakž uslyší pověst o nich, opadnou ruce jeho, úzkost zachvátí jej, bolest jako rodičku.'),
(1566471,54,24,50,44,'Aj, jako lev vystupuje, více než zdutí Jordána proti příbytku Nejsilnějšího, a však v okamžení zaženu jej z této země, a toho, kterýž jest vyvolený, ustanovím nad ní. Nebo kdo jest mně rovný? A kdo mi složí rok? A kdo jest ten pastýř, kterýž by se postavil proti mně?'),
(1566472,54,24,50,45,'Protož slyšte radu Hospodinovu, kterouž zavřel o Babylonu, a to, což myslil proti zemi Kaldejské: Zajisté žeť je vyvlekou nejmenší tohoto stáda, zajisté že je popléní i příbytek jejich.'),
(1566473,54,24,50,46,'Od zvuku při dobývání Babylona třásti se bude ta země, a křik mezi národy slyšán bude.'),
(1566474,54,24,51,1,'Takto praví Hospodin: Aj, já vzbudím proti Babylonu a proti těm, kteříž bydlejí u prostřed povstávajících proti mně, vítr hubící.'),
(1566475,54,24,51,2,'A pošli na Babylon ty, jenž vějí, kteřížto převívati budou jej, a vyprázdní zemi jeho, když budou proti němu vůkol v den bídy.'),
(1566476,54,24,51,3,'Natahujícímu, kterýž silně natahuje lučiště své, a kráčí v pancíři svém, dím: Neslitovávejtež se nad mládenci jeho, zahlaďte jako proklaté všecko vojsko jeho.'),
(1566477,54,24,51,4,'Ať padnou zbití v zemi Kaldejské, a probodnutí na ulicích jeho.'),
(1566478,54,24,51,5,'Nebo není opuštěn Izrael a Juda od Boha svého, od Hospodina zástupů, ačkoli země jejich plná jest provinění proti Svatému Izraelskému.'),
(1566479,54,24,51,6,'Utecte z prostředku Babylona, a zachovejte jeden každý život svůj, abyste nebyli vypléněni v nepravosti jeho. Nebo čas bude pomsty Hospodinovy, sám odplatu dá jemu.'),
(1566480,54,24,51,7,'Byltě koflíkem zlatým Babylon v ruce Hospodinově, opojujícím všecku zemi; víno jeho pili národové, protož se zbláznili národové.'),
(1566481,54,24,51,8,'Ale v náhle padne Babylon, a potřín bude. Kvělte nad ním, nabeřte masti pro bolesti jeho, snad bude moci zhojen býti.'),
(1566482,54,24,51,9,'Hojili jsme Babylon, ale není zhojen, opusťme jej, a poďme jeden každý do země své; nebo až k nebi dosahá soud jeho, a vznesen jest až k nejvyšším oblakům.'),
(1566483,54,24,51,10,'Vyvedl Hospodin při naši; poďte, a vypravujme na Sionu dílo Hospodina Boha našeho.'),
(1566484,54,24,51,11,'Vytřete střely, shledejte, což nejvíc můžete, pavéz, Hospodin vzbudil ducha králů Médských, proto že proti Babylonu usouzení jeho jest, aby jej zkazil; pomsta zajisté jest Hospodinova, pomštění chrámu jeho.'),
(1566485,54,24,51,12,'Na zdech Babylonských zdvihněte korouhev, osaďte stráž, postavte strážné, připravte zálohy; nebo i myslil Hospodin, i učiní, což řekl proti obyvatelům Babylonským.'),
(1566486,54,24,51,13,'Ó ty, kterýž bydlíš při vodách velikých, ó kterýž máš množství pokladů, přišloť skončení tvé, cíl lakomství tvého.'),
(1566487,54,24,51,14,'Přisáhlť jest Hospodin zástupů skrze samého sebe: Jistotně naplním tě lidmi jako brouky, kteříž by prokřikovali nad tebou radostně:'),
(1566488,54,24,51,15,'Ten, kterýž učinil zemi mocí svou, kterýž utvrdil okršlek světa moudrostí svou, a opatrností svou roztáhl nebesa,'),
(1566489,54,24,51,16,'Kterýžto, když vydává hlas, ječí vody na nebi, a kterýž působí to, aby vystupovaly páry od kraje země, blýskání s deštěm přivodí, a vyvodí vítr z pokladů svých.'),
(1566490,54,24,51,17,'Tak zhlupěl každý člověk, že nezná toho, že zahanben bývá každý zlatník od rytiny; nebo faleš jest slitina jeho, a není ducha v nich.'),
(1566491,54,24,51,18,'Marnost jsou a dílo podvodů; v čas, v němž navštíveni budou, zahynou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566492,54,24,51,19,'Neníť jim podobný díl Jákobův; nebo on jest stvořitelem všeho, a částka dědictví jeho, Hospodin zástupů jest jméno jeho.'),
(1566493,54,24,51,20,'Ty jsi mým kladivem rozrážejícím, nástroji válečnými, abych rozrážel skrze tebe národy, a kazil skrze tebe království,'),
(1566494,54,24,51,21,'Abych rozrážel skrze tebe koně s jezdcem jeho, abych rozrážel skrze tebe vůz s tím, kdož jezdí na něm.'),
(1566495,54,24,51,22,'Abych rozrážel skrze tebe muže i ženu, abych rozrážel skrze tebe starého i dítě, abych rozrážel skrze tebe mládence i pannu,'),
(1566496,54,24,51,23,'Abych rozrážel skrze tebe pastýře s stádem jeho, abych rozrážel skrze tebe oráče s spřežením jeho, abych rozrážel skrze tebe vývody a knížata.'),
(1566497,54,24,51,24,'Ale jižť odplatím Babylonu i všechněm obyvatelům Kaldejským za všecko bezpráví jejich, kteréž činili Sionu před očima vašima, dí Hospodin.'),
(1566498,54,24,51,25,'Aj, já jsem proti tobě, ó horo, kteráž hubíš, dí Hospodin, kteráž hubíš všecku zemi; a vztáhna ruku svou na tebe, svalím tě z těch skal, a obrátím tě v horu spálenou.'),
(1566499,54,24,51,26,'A nevezmou z tebe kamene k úhlu, ani kamene k základům; nebo pustinou věčnou budeš, praví Hospodin.'),
(1566500,54,24,51,27,'Vyzdvihněte korouhev v zemi, trubte trubou mezi národy, připravte proti němu národy, svolejte proti němu království Ararat, Minni, Ascenez, ustanovte hejtmana proti němu, přiveďte koní jako brouků počet nesčíslný.'),
(1566501,54,24,51,28,'Připravte proti Babylonu národy, krále země Médské, vývody její a všecka knížata její, i všecku zemi panování jejich.'),
(1566502,54,24,51,29,'I bude se třásti země a bolestiti, když vykonáváno bude usouzení Hospodinovo proti Babylonu, aby obrátil zemi Babylonskou v pustinu, v níž by se žádný neosazoval.'),
(1566503,54,24,51,30,'Přestanou silní Babylonští bojovati, seděti budou v ohradách, zhyne síla jejich, budou jako ženy, zapálí příbytky jejich, polámány budou závory jejich.'),
(1566504,54,24,51,31,'Pošta jedna druhou potká, a posel posla, aby oznámeno bylo králi Babylonskému, že vzato jest město jeho na kraji,'),
(1566505,54,24,51,32,'A že brodové vzati, i jezera vypálena ohněm, a muži bojovní předěšeni.'),
(1566506,54,24,51,33,'Nebo takto praví Hospodin zástupů, Bůh Izraelský: Dcera Babylonská jest jako humno, jehož nabíjení čas; ještě maličko, a přijde čas žně její.'),
(1566507,54,24,51,34,'Vyjídá mne, potírá mne Nabuchodonozor král Babylonský, vystavuje mne nádobu prázdnou, požírá mne jako drak, naplňuje břich svůj rozkošemi mými, vyhání mne.'),
(1566508,54,24,51,35,'Násilé, kteréž se mně a mému tělu děje, přijdiž na Babylon, praví obyvatelkyně Sionská, a krev má na obyvatele země Kaldejské, praví Jeruzalém.'),
(1566509,54,24,51,36,'Protož takto praví Hospodin: Aj, já vyvedu při tvou, a pomstím tě; nebo vysuším moře jeho, vysuším i vrchoviště jeho.'),
(1566510,54,24,51,37,'I bude Babylon v hromady, v příbytek draků, v užasnutí a ckání, tak že nebude v něm žádného obyvatele.'),
(1566511,54,24,51,38,'Jako lvové spolu řváti budou, skučeti budou jako lvíčata.'),
(1566512,54,24,51,39,'Když se rozpálí, učiním jim hody, a tak je opojím, že zkřiknouti a snem věčným zesnouti musejí, tak aby neprocítili, dí Hospodin.'),
(1566513,54,24,51,40,'Povedu je jako berany k zabití, jako skopce s kozly.'),
(1566514,54,24,51,41,'Jakž by dobyt býti mohl Sesák? Jakž by vzata býti mohla chvála vší země? Jakž by přijíti mohl na spuštění Babylon mezi národy?'),
(1566515,54,24,51,42,'Vystoupí proti Babylonu moře, množstvím vlnobití jeho přikryt bude.'),
(1566516,54,24,51,43,'Města jeho budou pustinou, zemí vyprahlou a pustou, zemí, v jejíchž městech neosadí se žádný, aniž projde skrze ně syn člověka.'),
(1566517,54,24,51,44,'Navštívím také Béle v Babyloně, a vytrhnu, což sehltil, z úst jeho, i nepohrnou se k němu více národové; také i zdi Babylonské padnou.'),
(1566518,54,24,51,45,'Vyjděte z prostředku jeho, lide můj, a vysvoboďte jeden každý duši svou od prchlivosti hněvu Hospodinova.'),
(1566519,54,24,51,46,'A nebuďtež choulostivého srdce, aniž se bojte pověsti, kteráž slyšána bude v té zemi, když přijde tohoto roku pověst, a potom druhého roku pověst, i ukrutenství v zemi, a pán na pána.'),
(1566520,54,24,51,47,'Protož aj, dnové přijdou, že navštívím rytiny Babylonské, a všecka země jeho zahanbena bude, i všickni zbití jeho padnou u prostřed něho.'),
(1566521,54,24,51,48,'I budou prozpěvovati nad Babylonem nebesa i země, a cožkoli v nich jest, když na něj od půlnoci přitáhnou ti zhoubcové, dí Hospodin.'),
(1566522,54,24,51,49,'Ano i Babylon padnouti musí, ó zbití Izraelovi, i s Babylonem padnou zbití vší země jeho.'),
(1566523,54,24,51,50,'Ó kdož jste znikli meče, jděte, nezastavujte se; zpomínejte, daleko jsouce, na Hospodina, a Jeruzalém nechť vstupuje na srdce vaše.'),
(1566524,54,24,51,51,'Rcete: Stydímeť se, že slýcháme útržku, hanbí se tváře naše, že cizozemci chodí do svatyní domu Hospodinova.'),
(1566525,54,24,51,52,'Protož aj, dnové přijdou, dí Hospodin, že navštívím rytiny jeho, a po vší zemi jeho stonati bude zraněný.'),
(1566526,54,24,51,53,'Byť pak vstoupil Babylon na nebe, a byť pak ohradil velmi vysokou pevnost svou, přitáhnou ode mne na něj zhoubcové, praví Hospodin.'),
(1566527,54,24,51,54,'Zvuk křiku z Babylona, a potření veliké z země Kaldejské.'),
(1566528,54,24,51,55,'Nebo Hospodin popléní Babylon, a vyhladí z něho hřmot veliký, byť pak zvučela vlnobití jejich jako vody mnohé, vydáván byl hluk hlasu jejich,'),
(1566529,54,24,51,56,'Když přitáhne na něj, na Babylon zhoubce. I budou jati silní jeho, potříno bude lučiště jejich; nebo Bůh silný odplatí, Hospodin vrchovatě odplatí.'),
(1566530,54,24,51,57,'Opojím knížata jeho i moudré jeho, vývody jeho i znamenitější jeho i silné jeho, aby zesnuli snem věčným, a neprocítili, dí král, jehož jméno jest Hospodin zástupů.'),
(1566531,54,24,51,58,'Takto praví Hospodin zástupů: Oboje zed Babylonská velmi široká do gruntu zbořena bude, a brány jeho vysoké ohněm spáleny budou, a tak nadarmo pracovati budou lidé a národové při ohni, až ustanou.'),
(1566532,54,24,51,59,'Slovo, kteréž přikázal Jeremiáš prorok Saraiášovi synu Neriášovu, synu Maaseiášovu, když se vypravil od Sedechiáše krále Judského do Babylona, léta čtvtého kralování jeho, (byl pak Saraiáš kníže Menuchské),'),
(1566533,54,24,51,60,'Když sepsal Jeremiáš všecko zlé, kteréž přijíti mělo na Babylon, do knihy jedné, všecka ta slova, kteráž jsou psána proti Babylonu.'),
(1566534,54,24,51,61,'I řekl Jeremiáš Saraiášovi: Když přijdeš do Babylona, a uzříš jej, tedy čti všecka ta slova.'),
(1566535,54,24,51,62,'A rci: Ó Hospodine, ty jsi mluvil o místě tomto, že je zkazíš, tak že nebude v něm obyvatele, od člověka až do hovada, ale že hrozně zpuštěno na věky bude.'),
(1566536,54,24,51,63,'Když pak do konce přečteš knihu tuto, přivaž k ní kámen, a hoď ji do prostřed Eufrates,'),
(1566537,54,24,51,64,'A rci: Tak potopen bude Babylon, a nepovstane z toho zlého, kteréž já uvedu na něj, ačkoli ustávati budou. Až potud slova Jeremiášova.'),
(1566538,54,24,52,1,'V jedenmecítma letech byl Sedechiáš, když počal kralovati, a jedenácte let kraloval v Jeruzalémě. Jméno matky jeho bylo Chamutal, dcera Jeremiášova z Lebna.'),
(1566539,54,24,52,2,'I činil to, což jest zlého před očima Hospodinovýma, všecko tak, jakž byl dělal Joakim.'),
(1566540,54,24,52,3,'Nebo se to dálo pro rozhněvání Hospodinovo proti Jeruzalému a Judovi, až je i zavrhl od tváři své. V tom zprotivil se Sedechiáš králi Babylonskému.'),
(1566541,54,24,52,4,'Stalo se pak léta devátého kralování jeho, měsíce desátého, v desátý den téhož měsíce, že přitáhl Nabuchodonozor král Babylonský se vším vojskem svým k Jeruzalému, a položili se u něho, a vzdělali proti němu hradbu vůkol.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566542,54,24,52,5,'A bylo město obleženo až do jedenáctého léta krále Sedechiáše.'),
(1566543,54,24,52,6,'V kterémžto, měsíce čtvrtého, devátého dne téhož měsíce, rozmohl se hlad v městě, a neměl chleba lid země.'),
(1566544,54,24,52,7,'I prolomeny jsou zdi městské, a všickni muži bojovní utekli, a vyšli z města v noci skrze bránu mezi dvěma zdmi, u zahrady královské, (Kaldejští pak leželi okolo města), a ušli cestou pouště.'),
(1566545,54,24,52,8,'I honilo vojsko Kaldejské krále, a postihli Sedechiáše na rovinách Jerišských, a všecko vojsko jeho rozprchlo se od něho.'),
(1566546,54,24,52,9,'A tak javše krále, přivedli ho k králi Babylonskému do Ribla v zemi Emat, kdežto učinil o něm soud.'),
(1566547,54,24,52,10,'I zmordoval král Babylonský syny Sedechiášovy před očima jeho, ano i všecka knížata Judská zmordoval v Ribla.'),
(1566548,54,24,52,11,'Oči pak Sedechiášovy oslepil, a svázav ho řetězy ocelivými král Babylonský, dal jej dovésti do Babylona, a dal jej do vězení až do dne smrti jeho.'),
(1566549,54,24,52,12,'Potom měsíce pátého, desátého dne téhož měsíce, léta devatenáctého kralování Nabuchodonozora krále Babylonského, přitáhl Nebuzardan, hejtman nad žoldnéři, kterýž sloužíval králi Babylonskému, do Jeruzaléma.'),
(1566550,54,24,52,13,'A zapálil dům Hospodinův, i dům královský, i všecky domy v Jeruzalémě, a tak všecky domy veliké vypálil ohněm.'),
(1566551,54,24,52,14,'Všecky také zdi Jeruzalémské vůkol pobořilo všecko vojsko Kaldejské, kteréž bylo s tím hejtmanem nad žoldnéři.'),
(1566552,54,24,52,15,'Přitom z chaterného lidu, totiž ostatek lidu, kterýž byl zůstal v městě, i poběhlce, kteříž byli ustoupili k králi Babylonskému, a jiný obecný lid zavedl Nebuzardan, hejtman nad žoldnéři.'),
(1566553,54,24,52,16,'Toliko něco chaterného lidu země zanechal Nebuzardan, hejtman nad žoldnéři, aby byli vinaři a oráči.'),
(1566554,54,24,52,17,'Nadto sloupy měděné, kteříž byli v domě Hospodinově, i podstavky i moře měděné, kteréž bylo v domě Hospodinově, ztloukli Kaldejští, a odvezli všecku měď z nich do Babylona.'),
(1566555,54,24,52,18,'Též hrnce. lopaty a nástroje hudebné, a kotlíky a kadidlnice, i všecky nádoby měděné, jimiž sloužili, pobrali.'),
(1566556,54,24,52,19,'I medenice a nádoby k oharkům, s kotlíky a hrnci, a svícny, a kadidlnice a koflíky, a cožkoli zlatého a stříbrného bylo, pobral hejtman nad žoldnéři;'),
(1566557,54,24,52,20,'Sloupy dva, moře jedno, a volů dvanáct měděných, kteříž byli pod podstavky, jichž byl nadělal král Šalomoun do domu Hospodinova. Nebylo váhy mědi všech těch nádob.'),
(1566558,54,24,52,21,'Nebo sloupů těch, osmnácti loket byla výška sloupu jednoho, kterýž okolek měl dvanácti loktů, ztlouští pak čtyř prstů byl dutý.'),
(1566559,54,24,52,22,'A makovice na něm měděná, a makovice jedné výška pěti loket, a mřežování i jablka zrnatá na té makovici vůkol; všecko bylo měděné. Takovýž byl i sloup druhý s zrnatými jablky.'),
(1566560,54,24,52,23,'A bylo jablek zrnatých devadesát a šest po každé straně; všudy jablek zrnatých bylo po stu na mřežování vůkol.'),
(1566561,54,24,52,24,'Vzal také hejtman nad žoldnéři Saraiáše kněze předního, a Sofoniáše kněze nižšího, a tři strážné prahu.'),
(1566562,54,24,52,25,'A z města vzal komorníka jednoho, kterýž byl hejtmanem nad muži bojovnými, a sedm mužů, jenž bývali při králi, kteříž nalezeni byli v městě, a předního spisovatele vojska, kterýž popisoval vojsko z lidu země, a šedesáte mužů z lidu země, kteříž nalezeni byli v městě.'),
(1566563,54,24,52,26,'Zjímav tedy je Nebuzardan, hejtman nad žoldnéři, přivedl je k králi Babylonskému do Ribla.'),
(1566564,54,24,52,27,'I pobil je král Babylonský, a zmordoval je v Ribla v zemi Emat, a tak zaveden jest Juda z země své.'),
(1566565,54,24,52,28,'Tenť jest lid, kterýž zavedl Nabuchodonozor léta sedmého, Judských tři tisíce a třimecítma.'),
(1566566,54,24,52,29,'Léta osmnáctého Nabuchodonozora zavedl z Jeruzaléma duší osm set třidceti a dvě.'),
(1566567,54,24,52,30,'Léta třimecítmého Nabuchodonozora zavedl Nebuzardan, hejtman nad žoldnéři, Judské, duší sedm set čtyřidceti a pět, všech duší čtyry tisíce a šest set.'),
(1566568,54,24,52,31,'Stalo se také třidcátého sedmého léta po zajetí Joachina krále Judského, dvanáctého měsíce, dvadcátého pátého dne téhož měsíce, povýšil Evilmerodach král Babylonský toho léta, když počal kralovati, Joachina krále Judského, pustiv ho z žaláře.'),
(1566569,54,24,52,32,'A mluvil s ním dobrotivě, i stolici jeho postavil nad stolice králů, kteříž s ním byli v Babyloně.'),
(1566570,54,24,52,33,'Změnil též roucho jeho, kteréž měl v žaláři, a jídal chléb před ním vždycky, po všecky dny života svého.'),
(1566571,54,24,52,34,'Nebo vyměřený pokrm ustavičně dáván byl jemu od krále Babylonského, a to na každý den, až do dne smrti jeho, po všecky dny života jeho.'),
(1566572,54,25,1,1,'Ach, město tak lidné, jakť jest samotné zůstalo, a učiněno jako vdova! Nejznamenitější mezi národy, přední mezi krajinami pod plat uvedeno.'),
(1566573,54,25,1,2,'Ustavičně pláče v noci, a slzy jeho na lících jeho, ze všech milovníků svých nemá žádného potěšitele; všickni přátelé jeho nevěrně se k němu mají, obrátili se mu v nepřátely.'),
(1566574,54,25,1,3,'Zastěhoval se Juda, proto že byl trápen a u veliké porobě, však osadiv se mezi pohany, nenalézá odpočinutí; všickni, kteříž jej honí, postihají jej v těsně.'),
(1566575,54,25,1,4,'Cesty Siona kvílí, že žádný nepřichází k slavnosti. Všecky brány jeho zpustly, kněží jeho vzdychají, panny jeho smutné jsou, on pak sám pln jest hořkosti.'),
(1566576,54,25,1,5,'Nepřátelé jeho jsou hlavou, odpůrcům jeho šťastně se vede; nebo jej Hospodin zarmoutil pro množství přestoupení jeho. Maličcí jeho odešli do zajetí před oblíčejem nepřítele.'),
(1566577,54,25,1,6,'A tak odňata od dcery Sionské všecka okrasa její. Knížata její jsou podobná jelenům, kteříž nenalézají pastvy, a ucházejí bez moci před tím, kdož je honí.'),
(1566578,54,25,1,7,'Rozpomínáť se dcera Jeruzalémská ve dnech trápení svého a kvílení svého na všecka svá utěšení, kteráž mívala ode dnů starodávních, když padá lid její od ruky nepřítele, nemajíc žádného, kdo by ji retoval. Protivníciť se jí dívajíce, posmívají se klesnutí jejímu.'),
(1566579,54,25,1,8,'Těžce hřešila dcera Jeruzalémská, protož jako nečistá odloučena jest. Všickni, kteříž ji v poctivosti mívali, neváží jí sobě, proto že vidí nahotu její; ona pak vzdychá, obrácena jsuci zpět.'),
(1566580,54,25,1,9,'Nečistota její na podolcích jejích; nepamatovala na skončení své, protož patrně klesá, nemajíc žádného, kdo by ji potěšil. Popatřiž, Hospodine, na trápení mé, neboť se vyvýšil nepřítel.'),
(1566581,54,25,1,10,'Sáhl rukou svou nepřítel na všecky drahé věci její; nebo musí se dívati pohanům, an chodí do svatyně její, o čemž jsi byl přikázal, aby tobě nevcházeli do shromáždění.'),
(1566582,54,25,1,11,'Všecken lid její vzdychajíce, hledají chleba, vynakládají nejdražší věci své za pokrm k očerstvení života. Vzezřiž, Hospodine, a popatřiž, neboť jsem v nevážnosti.'),
(1566583,54,25,1,12,'Nic-liž vám do toho, ó všickni, kteříž tudyto jdete? Pohleďte a vizte, jest-li bolest podobná bolesti mé, kteráž jest mi učiněna, jak mne zámutkem naplnil Hospodin v den prchlivosti hněvu svého.'),
(1566584,54,25,1,13,'Seslal s výsosti oheň do kostí mých, kterýž opanoval je; roztáhl sít nohám mým, obrátil mne zpět, obrátil mne v pustinu, celý den neduživá jsem.'),
(1566585,54,25,1,14,'Tuze svázáno jest rukou jeho jho přestoupení mých, tuze spletené houžve připadly na hrdlo mé, porazilo sílu mou; vydal mne Pán v ruku nepřátel, nemohuť povstati.'),
(1566586,54,25,1,15,'Pošlapal Pán všecky mé silné u prostřed mne, svolal proti mně zástupy, aby potřel mládence mé, tlačil Pán presem pannu dceru Judskou.'),
(1566587,54,25,1,16,'Pro tyť věci já pláči, z očí mých, z očí mých tekou vody, a že jest vzdálen ode mne potěšitel, kterýž by očerstvil duši mou; synové moji jsou pohubeni, nebo ssilil se nepřítel.'),
(1566588,54,25,1,17,'Rozprostírá dcera Sionská ruce své, nemá žádného, kdo by ji potěšil; vzbudiltě Hospodin proti Jákobovi všudy vůkol něho nepřátely jeho, mezi nimiž jest dcera Jeruzalémská jako pro nečistotu oddělená.'),
(1566589,54,25,1,18,'Spravedlivý jest Hospodin, neboť jsem na odpor činila ústům jeho. Slyšte medle všickni lidé, a vizte bolest mou; panny mé i mládenci moji odebrali se do zajetí.'),
(1566590,54,25,1,19,'Volala jsem na milovníky své, oni oklamali mne; kněží moji a starci moji v městě pomřeli, hledajíce pokrmu, aby posilnili života svého.'),
(1566591,54,25,1,20,'Popatřiž, ó Hospodine, neboť mi úzko; vnitřnosti mé zkormouceny jsou, srdce mé svadne ve mně, proto že jsem na odpor velice činila. Vně meč na sirobu přivodí, v domě pouhá smrt.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566592,54,25,1,21,'Slýchajíť, že já vzdychám, ale není žádného, kdo by mne potěšil. Všickni nepřátelé moji slyšíce o mých bídách, radují se, že jsi to učinil, a přivedl den předohlášený, ale budouť mně podobní.'),
(1566593,54,25,1,22,'Nechť přijde všecka nešlechetnost jejich před oblíčej tvůj, a učiň jim, jakož jsi učinil mně pro všecka přestoupení má; neboť jsou mnohá úpění má, a srdce mé neduživé.'),
(1566594,54,25,2,1,'Jak hustým oblakem prchlivosti své přikryl Pán dceru Sionskou! Shodil s nebe na zem slávu Izraelovu, aniž se rozpomenul na podnože noh svých v den prchlivosti své.'),
(1566595,54,25,2,2,'Sehltil Pán beze vší lítosti všecky příbytky Jákobovy, zbořil v prchlivosti své ohrady dcery Judské, udeřil jimi o zem, v potupu uvedl království i knížata její.'),
(1566596,54,25,2,3,'Odťal v rozpálení hněvu všecken roh Izraelův, odvrátil zpět pravici svou od nepřítele, a rozpáliv se proti Jákobovi jako oheň plápolající, pálí do cela vůkol.'),
(1566597,54,25,2,4,'Natáhl lučiště své jako nepřítel, postavil pravici svou jako protivník, i zbil všecky nejzdařilejší z lidu, a vylil do stánku dcery Sionské jako oheň prchlivost svou.'),
(1566598,54,25,2,5,'Učiněn jest Pán podobný nepříteli, sehltil Izraele, sehltil všecky paláce jeho, zkazil ohrady jeho, a rozmnožil v lidu Judském zámutek a žalost.'),
(1566599,54,25,2,6,'Mocí zajisté odtrhl jako od zahrady plot svůj, zkazil stánek svůj, v zapomenutí uvedl Hospodin na Sionu slavnost a sobotu, a v prchlivosti hněvu svého zavrhl krále i kněze.'),
(1566600,54,25,2,7,'Zavrhl Pán oltář svůj, v ošklivost vzal svatyni svou, vydal v ruku nepřítele zdi a paláce Sionské; křičeli v domě Hospodinově jako v den slavnosti.'),
(1566601,54,25,2,8,'Uložiltě Hospodin zkaziti zed dcery Sionské, roztáhl šňůru, a neodvrátil ruky své od zhouby; pročež val i zed kvílí, a spolu mdlejí.'),
(1566602,54,25,2,9,'Poraženy jsou na zem brány její, zkazil a polámal závory její; král její i knížata její mezi pohany. Není ani zákona, proroci také její nemívají vidění od Hospodina.'),
(1566603,54,25,2,10,'Starší dcery Sionské usadivše se na zemi, mlčí, posýpají prachem hlavy své, a přepasují se žíněmi panny Jeruzalémské, svěšují k zemi hlavy své.'),
(1566604,54,25,2,11,'Zhynuly od slz oči mé, zkormoutily se vnitřnosti mé, a vykydla se na zem játra má, pro potření dcery lidu mého, když i nemluvňátka a prsí požívající na ulicích města se svírají.'),
(1566605,54,25,2,12,'A říkají matkám svým: Kdež jest obilé a víno? když se jako zraněný svírají po ulicích města, a vypouštějí duše své na klíně matek svých.'),
(1566606,54,25,2,13,'Kohoť za svědka přivedu? Koho připodobním k tobě, ó dcero Jeruzalémská? Koho tobě přirovnám, abych tě potěšil, panno dcero Sionská? Nebo veliké jest jako moře potření tvé. Kdož by tě zhojiti mohl?'),
(1566607,54,25,2,14,'Proroci tvoji předpovídali tobě lživé a ničemné věci, a neodkrývali nepravosti tvé, aby odvrátili zajetí tvé, ale předpovídali tobě těžkosti, oklamání a vyhnání.'),
(1566608,54,25,2,15,'Všickni, kteříž jdou cestou, tleskají nad tebou rukama, diví se a potřásají hlavou svou za tebou, dcero Jeruzalémská, říkajíce: To-li jest to město, o němž říkávali, že jest nejkrásnější a utěšením vší země?'),
(1566609,54,25,2,16,'Všickni nepřátelé tvoji rozdírají na tebe ústa svá, hvízdají a škřipí zuby, říkajíce: Sehlťme ji. Totoť jest jistě ten den, jehož jsme očekávali; jižtě nastal, vidíme.'),
(1566610,54,25,2,17,'Učinil Hospodin to, což byl uložil, splnil řeč svou, kterouž přikazoval ode dnů starodávních, bořil bez lítosti, a obveselil nad tebou nepřítele, povýšil rohu protivníků tvých.'),
(1566611,54,25,2,18,'Vykřikovalo srdce jejich proti Pánu. Ó ty zdi dcery Sionské, vylévej jako potok slzy dnem i nocí, nedávej sobě odpočinutí, aniž se spokojuj zřítelnice oka tvého.'),
(1566612,54,25,2,19,'Vstaň, křič v noci, při počátku bdění, vylévej jako vodu srdce své před oblíčejem Páně; pozdvihuj k němu rukou svých za život dítek svých svírajících se hladem, na rohu všech ulic, a rci:'),
(1566613,54,25,2,20,'Pohleď, Hospodine, a popatř, komu jsi tak kdy učinil? Zdaliž jídají ženy plod svůj, nemluvňátka rozkošná? Zdaliž mordován býti má v svatyni Páně kněz a prorok?'),
(1566614,54,25,2,21,'Leží na zemi po ulicích mladý i starý, panny mé i mládenci moji padli od meče, zmordoval jsi je, a zbil v den prchlivosti své bez lítosti.'),
(1566615,54,25,2,22,'Svolal jsi jako ke dni slavnosti z vůkolí ty, jichž se velice straším, a nebylo v den prchlivosti Hospodinovy, kdo by ušel neb pozůstal. Kteréž jsem na rukou pěstovala a vychovala, ty nepřítel můj do konce zhubil.'),
(1566616,54,25,3,1,'Já jsem muž okoušející trápení od metly rozhněvání Božího.'),
(1566617,54,25,3,2,'Zahnal mne, a uvedl do tmy a ne k světlu.'),
(1566618,54,25,3,3,'Toliko proti mně se postavuje, a obrací ruku svou přes celý den.'),
(1566619,54,25,3,4,'Uvedl sešlost na tělo mé a kůži mou, a polámal kosti mé.'),
(1566620,54,25,3,5,'Zastavěl mne a obklíčil přeodpornou hořkostí.'),
(1566621,54,25,3,6,'Postavil mne v tmavých místech jako ty, kteříž již dávno zemřeli.'),
(1566622,54,25,3,7,'Ohradil mne, abych nevyšel; obtížil ocelivý řetěz můj.'),
(1566623,54,25,3,8,'A jakžkoli volám a křičím, zacpává uši před mou modlitbou.'),
(1566624,54,25,3,9,'Ohradil cesty mé tesaným kamenem, a stezky mé zmátl.'),
(1566625,54,25,3,10,'Jest nedvěd číhající na mne, lev v skrejších.'),
(1566626,54,25,3,11,'Cesty mé stočil, anobrž roztrhal mne, a na to mne přivedl, abych byl pustý.'),
(1566627,54,25,3,12,'Natáhl lučiště své, a vystavil mne za cíl střelám.'),
(1566628,54,25,3,13,'Postřelil ledví má střelami toulu svého.'),
(1566629,54,25,3,14,'Jsem v posměchu se vším lidem svým, a písničkou jejich přes celý den.'),
(1566630,54,25,3,15,'Sytí mne hořkostmi, opojuje mne pelynkem.'),
(1566631,54,25,3,16,'Nadto potřel o kameníčko zuby mé, vrazil mne do popela.'),
(1566632,54,25,3,17,'Tak jsi vzdálil, ó Bože, duši mou od pokoje, až zapomínám na pohodlí,'),
(1566633,54,25,3,18,'A říkám: Zahynulatě síla má i naděje má, kterouž jsem měl v Hospodinu.'),
(1566634,54,25,3,19,'A však duše má rozvažujíc trápení svá a pláč svůj, pelynek a žluč,'),
(1566635,54,25,3,20,'Rozvažujíc to ustavičně, ponižuje se ve mně.'),
(1566636,54,25,3,21,'A přivodě sobě to ku paměti, (naději mám),'),
(1566637,54,25,3,22,'Že veliké jest milosrdenství Hospodinovo, když jsme do konce nevyhynuli. Nepřestávajíť zajisté slitování jeho,'),
(1566638,54,25,3,23,'Ale nová jsou každého jitra; převeliká jest pravda tvá.'),
(1566639,54,25,3,24,'Díl můj jest Hospodin, říká duše má; protož naději mám v něm.'),
(1566640,54,25,3,25,'Dobrý jest Hospodin těm, jenž očekávají na něj, duši té, kteráž ho hledá.'),
(1566641,54,25,3,26,'Dobré jest trpělivě očekávajícímu na spasení Hospodinovo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566642,54,25,3,27,'Dobré jest muži tomu, kterýž by nosil jho od dětinství svého,'),
(1566643,54,25,3,28,'Kterýž by pak byl opuštěn, trpělivě se má v tom, což na něj vloženo,'),
(1566644,54,25,3,29,'Dávaje do prachu ústa svá, až by se ukázala naděje,'),
(1566645,54,25,3,30,'Nastavuje líce tomu, kdož jej bije, a sytě se potupou.'),
(1566646,54,25,3,31,'Neboť nezamítá Pán na věčnost;'),
(1566647,54,25,3,32,'Nýbrž ačkoli zarmucuje, však slitovává se podlé množství milosrdenství svého.'),
(1566648,54,25,3,33,'Netrápíť zajisté z srdce svého, aniž zarmucuje synů lidských.'),
(1566649,54,25,3,34,'Aby kdo potíral nohama svýma všecky vězně v zemi,'),
(1566650,54,25,3,35,'Aby nespravedlivě soudil muže před oblíčejem Nejvyššího,'),
(1566651,54,25,3,36,'Aby převracel člověka v při jeho, Pán nelibuje.'),
(1566652,54,25,3,37,'Kdo jest, ješto když řekl, stalo se něco, a Pán nepřikázal?'),
(1566653,54,25,3,38,'Z úst Nejvyššího zdali nepochází zlé i dobré?'),
(1566654,54,25,3,39,'Proč by tedy sobě stýskal člověk živý, muž nad kázní za hříchy své?'),
(1566655,54,25,3,40,'Zpytujme raději a ohledujme cest našich, a navraťme se až k Hospodinu.'),
(1566656,54,25,3,41,'Pozdvihujme srdcí i rukou svých k Bohu silnému v nebe.'),
(1566657,54,25,3,42,'Myť jsme se zpronevěřili, a zpurní jsme byli, protož ty neodpouštíš.'),
(1566658,54,25,3,43,'Obestřels se hněvem a stiháš nás, morduješ a nešanuješ.'),
(1566659,54,25,3,44,'Obestřels se oblakem, aby nemohla proniknouti k tobě modlitba.'),
(1566660,54,25,3,45,'Za smeti a povrhel položil jsi nás u prostřed národů těchto.'),
(1566661,54,25,3,46,'Rozdírají na nás ústa svá všickni nepřátelé naši.'),
(1566662,54,25,3,47,'Strach a jáma potkala nás, zpuštění a setření.'),
(1566663,54,25,3,48,'Potokové vod tekou z očí mých pro potření dcery lidu mého.'),
(1566664,54,25,3,49,'Oči mé slzí bez přestání, proto že není žádného odtušení,'),
(1566665,54,25,3,50,'Ažby popatřil a shlédl Hospodin s nebe.'),
(1566666,54,25,3,51,'Oči mé rmoutí duši mou pro všecky dcery města mého.'),
(1566667,54,25,3,52,'Loviliť jsou mne ustavičně, jako ptáče, nepřátelé moji bez příčiny.'),
(1566668,54,25,3,53,'Uvrhli do jámy život můj, a přimetali mne kamením.'),
(1566669,54,25,3,54,'Rozvodnily se vody nad hlavou mou, řekl jsem: Jižtě po mně.'),
(1566670,54,25,3,55,'Vzývám jméno tvé, ó Hospodine, z jámy nejhlubší.'),
(1566671,54,25,3,56,'Hlas můj vyslýchával jsi; nezacpávejž ucha svého před vzdycháním mým a voláním mým.'),
(1566672,54,25,3,57,'V ten den, v němž jsem tě vzýval, přicházeje, říkávals: Neboj se.'),
(1566673,54,25,3,58,'Pane, zasazuje se o při duše mé, vysvobozoval jsi život můj.'),
(1566674,54,25,3,59,'Vidíš, ó Hospodine, převrácenost, kteráž se mně děje, dopomoziž mi k spravedlnosti.'),
(1566675,54,25,3,60,'Vidíš všecko vymstívání se jejich, všecky úklady jejich proti mně.'),
(1566676,54,25,3,61,'Slýcháš utrhání jejich, ó Hospodine, i všecky obmysly jejich proti mně,'),
(1566677,54,25,3,62,'Řeči povstávajících proti mně, a přemyšlování jejich proti mně přes celý den.'),
(1566678,54,25,3,63,'Pohleď, jak při sedání jejich i povstání jejich jsem písničkou jejich.'),
(1566679,54,25,3,64,'Dej jim odplatu, Hospodine, podlé díla rukou jejich.'),
(1566680,54,25,3,65,'Dej jim zatvrdilé srdce a prokletí své na ně.'),
(1566681,54,25,3,66,'Stihej v prchlivosti, a vyhlaď je, ať nejsou pod nebem tvým.'),
(1566682,54,25,4,1,'Jak tě zašlo zlato, změnilo se ryzí zlato nejvýbornější, rozmetáno jest kamení svaté sem i tam po všech ulicích.'),
(1566683,54,25,4,2,'Synové Sionští nejdražší, kteříž ceněni býti měli za zlato nejčištší, jakť jsou počteni za nádoby hliněné, dílo rukou hrnčíře!'),
(1566684,54,25,4,3,'An draci vynímajíce prsy, krmí mladé své, dcera pak lidu mého příčinou ukrutníka podobná jest sovám na poušti.'),
(1566685,54,25,4,4,'Jazyk prsí požívajícího přilnul žízní k dásním jeho; děti prosí za chléb, ale není žádného, kdo by lámal jim.'),
(1566686,54,25,4,5,'Ti, kteříž jídali rozkošné krmě, hynou na ulicích; kteříž chováni byli v šarlatě, octli se v hnoji.'),
(1566687,54,25,4,6,'Větší jest trestání dcery lidu mého, než pomsta Sodomy, kteráž podvrácena jest jako v okamžení, aniž trvaly při ní rány.'),
(1566688,54,25,4,7,'Čistší byli Nazareové její než sníh, bělejší než mléko, rděla se těla jejich více než drahé kamení, jako by z zafiru vytesáni byli.'),
(1566689,54,25,4,8,'Ale již vzezření jejich temnější jest než černost, nemohou poznáni býti na ulicích; přischla kůže jejich k kostem jejich, prahne, jest jako dřevo.'),
(1566690,54,25,4,9,'Lépe se stalo těm, jenž zbiti jsou mečem, nežli kteříž mrou hladem, (oni zajisté zhynuli, probodeni byvše), pro nedostatek úrod polních.'),
(1566691,54,25,4,10,'Ruce žen lítostivých vařily syny své, aby jim byli za pokrm v potření dcery lidu mého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566692,54,25,4,11,'Všelijak vypustil Hospodin prchlivost svou, vylévá zůřivost hněvu svého, a zapálil oheň na Sionu, kterýž sežral základy jeho.'),
(1566693,54,25,4,12,'Králové země i všickni obyvatelé okršlku světa nikoli by neuvěřili, by měl byl vjíti protivník a nepřítel do bran Jeruzalémských,'),
(1566694,54,25,4,13,'Pro hříchy proroků jeho a nepravosti kněží jeho, vylévajících u prostřed něho krev spravedlivých.'),
(1566695,54,25,4,14,'Toulali se jako slepí po ulicích, kálejíce se ve krvi, kteréž nemohli se než dotýkati oděvy svými.'),
(1566696,54,25,4,15,'Volali na ně: Ustupujte nečistí, ustupujte, ustupujte, nedotýkejte se. Právěť jsou ustoupili, anobrž sem i tam se rozlezli, až mezi národy říkají: Nebudouť více míti vlastního bydlení.'),
(1566697,54,25,4,16,'Tvář hněvivá Hospodinova rozptýlila je, aniž na ně více popatří; nepřátelé kněží nešanují, starcům milosti nečiní.'),
(1566698,54,25,4,17,'A vždy ještě až do ustání očí svých hledíme o pomoc sobě neprospěšnou, zření majíce k národu, nemohoucímu vysvoboditi.'),
(1566699,54,25,4,18,'Šlakují kroky naše, tak že ani po ulicích našich choditi nemůžeme; přiblížilo se skončení naše, doplnili se dnové naši, přišlo zajisté skončení naše.'),
(1566700,54,25,4,19,'Rychlejší jsou ti, kteříž nás stihají, než orlice nebeské; po horách stihají nás, na poušti zálohy nám zdělali.'),
(1566701,54,25,4,20,'Dýchání chřípí našich, totiž pomazaný Hospodinův, lapen jest v jamách jejich, o němž jsme říkali: V stínu jeho živi budeme mezi národy.'),
(1566702,54,25,4,21,'Raduj se a vesel se, dcero Idumejská, kteráž jsi se usadila v zemi Uz. Takéť k tobě přijde kalich, opiješ se a obnažíš se.'),
(1566703,54,25,4,22,'Ó dcero Sionská, když vykonána bude kázeň nepravosti tvé, nenechá tě déle v zajetí tvém. Ale tvou nepravost, ó dcero Idumejská, trestati bude a odkryje hříchy tvé.'),
(1566704,54,25,5,1,'Rozpomeň se, Hospodine, co se nám děje; popatř a viz pohanění naše.'),
(1566705,54,25,5,2,'Dědictví naše obráceno jest k cizím, domové naši k cizozemcům.'),
(1566706,54,25,5,3,'Sirotci jsme a bez otce, matky naše jsou jako vdovy.'),
(1566707,54,25,5,4,'Vody své za peníze pijeme, dříví naše za záplatu přichází.'),
(1566708,54,25,5,5,'Na hrdle svém protivenství snášíme, pracujeme, nedopouští se nám odpočinouti.'),
(1566709,54,25,5,6,'Egyptským podáváme ruky i Assyrským, abychom nasyceni byli chlebem.'),
(1566710,54,25,5,7,'Otcové naši hřešili, není jich, my pak trestáni po nich neseme.'),
(1566711,54,25,5,8,'Služebníci panují nad námi; není žádného, kdo by vytrhl z ruky jejich.'),
(1566712,54,25,5,9,'S opovážením se života svého hledáme chleba svého, pro strach meče i na poušti.'),
(1566713,54,25,5,10,'Kůže naše jako pec zčernaly od náramného hladu.'),
(1566714,54,25,5,11,'Ženám na Sionu i pannám v městech Judských násilé činí.'),
(1566715,54,25,5,12,'Knížata rukou jejich zvěšena jsou, osoby starých nemají v poctivosti.'),
(1566716,54,25,5,13,'Mládence k žernovu berou, a pacholata pod dřívím klesají.'),
(1566717,54,25,5,14,'Starci sedati v branách přestali a mládenci od zpěvů svých.'),
(1566718,54,25,5,15,'Přestala radost srdce našeho, obrátilo se v kvílení plésání naše.'),
(1566719,54,25,5,16,'Spadla koruna s hlavy naší; běda nám již, že jsme hřešili.'),
(1566720,54,25,5,17,'Protoť jest mdlé srdce naše, pro tyť věci zatměly se oči naše,'),
(1566721,54,25,5,18,'Pro horu Sion, že zpuštěna jest; lišky chodí po ní.'),
(1566722,54,25,5,19,'Ty Hospodine, na věky zůstáváš, a stolice tvá od národu do pronárodu.'),
(1566723,54,25,5,20,'Proč se zapomínáš na věky na nás, a opouštíš nás za tak dlouhé časy?'),
(1566724,54,25,5,21,'Obrať nás, ó Hospodine, k sobě,a obráceni budeme; obnov dny naše, jakž byly za starodávna.'),
(1566725,54,25,5,22,'Nebo zdali všelijak zavržeš nás, a hněvati se budeš na nás velice?'),
(1566726,54,26,1,1,'Stalo se pak třidcátého léta, čtvrtého měsíce, dne pátého, když jsem byl mezi zajatými u řeky Chebar, že otevřína byla nebesa, a viděl jsem vidění Boží.'),
(1566727,54,26,1,2,'Pátého dne téhož měsíce, pátého léta zajetí krále Joachina,'),
(1566728,54,26,1,3,'V pravdě stalo se slovo Hospodinovo k Ezechielovi knězi, synu Buzi, v zemi Kaldejské u řeky Chebar, a byla nad ním ruka Hospodinova.'),
(1566729,54,26,1,4,'I viděl jsem, a aj, vítr tuhý přicházel od půlnoci, a oblak veliký, a oheň plápolající, a okolo něho byl blesk, a z prostředku jeho jako nějaká velmi prudká světlost, z prostředku toho ohně.'),
(1566730,54,26,1,5,'Z prostředku jeho také ukázalo se podobenství čtyř zvířat, jejichž takový byl způsob: Podobenství člověka měli.'),
(1566731,54,26,1,6,'A po čtyřech tvářích jedno každé, a po čtyřech křídlích jedno každé mělo.'),
(1566732,54,26,1,7,'Jejichž nohy nohy přímé, ale zpodek noh jejich jako zpodek nohy telecí, a blyštěly se podobně jako ocel pulerovaná.'),
(1566733,54,26,1,8,'Ruce pak lidské pod křídly jejich, po čtyřech stranách jejich, a tváři jejich i křídla jejich na čtyřech těch stranách.'),
(1566734,54,26,1,9,'Spojena byla křídla jejich jednoho s druhým. Neobracela se, když šla; jedno každé přímo na svou stranu šlo.'),
(1566735,54,26,1,10,'Podobenství pak tváří jejich s předu tvář lidská, a tvář lvová po pravé straně každého z nich; tvář pak volovou po levé straně všech čtvero, též tvář orličí s zadu mělo všech čtvero z nich.'),
(1566736,54,26,1,11,'A tváři jejich i křídla jejich pozdvižena byla zhůru. Každé zvíře dvě křídla pojilo s křídly dvěma druhého, dvěma pak přikrývala těla svá.'),
(1566737,54,26,1,12,'A každé přímo na svou stranu šlo. Kamkoli ukazoval duch, aby šla, tam šla, neuchylovala se, když chodila.'),
(1566738,54,26,1,13,'Podobnost také těch zvířat na pohledění byla jako uhlí řeřavého, na pohledění jako pochodně. Kterýžto oheň ustavičně chodil mezi zvířaty, a ten oheň měl blesk, a z téhož ohně vycházelo blýskání.'),
(1566739,54,26,1,14,'Také ta zvířata běhala, a navracovala se jako prudké blýskání.'),
(1566740,54,26,1,15,'A když jsem hleděl na ta zvířata, a aj, kolo jedno bylo na zemi při zvířatech u čtyř tváří jednoho každého z nich.'),
(1566741,54,26,1,16,'Na pohledění byla kola, a udělání jich jako barva tarsis, a podobnost jednostejnou měla všecka ta kola, a byla na pohledění i udělání jejich, jako by bylo kolo u prostřed kola.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566742,54,26,1,17,'Na čtyři strany své jíti majíce, chodila, a neuchylovala se, když šla.'),
(1566743,54,26,1,18,'A loukoti své, i vysokost měla, že hrůza z nich šla, a šínové jejich vůkol všech čtyř kol plní byli očí.'),
(1566744,54,26,1,19,'Když pak chodila zvířata, chodila kola podlé nich, a když se vznášela zvířata vzhůru od země, vznášela se i kola.'),
(1566745,54,26,1,20,'Kdekoli chtěl Duch, aby šla, tam šla; kde Duch chtěl jíti, i kola vznášela se naproti nim, nebo duch zvířat byl v kolách.'),
(1566746,54,26,1,21,'Když ona šla, šla, a když ona stála, stála, a když se vznášela od země, vznášela se také kola s nimi, nebo duch zvířat byl v kolách.'),
(1566747,54,26,1,22,'Podobenství pak oblohy bylo nad hlavami zvířat jako podobenství křištálu roztaženého nad hlavami jejich svrchu.'),
(1566748,54,26,1,23,'A pod oblohou křídla jejich pozdvižená byla, jedno připojené k druhému. Každé mělo dvě, jimiž se přikrývalo, každé, pravím, mělo dvě, jimiž přikrývalo tělo své.'),
(1566749,54,26,1,24,'I slyšel jsem zvuk křídel jejich jako zvuk vod mnohých, jako zvuk Všemohoucího, když chodila, zvuk hluku jako zvuk vojska. Když pak stála, spustila křídla svá.'),
(1566750,54,26,1,25,'Byl také zvuk svrchu nad oblohou, kteráž byla nad hlavou jejich, když stála a spustila křídla svá.'),
(1566751,54,26,1,26,'Svrchu pak na obloze, kteráž byla nad hlavou jejich, bylo podobenství trůnu, na pohledění jako kámen zafirový, a nad podobenstvím trůnu na něm svrchu, na pohledění jako tvárnost člověka.'),
(1566752,54,26,1,27,'I viděl jsem na pohledění jako velmi prudkou světlost, a u vnitřku jejím vůkol na pohledění jako oheň, od bedr jeho vzhůru; od bedr pak jeho dolů viděl jsem na pohledění jako oheň, a blesk vůkol něho.'),
(1566753,54,26,1,28,'Na pohledění jako duha, kteráž bývá na oblace v čas deště, takový na pohledění byl blesk vůkol. To bylo vidění podobenství slávy Hospodinovy. Kteréžto viděv, padl jsem na tvář svou, a slyšel jsem hlas mluvícího.'),
(1566754,54,26,2,1,'Kterýž řekl ke mně: Synu člověčí, postav se na nohy své, ať mluvím s tebou.'),
(1566755,54,26,2,2,'I vstoupil do mne duch, když promluvil ke mně, a postavil mne na nohy mé, a slyšel jsem, an mluví ke mně.'),
(1566756,54,26,2,3,'Kterýž řekl mi: Synu člověčí, já tě posílám k synům Izraelským, k národům zpurným, kteříž zpurně se postavovali proti mně; oni i otcové jejich zpronevěřovali se mi, až právě do tohoto dne.'),
(1566757,54,26,2,4,'K těch, pravím, synům nestydaté tváři a zatvrdilého srdce já posílám tě, a díš k nim: Takto praví Panovník Hospodin,'),
(1566758,54,26,2,5,'Již oni slyšte neb nechte: Že dům zpurný jsou. Ať vědí, že prorok byl u prostřed nich.'),
(1566759,54,26,2,6,'Ty pak synu člověčí, neboj se jich, aniž se boj slov jejich, že zpurní a jako trní jsou proti tobě, a že mezi štíry bydlíš. Slov jejich neboj se, a tváři jejich se nestrachuj, proto že dům zpurný jsou.'),
(1566760,54,26,2,7,'Ale mluv slova má k nim, již oni slyšte neb nechte: Že zpurní jsou.'),
(1566761,54,26,2,8,'Ty pak synu člověčí, slyš, co já pravím tobě: Nebuď zpurný jako ten dům zpurný. Otevři ústa svá, a sněz, co já tobě dám.'),
(1566762,54,26,2,9,'I viděl jsem, a aj, ruka vztažena byla ke mně, a aj, v ní svinutá kniha.'),
(1566763,54,26,2,10,'Kteroužto rozvinul přede mnou, a byla popsaná s předu i z zadu, a bylo v ní psáno naříkání, kvílení a běda.'),
(1566764,54,26,3,1,'Tedy řekl mi: Synu člověčí, což před tebou jest, sněz, sněz knihu tuto, a jdi, mluv k domu Izraelskému.'),
(1566765,54,26,3,2,'I otevřel jsem ústa svá, a dal mi snísti knihu tu,'),
(1566766,54,26,3,3,'Řka ke mně: Synu člověčí, nakrm břicho své, a střeva svá naplň knihou touto, kteroužť dávám. I snědl jsem, a byla v ústech mých jako med sladká.'),
(1566767,54,26,3,4,'Za tím řekl mi: Synu člověčí, jdiž k domu Izraelskému, a mluv k nim slovy mými.'),
(1566768,54,26,3,5,'Nebo nebudeš poslán k lidu hluboké řeči a nesnadného jazyka, ale k domu Izraelskému.'),
(1566769,54,26,3,6,'Ne k národům mnohým hluboké řeči a nesnadného jazyka, jejichž bys slovům nerozuměl, ješto, kdybych tě k nim poslal, uposlechli by tebe.'),
(1566770,54,26,3,7,'Ale dům Izraelský nebudou tě chtíti poslouchati, poněvadž nechtí poslouchati mne; nebo všecken dům Izraelský jest tvrdočelný a zatvrdilého srdce.'),
(1566771,54,26,3,8,'Ale učinil jsem tvář tvou tvrdou proti tváři jejich, a čelo tvé tvrdé proti čelu jejich.'),
(1566772,54,26,3,9,'Jako kámen přetvrdý, pevnější než skálu učinil jsem čelo tvé; nebojž se jich, aniž se strachuj tváři jejich, proto že dům zpurný jsou.'),
(1566773,54,26,3,10,'I řekl ke mně: Synu člověčí, všecka slova má, kterážť mluviti budu, přijmi v srdce své, a ušima svýma slyš.'),
(1566774,54,26,3,11,'A jdi k zajatým, k synům lidu svého, a mluv k nim, a rci jim: Takto praví Panovník Hospodin, již oni slyšte neb nechte.'),
(1566775,54,26,3,12,'Tehdy odnesl mne Duch, a slyšel jsem za sebou hlas hřmotu velikého: Požehnaná sláva Hospodinova z místa svého.'),
(1566776,54,26,3,13,'A hlas křídel těch zvířat, kteráž se vespolek dotýkala, a hlas kol naproti nim, a hlas hřmotu velikého.'),
(1566777,54,26,3,14,'Duch pak odnesl mne, a vzal mne, a odšel jsem truchliv, v hněvě ducha svého, ale ruka Hospodinova nade mnou silnější byla.'),
(1566778,54,26,3,15,'I přišel jsem k zajatým do Telabib, bydlícím při řece Chebar, a seděl jsem, kdež oni bydlili. Seděl jsem, pravím, sedm dní u prostřed nich s užasnutím.'),
(1566779,54,26,3,16,'I stalo se po dokonání sedmi dnů, že se stalo slovo Hospodinovo ke mně, řkoucí:'),
(1566780,54,26,3,17,'Synu člověčí, strážným jsem tě postavil nad domem Izraelským, abys slyše slovo z úst mých, napomínal jich ode mne.'),
(1566781,54,26,3,18,'Když bych já řekl bezbožnému: Smrtí umřeš, a nenapomenul bys ho, ani nemluvil, abys ho odvedl od cesty jeho bezbožné, proto abys ho při životu zachoval: ten bezbožný pro nepravost svou umře, ale krve jeho z ruky tvé vyhledám.'),
(1566782,54,26,3,19,'Paklibys ty napomenul bezbožného, a neodvrátil by se od bezbožnosti své, a od cesty své bezbožné, onť pro nepravost svou umře, ale ty duši svou vysvobodíš.'),
(1566783,54,26,3,20,'Odvrátil-li by se pak spravedlivý od spravedlnosti své, a činil by nepravost, a já bych položil urážku před něj, a tak by umřel, ty pak bys ho nenapomenul: pro hříchť svůj umře, aniž na pamět přijde která spravedlnost jeho, kterouž činil, ale krve jeho z ruky tvé vyhledám.'),
(1566784,54,26,3,21,'Pakli bys ty napomenul spravedlivého, aby nehřešil spravedlivý, a on by nehřešil, jistě že bude živ; nebo napomenut byl. Ty také duši svou vysvobodíš.'),
(1566785,54,26,3,22,'I byla tam nade mnou ruka Hospodinova, kterýžto řekl mi: Vstaň, jdi do tohoto údolí, a tam mluviti budu s tebou.'),
(1566786,54,26,3,23,'A tak vstav, šel jsem do toho údolí, a aj, sláva Hospodinova stála tam, jako sláva, kterouž jsem viděl u řeky Chebar. I padl jsem na tvář svou.'),
(1566787,54,26,3,24,'Tehdy vstoupil do mne Duch, a postaviv mne na nohy, mluvil ke mně, a řekl mi: Jdiž, zavři se v domě svém.'),
(1566788,54,26,3,25,'Nebo na tě, synu člověčí, aj, dadí na tě provazy, a sváží tě jimi, a nebudeš moci vyjíti mezi ně.'),
(1566789,54,26,3,26,'A já učiním, aby jazyk tvůj přilnul k dásním tvým, a abys oněměl, a nebyl jim mužem domlouvajícím, protože dům zpurný jsou.'),
(1566790,54,26,3,27,'Ale když mluviti budu s tebou, otevru ústa tvá, a díš jim: Takto praví Panovník Hospodin: Kdo slyšeti chce, nechť slyší, a kdo nechce, nechť nechá, že dům zpurný jsou.'),
(1566791,54,26,4,1,'Ty pak synu člověčí, vezmi sobě cihlu, a polože ji před sebe, vyrej na ní město Jeruzalém.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566792,54,26,4,2,'A postav na ní obležení, a vzdělaje na ní šance, vysyp na ní násyp, a polož na ní vojska, a postav na ní berany válečné vůkol.'),
(1566793,54,26,4,3,'Potom vezmi sobě pánev železnou, a polož ji místo zdi železné, mezi tebou a mezi městem, a zatvrď tvář svou proti němu, ať jest obleženo, a oblehneš je. Toť bude znamením domu Izraelskému.'),
(1566794,54,26,4,4,'Ty pak lehni na levý bok svůj, a vlož na něj nepravost domu Izraelského. Podlé počtu dnů, v němž ležeti budeš na něm, poneseš nepravost jejich.'),
(1566795,54,26,4,5,'A já dávám tobě léta nepravosti jejich v počtu dnů, tři sta a devadesáte dnů, v nichž poneseš nepravost domu Izraelského.'),
(1566796,54,26,4,6,'Když je pak vyplníš, budeš ležeti na pravém boku podruhé, a poneseš nepravost domu Judova čtyřidceti dnů. Den za rok, den za rok dávám tobě.'),
(1566797,54,26,4,7,'K obležení, pravím, Jeruzaléma zatvrď tvář svou, ohrna ruku svou, a prorokuje proti němu.'),
(1566798,54,26,4,8,'A aj, dávám na tě provazy, abys se neobracel z boku jednoho na druhý, dokudž nevyplníš dnů obležení svého.'),
(1566799,54,26,4,9,'Protož ty vezmi sobě pšenice a ječmene, též bobu, šočovice, i prosa, a špaldy, a dej to do jedné nádoby, abys sobě nastrojil z toho pokrmu podlé počtu dnů, v nichž ležeti budeš na boku svém. Za tři sta a devadesáte dnů jísti jej budeš.'),
(1566800,54,26,4,10,'Pokrmu pak tvého, kterýž jísti budeš, váha bude dvadceti lotů na den. Od času až do času jísti jej budeš.'),
(1566801,54,26,4,11,'Vodu také na míru píti budeš, šestý díl hin; od času do času píti budeš.'),
(1566802,54,26,4,12,'Podpopelný pak chléb ječný, kterýž jísti budeš, ten lejny nečistoty lidské pec před očima jejich.'),
(1566803,54,26,4,13,'I řekl Hospodin: Tak budou jísti synové Izraelští chléb svůj nečistý pro pohany, kteréž tam shromáždím.'),
(1566804,54,26,4,14,'Tedy řekl jsem: Ach, Panovníče Hospodine, aj, duše má není poškvrněna mrchami, a udáveného nejedl jsem od dětinství svého až podnes, aniž vešlo v ústa má maso ohavné.'),
(1566805,54,26,4,15,'Kterýž řekl mi: Aj, dávámť kravince místo lejn lidských, abys sobě jimi napekl chleba.'),
(1566806,54,26,4,16,'Za tím řekl mi: Synu člověčí, aj, já zlámi hůl chleba v Jeruzalémě, tak že jísti budou chléb na váhu, a to s zámutkem, a vodu na míru píti, a to s předěšením,'),
(1566807,54,26,4,17,'Aby nedostatek majíce v chlebě a v vodě, děsili se jeden každý z nich, a svadli pro nepravost svou.'),
(1566808,54,26,5,1,'Potom ty synu člověčí, vezmi sobě nůž ostrý, totiž břitvu holičů, vezmi jej sobě, a ohol ním hlavu i bradu svou. Potom vezma sobě váhu, rozděl to.'),
(1566809,54,26,5,2,'Třetinu ohněm spal u prostřed města, když se vyplní dnové obležení; zatím vezma druhou třetinu, posekej mečem okolo něho; ostatní pak třetinu rozptyl u vítr. Nebo mečem dobytým budu je stihati.'),
(1566810,54,26,5,3,'A však odejmi odtud něco málo, a zavaž do křídel svých.'),
(1566811,54,26,5,4,'A i z těch ještě vezma, uvrz je do prostřed ohně, a spal je ohněm, odkudž vyjde oheň na všecken dům Izraelský.'),
(1566812,54,26,5,5,'Takto praví Panovník Hospodin: Tento Jeruzalém, kterýž jsem postavil u prostřed pohanů, a vůkol otočil krajinami,'),
(1566813,54,26,5,6,'Změnil soudy mé v bezbožnost více než pohané, a ustanovení má více než jiné země, kteréž jsou vůkol něho; nebo soudy mými pohrdli, a v ustanoveních mých nechodili.'),
(1566814,54,26,5,7,'Protož takto praví Panovník Hospodin: Proto že mnohem více než pohané, kteříž jsou vůkol vás, v ustanoveních mých nechodili jste, a soudů mých nečinili jste, nýbrž ani tak jako pohané, kteříž jsou vůkol vás, soudů nekonali jste:'),
(1566815,54,26,5,8,'Protož takto praví Panovník Hospodin: Aj, já na tebe, aj já, a vykonám u prostřed tebe soudy před očima pohanů.'),
(1566816,54,26,5,9,'Nebo učiním při tobě to, čehož jsem prv neučinil, a čehož podobně neučiním více pro všecky ohavnosti tvé,'),
(1566817,54,26,5,10,'Tak že otcové jísti budou syny u prostřed tebe, a synové jísti budou otce své, a vykonám proti tobě soudy, a rozptýlím všecky ostatky tvé na všecky strany.'),
(1566818,54,26,5,11,'Protož živť jsem já, praví Panovník Hospodin, že poněvadž jsi ty svatyně mé poškvrnil všelikými mrzkostmi svými, a všelikými ohavnostmi svými, i já také zlehčím tebe, a neodpustíť oko mé, a nikoli se neslituji.'),
(1566819,54,26,5,12,'Třetina tebe morem zemře a hladem zhyne u prostřed tebe, a třetina druhá mečem padne vůkol tebe, ostatní pak třetinu na všecky stany rozptýlím, a mečem dobytým stihati je budu.'),
(1566820,54,26,5,13,'A tak do konce vylit bude hněv můj, a dotru prchlivostí svou na ně, i potěším se. I zvědíť, že já Hospodin mluvil jsem v horlivosti své, když vykonám prchlivost svou na nich,'),
(1566821,54,26,5,14,'A obrátím tě v poušť, a dám tě v útržku mezi národy, kteříž jsou vůkol tebe, před očima každého tudy jdoucího.'),
(1566822,54,26,5,15,'A tak budeš k útržce, posměchu, k hroznému příkladu a k užasnutí národům, kteříž jsou vůkol tebe, tehdáž když vykonám proti tobě soudy v hněvě a v prchlivosti a v žehrání zůřivém. Já Hospodin mluvil jsem.'),
(1566823,54,26,5,16,'Tehdáš když vystřelím jízlivé střely hladu k záhubě vaší, kteréž vystřelím, abych vás vyhubil, a hlad shromáždě proti vám, zlámi vám hůl chleba.'),
(1566824,54,26,5,17,'Pošli zajisté na vás hlad a zvěř lítou, kteráž tě na sirobu přivede; i mor a krev přijde na tebe, když uvedu na tě meč. Já Hospodin mluvil jsem.'),
(1566825,54,26,6,1,'I stalo se ke mně slovo Hospodinovo, řkoucí:'),
(1566826,54,26,6,2,'Synu člověčí, obrať tvář svou proti horám Izraelským, a prorokuj proti nim,'),
(1566827,54,26,6,3,'A rci: Hory Izraelské, slyšte slovo Panovníka Hospodina: Takto praví Panovník Hospodin horám a pahrbkům, prudkým potokům a údolím: Aj, já, já uvedu na vás meč, a zkazím výsosti vaše.'),
(1566828,54,26,6,4,'A tak zpustnou oltářové vaši, a ztroskotáni budou sluneční obrazové vaši, a rozmeci zbité vaše před ukydanými bohy vašimi.'),
(1566829,54,26,6,5,'Povrhu také mrtvá těla synů Izraelských před ukydanými bohy jejich, a rozptýlím kosti vaše okolo oltářů vašich.'),
(1566830,54,26,6,6,'Kdekoli bydliti budete, města zpuštěna budou, a výsosti zpustnou. Pročež popléněni budou a zpustnou i oltářové vaši, potroskotáni budou a přestanou ukydaní bohové vaši, a sluneční obrazové vaši zpodtínáni, a tak vyhlazena budou díla vaše.'),
(1566831,54,26,6,7,'I padnou zbití u prostřed vás, a zvíte, že já jsem Hospodin.'),
(1566832,54,26,6,8,'A pozůstavím některé z vás, kteříž by ušli meče, mezi pohany, když rozptýleni budete do zemí.'),
(1566833,54,26,6,9,'I budou se rozpomínati na mne, kteříž z vás zachováni budou mezi národy, mezi něž budou zajati, že jsem kormoucen byl srdcem jejich smilným, kteréž odstoupilo ode mne, a očima jejich, kteréž smilníce, chodily za ukydanými bohy svými, a tak sami se býti hodné ošklivosti seznají pro nešlechetnosti, kteréž páchali ve všech ohavnostech svých.'),
(1566834,54,26,6,10,'A zvědí, že já jsem Hospodin, a že jsem ne nadarmo mluvil, že na ně uvedu zlé toto.'),
(1566835,54,26,6,11,'Takto praví Panovník Hospodin: Tleskni rukou svou, a dupni nohou svou, a rci: Nastojte na dům Izraelský, že pro všecky ohavnosti nejhorší mečem, hladem a morem padnouti mají.'),
(1566836,54,26,6,12,'Ten, kdož daleko bude, morem umře, a kdo blízko, mečem padne, ostatní pak a obležený hladem umře, a tak docela vyleji prchlivost svou na ně.'),
(1566837,54,26,6,13,'A zvíte, že já jsem Hospodin, když budou zbití jejich u prostřed ukydaných bohů jejich vůkol oltářů jejich, na všelikém pahrbku vysokém, na všech vrších hor, a pod všelikým dřevem zeleným, i pod všelikým dubem hustým, na kterémkoli místě obětovávali vůni libou všelikým ukydaným bohům svým.'),
(1566838,54,26,6,14,'Nebo vztáhnu ruku svou na ně, a učiním zemi tuto zpustlou, zpustlejší než poušť Diblat, po všech obydlích jejich. I zvědí, že já jsem Hospodin.'),
(1566839,54,26,7,1,'Potom stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1566840,54,26,7,2,'Slyš, synu člověčí: Takto praví Panovník Hospodin o zemi Izraelské: Ach, skončení, přišlo skončení její na čtyři strany země.'),
(1566841,54,26,7,3,'Jižtě skončení nastalo tobě; nebo vypustím hněv svůj na tě, a budu tě souditi podlé cest tvých, a uvrhu na tě všecky ohavnosti tvé.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566842,54,26,7,4,'Neodpustí zajisté oko mé tobě, aniž se slituji, ale cesty tvé na tebe uvrhu, a ohavnosti tvé u prostřed tebe budou. I zvíte, že já jsem Hospodin.'),
(1566843,54,26,7,5,'Takto praví Panovník Hospodin: Bída jedna, aj hle, přichází bída.'),
(1566844,54,26,7,6,'Skončení přichází, přichází skončení, procítil na tě, aj, přicházíť.'),
(1566845,54,26,7,7,'Přicházíť to jitro na tebe, obyvateli země, přicházíť ten čas, přibližuje se ten den hřmotu, a ne hlas rozléhající se po horách.'),
(1566846,54,26,7,8,'Již tudíž vyliji prchlivost svou na tě, a docela vypustím hněv svůj na tebe, a budu tě souditi podlé cest tvých, a uvrhu na tě všecky ohavnosti tvé.'),
(1566847,54,26,7,9,'Neodpustíť zajisté oko mé, aniž se slituji, ale podlé cest tvých zaplatím tobě, a budou ohavnosti tvé u prostřed tebe. A tak zvíte, že já jsem Hospodin, ten, kterýž biji.'),
(1566848,54,26,7,10,'Aj, teď jest ten den, aj, přicházeje,přišlo to jitro, zkvetl prut, vypučila se z něho pýcha,'),
(1566849,54,26,7,11,'Ukrutnost vzrostla v prut bezbožnosti. Nezůstaneť z nich nic, ani z množství jejich, ani z hluku jejich, aniž bude naříkáno nad nimi.'),
(1566850,54,26,7,12,'Přicházíť ten čas, blízko jest ten den. Kdo koupí, nebude se veseliti, a kdo prodá, nic toho nebude litovati; nebo prchlivost přijde na všecko množství její.'),
(1566851,54,26,7,13,'Ten zajisté, kdož prodal, k věci prodané nepůjde nazpět, by pak ještě byl mezi živými život jejich, poněvadž vidění na všecko množství její nenavrátí se, a žádný v nepravosti života svého nezmocní se.'),
(1566852,54,26,7,14,'Troubiti budou v troubu, a připraví všecko, ale nebude žádného, kdo by šel k boji; nebo prchlivost má oboří se na všecko množství její.'),
(1566853,54,26,7,15,'Meč bude vně, mor pak a hlad doma; kdo bude na poli, mečem zabit bude, toho pak, kdož bude v městě, hlad a mor zahubí.'),
(1566854,54,26,7,16,'Kteříž pak z nich utekou, ti na horách, jako holubice v údolí, všickni lkáti budou, jeden každý pro nepravost svou.'),
(1566855,54,26,7,17,'Všeliké ruce klesnou, a všeliká kolena rozplynou se jako voda.'),
(1566856,54,26,7,18,'I přepáší se žíněmi, a hrůza je přikryje, a na všeliké tváři bude stud, a na všech hlavách jejich lysina.'),
(1566857,54,26,7,19,'Stříbro své po ulicích rozházejí, a zlato jejich bude jako nečistota; stříbro jejich a zlato jejich nebude jich moci vysvoboditi v den prchlivosti Hospodinovy. Nenasytí se, a střev svých nenaplní, proto že nepravost jejich jest jim k urážce,'),
(1566858,54,26,7,20,'A že v slávě okrasy své, v té, kterouž k důstojnosti postavil Bůh, obrazu ohavností svých a mrzkostí svých nadělali. Protož obrátil jsem jim ji v nečistotu.'),
(1566859,54,26,7,21,'Nebo vydám ji v ruku cizozemců k rozchvátání, a bezbožným na zemi za loupež, kteříž poškvrní jí.'),
(1566860,54,26,7,22,'Odvrátím též tvář svou od nich, i poškvrní svatyně mé, a vejdou do ní, boříce a poškvrňujíce jí.'),
(1566861,54,26,7,23,'Udělej řetěz, nebo země plná jest soudů ukrutných, a město plné jest nátisku.'),
(1566862,54,26,7,24,'Protož přivedu nejhorší z pohanů, aby dědičně vládli domy jejich; i učiním přítrž pýše silných, a poškvrněny budou, kteříž jich posvěcují.'),
(1566863,54,26,7,25,'Zkažení přišlo, protož hledati budou pokoje, ale žádného nebude.'),
(1566864,54,26,7,26,'Bída za bídou přijde, a novina bude za novinou, i budou hledati vidění od proroka, ale zákon zahyne od kněze, a rada od starců.'),
(1566865,54,26,7,27,'Král ustavičně kvíliti bude, a kníže obleče se v smutek, a ruce lidu v zemi předěšeny budou. Podlé cesty jejich učiním jim, a podlé soudů jejich souditi je budu. I zvědí, že já jsem Hospodin.'),
(1566866,54,26,8,1,'I stalo se léta šestého, v pátý den šestého měsíce, že jsem seděl v domě svém, a starší Judští seděli přede mnou. I připadla na mne tu ruka Panovníka Hospodina.'),
(1566867,54,26,8,2,'A viděl jsem, a aj, podobenství na pohledění jako oheň. Od bedr jeho dolů oheň, od bedr pak jeho vzhůru na pohledění jako blesk, na pohledění jako nějaká velmi prudká světlost.'),
(1566868,54,26,8,3,'Tedy vztáh podobenství ruky, vzal mne za kštici hlavy mé, a vyzdvihl mne Duch mezi nebe a mezi zemi, a uvedl mne do Jeruzaléma u viděních Božích, k vratům brány vnitřní, kteráž patří na půlnoci, kdež byla stolice modly k horlivosti a k zůřivosti popouzející.'),
(1566869,54,26,8,4,'A aj, sláva Boha Izraelského byla tam na pohledění jako ta, kterouž jsem viděl v údolí.'),
(1566870,54,26,8,5,'I řekl mi: Synu člověčí, pozdvihni nyní očí svých k cestě na půlnoci. Tedy pozdvihl jsem oči svých k cestě na půlnoci, a aj, na půlnoci u brány oltářové ta modla horlení, právě kudyž se vchází.'),
(1566871,54,26,8,6,'V tom řekl mi: Synu člověčí, vidíš-liž ty, co tito činí, ohavnosti tak veliké, kteréž činí dům Izraelský tuto, tak že se vzdáliti musím od svatyně své? Ale obrátě se, uzříš ještě větší ohavnosti.'),
(1566872,54,26,8,7,'I přivedl mne ke dveřům síně, kdež jsem uzřel, a aj, díra jedna byla v stěně.'),
(1566873,54,26,8,8,'A řekl mi: Synu člověčí, kopej medle tu stěnu. I kopal jsem stěnu, a aj, dvéře jedny.'),
(1566874,54,26,8,9,'Tedy řekl mi: Vejdi, a viz ohavnosti tyto nejhorší, kteréž oni činí zde.'),
(1566875,54,26,8,10,'Protož všed, uzřel jsem, a aj, všeliké podobenství zeměplazů a hovad ohyzdných, i všech ukydaných bohů domu Izraelského vyryto bylo na stěně vůkol a vůkol.'),
(1566876,54,26,8,11,'A sedmdesáte mužů z starších domu Izraelského, s Jazaniášem synem Safanovým, stojícím u prostřed nich, stáli před nimi, maje každý kadidlnici svou v ruce své, tak že hustý oblak kadění vzhůru vstupoval.'),
(1566877,54,26,8,12,'I řekl mi: Viděl-lis, synu člověčí, co starší domu Izraelského činí ve tmě, jeden každý v pokojích svých malovaných? Nebo říkají: Nikoli na nás nepatří Hospodin, opustil Hospodin zemi.'),
(1566878,54,26,8,13,'Dále mi řekl: Obrátě se, uzříš ještě větší ohavnosti, kteréž oni činí.'),
(1566879,54,26,8,14,'I přivedl mne k vratům brány domu Hospodinova, kteráž jest na půlnoci, a aj, ženy seděly tam, plačíce Tammuze.'),
(1566880,54,26,8,15,'I řekl mi: Viděl-lis, synu člověčí? Obrátě se, uzříš ještě větší ohavnosti nad tyto.'),
(1566881,54,26,8,16,'Tedy uvedl mne do síně domu Hospodinova vnitřní, a aj, u vrat chrámu Hospodinova, mezi síňcí a oltářem bylo okolo pětmecítma mužů, jejichž záda byla k chrámu Hospodinovu, tváři pak jejich k východu, kteříž klaněli se proti východu slunce.'),
(1566882,54,26,8,17,'I řekl mi: Viděl-lis, synu člověčí? Zdali lehká věc jest domu Judovu, aby činili ohavnosti tyto, kteréž činí zde? Nebo naplnivše zemi nátiskem,obrátili se, aby mne popouzeli, a aj, přičinějí ratolest vinnou k nosům svým.'),
(1566883,54,26,8,18,'Protož i já také učiním podlé prchlivosti; neslitujeť se oko mé, aniž se smiluji. I budou volati v uši mé hlasem velikým, a nevyslyším jich.'),
(1566884,54,26,9,1,'Potom zavolal hlasem velikým, tak že jsem slyšel, řka: Přistupte hejtmané k tomuto městu, a jeden každý s zbrojí svou hubící v ruce své.'),
(1566885,54,26,9,2,'A aj, šest mužů přišlo cestou k bráně hořejší, kteráž patří na půlnoci, maje každý zbroj svou rozrážející v ruce své. Muž pak jeden byl u prostřed nich, oděný rouchem lněným, a kalamář písařský při bedrách jeho; a přišedše, stáli u oltáře měděného.'),
(1566886,54,26,9,3,'Sláva pak Boha Izraelského sstoupila byla s cherubína, na kterémž byla, k prahu domu, a zvolala na muže toho oděného rouchem lněným, při jehož bedrách byl kalamář písařský.'),
(1566887,54,26,9,4,'I řekl jemu Hospodin: Přejdi prostředkem města, prostředkem Jeruzaléma, a znamenej znamením na čelích muže ty, kteříž vzdychají a naříkají nade všemi ohavnostmi dějícími se u prostřed něho.'),
(1566888,54,26,9,5,'Oněmno pak řekl tak, že jsem slyšel: Projděte skrze město za ním, a bíte; neodpouštějž oko vaše, aniž se slitovávejte.'),
(1566889,54,26,9,6,'Starce, mládence i pannu, maličké i ženy mordujte do vyhubení, ale ke všelikému muži, na němž by bylo znamení, nepřistupujte, a od svatyně mé počněte. Takž začali od mužů těch starších, kteříž byli před chrámem.'),
(1566890,54,26,9,7,'(Nebo jim byl řekl: Poškvrňte domu, a naplňte síně zbitými. Jdětež.) A vyšedše, bili v městě.'),
(1566891,54,26,9,8,'I stalo se, když je bili, a já pozůstal, že jsem padl na tvář svou, a zvolal jsem, řka: Ach, Panovníče Hospodine, zdaliž zahubíš všecken ostatek Izraelský, vylévaje prchlivost svou na Jeruzalém?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566892,54,26,9,9,'I řekl mi: Nepravost domu Izraelského a Judského veliká jest velmi velice, a naplněna jest země mordy, a město plné jest převrácenců. Nebo říkali: Opustil Hospodin zemi tuto, a Hospodin nikoli nevidí nás.'),
(1566893,54,26,9,10,'Protož já také cestu jejich na hlavu jejich obrátím; neodpustí oko mé, aniž se slituji.'),
(1566894,54,26,9,11,'A aj, muž oděný rouchem lněným, při jehož bedrách byl kalamář, oznámil to, řka: Učinil jsem, jakž jsi mi rozkázal.'),
(1566895,54,26,10,1,'I viděl jsem, a aj, na obloze, kteráž byla nad hlavou cherubínů, jako kámen zafirový na pohledění, jako podobenství trůnu se ukázalo nad nimi.'),
(1566896,54,26,10,2,'Tedy promluviv k muži tomu oděnému rouchem lněným, řekl: Vejdi do prostřed kol pod cherubíny, a naplň hrsti své uhlím řeřavým z prostředku cherubínů, a roztrus po městě. Kterýžto všel před očima mýma.'),
(1566897,54,26,10,3,'(Cherubínové pak stáli po pravé straně domu, když vcházel muž ten, a oblak hustý naplnil síň vnitřní.'),
(1566898,54,26,10,4,'Nebo když se byla zdvihla sláva Hospodinova s cherubínů k prahu domu, tedy naplněn byl dům tím hustým oblakem, a síň naplněna byla bleskem slávy Hospodinovy.'),
(1566899,54,26,10,5,'Zvuk také křídel cherubínů slyšán byl až k té síni zevnitřní jako hlas Boha silného, všemohoucího, když mluví.)'),
(1566900,54,26,10,6,'I stalo se, když přikázal muži tomu oděnému rouchem lněným, řka: Vezmi ohně z prostředku kol, z prostředku cherubínů, že všel a postavil se podlé kol.'),
(1566901,54,26,10,7,'Tedy vztáhl cherubín jeden ruku svou z prostředku cherubínů k ohni tomu, kterýž byl u prostřed cherubínů, a vzav, dal do hrsti toho oděného rouchem lněným. Kterýžto vzal a vyšel.'),
(1566902,54,26,10,8,'Nebo ukazovalo se na cherubíních podobenství ruky lidské pod křídly jejich.'),
(1566903,54,26,10,9,'I viděl jsem, a aj, čtyři kola podlé cherubínů, jedno kolo podlé jednoho každého cherubína, podobenství pak kol jako barva kamene tarsis.'),
(1566904,54,26,10,10,'A na pohledění měla podobnost jednostejnou ta kola, jako by bylo kolo u prostřed kola.'),
(1566905,54,26,10,11,'Když chodili, na čtyři strany jejich chodili. Neuchylovali se, když šli, ale k tomu místu, kamž se obracel vůdce, za ním šli. Neuchylovali se, když šli.'),
(1566906,54,26,10,12,'Všecko také tělo jejich i hřbetové jejich, i ruce jejich, i křídla jejich, též i kola plná byla očí vůkol jich samých čtyř i kol jejich.'),
(1566907,54,26,10,13,'Kola pak ta nazval okršlkem, jakž slyšely uši mé.'),
(1566908,54,26,10,14,'Čtyři tváři mělo každé. Tvář první tvář cherubínová, tvář pak druhá tvář člověčí, a třetí tvář lvová, čtvrtá pak tvář orličí.'),
(1566909,54,26,10,15,'I zdvihli se cherubínové. To jsou ta zvířata, kteráž jsem viděl u řeky Chebar.'),
(1566910,54,26,10,16,'Když pak šli cherubínové, šla i kola podlé nich, a když vznášeli cherubínové křídla svá, aby se pozdvihli od země, neuchylovala se také kola od nich.'),
(1566911,54,26,10,17,'Když stáli oni, stála, a když se vyzdvihovali, vyzdvihovala se s nimi; nebo duch zvířat byl v nich.'),
(1566912,54,26,10,18,'I odešla sláva Hospodinova od prahu domu, a stála nad cherubíny,'),
(1566913,54,26,10,19,'Hned jakž pozdvihli cherubínové křídel svých a vznesli se od země, před očima mýma odcházejíce, a kola naproti nim, a stála u vrat brány domu Hospodinova východní, a sláva Boha Izraelského svrchu nad nimi.'),
(1566914,54,26,10,20,'To jsou ta zvířata, kteráž jsem viděl pod Bohem Izraelským u řeky Chebar, a poznal jsem, že cherubínové byli.'),
(1566915,54,26,10,21,'Po čtyřech tvářích měl jeden každý, a po čtyřech křídlích jeden každý; podobenství také rukou lidských pod křídly jejich.'),
(1566916,54,26,10,22,'Podobenství pak tváří jejich bylo jako tváří, kteréž jsem byl viděl u řeky Chebar, oblíčej jejich i oni sami. Jeden každý přímo k své straně chodil.'),
(1566917,54,26,11,1,'I vznesl mne Duch, a přivedl mne k bráně východní domu Hospodinova, kteráž patří na východ, a aj, ve vratech brány té pětmecítma mužů, mezi kterýmiž jsem viděl Jazaniáše syna Azurova, a Pelatiáše syna Banaiášova, knížata lidu.'),
(1566918,54,26,11,2,'Tedy řekl mi: Synu člověčí, to jsou ti muži, kteříž smýšlejí nepravost, a skládají radu zlou v městě tomto,'),
(1566919,54,26,11,3,'Říkajíce: Nestavějme domů blízko, sic město bude hrnec a my maso.'),
(1566920,54,26,11,4,'Protož prorokuj proti nim, prorokuj, synu člověčí.'),
(1566921,54,26,11,5,'I sstoupil na mne Duch Hospodinův, a řekl mi: Rci: Takto dí Hospodin: Tak říkáte, dome Izraelský. Nebo což vám koli vstupuje na mysl, o tom já vím.'),
(1566922,54,26,11,6,'Veliké množství zmordovali jste v městě tomto, a naplnili jste ulice jeho zbitými.'),
(1566923,54,26,11,7,'Protož takto praví Panovník Hospodin: Ti, kteříž jsou zbiti od vás, kteréž jste skladli u prostřed něho, oniť jsou maso, město pak hrnec, ale vás vyvedu z prostředku jeho.'),
(1566924,54,26,11,8,'Báli jste se meče, ale meč uvedu na vás, praví Panovník Hospodin.'),
(1566925,54,26,11,9,'A vyvedu vás z prostředku jeho, a dám vás v ruku cizích, a vykonám nad vámi soudy.'),
(1566926,54,26,11,10,'Mečem padnete, na pomezí Izraelském souditi vás budu, a zvíte, že já jsem Hospodin.'),
(1566927,54,26,11,11,'Město nebude vám hrnec, aniž vy budete u prostřed něho maso, na pomezí Izraelském souditi vás budu.'),
(1566928,54,26,11,12,'I zvíte, že já jsem Hospodin, poněvadž jste v ustanoveních mých nechodili, a soudů mých nečinili, a podlé soudů těch národů, kteříž jsou vůkol vás, činili jste.'),
(1566929,54,26,11,13,'Stalo se pak, když jsem prorokoval, že Pelatiáš syn Banaiášův umřel. Pročež padl jsem na tvář svou, a zvolal jsem hlasem velikým, řka: Ach, Panovníče Hospodine, skonání, činíš ostatkům Izraelským.'),
(1566930,54,26,11,14,'Tedy stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1566931,54,26,11,15,'Synu člověčí, bratří tvoji, bratří tvoji, příbuzní tvoji, a všecken dům Izraelský, všecken dům, kterýmž říkali obyvatelé Jeruzalémští: Daleko zajděte od Hospodina, nám jest dána země tato v dědictví.'),
(1566932,54,26,11,16,'Protož rci: Takto praví Panovník Hospodin: Ačkoli daleko zahnal jsem je mezi národy, a ačkoli rozptýlil jsem je do zemí, však budu jim svatyní i za ten malý čas v zemích těch, do kterýchž přijdou.'),
(1566933,54,26,11,17,'Protož rci: Takto praví Panovník Hospodin: Shromáždím vás z národů a zberu vás z zemí, do kterýchž rozptýleni jste, a dám vám zemi Izraelskou.'),
(1566934,54,26,11,18,'I vejdou tam, a vyvrhou všecky mrzkosti její, i všecky ohavnosti její z ní.'),
(1566935,54,26,11,19,'Nebo dám jim srdce jedno, a Ducha nového dám do vnitřností vašich, a odejmu srdce kamenné z těla jejich, a dám jim srdce masité,'),
(1566936,54,26,11,20,'Aby v ustanoveních mých chodili, a soudů mých ostříhali, a činili je. I budou lidem mým, a já budu jejich Bohem.'),
(1566937,54,26,11,21,'Kterýchž pak srdce chodilo by po žádostech mrzkostí svých a ohavností svých, těch cestu na hlavu jejich obrátím, praví Panovník Hospodin.'),
(1566938,54,26,11,22,'Tedy vznesli cherubínové křídla svá i kola s nimi, sláva pak Boha Izraelského nad nimi svrchu.'),
(1566939,54,26,11,23,'I odešla sláva Hospodinova z prostředku města, a stála na hoře, kteráž jest na východ městu.'),
(1566940,54,26,11,24,'Duch pak vznesl mne, a zase mne přivedl do země Kaldejské k zajatým, u vidění skrze Ducha Božího. I odešlo ode mne vidění, kteréž jsem viděl.'),
(1566941,54,26,11,25,'A mluvil jsem k zajatým všecky ty věci Hospodinovy, kteréž mi ukázal.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566942,54,26,12,1,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1566943,54,26,12,2,'Synu člověčí, u prostřed domu zpurného ty bydlíš, kteříž mají oči, aby viděli, však nevidí; uši mají, aby slyšeli, však neslyší, proto že dům zpurný jsou.'),
(1566944,54,26,12,3,'Protož ty, synu člověčí, připrav sobě to, s čím bys se stěhoval, a stěhuj se ve dne před očima jejich. Přestěhuješ se pak z místa svého na místo jiné před očima jejich, zdaby aspoň viděli; nebo dům zpurný jsou.'),
(1566945,54,26,12,4,'Vynesa pak své věci, jakožto ty, s nimiž se stěhovati máš ve dne před očima jejich, vyjdi u večer před očima jejich, jako ti, kteříž se stěhují.'),
(1566946,54,26,12,5,'Před očima jejich prokopej sobě zed, a vynes skrze ni.'),
(1566947,54,26,12,6,'Před očima jejich na rameni nes, po tmě vynes, tvář svou přikrej, a nehleď na zemi; nebo za zázrak dal jsem tě domu Izraelskému.'),
(1566948,54,26,12,7,'I učinil jsem tak, jakž rozkázáno bylo. Věci své vynesl jsem, jakožto ty, s nimiž bych se stěhoval ve dne, u večer pak prokopal jsem sobě zed rukou; po tmě jsem je vynesl, na rameni nesa před očima jejich.'),
(1566949,54,26,12,8,'Opět stalo se slovo Hospodinovo ke mně ráno, řkoucí:'),
(1566950,54,26,12,9,'Synu člověčí, zdaližť řekli dům Izraelský, dům ten zpurný: Co ty děláš?'),
(1566951,54,26,12,10,'Rciž jim: Takto praví Panovník Hospodin: Na kníže v Jeruzalémě vztahuje se břímě toto a na všecken dům Izraelský, kteříž jsou u prostřed něho.'),
(1566952,54,26,12,11,'Rciž jim: Já jsem zázrakem vaším. Jakož jsem činil, tak se stane jim, postěhují se a v zajetí půjdou.'),
(1566953,54,26,12,12,'A kníže, kteréž jest u prostřed nich, na rameni ponese po tmě a vyjde. Zed prokopají, aby jej vyvedli skrze ni; tvář svou zakryje, tak že nebude viděti okem svým země.'),
(1566954,54,26,12,13,'Nebo roztáhnu sít svou na něj, a polapen bude do vrše mé, a zavedu jej do Babylona, země Kaldejské, kteréž neuzří, a tam umře.'),
(1566955,54,26,12,14,'Všecky také, kteříž jsou vůkol něho na pomoc jemu, i všecky houfy jeho rozptýlím na všecky strany, a mečem dobytým budu je stihati.'),
(1566956,54,26,12,15,'I zvědí, že já jsem Hospodin, když je rozptýlím mezi národy, a rozženu je po krajinách.'),
(1566957,54,26,12,16,'Pozůstavím pak z nich muže nemnohé po meči, po hladu a po moru, aby vypravovali všecky ohavnosti své mezi národy, kamž se dostanou, i zvědí, že já jsem Hospodin.'),
(1566958,54,26,12,17,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1566959,54,26,12,18,'Synu člověčí, chléb svůj s strachem jez, a vodu svou s třesením a s zámutkem pí,'),
(1566960,54,26,12,19,'A rci lidu země této: Takto praví Panovník Hospodin o obyvatelích Jeruzalémských, o zemi Izraelské: Chléb svůj s zámutkem jísti budou, a vodu svou s předěšením píti, aby obloupena byla země jeho z hojnosti své, pro nátisk všech přebývajících v ní.'),
(1566961,54,26,12,20,'Města také, v nichž bydlejí, zpustnou, a země pustá bude, a tak zvíte, že já jsem Hospodin.'),
(1566962,54,26,12,21,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1566963,54,26,12,22,'Synu člověčí, jaké to máte přísloví o zemi Izraelské, říkajíce: Prodlí se dnové, aneb zahyne všeliké vidění?'),
(1566964,54,26,12,23,'Protož rci jim: Takto praví Panovník Hospodin: Učiním, aby přestalo přísloví toto, aniž užívati budou přísloví toho více v Izraeli. Rci jim: Nýbrž přiblížili se dnové ti a splnění všelikého vidění.'),
(1566965,54,26,12,24,'Nebo nebude více žádného vidění marného, a hádání pochlebníka u prostřed domu Izraelského,'),
(1566966,54,26,12,25,'Proto že já Hospodin mluviti budu, a kterékoli slovo promluvím, stane se. Neprodlíť se dlouho, ale za dnů vašich, dome zpurný, mluviti budu slovo, a naplním je, praví Panovník Hospodin.'),
(1566967,54,26,12,26,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1566968,54,26,12,27,'Synu člověčí, aj, dům Izraelský říkají: Vidění to, kteréž vidí tento, ke dnům mnohým patří, a na dlouhé časy tento prorokuje.'),
(1566969,54,26,12,28,'Protož rci jim: Takto praví Panovník Hospodin: Neprodlíť se dlouho všeliké slovo mé, ale slovo, kteréž mluviti budu, stane se, praví Panovník Hospodin.'),
(1566970,54,26,13,1,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1566971,54,26,13,2,'Synu člověčí, prorokuj proti prorokům Izraelským, kteříž prorokují, a rci prorokujícím z srdce svého: Slyšte slovo Hospodinovo:'),
(1566972,54,26,13,3,'Takto praví Panovník Hospodin: Běda prorokům bláznivým, kteříž následují ducha svého, ješto však nic neviděli.'),
(1566973,54,26,13,4,'Podobni jsou liškám na pustinách proroci tvoji, Izraeli.'),
(1566974,54,26,13,5,'Nevstupujete k mezerám, aniž děláte hradby okolo domu Izraelského, aby ostáti mohl v boji v den Hospodinův.'),
(1566975,54,26,13,6,'Vídají marnost a hádání lživé. Říkají: Praví Hospodin, ješto jich neposlal Hospodin, a troštují lidi, aby jen utvrdili slovo své.'),
(1566976,54,26,13,7,'Zdaliž vidění marného nevídáte, a hádání lživého nevypravujete? A říkáte: Praví Hospodin, ješto jsem já nemluvil.'),
(1566977,54,26,13,8,'Pročež takto praví Panovník Hospodin: Proto že mluvíte marnost, a vídáte lež, protož aj, já jsem proti vám, praví Panovník Hospodin.'),
(1566978,54,26,13,9,'Nebo bude ruka má proti prorokům, kteříž vídají marnost a hádají lež. V losu lidu mého nebudou, a v popisu domu Izraelského nebudou zapsáni, aniž do země Izraelské vejdou. I zvíte, že já jsem Panovník Hospodin,'),
(1566979,54,26,13,10,'Proto, proto že v blud uvedli lid můj, říkajíce: Pokoj, ješto nebylo žádného pokoje. Jeden zajisté ustavěl stěnu hliněnou, a jiní obmítali ji vápnem ničemným.'),
(1566980,54,26,13,11,'Rciž těm, kteříž obmítají vápnem ničemným: I však to padne. Přijde příval rozvodnilý, a vy, kamenové krupobití velikého, spadnete, a vítr bouřlivý roztrhne ji.'),
(1566981,54,26,13,12,'A aj, když padne ta stěna, zdaliž vám nebude řečeno: Kdež jest to obmítání, jímž jste obmítali?'),
(1566982,54,26,13,13,'Protož takto praví Panovník Hospodin: Roztrhnu ji, pravím, větrem bouřlivým v prchlivosti své, a příval rozvodnilý v hněvě mém přijde, a kamení krupobití velikého v prchlivosti mé k vyhlazení jí.'),
(1566983,54,26,13,14,'Nebo rozbořím stěnu tu, kterouž jste obmetali vápnem ničemným, a porazím ji na zem, tak že odkryt bude grunt její. I padne, a zkaženi budete u prostřed ní, a zvíte, že já jsem Hospodin.'),
(1566984,54,26,13,15,'A tak vykonaje prchlivost svou na té stěně, a na těch, kteříž ji obmítají vápnem ničemným, dím vám: Není více té stěny, není ani těch, kteříž ji obmítali,'),
(1566985,54,26,13,16,'Totiž proroků Izraelských, kteříž prorokují Jeruzalému, a ohlašují jemu vidění pokoje, ješto není žádného pokoje, praví Panovník Hospodin.'),
(1566986,54,26,13,17,'Ty pak, synu člověčí, obrať tvář svou k dcerám lidu svého, kteréž prorokují z srdce svého, a prorokuj i proti nim.'),
(1566987,54,26,13,18,'A rci: Takto praví Panovník Hospodin: Běda těm, kteréž šijí polštáříky pod všeliké lokty rukou lidu mého, a dělají kukly na hlavu všeliké postavy, aby lovily duše. Zdaliž loviti máte duše lidu mého, abyste se živiti mohly?'),
(1566988,54,26,13,19,'Nebo zlehčujete mne u lidu mého pro hrst ječmene a pro kus chleba, umrtvujíce duše, kteréž neumrou, a obživujíce duše, kteréž živy nebudou, lhouce lidu mému, kteříž poslouchají lži.'),
(1566989,54,26,13,20,'Protož takto praví Panovník Hospodin: Aj, já dám se v polštáříky vaše, jimiž vy lovíte tam duše, abyste je oklamaly. Nebo strhnu je s ramenou vašich, a propustím duše, duše, kteréž vy lovíte, abyste je oklamaly.'),
(1566990,54,26,13,21,'I strhnu kukly vaše, a vytrhnu lid svůj z ruky vaší, tak abyste jich nemohly více loviti, i zvíte, že já jsem Hospodin;'),
(1566991,54,26,13,22,'Proto že kormoutíte srdce spravedlivého lžmi, ješto jsem já ho nekormoutil, a posilujete rukou bezbožného, aby se neodvrátil od zlé cesty své, obživujíce jej.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1566992,54,26,13,23,'Protož nebudete vídati marnosti, a s hádáním nebudete se obírati více; nebo vytrhnu lid svůj z ruky vaší, i zvíte, že já jsem Hospodin.'),
(1566993,54,26,14,1,'Potom přišedše ke mně muži z starších Izraelských, seděli přede mnou.'),
(1566994,54,26,14,2,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1566995,54,26,14,3,'Synu člověčí, muži tito složili ukydané bohy své v srdci svém, a nepravost, kteráž jim k urážce jest, položili před tváři své. Zdaliž se upřímě radí se mnou?'),
(1566996,54,26,14,4,'Protož mluv jim a rci jim: Takto praví Panovník Hospodin: Kdo by koli z domu Izraelského složil ukydané bohy své v srdci svém, a nepravost, kteráž mu k urážce jest, položil před tvář svou, a přišel by k proroku: já Hospodin odpovídati budu tomu, kterýž přišel, o množství ukydaných bohů jeho,'),
(1566997,54,26,14,5,'Abych polapil dům Izraelský v srdci jejich, že se odvrátili ode mne k ukydaným bohům svým všickni napořád.'),
(1566998,54,26,14,6,'Protož rci domu Izraelskému: Takto praví Panovník Hospodin: Obraťte se a odvraťte od ukydaných bohů vašich, a ode všech ohavností vašich odvraťte tvář svou.'),
(1566999,54,26,14,7,'Nebo kdož by koli z domu Izraelského i z pohostinných, kteříž jsou pohostinu v Izraeli, odvrátil se od následování mne, a složil by ukydané bohy své v srdci svém, a nepravost, kteráž mu k urážce jest, položil by před tvář svou a přišel by k proroku, aby se mne tázal skrze něho: já Hospodin odpovím jemu o sobě,'),
(1567000,54,26,14,8,'A obrátím tvář svou hněvivou proti muži tomu, a dám jej za znamení a za přísloví, a vytnu jej z prostřed lidu svého, i zvíte, že já jsem Hospodin.'),
(1567001,54,26,14,9,'Prorok pak, dal-li by se přivábiti, aby mluvil slovo, já Hospodin přivábil jsem proroka toho. Než vztáhnuť ruku svou na něj, a vyhladím jej z prostřed lidu svého Izraelského.'),
(1567002,54,26,14,10,'A tak ponesou nepravost svou. Jakáž pokuta na toho, kdož by se tázal, takováž pokuta na proroka bude,'),
(1567003,54,26,14,11,'Aby nebloudili více dům Izraelský ode mne, a nepoškvrňovali se více žádnými převrácenostmi svými, aby byli lidem mým, a já abych byl jejich Bohem, praví Panovník Hospodin.'),
(1567004,54,26,14,12,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567005,54,26,14,13,'Synu člověčí, když by země zhřešila proti mně, dopouštějíc se přestoupení, tehdy vztáhl-li bych ruku svou na ni, a zlámal jí hůl chleba, a poslal bych na ni hlad, a vyhubil z ní lidi i hovada:'),
(1567006,54,26,14,14,'By pak byli u prostřed ní tito tři muži, Noé, Daniel a Job, oni v spravedlnosti své vysvobodili by sami sebe, praví Panovník Hospodin.'),
(1567007,54,26,14,15,'Pakli bych zvěř lítou uvedl na zemi, tak že by ji na sirobu přivedla, a byla by pustá, aniž by kdo přes ni jíti mohl pro zvěř:'),
(1567008,54,26,14,16,'Živť jsem já, praví Panovník Hospodin, že byť tři muži tito u prostřed ní byli, nikoli by nevysvobodili synů ani dcer. Oni by sami vysvobozeni byli, země pak byla by pustá.'),
(1567009,54,26,14,17,'Aneb meč uvedl-li bych na zemi tu, a řekl bych meči: Projdi skrz zemi tu, abych vyhubil z ní lidi i hovada:'),
(1567010,54,26,14,18,'Živť jsem já, praví Panovník Hospodin, že byť pak tři muži tito byli u prostřed ní, nikoli by nevysvobodili synů ani dcer, ale oni sami by vysvobozeni byli.'),
(1567011,54,26,14,19,'Aneb mor poslal-li bych na zemi tu, a vylil prchlivost svou na ni k zhoubě, aby vyhlazeni byli z ní lidé i hovada:'),
(1567012,54,26,14,20,'Živť jsem já, praví Panovník Hospodin, že byť pak Noé, Daniel a Job u prostřed ní byli, nikoli by ani syna ani dcery nevysvobodili. Oni v spravedlnosti své vysvobodili by sami sebe.'),
(1567013,54,26,14,21,'Nýbrž takto praví Panovník Hospodin: Bych pak čtyři pokuty své zlé, meč a hlad, zvěř lítou a mor poslal na Jeruzalém, abych vyhubil z něho lidi i hovada,'),
(1567014,54,26,14,22,'A aj, pozůstali-li by v něm, kteříž by toho ušli, a vyvedeni byli, synové neb dcery: aj, i oni musejí jíti k vám, a uzříte cestu jejich a skutky jejich, i potěšíte se nad tím zlým, kteréž uvedu na Jeruzalém, nade vším, což uvedu na něj.'),
(1567015,54,26,14,23,'A tak potěší vás, když uzříte cestu jejich a skutky jejich. I zvíte, že jsem ne nadarmo učinil všecko to, což jsem učinil při něm, praví Panovník Hospodin.'),
(1567016,54,26,15,1,'Tedy stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567017,54,26,15,2,'Synu člověčí, co jest dřevo révové proti všelijakému dřevu, aneb proti ratolestem dříví lesního?'),
(1567018,54,26,15,3,'Zdaliž vzato bude z něho dřevo k udělání něčeho? Zdaliž udělají z něho hřebík k zavěšování na něm všelijaké nádoby?'),
(1567019,54,26,15,4,'Aj, na oheň dává se k sežrání. Když oba konce jeho sežere oheň, a prostředek jeho obhoří, zdaž se k čemu hoditi může?'),
(1567020,54,26,15,5,'Aj, když byl celý, nic nemohlo býti z něho uděláno, ovšem když jej oheň sežral, a shořel, k ničemu se více hoditi nebude.'),
(1567021,54,26,15,6,'Protož takto praví Panovník Hospodin: Jakož jest dřevo révové mezi dřívím lesním, kteréž jsem oddal ohni k sežrání, tak jsem oddal obyvatele Jeruzalémské.'),
(1567022,54,26,15,7,'Nebo postavím tvář svou hněvivou proti nim. Z ohně jednoho vyjdou, a oheň druhý zžíře je. I zvíte, že já jsem Hospodin, když obrátím tvář svou hněvivou proti nim.'),
(1567023,54,26,15,8,'A obrátím zemi tuto v poušť, proto že se přestoupení dopouštěli, praví Panovník Hospodin.'),
(1567024,54,26,16,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567025,54,26,16,2,'Synu člověčí, oznam Jeruzalému ohavnosti jeho,'),
(1567026,54,26,16,3,'A rci: Takto praví Panovník Hospodin dceři Jeruzalémské: Obcování tvé a rod tvůj jest z země Kananejské, otec tvůj jest Amorejský, a matka tvá Hetejská.'),
(1567027,54,26,16,4,'Narození pak tvé: V den, v němž jsi se narodila, nebyl přiřezán pupek tvůj, a vodou nebylas obmyta, abys ošetřena byla, aniž jsi byla solí posolena, ani plénkami obvinuta.'),
(1567028,54,26,16,5,'Neslitovalo se nad tebou oko, aťby v jednom z těch věcí posloužilo, maje lítost nad tebou, ale bylas povržena na svrchku pole, proto že jsi ošklivá byla v den, v kterémž jsi narodila se.'),
(1567029,54,26,16,6,'A jda mimo tebe, a vida tě ku potlačení vydanou ve krvi tvé, řekl jsem tobě: Ve krvi své živa buď. Řekl jsem, pravím, tobě: Ve krvi své živa buď.'),
(1567030,54,26,16,7,'Rozmnožil jsem tě jako z rostliny polní, i rozmnožena jsi a zveličena, a přišlas k největší ozdobě. Prsy tvé oduly se, a vlasy tvé zrostly, ač jsi byla nahá a odkrytá.'),
(1567031,54,26,16,8,'Protož jda mimo tě, a vida tě, an aj, čas tvůj čas milování, vztáhl jsem křídlo své na tě, a přikryl jsem nahotu tvou, a přísahou zavázav se tobě, všel jsem v smlouvu s tebou, praví Panovník Hospodin, a tak jsi má učiněna.'),
(1567032,54,26,16,9,'I umyl jsem tě vodou, a splákl jsem krev tvou s tebe, a pomazal jsem tě olejem.'),
(1567033,54,26,16,10,'Nadto přioděl jsem tě rouchem krumpovaným, a obul jsem tě v drahé střevíce, a opásal jsem tě kmentem, a přioděl jsem tě rouchem hedbávným.'),
(1567034,54,26,16,11,'Ozdobil jsem tě také ozdobou, a dal jsem náramky na ruce tvé, a točenici na hrdlo tvé.'),
(1567035,54,26,16,12,'Dalť jsem ozdobu i na čelo tvé, a náušnice na uši tvé, a korunu krásnou na hlavu tvou.'),
(1567036,54,26,16,13,'A tak bylas ozdobena zlatem a stříbrem, a oděv tvůj byl kment a roucho hedbávné, a proměnných barev roucho. Běl a med a olej jídala jsi, a krásná jsi učiněna velmi velice, a šťastněť se vedlo v království,'),
(1567037,54,26,16,14,'Tak že se rozešla pověst o tobě mezi národy pro krásu tvou; nebo dokonalá byla, pro slávu mou, kterouž jsem byl vložil na tebe, praví Panovník Hospodin.'),
(1567038,54,26,16,15,'Ale úfalas v krásu svou, a smilnilas přičinou pověstí své; nebo jsi páchala smilství s každým mimo tebe jdoucím. Každý snadně užil krásy tvé.'),
(1567039,54,26,16,16,'A vzavši z roucha svého, nadělalas sobě výsostí rozličných barev, a páchalas smilství při nich, jemuž podobné nikdy nepřijde, aniž kdy potom bude.'),
(1567040,54,26,16,17,'Nad to, vzavši přípravy ozdoby své z zlata mého a stříbra mého, kteréžť jsem byl dal, nadělalas sobě obrazů pohlaví mužského, a smilnilas s nimi.'),
(1567041,54,26,16,18,'Vzalas také roucha svá krumpovaná, a přiodílas je, olej můj i kadidlo mé kladlas před nimi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567042,54,26,16,19,'Ano i chléb můj, kterýžť jsem byl dal, běl a olej i med, jímž jsem tě krmil, kladlas před nimi u vůni příjemnou, a bylo tak, praví Panovník Hospodin.'),
(1567043,54,26,16,20,'Bralas i syny své a dcery své, kteréž jsi mně zplodila, a obětovalas jim k spálení. Cožť se ještě zdálo málo, taková smilství tvá,'),
(1567044,54,26,16,21,'Žes i syny mé zabíjela a dávalas je, aby je provodili jim?'),
(1567045,54,26,16,22,'K tomu ve všech ohavnostech svých a smilstvích svých nerozpomenulas se na dny mladosti své, když jsi byla nahá a odkrytá, ku potlačení vydaná ve krvi své.'),
(1567046,54,26,16,23,'Ale stalo se přes všecku tuto nešlechetnost tvou, (běda, běda tobě), praví Panovník Hospodin,'),
(1567047,54,26,16,24,'Že jsi vystavěla sobě i vysoké místo, a vzdělalas sobě výsost v každé ulici.'),
(1567048,54,26,16,25,'Při všelikém rozcestí udělalas výsost svou, a zohavilas krásu svou, roztahujíc nohy své každému tudy jdoucímu, a příliš jsi smilnila.'),
(1567049,54,26,16,26,'Nebo smilnila jsi s syny Egyptskými, sousedy svými velikého těla, a příliš jsi smilnila, abys mne k hněvu popouzela.'),
(1567050,54,26,16,27,'Protož aj, vztáhl jsem ruku svou na tebe, a ujal jsem vyměřeného pokrmu tvého, a vydal jsem tě k líbosti nenávidících tě dcer Filistinských, kteréžto styděly se za cestu tvou nešlechetnou.'),
(1567051,54,26,16,28,'Smilnilas též s syny Assyrskými, proto že jsi nemohla nasytiti se, a smilnivši s nimi, aniž jsi tak se nasytila.'),
(1567052,54,26,16,29,'A tak příliš jsi smilnila v zemi Kananejské s Kaldejskými, a aniž jsi tak se nasytila.'),
(1567053,54,26,16,30,'Jakť jest zmámeno srdce tvé, praví Panovník Hospodin, poněvadž se dopouštíš všech těchto skutků ženy nevěstky přenestydaté,'),
(1567054,54,26,16,31,'Stavěje sobě vysoké místo na rozcestí všeliké silnice, a výsost sobě stroje i v každé ulici. Nýbrž pohrdaje darem, nejsi ani jako nevěstka,'),
(1567055,54,26,16,32,'A žena cizoložná, kteráž místo muže svého povoluje cizím.'),
(1567056,54,26,16,33,'Všechněm nevěstkám dávají mzdu, ale ty dávalas mzdu svou všechněm frejířům svým, a darovalas je, aby vcházeli k tobě odevšad pro smilství tvá.'),
(1567057,54,26,16,34,'A tak jest při tobě naproti obyčeji těch žen při smilstvích tvých, poněvadž tě k smilství nehledají, nýbrž ty dáváš dary, a ne tobě dar dáván bývá. A toť jest naopak.'),
(1567058,54,26,16,35,'Protož ó nevěstko, slyš slovo Hospodinovo:'),
(1567059,54,26,16,36,'Takto praví Panovník Hospodin: Proto že vylita jest mrzkost tvá, a odkrývána byla nahota tvá při smilstvích tvých s frejíři tvými, a se všemi ukydanými bohy ohavností tvých, též pro krev synů tvých, kteréž jsi dala jim:'),
(1567060,54,26,16,37,'Proto aj, já shromáždím všecky frejíře tvé, s nimiž jsi obcovala, a všecky, kteréž jsi milovala, se všechněmi, jichž jsi nenáviděla, a shromáždě je proti tobě odevšad, odkryji nahotu tvou před nimi, aby viděli všecku nahotu tvou.'),
(1567061,54,26,16,38,'A budu tě souditi soudem cizoložnic, a těch, kteříž krev vylévají, a oddám tě k smrti, kteráž přijde na tě z prchlivosti a horlení.'),
(1567062,54,26,16,39,'Nebo vydám tě v ruku jejich. I rozboří vysoké místo tvé, a rozválejí výsosti tvé, a svlekouce tě z roucha tvého, poberou přípravy ozdoby tvé, a nechají tě nahé a odkryté.'),
(1567063,54,26,16,40,'I přivedou proti tobě shromáždění, a uházejí tě kamením, a probodnou tě meči svými.'),
(1567064,54,26,16,41,'Popálí také domy tvé ohněm, a vykonají na tobě pomstu před očima žen mnohých, a tak přítrž učiním tvému smilství, a aniž budeš dávati daru více.'),
(1567065,54,26,16,42,'A tak odpočineť sobě hněv můj na tobě, a horlení mé odejde od tebe, abych upokojil se a nehněval se více,'),
(1567066,54,26,16,43,'Proto žes se nerozpomenula na dny mladosti své, ale postavovalas se proti mně ve všem tom. Aj hle, já také cestu tvou na hlavu tvou obrátil jsem, praví Panovník Hospodin, tak že nebudeš páchati nešlechetnosti, ani kterých ohavností svých.'),
(1567067,54,26,16,44,'Aj, kdožkoli užívá přísloví, o tobě užive přísloví, řka: Jakáž matka, takáž dcera její.'),
(1567068,54,26,16,45,'Dcera matky své jsi, té, kteráž sobě zošklivila muže svého a dítky své, a sestra obou sestr svých jsi, kteréž zošklivily sobě muže své a dítky své. Matka vaše jest Hetejská, a otec váš Amorejský.'),
(1567069,54,26,16,46,'Sestra pak tvá starší, kteráž sedí po levici tvé, jest Samaří a dcery její, a sestra tvá mladší, kteráž sedí po pravici tvé, jest Sodoma a dcery její.'),
(1567070,54,26,16,47,'Nýbrž aniž jsi po cestách jejich chodila, ani podlé ohavností jejich činila, zošklivivši sobě jako věc špatnou, pročež pokazilas se více než ony na všech cestách svých.'),
(1567071,54,26,16,48,'Živť jsem já, praví Panovník Hospodin, že Sodoma sestra tvá i dcery její nečinily, jako jsi ty činila s dcerami svými.'),
(1567072,54,26,16,49,'Aj, tatoť byla nepravost Sodomy sestry tvé: Pýcha, sytost chleba a hojnost pokoje. To ona majíc i dcery její, ruky však chudého a nuzného neposilňovala.'),
(1567073,54,26,16,50,'Ale pozdvihše se, páchaly ohavnost přede mnou; protož sklidil jsem je, jakž mi se vidělo.'),
(1567074,54,26,16,51,'Samaří také ani polovice hříchů tvých nenahřešila. Nebo jsi rozhojnila ohavnosti své nad ně, a tak jsi spravedlivější býti ukázala sestry své všemi ohavnostmi svými, kteréž jsi páchala.'),
(1567075,54,26,16,52,'Nesiž i ty také potupu svou, kterouž jsi přisoudila sestrám svým, pro hříchy své, kteréž jsi ohavně páchala více než ony. Spravedlivějšíť byly než ty. I ty, pravím, styď se, a nes potupu svou, poněvadž spravedlivější býti ukazuješ sestry své.'),
(1567076,54,26,16,53,'Přivedu-li zase zajaté jejich, totiž zajaté Sodomy a dcer jejich, též zajaté Samaří a dcer jejich, takéť zajetí zajatých tvých u prostřed nich,'),
(1567077,54,26,16,54,'Proto, abys musila nésti potupu svou a hanbiti se za všecko, což jsi páchala, jsuc jejich potěšením.'),
(1567078,54,26,16,55,'Jestližeť sestry tvé, Sodoma a dcery její, navrátí se k prvnímu způsobu svému, též Samaří a dcery její navrátí-li se k prvnímu způsobu svému: i ty také s dcerami svými navrátíte se k prvnímu způsobu svému.'),
(1567079,54,26,16,56,'Poněvadž nebyla Sodoma sestra tvá pověstí v ústech tvých v den zvýšení tvého,'),
(1567080,54,26,16,57,'Prvé než zjevena byla zlost tvá, jako za času útržky od dcer Syrských a všech, kteříž jsou vůkol nich, dcer Filistinských, kteréž tě hubily se všech stran:'),
(1567081,54,26,16,58,'Nešlechetnost svou a ohavnosti své poneseš, praví Hospodin.'),
(1567082,54,26,16,59,'Nebo takto praví Panovník Hospodin: Tak učiním tobě, jakž jsi učinila, když jsi pohrdla přísahou, a zrušila smlouvu.'),
(1567083,54,26,16,60,'A však rozpomenu se na smlouvu svou s tebou ve dnech mladosti tvé, potvrdím, pravím, tobě smlouvy věčné.'),
(1567084,54,26,16,61,'I rozpomeneš se na cesty své, a hanbiti se budeš, když přijmeš sestry své starší, nežli jsi ty, i mladší, nežli jsi ty, a dám je tobě za dcery, ale ne podlé smlouvy tvé.'),
(1567085,54,26,16,62,'A tak utvrdím smlouvu svou s tebou, i zvíš, že já jsem Hospodin,'),
(1567086,54,26,16,63,'Abys se rozpomenula a styděla, a nemohla více úst otevříti pro hanbu svou, když tě očistím ode všeho, což jsi činila, praví Panovník Hospodin.'),
(1567087,54,26,17,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567088,54,26,17,2,'Synu člověčí, vydej pohádku, a předlož podobenství o domu Izraelském,'),
(1567089,54,26,17,3,'A rci: Takto praví Panovník Hospodin: Orlice veliká, velikých křídel a dlouhých brků, plná peří, strakatá, přiletěvši na Libán, vzala vrch cedru.'),
(1567090,54,26,17,4,'Vrch mladistvých ratolestí jeho ulomila, a přenesla jej do země kupecké; v městě kupeckém položila jej.'),
(1567091,54,26,17,5,'Potom vzavši z semene té země, vsadila je v poli úrodném, a vsadila je velmi opatrně při vodách mnohých.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567092,54,26,17,6,'Kteréžto bylo by vzešlo, a bylo by révem bujným, jakžkoli nízké postavy, a byly by patřily ratolesti jeho k ní, a kořenové jeho poddáni byli by jí, a tak bylo by kmenem vinným, kterýž by vydal byl ratolesti, a vypustil rozvody.'),
(1567093,54,26,17,7,'Ale byla orlice jedna veliká velikých křídel a vypeřená, a aj, ten kmen vinný připjal kořeny své k ní, a ratolesti své vztáhl k ní, aby svlažovala jej z brázd štípení svého,'),
(1567094,54,26,17,8,'Ješto v poli dobrém, při vodách mnohých štípen byl, aby vypustil ratolesti, a nesl ovoce, a byl kmenem slavným.'),
(1567095,54,26,17,9,'Rci: Takto praví Panovník Hospodin: Zdaliž se podaří? Zdaliž kořenů jeho nevytrhá, a ovoce jeho neotrhá a neusuší? Zdaž všech ratolestí vyrostlých z něho neusuší? Zdaliž s velikou silou a s mnohým lidem nevyhladí ho z kořenů jeho?'),
(1567096,54,26,17,10,'Aj, jakžkoli štípen, zdaliž se podaří? Zdaliž, jakž se ho dotkne vítr východní, do konce neuschne? Při brázdách, při nichž se ujal, zdaž neuschne?'),
(1567097,54,26,17,11,'Za tím stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567098,54,26,17,12,'Rci nyní domu zpurnému: Nevíte-liž, co je toto? Rci: Aj, přitáhl král Babylonský do Jeruzaléma, a vzal krále jeho i knížata jeho, a zavedl je s sebou do Babylona.'),
(1567099,54,26,17,13,'Vzal také z semene královského, a učiniv s ním smlouvu, přísahou jej zavázal, a silné země té pobral,'),
(1567100,54,26,17,14,'Aby bylo království snížené, proto aby se nepozdvihovalo, aby ostříhaje smlouvy jeho, tak stálo.'),
(1567101,54,26,17,15,'Ale zprotivil se jemu, poslav posly své do Egypta, aby jemu podal koní a lidu mnohého. Zdaž se mu to podaří? Zdaž pomsty ujde ten, kdož tak činí? Ten kdož ruší smlouvu, zdaliž pomsty ujde?'),
(1567102,54,26,17,16,'Živť jsem já, praví Panovník Hospodin, že v místě krále toho, kterýž jej králem učinil, jehož přísahou pohrdl, a jehož smlouvu zrušil, u něho v Babyloně umře.'),
(1567103,54,26,17,17,'Aniž mu Farao s vojskem velikým a s zástupem mnohým co napomůže v boji, když vysype násyp, a vzdělá šance, aby zahubil množství lidí,'),
(1567104,54,26,17,18,'Poněvadž pohrdl přísahou, zrušiv smlouvu. Neb aj, podal ruky své, a však všecko toto činí. Neujdeť pomsty.'),
(1567105,54,26,17,19,'Protož takto praví Panovník Hospodin: Živť jsem já, že přísahu svou, kterouž pohrdl, a smlouvu svou, kterouž zrušil, jistotně obrátím na hlavu jeho.'),
(1567106,54,26,17,20,'Nebo roztáhnu na něj sít svou, a polapen bude do vrše mé, i zavedu jej do Babylona, a souditi se s ním budu tam pro přestoupení jeho, kteréhož se dopustil proti mně.'),
(1567107,54,26,17,21,'Všickni též, kteříž utekli od něho se všemi houfy jeho, od meče padnou, ostatní pak na všecky strany rozprostříni budou. I zvíte, že já Hospodin mluvil jsem.'),
(1567108,54,26,17,22,'Takto praví Panovník Hospodin: A však vezmu z vrchu cedru toho vysokého a vsadím, z vrchu mladistvých ratolestí jeho mladou větvičku ulomím, a štípím na hoře vysoké a vyvýšené.'),
(1567109,54,26,17,23,'Na hoře vysoké Izraelské štípím ji, i vypustí ratolesti, a ponese ovoce, a tak učiněna bude cedrem slavným, a bude bydliti pod ním všeliké ptactvo; všecko, což křídla má, v stínu ratolestí jeho bydliti bude.'),
(1567110,54,26,17,24,'A tak zvědí všecka dříví polní, že já Hospodin snížil jsem dřevo vysoké, a povýšil jsem dřeva nízkého; usušil jsem strom zelený, a způsobil to, aby zkvetl strom suchý. Já Hospodin mluvil jsem to i učiním.'),
(1567111,54,26,18,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567112,54,26,18,2,'Což jest vám, že užíváte přísloví tohoto o zemi Izraelské, říkajíce: Otcové jedli hrozen trpký, a zubové synů laskominy mají?'),
(1567113,54,26,18,3,'Živť jsem já, praví Panovník Hospodin, že nebudete moci více užívati přísloví tohoto v Izraeli.'),
(1567114,54,26,18,4,'Aj, všecky duše mé jsou, jakož duše otcova, tak i duše synova mé jsou. Duše, kteráž hřeší, ta umře.'),
(1567115,54,26,18,5,'Nebo byl-li by někdo spravedlivý, a činil by soud a spravedlnost;'),
(1567116,54,26,18,6,'Na horách by nejídal, a očí svých nepozdvihoval k ukydaným bohům domu Izraelského, a manželky bližního svého by nepoškvrnil, a k ženě pro nečistotu oddělené nepřistoupil;'),
(1567117,54,26,18,7,'Kterýž by žádného neutiskal, základ dlužníku svému by navracoval, cizího mocí nebral, chleba svého by lačnému udílel, a nahého přiodíval rouchem;'),
(1567118,54,26,18,8,'Na lichvu by nedával, a úroku nebral, od nepravosti ruku svou by odvracoval, soud pravý mezi jedním i druhým by činil;'),
(1567119,54,26,18,9,'V ustanoveních mých by chodil, a soudů mých ostříhal, čině, což pravého jest: spravedlivý ten jistě žeť živ bude, praví Panovník Hospodin.'),
(1567120,54,26,18,10,'Zplodil-li by pak syna lotra, prolevače krve, kterýž by čímkoli z těch věcí škodil bratru,'),
(1567121,54,26,18,11,'Onoho pak všeho nečinil by, anobrž i na horách by jídal, a ženy bližního svého by poškvrnil;'),
(1567122,54,26,18,12,'Chudého a nuzného by utiskl, cizí věci mocí vzal, základu by nenavrátil, a k ukydaným bohům očí svých by pozdvihoval, ohavnost provodil,'),
(1567123,54,26,18,13,'Na lichvu by dával, a úrok bral: zdaž bude živ? Nebude živ. Poněvadž všecky ohavnosti tyto činil, jistotně umře, krev jeho přijde na něj.'),
(1567124,54,26,18,14,'A aj, zplodil-li by syna, kterýž by spatřil všecky hříchy otce svého, kteréž činil, a vida, nečinil by tak;'),
(1567125,54,26,18,15,'Na horách by nejídal, a očí svých nepozdvihoval k ukydaným bohům domu Izraelského, manželky bližního svého by nepoškvrnil,'),
(1567126,54,26,18,16,'A aniž by koho utiskal, základu by nezadržoval, cizího mocí nebral, chleba svého lačnému by udílel, a nahého rouchem by přiodíl;'),
(1567127,54,26,18,17,'Od chudého by zdržel ruku svou, lichvy a úroku by nebral, soudy mé činil, v ustanoveních mých by chodil: tenť neumře pro nepravost otce svého, jistě živ bude.'),
(1567128,54,26,18,18,'Otec pak jeho, proto že se bezpráví dopouštěl, cizí věci bratru mocí bral, a to, což není dobré, činil u prostřed lidu svého: protož aj, umře pro nepravost svou.'),
(1567129,54,26,18,19,'Ale říkáte: Jak by to bylo? Zdaž nenese syn nepravosti otcovy? Když syn činí soud a spravedlnost, všech ustanovení mých ostříhá a činí je, jistě žeť živ bude.'),
(1567130,54,26,18,20,'Duše, kteráž hřeší, ta umře. Syn neponese nepravosti otcovy, aniž otec ponese nepravosti synovy; spravedlnost spravedlivého při něm zůstane, též bezbožnost bezbožného na něj připadne.'),
(1567131,54,26,18,21,'Pakli byse bezbožný odvrátil ode všech hříchu svých, kteréž činil, a ostříhal by všech ustanovení mých, a činil by soud a spravedlnost, jistě živ bude a neumře.'),
(1567132,54,26,18,22,'Žádná přestoupení jeho, jichž se dopustil, nebudou jemu připomínána; v spravedlnosti své, kterouž by činil, živ bude.'),
(1567133,54,26,18,23,'Zdaliž jakou líbost mám, když umírá bezbožný? dí Panovník Hospodin. Zdali ne raději když se odvrací od cest svých, aby živ byl?'),
(1567134,54,26,18,24,'Pakli by se odvrátil spravedlivý od spravedlnosti své, a činil by nepravost, čině podlé všech ohavností, kteréž činí bezbožný, takový-liž by živ byl? Na žádné spravedlnosti jeho, kteréž činil, nebude pamatováno. Pro přestoupení své, jehož se dopouštěl, a pro hřích svůj, kterýž páchal, pro tyť věci umře.'),
(1567135,54,26,18,25,'Že pak říkáte: Není pravá cesta Páně, poslyštež nyní, ó dome Izraelský: Zdali má cesta není pravá? Zdali nejsou cesty vaše nepravé?'),
(1567136,54,26,18,26,'Když by se odvrátil spravedlivý od spravedlnosti své, a čině nepravost, v tom by umřel, pro nepravost svou, kterouž činil, umře.'),
(1567137,54,26,18,27,'A když by se odvrátil bezbožný od bezbožnosti své, kterouž činil, a činil by soud a spravedlnost, tenť duši svou zachová při životu.'),
(1567138,54,26,18,28,'Nebo prohlédl, a odvrátil, se ode všech přestoupení svých, jichž se dopouštěl; jistě žeť živ bude a neumře.'),
(1567139,54,26,18,29,'A však vždy říká dům Izraelský: Není pravá cesta Páně. Zdali mé cesty nepravé jsou, ó dome Izraelský? Zdaliž nejsou cesty vaše nepravé?'),
(1567140,54,26,18,30,'A protož každého z vás podlé cest jeho souditi budu, ó dome Izraelský, dí Panovník Hospodin. Navraťtež se a odvraťte ode všech přestoupení svých, aby vám nebyla k úrazu nepravost.'),
(1567141,54,26,18,31,'Odvrzte od sebe všecka přestoupení vaše, jichž jste se dopouštěli, a učiňte sobě srdce nové a ducha nového. I pročež mřete, ó dome Izraelský?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567142,54,26,18,32,'Však nemám líbosti v smrti toho, jenž umírá, dí Panovník Hospodin. Obraťte se tedy, a živi buďte.'),
(1567143,54,26,19,1,'Ty pak vydej se v naříkání nad knížaty Izraelskými.'),
(1567144,54,26,19,2,'A rci: Co byla matka tvá? Lvice mezi lvy odpočívající, a u prostřed dravých lvů vychovávala lvíčátka svá.'),
(1567145,54,26,19,3,'A když odchovala jedno z lvíčat svých, udělal se z něho dravý lev, tak že naučiv se bráti loupeže, žrával lidi.'),
(1567146,54,26,19,4,'To když uslyšeli národové, v jámě jejich polapen jest, a doveden v řetězích do země Egyptské.'),
(1567147,54,26,19,5,'To viduc lvice, že očekávaná zhynula jí naděje její, vzavši jedno z lvíčat svých, učinila z něho silného lva;'),
(1567148,54,26,19,6,'Kterýž ustavičně chodě mezi lvy, udělal se dravým lvem, a naučiv se bráti loupeže, žrával lidi.'),
(1567149,54,26,19,7,'Pobořil i pusté paláce jejich, a města jejich v poušť uvedl, tak že spustla země, i což v ní bylo, od hlasu řvání jeho.'),
(1567150,54,26,19,8,'I polékli na něj národové z okolních krajin, a rozestřeli na něj tenata svá, a do jámy jejich lapen jest.'),
(1567151,54,26,19,9,'I dali jej do klece v řetězích, a dopravili ho k králi Babylonskému, a uvedli jej do vězení nejtěžšího, aby nebyl slýchán hlas jeho více po horách Izraelských.'),
(1567152,54,26,19,10,'Matka tvá v čas pokoje tvého jako vinný kmen při vodách štípený; plodistvý a rozkladitý byl pro hojnost vod.'),
(1567153,54,26,19,11,'A měl pruty mocné k berlám panovníků, zrůst pak jeho vyvýšil se nad prostředek hustého větvoví, tak že patrný byl pro svou vysokost a pro množství ratolestí svých.'),
(1567154,54,26,19,12,'Ale vytržen jsa v prchlivosti, na zemi povržen jest, a vítr východní usušil ovoce jeho; vylomily se a uschly ratolesti silné jeho, oheň sežral je.'),
(1567155,54,26,19,13,'A nyní štípen jest na poušti, v zemi vyprahlé a žíznivé.'),
(1567156,54,26,19,14,'Nadto vyšed oheň z prutu ratolestí jeho, sežral ovoce jeho, tak že není na něm prutu mocného k berle panovníka. Toť jest naříkání, a budeť v naříkání.'),
(1567157,54,26,20,1,'Tedy stalo se léta sedmého, a dne desátého, pátého měsíce, přišli někteří z starších Izraelských raditi se s Hospodinem, a posadili se přede mnou.'),
(1567158,54,26,20,2,'Tehdy stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567159,54,26,20,3,'Synu člověčí, mluv k starším Izraelským a rci jim: Takto praví Panovník Hospodin: Zdali, abyste se se mnou radili, vy přicházíte? Živ jsem já, že vy se neradíte se mnou, dí Panovník Hospodin.'),
(1567160,54,26,20,4,'Zdali jich zastávati budeš? Zdali zastávati budeš, synu člověčí? Oznam jim ohavnosti otců jejich,'),
(1567161,54,26,20,5,'A rci jim: Takto praví Panovník Hospodin: V ten den, v kterýž jsem zvolil Izraele, zdvihl jsem ruku svou semeni domu Jákobova, a v známost jsem se uvedl jim v zemi Egyptské; zdvihlť jsem jim ruku svou, řka: Já jsem Hospodin Bůh váš.'),
(1567162,54,26,20,6,'V ten den zdvihl jsem jim ruku svou, že je vyvedu z země Egyptské do země, kterouž jsem jim obhlédl, tekoucí mlékem a strdí, jenž jest okrasa všech jiných zemí.'),
(1567163,54,26,20,7,'A řekl jsem jim: Jeden každý ohavnosti očí svých zavrzte, a ukydanými bohy Egyptskými se nepoškvrňujte, nebo já jsem Hospodin Bůh váš.'),
(1567164,54,26,20,8,'Ale zpurně se postavovali proti mně, aniž mne chtěli slyšeti, aniž kdo ohavnosti očí svých zavrhl, a ukydaných bohů Egyptských nezanechali.Protož jsem řekl: Vyleji prchlivost svou na ně, a vyplním hněv svůj na nich u prostřed země Egyptské.'),
(1567165,54,26,20,9,'A však učinil jsem pro jméno své, aby nebylo zlehčeno před očima těch národů, mezi nimiž byli, před jejichž očima jsem se jim v známost uvedl, že je chci vyvesti z země Egyptské.'),
(1567166,54,26,20,10,'Takž jsem je vyvedl z země Egyptské, a přivedl jsem je na poušť,'),
(1567167,54,26,20,11,'A dal jsem jim ustanovení svá, a soudy své v známost jsem jim uvedl, ješto činil-li by je kdo, jistě že by živ byl skrze ně.'),
(1567168,54,26,20,12,'Nadto i soboty své vydal jsem jim, aby byly na znamení mezi mnou a mezi nimi, aby znali, že já Hospodin jsem posvětitel jejich.'),
(1567169,54,26,20,13,'Ale dům Izraelský zpurně se postavovali proti mně na poušti, v ustanoveních mých nechodili, a soudy mými pohrdli, ješto činil-li by je kdo, jistě že by živ byl skrze ně; též soboty mé poškvrnili náramně. Pročež jsem řekl: Že vyleji prchlivost svou na ně na poušti, abych je docela vyhladil.'),
(1567170,54,26,20,14,'Ale učinil jsem pro jméno své, aby nebylo zlehčeno před očima těch národů, před jejichž očima jsem je vyvedl.'),
(1567171,54,26,20,15,'A však i já také přisáhl jsem jim na té poušti, že jich neuvedu do země, kterouž jsem byl dal, tekoucí mlékem a strdí, jenž jest okrasa všech jiných zemí,'),
(1567172,54,26,20,16,'Proto že soudy mými pohrdli, a v ustanoveních mých nechodili, a soboty mé poškvrnili, a že za ukydanými bohy jejich srdce jejich chodí.'),
(1567173,54,26,20,17,'Však odpustilo jim oko mé, tak že jsem jich nezahladil, a neučinil jim konce na poušti.'),
(1567174,54,26,20,18,'A řekl jsem synům jejich na též poušti: V ustanoveních otců svých nechoďte, a soudů jejich neostříhejte, a ukydanými bohy jejich se nepoškvrňujte.'),
(1567175,54,26,20,19,'Já jsem Hospodin Bůh váš, v ustanoveních mých choďte, a soudů mých ostříhejte, a čiňte je.'),
(1567176,54,26,20,20,'Též soboty mé svěťte, i budou na znamení mezi mnou a vámi, aby známé bylo, že já jsem Hospodin Bůh váš.'),
(1567177,54,26,20,21,'Ale zpurně se měli ke mně ti synové, v ustanoveních mých nechodili, a soudů mých nešetřili, aby je činili, (ješto činil-li by je kdo, jistě že by živ byl skrze ně), i soboty mé poškvrnili. I řekl jsem: Že vyleji prchlivost svou na ně, abych vyplnil hněv svůj na nich na té poušti.'),
(1567178,54,26,20,22,'Ale odvrátil jsem zase ruku svou; což jsem učinil pro jméno své, aby nebylo zlehčeno před očima těch národů, před jejichž očima jsem je vyvedl.'),
(1567179,54,26,20,23,'Také i těm přisáhl jsem na poušti, že je rozptýlím mezi pohany, a že je rozženu po krajinách,'),
(1567180,54,26,20,24,'Proto že soudů mých nečinili, a ustanoveními mými pohrdli, a soboty mé poškvrnili, a že k ukydaným bohům otců svých zření měli.'),
(1567181,54,26,20,25,'Pročež já také dal jsem jim ustanovení nedobrá, a soudy, skrze něž nebudou živi.'),
(1567182,54,26,20,26,'A poškvrnil jsem jich s jejich dary, (proto že provodili všecko, což otvírá život), abych je zkazil, aby poznali, že já jsem Hospodin.'),
(1567183,54,26,20,27,'Protož mluv k domu Izraelskému, synu člověčí, a rci jim: Takto praví Panovník Hospodin: Ještě i tímto rouhali se mi otcové vaši, dopouštějíce se proti mně přestoupení,'),
(1567184,54,26,20,28,'Že, když jsem je uvedl do země, o kteréž jsem přisáhl, že jim ji dám, kdež spatřili který pahrbek vysoký, aneb které dřevo husté, hned tu obětovali oběti své, a tu dávali popouzející dary své, tu kladli i vůni svou příjemnou, a tu obětovali mokré oběti své.'),
(1567185,54,26,20,29,'A ačkoli jsem říkal jim: Což jest ta výsost, kamž vy chodíváte? ale ona slove výsostí až do tohoto dne.'),
(1567186,54,26,20,30,'Protož rci domu Izraelskému: Takto praví Panovník Hospodin: Cestou-liž otců vašich vy se máte poškvrňovati, a s ohavnostmi jejich máte smilniti?'),
(1567187,54,26,20,31,'Též přinášejíce dary své, vodíce syny své skrze oheň, máte-liž se poškvrňovati při všech ukydaných bozích vašich až do tohoto dne, a ode mne vždy rady hledati, ó dome Izraelský? Živť jsem já, dí Panovník Hospodin, že vy se nebudete mne více raditi.'),
(1567188,54,26,20,32,'To pak, což jste sobě v mysli uložili, nikoli se nestane, že říkáte: Budeme jako jiní národové, jako čeledi jiných zemí, sloužíce dřevu a kameni.'),
(1567189,54,26,20,33,'Živ jsem já, praví Panovník Hospodin, že rukou silnou a ramenem vztaženým, a prchlivostí vylitou kralovati budu nad vámi.'),
(1567190,54,26,20,34,'Vyvedu vás zajisté z národů, a shromáždím vás z zemí, do nichž jste rozptýleni, rukou silnou a ramenem vztaženým, i prchlivostí vylitou.'),
(1567191,54,26,20,35,'A vodě vás po poušti těch národů, souditi se budu s vámi tam tváří v tvář.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567192,54,26,20,36,'Tak jako jsem se soudil s otci vašimi na poušti země Egyptské, tak se budu souditi s vámi, praví Panovník Hospodin.'),
(1567193,54,26,20,37,'A proženu vás pod hůl, abych vás uvedl do závazku smlouvy.'),
(1567194,54,26,20,38,'Ale ty, jenž se mi zprotivili a zpronevěřili, vymísím z vás; z země, v níž pohostinu jsou, vyvedu je, do země však Izraelské nevejdou. I zvíte, že já jsem Hospodin.'),
(1567195,54,26,20,39,'Vy tedy, ó dome Izraelský, takto praví Panovník Hospodin: Jdětež, služte každý ukydaným bohům svým i napotom, poněvadž neposloucháte mne, a jména mého svatého nepoškvrňujte více dary svými, a ukydanými bohy svými.'),
(1567196,54,26,20,40,'Nebo na hoře mé svaté, na hoře vysoké Izraelské, dí Panovník Hospodin, tam mi sloužiti budou všecken dům Izraelský, což jich koli bude v té zemi. Tam je laskavě přijmu, a tam vyhledávati budu od vás obětí vzhůru pozdvižení i prvotin darů vašich, se všemi svatými věcmi vašimi.'),
(1567197,54,26,20,41,'S vůní libou laskavě vás přijmu, když vás vyvedu z národů, a shromáždím vás z těch zemí, do nichž jste rozptýleni byli, a tak posvěcen budu v vás před očima těch národů.'),
(1567198,54,26,20,42,'I poznáte, že já jsem Hospodin, když vás uvedu do země Izraelské, do země té, o kteréž jsem přisáhl, že ji dám otcům vašim.'),
(1567199,54,26,20,43,'A tu se rozpomenete na cesty své a na všecky činy své, jimiž jste se poškvrňovali, tak že sami se býti hodné ošklivosti uznáte, pro všecky nešlechetnosti vaše, kteréž jste činívali.'),
(1567200,54,26,20,44,'Tu poznáte, že já jsem Hospodin, když vám to učiním pro jméno své, ne podlé cest vašich zlých, ani podlé činů vašich porušených, dome Izraelský, praví Panovník Hospodin.'),
(1567201,54,26,20,45,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567202,54,26,20,46,'Synu člověčí, obrať tvář svou k straně polední, a vypusť jako rosu na poledne, a prorokuj proti lesu toho pole, kteréž jest na poledne.'),
(1567203,54,26,20,47,'A rci lesu polednímu: Slyš slovo Hospodinovo: Takto praví Panovník Hospodin: Aj, já zanítím v tobě oheň, kterýž sežere v tobě každé dřevo zelené i každé dřevo suché; nezhasneť plamen přeprudký, a budou jím opáleny všecky tváře od poledne až na půlnoci.'),
(1567204,54,26,20,48,'I uzří všeliké tělo, že jsem já Hospodin zapálil jej; nezhasneť.'),
(1567205,54,26,20,49,'I řekl jsem: Ach, Panovníče Hospodine, oni mi říkají: Však tento v přísloví nám toliko mluví.'),
(1567206,54,26,21,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567207,54,26,21,2,'Synu člověčí, obrať tvář svou k Jeruzalému, a vypusť jako rosu proti místům svatým, a prorokuj proti zemi Izraelské.'),
(1567208,54,26,21,3,'A rci zemi Izraelské: Takto praví Hospodin: Aj, já jsem proti tobě, a vytáhnu meč svůj z pošvy jeho, a vypléním z tebe spravedlivého i bezbožného.'),
(1567209,54,26,21,4,'Proto, abych vyplénil z tebe spravedlivého i bezbožného, proto vyjde meč můj z pošvy své proti všelikému tělu, od poledne až na půlnoci.'),
(1567210,54,26,21,5,'I zvíť všeliké tělo, že jsem já Hospodin vytáhl meč svůj z pošvy jeho; nenavrátíť se zase více.'),
(1567211,54,26,21,6,'Ty pak synu člověčí, vzdychej, jako bys zlámaná měl bedra, a to s hořekováním vzdychej před očima jejich.'),
(1567212,54,26,21,7,'I stane se, žeť řeknou: Nad čím ty vzdycháš? Tedy řekneš: Nad pověstí, kteráž přichází, k níž rozplyne se každé srdce, a každé ruce klesnou, a všeliký duch skormoutí se, a každá kolena rozplynou se jako voda. Aj, přicházíť a děje se, praví Panovník Hospodin.'),
(1567213,54,26,21,8,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567214,54,26,21,9,'Synu člověčí, prorokuj a rci: Takto praví Hospodin: Rci: Meč, meč nabroušen, také i vyčištěn jest.'),
(1567215,54,26,21,10,'Aby zabíjel k zabití oddané, nabroušen jest; aby se blyštěl, vyčištěn jest. Radovati-liž se budeme, když prut syna mého pohrdá každým dřevem?'),
(1567216,54,26,21,11,'Dalť jej vyčistiti, aby v ruku vzat byl; jestiť nabroušený meč, jest i vyčištěný, aby dán byl do ruky mordujícího.'),
(1567217,54,26,21,12,'Křič a kvěl, synu člověčí, proto že ten bude proti lidu mému, tentýž proti všechněm knížatům Izraelským; uvrženi budou na meč s lidem mým, protož bí se v bedra.'),
(1567218,54,26,21,13,'Když jsem je trestával, co bylo? Nemám-liž metly hubící již přičiniti? dí Hospodin zástupů.'),
(1567219,54,26,21,14,'Ty tedy synu člověčí, prorokuj a tleskej rukama; nebo po druhé i po třetí přijde meč, meč mordujících, ten meč mordujících bez lítosti, pronikajících i do pokojů jejich.'),
(1567220,54,26,21,15,'Tak aby se rozplynulo srdce, a rozmnoženi byli úrazové, v každé bráně jejich postavím ostří meče. Ach, vyčištěnť jest, aby se blyštěl, zaostřen, aby zabíjel.'),
(1567221,54,26,21,16,'Shlukni se a pusť se na pravo i na levo, kamžkoli a načkoli se tobě nahodí.'),
(1567222,54,26,21,17,'I jáť také tleskati budu rukama svýma, a doložím prchlivost svou. Já Hospodin mluvil jsem.'),
(1567223,54,26,21,18,'V tom stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567224,54,26,21,19,'Ty pak synu člověčí, předlož sobě dvě cesty, kudy by jíti měl meč krále Babylonského. Z země jedné ať vycházejí obě dvě, a na rozcestí vybeř tu k městu, tu vybeř.'),
(1567225,54,26,21,20,'Ukaž cestu, kudy by jíti měl meč, k Rabbat-li synů Ammon, čili k Judstvu, na Jeruzalémské pevnosti,'),
(1567226,54,26,21,21,'Proto že stane král Babylonský na rozcestí, na počátku dvou cest, obíraje se s hádáním, vyčistí střely, doptávati se bude modl, hleděti bude do jater.'),
(1567227,54,26,21,22,'Po pravé ruce jeho hádání ukáže Jeruzalém, aby sšikoval hejtmany, kteříž by ponoukali k mordování, a pozdvihovali hlasu s prokřikováním, aby přistavili berany válečné proti branám, aby vysypán byl násyp, a vzdělání byli šancové.'),
(1567228,54,26,21,23,'I budou to míti za hádání marné před očima svýma ti, jenž se zavázali přísahami; a toť přivede na pamět nepravost, kterouž by popadeni byli.'),
(1567229,54,26,21,24,'Protož takto praví Panovník Hospodin: Proto že ku paměti přivodíte nepravost svou, a odkrývá se nevěra vaše, tak že jsou patrní hříchové vaši ve všech činech vašich, proto že na pamět přicházíte, rukou tou popadeni budete.'),
(1567230,54,26,21,25,'Ty pak nečistý bezbožníče, kníže Izraelské, jehož den přichází, a čas skonání nepravosti,'),
(1567231,54,26,21,26,'Takto praví Panovník Hospodin: Sejmi tu čepici, a svrz tu korunu, kteráž nikdy již taková nebude; toho, kterýž na snížení přišel, povyš, a vyvýšeného poniž.'),
(1567232,54,26,21,27,'Zmotanou, zmotanou, zmotanou učiním ji, (čehož prvé nebývalo), až přijde ten, jenž má právo, kteréž jsem jemu dal.'),
(1567233,54,26,21,28,'Ty pak synu člověčí, prorokuj a rci: Takto praví Panovník Hospodin o synech Ammon, i o pohanění jejich, rci, pravím: Meč, meč dobyt jest, k zabíjení vyčištěn jest, aby hubil všecko, a aby se blyštěl.'),
(1567234,54,26,21,29,'A ačkoli předpovídají tobě marné věci, a hádají tobě lež, aby tě přiložili k hrdlům zbitých bezbožníků, jejichž den přichází a čas skonání nepravosti:'),
(1567235,54,26,21,30,'Schovej meč do pošvy jeho. Na místě, na kterémž jsi zplozena, v zemi přebývání tvého, budu tě souditi.'),
(1567236,54,26,21,31,'A vyleji na tě rozhněvání své, ohněm prchlivosti své na tě dmýchati budu, a dám tě v ruku lidí vzteklých, řemeslníků všecko kazících.'),
(1567237,54,26,21,32,'Budeš ohni k sežrání, krev tvá bude u prostřed země, nebudeš připomínána; neboť jsem já Hospodin mluvil.'),
(1567238,54,26,22,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567239,54,26,22,2,'Ty pak synu člověčí, zastával-li bys, zastával-liž bys toho města vražedlného? Raději mu oznam všecky ohavnosti jeho,'),
(1567240,54,26,22,3,'A rci: Takto praví Panovník Hospodin: Přicházíť čas města toho, jenž prolévá krev u prostřed sebe, a dělá ukydané bohy proti sobě, aby se poškvrňovalo.'),
(1567241,54,26,22,4,'Ty krví svou, kterouž jsi prolilo, zavinivší, a ukydanými bohy svými, jichž jsi nadělalo, sebe poškvrnivší, to jsi způsobilo, že se přiblížili dnové tvoji, a přišlo jsi k letům svým. Protož vydám tě v pohanění národům, a ku posměchu všechněm zemím.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567242,54,26,22,5,'Blízké i daleké od tebe budou se tobě posmívati, ó zlopověstné a různic plné.'),
(1567243,54,26,22,6,'Aj, knížata Izraelská jeden každý vší silou na to se vydali, aby krev v tobě prolévali.'),
(1567244,54,26,22,7,'Otce i matku zlehčují v tobě, pohostinnému činí nátisk u prostřed tebe, sirotka a vdovu utiskují v tobě.'),
(1567245,54,26,22,8,'Svatými věcmi mými zhrdáš, a sobot mých poškvrňuješ.'),
(1567246,54,26,22,9,'Utrhači jsou v tobě, aby prolévali krev, a na horách jídají v tobě; nešlechetnost páší u prostřed tebe.'),
(1567247,54,26,22,10,'Nahotu otce syn odkrývá v tobě, a nečisté v oddělení ponižují v tobě.'),
(1567248,54,26,22,11,'Jiný pak s ženou bližního svého páše ohavnost, a jiný s nevěstou svou poškvrňuje se nešlechetností, a jiný sestry své, dcery otce svého, ponižuje v tobě.'),
(1567249,54,26,22,12,'Dar berou v tobě, aby krev prolili; lichvu a úrok béřeš, a zisku hledáš s útiskem bližního svého, na mne se pak zapomínáš, dí Panovník Hospodin.'),
(1567250,54,26,22,13,'Protož aj, já tleskl jsem rukama svýma nad ziskem tvým, jehož dobýváš, i nad tou krví, kteráž byla u prostřed tebe.'),
(1567251,54,26,22,14,'Zdali ostojí srdce tvé? Zdaž odolají ruce tvé dnům, v nichž já budu zacházeti s tebou? Já Hospodin mluvil jsem i učiním.'),
(1567252,54,26,22,15,'Nebo rozptýlím tě mezi pohany, a rozženu tě po krajinách, a do konce vyprázdním nečistotu tvou z tebe.'),
(1567253,54,26,22,16,'A zavrženo jsuc před očima pohanů, poznáš, že já jsem Hospodin.'),
(1567254,54,26,22,17,'Potom stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567255,54,26,22,18,'Synu člověčí, obrátili se mi dům Izraelský v trůsku, všickni napořád jsou měď, cín, železo a olovo u prostřed peci, trůsky stříbra jsou.'),
(1567256,54,26,22,19,'Pročež takto praví Panovník Hospodin: Proto že jste vy všickni obrátili se v trůsky, protož aj, já shromáždím vás do Jeruzaléma.'),
(1567257,54,26,22,20,'Jakž se shromažďuje stříbro a měď, železo, olovo i cín do prostřed peci, k rozdmýchání ohně vůkol něho a k rozpouštění: tak shromáždím v hněvě a v prchlivosti své, a slože, rozpouštěti vás budu.'),
(1567258,54,26,22,21,'Sberu vás, pravím, a rozdmýchám okolo vás oheň prchlivosti své, i rozpustíte se u prostřed města.'),
(1567259,54,26,22,22,'Jakž se stříbro rozpouští v peci, tak se rozpustíte u prostřed něho, i zvíte, že já Hospodin vylil jsem prchlivost svou na vás.'),
(1567260,54,26,22,23,'Ještě stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567261,54,26,22,24,'Synu člověčí, rci: Ty země jsi nečistá, nebudeš deštěm svlažena v den rozhněvání.'),
(1567262,54,26,22,25,'Spiknutí proroků jejích u prostřed ní, jsou podobni lvu řvoucímu, uchvacujícímu loupež, duše žerou, bohatství a věci drahé berou, a činí mnoho vdov u prostřed ní.'),
(1567263,54,26,22,26,'Kněží její natahují zákona mého, a svaté věci mé poškvrňují, mezi svatým a poškvrněným rozdílu nečiní, a mezi nečistým a čistým nerozeznávají. Nadto od sobot mých skrývají oči své, tak že zlehčován bývám mezi nimi.'),
(1567264,54,26,22,27,'Knížata její u prostřed ní jsou jako vlci uchvacující loupež, vylévajíce krev, hubíce duše, aby sháněli mrzký zisk.'),
(1567265,54,26,22,28,'Proroci pak jejich obmítají jim vápnem ničemným, předpovídají marné věci, a hádají jim lež, říkajíce: Takto praví Panovník Hospodin, ješto Hospodin nemluvil.'),
(1567266,54,26,22,29,'Lid této země činí nátisk, a cizí věci mocí béře, chudému a nuznému ubližují, a pohostinného utiskují nespravedlivě.'),
(1567267,54,26,22,30,'Hledaje pak někoho z nich, kterýž by udělal hradbu, a postavil se v mezeře před tváří mou za tuto zemi, abych jí nezkazil, žádného nenacházím.'),
(1567268,54,26,22,31,'Protož vyleji na ně rozhněvání své, ohněm prchlivosti své konec jim učiním, cestu jejich jim na hlavu obrátím, praví Panovník Hospodin.'),
(1567269,54,26,23,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567270,54,26,23,2,'Synu člověčí, dvě ženy, dcery jedné mateře byly.'),
(1567271,54,26,23,3,'Ty smilnily v Egyptě, v mladosti své smilnily. Tam jsou mačkány prsy jejich, tam opiplány prsy panenství jejich.'),
(1567272,54,26,23,4,'Jména pak jejich: větší Ahola, sestry pak její Aholiba. Tyť jsou byly mé, a rozplodily syny a dcery. Jména, pravím, jejich jsou: Samaří Ahola, Jeruzaléma pak Aholiba.'),
(1567273,54,26,23,5,'Ale Ahola maje mne, smilnila a frejů hleděla s milovníky svými, s Assyrskými blízkými,'),
(1567274,54,26,23,6,'Oděnými postavcem modrým, s vývodami a knížaty, i všemi napořád mládenci krásnými, a s jezdci jezdícími na koních.'),
(1567275,54,26,23,7,'Vydala se, pravím, v smilství svá s nimi, se všemi nejpřednějšími syny Assyrskými, a se všemi, jimž frejovala, a poškvrnila se všemi ukydanými bohy jejich.'),
(1567276,54,26,23,8,'A tak smilství svých Egyptských nenechala; nebo ji zléhali v mladosti její, a oni mačkali prsy panenství jejího, a vylili smilství svá na ni.'),
(1567277,54,26,23,9,'Protož dal jsem ji v ruku frejířů jejích, v ruku Assyrských, jimž frejovala.'),
(1567278,54,26,23,10,'Oniť jsou odkryli nahotu její, syny i dcery její pobrali, ji pak samu mečem zamordovali. Takž vzata jest na slovo od jiných žen, když soudy vykonali při ní.'),
(1567279,54,26,23,11,'To viděla sestra její Aholiba, však mnohem více než onano frejovala, a smilství její větší byla než smilství sestry její.'),
(1567280,54,26,23,12,'S Assyrskými frejů hleděla, s vývodami a knížaty blízkými, oděnými nádherně, s jezdci jezdícími na koních, a všemi mládenci krásnými.'),
(1567281,54,26,23,13,'I viděl jsem, že se poškvrnila, a že cesta jednostejná jest obou dvou.'),
(1567282,54,26,23,14,'Ale tato ještě to přičinila k smilstvím svým, že viduc muže vyryté na stěně, obrazy Kaldejských vymalované barvou,'),
(1567283,54,26,23,15,'Přepásané pasem po bedrách jejich, a klobouky barevné na hlavách jejich, a že jsou všickni na pohledění jako hejtmané, podobní synům Babylonským v Kaldejské zemi, jejichž ona vlast jest,'),
(1567284,54,26,23,16,'I zahořela k nim z pohledění očima svýma, a vyslala posly k nim do země Kaldejské.'),
(1567285,54,26,23,17,'Tedy vešli k ní Babylonští na lůže nepoctivé, a poškvrnili ji smilstvím svým. A když se poškvrnila s nimi, odloučila se duše její od nich.'),
(1567286,54,26,23,18,'A odkryla smilství svá, odkryla též nahotu svou, i odloučila se duše má od ní, tak jako se odloučila duše má od sestry její.'),
(1567287,54,26,23,19,'Nebo rozmnožila smilství svá, rozpomínajíc se na dny mladosti své, v nichž smilnila v zemi Egyptské,'),
(1567288,54,26,23,20,'A frejovala s kuběnáři jejich, jejichž tělo jest jako tělo oslů, a tok jejich jako tok koňský.'),
(1567289,54,26,23,21,'A tak jsi zase navrátila se k nešlechetnosti mladosti své, když mačkali Egyptští prsy tvé z příčiny prsů mladosti tvé.'),
(1567290,54,26,23,22,'Protož ó Aholiba, takto praví Panovník Hospodin: Aj, já vzbudím frejíře tvé proti tobě, ty, od nichž se odloučila duše tvá, a přivedu je na tě odevšad,'),
(1567291,54,26,23,23,'Babylonské a všecky Kaldejské, Pekodské, a Šohejské, i Kohejské, všecky syny Assyrské s nimi, mládence krásné, vývody a knížata všecka, hejtmany a slovoutné, všecky jezdící na koních.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567292,54,26,23,24,'A přitáhnou na tě na vozích železných a přikrytých, i kárách, a to s zběří národů, s pavézami a štíty i lebkami, položí se proti tobě vůkol, i předložím jim právo, aby tě soudili soudy svými.'),
(1567293,54,26,23,25,'Vyleji zajisté horlení své na tebe, tak že naloží s tebou prchlivě, nos tvůj i uši tvé odejmou, a ostatek tebe mečem padne. Ti syny tvé i dcery tvé poberou, a ostatek tebe spáleno bude ohněm.'),
(1567294,54,26,23,26,'A vyvlekou tě z roucha tvého, a rozberou šperky okrasy tvé.'),
(1567295,54,26,23,27,'A tak přítrž učiním při tobě nešlechetnosti tvé, i smilství tvému z země Egyptské vzatému, a nepozdvihneš očí svých k nim, a na Egypt nezpomeneš více.'),
(1567296,54,26,23,28,'Nebo takto praví Panovník Hospodin: Aj, já dám tebe v ruku těch, kterýchž nenávidíš, v ruku těch, od nichž se odloučila duše tvá,'),
(1567297,54,26,23,29,'I budou nakládati s tebou podlé nenávisti, a poberou všecko úsilé tvé, a nechají tě nahé a obnažené. A tak bude zřejmá nahota smilství tvého a nešlechetnosti tvé, smilství, pravím, tvého.'),
(1567298,54,26,23,30,'Což vše učiní tobě proto, že jsi smilnila, následujíc pohanů, proto že jsi poškvrnila se ukydanými bohy jejich.'),
(1567299,54,26,23,31,'Cestou sestry své chodila jsi, protož dám kalich její v ruku tvou.'),
(1567300,54,26,23,32,'Takto praví Panovník Hospodin: Kalich sestry své píti budeš hluboký a široký; budeť sporý, tak že smích a žert budou míti z tebe.'),
(1567301,54,26,23,33,'Opilstvím a zámutkem naplněna budeš, kalichem pustiny a zpuštění, kalichem sestry své Samaří.'),
(1567302,54,26,23,34,'I vypiješ jej a vyvážíš, a než jej polámeš, snáze prsy své roztrháš; neboť jsem já mluvil, praví Panovník Hospodin.'),
(1567303,54,26,23,35,'Protož takto praví Panovník Hospodin: Z té příčiny, že jsi zapomenula na mne, a zavrhlas mne za hřbet svůj, i ty také vezmi za svou nešlechetnost, a za smilství svá.'),
(1567304,54,26,23,36,'I řekl Hospodin ke mně: Synu člověčí, budeš-liž zastávati Ahole neb Aholiby? Nýbrž oznam jim ohavnosti jejich,'),
(1567305,54,26,23,37,'Že cizoložily, a krev jest na rukou jejich, a s ukydanými bohy svými cizoložily. Také i syny své, kteréž mně zplodily, vodily jim, aby sežráni byli.'),
(1567306,54,26,23,38,'Ještě i toto činily mi, že zanečišťovaly svatyni mou v tentýž den, a sobot mých poškvrňovaly.'),
(1567307,54,26,23,39,'Nebo obětovavše syny své ukydaným bohům svým, vcházely do svatyně mé v tentýž den, aby ji poškvrnily. Aj hle, takť jsou činívaly u prostřed mého domu.'),
(1567308,54,26,23,40,'Nadto, že vysílaly k mužům, jenž by přišli zdaleka, kteříž, jakž posel vyslán k nim, aj, hned přicházívali. Jimž jsi se umývala, a tvář svou líčila, a okrašlovalas se okrasou.'),
(1567309,54,26,23,41,'A usazovalas se na loži slavném, před nímž stůl připravený byl, na něž jsi i kadidlo mé i masti mé vynakládala.'),
(1567310,54,26,23,42,'Když pak hlas toho množství poutichl, tedy i k mužům z obecného lidu vysílaly, jenž bývali přivozováni ožralí z pouště. I dávali náramky na ruce jejich, i koruny ozdobné na hlavy jejich.'),
(1567311,54,26,23,43,'A ačkoli jsem se domlouval na cizoložství té lotryně, a že oni jednak s jednou, jednak s druhou smilství provodí,'),
(1567312,54,26,23,44,'A že každý z nich vchází k ní, tak jako někdo vchází k ženě nevěstce: však vždy vcházeli k Ahole a Aholibě, ženám přenešlechetným.'),
(1567313,54,26,23,45,'Protož muži spravedliví, tiť je souditi budou soudem cizoložných a soudem těch, jenž vylévaly krev, proto že cizoložily, a krev jest na rukou jejich.'),
(1567314,54,26,23,46,'Nebo takto praví Panovník Hospodin: Přivedu na ně vojsko, a dám je v posmýkání i v loupež.'),
(1567315,54,26,23,47,'I uhází je to shromáždění kamením, a poseká je meči svými; syny jejich i dcery jejich pomordují, a domy jejich ohněm popálí.'),
(1567316,54,26,23,48,'A tak přítrž učiním nešlechetnosti v zemi této, i budou se tím káti všecky ženy, a nedopustí se nešlechetnosti podobné vaší.'),
(1567317,54,26,23,49,'Nebo vzložena bude na vás nešlechetnost vaše, a ponesete hříchy ukydaných bohů svých. I zvíte, že já jsem Panovník Hospodin.'),
(1567318,54,26,24,1,'Opět stalo se slovo Hospodinovo ke mně léta devátého, měsíce desátého, desátého dne téhož měsíce, řkoucí:'),
(1567319,54,26,24,2,'Synu člověčí, napiš sobě jméno tohoto dne, vlastně dnešního dne tohoto: nebo oblehl král Babylonský Jeruzalém právě tohoto dnešního dne.'),
(1567320,54,26,24,3,'A předlož tomu domu zpurnému podobenství, řka k nim: Takto praví Panovník Hospodin: Přistav tento hrnec, přistav a nalej také do něho vody.'),
(1567321,54,26,24,4,'A sebera kusy náležité do něho, každý kus dobrý, stehno i plece, a nejlepšími kostmi napln jej.'),
(1567322,54,26,24,5,'Přivezmi i nejlepších bravů, a udělej oheň z kostí pod ním, způsob, ať to vře, ažby kypělo, ať se i kosti jeho rozvaří v něm.'),
(1567323,54,26,24,6,'Protož takto praví Panovník Hospodin: Běda městu tomu vražedlnému, hrnci, v němž zůstává připálenina jeho, z něhož, pravím, připálenina jeho nevychází. Po kusích, po kusích vytahuj z něho, nepadneť na něj los.'),
(1567324,54,26,24,7,'Nebo krev jest u prostřed něho. Na vysedlou skálu vystavilo ji; nevylilo jí na zemi, aby ji prach přikryl.'),
(1567325,54,26,24,8,'I já zanítě prchlivost k vykonání pomsty, vystavím krev na vysedlou skálu, aby nebyla přikryta.'),
(1567326,54,26,24,9,'Protož takto praví Panovník Hospodin: Běda městu vražedlnému, i já udělám veliký oheň,'),
(1567327,54,26,24,10,'Přikládaje dříví, rozněcuje oheň, v nic obraceje maso, a kořeně kořením, tak že i kosti spáleny budou.'),
(1567328,54,26,24,11,'A postavím ten hrnec na uhlí jeho prázdný, aby se zhřela i rozpálila měď jeho, ažby se vyvařila u prostřed něho nečistota jeho, a vyprázdnila připálenina jeho.'),
(1567329,54,26,24,12,'Klamy svými bylo mi těžké, protož nevyjde z něho množství šumu jeho; do ohně musí šum jeho.'),
(1567330,54,26,24,13,'V tvé nečistotě jest nešlechetnost, proto že jsem tě očišťoval, však nejsi očištěno. Nebudeš více očišťováno od nečistoty své, až i doložím prchlivost svou na tebe.'),
(1567331,54,26,24,14,'Já Hospodin mluvil jsem, dojdeť, a učiním to; neustoupímť, aniž se slituji, ani želeti budu. Podlé cest tvých a činů tvých budou tě souditi, praví Panovník Hospodin.'),
(1567332,54,26,24,15,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567333,54,26,24,16,'Synu člověčí, aj, já odejmu od tebe žádost očí tvých v náhle, však nekvěl ani plač, a nechť nevycházejí slzy tvé.'),
(1567334,54,26,24,17,'Stonati přestaň, smutku, jakž bývá nad mrtvým, nenes, klobouk svůj vstav na sebe, a střevíce své obuj na nohy své, a nezastírej brady své, aniž pokrmu čího jez.'),
(1567335,54,26,24,18,'Což když jsem pověděl lidu ráno, tedy umřela žena má u večer. I učinil jsem na ráno, jakž mi rozkázáno bylo.'),
(1567336,54,26,24,19,'I řekl ke mně lid: Což nám neoznámíš, co tyto věci nám znamenají, kteréž činíš?'),
(1567337,54,26,24,20,'Tedy řekl jsem jim: Slovo Hospodinovo stalo se ke mně, řkoucí:'),
(1567338,54,26,24,21,'Rci domu Izraelskému: Takto praví Panovník Hospodin: Aj, já poškvrním svatyně své, vyvýšenosti síly vaší, žádosti očí vašich a toho, čehož šanuje duše vaše. Též synové vaši i dcery vaše, kterýchž jste zanechali, mečem padnou.'),
(1567339,54,26,24,22,'I budete tak činiti, jakž já činím. Brady nezastřete, aniž čího pokrmu jísti budete.'),
(1567340,54,26,24,23,'A majíce klobouky své na hlavách svých a střevíce na nohách svých, nebudete kvíliti ani plakati, ale svadnouce pro nepravosti své, úpěti budete jeden s druhým.'),
(1567341,54,26,24,24,'Nebo jest vám Ezechiel zázrakem. Všecko, což on činí, budete činiti, a když to přijde, tedy zvíte, že já jsem Panovník Hospodin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567342,54,26,24,25,'Ty pak synu člověčí, zdali v ten den, když já odejmu od nich sílu jejich, veselé okrasy jejich, žádost očí jejich, a to, po čemž touží duše jejich, syny jejich i dcery jejich,'),
(1567343,54,26,24,26,'Zdali v ten den přijde k tobě ten, kdož uteče, vypravuje tu novinu?'),
(1567344,54,26,24,27,'V ten den otevrou se ústa tvá při přítomnosti toho, kterýž ušel, i budeš mluviti, a nebudeš více němým. Takž jim budeš zázrakem, i zvědí, že já jsem Hospodin.'),
(1567345,54,26,25,1,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567346,54,26,25,2,'Synu člověčí, obrať tvář svou proti synům Ammon, a prorokuj proti nim.'),
(1567347,54,26,25,3,'A rci synům Ammon: Slyšte slovo Panovníka Hospodina: Takto praví Panovník Hospodin: Proto že jsi nad svatyní mou, když poškvrněna byla, říkal: To dobře to, a nad zemí Izraelskou, když zpuštěna byla, a nad domem Judským, když šel v zajetí,'),
(1567348,54,26,25,4,'Protož aj, já dám tě národům východním za dědictví, i vzdělají sobě hrady v tobě, a vystavějí v tobě příbytky své. Tiť budou jísti ovoce tvé, a ti budou píti mléko tvé.'),
(1567349,54,26,25,5,'A dám Rabbu za obydlé velbloudům, a města synů Ammon za odpočivadlo stádům, i zvíte, že já jsem Hospodin.'),
(1567350,54,26,25,6,'Nebo takto praví Panovník Hospodin: Proto že jsi tleskal rukou, a dupal nohou, a veselil se srdečně, že jsi všelijak loupil zemi Izraelskou,'),
(1567351,54,26,25,7,'Protož aj, já vztáhnu ruku svou na tebe, a vydám tě v loupež národům, a vypléním tě z lidí, a vyhubím tě z zemí, i zahladím tě. Tu zvíš, že já jsem Hospodin.'),
(1567352,54,26,25,8,'Takto praví Panovník Hospodin: Z té příčiny, že říkal Moáb a Seir: Hle, podobný jest všechněm jiným národům dům Judský,'),
(1567353,54,26,25,9,'Protož aj, já otevru bok Moábských, (hned od Arim, od měst jejich na pomezí jejich, rozkošnou zemi Betjesimotských, Balmeonských i Kariataimských),'),
(1567354,54,26,25,10,'Národům východním s zemí synů Ammon; nebo jsem ji dal v dědictví, tak aby nebylo zpomínáno na syny Ammon mezi národy.'),
(1567355,54,26,25,11,'A tak i nad Moábem soudy vykonám, i zvědí, že já jsem Hospodin.'),
(1567356,54,26,25,12,'Takto praví Panovník Hospodin: Proto že Idumejští nenáležitě se vymstívajíce, ukrutně se měli k domu Judskému, a tak uvodili na se vinu velikou, vymstívajíce se na nich,'),
(1567357,54,26,25,13,'Protož takto dí Panovník Hospodin: I na Idumea vztáhnu ruku svou, a vypléním z něho lidi i hovada, a obrátím jej v pustinu. Hned od Teman až do Dedan mečem padati budou.'),
(1567358,54,26,25,14,'A tak uvedu pomstu svou na Idumejské skrze ruku lidu mého Izraelského, a naloží s Idumejskými podlé hněvu mého a podlé prchlivosti mé, i poznají pomstu mou, praví Panovník Hospodin.'),
(1567359,54,26,25,15,'Takto praví Panovník Hospodin: Proto že se Filistinští ukrutně měli z příčiny pomsty, nenáležitě se vymstívajíce, loupíce zlostně, a zhoubu uvodíce z nenávisti starodávní,'),
(1567360,54,26,25,16,'Protož takto praví Panovník Hospodin: Aj, já vztáhnu ruku svou na Filistinské, a vypléním Ceretejské, a zkazím ostatek přístavu mořského.'),
(1567361,54,26,25,17,'A tak vykonám při nich pomsty veliké káraními zůřivými, a zvědí, že já jsem Hospodin, když uvedu pomstu svou na ně.'),
(1567362,54,26,26,1,'Bylo pak jedenáctého léta, prvního dne měsíce, že se stalo slovo Hospodinovo ke mně, řkoucí:'),
(1567363,54,26,26,2,'Synu člověčí, proto že Týrus o Jeruzalému říká: Dobře se stalo, že jest potříno město bran velmi lidných, obrací se ke mně, naplněn budu, kdyžtě zpuštěno,'),
(1567364,54,26,26,3,'Protož takto praví Panovník Hospodin: Aj, já proti tobě, ó Týre, a přivedu na tě národy mnohé, tak jako bych přivedl moře s vlnami jeho.'),
(1567365,54,26,26,4,'I zkazí zdi Týru, a zboří věže jeho; vymetu také z něho prach jeho, a obrátím jej v skálu vysedlou,'),
(1567366,54,26,26,5,'Tak že budou vysušovati síti u prostřed moře. Nebo jsem já mluvil, praví Panovník Hospodin, protož bude v loupež národům.'),
(1567367,54,26,26,6,'Dcery pak jeho, kteréž na poli budou, mečem zmordovány budou, i zvědí, že já jsem Hospodin.'),
(1567368,54,26,26,7,'Nebo takto praví Panovník Hospodin: Aj, já přivedu na Týr Nabuchodonozora krále Babylonského od půlnoci, krále nad králi, s koňmi a s vozy, i s jezdci i s vojskem a s lidem mnohým.'),
(1567369,54,26,26,8,'Dcery tvé na poli mečem zmorduje, a vzdělá proti tobě šance, a vysype proti tobě násyp, a postaví proti tobě pavézníky.'),
(1567370,54,26,26,9,'I střelbu zasadí proti zdem tvým, a věže tvé poboří nosatci svými.'),
(1567371,54,26,26,10,'Od množství koní jeho přikryje tě prach jejich; od hřmotu jezdců a kár i vozů zatřesou se zdi tvé, když on vcházeti bude do bran tvých, jako do průchodů města probořeného.'),
(1567372,54,26,26,11,'Kopyty koní svých pošlapá všecky ulice tvé, lid tvůj mečem pomorduje, a sloupové pamětní síly tvé na zem padnou.'),
(1567373,54,26,26,12,'I rozberou zboží tvá, a rozchvátají kupectví tvá, a rozválejí zdi tvé, i domy tvé rozkošné poboří, a kamení tvé i dříví tvé, i prach tvůj do vody vmecí.'),
(1567374,54,26,26,13,'A tak přítrž učiním hluku zpěvů tvých, a zvuku citar tvých aby nebylo slýcháno více.'),
(1567375,54,26,26,14,'A obrátím tě v skálu vysedlou, budeš k vysušování sítí, nebudeš vystaven více; nebo já Hospodin mluvil jsem, praví Panovník Hospodin.'),
(1567376,54,26,26,15,'Takto praví Panovník Hospodin Týru: Zdaliž od hřmotu padání tvého, když stonati budou zranění, když ukrutný mord bude u prostřed tebe, nepohnou se ostrovové?'),
(1567377,54,26,26,16,'A vyvstanou z stolic svých všecka knížata pomořská, a složí z sebe pláště své, i roucha svá krumpovaná svlekou; v hrůzu se oblekou, na zemi seděti budou, a třesouce se každé chvíle, trnouti budou nad tebou.'),
(1567378,54,26,26,17,'I vydadí se nad tebou v naříkání, a řeknou tobě: Jak jsi zahynulo, ó město, v němž bydleno bylo pro moře, město slovoutné, ješto bylo pevné na moři, ono i s obyvateli svými, kteříž pouštěli strach svůj na všecky obyvatele jeho!'),
(1567379,54,26,26,18,'Tehdáž třásti se budou ostrovové v den pádu tvého; předěšeni, pravím, budou ostrovové, kteříž jsou na moři, nad zahynutím tvým.'),
(1567380,54,26,26,19,'Nebo tak praví Panovník Hospodin: Když tě učiním městem zpuštěným jako města, v nichž se nebydlí, když uvedu na tě hlubinu, tak že tě přikryjí vody mnohé,'),
(1567381,54,26,26,20,'Když učiním, že sstoupíš s sstupujícími do jámy k lidu dávnímu, a posadím tě v nejnižších stranách země, na pustinách starodávních s těmi, jenž sstupují do jámy, aby nebylo bydleno v tobě: prokáži slávu v zemi živých.'),
(1567382,54,26,26,21,'Nebo učiním to, že budeš k náramné hrůze, když tě nestane, a bys pak bylo hledáno, abys nebylo na věky nalezeno, praví Panovník Hospodin.'),
(1567383,54,26,27,1,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567384,54,26,27,2,'Ty pak synu člověčí, vydej se nad Týrem v naříkání,'),
(1567385,54,26,27,3,'A rci Týru, jenž sedě tu, kdež se na moře pouštějí, kupectví provodí s národy na ostrovích mnohých: Takto praví Panovník Hospodin: Ó Týre, ty jsi říkal: Já jsem nejkrásnější.'),
(1567386,54,26,27,4,'U prostřed moře byly hranice tvé, stavitelé tvoji dokonale tě ozdobovali.'),
(1567387,54,26,27,5,'Z jedloví z Sanir dělávali všecka taflování tvá, cedry z Libánu brávali k dělání sloupů tvých.'),
(1567388,54,26,27,6,'Z dubů Bázanských dělávali vesla tvá, a lavičky tvé dělávali z kostí slonových, a z pušpanu z ostrovů Citejských.'),
(1567389,54,26,27,7,'Kment s krumpováním Egyptským býval plátno tvé, z něhož jsi plachty míval; modrý postavec a šarlat z ostrovů Elisa přikrýval tě.'),
(1567390,54,26,27,8,'Obyvatelé Sidonští i Arvadští bývali plavci tvoji, moudří tvoji v tobě, ó Týre, ti bývali správcové tvoji.'),
(1567391,54,26,27,9,'Starší Gebalští a moudří jejich opravovali v tobě zbořeniny tvé; všecky lodí mořské i plavci jejich bývali v tobě, směňujíce s tebou kupectví.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567392,54,26,27,10,'Perští a Ludští i Putští bývali v vojště tvém bojovníci tvoji, pavézu a lebku zavěšovali v tobě. Tiť jsou přidávali tobě ozdoby.'),
(1567393,54,26,27,11,'Arvadští s vojskem tvým na zdech tvých vůkol, též Gamadští na věžech tvých bývali, štíty své zavěšovali na zdech tvých vůkol. Tiť jsou tě zvláštně ozdobovali.'),
(1567394,54,26,27,12,'Zámořští kupci tvoji v množství všelijakého zboží, v stříbře, železe, cínu i olově kupčili na jarmarcích tvých.'),
(1567395,54,26,27,13,'Javan, Tubal a Mešech, kupci tvoji, lidi a nádobí měděné dávali za směnu tobě.'),
(1567396,54,26,27,14,'Z domu Togarma v koních a jezdcích i mezcích kupčili na jarmarcích tvých.'),
(1567397,54,26,27,15,'Synové Dedanovi kupci tvoji, a ostrovové mnozí překupníci byli koupí tvých, tobě k ruce; rohy, kosti slonové i dříví hebénové směňovali za mzdu tvou.'),
(1567398,54,26,27,16,'Syrští kupci tvoji pro množství věcí tvých řemeslně udělaných, v karbunkulích, šarlatu, krumpování i kmentu, a korálích a křištálích kupčívali na jarmarcích tvých.'),
(1567399,54,26,27,17,'Judští i země Izraelská kupci tvoji, pšenici Mennitskou i Fenickou, a med, olej i kadidlo dávali za směnu tobě.'),
(1567400,54,26,27,18,'Damašští kupci tvoji, pro množství věcí tvých řemeslně udělaných, kupčili ve množství všelijakého zboží, ve víně Chelbonském a vně bělostkvoucí.'),
(1567401,54,26,27,19,'Též Dan i Javan chodíce na jarmarky tvé, kupčili, a železo pulerované, kassii i třtinu vonnou tobě směňovali.'),
(1567402,54,26,27,20,'Dedan kupčíval v tobě v suknech drahých k vozům.'),
(1567403,54,26,27,21,'Arabští i všecka knížata Cedarská kupčívali tobě k ruce v beranech a skopcích i kozlích, tím kupčívali v tobě.'),
(1567404,54,26,27,22,'Kupci Sabejští i Ragmejští bývali kupci tvoji ve všelijakých nejpřednějších vonných věcech, i ve všelijakém kamení drahém i zlatě, kupčívali na jarmarcích tvých.'),
(1567405,54,26,27,23,'Cháran a Kanne i Eden, kupci Sabejští, Assur i Kilmad kupčíval v tobě.'),
(1567406,54,26,27,24,'Ti bývali kupci tvoji na jarmarcích tvých s nejvýbornějšími věcmi, s štoučkami postavce modrého, a s krumpováním i s klénoty drahých věcí, kteréž se provazy svazují a zavírají do cedru.'),
(1567407,54,26,27,25,'Lodí mořské předek měly v kupectví tvém. Summou, naplněno jsi i zvelebeno náramně u prostřed moře.'),
(1567408,54,26,27,26,'Na vodu velikou zavezli tě ti, kteříž tě vesly táhli; vítr východní potříská tě u prostřed moře.'),
(1567409,54,26,27,27,'Zboží tvá i jarmarkové tvoji, kupectví tvá, plavci tvoji a správcové tvoji, i ti, kteříž opravovali zbořeniny tvé, a směňovali s tebou kupectví, a všickni muži váleční tvoji, kteříž byli v tobě, i všecko shromáždění tvé, kteréž bylo u prostřed tebe, padnou do hlubokosti mořské v den pádu tvého.'),
(1567410,54,26,27,28,'Od hřmotu křiku správců tvých zbouří se i vlnobití.'),
(1567411,54,26,27,29,'I vystoupí z lodí svých všickni ti, kteříž táhnou veslem, plavci i všickni správcové lodí mořských na zemi stanou,'),
(1567412,54,26,27,30,'A hlasem velikým nad tebou naříkati a žalostně křičeti budou, a sypouce prach na hlavy své, v popele se váleti.'),
(1567413,54,26,27,31,'Nadto zdělajíce příčinou tvou lysiny,přepáší se žíněmi, a kvílením hořkým nad tebou s žalostí srdečnou plakati budou.'),
(1567414,54,26,27,32,'Vydadí se, pravím, nad tebou s hořekováním svým v naříkání, a budou naříkati nad tebou: Které město podobné Týru, zahlazenému u prostřed moře?'),
(1567415,54,26,27,33,'Když vycházely koupě tvé z moře, nasycovalo jsi národy mnohé; množstvím zboží svého i kupectví svých zbohacovalos krále zemské.'),
(1567416,54,26,27,34,'Ale když ztroskotáno budeš od moře v hlubokých vodách, kupectví tvé i všecko shromáždění tvé u prostřed tebe klesne.'),
(1567417,54,26,27,35,'Všickni obyvatelé ostrovů ztrnou nad tebou, a králové jejich ohromeni jsouce, zhrozí se náramně.'),
(1567418,54,26,27,36,'Kupci mezi národy ckáti budou nad tebou; k hrůze veliké budeš, a nebude tě na věky.'),
(1567419,54,26,28,1,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567420,54,26,28,2,'Synu člověčí, rci vývodovi Tyrskému: Takto praví Panovník Hospodin: Proto že se vyvyšuje srdce tvé, a říkáš: Bůh silný jsem, na stolici Boží sedím u prostřed moře, ješto jsi člověk a ne Bůh silný, ačkoli sobě přivlastňuješ srdce podobné srdci Božímu,'),
(1567421,54,26,28,3,'Aj hle, moudřejší jsi nad Daniele, žádná věc tajná není před tebou ukrytá;'),
(1567422,54,26,28,4,'Moudrosti svou a rozumností svou nashromáždils sobě zboží, a nahrnuls zlata a stříbra do pokladů svých;'),
(1567423,54,26,28,5,'Velikou moudrostí svou v kupectví svém rozmnožil jsi zboží svá, a tak pozdvihlo se srdce tvé zbožím tvým;'),
(1567424,54,26,28,6,'Z té příčiny takto praví Panovník Hospodin: Proto že sobě přivlastňuješ srdce podobné srdci Božímu,'),
(1567425,54,26,28,7,'Protož aj, já přivedu na tě cizozemce, nejukrutnější národy, kteříž vytrhnouce meče své na krásu moudrosti tvé, zabijí jasnost tvou.'),
(1567426,54,26,28,8,'Do jámy spustí tě, a umřeš smrtí hroznou u prostřed moře.'),
(1567427,54,26,28,9,'Budeš-liž tu ještě říkati před oblíčejem mordéře svého: Bohem jsem, poněvadž jsi člověk a ne Bůh silný, jsa v ruce toho, jenž tě mordovati bude?'),
(1567428,54,26,28,10,'Smrtí neobřezanců umřeš od ruky cizozemců; nebo já mluvil jsem, praví Panovník Hospodin.'),
(1567429,54,26,28,11,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567430,54,26,28,12,'Synu člověčí, vydej se v naříkání nad králem Tyrským, a rci jemu: Takto praví Panovník Hospodin: Ty, jenž zapečeťuješ summy, plný moudrosti a nejkrásnější,'),
(1567431,54,26,28,13,'V Eden, zahradě Boží, byl jsi, všelijaké drahé kamení přikrývalo tě, sardius, topazius, jaspis, tarsis, onychin, beryl, zafir, karbunkulus a smaragd i zlato; nástrojové bubnů tvých a píšťal tvých v tobě, hned jakžs se narodil, připraveni jsou.'),
(1567432,54,26,28,14,'Ty jsi cherubem od pomazání. Jakž jsem tě za ochránce představil, na hoře svaté Boží jsi byl, u prostřed kamení ohnivého ustavičně jsi chodil.'),
(1567433,54,26,28,15,'Byl jsi dokonalý na cestách svých, hned jakžs se narodil, až se našla nepravost při tobě.'),
(1567434,54,26,28,16,'Pro množství kupectví tvého u prostřed tebe plno jest bezpráví, a velmi jsi prohřešil. Pročež zahubím tě, a vyhladím z hory Boží, ó cherube ochránce, z prostřed kamenů ohnivých.'),
(1567435,54,26,28,17,'Pozdvihlo se srdce tvé slávou tvou, k zlému jsi užíval moudrosti své příčinou jasnosti své. Porazím tě na zemi, před oblíčej králů povrhu tě, aby se dívali na tebe.'),
(1567436,54,26,28,18,'Pro množství nepravostí tvých, a pro nespravedlnosti kupectví tvého poškvrnil jsi svatyně své. Protož vyvedu oheň z prostřed tebe, kterýž tě sžíře, a obrátí tě v popel na zemi před očima všech na tě hledících.'),
(1567437,54,26,28,19,'Všickni, kdož tě znali mezi národy, ztrnou nad tebou; k hrůze veliké budeš, a nebude tě na věky.'),
(1567438,54,26,28,20,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567439,54,26,28,21,'Synu člověčí, obrať tvář svou proti Sidonu, a prorokuj proti němu,'),
(1567440,54,26,28,22,'A rci: Takto praví Panovník Hospodin: Aj, já proti tobě jsem, ó Sidone, a budu oslaven u prostřed tebe. I zvědí, že já jsem Hospodin, když vykonám při něm soudy, a posvěcen budu v něm.'),
(1567441,54,26,28,23,'Pošli zajisté na něj mor, a krev na ulice jeho, a padati budou zranění u prostřed něho od meče na všecky strany, i zvědí, že já jsem Hospodin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567442,54,26,28,24,'A tak nebude více míti dům Izraelský trnu urážejícího a bodláku bodoucího ze všech okolních pohrdajících jimi, a zvědí, že já jsem Panovník Hospodin.'),
(1567443,54,26,28,25,'Takto praví Panovník Hospodin: Když shromáždím dům Izraelský z národů, mezi něž rozptýleni jsou, a posvěcen budu v nich před očima pohanů, a bydliti budou v zemi své, kterouž jsem byl dal služebníku svému Jákobovi:'),
(1567444,54,26,28,26,'Tehdy bydliti budou v ní bezpečně, a nastavějí domů, a štípí vinice. Bydliti, pravím, budou bezpečně, když vykonám soudy, při všech zhoubcích jejich vůkol nich, i zvědí, že já jsem Hospodin Bůh jejich.'),
(1567445,54,26,29,1,'Léta desátého, desátého měsíce, dvanáctého dne téhož měsíce, stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567446,54,26,29,2,'Synu člověčí, obrať tvář svou proti Faraonovi králi Egyptskému, a prorokuj proti němu i proti všemu Egyptu.'),
(1567447,54,26,29,3,'Mluv a rci: Takto praví Panovník Hospodin: Aj, já proti tobě jsem, ó Faraone králi Egyptský, draku veliký, kterýž ležíš u prostřed řek svých, ješto říkáš: Já mám řeku svou, já zajisté jsem ji přivedl sobě.'),
(1567448,54,26,29,4,'Protož dám udici do čelistí tvých, a učiním, že zváznou ryby řek tvých na tvých šupinách; i vyvleku tě z prostředku řek tvých,i všecky ryby řek tvých na šupinách tvých zvázlé.'),
(1567449,54,26,29,5,'A nechám tě na poušti, tebe i všech ryb řek tvých. Na svrchku pole padneš, nebudeš sebrán ani shromážděn; šelmám zemským i ptactvu nebeskému dám tě k sežrání.'),
(1567450,54,26,29,6,'I zvědí všickni obyvatelé Egyptští, že já jsem Hospodin, proto že jste holí třtinovou domu Izraelskému.'),
(1567451,54,26,29,7,'Když se chytají tebe rukou, lámeš se, a roztínáš jim všecko rameno; a když se na tě zpodpírají, ztroskotána býváš, ačkoli nastavuješ jim všech bedr.'),
(1567452,54,26,29,8,'Protož takto praví Panovník Hospodin: Aj, já přivedu na tě meč, a vypléním z tebe lidi i hovada.'),
(1567453,54,26,29,9,'I bude země Egyptská pustinou a pouští, i zvědí, že já jsem Hospodin, proto že říkal: Řeka má jest, já zajisté jsem ji přivedl.'),
(1567454,54,26,29,10,'Protož aj, já budu proti tobě i proti řece tvé, a obrátím zemi Egyptskou v pustiny, v poušť přehroznou od věže Sevéne až do pomezí Mouřenínského.'),
(1567455,54,26,29,11,'Nepůjdeť přes ni noha člověka, ani noha dobytčete půjde přes ni, a nebude v ní bydleno za čtyřidceti let.'),
(1567456,54,26,29,12,'A tak uvedu zemi Egyptskou v pustinu nad jiné země pusté, a města její nad jiná města zpuštěná pustá budou za čtyřidceti let, když rozptýlím Egyptské mezi národy, a rozženu je do rozličných zemí.'),
(1567457,54,26,29,13,'A však takto praví Panovník Hospodin: Po skonání čtyřidceti let shromáždím Egyptské z národů, kamž rozptýleni budou.'),
(1567458,54,26,29,14,'A přivedu zase zajaté Egyptské, a uvedu je zase do země Patros, do země přebývání jejich, i budou tam královstvím sníženým.'),
(1567459,54,26,29,15,'Mimo jiná království bude sníženější, aniž se bude vynášeti více nad jiné národy; zmenším je zajisté, aby nepanovali nad národy.'),
(1567460,54,26,29,16,'I nebude více domu Izraelskému doufáním, kteréž by na pamět přivodilo nepravost, když by se obraceli za nimi; nebo zvědí, že já jsem Panovník Hospodin.'),
(1567461,54,26,29,17,'Potom bylo dvadcátého sedmého léta, prvního měsíce, prvního dne, že se stalo slovo Hospodinovo ke mně, řkoucí:'),
(1567462,54,26,29,18,'Synu člověčí, Nabuchodonozor král Babylonský podrobil vojsko své v službu velikou proti Týru. Každá hlava oblezla, a každé rameno odříno jest, mzdy pak nemá, on ani vojsko jeho, z Týru za tu službu, kterouž sloužili proti němu.'),
(1567463,54,26,29,19,'Z té příčiny takto praví Panovník Hospodin: Aj, já dávám Nabuchodonozorovi králi Babylonskému zemi Egyptskou, aby pobral zboží její, a rozebral loupeže její, i rozchvátal kořisti její, aby mělo mzdu vojsko jeho.'),
(1567464,54,26,29,20,'Za práci jejich, kterouž mi sloužili, dám jim zemi Egyptskou, proto že mně pracovali, praví Panovník Hospodin.'),
(1567465,54,26,29,21,'V ten den rozkáži vypučiti se rohu domu Izraelského. Tobě též způsobím, že otevřeš ústa u prostřed nich, i zvědí, že já jsem Hospodin.'),
(1567466,54,26,30,1,'Opět se stalo slovo Hospodinovo ke mně, řkoucí:'),
(1567467,54,26,30,2,'Synu člověčí, prorokuj a rci: Takto praví Panovník Hospodin: Kvělte: Ach, nastojte na tento den.'),
(1567468,54,26,30,3,'Nebo blízko jest den, blízko jest, pravím, den Hospodinův, den mrákoty, čas národů bude.'),
(1567469,54,26,30,4,'A přijde meč do Egypta, a bude přetěžká bolest v Mouřenínské zemi, když padati budou zbití v Egyptě, a poberou zboží jeho, a zbořeni budou základové jeho.'),
(1567470,54,26,30,5,'Mouřenínové a Putští i Ludští i všelijaká směsice, též Kubští i obyvatelé země smlouvy s nimi mečem padnou.'),
(1567471,54,26,30,6,'Takť praví Hospodin, že padnou podpůrcové Egypta, a snížena bude vyvýšenost síly jeho; od věže Sevéne mečem padati budou v ní, praví Panovník Hospodin.'),
(1567472,54,26,30,7,'I budou v pustinu obráceni nad jiné země pusté, a města jejich nad jiná města pustá budou.'),
(1567473,54,26,30,8,'I zvědí, že já jsem Hospodin, když zapálím oheň v Egyptě, a potříni budou všickni pomocníci jeho.'),
(1567474,54,26,30,9,'V ten den vyjdou poslové od tváři mé na lodech, aby přestrašili Mouřenínskou zemi ubezpečenou, i budou míti bolest přetěžkou, jakáž byla ve dni Egypta; nebo aj, přicházíť.'),
(1567475,54,26,30,10,'Takto praví panovník Hospodin: Učiním zajisté konec množství Egyptskému skrze ruku Nabuchodonozora krále Babylonského.'),
(1567476,54,26,30,11,'On i lid jeho s ním, nejukrutnější národové přivedeni budou, aby zkazili tu zemi; nebo vytrhnou meče své na Egypt, a naplní tu zemi zbitými.'),
(1567477,54,26,30,12,'A obrátě řeky v sucho, prodám tu zemi v ruku nešlechetných, a tak v pustinu uvedu zemi, i což v ní jest, skrze ruku cizozemců. Já Hospodin mluvil jsem.'),
(1567478,54,26,30,13,'Takto praví Panovník Hospodin: Zkazím i ukydané bohy, a konec učiním modlám v Nof, a knížete z země Egyptské nebude více, když pustím strach na zemi Egyptskou.'),
(1567479,54,26,30,14,'Nebo pohubím Patros, a zapálím oheň v Soan, a vykonám soudy v No.'),
(1567480,54,26,30,15,'Vyleji prchlivost svou i na Sin, pevnost Egyptskou, a vypléním množství No.'),
(1567481,54,26,30,16,'Když zapálím oheň v Egyptě, velikou bolest bude míti Sin, a No bude roztrháno, Nof pak nepřátely bude míti ve dne.'),
(1567482,54,26,30,17,'Mládenci On a Bubastští mečem padnou, panny pak v zajetí půjdou.'),
(1567483,54,26,30,18,'A v Tachpanches zatmí se den, když tam polámi závory Egypta, a přítrž se stane v něm vyvýšenosti síly jeho. Mrákota jej přikryje, dcery pak jeho v zajetí půjdou.'),
(1567484,54,26,30,19,'A tak vykonám soudy při Egyptu, i zvědí, že já jsem Hospodin.'),
(1567485,54,26,30,20,'Opět bylo jedenáctého léta, prvního měsíce, sedmého dne, že se stalo slovo Hospodinovo ke mně, řkoucí:'),
(1567486,54,26,30,21,'Synu člověčí, rámě Faraona krále Egyptského zlámal jsem, a aj, nebudeť uvázáno, ani přičiněno lékařství, aniž přiložen bude šat pro obvázání jeho a posilnění jeho k držení meče.'),
(1567487,54,26,30,22,'Protož takto praví panovník Hospodin: Aj, já jsem proti Faraonovi králi Egyptskému, a polámi ramena jeho, i sílu jeho, i budeť zlámané, a vyrazím meč z ruky jeho.'),
(1567488,54,26,30,23,'A rozptýlím Egyptské mezi národy, a rozženu je do zemí.'),
(1567489,54,26,30,24,'Posilním zajisté ramen krále Babylonského, a dám meč svůj v ruku jeho, i polámi ramena Faraonova, tak že stonati bude před ním, jakž stonává smrtelně raněný.'),
(1567490,54,26,30,25,'Posilním, pravím, ramen krále Babylonského, ramena pak Faraonova klesnou. I zvědí, že já jsem Hospodin, když dám meč svůj v ruku krále Babylonského, aby jej vztáhl na zemi Egyptskou.'),
(1567491,54,26,30,26,'A tak rozptýlím Egyptské mezi národy, a rozženu je do zemí, i zvědí, že já jsem Hospodin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567492,54,26,31,1,'Bylo pak jedenáctého léta, třetího měsíce, prvního dne téhož měsíce, že se stalo slovo Hospodinovo ke mně, řkoucí:'),
(1567493,54,26,31,2,'Synu člověčí, rci Faraonovi králi Egyptskému i množství jeho: K komu jsi podoben v své velikosti?'),
(1567494,54,26,31,3,'Aj, Assur byl jako cedr na Libánu, pěkných ratolestí, a větvovím zastěňující, a vysokého zrůstu, jehož vrchové byli mezi hustými větvemi.'),
(1567495,54,26,31,4,'Vody k zrůstu přivedly jej, propast jej vyvýšila, potoky jejími opuštěn byl vůkol kmen jeho, ješto jen praménky své vypouštěla na všecka dříví polní.'),
(1567496,54,26,31,5,'Takž se vyvýšil zrůst jeho nade všecka dříví polní, a rozmnožili se výstřelkové jeho, a pro hojnost vod roztáhly se ratolesti jeho, kteréž vypustil.'),
(1567497,54,26,31,6,'Na ratolestech jeho hnízdilo se všelijaké ptactvo nebeské, a pod větvemi jeho rodili se všelijací živočichové polní, a v stínu jeho sedali všickni národové velicí.'),
(1567498,54,26,31,7,'I byl ušlechtilý pro svou velikost, a pro dlouhost větví svých; nebo kořen jeho byl při vodách mnohých.'),
(1567499,54,26,31,8,'Cedrové v zahradě Boží nepřikryli ho, jedle nevrovnaly se ratolestem jeho, a stromové kaštanoví nebyli podobni větvem jeho. Žádné dřevo v zahradě Boží nebylo rovné jemu v kráse své.'),
(1567500,54,26,31,9,'Ozdobil jsem jej množstvím větvoví jeho, tak že mu záviděla všecka dříví Eden, kteráž byla v zahradě Boží.'),
(1567501,54,26,31,10,'Protož takto praví Panovník Hospodin: Proto že vysoce vyrostl, a vypustil vrch svůj mezi husté větvoví, a pozdvihlo se srdce jeho příčinou vysokosti jeho:'),
(1567502,54,26,31,11,'Protož vydal jsem jej v ruku nejsilnějšího z národů, aby s ním přísně nakládal; pro bezbožnost jeho vyhnal jsem jej.'),
(1567503,54,26,31,12,'A tak vyťali jej cizozemci, nejukrutnější národové, a nechali ho tu. Po horách i po všech údolích opadly větve jeho, a slomeny jsou ratolesti jeho na všecky prudké potoky té země. Pročež vystoupili z stínu jeho všickni národové země, a opustili jej.'),
(1567504,54,26,31,13,'Na němž padlém bydlí všelijaké ptactvo nebeské, a na ratolestech jeho jsou všelijací živočichové polní,'),
(1567505,54,26,31,14,'Proto aby se nevyvyšovalo v zrostu svém žádné dříví při vodách, a aby nevypouštělo vrchů svých mezi hustými větvemi, a nevypínalo se nad jiné vysokostí svou žádné dřevo zapojené vodami, proto že všickni ti oddáni jsou k smrti, dolů do země mezi syny lidské s těmi, kteříž sstupují do jámy.'),
(1567506,54,26,31,15,'Takto praví Panovník Hospodin: Toho dne, v kterýž on sstoupil do hrobu, přivedl jsem k kvílení, a přikryl jsem příčinou jeho propast, a zadržel jsem potoky její, aby se zastavily vody mnohé, a učinil jsem, aby smutek nesl příčinou jeho Libán, a všecko dříví polní příčinou jeho aby umdlelo.'),
(1567507,54,26,31,16,'Od hřmotu pádu jeho učinil jsem, že se třásli národové, když jsem jej svedl do hrobu s těmi, kteříž sstupují do jámy. Nad čímž se potěšila na zemi dole všecka dříví Eden, což výborného a dobrého jest na Libánu, vše což zapojeného jest vodou.'),
(1567508,54,26,31,17,'I ti s ním sstoupili do hrobu k těm, kteříž jsou zbiti mečem, i rámě jeho, i kteříž sedali v stínu jeho u prostřed národů.'),
(1567509,54,26,31,18,'Kterému z stromů Eden podoben jsi tak v slávě a velikosti? Však svržen budeš s dřívím Eden dolů na zem, mezi neobřezanci s zbitými mečem lehneš. Toť jest Farao i všecko množství jeho, praví Panovník Hospodin.'),
(1567510,54,26,32,1,'Opět bylo dvanáctého léta, dvanáctého měsíce, prvního dne téhož měsíce, že se stalo slovo Hospodinovo ke mně, řkoucí:'),
(1567511,54,26,32,2,'Synu člověčí, vydej se v naříkání nad Faraonem králem Egyptským, a rci jemu: Lvu mladému mezi národy podoben jsi, a jsi jako velryb v moři, když procházeje se v potocích svých, kalíš vodu nohama svýma, a kormoutíš potoky její.'),
(1567512,54,26,32,3,'Takto praví Panovník Hospodin: Rozestruť na tě síť svou skrze shromáždění národů mnohých, kteříž tě vytáhnou nevodem mým.'),
(1567513,54,26,32,4,'I nechám tě na zemi, povrhu tě na svrchku pole, a učiním, že na tobě přebývati bude všelijaké ptactvo nebeské, a nasytím tebou živočichy vší země.'),
(1567514,54,26,32,5,'A rozmeci maso tvé po horách, a naplním údolí vysokostí tvou.'),
(1567515,54,26,32,6,'A napojím zemi, v níž ploveš, krví tvou až do hor, tak že i potokové naplněni budou tebou.'),
(1567516,54,26,32,7,'V tom, když tě zhasím, zakryji nebesa, a zasmušilé učiním hvězdy jejich; slunce mrákotou zastru, a měsíc nebude svítiti světlem svým.'),
(1567517,54,26,32,8,'Všecka světla jasná na nebesích zasmušilá učiním příčinou tvou, a uvedu tmu na zemi tvou, praví Panovník Hospodin.'),
(1567518,54,26,32,9,'Nadto zkormoutím srdce národů mnohých, když způsobím, aby došla pověst o potření tvém mezi národy, do zemí, jichž jsi neznal.'),
(1567519,54,26,32,10,'Učiním, pravím, že trnouti budou nad tebou národové mnozí, a králové jejich hroziti se příčinou tvou velice, když šermovati budu mečem svým před tváří jejich. Budou se zajisté lekati každé chvilky, každý sám za sebe v den pádu tvého.'),
(1567520,54,26,32,11,'Nebo takto praví Panovník Hospodin: Meč krále Babylonského přijde na tě.'),
(1567521,54,26,32,12,'Meči udatných porazím množství tvé, nejukrutnějších ze všech národů; tiť zkazí pýchu Egypta, a zahlazeno bude všecko množství jeho.'),
(1567522,54,26,32,13,'Zahladím i všecka hovada jeho, kteráž jsou při vodách mnohých, tak že jich nezakalí noha člověčí více, aniž jich kaliti budou kopyta hovad.'),
(1567523,54,26,32,14,'Tuť učiním, že se usadí vody jejich, a potokové jejich že jako olej půjdou, praví Panovník Hospodin,'),
(1567524,54,26,32,15,'Když obrátím zemi Egyptskou v poušť přehroznou, v zemi prázdnou toho, což prvé v ní bylo, a když zbiji v ní všecky obyvatele. I zvědí, že já jsem Hospodin.'),
(1567525,54,26,32,16,'Toť jest naříkání, jímž naříkati budou. Tak dcery národů naříkati budou, tak nad Egyptem i nade vším jeho množstvím naříkati budou, dí Panovník Hospodin.'),
(1567526,54,26,32,17,'Potom bylo dvanáctého léta, patnáctého dne téhož měsíce, že se stalo slovo Hospodinovo ke mně, řkoucí:'),
(1567527,54,26,32,18,'Synu člověčí, naříkej nad množstvím Egypta, a snes jej i dcery národů těch slavných do zpodních míst země k těm, kteříž sstupují do jámy.'),
(1567528,54,26,32,19,'A rci: Nad kohož bys utěšenější byl? Sstupiž a lež s neobřezanci.'),
(1567529,54,26,32,20,'Mezi zbitými mečem padnou, meči vydán jest, vlectež jej i všecko množství jeho.'),
(1567530,54,26,32,21,'Budouť k němu mluviti hrdiny s jeho pomocníky z prostřed hrobu, kdež neobřezanci mečem zbití sstoupivše, leží.'),
(1567531,54,26,32,22,'Tam jest Assur i všecka zběř jeho, jehož hrobové jsou vůkol tohoto. Všickni ti byvše zbiti, padli od meče.'),
(1567532,54,26,32,23,'Jehož hrobové jsou po stranách jámy, aby byla zběř jeho vůkol hrobu tohoto. Všickni ti byvše zbiti, padli od meče, kteříž pouštívali strach v zemi živých.'),
(1567533,54,26,32,24,'Tam Elam i všecko množství jeho vůkol hrobu tohoto. Všickni ti neobřezanci byvše zbiti, padli od meče, a sstoupili do zpodních míst země, kteříž pouštívali strach svůj v zemi živých. Jižť nesou potupu svou s těmi, kteříž sstupují do jámy.'),
(1567534,54,26,32,25,'Mezi zbitými postavili jemu lože, i všemu množství jeho, vůkol něhož jsou hrobové tohoto. Všickni ti neobřezanci zbiti mečem, nebo pouštín býval strach jejich v zemi živých. Jižť nesou potupu svou s těmi, jenž sstupují do jámy, mezi zbitými položeni jsouce.'),
(1567535,54,26,32,26,'Tam Mešech, Tubal i všecko množství jeho, a vůkol něho hrobové tohoto. Všickni ti neobřezanci zbiti mečem, nebo pouštívali strach svůj v zemi živých.'),
(1567536,54,26,32,27,'Ačťkoli ti ještě nelehli s hrdinami, kteříž padli z neobřezanců, kteříž sstoupili do hrobu s zbrojí svou vojenskou, a podložili meče své pod hlavy své, a však důjdeť nepravost jejich na kosti jejich; nebo strach hrdin byl v zemi živých.'),
(1567537,54,26,32,28,'I ty mezi neobřezanci potřín budeš, a lehneš s zbitými mečem.'),
(1567538,54,26,32,29,'Tam Edom, králové jeho, i všecka knížata jeho, kteříž položeni jsou i s svou mocí s zbitými mečem. I ti s neobřezanci lehnou a s těmi, kteříž sstupují do jámy.'),
(1567539,54,26,32,30,'Tam knížata půlnoční strany všickni napořád, i všickni Sidonští, kteříž sstoupí k zbitým, s strachem svým, za svou moc stydíce se, a ležeti budou ti neobřezanci s zbitými mečem, a ponesou potupu svou s těmi, kteříž sstupují do jámy.'),
(1567540,54,26,32,31,'Ty uhlédaje Farao, potěší se nade vším množstvím svým, Farao i všecko vojsko jeho, zbiti jsouce mečem, dí Panovník Hospodin.'),
(1567541,54,26,32,32,'Nebo pustím strach svůj v zemi živých, a položen bude mezi neobřezanci s zbitými mečem Farao i všecko množství jeho, praví Panovník Hospodin.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567542,54,26,33,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567543,54,26,33,2,'Synu člověčí, mluv k synům lidu svého a rci jim: Když uvedu na zemi některou meč, jestliže vezme lid té země muže jednoho od končin svých, a ustanoví jej sobě za strážného,'),
(1567544,54,26,33,3,'A ten vida meč přicházející na tu zemi, troubil-li by na troubu a napomínal lidu,'),
(1567545,54,26,33,4,'A slyše někdo zvuk trouby, však by se nedal napomenouti, a v tom přijda meč, shladil by jej: krev jeho na hlavu jeho bude.'),
(1567546,54,26,33,5,'Nebo slyšel hlas trouby, však nedal se napomenouti; krev jeho na něm zůstane.Byť se byl napomenouti dal, duši svou byl by vysvobodil.'),
(1567547,54,26,33,6,'Pakli strážný vida, an meč přichází, však by nezatroubil na troubu, a lid by nebyl napomenut, a přijda meč, zachvátil by někoho z nich: ten pro nepravost svou zachvácen bude, ale krve jeho z ruky strážného toho vyhledávati budu.'),
(1567548,54,26,33,7,'Tebe pak synu člověčí, tebe jsem strážným ustanovil nad domem Izraelským, abys slyše z úst mých slovo, napomínal jich ode mne.'),
(1567549,54,26,33,8,'Když bych já řekl bezbožnému: Bezbožníče, smrtí umřeš, a nemluvil bys, vystříhaje bezbožného od cesty jeho: ten bezbožný pro nepravost svou umře, ale krve jeho z ruky tvé vyhledávati budu.'),
(1567550,54,26,33,9,'Pakli bys ty vystříhal bezbožného od cesty jeho, tak aby se od ní odvrátil, a však neodvrátil by se od cesty své: onť pro nepravost svou umře, ale ty duši svou vysvobodíš.'),
(1567551,54,26,33,10,'Protož ty synu člověčí, rci domu Izraelskému: Takto mluvíte, říkajíce: Proto že přestoupení naše a hříchové naši jsou na nás, a my v nich svadneme, i jakž bychom živi byli?'),
(1567552,54,26,33,11,'Rci jim: Živť jsem já, dí Panovník Hospodin, žeť nemám líbosti v smrti bezbožného, ale aby se odvrátil bezbožný od cesty své a živ byl. Odvraťtež se, odvraťte od cest svých zlých. I proč mříti máte, ó dome Izraelský?'),
(1567553,54,26,33,12,'Ty tedy synu člověčí, rci synům lidu svého: Spravedlnost spravedlivého nevytrhne ho v den přestoupení jeho, aniž bezbožný v své bezbožnosti padne, v kterýž by se den odvrátil od bezbožnosti své; tolikéž spravedlivý nebude moci živ býti v ní, v kterýž by den zhřešil.'),
(1567554,54,26,33,13,'Jestliže dím spravedlivému: Jistě živ budeš, a on doufaje v spravedlnost svou, činil by nepravost: žádná spravedlnost jeho nepřijde na pamět, ale pro tu nepravost svou, kterouž činil, umře.'),
(1567555,54,26,33,14,'Zase řeknu-li bezbožnému: Smrtí umřeš, však odvrátí-li se od hříchu svého, a činiti bude soud a spravedlnost,'),
(1567556,54,26,33,15,'Což v zástavě jest, navrátí-li bezbožný, což vydřel, nahradí-li, v ustanoveních života bude-li choditi, nečině nepravosti: jistě že bude živ, neumře.'),
(1567557,54,26,33,16,'Žádní hříchové jeho, jimiž hřešil, nebudou mu zpomínáni; soud a spravedlnost činil, jistě že bude živ.'),
(1567558,54,26,33,17,'A vždy říkají synové lidu tvého: Není pravá cesta Páně, ješto jejich cesta není pravá.'),
(1567559,54,26,33,18,'Když by se odvrátil spravedlivý od spravedlnosti své, a činil by nepravost, umřeť pro ty věci.'),
(1567560,54,26,33,19,'Ale když by se odvrátil bezbožný od bezbožnosti své, a činil by soud a spravedlnost, podlé těch věcí živ bude.'),
(1567561,54,26,33,20,'A předce říkáte: Není pravá cesta Páně. Každého z vás podlé cest jeho souditi budu, ó dome Izraelský.'),
(1567562,54,26,33,21,'Stalo se pak dvanáctého léta, desátého měsíce, pátého dne téhož měsíce od zajetí našeho, že přišel ke mně jeden, kterýž ušel z Jeruzaléma, řka: Dobyto jest město.'),
(1567563,54,26,33,22,'Ruka pak Hospodinova byla při mně u večer před tím, než přišel ten, kterýž utekl, a otevřela ústa má, až i ke mně přišel ráno; otevřela, pravím, ústa má, abych nebyl němým déle.'),
(1567564,54,26,33,23,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567565,54,26,33,24,'Synu člověčí, obyvatelé pustin těchto v zemi Izraelské mluví, řkouce: Jedinký byl Abraham, a dědičně držel zemi tuto, nás pak mnoho jest; námť dána jest země tato v dědictví.'),
(1567566,54,26,33,25,'Protož rci jim: Takto praví Panovník Hospodin: Se krví jídáte, a očí svých pozdvihujete k ukydaným modlám svým, i krev vyléváte, a chtěli byste zemí touto dědičně vládnouti?'),
(1567567,54,26,33,26,'Stojíte na meči svém, pášete ohavnost, a každý ženy bližního svého poškvrňujete, a chtěli byste zemí touto dědičně vládnouti?'),
(1567568,54,26,33,27,'Takto mluv k nim: Takto praví Panovník Hospodin: Živť jsem já, že ti, kteříž jsou na pustinách, mečem padnou, a kdo na poli, toho zvěři dám k sežrání, kdo pak na hradích neb v jeskyních, morem zemrou.'),
(1567569,54,26,33,28,'I obrátím zemi tu v hroznou poušť a přestane vyvýšenost moci její, a zpustnou hory Izraelské, tak že nebude žádného, kdo by šel přes ně.'),
(1567570,54,26,33,29,'I zvědí, že já jsem Hospodin, když obrátím zemi tu v hroznou poušť pro všecky ohavnosti jejich, kteréž páchali.'),
(1567571,54,26,33,30,'Ty pak synu člověčí, slyš, synové lidu tvého často mluvívají o tobě, za stěnami i ve dveřích domů, a říkají jeden druhému a každý bratru svému, řka: Poďte medle a poslechněte, jaké slovo vyšlo od Hospodina.'),
(1567572,54,26,33,31,'I scházejí se k tobě, tak jako se schází lid, a sedají před tebou lid můj, a poslouchají slov tvých, ale nečiní jich. A ačkoli je sobě ústy svými libují, však za mrzkým ziskem svým srdce jejich odchází.'),
(1567573,54,26,33,32,'A aj, ty jsi jim jako zpěv libý pěkného zvuku a dobře vznějící. Slyšíť zajisté slova tvá, ale žádný jich nečiní.'),
(1567574,54,26,33,33,'Než když to přijde, (aj, přicházíť), tedy zvědí, že prorok byl u prostřed nich.'),
(1567575,54,26,34,1,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567576,54,26,34,2,'Synu člověčí, prorokuj proti pastýřům Izraelským. Prorokuj a rci jim, těm pastýřům: Takto praví Panovník Hospodin: Běda pastýřům Izraelským, kteříž pasou sami sebe. Zdaliž pastýři nemají stáda pásti?'),
(1567577,54,26,34,3,'Tuk jídáte, a vlnou se odíváte, což tučného, zabijíte, stáda však nepasete.'),
(1567578,54,26,34,4,'Neduživých neposilujete, a nemocné nehojíte, a zlámané neuvazujete, a zaplašené zase nepřivodíte, a zahynulé nehledáte, ale přísně a tvrdě panujete nad nimi,'),
(1567579,54,26,34,5,'Tak že rozptýleny jsou, nemajíce pastýře, a rozptýleny jsouce, jsou za pokrm všelijaké zvěři polní.'),
(1567580,54,26,34,6,'Bloudí stádo mé po všech horách, a na každém pahrbku vysokém, nýbrž po vší země širokosti rozptýleny jsou ovce stáda mého, a není žádného, kdo by se po nich ptal, ani žádného, kdo by jich hledal.'),
(1567581,54,26,34,7,'Protož ó pastýři, slyšte slovo Hospodinovo:'),
(1567582,54,26,34,8,'Živť jsem já, praví Panovník Hospodin, zajisté proto že stádo mé bývá v loupež, a ovce stáda mého bývají k sežrání všelijaké zvěři polní, nemajíce žádného pastýře, aniž se ptají pastýři moji po stádu mém, ale pasou pastýři sami sebe, stáda pak mého nepasou:'),
(1567583,54,26,34,9,'Protož vy pastýři, slyšte slovo Hospodinovo:'),
(1567584,54,26,34,10,'Takto praví Panovník Hospodin: Aj, já jsem proti pastýřům těm, a budu vyhledávati stáda mého z ruky jejich, a zastavím jim pasení stáda, aby nepásli více ti pastýři samých sebe. Vytrhnu zajisté ovce své z úst jejich, aby jim nebyly za pokrm.'),
(1567585,54,26,34,11,'Nebo takto praví Panovník Hospodin: Aj já, já ptáti se budu po ovcích svých a shledávati je.'),
(1567586,54,26,34,12,'Jakož shledává pastýř stádo své tehdáž, když bývá u prostřed ovec svých rozptýlených: tak shledávati budu stádo své, a vytrhnu je ze všech míst, kamž v den oblaku a mrákoty rozptýleny byly.'),
(1567587,54,26,34,13,'A vyvedu je z národů, a shromáždím je z zemí, a uvedu je do země jejich, a pásti je budu na horách Izraelských, při potocích i na všech místech k bydlení příhodných v zemi té.'),
(1567588,54,26,34,14,'Na pastvě dobré pásti je budu, a na horách vysokých Izraelských bude ovčinec jejich. Tamť léhati budou v ovčinci veselém, a pastvou tučnou pásti se budou na horách Izraelských.'),
(1567589,54,26,34,15,'Já pásti budu stádo své, a já způsobím to, že odpočívati budou, praví Panovník Hospodin.'),
(1567590,54,26,34,16,'Zahynulé hledati budu, a zaplašenou zase přivedu, a polámanou uvíži, a nemocné posilím, tučnou pak a silnou zahladím; nebo je pásti budu v soudu.'),
(1567591,54,26,34,17,'Vy pak, stádo mé, slyšte: Takto praví Panovník Hospodin: Aj, já soudím mezi dobytčetem a dobytčetem, mezi skopci a kozly.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567592,54,26,34,18,'Což jest vám málo pastvou dobrou se pásti, že ještě ostatek pastvy vaší pošlapáváte nohama svýma? a učištěnou vodu píti, že ostatek nohama svýma kalíte,'),
(1567593,54,26,34,19,'Tak aby ovce mé tím, což vy nohama pošlapáte, se pásti, a kal noh vašich píti musily?'),
(1567594,54,26,34,20,'Protož takto praví Panovník Hospodin k nim: Aj já, já souditi budu mezi dobytčetem tučným a mezi dobytčetem hubeným,'),
(1567595,54,26,34,21,'Proto že boky i plecemi strkáte, a rohy svými trkáte všecky neduživé, tak že je vyháníte i ven.'),
(1567596,54,26,34,22,'Protož vysvobodím stádo své, aby nebylo více v loupež, a souditi budu mezi dobytčetem a dobytčetem.'),
(1567597,54,26,34,23,'A vzbudím nad nimi pastýře jednoho, kterýž je pásti bude, služebníka svého Davida. Tenť je pásti bude, a ten bude jejich pastýřem.'),
(1567598,54,26,34,24,'Já pak Hospodin budu jejich Bohem, a služebník můj David knížetem u prostřed nich. Já Hospodin mluvil jsem.'),
(1567599,54,26,34,25,'A učině s nimi smlouvu pokoje, způsobím, že přestane zvěř zlá na zemi; i budou bydleti na poušti bezpečně, a spáti i po lesích.'),
(1567600,54,26,34,26,'K tomu obdařím je i okolí pahrbku svého požehnáním, a ssílati budu déšť časem svým; dešťové požehnání budou bývati;'),
(1567601,54,26,34,27,'Tak že vydá dřevo polní ovoce své a země vydá úrodu svou; i budou v zemi své bezpeční, a zvědí, že já jsem Hospodin, když polámi závory jha jejich, a vytrhnu je z ruky těch, jenž je v službu podrobují.'),
(1567602,54,26,34,28,'I nebudou více loupeží národům, a zvěř zemská nebude jich žráti, ale bydliti budou bezpečně, aniž jich kdo přestraší.'),
(1567603,54,26,34,29,'Nadto vzbudím jim výstřelek k slávě, a nebudou více mříti hladem v té zemi, aniž ponesou více potupy od pohanů.'),
(1567604,54,26,34,30,'I zvědí, že já Hospodin Bůh jejich jsem s nimi, a oni lid můj, dům Izraelský, praví Panovník Hospodin.'),
(1567605,54,26,34,31,'Vy pak ovce mé, ovce pastvy mé, jste vy lidé, a já Bůh váš, praví Panovník Hospodin.'),
(1567606,54,26,35,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567607,54,26,35,2,'Synu člověčí, obrať tvář svou proti hoře Seir, a prorokuj proti ní.'),
(1567608,54,26,35,3,'A rci jí: Takto praví Panovník Hospodin: Aj, já jsem proti tobě, horo Seir, a vztáhnu ruku svou na tebe, a obrátím tě v hroznou poušť.'),
(1567609,54,26,35,4,'Města tvá v poušť obrátím, a ty budeš pustinou, i zvíš, že já jsem Hospodin,'),
(1567610,54,26,35,5,'Proto že máš nepřátelství věčné, a rozptyluješ syny Izraelské mečem v čas bídy jejich, v čas dokonání nepravosti.'),
(1567611,54,26,35,6,'Protož živť jsem já, praví Panovník Hospodin, že k zabití připravím tě, a krev tě stihati bude. Poněvadž krve vylévání v nenávisti nemáš, také tě krev stihati bude.'),
(1567612,54,26,35,7,'Obrátím, pravím, horu Seir v hroznou poušť, a vypléním z ní jdoucího přes ni i vracujícího se.'),
(1567613,54,26,35,8,'A naplním hory její zbitými jejími; na pahrbcích tvých i v údolích tvých, i při všech potocích tvých zbití mečem padati budou.'),
(1567614,54,26,35,9,'V pustiny věčné obrátím tě, tak že města tvá nebudou zase vzdělána, i zvíte, že já jsem Hospodin.'),
(1567615,54,26,35,10,'Proto že říkáš: Tito dva národové a tyto dvě země mé budou, a budeme dědičně vládnouti tou, v níž Hospodin přebýval,'),
(1567616,54,26,35,11,'Protož živť jsem já, praví Panovník Hospodin, žeť učiním podlé hněvu tvého a podlé závisti tvé, kterouž jsi prokázala z nenávisti své proti nim. I budu poznán od nich, když tě budu souditi.'),
(1567617,54,26,35,12,'A zvíš, že já Hospodin slyšel jsem všecka hanění tvá, kteráž jsi mluvila o horách Izraelských, řkuci: Zpuštěnyť jsou, námť jsou dány k sežrání.'),
(1567618,54,26,35,13,'Nebo jste se honosili proti mně ústy svými, a množili proti mně slova svá, což jsem sám slyšel.'),
(1567619,54,26,35,14,'Takto praví Panovník Hospodin: Jakž se veselí všecka ta země, tak pustinu učiním z tebe.'),
(1567620,54,26,35,15,'Jakž se veselíš nad dědictvím domu Izraelského, proto že zpustl, tak učiním i tobě. Pustinou budeš, ó horo Seir, i všecka země Idumejská naskrze, i zvědíť, že já jsem Hospodin.'),
(1567621,54,26,36,1,'Ty synu člověčí, prorokuj i o horách Izraelských a rci: Hory Izraelské, slyšte slovo Hospodinovo.'),
(1567622,54,26,36,2,'Takto praví Panovník Hospodin: Proto že říká ten nepřítel o vás: Aj, to dobře, takéť i výsosti věčné v dědictví se nám dostanou,'),
(1567623,54,26,36,3,'Protož prorokuj a rci: Takto praví Panovník Hospodin: Proto, proto že poplénili a sehltili vás vůkol, abyste byli za dědictví ostatku národů, a vydáni jste v pomluvu a v zlou pověst lidem,'),
(1567624,54,26,36,4,'Protož hory Izraelské, slyšte slovo Panovníka Hospodina: Takto praví Panovník Hospodin horám i pahrbkům, potokům i údolím, pustinám hrozným i městům opuštěným, jenž jsou za loupež a posměch ostatku národů okolních,'),
(1567625,54,26,36,5,'Protož takto dí Panovník Hospodin: jistě že v ohni horlivosti své mluviti budu proti ostatku těch národů, i proti vší zemi Idumejské, kteříž sobě osobili zemi mou za dědictví, veselíce se z celého srdce, a pléníce s chutí, aby sídlo vyhnaných z něho bylo v loupež.'),
(1567626,54,26,36,6,'Protož prorokuj o zemi Izraelské, a mluv k horám a pahrbkům, potokům i k údolím: Takto praví Panovník Hospodin: Aj, já v horlivosti své a v prchlivosti své mluvím, proto že pohanění od národů snášíte.'),
(1567627,54,26,36,7,'Protož takto praví Panovník Hospodin: já zdvihna ruku svou, přisahám, že ti národové, kteříž jsou vůkol vás, pohanění své nésti musejí.'),
(1567628,54,26,36,8,'Vy pak hory Izraelské, ratolesti své vypouštěti, a ovoce své přinášeti budete lidu mému Izraelskému, když se přiblíží a přijdou.'),
(1567629,54,26,36,9,'Nebo aj, já jsem s vámi, a patřím na vás, abyste dělány a osívány byly.'),
(1567630,54,26,36,10,'A rozmnožím v vás lidi, všecken dům Izraelský, jakýžkoli jest, i budou se osazovati města, a pustiny vzdělávati.'),
(1567631,54,26,36,11,'Rozmnožím, pravím, v vás lidi i hovada, a budou se množiti a ploditi, i učiním, že bydliti budete jako za předešlých let vašich, čině vám dobře, více než v prvotinách vašich. A zvíte, že já jsem Hospodin.'),
(1567632,54,26,36,12,'Nebo uvedu do vás lidi, lid svůj Izraelský, a budou tebou dědičně vládnouti; a budeš jim za dědictví, aniž kdy více siroby na ně uvedeš.'),
(1567633,54,26,36,13,'Takto praví Panovník Hospodin: Proto že říkají vám, že jsi ty ta země, kteráž zžíráš lidi, a sirotky činíš z národů svých,'),
(1567634,54,26,36,14,'Protož nebudeš více zžírati lidi, a národů svých více k sirobě přivoditi, praví panovník Hospodin.'),
(1567635,54,26,36,15,'Aniž dopustím, aby více slýcháno bylo v tobě potupy národů, aniž útržky lidské snášeti budeš více, ani ku pádu přivoditi více národů svých, praví Panovník Hospodin.'),
(1567636,54,26,36,16,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567637,54,26,36,17,'Synu člověčí, dům Izraelský, bydlíce v zemi své, poškvrnili jí cestou svou a skutky svými; podobná nečistotě ženy pro nečistotu oddělené byla cesta jejich před očima mýma.'),
(1567638,54,26,36,18,'Pročež vylil jsem prchlivost svou na ně, proto že krev vylévali na zemi, a ukydanými bohy svými poškvrnili jí.'),
(1567639,54,26,36,19,'I rozptýlil jsem je po národech, tak že rozplašeni jsou po zemích; podlé cesty jejich a podlé skutků jejich soudil jsem je.'),
(1567640,54,26,36,20,'Nýbrž odšedše mezi národy, kamž přišli, poškvrnili jména svatosti mé, když říkáno o nich: Že jsou lid Hospodinův, a že z jeho země vyšli.'),
(1567641,54,26,36,21,'Ale slitoval jsem se pro jméno svatosti své, kteréhož poškvrnili dům Izraelský mezi národy, kamž přišli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567642,54,26,36,22,'Protož rci domu Izraelskému: Takto praví Panovník Hospodin: Ne pro vás já to učiním, ó dome Izraelský, ale pro jméno svatosti své, kteréhož jste poškvrnili mezi národy, kamž jste přišli,'),
(1567643,54,26,36,23,'Abych posvětil jména svého velikého, kteréž bylo poškvrněno mezi národy, kteréhož jste poškvrnili u prostřed nich, aby poznali národové, že já jsem Hospodin, praví Panovník Hospodin, když posvěcen budu v vás před očima jejich.'),
(1567644,54,26,36,24,'Nebo poberu vás z národů, a shromáždím vás ze všech zemí, a uvedu vás do země vaší.'),
(1567645,54,26,36,25,'A pokropím vás vodou čistou, a čisti budete; ode všech poškvrn vašich, i ode všech ukydaných bohů vašich očistím vás.'),
(1567646,54,26,36,26,'A dám vám srdce nové, a ducha nového dám do vnitřností vašich, a odejma srdce kamenné z těla vašeho, dám vám srdce masité.'),
(1567647,54,26,36,27,'Ducha svého, pravím, dám do vnitřností vašich, a učiním, abyste v ustanoveních mých chodili, a soudů mých ostříhali a činili je.'),
(1567648,54,26,36,28,'I budete bydliti v zemi, kterouž jsem byl dal otcům vašim, a budete lidem mým, a já budu vaším Bohem.'),
(1567649,54,26,36,29,'Nebo vysvobodím vás ze všelijakých poškvrn vašich, a přivolám obilé, a rozmnožím je, a nedopustím na vás hladu.'),
(1567650,54,26,36,30,'Rozmnožím i ovoce stromů a úrody polní, tak že neponesete více potupy hladu mezi národy.'),
(1567651,54,26,36,31,'I rozpomenete se na zlé cesty vaše a na skutky vaše nedobré, tak že sami se býti hodné ošklivosti uznáte pro nepravosti vaše a pro ohavnosti vaše.'),
(1567652,54,26,36,32,'Ne pro vás já to učiním, praví Panovník Hospodin, známo vám buď. Zahanbětež se a zastyďte za cesty své, dome Izraelský.'),
(1567653,54,26,36,33,'Takto praví Panovník Hospodin: V ten den, v kterémž vás očistím ode všech nepravostí vašich, osadím města, a vzdělány budou pustiny.'),
(1567654,54,26,36,34,'A tak země pustá bude dělána, kteráž prvé byla pouští před očima každého tudy jdoucího.'),
(1567655,54,26,36,35,'I řeknou: Země tato zpuštěná jest jako zahrada Eden, ano i města pustá, zkažená a zbořená jsou ohrazena a osazena.'),
(1567656,54,26,36,36,'I zvědí národové, kteříž pozůstanou vůkol vás, že já Hospodin vystavěl jsem zbořeniny, a vysadil pustiny. Já Hospodin mluvil jsem i učiním.'),
(1567657,54,26,36,37,'Takto praví Panovník Hospodin: Ještě toho hledati bude při mně dům Izraelský, abych je rozmnožil. Rozmnožím je lidmi jako stády.'),
(1567658,54,26,36,38,'Jako stádo k obětem, jako stádo Jeruzalémské při slavnostech jeho, tak města pustá budou plná stád lidí, i zvědí, že já jsem Hospodin.'),
(1567659,54,26,37,1,'Byla nade mnou ruka Hospodinova, a vyvedl mne Hospodin v duchu, a postavil mne u prostřed údolí, kteréž bylo plné kostí.'),
(1567660,54,26,37,2,'I provedl mne skrze ně vůkol a vůkol, a aj, bylo jich velmi mnoho v tom údolí, a aj, byly velmi suché.'),
(1567661,54,26,37,3,'I řekl mi: Synu člověčí, mohly-li by ožiti kosti tyto? I řekl jsem: Panovníče Hospodine, ty víš.'),
(1567662,54,26,37,4,'V tom řekl mi: Prorokuj o těch kostech a rci jim: Kosti suché, slyšte slovo Hospodinovo.'),
(1567663,54,26,37,5,'Toto praví Panovník Hospodin kostem těmto: Aj, já uvedu do vás ducha, abyste ožily.'),
(1567664,54,26,37,6,'A dám na vás žily, a učiním, že zroste na vás maso, a otáhnu vás koží; dám, pravím, do vás ducha, abyste ožily, i zvíte, že já jsem Hospodin.'),
(1567665,54,26,37,7,'Tedy prorokoval jsem tak, jakž mi rozkázáno bylo. I stal se zvuk, když jsem já prorokoval, a aj, hřmot, když se přibližovaly kosti jedna k druhé.'),
(1567666,54,26,37,8,'I viděl jsem, a aj, žily a maso na nich se ukázalo, i koží potaženy byly po vrchu, ale ducha žádného nebylo v nich.'),
(1567667,54,26,37,9,'I řekl mi: Prorokuj k duchu, prorokuj, synu člověčí, a rci duchu: Takto praví Panovník Hospodin: Ode čtyř větrů přiď, duchu, a věj na tyto zmordované, ať oživou.'),
(1567668,54,26,37,10,'Tedy prorokoval jsem, jakž mi rozkázal. I všel do nich duch, a ožili, a postavili se na nohách svých, zástup velmi veliký.'),
(1567669,54,26,37,11,'I řekl mi: Synu člověčí, kosti tyto jsou všecken dům Izraelský. Aj, říkají: Uschly kosti naše, a zhynula čáka naše, jižť jest po nás.'),
(1567670,54,26,37,12,'Protož prorokuj a rci jim: Takto praví Panovník Hospodin: Aj, já otevru hroby vaše, a vyvedu vás z hrobů vašich, lide můj, a uvedu vás do země Izraelské.'),
(1567671,54,26,37,13,'I zvíte, že já jsem Hospodin, když otevru hroby vaše, a vyvedu vás z hrobů vašich, lide můj.'),
(1567672,54,26,37,14,'A dám Ducha svého do vás, abyste ožili, a osadím vás v zemi vaší, i zvíte, že já Hospodin mluvím i činím, dí Hospodin.'),
(1567673,54,26,37,15,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567674,54,26,37,16,'Ty pak synu člověčí, vezmi sobě dřevo jedno, a napiš na něm: Judovi, a synům Izraelským, tovaryšům jeho. Zatím vezma dřevo druhé, napiš na něm: Jozefovi dřevo Efraimovo, a všechněm synům Izraelským, tovaryšům jeho.'),
(1567675,54,26,37,17,'I spojž je sobě jedno k druhému v jedno dřevo, aby byla jako jedno v ruce tvé.'),
(1567676,54,26,37,18,'A když mluviti budou k tobě synové lidu tvého, řkouce: Což nám neoznámíš, co ty věci znamenají:'),
(1567677,54,26,37,19,'Mluv k nim: Takto praví panovník Hospodin: Aj, já vezmu dřevo Jozefovo, kteréž jest v ruce Efraimově, a pokolení Izraelských, tovaryšů jeho, a přiložím je s ním k dřevu Judovu, a učiním je dřevem jedním, i budou jedno v ruce mé.'),
(1567678,54,26,37,20,'A když budou ta dřeva, na kterýchž jsi psal, v ruce tvé před očima jejich,'),
(1567679,54,26,37,21,'Tedy mluv k nim: Takto praví Panovník Hospodin: Aj, já vezmu syny Izraelské z prostřed národů těch, kamž odešli, a shromáždě je odevšad, uvedu je do země jejich.'),
(1567680,54,26,37,22,'A učiním je, aby byli národem jedním v té zemi na horách Izraelských, a král jeden bude nad nimi nade všemi králem. A nebudou více dva národové, aniž se již více děliti budou na dvoje království.'),
(1567681,54,26,37,23,'Aniž se budou poškvrňovati více ukydanými bohy svými, a ohavnostmi svými, ani jakými přestoupeními svými, i vysvobodím je ze všech obydlí jejich, v nichž hřešili, a očistím je. I budou mým lidem, a já budu jejich Bohem.'),
(1567682,54,26,37,24,'A služebník můj David bude králem nad nimi, a pastýře jednoho všickni míti budou, aby v soudech mých chodili, a ustanovení mých ostříhali, i činili je.'),
(1567683,54,26,37,25,'I budou bydliti v té zemi, kterouž jsem byl dal služebníku svému Jákobovi, v níž bydlili otcové vaši. Budou, pravím, v ní bydliti oni i synové jejich, i synové synů jejich až na věky, a David služebník můj knížetem jejich bude na věky.'),
(1567684,54,26,37,26,'Nadto učiním s nimi smlouvu pokoje; smlouva věčná bude s nimi. A rozsadím je, i rozmnožím je, a postavím svatyni svou u prostřed nich na věky.'),
(1567685,54,26,37,27,'Bude i příbytek můj mezi nimi, a budu jejich Bohem, a oni budou lidem mým.'),
(1567686,54,26,37,28,'I zvědí národové, že jsem já Hospodin, jenž posvěcuji Izraele, když bude svatyně má u prostřed nich na věky.'),
(1567687,54,26,38,1,'Opět stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1567688,54,26,38,2,'Synu člověčí, obrať tvář svou proti Gogovi, země Magog, knížeti a hlavě v Mešech a Tubal, a prorokuj proti němu,'),
(1567689,54,26,38,3,'A rci: Takto praví Panovník Hospodin: Aj, já budu proti tobě, Gogu, kníže a hlavo v Mešech a Tubal.'),
(1567690,54,26,38,4,'A odvedu tě zpět, dada udice do čelistí tvých, když tě vyvedu i všecko vojsko tvé, koně i jezdce, všecky oblečené v celou zbroj, zástup veliký s pavézami a štíty, všecky ty, kteříž užívají meče:'),
(1567691,54,26,38,5,'Perské, Mouřeníny i Putské s nimi, všecky ty s štíty a lebkami,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567692,54,26,38,6,'Gomera i všecky houfy jeho, dům Togarmy od stran půlnočních, i všecky houfy jeho, národy mnohé s tebou.'),
(1567693,54,26,38,7,'Budiž hotov, a připrav se, ty i všecko shromáždění tvé, těch, kteříž se k tobě sebrali, a buď strážcím jejich.'),
(1567694,54,26,38,8,'Po mnohých dnech navštíven budeš, v potomních letech přitáhneš na lid vysvobozený od meče, a shromážděný z národů mnohých na hory Izraelské, kteréž byly pustinou ustavičně, když oni z národů jsouce vyvedeni, budou bydliti bezpečně všickni.'),
(1567695,54,26,38,9,'V tom přitáhneš a přijdeš jako bouře, budeš jako oblak přikrývající zemi, ty i všickni houfové tvoji, i národové mnozí s tebou.'),
(1567696,54,26,38,10,'Takto praví Panovník Hospodin: I stane se v ten den, že vstoupí mnohé věci na srdce tvé, a budeš mysliti myšlení zlé.'),
(1567697,54,26,38,11,'A díš: Potáhnu na zemi, v níž jsou vsi, přitáhnu na ty, jenž pokoje užívají, bydlíce bezpečně, na všecky, kteříž bydlejí beze všech zdí, a nemají žádné závory ani bran,'),
(1567698,54,26,38,12,'Abych vzebral kořisti, a rozchvátal loupeže, obraceje ruku svou proti pouštěm již osazeným, a proti lidu zase shromážděnému z národů, zacházejícímu s dobytkem a jměním, bydlejícím u prostřed země.'),
(1567699,54,26,38,13,'Sába a Dedan, a kupci mořští, i všecka lvíčata jeho řeknou tobě: K rozebrání-liž kořistí ty se béřeš? K rozchvátání-li loupeže shromáždil jsi množství své, abys bral stříbro a zlato, abys nabral dobytka i zboží, a nashromáždil loupeže veliké?'),
(1567700,54,26,38,14,'Protož synu člověčí, prorokuj a rci Gogovi: Takto praví Panovník Hospodin: Zdaliž toho dne, když bude lid můj Izraelský bydliti bezpečně, nezvíš,'),
(1567701,54,26,38,15,'Kdyžto přitáhnouce z místa svého od stran půlnočních, ty i národové mnozí s tebou, sedíce na koních všickni, shromáždění veliké a vojsko znamenité,'),
(1567702,54,26,38,16,'Potáhneš na lid můj Izraelský jako oblak, abys přikryl tu zemi? V potomních dnech stane se, že tě přivedu na zemi svou, aby mne poznali národové, když posvěcen budu v tobě před očima jejich, ó Gogu.'),
(1567703,54,26,38,17,'Takto praví Panovník Hospodin: Zdaliž ty nejsi ten, o kterémž jsem mluvil za dnů starodávních skrze služebníky své, proroky Izraelské, kteříž prorokovali za těch dnů a let, že tě přivedu na ně?'),
(1567704,54,26,38,18,'A však stane se v ten den, v den, v kterýž přitáhne Gog na zemi Izraelskou, praví Panovník Hospodin, že povstane prchlivost má s hněvem mým,'),
(1567705,54,26,38,19,'A v rozhorlení svém, v ohni prchlivosti své mluviti budu. Jistě že v ten den bude pohnutí veliké v zemi Izraelské,'),
(1567706,54,26,38,20,'Tak že se pohnou před tváří mou ryby mořské i ptactvo nebeské, a zvěř polní i všeliký zeměplaz plazící se po zemi, i všickni lidé, kteříž jsou na svrchku země. I rozválejí se hory, a padnou výsosti, i každá zed na zem upadne.'),
(1567707,54,26,38,21,'Nebo zavolám proti němu po všech horách mých meče, praví Panovník Hospodin; meč každého proti bratru jeho bude.'),
(1567708,54,26,38,22,'A vykonám při něm soud morem a krve prolitím a přívalem rozvodnilým, a kamením krupobití velikého, ohněm a sirou dštíti budu na něj i na houfy jeho, a na národy mnohé, kteříž jsou s ním.'),
(1567709,54,26,38,23,'A tak zveleben, a posvěcen, a v známost uveden budu před očima národů mnohých, a zvědí, že já jsem Hospodin.'),
(1567710,54,26,39,1,'Ty synu člověčí, prorokuj ještě proti Gogovi a rci: Takto praví Panovník Hospodin: Aj, já povstanu proti tobě, ó Gogu, kníže a hlavo v Mešech a Tubal.'),
(1567711,54,26,39,2,'A odvedu tě zpět, navštívě tě šesti ranami, když tě vzbudím, abys přitáhl od stran půlnočních, a přivedu tě na hory Izraelské.'),
(1567712,54,26,39,3,'Nebo vyrazím lučiště tvé z ruky tvé levé, a střely z ruky tvé pravé vyvrhu.'),
(1567713,54,26,39,4,'Na horách Izraelských padneš ty i všickni houfové tvoji i národové, kteříž budou s tebou; ptákům a všemu ptactvu křídla majícímu i zvěři polní dám tě k sežrání.'),
(1567714,54,26,39,5,'Na svrchku pole padneš; neboť jsem já mluvil, praví Panovník Hospodin.'),
(1567715,54,26,39,6,'Vypustím také oheň na Magoga i na ty, kteříž přebývají na ostrovích bezpečně, i zvědíť, že já jsem Hospodin.'),
(1567716,54,26,39,7,'A jméno svatosti své uvedu v známost u prostřed lidu svého Izraelského. Nedopustím, pravím, více poškvrňovati jména svatosti své, i zvědíť národové, že já jsem Hospodin Svatý v Izraeli.'),
(1567717,54,26,39,8,'Aj, přijdeť a stane se to, praví Panovník Hospodin, téhož dne, o kterémž jsem mluvil.'),
(1567718,54,26,39,9,'Tehdy vyjdou obyvatelé měst Izraelských, a zapálíce, popálí zbroj a štíty i pavézy, lučiště i střely, dřevce i kopí, a budou je páliti ohněm sedm let.'),
(1567719,54,26,39,10,'Aniž nositi budou dříví s pole, ani sekati v lesích, proto že zbrojí zaněcovati budou oheň, když zloupí ty, kteříž je loupívali, a mocí poberou těm, kteříž jim mocí brávali, praví Panovník Hospodin.'),
(1567720,54,26,39,11,'I stane se v ten den, že dám Gogovi místo ku pohřbu tam v Izraeli, údolí, kudyž se jde k východní straně k moři, kteréžto zacpá ústa tudy jdoucích. I pohřbí tam Goga i všecko množství jeho, a nazovou je údolí množství Gogova.'),
(1567721,54,26,39,12,'Nebo pochovávati je budou dům Izraelský za sem měsíců proto, aby vyčistili zemi.'),
(1567722,54,26,39,13,'A tak pohřbí je všecken lid té země, a bude jim to ku poctivosti v den, v kterýž oslaven budu, praví Panovník Hospodin.'),
(1567723,54,26,39,14,'Oddělíť pak muže statečné, kteříž by procházeli tu zemi, proto aby pochovávali ty, kteříž by pozůstali na svrchku země, aby ji vyčistili. Po vyjití sedmi měsíců přehledávati začnou.'),
(1567724,54,26,39,15,'A ti procházejíce, choditi budou po zemi, a když uzří kosti člověčí, vzdělají při nich znamení pamětné, aby je pohřbili hrobaři v údolí množství Gogova.'),
(1567725,54,26,39,16,'Nýbrž to množství jeho bude k slávě i městu, když vyčistí tu zemi.'),
(1567726,54,26,39,17,'Ty pak synu člověčí, takto praví Panovník Hospodin: Rci ke všelijakým ptákům křídla majícím i ke všelijaké zvěři polní: Shromažďte se a přiďte, zbeřte se odevšad k obětem mým, kterýchž já nabiji vám,obětí velikých na horách Izraelských, a budete jísti maso a píti krev.'),
(1567727,54,26,39,18,'Maso silných reků jísti budete, a krev knížat zemských píti, skopců, beranů a kozlů, volků, všecko tučných Bázanských.'),
(1567728,54,26,39,19,'A budete jísti tuk do sytosti, a píti krev do opití z obětí mých, kterýchž vám nabiji.'),
(1567729,54,26,39,20,'A nasytíte se z stolu mého koňmi i jezdci, silnými reky i všemi muži válečnými, dí Panovník Hospodin.'),
(1567730,54,26,39,21,'A tak zjevím slávu svou mezi národy, aby viděli všickni národové soud můj, kterýž jsem vykonal, i ruku mou, kterouž jsem doložil na ně.'),
(1567731,54,26,39,22,'I zvíť dům Izraelský, že já jsem Hospodin Bůh jejich, od tohoto dne i potom.'),
(1567732,54,26,39,23,'Zvědí také i národové, že pro svou nepravost zajat jest dům Izraelský, proto že se dopouštěli přestoupení proti mně; pročež jsem skryl tvář svou před nimi, a vydal jsem je v ruku protivníků jejich, aby padli mečem všickni napořád.'),
(1567733,54,26,39,24,'Podlé nečistoty jejich a podlé zpronevěření se jejich učinil jsem jim, a skryl jsem tvář svou před nimi.'),
(1567734,54,26,39,25,'Z té příčiny takto praví Panovník Hospodin: Jižť zase přivedu zajaté Jákobovy, a smiluji se nade vším domem Izraelským a horliti budu příčinou jména svatosti své,'),
(1567735,54,26,39,26,'Ač ponesou potupu svou a všecko přestoupení své, kteréhož se dopustili proti mně, když bydlili v zemi své bezpečně, aniž byl, kdo by je přestrašil.'),
(1567736,54,26,39,27,'A však je zase přivedu z národů, a shromáždím je z zemí nepřátel jejich, a posvěcen budu v nich před očima národů mnohých.'),
(1567737,54,26,39,28,'A tak poznají, že já jsem Hospodin Bůh jejich, když zaveda je do národů, shromáždím je do země jejich, a nepozůstavím tam žádného z nich.'),
(1567738,54,26,39,29,'Aniž skryji více tváři své před nimi, když vyleji Ducha svého na dům Izraelský, praví Panovník Hospodin.'),
(1567739,54,26,40,1,'Dvadcátého pátého léta od zajetí našeho, na počátku roku, desátého dne měsíce, čtrnáctého léta po dobytí města, právě v tentýž den byla nade mnou ruka Hospodinova, a uvedl mne tam.'),
(1567740,54,26,40,2,'U viděních Božích přivedl mne do země Izraelské, a postavil mne na hoře velmi vysoké, při níž bylo jako stavení města, ku poledni.'),
(1567741,54,26,40,3,'I uvedl mne tam, a aj, muž, kterýž na pohledění byl jako měď, maje šňůru lněnou v ruce své, a prut k rozměřování, a ten stál v bráně.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567742,54,26,40,4,'I mluvil ke mně ten muž: Synu člověčí, viz očima svýma, a ušima svýma slyš, a přilož srdce své ke všemu, což já ukáži tobě; nebo proto aťbych ukazoval, přiveden jsi sem. Ty pak oznámíš všecko domu Izraelskému, což vidíš.'),
(1567743,54,26,40,5,'A aj, zed zevnitř při domu vůkol a vůkol, a v ruce muže toho prut míry, šesti loket, (loket o dlaň delší než obecní). Změřil šířku toho stavení jednoho prutu, a výšku jednoho prutu.'),
(1567744,54,26,40,6,'A všed do brány, kteráž byla naproti východu, šel na horu po stupních jejích, i změřil prah brány jednoho prutu zšíří, a prah druhý jednoho prutu zšíří.'),
(1567745,54,26,40,7,'A pokojíky jednoho prutu zdélí, a jednoho prutu zšíří, mezi pokojíky pak pět loket, a prah brány podlé síňce brány vnitř prutu jednoho.'),
(1567746,54,26,40,8,'I změřil síňci brány vnitř na jeden prut.'),
(1567747,54,26,40,9,'Změřil také síňci brány osmi loket, a veřeje její dvou loket, totiž síňce brány vnitř.'),
(1567748,54,26,40,10,'I pokojíky brány východní, tři s jedné a tři s druhé strany. Jedné míry byly všecky tři, a míra jednostejná veřejí po obou stranách.'),
(1567749,54,26,40,11,'Změřil též i širokost dveří té brány desíti loket, a dlouhost též brány třinácti loket,'),
(1567750,54,26,40,12,'A přístřeší před pokojíky jednoho lokte, a na jeden loket přístřeší s této strany, pokojíky pak šesti loket s jedné, a šesti loket s druhé strany.'),
(1567751,54,26,40,13,'A tak změřil bránu od střechy pokojíka do střechy druhého, širokost pětmecítma loket, dvéře naproti dveřím.'),
(1567752,54,26,40,14,'A udělal veřeje šedesáti loket, a každé veřeje síně i brány vůkol a vůkol jedna míra.'),
(1567753,54,26,40,15,'Od předku pak brány, kudyž se vchází do předku síňce brány vnitřní, bylo padesáte loket.'),
(1567754,54,26,40,16,'A byla okna possoužená v pokojících i nad veřejemi jejich, do vnitřku brány vůkol a vůkol, takž i při klenutí, a na okních vůkol a vůkol do vnitřku, a na veřejích byly palmy.'),
(1567755,54,26,40,17,'Potom mne uvedl do síně zevnitřní, a aj, komůrky a půda udělaná při síni vůkol a vůkol. Třidceti komůrek na té půdě bylo.'),
(1567756,54,26,40,18,'Ta pak půda po straně těch bran, naproti dlouhosti bran, půda nižší byla.'),
(1567757,54,26,40,19,'Změřil také šířku od předku brány dolejší až k předku síně vnitřní, zevnitř na sto loket k východu a půlnoci.'),
(1567758,54,26,40,20,'Též bránu, kteráž byla na půlnoci při síni zevnitřní, změřil na dél i na šíř.'),
(1567759,54,26,40,21,'(Jejíž pokojíkové tři s jedné a tři s druhé strany, i veřeje její i síňce její byly podlé míry brány prvnější.) Padesáti loket dlouhost její, širokost pak pětmecítma loket.'),
(1567760,54,26,40,22,'Okna také její i síňce její i palmy její byly podlé míry brány té, kteráž byla k východu, a vstupovalo se k ní po sedmi stupních, před nimiž síňce její byly.'),
(1567761,54,26,40,23,'A byla ta brána u síně vnitřní naproti bráně půlnoční a východní; i odměřil od brány k bráně sto loket.'),
(1567762,54,26,40,24,'Potom mne vedl ku poledni, a aj, brána ku poledni; i změřil veřeje její, i síňce její podlé těch měr,'),
(1567763,54,26,40,25,'(A okna v ní i síňce její vůkol a vůkol podobná oknům oněm), padesáti loket zdélí a pětmecítma loket zšíří.'),
(1567764,54,26,40,26,'A k vstupování k ní stupňů sedm, a síňce její před nimi; též palmy při ní, jedna s jedné a druhá s druhé strany při veřejích jejích.'),
(1567765,54,26,40,27,'Též bránu síně vnitřní ku poledni změřil od brány k bráně, na poledne, sto loket.'),
(1567766,54,26,40,28,'I uvedl mne do síně vnitřní branou polední, a změřil tu bránu polední podlé týchž měr,'),
(1567767,54,26,40,29,'I pokojíky její i veřeje její, i síňce její podlé týchž měr, i okna její i síňce její vůkol a vůkol, padesáti loket na dél, a na šíř pětmecítma loket.'),
(1567768,54,26,40,30,'A síňce vůkol a vůkol zšíří pětmecítma loket, a zdélí padesáti loket.'),
(1567769,54,26,40,31,'A síňce její jako síň zevnitřní, i palmy při veřejích jejích, též stupňů osm k vstupování k ní.'),
(1567770,54,26,40,32,'Uvedl mne také do síně vnitřní k východu, i změřil bránu tu podlé týchž měr,'),
(1567771,54,26,40,33,'Též pokojíky její i veřeje její, i síňce její, podlé týchž měr, i okna její i síňce její vůkol a vůkol, zdélí padesáti loket, zšíří pak pětmecítma loket.'),
(1567772,54,26,40,34,'Též síňce její při síni zevnitřní, a palmy při veřejích s obou stran, a osm stupňů k vstupování k ní.'),
(1567773,54,26,40,35,'Přivedl mne též k bráně půlnoční, a změřil ji podlé týchž měr,'),
(1567774,54,26,40,36,'Pokojíky její, veřeje její i síňce její i okna její vůkol a vůkol, zdélí padesáti loket, a zšíří pětmecítma loket.'),
(1567775,54,26,40,37,'I veřeje její při síni zevnitřní a palmy při veřejích s obou stran, též osm stupňů k vstupování k ní,'),
(1567776,54,26,40,38,'I komůrky a dvéře její při veřejích bran, kdež obmývali oběti zápalné.'),
(1567777,54,26,40,39,'A v síňci brány byli dva štokové s jedné strany, a dva štokové s druhé strany, aby na nich zabíjeli oběti zápalné, a za hřích i vinu.'),
(1567778,54,26,40,40,'A po boku, kudyž se tam vstupuje při dveřích brány půlnoční, dva štokové; tolikéž po boku druhém síňce též brány dva štokové.'),
(1567779,54,26,40,41,'Čtyři štokové s jedné, a čtyři štokové s druhé strany po boku brány, osm štoků, na nichž zabíjeli.'),
(1567780,54,26,40,42,'Čtyři pak štokové k zápalu byli z kamení tesaného, zdélí půldruhého lokte, a zšíří půldruhého lokte, a zvýší lokte jednoho, na nichž nechávali nádobí, kterýmž zabíjeli k zápalům a obětem.'),
(1567781,54,26,40,43,'A kotliska ztlouští na jednu dlaň připravená v domě vůkol a vůkol, na štocích pak maso věcí obětovaných.'),
(1567782,54,26,40,44,'Potom zevnitř, při bráně vnitřní, komůrky zpěváků v síni vnitřní, kteráž byla po boku brány půlnoční, a ty byly na poledne; jedna při boku brány východní byla na půlnoci.'),
(1567783,54,26,40,45,'I mluvil ke mně: Tyto komůrky na poledne jsou kněží stráž držících nad domem;'),
(1567784,54,26,40,46,'Ty pak komůrky na půlnoci jsou kněží stráž držících nad oltářem, totiž synů Sádochových, kteříž přistupují z synů Léví k Hospodinu, aby sloužili jemu.'),
(1567785,54,26,40,47,'I změřil tu síň čtverhranou zdélí sto loket, a zšíří sto loket, i oltář před domem.'),
(1567786,54,26,40,48,'I přivedl mne k síňci domu, a změřil veřeje té síňce, pěti loket s jedné a pěti loket s druhé strany, širokost pak brány byla tří loket s jedné a tří loket s druhé strany.'),
(1567787,54,26,40,49,'Dlouhost síňce dvadcíti loket, širokost pak jedenácti loket i s stupni, po nichž se vstupovalo k ní; sloupové pak byli při veřejích, jeden s jedné, a druhý s druhé strany.'),
(1567788,54,26,41,1,'Opět přivedl mne k chrámu, a změřil veřeje, šesti loket zšíří s jedné strany, a šesti loket zšíří s druhé strany, podlé širokosti stánku.'),
(1567789,54,26,41,2,'A širokost dveří desíti loket, boky pak dveří pěti loket s jedné a pěti loket s druhé strany. Změřil také i dlouhost jejich čtyřidcíti loket, širokost pak dvadcíti loket.'),
(1567790,54,26,41,3,'Přišel také do vnitřku, a změřil veřeje dveří dvou loket, a dvéře šesti loket, širokost pak dveří sedmi loket.'),
(1567791,54,26,41,4,'Změřil také dlouhost svatyně dvadcíti loket, a širokost dvadcíti loket v chrámě, a řekl mi: Tato jest svatyně svatých.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567792,54,26,41,5,'Změřil též zed domu šesti loket, a širokost pavlače čtyř loket, vůkol a vůkol okolo domu.'),
(1567793,54,26,41,6,'Ty pak pavlače, pavlač nad pavlačí, byly tři, a třidcíti noh zdélí, a scházely se při zdi domu vespolek, tak že se pavlače vůkol a vůkol držely, a nedržely se na zdi domu.'),
(1567794,54,26,41,7,'Nebo se rozšiřovala vůkol více a více, svrchu pro pavlače, kteréž byly okolo domu, od vrchu až dolů, vůkol a vůkol domu, poněvadž nejširší dům byl na hoře, a tak nejnižší porozšiřovala se k vrchu pro prostřední.'),
(1567795,54,26,41,8,'Tak podobně spatřil jsem při domu pavlače, i nejvyšší vůkol a vůkol, jejichž půdy zouplna odměřeny byly šesti loket k výstupkům.'),
(1567796,54,26,41,9,'Širokost zdi, kteráž byla při pavlačích zevnitř, pěti loket byla, i plac pavlačí, kteréž byly při domu.'),
(1567797,54,26,41,10,'Mezi nimiž a komůrkami byla širokost dvadcíti loket okolo domu vůkol a vůkol.'),
(1567798,54,26,41,11,'A dvéře pavlačí byly k placu, dvéře jedny na půlnoci, a druhé dvéře na poledne, a širokost placu byla pěti loket vůkol a vůkol.'),
(1567799,54,26,41,12,'Stavení pak, kteréž bylo před příhradkem v úhlu k západu, širokost byla sedmdesáti loket, a zed téhož stavení pěti loket zšíří vůkol a vůkol, a zdélí devadesáti loket.'),
(1567800,54,26,41,13,'Potom změřil dům, zdélí sto loket, totiž příhradek i stavení, a zdi jeho zdélí sto loket.'),
(1567801,54,26,41,14,'Též širokost předku domu i příhradku k východu sto loket.'),
(1567802,54,26,41,15,'Změřil i dlouhost stavení před příhradkem, kteréž bylo za ním, též i paláce jeho s jedné i s druhé strany, a bylo sto loket; též chrám vnitř i síňce s síní,'),
(1567803,54,26,41,16,'Prahy i okna possoužená, i paláce vůkol po třech stranách jejich, naproti prahu taflování dřevěné vůkol a vůkol, i od země až do oken, též i okna otaflovaná,'),
(1567804,54,26,41,17,'Od svrchku dveří až do vnitřní i zevnitřní strany domu, i všecku zed vůkol a vůkol vnitř i zevnitř změřené.'),
(1567805,54,26,41,18,'Kteréž taflování bylo uděláno s cherubíny a palmami, a to vše palma mezi cherubínem a cherubínem. A cherubín měl dvě tváře.'),
(1567806,54,26,41,19,'Totiž tvář lidskou naproti palmě s jedné strany, a tvář lvíčete naproti palmě s druhé strany. Tak uděláno bylo ve všem domu vůkol a vůkol.'),
(1567807,54,26,41,20,'Od země až do vrchu dveří cherubínové a palmy zdělány byly i na zdi chrámu.'),
(1567808,54,26,41,21,'Chrámu veřeje byly čtverhrané, a předek svatyně podobný jemu.'),
(1567809,54,26,41,22,'Oltář dřevěný tří loket zvýší, zdélí pak dvou loket s úhly svými, jehož dlouhost i pobočnice jeho dřevěné byly. I mluvil ke mně: Tento jest stůl, kterýž stojí před Hospodinem.'),
(1567810,54,26,41,23,'A dvojnásobní dvéře byly u chrámu i u svatyně,'),
(1567811,54,26,41,24,'A dvojnásobní dvéře ve vratech, totiž dvojnásobní dvéře obracející se, dvojnásobní ve vratech jedněch, a dvojnásobní dvéře v druhých.'),
(1567812,54,26,41,25,'Byli pak uděláni na nich, na těch dveřích chrámu, cherubínové a palmy, tak jakž uděláni byli na stěnách, trámové také dřevění byli před síňcí vně.'),
(1567813,54,26,41,26,'Též na oknech possoužených byly palmy s obou stran po bocích síňce, i na pavlačích domu toho i trámích.'),
(1567814,54,26,42,1,'Potom mne vyvedl k síni zevnitřní, kteráž byla na půlnoci, a přivedl mne k těm komůrkám, kteréž byly před příhradkem, a kteréž byly naproti stavení na půlnoci,'),
(1567815,54,26,42,2,'Jehož délka při dveřích půlnočních na pohledění byla sto loket, a šířka padesát loket.'),
(1567816,54,26,42,3,'Naproti síni vnitřní, kteráž měla dvadceti loket, a naproti dlážení, kteréž bylo v síni zevnitřní, byl palác naproti paláci třmi řady.'),
(1567817,54,26,42,4,'Před komůrkami pak byli pláckové desíti loket zšíří vnitř, cesta k nim lokte jednoho, a dvéře jejich na půlnoci.'),
(1567818,54,26,42,5,'Komůrky pak nejvyšší byly užší, proto že palácové byli širší než ony, nežli nejzpodnější a prostřední stavení.'),
(1567819,54,26,42,6,'Nebo o trojím ponebí bylo, ale nemělo žádných sloupů, jacíž byli sloupové síní; protož užší bylo nežli dolejší i než prostřední od země.'),
(1567820,54,26,42,7,'Ohrady pak, kteráž byla vně naproti komůrkám k síni zevnitřní, před komůrkami, dlouhost byla padesáti loket.'),
(1567821,54,26,42,8,'Nebo dlouhost komůrek, kteréž byly v síni zevnitřní, byla padesáti loket, před chrámem pak sto loket.'),
(1567822,54,26,42,9,'Pod těmi pak komůrkami bylo vcházení od východu, skrze kteréž by se vcházelo do nich z síně té zevnitřní.'),
(1567823,54,26,42,10,'Na šíř ohrady té síně k východu před příhradkem i před stavením byly komůrky.'),
(1567824,54,26,42,11,'Cesta pak před nimi byla podobná cestě komůrek, kteréž byly na půlnoci. Jakáž byla dlouhost jejich, tak širokost jejich, a všecka vycházení jejich i dvéře jejich podobná oněmno.'),
(1567825,54,26,42,12,'A dvéře těch komůrek, kteréž byly na poledne, podobné byly dveřím při začátku cesty, cesty před ohradou přímou k východu, kudyž se vchází do nich.'),
(1567826,54,26,42,13,'I řekl mi: Komůrky na půlnoci a komůrky na poledne, kteréž jsou před příhradkem, jsou komůrky svaté, kdežto jídají kněží, kteříž přistupují k Hospodinu, věci nejsvětější. Tam nechávati budou věcí nejsvětějších a obětí suchých, též za hřích a za vinu; nebo to místo svaté jest.'),
(1567827,54,26,42,14,'Když tam vejdou kněží, tedy nevyjdou z svatyně do síně zevnitřní, leč tam nechají roucha svého, v němž přisluhovali; nebo svaté jest. A oblekou roucha jiná, když budou míti přistupovati k tomu, což se dotýče lidu.'),
(1567828,54,26,42,15,'A dokonav rozměřování domu vnitřního, i vedl mne k bráně, kteráž byla na východ, a změřil jej vůkol a vůkol.'),
(1567829,54,26,42,16,'Změřil stranu východní prutem, pět set loket prutových tím prutem vůkol.'),
(1567830,54,26,42,17,'Změřil stranu půlnoční tím prutem, pět set prutů vůkol.'),
(1567831,54,26,42,18,'Změřil stranu polední tím prutem, pět set prutů.'),
(1567832,54,26,42,19,'A obrátiv se k straně západní, naměřil tím prutem pět set prutů.'),
(1567833,54,26,42,20,'Na čtyři strany změřil to, totiž zed vůkol a vůkol, zdélí pěti set, a zšíří pěti set, aby dělila svaté místo od obecného.'),
(1567834,54,26,43,1,'Potom vedl mne k bráně, kterážto brána patřila k východu.'),
(1567835,54,26,43,2,'A aj, sláva Boha Izraelského přicházela od východu, jejíž zvuk byl jako zvuk vod mnohých, a země svítila se od slávy jeho.'),
(1567836,54,26,43,3,'A podobné bylo to vidění, kteréž jsem viděl, právě tomu vidění, kteréž jsem byl viděl, když jsem šel, abych kazil město, vidění, pravím, podobná vidění onomu, kteréž jsem viděl při řece Chebar. I padl jsem na tvář svou.'),
(1567837,54,26,43,4,'A když sláva Boží vcházela do domu, cestou brány patřící k východu,'),
(1567838,54,26,43,5,'Tedy pojal mne Duch, a uvedl mne do síně vnitřní, a aj, dům plný byl slávy Hospodinovy.'),
(1567839,54,26,43,6,'I slyšel jsem, an mluví ke mně z domu, a muž stál podlé mne.'),
(1567840,54,26,43,7,'I řekl mi: Synu člověčí, místo stolice mé a místo šlepějí noh mých, kdežto bydliti budu u prostřed synů Izraelských na věky, a nebudou poškvrňovati více dům Izraelský jména svatosti mé, oni ani králové jejich smilstvím svým a mrtvými těly králů svých, ani výsostmi svými,'),
(1567841,54,26,43,8,'Když kladli prah svůj podlé prahu mého, a veřeji svou podlé veřeje mé, a stěnu mezi mnou a mezi sebou, a tak poškvrňovali jména svatosti mé ohavnostmi svými, kteréž páchali, pročež jsem je sehltil v hněvě svém.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567842,54,26,43,9,'Ale nyní vzdálí smilství svá i mrtvá těla králů svých, ode mne, a budu bydliti u prostřed nich na věky.'),
(1567843,54,26,43,10,'Ty synu člověčí, oznam domu Izraelskému o tomto domu, a nechť se zahanbí pro nepravosti své, a ať změří všecko naskrze.'),
(1567844,54,26,43,11,'A když se hanbiti budou za všecko, což páchali, způsob domu i formu jeho, i vycházení jeho, též vcházení jeho, i všecky způsoby jeho, všecka ustanovení jeho, všecky, pravím, způsoby jeho i všecky zákony jeho v známost jim uveď, a napiš před očima jejich, ať ostříhají všeho způsobu jeho i všech ustanovení jeho a činí je.'),
(1567845,54,26,43,12,'Tento jest zákon toho domu: Na vrchu hory všecko obmezení jeho vůkol a vůkol, nejsvětějšíť jest. Aj, ten jest zákon toho domu.'),
(1567846,54,26,43,13,'Tyto pak jsou míry oltáře na též lokty, o dlaň delší: Předně zpodek lokte zvýší a lokte zšíří, obruba pak jeho při kraji jeho vůkol pídi jedné. Takový jest výstupek oltáře,'),
(1567847,54,26,43,14,'Totiž od zpodku při zemi až do přepásaní dolejšího dva lokty, širokost pak lokte jednoho, a od přepásání menšího až do přepásaní většího čtyři lokty, širokost též na loket.'),
(1567848,54,26,43,15,'Ale sám oltář ať jest čtyř loket, a z oltáře zhůru čtyři rohové.'),
(1567849,54,26,43,16,'Oltář pak dvanácti loket zdélí a dvanácti zšíří, čtyřhranatý po čtyřech stranách svých.'),
(1567850,54,26,43,17,'Přepásaní pak čtrnácti loket zdélí a čtrnácti zšíří po čtyřech stranách jeho, a obruba vůkol něho na půl lokte, a zpodek při něm na loket vůkol, a stupňové jeho naproti východu.'),
(1567851,54,26,43,18,'I řekl ke mně: Synu člověčí, takto praví Panovník Hospodin: Ta jsou ustanovení oltáře v den, v kterýž bude udělán, k obětování na něm zápalů a kropení na něj krví.'),
(1567852,54,26,43,19,'Nebo dáš kněžím Levítským, kteříž jsou z semene Sádochova, kteříž přistupují ke mně, dí Panovník Hospodin, aby mi sloužili, volka mladého za hřích.'),
(1567853,54,26,43,20,'A nabera krve jeho, dáš na čtyři rohy jeho, i na čtyři úhly toho přepásaní, i na obrubu vůkol, a tak jej očistíš i vyčistíš.'),
(1567854,54,26,43,21,'A vezmeš toho volka za hřích, i spálí jej na místě uloženém v tom domě, vně před svatyní.'),
(1567855,54,26,43,22,'V den pak druhý obětovati budeš kozla bez poškvrny za hřích, a očistí oltář, tak jakž vyčistili volkem.'),
(1567856,54,26,43,23,'A když dokonáš očišťování, obětuj volka mladého bez vady, a skopce z stáda bez poškvrny.'),
(1567857,54,26,43,24,'Kteréž když obětovati budeš před Hospodinem, uvrhou kněží na ně soli, a budou je obětovati v zápal Hospodinu.'),
(1567858,54,26,43,25,'Po sedm dní obětuj kozla za hřích, na každý den; též i volka mladého a skopce z stáda bez poškvrny obětovati budou.'),
(1567859,54,26,43,26,'Sedm dní očišťovati budou oltář, a vyčistí jej, a posvětí ruky své.'),
(1567860,54,26,43,27,'A když vyplní ty dny, osmého dne i potom obětovati budou kněží na oltáři zápaly vaše, a pokojné oběti vaše, i přijmu vás laskavě, praví Panovník Hospodin.'),
(1567861,54,26,44,1,'Tedy přivedl mne zase cestou k bráně svatyně zevnitřní, kteráž patří k východu, a ta byla zavřená.'),
(1567862,54,26,44,2,'I řekl ke mně Hospodin: Brána tato zavřená bude, nebudeť otvírána, aniž kdo bude vcházeti skrze ni. Nebo Hospodin Bůh Izraelský všel skrze ni; protož budeť zavřená.'),
(1567863,54,26,44,3,'Knížecí jest, kníže samo v ní sedati bude, aby jídalo chléb před Hospodinem. Cestou síně této brány vejde, a cestou její vyjde.'),
(1567864,54,26,44,4,'I vedl mne cestou k bráně půlnoční, k přední straně domu, i viděl jsem, a aj, naplnila sláva Hospodinova dům Hospodinův. I padl jsem na tvář svou.'),
(1567865,54,26,44,5,'I řekl ke mně Hospodin: Synu člověčí, přilož srdce své, a viz očima svýma, i ušima svýma slyš, cožkoli já mluvím tobě o všech ustanoveních domu Hospodinova, i o všech zákonech jeho. Přilož, pravím, srdce své k vcházení do domu, i ke všemu vycházení z svatyně,'),
(1567866,54,26,44,6,'A rci zpurnému domu Izraelskému: Takto praví Panovník Hospodin: Dosti mějte na všech ohavnostech svých, ó dome Izraelský,'),
(1567867,54,26,44,7,'Že jste uvodili cizozemce neobřezaného srdce a neobřezaného těla, aby bývali v svatyni mé, a poškvrňovali i domu mého, když jste obětovali chléb můj, tuk i krev, ješto oni sic rušili smlouvu mou, mimo všecky ohavnosti vaše,'),
(1567868,54,26,44,8,'A nedrželi jste stráže nad svatými věcmi mými, ale postavili jste strážné na stráži mé, v svatyni mé místo sebe.'),
(1567869,54,26,44,9,'Takto praví Panovník Hospodin: Žádný cizozemec neobřezaného srdce a neobřezaného těla nevejde do svatyně mé, ze všech cizozemců, kteříž mezi syny Izraelskými jsou.'),
(1567870,54,26,44,10,'Nýbrž i Levítové, kteříž se vzdalovali ode mne, když bloudil Izrael, kteříž zbloudili ode mne za ukydanými bohy svými, ponesou nepravost svou.'),
(1567871,54,26,44,11,'Nebo budou v svatyni mé za služebníky, v povinnostech při branách domu, a za slouhy při domu. Oni budou zabíjeti oběti zápalné i oběti lidu, a oni stávati budou před nimi k sloužení jim,'),
(1567872,54,26,44,12,'Proto že přisluhovali jim před ukydanými bohy jejich, a byli domu Izraelskému příčinou pádu v nepravost. Pročež přisáhl jsem jim, praví Panovník Hospodin, že ponesou nepravost svou.'),
(1567873,54,26,44,13,'Aniž přistoupí ke mně, aby mi kněžský úřad konali, ovšem aby přistupovati měli k kterým svatým věcem mým, neb k nejsvětějším, ale ponesou pohanění své i ohavnosti své, kteréž páchali.'),
(1567874,54,26,44,14,'Protož postavím je za strážné u domu, ke vší službě jeho i ke všemu, což činěno býti má v něm.'),
(1567875,54,26,44,15,'Kněží pak Levítští, synové Sádochovi, kteříž drželi stráž nad svatyní mou, když zbloudili synové Izraelští ode mne, ti budou přistupovati ke mně, aby mi přisluhovali, a státi před tváří mou, obětujíce mi tuk i krev, praví Panovník Hospodin.'),
(1567876,54,26,44,16,'Ti přicházeti budou k svatyni mé, a ti přistupovati k stolu mému, aby mi sloužili a drželi stráž mou.'),
(1567877,54,26,44,17,'I stane se, když budou míti vcházeti do bran síně vnitřní, že roucha lněná oblekou, aniž na se vezmou vlněného, když by služby konati měli v branách síně vnitřní i u vnitřku.'),
(1567878,54,26,44,18,'Klobouky lněné míti budou na hlavě své, a košilky lněné ať mají na bedrách svých, a nepřepasují se ničímž, což by pot vyvodilo.'),
(1567879,54,26,44,19,'A majíce vyjíti do síně zevnitřní, do síně zevnitřní k lidu, svlekou roucha svá, v kterýchž služby konali, a nechají jich v komůrkách svatyně, a oblekou roucha jiná, a nebudou posvěcovati lidu rouchem svým.'),
(1567880,54,26,44,20,'Aniž hlavy své holiti budou, ani vlasů nositi, ale slušně ostříhají vlasy své.'),
(1567881,54,26,44,21,'Vína též nebude píti žádný z kněží, když budou míti vcházeti do síně vnitřní.'),
(1567882,54,26,44,22,'Vdovy také aneb zahnané nebudou sobě pojímati za manželky, ale panny z semene domu Izraelského, aneb vdovu, kteráž by ovdověla po knězi, pojíti mohou.'),
(1567883,54,26,44,23,'A lid můj budou rozdílu učiti mezi svatým a nesvatým, též mezi nečistým a čistým ať je učí rozeznávati.'),
(1567884,54,26,44,24,'V rozepři pak ať se postavují k souzení, a podlé soudu mého soudí ji. Zákonů mých i ustanovení mých při všech slavnostech mých ať ostříhají, a soboty mé světí.'),
(1567885,54,26,44,25,'K mrtvému pak člověku nepůjde, aby se poškvrniti měl, leč při otci neb při mateři, též při synu a při dceři, při bratru a sestře, kteráž nebyla za mužem, může se poškvrniti.'),
(1567886,54,26,44,26,'Po očištění pak jeho (sedm dní odečtou jemu),'),
(1567887,54,26,44,27,'V ten den, v kterýž vejde do svatyně, do síně vnitřní, aby služby konal v svatyni, obětovati bude za hřích svůj, praví Panovník Hospodin.'),
(1567888,54,26,44,28,'Dědictví pak jejich toto: Já jsem dědictví jejich, protož vládařství nedávejte jim v Izraeli; já jsem vládařství jejich.'),
(1567889,54,26,44,29,'Oběti suché a za hřích i vinu, to oni jísti budou, i všelijaká věc, oddána Bohu v Izraeli, jejich bude.'),
(1567890,54,26,44,30,'I přední věci všech prvotin ze všeho, i každá obět zhůru pozdvižení všeliké věci, ze všech obětí zhůru pozdvižení vašich, kněžské bude. I prvotiny těsta vašeho dávati budete knězi, aby odpočinulo požehnání v domě tvém.'),
(1567891,54,26,44,31,'Žádné mrchy a udáveného, ani z ptactva ani z hovad nebudou jídati kněží.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567892,54,26,45,1,'Když pak ujmete zemi v dědictví, obětovati budete obět Hospodinu, díl svatý té země, zdélí pětmecítma tisíc loket, zšíří pak deset tisíc, a budeť svatý po všem pomezí svém vůkol.'),
(1567893,54,26,45,2,'Z něhož bude místo svaté pět set zdélí, a pět set zšíří, čtyřhrané vůkol, a ať má padesáte loket prostranství vůkol.'),
(1567894,54,26,45,3,'Z toho pak odměření odměříš dýlku pětmecítma tisíc loket, a šířku deset tisíc, aby na něm byla svatyně, i svatyně svatých.'),
(1567895,54,26,45,4,'Díl ten země svatý jest. Kněží služebníků při svatyni býti má, těch, kteříž přistupují, aby přisluhovali Hospodinu, aby měli místo pro domy i místo svaté pro svatyni.'),
(1567896,54,26,45,5,'Těch pak pětmecítma tisíc loket dýlka a deset tisíc šířka ať jest také Levítům, služebníkům domu, jim k držení dvadceti komůrek.'),
(1567897,54,26,45,6,'Místo pak k vystavení na něm města oddělíte pět tisíc loket na šíř, a na dýl pětmecítma tisíc, naproti oběti místa svatého; bude pro všecken dům Izraelský.'),
(1567898,54,26,45,7,'Knížeti pak s obou stran té oběti místa svatého, i položení města před oběti místa svatého, a před položením města od strany západní díl k západu, a po straně východní díl k východu, dlouhost pak naproti každému z těch dílů od pomezí západního ku pomezí východnímu.'),
(1567899,54,26,45,8,'To bude míti za vládařství v Izraeli, a nebudou více utiskati knížata má lidu mého, ale rozdadí zemi domu Izraelskému po pokoleních jejich.'),
(1567900,54,26,45,9,'Takto praví Panovník Hospodin: Dostitě již, ó knížata Izraelská, nátisk a zhoubu odložte, a soud a spravedlnost konejte, sejměte těžké roboty vaše s lidu mého, praví Panovník Hospodin.'),
(1567901,54,26,45,10,'Váhu spravedlivou a efi spravedlivou i bát spravedlivý míti budete.'),
(1567902,54,26,45,11,'Efi i bát v jednu míru ať jest, aby chomer bral v se deset bátů, efi pak desátý díl chomeru; podlé chomeru ať jest míra.'),
(1567903,54,26,45,12,'Lot dvadceti peněz; dvadceti lotů, pětmecítma lotů, a patnácte lotů libra bude vám.'),
(1567904,54,26,45,13,'Tato pak obět pozdvižení bude, kterouž obětovati budete: Šestý díl efi z chomeru pšenice, též šestý díl efi dáte z chomeru ječmene.'),
(1567905,54,26,45,14,'Nařízení pak o oleji (bát jest míra oleje): Desátý díl bátu z míry chomeru, desíti bátů; nebo deset bátů jest chomer.'),
(1567906,54,26,45,15,'A dobytče jedno ze dvou set bravů z dobrých pastvišť Izraelských, k oběti suché a zápalné a k obětem pokojným, k očištění vás, praví Panovník Hospodin.'),
(1567907,54,26,45,16,'Všecken lid té země, i s knížetem Izraelským zavázán bude k té oběti zhůru pozdvižení.'),
(1567908,54,26,45,17,'Nebo kníže povinen bude zápaly, a suché i mokré oběti, v svátky a na novměsíce, i v soboty, na všecky slavnosti domu Izraelského; on obětovati bude za hřích, i obět suchou i zápalnou, i oběti pokojné, aby se očištění dálo za dům Izraelský.'),
(1567909,54,26,45,18,'Takto praví Panovník Hospodin: Prvního měsíce, prvního dne vezmeš volka mladého bez poškvrny, kterýmž očistíš svatyni.'),
(1567910,54,26,45,19,'I nabéře kněz krve té oběti za hřích, a pomaže veřejí domu, a čtyř rohů toho přepásání na oltáři, i veřeje brány síně vnitřní.'),
(1567911,54,26,45,20,'Takž také učiní sedmého dne téhož měsíce, za každého pobloudilého i za hloupého. Tak očistíte dům.'),
(1567912,54,26,45,21,'Prvního měsíce, čtrnáctého dne, budete míti Fáze, svátek sedmi dnů, chlebové přesní jísti se budou.'),
(1567913,54,26,45,22,'A bude obětovati kníže v ten den za sebe i za všecken lid té země volka za hřích.'),
(1567914,54,26,45,23,'A po sedm dní svátku obětovati bude zápal Hospodinu, sedm volků a sedm skopců bez poškvrny na den, po těch sedm dní, a za hřích kozla na den.'),
(1567915,54,26,45,24,'A obět suchou, efi na volka a efi na skopce, připraví též oleje hin na efi.'),
(1567916,54,26,45,25,'Sedmého měsíce, patnáctého dne, v svátek tolikéž obětovati bude po sedm dní, jakož za hřích, tak zápal, tak obět suchou i olej.'),
(1567917,54,26,46,1,'Takto praví Panovník Hospodin: Brána síně vnitřní, kteráž patří k východu, bude zavřená po šest dní všedních, v den pak sobotní otevřína bude; též v den novměsíce otvírána bude.'),
(1567918,54,26,46,2,'I přijde kníže cestou síně brány zevnitř, a postaví se u veřeje té brány, a budou obětovati kněží obět zápalnou jeho, i oběti pokojné jeho, a pokloně se na prahu brány, potom vyjde. Brána pak nebude zavírána do večera,'),
(1567919,54,26,46,3,'Aby se klaněl lid země té u dveří brány té ve dny sobotní, i na novměsíce před Hospodinem.'),
(1567920,54,26,46,4,'Obět pak zápalná, kterouž obětovati má kníže Hospodinu v den sobotní, šest beránků bez vady a skopec bez poškvrny,'),
(1567921,54,26,46,5,'A obět suchá, efi na skopce, i na beránky obět suchá, podlé toho, jakž naděleno, a oleje hin na efi.'),
(1567922,54,26,46,6,'Ke dni pak novměsíce ať jest volek mladý bez poškvrny, a šest beránků i skopec bez poškvrny.'),
(1567923,54,26,46,7,'Též ať obětuje efi oběti suché při volku, a efi při skopci i při beráncích, seč bude moci býti, a oleje hin na efi.'),
(1567924,54,26,46,8,'Kníže pak vcházeje, cestou síňce též brány půjde, a cestou její odejde.'),
(1567925,54,26,46,9,'Ale když vcházeti bude lid země té před Hospodina na slavnosti, ten kdož vejde cestou brány půlnoční, aby se klaněl, vyjde cestou brány polední; a ten kdož vejde cestou brány polední, vyjde cestou brány půlnoční. Nenavrátí se cestou té brány, kterouž všel, ale naproti ní vyjde.'),
(1567926,54,26,46,10,'A když oni vcházeti budou, kníže mezi nimi vcházeti bude, a když odcházeti budou, odejde.'),
(1567927,54,26,46,11,'Též na svátky i na slavnosti ať jest suchá obět, efi na volka a efi na skopce, a na beránky, což naděleno, a oleje hin na efi.'),
(1567928,54,26,46,12,'Bude-li pak obětovati kníže obět dobrovolnou, zápal aneb oběti pokojné dobrovolně Hospodinu, tedy ať jest mu otevřína brána, kteráž k východu patří, a ať obětuje zápal svůj aneb pokojné oběti své, tak jakž obětuje v den sobotní. Potom odejde, a brána bude zavřína po odchodu jeho.'),
(1567929,54,26,46,13,'K tomu beránka ročního bez poškvrny obětovati bude v zápal každý den Hospodinu; každého jitra beránka obětovati bude.'),
(1567930,54,26,46,14,'Též suchou obět přičiní k němu, každého jitra šestý díl efi, též oleje třetinu hin k skropení mouky bělné, suchou obět Hospodinu, nařízením věčným ustavičně.'),
(1567931,54,26,46,15,'A tak budou obětovati beránka i obět suchou, i olej každého jitra, zápal ustavičný.'),
(1567932,54,26,46,16,'Taktoť praví Panovník Hospodin: Dá-li kníže dar někomu z synů svých, dědictvíť jeho jest, synů jeho buď, k vládařství jejich dědičnému.'),
(1567933,54,26,46,17,'Jestliže pak dá dar z dědictví svého některému z služebníků svých, také bude jeho až do léta svobodného, kdyžto navrátí se knížeti tomu; však dědictví jeho budou míti synové jeho.'),
(1567934,54,26,46,18,'Aniž bude bráti kníže z dědictví lidu, z vládařství jejich je vytiskuje; z svého vládařství dědictví dá synům svým, aby nebyl rozptylován lid můj žádný z vládařství svého.'),
(1567935,54,26,46,19,'Potom vedl mne průchodem, kterýž jest po straně brány, k kněžím do komůrek svatých, kteréž patřily na půlnoci, a aj, tu bylo místo po dvou bocích k západu.'),
(1567936,54,26,46,20,'I řekl mi: Toto jest místo, kdež vaří kněží oběti za vinu a za hřích, kdež smaží oběti suché, aby nevynášeli do síně zevnitřní ku posvěcování lidu.'),
(1567937,54,26,46,21,'Vyvedl mne též do síně zevnitřní, a vodil mne po čtyřech koutech síně, a aj, síň byla v každém rohu té síně.'),
(1567938,54,26,46,22,'Ve čtyřech úhlech té síně byly síně s komíny, čtyřidcíti loket zdélí a třídcíti zšíří; míra jednostejná těch čtyř síní nárožních.'),
(1567939,54,26,46,23,'A v těch čtyřech byly kuchyňky vůkol, též ohniště zdělána v těch kuchyňkách vůkol.'),
(1567940,54,26,46,24,'I řekl mi: Ta jsou místa těch, kteříž vaří, kdežto vaří služebníci domu oběti lidu.'),
(1567941,54,26,47,1,'Potom přivedl mne zase ke dveřím domu, a aj, vody vycházely od spodku prahu domu na východ; nebo přední strana domu k východu byla, a vody scházely pozpodu po pravé straně domu, po straně polední oltáře.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567942,54,26,47,2,'Odtud mne vyvedl cestou brány půlnoční, a obvedl mne cestou zevnitřní k bráně zevnitřní, cestou, kteráž patří k východu, a aj, vody vyplývaly po pravé straně.'),
(1567943,54,26,47,3,'Když pak vycházel ten muž k východu, v jehož rukou míra, i naměřil tisíc loket, a provedl mne skrze vodu,vodu do kůtků.'),
(1567944,54,26,47,4,'Potom naměřiv tisíc, provedl mne skrze vodu, vodu do kolenou; ještě naměřiv tisíc, provedl mne vodou do pasu.'),
(1567945,54,26,47,5,'Opět když naměřil tisíc, byl potok, kteréhož jsem nemohl přebřísti; nebo vyzdvihly se vody, vody, přes něž by se musilo plynouti, potok, kterýž by nemohl přebředen býti.'),
(1567946,54,26,47,6,'Tedy řekl mi: Viděl-lis, synu člověčí? I vedl mne, a posadil mne na břeh toho potoka.'),
(1567947,54,26,47,7,'Když jsem se pak obrátil, aj, na břehu toho potoka bylo dříví velmi veliké po obou stranách.'),
(1567948,54,26,47,8,'I řekl mi: Vody tyto vycházejí od Galilee první, a sstupujíce po rovině, vejdou do moře, a když do moře vpadnou, opraví se vody.'),
(1567949,54,26,47,9,'I stane se, že každý živočich, kterýž se plazí, všudy, kamžkoli přijdou potokové, ožive, a bude ryb velmi mnoho, proto že když přijdou tam tyto vody, očerstvějí, a živy budou všudy, kdežkoli dojde tento potok.'),
(1567950,54,26,47,10,'Stane se i to, že se postaví podlé něho rybáři od Engadi až do studnice Eglaim; budou tu rozstírány síti. Podlé rozličnosti své bude ryb jejich, jako ryb moře velikého, velmi mnoho.'),
(1567951,54,26,47,11,'Bahna a louže jeho, kteréž se neopraví, soli oddány budou.'),
(1567952,54,26,47,12,'Při potoku pak poroste na břehu jeho po obou stranách všelijaké dříví ovoce nesoucí, jehož list neprší, aniž ovoce jeho přestává, v měsících svých nese prvotiny; nebo vody jeho z svatyně vycházejí, protož ovoce jeho jest ku pokrmu, a lístí jeho k lékařství.'),
(1567953,54,26,47,13,'Takto praví Panovník Hospodin: Totoť jest obmezení, v němž sobě dědičně přivlastníte zemi po pokoleních Izraelských dvanácti; Jozefovi dva provazcové.'),
(1567954,54,26,47,14,'Dědičně, pravím, jí vládnouti budete, jeden rovně jako druhý, o níž přisáhl jsem, že ji dám otcům vašim. I připadne vám země tato v dědictví.'),
(1567955,54,26,47,15,'Toto jest tedy pomezí té země: K straně půlnoční od moře velikého cestou Chetlonu, kudyž se vchází do Sedad,'),
(1567956,54,26,47,16,'Emat, Berota, Sibraim, kteříž jsou mezi pomezím Damašským, a mezi pomezím Emat, vsi prostřední, kteréž jsou při pomezí Chavrón.'),
(1567957,54,26,47,17,'A tak bude pomezí od moře Azar Enon, pomezí Damašek, a půlnoční strana na půlnoci, a pomezí Emat. A to jest strana půlnoční.'),
(1567958,54,26,47,18,'Strana pak východní mezi Chavrón a mezi Damaškem, a mezi Galád, a mezi zemí Izraelskou při Jordánu; od toho pomezí při moři východním měřiti budete. A toť jest strana východní.'),
(1567959,54,26,47,19,'Strana pak polední na poledne, od Támar až k vodám sváru v Kádes, od potoka až k moři velikému. A to jest strana polední na poledne.'),
(1567960,54,26,47,20,'Strana pak západní moře veliké, od pomezí až naproti, kudyž se vchází do Emat. Ta jest strana západní.'),
(1567961,54,26,47,21,'A tak rozdělíte zemi tuto sobě po pokoleních Izraelských.'),
(1567962,54,26,47,22,'I stane se, že když ji rozměříte, bude vám v dědictví i příchozím, kteříž by pohostinu byli mezi vámi, kteříž by zplodili syny mezi vámi; nebo budou vám jako tu zrodilí mezi syny Izraelskými, s vámiť ujmou dědictví mezi pokoleními Izraelskými.'),
(1567963,54,26,47,23,'Protož nechť jest v tom pokolení příchozí, u něhož pohostinu jest. Tu dědictví dáte jemu, praví Panovník Hospodin.'),
(1567964,54,26,48,1,'Tato jsou pak jména pokolení: V končinách na půlnoční stranu podlé cesty Chetlon, kudyž se vchází do Emat, Azar Enan, ku pomezí Damašskému na půlnoční stranu, podlé Emat, od východní strany až do západní, osadí se pokolení jedno, totiž Dan,'),
(1567965,54,26,48,2,'A při pomezí Dan, od strany východní až k straně západní jedno, totiž Asser,'),
(1567966,54,26,48,3,'A při pomezí Asser, od strany východní až do strany západní jedno, totiž Neftalím,'),
(1567967,54,26,48,4,'A při pomezí Neftalím, od strany východní až do strany západní jedno, totiž Manasses,'),
(1567968,54,26,48,5,'A při pomezí Manasses, od strany východní až do strany západní jedno, totiž Efraim,'),
(1567969,54,26,48,6,'A při pomezí Efraim, od strany východní až k straně západní jedno, totiž Ruben,'),
(1567970,54,26,48,7,'A při pomezí Ruben, od strany východní až k straně západní jedno, totiž Juda.'),
(1567971,54,26,48,8,'A při pomezí Juda, od strany východní až k straně západní bude obět, kterouž obětovati budete, pětmecítma tisíc loket zšíří, zdélí pak zaroveň s jedním z jiných dílů, od strany východní až k straně západní, a bude svatyně u prostřed něho.'),
(1567972,54,26,48,9,'Ta obět, kterouž obětovati máte Hospodinu, bude zdélí pětmecítma tisíc loket, zšíří pak deset tisíc.'),
(1567973,54,26,48,10,'Těmto pak se dostane ta obět svatá,totiž kněžím, na půlnoci pětmecítma tisíc loket, k západu pak zšíří desíti tisíc, a na východ zšíří desíti tisíc, na poledne též zdélí pětmecítma tisíc, a bude svatyně Hospodinova u prostřed něho,'),
(1567974,54,26,48,11,'Kněžím, posvěcenému každému z synů Sádochových, kteříž drží stráž mou, kteříž nebloudili, když bloudili synové Izraelští, jako bloudili Levítové.'),
(1567975,54,26,48,12,'I bude díl jejich obětovaný z oběti té země, věc nejsvětější při pomezí Levítů.'),
(1567976,54,26,48,13,'Levítů pak díl bude naproti pomezí kněžskému, pětmecítma tisíc loket zdélí, a zšíří deset tisíc; každá dlouhost pětmecítma tisíc, a širokost deset tisíc.'),
(1567977,54,26,48,14,'A nebudou ho uprodávati, ani směňovati, ani přenášeti prvotin země, proto že jest posvěcená Hospodinu.'),
(1567978,54,26,48,15,'Pět pak tisíc loket pozůstalých na šíř, proti těm pětmecítma tisícům, bude místo obecné, pro město k bydlení a k předměstí, i bude město u prostřed něho.'),
(1567979,54,26,48,16,'Tyto pak jsou míry jeho: Strana půlnoční na čtyři tisíce a pět set loket, též strana polední na čtyři tisíce a pět set, od strany též východní čtyři tisíce a pět set, takž strana západní na čtyři tisíce a pět set.'),
(1567980,54,26,48,17,'Bude i předměstí při městě k půlnoci na dvě stě a padesáte loket, a ku poledni na dvě stě a padesáte, takž na východ na dvě stě a padesáte, též k západu na dvě stě a padesáte.'),
(1567981,54,26,48,18,'Ostatek pak na dél, naproti oběti svaté, deset tisíc loket k východu, a deset tisíc k západu; a z toho, což bude naproti té oběti svaté, budou míti důchody ku pokrmu služebníci města.'),
(1567982,54,26,48,19,'A ti služebníci města sloužiti budou Izraelovi ze všech pokolení Izraelských.'),
(1567983,54,26,48,20,'Všecku tuto oběť, pětmecítma tisíc loket, podlé těch pětmecítma tisíc, čtverhranou obětovati budete v obět svatou k vládařství městu.'),
(1567984,54,26,48,21,'Což pak pozůstane, knížeti, s obou stran oběti svaté a vládařství města, před těmi pětmecítma tisíci loket oběti, až ku pomezí východnímu, a od západu proti týmž pětmecítma tisíc loket, podlé pomezí západního naproti těm dílům, knížeti bude. A to bude obět svatá, a svatyně domu u prostřed něho.'),
(1567985,54,26,48,22,'Od vládařství pak Levítů a od vládařství města, u prostřed toho, což jest knížecího, mezi pomezím Judovým a mezi pomezím Beniaminovým, knížecí bude.'),
(1567986,54,26,48,23,'Ostatní pak pokolení, od strany východní až k straně západní, osadí se pokolení jedno, totiž Beniamin.'),
(1567987,54,26,48,24,'A při pomezí Beniamin, od strany východní až k straně západní jedno, totiž Simeon,'),
(1567988,54,26,48,25,'A při pomezí Simeon, od strany východní až k straně západní jedno, totiž Izachar,'),
(1567989,54,26,48,26,'A při pomezí Izachar, od strany východní až k straně západní jedno, totiž Zabulon,'),
(1567990,54,26,48,27,'A při pomezí Zabulon, od strany východní až k straně západní jedno, totiž Gád.'),
(1567991,54,26,48,28,'A při pomezí Gád, k straně polední na poledne, tu bude pomezí od Támar až k vodám sváru v Kádes, ku potoku při moři velikém.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1567992,54,26,48,29,'Toť jest ta země, kterouž ujmete hned od potoka, po pokoleních Izraelských, a ti dílové jejich, praví Panovník Hospodin.'),
(1567993,54,26,48,30,'Tato pak jsou vymezení města: Od strany půlnoční čtyř tisíc a pět set loket míra.'),
(1567994,54,26,48,31,'Brány pak města podlé jmen pokolení Izraelských, brány tři na půlnoci, brána Rubenova jedna, brána Judova jedna, brána Léví jedna.'),
(1567995,54,26,48,32,'A od strany východní čtyř tisíc a pět set, a brány tři, totiž brána Jozefova jedna, brána Beniaminova jedna, brána Danova jedna.'),
(1567996,54,26,48,33,'Též od strany polední čtyř tisíc a pět set loket míra, a brány tři, brána Simeonova jedna, brána Izacharova jedna, brána Zabulonova jedna.'),
(1567997,54,26,48,34,'Od strany západní čtyř tisíc a pět set, brány jejich tři, brána Gádova jedna, brána Asserova jedna, brána Neftalímova jedna.'),
(1567998,54,26,48,35,'Okolek osmnácti tisíc loket, jméno pak města od dnešního dne bude: Hospodin tam přebývá.'),
(1567999,54,27,1,1,'Léta třetího kralování Joakima krále Judského, přitáhl Nabuchodonozor král Babylonský k Jeruzalému, a oblehl jej.'),
(1568000,54,27,1,2,'I vydal Pán v ruku jeho Joakima krále Judského, a něco nádobí domu Božího. Kterýž zavezl je do země Sinear, do domu boha svého, a nádobí to dal vnésti do domu pokladu boha svého.'),
(1568001,54,27,1,3,'Rozkázal také král Ašpenazovi, správci dvořanů svých, aby přivedl z synů Izraelských, z semene královského a z knížat,'),
(1568002,54,27,1,4,'Mládence, na nichž by nebylo žádné poškvrny, a krásného oblíčeje, a vtipné ke vší moudrosti, a schopné k umění i k nabývání jeho, a v kterýchž by byla síla, aby stávali na palácu královském, a učili se liternímu umění a jazyku Kaldejskému.'),
(1568003,54,27,1,5,'I nařídil jim král odměřený pokrm na každý den z stolu královského, i vína, kteréž on sám pil, a aby je tak choval za tři léta, a po dokonání jich aby stávali před králem.'),
(1568004,54,27,1,6,'Byli pak mezi nimi z synů Juda: Daniel, Chananiáš, Mizael a Azariáš.'),
(1568005,54,27,1,7,'I dal jim správce dvořanů jména. Nazval Daniele Baltazarem, Chananiáše pak Sidrachem, a Mizaele Mizachem, a Azariáše Abdenágem.'),
(1568006,54,27,1,8,'Ale Daniel uložil v srdci svém, aby se nepoškvrňoval pokrmem z stolu královského, a vínem, kteréž král pil. Pročež hledal toho u správce nad dvořany, aby se nemusil poškvrňovati.'),
(1568007,54,27,1,9,'I způsobil Bůh Danielovi milost a lásku u správce nad dvořany.'),
(1568008,54,27,1,10,'A řekl správce nad dvořany Danielovi: Já se bojím pána svého krále, kterýž vyměřil pokrm váš a nápoj váš, tak že uzřel-li by, že tváře vaše opadlejší jsou, nežli mládenců těch, kteříž podobně jako i vy chování býti mají, způsobíte mi to u krále, že přijdu o hrdlo.'),
(1568009,54,27,1,11,'I řekl Daniel služebníku, kteréhož ustanovil správce dvořanů nad Danielem, Chananiášem, Mizaelem a Azariášem:'),
(1568010,54,27,1,12,'Zkus, prosím, služebníků svých za deset dní, a nechť se nám vaření dává, kteréž bychom jedli, a voda, kterouž bychom pili.'),
(1568011,54,27,1,13,'A potom nechť se spatří před tebou tváře naše a tváře mládenců, kteříž jídají pokrm z stolu královského, a jakž uhlédáš, učiň s služebníky svými.'),
(1568012,54,27,1,14,'I uposlechl jich v té věci, a zkusil jich za deset dní.'),
(1568013,54,27,1,15,'Po skonání pak desíti dnů spatříno jest, že tváře jejich byly krásnější, a byli tlustší na těle než všickni mládenci, kteříž jídali pokrm z stolu královského.'),
(1568014,54,27,1,16,'Protož služebník brával ten vyměřený pokrm jejich, a víno nápoje jejich, a dával jim vaření.'),
(1568015,54,27,1,17,'Mládence pak ty čtyři obdařil Bůh povědomostí a rozumností ve všelikém literním umění a moudrostí; nadto Danielovi dal, aby rozuměl všelikému vidění a snům.'),
(1568016,54,27,1,18,'A když se dokonali dnové, po kterýchž rozkázal král, aby je přivedli, přivedl je správce dvořanů před Nabuchodonozora.'),
(1568017,54,27,1,19,'I mluvil s nimi král. Ale není nalezen mezi všemi těmi, jako Daniel, Chananiáš, Mizael a Azariáš. I stávali před králem.'),
(1568018,54,27,1,20,'A ve všelikém slovu moudrosti a rozumnosti, na kteréž se jich doptával král, nalezl je desetkrát zběhlejší nade všecky mudrce a hvězdáře, kteříž byli ve všem království jeho.'),
(1568019,54,27,1,21,'I zůstával tu Daniel až do léta prvního Cýra krále.'),
(1568020,54,27,2,1,'Léta pak druhého kralování Nabuchodonozora měl Nabuchodonozor sen, a děsil se duch jeho, až se tudy i ze sna protrhl.'),
(1568021,54,27,2,2,'I rozkázal král svolati mudrce, a hvězdáře i kouzedlníky a Kaldejské, aby oznámili králi sen jeho. Kteřížto přišli, a postavili se před králem.'),
(1568022,54,27,2,3,'Tedy řekl jim král: Měl jsem sen, a předěsil se duch můj, tak že nevím, jaký to byl sen.'),
(1568023,54,27,2,4,'I mluvili Kaldejští králi Syrsky: Králi, na věky buď živ. Pověz sen služebníkům svým, a oznámímeť výklad.'),
(1568024,54,27,2,5,'Odpověděl král a řekl Kaldejským: Ten sen mi již z paměti vyšel. Neoznámíte-li mi snu i výkladu jeho, na kusy rozsekáni budete, a domové vaši v záchody obráceni budou.'),
(1568025,54,27,2,6,'Pakli mi sen i výklad jeho oznámíte, daru, odplaty a slávy veliké důjdete ode mne. A protož sen i výklad jeho mi oznamte.'),
(1568026,54,27,2,7,'Odpověděli po druhé a řekli: Nechať král sen poví služebníkům svým, a výklad jeho oznámíme.'),
(1568027,54,27,2,8,'Odpověděl král a řekl: Jistotně rozumím tomu, že naschvál odtahujete, vidouce, že mi vyšel z paměti ten sen.'),
(1568028,54,27,2,9,'Neoznámíte-li mi toho snu, jistý jest ten úsudek o vás. Nebo řeč lživou a chytrou smyslili jste sobě, abyste mluvili přede mnou, ažby se čas proměnil. A protož sen mi povězte, a zvím, budete-li mi moci i výklad jeho oznámiti.'),
(1568029,54,27,2,10,'Odpověděli Kaldejští králi a řekli: Není člověka na zemi, kterýž by tu věc králi oznámiti mohl. Nadto žádný král, kníže neb potentát takové věci se nedoptával na žádném mudrci a hvězdáři aneb Kaldeovi.'),
(1568030,54,27,2,11,'Nebo ta věc, na niž se král ptá, nesnadná jest, a není jiného, kdo by ji oznámiti mohl králi, kromě bohů, kteříž bydlení s lidmi nemají.'),
(1568031,54,27,2,12,'Z té příčiný rozlítil se král a rozhněval velmi, a přikázal, aby zhubili všecky mudrce Babylonské.'),
(1568032,54,27,2,13,'A když vyšel ortel, a mudrci mordováni byli, hledali i Daniele a tovaryšů jeho, aby zmordováni byli.'),
(1568033,54,27,2,14,'Tedy Daniel odpověděl moudře a opatrně Ariochovi, hejtmanu nad žoldnéři královskými, kterýž vyšel, aby mordoval mudrce Babylonské.'),
(1568034,54,27,2,15,'A odpovídaje, řekl Ariochovi, hejtmanu královskému: Proč ta výpověd náhle vyšla od krále? I oznámil tu věc Arioch Danielovi.'),
(1568035,54,27,2,16,'Pročež Daniel všed, prosil krále, aby jemu prodlel času k oznámení výkladu toho králi.'),
(1568036,54,27,2,17,'A odšed Daniel do domu svého, oznámil tu věc Chananiášovi, Mizaelovi a Azariášovi, tovaryšům svým,'),
(1568037,54,27,2,18,'Aby se za milosrdenství modlili Bohu nebeskému příčinou té věci tajné, a nebyli zahubeni Daniel a tovaryši jeho s pozůstalými mudrci Babylonskými.'),
(1568038,54,27,2,19,'I zjevena jest Danielovi u vidění nočním ta věc tajná. Pročež Daniel dobrořečil Bohu nebeskému.'),
(1568039,54,27,2,20,'Mluvil pak Daniel a řekl: Buď jméno Boží požehnáno od věků až na věky, nebo moudrost a síla jeho jest.'),
(1568040,54,27,2,21,'A on proměňuje časy i chvíle; ssazuje krále, i ustanovuje krále; dává moudrost moudrým a umění majícím rozum.'),
(1568041,54,27,2,22,'On zjevuje věci hluboké a skryté; zná to, což jest v temnostech, a světlo s ním přebývá.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568042,54,27,2,23,'Ó Bože otců mých, těť oslavuji a chválím, že jsi mne moudrostí a silou obdařil, ovšem nyní, že jsi mi oznámil to, čehož jsme žádali od tebe; nebo věc královu oznámil jsi nám.'),
(1568043,54,27,2,24,'A protož Daniel všel k Ariochovi, kteréhož ustanovil král, aby zhubil mudrce Babylonské. A přišed, takto řekl jemu: Mudrců Babylonských nezahlazuj; uveď mne před krále a výklad ten oznámím.'),
(1568044,54,27,2,25,'Tedy Arioch s chvátáním uvedl Daniele před krále, a takto řekl jemu: Našel jsem muže z zajatých synů Judských, kterýž výklad ten králi oznámí.'),
(1568045,54,27,2,26,'Odpověděl král a řekl Danielovi, jehož jméno bylo Baltazar: Budeš-liž ty mi moci oznámiti sen, kterýž jsem viděl, i výklad jeho?'),
(1568046,54,27,2,27,'Odpověděl Daniel králi a řekl: Té věci tajné, na niž se král doptává, nikoli nemohou mudrci, hvězdáři, věšťci a hadači králi oznámiti.'),
(1568047,54,27,2,28,'Ale však jest Bůh na nebi, kterýž zjevuje tajné věci, a on ukázal králi Nabuchodonozorovi, co se díti bude v potomních dnech. Sen tvůj, a což jsi ty viděl na ložci svém, toto jest:'),
(1568048,54,27,2,29,'Tobě, ó králi, na mysl přicházelo na ložci tvém, co bude potom, a ten, kterýž zjevuje tajné věci, ukázalť to, což budoucího jest.'),
(1568049,54,27,2,30,'Strany pak mne, ne skrze moudrost, kteráž by při mně byla nade všecky lidi, ta věc tajná mně zjevena jest, ale skrze modlitbu, aby ten výklad králi oznámen byl, a ty myšlení srdce svého abys zvěděl.'),
(1568050,54,27,2,31,'Ty králi, viděl jsi, a aj, obraz nějaký veliký, (obraz ten byl znamenitý a blesk jeho náramný), stál naproti tobě, kterýž na pohledění byl hrozný.'),
(1568051,54,27,2,32,'Toho obrazu hlava byla z zlata výborného, prsy jeho a ramena jeho z stříbra, a břicho jeho i bedra jeho z mědi,'),
(1568052,54,27,2,33,'Hnátové jeho z železa, nohy jeho z částky z železa a z částky z hliny.'),
(1568053,54,27,2,34,'Hleděls na to, až se utrhl kámen, kterýž nebýval v rukou, a udeřil obraz ten v nohy jeho železné a hliněné, a potřel je.'),
(1568054,54,27,2,35,'A tak potříno jest spolu železo, hlina, měď, stříbro i zlato, a bylo to všecko jako plevy z placu letního, a zanesl to vítr, tak že místa jejich není nalezeno. Kámen pak ten, kterýž udeřil v obraz, učiněn jest horou velikou, a naplnil všecku zemi.'),
(1568055,54,27,2,36,'Toť jest ten sen. Výklad jeho také povíme králi:'),
(1568056,54,27,2,37,'Ty králi, jsi král králů; nebo Bůh nebeský dal tobě království, moc a sílu i slávu.'),
(1568057,54,27,2,38,'A všeliké místo, na němž přebývají synové lidští, zvěř polní i ptactvo nebeské dal v ruku tvou, a pánem tě ustavil nade všemi těmi věcmi. Ty jsi ta hlava zlatá.'),
(1568058,54,27,2,39,'Ale po tobě povstane království jiné, nižší než tvé, a jiné království třetí měděné, kteréž panovati bude po vší zemi.'),
(1568059,54,27,2,40,'Království pak čtvrté bude tvrdé jako železo. Nebo jakož železo drobí a zemdlévá všecko, tak, pravím, jako železo, kteréž potírá všecko, i ono potře a potříská všecko.'),
(1568060,54,27,2,41,'Že jsi pak viděl nohy a prsty z částky z hliny hrnčířské a z částky z železa, království rozdílné znamená, v němž bude něco mocnosti železa, tak jakž jsi viděl železo smíšené s hlinou ničemnou.'),
(1568061,54,27,2,42,'Ale prstové noh z částky z železa a z částky z hliny znamenají království z částky mocné a z částky ku potření snadné.'),
(1568062,54,27,2,43,'A že jsi viděl železo smíšené s hlinou ničemnou, ukazuje, že se přízniti budou vespolek lidé, a však nebude se přídržeti jeden druhého, tak jako železo nedrží se z hlinou.'),
(1568063,54,27,2,44,'Za dnů pak těch králů vzbudí Bůh nebeský království, kteréž na věky nebude zkaženo, a království to na žádného jiného nespadne, ale ono potře a konec učiní všechněm těm královstvím, samo pak státi bude na věky,'),
(1568064,54,27,2,45,'Tak jakž jsi viděl, že se s hory utrhl kámen, kterýž nebýval v rukou, a potřel železo, měď, hlinu, stříbro a zlato. Bůh veliký oznámil králi, co býti má potom, a pravý jest sen ten i věrný výklad jeho.'),
(1568065,54,27,2,46,'Tedy král Nabuchodonozor padl na tvář svou, a poklonil se Danielovi, a rozkázal, aby oběti a vůně libé obětovali jemu.'),
(1568066,54,27,2,47,'A odpovídaje král Danielovi, řekl: V pravdě že Bůh váš jest Bůh bohů a Pán králů, kterýž zjevuje skryté věci, poněvadž jsi mohl vyjeviti tajnou věc tuto.'),
(1568067,54,27,2,48,'Tedy král zvelebil Daniele, a dary veliké a mnohé dal jemu, a pánem ho učinil nade vší krajinou Babylonskou, a knížetem nad vývodami, a nade všemi mudrci Babylonskými.'),
(1568068,54,27,2,49,'Daniel pak vyžádal na králi, aby představil krajině Babylonské Sidracha, Mizacha a Abdenágo. Ale Daniel býval v bráně královské.'),
(1568069,54,27,3,1,'Potom Nabuchodonozor král udělav obraz zlatý, jehož výška byla šedesáti loket, šířka pak šesti loket, postavil jej na poli Dura v krajině Babylonské.'),
(1568070,54,27,3,2,'I poslal Nabuchodonozor král, aby shromáždili knížata, vývody a vůdce, starší, správce nad poklady, v právích zběhlé, úředníky a všecky, kteříž panovali nad krajinami, aby přišli ku posvěcování obrazu, kterýž postavil Nabuchodonozor král.'),
(1568071,54,27,3,3,'Tedy shromáždili se knížata, vývodové a vůdcové, starší, správcové nad poklady, v právích zběhlí, úředníci a všickni, kteříž panovali nad krajinami ku posvěcování obrazu toho, kterýž postavil Nabuchodonozor král, a stáli před obrazem, kterýž postavil Nabuchodonozor.'),
(1568072,54,27,3,4,'Biřic pak volal ze vší síly: Vám se to praví lidem, národům a jazykům,'),
(1568073,54,27,3,5,'Jakž uslyšíte zvuk trouby, píšťalky, citary, huslí, loutny, zpívání a všelijaké muziky, padněte a klanějte se obrazu zlatému, kterýž postavil Nabuchodonozor král.'),
(1568074,54,27,3,6,'Kdož by pak nepadl a neklaněl se, té hodiny uvržen bude do prostřed peci ohnivé rozpálené.'),
(1568075,54,27,3,7,'A protož hned, jakž uslyšeli všickni lidé zvuk trouby, píšťalky, citary, huslí, loutny a všelijaké muziky, padli všickni lidé, národové a jazykové, klanějíce se obrazu zlatému, kterýž postavil Nabuchodonozor král.'),
(1568076,54,27,3,8,'A hned téhož času přistoupili muži Kaldejští, a s křikem žalovali na Židy,'),
(1568077,54,27,3,9,'A mluvíce, řekli Nabuchodonozorovi králi: Králi, na věky buď živ.'),
(1568078,54,27,3,10,'Ty králi, vynesls výpověd, aby každý člověk, kterýž by slyšel zvuk trouby, píšťalky, citary, huslí, loutny, zpívání a všelijaké muziky, padl a klaněl se obrazu zlatému,'),
(1568079,54,27,3,11,'A kdož by nepadl a neklaněl se, aby uvržen byl do prostřed peci ohnivé rozpálené.'),
(1568080,54,27,3,12,'Našli se pak někteří Židé, kteréž jsi představil krajině Babylonské, totiž Sidrach, Mizach a Abdenágo, kteřížto muži nedbali na tvé, ó králi, nařízení. Bohů tvých nectí, a obrazu zlatému, kterýž jsi postavil, se neklanějí.'),
(1568081,54,27,3,13,'Tedy Naduchodonozor v hněvě a v prchlivosti rozkázal přivésti Sidracha, Mizacha a Abdenágo. I přivedeni jsou muži ti před krále.'),
(1568082,54,27,3,14,'I mluvil Nabuchodonozor a řekl jim: Zoumyslně-li, Sidrachu, Mizachu a Abdenágo, bohů mých nectíte, a obrazu zlatému, kterýž jsem postavil, se neklaníte?'),
(1568083,54,27,3,15,'Protož nyní, jste-liž hotovi, abyste hned, jakž uslyšíte zvuk trouby, píšťalky, citary, huslí, loutny, zpívání a všelijaké muziky, padli a klaněli se obrazu tomu, kterýž jsem učinil? Pakli se klaněti nebudete, té hodiny uvrženi budete do prostřed peci ohnivé rozpálené, a který jest ten Bůh, ješto by vás vytrhl z ruky mé?'),
(1568084,54,27,3,16,'Odpověděli Sidrach, Mizach a Abdenágo, a řekli králi: My se nestaráme o to, ó Nabuchodonozoře, co bychom měli odpovědíti tobě.'),
(1568085,54,27,3,17,'Nebo aj, buďto že Bůh, jehož my ctíme, (kterýž mocen jest vytrhnouti nás z peci ohnivé rozpálené, a tak z ruky tvé, ó králi), vytrhne nás.'),
(1568086,54,27,3,18,'Buď že nevytrhne, známo buď tobě, ó králi, žeť bohů tvých ctíti a obrazu zlatému, kterýž jsi postavil, klaněti se nebudeme.'),
(1568087,54,27,3,19,'Tedy Nabuchodonozor naplněn jsa prchlivostí, tak že oblíčej tváři jeho se proměnil proti Sidrachovi, Mizachovi a Abdenágovi, a odpovídaje, rozkázal rozpáliti pec sedmkrát více, než obyčej měli ji rozpalovati.'),
(1568088,54,27,3,20,'A mužům silným, kteříž byli mezi rytíři jeho, rozkázal, aby svížíce Sidracha, Mizacha a Abdenágo, uvrhli do peci ohnivé rozpálené.'),
(1568089,54,27,3,21,'Tedy svázali muže ty v pláštích jejich, v košilkách jejich, i v kloboucích jejich a v oděvu jejich, a uvrhli je do prostřed peci ohnivé rozpálené.'),
(1568090,54,27,3,22,'Že pak rozkaz královský náhlý byl, a pec velmi rozpálená, z té příčiny muže ty, kteříž uvrhli Sidracha, Mizacha a Abdenágo, zadusil plamen ohně.'),
(1568091,54,27,3,23,'Ale ti tři muži, Sidrach, Mizach a Abdenágo, padli do prostřed peci ohnivé rozpálené svázaní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568092,54,27,3,24,'Tedy Nabuchodonozor král zděsil se, a vstal s chvátáním, a promluviv, řekl hejtmanům svým: Zdaliž jsme neuvrhli tří mužů do prostřed peci svázaných? Odpověděli a řekli králi: Pravda jest, králi.'),
(1568093,54,27,3,25,'On pak odpovídaje, řekl: Aj, vidím čtyři muže rozvázané, procházející se u prostřed ohně, a není žádného porušení při nich, a čtvrtý na pohledění podobný jest synu Božímu.'),
(1568094,54,27,3,26,'A přistoupiv Nabuchodonozor k čelisti peci ohnivé rozpálené, mluvil a řekl: Sidrachu, Mizachu a Abdenágo, služebníci Boha nejvyššího, vyjděte a poďte sem. I vyšli Sidrach, Mizach a Abdenágo z prostředku ohně.'),
(1568095,54,27,3,27,'Shromáždivše se pak knížata, vývodové a vůdcové a hejtmané královští, hleděli na ty muže, an žádné moci neměl oheň při tělích jejich, ani vlas hlavy jejich nepřiškvrkl, ani plášťové jejich se nezměnili, aniž co ohněm páchli.'),
(1568096,54,27,3,28,'I mluvil Nabuchodonozor a řekl: Požehnaný Bůh jejich, totiž Sidrachův, Mizachův a Abdenágův, kterýž poslal anděla svého, a vytrhl služebníky své, kteříž doufali v něho, až i rozkazu královského neuposlechli, ale těla svá vydali, aby nesloužili a neklaněli se žádnému bohu, kromě Bohu svému.'),
(1568097,54,27,3,29,'A protož toto já přikazuji, aby každý ze všelikého lidu, národu a jazyku, kdož by koli co rouhavého řekl proti Bohu Sidrachovu, Mizachovu a Abdenágovu, na kusy rozsekán byl, a dům jeho v záchod obrácen, proto že není Boha jiného, kterýž by mohl vytrhovati, jako tento.'),
(1568098,54,27,3,30,'Tedy zvelebil zase král Sidracha, Mizacha a Abdenága v krajině Babylonské.'),
(1568099,54,27,3,31,'Nabuchodonozor král všechněm lidem, národům i jazykům, kteříž bydlí na vší zemi: Pokoj váš rozmnožen buď.'),
(1568100,54,27,3,32,'Znamení a divy, kteréž učinil při mně Bůh nejvyšší, vidělo mi se za slušné, abych vypravoval.'),
(1568101,54,27,3,33,'Znamení jeho jak veliká jsou, a divové jeho jak mocní jsou, království jeho království věčné, a panování jeho od národu do pronárodu.'),
(1568102,54,27,4,1,'Já Nabuchodonozor, užívaje pokoje v domě svém, a kveta na palácu svém,'),
(1568103,54,27,4,2,'Měl jsem sen, kterýž mne zhrozil, a myšlení na ložci svém, a to, což jsem viděl, znepokojilo mne.'),
(1568104,54,27,4,3,'A protož vyšla ode mne ta výpověd, aby uvedeni byli přede mne mudrci Babylonští, kteříž by mi výklad toho snu oznámili.'),
(1568105,54,27,4,4,'Tedy předstoupili mudrci, hvězdáři, Kaldejští a hadači. I pověděl jsem jim sen, a však výkladu jeho nemohli mi oznámiti.'),
(1568106,54,27,4,5,'Až naposledy předstoupil přede mne Daniel, jehož jméno Baltazar, podlé jména boha mého, a v němž jest duch bohů svatých. Jemuž jsem oznámil sen:'),
(1568107,54,27,4,6,'Baltazaře, kníže mudrců, já vím, že duch bohů svatých jest v tobě, a nic tajného není tobě nesnadného. Vidění snu mého, kterýž jsem měl, i výklad jeho oznam.'),
(1568108,54,27,4,7,'U vidění pak, kteréž jsem viděl na ložci svém, viděl jsem, a aj, strom u prostřed země, jehož vysokost byla veliká.'),
(1568109,54,27,4,8,'Veliký byl strom ten a mocný, a výsost jeho dosahovala až k nebi, a patrný byl až do končin vší země.'),
(1568110,54,27,4,9,'Lístí jeho bylo pěkné, a ovoce jeho hojné, všechněm za pokrm, pod stínem pak jeho byla zvěř polní, a na ratolestech jeho bydlili ptáci nebeští, a z něho potravu měl všeliký živočich.'),
(1568111,54,27,4,10,'Viděl jsem také u viděních svých na ložci svém, a aj, hlásný a svatý s nebe sstoupiv,'),
(1568112,54,27,4,11,'Volal ze vší síly, a tak pravil: Podetněte strom ten, a osekejte ratolesti jeho, a otlucte lístí jeho, a rozmecte ovoce jeho; nechať se vzdálí zvěř od něho, a ptáci z ratolestí jeho.'),
(1568113,54,27,4,12,'A však kmene kořenů jeho v zemi zanechejte, a v poutech železných a ocelivých na trávě polní, aby rosou nebeskou smáčín byl, a díl jeho s zvěří v bylině zemské.'),
(1568114,54,27,4,13,'Srdce jeho od lidského ať jest rozdílné, a srdce zvířecí nechť jest dáno jemu, ažby sedm let vyplnilo se při něm.'),
(1568115,54,27,4,14,'Usouzení hlásných a řeč žádosti svatých stane se, ažby k tomu přišlo, aby poznali lidé, že Nejvyšší panuje nad královstvím lidským, a že komuž chce, dává je, a toho, kterýž jest ponížený mezi lidmi, ustanovuje nad ním.'),
(1568116,54,27,4,15,'Tento sen viděl jsem já Nabuchodonozor král, ty pak, Baltazaře, oznam výklad jeho. Nebo všickni mudrci v království mém nemohli mi výkladu oznámiti, ale ty můžeš, proto že duch bohů svatých jest v tobě.'),
(1568117,54,27,4,16,'Tedy Daniel, jemuž jméno Baltazar, předěšený stál za jednu hodinu, a myšlení jeho strašila ho. A odpověděv král, řekl: Baltazaře, sen ani výklad jeho nechť nestraší tebe. Odpověděl Baltazar a řekl: Pane můj, sen tento přiď na ty, kteříž tě v nenávisti mají, a výklad jeho na tvé nepřátely.'),
(1568118,54,27,4,17,'Strom ten, kterýž jsi viděl, veliký a mocný, jehož výsost dosahovala až k nebi, a kterýž patrný byl po vší zemi.'),
(1568119,54,27,4,18,'A lístí jeho pěkné, a ovoce jeho hojné, a z něhož všickni pokrm měli, pod nímž byla zvěř polní, a na ratolestech jeho bydlili ptáci nebeští,'),
(1568120,54,27,4,19,'Ty jsi ten, ó králi, kterýž jsi rozšířil se a zmocnil, a velikost tvá vzrostla a vznesla se až k nebi, a panování tvé až do konce země.'),
(1568121,54,27,4,20,'Že pak viděl král hlásného a svatého sstupujícího s nebe, kterýž řekl: Podetněte strom ten a zkazte jej, a však kmene kořenů jeho v zemi zanechejte, a v okovách železných a ocelivých ať jest na trávě polní, aby rosou nebeskou smáčín byl, a s zvěří polní díl jeho, ažby sedm let vyplnilo se při něm:'),
(1568122,54,27,4,21,'Tenť jest výklad, ó králi, a ortel Nejvyššího, kterýž vyšel na pána mého krále.'),
(1568123,54,27,4,22,'Nebo zaženou tě lidé od sebe, a s zvěří polní bude bydlení tvé, a bylinu jako volům tobě jísti dávati budou, a rosou nebeskou smáčín budeš, až se vyplní sedm let při tobě, dokudž bys nepoznal, že panuje Nejvyšší nad královstvím lidským, a že komuž chce, dává je.'),
(1568124,54,27,4,23,'Že pak řekli, aby zanechán byl kmen kořenů toho stromu, království tvé tobě zůstane, jakž jen poznáš, že nebesa panují.'),
(1568125,54,27,4,24,'Protož ó králi, přijmi radu mou, a hříchy své spravedlností přetrhuj, a nepravosti své milostivostí k ssouženým, zdaby prodloužen byl pokoj tvůj.'),
(1568126,54,27,4,25,'Všecko to přišlo na krále Nabuchodonozora.'),
(1568127,54,27,4,26,'Nebo po dokonání dvanácti měsíců, procházeje se po palácu královském v Babyloně,'),
(1568128,54,27,4,27,'Mluvil král a řekl: Zdaliž toto není ten Babylon veliký, kterýž jsem já vystavěl mocí síly své, aby byl stolicí království k ozdobě slávy mé?'),
(1568129,54,27,4,28,'Ještě ta řeč byla v ústech krále, a aj, hlas s nebe přišel: Toběť se praví, Nabuchodonozoře králi, že království odešlo od tebe,'),
(1568130,54,27,4,29,'Nýbrž tě lidé i z sebe vyvrhou, a s zvěří polní bydliti budeš. Bylinu jako volům tobě jísti dávati budou, ažby sedm let vyplnilo se při tobě, dokudž bys nepoznal, že panuje Nejvyšší nad královstvím lidským, a že komuž chce, dává je.'),
(1568131,54,27,4,30,'V touž hodinu řeč ta naplnila se při Nabuchodonozorovi. Nebo z spolku lidí vyvržen byl, a bylinu jako vůl jedl, a rosou nebeskou tělo jeho smáčíno bylo, až na něm vlasy zrostly jako peří orličí, a nehty jeho jako pazoury ptačí.'),
(1568132,54,27,4,31,'Při skonání pak těch dnů já Nabuchodonozor pozdvihl jsem očí svých k nebi, a rozum můj ke mně se zase navrátil. I dobrořečil jsem Nejvyššímu, a živého na věky chválil jsem a oslavoval; nebo panování jeho jest panování věčné, a království jeho od národu do pronárodu.'),
(1568133,54,27,4,32,'A všickni obyvatelé země jako za nic počteni jsou, a podlé vůle své činí mezi vojskem nebeským i obyvateli země, aniž jest kdo, ješto by mu přes ruku dáti mohl, a říci jemu: Co to děláš?'),
(1568134,54,27,4,33,'Téhož času rozum můj navrátil se ke mně, a k slávě království mého ozdoba má, i důstojnost má navrátila se ke mně; nadto i hejtmané moji a knížata má hledali mne, a zmocněn jsem v království svém, a velebnost větší jest mi přidána.'),
(1568135,54,27,4,34,'Nyní tedy já Nabuchodonozor chválím, vyvyšuji a oslavuji krále nebeského, jehož všickni skutkové jsou pravda, a stezky jeho soud, a kterýž chodící v pýše může snižovati.'),
(1568136,54,27,5,1,'Balsazar král učinil hody veliké tisíci knížatům svým, a před nimi víno pil.'),
(1568137,54,27,5,2,'A když pil víno Balsazar, rozkázal přinésti nádobí zlaté a stříbrné, kteréž vynesl Nabuchodonozor otec jeho z chrámu Jeruzalémského, aby z něho pili král i knížata jeho, ženy jeho i ženiny jeho.'),
(1568138,54,27,5,3,'I přineseno jest nádobí zlaté, kteréž vynesli z chrámu domu Božího, kterýž byl v Jeruzalémě, a pili z něho král i knížata jeho, ženy jeho i ženiny jeho.'),
(1568139,54,27,5,4,'Pili víno, a chválili bohy zlaté a stříbrné, měděné, železné, dřevěné a kamenné.'),
(1568140,54,27,5,5,'V touž hodinu vyšli prstové ruky lidské, a psali naproti svícnu na stěně paláce královského, a král hleděl na částky ruky, kteráž psala.'),
(1568141,54,27,5,6,'Tedy jasnost královská změnila se, a myšlení jeho zkormoutila ho, a pasové bedr jeho rozpásali se, i kolena jeho jedno o druhé se tlouklo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568142,54,27,5,7,'A zkřikl král ze vší síly, aby přivedeni byli hvězdáři, Kaldejští a hadači. I mluvil král a řekl mudrcům Babylonským: Kdokoli přečte psání toto, a výklad jeho mi oznámí, šarlatem odín bude, a řetěz zlatý na hrdlo jeho, a třetím v království po mně bude.'),
(1568143,54,27,5,8,'I předstoupili všickni mudrci královští, ale nemohli písma toho čísti, ani výkladu oznámiti králi.'),
(1568144,54,27,5,9,'Pročež král Balsazar velmi předěšen byl, a jasnost jeho změnila se na něm, ano i knížata jeho zkormouceni byli.'),
(1568145,54,27,5,10,'Královna pak, příčinou té věci královské a knížat jeho, do domu těch hodů vešla, a promluvivši královna, řekla: Králi, na věky živ buď. Nechť tě neděsí myšlení tvá, a jasnost tvá nechť se nemění.'),
(1568146,54,27,5,11,'Jest muž v království tvém, v němž jest duch bohů svatých, v kterémž za dnů otce tvého osvícení, rozumnost a moudrost, jako moudrost bohů, nalezena, jehož král Nabuchodonozor otec tvůj knížetem mudrců, hvězdářů, Kaldejských a hadačů ustanovil, otec tvůj, ó králi,'),
(1568147,54,27,5,12,'Proto že duch znamenitý, i umění a rozumnost vykládání snů a oznámení pohádek, i rozvázání věcí nesnadných nalezeno při Danielovi, jemuž král jméno dal Baltazar. Nechať nyní zavolán jest Daniel, a oznámíť výklad ten.'),
(1568148,54,27,5,13,'Tedy přiveden jest Daniel před krále. I mluvil král a řekl Danielovi: Ty-li jsi ten Daniel, jeden z synů zajatých Judských, kteréhož přivedl král otec můj z Judstva?'),
(1568149,54,27,5,14,'Slyšel jsem zajisté o tobě, že duch bohů svatých jest v tobě, a osvícení i rozumnost a moudrost znamenitá nalezena jest v tobě.'),
(1568150,54,27,5,15,'A nyní přivedeni jsou přede mne mudrci a hvězdáři, aby mi písmo toto přečtli, a výklad jeho oznámili, a však nemohli výkladu věci té oznámiti.'),
(1568151,54,27,5,16,'Já pak slyšel jsem o tobě, že můžeš to, což jest nesrozumitelného, vykládati, a což nesnadného, rozvázati. Protož nyní, budeš-li moci písmo to přečísti, a výklad jeho mně oznámiti, v šarlat oblečen budeš, a řetěz zlatý na hrdlo tvé, a třetím v království po mně budeš.'),
(1568152,54,27,5,17,'Tedy odpověděl Daniel a řekl před králem: Darové tvoji nechť zůstávají tobě, a odplatu svou dej jinému, a však písmo přečtu králi, a výklad oznámím jemu.'),
(1568153,54,27,5,18,'Ty králi, slyš: Bůh nejvyšší královstvím a důstojností i slávou a okrasou obdařil Nabuchodonozora otce tvého,'),
(1568154,54,27,5,19,'A pro důstojnost, kterouž ho obdařil, všickni lidé, národové a jazykové třásli a báli se před ním. Kohokoli chtěl, zabil, a kterékoli chtěl, bil, kteréž chtěl, povyšoval, a kteréž chtěl, ponižoval.'),
(1568155,54,27,5,20,'Když se pak bylo pozdvihlo srdce jeho, a duch jeho zmocnil se v pýše, ssazen byl z stolice království svého, a slávu odjali od něho.'),
(1568156,54,27,5,21,'Ano i z spolku synů lidských vyvržen byl, a srdce jeho zvířecímu podobné učiněno bylo, a s divokými osly bylo bydlení jeho. Bylinu jako volům dávali jemu jísti, a rosou nebeskou tělo jeho smáčíno bylo, dokudž nepoznal, že panuje Bůh nejvyšší nad královstvím lidským, a že kohož chce, ustanovuje nad ním.'),
(1568157,54,27,5,22,'Ty také, synu jeho Balsazaře, neponížil jsi srdce svého, ačkolis o tom o všem věděl.'),
(1568158,54,27,5,23,'Ale pozdvihls se proti Pánu nebes; nebo nádobí domu jeho přinesli před tebe, a ty i knížata tvá, ženy tvé i ženiny tvé pili jste víno z něho. Nadto bohy stříbrné a zlaté, měděné, železné, dřevěné a kamenné, kteříž nevidí, ani slyší, aniž co vědí, chválil jsi, Boha pak, v jehož ruce jest dýchání tvé i všecky cesty tvé, neoslavoval jsi.'),
(1568159,54,27,5,24,'Protož nyní od něho poslána jest částka ruky této, a písmo to napsáno jest.'),
(1568160,54,27,5,25,'A totoť jest písmo napsané: Mene, mene, tekel, ufarsin, totiž: Zčetl jsem, zčetl, zvážil a rozděluji.'),
(1568161,54,27,5,26,'Tento pak jest výklad slov: Mene, zčetl Bůh království tvé, a k konci je přivedl.'),
(1568162,54,27,5,27,'Tekel, zvážen jsi na váze, a nalezen jsi lehký.'),
(1568163,54,27,5,28,'Peres, rozděleno jest království tvé, a dáno jest Médským a Perským.'),
(1568164,54,27,5,29,'Tedy z rozkazu Balsazarova oblékli Daniele v šarlat, a řetěz zlatý dali na hrdlo jeho, a rozhlašovali o něm, že má býti pánem třetím v království.'),
(1568165,54,27,5,30,'V touž noc zabit jest Balsazar král Kaldejský.'),
(1568166,54,27,5,31,'Darius pak Médský ujal království v letech okolo šedesáti a dvou.'),
(1568167,54,27,6,1,'Líbilo se pak Dariovi, aby ustanovil nad královstvím úředníků sto a dvadceti, kteříž by byli po všem království.'),
(1568168,54,27,6,2,'Nad těmi pak hejtmany tři, z nichžto Daniel přední byl, kterýmž by úředníci onino vydávali počet, aby se králi škoda nedála.'),
(1568169,54,27,6,3,'Tedy Daniel převyšoval ty hejtmany a úředníky, proto že duch znamenitější v něm byl. Pročež král myslil ustanoviti jej nade vším královstvím.'),
(1568170,54,27,6,4,'Tedy hejtmané a úředníci hledali příčiny proti Danielovi s strany království, a však žádné příčiny ani vady nemohli najíti; nebo věrný byl, aniž jaký omyl neb vada nalézala se při něm.'),
(1568171,54,27,6,5,'Protož muži ti řekli: Nenajdeme proti Danielovi tomuto žádné příčiny, jediné leč bychom našli něco proti němu s strany zákona Boha jeho.'),
(1568172,54,27,6,6,'Tedy hejtmané a úředníci ti shromáždivše se k králi, takto mluvili k němu: Darie králi, na věky buď živ.'),
(1568173,54,27,6,7,'Uradili se všickni hejtmané království, vývodové, úředníci, správcové a vůdcové, abys ustanovil nařízení královské, a utvrdil zápověd: Kdož by koli vložil žádost na kteréhokoli boha neb člověka do třidcíti dnů, kromě na tebe, králi, aby uvržen byl do jámy lvové.'),
(1568174,54,27,6,8,'Nyní tedy, ó králi, potvrď zápovědi této, a vydej mandát, kterýž by nemohl změněn býti podlé práva Médského a Perského, kteréž jest neproměnitelné.'),
(1568175,54,27,6,9,'Pročež král Darius vydal mandát a zápověd.'),
(1568176,54,27,6,10,'Daniel pak, když se dověděl, že jest vydán mandát, všel do domu svého, kdež otevřená byla okna v pokoji jeho proti Jeruzalému, a třikrát za den klekal na kolena svá, a modlíval se a vyznával se Bohu svému, tak jakož prvé to činíval.'),
(1568177,54,27,6,11,'Tedy muži ti shromáždivše se a nalezše Daniele, an se modlí a pokorně prosí Boha svého,'),
(1568178,54,27,6,12,'Tedy přistoupili a mluvili k králi o zápovědi královské: Zdaliž jsi nevydal mandátu, aby každý člověk, kdož by koli něčeho žádal od kterého boha neb člověka až do třidcíti dnů, kromě od tebe, králi, uvržen byl do jámy lvové? Odpověděv král, řekl: Pravéť jest slovo to, podlé práva Médského a Perského, kteréž jest neproměnitelné.'),
(1568179,54,27,6,13,'Tedy odpovídajíce, řekli králi: Daniel ten, kterýž jest z zajatých synů Judských, nechtěl dbáti na tvé, ó králi, nařízení, ani na mandát tvůj, kterýž jsi vydal, ale třikrát za den modlívá se modlitbou svou.'),
(1568180,54,27,6,14,'Tedy král, jakž uslyšel tu řeč, velmi se zarmoutil nad tím, a uložil král v mysli své vysvoboditi Daniele, a až do západu slunce usiloval ho vytrhnouti.'),
(1568181,54,27,6,15,'Ale muži ti shromáždivše se k králi, mluvili jemu: Věz, králi, že jest takové právo u Médských a Perských, aby každá výpověd a nařízení, kteréž by král ustanovil, neproměnitelné bylo.'),
(1568182,54,27,6,16,'I řekl král, aby přivedli Daniele, a uvrhli jej do jámy lvové. Mluvil pak král a řekl Danielovi: Bůh tvůj, kterémuž sloužíš ustavičně, on vysvobodí tebe.'),
(1568183,54,27,6,17,'A přinesen jest kámen jeden, a položen na díru té jámy, a zapečetil ji král prstenem svým a prsteny knížat svých, aby nebyl změněn ortel při Danielovi.'),
(1568184,54,27,6,18,'I odšel král na palác svůj, a šel ležeti, nic nejeda, a ničímž se obveseliti nedal, tak že i sen jeho vzdálen byl od něho.'),
(1568185,54,27,6,19,'Tedy král hned ráno vstav na úsvitě, s chvátáním šel k jámě lvové.'),
(1568186,54,27,6,20,'A jakž se přiblížil k jámě, hlasem žalostným zavolal na Daniele, a promluviv král, řekl Danielovi: Danieli, služebníče Boha živého, Bůh tvůj, kterémuž ty sloužíš ustavičně, mohl-liž tě vysvoboditi od lvů?'),
(1568187,54,27,6,21,'Tedy Daniel mluvil s králem, řka: Králi, na věky buď živ.'),
(1568188,54,27,6,22,'Bůh můj poslal anděla svého, kterýž zavřel ústa lvů, aby mi neuškodili; nebo před ním nevina nalezena jest při mně, nýbrž ani proti tobě, králi, nic zlého jsem neučinil.'),
(1568189,54,27,6,23,'Tedy král velmi se z toho zradoval, a rozkázal Daniele vytáhnouti z jámy. I vytažen byl Daniel z jámy, a žádného úrazu není nalezeno na něm; nebo věřil v Boha svého.'),
(1568190,54,27,6,24,'I rozkázal král, aby přivedeni byli muži ti, kteříž osočili Daniele, a uvrženi jsou do jámy lvové, oni i synové jejich i ženy jejich, a prvé než dopadli dna té jámy, zmocnili se jich lvové, a všecky kosti jejich zetřeli.'),
(1568191,54,27,6,25,'Tedy Darius král napsal všechněm lidem, národům a jazykům, kteříž bydlili po vší zemi: Pokoj váš rozmnožen buď.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568192,54,27,6,26,'Ode mne vyšlo nařízení toto, aby na všem panství království mého třásli a báli se před Bohem Danielovým; nebo on jest Bůh živý a zůstávající na věky, a království jeho nebude zrušeno, ani panování jeho až do konce.'),
(1568193,54,27,6,27,'Vysvobozuje a vytrhuje, a činí znamení a divy na nebi i na zemi, kterýž vysvobodil Daniele z moci lvů.'),
(1568194,54,27,6,28,'Danielovi pak šťastně se vedlo v království Dariovu, a v království Cýra Perského.'),
(1568195,54,27,7,1,'Léta prvního Balsazara krále Babylonského Daniel měl sen a vidění svá na ložci svém, i napsal ten sen krátkými slovy.'),
(1568196,54,27,7,2,'Mluvil Daniel a řekl? Viděl jsem u vidění svém v noci, a aj, čtyři větrové nebeští bojovali na moři velikém.'),
(1568197,54,27,7,3,'A čtyři šelmy veliké vystupovaly z moře, jedna od druhé rozdílná.'),
(1568198,54,27,7,4,'První podobná lvu, a křídla orličí měla. Hleděl jsem, až vytrhána byla křídla její, jimiž se vznášela od země, tak že na nohách jako člověk státi musila, a srdce lidské dáno jest jí.'),
(1568199,54,27,7,5,'A aj, jiná šelma druhá podobná nedvědu, kteráž panství jedno vyzdvihla, a tři žebra v ústech jejích, mezi zuby jejími, a tak mluveno bylo k ní: Vstaň, nažer se hojně masa.'),
(1568200,54,27,7,6,'Potom jsem viděl, a aj, jiná podobná pardovi, kteráž měla čtyři křídla ptačí na hřbetě svém, a čtyřhlavá byla šelma ta, jíž moc dána byla.'),
(1568201,54,27,7,7,'Potom viděl jsem u viděních nočních, a aj, šelma čtvrtá strašlivá a hrozná a velmi silná, mající zuby železné veliké, kteráž zžírala a potírala, ostatek pak nohama svýma pošlapávala; a ta byla rozdílná ode všech šelm, kteréž byly před ní, a měla rohů deset.'),
(1568202,54,27,7,8,'Pilně jsem šetřil těch rohů, a hle, roh poslední malý vyrostal mezi nimi, a tři z těch rohů prvních vyvráceni jsou před ním; a aj, oči podobné očím lidským v rohu tom, a ústa mluvící pyšně.'),
(1568203,54,27,7,9,'Hleděl jsem, až trůnové ti svrženi byli, a Starý dnů posadil se, jehož roucho jako sníh bílé, a vlasové hlavy jeho jako vlna čistá, trůn jako jiskry ohně, kola jeho jako oheň hořící.'),
(1568204,54,27,7,10,'Potok ohnivý tekl a vycházel od něho, tisícové tisíců sloužili jemu, a desetkrát tisíckrát sto tisíců stálo před ním; soud zasedl, a knihy otevříny byly.'),
(1568205,54,27,7,11,'Patřil jsem tehdáž, hned jakž se začal zvuk té řeči pyšné, kterouž roh mluvil; patřil jsem, dokudž ta šelma nebyla zabita, a vyhlazeno tělo její, a dáno k spálení ohni.'),
(1568206,54,27,7,12,'A i ostatkům šelm odjali panství; nebo dlouhost života jim odměřena byla až do času, a to uloženého času.'),
(1568207,54,27,7,13,'Viděl jsem u vidění nočním, a aj, s oblaky nebeskými podobný Synu člověka přicházel; potom až k Starému dnů přišel, a před něj postaven byl.'),
(1568208,54,27,7,14,'I dáno jest jemu panství a sláva i království, aby všickni lidé, národové a jazykové sloužili jemu; jehož panství jest panství věčné, kteréž nepomíjí, a království jeho, kteréž se neruší.'),
(1568209,54,27,7,15,'I zhrozil se duch můj ve mně Danielovi u prostřed těla, a vidění má předěsila mne.'),
(1568210,54,27,7,16,'Tedy přistoupil jsem k jednomu z přístojících, a ptal jsem se ho na jistotu vší té věci. I pověděl mi, a výklad řečí mi oznámil:'),
(1568211,54,27,7,17,'Ty šelmy veliké, kteréž jsou čtyry, jsou čtyři králové, kteříž povstanou z země,'),
(1568212,54,27,7,18,'A ujmou království svatých výsostí, kteříž obdržeti mají království až na věky, a až na věky věků.'),
(1568213,54,27,7,19,'Tedy žádostiv jsem byl zprávy o šelmě čtvrté, kteráž rozdílná byla ode všech jiných, hrozná velmi; zubové její železní, a pazoury její ocelivé, kteráž zžírala, potírala, ostatek pak nohama svýma pošlapávala.'),
(1568214,54,27,7,20,'Tolikéž o rozích desíti, kteříž byli na hlavě její, a o posledním, kterýž vyrostl, a před ním spadli tři; o tom rohu, pravím, kterýž měl oči a ústa mluvící pyšně, a byl na pohledění větší než jiní.'),
(1568215,54,27,7,21,'Viděl jsem, an roh ten válku vedl s svatými, a přemáhal je,'),
(1568216,54,27,7,22,'Až přišel Starý dnů, a oddán jest soud svatým výsostí, a čas přišel, aby to království svatí obdrželi.'),
(1568217,54,27,7,23,'Řekl takto: Šelma čtvrtá znamená království čtvrté na zemi, kteréž rozdílné bude ode všech království, a zžíře všecku zemi, a zmlátí ji a potře ji.'),
(1568218,54,27,7,24,'Rohů pak deset znamená, že z království toho deset králů povstane, a poslední povstane po nich, kterýž bude rozdílný od prvních, a poníží tří králů.'),
(1568219,54,27,7,25,'A slova proti Nejvyššímu mluviti bude, a svaté výsostí potře; nadto pomýšleti bude, aby proměnil časy i práva, když vydáni budou v ruku jeho, až do času a časů, i do částky časů.'),
(1568220,54,27,7,26,'V tom bude soud osazen, a panství jeho odejmou, vypléní a vyhladí je docela.'),
(1568221,54,27,7,27,'Království pak i panství, a důstojnost královská pode vším nebem dána bude lidu svatých výsostí; jehož království bude království věčné, a všickni páni jemu sloužiti a jeho poslouchati budou.'),
(1568222,54,27,7,28,'Až potud konec té řeči. Mne pak Daniele myšlení má velice zkormoutila, a krása má proměnila se při mně, slovo však toto v srdci svém zachoval jsem.'),
(1568223,54,27,8,1,'Léta třetího kralování Balsazara krále ukázalo mi se vidění, mně Danielovi po onom, kteréž se mi ukázalo na počátku.'),
(1568224,54,27,8,2,'I viděl jsem u vidění, (tehdáž pak, když jsem viděl, byl jsem v Susan, na hradě, kterýž jest v krajině Elam), viděl jsem, pravím, byv u potoka Ulai.'),
(1568225,54,27,8,3,'A pozdvih očí svých, viděl jsem, a aj, u toho potoka stál skopec jeden, kterýž měl dva rohy. A ti dva rohové byli vysocí, a však jeden vyšší než druhý, ale ten vyšší zrostl posléze.'),
(1568226,54,27,8,4,'Viděl jsem skopce toho, an trkal k západu, půlnoci a poledni, jemuž žádná šelma odolati nemohla, aniž kdo co mohl vytrhnouti z moci jeho; pročež činil podlé vůle své, a to věci veliké.'),
(1568227,54,27,8,5,'A když jsem to rozvažoval, aj, kozel přicházel od západu na svrchek vší země, a žádný se ho nedotýkal na zemi, a ten kozel měl roh znamenitý mezi očima svýma.'),
(1568228,54,27,8,6,'A přišel až k tomu skopci majícímu dva rohy, kteréhož jsem byl viděl stojícího u potoka, a přiběhl k němu v prchlivosti síly své.'),
(1568229,54,27,8,7,'Viděl jsem také, an dotřel na toho skopce, a rozlítiv se proti němu, udeřil jej, tak že zlámal oba rohy jeho, a nebylo síly v skopci k odpírání jemu. A poraziv ho na zemi, pošlapal jej, aniž byl, kdo by vytrhl skopce z moci jeho.'),
(1568230,54,27,8,8,'Kozel pak velikým učiněn jest velmi. A když se ssilil, zlámal se roh ten veliký, i zrostli znamenití čtyři místo něho, na čtyři strany světa.'),
(1568231,54,27,8,9,'Z těch pak jednoho vyšel roh jeden maličký, a zrostl velmi ku poledni a východu, a k zemi Judské.'),
(1568232,54,27,8,10,'A zpjal se až k vojsku nebeskému, a svrhl na zemi některé z vojska toho i z hvězd, a pošlapal je.'),
(1568233,54,27,8,11,'Anobrž až k vojska toho knížeti zpjal se, nebo od něho zastavena byla ustavičná obět, a zavržen příbytek svatyně Boží,'),
(1568234,54,27,8,12,'Tak že vojsko to vydáno v převrácenost proti ustavičné oběti, a povrhlo pravdu na zemi, a což činilo, šťastně mu se dařilo.'),
(1568235,54,27,8,13,'Tedy slyšel jsem jednoho svatého mluvícího, a řekl ten svatý tomu, kterýž tajné věci v počtu maje, mluví: Dokudž toto vidění o oběti ustavičné, a převrácenost na zpuštění přivodící trvati bude, a svaté služby vydávány budou i vojsko v pošlapání?'),
(1568236,54,27,8,14,'A řekli mi: Až do dvou tisíc a tří set večerů a jiter, a přijdou k obnovení svému svaté služby.'),
(1568237,54,27,8,15,'Stalo se pak, že když jsem já Daniel hleděl na to vidění, a ptal jsem se na rozum jeho, aj, postavil se podlé mne na pohledění jako muž.'),
(1568238,54,27,8,16,'Slyšel jsem také hlas lidský mezi Ulaiem, kterýžto zavolav, řekl: Gabrieli, vylož tomuto vidění to.'),
(1568239,54,27,8,17,'I přišel ke mně, kdež jsem stál, a když přišel, zhrozil jsem se, a padl jsem na tvář svou. I řekl ke mně: Pozoruj, synu člověčí; nebo v času uloženém vidění toto se naplní.'),
(1568240,54,27,8,18,'Když pak on mluvil se mnou, usnul jsem tvrdě, leže tváří svou na zemi. I dotekl se mne, a postavil mne tu, kdež jsem byl stál,'),
(1568241,54,27,8,19,'A řekl: Aj, já oznámím tobě to, což se díti bude až do vykonání hněvu toho; nebo v uloženém času konec bude.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568242,54,27,8,20,'Skopec ten, kteréhož jsi viděl, an měl dva rohy, jsou králové Médský a Perský.'),
(1568243,54,27,8,21,'Kozel pak ten chlupatý jest král Řecký, a roh ten veliký, kterýž jest mezi očima jeho, jest král první.'),
(1568244,54,27,8,22,'Že pak zlámán jest, a povstali čtyři místo něho, čtvero království z svého národu povstane, ale ne s takovou silou.'),
(1568245,54,27,8,23,'Při dokonání pak království jejich, když na vrch vzejdou nešlechetníci, povstane král nestydatý a chytrý.'),
(1568246,54,27,8,24,'Jehož síla zmocní se, ačkoli ne jeho silou, tak že ku podivení hubiti bude, a šťastně se mu povede, až i vše vykoná; nebo hubiti bude silné i lid svatý.'),
(1568247,54,27,8,25,'A obmyslností svou šťastně svede lest v předsevzetí svém, a v srdci svém zvelebí sebe, a v čas pokoje zhubí mnohé; nadto i proti knížeti knížat se postaví, a však bez rukou potřín bude.'),
(1568248,54,27,8,26,'Vidění pak to večerní a jitřní, o němž povědíno, jest jistá pravda; pročež ty zavři to vidění, nebo jest mnohých dnů.'),
(1568249,54,27,8,27,'Tedy já Daniel zchuravěl jsem, a nemocen jsem byl několik dnů. Potom povstav, konal jsem povinnost od krále poručenou, byv předěšen nad tím viděním, čehož však žádný na mně neseznal.'),
(1568250,54,27,9,1,'Léta prvního Daria syna Asverova z semene Médského, kteréhož učiněn jest králem v království Kaldejském,'),
(1568251,54,27,9,2,'Léta prvního kralování jeho já Daniel porozuměl jsem z knih počtu let, o nichž se stalo slovo Hospodinovo k Jeremiášovi proroku, že se vyplní zpuštění Jeruzaléma sedmdesátého léta.'),
(1568252,54,27,9,3,'A obrátil jsem tvář svou ku Pánu Bohu, hledaje ho modlitbou a pokornými prosbami, v postu, v žíni a popele.'),
(1568253,54,27,9,4,'I modlil jsem se Hospodinu Bohu svému, a vyznávaje se, řekl jsem: Prosím , Pane Bože silný, veliký a všeliké cti hodný, ostříhající smlouvy a dobrotivosti k těm, kteříž tě milují, a ostříhají přikázaní tvých.'),
(1568254,54,27,9,5,'Zhřešiliť jsme a převráceně jsme činili, bezbožnost jsme páchali, a protivili jsme se, a odvrátili od přikázaní tvých a soudů tvých.'),
(1568255,54,27,9,6,'Aniž jsme poslouchali služebníků tvých proroků, kteříž mluvívali ve jménu tvém králům našim, knížatům našim a otcům našim, i všemu lidu země.'),
(1568256,54,27,9,7,'Toběť, ó Pane, přísluší spravedlnost, nám pak zahanbení tváři, jakž se to děje nyní mužům Judským a obyvatelům Jeruzalémským, a všechněm Izraelským, blízkým i dalekým, ve všech zemích, kamž jsi je zahnal pro přestoupení jejich, jímž přestupovali proti tobě.'),
(1568257,54,27,9,8,'Námť, ó Hospodine, sluší zahanbení tváři, králům našim, knížatům našim a otcům našim, neboť jsme zhřešili proti tobě,'),
(1568258,54,27,9,9,'Pánu Bohu pak našemu milosrdenství a slitování, poněvadž jsme se protivili jemu,'),
(1568259,54,27,9,10,'A neposlouchali jsme hlasu Hospodina Boha našeho, abychom chodili v naučeních jeho, kteréž předkládal před oči naše skrze služebníky své proroky.'),
(1568260,54,27,9,11,'Nýbrž všickni Izraelští přestoupili zákon tvůj a odvrátili se, aby neposlouchali hlasu tvého; protož vylito jest na nás to prokletí a klatba, kteráž jest zapsána v zákoně Mojžíše služebníka Božího, nebo jsme zhřešili proti němu.'),
(1568261,54,27,9,12,'Pročež splnil slovo své, kteréž mluvil proti nám a proti soudcům našim, kteříž nás soudili, a uvedl na nás toto zlé veliké, jehož se nestalo pode vším nebem, jakéž se stalo v Jeruzalémě.'),
(1568262,54,27,9,13,'Tak jakž zapsáno jest v zákoně Mojžíšově, všecko to zlé přišlo na nás, a však ani tak jsme se nekořili před tváří hněvivou Hospodina Boha našeho, abychom se odvrátili od nepravostí svých, a šetřili pravdy jeho.'),
(1568263,54,27,9,14,'Protož neobmeškal Hospodin s tím zlým, ale uvedl je na nás; nebo spravedlivý jest Hospodin Bůh náš ve všech skutcích svých, kteréž činí, jehož hlasu poslušni jsme nebyli.'),
(1568264,54,27,9,15,'Nyní však, ó Pane Bože náš, kterýž jsi vyvedl lid svůj z země Egyptské rukou silnou, a způsobils sobě jméno, jakéž jest dnešního dne, zhřešili jsme, bezbožně jsme činili.'),
(1568265,54,27,9,16,'Ó Pane, podlé vší tvé dobrotivosti nechť se, prosím, odvrátí hněv tvůj a prchlivost tvá od města tvého Jeruzaléma, hory svatosti tvé; nebo pro hříchy naše a pro nepravosti otců našich Jeruzalém a lid tvůj v pohanění jest u všech, kteříž jsou vůkol nás.'),
(1568266,54,27,9,17,'Nyní tedy, ó Bože náš, vyslyš modlitbu služebníka svého, a pokorné prosby jeho, a zasvěť tvář svou nad svatyní svou spuštěnou, pro Pána.'),
(1568267,54,27,9,18,'Nakloň, Bože můj, ucha svého a slyš, otevři oči své a viz zpuštění naše i města, kteréž jest nazváno od jména tvého; nebo ne pro nějaké naše spravedlnosti padajíce, pokorně prosíme tebe, ale pro milosrdenství tvá mnohá.'),
(1568268,54,27,9,19,'Vyslyšiž, ó Pane, Pane, odpusť, Pane, pozoruj a učiň; neprodlévejž pro sebe samého, můj Bože, nebo od jména tvého nazváno jest město toto i lid tvůj.'),
(1568269,54,27,9,20,'Ještě jsem mluvil a modlil se, a vyznával hřích svůj i hřích lidu svého Izraelského, a padna, pokorně jsem se modlil před tváří Hospodina Boha svého, za horu svatosti Boha svého,'),
(1568270,54,27,9,21,'Ještě, pravím, mluvil jsem při modlitbě, a muž ten Gabriel, kteréhož jsem viděl v tom vidění na počátku, rychle přiletěv, dotekl se mne v čas oběti večerní.'),
(1568271,54,27,9,22,'A slouže mi k srozumění, mluvil se mnou a řekl: Danieli, nyní jsem vyšel, abych tě naučil vyrozumívati tajemstvím.'),
(1568272,54,27,9,23,'Při počátku pokorných proseb tvých vyšlo slovo, a já jsem přišel, aťbych je oznámil, nebo jsi velmi milý; pročež pozoruj slova toho, a rozuměj vidění tomu.'),
(1568273,54,27,9,24,'Sedmdesáte téhodnů odečteno jest lidu tvému a městu svatému tvému k zabránění převrácenosti a k zapečetění hříchů, i vyčištění nepravosti a k přivedení spravedlnosti věčné, a k zapečetění vidění i proroctví, a ku pomazání Svatého svatých.'),
(1568274,54,27,9,25,'Věziž tedy a rozuměj, že od vyjití výpovědi o navrácení a o vystavení Jeruzaléma až do Mesiáše vývody bude téhodnů sedm, potom téhodnů šedesáte dva, když již zase vzdělána bude ulice a příkopa, a ti časové budou přenesnadní.'),
(1568275,54,27,9,26,'Po téhodnech pak těch šedesáti a dvou zabit bude Mesiáš, však jemu to nic neuškodí; nýbrž to město i tu svatyni zkazí, i lid ten svůj budoucí, tak že skončení jeho bude hrozné, ano i do vykonání boje bude boj stálý všelijak do vyplénění.'),
(1568276,54,27,9,27,'Utvrdí však smlouvu mnohým v téhodni posledním, u prostřed pak toho téhodne učiní konec oběti zápalné i oběti suché; a skrze vojsko ohavné, až do posledního a uloženého poplénění hubící, na popléněné vylito bude zpuštění.'),
(1568277,54,27,10,1,'Léta třetího Cýra krále Perského, zjeveno bylo slovo Danielovi, kterýž sloul jménem Baltazar, a pravé bylo slovo to, i uložený čas dlouhý, a rozum toho slova i smysl zjeven jemu u vidění.'),
(1568278,54,27,10,2,'V těch dnech já Daniel kvílil jsem za tři téhodny dnů.'),
(1568279,54,27,10,3,'Pokrmu pochotného jsem nejedl, ani maso ani víno nevešlo do úst mých, aniž jsem se mastí mazal, až se vyplnili dnové tří téhodnů.'),
(1568280,54,27,10,4,'Dne pak dvadcátého čtvrtého měsíce prvního, když jsem byl na břehu řeky veliké, to jest Hiddekel.'),
(1568281,54,27,10,5,'Pozdvih očí svých, viděl jsem, a aj, muž jeden oděný v roucho lněné, a bedra jeho přepásaná byla zlatem ryzím z Ufaz.'),
(1568282,54,27,10,6,'Tělo pak jeho jako tarsis, a oblíčej jeho na pohledění jako blesk, a oči jeho podobné pochodním hořícím, a ramena jeho i nohy jeho na pohledění jako měď vypulerovaná, a zvuk slov jeho podobný zvuku množství.'),
(1568283,54,27,10,7,'Viděl jsem pak já Daniel sám vidění to, ale muži ti, kteříž se mnou byli, neviděli toho vidění, než hrůza veliká připadla na ně, až i utekli, aby se skryli.'),
(1568284,54,27,10,8,'Pročež já zůstal jsem sám, a viděl jsem vidění to veliké, ale nezůstalo i ve mně síly, a krása má změnila se, a porušila na mně, aniž jsem mohl zadržeti síly.'),
(1568285,54,27,10,9,'Tedy slyšel jsem zvuk slov jeho, a uslyšav zvuk slov jeho, usnul jsem tvrdě na tváři své, na tváři své na zemi.'),
(1568286,54,27,10,10,'V tom aj, ruka dotkla se mne, a pozdvihla mne na kolena má a na dlaně rukou mých.'),
(1568287,54,27,10,11,'I řekl mi: Danieli, muži velmi milý, pozoruj slov, kteráž já mluviti budu tobě, a stůj na místě svém, nebo nyní poslán jsem k tobě. A když promluvil ke mně slovo to, stál jsem, třesa se.'),
(1568288,54,27,10,12,'Pročež řekl mi: Nebojž se, Danieli; nebo od prvního dne, jakž jsi přiložil srdce své, abys rozuměl, a trápil se před Bohem svým, vyslyšána jsou slova tvá, a já přišel jsem příčinou slov tvých.'),
(1568289,54,27,10,13,'Ale kníže království Perského postavovalo se proti mně za jedenmecítma dnů, až aj, Michal, jeden přední z knížat, přišel mi na pomoc; protož jsem já zůstával tam při králích Perských.'),
(1568290,54,27,10,14,'Již pak přišel jsem, aťbych oznámil, co potkati má lid tvůj v potomních dnech; nebo ještě vidění bude o těch dnech.'),
(1568291,54,27,10,15,'A když mluvil ke mně ta slova, sklopiv tvář svou k zemi, oněměl jsem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568292,54,27,10,16,'A aj, jako podobnost člověka dotkla se rtů mých, a otevřev ústa svá, mluvil jsem a řekl tomu, kterýž stál naproti mně: Pane můj, příčinou toho vidění obrátili se bolesti mé na mne, a aniž jsem síly zadržeti mohl.'),
(1568293,54,27,10,17,'Jakž tedy bude moci služebník Pána mého takový mluviti se Pánem mým takovým, poněvadž ve mně od toho času, ve mně, pravím, nezůstalo síly, ani dchnutí nepozůstalo ve mně?'),
(1568294,54,27,10,18,'Pročež opět dotkl se mne na pohledění jako člověk, a posilnil mne.'),
(1568295,54,27,10,19,'A řekl: Neboj se, muži velmi milý, pokoj tobě, posilň se, posilň se, pravím. Když pak on mluvil se mnou, posilněn jsa, řekl jsem: Nechť mluví Pán můj, nebo jsi mne posilnil.'),
(1568296,54,27,10,20,'I řekl: Víš-liž, proč jsem přišel k tobě? Nebo již navrátím se, abych bojoval s knížetem Perským. A já odcházím, a aj, kníže Řecké přitáhne.'),
(1568297,54,27,10,21,'Ale oznámímť to, což jest zapsáno v psání pravdomluvném; nebo ani jednoho není, ješto by sobě zmužile počínal se mnou v těch věcech, kromě Michala knížete vašeho.'),
(1568298,54,27,11,1,'A tak já léta prvního Daria Médského postavil jsem se, abych ho zmocňoval a posiloval.'),
(1568299,54,27,11,2,'Již pak oznámímť pravdu: Aj, ještě tři králové kralovati budou v Perské zemi; potom čtvrtý zbohatne bohatstvím velikým nade všecky, a když se zmocní v bohatství svém, vzbudí všecky proti království Řeckému.'),
(1568300,54,27,11,3,'I povstane král mocný, kterýž bude míti panství široké, a bude činiti podlé vůle své.'),
(1568301,54,27,11,4,'Když se pak zmocní, potříno bude království jeho, a rozděleno bude na čtyři strany světa, však ne mezi potomky jeho, aniž bude panství jeho takové, jakéž bylo; nebo vykořeněno bude království jeho, a jiným mimo ně se dostane.'),
(1568302,54,27,11,5,'Pročež posilní se král polední, ano i jedno z knížat jeho, a mocnější bude nad něho, a panovati bude; panství široké bude panství jeho.'),
(1568303,54,27,11,6,'Po některých pak letech spřízní se; nebo dcera krále poledního dostane se za krále půlnočního, aby učinila příměří. Ale neobdrží síly ramene, aniž on ostojí s ramenem svým, ale vydána bude ona i ti, kteříž ji přivedou, i syn její, i ten, kterýž ji posilňoval v ty časy.'),
(1568304,54,27,11,7,'Potom povstane z výstřelku kořenů jejích na místo jeho, kterýž přitáhne s vojskem svým, a udeří na pevnost krále půlnočního, a přičiní se, aby se jich zmocnil.'),
(1568305,54,27,11,8,'Nadto i bohy jejich s knížaty jejich, s nádobami drahými jejich, stříbrem a zlatem v zajetí zavede do Egypta, a bude bezpečen za mnoho let před králem půlnočním.'),
(1568306,54,27,11,9,'A tak přijde do království král polední, a navrátí se do země své.'),
(1568307,54,27,11,10,'Ale synové onoho válčiti budou, a seberou množství vojsk velikých. A nenadále přijda, jako povodeň procházeti bude, a navracuje se, válkou dotírati bude až k jeho pevnostem.'),
(1568308,54,27,11,11,'Pročež rozdrážděn jsa král polední, vytáhne, a bojovati bude s ním, s králem půlnočním, a sšikuje množství veliké, i bude vydáno množství to v ruku jeho.'),
(1568309,54,27,11,12,'I pozdvihne se množství to, a povýší se srdce jeho, a ačkoli porazí na tisíce, a však se nezmocní.'),
(1568310,54,27,11,13,'Potom navrátě se král půlnoční, sšikuje množství větší než prvé, a po dokonání času některých let, nenadále přijde s vojskem velikým a s dostatkem hojným.'),
(1568311,54,27,11,14,'V těch časích mnozí se postaví proti králi polednímu, ale synové nešlechetní z lidu tvého zhubeni budou, a pro stvrzení vidění tohoto padnou.'),
(1568312,54,27,11,15,'Nebo přitáhne král půlnoční, a vzdělaje náspy, dobude měst hrazených, tak že ramena poledního neostojí, ani lid vybraný jeho, aniž budou míti síly k odpírání.'),
(1568313,54,27,11,16,'A přitáhna proti němu, bude činiti podlé vůle své, a nebude žádného, ješto by se postavil proti němu. Postaví se také v zemi Judské, kterouž docela zkazí rukou svou.'),
(1568314,54,27,11,17,'Potom obrátí tvář svou, aby přitáhna s mocí všeho království svého, a ukazuje se jako by vše upřímě jednal, dovede něčeho. Nebo dá jemu krásnou pannu, aby ho zahubil skrze ni, ale ona nedostojí aniž bude držeti s ním.'),
(1568315,54,27,11,18,'Zatím obrátí tvář svou k ostrovům, a dobude mnohých, ale vůdce přítrž učiní pohanění jeho, anobrž to hanění jeho na něj obrátí.'),
(1568316,54,27,11,19,'Pročež obrátí tvář svou k pevnostem země své, ale klesne a padne, i zahyne.'),
(1568317,54,27,11,20,'I povstane na místo jeho v slávě královské ten, kterýž rozešle výběrčí, ale ten po nemnohých dnech potřín bude, a to ne v hněvě, ani v boji.'),
(1568318,54,27,11,21,'Na místě tohoto postaví se nevzácný, ačkoli nevloží na něj ozdoby královské, a však přijda pokojně, ujme království skrze úlisnost.'),
(1568319,54,27,11,22,'A rameny jako povodní zachváceni budou před oblíčejem jeho mnozí, a potříni budou jako i ten vůdce, kterýž s ním smlouvu učinil.'),
(1568320,54,27,11,23,'Nebo v tovaryšství s ním vejda, prokáže nad ním lest, a přijeda, zmocní se království s malým počtem lidu.'),
(1568321,54,27,11,24,'Bezpečně také i do nejúrodnějších míst té krajiny vpadne, a činiti bude to, čehož nečinili otcové jeho, ani otcové otců jeho; loupež a kořisti a zboží jim rozdělí, ano i proti pevnostem chytrosti své vymýšleti bude, a to do času.'),
(1568322,54,27,11,25,'Potom vzbudí sílu svou a srdce své proti králi polednímu s vojskem velikým, s nímž král polední vojensky se potýkati bude, s vojskem velikým a velmi silným, ale neostojí, proto že vymyslí proti němu chytrost.'),
(1568323,54,27,11,26,'Nebo kteříž jídají pokrm, potrou jej, když vojsko onoho se rozvodní; i padnou, zbiti jsouce mnozí.'),
(1568324,54,27,11,27,'Tehdáž obou těch králů srdce bude činiti zlé, a za jedním a týmž stolem lež mluviti budou, ale nepodaří se, proto že cíl uložený na jiný ještě čas odložen.'),
(1568325,54,27,11,28,'A protož navrátí se do země své s zbožím velikým, a srdce jeho bude proti smlouvě svaté. Což učině, navrátí se do země své.'),
(1568326,54,27,11,29,'V uložený čas navrátě se, potáhne na poledne, ale to nebude podobné prvnímu ani poslednímu.'),
(1568327,54,27,11,30,'Nebo přijdou proti němu lodí Citejské, pročež bude jej to boleti, tak že opět zlobiti se bude proti smlouvě svaté. Což učině, navrátí se, a srozumění míti bude s těmi, kteříž opustili smlouvu svatou.'),
(1568328,54,27,11,31,'A vojska veliká podlé něho státi budou, a poškvrní svatyně a pevnosti; odejmou také obět ustavičnou, a postaví ohavnost zpuštění,'),
(1568329,54,27,11,32,'Tak aby ty, kteříž se bezbožně proti smlouvě chovati budou, v pokrytství posiloval úlisnostmi, lid pak, kterýž zná Boha svého, aby jímali. Což i učiní.'),
(1568330,54,27,11,33,'Pročež vyučující lid, vyučující mnohé, padati budou od meče a ohně, zajetí a loupeže za mnohé dny.'),
(1568331,54,27,11,34,'A když padati budou, malou pomoc míti budou; nebo připojí se k nim mnozí pochlebně.'),
(1568332,54,27,11,35,'Z těch pak, kteříž jiné vyučují, padati budou, aby prubováni a čištěni a bíleni byli až do času jistého; neboť to ještě potrvá až do času uloženého.'),
(1568333,54,27,11,36,'Král zajisté ten bude činiti podlé vůle své, a pozdvihne se a zvelebí nad každého boha, i proti Bohu nade všemi bohy nejsilnějšímu mluviti bude divné věci; a šťastně se mu povede až do vykonání prchlivosti, ažby se to, což uloženo jest, vykonalo.'),
(1568334,54,27,11,37,'Ani k bohům otců svých se nenakloní, ani k milování žen, aniž k komu z bohů se nakloní, proto že se nade všecko velebiti bude.'),
(1568335,54,27,11,38,'A na místě Boha nejsilnějšího ctíti bude boha, kteréhož neznali otcové jeho; ctíti bude zlatem a stříbrem, a kamením drahým a klénoty.'),
(1568336,54,27,11,39,'A tak dovede toho, že pevnosti Nejsilnějšího budou boha cizího, a kteréž se mu viděti bude, poctí slávou, a způsobí, aby panovali nad mnohými, a zemi rozdělí místo mzdy.'),
(1568337,54,27,11,40,'Při dokonání pak toho času trkati se s ním bude král polední, ale král půlnoční oboří se na něj s vozy a s jezdci a lodími mnohými, a přitáhna do zemí, jako povodeň projde.'),
(1568338,54,27,11,41,'Potom přitáhne do země Judské, a mnohé země padnou. Tito pak ujdou ruky jeho, Idumejští a Moábští, a prvotiny synů Ammon.'),
(1568339,54,27,11,42,'A když ruku svou vztáhne na země, ani země Egyptská nebude moci jeho zniknouti.'),
(1568340,54,27,11,43,'Nebo opanuje poklady zlata a stříbra, a všecky klénoty Egyptské; Lubimští také a Mouřenínové za ním půjdou.'),
(1568341,54,27,11,44,'V tom noviny od východu a od půlnoci přestraší jej; pročež vytáhne s prchlivostí velikou, aby hubil a mordoval mnohé.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568342,54,27,11,45,'I rozbije stany paláce svého mezi mořemi, na hoře okrasy svatosti; a když přijde k skonání svému, nebude míti žádného spomocníka.'),
(1568343,54,27,12,1,'Toho času postaví se Michal, kníže veliké, kterýž zastává synů lidu tvého, a bude čas ssoužení, jakéhož nebylo, jakž jest národ, až do toho času; toho, pravím, času vysvobozen bude lid tvůj, kdožkoli nalezen bude zapsaný v knize.'),
(1568344,54,27,12,2,'Tuť mnozí z těch, kteříž spí v prachu země, procítí, jedni k životu věčnému, druzí pak ku pohanění a ku potupě věčné.'),
(1568345,54,27,12,3,'Ale ti, kteříž jiné vyučují, stkvíti se budou jako blesk oblohy, a kteříž k spravedlnosti přivozují mnohé, jako hvězdy na věčné věky.'),
(1568346,54,27,12,4,'Ty pak Danieli, zavři slova tato, a zapečeť knihu tuto až do času jistého. Mnozíť budou pilně zpytovati, a rozmnoženo bude umění.'),
(1568347,54,27,12,5,'Zatím viděl jsem já Daniel, a aj, jiní dva stáli, jeden z této strany břehu řeky, a druhý z druhé strany břehu též řeky.'),
(1568348,54,27,12,6,'A řekl muži tomu oblečenému v roucho lněné, kterýž stál nad vodou té řeky: Když bude konec těm divným věcem?'),
(1568349,54,27,12,7,'I slyšel jsem muže toho oblečeného v roucho lněné, kterýž stál nad vodou té řeky, an zdvihl pravici svou i levici svou k nebi, a přisáhl skrze Živého na věky, že po uloženém času, a uložených časích, i půl času, a když do cela rozptýlí násilí lidu svatého, dokonají se všecky tyto věci.'),
(1568350,54,27,12,8,'A když jsem já slyše, nerozuměl, řekl jsem: Pane můj, jaký konec bude těch věcí?'),
(1568351,54,27,12,9,'Tedy řekl: Odejdi, Danieli, nebo zavřína jsou a zapečetěna slova ta až do času jistého.'),
(1568352,54,27,12,10,'Přečišťováni a bíleni a prubováni budou mnozí; bezbožní zajisté bezbožnost páchati budou, aniž co porozumějí kteří z nich, ale moudří porozumějí.'),
(1568353,54,27,12,11,'Od toho pak času, v němž odjata bude obět ustavičná, a postavena ohavnost hubící, bude dnů tisíc, dvě stě a devadesát.'),
(1568354,54,27,12,12,'Blahoslavený, kdož dočeká a přijde ke dnům tisíci, třem stům, třidcíti a pěti.'),
(1568355,54,27,12,13,'Ty pak odejdi k místu svému, a odpočívati budeš, a zůstaneš v losu svém na skonání dnů.'),
(1568356,54,28,1,1,'Slovo Hospodinovo, kteréž se stalo k Ozeášovi synu Bérovu za dnů Uziáše, Jotama, Achasa, Ezechiáše, králů Judských, a za dnů Jeroboáma syna Joasova, krále Izraelského.'),
(1568357,54,28,1,2,'Když Hospodin začal mluviti k Ozeášovi, řekl Hospodin Ozeášovi: Jdi, pojmi sobě ženu smilnou, a děti z smilstva; nebo nestydatě smilněci tato země, odvrátila se od Hospodina.'),
(1568358,54,28,1,3,'A tak šel a pojal Gomeru, dceru Diblaimskou, kterážto počala a porodila jemu syna.'),
(1568359,54,28,1,4,'Tedy řekl jemu Hospodin: Nazoviž jméno jeho Jezreel; nebo po malém času já vyhledávati budu krve Jezreel na domu Jéhu, a přestati káži království domu toho.'),
(1568360,54,28,1,5,'I stane se v ten den, že polámi lučiště Izraelovo v údolí Jezreel.'),
(1568361,54,28,1,6,'Opět počala znovu a porodila dceru. I řekl jemu: Nazov jméno její Lorucháma; nebo již více neslituji se nad domem Izraelským, abych jim co prominouti měl.'),
(1568362,54,28,1,7,'Ale nad domem Judským se slituji, a vysvobodím je skrze Hospodina Boha jejich; nebo nevysvobodím jich lučištěm a mečem, ani bojem, koňmi neb jezdci.'),
(1568363,54,28,1,8,'Potom ostavivši Loruchámu, opět počala a porodila syna.'),
(1568364,54,28,1,9,'I řekl: Nazov jméno jeho Loammi; nebo vy nejste lid můj, a já také nebudu váš.'),
(1568365,54,28,1,10,'A však bude počet synů Izraelských jako písku mořského, kterýž ani změřen, ani sečten býti nemůže. A stane se, že místo toho, kdež řečeno jim bylo: Nejste vy lid můj, řečeno jim bude: Synové Boha silného a živého jste.'),
(1568366,54,28,1,11,'I budou shromážděni synové Judští a synové Izraelští spolu, a ustanovíce nad sebou hlavu jednu, vyjdou z této země, ačkoli veliký bude den Jezreel.'),
(1568367,54,28,2,1,'Rcete bratřím vašim: Ó lide můj, a sestrám vašim: Ó milosrdenství došlá.'),
(1568368,54,28,2,2,'Odpor veďte proti matce vaší, dokažte, že ona není manželka má, a že já nejsem muž její, leč odvaruje smilství svých od tváři své, a cizoložství svých z prostřed prsí svých,'),
(1568369,54,28,2,3,'Abych jí nesvlékl do naha, a nepostavil jí tak, jakž byla v den narození svého, a učině ji podobnou poušti, a obrátě ji jako v zemi vyprahlou, umořil bych ji žízní.'),
(1568370,54,28,2,4,'Neslitoval bych se ani nad syny jejími, proto že jsou synové z smilstva.'),
(1568371,54,28,2,5,'Nebo smilní matka jejich, hanebnost páše rodička jejich; říká zajisté: Půjdu za frejíři svými, kteříž mi dodávají chleba mého, vody mé, vlny mé, lnu mého, oleje mého i nápojů mých.'),
(1568372,54,28,2,6,'A protož aj, já opletu cestu její trním, a ohradím hradbou, aby stezek svých nalezti nemohla.'),
(1568373,54,28,2,7,'Tehdy běhati bude za frejíři svými, a však nedostihne jich, hledati jich bude, ale nenalezne. I dí: Ej nu, již se navrátím k manželu svému prvnímu, proto že mi lépe tehdáž bylo než nyní.'),
(1568374,54,28,2,8,'Nebo ona nezná toho, že jsem já dával jí obilé, a mest a olej, anobrž rozmnožoval stříbro i zlato, kteréž vynakládají na Bále.'),
(1568375,54,28,2,9,'Protož poberu zase obilé své v čas jeho, i mest svůj v jistý čas jeho, a odejmu jí vlnu svou i len svůj k přiodívání nahoty její,'),
(1568376,54,28,2,10,'A tak v brzce odkryji mrzkost její před očima frejířů jejích, a žádný jí nevytrhne z ruky mé.'),
(1568377,54,28,2,11,'A učiním přítrž vší radosti její, svátkům jejím, novoměsícům jejím i sobotám jejím, a všechněm slavnostem jejím.'),
(1568378,54,28,2,12,'Pohubím také révoví její a fíkoví její, proto že říká: Ty věci jsou mzda má, kterouž mi dali frejíři moji; a obrátím je v les, a sžerou je živočichové polní.'),
(1568379,54,28,2,13,'A budu na ní vyhledávati dnů Bálů,v nichž jim kadí, a ozdoběci se náušnicemi svými a záponami svými, chodí za frejíři svými, na mne se pak zapomíná, praví Hospodin.'),
(1568380,54,28,2,14,'Protož aj, já namluvím ji, když ji uvedu na poušť; nebo mluviti budu k srdci jejímu.'),
(1568381,54,28,2,15,'A dám jí vinice její od téhož místa, i údolé Achor místo dveří naděje, i bude tam zpívati jako za dnů mladosti své, totiž jako tehdáž, když vycházela z země Egyptské.'),
(1568382,54,28,2,16,'I stane se v ten den, dí Hospodin, že volati budeš: Muži můj, a nebudeš mne volati více: Báli můj.'),
(1568383,54,28,2,17,'Nebo vyprázdním jména Bálů z úst tvých, aniž připomínáni budou více v jménu svém.'),
(1568384,54,28,2,18,'A učiním pro tebe smlouvu v ten den s živočichy polními, a s ptactvem nebeským i s zeměplazy, lučiště pak a meč polámi, i válku odejmu z země, a způsobím to, aby bydleli bezpečně.'),
(1568385,54,28,2,19,'I zasnoubím tě sobě na věčnost, zasnoubím tě sobě, pravím, v spravedlnosti a v soudu a v dobrotivosti a v hojném milosrdenství.'),
(1568386,54,28,2,20,'Zasnoubím tě sobě také u víře, abys poznala Hospodina.'),
(1568387,54,28,2,21,'I stane se v ten den, že vyslýchati budu, dí Hospodin, vyslýchati budu nebesa, a ona vyslyší zemi.'),
(1568388,54,28,2,22,'Země pak vyslyší obilé, i mest, i olej, a ty věci vyslyší Jezreele.'),
(1568389,54,28,2,23,'Nebo ji rozseji sobě na zemi, a smiluji se nad Loruchámou, Loammi pak řeknu: Lid můj jsi ty, a on dí: Bože můj.'),
(1568390,54,28,3,1,'Opět řekl mi Hospodin: Ještě jdi, a zamiluj ženu, milou frejíři a cizoložnou, tak jako miluje Hospodin syny Izraelské, ačkoli oni hledí k bohům cizím, a milují kádě vína.'),
(1568391,54,28,3,2,'Tedy zjednal jsem ji sobě z patnácti stříbrných a z půldruhého chomeru ječmene.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568392,54,28,3,3,'A řekl jsem jí: Za mnoho dnů seď mi, nesmilni, aniž se vdávej za muže, a já také příčinou tvou.'),
(1568393,54,28,3,4,'Nebo za mnohé dny budou synové Izraelští bez krále, bez knížete, bez oběti, bez modly, bez efodu a terafim.'),
(1568394,54,28,3,5,'Potom pak obrátí se synové Izraelští, a hledati budou Hospodina Boha svého i Davida krále svého; a předěšeni jsouce, poběhnou k Hospodinu a k dobrotě jeho v posledních časích.'),
(1568395,54,28,4,1,'Slyšte slovo Hospodinovo, ó synové Izraelští, neboť má rozepři Hospodin s obyvateli země této, proto že není žádné věrnosti, ani žádného milosrdenství, ani žádné známosti Boží v této zemi.'),
(1568396,54,28,4,2,'Proklínání a lži a vraždy, a zlodějství i cizoložství na vrch zrostlo, a vražda vraždu postihá.'),
(1568397,54,28,4,3,'Protož kvíliti bude tato země, a umdlí všecko, což v ní přebývá, živočichové polní i ptactvo nebeské, ano i ryby mořské zhynou.'),
(1568398,54,28,4,4,'A však žádný jim nedomlouvej, aniž jich kdo tresci; nebo lid tvůj podobni jsou těm, kteříž se vadí s knězem.'),
(1568399,54,28,4,5,'Protož ve dne padneš, padne také i prorok s tebou v noci, zahladím i matku tvou.'),
(1568400,54,28,4,6,'Vyhlazen bude lid můj pro neumění. Poněvadž jsi ty pohrdl uměním, i tebou pohrdnu, abys mi kněžství nekonal; a že jsi zapomněl na zákon Boha svého, já také zapomenu se na syny tvé.'),
(1568401,54,28,4,7,'Čím se více rozmohli, tím více hřešili proti mně; slávu jejich v pohanění směním.'),
(1568402,54,28,4,8,'Oběti za hřích lidu mého jedí, protož k nepravosti jejich duše své pozdvihují.'),
(1568403,54,28,4,9,'Pročež stane se jakž lidu tak knězi. Nebo vyhledávati budu na něm cest jeho, a skutky jeho jemu vrátím.'),
(1568404,54,28,4,10,'I budou jísti, a však se nenasytí, smilniti budou, ale nerozmnoží se; nebo nechtějí pozoru míti na Hospodina.'),
(1568405,54,28,4,11,'Smilství a víno a mest odjímá srdce.'),
(1568406,54,28,4,12,'Lid můj dřeva svého se dotazuje, a hůl jeho oznamuje jemu; nebo je duch smilství v blud uvodí, aby smilnili, odcházejíce od Boha svého.'),
(1568407,54,28,4,13,'Na vrších hor obětují, a na pahrbcích kadí, pod doubím a topolím a jilmovím, nebo jest příhodný stín jejich; protož smilní dcery vaše, a nevěsty vaše cizoloží.'),
(1568408,54,28,4,14,'Nevyhledával-liž bych na dcerách vašich, že smilní, a na nevěstách vašich, že cizoloží, že tito s nevěstkami se oddělují, a s ženkami obětují? Anobrž lid, kterýž sobě nesrozumívá, padne.'),
(1568409,54,28,4,15,'Jestliže smilníš ty Izraeli, nechažť nehřeší Juda. Protož nechoďtež do Galgala, aniž vstupujte do Betaven, aniž přisahejte: Živť jest Hospodin.'),
(1568410,54,28,4,16,'Nebo jako jalovice tvrdošijná tvrdošijný jest Izrael, jižť je pásti bude Hospodin jako beránka na prostranně.'),
(1568411,54,28,4,17,'Efraim stovaryšil se s modlami, nechej ho.'),
(1568412,54,28,4,18,'Zpurné je činí nápoj jejich, velice smilní, milují: Dejte. Ochráncové jeho jsou ohyzda.'),
(1568413,54,28,4,19,'Zachvátí je vítr křídly svými, i budou zahanbeni pro své oběti.'),
(1568414,54,28,5,1,'Slyštež to, ó kněží, a pozorujte, dome Izraelský, i dome královský, poslouchejte, nebo proti vám soud tento jest, proto že jste osídlo v Masfa, a sítka rozestřená na vrchu Tábor.'),
(1568415,54,28,5,2,'Nýbrž k zabíjení uchylujíce se, připadají k zemi, ale já ztresci každého z nich.'),
(1568416,54,28,5,3,'Známť já Efraima, a Izrael není ukryt přede mnou; nebo nyní smilníš, Efraime, poškvrňuje se Izrael.'),
(1568417,54,28,5,4,'Nemají se k tomu, aby se obrátili k Bohu svému, proto že duch smilství mezi nimi jest, Hospodina pak znáti nechtějí,'),
(1568418,54,28,5,5,'Tak že hrdost Izraelova svědčí vůči proti němu; protož Izrael i Efraim padnou pro nepravost svou, padne také i Juda s nimi.'),
(1568419,54,28,5,6,'S stády bravů a skotů svých půjdou hledati Hospodina, však nenaleznou; vzdáliltě se od nich.'),
(1568420,54,28,5,7,'Hospodinu se zpronevěřili, nebo syny cizí zplodili; jižť je zžíře měsíc i s jměním jejich.'),
(1568421,54,28,5,8,'Trubte trubou v Gabaa, a na pozoun v Ráma; křičte v Betaven: Po tobě, ó Beniamine.'),
(1568422,54,28,5,9,'Efraim zpuštěn bude v den kázně, v němž po pokoleních Izraelských uvedu v známost pravdu.'),
(1568423,54,28,5,10,'Knížata Judská jsou podobná těm, kteříž přenášejí mezník; vyleji na ně jako vodu prchlivost svou.'),
(1568424,54,28,5,11,'Utištěn jest Efraim, potřín soudem, však sobě libuje choditi za rozkazem.'),
(1568425,54,28,5,12,'Protož i já byl jsem jako mol Efraimovi, a jako hnis domu Judovu.'),
(1568426,54,28,5,13,'Pročež vida Efraim neduh svůj, a Juda nežit svůj, utekl se Efraim k Assurovi, a poslal k králi, kterýž by se o něj zasadil. Ale on nebude moci zhojiti vás, ani uzdraviti vás od nežitů.'),
(1568427,54,28,5,14,'Nebo já jsem jako lítý lev Efraimovi, a jako lvíče domu Judovu; já, já uchvátím a ujdu, vezmu, a žádný nevytrhne.'),
(1568428,54,28,5,15,'Odejda, navrátím se na místo své, až se vinni dadí, a hledati budou tváři mé.'),
(1568429,54,28,6,1,'V úzkosti své ráno hledati mne budou: Poďte, a navraťme se k Hospodinu; nebo on uchvátil a zhojí nás, ubil a uvíže rány naše.'),
(1568430,54,28,6,2,'Obživí nás po dvou dnech, dne třetího vzkřísí nás, a budeme živi před oblíčejem jeho,'),
(1568431,54,28,6,3,'Tak abychom znajíce Hospodina, více poznávati se snažovali; nebo jako jitřní svitání jest vycházení jeho, a přijde nám jako déšť jarní a podzimní na zemi.'),
(1568432,54,28,6,4,'Což mám činiti s tebou, ó Efraime? Což mám činiti s tebou, ó Judo, ano vaše dobrota jest jako oblak ranní, a jako rosa jitřní pomíjející?'),
(1568433,54,28,6,5,'Protož otesával jsem skrze proroky, zbil jsem je řečmi úst svých, aby soudů tvých světlo vzešlo.'),
(1568434,54,28,6,6,'Nebo milosrdenství oblibuji a ne obět, a známost Boha více než zápaly.'),
(1568435,54,28,6,7,'Ale oni smlouvu mou jako lidskou přestoupili, a tu se mi zpronevěřili.'),
(1568436,54,28,6,8,'Galád město činitelů nepravosti, plné šlepějí krvavých.'),
(1568437,54,28,6,9,'Rota pak kněžstva jsou jako lotři, kteříž na někoho čekají na cestě, kudyž se jde do Sichem; nebo zúmyslnou nešlechetnost páší.'),
(1568438,54,28,6,10,'V domě Izraelském vidím hroznou věc: Tam smilstvím Efraimovým poškvrňuje se Izrael.'),
(1568439,54,28,6,11,'Ano i u tebe, ó Judo, vsadil rouby, když jsem já zase vedl zajatý lid svůj.'),
(1568440,54,28,7,1,'Když léčím Izraele, tedy zjevuje se nepravost Efraimova a zlosti Samařské; nebo provodí faleš. Vnitř zlodějství, a vně provozují loupežnictví.'),
(1568441,54,28,7,2,'Aniž na to pomýšlejí v srdci svém, že na všecku nešlechetnost jejich pamatují; již je obkličují skutkové jejich, a před mým oblíčejem jsou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568442,54,28,7,3,'Nešlechetností svou obveselují krále, a klamy svými knížata.'),
(1568443,54,28,7,4,'Všickni napořád cizoloží, podobni jsouce peci zanícené od pekaře, kterýž přestává bdíti, jen ažby zadělané těsto zkynulo.'),
(1568444,54,28,7,5,'V den krále našeho k nemoci jej přivodí knížata láhvicí vína; vztahuje ruku svou s posměvači.'),
(1568445,54,28,7,6,'Nebo přiložili k úkladům svým srdce své podobné peci; celou noc spí pekař jejich, v jitře hoří jako plamen ohně.'),
(1568446,54,28,7,7,'Všickni napořád rozpáleni jsou jako pec, a zžírají soudce své; všickni králové jejich padají, aniž kdo z nich volá ke mně.'),
(1568447,54,28,7,8,'Efraim s národy smísil se, Efraim bude chléb podpopelný neobrácený.'),
(1568448,54,28,7,9,'Cizozemci zžírají sílu jeho, ačkoli on toho nezná; i šedinami prokvítaje, však vždy toho nezná.'),
(1568449,54,28,7,10,'A ačkoli pýcha Izraelova svědčí vůči proti němu, však se nenavracují k Hospodinu Bohu svému, aniž ho hledají s tím se vším.'),
(1568450,54,28,7,11,'A Efraim jest jako holubice hloupá bez srdce; k Egyptskému králi volají, k Assyrskému se utíkají.'),
(1568451,54,28,7,12,'Když odejdou, roztáhnu na ně sítku svou, a jako ptactvo nebeské přitrhnu je; kárati je budu tak, jakž slýcháno bylo o tom v shromáždění jejich.'),
(1568452,54,28,7,13,'Běda jim, že jsou poběhli mne. Zpuštění na ně, proto že se mi zpronevěřili, ješto jsem já je vykoupil, ale oni mluvili proti mně lži.'),
(1568453,54,28,7,14,'Aniž volají ke mně z srdce svého, když kvílí na ložcích svých, a když pro obilé a mest shromažďujíce se, obracejí se ke mně,'),
(1568454,54,28,7,15,'Ješto já potrestav, posiloval jsem ramen jejich, ale oni proti mně zlé vymýšlejí.'),
(1568455,54,28,7,16,'Navracujíť se, ale ne k Nejvyššímu, jsou jako lučiště omylné, padají od meče knížata jejich, od rozhněvání jazyka jejich, což jim ku posměchu jest v zemi Egyptské.'),
(1568456,54,28,8,1,'Přičině k ústům svým troubu, rci: Aj, letí jako orlice na dům Hospodinův, proto že přestoupili smlouvu mou, a proti zákonu mému převráceně činili.'),
(1568457,54,28,8,2,'Budouť sic volati: Bože můj, znáť tebe Izrael,'),
(1568458,54,28,8,3,'Ale opustilť jest Izrael dobré, nepřítel jej stihati bude.'),
(1568459,54,28,8,4,'Oniť ustanovují krále, ale beze mne; knížata vyzdvihují, k nimž já se neznám; z stříbra i z zlata svého činí sobě modly k svému zkažení.'),
(1568460,54,28,8,5,'Opustíť je tele tvé, ó Samaří, když se zažhne prchlivost má na ně. Až dokudž nebudou moci ostříhati nevinnosti?'),
(1568461,54,28,8,6,'Však i ono jest od Izraele, řemeslník je udělal, a neníť Bohem; nebo drtiny budou z toho telete Samařského.'),
(1568462,54,28,8,7,'Poněvadž větru rozsívají, takéť vichřici žíti budou; ani stébla žádného míti nebudou; úroda nevydá mouky, a by pak i vydala, cizozemci to sehltí.'),
(1568463,54,28,8,8,'Sehlcen bude Izrael, tudíž budou mezi pohany jako nádoba, v níž není žádné líbosti.'),
(1568464,54,28,8,9,'Proto že se oni utíkají k Assurovi, oslu divokému, kterýž jest toliko sám svůj, a že Efraim sobě najímá milovníky,'),
(1568465,54,28,8,10,'A že posílali dary mezi pohany: protož tudíž je zberu i já, anobrž jižť jsou okusili něčeho pro břímě krále knížat.'),
(1568466,54,28,8,11,'Nebo vzdělal Efraim mnoho oltářů k hřešení, máť oltáře k hřešení.'),
(1568467,54,28,8,12,'Vypsal jsem jemu znamenité věci v zákoně svém, ale neváží sobě rovně jako cizí věci.'),
(1568468,54,28,8,13,'Z obětí darů mých obětují maso a jedí, Hospodin neoblibuje jich. Jižť zpomene na nepravost jejich, a vyhledávati bude hříchy jejich, že se oni do Egypta navracují,'),
(1568469,54,28,8,14,'A že se zapomenul Izrael na Učinitele svého, a nastavěl chrámů, a Juda vzdělal mnoho měst hrazených. Protož pošli oheň na města jeho, a zžíře paláce jeho.'),
(1568470,54,28,9,1,'Neraduj se, Izraeli, s plésáním jako jiní národové, že smilníš, odcházeje od Boha svého, a miluješ mzdu po všech obilnicích.'),
(1568471,54,28,9,2,'Obilnice ani pres nebude jich pásti, a mest pochybí jim.'),
(1568472,54,28,9,3,'Aniž budou bydliti v zemi Hospodinově, ale navrátí se Efraim do Egypta, a v Assyrii věci nečisté jísti budou.'),
(1568473,54,28,9,4,'Nebudou obětovati Hospodinu vína, aniž příjemné jemu bude. Oběti jejich budou jako chléb kvílících, z něhož kdož by koli jedli, poškvrnili by se, protože chléb jejich pro mrtvé jejich nemá přicházeti do domu Hospodinova.'),
(1568474,54,28,9,5,'Co pak činiti budete v den slavnosti, a v den svátku Hospodinova?'),
(1568475,54,28,9,6,'Nebo aj, zahynou skrze poplénění, Egypt zbéře je, a pohřbí je Memfis; nejrozkošnějšími schranami stříbra jejich kopřiva dědičně vládnouti bude, a bodláčí v domích jejich.'),
(1568476,54,28,9,7,'Přijdou dnové navštívení, přijdou dnové odplacení, poznají Izraelští, že ten prorok jest blázen šílený a člověk ničemný, pro množství nepravosti tvé a velikou nenávist tvou.'),
(1568477,54,28,9,8,'Prorok, kterýž stráž drží nad Efraimem spolu s Bohem mým, jest osídlem čihařským na všech cestách svých, nenávist jest v domě Boha jeho.'),
(1568478,54,28,9,9,'Hlubokoť jsou zabředli a porušili se, tak jako za dnů Gabaa; zpomeneť na nepravost jejich, a vyhledávati bude hříchy jejich.'),
(1568479,54,28,9,10,'Jako hrozny na poušti nalezl jsem byl Izraele, jako ranní fíky v prvotinách jejich popatřil jsem na otce vaše; oni odešli za Belfegor, a oddali se té ohavnosti, protož budouť ohavní, tak jakž se jim líbilo.'),
(1568480,54,28,9,11,'Efraim jako pták zaletí, i sláva jejich od narození a od života, nýbrž od početí.'),
(1568481,54,28,9,12,'A byť pak i odchovali syny své, však je zbavím věku zmužilého; nýbrž i jim běda, když já se od nich odvrátím.'),
(1568482,54,28,9,13,'Efraim, jakýž vidím Týr, vštípen jest v obydlí, a však Efraim vyvede k mordéři syny své.'),
(1568483,54,28,9,14,'Dej jim, Hospodine; co bys dal? Dej jim život neplodný a prsy vyschlé.'),
(1568484,54,28,9,15,'Vrch zlosti jejich jest v Galgala, protož i tam jich nenávidím. Pro zlost skutků jejich vyženu je z domu svého, aniž jich více budu milovati; všecka knížata jejich jsou zpurná.'),
(1568485,54,28,9,16,'Bit bude Efraim, kořen jejich uschne, ovoce nepřinesou, a byť pak zplodili, tedy zmořím nejmilejší života jejich.'),
(1568486,54,28,9,17,'Pohrdne jimi Bůh můj, nebo nechtí ho poslouchati, i budou tuláci mezi pohany.'),
(1568487,54,28,10,1,'Izrael jest vinný kmen prázdný, ovoce skládá sobě. Čím více mívá ovoce svého, tím více rozmnožuje oltáře, a čím lepší jest země jeho, tím více vzdělává obrazy.'),
(1568488,54,28,10,2,'Klade díly srdce jejich, pročež vinni jsou. Onť poboří oltáře jejich, popléní obrazy jejich,'),
(1568489,54,28,10,3,'Poněvadž i říkají: Nemáme žádného krále, nýbrž aniž se bojíme Hospodina, a král co by nám učinil?'),
(1568490,54,28,10,4,'Mluví slova, klnouce se lživě, když činí smlouvu, a soud podobný jedu roste na záhonech polí mých.'),
(1568491,54,28,10,5,'Z příčiny jalovic Betavenských děsiti se budou obyvatelé Samařští, když kvíliti bude nad nimi lid jejich i kněží jejich, (kteříž příčinou jejich nyní pléší), proto že sláva jejich zastěhuje se od nich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568492,54,28,10,6,'Ano i sám lid do Assyrie zaveden bude v dar králi, kterýž obhájce býti měl; Efraim hanbu ponese, a Izrael styděti se bude za své předsevzetí.'),
(1568493,54,28,10,7,'Vyhlazen bude král Samařský jako pěna na svrchku vody.'),
(1568494,54,28,10,8,'Vypléněny budou také výsosti Avenu, hřích Izraelských, trní a hloží zroste na oltářích jejich. I dějí horám: Přikrejte nás, a pahrbkům: Padněte na nás.'),
(1568495,54,28,10,9,'Ode dnů Gabaa hřešil jsi, Izraeli. Tamť jsou ostáli, nepostihla jich v Gabaa válka proti nešlechetným.'),
(1568496,54,28,10,10,'A protož podlé líbosti své svíži je; nebo sberou se na ně národové k svázání jich, pro dvojí nepravost jejich.'),
(1568497,54,28,10,11,'Nebo Efraim jest jalovička, kteráž byla vyučována; mlatbu miluje, ačkoli jsem já nastupoval na tučný krk její, abych k jízdě užíval Efraima, Juda aby oral, a Jákob vláčil. A říkal jsem:'),
(1568498,54,28,10,12,'Rozsívejte sobě k spravedlnosti, žněte k milosrdenství, ořte sobě ouhor, poněvadž čas jest k hledání Hospodina, ažby přišel a dštil vám spravedlností.'),
(1568499,54,28,10,13,'Ale orali jste bezbožnost, žali jste nepravost, jedli jste ovoce lži; nebo doufáš v cestu svou a ve množství reků svých.'),
(1568500,54,28,10,14,'Protož povstane rozbroj mezi lidem tvým, i každá pevnost tvá zpuštěna bude, tak jako zpustil Salman Bet Arbel v den boje; matky s syny rozrážíny budou.'),
(1568501,54,28,10,15,'Aj, toť vám způsobí Bethel pro přílišnou nešlechetnost vaši; na svitání docela vyhlazen bude král Izraelský.'),
(1568502,54,28,11,1,'Když dítětem byl Izrael, miloval jsem jej, a z Egypta povolal jsem syna svého.'),
(1568503,54,28,11,2,'Volali jich, oni tím více ucházeli před nimi, Bálům obětovali, a rytinám kadili,'),
(1568504,54,28,11,3,'Ješto jsem já na nohy stavěl Efraima, on pak bral je na lokty své; aniž znáti chtěli, že jsem já je uzdravoval.'),
(1568505,54,28,11,4,'Potahoval jsem jich provázky lidskými, provazy milování, a činil jsem jim tak jako ti, kteříž pozdvihují jha na čelistech hovádka, podávaje potravy jemu.'),
(1568506,54,28,11,5,'Nenavrátíť se do země Egyptské, ale Assur bude králem jeho, proto že se nechtěli obrátiti.'),
(1568507,54,28,11,6,'Nadto bude trvati meč v městech jeho, a zkazí závory jeho, a sžíře je pro rady jejich.'),
(1568508,54,28,11,7,'Nebo lid můj ustrnul na odvrácení se ode mne, a ač ho k Nejvyššímu volají, však žádný ho neoslavuje.'),
(1568509,54,28,11,8,'Jakž bych tě vydal, ó Efraime? Jakž bych tě vydal, ó Izraeli? Kterak bych tě položil jako Adamu, podvrátil jako Seboim? Zkormouceno jest ve mně srdce mé, ano i střeva slitování mých pohnula se.'),
(1568510,54,28,11,9,'Nevykonámť prchlivosti hněvu svého, nezkazím více Efraima; nebo jsem já Bůh silný, a ne člověk, u prostřed tebe svatý, aniž přitáhnu na město.'),
(1568511,54,28,11,10,'I půjdou za Hospodinem řvoucím jako lev; on zajisté řváti bude, tak že s strachem přiběhnou synové od moře.'),
(1568512,54,28,11,11,'S strachem poběhnou jako ptactvo z Egypta, a jako holubice z země Assyrské, i osadím je v domích jejich, dí Hospodin.'),
(1568513,54,28,11,12,'Obklíčili mne Efraimští lží, a dům Izraelský lstí, když ještě Juda panoval s Bohem silným, a s svatými věrný byl.'),
(1568514,54,28,12,1,'Efraim se větrem pase, a vítr východní honí, každého dne lež a zhoubu množí; nebo smlouvu s Assurem činí, a masti do Egypta donášejí se.'),
(1568515,54,28,12,2,'I s Judou má soud Hospodin; pročež navštívě Jákoba podlé cest jeho, podlé snažností jeho odplatí jemu.'),
(1568516,54,28,12,3,'V životě za patu držel bratra svého, a silou svou knížetsky se potýkal s Bohem.'),
(1568517,54,28,12,4,'Knížetsky, pravím, potýkal se s andělem, a přemohl; plakal a pokorně ho prosil; v Bethel jej nalezl, a tam s námi mluvil.'),
(1568518,54,28,12,5,'Toť jest Hospodin Bůh zástupů, pamětné jeho jest Hospodin.'),
(1568519,54,28,12,6,'Protož ty k Bohu svému se obrať, milosrdenství a soudu ostříhej, a očekávej na Boha svého ustavičně.'),
(1568520,54,28,12,7,'Kramářem jest, v jehož ruce jsou vážky falešné, rád utiskuje,'),
(1568521,54,28,12,8,'A říká Efraim: Však jsem zbohatl, dobyl jsem sobě zboží; ve všech mých pracech nenajdou mi nepravosti, jenž by hříchem byla.'),
(1568522,54,28,12,9,'Já pak Hospodin jsa Bohem tvým od vyjití z země Egyptské, ještě-liž bych tě seděti nechal v stáncích jako ve dnech svátečních?'),
(1568523,54,28,12,10,'A mluvě skrze proroky, já abych vidění mnoho ukazoval, a skrze proroky podobenství předkládal?'),
(1568524,54,28,12,11,'Zdali toliko v Gálád byla nepravost a marnost? I v Galgala voly obětují, přes to i oltářů jejich jest jako kopců na záhonech polí mých.'),
(1568525,54,28,12,12,'Tamto utekl byl Jákob z krajiny Syrské, kdež sloužil Izrael pro ženu, a pro ženu byl pastýřem;'),
(1568526,54,28,12,13,'Sem pak skrze proroka přivedl Hospodin Izraele z Egypta, též skrze proroka ostříhán jest.'),
(1568527,54,28,12,14,'Vzbudilť Efraim hněv přehořký, a protož krev jeho na něj se vztáhne, a potupu svou vrátí jemu Pán jeho.'),
(1568528,54,28,13,1,'Když mluvíval Efraim, býval strach; vznešený byl v Izraeli, ale prohřešiv při Bálovi, tožť umřel.'),
(1568529,54,28,13,2,'A i nyní ještě předce hřeší. Nebo dělají sobě a slévají z stříbra svého podlé rozumu svého strašidla, ješto všecko to není než dílo řemeslníků, o čemž říkají: Lidé, kteříž obětují, telata ať líbají.'),
(1568530,54,28,13,3,'Protož budou jako oblak ranní a jako rosa jitřní, kteráž odchází, jako plevy vichřicí zachvácené z humna, a jako dým z komínu,'),
(1568531,54,28,13,4,'Ješto já jsem Hospodin Bůh tvůj od vyjití z země Egyptské, a Boha kromě mne nepoznal jsi, aniž jest jiný vysvoboditel kromě mne.'),
(1568532,54,28,13,5,'Jáť jsem tě poznal na poušti v zemi velmi vyprahlé.'),
(1568533,54,28,13,6,'Dobré pastvy měvše, nasyceni jsou, ale když se nasytili, pozdvihlo se srdce jejich, protož zapomenuli na mne.'),
(1568534,54,28,13,7,'Pročež budu jim jako lítý lev, jako pardus vedlé cesty číhati budu.'),
(1568535,54,28,13,8,'Potkám se s nimi jako nedvěd osiřelý, a roztrhám všecko srdce jejich, a sežeru je tam jako lev, jako zvěř divoká roztrhující je.'),
(1568536,54,28,13,9,'Z tebeť jest zhouba tvá, ó Izraeli, ješto ve mně všecka pomoc tvá.'),
(1568537,54,28,13,10,'Kdež jest král tvůj? Kdež jest? Nechť tě zachová ve všech městech tvých. Aneb soudcové tvoji, o nichž jsi řekl: Dej mi krále a knížata?'),
(1568538,54,28,13,11,'Dal jsem tobě krále v hněvě svém, a odjal jsem v prchlivosti své.'),
(1568539,54,28,13,12,'Svázánať jest nepravost Efraimova, schován jest hřích jeho.'),
(1568540,54,28,13,13,'Bolesti rodičky přijdou na něj; jest syn nemoudrý, sic jinak nezůstával by tak dlouho v životě matky.'),
(1568541,54,28,13,14,'Z ruky hrobu vyplatím je, od smrti vykoupím je; budu zhoubcím tvým, ó smrti, budu zkažením tvým, ó hrobe, želení skryto bude od očí mých.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568542,54,28,13,15,'Nebo on mezi bratřími ovoce ponese, ač prv přijde vítr východní, vítr Hospodinův od pouště vstupující, a vysuší studnice jeho, osuší i vrchoviště jeho; onenno rozchvátá poklad všech nejdražších klénotů.'),
(1568543,54,28,13,16,'Zpuštěna bude Samaří, proto že se protivila Bohu svému; od meče padnou, dítky jejich zrozrážíny budou, a těhotné ženy jejich zroztínány.'),
(1568544,54,28,14,1,'Obratiž se, ó Izraeli, cele k Hospodinu Bohu svému, nebo jsi padl příčinou nepravosti své.'),
(1568545,54,28,14,2,'Vezměte s sebou slova, a obraťte se k Hospodinu, a rcete jemu: Sejmi všelikou nepravost, a dej to, což dobrého jest, a budemeť se odplaceti volky rtů našich.'),
(1568546,54,28,14,3,'Assurť nemůže zachovati nás, na koních nepojedeme, aniž díme více dílu rukou našich: Bůh náš; nebo v tobě smilování nalézá sirotek.'),
(1568547,54,28,14,4,'Uzdravím odvrácení jejich, budu je milovati dobrovolně; nebo odvrácen bude hněv můj od nich.'),
(1568548,54,28,14,5,'Budu jako rosa Izraelovi, zkvetne jako lilium, a hluboce vpustí kořeny své jako Libán.'),
(1568549,54,28,14,6,'Rozloží se ratoléstky jeho, a bude jako oliva okrasa jeho, a vůně jeho jako Libánská.'),
(1568550,54,28,14,7,'Ti, kteříž by seděli pod stínem jeho, navrátí se, oživou jako obilé, a pučiti se budou jako kmen vinný, jehož památka bude jako vína Libánského.'),
(1568551,54,28,14,8,'Efraime, což jest mi již do modl? Já vyslýchati, a patřiti budu na tě; já jsem jako jedle zelenající se, ze mneť ovoce tvé jest.'),
(1568552,54,28,14,9,'Kdo jest moudrý, porozuměj těmto věcem, a rozumný poznej je; nebo přímé jsou cesty Hospodinovy, a spravedliví choditi budou po nich, přestupníci pak na nich padnou.'),
(1568553,54,29,1,1,'Slovo Hospodinovo, kteréž se stalo k Joelovi synu Petuelovu:'),
(1568554,54,29,1,2,'Slyšte to starší, a pozorujte všickni obyvatelé této země, stalo-li se to za dnů vašich, aneb za dnů otců vašich?'),
(1568555,54,29,1,3,'Vypravujte o tom synům svým, a synové vaši synům svým, synové pak jejich rodině potomní.'),
(1568556,54,29,1,4,'Co pozůstalo po housenkách, snědly kobylky, a co pozůstalo po kobylkách, snědli brouci, co pak pozůstalo po broucích, dojedli chroustové.'),
(1568557,54,29,1,5,'Prociťte opilci, a plačte a kvělte všickni, kteříž píjíte víno, proto že odtržen jest mest od úst vašich.'),
(1568558,54,29,1,6,'Nebo přitáhl do země mé národ silný a nesčíslný, jehož zubové zubové lva, a střenovní zubové jeho lvoví.'),
(1568559,54,29,1,7,'Přivedl vinné kmeny mé v pustinu, a fíkoví mé na zkázu; docela obnažil je a zporážel, zbělely ratolesti jejich.'),
(1568560,54,29,1,8,'Kvěl jako mladice přepásaná žíní pro muže mladosti své.'),
(1568561,54,29,1,9,'Odjata jest suchá i mokrá obět z domu Hospodinova, kvílí kněží, služebníci Hospodinovi.'),
(1568562,54,29,1,10,'Zpustlo pole, kvílí země, proto že pohubeno obilé, vyschl mest, olej zhynul.'),
(1568563,54,29,1,11,'Stydí se oráči, kvílí vinaři z příčiny pšenice a ječmene; nebo zahynula žeň polní.'),
(1568564,54,29,1,12,'Vinný kmen usechl, a fík usvadl, strom zrnatých jablek, též i palma i jabloň, všecko dříví polní poschlo, a že odňato potěšení od synů lidských.'),
(1568565,54,29,1,13,'Přepašte se a kvělte, ó kněží, úpějte přisluhující oltáři, vejděte a léhejte i v noci v žíních, služebníci Boha mého. Nebo nevnáší se do domu Boha vašeho suché ani mokré oběti.'),
(1568566,54,29,1,14,'Uložte půst, svolejte shromáždění, shromažďte starší i všecky obyvatele země do domu Hospodina Boha vašeho, a volejte k Hospodinu:'),
(1568567,54,29,1,15,'Ach, nastojte na tento den; nebo blízký jest den Hospodinův, a jako poplénění od Všemohoucího přichází.'),
(1568568,54,29,1,16,'Ano před očima našima pokrm odjat jest, z domu Boha našeho veselé a plésání.'),
(1568569,54,29,1,17,'Vyhynulo símě pod hrudami svými, zpustly stodoly, zbořeny jsou obilnice; nebo vyschlo obilé.'),
(1568570,54,29,1,18,'Aj, jak vzdychá dobytek, svírají se stáda skotů, proto že nemají žádné pastvy, ano i stáda bravů hynou.'),
(1568571,54,29,1,19,'K toběť, ó Hospodine, volám; nebo oheň sežral pastviska pouště; a plamen popálil všecka dříví polní.'),
(1568572,54,29,1,20,'Také i zvěř polní všecka lká k tobě, proto že vyschli potokové vod, a oheň sežral pastviska na poušti.'),
(1568573,54,29,2,1,'Trubte trubou na Sionu, a křičte na hoře svaté mé, nechť se třesou všickni obyvatelé této země, nebo přichází den Hospodinův, nebo blízký jest,'),
(1568574,54,29,2,2,'Den temnosti a mračna, den oblaku a mrákoty, jako záře jitřní rozprostřená po horách: Lid mnohý a silný, jemuž rovného nebylo od věků, aniž po něm kdy bude až do let národů i pronárodů.'),
(1568575,54,29,2,3,'Před tváří jeho oheň zžírati bude, a za ním plamen plápolati; před ním země tato jako zahrada Eden, ale po něm bude poušť přehrozná, a aniž bude, což by ušlo před ním.'),
(1568576,54,29,2,4,'Způsob jeho bude jako způsob koní, a jako jízdní, tak poběhnou.'),
(1568577,54,29,2,5,'Jako s hřmotem vozů po vrších hor skákati budou, jako hluk plamene ohně zžírajícího strniště, jako lid silný zšikovaný k bitvě.'),
(1568578,54,29,2,6,'Tváři jeho děsiti se budou lidé, všecky tváře zčernají jako hrnec.'),
(1568579,54,29,2,7,'Jako rekové poběhnou, jako muži váleční vstoupí na zed, a jeden každý cestou svou půjde, aniž se uchýlí z stezek svých.'),
(1568580,54,29,2,8,'Jeden druhého nebude tlačiti, každý silnicí svou půjde, a byť i na meč upadli, nebudou raněni.'),
(1568581,54,29,2,9,'Po městě těkati budou, po zdech běhati, na domy vstupovati, a okny polezou jako zloděj.'),
(1568582,54,29,2,10,'Před tváří jeho třásti se bude země, pohnou se nebesa, slunce i měsíc se zatmí, a hvězdy potratí blesk svůj.'),
(1568583,54,29,2,11,'Hospodin pak sám vydá hlas svůj před vojskem svým, proto že velmi veliký bude tábor jeho, proto že silný ten, kdož vykoná slovo jeho. (Nebo veliký bude den Hospodinův a hrozný náramně), i kdož jej bude moci snésti?'),
(1568584,54,29,2,12,'A protož ještě nyní dí Hospodin: Obraťte se ke mně samému celým srdcem svým, a to s postem a s pláčem i s kvílením.'),
(1568585,54,29,2,13,'A roztrhněte srdce vaše, a ne roucha vaše, a navraťte se k Hospodinu Bohu vašemu; neboť jest on milostivý a lítostivý, dlouhočekající a hojný v milosrdenství, a kterýž lituje zlého.'),
(1568586,54,29,2,14,'Kdo ví, neobrátí-li se a nebude-li želeti, a nezůstaví-li po něm požehnání, oběti suché a mokré Hospodinu Bohu vašemu.'),
(1568587,54,29,2,15,'Trubte trubou na Sionu, uložte půst, svolejte shromáždění.'),
(1568588,54,29,2,16,'Shromažďte lid, posvěťte shromáždění, shromažďte starce, shromažďte maličké i ty, jenž prsí požívají; nechť vyjde ženich z pokojíka svého a nevěsta z schrany své.'),
(1568589,54,29,2,17,'Kněží, služebníci Hospodinovi, ať plačí mezi síňcí a oltářem, a řeknou: Odpusť, ó Hospodine, lidu svému, a nevydávej dědictví svého v pohanění, tak aby nad nimi panovati měli pohané. Proč mají říkati mezi národy: Kde jest Bůh jejich?'),
(1568590,54,29,2,18,'I bude horlivou milostí zažžen Hospodin k zemi své, a slituje se nad lidem svým.'),
(1568591,54,29,2,19,'A ohlásí se Hospodin, a řekne lidu svému: Aj, já pošli vám obilé, mest a olej, i budete jím nasyceni, aniž vás vydám více v pohanění mezi pohany.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568592,54,29,2,20,'Nebo půlnoční vojsko vzdálím od vás, a zaženu je do země vyprahlé a pusté, přední houf jeho k moři východnímu, konec pak jeho k moři nejdalšímu; i vzejde z něho smrad a puch, jakžkoli sobě mocně počíná.'),
(1568593,54,29,2,21,'Neboj se země, plésej a vesel se; neboť mocně dělati bude Hospodin dílo své.'),
(1568594,54,29,2,22,'Nebojtež se zvířátka polí mých; neboť se zotaví pastviska na poušti, a stromoví přinese ovoce své, fík i vinný kmen vydadí moc svou.'),
(1568595,54,29,2,23,'I vy, synové Sionští, plésejte a veselte se v Hospodinu Bohu vašem; nebo vám dá déšť příhodný, a sešle vám déšť hojný, podzimní i jarní, v čas.'),
(1568596,54,29,2,24,'I budou naplněny stodoly obilím, a oplývati budou presové mstem a olejem.'),
(1568597,54,29,2,25,'A tak nahradím vám léta, kteráž sežraly kobylky, brouci, chroustové a housenky, vojsko mé veliké, kteréž jsem posílal na vás.'),
(1568598,54,29,2,26,'Budete zajisté míti co jísti, a nasyceni jsouce, chváliti budete jméno Hospodina Boha svého, kterýž učinil s vámi divné věci, aniž zahanben bude lid můj na věky.'),
(1568599,54,29,2,27,'A poznáte, že já jsem u prostřed Izraele, a že já Hospodin jsem Bohem vaším, a že není žádného jiného; neboť nebude zahanben lid můj na věky.'),
(1568600,54,29,2,28,'I stane se potom, že vyleji Ducha svého na všeliké tělo, a budou prorokovati synové vaši i dcery vaše; starci vaši sny mívati budou, mládenci vaši vidění vídati budou.'),
(1568601,54,29,2,29,'Nýbrž i na služebníky a na služebnice v těch dnech vyleji Ducha svého,'),
(1568602,54,29,2,30,'A ukáži zázraky na nebi i na zemi, krev a oheň a sloupy dymové.'),
(1568603,54,29,2,31,'Slunce obrátí se v tmu a měsíc v krev, prvé než přijde den Hospodinův veliký a hrozný,'),
(1568604,54,29,2,32,'A však stane se, že kdož by koli vzýval jméno Hospodinovo, vysvobozen bude; nebo na hoře Sion a v Jeruzalémě bude vysvobození, jakož pověděl Hospodin, totiž v ostatcích, kterýchž povolá Hospodin.'),
(1568605,54,29,3,1,'Nebo aj, v těch dnech a v ten čas, když zase přivedu zajatý lid Judský a Jeruzalémský,'),
(1568606,54,29,3,2,'Shromáždím také všecky národy, a svedu je do údolí Jozafat, abych se tam soudil s nimi o lid svůj a dědictví své, Izraele, jejž rozptýlili mezi pohany a zemi mou rozdělili.'),
(1568607,54,29,3,3,'Také o lid můj metali los, a dávali mládence za nevěstku, mladice pak prodávali za víno, aby pili.'),
(1568608,54,29,3,4,'Anobrž, co vy máte proti mně, ó Tyrští a Sidonští, i všecky končiny Filistinské? Zdaliž se mi odplacujete? Jestliže mi se odplacujete, snadněť a vnáhleť i já obrátím odplatu vaši na hlavu vaši,'),
(1568609,54,29,3,5,'Kteříž stříbro mé i zlato mé béřete, a klénoty mé výborné vnášíte do chrámů svých,'),
(1568610,54,29,3,6,'A syny Judské i syny Jeruzalémské prodáváte synům Javanovým, aby je pryč zavodili od pomezí jejich.'),
(1568611,54,29,3,7,'Aj, já vzbudím je z toho místa, kamž jste je prodali, a obrátím odplatu vaši na hlavu vaši.'),
(1568612,54,29,3,8,'Prodám zajisté syny i dcery vaše v moc synů Judských, i prodadí je Sabejským, do národu dalekého; neboť jest Hospodin mluvil.'),
(1568613,54,29,3,9,'Provolejte to mezi národy, vyhlaste boj, probuďte reků, nechť přitáhnou, a dadí se najíti všickni muži váleční.'),
(1568614,54,29,3,10,'Skujte motyky své v meče, a srpy své v oštípy; ten, kterýž jest mdlý, nechť řekne: Udatný jsem.'),
(1568615,54,29,3,11,'Shromažďte se a přitáhněte všickni národové okolní, a shlukněte se; způsobiž to, ať tam sstoupí, ó Hospodine, rekové tvoji.'),
(1568616,54,29,3,12,'Probudíť se a přitáhnou národové ti do údolé Jozafat; nebo tam se posadím, abych soudil všecky ty národy okolní.'),
(1568617,54,29,3,13,'Přičiňte srp, nebo uzralo obilé; poďte, sstupte, nebo plný jest pres, oplývají kádě; mnohá zajisté jest zlost jejich.'),
(1568618,54,29,3,14,'Ale více hromad, hromad v údolí posekání; nebo blízký jest den Hospodinův, v údolí posekání.'),
(1568619,54,29,3,15,'Slunce a měsíc zatmí se, a hvězdy potratí blesk svůj.'),
(1568620,54,29,3,16,'A Hospodin řváti bude z Siona, a z Jeruzaléma vydá hlas svůj, tak že se třásti budou nebesa i země; nebo Hospodin jest útočiště lidu svého, a síla synů Izraelských.'),
(1568621,54,29,3,17,'I zvíte, že já Hospodin jsem Bohem vaším, kterýž bydlím na Sionu, hoře svatosti své, a tak Jeruzalém bude svatý, a cizí nepůjdou přes něj více.'),
(1568622,54,29,3,18,'I stane se v ten čas, že hory dštíti budou mstem, a pahrbkové oplývati mlékem, a všickni potokové Judští budou plní vody, a studnice z domu Hospodinova vyjde, kteráž zapojí údolé Setim.'),
(1568623,54,29,3,19,'Egypt na zpuštění přijde, a země Idumejská hrozně zpuštěna bude pro násilí synům Judským činěné; nebo vylévali krev nevinnou v zemi jejich.'),
(1568624,54,29,3,20,'Juda pak na věky trvati bude, a Jeruzalém od národu do pronárodu.'),
(1568625,54,29,3,21,'A očistím ty, jejichž jsem krve neočistil; nebo Hospodin přebývá na Sionu.'),
(1568626,54,30,1,1,'Slova Amosova, (kterýž byl mezi pastýři) z Tekoa, kteráž viděl o Izraelovi za dnů Uziáše krále Judského, a za dnů Jeroboáma syna Joasova, krále Izraelského, dvě létě před země třesením.'),
(1568627,54,30,1,2,'I řekl: Hospodin řváti bude z Siona, a z Jeruzaléma vydá hlas svůj, i budou kvíliti salášové pastýřů, a vyschnou pole nejvýbornější.'),
(1568628,54,30,1,3,'Takto praví Hospodin: Pro troji nešlechetnost Damašku, ovšem pro čtveru neodpustím jemu, proto že mlátili Galáda cepami okovanými.'),
(1568629,54,30,1,4,'Ale pošli oheň na dům Hazaelův, kterýžto zžíře paláce Benadadovy.'),
(1568630,54,30,1,5,'I polámi závoru Damašku, a vypléním obyvatele z údolí Aven, a toho, kterýž drží berlu, z domu Eden, i půjde v zajetí lid Syrský do Kir, dí Hospodin.'),
(1568631,54,30,1,6,'Takto praví Hospodin: Pro troji nešlechetnost Gázy, ovšem pro čtveru neslituji se nad ním, proto že je zajímajíce, v zajetí věčné podrobovali Idumejským.'),
(1568632,54,30,1,7,'Ale pošli oheň na zed Gázy, kterýžto zžíře paláce její,'),
(1568633,54,30,1,8,'A vypléním obyvatele z Azotu, i toho, kterýž drží berlu, z Aškalon, a obrátím ruku svou proti Akaron, i zahyne ostatek Filistinských, praví Panovník Hospodin.'),
(1568634,54,30,1,9,'Takto praví Hospodin: Pro troji nešlechetnost Týru, ovšem pro čtveru neodpustím jemu, proto že je v zajetí věčné podrobili Idumejským, a nepamatovali na smlouvu bratrskou.'),
(1568635,54,30,1,10,'Ale pošli oheň na zed Tyrskou, kterýžto zžíře paláce jeho.'),
(1568636,54,30,1,11,'Takto praví Hospodin: Pro troji nešlechetnost Edoma, ovšem pro čtveru neslituji se nad ním, proto že udusiv v sobě všecku lítostivost, stihá mečem bratra svého, a hněv jeho ustavičně rozsapává, anobrž vzteklost jeho špehuje bez přestání.'),
(1568637,54,30,1,12,'Ale pošli oheň na Teman, kterýžto zžíře paláce v Bozra.'),
(1568638,54,30,1,13,'Toto praví Hospodin: Pro troji nešlechetnost synů Ammon, ovšem pro čtveru neodpustím jemu, proto že roztínali těhotné Galádské, jen aby rozšiřovali pomezí své.'),
(1568639,54,30,1,14,'Ale zanítím oheň na zdi Rabba, kterýžto zžíře paláce její, s troubením v den boje a s bouří v den vichřice.'),
(1568640,54,30,1,15,'I půjde král jejich v zajetí, on i knížata jeho s ním, praví Hospodin.'),
(1568641,54,30,2,1,'Takto praví Hospodin: Pro troji nešlechetnost Moábovu, ovšem pro čtveru neodpustím jemu, proto že spálil kosti krále Idumejského na vápno.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568642,54,30,2,2,'Ale pošli oheň na Moába, kterýžto zžíře paláce Kariot, i umře s hlukem Moáb, s křikem a s hlasem trouby.'),
(1568643,54,30,2,3,'A vypléním soudce jeho, i všecka knížata jeho zmorduji s ním, praví Hospodin.'),
(1568644,54,30,2,4,'Takto praví Hospodin: Pro troji nešlechetnost Judovu, ovšem pro čtveru neslituji se nad ním, proto že oni pohrdají zákonem Hospodinovým, a ustanovení jeho neostříhají, a svodí se lžmi svými, jichž následovali otcové jejich.'),
(1568645,54,30,2,5,'Ale pošli oheň na Judu, kterýžto zžíře paláce Jeruzalémské.'),
(1568646,54,30,2,6,'Takto praví Hospodin: Pro troji nešlechetnost Izraelovu, ovšem pro čtveru neodpustím jemu, proto že prodávají spravedlivého za peníze, a nuzného za pár střevíců.'),
(1568647,54,30,2,7,'Kteříž dychtí, aby chudé s prstí smísili, a cestu tichých převracejí; nadto syn i otec vcházejí k jedné a též mladici, aby poškvrnili jména svatosti mé.'),
(1568648,54,30,2,8,'A na oděvu zastaveném klanějí se při každém oltáři, a víno pokutovaných pijí v domě bohů svých,'),
(1568649,54,30,2,9,'Ješto jsem já vyhladil Amorejského od tváři jejich, jehož vysokost byla jako vysokost cedrů. Ačkoli pevně stál jako dub, však jsem zkazil svrchu ovoce jeho, pospodu pak kořeny jeho.'),
(1568650,54,30,2,10,'A vás já jsem vyvedl z země Egyptské, a vyvedl jsem vás po poušti čtyřidceti let, abyste dědičně vládli zemí Amorejského.'),
(1568651,54,30,2,11,'A vzbuzoval jsem z synů vašich proroky, a z mládenců vašich Nazarejské. Zdaliž není tak, ó synové Izraelští? praví Hospodin.'),
(1568652,54,30,2,12,'Ale vy jste napájeli Nazarejské vínem, a prorokům jste zapovídali, řkouce: Neprorokujte.'),
(1568653,54,30,2,13,'Aj, já tlačiti budu zemi vaši tak, jako vůz těžký tlačí snopy.'),
(1568654,54,30,2,14,'I zahyne utíkání od rychlého, silný též neužive síly své, a udatný nevysvobodí života svého.'),
(1568655,54,30,2,15,'A ten, kterýž se chápá lučiště, neostojí, a čerstvý na nohy své neuteče, a ten, kterýž jezdí na koni, nevysvobodí života svého.'),
(1568656,54,30,2,16,'Ale i zmužilého srdce mezi nejudatnějšími nahý utíkati bude v ten den, praví Hospodin.'),
(1568657,54,30,3,1,'Slyšte slovo to, kteréž mluví Hospodin proti vám, synové Izraelští, proti vší té rodině, kterouž jsem vyvedl z země Egyptské, řka:'),
(1568658,54,30,3,2,'Toliko vás samy poznal jsem ze všeliké rodiny země, protož trestati vás budu ze všech nepravostí vašich.'),
(1568659,54,30,3,3,'Zdaliž půjdou dva spolu, leč by se snesli?'),
(1568660,54,30,3,4,'Zdaliž zařve lev v lese, když by nebylo žádné loupeže? Vydá-liž lvíček hlas svůj z peleše své, kdyby lapiti neměl?'),
(1568661,54,30,3,5,'Padne-liž ptáče do osídla na zem, když by žádné léčky nebylo? Bude-liž zdviženo osídlo z země, když by nic neuvázlo?'),
(1568662,54,30,3,6,'Zdaliž když se troubí trubou v městě, lid s strachem se nezbíhá? Zdaž když se má státi v městě co zlého, Hospodin toho známa nečiní?'),
(1568663,54,30,3,7,'Nečiníť zajisté Panovník Hospodin ničeho, leč by zjevil tajemství své služebníkům svým prorokům.'),
(1568664,54,30,3,8,'Lev řve, kdož by se nebál? Panovník Hospodin velí, kdož by neprorokoval?'),
(1568665,54,30,3,9,'Rozhlaste po palácích v Azotu, a po palácích v zemi Egyptské, a rcete: Sbeřte se na hory Samaří, a vizte znepokojení veliká u prostřed něho a nátisk trpící v něm,'),
(1568666,54,30,3,10,'A že neumějí dělati upřímě, dí Hospodin. Poklady skládají z nátisku a loupeže na palácích svých.'),
(1568667,54,30,3,11,'Protož takto praví Panovník Hospodin: Aj, nepřítel, a to na zemi tuto vůkol, a tenť odejme od tebe sílu tvou, i budou rozchvátáni palácové tvoji.'),
(1568668,54,30,3,12,'Takto praví Hospodin: Jako když vytrhne pastýř z úst lva dva hnáty aneb kus ucha, tak vytrženi budou synové Izraelští, sedící v Samaří lhostejně na postelích, a na ložcích rozkošných.'),
(1568669,54,30,3,13,'Slyšte a osvědčte v domě Jákobově, dí Panovník Hospodin, Bůh zástupů,'),
(1568670,54,30,3,14,'Že v ten den, když Izraele trestati budu pro přestoupení jeho, navštívím také oltáře v Bethel, a odťati budou rohové oltáře, tak že spadnou na zem.'),
(1568671,54,30,3,15,'A udeřím domem zimním o dům letní, i zahynou domové z kostí slonových, a konec vezmou domové velicí, praví Hospodin.'),
(1568672,54,30,4,1,'Slyšte slovo toto, ó krávy Bázanské, kteréž jste na horách Samařských, kteréž nátisk činíte chudým, a potíráte nuzné, kteréž říkáte pánům jejich: Přineste, ať pijeme.'),
(1568673,54,30,4,2,'Přisáhl Panovník Hospodin skrze svatost svou, že aj, dnové jdou na vás, v nichž vezme vás na háky, a potomky vaše na udice rybářské.'),
(1568674,54,30,4,3,'I vyjdete mezerami, každá tak, jakž stojí, a budete rozhazovati, což na palácích, dí Hospodin.'),
(1568675,54,30,4,4,'Jdětež do Bethel, a buďtež poběhlci Galgala, rozmnožujte převrácenost, a přinášejte každého jitra oběti své, třetího roku desátky své.'),
(1568676,54,30,4,5,'A pálíce obět chvály z kvašených věcí, provolejte i oběti dobrovolné, a rozhlaste, poněvadž se vám tak líbí, ó synové Izraelští, dí Panovník Hospodin.'),
(1568677,54,30,4,6,'A ačkoli já dal jsem vám čistotu zubů po všech městech vašich, totiž nedostatek chleba na všech místech vašich, a však jste se ke mně neobrátili, dí Hospodin.'),
(1568678,54,30,4,7,'Já také zadržel jsem vám déšť, když ještě tři měsícové byli do žně, a dštil jsem na jedno město, a na druhé město jsem nedštil; jeden díl deštěm svlažen byl, a ten díl, na kterýž nepršelo, uschl.'),
(1568679,54,30,4,8,'A toulali se dvě i tři města k jednomu městu, aby se napili vody, aniž se napiti mohli, a však jste se neobrátili ke mně, dí Hospodin.'),
(1568680,54,30,4,9,'Bil jsem vás suchem a rzí; hojnost, kterouž přinášely zahrady vaše a vinice vaše, i fíkoví vaše, i olivoví vaše, pojedly housenky, a však jste se neobrátili ke mně, dí Hospodin.'),
(1568681,54,30,4,10,'Poslal jsem na vás mor tak jako na Egypt, zbil jsem mečem mládence vaše, v zajetí jsem vydal koně vaše, a učinil jsem, že vstupoval smrad vojsk vašich i v chřípě vaše, a však jste se neobrátili ke mně, dí Hospodin.'),
(1568682,54,30,4,11,'Podvrátil jsem vás, jako podvrátil Bůh Sodomu a Gomoru, tak že jste byli jako hlavně vychvácená z ohně, vždy však neobrátili jste se ke mně, dí Hospodin.'),
(1568683,54,30,4,12,'A protož takť učiním, ó Izraeli, a poněvadž takť učiniti míním, připraviž se vstříc Bohu svému, ó Izraeli.'),
(1568684,54,30,4,13,'Nebo aj, on jest sformovatel hor a stvořitel větrů, a oznamuje člověku, jaké by bylo jeho myšlení; činí z záře jitřní tmu, a šlapá po vysokostech země. Hospodin Bůh zástupů jest jméno jeho.'),
(1568685,54,30,5,1,'Slyšte slovo toto, kteréž já vynáším proti vám, totiž naříkání nad domem Izraelským.'),
(1568686,54,30,5,2,'Padneť, aniž více povstane panna Izraelská; opuštěna bude v zemi své, nebude žádného, kdo by jí pozdvihl.'),
(1568687,54,30,5,3,'Nebo takto praví Panovník Hospodin: V městě, z kteréhož vycházelo tisíc, zůstane sto, v tom pak, z kteréhož vycházelo sto, zůstane deset domu Izraelskému.'),
(1568688,54,30,5,4,'Nebo takto praví Hospodin domu Izraelskému: Hledejte mne a živi buďte.'),
(1568689,54,30,5,5,'A nehledejte Bethel, aniž choďte do Galgala, a do Bersabé se nesmýkejte; nebo Galgal jistotně se přestěhuje, a Bethel přijde na nic.'),
(1568690,54,30,5,6,'Hledejte Hospodina, (a živi buďte, aby nepronikl jako oheň domu Jozefova, a nesehltil, a nebylo by žádného, kdo by uhasil Bethelské,'),
(1568691,54,30,5,7,'Kteříž proměňují v pelynek soud, a spravedlnosti na zemi zanechávají),');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568692,54,30,5,8,'Toho, kterýž učinil Kuřátka i Oriona, kterýž proměňuje stín smrti v jitro, a den v temnosti noční, kterýž přivolává vody mořské, a vylévá je na svrchek země, jehož jméno jest Hospodin,'),
(1568693,54,30,5,9,'Kterýž očerstvuje zemdleného proti silnému, tak že zemdlený do pevnosti vchází.'),
(1568694,54,30,5,10,'Nenávidí trescícího v bráně, a toho, kdož mluví věci pravé, v ohavnosti mají.'),
(1568695,54,30,5,11,'A protož, proto že loupíte chudého, a břímě obilé béřete od něho, domů z tesaného kamení nastavěli jste, ale nebudete bydliti v nich; vinic výborných naštěpovali jste, ale nebudete píti vína z nich.'),
(1568696,54,30,5,12,'Nebo já vím o mnohých nešlechetnostech vašich a velikých hříších vašich, že trápíte spravedlivého, berouce poctu, a nuzných při v bráně převracíte.'),
(1568697,54,30,5,13,'Protož rozumný v ten čas mlčeti musí, nebo čas ten zlý jest.'),
(1568698,54,30,5,14,'Hledejte dobrého a ne zlého, abyste živi byli, a budeť tak Hospodin Bůh zástupů s vámi, jakž pravíte.'),
(1568699,54,30,5,15,'Mějte v nenávisti zlé, a milujte dobré, a ustanovte v bráně soud; snad Hospodin Bůh zástupů milost učiní ostatkům Jozefovým.'),
(1568700,54,30,5,16,'Protož takto praví Panovník Hospodin, Bůh zástupů: Po všech ulicích bude kvílení, a na všecky strany zkřiknou: Ouvech, ouvech, a povolají oráče k pláči a kvílení s těmi, kteříž umějí naříkati.'),
(1568701,54,30,5,17,'Nýbrž i po všech vinicích bude kvílení, když projdu prostředkem tebe, dí Hospodin.'),
(1568702,54,30,5,18,'Běda těm, kteříž žádají dne Hospodinova. K čemuž jest vám ten den Hospodinův, poněvadž jest tmy a ne světla?'),
(1568703,54,30,5,19,'Jako když by někdo utíkal před lvem, potkal by se s ním nedvěd; aneb když by všel do domu, a zpolehna rukou svou na stěnu, ušťkl by ho had.'),
(1568704,54,30,5,20,'Zdali není tmy a ne světla den Hospodinův, v němž není blesku, ale mrákota?'),
(1568705,54,30,5,21,'Nenávidím, zavrhl jsem svátky vaše, aniž sobě chutnám slavností vašich.'),
(1568706,54,30,5,22,'Nebo budete-li mi obětovati zápaly a suché oběti vaše, neoblíbím jich, a na pokojné oběti krmného dobytka vašeho nepopatřím.'),
(1568707,54,30,5,23,'Odejmi ode mne hluk písní svých, ani hudby louten vašich nechci poslouchati.'),
(1568708,54,30,5,24,'Ale povalí se jako voda soud, a spravedlnost jako potok silný.'),
(1568709,54,30,5,25,'Zdali jste mně oběti a dary obětovali na poušti za čtyřidceti let, dome Izraelský?'),
(1568710,54,30,5,26,'Nýbrž nosili jste stánek Melecha vašeho a Kijuna, obrazy vaše, hvězdu boha vašeho, kteréžto věci sami jste sobě zdělali.'),
(1568711,54,30,5,27,'Protož přestěhuji vás dále než Damašské, praví Hospodin, jehož jméno jest Bůh zástupů.'),
(1568712,54,30,6,1,'Běda pokoj majícím na Sionu, a doufajícím v horu Samařskou, kteréžto hory jsou slovoutné mimo jiné u těch národů, k nimž se scházejí dům Izraelský.'),
(1568713,54,30,6,2,'Projděte až do Chalne, a odtud jděte do Emat veliké, a sstupte do Gát Filistinských, a shlédněte, jsou-li která království lepší nežli tato? Jest-li větší jejich kraj nežli kraj váš?'),
(1568714,54,30,6,3,'Kteříž smyslíte, že jest daleko den bídy, a přistavujete stolici nátisku.'),
(1568715,54,30,6,4,'Kteříž léhají na ložcích slonových, a rozkošně sobě počínají na postelích svých, kteříž jídají berany z stáda a telata nejtučnější,'),
(1568716,54,30,6,5,'Přizpěvujíce k loutně jako David, vymýšlejíce sobě nástroje muzické.'),
(1568717,54,30,6,6,'Kteříž pijí z bání vinných, a drahými mastmi se maží, aniž jsou čitelni bolesti pro potření Jozefovo.'),
(1568718,54,30,6,7,'Pročež jižť půjdou v zajetí v prvním houfu stěhujících se, a tak nastane žalost těm, kteříž sobě rozkošně počínají.'),
(1568719,54,30,6,8,'Přisáhl Panovník Hospodin skrze sebe samého, dí Hospodin Bůh zástupů: V ohavnosti mám pýchu Jákobovu, i paláců jeho nenávidím, pročež vydám město i vše, což v něm jest.'),
(1568720,54,30,6,9,'I stane se, že pozůstane-li deset osob v domě jednom, i ti zemrou.'),
(1568721,54,30,6,10,'A vezme někoho strýc jeho, aneb ten, kterýž mu strojí pohřeb, aby vynesl kosti z domu, a dí tomu, kdož jest v pokoji domu: Jest-liž ještě s tebou kdo? I dí: Není žádného. I řekne: Mlč, proto že nepřipomínali jména Hospodinova.'),
(1568722,54,30,6,11,'Nebo aj, Hospodin přikáže, a bíti bude na dům veliký přívaly, a na dům menší rozsedlinami.'),
(1568723,54,30,6,12,'Zdaliž koni běžeti mohou po skále? Zdaliž ji kdo orati může voly? Nebo jste proměnili soud v jed, a ovoce spravedlnosti v pelynek,'),
(1568724,54,30,6,13,'Vy, kteříž se veselíte, ano není z čeho, říkajíce: Zdaliž jsme svou silou nevzali sobě rohů?'),
(1568725,54,30,6,14,'Ale aj, já vzbudím proti vám, ó dome Izraelský, praví Hospodin Bůh zástupů, národ, kterýž vás ssouží, odtud, kudy se jde do Emat, až do potoka roviny.'),
(1568726,54,30,7,1,'Toto mi ukázal Panovník Hospodin, že aj, formoval kobylky, když nejprvé počala růsti otava, když aj, otava byla po královském posečení.'),
(1568727,54,30,7,2,'I stalo se, když snědly byliny zemské, že jsem řekl: Panovníče Hospodine, odpustiž, prosím. Kdož zůstane Jákobovi? Neboť ho maličko jest.'),
(1568728,54,30,7,3,'I želel Hospodin toho. Nestaneť se, řekl Hospodin.'),
(1568729,54,30,7,4,'Tedy ukázal mi Panovník Hospodin, a aj, Panovník Hospodin volal, že při svou povede ohněm. A spáliv propast velikou, spálil i díl.'),
(1568730,54,30,7,5,'Já pak řekl jsem: Panovníče Hospodine, přestaniž, prosím. Kdož zůstane Jákobovi? Neboť ho maličko jest.'),
(1568731,54,30,7,6,'I želel Hospodin toho. A ani toho se nestane, řekl Panovník Hospodin.'),
(1568732,54,30,7,7,'Potom ukázal mi, a aj, Pán stál na zdi podlé pravidla vzdělané, v jehož ruce bylo pravidlo.'),
(1568733,54,30,7,8,'I řekl mi Hospodin: Co vidíš, Amose? Řekl jsem: Pravidlo. I řekl Pán: Aj, já položím pravidlo u prostřed lidu svého Izraelského, nebuduť již více promíjeti jemu.'),
(1568734,54,30,7,9,'Nebo zpuštěny budou výsosti Izákovy, a svatyně Izraelovy zpustnou, tehdáž, když povstanu proti domu Jeroboámovu s mečem.'),
(1568735,54,30,7,10,'Tedy poslal Amaziáš kněz Bethelský k Jeroboámovi králi Izraelskému, řka: Spuntoval se proti tobě Amos u prostřed domu Izraelského, ta země nemohla by snésti všech slov jeho.'),
(1568736,54,30,7,11,'Nebo takto praví Amos: Od meče umře Jeroboám, a Izrael jistotně přestěhován bude z země své.'),
(1568737,54,30,7,12,'Potom řekl Amaziáš Amosovi: Ó vidoucí, ujdi, radímť, utec do země Judské, a jez tam chléb, a tam prorokuj.'),
(1568738,54,30,7,13,'Ale v Bethel již více neprorokuj, nebo ono svatyně králova i dům královský jest.'),
(1568739,54,30,7,14,'Tedy odpovídaje Amos, řekl Amaziášovi: Nebylť jsem já prorokem, ano ani synem prorockým, ale byl jsem skotákem, a česával jsem plané fíky.'),
(1568740,54,30,7,15,'Ale Hospodin mne vzal, když jsem chodil za stádem, a řekl mi Hospodin: Jdi, prorokuj lidu mému Izraelskému.'),
(1568741,54,30,7,16,'Nyní tedy slyšiž slovo Hospodinovo. Ty pravíš: Neprorokuj v Izraeli, a nekaž v domě Izákově.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568742,54,30,7,17,'Protož takto praví Hospodin: Žena tvá cizoložiti bude v městě, synové pak tvoji i dcery tvé od meče padnou; a země tvá provazcem dělena bude, a ty v zemi nečisté umřeš, Izrael pak jistotně přestěhován bude z země své.'),
(1568743,54,30,8,1,'Také mi ukázal Panovník Hospodin, a aj, byl koš ovoce letního.'),
(1568744,54,30,8,2,'A řekl: Co ty vidíš, Amose? I řekl jsem: Koš ovoce letního. Opět mi řekl Hospodin: Přišeltě konec lidu mému Izraelskému, nebuduť již více promíjeti jemu.'),
(1568745,54,30,8,3,'Pročež kvíliti budou zpěvové chrámoví v ten den, praví Panovník Hospodin. Množství mrtvých, mlče, namece na všelijaké místo.'),
(1568746,54,30,8,4,'Slyštež to vy, kteříž sehlcujete chudého, abyste vyhladili nuzné z země,'),
(1568747,54,30,8,5,'Říkajíce: Skoro-liž pomine novměsíce, abychom prodávali obilé, a sobota, abychom otevřeli obilnice, abychom ujímali efi, a přivětšovali váhy, a faleš provodili vážkami falešnými,'),
(1568748,54,30,8,6,'Kupujíce za peníze nuzné, a chudého za pár střevíců, nadto abychom plevy obilné prodávali?'),
(1568749,54,30,8,7,'Přisáhl Hospodin skrze důstojnost Jákobovu: Žeť se nezapomenu na věky na všecky skutky jejich.'),
(1568750,54,30,8,8,'Nad tím-liž by se netřásla i země, a nekvílil by každý, kdož přebývá na ní? Proto-liž by neměla vystoupiti všecka jako potok, a zachvácena i zatopena býti jako potokem Egyptským?'),
(1568751,54,30,8,9,'Anobrž stane se v ten den, praví Panovník Hospodin, učiním, že slunce zajde o poledni, a uvedu tmy na zemi v jasný den.'),
(1568752,54,30,8,10,'A proměním svátky vaše v kvílení, a všecky zpěvy vaše v naříkání, a způsobím to, že bude na každých bedrách žíně, a na každé hlavě lysina, a bude v zemi této kvílení jako nad jednorozeným, a poslední věci její jako den hořkosti.'),
(1568753,54,30,8,11,'Aj, dnové jdou, dí Panovník Hospodin, že pošli hlad na zemi, ne hlad chleba, ani žízeň vody, ale slyšení slov Hospodinových,'),
(1568754,54,30,8,12,'Tak že toulati se budou od moře až k moři, a od půlnoci až na východ běhati, hledajíce slova Hospodinova, však nenajdou.'),
(1568755,54,30,8,13,'V ten čas umdlévati budou panny krásné, ano i mládenci tou žízní,'),
(1568756,54,30,8,14,'Kteříž přisahají skrze ohavnost Samařskou, a říkají: Živť jest Bůh tvůj, ó Dan, a živa jest cesta Bersabé. I padnou, a nepovstanou více.'),
(1568757,54,30,9,1,'Viděl jsem Pána, an se postavil na oltáři a řekl: Udeř v makovici, až se zatřesou ty veřeje, a rozetni je všecky od vrchu jejich, ostatek pak mečem zmorduji. Neutečeť žádný z nich, aniž kdo z nich bude, ješto by toho znikl.'),
(1568758,54,30,9,2,'Byť se pak do země zakopali, i odtud by je ruka má vzala; pakli by vstoupili do nebe, i odtud bych je strhl.'),
(1568759,54,30,9,3,'A jestliže by se schovali na vrchu Karmele, vyhledám a vezmu je odtud; pakli by se skryli před očima mýma na dně moře, přikáži hadu, aby je i odtud vyhryzl.'),
(1568760,54,30,9,4,'Pakliť by šli v zajetí před nepřátely svými, i tam přikáži meči, aby je zmordoval; obrátím zajisté oko své proti nim k zlému, a ne k dobrému.'),
(1568761,54,30,9,5,'Nebo Panovník Hospodin zástupů když se jen dotkne země, rozplývá se, a kvílí všickni přebývající na ní, a vystupuje všecka jako potok, a zatopena bývá jako potokem Egyptským,'),
(1568762,54,30,9,6,'Kterýž vzdělal na nebesích paláce své, a zástup svůj na zemi sšikoval, kterýž může zavolati vody mořské, a vyliti ji na svrchek země, jehož jméno jest Hospodin.'),
(1568763,54,30,9,7,'Zdaliž nejste podobni synům Mouřenínů přede mnou, ó synové Izraelovi? dí Hospodin. Zdaliž jsem Izraele nevyvedl z země Egyptské, tak jako Filistinské z Kaftor, a Syrské z Kir?'),
(1568764,54,30,9,8,'Aj, oči Panovníka Hospodina proti království tomuto hřešícímu, abych je vyhladil se svrchku země, a však nevyhladím docela domu Jákobova, dí Hospodin.'),
(1568765,54,30,9,9,'Nebo aj, já přikázal jsem, a budu zmítati domem Izraelským mezi všemi národy, tak jako zmítáno bývá na říčici, tak že ani kameníčko nepropadne na zem.'),
(1568766,54,30,9,10,'Mečem zbiti budou všickni hříšníci z lidu mého, kteříž říkají: Nepřiblížíť se, aniž potká nás to zlé.'),
(1568767,54,30,9,11,'V ten den zdvihnu stánek Davidův, kterýž klesá, a zahradím mezery jeho, a zbořeniny jeho opravím, a vzdělám jej jako za dnů starodávních,'),
(1568768,54,30,9,12,'Aby dědili s ostatky Idumejských a se všechněmi národy, nad kterýmiž jest vzýváno jméno mé, dí Hospodin, kterýž to učiní.'),
(1568769,54,30,9,13,'Aj, dnové jdou, dí Hospodin, že postihati bude oráč žence, a ten, kdož tlačí hrozny, rozsevače, hory pak dštíti budou mstem, a všickni pahrbkové oplývati.'),
(1568770,54,30,9,14,'Přivedu také zase zajatý lid svůj Izraelský, a vystavějí města zpuštěná, aby v nich bydlili; a budou štěpovati vinice, a píti víno jejich, nadělají i zahrad, a jísti budou ovoce jejich.'),
(1568771,54,30,9,15,'A tak je štípím v zemi jejich, že nebudou vykořeněni více z země své, kterouž jsem dal jim, praví Hospodin Bůh tvůj.'),
(1568772,54,31,1,1,'Vidění Abdiášovo. Takto praví Panovník Hospodin o zemi Idumejské: Pověst jsme slyšeli od Hospodina, a legáta k národům vyslaného: Nuže, povstaňmež k boji proti ní.'),
(1568773,54,31,1,2,'Aj, způsobím to, abys byl nejšpatnější mezi národy, a abys byl v náramném pohrdání.'),
(1568774,54,31,1,3,'Pýcha srdce tvého zklamá tě, ó ty, kterýž bydlíš v rozsedlinách skalních, v převysokém obydlí svém, říkaje v srdci svém: Kdož by mne strhl na zem?'),
(1568775,54,31,1,4,'Bys pak vysoko udělal jako orlice, nýbrž bys mezi hvězdami položil hnízdo své, i odtud strhnu tě, praví Hospodin.'),
(1568776,54,31,1,5,'Kterak jsi popléněn? Zdali zloději přišli na tebe? Zdali loupežníci noční? Zdaliž by kradli přes spotřebu svou? Kdyby ti, kteříž zbírají víno, přišli na tebe, zdaž by nepozůstavili aspoň paběrků?'),
(1568777,54,31,1,6,'Jakť jsou vystiženy věci Ezau, vyhledáni pokladové jeho!'),
(1568778,54,31,1,7,'Až ku pomezí vystrčí tě všickni, s kterýmiž smlouvu máš; podvedou tě, zmocní se tebe ti, s nimiž pokoj máš; náchlebníci tvoji udělajíť ránu zrádně, již nebude lze vyrozuměti.'),
(1568779,54,31,1,8,'Zdaliž v ten den, praví Hospodin, nevyhladím moudrých z země Idumejské, a rozumných s hory Ezau?'),
(1568780,54,31,1,9,'I budou se děsiti udatní tvoji, ó Temane, proto, že poraženi jsouce, vypléněni budou všickni s hory Ezau.'),
(1568781,54,31,1,10,'Pro nátisk bratru tvému Jákobovi činěný přikryje tě hanba, a vypléněn budeš na věčnost.'),
(1568782,54,31,1,11,'Stál jsi v ten den naproti, a když zajímali cizí vojsko jeho, a když cizozemci vcházeli do bran jeho, a o Jeruzalém metali losy, ty jsi také byl jako jeden z nich.'),
(1568783,54,31,1,12,'Nedívejž se tedy na den bratra svého, na den zajetí jeho, aniž se vesel nad syny Judskými v den zahynutí jejich, aniž pyšně mluv ústy svými v den uzkosti.'),
(1568784,54,31,1,13,'Nevcházej do brány lidu mého v den bídy jejich, aniž se dívej trápení jeho v den bídy jeho, a nechtěj sahati na statek jeho v den bídy jeho.'),
(1568785,54,31,1,14,'Aniž stůj při mezeře, abys hubil ty, kteříž z nich ucházejí, aniž vydávej nepříteli v moc těch, kteříž z nich pozůstali v den úzkosti.'),
(1568786,54,31,1,15,'Nebo blízko jest den Hospodinův proti všechněm těm národům. Jakž jsi činil, tak se stane tobě, odplata tvá navrátí se na hlavu tvou.'),
(1568787,54,31,1,16,'Nebo poněvadž vy na mé hoře svaté píti bedete, nadtoť píti budou všickni národové ustavičně. Píti, pravím, a požírati budou, až budou, jako by jich nebylo.'),
(1568788,54,31,1,17,'Na hoře pak Sion bude vysvobození, a bude svatá, a tak dědičně držeti bude dům Jákobův dědictví svá.'),
(1568789,54,31,1,18,'I bude dům Jákobův oheň, a dům Jozefův plamen, dům pak Ezau plevy, i rozpálí se na ně a sehltí je, aniž kdo pozůstane z domu Ezau; nebo Hospodin mluvil.'),
(1568790,54,31,1,19,'A tak děditi budou v krajině polední s horou Ezau, i v rovině s Filistinskými; vládnouti také budou krajinou Efraimovou i krajinou Samařskou, a Beniaminovou i Galádskou.'),
(1568791,54,31,1,20,'I zajaté vojsko toto synů Izraelských v tom, což bylo Kananejských až do Sarepty, zajatí pak Jeruzalémští v tom, což jest na konci panství, děditi budou s městy na poledne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568792,54,31,1,21,'I vstoupí vysvoboditelé na horu Sion, aby soudili horu Ezau, a tak bude Hospodinovo království.'),
(1568793,54,32,1,1,'I stalo se slovo Hospodinovo k Jonášovi synu Amaty, řkoucí:'),
(1568794,54,32,1,2,'Vstaň, jdi do Ninive města toho velikého, a volej proti němu; neboť jest vstoupila nešlechetnost jejich před oblíčej můj.'),
(1568795,54,32,1,3,'Ale Jonáš vstal, aby utekl do Tarsu od tváři Hospodinovy. A přišed do Joppe, našel lodí, ana jde do Tarsu, a zaplativ od ní, vstoupil na ni, aby se plavil s nimi do Tarsu od tváři Hospodinovy.'),
(1568796,54,32,1,4,'Ale Hospodin vzbudil vítr veliký na moři. I stala se bouře veliká na moři, až se domnívali, že se lodí ztroskoce.'),
(1568797,54,32,1,5,'A bojíce se plavci, volali jeden každý k bohu svému, a vyhazovali to, což měli na lodí, do moře, aby sobě tím polehčili. Jonáš pak byl sešel k bokům lodí, a položiv se, spal tvrdě.'),
(1568798,54,32,1,6,'Tedy přišed k němu správce lodí, řekl jemu: Což ty děláš, ospalče? Vstaň, volej k Bohu svému. Snad ten Bůh rozpomene se na nás, abychom nezahynuli.'),
(1568799,54,32,1,7,'I řekli jeden druhému: Poďte, vrzme losy, abychom zvěděli, pro koho to zlé přišlo na nás. Tedy metali losy, a padl los na Jonáše.'),
(1568800,54,32,1,8,'I řekli jemu: Pověz nám medle, pro koho toto zlé na nás? Jaký jest obchod tvůj, a odkud jdeš? Z které jsi země a z kterého národu?'),
(1568801,54,32,1,9,'I řekl jim: Hebrejský jsem, a Hospodina Boha nebes, kterýž učinil moře i zemi, já ctím.'),
(1568802,54,32,1,10,'Pročež báli se ti muži bázní velikou,a dověděvše se muži ti, že od tváři Hospodinovy utíká, (nebo jim byl oznámil), řekli jemu: Což jsi to učinil?'),
(1568803,54,32,1,11,'Řekli ještě k němu: Což máme učiniti s tebou, aby se moře spokojilo? (Nebo moře vždy více a více bouřilo se.)'),
(1568804,54,32,1,12,'Jimžto řekl: Vezměte mne, a uvrzte mne do moře, a utichne moře před vámi; nebo já vím, že příčinou mou bouře tato veliká jest proti vám.'),
(1568805,54,32,1,13,'Ale muži ti statečně táhli, chtíce k břehu přistati, však nemohli; nebo moře vždy více a více se bouřilo proti nim.'),
(1568806,54,32,1,14,'I zvolali k Hospodinu, řkouce: Prosímeť, ó Hospodine, abychom nezahynuli pro smrt člověka tohoto, aniž na nás vyhledávej krve nevinné; nebo ty, ó Hospodine, jakž chceš, tak činíš.'),
(1568807,54,32,1,15,'Tedy vzavše Jonáše, uvrhli ho do moře. I přestalo moře bouřiti se.'),
(1568808,54,32,1,16,'Pročež báli se muži ti bázní velikou Hospodina, a obětovali obět Hospodinu, a sliby činili.'),
(1568809,54,32,2,1,'Nastrojil pak byl Hospodin rybu velikou, aby požřela Jonáše. I byl Jonáš v střevách té ryby tři dni a tři noci.'),
(1568810,54,32,2,2,'I modlil se Jonáš Hospodinu Bohu svému v střevách té ryby,'),
(1568811,54,32,2,3,'A řekl: Z ssoužení svého volal jsem k Hospodinu, a ozval se mi; z břicha hrobu křičel jsem, a vyslyšel jsi hlas můj.'),
(1568812,54,32,2,4,'Nebo jsi mne uvrhl do hlubiny, do prostřed moře, a řeka obklíčila mne; všecka vlnobití tvá i rozvodnění tvá na mne se svalila.'),
(1568813,54,32,2,5,'Bylť jsem již řekl: Vyhnán jsem od očí tvých, ale ještěť pohledím na tvůj svatý chrám.'),
(1568814,54,32,2,6,'Obklíčily mne vody až k duši, propast obklíčila mne, lekno otočilo se okolo hlavy mé.'),
(1568815,54,32,2,7,'Až k spodkům hor dostal jsem se, země závorami svými zalehla mi na věčnost, ty jsi však vysvobodil od porušení život můj, ó Hospodine Bože můj.'),
(1568816,54,32,2,8,'Když se svírala ve mně duše má, na Hospodina jsem se rozpomínal, i přišla k tobě modlitba má do chrámu svatého tvého.'),
(1568817,54,32,2,9,'Kteříž ostříhají marností pouhých, dobroty Boží se zbavují.'),
(1568818,54,32,2,10,'Já pak s hlasem díkčinění obětovati budu tobě; což jsem slíbil, splním. Hojné vysvobození jest u Hospodina.'),
(1568819,54,32,2,11,'Rozkázal pak byl Hospodin rybě té, i vyvrátila Jonáše na břeh.'),
(1568820,54,32,3,1,'I stalo se slovo Hospodinovo k Jonášovi podruhé, řkoucí:'),
(1568821,54,32,3,2,'Vstaň, jdi do Ninive města toho velikého, a kaž proti němu to, což já poroučím tobě.'),
(1568822,54,32,3,3,'Tedy vstav Jonáš, šel do Ninive podlé slova Hospodinova. (Bylo pak Ninive město velmi veliké, cesty tří dnů.)'),
(1568823,54,32,3,4,'A jakž počal byl Jonáš jíti po městě cestou dne jednoho a volati, pravě: Po čtyřidcíti dnech Ninive vyvráceno bude,'),
(1568824,54,32,3,5,'Tedy uvěřili Ninivitští Bohu, a vyhlásivše půst, oblékli se v žíně, od největšího z nich až do nejmenšího z nich.'),
(1568825,54,32,3,6,'Nebo jakž došla ta řeč krále Ninivitského, vstav s trůnu svého, složil s sebe oděv svůj, a přioděv se žíní, seděl v popele.'),
(1568826,54,32,3,7,'A dal provolati a oznámiti v Ninive z usouzení královského i knížat svých, takto řka: Lidé i hovada, volové i ovce, neokoušejte ničeho, nepaste se, ani vody nepíte.'),
(1568827,54,32,3,8,'Ale přiodějte se žíněmi lidé i hovada, a volejte k Bohu horlivě, a odvrať se jeden každý od cesty své zlé, i loupeže, kteráž jest v rukou jeho.'),
(1568828,54,32,3,9,'Kdo ví, neobrátí-li se a nebude-li želeti toho Bůh; neodvrátí-li se, pravím, od prchlivosti hněvu svého, abychom nezahynuli.'),
(1568829,54,32,3,10,'I viděl Bůh skutky jejich, že se odvrátili od cesty své zlé, a lítost měl Bůh nad tím zlým, kteréž řekl učiniti jim. A neučinil.'),
(1568830,54,32,4,1,'I mrzelo to Jonáše velmi, a rozpálen byl hněv jeho.'),
(1568831,54,32,4,2,'Pročež modlil se Hospodinu a řekl: Prosím, Hospodine, zdaliž jsem toho neřekl, když jsem ještě byl v zemi své? Protož jsem pospíšil uteci do Tarsu; nebo jsem věděl, že jsi ty Bůh milostivý a lítostivý, dlouhočekající a hojný v milosrdenství, a kterýž lituješ zlého.'),
(1568832,54,32,4,3,'Nyní tedy, ó Hospodine, vezmi, prosím, duši mou ode mne; nebo lépe jest mi umříti nežli živu býti.'),
(1568833,54,32,4,4,'I řekl Hospodin: Jest-liž to dobře, že tak horlíš?'),
(1568834,54,32,4,5,'Nebo vyšel byl Jonáš z města, a seděl na východ proti městu, a udělav sobě tu boudu, seděl pod ní v stínu, ažby viděl, co se bude díti s tím městem.'),
(1568835,54,32,4,6,'Přistrojil pak byl Hospodin Bůh břečtan, kterýž vyrostl nad Jonáše, aby zastěňoval hlavu jeho, a chránil ho před horkem. I radoval se Jonáš z toho břečtanu radostí velikou.'),
(1568836,54,32,4,7,'V tom nazejtří v svitání nastrojil Bůh červa, kterýž ranil ten břečtan, tak že uschl.'),
(1568837,54,32,4,8,'I stalo se, že když vzešlo slunce, nastrojil Bůh vítr východní žhoucí, a bilo slunce na hlavu Jonášovu, tak že umdléval, a žádal sobě, aby umřel, řka: Lépeť mi jest umříti nežli živu býti.'),
(1568838,54,32,4,9,'I řekl Bůh Jonášovi: Jest-liž to dobře, že se tak hněváš pro ten břečtan? Kterýžto řekl: An dobře jest, že se hněvám až na smrt.'),
(1568839,54,32,4,10,'Jemuž řekl Hospodin: Ty lituješ toho břečtanu, o němž jsi nepracoval, aniž jsi ho k zrostu přivedl, kterýž za jednu noc zrostl, a jedné noci zahynul,'),
(1568840,54,32,4,11,'A já abych nelitoval Ninive města tak velikého, v němž jest více nežli sto a dvadceti tisíc lidí, kteříž neznají rozdílu mezi pravicí svou a levicí svou, a dobytka mnoho?'),
(1568841,54,33,1,1,'Slovo Hospodinovo, kteréž se stalo k Micheášovi Moraštickému za dnů Jotama, Achasa a Ezechiáše králů Judských, kteréž u vidění slyšel o Samaří a Jeruzalému.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568842,54,33,1,2,'Slyšte všickni lidé napořád, pozoruj země, i což na ní jest, a nechť jest Panovník Hospodin proti vám svědkem, Panovník z chrámu svatosti své.'),
(1568843,54,33,1,3,'Nebo aj, Hospodin vyjde z místa svého, a sstoupě, šlapati bude po vysokostech země.'),
(1568844,54,33,1,4,'I budou se rozplývati hory pod ním, a údolé se roztrhovati, tak jako vosk od ohně, a jako vody mající spád dolů,'),
(1568845,54,33,1,5,'A to všecko pro Jákobovo zpronevěření, a pro hříchy domu Izraelského. Kdo jest příčina zpronevěření Jákobova? Zdali ne Samaří? A kdo výsostí Judských: Zdali ne Jeruzalém?'),
(1568846,54,33,1,6,'Protož obrátím Samaří v hromadu rumu, k štípení vinic, a svalím do údolí kamení její, i základy její odkryji.'),
(1568847,54,33,1,7,'A všecky rytiny její ztlučeny budou, i všickni darové její ohněm spáleni, a všecky modly její obrátím v pustinu. Nebo ze mzdy nevěstčí toho nashromáždila, protož se zase ke mzdě nevěstčí to navrátí.'),
(1568848,54,33,1,8,'Nad čímž kvíliti a naříkati budu, chodě svlečený a nahý, vydám se v naříkání jako drakové, a v kvílení jako mladé sovy,'),
(1568849,54,33,1,9,'Proto že zneduživěla od ran svých, a že přišlo to až k Judovi, dosáhlo až k bráně lidu mého, až do Jeruzaléma.'),
(1568850,54,33,1,10,'Neoznamujtež v Gát, aniž hned plačte; v domě Ofra v prachu se válej.'),
(1568851,54,33,1,11,'Ty, kteráž bydlíš v Safir, zajdi, obnaženou majíc hanbu. Nevyjdeť ta, kteráž bydlí v Zaanan pro kvílení v Betezel, od vás maje živnost svou.'),
(1568852,54,33,1,12,'Bude, pravím, bolestiti pro dobré věci obyvatelkyně Marót, proto že sstoupí zlé od Hospodina až do brány Jeruzalémské.'),
(1568853,54,33,1,13,'Zapřáhni do vozu rychlé koně, obyvatelkyně Lachis, kteráž jsi původ hřícha dceři Sionské; nebo v tobě nalezena jsou přestoupení Izraelova.'),
(1568854,54,33,1,14,'Protož pošleš dary své s Morešet v Gát; domové Achzib zklamají krále Izraelské.'),
(1568855,54,33,1,15,'Ó obyvatelkyně Maresa, i toběť tudíž přivedu dědice; až do Adulam přijde, k slávě Izraelské.'),
(1568856,54,33,1,16,'Učiniž sobě lysinu, a ohol se pro syny rozkoší svých; rozšiř lysinu svou jako orlice, nebo stěhují se od tebe.'),
(1568857,54,33,2,1,'Běda těm, kteříž vymýšlejí nepravost a ukládají zlé na ložcích svých, a na úsvitě ráno vykonávají je, když jest v moci rukou jejich.'),
(1568858,54,33,2,2,'Požádají polí, i vydírají, takž i domů, a odjímají; a tak provozují moc nad mužem i domem jeho, nad jedním každým i dědictvím jeho.'),
(1568859,54,33,2,3,'Protož takto praví Hospodin: Aj, já myslím proti čeledi té věc zlou, odkudž nevyňmete hrdel vašich, aniž budete choditi vysokomyslně; nebo čas zlý bude.'),
(1568860,54,33,2,4,'V ten den užívati budou o vás přísloví, a naříkati budou naříkáním žalostným, řkouce: Do cela zpuštěni jsme, podíl lidu mého proměnil. Jaktě mi jej odjal, a vzav pole naše, rozdělil!'),
(1568861,54,33,2,5,'Protož nebudeš míti, kdožť by vztáhl provazec na los v shromáždění Hospodinovu.'),
(1568862,54,33,2,6,'Neprorokujte. Budou prorokovati, ale nebudou těmto prorokovati, a neponesou pohanění.'),
(1568863,54,33,2,7,'Ó kteráž sloveš domem Jákobovým, zdali do těsna vehnán býti má duch Hospodinův? To-liž by skutkové jeho byli? Zdaliž slova má nejsou dobrá tomu, kdož upřímě chodí?'),
(1568864,54,33,2,8,'Včera byl lidem mým, již jako nepřítel povstává. Majíce oděv, plášť strhujete s těch, kteříž chodí bezpečně, vyhýbajíce se bitvě.'),
(1568865,54,33,2,9,'Manželky lidu mého vyháníte z domu rozkoší jejich, od dítek jejich odjímáte slávu mou na věky.'),
(1568866,54,33,2,10,'Vstaňte a odejděte, neboť tato není sídlem pro nečistotu. Ztratí vás, a to ztracením jistým.'),
(1568867,54,33,2,11,'Jestliže za proroka se vydávaje a lež mluvě, říká: Budu tobě prorokovati o víně aneb o nápoji opojujícím, takový bývá prorokem lidu tohoto.'),
(1568868,54,33,2,12,'Jistotně zberu tě, Jákobe, docela, jistotně shromáždím ostatky Izraele, a seženu je v hromadu jako ovce v Bozra, jako stádo do prostřed ovčince jeho, i vzejde hluk od lidu.'),
(1568869,54,33,2,13,'Vstoupí ten, kterýž prolamovati bude před nimi. Prolomí, a projdou bránu, a vyjdou skrze ni; ano i král jejich půjde před nimi, a Hospodin na špici jejich.'),
(1568870,54,33,3,1,'Protož pravím: Slyštež již přední v Jákobovi, a vůdcové domu Izraelského: Zdaliž vy nemáte povědomi býti soudu?'),
(1568871,54,33,3,2,'Nenávidí dobrého a milují zlé, sdírají s lidu kůži jejich, a maso jejich s kostí jejich.'),
(1568872,54,33,3,3,'A jedí maso lidu mého, a kůži jejich s nich svláčejí, i kosti jejich rozlamují, a rozdělují jako do hrnce, a jako maso do kotlíku.'),
(1568873,54,33,3,4,'Tehdy volati budou k Hospodinu, a nevyslyší jich, ale skryje tvář svou před nimi v ten čas, tak jakž oni vykonávali zlá předsevzetí svá.'),
(1568874,54,33,3,5,'Takto praví Hospodin o těch prorocích, kteříž v blud uvodí lid můj, a hryzouce zuby svými, vyhlašují pokoj, a proti tomu, kdož by jim nic do úst nedal, válku vyzdvihují.'),
(1568875,54,33,3,6,'A protož obrátí se vám vidění v noc, a předpovídání vaše v tmu; nebo zajde slunce těm prorokům, a zatmí se jim den.'),
(1568876,54,33,3,7,'I budou se hanbiti ti vidoucí, a styděti ti věštci, a zastrou bradu svou všickni napořád, proto že nebude žádné odpovědi Boží.'),
(1568877,54,33,3,8,'Ale já naplněn jsem silou Ducha Hospodinova, a soudem i udatností, abych oznámil Jákobovi zpronevěření jeho, a Izraelovi hřích jeho.'),
(1568878,54,33,3,9,'Slyštež již toto přední v domě Jákobově, a vůdcové domu Izraelského, kteříž v ošklivosti mají soud, a cožkoli jest pravého, převracejí:'),
(1568879,54,33,3,10,'Každý vzdělává Sion vraždami, a Jeruzalém nepravostí.'),
(1568880,54,33,3,11,'Jehož přední podlé darů soudí, a kněží jeho ze mzdy učí, a proroci jeho z peněz hádají, a však na Hospodina zpoléhají, říkajíce: Zdaliž Hospodina není u prostřed nás? Nepřijdeť na nás nic zlého.'),
(1568881,54,33,3,12,'A protož vaší příčinou Sion jako pole orán bude, a Jeruzalém v hromady obrácen bude, a hora domu toho v vysoké lesy.'),
(1568882,54,33,4,1,'Ale stane se v posledních dnech, že utvrzena bude hora domu Hospodinova na vrchu hor, a vyvýšena nad pahrbky, i pohrnou se k ní národové.'),
(1568883,54,33,4,2,'A půjdou lidé mnozí, říkajíce: Poďte, a vstupme na horu Hospodinovu, totiž do domu Boha Jákobova, a bude nás vyučovati cestám svým, i budeme choditi po stezkách jeho. Nebo z Siona vyjde zákon, a slovo Hospodinovo z Jeruzaléma.'),
(1568884,54,33,4,3,'Onť bude souditi mezi národy mnohými, a trestati bude národy silné za dlouhé časy. I skují meče své v motyky, a oštípy své v srpy. Nepozdvihne národ proti národu meče, a nebudou se více učiti boji.'),
(1568885,54,33,4,4,'Ale seděti bude každý pod vinným kmenem svým, a pod fíkovím svým, a nebude žádného, kdo by přestrašil; nebo ústa Hospodina zástupů mluvila.'),
(1568886,54,33,4,5,'Všickni zajisté národové choditi budou jeden každý ve jménu boha svého, ale my choditi budeme ve jménu Hospodina Boha našeho na věky věků.'),
(1568887,54,33,4,6,'V ten den, dí Hospodin, zberu zase kulhavou, a zahnanou shromáždím, i tu, kteréž jsem zle činil.'),
(1568888,54,33,4,7,'I dám té kulhavé potomky, a pryč zahnané národ silný, a bude kralovati Hospodin nad nimi na hoře Sion od tohoto času až na věky.'),
(1568889,54,33,4,8,'A tak ty věže bravná, bašto dcery Sionské, až k tobě přijde, přijde, pravím, panování první, a království k dceři Jeruzalémské.'),
(1568890,54,33,4,9,'Pročež nyní tak velice křičíš? Zdaliž není žádného krále v tobě? Zdali rádce tvůj zahynul, že tě zachvátila bolest jako rodičku?'),
(1568891,54,33,4,10,'Pracujž ku porodu a úpěj, dcero Sionská, jako rodička; nebo již vyjdeš z města, a budeš bydliti na poli, a přijdeš až do Babylona. Tam vytržena budeš, tam tě vykoupí Hospodin z ruky nepřátel tvých.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568892,54,33,4,11,'Sbírajíť se nyní sic proti tobě národové mnozí, říkající: Nechť jest poškvrněn Sion, a nechť se podívají na to oči naše.'),
(1568893,54,33,4,12,'Však oni neznají myšlení Hospodinových, aniž rozumějí radě jeho, že je shromažďuje jako snopy na humno.'),
(1568894,54,33,4,13,'Vstaniž a mlať, dcero Sionská; nebo rok tvůj učiním železný, a kopyta tvá učiním ocelivá. I zetřeš národy mnohé, a posvětím Hospodinu jmění jejich, a zboží jejich Pánu vší země.'),
(1568895,54,33,5,1,'Sbeřiž se nyní po houfích, ó záškodnice, oblehni nás, nechať bijí holí v líce soudce Izraelského.'),
(1568896,54,33,5,2,'A ty Betléme Efrata, jakžkoli jsi nejmenší mezi tisíci Judskými, z tebe mi vyjde ten, kterýž má býti Panovníkem v Izraeli, a jehož východové jsou od starodávna, ode dnů věčných.'),
(1568897,54,33,5,3,'Protož, ač je vydá v rozptýlení, ažby ta, kteráž rodí, porodila, však ostatek bratří jeho navrátí se s syny Izraelskými.'),
(1568898,54,33,5,4,'I stane a pásti bude v síle Hospodinově, a u velebnosti jména Hospodina Boha svého. I budou bydliti, nebo již velikomocný bude až do končin země.'),
(1568899,54,33,5,5,'I budeť takový pokoj, že když Assur přitáhne do země naší, a šlapati bude po palácích našich, tedy postavíme proti němu sedm pastýřů, a osmero knížat z lidu,'),
(1568900,54,33,5,6,'Kteříž spasou zemi Assyrskou mečem, a zemi Nimrodovu v pomezích jejích. A tak vytrhne od Assura, když přitáhne do země naší, a šlapati bude po našem pomezí.'),
(1568901,54,33,5,7,'A protož ostatkové Jákobovi u prostřed národů mnohých budou jako rosa od Hospodina, jako tiší dešťové skrápějící bylinu, jichž neočekává od žádného, aniž čeká od synů lidských.'),
(1568902,54,33,5,8,'Budou též ostatkové Jákobovi mezi pohany, a u prostřed národů mnohých, jako lev mezi zvěří divokou, jako mladý lev mezi stády ovec. Kterýžto když jde, a pošlapává, i lapá, není žádného, kdo by vytrhl.'),
(1568903,54,33,5,9,'Vyvýšiť se ruka tvá nad tvými nepřátely, a všickni protivníci tvoji vypléněni budou.'),
(1568904,54,33,5,10,'I stane se v ten den, dí Hospodin, že vypléním koně tvé z prostředku tvého, a zkazím vozy tvé.'),
(1568905,54,33,5,11,'A vypléním města země tvé, a rozbořím všecky pevnosti tvé.'),
(1568906,54,33,5,12,'Vypléním též kouzly z tebe, a planetářů nebude v tobě.'),
(1568907,54,33,5,13,'Zahladím i rytiny tvé, i obrazy tvé z prostředku tvého, a nebudeš se klaněti více dílu rukou svých.'),
(1568908,54,33,5,14,'Vykořením i háje tvé z prostředku tvého, a zkazím nepřátely tvé.'),
(1568909,54,33,5,15,'A tak v hněvu a v prchlivosti vykonám pomstu nad těmi národy, kteříž nebyli poslušni.'),
(1568910,54,33,6,1,'Slyštež nyní, co praví Hospodin: Vstaň, suď se s těmito horami, a nechť slyší pahrbkové hlas tvůj.'),
(1568911,54,33,6,2,'Slyštež hory rozepři Hospodinovu, i nejpevnější základové země; nebo má rozepři Hospodin s lidem svým, a proti Izraelovi odpor povede.'),
(1568912,54,33,6,3,'Lide můj, cožť jsem učinil? A čím jsem tě obtěžoval? Vydej svědectví proti mně.'),
(1568913,54,33,6,4,'Ješto jsem tě vyvedl z země Egyptské, a z domu služebníků vykoupil jsem tě, a poslal jsem před tváří tvou Mojžíše, Arona a Marii.'),
(1568914,54,33,6,5,'Lide můj, rozpomeň se nyní, jakou radu skládal Balák král Moábský, a co jemu odpovídal Balám syn Beorův, od Setim až do Galgala, abys poznal hojnou spravedlnost Hospodinovu.'),
(1568915,54,33,6,6,'Čímž předejdu Hospodina? Skloniti-liž se mám před Bohem nejvyšším? Předejdu-liž ho zápaly, volky ročními?'),
(1568916,54,33,6,7,'Zalíbí-liž sobě Hospodin v tisících skopců, v mnohokrát desíti tisících potoků oleje? Dám-liž prvorozeného svého za přestoupení své, plod života svého za hřích duše své?'),
(1568917,54,33,6,8,'Oznámiltě tobě, ó člověče, co jest dobrého, i čehož Hospodin vyhledává od tebe, jediné, abys činil soud, a miloval milosrdenství, a pokorně chodil s Bohem svým.'),
(1568918,54,33,6,9,'Hlas Hospodinův na město volá (ale sám rozumný spatřuje jméno tvé,): Slyštež o metle, a kdo ji uložil.'),
(1568919,54,33,6,10,'Ještě-liž jsou v domě bezbožného pokladové nespravedliví, a míra nespravedlivá a ohavná?'),
(1568920,54,33,6,11,'Zdaliž ospravedlniti mám vážky nepravé, a v pytlíku kamení falešné?'),
(1568921,54,33,6,12,'Bohatí jeho plní jsou nátisku, a obyvatelé jeho mluví lež, a jazyk jejich lstivý jest v ústech jejich.'),
(1568922,54,33,6,13,'Pročež i já také nemoc dopustím, bíti a pléniti tě budu pro hříchy tvé.'),
(1568923,54,33,6,14,'Ty budeš jísti, a nenasytíš se, a snížení tvé bude u prostřed tebe. Vyneseš zajisté, ale neodneseš, a co vyneseš, vydám pod meč.'),
(1568924,54,33,6,15,'Ty budeš síti, ale nebudeš žíti; ty tlačiti budeš olivky, ale nebudeš se pomazovati olejem, i mest, ale nebudeš píti vína.'),
(1568925,54,33,6,16,'Nebo snažně ostříhá ustanovení Amri, i každého skutku domu Achabova, a spravujete se radami jejich, tak abych tě vydal v zpuštění, a obyvatele jeho v posměch. A protož pohanění lidu mého ponesete.'),
(1568926,54,33,7,1,'Běda mně, že jsem jako paběrek úrod letních, jako paběrkové po vinobraní. Není žádného hroznu k jídlu, prvotiny z ovoce žádá duše má.'),
(1568927,54,33,7,2,'Zahynul pobožný z země této, a upřímého mezi lidmi není žádného; všickni napořád o vylití krve úklady činí, jeden každý bratra svého loví sítí.'),
(1568928,54,33,7,3,'Co zlého oběma rukama páchají, to aby za dobré počteno bylo. Kníže žádá, a soudce z úplatku soudí, a kdož veliký jest, ten mluví převrácenost duše své, a v hromadu ji pletou.'),
(1568929,54,33,7,4,'Nejlepší z nich jest jako bodlák, nejupřímější převyšuje trní. Přicházíť den strážných tvých, navštívení tvé přichází; jižť nastane zpletení jejich.'),
(1568930,54,33,7,5,'Nedověřujte se příteli, nedoufejte v vůdce; před tou, jenž leží v lůnu tvém, ostříhej dveří úst svých.'),
(1568931,54,33,7,6,'Nebo syn v lehkost uvodí otce, dcera povstává proti mateři své, nevěsta proti svegruši své, a nepřátelé jednoho každého jsou vlastní jeho.'),
(1568932,54,33,7,7,'Protož já na Hospodina vyhlédati budu, očekávati budu na Boha spasení svého, vyslyšíť mne Bůh můj.'),
(1568933,54,33,7,8,'Neraduj se ze mne, nepřítelkyně má. Upadla-liť jsem, povstanu; sedím-liť v temnostech, svítí mi Hospodin.'),
(1568934,54,33,7,9,'Zůřivost Hospodinovu ponesu, nebo jsem proti němu zhřešila, až se vždy zasadí o mou při, a mne zastane. Vyvedeť mne na světlo, budu viděti spravedlnost jeho.'),
(1568935,54,33,7,10,'Uzříť to nepřítelkyně má, a přikryje ji hanba, ješto mi říká: Kdež jest Hospodin Bůh tvůj? Oči mé podívají se na ni; jižť bude rozšlapána jako bláto na ulicích.'),
(1568936,54,33,7,11,'Toho dne, v němž vystaveny budou hradby tvé, toho dne daleko se rozejde výpověd.'),
(1568937,54,33,7,12,'Toho dne k tobě přicházeti budou i z Assyrské země až do pevností, a od pevností až k řece, a od moře k moři, a od hory k hoře.'),
(1568938,54,33,7,13,'A však země tato zpuštěna bude pro obyvatele své, pro ovoce činů jejich.'),
(1568939,54,33,7,14,'Pasiž lid svůj berlou svou, stádce dědictví svého, kteréž přebývá osamělé v lese u prostřed polí, ať spasou Bázan a Galád jako za dnů starodávních,'),
(1568940,54,33,7,15,'Jako za dnů v nichž jsi vyšel z země Egyptské. Ukáži jemu divné věci.'),
(1568941,54,33,7,16,'Což vidouce národové, styděti se budou za všecku sílu svou; vloží ruku na ústa, a uši jejich ohlechnou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568942,54,33,7,17,'Lízati budou prach jako had, a jako hadové zemští s třesením polezou z děr svých; k Hospodinu Bohu našemu, předěšeni jsouce, poběhnou, a báti se tebe budou.'),
(1568943,54,33,7,18,'Kdo jest Bůh silný podobný tobě, kterýž by snímal nepravost a promíjel přestoupení ostatkům dědictví svého, kterýž by nedržel na věky hněvu svého, proto že líbost má v slitování se?'),
(1568944,54,33,7,19,'Navrátě se, slituje se nad námi, podmaní nepravosti naše; nýbrž uvržeš do hlubin mořských všecky hříchy naše.'),
(1568945,54,33,7,20,'Pravdomluvným se ukážeš Jákobovi, milosrdným Abrahamovi, jakož jsi přisáhl otcům našim ode dnů starodávních.'),
(1568946,54,34,1,1,'Břímě Ninive: Kniha vidění Nahuma Elkošského.'),
(1568947,54,34,1,2,'Hospodin jest Bůh horlivý a mstitel, mstitel jestiť Hospodin, a zůřivý. Hospodin uvodí pomstu na protivníky své, a drží hněv proti nepřátelům svým.'),
(1568948,54,34,1,3,'Hospodin dlouhočekající jest a velikomocný, však nikoli neospravedlňuje vinného. U vichru a bouři jest cesta Hospodinova, a oblak jest prach noh jeho.'),
(1568949,54,34,1,4,'Když domlouvá moři, vysušuje je, i všecky řeky vysušuje; chřadne Bázan i Karmel, i květ Libánský chřadne.'),
(1568950,54,34,1,5,'Hory se třesou před ním, a pahrbkové se rozplývají, země pak hoří před tváří jeho, i okršlek zemský a všickni, kteříž přebývají na něm.'),
(1568951,54,34,1,6,'Před rozhněváním jeho kdo ostojí? A kdo se postaví proti prchlivosti hněvu jeho? Prchlivost jeho vylévá se jako oheň, a skály vyvracejí se před ním.'),
(1568952,54,34,1,7,'Dobrýť jest Hospodin, silou jest v den ssoužení, a zná ty, kdož v něho doufají.'),
(1568953,54,34,1,8,'Protož povodní prudkou konec učiní místu jeho, a nepřátely Boží stihati budou temnosti.'),
(1568954,54,34,1,9,'Co myslíte proti Hospodinu? Onť konec učiní, nezdvihne druhé rány.'),
(1568955,54,34,1,10,'Nebo rovně jako trní spleteni jsouce, a jako vínem opojeni, jako strniště suché docela sehlceni budou.'),
(1568956,54,34,1,11,'Z tebeť vyšel ten, kterýž myslí proti Hospodinu zlé, rádce nešlechetný.'),
(1568957,54,34,1,12,'Takto dí Hospodin: Byť se byli pokojně měli, byliť by tak v rozšíření zůstali aneb by toliko přemrštěni byli; i bylo by to pominulo, a netrápil bych jich více, tak jako jsem trápil.'),
(1568958,54,34,1,13,'Nyní pak polámi jho jeho, aby neleželo na tobě, a to, čímž jsi svázán, roztrhám.'),
(1568959,54,34,1,14,'Nebo přikázaní vydal proti tobě Hospodin, nebudeť rozsíváno ze jména tvého více; z domu Boha tvého vyhladím rytinu i slitinu, a když zlehčen budeš, způsobímť hrob.'),
(1568960,54,34,1,15,'Aj hle na horách těchto nohy potěšené věci zvěstujícího, ohlašujícího pokoj. Slaviž, o Judo, slavnosti své, plň sliby své. Neboť nepokusí se více ani mimo tebe choditi nešlechetný, docelať jest vyhlazen.'),
(1568961,54,34,2,1,'Táhneť zhoubce na tebe, ostříhejž pevnosti, vyhlídej na cestu, posilň bedr, dobře se silou opatř.'),
(1568962,54,34,2,2,'Neboť jest odjal Hospodin pýchu Jákobovu jako pýchu Izraelovu, proto že vyprázdnili je zhoubcové, a réví jejich pokazili.'),
(1568963,54,34,2,3,'Pavéza udatných jeho červená, bojovníci červcem odění, vozové jako pochodně hořící jiskřiti budou v den mustruňku jeho, a jedle hrozně třásti se budou.'),
(1568964,54,34,2,4,'Po ulicích jezditi budou vozové, a hrčeti po ryncích; na pohledění budou jako pochodně, a jako blesk pronikati budou.'),
(1568965,54,34,2,5,'Sšikuje nejznamenitější své, klesnou v šiku svém, pospíší ke zdem jeho, a skryše připravována bude.'),
(1568966,54,34,2,6,'Brány při řekách se otevrou, chrám se rozplyne.'),
(1568967,54,34,2,7,'A Hutsab zajata jsuc, zavedena bude, a děvečky její poberou se, lkajíce jako holubice, a tepouce prsy své.'),
(1568968,54,34,2,8,'A ačkoli jako rybník vod bylo Ninive od začátku svého, však již sami utíkají. Stůjte, stůjte a však žádný se neohlédne.'),
(1568969,54,34,2,9,'Rozchvátejtež stříbro, rozchvácejte zlato a nesčíslná zboží, a cožkoli nejvzácnějšího na všelikých klénotích drahých.'),
(1568970,54,34,2,10,'Prázdné a vyprázdněné, nýbrž docela zpuštěné bude, a srdce se rozplyne, a tlučení kolen vespolek i bolest na všech bedrách bude, a tváře všech zčernají jako hrnec.'),
(1568971,54,34,2,11,'Kdež jest peleš lvů a to pastviště lvíčat, kamž chodíval lev, lev i lvíče, a nebylo žádného, kdo by přestrašil.'),
(1568972,54,34,2,12,'Lev, kterýž hojně lovíval mladým svým, a dávíval lvicím svým, kterýž naplňoval loupeží jeskyně své, a peleše své tím, což nahonil?'),
(1568973,54,34,2,13,'Aj, já proti tobě, praví Hospodin zástupů, a popálím na prach vozy tvé, a lvíčata tvá sžíře meč; i vypléním z země loupež tvou, a nebude slyšán více hlas poslů tvých.'),
(1568974,54,34,3,1,'Běda městu vražednému, kteréž všecko lži a ukrutenství plné jest, neodchází z něho loupež.'),
(1568975,54,34,3,2,'Praskání bičů a hřmot kol, a dusání koní, a vozů skákání bude.'),
(1568976,54,34,3,3,'Jezdec vyzdvihne třpytící se meč, a blýskající se kopí, i bude množství zbitých, a veliké hromady těl mrtvých, tak že nebude žádného počtu těl mrtvých, až i padati budou přes těla jejich,'),
(1568977,54,34,3,4,'Pro množství smilství smilnice, velmi milé, mistryně kouzlů, kteráž prodávala národy smilstvými svými, a lidi kouzly svými.'),
(1568978,54,34,3,5,'Aj, já proti tobě, dí Hospodin zástupů, a odkryji podolek tvůj nad hlavu tvou, a ukáži národům nahotu tvou, a královstvím hanbu tvou.'),
(1568979,54,34,3,6,'A ukydaje tě ohavnými věcmi, uvedu tě v lehkost, a vystavím tě za divadlo.'),
(1568980,54,34,3,7,'I stane se, že kdožkoli uzří tě, vzdálí se od tebe, a dí: Vyplundrováno jest Ninive. Kdož by ho litovati měl? Kdež bych shledal ty, kteříž by tě těšiti měli?'),
(1568981,54,34,3,8,'Což by se tobě lépe díti mělo, nežli No lidnému, kteréž sedělo mezi řekami, vodami byvši opuštěno, jehož val bylo moře, zed mělo od moře?'),
(1568982,54,34,3,9,'Mouřenínská země i Egypt silou jeho byla, a nesčíslní, Putští a Lubimští, byli jemu na pomoc.'),
(1568983,54,34,3,10,'A však i to v přestěhování přišlo a v zajetí, tak že i maličcí jeho rozrážíni byli na úhlech všech ulic, a o nejslavnější jeho metali los, a všickni znamenití jeho sevříni byli pouty.'),
(1568984,54,34,3,11,'Takž i ty opiješ se, a pokrývati se musíš, i ty hledati budeš pomoci proti nepříteli.'),
(1568985,54,34,3,12,'Všecky tvé pevnosti jsou jako fíkové s ovocem ranním, jimž jakž se zatřese, prší do úst toho, kdož by jedl.'),
(1568986,54,34,3,13,'Aj, lid tvůj jsou ženy u prostřed tebe, nepřátelům tvým dokořen otevříny budou brány země tvé, a oheň sžíře závory tvé.'),
(1568987,54,34,3,14,'Navaž sobě vody k obležení, upevni ohrady své, vejdi do bláta a šlapej hlinu, oprav cihelnu.'),
(1568988,54,34,3,15,'Tam tě sžíře oheň, vytne tě meč, sžíře tě jako brouky, nechť jest vás veliký počet jako brouků, nechť jest vás veliký počet jako kobylek.'),
(1568989,54,34,3,16,'Rozmnožilo jsi kupce své nad hvězdy nebeské, brouci připadnou i zaletují.'),
(1568990,54,34,3,17,'Znamenití tvoji jako kobylky, a hejtmané tvoji jako velicí chroustové, kteříž se kladou vojensky po plotích v čas studena. Slunce vzešlo, tožť letí, aniž znáti místa jejich, kde byli.'),
(1568991,54,34,3,18,'Zdřímají pastýři tvoji, ó králi Assyrský, ležeti budou znamenití tvoji, hojnost lidu tvého bude po horách, ale nebude žádného, kdo by shromáždil.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1568992,54,34,3,19,'K potření tvému není žádného léku, bolest rány tvé rozmohla se. Kteřížkoli uslyší pověst o tobě, rukama plésati budou nad tebou. Nebo na koho ustavičně nedocházelo ukrutenství tvé?'),
(1568993,54,35,1,1,'Břímě, kteréž u vidění viděl Abakuk prorok.'),
(1568994,54,35,1,2,'Až dokud, ó Hospodine, křičeti budu, a nevyslyšíš? Volati budu k tobě pro nátisk, a nespomůžeš?'),
(1568995,54,35,1,3,'Proč dopouštíš, abych hleděti musil na nepravost, a na bezpráví se dívati, též na zhoubu a na nátisk proti mně? A vždy jest, kdož svár a různici vzbuzuje.'),
(1568996,54,35,1,4,'Odkudž se děje opuštění zákona, a nedochází nikdá soud. Nebo bezbožný obkličuje spravedlivého, pročež vychází soud převrácený.'),
(1568997,54,35,1,5,'Pohleďte na národy a popatřte, nýbrž s velikým podivením se užasněte, proto že dělám dílo ve dnech vašich, o němž když vypravováno bude, neuvěříte.'),
(1568998,54,35,1,6,'Nebo aj, já vzbudím Kaldejské, národ lítý a rychlý, kterýž zjezdí všecku širokost země, aby dědičně opanoval příbytky jiných,'),
(1568999,54,35,1,7,'Strašlivý a hrozný, od něhož soud jeho i vyvýšenost jeho vyjde.'),
(1569000,54,35,1,8,'Koni jeho rychlejší budou než rysové, a lítější nad vlky večerní; veliké množství bude jezdců jeho, kteřížto jezdci jeho zdaleka přijedou, a přiletí jako orlice, kteráž chvátá na pastvu.'),
(1569001,54,35,1,9,'Každý z nich k utiskování přijde, obrátíce tváři své k východu, když seberou jako písek zajaté.'),
(1569002,54,35,1,10,'Tentýž i králům se posmívati bude, a knížata smích jemu budou; tentýž každé pevnosti smáti se bude, a zdělaje náspy, dobude jí.'),
(1569003,54,35,1,11,'Tehdy promění se duch jeho, a přestoupí i zaviní, mysle, že ta moc jeho boha jeho jest.'),
(1569004,54,35,1,12,'Hospodine Bože můj, Svatý můj, zdaliž ty nejsi od věčnosti? Myť nezemřeme. Hospodine, k soudu postavil jsi jej, ty, ó skálo, k trestání nastrojil jsi ho.'),
(1569005,54,35,1,13,'Čistéť jsou tvé oči, tak že na zlé věci hleděti, a na bezpráví se dívati nemůžeš. Pročež přehlídati máš nešlechetníkům a mlčeti, poněvadž bezbožník sehlcuje spravedlivějšího, než sám jest.'),
(1569006,54,35,1,14,'A zanechávati lidí jako ryb mořských, jako zeměplazu, kterýž nemá pána?'),
(1569007,54,35,1,15,'Všecky napořád udicí vytahuje, zatahuje je sítí svou, a zahrnuje je nevodem svým, protož veselí se a pléše.'),
(1569008,54,35,1,16,'Protož síti své obětuje, a kadí nevodu svému; nebo skrze ně ztučněl díl jeho, a strava jeho zlepšena.'),
(1569009,54,35,1,17,'S tím-liž se vším předce zatahovati má sít svou, a ustavičně národy mordovati bez lítosti?'),
(1569010,54,35,2,1,'Na stráži své státi budu, a postavím se na baště, vyhlédaje, abych viděti mohl, co mluviti bude ke mně Bůh, a co bych odpovídati měl po svém trestání.'),
(1569011,54,35,2,2,'I odpověděl mi Hospodin, a řekl: Napiš vidění, a to zřetelně na dskách, aby je přeběhl čtenář,'),
(1569012,54,35,2,3,'Proto že ještě do jistého času bude vidění, a směle mluviti bude až do konce, a nesklamáť. Jestliže by pak poprodlilo, posečkej na ně; neboť jistotně dojde, aniž bude meškati.'),
(1569013,54,35,2,4,'Aj ten, kdož se zpíná, tohoť duše není upřímá v něm, ale spravedlivý z víry své živ bude.'),
(1569014,54,35,2,5,'Ovšem pak více opilec, nešlechetnost a pýchu provodě, neostojí v příbytku; kterýž rozšiřuje jako peklo duši svou, jest jako smrt, kteráž se nemůže nasytiti, byť pak shromáždil k sobě všecky národy, a shrnul k sobě všecky lidi.'),
(1569015,54,35,2,6,'Zdaliž všickni ti proti němu přísloví nevynesou, a světlých slov i pohádek o něm? A neřeknou-liž: Běda tomu, kterýž rozmnožuje věci ne své, (až dokud pak?) a obtěžuje se hustým blátem?'),
(1569016,54,35,2,7,'Zdaliž nepovstanou rychle, kteříž by tě hryzli, a neprocítí, kteříž by tebou smýkali? A budeš u nich v ustavičném potlačení.'),
(1569017,54,35,2,8,'Proto že jsi ty zloupil národy mnohé, zloupí tě všickni ostatkové národů, pro krev lidskou, a nátisk země a města, i všech, kteříž přebývají v něm.'),
(1569018,54,35,2,9,'Běda tomu, kdož lakomě hledá mrzkého zisku domu svému, aby postavil na místě vysokém hnízdo své, a tak znikl nebezpečenství.'),
(1569019,54,35,2,10,'Uradils se k hanbě domu svému, abys plénil národy mnohé, a zhřešil sobě samému.'),
(1569020,54,35,2,11,'Nebo kamení ze zdi křičeti bude, a suk z dřeva posvědčovati bude toho.'),
(1569021,54,35,2,12,'Běda tomu, kterýž staví město krví, a utvrzuje město nepravostí.'),
(1569022,54,35,2,13,'Aj, zdaliž to není od Hospodina zástupů, že, o čemž pracují lidé a národové až do ustání nadarmo, oheň zkazí.'),
(1569023,54,35,2,14,'Nebo naplněna bude země známostí slávy Hospodinovy, jako vody naplňují moře.'),
(1569024,54,35,2,15,'Běda tomu, kterýž napájí bližního svého, přičiněje nádoby své, tak aby jej opojil, a díval se na jeho nahotu.'),
(1569025,54,35,2,16,'Sytíš se potupou, proto že jsi slavný. Píti budeš i ty, a obnažen budeš; obejdeť k tobě kalich pravice Hospodinovy, a vývratek mrzutý na slávu tvou.'),
(1569026,54,35,2,17,'Nebo nátisk Libánu a zhouba zvěři, kteráž ji děsila, přikryje tě, pro krev lidskou, a nátisk země a města, i všech, kteříž přebývají v něm.'),
(1569027,54,35,2,18,'Co prospívá rytina, že ji vyryl řemeslník její? Slitina i učitel lži, že doufá učinitel v účinek svůj, dělaje modly němé?'),
(1569028,54,35,2,19,'Běda tomu, kterýž říká dřevu: Prociť, a kameni němému: Probuď se. On-liž by učiti mohl? Pohleď na něj. Obloženť jest zlatem a stříbrem, ale není v něm žádného ducha.'),
(1569029,54,35,2,20,'Hospodin pak v chrámě svatosti své jest, umlkniž před oblíčejem jeho všecka země.'),
(1569030,54,35,3,1,'Modlitba Abakuka proroka podlé Šigejonót:'),
(1569031,54,35,3,2,'Ó Hospodine, uslyšev pohrůžku tvou, ulekl jsem se. Hospodine, dílo své u prostřed let při životu zachovej, u prostřed let známé učiň, v hněvě na milosrdenství se rozpomeň.'),
(1569032,54,35,3,3,'Když se Bůh bral od poledne, a Svatý s hory Fáran, Sélah, slávu jeho přikryla nebesa, a země byla plná chvály jeho.'),
(1569033,54,35,3,4,'Blesk byl jako světlo, rohy po bocích svých měl, a tu skryta byla síla jeho.'),
(1569034,54,35,3,5,'Před tváří jeho šlo morní nakažení, a uhlí řeřavé šlo před nohama jeho.'),
(1569035,54,35,3,6,'Zastavil se, a změřil zemi; pohleděl, a rozptýlil národy. Zrozrážíny jsou hory věčné, sklonili se pahrbkové věční, cesty jeho jsou věčné.'),
(1569036,54,35,3,7,'Viděl jsem, že stanové Chusan jsou pouhá marnost, a třásli se kobercové země Madianské.'),
(1569037,54,35,3,8,'Zdaliž se na řeky, ó Hospodine, zdaliž se na řeky rozpálil hněv tvůj? Zdali proti moři rozhněvání tvé, když jsi jel na koních svých a na vozích svých spasitelných?'),
(1569038,54,35,3,9,'Patrně jest zjeveno lučiště tvé pro přísahy pokolením lidu tvého stalé, Sélah. Řeky země jsi rozdělil,'),
(1569039,54,35,3,10,'Viděly tě hory, třásly se, povodeň vod ustoupila; vydala propast hlas svůj, hlubina rukou svých pozdvihla.'),
(1569040,54,35,3,11,'Slunce a měsíc v obydlí svém zastavil se, při světle střely tvé létaly, při blesku stkvoucí kopí tvé.'),
(1569041,54,35,3,12,'V hněvě šlapal jsi zemi, v prchlivosti mlátil jsi pohany.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569042,54,35,3,13,'Vyšel jsi k vysvobození lidu svého, k vysvobození s pomazaným svým; srazil jsi hlavu s domu bezbožníka až do hrdla, obnaživ základ. Sélah.'),
(1569043,54,35,3,14,'Holemi jeho probodl jsi hlavu vsí jeho, když se bouřili jako vichřice k rozptýlení mému, plésali, jako by sežrati měli chudého v skrytě.'),
(1569044,54,35,3,15,'Bral jsi se po moři na koních svých, skrze hromadu vod mnohých.'),
(1569045,54,35,3,16,'Slyšel jsem, a zatřáslo se břicho mé, k hlasu tomu drkotali rtové moji, kosti mé práchnivěly, a všecken jsem se třásl, že se mám upokojiti v den ssoužení, když přitáhne na lid, aby jej válečně hubil.'),
(1569046,54,35,3,17,'Byť pak fík nekvetl, a nebylo úrody na vinicích; byť i ovoce olivy pochybilo, a rolí nepřinesla užitky; a od ovčince odřezován byl brav, a nebylo žádného skotu v chlévích:'),
(1569047,54,35,3,18,'Já však v Hospodinu veseliti se budu, plésati budu v Bohu spasení svého.'),
(1569048,54,35,3,19,'Hospodin Panovník jest síla má, kterýž činí nohy mé jako laní, a na vysokých místech mých cestu mi způsobuje. Přednímu zpěváku na můj neginot.'),
(1569049,54,36,1,1,'Slovo Hospodinovo, kteréž se stalo k Sofoniášovi synu Chusi, syna Godoliášova, syna Amariášova, syna Ezechiášova, za dnů Joziáše syna Amonova, krále Judského.'),
(1569050,54,36,1,2,'Zajisté že sklidím všecko se svrchku té země, praví Hospodin.'),
(1569051,54,36,1,3,'Sklidím lidi i hovada, sklidím ptactvo nebeské i ryby mořské, i pohoršení s bezbožnými; vypléním, pravím, lidi se svrchku této země, praví Hospodin.'),
(1569052,54,36,1,4,'Nebo vztáhna ruku svou na Judu a na všecky obyvatele Jeruzalémské, zahladím z místa tohoto ostatek Bále, i kněží jeho s jich pomocníky,'),
(1569053,54,36,1,5,'I ty, kteříž se klanějí na střechách vojsku nebeskému, i ty, kteříž klanějíce se, přisahají skrze Hospodina, i ty, kteříž přisahají skrze Melecha svého.'),
(1569054,54,36,1,6,'I ty, kteříž zpět odcházejí, aby nenásledovali Hospodina, a kteříž nehledají Hospodina, aniž se ho dotazují.'),
(1569055,54,36,1,7,'Umlkni před oblíčejem Panovníka Hospodina, nebo blízký jest den Hospodinův; přistrojil zajisté Hospodin obět, povolal pozvaných svých.'),
(1569056,54,36,1,8,'I stane se v den oběti Hospodinovy, že navštívím knížata a syny královy i všecky, kteříž se obláčejí v roucho cizozemců.'),
(1569057,54,36,1,9,'Navštívím v ten den i každého, kterýž vskakuje na prah, kteříž naplňují dům pánů svých nátiskem a lstí.'),
(1569058,54,36,1,10,'I stane se v ten den, praví Hospodin, hlas křiku od brány rybné, a kvílení od druhé strany a třeskot veliký od pahrbků.'),
(1569059,54,36,1,11,'Kvělte vy, kteříž bydlíte u vnitřku; nebo vyhlazen bude všecken obor kupců, vypléněni budou všickni snášející stříbro.'),
(1569060,54,36,1,12,'I stane se v ten čas, že přehledávati budu Jeruzalém s lucernami, a navštívím muže, kteříž ulnuli v kvasnicích svých, kteříž říkají v srdci svém: Nečiniť dobře Hospodin, aniž zle činí.'),
(1569061,54,36,1,13,'Nebo přijde statek jejich na rozchvátání, a domové jejich na zpuštění. Stavějí zajisté domy, ale nebudou v nich bydliti; a štěpují vinice, ale nebudou píti vína z nich.'),
(1569062,54,36,1,14,'Blízký jest den Hospodinův veliký, blízký jest a rychlý velmi zvuk dne Hospodinova, tuť hořce křičeti bude udatný.'),
(1569063,54,36,1,15,'Den rozhněvání bude ten den, den úzkosti a trápení, den zpuštění a to hrozného, den temnosti a mračna, den oblaku a mrákoty,'),
(1569064,54,36,1,16,'Den trouby a troubení proti městům hrazeným, a proti úhlům vysokým,'),
(1569065,54,36,1,17,'V němž úzkostmi sevru lidi, aby chodili jako slepí, nebo proti Hospodinu zhřešili. I vylita bude krev jejich jako prach, a těla jejich jako lejna.'),
(1569066,54,36,1,18,'Ani stříbro jejich, ani zlato jejich nebude jich moci vytrhnouti v den rozhněvání Hospodinova; nebo ohněm horlivosti jeho sehlcena bude tato všecka země, proto že konec jistě rychlý učiní všechněm obyvatelům země.'),
(1569067,54,36,2,1,'Ohledejte sebe, ohledejte, pravím, ó národe nemilý,'),
(1569068,54,36,2,2,'Prvé než uložení přijde, a den jako plevy pomine, prvé než přijde na vás prchlivost hněvu Hospodinova, prvé než přijde na vás den hněvu Hospodinova.'),
(1569069,54,36,2,3,'Hledejte Hospodina všickni tiší země, kteříž soud jeho činíte; hledejte spravedlnosti, hledejte tichosti. Snad se ukryjete v den hněvu Hospodinova.'),
(1569070,54,36,2,4,'Nebo Gáza bude opuštěno, a Aškalon zpustne; Azot o polednách zaženou, a Akaron vykořeněn bude.'),
(1569071,54,36,2,5,'Běda těm, kteříž bydlí v krajině pomořské, národu Ceretejských. Slovo Hospodinovo proti vám jest, ó země Kananejská Filistinských, že tě tak zahladím, aby nebylo žádného obyvatele.'),
(1569072,54,36,2,6,'I bude krajina pomořská místo ovčinců, jam pastýřských a stájí dobytka.'),
(1569073,54,36,2,7,'Bude také i ostatku domu Judského krajinou, kdež by pásli. V domích Aškalonu u večer léhati budou, když je navštíví Hospodin Bůh jejich, a přivede zase zajaté jejich.'),
(1569074,54,36,2,8,'Slyšelť jsem hanění Moábských a utrhání synů Ammonitských, kterýmiž haněli můj lid, a honosili se na pomezí jejich.'),
(1569075,54,36,2,9,'Protož živ jsem já, praví Hospodin zástupů, Bůh Izraelský, že Moáb jako Sodoma bude, a synové Ammonitští jako Gomora, místem kopřiv a domem solným a pustinou až na věky. Ostatkové lidu mého rozchvátají je, a pozůstalí z lidu mého dědičně je obdrží.'),
(1569076,54,36,2,10,'To jim pro pýchu jejich, že zhaněli a zpínali se nad lid Hospodina zástupů.'),
(1569077,54,36,2,11,'Hrozný jim bude Hospodin; nebo způsobí, aby zhubeněli všickni bohové země. I bude se jemu klaněti každý z místa svého, všickni ostrovové národu.'),
(1569078,54,36,2,12,'Také i vy, Mouřenínové, mečem mým zbiti budete.'),
(1569079,54,36,2,13,'Nebo vztáhne ruku svou na půlnoci, a zhubí Assyrii, a obrátí Ninive v pustinu, a v suchost jako poušť.'),
(1569080,54,36,2,14,'I budou u prostřed něho léhati stáda, všecky šelmy národů, pelikán i výr na makovicích jeho nocovati budou; hlas zníti bude na okně, pustina na veřeji, když cedroví jeho obnaží.'),
(1569081,54,36,2,15,'Takovéť bude to město plésající, kteréž sedí bezpečně, říkaje v srdci svém: Já jsem, a kromě mne není žádného více. Jakť jest učiněno pusté, peleší šelmám! Kdožkoli půjde skrze ně, ckáti bude a zmítati rukou svou.'),
(1569082,54,36,3,1,'Běda městu tomuto hltavému a poškvrněnému a utiskujícímu.'),
(1569083,54,36,3,2,'Neposlouchá hlasu, aniž přijímá kázně; v Hospodina nedoufá, k Bohu svému nepřibližuje se.'),
(1569084,54,36,3,3,'Knížata jeho jsou u prostřed něho lvové řvoucí, soudcové jeho vlci večerní, nehryzou kostí až do rána.'),
(1569085,54,36,3,4,'Proroci jeho kvapní, muži velmi nešlechetní; kněží jeho poškvrňují věci svaté, natahují zákona.'),
(1569086,54,36,3,5,'Hospodin spravedlivý u prostřed něho jest, nelibuje nepravosti, každého dne soud svůj vynáší na světlo bez přestání, a však nešlechetník neumí se styděti.'),
(1569087,54,36,3,6,'Vyplénil jsem národy, zpustli zámkové jejich, v pustinu obrátil jsem ulice jejich, tak že žádný přes ně nechodí; zpustla města jejich, tak že není člověka, není žádného obyvatele.'),
(1569088,54,36,3,7,'Řekl jsem: Jistotně báti se mne budeš, přijmeš kázeň, aby nebyl vypléněn příbytek tvůj tím, čím jsem tě navštíviti chtěl. Ale ráno vstanouce, porušují všecky snažnosti své.'),
(1569089,54,36,3,8,'Protož očekávejtež na mne, praví Hospodin, do dne toho, v kterémž povstanu k loupeži. Nebo soud můj jest, abych sebral národy, shromáždil království, abych vylil na ně rozhněvání své a všecku prchlivost hněvu svého; ohněm zajisté horlivosti mé sehlcena bude všecka tato země.'),
(1569090,54,36,3,9,'Tehdáž zajisté způsobím národům rty čisté, jimiž by vzývali všickni jméno Hospodinovo, a sloužili jemu jedním ramenem.'),
(1569091,54,36,3,10,'Ti, kteříž jsou za řekami Mouřenínské země, koříce se mi, se dcerou rozptýlených mých dary mi přinesou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569092,54,36,3,11,'V ten den nebudeš se hanbiti za žádné skutky své, jichž jsi se dopustil proti mně; nebo tehdáž odejmu z prostředku tvého ty, kteříž pléší v důstojnosti tvé, a nebudeš se více vyvyšovati na hoře svatosti mé.'),
(1569093,54,36,3,12,'A pozůstavím u prostřed tebe lid chudý a nuzný, i budou doufati ve jménu Hospodinovu.'),
(1569094,54,36,3,13,'Ostatkové Izraele neučiní nepravosti, aniž mluviti budou lži, aniž se nalezne v ústech jejich jazyk lstivý, ale pásti se budou a odpočívati, a nebude žádného, kdo by je přestrašil.'),
(1569095,54,36,3,14,'Prozpěvuj, dcero Sionská, prokřikujte, Izraelští, vesel se a plésej vším srdcem, dcero Jeruzalémská,'),
(1569096,54,36,3,15,'Že odjal Hospodin soudy tvé, odklidil nepřítele tvého. Král Izraelský Hospodin jest u prostřed tebe, nebudeš se báti více zlého.'),
(1569097,54,36,3,16,'V ten den bude řečeno Jeruzalému: Neboj se, a Sionu: Nechť nemdlejí ruce tvé.'),
(1569098,54,36,3,17,'Hospodin Bůh tvůj u prostřed tebe mocný zachová tě, radovati se bude z tebe velice, přestane na milování svém tebe, plésati bude nad tebou s prozpěvováním, řka:'),
(1569099,54,36,3,18,'Toužící po Jeruzalému zase sberu, z tebeť jsou, bolestící pro břímě pohanění vzložené na tebe.'),
(1569100,54,36,3,19,'Aj, já konec učiním všechněm, kteříž tě trápiti budou v ten čas, a zachovám kulhavou, a zahnanou shromáždím; nýbrž způsobím jim chválu a jméno po vší zemi, v níž pohanění nesli.'),
(1569101,54,36,3,20,'V ten čas přivedu vás, v ten čas, pravím, shromáždím vás; nebo dám vám jméno a chválu mezi všemi národy země, když zase přivedu zajaté vaše před očima vašima, dí Hospodin.'),
(1569102,54,37,1,1,'Léta druhého Daria krále, měsíce šestého, prvního dne téhož měsíce, stalo se slovo Hospodinovo skrze Aggea proroka k Zorobábelovi synu Salatielovu, knížeti Judskému, a k Jozue synu Jozadakovu, knězi nejvyššímu, řkoucí:'),
(1569103,54,37,1,2,'Takto dí Hospodin zástupů, řka: Lid tento praví, že nepřišel čas, čas, v němž by dům Hospodinův staven byl.'),
(1569104,54,37,1,3,'Pročež stalo se slovo Hospodinovo skrze Aggea proroka, řkoucí:'),
(1569105,54,37,1,4,'Jest-liž vám čas, abyste vy seděli v domích svých taflovaných, a dům tento pustý stál?'),
(1569106,54,37,1,5,'Protož nyní takto praví Hospodin zástupů: Přiložte srdce své k cestám svým.'),
(1569107,54,37,1,6,'Sejete mnoho, a shromažďujete málo; jíte, ale nebýváte nasyceni; pijete, ale neuhašujete žízně; obláčíte se, ale žádný nemůže se zahříti; a ten, kdož sobě mzdu shromažďuje, shromažďuje ji do pytlíka děravého.'),
(1569108,54,37,1,7,'Takto praví Hospodin zástupů: Přiložte srdce své k cestám svým.'),
(1569109,54,37,1,8,'Vstupte na tuto horu, a svezouce dříví, stavějte dům tento, i oblíbím sobě to, a budu oslaven, praví Hospodin.'),
(1569110,54,37,1,9,'Patříte na mnoho, a aj, maličko jest, a což vnášíte do domu, já to rozdmychuji. Proč se to děje? dí Hospodin zástupů. I pro dům můj, že pustý jest, ješto vy jeden každý pečlivi jste o dům svůj.'),
(1569111,54,37,1,10,'Protož zavřelo se nebe nad vámi, aby nedávalo rosy, země také zavřela se, aby nevydávala úrody své.'),
(1569112,54,37,1,11,'A tak zavolal jsem sucha na zemi tuto, a na tyto hory, i na obilé, i na víno, a na olej, i na to, což by měla vydávati země, i na lidi, i na dobytek, i na všecku práci rukou.'),
(1569113,54,37,1,12,'I uposlechl Zorobábel syn Salatielův, a Jozue syn Jozadakův, kněz nejvyšší, i všickni ostatkové lidu hlasu Hospodina Boha svého, a slov Aggea proroka, poněvadž jej poslal Hospodin Bůh jejich; nebo se bál lid tváři Hospodinovy.'),
(1569114,54,37,1,13,'Tedy Aggeus posel Hospodinův mluvil lidu v poselství Hospodinovu, řka: Já s vámi jsem, praví Hospodin.'),
(1569115,54,37,1,14,'V tom vzbudil Hospodin ducha Zorobábele syna Salatielova, knížete Judského, a ducha Jozue syna Jozadakova, kněze nejvyššího, a ducha ostatků všeho lidu, a přišedše, dělali dílo v domě Hospodina zástupů, Boha svého.'),
(1569116,54,37,2,1,'Dne dvadcátého čtvrtého, měsíce šestého, léta druhého Daria krále.'),
(1569117,54,37,2,2,'Měsíce sedmého, dvadcátého prvního dne téhož měsíce, stalo se slovo Hospodinovo skrze Aggea proroka, řkoucí:'),
(1569118,54,37,2,3,'Mluv nyní k Zorobábelovi synu Salatielovu, knížeti Judskému, a Jozue synu Jozadakovu, knězi nejvyššímu, i k ostatkům lidu, řka:'),
(1569119,54,37,2,4,'Kdo jest mezi vámi pozůstalý, ješto viděl dům ten v slávě jeho první? A jaký vy jej nyní vidíte? Zdaliž není proti onomu jako nic před očima vašima?'),
(1569120,54,37,2,5,'A však nyní posilň se Zorobábeli, praví Hospodin, posilň se i Jozue synu Jozadakův, kněže nejvyšší, a posilň se všecken lide země této, praví Hospodin, a dodělejte; nebo já s vámi jsem, praví Hospodin zástupů,'),
(1569121,54,37,2,6,'Podlé slova, jímž jsem smlouvu učinil s vámi, když jste vycházeli z Egypta. Duch také můj stane u prostřed vás, nebojtež se.'),
(1569122,54,37,2,7,'Nebo takto praví Hospodin zástupů: Po malém času, aj, já ještě jednou pohnu nebem i zemí, a mořem i suchostí.'),
(1569123,54,37,2,8,'Pohnu, pravím, všemi národy, a přijdou k Žádoucímu všechněm národům, i naplním dům tento slávou, praví Hospodin zástupů.'),
(1569124,54,37,2,9,'Méť jest stříbro a mé jest zlato, praví Hospodin zástupů.'),
(1569125,54,37,2,10,'Větší bude sláva domu tohoto posledního, než onoho prvního, praví Hospodin zástupů; nebo na tomto místě způsobím pokoj, praví Hospodin zástupů.'),
(1569126,54,37,2,11,'Dvadcátého čtvrtého dne, devátého měsíce, léta druhého Daria, stalo se slovo Hospodinovo skrze Aggea proroka, řkoucí:'),
(1569127,54,37,2,12,'Takto praví Hospodin zástupů: Vzeptej se nyní kněží na zákon, řka:'),
(1569128,54,37,2,13,'Ej, kdyby někdo nesl maso svaté v křídle sukně své, aneb dotkl by se křídlem svým chleba, neb vaření, neb vína, neb oleje, neb jakéžkoli krmě, zdali bude posvěcen? I odpověděli kněží a řekli: Nikoli.'),
(1569129,54,37,2,14,'Tedy řekl Aggeus: Jestliže někdo jsa nečistý od těla mrtvého, dotkl by se něčeho z těch věcí, bude-li nečisté? I odpověděli kněží a řekli: Nečisté bude.'),
(1569130,54,37,2,15,'Tedy odpovídaje Aggeus, řekl: Tak lid tento a tak národ tento před tváří mou, praví Hospodin, a tak všecko dílo rukou jejich, i cožkoli obětovali tam, nečisté bylo.'),
(1569131,54,37,2,16,'Nyní tedy přiložte medle srdce své od tohoto dne až do onoho, jakž přestal kladen býti kámen na kameni v domě Hospodinově,'),
(1569132,54,37,2,17,'Od toho času, když přišel někdo k hromadě dvadcíti, bylo jen deset; když přišel k kádi, aby nabral padesáte z presu, bylo jen dvadcet.'),
(1569133,54,37,2,18,'Bil jsem vás suchem a rzí, i krupobitím všecko dílo rukou vašich, však žádný z vás neobrátil se ke mně, praví Hospodin.'),
(1569134,54,37,2,19,'Přiložte již srdce své od tohoto dne až do onoho, ode dne dvadcátého čtvrtého, měsíce devátého, až do dne, v kterémž založen byl chrám Hospodinův, (přiložte srdce své).'),
(1569135,54,37,2,20,'Zdali již jest semeno v obilnici? Anobrž ani vinný kmen, ani fík, ani strom jablek zrnatých, ani strom olivový nevydal ovoce. Od tohoto dne požehnám.'),
(1569136,54,37,2,21,'Potom stalo se slovo Hospodinovo po druhé k Aggeovi, dvadcátého čtvrtého dne téhož měsíce, řkoucí:'),
(1569137,54,37,2,22,'Mluv k Zorobábelovi knížeti Judskému, řka: Já pohnu nebem i zemí,'),
(1569138,54,37,2,23,'A podvrátím stolici království, a zkazím sílu království pohanských; podvrátím, pravím, vůz i ty, kteříž na něm jezdí, a sejdou koni i jezdci jejich jeden každý od meče bratra svého.'),
(1569139,54,37,2,24,'V ten den, praví Hospodin zástupů, vezmu tebe, Zorobábeli synu Salatielův, služebníče můj, praví Hospodin, a učiním tě jako pečetní prsten; nebo jsem tě vyvolil, praví Hospodin zástupů.'),
(1569140,54,38,1,1,'Měsíce osmého, léta druhého Dariova, stalo se slovo Hospodinovo k Zachariášovi synu Barachiáše, syna Iddova, proroku, řkoucí:'),
(1569141,54,38,1,2,'Rozhněval se Hospodin na otce vaše velice.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569142,54,38,1,3,'Protož rci těmto: Takto praví Hospodin zástupů: Navraťte se ke mně, praví Hospodin zástupů, a navrátím se k vám, praví Hospodin zástupů.'),
(1569143,54,38,1,4,'Nebuďte jako otcové vaši, na něž volávali proroci onino předešlí, říkajíce: Takto praví Hospodin zástupů: Navraťte se nyní od cest svých zlých, i od skutků vašich zlých, ale neuposlechli, ani pozorovali mne, praví Hospodin.'),
(1569144,54,38,1,5,'Otcové vaši kde jsou? A proroci ti zdali na věky živi jsou?'),
(1569145,54,38,1,6,'Ale však slova má a soudové moji, kteréž jsem přikázal služebníkům svým prorokům, zdali nepostihli otců vašich? tak že obrátivše se, řekli: Jakž uložil Hospodin zástupů učiniti nám podlé cest našich, a podlé skutků našich, tak učinil nám.'),
(1569146,54,38,1,7,'Dne čtyřmecítmého, jedenáctého měsíce, kterýž jest měsíc Šebat, léta druhého Dariova, stalo se slovo Hospodinovo k Zachariášovi synu Barachiáše, syna Iddova, proroku, řkoucí:'),
(1569147,54,38,1,8,'Viděl jsem v noci, a aj, muž sedí na koni ryzím, kterýž stál mezi myrtovím, kteréž bylo v dolině, za ním pak koně ryzí, strakaté a bílé.'),
(1569148,54,38,1,9,'I řekl jsem: Kdo jsou tito, Pane můj? Řekl mi anděl ten, kterýž mluvil se mnou: Já ukáži tobě, kdo jsou tito.'),
(1569149,54,38,1,10,'Tedy odpovídaje muž ten, kterýž stál mezi myrtovím, řekl: Tito jsou, kteréž poslal Hospodin, aby zchodili zemi.'),
(1569150,54,38,1,11,'I odpověděli andělu Hospodinovu tomu, kterýž stál mezi myrtovím, a řekli: Zchodili jsme zemi, a aj, všecka země bezpečně bydlí, a pokoje užívá.'),
(1569151,54,38,1,12,'Tedy odpověděl anděl Hospodinův a řekl: Ó Hospodine zástupů, až dokudž ty se nesmiluješ nad Jeruzalémem a nad městy Judskými, na kteréž jsi hněval se již sedmdesáte let?'),
(1569152,54,38,1,13,'I odpověděl Hospodin andělu tomu, kterýž mluvil se mnou, slovy dobrými, slovy potěšitelnými.'),
(1569153,54,38,1,14,'Tedy řekl mi anděl, kterýž mluvil ke mně: Volej a rci: Takto praví Hospodin zástupů: Horlím pro Jeruzalém a Sion horlením velikým.'),
(1569154,54,38,1,15,'A hněvám se náramně na ty národy, kteříž mají pokoj; nebo když jsem já se málo rozhněval, oni pomáhali k zlému.'),
(1569155,54,38,1,16,'Protož takto praví Hospodin: Navrátil jsem se k Jeruzalému milosrdenstvím, dům můj staven bude v něm, praví Hospodin zástupů, a pravidlo vztaženo bude na Jeruzalém.'),
(1569156,54,38,1,17,'Ještě volej a rci: Takto praví Hospodin zástupů: Ještěť se rozsadí města má pro hojnost dobrého; neboť utěší ještě Hospodin Sion, a vyvolí ještě Jeruzalém.'),
(1569157,54,38,1,18,'Tedy pozdvihl jsem očí svých, a uzřel jsem, a aj, čtyři rohové.'),
(1569158,54,38,1,19,'I řekl jsem andělu, kterýž mluvil se mnou: Co jest toto? I řekl mi: To jsou ti rohové, kteříž zmítali Judou, Izraelem a Jeruzalémem.'),
(1569159,54,38,1,20,'Ukázal mi také Hospodin čtyři kováře.'),
(1569160,54,38,1,21,'I řekl jsem: Co jdou dělati tito? I mluvil, řka: Tito jsou rohové, kteříž zmítali Judou, tak že žádný nemohl pozdvihnouti hlavy své. Protož přišli tito, aby je přestrašili, a srazili rohy těch národů, kteříž pozdvihli rohu proti zemi Judské, aby ní zmítali.'),
(1569161,54,38,2,1,'Opět pozdvihl jsem očí svých, a uzřel jsem, a aj muž, v jehož ruce byla šnůra míry.'),
(1569162,54,38,2,2,'I řekl jsem: Kam jdeš? I řekl mi: Měřiti Jeruzaléma, abych viděl, jak veliká širokost jeho, a jak veliká dlouhost jeho.'),
(1569163,54,38,2,3,'A aj, když anděl ten, kterýž mluvil se mnou, vycházel, jiný anděl vycházel jemu vstříc.'),
(1569164,54,38,2,4,'A řekl jemu: Běž, mluv k mládenci tomu, řka: Po vsech bydliti budou Jeruzalémští, pro množství lidu a dobytka u prostřed něho.'),
(1569165,54,38,2,5,'A já budu, praví Hospodin, jeho zdí ohnivou vůkol, a slávou budu u prostřed něho.'),
(1569166,54,38,2,6,'Nuže, nuže, utectež již z země půlnoční, praví Hospodin, poněvadž se čtyř stran světa volný průchod učinil jsem vám, praví Hospodin.'),
(1569167,54,38,2,7,'Nuže, Sione, kterýž přebýváš u dcery Babylonské, vydobuď se.'),
(1569168,54,38,2,8,'Nebo takto praví Hospodin zástupů: Po slávě poslal mne proti národům těm, kteříž zloupili vás; nebo kdož se dotýká vás, dotýká se zřítelnice oka mého.'),
(1569169,54,38,2,9,'Nebo aj, já zdvihnu ruku svou proti nim, a budou loupež služebníkům svým, i zvíte, že Hospodin zástupů poslal mne.'),
(1569170,54,38,2,10,'Prozpěvuj a vesel se, dcero Sionská; nebo aj, já přijdu a budu bydliti u prostřed tebe, praví Hospodin.'),
(1569171,54,38,2,11,'I připojí se národové mnozí k Hospodinu v ten den, a budou mým lidem, a budu bydliti u prostřed tebe, i zvíš, že Hospodin zástupů poslal mne k tobě.'),
(1569172,54,38,2,12,'Tehdy dědičně ujme Hospodin Judu, díl svůj, v zemi svaté, a vyvolí zase Jeruzalém.'),
(1569173,54,38,2,13,'Umlkniž všeliké tělo před oblíčejem Hospodinovým, neboť procítí z příbytku svatosti své.'),
(1569174,54,38,3,1,'Potom mi ukázal Jozue kněze nejvyššího, stojícího před andělem Hospodinovým, a satana stojícího po pravici jeho, aby se mu protivil.'),
(1569175,54,38,3,2,'Ale Hospodin řekl satanu: Potresciž tě Hospodin, satane, potresciž tě, pravím, Hospodin, kterýž vyvoluje Jeruzalém. Zdaliž tento není jako hlavně vychvácená z ohně?'),
(1569176,54,38,3,3,'Jozue pak oblečen byl v roucha zmazaná, a stál před andělem.'),
(1569177,54,38,3,4,'I odpověděl a řekl těm, kteříž stáli před ním, řka: Vezměte roucho to zmazané s něho. A řekl jemu: Pohleď, přenesl jsem s tebe nepravost tvou, a oblékl jsem tě v roucha proměnná.'),
(1569178,54,38,3,5,'Opět řekl: Nechť vstaví čepici pěknou na hlavu jeho. I vstavili čepici pěknou na hlavu jeho, a oblékli ho v roucha. Anděl pak Hospodinův tu stál.'),
(1569179,54,38,3,6,'A osvědčil anděl Hospodinův Jozue, řka:'),
(1569180,54,38,3,7,'Takto praví Hospodin zástupů: Jestliže po cestách mých choditi budeš, a jestliže stráž mou držeti budeš, budeš-li také souditi dům můj, a budeš-li ostříhati síní mých: dámť zajisté to, abys chodil mezi těmito přístojícími.'),
(1569181,54,38,3,8,'Slyš nyní, Jozue, kněže nejvyšší, ty i tovaryši tvoji, kteříž sedí před tebou: Ačkoli muži ti jsou za zázrak, aj, já však přivedu služebníka svého, Výstřelek.'),
(1569182,54,38,3,9,'Nebo aj, totoť jest ten kámen, kterýž kladu před Jozue, na kámen jeden sedm očí; aj, já vyřeži na něm řezbu, praví Hospodin zástupů, a odejmu nepravost té země jednoho dne.'),
(1569183,54,38,3,10,'V ten den, praví Hospodin zástupů, povoláte jeden každý bližního svého pod vinný kmen a pod fík.'),
(1569184,54,38,4,1,'Potom navrátil se anděl, kterýž mluvil se mnou, a zbudil mne jako muže, kterýž zbuzen bývá ze sna svého.'),
(1569185,54,38,4,2,'I řekl mi: Co vidíš? Jemuž jsem řekl:Vidím, že aj, svícen zlatý všecken, a olejný dčbán na vrchu jeho, a sedm lamp jeho na něm, a sedm nálevek k těm sedmi lampám, kteréž jsou na vrchu jeho.'),
(1569186,54,38,4,3,'A dvě olivy při něm, jedna po pravé straně dčbánu olejného, a druhá po levé straně jeho.'),
(1569187,54,38,4,4,'Tehdy odpověděl jsem a řekl jsem andělu tomu, kterýž mluvil ke mně, řka: Co ty věci jsou, pane můj?'),
(1569188,54,38,4,5,'A odpovídaje anděl, kterýž mluvil se mnou, řekl mi: Což nevíš, co ty věci jsou? I řekl jsem: Nevím, pane můj.'),
(1569189,54,38,4,6,'Tedy odpovídaje, mluvil ke mně, řka: Toto jest slovo Hospodinovo k Zorobábelovi, řkoucí: Ne silou, ani mocí, ale Duchem mým, praví Hospodin zástupů.'),
(1569190,54,38,4,7,'Co jsi ty, ó horo veliká, před Zorobábelem? Rovina. Nebo doloží nejvyšší kámen s hlučným prokřikováním: Milost, milost jemu.'),
(1569191,54,38,4,8,'I stalo se slovo Hospodinovo ke mně, řkoucí:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569192,54,38,4,9,'Ruce Zorobábelovy založily dům tento, a ruce jeho dokonají. I zvíš, že Hospodin zástupů poslal mne k vám.'),
(1569193,54,38,4,10,'Nebo kdož by pohrdal dnem malých začátků, poněvadž se veselí, hledíce na ten kámen, totiž na závaží v ruce Zorobábelově, těch sedm očí Hospodinových, procházejících všecku zemi?'),
(1569194,54,38,4,11,'Tedy odpovídaje jemu, řekl jsem? Co ty dvě olivy po pravé straně toho svícnu, i po levé straně jeho?'),
(1569195,54,38,4,12,'Opět odpovídaje jemu, řekl jsem: Co ty dvě olivky, kteréž jsou mezi dvěma trubicemi zlatými, kteréž vylévají z sebe zlato?'),
(1569196,54,38,4,13,'I mluvil ke mně, řka: Víš-liž, co ty věci jsou? I řekl jsem: Nevím, pane můj.'),
(1569197,54,38,4,14,'Tedy řekl: To jsou ty dvě olivy, kteréž jsou u Panovníka vší země.'),
(1569198,54,38,5,1,'Potom opět pozdvihna očí svých, uzřel jsem, a aj, kniha letěla.'),
(1569199,54,38,5,2,'I řekl mi: Co vidíš? Jemuž jsem řekl: Vidím knihu letící, jejíž dlouhost byla dvadcíti loktů a širokost desíti loktů.'),
(1569200,54,38,5,3,'Tedy řekl mi: Toto prokletí vyjde na širokost vší země. Nebo každý zloděj podlé něho jako i ona vyhlazen, a každý přisahající podlé něho jako i ona vyhlazen bude.'),
(1569201,54,38,5,4,'Vynesu je, praví Hospodin zástupů, aby došlo na dům zloděje, a na dům přisahajícího skrze jméno mé falešně; anobrž bude bydliti u prostřed domu jeho, a docela zkazí jej, i dříví jeho i kamení jeho.'),
(1569202,54,38,5,5,'Tedy vyšel anděl ten, kterýž mluvil se mnou, a řekl mi: Pozdvihni nyní očí svých a viz, co jest to, což pochází.'),
(1569203,54,38,5,6,'I řekl jsem: Co jest? Kterýž odpověděl: Toto jest efi pocházející. Řekl také: Toto jest oko její prohlédající všecku zemi.'),
(1569204,54,38,5,7,'A aj, plech tlustý olověný nesen byl, a přitom žena jedna, kteráž seděla u prostřed té efi.'),
(1569205,54,38,5,8,'I řekl: Toto jest ta bezbožnost. I uvrhl ji do prostřed té efi, uvrhl i ten plech olověný na vrch její.'),
(1569206,54,38,5,9,'A pozdvihna očí svých, uzřel jsem, a aj, dvě ženy vycházely, majíce vítr v křídlách svých. Měly pak křídla podobná křídlům čápím, a vyzdvihly tu efi mezi zemi a mezi nebe.'),
(1569207,54,38,5,10,'I řekl jsem andělu tomu, kterýž mluvil se mnou: Kam ony nesou tu efi?'),
(1569208,54,38,5,11,'Kterýž řekl mi: Aby sobě vystavěla dům v zemi Sinear, kdež by utvrzena byla a postavena na podstavku svém.'),
(1569209,54,38,6,1,'Potom opět pozdvihna očí svých, viděl jsem, a aj, čtyři vozové vycházeli z prostředku dvou hor, hory pak ty byly hory ocelivé.'),
(1569210,54,38,6,2,'V prvním voze byli koni ryzí, a v druhém voze byli koni vraní,'),
(1569211,54,38,6,3,'V voze pak třetím koni bílí, a v voze čtvrtém koni strakatí a hnědí.'),
(1569212,54,38,6,4,'Tedy odpovídaje, řekl jsem andělu, kterýž mluvil se mnou: Co tyto věci, pane můj?'),
(1569213,54,38,6,5,'I odpověděl anděl ten a řekl mi: To jsou čtyři větrové nebeští, vycházející odtud, kdež stáli před Panovníkem vší země.'),
(1569214,54,38,6,6,'Koni vraní zapřežení vycházejí do země půlnoční, a bílí vycházejí za nimi, strakatí pak vycházejí do země polední.'),
(1569215,54,38,6,7,'Hnědí také vyšedše, chtěli jíti, aby schodili zemi. Protož řekl: Jděte, schoďte zemi. I schodili zemi.'),
(1569216,54,38,6,8,'A povolav mne, mluvil ke mně, řka: Aj ti, kteříž vyšli do země půlnoční, spokojili ducha mého v zemi půlnoční.'),
(1569217,54,38,6,9,'I stalo se slovo Hospodinovo ke mně, řkoucí:'),
(1569218,54,38,6,10,'Vezmi od zajatých, od Cheldaje a od Tobiáše a od Jedaiáše, (a přijdeš ty téhož dne, a vejdeš do domu Joziáše syna Sofoniášova), kteříž jdou z Babylona,'),
(1569219,54,38,6,11,'Vezmi, pravím, stříbro a zlato, a udělej koruny, a vstav na hlavu Jozue syna Jozadakova, kněze nejvyššího.'),
(1569220,54,38,6,12,'A mluviti budeš k němu, řka: Takto praví Hospodin zástupů, řka: Aj muž, jehož jméno jest Výstřelek, kterýž z místa svého pučiti se bude, ten vystaví chrám Hospodinův.'),
(1569221,54,38,6,13,'Nebo ten má vystavěti chrám Hospodinův, a tentýž zase přinese slávu, a seděti a panovati bude na trůnu svém, a bude knězem na trůnu svém, a rada pokoje bude mezi nimi oběma.'),
(1569222,54,38,6,14,'Budou pak ty koruny Chelemovi, a Tobiášovi, a Jedaiášovi, a Chenovi synu Sofoniášovu na památku v chrámě Hospodinově.'),
(1569223,54,38,6,15,'Nebo dalecí přijdou, a budou stavěti chrám Hospodinův, i zvíte, že Hospodin zástupů poslal mne k vám. A to se stane, jestliže skutečně poslouchati budete hlasu Hospodina Boha svého.'),
(1569224,54,38,7,1,'Potom stalo se léta čtvrtého Daria krále, stalo se slovo Hospodinovo k Zachariášovi, čtvrtého dne měsíce devátého, kterýž jest Kislef,'),
(1569225,54,38,7,2,'Když poslal do domu Božího Sarezer a Regemmelech, i muži jeho, aby se kořili tváři Hospodinově,'),
(1569226,54,38,7,3,'A aby mluvili k kněžím, kteříž byli v domě Hospodina zástupů, i k prorokům, řkouce: Budeme-li plakati měsíce pátého, oddělujíce se, jako jsme činili již po mnoho let?'),
(1569227,54,38,7,4,'I stalo se slovo Hospodina zástupů ke mně, řkoucí:'),
(1569228,54,38,7,5,'Rci všemu lidu této země i kněžím takto: Když jste se postívali a kvílili, pátého a sedmého měsíce, a to po sedmdesáte let, zdaliž jste se opravdu mně, mně, pravím, postili?'),
(1569229,54,38,7,6,'A když jíte aneb pijete, zdaliž ne pro sebe jíte a ne pro sebe pijete?'),
(1569230,54,38,7,7,'Zdaliž tato nejsou slova, kteráž prohlásil Hospodin skrze proroky předešlé, když ještě Jeruzalém seděl bezpečně a užíval pokoje, i města jeho vůkol něho, a lid v straně polední i na rovinách bydlil?'),
(1569231,54,38,7,8,'I stalo se slovo Hospodinovo k Zachariášovi, řkoucí:'),
(1569232,54,38,7,9,'Takto mluvíval Hospodin zástupů, řka: Soud pravý vynášejte, a milosrdenství a lítosti dokazujte jeden každý k bližnímu svému.'),
(1569233,54,38,7,10,'A vdovy ani sirotka, příchozího ani chudého neutiskejte, a zlého žádný bližnímu svému neobmýšlejte v srdci svém.'),
(1569234,54,38,7,11,'Ale nechtěli pozorovati, a nastavili ramene urputného, a uši své obtížili, aby neslyšeli.'),
(1569235,54,38,7,12,'A srdce své učinili kámen přetvrdý, aby neslyšeli zákona toho a slov těch, kteráž posílal Hospodin zástupů Duchem svým skrze proroky předešlé. Pročež přišel hněv veliký od Hospodina zástupů.'),
(1569236,54,38,7,13,'Nebo stalo se, že jakož volajícího neslyšeli, tak když volali, neslyšel jsem, praví Hospodin zástupů.'),
(1569237,54,38,7,14,'A vichřicí rozptýlil jsem je mezi všecky ty národy, kterýchž neznali, a země tato spustla po nich, tak že nebylo žádného, kdo by tudy chodil, a tak přivedli zemi žádoucí na spuštění.'),
(1569238,54,38,8,1,'Opět stalo se slovo Hospodina zástupů, řkoucí:'),
(1569239,54,38,8,2,'Takto praví Hospodin zástupů: Horlil jsem pro Sion horlením velikým, nýbrž rozhněváním velikým horlil jsem pro něj.'),
(1569240,54,38,8,3,'Takto praví Hospodin: Navrátil jsem se k Sionu, a bydlím u prostřed Jeruzaléma, aby sloul Jeruzalém městem věrným, a hora Hospodina zástupů horou svatosti.'),
(1569241,54,38,8,4,'Takto praví Hospodin zástupů: Ještěť sedati budou starci i baby na ulicích Jeruzalémských, maje každý z nich hůl v ruce své pro sešlost věku.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569242,54,38,8,5,'Ulice také města plné budou pacholat a děvčat, hrajících na ulicích jeho.'),
(1569243,54,38,8,6,'Takto praví Hospodin zástupů: Zdali, že se to nepodobné zdá před očima ostatků lidu tohoto dnů těchto, také před očima mýma nepodobné bude? praví Hospodin zástupů.'),
(1569244,54,38,8,7,'Takto praví Hospodin zástupů: Aj, já vysvobozuji lid svůj z země východní, a z země na západ slunce,'),
(1569245,54,38,8,8,'A přivedu je zase. I budou bydliti u prostřed Jeruzaléma, a budou lidem mým, a já budu jejich Bohem v pravdě a v spravedlnosti.'),
(1569246,54,38,8,9,'Takto praví Hospodin zástupů: Posilňtež se ruce vaše, kteříž jste slyšeli těchto dnů slova tato z úst proroků, od toho dne, v němž založen jest dům Hospodina zástupů, že má chrám dostaven býti.'),
(1569247,54,38,8,10,'Nebo před těmito dny práce lidská, ani práce hovádek se nenahražovala, nýbrž ani vycházejícímu ani vcházejícímu nebylo pokoje pro nepřítele, nebo já spustil jsem všecky lidi jedny s druhými.'),
(1569248,54,38,8,11,'Nyní pak, ne jako ve dnech těch předešlých, činím ostatkům lidu tohoto, praví Hospodin zástupů.'),
(1569249,54,38,8,12,'Ale rozsívání máte pokojné, vinný kmen vydává ovoce své, a země vydává úrodu svou, nebesa také dávají rosu svou, a to všecko dávám v dědictví ostatkům lidu tohoto.'),
(1569250,54,38,8,13,'A tak stane se, že jakož jste byli zlořečením mezi pohany, ó dome Judský a dome Izraelský, tak zase vás chrániti budu, a budete požehnáním. Nebojtež se, posilňte se ruce vaše.'),
(1569251,54,38,8,14,'Nebo takto praví Hospodin zástupů: Jakož jsem byl myslil zle učiniti vám, když mne hněvali otcové vaši, praví Hospodin zástupů, aniž jsem litoval:'),
(1569252,54,38,8,15,'Tak obrátě se, myslím v těchto dnech dobře činiti Jeruzalému a domu Judskému. Nebojtež se.'),
(1569253,54,38,8,16,'Tyto pak věci jsou, kteréž činiti budete: Mluvte pravdu každý s bližním svým, pravý a pokojný soud vynášejte v branách svých.'),
(1569254,54,38,8,17,'Aniž kdo bližnímu svému zlého obmýšlej v srdci svém, též přísahy falešné nemilujte; nebo všecko to jest, čehož nenávidím, praví Hospodin.'),
(1569255,54,38,8,18,'I stalo se slovo Hospodina zástupů ke mně, řkoucí:'),
(1569256,54,38,8,19,'Takto praví Hospodin zástupů: Půst čtvrtého měsíce, a půst pátého, a půst sedmého, a půst desátého obrátí se domu Judskému v radost a veselí, i v slavnosti rozkošné, ale pravdu a pokoj milujte.'),
(1569257,54,38,8,20,'Takto praví Hospodin zástupů: Ještěť budou přicházeti národové a obyvatelé měst mnohých,'),
(1569258,54,38,8,21,'Přicházeti budou, pravím, obyvatelé jednoho k druhému, řkouce: Poďmež s ochotností kořiti se tváři Hospodinově, a hledati Hospodina zástupů. Půjdu i já.'),
(1569259,54,38,8,22,'A tak přijdou lidé mnozí a národové nesčíslní, aby hledali Hospodina zástupů v Jeruzalémě, a kořili se tváři Hospodinově.'),
(1569260,54,38,8,23,'Takto praví Hospodin zástupů: V těch dnech chopí se deset mužů ze všech jazyků těch národů, chopí se, pravím, podolka jednoho Žida, řkouce: Půjdeme s vámi; nebo slyšíme, že jest Bůh s vámi.'),
(1569261,54,38,9,1,'Břímě slova Hospodinova proti zemi, kteráž jest v vůkolí tvém, a Damašek bude odpočinutí jeho. Nebo k Hospodinu zřetel člověka i všech pokolení Izraelských.'),
(1569262,54,38,9,2,'Ano i do Emat dosáhne, do Týru i Sidonu, ačkoli jest moudrý velmi.'),
(1569263,54,38,9,3,'Vystavěltě sobě Týrus pevnost, a nashromáždil stříbra jako prachu, a ryzího zlata jako bláta na ulicích.'),
(1569264,54,38,9,4,'Aj, Pán vyžene jej, a vrazí do moře sílu jeho, i on od ohně sežrán bude.'),
(1569265,54,38,9,5,'Vida to Aškalon, báti se bude, i Gáza velikou bolest míti bude, též i Akaron, proto že jej zahanbilo očekávání jeho. I zahyne král z Gázy, a Aškalon neosedí.'),
(1569266,54,38,9,6,'A bude bydliti pankhart v Azotu, a tak vypléním pýchu Filistinských.'),
(1569267,54,38,9,7,'Když pak odejmu vraždu jednoho každého od úst jeho, a ohavnosti jeho od zubů jeho, připojen bude také i on Bohu našemu, aby byl jako vývoda v Judstvu, a Akaron jako Jebuzejský.'),
(1569268,54,38,9,8,'A položím se vojensky u domu svého pro vojsko a pro ty, kteříž tam i zase jdou; aniž půjde skrze ně více násilník, proto že se tak nyní vidí očím mým.'),
(1569269,54,38,9,9,'Plésej velice, dcerko Sionská, prokřikuj, dcerko Jeruzalémská. Aj, král tvůj přijde tobě spravedlivý a spasení plný, chudý a sedící na oslu, totiž na oslátku mladém.'),
(1569270,54,38,9,10,'Nebo vypléním vozy z Efraima a koně z Jeruzaléma, a vypléněna budou lučiště válečná; nadto rozhlásí pokoj národům, a panování jeho od moře až k moři, a od řeky až do končin země.'),
(1569271,54,38,9,11,'Anobrž ty, pro krev smlouvy své vypustil jsem vězně tvé z jámy, v níž není žádné vody.'),
(1569272,54,38,9,12,'Navraťež se k ohradě, ó vězňové v naději postavení. A tak v ten den, jakžť oznamuji, dvojnásobně nahradím tobě,'),
(1569273,54,38,9,13,'Když sobě napnu Judu a lučiště naplním Efraimem, a vzbudím syny tvé, ó Sione, proti synům tvým, ó Javane, a nastrojím tě jako meč udatného.'),
(1569274,54,38,9,14,'Nebo Hospodin proti nim se ukáže, a vynikne jako blesk střela jeho. Panovník, pravím, Hospodin trubou troubiti bude, a pobéře se s vichřicemi poledními.'),
(1569275,54,38,9,15,'Hospodin zástupů chrániti bude lidu svého, aby zmocníce se kamením z praku, jedli a pili, prokřikujíce jako od vína, a naplní jakož číši tak i rohy oltáře.'),
(1569276,54,38,9,16,'A tak je vysvobodí v ten den Hospodin Bůh jejich, jakožto stádce lid svůj, a vystaveno bude kamení pěkně tesané místo korouhví v zemi jeho.'),
(1569277,54,38,9,17,'Nebo aj, jaké blahoslavenství jeho, a jak veliká okrasa jeho! Obilé mládence a mest panny učiní mluvné.'),
(1569278,54,38,10,1,'Žádejte od Hospodina deště v čas příhodný, i způsobí Hospodin pršku, a dá vám déšť hojný, a každému bylinu na poli.'),
(1569279,54,38,10,2,'Nebo obrazové mluví marnost, a věšťci prorokují faleš, a sny marné mluví, marností potěšují. Protož šli jako stádo, ztrestáni jsou, proto že žádného nebylo pastýře.'),
(1569280,54,38,10,3,'Proti pastýřům takovým zažžen jest hněv můj, a kozly ty trestati budu, ale stádo své, dům Judský, navštíví Hospodin zástupů, a učiní je jako koně ozdobného k boji.'),
(1569281,54,38,10,4,'Od něho úhel, od něho hřeb, od něho lučiště válečné, od něho též pojde všeliký úředník.'),
(1569282,54,38,10,5,'A budou podobni rekům, pošlapávajíce do bláta na ulicích v boji, když bojovati budou; nebo Hospodin s nimi, a zahanbí ty, kteříž jedou na koních.'),
(1569283,54,38,10,6,'Posilním zajisté domu Judova, a dům Jozefův vysvobodím, a bezpečně je osadím. Nebo lítost mám nad nimi, i budou, jako bych jich nezahnal; nebo já jsem Hospodin Bůh jejich, a vyslyším je.'),
(1569284,54,38,10,7,'I budou Efraimští jako silný rek, a veseliti se bude srdce jejich jako od vína. I jejich synové vidouce to, rozveselí se, a zpléše srdce jejich v Hospodinu.'),
(1569285,54,38,10,8,'Šeptati jim budu, a tak je shromáždím; nebo je vykoupím, a rozmnoženi budou, jakož rozmnoženi byli.'),
(1569286,54,38,10,9,'Nadto rozseji je mezi národy, aby na místech dalekých rozpomínali se na mne, a živi jsouce s syny svými, navrátili se.'),
(1569287,54,38,10,10,'A tak je zase přivedu z země Egyptské, i z Assyrské shromáždím je, a do země Galád a k Libánu přivedu je, ale nepostačí jim.'),
(1569288,54,38,10,11,'Protož pro těsnost přejde přes moře, a prorazí na moři vlnobití, i vyschnou všecky hlubiny řeky, budeť snížena i pýcha Assyrie, a berla Egypta odjata bude.'),
(1569289,54,38,10,12,'A posilním jich v Hospodinu, aby ve jménu jeho ustavičně chodili, praví Hospodin.'),
(1569290,54,38,11,1,'Otevři, Libáne, vrata svá, ať zžíře oheň cedry tvé.'),
(1569291,54,38,11,2,'Kvěl jedle, nebo padl cedr, nebo znamenití vypléněni jsou; kvělte dubové Bázanští, nebo klesl les ohražený.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569292,54,38,11,3,'Hlas kvílení pastýřů, proto že popléněno důstojenství jejich; hlas řvání lvů, proto že popléněna pýcha Jordánu.'),
(1569293,54,38,11,4,'Takto praví Hospodin Bůh můj: Pas ovce tyto k zbití oddané,'),
(1569294,54,38,11,5,'Kteříž držitelé jejich mordují, aniž bývají obviňováni, a kdož je prodávají, říkají: Požehnaný Hospodin, že jsme zbohatli, a kteříž je pasou, nemají lítosti nad nimi.'),
(1569295,54,38,11,6,'Protož nebudu míti lítosti více nad obyvateli této země, praví Hospodin, ale aj, já uvedu ty lidi jednoho druhému v ruku, a v ruku krále jejich. I budou potírati zemi tuto, a nevytrhnu jí z ruky jejich.'),
(1569296,54,38,11,7,'Nebo jsem pásl ovce k zbití oddané, totiž vás chudé toho stáda, a vzav sobě dvě hole, nazval jsem jednu utěšením, a druhou jsem nazval svazujících. A pásl jsem, pravím, ty ovce,'),
(1569297,54,38,11,8,'A zahladil jsem tři pastýře měsíce jednoho, ale duše má stýskala sobě s nimi, proto že duše jejich nenáviděla mne.'),
(1569298,54,38,11,9,'Pročež řekl jsem: Nebudu vás pásti. Kteráž umříti má, nechť umře, a kteráž má vyhlazena býti, nechť jest vyhlazena, a jiné nechažť jedí maso jedna druhé.'),
(1569299,54,38,11,10,'Protož vzav hůl svou utěšení, posekal jsem ji, zrušiv smlouvu svou, kterouž jsem učinil se vším tím lidem.'),
(1569300,54,38,11,11,'A v ten den, když zrušena byla, právě poznali chudí toho stáda, kteříž na mne pozor měli, že řeč Hospodinova jest.'),
(1569301,54,38,11,12,'Nebo jsem řekl jim: Jestliže se vám vidí, dejte mzdu mou; pakli nic, nechte tak. I odvážili mzdu mou třidceti stříbrných.'),
(1569302,54,38,11,13,'I řekl mi Hospodin: Povrz je před hrnčíře. Znamenitá mzda, kterouž jsem tak draze šacován od nich. A tak vzav třidceti stříbrných, uvrhl jsem je v domě Hospodinově před hrnčíře.'),
(1569303,54,38,11,14,'Potom posekal jsem hůl svou druhou svazujících, zrušiv bratrství mezi Judou a mezi Izraelem.'),
(1569304,54,38,11,15,'I řekl mi Hospodin: Vezmi sobě ještě oruží pastýře bláznivého.'),
(1569305,54,38,11,16,'Nebo aj, já vzbudím pastýře v této zemi. Pobloudilých nebude navštěvovati, ani jehňátka hledati, ani což polámaného jest, léčiti, ani toho, což se zastavuje, nositi, ale maso toho, což tučnějšího jest, jísti bude, a kopyta jejich poláme.'),
(1569306,54,38,11,17,'Běda pastýři tomu ničemnému, kterýž opouští stádo. Meč na rameno jeho a na oko pravé jeho, rámě jeho docela uschne, a oko pravé jeho naprosto zatmí se.'),
(1569307,54,38,12,1,'Břímě slova Hospodinova příčinou Izraele. Praví Hospodin, kterýž roztáhl nebesa, a založil zemi, a sformoval ducha člověka, kterýž jest v něm:'),
(1569308,54,38,12,2,'Aj, já postavím Jeruzalém jako číši, kteráž ku potácení přivede všecky národy vůkol, kteříž budou proti Judovi v obležení, i proti Jeruzalému.'),
(1569309,54,38,12,3,'Nýbrž stane se v ten den, že položím Jeruzalém jako kámen přetěžký všechněm národům, jejž kdožkoli zdvihati budou, velmi se urazí, byť se pak shromáždili proti němu všickni národové země.'),
(1569310,54,38,12,4,'V ten den, praví Hospodin, raním všelikého koně strnutím, a jezdce jeho zblázněním, ale na dům Judský otevru oči své, a všecky koně národů raním slepotou.'),
(1569311,54,38,12,5,'I dějí vůdcové Judští v srdci svém: Mámeť sílu, i obyvatelé Jeruzalémští, v Hospodinu zástupů, Bohu svém.'),
(1569312,54,38,12,6,'V ten den učiním vůdce Judské podobné ohni zanícenému mezi dřívím, a pochodni hořící mezi snopy, i zžíře na pravo i na levo všecky národy vůkol, a ostojí Jeruzalém ještě na místě svém v Jeruzalémě.'),
(1569313,54,38,12,7,'Zachová Hospodin i stánky Judské prvé, aby se nevelebila ozdoba domu Davidova a ozdoba, přebývajících v Jeruzalémě nad Judu.'),
(1569314,54,38,12,8,'V ten den chrániti bude Hospodin obyvatelů Jeruzalémských, a bude nejnestatečnější z nich v ten den podobný Davidovi, a dům Davidův podobný bohům, podobný andělu Hospodinovu před nimi.'),
(1569315,54,38,12,9,'Nebo stane se v ten den, že shledám všecky národy, kteříž přitáhnou proti Jeruzalému, abych je zahladil.'),
(1569316,54,38,12,10,'A vyleji na dům Davidův a na obyvatele Jeruzalémské Ducha milosti a pokorných proseb. I obrátí zřetel ke mně, kteréhož jsou bodli, a kvíliti budou nad ním jako kvílením nad jednorozeným; hořce, pravím, plakati budou nad ním, jako hořce plačí nad prvorozeným.'),
(1569317,54,38,12,11,'V ten den bude veliké kvílení v Jeruzalémě, jako kvílení v Adadremmon na poli Mageddo.'),
(1569318,54,38,12,12,'Nebo kvíliti bude země, každá čeled obzvláštně, čeled domu Davidova obzvláštně, a ženy jejich obzvláštně, čeled domu Nátanova obzvláštně, a ženy jejich obzvláštně,'),
(1569319,54,38,12,13,'Čeled domu Léví obzvláštně, a ženy jejich obzvláštně, čeled Semei obzvláštně, a ženy jejich obzvláštně,'),
(1569320,54,38,12,14,'I všecky čeledi jiné, každá čeled obzvláštně, a ženy jejich obzvláštně.'),
(1569321,54,38,13,1,'V ten den bude studnice otevřená domu Davidovu a obyvatelům Jeruzalémským, k obmytí hřícha i nečistoty.'),
(1569322,54,38,13,2,'Stane se také v ten den, praví Hospodin zástupů, že vyhladím jména modl z země, tak že nebudou připomínány více, nýbrž také i ty proroky a ducha nečistoty vyprázdním z země.'),
(1569323,54,38,13,3,'I stane se, prorokoval-li by někdo více, že jemu řeknou otec jeho a matka jeho, kteříž jej zplodili: Nebudeš živ, proto že jsi lež mluvil ve jménu Hospodinovu. I probodnou jej otec jeho a matka jeho, kteříž jej zplodili, že prorokoval.'),
(1569324,54,38,13,4,'A tak stane se v ten den, že se budou styděti proroci ti, každý za vidění své, když by prorokovali, aniž oblekou sukně z srstí, aby klamali.'),
(1569325,54,38,13,5,'Ale dí každý: Nejsem já prorok. Muž, kterýž zemi dělá, jsem já; nebo mne učil tomu člověk od dětinství mého.'),
(1569326,54,38,13,6,'A dí-li kdo jemu: Jaké to máš rány na rukou svých? I odpoví: Jimiž jsem zbit v domě těch, kteříž mne milují.'),
(1569327,54,38,13,7,'Ó meči, prociť na pastýře mého, a na muže bližního mého, praví Hospodin zástupů. Bí pastýře, a rozprchnou se ovce, ale zase obrátím ruku svou k maličkým.'),
(1569328,54,38,13,8,'Nebo stane se po vší zemi této, praví Hospodin, že dvě částky vyhlazeny budou v ní a zemrou, a třetí v ní zanechána bude.'),
(1569329,54,38,13,9,'A i tu třetí uvedu do ohně, a přeženu je, jako se přehání stříbro, a zprubuji je, jako prubováno bývá zlato. Každý vzývati bude jméno mé, a já vyslyším jej. Řeknu: Lid můj jest: a on dí: Hospodin jest Bůh můj.'),
(1569330,54,38,14,1,'Aj, den Hospodinův přichází, a rozděleny budou kořisti tvé u prostřed tebe.'),
(1569331,54,38,14,2,'Nebo shromáždím všecky národy proti Jeruzalému k boji, i bude dobyto město, a domové zloupeni, a ženy zhanobeny budou. A když vyjde díl města v zajetí, ostatek lidu nebude vyhlazeno z města.'),
(1569332,54,38,14,3,'Nebo Hospodin vytáhna, bude bojovati proti těm národům, jakž bojuje v den potýkání.'),
(1569333,54,38,14,4,'I stanou nohy jeho v ten den na hoře Olivetské, kteráž jest naproti Jeruzalému od východu, a rozdvojí se hora Olivetská napoly k východu a k západu údolím velmi velikým, a odstoupí díl té hory na půlnoci, a díl její na poledne.'),
(1569334,54,38,14,5,'I budete utíkati před údolím hor; nebo dosáhne údolí hor až k Azal. Budete, pravím, utíkati, jako jste utíkali před země třesením za dnů Uziáše krále Judského, když přijde Hospodin Bůh můj, a všickni svatí s ním.'),
(1569335,54,38,14,6,'I stane se v ten den, že nebude světla drahého, ani tmy husté.'),
(1569336,54,38,14,7,'A tak bude den jeden, kterýž jest znám Hospodinu, aniž bude den, ani noc; a však stane se, že v čas večera bude světlo.'),
(1569337,54,38,14,8,'Stane se také v ten den, že vycházeti budou vody živé z Jeruzaléma, díl jich k moři východnímu, a díl jich k moři nejdalšímu. V létě i v zimě bude.'),
(1569338,54,38,14,9,'A bude Hospodin králem nade vší zemí; v ten den bude Hospodin jediný, a jméno jeho jedno.'),
(1569339,54,38,14,10,'A učiněna bude všecka tato země jako rovina od Gaba k Remmon na polední straně Jeruzalému, kterýž vyvýšen jsa, státi bude na místě svém, od brány Beniaminovy až k místu brány první, a až k bráně úhlové, a od věže Chananeel až k presu královskému.'),
(1569340,54,38,14,11,'A budou bydliti v něm, a nebude více v prokletí; město Jeruzalém zajisté bezpečně seděti bude.'),
(1569341,54,38,14,12,'Tato pak bude rána, kterouž raní Hospodin všecky národy, kteříž by bojovali proti Jeruzalému: Usuší tělo jednoho každého, stojícího na nohách svých, a oči jednoho každého usvadnou v děrách svých, a jazyk jednoho každého usvadne v ústech jejich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569342,54,38,14,13,'I stane se v ten den, že bude znepokojení Hospodinovo veliké mezi nimi, tak že uchopí jeden druhého ruku, a vztažena bude ruka jednoho na ruku druhého.'),
(1569343,54,38,14,14,'Také i ty, Judo, bojovati budeš v Jeruzalémě, a shromážděno bude zboží všech národů vůkol, zlato a stříbro, i roucha velmi mnoho.'),
(1569344,54,38,14,15,'A podobná bude rána koní, mezků, velbloudů a oslů i všech hovad, kteráž budou v tom ležení, podobná ráně té.'),
(1569345,54,38,14,16,'I stane se, že kdožkoli pozůstane ze všech národů, kteříž by přitáhli proti Jeruzalému, přicházeti budou z rok do roka klaněti se králi Hospodinu zástupů a slaviti slavnost stánků.'),
(1569346,54,38,14,17,'I stane se, kdo z čeledí země nebude přicházeti do Jeruzaléma klaněti se králi Hospodinu zástupů, že nebude na ně pršeti déšt.'),
(1569347,54,38,14,18,'A jestliže čeled Egyptská nevstoupí, ani přijde, jakkoli na ně nepršívá, přijde však táž rána, kterouž raní Hospodin národy, kteříž by nepřicházeli k slavení slavnosti stánků.'),
(1569348,54,38,14,19,'Tať bude pokuta pro hřích Egyptských a pokuta pro hřích všech národů, kteříž by nechodili k slavení slavnosti stánků.'),
(1569349,54,38,14,20,'V ten den bude na zvoncích koňských: Svatost Hospodinu; a bude hrnců v domě Hospodinově jako číší před oltářem.'),
(1569350,54,38,14,21,'Nýbrž bude všeliký hrnec v Jeruzalémě a v Judstvu svatost Hospodinu zástupů; a přicházejíce všickni, kteříž obětovati mají, budou je bráti a vařiti v nich. Aniž bude Kananejský více v domě Hospodina zástupů v ten den.'),
(1569351,54,39,1,1,'Břímě slova Hospodinova proti Izraelovi skrze Malachiáše.'),
(1569352,54,39,1,2,'Miluji vás, praví Hospodin, vy pak říkáte: V čem nás miluješ? Zdaliž Ezau nebyl bratr Jákobův? praví Hospodin. A však jsem miloval Jákoba.'),
(1569353,54,39,1,3,'Ezau pak měl jsem v nenávisti; protož zanechal jsem hor jeho pustých, a dědictví jeho drakům pouště.'),
(1569354,54,39,1,4,'Řekne-li Idumejská země: Ochuzeniť jsme, ale navrátíme se zase, a vystavíme místa pustá, takto praví Hospodin zástupů: Oni nechť stavějí, a já budu bořiti. I budou je nazývati pomezím bezbožnosti a lidem, na nějž hněviv bude Hospodin až na věky.'),
(1569355,54,39,1,5,'Což oči vaše uzří, a vy díte: Veleben buď Hospodin po pomezích Izraelských.'),
(1569356,54,39,1,6,'Syn ctí otce, a služebník pána svého. Protož jestližeť jsem já otec, kdež jest čest má? A jestliže jsem pán, kde jest bázeň má? Vám to mluví Hospodin zástupů, ó kněží, kteříž sobě zlehčujete jméno mé. A však říkáte: V čem zlehčujeme jméno tvé?'),
(1569357,54,39,1,7,'Kteříž přinášejíce na oltář můj obět poškvrněnou, říkáte: Čímž jsme tě poškvrnili? Tím, když říkáte: Stůl Hospodinův v pohrdání jest.'),
(1569358,54,39,1,8,'Nebo když přivodíte slepé k obětování, což to není nic zlého? A když přivodíte chromé aneb nemocné, což to není nic zlého? Daruj je medle knížeti svému, zalíbíš-li mu se tím, a přijme-li tvář tvou, praví Hospodin zástupů.'),
(1569359,54,39,1,9,'A protož nyní kořtež se tváři Boha silného, aby nám milost učinil. Ale když to z rukou vašich jest, přijme-liž kterého z vás oblíčej? praví Hospodin zástupů.'),
(1569360,54,39,1,10,'Anobrž kdo jest mezi vámi, aby zavřel dvéře, aneb zapálil na oltáři mém darmo? Nemámť v vás žádné líbosti, praví Hospodin zástupů, a oběti nepřijmu z ruky vaší.'),
(1569361,54,39,1,11,'Nebo od východu slunce až na západ jeho veliké bude jméno mé mezi národy, a na všelikém místě kadění přinášíno bude jménu mému, a obět čistá. Veliké zajisté jméno mé bude mezi národy, praví Hospodin zástupů,'),
(1569362,54,39,1,12,'Ačkoli vy ho poškvrňujete, když říkáte: Stůl Hospodinův v pohrdání jest, a což kladeno bývá na něj, že jest chaterný pokrm.'),
(1569363,54,39,1,13,'Říkáte také: Ach, větší práce, ješto byste to zdmýchnouti mohli, praví Hospodin zástupů. Nebo přinášíte to, což jest vydřeno, a chromé i nemocné, přinášejíce dar. To-liž mám přijímati z ruky vaší? praví Hospodin.'),
(1569364,54,39,1,14,'Anobrž zlořečený jest fortelný, kterýž maje v svém stádě samce, činí slib, a obětuje Pánu to, což jest churavého. Nebo král veliký já jsem, praví Hospodin zástupů, a jméno mé jest hrozné mezi národy.'),
(1569365,54,39,2,1,'A tak nyní k vám přikázání to, ó kněží.'),
(1569366,54,39,2,2,'Neuposlechnete-li a nesložíte-li v srdci, abyste dali slávu jménu mému, praví Hospodin zástupů, zajisté že pošli na vás zlořečenství, a zlořečiti budu požehnáním vašim. Anobrž již jsem zlořečil každému z nich, nebo jste nikoli nesložili toho v srdci.'),
(1569367,54,39,2,3,'Aj, já pokazím vám to, což nasejete, a vkydnu lejno na tváře vaše, lejno obětí vašich, tak že vás zachvátí k sobě.'),
(1569368,54,39,2,4,'Nebo víte, že jsem poslal k vám přikázaní to, aby byla stálá smlouva s Léví, praví Hospodin zástupů.'),
(1569369,54,39,2,5,'Smlouva má byla s ním života a pokoje, a dal jsem jemu to pro bázeň; nebo se bál mne, a pro jméno mé potřín byl.'),
(1569370,54,39,2,6,'Zákon pravdy byl v ústech jeho, a nepravost nebyla nalezena ve rtech jeho, v pokoji a upřímosti chodil se mnou, a mnohé odvrátil od nepravosti.'),
(1569371,54,39,2,7,'Nebo rtové kněze mají ostříhati umění, a na zákon doptávati se z úst jeho; posel zajisté Hospodina zástupů jest.'),
(1569372,54,39,2,8,'Vy pak sešli jste s cesty, byli jste příčinou mnohým, aby činili proti zákonu; zrušili jste smlouvu Levítskou, praví Hospodin zástupů.'),
(1569373,54,39,2,9,'Pročež i já také vydal jsem vás v potupu a v nevážnost všemu lidu, jakož vy v ničemž neostříháte cest mých, a přijímáte osoby v zákoně.'),
(1569374,54,39,2,10,'Zdaliž není jeden otec všech nás? Zdaliž Bůh jeden nestvořil nás? Proč nevěrně činiti máme jeden druhému a zlehčovati smlouvu otců našich?'),
(1569375,54,39,2,11,'Nevěrně činí Juda, a ohavnost se děje v Izraeli a v Jeruzalémě; nebo poškvrňuje Juda svatosti Hospodinovy, kterouž by milovati měl, pojímaje za manželku dceru boha jiného.'),
(1569376,54,39,2,12,'Vypléní Hospodin muže, kterýž to činí, z stánků Jákobových, bdícího i odpovídajícího, i obětujícího dar Hospodinu zástupů.'),
(1569377,54,39,2,13,'Již to podruhé činíte, že přikrýváte slzami oltář Hospodinův, pláčem a křikem, pročež nikoli nepatří již více k daru, aniž přijímá oběti vzácné z ruky vaší.'),
(1569378,54,39,2,14,'A však říkáte? Pro kterou příčinu? Proto že Hospodin jest svědkem mezi tebou a manželkou mladosti tvé, kteréž ty nevěrně činíš, ješto ona jest tovaryška tvá, a manželka smlouvy tvé.'),
(1569379,54,39,2,15,'Zdaliž neučinil jedno, ačkoli ještě více ducha měl? Proč pak jedno? Aby hledali semene Božího. Protož ostříhejte ducha svého, a manželce mladosti své nečiňte nevěrně.'),
(1569380,54,39,2,16,'Proto že v nenávisti má propouštění, praví Hospodin Bůh Izraelský, proto že takový přikrývá ukrutnost pláštěm jeho, praví Hospodin zástupů, protož ostříhejte ducha svého, abyste nečinili nevěrně.'),
(1569381,54,39,2,17,'Těžcí jste Hospodinu slovy svými, a však říkáte: V čem jsme těžcí? Když říkáte: Každý, kdož činí zlé, líbí se Hospodinu, a v těch on líbost má, aneb: Kde jest Bůh soudu?'),
(1569382,54,39,3,1,'Aj, já posílám anděla svého, kterýž připraví cestu před tváří mou. V tom hned přijde do chrámu svého Panovník, kteréhož vy hledáte, a anděl smlouvy, v němž vy líbost máte. Aj, přijdeť, praví Hospodin zástupů.'),
(1569383,54,39,3,2,'Ale kdo bude moci snésti den příchodu jeho? A kdo ostojí, když se on ukáže? Nebo on jest jako oheň rozpouštějící a jako mýdlo běličů.'),
(1569384,54,39,3,3,'I sedna, přeháněti bude a přečišťovati stříbro, a přečistí syny Léví, a vyčistí je jako zlato a jako stříbro. I budou Hospodinovi, obětujíce oběti v spravedlnosti.'),
(1569385,54,39,3,4,'I zachutná sobě Hospodin obět Judovu a Jeruzalémských, jako za dnů prvních, a jako za let starodávních.'),
(1569386,54,39,3,5,'K vám pak přikročím s pomstou, a budu rychlým svědkem proti kouzedlníkům, a proti cizoložníkům, a proti křivopřísežníkům, i proti těm, kteříž s útiskem zadržují mzdu nájemníka, vdově a sirotku, a příchozímu křivdu činíce, nebojí se mne, praví Hospodin zástupů.'),
(1569387,54,39,3,6,'Nebo já Hospodin neměním se, protož vy, synové Jákobovi, nevzali jste skončení.'),
(1569388,54,39,3,7,'Hned ode dnů otců vašich odešli jste od ustanovení mých, a neostříhali jste jich. Navraťtež se ke mně, a navrátím se k vám, praví Hospodin zástupů. Ale říkáte: V čem bychom se navrátiti měli?'),
(1569389,54,39,3,8,'Loupiti-liž má člověk Boha, že vy loupíte mne? A však říkáte: V čem tě loupíme? V desátcích a obětech.'),
(1569390,54,39,3,9,'Naprosto zlořečení jste, proto že mne loupíte, vy pokolení všecko.'),
(1569391,54,39,3,10,'Sneste všecky desátky do obilnice, aby byla potrava v domě mém, a zkuste mne nyní v tom, praví Hospodin zástupů, nezotvírám-liť vám průduchů nebeských, a nevyleji-li na vás požehnání, tak že neodoláte.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569392,54,39,3,11,'A přimluvím pro vás tomu, což zžírá, a nebude vám kaziti úrod zemských, aniž vám pochybí vinný kmen na poli, praví Hospodin zástupů.'),
(1569393,54,39,3,12,'I budou vás blažiti všickni národové; nebo vy budete zemí rozkošnou, praví Hospodin zástupů.'),
(1569394,54,39,3,13,'Rozmohlať se proti mně slova vaše, praví Hospodin, a však říkáte: Což jsme mluvili proti tobě?'),
(1569395,54,39,3,14,'Říkáte: Daremná jest věc sloužiti Bohu, a jaký zisk, budeme-li ostříhati nařízení jeho, a budeme-li choditi zasmušile, bojíce se Hospodina zástupů?'),
(1569396,54,39,3,15,'Nýbrž nyní blahoslavíme pyšné. Ti, kteříž páší bezbožnost, vzdělávají se, a pokoušející Boha vysvobozeni bývají.'),
(1569397,54,39,3,16,'Tehdy ti, kteříž se bojí Hospodina, tytýž mluvili jeden k druhému. I pozoroval Hospodin a slyšel, a psána jest kniha pamětná před ním pro ty, kteříž se bojí Hospodina, a myslí na jméno jeho.'),
(1569398,54,39,3,17,'Tiť budou, praví Hospodin zástupů, v den, kterýž já učiním, mým klínotem, a slituji se nad nimi, jako se slitovává otec nad synem svým, kterýž mu slouží.'),
(1569399,54,39,3,18,'Tehdy obrátíte se, a uzříte rozdíl mezi spravedlivým a bezbožným, mezi tím, kdo slouží Bohu, a tím, kdo jemu neslouží.'),
(1569400,54,39,4,1,'Nebo aj, den ten přichází hořící jako pec, v němž budou všickni pyšní, a všickni pášící bezbožnost jako strniště. I zažhne je ten den, kterýž přijíti má, praví Hospodin zástupů, tak že neostaví jim ani kořene ani ratolesti.'),
(1569401,54,39,4,2,'Vám pak, kteříž se bojíte jména mého, vzejde slunce spravedlnosti, a zdraví bude na paprslcích jeho. Tedy vycházeti budete,a porostete jako telata vykrmená.'),
(1569402,54,39,4,3,'A pošlapáte bezbožné, tak že budou jako popel pod nohami vašimi v den, kterýž já učiním, praví Hospodin zástupů.'),
(1569403,54,39,4,4,'Pamatujtež na zákon Mojžíše služebníka mého, jemuž jsem přikázal na Orébě přednesti všemu Izraeli ustanovení a soudy.'),
(1569404,54,39,4,5,'Aj, já pošli vám Eliáše proroka, prvé nežli přijde den Hospodinův veliký a hrozný,'),
(1569405,54,39,4,6,'Aby obrátil srdce otců k synům, a srdce synů k otcům jejich, abych přijda, neranil země prokletím.'),
(1569406,54,40,1,1,'Kniha (o) rodu Ježíše Krista syna Davidova, syna Abrahamova.'),
(1569407,54,40,1,2,'Abraham zplodil Izáka. Izák pak zplodil Jákoba. Jákob zplodil Judu a bratří jeho.'),
(1569408,54,40,1,3,'Judas pak zplodil Fáresa a Záru z Támar. Fáres pak zplodil Ezroma. Ezrom zplodil Arama.'),
(1569409,54,40,1,4,'Aram pak zplodil Aminadaba. Aminadab pak zplodil Názona. Názon zplodil Salmona.'),
(1569410,54,40,1,5,'Salmon zplodil Bóza z Raab. A Bóz zplodil Obéda z Rut. Obéd pak zplodil Jesse.'),
(1569411,54,40,1,6,'Jesse zplodil Davida krále. David pak král zplodil Šalomouna, z té, kteráž někdy byla žena Uriášova.'),
(1569412,54,40,1,7,'Šalomoun zplodil Roboáma. Roboám zplodil Abiáše. Abiáš zplodil Azu.'),
(1569413,54,40,1,8,'Aza zplodil Jozafata. Jozafat zplodil Joráma. Jorám zplodil Oziáše.'),
(1569414,54,40,1,9,'Oziáš pak zplodil Joátama. Joátam pak zplodil Achasa. Achas zplodil Ezechiáše.'),
(1569415,54,40,1,10,'Ezechiáš pak zplodil Manasesa. A Manases zplodil Amona. Amon pak zplodil Joziáše.'),
(1569416,54,40,1,11,'Joziáš pak zplodil Jekoniáše a bratří jeho v zajetí Babylonském.'),
(1569417,54,40,1,12,'A po zajetí Babylonském Jekoniáš zplodil Salatiele. Salatiel pak zplodil Zorobábele.'),
(1569418,54,40,1,13,'A Zorobábel zplodil Abiuda. Abiud pak zplodil Eliachima. Eliachim zplodil Azora.'),
(1569419,54,40,1,14,'Azor potom zplodil Sádocha. Sádoch zplodil Achima. Achim pak zplodil Eliuda.'),
(1569420,54,40,1,15,'Eliud zplodil Eleazara. Eleazar zplodil Mátana. Mátan zplodil Jákoba.'),
(1569421,54,40,1,16,'Jákob pak zplodil Jozefa, muže Marie, z nížto narodil se JEŽÍŠ, jenž slove Kristus.'),
(1569422,54,40,1,17,'A tak všech rodů od Abrahama až do Davida bylo rodů čtrnácte. A od Davida až do zajetí Babylonského rodů čtrnácte. A od zajetí Babylonského až do Krista rodů čtrnácte.'),
(1569423,54,40,1,18,'Jezukristovo pak narození takto se stalo: Když matka jeho Maria snoubena byla Jozefovi, prve než se sešli, nalezena jest těhotná z Ducha svatého.'),
(1569424,54,40,1,19,'Ale Jozef muž její spravedlivý jsa, a nechtěv jí v lehkost uvésti, chtěl ji tajně propustiti.'),
(1569425,54,40,1,20,'Když pak on o tom přemyšloval, aj, anděl Páně ve snách ukázal se jemu, řka: Jozefe synu Davidův, neboj se přijíti Marie manželky své; nebo což v ní jest počato, z Ducha svatého jest.'),
(1569426,54,40,1,21,'Porodíť pak syna, a nazůveš jméno jeho Ježíš; onť zajisté vysvobodí lid svůj od hříchů jejich.'),
(1569427,54,40,1,22,'Toto pak všecko stalo se, aby se naplnilo, což povědíno bylo ode Pána skrze proroka, řkoucího:'),
(1569428,54,40,1,23,'Aj, panna těhotná bude, a porodí syna, a nazůveš jméno jeho Emmanuel, jenž se vykládá: S námi Bůh.'),
(1569429,54,40,1,24,'Procítiv pak Jozef ze sna, učinil, jakož mu přikázal anděl Páně, a přijal manželku svou.'),
(1569430,54,40,1,25,'Ale nepoznal jí, až i porodila Syna svého prvorozeného, a nazvala jméno jeho Ježíš.'),
(1569431,54,40,2,1,'Když se pak narodil Ježíš v Betlémě Judově, za dnů Herodesa krále, aj, mudrci od východu slunce přijeli do Jeruzaléma,'),
(1569432,54,40,2,2,'Řkouce: Kde jest ten, kterýž se narodil Král Židovský? Nebo viděli jsme hvězdu jeho na východu slunce, a přijeli jsme klaněti se jemu.'),
(1569433,54,40,2,3,'To uslyšev Herodes král, zarmoutil se i všecken Jeruzalém s ním.'),
(1569434,54,40,2,4,'A svolav všecky přední kněží a učitele lidu, tázal se jich, kde by se Kristus měl naroditi.'),
(1569435,54,40,2,5,'Oni pak řekli jemu: V Betlémě Judově. Nebo tak jest psáno skrze proroka:'),
(1569436,54,40,2,6,'A ty Betléme, země Judská, nikoli nejsi nejmenší mezi knížaty Judskými; neboť z tebe vyjde Vývoda, kterýž pásti bude lid můj Izraelský.'),
(1569437,54,40,2,7,'Tedy Herodes tajně povolav mudrců, pilně se jich ptal, kterého by se jim času hvězda ukázala.'),
(1569438,54,40,2,8,'A když je propouštěl do Betléma, řekl: Jdouce, ptejte se pilně na to dítě, a když naleznete, zvěstujtež mi, ať i já přijda, pokloním se jemu.'),
(1569439,54,40,2,9,'Oni pak vyslyševše krále, jeli. A aj, hvězda, kterouž byli viděli na východu slunce, předcházela je, až i přišedši, stála nad domem, kdež bylo dítě.'),
(1569440,54,40,2,10,'A uzřevše hvězdu, zradovali se radostí velmi velikou.'),
(1569441,54,40,2,11,'I všedše do domu, nalezli dítě s Marijí matkou jeho, a padše, klaněli se jemu; a otevřevše poklady své, obětovali jemu dary, zlato a kadidlo a mirru.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569442,54,40,2,12,'A od Boha napomenuti jsouce ve snách, aby se nenavraceli k Herodesovi, jinou cestou navrátili se do krajiny své.'),
(1569443,54,40,2,13,'Když pak oni odjeli, aj, anděl Páně ukázal se Jozefovi ve snách, řka: Vstana, vezmi dítě i matku jeho, a utec do Egypta, a buď tam, dokavadž nepovím tobě; neboť bude Herodes hledati dítě, aby je zahubil.'),
(1569444,54,40,2,14,'Kterýžto vstav hned v noci, vzal dítě i matku jeho, a odšel do Egypta.'),
(1569445,54,40,2,15,'A byl tam až do smrti Herodesovy, aby se naplnilo povědění Páně skrze proroka, řkoucího: Z Egypta povolal jsem Syna svého.'),
(1569446,54,40,2,16,'Tehdy Herodes uzřev, že by oklamán byl od mudrců, rozhněval se náramně, a poslav služebníky své, zmordoval všecky dítky, kteréž byly v Betlémě i ve všech končinách jeho, od dvouletých a níže, podle času, na kterýž se byl pilně vyptal od mudrců.'),
(1569447,54,40,2,17,'Tehdy naplněno jest to povědění Jeremiáše proroka, řkoucího:'),
(1569448,54,40,2,18,'Hlas v Ráma slyšán jest, naříkání a pláč a kvílení mnohé; Ráchel plačící synů svých, a nedala se potěšiti, protože jich není.'),
(1569449,54,40,2,19,'Když pak umřel Herodes, aj, anděl Páně ukázal se Jozefovi ve snách v Egyptě,'),
(1569450,54,40,2,20,'Řka: Vstana, vezmi dítě i matku jeho, a jdiž do země Izraelské; neboť jsou zemřeli ti, jenž hledali bezživotí dítěte.'),
(1569451,54,40,2,21,'Kterýžto vstav, vzal dítě i matku jeho, a přišel do země Izraelské.'),
(1569452,54,40,2,22,'A uslyšev, že by Archelaus kraloval v Judstvu místo Herodesa otce svého, obával se tam jíti; a napomenut jsa od Boha ve snách, obrátil se do krajin Galilejských.'),
(1569453,54,40,2,23,'A přišed, bydlil v městě, jenž slove Nazarét, aby se naplnilo, což povědíno bylo skrze proroky, že Nazaretský slouti bude.'),
(1569454,54,40,3,1,'V těch pak dnech přišel Jan Křtitel, káže na poušti Judské,'),
(1569455,54,40,3,2,'A řka: Pokání čiňte, nebo přiblížilo se království nebeské.'),
(1569456,54,40,3,3,'Totoť jest zajisté ten Předchůdce předpověděný od Izaiáše proroka, řkoucího: Hlas volajícího na poušti: Připravujte cestu Páně, přímé čiňte stezky jeho.'),
(1569457,54,40,3,4,'Měl pak Jan roucho z srstí velbloudových a pás kožený okolo bedr svých, a pokrm jeho byl kobylky a med lesní.'),
(1569458,54,40,3,5,'Tedy vycházeli k němu z Jeruzaléma a ze všeho Judstva, i ze vší krajiny ležící při Jordánu,'),
(1569459,54,40,3,6,'A křtěni byli od něho v Jordáně, vyznávajíce hříchy své.'),
(1569460,54,40,3,7,'Uzřev pak mnohé z farizeů a z saduceů, že jdou k jeho křtu, řekl jim: Pokolení ještěrčí, i kdo vám ukázal, kterak byste utéci měli budoucího hněvu?'),
(1569461,54,40,3,8,'Protož čiňte ovoce hodné pokání.'),
(1569462,54,40,3,9,'A nedomnívejte se, že můžete říkati sami u sebe: Otce máme Abrahama. Neboť pravím vám, že by mohl Bůh z kamení tohoto vzbuditi syny Abrahamovi.'),
(1569463,54,40,3,10,'A jižť jest i sekera k kořenu stromů přiložena. Každý zajisté strom, kterýž nenese ovoce dobrého, vyťat a na oheň uvržen bývá.'),
(1569464,54,40,3,11,'Já křtím vás vodou ku pokání, ten pak, kterýž po mně přichází, jestiť mocnější nežli já, jehožto nejsem hoden obuvi nositi. Onť vás křtíti bude Duchem svatým a ohněm.'),
(1569465,54,40,3,12,'Jehožto věječka v ruce jeho, a vyčistíť humno své, a shromáždí pšenici svou do obilnice, ale plevy páliti bude ohněm neuhasitelným.'),
(1569466,54,40,3,13,'Tehdy přišel Ježíš od Galilee k Jordánu k Janovi, aby také pokřtěn byl od něho.'),
(1569467,54,40,3,14,'Ale Jan zbraňoval mu, řka: Mně jest potřebí, abych od tebe pokřtěn byl, a ty pak jdeš ke mně?'),
(1569468,54,40,3,15,'A odpovídaje Ježíš, dí jemu: Dopusť tak; neboť tak sluší na nás, abychom plnili všelikou spravedlnost. Tedy dopustil jemu.'),
(1569469,54,40,3,16,'A pokřtěn jsa Ježíš, vystoupil ihned z vody; a aj, otevřína jsou mu nebesa, a viděl Ducha Božího, sstupujícího jako holubici a přicházejícího na něj.'),
(1569470,54,40,3,17,'A aj, zavzněl hlas s nebe řkoucí: Tentoť jest ten můj milý Syn, v němž mi se dobře zalíbilo.'),
(1569471,54,40,4,1,'Tehdy Ježíš veden jest na poušť od Ducha, aby pokoušín byl od ďábla.'),
(1569472,54,40,4,2,'A postiv se čtyřidceti dnů a čtyřidceti nocí, potom zlačněl.'),
(1569473,54,40,4,3,'A přistoupiv k němu pokušitel, řekl: Jsi-li Syn Boží, rciž, ať kamení toto chlebové jsou.'),
(1569474,54,40,4,4,'On pak odpovídaje, řekl: Psánoť jest: Ne samým chlebem živ bude člověk, ale každým slovem vycházejícím skrze ústa Boží.'),
(1569475,54,40,4,5,'Tedy pojal jej ďábel do svatého města a postavil ho na vrchu chrámu.'),
(1569476,54,40,4,6,'A řekl mu: Jsi-li Syn Boží, spustiž se dolů; nebo psánoť jest, že andělům svým přikázal o tobě, a na ruce uchopí tebe, abys někde o kámen nohy své neurazil.'),
(1569477,54,40,4,7,'I řekl mu Ježíš: Zase psáno jest: Nebudeš pokoušeti Pána Boha svého.'),
(1569478,54,40,4,8,'Opět pojal ho ďábel na horu vysokou velmi, a ukázal mu všecka království světa i slávu jejich, a řekl jemu:'),
(1569479,54,40,4,9,'Toto všecko tobě dám, jestliže padna, budeš mi se klaněti.'),
(1569480,54,40,4,10,'Tedy dí mu Ježíš: Odejdiž, satane; neboť jest psáno: Pánu Bohu svému klaněti se budeš a jemu samému sloužiti budeš.'),
(1569481,54,40,4,11,'Tedy opustil ho ďábel, a aj, andělé přistoupili a sloužili jemu.'),
(1569482,54,40,4,12,'A když uslyšel Ježíš, že by Jan vsazen byl do žaláře, odšel do Galilee.'),
(1569483,54,40,4,13,'A opustiv Nazarét, přišed, bydlil v Kafarnaum za mořem, v krajinách Zabulon a Neftalím,'),
(1569484,54,40,4,14,'Aby se naplnilo povědění skrze Izaiáše proroka, řkoucího:'),
(1569485,54,40,4,15,'Země Zabulon a Neftalím při moři za Jordánem, Galilea pohanská,'),
(1569486,54,40,4,16,'Lid, kterýž bydlil v temnostech, viděl světlo veliké, a sedícím v krajině a stínu smrti, světlo vzešlo jim.'),
(1569487,54,40,4,17,'Od toho času počal Ježíš kázati a praviti: Pokání čiňte; neboť se přiblížilo království nebeské.'),
(1569488,54,40,4,18,'A chodě Ježíš podle moře Galilejského, uzřel dva bratry, Šimona, kterýž slove Petr, a Ondřeje bratra jeho, ani pouštějí sít do moře, (nebo byli rybáři.)'),
(1569489,54,40,4,19,'I dí jim: Pojďte za mnou, a učiním vás rybáře lidí.'),
(1569490,54,40,4,20,'A oni hned opustivše síti, šli za ním.'),
(1569491,54,40,4,21,'A poodšed odtud, uzřel jiné dva bratry, Jakuba syna Zebedeova, a Jana bratra jeho, na lodí s Zebedeem otcem jejich, ani tvrdí síti své. I povolal jich.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569492,54,40,4,22,'A oni hned opustivše lodí a otce svého, šli za ním.'),
(1569493,54,40,4,23,'I procházel Ježíš všecku Galilei, uče v shromážděních jejich a káže evangelium království a uzdravuje všelikou nemoc i všeliký neduh v lidu.'),
(1569494,54,40,4,24,'A rozešla se o něm pověst po vší Syrii. I přivedli k němu všecky nemocné, rozličnými neduhy a trápeními poražené, i ďábelníky, i náměsičníky, i šlakem poražené; a uzdravoval je.'),
(1569495,54,40,4,25,'I šli za ním zástupové mnozí z Galilee a z krajiny Desíti měst, i z Jeruzaléma i z Judstva i z Zajordání.'),
(1569496,54,40,5,1,'Vida pak Ježíš zástupy, vstoupil na horu; a když se posadil, přistoupili k němu učedlníci jeho.'),
(1569497,54,40,5,2,'I otevřev ústa svá, učil je, řka:'),
(1569498,54,40,5,3,'Blahoslavení chudí duchem, nebo jejich jest království nebeské.'),
(1569499,54,40,5,4,'Blahoslavení lkající, nebo oni potěšeni budou.'),
(1569500,54,40,5,5,'Blahoslavení tiší, nebo oni dědictví obdrží na zemi.'),
(1569501,54,40,5,6,'Blahoslavení, kteříž lačnějí a žíznějí spravedlnosti, nebo oni nasyceni budou.'),
(1569502,54,40,5,7,'Blahoslavení milosrdní, nebo oni milosrdenství důjdou.'),
(1569503,54,40,5,8,'Blahoslavení čistého srdce, nebo oni Boha viděti budou.'),
(1569504,54,40,5,9,'Blahoslavení pokojní, nebo oni synové Boží slouti budou.'),
(1569505,54,40,5,10,'Blahoslavení, kteříž protivenství trpí pro spravedlnost, neb jejich jest království nebeské.'),
(1569506,54,40,5,11,'Blahoslavení jste, když vám zlořečiti budou lidé a protivenství činiti, a mluviti všecko zlé o vás, lhouce, pro mne.'),
(1569507,54,40,5,12,'Radujte se a veselte se, nebo odplata vaše hojná jest v nebesích. Takť zajisté protivili se prorokům, kteříž byli před vámi.'),
(1569508,54,40,5,13,'Vy jste sůl země. Jestliže sůl zmařena bude, čím bude osolena? K ničemuž se nehodí více, než aby byla ven vyvržena a od lidí potlačena.'),
(1569509,54,40,5,14,'Vy jste světlo světa. Nemůžeť město na hoře ležící skryto býti.'),
(1569510,54,40,5,15,'Aniž rozsvěcují svíce a stavějí ji pod kbelec, ale na svícen; i svítí všechněm, kteříž v domu jsou.'),
(1569511,54,40,5,16,'Tak svěť světlo vaše před lidmi, ať vidí skutky vaše dobré, a slaví Otce vašeho, jenž jest v nebesích.'),
(1569512,54,40,5,17,'Nedomnívejte se, že bych přišel rušiti Zákon anebo Proroky. Nepřišelť jsem rušiti, ale naplniti.'),
(1569513,54,40,5,18,'Amen zajisté pravím vám: Dokudž nepomine nebe i země, jediná literka aneb jediný puňktík nepomine z Zákona, až se všecky věci stanou.'),
(1569514,54,40,5,19,'Protož zrušil-li by kdo jedno z přikázání těchto nejmenších a učil by tak lidi, nejmenší slouti bude v království nebeském. Kdož by pak koli činil i jiné učil, ten veliký slouti bude v království nebeském.'),
(1569515,54,40,5,20,'Nebo pravím vám: Nebude-liť hojnější spravedlivost vaše nežli zákoníků a farizeů, nikoli nevejdete do království nebeského.'),
(1569516,54,40,5,21,'Slyšeli jste, že řečeno jest od starých: Nezabiješ. Pakli by kdo zabil, povinen bude státi k soudu.'),
(1569517,54,40,5,22,'Ale jáť pravím vám: Že každý, kdož se hněvá na bratra svého bez příčiny, povinen k soudu státi. Kdož by pak řekl bratru svému: Rácha, povinen bude před radou státi; a kdož by řekl: Blázne, povinen bude pekelný oheň trpěti.'),
(1569518,54,40,5,23,'Protož obětoval-li bys dar svůj na oltář, a tu bys se rozpomenul, že bratr tvůj má něco proti tobě,'),
(1569519,54,40,5,24,'Nechejž tu daru svého před oltářem a jdi, prve smiř se s bratrem svým, a potom přijda, obětuj dar svůj.'),
(1569520,54,40,5,25,'Vejdi v dobrou vůli s protivníkem svým rychle, dokudž jsi s ním na cestě, ať by snad nedal tebe protivník tvůj soudci, a soudce dal by tě služebníku, a byl bys uvržen do žaláře.'),
(1569521,54,40,5,26,'Amen pravím tobě: Nevyjdeš odtud nikoli, dokudž i toho posledního haléře nenavrátíš.'),
(1569522,54,40,5,27,'Slyšeli jste, že řečeno jest od starých: Nezcizoložíš.'),
(1569523,54,40,5,28,'Ale jáť pravím vám: Že každý, kdož by pohleděl na ženu ku požádání jí, již zcizoložil s ní v srdci svém.'),
(1569524,54,40,5,29,'Jestliže pak oko tvé pravé horší tě, vylupiž je a vrz od sebe; nebť jest užitečněji tobě, aby raději zahynul jeden úd tvůj, nežli by celé tělo tvé uvrženo bylo do ohně pekelného.'),
(1569525,54,40,5,30,'A pakli ruka tvá pravá horší tě, utniž ji a vrz od sebe; nebo užitečněji jest tobě, aby zahynul raději jeden úd tvůj, nežli by všecko tělo tvé uvrženo bylo do pekelného ohně.'),
(1569526,54,40,5,31,'Též řečeno jest: Kdož by koli propustil manželku svou, aby jí dal lístek rozloučení.'),
(1569527,54,40,5,32,'Jáť pak pravím vám: Že kdožkoli propustil by manželku svou, kromě příčiny cizoložstva, uvodí ji v cizoložstvo, a kdož propuštěnou pojme, cizoloží.'),
(1569528,54,40,5,33,'Opět slyšeli jste, že řečeno jest od starých: Nebudeš křivě přisahati, ale splníš Pánu přísahy své.'),
(1569529,54,40,5,34,'Ale jáť pravím vám: Abyste nepřisahali všelijak, ani skrze nebe, nebo stolice Boží jest,'),
(1569530,54,40,5,35,'Ani skrze zemi, nebo podnož jeho jest, ani skrze Jeruzalém, nebo město velikého Krále jest.'),
(1569531,54,40,5,36,'Ani skrze hlavu svou budeš přisahati, nebo nemůžeš jednoho vlasu učiniti bílého aneb černého.'),
(1569532,54,40,5,37,'Ale buď řeč vaše: Jistě, jistě; nikoli, nikoli. Což pak nad to více jest, to od toho zlého jest.'),
(1569533,54,40,5,38,'Slyšeli jste, že řečeno jest: Oko za oko, a zub za zub.'),
(1569534,54,40,5,39,'Jáť pak pravím vám: Abyste neodpírali zlému. Ale udeří-li tě kdo v pravé líce tvé, nasaď jemu i druhého.'),
(1569535,54,40,5,40,'A tomu, kdož se s tebou chce souditi a sukni tvou vzíti, nech mu i pláště.'),
(1569536,54,40,5,41,'A nutil-li by tě kdo jíti s sebou míli jednu, jdi s ním dvě.'),
(1569537,54,40,5,42,'A prosícímu tebe dej, a od toho, kdo by chtěl vypůjčiti od tebe, neodvracuj se.'),
(1569538,54,40,5,43,'Slyšeli jste, že řečeno jest: Milovati budeš bližního svého, a nenáviděti budeš nepřítele svého.'),
(1569539,54,40,5,44,'Ale jáť vám pravím: Milujte nepřátely vaše, dobrořečte těm, kteříž vás proklínají, a dobře čiňte nenávidícím vás, a modlte se za nepřátely a protivníky vaše,'),
(1569540,54,40,5,45,'Abyste byli synové Otce vašeho, jenž jest v nebesích; ješto slunci svému velí vzchoditi na dobré i na zlé, a déšť dává na spravedlivé i na nespravedlivé.'),
(1569541,54,40,5,46,'Nebo milujete-li ty, jenž vás milují, jakou odplatu míti budete? Zdaliž i publikáni téhož nečiní?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569542,54,40,5,47,'A budete-li pozdravovati toliko bratří svých, což více nad jiné činíte? Však i publikáni to činí.'),
(1569543,54,40,5,48,'Buďtež vy tedy dokonalí, jako i Otec váš nebeský dokonalý jest.'),
(1569544,54,40,6,1,'Pilně se varujte, abyste almužny vaší nedávali před lidmi, proto abyste byli vidíni od nich, jinak nebudete míti odplaty u Otce vašeho, jenž jest v nebesích.'),
(1569545,54,40,6,2,'Protož když dáváš almužnu, netrub před sebou, jako pokrytci činí v školách a na ulicech, aby chváleni byli od lidí. Amen pravím vám, majíť odplatu svou.'),
(1569546,54,40,6,3,'Ale ty když dáváš almužnu, tak čiň, ať neví levice tvá, co činí pravice tvá,'),
(1569547,54,40,6,4,'Aby almužna tvá byla v skrytě, a Otec tvůj, kterýž vidí v skrytě, odplatí tobě zjevně.'),
(1569548,54,40,6,5,'A když bys se chtěl modliti, nebývejž jako pokrytci, kteříž obyčej mají, v školách a na úhlech rynku stojíce, modliti se, aby byli vidíni od lidí. Amen pravím vám, žeť mají odplatu svou.'),
(1569549,54,40,6,6,'Ale ty když bys se modliti chtěl, vejdi do pokojíka svého, a zavra dveře své, modliž se Otci svému, jenž jest v skrytě, a Otec tvůj, kterýž vidí v skrytě, odplatí tobě zjevně.'),
(1569550,54,40,6,7,'Modléce se pak, nebuďtež marnomluvní jako pohané; nebo se domnívají, že mnohomluvností svou to způsobí, aby byli uslyšáni.'),
(1569551,54,40,6,8,'Nepřirovnávejtež se tedy jim, neboť ví Otec váš, čeho jest vám potřebí, prve nežli byste vy ho prosili.'),
(1569552,54,40,6,9,'A protož vy takto se modlte: Otče náš, jenž jsi v nebesích, posvěť se jméno tvé.'),
(1569553,54,40,6,10,'Přijď království tvé. Buď vůle tvá jako v nebi tak i na zemi.'),
(1569554,54,40,6,11,'Chléb náš vezdejší dej nám dnes.'),
(1569555,54,40,6,12,'A odpusť nám viny naše, jakož i my odpouštíme vinníkům našim.'),
(1569556,54,40,6,13,'I neuvoď nás v pokušení, ale zbav nás od zlého. Nebo tvé jest království, i moc, i sláva, na věky, Amen.'),
(1569557,54,40,6,14,'Nebo budete-li odpouštěti lidem viny jejich, odpustíť i vám nebeský Otec váš.'),
(1569558,54,40,6,15,'Jestliže pak neodpustíte lidem vin jejich, aniž Otec váš odpustí vám hříchů vašich.'),
(1569559,54,40,6,16,'Když byste se pak postili, nebývejtež jako pokrytci zasmušilí; neboť pošmuřují tváří svých, aby vědomé bylo lidem, že se postí. Amen pravím vám, vzaliť jsou odplatu svou.'),
(1569560,54,40,6,17,'Ty pak, když se postíš, pomaž hlavy své a tvář svou umej,'),
(1569561,54,40,6,18,'Aby nebylo zjevné lidem, že se postíš, ale Otci tvému, kterýž jest v skrytě. A Otec tvůj, kterýž vidí v skrytosti, odplatí tobě zjevně.'),
(1569562,54,40,6,19,'Neskládejte sobě pokladů na zemi, kdežto mol a rez kazí, a kdež zloději vykopávají a kradou.'),
(1569563,54,40,6,20,'Ale skládejte sobě poklady v nebi, kdežto ani mol ani rez kazí, a kdežto zloději nevykopávají ani kradou.'),
(1569564,54,40,6,21,'Nebo kdežť jest poklad váš, tuť jest i srdce vaše.'),
(1569565,54,40,6,22,'Svíce těla jestiť oko; jestliže oko tvé sprostné bylo by, všecko tělo tvé světlé bude.'),
(1569566,54,40,6,23,'Pakliť by oko tvé bylo nešlechetné, všecko tělo tvé tmavé bude. Protož jestliže světlo, kteréž jest v tobě, jest tma, co pak sama tma, jaká bude?'),
(1569567,54,40,6,24,'Žádný nemůže dvěma pánům sloužiti. Nebo zajisté jednoho nenáviděti bude, a druhého milovati, aneb jednoho přídržeti se bude, a druhým pohrdne. Nemůžte Bohu sloužiti i mamoně.'),
(1569568,54,40,6,25,'Protož pravím vám: Nepečujte o život váš, co byste jedli a co pili, ani o tělo vaše, čím byste je odívali. Zdaliž není život více nežli pokrm, a tělo více nežli oděv?'),
(1569569,54,40,6,26,'Hleďte na ptactvo nebeské, žeť nesejí ani žnou, ani shromažďují do stodol, avšak Otec váš nebeský krmí je. I zdaliž vy jich mnohem nepřevyšujete?'),
(1569570,54,40,6,27,'A kdo z vás pečlivě mysle, může přidati ku postavě své loket jeden?'),
(1569571,54,40,6,28,'A o oděv proč pečujete? Poučte se na kvítí polním, kterak roste, nepracuje ani přede.'),
(1569572,54,40,6,29,'A aj, pravím vám, že ani Šalomoun ve vší slávě své tak odín nebyl, jako jedno z nich.'),
(1569573,54,40,6,30,'Poněvadž tedy trávu polní, ješto dnes jest, a zítra do peci bývá vložena, Bůh tak odívá, i zdaliž mnohem více vám toho nečiní, ó malé víry?'),
(1569574,54,40,6,31,'Nepečujtež tedy, říkajíce: Co budeme jísti? anebo: Co budeme píti? anebo: Čím se budeme odívati?'),
(1569575,54,40,6,32,'Nebo toho všeho pohané hledají. Víť zajisté Otec váš nebeský, že toho všeho potřebujete.'),
(1569576,54,40,6,33,'Ale hledejte vy nejprv království Božího a spravedlnosti jeho, a toto vše bude vám přidáno.'),
(1569577,54,40,6,34,'Protož nepečujte o zítřejší den, nebo zítřejší den pečovati bude o své věci. Dostiť má den na svém trápení.'),
(1569578,54,40,7,1,'Nesuďtež, abyste nebyli souzeni.'),
(1569579,54,40,7,2,'Nebo jakým soudem soudíte, takovýmž budete souzeni, a jakouž měrou měříte, takovouž bude vám zase odměřeno.'),
(1569580,54,40,7,3,'Kterakž pak vidíš mrvu v oku bratra svého, a v oku svém břevna necítíš?'),
(1569581,54,40,7,4,'Aneb kterak díš bratru svému: Nech, ať vyvrhu mrvu z oka tvého, a aj, břevno jest v oku tvém?'),
(1569582,54,40,7,5,'Pokrytče, vyvrz nejprv břevno z oka svého, a tehdy prohlédneš, abys vyňal mrvu z oka bratra tvého.'),
(1569583,54,40,7,6,'Nedávejte svatého psům, aniž mecte perel svých před svině, ať by snad nepotlačily jich nohama svýma, a psi obrátíce se, aby neroztrhaly vás.'),
(1569584,54,40,7,7,'Proste, a dánoť bude vám; hledejte, a naleznete; tlucte, a bude vám otevříno.'),
(1569585,54,40,7,8,'Nebo každý, kdož prosí, béře; a kdož hledá, nalézá; a tomu, jenž tluče, bude otevříno.'),
(1569586,54,40,7,9,'Nebo který z vás jest člověk, kteréhož kdyby prosil syn jeho za chléb, zdali kamene podá jemu?'),
(1569587,54,40,7,10,'A prosil-li by za rybu, zdali hada podá jemu?'),
(1569588,54,40,7,11,'Poněvadž tedy vy, jsouce zlí, umíte dobré dary dávati synům vašim, čím více Otec váš, jenž jest v nebesích, dá dobré věci těm, kteříž ho prosí?'),
(1569589,54,40,7,12,'A protož všecko, což byste chtěli, aby vám lidé činili, to i vy čiňte jim; toť zajisté jest Zákon i Proroci.'),
(1569590,54,40,7,13,'Vcházejte těsnou branou; nebo prostranná brána a široká cesta jest, kteráž vede k zahynutí, a mnoho jest těch, kteříž vcházejí skrze ni.'),
(1569591,54,40,7,14,'Nebo těsná jest brána a úzká cesta, kteráž vede k životu, a málo jest nalézajících ji.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569592,54,40,7,15,'Pilně se pak varujte falešných proroků, kteříž přicházejí k vám v rouše ovčím, ale vnitř jsou vlci hltaví.'),
(1569593,54,40,7,16,'Po ovocích jejich poznáte je. Zdaliž sbírají z trní hrozny, aneb z bodláčí fíky?'),
(1569594,54,40,7,17,'Takť každý strom dobrý ovoce dobré nese, zlý pak strom zlé ovoce nese.'),
(1569595,54,40,7,18,'Nemůžeť dobrý strom zlého ovoce nésti, ani strom zlý ovoce dobrého vydávati.'),
(1569596,54,40,7,19,'Všeliký strom, kterýž nenese ovoce dobrého, vyťat a na oheň uvržen bývá.'),
(1569597,54,40,7,20,'A tak tedy po ovocích jejich poznáte je.'),
(1569598,54,40,7,21,'Ne každý, kdož mi říká: Pane, Pane, vejde do království nebeského, ale ten, kdož činí vůli Otce mého, kterýž v nebesích jest.'),
(1569599,54,40,7,22,'Mnozíť mi dějí v onen den: Pane, Pane, zdaliž jsme ve jménu tvém neprorokovali, a ve jménu tvém ďáblů nevymítali, a v tvém jménu zdaliž jsme divů mnohých nečinili?'),
(1569600,54,40,7,23,'A tehdyť jim vyznám, že jsem vás nikdy neznal. Odejděte ode mne, činitelé nepravosti.'),
(1569601,54,40,7,24,'A protož každého, kdož slyší slova má tato a zachovává je, připodobním muži moudrému, kterýž ustavěl dům svůj na skále.'),
(1569602,54,40,7,25,'I spadl příval, a přišly řeky, a váli větrové, a obořili se na ten dům, a nepadl; nebo založen byl na skále.'),
(1569603,54,40,7,26,'A každý, kdož slyší slova má tato, a neplní jich, připodobněn bude muži bláznu, kterýž ustavěl dům svůj na písku.'),
(1569604,54,40,7,27,'I spadl příval, a přišly řeky, a váli větrové, a obořili se na ten dům, i padl, a byl pád jeho veliký.'),
(1569605,54,40,7,28,'I stalo se, když dokonal Ježíš řeči tyto, že se převelmi divili zástupové učení jeho.'),
(1569606,54,40,7,29,'Nebo učil je jako moc maje, a ne jako zákoníci.'),
(1569607,54,40,8,1,'A když sstupoval s hory, šli za ním zástupové mnozí.'),
(1569608,54,40,8,2,'A aj, malomocný přišed, klaněl se jemu, řka: Pane, kdybys jen chtěl, můžeš mne očistiti.'),
(1569609,54,40,8,3,'I vztáh Ježíš ruku, dotekl se ho, řka: Chci, buď čist. A hned očištěno jest malomocenství jeho.'),
(1569610,54,40,8,4,'I dí mu Ježíš: Viziž, abys žádnému nepravil. Ale jdi, a ukaž se knězi, a obětuj dar, kterýž přikázal Mojžíš, na svědectví jim.'),
(1569611,54,40,8,5,'A když vcházel Ježíš do Kafarnaum, přistoupil k němu setník, prose ho,'),
(1569612,54,40,8,6,'A řka: Pane, služebník můj leží doma šlakem poražený, velmi se trápě.'),
(1569613,54,40,8,7,'I dí mu Ježíš: Já přijdu a uzdravím ho.'),
(1569614,54,40,8,8,'A odpovídaje setník, řekl: Pane, nejsemť hoden, abys všel pod střechu mou, ale toliko rci slovo, a uzdraven bude služebník můj.'),
(1569615,54,40,8,9,'Nebo i já jsem člověk moci poddaný, maje pod sebou žoldnéře, avšak dím-li tomuto: Jdi, tedy jde, a jinému: Přijď, a přijde, a služebníku svému: Učiň toto, a učiní.'),
(1569616,54,40,8,10,'Tedy uslyšev to Ježíš, podivil se, a jdoucím za sebou řekl: Amen pravím vám, ani v Izraeli tak veliké víry jsem nenalezl.'),
(1569617,54,40,8,11,'Pravím pak vám, žeť přijdou mnozí od východu i od západu, a stoliti budou s Abrahamem, s Izákem a s Jákobem v království nebeském,'),
(1569618,54,40,8,12,'Ale synové království vyvrženi budou do temností zevnitřních. Tamť bude pláč a škřipení zubů.'),
(1569619,54,40,8,13,'I řekl Ježíš setníkovi: Jdiž, a jakžs uvěřil, staň se tobě. I uzdraven jest služebník jeho v tu hodinu.'),
(1569620,54,40,8,14,'A přišed Ježíš do domu Petrova, uzřel svegruši jeho, ana leží a má zimnici.'),
(1569621,54,40,8,15,'I dotekl se ruky její, a hned přestala jí zimnice. I vstala a posluhovala jim.'),
(1569622,54,40,8,16,'A když byl večer, přivedli k němu mnohé, kteříž ďábelství měli, a on vymítal duchy zlé slovem, a všecky, kteříž se zle měli, uzdravil,'),
(1569623,54,40,8,17,'Aby se naplnilo povědění skrze Izaiáše proroka, řkoucího: Onť jest vzal na se mdloby naše, a neduhy naše nesl.'),
(1569624,54,40,8,18,'Vida pak Ježíš zástupy mnohé okolo sebe, kázal přeplaviti se na druhou stranu.'),
(1569625,54,40,8,19,'A přistoupiv jeden zákoník, řekl jemu: Mistře, půjdu za tebou, kamžkoli půjdeš.'),
(1569626,54,40,8,20,'I dí mu Ježíš: Lišky doupata mají, a ptactvo nebeské hnízda, ale Syn člověka nemá, kde by hlavu sklonil.'),
(1569627,54,40,8,21,'Jiný pak z učedlníků jeho řekl jemu: Pane, dopusť mi prve odjíti a pochovati otce mého.'),
(1569628,54,40,8,22,'Ale Ježíš řekl jemu: Pojď za mnou, a nech, ať tam mrtví pochovávají mrtvé své.'),
(1569629,54,40,8,23,'A když vstoupil na lodí, vstoupili za ním i učedlníci jeho.'),
(1569630,54,40,8,24,'A aj, bouře veliká stala se jest na moři, takže vlny přikrývaly lodí. On pak spal.'),
(1569631,54,40,8,25,'A přistoupivše učedlníci jeho, zbudili jej, řkouce: Pane, zachovej nás, hynemeť.'),
(1569632,54,40,8,26,'I dí jim: Proč se bojíte, ó malé víry? Tedy vstav, přimluvil větrům a moři, i stalo se utišení veliké.'),
(1569633,54,40,8,27,'Lidé pak divili se, řkouce: Kteraký jest tento, že ho i větrové i moře poslouchají?'),
(1569634,54,40,8,28,'A když se přeplavil na druhou stranu do krajiny Gergezenských, potkali se s ním dva ďábelníci z hrobu vyšlí, ukrutní náramně, takže pro ně žádný nemohl tou cestou choditi.'),
(1569635,54,40,8,29,'A aj, zkřikli, řkouce: Co je nám po tobě, Ježíši, Synu Boží? Přišel jsi sem před časem trápiti nás.'),
(1569636,54,40,8,30,'A bylo opodál od nich stádo veliké vepřů, pasoucích se.'),
(1569637,54,40,8,31,'Ďáblové pak prosili ho, řkouce: Poněvadž nás vymítáš, dopustiž nám vjíti do toho stáda vepřů.'),
(1569638,54,40,8,32,'I řekl jim: Jděte. A oni vyšedše, vešli do stáda těch vepřů. A aj, hnalo se všecko stádo těch vepřů s vrchu dolů do moře, i ztonuli v vodách.'),
(1569639,54,40,8,33,'Pastýři pak utekli. A přišedše do města, vypravovali to všecko, i o těch ďábelnících.'),
(1569640,54,40,8,34,'A aj, všecko město vyšlo v cestu Ježíšovi, a uzřevše ho, prosili, aby šel z končin jejich.'),
(1569641,54,40,9,1,'A vstoupiv na lodí, přeplavil se, a přišel do města svého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569642,54,40,9,2,'A aj, přinesli mu šlakem poraženého, ležícího na loži. A viděv Ježíš víru jejich, dí šlakem poraženému: Doufej, synu, odpuštěniť jsou tobě hříchové tvoji.'),
(1569643,54,40,9,3,'A aj, někteří z zákoníků řekli sami v sobě: Tento se rouhá.'),
(1569644,54,40,9,4,'A viděv Ježíš myšlení jejich, řekl: Proč vy myslíte zlé věci v srdcích vašich?'),
(1569645,54,40,9,5,'Nebo co jest snáze říci, to-li: Odpouštějí se tobě hříchové? čili říci: Vstaň a choď?'),
(1569646,54,40,9,6,'Ale abyste věděli, žeť má moc Syn člověka na zemi odpouštěti hříchy, tedy dí šlakem poraženému: Vstaň, vezmi lože své, a jdi do domu svého.'),
(1569647,54,40,9,7,'Tedy vstal a odšel do domu svého.'),
(1569648,54,40,9,8,'A vidouce to zástupové, divili se a velebili Boha, kterýž dal takovou moc lidem.'),
(1569649,54,40,9,9,'A jda odtud Ježíš, uzřel člověka sedícího na cle, jménem Matouše. I dí mu: Pojď za mnou. A on vstav, šel za ním.'),
(1569650,54,40,9,10,'I stalo se, když seděl za stolem v domu jeho, a aj, mnozí celní a hříšníci přišedše, stolili s Ježíšem a s učedlníky jeho.'),
(1569651,54,40,9,11,'A vidouce to farizeové, řekli učedlníkům jeho: Proč s celnými a hříšníky jí Mistr váš?'),
(1569652,54,40,9,12,'Ježíš pak uslyšev to, řekl jim: Nepotřebujíť zdraví lékaře, ale nemocní.'),
(1569653,54,40,9,13,'Jděte vy raději a učte se, co jest to: Milosrdenství chci a ne oběti. Nebo nepřišel jsem volati spravedlivých, ale hříšných ku pokání.'),
(1569654,54,40,9,14,'Tehdy přistoupili k němu učedlníci Janovi, řkouce: Proč my a farizeové postíme se často, učedlníci pak tvoji se nepostí?'),
(1569655,54,40,9,15,'I řekl jim Ježíš: Zdaliž mohou synové Ženichovi rmoutiti se, dokudž s nimi jest Ženich? Ale přijdou dnové, když bude od nich odjat Ženich, a tehdyť se budou postiti.'),
(1569656,54,40,9,16,'Žádný zajisté nepřišívá záplaty sukna nového k rouchu vetchému; nebo ta záplata jeho odtrhla by ještě nějaký díl od roucha, a tak větší by díra byla.'),
(1569657,54,40,9,17,'Aniž lejí vína nového do nádob starých; sic jinak rozpuknou se sudové, a víno se vyleje, a sudové se zkazí. Ale víno nové lejí do nových nádob, a bývá obé zachováno.'),
(1569658,54,40,9,18,'A když on toto k nim mluvil, aj, kníže jedno přistoupilo a klanělo se jemu, řka: Pane dcera má nyní umřela. Ale pojď, vlož na ni ruku svou, a budeť živa.'),
(1569659,54,40,9,19,'A vstav Ježíš, šel za ním, i učedlníci jeho.'),
(1569660,54,40,9,20,'(A aj, žena, kteráž nemocí svou trápena byla ode dvanácti let, přistoupivši pozadu, dotkla se podolka roucha jeho.'),
(1569661,54,40,9,21,'Nebo řekla sama v sobě: Dotknu-li se jen toliko roucha jeho, uzdravena budu.'),
(1569662,54,40,9,22,'Ježíš pak obrátiv se a uzřev ji, řekl: Doufej, dcero, víra tvá tě uzdravila. A zdráva učiněna jest žena od té chvíle.)'),
(1569663,54,40,9,23,'Přišed pak Ježíš do domu knížete, a uzřev tu trubače a zástup hlučící,'),
(1569664,54,40,9,24,'Řekl jim: Odejdětež; nebť neumřela děvečka, ale spí. I posmívali se jemu.'),
(1569665,54,40,9,25,'A když byl vyhnán zástup, všed tam, ujal ji za ruku její; i vstala jest děvečka.'),
(1569666,54,40,9,26,'A roznesla se pověst ta po vší té zemi.'),
(1569667,54,40,9,27,'A když šel odtud Ježíš, šli za ním dva slepí, volajíce a řkouce: Smiluj se nad námi, Synu Davidův.'),
(1569668,54,40,9,28,'A když všel do domu, přistoupili k němu ti slepí. I dí jim Ježíš: Věříte-li, že to mohu učiniti? Řekli jemu: Ovšem, Pane.'),
(1569669,54,40,9,29,'Tedy dotekl se očí jejich, řka: Podle víry vaší staniž se vám.'),
(1569670,54,40,9,30,'I otevříny jsou oči jejich. Zapověděl jim pak tuze Ježíš, řka: Viztež, ať nižádný o tom nezví.'),
(1569671,54,40,9,31,'Ale oni vyšedše, rozhlásali jej po vší té zemi.'),
(1569672,54,40,9,32,'A když oni vycházeli, aj, přivedli mu člověka němého, majícího ďábelství.'),
(1569673,54,40,9,33,'A když vyvrhl ďábelství, mluvil jest němý. I divili se zástupové, řkouce: Že nikdy se nic takového neukázalo v lidu Izraelském.'),
(1569674,54,40,9,34,'Farizeové pak pravili: Mocí knížete ďábelského vymítá ďábly.'),
(1569675,54,40,9,35,'I obcházel Ježíš všecka města i městečka, uče v školách jejich a káže evangelium království, a uzdravuje všelikou nemoc i všeliký neduh v lidu.'),
(1569676,54,40,9,36,'A když hleděl na zástupy, slitovalo se mu jich, že byli tak opuštěni a rozptýleni jako ovce, nemajíce pastýře.'),
(1569677,54,40,9,37,'Tedy dí učedlníkům svým: Žeň zajisté jest mnohá, ale dělníků málo.'),
(1569678,54,40,9,38,'Protož proste Pána žni, ať vypudí dělníky na žeň svou.'),
(1569679,54,40,10,1,'A svolav k sobě dvanácte učedlníků svých, dal jim moc nad duchy nečistými, aby je vymítali, a aby uzdravovali všelikou nemoc, i všeliký neduh.'),
(1569680,54,40,10,2,'Dvanácti pak apoštolů jména jsou tato: První Šimon, jenž slove Petr, a Ondřej bratr jeho, Jakub Zebedeův a Jan bratr jeho,'),
(1569681,54,40,10,3,'Filip a Bartoloměj, Tomáš a Matouš, jenž byl celný, Jakub Alfeův a Lebbeus, přijmím Thaddeus,'),
(1569682,54,40,10,4,'Šimon Kananitský a Jidáš Iškariotský, kterýž i zradil ho.'),
(1569683,54,40,10,5,'Těch dvanácte poslal Ježíš, přikazuje jim, řka: Na cestu pohanů nechoďte, a do měst Samaritánských nevcházejte.'),
(1569684,54,40,10,6,'Ale raději jděte k ovcem zahynulým z domu Izraelského.'),
(1569685,54,40,10,7,'Jdouce pak, kažte, řkouce: Že se přiblížilo království nebeské.'),
(1569686,54,40,10,8,'Nemocné uzdravujte, malomocné čisťte, mrtvé křeste, ďábelství vymítejte; darmo jste vzali, darmo dejte.'),
(1569687,54,40,10,9,'Neshromažďujte zlata ani stříbra, ani peněz v opascích vašich mívejte,'),
(1569688,54,40,10,10,'Ani mošny na cestě, ani dvou sukní, ani obuvi, ani hůlky; hodenť jest zajisté dělník pokrmu svého.'),
(1569689,54,40,10,11,'A do kteréhožkoli města neb městečka vešli byste, vzeptejte se, kdo by v něm hodný byl, a tu pobuďte, až byste i vyšli odtud.'),
(1569690,54,40,10,12,'A vcházejíce do domu, pozdravtež ho.'),
(1569691,54,40,10,13,'A jestližeť bude dům ten hodný, pokoj váš přijdiž naň; pakliť by nebyl hodný, pokoj váš navratiž se k vám.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569692,54,40,10,14,'A kdožkoli nepřijal by vás, a neuposlechl by řečí vašich, vyjdouce ven z domu neb z města toho, vyraztež prach z noh vašich.'),
(1569693,54,40,10,15,'Amen pravím vám: Lehčeji bude zemi Sodomských a Gomorských v den soudný nežli městu tomu.'),
(1569694,54,40,10,16,'Aj, já posílám vás jako ovce mezi vlky; protož buďte opatrní jako hadové, a sprostní jako holubice.'),
(1569695,54,40,10,17,'Vystříhejtež se pak lidí; nebť vás vydávati budou do sněmů, a v školách svých budou vás bičovati.'),
(1569696,54,40,10,18,'Ano i před vladaře i před krále vedeni budete pro mne, na svědectví jim, i těm národům.'),
(1569697,54,40,10,19,'Kdyžť pak vás vydadí, nebuďtež pečliví, kterak aneb co byste mluvili; dánoť bude zajisté vám v tu hodinu, co budete míti mluviti.'),
(1569698,54,40,10,20,'Nebo ne vy jste, jenž mluvíte, ale duch Otce vašeho, jenž mluví v vás.'),
(1569699,54,40,10,21,'Vydáť pak bratr bratra na smrt, i otec syna, a povstanouť dítky proti rodičům, a zmordují je.'),
(1569700,54,40,10,22,'A budete v nenávisti všechněm pro jméno mé, ale kdož setrvá až do konce, tenť spasen bude.'),
(1569701,54,40,10,23,'Když se pak vám budou protiviti v tom městě, utecte do jiného. Amen zajisté pravím vám, nezchodíte měst Izraelských, ažť přijde Syn člověka.'),
(1569702,54,40,10,24,'Neníť učedlník nad mistra, ani služebník nad pána svého.'),
(1569703,54,40,10,25,'Dostiť jest učedlníku, aby byl jako mistr jeho, a služebník jako pán jeho. Poněvadž jsou hospodáře Belzebubem nazývali, čím pak více domácí jeho?'),
(1569704,54,40,10,26,'Protož nebojte se jich; nebť není nic skrytého, což by nemělo býti zjeveno, ani co tajného, ješto by nemělo zvědíno býti.'),
(1569705,54,40,10,27,'Což vám pravím ve tmách, pravte na světle, a co v uši slyšíte, hlásejte na domích.'),
(1569706,54,40,10,28,'A nebojte se těch, kteříž zabíjejí tělo, ale duše nemohou zabíti; než bojte se raději toho, kterýž může i duši i tělo zatratiti v pekelném ohni.'),
(1569707,54,40,10,29,'Zdaliž neprodávají dvou vrabců za malý peníz? a jeden z nich nepadá na zem bez vůle Otce vašeho.'),
(1569708,54,40,10,30,'Vaši pak i vlasové na hlavě všickni sečteni jsou.'),
(1569709,54,40,10,31,'Protož nebojte se, mnohých vrabců dražší jste vy.'),
(1569710,54,40,10,32,'Kdožkoli tedy vyzná mne před lidmi, vyznámť i já jej před Otcem svým, jenž jest v nebesích.'),
(1569711,54,40,10,33,'Ale kdož by mne zapřel před lidmi, zapřímť ho i já před Otcem svým, kterýž jest v nebesích.'),
(1569712,54,40,10,34,'Nedomnívejte se, že bych přišel pokoj dáti na zemi. Nepřišelť jsem, abych pokoj uvedl, ale meč.'),
(1569713,54,40,10,35,'Přišelť jsem zajisté, abych rozdělil člověka proti otci jeho, a dceru proti mateři její, a nevěstu proti svegruši její.'),
(1569714,54,40,10,36,'A nepřátelé člověka budou domácí jeho.'),
(1569715,54,40,10,37,'Kdo miluje otce neb matku více nežli mne, neníť mne hoden; a kdož miluje syna nebo dceru více nežli mne, neníť mne hoden.'),
(1569716,54,40,10,38,'A kdož nebéře kříže svého a nenásleduje mne, neníť mne hoden.'),
(1569717,54,40,10,39,'Kdož nalezne duši svou, ztratíť ji; a kdo by ztratil duši svou pro mne, nalezneť ji.'),
(1569718,54,40,10,40,'Kdož vás přijímá, mneť přijímá; a kdo mne přijímá, přijímáť toho, kterýž mne poslal.'),
(1569719,54,40,10,41,'Kdo přijímá proroka ve jménu proroka, odplatu proroka vezme; a kdož přijímá spravedlivého ve jménu spravedlivého, odplatu spravedlivého vezme.'),
(1569720,54,40,10,42,'A kdož by koli dal jednomu z těchto nejmenších číši vody studené k nápoji, toliko ve jménu učedlníka, zajisté pravím vám, neztratíť odplaty své.'),
(1569721,54,40,11,1,'I stalo se, když dokonal Ježíš řeči své, kteréž mluvil, přikázání dávaje dvanácti učedlníkům svým, bral se odtud, aby učil a kázal v městech jejich.'),
(1569722,54,40,11,2,'Jan pak v vězení uslyšev o skutcích Kristových, poslal dva z učedlníků svých,'),
(1569723,54,40,11,3,'A řekl jemu: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?'),
(1569724,54,40,11,4,'I odpovídaje Ježíš, řekl jim: Jdouce, zvěstujtež Janovi, co slyšíte a vidíte:'),
(1569725,54,40,11,5,'Slepí vidí, a kulhaví chodí, malomocní se čistí, a hluší slyší, mrtví z mrtvých vstávají, chudým pak evangelium se zvěstuje.'),
(1569726,54,40,11,6,'A blahoslavený jest, kdož se nehorší na mně.'),
(1569727,54,40,11,7,'A když oni odešli, počal Ježíš praviti zástupům o Janovi: Co jste vyšli na poušť viděti? Zdali třtinu větrem se klátící?'),
(1569728,54,40,11,8,'Aneb co jste vyšli viděti? Zda člověka měkkým rouchem oděného? Aj, kteříž se měkkým rouchem odívají, v domích královských jsou.'),
(1569729,54,40,11,9,'Aneb co jste vyšli viděti? Proroka-li? Jistě pravím vám, i více nežli proroka.'),
(1569730,54,40,11,10,'Tentoť jest zajisté, o němž psáno: Aj, já posílám anděla svého před tváří tvou, kterýžto připraví cestu tvou před tebou.'),
(1569731,54,40,11,11,'Amen pravím vám, mezi syny ženskými nepovstal větší nad Jana Křtitele; ale kdo jest menší v království nebeském, jestiť větší nežli on.'),
(1569732,54,40,11,12,'Ode dnů pak Jana Křtitele až dosavad království nebeské násilí trpí, a ti, kteříž násilí činí, uchvacujíť je.'),
(1569733,54,40,11,13,'Nebo všickni Proroci i Zákon až do Jana prorokovali.'),
(1569734,54,40,11,14,'A chcete-li přijmouti: Onť jest Eliáš, kterýž přijíti měl.'),
(1569735,54,40,11,15,'Kdo má uši k slyšení, slyš.'),
(1569736,54,40,11,16,'Ale k komu připodobním pokolení toto? Podobno jest dětem, sedícím na ryncích, a kteříž na tovaryše své volají,'),
(1569737,54,40,11,17,'A říkají: Pískali jsme vám, a neskákali jste; žalostně jsme naříkali, a neplakali jste.'),
(1569738,54,40,11,18,'Přišel zajisté Jan, nejeda ani pije, a oni řkou: Ďábelství má.'),
(1569739,54,40,11,19,'Přišel Syn člověka, jeda a pije, a oni řkou: Aj, člověk žráč a pijan vína, přítel publikánů a hříšníků. Ale ospravedlněna jest moudrost od synů svých.'),
(1569740,54,40,11,20,'Tehdy počal přimlouvati městům, v nichžto činěni jsou jeho mnozí divové, že pokání nečinili.'),
(1569741,54,40,11,21,'Běda tobě Korozaim, běda tobě Betsaido. Nebo kdyby v Týru a Sidonu byli činěni divové ti, kteříž jsou činěni v vás, dávno by byli v žíni a v popele pokání činili.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569742,54,40,11,22,'Nýbrž pravím vám, že Týru a Sidonu lehčeji bude v den soudný nežli vám.'),
(1569743,54,40,11,23,'A ty Kafarnaum, kteréž jsi až k nebi vyvýšeno, až do pekla sstrčeno budeš. Nebo kdyby v Sodomě činěni byli divové ti, kteříž jsou činěni v tobě, byliť by zůstali až do dnešního dne.'),
(1569744,54,40,11,24,'Ano více pravím vám, že zemi Sodomských lehčeji bude v den soudný nežli tobě.'),
(1569745,54,40,11,25,'V ten čas odpověděv Ježíš, řekl: Chválím tě, Otče, Pane nebe i země, že jsi skryl tyto věci před moudrými a opatrnými, a zjevil jsi je maličkým.'),
(1569746,54,40,11,26,'Jistě, Otče, že se tak líbilo před tebou.'),
(1569747,54,40,11,27,'Všecky věci dány jsou mi od Otce mého, a žádnýť nezná Syna, jediné Otec, aniž Otce kdo zná, jediné Syn, a komuž by chtěl Syn zjeviti.'),
(1569748,54,40,11,28,'Pojdtež ke mně všickni, kteříž pracujete a obtíženi jste, a já vám odpočinutí dám.'),
(1569749,54,40,11,29,'Vezměte jho mé na se, a učte se ode mne, neboť jsem tichý a pokorný srdcem, a naleznete odpočinutí dušem vašim.'),
(1569750,54,40,11,30,'Jho mé zajisté jestiť rozkošné, a břímě mé lehké.'),
(1569751,54,40,12,1,'V ten čas šel Ježíš v den sváteční skrze obilí, a učedlníci jeho lačni jsouce, počali vymínati klasy a jísti.'),
(1569752,54,40,12,2,'Farizeové pak vidouce to, řekli jemu: Hle, učedlníci tvoji činí to, čehož nesluší činiti v den sváteční.'),
(1569753,54,40,12,3,'On pak řekl jim: Co jste nečtli, co jest učinil David, když lačněl, on i ti, kteříž s ním byli?'),
(1569754,54,40,12,4,'Kterak všel do domu Božího a chleby posvátné jedl, kterýchžto jemu neslušelo jísti, ani těm, kteříž s ním byli, než toliko samým kněžím?'),
(1569755,54,40,12,5,'Anebo zdali jste nečtli v Zákoně, že kněží ve dny sváteční v chrámě svátek ruší, a jsou bez hříchu?'),
(1569756,54,40,12,6,'Ale pravímť vám, žeť větší jest tuto nežli chrám.'),
(1569757,54,40,12,7,'Než kdybyste věděli, co je to: Milosrdenství chci a ne oběti, neodsuzovali byste nevinných.'),
(1569758,54,40,12,8,'Syn zajisté člověka jestiť pánem i dne svátečního.'),
(1569759,54,40,12,9,'A poodšed odtud Ježíš, přišel do školy jejich.'),
(1569760,54,40,12,10,'A aj, byl tu člověk, maje ruku uschlou. I tázali se ho, řkouce: Sluší-li v den sváteční uzdravovati? aby jej obžalovali.'),
(1569761,54,40,12,11,'On pak dí jim: Který bude z vás člověk, ješto by měl ovci jednu, a kdyby ta upadla do jámy v den sváteční, i zdaliž dosáhna nevytáhne jí?'),
(1569762,54,40,12,12,'A čím lepší jest člověk nežli ovce? A protož slušíť v den sváteční dobře činiti.'),
(1569763,54,40,12,13,'Tedy řekl člověku tomu: Vztáhni ruku svou. I vztáhl, a učiněna jest zdravá jako i druhá.'),
(1569764,54,40,12,14,'Farizeové pak vyšedše, drželi radu proti němu, kterak by jej zahladili.'),
(1569765,54,40,12,15,'A věda to Ježíš, šel odtud. I šli za ním zástupové mnozí, a uzdravil je všecky.'),
(1569766,54,40,12,16,'A s pohrůžkou přikázal jim, aby ho nezjevovali,'),
(1569767,54,40,12,17,'Aby se naplnilo povědění skrze Izaiáše proroka, řkoucího:'),
(1569768,54,40,12,18,'Aj, služebník můj, kteréhož jsem vyvolil, milý můj, v němž se dobře zalíbilo duši mé. Položím Ducha svého na něj, a soud národům zvěstovati bude.'),
(1569769,54,40,12,19,'Nebude se vaditi, ani křičeti, ani kdo na ulicích uslyší hlas jeho.'),
(1569770,54,40,12,20,'Třtiny nalomené nedolomí, a lnu kouřícího se neuhasí, až i vypoví soud k vítězství.'),
(1569771,54,40,12,21,'A ve jménu jeho národové doufati budou.'),
(1569772,54,40,12,22,'Tedy podán jemu ďábelstvím posedlý, slepý a němý. I uzdravil jej, takže ten byv slepý a němý, i mluvil i viděl.'),
(1569773,54,40,12,23,'I divili se všickni zástupové a pravili: Není-liž tento Syn Davidův?'),
(1569774,54,40,12,24,'Ale farizeové to uslyševše, řekli: Tento nevymítá ďáblů než Belzebubem, knížetem ďábelským.'),
(1569775,54,40,12,25,'Ježíš pak znaje myšlení jejich, dí jim: Každé království rozdělené samo v sobě zpustne, a každé město neb dům proti sobě rozdělený nestane.'),
(1569776,54,40,12,26,'A jestližeť satan satana vymítá, proti sobě rozdělen jest. Kterak tedy stane království jeho?'),
(1569777,54,40,12,27,'A vymítám-liť já ďábly v Belzebubu, synové vaši v kom vymítají? Protož oni soudcové vaši budou.'),
(1569778,54,40,12,28,'Pakliť já Duchem Božím ďábly vymítám, jistě přišlo jest mezi vás království Boží.'),
(1569779,54,40,12,29,'Aneb kterak kdo může do domu silného reka vjíti a jeho nádobí pobrati, leč by prve svázal toho silného, a teprvť by dům jeho obloupiti mohl?'),
(1569780,54,40,12,30,'Kdož není se mnou, proti mně jest; a kdo neshromažďuje se mnou, rozptylujeť.'),
(1569781,54,40,12,31,'Protož pravím vám: Všeliký hřích i rouhání bude lidem odpuštěno, ale rouhání proti Duchu svatému nebude odpuštěno lidem.'),
(1569782,54,40,12,32,'A kdyby kdo řekl slovo proti Synu člověka, bude jemu odpuštěno, ale kdož by mluvil proti Duchu svatému, nebude jemu odpuštěno, ani na tomto světě, ani na budoucím.'),
(1569783,54,40,12,33,'A protož nebo čiňte strom dobrý, a ovoce jeho dobré; anebo čiňte strom zlý, a ovoce jeho zlé. Neboť po ovoci strom bývá poznán.'),
(1569784,54,40,12,34,'Pokolení ještěrčí, kterakž můžete dobré věci mluviti, jsouce zlí? Nebo z hojnosti srdce ústa mluví.'),
(1569785,54,40,12,35,'Dobrý člověk z dobrého pokladu srdce vynáší dobré, a zlý člověk ze zlého pokladu vynáší zlé.'),
(1569786,54,40,12,36,'Ale pravím vám, že z každého slova prázdného, kteréž mluviti budou lidé, vydadí počet v den soudný.'),
(1569787,54,40,12,37,'Nebo z slov svých spravedliv budeš učiněn, a z řečí tvých budeš odsouzen.'),
(1569788,54,40,12,38,'Tehdy odpověděli někteří z zákoníků a farizeů, řkouce: Mistře, chceme od tebe znamení viděti.'),
(1569789,54,40,12,39,'On pak odpovídaje, dí jim: Pokolení zlé a cizoložné znamení hledá, a znamení nebude jemu dáno, jediné znamení Jonáše proroka.'),
(1569790,54,40,12,40,'Nebo jakož byl Jonáš v břiše velryba tři dni a tři noci, takť bude Syn člověka v srdci země tři dni a tři noci.'),
(1569791,54,40,12,41,'Muži Ninivitští stanou na soudu s pokolením tímto, a odsoudí je, protože pokání činili k Jonášovu kázání, a aj, víceť jest nežli Jonáš tuto.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569792,54,40,12,42,'Královna od poledne povstane k soudu s pokolením tímto, a odsoudí je; nebo přijela od končin země, aby slyšela moudrost Šalomounovu, a aj, víceť jest tuto nežli Šalomoun.'),
(1569793,54,40,12,43,'Když pak nečistý duch vyjde od člověka, chodí po místech suchých, hledaje odpočinutí, ale nenalézaje, dí:'),
(1569794,54,40,12,44,'Navrátím se do domu svého, odkudž jsem vyšel. A přijda, nalezne prázdný, vyčištěný a ozdobený.'),
(1569795,54,40,12,45,'Tedy jde a vezme s sebou sedm jiných duchů horších, a vejdouce, přebývají tam, i bývají poslední věci člověka toho horší nežli první. Takť bude i tomuto zlému pokolení.'),
(1569796,54,40,12,46,'A když on ještě mluvil k zástupům, aj, matka a bratří jeho stáli vně, žádajíce s ním promluviti.'),
(1569797,54,40,12,47,'I řekl jemu jeden: Aj, matka tvá i bratří tvoji stojí vně, chtíce s tebou mluviti.'),
(1569798,54,40,12,48,'On pak odpovídaje, řekl tomu, kterýž k němu byl promluvil: Kdo jest matka má? A kdo jsou bratří moji?'),
(1569799,54,40,12,49,'A vztáhna ruku svou na učedlníky své, i řekl: Aj, matka má i bratří moji.'),
(1569800,54,40,12,50,'Nebo kdož by činil vůli Otce mého nebeského, tenť jest bratr můj, i sestra má, i matka má.'),
(1569801,54,40,13,1,'A v ten den vyšed Ježíš z domu, sedl podle moře.'),
(1569802,54,40,13,2,'I sešli se k němu zástupové mnozí, takže vstoupiv na lodí, seděl, všecken pak zástup stál na břehu.'),
(1569803,54,40,13,3,'I mluvil jim mnoho v podobenstvích, řka: Aj, vyšel rozsevač, aby rozsíval.'),
(1569804,54,40,13,4,'A když on rozsíval, některá seménka padla podle cesty, a přiletěli ptáci, i szobali je.'),
(1569805,54,40,13,5,'Jiná pak padla na místa skalnatá, kdežto neměla mnoho země; a rychle vzešla, protože neměla hlubokosti země.'),
(1569806,54,40,13,6,'Ale když slunce vzešlo, uvadla, a že neměla kořene, uschla.'),
(1569807,54,40,13,7,'Jiná pak padla v trní; i vzrostlo trní, a udusilo je.'),
(1569808,54,40,13,8,'A jiná padla v zemi dobrou; i vydalo užitek, některé stý, jiné šedesátý a jiné třidcátý.'),
(1569809,54,40,13,9,'Kdo má uši k slyšení, slyš.'),
(1569810,54,40,13,10,'Tedy přistoupivše učedlníci, řekli jemu: Proč jim v podobenstvích mluvíš?'),
(1569811,54,40,13,11,'On pak odpověděv, řekl jim: Nebo vám dáno jest znáti tajemství království nebeského, ale jim není dáno.'),
(1569812,54,40,13,12,'(Nebo kdož má, bude jemu dáno a rozhojníť se; ale kdož nemá, i to, což má, bude od něho odjato.)'),
(1569813,54,40,13,13,'Protoť v podobenstvích mluvím jim, že vidouce nevidí, a slyšíce neslyší, ani rozumějí.'),
(1569814,54,40,13,14,'A plní se na nich proroctví Izaiáše, řkoucí: Ušima uslyšíte, ale nesrozumíte; a hledíce, hleděti budete, ale neuzříte.'),
(1569815,54,40,13,15,'Nebo ztučnělo jest srdce lidu tohoto, a ušima těžce slyšeli a oči své zamhouřili, aby snad někdy neuzřeli očima a ušima neslyšeli a srdcem nesrozuměli, a neobrátili se, a já abych jich neuzdravil.'),
(1569816,54,40,13,16,'Ale oči vaše blahoslavené jsou, že vidí, i uši vaše, že slyší.'),
(1569817,54,40,13,17,'Amen zajisté pravím vám, že mnozí proroci a spravedliví žádali viděti to, což vy vidíte, a neviděli, a slyšeti to, což vy slyšíte, a neslyšeli.'),
(1569818,54,40,13,18,'Vy tedy slyšte podobenství rozsevače.'),
(1569819,54,40,13,19,'Každý, kdož slyší slovo království a nerozumí, přichází ten zlý a uchvacuje to, což jest vsáto v srdce jeho. To jest ten, kterýž podle cesty vsát jest.'),
(1569820,54,40,13,20,'Ale v skalnatou zemi vsátý, ten jest, kterýž slyší slovo, a hned je s radostí přijímá.'),
(1569821,54,40,13,21,'Než nemá v sobě kořene, ale jest časný, a když přichází soužení nebo protivenství pro slovo, hned se horší.'),
(1569822,54,40,13,22,'Ale mezi trní vsátý, ten jest, kterýž slyší slovo Boží, ale pečování tohoto světa a oklamání zboží udušuje slovo, i bývá učiněno bez užitku.'),
(1569823,54,40,13,23,'V dobrou pak zemi vsátý, ten jest, kterýž slyší slovo a rozumí, i ovoce nese a vydává, některé zajisté stý, a jiné šedesátý, jiné pak třidcátý.'),
(1569824,54,40,13,24,'Jiné podobenství předložil jim, řka: Podobno jest království nebeské člověku, rozsívajícímu dobré semeno na poli svém.'),
(1569825,54,40,13,25,'Když pak lidé zesnuli, přišel nepřítel jeho a nasál koukole mezi pšenici a odšel.'),
(1569826,54,40,13,26,'A když vzrostla bylina a užitek přinesla, tedy ukázal se i koukol.'),
(1569827,54,40,13,27,'I přistoupivše služebníci hospodáře toho, řekli jemu: Pane, všaks dobrého semene nasál na poli svém, kdeže se pak vzal koukol?'),
(1569828,54,40,13,28,'A on řekl jim: Nepřítel člověk to učinil. Služebníci pak řekli mu: Chceš-liž, tedy půjdeme a vytrháme jej?'),
(1569829,54,40,13,29,'On pak odpověděl: Nikoli, abyste trhajíce koukol, spolu s ním nevytrhali pšenice.'),
(1569830,54,40,13,30,'Nechte, ať obé spolu roste až do žni. A v čas žni dím žencům: Vytrhejte nejprv koukol a svažte jej v snopky k spálení, ale pšenici shromažďte do stodoly mé.'),
(1569831,54,40,13,31,'Jiné podobenství předložil jim, řka: Podobno jest království nebeské zrnu horčičnému, kteréž vzav člověk, vsál na poli svém.'),
(1569832,54,40,13,32,'Kteréžto zajisté nejmenší jest mezi všemi semeny, když pak vzroste, větší jest všech bylin, a bývá strom, takže ptactvo nebeské přiletíce, hnízda sobě dělají na ratolestech jeho.'),
(1569833,54,40,13,33,'Jiné podobenství mluvil jim, řka: Podobno jest království nebeské kvasu, kterýž vzavši žena, zadělala ve třech měřicích mouky, až by zkysalo všecko.'),
(1569834,54,40,13,34,'Toto všecko mluvil Ježíš v podobenstvích k zástupům, a bez podobenství nemluvil jim,'),
(1569835,54,40,13,35,'Aby se naplnilo povědění skrze proroka, řkoucího: Otevru v podobenstvích ústa svá, vypravovati budu skryté věci od založení světa.'),
(1569836,54,40,13,36,'Tedy rozpustiv zástupy, šel do domu Ježíš. I přistoupili k němu učedlníci jeho, řkouce: Vylož nám podobenství o koukoli toho pole.'),
(1569837,54,40,13,37,'On pak odpovídaje, řekl jim: Rozsevač dobrého semene jestiť Syn člověka.'),
(1569838,54,40,13,38,'A pole jest tento svět, dobré pak símě jsouť synové království, ale koukol jsou synové toho zlostníka.'),
(1569839,54,40,13,39,'A nepřítel, kterýž jej rozsívá, jestiť ďábel, ale žeň jest skonání světa, a ženci jsou andělé.'),
(1569840,54,40,13,40,'Protož jakož vytrhávají koukol a ohněm spalují, takť bude při skonání světa tohoto.'),
(1569841,54,40,13,41,'Pošle Syn člověka anděly své, i vyberouť z království jeho všecka pohoršení, i ty, kteříž činí nepravost,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569842,54,40,13,42,'A uvrhouť je do peci ohnivé. Tamť bude pláč a škřipení zubů.'),
(1569843,54,40,13,43,'A tehdážť spravedliví stkvíti se budou jako slunce v království Otce svého. Kdo má uši k slyšení, slyš.'),
(1569844,54,40,13,44,'Opět podobno jest království nebeské pokladu skrytému v poli, kterýž nalezna člověk, skrývá, a radostí pro něj odejde a prodá všecko, což má, a koupí pole to.'),
(1569845,54,40,13,45,'Opět podobno jest království nebeské člověku kupci, hledajícímu dobrých perel.'),
(1569846,54,40,13,46,'Kterýž nalezna jednu velmi drahou perlu, odšel a prodal všecko, což měl, a koupil ji.'),
(1569847,54,40,13,47,'Opět podobno jest království nebeské vrši puštěné do moře a ze všelikého plodu shromažďující;'),
(1569848,54,40,13,48,'Kteroužto, když naplněna byla, vytáhše na břeh a sedíce, vybírali, což dobrého bylo, v nádoby své, a což bylo zlého, preč zamítali.'),
(1569849,54,40,13,49,'Takť bude při skonání světa. Vyjdou andělé a oddělí zlé z prostředku spravedlivých,'),
(1569850,54,40,13,50,'A uvrhou je do peci ohnivé. Tamť bude pláč a škřipení zubů.'),
(1569851,54,40,13,51,'Potom dí jim Ježíš: Srozuměli-li jste tomuto všemu? Řekli jemu: I ovšem, Pane.'),
(1569852,54,40,13,52,'On pak řekl jim: Protož každý učitel umělý v království nebeském podoben jest člověku hospodáři, kterýž vynáší z pokladu svého nové i staré věci.'),
(1569853,54,40,13,53,'I stalo se, když dokonal Ježíš podobenství tato, bral se odtud.'),
(1569854,54,40,13,54,'A přišed do vlasti své, učil je v školách jejich, takže se velmi divili, řkouce: Odkud má tento moudrost tuto a moc tuto?'),
(1569855,54,40,13,55,'Zdaliž tento není syn tesařův? a zdaliž matka jeho neslove Maria a bratří jeho Jakub a Jozes a Šimon a Judas?'),
(1569856,54,40,13,56,'A sestry jeho zdaliž také všecky u nás nejsou? Odkudž tedy má tyto všecky věci?'),
(1569857,54,40,13,57,'I zhoršili se na něm. A Ježíš řekl: Není prorok beze cti, než v své vlasti a v domu svém.'),
(1569858,54,40,13,58,'I neučinil tu mnoho divů, pro nevěru jejich.'),
(1569859,54,40,14,1,'V tom čase uslyšel Herodes čtvrták pověst o Ježíšovi.'),
(1569860,54,40,14,2,'I řekl služebníkům svým: To jest Jan Křtitel. Onť jest vstal z mrtvých, a protož se divové dějí skrze něho.'),
(1569861,54,40,14,3,'Nebo Herodes byl jal Jana a svázal jej a dal do žaláře pro Herodiadu manželku Filipa bratra svého.'),
(1569862,54,40,14,4,'Nebo byl řekl jemu Jan: Nesluší tobě míti jí.'),
(1569863,54,40,14,5,'A chtěv zabíti jej, bál se lidu; nebo za proroka jej měli.'),
(1569864,54,40,14,6,'Když pak slaven byl den narození Herodesova, tancovala dcera Herodiady uprostřed hodovníků, i líbilo se to Herodesovi,'),
(1569865,54,40,14,7,'Tak že s přísahou zaslíbil jí dáti, zač by ho prosila.'),
(1569866,54,40,14,8,'A ona jsuci prve navedena od mateře své, řekla: Dej mi zde na míse hlavu Jana Křtitele.'),
(1569867,54,40,14,9,'I zarmoutil se král, ale pro přísahu a pro ty, kteříž spolu s ním stolili, rozkázal jí dáti.'),
(1569868,54,40,14,10,'A poslav kata, sťal Jana v žaláři.'),
(1569869,54,40,14,11,'I přinesena jest hlava jeho na míse, a dána děvečce. A ona nesla ji mateři své.'),
(1569870,54,40,14,12,'A přišedše učedlníci jeho, vzali tělo jeho a pochovali je; a šedše, pověděli to Ježíšovi.'),
(1569871,54,40,14,13,'A uslyšev to Ježíš, plavil se odtud na lodičce na místo pusté soukromí. A uslyševše o tom zástupové, šli za ním pěšky z měst.'),
(1569872,54,40,14,14,'A vyšed Ježíš, uzřel zástup mnohý. I slitovalo mu se jich, a uzdravoval nemocné jejich.'),
(1569873,54,40,14,15,'A když bylo k večerou, přistoupili k němu učedlníci jeho, řkouce: Pusté jest místo toto, a čas již pominul. Rozpusť zástupy, ať jdouce do městeček, nakoupí sobě pokrmů.'),
(1569874,54,40,14,16,'Ježíš pak řekl jim: Není potřebí odcházeti, dejte vy jim jísti.'),
(1569875,54,40,14,17,'A oni řkou jemu: Nemáme zde, než pět chlebů a dvě rybě.'),
(1569876,54,40,14,18,'Kterýžto dí jim: Přinestež mi je sem.'),
(1569877,54,40,14,19,'A rozkázav zástupu posaditi se na trávě a vzav pět chlebů a dvě rybě, vzhléd v nebe, požehnal, a lámaje, dal učedlníkům chleby, a učedlníci zástupům.'),
(1569878,54,40,14,20,'I jedli všickni a nasyceni jsou. I sebrali pozůstalých drobtů, dvanácte košů plných.'),
(1569879,54,40,14,21,'Těch pak, kteříž jedli, bylo okolo pěti tisíců mužů, kromě žen a dětí.'),
(1569880,54,40,14,22,'A ihned přinutil učedlníky své, aby vstoupili na lodí a předešli jej za moře, dokudž by nerozpustil zástupů.'),
(1569881,54,40,14,23,'A rozpustiv zástupy, vstoupil na horu soukromí, aby se modlil. A když byl večer, sám byl tam.'),
(1569882,54,40,14,24,'Lodí pak již byla uprostřed moře, zmítající se vlnami, nebo byl vítr odporný jim.'),
(1569883,54,40,14,25,'Při čtvrtém pak bdění nočním bral se k nim Ježíš, jda po moři.'),
(1569884,54,40,14,26,'A vidouce jej učedlníci po moři jdoucího, zarmoutili se, řkouce: Obluda jest. A strachem křičeli.'),
(1569885,54,40,14,27,'Ale ihned Ježíš promluvil k nim, řka: Doufejtež, jáť jsem, nebojte se.'),
(1569886,54,40,14,28,'I odpověděv Petr, řekl: Pane, jsi-li ty, rozkažiž mi k sobě přijíti po vodě.'),
(1569887,54,40,14,29,'A on řekl: Pojď. A vystoupiv Petr z lodí, šel po vodě, aby přišel k Ježíšovi.'),
(1569888,54,40,14,30,'Ale vida vítr tuhý, bál se. A počav tonouti, zkřikl, řka: Pane, pomoz mi.'),
(1569889,54,40,14,31,'A ihned Ježíš vztáh ruku, ujal jej a řekl jemu: Malé víry, pročežs pochyboval?'),
(1569890,54,40,14,32,'A jakž oni vstoupili na lodí, přestal vítr.'),
(1569891,54,40,14,33,'Ti pak, kteříž na lodí byli, přistoupivše, klaněli se jemu, řkouce: Jistě Syn Boží jsi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569892,54,40,14,34,'A přeplavivše se, přišli do země Genezaretské.'),
(1569893,54,40,14,35,'A poznavše jej muži místa toho, rozeslali po vší té krajině vůkol, a shromáždili k němu všecky neduživé.'),
(1569894,54,40,14,36,'A prosili ho, aby se aspoň podolka roucha jeho dotkli. A kteřížkoli dotkli se, uzdraveni jsou.'),
(1569895,54,40,15,1,'A v tom přistoupí k Ježíšovi Jeruzalémští zákoníci a farizeové, řkouce:'),
(1569896,54,40,15,2,'Proč učedlníci tvoji přestupují ustanovení starších? Nebo neumývají rukou svých, když mají jísti chléb.'),
(1569897,54,40,15,3,'A on odpovídaje, řekl jim: Pročež i vy přestupujete přikázání Boží pro ustanovení vaše?'),
(1569898,54,40,15,4,'Nebo přikázal Bůh, řka: Cti otce svého i matku, a kdož by zlořečil otci neb mateři, smrtí ať umře.'),
(1569899,54,40,15,5,'Ale vy pravíte: Kdož by koli řekl otci neb mateři: Dar ode mne obětovaný, tobě prospěje, by pak i neuctil otce svého neb mateře své, bez viny bude.'),
(1569900,54,40,15,6,'A takž zrušili jste přikázání Boží pro své ustanovení.'),
(1569901,54,40,15,7,'Pokrytci, dobře prorokoval o vás Izaiáš, řka:'),
(1569902,54,40,15,8,'Přibližuje se ke mně lid tento ústy svými a rty mne ctí, ale srdce jejich daleko jest ode mne.'),
(1569903,54,40,15,9,'Nadarmoť mne ctí, učíce učení, jenž jsou přikázání lidská.'),
(1569904,54,40,15,10,'A svolav zástup, řekl jim: Slyšte a rozumějte.'),
(1569905,54,40,15,11,'Ne to, což vchází v ústa, poskvrňuje člověka, ale což z úst pochází, toť poskvrňuje člověka.'),
(1569906,54,40,15,12,'Tehdy přistoupivše učedlníci jeho, řekli mu: Víš-li, že farizeové, slyševše tu řeč, zhoršili se?'),
(1569907,54,40,15,13,'A on odpovídaje, řekl: Všeliké štípení, jehož neštípil Otec můj nebeský, vykořeněno bude.'),
(1569908,54,40,15,14,'Nechte jich, vůdcovéť jsou slepí slepých, a povede-li slepý slepého, oba v jámu upadnou.'),
(1569909,54,40,15,15,'I odpověděv Petr, řekl jemu: Vylož nám to podobenství.'),
(1569910,54,40,15,16,'Ježíš pak řekl: Ještě i vy bez rozumu jste?'),
(1569911,54,40,15,17,'Nerozumíte-liž, že všecko, což v ústa vchází, do břicha jde a vypouští se ven?'),
(1569912,54,40,15,18,'Ale které věci z úst pocházejí, z srdce jdou, a tyť poskvrňují člověka.'),
(1569913,54,40,15,19,'Z srdceť zajisté vycházejí zlá myšlení, vraždy, cizoložstva, smilstva, krádeže, křivá svědectví, rouhání.'),
(1569914,54,40,15,20,'Tyť jsou věci poskvrňující člověka. Ale neumytýma rukama jísti, toť neposkvrňuje člověka.'),
(1569915,54,40,15,21,'A vyšed odtud Ježíš, bral se do krajin Tyrských a Sidonských.'),
(1569916,54,40,15,22,'A aj, žena Kananejská z končin těch vyšedši, volala za ním, řkuci: Smiluj se nade mnou, Pane, synu Davidův. Dceru mou hrozně trápí ďábelství.'),
(1569917,54,40,15,23,'Kterýžto neodpověděl jí slova. I přistoupivše učedlníci jeho, prosili ho, řkouce: Propusť ji, neboť volá za námi.'),
(1569918,54,40,15,24,'On pak odpověděv, řekl: Nejsem poslán než k ovcem zahynulým z domu Izraelského.'),
(1569919,54,40,15,25,'Ale ona přistoupivši, klaněla se jemu, řkuci: Pane, pomoz mi.'),
(1569920,54,40,15,26,'On pak odpověděv, řekl: Není slušné vzíti chléb synů a vrci štěňatům.'),
(1569921,54,40,15,27,'A ona řekla: Takť jest, Pane. Avšak štěňata jedí drobty, kteříž padají z stolů pánů jejich.'),
(1569922,54,40,15,28,'Tedy odpovídaje Ježíš, řekl jí: Ó ženo, veliká jest víra tvá. Staniž se tobě, jakž chceš. I uzdravena jest dcera její v tu hodinu.'),
(1569923,54,40,15,29,'A odšed odtud Ježíš, šel podle moře Galilejského, a vstoupiv na horu, posadil se tam.'),
(1569924,54,40,15,30,'I přišli k němu zástupové mnozí, majíce s sebou kulhavé, slepé, němé, polámané a jiné mnohé. I kladli je k nohám Ježíšovým, a on uzdravil je,'),
(1569925,54,40,15,31,'Takže se zástupové divili, vidouce, ano němí mluví, polámaní zdraví jsou, kulhaví chodí, slepí vidí. I velebili Boha Izraelského.'),
(1569926,54,40,15,32,'Ježíš pak svolav učedlníky své, řekl: Líto mi zástupu, ješto již tři dni trvají se mnou a nemají, co by jedli; a rozpustiti jich lačných nechci, aby nezhynuli na cestě.'),
(1569927,54,40,15,33,'I řekli mu učedlníci jeho: I kde bychom vzali tolik chleba na této poušti, abychom takový zástup nasytili?'),
(1569928,54,40,15,34,'I řekl jim Ježíš: Kolik chlebů máte? A oni řkou: Sedm a málo rybiček.'),
(1569929,54,40,15,35,'I rozkázal zástupům, aby se posadili na zemi.'),
(1569930,54,40,15,36,'A vzav těch sedm chlebů a ryby, učiniv díky, lámal a dal učedlníkům svým, a učedlníci zástupu.'),
(1569931,54,40,15,37,'I jedli všickni a nasyceni jsou. A sebrali, což zbylo drobtů, sedm košů plných.'),
(1569932,54,40,15,38,'Bylo pak těch, kteříž jedli, čtyři tisíce mužů kromě žen a dětí.'),
(1569933,54,40,15,39,'A rozpustiv zástupy, vstoupil na lodí. I přišel do krajiny Magdala.'),
(1569934,54,40,16,1,'I přistoupili k němu farizeové a saduceové, a pokoušejíce, prosili ho, aby jim znamení s nebe ukázal.'),
(1569935,54,40,16,2,'On pak odpovídaje, řekl jim: Když bývá večer, říkáte: Jasno bude, nebo se červená nebe.'),
(1569936,54,40,16,3,'A ráno: Dnes bude nečas, nebo se červená zasmušilé nebe. Pokrytci, způsob zajisté nebe rozsouditi umíte, znamení pak časů nemůžete souditi?'),
(1569937,54,40,16,4,'Národ zlý a cizoložný znamení hledá, ale znamení jemu nebude dáno, než toliko znamení Jonáše proroka. A opustiv je, odšel.'),
(1569938,54,40,16,5,'A přeplavivše se učedlníci jeho přes moře, zapomenuli vzíti chleba.'),
(1569939,54,40,16,6,'Ježíš pak řekl jim: Hleďte a varujte se kvasu farizejského a saducejského.'),
(1569940,54,40,16,7,'Oni pak rozjímali mezi sebou, řkouce: Nevzali jsme chleba.'),
(1569941,54,40,16,8,'A znaje to Ježíš, řekl jim: Co to rozjímáte mezi sebou, ó malé víry, že jste chlebů nevzali?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569942,54,40,16,9,'Ještě-liž nerozumíte, ani pamatujete na pět chlebů, jimiž nasyceno bylo pět tisíců lidu, a kolik jste košů drobtů sebrali?'),
(1569943,54,40,16,10,'Ani na sedm chlebů, jimiž nasyceno bylo čtyři tísíce lidí, a kolik jste košů drobtů sebrali?'),
(1569944,54,40,16,11,'I kterakž pak nerozumíte, že ne o chlebu mluvil jsem vám, pravě: Varujte se od kvasu farizejského a saducejského?'),
(1569945,54,40,16,12,'Tedy srozuměli, že neřekl, aby se varovali od kvasu chleba, ale od učení farizeů a saduceů.'),
(1569946,54,40,16,13,'Přišed pak Ježíš do krajin Cesaree Filipovy, otázal se učedlníků svých, řka: Kým mne praví lidé býti, mne Syna člověka?'),
(1569947,54,40,16,14,'A oni řekli: Někteří Janem Křtitelem, a jiní Eliášem, jiní pak Jeremiášem, aneb jedním z proroků.'),
(1569948,54,40,16,15,'I dí jim: Vy pak kým mne býti pravíte?'),
(1569949,54,40,16,16,'I odpověděv Šimon Petr, řekl: Ty jsi Kristus, Syn Boha živého.'),
(1569950,54,40,16,17,'A odpovídaje Ježíš, řekl mu: Blahoslavený jsi Šimone, synu Jonášův; nebo tělo a krev nezjevilo tobě toho, ale Otec můj, kterýž jest v nebesích.'),
(1569951,54,40,16,18,'I jáť pravím tobě, že jsi ty Petr, a na téť skále vzdělám církev svou, a brány pekelné nepřemohou jí.'),
(1569952,54,40,16,19,'A tobě dám klíče království nebeského. A což bys koli svázal na zemi, budeť svázáno i na nebi; a což bys koli rozvázal na zemi, budeť rozvázáno i na nebi.'),
(1569953,54,40,16,20,'Tedy přikázal učedlníkům svým, aby žádnému nepravili, že by on byl ten Ježíš Kristus.'),
(1569954,54,40,16,21,'A od té chvíle počal Ježíš oznamovati učedlníkům svým, že musí jíti do Jeruzaléma, a mnoho trpěti od starších a předních kněží a od zákonníků, a zabit býti, a třetího dne z mrtvých vstáti.'),
(1569955,54,40,16,22,'I odved ho Petr na stranu, počal mu přimlouvati, řka: Odstup to od tebe, Pane, nestaneť se tobě toho.'),
(1569956,54,40,16,23,'Kterýžto obrátiv se, řekl Petrovi: Jdiž za mnou, satane, ku pohoršení jsi mi; nebo nechápáš těch věcí, kteréž jsou Boží, ale kteréž jsou lidské.'),
(1569957,54,40,16,24,'Tedy řekl Ježíš učedlníkům svým: Chce-li kdo za mnou přijíti, zapřiž sebe sám, a vezmi kříž svůj, a následujž mne.'),
(1569958,54,40,16,25,'Nebo kdož by chtěl duši svou zachovati, ztratíť ji; kdož by pak ztratil duši svou pro mne, nalezneť ji.'),
(1569959,54,40,16,26,'Nebo co jest platno člověku, by pak všecken svět získal, a své duši uškodil? Aneb kterou dá člověk odměnu za duši svou?'),
(1569960,54,40,16,27,'Syn zajisté člověka přijde v slávě Otce svého s anděly svými, a tehdážť odplatí jednomu každému podle skutků jeho.'),
(1569961,54,40,16,28,'Amen pravím vám: Jsou někteří z stojících tuto, kteříž neokusí smrti, až i uzří Syna člověka, přicházejícího v království svém.'),
(1569962,54,40,17,1,'A po šesti dnech pojal Ježíš Petra a Jakuba a Jana bratra jeho, i uvedl je na horu vysokou soukromí,'),
(1569963,54,40,17,2,'A proměnil se před nimi. I zastkvěla se tvář jeho jako slunce, a roucho jeho učiněno bílé jako světlo.'),
(1569964,54,40,17,3,'A aj, ukázali se jim Mojžíš a Eliáš, rozmlouvající s ním.'),
(1569965,54,40,17,4,'A odpověděv Petr, řekl Ježíšovi: Pane, dobré jest nám tuto býti. Chceš-li, udělejme tuto tři stánky, tobě jeden a Mojžíšovi jeden a Eliášovi jeden.'),
(1569966,54,40,17,5,'Když pak on ještě mluvil, aj, oblak světlý zastínil je. A aj, zavzněl hlas z oblaku řkoucí: Toto jest ten můj milý Syn, v němž mi se dobře zalíbilo, toho poslouchejte.'),
(1569967,54,40,17,6,'To uslyšavše učedlníci, padli na tváři své a báli se velmi.'),
(1569968,54,40,17,7,'A přistoupiv Ježíš, dotekl se jich, řka jim: Vstaňte, nebojte se.'),
(1569969,54,40,17,8,'A pozdvihše očí svých, žádného neviděli, než samého Ježíše.'),
(1569970,54,40,17,9,'Když pak sstupovali s hory, přikázal jim Ježíš, řka: Žádnému nepravte tohoto vidění, dokudž by Syn člověka nevstal z mrtvých.'),
(1569971,54,40,17,10,'I otázali se ho učedlníci jeho, řkouce: Což to pak zákoníci praví, že má Eliáš prve přijíti?'),
(1569972,54,40,17,11,'A Ježíš odpovídaje, řekl jim: Eliáš zajisté přijde prve a napraví všecky věci.'),
(1569973,54,40,17,12,'Ale pravím vám, že Eliáš již přišel, avšak nepoznali ho, ale učinili mu, což chtěli. Takť i Syn člověka trpěti bude od nich.'),
(1569974,54,40,17,13,'Tedy srozuměli učedlníci, že jim to praví o Janovi Křtiteli.'),
(1569975,54,40,17,14,'A když přišli k zástupu, přistoupil k němu člověk jeden, a poklekl před ním na kolena,'),
(1569976,54,40,17,15,'A řekl: Pane, smiluj se nad synem mým, nebo náměsičník jest, a bídně se trápí. Často zajisté padá do ohně a častokrát do vody.'),
(1569977,54,40,17,16,'I přivedl jsem ho učedlníkům tvým, ale nemohli ho uzdraviti.'),
(1569978,54,40,17,17,'Odpovídaje pak Ježíš, řekl: Ó národe nevěrný a převrácený, dokud budu s vámi? Dokudž vás trpěti budu? Přiveďte jej sem ke mně.'),
(1569979,54,40,17,18,'I pohrozil jemu Ježíš. I vyšlo od něho ďábelství a uzdraven jest mládenec v tu hodinu.'),
(1569980,54,40,17,19,'Tedy přistoupivše učedlníci k Ježíšovi soukromí, řekli jemu: Proč jsme my ho nemohli vyvrci?'),
(1569981,54,40,17,20,'Řekl jim Ježíš: Pro nevěru vaši. Amen zajisté pravím vám: Budete-li míti víru, jako jest zrno horčičné, díte hoře této: Jdi odsud tam, a půjde, a nebudeť vám nic nemožného.'),
(1569982,54,40,17,21,'Toto pak pokolení nevychází, jediné skrze modlitbu a půst.'),
(1569983,54,40,17,22,'A když byli v Galileji, řekl jim Ježíš: Syn člověka bude zrazen v ruce lidí bezbožných.'),
(1569984,54,40,17,23,'A zabijíť jej, a třetího dne z mrtvých vstane. I zarmoutili se náramně.'),
(1569985,54,40,17,24,'A když přišli do Kafarnaum, přistoupili, kteříž plat vybírali, ku Petrovi a řekli: Což mistr váš nedává platu?'),
(1569986,54,40,17,25,'A on řekl: Dává. A když všel do domu, předšel jej Ježíš řečí, řka: Co se tobě zdá, Šimone? Králové zemští od kterých berou daň anebo plat, od synů-li svých, čili od cizích?'),
(1569987,54,40,17,26,'Odpověděl jemu Petr: Od cizích. I dí mu Ježíš: Tedy synové jsou svobodní?'),
(1569988,54,40,17,27,'Ale abychom jich nepohoršili, jda k moři, vrz udici, a tu rybu, kteráž nejprve uvázne, vezmi, a otevra ústa její, nalezneš groš. Ten vezma, dej jim za mne i za sebe.'),
(1569989,54,40,18,1,'V ten čas přistoupili učedlníci k Ježíšovi, řkouce: Kdo pak jest větší v království nebeském?'),
(1569990,54,40,18,2,'A zavolav Ježíš pacholete, postavil je uprostřed nich,'),
(1569991,54,40,18,3,'A řekl: Amen pravím vám: Neobrátíte-li se a nebudete-li jako pacholátka, nikoli nevejdete do království nebeského.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1569992,54,40,18,4,'Protož kdož by se koli ponížil jako pacholátko toto, tenť jest větší v království nebeském.'),
(1569993,54,40,18,5,'A kdož by koli přijal pacholátko takové ve jménu mém, mneť přijímá.'),
(1569994,54,40,18,6,'Kdo by pak pohoršil jednoho z maličkých těchto věřících ve mne, lépe by jemu bylo, aby zavěšen byl žernov osličí na hrdlo jeho, a pohřížen byl do hlubokosti mořské.'),
(1569995,54,40,18,7,'Běda světu pro pohoršení. Ačkoli musí to býti, aby přicházela pohoršení, ale však běda člověku, skrze něhož přichází pohoršení.'),
(1569996,54,40,18,8,'Protož jestliže ruka tvá anebo noha tvá pohoršuje tě, utniž ji a vrz od sebe. Lépe jest tobě do života vjíti kulhavému anebo bezrukému, nežli dvě ruce aneb dvě noze majícímu uvrženu býti do věčného ohně.'),
(1569997,54,40,18,9,'A pakli oko tvé pohoršuje tebe, vylup je a vrz od sebe. Lépe jest tobě jednookému do života vjíti, nežli obě oči majícímu uvrženu býti do pekelného ohně.'),
(1569998,54,40,18,10,'Viztež, abyste nepotupovali ani jednoho z maličkých těchto. Neboť pravím vám, že andělé jejich v nebesích vždycky vidí tvář Otce mého, kterýž v nebesích jest.'),
(1569999,54,40,18,11,'Nebo přišel Syn člověka, aby spasil to, což bylo zahynulo.'),
(1570000,54,40,18,12,'Co se vám zdá? Kdyby některý člověk měl sto ovec, a zbloudila by jedna z nich, zdaliž nenechá devadesáti devíti, a jda na hory, nehledá té pobloudilé?'),
(1570001,54,40,18,13,'A nahodí-liť mu se nalézti ji, amen pravím vám, že se radovati bude nad ní více, než nad devadesáti devíti nepobloudilými.'),
(1570002,54,40,18,14,'Takť není vůle před Otcem vaším, kterýž jest v nebesích, aby zhynul jeden z maličkých těchto.'),
(1570003,54,40,18,15,'Zhřešil-li by pak proti tobě bratr tvůj, jdi a potresci ho mezi sebou a jím samým. Uposlechl-li by tebe, získal jsi bratra svého.'),
(1570004,54,40,18,16,'Jestliže by pak neuposlechl, přijmi k sobě jednoho anebo dva, aby v ústech dvou nebo tří svědků stálo každé slovo.'),
(1570005,54,40,18,17,'Pakliť by jich neuposlechl, pověz církvi. Jestliže pak i církve neuposlechne, budiž tobě jako pohan a publikán.'),
(1570006,54,40,18,18,'Amen pravím vám: Cožkoli svížete na zemi, budeť svázáno i na nebi; a cožkoli rozvížete na zemi, budeť rozvázáno i na nebi.'),
(1570007,54,40,18,19,'Opět pravím vám: Jestliže by dva z vás svolili se na zemi o všelikou věc, za kterouž by koli prosili, staneť se jim od Otce mého nebeského.'),
(1570008,54,40,18,20,'Nebo kdežkoli shromáždí se dva nebo tři ve jménu mém, tuť jsem já uprostřed nich.'),
(1570009,54,40,18,21,'Tedy přistoupiv k němu Petr, řekl: Pane, kolikrát zhřeší proti mně bratr můj, a odpustím jemu? Do sedmilikrát?'),
(1570010,54,40,18,22,'I dí mu Ježíš: Nepravím tobě až do sedmikrát, ale až do sedmdesátikrát sedmkrát.'),
(1570011,54,40,18,23,'A protož podobno jest království nebeské člověku králi, kterýž chtěl počet klásti s služebníky svými.'),
(1570012,54,40,18,24,'A když počal počtu klásti, podán mu jeden, kterýž byl dlužen deset tisíců hřiven.'),
(1570013,54,40,18,25,'A když neměl čím zaplatiti, kázal jej pán jeho prodati, i ženu jeho i děti i všecko, což měl, a zaplatiti.'),
(1570014,54,40,18,26,'Tedy padna služebník ten, prosil ho, řka: Pane, poshověj mi, a všeckoť zaplatím tobě.'),
(1570015,54,40,18,27,'I slitovav se pán nad služebníkem tím, propustil ho a dluh jemu odpustil.'),
(1570016,54,40,18,28,'Vyšed pak služebník ten, nalezl jednoho z spoluslužebníků svých, kterýž mu byl dlužen sto peněz, a chopiv se ho, hrdloval se s ním, řka: Zaplať mi, cos dlužen.'),
(1570017,54,40,18,29,'Tedy padna spoluslužebník ten k nohám jeho, prosil ho, řka: Poshověj mi, a všeckoť zaplatím tobě.'),
(1570018,54,40,18,30,'On pak nechtěl, ale odšed, dal jej do žaláře, dokudž by nezaplatil dluhu.'),
(1570019,54,40,18,31,'Tedy vidouce spoluslužebníci, co se dálo, zarmoutili se velmi; a šedše, pověděli pánu svému všecko, co se bylo stalo.'),
(1570020,54,40,18,32,'Tehdy povolav ho pán jeho, dí mu: Služebníče zlý, všecken ten tvůj dluh odpustil jsem tobě, nebs mne prosil.'),
(1570021,54,40,18,33,'Zdaližs i ty neměl se smilovati nad spoluslužebníkem svým, jako i já smiloval jsem se nad tebou?'),
(1570022,54,40,18,34,'I rozhněvav se pán jeho, dal jej katům, dokudž by nezaplatil všeho, což mu byl dlužen.'),
(1570023,54,40,18,35,'Takť i Otec můj nebeský učiní vám, jestliže neodpustíte jeden každý bratru svému z srdcí vašich jejich provinění.'),
(1570024,54,40,19,1,'I stalo se, když dokonal Ježíš řeči tyto, bral se z Galilee, a přišel do končin Judských za Jordán.'),
(1570025,54,40,19,2,'I šli za ním zástupové mnozí, a uzdravil je tam.'),
(1570026,54,40,19,3,'I přistoupili k němu farizeové, pokoušejíce ho a řkouce jemu: Sluší-li člověku propustiti ženu svou z kterékoli příčiny?'),
(1570027,54,40,19,4,'On pak odpovídaje, řekl jim: Což jste nečtli, že ten, jenž stvořil člověka s počátku, muže a ženu učinil je?'),
(1570028,54,40,19,5,'A řekl: Protož opustí člověk otce i matku, a připojí se k manželce své, i budou dva jedno tělo.'),
(1570029,54,40,19,6,'A tak již nejsou dva, ale jedno tělo. A protož, což jest Bůh spojil, člověk nerozlučuj.'),
(1570030,54,40,19,7,'Řekli jemu: Pročež tedy Mojžíš rozkázal dáti list zapuzení a propustiti jí?'),
(1570031,54,40,19,8,'Dí jim: Mojžíš pro tvrdost srdce vašeho dopustil vám propouštěti manželky vaše, ale s počátku nebylo tak.'),
(1570032,54,40,19,9,'Protož pravím vám: Že kdožkoli propustil by manželku svou, (leč pro smilství) a jinou pojme, cizoloží, a kdož propuštěnou pojme, také cizoloží.'),
(1570033,54,40,19,10,'Řekli jemu učedlníci jeho: Poněvadž jest taková pře s manželkou, není dobré ženiti se.'),
(1570034,54,40,19,11,'On pak řekl jim: Ne všickniť chápají slova toho, ale ti toliko, jimž jest dáno.'),
(1570035,54,40,19,12,'Jsouť zajisté panicové, kteříž se tak z života matky zrodili; a jsouť panicové, kteříž učiněni jsou od lidí; a jsou panicové, kteříž se sami v panictví oddali pro království nebeské. Kdo může pochopiti, pochop.'),
(1570036,54,40,19,13,'Tehdy přineseny jsou k němu dítky, aby na ně ruce vzkládal a modlil se za ně. Učedlníci pak přimlouvali jim.'),
(1570037,54,40,19,14,'Ale Ježíš řekl jim: Nechte dítek a nebraňte jim jíti ke mně; nebo takovýchť jest království nebeské.'),
(1570038,54,40,19,15,'A po vzkládání na ně rukou odebral se odtud.'),
(1570039,54,40,19,16,'A aj, jeden přistoupiv, řekl jemu: Mistře dobrý, co dobrého budu činiti, abych měl život věčný?'),
(1570040,54,40,19,17,'A on řekl jemu: Co mne nazýváš dobrým? Žádný není dobrý, než jediný, totiž Bůh. Chceš-li pak vjíti do života, ostříhej přikázání.'),
(1570041,54,40,19,18,'Dí jemu: Kterých? A Ježíš řekl mu: Nezabiješ, nezcizoložíš, nepokradeš, nepromluvíš křivého svědectví,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570042,54,40,19,19,'Cti otce svého i matku, a milovati budeš bližního svého jako sebe samého.'),
(1570043,54,40,19,20,'Dí jemu mládenec: Všeho toho ostříhal jsem od své mladosti. Čehož mi se ještě nedostává?'),
(1570044,54,40,19,21,'Řekl mu Ježíš: Chceš-li dokonalým býti, jdiž a prodej statek svůj, a rozdej chudým, a budeš míti poklad v nebi, a pojď, následuj mne.'),
(1570045,54,40,19,22,'Uslyšev pak mládenec tu řeč, odšel, smuten jsa; nebo měl statku mnoho.'),
(1570046,54,40,19,23,'Tedy Ježíš řekl učedlníkům svým: Amen pravím vám, že bohatý nesnadně vejde do království nebeského.'),
(1570047,54,40,19,24,'A opět pravím vám: Snázeť jest velbloudu skrze ucho jehly projíti, nežli bohatému vjíti do království Božího.'),
(1570048,54,40,19,25,'A uslyšavše to učedlníci jeho, i užasli se velmi, řkouce: I kdož tedy může spasen býti?'),
(1570049,54,40,19,26,'A pohleděv na ně Ježíš, řekl jim: U lidíť jest to nemožné, ale u Boha všecko jest možné.'),
(1570050,54,40,19,27,'Tehdy odpověděv Petr, řekl mu: Aj, my opustili jsme všecky věci, a šli jsme za tebou. Což pak nám bude dáno za to?'),
(1570051,54,40,19,28,'A Ježíš řekl jim: Amen pravím vám, že vy, kteříž jste následovali mne, v druhém narození, když se posadí Syn člověka na trůnu velebnosti své, sednete i vy na dvanácti stolicích, soudíce dvanáctero pokolení Izraelské.'),
(1570052,54,40,19,29,'A každý, kdož opustil by domy, nebo bratry, neb sestry, neb otce, neb matku, nebo manželku, nebo syny, nebo pole pro jméno mé, stokrát více vezme, a život věčný dědičně obdrží.'),
(1570053,54,40,19,30,'Mnozí pak první budou poslední, a poslední první.'),
(1570054,54,40,20,1,'Nebo podobno jest království nebeské člověku hospodáři, kterýž vyšel na úsvitě, aby najal dělníky na vinici svou.'),
(1570055,54,40,20,2,'Smluviv pak s dělníky z peníze denního, odeslal je na vinici svou.'),
(1570056,54,40,20,3,'A vyšed okolo hodiny třetí, uzřel jiné, ani stojí na trhu zahálejíce.'),
(1570057,54,40,20,4,'I řekl jim: Jdětež i vy na vinici mou, a co bude spravedlivého, dám vám.'),
(1570058,54,40,20,5,'A oni šli. Opět vyšed při šesté a deváté hodině, učinil též.'),
(1570059,54,40,20,6,'Při jedenácté pak hodině vyšed, nalezl jiné, ani stojí zahálejíce. I řekl jim: Pročež tu stojíte, celý den zahálejíce?'),
(1570060,54,40,20,7,'Řkou jemu: Nebo nižádný nás nenajal. Dí jim: Jdětež i vy na vinici mou, a což by bylo spravedlivého, vezmete.'),
(1570061,54,40,20,8,'Večer pak řekl pán vinice šafáři svému: Zavolej dělníků a zaplať jim, počna od posledních až do prvních.'),
(1570062,54,40,20,9,'A přišedše ti, kteříž byli při jedenácté hodině najati, vzali jeden každý po penízi.'),
(1570063,54,40,20,10,'Přišedše pak první, domnívali se, že by více měli vzíti; ale vzali i oni jeden každý po penízi.'),
(1570064,54,40,20,11,'A vzavše, reptali proti hospodáři, řkouce:'),
(1570065,54,40,20,12,'Tito poslední jednu hodinu toliko dělali, a rovné jsi je nám učinil, kteříž jsme nesli břímě dne i horko.'),
(1570066,54,40,20,13,'On pak odpovídaje jednomu z nich, řekl: Příteli, nečiním tobě křivdy; však jsi z peníze denního smluvil se mnou.'),
(1570067,54,40,20,14,'Vezmiž, což tvého jest, a jdi předce. Já pak chci tomuto poslednímu dáti jako i tobě.'),
(1570068,54,40,20,15,'Zdaliž mi nesluší v mém učiniti, což chci? Čili oko tvé nešlechetné jest, že já dobrý jsem?'),
(1570069,54,40,20,16,'Takť budou poslední první, a první poslední; nebo mnoho jest povolaných, ale málo vyvolených.'),
(1570070,54,40,20,17,'A vstupuje Ježíš do Jeruzaléma, pojal dvanácte učedlníků svých soukromí na cestě, i řekl jim:'),
(1570071,54,40,20,18,'Aj, vstupujeme do Jeruzaléma, a Syn člověka vydán bude předním kněžím a zákoníkům, a odsoudí ho na smrt.'),
(1570072,54,40,20,19,'A vydadíť jej pohanům ku posmívání a k bičování a ukřižování; a třetího dne z mrtvých vstane.'),
(1570073,54,40,20,20,'Tedy přistoupila k němu matka synů Zebedeových s syny svými, klanějící se a prosecí něco od něho.'),
(1570074,54,40,20,21,'Kterýžto řekl jí: Co chceš? Řekla jemu: Rci, ať tito dva synové moji sednou, jeden na pravici tvé a druhý na levici, v království tvém.'),
(1570075,54,40,20,22,'Odpovídaje pak Ježíš, řekl: Nevíte, zač prosíte. Můžete-li píti kalich, kterýž já píti budu, a křtem, jímž já se křtím, křtěni býti? Řekli jemu: Můžeme.'),
(1570076,54,40,20,23,'Dí jim: Kalich zajisté můj píti budete, a křtem, jímž já se křtím, pokřtěni budete, ale seděti na pravici mé a na levici mé, neníť mé dáti vám, ale dáno bude těm, kterýmž připraveno jest od Otce mého.'),
(1570077,54,40,20,24,'A uslyšavše to deset učedlníků Páně, rozhněvali se na ty dva bratry.'),
(1570078,54,40,20,25,'Ale Ježíš svolav je, řekl: Víte, že knížata národů panují nad svými, a kteříž velicí jsou, moci užívají nad nimi.'),
(1570079,54,40,20,26,'Ne tak bude mezi vámi; ale kdožkoli chtěl by mezi vámi býti velikým, budiž služebník váš.'),
(1570080,54,40,20,27,'A kdož by koli mezi vámi chtěl býti první, budiž váš služebník;'),
(1570081,54,40,20,28,'Jako i Syn člověka nepřišel, aby jemu slouženo bylo, ale aby on sloužil a aby dal život svůj na vykoupení za mnohé.'),
(1570082,54,40,20,29,'A když vycházeli z Jericho, šel za ním zástup veliký.'),
(1570083,54,40,20,30,'A aj, dva slepí sedící u cesty, uslyševše, že by Ježíš tudy šel, zvolali, řkouce: Smiluj se nad námi, Pane, synu Davidův.'),
(1570084,54,40,20,31,'Zástup pak přimlouval jim, aby mlčeli. Oni pak více volali, řkouce: Smiluj se nad námi, Pane, synu Davidův.'),
(1570085,54,40,20,32,'I zastaviv se Ježíš, zavolal jich, a řekl: Co chcete, abych vám učinil?'),
(1570086,54,40,20,33,'Řkou jemu: Pane, ať se otevrou oči naše.'),
(1570087,54,40,20,34,'I slitovav se nad nimi Ježíš, dotekl se očí jejich, a ihned prohlédly oči jejich. A oni šli za ním.'),
(1570088,54,40,21,1,'A když se přiblížili k Jeruzalému, a přišli do Betfage k hoře Olivetské, tedy Ježíš poslal dva učedlníky své,'),
(1570089,54,40,21,2,'Řka jim: Jdětež do městečka, kteréž proti vám jest, a hned naleznete oslici přivázanou a oslátko s ní. Odvěžtež je a přiveďte ke mně.'),
(1570090,54,40,21,3,'A řekl-liť by kdo co vám, rcete, že Pán jich potřebuje, a hnedť propustí je.'),
(1570091,54,40,21,4,'Toto se pak všecko stalo, aby se naplnilo povědění skrze proroka, řkoucího:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570092,54,40,21,5,'Povězte dceři Sionské: Aj, král tvůj béře se tobě tichý, a sedě na oslici, a na oslátku té oslice jhu podrobené.'),
(1570093,54,40,21,6,'I jdouce učedlníci, a učinivše tak, jakož jim přikázal Ježíš,'),
(1570094,54,40,21,7,'Přivedli oslici i oslátko, a vložili na ně roucha svá, a jej navrchu posadili.'),
(1570095,54,40,21,8,'Mnohý pak zástup stlali roucha svá na cestě, jiní pak ratolesti z dříví sekali a metali na cestu.'),
(1570096,54,40,21,9,'A zástupové, kteříž napřed šli, i ti, kteříž nazad byli, volali, řkouce: Aj syn Davidův, Spasitel. Požehnaný, jenž se béře ve jménu Páně; spasiž nás ty, kterýž jsi na výsostech.'),
(1570097,54,40,21,10,'A když vjel do Jeruzaléma, zbouřilo se všecko město, řkouce: I kdo jest tento?'),
(1570098,54,40,21,11,'Zástupové pak pravili: Toto jest ten Ježíš, prorok od Nazarétu Galilejského.'),
(1570099,54,40,21,12,'I všel Ježíš do chrámu Božího, a vymítal všecky prodavače a kupce z chrámu, a stoly penězoměnců a stolice prodávajících holubice převracel,'),
(1570100,54,40,21,13,'A řekl jim: Psánoť jest: Dům můj dům modlitby slouti bude, ale vy učinili jste jej peleší lotrovskou.'),
(1570101,54,40,21,14,'I přistoupili k němu slepí a kulhaví v chrámě, i uzdravil je.'),
(1570102,54,40,21,15,'Vidouce pak přední kněží a zákoníci divy, kteréž činil, a dítky, any volají v chrámě a praví : Aj syn Davidův, Spasitel, rozhněvali se.'),
(1570103,54,40,21,16,'A řekli jemu: Slyšíš-liž, co tito praví? Ježíš pak řekl jim: I ovšem. Nikdá-liž jste nečtli, že z úst nemluvňátek a těch, jenž prsí požívají, dokonal jsi chválu?'),
(1570104,54,40,21,17,'A opustiv je, šel ven z města do Betany a tu zůstal.'),
(1570105,54,40,21,18,'Ráno pak navracuje se do města, zlačněl.'),
(1570106,54,40,21,19,'A vida jeden fíkový strom podle cesty, šel k němu, a nic na něm nenalezl, než listí toliko. I dí tomu stromu: Nikdy více neroď se z tebe ovoce na věky. I usechl jest hned fík ten.'),
(1570107,54,40,21,20,'A vidouce to učedlníci, divili se, řkouce: Kterak jest ihned usechl fík ten!'),
(1570108,54,40,21,21,'I odpověděv Ježíš, řekl jim: Amen pravím vám: Budete-li míti víru, a nebudete-li pochybovati, netoliko to, co se stalo fíkovému dřevu, učiníte, a kdybyste i této hoře řekli: Zdvihni se a vrz sebou do moře, staneť se.'),
(1570109,54,40,21,22,'A všecko, zač byste koli prosili na modlitbě, věříce, vezmete.'),
(1570110,54,40,21,23,'A když přišel do chrámu, přistoupili k němu přední kněží a starší lidu, když učil, řkouce: Jakou mocí tyto věci činíš? A kdo jest tobě tu moc dal?'),
(1570111,54,40,21,24,'Odpovídaje pak Ježíš, řekl jim: Otížiť se i já vás na jednu věc, kterouž povíte-li mi, i já vám povím, jakou mocí tyto věci činím.'),
(1570112,54,40,21,25,'Křest Janův odkud jest byl? S nebe-li, čili z lidí? A oni rozvažovali mezi sebou, řkouce: Díme-li: S nebe, díť nám: Proč jste pak nevěřili jemu?'),
(1570113,54,40,21,26,'Pakli díme: Z lidí, bojíme se zástupu. Nebo všickni měli Jana za proroka.'),
(1570114,54,40,21,27,'I odpovídajíce Ježíšovi, řekli: Nevíme. Řekl jim i on: Aniž já vám povím, jakou mocí tyto věci činím.'),
(1570115,54,40,21,28,'Ale co se vám zdá? Člověk jeden měl dva syny. A přistoupiv k prvnímu, řekl: Synu, jdi na vinici mou dnes a dělej.'),
(1570116,54,40,21,29,'A on odpověděv, řekl: Nechci. A potom usmysliv sobě, šel.'),
(1570117,54,40,21,30,'I přistoupiv k druhému, řekl jemu též. A on odpověděv, řekl: Jdu, pane. A nešel.'),
(1570118,54,40,21,31,'Který z těch dvou učinil vůli otcovu? Řekli jemu: První. Dí jim Ježíš: Amen pravím vám, že publikáni a nevěstky předcházejí vás do království Božího.'),
(1570119,54,40,21,32,'Nebo přišel k vám Jan cestou spravedlnosti, a neuvěřili jste mu, ale publikáni a nevěstky uvěřili jemu. Vy pak viděvše to, aniž jste potom usmyslili sobě, abyste věřili jemu.'),
(1570120,54,40,21,33,'Jiné podobenství slyšte: Byl jeden hospodář, kterýž vzdělal vinici, a opletl ji plotem, a vkopal v ní pres, a ustavěl věži, i pronajal ji vinařům, a odšel pryč přes pole.'),
(1570121,54,40,21,34,'A když se přiblížil čas ovoce, poslal služebníky své k vinařům, aby vzali užitky její.'),
(1570122,54,40,21,35,'Vinaři pak zjímavše služebníky jeho, jiného zmrskali, jiného zabili, a jiného ukamenovali.'),
(1570123,54,40,21,36,'Opět poslal jiných služebníků více nežli prve. I učinili jim též.'),
(1570124,54,40,21,37,'Naposledy pak poslal k nim syna svého, řka: Ostýchati se budou syna mého.'),
(1570125,54,40,21,38,'Vinaři pak uzřevše syna jeho, řekli mezi sebou: Tentoť jest dědic; pojďte, zabijme jej, a uvažme se v dědictví jeho.'),
(1570126,54,40,21,39,'I chytivše ho, vyvrhli jej ven z vinice a zabili.'),
(1570127,54,40,21,40,'Protož když přijde pán vinice, co učiní vinařům těm?'),
(1570128,54,40,21,41,'Řekli jemu: Zlé zle zatratí, a vinici svou pronajme jiným vinařům, kteříž budou vydávati jemu užitek časy svými.'),
(1570129,54,40,21,42,'Řekl jim Ježíš: Nikdy-li jste nečtli v Písmích: Kámen, kterýž jsou zavrhli dělníci, ten učiněn jest v hlavu úhlovou? Ode Pána stalo se toto, a jest divné před očima našima.'),
(1570130,54,40,21,43,'Protož pravím vám, že bude odjato od vás království Boží, a bude dáno lidu činícímu užitky jeho.'),
(1570131,54,40,21,44,'A kdož by padl na ten kámen, rozrazíť se; a na kohož upadne, setřeť jej.'),
(1570132,54,40,21,45,'A slyšavše přední kněží podobenství jeho, porozuměli, že by o nich mluvil.'),
(1570133,54,40,21,46,'I hledajíce ho jíti, báli se zástupů; neb ho měli za proroka.'),
(1570134,54,40,22,1,'I odpovídaje Ježíš, mluvil jim opět v podobenstvích, řka:'),
(1570135,54,40,22,2,'Podobno jest království nebeské člověku králi, kterýž učinil svadbu synu svému.'),
(1570136,54,40,22,3,'I poslal služebníky své, aby povolali pozvaných na svadbu; a oni nechtěli přijíti.'),
(1570137,54,40,22,4,'Opět poslal jiné služebníky, řka: Povězte pozvaným: Aj, oběd můj připravil jsem, volové moji a krmný dobytek zbit jest, a všecko hotovo. Pojďtež na svadbu.'),
(1570138,54,40,22,5,'Ale oni nedbavše na to, odešli, jiný do vsi své a jiný po kupectví svém.'),
(1570139,54,40,22,6,'Jiní pak zjímavše služebníky jeho a posměch jim učinivše, zmordovali.'),
(1570140,54,40,22,7,'A uslyšav to král, rozhněval se; a poslav vojska svá, zhubil vražedníky ty a město jejich zapálil.'),
(1570141,54,40,22,8,'Tedy řekl služebníkům svým: Svadba zajisté hotova jest, ale ti, kteříž pozváni byli, nebyli hodni.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570142,54,40,22,9,'Protož jděte na rozcestí, a kteréžkoli naleznete, zovtež na svadbu.'),
(1570143,54,40,22,10,'I vyšedše služebníci ti na cesty, shromáždili všecky, kteréžkoli nalezli, zlé i dobré. A naplněna jest svadba hodovníky.'),
(1570144,54,40,22,11,'Tedy všed král, aby pohleděl na hodovníky, uzřel tam člověka neoděného rouchem svadebním.'),
(1570145,54,40,22,12,'I řekl jemu: Příteli, kteraks ty sem všel, nemaje roucha svadebního? A on oněměl.'),
(1570146,54,40,22,13,'Tedy řekl král služebníkům: Svížíce ruce jeho i nohy, vezměte ho, a uvrztež jej do temností zevnitřních. Tamť bude pláč a škřipení zubů.'),
(1570147,54,40,22,14,'Nebo mnoho jest povolaných, ale málo vyvolených.'),
(1570148,54,40,22,15,'Tedy odšedše farizeové, radili se, jak by polapili jej v řeči.'),
(1570149,54,40,22,16,'I poslali k němu učedlníky své s herodiány, řkouce: Mistře, víme, že pravdomluvný jsi a cestě Boží v pravdě učíš a nedbáš na žádného; nebo nepatříš na osobu lidskou.'),
(1570150,54,40,22,17,'Protož pověz nám, co se tobě zdá: Sluší-li daň dáti císaři, čili nic?'),
(1570151,54,40,22,18,'Znaje pak Ježíš zlost jejich, řekl: Co mne pokoušíte, pokrytci?'),
(1570152,54,40,22,19,'Ukažte mi peníz daně. A oni podali mu peníze.'),
(1570153,54,40,22,20,'I řekl jim: Čí jest tento obraz a svrchu napsání?'),
(1570154,54,40,22,21,'Řekli mu: Císařův. Tedy dí jim: Dejtež, co jest císařova, císaři, a co jest Božího, Bohu.'),
(1570155,54,40,22,22,'To uslyšavše, divili se, a opustivše jej, odešli.'),
(1570156,54,40,22,23,'V ten den přišli k němu saduceové, kteříž praví, že není z mrtvých vstání. I otázali se ho,'),
(1570157,54,40,22,24,'Řkouce: Mistře, Mojžíš pověděl: Umřel-li by kdo, nemaje dětí, aby bratr jeho právem švagrovství pojal ženu jeho a vzbudil símě bratru svému.'),
(1570158,54,40,22,25,'I bylo u nás sedm bratrů. První pojav ženu, umřel, a nemaje semene, zůstavil ženu svou bratru svému.'),
(1570159,54,40,22,26,'Takž podobně i druhý, i třetí, až do sedmého.'),
(1570160,54,40,22,27,'Nejposléze pak po všech umřela i žena.'),
(1570161,54,40,22,28,'Protož při vzkříšení kterého z těch sedmi bude žena? Nebo všickni ji měli.'),
(1570162,54,40,22,29,'I odpověděv Ježíš, řekl jim: Bloudíte, neznajíce Písem ani moci Boží.'),
(1570163,54,40,22,30,'Však při vzkříšení ani se nebudou ženiti ani vdávati, ale budou jako andělé Boží v nebi.'),
(1570164,54,40,22,31,'O vzkříšení pak mrtvých zdaliž jste nečtli, co jest vám povědíno od Boha, kterýž takto dí:'),
(1570165,54,40,22,32,'Já jsem Bůh Abrahamův a Bůh Izákův a Bůh Jákobův; a Bůhť není Bůh mrtvých, ale živých.'),
(1570166,54,40,22,33,'A slyševše to zástupové, divili se učení jeho.'),
(1570167,54,40,22,34,'Farizeové pak uslyšavše, že by k mlčení přivedl saducejské, sešli se v jedno.'),
(1570168,54,40,22,35,'I otázal se ho jeden z nich zákoník nějaký, pokoušeje ho, a řka:'),
(1570169,54,40,22,36,'Mistře, které jest přikázání veliké v Zákoně?'),
(1570170,54,40,22,37,'I řekl mu Ježíš: Milovati budeš Pána Boha svého z celého srdce svého a ze vší duše své a ze vší mysli své.'),
(1570171,54,40,22,38,'To jest přední a veliké přikázání.'),
(1570172,54,40,22,39,'Druhé pak jest podobné tomu: Milovati budeš bližního svého jako sebe samého.'),
(1570173,54,40,22,40,'Na těch dvou přikázáních všecken Zákon záleží i Proroci.'),
(1570174,54,40,22,41,'A když se sešli farizeové, otázal se jich Ježíš,'),
(1570175,54,40,22,42,'Řka: Co se vám zdá o Kristu? Čí jest syn? Řkou jemu: Davidův.'),
(1570176,54,40,22,43,'Dí jim: Kterakž pak David v Duchu nazývá ho Pánem, řka:'),
(1570177,54,40,22,44,'Řekl Pán Pánu mému: Seď na pravici mé, dokavadž nepodložím nepřátel tvých, aby byli za podnože noh tvých?'),
(1570178,54,40,22,45,'Poněvadž tedy David Pánem ho nazývá, i kterakž syn jeho jest?'),
(1570179,54,40,22,46,'A nižádný nemohl jemu odpovědíti slova, aniž se odvážil kdo více od toho dne jeho se nač tázati.'),
(1570180,54,40,23,1,'Tedy Ježíš mluvil zástupům a učedlníkům svým,'),
(1570181,54,40,23,2,'Řka: Na stolici Mojžíšově posadili se zákoníci a farizeové.'),
(1570182,54,40,23,3,'Protož všecko, což by koli rozkázali vám zachovávati, zachovávejte a čiňte, ale podle skutků jejich nečiňte; neboť praví, a nečiní.'),
(1570183,54,40,23,4,'Svazujíť zajisté břemena těžká a nesnesitelná, a vzkládají na ramena lidská, ale prstem svým nechtí jimi ani pohnouti.'),
(1570184,54,40,23,5,'A všeckyť ty své skutky činí, aby byli vidíni od lidí. Rozšiřují zajisté nápisy své a veliké dělají podolky pláštů svých,'),
(1570185,54,40,23,6,'A milují přední místa na večeřích, a první stolice v školách,'),
(1570186,54,40,23,7,'A pozdravování na trhu, a aby byli nazýváni od lidí: Mistři, mistři.'),
(1570187,54,40,23,8,'Ale vy nebývejte nazýváni mistři; nebo jeden jest Mistr váš, totiž Kristus, vy pak všickni bratří jste.'),
(1570188,54,40,23,9,'A otce nenazývejte sobě na zemi; nebo jeden jest Otec váš, kterýž jest v nebesích.'),
(1570189,54,40,23,10,'Ani se nazývejte vůdcové; nebo jeden jest vůdce váš Kristus.'),
(1570190,54,40,23,11,'Ale kdo z vás větší jest, budeť služebníkem vaším.'),
(1570191,54,40,23,12,'Nebo kdož by se sám povyšoval, bude ponížen; a kdož by se ponížil, bude povýšen.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570192,54,40,23,13,'Ale běda vám, zákoníci a farizeové pokrytci, že zavíráte království nebeské před lidmi; nebo sami tam nevcházíte, ani těm, jenž by vjíti chtěli, vcházeti dopouštíte.'),
(1570193,54,40,23,14,'Běda vám, zákoníci a farizeové pokrytci, že zžíráte domy vdovské, za příčinou dlouhého modlení; protož těžší soud ponesete.'),
(1570194,54,40,23,15,'Běda vám, zákoníci a farizeové pokrytci, že obcházíte moře i zemi, abyste učinili jednoho novověrce, a když bude učiněn, učiníte jej syna zatracení, dvakrát více, nežli jste sami.'),
(1570195,54,40,23,16,'Běda vám, vůdcové slepí, kteříž říkáte: Přisáhl-li by kdo skrze chrám, to nic není; ale kdo by přisáhl skrze zlato chrámové, povinenť jest přísaze dosti činiti.'),
(1570196,54,40,23,17,'Blázni a slepci; nebo co jest většího, zlato-li, čili chrám, kterýž posvěcuje zlata?'),
(1570197,54,40,23,18,'A přisáhl-li by kdo skrze oltář, nic není; ale kdo by přisáhl skrze ten dar, kterýž jest na něm, povinen jest.'),
(1570198,54,40,23,19,'Blázni a slepci, i co jest většího, dar-li, čili oltář, kterýž posvěcuje daru?'),
(1570199,54,40,23,20,'A protož kdokoli přisahá skrze oltář, přisahá skrze něj, i skrze to všecko, což na něm jest .'),
(1570200,54,40,23,21,'A kdož přisahá skrze chrám, přisahá skrze něj, i skrze toho, kterýž přebývá v něm.'),
(1570201,54,40,23,22,'A kdož přisahá skrze nebe, přisahá skrze trůn Boží, i skrze toho, kterýž na něm sedí.'),
(1570202,54,40,23,23,'Běda vám, zákoníci a farizeové pokrytci, že dáváte desátky z máty a z kopru a z kmínu, a opouštíte to, což těžšího jest v Zákoně, totiž soud a milosrdenství a věrnost. Tyto věci měli jste činiti a oněch neopouštěti.'),
(1570203,54,40,23,24,'Vůdcové slepí, kteříž cedíte komára, velblouda pak požíráte.'),
(1570204,54,40,23,25,'Běda vám, zákoníci a farizeové pokrytci, že čistíte po vrchu konvice a mísy, a vnitř plno jest loupeže a nestředmosti.'),
(1570205,54,40,23,26,'Farizee slepče, vyčisť prve to, což vnitř jest v konvi a v míse, aby i to, což jest zevnitř, bylo čisto.'),
(1570206,54,40,23,27,'Běda vám, zákoníci a farizeové pokrytci, nebo jste se připodobnili hrobům zbíleným, kteříž ač se zdadí zevnitř krásní, ale vnitř jsou plní kostí umrlčích i vší nečistoty.'),
(1570207,54,40,23,28,'Tak i vy zevnitř zajisté zdáte se lidem spravedliví, ale vnitř plní jste pokrytství a nepravosti.'),
(1570208,54,40,23,29,'Běda vám, zákoníci a farizeové pokrytci, neboť vzděláváte hroby proroků a ozdobujete hroby spravedlivých,'),
(1570209,54,40,23,30,'A říkáte: Kdybychom byli za dnů otců našich, nebyli bychom účastníci jejich ve krvi proroků.'),
(1570210,54,40,23,31,'Protož osvědčujete sami proti sobě, že jste synové těch, kteříž proroky zmordovali.'),
(1570211,54,40,23,32,'I vy také naplňte míru otců svých.'),
(1570212,54,40,23,33,'Hadové, plémě ještěrčí, i jakž byste ušli odsudku do pekelného ohně?'),
(1570213,54,40,23,34,'Protož aj, já posílám k vám proroky a moudré a učitele, a vy z těch některé zmordujete a ukřižujete, a některé z nich bičovati budete v školách vašich, a budete je honiti z města do města,'),
(1570214,54,40,23,35,'Aby přišla na vás všeliká krev spravedlivá, vylitá na zemi, od krve Abele spravedlivého, až do krve Zachariáše syna Barachiášova, kteréhož jste zabili mezi chrámem a oltářem.'),
(1570215,54,40,23,36,'Amen pravím vám: Přijdou tyto všecky věci na pokolení toto.'),
(1570216,54,40,23,37,'Jeruzaléme, Jeruzaléme, mordéři proroků, a kterýž kamenuješ ty, jenž byli k tobě posíláni, kolikrát jsem chtěl shromážditi dítky tvé, tak jako slepice shromažďuje kuřátka svá pod křídla, a nechtěli jste.'),
(1570217,54,40,23,38,'Aj, zanecháváť se vám dům váš pustý.'),
(1570218,54,40,23,39,'Neboť pravím vám, že mne již více nikoli neuzříte od této chvíle, až i díte: Požehnaný, jenž se béře ve jménu Páně.'),
(1570219,54,40,24,1,'A vyšed Ježíš, bral se z chrámu; i přistoupili učedlníci jeho, aby ukázali jemu stavení chrámové.'),
(1570220,54,40,24,2,'Ježíš pak řekl jim: Vidíte-liž tyto všecky věci? Amen pravím vám: Nebude zůstaven tuto kámen na kameni, kterýž by nebyl zbořen.'),
(1570221,54,40,24,3,'A když se posadil na hoře Olivetské, přistoupili k němu učedlníci jeho soukromí, řkouce: Pověz nám, kdy to bude, a která znamení budou příchodu tvého a skonání světa?'),
(1570222,54,40,24,4,'I odpověděv Ježíš, řekl jim: Vizte, aby vás žádný nesvedl.'),
(1570223,54,40,24,5,'Nebo mnozí přijdou ve jménu mém, řkouce: Jáť jsem Kristus, a svedouť mnohé.'),
(1570224,54,40,24,6,'Budete slyšeti zajisté boje a pověsti bojů. Hleďtež, abyste se nekormoutili; nebo musí to všecko býti; ale ne ihned bude konec.'),
(1570225,54,40,24,7,'Nebo povstane národ proti národu a království proti království, a budou morové a hladové a zemětřesení po místech.'),
(1570226,54,40,24,8,'Ale tyto všecky věci jsou počátkové bolestí.'),
(1570227,54,40,24,9,'A tehdy vy budete souženi, a budou vás mordovati, a budete v nenávisti u všech národů pro jméno mé.'),
(1570228,54,40,24,10,'A tehdyť se zhorší mnozí a vespolek se budou zrazovati a nenáviděti.'),
(1570229,54,40,24,11,'A mnozí falešní proroci povstanou, a svedou mnohé.'),
(1570230,54,40,24,12,'A že rozmnožena bude nepravost, ustydneť láska mnohých.'),
(1570231,54,40,24,13,'Ale kdož by setrval až do konce, tenť spasen bude.'),
(1570232,54,40,24,14,'A budeť kázáno toto evangelium království po všem světě, na svědectví všem národům, a tehdážť přijde skonání.'),
(1570233,54,40,24,15,'Protož když uzříte ohavnost zpuštění, předpověděnou od Daniele proroka, ana stojí na místě svatém, (kdo čte, rozuměj,)'),
(1570234,54,40,24,16,'Tehdáž ti, kteříž by byli v Judstvu, nechť utekou k horám.'),
(1570235,54,40,24,17,'A kdo na střeše, nesstupuj dolů, aby něco vzal z domu svého.'),
(1570236,54,40,24,18,'A kdo na poli, nevracuj se zase, aby vzal roucha svá.'),
(1570237,54,40,24,19,'Běda pak těhotným a těm, kteréž kojí, v těch dnech.'),
(1570238,54,40,24,20,'Protož modlte se, aby utíkání vaše nebylo v zimě anebo v svátek.'),
(1570239,54,40,24,21,'Nebo bude tehdáž soužení veliké, jakéž nebylo od počátku světa až dosavad, aniž kdy potom bude.'),
(1570240,54,40,24,22,'A byť nebyli ukráceni dnové ti, nebyl by spasen nižádný člověk. Ale pro vyvolené ukráceni budou dnové ti.'),
(1570241,54,40,24,23,'Tehdy řekl-li by vám kdo: Aj, tutoť jest Kristus, anebo tamto, nevěřte.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570242,54,40,24,24,'Nebo povstanou falešní Kristové a falešní proroci, a činiti budou divy veliké a zázraky, tak aby v blud uvedli, (by možné bylo,) také i vyvolené.'),
(1570243,54,40,24,25,'Aj, předpověděl jsem vám.'),
(1570244,54,40,24,26,'Protož řeknou-liť vám: Aj, na poušti jest, nevycházejte. Aj, v skrýších, nevěřte.'),
(1570245,54,40,24,27,'Neb jakož blesk vychází od východu slunce, a ukazuje se až na západ, takť bude i příchod Syna člověka.'),
(1570246,54,40,24,28,'Neboť kdežkoli bude tělo, tuť se sletí i orlice.'),
(1570247,54,40,24,29,'A hned po soužení, kteréž bude těch dnů, slunce se zatmí a měsíc nedá světla svého a hvězdy budou padati s nebe a moci nebeské budou se pohybovati.'),
(1570248,54,40,24,30,'A tehdyť se ukáže znamení Syna člověka na nebi, a tuť budou kvíliti všecka pokolení země, a uzříť Syna člověka přicházejícího na oblacích nebeských s mocí a slavou velikou.'),
(1570249,54,40,24,31,'Kterýž pošle anděly své s hlasem velikým trouby, a shromáždíť vyvolené jeho ode čtyř větrů, od končin nebes až do končin jejich.'),
(1570250,54,40,24,32,'Od stromu pak fíkového naučte se podobenství: Když již ratolest jeho odmladne a listí se pučí, porozumíváte, že blízko jest léto.'),
(1570251,54,40,24,33,'Takéž i vy, když uzřeli byste toto všecko, vězte, žeť blízko jest a ve dveřích království Boží.'),
(1570252,54,40,24,34,'Amen pravím vám, že nepomine věk tento, až se tyto všecky věci stanou.'),
(1570253,54,40,24,35,'Nebe a země pominou, ale slova má nepominou.'),
(1570254,54,40,24,36,'O tom pak dni a hodině té nižádný neví, ani andělé nebeští, jediné sám Otec můj.'),
(1570255,54,40,24,37,'Ale jakož bylo za dnů Noé, takť bude i příchod Syna člověka.'),
(1570256,54,40,24,38,'Nebo jakož jsou za dnů těch před potopou žrali a pili, ženili se a vdávaly se, až do toho dne, když Noé všel do korábu,'),
(1570257,54,40,24,39,'A nezvěděli, až přišla potopa, a zachvátila všecky, takť bude i příští Syna člověka.'),
(1570258,54,40,24,40,'Tehdyť dva budou na poli; jeden bude vzat, a druhý zanechán.'),
(1570259,54,40,24,41,'Dvě budou ve mlýně při žernovu; jedna bude vzata, a druhá zanechána.'),
(1570260,54,40,24,42,'Bdětež tedy, poněvadž nevíte, v kterou hodinu Pán váš přijíti má.'),
(1570261,54,40,24,43,'Toto pak vězte, že byť věděl hospodář, v které by bdění zloděj měl přijíti, bděl by zajisté, a nedalť by podkopati domu svého.'),
(1570262,54,40,24,44,'Protož i vy buďte hotovi; nebo v tu hodinu, v kterouž se nenadějete, Syn člověka přijde.'),
(1570263,54,40,24,45,'Kdoť tedy jest služebník věrný a opatrný, kteréhož ustanovil pán jeho nad čeledí svou, aby jim dával pokrm v čas?'),
(1570264,54,40,24,46,'Blahoslavený služebník ten, kteréhož, přijda pán jeho, nalezl by, an tak činí.'),
(1570265,54,40,24,47,'Amen pravím vám, že nade vším statkem svým ustanoví jej.'),
(1570266,54,40,24,48,'Jestliže by pak řekl zlý služebník ten v srdci svém: Prodlévá pán můj přijíti,'),
(1570267,54,40,24,49,'I počal by bíti spoluslužebníky, jísti a píti s opilci,'),
(1570268,54,40,24,50,'Přijdeť pán služebníka toho v den, v kterýž se nenaděje, a v hodinu, v kterouž neví.'),
(1570269,54,40,24,51,'I oddělíť jej, a díl jeho položí s pokrytci. Tamť bude pláč a škřipení zubů.'),
(1570270,54,40,25,1,'Tehdy podobno bude království nebeské desíti pannám, kteréžto vzavše lampy své, vyšly proti Ženichovi.'),
(1570271,54,40,25,2,'Pět pak z nich bylo opatrných, a pět bláznivých.'),
(1570272,54,40,25,3,'Ty bláznivé vzavše lampy své, nevzaly s sebou oleje.'),
(1570273,54,40,25,4,'Opatrné pak vzaly olej v nádobkách svých s lampami svými.'),
(1570274,54,40,25,5,'A když prodléval Ženich, zdřímaly se všecky a zesnuly.'),
(1570275,54,40,25,6,'O půlnoci pak stal se křik: Aj, Ženich jde, vyjděte proti němu.'),
(1570276,54,40,25,7,'Tedy vstaly všecky panny ty, a ozdobily lampy své.'),
(1570277,54,40,25,8,'Bláznivé pak opatrným řekly: Udělte nám oleje vašeho, nebo lampy naše hasnou.'),
(1570278,54,40,25,9,'I odpověděly opatrné, řkouce: Bojíme se, že by se snad ani nám i vám nedostalo, jděte raději k prodavačům a kupte sobě.'),
(1570279,54,40,25,10,'A když odešly kupovati, přišel Ženich, a které hotovy byly, vešly s ním na svadbu, i zavříny jsou dveře.'),
(1570280,54,40,25,11,'Potom pak přišly i ty druhé panny, řkouce: Pane, pane, otevři nám.'),
(1570281,54,40,25,12,'A on odpověděv, řekl: Amen, pravím vám, neznámť vás.'),
(1570282,54,40,25,13,'Bdětež tedy; neb nevíte dne ani hodiny, v kterou Syn člověka přijde.'),
(1570283,54,40,25,14,'Neb tak se díti bude, jako když člověk jeden, jda na cestu, povolal služebníků svých a poručil jim statek svůj.'),
(1570284,54,40,25,15,'I dal jednomu pět hřiven, jinému pak dvě, a jinému jednu, každému podle možnosti jeho, i odšel hned.'),
(1570285,54,40,25,16,'Odšed pak ten, kterýž vzal pět hřiven, těžel jimi, i vydělal jiných pět hřiven.'),
(1570286,54,40,25,17,'Též i ten, kterýž vzal dvě, získal jiné dvě.'),
(1570287,54,40,25,18,'Ale ten, kterýž vzal jednu, odšed, zakopal ji v zemi, a skryl peníze pána svého.'),
(1570288,54,40,25,19,'Po mnohém pak času přišel pán služebníků těch, i činil počet s nimi.'),
(1570289,54,40,25,20,'A přistoupiv ten, kterýž byl pět hřiven vzal, podal jiných pěti hřiven, řka: Pane, pět hřiven dal jsi mi, aj, jiných pět hřiven získal jsem jimi.'),
(1570290,54,40,25,21,'I řekl mu pán jeho: To dobře, služebníče dobrý a věrný, nad málem byl jsi věrný, nad mnohem tebe ustanovím. Vejdiž v radost pána svého.'),
(1570291,54,40,25,22,'Přistoupiv pak ten, kterýž byl dvě hřivně vzal, dí: Pane, dvě hřivně jsi mi dal, aj, jiné dvě jimi získal jsem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570292,54,40,25,23,'Řekl mu pán jeho: To dobře, služebníče dobrý a věrný, nad málem byl jsi věrný, nad mnohem tebe ustanovím. Vejdiž v radost pána svého.'),
(1570293,54,40,25,24,'Přistoupiv pak i ten, kterýž vzal jednu hřivnu, řekl: Pane, věděl jsem, že jsi ty člověk přísný, žna, kde jsi nerozsíval, a sbíraje, kde jsi nerozsypal,'),
(1570294,54,40,25,25,'I boje se, odšel jsem a skryl hřivnu tvou v zemi. Aj, teď máš, což tvého jest.'),
(1570295,54,40,25,26,'A odpovídaje pán jeho, řekl mu: Služebníče zlý a lenivý, věděl jsi, že žnu, kdež jsem nerozsíval, a sbírám, kdež jsem nerozsypal,'),
(1570296,54,40,25,27,'Protož měl jsi ty peníze mé dáti penězoměncům, a já přijda, vzal byl bych, což jest mého, s požitkem.'),
(1570297,54,40,25,28,'Nu vezmětež od něho tu hřivnu, a dejte tomu, kterýž má deset hřiven.'),
(1570298,54,40,25,29,'(Nebo každému majícímu bude dáno, a budeť hojně míti, od nemajícího pak i to, což má, budeť odjato.)'),
(1570299,54,40,25,30,'A toho neužitečného služebníka uvrztež do temností zevnitřních. Tamť bude pláč a škřipení zubů.'),
(1570300,54,40,25,31,'A když přijde Syn člověka v slávě své, a všickni svatí andělé s ním, tedy se posadí na trůnu velebnosti své,'),
(1570301,54,40,25,32,'A shromážděni budou před něj všickni národové. I rozdělí je na různo, jedny od druhých, tak jako pastýř odděluje ovce od kozlů.'),
(1570302,54,40,25,33,'A postavíť ovce zajisté na pravici své, kozly pak na levici.'),
(1570303,54,40,25,34,'Tedy dí Král těm, kteříž na pravici jeho budou: Pojďte požehnaní Otce mého, dědičně vládněte královstvím, vám připraveným od ustanovení světa.'),
(1570304,54,40,25,35,'Nebo jsem lačněl, a dali jste mi jísti; žíznil jsem, a dali jste mi píti; hostem jsem býval, a přijali jste mne;'),
(1570305,54,40,25,36,'Nah jsem byl, a přioděli jste mne; nemocen jsem byl, a navštívili jste mne; v žaláři jsem seděl, a přicházeli jste ke mně.'),
(1570306,54,40,25,37,'Tedy odpovědí jemu spravedliví, řkouce: Pane, kdy jsme tě vídali lačného, a krmili jsme tebe, žíznivého, a dávaliť jsme nápoj?'),
(1570307,54,40,25,38,'Aneb kdy jsme tě viděli hostě, a přijali jsme tebe, anebo nahého, a přioděli jsme tebe?'),
(1570308,54,40,25,39,'Aneb kdy jsme tě viděli nemocného, aneb v žaláři, a přicházeli jsme k tobě?'),
(1570309,54,40,25,40,'A odpovídaje Král, dí jim: Amen pravím vám: Cožkoli jste činili jednomu z bratří těchto mých nejmenších, mně jste učinili.'),
(1570310,54,40,25,41,'Potom dí i těm, kteříž na levici budou: Jděte ode mne zlořečení do ohně věčného, kterýž jest připraven ďáblu i andělům jeho.'),
(1570311,54,40,25,42,'Neboť jsem lačněl, a nedali jste mi jísti; žíznil jsem, a nedali jste mi píti;'),
(1570312,54,40,25,43,'Hostem jsem byl, a nepřijali jste mne; nah, a neodívali jste mne; nemocen a v žaláři jsem byl, a nenavštívili jste mne.'),
(1570313,54,40,25,44,'Tedy odpovědí jemu i oni, řkouce: Pane, kdy jsme tebe vídali lačného, neb žíznivého, aneb hostě, nebo nahého, neb nemocného, aneb v žaláři, a neposloužili jsme tobě?'),
(1570314,54,40,25,45,'Tedy odpoví jim, řka: Amen pravím vám: Čehož jste koli nečinili jednomu z nejmenších těchto, mně jste nečinili.'),
(1570315,54,40,25,46,'I půjdou tito do trápení věčného, ale spravedliví do života věčného.'),
(1570316,54,40,26,1,'I stalo se, když dokonal Ježíš řeči tyto všecky, řekl učedlníkům svým:'),
(1570317,54,40,26,2,'Víte, že po dvou dnech velikanoc bude a Syn člověka zrazen bude, aby byl ukřižován.'),
(1570318,54,40,26,3,'Tedy sešli se přední kněží a zákoníci, i starší lidu na síň nejvyššího kněze, kterýž sloul Kaifáš.'),
(1570319,54,40,26,4,'A radili se, jak by Ježíše lstivě jali a zamordovali.'),
(1570320,54,40,26,5,'Ale pravili: Ne v den sváteční, aby snad nebyl rozbroj v lidu.'),
(1570321,54,40,26,6,'Když pak byl Ježíš v Betany, v domu Šimona malomocného,'),
(1570322,54,40,26,7,'Přistoupila k němu žena, mající nádobu alabastrovou masti drahé, i vylila ji na hlavu jeho, když seděl za stolem.'),
(1570323,54,40,26,8,'A vidouce to učedlníci jeho, rozhněvali se, řkouce: I k čemu jest ztráta tato?'),
(1570324,54,40,26,9,'Neb mohla tato mast prodána býti za mnoho, a dáno býti chudým.'),
(1570325,54,40,26,10,'A znaje to Ježíš, dí jim: Proč za zlé máte této ženě? Dobrý zajisté skutek učinila nade mnou.'),
(1570326,54,40,26,11,'Nebo chudé vždycky máte s sebou, ale mne ne vždycky míti budete.'),
(1570327,54,40,26,12,'Vylivši zajisté tato mast tuto na mé tělo, ku pohřebu mému to učinila.'),
(1570328,54,40,26,13,'Amen pravím vám: Kdežkoli kázáno bude evangelium toto po všem světě, takéť i to bude praveno, co učinila tato, na památku její.'),
(1570329,54,40,26,14,'Tedy odšed k předním kněžím, jeden ze dvanácti, kterýž sloul Jidáš Iškariotský,'),
(1570330,54,40,26,15,'Řekl jim: Co mi chcete dáti, a já vám ho zradím? A oni uložili jemu dáti třidceti stříbrných.'),
(1570331,54,40,26,16,'A od té chvíle hledal příhodného času, aby ho zradil.'),
(1570332,54,40,26,17,'Prvního pak dne přesnic, přistoupili k Ježíšovi učedlníci, řkouce jemu: Kde chceš, ať připravíme tobě, abys jedl beránka?'),
(1570333,54,40,26,18,'On pak řekl: Jděte tam k jednomu do města, a rcete jemu: Vzkázalť Mistr: Čas můj blízko jest, u tebeť jísti budu beránka s učedlníky svými.'),
(1570334,54,40,26,19,'I učinili učedlníci tak, jakož jim poručil Ježíš, a připravili beránka.'),
(1570335,54,40,26,20,'A když byl večer, posadil se za stůl se dvanácti.'),
(1570336,54,40,26,21,'A když jedli, řekl jim: Amen pravím vám, že jeden z vás mne zradí.'),
(1570337,54,40,26,22,'I zarmoutivše se velmi, počali každý z nich říci jemu: Zdali já jsem, Pane?'),
(1570338,54,40,26,23,'On pak odpovídaje, řekl: Kdo omáčí se mnou rukou v míse, tenť mne zradí.'),
(1570339,54,40,26,24,'Synť zajisté člověka jde, jakož psáno o něm, ale běda člověku tomu, skrze něhož Syn člověka zrazen bude. Dobré by bylo jemu, by se byl nenarodil člověk ten.'),
(1570340,54,40,26,25,'Odpovídaje pak Jidáš, kterýž ho zrazoval, dí: Zdali já jsem, Mistře? Řekl jemu: Ty jsi řekl.'),
(1570341,54,40,26,26,'A když oni jedli, vzav Ježíš chléb a dobrořečiv, lámal, a dal učedlníkům, a řekl: Vezměte, jezte, to jest tělo mé.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570342,54,40,26,27,'A vzav kalich, a díky činiv, dal jim, řka: Pijte z toho všickni.'),
(1570343,54,40,26,28,'Neb to jest krev má nové smlouvy, kteráž za mnohé vylévá se na odpuštění hříchů.'),
(1570344,54,40,26,29,'Ale pravímť vám, žeť nebudu píti již více z tohoto plodu vinného kořene, až do onoho dne, když jej píti budu s vámi nový v království Otce mého.'),
(1570345,54,40,26,30,'A sezpívavše písničku, vyšli na horu Olivetskou.'),
(1570346,54,40,26,31,'Tedy dí jim Ježíš: Všickni vy zhoršíte se nade mnou této noci. Nebo psáno jest: Bíti budu pastýře, a rozprchnouť se ovce stáda.'),
(1570347,54,40,26,32,'Ale když z mrtvých vstanu, předejdu vás do Galilee.'),
(1570348,54,40,26,33,'Odpovídaje pak Petr, řekl jemu: Byť se pak všickni zhoršili nad tebou, jáť se nikdy nezhorším.'),
(1570349,54,40,26,34,'Dí mu Ježíš: Amen pravím tobě, že této noci, prve než kohout zazpívá, třikrát mne zapříš.'),
(1570350,54,40,26,35,'Řekl jemu Petr: Bychť pak měl také s tebou umříti, nezapřím tebe. Takž podobně i všickni učedlníci pravili.'),
(1570351,54,40,26,36,'Tedy přišel s nimi Ježíš na místo, kteréž sloulo Getsemany. I dí učedlníkům: Poseďtež tuto, ažť odejda, pomodlím se tamto.'),
(1570352,54,40,26,37,'A pojav s sebou Petra a dva syny Zebedeovy, počal se rmoutiti a teskliv býti.'),
(1570353,54,40,26,38,'Tedy řekl jim: Smutnáť jest duše má až k smrti. Pozůstaňtež tuto a bděte se mnou.'),
(1570354,54,40,26,39,'A poodšed maličko, padl na tvář svou, modle se a řka: Otče můj, jest-li možné, nechť odejde ode mne kalich tento. Avšak ne jakž já chci, ale jakž ty chceš.'),
(1570355,54,40,26,40,'I přišel k učedlníkům, a nalezl je, ani spí. I řekl Petrovi: Tak-liž jste nemohli jediné hodiny bdíti se mnou?'),
(1570356,54,40,26,41,'Bdětež a modlte se, abyste nevešli v pokušení. Duchť zajisté hotov jest, ale tělo nemocno.'),
(1570357,54,40,26,42,'Opět po druhé odšed, modlil se, řka: Otče můj, nemůže-liť tento kalich minouti mne, než abych jej pil, staniž se vůle tvá.'),
(1570358,54,40,26,43,'I přišed k nim, nalezl je, a oni zase spí; nebo byly oči jejich obtíženy.'),
(1570359,54,40,26,44,'A nechav jich, opět odšel, a modlil se po třetí, touž řeč říkaje.'),
(1570360,54,40,26,45,'Tedy přišel k učedlníkům svým, a řekl jim: Spětež již a odpočívejte. Aj, přiblížila se hodina, a Syna člověka zrazují v ruce hříšných.'),
(1570361,54,40,26,46,'Vstaňtež, pojďme. Aj, přiblížil se ten, jenž mne zrazuje.'),
(1570362,54,40,26,47,'A když on ještě mluvil, aj, Jidáš, jeden ze dvanácti, přišel, a s ním zástup mnohý s meči a s kyjmi, poslaných od předních kněží a starších lidu.'),
(1570363,54,40,26,48,'Ten pak, jenž jej zrazoval, dal jim znamení, řka: Kteréhožťkoli políbím, ten jest; držtež jej.'),
(1570364,54,40,26,49,'A hned přistoupiv k Ježíšovi, řekl: Zdráv buď, Mistře, a políbil jej.'),
(1570365,54,40,26,50,'I řekl jemu Ježíš: Příteli, nač jsi přišel? Tedy přistoupili a ruce vztáhli na Ježíše a jali ho.'),
(1570366,54,40,26,51,'A aj, jeden z těch, kteříž byli s Ježíšem, vztáh ruku, vytrhl meč svůj; a udeřiv služebníka nejvyššího kněze, uťal ucho jeho.'),
(1570367,54,40,26,52,'Tedy dí jemu Ježíš: Obrať meč svůj v místo jeho; nebo všickni, kteříž meč berou, od meče zahynou.'),
(1570368,54,40,26,53,'Zdaliž mníš, že bych nyní nemohl prositi Otce svého, a vydal by mi více nežli dvanácte houfů andělů?'),
(1570369,54,40,26,54,'Ale kterak by se pak naplnila Písma, kteráž svědčí, že tak musí býti?'),
(1570370,54,40,26,55,'V tu hodinu řekl Ježíš k zástupům: Jako na lotra vyšli jste s meči a s kyjmi jímati mne. Na každý den sedával jsem u vás, uče v chrámě, a nejali jste mne.'),
(1570371,54,40,26,56,'Ale toto se všecko stalo, aby se naplnila Písma prorocká. Tedy učedlníci všickni opustivše ho, utekli.'),
(1570372,54,40,26,57,'A oni javše Ježíše, vedli ho k Kaifášovi nejvyššímu knězi, kdežto zákoníci a starší byli se sešli.'),
(1570373,54,40,26,58,'Ale Petr šel za ním zdaleka, až do síně nejvyššího kněze. A všed vnitř, seděl s služebníky, aby viděl všeho toho konec.'),
(1570374,54,40,26,59,'Přední pak kněží a starší a všecka ta rada hledali falešného svědectví proti Ježíšovi, aby jej na smrt vydali,'),
(1570375,54,40,26,60,'I nenalezli. A ačkoli mnozí falešní svědkové přistupovali, však nenalézali. Naposledy pak přišli dva falešní svědkové,'),
(1570376,54,40,26,61,'A řekli: Tento jest pověděl: Mohu zbořiti chrám Boží a ve třech dnech zase jej ustavěti.'),
(1570377,54,40,26,62,'A povstav nejvyšší kněz, řekl jemu: Nic neodpovídáš? Což pak tito proti tobě svědčí?'),
(1570378,54,40,26,63,'Ale Ježíš mlčel. I odpovídaje nejvyšší kněz, řekl k němu: Zaklínám tě skrze Boha živého, abys nám pověděl, jsi-li ty Kristus Syn Boží?'),
(1570379,54,40,26,64,'Dí mu Ježíš: Ty jsi řekl. Ale však pravím vám: Od toho času uzříte Syna člověka sedícího na pravici moci Boží a přicházejícího na oblacích nebeských.'),
(1570380,54,40,26,65,'Tedy nejvyšší kněz roztrhl roucho své, a řekl: Rouhal se. Což ještě potřebujeme svědků? Aj, nyní jste slyšeli rouhání jeho.'),
(1570381,54,40,26,66,'Co se vám zdá? A oni odpovídajíce, řekli: Hodenť jest smrti.'),
(1570382,54,40,26,67,'Tedy plili na tvář jeho a pohlavkovali jej; jiní pak hůlkami jej bili,'),
(1570383,54,40,26,68,'Říkajíce: Hádej nám, Kriste, kdo jest ten, kterýž tebe udeřil?'),
(1570384,54,40,26,69,'Ale Petr seděl vně v síni. I přistoupila k němu jedna děvečka, řkuci: I ty jsi byl s Ježíšem tím Galilejským.'),
(1570385,54,40,26,70,'On pak zapřel přede všemi, řka: Nevím, co pravíš.'),
(1570386,54,40,26,71,'A když vycházel ze dveří, uzřela jej jiná děvečka. I řekla těm, kteříž tu byli: I tento byl s Ježíšem tím Nazaretským.'),
(1570387,54,40,26,72,'A on opět zapřel s přísahou, řka: Neznám toho člověka.'),
(1570388,54,40,26,73,'A po malé chvíli přistoupili blíže, kteříž tu stáli, i řekli Petrovi: Jistě i ty z nich jsi, neb i řeč tvá známa tebe činí.'),
(1570389,54,40,26,74,'Tedy počal se proklínati a přisahati, řka: Neznám toho člověka. A hned kohout zazpíval.'),
(1570390,54,40,26,75,'I rozpomenul se Petr na slovo Ježíšovo, kterýž jemu byl řekl: Že prve než kohout zazpívá, třikrát mne zapříš. A vyšed ven, plakal hořce.'),
(1570391,54,40,27,1,'A když bylo ráno, vešli v radu všickni přední kněží a starší lidu proti Ježíšovi, aby jej na smrt vydali.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570392,54,40,27,2,'I svázavše jej, vedli, a vydali ho Pontskému Pilátovi hejtmanu.'),
(1570393,54,40,27,3,'Tedy vida Jidáš, zrádce jeho, že by odsouzen byl, želeje toho, navrátil zase třidceti stříbrných předním kněžím a starším,'),
(1570394,54,40,27,4,'Řka: Zhřešil jsem, zradiv krev nevinnou. Oni pak řekli: Co nám do toho? Ty viz.'),
(1570395,54,40,27,5,'A on povrh ty stříbrné v chrámě, odšel pryč, a odšed, oběsil se.'),
(1570396,54,40,27,6,'A přední kněží vzavše peníze, řekli: Neslušíť jich vložiti do pokladnice, nebo mzda krve jest.'),
(1570397,54,40,27,7,'A poradivše se, koupili za ně pole to hrnčířovo, ku pohřebu poutníků.'),
(1570398,54,40,27,8,'Protož nazváno jest pole to pole krve, až do dnešního dne.'),
(1570399,54,40,27,9,'A tehdy naplnilo se povědění skrze Jeremiáše proroka řkoucího: A vzali třidceti stříbrných, mzdu ceněného, kterýž šacován byl od synů Izraelských,'),
(1570400,54,40,27,10,'A dali je za pole hrnčířovo, jakož mi ustanovil Pán.'),
(1570401,54,40,27,11,'Ježíš pak stál před vladařem. A otázal se ho vladař, řka: Ty-li jsi ten král Židovský? Řekl jemu Ježíš: Ty pravíš.'),
(1570402,54,40,27,12,'A když na něj přední kněží a starší žalovali, nic neodpověděl.'),
(1570403,54,40,27,13,'Tedy dí mu Pilát: Neslyšíš-li, kteraké věci proti tobě svědčí?'),
(1570404,54,40,27,14,'Ale on neodpověděl jemu k žádnému slovu, takže se vladař tomu velmi divil.'),
(1570405,54,40,27,15,'Měl pak obyčej vladař v svátek propustiti lidu vězně jednoho, kteréhož by chtěli.'),
(1570406,54,40,27,16,'I měli v ten čas vězně jednoho znamenitého, kterýž sloul Barabbáš.'),
(1570407,54,40,27,17,'Protož když se lidé sešli, řekl: Kterého chcete, ať vám propustím? Barabbáše-li, čili Ježíše, jenž slove Kristus?'),
(1570408,54,40,27,18,'Neboť věděl, že jej z závisti vydali.'),
(1570409,54,40,27,19,'A když seděl na soudné stolici, poslala k němu žena jeho, řkuci: Nic neměj činiti s spravedlivým tímto, nebo jsem mnoho trpěla dnes ve snách pro něho.'),
(1570410,54,40,27,20,'Ale přední kněží a starší navedli lid, aby prosili za Barabbáše, Ježíše pak aby zahubili.'),
(1570411,54,40,27,21,'I odpověděv vladař, řekl jim: Kterého chcete ze dvou, ať vám propustím? A oni řekli: Barabbáše.'),
(1570412,54,40,27,22,'Dí jim Pilát: Co pak učiním s Ježíšem, jenž slove Kristus? Řekli mu všickni: Ukřižován buď.'),
(1570413,54,40,27,23,'Vladař pak řekl: I což jest zlého učinil? Oni pak více volali, řkouce: Ukřižován buď.'),
(1570414,54,40,27,24,'A vida Pilát, že by nic neprospěl, ale že by větší rozbroj byl, vzav vodu, umyl ruce před lidem, řka: Čist jsem já od krve spravedlivého tohoto. Vy vizte.'),
(1570415,54,40,27,25,'A odpověděv všecken lid, řekl: Krev jeho na nás i na naše syny.'),
(1570416,54,40,27,26,'Tedy propustil jim Barabbáše, ale Ježíše zbičovav, vydal, aby byl ukřižován.'),
(1570417,54,40,27,27,'Tedy žoldnéři hejtmanovi, vzavše Ježíše do radného domu, shromáždili k němu všecku svou rotu.'),
(1570418,54,40,27,28,'A svlékše jej, přiodíli ho pláštěm brunátným.'),
(1570419,54,40,27,29,'A spletše korunu z trní, vstavili na hlavu jeho, a dali třtinu v pravou ruku jeho, a klekajíce před ním, posmívali se jemu, řkouce: Zdráv buď, ó králi Židovský.'),
(1570420,54,40,27,30,'A plijíce na něho, brali třtinu a bili jej v hlavu.'),
(1570421,54,40,27,31,'A když se mu naposmívali, svlékli s něho plášť, a oblékli jej v roucho jeho. I vedli ho, aby byl ukřižován.'),
(1570422,54,40,27,32,'A vyšedše, nalezli člověka Cyrenenského, jménem Šimona. Toho přinutili, aby nesl kříž jeho.'),
(1570423,54,40,27,33,'I přišedše na místo, kteréž slove Golgata, to jest popravné místo,'),
(1570424,54,40,27,34,'Dali mu píti octa, smíšeného se žlučí. A okusiv ho, nechtěl píti.'),
(1570425,54,40,27,35,'Ukřižovavše pak jej, rozdělili roucha jeho, mecíce o ně los, aby se naplnilo povědění proroka, řkoucího: Rozdělili sobě roucho mé, a o můj oděv metali los.'),
(1570426,54,40,27,36,'A sedíce, ostříhali ho tu.'),
(1570427,54,40,27,37,'I vstavili nad hlavu jeho vinu jeho napsanou: Totoť jest Ježíš, ten král Židovský.'),
(1570428,54,40,27,38,'I ukřižováni jsou s ním dva lotři, jeden na pravici a druhý na levici.'),
(1570429,54,40,27,39,'Ti pak, kteříž chodili tudy, rouhali mu se, ukřivujíce hlav svých,'),
(1570430,54,40,27,40,'A říkajíce: Hej, ty jako rušíš chrám Boží a ve třech dnech jej zase vzděláváš, pomoziž sám sobě. Jsi-li Syn Boží, sestupiž s kříže.'),
(1570431,54,40,27,41,'Tak podobně i přední kněží posmívajíce se s zákoníky a staršími, pravili:'),
(1570432,54,40,27,42,'Jiným pomáhal, sám sobě nemůž pomoci. Jestliže jest král Židovský, nechať nyní sstoupí s kříže, a uvěříme jemu.'),
(1570433,54,40,27,43,'Doufalť v Boha, nechať ho nyní vysvobodí, chce-liť mu; nebo pravil: Syn Boží jsem.'),
(1570434,54,40,27,44,'Takž také i lotři, kteříž byli s ním ukřižováni, utrhali jemu.'),
(1570435,54,40,27,45,'Od šesté pak hodiny tma se stala po vší té zemi až do hodiny deváté.'),
(1570436,54,40,27,46,'A při hodině deváté zvolal Ježíš hlasem velikým, řka: Eli, Eli, lama zabachtani? To jest: Bože můj, Bože můj, proč jsi mne opustil?'),
(1570437,54,40,27,47,'A někteří z těch, jenž tu stáli, slyšíce, pravili, že Eliáše volá tento.'),
(1570438,54,40,27,48,'A hned jeden z nich běžev, vzal houbu, naplnil ji octem a vloživ na tresť, dával jemu píti.'),
(1570439,54,40,27,49,'Ale jiní pravili: Nech tak, pohledíme, přijde-li Eliáš, aby ho vysvobodil.'),
(1570440,54,40,27,50,'Ježíš pak opět volaje hlasem velikým, vypustil duši.'),
(1570441,54,40,27,51,'A aj, opona chrámová roztrhla se na dvé, od vrchu až dolů, a země se třásla a skálé se pukalo,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570442,54,40,27,52,'A hrobové se otvírali, a mnohá těla zesnulých svatých vstala jsou.'),
(1570443,54,40,27,53,'A vyšedše z hrobů, po vzkříšení jeho přišli do svatého města a ukázali se mnohým.'),
(1570444,54,40,27,54,'Tedy centurio a ti, kteříž s ním byli, ostříhajíce Ježíše, vidouce zemětřesení a to, co se dálo, báli se velmi, řkouce: Jistě Syn Boží byl tento.'),
(1570445,54,40,27,55,'Byly také tu ženy mnohé, zdaleka se dívajíce, kteréž byly přišly za Ježíšem od Galilee, posluhujíce jemu,'),
(1570446,54,40,27,56,'Mezi nimiž byla Maria Magdaléna a Maria, matka Jakubova a Jozesova, a matka synů Zebedeových.'),
(1570447,54,40,27,57,'A když byl večer, přišel jeden člověk bohatý od Arimatie, jménem Jozef, kterýž také byl učedlník Ježíšův.'),
(1570448,54,40,27,58,'Ten přistoupil ku Pilátovi a prosil za tělo Ježíšovo. Tedy Pilát rozkázal dáti tělo.'),
(1570449,54,40,27,59,'A vzav tělo Ježíšovo Jozef, obvinul je v plátno čisté,'),
(1570450,54,40,27,60,'A vložil do svého nového hrobu, kterýž byl vytesal v skále; a přivaliv kámen veliký ke dveřům hrobovým, odšel.'),
(1570451,54,40,27,61,'A byla tu Maria Magdaléna a druhá Maria, sedíce naproti hrobu.'),
(1570452,54,40,27,62,'Druhého pak dne, kterýž byl po velikém pátku, sešli se přední kněží a farizeové ku Pilátovi,'),
(1570453,54,40,27,63,'Řkouce: Pane, rozpomenuli jsme se, že ten svůdce řekl, ještě živ jsa: Po třech dnech vstanu.'),
(1570454,54,40,27,64,'Rozkažiž tedy ostříhati hrobu až do třetího dne, ať by snad učedlníci jeho, přijdouce v noci, neukradli ho, a řekli by lidu: Vstalť jest z mrtvých. I budeť poslední blud horší nežli první.'),
(1570455,54,40,27,65,'Řekl jim Pilát: Máte stráž; jděte, ostříhejte, jakž víte.'),
(1570456,54,40,27,66,'A oni šedše, osadili hrob strážnými, zapečetivše kámen.'),
(1570457,54,40,28,1,'Na skonání pak soboty, když již svitalo na první den toho téhodne, přišla Maria Magdaléna a druhá Maria, aby pohleděly na hrob.'),
(1570458,54,40,28,2,'A aj, zemětřesení stalo se veliké. Nebo anděl Páně sstoupiv s nebe a přistoupiv, odvalil kámen ode dveří hrobových, a posadil se na něm.'),
(1570459,54,40,28,3,'A byl obličej jeho jako blesk, a roucho jeho bílé jako sníh.'),
(1570460,54,40,28,4,'A pro strach jeho zděsili se strážní a učiněni jsou jako mrtví.'),
(1570461,54,40,28,5,'I odpověděv anděl, řekl ženám: Nebojte se vy, neboť vím, že Ježíše ukřižovaného hledáte.'),
(1570462,54,40,28,6,'Neníť ho tuto; nebo vstalť jest, jakož předpověděl. Pojďte, a vizte místo, kdež ležel Pán.'),
(1570463,54,40,28,7,'A rychle jdouce, povězte učedlníkům jeho, že vstal z mrtvých. A aj, předchází vás do Galilee, tam jej uzříte. Aj, pověděl jsem vám.'),
(1570464,54,40,28,8,'I vyšedše rychle z hrobu s bázní a s radostí velikou, běžely, aby učedlníkům jeho zvěstovaly.'),
(1570465,54,40,28,9,'Když pak šly zvěstovati učedlníkům jeho, aj, Ježíš potkal se s nimi, řka: Zdrávy buďte. A ony přistoupivše, chopily se noh jeho, a klaněly se jemu.'),
(1570466,54,40,28,10,'Tedy dí jim Ježíš: Nebojtež se. Jděte, zvěstujte bratřím mým, ať jdou do Galilee, a tamť mne uzří.'),
(1570467,54,40,28,11,'Když pak ony odešly, aj, někteří z stráže přišedše do města, oznámili předním kněžím všecko, co se stalo.'),
(1570468,54,40,28,12,'Kteřížto shromáždivše se s staršími a uradivše se, mnoho peněz dali žoldnéřům,'),
(1570469,54,40,28,13,'Řkouce: Pravte, že učedlníci jeho nočně přišedše, ukradli jej, když jsme my spali.'),
(1570470,54,40,28,14,'A uslyší-liť o tom hejtman, myť ho spokojíme a vás bezpečny učiníme.'),
(1570471,54,40,28,15,'A oni vzavše peníze, učinili, jakž naučeni byli. I rozhlášeno jest slovo to u Židů až do dnešního dne.'),
(1570472,54,40,28,16,'Jedenácte pak učedlníků šli do Galilee na horu, kdežto jim byl uložil Ježíš.'),
(1570473,54,40,28,17,'A uzřevše ho, klaněli se jemu. Ale někteří pochybovali.'),
(1570474,54,40,28,18,'A přistoupiv Ježíš, mluvil jim, řka: Dána jest mi všeliká moc na nebi i na zemi.'),
(1570475,54,40,28,19,'Protož jdouce, učte všecky národy, křtíce je ve jméno Otce i Syna i Ducha svatého,'),
(1570476,54,40,28,20,'Učíce je zachovávati všecko, což jsem koli přikázal vám. A aj, já s vámi jsem po všecky dny, až do skonání světa. Amen.'),
(1570477,54,41,1,1,'Počátek evangelium Ježíše Krista, Syna Božího;'),
(1570478,54,41,1,2,'Jakož psáno jest v Prorocích: Aj, já posílám anděla svého před tváří tvou, kterýž připraví cestu tvou před tebou.'),
(1570479,54,41,1,3,'Hlas volajícího na poušti: Připravujte cestu Páně, přímé čiňte stezky jeho.'),
(1570480,54,41,1,4,'Křtil Jan na poušti a kázal křest pokání na odpuštění hříchů.'),
(1570481,54,41,1,5,'I vycházeli k němu ze vší krajiny Židovské i Jeruzalémští, a křtili se od něho všickni v Jordáně řece, vyznávajíce hříchy své.'),
(1570482,54,41,1,6,'Byl pak Jan odín srstmi velbloudovými, a pás kožený na bedrách jeho, a jídal kobylky a med lesní.'),
(1570483,54,41,1,7,'A kázal, řka: Za mnou jde silnější mne, kteréhožto nejsem hoden, sehna se, rozvázati řeménka u obuvi jeho.'),
(1570484,54,41,1,8,'Já zajisté křtil jsem vás vodou, ale onť vás křtíti bude Duchem svatým.'),
(1570485,54,41,1,9,'I stalo se v těch dnech, přišel Ježíš z Nazarétu Galilejského, a pokřtěn jest v Jordáně od Jana.'),
(1570486,54,41,1,10,'A hned vystoupě z vody, uzřel nebesa otevřená a Ducha jakožto holubici, sstupujícího na něj.'),
(1570487,54,41,1,11,'A hlas stal se s nebe: Ty jsi ten můj milý Syn, v němž mi se dobře zalíbilo.'),
(1570488,54,41,1,12,'A ihned ho Duch vypudil na poušť.'),
(1570489,54,41,1,13,'I byl tam na poušti čtyřidceti dnů, a pokoušín byl od satana; a byl s zvěří, a andělé přisluhovali jemu.'),
(1570490,54,41,1,14,'Když pak byl vsazen Jan do žaláře, přišel Ježíš do Galilee, zvěstuje evangelium království Božího,'),
(1570491,54,41,1,15,'Pravě: Že se naplnil čas, a přiblížilo se království Boží. Čiňte pokání, a věřte evangelium.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570492,54,41,1,16,'A chodě podle moře Galilejského, uzřel Šimona a Ondřeje bratra jeho, ani pouštějí síti do moře, nebo rybáři byli.'),
(1570493,54,41,1,17,'I řekl jim Ježíš: Pojďte za mnou, a učiním vás rybáře lidí.'),
(1570494,54,41,1,18,'A oni hned opustivše síti své, šli za ním.'),
(1570495,54,41,1,19,'A pošed odtud maličko, uzřel Jakuba Zebedeova, a Jana bratra jeho, kteříž také byli na lodí tvrdíce síti své;'),
(1570496,54,41,1,20,'A hned povolal jich. A oni opustivše otce svého Zebedea na lodí s pacholky, šli za ním.'),
(1570497,54,41,1,21,'I vešli do Kafarnaum. A hned v sobotu šel Ježíš do školy, a učil.'),
(1570498,54,41,1,22,'I divili se náramně učení jeho; nebo učil je, jako moc maje, a ne jako zákoníci.'),
(1570499,54,41,1,23,'I byl v škole jejich člověk, posedlý duchem nečistým. I zvolal,'),
(1570500,54,41,1,24,'Řka: Ale což jest tobě do nás, Ježíši Nazaretský? Přišel jsi zatratiti nás; znám tě, kdo jsi, a vím, že jsi ten svatý Boží.'),
(1570501,54,41,1,25,'I přimluvil mu Ježíš, řka: Umlkniž a vyjdi z něho.'),
(1570502,54,41,1,26,'I polomcovav jím duch nečistý a křiče hlasem velikým, vyšel z něho.'),
(1570503,54,41,1,27,'I lekli se všickni, takže se tázali mezi sebou, řkouce: I co jest toto? Jakéž jest toto nové učení, že tento mocně duchům nečistým rozkazuje, a poslouchají ho?'),
(1570504,54,41,1,28,'I roznesla se pověst o něm hned po vší krajině Galilejské.'),
(1570505,54,41,1,29,'A hned vyšedše ze školy, přišli do domu Šimonova a Ondřejova s Jakubem a s Janem.'),
(1570506,54,41,1,30,'Šimonova pak svegruše ležela, majíc zimnici. A hned jemu pověděli o ní.'),
(1570507,54,41,1,31,'A přistoupiv, pozdvihl jí, ujav ji za ruku její, a hned přestala jí zimnice. I posluhovala jim.'),
(1570508,54,41,1,32,'Večer pak již při západu slunce, nosili k němu všecky nemocné i ďábelníky.'),
(1570509,54,41,1,33,'A bylo se všecko město sběhlo ke dveřům.'),
(1570510,54,41,1,34,'I uzdravoval mnohé ztrápené rozličnými neduhy, a ďábelství mnohá vymítal, a nedopustil mluviti ďáblům; nebo znali ho.'),
(1570511,54,41,1,35,'A přede dnem velmi ráno vstav Ježíš, vyšel, a šel na pusté místo, a tam se modlil.'),
(1570512,54,41,1,36,'I šel za ním Šimon i ti, kteříž s ním byli.'),
(1570513,54,41,1,37,'A když jej nalezli, řekli jemu: Všickni tě hledají.'),
(1570514,54,41,1,38,'I dí jim: Pojďmež do okolních městeček, abych i tam kázal. Nebo na to jsem přišel.'),
(1570515,54,41,1,39,'I kázal v školách jejich ve vší Galileji, a ďábelství vymítal.'),
(1570516,54,41,1,40,'Tedy přišel k němu malomocný, prose ho, a klekna před ním, řekl jemu: Pane, chceš-li, můžeš mne očistiti.'),
(1570517,54,41,1,41,'Ježíš pak slitovav se, vztáhl ruku, dotekl se ho a řekl jemu: Chci, buď čist.'),
(1570518,54,41,1,42,'A když to řekl, hned odstoupilo od něho malomocenství, a očištěn jest.'),
(1570519,54,41,1,43,'I pohroziv mu, hned ho odbyl,'),
(1570520,54,41,1,44,'A řekl mu: Viziž, abys nižádnému nic nepravil. Ale jdi, ukaž se knězi, a obětuj za očištění své to, což přikázal Mojžíš, na svědectví jim.'),
(1570521,54,41,1,45,'On pak vyšed, počal vypravovati mnoho a ohlašovati tu věc, takže již nemohl Ježíš do města zjevně vjíti, ale vně na místech pustých byl. I scházeli se k němu odevšad.'),
(1570522,54,41,2,1,'A opět všel do Kafarnaum po několika dnech. I uslyšáno jest, že by doma byl.'),
(1570523,54,41,2,2,'A hned sešlo se jich množství, takže již nemohli ani ke dveřům. I mluvil jim slovo.'),
(1570524,54,41,2,3,'Tedy přijdou k němu někteří, nesouce šlakem poraženého, kterýžto ode čtyř nesen byl.'),
(1570525,54,41,2,4,'A když k němu nemohli pro zástupy, loupali střechu, kdež byl Ježíš, a probořivše půdu, spustili po provazích dolů ložce, na němž ležel šlakem poražený.'),
(1570526,54,41,2,5,'A vida Ježíš víru jejich, dí šlakem poraženému: Synu, odpouštějí se tobě hříchové tvoji.'),
(1570527,54,41,2,6,'A byli tu někteří z zákoníků, sedíce a myslíce v srdcích svých:'),
(1570528,54,41,2,7,'Co tento tak mluví rouhavě? Kdo můž odpustiti hříchy, jediné sám Bůh?'),
(1570529,54,41,2,8,'To hned poznav Ježíš duchem svým, že by tak přemyšlovali sami v sobě, řekl jim: Proč o tom přemyšlujete v srdcích svých?'),
(1570530,54,41,2,9,'Co jest snáze říci šlakem poraženému: Odpouštějí se tobě hříchové, čili říci: Vstaň a vezmi lože své a choď?'),
(1570531,54,41,2,10,'Ale abyste věděli, že Syn člověka má moc na zemi odpouštěti hříchy, dí šlakem poraženému:'),
(1570532,54,41,2,11,'Toběť pravím: Vstaň, a vezmi lože své, a jdi do domu svého.'),
(1570533,54,41,2,12,'I vstal hned, a vzav lože své přede všemi, odšel, takže se děsili všickni, a chválili Boha, řkouce: Nikdy jsme toho neviděli.'),
(1570534,54,41,2,13,'I vyšel opět k moři, a všecken zástup přicházel k němu, i učil je.'),
(1570535,54,41,2,14,'A pomíjeje Ježíš, uzřel Léví syna Alfeova, sedícího na cle. I dí jemu: Pojď za mnou. A on vstav, šel za ním.'),
(1570536,54,41,2,15,'I stalo se, když seděl za stolem v domu jeho, že i publikáni mnozí a hříšníci seděli spolu s Ježíšem a s učedlníky jeho; neb mnoho jich bylo, a šlo za ním.'),
(1570537,54,41,2,16,'Zákoníci pak a farizeové vidouce, že jedl s publikány a s hříšníky, řekli učedlníkům jeho: Což jest toho, že s publikány a hříšníky jí a pije Mistr váš?'),
(1570538,54,41,2,17,'To uslyšav Ježíš, dí jim: Nepotřebují zdraví lékaře, ale nemocní. Nepřišelť jsem volati spravedlivých, ale hříšných ku pokání.'),
(1570539,54,41,2,18,'Učedlníci pak Janovi a farizejští postívali se. I přišli a řekli jemu: Proč učedlníci Janovi a farizejští postí se, a tvoji učedlníci se nepostí?'),
(1570540,54,41,2,19,'I řekl jim Ježíš: Kterakž mohou synové Ženichovi postiti se, když jest s nimi Ženich? Dokavadž mají s sebou Ženicha, nemohouť se postiti.'),
(1570541,54,41,2,20,'Ale přijdouť dnové, když od nich odjat bude Ženich, a tehdáž se budou postiti v těch dnech.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570542,54,41,2,21,'Ano nižádný záplaty sukna nového nepřišívá k rouchu starému; jinak odtrhne ta záplata nová od starého ještě něco, i bývá větší díra.'),
(1570543,54,41,2,22,'A žádný nevlévá vína nového do nádob starých; jinak rozpučí nové víno nádoby, a tak víno se vyleje, a nádoby se pokazí. Ale víno nové má lito býti do nádob nových.'),
(1570544,54,41,2,23,'I stalo se, že šel Ježíš v sobotu skrze obilí, i počali učedlníci jeho jdouce vymínati klasy.'),
(1570545,54,41,2,24,'Tedy farizeové řekli jemu: Pohleď, coť činí učedlníci tvoji, čehož nesluší činiti v sobotu.'),
(1570546,54,41,2,25,'I řekl jim: Nikdy-liž jste nečtli, co učinil David, když nouze byla, a lačněl, on i ti, kteříž s ním byli?'),
(1570547,54,41,2,26,'Kterak všel do domu Božího za Abiatara nejvyššího kněze, a jedl chleby posvátné, (jichžto neslušelo jísti než samým kněžím,) a dal i těm, kteříž s ním byli?'),
(1570548,54,41,2,27,'I pravil jim: Sobota pro člověka učiněna jest, a ne člověk pro sobotu.'),
(1570549,54,41,2,28,'Protož Syn člověka jest pánem také i soboty.'),
(1570550,54,41,3,1,'I všel opět do školy, a byl tu člověk, maje ruku uschlou.'),
(1570551,54,41,3,2,'I šetřili ho, uzdraví-li jej v sobotu, aby ho obžalovali.'),
(1570552,54,41,3,3,'I řekl tomu člověku, kterýž měl uschlou ruku: Vstaň a pojď sem do prostředku.'),
(1570553,54,41,3,4,'I dí jim: Sluší-li v sobotu dobře činiti, čili zle, život zachovati, čili zamordovati? Ale oni mlčeli.'),
(1570554,54,41,3,5,'A pohleděv na ně vůkol hněvivě, zarmoutiv se nad tvrdostí srdce jejich, řekl člověku: Vztáhni ruku svou. I vztáhl, a učiněna jest ruka jeho zdravá, jako i druhá.'),
(1570555,54,41,3,6,'A vyšedše farizeové, hned s herodiány radu učinili proti Ježíšovi, kterak by ho zahubili.'),
(1570556,54,41,3,7,'Ježíš pak s učedlníky svými poodšel k moři, a veliké množství od Galilee šlo za ním, i z Judstva,'),
(1570557,54,41,3,8,'I od Jeruzaléma, i od Idumee, i z Zajordání; i ti, kteříž byli okolo Týru a Sidonu, množství veliké, slyšíce, kteraké věci činí, přišli k němu.'),
(1570558,54,41,3,9,'I rozkázal učedlníkům svým, aby lodičku ustavičně nahotově měli, pro zástup, aby ho tak netiskli.'),
(1570559,54,41,3,10,'Nebo mnohé uzdravoval, takže naň padali, aby se ho dotýkali, kteřížkoli měli jaké neduhy.'),
(1570560,54,41,3,11,'A duchové nečistí, jakž ho zazřeli, padali před ním a křičeli, řkouce: Ty jsi Syn Boží.'),
(1570561,54,41,3,12,'A on velmi jim přimlouval, aby ho nezjevovali.'),
(1570562,54,41,3,13,'I vstoupil na horu, a povolal k sobě těch, kterýchž se jemu vidělo; i přišli k němu.'),
(1570563,54,41,3,14,'I ustanovil jich dvanácte, aby s ním byli, aby je poslal kázati,'),
(1570564,54,41,3,15,'A aby měli moc uzdravovati nemoci a vymítati ďábelství:'),
(1570565,54,41,3,16,'A nejprve Šimona, jemuž dal jméno Petr,'),
(1570566,54,41,3,17,'A Jakuba Zebedeova, a Jana bratra Jakubova, (a dal jim jméno Boanerges, to jest synové hromovi,)'),
(1570567,54,41,3,18,'A Ondřeje, a Filipa, a Bartoloměje, a Matouše, a Tomáše, a Jakuba Alfeova, a Taddea, a Šimona Kananejského,'),
(1570568,54,41,3,19,'A Jidáše Iškariotského, kterýž i zradil jej. I šli s ním domů.'),
(1570569,54,41,3,20,'A vtom opět sšel se zástup, takže nemohli ani chleba pojísti.'),
(1570570,54,41,3,21,'A slyšavše o tom příbuzní jeho, přišli, aby jej vzali; nebo pravili, že by se smyslem pominul.'),
(1570571,54,41,3,22,'Zákoníci pak, kteříž byli přišli od Jeruzaléma, pravili, že Belzebuba má a že v knížeti ďábelském vymítá ďábly.'),
(1570572,54,41,3,23,'A povolav jich, mluvil k nim v podobenstvích: Kterak může satan satana vymítati?'),
(1570573,54,41,3,24,'A jestliže království v sobě se rozdvojí, nemůže státi království to.'),
(1570574,54,41,3,25,'A rozdvojí-li se dům proti sobě, nebude moci dům ten státi.'),
(1570575,54,41,3,26,'Tak jestliže jest povstal satan sám proti sobě, a rozdvojen jest, nemůže státi, ale konec béře.'),
(1570576,54,41,3,27,'Nižádný nemůže nádobí silného reka, vejda do domu jeho, rozebrati, leč by prve silného toho svázal; a tehdyť dům jeho zloupí.'),
(1570577,54,41,3,28,'Amen pravím vám, že všickni hříchové odpuštěni budou synům lidským, i rouhání, jímž by se rouhali,'),
(1570578,54,41,3,29,'Ale kdo by se rouhal proti Duchu svatému, nemá odpuštění na věky, ale hoden jest věčného odsouzení.'),
(1570579,54,41,3,30,'Nebo pravili: Že ducha nečistého má.'),
(1570580,54,41,3,31,'Tedy přišla matka jeho a bratří, a stojíce vně, poslali k němu, aby ho vyvolali.'),
(1570581,54,41,3,32,'A seděl okolo něho zástup. I řekli jemu: Aj, matka tvá a bratří tvoji vně hledají tebe.'),
(1570582,54,41,3,33,'Ale on odpověděl jim, řka: Kdo jest matka má a bratří moji?'),
(1570583,54,41,3,34,'A obezřev učedlníky vůkol sedící, řekl: Aj, matka má a bratří moji.'),
(1570584,54,41,3,35,'Nebo kdož by koli činil vůli Boží, tenť jest bratr můj, i sestra, i matka má.'),
(1570585,54,41,4,1,'A opět počal Ježíš učiti u moře. I shromáždil se k němu zástup mnohý, takže vstoupiv na lodí, seděl na moři, a všecken zástup byl na zemi podle moře.'),
(1570586,54,41,4,2,'I učil je mnohým věcem v podobenstvích, a pravil jim v učení svém:'),
(1570587,54,41,4,3,'Slyšte. Aj, vyšel rozsevač, aby rozsíval.'),
(1570588,54,41,4,4,'I stalo se v tom rozsívání, že jedno padlo podle cesty, a přiletělo ptactvo nebeské, i szobali je.'),
(1570589,54,41,4,5,'A jiné padlo na místo skalnaté, kdežto nemělo mnoho země, a hned vzešlo; neb nemělo hlubokosti země.'),
(1570590,54,41,4,6,'A když vyšlo slunce, uvadlo, a protože nemělo kořene, uschlo.'),
(1570591,54,41,4,7,'A jiné padlo mezi trní; i zrostlo trní, a udusilo je. I nevydalo užitku.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570592,54,41,4,8,'Jiné pak padlo v zemi dobrou, a dalo užitek vzhůru vstupující a rostoucí; přineslo zajisté jedno třidcátý, a jiné šedesátý, a jiné pak stý.'),
(1570593,54,41,4,9,'I pravil jim: Kdo má uši k slyšení, slyš.'),
(1570594,54,41,4,10,'A když pak byl sám, tázali se ho ti, kteříž při něm byli, se dvanácti, na to podobenství.'),
(1570595,54,41,4,11,'I řekl jim: Vámť jest dáno, znáti tajemství království Božího, ale těm, kteříž jsou vně, v podobenství všecko se děje,'),
(1570596,54,41,4,12,'Aby hledíce, hleděli, a neuzřeli, a slyšíce, slyšeli, a nesrozuměli, aby se snad neobrátili, a byli by jim odpuštěni hříchové.'),
(1570597,54,41,4,13,'I dí jim: Neznáte podobenství tohoto? A kterakž pak jiná všecka podobenství poznáte?'),
(1570598,54,41,4,14,'Rozsevač, ten slovo rozsívá.'),
(1570599,54,41,4,15,'Titoť pak jsou, ješto podle cesty símě přijímají, kdežto se rozsívá slovo, kteréž když oni slyší, ihned přichází satan a vynímá slovo, kteréž vsáto jest v srdcích jejich.'),
(1570600,54,41,4,16,'A tak podobně ti, kteříž jako skalnatá země posáti jsou, kteřížto jakž uslyší slovo, hned s radostí přijímají je.'),
(1570601,54,41,4,17,'Než nemají kořene v sobě, ale jsou časní; potom když vznikne soužení a protivenství pro slovo Boží, hned se horší.'),
(1570602,54,41,4,18,'A tito jsou, jenž mezi trní posáti jsou, kteříž ač slovo slyší,'),
(1570603,54,41,4,19,'Ale pečování tohoto světa a oklamání zboží, a jiné žádosti zlé k tomu přistupující, udušují slovo, takže bez užitku bývá.'),
(1570604,54,41,4,20,'Titoť pak jsou, jenž v zemi dobrou símě přijali, kteříž slyší slovo Boží, a přijímají, a užitek přinášejí, jedno třidcátý, a jiné šedesátý, a jiné stý.'),
(1570605,54,41,4,21,'Dále pravil jim: Zdali rozsvícena bývá svíce, aby postavena byla pod nádobu nebo pod postel? Však aby na svícen vstavena byla.'),
(1570606,54,41,4,22,'Nebo nic není skrytého, co by nebylo zjeveno; aniž jest co tak ukrytého, aby najevo nevyšlo.'),
(1570607,54,41,4,23,'Jestliže kdo má uši k slyšení, slyš.'),
(1570608,54,41,4,24,'I mluvil k nim: Vizte, co slyšíte. Kterou měrou budete měřiti, touť vám bude odměřeno, a přidáno bude vám poslouchajícím.'),
(1570609,54,41,4,25,'Nebo kdožť má, tomu bude dáno; a kdo nemá, i to, což má, bude od něho odjato.'),
(1570610,54,41,4,26,'I pravil jim: Tak jest království Boží, jako kdyby člověk uvrhl símě v zemi.'),
(1570611,54,41,4,27,'A spal by, a vstával by ve dne i v noci, a semeno by vzešlo a vzrostlo, jakž on neví.'),
(1570612,54,41,4,28,'Nebo sama od sebe země plodí, nejprv bylinu, potom klas, potom plné obilé v klasu.'),
(1570613,54,41,4,29,'A když sezrá úroda, ihned přičiní srp; neboť jest nastala žeň.'),
(1570614,54,41,4,30,'I řekl opět: K čemu připodobníme království Boží? Aneb kterému podobenství je přirovnáme?'),
(1570615,54,41,4,31,'Jest jako zrno horčičné, kteréžto, když vsáto bývá v zemi, menší jest ze všech semen, kteráž jsou na zemi.'),
(1570616,54,41,4,32,'Ale když vsáto bývá, roste, a bývá větší než všecky byliny, a činíť ratolesti veliké, takže pod stínem jeho mohou sobě ptáci nebeští hnízda dělati.'),
(1570617,54,41,4,33,'A takovými mnohými podobenstvími mluvil jim slovo, jakž mohli slyšeti.'),
(1570618,54,41,4,34,'A bez podobenství nemluvil jim, učedlníkům pak svým soukromí vykládal všecko.'),
(1570619,54,41,4,35,'I řekl jim v ten den, když již bylo večer: Plavme se na druhou stranu.'),
(1570620,54,41,4,36,'A nechavše zástupu, pojali jej, tak jakž byl na lodičce. Ale i jiné lodičky byly s ním.'),
(1570621,54,41,4,37,'Tedy stala se bouře veliká od větru, až se vlny na lodí valily, takže se již naplňovala lodí.'),
(1570622,54,41,4,38,'A on zzadu na lodí spal na podušce. I zbudili jej, a řekli jemu: Mistře, což pak nic nedbáš, že hyneme?'),
(1570623,54,41,4,39,'I probudiv se, přimluvil větru a řekl moři: Umlkni a upokoj se. I přestal vítr, a stalo se utišení veliké.'),
(1570624,54,41,4,40,'I řekl jim: Proč se tak bojíte? Což ještě nemáte víry?'),
(1570625,54,41,4,41,'I báli se bázní velikou, a pravili jeden k druhému: Hle kdo jest tento, že i vítr i moře poslouchají jeho?'),
(1570626,54,41,5,1,'Tedy přeplavili se přes moře do krajiny Gadarenských.'),
(1570627,54,41,5,2,'A jakž vyšel z lodí, hned se s ním potkal člověk z hrobů, maje ducha nečistého.'),
(1570628,54,41,5,3,'Kterýž bydlil v hrobích, a aniž ho kdo již mohl řetězy svázati,'),
(1570629,54,41,5,4,'Nebo často jsa pouty a řetězy okován, polámal řetězy a pouta roztrhal, a žádný nemohl ho zkrotiti.'),
(1570630,54,41,5,5,'A vždycky ve dne i v noci na horách a v hrobích byl, křiče a tepa se kamením.'),
(1570631,54,41,5,6,'Uzřev pak Ježíše zdaleka, běžel a poklonil se jemu,'),
(1570632,54,41,5,7,'A křiče hlasem velikým, řekl: Co jest tobě do mne, Ježíši, Synu Boha nejvyššího? Zaklínám tě skrze Boha, abys mne netrápil.'),
(1570633,54,41,5,8,'(Nebo pravil jemu: Vyjdiž, duchu nečistý, z člověka tohoto.)'),
(1570634,54,41,5,9,'I otázal se ho: Jakť říkají? A on odpovídaje, řekl: Množství jméno mé jest, neb jest nás mnoho.'),
(1570635,54,41,5,10,'I prosil ho velmi, aby jich nevyháněl z té krajiny.'),
(1570636,54,41,5,11,'Bylo pak tu při horách stádo vepřů veliké pasoucích se.'),
(1570637,54,41,5,12,'I prosili ho všickni ti ďáblové, řkouce: Pusť nás do vepřů, ať do nich vejdeme.'),
(1570638,54,41,5,13,'I povolil jim hned Ježíš. A vyšedše duchové nečistí, vešli do vepřů. I běželo to stádo s vrchu dolů do moře, (a bylo jich ke dvěma tisícům,) i ztonuli v moři.'),
(1570639,54,41,5,14,'Ti pak, kteříž ty vepře pásli, utekli a oznámili to v městě i ve vsech. I vyšli lidé, aby viděli, co je se to stalo.'),
(1570640,54,41,5,15,'I přišli k Ježíšovi, a uzřeli toho, kterýž byl trápen od ďábelství, an sedí, odín jsa a maje zdravý rozum, toho totiž, kterýž měl tmu ďáblů. I báli se.'),
(1570641,54,41,5,16,'A kteříž to viděli, vypravovali jim, kterak se stalo tomu, kterýž měl ďábelství, i o vepřích.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570642,54,41,5,17,'Tedy počali ho prositi, aby odšel z krajin jejich.'),
(1570643,54,41,5,18,'A když vstoupil na lodí, prosil ho ten, kterýž trápen byl od ďábelství, aby byl s ním.'),
(1570644,54,41,5,19,'Ježíš pak nedopustil mu, ale řekl jemu: Jdi k svým do domu svého, a zvěstuj jim, kterak jest veliké věci učinil tobě Hospodin, a slitoval se nad tebou.'),
(1570645,54,41,5,20,'I odšel, a počal ohlašovati v krajině Desíti měst, kterak veliké věci učinil mu Ježíš. I divili se všickni.'),
(1570646,54,41,5,21,'A když se přeplavil Ježíš na lodí zase na druhou stranu, sšel se k němu zástup mnohý. A on byl u moře.'),
(1570647,54,41,5,22,'A aj, přišel jeden z knížat školy Židovské, jménem Jairus, a uzřev jej, padl k nohám jeho,'),
(1570648,54,41,5,23,'A velmi ho prosil, řka: Dcerka má skonává. Prosím, pojď, vlož na ni ruce, aby uzdravena byla, a budeť živa.'),
(1570649,54,41,5,24,'I šel s ním, a zástup mnohý šel za ním, i tiskli jej.'),
(1570650,54,41,5,25,'(Tedy žena jedna, kteráž tok krve měla dvanácte let,'),
(1570651,54,41,5,26,'A mnoho byla trápena od mnohých lékařů, a vynaložila všecken statek svůj, a nic jí bylo neprospělo, ale vždy se hůře měla,'),
(1570652,54,41,5,27,'Uslyšavši o Ježíšovi, přišla v zástupu pozadu, a dotkla se roucha jeho.'),
(1570653,54,41,5,28,'Neb řekla byla: Dotknu-li se jen roucha jeho, uzdravena budu.'),
(1570654,54,41,5,29,'A hned přestal jest krvotok její, a pocítila na těle, že by uzdravena byla od neduhu svého.'),
(1570655,54,41,5,30,'A hned Ježíš poznav sám v sobě, že jest moc vyšla z něho k uzdravení, obrátiv se v zástupu, řekl: Kdo se dotekl roucha mého?'),
(1570656,54,41,5,31,'I řekli mu učedlníci jeho: Vidíš, že tě zástup tiskne, a pravíš: Kdo se mne dotekl?'),
(1570657,54,41,5,32,'I hleděl vůkol, aby ji uzřel, která jest to učinila.'),
(1570658,54,41,5,33,'Ta pak žena s bázní a s třesením, věduci, co se stalo při ní, přistoupila a padla před ním, a pověděla mu všecku pravdu.'),
(1570659,54,41,5,34,'On pak řekl jí: Dcero, víra tvá tě uzdravila, jdiž u pokoji, a buď zproštěna od trápení svého.)'),
(1570660,54,41,5,35,'A když on ještě mluvil, přišli někteří z domu knížete školy, řkouce: Dcera tvá umřela, proč již zaměstknáváš Mistra?'),
(1570661,54,41,5,36,'Ježíš pak, hned jakž uslyšel to, což oni mluvili, řekl knížeti školy: Neboj se, toliko věř.'),
(1570662,54,41,5,37,'I nedal žádnému za sebou jíti, jediné Petrovi, Jakubovi a Janovi, bratru Jakubovu.'),
(1570663,54,41,5,38,'I přišel do domu knížete školy, a viděl tam hluk, ano plačí a kvílí velmi.'),
(1570664,54,41,5,39,'I všed tam, řekl jim: Co se bouříte a plačete? Neumřelať jest děvečka, ale spí.'),
(1570665,54,41,5,40,'I posmívali se jemu. On pak vyhnav všecky, pojal toliko otce a matku děvečky, a ty, kteříž s ním byli, i všel tam, kdež děvečka ležela.'),
(1570666,54,41,5,41,'A vzav ruku děvečky, řekl jí: Talitha kumi, jenž se vykládá: Děvečko, (toběť pravím,) vstaň.'),
(1570667,54,41,5,42,'A hned vstala děvečka, a chodila; nebo byla ve dvanácti letech. I zděsili se divením převelikým.'),
(1570668,54,41,5,43,'A přikázal jim pilně, aby žádný o tom nezvěděl. I rozkázal jí dáti jísti.'),
(1570669,54,41,6,1,'I vyšel odtud a přišel do vlasti své, a šli za ním učedlníci jeho.'),
(1570670,54,41,6,2,'A když bylo v sobotu, počal učiti v škole, a mnozí slyšíce, divili se, řkouce: Odkud tento má tyto věci? A jaká jest to moudrost, kteráž jest jemu dána, že i takové moci dějí se skrze ruce jeho?'),
(1570671,54,41,6,3,'Zdaliž tento není tesař, syn Marie, bratr Jakubův a Jozesův a Judův a Šimonův? A zdaliž nejsou i sestry jeho zde u nás? I zhoršili se na něm.'),
(1570672,54,41,6,4,'I řekl jim Ježíš: Není prorok beze cti, jediné v vlasti své a v rodině své a v domu svém.'),
(1570673,54,41,6,5,'I nemohl tu znamení žádného učiniti, jediné málo nemocných, vzkládaje na ně ruce, uzdravil.'),
(1570674,54,41,6,6,'I podivil se jejich nevěře, a obcházel vůkol po městečkách, uče.'),
(1570675,54,41,6,7,'A svolav dvanácte, počal je posílati po dvou a dvou, a dal jim moc nad duchy nečistými.'),
(1570676,54,41,6,8,'A přikázal jim, aby ničehož nebrali na cestu, jediné toliko hůl, ani mošny, ani chleba, ani na pase peněz,'),
(1570677,54,41,6,9,'Ale jen obuté míti nohy v střevíce, a aby neobláčeli dvou sukní.'),
(1570678,54,41,6,10,'A pravil jim: Kdežkoli vešli byste do domu, tu ostaňte, dokudž nevyšli byste odtud.'),
(1570679,54,41,6,11,'A kdož by koli vás nepřijali, ani vás slyšeli, vyjdouce odtud, vyrazte prach z noh vašich na svědectví jim. Amen pravím vám: Lehčeji bude Sodomským a Gomorským v den soudný nežli městu tomu.'),
(1570680,54,41,6,12,'Tedy oni vyšedše, kázali, aby pokání činili.'),
(1570681,54,41,6,13,'A ďábelství mnohá vymítali, a mazali olejem mnohé nemocné, a uzdravovali je.'),
(1570682,54,41,6,14,'A uslyšev o tom Herodes král, (neb zjevné učiněno bylo jméno jeho,) i pravil, že Jan Křtitel vstal z mrtvých, a protož se dějí divové skrze něho.'),
(1570683,54,41,6,15,'Jiní pak pravili, že jest Eliáš; a jiní pravili, že jest prorok, aneb jako jeden z proroků.'),
(1570684,54,41,6,16,'To uslyšev Herodes, řekl: Kteréhož jsem já sťal, Jana, tenť jest. Ontě z mrtvých vstal.'),
(1570685,54,41,6,17,'Ten zajisté Herodes byl poslal a jal Jana a vsadil jej do žaláře pro Herodiadu manželku Filipa bratra svého, že ji byl za manželku pojal.'),
(1570686,54,41,6,18,'Nebo pravil Jan Herodesovi: Neslušíť tobě míti manželky bratra svého.'),
(1570687,54,41,6,19,'Herodias pak lest skládala proti němu, a chtěla jej o hrdlo připraviti, ale nemohla.'),
(1570688,54,41,6,20,'Nebo Herodes ostýchal se Jana, věda jej býti muže spravedlivého a svatého. I šetřil ho, a slýchaje jej, mnoho i činil, a rád ho poslouchal.'),
(1570689,54,41,6,21,'A když přišel den příhodný, že Herodes, pamatuje den svého narození, učinil večeři knížatům svým a hejtmanům a předním mužům z Galilee,'),
(1570690,54,41,6,22,'A dcera té Herodiady tam vešla a tancovala, zalíbilo se Herodesovi i spoluhodovníkům, i řekl král děvečce: Pros mne, zač chceš, a dámť.'),
(1570691,54,41,6,23,'I přisáhl jí: Že začkoli prositi budeš, dám tobě, by pak bylo až do polovice království mého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570692,54,41,6,24,'Ona pak vyšedši, řekla mateři své: Zač budu prositi? A ona řekla: Za hlavu Jana Křtitele.'),
(1570693,54,41,6,25,'A všedši hned s chvátáním k králi, prosila ho, řkuci: Chci, abys mi dal hned na míse hlavu Jana Křtitele.'),
(1570694,54,41,6,26,'Král pak zarmoutiv se velmi, pro přísahu a pro spoluhodovníky nechtěl jí oslyšeti.'),
(1570695,54,41,6,27,'I poslav hned kata, rozkázal přinésti hlavu Janovu.'),
(1570696,54,41,6,28,'A on odšed, sťal jej v žaláři, a přinesl hlavu jeho na míse, a dal ji děvečce, a děvečka dala mateři své.'),
(1570697,54,41,6,29,'To uslyšavše učedlníci jeho, přišli a vzali tělo jeho, a pochovali je v hrobě.'),
(1570698,54,41,6,30,'Tedy sšedše se apoštolé k Ježíšovi, zvěstovali jemu všecko, i to, co činili, i co učili.'),
(1570699,54,41,6,31,'I řekl jim: Pojďte vy sami obzvláštně na pusté místo, a odpočiňte maličko. Nebo bylo množství těch, kteříž přicházeli a odcházeli, takže jsou ani k jídlu chvíle neměli.'),
(1570700,54,41,6,32,'I plavili se až na pusté místo soukromí.'),
(1570701,54,41,6,33,'A vidouce je zástupové, že jdou pryč, poznali jej mnozí. I sběhli se tam ze všech měst pěšky, a předešli je, a shromáždili se k němu.'),
(1570702,54,41,6,34,'Tedy vyšed Ježíš, uzřel zástup mnohý, a slitovalo mu se jich, že byli jako ovce, nemající pastýře. I počal je učiti mnohým věcem.'),
(1570703,54,41,6,35,'A když se již prodlilo, přistoupivše k němu učedlníci jeho, řekli: Pustéť jest toto místo, a již se prodlilo,'),
(1570704,54,41,6,36,'Rozpusť je, ať jdouce do okolních vesnic a městeček, nakoupí sobě chleba; nebo nemají, co by jedli.'),
(1570705,54,41,6,37,'On pak odpověděv, řekl jim: Dejte vy jim jísti. I řkou jemu: Co tedy, jdouce koupíme za dvě stě grošů chleba, a dáme jim jísti?'),
(1570706,54,41,6,38,'I dí jim: Kolik chlebů máte? Jděte a zvězte. A když zvěděli, řekli: Pět, a dvě rybě.'),
(1570707,54,41,6,39,'I rozkázal jim, aby se kázali posaditi všechněm po houfích na zelené trávě.'),
(1570708,54,41,6,40,'I usadili se rozdílně, místy po stu a místy po padesáti.'),
(1570709,54,41,6,41,'A vzav těch pět chlebů a ty dvě rybě, popatřiv do nebe, dobrořečil, i lámal chleby, a dal učedlníkům svým, aby kladli před ně. A dvě rybě rozdělil též mezi všecky.'),
(1570710,54,41,6,42,'I jedli všickni, a nasyceni jsou.'),
(1570711,54,41,6,43,'Potom sebrali drobtů dvanácte košů plných, i z ryb.'),
(1570712,54,41,6,44,'A bylo těch, kteříž jedli ty chleby, okolo pět tisíců mužů.'),
(1570713,54,41,6,45,'A hned přinutil učedlníky své vstoupiti na lodí, aby jej předešli přes moře do Betsaidy, až by on rozpustil zástup.'),
(1570714,54,41,6,46,'A rozpustiv je, šel na horu, aby se modlil.'),
(1570715,54,41,6,47,'A když bylo večer, byla lodí uprostřed moře, a on sám na zemi.'),
(1570716,54,41,6,48,'A viděl je, a oni se s těžkostí plavili; (nebo byl vítr odporný jim.) A při čtvrtém bdění nočním přišel k nim, chodě po moři, a chtěl je pominouti.'),
(1570717,54,41,6,49,'Oni pak uzřevše jej, an chodí po moři, domnívali se, že by obluda byla, i zkřikli.'),
(1570718,54,41,6,50,'(Nebo jej všickni viděli, a zstrašili se.) A hned promluvil k nim a řekl jim: Doufejtež, jáť jsem, nebojte se.'),
(1570719,54,41,6,51,'I vstoupil k nim na lodí, a utišil se vítr; a oni náramně sami v sobě se děsili a divili.'),
(1570720,54,41,6,52,'Nebo nerozuměli byli, co se stalo při chlebích; bylo zajisté srdce jejich zhrublo.'),
(1570721,54,41,6,53,'A když se přeplavili, přišli do země Genezaretské, a tu lodí přistavili.'),
(1570722,54,41,6,54,'A když vyšli z lodí, hned jej poznali.'),
(1570723,54,41,6,55,'A běhajíce po vší krajině té, počali na ložcích k němu nositi nemocné, kdežkoli zvěděli o něm, že by byl.'),
(1570724,54,41,6,56,'A kamžkoli vcházel do městeček neb do měst nebo do vsí, na ulicech kladli neduživé, a prosili ho, aby se aspoň podolka roucha jeho dotkli. A kolikož jich koli se jeho dotkli, uzdraveni byli.'),
(1570725,54,41,7,1,'I sešli se k němu farizeové a někteří z zákoníků, kteříž byli přišli z Jeruzaléma.'),
(1570726,54,41,7,2,'A uzřevše některé z učedlníků jeho obecnýma rukama (to jest neumytýma) jísti chleby, reptali o to.'),
(1570727,54,41,7,3,'Nebo farizeové i všickni Židé nejedí, leč by ruce umyli, držíce ustanovení starších.'),
(1570728,54,41,7,4,'A z trhu přijdouce nejedí, leč se umyjí. A jiné mnohé věci jsou, kteréž přijali, aby zachovávali, jako umývání koflíků, žejdlíků a medenic i stolů.'),
(1570729,54,41,7,5,'Potom otázali se ho farizeové a zákoníci: Proč učedlníci tvoji nezachovávají ustanovení starších, ale neumytýma rukama jedí chléb?'),
(1570730,54,41,7,6,'On pak odpověděv, řekl jim: Dobře o vás pokrytcích prorokoval Izaiáš, jakož psáno jest: Lid tento rty mne ctí, srdce pak jejich daleko jest ode mne.'),
(1570731,54,41,7,7,'Ale nadarmoť mne ctí, učíce učení, kterážto nejsou než ustanovení lidská.'),
(1570732,54,41,7,8,'Nebo opustivše přikázání Boží, držíte ustanovení lidská, totiž umývání žejdlíků a koflíků; a jiné mnohé věci těm podobné činíte.'),
(1570733,54,41,7,9,'I pravil jim: Čistě vy rušíte přikázání Boží, abyste ustanovení své zachovali.'),
(1570734,54,41,7,10,'Nebo Mojžíš pověděl: Cti otce svého i matku svou, a kdož by zlořečil otci nebo mateři, ať smrtí umře.'),
(1570735,54,41,7,11,'Ale vy pravíte: Řekl-li by člověk otci neb mateři: Korban, to jest, dar, kterýžkoli jest ode mne, toběť prospěje,'),
(1570736,54,41,7,12,'A nedopustíte mu nic více učiniti otci svému nebo mateři své,'),
(1570737,54,41,7,13,'Rušíce přikázání Boží ustanoveními vašimi, kteráž jste ustanovili. A mnohé těm podobné věci činíte.'),
(1570738,54,41,7,14,'I svolav všecken zástup, pravil jim: Slyšte mne všickni a rozumějte.'),
(1570739,54,41,7,15,'Nic není z zevnitřku vcházejícího do člověka, což by jej poskvrniti mohlo; ale to, což pochází z něho, toť jest, což poskvrňuje člověka.'),
(1570740,54,41,7,16,'Má-li kdo uši k slyšení, slyš.'),
(1570741,54,41,7,17,'A když všel do domu od zástupu, tázali se ho učedlníci jeho o tom podobenství.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570742,54,41,7,18,'I řekl jim: Tak jste i vy nerozumní? Což nerozumíte, že všecko, což z zevnitřku do člověka vchází, nemůže ho poskvrniti?'),
(1570743,54,41,7,19,'Nebo nevchází v srdce jeho, ale v břicho, a potom ven vychází, čistěci všeliké pokrmy.'),
(1570744,54,41,7,20,'Ale pravil, že to, což pochází z člověka, to poskvrňuje člověka.'),
(1570745,54,41,7,21,'Nebo z vnitřku z srdce lidského zlá myšlení pocházejí, cizoložstva, smilstva, vraždy,'),
(1570746,54,41,7,22,'Krádeže, lakomství, nešlechetnosti, lest, nestydatost, oko zlé, rouhání, pýcha, bláznovství.'),
(1570747,54,41,7,23,'Všecky tyto zlé věci pocházejí z vnitřku a poskvrňují člověka.'),
(1570748,54,41,7,24,'A vstav odtud, odšel do končin Týru a Sidonu, a všed do domu, nechtěl, aby kdo o něm věděl, ale nemohl se tajiti.'),
(1570749,54,41,7,25,'Nebo uslyševši o něm žena, jejížto dcerka měla ducha nečistého, přišla a padla k nohám jeho.'),
(1570750,54,41,7,26,'(Byla pak ta žena pohanka, Syrofenitská rodem.) I prosila ho, aby ďábelství vyvrhl z její dcery.'),
(1570751,54,41,7,27,'Ale Ježíš řekl jí: Nechať se prve nasytí synové; nebť není slušné vzíti chléb synů a vrci štěňatům.'),
(1570752,54,41,7,28,'A ona odpověděla a řekla mu: Ovšem, Pane, nebo štěňátka jedí pod stolem drobty synů.'),
(1570753,54,41,7,29,'I řekl jí: Pro tu řeč jdi, vyšloť jest ďábelství z tvé dcery.'),
(1570754,54,41,7,30,'I odšedši do domu svého, nalezla děvečku, ana leží na loži, a ďábelství z ní vyšlo.'),
(1570755,54,41,7,31,'Tedy odšed zase z končin Tyrských a Sidonských, přišel k moři Galilejskému, prostředkem krajin Desíti měst.'),
(1570756,54,41,7,32,'I přivedli jemu hluchého a němého, a prosili ho, aby na něj ruku vzložil.'),
(1570757,54,41,7,33,'A pojav jej soukromí ven z zástupu, vložil prsty své v uši jeho, a plinuv, dotekl se jazyka jeho.'),
(1570758,54,41,7,34,'A vzezřev k nebi, vzdechl, a řekl jemu: Effeta, to jest, otevři se.'),
(1570759,54,41,7,35,'A hned otevříny jsou uši jeho, a rozvázán jest svazek jazyka jeho, i mluvil právě.'),
(1570760,54,41,7,36,'I přikázal jim, aby žádnému nepravili. Ale jakžkoli on jim přikazoval, předce oni mnohem více ohlašovali.'),
(1570761,54,41,7,37,'A převelmi se divili, řkouce: Dobře všecky věci učinil. I hluchým rozkázal slyšeti, i němým mluviti.'),
(1570762,54,41,8,1,'V těch dnech když opět velmi veliký zástup byl s ním, a neměli, co by jedli, svolav Ježíš učedlníky své, řekl jim:'),
(1570763,54,41,8,2,'Lítost mám nad zástupy; nebo již tři dni trvají se mnou a nemají, co by jedli.'),
(1570764,54,41,8,3,'A rozpustím-li je lačné do domů jejich, zhynou na cestě; nebo někteří z nich zdaleka přišli.'),
(1570765,54,41,8,4,'Odpověděli mu učedlníci jeho: I odkud bude moci kdo tyto nakrmiti chleby zde na poušti?'),
(1570766,54,41,8,5,'I otázal se jich: Kolik chlebů máte? A oni řekli: Sedm.'),
(1570767,54,41,8,6,'I kázal zástupu posaditi se na zemi. A vzav sedm chlebů, díky učiniv, lámal a dával učedlníkům svým, aby předkládali. I kladli před zástup.'),
(1570768,54,41,8,7,'A měli také rybiček maličko. Jichž požehnav, kázal i ty před ně klásti.'),
(1570769,54,41,8,8,'I jedli a nasyceni jsou; a sebrali, což pozůstalo drobtů, sedm košů.'),
(1570770,54,41,8,9,'Těch pak, kteříž jedli, bylo okolo čtyř tisíců. I rozpustil je.'),
(1570771,54,41,8,10,'Potom hned vstoupiv na lodí s učedlníky svými, přeplavil se do krajin Dalmanutských.'),
(1570772,54,41,8,11,'I vyšli farizeové a počali se s ním hádati, hledajíce od něho znamení s nebe, pokoušejíce ho.'),
(1570773,54,41,8,12,'A on vzdech duchem svým, dí: Co pokolení toto znamení hledá? Amen pravím vám: Nebude dáno znamení pokolení tomuto.'),
(1570774,54,41,8,13,'A opustiv je, vstoupil zase na lodí, i plavil se přes moře.'),
(1570775,54,41,8,14,'I zapomenuli s sebou vzíti chlebů, a neměli než jeden chléb s sebou na lodí.'),
(1570776,54,41,8,15,'Tedy přikazoval jim, řka: Vizte a pilně se šetřte kvasu farizejského a kvasu Herodesova.'),
(1570777,54,41,8,16,'I přemyšlovali, řkouce jeden k druhému: Chleba nemáme.'),
(1570778,54,41,8,17,'A znaje to Ježíš, řekl jim: Co přemyšlujete o tom, že chleba nemáte? Ještě neznáte, ani rozumíte? Ještě máte oslepené srdce vaše?'),
(1570779,54,41,8,18,'Oči majíce, nevidíte? A uši majíce, neslyšíte? A nepomníte,'),
(1570780,54,41,8,19,'Že jsem pět chlebů lámal mezi pět tisíců? A kolik jste plných košů drobtů sebrali? Řekli jemu: Dvanácte.'),
(1570781,54,41,8,20,'A když také sedm chlebů lámal jsem mezi čtyři tisíce, kolik jste plných košů drobtů vzali? I řkou jemu: Sedm.'),
(1570782,54,41,8,21,'I řekl jim: Kterakž tedy ještě nerozumíte?'),
(1570783,54,41,8,22,'I přišel do Betsaidy, a přivedli k němu slepého, prosíce ho, aby se ho dotekl.'),
(1570784,54,41,8,23,'I ujav slepého za ruku, vyvedl jej ven z městečka, a plinuv na oči jeho a vloživ na něj ruce, otázal se ho, viděl-li by co.'),
(1570785,54,41,8,24,'A on pohleděv, řekl: Znamenám lidi; nebo vidím, že chodí jako stromové.'),
(1570786,54,41,8,25,'Potom opět vložil ruce na oči jeho, a kázal mu hleděti. I uzdraven jest, takže i zdaleka jasně viděl všecky.'),
(1570787,54,41,8,26,'I odeslal jej do domu jeho, řka: Aniž do toho městečka choď, aniž komu z městečka co o tom prav.'),
(1570788,54,41,8,27,'Tedy vyšel Ježíš a učedlníci jeho do městeček Cesaree Filipovy. A na cestě tázal se učedlníků svých, řka jim: Kým mne praví býti lidé?'),
(1570789,54,41,8,28,'Kteřížto odpověděli: Janem Křtitelem, a jiní Eliášem, jiní pak jedním z proroků.'),
(1570790,54,41,8,29,'Tedy on řekl jim: Vy pak kým mne býti pravíte? Odpověděv Petr, řekl jemu: Ty jsi Kristus.'),
(1570791,54,41,8,30,'I přikázal jim, aby toho o něm žádnému nepravili.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570792,54,41,8,31,'I počal učiti je, že Syn člověka musí mnoho trpěti, a potupen býti od starších a předních kněží a zákoníků, a zabit býti, a ve třech dnech z mrtvých vstáti.'),
(1570793,54,41,8,32,'Zjevně to slovo mluvil. A chytiv jej Petr, počal mu domlouvati.'),
(1570794,54,41,8,33,'Kterýžto obrátiv se a pohleděv na učedlníky své, přimluvil Petrovi, řka: Jdiž za mnou, satane; nebo nechápáš, co jest Božího, ale co lidského.'),
(1570795,54,41,8,34,'A svolav zástup s učedlníky svými, řekl jim: Chce-li kdo za mnou přijíti, zapři sebe sám, a vezmi kříž svůj, a následujž mne.'),
(1570796,54,41,8,35,'Nebo chtěl-li by kdo duši svou zachovati, ztratíť ji; pakli by kdo ztratil duši svou pro mne a pro evangelium, tenť ji zachová.'),
(1570797,54,41,8,36,'Nebo co prospěje člověku, by všecken svět získal, a své duši škodu učinil?'),
(1570798,54,41,8,37,'Aneb jakou dá člověk odměnu za duši svou?'),
(1570799,54,41,8,38,'Nebo kdož by se koli za mne styděl a za má slova v tomto pokolení cizoložném a hříšném, i Syn člověka styděti se bude za něj, když přijde v slávě Otce svého s anděly svatými.'),
(1570800,54,41,9,1,'I pravil jim: Amen pravím vám, žeť jsou někteří z stojících tuto, kteříž neokusí smrti, až i uzří království Boží přicházející v moci.'),
(1570801,54,41,9,2,'A po šesti dnech pojal Ježíš Petra a Jakuba a Jana, i uvedl je na horu vysokou soukromí samy, a proměnil se před nimi.'),
(1570802,54,41,9,3,'A učiněno jest roucho jeho stkvoucí a bílé velmi jako sníh, ješto tak bílého žádný bělič na zemi učiniti nemůže.'),
(1570803,54,41,9,4,'I uzřeli Eliáše s Mojžíšem, ani s Ježíšem mluví.'),
(1570804,54,41,9,5,'A odpověděv Petr, řekl k Ježíšovi: Mistře, dobréť jest nám tuto býti. Protož udělejme tři stánky, tobě jeden, Mojžíšovi jeden a Eliášovi jeden.'),
(1570805,54,41,9,6,'Nebo nevěděl, co mluví; byli zajisté přestrašeni.'),
(1570806,54,41,9,7,'I stal se oblak zastěňující je, a přišel hlas z oblaku, řkoucí: Tentoť jest ten Syn můj milý, jeho poslouchejte.'),
(1570807,54,41,9,8,'A hned obezřevše se, žádného víc neviděli než samého Ježíše s sebou.'),
(1570808,54,41,9,9,'A když sstupovali s hory, přikázal jim, aby toho žádnému nevypravovali, co viděli, než až Syn člověka z mrtvých vstane.'),
(1570809,54,41,9,10,'I zachovali tu věc u sebe, tížíce mezi sebou, co by to bylo z mrtvých vstáti?'),
(1570810,54,41,9,11,'I otázali se ho, řkouce: Což pak zákoníci praví, že Eliáš musí přijíti prve?'),
(1570811,54,41,9,12,'On pak odpověděv, řekl jim: Eliáš přijda nejprve, napraví všecky věci, a jakož psáno jest o Synu člověka, že má mnoho trpěti a za nic položen býti.'),
(1570812,54,41,9,13,'Ale pravím vám, že Eliáš již přišel, a učinili mu, což jsou chtěli, jakož psáno jest o něm.'),
(1570813,54,41,9,14,'Tedy přišed k učedlníkům, uzřel zástup veliký okolo nich a zákoníky, an se hádají s nimi.'),
(1570814,54,41,9,15,'A hned všecken zástup uzřev jej, ulekli se; a sběhše se, přivítali ho.'),
(1570815,54,41,9,16,'I otázal se zákoníků: Co se hádáte spolu?'),
(1570816,54,41,9,17,'A odpovídaje jeden z zástupu, řekl: Mistře, přivedl jsem syna svého k tobě, kterýž má ducha němého.'),
(1570817,54,41,9,18,'Ten kdyžkoli jej pochopí, lomcuje jím, a on se sliní, a škřipí zubami, a svadne. I řekl jsem učedlníkům tvým, aby jej vyvrhli, a nemohli.'),
(1570818,54,41,9,19,'A on odpovídaje jemu, řekl: Ó národe nevěrný! Ale dokudž s vámi budu? A dokudž vás trpěti budu? Přiveďte jej ke mně.'),
(1570819,54,41,9,20,'I přivedli ho k němu. A jakž jej uzřel, hned jím duch lomcoval; a padna na zemi, válel se a slinil.'),
(1570820,54,41,9,21,'I otázal se otce jeho: Dávno-li se jemu to stalo? A on řekl: Hned od dětinství.'),
(1570821,54,41,9,22,'A často jím metal i na oheň i do vody, aby jej zahubil. Ale můžeš-li co, spomoz nám, slituje se nad námi.'),
(1570822,54,41,9,23,'A Ježíš řekl jemu: Můžeš-li tomu věřiti; všeckoť jest možné věřícímu.'),
(1570823,54,41,9,24,'A ihned zvolav otec mládence toho s slzami, řekl: Věřím, Pane, spomoz nedověře mé.'),
(1570824,54,41,9,25,'Uzřev pak Ježíš, že se zástup sbíhá, přimluvil duchu tomu nečistému, řka jemu: Hluchý a němý duše, já tobě přikazuji, vyjdi z něho, a nevcházej více do něho.'),
(1570825,54,41,9,26,'Tedy křiče a velmi jím lomcuje, vyšel z něho. I učiněn jest člověk ten jako mrtvý, takže mnozí pravili, že umřel.'),
(1570826,54,41,9,27,'Ale Ježíš ujav jej za ruku, pozdvihl ho, a on vstal.'),
(1570827,54,41,9,28,'A když všel do domu, učedlníci jeho otázali ho soukromí: Pročež jsme my ho nemohli vyvrci?'),
(1570828,54,41,9,29,'I řekl jim: Toto pokolení nijakž nemůž vyhnáno býti, jediné modlitbou a postem.'),
(1570829,54,41,9,30,'A jdouce odtud, šli skrze Galilei, a nechtěl, aby kdo o tom věděl.'),
(1570830,54,41,9,31,'Nebo učil učedlníky své a pravil jim: Že Syn člověka dán bude v ruce lidské, a zamordujíť jej, ale zamordován jsa, třetí den z mrtvých vstane.'),
(1570831,54,41,9,32,'Oni pak nesrozuměli tomu povědění, a ostýchali se ho otázati.'),
(1570832,54,41,9,33,'I přišel do Kafarnaum, a v domě byv, otázal se jich: Co jste na cestě mezi sebou rozjímali?'),
(1570833,54,41,9,34,'A oni mlčeli. Nebo hádali se byli na cestě mezi sebou, kdo by z nich byl větší.'),
(1570834,54,41,9,35,'A posadiv se, zavolal dvanácti, a dí jim: Chce-li kdo první býti, budeť všech nejposlednější a všech služebník.'),
(1570835,54,41,9,36,'A vzav pacholátko, postavil je uprostřed nich, a vzav je na lokty své, řekl jim:'),
(1570836,54,41,9,37,'Kdož by koli jedno z takových dítek přijal ve jménu mém, mneť přijímá; a kdož by mne koli přijal, ne mneť přijímá, ale toho, kterýž mne poslal.'),
(1570837,54,41,9,38,'I odpověděl mu Jan, řka: Mistře, viděli jsme tam jednoho, an ve jménu tvém ďábly vymítá, kterýž nechodí s námi; i bránili jsme mu, protože s námi nechodí.'),
(1570838,54,41,9,39,'Ježíš pak řekl: Nebraňtež mu. Nebť není žádného, kterýž by divy činil ve jménu mém, ať by mohl snadně zle mluviti o mně.'),
(1570839,54,41,9,40,'Nebo kdož není proti nám, s námiť jest.'),
(1570840,54,41,9,41,'Kdož by koli zajisté dal vám píti číši vody ve jménu mém, protože jste Kristovi, amen pravím vám, neztratíť nikoli odplaty své.'),
(1570841,54,41,9,42,'A kdožť by koli pohoršil jednoho z těchto maličkých, věřících ve mne, mnohem by lépe mu bylo, aby byl zavěšen na hrdlo jeho žernov mlýnský a vržen byl do moře.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570842,54,41,9,43,'A horšila-li by tě ruka tvá, utni ji. Lépeť jest tobě bezrukému vjíti do života, raději nežli obě ruce majícímu jíti do pekla, v oheň neuhasitelný,'),
(1570843,54,41,9,44,'Kdež červ jejich neumírá a oheň nehasne.'),
(1570844,54,41,9,45,'A pakli noha tvá horšila by tě, utniž ji. Lépeť jest tobě kulhavému vjíti do života, nežli obě noze majícímu uvrženu býti do pekla, v oheň neuhasitelný,'),
(1570845,54,41,9,46,'Kdežto červ jejich neumírá a oheň nehasne.'),
(1570846,54,41,9,47,'Pakli by tě oko tvé horšilo, vylup je. Lépeť jest tobě jednookému vjíti do království Božího, nežli obě oči majícímu uvrženu býti do ohně pekelného,'),
(1570847,54,41,9,48,'Kdežto červ jejich neumírá a oheň nehasne.'),
(1570848,54,41,9,49,'Nebo každý člověk ohněm bude solen, a všeliká obět solí bude osolena.'),
(1570849,54,41,9,50,'Dobráť jest sůl. Pakli sůl bude neslaná, čím ji osolíte? Mějte sůl v sobě sami, a pokoj mějte mezi sebou.'),
(1570850,54,41,10,1,'A vstav odtud, přišel do končin Judských skrze krajinu za Jordánem ležící. I sešli se k němu zase zástupové, a jakž obyčej měl, opět je učil.'),
(1570851,54,41,10,2,'Tedy přistoupivše farizeové, otázali se ho: Sluší-li muži ženu propustiti? pokoušejíce ho.'),
(1570852,54,41,10,3,'On pak odpovídaje, řekl jim: Co vám přikázal Mojžíš?'),
(1570853,54,41,10,4,'Kteřížto řekli: Mojžíš dopustil lístek zapuzení napsati a propustiti.'),
(1570854,54,41,10,5,'I odpověděv Ježíš, řekl jim: Pro tvrdost srdce vašeho napsal vám Mojžíš to přikázání.'),
(1570855,54,41,10,6,'Ale od počátku stvoření muže a ženu učinil je Bůh.'),
(1570856,54,41,10,7,'Protoť opustí člověk otce svého i matku, a přídržeti se bude ženy své.'),
(1570857,54,41,10,8,'I budou dva jedno tělo. A tak již nejsou dva, ale jedno tělo.'),
(1570858,54,41,10,9,'Protož což Bůh spojil, člověk nerozlučuj.'),
(1570859,54,41,10,10,'A v domu opět učedlníci jeho otázali se ho o též věci.'),
(1570860,54,41,10,11,'I dí jim: Kdož by koli propustil manželku svou a jinou pojal, cizoloží a hřeší proti ní.'),
(1570861,54,41,10,12,'A jestliže by žena propustila muže svého a za jiného se vdala, cizoloží.'),
(1570862,54,41,10,13,'Tedy přinášeli k němu dítky, aby se jich dotýkal. Ale učedlníci přimlouvali těm, kteříž je nesli.'),
(1570863,54,41,10,14,'To viděv Ježíš, nelibě to nesl, a řekl jim: Nechtež dítek jíti ke mně a nebraňtež jim, nebo takovýchť jest království Boží.'),
(1570864,54,41,10,15,'Amen pravím vám: Kdož by koli nepřijal království Božího jako dítě, nikoliť do něho nevejde.'),
(1570865,54,41,10,16,'A bera je na lokty své a vzkládaje na ně ruce, požehnání jim dával.'),
(1570866,54,41,10,17,'Potom když vyšel na cestu, přiběhl jeden, a poklekna před ním, otázal se ho, řka: Mistře dobrý, co učiním, abych života věčného dědičně došel?'),
(1570867,54,41,10,18,'I řekl mu Ježíš: Co mne nazýváš dobrým? Žádný není dobrý, než sám toliko Bůh.'),
(1570868,54,41,10,19,'Přikázání umíš: Nezcizoložíš, nezabiješ, neukradneš, nevydáš falešného svědectví, neoklamáš, cti otce svého i matku.'),
(1570869,54,41,10,20,'A on odpověděv, řekl jemu: Mistře, toho všeho jsem ostříhal od své mladosti.'),
(1570870,54,41,10,21,'Tedy Ježíš pohleděv na něj, zamiloval ho, a řekl mu: Jednohoť se nedostává. Jdi, a cožkoli máš, prodej, a dej chudým, a budeš míti poklad v nebi; a pojď, následuj mne, vezma kříž svůj.'),
(1570871,54,41,10,22,'On pak zarmoutiv se pro to slovo, odšel, truchliv jsa; nebo měl mnohá zboží.'),
(1570872,54,41,10,23,'A pohleděv vůkol Ježíš, dí učedlníkům svým: Aj jak nesnadně ti, jenž statky mají, vejdou do království Božího.'),
(1570873,54,41,10,24,'Tedy učedlníci užasli se nad řečmi jeho. Ježíš pak zase odpověděv, dí jim: Synáčkové, kterak nesnadné jest doufajícím v statek do království Božího vjíti.'),
(1570874,54,41,10,25,'Snáze jest velbloudu skrze jehelní ucho projíti, nežli bohatému vjíti do království Božího.'),
(1570875,54,41,10,26,'Oni pak více se děsili, řkouce mezi sebou: I kdož může spasen býti?'),
(1570876,54,41,10,27,'A pohleděv na ně Ježíš, dí: U lidíť jest nemožné, ale ne u Boha; nebo u Boha všecko možné jest.'),
(1570877,54,41,10,28,'I počal Petr mluviti k němu: Aj, my opustili jsme všecko a šli jsme za tebou.'),
(1570878,54,41,10,29,'Odpověděv pak Ježíš, řekl: Amen pravím vám, žádného není, ješto by opustil dům, neb bratří, nebo sestry, neb otce, nebo matku, nebo manželku, nebo syny, nebo rolí pro mne a pro evangelium,'),
(1570879,54,41,10,30,'Aby nevzal stokrát tolik nyní v času tomto domů a bratrů a sestr a matek a synů a rolí s protivenstvím, a v budoucím věku život věčný.'),
(1570880,54,41,10,31,'Mnozíť zajisté byvše první, budou poslední, a poslední první.'),
(1570881,54,41,10,32,'Byli pak na cestě, jdouce do Jeruzaléma, a Ježíš šel napřed. I byli předěšeni, a jdouce za ním, báli se. Tedy pojav Ježíš opět dvanácte, počal jim praviti, co se jemu má státi,'),
(1570882,54,41,10,33,'Řka: Aj, vstupujeme do Jeruzaléma, a Syn člověka vydán bude předním kněžím a zákoníkům, i odsoudí jej na smrt, a vydadí jej pohanům.'),
(1570883,54,41,10,34,'Kteřížto posmívati se budou jemu, a ubičují ho, a uplijí a zabijí jej, ale třetího dne z mrtvých vstane.'),
(1570884,54,41,10,35,'Tedy přistoupili k němu Jakub a Jan, synové Zebedeovi, řkouce: Mistře, chceme, zač bychom koli prosili tebe, abys učinil nám.'),
(1570885,54,41,10,36,'On pak řekl jim: Co chcete, abych vám učinil?'),
(1570886,54,41,10,37,'I řekli jemu: Dej nám, abychom jeden na pravici tvé a druhý na levici tvé seděli v slávě tvé.'),
(1570887,54,41,10,38,'Ježíš pak řekl jim: Nevíte, zač prosíte. Můžete-li píti kalich, kterýž já piji, a křtíti se křtem, kterýmž já se křtím?'),
(1570888,54,41,10,39,'A oni řekli jemu: Můžeme. A Ježíš řekl jim: Kalich zajisté, kterýž já piji, píti budete, a křtem, kterýmž já se křtím, křtěni budete,'),
(1570889,54,41,10,40,'Ale seděti na pravici mé, nebo na levici mé, neníť má věc dáti vám, ale dánoť bude, kterýmž připraveno jest.'),
(1570890,54,41,10,41,'A uslyšavše to jiných deset, počali se hněvati na Jakuba a na Jana.'),
(1570891,54,41,10,42,'Ale Ježíš povolav jich, řekl jim: Víte, že ti, kteříž sobě zalibují vládnouti nad národy, panujíť nad nimi; a kteříž velicí u nich jsou, moc provozují nad nimi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570892,54,41,10,43,'Ne takť bude mezi vámi. Ale kdožkoli chtěl by mezi vámi býti veliký, budiž váš služebník.'),
(1570893,54,41,10,44,'A kdožkoli z vás chtěl by býti přední, budiž služebník všech.'),
(1570894,54,41,10,45,'Nebo i Syn člověka nepřišel, aby mu sloužili, ale aby on sloužil, a aby dal duši svou na vykoupení za mnohé.'),
(1570895,54,41,10,46,'Tedy přišli do Jericho, a když vycházel on z Jericha, i učedlníci jeho a zástup mnohý, Timeův syn, Bartimeus slepý, seděl podle cesty, žebře.'),
(1570896,54,41,10,47,'A když uslyšel, že by to byl Ježíš Nazaretský, počal volati a říci: Ježíši, synu Davidův, smiluj se nade mnou.'),
(1570897,54,41,10,48,'I přimlouvali mu mnozí, aby mlčel. Ale on mnohem více volal: Synu Davidův, smiluj se nade mnou.'),
(1570898,54,41,10,49,'Tedy zastaviv se Ježíš, kázal ho zavolati. I zavolali toho slepého, řkouce jemu: Dobré mysli buď, vstaň, volá tě.'),
(1570899,54,41,10,50,'On pak povrh plášť svůj, a zchopiv se, šel k Ježíšovi.'),
(1570900,54,41,10,51,'I odpověděv Ježíš, dí jemu: Co chceš, ať učiním? A slepý řekl jemu: Mistře, ať vidím.'),
(1570901,54,41,10,52,'Tedy Ježíš řekl mu: Jdi, víra tvá tě uzdravila. A on hned prohlédl, a šel cestou za Ježíšem.'),
(1570902,54,41,11,1,'A když se přiblížili k Jeruzalému a Betfagi i Betany při hoře Olivetské, poslal dva z učedlníků svých,'),
(1570903,54,41,11,2,'A řekl jim: Jděte do hrádku, kterýž proti vám jest, a hned vejdouce tam, naleznete oslátko přivázané, na kterémž ještě nižádný z lidí neseděl. Odvížíce, přiveďte ke mně.'),
(1570904,54,41,11,3,'A řekl-liť by vám kdo: Co to činíte? rcete: Že ho Pán potřebuje. A hned je propustí sem.'),
(1570905,54,41,11,4,'I odešli, a nalezli oslátko přivázané vně u dveří na rozcestí. I odvázali je.'),
(1570906,54,41,11,5,'Tedy někteří z těch, kteříž tu stáli, řekli jim: Co činíte, odvazujíce oslátko?'),
(1570907,54,41,11,6,'Oni pak řekli jim, jakož byl přikázal Ježíš. I nechali jich.'),
(1570908,54,41,11,7,'Protož přivedli oslátko k Ježíšovi, a vložili na ně roucha svá. I vsedl na ně.'),
(1570909,54,41,11,8,'Mnozí pak stlali roucha svá na cestě, a jiní ratolesti sekali z stromů, a metali na cestu.'),
(1570910,54,41,11,9,'A kteříž napřed šli, i ti, kteříž za ním šli, volali, řkouce: Spas nás. Požehnaný, jenž se béře ve jménu Páně.'),
(1570911,54,41,11,10,'Požehnané, kteréž jest přišlo ve jménu Páně, království otce našeho Davida! Spas nás na výsostech.'),
(1570912,54,41,11,11,'I všel do Jeruzaléma Ježíš, i do chrámu. A spatřiv tu všecko, když již byla večerní hodina, vyšel do Betany se dvanácti.'),
(1570913,54,41,11,12,'A druhého dne, když vycházel z Betany, zlačněl.'),
(1570914,54,41,11,13,'A uzřev zdaleka fík, an má listí, šel, zda by co nalezl na něm. A když přišel k němu, nic nenalezl kromě listí; nebo nebyl čas fíků.'),
(1570915,54,41,11,14,'Tedy odpověděv Ježíš, řekl jemu: Již více na věky nižádný z tebe ovoce nejez. A slyšeli to učedlníci jeho.'),
(1570916,54,41,11,15,'I přišli do Jeruzaléma. A všed Ježíš do chrámu, počal vymítati ty, jenž prodávali a kupovali v chrámě, a stoly penězoměnců a stolice prodávajících holuby převracel.'),
(1570917,54,41,11,16,'A nedopustil, aby kdo jakou nádobu nesl skrze chrám.'),
(1570918,54,41,11,17,'I učil je, řka jim: Zdaliž není psáno, že dům můj dům modlitby slouti bude u všech národů? Vy pak učinili jste jej peleší lotrů.'),
(1570919,54,41,11,18,'Slyšeli pak to zákoníci i přední kněží, a hledali, kterak by jej zahubili; nebo se ho báli, protože všecken zástup divil se učení jeho.'),
(1570920,54,41,11,19,'A když byl večer, vyšel Ježíš z města.'),
(1570921,54,41,11,20,'A učedlníci ráno jdouce, uzřeli fík, an usechl hned z kořene.'),
(1570922,54,41,11,21,'Tedy zpomenuv Petr, řekl jemu: Mistře, aj fík, kterémuž jsi zlořečil, usechl.'),
(1570923,54,41,11,22,'I odpověděv Ježíš, řekl jim: Mějte víru Boží.'),
(1570924,54,41,11,23,'Nebo amen pravím vám, že kdož by koli řekl hoře této: Zdvihni se a vrz sebou do moře, a nepochyboval by v srdci svém, ale věřil by, že se stane, cožkoli dí, budeť jemu tak, což by koli řekl.'),
(1570925,54,41,11,24,'Protož pravím vám: Začež byste koli, modléce se, prosili, věřte, že vezmete, a staneť se vám.'),
(1570926,54,41,11,25,'A když se postavíte k modlení, odpouštějte, máte-li co proti komu, aby i Otec váš nebeský odpustil vám hříchy vaše.'),
(1570927,54,41,11,26,'Nebo jestliže vy neodpustíte, ani Otec váš, kterýž v nebesích jest, odpustí vám hříchů vašich.'),
(1570928,54,41,11,27,'I přišli zase do Jeruzaléma. A když on chodil v chrámě, přistoupili k němu přední kněží a zákoníci a starší.'),
(1570929,54,41,11,28,'I řekli jemu: Jakou mocí to činíš? A kdo jest tobě dal tu moc, abys tyto věci činil?'),
(1570930,54,41,11,29,'Tedy odpovídaje Ježíš, řekl jim: Otížiť se i já vás na jednu věc. Odpovězte mi, a povím vám, jakou mocí to činím.'),
(1570931,54,41,11,30,'Křest Janův s nebe-li byl, čili z lidí? Odpovězte mi.'),
(1570932,54,41,11,31,'I rozvažovali to sami mezi sebou, řkouce: Díme-li: S nebe, díť nám: Pročež jste tedy neuvěřili jemu?'),
(1570933,54,41,11,32,'Pakli díme: Z lidí, bojíme se lidu. Nebo všickni o Janovi smyslili, že jest právě byl prorok.'),
(1570934,54,41,11,33,'I odpověděvše, řekli Ježíšovi: Nevíme. A Ježíš odpovídaje, řekl jim: Aniž já vám povím, jakou mocí to činím.'),
(1570935,54,41,12,1,'Tedy počal jim mluviti v podobenstvích: Vinici štípil jeden člověk, a opletl ji plotem, a vkopal pres, a ustavěl věži, a najal ji vinařům, i odšel na cestu.'),
(1570936,54,41,12,2,'A v čas užitků poslal k vinařům služebníka, aby od vinařů vzal ovoce z vinice.'),
(1570937,54,41,12,3,'Oni pak javše jej, zmrskali ho a odeslali prázdného.'),
(1570938,54,41,12,4,'I poslal k nim zase jiného služebníka. I toho též kamenovavše, ranili v hlavu a odeslali zohaveného.'),
(1570939,54,41,12,5,'I poslal opět jiného. I toho zabili, a mnoho jiných, z nichž některé zmrskali a jiné zmordovali.'),
(1570940,54,41,12,6,'Ještě pak maje jediného syna nejmilejšího, i toho poslal k nim naposledy, řka: Ostýchati se budou syna mého.'),
(1570941,54,41,12,7,'Ale vinaři řekli jedni k druhým: Tentoť jest dědic; pojďte, zabijme jej, a budeť naše dědictví.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570942,54,41,12,8,'Tedy javše jej, zabili ho a vyvrhli ven z vinice.'),
(1570943,54,41,12,9,'Což tedy učiní pán vinice? Přijde, a zatratí vinaře ty, a dá vinici jiným.'),
(1570944,54,41,12,10,'Zdaliž jste písma toho nečtli? Kámen, kterýž zavrhli dělníci, ten učiněn jest hlavou úhlovou.'),
(1570945,54,41,12,11,'Ode Pána stalo se toto, a jest divné před očima našima.'),
(1570946,54,41,12,12,'I hledali ho jíti, ale báli se zástupu; nebo poznali, že podobenství to proti nim pověděl. A nechavše ho, odešli pryč.'),
(1570947,54,41,12,13,'Potom poslali k němu některé z farizeů a herodiánů, aby jej polapili v řeči.'),
(1570948,54,41,12,14,'Kteřížto přišedše, řekli jemu: Mistře, víme, že jsi pravdomluvný, a nedbáš na žádného; nebo nepatříš na osobu lidskou, ale v pravdě cestě Boží učíš. Sluší-li daň dávati císaři, čili nic? Dáme-liž, čili nedáme?'),
(1570949,54,41,12,15,'On pak znaje pokrytství jejich, řekl jim: Co mne pokoušíte? Přineste mi peníz, ať pohledím.'),
(1570950,54,41,12,16,'A oni podali mu. Tedy řekl jim: Čí jest tento obraz a nápis? A oni řekli mu: Císařův.'),
(1570951,54,41,12,17,'I odpověděv Ježíš, řekl jim: Dávejtež tedy, což jest císařova, císaři, a což jest Božího, Bohu. I podivili se tomu.'),
(1570952,54,41,12,18,'Potom přišli k němu saduceové, kteříž praví, že není z mrtvých vstání. I otázali se ho, řkouce:'),
(1570953,54,41,12,19,'Mistře, Mojžíš nám napsal: Kdyby čí bratr umřel, a ostavil po sobě manželku, a synů by neměl, aby bratr jeho pojal manželku jeho a vzbudil símě bratru svému.'),
(1570954,54,41,12,20,'I bylo sedm bratrů. A první pojav ženu, umřel, neostaviv semene.'),
(1570955,54,41,12,21,'A druhý pojav ji, také umřel, a aniž ten ostavil semene. A třetí tolikéž.'),
(1570956,54,41,12,22,'A tak ji pojalo všech sedm, a nezůstavili po sobě semene. Nejposléze pak po všech umřela i žena.'),
(1570957,54,41,12,23,'Protož při vzkříšení, když z mrtvých vstanou, čí z těch bude manželka? Neb jich sedm mělo ji za manželku.'),
(1570958,54,41,12,24,'A odpovídaje Ježíš, řekl jim: Zdaliž ne proto bloudíte, že neznáte Písem ani moci Boží?'),
(1570959,54,41,12,25,'Nebo když vstanou z mrtvých, nebudou se ženiti ani vdávati, ale budou jako andělé nebeští.'),
(1570960,54,41,12,26,'O mrtvých pak, že mají vstáti, zdaliž jste nečtli v knihách Mojžíšových, kterak ve kři promluvil k němu Bůh, řka: Já jsem Bůh Abrahamův a Bůh Izákův a Bůh Jákobův?'),
(1570961,54,41,12,27,'Neníť Bůh mrtvých, ale Bůh živých. Protož vy velmi bloudíte.'),
(1570962,54,41,12,28,'Tedy přistoupil k němu jeden z zákoníků, slyšev je hádající se, a vida, že jim dobře odpověděl, otázal se ho, které by bylo přikázání první ze všech.'),
(1570963,54,41,12,29,'A Ježíš odpověděl jemu, že první ze všech přikázání jest: Slyš, Izraeli, Pán Bůh náš Pán jeden jest.'),
(1570964,54,41,12,30,'Protož milovati budeš Pána Boha svého ze všeho srdce svého, a ze vší duše své, a ze vší mysli své, i ze všech mocí svých. To jest první přikázání.'),
(1570965,54,41,12,31,'Druhé pak jest podobné tomu: Milovati budeš bližního svého jako sebe samého. Většího přikázání jiného nad tato není.'),
(1570966,54,41,12,32,'I řekl jemu ten zákoník: Mistře, dobře jsi vpravdě pověděl. Nebo jeden jest Bůh, a není jiného kromě něho;'),
(1570967,54,41,12,33,'A milovati ho ze všeho srdce, a ze vší mysli, a ze vší duše, i ze všech mocí, a milovati bližního jako sebe samého, toť jest větší nade všecky zápalné i vítězné oběti.'),
(1570968,54,41,12,34,'A viděv Ježíš, že by moudře odpověděl, dí jemu: Nejsi daleko od království Božího. A žádný více neodvážil se ho o nic tázati.'),
(1570969,54,41,12,35,'I odpovídaje Ježíš, řekl, uče v chrámě: Kterak praví zákoníci, že Kristus jest syn Davidův?'),
(1570970,54,41,12,36,'Nebo David praví v Duchu svatém: Řekl Pán Pánu mému: Seď na pravici mé, ažť i položím nepřátely tvé podnože noh tvých.'),
(1570971,54,41,12,37,'Poněvadž sám David nazývá jej Pánem, kterakž syn jeho jest? A mnohý zástup rád ho poslouchal.'),
(1570972,54,41,12,38,'I mluvil jim v učení svém: Varujte se zákoníků, kteříž rádi v krásném rouše chodí, a chtějí pozdravováni býti na trhu,'),
(1570973,54,41,12,39,'A na předních stolicích seděti v školách, a přední místa míti na večeřech,'),
(1570974,54,41,12,40,'Kteřížto zžírají domy vdovské pod zámyslem dlouhých modliteb. Tiť vezmou soud těžší.'),
(1570975,54,41,12,41,'A posadiv se Ježíš proti pokladnici, díval se, kterak zástup metal peníze do pokladnice. A mnozí bohatí metali mnoho.'),
(1570976,54,41,12,42,'A přišedši jedna chudá vdova, i vrhla dva šarty, jenž jest čtvrtá částka peníze tehdejšího.'),
(1570977,54,41,12,43,'I svolav učedlníky své, dí jim: Amen pravím vám, že tato chudá vdova více uvrhla, než tito všickni, kteříž metali do pokladnice.'),
(1570978,54,41,12,44,'Nebo všickni z toho, což jim zbývalo, metali, ale tato z své chudoby, všecko, což měla, uvrhla, všecku živnost svou.'),
(1570979,54,41,13,1,'A když vycházel z chrámu, dí jemu jeden z učedlníků jeho: Mistře, pohleď, kteraké kamení a jaké jest toto stavení!'),
(1570980,54,41,13,2,'Tedy Ježíš odpovídaje, řekl jemu: Vidíš toto tak veliké stavení? Nebudeť ostaven kámen na kameni, kterýž by nebyl zbořen.'),
(1570981,54,41,13,3,'A když se posadil na hoře Olivetské proti chrámu, otázali se jeho obzvláštně Petr, Jakub a Jan a Ondřej, řkouce:'),
(1570982,54,41,13,4,'Pověz nám, kdy to bude? A které znamení, když se toto všecko bude plniti?'),
(1570983,54,41,13,5,'Ježíš pak odpovídaje jim, počal praviti: Vizte, aby vás někdo nesvedl.'),
(1570984,54,41,13,6,'Neboť mnozí přijdou ve jménu mém, řkouce: Já jsem Kristus, a mnohéť svedou.'),
(1570985,54,41,13,7,'Když pak uslyšíte boje a pověst o válkách, nestrachujte se; nebo musí to býti, ale ne ihned konec.'),
(1570986,54,41,13,8,'Povstaneť zajisté národ proti národu a království proti království, a bude zemětřesení po místech, a hladové i bouřky.'),
(1570987,54,41,13,9,'A toť budou počátkové bolesti. Vy pak šetřte se. Nebo vydávati vás budou na sněmy a do shromáždění; budete biti, a před vladaři a králi stanete pro mne, na svědectví jim.'),
(1570988,54,41,13,10,'Ale ve všech národech nejprv musí býti kázáno evangelium.'),
(1570989,54,41,13,11,'Když pak vás povedou vyzrazujíce, nestarejte se, co byste mluvili, aniž o to pečlivě přemyšlujte, ale což vám bude dáno v tu hodinu, to mluvte; nebo nejste vy, jenž mluvíte, ale Duch svatý.'),
(1570990,54,41,13,12,'Vydáť pak bratr bratra na smrt a otec syna, a povstanou děti proti rodičům, a budou je mordovati.'),
(1570991,54,41,13,13,'A budete v nenávisti všechněm pro jméno mé. Ale kdož setrvá až do konce, tenť spasen bude.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1570992,54,41,13,14,'Když pak uzříte ohavnost zpuštění, o kteréž povědíno jest skrze Daniele proroka, ana stojí, kdež by státi neměla, (kdo čte, rozuměj,) tehdáž ti, kdož jsou v Židovstvu, ať utekou na hory.'),
(1570993,54,41,13,15,'A kdož na střeše jest, nesstupuj do domu, ani vcházej, aby co vzal z domu svého.'),
(1570994,54,41,13,16,'A kdo na poli, nevracuj se zase, aby vzal roucho své.'),
(1570995,54,41,13,17,'Běda pak těhotným a těm, kteréž krmí v těch dnech.'),
(1570996,54,41,13,18,'Protož modlte se, aby utíkání vaše nebylo v zimě.'),
(1570997,54,41,13,19,'Neboť budou ti dnové plní takového soužení, jakéhož nebylo od počátku stvoření, kteréž Bůh stvořil, až dosavad, aniž potom bude.'),
(1570998,54,41,13,20,'A byť neukrátil Pán těch dnů, nebyl by spasen žádný člověk. Ale pro vyvolené, kteréž vyvolil, ukrátil těch dnů.'),
(1570999,54,41,13,21,'A tehdáž řekl-li by vám kdo: Aj teď jest Kristus, aneb, aj tamto, nevěřte.'),
(1571000,54,41,13,22,'Neboť povstanou falešní Kristové a falešní proroci, a budou činiti divy a zázraky k svedení, by možné bylo, také i vyvolených.'),
(1571001,54,41,13,23,'Vy pak šetřte se. Aj, předpověděl jsem vám všecko.'),
(1571002,54,41,13,24,'V těch pak dnech, po soužení tom, slunce se zatmí a měsíc nedá světla svého.'),
(1571003,54,41,13,25,'A hvězdy nebeské budou padati, a moci, které jsou na nebi, pohnou se.'),
(1571004,54,41,13,26,'A tehdážť uzří Syna člověka, an se béře v oblacích s mocí velikou a s slavou.'),
(1571005,54,41,13,27,'I tehdyť pošle anděly své, a shromáždí vyvolené své ode čtyř větrů, od končin země až do končin nebe.'),
(1571006,54,41,13,28,'Od fíku pak učte se podobenství: Když již ratolest jeho odmladne a vypučí se listí, znáte, že blízko jest léto.'),
(1571007,54,41,13,29,'Takž i vy, když uzříte, ano se tyto věci dějí, vězte, že blízko jest a ve dveřích království Boží.'),
(1571008,54,41,13,30,'Amen pravím vám, žeť nepomine pokolení toto, až se tyto všecky věci stanou.'),
(1571009,54,41,13,31,'Nebe a země pominou, ale slova má nepominou.'),
(1571010,54,41,13,32,'Ale o tom dni a hodině žádný neví, ani andělé, jenž jsou v nebesích, ani Syn, jediné sám Otec.'),
(1571011,54,41,13,33,'Vizte, bděte a modlte se; nebo nevíte, kdy bude ten čas.'),
(1571012,54,41,13,34,'Syn člověka zajisté jest jako člověk, kterýž daleko odšel, opustiv dům svůj, a poručiv služebníkům svým vladařství, a jednomu každému práci jeho, vrátnému přikázal, aby bděl.'),
(1571013,54,41,13,35,'Protož bděte; nebo nevíte, kdy Pán domu přijde, u večer-li, čili o půlnoci, čili když kohouti zpívají, čili ráno;'),
(1571014,54,41,13,36,'Aby snad přijda v nenadále, nenalezl vás, a vy spíte.'),
(1571015,54,41,13,37,'A cožť vám pravím, všechněmť pravím: Bděte.'),
(1571016,54,41,14,1,'Po dvou pak dnech byl hod beránka a přesnic; i hledali přední kněží a zákoníci, kterak by jej lstivě jmouce, zamordovali.'),
(1571017,54,41,14,2,'Ale pravili: Ne v svátek, aby snad nebyl rozbroj v lidu.'),
(1571018,54,41,14,3,'A když byl v Betany, v domu Šimona malomocného, a seděl za stolem, přišla žena, mající nádobu alabastrovou masti velmi drahé, z nardového koření. A rozbivši nádobu, vylila ji na hlavu jeho.'),
(1571019,54,41,14,4,'I hněvali se někteří mezi sebou, řkouce: I proč ztráta masti této stala se?'),
(1571020,54,41,14,5,'Nebo mohlo jest toto prodáno býti dráže než za tři sta peněz, a dáno býti chudým. I škřipěli zubami na ni.'),
(1571021,54,41,14,6,'Ale Ježíš řekl: Nechtež jí. Proč ji rmoutíte? Dobrýť jest skutek učinila nade mnou.'),
(1571022,54,41,14,7,'Však chudé máte vždycky s sebou, a když budete chtíti, můžete jim dobře činiti, ale mne ne vždy míti budete.'),
(1571023,54,41,14,8,'Ona což mohla, to učinila; předešlať jest, aby těla mého pomazala ku pohřebu.'),
(1571024,54,41,14,9,'Amen pravím vám: Kdežkoli bude kázáno toto evangelium po všem světě, také i to, což učinila tato, bude vypravováno na památku její.'),
(1571025,54,41,14,10,'Tedy Jidáš Iškariotský, jeden ze dvanácti, odšel k předním kněžím, aby ho jim zradil.'),
(1571026,54,41,14,11,'Oni pak uslyševše to, zradovali se, a slíbili mu peníze dáti. I hledal, kterak by ho příhodně zradil.'),
(1571027,54,41,14,12,'Prvního pak dne přesnic, když velikonoční beránek zabíjín býval, řkou jemu učedlníci jeho: Kde chceš, ať jdouce, připravíme, abys jedl beránka?'),
(1571028,54,41,14,13,'I poslal dva z učedlníků svých, a řekl jim: Jděte do města, a potkáť vás člověk dčbán vody nesa. Jdětež za ním.'),
(1571029,54,41,14,14,'A kamžkoli vejde, rcete k hospodáři domu toho: Mistrť praví: Kde jest večeřadlo, v němž bych jedl beránka s učedlníky svými?'),
(1571030,54,41,14,15,'A on vám ukáže večeřadlo veliké, podlážené a připravené. Tu nám připravte.'),
(1571031,54,41,14,16,'I odešli učedlníci jeho, a přišli do města, a nalezli tak, jakož jim byl pověděl. I připravili beránka.'),
(1571032,54,41,14,17,'Když pak byl večer, přišel se dvanácti.'),
(1571033,54,41,14,18,'A když seděli za stolem a jedli, řekl Ježíš: Amen pravím vám, že jeden z vás mne zradí, kterýž jí se mnou.'),
(1571034,54,41,14,19,'A oni počali se rmoutiti a praviti jemu jeden každý obzvláštně: Zdali já jsem? A jiný: Zdali já?'),
(1571035,54,41,14,20,'On pak odpověděv, řekl jim: Jeden ze dvanácti, kterýž omáčí se mnou v míse.'),
(1571036,54,41,14,21,'Syn zajisté člověka jde, jakož jest psáno o něm, ale běda člověku tomu, skrze něhož Syn člověka bude zrazen. Dobré by bylo jemu, aby se byl nenarodil člověk ten.'),
(1571037,54,41,14,22,'A když oni jedli, vzav Ježíš chléb, a dobrořečiv, lámal a dával jim, řka: Vezměte, jezte, to jest tělo mé.'),
(1571038,54,41,14,23,'A vzav kalich, a díky učiniv, dal jim. A pili z něho všickni.'),
(1571039,54,41,14,24,'I řekl jim: To jest krev má nového Zákona, kteráž se za mnohé vylévá.'),
(1571040,54,41,14,25,'Amen pravím vám, žeť již více nebudu píti z plodu vinného kořene, až do onoho dne, když jej píti budu nový v království Božím.'),
(1571041,54,41,14,26,'A sezpívavše písničku, vyšli na horu Olivetskou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571042,54,41,14,27,'Potom řekl jim Ježíš: Všickni vy zhoršíte se nade mnou této noci. Nebo psáno jest: Bíti budu pastýře, a rozprchnou se ovce.'),
(1571043,54,41,14,28,'Ale když z mrtvých vstanu, předejduť vás do Galilee.'),
(1571044,54,41,14,29,'Tedy Petr řekl jemu: Byť se pak všickni zhoršili, ale já nic.'),
(1571045,54,41,14,30,'Řekl jemu Ježíš: Amen pravím tobě, že dnes této noci, prve než kohout po dvakrát zazpívá, třikrát mne zapříš.'),
(1571046,54,41,14,31,'On pak mnohem více mluvil: Bychť pak měl s tebou i umříti, nezapřímť tebe. A takž také i všickni mluvili.'),
(1571047,54,41,14,32,'I přišli na místo, kterémuž jméno Getsemany. Tedy řekl učedlníkům svým: Seďtež tuto, ažť se pomodlím.'),
(1571048,54,41,14,33,'A pojav s sebou Petra a Jakuba a Jana, počal se lekati a velmi teskliv býti.'),
(1571049,54,41,14,34,'I dí jim: Smutnáť jest duše má až k smrti. Počekejtež tuto a bděte.'),
(1571050,54,41,14,35,'A poodšed maličko, padl na zemi a modlil se, aby, bylo-li by možné, odešla od něho hodina ta.'),
(1571051,54,41,14,36,'I řekl: Abba, Otče, všecko jest možné tobě. Přenes kalich tento ode mne, ale však ne, což já chci, ale co ty.'),
(1571052,54,41,14,37,'I přišel k učedlníkům a nalezl je, ani spí. I řekl Petrovi: Šimone, spíš? Nemohl-lis jediné hodiny bdíti?'),
(1571053,54,41,14,38,'Bděte a modlte se, abyste nevešli v pokušení. Duchť zajisté hotov jest, ale tělo nemocno.'),
(1571054,54,41,14,39,'A opět odšed, modlil se, táž slova mluvě.'),
(1571055,54,41,14,40,'A navrátiv se, nalezl je, ani opět spí; nebo oči jejich byly obtíženy; aniž věděli, co by jemu odpověděli.'),
(1571056,54,41,14,41,'I přišel po třetí, a řekl jim: Spětež již a odpočívejte; dostiť jest. Přišla hodina; aj, Syna člověka zrazují v ruce hříšných.'),
(1571057,54,41,14,42,'Vstaňte, pojďme. Aj, kterýž mne zrazuje, blízkoť jest.'),
(1571058,54,41,14,43,'A hned, když on ještě mluvil, přišel Jidáš, jenž byl jeden ze dvanácti, a s ním zástup veliký s meči a s kyjmi, poslaných od předních kněží a od zákoníků a starších.'),
(1571059,54,41,14,44,'Zrádce pak byl jim dal znamení, řka: Kteréhožkoli políbím, tenť jest, jmětež ho a veďte opatrně.'),
(1571060,54,41,14,45,'A přišed, hned přistoupiv k němu, řekl: Mistře, Mistře, a políbil ho.'),
(1571061,54,41,14,46,'Tedy oni vztáhli naň ruce své a jali jej.'),
(1571062,54,41,14,47,'Jeden pak z těch, kteříž tu okolo stáli, vytrh meč, udeřil služebníka nejvyššího kněze, a uťal jemu ucho.'),
(1571063,54,41,14,48,'I odpověděv Ježíš, řekl jim: Jako na lotra vyšli jste s meči a s kyjmi, abyste mne jali?'),
(1571064,54,41,14,49,'Na každý den býval jsem u vás, uče v chrámě, a nejali jste mne. Ale toť se děje, aby se naplnila písma.'),
(1571065,54,41,14,50,'Tedy učedlníci opustivše jej, všickni utekli.'),
(1571066,54,41,14,51,'Jeden pak mládenček šel za ním, odín jsa rouchem lněným po nahém těle. I popadli jej mládenci.'),
(1571067,54,41,14,52,'On pak opustiv roucho, nahý utekl od nich.'),
(1571068,54,41,14,53,'I přivedli Ježíše k nejvyššímu knězi, a sešli se k němu všickni přední kněží i starší i zákoníci.'),
(1571069,54,41,14,54,'Petr pak šel za ním zdaleka až na dvůr nejvyššího kněze; i seděl s služebníky, zhřívaje se u ohně.'),
(1571070,54,41,14,55,'Ale nejvyšší kněz i všecka ta rada hledali proti Ježíšovi svědectví, aby jej na smrt vydali, avšak nenalezli.'),
(1571071,54,41,14,56,'Nebo ač mnozí křivé svědectví mluvili proti němu, ale svědectví jejich nebyla jednostejná.'),
(1571072,54,41,14,57,'Tedy někteří povstavše, křivé svědectví dávali proti němu, řkouce:'),
(1571073,54,41,14,58,'My jsme slyšeli tohoto, že řekl: Já zbořím chrám tento rukou udělaný, a ve třech dnech jiný ne rukou udělaný postavím.'),
(1571074,54,41,14,59,'Ale ani to jejich svědectví nebylo jednostejné.'),
(1571075,54,41,14,60,'Tedy povstav nejvyšší kněz uprostřed, otázal se Ježíše, řka: Neodpovídáš ničehož, což tito na tebe svědčí?'),
(1571076,54,41,14,61,'Ale on mlčel, a nic neodpověděl. Opět nejvyšší kněz otázal se ho a řekl jemu: Jsi-liž ty Kristus, Syn Boha Požehnaného?'),
(1571077,54,41,14,62,'A Ježíš řekl: Jáť jsem, a uzříte Syna člověka, an sedí na pravici moci Boží, a přichází s oblaky nebeskými.'),
(1571078,54,41,14,63,'Tedy nejvyšší kněz roztrh roucho své, řekl: I což ještě potřebujeme svědků?'),
(1571079,54,41,14,64,'Slyšeli jste rouhání. Co se vám zdá? Oni pak všickni odsoudili jej, že jest hoden smrti.'),
(1571080,54,41,14,65,'I počali někteří naň plvati, a tvář jeho zakrývati, a poličkovati, a říkati jemu: Prorokuj nám. A služebníci kyji jej bili.'),
(1571081,54,41,14,66,'A když byl Petr v síni dole, přišla jedna z děveček nejvyššího kněze.'),
(1571082,54,41,14,67,'A uzřevši Petra, an se ohřívá, a popatřivši naň, dí: I ty s Ježíšem Nazaretským byl jsi.'),
(1571083,54,41,14,68,'Ale on zapřel, řka: Aniž vím, ani rozumím, co ty pravíš. I vyšel ven před síň, a kohout zazpíval.'),
(1571084,54,41,14,69,'Tedy děvečka, uzřevši jej opět, počala praviti těm, kteříž tu okolo stáli, že tento z nich jest.'),
(1571085,54,41,14,70,'A on opět zapřel. A po malé chvíli opět ti, kteříž tu stáli, řekli Petrovi: Jistě z nich jsi, nebo i Galilejský jsi, i řeč tvá podobná jest.'),
(1571086,54,41,14,71,'On pak počal se proklínati a přisahati, pravě: Neznám člověka toho, o němž vy pravíte.'),
(1571087,54,41,14,72,'A hned po druhé kohout zazpíval. I rozpomenul se Petr na slovo, kteréž byl řekl jemu Ježíš: Že prve než kohout dvakrát zazpívá, třikrát mne zapříš. A vyšed, plakal.'),
(1571088,54,41,15,1,'A hned ráno uradivše se přední kněží s staršími a s zákoníky i se vším shromážděním, svázavše Ježíše, vedli jej a dali Pilátovi.'),
(1571089,54,41,15,2,'I otázal se ho Pilát: Ty-liž jsi král Židovský? A on odpověděv, řekl jemu: Ty pravíš.'),
(1571090,54,41,15,3,'I žalovali na něj přední kněží mnoho. On pak nic neodpovídal.'),
(1571091,54,41,15,4,'Tedy Pilát otázal se ho opět, řka: Nic neodpovídáš? Hle, jak mnoho proti tobě svědčí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571092,54,41,15,5,'Ale Ježíš předce nic neodpověděl, takže se podivil Pilát.'),
(1571093,54,41,15,6,'Ve svátek pak propouštíval jim jednoho z vězňů, za kteréhož by prosili.'),
(1571094,54,41,15,7,'I byl jeden, kterýž sloul Barabbáš, jenž s svárlivými byl v vězení, kteříž v svadě vraždu byli spáchali.'),
(1571095,54,41,15,8,'A zvolav zástup, počal prositi, aby učinil, jakož jim vždycky činíval.'),
(1571096,54,41,15,9,'Pilát pak odpověděl jim, řka: Chcete-li, propustím vám krále Židovského?'),
(1571097,54,41,15,10,'(Nebo věděl, že jsou jej z závisti vydali přední kněží.)'),
(1571098,54,41,15,11,'Ale přední kněží ponukli zástupu, aby jim raději propustil Barabbáše.'),
(1571099,54,41,15,12,'A Pilát odpověděv, řekl jim zase: Což pak chcete, ať učiním tomu, kteréhož králem Židovským nazýváte?'),
(1571100,54,41,15,13,'A oni opět zvolali: Ukřižuj ho.'),
(1571101,54,41,15,14,'A Pilát pravil jim: I což jest zlého učinil? Oni pak více volali: Ukřižuj ho.'),
(1571102,54,41,15,15,'Tedy Pilát, chtě lidu dosti učiniti, pustil jim Barabbáše, a dal jim Ježíše ubičovaného, aby byl ukřižován.'),
(1571103,54,41,15,16,'Žoldnéři pak uvedli jej vnitř do síně, do radného domu, a svolali všecku sběř.'),
(1571104,54,41,15,17,'I oblékli jej v šarlat, a korunu spletše z trní, vložili naň.'),
(1571105,54,41,15,18,'I počali ho pozdravovati, řkouce: Zdráv buď, králi Židovský.'),
(1571106,54,41,15,19,'A bili hlavu jeho třtinou, a plvali na něj, a sklánějíce kolena, klaněli se jemu.'),
(1571107,54,41,15,20,'A když se jemu naposmívali, svlékli s něho šarlat, a oblékli jej v roucho jeho vlastní. I vedli jej, aby ho ukřižovali.'),
(1571108,54,41,15,21,'I přinutili nějakého Šimona Cyrenenského, pomíjejícího je, (kterýž šel z pole, otce Alexandrova a Rufova,) aby vzal kříž jeho.'),
(1571109,54,41,15,22,'I vedli jej až na místo Golgota, to jest, (vyložil-li by,) popravné místo.'),
(1571110,54,41,15,23,'I dávali mu píti víno s mirrou, ale on nepřijal ho.'),
(1571111,54,41,15,24,'A ukřižovavše jej, rozdělili roucha jeho, mecíce o ně los, kdo by co vzíti měl.'),
(1571112,54,41,15,25,'A byla hodina třetí, když ho ukřižovali.'),
(1571113,54,41,15,26,'A byl nápis viny jeho napsán těmi slovy: Král Židovský.'),
(1571114,54,41,15,27,'Ukřižovali také s ním dva lotry: jednoho na pravici a druhého na levici jeho.'),
(1571115,54,41,15,28,'I naplněno jest písmo, řkoucí: A s nepravými počten jest.'),
(1571116,54,41,15,29,'A kteříž tudy chodili mimo něj, rouhali se jemu, potřásajíce hlavami svými, a říkajíce: Hahá, kterýž rušíš chrám Boží, a ve třech dnech jej zase vzděláváš,'),
(1571117,54,41,15,30,'Spomoz sobě samému, a sstup s kříže.'),
(1571118,54,41,15,31,'Též i přední kněží posmívajíce se, jeden k druhému s zákoníky pravili: Jinýmť jest pomáhal, sám sobě pomoci nemůže.'),
(1571119,54,41,15,32,'Kristus král Izraelský, nechažť nyní sstoupí s kříže, ať uzříme a uvěříme. A i ti, kteříž s ním ukřižováni byli, útržku mu činili.'),
(1571120,54,41,15,33,'A když byla hodina šestá, stala se tma po vší zemi až do hodiny deváté.'),
(1571121,54,41,15,34,'A v hodinu devátou zvolal Ježíš hlasem velikým, řka: Elói, Elói, lama zabachtani? jenž se vykládá: Bože můj, Bože můj, pročs mne opustil?'),
(1571122,54,41,15,35,'A někteří z okolo stojících, slyševše to, pravili: Hle, Eliáše volá.'),
(1571123,54,41,15,36,'A běžev jeden, naplnil houbu octem a vloživ na tresť, dával jemu píti, řka: Ponechte, uzříme, přijde-li Eliáš, aby jej složil.'),
(1571124,54,41,15,37,'Ježíš pak zvolav hlasem velikým, pustil duši.'),
(1571125,54,41,15,38,'A opona v chrámě roztrhla se na dvé, od vrchu až dolů.'),
(1571126,54,41,15,39,'Viděv pak to centurio, kterýž naproti stál, že tak volaje, vypustil duši, řekl: Jistě člověk tento Syn Boží byl.'),
(1571127,54,41,15,40,'Byly pak tu i ženy, zdaleka se dívajíce, mezi nimiž byla Maria Magdaléna, a Maria Jakuba menšího, a Jozesova mátě, a Salome.'),
(1571128,54,41,15,41,'Kteréž, když ještě byl v Galilei, chodily za ním a posluhovaly jemu, i jiné mnohé, kteréž byly s ním vstoupily do Jeruzaléma.'),
(1571129,54,41,15,42,'A když již byl večer, (že byl den připravování, to jest před sobotou,)'),
(1571130,54,41,15,43,'Přišed Jozef z Arimatie, počestná osoba úřadná, kterýž také očekával království Božího, směle všel ku Pilátovi a prosil za tělo Ježíšovo.'),
(1571131,54,41,15,44,'Pilát pak podivil se, již-li by umřel. A povolav centuriona, otázal se ho, dávno-li je umřel.'),
(1571132,54,41,15,45,'A zvěděv od centuriona, dal tělo Jozefovi.'),
(1571133,54,41,15,46,'A Jozef koupiv plátna, a složiv ho s kříže, obvinul v plátno, i položil do hrobu, kterýž byl vytesán z skály, a přivalil kámen ke dveřům hrobovým.'),
(1571134,54,41,15,47,'Ale Maria Magdaléna a Maria Jozesova dívaly se, kde by byl položen.'),
(1571135,54,41,16,1,'A když pominula sobota, Maria Magdaléna a Maria Jakubova a Salome nakoupily vonných věcí, aby přijdouce, pomazaly Ježíše.'),
(1571136,54,41,16,2,'A velmi ráno vyšedše první den po sobotě, přišly k hrobu, an již slunce vzešlo.'),
(1571137,54,41,16,3,'I pravily vespolek: Kdo nám odvalí kámen ode dveří hrobových?'),
(1571138,54,41,16,4,'(A vzhlédše, uzřely odvalený kámen.) Byl zajisté veliký velmi.'),
(1571139,54,41,16,5,'A všedše do hrobu, uzřely mládence, an sedí na pravici, oděného rouchem bílým. I ulekly se.'),
(1571140,54,41,16,6,'Kterýžto řekl jim: Nebojte se. Ježíše hledáte Nazaretského ukřižovaného. Vstalť jest, neníť ho tuto; aj, místo, kdež jej byli položili.'),
(1571141,54,41,16,7,'Ale jděte, povězte učedlníkům jeho i Petrovi, žeť vás předejde do Galilee. Tam jej uzříte, jakož jest pověděl vám.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571142,54,41,16,8,'A ony vyšedše rychle, utekly od hrobu; nebo přišel na ně strach a hrůza. A aniž komu co řekly, nebo se bály.'),
(1571143,54,41,16,9,'Vstav pak Ježíš z mrtvých ráno v neděli, ukázal se nejprv Mariji Magdaléně, z nížto byl vyvrhl sedm ďáblů.'),
(1571144,54,41,16,10,'Ona pak šedši, zvěstovala těm, kteříž s ním bývali, lkajícím a plačícím.'),
(1571145,54,41,16,11,'A oni slyšavše, že by živ byl a vidín od ní, nevěřili.'),
(1571146,54,41,16,12,'Potom pak dvěma z nich jdoucím ukázal se v jiné způsobě, když šli přes pole.'),
(1571147,54,41,16,13,'A ti šedše, pověděli jiným. Ani těm nevěřili.'),
(1571148,54,41,16,14,'Nejposléze sedícím spolu jedenácti ukázal se, a trestal nedověru jejich a tvrdost srdce, že těm, kteříž jej viděli vzkříšeného, nevěřili.'),
(1571149,54,41,16,15,'A řekl jim: Jdouce po všem světě, kažte evangelium všemu stvoření.'),
(1571150,54,41,16,16,'Kdož uvěří a pokřtí se, spasen bude; kdož pak neuvěří, budeť zatracen.'),
(1571151,54,41,16,17,'Znamení pak ti, kteříž uvěří, tato míti budou: Ve jménu mém ďábly budou vymítati, jazyky novými mluviti.'),
(1571152,54,41,16,18,'Hady bráti; a jestliže by co jedovatého pili, neuškodíť jim; na nemocné ruce vzkládati budou, a dobře se míti budou.'),
(1571153,54,41,16,19,'Když pak jim odmluvil Pán, vzhůru vzat jest do nebe, a sedí na pravici Boží.'),
(1571154,54,41,16,20,'A oni šedše, kázali všudy, a Pán jim pomáhal, a slov jejich potvrzoval činěním divů.'),
(1571155,54,42,1,1,'Poněvadž mnozí usilovali sepsati pořádně vypravování těch věcí, kteréž jsou u nás jisté,'),
(1571156,54,42,1,2,'Jakž jsou nám vydali ti, kteřížto od počátku sami viděli, a služebníci toho Slova byli,'),
(1571157,54,42,1,3,'Vidělo se i mně, kterýž jsem toho všeho pravé povědomosti došel, tobě z gruntu o tom pořádně vypsati, výborný Theofile,'),
(1571158,54,42,1,4,'Abys zvěděl jistotu těch věcí, jimž jsi vyučován.'),
(1571159,54,42,1,5,'Byl za dnů Herodesa krále Judského kněz nějaký, jménem Zachariáš, z třídy Abiášovy, a manželka jeho ze dcer Aronových, a jméno její Alžběta.'),
(1571160,54,42,1,6,'Byli pak oba spravedliví před obličejem Božím, chodíce ve všech přikázáních a spravedlnostech Páně bez úhony.'),
(1571161,54,42,1,7,'A neměli plodu, protože Alžběta byla neplodná, a oba se byli zstarali ve dnech svých.'),
(1571162,54,42,1,8,'I stalo se, když on úřad kněžský konal v pořádku třídy své před Bohem,'),
(1571163,54,42,1,9,'Že vedle obyčeje úřadu kněžského los naň přišel, aby položil zápal, vejda do chrámu Páně.'),
(1571164,54,42,1,10,'A všecko množství lidu bylo vně, modlíce se v hodinu zápalu.'),
(1571165,54,42,1,11,'Tedy ukázal se jemu anděl Páně, stoje na pravé straně oltáře zápalu.'),
(1571166,54,42,1,12,'A uzřev jej Zachariáš, zstrašil se, a bázeň připadla na něj.'),
(1571167,54,42,1,13,'I řekl jemu anděl: Neboj se, Zachariáši, neboť jest uslyšána modlitba tvá, a Alžběta manželka tvá porodí tobě syna, a nazůveš jméno jeho Jan.'),
(1571168,54,42,1,14,'Z čehož budeš míti radost a veselé, a mnozí z jeho narození budou se radovati.'),
(1571169,54,42,1,15,'Bude zajisté veliký před obličejem Páně, a vína i nápoje opojného nebudeť píti, a Duchem svatým bude naplněn hned od života matky své.'),
(1571170,54,42,1,16,'A mnohé z synů Izraelských obrátí ku Pánu Bohu jejich.'),
(1571171,54,42,1,17,'Neboť, on předejde před obličejem jeho v duchu a v moci Eliášově, aby obrátil srdce otců k synům, a nevěřící k opatrnosti spravedlivých, aby tak připravil Pánu lid hotový.'),
(1571172,54,42,1,18,'I řekl Zachariáš k andělu: Po čemž to poznám? Nebo já starý jsem, a manželka má zstarala se ve dnech svých.'),
(1571173,54,42,1,19,'Odpověděv anděl, řekl jemu: Jáť jsem Gabriel, kterýž stojím před obličejem Božím, a poslán jsem, abych mluvil s tebou, a tyto věci veselé tobě zvěstoval.'),
(1571174,54,42,1,20,'A aj, budeš němý, a nebudeš moci mluviti až do toho dne, v kterémž se tyto věci stanou, protože jsi neuvěřil řečem mým, kteréž se naplní časem svým.'),
(1571175,54,42,1,21,'Lid pak očekával Zachariáše, a divili se, že on tak prodléval v chrámě.'),
(1571176,54,42,1,22,'Vyšed pak, nemohl mluviti k nim. I srozuměli, že vidění viděl v chrámě. Nebo on návěští jim dával, a zůstal němý.'),
(1571177,54,42,1,23,'I stalo se, když se vyplnili dnové konání úřadu jeho, odšel do domu svého.'),
(1571178,54,42,1,24,'A po těch dnech počala Alžběta manželka jeho, a tajila se za pět měsíců, řkuci:'),
(1571179,54,42,1,25,'Že tak mi učinil Pán ve dnech, v nichžto vzezřel, aby odjal mé pohanění mezi lidmi.'),
(1571180,54,42,1,26,'V měsíci pak šestém poslán jest anděl Gabriel od Boha do města Galilejského, kterémuž jméno Nazarét,'),
(1571181,54,42,1,27,'Ku panně zasnoubené muži, kterémuž jméno bylo Jozef, z domu Davidova, a jméno panny Maria.'),
(1571182,54,42,1,28,'I všed k ní anděl, dí: Zdráva milosti došlá, Pán Bůh s tebou, požehnaná ty mezi ženami.'),
(1571183,54,42,1,29,'Ona pak uzřevši ho, zarmoutila se nad řečí jeho, a myslila, jaké by to bylo pozdravení.'),
(1571184,54,42,1,30,'I řekl jí anděl: Neboj se, Maria, nebo jsi nalezla milost u Boha.'),
(1571185,54,42,1,31,'A počneš v životě a porodíš syna, a nazůveš jméno jeho Ježíš.'),
(1571186,54,42,1,32,'Tenť bude veliký, a Syn Nejvyššího slouti bude, a dáť jemu Pán Bůh stolici Davida otce jeho.'),
(1571187,54,42,1,33,'A kralovati bude v domě Jákobově na věky, a království jeho nebude konce.'),
(1571188,54,42,1,34,'I řekla Maria k andělu: Kterak se to stane, poněvadž já muže nepoznávám?'),
(1571189,54,42,1,35,'A odpověděv anděl, řekl jí: Duch svatý sstoupí v tě, a moc Nejvyššího zastíní tobě; a protož, což se z tebe svatého narodí, slouti bude Syn Boží.'),
(1571190,54,42,1,36,'A aj, Alžběta, příbuzná tvá, i ona počala syna v starosti své, a tento jest jí šestý měsíc, kteráž sloula neplodná.'),
(1571191,54,42,1,37,'Neboť nebude nemožné u Boha všeliké slovo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571192,54,42,1,38,'I řekla Maria: Aj, služebnice Páně, staniž mi se podle slova tvého. I odšel od ní anděl.'),
(1571193,54,42,1,39,'Tedy povstavši Maria v těch dnech, odešla na hory s chvátáním do města Judova.'),
(1571194,54,42,1,40,'I vešla do domu Zachariášova, a pozdravila Alžběty.'),
(1571195,54,42,1,41,'I stalo se, jakž uslyšela pozdravení Marie Alžběta, zplésalo nemluvňátko v životě jejím, a naplněna jest Duchem svatým Alžběta.'),
(1571196,54,42,1,42,'I zvolala hlasem velikým a řekla: Požehnaná ty mezi ženami, a požehnaný plod života tvého.'),
(1571197,54,42,1,43,'A odkud mi to, aby přišla matka Pána mého ke mně?'),
(1571198,54,42,1,44,'Nebo aj, jakž se stal hlas pozdravení tvého v uších mých, zplésalo radostně nemluvňátko v životě mém.'),
(1571199,54,42,1,45,'A blahoslavená, kteráž uvěřila, neboť dokonány budou ty věci, kteréž jsou povědíny jí ode Pána.'),
(1571200,54,42,1,46,'Tedy řekla Maria: Velebí duše má Hospodina,'),
(1571201,54,42,1,47,'A veselí se duch můj v Bohu, Spasiteli mém,'),
(1571202,54,42,1,48,'Že jest vzezřel na ponížení služebnice své; neb aj, od této chvíle blahoslaviti mne budou všickni národové.'),
(1571203,54,42,1,49,'Neboť mi učinil veliké věci ten, jenž mocný jest, a svaté jméno jeho,'),
(1571204,54,42,1,50,'A jehož milosrdenství od pokolení až do pokolení bojícím se jeho.'),
(1571205,54,42,1,51,'Dokázal moci ramenem svým, rozptýlil pyšné myšlením srdce jejich.'),
(1571206,54,42,1,52,'Sházel mocné s stolic, a povýšil ponížených.'),
(1571207,54,42,1,53,'Lačné nakrmil dobrými věcmi, a bohaté pustil prázdné.'),
(1571208,54,42,1,54,'Přijal Izraele, služebníka svého, pamětliv jsa na milosrdenství své'),
(1571209,54,42,1,55,'(Jakož mluvil k otcům našim, k Abrahamovi a semeni jeho) na věky.'),
(1571210,54,42,1,56,'I zůstala Maria s ní asi za tři měsíce, a potom navrátila se do domu svého.'),
(1571211,54,42,1,57,'Alžbětě pak naplnil se čas, aby porodila; i porodila syna.'),
(1571212,54,42,1,58,'A uslyšeli sousedé a přátelé její, že Hospodin veliké učinil s ní milosrdenství své, i radovali se spolu s ní.'),
(1571213,54,42,1,59,'Stalo se pak v den osmý, přišli obřezovati dítěte, a nazývali jej jménem otce jeho Zachariášem.'),
(1571214,54,42,1,60,'Ale odpověděvši matka jeho, řekla: Nikoli, ale slouti bude Jan.'),
(1571215,54,42,1,61,'I řekli k ní: Však nižádného není v rodu tvém, kterýž by sloul jménem tím.'),
(1571216,54,42,1,62,'I dávali návěští otci jeho, jak by ho chtěl nazývati.'),
(1571217,54,42,1,63,'A on požádav deštičky, napsal řka: Jan jest jméno jeho. I divili se všickni.'),
(1571218,54,42,1,64,'A ihned otevřela se ústa jeho a jazyk jeho, i mluvil, velebě Boha.'),
(1571219,54,42,1,65,'Tedy přišla bázeň na všecky sousedy jejich, a po všech horách Judských rozhlásána jsou všecka ta slova.'),
(1571220,54,42,1,66,'A všickni, kteříž o tom slyšeli, skládali to v srdci svém, řkouce: I kteraké dítě toto bude? A ruka Páně byla s ním.'),
(1571221,54,42,1,67,'Zachariáš pak otec jeho naplněn jest Duchem svatým, a prorokoval řka:'),
(1571222,54,42,1,68,'Požehnaný Pán Bůh Izraelský, že jest navštívil, a učinil vykoupení lidu svému,'),
(1571223,54,42,1,69,'A vyzdvihl nám roh spasení v domu Davida, služebníka svého,'),
(1571224,54,42,1,70,'Jakož mluvil skrze ústa proroků svých svatých, kteříž byli od věků,'),
(1571225,54,42,1,71,'O vysvobození z nepřátel našich, a z ruky všech, kteříž nás nenáviděli,'),
(1571226,54,42,1,72,'Aby učinil milosrdenství s otci našimi, a rozpomenul se na smlouvu svou svatou,'),
(1571227,54,42,1,73,'Na přísahu, kterouž jest přisáhl Abrahamovi, otci našemu, že jistě nám to dá,'),
(1571228,54,42,1,74,'Abychom bez strachu, z ruky nepřátel našich jsouce vysvobozeni, sloužili jemu,'),
(1571229,54,42,1,75,'V svatosti a v spravedlnosti před obličejem jeho, po všecky dny života našeho.'),
(1571230,54,42,1,76,'Ty pak, dítě, prorokem Nejvyššího slouti budeš, nebo předejdeš před tváří Páně připravovati cesty jeho,'),
(1571231,54,42,1,77,'Aby bylo dáno umění spasitelné lidu jeho na odpuštění hříchů jejich,'),
(1571232,54,42,1,78,'Skrze srdečné milosrdenství Boha našeho, v němžto navštívil nás, vyšed z výsosti,'),
(1571233,54,42,1,79,'Aby se ukázal sedícím v temnostech a v stínu smrti, k spravení noh našich na cestu pokoje.'),
(1571234,54,42,1,80,'Dítě pak rostlo a posilovalo se v duchu, a bylo na poušti až do dne zjevení svého lidu Izraelskému.'),
(1571235,54,42,2,1,'I stalo se v těch dnech, vyšlo jest vyrčení od císaře Augusta, aby byl popsán všecken svět.'),
(1571236,54,42,2,2,'(To popsání nejprve stalo se, když vladařem Syrským byl Cyrenius.)'),
(1571237,54,42,2,3,'I šli všickni, aby zapsáni byli, jeden každý do svého města.'),
(1571238,54,42,2,4,'Vstoupil pak i Jozef od Galilee z města Nazarétu do Judstva, do města Davidova, kteréž slove Betlém, (protože byl z domu a z čeledi Davidovy,)'),
(1571239,54,42,2,5,'Aby zapsán byl s Marijí, zasnoubenou sobě manželkou, těhotnou.'),
(1571240,54,42,2,6,'I stalo se, když tam byli, naplnili se dnové Marie, aby porodila.'),
(1571241,54,42,2,7,'I porodila Syna svého prvorozeného, a plénkami ho obvinula, a položila jej v jeslech, neb neměli jinde místa v hospodě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571242,54,42,2,8,'A pastýři byli v krajině té, ponocujíce a stráž noční držíce nad svým stádem.'),
(1571243,54,42,2,9,'A aj, anděl Páně postavil se podle nich, a sláva Páně osvítila je. I báli se bázní velikou.'),
(1571244,54,42,2,10,'Tedy řekl jim anděl: Nebojtež se; nebo aj, zvěstuji vám radost velikou, kteráž bude všemu lidu.'),
(1571245,54,42,2,11,'Nebo narodil se vám dnes Spasitel, jenž jest Kristus Pán, v městě Davidově.'),
(1571246,54,42,2,12,'A toto vám bude za znamení: Naleznete nemluvňátko plénkami obvinuté, a ležící v jeslech.'),
(1571247,54,42,2,13,'A hned s andělem zjevilo se množství rytířstva nebeského, chválících Boha a řkoucích:'),
(1571248,54,42,2,14,'Sláva na výsostech Bohu, a na zemi pokoj, lidem dobrá vůle.'),
(1571249,54,42,2,15,'I stalo se, jakž odešli od nich andělé do nebe, že ti lidé, totiž pastýři, řekli vespolek: Pojďme až do Betléma a vizme tu věc, jenž se stala, o níž Pán oznámil nám.'),
(1571250,54,42,2,16,'I přišli, chvátajíce, a nalezli Mariji a Jozefa, a nemluvňátko ležící v jeslech.'),
(1571251,54,42,2,17,'A viděvše, rozhlašovali to, což jim povědíno bylo o tom dítěti.'),
(1571252,54,42,2,18,'I divili se všickni, kteříž slyšeli o tom, což bylo mluveno od pastýřů k nim.'),
(1571253,54,42,2,19,'Ale Maria zachovávala všecka slova tato, skládajici je v srdci svém.'),
(1571254,54,42,2,20,'I navrátili se pastýři, velebíce a chválíce Boha ze všeho, což slyšeli a viděli, tak jakž bylo povědíno jim.'),
(1571255,54,42,2,21,'A když se naplnilo dní osm, aby obřezáno bylo dítě, nazváno jest jméno jeho Ježíš, kterýmž bylo nazváno od anděla, prve než se v životě počalo.'),
(1571256,54,42,2,22,'A když se naplnili dnové očišťování Marie podle Zákona Mojžíšova, přinesli jej do Jeruzaléma, aby ho postavili přede Pánem,'),
(1571257,54,42,2,23,'(Jakož psáno jest v Zákoně Páně, že každý pacholík, otvíraje život, svatý Pánu slouti bude,)'),
(1571258,54,42,2,24,'A aby dali obět, jakož povědíno jest v Zákoně Páně, dvě hrdličky anebo dvé holoubátek.'),
(1571259,54,42,2,25,'A aj, člověk jeden byl v Jeruzalémě, jemuž jméno Simeon. A člověk ten byl spravedlivý a nábožný, očekávající potěšení Izraelského, a Duch svatý byl v něm.'),
(1571260,54,42,2,26,'A bylo jemu zjeveno od Ducha svatého, že neuzří smrti, až by prve uzřel Krista Páně.'),
(1571261,54,42,2,27,'Ten přišel, ponuknut jsa od Ducha Páně, do chrámu. A když uvodili dítě Ježíše rodičové, aby učinili podle obyčeje Zákona za něj,'),
(1571262,54,42,2,28,'Tedy on vzal jej na lokty své, i chválil Boha a řekl:'),
(1571263,54,42,2,29,'Nyní propouštíš služebníka svého, Pane, podle slova svého v pokoji.'),
(1571264,54,42,2,30,'Neboť jsou viděly oči mé spasení tvé,'),
(1571265,54,42,2,31,'Kteréž jsi připravil před obličejem všech lidí,'),
(1571266,54,42,2,32,'Světlo k zjevení národům a slávu lidu tvého Izraelského.'),
(1571267,54,42,2,33,'Otec pak a matka jeho divili se těm věcem, kteréž praveny byly o něm.'),
(1571268,54,42,2,34,'I požehnal jim Simeon, a řekl k Mariji, matce jeho: Aj, položen jest tento ku pádu a ku povstání mnohým v Izraeli, a na znamení, kterémužto bude odpíráno,'),
(1571269,54,42,2,35,'(A tvou vlastní duši pronikne meč,) aby zjevena byla z mnohých srdcí myšlení.'),
(1571270,54,42,2,36,'Byla také Anna prorokyně, dcera Fanuelova z pokolení Aser. Ta se byla zstarala ve dnech mnohých, a živa byla s mužem svým sedm let od panenství svého.'),
(1571271,54,42,2,37,'A ta vdova byla, mající let okolo osmdesáti a čtyř, kteráž nevycházela z chrámu, posty a modlitbami sloužeci Bohu dnem i nocí.'),
(1571272,54,42,2,38,'A ta v touž hodinu přišedši, chválila Pána, a mluvila o něm všechněm, kteříž čekali vykoupení v Jeruzalémě.'),
(1571273,54,42,2,39,'Oni pak, jakž vykonali všecko podle Zákona Páně, vrátili se do Galilee, do města svého Nazaréta.'),
(1571274,54,42,2,40,'Dítě pak rostlo a posilovalo se v duchu, plné moudrosti, a milost Boží byla v něm.'),
(1571275,54,42,2,41,'I chodívali rodičové jeho každého roku do Jeruzaléma na den slavný velikonoční.'),
(1571276,54,42,2,42,'A když byl ve dvanácti letech, a oni vstupovali do Jeruzaléma, podle obyčeje toho dne svátečního,'),
(1571277,54,42,2,43,'A když vykonali dni, a již se navracovali, zůstalo dítě Ježíš v Jeruzalémě, a nevěděli o tom Jozef a matka jeho.'),
(1571278,54,42,2,44,'Domnívajíce se pak o něm, že by byl v zástupu, ušli den cesty. I hledali ho mezi příbuznými a známými.'),
(1571279,54,42,2,45,'A nenalezše jeho, navrátili se do Jeruzaléma, hledajíce ho.'),
(1571280,54,42,2,46,'I stalo se po třech dnech, že nalezli jej v chrámě, an sedí mezi doktory, poslouchaje jich a otazuje se jich.'),
(1571281,54,42,2,47,'A děsili se všickni, kteříž jej slyšeli, nad rozumností a odpovědmi jeho.'),
(1571282,54,42,2,48,'A uzřevše ho, ulekli se. I řekla matka jeho k němu: Synu, proč jsi nám tak učinil? Aj, otec tvůj a já s bolestí hledali jsme tebe.'),
(1571283,54,42,2,49,'I řekl k nim: Co jest, že jste mne hledali? Zdaliž jste nevěděli, že v těch věcech, kteréž jsou Otce mého, musím já býti?'),
(1571284,54,42,2,50,'Ale oni nesrozuměli těm slovům, kteráž k nim mluvil.'),
(1571285,54,42,2,51,'I šel s nimi, a přišel do Nazarétu, a byl poddán jim. Matka pak jeho zachovávala všecka slova ta v srdci svém.'),
(1571286,54,42,2,52,'A Ježíš prospíval moudrostí, a věkem, a milostí, u Boha i u lidí.'),
(1571287,54,42,3,1,'Léta pak patnáctého císařství Tiberia císaře, když Pontský Pilát spravoval Judstvo, a Herodes byl čtvrtákem v Galilei, Filip pak bratr jeho byl čtvrtákem Iturejské a Trachonitidské krajiny, a Lyzaniáš čtvrtákem Abilinským,'),
(1571288,54,42,3,2,'Za nejvyššího kněze Annáše a Kaifáše, stalo se slovo Páně nad Janem synem Zachariášovým na poušti.'),
(1571289,54,42,3,3,'I chodil po vší krajině ležící při Jordánu a kázal křest pokání na odpuštění hříchů,'),
(1571290,54,42,3,4,'Jakož psáno jest v knihách proroctví Izaiáše proroka, řkoucího: Hlas volajícího na poušti: Připravujte cestu Páně, přímé čiňte stezky jeho.'),
(1571291,54,42,3,5,'Každé údolí bude vyplněno, a každá hora a pahrbek bude ponížen; i budou křivé věci spraveny a ostré cesty budou hladké.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571292,54,42,3,6,'A uzříť všeliké tělo spasení Boží.'),
(1571293,54,42,3,7,'Pravil pak k zástupům vycházejícím, aby se křtili od něho: Plemeno ještěrčí, kdo je vám ukázal, abyste utekli před budoucím hněvem?'),
(1571294,54,42,3,8,'Protož čiňte ovoce hodné pokání, a neříkejtež u sebe: Otce máme Abrahama. Neboť pravím vám, žeť jest mocen Bůh z kamení tohoto vzbuditi syny Abrahamovi.'),
(1571295,54,42,3,9,'A jižť jest i sekera k kořenu stromů přiložena. Protož každý strom, jenž nenese ovoce dobrého, vyťat a na oheň uvržen bude.'),
(1571296,54,42,3,10,'I tázali se ho zástupové, řkouce: Což tedy činiti budeme?'),
(1571297,54,42,3,11,'A on odpovídaje, pravil jim: Kdo má dvě sukně, dej jednu nemajícímu, a kdo má pokrmy, tolikéž učiň.'),
(1571298,54,42,3,12,'Přišli pak i celní křtíti se, i řekli jemu: Mistře, co budeme činiti?'),
(1571299,54,42,3,13,'A on řekl k nim: Nic více nevybírejte než to, což jest ustaveno.'),
(1571300,54,42,3,14,'I tázali se ho také i žoldnéři, řkouce: A my což činiti budeme? I řekl jim: Nižádného neutiskujte, ani podvodně čiňte, a dosti mějte na svých žoldích.'),
(1571301,54,42,3,15,'A když pak lid očekával, a myslili všickni v srdcích svých o Janovi, nebyl-li by snad on Kristus,'),
(1571302,54,42,3,16,'Odpověděl Jan všechněm, a řka: Jáť zajisté křtím vás vodou, ale jdeť silnější nežli já, kteréhožto nejsem hoden rozvázati řeménka u obuvi jeho. Tenť vás křtíti bude Duchem svatým a ohněm.'),
(1571303,54,42,3,17,'Jehožto věječka v ruce jeho, a vyčistíť humno své, a shromáždí pšenici do obilnice své, ale plevy páliti bude ohněm neuhasitelným.'),
(1571304,54,42,3,18,'A tak mnohé jiné věci, napomínaje, zvěstoval lidu.'),
(1571305,54,42,3,19,'Herodes pak čtvrták, když od něho byl trestán pro Herodiadu manželku Filipa bratra svého, i ze všech zlých věcí, kteréž činil Herodes,'),
(1571306,54,42,3,20,'Přidal i toto nade všecko, že jest vsadil Jana do žaláře.'),
(1571307,54,42,3,21,'I stalo se, když se křtil všecken lid, a když se pokřtil i Ježíš, a modlil se, že otevřelo se nebe,'),
(1571308,54,42,3,22,'A sstoupil Duch svatý v tělesné způsobě jako holubice na něj, a stal se hlas s nebe, řkoucí: Ty jsi Syn můj milý, v toběť mi se zalíbilo.'),
(1571309,54,42,3,23,'Ježíš pak počínal býti jako ve třidcíti letech, jakž domnín byl syn Jozefův, kterýž byl syn Heli,'),
(1571310,54,42,3,24,'Kterýž byl Matatův, kterýž byl Léví, kterýž byl Melchův, kterýž byl Jannův, kterýž byl Jozefův,'),
(1571311,54,42,3,25,'Kterýž byl Matatiášův, kterýž byl Amosův, kterýž byl Naum, kterýž byl Esli, kterýž byl Nagge,'),
(1571312,54,42,3,26,'Kterýž byl Mahatův, kterýž byl Matatiášův, kterýž byl Semei, kterýž byl Jozefův, kterýž byl Judův,'),
(1571313,54,42,3,27,'Kterýž byl Johannův, kterýž byl Resův, kterýž byl Zorobábelův, kterýž byl Salatielův, kterýž byl Neriův,'),
(1571314,54,42,3,28,'Kterýž byl Melchiův, kterýž byl Addiův, kterýž byl Kozamův, kterýž byl Elmódamův, kterýž byl Erův,'),
(1571315,54,42,3,29,'Kterýž byl Józův, kterýž byl Eliezerův, kterýž byl Jórimův, kterýž byl Matatův, kterýž byl Léví,'),
(1571316,54,42,3,30,'Kterýž byl Simeonův, kterýž byl Judův, kterýž byl Jozefův, kterýž byl Jónamův, kterýž byl Eliachimův,'),
(1571317,54,42,3,31,'Kterýž byl Meleův, kterýž byl Ménamův, kterýž byl Matatanův, kterýž byl Nátanův, kterýž byl Davidův,'),
(1571318,54,42,3,32,'Kterýž byl Jesse, kterýž byl Obédův, kterýž byl Bózův, kterýž byl Salmonův, kterýž byl Názonův,'),
(1571319,54,42,3,33,'Kterýž byl Aminadabův, kterýž byl Aramův, kterýž byl Ezromův, kterýž byl Fáresův, kterýž byl Judův, kterýž byl Jákobův,'),
(1571320,54,42,3,34,'Kterýž byl Izákův, kterýž byl Abrahamův, kterýž byl Táre, kterýž byl Náchorův,'),
(1571321,54,42,3,35,'Kterýž byl Sáruchův, kterýž byl Ragaův, kterýž byl Fálekův, kterýž byl Heberův, kterýž byl Sále,'),
(1571322,54,42,3,36,'Kterýž byl Kainanův, kterýž byl Arfaxadův, kterýž byl Semův, kterýž byl Noé, kterýž byl Lámechův,'),
(1571323,54,42,3,37,'Kterýž byl Matuzalémův, kterýž byl Enochův, kterýž byl Járedův, kterýž byl Malalehelův, kterýž byl Kainanův,'),
(1571324,54,42,3,38,'Kterýž byl Enosův, kterýž byl Setův, kterýž byl Adamův, kterýž byl Boží.'),
(1571325,54,42,4,1,'Ježíš pak, pln jsa Ducha svatého, vrátil se od Jordánu, a puzen jest v Duchu na poušť.'),
(1571326,54,42,4,2,'A za čtyřidceti dní pokoušín byl od ďábla, a nic nejedl v těch dnech. A když se skonali dnové ti, potom zlačněl.'),
(1571327,54,42,4,3,'I řekl jemu ďábel: Jestliže jsi Syn Boží, rci kamenu tomuto, ať jest chléb.'),
(1571328,54,42,4,4,'I odpověděl jemu Ježíš: Psánoť jest: Že ne samým chlebem živ bude člověk, ale každým slovem Božím.'),
(1571329,54,42,4,5,'I vedl jej ďábel na horu vysokou, a ukázal mu všecka království okršlku země pojednou.'),
(1571330,54,42,4,6,'A řekl jemu ďábel: Toběť dám tuto všecku moc i slávu těchto království, nebo mně dána jest, a komuž bych koli chtěl, dám ji.'),
(1571331,54,42,4,7,'Protož ty pokloníš-li se přede mnou, budeť všecko tvé.'),
(1571332,54,42,4,8,'I odpověděv Ježíš, řekl jemu: Jdi pryč ode mne, satanáši; neboť psáno jest: Pánu Bohu svému budeš se klaněti a jemu samému sloužiti.'),
(1571333,54,42,4,9,'Tedy vedl jej do Jeruzaléma, a postavil ho na vrchu chrámu, a řekl mu: Jsi-li Syn Boží, pusť se odtud dolů.'),
(1571334,54,42,4,10,'Nebo psáno jest: Že andělům svým přikáže o tobě, aby tě ostříhali,'),
(1571335,54,42,4,11,'A že tě na ruce uchopí, abys neurazil o kámen nohy své.'),
(1571336,54,42,4,12,'A odpovídaje, dí mu Ježíš: Povědínoť jest: Nebudeš pokoušeti Pána Boha svého.'),
(1571337,54,42,4,13,'A dokonav všecka pokušení ďábel, odšel od něho až do času.'),
(1571338,54,42,4,14,'I navrátil se Ježíš v moci Ducha do Galilee, a vyšla pověst o něm po vší té okolní krajině.'),
(1571339,54,42,4,15,'A on učil v školách jejich, a slaven byl ode všech.'),
(1571340,54,42,4,16,'I přišel do Nazaréta, kdež byl vychován, a všel podle obyčeje svého v den sobotní do školy. I vstal, aby četl.'),
(1571341,54,42,4,17,'I dána jemu kniha Izaiáše proroka. A otevřev knihu, nalezl místo, kdež bylo napsáno:');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571342,54,42,4,18,'Duch Páně nade mnou, protože pomazal mne, kázati evangelium chudým poslal mne, a uzdravovati zkroušené srdcem, zvěstovati jatým propuštění a slepým vidění, a propustiti soužené v svobodu,'),
(1571343,54,42,4,19,'A zvěstovati léto Páně vzácné.'),
(1571344,54,42,4,20,'A zavřev knihu a vrátiv služebníku, posadil se. A všech v škole oči byly obráceny naň.'),
(1571345,54,42,4,21,'I počal mluviti k nim: Že dnes naplnilo se písmo toto v uších vašich.'),
(1571346,54,42,4,22,'A všickni jemu posvědčovali, a divili se libým slovům, pocházejícím z úst jeho, a pravili: Zdaliž tento není syn Jozefův?'),
(1571347,54,42,4,23,'I dí k nim: Zajisté díte mi toto podobenství: Lékaři, uzdrav se sám. Které věci slyšeli jsme, žes činil v Kafarnaum, učiň také i zde v své vlasti.'),
(1571348,54,42,4,24,'I řekl jim: Amen pravím vám, žeť žádný prorok není vzácen v vlasti své.'),
(1571349,54,42,4,25,'Ale v pravdě pravím vám, že mnoho vdov bylo za dnů Eliáše v lidu Izraelském, kdyžto zavříno bylo nebe za tři léta a za šest měsíců, takže byl hlad veliký po vší zemi,'),
(1571350,54,42,4,26,'Však Eliáš k nižádné z nich není poslán, než toliko do Sarepty Sidonské k ženě vdově.'),
(1571351,54,42,4,27,'A mnoho malomocných bylo v lidu Izraelském za Elizea proroka, a žádný z nich není očištěn, než Náman Syrský.'),
(1571352,54,42,4,28,'I naplněni jsou všickni v škole hněvem, slyšíce to.'),
(1571353,54,42,4,29,'A povstavše, vyvedli jej ven z města, a vedli ho až na vrch hory, na nížto město jejich bylo vzděláno, aby jej dolů sstrčili.'),
(1571354,54,42,4,30,'Ale on bera se prostředkem jich, ušel.'),
(1571355,54,42,4,31,'I sstoupil do Kafarnaum, města Galilejského, a tu učil je ve dny sobotní.'),
(1571356,54,42,4,32,'I divili se velmi učení jeho, nebo mocná byla řeč jeho.'),
(1571357,54,42,4,33,'Byl pak tu v škole člověk jeden, mající ducha ďábelství nečistého. I zvolal hlasem velikým,'),
(1571358,54,42,4,34,'Řka: Ach, což jest tobě do nás, Ježíši Nazaretský? Přišel jsi zatratiti nás? Znám tě, kdo jsi, že jsi ten svatý Boží.'),
(1571359,54,42,4,35,'I přimluvil jemu Ježíš, řka: Umlkniž a vyjdi od něho. A povrha jej ďábel mezi ně, vyšel od něho, a nic mu neuškodil.'),
(1571360,54,42,4,36,'I přišel strach na všecky, a rozmlouvali vespolek, řkouce: Jaké jest toto slovo, že v moci a síle přikazuje nečistým duchům, a vycházejí?'),
(1571361,54,42,4,37,'I rozcházela se o něm pověst po všem okolí té krajiny.'),
(1571362,54,42,4,38,'Vstav pak Ježíš ze školy, všel do domu Šimonova. Svegruše pak Šimonova trápena byla těžkou zimnicí. I prosili ho za ni.'),
(1571363,54,42,4,39,'Tedy stoje nad ní, přimluvil zimnici, i přestala jí. A ona hned vstavši, posluhovala jim.'),
(1571364,54,42,4,40,'Při západu pak slunce všickni, kteříž měli nemocné rozličnými neduhy, vodili je k němu, a on na jednoho každého z nich ruce vzkládav, uzdravoval je.'),
(1571365,54,42,4,41,'Od mnohých také ďábelství vycházela, křičící a říkající: Ty jsi Kristus, Syn Boží. Ale on přimlouvaje, nedopouštěl jim mluviti; nebo věděli, že jest on Kristus.'),
(1571366,54,42,4,42,'A jakž byl den, vyšed, bral se na pusté místo. I hledali ho zástupové, a přišli až k němu, a zdržovali ho, aby neodcházel od nich.'),
(1571367,54,42,4,43,'On pak řekl jim: I jinýmť městům musím zvěstovati království Boží; nebo na to poslán jsem.'),
(1571368,54,42,4,44,'I kázal v školách Galilejských.'),
(1571369,54,42,5,1,'Stalo se pak, když se zástup na něj valil, aby slyšeli slovo Boží, že on stál podle jezera Genezaretského.'),
(1571370,54,42,5,2,'I uzřel dvě lodí, any stojí u jezera, rybáři pak sstoupivše z nich, vypírali síti.'),
(1571371,54,42,5,3,'I vstoupiv na jednu z těch lodí, kteráž byla Šimonova, prosil ho, aby od země odvezl maličko. A posadiv se, učil z lodí zástupy.'),
(1571372,54,42,5,4,'A když přestal mluviti, dí k Šimonovi: Vez na hlubinu, a rozestřete síti své k lovení ryb.'),
(1571373,54,42,5,5,'I odpověděv Šimon, řekl jemu: Mistře, přes celou noc pracovavše, nic jsme nepopadli, ale k slovu tvému rozestru sít.'),
(1571374,54,42,5,6,'A když to učinili, zahrnuli množství veliké ryb, takže se trhala sít jejich.'),
(1571375,54,42,5,7,'I ponukli tovaryšů, kteříž byli na druhé lodí, aby přišli a pomohli jim. I přišli a naplnili obě lodí, takže se téměř pohřižovaly.'),
(1571376,54,42,5,8,'To uzřev Šimon Petr, padl k nohám Ježíšovým, řka: Odejdi ode mne, Pane, neboť jsem člověk hříšný.'),
(1571377,54,42,5,9,'Hrůza zajisté byla jej obklíčila, i všecky, kteříž s ním byli, nad tím lovením ryb, kteréž byli popadli,'),
(1571378,54,42,5,10,'A též Jakuba a Jana, syny Zebedeovy, kteříž byli tovaryši Šimonovi. I dí Šimonovi Ježíš: Nebojž se. Již od tohoto času lidi živé budeš loviti.'),
(1571379,54,42,5,11,'A přivezše k břehu lodí, a všecko opustivše, šli za ním.'),
(1571380,54,42,5,12,'I stalo se, když byl v jednom městě, a aj, byl tam muž plný malomocenství. A uzřev Ježíše, padl na tvář, a prosil ho, řka: Pane, kdybys chtěl, můžeš mne očistiti.'),
(1571381,54,42,5,13,'I vztáh Ježíš ruku, dotekl se ho, řka: Chci, buď čist. A hned odešlo od něho malomocenství.'),
(1571382,54,42,5,14,'I přikázal jemu, aby žádnému nepravil, ale řekl mu: Odejda, ukaž se knězi, a obětuj za očištění své, jakož přikázal Mojžíš, na svědectví jim.'),
(1571383,54,42,5,15,'Tedy rozhlašovala se více řeč o něm, a scházeli se zástupové mnozí, aby jej slyšeli, a uzdravováni byli od něho v svých nemocech.'),
(1571384,54,42,5,16,'On pak odcházel na pouště, a modlil se.'),
(1571385,54,42,5,17,'I stalo se v jeden den, že on seděl uče, a seděli také tu i farizeové a Zákona učitelé, kteříž se byli sešli z každého městečka Galilejského a Judského i z Jeruzaléma, a moc Páně přítomná byla k uzdravování jich.'),
(1571386,54,42,5,18,'A aj, muži nesli na loži člověka, kterýž byl šlakem poražený, i hledali vnésti ho a položiti před něj.'),
(1571387,54,42,5,19,'A nenalezše, kterou by jej stranou vnesli pro zástup, vstoupili na dům, a skrze podlahu spustili jej s ložem uprostřed před Ježíše.'),
(1571388,54,42,5,20,'Kterýžto viděv víru jejich, řekl mu: Člověče, odpuštěniť jsou tobě hříchové tvoji.'),
(1571389,54,42,5,21,'Tedy počali přemyšlovati zákoníci a farizeové, řkouce: Kdo jest tento, jenž mluví rouhání? Kdo může odpustiti hříchy, jediné sám Bůh?'),
(1571390,54,42,5,22,'Poznav pak Ježíš myšlení jejich, odpovídaje, řekl k nim: Co tak utrhavě přemyšlujete v srdcích vašich?'),
(1571391,54,42,5,23,'Co jest snáze říci: Odpouštějí se tobě hříchové tvoji, čili říci: Vstaň a choď?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571392,54,42,5,24,'Ale abyste věděli, že Syn člověka má moc na zemi odpouštěti hříchy, (řekl dnou zlámanému:) Toběť pravím: Vstaň, a vezma lože své, jdi do domu svého.'),
(1571393,54,42,5,25,'A on hned vstav před nimi, vzal lože, na němž ležel, i odšel do domu svého, velebě Boha.'),
(1571394,54,42,5,26,'I užasli se všickni, i velebili Boha, a naplněni jsou bázní, řkouce: Že jsme viděli dnes divné věci.'),
(1571395,54,42,5,27,'A potom vyšel Ježíš a uzřel celného, jménem Léví, sedícího na cle. I řekl jemu: Pojď za mnou.'),
(1571396,54,42,5,28,'A on opustiv všecko, vstav, šel za ním.'),
(1571397,54,42,5,29,'I učinil jemu hody veliké Léví v domu svém, a byl tu zástup veliký publikánů i jiných, kteříž s ním stolili.'),
(1571398,54,42,5,30,'Tedy reptali zákoníci a farizeové, řkouce učedlníkům jeho: Proč s publikány a hříšníky jíte a pijete?'),
(1571399,54,42,5,31,'I odpověděv Ježíš, řekl k nim: Nepotřebujíť zdraví lékaře, ale nemocní.'),
(1571400,54,42,5,32,'Nepřišelť jsem volati spravedlivých, ale hříšných ku pokání.'),
(1571401,54,42,5,33,'A oni řekli jemu: Proč učedlníci Janovi postí se často a modlí se, též podobně i farizejští, tvoji pak jedí a pijí?'),
(1571402,54,42,5,34,'On pak řekl k nim: Zdali můžete synům ženicha, dokudž s nimi jest ženich, kázati se postiti?'),
(1571403,54,42,5,35,'Ale přijdouť dnové, a když odjat bude od nich ženich, tehdážť se budou postiti v těch dnech.'),
(1571404,54,42,5,36,'Pravil pak i podobenství k nim: Že žádný záplaty roucha nového nepřišívá k rouchu vetchému; sic jinak i nové roztrhuje, a vetchému nepřísluší záplata z nového.'),
(1571405,54,42,5,37,'A žádný nevlévá vína nového do nádob starých; sic jinak víno nové rozpučí nádoby, a samo vyteče, a nádoby se pokazí.'),
(1571406,54,42,5,38,'Ale víno nové v nádoby nové má lito býti, a obé bude zachováno.'),
(1571407,54,42,5,39,'A aniž kdo, když pije staré, hned chce nového, ale díť: Staré lepší jest.'),
(1571408,54,42,6,1,'I stalo se v druhou sobotu, že šel Ježíš skrze obilí. I trhali učedlníci jeho klasy, a rukama vymínajíce, jedli.'),
(1571409,54,42,6,2,'Tehdy někteří z farizeů řekli jim: Proč to činíte, čehož nesluší činiti v svátky?'),
(1571410,54,42,6,3,'I odpověděv Ježíš, řekl jim: Což jste ani toho nečtli, co jest učinil David, když lačněl, on i ti, kteříž s ním byli?'),
(1571411,54,42,6,4,'Kterak všel do domu Božího, a chleby posvátné vzal a jedl, a dal i těm, kteříž s ním byli, jichžto nenáleží jísti než toliko samým kněžím?'),
(1571412,54,42,6,5,'I řekl jim: Že jest Syn člověka pánem také i dne svátečního.'),
(1571413,54,42,6,6,'Stalo se pak i v jiný den sváteční, že všel do školy Ježíš, a učil. A byl tu člověk, jehož pravá ruka byla uschlá.'),
(1571414,54,42,6,7,'I šetřili ho zákoníci a farizeové, bude-li v sobotu uzdravovati, aby nalezli, čím by jej obžalovali.'),
(1571415,54,42,6,8,'Ale on znal přemyšlování jich. I dí člověku, kterýž měl ruku uschlou: Vstaň, a stůj v prostředku. A on vstav, i stál.'),
(1571416,54,42,6,9,'Tedy řekl k nim Ježíš: Otíži se vás na jednu věc: Sluší-li v sobotu dobře činiti? duši zachovati, čili zatratiti?'),
(1571417,54,42,6,10,'A pohleděv na ně na všecky vůkol, dí člověku: Vztáhni ruku svou. A on učinil tak. I navrácena jest k zdraví ruka jeho a byla jako druhá.'),
(1571418,54,42,6,11,'Oni pak naplněni jsou hněvivou nemoudrostí, a rozmlouvali mezi sebou, co by učiniti měli Ježíšovi.'),
(1571419,54,42,6,12,'I stalo se v těch dnech, vyšel Ježíš na horu k modlení. I byl tam přes noc na modlitbě Boží.'),
(1571420,54,42,6,13,'A když byl den, povolal učedlníků svých, a vyvolil z nich dvanácte, kteréž i apoštoly nazval.'),
(1571421,54,42,6,14,'(Šimona, kterémuž také dal jméno Petr, a Ondřeje bratra jeho, Jakuba a Jana, Filipa a Bartoloměje,'),
(1571422,54,42,6,15,'Matouše a Tomáše, Jakuba syna Alfeova, a Šimona, kterýž slove Zelótes,'),
(1571423,54,42,6,16,'Judu bratra Jakubova, a Jidáše Iškariotského, kterýž pak byl zrádce.)'),
(1571424,54,42,6,17,'I sstoupiv s nimi s hory, stál na místě polním, a zástup učedlníků jeho, a množství veliké lidu ze všeho Judstva i z Jeruzaléma, i z Týru i z Sidonu, jenž při moři jsou, kteříž byli přišli, aby jej slyšeli a uzdraveni byli od neduhů svých,'),
(1571425,54,42,6,18,'I kteříž trápeni byli od duchů nečistých. A byli uzdravováni.'),
(1571426,54,42,6,19,'A všecken zástup hledal se ho dotknouti; nebo moc z něho vycházela, a uzdravovala všecky.'),
(1571427,54,42,6,20,'A on pozdvih očí svých na učedlníky, pravil: Blahoslavení chudí, nebo vaše jest království Boží.'),
(1571428,54,42,6,21,'Blahoslavení, kteříž nyní lačníte, nebo nasyceni budete. Blahoslavení, kteříž nyní plačete, nebo smáti se budete.'),
(1571429,54,42,6,22,'Blahoslavení budete, když vás nenáviděti budou lidé, a když vás vyobcují, a haněti budou, a vyvrhou jméno vaše jakožto zlé, pro Syna člověka.'),
(1571430,54,42,6,23,'Radujte se v ten den a veselte se, nebo aj, odplata vaše mnohá jest v nebesích. Takť jsou zajisté činívali prorokům otcové jejich.'),
(1571431,54,42,6,24,'Ale běda vám bohatým, nebo vy již máte potěšení své.'),
(1571432,54,42,6,25,'Běda vám, kteříž jste nasyceni, nebo lačněti budete. Běda vám, kteříž se nyní smějete, nebo kvíliti a plakati budete.'),
(1571433,54,42,6,26,'Běda vám, když by dobře o vás mluvili všickni lidé; nebo tak jsou činívali falešným prorokům otcové jejich.'),
(1571434,54,42,6,27,'Ale vámť pravím, kteříž slyšíte: Milujte nepřátely vaše, dobře čiňte těm, kteříž vás nenávidí,'),
(1571435,54,42,6,28,'Dobrořečte těm, kteříž vás proklínají, a modlte se za ty, kteříž vám bezpráví činí.'),
(1571436,54,42,6,29,'A udeřil-li by tebe kdo v líce jedno, nasaď mu i druhého, a tomu, kterýž tobě odjímá plášť, také i sukně nebraň.'),
(1571437,54,42,6,30,'Každému pak prosícímu tebe dej, a od toho, jenž béře tvé věci, zase nežádej.'),
(1571438,54,42,6,31,'A jakž chcete, aby vám lidé činili, i vy jim též podobně čiňte.'),
(1571439,54,42,6,32,'Nebo jestliže milujete ty, kteříž vás milují, jakou míti budete milost? Nebo i hříšníci milují ty, od nichž milováni bývají.'),
(1571440,54,42,6,33,'A budete-li dobře činiti těm, kteříž vám dobře činí, jakou máte milost? Však i hříšníci totéž činí.'),
(1571441,54,42,6,34,'A budete-li půjčovati těm, od kterýchž se nadějete zase vzíti, jakou máte milost? Však i hříšníci hříšníkům půjčují, aby tolikéž zase vzali.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571442,54,42,6,35,'Protož milujte nepřátely vaše, a dobře čiňte, a půjčujte, nic se odtud nenadějíce, a budeť odplata vaše mnohá, a budete synové Nejvyššího. Nebo on dobrotivý jest i k nevděčným a zlým.'),
(1571443,54,42,6,36,'Protož buďte milosrdní, jako i Otec váš milosrdný jest.'),
(1571444,54,42,6,37,'Nesuďte, a nebudete souzeni. Nepotupujte, a nebudete potupeni. Odpouštějte, a budeť vám odpuštěno.'),
(1571445,54,42,6,38,'Dávejte, a budeť vám dáno. Míru dobrou, natlačenou, a natřesenou, a osutou dadíť v lůno vaše; touž zajisté měrou, kterouž měříte, bude vám odměřeno.'),
(1571446,54,42,6,39,'Pověděl jim také i podobenství: Zdali může slepý slepého vésti? Zdaž oba do jámy neupadnou?'),
(1571447,54,42,6,40,'Neníť učedlník nad mistra svého, ale dokonalý bude každý, bude-li jako mistr jeho.'),
(1571448,54,42,6,41,'Což pak vidíš mrvu v oku bratra svého, a břevna, kteréž jest v tvém vlastním oku, neznamenáš?'),
(1571449,54,42,6,42,'Aneb kterak můžeš říci bratru svému: Bratře, nechať vyvrhu mrvu z oka tvého, sám v oku svém břevna nevida? Pokrytče, vyvrz prve břevno z oka svého, a tehdy prohlédneš, abys vyňal mrvu, kteráž jest v oku bratra tvého.'),
(1571450,54,42,6,43,'Neboť není ten strom dobrý, kterýž nese ovoce zlé, aniž jest strom zlý, kterýž nese ovoce dobré.'),
(1571451,54,42,6,44,'Každý zajisté strom po svém vlastním ovoci bývá poznán; nebo nesbírají s trní fíků, ani s hloží sbírají hroznů.'),
(1571452,54,42,6,45,'Dobrý člověk z dobrého pokladu srdce svého vynáší dobré, a zlý člověk ze zlého pokladu srdce svého vynáší zlé. Nebo z hojnosti srdce mluví ústa jeho.'),
(1571453,54,42,6,46,'Co pak mi říkáte: Pane, Pane, a nečiníte, což pravím?'),
(1571454,54,42,6,47,'Každý kdož přichází ke mně, a slyší slovo mé, a zachovává je, ukáži vám, komu by podoben byl.'),
(1571455,54,42,6,48,'Podoben jest člověku stavějícímu dům, kterýž kopal hluboko, a založil grunty v skále. A když se stala povodeň, obořila se řeka na dům ten, ale nemohla jím pohnouti, nebo byl založen na skále.'),
(1571456,54,42,6,49,'Ale kdož slyší a nečiní, podoben jest člověku, kterýž staví dům svůj na zemi bez gruntu. Na kterýžto obořila se řeka, a on hned padl, i stal se pád domu toho veliký.'),
(1571457,54,42,7,1,'A když vykonal všecka slova svá při přítomnosti lidu, všel do Kafarnaum.'),
(1571458,54,42,7,2,'Setníka pak jednoho služebník nemocen jsa, k smrti se přibližoval, kteréhož on sobě mnoho vážil.'),
(1571459,54,42,7,3,'I uslyšav o Ježíšovi, poslal k němu starší z Židů, prose ho, aby přišel a uzdravil služebníka jeho.'),
(1571460,54,42,7,4,'A oni přišedše k Ježíšovi, prosili ho snažně, řkouce: Hoden jest, abys jemu to učinil.'),
(1571461,54,42,7,5,'Nebo miluje národ náš, a školu on nám vystavěl.'),
(1571462,54,42,7,6,'Tedy Ježíš šel s nimi. A když již nedaleko byl od domu, poslal k němu setník přátely, řka jemu: Pane, nepřidávej sobě práce. (Nejsem zajisté hoden, abys všel pod střechu mou.'),
(1571463,54,42,7,7,'A protožť jsem i sebe samého za nehodného položil, abych přišel k tobě.) Ale rci slovem, a budeť uzdraven služebník můj.'),
(1571464,54,42,7,8,'Nebo i já jsem člověk pod mocí postavený, maje pod sebou žoldnéře, a dím tomuto: Jdi, a jde, a jinému: Přijď, a přijde, a služebníku svému: Učiň toto, a učiní.'),
(1571465,54,42,7,9,'Tedy uslyšav to Ježíš, podivil se jemu, a obrátiv se k zástupu, kterýž za ním šel, řekl: Pravím vám, že ani v Izraeli nenalezl jsem tak veliké víry.'),
(1571466,54,42,7,10,'Vrátivše se pak do domu ti, kteříž posláni byli, nalezli služebníka, kterýž nemocen byl, zdravého.'),
(1571467,54,42,7,11,'I stalo se potom, šel Ježíš do města, kteréž slove Naim, a šli s ním učedlníci jeho mnozí a zástup veliký.'),
(1571468,54,42,7,12,'A když se přiblížil k bráně města, aj, mrtvý byl nesen ven, syn jediný matky své, a ta vdova byla, a zástup města mnohý s ní.'),
(1571469,54,42,7,13,'Kteroužto uzřev Pán, milosrdenstvím hnut jsa nad ní, řekl jí: Neplačiž.'),
(1571470,54,42,7,14,'A přistoupiv, dotekl se már. (Ti pak, kteříž nesli, zastavili se.) I řekl: Mládenče, toběť pravím, vstaň.'),
(1571471,54,42,7,15,'I pozdvih se mrtvý, sedl, a počal mluviti. I dal jej mateři jeho.'),
(1571472,54,42,7,16,'Tedy podjala všecky bázeň, i velebili Boha, řkouce: Že prorok veliký povstal mezi námi, a že Bůh navštívil lid svůj.'),
(1571473,54,42,7,17,'I vyšla řeč ta o něm po všem Judstvu i po vší okolní krajině.'),
(1571474,54,42,7,18,'I zvěstovali Janovi učedlníci jeho o všech těchto věcech. A zavolav kterýchs dvou z učedlníků svých Jan,'),
(1571475,54,42,7,19,'Poslal k Ježíšovi, řka: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?'),
(1571476,54,42,7,20,'Přišedše pak k němu muži ti, řekli: Jan Křtitel poslal nás k tobě, řka: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?'),
(1571477,54,42,7,21,'A v touž hodinu mnohé uzdravil od neduhů, od nemocí a duchů zlých, a slepým mnohým zrak dal.'),
(1571478,54,42,7,22,'Odpověděv pak Ježíš, řekl jim: Jdouce, povězte Janovi, co jste viděli a slyšeli, že slepí vidí, kulhaví chodí, malomocní očištění přijímají, hluší slyší, mrtví z mrtvých vstávají, chudým se zvěstuje evangelium.'),
(1571479,54,42,7,23,'A blahoslavený jest, kdož by se na mně nezhoršil.'),
(1571480,54,42,7,24,'A když odešli poslové Janovi, počal praviti k zástupům o Janovi: Co jste vyšli na poušť spatřovati? Třtinu-li, kteráž se větrem klátí?'),
(1571481,54,42,7,25,'Anebo nač jste hleděti vyšli? Na člověka-li měkkým rouchem oděného? Aj, kteříž v rouše slavném a v rozkoši jsou, v domích královských jsou.'),
(1571482,54,42,7,26,'Aneb co jste vyšli viděti? Proroka-li? Ovšem pravím vám, i více nežli proroka.'),
(1571483,54,42,7,27,'Tentoť jest, o kterémž jest psáno: Aj, já posílám anděla svého před tváří tvou, jenž připraví cestu tvou před tebou.'),
(1571484,54,42,7,28,'Nebo pravím vám, většího proroka mezi syny ženskými nad Jana Křtitele není žádného, ale kdož jest menší v království Božím, většíť jest nežli on.'),
(1571485,54,42,7,29,'Tedy všecken lid slyše to i publikáni, velebili Boha, byvše pokřtěni křtem Janovým.'),
(1571486,54,42,7,30,'Ale farizeové a zákoníci pohrdli radou Boží sami proti sobě, nebyvše pokřtěni od něho.'),
(1571487,54,42,7,31,'I řekl Pán: Komu tedy přirovnám lidi pokolení tohoto a čemu podobni jsou?'),
(1571488,54,42,7,32,'Podobni jsou dětem, jenž na rynku sedí a jedni na druhé volají, říkajíce: Pískali jsme vám, a neskákali jste; žalostně jsme naříkali vám, a neplakali jste.'),
(1571489,54,42,7,33,'Nebo přišel Jan Křtitel, nejeda chleba, ani pije vína, a pravíte: Ďábelství má.'),
(1571490,54,42,7,34,'Přišel Syn člověka, jeda a pije, a pravíte: Aj, člověk žráč a pijan vína, přítel publikánů a hříšníků.'),
(1571491,54,42,7,35,'Ale ospravedlněna jest moudrost ode všech synů svých.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571492,54,42,7,36,'Prosil ho pak jeden z farizeů, aby jedl s ním. Pročež všed do domu toho farizea, posadil se za stůl.'),
(1571493,54,42,7,37,'A aj, žena jedna v městě, kteráž byla hříšnice, zvěděvši, že by seděl za stolem v domě farizea, přinesla nádobu alabastrovou masti.'),
(1571494,54,42,7,38,'A stojeci zzadu u noh jeho, s pláčem počala slzami smáčeti nohy jeho, a vlasy hlavy své vytírala, a líbala nohy jeho, a mastí mazala.'),
(1571495,54,42,7,39,'Uzřev pak to farizeus, kterýž ho byl pozval, řekl sám v sobě: Byť tento byl prorok, vědělť by, která a jaká jest to žena, kteráž se ho dotýká; nebo hříšnice jest.'),
(1571496,54,42,7,40,'I odpověděv Ježíš, dí k němu: Šimone, mámť něco povědíti. A on řekl: Mistře, pověz.'),
(1571497,54,42,7,41,'I řekl Ježíš: Dva dlužníky měl jeden věřitel. Jeden dlužen byl pět set peněz, a druhý padesát.'),
(1571498,54,42,7,42,'A když neměli, odkud by zaplatili, odpustil oběma. Pověziž tedy, který z nich více jej bude milovati?'),
(1571499,54,42,7,43,'I odpověděv Šimon, řekl: Mám za to, že ten, kterémuž více odpustil. A on řekl jemu: Právě jsi rozsoudil.'),
(1571500,54,42,7,44,'A obrátiv se k ženě, řekl Šimonovi: Vidíš tuto ženu? Všel jsem do domu tvého, vody nohám mým nepodal jsi, ale tato slzami smáčela nohy mé, a vlasy hlavy své vytřela.'),
(1571501,54,42,7,45,'Nepolíbil jsi mne, ale tato, jakž jsem všel, nepřestala líbati noh mých.'),
(1571502,54,42,7,46,'Olejem hlavy mé nepomazal jsi, ale tato mastí mazala nohy mé.'),
(1571503,54,42,7,47,'Protož pravím tobě: Odpuštěniť jsou jí hříchové mnozí, neboť jest milovala mnoho. Komuť se pak málo odpouští, málo miluje.'),
(1571504,54,42,7,48,'I řekl k ní: Odpuštěniť jsou tobě hříchové.'),
(1571505,54,42,7,49,'Tedy počali, kteříž tu spolu seděli za stolem, říci sami mezi sebou: Kdo jest tento, kterýž i hříchy odpouští?'),
(1571506,54,42,7,50,'I řekl k ženě: Víra tvá tebe k spasení přivedla. Jdiž u pokoji.'),
(1571507,54,42,8,1,'I stalo se potom, že on chodil po městech a po městečkách, káže a zvěstuje království Boží, a dvanácte s ním,'),
(1571508,54,42,8,2,'I ženy některé, kteréž byly uzdraveny od duchů zlých a od nemocí: Maria, jenž slove Magdaléna, z nížto bylo sedm ďáblů vyšlo,'),
(1571509,54,42,8,3,'A Johanna manželka Chuzova, úředníka Herodesova, a Zuzanna, a jiné mnohé, kteréž posluhovaly jemu z statků svých.'),
(1571510,54,42,8,4,'Když se pak scházel zástup mnohý, a z okolních měst hrnuli se k němu, mluvil jim v podobenství:'),
(1571511,54,42,8,5,'Vyšel rozsevač, aby rozsíval símě své. A když on rozsíval, jedno padlo podle cesty, i pošlapáno jest, a ptáci nebeští szobali je.'),
(1571512,54,42,8,6,'A jiné padlo na skálu, a vzešlé uvadlo, nebo nemělo vláhy.'),
(1571513,54,42,8,7,'Jiné pak padlo mezi trní, a spolu vzrostlé trní udusilo je.'),
(1571514,54,42,8,8,'A jiné padlo v zemi dobrou, a když vzešlo, učinilo užitek stý. To pověděv, volal: Kdo má uši k slyšení, slyš.'),
(1571515,54,42,8,9,'I otázali se ho učedlníci jeho, řkouce: Jaké jest to podobenství?'),
(1571516,54,42,8,10,'A on řekl: Vám dáno jest znáti tajemství království Božího, ale jiným v podobenství, aby hledíce, neviděli, a slyšíce, nerozuměli.'),
(1571517,54,42,8,11,'Jestiť pak podobenství toto: Símě jest slovo Boží.'),
(1571518,54,42,8,12,'A kteréž padlo podle cesty, jsou ti, kteříž slyší, a potom přichází ďábel, a vynímá slovo z srdce jejich, aby nevěříce, spaseni nebyli.'),
(1571519,54,42,8,13,'Ale kteříž na skálu, ti když slyší, s radostí příjímají slovo, a tiť kořenů nemají; ti na čas věří, a v čas pokušení odstupují.'),
(1571520,54,42,8,14,'Kteréž pak mezi trní padlo, tiť jsou, kteříž slyšíce, a po pečování a zboží a rozkošech života jdouce, bývají udušeni, a nepřinášejí užitku.'),
(1571521,54,42,8,15,'Ale kteréž padlo v zemi dobrou, ti jsou, kteřížto v srdci ctném a dobrém, slyšíce slovo, zachovávají je, a užitek přinášejí v trpělivosti.'),
(1571522,54,42,8,16,'Nižádný pak rozsvítě svíci, nepřikrývá jí nádobou, ani staví pod postel, ale na svícen staví, aby ti, kteříž vcházejí, světlo viděli.'),
(1571523,54,42,8,17,'Nebo nic není tajného, což by nemělo býti zjeveno, ani co ukrytého, což by nemělo poznáno býti a na světlo vyjíti.'),
(1571524,54,42,8,18,'Protož vizte, jak slyšíte. Nebo kdož má, tomu bude dáno, a kdo nemá, i to, což domnívá se míti, bude odjato od něho.'),
(1571525,54,42,8,19,'Tedy přišli k němu matka a bratří jeho, ale nemohli ho dojíti pro zástup.'),
(1571526,54,42,8,20,'I pověděli mu, řkouce: Matka tvá a bratří tvoji stojí vně, chtíce tebe viděti.'),
(1571527,54,42,8,21,'A on odpověděv, řekl k nim: Matka má a bratří moji jsou ti, kteříž slovo Boží slyší a plní je.'),
(1571528,54,42,8,22,'Stalo se pak v jeden den, že on vstoupil na lodí i učedlníci jeho. I řekl k nim: Přeplavme se přes jezero. I odstrčili lodí od břehu.'),
(1571529,54,42,8,23,'A když se plavili, usnul. Tedy přišla bouře tuhého větru na jezero, a vlny lodí naplňovaly, takže v nebezpečenství byli.'),
(1571530,54,42,8,24,'I přistoupivše, zbudili ho, řkouce: Mistře, Mistře, hyneme. A on procítiv, přimluvil větru a zdutí vod. I přestala bouře, a stalo se utišení.'),
(1571531,54,42,8,25,'I řekl jim: Kde je víra vaše? Kteřížto bojíce se, podivili se, vespolek řkouce: I kdo jest tento, že větrům přikazuje i vodám, a poslouchají ho?'),
(1571532,54,42,8,26,'I plavili se do krajiny Gadarenské, kteráž jest proti Galilei.'),
(1571533,54,42,8,27,'A když z lodí vystoupil na zemi, potkal jej muž jeden z města, kterýž měl ďábelství od mnoha časů, a rouchem se neodíval, ani v domu býval, ale v hrobích.'),
(1571534,54,42,8,28,'Ten uzřev Ježíše zkřikl a padl před ním, a hlasem velikým řekl: Co je tobě do mne, Ježíši, Synu Boha nejvyššího? Prosím tebe, netrap mne.'),
(1571535,54,42,8,29,'Nebo přikazoval duchu nečistému, aby vyšel z toho člověka. Po mnohé zajisté časy jím lomcoval, a býval ukován řetězy a v poutech ostříhán, ale on polámal okovy a býval od ďábelství puzen na poušť.'),
(1571536,54,42,8,30,'I otázal se Ježíš, řka: Jakť říkají? A on řekl: Tma. Neb bylo mnoho ďáblů vešlo do něho.'),
(1571537,54,42,8,31,'Tedy prosili ho, aby jim nepřikazoval jíti do propasti.'),
(1571538,54,42,8,32,'Bylo pak tu veliké stádo vepřů, kteříž se pásli na hoře. I prosili ho ďáblové, aby jim dopustil do nich vjíti. I dopustil jim.'),
(1571539,54,42,8,33,'I vyšedše ďáblové z člověka, vešli do vepřů, a hned běželo stádo s chvátáním s vrchu do jezera, i ztonulo.'),
(1571540,54,42,8,34,'A viděvše pastýři, co se stalo, utekli pryč; a šedše, vypravovali to v městě i po vsech.'),
(1571541,54,42,8,35,'I vyšli lidé, aby viděli, co se stalo. I přišli k Ježíšovi, a nalezli člověka toho, z kteréhož ďáblové vyšli, oděného a majícího rozum, an sedí u noh Ježíšových. I báli se.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571542,54,42,8,36,'A vypravovali jim také ti, kteříž byli viděli, kterak jest zdráv učiněn ten, jenž měl ďábelství.'),
(1571543,54,42,8,37,'I prosilo ho to všecko množství té okolní krajiny Gadarenských, aby odšel od nich; nebo bázní velikou naplněni byli. A on vstoupiv na lodí, navrátil se.'),
(1571544,54,42,8,38,'Prosil ho pak muž ten, z kteréhož ďáblové vyšli, aby s ním byl. Ale Ježíš propustil ho, řka:'),
(1571545,54,42,8,39,'Navrať se do domu svého, a vypravuj, kterak veliké věci učinil tobě Bůh. I odšel, po všem městě vypravuje, jak veliké věci učinil jemu Ježíš.'),
(1571546,54,42,8,40,'Stalo se pak, když se navrátil Ježíš, že přijal jej zástup; nebo všickni očekávali ho.'),
(1571547,54,42,8,41,'A aj, přišel muž, kterémuž jméno bylo Jairus, a ten byl kníže školy Židovské. I padna k nohám Ježíšovým, prosil ho, aby všel do domu jeho.'),
(1571548,54,42,8,42,'Nebo měl dceru tu jedinou, kteréž bylo okolo dvanácti let, a ta umírala. A když šel, tiskl jej zástup.'),
(1571549,54,42,8,43,'Tedy žena jedna, jenž nemoc svou trpěla od let dvanácti, (kterážto byla na lékaře vynaložila všecken statek, a od žádného nemohla uzdravena býti,)'),
(1571550,54,42,8,44,'Přistoupivši pozadu, dotkla se podolka roucha jeho, a hned přestala nemoc její.'),
(1571551,54,42,8,45,'I řekl Ježíš: Kdo jest, jenž se mne dotekl? A když všickni zapírali, řekl Petr, a kteříž s ním byli: Mistře, zástupové tebe tisknou a tlačí, a ty pravíš: Kdo se mne dotekl?'),
(1571552,54,42,8,46,'I řekl Ježíš: Dotekl se mne někdo, nebo poznal jsem já, že jest moc ode mne vyšla.'),
(1571553,54,42,8,47,'A viduci žena, že by tajno nebylo, třesuci se, přistoupila a padla před ním, a pro kterou příčinu dotkla se ho, pověděla přede vším lidem, a kterak jest hned uzdravena.'),
(1571554,54,42,8,48,'A on řekl jí: Dobré mysli buď, dcero, víra tvá tebe uzdravila. Jdiž u pokoji.'),
(1571555,54,42,8,49,'A když on ještě mluvil, přišel jeden od knížete školy, řka jemu: Již umřela dcera tvá, nezaměstnávej Mistra.'),
(1571556,54,42,8,50,'Ale Ježíš uslyšav to, odpověděl jemu: Nebojž se, věř toliko, a zdrávať bude.'),
(1571557,54,42,8,51,'A všed do domu, nedopustil s sebou vjíti žádnému než Petrovi a Jakubovi a Janovi, a otci a mateři té děvečky.'),
(1571558,54,42,8,52,'Plakali jí pak všickni a kvílili. A on řekl: Neplačtež. Neumřelať, ale spíť.'),
(1571559,54,42,8,53,'I posmívali se jemu, vědouce, že jest umřela.'),
(1571560,54,42,8,54,'On pak vyhnav ven všecky, a ujav ruku její, zavolal, řka: Děvečko, vstaň!'),
(1571561,54,42,8,55,'I navrátil se duch její, a vstala hned. I kázal jí dáti jísti.'),
(1571562,54,42,8,56,'I divili se náramně rodičové její. A on jim kázal, aby žádnému nepravili o tom, co se bylo stalo.'),
(1571563,54,42,9,1,'I svolav Ježíš dvanácte učedlníků svých, dal jim sílu a moc nad všelikým ďábelstvím, a aby neduhy uzdravovali.'),
(1571564,54,42,9,2,'I poslal je, aby kázali království Boží, a uzdravovali nemocné.'),
(1571565,54,42,9,3,'A řekl jim: Nic nebeřte na cestu, ani hůlky, ani mošny, ani chleba, ani peněz, ani po dvou sukních mívejte.'),
(1571566,54,42,9,4,'A do kteréhožkoli domu vešli byste, tu zůstaňte, a odtud vyjděte.'),
(1571567,54,42,9,5,'A kteříž by vás koli nepřijali, vyjdouce z města toho, také i ten prach z noh vašich vyrazte na svědectví proti nim.'),
(1571568,54,42,9,6,'I vyšedše, chodili po městečkách vůkol, zvěstujíce evangelium, a uzdravujíce všudy.'),
(1571569,54,42,9,7,'Uslyšel pak Herodes čtvrták o všech věcech, kteréž se dály od něho. I rozjímal to v mysli své, protože bylo praveno od některých, že by Jan vstal z mrtvých,'),
(1571570,54,42,9,8,'A od jiných, že by se Eliáš zjevil, od některých pak, že by jeden z proroků starých vstal.'),
(1571571,54,42,9,9,'I řekl Herodes: Jana jsem já sťal. Kdož pak jest tento, o kterémž já slyším takové věci? I žádostiv byl ho viděti.'),
(1571572,54,42,9,10,'Vrátivše se pak apoštolé, vypravovali jemu, cožkoli činili. A pojav je, odšel soukromí na místo pusté města řečeného Betsaida.'),
(1571573,54,42,9,11,'To když zvěděli zástupové, šli za ním; i přijal je, a mluvil jim o království Božím, a ty, kteříž uzdravení potřebovali, uzdravoval.'),
(1571574,54,42,9,12,'Den pak počal se nachylovati. I přistoupivše dvanácte učedlníků, řekli jemu: Rozpusť zástupy, ať rozejdouce se do městeček okolních a do vesnic, jdou a hledají pokrmů, nebo jsme tuto na místě pustém.'),
(1571575,54,42,9,13,'I řekl jim: Dejte vy jim jísti. A oni řekli: Nemámeť víc než pět chlebů a dvě rybě, leč bychom my snad šli a nakoupili na tento všecken lid pokrmů?'),
(1571576,54,42,9,14,'Nebo bylo mužů okolo pěti tisíců. I řekl učedlníkům svým: Rozkažte se jim posaditi v každém řadu po padesáti.'),
(1571577,54,42,9,15,'I učinili tak, a posadili se všickni.'),
(1571578,54,42,9,16,'A vzav těch pět chlebů a dvě rybě, vzhlédl v nebe a dobrořečil jim, i lámal, a rozdával učedlníkům, aby kladli před zástup.'),
(1571579,54,42,9,17,'I jedli, a nasyceni jsou všickni. A sebráno jest, což jim bylo ostalo drobtů, dvanácte košů.'),
(1571580,54,42,9,18,'I stalo se, když se on modlil obzvláštně, že byli s ním učedlníci. I otázal se jich, řka: Kým mne praví býti zástupové?'),
(1571581,54,42,9,19,'A oni odpověděvše, řekli: Janem Křtitelem, a jiní Eliášem, jiní pak, že prorok jeden z starých vstal.'),
(1571582,54,42,9,20,'I řekl jim: Vy pak kým mne býti pravíte? Odpověděv Petr, řekl: Krista toho Božího.'),
(1571583,54,42,9,21,'A on pohroziv jim, rozkázal, aby toho žádnému nepravili,'),
(1571584,54,42,9,22,'Pravě: Že Syn člověka musí mnoho trpěti, a potupen býti od starších a od předních kněží i od zákoníků, a zamordován býti, a třetího dne z mrtvých vstáti.'),
(1571585,54,42,9,23,'I pravil ke všechněm: Chce-li kdo přijíti za mnou, zapři sám sebe, a beř svůj kříž na každý den, a následuj mne.'),
(1571586,54,42,9,24,'Nebo kdož bude chtíti duši svou zachovati, ztratíť ji; a kdož ztratí duši svou pro mne, zachováť ji.'),
(1571587,54,42,9,25,'Nebo co jest platno člověku, by všecken svět získal, kdyby sám sebe zatratil, nebo sám sebe zmrhal?'),
(1571588,54,42,9,26,'Neb kdož by se za mne styděl a za mé řeči, za tohoť se Syn člověka styděti bude, když přijde v slávě své a Otce svého i svatých andělů.'),
(1571589,54,42,9,27,'Ale pravímť vám jistě: Jsouť někteří z těch, jenž tuto stojí, kteříž neokusí smrti, až i uzří království Boží.'),
(1571590,54,42,9,28,'I stalo se po těch řečech, jako po osmi dnech, že Ježíš vzav s sebou Petra a Jakuba a Jana, vstoupil na horu, aby se modlil.'),
(1571591,54,42,9,29,'A když se modlil, učiněna jest tvář jeho proměněná, a oděv jeho bílý a stkvoucí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571592,54,42,9,30,'A aj, dva muži mluvili s ním, a ti byli Mojžíš a Eliáš.'),
(1571593,54,42,9,31,'Kteříž okázavše se v slávě, vypravovali o smrti jeho, kterouž měl podstoupiti v Jeruzalémě.'),
(1571594,54,42,9,32,'Petr pak a ti, kteříž s ním byli, obtíženi byli snem, a procítivše, viděli slávu jeho a dva muže, ani stojí s ním.'),
(1571595,54,42,9,33,'I stalo se, když oni odešli od něho, řekl Petr k Ježíšovi: Mistře, dobréť jest nám zde býti. Protož udělejme tuto tři stánky, tobě jeden, a Mojžíšovi jeden, a Eliášovi jeden, nevěda, co mluví.'),
(1571596,54,42,9,34,'A když on to mluvil, stal se oblak, i zastínil je. Báli se pak učedlníci, když oni vcházeli do oblaku.'),
(1571597,54,42,9,35,'I stal se hlas z oblaku řkoucí: Tentoť jest Syn můj milý, jeho poslouchejte.'),
(1571598,54,42,9,36,'A když se ten hlas stal, nalezen jest Ježíš sám. A oni mlčeli, a nepravili žádnému v těch dnech ničehož z těch věcí, kteréž jsou viděli.'),
(1571599,54,42,9,37,'Stalo se pak druhého dne, když sstupovali s hory, potkal jej zástup mnohý.'),
(1571600,54,42,9,38,'A aj, muž z zástupu zvolal, řka: Mistře, prosím tebe, vzhlédni na syna mého, nebť jediného toho mám.'),
(1571601,54,42,9,39,'A aj, duch jej napadá, a on ihned křičí, a sliní se, a ďábel lomcuje jím slinícím se, a nesnadně odchází od něho, sápaje jím.'),
(1571602,54,42,9,40,'I prosil jsem učedlníků tvých, aby jej vyvrhli, ale nemohli.'),
(1571603,54,42,9,41,'I odpověděv Ježíš, řekl: Ó pokolení nevěrné a převrácené, dokudž budu u vás a dokud vás snášeti budu? Přiveď sem syna svého.'),
(1571604,54,42,9,42,'A v tom, když on přicházel, porazil jej ďábel a lomcoval jím. I přimluvil duchu nečistému Ježíš, a uzdravil mládence, a navrátil jej otci jeho.'),
(1571605,54,42,9,43,'I divili se náramně všickni velikomocnosti Božské. A když se všickni divili všem věcem, kteréž činil Ježíš, řekl učedlníkům svým:'),
(1571606,54,42,9,44,'Složte vy v uších vašich řeči tyto, neboť Syn člověka bude vydán v ruce lidské.'),
(1571607,54,42,9,45,'Ale oni nesrozuměli slovu tomu, a bylo před nimi skryto, aby nevyrozuměli jemu. A báli se ho otázati o tom slovu.'),
(1571608,54,42,9,46,'I vznikla mezi nimi hádka o to, kdo by z nich byl větší.'),
(1571609,54,42,9,47,'Ježíš pak viděv přemyšlování srdce jejich, vzav dítě, postavil je podle sebe,'),
(1571610,54,42,9,48,'A řekl jim: Kdožkoli přijal by dítě toto ve jménu mém, mneť přijímá; a kdož by koli mne přijal, přijímá toho, kterýž mne poslal. Nebo kdožť jest nejmenší mezi všemi vámi, tenť bude veliký.'),
(1571611,54,42,9,49,'I odpověděv Jan, řekl: Mistře, viděli jsme jednoho, an ve jménu tvém ďábly vymítá; i bránili jsme mu, protože nechodí s námi.'),
(1571612,54,42,9,50,'I dí jemu Ježíš: Nebraňtež. Nebo kdoť není proti nám, s námiť jest.'),
(1571613,54,42,9,51,'I stalo se, když se doplnili dnové vzetí jeho vzhůru, a on se byl již na tom ustavil, aby šel do Jeruzaléma,'),
(1571614,54,42,9,52,'Že poslal posly před sebou. A oni jdouce, vešli do městečka Samaritánského, aby jemu zjednali hospodu.'),
(1571615,54,42,9,53,'I nepřijali ho, protože obličej jeho byl obrácen k jití do Jeruzaléma.'),
(1571616,54,42,9,54,'A viděvše to učedlníci jeho, Jakub a Jan, řekli: Pane, chceš-li, ať díme, aby oheň sstoupil s nebe a spálil je, jako i Eliáš učinil?'),
(1571617,54,42,9,55,'A obrátiv se Ježíš, potrestal jich, řka: Nevíte, čího jste vy duchu.'),
(1571618,54,42,9,56,'Syn zajisté člověka nepřišel zatracovati duší lidských, ale aby je spasil. I odešli do jiného městečka.'),
(1571619,54,42,9,57,'Stalo se pak, když šli cestou, řekl jemu jeden: Pane, půjdu za tebou, kam se koli obrátíš.'),
(1571620,54,42,9,58,'I řekl jemu Ježíš: Lišky doupata mají a ptáci nebeští hnízda, ale Syn člověka nemá, kde by hlavu sklonil.'),
(1571621,54,42,9,59,'I řekl k jinému: Pojď za mnou. A on řekl: Pane, dopusť mi prve jíti a pochovati otce mého.'),
(1571622,54,42,9,60,'I dí jemu Ježíš: Nech, ať mrtví pochovávají mrtvé své, ale ty jda, zvěstuj království Boží.'),
(1571623,54,42,9,61,'I řekl opět jiný : Půjdu za tebou, Pane, ale prve dopusť mi, ať se rozžehnám s těmi, kteříž jsou v domu mém.'),
(1571624,54,42,9,62,'Řekl jemu Ježíš: Žádný, kdož vztáhna ruku svou k pluhu, ohlídal by se nazpět, není způsobný k království Božímu.'),
(1571625,54,42,10,1,'Potom pak vyvolil Pán i jiných sedmdesát, a poslal je po dvou před tváří svou do každého města i místa, kamž měl sám přijíti.'),
(1571626,54,42,10,2,'A pravil jim: Žeň zajisté jest mnohá, ale dělníků málo. Protož proste Pána žni, ať vypudí dělníky na žeň svou.'),
(1571627,54,42,10,3,'Jdětež. Aj, já posílám vás jako berany mezi vlky.'),
(1571628,54,42,10,4,'Nenostež s sebou pytlíka, ani mošny, ani obuvi, a žádného na cestě nepozdravujte.'),
(1571629,54,42,10,5,'A do kteréhožkoli domu vejdete, nejprve rcete: Pokoj tomuto domu.'),
(1571630,54,42,10,6,'A bude-liť tu který syn pokoje, odpočineť na něm pokoj váš; pakli nic, k vámť se navrátí.'),
(1571631,54,42,10,7,'A v témž domu ostaňte, jedouce a pijíce, což u nich jest. Nebo hoden jest dělník mzdy své. Nechoďtež z domu do domu.'),
(1571632,54,42,10,8,'Ale do kteréhožkoli města vešli byste a přijali by vás, jezte, což před vás předloží.'),
(1571633,54,42,10,9,'A uzdravujte nemocné, kteříž by v něm byli, a rcete jim: Přiblížiloť se k vám království Boží.'),
(1571634,54,42,10,10,'A do kteréhožkoli města vešli byste, a nepřijali by vás, vyjdouce na ulice jeho, rcetež:'),
(1571635,54,42,10,11,'Také i ten prach, kterýž se přichytil nás z města vašeho, vyrážíme na vás. Ale však to vězte, žeť se jest přiblížilo k vám království Boží.'),
(1571636,54,42,10,12,'Pravím zajisté vám, že Sodomským v onen den lehčeji bude nežli tomu městu.'),
(1571637,54,42,10,13,'Běda tobě Korozaim, běda tobě Betsaido. Nebo kdyby v Týru a v Sidonu činěni byli divové ti, kteříž v vás činěni jsou, dávno by v žíni a v popele sedíce, pokání činili.'),
(1571638,54,42,10,14,'A protož Týru a Sidonu lehčeji bude na soudu nežli vám.'),
(1571639,54,42,10,15,'A ty Kafarnaum, které jsi až do nebe zvýšeno, až do pekla sníženo budeš.'),
(1571640,54,42,10,16,'Kdož vás slyší, mne slyší; a kdo vámi pohrdá, mnou pohrdá; kdož pak mnou pohrdá, pohrdáť tím, kdož mne poslal.'),
(1571641,54,42,10,17,'Potom navrátilo se s radostí těch sedmdesáte, řkouce: Pane, také i ďáblové se nám poddávají ve jménu tvém.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571642,54,42,10,18,'I řekl jim: Viděl jsem satana jako blesk padajícího s nebe.'),
(1571643,54,42,10,19,'Aj, dávámť vám moc šlapati na hady a na štíry i na všelikou moc nepřítele, a nic vám neuškodí.'),
(1571644,54,42,10,20,'Avšak z toho se neradujte, žeť se vám poddávají duchové, ale raději se radujte, že jména vaše napsána jsou v nebesích.'),
(1571645,54,42,10,21,'V tu hodinu rozveselil se v duchu Ježíš, a řekl: Chválím tě, Otče, Pane nebe i země, že jsi tyto věci skryl před moudrými a opatrnými, a zjevils je maličkým. Ovšem, Otče, neb tak se líbilo před tebou.'),
(1571646,54,42,10,22,'Všecky věci dány jsou mi od Otce mého, a žádný neví, kdo by byl Syn, jediné Otec, a kdo by byl Otec, jediné Syn, a komuž by chtěl Syn zjeviti.'),
(1571647,54,42,10,23,'A obrátiv se k učedlníkům obzvláštně, řekl: Blahoslavené oči, kteréž vidí, co vy vidíte.'),
(1571648,54,42,10,24,'Nebo pravím vám, že mnozí proroci i králové chtěli viděti, což vy vidíte, a neviděli, a slyšeti, což vy slyšíte, a neslyšeli.'),
(1571649,54,42,10,25,'A aj, jeden zákoník vstal, pokoušeje ho, a řka: Mistře, co čině, život věčný dědičně obdržím?'),
(1571650,54,42,10,26,'A on řekl k němu: V Zákoně co jest psáno? Kterak čteš?'),
(1571651,54,42,10,27,'A on odpověděv, řekl: Milovati budeš Pána Boha svého ze všeho srdce svého, a ze vší duše své, a ze vší síly své, i ze vší mysli své, a bližního svého jako sebe samého.'),
(1571652,54,42,10,28,'I řekl mu Ježíš: Právě jsi odpověděl. To čiň, a živ budeš.'),
(1571653,54,42,10,29,'On pak chtěje se sám ospravedlniti, dí Ježíšovi: A kdo jest můj bližní?'),
(1571654,54,42,10,30,'I odpověděv Ježíš, řekl: Člověk jeden šel z Jeruzaléma do Jericho, i upadl mezi lotry. Kteříž obloupivše jej a zranivše, odešli, odpolu živého nechavše.'),
(1571655,54,42,10,31,'I přihodilo se, že kněz jeden šel touž cestou, a uzřev jej, pominul.'),
(1571656,54,42,10,32,'Též i Levíta až k tomu místu přišed, a uzřev jej, pominul.'),
(1571657,54,42,10,33,'Samaritán pak jeden, cestou se bera, přišel až k němu, a uzřev jej, milosrdenstvím hnut jest.'),
(1571658,54,42,10,34,'A přistoupě, uvázal rány jeho, naliv oleje a vína, a vloživ jej na hovado své, vedl do hospody, a péči o něj měl.'),
(1571659,54,42,10,35,'Druhého pak dne odjíti maje, vyňav dva peníze, dal hospodáři, a řekl: Měj o něj péči, a cožkoli nad to vynaložíš, já když se vrátím, zaplatím tobě.'),
(1571660,54,42,10,36,'Kdo tedy z těch tří zdá se tobě bližním býti tomu, kterýž upadl mezi lotry?'),
(1571661,54,42,10,37,'A on řekl: Ten, kterýž učinil milosrdenství nad ním. I řekl jemu Ježíš: Jdi, i ty učiň též.'),
(1571662,54,42,10,38,'I stalo se, když šli, že on všel do jednoho městečka. Žena pak jedna, jménem Marta, přijala jej do domu svého.'),
(1571663,54,42,10,39,'A ta měla sestru, jménem Mariji, kterážto seděci u noh Ježíšových, poslouchala slova jeho.'),
(1571664,54,42,10,40,'Ale Marta pečliva byla při mnohé službě Pánu. Kterážto přistoupivši, řekla: Pane, nemáš-liž o to péče, že sestra má nechala mne samé sloužiti? Protož rci jí, ať mi pomůž.'),
(1571665,54,42,10,41,'A odpověděv, řekl jí Ježíš: Marta, Marta, pečlivá jsi, a rmoutíš se při mnohých věcech.'),
(1571666,54,42,10,42,'Ale jednohoť jest potřebí. Mariať dobrou stránku vyvolila, kterážto nebude odjata od ní.'),
(1571667,54,42,11,1,'I stalo se, když byl na jednom místě, modle se, že když přestal, řekl k němu jeden z učedlníků jeho: Pane, nauč nás modliti se, jako i Jan učil učedlníky své.'),
(1571668,54,42,11,2,'I řekl jim: Když se modlíte; říkejte: Otče náš, jenž jsi v nebesích, posvěť se jméno tvé. Přijď království tvé. Buď vůle tvá, jako v nebi tak i na zemi.'),
(1571669,54,42,11,3,'Chléb náš vezdejší dávej nám každého dne.'),
(1571670,54,42,11,4,'I odpusť nám hříchy naše, nebo i my odpouštíme všelikému vinníku našemu. A neuvoď nás v pokušení, ale zbav nás od zlého.'),
(1571671,54,42,11,5,'I řekl k nim: Kdo z vás bude míti přítele, a půjde k němu o půlnoci, a dí jemu: Příteli, půjč mi tří chlebů.'),
(1571672,54,42,11,6,'Nebo přítel můj přišel s cesty ke mně, a nemám, co bych předložil před něj.'),
(1571673,54,42,11,7,'A on vnitř jsa, odpověděl by, řka: Nečiň mi nevole, neb jsou již dveře zavříny, a dítky mé se mnou jsou v pokoji. Nemohuť vstáti a dáti tobě.'),
(1571674,54,42,11,8,'Pravím vám: Ačť nedá jemu, vstana, protože jest přítel jeho, ale však pro nezbednost jeho vstana, dá jemu, kolikožkoli potřebuje.'),
(1571675,54,42,11,9,'I jáť pravím vám: Proste, a budeť vám dáno; hledejte, a naleznete; tlucte, a budeť vám otevříno.'),
(1571676,54,42,11,10,'Neb každý, kdož prosí, béře; a kdož hledá, nalézá; a tomu, kdož tluče, bude otevříno.'),
(1571677,54,42,11,11,'Kterého pak z vás otce prosil by syn za chléb, zdali kamene podá jemu? Aneb za rybu, zdali místo ryby dá jemu hada?'),
(1571678,54,42,11,12,'Aneb prosil-li by za vejce, zdali podá jemu štíra?'),
(1571679,54,42,11,13,'Poněvadž tedy vy, zlí jsouce, umíte dobré dary dávati dětem svým, čím více Otec váš nebeský dá Ducha svatého těm, kteříž ho prosí?'),
(1571680,54,42,11,14,'I vymítal Ježíš ďábelství, a to bylo němé. Stalo se pak, když vyšlo ďábelství, že mluvil němý. I divili se zástupové.'),
(1571681,54,42,11,15,'Ale někteří z nich pravili: V Belzebubu, knížeti ďábelském, vymítá ďábly.'),
(1571682,54,42,11,16,'A jiní pokoušejíce ho, znamení s nebe hledali od něho.'),
(1571683,54,42,11,17,'Ale on znaje myšlení jejich, řekl jim: Každé království samo v sobě rozdělené pustne, a dům na dům padá.'),
(1571684,54,42,11,18,'Jestližeť jest pak i satan proti sobě rozdělen, kterakž stane království jeho? Nebo pravíte, že já v Belzebubu vymítám ďábly.'),
(1571685,54,42,11,19,'Jestliže já v Belzebubu vymítám ďábly, synové vaši v kom vymítají? Protož oni soudcové vaši budou.'),
(1571686,54,42,11,20,'Pakliť prstem Božím vymítám ďábly, jistěť jest přišlo k vám království Boží.'),
(1571687,54,42,11,21,'Když silný oděnec ostříhá síně své, v pokoji jsou všecky věci, kteréž má.'),
(1571688,54,42,11,22,'Pakli by silnější než on přijda, přemohl jej, všecka odění jeho odejme, v něž úfal, a loupeže jeho rozdělí.'),
(1571689,54,42,11,23,'Kdožť není se mnou, proti mně jest; a kdož neshromažďuje se mnou, rozptylujeť.'),
(1571690,54,42,11,24,'Když nečistý duch vyjde od člověka, chodí po místech suchých, hledaje odpočinutí. A nenalezna, dí: Vrátím se do domu svého, odkudž jsem vyšel.'),
(1571691,54,42,11,25,'A přijda, nalezne jej vymetený a ozdobený.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571692,54,42,11,26,'I jde, a přijme k sobě jiných sedm duchů horších sebe, a vejdouce, přebývají tam. I jsou poslední věci člověka toho horší nežli první.'),
(1571693,54,42,11,27,'I stalo se, když on to mluvil, pozdvihši hlasu jedna žena z zástupu, řekla jemu: Blahoslavený život, kterýž tebe nosil, a prsy, kterýchž jsi požíval.'),
(1571694,54,42,11,28,'A on řekl: Ovšem pak blahoslavení, kteříž slyší slovo Boží a ostříhají jeho.'),
(1571695,54,42,11,29,'A když se zástupové scházeli, počal praviti: Pokolení toto nešlechetné jest. Znamení vyhledává, a znamení jemu nebude dáno, než znamení Jonáše proroka.'),
(1571696,54,42,11,30,'Nebo jakož Jonáš učiněn byl znamením Ninivitským, takť bude i Syn člověka pokolení tomuto.'),
(1571697,54,42,11,31,'Královna od poledne stane na soudu s muži pokolení tohoto, a odsoudí je. Nebo přijela od končin země, aby slyšela moudrost Šalomounovu, a aj, více než Šalomoun tuto!'),
(1571698,54,42,11,32,'Muži Ninivitští povstanou na soudu s pokolením tímto, a odsoudí je. Nebo činili pokání k kázání Jonášovu, a aj, více nežli Jonáš tuto!'),
(1571699,54,42,11,33,'Žádný rozsvítě svíci, nepostaví jí do skrýše, ani pod kbelec, ale na svícen, aby ti, kteříž vcházejí, světlo viděli.'),
(1571700,54,42,11,34,'Svíce těla tvého jest oko tvé. Když by tedy oko tvé sprostné bylo, i tělo tvé všecko bude světlé; a pakliť bude nešlechetné, takéť i tělo tvé tmavé bude.'),
(1571701,54,42,11,35,'Viziž tedy, aby světlo, kteréž jest v tobě, nebylo tmou.'),
(1571702,54,42,11,36,'Pakli celé tělo tvé světlé bude, nemaje žádné částky tmavé, budeť všecko tak světlé, že tě jako svíce bleskem osvítí.'),
(1571703,54,42,11,37,'A mezi tím když on mluvil, prosil ho jeden farizeus, aby obědval u něho. A všed, posadil se za stůl.'),
(1571704,54,42,11,38,'Farizeus pak viděv to, podivil se, že se neumyl před obědem.'),
(1571705,54,42,11,39,'I řekl Pán k němu: Nyní vy farizeové povrchu konvice a mísy čistíte, ale to, což vnitř jest v vás, plno jest loupeže a nešlechetností.'),
(1571706,54,42,11,40,'Blázni, zdaliž ten, kterýž učinil, což zevnitř jest, neučinil také i toho, což jest vnitř?'),
(1571707,54,42,11,41,'Ale však i z toho, což máte, dávejte almužnu, a aj, všecky věci vaše čisté budou.'),
(1571708,54,42,11,42,'Ale běda vám farizeům, kteříž desátky dáváte z máty a z routy a ze všeliké byliny, ale opouštíte soud a lásku Boží; ješto tyto věci měli jste činiti, a oněch neopouštěti.'),
(1571709,54,42,11,43,'Běda vám farizeům, nebo milujete první místa v školách a pozdravování na trzích.'),
(1571710,54,42,11,44,'Běda vám, zákoníci a farizeové pokrytci, nebo jste jako hrobové nepatrní, po nichž lidé chodíce, nevědí o tom, co tam jest.'),
(1571711,54,42,11,45,'I odpověděv jeden z zákoníků, řekl jemu: Mistře, tyto věci mluvě, i nám také lehkost činíš.'),
(1571712,54,42,11,46,'A on řekl: I vám zákoníkům běda, nebo obtěžujete lidi břemeny nesnesitelnými, a sami se těch břemen jedním prstem nedotýkáte.'),
(1571713,54,42,11,47,'Běda vám, jenž vzděláváte hroby prorocké, kteréž otcové vaši zmordovali.'),
(1571714,54,42,11,48,'A tak osvědčujete a potvrzujete skutků otců vašich. Nebo oni zajisté zmordovali jsou je, vy pak vzděláváte hroby jejich.'),
(1571715,54,42,11,49,'Protož i Moudrost Boží řekla: Pošliť k nim proroky a apoštoly, a z těch některé mordovati budou, a jiné vyháněti,'),
(1571716,54,42,11,50,'Aby požádáno bylo od tohoto pokolení krve všech proroků, kteráž vylita jest od ustanovení světa,'),
(1571717,54,42,11,51,'Od krve Abelovy až do krve Zachariášovy, kterýž zahynul mezi oltářem a chrámem. Jistě, pravím vám, požádáno bude od pokolení tohoto.'),
(1571718,54,42,11,52,'Běda vám zákoníkům, nebo jste vzali klíč umění; sami jste nevešli, a těm, kteříž vcházeli, zbránili jste.'),
(1571719,54,42,11,53,'A když jim to mluvil, počali zákoníci a farizeové přísně jemu odpírati, a k mnohým řečem příčiny jemu dávati,'),
(1571720,54,42,11,54,'Ukládajíce o něm, a hledajíce popadnouti něco z úst jeho, aby jej obžalovali.'),
(1571721,54,42,12,1,'A vtom, když mnozí zástupové scházeli se, takže jedni druhé velmi tlačili, počal mluviti k učedlníkům svým: Nejpředněji se varujte od kvasu farizeů, jenž jest pokrytství.'),
(1571722,54,42,12,2,'Neboť nic není skrytého, což by nemělo býti zjeveno; ani jest co tajného, ješto by nemělo býti zvědíno.'),
(1571723,54,42,12,3,'Protož to, co jste pravili ve tmách, bude na světle slyšáno, a co jste sobě v uši šeptali v pokojích, hlásánoť bude na střechách.'),
(1571724,54,42,12,4,'Pravím pak vám přátelům svým: Nestrachujte se těch, jenž tělo zabíjejí, a potom nemají, co by více učinili.'),
(1571725,54,42,12,5,'Ale ukážiť vám, koho se máte báti: Bojte se toho, kterýžto, když zabije, má moc uvrci do pekelného ohně. Jistě, pravím vám, toho se bojte.'),
(1571726,54,42,12,6,'Zdaliž neprodávají pět vrabců za dva haléře? Avšak ani jeden z nich není v zapomenutí před Bohem.'),
(1571727,54,42,12,7,'Nýbrž i vlasové hlavy vaší všickni zečteni jsou. Protož nebojtež se, mnohemť vy vrabce převyšujete.'),
(1571728,54,42,12,8,'Pravímť pak vám: Každý kdož by koli vyznal mne před lidmi, i Syn člověka vyzná jej před anděly Božími.'),
(1571729,54,42,12,9,'Kdož by mne pak zapřel před lidmi, zapřínť bude před anděly Božími.'),
(1571730,54,42,12,10,'A každý kdož dí slovo proti Synu člověka, bude mu odpuštěno, ale tomu, kdož by se Duchu svatému rouhal, nebudeť odpuštěno.'),
(1571731,54,42,12,11,'Když pak vás voditi budou do škol a k vladařům a k mocným, nepečujte, kterak aneb co byste odpovídali, aneb co byste mluvili.'),
(1571732,54,42,12,12,'Duch svatý zajisté naučí vás v tu hodinu, co byste měli mluviti.'),
(1571733,54,42,12,13,'I řekl jemu jeden z zástupu: Mistře, rci bratru mému, ať rozdělí se mnou dědictví.'),
(1571734,54,42,12,14,'A on řekl jemu: Člověče, kdo mne ustavil soudcí aneb děličem nad vámi?'),
(1571735,54,42,12,15,'I řekl k nim: Viztež a vystříhejte se od lakomství; neboť ne v rozhojnění statku něčího život jeho záleží.'),
(1571736,54,42,12,16,'Pověděl jim také i podobenství, řka: Člověka jednoho bohatého hojné úrody pole přineslo.'),
(1571737,54,42,12,17,'I přemyšloval sám v sobě, řka: Co učiním, že nemám, kde bych shromáždil úrody své?'),
(1571738,54,42,12,18,'I řekl: Toto učiním: Zbořím stodoly své a větších nadělám, a tu shromáždím všecky své úrody i zboží svá.'),
(1571739,54,42,12,19,'A dím duši své: Duše, máš mnoho statku složeného za mnohá léta, odpočívej, jez, pij, měj dobrou vůli.'),
(1571740,54,42,12,20,'I řekl jemu Bůh: Ó blázne, této noci požádají duše tvé od tebe, a to, cožs připravil, čí bude?'),
(1571741,54,42,12,21,'Takť jest každý, kdož sobě shromažďuje, a není v Bohu bohatý.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571742,54,42,12,22,'Řekl pak učedlníkům svým: Protož pravím vám: Nebuďtež pečliví o život svůj, co byste jedli, ani o tělo, čím byste se odívali.'),
(1571743,54,42,12,23,'Život větší jest nežli pokrm, a tělo větší nežli oděv.'),
(1571744,54,42,12,24,'Patřte na havrany, žeť nesejí, ani žnou, a nemají špižírny, ani stodoly, a Bůh krmí je. I čím v větší vážnosti jste vy než ptactvo?'),
(1571745,54,42,12,25,'A kdož pak z vás pečlivě o to mysle, můž přidati ku postavě své loket jeden?'),
(1571746,54,42,12,26,'Poněvadž tedy nemůžete s to býti, což nejmenšího jest, proč o jiné věci se staráte?'),
(1571747,54,42,12,27,'Patřte na kvítí polní, kterak rostou, nedělají, ani předou, a pravímť vám, že ani Šalomoun ve vší slávě své nebyl tak odín, jako jedno z těchto.'),
(1571748,54,42,12,28,'A poněvadž trávu, kteráž dnes na poli jest, a zítra do peci uvržena bývá, Bůh tak odívá, čím více vás, ó malé víry?'),
(1571749,54,42,12,29,'I vy nestarejte se o to, co byste jedli, aneb co byste pili, aniž o to tak velmi pečujte.'),
(1571750,54,42,12,30,'Nebo těch všech věcí národové světa tohoto hledají. Víť pak Otec váš, že těch věcí potřebujete.'),
(1571751,54,42,12,31,'Ale raději hledejte království Božího, a tyto všecky věci budou vám přidány.'),
(1571752,54,42,12,32,'Neboj se, ó maličké stádce, neboť se zalíbilo Otci vašemu dáti vám království.'),
(1571753,54,42,12,33,'Prodávejte statky vaše, a dávejte almužnu. Dělejte sobě pytlíky, kteříž nevetšejí, poklad, kterýž nehyne, v nebesích, kdežto zloděj dojíti nemůž, a kdež mol nekazí.'),
(1571754,54,42,12,34,'Nebo kdež jest poklad váš, tuť bude i srdce vaše.'),
(1571755,54,42,12,35,'Buďtež bedra vaše přepásaná, a svíce hořící.'),
(1571756,54,42,12,36,'A vy podobni buďte lidem očekávajícím Pána svého, až by se vrátil z svadby, aby hned, jakž by přišel a potloukl, otevřeli jemu.'),
(1571757,54,42,12,37,'Blaze služebníkům těm, kteréž přijda Pán, nalezl by, a oni bdí. Amen pravím vám, že přepáše se, a káže jim sednouti za stůl, a chodě, bude jim sloužiti.'),
(1571758,54,42,12,38,'A přišel-liť by v druhé bdění, a pakliť by v třetí bdění přišel, a tak je nalezl, blahoslavení jsou služebníci ti.'),
(1571759,54,42,12,39,'Toto pak vězte, že byť věděl hospodář, v kterou by hodinu měl zloděj přijíti, bděl by zajisté, a nedal by podkopati domu svého.'),
(1571760,54,42,12,40,'Protož i vy buďte hotovi, nebo v kterou hodinu nenadějete se, Syn člověka přijde.'),
(1571761,54,42,12,41,'I řekl jemu Petr: Pane, nám-li pravíš toto podobenství, čili všechněm?'),
(1571762,54,42,12,42,'I dí Pán: Aj kdo jest věrný šafář a opatrný, jehož by ustanovil pán nad čeledí svou, aby jim v čas dával vyměřený pokrm,'),
(1571763,54,42,12,43,'Blahoslavený služebník ten, kteréhož, když by přišel pán jeho, nalezne, an tak činí.'),
(1571764,54,42,12,44,'Vpravdě pravím vám, že nade vším statkem svým ustanoví jej.'),
(1571765,54,42,12,45,'Pakli by řekl služebník ten v srdci svém: Prodlévá přijíti pán můj, i počal by bíti služebníky a služebnice, a jísti a píti i opíjeti se,'),
(1571766,54,42,12,46,'Přijdeť pán služebníka toho v den, v kterýž se nenaděje, a v hodinu, kteréž neví. I oddělíť jej, a díl jeho položí s nevěrnými.'),
(1571767,54,42,12,47,'Služebník pak ten, kterýž by znal vůli pána svého a nepřipravoval se, a nečinil podle vůle jeho, bit bude velmi.'),
(1571768,54,42,12,48,'Ale kterýž neznal, a hodné věci trestání činil, bit bude ne tak velmi. Každému pak, komuž jest mnoho dáno, mnoho bude od něho požádáno; a komuť jsou mnoho poručili, víceť požádají od něho.'),
(1571769,54,42,12,49,'Oheň přišel jsem pustiti na zemi, a co chci, jestliže již hoří?'),
(1571770,54,42,12,50,'Ale křtem mám křtěn býti, a kterak jsem soužen, dokudž se nevykoná!'),
(1571771,54,42,12,51,'A což se domníváte, že bych přišel pokoj dáti na zemi? Nikoli, pravím vám, ale rozdělení.'),
(1571772,54,42,12,52,'Nebo již od této chvíle bude jich pět v jednom domu rozděleno, tři proti dvěma, a dva proti třem.'),
(1571773,54,42,12,53,'Bude rozdělen otec proti synu, a syn proti otci, mátě proti dceři, a dcera proti mateři, svegruše proti nevěstě své, a nevěsta proti svegruši své.'),
(1571774,54,42,12,54,'Pravil také i k zástupům: Když vídáte oblak, an vzchodí od západu, hned pravíte: Příval jde, a tak bývá.'),
(1571775,54,42,12,55,'A když od poledne vítr věje, říkáte: Bude horko, a býváť.'),
(1571776,54,42,12,56,'Pokrytci, způsob nebe a země umíte souditi, a kterakž pak tohoto času nepoznáváte?'),
(1571777,54,42,12,57,'Ano proč i sami od sebe nesoudíte, což spravedlivého jest?'),
(1571778,54,42,12,58,'Když pak jdeš s protivníkem svým k vrchnosti, na cestě přičiň se o to, abys byl zproštěn od něho, aby snad netáhl tebe k soudci, a soudce dal by tebe biřici, a biřic vsadil by tě do žaláře.'),
(1571779,54,42,12,59,'Pravím tobě: Nevyjdeš odtud, dokudž bys i toho posledního haléře nenavrátil.'),
(1571780,54,42,13,1,'Byli pak tu přítomní času toho někteří, vypravujíce jemu o Galilejských, kterýchžto krev Pilát smísil s obětmi jejich.'),
(1571781,54,42,13,2,'I odpověděv Ježíš, řekl jim: Co mníte, že jsou ti Galilejští byli větší hříšníci nežli všickni jiní Galilejští, že takové věci trpěli?'),
(1571782,54,42,13,3,'Nikoli, pravímť vám. Ale nebudete-li pokání činiti, všickni též zahynete.'),
(1571783,54,42,13,4,'Anebo oněch osmnácte, na kteréžto upadla věže v Siloe, a zbila je, zdali se domníváte, že by oni vinni byli nad všecky lidi přebývající v Jeruzalémě?'),
(1571784,54,42,13,5,'Nikoli, pravím vám. Ale nebudete-li pokání činiti, všickni též zahynete.'),
(1571785,54,42,13,6,'Pověděl pak toto podobenství: Člověk jeden měl strom fíkový štípený na vinici své. I přišel, hledaje ovoce na něm, ale nenalezl.'),
(1571786,54,42,13,7,'I řekl k vinaři: Aj, po tři léta již přicházím, hledaje ovoce na tom fíku, a nenalézám. Vytniž jej! Proč i tu zemi darmo kazí?'),
(1571787,54,42,13,8,'On pak odpověděv, řekl jemu: Pane, ponechejž ho i tohoto léta, ažť jej okopám a ohnojím,'),
(1571788,54,42,13,9,'Zdali by nesl ovoce. Pakliť neponese, potom vytneš jej.'),
(1571789,54,42,13,10,'Učil pak v jedné škole jejich v den sváteční.'),
(1571790,54,42,13,11,'A aj, byla tu žena, kteráž měla ducha nemoci osmnácte let, a byla sklíčena, a nijakž se nemohla zprostiti.'),
(1571791,54,42,13,12,'A uzřev ji Ježíš, zavolal jí k sobě, a řekl jí: Ženo, zproštěna jsi od nemoci své.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571792,54,42,13,13,'I vložil na ni ruce, a ihned zdvihla se, a velebila Boha.'),
(1571793,54,42,13,14,'Tedy kníže školní odpověděv, hněvaje se proto, že v den sváteční uzdravoval Ježíš, řekl k zástupu: Šest dní jest, v nichž náleží dělati; protož v těch dnech přicházejíce, buďte uzdravováni, a ne v den sobotní.'),
(1571794,54,42,13,15,'I odpověděv jemu Pán, řekl: Pokrytče, zdali jeden každý z vás v den sváteční neodvazuje vola svého nebo osla od jeslí, a nevodí napájeti?'),
(1571795,54,42,13,16,'Tato pak dcera Abrahamova, kterouž byl svázal satan již osmnácte let, což neměla býti rozvázána od svazku v den sváteční?'),
(1571796,54,42,13,17,'A když on to pověděl, zastyděli se všickni protivníci jeho, ale všecken lid radoval se ze všech těch slavných skutků, kteříž se dáli od něho.'),
(1571797,54,42,13,18,'I řekl Ježíš: Čemu podobno jest království Boží a k čemu je přirovnám?'),
(1571798,54,42,13,19,'Podobno jest zrnu horčičnému, kteréžto vzav člověk, uvrhl do zahrady své. I rostlo, a učiněno jest v strom veliký, a ptactvo nebeské hnízda sobě dělali na ratolestech jeho.'),
(1571799,54,42,13,20,'A opět řekl: K čemu připodobním království Boží?'),
(1571800,54,42,13,21,'Podobno jest kvasu, kterýžto vzavši žena, zadělala ve třech měřicích mouky, až zkysalo všecko.'),
(1571801,54,42,13,22,'I chodil po městech a městečkách uče, bera se do Jeruzaléma.'),
(1571802,54,42,13,23,'I řekl jemu jeden: Pane, tuším, že jest málo těch, kteříž spaseni býti mají? On pak řekl k nim:'),
(1571803,54,42,13,24,'Snažujte se vcházeti těsnou branou; neboť (pravím vám) mnozí hledati budou vjíti, a nebudou moci,'),
(1571804,54,42,13,25,'Totiž když vejde hospodář, a zavře dveře, a počnete vně státi a tlouci na dveře, řkouce: Pane, Pane, otevři nám, a on odpovídaje, díť vám: Neznám vás, odkud jste:'),
(1571805,54,42,13,26,'Tedy počnete říci: Jídali jsme a píjeli před tebou, a na ulicech našich jsi učil.'),
(1571806,54,42,13,27,'I dí: Pravím vám, žeť vás neznám, odkud jste. Odejdětež ode mne všickni činitelé nepravosti.'),
(1571807,54,42,13,28,'Tamť bude pláč a škřipení zubů, když uzříte Abrahama a Izáka a Jákoba a všecky proroky v království Božím, sami pak sebe vyhnané ven.'),
(1571808,54,42,13,29,'I přijdouť mnozí od východu, a od západu, a od půlnoci, i od poledne, a budou stoliti v království Božím.'),
(1571809,54,42,13,30,'A aj, jsouť poslední, kteříž budou první, a jsou první, kteříž budou poslední.'),
(1571810,54,42,13,31,'A v ten den přistoupili někteří z farizeů, řkouce jemu: Vyjdi, a odejdi odsud, nebo Herodes chce tě zamordovati.'),
(1571811,54,42,13,32,'I řekl jim: Jdouce, povězte lišce té: Aj, vymítám ďábly, a uzdravuji dnes a zítra, a třetího dne dokonám.'),
(1571812,54,42,13,33,'Ale však musím dnes a zítra i pozejtří choditi; neboť jest nelze proroku zahynouti jinde kromě Jeruzaléma.'),
(1571813,54,42,13,34,'Jeruzaléme, Jeruzaléme, ješto morduješ proroky a kamenuješ ty, kteříž k tobě bývají posláni, kolikrát jsem chtěl shromážditi syny tvé, jako slepice kuřátka svá pod křídla? A nechtěli jste.'),
(1571814,54,42,13,35,'Aj, opuštěn bude dům váš a zanechán vám pustý. Ale jistě pravím vám, že nikoli mne neuzříte, ažť přijde čas, když díte: Požehnaný, jenž se béře ve jménu Páně.'),
(1571815,54,42,14,1,'I stalo se, když všel Ježíš do domu jednoho knížete farizejského v sobotu, aby jedl chléb, že oni šetřili ho.'),
(1571816,54,42,14,2,'A aj, člověk jeden vodnotelný byl před ním.'),
(1571817,54,42,14,3,'I odpověděv Ježíš, dí zákoníkům a farizeům, řka: Sluší-li v sobotu uzdravovati?'),
(1571818,54,42,14,4,'A oni mlčeli. Tedy on dosáh jeho, uzdravil a propustil.'),
(1571819,54,42,14,5,'A odpověděv k nim řekl: Čí z vás osel anebo vůl upadl by do studnice, a ne ihned by ho vytáhl v den sobotní?'),
(1571820,54,42,14,6,'I nemohli jemu na to odpovědíti.'),
(1571821,54,42,14,7,'Pověděl také i ku pozvaným podobenství, (spatřiv to, kterak sobě přední místa vyvolovali,) řka k nim:'),
(1571822,54,42,14,8,'Kdybys byl od někoho pozván na svadbu, nesedej na předním místě, ať by snad vzácnější nežli ty nebyl pozván od něho.'),
(1571823,54,42,14,9,'A přijda ten, kterýž tebe i onoho pozval, řekl by tobě: Dej tomuto místo. A tehdy počal bys s hanbou na posledním místě seděti.'),
(1571824,54,42,14,10,'Ale když bys byl pozván, jda, posaď se na posledním místě. A kdyby přišel ten, kterýž tebe pozval, aby řekl tobě: Příteli, posedni výše, tedy budeš míti chválu před spolustolícími.'),
(1571825,54,42,14,11,'Nebo každý, kdož se povyšuje, bude ponížen; a kdož se ponižuje, bude povýšen.'),
(1571826,54,42,14,12,'Pravil také i tomu, kterýž ho byl pozval: Když činíš oběd nebo večeři, nezov přátel svých, ani bratří svých, ani sousedů bohatých, ať by snad i oni zase nezvali tebe, a měl bys odplatu.'),
(1571827,54,42,14,13,'Ale když činíš hody, povolej chudých, chromých, kulhavých, slepých,'),
(1571828,54,42,14,14,'A blahoslavený budeš. Neboť nemají, odkud by odplatili tobě, ale budeť odplaceno při vzkříšení spravedlivých.'),
(1571829,54,42,14,15,'I uslyšav to jeden z přísedících, řekl jemu: Blahoslavený jest, kdož jí chléb v království Božím.'),
(1571830,54,42,14,16,'On pak řekl jemu: Člověk jeden učinil večeři velikou, a pozval mnohých.'),
(1571831,54,42,14,17,'I poslal služebníka svého v hodinu večeře, aby řekl pozvaným: Pojďte, nebo již připraveno jest všecko.'),
(1571832,54,42,14,18,'I počali se všickni spolu vymlouvati. První řekl jemu: Ves jsem koupil, a musím vyjíti a ohledati jí; prosím tebe, vymluv mne.'),
(1571833,54,42,14,19,'A druhý řekl: Patero spřežení volů koupil jsem, a jdu, abych jich zkusil; prosím tebe, vymluv mne.'),
(1571834,54,42,14,20,'A jiný dí: Ženu jsem pojal, a protož nemohu přijíti.'),
(1571835,54,42,14,21,'I navrátiv se služebník, zvěstoval tyto věci pánu svému. Tedy rozhněvav se hospodář, řekl služebníku svému: Vyjdi rychle na rynky a na ulice města, a chudé, i chromé, i kulhavé, a slepé uveď sem.'),
(1571836,54,42,14,22,'I řekl služebník: Pane, stalo se, jakož jsi rozkázal, a ještěť místo jest.'),
(1571837,54,42,14,23,'Tedy řekl pán služebníku: Vyjdiž na cesty a mezi ploty, a přinuť vjíti, ať se naplní dům můj.'),
(1571838,54,42,14,24,'Nebo pravímť vám, že žádný z mužů těch, kteříž pozváni byli, neokusí večeře mé.'),
(1571839,54,42,14,25,'Šli pak mnozí zástupové s ním. A on obrátiv se, řekl jim:'),
(1571840,54,42,14,26,'Jde-li kdo ke mně, a nemá-li v nenávisti otce svého, i mateře, i ženy, i dětí, i bratří, i sestr, ano i té duše své, nemůž býti mým učedlníkem.'),
(1571841,54,42,14,27,'A kdožkoli nenese kříže svého, a jde za mnou, nemůž býti mým učedlníkem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571842,54,42,14,28,'Nebo kdo z vás jest, chtěje stavěti věži, aby prve sedna, nepočetl nákladu, bude-li míti dosti k dokonání toho díla?'),
(1571843,54,42,14,29,'Aby snad, když by položil grunt, a nemohl dokonati, nepřišlo na to, že všickni to vidouce, počali by se jemu posmívati,'),
(1571844,54,42,14,30,'Řkouce: Tento člověk počal stavěti, a nemohl dokonati.'),
(1571845,54,42,14,31,'Anebo který král bera se k boji proti jinému králi, zdaliž prve nesedne, aby se poradil, mohl-li by s desíti tisíci potkati se s tím, kterýž s dvadcíti tisíci táhne proti němu?'),
(1571846,54,42,14,32,'Sic jinak, když ještě podál od něho jest, pošle posly k němu, žádaje toho, což by bylo ku pokoji.'),
(1571847,54,42,14,33,'Tak zajisté každý z vás, kdož se neodřekne všech věcí, kterýmiž vládne, nemůž býti mým učedlníkem.'),
(1571848,54,42,14,34,'Dobráť jest sůl. Pakli sůl bude zmařena, čím bude napravena?'),
(1571849,54,42,14,35,'Ani do země, ani do hnoje se nehodí; ale vyvržena bude ven. Kdo má uši k slyšení, slyš.'),
(1571850,54,42,15,1,'Přibližovali se pak k němu všickni publikáni a hříšníci, aby ho slyšeli.'),
(1571851,54,42,15,2,'I reptali farizeové a zákoníci, řkouce: Tento hříšníky přijímá a jí s nimi.'),
(1571852,54,42,15,3,'I pověděl jim podobenství toto, řka:'),
(1571853,54,42,15,4,'Kdyby někdo z vás měl sto ovec, a ztratil by jednu z nich, zdaliž by nenechal devadesáti devíti na poušti, a nešel k té, kteráž zahynula, až by i nalezl ji?'),
(1571854,54,42,15,5,'A nalezna, jistě by ji vložil na ramena svá s radostí.'),
(1571855,54,42,15,6,'A přijda domů, svolal by přátely a sousedy, řka jim: Spolu radujte se se mnou, neb jsem nalezl ovci svou, kteráž byla zahynula.'),
(1571856,54,42,15,7,'Pravímť vám, že tak jest radost v nebi nad jedním hříšníkem pokání činícím větší, nežli nad devadesáti devíti spravedlivými, kteříž nepotřebují pokání.'),
(1571857,54,42,15,8,'Aneb žena některá mající grošů deset, ztratila-li by jeden groš, zdaliž nezažže svíce, a nemete domu, a nehledá pilně, dokudž nenalezne?'),
(1571858,54,42,15,9,'A když nalezne, svolá přítelkyně a sousedy, řkuci: Spolu radujte se se mnou, neb jsem nalezla groš, kterýž jsem byla ztratila.'),
(1571859,54,42,15,10,'Takť pravím vám, že jest radost před anděly Božími nad jedním hříšníkem pokání činícím.'),
(1571860,54,42,15,11,'Řekl také Ježíš: Člověk jeden měl dva syny.'),
(1571861,54,42,15,12,'Z nichž mladší řekl otci: Otče, dej mi díl statku, kterýž mně náleží. I rozdělil jim statek.'),
(1571862,54,42,15,13,'A po nemnohých dnech, shromáždiv sobě všecko mladší syn, odšel do daleké krajiny, a tam rozmrhal statek svůj, živ jsa prostopášně.'),
(1571863,54,42,15,14,'A když všecko utratil, stal se hlad veliký v krajině té, a on počal nouzi trpěti.'),
(1571864,54,42,15,15,'I všed, přídržel se jednoho měštěnína krajiny té; a on jej poslal do vsi své, aby pásl vepře.'),
(1571865,54,42,15,16,'I žádal nasytiti břicho své mlátem, kteréž svině jedly, a žádný nedával jemu.'),
(1571866,54,42,15,17,'On pak přišed sám k sobě, řekl: Aj, jak mnozí čeledínové u otce mého hojnost mají chleba, a já tuto hladem mru!'),
(1571867,54,42,15,18,'Vstana, půjdu k otci svému, a dím jemu: Otče, zhřešil jsem proti nebi a před tebou,'),
(1571868,54,42,15,19,'A již více nejsem hoden slouti syn tvůj. Ale učiň mne jako jednoho z čeledínů svých.'),
(1571869,54,42,15,20,'I vstav, šel k otci svému. A když ještě opodál byl, uzřel jej otec jeho, a milosrdenstvím hnut jsa, přiběh, padl na šíji jeho, a políbil ho.'),
(1571870,54,42,15,21,'I řekl jemu syn: Otče, zhřešil jsem proti nebi a před tebou, a jižť nejsem hoden slouti syn tvůj.'),
(1571871,54,42,15,22,'I řekl otec služebníkům svým: Přineste roucho to první, a oblecte jej, a dejte prsten na ruku jeho a obuv na nohy.'),
(1571872,54,42,15,23,'A přivedouce tele tučné, zabijte, a hodujíce, buďme veseli.'),
(1571873,54,42,15,24,'Nebo tento syn můj byl umřel, a zase ožil; byl zahynul, a nalezen jest. I počali veseli býti.'),
(1571874,54,42,15,25,'Byl pak syn jeho starší na poli. A jda, když se přibližoval k domu, uslyšel zpívání a hluk veselících se.'),
(1571875,54,42,15,26,'I povolav jednoho z služebníků svých, otázal se ho, co by to bylo.'),
(1571876,54,42,15,27,'A on řekl jemu: Bratr tvůj přišel, i zabil otec tvůj tučné tele, že ho zdravého přijal.'),
(1571877,54,42,15,28,'I rozhněval se on, a nechtěl tam vjíti. Otec pak jeho vyšed, prosil ho.'),
(1571878,54,42,15,29,'A on odpověděv, řekl otci: Aj, tolik let sloužím tobě, a nikdy jsem přikázání tvého nepřestoupil, avšak nikdy jsi mi nedal ani kozelce, abych také s přáteli svými vesel pobyl.'),
(1571879,54,42,15,30,'Ale když syn tvůj tento, kterýž prožral statek tvůj s nevěstkami, přišel, zabils jemu tele tučné.'),
(1571880,54,42,15,31,'A on řekl mu: Synu, ty vždycky se mnou jsi, a všecky věci mé jsou tvé.'),
(1571881,54,42,15,32,'Ale hodovati a radovati se náleželo. Nebo bratr tvůj tento byl umřel, a zase ožil; zahynul byl, a nalezen jest.'),
(1571882,54,42,16,1,'Pravil pak i k učedlníkům svým: Člověk jeden byl bohatý, kterýž měl šafáře; a ten obžalován jest před ním, jako by mrhal statek jeho.'),
(1571883,54,42,16,2,'I povolav ho, řekl jemu: Což to slyším o tobě? Vydej počet z vladařství svého, neb již nebudeš moci déle vládnouti.'),
(1571884,54,42,16,3,'I dí vladař sám v sobě: Co učiním? Teď pán můj odjímá ode mne vladařství. Kopati nemohu, žebrati se stydím.'),
(1571885,54,42,16,4,'Vím, co učiním, aby, když budu zbaven vladařství, přijali mne do svých domů.'),
(1571886,54,42,16,5,'I zavolav jednoho každého dlužníka pána svého, řekl prvnímu: Jaks mnoho dlužen pánu mému?'),
(1571887,54,42,16,6,'A on řekl: Sto tun oleje. I řekl mu: Vezmi rejistra svá, a sedna rychle, napiš padesát.'),
(1571888,54,42,16,7,'Potom druhému řekl: Ty pak jaks mnoho dlužen? Kterýž řekl: Sto korců pšenice. I dí mu: Vezmi rejistra svá, a napiš osmdesát.'),
(1571889,54,42,16,8,'I pochválil pán vladaře nepravého, že sobě opatrně učinil. Nebo synové tohoto světa opatrnější jsou, nežli synové světla v svých věcech.'),
(1571890,54,42,16,9,'I jáť pravím vám: Čiňte sobě přátely z mamony nepravosti, aby, když byste zhynuli, přijali vás do věčných stanů.'),
(1571891,54,42,16,10,'Kdožť jest věrný v mále, i ve mnozeť věrný bude. A kdož v mále jest nepravý, i ve mnozeť nepravý jest.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571892,54,42,16,11,'Poněvadž tedy v mamoně nepravé věrní jste nebyli, spravedlivého zboží kdo vám svěří?'),
(1571893,54,42,16,12,'A když jste v cizím věrní nebyli, což vašeho jest, kdo vám dá?'),
(1571894,54,42,16,13,'Nižádný služebník nemůž dvěma pánům sloužiti. Nebť zajisté jednoho nenáviděti bude, a druhého milovati, aneb jednoho přídržeti se bude, a druhým pohrdne. Nemůžte Bohu sloužiti a mamoně.'),
(1571895,54,42,16,14,'Slyšeli pak toto všecko i farizeové, kteříž byli lakomí, a posmívali se jemu.'),
(1571896,54,42,16,15,'I dí jim: Vy jste, ješto se sami spravedliví činíte před lidmi, ale Bůhť zná srdce vaše; nebo což jest u lidí vysokého, ohavnost jest před Bohem.'),
(1571897,54,42,16,16,'Zákon a Proroci až do Jana, a od té chvíle království Boží zvěstuje se, a každý se do něho násilně tiskne.'),
(1571898,54,42,16,17,'Snázeť jest zajisté nebi a zemi pominouti, nežli v Zákoně jednomu tytlíku zahynouti.'),
(1571899,54,42,16,18,'Každý, kdož propustí manželku svou, a jinou pojímá, cizoloží; a kdož propuštěnou od muže pojímá, cizoloží.'),
(1571900,54,42,16,19,'Byl pak člověk jeden bohatý, a obláčel se v šarlat a v kment, a hodoval na každý den stkvostně.'),
(1571901,54,42,16,20,'A byl také jeden žebrák, jménem Lazar, kterýžto ležel u vrat jeho vředovitý,'),
(1571902,54,42,16,21,'Žádaje nasycen býti z drobtů, kteříž padali z stolu bohatce. Ale i psi přicházejíce, lízali vředy jeho.'),
(1571903,54,42,16,22,'I stalo se, že ten žebrák umřel, a nesen jest od andělů do lůna Abrahamova. Umřel pak i bohatec, a pohřben jest.'),
(1571904,54,42,16,23,'Potom v pekle pozdvih očí svých, v mukách jsa, uzřel Abrahama zdaleka, a Lazara v lůnu jeho.'),
(1571905,54,42,16,24,'I zvolav bohatec, řekl: Otče Abrahame, smiluj se nade mnou, a pošli Lazara, ať omočí konec prstu svého v vodě, a svlaží jazyk můj; nebo se mučím v tomto plameni.'),
(1571906,54,42,16,25,'I řekl mu Abraham: Synu, rozpomeň se, žes ty již vzal dobré věci své v životě svém, a Lazar též zlé. Nyní pak tento se již těší, ale ty se mučíš.'),
(1571907,54,42,16,26,'A nadto nade všecko mezi námi a vámi propast veliká utvrzena jest, aby ti, kteříž chtí odsud k vám jíti, nemohli, ani odonud k nám přijíti.'),
(1571908,54,42,16,27,'I řekl: Ale prosím tebe, Otče, abys ho poslal do domu otce mého.'),
(1571909,54,42,16,28,'Neboť mám pět bratrů. Ať jim svědčí, aby i oni nepřišli do tohoto místa muk.'),
(1571910,54,42,16,29,'I řekl jemu Abraham: Majíť Mojžíše a Proroky, nechť jich poslouchají.'),
(1571911,54,42,16,30,'A on řekl: Nic, otče Abrahame, ale kdyby kdo z mrtvých šel k nim, budou pokání činiti.'),
(1571912,54,42,16,31,'I řekl mu: Poněvadž Mojžíše a Proroků neposlouchají, aniž byť kdo z mrtvých vstal, uvěří jemu.'),
(1571913,54,42,17,1,'Tedy řekl učedlníkům: Není možné, aby nepřišla pohoršení, ale běda tomu, skrze kohož přicházejí.'),
(1571914,54,42,17,2,'Lépe by mu bylo, aby žernov osličí vložen byl na hrdlo jeho, a uvržen byl do moře, nežli by pohoršil jednoho z těchto maličkých.'),
(1571915,54,42,17,3,'Šetřte se. Zhřešil-li by pak proti tobě bratr tvůj, potresci ho, a bude-liť toho želeti, odpusť mu.'),
(1571916,54,42,17,4,'A byť pak sedmkrát za den zhřešil proti tobě, a sedmkrát za den obrátil se k tobě, řka: Žel mi toho, odpusť mu.'),
(1571917,54,42,17,5,'I řekli apoštolé Pánu: Přispoř nám víry.'),
(1571918,54,42,17,6,'I dí Pán: Kdybyste měli víru jako zrno horčičné, řekli byste této moruši: Vykořeň se a přesaď se do moře, a uposlechla by vás.'),
(1571919,54,42,17,7,'Nebo kdo jest z vás, maje služebníka, ješto oře aneb pase dobytek, aby jemu, když by se s pole navrátil, hned řekl: Pojď a seď za stůl?'),
(1571920,54,42,17,8,'Ale zdali raději nedí jemu: Připrav, ať povečeřím, a opáše se, služ mi, až se najím a napím, a potom i ty jez a pij?'),
(1571921,54,42,17,9,'Zdali děkuje služebníku tomu, že učinil to, což mu rozkázal? Nezdá mi se.'),
(1571922,54,42,17,10,'Tak i vy, když učiníte všecko, což vám přikázáno, rcete: Služebníci neužiteční jsme. Což jsme povinni byli učiniti, učinili jsme.'),
(1571923,54,42,17,11,'I stalo se, když se bral do Jeruzaléma, že šel skrze Samaří a Galilei.'),
(1571924,54,42,17,12,'A když vcházel do jednoho městečka, potkalo se s ním deset mužů malomocných, kteřížto stáli zdaleka.'),
(1571925,54,42,17,13,'A pozdvihše hlasu, řekli: Ježíši přikazateli, smiluj se nad námi.'),
(1571926,54,42,17,14,'Kteréžto on uzřev, řekl jim: Jdouce, ukažte se kněžím. I stalo se, když šli, že očištěni jsou.'),
(1571927,54,42,17,15,'Jeden pak z nich uzřev, že jest uzdraven, navrátil se s velikým hlasem, velebě Boha.'),
(1571928,54,42,17,16,'A padl na tvář k nohám jeho, díky čině jemu. A ten byl Samaritán.'),
(1571929,54,42,17,17,'I odpověděv Ježíš, řekl: Zdaliž jich deset není očištěno? A kdež jest jich devět?'),
(1571930,54,42,17,18,'Nenalezli se k tomu, aby přijdouce, chválu Bohu vzdali, jediné cizozemec tento?'),
(1571931,54,42,17,19,'I řekl jemu: Vstana, jdi, víra tvá tě uzdravila.'),
(1571932,54,42,17,20,'Otázán pak jsa od zákoníků, kdy přijde království Boží, odpověděl jim a řekl: Nepřijdeť království Boží patrně.'),
(1571933,54,42,17,21,'Aniž řeknou: Aj, tuto, aneb aj, tamto. Nebo aj, království Boží jestiť mezi vámi.'),
(1571934,54,42,17,22,'I řekl učedlníkům: Přijdou dnové, že budete žádati viděti jeden den Syna člověka, a neuzříte.'),
(1571935,54,42,17,23,'A dějíť vám: Aj, zde, hle, tamto. Nechoďte, ani následujte.'),
(1571936,54,42,17,24,'Nebo jakožto blesk blýskající se z jedné krajiny, kteráž pod nebem jest, až do druhé, kteráž též pod nebem jest, svítí, tak bude i Syn člověka ve dni svém.'),
(1571937,54,42,17,25,'Ale nejprve musí mnoho trpěti, a potupen býti od národu tohoto.'),
(1571938,54,42,17,26,'A jakož se dálo za dnů Noé, tak bude i za dnů Syna člověka.'),
(1571939,54,42,17,27,'Jedli, pili, ženili se, vdávaly se až do toho dne, v kterémžto Noé všel do korábu; i přišla potopa, a zahladila všecky.'),
(1571940,54,42,17,28,'A též podobně, jako se stalo ve dnech Lotových: Jedli, pili, kupovali, prodávali, štěpovali, stavěli.'),
(1571941,54,42,17,29,'Ale dne toho, když vyšel Lot z Sodomy, pršel oheň s sirou s nebe, a zahladil všecky.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571942,54,42,17,30,'Takť nápodobně bude v ten den, když se Syn člověka zjeví.'),
(1571943,54,42,17,31,'V ten čas kdo by byl na střeše, a nádobí jeho v domu, nesstupuj, aby je pobral; a kdo na poli, též nevracuj se zase.'),
(1571944,54,42,17,32,'Pomněte na Lotovu ženu.'),
(1571945,54,42,17,33,'Nebo kdož by koli hledal život svůj zachovati, ztratíť jej; a kdož by jej koli ztratil, obživíť jej.'),
(1571946,54,42,17,34,'Pravímť vám: V tu noc budou dva na loži jednom; jeden bude vzat, a druhý opuštěn.'),
(1571947,54,42,17,35,'Dvě budou mleti spolu; jedna bude vzata, a druhá opuštěna.'),
(1571948,54,42,17,36,'Dva budou na poli; jeden bude vzat, a druhý opuštěn.'),
(1571949,54,42,17,37,'I odpověděvše, řekli jemu: Kde, Pane? On pak řekl jim: Kdežť bude tělo, tamť se shromáždí i orlice.'),
(1571950,54,42,18,1,'Pověděl jim také i podobenství, kterak by potřebí bylo vždycky se modliti a neoblevovati,'),
(1571951,54,42,18,2,'Řka: Byl jeden soudce v městě jednom, kterýž se Boha nebál a člověka nestyděl.'),
(1571952,54,42,18,3,'Byla pak vdova jedna v témž městě. I přišla k němu, řkuci: Pomsti mne nad protivníkem mým.'),
(1571953,54,42,18,4,'A on nechtěl za dlouhý čas. Ale potom řekl sám v sobě: Ač se Boha nebojím, a člověka nestydím,'),
(1571954,54,42,18,5,'Však že mi pokoje nedá tato vdova, pomstím jí, aby naposledy přijduci, neuhaněla mne.'),
(1571955,54,42,18,6,'I dí Pán: Slyšte, co praví soudce nepravý.'),
(1571956,54,42,18,7,'A což by pak Bůh nepomstil volených svých, volajících k němu dnem i nocí, ačkoli i prodlévá jim?'),
(1571957,54,42,18,8,'Pravímť vám, žeť jich brzo pomstí. Ale když přijde Syn člověka, zdaliž nalezne víru na zemi?'),
(1571958,54,42,18,9,'I řekl také k některým, kteříž v sebe doufali, že by spravedliví byli, jiných sobě za nic nevážíce, podobenství toto:'),
(1571959,54,42,18,10,'Dva muži vstupovali do chrámu, aby se modlili, jeden farizeus a druhý publikán.'),
(1571960,54,42,18,11,'Farizeus stoje soukromí, takto se modlil: Bože, děkuji tobě, že nejsem jako jiní lidé, dráči, nespravedliví, cizoložníci, aneb jako i tento publikán.'),
(1571961,54,42,18,12,'Postím se dvakrát do téhodne, desátky dávám ze všech věcí, kterýmiž vládnu.'),
(1571962,54,42,18,13,'Publikán pak zdaleka stoje, nechtěl ani očí k nebi pozdvihnouti, ale bil se v prsy své, řka: Bože, buď milostiv mně hříšnému.'),
(1571963,54,42,18,14,'Pravímť vám: Odšel tento, ospravedlněn jsa, do domu svého, a ne onen. Nebo každý, kdož se povyšuje, bude ponížen; a kdož se ponižuje, bude povýšen.'),
(1571964,54,42,18,15,'Přinášeli také k němu i nemluvňátka, aby se jich dotýkal. To viděvše učedlníci, přimlouvali jim.'),
(1571965,54,42,18,16,'Ale Ježíš svolav je, řekl: Nechte dítek, ať jdou ke mně, a nebraňte jim, nebo takovýchť jest království Boží.'),
(1571966,54,42,18,17,'Amen pravím vám: Kdož by koli nepřijal království Božího jako dítě, nevejdeť do něho.'),
(1571967,54,42,18,18,'I otázalo se ho jedno kníže, řka: Mistře dobrý, co čině, život věčný obdržím?'),
(1571968,54,42,18,19,'I řekl jemu Ježíš: Co mne nazýváš dobrým? Žádný není dobrý, než sám toliko Bůh.'),
(1571969,54,42,18,20,'Však umíš přikázání: Nezcizoložíš, nezabiješ, nepokradeš, nepromluvíš křivého svědectví, cti otce svého i matku svou.'),
(1571970,54,42,18,21,'On pak řekl: Toho všeho ostříhal jsem od své mladosti.'),
(1571971,54,42,18,22,'Slyšav to Ježíš, řekl mu: Ještěť se jednoho nedostává. Všecko, což máš, prodej, a rozdej chudým, a budeš míti poklad v nebi, a pojď, následuj mne.'),
(1571972,54,42,18,23,'On pak uslyšav to, zarmoutil se; byl zajisté bohatý velmi.'),
(1571973,54,42,18,24,'A viděv jej Ježíš zarmouceného, řekl: Aj, jak nesnadně ti, kdož statky mají, do království Božího vejdou!'),
(1571974,54,42,18,25,'Snáze jest zajisté velbloudu skrze jehelnou dírku projíti, nežli bohatému vjíti do království Božího.'),
(1571975,54,42,18,26,'Tedy řekli ti, kteříž to slyšeli: I kdož může spasen býti?'),
(1571976,54,42,18,27,'A on dí jim: Což jest nemožného u lidí, možné jest u Boha.'),
(1571977,54,42,18,28,'I řekl Petr: Aj, my opustili jsme všecko, a šli jsme za tebou.'),
(1571978,54,42,18,29,'On pak řekl jim: Amen pravím vám, že není žádného, kterýž by opustil dům, neb rodiče, neb bratří, neb manželku, nebo dítky, pro království Boží,'),
(1571979,54,42,18,30,'Aby nevzal v tomto času mnohem více, v budoucím pak věku míti bude život věčný.'),
(1571980,54,42,18,31,'Tedy pojav Ježíš dvanácte, řekl jim: Aj, vstupujeme do Jeruzaléma, a naplníť se všecko to, což psáno jest skrze Proroky o Synu člověka.'),
(1571981,54,42,18,32,'Nebo vydán bude pohanům, a bude posmíván, a zlehčen i uplván.'),
(1571982,54,42,18,33,'A ubičujíce, zamordují jej, ale on třetího dne z mrtvých vstane.'),
(1571983,54,42,18,34,'Oni pak tomu nic nerozuměli, a bylo slovo to skryto před nimi, aniž věděli, co se pravilo.'),
(1571984,54,42,18,35,'I stalo se, když se přibližoval k Jericho, slepý jeden seděl podle cesty, žebře.'),
(1571985,54,42,18,36,'A slyšev zástup pomíjející, otázal se, co by to bylo?'),
(1571986,54,42,18,37,'I oznámili jemu, že Ježíš Nazaretský tudy jde.'),
(1571987,54,42,18,38,'I zvolal, řka: Ježíši, synu Davidův, smiluj se nade mnou!'),
(1571988,54,42,18,39,'A ti, kteříž napřed šli, přimlouvali mu, aby mlčal. Ale on mnohem více volal: Synu Davidův, smiluj se nade mnou!'),
(1571989,54,42,18,40,'Tedy zastaviv se Ježíš, rozkázal ho k sobě přivésti. A když se přibližoval, otázal se ho,'),
(1571990,54,42,18,41,'Řka: Co chceš, ať tobě učiním? On pak dí: Pane, ať vidím.'),
(1571991,54,42,18,42,'A Ježíš řekl jemu: Prohlédni. Víra tvá tě uzdravila.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1571992,54,42,18,43,'A ihned prohlédl, a šel za ním, velebě Boha. A všecken lid viděv to, vzdal chválu Bohu.'),
(1571993,54,42,19,1,'A všed Ježíš, bral se přes Jericho.'),
(1571994,54,42,19,2,'A aj, muž, jménem Zacheus, a ten byl hejtman nad celnými, a byl bohatý.'),
(1571995,54,42,19,3,'I žádostiv byl viděti Ježíše, kdo by byl; a nemohl pro zástup, nebo postavy malé byl.'),
(1571996,54,42,19,4,'A předběh napřed, vstoupil na strom planého fíku, aby jej viděl; neb tudy měl jíti.'),
(1571997,54,42,19,5,'A když přišel k tomu místu, pohleděv zhůru Ježíš, uzřel jej, i řekl jemu: Zachee, spěšně sstup dolů, nebo dnes v domu tvém musím zůstati.'),
(1571998,54,42,19,6,'I sstoupil rychle, a přijal jej radostně.'),
(1571999,54,42,19,7,'A viděvše to všickni, reptali, řkouce: K člověku hříšnému se obrátil.'),
(1572000,54,42,19,8,'Stoje pak Zacheus, řekl ku Pánu: Aj, polovici statku svého, Pane, dávám chudým, a oklamal-li jsem v čem koho, navracuji to čtvernásob.'),
(1572001,54,42,19,9,'I dí jemu Ježíš: Dnes spasení stalo se domu tomuto, protože i on jest syn Abrahamův.'),
(1572002,54,42,19,10,'Nebo přišel Syn člověka, aby hledal a spasil, což bylo zahynulo.'),
(1572003,54,42,19,11,'Toho když oni poslouchali, promluvil k nim dále podobenství, protože byl blízko od Jeruzaléma a že se oni domnívali, že by se hned mělo zjeviti království Boží.'),
(1572004,54,42,19,12,'I řekl: Člověk jeden rodu znamenitého odšel do daleké krajiny, aby přijal království a zase se navrátil.'),
(1572005,54,42,19,13,'I povolav desíti služebníků svých, dal jim deset hřiven, a řekl jim: Kupčtež, dokudž nepřijdu.'),
(1572006,54,42,19,14,'Měšťané pak jeho nenáviděli ho, a poslali poselství za ním, řkouce: Nechcemeť, aby tento kraloval nad námi.'),
(1572007,54,42,19,15,'I stalo se, když se navrátil, přijav království, rozkázal zavolati těch svých služebníků, kterýmž byl dal peníze, aby zvěděl, jak kdo mnoho získal.'),
(1572008,54,42,19,16,'I přišel první, řka: Pane, hřivna tvá deset hřiven získala.'),
(1572009,54,42,19,17,'I řekl jemu: To dobře, služebníče dobrý. Že jsi nad málem byl věrný, mějž moc nad desíti městy.'),
(1572010,54,42,19,18,'A druhý přišel, řka: Pane, hřivna tvá získala pět hřiven.'),
(1572011,54,42,19,19,'I tomu řekl: I ty budiž nad pěti městy.'),
(1572012,54,42,19,20,'A jiný přišel, řka: Pane, aj, teď hřivna tvá, kterouž jsem měl složenou v šátku.'),
(1572013,54,42,19,21,'Nebo jsem se bál tebe, ješto jsi člověk přísný; béřeš, čeho jsi nepoložil, a žneš, čeho jsi nerozsíval.'),
(1572014,54,42,19,22,'I řekl jemu: Z úst tvých soudím tebe, služebníče zlý. Věděl jsi, že jsem já člověk přísný, bera, což jsem nepoložil, a žna, čehož jsem nerozsíval.'),
(1572015,54,42,19,23,'I pročes tedy nedal peněz mých na stůl, a já přijda, byl bych je vzal i s požitky?'),
(1572016,54,42,19,24,'I řekl těm, kteříž tu stáli: Vezměte od něho hřivnu, a dejte tomu, kterýž má deset hřiven.'),
(1572017,54,42,19,25,'I řekli jemu: Pane, máť deset hřiven.'),
(1572018,54,42,19,26,'I dí jim: Jistě pravím vám, že každému, kdož má, bude dáno, ale od toho, kterýž nemá, i to, což má, bude odjato.'),
(1572019,54,42,19,27,'Ty pak nepřátely mé, kteříž nechtěli, abych nad nimi kraloval, přiveďte sem a zmordujte přede mnou.'),
(1572020,54,42,19,28,'To pověděv, šel předce, vstupuje k Jeruzalému.'),
(1572021,54,42,19,29,'I stalo se; když se přiblížil k Betfagi a k Betany, k hoře, kteráž slove Olivetská, poslal dva učedlníky své,'),
(1572022,54,42,19,30,'Řka: Jděte do městečka, kteréž proti vám jest. Do kteréhožto vejdouce, naleznete oslátko přivázané, na němžto nikdy žádný z lidí neseděl. Odvěžtež je, a přiveďte ke mně.'),
(1572023,54,42,19,31,'A optal-liť by se vás kdo, proč je odvazujete, tak jemu díte: Protože Pán ho potřebuje.'),
(1572024,54,42,19,32,'Tedy odšedše ti, kteříž byli posláni, nalezli tak, jakž jim byl pověděl.'),
(1572025,54,42,19,33,'A když odvazovali oslátko, řekli páni jeho k nim: Proč odvazujete oslátko?'),
(1572026,54,42,19,34,'A oni řekli: Pán ho potřebuje.'),
(1572027,54,42,19,35,'I přivedli je k Ježíšovi, a vloživše roucha svá na oslátko, vsadili na ně Ježíše.'),
(1572028,54,42,19,36,'A když on jel, stlali roucha svá na cestě.'),
(1572029,54,42,19,37,'Když se pak již přibližoval k místu tomu, kudyž scházejí s hory Olivetské, počalo všecko množství učedlníků radostně chváliti Boha hlasem velikým ze všech divů, kteréž byli viděli,'),
(1572030,54,42,19,38,'Řkouce: Požehnaný král, jenž se béře ve jménu Páně. Pokoj na nebi, a sláva na výsostech.'),
(1572031,54,42,19,39,'Ale někteří z farizeů, kteříž tu byli v zástupu, řekli k němu: Mistře, potresci učedlníků svých.'),
(1572032,54,42,19,40,'I odpověděv, řekl jim: Pravímť vám: Budou-li tito mlčeti, kameníť bude volati.'),
(1572033,54,42,19,41,'A když se přiblížil, uzřev město, plakal nad ním,'),
(1572034,54,42,19,42,'Řka: Ó kdybys poznalo i ty, a to aspoň v takový tento den tvůj, které by věci ku pokoji tobě byly; ale skrytoť jest to nyní od očí tvých.'),
(1572035,54,42,19,43,'Nebo přijdou na tě dnové, v nichž obklíčí tě nepřátelé tvoji valem, a oblehnou tebe, a ssouží tě se všech stran.'),
(1572036,54,42,19,44,'A s zemí srovnají tě, i syny tvé, kteříž v tobě jsou, a nenechajíť v tobě kamene na kameni, protože jsi nepoznalo času navštívení svého.'),
(1572037,54,42,19,45,'A všed do chrámu, počal vymítati prodavače a kupce z něho,'),
(1572038,54,42,19,46,'Řka jim: Psáno jest: Dům můj dům modlitby jest, vy jste jej pak učinili peleší lotrovskou.'),
(1572039,54,42,19,47,'I učil na každý den v chrámě. Přední pak kněží a zákoníci i přední v lidu hledali ho zahladiti.'),
(1572040,54,42,19,48,'A nenalezli, co by jemu učinili. Nebo všecken lid jej sobě liboval, poslouchaje ho.'),
(1572041,54,42,20,1,'I stalo se v jeden den, když on učil lid v chrámě a kázal evangelium, že přišli k tomu přední kněží a zákoníci s staršími,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572042,54,42,20,2,'I řekli jemu: Pověz nám, jakou mocí tyto věci činíš, aneb kdo tobě tuto moc dal?'),
(1572043,54,42,20,3,'I odpověděv, řekl jim: Otížiť se i já vás o jedné věci a odpověztež mi:'),
(1572044,54,42,20,4,'Křest Janův s nebe-li byl, čili z lidí?'),
(1572045,54,42,20,5,'Oni pak uvažovali to mezi sebou, řkouce: Jestliže bychom řekli: S nebe, díť nám: Pročež jste tedy neuvěřili jemu?'),
(1572046,54,42,20,6,'Pakli díme: Z lidí, lid všecken ukamenuje nás; neb oni cele tak drží, že Jan jest prorok.'),
(1572047,54,42,20,7,'I odpověděli: Že nevědí, odkud jest byl.'),
(1572048,54,42,20,8,'I řekl jim Ježíš: Aniž já vám povím, jakou mocí toto činím.'),
(1572049,54,42,20,9,'I počal lidu praviti podobenství toto: Člověk jeden štípil vinici, a pronajal ji vinařům, a sám odšed podál byl tam za mnohé časy.'),
(1572050,54,42,20,10,'A v čas slušný poslal k vinařům služebníka, aby z ovoce vinice dali jemu. Vinaři pak zmrskavše jej, pustili ho prázdného.'),
(1572051,54,42,20,11,'A on poslal druhého služebníka. Oni pak i toho zmrskavše a zohavivše, pustili prázdného.'),
(1572052,54,42,20,12,'I poslal třetího. Ale oni i toho zranivše, vystrčili ven.'),
(1572053,54,42,20,13,'Tedy řekl Pán vinice: Co učiním? Pošli svého milého Syna. Snad když toho uzří, ostýchati se budou.'),
(1572054,54,42,20,14,'Uzřevše pak vinaři, rozmlouvali mezi sebou, řkouce: Tentoť jest dědic; pojďte, zabijme jej, aby naše bylo dědictví.'),
(1572055,54,42,20,15,'A vystrčivše jej ven z vinice, zamordovali ho. Což tedy učiní jim Pán vinice?'),
(1572056,54,42,20,16,'Přijde a vyhladí vinaře ty, a dá vinici jiným. To uslyšavše, řekli: Odstup to.'),
(1572057,54,42,20,17,'A on pohleděv na ně, řekl: Co jest pak to, což napsáno jest: Kámen, kterýmž pohrdli dělníci, ten učiněn jest v hlavu úhelní.'),
(1572058,54,42,20,18,'Každý, kdož padne na ten kámen, rozrazí se; a na kohož by on upadl, potřeť jej.'),
(1572059,54,42,20,19,'I hledali přední kněží a zákoníci, jak by naň vztáhli ruce v tu hodinu, ale báli se lidu. Nebo porozuměli, že by na ně mluvil podobenství to.'),
(1572060,54,42,20,20,'Tedy ukládajíce o něm, poslali špehéře, kteříž by se spravedlivými činili, aby ho polapili v řeči, a potom jej vydali vrchnosti a v moc hejtmanu.'),
(1572061,54,42,20,21,'I otázali se ho oni, řkouce: Mistře víme, že právě mluvíš a učíš, a nepřijímáš osoby, ale v pravdě cestě Boží učíš.'),
(1572062,54,42,20,22,'Sluší-li nám daň dávati císaři, čili nic?'),
(1572063,54,42,20,23,'Ale Ježíš rozuměje chytrosti jejich, dí jim: Co mne pokoušíte?'),
(1572064,54,42,20,24,'Ukažte mi peníz. Čí má obraz a nápis? I odpověděvše, řekli: Císařův.'),
(1572065,54,42,20,25,'On pak řekl jim: Dejtež tedy, co jest císařova, císaři, a což jest Božího, Bohu.'),
(1572066,54,42,20,26,'I nemohli ho za slovo popadnouti před lidem, a divíce se odpovědi jeho, umlkli.'),
(1572067,54,42,20,27,'Přistoupivše pak někteří z saduceů, (kteříž odpírají býti vzkříšení,) otázali se ho,'),
(1572068,54,42,20,28,'Řkouce: Mistře, Mojžíš napsal nám: Kdyby bratr něčí umřel, maje manželku, a umřel by bez dětí, aby ji pojal bratr jeho za manželku, a vzbudil símě bratru svému.'),
(1572069,54,42,20,29,'I bylo sedm bratří, a první pojav ženu, umřel bez dětí.'),
(1572070,54,42,20,30,'I pojal ji druhý, a umřel i ten bez dětí.'),
(1572071,54,42,20,31,'A třetí pojal ji, též i všech těch sedm, a nezůstavivše semene, zemřeli.'),
(1572072,54,42,20,32,'Nejposléze po všech umřela i žena.'),
(1572073,54,42,20,33,'Protož při vzkříšení kterého z nich bude manželka, poněvadž sedm jich mělo ji za manželku?'),
(1572074,54,42,20,34,'A odpovídaje, řekl jim Ježíš: Synové tohoto světa žení se a vdávají.'),
(1572075,54,42,20,35,'Ale ti, kteříž hodni jmíni budou dosáhnouti onoho věku a vzkříšení z mrtvých, ani se ženiti budou ani vdávati.'),
(1572076,54,42,20,36,'Nebo ani umírati více nebudou moci, andělům zajisté rovni budou. A jsou synové Boží, poněvadž jsou synové vzkříšení.'),
(1572077,54,42,20,37,'A že mrtví vstanou z mrtvých, i Mojžíš ukázal při onom kři, když nazývá Pána Bohem Abrahamovým a Bohem Izákovým a Bohem Jákobovým.'),
(1572078,54,42,20,38,'Bůhť pak není mrtvých, ale živých, nebo všickni jsou jemu živi.'),
(1572079,54,42,20,39,'Tedy odpověděvše někteří z zákoníků, řekli: Mistře, dobře jsi pověděl.'),
(1572080,54,42,20,40,'I neodvážili se jeho na nic více tázati.'),
(1572081,54,42,20,41,'On pak řekl jim: Kterak někteří praví Krista býti synem Davidovým?'),
(1572082,54,42,20,42,'A sám David praví v knihách Žalmových: Řekl Pán Pánu mému: Seď na pravici mé,'),
(1572083,54,42,20,43,'Ažť i položím nepřátely tvé v podnož noh tvých.'),
(1572084,54,42,20,44,'Poněvadž David jej Pánem nazývá, i kterakž syn jeho jest?'),
(1572085,54,42,20,45,'I řekl učedlníkům svým přede vším lidem:'),
(1572086,54,42,20,46,'Varujte se od zákoníků, kteříž rádi chodí v krásném rouše a milují pozdravování na trzích a přední stolice v školách a první místo na večeřích,'),
(1572087,54,42,20,47,'Kteříž zžírají domy vdovské pod zámyslem dlouhé modlitby. Tiť vezmou těžší odsouzení.'),
(1572088,54,42,21,1,'A pohleděv, uzřel lidi bohaté, kteříž metali dary své do pokladnice.'),
(1572089,54,42,21,2,'Uzřel pak i jednu vdovu chudičkou, ana uvrhla dva šarty.'),
(1572090,54,42,21,3,'I řekl: Vpravdě pravím vám, že vdova tato chudá více uvrhla nežli všickni jiní.'),
(1572091,54,42,21,4,'Nebo všickni tito z toho, což jim zbývalo, dali dary Bohu, tato pak z své chudoby všecku živnost svou, kterouž měla, uvrhla.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572092,54,42,21,5,'A když někteří pravili o chrámu, kterak by kamením pěkným i jinými okrasami ozdoben byl, řekl:'),
(1572093,54,42,21,6,'Načež se to díváte? Přijdouť dnové, v nichžto nebude zůstaven kámen na kameni, kterýž by nebyl zbořen.'),
(1572094,54,42,21,7,'I otázali se ho, řkouce: Mistře, kdy to bude? A které znamení, když se to bude míti státi?'),
(1572095,54,42,21,8,'On pak řekl: Vizte, abyste nebyli svedeni. Nebo mnozí přijdou ve jménu mém, řkouce: Že já jsem Kristus, a čas se blíží. Protož nepostupujte po nich.'),
(1572096,54,42,21,9,'Když pak uslyšíte o válkách a různicech, nestrachujte se; neboť musí to prve býti, ale ne ihned konec.'),
(1572097,54,42,21,10,'Tehdy pravil jim: Povstaneť národ proti národu, a království proti království.'),
(1572098,54,42,21,11,'A země třesení veliká budou po místech, a hladové, a morové, hrůzy i zázrakové s nebe velicí.'),
(1572099,54,42,21,12,'Ale před tím přede vším vztáhnou ruce své na vás, a protiviti se vám budou, vydávajíce vás do škol a žalářů, vodíce k králům a k vladařům pro jméno mé.'),
(1572100,54,42,21,13,'A toť se vám díti bude na svědectví.'),
(1572101,54,42,21,14,'Protož složtež to v srdcích vašich, abyste se nestarali, kterak byste odpovídati měli.'),
(1572102,54,42,21,15,'Jáť zajisté dám vám ústa a moudrost, kteréžto nebudou moci odolati, ani proti vám ostáti všickni protivníci vaši.'),
(1572103,54,42,21,16,'Budete pak zrazováni i od rodičů a od bratrů, od příbuzných i od přátel, a zmordují některé z vás.'),
(1572104,54,42,21,17,'A budete v nenávisti všechněm pro jméno mé.'),
(1572105,54,42,21,18,'Ale vlas s hlavy vaší nezahyne.'),
(1572106,54,42,21,19,'V trpělivosti vaší vládněte dušemi vašimi.'),
(1572107,54,42,21,20,'Když pak uzříte obležený od vojska Jeruzalém, tedy vězte, žeť se přiblížilo zkažení jeho.'),
(1572108,54,42,21,21,'A tehdy ti, kdož jsou v Judstvu, utíkejte k horám, a kdo uprostřed něho, vyjděte, a kteří v končinách, nevcházejte do něho.'),
(1572109,54,42,21,22,'Neboť budou dnové pomsty, aby se naplnilo všecko, což psáno jest.'),
(1572110,54,42,21,23,'Ale běda těhotným a těm, kteréž kojí v těch dnech. Neboť bude dav veliký v této zemi, a hněv Boží nad lidem tímto.'),
(1572111,54,42,21,24,'I padati budou ostrostí meče, a zjímaní vedeni budou mezi všecky národy, a Jeruzalém tlačen bude od pohanů, dokudž se nenaplní časové pohanů.'),
(1572112,54,42,21,25,'A budouť znamení na slunci a na měsíci i na hvězdách, a na zemi soužení národů, nevědoucích se kam díti, když zvuk vydá moře a vlnobití,'),
(1572113,54,42,21,26,'Takže zmrtvějí lidé pro strach a pro očekávání těch věcí, kteréž přijdou na všecken svět. Nebo moci nebeské pohybovati se budou.'),
(1572114,54,42,21,27,'A tehdyť uzří Syna člověka, an se béře v oblace s mocí a slavou velikou.'),
(1572115,54,42,21,28,'A když se toto počne díti, pohleďtež a pozdvihnětež hlav vašich,protože se přibližuje vykoupení vaše.'),
(1572116,54,42,21,29,'I pověděl jim podobenství: Patřte na fíkový strom i na všecka stromoví.'),
(1572117,54,42,21,30,'Když se již pučí, vidouce to, sami to znáte, že blízko jest léto.'),
(1572118,54,42,21,31,'Takž i vy, když uzříte, ano se tyto věci dějí, věztež, že blízko jest království Boží.'),
(1572119,54,42,21,32,'Amen pravím vám, že nepomine věk tento, ažť se toto všecko stane.'),
(1572120,54,42,21,33,'Nebe a země pominou, ale slova má nepominou.'),
(1572121,54,42,21,34,'Pilně se pak varujte, aby snad nebyla obtížena srdce vaše obžerstvím a opilstvím a pečováním o tento život, a vnáhle přikvačil by vás ten den.'),
(1572122,54,42,21,35,'Nebo jako osidlo přijde na všecky, jenž přebývají na tváři vší země.'),
(1572123,54,42,21,36,'Protož bděte všelikého času, modléce se, abyste hodni byli ujíti všech těch věcí, kteréž se budou díti, a postaviti se před Synem člověka.'),
(1572124,54,42,21,37,'I býval ve dne v chrámě, uče, ale v noci vycházeje, přebýval na hoře, kteráž slove Olivetská.'),
(1572125,54,42,21,38,'A všecken lid na úsvitě přicházel k němu do chrámu, aby ho poslouchal.'),
(1572126,54,42,22,1,'Přibližoval se pak svátek přesnic, jenž slove velikanoc.'),
(1572127,54,42,22,2,'I hledali přední kněží a zákoníci, kterak by jej vyhladili; ale obávali se lidu.'),
(1572128,54,42,22,3,'Tedy ďábel vstoupil do Jidáše, kterýž sloul Iškariotský, jednoho z počtu dvanácti.'),
(1572129,54,42,22,4,'A on odšed, mluvil s předními kněžími, a s úředníky nad chrámem, kterak by ho jim zradil.'),
(1572130,54,42,22,5,'I zradovali se, a smluvili s ním, že mu chtí peníze dáti.'),
(1572131,54,42,22,6,'A on také jim přiřekl. I hledal příhodného času, aby ho jim zradil bez zástupu.'),
(1572132,54,42,22,7,'Tedy přišel den přesnic, v kterémžto zabit měl býti beránek.'),
(1572133,54,42,22,8,'I poslal Ježíš Petra a Jana, řka: Jdouce, připravte nám beránka, abychom jedli.'),
(1572134,54,42,22,9,'A oni řekli mu: Kde chceš, ať připravíme?'),
(1572135,54,42,22,10,'On pak řekl k nim: Aj, když vcházeti budete do města, potkáť vás člověk, dčbán vody nesa. Jdětež za ním do domu, do kteréhož vejde.'),
(1572136,54,42,22,11,'A díte hospodáři toho domu: Vzkazuje tobě Mistr: Kde jest síň, kdežto budu jísti beránka s učedlníky svými?'),
(1572137,54,42,22,12,'A onť vám ukáže večeřadlo veliké podlážené. Tam připravte.'),
(1572138,54,42,22,13,'I odšedše, nalezli, jakž jim pověděl, a připravili beránka.'),
(1572139,54,42,22,14,'A když přišel čas večeře, posadil se za stůl, a dvanácte apoštolů s ním.'),
(1572140,54,42,22,15,'I řekl jim: Žádostí žádal jsem tohoto beránka jísti s vámi, prve než bych trpěl.'),
(1572141,54,42,22,16,'Nebo pravímť vám, žeť ho již více nebudu jísti, ažť se naplní v království Božím.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572142,54,42,22,17,'A vzav kalich, a díky činiv, řekl: Vezměte jej a dělte mezi sebou.'),
(1572143,54,42,22,18,'Neboť pravím vám, žeť nebudu píti z plodu vinného kořene, ažť království Boží přijde.'),
(1572144,54,42,22,19,'A vzav chléb, díky činiv, lámal a dal jim, řka: To jest tělo mé, kteréž se za vás dává. To čiňte na mou památku.'),
(1572145,54,42,22,20,'Takž také dal jim i kalich, když bylo po večeři, řka: Tento kalich jest nová smlouva v mé krvi, kteráž se za vás vylévá.'),
(1572146,54,42,22,21,'Ale aj, ruka zrádce mého se mnou jest za stolem.'),
(1572147,54,42,22,22,'A Syn zajisté člověka jde, tak jakž jest uloženo o něm, ale běda člověku tomu, kterýž ho zrazuje.'),
(1572148,54,42,22,23,'Tedy oni počali vyhledávati mezi sebou, kdo by z nich byl, kterýž by to měl učiniti.'),
(1572149,54,42,22,24,'Stal se pak i svár mezi nimi, kdo by z nich zdál se býti větší.'),
(1572150,54,42,22,25,'On pak řekl jim: Králové národů panují nad nimi, a kteříž moc mají nad nimi, dobrodincové slovou.'),
(1572151,54,42,22,26,'Ale vy ne tak. Nýbrž kdož větší jest mezi vámi, budiž jako nejmenší, a kdož vůdce jest, budiž jako sloužící.'),
(1572152,54,42,22,27,'Nebo kdo větší jest, ten-li, kterýž sedí, čili ten, kterýž slouží? Zdali ne ten, kterýž sedí? Ale já mezi vámi jsem jako ten, kterýž slouží.'),
(1572153,54,42,22,28,'Vy pak jste ti, kteříž jste v mých pokušeních se mnou zůstali.'),
(1572154,54,42,22,29,'A jáť vám způsobuji, jakož mi způsobil Otec můj, království,'),
(1572155,54,42,22,30,'Abyste jedli a pili za stolem mým v království mém, a seděli na stolicích, soudíce dvanáctero pokolení Izraelské.'),
(1572156,54,42,22,31,'I řekl Pán: Šimone, Šimone, aj, satan vyprosil vás, aby vás tříbil jako pšenici.'),
(1572157,54,42,22,32,'Ale jáť jsem prosil za tebe, aby nezhynula víra tvá. A ty někdy obrátě se, potvrzuj bratří svých.'),
(1572158,54,42,22,33,'A on řekl jemu: Pane, s tebou hotov jsem i do žaláře i na smrt jíti.'),
(1572159,54,42,22,34,'On pak dí: Pravím tobě, Petře, nezazpíváť dnes kohout, až prve třikrát zapříš, že neznáš mne.'),
(1572160,54,42,22,35,'I řekl jim: Když jsem vás posílal bez pytlíka, a bez mošny, a bez obuvi, zdali jste v čem nedostatek měli? A oni řekli: V ničemž.'),
(1572161,54,42,22,36,'Tedy dí jim: Ale nyní, kdo má pytlík, vezmi jej, a též i mošnu; a kdož nemá, prodej sukni svou, a kup sobě meč.'),
(1572162,54,42,22,37,'Nebo pravím vám, že se ještě to musí naplniti na mně, což psáno: A s nešlechetnými počten jest. Nebo ty věci, kteréž psány jsou o mně, konec berou.'),
(1572163,54,42,22,38,'Oni pak řekli: Pane, aj, dva meče teď. A on řekl jim: Dostiť jest.'),
(1572164,54,42,22,39,'A vyšed podle obyčeje svého, šel na horu Olivovou, a šli za ním i učedlníci jeho.'),
(1572165,54,42,22,40,'A když přišel na místo, řekl jim: Modlte se, abyste nevešli v pokušení.'),
(1572166,54,42,22,41,'A sám vzdáliv se od nich, jako by mohl kamenem dohoditi, a poklek na kolena, modlil se,'),
(1572167,54,42,22,42,'Řka: Otče, chceš-li, přenes kalich tento ode mne, ale však ne má vůle, ale tvá staň se.'),
(1572168,54,42,22,43,'I ukázal se jemu anděl s nebe, posiluje ho.'),
(1572169,54,42,22,44,'A jsa v boji, horlivěji se modlil. I učiněn jest pot jeho jako krůpě krve tekoucí na zemi.'),
(1572170,54,42,22,45,'A vstav od modlitby, a přišed k učedlníkům, nalezl je, ani spí zámutkem.'),
(1572171,54,42,22,46,'I řekl jim: Co spíte? Vstaňte a modlte se, abyste nevešli v pokušení.'),
(1572172,54,42,22,47,'A když on ještě mluvil, aj, zástup, a ten, kterýž sloul Jidáš, jeden ze dvanácti, šel napřed, a přiblížil se k Ježíšovi, aby jej políbil.'),
(1572173,54,42,22,48,'Ježíš pak řekl jemu: Jidáši, políbením Syna člověka zrazuješ?'),
(1572174,54,42,22,49,'A vidouce ti, kteříž při něm byli, k čemu se chýlí, řekli jemu: Pane, budeme-liž bíti mečem?'),
(1572175,54,42,22,50,'I udeřil jeden z nich služebníka nejvyššího kněze, a uťal ucho jeho pravé.'),
(1572176,54,42,22,51,'A Ježíš odpověděv, řekl: Nechtež až potud. A dotkna se ucha jeho, uzdravil jej.'),
(1572177,54,42,22,52,'I dí Ježíš těm, kteříž přišli k němu, předním kněžím a úředníkům chrámu a starším: Jako na lotra vyšli jste s meči a s kyjmi?'),
(1572178,54,42,22,53,'Ješto na každý den býval jsem s vámi v chrámě, a nevztáhli jste rukou na mne. Ale totoť jest ta vaše hodina a moc temnosti.'),
(1572179,54,42,22,54,'A oni javše jej, vedli ho, a uvedli do domu nejvyššího kněze. Petr pak šel za ním zdaleka.'),
(1572180,54,42,22,55,'A když zanítili oheň uprostřed síně a posadili se vůkol, sedl Petr mezi ně.'),
(1572181,54,42,22,56,'A uzřevši ho jedna děvečka, an sedí u ohně, a pilně naň pohleděvši, řekla: I tento byl s ním.'),
(1572182,54,42,22,57,'A on zapřel ho, řka: Ženo, neznám ho.'),
(1572183,54,42,22,58,'A po malé chvíli jiný, vida jej, řekl: I ty z nich jsi. Petr pak řekl: Ó člověče, nejsem.'),
(1572184,54,42,22,59,'A potom asi po jedné hodině jiný potvrzoval, řka: V pravdě i tento s ním byl, neb i Galilejský jest.'),
(1572185,54,42,22,60,'I řekl Petr: Člověče, nevím, co pravíš. A hned, když on ještě mluvil, kohout zazpíval.'),
(1572186,54,42,22,61,'I obrátiv se Pán, pohleděl na Petra. I rozpomenul se Petr na slovo Páně, kterak jemu byl řekl: Že prve než kohout zazpívá, třikrát mne zapříš.'),
(1572187,54,42,22,62,'I vyšed ven Petr, plakal hořce.'),
(1572188,54,42,22,63,'Muži pak ti, kteříž drželi Ježíše, posmívali se jemu, tepouce ho.'),
(1572189,54,42,22,64,'A zakrývajíce ho, bili jej v tvář, a tázali se ho, řkouce: Prorokuj, kdo jest, kterýž tebe udeřil?'),
(1572190,54,42,22,65,'A jiného mnoho, rouhajíce se, mluvili proti němu.'),
(1572191,54,42,22,66,'A když byl den, sešli se starší lidu a přední kněží a zákoníci, a vedli ho do rady své,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572192,54,42,22,67,'Řkouce: Jsi-li ty Kristus? Pověz nám! I dí jim: Povím-li vám, nikoli neuvěříte.'),
(1572193,54,42,22,68,'A pakli se vás co otíži, neodpovíte mi, ani propustíte.'),
(1572194,54,42,22,69,'Ale od této chvíle Syn člověka sedne na pravici moci Boží.'),
(1572195,54,42,22,70,'I řekli všickni: Tedy jsi ty Syn Boží? On pak řekl jim: Vy pravíte, že já jsem.'),
(1572196,54,42,22,71,'A oni řekli: Což ještě potřebujeme svědectví? Však jsme sami slyšeli z úst jeho.'),
(1572197,54,42,23,1,'Tehdy povstavši všecko to množství jich, vedli jej ku Pilátovi.'),
(1572198,54,42,23,2,'A počali naň žalovati, řkouce: Tohoto jsme nalezli, an převrací lid, a brání daně dávati císaři, pravě se býti Kristem králem.'),
(1572199,54,42,23,3,'Pilát pak otázal se ho, řka: Ty-li jsi král Židovský? A on odpověděv, řekl jemu: Ty pravíš.'),
(1572200,54,42,23,4,'I dí Pilát k předním kněžím a k zástupům: Žádné viny nenalézám na tomto člověku.'),
(1572201,54,42,23,5,'Oni pak více se rozmáhali v křiku, řkouce: Bouříť lid, uče po všem Judstvu, počav od Galilee až sem.'),
(1572202,54,42,23,6,'Tedy Pilát uslyšav o Galilei, otázal se, byl-li by člověk Galilejský.'),
(1572203,54,42,23,7,'A když zvěděl, že by byl z panství Herodesova, poslal jej k Herodesovi, kterýž také v Jeruzalémě byl v ty dni.'),
(1572204,54,42,23,8,'Herodes pak uzřev Ježíše, zradoval se velmi. Nebo dávno žádal viděti jej, protože mnoho o něm slýchal, a nadál se, že nějaký div od něho učiněný uzří.'),
(1572205,54,42,23,9,'I tázal se ho mnohými řečmi, ale on jemu nic neodpovídal.'),
(1572206,54,42,23,10,'Stáli pak tu přední kněží a zákoníci, tuze na něj žalujíce.'),
(1572207,54,42,23,11,'A pohrdna jím Herodes s svým rytířstvem, a naposmívav se jemu, oblékl jej v roucho bílé, i odeslal zase ku Pilátovi.'),
(1572208,54,42,23,12,'I učiněni jsou přátelé Herodes s Pilátem v ten den. Nebo před tím nepřátelé byli vespolek.'),
(1572209,54,42,23,13,'Pilát pak svolav přední kněží a úřadné osoby i lid,'),
(1572210,54,42,23,14,'Řekl k nim: Dali jste mi toho člověka, jako by lid odvracel po sobě, a aj, já před vámi vyptávaje se ho, žádné viny jsem nenalezl na tom člověku ve všem tom, což vy na něj žalujete.'),
(1572211,54,42,23,15,'Ano ani Herodes; nebo odeslal jsem vás k němu, a aj, nic hodného smrti nestalo se jemu.'),
(1572212,54,42,23,16,'Protož potresce ho, propustím jej.'),
(1572213,54,42,23,17,'Musíval pak propouštěti jim v svátek jednoho vězně.'),
(1572214,54,42,23,18,'Protož zkřikli spolu všecko množství, řkouce: Zahlaď tohoto, a propusť nám Barabbáše.'),
(1572215,54,42,23,19,'Kterýž byl pro svádu nějakou v městě učiněnou a pro vraždu vsazen do žaláře.'),
(1572216,54,42,23,20,'Tedy Pilát opět mluvil k nim, chtěje propustiti Ježíše.'),
(1572217,54,42,23,21,'A oni vždy volali, řkouce: Ukřižuj ho, ukřižuj!'),
(1572218,54,42,23,22,'A on po třetí řekl k nim: Což jest pak zlého učinil tento? Jáť žádné příčiny smrti nenalézám na něm. Protož potresce ho, propustím.'),
(1572219,54,42,23,23,'Oni pak předce dotírali na něj křikem velikým, žádajíce, aby byl ukřižován. A rozmáhali se hlasové jejich a předních kněží.'),
(1572220,54,42,23,24,'Pilát pak přisoudil, aby se naplnila žádost jejich.'),
(1572221,54,42,23,25,'I propustil jim toho, kterýž pro bouřku a vraždu vsazen byl do žaláře, za něhož prosili, ale Ježíše vydal k vůli jejich.'),
(1572222,54,42,23,26,'A když jej vedli, chytivše Šimona nějakého Cyrenenského, jdoucího s pole, vložili na něj kříž, aby jej nesl za Ježíšem.'),
(1572223,54,42,23,27,'I šlo za ním veliké množství lidu i žen, kteréžto plakaly a kvílily ho.'),
(1572224,54,42,23,28,'A obrátiv se k nim Ježíš, dí: Dcery Jeruzalémské, neplačtež nade mnou, ale raději samy nad sebou plačte a nad svými dětmi.'),
(1572225,54,42,23,29,'Nebo aj, přijdou dnové, v nichžto řeknou: Blahoslavené neplodné, a břicha, kteráž nerodila, a prsy, kteréž nekrmily.'),
(1572226,54,42,23,30,'Tehdyť počnou říci k horám: Padněte na nás, a pahrbkům: Přikrejte nás!'),
(1572227,54,42,23,31,'Nebo poněvadž na zeleném dřevě toto se děje, i co pak bude na suchém?'),
(1572228,54,42,23,32,'Vedeni pak byli s ním i jiní dva zločinci, aby spolu s ním byli ukřižováni.'),
(1572229,54,42,23,33,'A když přišli na místo, kteréž slove popravištné, tu jej ukřižovali, i ty zločince, jednoho na pravici, druhého pak na levici.'),
(1572230,54,42,23,34,'Tedy Ježíš řekl: Otče, odpusť jim, neboť nevědí, co činí. A rozdělivše roucho jeho, metali o ně los.'),
(1572231,54,42,23,35,'I stál lid, dívaje se. A posmívali se jemu knížata s nimi, řkouce: Jinýmť jest spomáhal, nechať nyní pomůže sám sobě, jestliže on jest Kristus, ten Boží zvolený.'),
(1572232,54,42,23,36,'Posmívali se také jemu žoldnéři, přistupujíce a octa podávajíce jemu,'),
(1572233,54,42,23,37,'A řkouce: Jsi-li ty ten král Židovský, spomoziž sám sobě.'),
(1572234,54,42,23,38,'A byl také i nápis napsaný nad ním, literami Řeckými a Latinskými a Židovskými: Tento jest král Židovský.'),
(1572235,54,42,23,39,'Jeden pak z těch zločinců, kteříž s ním viseli, rouhal se jemu, řka: Jsi-li ty Kristus, spomoziž sobě i nám.'),
(1572236,54,42,23,40,'A odpověděv druhý, trestal ho, řka: Ty se ani Boha nebojíš, ješto jsi v témž odsouzení?'),
(1572237,54,42,23,41,'Myť zajisté spravedlivě trpíme, nebo hodnou pomstu za skutky naše béřeme, ale tento nic zlého neučinil.'),
(1572238,54,42,23,42,'I dí Ježíšovi: Pane, rozpomeň se na mne, když přijdeš do království svého.'),
(1572239,54,42,23,43,'I řekl mu Ježíš: Amen pravím tobě, dnes budeš se mnou v ráji.'),
(1572240,54,42,23,44,'A bylo okolo hodiny šesté. I stala se tma po vší zemi až do hodiny deváté.'),
(1572241,54,42,23,45,'I zatmělo se slunce, a opona chrámová roztrhla se na poly.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572242,54,42,23,46,'A zvolav Ježíš hlasem velikým, řekl: Otče, v ruce tvé poroučím ducha svého. A to pověděv, umřel.'),
(1572243,54,42,23,47,'A vida centurio, co se stalo, velebil Boha, řka: Jistě člověk tento spravedlivý byl.'),
(1572244,54,42,23,48,'A všickni zástupové, přítomní tomu divadlu, hledíce na to, co se dálo, tepouce prsy své, navracovali se.'),
(1572245,54,42,23,49,'Stáli pak všickni známí jeho zdaleka, i ženy, kteréž byly přišly za ním od Galilee, hledíce na to.'),
(1572246,54,42,23,50,'A aj, muž jménem Jozef, jeden z úřadu, muž dobrý a spravedlivý,'),
(1572247,54,42,23,51,'Kterýž byl nepovolil radě a skutku jejich, z Arimatie města Judského, kterýžto také očekával království Božího,'),
(1572248,54,42,23,52,'Ten přistoupiv ku Pilátovi, vyprosil tělo Ježíšovo,'),
(1572249,54,42,23,53,'A složiv je s kříže, obvinul v kment a pochoval je v hrobě vytesaném v skále, v kterémž ještě nebyl žádný pochován.'),
(1572250,54,42,23,54,'A byl den připravování, a sobota se začínala.'),
(1572251,54,42,23,55,'Šedše pak také za ním ženy, kteréž byly s Ježíšem přišly od Galilee, pohleděly na hrob, a kterak pochováno bylo tělo jeho.'),
(1572252,54,42,23,56,'Vrátivše se pak, připravily vonné věci a masti, ale v sobotu odpočinuly, podle přikázání.'),
(1572253,54,42,24,1,'První pak den po sobotě, velmi ráno vyšedše, přišly k hrobu, nesouce vonné věci, kteréž byly připravily, a některé jiné byly spolu s nimi.'),
(1572254,54,42,24,2,'I nalezly kámen odvalený od hrobu.'),
(1572255,54,42,24,3,'A všedše tam, nenalezly těla Pána Ježíše.'),
(1572256,54,42,24,4,'I stalo se, když ony se toho užasly, aj, muži dva postavili se podle nich, v rouše stkvoucím.'),
(1572257,54,42,24,5,'Když se pak ony bály, a sklonily tváři své k zemi, řekli k nim: Co hledáte živého s mrtvými?'),
(1572258,54,42,24,6,'Neníť ho tuto, ale vstalť jest. Rozpomeňte se, kterak mluvil vám, když ještě v Galilei byl,'),
(1572259,54,42,24,7,'Řka: Že Syn člověka musí vydán býti v ruce hříšných lidí, a ukřižován býti, a třetí den z mrtvých vstáti.'),
(1572260,54,42,24,8,'I rozpomenuly se na slova jeho.'),
(1572261,54,42,24,9,'A navrátivše se od hrobu, zvěstovaly to všecko těm jedenácti učedlníkům i jiným všechněm.'),
(1572262,54,42,24,10,'Byly pak ženy ty: Maria Magdaléna a Johanna a Maria matka Jakubova, a jiné některé s nimi, kteréž vypravovaly to apoštolům.'),
(1572263,54,42,24,11,'Ale oni měli za bláznovství slova jejich, a nevěřili jim.'),
(1572264,54,42,24,12,'Tedy Petr vstav, běžel k hrobu, a pohleděv do něho, uzřel prostěradla, ana sama leží. I odšel, divě se sám v sobě, co se to stalo.'),
(1572265,54,42,24,13,'A aj, dva z nich šli toho dne do městečka, kteréž bylo vzdálí od Jeruzaléma honů šedesáte, jemuž jméno Emaus.'),
(1572266,54,42,24,14,'A rozmlouvali vespolek o těch všech věcech, kteréž se byly staly.'),
(1572267,54,42,24,15,'I stalo se, když rozmlouvali a sebe se otazovali, že i Ježíš, přiblíživ se k nim, šel s nimi.'),
(1572268,54,42,24,16,'Ale oči jejich držány byly, aby ho nepoznali.'),
(1572269,54,42,24,17,'I řekl k nim: Které jsou to věci, o nichž rozjímáte vespolek, jdouce, a proč jste smutní?'),
(1572270,54,42,24,18,'A odpověděv jeden, kterémuž jméno Kleofáš, řekl jemu: Ty sám jeden jsi z příchozích do Jeruzaléma, ještos nezvěděl, co se stalo v něm těchto dnů?'),
(1572271,54,42,24,19,'Kterýmžto on řekl: I co? Oni pak řekli jemu: O Ježíšovi Nazaretském, kterýž byl muž prorok, mocný v slovu i v skutku, před Bohem i přede vším lidem,'),
(1572272,54,42,24,20,'A kterak jej vydali přední kněží a knížata naše na odsouzení k smrti, i ukřižovali jej.'),
(1572273,54,42,24,21,'My pak jsme se nadáli, že by on měl vykoupiti lid Izraelský. Ale nyní tomu všemu třetí den jest dnes, jakž se to stalo.'),
(1572274,54,42,24,22,'Ale i ženy některé z našich zděsily nás, kteréž ráno byly u hrobu,'),
(1572275,54,42,24,23,'A nenalezše těla jeho, přišly, pravíce, že jsou také vidění andělské viděly, kteřížto praví, že by živ byl.'),
(1572276,54,42,24,24,'I chodili někteří z našich k hrobu, a nalezli tak, jakž pravily ženy, ale jeho neviděli.'),
(1572277,54,42,24,25,'Tedy on řekl k nim: Ó blázni a zpozdilí srdcem k věření všemu tomu, což mluvili Proroci.'),
(1572278,54,42,24,26,'Zdaliž nemusil těch věcí trpěti Kristus a tak vjíti v slávu svou?'),
(1572279,54,42,24,27,'A počav od Mojžíše a všech Proroků, vykládal jim všecka ta písma, kteráž o něm byla.'),
(1572280,54,42,24,28,'A vtom přiblížili se k městečku, do kteréhož šli, a on potrh se, jako by chtěl dále jíti.'),
(1572281,54,42,24,29,'Ale oni přinutili ho, řkouce: Zůstaň s námi, nebo se již připozdívá, a den se nachýlil. I všel, aby s nimi zůstal.'),
(1572282,54,42,24,30,'I stalo se, když seděl s nimi za stolem, vzav chléb, dobrořečil, a lámaje, podával jim.'),
(1572283,54,42,24,31,'I otevříny jsou oči jejich, a poznali ho. On pak zmizel od očí jejich.'),
(1572284,54,42,24,32,'I řekli vespolek: Zdaliž srdce naše v nás nehořelo, když mluvil nám na cestě a otvíral nám písma?'),
(1572285,54,42,24,33,'A vstavše v tu hodinu, vrátili se do Jeruzaléma, a nalezli shromážděných jedenácte, a ty, kteříž s nimi byli,'),
(1572286,54,42,24,34,'Ani praví: Že vstal Pán právě, a ukázal se Šimonovi.'),
(1572287,54,42,24,35,'I vypravovali oni také to, co se stalo na cestě, a kterak ho poznali v lámání chleba.'),
(1572288,54,42,24,36,'A když oni o tom rozmlouvali, postavil se Ježíš uprostřed nich, a řekl jim: Pokoj vám.'),
(1572289,54,42,24,37,'Oni pak zhrozivše se a přestrašeni byvše, domnívali se, že by ducha viděli.'),
(1572290,54,42,24,38,'I dí jim: Co se strašíte a myšlení vstupují na srdce vaše?'),
(1572291,54,42,24,39,'Vizte ruce mé i nohy mé, žeť v pravdě já jsem. Dotýkejte se a vizte; neboť duch těla a kostí nemá, jako mne vidíte míti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572292,54,42,24,40,'A pověděv to, ukázal jim ruce i nohy.'),
(1572293,54,42,24,41,'Když pak oni ještě nevěřili pro radost, ale divili se, řekl jim: Máte-li tu něco, ješto by se pojedlo?'),
(1572294,54,42,24,42,'A oni podali jemu kusu ryby pečené a plástu strdi.'),
(1572295,54,42,24,43,'A vzav to, pojedl před nimi,'),
(1572296,54,42,24,44,'A řekl jim: Tatoť jsou slova, kteráž jsem mluvil vám, ještě byv s vámi: Že se musí naplniti všecko, což psáno jest v Zákoně Mojžíšově a v Prorocích i v Žalmích o mně.'),
(1572297,54,42,24,45,'Tedy otevřel jim mysl, aby rozuměli Písmům.'),
(1572298,54,42,24,46,'A řekl jim: Že tak psáno jest a tak musil Kristus trpěti, a třetího dne z mrtvých vstáti,'),
(1572299,54,42,24,47,'A aby bylo kázáno ve jménu jeho pokání a odpuštění hříchů mezi všemi národy, počna od Jeruzaléma.'),
(1572300,54,42,24,48,'Vy jste pak svědkové toho.'),
(1572301,54,42,24,49,'A aj, já pošli zaslíbení Otce svého na vás. Vy pak čekejte v městě Jeruzalémě, dokudž nebudete oblečeni mocí s výsosti.'),
(1572302,54,42,24,50,'I vyvedl je ven až do Betany, a pozdvih rukou svých, dal jim požehnání.'),
(1572303,54,42,24,51,'I stalo se, když jim žehnal, bral se od nich, a nesen jest do nebe.'),
(1572304,54,42,24,52,'A oni poklonivše se jemu, navrátili se do Jeruzaléma s radostí velikou.'),
(1572305,54,42,24,53,'A byli vždycky v chrámě, chválíce a dobrořečíce Boha. Amen.'),
(1572306,54,43,1,1,'Na počátku bylo Slovo, a to Slovo bylo u Boha, a to Slovo byl Bůh.'),
(1572307,54,43,1,2,'To bylo na počátku u Boha.'),
(1572308,54,43,1,3,'Všecky věci skrze ně učiněny jsou, a bez něho nic není učiněno, což učiněno jest.'),
(1572309,54,43,1,4,'V něm život byl, a život byl světlo lidí.'),
(1572310,54,43,1,5,'A to Světlo v temnostech svítí, ale tmy ho neobsáhly.'),
(1572311,54,43,1,6,'Byl člověk poslaný od Boha, jemuž jméno bylo Jan.'),
(1572312,54,43,1,7,'Ten přišel na svědectví, aby svědčil o tom Světle, aby všickni uvěřili skrze něho.'),
(1572313,54,43,1,8,'Nebyl on to Světlo, ale poslán byl, aby svědectví vydával o tom Světle.'),
(1572314,54,43,1,9,'Tenť byl to pravé Světlo, jenž osvěcuje každého člověka přicházejícího na svět.'),
(1572315,54,43,1,10,'Na světě byl, a svět skrze něho učiněn jest, a svět ho nepoznal.'),
(1572316,54,43,1,11,'Do svého vlastního přišel, a vlastní jeho nepřijali ho.'),
(1572317,54,43,1,12,'Kteříž pak koli přijali jej, dal jim moc syny Božími býti, totiž těm, kteříž věří ve jméno jeho,'),
(1572318,54,43,1,13,'Kteřížto ne ze krví, ani z vůle těla, ani z vůle muže, ale z Boha zplozeni jsou.'),
(1572319,54,43,1,14,'A Slovo to tělo učiněno jest, a přebývalo mezi námi, (a viděli jsme slávu jeho, slávu jakožto jednorozeného od Otce,) plné milosti a pravdy.'),
(1572320,54,43,1,15,'Jan svědectví vydával o něm, a volal, řka: Tentoť jest, o němž jsem pravil, že po mně přišed, předšel mne; nebo přednější jest nežli já.'),
(1572321,54,43,1,16,'A z plnosti jeho my všickni vzali jsme, a to milost za milost.'),
(1572322,54,43,1,17,'Nebo zákon skrze Mojžíše dán jest, ale milost a pravda skrze Ježíše Krista stala se jest.'),
(1572323,54,43,1,18,'Boha žádný nikdy neviděl, ale jednorozený Syn, kterýž jest v lůnu Otce, onť jest nám vypravil.'),
(1572324,54,43,1,19,'A totoť jest svědectví Janovo, když poslali Židé z Jeruzaléma kněží a Levíty, aby se ho otázali: Ty kdo jsi?'),
(1572325,54,43,1,20,'I vyznal a nezapřel, a vyznal: Že já nejsem ten Kristus.'),
(1572326,54,43,1,21,'I otázali se ho: Což pak? Eliáš jsi ty? I řekl: Nejsem. Tedy jsi ten Prorok? Odpověděl: Nejsem.'),
(1572327,54,43,1,22,'I řekli jemu: Kdožs pak? Ať odpověd dáme těm, kteříž nás poslali. Co pravíš sám o sobě?'),
(1572328,54,43,1,23,'Řekl: Já jsem hlas volajícího na poušti: Spravte cestu Páně, jakož pověděl Izaiáš prorok.'),
(1572329,54,43,1,24,'Ti pak, kteříž byli posláni, z farizeů byli.'),
(1572330,54,43,1,25,'I otázali se ho a řekli jemu: Pročež tedy křtíš, poněvadž ty nejsi Kristus, ani Eliáš, ani Prorok?'),
(1572331,54,43,1,26,'Odpověděl jim Jan, řka: Já křtím vodou, ale uprostřed vás stojí, jehož vy neznáte.'),
(1572332,54,43,1,27,'Ten ačkoli po mně přišel, však předšel mne, u jehožto obuvi já nejsem hoden rozvázati řeménka.'),
(1572333,54,43,1,28,'Toto v Betabaře stalo se za Jordánem, kdežto Jan křtil.'),
(1572334,54,43,1,29,'Druhého pak dne uzřel Jan Ježíše, an jde k němu. I dí: Aj, Beránek Boží, kterýž snímá hřích světa.'),
(1572335,54,43,1,30,'Tentoť jest, o kterémž jsem já pravil, že za mnou jde muž, kterýž mne předšel; nebo přednější jest nežli já.'),
(1572336,54,43,1,31,'A já jsem ho neznal, ale aby zjeven byl lidu Izraelskému, proto jsem já přišel, křtě vodou.'),
(1572337,54,43,1,32,'A svědectví vydal Jan, řka: Viděl sem Ducha sstupujícího jako holubice s nebe, a zůstal na něm.'),
(1572338,54,43,1,33,'A já jsem ho neznal, ale kterýž mne poslal křtíti vodou, ten mi řekl: Nad kýmž uzříš Ducha sstupujícího a zůstávajícího na něm, tenť jest, kterýž křtí Duchem svatým.'),
(1572339,54,43,1,34,'A já jsem viděl, a svědectví jsem vydal, že on jest ten Syn Boží.'),
(1572340,54,43,1,35,'Druhého pak dne opět stál Jan, a z učedlníků jeho dva,'),
(1572341,54,43,1,36,'A uzřev Ježíše, an se prochází, řekl: Aj, Beránek Boží.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572342,54,43,1,37,'I slyšeli ho dva učedlníci mluvícího, a šli za Ježíšem.'),
(1572343,54,43,1,38,'I obrátiv se Ježíš, a uzřev je, ani jdou za ním, dí jim:'),
(1572344,54,43,1,39,'Co hledáte? A oni řekli jemu: Rabbi, (jenž se vykládá: Mistře,) kde bydlíš?'),
(1572345,54,43,1,40,'Dí jim: Pojďte a vizte. I šli, aby viděli, kde by bydlil, a zůstali u něho ten den; neb bylo již okolo desáté hodiny.'),
(1572346,54,43,1,41,'Byl pak Ondřej, bratr Šimona Petra, jeden ze dvou, kteříž byli to slyšeli od Jana, a šli za ním.'),
(1572347,54,43,1,42,'I nalezl ten první bratra svého vlastního Šimona, a řekl mu: Nalezli jsme Mesiáše, jenž se vykládá Kristus.'),
(1572348,54,43,1,43,'I přivedl jej k Ježíšovi. A pohleděv naň Ježíš, dí: Ty jsi Šimon, syn Jonášův, ty slouti budeš Céfas, jenž se vykládá Petr.'),
(1572349,54,43,1,44,'Na druhý pak den Ježíš chtěl vyjíti do Galilee, i nalezl Filipa, a řekl jemu: Pojď za mnou.'),
(1572350,54,43,1,45,'A byl Filip z Betsaidy, města Ondřejova a Petrova.'),
(1572351,54,43,1,46,'Nalezl také Filip Natanaele. I dí jemu: O kterémž psal Mojžíš v Zákoně a Proroci, nalezli jsme Ježíše, syna Jozefova z Nazaréta.'),
(1572352,54,43,1,47,'I řekl jemu Natanael: A může z Nazaréta co dobrého býti? Řekl jemu Filip: Pojď a viz.'),
(1572353,54,43,1,48,'Vida Ježíš Natanaele, an jde k němu, i dí o něm: Aj, právě Izraelitský, v němžto lsti není.'),
(1572354,54,43,1,49,'Řekl mu Natanael: Jakž ty mne znáš? Odpověděl Ježíš a řekl jemu: Prve nežli tě Filip zavolal, kdyžs byl pod fíkem, viděl jsem tebe.'),
(1572355,54,43,1,50,'Odpověděl Natanael a řekl jemu: Mistře, ty jsi Syn Boží, ty jsi ten Král Izraelský.'),
(1572356,54,43,1,51,'Odpověděl Ježíš a řekl jemu: Žeť jsem řekl: Viděl jsem tebe pod fíkem, věříš? Větší věci nad tyto uzříš.'),
(1572357,54,43,1,52,'I dí mu: Amen, amen pravím vám: Od tohoto času uzříte nebe otevřené, a anděly Boží vstupující a sstupující na Syna člověka.'),
(1572358,54,43,2,1,'Třetího dne stala se svadba v Káni Galilejské, a byla matka Ježíšova tam.'),
(1572359,54,43,2,2,'A pozván jest také Ježíš i učedlníci jeho na svadbu.'),
(1572360,54,43,2,3,'Když se pak nedostalo vína, řekla matka Ježíšova k němu: Vína nemají.'),
(1572361,54,43,2,4,'Dí jí Ježíš: Co mně a tobě ženo? Ještě nepřišla hodina má.'),
(1572362,54,43,2,5,'Dí matka jeho k služebníkům: Což by koli vám řekl, učiňte.'),
(1572363,54,43,2,6,'I bylo tu kamenných stoudví šest postaveno, podle obyčeje očišťování Židovského, beroucí v sebe jedna každá dvě nebo tři míry.'),
(1572364,54,43,2,7,'Řekl jim Ježíš: Naplňte ty stoudve vodou. I naplnili je až do vrchu.'),
(1572365,54,43,2,8,'I dí jim: Nalévejtež již, a neste vrchnímu správci svadby. I nesli.'),
(1572366,54,43,2,9,'A jakž okusil vrchní správce svadby vody vínem učiněné, (nevěděl pak, odkud by bylo, ale služebníci věděli, kteříž vážili vodu,) povolal ženicha ten vrchní správce,'),
(1572367,54,43,2,10,'A řekl mu: Každý člověk nejprve dobré víno dává, a když by se hojně napili, tehdy to, kteréž horší jest. Ale ty zachoval jsi víno dobré až dosavad.'),
(1572368,54,43,2,11,'To učinil Ježíš počátek divů v Káni Galilejské, a zjevil slávu svou. I uvěřili v něho učedlníci jeho.'),
(1572369,54,43,2,12,'Potom sstoupil do Kafarnaum, on i matka jeho, i bratří jeho, i učedlníci jeho, a pobyli tam nemnoho dní;'),
(1572370,54,43,2,13,'Nebo blízko byla velikanoc Židovská. I vstoupil Ježíš do Jeruzaléma.'),
(1572371,54,43,2,14,'A nalezl v chrámě, ano prodávají voly a ovce i holubice, a penězoměnce sedící.'),
(1572372,54,43,2,15,'A udělav bič z provázků, všecky vyhnal z chrámu, i ovce i voly, a penězoměncům rozsypal peníze, a stoly zpřevracel.'),
(1572373,54,43,2,16,'A těm, kteříž holuby prodávali, řekl: Odnestež tyto věci odsud, a nečiňte domu Otce mého domem kupeckým.'),
(1572374,54,43,2,17,'I rozpomenuli se učedlníci jeho, že psáno jest: Horlivost domu tvého snědla mne.'),
(1572375,54,43,2,18,'Tedy odpověděli Židé a řekli jemu: Jaké znamení toho nám ukážeš, že tyto věci činíš?'),
(1572376,54,43,2,19,'Odpověděl Ježíš a řekl jim: Zrušte chrám tento, a ve třech dnech zase vzdělám jej.'),
(1572377,54,43,2,20,'I řekli Židé: Čtyřidceti a šest let dělán jest chrám tento, a ty ve třech dnech vzděláš jej?'),
(1572378,54,43,2,21,'Ale on pravil o chrámu těla svého.'),
(1572379,54,43,2,22,'A protož když z mrtvých vstal, rozpomenuli se učedlníci jeho, že jim to byl pověděl. I uvěřili Písmu a slovu, kteréž pověděl Ježíš.'),
(1572380,54,43,2,23,'A když byl v Jeruzalémě na velikunoc v den sváteční, mnozí uvěřili ve jméno jeho, vidouce divy jeho, kteréž činil.'),
(1572381,54,43,2,24,'Ale Ježíš nesvěřil sebe samého jim, protože on znal všecky.'),
(1572382,54,43,2,25,'Aniž potřeboval, aby jemu kdo svědectví vydával o člověku; neb on věděl, co by bylo v člověku.'),
(1572383,54,43,3,1,'Byl pak člověk z farizeů, jménem Nikodém, kníže Židovské.'),
(1572384,54,43,3,2,'Ten přišel k Ježíšovi v noci, a řekl jemu: Mistře, víme, že jsi od Boha přišel Mistr; nebo žádný nemůže těch divů činiti, kteréž ty činíš, leč by Bůh byl s ním.'),
(1572385,54,43,3,3,'Odpověděl Ježíš a řekl jemu: Amen, amen pravím tobě: Nenarodí-li se kdo znovu, nemůž viděti království Božího.'),
(1572386,54,43,3,4,'Řekl jemu Nikodém: Kterak můž člověk naroditi se, starý jsa? Zdali může opět v život matky své vjíti a naroditi se?'),
(1572387,54,43,3,5,'Odpověděl Ježíš: Amen, amen pravím tobě: Nenarodí-li se kdo z vody a z Ducha svatého, nemůž vjíti do království Božího.'),
(1572388,54,43,3,6,'Což se narodilo z těla, tělo jest, a což se narodilo z Ducha, duch jest.'),
(1572389,54,43,3,7,'Nediviž se, že jsem řekl tobě: Musíte se znovu zroditi.'),
(1572390,54,43,3,8,'Vítr kde chce věje, a hlas jeho slyšíš, ale nevíš, odkud přichází, a kam jde. Takť jest každý, kdož se z Ducha narodil.'),
(1572391,54,43,3,9,'Odpověděl Nikodém a řekl jemu: Kterak mohou tyto věci býti?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572392,54,43,3,10,'Odpověděl Ježíš a řekl jemu: Ty jsi mistr v Izraeli, a toho neznáš?'),
(1572393,54,43,3,11,'Amen, amen pravím tobě: Že což víme, mluvíme, a což jsme viděli, svědčíme, ale svědectví našeho nepřijímáte.'),
(1572394,54,43,3,12,'Poněvadž zemské věci mluvil jsem vám, a nevěříte, kterak, budu-li vám praviti nebeské, uvěříte?'),
(1572395,54,43,3,13,'Nebo žádný nevstoupil v nebe, než ten, jenž sstoupil s nebe, Syn člověka, kterýž jest v nebi.'),
(1572396,54,43,3,14,'A jakož jest Mojžíš povýšil hada na poušti, takť musí povýšen býti Syn člověka,'),
(1572397,54,43,3,15,'Aby každý, kdož věří v něho, nezahynul, ale měl život věčný.'),
(1572398,54,43,3,16,'Nebo tak Bůh miloval svět, že Syna svého jednorozeného dal, aby každý, kdož věří v něho, nezahynul, ale měl život věčný.'),
(1572399,54,43,3,17,'Neboť jest neposlal Bůh Syna svého na svět, aby odsoudil svět, ale aby spasen byl svět skrze něho.'),
(1572400,54,43,3,18,'Kdož věří v něho, nebude odsouzen, ale kdož nevěří, jižť jest odsouzen; nebo neuvěřil ve jméno jednorozeného Syna Božího.'),
(1572401,54,43,3,19,'Toto pak jest ten soud, že Světlo přišlo na svět, ale milovali lidé více tmu nežli Světlo; nebo skutkové jejich byli zlí.'),
(1572402,54,43,3,20,'Každý zajisté, kdož zle činí, nenávidí světla, a nejde k světlu, aby nebyli trestáni skutkové jeho.'),
(1572403,54,43,3,21,'Ale kdož činí pravdu, jde k světlu, aby zjeveni byli skutkové jeho, že v Bohu učiněni jsou.'),
(1572404,54,43,3,22,'Potom přišel Ježíš i učedlníci jeho do země Judské, a tu přebýval s nimi, a křtil.'),
(1572405,54,43,3,23,'A Jan také křtil v Enon, blízko Sálim, nebo byly tam vody mnohé. I přicházeli mnozí, a křtili se.'),
(1572406,54,43,3,24,'Nebo ještě Jan nebyl vsazen do žaláře.'),
(1572407,54,43,3,25,'Tedy vznikla otázka mezi Židy a některými z učedlníků Janových o očišťování.'),
(1572408,54,43,3,26,'I přišli k Janovi a řekli jemu: Mistře, ten, kterýž byl s tebou za Jordánem, jemužs ty svědectví vydal, aj, on křtí, a všickni jdou k němu.'),
(1572409,54,43,3,27,'Odpověděl Jan a řekl: Nemůžť člověk vzíti ničehož, leč by jemu dáno bylo s nebe.'),
(1572410,54,43,3,28,'Vy sami svědkové jste mi, že jsem pověděl: Nejsem já Kristus, ale že jsem poslán před ním.'),
(1572411,54,43,3,29,'Kdož má nevěstu, ženichť jest, přítel pak ženicha, jenž stojí a slyší ho, radostí raduje se pro hlas ženicha. Protož ta radost má naplněna jest.'),
(1572412,54,43,3,30,'Onť musí růsti, já pak menšiti se.'),
(1572413,54,43,3,31,'Kdož jest shůry přišel, nade všeckyť jest; kdožť jest z země, zemskýť jest, a zemské věci mluví. Ale ten, jenž s nebe přišel, nade všecky jest.'),
(1572414,54,43,3,32,'A což viděl a slyšel, toť svědčí, ale svědectví jeho žádný nepřijímá.'),
(1572415,54,43,3,33,'Kdož pak přijímá svědectví jeho, zpečetil jest to, že Bůh pravdomluvný jest.'),
(1572416,54,43,3,34,'Nebo ten, kteréhož Bůh poslal, slovo Boží mluví; nebo jemu ne v míru dává Bůh ducha.'),
(1572417,54,43,3,35,'Otec miluje Syna a všecko dal v ruku jeho.'),
(1572418,54,43,3,36,'Kdož věří v Syna, má život věčný; ale kdožť jest nevěřící Synu, neuzříť života, ale hněv Boží zůstává na něm.'),
(1572419,54,43,4,1,'A jakž poznal Pán, že jsou slyšeli farizeové, že by Ježíš více učedlníků činil a křtil nežli Jan,'),
(1572420,54,43,4,2,'(Ačkoli Ježíš sám nekřtil, ale učedlníci jeho,)'),
(1572421,54,43,4,3,'Opustil Judstvo a odšel opět do Galilee.'),
(1572422,54,43,4,4,'Musil pak jíti skrze Samaří.'),
(1572423,54,43,4,5,'I přišel k městu Samařskému, kteréž slove Sichar, vedle popluží, kteréž byl dal Jákob Jozefovi, synu svému.'),
(1572424,54,43,4,6,'Byla pak tu studnice Jákobova. Protož ustav na cestě Ježíš, posadil se tak na studnici. A bylo již okolo šesté hodiny.'),
(1572425,54,43,4,7,'I přišla žena z Samaří vážiti vody. Kteréžto řekl Ježíš: Dej mi píti.'),
(1572426,54,43,4,8,'(Nebo učedlníci jeho byli odešli do města, aby nakoupili pokrmů.)'),
(1572427,54,43,4,9,'I řekla jemu žena ta Samaritánka: Kterakž ty, jsa Žid, žádáš ode mne nápoje od ženy Samaritánky? (Nebo neobcují Židé s Samaritány.)'),
(1572428,54,43,4,10,'Odpověděl Ježíš a řekl jí: Kdybys znala ten dar Boží, a věděla, kdo jest, kterýž praví tobě: Dej mi píti, ty bys prosila jeho, a dalť by tobě vody živé.'),
(1572429,54,43,4,11,'I dí jemu žena: Pane, aniž máš, čím bys navážil, a studnice jest hluboká. Odkudž tedy máš tu vodu živou?'),
(1572430,54,43,4,12,'Zdaliž jsi ty větší nežli otec náš Jákob, kterýž nám dal tuto studnici, a sám z ní pil, i synové jeho, i dobytek jeho?'),
(1572431,54,43,4,13,'Odpověděl Ježíš a řekl jí: Každý, kdož pije vodu tuto, žízniti bude opět.'),
(1572432,54,43,4,14,'Ale kdož by se napil vody té, kterouž já dám jemu, nežíznil by na věky, ale voda ta, kterouž já dám jemu, bude v něm studnicí vody prýštící se k životu věčnému.'),
(1572433,54,43,4,15,'Řekla jemu žena: Pane, dej mi té vody, ať bych nežíznila, ani chodila sem vážiti.'),
(1572434,54,43,4,16,'Řekl jí Ježíš: Jdi, zavolej muže svého, a přijď sem.'),
(1572435,54,43,4,17,'Odpověděla žena a řekla: Nemám muže. Dí jí Ježíš: Dobřes řekla: Nemám muže.'),
(1572436,54,43,4,18,'Nebos pět mužů měla, a nyní kteréhož máš, není tvůj muž. To jsi pravdu pověděla.'),
(1572437,54,43,4,19,'Řekla jemu žena: Pane, vidím, že jsi ty prorok.'),
(1572438,54,43,4,20,'Otcové naši na této hoře modlívali se, a vy pravíte, že v Jeruzalémě jest místo, kdežto náleží se modliti.'),
(1572439,54,43,4,21,'Dí jí Ježíš: Ženo, věř mi, žeť jde hodina, kdyžto ani na této hoře, ani v Jeruzalémě nebudete se modliti Otci.'),
(1572440,54,43,4,22,'Vy se modlíte, a nevíte, čemu; my se pak modlíme, čemuž víme, nebo spasení z Židů jest.'),
(1572441,54,43,4,23,'Ale jdeť hodina, a nyníť jest, kdyžto praví modlitebníci modliti se budou Otci v duchu a v pravdě. Neboť takových Otec hledá, aby se modlili jemu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572442,54,43,4,24,'Bůh duch jest, a ti, kteříž se jemu modlí, v duchu a v pravdě musejí se modliti.'),
(1572443,54,43,4,25,'Dí jemu žena: Vím, že Mesiáš přijde, jenž slove Kristus. Ten, když přijde, oznámí nám všecko.'),
(1572444,54,43,4,26,'Dí jí Ježíš: Jáť jsem, kterýž mluvím s tebou.'),
(1572445,54,43,4,27,'A v tom přišli učedlníci jeho, i divili se, že by s ženou mluvil, avšak žádný jemu neřekl: Nač se jí ptáš, aneb proč mluvíš s ní?'),
(1572446,54,43,4,28,'I nechala tu žena vědra svého, a šla do města, a řekla těm lidem:'),
(1572447,54,43,4,29,'Pojďte, vizte člověka, kterýž pověděl mi všecko, což jsem koli činila. Není-li on ale Kristus?'),
(1572448,54,43,4,30,'Tedy vyšli z města, a přišli k němu.'),
(1572449,54,43,4,31,'Mezi tím pak prosili ho učedlníci, řkouce: Mistře, pojez.'),
(1572450,54,43,4,32,'A on řekl jim: Jáť mám pokrm k jísti, kteréhož vy nevíte.'),
(1572451,54,43,4,33,'Učedlníci pak mluvili vespolek: Zdali jemu kdo přinesl jísti?'),
(1572452,54,43,4,34,'Dí jim Ježíš: Můjť pokrm jest, abych činil vůli toho, jenž mne poslal, a dokonal dílo jeho.'),
(1572453,54,43,4,35,'Však vy pravíte, že ještě čtyři měsícové jsou, a žeň přijde. Aj, pravím vám: Pozdvihněte očí vašich, a patřte na krajiny, žeť se již bělejí ke žni.'),
(1572454,54,43,4,36,'Kdož pak žne, odplatuť béře, a shromažďuje užitek k životu věčnému, aby i ten, kdož rozsívá, spolu se radoval, i kdo žne.'),
(1572455,54,43,4,37,'Nebo i v tom pravé jest slovo, žeť jiný jest, jenž rozsívá, a jiný, kterýž žne.'),
(1572456,54,43,4,38,'Jáť jsem vás poslal žíti, o čemž jste vy nepracovali. Jiníť jsou pracovali, a vy jste v jejich práce vešli.'),
(1572457,54,43,4,39,'Z města pak toho mnozí z Samaritánů uvěřili v něho, pro řeč ženy, svědčící: Že mi pověděl všecko, což jsem činila.'),
(1572458,54,43,4,40,'A když k němu přišli Samaritáni, prosili ho, aby s nimi zůstal. I pobyl tu za dva dni.'),
(1572459,54,43,4,41,'A mnohem jich více uvěřilo pro řeč jeho.'),
(1572460,54,43,4,42,'A ženě té řekli: Že již ne pro tvé vypravování věříme; nebo sami jsme slyšeli, a víme, že tento jest právě Spasitel světa, Kristus.'),
(1572461,54,43,4,43,'Po dvou pak dnech vyšel odtud, a šel do Galilee.'),
(1572462,54,43,4,44,'Nebo sám Ježíš byl svědectví vydal, že prorok v vlasti své v vážnosti není.'),
(1572463,54,43,4,45,'A když přišel do Galilee, přijali jej Galilejští, všecko viděvše, co činil v Jeruzalémě v svátek; nebo i oni byli přišli ke dni svátečnímu.'),
(1572464,54,43,4,46,'Tedy opět přišel Ježíš do Káně Galilejské, kdežto učinil byl z vody víno. I byl jeden královský služebník v Kafarnaum, jehožto syn nemocen byl.'),
(1572465,54,43,4,47,'Ten uslyšev, že by Ježíš přišel z Judstva do Galilee, šel k němu, a prosil ho, aby sstoupil a uzdravil syna jeho; nebo počínal umírati.'),
(1572466,54,43,4,48,'I řekl k němu Ježíš: Neuzříte-li divů a zázraků, neuvěříte.'),
(1572467,54,43,4,49,'Dí jemu ten královský služebník: Pane, pojď prve, nežli umře syn můj.'),
(1572468,54,43,4,50,'Dí jemu Ježíš: Jdi, syn tvůj živ jest. I uvěřil člověk řeči, kterouž mluvil k němu Ježíš, a šel.'),
(1572469,54,43,4,51,'Když pak on již šel, potkali se s ním služebníci jeho a zvěstovali mu, řkouce: Syn tvůj živ jest.'),
(1572470,54,43,4,52,'Tedy otázal se jich na hodinu, v kterou by se lépe měl. I řekli jemu: Včera v hodinu sedmou přestala mu zimnice.'),
(1572471,54,43,4,53,'Tedy poznal otec, že právě v tu hodinu to se stalo, v kterouž řekl byl jemu Ježíš: Syn tvůj živ jest. I uvěřil on i dům jeho všecken.'),
(1572472,54,43,4,54,'To opět druhý div učinil Ježíš, přišed z Judstva do Galilee.'),
(1572473,54,43,5,1,'Potom byl svátek Židovský, i šel Ježíš do Jeruzaléma.'),
(1572474,54,43,5,2,'Byl pak v Jeruzalémě u brány bravné rybník, kterýž slove Židovsky Bethesda, patero přístřeší maje.'),
(1572475,54,43,5,3,'Kdežto leželo množství veliké neduživých, slepých, kulhavých, suchých, očekávajících hnutí vody.'),
(1572476,54,43,5,4,'Nebo anděl Páně jistým časem sstupoval do rybníka, a kormoutil vodu. A kdož tam nejprve sstoupil po tom zkormoucení vody, uzdraven býval, od kterékoli nemoci trápen byl.'),
(1572477,54,43,5,5,'I byl tu člověk jeden, kterýž osm a třidceti let nemocen byl.'),
(1572478,54,43,5,6,'Toho uzřev Ježíš ležícího, a poznav, že jest již dávno nemocen, dí jemu: Chceš-li zdráv býti?'),
(1572479,54,43,5,7,'Odpověděl mu nemocný: Pane, nemám člověka, kterýž by, když se zkormoutí voda, uvrhl mne do rybníka, nebo když já jdu, jiný přede mnou již vstupuje.'),
(1572480,54,43,5,8,'Dí jemu Ježíš: Vstaň, vezmi lože své a choď.'),
(1572481,54,43,5,9,'A hned zdráv jest učiněn člověk ten, a vzav lože své, i chodil. A byla sobota v ten den.'),
(1572482,54,43,5,10,'Tedy řekli Židé tomu uzdravenému: Sobota jest, neslušíť tobě lože nositi.'),
(1572483,54,43,5,11,'Odpověděl jim: Ten, kterýž mne uzdravil, onť mi řekl: Vezmi lože své a choď.'),
(1572484,54,43,5,12,'I otázali se ho: Kdo jest ten člověk, kterýž tobě řekl: Vezmi lože své a choď?'),
(1572485,54,43,5,13,'Ten pak uzdravený nevěděl, kdo by byl. Nebo Ježíš byl poodšel od zástupu shromážděného na tom místě.'),
(1572486,54,43,5,14,'Potom pak nalezl jej Ježíš v chrámě, a řekl jemu: Aj, zdráv jsi učiněn; nikoli víc nehřeš, ať by se něco horšího nepřihodilo.'),
(1572487,54,43,5,15,'Odšel ten člověk, a pověděl Židům, že by Ježíš byl ten, kterýž ho zdravého učinil.'),
(1572488,54,43,5,16,'A protož protivili se Židé Ježíšovi, a hledali ho zabíti, že to učinil v sobotu.'),
(1572489,54,43,5,17,'Ježíš pak odpověděl jim: Otec můj až dosavad dělá, i jáť dělám.'),
(1572490,54,43,5,18,'Tedy Židé ještě víc proto hledali ho zamordovati, že by netoliko rušil sobotu, ale že Otce svého pravil býti Boha, rovného se čině Bohu.'),
(1572491,54,43,5,19,'I odpověděl Ježíš a řekl jim: Amen, amen pravím vám: Nemůžeť Syn sám od sebe nic činiti, jediné což vidí, an Otec činí. Nebo cožkoli on činí, toť i Syn též podobně činí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572492,54,43,5,20,'Otec zajisté miluje Syna, a ukazuje mu všecko, což sám činí; a větší nad to ukáže jemu skutky tak, abyste vy se divili.'),
(1572493,54,43,5,21,'Nebo jakož Otec křísí mrtvé a obživuje, tak i Syn, kteréž chce, obživuje.'),
(1572494,54,43,5,22,'Aniž zajisté Otec soudí koho, ale všecken soud dal Synu,'),
(1572495,54,43,5,23,'Aby všickni ctili Syna, tak jakž Otce ctí. Kdo nectí Syna, nectí ani Otce, kterýž ho poslal.'),
(1572496,54,43,5,24,'Amen, amen pravím vám: Že kdož slovo mé slyší, a věří tomu, jenž mne poslal, máť život věčný, a na soud nepřijde, ale přešelť jest z smrti do života.'),
(1572497,54,43,5,25,'Amen, amen pravím vám: Že přijde hodina, a nyníť jest, kdyžto mrtví uslyší hlas Syna Božího, a kteříž uslyší, živi budou.'),
(1572498,54,43,5,26,'Nebo jakož Otec má život sám v sobě, tak jest dal i Synu, aby měl život v samém sobě.'),
(1572499,54,43,5,27,'A dal jemu moc i soud činiti, nebo Syn člověka jest.'),
(1572500,54,43,5,28,'Nedivtež se tomu; neboť přijde hodina, v kteroužto všickni, kteříž v hrobích jsou, uslyší hlas jeho.'),
(1572501,54,43,5,29,'A půjdou ti, kteříž dobré věci činili, na vzkříšení života, ale ti, kteříž zlé věci činili, na vzkříšení soudu.'),
(1572502,54,43,5,30,'Nemohuť já sám od sebe nic činiti. Ale jakžť slyším, takť soudím, a soud můj spravedlivý jest. Nebo nehledám vůle své, ale vůle toho, jenž mne poslal, Otcovy.'),
(1572503,54,43,5,31,'Vydám-liť já svědectví sám o sobě, svědectví mé není pravé.'),
(1572504,54,43,5,32,'Jinýť jest, kterýž svědectví vydává o mně, a vím, že pravé jest svědectví, kteréž vydává o mně.'),
(1572505,54,43,5,33,'Vy jste byli poslali k Janovi, a on svědectví vydal pravdě.'),
(1572506,54,43,5,34,'Ale jáť nepřijímám svědectví od člověka, než totoť pravím, abyste vy spaseni byli.'),
(1572507,54,43,5,35,'Onť jest byl svíce hořící a svítící, vy pak chtěli jste na čas poradovati se v světle jeho.'),
(1572508,54,43,5,36,'Ale já mám větší svědectví, nežli Janovo. Nebo skutkové, kteréž mi dal Otec, abych je vykonal, tiť skutkové, kteréž já činím, svědčí o mně, že jest mne Otec poslal.'),
(1572509,54,43,5,37,'A kterýž mne poslal, Otec, onť jest svědectví vydal o mně, jehož jste vy hlasu nikdy neslyšeli, ani tváři jeho viděli.'),
(1572510,54,43,5,38,'A slova jeho nemáte v sobě zůstávajícího. Nebo kteréhož jest on poslal, tomu vy nevěříte.'),
(1572511,54,43,5,39,'Ptejte se na Písma; nebo vy domníváte se v nich věčný život míti, a tať svědectví vydávají o mně.'),
(1572512,54,43,5,40,'A nechcete přijíti ke mně, abyste život měli.'),
(1572513,54,43,5,41,'Chvály od lidí jáť nepřijímám.'),
(1572514,54,43,5,42,'Ale poznal jsem vás, že milování Božího nemáte v sobě.'),
(1572515,54,43,5,43,'Já jsem přišel ve jménu Otce svého, a nepřijímáte mne. Kdyby jiný přišel ve jménu svém, toho přijmete.'),
(1572516,54,43,5,44,'Kterak vy můžete věřiti, chvály jedni od druhých hledajíce, poněvadž chvály, kteráž jest od samého Boha, nehledáte?'),
(1572517,54,43,5,45,'Nedomnívejte se, bychť já na vás žalovati měl před Otcem. Jestiť, kdo by žaloval na vás, Mojžíš, v němž vy naději máte.'),
(1572518,54,43,5,46,'Nebo kdybyste věřili Mojžíšovi, věřili byste i mně; nebť jest on o mně psal.'),
(1572519,54,43,5,47,'Ale poněvadž jeho písmům nevěříte, i kterak slovům mým uvěříte?'),
(1572520,54,43,6,1,'Potom odšel Ježíš za moře Galilejské, jenž jest Tiberiadské.'),
(1572521,54,43,6,2,'A šel za ním zástup veliký; nebo viděli divy jeho, kteréž činil nad nemocnými.'),
(1572522,54,43,6,3,'I všel na horu Ježíš, a tam seděl s učedlníky svými.'),
(1572523,54,43,6,4,'Byla pak blízko velikanoc, svátek Židovský.'),
(1572524,54,43,6,5,'Tedy pozdvih očí Ježíš a viděv, že zástup veliký jde k němu, dí k Filipovi: Kde nakoupíme chlebů, aby pojedli tito?'),
(1572525,54,43,6,6,'(Ale to řekl pokoušeje ho; nebo on sám věděl, co by měl učiniti.)'),
(1572526,54,43,6,7,'Odpověděl jemu Filip: Za dvě stě peněz chlebů nepostačí jim, aby jeden každý z nich něco maličko vzal.'),
(1572527,54,43,6,8,'Dí jemu jeden z učedlníků jeho, Ondřej, bratr Šimona Petra:'),
(1572528,54,43,6,9,'Jestiť mládenček jeden zde, kterýž má pět chlebů ječných a dvě rybičky. Ale coť jest to mezi tak mnohé?'),
(1572529,54,43,6,10,'I řekl Ježíš: Rozkažtež lidu, ať se usadí. A bylo trávy mnoho na tom místě. I posadilo se mužů v počtu okolo pěti tisíců.'),
(1572530,54,43,6,11,'Tedy Ježíš vzal ty chleby, a díky učiniv, rozdával učedlníkům, učedlníci pak sedícím; též podobně z těch rybiček, jakž jsou mnoho chtěli.'),
(1572531,54,43,6,12,'A když byli nasyceni, řekl učedlníkům svým: Sbeřte ty drobty, kteříž zůstali, ať nezhynou.'),
(1572532,54,43,6,13,'I sebrali a naplnili dvanácte košů drobtů z pěti chlebů ječných, kteříž pozůstali po těch, jenž jedli.'),
(1572533,54,43,6,14,'Ti pak lidé, uzřevše ten div, kterýž učinil Ježíš, pravili: Tento jest jistě prorok, kterýž měl přijíti na svět.'),
(1572534,54,43,6,15,'Tedy Ježíš věda, že by měli přijíti a chytiti jej, aby ho učinili králem, ušel na horu opět sám jediný.'),
(1572535,54,43,6,16,'Když pak byl večer, sstoupili učedlníci jeho k moři.'),
(1572536,54,43,6,17,'A vstoupivše na lodí, plavili se přes moře do Kafarnaum. A bylo již tma, a nepřišel byl Ježíš k nim.'),
(1572537,54,43,6,18,'Moře pak dutím velikého větru zdvihalo se.'),
(1572538,54,43,6,19,'A odplavivše se honů jako pětmecítma nebo třidceti, uzřeli Ježíše, an chodí po moři a přibližuje se k lodí. I báli se.'),
(1572539,54,43,6,20,'On pak řekl jim: Jáť jsem, nebojte se.'),
(1572540,54,43,6,21,'I vzali ho na lodí ochotně, a hned přiběhla k zemi, do kteréž se plavili.'),
(1572541,54,43,6,22,'Nazejtří pak zástup, kterýž byl za mořem, viděv, že jiné lodičky nebylo, než ta jedna, na kterouž byli vstoupili učedlníci jeho, a že Ježíš nebyl všel s učedlníky svými na lodí, ale sami učedlníci jeho byli se plavili,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572542,54,43,6,23,'(Jiné pak lodí byly připlouly od Tiberiady k tomu místu blízko, kdežto byli jedli chléb, když díky učinil Pán,)'),
(1572543,54,43,6,24,'Když tedy uzřel zástup, že Ježíše tu není, ani učedlníků jeho, vstoupili i oni na lodí, a přijeli do Kafarnaum, hledajíce Ježíše.'),
(1572544,54,43,6,25,'A nalezše ho za mořem, řekli jemu: Mistře, kdy jsi sem přišel?'),
(1572545,54,43,6,26,'Odpověděl jim Ježíš a řekl: Amen, amen pravím vám: Hledáte mne, ne protože jste divy viděli, ale že jste jedli chleby a nasyceni jste.'),
(1572546,54,43,6,27,'Pracujte ne o pokrm, kterýž hyne, ale o ten pokrm, kterýž zůstává k životu věčnému, kterýž Syn člověka dá vám. Nebo tohoť jest potvrdil Bůh Otec.'),
(1572547,54,43,6,28,'Tedy řekli jemu: Co budeme činiti, abychom dělali dílo Boží?'),
(1572548,54,43,6,29,'Odpověděl Ježíš a řekl jim: Totoť jest to dílo Boží, abyste věřili v toho, kteréhož on poslal.'),
(1572549,54,43,6,30,'I řekli jemu: Jakéž pak ty znamení činíš, abychom viděli a věřili tobě? Co děláš?'),
(1572550,54,43,6,31,'Otcové naši jedli mannu na poušti, jakož psáno jest: Chléb s nebe dal jim jísti.'),
(1572551,54,43,6,32,'Tedy řekl Ježíš: Amen, amen pravím vám: Ne Mojžíš dal vám chléb s nebe, ale Otec můj vám dává ten chléb s nebe pravý.'),
(1572552,54,43,6,33,'Nebo chléb Boží ten jest, kterýž sstupuje s nebe a dává život světu.'),
(1572553,54,43,6,34,'A oni řekli jemu: Pane, dávejž nám chléb ten vždycky.'),
(1572554,54,43,6,35,'I řekl jim Ježíš: Jáť jsem ten chléb života. Kdož přichází ke mně, nebude nikoli lačněti, a kdož věří ve mne, nebude žízniti nikdy.'),
(1572555,54,43,6,36,'Ale pověděl jsem vám, anobrž viděli jste mne, a nevěříte.'),
(1572556,54,43,6,37,'Všecko, což mi dává Otec, ke mně přijde, a toho, kdož ke mně přijde, nevyvrhu ven.'),
(1572557,54,43,6,38,'Nebo jsem sstoupil s nebe, ne abych činil vůli svou, ale vůli toho, jenž mne poslal.'),
(1572558,54,43,6,39,'Tatoť jest pak vůle toho, kterýž mne poslal, Otcova, abych všecko, což mi dal, neztratil toho, ale vzkřísil to v nejposlednější den.'),
(1572559,54,43,6,40,'A tatoť jest vůle toho, kterýž mne poslal, aby každý, kdož vidí Syna a věří v něho, měl život věčný. A jáť jej vzkřísím v den nejposlednější.'),
(1572560,54,43,6,41,'I reptali Židé na něho, že řekl: Já jsem chléb, kterýž jsem s nebe sstoupil.'),
(1572561,54,43,6,42,'A pravili: Zdaliž tento není Ježíš, syn Jozefův, jehož my otce i matku známe? Kterak pak dí tento: S nebe jsem sstoupil?'),
(1572562,54,43,6,43,'Tedy odpověděl Ježíš a řekl jim: Nerepcete vespolek.'),
(1572563,54,43,6,44,'Však žádný nemůž přijíti ke mně, jediné leč Otec můj, kterýž mne poslal, přitrhl by jej; a jáť jej vzkřísím v den nejposlednější.'),
(1572564,54,43,6,45,'Psáno jest v Prorocích: A budou všickni učeni od Boha. Protož každý, kdož slyšel od Otce a naučil se, jdeť ke mně.'),
(1572565,54,43,6,46,'Ne že by kdo viděl Otce, jediné ten, kterýž jest od Boha, tenť jest viděl Otce.'),
(1572566,54,43,6,47,'Amen, amen pravím vám: Kdož věří ve mne, máť život věčný.'),
(1572567,54,43,6,48,'Jáť jsem ten chléb života.'),
(1572568,54,43,6,49,'Otcové vaši jedli mannu na poušti, a zemřeli.'),
(1572569,54,43,6,50,'Totoť jest chléb ten s nebe sstupující. Kdožť by koli jej jedl, neumřeť.'),
(1572570,54,43,6,51,'Jáť jsem ten chléb živý, jenž jsem s nebe sstoupil. Bude-li kdo jísti ten chléb, živ bude na věky. A chléb, kterýž já dám, tělo mé jest, kteréž já dám za život světa.'),
(1572571,54,43,6,52,'Tedy hádali se Židé vespolek, řkouce: Kterak tento může dáti nám tělo své jísti?'),
(1572572,54,43,6,53,'I řekl jim Ježíš: Amen, amen pravím vám: Nebudete-li jísti těla Syna člověka a píti krve jeho, nemáte života v sobě.'),
(1572573,54,43,6,54,'Kdož jí mé tělo a pije mou krev, máť život věčný, a jáť jej vzkřísím v nejposlednější den.'),
(1572574,54,43,6,55,'Nebo tělo mé právě jest pokrm, a krev má právě jest nápoj.'),
(1572575,54,43,6,56,'Kdo jí mé tělo a pije mou krev, ve mně přebývá a já v něm.'),
(1572576,54,43,6,57,'Jakož mne poslal ten živý Otec, a já živ jsem skrze Otce, tak kdož jí mne, i on živ bude skrze mne.'),
(1572577,54,43,6,58,'Totoť jest ten chléb, kterýž s nebe sstoupil. Ne jako otcové vaši jedli mannu, a zemřeli. Kdož jí chléb tento, živť bude na věky.'),
(1572578,54,43,6,59,'Toto mluvil Ježíš v škole, uče v Kafarnaum.'),
(1572579,54,43,6,60,'Tedy mnozí z učedlníků jeho, slyševše to, řekli: Tvrdáť jest toto řeč. Kdo ji může slyšeti?'),
(1572580,54,43,6,61,'Ale věda Ježíš sám v sobě, že by proto reptali učedlníci jeho, řekl jim: To vás uráží?'),
(1572581,54,43,6,62,'Co pak, kdybyste uzřeli Syna člověka, an vstupuje, kdež prve byl?'),
(1572582,54,43,6,63,'Duch jest, jenž obživuje, těloť nic neprospívá. Slova, kteráž já mluvím vám, Duch a život jsou.'),
(1572583,54,43,6,64,'Ale jsouť někteří z vás, ješto nevěří. Nebo věděl Ježíš od počátku, kdo by byli nevěřící, a kdo by ho měl zraditi.'),
(1572584,54,43,6,65,'I pravil: Protož jsem vám řekl, že žádný nemůže přijíti ke mně, leč by dáno bylo od Otce mého.'),
(1572585,54,43,6,66,'A z toho mnozí z učedlníků jeho odešli zpět, a nechodili s ním více.'),
(1572586,54,43,6,67,'Tedy řekl Ježíš ke dvanácti: Zdali i vy chcete odjíti?'),
(1572587,54,43,6,68,'I odpověděl jemu Šimon Petr: Pane, k komu půjdeme? A ty slova věčného života máš.'),
(1572588,54,43,6,69,'A my jsme uvěřili, a poznali, že jsi ty Kristus, Syn Boha živého.'),
(1572589,54,43,6,70,'Odpověděl jim Ježíš: Však jsem já vás dvanácte vyvolil, a jeden z vás ďábel jest.'),
(1572590,54,43,6,71,'A to řekl o Jidášovi synu Šimona Iškariotského; nebo ten jej měl zraditi, byv jeden ze dvanácti.'),
(1572591,54,43,7,1,'Potom pak chodil Ježíš po Galilei; nebo nechtěl býti v Judstvu, protože ho hledali Židé zabíti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572592,54,43,7,2,'A byl blízko svátek Židovský, památka stánků.'),
(1572593,54,43,7,3,'Tedy řekli jemu bratří jeho: Vyjdi odsud, a jdi do Judstva, ať i učedlníci tvoji vidí skutky tvé, kteréž činíš.'),
(1572594,54,43,7,4,'Nižádný zajisté v skrytě nic nedělá, kdož chce vidín býti. Protož ty, činíš-li takové věci, zjeviž se světu.'),
(1572595,54,43,7,5,'Nebo ani bratří jeho nevěřili v něho.'),
(1572596,54,43,7,6,'I dí jim Ježíš: Čas můj ještě nepřišel, ale čas váš vždycky jest hotov.'),
(1572597,54,43,7,7,'Nemůžeť vás svět nenáviděti, ale mneť nenávidí; nebo já svědectví vydávám o něm, že skutkové jeho zlí jsou.'),
(1572598,54,43,7,8,'Vy jděte k svátku tomuto. Jáť ještě nepůjdu k svátku tomuto, nebo čas můj ještě se nenaplnil.'),
(1572599,54,43,7,9,'To pověděv jim, zůstal v Galilei.'),
(1572600,54,43,7,10,'A když odešli bratří jeho, tedy i on šel k svátku, ne zjevně, ale jako ukrytě.'),
(1572601,54,43,7,11,'Židé pak hledali ho v svátek, a pravili: Kde jest onen?'),
(1572602,54,43,7,12,'A mnoho řečí bylo o něm v zástupu. Nebo někteří pravili, že dobrý jest, a jiní pravili: Není, ale svodí zástup.'),
(1572603,54,43,7,13,'Žádný však o něm nemluvil zjevně pro bázeň Židů.'),
(1572604,54,43,7,14,'Když pak již polovici svátku se vykonalo, vstoupil Ježíš do chrámu, a učil.'),
(1572605,54,43,7,15,'I divili se Židé, řkouce: Kterak tento Písmo umí, neučiv se?'),
(1572606,54,43,7,16,'Odpověděl jim Ježíš a řekl: Mé učení neníť mé, ale toho, jenž mne poslal.'),
(1572607,54,43,7,17,'Bude-li kdo chtíti vůli jeho činiti, tenť bude uměti rozeznati, jest-li to učení z Boha, čili mluvím já sám od sebe.'),
(1572608,54,43,7,18,'Kdoť sám od sebe mluví, chvály své vlastní hledá, ale kdož hledá chvály toho, kterýž ho poslal, tenť pravdomluvný jest, a nepravosti v něm není.'),
(1572609,54,43,7,19,'Však Mojžíš dal vám Zákon? a žádný z vás neplní Zákona? Proč mne hledáte zamordovati?'),
(1572610,54,43,7,20,'Odpověděl zástup a řekl: Ďábelství máš. Kdo tě hledá zamordovati?'),
(1572611,54,43,7,21,'Odpověděl Ježíš a řekl jim: Jeden skutek učinil jsem, a všickni se tomu divíte.'),
(1572612,54,43,7,22,'Mojžíš vydal vám obřízku, (ne že by z Mojžíše byla, ale z otců,) a v sobotu obřezujete člověka.'),
(1572613,54,43,7,23,'Poněvadž člověk obřízku přijímá i v sobotu, aby nebyl rušen Zákon Mojžíšův, proč pak se na mne hněváte, že jsem celého člověka uzdravil v sobotu?'),
(1572614,54,43,7,24,'Nesuďte podle osoby, ale spravedlivý soud suďte.'),
(1572615,54,43,7,25,'Tedy někteří z Jeruzalémských pravili: Zdaliž toto není ten, kteréhož hledají zabíti?'),
(1572616,54,43,7,26,'A aj, svobodně mluví, a nic mu neříkají. Zdali jsou již právě poznali knížata, že tento jest právě Kristus?'),
(1572617,54,43,7,27,'Ale o tomto víme, odkud jest, Kristus pak když přijde, žádný nebude věděti, odkud by byl.'),
(1572618,54,43,7,28,'I volal Ježíš v chrámě, uče a řka: I mne znáte, i odkud jsem, víte. A všakť jsem nepřišel sám od sebe, ale jestiť pravdomluvný, kterýž mne poslal, jehož vy neznáte.'),
(1572619,54,43,7,29,'Ale já znám jej, nebo od něho jsem, a on mne poslal.'),
(1572620,54,43,7,30,'I hledali ho jíti, ale žádný nevztáhl ruky na něho, nebo ještě byla nepřišla hodina jeho.'),
(1572621,54,43,7,31,'Z zástupu pak mnozí uvěřili v něj, a pravili: Kristus když přijde, zdali více divů činiti bude nad ty, kteréž tento činí?'),
(1572622,54,43,7,32,'Slyšeli pak farizeové zástup, an o něm takové věci rozmlouvá, i poslali farizeové a přední kněží služebníky, aby jej jali.'),
(1572623,54,43,7,33,'Tedy řekl jim Ježíš: Ještě maličký čas jsem s vámi, potom odejdu k tomu, jenž mne poslal.'),
(1572624,54,43,7,34,'Hledati mne budete, a nenaleznete, a kdež já budu, vy tam nemůžte přijíti.'),
(1572625,54,43,7,35,'I řekli Židé k sobě vespolek: Kam tento půjde, že my ho nenalezneme? Zdali v rozptýlení pohanů půjde, a bude učiti pohany?'),
(1572626,54,43,7,36,'Jaká jest to řeč, kterouž promluvil: Hledati mne budete, a nenaleznete, a kdež já budu, vy nemůžete přijíti?'),
(1572627,54,43,7,37,'V poslední pak den ten veliký svátku toho, stál Ježíš a volal, řka: Žízní-li kdo, pojď ke mně, a napij se.'),
(1572628,54,43,7,38,'Kdož věří ve mne, jakož dí Písmo, řeky z života jeho poplynou vody živé.'),
(1572629,54,43,7,39,'(A to řekl o Duchu svatém, kteréhož měli přijíti věřící v něho; nebo ještě nebyl dán Duch svatý, protože ještě Ježíš nebyl oslaven.)'),
(1572630,54,43,7,40,'Tedy mnozí z zástupu uslyševše tu řeč, pravili: Tentoť jest právě prorok.'),
(1572631,54,43,7,41,'Jiní pravili: Tentoť jest Kristus. Ale někteří pravili: Zdaliž od Galilee přijde Kristus?'),
(1572632,54,43,7,42,'Zdaž nedí písmo, že z semene Davidova a z Betléma městečka, kdež býval David, přijíti má Kristus?'),
(1572633,54,43,7,43,'A tak různice v zástupu stala se pro něj.'),
(1572634,54,43,7,44,'Někteří pak z nich chtěli ho jíti, ale žádný nevztáhl ruky na něj.'),
(1572635,54,43,7,45,'Tedy přišli služebníci k předním kněžím a k farizeům, i řekli jim oni: Proč jste ho nepřivedli?'),
(1572636,54,43,7,46,'Odpověděli služebníci: Nikdy tak člověk nemluvil, jako tento člověk.'),
(1572637,54,43,7,47,'I odpověděli jim farizeové: Zdali i vy jste svedeni?'),
(1572638,54,43,7,48,'Zdaliž kdo z knížat uvěřil v něho anebo z farizeů?'),
(1572639,54,43,7,49,'Než zástup ten, kterýž nezná Zákona. Zlořečeníť jsou.'),
(1572640,54,43,7,50,'I dí k nim Nikodém, ten, jenž byl přišel k němu v noci, kterýž byl jeden z nich:'),
(1572641,54,43,7,51,'Zdali Zákon náš soudí člověka, leč prve uslyší od něho a zví, co by činil?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572642,54,43,7,52,'Odpověděli a řekli jemu: Zdali i ty Galilejský jsi? Ptej se, žeť žádný prorok od Galilee nepovstal.'),
(1572643,54,43,7,53,'I šel jeden každý do domu svého.'),
(1572644,54,43,8,1,'Ježíš pak odšel na horu Olivetskou.'),
(1572645,54,43,8,2,'Potom na úsvitě zase přišel do chrámu, a všecken lid sšel se k němu. A on posadiv se, učil je.'),
(1572646,54,43,8,3,'I přivedli k němu zákoníci a farizeové ženu v cizoložstvu popadenou; a postavivše ji v prostředku,'),
(1572647,54,43,8,4,'Řekli jemu: Mistře, tato žena jest postižena při skutku, když cizoložila.'),
(1572648,54,43,8,5,'A v Zákoně Mojžíš přikázal nám takové kamenovati. Ty pak co pravíš?'),
(1572649,54,43,8,6,'A to řekli, pokoušejíce ho, aby jej mohli obžalovati. Ježíš pak skloniv se dolů, prstem psal na zemi.'),
(1572650,54,43,8,7,'A když se nepřestávali otazovati jeho, zdvihl se a řekl jim: Kdo jest z vás bez hříchu, nejprv hoď na ni kamenem.'),
(1572651,54,43,8,8,'A opět schýliv se, psal na zemi.'),
(1572652,54,43,8,9,'A oni uslyševše to a v svědomích svých obviněni jsouce, jeden po druhém odcházeli, počavše od starších až do posledních. I zůstal tu Ježíš sám, a žena uprostřed stojeci.'),
(1572653,54,43,8,10,'A pozdvih se Ježíš a žádného neviděv, než ženu, řekl jí: Ženo, kde jsou ti, kteříž na tebe žalovali? Žádný-li tě neodsoudil?'),
(1572654,54,43,8,11,'Kterážto řekla: Žádný, Pane. I řekl jí Ježíš: Aniž já tebe odsuzuji. Jdiž a nehřeš více.'),
(1572655,54,43,8,12,'Tedy Ježíš opět jim mluvil, řka: Já jsem Světlo světa. Kdož mne následuje, nebudeť choditi v temnostech, ale budeť míti Světlo života.'),
(1572656,54,43,8,13,'I řekli jemu farizeové: Ty sám o sobě svědectví vydáváš, svědectví tvé není pravé.'),
(1572657,54,43,8,14,'Odpověděl Ježíš a řekl jim: Ačkoli já svědectví vydávám sám o sobě, však pravé jest svědectví mé; nebo vím, odkud jsem přišel a kam jdu. Ale vy nevíte, odkud jsem přišel, anebo kam jdu.'),
(1572658,54,43,8,15,'Vy podle těla soudíte, já nesoudím žádného.'),
(1572659,54,43,8,16,'A bychť pak i soudil já, soud můj jestiť pravý; nebo nejsem sám, ale jsem já a ten, kterýž mne poslal, Otec.'),
(1572660,54,43,8,17,'A v Zákoně vašem psáno jest: Že dvou člověků svědectví pravé jest.'),
(1572661,54,43,8,18,'Jáť svědectví vydávám sám o sobě, a svědectví vydává o mně ten, kterýž mne poslal, Otec.'),
(1572662,54,43,8,19,'Tedy řekli jemu: Kdež jest ten tvůj Otec? Odpověděl Ježíš: Aniž mne znáte, ani Otce mého. Kdybyste mne znali, i Otce mého znali byste.'),
(1572663,54,43,8,20,'Tato slova mluvil Ježíš u pokladnice, uče v chrámě, a žádný ho nejal, nebo ještě byla nepřišla hodina jeho.'),
(1572664,54,43,8,21,'I řekl jim opět Ježíš: Já jdu, a hledati budete mne, a v hříchu vašem zemřete. Kam já jdu, vy nemůžete přijíti.'),
(1572665,54,43,8,22,'I pravili Židé: Zdali se sám zabije, že praví: Kam já jdu, vy nemůžete přijíti?'),
(1572666,54,43,8,23,'I řekl jim: Vy z důlu jste, já s hůry jsem. Vy jste z tohoto světa, já nejsem z světa tohoto.'),
(1572667,54,43,8,24,'Protož jsem řekl vám: Že zemřete v hříších svých. Nebo jestliže nebudete věřiti, že já jsem, zemřete v hříších vašich.'),
(1572668,54,43,8,25,'I řekli jemu: Kdo jsi ty? I řekl jim Ježíš: To, což hned s počátku pravím vám.'),
(1572669,54,43,8,26,'Mnohoť mám o vás mluviti a souditi, ale ten, kterýž mne poslal, pravdomluvný jest, a já, což jsem slyšel od něho, to mluvím na světě.'),
(1572670,54,43,8,27,'A oni neporozuměli, že by o Bohu Otci pravil jim.'),
(1572671,54,43,8,28,'Protož řekl jim Ježíš: Když povýšíte Syna člověka, tehdy poznáte, že já jsem. A sám od sebe nic nečiním, ale jakž mne naučil Otec můj, takť mluvím.'),
(1572672,54,43,8,29,'A ten, kterýž mne poslal, se mnouť jest, a neopustil mne samého Otec; nebo což jest jemu libého, to já činím vždycky.'),
(1572673,54,43,8,30,'Ty věci když mluvil, mnozí uvěřili v něho.'),
(1572674,54,43,8,31,'Tedy řekl Ježíš těm Židům, kteříž uvěřili jemu: Jestliže vy zůstanete v řeči mé, právě učedlníci moji budete.'),
(1572675,54,43,8,32,'A poznáte pravdu, a pravda vás vysvobodí.'),
(1572676,54,43,8,33,'I odpověděli jemu: Símě Abrahamovo jsme, a žádnému jsme nesloužili nikdy. I kterakž ty díš: Že svobodní budete?'),
(1572677,54,43,8,34,'Odpověděl jim Ježíš: Amen, amen pravím vám: Že každý, kdož činí hřích, služebník jest hřícha.'),
(1572678,54,43,8,35,'A služebník nezůstává v domu na věky; ale Syn zůstává na věky.'),
(1572679,54,43,8,36,'Protož jestližeť vás vysvobodí Syn, právě svobodní budete.'),
(1572680,54,43,8,37,'Vím, že jste símě Abrahamovo, ale hledáte mne zabíti; nebo řeč má nemá místa u vás.'),
(1572681,54,43,8,38,'Já, což jsem viděl u Otce svého, to mluvím; a i vy, co jste viděli u otce vašeho, to činíte.'),
(1572682,54,43,8,39,'Odpověděli a řekli jemu: Otec náš jest Abraham. Dí jim Ježíš: Kdybyste synové Abrahamovi byli, činili byste skutky Abrahamovy.'),
(1572683,54,43,8,40,'Ale nyní hledáte mne zabíti, člověka toho, kterýž jsem pravdu mluvil vám, kterouž jsem slyšel od Boha. Tohoť jest Abraham nečinil.'),
(1572684,54,43,8,41,'Vy činíte skutky otce svého. I řekli jemu: Myť z smilstva nejsme zplozeni, jednohoť Otce máme, totiž Boha.'),
(1572685,54,43,8,42,'Tedy řekl jim Ježíš: Byť Bůh Otec váš byl, milovali byste mne. Nebo já jsem z Boha pošel, a přišel jsem; aniž jsem sám od sebe přišel, ale on mne poslal.'),
(1572686,54,43,8,43,'Proč mluvení mého nechápáte? Protože hned slyšeti nemůžete řeči mé.'),
(1572687,54,43,8,44,'Vy z otce ďábla jste, a žádosti otce vašeho chcete činiti. On byl vražedník od počátku, a v pravdě nestál; nebo pravdy v něm není. Když mluví lež, z svého vlastního mluví; nebo lhář jest a otec lži.'),
(1572688,54,43,8,45,'Já pak že pravdu pravím, nevěříte mi.'),
(1572689,54,43,8,46,'Kdo z vás bude mne obviňovati z hříchu? A poněvadž pravdu pravím, proč vy mi nevěříte?'),
(1572690,54,43,8,47,'Kdo z Boha jest, slova Boží slyší; protož vy neslyšíte, že z Boha nejste.'),
(1572691,54,43,8,48,'Tedy odpověděli Židé a řekli jemu: Zdaliž my dobře nepravíme, že jsi ty Samaritán, a ďábelství máš?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572692,54,43,8,49,'Odpověděl Ježíš: Jáť ďábelství nemám, ale ctím Otce svého; než vy jste mne neuctili.'),
(1572693,54,43,8,50,'Jáť pak nehledám chvály své; jestiť, kdo hledá a soudí.'),
(1572694,54,43,8,51,'Amen, amen pravím vám: Bude-li kdo zachovávati slovo mé, smrti neuzří na věky.'),
(1572695,54,43,8,52,'Tedy řekli mu Židé: Nyní jsme poznali, že ďábelství máš. Abraham umřel i proroci, a ty pravíš: Bude-li kdo zachovávati řeč mou, smrti neokusí na věky.'),
(1572696,54,43,8,53,'Zdali jsi ty větší otce našeho Abrahama, kterýž umřel? I proroci zemřeli jsou. Kým ty se činíš?'),
(1572697,54,43,8,54,'Odpověděl Ježíš: Chválím-liť já se sám, chvála má nic není. Jestiť kterýž mne chválí, Otec můj, o němž vy pravíte, že Bůh váš jest.'),
(1572698,54,43,8,55,'A nepoznali jste ho, ale já jej znám. A kdybych řekl, že ho neznám, byl bych podobný vám, lhář. Ale známť jej, a řeč jeho zachovávám.'),
(1572699,54,43,8,56,'Abraham, otec váš, veselil se, aby viděl den můj, i viděl, a radoval se.'),
(1572700,54,43,8,57,'Tedy řekli jemu Židé: Padesáti let ještě nemáš, a Abrahama jsi viděl?'),
(1572701,54,43,8,58,'Řekl jim Ježíš: Amen, amen pravím vám: Prve nežli Abraham byl, já jsem.'),
(1572702,54,43,8,59,'I zchápali Židé kamení, aby házeli na něj. Ježíš pak skryl se, a prošed skrze ně, vyšel z chrámu, a tak jich znikl.'),
(1572703,54,43,9,1,'Pomíjeje Ježíš, uzřel člověka slepého od narození.'),
(1572704,54,43,9,2,'I otázali se učedlníci jeho, řkouce: Mistře, kdo jest zhřešil, tento-li, čili rodičové jeho, že se slepý narodil?'),
(1572705,54,43,9,3,'Odpověděl Ježíš: Ani tento nezhřešil, ani rodičové jeho, ale aby zjeveni byli skutkové Boží na něm.'),
(1572706,54,43,9,4,'Jáť musím dělati dílo toho, kterýž mne poslal, dokudž den jest. Přicházíť noc, kdyžto žádný nebude moci dělati.'),
(1572707,54,43,9,5,'Dokudž jsem na světě, Světlo jsem světa.'),
(1572708,54,43,9,6,'To pověděv, plinul na zemi, a učinil bláto z sliny, i pomazal tím blátem oči slepého.'),
(1572709,54,43,9,7,'A řekl jemu: Jdi, umej se v rybníku Siloe, jenž se vykládá: Poslaný. A on šel a umyl se, i přišel, vida.'),
(1572710,54,43,9,8,'Sousedé pak a ti, kteříž jej prve vídali slepého, řekli: Však tento jest, kterýž sedával a žebral?'),
(1572711,54,43,9,9,'Jiní pravili, že ten jest, a jiní, že jest podoben k němu. Ale on pravil: Já jsem.'),
(1572712,54,43,9,10,'Tedy řekli jemu: Kterak jsou otevříny oči tvé?'),
(1572713,54,43,9,11,'On odpověděl a řekl: Člověk ten, kterýž slove Ježíš, bláto učinil a pomazal očí mých, a řekl mi: Jdi k rybníku Siloe, a umej se. I odšed a umyv se, prohlédl jsem.'),
(1572714,54,43,9,12,'I řekli jemu: Kde jest ten člověk? Řekl: Nevím.'),
(1572715,54,43,9,13,'Tedy přivedli toho, kterýž někdy byl slepý, k farizeům.'),
(1572716,54,43,9,14,'Byla pak sobota, když Ježíš učinil bláto a otevřel oči jeho.'),
(1572717,54,43,9,15,'I tázali se ho opět i farizeové, kterak by prozřel. On pak řekl jim: Bláto položil mi na oči, a umyl jsem se, i vidím.'),
(1572718,54,43,9,16,'Tedy někteří z farizeů řekli: Tento člověk není z Boha, nebo neostříhá soboty. Jiní pravili: Kterak může člověk hříšný takové divy činiti? I byla různice mezi nimi.'),
(1572719,54,43,9,17,'Tedy řekli opět slepému: Co ty o něm pravíš, že otevřel oči tvé? A on řekl: Že prorok jest.'),
(1572720,54,43,9,18,'I nevěřili Židé o něm, by slepý byl a prozřel, až povolali rodičů toho, kterýž byl prozřel.'),
(1572721,54,43,9,19,'A otázali se jich, řkouce: Jest-li ten syn váš, o kterémž vy pravíte, že by se slepý narodil? Kterakž pak nyní vidí?'),
(1572722,54,43,9,20,'Odpověděli jim rodičové jeho a řekli: Vímeť, že tento jest syn náš a že se slepý narodil.'),
(1572723,54,43,9,21,'Ale kterak nyní vidí, nevíme; aneb kdo jest otevřel oči jeho, myť nevíme. Však má léta, ptejte se ho, on sám za sebe mluviti bude.'),
(1572724,54,43,9,22,'Tak mluvili rodičové jeho, že se báli Židů; nebo již tak byli uložili Židé, kdož by ho koli vyznal Kristem, aby byl vyobcován ze školy.'),
(1572725,54,43,9,23,'Protož řekli rodičové jeho: Máť léta, ptejte se jeho.'),
(1572726,54,43,9,24,'I zavolali po druhé člověka toho, kterýž býval slepý, a řekli jemu: Vzdej chválu Bohu. My víme, že člověk ten hříšník jest.'),
(1572727,54,43,9,25,'I odpověděl on a řekl: Jest-li hříšník, nevím, než to vím, že byv slepý, již nyní vidím.'),
(1572728,54,43,9,26,'I řekli jemu opět: Coť učinil? Kterak otevřel oči tvé?'),
(1572729,54,43,9,27,'Odpověděl jim: Již jsem vám pověděl, a neslyšeli jste? Což opět chcete slyšeti? Zdaliž i vy chcete učedlníci jeho býti?'),
(1572730,54,43,9,28,'I zlořečili jemu a řekli: Budiž ty sám učedlníkem jeho, ale myť jsme Mojžíšovi učedlníci.'),
(1572731,54,43,9,29,'My víme, že Mojžíšovi mluvil Bůh, tento pak nevíme, odkud jest.'),
(1572732,54,43,9,30,'Odpověděl ten člověk a řekl jim: Toť jest jistě divná věc, že vy nevíte, odkud jest, a otevřel oči mé.'),
(1572733,54,43,9,31,'Víme pak, že Bůh hříšníků neslyší, ale kdo by byl ctitel Boží a vůli jeho činil by, toho slyší.'),
(1572734,54,43,9,32,'Od věku není slýcháno, aby kdo otevřel oči slepého tak narozeného.'),
(1572735,54,43,9,33,'Byť tento nebyl od Boha, nemohlť by nic učiniti.'),
(1572736,54,43,9,34,'Odpověděli a řekli jemu: Ty jsi všecken se v hříších narodil, a ty náš učíš? I vyhnali jej ven.'),
(1572737,54,43,9,35,'Uslyšel pak Ježíš, že jsou jej vyhnali ven. A když jej nalezl, řekl jemu: Věříš-liž ty v Syna Božího?'),
(1572738,54,43,9,36,'Odpověděl on a řekl: I kdož jest, Pane, abych věřil v něho?'),
(1572739,54,43,9,37,'I řekl jemu Ježíš: I viděl jsi ho, a kterýž mluví s tebou, onť jest.'),
(1572740,54,43,9,38,'A on řekl: Věřím, Pane, a klaněl se jemu.'),
(1572741,54,43,9,39,'I řekl jemu Ježíš: Na soud přišel jsem já na tento svět, aby ti, kteříž nevidí, viděli, a ti, jenž vidí, aby slepí byli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572742,54,43,9,40,'I slyšeli to někteří z farizeů, kteříž s ním byli, a řekli jemu: Zdali i my slepí jsme?'),
(1572743,54,43,9,41,'Řekl jim Ježíš: Byste slepí byli, hříchu byste neměli; ale nyní pravíte: Vidíme, protož hřích váš zůstává.'),
(1572744,54,43,10,1,'Amen, amen pravím vám: Kdož nevchází dveřmi do ovčince ovcí, ale vchází jinudy, ten zloděj jest a lotr.'),
(1572745,54,43,10,2,'Ale kdož vchází dveřmi, pastýř jest ovcí.'),
(1572746,54,43,10,3,'Tomuť vrátný otvírá, a ovce hlas jeho slyší, a on svých vlastních ovec ze jména povolává, a vyvodí je.'),
(1572747,54,43,10,4,'A jakž ovce své vlastní ven vypustí, před nimi jde, a ovce jdou za ním; nebo znají hlas jeho.'),
(1572748,54,43,10,5,'Ale cizího nikoli následovati nebudou, ale utekou od něho; nebo neznají hlasů cizích.'),
(1572749,54,43,10,6,'To přísloví pověděl jim Ježíš, ale oni nevěděli, co by to bylo, což jim mluvil.'),
(1572750,54,43,10,7,'Tedy opět řekl jim Ježíš: Amen, amen pravím vám: Že já jsem dveře ovcí.'),
(1572751,54,43,10,8,'Všickni, kolikož jich koli přede mnou přišlo, zloději jsou a lotři, ale neslyšely jich ovce.'),
(1572752,54,43,10,9,'Já jsem dveře. Skrze mne všel-li by kdo, spasen bude, a vejde i vyjde, a pastvu nalezne.'),
(1572753,54,43,10,10,'Zloděj nepřichází, jediné aby kradl a mordoval a hubil; já jsem přišel, aby život měly, a hojně aby měly.'),
(1572754,54,43,10,11,'Já jsem ten pastýř dobrý. Dobrý pastýř duši svou pokládá za ovce.'),
(1572755,54,43,10,12,'Ale nájemník a ten, kterýž není pastýř, jehož nejsou ovce vlastní, vida vlka, an jde, i opouští ovce i utíká, a vlk lapá a rozhání ovce.'),
(1572756,54,43,10,13,'Nájemník pak utíká; nebo nájemník jest, a nemá péče o ovce.'),
(1572757,54,43,10,14,'Já jsem ten dobrý pastýř, a známť ovce své, a znajíť mne mé.'),
(1572758,54,43,10,15,'Jakož mne zná Otec, tak i já znám Otce, a duši svou pokládám za ovce.'),
(1572759,54,43,10,16,'A mámť i jiné ovce, kteréž nejsou z tohoto ovčince. I tyť musím přivésti, a hlas můj slyšeti budou. A budeť jeden ovčinec a jeden pastýř.'),
(1572760,54,43,10,17,'Protož mne Otec miluje, že já pokládám duši svou, abych ji zase vzal.'),
(1572761,54,43,10,18,'Nižádnýť jí nebéře ode mne, ale já pokládám ji sám od sebe. Mám moc položiti ji, a mám moc zase vzíti ji. To přikázání vzal jsem od Otce svého.'),
(1572762,54,43,10,19,'Tedy stala se opět různice mezi Židy pro ty řeči.'),
(1572763,54,43,10,20,'A pravili mnozí z nich: Ďábelství má a blázní. Co ho posloucháte?'),
(1572764,54,43,10,21,'Jiní pravili: Tato slova nejsou ďábelství majícího. Zdaliž ďábelství může slepých oči otvírati?'),
(1572765,54,43,10,22,'I bylo posvícení v Jeruzalémě, a zima byla.'),
(1572766,54,43,10,23,'I procházel se Ježíš v chrámě po síňci Šalomounově.'),
(1572767,54,43,10,24,'Tedy obstoupili jej Židé, a řekli jemu: Dokudž duši naši držíš? Jestliže jsi ty Kristus, pověz nám zjevně.'),
(1572768,54,43,10,25,'Odpověděl jim Ježíš: Pověděl jsem vám, a nevěříte. Skutkové, kteréž já činím ve jménu Otce svého, tiť svědectví vydávají o mně.'),
(1572769,54,43,10,26,'Ale vy nevěříte, nebo nejste z ovcí mých, jakož jsem vám pověděl.'),
(1572770,54,43,10,27,'Nebo ovce mé hlas můj slyší, a já je znám, a následujíť mne.'),
(1572771,54,43,10,28,'A jáť život věčný dávám jim, a nezahynouť na věky, aniž jich kdo vytrhne z ruky mé.'),
(1572772,54,43,10,29,'Otec můj, kterýž mi je dal, většíť jest nade všecky, a žádnýť jich nemůže vytrhnouti z ruky Otce mého.'),
(1572773,54,43,10,30,'Já a Otec jedno jsme.'),
(1572774,54,43,10,31,'Tedy zchápali opět kamení Židé, aby jej kamenovali.'),
(1572775,54,43,10,32,'Odpověděl jim Ježíš: Mnohé dobré skutky ukázal jsem vám od Otce svého. Pro který z těch skutků kamenujete mne?'),
(1572776,54,43,10,33,'Odpověděli jemu Židé, řkouce: Pro dobrý skutek tebe nekamenujeme, ale pro rouhání, totiž že ty, člověk jsa, děláš se Bohem.'),
(1572777,54,43,10,34,'Odpověděl jim Ježíš: Však psáno jest v Zákoně vašem: Já jsem řekl: Bohové jste.'),
(1572778,54,43,10,35,'Poněvadž ty nazval bohy, k nimžto řeč Boží stala se, a nemůžeť zrušeno býti Písmo,'),
(1572779,54,43,10,36,'Kterakž tedy o mně, kteréhož posvětil Otec a poslal na svět, vy pravíte, že se rouhám, že jsem řekl: Syn Boží jsem?'),
(1572780,54,43,10,37,'Nečiním-liť skutků Otce svého, nevěřte mi.'),
(1572781,54,43,10,38,'Pakliť činím, tedy byste pak mně nevěřili, aspoň skutkům věřte, abyste poznali a věřili, že Otec ve mně jest, a já v něm.'),
(1572782,54,43,10,39,'Tedy opět hledali ho jíti, ale on vyšel z rukou jejich.'),
(1572783,54,43,10,40,'I odšel opět za Jordán na to místo, kdež nejprv Jan křtil, a pozůstal tam.'),
(1572784,54,43,10,41,'I přišli k němu mnozí, a pravili: Jan zajisté žádného divu neučinil, ale všecko, cožkoli mluvil Jan o tomto, pravé bylo.'),
(1572785,54,43,10,42,'A mnozí tam uvěřili v něho.'),
(1572786,54,43,11,1,'Byl pak nemocen člověk nějaký jménem Lazar z Betany, totiž z městečka Marie a Marty, sestry její.'),
(1572787,54,43,11,2,'(A to byla ta Maria, kteráž pomazala Pána mastí a vytřela nohy jeho vlasy svými, jejížto bratr Lazar byl nemocen.)'),
(1572788,54,43,11,3,'Tedy poslaly k němu sestry jeho, řkouce: Pane, aj, ten, kteréhož miluješ, nemocen jest.'),
(1572789,54,43,11,4,'A uslyšav to Ježíš, řekl: Nemoc ta neníť k smrti, ale pro slávu Boží, aby oslaven byl Syn Boží skrze ni.'),
(1572790,54,43,11,5,'Miloval pak Ježíš Martu i sestru její i Lazara.'),
(1572791,54,43,11,6,'A jakž uslyšel, že by nemocen byl, i pozůstal za dva dni na tom místě, kdež byl.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572792,54,43,11,7,'Potom pak dí učedlníkům: Pojďme zase do Judstva.'),
(1572793,54,43,11,8,'Řekli jemu učedlníci: Mistře, nyní hledali tě Židé kamenovati, a ty zase tam chceš jíti?'),
(1572794,54,43,11,9,'Odpověděl Ježíš: Však dvanácte hodin za den jest. Chodí-li kdo ve dne, neurazí se; nebo světlo tohoto světa vidí.'),
(1572795,54,43,11,10,'Pakliť by kdo chodil v noci, urazíť se; nebo světla není v něm.'),
(1572796,54,43,11,11,'To pověděl, a potom dí jim: Lazar, přítel náš, spí, ale jduť, abych jej ze sna probudil.'),
(1572797,54,43,11,12,'I řekli učedlníci jeho: Pane, spí-liť, zdráv bude.'),
(1572798,54,43,11,13,'Ale Ježíš řekl o smrti jeho, oni pak domnívali se, že by o spání sna mluvil.'),
(1572799,54,43,11,14,'Tedy řekl jim Ježíš zjevně: Lazar umřel.'),
(1572800,54,43,11,15,'A raduji se pro vás, že jsem tam nebyl, abyste věřili. Ale pojďme k němu.'),
(1572801,54,43,11,16,'I řekl Tomáš, kterýž slove Didymus, spoluučedlníkům: Pojďme i my, abychom zemřeli s ním.'),
(1572802,54,43,11,17,'Tedy přišel Ježíš, i nalezl ho již čtyři dni v hrobě pochovaného.'),
(1572803,54,43,11,18,'Byla pak Betany blízko od Jeruzaléma, okolo honů patnácte.'),
(1572804,54,43,11,19,'Mnozí pak z Židů byli přišli k Martě a Mariji, aby je těšili pro smrt bratra jejich.'),
(1572805,54,43,11,20,'Tedy Marta, jakž uslyšela, že Ježíš jde, vyšla proti němu, ale Maria doma seděla.'),
(1572806,54,43,11,21,'I řekla Marta k Ježíšovi: Pane, kdybys ty byl zde, bratr můj byl by neumřel.'),
(1572807,54,43,11,22,'Ale i nyníť vím, že cožkoli požádal bys od Boha, dá tobě Bůh.'),
(1572808,54,43,11,23,'Dí jí Ježíš: Vstaneť bratr tvůj.'),
(1572809,54,43,11,24,'Řekla jemu Marta: Vím, že vstane při vzkříšení v den nejposlednější.'),
(1572810,54,43,11,25,'Řekl jí Ježíš: Já jsem vzkříšení i život. Kdo věří ve mne, byť pak i umřel, živ bude.'),
(1572811,54,43,11,26,'A každý, kdož jest živ, a věří ve mne, neumřeť na věky. Věříš-li tomu?'),
(1572812,54,43,11,27,'Řekla jemu: Ovšem, Pane, já jsem uvěřila, že jsi ty Kristus, Syn Boží, kterýž měl přijíti na svět.'),
(1572813,54,43,11,28,'A když to pověděla, odešla a zavolala tajně Marie, sestry své, řkuci: Mistr zde jest, a volá tebe.'),
(1572814,54,43,11,29,'Ona jakž to uslyšela, vstala rychle, a šla k němu.'),
(1572815,54,43,11,30,'(Ještě pak byl Ježíš nepřišel do městečka, ale byl na tom místě, kdež vyšla byla proti němu Marta.)'),
(1572816,54,43,11,31,'Tedy Židé, kteříž s ní byli v domě a těšili ji, viděvše Mariji, že jest rychle vstala a vyšla, šli za ní, řkouce: Jde k hrobu, aby tam plakala.'),
(1572817,54,43,11,32,'Ale Maria, když tam přišla, kdež byl Ježíš, uzřevši jej, padla k nohám jeho, a řekla jemu: Pane, bys ty byl zde, bratr můj byl by neumřel.'),
(1572818,54,43,11,33,'Ježíš pak jakž uzřel, ana pláče, i Židy, kteříž byli s ní přišli, ani plačí, zastonal duchem, a zkormoutil se.'),
(1572819,54,43,11,34,'A řekl: Kdež jste jej položili? Řkou jemu: Pane, pojď a pohleď.'),
(1572820,54,43,11,35,'I zaplakal Ježíš.'),
(1572821,54,43,11,36,'Tedy řekli Židé: Aj, kterak ho miloval!'),
(1572822,54,43,11,37,'Někteří pak z nich řekli: Nemohl-liž jest tento, kterýž otevřel oči slepého, učiniti i toho, aby tento neumřel?'),
(1572823,54,43,11,38,'Ježíš pak opět zastonav sám v sobě, přišel k hrobu. Byla pak jeskyně, a kámen byl svrchu položen na ni.'),
(1572824,54,43,11,39,'I dí Ježíš: Zdvihněte kámen. Řekla jemu Marta, sestra toho mrtvého: Pane, jižť smrdí; nebo čtyři dni v hrobě jest.'),
(1572825,54,43,11,40,'Dí jí Ježíš: Všakť jsem řekl, že budeš-li věřiti, uzříš slávu Boží.'),
(1572826,54,43,11,41,'Tedy zdvihli kámen, kdež byl mrtvý pochován. Ježíš pak pozdvihl vzhůru očí a řekl: Otče, děkuji tobě, že jsi mne slyšel.'),
(1572827,54,43,11,42,'Já zajisté vím, že ty mne vždycky slyšíš, ale pro zástup, kterýž okolo stojí, řekl jsem, aby věřili, že jsi ty mne poslal.'),
(1572828,54,43,11,43,'A to pověděv, zavolal hlasem velikým: Lazaře, pojď ven!'),
(1572829,54,43,11,44,'I vyšel, kterýž byl umřel, maje svázané ruce i nohy rouchami, a tvář jeho šatem byla obvinuta. Řekl jim Ježíš: Rozvěžtež jej, a nechte, ať odejde.'),
(1572830,54,43,11,45,'Tedy mnozí z Židů, kteříž byli přišli k Mariji, viděvše, co jest učinil Ježíš, uvěřili v něho.'),
(1572831,54,43,11,46,'Někteří pak z nich odešli k farizeům a pověděli jim, co jest učinil Ježíš.'),
(1572832,54,43,11,47,'I sešli se přední kněží a farizeové v radu, a pravili: Co činíme? Tento člověk divy mnohé činí.'),
(1572833,54,43,11,48,'Necháme-li ho tak, všickni uvěří v něho, i přijdou Římané, a odejmou místo naše i lid.'),
(1572834,54,43,11,49,'Jeden pak z nich, jménem Kaifáš, nejvyšším knězem jsa toho léta, řekl jim: Vy nic nevíte,'),
(1572835,54,43,11,50,'Aniž co o tom přemyšlujete, že jest užitečné nám, aby jeden člověk umřel za lid, a ne, aby všecken tento národ zahynul.'),
(1572836,54,43,11,51,'Toho pak neřekl sám od sebe, ale nejvyšším knězem byv léta toho, prorokoval, že jest měl Ježíš umříti za tento národ,'),
(1572837,54,43,11,52,'A netoliko za tento národ, ale také, aby syny Boží rozptýlené shromáždil v jedno.'),
(1572838,54,43,11,53,'Protož od toho dne spolu se o to radili, aby jej zabili.'),
(1572839,54,43,11,54,'Ježíš pak již nechodil zjevně mezi Židy, ale odšel odtud do krajiny, kteráž byla blízko pouště, do města, jenž slove Efraim, a tu bydlil s učedlníky svými.'),
(1572840,54,43,11,55,'Byla pak blízko velikanoc Židovská. I šli mnozí do Jeruzaléma z krajiny té před velikonocí, aby se očistili.'),
(1572841,54,43,11,56,'I hledali Ježíše, a rozmlouvali vespolek, v chrámě stojíce: Co se vám zdá, že nepřišel k svátku?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572842,54,43,11,57,'Vydali pak byli přední kněží a farizeové mandát, jestliže by kdo zvěděl, kde by byl, aby pověděl, aby jej jali.'),
(1572843,54,43,12,1,'Tedy Ježíš šestý den před velikonocí přišel do Betany, kdežto byl Lazar, ten kterýž byl umřel, jehož vzkřísil z mrtvých.'),
(1572844,54,43,12,2,'I připravili jemu tu večeři, a Marta posluhovala, Lazar pak byl jeden z stolících s nimi.'),
(1572845,54,43,12,3,'Maria pak vzavši libru masti drahé z nardu výborného, pomazala noh Ježíšových, a vytřela vlasy svými nohy jeho. I naplněn jest dům vůní té masti.'),
(1572846,54,43,12,4,'Tedy řekl jeden z učedlníků jeho, Jidáš, syn Šimona Iškariotského, kterýž jej měl zraditi:'),
(1572847,54,43,12,5,'Proč tato mast není prodána za tři sta peněz, a není dáno chudým?'),
(1572848,54,43,12,6,'To pak řekl, ne že by měl péči o chudé, ale že zloděj byl, a měšec měl, a to, což do něho kladeno bylo, nosil.'),
(1572849,54,43,12,7,'Tedy řekl Ježíš: Nech jí, ke dni pohřebu mého zachovala to.'),
(1572850,54,43,12,8,'Chudé zajisté vždycky máte s sebou, ale mne ne vždycky míti budete.'),
(1572851,54,43,12,9,'Zvěděl pak zástup veliký z Židů o něm, že by tu byl. I přišli tam, ne pro Ježíše toliko, ale také, aby Lazara viděli, kteréhož byl vzkřísil z mrtvých.'),
(1572852,54,43,12,10,'Radili se pak přední kněží, aby i Lazara zamordovali.'),
(1572853,54,43,12,11,'Nebo mnozí z Židů odcházeli pro něho, a uvěřili v Ježíše.'),
(1572854,54,43,12,12,'Potom nazejtří mnohý zástup, kterýž byl přišel k svátku velikonočnímu, když uslyšeli, že Ježíš jde do Jeruzaléma,'),
(1572855,54,43,12,13,'Nabrali ratolestí palmových, a vyšli proti němu, a volali: Spas nás! Požehnaný, jenž se béře ve jménu Páně, Král Izraelský.'),
(1572856,54,43,12,14,'I dostav Ježíš oslátka, vsedl na ně, jakož psáno jest:'),
(1572857,54,43,12,15,'Neboj se, dcero Sionská, aj, Král tvůj béře se, na oslátku sedě.'),
(1572858,54,43,12,16,'Tomu pak nesrozuměli učedlníci jeho zprvu, ale když oslaven byl Ježíš, tedy se rozpomenuli, že jest to psáno bylo o něm a že jemu to učinili.'),
(1572859,54,43,12,17,'Vydával pak o něm svědectví zástup, kterýž byl s ním, že Lazara povolal z hrobu a vzkřísil jej z mrtvých.'),
(1572860,54,43,12,18,'Protož i v cestu vyšel jemu zástup, když slyšeli, že by ten div učinil.'),
(1572861,54,43,12,19,'Tedy farizeové pravili mezi sebou: Vidíte, že nic neprospíváte? Aj, všecken svět postoupil po něm.'),
(1572862,54,43,12,20,'Byli pak někteří Řekové z těch, kteříž přicházívali, aby se modlili v svátek.'),
(1572863,54,43,12,21,'Ti také přistoupili k Filipovi, kterýž byl od Betsaidy Galilejské, a prosili ho, řkouce: Pane, chtěli bychom Ježíše viděti.'),
(1572864,54,43,12,22,'Přišel Filip a pověděl Ondřejovi, Ondřej pak a Filip pověděli Ježíšovi.'),
(1572865,54,43,12,23,'A Ježíš odpověděl jim, řka: Přišlať jest hodina, aby oslaven byl Syn člověka.'),
(1572866,54,43,12,24,'Amen, amen pravím vám: Zrno pšeničné padna v zemi, neumře-li, onoť samo zůstane, a pakliť umře, mnohý užitek přinese.'),
(1572867,54,43,12,25,'Kdož miluje duši svou, ztratíť ji; a kdož nenávidí duše své na tomto světě, k životu věčnému ostříhá jí.'),
(1572868,54,43,12,26,'Slouží-li mi kdo, následujž mne; a kdež jsem já, tuť i můj služebník bude. A bude-li mi kdo sloužiti, poctíť ho Otec můj.'),
(1572869,54,43,12,27,'Nyní duše má zkormoucena jest, a což dím? Otče, vysvoboď mne z této hodiny. Ale proto jsem přišel k hodině této.'),
(1572870,54,43,12,28,'Otče, oslaviž jméno své. Tedy přišel hlas s nebe řkoucí: I oslavil jsem, i ještě oslavím.'),
(1572871,54,43,12,29,'Ten pak zástup, kterýž tu stál a to slyšel, pravil: Zahřmělo. Jiní pravili: Anděl k němu mluvil.'),
(1572872,54,43,12,30,'Odpověděl Ježíš a řekl: Ne pro mneť hlas tento se stal, ale pro vás.'),
(1572873,54,43,12,31,'Nyníť jest soud světa tohoto, nyní kníže světa tohoto vyvrženo bude ven.'),
(1572874,54,43,12,32,'A já budu-liť povýšen od země, všecky potáhnu k sobě.'),
(1572875,54,43,12,33,'(To pak pověděl, znamenaje, kterou by smrtí měl umříti.)'),
(1572876,54,43,12,34,'Odpověděl jemu zástup: My jsme slyšeli z Zákona, že Kristus zůstává na věky, a kterakž ty pravíš, že musí býti povýšen Syn člověka? Kdo jest to Syn člověka?'),
(1572877,54,43,12,35,'Tedy řekl jim Ježíš: Ještě na malý čas Světlo s vámi jest. Choďte, dokud Světlo máte, ať vás tma nezachvátí; nebo kdo chodí ve tmách, neví, kam jde.'),
(1572878,54,43,12,36,'Dokud Světlo máte, věřte v Světlo, abyste synové Světla byli. Toto pověděl Ježíš, a odšed, skryl se před nimi.'),
(1572879,54,43,12,37,'A ačkoli tak mnohá znamení činil před nimi, však jsou neuvěřili v něho,'),
(1572880,54,43,12,38,'Aby se naplnila řeč Izaiáše proroka, kterouž pověděl: Pane, kdo uvěřil kázaní našemu a rámě Páně komu jest zjeveno?'),
(1572881,54,43,12,39,'Ale protoť jsou nemohli věřiti, neb opět Izaiáš řekl:'),
(1572882,54,43,12,40,'Oslepil oči jejich a zatvrdil srdce jejich, aby očima neviděli a srdcem nerozuměli a neobrátili se, abych jich neuzdravil.'),
(1572883,54,43,12,41,'To pověděl Izaiáš, když viděl slávu jeho a mluvil o něm.'),
(1572884,54,43,12,42,'A ačkoli mnozí z knížat uvěřili v něho, však pro farizee nevyznávali ho, aby ze školy nebyli vyobcováni.'),
(1572885,54,43,12,43,'Nebo milovali slávu lidskou více než slávu Boží.'),
(1572886,54,43,12,44,'Ježíš pak zvolal a řekl: Kdo věří ve mne, ne ve mneť věří, ale v toho, jenž mne poslal.'),
(1572887,54,43,12,45,'A kdož vidí mne, vidí toho, kterýž mne poslal.'),
(1572888,54,43,12,46,'Já Světlo na svět jsem přišel, aby žádný, kdož věří ve mne, ve tmě nezůstal.'),
(1572889,54,43,12,47,'A slyšel-liť by kdo slova má, a nevěřil by, jáť ho nesoudím; nebo nepřišel jsem, abych soudil svět, ale abych spasen učinil svět.'),
(1572890,54,43,12,48,'Kdož mnou pohrdá a nepřijímá slov mých, máť, kdo by jej soudil. Slova, kteráž jsem mluvil, tať jej souditi budou v nejposlednější den.'),
(1572891,54,43,12,49,'Nebo já sám od sebe jsem nemluvil, ale ten, jenž mne poslal, Otec, on mi přikázaní dal, co bych měl praviti a mluviti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572892,54,43,12,50,'A vím, že přikázání jeho jest život věčný. A protož, což já mluvím, jakž mi pověděl Otec, takť mluvím.'),
(1572893,54,43,13,1,'Před svátkem pak velikonočním, věda Ježíš, že přišla hodina jeho, aby šel z tohoto světa k Otci, milovav své, kteříž byli na světě, až do konce je miloval.'),
(1572894,54,43,13,2,'A když večeřeli, (a ďábel již byl vnukl v srdce Jidáše Šimona Iškariotského, aby jej zradil,)'),
(1572895,54,43,13,3,'Věda Ježíš, že jemu Otec všecko v ruce dal a že od Boha vyšel a k Bohu jde,'),
(1572896,54,43,13,4,'Vstal od večeře, a složil roucho své, a vzav rouchu, přepásal se.'),
(1572897,54,43,13,5,'Potom nalil vody do medenice, i počal umývati nohy učedlníků a vytírati rouchou, kterouž byl přepásán.'),
(1572898,54,43,13,6,'Tedy přišel k Šimonovi Petrovi. A on řekl jemu: Pane, ty mi chceš nohy mýti?'),
(1572899,54,43,13,7,'Odpověděl Ježíš a řekl jemu: Co já činím, ty nevíš nyní, ale potom zvíš.'),
(1572900,54,43,13,8,'Dí jemu Petr: Nebudeš ty mýti noh mých na věky. Odpověděl jemu Ježíš: Neumyji-liť tebe, nebudeš míti dílu se mnou.'),
(1572901,54,43,13,9,'Dí jemu Šimon Petr: Pane, netoliko nohy mé, ale i ruce i hlavu.'),
(1572902,54,43,13,10,'Řekl jemu Ježíš: Kdož jest umyt, nepotřebuje, než aby nohy umyl; nebo čist jest všecken. I vy čistí jste, ale ne všickni.'),
(1572903,54,43,13,11,'Nebo věděl o zrádci svém; protož řekl: Ne všickni čistí jste.'),
(1572904,54,43,13,12,'Když pak umyl nohy jejich a vzal na sebe roucho své, posadiv se za stůl zase, řekl jim: Víte-liž, co jsem učinil vám?'),
(1572905,54,43,13,13,'Vy nazýváte mne Mistrem a Pánem, a dobře pravíte, jsemť zajisté.'),
(1572906,54,43,13,14,'Poněvadž tedy já umyl jsem nohy vaše, Pán a Mistr, i vy máte jeden druhému nohy umývati.'),
(1572907,54,43,13,15,'Příklad zajisté dal jsem vám, abyste, jakož jsem já učinil vám, i vy též činili.'),
(1572908,54,43,13,16,'Amen, amen pravím vám: Není služebník větší pána svého, ani posel větší nežli ten, kdož jej poslal.'),
(1572909,54,43,13,17,'Znáte-li tyto věci, blahoslavení jste, budete-li je činiti.'),
(1572910,54,43,13,18,'Ne o všechť vás pravím. Já vím, které jsem vyvolil, ale musí to býti, aby se naplnilo písmo: Ten, jenž jí chléb se mnou, pozdvihl proti mně paty své.'),
(1572911,54,43,13,19,'Nyní pravím vám, prve než by se to stalo, abyste, když se stane, uvěřili, že já jsem.'),
(1572912,54,43,13,20,'Amen, amen pravím vám: Kdo přijímá toho, kohož bych já poslal, mneť přijímá; a kdož mne přijímá, přijímá toho, kterýž mne poslal.'),
(1572913,54,43,13,21,'A to pověděv Ježíš, zkormoutil se v duchu, a osvědčil, řka: Amen, amen pravím vám, že jeden z vás mne zradí.'),
(1572914,54,43,13,22,'Tedy učedlníci vzhlédali na sebe vespolek, pochybujíce, o kom by to pravil.'),
(1572915,54,43,13,23,'Byl pak jeden z učedlníků Ježíšových, kterýž zpolehl na klíně jeho, jehož miloval Ježíš.'),
(1572916,54,43,13,24,'Protož tomu návěští dal Šimon Petr, aby se zeptal, kdo by to byl, o němž praví?'),
(1572917,54,43,13,25,'A on odpočívaje na prsech Ježíšových, řekl jemu: Pane, kdo jest?'),
(1572918,54,43,13,26,'Odpověděl Ježíš: Ten jest, komuž já omočené skyvy chleba podám. A omočiv skyvu chleba, podal Jidášovi, synu Šimona Iškariotského.'),
(1572919,54,43,13,27,'A hned po vzetí toho chleba vstoupil do něho satan. I řekl jemu Ježíš: Co činíš, čiň spěšně.'),
(1572920,54,43,13,28,'Tomu pak žádný z přísedících nerozuměl, k čemu by jemu to řekl.'),
(1572921,54,43,13,29,'Nebo někteří se domnívali, poněvadž Jidáš měšec měl, že by jemu řekl Ježíš: Nakup těch věcí, kterýchž jest nám potřebí k svátku, anebo aby něco chudým dal.'),
(1572922,54,43,13,30,'A on vzav skyvu chleba, hned vyšel. A byla již noc.'),
(1572923,54,43,13,31,'Když pak on vyšel, dí Ježíš: Nyníť oslaven jest Syn člověka, a Bůh oslaven jest v něm.'),
(1572924,54,43,13,32,'A poněvadž Bůh oslaven jest v něm, i Bůh oslaví jej sám v sobě, a to hned oslaví jej.'),
(1572925,54,43,13,33,'Synáčkové, ještě maličko s vámi jsem. Hledati mne budete, a jakož jsem řekl Židům: Kam já jdu, vy nemůžete přijíti, tak i vám pravím nyní.'),
(1572926,54,43,13,34,'Přikázání nové dávám vám, abyste se milovali vespolek; jakož já miloval jsem vás, tak abyste i vy milovali jeden druhého.'),
(1572927,54,43,13,35,'Po tomť poznají všickni, že jste moji učedlníci, budete-li míti lásku jedni k druhým.'),
(1572928,54,43,13,36,'Dí jemu Šimon Petr: Pane, kam jdeš? Odpověděl mu Ježíš: Kam já jdu, nemůžeš ty nyní jíti za mnou, ale půjdeš potom.'),
(1572929,54,43,13,37,'Dí jemu Petr: Pane, proč bych nemohl nyní jíti za tebou? A já duši svou za tebe položím.'),
(1572930,54,43,13,38,'Odpověděl jemu Ježíš: Duši svou za mne položíš? Amen pravím tobě: Nezazpíváť kohout, až mne třikrát zapříš.'),
(1572931,54,43,14,1,'Nermutiž se srdce vaše. Věříte v Boha, i ve mne věřte.'),
(1572932,54,43,14,2,'V domu Otce mého příbytkové mnozí jsou. Byť nebylo tak, pověděl bych vám.'),
(1572933,54,43,14,3,'Jduť, abych vám připravil místo. A odejdu-liť, a připravím vám místo, zaseť přijdu, a poberu vás k sobě samému, abyste, kde jsem já, i vy byli.'),
(1572934,54,43,14,4,'A kam já jdu, víte, i cestu víte.'),
(1572935,54,43,14,5,'Dí jemu Tomáš: Pane, nevíme, kam jdeš. A kterak můžeme cestu věděti?'),
(1572936,54,43,14,6,'Dí jemu Ježíš: Já jsem cesta, i pravda, i život. Žádný nepřichází k Otci než skrze mne.'),
(1572937,54,43,14,7,'Byste znali mne, také i Otce mého znali byste; a již nyní jej znáte, a viděli jste ho.'),
(1572938,54,43,14,8,'Řekl jemu Filip: Pane, ukaž nám Otce, a dostiť jest nám.'),
(1572939,54,43,14,9,'Dí jemu Ježíš: Tak dlouhý čas s vámi jsem, a nepoznal jsi mne? Filipe, kdož vidí mne, vidí Otce, a kterak ty pravíš: Ukaž nám Otce?'),
(1572940,54,43,14,10,'A což nevěříš, že já v Otci a Otec ve mně jest? Slova, kteráž já mluvím vám, sám od sebe nemluvím, ale Otec ve mně přebývaje, onť činí skutky.'),
(1572941,54,43,14,11,'Věřtež mi, že jsem já v Otci a Otec ve mně; nebo aspoň pro samy skutky věřte mi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572942,54,43,14,12,'Amen, amen pravím vám: Kdož věří ve mne, skutky, kteréž já činím, i on činiti bude, a větší nad ty činiti bude. Nebo já jdu k Otci svému.'),
(1572943,54,43,14,13,'A jestliže byste co prosili ve jménu mém, toť učiním, aby oslaven byl Otec v Synu.'),
(1572944,54,43,14,14,'Budete-li zač prositi ve jménu mém, jáť učiním.'),
(1572945,54,43,14,15,'Milujete-li mne, přikázání mých ostříhejte.'),
(1572946,54,43,14,16,'A jáť prositi budu Otce, a jiného Utěšitele dá vám, aby s vámi zůstal na věky,'),
(1572947,54,43,14,17,'Ducha pravdy, jehož svět nemůže přijíti. Nebo nevidí ho, aniž ho zná, ale vy znáte jej, nebť u vás přebývá a v vás bude.'),
(1572948,54,43,14,18,'Neopustímť vás sirotků, přijduť k vám.'),
(1572949,54,43,14,19,'Ještě maličko, a svět mne již neuzří, ale vy uzříte mne; nebo já živ jsem, a i vy živi budete.'),
(1572950,54,43,14,20,'V ten den vy poznáte, že já jsem v Otci svém, a vy ve mně, a já v vás.'),
(1572951,54,43,14,21,'Kdož by měl přikázaní má a ostříhal jich, onť jest ten, kterýž mne miluje. A kdož mne miluje, milován bude od Otce mého, a jáť jej budu milovati a zjevím jemu samého sebe.'),
(1572952,54,43,14,22,'Řekl jemu Judas, ne onen Iškariotský: Pane, jakž jest to, že sebe nám zjeviti chceš, a ne světu?'),
(1572953,54,43,14,23,'Odpověděl Ježíš a řekl jemu: Miluje-li mne kdo, slova mého ostříhati bude, a Otec můj bude jej milovati, a k němu přijdeme, a příbytek u něho učiníme.'),
(1572954,54,43,14,24,'Kdož pak nemiluje mne, slov mých neostříhá; a slovo, kteréž slyšíte, neníť mé, ale toho, kterýž mne poslal, Otcovo.'),
(1572955,54,43,14,25,'Toto mluvil jsem vám, u vás přebývaje.'),
(1572956,54,43,14,26,'Utěšitel pak, ten Duch svatý, kteréhož pošle Otec ve jménu mém, onť vás naučí všemu a připomeneť vám všecko, což jsem koli mluvil vám.'),
(1572957,54,43,14,27,'Pokoj zůstavuji vám, pokoj můj dávám vám; ne jako svět dává, já dávám vám. Nermutiž se srdce vaše, ani strachuj.'),
(1572958,54,43,14,28,'Slyšeli jste, že já řekl jsem vám: Jdu, a zase přijdu k vám. Kdybyste mne milovali, radovali byste se jistě, že jsem řekl: Jdu k Otci; nebo Otec větší mne jest.'),
(1572959,54,43,14,29,'A nyní pověděl jsem vám, prve nežli by se stalo, abyste, když se stane, uvěřili.'),
(1572960,54,43,14,30,'Již nemnoho mluviti budu s vámi; neboť jde Kníže tohoto světa, ale nemáť nic na mně.'),
(1572961,54,43,14,31,'Ale aby poznal svět, že miluji Otce, a jakož mi přikázání dal Otec, tak činím. Vstaňte, pojďme odtud.'),
(1572962,54,43,15,1,'Já jsem ten vinný kmen pravý, a Otec můj vinař jest'),
(1572963,54,43,15,2,'Každou ratolest, kteráž ve mně nenese ovoce, odřezuje, a každou, kteráž nese ovoce, čistí, aby hojnější ovoce nesla.'),
(1572964,54,43,15,3,'Již vy čisti jste pro řeč, kterouž jsem mluvil vám.'),
(1572965,54,43,15,4,'Zůstaňtež ve mně, a já v vás. Jakož ratolest nemůže nésti ovoce sama od sebe, nezůstala-li by při kmenu, takž ani vy, leč zůstanete ve mně.'),
(1572966,54,43,15,5,'Já jsem vinný kmen a vy ratolesti. Kdo zůstává ve mně, a já v něm, ten nese ovoce mnohé; nebo beze mne nic nemůžete učiniti.'),
(1572967,54,43,15,6,'Nezůstal-li by kdo ve mně, vyvržen bude ven jako ratolest, a uschneť, a sberouť ty ratolesti a na oheň uvrhou a shoříť.'),
(1572968,54,43,15,7,'Zůstanete-li ve mně, a slova má zůstanou-liť v vás, což byste koli chtěli, proste, a staneť se vám.'),
(1572969,54,43,15,8,'V tomť bývá oslaven Otec můj, když ovoce nesete hojné, a takť budete moji učedlníci.'),
(1572970,54,43,15,9,'Jakož miloval mne Otec, tak i já miloval jsem vás. Zůstaňtež v milování mém.'),
(1572971,54,43,15,10,'Budete-li zachovávati přikázaní má, zůstanete v mém milování, jakož i já přikázání Otce svého zachoval jsem, i zůstávám v jeho milování.'),
(1572972,54,43,15,11,'Toto mluvil jsem vám, aby radost má zůstala v vás, a radost vaše aby byla plná.'),
(1572973,54,43,15,12,'Totoť jest přikázání mé, abyste se milovali vespolek, jako i já miloval jsem vás.'),
(1572974,54,43,15,13,'Většího milování nad to žádný nemá, než aby duši svou položil za přátely své.'),
(1572975,54,43,15,14,'Vy přátelé moji jste, učiníte-li to, což já přikazuji vám.'),
(1572976,54,43,15,15,'Již vás nebudu více nazývati služebníky, nebo služebník neví, co by činil pán jeho. Ale vás jsem nazval přáteli, nebo všecko, což jsem koli slyšel od Otce svého, oznámil jsem vám.'),
(1572977,54,43,15,16,'Ne vy jste mne vyvolili, ale já jsem vás vyvolil a postavil, abyste šli a ovoce přinesli, a ovoce vaše aby zůstalo, aby zač byste koli prosili Otce ve jménu mém, dal vám.'),
(1572978,54,43,15,17,'To přikazuji vám, abyste se milovali vespolek.'),
(1572979,54,43,15,18,'Jestližeť vás svět nenávidí, víte, žeť jest mne prve než vás v nenávisti měl.'),
(1572980,54,43,15,19,'Byste byli z světa, svět, což jest jeho, miloval by; že pak nejste z světa, ale já z světa vyvolil jsem vás, protož vás svět nenávidí.'),
(1572981,54,43,15,20,'Pamatujte na řeč mou, kterouž jsem já mluvil vám: Neníť služebník větší nežli pán jeho. Poněvadž se mně protivili, i vámť se protiviti budou; poněvadž jsou řeči mé šetřili, i vaší šetřiti budou.'),
(1572982,54,43,15,21,'Ale toto všecko učiní vám pro jméno mé; nebo neznají toho, jenž mne poslal.'),
(1572983,54,43,15,22,'Kdybych byl nepřišel a nemluvil jim, hříchu by neměli; ale nyní výmluvy nemají z hříchu svého.'),
(1572984,54,43,15,23,'Kdož mne nenávidí, i Otceť mého nenávidí.'),
(1572985,54,43,15,24,'Bych byl skutků nečinil mezi nimi, jichžto žádný jiný nečinil, hříchu by neměli; ale nyní jsou i viděli, i nenáviděli, i mne i Otce mého.'),
(1572986,54,43,15,25,'Ale musilo tak býti, aby se naplnila řeč, kteráž v Zákoně jejich napsána jest: Že v nenávisti měli mne bez příčiny.'),
(1572987,54,43,15,26,'Když pak přijde Utěšitel, kteréhož já pošli vám od Otce, Duch pravdy, kterýž od Otce pochází, tenť svědectví vydávati bude o mně.'),
(1572988,54,43,15,27,'Ano i vy svědectví vydávati budete, nebo od počátku se mnou jste.'),
(1572989,54,43,16,1,'Toto mluvil jsem vám, abyste se nezhoršili.'),
(1572990,54,43,16,2,'Vypovědíť vás ze škol, ano přijdeť čas, že všeliký, kdož vás mordovati bude, domnívati se bude, že tím Bohu slouží.'),
(1572991,54,43,16,3,'A toť učiní vám proto, že nepoznali Otce ani mne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1572992,54,43,16,4,'Ale toto mluvil jsem vám, abyste, když přijde ten čas, rozpomenuli se na to, že jsem já to předpověděl vám. Tohoť jsem vám s počátku nemluvil, neb jsem byl s vámi.'),
(1572993,54,43,16,5,'Nyní pak jdu k tomu, kterýž mne poslal, a žádný z vás neptá se mne: Kam jdeš?'),
(1572994,54,43,16,6,'Ale že jsem vám tyto věci mluvil, zámutek naplnil srdce vaše.'),
(1572995,54,43,16,7,'Já pak pravdu pravím vám, že jest vám užitečné, abych já odšel. Nebo neodejdu-liť, Utěšitel nepřijde k vám; a pakliť odejdu, pošli ho k vám.'),
(1572996,54,43,16,8,'A onť přijda, obviňovati bude svět z hříchu, a z spravedlnosti, a z soudu.'),
(1572997,54,43,16,9,'Z hříchu zajisté, že nevěří ve mne;'),
(1572998,54,43,16,10,'A z spravedlnosti, že jdu k Otci, a již více neuzříte mne;'),
(1572999,54,43,16,11,'Z soudu pak, že Kníže tohoto světa již jest odsouzeno.'),
(1573000,54,43,16,12,'Ještěť bych měl mnoho mluviti vám, ale nemůžete snésti nyní.'),
(1573001,54,43,16,13,'Ale když přijde ten Duch pravdy, uvedeť vás ve všelikou pravdu. Nebo nebude mluviti sám od sebe, ale cožkoli uslyší, toť mluviti bude; ano i budoucí věci zvěstovati bude vám.'),
(1573002,54,43,16,14,'Onť mne oslaví; nebo z mého vezme, a zvěstuje vám.'),
(1573003,54,43,16,15,'Všecko, cožkoli má Otec, mé jest. Protož jsem řekl, že z mého vezme, a zvěstuje vám.'),
(1573004,54,43,16,16,'Maličko, a neuzříte mne, a opět maličko, a uzříte mne; nebo já jdu k Otci.'),
(1573005,54,43,16,17,'I řekli někteří z učedlníků jeho mezi sebou: Co jest to, že praví nám: Maličko, a neuzříte mne, a opět maličko, a uzříte mne, a že já jdu k Otci?'),
(1573006,54,43,16,18,'Protož pravili: Co jest to, že praví: Maličko? Nevíme, co praví.'),
(1573007,54,43,16,19,'I poznal Ježíš, že se ho chtěli otázati. I řekl jim: O tom tížete mezi sebou, že jsem řekl: Maličko, a neuzříte mne, a opět maličko, a uzříte mne?'),
(1573008,54,43,16,20,'Amen, amen pravím vám, že plakati a kvíliti budete vy, ale svět se bude radovati; vy pak se budete rmoutiti, ale zámutek váš obrátíť se v radost.'),
(1573009,54,43,16,21,'Žena, když rodí, zámutek má, nebo přišla hodina její; ale když porodí dítě, již nepamatuje na soužení, pro radost, že se narodil člověk na svět.'),
(1573010,54,43,16,22,'Protož i vy zámutek máte nyní, ale opět uzřím vás, a radovati se bude srdce vaše, a radosti vaší žádný neodejme od vás.'),
(1573011,54,43,16,23,'A v ten den nebudete se mne tázati o ničemž. Amen, amen pravím vám: Že zač byste koli prosili Otce ve jménu mém, dáť vám.'),
(1573012,54,43,16,24,'Až dosavad za nic jste neprosili ve jménu mém. Prostež, a vezmete, aby radost vaše doplněna byla.'),
(1573013,54,43,16,25,'Toto v příslovích mluvil jsem vám; přijdeť hodina, když již ne v příslovích budu mluviti vám, ale zjevně o Otci svém zvěstovati budu vám.'),
(1573014,54,43,16,26,'V ten den ve jménu mém prositi budete, a nepravímť vám, že já budu prositi Otce za vás.'),
(1573015,54,43,16,27,'Nebo sám Otec miluje vás, proto že jste vy mne milovali, a uvěřili, že jsem já od Boha vyšel.'),
(1573016,54,43,16,28,'Vyšelť jsem od Otce, a přišel jsem na svět; a opět opouštím svět, a jdu k Otci.'),
(1573017,54,43,16,29,'Řkou jemu učedlníci jeho: Aj, nyní zjevně mluvíš, a přísloví žádného nepravíš.'),
(1573018,54,43,16,30,'Nyní víme, že víš všecko, a nepotřebuješ, aby se kdo tebe tázal. Skrze to věříme, že jsi od Boha přišel.'),
(1573019,54,43,16,31,'Odpověděl jim Ježíš: Nyní věříte.'),
(1573020,54,43,16,32,'Aj, přijdeť hodina, anobrž již přišla, že se rozprchnete jeden každý k svému, a mne samého necháte. Ale nejsemť sám, nebo Otec se mnou jest.'),
(1573021,54,43,16,33,'Tyto věci mluvil jsem vám, abyste ve mně pokoj měli. Na světě soužení míti budete, ale doufejtež, jáť jsem přemohl svět.'),
(1573022,54,43,17,1,'To pověděv Ježíš, i pozdvihl očí svých k nebi a řekl: Otče, přišlať jest hodina, oslaviž Syna svého, aby i Syn tvůj oslavil tebe;'),
(1573023,54,43,17,2,'Jakož jsi dal jemu moc nad každým člověkem, aby těm všechněm, kteréž jsi dal jemu, on život věčný dal.'),
(1573024,54,43,17,3,'Totoť jest pak věčný život, aby poznali tebe samého pravého Boha, a kteréhož jsi poslal, Ježíše Krista.'),
(1573025,54,43,17,4,'Jáť jsem oslavil tebe na zemi; dílo jsem vykonal, kteréž jsi mi dal, abych činil.'),
(1573026,54,43,17,5,'A nyní oslaviž ty mne, Otče, u sebe samého, slávou, kterouž jsem měl u tebe, prve nežli svět byl.'),
(1573027,54,43,17,6,'Oznámil jsem jméno tvé lidem, kteréž jsi mi dal z světa. Tvojiť jsou byli, a mně jsi je dal, a řeč tvou zachovali.'),
(1573028,54,43,17,7,'A nyní poznali, že všecky věci, kteréž jsi mi dal, od tebe jsou.'),
(1573029,54,43,17,8,'Nebo slova, kteráž jsi mi dal, dal jsem jim; a oni přijali, a poznali vpravdě, že jsem od tebe vyšel, a uvěřili, že jsi ty mne poslal.'),
(1573030,54,43,17,9,'Já za ně prosím, ne za svět prosím, ale za ty, kteréž jsi mi dal, nebo tvoji jsou.'),
(1573031,54,43,17,10,'A všecky věci mé tvé jsou, a tvé mé jsou, a já oslaven jsem v nich.'),
(1573032,54,43,17,11,'Již pak více nejsem na světě, ale oni jsou na světě, a já k tobě jdu. Otče svatý, ostříhejž jich ve jménu svém, kteréž jsi mi dal, ať by byli jedno jako i my.'),
(1573033,54,43,17,12,'Dokudž jsem s nimi byl na světě, já jsem jich ostříhal ve jménu tvém. Kteréž jsi mi dal, zachoval jsem, a žádný z nich nezahynul, než syn zatracení, aby #se Písmo naplnilo.'),
(1573034,54,43,17,13,'Ale nyní k tobě jdu, a toto mluvím na světě, aby měli radost mou plnou v sobě.'),
(1573035,54,43,17,14,'Já jsem jim dal slovo tvé, a svět jich nenáviděl; nebo nejsou z světa, jako i já nejsem z světa.'),
(1573036,54,43,17,15,'Neprosímť, abys je vzal z světa, ale abys jich zachoval od zlého.'),
(1573037,54,43,17,16,'Z světať nejsou, jakož i já nejsem z světa.'),
(1573038,54,43,17,17,'Posvětiž jich v pravdě své, slovo tvé pravda jest.'),
(1573039,54,43,17,18,'Jakož jsi mne poslal na svět, i já jsem je poslal na svět.'),
(1573040,54,43,17,19,'A já posvěcuji sebe samého za ně, aby i oni posvěceni byli v pravdě.'),
(1573041,54,43,17,20,'Ne za tytoť pak toliko prosím, ale i za ty, kteříž skrze slovo jejich mají uvěřiti ve mne,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573042,54,43,17,21,'Aby všickni jedno byli, jako ty, Otče, ve mně, a já v tobě, aby i oni v nás jedno byli, aby uvěřil svět, že jsi ty mne poslal.'),
(1573043,54,43,17,22,'A já slávu, kterouž jsi mi dal, dal jsem jim, aby byli jedno, jakož i my jedno jsme.'),
(1573044,54,43,17,23,'Já v nich, a ty ve mně, aby dokonáni byli v jedno, a aby poznal svět, že jsi ty mne poslal, a že jsi je miloval, jakožs i mne miloval.'),
(1573045,54,43,17,24,'Otče, kteréž jsi mi dal, chciť, kdež jsem já, aby i oni byli se mnou, aby hleděli na slávu mou, kteroužs mi dal; nebo jsi mne miloval před ustanovením světa.'),
(1573046,54,43,17,25,'Otče spravedlivý, tebeť jest svět nepoznal, ale já jsem tebe poznal, a i tito poznali, že jsi ty mne poslal.'),
(1573047,54,43,17,26,'A známéť jsem jim učinil jméno tvé, a ještě známo učiním, aby to milování, kterýmž jsi mne miloval, bylo v nich, a i já v nich.'),
(1573048,54,43,18,1,'To když pověděl Ježíš, vyšel s učedlníky svými přes potok Cedron, kdež byla zahrada; do kteréžto všel on i učedlníci jeho.'),
(1573049,54,43,18,2,'Věděl pak i Jidáš, zrádce jeho, to místo; nebo často chodíval tam Ježíš s učedlníky svými.'),
(1573050,54,43,18,3,'Protož Jidáš pojav s sebou zástup, a od předních kněží a farizeů služebníky, přišel tam s lucernami a s pochodněmi a s zbrojí.'),
(1573051,54,43,18,4,'Ježíš pak věda všecko, což přijíti mělo na něj, vyšed proti nim, řekl jim: Koho hledáte?'),
(1573052,54,43,18,5,'Odpověděli jemu: Ježíše Nazaretského. Řekl jim Ježíš: Jáť jsem. Stál pak s nimi i Jidáš, zrádce jeho.'),
(1573053,54,43,18,6,'A jakž řekl jim: Já jsem, postoupili nazpět, a padli na zem.'),
(1573054,54,43,18,7,'I otázal se jich opět: Koho hledáte? A oni řekli: Ježíše Nazaretského.'),
(1573055,54,43,18,8,'Odpověděl Ježíš: Pověděl jsem vám, že já jsem. Poněvadž tedy mne hledáte, nechtež těchto, ať odejdou.'),
(1573056,54,43,18,9,'Aby se naplnila řeč, kterouž byl pověděl: Že které jsi mi dal, neztratil jsem z nich žádného.'),
(1573057,54,43,18,10,'Tedy Šimon Petr, maje meč, vytrhl jej a udeřil služebníka nejvyššího kněze a uťal mu ucho jeho pravé. A bylo jméno služebníka toho Malchus.'),
(1573058,54,43,18,11,'I řekl Ježíš Petrovi: Schovej meč svůj do pošvy. Což nemám píti kalicha, kterýž mi dal Otec?'),
(1573059,54,43,18,12,'Tedy zástup a hejtman a služebníci Židovští jali Ježíše, a svázali jej.'),
(1573060,54,43,18,13,'A vedli ho k Annášovi nejprve; nebo byl test Kaifášův, kterýž byl nejvyšším knězem toho léta.'),
(1573061,54,43,18,14,'Kaifáš pak byl ten, kterýž byl radu dal Židům, že by užitečné bylo, aby člověk jeden umřel za lid.'),
(1573062,54,43,18,15,'Šel pak za Ježíšem Šimon Petr a jiný učedlník. A ten učedlník byl znám nejvyššímu knězi, i všel s Ježíšem do síně nejvyššího kněze.'),
(1573063,54,43,18,16,'Ale Petr stál u dveří vně. I vyšel ten druhý učedlník, kterýž byl znám nejvyššímu knězi, a promluvil s vrátnou, i uvedl tam Petra.'),
(1573064,54,43,18,17,'Tedy řekla Petrovi děvečka vrátná: Nejsi-liž i ty z učedlníků člověka toho? Řekl on: Nejsem.'),
(1573065,54,43,18,18,'Stáli pak tu služebníci a pacholci, kteříž oheň udělali, nebo zima bylo, i zhřívali se. A byl s nimi také i Petr, stoje tu a zhřívaje se.'),
(1573066,54,43,18,19,'Tedy nejvyšší kněz tázal se Ježíše o učedlnících jeho a o učení jeho.'),
(1573067,54,43,18,20,'Odpověděl jemu Ježíš: Já zjevně mluvil jsem světu, já vždycky učíval jsem v škole a v chrámě, kdežto se odevšad Židé scházejí, a tajně jsem nic nemluvil,'),
(1573068,54,43,18,21,'Co se mne ptáš? Ptej se těch, kteříž mne slýchali, co jsem jim mluvil. Aj, tiť vědí, co jsem já mluvil.'),
(1573069,54,43,18,22,'A když on to pověděl, jeden z služebníků, stoje tu, dal poliček Ježíšovi, řka: Tak-liž odpovídáš nejvyššímu knězi?'),
(1573070,54,43,18,23,'Odpověděl mu Ježíš: Mluvil-li jsem zle, svědectví vydej o zlém; pakli dobře, proč mne tepeš?'),
(1573071,54,43,18,24,'I poslal jej Annáš svázaného k Kaifášovi nejvyššímu knězi.'),
(1573072,54,43,18,25,'Stál pak Šimon Petr, a zhříval se. Tedy řekli jemu: Nejsi-liž i ty z učedlníků jeho? Zapřel on a řekl: Nejsem.'),
(1573073,54,43,18,26,'Dí jemu jeden z služebníků nejvyššího kněze, příbuzný toho, kterémuž Petr uťal ucho: Zdaž jsem já tebe neviděl s ním v zahradě?'),
(1573074,54,43,18,27,'Tedy Petr opět zapřel. A hned kohout zazpíval.'),
(1573075,54,43,18,28,'I vedli Ježíše od Kaifáše do radného domu, a bylo ráno. Oni pak nevešli do radného domu, aby se neposkvrnili, ale aby jedli beránka.'),
(1573076,54,43,18,29,'Tedy vyšel k nim Pilát ven a řekl: Jakou žalobu vedete proti člověku tomuto?'),
(1573077,54,43,18,30,'Odpověděli a řekli jemu: Byť tento nebyl zločinec, nedali bychom ho tobě.'),
(1573078,54,43,18,31,'I řekl jim Pilát: Vezměte vy jej, a podle Zákona vašeho suďte ho. I řekli mu Židé: Námť nesluší zabíti žádného.'),
(1573079,54,43,18,32,'Aby se řeč Ježíšova naplnila, kterouž řekl, znamenaje, kterou by smrtí měl umříti.'),
(1573080,54,43,18,33,'Tedy Pilát všel opět do radného domu, i povolal Ježíše a řekl jemu: Ty-li jsi Král Židovský?'),
(1573081,54,43,18,34,'Odpověděl Ježíš: Sám-li od sebe to pravíš, čili jiní tobě pověděli o mně?'),
(1573082,54,43,18,35,'Odpověděl Pilát: Zdaliž jsem já Žid? Národ tvůj a přední kněží dali mi tebe. Co jsi učinil?'),
(1573083,54,43,18,36,'Odpověděl Ježíš: Království mé není z tohoto světa. Byť z tohoto světa bylo království mé, služebníci moji bránili by mne, abych nebyl vydán Židům. Ale nyní mé království není odsud.'),
(1573084,54,43,18,37,'I řekl jemu Pilát: Tedy král jsi ty? Dí Ježíš: Ty pravíš, že já král jsem. Jáť jsem se k tomu narodil, a proto jsem na svět přišel, abych svědectví vydal pravdě. Každý, kdož jest z pravdy, slyší hlas můj.'),
(1573085,54,43,18,38,'Dí jemu Pilát: Co jest pravda? A když to řekl, opět vyšel k Židům, a dí jim: Já na něm žádné viny nenalézám.'),
(1573086,54,43,18,39,'Ale jest obyčej váš, abych vám propustil jednoho vězně na velikunoc. Chcete-liž tedy, ať vám propustím Krále Židovského?'),
(1573087,54,43,18,40,'I zkřikli opět všickni, řkouce: Ne toho, ale Barabbáše. Byl pak Barabbáš lotr.'),
(1573088,54,43,19,1,'Tedy vzal Pilát Ježíše, a zbičoval jej.'),
(1573089,54,43,19,2,'A žoldnéři zpletše korunu z trní, vstavili na hlavu jeho, a pláštěm šarlatovým přioděli jej.'),
(1573090,54,43,19,3,'A říkali: Zdráv buď, Králi Židovský. A dávali jemu poličky.'),
(1573091,54,43,19,4,'I vyšel opět ven Pilát, a řekl jim: Aj, vyvedu jej vám ven, abyste poznali, žeť na něm žádné viny nenalézám.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573092,54,43,19,5,'Tedy vyšel Ježíš ven, nesa trnovou korunu a plášť šarlatový. I řekl jim Pilát: Aj, člověk.'),
(1573093,54,43,19,6,'A jakž jej uzřeli přední kněží a služebníci jejich, zkřikli řkouce: Ukřižuj, ukřižuj ho. Dí jim Pilát: Vezmětež vy jej a ukřižujte, nebo já na něm viny nenalézám.'),
(1573094,54,43,19,7,'Odpověděli jemu Židé: My Zákon máme, a podle Zákona našeho máť umříti, nebo Synem Božím se činil.'),
(1573095,54,43,19,8,'A když Pilát uslyšel tuto řeč, více se obával.'),
(1573096,54,43,19,9,'I všel do radného domu zase, a řekl Ježíšovi: Odkud jsi ty? Ale Ježíš nedal jemu odpovědi.'),
(1573097,54,43,19,10,'Tedy řekl jemu Pilát: Nemluvíš se mnou? Nevíš-liž, že mám moc ukřižovati tě a moc mám propustiti tebe?'),
(1573098,54,43,19,11,'Odpověděl Ježíš: Neměl bys nade mnou moci nižádné, byť nebylo dáno s hůry; protož, kdoť jest mne tobě vydal, většíť hřích má.'),
(1573099,54,43,19,12,'Od té chvíle hledal Pilát propustiti ho. Ale Židé volali řkouce: Propustíš-li tohoto, nejsi přítel císařův; nebo každý, kdož se králem činí, protiví se císaři.'),
(1573100,54,43,19,13,'Tedy Pilát uslyšev tu řeč, vyvedl ven Ježíše, a sedl na soudné stolici na místě, kteréž slove Litostrotos, a Židovsky Gabbata.'),
(1573101,54,43,19,14,'A byl den připravování před velikonocí, okolo šesté hodiny. I řekl Židům: Aj, král váš.'),
(1573102,54,43,19,15,'Oni pak zkřikli: Vezmi, vezmi a ukřižuj jej. Řekl jim Pilát: Krále vašeho ukřižuji? Odpověděli přední kněží: Nemámeť krále, než císaře.'),
(1573103,54,43,19,16,'Tedy vydal jim ho, aby byl ukřižován. I pojali Ježíše a vedli jej ven.'),
(1573104,54,43,19,17,'A on nesa kříž svůj, šel až na místo, kteréž slove popravné, a Židovsky Golgota.'),
(1573105,54,43,19,18,'Kdežto ukřižovali ho, a s ním jiné dva s obou stran, a v prostředku Ježíše.'),
(1573106,54,43,19,19,'Napsal pak i nápis Pilát, a vstavil na kříž. A bylo napsáno: Ježíš Nazaretský, Král Židovský.'),
(1573107,54,43,19,20,'Ten pak nápis mnozí z Židů čtli; nebo blízko města bylo to místo, kdež ukřižován byl Ježíš. A bylo psáno Židovsky, Řecky a Latině.'),
(1573108,54,43,19,21,'Tedy přední kněží Židovští řekli Pilátovi: Nepiš: Král Židovský, ale že on řekl: Král Židovský jsem.'),
(1573109,54,43,19,22,'Odpověděl Pilát: Co jsem psal, psal jsem.'),
(1573110,54,43,19,23,'Žoldnéři pak, když Ježíše ukřižovali, vzali roucha jeho, a učinili čtyři díly, každému rytíři díl jeden, vzali také i sukni, kterážto sukně byla nesšívaná, ale odvrchu všecka naskrze setkaná.'),
(1573111,54,43,19,24,'I řekli mezi sebou: Neroztrhujme jí, ale losujme o ni, čí bude. Aby se naplnilo písmo, řkoucí: Rozdělili sobě roucho mé, a o můj oděv metali los. A žoldnéři zajisté tak učinili.'),
(1573112,54,43,19,25,'Stály pak blízko kříže Ježíšova matka jeho a sestra matky jeho, Maria, manželka Kleofášova, a Maria Magdaléna.'),
(1573113,54,43,19,26,'Tedy Ježíš uzřev matku a učedlníka tu stojícího, kteréhož miloval, řekl k matce své: Ženo, aj, syn tvůj.'),
(1573114,54,43,19,27,'Potom řekl učedlníkovi: Aj, matka tvá. A od té hodiny přijal ji učedlník ten k sobě.'),
(1573115,54,43,19,28,'Potom věda Ježíš, že již všecko jiné dokonáno jest, aby se naplnilo písmo, řekl: Žízním.'),
(1573116,54,43,19,29,'Byla pak tu postavena nádoba plná octa. Tedy oni naplnili houbu octem, a obloživše yzopem, podali k ústům jeho.'),
(1573117,54,43,19,30,'A když okusil Ježíš octa, řekl: Dokonánoť jest. A nakloniv hlavy, ducha Otci poručil.'),
(1573118,54,43,19,31,'Židé pak, aby nezůstala na kříži těla na sobotu, poněvadž byl den připravování, (byl zajisté veliký ten den sobotní,) prosili Piláta, aby zlámáni byli hnátové jejich a aby byli složeni.'),
(1573119,54,43,19,32,'I přišli žoldnéři, a prvnímu zajisté zlámali hnáty, i druhému, kterýž ukřižován byl s ním.'),
(1573120,54,43,19,33,'Ale k Ježíšovi přišedše, jakž uzřeli jej již mrtvého, nelámali hnátů jeho.'),
(1573121,54,43,19,34,'Ale jeden z žoldnéřů bok jeho kopím otevřel, a hned vyšla krev a voda.'),
(1573122,54,43,19,35,'A ten, jenž viděl, svědectví vydal, a pravé jest svědectví jeho; onť ví, že pravé věci praví, abyste i vy věřili.'),
(1573123,54,43,19,36,'Stalo se pak to, aby se naplnilo Písmo: Kost jeho žádná nebude zlámána.'),
(1573124,54,43,19,37,'A opět jiné Písmo dí: Uzříť, v koho jsou bodli.'),
(1573125,54,43,19,38,'Potom pak prosil Piláta Jozef z Arimatie, (kterýž byl učedlník Ježíšův, ale tajný, pro strach Židovský,) aby sňal tělo Ježíšovo. I dopustil Pilát. A on přišed, i sňal tělo Ježíšovo.'),
(1573126,54,43,19,39,'Přišel pak i Nikodém, (kterýž byl prve přišel k Ježíšovi v noci,) nesa smíšení mirry a aloes okolo sta liber.'),
(1573127,54,43,19,40,'Tedy vzali tělo Ježíšovo, a obvinuli je prostěradly s vonnými věcmi, jakž obyčej jest Židům se pochovávati.'),
(1573128,54,43,19,41,'A byla na tom místě, kdež ukřižován byl, zahrada, a v zahradě hrob nový, v němžto ještě žádný nebyl pochován.'),
(1573129,54,43,19,42,'Protož tu pro den připravování Židovský, že blízko byl hrob, položili Ježíše.'),
(1573130,54,43,20,1,'První pak den po sobotě Maria Magdaléna přišla ráno k hrobu, když ještě tma bylo. I uzřela kámen odvalený od hrobu.'),
(1573131,54,43,20,2,'I běžela odtud a přišla k Šimonovi Petrovi a k jinému učedlníku, jehož miloval Ježíš, a řekla jim: Vzali Pána z hrobu, a nevíme, kde jsou jej položili.'),
(1573132,54,43,20,3,'Tedy vyšel Petr a jiný učedlník, a šli k hrobu.'),
(1573133,54,43,20,4,'I běželi oba spolu. Ale ten druhý učedlník předběhl Petra, a přišel prve k hrobu.'),
(1573134,54,43,20,5,'A nachýliv se, uzřel prostěradla položená, ale však tam nevšel.'),
(1573135,54,43,20,6,'Tedy přišel Šimon Petr, za ním jda, a všel do hrobu. I uzřel prostěradla položená,'),
(1573136,54,43,20,7,'A rouchu, kteráž byla na hlavě jeho, ne s prostěradly položenou, ale obzvláštně svinutou na jednom místě.'),
(1573137,54,43,20,8,'Potom všel i ten druhý učedlník, kterýž byl prve přišel k hrobu, i uzřel a uvěřil.'),
(1573138,54,43,20,9,'Nebo ještě neznali Písma, že měl Kristus z mrtvých vstáti.'),
(1573139,54,43,20,10,'I odešli zase ti učedlníci tam, kdež prve byli.'),
(1573140,54,43,20,11,'Ale Maria stála u hrobu vně, plačici. A když plakala, naklonila se do hrobu.'),
(1573141,54,43,20,12,'A uzřela dva anděly v bílém rouše sedící, jednoho u hlavy a druhého u noh, tu kdež bylo položeno tělo Ježíšovo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573142,54,43,20,13,'Kteřížto řekli jí: Ženo, co pláčeš? I dí jim: Vzali Pána mého, a nevím, kde ho položili.'),
(1573143,54,43,20,14,'To když řekla, obrátila se zpátkem, a uzřela Ježíše, an stojí, ale nevěděla, by Ježíš byl.'),
(1573144,54,43,20,15,'Dí jí Ježíš: Ženo, co pláčeš? Koho hledáš? Ona domnívajici se, že by zahradník byl, řekla jemu: Pane, vzal-lis ty jej, pověz mi, kdes ho položil, ať já jej vezmu.'),
(1573145,54,43,20,16,'Řekl jí Ježíš: Maria. Obrátivši se ona, řekla jemu: Rabbóni, jenž se vykládá: Mistře.'),
(1573146,54,43,20,17,'Dí jí Ježíš: Nedotýkejž se mne; neb jsem ještě nevstoupil k Otci svému. Ale jdiž k bratřím mým, a pověz jim: Vstupuji k Otci svému, a k Otci vašemu, k Bohu svému, a k Bohu vašemu.'),
(1573147,54,43,20,18,'I přišla Maria Magdaléna, zvěstujici učedlníkům, že by viděla Pána a že jí to pověděl.'),
(1573148,54,43,20,19,'Když pak byl večer toho dne, kterýž jest první po sobotě, a dveře byly zavříny, kdež byli učedlníci shromážděni, pro strach Židovský, přišel Ježíš, a stál u prostřed, a řekl jim: Pokoj vám.'),
(1573149,54,43,20,20,'A to pověděv, ukázal jim ruce i bok svůj. I zradovali se učedlníci, vidouce Pána.'),
(1573150,54,43,20,21,'Tedy řekl jim opět: Pokoj vám. Jakož mne poslal Otec, tak i já posílám vás.'),
(1573151,54,43,20,22,'To pověděv, dechl, a řekl jim: Přijměte Ducha svatého.'),
(1573152,54,43,20,23,'Kterýmžkoli odpustili byste hříchy, odpouštějíť se jim; a kterýmžkoli zadrželi byste je, zadržániť jsou.'),
(1573153,54,43,20,24,'Tomáš pak jeden ze dvanácti, jenž sloul Didymus, nebyl s nimi, když byl přišel Ježíš.'),
(1573154,54,43,20,25,'I řekli jemu jiní učedlníci: Viděli jsme Pána. A on řekl jim: Leč uzřím v rukou jeho bodení hřebů, a vpustím prst svůj v místo hřebů, a ruku svou vložím v bok jeho, nikoli neuvěřím.'),
(1573155,54,43,20,26,'A po osmi dnech opět učedlníci jeho byli vnitř, a Tomáš s nimi. Přišel Ježíš, a dveře byly zavříny, i stál uprostřed a řekl: Pokoj vám.'),
(1573156,54,43,20,27,'Potom řekl k Tomášovi: Vložiž prst svůj sem, a viz ruce mé, a vztáhni ruku svou, a vpusť v bok můj, a nebudiž nevěřící, ale věřící.'),
(1573157,54,43,20,28,'I odpověděl Tomáš a řekl jemu: Pán můj a Bůh můj.'),
(1573158,54,43,20,29,'Dí jemu Ježíš: Žes mne viděl, Tomáši, uvěřil jsi. Blahoslavení, kteříž neviděli, a uvěřili.'),
(1573159,54,43,20,30,'Mnohé zajisté i jiné divy činil Ježíš před obličejem učedlníků svých, kteréž nejsou psány v knize této.'),
(1573160,54,43,20,31,'Ale toto psáno jest, abyste věřili, že Ježíš jest Kristus, Syn Boží, a abyste věříce, život věčný měli ve jménu jeho.'),
(1573161,54,43,21,1,'Potom opět zjevil se Ježíš učedlníkům u moře Tiberiadského. A zjevil se takto:'),
(1573162,54,43,21,2,'Byli spolu Šimon Petr a Tomáš, jenž sloul Didymus, a Natanael, jenž byl z Kány Galilejské, a synové Zebedeovi, a jiní z učedlníků jeho dva.'),
(1573163,54,43,21,3,'Dí jim Šimon Petr: Půjdu ryb loviti. Řekli jemu: Půjdeme i my s tebou. I šli, a vstoupili na lodí hned; a té noci nic nepopadli.'),
(1573164,54,43,21,4,'A když bylo již ráno, stál Ježíš na břehu. Nevěděli však učedlníci, by Ježíš byl.'),
(1573165,54,43,21,5,'Tedy dí jim Ježíš: Dítky, máte-li jakou krmičku? Odpověděli jemu: Nemáme.'),
(1573166,54,43,21,6,'On pak řekl jim: Zavrztež sít na pravou stranu lodí, a naleznete. I zavrhli sít a hned nemohli jí táhnouti pro množství ryb.'),
(1573167,54,43,21,7,'I řekl učedlník ten, kteréhož miloval Ježíš, Petrovi: Pán jest. A Šimon Petr, jakž uslyšel, že Pán jest, opásal se po košili, (nebo byl nah,) a pustil se do moře.'),
(1573168,54,43,21,8,'Jiní také učedlníci na lodí plavili se, (nebo nedaleko byli od břehu, asi okolo dvou set loket,) táhnouce sít plnou ryb.'),
(1573169,54,43,21,9,'A jakž vystoupili na břeh, uzřeli řeřavé uhlí a rybu svrchu položenou a chléb.'),
(1573170,54,43,21,10,'Řekl jim Ježíš: Přineste z ryb, kterýchž jste nalapali nyní.'),
(1573171,54,43,21,11,'Vstoupil pak Šimon Petr a vytáhl sít na zem, plnou ryb velikých, jichž bylo sto padesáte a tři. A ačkoli jich tak mnoho bylo, však neztrhala se sít.'),
(1573172,54,43,21,12,'Řekl jim Ježíš: Pojďte, obědujte. Žádný pak z učedlníků neodvážil se ho otázati: Ty kdo jsi? vědouce, že Pán jest.'),
(1573173,54,43,21,13,'I přišel Ježíš, a vzal chléb, a dával jim, i rybu též.'),
(1573174,54,43,21,14,'To již po třetí ukázal se Ježíš učedlníkům svým, vstav z mrtvých.'),
(1573175,54,43,21,15,'A když poobědvali, řekl Ježíš Šimonovi Petrovi: Šimone, synu Jonášův, miluješ-li mne více nežli tito? Řekl jemu: Ovšem, Pane, ty víš, že tě miluji. Dí jemu: Pasiž beránky mé.'),
(1573176,54,43,21,16,'Řekl jemu opět po druhé: Šimone Jonášův, miluješ-li mne? Řekl jemu: Ovšem, Pane, ty víš, že tě miluji. Dí jemu: Pasiž ovce mé.'),
(1573177,54,43,21,17,'Řekl jemu po třetí: Šimone Jonášův, miluješ-li mne? I zarmoutil se Petr proto, že jemu řekl po třetí: Miluješ-li mne? A odpověděl jemu: Pane, ty znáš všecko, ty víš, že tě miluji. Řekl jemu Ježíš: Pasiž ovce mé.'),
(1573178,54,43,21,18,'Amen, amen pravím tobě: Když jsi byl mladší, opasovals se a chodíval jsi, kams chtěl; ale když se zstaráš, ztáhneš ruce své, a jiný tě opáše, a povede, kamž ty nechceš.'),
(1573179,54,43,21,19,'To pak pověděl, znamenaje, kterou by smrtí měl oslaviti Boha. A to pověděv, řekl jemu: Pojď za mnou.'),
(1573180,54,43,21,20,'I obrátiv se Petr, uzřel toho učedlníka, kteréhož miloval Ježíš, an jde za ním, kterýž i odpočíval za večeří na prsech jeho, a byl řekl: Pane, kdo jest ten, kterýž tě zradí?'),
(1573181,54,43,21,21,'Toho viděv Petr, dí k Ježíšovi: Pane, co pak tento?'),
(1573182,54,43,21,22,'Řekl jemu Ježíš: Chci-li ho nechati, dokudž nepřijdu, co tobě po tom? Ty pojď za mnou.'),
(1573183,54,43,21,23,'I vyšla řeč ta mezi bratří, že by učedlník ten neměl umříti. A neřekl byl jemu Ježíš, že by neměl umříti, ale řekl: Chci-li ho nechati, dokudž nepřijdu, co tobě po tom?'),
(1573184,54,43,21,24,'Toť jest učedlník ten, kterýž svědectví vydává o těchto věcech, a napsal toto, a víme, že pravé jest svědectví jeho.'),
(1573185,54,43,21,25,'Jestiť pak i jiných mnoho věcí, kteréž činil Ježíš, kteréž kdyby měly všecky, každá obzvláštně, psány býti, mám za to, že by ten svět nemohl přijíti těch knih, kteréž by napsány byly. Amen.'),
(1573186,54,44,1,1,'První zajisté knihu sepsalť jsem, ó Teofile, o všech věcech, kteréž začal Ježíš činiti a učiti,'),
(1573187,54,44,1,2,'Až do toho dne, v kterémžto dav přikázání apoštolům, kteréž byl skrze Ducha svatého vyvolil, vzhůru vzat jest.'),
(1573188,54,44,1,3,'Kterýmžto i zjevoval sebe samého živého po svém umučení ve mnohých jistých důvodích, za čtyřidceti dnů ukazuje se jim a mluvě o království Božím.'),
(1573189,54,44,1,4,'A shromáždiv se s nimi, přikázal jim, aby z Jeruzaléma neodcházeli, ale aby očekávali zaslíbení Otcova, o kterémž jste prý slyšeli ode mne.'),
(1573190,54,44,1,5,'Nebo Jan zajisté křtil vodou, ale vy pokřtěni budete Duchem svatým po nemnohých těchto dnech.'),
(1573191,54,44,1,6,'Oni pak sšedše se, otázali se ho, řkouce: Pane, v tomto-li času napravíš království Izraelské?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573192,54,44,1,7,'I řekl jim: Neníť vaše věc znáti časy anebo příhodnosti časů, kteréžto Otec v moci své položil.'),
(1573193,54,44,1,8,'Ale přijmete moc Ducha svatého, přicházejícího na vás, a budete mi svědkové, i v Jeruzalémě, i ve všem Judstvu, i v Samaří, a až do posledních končin země.'),
(1573194,54,44,1,9,'A to pověděv, ani na to hledí, vzhůru vyzdvižen jest, a oblak vzal jej od očí jejich.'),
(1573195,54,44,1,10,'A když za ním v nebe jdoucím pilně hleděli, aj, dva muži postavili se podle nich v rouše bílém,'),
(1573196,54,44,1,11,'A řekli: Muži Galilejští, co stojíte, hledíce do nebe? Tento Ježíš, kterýž vzhůru vzat jest od vás do nebe, takť přijde, jakž jste spatřili způsob jeho jdoucího do nebe.'),
(1573197,54,44,1,12,'Tedy navrátili se do Jeruzaléma od hory, jenž slove Olivetská, kteráž jest blízko Jeruzaléma, vzdálí cesty jednoho dne svátečního.'),
(1573198,54,44,1,13,'A když přišli domů, vstoupili do vrchního příbytku domu, kdež přebývali, i Petr i Jakub, i Jan a Ondřej, Filip a Tomáš, Bartoloměj a Matouš, Jakub Alfeův a Šimon Zelótes a Judas bratr Jakubův.'),
(1573199,54,44,1,14,'Ti všickni byli trvajíce jednomyslně na modlitbě a pokorné prosbě s ženami a s Marijí, matkou Ježíšovou, i s bratřími jeho.'),
(1573200,54,44,1,15,'V těch pak dnech povstav Petr uprostřed učedlníků, řekl (a byl zástup lidí spolu shromážděných okolo sta a dvadcíti):'),
(1573201,54,44,1,16,'Muži bratří, musilo se naplniti Písmo to, kteréž předpověděl Duch svatý skrze ústa Davidova o Jidášovi, kterýž byl vůdce těch, jenž jímali Ježíše.'),
(1573202,54,44,1,17,'Nebo byl přičten k nám, a byl došel losu přisluhování tohoto.'),
(1573203,54,44,1,18,'Ten zajisté obdržel pole ze mzdy nepravosti, a oběsiv se, rozpukl se na dvé, i vykydla se všecka střeva jeho.'),
(1573204,54,44,1,19,'A to známé jest učiněno všechněm přebývajícím v Jeruzalémě, takže jest nazváno pole to vlastním jazykem jejich Akeldama, to jest pole krve.'),
(1573205,54,44,1,20,'Psáno jest zajisté v knihách Žalmů: Budiž příbytek jeho pustý, a nebuď, kdo by přebýval v něm, a opět: Biskupství jeho vezmi jiný.'),
(1573206,54,44,1,21,'Protož musíť to býti, aby jeden z těch mužů, kteříž jsou s námi bývali po všecken čas, v němž přebýval mezi námi Pán Ježíš,'),
(1573207,54,44,1,22,'Počav od křtu Janova až do dne toho, v kterémžto vzhůru vzat jest od nás, byl svědkem spolu s námi vzkříšení jeho.'),
(1573208,54,44,1,23,'Tedy postavili dva, Jozefa, jenž sloul Barsabáš, kterýž měl příjmí Justus, a Matěje.'),
(1573209,54,44,1,24,'A modléce se, řekli: Ty, Pane, všech srdcí zpytateli, ukažiž, kterého jsi vyvolil z těchto dvou,'),
(1573210,54,44,1,25,'Aby přijal los přisluhování tohoto a apoštolství, z něhož jest vypadl Jidáš, aby odšel na místo své.'),
(1573211,54,44,1,26,'I dali jim losy. Spadl pak los na Matěje, i připojen jest z společného snešení k jedenácti apoštolům.'),
(1573212,54,44,2,1,'A když přišel den padesátý, byli všickni spolu na jednom místě.'),
(1573213,54,44,2,2,'I stal se rychle zvuk s nebe, jako přicházejícího větru prudkého, a naplnil všecken dům, kdež seděli.'),
(1573214,54,44,2,3,'I ukázali se jim rozdělení jazykové jako oheň, kterýžto posadil se na každém z nich.'),
(1573215,54,44,2,4,'I naplněni jsou všickni Duchem svatým, a počali mluviti jinými jazyky, jakž ten Duch dával jim vymlouvati.'),
(1573216,54,44,2,5,'Byli pak v Jeruzalémě přebývající Židé, muži nábožní, ze všelikého národu, kterýž pod nebem jest.'),
(1573217,54,44,2,6,'A když se stal ten hlas, sešlo se množství a užasli se toho, že je slyšel jeden každý, ani mluví přirozeným jazykem jeho.'),
(1573218,54,44,2,7,'I děsili se všickni a divili se, řkouce jedni k druhým: Aj, zdaliž nejsou tito všickni, kteříž mluví, Galilejští?'),
(1573219,54,44,2,8,'A kterak my je slyšíme jeden každý z nás mluviti jazykem naším, v kterémž jsme se zrodili?'),
(1573220,54,44,2,9,'Partští, a Medští, a Elamitští, a kteříž přebýváme v Mezopotamii, v Židovstvu a v Kappadocii, v Pontu a v Azii,'),
(1573221,54,44,2,10,'V Frygii a v Pamfylii, v Egyptě a v krajinách Libye, kteráž jest vedle Cyrénu, a hosté Římané, Židé, i vnově na víru obrácení,'),
(1573222,54,44,2,11,'Kretští i Arabští, slyšíme je, ani mluví jazyky našimi veliké věci Boží.'),
(1573223,54,44,2,12,'I děsili se všickni a divili se, jeden k druhému řkouce: I což toto bude?'),
(1573224,54,44,2,13,'Jiní pak posmívajíce se, pravili: Mstem se zpili tito.'),
(1573225,54,44,2,14,'A stoje Petr s jedenácti, pozdvihl hlasu svého a promluvil k nim: Muži Židé a všickni, kteříž bydlíte v Jeruzalémě, toto vám známo buď, a ušima pozorujte slov mých.'),
(1573226,54,44,2,15,'Jistě nejsouť tito, jakož vy se domníváte, zpilí, poněvadž jest teprv třetí hodina na den.'),
(1573227,54,44,2,16,'Ale totoť jest, což jest předpovědíno skrze proroka Joele:'),
(1573228,54,44,2,17,'A budeť v posledních dnech, (dí Bůh,) vyleji z Ducha mého na všeliké tělo, a prorokovati budou synové vaši, i dcery vaše, a mládenci vaši vidění vídati budou, a starci vaši sny míti budou.'),
(1573229,54,44,2,18,'A zajisté na služebníky své a na služebnice své v těch dnech vyleji z Ducha mého, a budou prorokovati.'),
(1573230,54,44,2,19,'A ukáži zázraky na nebi svrchu a znamení na zemi dole, krev a oheň a páru dýmovou.'),
(1573231,54,44,2,20,'Slunce obrátí se v temnost a měsíc v krev, prve než přijde den Páně veliký a zjevný.'),
(1573232,54,44,2,21,'A staneť se, že každý, kdožkoli vzýval by jméno Páně, spasen bude.'),
(1573233,54,44,2,22,'Muži Izraelští, slyšte slova tato: Ježíše toho Nazaretského, muže od Boha zveličeného mezi vámi mocmi a zázraky a znameními, kteréž činil skrze něho Bůh uprostřed vás, jakož i vy sami víte,'),
(1573234,54,44,2,23,'Toho, pravím, vydaného, z uložené rady a předzvědění Božího vzavše a skrze ruce nešlechetných ukřižovavše, zamordovali jste.'),
(1573235,54,44,2,24,'Jehožto Bůh vzkřísil, zprostiv ho bolestí smrti, jakož nebylo možné jemu držánu býti od ní.'),
(1573236,54,44,2,25,'Nebo David praví o něm: Spatřoval jsem Pána před sebou vždycky; nebo jest mi po pravici, abych se nepohnul.'),
(1573237,54,44,2,26,'Protož rozveselilo se srdce mé, a zplésal jazyk můj, nýbrž i tělo mé odpočine v naději.'),
(1573238,54,44,2,27,'Nebo nenecháš duše mé v pekle, aniž dáš viděti svatému svému porušení.'),
(1573239,54,44,2,28,'Známé jsi mi učinil cesty života, a naplníš mne utěšením před obličejem svým.'),
(1573240,54,44,2,29,'Muži bratří, sluší směle mluviti k vám o patriarchovi Davidovi, že i umřel, i pochován jest, i hrob jeho jest u nás až do dnešního dne.'),
(1573241,54,44,2,30,'Prorok tedy byv a věděv, že přísahou zavázal se jemu Bůh, že z plodu ledví jeho podle těla vzbudí Krista a posadí na stolici jeho,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573242,54,44,2,31,'To předzvěděv, mluvil o vzkříšení Kristovu, že není opuštěna duše jeho v pekle, ani tělo jeho vidělo porušení.'),
(1573243,54,44,2,32,'Toho Ježíše vzkřísil Bůh, jehožto my všickni svědkové jsme.'),
(1573244,54,44,2,33,'Protož pravicí Boží jsa zvýšen, a vzav zaslíbení Ducha svatého od Otce, vylil to, což vy nyní vidíte a slyšíte.'),
(1573245,54,44,2,34,'Neboť jest David nevstoupil v nebe, ale on praví: Řekl Pán Pánu mému: Seď na pravici mé,'),
(1573246,54,44,2,35,'Dokavadž nepoložím nepřátel tvých, aby byli podnože noh tvých.'),
(1573247,54,44,2,36,'Protož věziž jistě všecken dům Izraelský, žeť jest Bůh i Pánem ho učinil i Kristem, toho Ježíše, kteréhož jste vy ukřižovali.'),
(1573248,54,44,2,37,'To slyševše, zkormouceni jsou v srdci svém, a řekli ku Petrovi a k jiným apoštolům: Což máme činiti, muži bratří?'),
(1573249,54,44,2,38,'Tedy Petr řekl k nim: Pokání čiňte, a pokřti se jeden každý z vás ve jménu Ježíše Krista na odpuštění hříchů a přijmete dar Ducha svatého.'),
(1573250,54,44,2,39,'Vámť jest zajisté zaslíbení stalo se a synům vašim, i všechněm, kteříž daleko jsou, kterýchžkoli povolal by Pán Bůh náš.'),
(1573251,54,44,2,40,'A jinými slovy mnohými osvědčoval a napomínal jich, řka: Oddělte se od pokolení toho zlého.'),
(1573252,54,44,2,41,'Tedy ti, kteříž ochotně přijali slova jeho, pokřtěni jsou, a připojilo se k nim ten den duší okolo tří tisíců.'),
(1573253,54,44,2,42,'I zůstávali v učení apoštolském, a v společnosti, a v lámání chleba, a na modlitbách.'),
(1573254,54,44,2,43,'I přišla na všelikou duši bázeň, a mnozí divové a zázrakové dáli se skrze apoštoly.'),
(1573255,54,44,2,44,'Všickni pak věřící byli pospolu, a měli všecky věci obecné.'),
(1573256,54,44,2,45,'A prodávali vladařství a statky, a dělili mezi všecky, jakž komu potřebí bylo.'),
(1573257,54,44,2,46,'A na každý den trvajíce jednomyslně v chrámě, a lámajíce po domích chléb, přijímali pokrm s potěšením a sprostností srdce,'),
(1573258,54,44,2,47,'Chválíce Boha a milost majíce u všeho lidu. Pán pak přidával církvi na každý den těch, kteříž by spaseni byli.'),
(1573259,54,44,3,1,'Petr pak a Jan spolu vstupovali do chrámu v hodinu modlitebnou devátou.'),
(1573260,54,44,3,2,'A muž nějaký, chromý tak narozený z života matky své, nesen byl, kteréhož sázeli na každý den u dveří chrámových, kteréž slouly Krásné, aby prosil za almužnu těch, kteříž vcházeli do chrámu.'),
(1573261,54,44,3,3,'Ten uzřev Petra a Jana, ani vcházeti měli do chrámu, prosil jich, aby mu almužnu dali.'),
(1573262,54,44,3,4,'I pohleděv naň Petr s Janem, řekl: Hleď na nás.'),
(1573263,54,44,3,5,'A on pilně pohleděl na ně, naděje se, že něco vezme od nich.'),
(1573264,54,44,3,6,'Tedy řekl Petr: Stříbra a zlata nemám, ale což mám, to tobě dám. Ve jménu Ježíše Krista Nazaretského vstaň a choď.'),
(1573265,54,44,3,7,'I ujav jej za ruku jeho pravou, pozdvihl ho, a hned utvrzeny jsou nohy jeho i kloubové.'),
(1573266,54,44,3,8,'A zchytiv se, stál, a chodil, a všel s nimi do chrámu, chodě, a poskakuje, a chvále Boha.'),
(1573267,54,44,3,9,'A viděl jej všecken lid, an chodí a chválí Boha.'),
(1573268,54,44,3,10,'I poznali ho, že jest ten, kterýž na almužně sedával u dveří Krásných chrámových. I naplněni jsou strachem a děšením nad tím, což se stalo jemu.'),
(1573269,54,44,3,11,'A když se ten uzdravený přídržel Petra a Jana, sběhl se k nim všecken lid do síňce, kteráž sloula Šalomounova, předěšen jsa.'),
(1573270,54,44,3,12,'To viděv Petr, promluvil k lidu: Muži Izraelští, co se divíte tomuto? Anebo co na nás tak pilně hledíte, jako bychom my svou mocí aneb nábožností učinili to, aby tento chodil?'),
(1573271,54,44,3,13,'Bůh Abrahamův a Izákův a Jákobův, Bůh otců našich, oslavil Syna svého Ježíše, kteréhož jste vy vydali a odepřeli se před tváří Pilátovou, kterýž ho soudil býti hodného propuštění.'),
(1573272,54,44,3,14,'Vy pak svatého a spravedlivého odepřeli jste se a prosili jste za muže vražedníka, aby vám byl dán.'),
(1573273,54,44,3,15,'Ale dárce života zamordovali jste, kteréhož Bůh vzkřísil z mrtvých; čehož my svědkové jsme.'),
(1573274,54,44,3,16,'A skrze víru ve jméno jeho, tohoto, kteréhož vy vidíte a znáte, utvrdilo jest jméno jeho a víra, kteráž jest skrze něho, dala jemu celé zdraví toto před obličejem všech vás.'),
(1573275,54,44,3,17,'Ale nyní, bratří, vím, že jste to z nevědomí učinili, jako i knížata vaše.'),
(1573276,54,44,3,18,'Bůh pak to, což předzvěstoval skrze ústa všech proroků, že měl Kristus trpěti, tak jest naplnil.'),
(1573277,54,44,3,19,'Protož čiňte pokání, a obraťte se, aby byli shlazeni hříchové vaši, když by přišli časové rozvlažení od tváři Páně,'),
(1573278,54,44,3,20,'A poslal by toho, kterýž vám kázán jest, Ježíše Krista.'),
(1573279,54,44,3,21,'Kteréhož zajisté musí přijíti nebesa, až do času napravení všech věcí; což byl předpověděl Bůh skrze ústa svých svatých proroků od věků.'),
(1573280,54,44,3,22,'Mojžíš zajisté otcům řekl, že Proroka vám vzbudí Pán Bůh váš z bratří vašich jako mne, jehož poslouchati budete ve všem, cožkoli bude mluviti vám.'),
(1573281,54,44,3,23,'A staneť se, že každá duše, kteráž by neposlouchala toho Proroka, vyhlazena bude z lidu mého.'),
(1573282,54,44,3,24,'Ano i všickni proroci od Samuele a potomních, kteřížkoli mluvili, také jsou o těchto dnech předzvěstovali.'),
(1573283,54,44,3,25,'Vy jste synové proroků a synové úmluvy, kterouž učinil Bůh s otci našimi, řka k Abrahamovi: V semeni tvém požehnány budou všecky čeledi země.'),
(1573284,54,44,3,26,'Vám nejprve Bůh, vzbudiv Syna svého Ježíše, poslal ho dobrořečícího vám, aby se jeden každý z vás odvrátil od nepravostí svých.'),
(1573285,54,44,4,1,'A když oni mluvili k lidu, přišli kněží a úředník chrámu a saduceové,'),
(1573286,54,44,4,2,'Těžce to nesouce, že lid učili a zvěstovali ve jménu Ježíše vzkříšení z mrtvých.'),
(1573287,54,44,4,3,'I vztáhli na ně ruce a vsadili je do žaláře až do jitra, neb již byl večer.'),
(1573288,54,44,4,4,'Mnozí pak z těch, kteříž slyšeli slovo Boží, uvěřili. I učiněn jest počet mužů okolo pěti tisíců.'),
(1573289,54,44,4,5,'Stalo se pak nazejtří, sešli se knížata jejich, a starší, a zákoníci v Jeruzalémě,'),
(1573290,54,44,4,6,'A Annáš nejvyšší kněz, a Kaifáš, a Jan, a Alexander, a kteřížkoli byli z pokolení nejvyššího kněze.'),
(1573291,54,44,4,7,'I postavivše je mezi sebou, otázali se jich: Jakou mocí aneb v kterém jménu učinili jste to vy?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573292,54,44,4,8,'Tedy Petr, jsa pln Ducha svatého, řekl jim: Knížata lidu a starší Izraelští,'),
(1573293,54,44,4,9,'Poněvadž my dnes k soudu jsme přivedeni pro dobrodiní člověku nemocnému učiněné, kterak by on zdráv učiněn byl:'),
(1573294,54,44,4,10,'Známo buď všechněm vám i všemu lidu Izraelskému, že ve jménu Ježíše Krista Nazaretského, kteréhož jste vy ukřižovali, jehož Bůh vzkřísil z mrtvých, skrze toho jméno tento stojí před vámi zdravý.'),
(1573295,54,44,4,11,'Toť jest ten kámen za nic položený od vás dělníků, kterýž učiněn jest v hlavu úhelní.'),
(1573296,54,44,4,12,'A neníť v žádném jiném spasení; neboť není jiného jména pod nebem daného lidem, skrze kteréž bychom mohli spaseni býti.'),
(1573297,54,44,4,13,'I vidouce takovou udatnost a smělost v mluvení Petrovu a Janovu, a shledavše, že jsou lidé neučení a prostí, divili se, a poznali je, že s Ježíšem bývali.'),
(1573298,54,44,4,14,'Člověka také toho vidouce, an stojí s nimi, kterýž byl uzdraven, neměli co mluviti proti nim.'),
(1573299,54,44,4,15,'I rozkázavše jim vystoupiti z rady, rozmlouvali vespolek,'),
(1573300,54,44,4,16,'Řkouce: Co učiníme lidem těmto? Nebo že jest zjevný zázrak stal se skrze ně, všem přebývajícím v Jeruzalémě známé jest, aniž můžeme toho zapříti.'),
(1573301,54,44,4,17,'Ale aby se to více nerozhlašovalo v lidu, s pohrůžkou přikažme jim, aby více v tom jménu žádnému z lidí nemluvili.'),
(1573302,54,44,4,18,'I povolavše jich, přikázali jim, aby nikoli nemluvili, ani učili ve jménu Ježíšovu.'),
(1573303,54,44,4,19,'Tedy Petr a Jan odpovídajíce, řekli jim: Jest-li to spravedlivé před obličejem Božím, abychom vás více poslouchali než Boha, suďte.'),
(1573304,54,44,4,20,'Nebť nemůžeme nemluviti toho, co jsme viděli a slyšeli.'),
(1573305,54,44,4,21,'A oni pohrozivše jim, propustili je, nenalezše na nich příčiny trestání, pro lid; nebo všickni velebili Boha z toho, co se bylo stalo.'),
(1573306,54,44,4,22,'Byl zajisté v letech více než ve čtyřidcíti člověk ten, při kterémž se byl stal zázrak ten uzdravení.'),
(1573307,54,44,4,23,'A jsouce propuštěni, přišli k svým a pověděli jim, co k nim přední kněží a starší mluvili.'),
(1573308,54,44,4,24,'Kteříž uslyševše to, jednomyslně pozdvihli hlasu k Bohu a řekli: Hospodine, ty jsi Bůh, kterýž jsi učinil nebe i zemi, i moře i všecko, což v nich jest,'),
(1573309,54,44,4,25,'Kterýž jsi skrze ústa Davida, služebníka svého, řekl: Proč jsou se bouřili národové a lidé myslili marné věci?'),
(1573310,54,44,4,26,'Postavili se králové zemští, a knížata sešla se vespolek proti Pánu a proti Pomazanému jeho.'),
(1573311,54,44,4,27,'Právěť jsou se jistě sešli proti svatému Synu tvému Ježíšovi, kteréhož jsi pomazal, Herodes a Pontský Pilát, s pohany a lidem Izraelským,'),
(1573312,54,44,4,28,'Aby učinili to, což ruka tvá a rada tvá předuložila, aby se stalo.'),
(1573313,54,44,4,29,'A nyní, Pane, pohlediž na pohrůžky jejich a dejž služebníkům svým mluviti slovo tvé svobodně a směle,'),
(1573314,54,44,4,30,'Vztahuje ruku svou k uzdravování a k činění divů a zázraků, skrze jméno svatého Syna tvého Ježíše.'),
(1573315,54,44,4,31,'A když se oni modlili, zatřáslo se to místo, na kterémž byli shromážděni, a naplněni jsou všickni Duchem svatým, a mluvili slovo Boží směle a svobodně.'),
(1573316,54,44,4,32,'Toho pak množství věřících bylo jedno srdce a jedna duše. Aniž kdo co z těch věcí, kteréž měl, svým vlastním býti pravil, ale měli všecky věci obecné.'),
(1573317,54,44,4,33,'A mocí velikou vydávali apoštolé svědectví o vzkříšení Pána Ježíše, a milost veliká přítomná byla všechněm jim.'),
(1573318,54,44,4,34,'A žádný mezi nimi nebyl nuzný; nebo kteřížkoli měli pole nebo domy, prodávajíce, přinášeli peníze, za kteréž prodávali,'),
(1573319,54,44,4,35,'A kladli před nohy apoštolské. I rozdělováno bylo jednomu každému, jakž komu potřebí bylo.'),
(1573320,54,44,4,36,'Jozes pak, kterýž příjmí měl od apoštolů Barnabáš, (což se vykládá syn utěšení,) z pokolení Levítského, z Cypru rodem,'),
(1573321,54,44,4,37,'Měv pole, prodal je, a přinesl peníze, a položil k nohám apoštolským.'),
(1573322,54,44,5,1,'Muž pak jeden, jménem Ananiáš, s Zafirou, manželkou svou, prodal statek.'),
(1573323,54,44,5,2,'A lstivě něco těch peněz ujal s vědomím manželky své, a přinesa díl nějaký, položil k nohám apoštolským.'),
(1573324,54,44,5,3,'I řekl Petr: Ananiáši, proč naplnil satan srdce tvé lstí, tak abys lhal Duchu svatému a lstivě ujal částku peněz za to pole?'),
(1573325,54,44,5,4,'Zdaliž nebylo tvé, kdybys ho byl sobě nechal? A když bylo prodáno, v moci tvé bylo. I proč jsi tuto věc složil v srdci svém? Neselhal jsi lidem, ale Bohu.'),
(1573326,54,44,5,5,'Tedy uslyšav Ananiáš tato slova, padna, zdechl. I spadla bázeň veliká na všecky, kteříž to slyšeli.'),
(1573327,54,44,5,6,'A vstavše mládenci, vzali jej, a vynesše ven, pochovali.'),
(1573328,54,44,5,7,'I stalo se po chvíli, jako po třech hodinách, že i jeho žena, nevěduci, co se bylo stalo, přišla.'),
(1573329,54,44,5,8,'I řekl k ní Petr: Pověz mi, za toliko-li jste pole své prodali? A ona řekla: Ano, za tolik.'),
(1573330,54,44,5,9,'Tedy dí jí Petr: I pročež jste se smluvili, abyste pokoušeli Ducha Páně? Aj, nohy těch, kteříž pochovali muže tvého, přede dveřmi jsou, a vynesouť také i tebe.'),
(1573331,54,44,5,10,'I padla hned před nohy jeho, a zdechla. A všedše mládenci, nalezli ji mrtvou; i vynesše, pochovali podle muže jejího.'),
(1573332,54,44,5,11,'I byla bázeň veliká po vší církvi, i mezi všemi, kteříž to slyšeli.'),
(1573333,54,44,5,12,'Skrze ruce pak apoštolů dáli se divové a zázrakové velicí v lidu, (A bývali všickni jednomyslně v síňci Šalomounově.'),
(1573334,54,44,5,13,'Jiný pak žádný neodvážil se připojiti k nim, ale velebil je lid.'),
(1573335,54,44,5,14,'A vždy více se rozmáhalo množství věřících Pánu, mužů i také žen.)'),
(1573336,54,44,5,15,'Takže i na ulice vynášeli nemocné, a kladli na ložcích a na nosidlách, aby, když by šel Petr, aspoň stín jeho zastínil na některé z nich.'),
(1573337,54,44,5,16,'Scházelo se pak množství z okolních měst do Jeruzaléma, nesouce nemocné a trápené od duchů nečistých, a uzdravováni byli všickni.'),
(1573338,54,44,5,17,'Tedy povstav nejvyšší kněz a všickni, kteříž byli s ním, (jenž byli saducejské sekty,) naplněni jsou závistí.'),
(1573339,54,44,5,18,'I zjímali apoštoly, a vsázeli je do žaláře obecného.'),
(1573340,54,44,5,19,'Ale anděl Páně v noci otevřev dveře u žaláře, vyvedl je ven a řekl:'),
(1573341,54,44,5,20,'Jděte, a postavíce se, mluvte lidu v chrámě všecka slova života tohoto.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573342,54,44,5,21,'To oni uslyševše, vešli na úsvitě do chrámu a učili. Tedy přišed nejvyšší kněz a ti, kteříž s ním byli, svolali radu a všecky starší synů Izraelských, i poslali do žaláře, aby byli přivedeni.'),
(1573343,54,44,5,22,'A služebníci přišedše, nenalezli jich v žaláři. A navrátivše se, vypravovali,'),
(1573344,54,44,5,23,'Řkouce: Žalář zajisté nalezli jsme zavřený se vší pilností a strážné vně stojící u dveří, ale otevřevše dveře, žádného jsme tam nenalezli.'),
(1573345,54,44,5,24,'A když uslyšeli řeči tyto i nejvyšší kněz i úředník chrámu i jiní přední kněží, nerozuměli, co by se to stalo.'),
(1573346,54,44,5,25,'A přišed kdosi, pověděl jim, řka: Aj, muži, kteréž jste vsázeli do žaláře, v chrámě stojí a učí lid.'),
(1573347,54,44,5,26,'Tedy šel tam úředník s služebníky, a přivedl je bez násilé; nebo se báli lidu, aby nebyli ukamenováni.'),
(1573348,54,44,5,27,'A přivedše je, postavili je v radě. I otázal se jich nejvyšší kněz,'),
(1573349,54,44,5,28,'Řka: Zdaliž jsme vám přísně nepřikázali, abyste neučili v tom jménu? A aj, naplnili jste Jeruzalém učením svým, a chcete na nás uvésti krev člověka toho.'),
(1573350,54,44,5,29,'Odpověděv pak Petr a apoštolé, řekli: Více sluší poslouchati Boha než lidí.'),
(1573351,54,44,5,30,'Bůh otců našich vzkřísil Ježíše, kteréhož jste vy zamordovali, pověsivše na dřevě.'),
(1573352,54,44,5,31,'Toho jest Bůh, jakožto Knížete a Spasitele, povýšil pravicí svou, aby bylo dáno lidu Izraelskému pokání a odpuštění hříchů.'),
(1573353,54,44,5,32,'A my jsme svědkové toho všeho, což mluvíme, ano i Duch svatý, kteréhož dal Bůh těm, jenž jsou poslušni jeho.'),
(1573354,54,44,5,33,'Oni pak slyševše to, rozzlobili se, a radili se o to, kterak by je vyhladili.'),
(1573355,54,44,5,34,'Tedy povstav v radě jeden farizeus, jménem Gamaliel, Zákona učitel, vzácný muž u všeho lidu, rozkázal, aby na malou chvíli ven vyvedli apoštoly.'),
(1573356,54,44,5,35,'I řekl jim: Muži Izraelští, pilně se rozmyslte při těchto lidech, co máte činiti.'),
(1573357,54,44,5,36,'Nebo před těmito časy byl povstal Teudas, pravě se také býti něčím velikým, jehož se přídrželo mužů okolo čtyř set; kterýžto již zahynul, i všickni, kteříž přistoupili k němu, rozptýleni jsou a v nic obráceni.'),
(1573358,54,44,5,37,'Po něm pak povstal Judas Galilejský za dnů popisu, a mnoho lidu po sobě obrátil. Ale i ten zahynul, a všickni, kteřížkoli přistoupili k němu, rozptýleni jsou.'),
(1573359,54,44,5,38,'A protož nyní pravím vám: Dejte pokoj těmto lidem, a nechte jich. Nebo jestližeť jest z lidí rada tato anebo dílo toto, rozprchneť se;'),
(1573360,54,44,5,39,'Pakliť jest z Boha, nebudete moci toho zkaziti; abyste snad i Bohu odporní nalezeni nebyli.'),
(1573361,54,44,5,40,'I povolili jemu. A povolavše apoštolů, a zmrskavše je, přikázali, aby více nemluvili ve jménu Ježíšovu. I propustili je.'),
(1573362,54,44,5,41,'Oni pak šli z toho jejich shromáždění, radujíce se, že jsou hodni učiněni trpěti protivenství pro jméno Pána Ježíše.'),
(1573363,54,44,5,42,'Na každý pak den nepřestávali v chrámě i po domích učiti a zvěstovati Ježíše Krista.'),
(1573364,54,44,6,1,'A v těch dnech, když se rozmnožovali učedlníci, stalo se reptání Řeků proti Židům proto, že by zanedbávány byly v přisluhování vezdejším vdovy jejich.'),
(1573365,54,44,6,2,'Tedy dvanácte apoštolů, svolavše množství učedlníků, řekli: Není slušné, abychom my, opustíce slovo Boží, přisluhovali stolům.'),
(1573366,54,44,6,3,'Protož, bratří, vybeřte z sebe mužů sedm dobropověstných, plných Ducha svatého a moudrosti, jimž bychom poručili tu práci.'),
(1573367,54,44,6,4,'My pak modlitby a služby slova Páně pilni budeme.'),
(1573368,54,44,6,5,'I líbila se ta řeč všemu množství. I vyvolili Štěpána, muže plného víry a Ducha svatého, a Filipa, a Prochora, a Nikánora, a Timona, a Parména, a Mikuláše Antiochenského, k víře vnově obráceného.'),
(1573369,54,44,6,6,'Ty postavili před obličejem apoštolů, kteřížto pomodlivše se, vzkládali na ně ruce.'),
(1573370,54,44,6,7,'I rostlo jest slovo Boží, a rozmáhal se počet učedlníků v Jeruzalémě velmi. Mnohý také zástup kněží poslouchal víry.'),
(1573371,54,44,6,8,'Štěpán pak, jsa plný víry a moci, činil divy a zázraky veliké v lidu.'),
(1573372,54,44,6,9,'I povstali někteří z školy, kteráž sloula Libertinských, a Cyrenenských, a Alexandrinských, a těch, kteříž byli z Cilicie a Azie, hádajíce se s Štěpánem.'),
(1573373,54,44,6,10,'A nemohli odolati moudrosti a Duchu Páně, kterýž mluvil.'),
(1573374,54,44,6,11,'Tedy lstivě nastrojili muže, kteříž řekli: My jsme jej slyšeli mluviti slova rouhavá proti Mojžíšovi a proti Bohu.'),
(1573375,54,44,6,12,'A tak zbouřili lid a starší i zákoníky, a obořivše se na něj, chytili jej, a vedli do rady.'),
(1573376,54,44,6,13,'I vystavili falešné svědky, kteříž řekli: Člověk tento nepřestává mluviti slov rouhavých proti místu tomuto svatému i proti Zákonu.'),
(1573377,54,44,6,14,'Nebo jsme slyšeli jej, an praví: Že ten Ježíš Nazaretský zkazí místo toto, a promění ustanovení, kteráž nám vydal Mojžíš.'),
(1573378,54,44,6,15,'A pilně patříce na něj všickni, kteříž seděli v radě, viděli tvář jeho, jako tvář anděla.'),
(1573379,54,44,7,1,'Tedy řekl nejvyšší kněz: Jest-liž to tak?'),
(1573380,54,44,7,2,'A on řekl: Muži bratří a otcové, slyšte. Bůh slávy ukázal se otci našemu Abrahamovi, když byl v Mezopotamii, prve než bydlil v Cháran.'),
(1573381,54,44,7,3,'A řekl k němu: Vyjdi z země své a z příbuznosti své, a pojď do země, kterouž ukáži tobě.'),
(1573382,54,44,7,4,'Tedy vyšel z země Kaldejské a bydlil v Cháran. A odtud, když umřel otec jeho, přestěhoval jej do země této, v kteréžto vy nyní bydlíte.'),
(1573383,54,44,7,5,'A nedal jemu dědictví v ní, ani šlépěje nožné, ač byl jemu ji slíbil dáti k vladařství, i semeni jeho po něm, když ještě neměl dědice.'),
(1573384,54,44,7,6,'Mluvil pak jemu Bůh takto: Budeť símě tvé pohostinu v zemi cizí, a bude v službu podrobeno, a zle s ním budou nakládati za čtyři sta let.'),
(1573385,54,44,7,7,'Ale národ ten, jemuž sloužiti budou, já souditi budu, pravíť Bůh. A potom zase vyjdou, a sloužiti mi budou na tomto místě.'),
(1573386,54,44,7,8,'I vydal jemu smlouvu obřízky. A tak on zplodil Izáka, a obřezal jej osmého dne, a Izák zplodil Jákoba, a Jákob'),
(1573387,54,44,7,9,'A patriarchové v nenávisti měvše Jozefa, prodali jej do Egypta. Ale Bůh byl s ním,'),
(1573388,54,44,7,10,'A vysvobodil ho ze všech úzkostí jeho, a dal jemu milost a moudrost před tváří faraona, krále Egyptského, takže ho učinil úředníkem nad Egyptem a nade vším domem svým.'),
(1573389,54,44,7,11,'Potom přišel hlad na všecku zemi Egyptskou i Kananejskou, a soužení veliké, aniž měli pokrmů otcové naši.'),
(1573390,54,44,7,12,'A uslyšev Jákob, že by obilé bylo v Egyptě, poslal tam otce naše nejprve.'),
(1573391,54,44,7,13,'A když je poslal po druhé, poznán jest Jozef od bratří svých, a zjevena jest rodina Jozefova faraonovi.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573392,54,44,7,14,'Tedy poslav Jozef posly, přistěhoval otce svého Jákoba, i všecku rodinu svou v osobách sedmdesáti a pěti.'),
(1573393,54,44,7,15,'I vstoupil Jákob do Egypta, a tam umřel on i otcové naši.'),
(1573394,54,44,7,16,'I přeneseni jsou do Sichem, a pochováni v hrobě, kterýž byl koupil Abraham za stříbro od synů Emorových, otce Sichemova.'),
(1573395,54,44,7,17,'Když se pak přibližoval čas zaslíbení, o kterémž byl přisáhl Bůh Abrahamovi, rostl lid a množil se v Egyptě,'),
(1573396,54,44,7,18,'Až vtom povstal jiný král, kterýž neznal Jozefa.'),
(1573397,54,44,7,19,'Ten lstivě nakládaje s pokolením naším, trápil otce naše, takže musili vyhazovati nemluvňátka svá, aby se nerozplozovali.'),
(1573398,54,44,7,20,'V tom času narodil se Mojžíš, a byl velmi krásný, kterýžto chován jest za tři měsíce v domu otce svého.'),
(1573399,54,44,7,21,'A když vyložen byl na řeku, vzala jej dcera faraonova, a vychovala jej sobě za syna.'),
(1573400,54,44,7,22,'I vyučen jest Mojžíš vší moudrosti Egyptské, a byl mocný v řečech i v skutcích.'),
(1573401,54,44,7,23,'A když jemu bylo čtyřidceti let, vstoupilo na srdce jeho, aby navštívil bratří své, syny Izraelské.'),
(1573402,54,44,7,24,'A uzřev jednoho, an bezpráví trpí, zastal ho a pomstil toho, kterýž bezpráví trpěl, zabiv Egyptského.'),
(1573403,54,44,7,25,'Domníval se zajisté, že bratří jeho rozumějí tomu, že skrze ruku jeho chce jim dáti Bůh vysvobození, ale oni nerozuměli.'),
(1573404,54,44,7,26,'Druhého pak dne ukázal se jim, když se vadili, i chtěl je v pokoj uvésti, řka: Muži, bratří jste, i proč křivdu činíte sobě vespolek?'),
(1573405,54,44,7,27,'Ten pak, kterýž činil křivdu bližnímu svému, odehnal ho, řka: Kdo tě ustanovil knížetem a soudcím nad námi?'),
(1573406,54,44,7,28,'Což ty mne chceš zamordovati, jako jsi včera zabil Egyptského?'),
(1573407,54,44,7,29,'I utekl Mojžíš pro ta slova a bydlil pohostinu v zemi Madianské, a tam zplodil dva syny.'),
(1573408,54,44,7,30,'A když se vyplnilo let čtyřidceti, ukázal se jemu na poušti hory Sinai anděl Páně, v plameni ohně ve kři.'),
(1573409,54,44,7,31,'A Mojžíš uzřev to, divil se tomu vidění. A když blíže přistoupil, aby to pilněji spatřil, stal se k němu hlas Páně:'),
(1573410,54,44,7,32,'Jáť jsem Bůh otců tvých, Bůh Abrahamův a Bůh Izákův a Bůh Jákobův. I zhroziv se Mojžíš, neodvážil se patřiti.'),
(1573411,54,44,7,33,'I řekl jemu Pán: Zzuj obuv s noh svých; nebo místo, na kterémž stojíš, země svatá jest.'),
(1573412,54,44,7,34,'Viděl jsem, viděl trápení lidu svého, kterýž jest v Egyptě, a vzdychání jejich uslyšel jsem a sstoupil jsem, abych je vysvobodil. Protož nyní pojď, pošli tě do Egypta.'),
(1573413,54,44,7,35,'Toho Mojžíše, kteréhož se odepřeli, řkouce: Kdo tě ustanovil knížetem a soudcí? tohoť jest Bůh kníže a vysvoboditele poslal, skrze ruku anděla, kterýž se jemu ukázal ve kři.'),
(1573414,54,44,7,36,'A ten je vyvedl, čině divy a zázraky v zemi Egyptské a na moři Červeném, i na poušti za čtyřidceti let.'),
(1573415,54,44,7,37,'Toť jest ten Mojžíš, kterýž řekl synům Izraelským: Proroka vám vzbudí Pán Bůh váš z bratří vašich, podobně jako mne, toho poslouchejte.'),
(1573416,54,44,7,38,'Onť jest, kterýž byl mezi lidem na poušti s andělem, kterýž mluvíval k němu na hoře Sinai, i s otci našimi, kterýž přijal slova živá, aby je nám vydal.'),
(1573417,54,44,7,39,'Jehož nechtěli poslušni býti otcové naši, ale zavrhli jej, a odvrátili se srdci svými do Egypta,'),
(1573418,54,44,7,40,'Řkouce k Aronovi: Učiň nám bohy, kteříž by šli před námi; nebo Mojžíšovi tomu, kterýž nás vyvedl z země Egyptské, nevíme, co se přihodilo.'),
(1573419,54,44,7,41,'I udělali v těch dnech tele, a obětovali oběti modle, a veselili se v díle rukou svých.'),
(1573420,54,44,7,42,'I odvrátil se od nich Bůh, a vydal je, aby sloužili vojsku nebeskému, jakož napsáno jest v knihách Prorockých: Zdaliž jste mi oběti aneb dary obětovali za čtyřidceti let na poušti, dome Izraelský?'),
(1573421,54,44,7,43,'Nýbrž nosili jste stánek modly Moloch, a hvězdu boha vašeho Remfan, ta podobenství, kteráž jste zdělali sobě, abyste se jim klaněli. Protož přestěhuji vás za Babylon.'),
(1573422,54,44,7,44,'Stánek svědectví měli jsou otcové naši na poušti, jakož byl nařídil ten, jenž řekl Mojžíšovi, aby jej udělal, podle způsobu toho, kterýž byl viděl.'),
(1573423,54,44,7,45,'Kterýžto přijavše otcové naši, vnesli jej s Jozue tam, kdež bylo prve vladařství pohanů, kteréž vyhnal Bůh od tváři otců našich, až do dnů Davida.'),
(1573424,54,44,7,46,'Jenž nalezl milost před obličejem Božím, a prosil, aby nalezl stánek Bohu Jákobovu.'),
(1573425,54,44,7,47,'Šalomoun pak udělal jemu dům.'),
(1573426,54,44,7,48,'Ale Nejvyšší nebydlí v domích rukou udělaných, jakož dí prorok:'),
(1573427,54,44,7,49,'Nebe jest mi stolice a země podnož noh mých, i jakýž mi tedy dům uděláte? praví Pán. Anebo jaké jest místo odpočívání mého?'),
(1573428,54,44,7,50,'Zdaliž ruka má všeho toho neučinila?'),
(1573429,54,44,7,51,'Tvrdošijní a neobřezaného srdce i uší, vy jste se vždycky Duchu svatému protivili, jakož otcové vaši, takž i vy.'),
(1573430,54,44,7,52,'Kterému z proroků otcové vaši se neprotivili? Zmordovali zajisté ty, jenž předzvěstovali příchod spravedlivého tohoto, jehožto vy nyní zrádci a vražedníci jste.'),
(1573431,54,44,7,53,'Kteříž jste vzali Zákon působením andělským, a neostříhali jste ho.'),
(1573432,54,44,7,54,'Tedy slyšíce to, rozzlobili se v srdcích svých a škřipěli zuby na něho.'),
(1573433,54,44,7,55,'On pak pln jsa Ducha svatého, pohleděv do nebe, uzřel slávu Boží a Ježíše stojícího na pravici Boží.'),
(1573434,54,44,7,56,'I řekl: Aj, vidím nebesa otevřená a Syna člověka stojícího na pravici Boží.'),
(1573435,54,44,7,57,'A oni zkřikše hlasem velikým, zacpali uši své, a obořili se jednomyslně na něj.'),
(1573436,54,44,7,58,'A vyvedše jej z města, kamenovali ho. A svědkové složili roucha svá u noh mládence, kterýž sloul Saul.'),
(1573437,54,44,7,59,'I kamenovali Štěpána vzývajícího Boha a řkoucího: Pane Ježíši, přijmi ducha mého.'),
(1573438,54,44,7,60,'A poklek na kolena, zvolal hlasem velikým: Pane, nepokládej jim toho za hřích. A to pověděv, usnul v Pánu.'),
(1573439,54,44,8,1,'Saul pak také přivolil k usmrcení jeho. I přišlo v ten čas veliké protivenství na církev, kteráž byla v Jeruzalémě, a všickni se rozprchli po krajinách Judských a Samařských, kromě apoštolů.'),
(1573440,54,44,8,2,'I pochovali Štěpána muži pobožní, a plakali velmi nad ním.'),
(1573441,54,44,8,3,'Saul pak hubil církev, do domů vcházeje, a jímaje muže i ženy, dával je do žaláře.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573442,54,44,8,4,'Ti pak, kteříž se byli rozprchli, chodili, kážíce slovo Boží.'),
(1573443,54,44,8,5,'A Filip všed do města Samaří, kázal jim Krista.'),
(1573444,54,44,8,6,'I pozorovali zástupové s pilností jednomyslně toho, což se pravilo od Filipa, slyšíce a vidouce divy, kteréž činil.'),
(1573445,54,44,8,7,'Nebo duchové nečistí z mnohých, kteříž je měli, křičíce hlasem velikým, vycházeli, a mnozí šlakem poražení a kulhaví uzdraveni jsou.'),
(1573446,54,44,8,8,'A stala se radost veliká v tom městě.'),
(1573447,54,44,8,9,'Muž pak nějaký, jménem Šimon, před tím v tom městě čáry provodil, a lid Samařský mámil, pravě se býti nějakým velikým.'),
(1573448,54,44,8,10,'Na něhož pozor měli všickni, od nejmenšího až do největšího, říkajíce: Tentoť jest Boží moc veliká.'),
(1573449,54,44,8,11,'Pozor pak měli na něho, protože je za mnohý čas mámil svými čáry.'),
(1573450,54,44,8,12,'A když, uvěřivše Filipovi zvěstujícímu o království Božím a o jménu Ježíše Krista, křtili se muži i ženy,'),
(1573451,54,44,8,13,'Tedy i ten Šimon také uvěřil, a pokřtěn byv, přídržel se Filipa, a vida zázraky a moci veliké činěné, děsil se.'),
(1573452,54,44,8,14,'Uslyšavše pak v Jeruzalémě apoštolé, že by Samaří přijala slovo Boží, poslali k nim Petra a Jana.'),
(1573453,54,44,8,15,'Kteříž přišedše k nim, modlili se za ně, aby přijali Ducha svatého.'),
(1573454,54,44,8,16,'(Nebo ještě byl na žádného z nich nesstoupil, ale pokřtěni toliko byli ve jménu Pána Ježíše.)'),
(1573455,54,44,8,17,'Tedy vzkládali na ně ruce, a oni přijali Ducha svatého.'),
(1573456,54,44,8,18,'I uzřev Šimon, že skrze vzkládání rukou apoštolských dává se Duch svatý, přinesl jim peníze,'),
(1573457,54,44,8,19,'Řka: Dejte i mně tu moc, ať, na kohož bych koli vzložil ruce, přijme Ducha svatého.'),
(1573458,54,44,8,20,'I řekl k němu Petr: Peníze tvé buďtež s tebou na zatracení, protože jsi se domníval, že by dar Boží mohl býti zjednán za peníze.'),
(1573459,54,44,8,21,'Nemáš dílu ani losu v této věci; nebo srdce tvé není upřímé před Bohem.'),
(1573460,54,44,8,22,'Protož čiň pokání z této své nešlechetnosti, a pros Boha, zda by odpuštěno bylo tobě to myšlení srdce tvého.'),
(1573461,54,44,8,23,'Nebo v žluči hořkosti a v svazku nepravosti tebe býti vidím.'),
(1573462,54,44,8,24,'I odpověděv Šimon, řekl: Modltež vy se za mne Pánu, aby na mne nepřišlo něco z těch věcí, kteréž jste mluvili.'),
(1573463,54,44,8,25,'Oni pak osvědčovavše a mluvivše slovo Páně, navrátili se do Jeruzaléma, a ve mnohých městečkách Samaritánských kázali evangelium.'),
(1573464,54,44,8,26,'V tom anděl Páně mluvil k Filipovi, řka: Vstaň a jdi ku polední straně na cestu, kteráž vede od Jeruzaléma do města Gázy, kteréž jest pusté.'),
(1573465,54,44,8,27,'A on vstav, i šel. A aj, muž Mouřenín, kleštěnec, komorník královny Mouřenínské Kandáces, kterýž vládl všemi poklady jejími, a byl přijel do Jeruzaléma, aby se modlil,'),
(1573466,54,44,8,28,'Již se navracoval zase, sedě na voze svém, a četl Izaiáše proroka.'),
(1573467,54,44,8,29,'I řekl Duch k Filipovi: Přistup a přiviň se k vozu tomu.'),
(1573468,54,44,8,30,'A přiběh Filip, slyšel jej, an čte Izaiáše proroka. I řekl: Rozumíš-liž, co čteš?'),
(1573469,54,44,8,31,'A on řekl: Kterakž bych mohl rozuměti, leč by mi kdo vyložil? I prosil Filipa, aby vstoupil na vůz, a seděl s ním.'),
(1573470,54,44,8,32,'Místo pak toho Písma, kteréž četl, toto bylo: Jako ovce k zabití veden jest, a jako beránek němý před tím, kdož jej střiže, tak neotevřel úst svých.'),
(1573471,54,44,8,33,'V ponížení jeho odsouzení jeho vyhlazeno jest, rod pak jeho kdo vypraví, ačkoli zahlazen byl z země život jeho?'),
(1573472,54,44,8,34,'A odpovídaje komorník Filipovi, dí: Prosím tebe, o kom toto mluví prorok? Sám-li o sobě, čili o někom jiném?'),
(1573473,54,44,8,35,'Tedy otevřev Filip ústa svá, a počav od toho Písma, zvěstoval jemu Ježíše.'),
(1573474,54,44,8,36,'A když jeli cestou, přijeli k jedné vodě. I řekl komorník: Aj, teď voda. Proč nemám býti pokřtěn?'),
(1573475,54,44,8,37,'I řekl Filip: Věříš-li celým srdcem, slušíť. A on odpověděv, řekl: Věřím, že Ježíš Kristus jest Syn Boží.'),
(1573476,54,44,8,38,'I rozkázal státi vozu, a sstoupili oba do vody, i Filip i komorník. I pokřtil ho.'),
(1573477,54,44,8,39,'A když vystoupili z vody, Duch Páně pochopil Filipa, a neviděl ho více komorník; i jel cestou svou, raduje se.'),
(1573478,54,44,8,40,'Filip pak nalezen jest v Azotu; a chodě, kázal evangelium všem městům, až přišel do Cesaree.'),
(1573479,54,44,9,1,'Saul pak ještě dychtě po pohrůžkách a po mordu proti učedlníkům Páně, šel k nejvyššímu knězi,'),
(1573480,54,44,9,2,'A vyžádal od něho listy do Damašku do škol, nalezl-li by tam té cesty které muže nebo ženy, aby svázané přivedl do Jeruzaléma.'),
(1573481,54,44,9,3,'A když byl na cestě, stalo se, že již přibližoval se k Damašku. Tedy pojednou rychle obklíčilo jej světlo s nebe.'),
(1573482,54,44,9,4,'A padna na zem, uslyšel hlas řkoucí: Saule, Saule, proč mi se protivíš?'),
(1573483,54,44,9,5,'A on řekl: I kdo jsi, Pane? A Pán řekl: Já jsem Ježíš, jemuž ty se protivíš. Tvrdoť jest tobě proti ostnům se zpěčovati.'),
(1573484,54,44,9,6,'A on třesa se a boje se, řekl: Pane, co chceš, abych činil? A Pán k němu: Vstaň a jdi do města, a bude tobě povědíno, co bys ty měl činiti.'),
(1573485,54,44,9,7,'Ti pak muži, kteříž šli za ním, stáli, ohromeni jsouce, hlas zajisté slyšíce, ale žádného nevidouce.'),
(1573486,54,44,9,8,'I vstal Saul z země, a otevřev oči své, nic neviděl. Tedy pojavše ho za ruce, uvedli jej do Damašku.'),
(1573487,54,44,9,9,'I byl tu za tři dni nevida, a nejedl nic, ani nepil.'),
(1573488,54,44,9,10,'Byl pak jeden učedlník apoštolský v Damašku, jménem Ananiáš. I řekl k němu Pán u vidění: Ananiáši. A on řekl: Aj, já, Pane.'),
(1573489,54,44,9,11,'A Pán k němu: Vstaň a jdi do ulice, kteráž slove Přímá, a hledej v domě Judově Saule, jménem Tarsenského. Nebo aj, modlí se,'),
(1573490,54,44,9,12,'A viděl u vidění muže, Ananiáše jménem, an jde k němu, a vzkládá naň ruku, aby zrak přijal.'),
(1573491,54,44,9,13,'I odpověděl Ananiáš: Pane, slyšel jsem od mnohých o tom muži, kterak mnoho zlého činil svatým tvým v Jeruzalémě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573492,54,44,9,14,'A i zdeť má moc od předních kněží, aby jímal všecky, kteříž vzývají jméno tvé.'),
(1573493,54,44,9,15,'I řekl jemu Pán: Jdi, neboť on jest má nádoba vyvolená, aby nosil jméno mé před pohany i krále, i před syny Izraelské.'),
(1573494,54,44,9,16,'Jáť zajisté ukáži jemu, kterak on mnoho musí trpěti pro jméno mé.'),
(1573495,54,44,9,17,'I šel Ananiáš, a všel do toho domu, a vloživ ruce naň, řekl: Saule bratře, Pán Ježíš poslal mne, kterýž se ukázal tobě na cestě, po níž jsi šel, abys zrak přijal a naplněn byl Duchem svatým.'),
(1573496,54,44,9,18,'A hned spadly s očí jeho jako lupiny, a on prohlédl pojednou; a vstav, pokřtěn jest.'),
(1573497,54,44,9,19,'A přijav pokrm, posilnil se. I zůstal Saul s učedlníky, kteříž byli v Damašku, za několiko dní.'),
(1573498,54,44,9,20,'A hned v školách kázal Krista, pravě, že on jest Syn Boží.'),
(1573499,54,44,9,21,'I divili se náramně všickni, kteříž jej slyšeli, a pravili: Zdaliž toto není ten, jenž hubil v Jeruzalémě ty, kteříž vzývali jméno toto, a sem na to přišel, aby je svázané vedl k předním kněžím?'),
(1573500,54,44,9,22,'Saul pak mnohem více se zmocňoval a zahanboval Židy, kteříž byli v Damašku, potvrzuje toho, že ten jest Kristus.'),
(1573501,54,44,9,23,'A když přeběhlo drahně dnů, radu mezi sebou na tom zavřeli Židé, aby jej zabili.'),
(1573502,54,44,9,24,'Ale zvěděl Saul o těch úkladech jejich. Ostříhali také i bran ve dne i v noci, aby jej zahubili.'),
(1573503,54,44,9,25,'Ale učedlníci v noci vzavše ho, spustili jej po provaze přes zed v koši.'),
(1573504,54,44,9,26,'Přišed pak Saul do Jeruzaléma, pokoušel se přitovaryšiti k učedlníkům, ale báli se ho všickni, nevěříce, by byl učedlníkem.'),
(1573505,54,44,9,27,'Barnabáš pak přijav jej, vedl ho k apoštolům, a vypravoval jim, kterak na cestě viděl Pána, a že mluvil s ním, a kterak v Damašku svobodně mluvil ve jménu Ježíše.'),
(1573506,54,44,9,28,'I byl s nimi přebývaje v Jeruzalémě,'),
(1573507,54,44,9,29,'A směle mluvě ve jménu Pána Ježíše, a hádal se s Řeky; oni pak usilovali ho zabíti.'),
(1573508,54,44,9,30,'To zvěděvše bratří, dovedli ho do Cesaree, a poslali jej do Tarsu.'),
(1573509,54,44,9,31,'A tak sborové po všem Judstvu a Galilei i Samaří měli pokoj, vzdělávajíce se, a chodíce v bázni Páně, a rozhojňovali se potěšením Ducha svatého.'),
(1573510,54,44,9,32,'Stalo se pak, že Petr, když procházel všecky sbory, přišel také k svatým, kteříž byli v Lyddě.'),
(1573511,54,44,9,33,'I nalezl tu člověka jednoho, jménem Eneáše, již od osmi let na loži ležícího, kterýž byl šlakem poražený.'),
(1573512,54,44,9,34,'I řekl mu Petr: Eneáši, uzdravujeť tebe Ježíš Kristus; vstaň a ustel sobě. A hned vstal.'),
(1573513,54,44,9,35,'I viděli jej všickni, kteříž bydlili v Lyddě a v Sároně, kteříž se obrátili ku Pánu.'),
(1573514,54,44,9,36,'Byla pak jedna učedlnice v Joppen, jménem Tabita, což se vykládá Dorkas. Ta byla plná skutků dobrých a almužen, kteréž činila.'),
(1573515,54,44,9,37,'I stalo se v těch dnech, že roznemohši se, umřela. Kteroužto umyvše, položili na síň vrchní.'),
(1573516,54,44,9,38,'A že byla blízko Lydda od Joppen, uslyšavše učedlníci, že by tam byl Petr, poslali k němu dva muže, prosíce ho, aby sobě neobtěžoval přijíti až k nim.'),
(1573517,54,44,9,39,'Tedy vstav Petr, šel s nimi. A když přišel, vedli jej na síň. I obstoupily ho všecky vdovy, plačíce a ukazujíce sukně a pláště, kteréž jim dělala, dokudž s nimi byla, Dorkas.'),
(1573518,54,44,9,40,'I rozkázav všechněm vyjíti ven Petr, poklek na kolena, modlil se, a obrátiv se k tomu tělu, řekl: Tabito, vstaň. A ona otevřela oči své, a uzřevši Petra, posadila se.'),
(1573519,54,44,9,41,'A podav jí ruky Petr, pozdvihl jí; a povolav svatých a vdov, ukázal jim ji živou.'),
(1573520,54,44,9,42,'I rozhlášeno jest to po všem městě Joppen, a uvěřili mnozí v Pána.'),
(1573521,54,44,9,43,'I stalo se, že za mnohé dni pozůstal Petr v Joppen u nějakého Šimona koželuha.'),
(1573522,54,44,10,1,'Muž pak nějaký byl v Cesarii, jménem Kornelius, setník, z zástupu, kterýž sloul Vlaský,'),
(1573523,54,44,10,2,'Nábožný a bohobojný se vším domem svým, čině almužny mnohé lidu,'),
(1573524,54,44,10,3,'A modle se Bohu vždycky. Ten viděl u vidění zřetelně, jako v hodinu devátou na den, anděla Božího, an všel k němu, a řekl jemu: Kornéli.'),
(1573525,54,44,10,4,'A on pilně popatřil naň, a zstrašiv se, řekl: Co chceš, Pane? I řekl jemu: Modlitby tvé a almužny tvé vstoupily na pamět před tváří Boží.'),
(1573526,54,44,10,5,'Protož nyní pošli muže některé do Joppen, a povolej Šimona, kterýž má příjmí Petr.'),
(1573527,54,44,10,6,'Tenť hospodu má u nějakého Šimona koželuha, kterýž má dům u moře. Onť poví tobě, co bys měl činiti.'),
(1573528,54,44,10,7,'A když odšel anděl, kterýž mluvil Korneliovi, zavolal dvou služebníků svých, a rytíře pobožného z těch, kteříž vždycky při něm byli,'),
(1573529,54,44,10,8,'A pověděv jim všecko to, poslal je do Joppen.'),
(1573530,54,44,10,9,'Nazejtří pak, když oni šli a přibližovali se k městu, všel Petr nahoru, aby se modlil, v hodinu šestou.'),
(1573531,54,44,10,10,'A potom velice zlačněv, chtěl pojísti. Když pak oni strojili, připadlo na něj mysli vytržení.'),
(1573532,54,44,10,11,'I uzřel nebe otevřené a sstupující k sobě nádobu jakous jako prostěradlo veliké, za čtyři rohy uvázané, ano se spouští na zem,'),
(1573533,54,44,10,12,'Na němž byla všeliká zemská hovada čtvernohá, a zvířata, a zeměplazové, i ptactvo nebeské.'),
(1573534,54,44,10,13,'I stal se hlas k němu: Vstaň, Petře, bij a jez.'),
(1573535,54,44,10,14,'I řekl Petr: Nikoli, Pane, nebť jsem nikdy nejedl nic obecného anebo nečistého.'),
(1573536,54,44,10,15,'Tedy opět po druhé stal se hlas k němu: Cožť jest Bůh očistil, neměj ty toho za nečisté.'),
(1573537,54,44,10,16,'A to se stalo po třikrát. I vzato jest zase prostěradlo do nebe.'),
(1573538,54,44,10,17,'A když Petr sám u sebe rozjímal, co by znamenalo vidění to, kteréž viděl, aj muži ti, kteříž posláni byli od Kornelia, ptajíce se na dům Šimonův, stáli přede dveřmi.'),
(1573539,54,44,10,18,'A zavolavše kohosi, tázali se: Má-li zde hospodu Šimon, kterýž má příjmí Petr?'),
(1573540,54,44,10,19,'A když Petr přemyšloval o tom vidění, řekl jemu Duch: Aj, muži tři hledají tebe.'),
(1573541,54,44,10,20,'Protož vstana, sejdi dolů a jdi s nimi, nic nepochybuje; neboť jsem já je poslal.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573542,54,44,10,21,'Tedy sšed Petr k mužům, jenž posláni byli k němu od Kornelia, řekl: Aj, jáť jsem ten, kteréhož hledáte. Jaká jest příčina, pro niž jste přišli?'),
(1573543,54,44,10,22,'Oni pak řekli: Kornelius setník, muž spravedlivý a bohabojící, i svědectví dobré mající ode všeho národu Židovského, u vidění napomenut jest od anděla svatého, aby povolal tebe do domu svého a slyšel řeč od tebe.'),
(1573544,54,44,10,23,'Tedy zavolav jich do domu, přijal je do hospody. Druhého pak dne Petr šel s nimi, a někteří bratří z Joppen šli s ním.'),
(1573545,54,44,10,24,'A nazejtří přišli do Cesaree. Kornelius pak očekával jich, svolav příbuzné své a přátely blízké.'),
(1573546,54,44,10,25,'I stalo se, když vcházel Petr, vyšel proti němu Kornelius, a padna k nohám jeho, klaněl se mu.'),
(1573547,54,44,10,26,'Ale Petr pozdvihl ho, řka: Vstaň, všakť i já také člověk jsem.'),
(1573548,54,44,10,27,'A rozmlouvaje s ním, všel do domu, a nalezl mnoho těch, kteříž se byli sešli.'),
(1573549,54,44,10,28,'I řekl k nim: Vy víte, že neslušné jest muži Židu připojiti se aneb přistoupiti k cizozemci, ale mně ukázal Bůh, abych žádného člověka nepravil obecným neb nečistým býti.'),
(1573550,54,44,10,29,'Protož bez odporu přišel jsem, povolán jsa. I ptám se vás, pro kterou příčinu poslali jste pro mne?'),
(1573551,54,44,10,30,'A Kornelius řekl: Přede čtyřmi dny postil jsem se až do této hodiny, a v hodinu devátou modlil jsem se v domu svém. A aj, postavil se přede mnou muž v rouše bělostkvoucím,'),
(1573552,54,44,10,31,'A řekl: Kornéli, uslyšánať jest modlitba tvá a almužny tvé jsouť v paměti před tváří Boží.'),
(1573553,54,44,10,32,'Protož pošli do Joppen a povolej Šimona, kterýž slove Petr. Tenť má hospodu v domu Šimona koželuha u moře; on přijda, bude mluviti tobě.'),
(1573554,54,44,10,33,'Já pak hned jsem poslal k tobě, a ty jsi dobře učinil, žes přišel. Nyní tedy my všickni před obličejem Božím hotovi jsme slyšeti všecko, což jest koli přikázáno tobě od Boha.'),
(1573555,54,44,10,34,'Tedy Petr otevřev ústa, řekl: V pravdě jsem shledal, že Bůh není přijimač osob.'),
(1573556,54,44,10,35,'Ale v každém národu, kdož se ho bojí a činí spravedlnost, příjemný jest jemu;'),
(1573557,54,44,10,36,'Jakž to oznámil synům Izraelským, zvěstuje pokoj skrze Ježíše Krista, jenž jest Pánem všeho.'),
(1573558,54,44,10,37,'O čemž i vy sami víte, co se dálo po všem Židovstvu, počna od Galilee, po křtu, kterýž kázal Jan:'),
(1573559,54,44,10,38,'Kterak Ježíše od Nazaréta pomazal Bůh Duchem svatým a mocí; kterýžto chodil, dobře čině, a uzdravuje všecky posedlé od ďábla; nebo Bůh s ním byl.'),
(1573560,54,44,10,39,'A my jsme svědkové všeho toho, což jest činil v krajině Judské a v Jeruzalémě. Kteréhožto zamordovali jsou, pověsivše na dřevě.'),
(1573561,54,44,10,40,'Toho Bůh vzkřísil třetího dne, a způsobil to, aby zjeven byl,'),
(1573562,54,44,10,41,'Ne všemu lidu, ale svědkům prve k tomu zřízeným od Boha, nám, kteříž jsme s ním jedli a pili po jeho z mrtvých vstání.'),
(1573563,54,44,10,42,'A přikázal nám kázati lidu a svědčiti, že on jest ten ustanovený od Boha soudce živých i mrtvých.'),
(1573564,54,44,10,43,'Jemuť všickni proroci svědectví vydávají, že odpuštění hříchů vezme skrze jméno jeho všeliký, kdožkoli uvěřil by v něho.'),
(1573565,54,44,10,44,'A když ještě Petr mluvil slova tato, sstoupil Duch svatý na všecky, kteříž poslouchali slova Božího.'),
(1573566,54,44,10,45,'I užasli se ti, jenž z obřezaných věřící byli, kteříž byli přišli s Petrem, že i na pohany dar Ducha svatého jest vylit.'),
(1573567,54,44,10,46,'Nebo slyšeli je, ani mluví jazyky rozličnými, a velebí Boha. Tedy odpověděl Petr:'),
(1573568,54,44,10,47,'Zdali může kdo zabrániti vody, aby tito nebyli pokřtěni, kteříž Ducha svatého přijali jako i my?'),
(1573569,54,44,10,48,'A rozkázal je pokřtíti ve jménu Páně. I prosili ho, aby u nich pobyl za některý den.'),
(1573570,54,44,11,1,'Uslyšeli pak apoštolé a bratří, kteříž byli v Judstvu, že by i pohané přijali slovo Boží.'),
(1573571,54,44,11,2,'A když přišel Petr do Jeruzaléma, domlouvali se naň ti, kteříž byli z obřezaných,'),
(1573572,54,44,11,3,'Řkouce: K mužům neobřezaným všel jsi, a jedl jsi s nimi.'),
(1573573,54,44,11,4,'Tedy začav Petr, vypravoval jim pořád, řka:'),
(1573574,54,44,11,5,'Byl jsem v městě Joppen, modle se. I viděl jsem u vytržení mysli jsa vidění, nádobu nějakou sstupující jako prostěradlo veliké, za čtyři rohy přivázané, ano se spouští s nebe, a přišlo až ke mně.'),
(1573575,54,44,11,6,'V kteréž pohleděv pilně, spatřil jsem hovada zemská čtvernohá, i zvířata, a zeměplazy, i ptactvo nebeské.'),
(1573576,54,44,11,7,'Slyšel jsem také i hlas ke mně řkoucí: Vstaň, Petře, bij a jez.'),
(1573577,54,44,11,8,'I řekl jsem: Nikoli, Pane, nebo nic obecného aneb nečistého nikdy nevcházelo v ústa má.'),
(1573578,54,44,11,9,'I odpověděl mi hlas po druhé s nebe, řka: Co jest Bůh očistil, neměj ty toho za nečisté.'),
(1573579,54,44,11,10,'A to se stalo po třikrát. I vtrženo jest zase to všecko do nebe.'),
(1573580,54,44,11,11,'A aj, hned té chvíle tři muži stáli u domu, v kterémž jsem byl, posláni jsouce ke mně z Cesaree.'),
(1573581,54,44,11,12,'I řekl mi Duch, abych šel s nimi, nic nepochybuje. A šlo se mnou i těchto šest bratří, a vešli jsme do domu muže jednoho.'),
(1573582,54,44,11,13,'Kterýžto vypravoval nám, kterak viděl anděla v domu svém, an se před ním postavil a řekl jemu: Pošli do Joppen muže některé a povolej Šimona, kterýž slove Petr.'),
(1573583,54,44,11,14,'Onť tobě bude mluviti slova, skrze něž spasen budeš ty i všecken tvůj dům.'),
(1573584,54,44,11,15,'Když jsem pak já mluviti začal, sstoupil Duch svatý na ně jako i na nás na počátku.'),
(1573585,54,44,11,16,'I rozpomenul jsem se na slovo Páně, kteréž byl pověděl: Jan zajisté křtil vodou, ale vy pokřtěni budete Duchem svatým.'),
(1573586,54,44,11,17,'Poněvadž tedy jednostejný dar dal jim Bůh jako i nám, kteříž uvěřili v Pána Ježíše Krista, i kdož jsem já byl, abych mohl zabrániti Bohu?'),
(1573587,54,44,11,18,'To uslyšavše, spokojili se a slavili Boha, řkouce: Tedy i pohanům Bůh pokání dal k životu.'),
(1573588,54,44,11,19,'Ti pak, kteříž se byli rozprchli příčinou soužení, kteréž se bylo stalo pro Štěpána, přišli až do Fenicen a Cypru a do Antiochie, žádnému nemluvíce slova Božího než samým toliko Židům.'),
(1573589,54,44,11,20,'A byli někteří z nich muži z Cypru a někteří Cyrenenští, kteřížto přišedše do Antiochie, mluvili Řekům, zvěstujíce jim Pána Ježíše.'),
(1573590,54,44,11,21,'A byla ruka Páně s nimi, a veliký počet věřících obrátil se ku Pánu.'),
(1573591,54,44,11,22,'I přišla pověst o tom k církvi, kteráž byla v Jeruzalémě. I poslali Barnabáše, aby šel až do Antiochie.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573592,54,44,11,23,'Kterýžto přišed tam, a uzřev milost Boží, zradoval se, a napomínal všech, aby v úmyslu srdce svého trvali v Pánu.'),
(1573593,54,44,11,24,'Nebo byl muž dobrý, a plný Ducha svatého a víry. I přibyl jich tu veliký zástup Pánu.'),
(1573594,54,44,11,25,'Tedy šel odtud Barnabáš do Tarsu hledati Saule, a nalezna jej, přivedl ho do Antiochie.'),
(1573595,54,44,11,26,'I byli přes celý rok při tom sboru, a učili zástup veliký, takže nejprv tu v Antiochii učedlníci nazváni jsou křesťané.'),
(1573596,54,44,11,27,'V těch pak dnech přišli z Jeruzaléma proroci do Antiochie.'),
(1573597,54,44,11,28,'I povstav jeden z nich, jménem Agabus, oznamoval, ponuknut jsa skrze Ducha, že bude hlad veliký po všem okršlku zemském. Kterýžto i stal se za císaře Klaudia.'),
(1573598,54,44,11,29,'Tedy učedlníci, jeden každý podle možnosti své, umínili poslati něco ku pomoci bratřím přebývajícím v Judstvu.'),
(1573599,54,44,11,30,'Což i učinili, poslavše k starším skrze ruce Barnabáše a Saule.'),
(1573600,54,44,12,1,'A při tom času dal se v to Herodes král, aby sužoval některé z církve.'),
(1573601,54,44,12,2,'I zamordoval Jakuba, bratra Janova, mečem.'),
(1573602,54,44,12,3,'A vida, že se to líbilo Židům, umínil jíti i Petra. (A byli dnové přesnic.)'),
(1573603,54,44,12,4,'Kteréhož jav, do žaláře vsadil, poručiv jej šestnácti žoldnéřům k ostříhání, chtěje po velikonoci vyvésti jej lidu.'),
(1573604,54,44,12,5,'I byl Petr ostříhán v žaláři, modlitba pak ustavičná k Bohu dála se za něj od církve.'),
(1573605,54,44,12,6,'A když jej již vyvésti měl Herodes, té noci spal Petr mezi dvěma žoldnéři, svázán jsa dvěma řetězy, a strážní přede dveřmi ostříhali žaláře.'),
(1573606,54,44,12,7,'A aj, anděl Páně postavil se, a světlo se zastkvělo v žaláři; a udeřiv Petra v bok, zbudil ho, řka: Vstaň rychle. I spadli řetězové s rukou jeho.'),
(1573607,54,44,12,8,'Tedy řekl anděl k němu: Opaš se a podvaž obuv svou. To když učinil, řekl jemu: Oděj se pláštěm svým, a pojď za mnou.'),
(1573608,54,44,12,9,'I vyšed, bral se za ním, a nevěděl, by to pravé bylo, co se dálo skrze anděla, ale domníval se, že by vidění viděl.'),
(1573609,54,44,12,10,'A prošedše skrze první i druhou stráž, přišli k bráně železné, kteráž vede do města, a ta se jim hned sama otevřela. A všedše skrze ni, přešli ulici jednu, a hned odšel anděl od něho.'),
(1573610,54,44,12,11,'Tedy Petr přišed sám k sobě, řekl: Nyní právě vím, že poslal Pán anděla svého, a vytrhl mne z ruky Herodesovy, a ze všeho očekávání lidu Židovského.'),
(1573611,54,44,12,12,'A pováživ toho, šel k domu Marie, matky Janovy, kterýž příjmí měl Marek, kdež se jich bylo mnoho sešlo, a modlili se.'),
(1573612,54,44,12,13,'A když Petr potloukl na dveře, vyšla děvečka, aby poslechla, jménem Ródé.'),
(1573613,54,44,12,14,'A poznavši hlas Petrův, pro radost neotevřela dveří, ale vběhši, zvěstovala, že Petr stojí u dveří.'),
(1573614,54,44,12,15,'A oni řekli jí: I co blázníš? Ona pak potvrzovala, že tak jest. Tedy oni řekli: Anděl jeho jest.'),
(1573615,54,44,12,16,'Ale Petr předce tloukl. A otevřevše dveře, uzřeli jej, i ulekli se.'),
(1573616,54,44,12,17,'A pokynuv na ně rukou, aby mlčeli, vypravoval jim, kterak jest jej Pán vyvedl z žaláře, a potom řekl: Pověztež to Jakubovi a bratřím. A vyšed, bral se na jiné místo.'),
(1573617,54,44,12,18,'A když byl den, stal se rozbroj nemalý mezi žoldnéři o to, co se stalo při Petrovi.'),
(1573618,54,44,12,19,'Herodes pak ptaje se na něj, a nenalezna, vytazovav se na strážných, kázal je pryč vésti; a odebrav se z Judstva do Cesaree, přebýval tam.'),
(1573619,54,44,12,20,'A v ten čas Herodes rozzlobil se proti Tyrským a Sidonským. Kteřížto jednomyslně přišli k němu, a namluvivše sobě Blasta, předního komorníka královského, žádali za pokoj, protože jejich krajiny potravu měly z zemí královských.'),
(1573620,54,44,12,21,'V uložený pak den Herodes, obleka se v královské roucho, a posadiv se na soudné stolici, učinil k nim řeč.'),
(1573621,54,44,12,22,'I zvolal lid, řka: Boží jest toto hlas, a ne lidský.'),
(1573622,54,44,12,23,'A ihned ranil jej anděl Páně, protože nevzdal slávy Bohu; a rozlez se červy, umřel.'),
(1573623,54,44,12,24,'A slovo Páně rostlo a rozmáhalo se.'),
(1573624,54,44,12,25,'Barnabáš pak a Saul navrátili se z Jeruzaléma, vykonavše službu, pojavše s sebou i Jana, kterýž příjmí měl Marek.'),
(1573625,54,44,13,1,'Byli pak v církvi, kteráž byla v Antiochii, proroci a učitelé, jako Barnabáš a Šimon, kterýž měl příjmí Černý, a Lucius Cyrenenský, a Manahen, kterýž byl spolu vychován s Herodesem tetrarchou, a Saul.'),
(1573626,54,44,13,2,'A když oni služby Páně konali a postili se, dí jim Duch svatý: Oddělte mi Barnabáše a Saule k dílu, k kterémuž jsem jich povolal.'),
(1573627,54,44,13,3,'Tedy postíce se, a modlíce se, a vzkládajíce na ně ruce, propustili je.'),
(1573628,54,44,13,4,'A oni posláni jsouce od Ducha svatého, přišli do Seleucie, a odtud plavili se do Cypru.'),
(1573629,54,44,13,5,'A přišedše do Salaminy, kázali slovo Boží v školách Židovských; a měli s sebou i Jana k službě.'),
(1573630,54,44,13,6,'A když zchodili ten ostrov až do Páfu, nalezli tu jakéhos čarodějníka, falešného proroka Žida, jemuž jméno bylo Barjezus,'),
(1573631,54,44,13,7,'Kterýž byl u znamenitého vladaře Sergia Pavla, muže opatrného. Ten povolav Barnabáše a Saule, žádal od nich slyšeti slovo Boží.'),
(1573632,54,44,13,8,'Ale protivil se jim Elymas, totiž čarodějník ten, (nebo se tak vykládá jméno jeho,) usiluje odvrátiti vladaře od víry.'),
(1573633,54,44,13,9,'Tedy Saul, kterýž slove i Pavel, naplněn jsa Duchem svatým, pilně pohleděv na něj,'),
(1573634,54,44,13,10,'Řekl: Ó plný vší lsti a vší nešlechetnosti, synu ďáblův, a nepříteli vší spravedlnosti, což nepřestaneš převraceti cest Páně přímých?'),
(1573635,54,44,13,11,'A aj, nyní ruka Páně nad tebou, a budeš slepý, nevida slunce až do času. A pojednou připadla na něj mrákota a tma, a jda vůkol, hledal, kdo by ho za ruku vedl.'),
(1573636,54,44,13,12,'Tehdy vladař uzřev, co se stalo, uvěřil, divě se učení Páně.'),
(1573637,54,44,13,13,'A pustivše se od Páfu Pavel a ti, kteříž s ním byli, přišli do města Pergen v krajině Pamfylii. Jan pak odšed od nich, vrátil se do Jeruzaléma.'),
(1573638,54,44,13,14,'Oni pak šedše z Pergen, přišli do Antiochie Pisidické, a všedše do školy v den sobotní, posadili se.'),
(1573639,54,44,13,15,'A když bylo po čtení Zákona a Proroků, poslali k nim knížata školy té řkouce: Muži bratří, máte-li úmysl jaké napomenutí učiniti k lidu, mluvte.'),
(1573640,54,44,13,16,'Tedy Pavel povstav a rukou, aby mlčeli, pokynuv, řekl: Muži Izraelští, a kteříž se bojíte Boha, slyšte.'),
(1573641,54,44,13,17,'Bůh lidu tohoto Izraelského vyvolil otce naše a lidu povýšil, když byl pohostinu v zemi Egyptské, a v rameni vztaženém vyvedl je z ní.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573642,54,44,13,18,'A za čas čtyřidceti let snášel jejich obyčeje na poušti.'),
(1573643,54,44,13,19,'A zahladiv sedm národů v zemi Kanán, rozdělil losem mezi ně zemi jejich.'),
(1573644,54,44,13,20,'A potom, téměř za čtyři sta a padesáte let, dával jim soudce až do Samuele proroka.'),
(1573645,54,44,13,21,'A vtom žádali za krále, i dal jim Bůh Saule, syna Cis, muže z pokolení Beniaminova, za čtyřidceti let.'),
(1573646,54,44,13,22,'A když toho zavrhl, vzbudil jim Davida krále, kterémužto svědectví dávaje, řekl: Nalezl jsem Davida, syna Jesse, muže podle srdce svého, kterýž bude činiti všecku vůli mou.'),
(1573647,54,44,13,23,'Z jehožto semene Bůh podle zaslíbení vzbudil lidu Izraelskému Spasitele Ježíše,'),
(1573648,54,44,13,24,'Před jehožto příštím kázal Jan křest pokání všemu lidu Izraelskému.'),
(1573649,54,44,13,25,'A když Jan dokonával běh svůj, pravil: Kteréhož se mne domníváte býti, nejsem já ten, ale aj, přijdeť po mně tak důstojný, ješto já nejsem hoden rozvázati obuvi noh jeho.'),
(1573650,54,44,13,26,'Muži bratří, synové rodu Abrahamova, a kteříž mezi vámi jsou bojící se Boha, vám slovo spasení tohoto posláno jest.'),
(1573651,54,44,13,27,'Nebo ti, kteříž přebývají v Jeruzalémě, a knížata jejich, toho Ježíše neznajíce, odsoudili, a tak hlasy Prorocké, kteříž se na každou sobotu čtou, naplnili.'),
(1573652,54,44,13,28,'A nižádné viny hodné smrti na něm nenalezše, aby zamordován byl, Piláta prosili.'),
(1573653,54,44,13,29,'A když dokonali všecko, což o něm psáno bylo, složen jsa s dřeva, do hrobu jest položen.'),
(1573654,54,44,13,30,'Bůh pak vzkřísil jej z mrtvých.'),
(1573655,54,44,13,31,'Kterýžto vidín jest po mnohé dni od těch, jenž spolu s ním byli přišli z Galilee do Jeruzaléma, kteřížto jsou svědkové jeho k lidu.'),
(1573656,54,44,13,32,'A my vám zvěstujeme to zaslíbení, které se stalo otcům, že jest je již Bůh naplnil nám synům jejich, vzkřísiv Ježíše;'),
(1573657,54,44,13,33,'Jakož i v druhém Žalmu napsáno jest: Syn můj jsi ty, já dnes zplodil jsem tebe.'),
(1573658,54,44,13,34,'A že jej z mrtvých vzkřísil, aby se již více nenavracoval v porušení, takto o tom řekl: Dám vám svaté věci Davidovy věrné.'),
(1573659,54,44,13,35,'Protož i v jiném Žalmu dí: Nedáš svatému svému viděti porušení.'),
(1573660,54,44,13,36,'David zajisté za svého věku poslouživ vůli Boží, usnul, a přiložen jest k otcům svým, a viděl porušení,'),
(1573661,54,44,13,37,'Ale ten, kteréhož Bůh vzkřísil, neviděl porušení.'),
(1573662,54,44,13,38,'Protož známo vám buď, muži bratří, že skrze toho zvěstuje se vám odpuštění hříchů,'),
(1573663,54,44,13,39,'A to ode všech, od kterýchž jste nemohli skrze Zákon Mojžíšův ospravedlněni býti, skrze tohoto každý, kdož věří, bývá ospravedlněn.'),
(1573664,54,44,13,40,'Protož vizte, ať na vás nepřijde to, což jest v Prorocích povědíno:'),
(1573665,54,44,13,41,'Vizte potupníci, a podivte se, a na nic přijďte; nebo já dílo dělám za dnů vašich, dílo to, o kterémž vy neuvěříte, kdyby je vám kdo vypravoval.'),
(1573666,54,44,13,42,'A když vycházeli ze školy Židovské, prosili jich pohané, aby jim v druhou sobotu mluvili táž slova.'),
(1573667,54,44,13,43,'A když bylo rozpuštěno shromáždění, šlo mnoho Židů a nábožných lidí znovu na víru obrácených za Pavlem a Barnabášem, kteřížto promlouvajíce k nim, radili jim, aby trvali v milosti Boží.'),
(1573668,54,44,13,44,'V druhou pak sobotu téměř všecko město sešlo se k slyšení slova Božího.'),
(1573669,54,44,13,45,'A Židé vidouce zástupy, naplněni jsou závistí, a odporovali tomu, co bylo praveno od Pavla, protivíce a rouhajíce se.'),
(1573670,54,44,13,46,'Tedy svobodně Pavel a Barnabáš řekli: Vámť jest mělo nejprv mluveno býti slovo Boží, ale poněvadž je zamítáte, a za nehodné sebe soudíte věčného života, aj, obracíme se ku pohanům.'),
(1573671,54,44,13,47,'Neboť jest nám tak přikázal Pán, řka: Položil jsem tebe světlo pohanům, tak abys ty byl spasení až do končin země.'),
(1573672,54,44,13,48,'A slyšíce to pohané, zradovali se a velebili slovo Páně; a uvěřili všickni, což jich koli bylo předzřízeno k životu věčnému.'),
(1573673,54,44,13,49,'I rozhlašovalo se slovo Páně po vší krajině.'),
(1573674,54,44,13,50,'Tedy Židé zbouřili ženy nábožné a poctivé a přední měšťany, a vzbudili protivenství proti Pavlovi a Barnabášovi, i vyhnali je z končin svých.'),
(1573675,54,44,13,51,'A oni vyrazivše prach z noh svých na ně, přišli do Ikonie.'),
(1573676,54,44,13,52,'Učedlníci pak naplněni byli radostí a Duchem svatým.'),
(1573677,54,44,14,1,'I stalo se v Ikonii, že vešli spolu do školy Židovské, a mluvili slovo Boží, takže jest uvěřilo i Židů i Řeků veliké množství.'),
(1573678,54,44,14,2,'Ale kteříž z Židů nepovolní byli, ti zbouřili a zdráždili mysli pohanů proti bratřím.'),
(1573679,54,44,14,3,'I byli tu za dlouhý čas, směle a svobodně mluvíce v Pánu, kterýž svědectví vydával slovu milosti své, a působil to, aby se dáli divové a zázrakové skrze ruce jejich.'),
(1573680,54,44,14,4,'I rozdělilo se množství města, a jedni byli s Židy, a jiní s apoštoly.'),
(1573681,54,44,14,5,'A když se obořili na apoštoly i pohané i Židé s knížaty svými, aby je utiskli a kamenovali,'),
(1573682,54,44,14,6,'Oni srozuměvše tomu, utekli do měst Lykaonitských, do Lystry a do Derben, a do toho okolí,'),
(1573683,54,44,14,7,'A tu kázali evangelium.'),
(1573684,54,44,14,8,'Muž pak nějaký v Lystře, nemocný na nohy, sedával, chromý jsa hned z života matky své, kterýž nikdy nechodil.'),
(1573685,54,44,14,9,'Ten poslouchal Pavla mluvícího. Kterýžto pohleděv naň, a vida, an věří, že uzdraven bude,'),
(1573686,54,44,14,10,'Řekl velikým hlasem: Postav se přímě na nohách svých. I zchopil se a chodil.'),
(1573687,54,44,14,11,'Zástupové pak viděvše, co učinil Pavel, pozdvihli hlasu svého, Lykaonitsky řkouce: Bohové připodobnivše se lidem, sstoupili k nám.'),
(1573688,54,44,14,12,'I nazvali Barnabáše Jupiterem a Pavla Merkuriášem; nebo on mluvil slovo Boží.'),
(1573689,54,44,14,13,'Tedy kněz Jupitera, modly té, kteráž byla před městem jejich, přivedl býky a přinesl věnce před bránu, a chtěl s lidem oběti obětovati.'),
(1573690,54,44,14,14,'To když uslyšeli apoštolé, Barnabáš a Pavel, roztrhše sukně své, vyběhli k zástupům, křičíce,'),
(1573691,54,44,14,15,'A řkouce: Muži, což to činíte? Však i my lidé jsme, týmž bídám jako i vy poddaní, kteříž vás napomínáme, abyste se obrátili od těchto marností k Bohu živému, kterýž učinil nebe i zemi, i moře, i všecko, což v nich jest.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573692,54,44,14,16,'Kterýžto za předešlých věků všech pohanů nechával, aby chodili po cestách svých,'),
(1573693,54,44,14,17,'Ačkoli proto nenechal sebe bez osvědčení, dobře čině, dávaje nám s nebe déšť a časy úrodné, naplňuje pokrmem a potěšením srdce naše.'),
(1573694,54,44,14,18,'A to mluvíce, sotva spokojili zástupy, aby jim neobětovali.'),
(1573695,54,44,14,19,'A vtom přišli od Antiochie a Ikonie nějací Židé, kteřížto navedše zástupy, a ukamenovavše Pavla, vytáhli jej před město, domnívajíce se, že umřel.'),
(1573696,54,44,14,20,'A když jej obstoupili učedlníci, vstal a všel do města, a nazejtří odšel s Barnabášem do Derben.'),
(1573697,54,44,14,21,'A kázavše evangelium městu tomu, a učedlníků mnoho získavše, navrátili se do Lystry a do Ikonie a do Antiochie,'),
(1573698,54,44,14,22,'Potvrzujíce duší učedlníků, a napomínajíce jich, aby trvali u víře, a pravíce, že musíme skrze mnohá soužení vjíti do království Božího.'),
(1573699,54,44,14,23,'A zřídivše jim, podle daných hlasů, starší po církvech, a modlivše se s postem, poručili je Pánu, v kteréhož jsou uvěřili.'),
(1573700,54,44,14,24,'A prošedše Pisidii, přišli do Pamfylie,'),
(1573701,54,44,14,25,'A mluvivše slovo Boží v Pergen, šli do města Attalie.'),
(1573702,54,44,14,26,'A odtud plavili se do Antiochie, odkudž poručeni byli milosti Boží k dílu, kteréž jsou vykonali.'),
(1573703,54,44,14,27,'A když tam přišli a shromáždili církev, vypravovali jim, kteraké věci Bůh skrze ně učinil a že otevřel pohanům dveře víry.'),
(1573704,54,44,14,28,'I byli tu za dlouhý čas s učedlníky.'),
(1573705,54,44,15,1,'Přišedše pak někteří z Židovstva, učili bratří: Že nebudete-li se obřezovati podle obyčeje Mojžíšova, nebudete moci spaseni býti.'),
(1573706,54,44,15,2,'A když se stala mezi nimi různice, a nemalou hádku Pavel a Barnabáš s nimi měl, i zůstali na tom, aby Pavel a Barnabáš a někteří jiní z nich šli k apoštolům a starším do Jeruzaléma o tu otázku.'),
(1573707,54,44,15,3,'Tedy oni jsouce vyprovozeni od církve, šli skrze Fenicen a Samaří, vypravujíce o obrácení pohanů na víru, i způsobili radost velikou všem bratřím.'),
(1573708,54,44,15,4,'A když se dostali do Jeruzaléma, přijati jsou od církve a od apoštolů a starších. I zvěstovali jim, kteraké věci činil skrze ně Bůh.'),
(1573709,54,44,15,5,'A že povstali někteří z sekty farizejské, kteříž byli uvěřili, pravíce, že musejí obřezováni býti, a potom aby jim bylo přikázáno zachovávati zákon Mojžíšův.'),
(1573710,54,44,15,6,'Tedy sešli se apoštolé a starší, aby toho povážili.'),
(1573711,54,44,15,7,'A když mnohé vyhledávání toho bylo, povstav Petr, řekl k nim: Muži bratří, vy víte, že od dávních dnů mezi námi Bůh vyvolil mne, aby skrze ústa má slyšeli pohané slovo evangelium a uvěřili.'),
(1573712,54,44,15,8,'A ten, jenž zpytuje srdce, Bůh, svědectví jim vydal, dav jim Ducha svatého, jako i nám.'),
(1573713,54,44,15,9,'A neučinil rozdílu mezi nimi a námi, věrou očistiv srdce jejich.'),
(1573714,54,44,15,10,'Protož nyní, proč pokoušíte Boha, chtíce vzložiti na hrdlo učedlníků jho, kteréhož ani otcové naši, ani my nésti jsme nemohli?'),
(1573715,54,44,15,11,'Ale skrze milost Pána Ježíše Krista věříme, že spaseni budeme, rovně jako i oni.'),
(1573716,54,44,15,12,'I mlčelo všecko to množství, a poslouchali Barnabáše a Pavla, vypravujících, kteraké divy a zázraky činil Bůh skrze ně mezi pohany.'),
(1573717,54,44,15,13,'A když oni tak umlkli, odpověděl Jakub, řka: Muži bratří, slyšte mne.'),
(1573718,54,44,15,14,'Šimon teď vypravoval, kterak Bůh nejprve popatřil na pohany, aby z nich přijal lid jménu svému.'),
(1573719,54,44,15,15,'A s tím se srovnávají i řeči prorocké, jakož psáno jest:'),
(1573720,54,44,15,16,'Potom se navrátím, a vzdělám zase stánek Davidův, kterýž byl klesl, a zbořeniny jeho zase vzdělám, a vyzdvihnu jej,'),
(1573721,54,44,15,17,'Tak aby ti ostatkové toho lidu hledali Pána, i všickni pohané, nad kterýmiž jest vzýváno jméno mé, dí Pán, jenž činí tyto všecky věci.'),
(1573722,54,44,15,18,'Známáť jsou Bohu od věků všecka díla jeho.'),
(1573723,54,44,15,19,'Protož já tak soudím, aby nebyli kormouceni ti, kteříž se z pohanů obracejí k Bohu,'),
(1573724,54,44,15,20,'Ale aby jim napsáno bylo, ať se zdržují od poskvrn modl, a smilstva, a toho, což jest udáveného a od krve.'),
(1573725,54,44,15,21,'Nebo Mojžíš od dávních věků má po všech městech, kdo by jej kázal v školách, poněvadž na každou sobotu čítán bývá.'),
(1573726,54,44,15,22,'Tehdy vidělo se apoštolům a starším se vší církví, aby vyvolili z sebe muže a poslali je do Antiochie s Pavlem a Barnabášem: Judu, kterýž sloul Barsabáš, a Sílu, muže znamenité mezi bratřími,'),
(1573727,54,44,15,23,'Napsavše po nich toto: Apoštolé a starší i všickni bratří těm, kteříž jsou v Antiochii a v Syrii a v Cilicii bratřím, kteříž jsou z pohanů, pozdravení vzkazují.'),
(1573728,54,44,15,24,'Poněvadž jsme slyšeli, že někteří vyšedše od nás, zkormoutili vás, řečmi svými zemdlévajíce duše vaše, pravíce, že se máte obřezovati a Zákon zachovávati, jimž jsme toho neporučili:'),
(1573729,54,44,15,25,'I vidělo se nám shromážděným jednomyslně, abychom vyvolili muže některé a poslali k vám s nejmilejšími našimi bratřími, Barnabášem a Pavlem,'),
(1573730,54,44,15,26,'Lidmi těmi, kteříž vydali duše své pro jméno Pána našeho Ježíše Krista.'),
(1573731,54,44,15,27,'Protož poslali jsme Judu a Sílu, a tiť i ústně povědí vám totéž.'),
(1573732,54,44,15,28,'Vidělo se zajisté Duchu svatému i nám, žádného více na vás břemene nevzkládati, kromě těchto věcí potřebných,'),
(1573733,54,44,15,29,'Totiž abyste se zdržovali od obětovaného modlám, a od krve, a od udáveného, a od smilstva. Od těch věcí budete-li se ostříhati, dobře budete činiti. Mějte se dobře.'),
(1573734,54,44,15,30,'Tedy oni propuštěni jsouce, přišli do Antiochie, a shromáždivše množství, dali jim list.'),
(1573735,54,44,15,31,'Kterýžto čtouce, radovali se z toho potěšení jich.'),
(1573736,54,44,15,32,'Judas pak a Sílas, byvše i oni proroci, širokou řečí napomínali bratří a potvrzovali jich.'),
(1573737,54,44,15,33,'A pobyvše tu za některý čas, propuštěni jsou od bratří v pokoji zase k apoštolům.'),
(1573738,54,44,15,34,'Ale Sílovi se vidělo, aby tu zůstal.'),
(1573739,54,44,15,35,'Tolikéž Pavel i Barnabáš pobyli v Antiochii, učíce a zvěstujíce slovo Páně, i s mnohými jinými.'),
(1573740,54,44,15,36,'Po několika pak dnech řekl Pavel k Barnabášovi: Vracujíce se, navštěvme bratří naše po všech městech, v kterýchž jsme kázali slovo Páně, a přezvíme, kterak se mají.'),
(1573741,54,44,15,37,'Tedy Barnabáš radil, aby pojali s sebou i Jana, kterýž příjmí měl Marek.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573742,54,44,15,38,'Ale Pavlovi se nezdálo pojíti toho s sebou, kterýž byl odšel od nich z Pamfylie, aniž šel s nimi ku práci.'),
(1573743,54,44,15,39,'I vznikl mezi nimi tuhý odpor, takže se rozešli různo. Barnabáš pak pojav s sebou Marka, plavil se do Cypru.'),
(1573744,54,44,15,40,'A Pavel připojiv k sobě Sílu, odšel, poručen jsa milosti Boží od bratří.'),
(1573745,54,44,15,41,'I chodil po Syrii a Cilicii, potvrzuje církví.'),
(1573746,54,44,16,1,'Přišel pak do Derben a do Lystry, aj, učedlník jeden tu byl, jménem Timoteus, syn jedné ženy Židovky věřící, ale otce měl Řeka.'),
(1573747,54,44,16,2,'Tomu svědectví dobré vydávali ti, jenž byli v Lystře a v Ikonii bratří.'),
(1573748,54,44,16,3,'Toho sobě oblíbil Pavel, aby s ním šel. I pojav ho, obřezal jej, pro Židy, kteříž byli v těch místech; nebo věděli všickni, že otec jeho byl Řek.'),
(1573749,54,44,16,4,'A když chodili po městech, vydávali jim k ostříhání ustanovení zřízená od apoštolů a od starších, kteříž byli v Jeruzalémě.'),
(1573750,54,44,16,5,'A tak církve utvrzovaly se u víře a rozmáhaly se v počtu na každý den.'),
(1573751,54,44,16,6,'A prošedše Frygii i Galatskou krajinu, když jim zabráněno od Ducha svatého, aby nemluvili slova Božího v Azii,'),
(1573752,54,44,16,7,'Přišedše do Myzie, pokoušeli se jíti do Bitynie. Ale nedal jim Duch Ježíšův.'),
(1573753,54,44,16,8,'Tedy pominuvše Myzii, šli do Troady.'),
(1573754,54,44,16,9,'I ukázalo se Pavlovi v noci vidění, jako by muž nějaký Macedonský stál, a prosil ho, řka: Přijda do Macedonie, pomoz nám.'),
(1573755,54,44,16,10,'A jakž to vidění viděl, ihned jsme usilovali o to, abychom šli do Macedonie, tím ujištěni jsouce, že jest nás povolal Pán, abychom jim kázali evangelium.'),
(1573756,54,44,16,11,'Protož pustivše se od Troady, přímým během připlavili jsme se do Samotracie a nazejtří do Neapolis,'),
(1573757,54,44,16,12,'A odtud do Filippis, kteréžto jest první město krajiny Macedonské, obyvateli cizími osazené. I zůstali jsme v tom městě za několik dní.'),
(1573758,54,44,16,13,'V den pak sobotní vyšli jsme ven za město k řece, kdež býval obyčej modliti se. A usadivše se, mluvili jsme ženám, kteréž se tu byly sešly.'),
(1573759,54,44,16,14,'Jedna pak žena, jménem Lydia, kteráž šarlaty prodávala v městě Tyatirských, bohabojící, poslouchala nás. Jejížto srdce otevřel Pán, aby to pilně rozsuzovala, co se od Pavla pravilo.'),
(1573760,54,44,16,15,'A když pokřtěna byla i dům její, prosila, řkuci: Poněvadž jste mne soudili věrnou Pánu býti, vejdětež do domu mého, a pobuďte u mne. I přinutila nás.'),
(1573761,54,44,16,16,'I stalo se, když jsme šli k modlitbě, že děvečka nějaká, mající ducha věštího, potkala se s námi, kteráž veliký užitek přinášela pánům svým budoucích věcí předpovídáním.'),
(1573762,54,44,16,17,'Ta šedši za Pavlem a za námi, volala, řkuci: Tito lidé jsou služebníci Boha nejvyššího, kteřížto zvěstují nám cestu spasení.'),
(1573763,54,44,16,18,'A to činívala za mnoho dní. Pavel pak těžce to nesa, a obrátiv se, řekl duchu tomu: Přikazuji tobě ve jménu Ježíše Krista, abys vyšel od ní. I vyšel hned té chvíle.'),
(1573764,54,44,16,19,'A viděvše páni její, že jest odešla naděje zisku jejich, chytivše Pavla a Sílu, vedli je na rynk před úřad.'),
(1573765,54,44,16,20,'A postavivše je před úředníky, řekli: Tito lidé bouří město naše, jsouce Židé,'),
(1573766,54,44,16,21,'A zvěstují obyčeje, kterýchž nám nesluší přijíti ani zachovávati, poněvadž jsme my Římané.'),
(1573767,54,44,16,22,'I povstala obec proti nim. A úředníci, roztrhše sukně jejich, kázali je metlami mrskati.'),
(1573768,54,44,16,23,'A množství ran jim davše, vsadili je do žaláře, přikázavše strážnému žaláře, aby jich pilně ostříhal.'),
(1573769,54,44,16,24,'Tedy on takové maje přikázání, vsadil je do nejhlubšího žaláře, a nohy jejich sevřel kladou.'),
(1573770,54,44,16,25,'O půlnoci pak Pavel a Sílas modléce se, zpívali písničky o Bohu, takže je slyšeli i jiní vězňové.'),
(1573771,54,44,16,26,'A vtom pojednou země třesení stalo se veliké, až se pohnuli gruntové žaláře, a hned se jim všecky dveře otevřely a všech okovové spadli.'),
(1573772,54,44,16,27,'I procítiv strážný žaláře a vida dveře žaláře otevřené, vytrhl meč, aby se zabil, domnívaje se, že vězňové utekli.'),
(1573773,54,44,16,28,'I zkřikl naň Pavel hlasem velikým, řka: Nečiň sobě nic zlého, však jsme teď všickni.'),
(1573774,54,44,16,29,'A požádav světla, vběhl k nim, a třesa se, padl k nohám Pavlovým a Sílovým.'),
(1573775,54,44,16,30,'I vyved je ven, řekl: Páni, co já mám činiti, abych spasen byl?'),
(1573776,54,44,16,31,'A oni řekli: Věř v Pána Ježíše a budeš spasen ty i dům tvůj.'),
(1573777,54,44,16,32,'I mluvili jemu slovo Páně, i všechněm, kteříž byli v domu jeho.'),
(1573778,54,44,16,33,'A on pojav je v tu hodinu v noci, umyl rány jejich. I pokřtěn jest hned on i všecka čeled jeho.'),
(1573779,54,44,16,34,'A když je uvedl do domu svého, připravil jim stůl, a veselil se, že jest se vším domem svým uvěřil Bohu.'),
(1573780,54,44,16,35,'A když bylo ve dne, poslali úředníci služebníky, řkouce: Vypusť ty lidi.'),
(1573781,54,44,16,36,'I oznámil strážný žaláře slova ta Pavlovi, pravě: Že poslali úředníci, abyste byli propuštěni. Protož nyní vyjdouce, jdětež v pokoji.'),
(1573782,54,44,16,37,'Ale Pavel řekl k nim: Zmrskavše nás zjevně a bez vyslyšení, lidi Římany, vsázeli do žaláře, a již nyní nás chtějí tajně vyhnati? Nikoli, ale nechať sami přijdou, a vyvedou nás.'),
(1573783,54,44,16,38,'Tedy pověděli úředníkům služebníci slova ta. I báli se, uslyšavše, že by Římané byli.'),
(1573784,54,44,16,39,'A přišedše, prosili jich; a vyvedše je, žádali jich, aby šli z města.'),
(1573785,54,44,16,40,'I vyšedše z žaláře, vešli k Lydii, a uzřevše bratří, potěšili jich, i šli odtud.'),
(1573786,54,44,17,1,'A prošedše město Amfipolim a Apollonii, přišli do Tessaloniky, kdež byla Židovská škola.'),
(1573787,54,44,17,2,'Tedy Pavel podle obyčeje svého všel k nim, a po tři soboty kázal jim z Písem,'),
(1573788,54,44,17,3,'Otvíraje a předkládaje to, že měl Kristus trpěti a z mrtvých vstáti, a že ten jest Kristus Ježíš, kteréhož já zvěstuji vám.'),
(1573789,54,44,17,4,'I uvěřili někteří z nich, a připojili se Pavlovi a Sílovi, i Řeků nábožných veliké množství, i žen znamenitých nemálo.'),
(1573790,54,44,17,5,'Ale zažženi jsouce závistí Židé pravdě nepovolní, a přivzavše k sobě některé lehkomyslné a zlé lidi, shlukše se, zbouřili město, a útok učinivše na dům Jázonův, hledali jich, aby je vyvedli před lid.'),
(1573791,54,44,17,6,'A nenalezše jich, táhli Jázona a některé bratří k starším města, křičíce: Tito, kteříž všecken svět bouří, ti sem také přišli,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573792,54,44,17,7,'Kteréž přijal Jázon. A ti všickni proti ustanovení císařskému činí, pravíce býti králem jiného, jménem Ježíše.'),
(1573793,54,44,17,8,'A tak zbouřili obec i starší města, kteříž od nich to slyšeli.'),
(1573794,54,44,17,9,'Ale oni přijavše dosti učinění od Jázona a jiných, propustili je.'),
(1573795,54,44,17,10,'Bratří pak hned v noci vypustili i Pavla i Sílu do Berie. Kteřížto přišedše tam, vešli do školy Židovské.'),
(1573796,54,44,17,11,'A ti byli udatnější nežli Tessalonitští, kteřížto přijali slovo Boží se vší chtivostí, na každý den rozvažujíce Písma, tak-li by ty věci byly, jakž kázal Pavel.'),
(1573797,54,44,17,12,'A tak mnozí z nich uvěřili, i Řecké ženy poctivé i mužů nemálo.'),
(1573798,54,44,17,13,'A když zvěděli Židé v Tessalonice, že by i v Berii kázáno bylo slovo Boží od Pavla, přišli také tam, bouříce zástupy.'),
(1573799,54,44,17,14,'Ale hned bratří vypustili Pavla, aby šel jako k moři; Sílas pak a Timoteus zůstali tu.'),
(1573800,54,44,17,15,'Ti pak, kteříž provodili Pavla, dovedli ho až do Atén. A vzavše poručení k Sílovi a k Timoteovi, aby přišli k němu, což nejspíše mohou, šli zase.'),
(1573801,54,44,17,16,'A když Pavel čekal jich v Aténách, rozněcoval se v něm duch jeho, vida to město oddané býti modloslužbě.'),
(1573802,54,44,17,17,'I rozmlouval s Židy a nábožnými lidmi v škole, ano i na rynku, po všecky dni, s těmi, kteříž se koli nahodili.'),
(1573803,54,44,17,18,'Tedy někteří z epikureů a stoických mudráků hádali se s ním. A někteří řekli: I co tento žváč chce povědíti? Jiní pak pravili: Zdá se býti nějakých cizích bohů zvěstovatel. Neb jim o Ježíšovi a o z mrtvých vstání vypravoval.'),
(1573804,54,44,17,19,'I popadše jej, vedli ho do Areopágu, a řekli jemu: Můžeme-li věděti, jaké jest to učení nové, kteréž vypravuješ?'),
(1573805,54,44,17,20,'Nebo nové jakési věci vkládáš v uši naše, protož chceme věděti, co by to bylo.'),
(1573806,54,44,17,21,'(Aténští zajisté všickni, i ti, kteříž tu byli hosté, k ničemuž jinému tak hotovi nebyli, než praviti neb slyšeti něco nového.)'),
(1573807,54,44,17,22,'Tedy Pavel, stoje uprostřed Areopágu, řekl: Muži Aténští, vidím vás býti všelijak příliš nábožné lidi.'),
(1573808,54,44,17,23,'Nebo procházeje se a spatřuje náboženství vaše, nalezl jsem také oltář, na kterémž napsáno jest: Neznámému Bohu. Protož kteréhož vy ctíte neznajíce, tohoť já zvěstuji vám.'),
(1573809,54,44,17,24,'Bůh ten, kterýž stvořil svět i všecko, což jest na něm, ten jsa Pánem nebe i země, nebydlí v chrámích rukou udělaných,'),
(1573810,54,44,17,25,'Aniž bývá ctěn lidskýma rukama, jako by něčeho potřeboval, poněvadž on dává všechněm život i dýchání i všecko.'),
(1573811,54,44,17,26,'A učinil z jedné krve všecko lidské pokolení, aby přebývalo na tváři vší země, vyměřiv jim uložené časy a cíle přebývání jejich,'),
(1573812,54,44,17,27,'Aby hledali Boha, zda by snad makajíce, mohli nalézti jej, ačkoli není daleko od jednoho každého z nás.'),
(1573813,54,44,17,28,'Nebo jím živi jsme, a hýbeme se, i trváme, jakož i někteří z vašich poetů pověděli: Že i rodina jeho jsme.'),
(1573814,54,44,17,29,'Rodina tedy Boží jsouce, nemámeť se domnívati, že by Bůh zlatu neb stříbru neb kamenu, řemeslem anebo důvtipem lidským vyrytému, byl podoben.'),
(1573815,54,44,17,30,'Nebo časy této neznámosti přehlídaje Bůh, již nyní zvěstuje lidem všechněm všudy, aby pokání činili,'),
(1573816,54,44,17,31,'Protože uložil den, v kterémžto souditi bude všecken svět v spravedlnosti skrze muže, kteréhož jest k tomu vystavil, slouže k víře o tom všechněm, vzkříšením jeho z mrtvých.'),
(1573817,54,44,17,32,'Uslyševše pak o vzkříšení z mrtvých, někteří se posmívali, a někteří řekli: Budeme tě slyšeti o tom po druhé.'),
(1573818,54,44,17,33,'A tak Pavel vyšel z prostředku jejich.'),
(1573819,54,44,17,34,'Někteří pak muži, přídržíce se ho, uvěřili, mezi kterýmiž byl i Dionyzius Areopagitský, i žena, jménem Damaris, a jiní s nimi.'),
(1573820,54,44,18,1,'Potom pak Pavel vyšed z Atén, přišel do Korintu.'),
(1573821,54,44,18,2,'A nalezl jednoho Žida, jménem Akvilu, jenž byl rodem z Pontu, kterýž nedávno byl přišel z Vlach, i s Priscillou manželku svou, (protože byl rozkázal Klaudius, aby všickni Židé z Říma vyšli), i přivinul se k nim.'),
(1573822,54,44,18,3,'A že byl téhož řemesla jako oni, bydlil u nich a dělal; a bylo řemeslo jejich stany dělati.'),
(1573823,54,44,18,4,'I hádal se v škole na každou sobotu a k získání přivodil i Židy i Řeky.'),
(1573824,54,44,18,5,'A když přišli z Macedonie Sílas a Timoteus, rozněcoval se v duchu Pavel, osvědčuje Židům, že Ježíš jest Kristus.'),
(1573825,54,44,18,6,'A když jemu oni odporovali a rouhali se, vyraziv prach z roucha svého, řekl k nim: Krev vaše budiž na hlavu vaši. Já čist jsa, hned půjdu ku pohanům.'),
(1573826,54,44,18,7,'A jda odtud, všel do domu člověka jednoho, jménem Justa, ctitele Božího, kteréhož dům byl u samé školy.'),
(1573827,54,44,18,8,'Krispus pak, kníže školy, uvěřil Pánu se vším domem svým, a mnozí z Korintských slyšíce, uvěřili a křtěni byli.'),
(1573828,54,44,18,9,'I řekl Pán v noci u vidění Pavlovi: Neboj se, ale mluv a nemlč.'),
(1573829,54,44,18,10,'Nebť já s tebou jsem, a žádnýť nesáhne na tebe, ať by zle učinil; nebo mnoho mám lidu v tomto městě.'),
(1573830,54,44,18,11,'I byl tu půl druhého léta, káže jim slovo Boží.'),
(1573831,54,44,18,12,'Když pak Gallio vladařem byl v Achaii, povstali jednomyslně Židé proti Pavlovi, a přivedli jej před soudnou stolici,'),
(1573832,54,44,18,13,'Pravíce: Tento navodí lidi, aby proti Zákonu ctili Boha.'),
(1573833,54,44,18,14,'A když Pavel měl již otevříti ústa, řekl Gallio k Židům: Ó Židé, jestliže by co nepravého stalo se, nebo nešlechetnost nějaká, slušně bych vás vyslyšel.'),
(1573834,54,44,18,15,'Pakliť jsou jaké hádky o slovích a o jméních a Zákonu vašem, vy sami k tomu přihlédněte. Jáť toho soudce býti nechci.'),
(1573835,54,44,18,16,'I odehnal je od soudné stolice.'),
(1573836,54,44,18,17,'Tedy Řekové všickni, uchopivše Sostena, kníže školy Židovské, bili jej tu před soudnou stolicí, a Gallio na to nic nedbal.'),
(1573837,54,44,18,18,'Pavel pak, pobyv tam ještě za mnoho dní, i rozžehnav se s bratřími, plavil se do Syrie, a s ním spolu Priscilla a Akvila, oholiv hlavu v Cenchreis; nebo byl učinil slib.'),
(1573838,54,44,18,19,'I přišel do Efezu a nechal jich tu; sám pak všed do školy, hádal se s Židy.'),
(1573839,54,44,18,20,'A když ho prosili, aby tu déle pobyl u nich, nepovolil.'),
(1573840,54,44,18,21,'Ale požehnav jich, řekl: Musím já jistotně svátek ten, kterýž nastává, v Jeruzalémě slaviti, ale navrátím se k vám zase, bude-li vůle Boží. I bral se z Efezu.'),
(1573841,54,44,18,22,'A přišed do Cesaree, vstoupil do Jeruzaléma, a pozdraviv církve, odtud šel do Antiochie.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573842,54,44,18,23,'A pobyv tu za některý čas, odšel a procházel pořád Galatskou krajinu a Frygii, potvrzuje všech učedlníků.'),
(1573843,54,44,18,24,'Žid pak nějaký, jménem Apollo, rodem z Alexandrie, muž výmluvný, přišel do Efezu, učený v Písmě.'),
(1573844,54,44,18,25,'Ten byl počátečně naučen cestě Páně, a jsa vroucího ducha, horlivě mluvil a učil pilně těm věcem, kteréž jsou Páně, znaje toliko křest Janův.'),
(1573845,54,44,18,26,'A ten počal směle a svobodně mluviti v škole. Kteréhož slyševše Priscilla a Akvila, přijali ho k sobě a dokonaleji vypravovali jemu o cestě Boží.'),
(1573846,54,44,18,27,'A když chtěl jíti do Achaie, bratří napomenuvše ho, psali učedlníkům, aby jej přijali. Kterýžto když tam přišel, mnoho prospěl těm, kteříž uvěřili skrze milost Boží.'),
(1573847,54,44,18,28,'Nebo náramně přemáhal Židy, zjevně přede všemi jim toho dokazuje z Písem, že Ježíš jest Kristus.'),
(1573848,54,44,19,1,'I stalo se, když Apollo byl v Korintu, že Pavel prošed vrchní krajiny, přišel do Efezu, a nalezna tu některé učedlníky,'),
(1573849,54,44,19,2,'Řekl k nim: Přijali-li jste Ducha svatého, uvěřivše? A oni řekli jemu: Ba, aniž jsme slýchali, jest-li Duch svatý.'),
(1573850,54,44,19,3,'On pak řekl jim: Načež tedy pokřtěni jste? A oni řekli: Křtěni jsme křtem Janovým.'),
(1573851,54,44,19,4,'I řekl Pavel: Janť zajisté křtil křtem pokání, pravě lidu, aby v toho, kterýž měl po něm přijíti, věřili, to jest v Krista Ježíše.'),
(1573852,54,44,19,5,'Kteříž pak toho uposlechli, pokřtěni jsou ve jméno Pána Ježíše.'),
(1573853,54,44,19,6,'A když vzkládal na tyto ruce Pavel, sstoupil Duch svatý na ně, i mluvili jazyky rozličnými, a prorokovali.'),
(1573854,54,44,19,7,'A bylo všech spolu okolo dvanácti mužů.'),
(1573855,54,44,19,8,'Tedy Pavel všed do školy, směle a svobodně mluvil za tři měsíce, hádaje se a uče o království Božím.'),
(1573856,54,44,19,9,'A když se někteří zatvrdili a nepovolovali, zle mluvíce o cestě Boží přede vším množstvím, odstoupiv od nich, oddělil učedlníky, na každý den kázání čině v škole nějakého Tyranna.'),
(1573857,54,44,19,10,'A to se dálo za dvě létě, takže všickni, kteříž přebývali v Azii, poslouchali slova Pána Ježíše, i Židé i Řekové.'),
(1573858,54,44,19,11,'A divy veliké činil Bůh skrze ruce Pavlovy,'),
(1573859,54,44,19,12,'Takže i šátky a fěrtochy od jeho těla na nemocné nosívali, a odstupovaly od nich nemoci, a duchové nečistí vycházeli z nich.'),
(1573860,54,44,19,13,'Tedy pokusili se někteří z Židů tuláků, kteříž se s zaklínáním obírali, vzývati jméno Pána Ježíše nad těmi, jenž měli duchy nečisté, říkajíce: Zaklínáme vás skrze Ježíše, kteréhož káže Pavel.'),
(1573861,54,44,19,14,'A bylo jich sedm synů jednoho Žida, jménem Scevy, předního kněze, kteříž to činili.'),
(1573862,54,44,19,15,'Tedy odpověděv duch zlý, řekl: Ježíše znám, a o Pavlovi vím, ale vy kdo jste?'),
(1573863,54,44,19,16,'A obořiv se na ně člověk ten, v kterémž byl duch zlý, a opanovav je, zmocnil se jich, takže nazí a zranění vyběhli z domu toho.'),
(1573864,54,44,19,17,'A to známo učiněno jest všechněm Židům i Řekům bydlícím v Efezu, a spadla bázeň na ně na všecky. I oslaveno jest jméno Pána Ježíše.'),
(1573865,54,44,19,18,'Mnozí pak z věřících přicházeli, vyznávajíce se a zjevujíce skutky své.'),
(1573866,54,44,19,19,'Mnozí také z těch, kteříž se s marnými uměními obírali, snesše knihy o těch věcech, spálili je přede všemi; a početše cenu jejich, shledali toho padesáte tisíců peněz.'),
(1573867,54,44,19,20,'Tak jest mocně rostlo slovo Páně a zmocňovalo se.'),
(1573868,54,44,19,21,'A když se to všecko dokonalo, uložil Pavel v duchu svém, aby projda Macedonii a Achaii, šel do Jeruzaléma, řka: Když pobudu tam, musímť také i na Řím pohleděti.'),
(1573869,54,44,19,22,'I poslav dva z těch, jenž mu přisluhovali, do Macedonie, Timotea a Erasta, sám pozůstal v Azii do času.'),
(1573870,54,44,19,23,'Tedy stala se v ten čas nemalá bouřka pro cestu Boží.'),
(1573871,54,44,19,24,'Nebo zlatník jeden, jménem Demetrius, kterýž dělával chrámy stříbrné modly Diány, nemalý zisk přivodil řemeslníkům.'),
(1573872,54,44,19,25,'Kteréž svolav, i ty, kteříž byli k těm podobných věcí dělníci, řekl jim: Muži, víte, že z tohoto řemesla jest živnost naše.'),
(1573873,54,44,19,26,'A vidíte i slyšíte, že netoliko v Efezu, ale téměř po vší Azii tento Pavel svedl a odvrátil veliké množství lidu, pravě: Že to nejsou bohové, kteříž jsou rukama udělaní.'),
(1573874,54,44,19,27,'A protož strach jest, netoliko aby se nám v živnosti naší přítrž nestala, ale také i veliké bohyně Diány chrám aby za nic nebyl jmín, a aby nepřišlo k zkáze důstojenství její, kteroužto všecka Azia i všecken světa okršlek ctí.'),
(1573875,54,44,19,28,'To uslyšavše a naplněni jsouce hněvem, zkřikli řkouce: Veliká jest Diána Efezských.'),
(1573876,54,44,19,29,'I naplněno jest všecko město rozbrojem, a valili se všickni spolu na plac, pochopivše Gáia a Aristarcha, Macedonské, tovaryše cesty Pavlovy.'),
(1573877,54,44,19,30,'Pavlovi pak, když chtěl jíti k lidu, nedopustili učedlníci.'),
(1573878,54,44,19,31,'Ano i někteří z předních mužů Azianských, kteříž jemu přáli, poslavše k němu, prosili ho, aby se nedával do toho hluku.'),
(1573879,54,44,19,32,'A jedni tak, jiní jinak křičeli; nebo byla obec zbouřena, a mnozí nevěděli, proč jsou se sběhli.'),
(1573880,54,44,19,33,'Z zástupu pak někteří Alexandra nějakého táhli k mluvení, kteréhož i Židé k tomu nutili. Alexander pak pokynuv rukou, chtěl zprávu dáti lidu.'),
(1573881,54,44,19,34,'Ale jakž poznali, že jest Žid, ihned se stal jednostejný všech hlas, jako za dvě hodině volajících: Veliká jest Diána Efezských.'),
(1573882,54,44,19,35,'A když písař pokojil zástup, řekl: Muži Efezští, i kdož z lidí jest, ješto by nevěděl, že město Efezské slouží veliké bohyni Diáně a od Jupitera spadlému obrazu?'),
(1573883,54,44,19,36,'A poněvadž tomu odpíráno býti nemůže, slušné jest, abyste se upokojili a nic kvapně nečinili.'),
(1573884,54,44,19,37,'Přivedli jste zajisté lidi tyto, kteříž nejsou ani svatokrádce ani ruhači bohyně vaší.'),
(1573885,54,44,19,38,'Jestliže pak Demetrius a ti, kteříž jsou s ním řemeslníci, mají s kým jakou při, však bývá obecný soud, a jsou k tomu konšelé. Nechať jedni druhé viní.'),
(1573886,54,44,19,39,'Pakli čeho jiného hledáte, i toť můž v pořádném svolání obce skoncováno býti.'),
(1573887,54,44,19,40,'Nebo strach jest, abychom nedošli nesnáze pro tu bouřku dnešní, poněvadž žádné příčiny není, kterouž bychom mohli předložiti, proč jsme se tuto sběhli. A to pověděv, rozpustil lid.'),
(1573888,54,44,20,1,'Když pak přestala ta bouřka, povolav Pavel učedlníků a požehnav jich, vyšel odtud, aby se bral do Macedonie.'),
(1573889,54,44,20,2,'A když prošel krajiny ty, a napomenutí jim učiniv mnohými řečmi, přišel do země Řecké,'),
(1573890,54,44,20,3,'V kteréžto pobyv za tři měsíce, (kdežto Židé učinili jemu zálohy,) když se měl plaviti do Syrie, umínil navrátiti se skrze Macedonii.'),
(1573891,54,44,20,4,'I šel s ním Sópater Berienský až do Azie, a z Tessalonicenských Aristarchus a Sekundus a Gáius Derbeus a Timoteus, z Azianských pak Tychikus a Trofimus.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573892,54,44,20,5,'Ti všickni šedše napřed, dočkali nás v Troadě.'),
(1573893,54,44,20,6,'My pak plavili jsme se po velikonoci z Filippis, a přišli jsme k nim do Troady v pěti dnech, a tu jsme pobyli za sedm dní.'),
(1573894,54,44,20,7,'Tedy první den po sobotě, když se učedlníci sešli k lámání chleba, Pavel mluvil k nim, maje nazejtří jíti pryč, i prodlil řečí až do půlnoci.'),
(1573895,54,44,20,8,'A bylo mnoho světel tu na té síni, kdež byli shromážděni.'),
(1573896,54,44,20,9,'Jeden pak mládenec, jménem Eutychus, sedě na okně, jsa obtížen hlubokým snem, když tak dlouho Pavel kázal, spě, spadl s třetího ponebí dolů, a vzat jest mrtvý.'),
(1573897,54,44,20,10,'I sstoupiv dolů Pavel, zpolehl na něj, a objav jej, řekl: Nermuťtež se, však duše jeho v něm jest.'),
(1573898,54,44,20,11,'A vstoupiv zase na síň, lámal chléb a jedl, a kázání jim učiniv dlouho až do svitání, tak odšel pryč.'),
(1573899,54,44,20,12,'I přivedli toho mládence živého, a byli nad tím velice potěšeni.'),
(1573900,54,44,20,13,'My pak vstoupivše na lodí, plavili jsme se do Asson, odtud majíce k sobě vzíti Pavla; neb jest byl tak poručil, maje sám jíti po zemi.'),
(1573901,54,44,20,14,'A když se k nám připojil v Asson, vzavše jej, přijeli jsme do Mitylénu.'),
(1573902,54,44,20,15,'A odtud plavíce se, druhý den byli jsme proti Chium, a třetího dne přistavili jsme bárku k Sámu, a pobyvše v Trogyllí, nazejtří přišli jsme do Milétu.'),
(1573903,54,44,20,16,'Nebo Pavel byl umínil pominouti Efez, aby se nemeškal v Azii; nebo pospíchal, by možné bylo, aby byl o letnicích v Jeruzalémě.'),
(1573904,54,44,20,17,'Tedy z Milétu poslav do Efezu, povolal k sobě starších církve.'),
(1573905,54,44,20,18,'Kteřížto když přišli k němu, řekl jim: Vy víte od prvního dne, v kterýžto přišel jsem do Azie, kterak jsem po všecken ten čas s vámi byl,'),
(1573906,54,44,20,19,'Slouže Pánu se vší pokorou i s mnohými slzami a pokušeními, kteráž na mne přicházela z úkladů Židovských.'),
(1573907,54,44,20,20,'Kterak jsem ničehož nepominul, což by vám užitečného bylo, abych vám toho neoznámil, ale učil jsem vás vůbec zjevně i po domích,'),
(1573908,54,44,20,21,'Svědectví vydávaje i Židům i Řekům o pokání k Bohu a o víře v Pána našeho Ježíše Krista.'),
(1573909,54,44,20,22,'A aj, nyní já sevřín jsa duchem, beru se do Jeruzaléma, nevěda, co mi se v něm má státi,'),
(1573910,54,44,20,23,'Než že Duch svatý po městech, kudyž jsem šel, osvědčuje mi, pravě, že vězení a soužení mne očekávají.'),
(1573911,54,44,20,24,'Však já nic na to nedbám, aniž jest mi tak drahá duše má, jen abych běh svůj s radostí vykonal a přisluhování, kteréž jsem přijal od Pána Ježíše, k osvědčování evangelium milosti Boží.'),
(1573912,54,44,20,25,'A aj, já nyní vím, že již více neuzříte tváři mé vy všickni, mezi kterýmiž jsem chodil, káže o království Božím.'),
(1573913,54,44,20,26,'Protož osvědčujiť vám dnešní den, žeť jsem čist od krve všech.'),
(1573914,54,44,20,27,'Nebť jsem neobmeškal zvěstovati vám všeliké rady Boží.'),
(1573915,54,44,20,28,'Buďtež tedy sebe pilni i všeho stáda, v němžto Duch svatý ustanovil vás biskupy, abyste pásli církev Boží, kteréž sobě dobyl svou vlastní krví.'),
(1573916,54,44,20,29,'Nebo já to jistotně vím, že po mém odjití vejdou mezi vás vlci hltaví, kteříž nebudou odpouštěti stádu.'),
(1573917,54,44,20,30,'A z vás samých povstanou muži, jenž budou mluviti převrácené věci, aby obrátili učedlníky po sobě.'),
(1573918,54,44,20,31,'Protož bděte, v paměti majíce, že jsem po tři léta nepřestával dnem i nocí s pláčem napomínati jednoho každého z vás.'),
(1573919,54,44,20,32,'A již nyní, bratří, poroučím vás Bohu a slovu milosti jeho, kterýžto mocen jest vzdělati vás, a dáti vám dědictví mezi všemi posvěcenými.'),
(1573920,54,44,20,33,'Stříbra nebo zlata neb roucha nežádal jsem od žádného.'),
(1573921,54,44,20,34,'Nýbrž sami víte, že toho, čehož mi kdy potřebí bylo, i těm, kteříž jsou se mnou, dobývaly ruce tyto.'),
(1573922,54,44,20,35,'Vše ukázal jsem vám, že tak pracujíce, musíme snášeti mdlé, a pamatovati na slova Pána Ježíše; nebť on řekl: Blahoslaveněji jest dáti nežli bráti.'),
(1573923,54,44,20,36,'A to pověděv, klekna na kolena svá, modlil se s nimi se všemi.'),
(1573924,54,44,20,37,'I stal se pláč veliký ode všech, a padajíce na hrdlo Pavlovo, líbali jej,'),
(1573925,54,44,20,38,'Rmoutíce se nejvíce nad tím slovem, kteréž řekl, že by již více neměli tváři jeho viděti. I provodili jej až k lodí.'),
(1573926,54,44,21,1,'Když jsme se pak plavili, rozloučivše se s nimi, přímým během přijeli jsme do Koum, a druhý den do Ródu, a odtud do Patary.'),
(1573927,54,44,21,2,'I nalezše tu lodí, kteráž měla plouti do Fenicen, a vstoupivše na ni, plavili jsme se.'),
(1573928,54,44,21,3,'A když se nám počal ukazovati Cyprus, nechavše ho na levé straně, plavili jsme se do Syrie, a připlavili jsme se do Týru; nebo tu měli složiti náklad z lodí.'),
(1573929,54,44,21,4,'A nalezše tu učedlníky, pobyli jsme tam za sedm dní, kteřížto pravili Pavlovi skrze Ducha svatého, aby nechodil do Jeruzaléma.'),
(1573930,54,44,21,5,'A když jsme my vyplnili ty dni, vyšedše, brali jsme se pryč, a sprovodili nás všickni s ženami i s dětmi až za město. A poklekše na kolena na břehu, pomodlili jsme se.'),
(1573931,54,44,21,6,'A když jsme se vespolek rozžehnali, vstoupili jsme na lodí, a oni se vrátili domů.'),
(1573932,54,44,21,7,'My pak přeplavivše se od Týru, dostali jsme se až do Ptolemaidy, a pozdravivše tu bratří, pobyli jsme u nich jeden den.'),
(1573933,54,44,21,8,'A nazejtří vyšedše Pavel a my, jenž jsme s ním byli, přišli jsme do Cesaree, a všedše do domu Filipa evangelisty, (kterýž byl jeden z oněch sedmi,) pobyli jsme u něho.'),
(1573934,54,44,21,9,'A ten měl čtyři dcery panny, prorokyně.'),
(1573935,54,44,21,10,'A když jsme tu pobyli za drahně dní, přišel prorok nějaký z Judstva, jménem Agabus.'),
(1573936,54,44,21,11,'Ten když k nám přišel, vzal pás Pavlův, a svázav sobě ruce i nohy, řekl: Totoť praví Duch svatý: Muže toho, jehož jest pás tento, tak sváží Židé v Jeruzalémě a vydadí v ruce pohanům.'),
(1573937,54,44,21,12,'A jakž jsme to uslyšeli, prosili jsme ho i my i ti, kteříž byli v tom místě, aby nechodil do Jeruzaléma.'),
(1573938,54,44,21,13,'Tedy odpověděl Pavel: I co činíte, plačíce a trápíce srdce mé? Však já netoliko svázán býti, ale i umříti hotov jsem v Jeruzalémě pro jméno Pána Ježíše.'),
(1573939,54,44,21,14,'A když nechtěl povoliti, dali jsme tomu pokoj, řkouce: Staň se vůle Páně.'),
(1573940,54,44,21,15,'Po těch pak dnech připravivše se, brali jsme se do Jeruzaléma.'),
(1573941,54,44,21,16,'A šli s námi i učedlníci někteří z Cesaree, vedouce s sebou nějakého Mnázona z Cypru, starého učedlníka, u něhož bychom hospodu měli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573942,54,44,21,17,'A když jsme přišli do Jeruzaléma, vděčně nás přijali bratří.'),
(1573943,54,44,21,18,'Druhého pak dne všel Pavel s námi k Jakubovi, a tu se byli všickni starší sešli.'),
(1573944,54,44,21,19,'Jichžto pozdraviv, vypravoval jim všecko, což Bůh skrze službu jeho činil mezi pohany.'),
(1573945,54,44,21,20,'A oni slyšavše to, velebili Pána, a řekli jemu: Vidíš, bratře, kterak jest mnoho tisíců Židů věřících, a ti všickni jsou horliví milovníci Zákona.'),
(1573946,54,44,21,21,'Ale o toběť mají zprávu, že bys ty vedl od Zákona Mojžíšova všecky ty Židy, kteříž jsou mezi pohany, pravě, že nemají obřezovati synů svých, ani zachovávati obyčejů Zákona.'),
(1573947,54,44,21,22,'Což tedy činiti? Musíť zajisté shromážděno býti všecko množství, neboť uslyší o tobě, že jsi přišel.'),
(1573948,54,44,21,23,'Učiniž tedy toto, cožť povíme: Mámeť tu čtyři muže, kteříž mají slib na sobě.'),
(1573949,54,44,21,24,'Ty přijma k sobě, posvěť se s nimi, i náklad učiň s nimi, aby oholili hlavy své. A takť zvědí všickni, že to, což slyšeli o tobě, nic není, ale že i sám ty chodíš, ostříhaje Zákona.'),
(1573950,54,44,21,25,'Z strany pak těch, kteříž z pohanů uvěřili, my jsme psali, usoudivše, aby tohoto ničeho nešetřili, toliko aby se varovali modlám obětovaného, a krve, a udáveného, a smilstva.'),
(1573951,54,44,21,26,'Tedy Pavel, přijav k sobě ty muže, na druhý den posvětiv se s nimi, všel do chrámu, a vypravoval o vyplnění dní toho posvěcení, až i obětována jest obět za jednoho každého z nich.'),
(1573952,54,44,21,27,'A když se vyplniti mělo dní sedm, Židé někteří z Azie, uzřevše jej v chrámě, zbouřili všecken lid a vztáhli naň ruce,'),
(1573953,54,44,21,28,'Křičíce: Muži Izraelští, pomozte! Totoť jest ten člověk, kterýž proti lidu i Zákonu i místu tomuto všecky všudy učí, a k tomu i pohany uvedl do chrámu, a poskvrnil svatého tohoto místa.'),
(1573954,54,44,21,29,'Nebo byli viděli prve Trofima Efezského s ním v městě, kteréhož domnívali se, že by Pavel do chrámu uvedl.'),
(1573955,54,44,21,30,'Takž se zbouřilo všecko město, a sběhli se lidé, a uchopivše Pavla, táhli jej ven z chrámu. A hned zavříny jsou dveře.'),
(1573956,54,44,21,31,'A když jej chtěli zamordovati, povědíno hejtmanu vojska, že se bouří všecken Jeruzalém.'),
(1573957,54,44,21,32,'Kterýžto hned pojav s sebou žoldnéře a setníky, přiběhl na ně. A oni uzřevše hejtmana a žoldnéře, přestali bíti Pavla.'),
(1573958,54,44,21,33,'Tedy přistoupiv hejtman, dosáhl ho, a rozkázal jej svázati dvěma řetězy, a ptal se, kdo jest a co učinil.'),
(1573959,54,44,21,34,'V zástupu pak jedni tak, jiní jinak křičeli. A nemoha nic jistého zvěděti pro hluk, rozkázal jej vésti do vojska.'),
(1573960,54,44,21,35,'A když přišel k stupňům, nahodilo se, že nesen byl od žoldnéřů pro násilé lidu.'),
(1573961,54,44,21,36,'Nebo šlo za ním množství lidu, křičíce: Zahlaď jej!'),
(1573962,54,44,21,37,'A když měl již uveden býti do vojska Pavel, řekl hejtmanu: Mohu-li co promluviti k tobě? Kterýž řekl: Umíš Řecky?'),
(1573963,54,44,21,38,'Nejsi-liž ty ten Egyptský, kterýž jsi před těmito dny byl bouřku učinil, a vyvedls na poušť čtyři tisíce lotrů?'),
(1573964,54,44,21,39,'I řekl Pavel: Jáť jsem člověk Žid Tarsenský, neposledního města Cilické země obyvatel; protož prosím tebe, dopusť mi promluviti k lidu.'),
(1573965,54,44,21,40,'A když mu on dopustil, Pavel stoje na stupních, pokynul rukou na lid. A když se veliké mlčení stalo, mluvil k nim Židovsky, řka:'),
(1573966,54,44,22,1,'Muži bratří a otcové, poslechněte této mé omluvy, kterouž vám nyní předložím.'),
(1573967,54,44,22,2,'(Uslyševše pak, že by k nim mluvil Židovským jazykem, tím raději mlčeli.) I řekl:'),
(1573968,54,44,22,3,'Já zajisté jsem muž Žid, narozený v Tarsu městě Cilickém, ale vychován jsem v tomto městě u noh Gamalielových, vyučený s pilností podle Zákona otcovského, horlivý milovník Boha, jakož i vy všickni podnes jste.'),
(1573969,54,44,22,4,'Kterýž jsem se této cestě protivil až k smrti, svazuje a dávaje do žaláře i muže i ženy,'),
(1573970,54,44,22,5,'Jakož i nejvyšší kněz svědek mi toho jest, i všickni starší. Od nichž i listy k bratřím vzav, šel jsem do Damašku, abych i ty, kteříž tam byli, svázané přivedl do Jeruzaléma, aby byli trápeni.'),
(1573971,54,44,22,6,'I stalo se, když jsem se bral cestou a přibližoval k Damašku, okolo poledne, že pojednou rychle s nebe obklíčilo mne světlo veliké.'),
(1573972,54,44,22,7,'I padl jsem na zem, a slyšel jsem hlas, an mi dí: Saule, Saule, proč mi se protivíš?'),
(1573973,54,44,22,8,'A já odpověděl jsem: Kdo jsi, Pane? I řekl ke mně: Jáť jsem Ježíš Nazaretský, kterémuž ty se protivíš.'),
(1573974,54,44,22,9,'Ti pak, kteříž se mnou byli, světlo zajisté viděli a přestrašeni jsou, ale hlasu toho, kterýž se mnou mluvil, neslyšeli.'),
(1573975,54,44,22,10,'I řekl jsem: Pane, což mám činiti? A Pán řekl ke mně: Vstana, jdiž do Damašku, a tuť tobě bude povědíno všecko, což jest uloženo, abys ty činil.'),
(1573976,54,44,22,11,'A že jsem byl oslnul pro jasnost světla toho, za ruce jsa veden od těch, kteříž se mnou byli, přišel jsem do Damašku.'),
(1573977,54,44,22,12,'Ananiáš pak nějaký, muž pobožný podle zákona, svědectví maje ode všech přebývajících v Damašku Židů,'),
(1573978,54,44,22,13,'Přišel ke mně, a stoje, řekl mi: Saule, bratře, prohlédni. A já hned v tu hodinu pohleděl jsem na něj.'),
(1573979,54,44,22,14,'I řekl mi: Bůh otců našich vyvolil tě, abys poznal vůli jeho, a uzřel Spravedlivého tohoto, a abys slyšel hlas z úst jeho.'),
(1573980,54,44,22,15,'Nebo svědkem jemu budeš u všech lidí těch věcí, kteréž jsi viděl a slyšel.'),
(1573981,54,44,22,16,'A protož nyní co prodléváš? Vstana, pokřti se, a obmej hříchy své, vzývaje jméno Páně.'),
(1573982,54,44,22,17,'Stalo se pak, když jsem se navrátil do Jeruzaléma a modlil jsem se v chrámě, že jsem byl u vytržení mysli.'),
(1573983,54,44,22,18,'I viděl jsem jej, an dí ke mně: Pospěš a vyjdi rychle z Jeruzaléma, neboť nepřijmou svědectví tvého o mně.'),
(1573984,54,44,22,19,'A já řekl jsem: Pane, oniť vědí, že jsem já do žaláře dával a bil jsem v školách ty, kteříž věřili v tebe.'),
(1573985,54,44,22,20,'A když vylévali krev Štěpána, svědka tvého, já také jsem tu stál, a přivolil jsem k usmrcení jeho, a ostříhal jsem roucha těch, kteříž jej mordovali.'),
(1573986,54,44,22,21,'A Pán řekl ke mně: Jdi, neboť já ku pohanům daleko pošli tebe.'),
(1573987,54,44,22,22,'I poslouchali ho až do toho slova. A tu hned pozdvihli hlasu svého, řkouce: Zahlaď z země takového, neboť nesluší jemu živu býti.'),
(1573988,54,44,22,23,'A když oni křičeli, a metali s sebe roucha, a prachem házeli v povětří,'),
(1573989,54,44,22,24,'Rozkázal jej hejtman uvésti do vojska, a kázal jej biči mrskati, aby zvěděl, pro kterou příčinu na něj tak křičí.'),
(1573990,54,44,22,25,'A když jej svázali řemením, řekl Pavel setníkovi, jenž tu stál: Sluší-liž vám člověka Římana a neodsouzeného mrskati?'),
(1573991,54,44,22,26,'To uslyšav setník, přistoupě k hejtmanu, pověděl jemu, řka: Viz, co chceš činiti; nebo člověk tento jest Říman.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1573992,54,44,22,27,'A přistoupiv hejtman, řekl mu: Pověz mi, jsi-li ty Říman? A on řekl: A já jsem.'),
(1573993,54,44,22,28,'I odpověděl hejtman: Já jsem za veliké peníze toho měšťanství dosáhl. Pavel pak řekl: Ale já jsem se i narodil Říman.'),
(1573994,54,44,22,29,'Tedy ihned odstoupili od něho ti, kteříž jej měli trápiti. Ano i hejtman bál se, když zvěděl, že jest Říman, a že jej byl kázal svázati.'),
(1573995,54,44,22,30,'Nazejtří pak, chtěje zvěděti jistotu, z čeho by jej vinili Židé, propustil jej z pout, a rozkázal, aby se sešli přední kněží i všecka rada jejich. I vyvedl Pavla, a postavil ho před nimi.'),
(1573996,54,44,23,1,'Tedy Pavel, pohleděv pilně na to shromáždění, řekl: Muži bratří, já všelijak s dobrým svědomím sloužil jsem Bohu až do dnešního dne.'),
(1573997,54,44,23,2,'Tedy nejvyšší kněz Ananiáš kázal těm, kteříž tu stáli, aby jej bili v ústa.'),
(1573998,54,44,23,3,'Pavel pak řekl jemu: Budeť tebe bíti Bůh, stěno zbílená. A ty sedíš, soudě mne vedle Zákona, a proti Zákonu velíš mne bíti.'),
(1573999,54,44,23,4,'A někteří stojíce tu řekli: Nejvyššímu knězi Božímu zlořečíš?'),
(1574000,54,44,23,5,'I řekl Pavel: Nevědělť jsem, bratří, byť nejvyšším knězem byl; psánoť jest zajisté: Knížeti lidu svého nebudeš zlořečiti.'),
(1574001,54,44,23,6,'A věda Pavel, že tu byla jedna strana saduceů a druhá farizeů, zvolal v radě: Muži bratří, já jsem farizeus, syn farizeův; pro naději a z mrtvých vstání já tuto k soudu stojím.'),
(1574002,54,44,23,7,'A když on to promluvil, stal se rozbroj mezi farizei a saducei, a rozdvojilo se množství.'),
(1574003,54,44,23,8,'Nebo saduceové tak praví, že není vzkříšení, ani anděla, ani ducha, ale farizeové obé to vyznávají.'),
(1574004,54,44,23,9,'I stal se křik veliký. A povstavše učitelé strany farizejské, zastávali ho, řkouce: Nic jsme zlého nenalezli na tomto člověku; protož buď že mluvil jemu duch neb anděl, nebojujme s Bohem.'),
(1574005,54,44,23,10,'A když veliký rozbroj vznikl, obávaje se hejtman, aby Pavel nebyl od nich roztrhán, rozkázal žoldnéřům sjíti dolů a vychvátiti ho z prostředku jejich a vésti do vojska.'),
(1574006,54,44,23,11,'V druhou pak noc ukázav se jemu Pán, řekl: Budiž stálý, Pavle; nebo jakož jsi svědčil o mně v Jeruzalémě, tak musíš svědčiti i v Římě.'),
(1574007,54,44,23,12,'A když byl den, sšedše se někteří z Židů, zapřisáhli se s klatbou, řkouce, že nebudou jísti ani píti, až zabijí Pavla.'),
(1574008,54,44,23,13,'A bylo jich více než čtyřidceti, kteříž se byli tak spikli.'),
(1574009,54,44,23,14,'Kteřížto přistoupivše k předním kněžím a k starším, řekli: Prokletím prokleli jsme se, že neokusíme ničehož, dokudž nezabijeme Pavla.'),
(1574010,54,44,23,15,'Protož vy nyní dejte věděti hejtmanu, z jednostejného vší rady svolení, aby jej zítra k vám přivedl, jako byste něco jistšího chtěli zvěděti o jeho věcech; my pak, prve nežliť se k vám přiblíží, hotovi jsme jej zabíti.'),
(1574011,54,44,23,16,'Slyšev pak o těch úkladech, syn sestry Pavlovy odšel, a všel do vojska a pověděl Pavlovi.'),
(1574012,54,44,23,17,'Tedy zavolav Pavel k sobě jednoho z setníků, řekl: Doveď mládence tohoto k hejtmanu; neboť má jemu něco povědíti.'),
(1574013,54,44,23,18,'A on pojav jej, vedl k hejtmanu a řekl jemu: Vězeň Pavel zavolav mne, prosil, abych tohoto mládence přivedl k tobě, že by měl něco mluvit s tebou.'),
(1574014,54,44,23,19,'I vzav jej hejtman za ruku jeho, a odstoupiv s ním soukromí, otázal se ho: Co jest to, ješto mi máš oznámiti?'),
(1574015,54,44,23,20,'Tedy on řekl: Že jsou Židé uložili prositi tebe, abys k nim zítra do rady uvedl Pavla, jako by něco jistšího chtěli vyzvěděti o něm.'),
(1574016,54,44,23,21,'Ale ty nepovoluj jim; neboť úklady činí jemu více než čtyřidceti mužů z nich, kteříž se zapřisáhli s klatbou, že nebudou ani jísti, ani píti, až jej zabijí. A jižť jsou hotovi, čekajíce na odpověd od tebe.'),
(1574017,54,44,23,22,'Tedy hejtman propustil toho mládence, přikázav: Abys žádnému nepravil, žes mi to oznámil.'),
(1574018,54,44,23,23,'A zavolav dvou setníků, řekl jim: Připravte žoldnéřů dvě stě, aby šli až do Cesaree, a jezdců sedmdesáte, a drabantů dvě stě k třetí hodině na noc.'),
(1574019,54,44,23,24,'I hovada přiveďte, aby vsadíce na ně Pavla, ve zdraví jej dovedli k Felixovi vladaři;'),
(1574020,54,44,23,25,'Napsav jemu také i list v tento rozum:'),
(1574021,54,44,23,26,'Klaudius Lyziáš výbornému vladaři Felixovi vzkazuje pozdravení.'),
(1574022,54,44,23,27,'Muže tohoto javše Židé, hned zamordovati měli. Kteréhožto já, přispěv s houfem žoldnéřů, vydřel jsem, zvěděv, že jest Říman.'),
(1574023,54,44,23,28,'A chtěje zvěděti, z čeho by jej vinili, uvedl jsem ho do rady jejich.'),
(1574024,54,44,23,29,'I shledal jsem, že na něj žalují o nějaké otázky Zákona jejich a že nemá žádné viny, pro kterouž by byl hoden smrti neb vězení.'),
(1574025,54,44,23,30,'A když mi povědíno o úkladech, kteréž jsou o něm skládali Židé, ihned jsem jej poslal k tobě, přikázav také i žalobníkům jeho, aby, což mají proti němu, oznámili před tebou. Měj se dobře.'),
(1574026,54,44,23,31,'Tedy žoldnéři, jakž jim poručeno bylo, pojavše Pavla, přivedli jej v noci do Antipatridy.'),
(1574027,54,44,23,32,'A nazejtří, nechavše jízdných, aby s ním jeli, vrátili se do vojska.'),
(1574028,54,44,23,33,'Oni pak přijevše do Cesaree, dali list vladaři, a Pavla také postavili před ním.'),
(1574029,54,44,23,34,'A přečta list vladař, i otázal se ho, z které by krajiny byl. A zvěděv, že jest z Cilicie,'),
(1574030,54,44,23,35,'Řekl: Budu tě slyšeti, když tvoji žalobníci také přijdou. I rozkázal ho ostříhati v domě Herodesově.'),
(1574031,54,44,24,1,'Po pěti pak dnech sstoupil nejvyšší kněz Ananiáš s staršími a s nějakým Tertullem řečníkem; kteřížto postavili se před vladařem proti Pavlovi.'),
(1574032,54,44,24,2,'A když povolán byl, počal naň žalovati Tertullus, řka:'),
(1574033,54,44,24,3,'Kterak mnohý pokoj způsoben jest nám skrze tebe a mnohé věci v tomto národu výborně se dějí skrze tvou opatrnost, to my i všelijak i všudy se vším děkováním vyznáváme, výborný Felix.'),
(1574034,54,44,24,4,'Ale abych tě déle nezaměstnával, prosím, vyslyšiž nás maličko podle obyčeje přívětivosti své.'),
(1574035,54,44,24,5,'Nalezli jsme zajisté člověka tohoto nešlechetného, a vzbuzujícího různice mezi všemi Židy po všem světě, a vůdci té sekty nazaretské;'),
(1574036,54,44,24,6,'Jenž také i o to se pokoušel, aby chrámu poskvrnil; a kteréhožto javše, vedle Zákona našeho chtěli jsme souditi.'),
(1574037,54,44,24,7,'Ale přišed k tomu hejtman Lyziáš s mocí velikou, vzal ho z rukou našich,'),
(1574038,54,44,24,8,'Rozkázav, aby žalobníci jeho šli k tobě. Od něhožto ty sám budeš moci, vyptaje se, zvěděti o všem o tom, z čeho my jej viníme.'),
(1574039,54,44,24,9,'A k tomu se přimluvili i Židé, pravíce, že to tak jest.'),
(1574040,54,44,24,10,'Tedy Pavel odpověděl, když mu návěští dal vladař, aby mluvil: Od mnohých let věda tebe býti soudcím národu tomuto představeným, s lepší myslí k tomu, což se mne dotýče, odpovídati budu,'),
(1574041,54,44,24,11,'Poněvadž ty můžeš to věděti, že není tomu dní více než dvanácte, jakž jsem přišel do Jeruzaléma, abych se modlil.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574042,54,44,24,12,'A aniž jsou mne nalezli v chrámě s někým se hádajícího, aneb činícího roty v zástupu, ani v školách, ani v městě,'),
(1574043,54,44,24,13,'Aniž toho prokázati mohou, což na mne žalují.'),
(1574044,54,44,24,14,'Ale totoť já před tebou vyznávám, že podle té cesty, kterouž oni nazývají kacířstvím, tak sloužím Bohu otců svých, věře všemu, cožkoli psáno jest v Zákoně a v Prorocích,'),
(1574045,54,44,24,15,'Maje naději v Bohu, že bude, jehož i oni čekají, vzkříšení z mrtvých, i spravedlivých i nespravedlivých.'),
(1574046,54,44,24,16,'A tak se chovati hledím, abych měl dobré svědomí bez úrazu před Bohem i před lidmi vždycky'),
(1574047,54,44,24,17,'Po mnohých pak letech přišel jsem, almužny nesa národu svému a oběti.'),
(1574048,54,44,24,18,'Při čemž mne nalezli v chrámě očištěného, ne s zástupem, ani s bouřkou, někteří Židé z Azie,'),
(1574049,54,44,24,19,'Kteříž by měli tuto také před tebou státi a žalovati, měli-li by co proti mně.'),
(1574050,54,44,24,20,'Anebo nechať tito sami povědí, nalezli-li jsou na mně jakou nepravost, když jsem stál v radě,'),
(1574051,54,44,24,21,'Leč to jedno promluvení, že jsem zavolal, stoje mezi nimi: Pro vzkříšení z mrtvých já k soudu potažen jsem dnes od vás.'),
(1574052,54,44,24,22,'A vyslyšav to Felix, odložil jim, až by o té cestě něco místnějšího vyzvěděl, řka: Až hejtman Lyziáš sem přijede, posoudím té pře vaší.'),
(1574053,54,44,24,23,'I poručil setníkovi, aby Pavla ostříhal a polehčil mu vězení a nebránil žádnému z přátel jeho posluhovati jemu anebo navštěvovati ho.'),
(1574054,54,44,24,24,'Po několika pak dnech přišed Felix s Druzillou, manželkou svou, kteráž byla Židovka, zavolal Pavla, a slyšel od něho o víře v Krista.'),
(1574055,54,44,24,25,'A když on vypravoval o spravedlnosti a o zdrželivosti a o budoucím soudu, ulekl se Felix, a odpověděl: Nyní odejdi, a v čas příhodný zavolám tě.'),
(1574056,54,44,24,26,'Nadál se pak, že jemu Pavel dá nějaké peníze, aby jej propustil, pročež i tím častěji, povolávaje ho, mluvíval s ním.'),
(1574057,54,44,24,27,'Po dvou pak letech měl po sobě náměstka Felix, Festa Porcia, a chtěje se zalíbiti Židům Felix, nechal Pavla v vězení.'),
(1574058,54,44,25,1,'Tedy Festus vladařství ujav, po třech dnech přijel z Cesaree do Jeruzaléma.'),
(1574059,54,44,25,2,'I oznámili jemu nejvyšší kněz a přednější z Židů o Pavlovi, a prosili ho,'),
(1574060,54,44,25,3,'Žádajíce té milosti proti němu, aby jej kázal přivésti do Jeruzaléma, zálohy učinivše jemu, aby zabit byl na cestě.'),
(1574061,54,44,25,4,'A Festus odpověděl, že má Pavel ostříhán býti v Cesaree, a on sám že tudíž tam přijede.'),
(1574062,54,44,25,5,'Protož (řekl), kteříž z vás mohou, nechť tam také se vypraví spolu se mnou, a jest-li jaká vina na tom muži, nechať naň žalují.'),
(1574063,54,44,25,6,'A pobyv mezi nimi nic více než deset dní, jel do Cesaree. A druhého dne posadiv se na soudné stolici, kázal Pavla přivésti.'),
(1574064,54,44,25,7,'Kterýžto když byl přiveden, obstoupili jej ti, jenž byli přišli z Jeruzaléma, Židé, mnohé a těžké žaloby proti Pavlovi vedouce, kterýchž nemohli dovésti,'),
(1574065,54,44,25,8,'Nebo Pavel při všem mírnou zprávu dával, že ani proti Zákonu Židovskému, ani proti chrámu, ani proti císaři nic neprovinil.'),
(1574066,54,44,25,9,'Ale Festus, chtěje se Židům zalíbiti, odpověděv, řekl Pavlovi: Chceš-li jíti do Jeruzaléma a tam o to souzen býti přede mnou?'),
(1574067,54,44,25,10,'I řekl Pavel: Před stolicí císařovou chci státi a tam souzen býti. Židům jsem nic neublížil, jakož i ty dobře to víš.'),
(1574068,54,44,25,11,'Nebo jestližeť jim v čem ubližuji, aneb něco smrti hodného jsem spáchal, neodpírámť umříti; a pakliť nic toho při mně není, z čehož mne oni viní, žádnýť mne jim nemůže dáti. K císaři se odvolávám.'),
(1574069,54,44,25,12,'Tedy Festus promluviv s radou, odpověděl: K císařis se odvolal? K císaři půjdeš.'),
(1574070,54,44,25,13,'A po několika dnech král Agrippa a Bernice přijeli do Cesaree, aby pozdravili Festa.'),
(1574071,54,44,25,14,'A když tu za mnoho dní pobyli, oznámil Festus králi o Pavlově při, řka: Muž jeden ostaven jest od Felixa v vězení,'),
(1574072,54,44,25,15,'O kterémž, když jsem byl v Jeruzalémě, oznámili mi přední kněží a starší Židovští, žádajíce na něj ortele.'),
(1574073,54,44,25,16,'Kterýmž jsem odpověděl, že není obyčej Římanům vydati člověka na smrt, prve nežli by ten, na kohož se žaloba děje, přítomné měl žalobníky a volnost k odpovídání na to, z čehož by byl obviňován.'),
(1574074,54,44,25,17,'A protož když se byli sem sešli, hned beze všeho meškání, druhý den posadiv se na soudné stolici, rozkázal jsem přivésti toho muže.'),
(1574075,54,44,25,18,'Jehožto žalobníci tu stojíce, z ničeho takového nevinili ho, čehož jsem já se domníval.'),
(1574076,54,44,25,19,'Ale o nějaké otázky při tom svém náboženství měli s ním nesnáz, a o jakémsi Ježíšovi mrtvém, o kterémž jistil Pavel, že jest živ.'),
(1574077,54,44,25,20,'Já pak maje tu při v pochybnosti, řekl jsem jemu, chtěl-li by jíti do Jeruzaléma, a tam o ty věci souzen býti.'),
(1574078,54,44,25,21,'A když se on odvolal, aby byl chován k soudu Augustovu, kázal jsem ho hlídati, až bych jej poslal k císaři.'),
(1574079,54,44,25,22,'Tedy Agrippa řekl k Festovi: Chtělť bych i já rád člověka toho slyšeti. A on řekl: Zítra ho uslyšíš.'),
(1574080,54,44,25,23,'Nazejtří pak, když přišel Agrippa a Bernice s velikou slavou, a vešli na síň s hejtmany a s lidmi nejznamenitějšími města toho, k rozkázání Festovu přiveden jest Pavel.'),
(1574081,54,44,25,24,'I řekl Festus: Králi Agrippo a všickni, kteříž jste tuto s námi, vidíte tohoto, za nějžto všecko množství Židů prosili mne, i v Jeruzalémě i zde, křičíce, že takový nemá více živ býti.'),
(1574082,54,44,25,25,'Já pak shledav to, že nic hodného smrti neučinil, však když se sám k Augustovi odvolal, umínil jsem jej tam poslati.'),
(1574083,54,44,25,26,'O němž, co bych jistého napsal pánu svému, nevím. Protož jsem jej teď přivedl před vás, a zvláště před tebe, králi Agrippo, abych vyptaje se, věděl, co psáti.'),
(1574084,54,44,25,27,'Nebo zdá mi se to neslušné býti poslati vězně a pře jeho neoznámiti.'),
(1574085,54,44,26,1,'Potom Agrippa řekl Pavlovi: Dopouštíť se, abys sám za sebe promluvil. Tedy Pavel vztáh ruku, mluvil:'),
(1574086,54,44,26,2,'Na všecky ty věci, z kterýchž mne viní Židé, králi Agrippo, za šťastného se počítám, že dnes před tebou odpovídati mám,'),
(1574087,54,44,26,3,'A zvláště proto, poněvadž jsi ty povědom všech těch, kteříž u Židů jsou, obyčejů a otázek. Protož prosím tebe, vyslyšiž mne trpělivě.'),
(1574088,54,44,26,4,'O životu mém hned od mladosti mé, jaký byl od počátku v národu mém v Jeruzalémě, vědí všickni Židé,'),
(1574089,54,44,26,5,'Měvše mne prve zdávna v dobré známosti, (kdyby chtěli svědectví vydati,) kterak vedle nejjistší sekty v našem náboženství byl jsem živ farizeus.'),
(1574090,54,44,26,6,'A nyní pro naději toho zaslíbení, kteréž se stalo otcům našim od Boha, teď stojím, soudu jsa poddán,'),
(1574091,54,44,26,7,'K kterémužto zaslíbení dvanáctero pokolení naše, sloužíce Bohu ustavičně dnem i nocí, naději má, že přijde; pro kteroužto naději žalují na mne Židé, ó králi Agrippo.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574092,54,44,26,8,'A tak-liž se to od vás za nepodobné k víře soudí, že Bůh křísí mrtvé?'),
(1574093,54,44,26,9,'Ačť i mně se zdálo, že by mi náležité bylo, proti jménu Ježíše Nazaretského mnoho odporného činiti,'),
(1574094,54,44,26,10,'Jakož jsem i činil v Jeruzalémě, a mnohé z svatých já jsem do žalářů dával, vzav moc od předních kněží. A když měli mordováni býti, já jsem pomáhal ortele vynášeti.'),
(1574095,54,44,26,11,'A po všech školách často trápě je, přinucoval jsem, aby se rouhali; a náramně rozlítiv se na ně, protivil jsem se jim, až i do jiných měst na to jsem jezdil.'),
(1574096,54,44,26,12,'A v tom, když jsem šel do Damašku, s mocí a s poručením předních kněží,'),
(1574097,54,44,26,13,'O poledni na cestě, ó králi, uzřel jsem, ano světlo s nebe, jasnější nad blesk slunečný, obklíčilo mne, i ty, kteříž se mnou šli.'),
(1574098,54,44,26,14,'A když jsme my všickni na zem padli, slyšel jsem hlas mluvící ke mně a řkoucí Židovským jazykem: Saule, Saule, proč mi se protivíš? Tvrdoť jest tobě proti ostnům se zpěčovati.'),
(1574099,54,44,26,15,'A já řekl: I kdo jsi, Pane? A on řekl: Já jsem Ježíš, kterémuž ty se protivíš.'),
(1574100,54,44,26,16,'Ale vstaň a stůj na nohách svých; nebo protoť jsem se tobě ukázal, ať bych tebe učinil služebníkem a svědkem i těch věcí, kteréž jsi viděl, i těch, v kterýchžto ukazovati se budu tobě,'),
(1574101,54,44,26,17,'Vysvobozuje tebe z lidu tohoto, i z pohanů, k nimž tě nyní posílám,'),
(1574102,54,44,26,18,'Otvírati oči jejich, aby se obrátili od temností k světlu a z moci ďábelské k Bohu, aby tak hříchů odpuštění a díl s posvěcenými vzali skrze víru, kteráž jest ve mne.'),
(1574103,54,44,26,19,'A protož, ó králi Agrippo, nebyl jsem nevěřící nebeskému vidění.'),
(1574104,54,44,26,20,'Ale hned nejprv těm, kteříž jsou v Damašku a v Jeruzalémě, i po vší krajině Judské, potom i pohanům zvěstoval jsem evangelium, aby pokání činili a obrátili se k Bohu, skutky hodné pokání činíce.'),
(1574105,54,44,26,21,'A pro tu příčinu Židé javše mne v chrámě, pokoušeli se rukama svýma zamordovati.'),
(1574106,54,44,26,22,'Ale s pomocí Boží ještě až do dnešního dne stojím, vydávaje svědectví i malému i velikému, nic jiného nevypravuje, než to, což jsou Proroci a Mojžíš zvěstovali, že se mělo státi:'),
(1574107,54,44,26,23,'Totiž, že měl Kristus trpěti, a z mrtvých vstana první, zvěstovati světlo lidu tomuto i pohanům.'),
(1574108,54,44,26,24,'To když od sebe promluvil Pavel, Festus hlasem velikým řekl: Blázníš, Pavle. Mnohé tvé umění k bláznovství tebe přivodí.'),
(1574109,54,44,26,25,'On pak řekl: Nebláznímť, výborný Feste, ale slova pravdy a středmosti mluvím.'),
(1574110,54,44,26,26,'Víť zajisté o těch věcech král, před kterýmž směle a svobodně mluvím; nebo mám za to, žeť ho nic z těchto věcí tajno není, poněvadž se toto nedálo pokoutně.'),
(1574111,54,44,26,27,'Věříš-li, králi Agrippo, Prorokům? Vím, že věříš.'),
(1574112,54,44,26,28,'Tedy Agrippa řekl Pavlovi: Téměř bys mne k tomu naklonil, abych byl křesťanem.'),
(1574113,54,44,26,29,'A Pavel řekl: Žádalť bych od Boha, abyste i poněkud i z cela, netoliko ty, ale všickni, kteříž slyší mne dnes, byli takoví, jakýž já jsem, kromě okovů těchto.'),
(1574114,54,44,26,30,'A když to Pavel promluvil, vstal král, i vladař a Bernice, i ti, kteříž s nimi seděli.'),
(1574115,54,44,26,31,'A odšedše na stranu, mluvili spolu, řkouce: Nic hodného smrti neb vězení nečiní člověk tento.'),
(1574116,54,44,26,32,'Agrippa pak Festovi řekl: Mohl propuštěn býti člověk tento, kdyby se byl neodvolal k císaři.'),
(1574117,54,44,27,1,'A když bylo již usouzeno, abychom my se plavili do Vlach, poručen jest i Pavel i někteří jiní vězňové setníku, jménem Juliovi, kterýž byl nad houfem Augustovým.'),
(1574118,54,44,27,2,'Tedy všedše na lodí Adramyttenskou, abychom se plavili podle krajin Azie, pustili jsme se na moře. A byl s námi Aristarchus Macedonský z Tessaloniky.'),
(1574119,54,44,27,3,'Druhý pak den připlavili jsme se k Sidonu. A tu Julius přívětivě se maje ku Pavlovi, dopustil mu, aby jda k přátelům, u nich měl pohodlí.'),
(1574120,54,44,27,4,'A berouce se odtud, plavili jsme se podle Cypru, protože byl vítr odporný nám.'),
(1574121,54,44,27,5,'A tak přeplavivše se přes moře Cilické a Pamfylické, přišli jsme do města Myry, kteréž jest v krajině, jenž slove Lycia.'),
(1574122,54,44,27,6,'A tu našed setník bárku Alexandrinskou, kteráž měla plouti do Vlach, uvedl nás na ni.'),
(1574123,54,44,27,7,'A když jsme za mnoho dní znenáhla se plavili a sotva připlouli proti Gnidum, a vítr nám bránil přiblížiti se k zemi, i podjeli jsme Krétu podle Salmóny.'),
(1574124,54,44,27,8,'A sotva ji pomíjeti mohše, přijeli jsme na jedno místo, kteréž slove Pěkný břeh, od kteréhožto nedaleko bylo město Lasea.'),
(1574125,54,44,27,9,'Když pak drahný čas přešel, a již bylo nebezpečné plavení, (neb již byl i půst pominul,) napomínal jich Pavel,'),
(1574126,54,44,27,10,'Řka k nim: Muži, vidím, že s velikým ublížením a s mnohou škodou netoliko nákladu a lodí, ale i životů našich toto plavení bude.'),
(1574127,54,44,27,11,'Ale setník více věřil správci lodí a marináři, nežli tomu, co Pavel pravil.'),
(1574128,54,44,27,12,'A když nebylo tu příhodného přístavu, kdež by pobyli přes zimu, mnozí tak radili, aby se předce pustili odtud, zda by jak mohli, přijedouce do Fenicen, přes zimu tu pobýti na břehu Kréty, kterýž leží k větru nešpornímu a k větru více než západnímu.'),
(1574129,54,44,27,13,'A když počal vítr víti od poledne, majíce za to, že se budou umíněnou cestou držeti, i nahodilo se jim, že jeli blízko Kréty.'),
(1574130,54,44,27,14,'Po neveliké pak chvíli zdvihl se proti nim vítr bouřlivý půlnoční, kterýž slove Euroklydon.'),
(1574131,54,44,27,15,'A když lodí zachvácena byla a nemohla odolati proti větru, pustivše ji po větru, tak jsme se vezli.'),
(1574132,54,44,27,16,'A přiběhše pod jeden ostrov neveliký, kterýž slove Klauda, sotva jsme mohli obdržeti člun u bárky.'),
(1574133,54,44,27,17,'Kterýžto zdvihše, pomoci užívali, podpásavše bárku; a bojíce se, aby neuhodili na místo nebezpečné, spustivše člun, tak se plavili.'),
(1574134,54,44,27,18,'A když bouře vichrová námi velmi zmítala, na druhý den, což bylo v lodí nákladů, metali ven.'),
(1574135,54,44,27,19,'A třetí den i to nádobí bárce potřebné svýma rukama vyházeli jsme.'),
(1574136,54,44,27,20,'A když ani slunce se neukázalo ani hvězdy za mnoho dní, a bouře vždy větší nastávala, již byla všecka naděje o vysvobození našem odjata.'),
(1574137,54,44,27,21,'A když jsme již byli hladem velmi ztrápeni, tedy stoje Pavel uprostřed nich, řekl: Měli jste zajisté, ó muži, uposlechnouce mne, nehýbati se od Kréty, a tak uvarovati se nebezpečenství tohoto a škody'),
(1574138,54,44,27,22,'A i nyní vás napomínám, abyste dobré mysli byli; neboť nezahyne žádný z vás, kromě bárky samé.'),
(1574139,54,44,27,23,'Nebo této noci ukázal mi se anděl Boha toho, jehož já jsem a kterémuž sloužím,'),
(1574140,54,44,27,24,'Řka: Neboj se, Pavle, před císařem máš státi, a aj, dalť jest tobě Bůh všecky, kteříž se plaví s tebou.'),
(1574141,54,44,27,25,'Protož buďte dobré mysli, muži; neboť já věřím Bohu, žeť se tak stane, jakž jest mi mluveno.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574142,54,44,27,26,'Mámeť se pak dostati na nějaký ostrov.'),
(1574143,54,44,27,27,'A když již byla čtrnáctá noc, a my se plavili po moři Adriatickém, okolo půlnoci, domnívali se plavci, že by se jim okazovala krajina nějaká.'),
(1574144,54,44,27,28,'Kteřížto spustivše do vody olovnici, nalezli hlubokost dvadcíti loktů; a odjevše odtud maličko, opět spustivše olovnici, nalezli hlubokost patnácti loktů.'),
(1574145,54,44,27,29,'A bojíce se, aby na místa skalnatá neuhodili, spustivše z bárky čtyři kotve, žádali, aby den byl.'),
(1574146,54,44,27,30,'Chtěli pak marináři utéci z bárky, pustivše člun do moře, pod zámyslem, jako by chtěli od předku lodí kotve roztahovati,'),
(1574147,54,44,27,31,'I řekl Pavel setníkovi a žoldnéřům: Nezůstanou-li tito na lodí, vy nebudete moci zachováni býti.'),
(1574148,54,44,27,32,'Tedy žoldnéři utínali provazy u člunu, a pustili jej, aby pryč plynul.'),
(1574149,54,44,27,33,'A když již dnělo, napomínal Pavel všech, aby pojedli, řka: Již jest tomu dnes čtrnáctý den, jakž očekávajíce, trváte lační, nic nejedouce.'),
(1574150,54,44,27,34,'Protož prosím vás, abyste pojedli pro zachování vašeho zdraví; neb žádného z vás vlas s hlavy nespadne.'),
(1574151,54,44,27,35,'A to pověděv, vezma chléb, díky vzdával Bohu přede všemi, a rozlomiv, počal jísti.'),
(1574152,54,44,27,36,'A tak potěšeni byvše všickni, pojedli i oni.'),
(1574153,54,44,27,37,'Bylo pak nás všech osob na lodí dvě stě sedmdesáte a šest.'),
(1574154,54,44,27,38,'A nasyceni jsouce pokrmem, oblehčovali bárku, vysýpajíce pšenici do moře.'),
(1574155,54,44,27,39,'A když byl den, nemohli země viděti, než okřídlí nějaké znamenali, ano má břeh, k němuž myslili, kdyby jak mohli přistáti s lodí.'),
(1574156,54,44,27,40,'A vytáhše kotvy, pustili se po moři, rozpustivše také provazy pravidl; a zdvihše plachtu k větru, táhli se k břehu.'),
(1574157,54,44,27,41,'Ale když trefili na to místo, kdež se dvoje moře schází, tu se zastavila lodí. A přední konec lodí uváznutý stál, nehýbaje se, zadní pak konec lámal se násilím vln.'),
(1574158,54,44,27,42,'Tedy žoldnéři radili setníkovi, aby vězně zmordovali, aby jim některý vyplyna, neutekl.'),
(1574159,54,44,27,43,'Ale setník chtěje zachovati Pavla, nedal toho učiniti. I rozkázal těm, kteříž mohli plynouti, aby se pustili nejprv do moře a vyplynuli na zem,'),
(1574160,54,44,27,44,'Jiní pak aby na dskách plynuli a někteří na těch kusích lodí. I takž se stalo, že všickni zdraví vyšli na zemi.'),
(1574161,54,44,28,1,'A tak zachováni jsouce, teprv poznali, že ostrov ten sloul Melita.'),
(1574162,54,44,28,2,'Lidé pak toho ostrova velikou přívětivost k nám ukázali. Nebo zapálivše hranici drev, přijali nás všecky, pro déšť, kterýž v tu chvíli byl, a pro zimu.'),
(1574163,54,44,28,3,'A když Pavel sebral drahně roždí a kladl na oheň, ještěrka, utíkajíc před horkem, připjala se k ruce jeho.'),
(1574164,54,44,28,4,'A když uzřeli lidé toho ostrovu, ano ještěrka visí u ruky jeho, řekli jedni k druhým: Jistě člověk tento jest vražedlník; neb ač z moře vyšel, však pomsta Boží nedá jemu živu býti.'),
(1574165,54,44,28,5,'Ale on střásl tu ještěrku do ohně, a nic se jemu zlého nestalo.'),
(1574166,54,44,28,6,'Oni pak očekávali, že oteče, aneb padna, pojednou umře. A když toho dlouho čekali a viděli, že se mu nic zlého nestalo, změnivše myšlení své, pravili, že jest on bůh.'),
(1574167,54,44,28,7,'Na těch pak místech měl popluží kníže toho ostrova, jménem Publius, kterýžto přijav nás k sobě, za tři dni přátelsky u sebe v hospodě choval.'),
(1574168,54,44,28,8,'I přihodilo se, že otec toho Publia ležel, maje zimnici a červenou nemoc. K němuž všed Pavel, a pomodliv se, vzložil na něj ruce a uzdravil jej.'),
(1574169,54,44,28,9,'A když se to stalo, tedy i jiní, kteříž na ostrově tom nemocní byli, přistupovali, a byli uzdravováni.'),
(1574170,54,44,28,10,'Ctili nás pak velice, a když jsme se měli pryč plaviti, nakladli nám na lodí toho, čehož potřebí bylo.'),
(1574171,54,44,28,11,'A po třech měsících plavili jsme se na bárce Alexandrinské, kteráž tu byla na tom ostrově přes zimu, majici za erb Kastora a Polluxa.'),
(1574172,54,44,28,12,'A když jsme přijeli do Syrakusis, zůstali jsme tu za tři dni.'),
(1574173,54,44,28,13,'A odtud okolo plavíce se, přišli jsme do Regium; a po jednom dni, když vál vítr od poledne, druhý den přijeli jsme do Puteolos.'),
(1574174,54,44,28,14,'Kdežto nalezli jsme bratří, kteříž nás prosili, abychom pobyli u nich za sedm dní. A tak jsme šli k Římu.'),
(1574175,54,44,28,15,'Odkudž, když o nás uslyšeli bratří, vyšli proti nám až na rynk Appiův a ke Třem krčmám. Kteréžto uzřev Pavel, poděkoval Bohu a počal býti dobré mysli.'),
(1574176,54,44,28,16,'A když jsme přišli do Říma, setník dal vězně v moc hejtmanu vojska, ale Pavlovi dopuštěno, aby sám bydlil s žoldnéřem, kterýž ho ostříhal.'),
(1574177,54,44,28,17,'I stalo se po třech dnech, svolal Pavel muže přední z Židů. A když se sešli, řekl k nim: Muži bratří, já nic neučiniv proti lidu ani proti obyčejům otcovským, jat jsa, z Jeruzaléma vydán jsem v ruce Římanům,'),
(1574178,54,44,28,18,'Kteříž vyslyševše mne, chtěli mne propustiti, protože žádné viny hodné smrti na mně nebylo.'),
(1574179,54,44,28,19,'Ale když Židé tomu odpírali, přinucen jsem odvolati se k císaři, ne jako bych měl co národ svůj žalovati.'),
(1574180,54,44,28,20,'A protož z té příčiny povolal jsem vás, žádostiv jsa viděti vás a s vámi promluviti; nebo pro naději lidu Izraelského řetězem tímto svázán jsem.'),
(1574181,54,44,28,21,'A oni řekli jemu: Myť jsme žádného psaní neměli o tobě z Židovstva, aniž kdo z bratří přijda, vypravoval nám, aneb mluvil co zlého o tobě.'),
(1574182,54,44,28,22,'Ale žádámeť od tebe slyšeti, jak smyslíš; nebo víme o té sektě, že se jí všudy odpírá.'),
(1574183,54,44,28,23,'A když jemu uložili den, sešlo se jich mnoho do hospody k němu, jimžto s osvědčováním vypravoval o království Božím, slouže jim k víře o Ježíšovi z Zákona Mojžíšova a Proroků, od jitra až do večera.'),
(1574184,54,44,28,24,'A někteří uvěřili tomu, což Pavel vypravoval, někteří pak nevěřili.'),
(1574185,54,44,28,25,'A tak nejsouce mezi sebou svorní, rozešli se, k nimžto promluvil Pavel toto jedno slovo: Jistě žeť jest dobře Duch svatý skrze proroka Izaiáše mluvil k otcům našim,'),
(1574186,54,44,28,26,'Řka: Jdi k lidu tomuto a rciž jim: Sluchem slyšeti budete, a nesrozumíte, a hledíce hleděti budete, a neuzříte.'),
(1574187,54,44,28,27,'Nebo zhrublo srdce lidu tohoto, a ušima těžce slyšeli, a oči své zamhouřili, aby snad neviděli očima, a ušima neslyšeli, a srdcem nerozuměli, a neobrátili se, abych jich neuzdravil.'),
(1574188,54,44,28,28,'Budiž vám tedy známo, že jest pohanům posláno toto spasení Boží, a oniť slyšeti budou.'),
(1574189,54,44,28,29,'A když on to propověděl, odešli Židé, majíce mezi sebou mnohé hádky.'),
(1574190,54,44,28,30,'Pavel pak trval za celé dvě létě v hospodě své, a přijímal všecky, kteříž přicházeli k němu,'),
(1574191,54,44,28,31,'Káže o království Božím a uče těm věcem, kteréž jsou o Pánu Ježíši Kristu, se vší doufanlivostí bez překážky.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574192,54,45,1,1,'Pavel, služebník Jezukristův, povolaný apoštol, oddělený k kázaní evangelium Božího,'),
(1574193,54,45,1,2,'(Kteréžto zdávna zaslíbil skrze proroky své v Písmích svatých,)'),
(1574194,54,45,1,3,'O Synu jeho, (zplozeném z semene Davidova s strany těla,'),
(1574195,54,45,1,4,'Kterýž prokázán jest býti Synem Božím mocně, podle Ducha posvěcení, skrze z mrtvých vstání,) totiž o Ježíši Kristu, Pánu našem,'),
(1574196,54,45,1,5,'Skrze něhožto jsme přijali milost a apoštolství ku poslušenství víry mezi všemi národy pro jméno jeho,'),
(1574197,54,45,1,6,'Z nichžto i vy jste povolaní Ježíše Krista,'),
(1574198,54,45,1,7,'Všechněm, kteříž jste v Římě, milým Božím, povolaným svatým: Milost vám a pokoj od Boha Otce našeho a Pána Ježíše Krista.'),
(1574199,54,45,1,8,'Nejprve pak díky činím Bohu svému skrze Ježíše Krista ze všech vás, že víra vaše rozhlašuje se po všem světě.'),
(1574200,54,45,1,9,'Svědek mi jest zajisté Bůh, kterémužto sloužím duchem mým v evangelium Syna jeho, žeť bez přestání zmínku o vás činím,'),
(1574201,54,45,1,10,'Vždycky na svých modlitbách žádaje, abych aspoň někdy mohl šťastně k vám, byla-li by vůle Boží, přijíti.'),
(1574202,54,45,1,11,'Neboť velice žádám viděti vás, abych vám udělil částku nějakou milosti duchovní ku potvrzení vašemu,'),
(1574203,54,45,1,12,'To jest, abych spolu s vámi potěšen byl, skrze společnou i vaši i mou víru.'),
(1574204,54,45,1,13,'Nechciť pak, bratří, abyste nevěděli, žeť jsem mnohokrát již uložil přijíti k vám, (ale překážky jsem měl až dosavad,) abych nějaký užitek také i mezi vámi měl, jako i mezi jinými národy.'),
(1574205,54,45,1,14,'Nebo Řekům i kterýmkoli jiným národům, i moudrým i nemoudrým, dlužník jsem.'),
(1574206,54,45,1,15,'A tak, pokudž na mně jest, hotov jsem i vám, kteříž v Římě jste, zvěstovati evangelium.'),
(1574207,54,45,1,16,'Neboť se nestydím za evangelium Kristovo; moc zajisté Boží jest k spasení každému věřícímu, Židu předně, potom i Řeku.'),
(1574208,54,45,1,17,'Nebo spravedlnost Boží zjevuje se skrze ně z víry u víru, jakož psáno jest: Spravedlivý pak z víry živ bude.'),
(1574209,54,45,1,18,'Zjevuje se zajisté hněv Boží s nebe proti každé bezbožnosti a nepravosti lidí, pravdu Boží v nepravosti zadržujících.'),
(1574210,54,45,1,19,'Nebo což poznáno býti může o Bohu, známé jest jim učiněno, Bůh zajisté zjevil jim.'),
(1574211,54,45,1,20,'Nebo neviditelné věci jeho mohou vidíny býti, když z skutků při stvoření světa stalých rozumem pochopeny bývají, totiž ta jeho věčná moc a Božství, tak aby již byli bez výmluvy,'),
(1574212,54,45,1,21,'Protože poznavše Boha, nectili jako Boha, ani jemu děkovali, ale marní učiněni jsou v myšleních svých, a zatmíno jest nemoudré srdce jejich.'),
(1574213,54,45,1,22,'Měvše se za moudré, blázni učiněni jsou.'),
(1574214,54,45,1,23,'Nebo směnili slávu neporušitelného Boha v slávu podobenství obraza porušitelného člověka, i ptactva, i hovad čtvernohých, i zeměplazů.'),
(1574215,54,45,1,24,'Protož i Bůh vydal je v žádosti srdce jejich, v nečistotu, aby zprznili těla svá vespolek,'),
(1574216,54,45,1,25,'Jakožto ty, kteříž jsou směnili pravdu Boží za lež, a ctili i sloužili stvoření raději nežli Stvořiteli, kterýž jest požehnaný na věky. Amen.'),
(1574217,54,45,1,26,'Protož je vydal Bůh v žádosti ohavné. Nebo i ženy jejich změnily přirozené sebe užívání v to, kteréž jest proti přirození.'),
(1574218,54,45,1,27,'A podobně i mužské pohlaví, opustivše přirozené užívání ženy, rozpálili se v žádostech svých jedni k druhým, mužské pohlaví vespolek mrzkost pášíce, a tak spravedlivou mzdu, kteráž na jejich blud slušela, sami na sebe uvodíce.'),
(1574219,54,45,1,28,'A jakož sobě málo vážili známosti Boha, takž také Bůh vydal je v převrácený smysl, aby činili to, což nesluší,'),
(1574220,54,45,1,29,'Jsouce naplněni vší nepravostí, zlostí, smilstvem, nešlechetností, lakomstvím, plní závisti, vraždy, svárů, lsti, zlých obyčejů,'),
(1574221,54,45,1,30,'Utrhači, pomluvači, Boha nenávidící, hanliví, pyšní, chlubní, nalezači zlých věcí, rodičů neposlušní,'),
(1574222,54,45,1,31,'Nemoudří, smluv nezdrželiví, beze vší lítosti, neukojitelní a nemilosrdní.'),
(1574223,54,45,1,32,'Kteřížto vědouce o tom právu Božím, že ti, kteříž takové věci činí, hodni jsou smrti, avšak netoliko ty věci činí, ale i jiným též činícím nakládají.'),
(1574224,54,45,2,1,'Protož nemůžeš se vymluviti, ó člověče každý, potupuje jiného. Nebo tím, že jiného potupuješ, sám sebe odsuzuješ, poněvadž totéž činíš, což na jiném tupíš.'),
(1574225,54,45,2,2,'Vímeť zajisté, že soud Boží jest podle pravdy proti těm, kteříž takové věci činí.'),
(1574226,54,45,2,3,'Zdali se domníváš, ó člověče, jenž soudíš ty, kdož takové věci činí, a sám totéž čině, že ty ujdeš soudu Božího?'),
(1574227,54,45,2,4,'Čili bohatstvím dobrotivosti jeho a snášelivosti i dlouhočekání pohrdáš, nevěda, že dobrotivost Boží ku pokání tebe vede?'),
(1574228,54,45,2,5,'Ale podle tvrdosti své a srdce nekajícího shromažďuješ sobě hněv ke dni hněvu a zjevení spravedlivého soudu Božího,'),
(1574229,54,45,2,6,'Kterýž odplatí jednomu každému podle skutků jeho,'),
(1574230,54,45,2,7,'Těm zajisté, kteříž trvajíce v dobrém skutku, slávy a cti a nesmrtelnosti hledají, životem věčným,'),
(1574231,54,45,2,8,'Těm pak, kteříž jsou svárliví a pravdě nepovolují, ale povolují nepravosti, prchlivostí a hněvem,'),
(1574232,54,45,2,9,'Trápením a úzkostí, a to každé duši člověka činícího zlé, i Žida předně, a též i Řeka.'),
(1574233,54,45,2,10,'Ale slávu a čest a pokoj dá každému, kdož činí dobré, i Židu předně, a též i Řeku.'),
(1574234,54,45,2,11,'Neboť není přijímání osob u Boha.'),
(1574235,54,45,2,12,'Kteřížkoli zajisté bez Zákona hřešili, bez Zákona i zahynou; a kteřížkoli pod Zákonem byvše hřešili, skrze Zákon odsouzeni budou,'),
(1574236,54,45,2,13,'(Nebo ne ti, jenž slyší Zákon, spravedlivi jsou před Bohem, ale činitelé Zákona spravedlivi budou.'),
(1574237,54,45,2,14,'Nebo když pohané Zákona nemajíce, od přirození činí to, což přikazuje Zákon, takoví Zákona nemajíce, sami sobě zákonem jsou,'),
(1574238,54,45,2,15,'Kteřížto ukazují dílo Zákona napsané na srdcích svých, když jim to osvědčuje svědomí jejich i myšlení, kteráž se vespolek obviňují, anebo také vymlouvají.)'),
(1574239,54,45,2,16,'V ten den, kdyžto souditi bude Bůh tajné věci lidské, podle evangelium mého skrze Jezukrista.'),
(1574240,54,45,2,17,'Aj, ty sloveš Žid, a spoléháš na Zákon, a chlubíš se Bohem,'),
(1574241,54,45,2,18,'A znáš vůli jeho, a rozeznáváš, co sluší neb nesluší, naučen jsa z Zákona,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574242,54,45,2,19,'A za to máš, že jsi ty vůdcím slepých, světlem těch, kteříž jsou ve tmě,'),
(1574243,54,45,2,20,'Ředitelem nemoudrých, učitelem nemluvňat, majícím formu umění a pravdy v Zákoně.'),
(1574244,54,45,2,21,'Kterakž tedy jiného uče, sám sebe neučíš? Vyhlašuje, že nemá kradeno býti, sám kradeš?'),
(1574245,54,45,2,22,'Pravě: Nezcizoložíš, a cizoložství pácháš? V ohavnosti maje modly, svatokrádeže se dopouštíš?'),
(1574246,54,45,2,23,'Zákonem se chlubě, přestupováním Zákona Bohu neúctu činíš?'),
(1574247,54,45,2,24,'Nebo jméno Boží pro vás v porouhání jest mezi pohany, jakož psáno jest.'),
(1574248,54,45,2,25,'Obřezáníť zajisté prospěje, budeš-li Zákon plniti; pakli budeš přestupitelem Zákona, obřezání tvé učiněno jest neobřezáním.'),
(1574249,54,45,2,26,'A protož jestližeť by neobřízka ostříhala práv Zákona, zdaliž nebude počtena neobřízka jejich za obřízku?'),
(1574250,54,45,2,27,'A odsoudí ti, kteříž jsou z přirození neobřízka, zachovávajíce Zákon, tebe, kterýž pod literou a obřízkou přestupník jsi Zákona?'),
(1574251,54,45,2,28,'Nebo ne ten jest pravý Žid, kterýž jest zjevně Židem; aniž to jest pravé obřezání, kteréž bývá zjevně na těle;'),
(1574252,54,45,2,29,'Ale ten jest pravý Žid, kterýžto vnitř jest Židem, a to jest pravé obřezání, kteréž jest srdečné v duchu, a ne podle litery; jehožto chvála ne z lidí jest, ale z Boha.'),
(1574253,54,45,3,1,'Což tedy má více Žid nežli pohan? Aneb jaký jest užitek obřízky?'),
(1574254,54,45,3,2,'Mnohý všelikterak. Přední zajisté ten, že jest jim svěřen Zákon Boží.'),
(1574255,54,45,3,3,'Nebo což jest do toho, jestliže byli někteří z nich nevěrní? Zdaliž nevěra jejich věrnost Boží vyprázdní?'),
(1574256,54,45,3,4,'Nikoli, nýbrž budiž Bůh pravdomluvný, ale každý člověk lhář, jakož psáno jest: Aby ospravedlněn byl v řečech svých, a přemohl, když by soudil.'),
(1574257,54,45,3,5,'Ale jestližeť pak nepravost naše spravedlnost Boží zvelebuje, což díme? Zdali nespravedlivý jest Bůh, jenž uvodí hněv? (Po lidskuť pravím.)'),
(1574258,54,45,3,6,'Nikoli, sic jinak kterakž by Bůh soudil svět?'),
(1574259,54,45,3,7,'Nebo jestližeť pravda Boží mou lží rozmohla se k slávě jeho, i pročež pak já jako hříšník bývám souzen?'),
(1574260,54,45,3,8,'A ne raději (jakž o nás zle mluví a jakož někteří praví, že bychom říkali,): Čiňme zlé věci, aby přišly dobré? Jichžto spravedlivé jest odsouzení.'),
(1574261,54,45,3,9,'Což tedy? My převyšujeme pohany? Nikoli, nebo jsme již prve dokázali toho, že jsou, i Židé i Řekové, všickni pod hříchem,'),
(1574262,54,45,3,10,'Jakož psáno jest: Že není spravedlivého ani jednoho.'),
(1574263,54,45,3,11,'Není rozumného, není, kdo by hledal Boha.'),
(1574264,54,45,3,12,'Všickni se uchýlili, spolu neužiteční učiněni jsou; není, kdo by činil dobré, není ani jednoho.'),
(1574265,54,45,3,13,'Hrob otevřený hrdlo jejich, jazyky svými lstivě mluvili, jed lítých hadů pod rty jejich.'),
(1574266,54,45,3,14,'Kterýchžto ústa plná jsou zlořečení a hořkosti.'),
(1574267,54,45,3,15,'Nohy jejich rychlé k vylévání krve.'),
(1574268,54,45,3,16,'Setření a bída na cestách jejich.'),
(1574269,54,45,3,17,'A cesty pokoje nepoznali.'),
(1574270,54,45,3,18,'Není bázně Boží před očima jejich.'),
(1574271,54,45,3,19,'Víme pak, že cožkoli Zákon mluví, těm, kteříž jsou pod Zákonem, mluví, aby všeliká ústa zacpána byla a aby vinen byl všecken svět Bohu.'),
(1574272,54,45,3,20,'Protož z skutků Zákona nebude ospravedlněn žádný člověk před obličejem jeho; nebo skrze Zákon přichází poznání hřícha.'),
(1574273,54,45,3,21,'Ale nyní bez Zákona spravedlnost Boží zjevena jest, osvědčená Zákonem i Proroky,'),
(1574274,54,45,3,22,'Spravedlnost totiž Boží, skrze víru Ježíše Krista, ke všem a na všecky věřící.'),
(1574275,54,45,3,23,'Neboť není rozdílu. Všickniť zajisté zhřešili, a nemají slávy Boží.'),
(1574276,54,45,3,24,'Spravedlivi pak učiněni bývají darmo, milostí jeho, skrze vykoupení, kteréž se stalo v Kristu Ježíši,'),
(1574277,54,45,3,25,'Jehožto Bůh vydal za smírci, skrze víru ve krvi jeho, k ukázání spravedlnosti své, skrze odpuštění předešlých hříchů,'),
(1574278,54,45,3,26,'V shovívání Božím, k dokázání spravedlnosti své v nynějším času, k tomu, aby on spravedlivým byl a ospravedlňujícím toho, jenž jest z víry Ježíšovy.'),
(1574279,54,45,3,27,'Kdež jest tedy chlouba tvá? Vyprázdněna jest. Skrze který zákon? Skutků-li? Nikoli, ale skrze zákon víry.'),
(1574280,54,45,3,28,'Protož za to máme, že člověk bývá spravedliv učiněn věrou bez skutků Zákona.'),
(1574281,54,45,3,29,'Zdaliž jest toliko Bůh Židů? Zdali také není i pohanů? Ba, jistě i pohanů,'),
(1574282,54,45,3,30,'Poněvadž jeden jest Bůh, kterýž ospravedlňuje obřízku z víry, a neobřízku skrze víru.'),
(1574283,54,45,3,31,'Což tedy Zákon vyprazdňujeme skrze víru? Nikoli, nýbrž Zákon tvrdíme.'),
(1574284,54,45,4,1,'Což tedy díme, čeho jest došel podle těla Abraham otec náš?'),
(1574285,54,45,4,2,'Nebo byl-liť Abraham z skutků spravedliv učiněn, máť se čím chlubiti, ale ne u Boha.'),
(1574286,54,45,4,3,'Nebo co praví Písmo? Uvěřil pak Abraham Bohu, i počteno jemu za spravedlnost.'),
(1574287,54,45,4,4,'Kdožť skutky činí, tomuť odplata nebývá počtena podle milosti, ale podle dluhu.'),
(1574288,54,45,4,5,'Tomu pak, kdož nečiní skutků, ale věří v toho, kterýž spravedlivého činí bezbožníka, bývá počtena víra jeho za spravedlnost,'),
(1574289,54,45,4,6,'Jakož i David vypravuje blahoslavenství člověka, jemuž Bůh přivlastňuje spravedlnost bez skutků, řka:'),
(1574290,54,45,4,7,'Blahoslavení, jichžto odpuštěny jsou nepravosti a jejichžto přikryti jsou hříchové.'),
(1574291,54,45,4,8,'Blahoslavený muž, kterémuž Pán nepočítá hříchu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574292,54,45,4,9,'Blahoslavenství tedy toto k obřízce-li se vztahuje toliko, čili také k neobřízce? Nebo pravíme, že Abrahamovi víra jest počtena za spravedlnost.'),
(1574293,54,45,4,10,'Kterak pak jest počtena? Zdali když byl obřezán, čili před obřezáním? Ne v obřízce, ale před obřezáním.'),
(1574294,54,45,4,11,'A potom znamení, totiž obřízku, přijal za znamení spravedlnosti víry, kteráž byla před obřezáním, na to, aby byl otcem všech věřících v neobřízce, aby i jim přičtena byla spravedlnost,'),
(1574295,54,45,4,12,'A aby byl otcem obřízky, těch totiž, kteříž ne z obřízky toliko jsou, ale kteříž kráčejí šlépějemi víry otce našeho Abrahama, kteráž byla před obřezáním.'),
(1574296,54,45,4,13,'Nebo ne skrze Zákon stalo se zaslíbení Abrahamovi, aneb semeni jeho, aby byl dědicem světa, ale skrze spravedlnost víry.'),
(1574297,54,45,4,14,'Nebo jestližeť toliko ti, kteříž jsou z Zákona, dědicové jsou, zmařena jest víra a zrušeno zaslíbení.'),
(1574298,54,45,4,15,'Zákon zajisté hněv působí; nebo kdež není Zákona, tu ani přestoupení.'),
(1574299,54,45,4,16,'A protož z víry jde dědictví, aby šlo podle milosti, proto aby pevné bylo zaslíbení všemu semeni, netoliko tomu, kteréž z Zákona jest, ale i tomu, jenž jest z víry Abrahamovy, kterýž jest otec všech nás,'),
(1574300,54,45,4,17,'(Jakož psáno jest: Otcem mnohých národů postavil jsem tebe,) před obličejem Boha, jemuž uvěřil, kterýž obživuje mrtvé a povolává i těch věcí, jichž není, jako by byly.'),
(1574301,54,45,4,18,'Kterýžto Abraham v naději proti naději uvěřil, že bude otcem mnohých národů, podle toho povědění: Takť bude símě tvé, jakožto hvězdy nebeské a jako písek mořský.'),
(1574302,54,45,4,19,'A nezemdlev u víře, nepatřil na své tělo již umrtvené, ješto téměř ve stu letech byl, ani na život Sáry také již umrtvený.'),
(1574303,54,45,4,20,'Ale o zaslíbení Božím nepochyboval z nedověry, nýbrž posilnil se věrou, dav chválu Bohu,'),
(1574304,54,45,4,21,'Jsa tím jist, že cožkoli zaslíbil, mocen jest i učiniti.'),
(1574305,54,45,4,22,'A protož počteno jest jemu to za spravedlnost.'),
(1574306,54,45,4,23,'Jestiť pak to napsáno ne pro něj toliko, že jemu to počteno bylo za spravedlnost,'),
(1574307,54,45,4,24,'Ale i pro nás, kterýmžto bude počteno za spravedlnost, věřícím v toho, kterýž vzkřísil Ježíše Pána našeho z mrtvých,'),
(1574308,54,45,4,25,'Kterýž vydán jest na smrt pro hříchy naše a vstal z mrtvých pro ospravedlnění naše.'),
(1574309,54,45,5,1,'Ospravedlněni tedy jsouce z víry, pokoj máme s Bohem skrze Pána našeho Jezukrista,'),
(1574310,54,45,5,2,'Skrze něhož i přístup měli jsme věrou k milosti této, kterouž stojíme. A chlubíme se nadějí slávy Boží.'),
(1574311,54,45,5,3,'A ne toliko nadějí, ale také chlubíme se souženími, vědouce, že soužení trpělivost působí,'),
(1574312,54,45,5,4,'A trpělivost zkušení, zkušení pak naději,'),
(1574313,54,45,5,5,'A nadějeť nezahanbuje. Nebo láska Boží rozlita jest v srdcích našich skrze Ducha svatého, kterýž dán jest nám.'),
(1574314,54,45,5,6,'Kristus zajisté, když jsme my ještě mdlí byli, v čas příhodný za bezbožné umřel.'),
(1574315,54,45,5,7,'Ješto sotva kdo za spravedlivého umře, ač za dobréhoť by někdo snad i umříti směl.'),
(1574316,54,45,5,8,'Dokazujeť pak Bůh lásky své k nám; nebo když jsme ještě hříšníci byli, Kristus umřel za nás.'),
(1574317,54,45,5,9,'Čím tedy více nyní již ospravedlněni jsouce krví jeho, spaseni budeme skrze něho od hněvu.'),
(1574318,54,45,5,10,'Poněvadž byvše nepřátelé, smířeni jsme s Bohem skrze smrt Syna jeho, nadtoť již smíření spaseni budeme skrze život jeho.'),
(1574319,54,45,5,11,'A ne toliko to, ale chlubíme se také i Bohem, skrze Pána našeho Jezukrista, skrze něhož nyní smíření jsme došli.'),
(1574320,54,45,5,12,'A protož jakož skrze jednoho člověka hřích na svět všel a skrze hřích smrt, a tak na všecky lidi smrt přišla, v němž všickni zhřešili.'),
(1574321,54,45,5,13,'Nebo až do Zákona hřích byl na světě, ale hřích se nepočítá, když Zákona není.'),
(1574322,54,45,5,14,'Kralovala pak smrt od Adama až do Mojžíše také i nad těmi, kteříž nehřešili ku podobenství přestoupení Adamova, kterýž jest figura toho budoucího Adama.'),
(1574323,54,45,5,15,'Ale ne jako hřích, tak i milost. Nebo poněvadž onoho pádem jednoho mnoho jich zemřelo, mnohemť více milost Boží a dar z milosti toho jednoho člověka Jezukrista na mnohé rozlit jest.'),
(1574324,54,45,5,16,'Avšak ne jako skrze jednoho, kterýž zhřešil, tak zase milost. Nebo vina z jednoho pádu přivedla všecky k odsouzení, ale milost z mnohých hříchů přivodí k ospravedlnění.'),
(1574325,54,45,5,17,'Nebo poněvadž pro pád jeden smrt kralovala pro jednoho, mnohemť více, kteříž by rozhojněnou milost a dar spravedlnosti přijali, v životě novém kralovati budou skrze jednoho Jezukrista.'),
(1574326,54,45,5,18,'A tak tedy, jakž skrze pád jeden všickni lidé přišli k odsouzení, tak i skrze ospravedlnění jednoho všickni lidé mohou přijíti k ospravedlnění života.'),
(1574327,54,45,5,19,'Neb jakož skrze neposlušenství jednoho člověka učiněno jest mnoho hříšných, tak i skrze poslušenství jednoho spravedlivi učiněni budou mnozí.'),
(1574328,54,45,5,20,'Zákon pak vkročil mezi to, aby se rozhojnil hřích, a když se rozhojnil hřích, tedy ještě více rozhojnila se milost,'),
(1574329,54,45,5,21,'Aby jakož jest kraloval hřích k smrti, tak aby i milost kralovala skrze spravedlnost k životu věčnému, skrze Jezukrista Pána našeho.'),
(1574330,54,45,6,1,'Což tedy díme? Snad zůstaneme v hříchu, aby se milost rozhojnila?'),
(1574331,54,45,6,2,'Nikoli. Kteříž jsme zemřeli hříchu, kterakž ještě živi budeme v něm?'),
(1574332,54,45,6,3,'Zdaliž nevíte, že kteřížkoli pokřtěni jsme v Krista Ježíše, v smrt jeho pokřtěni jsme?'),
(1574333,54,45,6,4,'Pohřbeni jsme tedy s ním skrze křest v smrt, abychom, jakož z mrtvých vstal Kristus k slávě Otce, tak i my v novotě života chodili.'),
(1574334,54,45,6,5,'Nebo poněvadž jsme v něj vštípeni připodobněním smrti jeho, tedy i vzkříšením jemu připodobněni budeme,'),
(1574335,54,45,6,6,'To vědouce, že starý člověk náš s ním spolu ukřižován jest, aby bylo umrtveno tělo hřícha, abychom již potom nesloužili hříchu.'),
(1574336,54,45,6,7,'Nebo kdožť umřel, ospravedlněn jest od hříchu.'),
(1574337,54,45,6,8,'Jestližeť jsme pak zemřeli s Kristem, věřímeť, že spolu s ním také živi budeme,'),
(1574338,54,45,6,9,'Vědouce, že Kristus vstav z mrtvých, již více neumírá, smrt nad ním již více nepanuje.'),
(1574339,54,45,6,10,'Nebo že jest umřel, hříchu umřel jednou; že pak jest živ, živ jest Bohu.'),
(1574340,54,45,6,11,'Tak i vy za to mějte, že jste zemřeli zajisté hříchu, ale živi jste Bohu v Kristu Ježíši, Pánu našem.'),
(1574341,54,45,6,12,'Nepanujž tedy hřích v smrtelném těle vašem, tak abyste povolovali jemu v žádostech jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574342,54,45,6,13,'Aniž vydávejte údů svých za odění nepravosti kterémukoli hříchu, ale vydávejte se k sloužení Bohu, jakožto vstavše z mrtvých a jsouce živi, a údy své vydávejte za odění spravedlnosti Bohu.'),
(1574343,54,45,6,14,'Nebo hřích nebude panovati nad vámi; nejste zajisté pod Zákonem, ale pod milostí.'),
(1574344,54,45,6,15,'Což tedy? Hřešiti budeme, když nejsme pod Zákonem, ale pod milostí? Nikoli.'),
(1574345,54,45,6,16,'Zdaliž nevíte, že komuž se vydáváte za služebníky ku poslušenství, toho jste služebníci, kohož posloucháte, buďto hříchu k smrti, buďto poslušenství k spravedlnosti?'),
(1574346,54,45,6,17,'Ale díka Bohu, že byvše služebníci hřícha, uposlechli jste z srdce způsobu učení toho, v kteréž uvedeni jste.'),
(1574347,54,45,6,18,'Vysvobozeni jsouce pak od hříchu, učiněni jste služebníci spravedlnosti.'),
(1574348,54,45,6,19,'Po lidsku pravím, pro mdlobu těla vašeho: Jakž jste vydávali údy vaše v službu nečistotě a nepravosti k tomu, abyste činili nepravost, tak již nyní vydávejte údy vaše v službu spravedlnosti ku posvěcení.'),
(1574349,54,45,6,20,'Nebo když jste byli služebníci hřícha, cizí jste byli od spravedlnosti.'),
(1574350,54,45,6,21,'Jaký jste pak užitek měli tehdáž toho, začež se nyní stydíte? Konec zajisté těch věcí jest smrt.'),
(1574351,54,45,6,22,'Nyní pak vysvobozeni jsouce od hříchu a podmaněni v službu Bohu, máte užitek váš ku posvěcení, cíl pak život věčný.'),
(1574352,54,45,6,23,'Nebo odplata za hřích jest smrt, ale milost Boží jest život věčný v Kristu Ježíši, Pánu našem.'),
(1574353,54,45,7,1,'Zdaliž nevíte, bratří, (nebo povědomým Zákona mluvím) že Zákon panuje nad člověkem, dokudž živ jest člověk?'),
(1574354,54,45,7,2,'Nebo žena, kteráž za mužem jest, živému muži přivázána jest zákonem; pakli by umřel muž její, rozvázána jest od zákona muže.'),
(1574355,54,45,7,3,'A protož dokudž jest živ muž její, slouti bude cizoložnice, bude-li s jiným mužem; pakliť by muž její umřel, jižť jest svobodna od zákona toho, takže již nebude cizoložnice, bude-li s jiným mužem.'),
(1574356,54,45,7,4,'Takž, bratří moji, i vy umrtveni jste Zákonu skrze tělo Kristovo, abyste byli jiného, totiž toho, kterýž z mrtvých vstal, abychom ovoce nesli Bohu.'),
(1574357,54,45,7,5,'Nebo když jsme byli v těle, žádosti hříchů příčinou Zákona vzbuzené moc svou provodily v údech našich k nesení ovoce ne Bohu, ale smrti.'),
(1574358,54,45,7,6,'Nyní pak osvobozeni jsme od Zákona, když umřel ten, v němž jsme držáni byli, tak abychom již sloužili v novotě ducha, a ne v vetchosti litery.'),
(1574359,54,45,7,7,'Což tedy díme? Že Zákon jest hříchem? Nikoli; nýbrž hříchu jsem nepoznal, než skrze Zákon. Nebo i o žádosti byl bych nevěděl, aby hříchem byla, by byl Zákon neřekl: Nepožádáš.'),
(1574360,54,45,7,8,'Ale příčinu vzav hřích skrze přikázaní, zplodil ve mně všelikou žádost. Bez Zákona zajisté hřích mrtev jest.'),
(1574361,54,45,7,9,'Jáť pak byl jsem živ někdy bez Zákona, ale když přišlo přikázání, hřích ožil,'),
(1574362,54,45,7,10,'a já umřel. I shledáno jest, že to přikázání, kteréž mělo mi býti k životu, že jest mi k smrti.'),
(1574363,54,45,7,11,'Nebo hřích, vzav příčinu skrze to přikázání, podvedl mne, a skrze ně i zabil.'),
(1574364,54,45,7,12,'A tak Zákon zajisté svatý, a přikázání svaté i spravedlivé a dobré jest.'),
(1574365,54,45,7,13,'Tedy to dobré učiněno jest mi smrt? Nikoli, ale hřích, kterýž aby se okázal býti hříchem, skrze to dobré zplodil mi smrt, aby tak byl příliš velmi hřešící hřích skrze přikázání.'),
(1574366,54,45,7,14,'Víme zajisté, že Zákon jest duchovní, ale já jsem tělesný, prodaný hříchu.'),
(1574367,54,45,7,15,'Nebo toho, což činím, neoblibuji; nebo ne, což chci, to činím, ale, což v nenávisti mám, to činím.'),
(1574368,54,45,7,16,'Jestližeť pak, což nechci, to činím, tedy povoluji Zákonu, že jest dobrý.'),
(1574369,54,45,7,17,'A tak již ne já to činím, ale ten, kterýž přebývá ve mně, hřích.'),
(1574370,54,45,7,18,'Vímť zajisté, že nepřebývá ve mně, (to jest v těle mém), dobré. Nebo chtění hotové mám, ale vykonati dobrého, tohoť nenalézám.'),
(1574371,54,45,7,19,'Nebo nečiním toho dobrého, což chci, ale činím to zlé, čehož nechci.'),
(1574372,54,45,7,20,'A poněvadž pak, čehož já nechci, to činím, tedyť již ne já činím to, ale ten, kterýž přebývá ve mně, hřích.'),
(1574373,54,45,7,21,'Nalézám tedy takový při sobě zákon, když chci činiti dobré, že se mne přídrží zlé.'),
(1574374,54,45,7,22,'Nebo zvláštní libost mám v Zákoně Božím podle vnitřního člověka;'),
(1574375,54,45,7,23,'Ale vidím jiný zákon v údech svých, odporující zákonu mysli mé a jímající mne, tak abych byl vězeň zákona hřícha, kterýž jest v údech mých.'),
(1574376,54,45,7,24,'Bídný já člověk! Kdo mne vysvobodí z toho těla smrti?'),
(1574377,54,45,7,25,'Ale děkujiť Bohu skrze Jezukrista Pána našeho. A takžť já sloužím myslí Zákonu Božímu, ale tělem zákonu hřícha.'),
(1574378,54,45,8,1,'A protož neníť již žádného odsouzení těm, kteříž jsou v Kristu Ježíši, totiž nechodícím podle těla, ale podle Ducha.'),
(1574379,54,45,8,2,'Nebo zákon Ducha života v Kristu Ježíši, vysvobodil mne od zákona hřícha a smrti.'),
(1574380,54,45,8,3,'Nebo seč nemohl býti Zákon, byv mdlý pro tělo, Bůh poslav Syna svého v podobnosti těla hřícha, a to příčinou hřícha, odsoudil hřích na těle,'),
(1574381,54,45,8,4,'Aby spravedlnost Zákona vyplněna byla v nás, kteříž nechodíme podle těla, ale podle Ducha.'),
(1574382,54,45,8,5,'Ti zajisté, kteříž jsou podle těla živi, chutnají to, což jest těla, ale ti, kteříž jsou živi podle Ducha, oblibují to, což jest Ducha.'),
(1574383,54,45,8,6,'Nebo smýšlení těla jest smrt, smýšlení pak Ducha život a pokoj,'),
(1574384,54,45,8,7,'Protože smýšlení těla jest nepřátelské Bohu; nebo Zákonu Božímu není poddáno, a aniž hned může býti.'),
(1574385,54,45,8,8,'Protož ti, kteříž jsou v těle, Bohu se líbiti nemohou.'),
(1574386,54,45,8,9,'Vy pak nejste v těle, ale v Duchu, poněvadž Duch Boží přebývá v vás. Jestližeť pak kdo Ducha Kristova nemá, tenť není jeho.'),
(1574387,54,45,8,10,'A jest-liť Kristus v vás, tedy ač tělo umrtveno jest pro hřích, však duch živ jest pro spravedlnost.'),
(1574388,54,45,8,11,'Jestližeť pak Duch toho, kterýž vzkřísil Ježíše z mrtvých, přebývá v vás, ten, kterýž vzkřísil Krista z mrtvých, obživí i smrtelná těla vaše, pro přebývajícího Ducha jeho v vás.'),
(1574389,54,45,8,12,'A takž tedy, bratří, dlužníciť jsme ne tělu, abychom podle těla živi byli.'),
(1574390,54,45,8,13,'Nebo budete-li podle těla živi, zemřete; pakli byste Duchem skutky těla mrtvili, živi budete.'),
(1574391,54,45,8,14,'Nebo kteřížkoli Duchem Božím vedeni bývají, ti jsou synové Boží.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574392,54,45,8,15,'Nepřijali jste zajisté Ducha služby opět k bázni, ale přijali jste Ducha synovství, v němžto voláme Abba, totiž Otče.'),
(1574393,54,45,8,16,'A tenť Duch osvědčuje duchu našemu, že jsme synové Boží.'),
(1574394,54,45,8,17,'A jestliže synové, tedy i dědicové, dědicové zajisté Boží, spolu pak dědicové Kristovi, však tak, jestliže spolu s ním trpíme, abychom spolu i oslaveni byli.'),
(1574395,54,45,8,18,'Nebo tak za to mám, že nejsou rovná utrpení nynější oné budoucí slávě, kteráž se zjeviti má na nás.'),
(1574396,54,45,8,19,'Nebo pečlivé očekávání všeho stvoření očekává žádostivého zjevení synů Božích.'),
(1574397,54,45,8,20,'Marnosti zajisté poddáno jest stvoření, nechtě, ale pro toho, kterýž je poddal,'),
(1574398,54,45,8,21,'V naději, že i ono vysvobozeno bude od služby porušení a přivedeno v svobodu slávy synů Božích.'),
(1574399,54,45,8,22,'Nebo víme, že všecko stvoření spolu lká a spolu ku porodu pracuje až posavad,'),
(1574400,54,45,8,23,'A netoliko ono, ale i my, prvotiny Ducha mající, i myť také sami v sobě lkáme, zvolení synů Božích očekávajíce, a tak vykoupení těla našeho.'),
(1574401,54,45,8,24,'Nebo nadějí spaseni jsme. Naděje pak, kteráž se vidí, není naděje. Nebo což kdo vidí, proč by se toho nadál?'),
(1574402,54,45,8,25,'Pakli čehož nevidíme, toho se nadějeme, tedy toho skrze trpělivost očekáváme.'),
(1574403,54,45,8,26,'Ano také i Duch svatý pomocen jest mdlobám našim. Nebo zač bychom se měli modliti, jakž by náleželo, nevíme, ale ten Duch prosí za nás lkáními nevypravitelnými.'),
(1574404,54,45,8,27,'Ten pak, kterýž jest zpytatel srdcí, zná, jaký by byl smysl Ducha, že podle Boha prosí za svaté.'),
(1574405,54,45,8,28,'Vímeť pak, že milujícím Boha všecky věci napomáhají k dobrému, totiž těm, kteříž podle uložení jeho povoláni jsou.'),
(1574406,54,45,8,29,'Nebo kteréž předzvěděl, ty i předzřídil, aby byli připodobněni obrazu Syna jeho, aby tak on byl prvorozený mezi mnohými bratřími.'),
(1574407,54,45,8,30,'Kteréž pak předzřídil, těch i povolal, a kterýchž povolal, ty i ospravedlnil, a kteréž ospravedlnil, ty i oslavil.'),
(1574408,54,45,8,31,'Což tedy díme k tomu? Kdyžť jest Bůh s námi, i kdo proti nám?'),
(1574409,54,45,8,32,'Kterýž ani vlastnímu Synu svému neodpustil, ale za nás za všecky vydal jej, i kterakž by tedy nám s ním všech věcí nedal?'),
(1574410,54,45,8,33,'Kdo bude žalovati na vyvolené Boží? Bůh jest, jenž ospravedlňuje.'),
(1574411,54,45,8,34,'Kdo jest, ješto by je odsoudil? Kristus jest, kterýž umřel za ně, nýbrž i z mrtvých vstal, a kterýž i na pravici Boží jest, kterýž také i oroduje za nás.'),
(1574412,54,45,8,35,'A protož kdo nás odloučí od lásky Kristovy? Zdali zarmoucení, aneb úzkost, nebo protivenství? Zdali hlad, čili nahota? Zdali nebezpečenství, čili meč?'),
(1574413,54,45,8,36,'Jakož psáno jest: Pro tebe mrtveni býváme celý den, jmíni jsme jako ovce oddané k zabití.'),
(1574414,54,45,8,37,'Ale v tom ve všem udatně vítězíme, skrze toho, kterýž nás zamiloval.'),
(1574415,54,45,8,38,'Jist jsem zajisté, že ani smrt, ani život, ani andělé, ani knížatstvo, ani mocnosti, ani nastávající věci, ani budoucí,'),
(1574416,54,45,8,39,'Ani vysokost, ani hlubokost, ani kterékoli jiné stvoření, nebude moci nás odloučiti od lásky Boží, kteráž jest v Kristu Ježíši, Pánu našem.'),
(1574417,54,45,9,1,'Pravduť pravím v Kristu a neklamámť, čemuž i svědomí mé svědectví vydává v Duchu svatém,'),
(1574418,54,45,9,2,'Žeť mám veliký zámutek a ustavičnou bolest v srdci svém.'),
(1574419,54,45,9,3,'Nebo žádal bych já sám zavrženým býti od Krista místo bratří svých, totiž příbuzných svých podle těla.'),
(1574420,54,45,9,4,'Kteřížto jsou Izraelští, jejichžto jest přijetí za syny, i sláva, i smlouvy, i Zákona dání, i služba Boží, i zaslíbení.'),
(1574421,54,45,9,5,'Jejichž jsou i otcové, a ti, z nichžto jest Kristus podle těla, kterýž jest nade všecky Bůh požehnaný na věky. Amen.'),
(1574422,54,45,9,6,'Avšak nemůže zmařeno býti slovo Boží. Nebo ne všickni, kteříž jsou z Izraele, Izraelští jsou.'),
(1574423,54,45,9,7,'Aniž proto, že jsou símě Abrahamovo, hned také všickni jsou synové, ale v Izákovi nazváno bude tvé símě.'),
(1574424,54,45,9,8,'To jest, ne všickni ti, jenž jsou synové těla, jsou také synové Boží, ale kteříž jsou synové Božího zaslíbení, ti se počítají za símě.'),
(1574425,54,45,9,9,'Nebo toto jest slovo zaslíbení: V týž čas přijdu, a Sára bude míti syna.'),
(1574426,54,45,9,10,'A netoliko to, ale i Rebeka z jednoho počavši, totiž z Izáka, otce našeho, toho důvodem jest.'),
(1574427,54,45,9,11,'Nebo ještě před narozením obou těch synů, a prve nežli co dobrého nebo zlého učinili, aby uložení Boží, kteréžto jest podle vyvolení, a tak ne z skutků, ale z toho, jenž povolává, pevné bylo,'),
(1574428,54,45,9,12,'Řečeno jest jí: Větší sloužiti bude menšímu,'),
(1574429,54,45,9,13,'Jakož psáno jest: Jákoba jsem miloval, ale Ezau nenáviděl jsem.'),
(1574430,54,45,9,14,'I což tedy díme? Zdali nespravedlnost jest u Boha? Nikoli.'),
(1574431,54,45,9,15,'Nebo Mojžíšovi dí: Smiluji se nad tím, komuž milost učiním, a slituji se nad tím, nad kýmž se slituji.'),
(1574432,54,45,9,16,'A tak tedy neníť vyvolování na tom, jenž chce, ani na tom, jenž běží, ale na Bohu, jenž se smilovává.'),
(1574433,54,45,9,17,'Nebo dí Písmo faraonovi: Proto jsem vzbudil tebe, abych na tobě ukázal moc svou a aby rozhlášeno bylo jméno mé po vší zemi.'),
(1574434,54,45,9,18,'A tak tedy nad kýmž chce, smilovává se, a koho chce, zatvrzuje.'),
(1574435,54,45,9,19,'Ale díš mi: I pročež se pak hněvá? Nebo vůli jeho kdo odepřel?'),
(1574436,54,45,9,20,'Ale ó člověče, kdo jsi ty, že tak odpovídáš Bohu? Zdaž hrnec dí hrnčíři: Pročs mne tak udělal?'),
(1574437,54,45,9,21,'Zdaliž hrnčíř nemá moci nad hlinou, aby z jednostejného truple udělal jednu nádobu ke cti a jinou ku potupě?'),
(1574438,54,45,9,22,'Což pak divného, že Bůh, chtěje ukázati hněv a oznámiti moc svou, snášel ve mnohé trpělivosti nádoby hněvu, připravené k zahynutí.'),
(1574439,54,45,9,23,'A takž také, aby známé učinil bohatství slávy své při nádobách milosrdenství, kteréž připravil k slávě.'),
(1574440,54,45,9,24,'Kterýchžto i povolal, totiž nás, netoliko z Židů, ale také i z pohanů,'),
(1574441,54,45,9,25,'Jakož i skrze Ozé dí: Nazovu nelid můj lidem mým, a nemilou nazovu milou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574442,54,45,9,26,'A budeť na tom místě, kdež řečeno bylo jim: Nejste vy lid můj, tuť nazváni budou synové Boha živého.'),
(1574443,54,45,9,27,'Izaiáš pak volá nad Izraelem, řka: Byť pak byl počet synů Izraelských jako písek mořský, ostatkové toliko spaseni budou.'),
(1574444,54,45,9,28,'Nebo pohubení učiní spravedlivé, a to jisté, pohubení zajisté učiní Pán na zemi, a to jisté.'),
(1574445,54,45,9,29,'A jakož prve pověděl Izaiáš: Byť byl Pán zástupů nepozůstavil nám semene, jako Sodoma učiněni bychom byli, a Gomoře byli bychom podobni.'),
(1574446,54,45,9,30,'Což tedy díme? Že pohané, kteříž nenásledovali spravedlnosti, dosáhli spravedlnosti, a to spravedlnosti té, kteráž jest z víry;'),
(1574447,54,45,9,31,'Izrael pak následovav zákona spravedlnosti, k zákonu spravedlnosti nepřišel.'),
(1574448,54,45,9,32,'Proč? Nebo ne z víry, ale jako z skutků Zákona jí hledali. Urazili se zajisté o kámen urážky,'),
(1574449,54,45,9,33,'Jakož psáno jest: Aj, kladu na Sionu kámen urážky a skálu pohoršení, a každý, kdož uvěří v něj, nebude zahanben.'),
(1574450,54,45,10,1,'Bratří, příchylnost zajisté s zvláštní libostí srdce mého jestiť k Izraelovi, i modlitba za něj k Bohu, aby spasen byl.'),
(1574451,54,45,10,2,'Neboť jim svědectví vydávám, žeť horlivost Boží mají, ale ne podle umění.'),
(1574452,54,45,10,3,'Nebo neznajíce Boží spravedlnosti, a svou vlastní spravedlnost hledajíce vystaviti, spravedlnosti Boží nebyli poddáni.'),
(1574453,54,45,10,4,'Nebo konec Zákona jest Kristus k ospravedlnění všelikému věřícímu.'),
(1574454,54,45,10,5,'Nebo Mojžíš píše o spravedlnosti, kteráž jest z Zákona, pravě: Který by koli člověk činil ty věci, živ bude v nich.'),
(1574455,54,45,10,6,'Ta pak spravedlnost, kteráž jest z víry, takto praví: Neříkej v srdci svém: Kdo vstoupí na nebe? To jest Krista s výsosti svésti.'),
(1574456,54,45,10,7,'Aneb kdo sstoupí do propasti? To jest Krista z mrtvých vzbuditi.'),
(1574457,54,45,10,8,'Ale co dí spravedlnost z víry? Blízko tebe jestiť slovo, v ústech tvých a v srdci tvém. A toť jest slovo to víry, kteréž kážeme,'),
(1574458,54,45,10,9,'Totiž, vyznáš-li ústy svými Pána Ježíše a srdcem svým uvěříš-li, že jej Bůh vzkřísil z mrtvých, spasen budeš.'),
(1574459,54,45,10,10,'Nebo srdcem se věří k spravedlnosti, ale ústy vyznání děje se k spasení.'),
(1574460,54,45,10,11,'Nebo dí Písmo: Všeliký, kdož věří v něj, nebude zahanben.'),
(1574461,54,45,10,12,'Neníť zajisté rozdílu mezi Židem a Řekem; nebo tentýž Pán všech, bohatý jest ke všem vzývajícím jej.'),
(1574462,54,45,10,13,'Každý zajisté, kdožkoli vzýval by jméno Páně, spasen bude.'),
(1574463,54,45,10,14,'Ale kterak budou vzývati toho, v kteréhož neuvěřili? A kterak uvěří tomu, o němž neslyšeli? A kterak uslyší bez kazatele?'),
(1574464,54,45,10,15,'A kterak kázati budou, jestliže nebudou posláni? Jakož psáno jest: Aj, jak krásné nohy zvěstujících pokoj, zvěstujících dobré věci.'),
(1574465,54,45,10,16,'Ale ne všickni uposlechli evangelium. Nebo Izaiáš praví: Pane, kdo uvěřil kázání našemu?'),
(1574466,54,45,10,17,'Tedy víra z slyšení, a slyšení skrze slovo Boží.'),
(1574467,54,45,10,18,'Ale pravímť: Zdaliž jsou neslyšeli? Anobrž po vší zemi rozšel se zvuk jejich a až do končin okršlku země slova jejich.'),
(1574468,54,45,10,19,'Ale pravím: Zdaliž nepoznal Izrael toho? Ano první z nich Mojžíš řekl: Já k závisti vás přivedu skrze národ ten, kteréhož nemáte za lid můj; skrze lid nemoudrý k hněvu popudím vás.'),
(1574469,54,45,10,20,'A Izaiáš směle dí: Nalezen jsem od těch, kteříž mne nehledali; zjeven jsem těm, kteříž se na mne neptali.'),
(1574470,54,45,10,21,'Ale proti lidu Izraelskému dí: Přes celý den roztahoval jsem ruce své k lidu nepovolnému a protivnému.'),
(1574471,54,45,11,1,'Protož pravím: Zdali jest Bůh zavrhl lid svůj? Nikoli; nebo i já Izraelský jsem, z semene Abrahamova, z pokolení Beniaminova.'),
(1574472,54,45,11,2,'Nezavrhlť jest Bůh lidu svého, kterýž předzvěděl. Zdali nevíte, co Písmo praví o Eliášovi? Kterak se modlí Bohu proti lidu Izraelskému řka:'),
(1574473,54,45,11,3,'Pane, proroky tvé zmordovali a oltáře tvé rozkopali, já pak zůstal jsem sám, a i méť duše hledají.'),
(1574474,54,45,11,4,'Ale co jemu dí odpověd Boží? Pozůstavil jsem sobě sedm tisíců mužů, kteříž neskláněli kolen před Bálem.'),
(1574475,54,45,11,5,'Takť i nyní ostatkové podle vyvolení jdoucího z pouhé milosti Boží zůstali,'),
(1574476,54,45,11,6,'A poněvadž z milosti, tedy ne z skutků, sic jinak milost již by nebyla milost. Pakli z skutků, tedy již není milost, jinak skutek nebyl by skutek.'),
(1574477,54,45,11,7,'Což tedy? Čeho hledá Izrael, toho jest nedošel, ale vyvolení došli toho, jiní pak zatvrzeni jsou,'),
(1574478,54,45,11,8,'(Jakož psáno jest: Dal jim Bůh ducha zkormoucení, oči, aby neviděli, a uši, aby neslyšeli,) až do dnešního dne.'),
(1574479,54,45,11,9,'A David dí: Budiž jim stůl jejich osidlem a pastmi a pohoršením i spravedlivým odplacením.'),
(1574480,54,45,11,10,'Zatmětež se oči jejich, ať nevidí, a hřbet jejich vždycky shýbej.'),
(1574481,54,45,11,11,'A z toho pravím: Tak-liž jsou pak Židé klesli, aby docela padli? Nikoli, ale jejich klesnutím spasení přiblížilo se pohanům, aby je tak Bůh k závidění přivedl.'),
(1574482,54,45,11,12,'A poněvadž pak jejich pád jest bohatství světa a zmenšení jejich jest bohatství pohanů, čím více plnost jich?'),
(1574483,54,45,11,13,'Vámť zajisté pravím pohanům, jelikož jsem já apoštol pohanský, přisluhování mé oslavuji,'),
(1574484,54,45,11,14,'Zda bych jak k závidění vzbuditi mohl ty, jenž jsou tělo mé, a k spasení přivésti aspoň některé z nich.'),
(1574485,54,45,11,15,'Nebo kdyžť zavržení jich jest smíření světa, co pak bude zase jich přijetí, než život z mrtvých?'),
(1574486,54,45,11,16,'Poněvadž prvotiny svaté jsou, takéť svaté jest i těsto; a jest-liť kořen svatý, tedy i ratolesti.'),
(1574487,54,45,11,17,'Žeť jsou pak některé ratolesti vylomeny, a ty, byv planou olivou, vštípen jsi místo nich a učiněn jsi účastník kořene i tučnosti olivy.'),
(1574488,54,45,11,18,'Proto ty se nechlub proti ratolestem. Pakli se chlubíš, věz, že ne ty kořen neseš, ale kořen tebe.'),
(1574489,54,45,11,19,'Pakli díš: Vylomeny jsou ratolesti, abych já byl vštípen,'),
(1574490,54,45,11,20,'Dobře pravíš. Pro nevěru vylomeny jsou, ale ty věrou stojíš. Nebudiž vysokomyslný, ale boj se.'),
(1574491,54,45,11,21,'Nebo poněvadž Bůh ratolestem přirozeným neodpustil, věz, žeť by ani tobě neodpustil.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574492,54,45,11,22,'A protož viz dobrotivost i zuřivost Boží. K těm zajisté, kteříž padli, zuřivost, ale k tobě dobrotivost, ač budeš-li trvati v dobrotě. Sic jinak i ty vyťat budeš.'),
(1574493,54,45,11,23,'Ano i oni, jestliže nezůstanou v nevěře, zase vštípeni budou. Mocenť jest zajisté Bůh zase vštípiti je.'),
(1574494,54,45,11,24,'Nebo poněvadž ty vyťat jsi z přirozené plané olivy a proti přirození vštípen jsi v dobrou olivu, čím více pak ti, kteříž podle přirození jsou z dobré olivy, vštípeni budou v svou vlastní olivu.'),
(1574495,54,45,11,25,'Neboť nechci, bratří, abyste nevěděli tohoto tajemství, (abyste nebyli sami u sebe moudří,) že zatvrdilost tato zčástky přihodila se Izraelovi, dokudž by nevešla plnost pohanů.'),
(1574496,54,45,11,26,'A takť všecken Izrael spasen bude, jakož psáno jest: Přijde z Siona vysvoboditel a odvrátíť bezbožnosti od Jákoba.'),
(1574497,54,45,11,27,'A tatoť bude smlouva má s nimi, když shladím hříchy jejich.'),
(1574498,54,45,11,28,'A tak s strany evangelium jsouť nepřátelé pro vás, ale podle vyvolení jsou milí pro otce svaté.'),
(1574499,54,45,11,29,'Darů zajisté svých a povolání Bůh nelituje.'),
(1574500,54,45,11,30,'Nebo jakož i vy někdy jste nebyli poslušni Boha, ale nyní milosrdenství jste došli pro jejich nevěru,'),
(1574501,54,45,11,31,'Tak i oni nyní neuposlechli, aby pro učiněné vám milosrdenství i oni také milosrdenství dosáhli.'),
(1574502,54,45,11,32,'Zavřel zajisté Bůh všecky v nevěře, aby se nade všemi smiloval.'),
(1574503,54,45,11,33,'Ó hlubokosti bohatství i moudrosti i umění Božího! Jak jsou nezpytatelní soudové jeho a nevystižitelné cesty jeho!'),
(1574504,54,45,11,34,'Nebo kdo jest poznal mysl Páně? Aneb kdo jemu radil?'),
(1574505,54,45,11,35,'Nebo kdo prve dal jemu, a budeť mu odplaceno?'),
(1574506,54,45,11,36,'Nebo z něho a skrze něho a v něm jsou všecky věci, jemuž sláva na věky. Amen.'),
(1574507,54,45,12,1,'Protož prosím vás, bratří, skrze milosrdenství Boží, abyste vydávali těla svá v obět živou, svatou, Bohu libou, rozumnou službu vaši.'),
(1574508,54,45,12,2,'A nepřipodobňujte se světu tomuto, ale proměňtež se obnovením mysli vaší, tak abyste zkusili, jaká by byla vůle Boží dobrá, libá a dokonalá.'),
(1574509,54,45,12,3,'Neboť pravím (skrze milost, kteráž dána jest mi,) každému z těch, jenž jsou mezi vámi, aby ne více smyslil, než sluší smysliti, ale aby smyslil v středmosti, tak jakž jednomu každému Bůh udělil míru víry.'),
(1574510,54,45,12,4,'Nebo jakož v jednom těle mnohé údy máme, ale nemají všickni údové jednostejného díla,'),
(1574511,54,45,12,5,'Tak mnozí jedno tělo jsme v Kristu, a obzvláštně jedni druhých údové.'),
(1574512,54,45,12,6,'Ale majíce obdarování rozdílná podle milosti, kteráž dána jest nám, buďto proroctví, kteréž ať jest podle pravidla víry;'),
(1574513,54,45,12,7,'Buďto úřad, v bedlivém přisluhování; buďto ten, jenž učí, v vyučování.'),
(1574514,54,45,12,8,'Též kdo napomíná, v napomínání; ten, jenž rozdává, dávej v upřímnosti; kdož jiným předložen jest, konej úřad svůj s pilností; kdo milosrdenství činí, s ochotností.'),
(1574515,54,45,12,9,'Milování buď bez pokrytství; v ošklivosti mějte zlé, připojeni jsouce k dobrému.'),
(1574516,54,45,12,10,'Láskou bratrskou jedni k druhým nakloněni jsouce, uctivostí se vespolek předcházejte,'),
(1574517,54,45,12,11,'V pracech neleniví, duchem vroucí, příhodnosti času šetřící,'),
(1574518,54,45,12,12,'Nadějí se radující, v souženích trpěliví, na modlitbě ustaviční,'),
(1574519,54,45,12,13,'V potřebách s svatými se sdělující, přívětivosti k hostem následující.'),
(1574520,54,45,12,14,'Dobrořečte protivníkům vašim, dobrořečte, pravím, a nezlořečte.'),
(1574521,54,45,12,15,'Radujte s radujícími, a plačte s plačícími.'),
(1574522,54,45,12,16,'Buďte vespolek jednomyslní, ne vysoce o sobě smýšlejíce, ale k nízkým se nakloňujíce.'),
(1574523,54,45,12,17,'Nebuďte opatrní sami u sebe. Žádnému zlého za zlé neodplacujte, opatrujíce dobré přede všemi lidmi,'),
(1574524,54,45,12,18,'Jestliže jest možné, pokudž na vás jest, se všemi lidmi pokoj majíce,'),
(1574525,54,45,12,19,'Ne sami sebe mstíce, nejmilejší, ale dejte místo hněvu; nebo psáno jest: Mně pomsta, já odplatím, praví Pán.'),
(1574526,54,45,12,20,'A protož lační-li nepřítel tvůj, nakrm jej, a žízní-li, dej mu píti. Nebo to učině, uhlí řeřavé shrneš na hlavu jeho.'),
(1574527,54,45,12,21,'Nedej se přemoci zlému, ale přemáhej v dobrém zlé.'),
(1574528,54,45,13,1,'Každá duše vrchnostem povýšeným poddána buď. Neboť není vrchnosti, jediné od Boha, a kteréž vrchnosti jsou, ty od Boha zřízené jsou.'),
(1574529,54,45,13,2,'A protož, kdož se vrchnosti protiví, Božímu zřízení se protiví; kteříž se pak protiví, tiť sobě odsouzení dobudou.'),
(1574530,54,45,13,3,'Nebo vrchnosti nejsou k strachu dobře činícím, ale zle činícím. Protož chceš-li se nebáti vrchnosti, čiň dobře, a budeš míti chválu od ní.'),
(1574531,54,45,13,4,'Boží zajisté služebník jest, tobě k dobrému. Pakli bys zle činil, boj se; neboť ne nadarmo nese meč. Boží zajisté služebník jest, mstitel zuřivý nad tím, kdož zle činí.'),
(1574532,54,45,13,5,'A protož musejíť vrchnostem všickni poddáni býti, netoliko pro hněv, ale i pro svědomí.'),
(1574533,54,45,13,6,'Nebo proto i daň dáváte, poněvadž služebníci Boží jsou, pilnou práci o to vedouce.'),
(1574534,54,45,13,7,'Každému tedy což jste povinni, dávejte. Komu daň, tomu daň; komu clo, tomu clo; komu bázeň, tomu bázeň; komu čest, tomu čest.'),
(1574535,54,45,13,8,'Žádnému nebývejte nic dlužni, než to, abyste se vespolek milovali. Nebo kdož miluje bližního, Zákon naplnil,'),
(1574536,54,45,13,9,'Poněvadž to přikázání: Nesesmilníš, nezabiješ, neukradneš, nepromluvíš křivého svědectví, nepožádáš, a jest-li které jiné přikázání, v tomto slovu se zavírá: Milovati budeš bližního svého jako sebe samého.'),
(1574537,54,45,13,10,'Láska bližnímu zle neučiní, a protož plnost Zákona jestiť láska.'),
(1574538,54,45,13,11,'A zvláště pak vidouce takovou příhodnost, žeť jest se nám již čas ze sna probuditi. (Nyníť zajisté blíže nás jest spasení, nežli když jsme uvěřili.)'),
(1574539,54,45,13,12,'Noc pominula, ale den se přiblížil. Odvrzmež tedy skutky temnosti, a oblecme se v odění světla.'),
(1574540,54,45,13,13,'Jakožto ve dne poctivě choďme, ne v hodování a v opilství, ne v smilstvích a v chlipnostech, ne v sváru a v závisti,'),
(1574541,54,45,13,14,'Ale oblecte se v Pána Jezukrista, a nepečujte o tělo k vyplňování žádostí jeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574542,54,45,14,1,'Mdlého pak u víře přijímejte, ne k hádkám o nepotřebných otázkách.'),
(1574543,54,45,14,2,'Nebo někdo věří, že může jísti všecko; jiný pak u víře mdlý jsa, jí zelinu.'),
(1574544,54,45,14,3,'Ten, kdož jí, nepokládej sobě za nic toho, kdož nejí; a kdo nejí, toho nesuď, kdož jí. Nebo Bůh přijal jej.'),
(1574545,54,45,14,4,'Ty kdo jsi, abys soudil cizího služebníka? Však Pánu svému stojí, anebo padá. Staneť pak; mocen jest zajisté Bůh utvrditi jej.'),
(1574546,54,45,14,5,'Nebo někdo rozsuzuje mezi dnem a dnem, a někdo soudí každý den jednostejný býti. Jeden každý v svém smyslu ujištěn buď.'),
(1574547,54,45,14,6,'Kdož dnů šetří, Pánu šetří; a kdo nešetří, Pánu nešetří. A kdo jí, Pánu jí, nebo děkuje Bohu; a kdož nejí, Pánu nejí, a děkuje Bohu.'),
(1574548,54,45,14,7,'Žádný zajisté z nás není sám sobě živ, a žádný sobě sám neumírá.'),
(1574549,54,45,14,8,'Nebo buďto že jsme živi, Pánu živi jsme; buďto že mřeme, Pánu mřeme. A tak buď že jsme živi, buď že umíráme, Páně jsme.'),
(1574550,54,45,14,9,'Na toť jest zajisté Kristus i umřel, i z mrtvých vstal, i ožil, aby nad živými i nad mrtvými panoval.'),
(1574551,54,45,14,10,'Ty pak proč odsuzuješ bratra svého? Anebo také ty proč za nic pokládáš bratra svého? Však všickni staneme před stolicí Kristovou.'),
(1574552,54,45,14,11,'Psáno jest zajisté: Živť jsem já, praví Pán, žeť přede mnou bude klekati každé koleno, a každý jazyk vyznávati bude Boha.'),
(1574553,54,45,14,12,'A takť jeden každý z nás sám za sebe počet vydávati bude Bohu.'),
(1574554,54,45,14,13,'Nesuďmež tedy více jedni druhých, ale toto raději rozsuzujte, jak byste nekladli úrazu nebo pohoršení bratru.'),
(1574555,54,45,14,14,'Vím a v tom ujištěn jsem v Pánu Ježíši, žeť nic nečistého není samo z sebe; než tomu, kdož tak soudí, že by nečisté bylo, jemuť nečisté jest.'),
(1574556,54,45,14,15,'Ale bývá-liť rmoucen bratr tvůj pro pokrm, již nechodíš podle lásky. Hlediž, abys k zahynutí nepřivedl pokrmem svým toho, za kteréhož Kristus umřel.'),
(1574557,54,45,14,16,'Nebudiž tedy v porouhání dáno dobré vaše.'),
(1574558,54,45,14,17,'Království zajisté Boží není pokrm a nápoj, ale spravedlnost a pokoj a radost v Duchu svatém.'),
(1574559,54,45,14,18,'Nebo kdož v tom slouží Kristu, milý jest Bohu a lidem příjemný.'),
(1574560,54,45,14,19,'Protož následujme toho, což by sloužilo ku pokoji a k vzdělání vespolek.'),
(1574561,54,45,14,20,'Nekaziž pro pokrm díla Božího. Všecko zajisté čisté jest, ale zlé jest člověku, kterýž jí s pohoršením.'),
(1574562,54,45,14,21,'Dobré jest nejísti masa a nepíti vína, ani čehokoli toho, na čemž se uráží bratr tvůj, nebo horší, anebo zemdlívá.'),
(1574563,54,45,14,22,'Ty víru máš? Mějž ji sám u sebe před Bohem. Blahoslavený, kdož nesoudí sebe samého v tom, což oblibuje.'),
(1574564,54,45,14,23,'Ale kdož pak rozpakuje se, kdyby jedl, odsouzen jest, nebo ne z víry jí. A cožkoli není z víry, hřích jest.'),
(1574565,54,45,15,1,'Povinniť jsme pak my silní mdloby nemocných snášeti, a ne sami sobě se líbiti.'),
(1574566,54,45,15,2,'Ale jeden každý z nás bližnímu se lib k dobrému pro vzdělání.'),
(1574567,54,45,15,3,'Nebo i Kristus ne sám se sobě líbil, ale jakož psáno jest: Hanění hanějících tebe připadla jsou na mne.'),
(1574568,54,45,15,4,'Nebo kteréžkoli věci napsány jsou, k našemu naučení napsány jsou, abychom skrze trpělivost a potěšení Písem naději měli.'),
(1574569,54,45,15,5,'Bůh pak dárce trpělivosti a potěšení dejž vám jednomyslným býti vespolek podle Jezukrista,'),
(1574570,54,45,15,6,'Abyste jednomyslně jedněmi ústy oslavovali Boha a Otce Pána našeho Jezukrista.'),
(1574571,54,45,15,7,'Protož přijímejte se vespolek, jakož i Kristus přijal nás v slávu Boží.'),
(1574572,54,45,15,8,'Neboť pravím vám, že Kristus Ježíš byl služebníkem obřízky pro Boží pravost, aby potvrzeni byli slibové otcům učinění,'),
(1574573,54,45,15,9,'A aby pohané z milosrdenství slavili Boha, jakož psáno jest: Protož vyznávati tebe budu mezi pohany, a jménu tvému plésati budu.'),
(1574574,54,45,15,10,'A opět dí: Veselte se pohané s lidem jeho.'),
(1574575,54,45,15,11,'A opět: Chvalte Hospodina všickni národové, a velebtež ho všickni lidé.'),
(1574576,54,45,15,12,'A opět Izaiáš dí: Budeť kořen Jesse, a ten, jenž povstane, panovati nad pohany; v němť pohané doufati budou.'),
(1574577,54,45,15,13,'Bůh pak naděje naplňujž vás všelikou radostí a pokojem u víře, tak abyste se rozhojnili v naději skrze moc Ducha svatého.'),
(1574578,54,45,15,14,'Vím zajisté, bratří moji, i já také o vás, že i vy jste plní dobroty, naplněni jsouce všelikou známostí, takže se i napomínati můžete vespolek.'),
(1574579,54,45,15,15,'Ale však proto psal jsem vám, bratří, poněkud směle, jako ku paměti přivodě vám, podle milosti, kteráž jest mi dána od Boha,'),
(1574580,54,45,15,16,'K tomu, abych byl služebníkem Ježíše Krista mezi pohany, slouže evangelium Božímu, aby byla obět pohanů vzácná, posvěcena jsuci skrze Ducha svatého.'),
(1574581,54,45,15,17,'Mám se tedy čím chlubiti v Kristu Ježíši, v Božích věcech.'),
(1574582,54,45,15,18,'Neboť bych se neodvážil mluviti toho, čehož by skrze mne neučinil Kristus, k tomu, aby ku poslušenství přivedeni byli pohané slovem i skutkem,'),
(1574583,54,45,15,19,'V moci divů a zázraků, v síle Ducha Božího, takže jsem od Jeruzaléma vůkol až k Ilyrické zemi naplnil evangelium Kristovým,'),
(1574584,54,45,15,20,'A to tak žádostiv jsa kázati evangelium, kdež ani jmenován nebyl Kristus, abych na cizí základ nestavěl,'),
(1574585,54,45,15,21,'Ale jakož psáno jest: Kterýmž není zvěstováno o něm, uzří, a ti, jenž neslýchali, srozumějí.'),
(1574586,54,45,15,22,'A tímť jest mi mnohokrát překaženo přijíti k vám.'),
(1574587,54,45,15,23,'Nyní pak nemaje již více místa v těchto krajinách a žádost maje přijíti k vám od mnoha let,'),
(1574588,54,45,15,24,'Kdyžkoli půjdu do Hišpanie, přijdu k vám. Mámť zajisté naději, že tudy jda, uzřím vás, a že vy mne provodíte tam, avšak až bych prve u vás poněkud pobyl.'),
(1574589,54,45,15,25,'Nyní pak beru se do Jeruzaléma, službu čině svatým.'),
(1574590,54,45,15,26,'Nebo za dobré se vidělo Macedonským a Achaiským, aby sbírku nějakou učinili na chudé svaté, kteříž jsou v Jeruzalémě.'),
(1574591,54,45,15,27,'Takť sobě to oblíbili, a také povinni jsou jim to. Nebo poněvadž duchovních věcí jejich byli účastni pohané, povinniť jsou jim také sloužiti tělesnými.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574592,54,45,15,28,'A protož když to vykonám a jim odvedu užitek ten, půjduť skrze vás do Hišpanie.'),
(1574593,54,45,15,29,'A vímť, že přijda k vám, v hojnosti požehnání evangelium Kristova přijdu.'),
(1574594,54,45,15,30,'Prosímť pak vás, bratří, skrze Pána našeho Jezukrista a skrze lásku Ducha svatého, abyste spolu se mnou modlili se za mne Bohu snažně,'),
(1574595,54,45,15,31,'Abych vysvobozen byl od protivníků, kteříž jsou v Judstvu a aby služba tato má příjemná byla svatým v Jeruzalémě,'),
(1574596,54,45,15,32,'Abych k vám bohdá s radostí přišel, a s vámi poodpočinul.'),
(1574597,54,45,15,33,'Bůh pak pokoje budiž se všemi vámi. Amen.'),
(1574598,54,45,16,1,'Poroučímť pak vám Fében, sestru naši, služebnici církve Cenchrenské,'),
(1574599,54,45,16,2,'Abyste ji přijali v Pánu, tak jakž sluší na svaté, a abyste jí pomocni byli, jestliže by vás v čem potřebovala. Nebo i ona mnohým hostem ochotně posluhovala, až i mně také.'),
(1574600,54,45,16,3,'Pozdravte Priscilly a Akvila, pomocníků mých v Kristu Ježíši,'),
(1574601,54,45,16,4,'Kteříž pro můj život svých vlastních hrdel nasadili, jimžto ne já sám toliko děkuji, ale i všecky církve pohanské,'),
(1574602,54,45,16,5,'I domácího jejich shromáždění. Pozdravte mého milého Epéneta, kterýž jest prvotiny Achaie v Kristu.'),
(1574603,54,45,16,6,'Pozdravte Marie, kteráž mnoho práce měla s námi.'),
(1574604,54,45,16,7,'Pozdravte Andronika a Junia, příbuzných mých a spoluvězňů mých, kteříž jsou vzácní u apoštolů a kteříž přede mnou byli v Kristu Ježíši.'),
(1574605,54,45,16,8,'Pozdravte Amplia mně v Pánu milého.'),
(1574606,54,45,16,9,'Pozdravte Urbana, pomocníka našeho v Kristu, a Stachyna mého milého.'),
(1574607,54,45,16,10,'Pozdravte Apella zkušeného v Kristu. Pozdravte těch, kteříž jsou z domu Aristobulova.'),
(1574608,54,45,16,11,'Pozdravte Herodiona, příbuzného mého. Pozdravte těch, kteří jsou z čeledi Narciškovy věřící v Pána.'),
(1574609,54,45,16,12,'Pozdravte Tryfény a Tryfózy, kteréž práci vedou v Pánu. Pozdravte Persidy milé, kteráž mnoho pracovala v Pánu.'),
(1574610,54,45,16,13,'Pozdravte Rufa, zvláštního v Pánu, a matky jeho i mé.'),
(1574611,54,45,16,14,'Pozdravte Asynkrita, Flegonta, Hermy, Patroba, Merkuria, i jiných bratří, kteříž jsou s nimi.'),
(1574612,54,45,16,15,'Pozdravte Filologa i Julie, Nerea a sestry jeho, i Olympa i všech svatých, kteříž jsou s nimi.'),
(1574613,54,45,16,16,'Pozdravte sebe vespolek v políbení svatém. Pozdravujíť vás církve Kristovy.'),
(1574614,54,45,16,17,'Prosímť pak vás, bratří, abyste šetřili těch, kteříž různice a pohoršení činí, naodpor učení tomu, kterémuž jste vy se naučili, a varujte se jich.'),
(1574615,54,45,16,18,'Nebo takoví Pánu našemu Ježíši Kristu neslouží, ale svému břichu; a skrze lahodné řeči a pochlebenství svodí srdce prostých.'),
(1574616,54,45,16,19,'Nebo vaše poslušenství všechněch došlo. A protož se raduji z vás. Než chciť, abyste byli moudří k dobrému, a prostí k zlému.'),
(1574617,54,45,16,20,'Bůh pak pokoje potře satana pod nohy vaše brzo. Milost Pána našeho Jezukrista budiž s vámi. Amen.'),
(1574618,54,45,16,21,'Pozdravují vás Timoteus, pomocník můj, a Lucius, a Jázon, a #Sozipater, příbuzní moji.'),
(1574619,54,45,16,22,'Pozdravuji vás v Pánu já Tercius, kterýž jsem psal tento list.'),
(1574620,54,45,16,23,'Pozdravuje vás Gáius, hospodář můj i vší církve. Pozdravuje vás Erastus, důchodní písař městský, a Kvartus bratr.'),
(1574621,54,45,16,24,'Milost Pána našeho Jezukrista se všemi vámi. Amen.'),
(1574622,54,45,16,25,'Tomu pak, jenž může vás utvrditi podle evangelium mého a kázání Ježíše Krista, podle zjevení tajemství od časů věčných skrytého,'),
(1574623,54,45,16,26,'Nyní pak zjeveného i skrze Písma prorocká, podle poručení věčného Boha, ku poslušenství víry všechněm národům oznámeného,'),
(1574624,54,45,16,27,'Tomu, pravím, samému moudrému Bohu sláva skrze Jezukrista na věky. Amen List tento k Římanům psán jest z Korintu, a poslán po Fében, služebnici sboru Cenchrenského.'),
(1574625,54,46,1,1,'Pavel, povolaný apoštol Ježíše Krista, skrze vůli Boží, a bratr Sostenes,'),
(1574626,54,46,1,2,'Církvi Boží, kteráž jest v Korintu, posvěceným v Kristu Ježíši, povolaným svatým, spolu se všemi, kteříž vzývají jméno Pána našeho Jezukrista na všelikém místě, i jejich i našem:'),
(1574627,54,46,1,3,'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.'),
(1574628,54,46,1,4,'Děkuji Bohu svému vždycky za vás pro tu milost Boží, kteráž dána jest vám v Kristu Ježíši,'),
(1574629,54,46,1,5,'Že ve všem obohaceni jste v něm, v každém slovu a ve všelikém umění,'),
(1574630,54,46,1,6,'Jakož svědectví Kristovo upevněno jest mezi vámi,'),
(1574631,54,46,1,7,'Takže nemáte žádného nedostatku ve všeliké milosti, očekávajíce zjevení Pána našeho Jezukrista,'),
(1574632,54,46,1,8,'Kterýžto i utvrdí vás až do konce bez úhony ke dni příští Pána našeho Jezukrista.'),
(1574633,54,46,1,9,'Věrnýť jest Bůh, skrze něhož povoláni jste k účastenství Syna jeho Jezukrista, Pána našeho.'),
(1574634,54,46,1,10,'Prosímť vás pak, bratří, skrze jméno Pána našeho Jezukrista, abyste jednostejně mluvili všickni a aby nebylo mezi vámi roztržek, ale buďte spojeni jednostejnou myslí a jednostejným smyslem.'),
(1574635,54,46,1,11,'Nebo oznámeno jest mi o vás, bratří moji, od některých z čeledi Chloe, že by mezi vámi byly různice.'),
(1574636,54,46,1,12,'Míním pak toto, že jeden každý z vás říká: Já jsem Pavlův, já Apollův, já Petrův, já pak Kristův.'),
(1574637,54,46,1,13,'Zdali rozdělen jest Kristus? Zdali Pavel ukřižován jest za vás? Anebo zdali jste ve jménu Pavlovu pokřtěni byli?'),
(1574638,54,46,1,14,'Děkuji Bohu, že jsem žádného z vás nekřtil, než Krispa a Gáia,'),
(1574639,54,46,1,15,'Aby někdo neřekl, že jsem ve jméno své křtil.'),
(1574640,54,46,1,16,'Křtilť jsem také i Štěpánovu čeled. Více nevím, abych koho jiného křtil.'),
(1574641,54,46,1,17,'Nebo neposlal mne Kristus křtíti, ale evangelium kázati, ne v moudrosti řeči, aby nebyl vyprázdněn kříž Kristův.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574642,54,46,1,18,'Nebo slovo kříže těm, kteříž hynou, bláznovstvím jest, ale nám, kteříž spasení dosahujeme, moc Boží jest.'),
(1574643,54,46,1,19,'Nebo psáno jest: Zahladím moudrost moudrých, a opatrnost opatrných zavrhu.'),
(1574644,54,46,1,20,'Kde jest moudrý? A kde učený? A kde chytrák tohoto světa? Zdaliž Bůh neobrátil moudrosti tohoto světa v bláznovství?'),
(1574645,54,46,1,21,'Nebo když v moudrosti Boží svět nepoznal skrze moudrost Boha, zalíbilo se Bohu skrze bláznové kázaní spasiti věřící,'),
(1574646,54,46,1,22,'Poněvadž i Židé zázraků žádají, i Řekové hledají moudrosti.'),
(1574647,54,46,1,23,'Myť pak kážeme Krista ukřižovaného, Židům zajisté pohoršení, a Řekům bláznovství,'),
(1574648,54,46,1,24,'Ale povolaným, i Židům i Řekům, Krista, Boží moc a Boží moudrost.'),
(1574649,54,46,1,25,'Nebo to bláznovství Boží jest moudřejší nežli lidé a mdloba Boží jest silnější než lidé.'),
(1574650,54,46,1,26,'Vidíte zajisté povolání vaše, bratří, že nemnozí moudří podle těla, nemnozí mocní, nemnozí urození;'),
(1574651,54,46,1,27,'Ale což bláznivého jest u světa, to sobě vyvolil Bůh, aby zahanbil moudré, a to, což jest u světa mdlé, Bůh vyvolil, aby zahanbil silné.'),
(1574652,54,46,1,28,'A neurozené u světa a za nic položené vyvolil Bůh, ano hned, kteréž nejsou, aby ty věci, kteréž jsou, zkazil,'),
(1574653,54,46,1,29,'Proto aby se nechlubilo před obličejem jeho žádné tělo.'),
(1574654,54,46,1,30,'Vy pak jste z něho v Kristu Ježíši, kterýž učiněn jest nám moudrost od Boha, i spravedlnost, i posvěcení, i #vykoupení,'),
(1574655,54,46,1,31,'Aby se tak dálo, jakož jest napsáno: Kdo se chlubí, v Pánu se chlub.'),
(1574656,54,46,2,1,'I já přišed k vám, bratří, nepřišel jsem s důstojností řeči nebo moudrostí, zvěstuje vám svědectví Boží.'),
(1574657,54,46,2,2,'Nebo tak jsem usoudil nic jiného neuměti mezi vámi, nežli Ježíše Krista, a to ještě toho ukřižovaného.'),
(1574658,54,46,2,3,'A byl jsem já u vás v mdlobě, a v bázni, i v strachu mnohém.'),
(1574659,54,46,2,4,'A řeč má a kázaní mé nebylo v slibných lidské moudrosti řečech, ale v dokázání Ducha svatého a moci,'),
(1574660,54,46,2,5,'Aby víra vaše nebyla založena v moudrosti lidské, ale v moci Boží.'),
(1574661,54,46,2,6,'Moudrost pak mluvíme mezi dokonalými, ale moudrost ne tohoto světa, ani knížat světa tohoto, jenž hynou.'),
(1574662,54,46,2,7,'Ale mluvíme moudrost Boží v tajemství, kterážto skryta jest, kterouž Bůh předuložil před věky k slávě naší,'),
(1574663,54,46,2,8,'Jížto žádný z knížat světa tohoto nepoznal. Nebo kdyby byli poznali, nebyliť by Pána slávy ukřižovali.'),
(1574664,54,46,2,9,'Ale kážeme, jakož psáno jest: Čehož oko nevídalo, ani ucho slýchalo, ani na srdce lidské vstoupilo, co jest připravil Bůh těm, kteříž jej milují.'),
(1574665,54,46,2,10,'Nám pak Bůh zjevil skrze Ducha svého. Nebo Duch zpytuje všecky věci, i hlubokosti Božské.'),
(1574666,54,46,2,11,'Nebo kdo z lidí ví, co jest v člověku, jediné duch člověka, kterýž jest v něm? Takť i Božích věcí nezná žádný, jediné Duch Boží.'),
(1574667,54,46,2,12,'My pak nepřijali jsme ducha světa, ale Ducha toho, kterýž jest z Boha, abychom věděli, které věci od Boha darovány jsou nám.'),
(1574668,54,46,2,13,'O nichž i mluvíme ne těmi slovy, jimž lidská moudrost učí, ale kterýmž vyučuje Duch svatý, duchovním to, což duchovního jest, přivlastňujíce.'),
(1574669,54,46,2,14,'Ale tělesný člověk nechápá těch věcí, kteréž jsou Ducha Božího; nebo jsou jemu bláznovství, aniž jich může poznati, protože ony duchovně mají rozsuzovány býti.'),
(1574670,54,46,2,15,'Ale duchovní člověk rozsuzujeť všecko, sám pak od žádného nebývá souzen.'),
(1574671,54,46,2,16,'Nebo kdo jest poznal mysl Páně? A kdo jej bude učiti? My pak mysl Kristovu máme.'),
(1574672,54,46,3,1,'A já, bratří, nemohl jsem vám mluviti jako duchovním, ale jako tělesným, jako maličkým v Kristu.'),
(1574673,54,46,3,2,'Mlékem jsem vás živil, a ne pokrmem; nebo jste ještě nemohli pokrmů tvrdších užívati, ano i nyní ještě nemůžete.'),
(1574674,54,46,3,3,'Ještě zajisté tělesní jste. Poněvadžť jest mezi vámi nenávist, svárové a různice, zdaž ještě tělesní nejste? a tak podle člověka chodíte.'),
(1574675,54,46,3,4,'Nebo když někdo říká: Jáť jsem Pavlův, jiný pak: Já Apollův, zdaliž nejste tělesní?'),
(1574676,54,46,3,5,'Nebo kdo jest Pavel, a kdo jest Apollo, než služebníci, skrze něž jste uvěřili, a jakž jednomu každému dal Pán?'),
(1574677,54,46,3,6,'Jáť jsem štípil, Apollo zaléval, ale Bůh dal zrůst.'),
(1574678,54,46,3,7,'A protož ani ten, kdož štěpuje, nic není, ani ten, jenž zalévá, ale ten, kterýž zrůst dává, Bůh.'),
(1574679,54,46,3,8,'Ten pak, kdož štěpuje, a ten, kdož zalévá, jedno jsou, avšak jeden každý vlastní odplatu vezme podle své práce.'),
(1574680,54,46,3,9,'Božíť jsme zajisté pomocníci, Boží rolí, Boží vzdělání jste.'),
(1574681,54,46,3,10,'Já podle milosti Boží mně dané, jako moudrý stavitel, základ jsem založil, jiný pak na něm staví. Ale jeden každý viz, jak na něm staví.'),
(1574682,54,46,3,11,'Nebo základu jiného žádný položiti nemůž, mimo ten, kterýž položen jest, jenž jest Ježíš Kristus.'),
(1574683,54,46,3,12,'Staví-liť pak kdo na ten základ zlato, stříbro, kamení drahé, dříví, seno, strniště,'),
(1574684,54,46,3,13,'Jednohoť každého dílo zjeveno bude. Den zajisté to všecko okáže; nebo v ohni zjeví se, a jednoho každého dílo, jaké by bylo, oheň zprubuje.'),
(1574685,54,46,3,14,'Zůstane-liť čí dílo, kteréž na něm stavěl, vezme odplatu.'),
(1574686,54,46,3,15,'Pakliť čí dílo shoří, tenť vezme škodu, ale sám spasen bude, avšak tak jako skrze oheň.'),
(1574687,54,46,3,16,'Zdaliž nevíte, že chrám Boží jste, a Duch Boží v vás přebývá?'),
(1574688,54,46,3,17,'Jestližeť kdo chrámu Božího poskvrňuje, tohoť zatratí Bůh; nebo chrám Boží svatý jest, jenž jste vy.'),
(1574689,54,46,3,18,'Žádný sám sebe nesvoď. Zdá-li se komu z vás, že jest moudrý na tomto světě, budiž bláznem, aby byl učiněn moudrým.'),
(1574690,54,46,3,19,'Moudrost zajisté světa tohoto bláznovství jest u Boha. Nebo psáno jest: Kterýž zlapá moudré v chytrosti jejich.'),
(1574691,54,46,3,20,'A opět: Znáť Pán přemyšlování moudrých, že jsou marná.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574692,54,46,3,21,'A tak nechlubiž se žádný lidmi; nebo všecky věci vaše jsou.'),
(1574693,54,46,3,22,'Buďto Pavel, buďto Apollo, buďto Petr, buďto svět, buďto život, buďto smrt, buďto přítomné věci, buďto budoucí, všecko jest vaše,'),
(1574694,54,46,3,23,'Vy pak Kristovi, a Kristus Boží.'),
(1574695,54,46,4,1,'Tak o nás smýšlej člověk, jako o služebnících Kristových a šafářích tajemství Božích.'),
(1574696,54,46,4,2,'Dále pak vyhledává se při šafářích toho, aby každý z nich věrný nalezen byl.'),
(1574697,54,46,4,3,'Mně pak to za nejmenší věc jest, abych od vás souzen byl, aneb od lidského soudu; nýbrž aniž sám sebe soudím.'),
(1574698,54,46,4,4,'Nebo ačkoli do sebe nic bezbožného nevím, však ne skrze to jsem spravedliv; nebo ten, ješto mne soudí, Pán jest.'),
(1574699,54,46,4,5,'Protož nesuďtež nic před časem, až by přišel Pán, kterýž i osvítí to, což skrytého jest ve tmě, a zjeví rady srdcí. A tehdážť bude míti chválu jeden každý od Boha.'),
(1574700,54,46,4,6,'Tyto pak věci, bratří moji, v podobenství obrátil jsem na sebe a na Apollo, pro vás, abyste se na nás učili nad to, což psáno jest, výše nesmýšleti, a abyste jeden pro druhého nenadýmali se proti někomu.'),
(1574701,54,46,4,7,'Nebo kdož tě soudí? A co máš, ješto bys nevzal? A když jsi vzal, proč se chlubíš, jako bys nevzal?'),
(1574702,54,46,4,8,'Již jste nasyceni, již jste zbohatli, bez nás kralujete. Ale ó byste kralovali, abychom i my také spolu s vámi kralovali.'),
(1574703,54,46,4,9,'Za to mám jistě, že nás Bůh apoštoly poslední okázal jako k smrti oddané; nebo učiněni jsme divadlo tomuto světu, i andělům, i lidem.'),
(1574704,54,46,4,10,'My blázni pro Krista, ale vy opatrní v Kristu; my mdlí, vy pak silní; vy slavní, ale my opovržení.'),
(1574705,54,46,4,11,'Až do tohoto času i lačníme, i žízníme, i nahotu trpíme, i poličkováni býváme, i místa nemáme,'),
(1574706,54,46,4,12,'A pracujeme, dělajíce rukama vlastníma; uhaněni jsouce, dobrořečíme; protivenství trpíce, mile snášíme.'),
(1574707,54,46,4,13,'Když se nám rouhají, modlíme se za ně; jako smeti tohoto světa učiněni jsme, a jako povrhel u všech, až posavad.'),
(1574708,54,46,4,14,'Ne proto, abych vás zahanbil, píši toto, ale jako svých milých synů napomínám.'),
(1574709,54,46,4,15,'Nebo byste pak deset tisíc pěstounů měli v Kristu, však proto nemnoho máte otců. Nebo v Kristu Ježíši skrze evangelium já jsem vás zplodil.'),
(1574710,54,46,4,16,'Protož prosím vás, buďtež následovníci moji.'),
(1574711,54,46,4,17,'Pro tu příčinu poslal jsem vám Timotea, kterýžto jest syn můj milý a věrný v Pánu. Tenť vám připomínati bude, které jsou cesty mé v Kristu, jakž všudy v každé církvi učím.'),
(1574712,54,46,4,18,'Rovně jako bych neměl k vám přijíti, tak se naduli někteří.'),
(1574713,54,46,4,19,'Ale přijduť k vám brzo, bude-li Pán chtíti, a poznám ne řeč těch nadutých, ale moc.'),
(1574714,54,46,4,20,'Neboť nezáleží v řeči království Boží, ale v moci.'),
(1574715,54,46,4,21,'Co chcete? S metlou-li abych přišel k vám, čili s láskou, a s duchem tichosti?'),
(1574716,54,46,5,1,'Naprosto se slyší, že by mezi vámi bylo smilstvo, a to takové smilstvo, jakéž se ani mezi pohany nejmenuje, totiž aby někdo měl manželku otce svého.'),
(1574717,54,46,5,2,'A vy nadutí jste, a nermoutíte se raději, aby vyvržen byl z prostředku vás ten, kdož takový skutek spáchal.'),
(1574718,54,46,5,3,'Já zajisté, ač vzdálený tělem, ale přítomný duchem, již jsem to usoudil, jako bych přítomen byl, abyste toho, kterýž to tak spáchal,'),
(1574719,54,46,5,4,'Ve jménu Pána našeho Jezukrista sejdouce se spolu, i s mým duchem, s mocí Pána našeho Jezukrista,'),
(1574720,54,46,5,5,'Vydali takového satanu k zahubení těla, aby duch spasen byl v den Pána Ježíše.'),
(1574721,54,46,5,6,'Neníť dobrá chlouba vaše. Zdaliž nevíte, že maličko kvasu všecko těsto nakvašuje?'),
(1574722,54,46,5,7,'Vyčisťtež tedy starý kvas, abyste byli nové zadělání, jakož pak jste nenakvašeni. Neboť jest Beránek náš velikonoční za nás obětován, Kristus.'),
(1574723,54,46,5,8,'A protož hodujmež ne v kvasu starém, ani v kvasu zlosti a nešlechetnosti, ale v přesnicích upřímosti a pravdy.'),
(1574724,54,46,5,9,'Psal jsem vám v listu, abyste se nesměšovali s smilníky.'),
(1574725,54,46,5,10,'Ale ne všelikterak s smilníky tohoto světa, neb s lakomci, nebo s dráči, aneb s modláři, sic jinak musili byste z tohoto světa vyjíti.'),
(1574726,54,46,5,11,'Nyní pak psal jsem vám, abyste se nesměšovali s takovými, kdyby kdo, maje jméno bratr, byl smilník, neb lakomec, neb modlář, neb zlolejce, neb opilec, neb dráč. S takovým ani nejezte.'),
(1574727,54,46,5,12,'Nebo proč já mám i ty, kteříž jsou vně, souditi? Však ty, kteříž jsou vnitř, vy soudíte?'),
(1574728,54,46,5,13,'Ty pak, kteříž jsou vně, Bůh soudí. Vyvrztež tedy toho zlého sami z sebe.'),
(1574729,54,46,6,1,'Smí někdo z vás, maje při s druhým, souditi se před nepravými, a ne raději před svatými?'),
(1574730,54,46,6,2,'Nevíte-liž, že svatí svět souditi budou? I poněvadž od vás souzen býti má svět, kterakž tedy nehodni jste těch nejmenších věcí rozsuzovati?'),
(1574731,54,46,6,3,'Zdaliž nevíte, že anděly souditi budeme? Co pak tyto časné věci?'),
(1574732,54,46,6,4,'Protož když byste měli míti soud o tyto časné věci, těmi, kteříž nejzadnější jsou v církvi, soud osaďte.'),
(1574733,54,46,6,5,'K zahanbeníť vašemu to pravím. Tak-liž není mezi vámi moudrého ani jednoho, kterýž by mohl rozsouditi mezi bratrem a bratrem svým?'),
(1574734,54,46,6,6,'Ale bratr s bratrem soudí se, a to před nevěřícími?'),
(1574735,54,46,6,7,'Již tedy konečně nedostatek mezi vámi jest, že soudy máte mezi sebou. Proč raději křivdy netrpíte? Proč raději škody nebéřete?'),
(1574736,54,46,6,8,'Nýbrž vy křivdu činíte, a k škodě přivodíte, a to bratří své.'),
(1574737,54,46,6,9,'Zdali nevíte, že nespravedliví dědictví království Božího nedosáhnou? Nemylte se, však ani smilníci, ani modláři, ani cizoložníci, ani zženštilí, ani samcoložníci,'),
(1574738,54,46,6,10,'Ani zloději, ani lakomci, ani opilci, ani zlolejci, ani dráči, dědictví království Božího nedůjdou.'),
(1574739,54,46,6,11,'A takoví jste někteří byli, ale obmyti jste, ale posvěceni jste, ale ospravedlněni jste ve jménu Pána Jezukrista a skrze Ducha Boha našeho.'),
(1574740,54,46,6,12,'Všecko mi sluší, ale ne všecko prospívá; všecko mi sluší, ale jáť pod žádné té věci moc poddán nebudu.'),
(1574741,54,46,6,13,'Pokrmové břichu náležejí, a břicho pokrmům; Bůh pak i pokrmy i břicho zkazí. Ale tělo ne smilstvu oddáno býti má, ale Pánu, a Pán tělu.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574742,54,46,6,14,'Bůh pak i Pána Ježíše vzkřísil, i nás také vzkřísí mocí svou.'),
(1574743,54,46,6,15,'Nevíte-liž, že těla vaše jsou údové Kristovi? Což tedy vezma údy Kristovy, učiním je údy nevěstky? Odstup to.'),
(1574744,54,46,6,16,'Zdaliž nevíte, že kdož se připojuje k nevěstce, jedno tělo jest s ní? Nebo dí Písmo: Budou dva jedno tělo.'),
(1574745,54,46,6,17,'Ten pak, jenž se připojuje Pánu, jeden duch jest s ním.'),
(1574746,54,46,6,18,'Utíkejte smilstva. Všeliký hřích, kterýžkoli učinil by člověk, kromě těla jest, ale kdož smilní, ten proti svému vlastnímu tělu hřeší.'),
(1574747,54,46,6,19,'Zdaliž nevíte, že tělo vaše jest chrám Ducha svatého, jenž přebývá v vás, kteréhož máte od Boha, a nejste sami svoji?'),
(1574748,54,46,6,20,'Nebo koupeni jste za velikou mzdu. Oslavujtež tedy Boha tělem vaším i duchem vaším, kteréžto věci Boží jsou.'),
(1574749,54,46,7,1,'O čemž jste mi pak psali, k tomuť vám toto odpovídám: Dobréť by bylo člověku ženy se nedotýkati.'),
(1574750,54,46,7,2,'Ale pro uvarování se smilstva, jeden každý manželku svou měj a jedna každá měj muže svého.'),
(1574751,54,46,7,3,'Muž k ženě povinnou přívětivost okazuj, a tak podobně i žena muži.'),
(1574752,54,46,7,4,'Žena vlastního těla svého v moci nemá, ale muž; též podobně i muž těla svého vlastního v moci nemá, ale žena.'),
(1574753,54,46,7,5,'Nezbavujte jeden druhého, leč by to bylo z společného svolení na čas, abyste se uprázdnili ku postu a k modlitbě; a potom zase k témuž se navraťte, aby vás nepokoušel satan pro nezdrželivost vaši.'),
(1574754,54,46,7,6,'Ale toť pravím podle dopuštění, ne podle rozkazu.'),
(1574755,54,46,7,7,'Nebo chtěl bych, aby všickni lidé tak byli jako já, ale jeden každý svůj vlastní dar od Boha má, jeden tak a jiný jinak.'),
(1574756,54,46,7,8,'Pravím pak neženatým a vdovám: Dobré jest jim, aby tak zůstali jako i já.'),
(1574757,54,46,7,9,'Pakliť se nemohou zdržeti, nechažť v stav manželský vstoupí; nebo lépe jest v stav manželský vstoupiti nežli páliti se.'),
(1574758,54,46,7,10,'Vdaným pak přikazuji ne já, ale Pán, řka: Manželka od muže neodcházej.'),
(1574759,54,46,7,11,'Pakliť by odešla, zůstaniž nevdaná, anebo smiř se s mužem svým. Tolikéž muž nepropouštěj ženy.'),
(1574760,54,46,7,12,'Jiným pak pravím já, a ne Pán: Má-li který bratr manželku nevěřící, a ta povoluje býti s ním, nepropouštějž jí.'),
(1574761,54,46,7,13,'A má-li která žena muže nevěřícího, a on chce býti s ní, nepropouštěj ho.'),
(1574762,54,46,7,14,'Posvěcenť jest zajisté nevěřící muž pro ženu věřící, a žena nevěřící posvěcena jest pro muže; sic jinak děti vaši nečistí by byli, ale nyní svatí jsou.'),
(1574763,54,46,7,15,'Pakliť nevěřící odjíti chce, nechať jde. Neníť manem bratr neb sestra v takové věci, ale ku pokoji povolal nás Bůh.'),
(1574764,54,46,7,16,'A kterak ty víš, ženo, získáš-li muže svého? Anebo co ty víš, muži, získáš-li ženu?'),
(1574765,54,46,7,17,'Ale jakž jednomu každému odměřil Bůh a jakž jednoho každého povolal Pán, tak choď. A takť ve všech církvech řídím.'),
(1574766,54,46,7,18,'Obřezaný někdo povolán jest? Neuvodiž na sebe neobřezání; pakli kdo v neobřízce povolán, neobřezuj se.'),
(1574767,54,46,7,19,'Nebo obřízka nic není, a neobřízka také nic není, ale zachovávání přikázání Božích.'),
(1574768,54,46,7,20,'Jeden každý v povolání tom, jímž povolán jest, zůstávej.'),
(1574769,54,46,7,21,'Služebníkem byv, povolán jsi? Nedbej na to. Pakli bys mohl býti svobodný, raději toho užívej.'),
(1574770,54,46,7,22,'Nebo kdož jest v Pánu povolán, byv služebníkem, osvobozený jest Páně. Též podobně kdož jest povolán byv svobodný, služebník jest Kristův.'),
(1574771,54,46,7,23,'Za mzdu koupeni jste, nebuďtež služebníci lidští.'),
(1574772,54,46,7,24,'Jeden každý, jakž povolán jest, bratří, v tom zůstávej před Bohem.'),
(1574773,54,46,7,25,'O pannách pak přikázání Páně nemám, ale však radu dávám, jakožto ten, jemuž z milosrdenství svého Pán dal věrným býti.'),
(1574774,54,46,7,26,'Za toť pak mám, že jest to dobré pro nastávající potřebu, totiž že jest dobré člověku tak býti.'),
(1574775,54,46,7,27,'Přivázán-lis k ženě, nehledej rozvázání. Jsi-li prost od ženy, nehledej ženy.'),
(1574776,54,46,7,28,'Pakli bys ses i oženil, nezhřešils, a vdala-li by se panna, nezhřešila; ale trápení těla míti budou takoví; jáť pak vám odpouštím.'),
(1574777,54,46,7,29,'Ale totoť vám pravím, bratří, protože čas ostatní jest ukrácený: náležíť tedy, aby i ti, kteříž mají ženy, byli, jako by jich neměli.'),
(1574778,54,46,7,30,'A kteříž plačí, jako by neplakali, a kteříž se radují, jako by se neradovali, a kteříž kupují, jako by nevládli,'),
(1574779,54,46,7,31,'A kteříž užívají tohoto světa, jako by neužívali. Neboť pomíjí způsob tohoto světa.'),
(1574780,54,46,7,32,'A já bych rád chtěl, abyste vy bez pečování byli. Nebo kdo ženy nemá, pečuje o to, což jest Páně, kterak by se líbil Pánu.'),
(1574781,54,46,7,33,'Ale kdo se oženil, pečuje o věci tohoto světa, kterak by se líbil ženě.'),
(1574782,54,46,7,34,'Rozdílnéť jsou jistě žena a panna. Nevdaná pečuje o to, což jest Páně, aby byla svatá i tělem i duchem, ale vdaná pečuje o věci světa, kterak by se líbila muži.'),
(1574783,54,46,7,35,'Totoť pak pravím proto, abych vám to, což jest užitečnějšího, ukázal, ne abych na vás osidlo uvrhl, ale abyste slušně a případně Pána se přídrželi bez všeliké roztržitosti.'),
(1574784,54,46,7,36,'Pakli kdo za neslušnou věc své panně pokládá pomíjení času k vdání, a tak by se státi mělo, učiň, jakžkoli chce, nezhřeší. Nechažť ji vdá.'),
(1574785,54,46,7,37,'Ale kdož jest se pevně ustavil v srdci svém, a není mu toho potřeba, ale v moci má vlastní vůli svou, a to uložil v srdci svém, aby choval pannu svou, dobře činí.'),
(1574786,54,46,7,38,'A tak i ten, kdož vdává pannu svou, dobře činí, ale kdo nevdává, lépe činí.'),
(1574787,54,46,7,39,'Žena přivázána jest k manželství zákonem dotud, dokudž její muž živ jest. Pakli by umřel muž její, svobodná jest; můž se vdáti, za kohož chce, toliko v Pánu.'),
(1574788,54,46,7,40,'Ale blahoslavenější jest, zůstala-li by tak, podle mého soudu. Mámť pak za to, žeť i já mám Ducha Božího.'),
(1574789,54,46,8,1,'O těch pak věcech, kteréž modlám obětovány bývají, víme, že všickni známost máme. A známost nadýmá, ale láska vzdělává.'),
(1574790,54,46,8,2,'Zdá-li se pak komu, že něco umí, ještě nic nepoznal, tak jakž by měl znáti.'),
(1574791,54,46,8,3,'Ale jestliže kdo miluje Boha, tenť jest vyučen od něho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574792,54,46,8,4,'A protož o pokrmích, kteříž se modlám obětují, toto dím: Víme, že modla na světě nic není a že není jiného žádného Boha nežli jeden.'),
(1574793,54,46,8,5,'Nebo ačkoli jsou někteří, ješto slovou bohové, i na nebi i na zemi, (jakož jsou mnozí bohové a páni mnozí,)'),
(1574794,54,46,8,6,'Ale my máme jediného Boha Otce, z něhož všecko, a my v něm, a jednoho Pána Ježíše Krista, skrze něhož všecko, i my skrze něho.'),
(1574795,54,46,8,7,'Ale ne ve všechť jest to umění. Nebo někteří se zlým svědomím pro modlu až dosavad jako modlám obětované jedí, a svědomí jejich, jsuci mdlé, poskvrňuje se.'),
(1574796,54,46,8,8,'Nečiníť pak nás pokrm vzácných Bohu. Nebo budeme-li jísti, nic tím lepší nebudeme, a nebudeme-li jísti, nic horší nebudeme.'),
(1574797,54,46,8,9,'Ale vizte, ať by snad ta vaše moc nebyla k urážce mdlým.'),
(1574798,54,46,8,10,'Nebo uzří-li kdo tebe, majícího známost, a ty sedíš při pokrmu modlám obětovaném, zdaliž svědomí toho, kterýž jest mdlý, nebude přivedeno k tomu, aby také jedl modlám obětované?'),
(1574799,54,46,8,11,'I zahyneť bratr mdlý, (pro tvé to vědění), za kteréhož Kristus umřel.'),
(1574800,54,46,8,12,'A tak hřešíce proti bratřím, a urážejíce svědomí jejich mdlé, proti Kristu hřešíte.'),
(1574801,54,46,8,13,'A protož jestližeť pohoršuje pokrm bližního mého, nebudu jísti masa na věky, abych nezhoršil bratra svého.'),
(1574802,54,46,9,1,'Zdaliž nejsem apoštol? Zdaliž nejsem svobodný? Zdaliž jsem Jezukrista Pána našeho neviděl? Zdaliž vy nejste práce má v Pánu?'),
(1574803,54,46,9,2,'Bychť pak jiným nebyl apoštol, tedy vám jsem. Nebo pečet mého apoštolství vy jste v Pánu.'),
(1574804,54,46,9,3,'Odpověd má před těmi, jenž mne soudí, ta jest:'),
(1574805,54,46,9,4,'Zdaliž nemáme moci jísti a píti?'),
(1574806,54,46,9,5,'Zdaliž nemáme moci sestry ženy při sobě míti, jako i jiní apoštolé, i bratří Páně, i Petr?'),
(1574807,54,46,9,6,'Zdaliž sám já a Barnabáš nemáme moci tělesných prací zanechati?'),
(1574808,54,46,9,7,'I kdo bojuje kdy na svůj náklad? Kdo štěpuje vinici a jejího ovoce nejí? Anebo kdo pase stádo a mléka od stáda nejí?'),
(1574809,54,46,9,8,'Zdali podle člověka to pravím? Zdaliž i Zákon toho nepraví?'),
(1574810,54,46,9,9,'Nebo v Zákoně Mojžíšově psáno jest: Nezavížeš úst volu mlátícímu. I zdali Bůh tak o voly pečuje?'),
(1574811,54,46,9,10,'Čili naprosto pro nás to praví? Pro násť jistě to napsáno jest. Nebo kdo oře, v naději orati má; a kdo mlátí v naději, naděje své má účasten býti.'),
(1574812,54,46,9,11,'Poněvadž jsme my vám duchovní věci rozsívali, tak-liž jest pak to veliká věc, jestliže bychom my vaše časné věci žali?'),
(1574813,54,46,9,12,'Kdyžť jiní práva svého k vám užívají, proč ne raději my? Avšak neužívali jsme práva toho, ale všecko snášíme, abychom žádné překážky neučinili evangelium Kristovu.'),
(1574814,54,46,9,13,'Zdaliž nevíte, že ti, kteříž o svatých věcech pracují, z svatých věcí jedí, a kteříž oltáři přístojí, s oltářem spolu díl mají?'),
(1574815,54,46,9,14,'Tak jest i Pán nařídil těm, kteříž evangelium zvěstují, aby z evangelium živi byli.'),
(1574816,54,46,9,15,'Jáť jsem však ničeho toho neužíval. Aniž jsem toho proto psal, aby se to při mně tak dálo, anoť by mi mnohem lépe bylo umříti, nežli aby kdo chválu mou vyprázdnil.'),
(1574817,54,46,9,16,'Nebo káži-li evangelium, nemám se čím chlubiti, poněvadž jsem to povinen; ale běda by mně bylo, kdybych nekázal.'),
(1574818,54,46,9,17,'Jestližeť pak dobrovolně to činím, mámť odplatu; pakli bezděky, úřadť jest mi svěřen.'),
(1574819,54,46,9,18,'Jakouž tedy mám odplatu? abych evangelium káže, bez nákladů býti evangelium Kristovo uložil, proto abych zle nepožíval práva svého při evangelium.'),
(1574820,54,46,9,19,'Svoboden zajisté jsa ode všech, všechněm sebe samého v službu jsem vydal, abych mnohé získal.'),
(1574821,54,46,9,20,'A učiněn jsem Židům jako Žid, abych Židy získal; těm, kteříž pod Zákonem jsou, jako bych pod Zákonem byl, abych ty, kteříž pod Zákonem jsou, získal.'),
(1574822,54,46,9,21,'Těm, kteříž jsou bez Zákona, jako bych bez Zákona byl, (a nejsa bez Zákona Bohu, ale jsa v Zákoně Kristu,) abych získal ty, jenž jsou bez Zákona.'),
(1574823,54,46,9,22,'Učiněn jsem mdlým jako mdlý, abych mdlé získal. Všechněm všecko jsem učiněn, abych vždy některé k spasení přivedl.'),
(1574824,54,46,9,23,'A toť činím pro evangelium, abych účastník jeho byl.'),
(1574825,54,46,9,24,'Zdaliž nevíte, že ti, kteříž v závod běží, všickni zajisté běží, ale jeden béře základ? Tak běžte, abyste základu dosáhli.'),
(1574826,54,46,9,25,'A všeliký, kdož bojuje, ve všem jest zdrželivý. A oni zajisté, aby porušitelnou korunu vzali, jsou zdrželiví, ale my neporušitelnou.'),
(1574827,54,46,9,26,'Protož já tak běžím, ne jako v nejistotu, tak bojuji, ne jako vítr rozrážeje,'),
(1574828,54,46,9,27,'Ale podmaňuji tělo své a v službu podrobuji, abych snad jiným káže, sám nebyl nešlechetný.'),
(1574829,54,46,10,1,'Nechciť pak, abyste nevěděli, bratří, že otcové naši všickni pod oblakem byli, a všickni moře přešli,'),
(1574830,54,46,10,2,'A všickni v Mojžíše pokřtěni jsou v oblace a v moři,'),
(1574831,54,46,10,3,'A všickni týž pokrm duchovní jedli,'),
(1574832,54,46,10,4,'A všickni týž nápoj duchovní pili. Pili zajisté z duchovní skály, kteráž za nimi šla; a ta skála byl Kristus.'),
(1574833,54,46,10,5,'Ale ne ve mnohých z nich zalíbilo se Bohu, nebo zhynuli na poušti.'),
(1574834,54,46,10,6,'Ty pak věci za příklad nám býti mají k tomu, abychom nebyli žádostivi zlého, jako i oni žádali.'),
(1574835,54,46,10,7,'Protož nebuďte modláři, jako někteří z nich, jakož psáno jest: Posadil se lid, aby jedl a pil, a vstali, aby hrali.'),
(1574836,54,46,10,8,'Aniž smilněme, jako někteří z nich smilnili, a padlo jich jeden den třimecítma tisíců.'),
(1574837,54,46,10,9,'Ani pokoušejme Krista, jako někteří z nich pokoušeli, a od hadů zhynuli.'),
(1574838,54,46,10,10,'Ani repcete, jako i někteří z nich reptali, a zhynuli od záhubce.'),
(1574839,54,46,10,11,'Toto pak všecko u figuře dálo se jim, a napsáno jest k napomenutí našemu, kteříž jsme již na konci světa.'),
(1574840,54,46,10,12,'A protož kdo se domnívá, že stojí, hlediž, aby nepadl.'),
(1574841,54,46,10,13,'Pokušení vás nezachvátilo, než lidské. Ale věrnýť jest Bůh, kterýž nedopustí vás pokoušeti nad vaši možnost, ale způsobíť s pokušením také i vysvobození, abyste mohli snésti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574842,54,46,10,14,'Protož, moji milí bratří, utíkejtež modlářství.'),
(1574843,54,46,10,15,'Jakožto opatrným mluvím. Vy suďte, co pravím.'),
(1574844,54,46,10,16,'Kalich dobrořečení, kterémuž dobrořečíme, zdaliž není společnost krve Kristovy? A chléb, kterýž lámeme, zdaliž není společnost těla Kristova?'),
(1574845,54,46,10,17,'Nebo jeden chléb, jedno tělo mnozí jsme; všickni zajisté z jednoho chleba jíme.'),
(1574846,54,46,10,18,'Pohleďte na Izraele podle těla. Zdaliž ti, kteříž jedí oběti, nejsou účastníci oltáře?'),
(1574847,54,46,10,19,'Což pak tedy dím? Že modla jest něco? Anebo že modlám obětované něco jest? Nikoli.'),
(1574848,54,46,10,20,'Ale toto pravím, že, což obětují pohané, ďáblům obětují, a ne Bohu. Nechtělť bych pak, abyste vy byli účastníci ďáblů.'),
(1574849,54,46,10,21,'Nebo nemůžete kalicha Páně píti a kalicha ďáblů; nemůžete účastníci býti stolu Páně a stolu ďáblů.'),
(1574850,54,46,10,22,'Čili k hněvu popouzíme Pána? Zdali silnější jsme nežli on?'),
(1574851,54,46,10,23,'Všecko mi sluší, ale ne všecko jest užitečné; všecko mi sluší, ale ne všecko vzdělává.'),
(1574852,54,46,10,24,'Žádný nehledej svých věcí, ale jeden každý toho, což jest bližního.'),
(1574853,54,46,10,25,'Všecko, což se v masných krámích prodává, jezte, nic se nevyptávajíce pro svědomí.'),
(1574854,54,46,10,26,'Nebo Páněť jest země i plnost její.'),
(1574855,54,46,10,27,'Pozval-liť by vás pak kdo z nevěřících k stolu, a chcete jíti, vše, cožkoli bylo by vám předloženo, jezte, nic se nevyptávajíce pro svědomí.'),
(1574856,54,46,10,28,'Pakli by vám někdo řekl: Toto jest modlám obětované, nejezte pro toho, jenž oznámil, a pro svědomí. Páně zajisté jest země i plnost její.'),
(1574857,54,46,10,29,'Svědomí pak pravím ne tvé, ale toho druhého. Nebo proč by měla svoboda má potupena býti od cizího svědomí?'),
(1574858,54,46,10,30,'A poněvadž já s díků činěním požívám, proč mi se rouhají příčinou toho, z čehož já díky činím?'),
(1574859,54,46,10,31,'Protož buďto že jíte, nebo pijete, anebo cožkoli činíte, všecko k slávě Boží čiňte.'),
(1574860,54,46,10,32,'Bez úrazu buďte i Židům i Řekům i církvi Boží,'),
(1574861,54,46,10,33,'Jakož i já ve všem líbím se všechněm, nehledaje v tom svého užitku, ale mnohých, aby spaseni byli.'),
(1574862,54,46,11,1,'Následovníci moji buďte, jako i já Kristův.'),
(1574863,54,46,11,2,'Chválímť pak vás, bratří, že všecky věci mé v paměti máte, a jakž jsem vydal vám ustanovení, tak je zachováváte.'),
(1574864,54,46,11,3,'Chciť pak, abyste věděli, že všelikého muže hlava jest Kristus, a hlava ženy muž, hlava pak Kristova Bůh.'),
(1574865,54,46,11,4,'Každý muž, modle se aneb prorokuje s přikrytou hlavou, ohyžďuje hlavu svou.'),
(1574866,54,46,11,5,'Každá pak žena, modleci se anebo prorokujici s nepřikrytou hlavou, ohyžďuje hlavu svou; nebo jednostejná věc jest, jako by se oholila.'),
(1574867,54,46,11,6,'Nebo nezavíjí-liť žena hlavy své, nechažť se také ostříhá. Pakli jest mrzká věc ženě oholiti se neb ostříhati, nechažť se zavíjí.'),
(1574868,54,46,11,7,'Mužť nemá zavíjeti hlavy své, obraz a sláva Boží jsa, ale žena sláva mužova jest.'),
(1574869,54,46,11,8,'Nebo není muž z ženy, ale žena z muže.'),
(1574870,54,46,11,9,'Není zajisté muž stvořen pro ženu, ale žena pro muže.'),
(1574871,54,46,11,10,'Protož máť žena míti obestření na hlavě pro anděly.'),
(1574872,54,46,11,11,'Avšak ani muž bez ženy, ani žena bez muže, v Pánu.'),
(1574873,54,46,11,12,'Nebo jakož žena jest z muže, tak i muž skrze ženu, všecky pak věci z Boha.'),
(1574874,54,46,11,13,'Vy sami mezi sebou suďte, sluší-li se ženě s nepřikrytou hlavou modliti Bohu.'),
(1574875,54,46,11,14,'Zdaliž vás i samo přirození neučí, žeť jest ohyzda muži míti dlouhé vlasy?'),
(1574876,54,46,11,15,'Ale ženě míti dlouhé vlasy poctivé jest; nebo vlasové k zastírání dány jsou jí.'),
(1574877,54,46,11,16,'Jestliže pak komu se vidí neustupným býti, myť takového obyčeje nemáme, ani církev Boží.'),
(1574878,54,46,11,17,'Toto pak předkládaje, nechválím toho, že ne k lepšímu, ale k horšímu se scházíte.'),
(1574879,54,46,11,18,'Nejprve zajisté, když se scházíte do shromáždění, slyším, že jsou roztržky mezi vámi, a poněkud tomu věřím.'),
(1574880,54,46,11,19,'Neboť musejí i kacířstva mezi vámi býti, aby právě zbožní zjeveni byli mezi vámi.'),
(1574881,54,46,11,20,'A tak když se scházíte vespolek, jižť to není večeři Páně jísti,'),
(1574882,54,46,11,21,'Poněvadž jeden každý nejprv večeři svou přijímá v jedení, a tu někdo lační, a jiný se přepil.'),
(1574883,54,46,11,22,'A což pak domů nemáte k jedení a ku pití? Čili církev Boží tupíte, a zahanbujete ty, kteříž nemají hojnosti pokrmů? Což vám dím? Chváliti budu vás? V tom jistě nechválím.'),
(1574884,54,46,11,23,'Já zajisté přijal jsem ode Pána, což i vydal jsem vám, že Pán Ježíš v tu noc, v kterouž zrazen jest, vzal chléb,'),
(1574885,54,46,11,24,'A díky činiv, lámal a řekl: Vezměte, jezte, to jest tělo mé, kteréž se za vás láme. To čiňte na mou památku.'),
(1574886,54,46,11,25,'Takž i kalich, když povečeřel, řka: Tento kalich jest ta nová smlouva v mé krvi. To čiňte, kolikrátkoli píti budete, na mou památku.'),
(1574887,54,46,11,26,'Nebo kolikrátž byste koli jedli chléb tento a z kalicha toho pili, smrt Páně zvěstujte, dokavadž nepřijde.'),
(1574888,54,46,11,27,'A protož kdokoli jedl by chléb tento a pil z kalicha Páně nehodně, vinen bude tělem a krví Páně.'),
(1574889,54,46,11,28,'Zkusiž tedy sám sebe člověk, a tak chléb ten jez, a z toho kalicha pí.'),
(1574890,54,46,11,29,'Nebo kdož jí a pije nehodně, odsouzení sobě jí a pije, nerozsuzuje těla Páně.'),
(1574891,54,46,11,30,'Protož mezi vámi jsou mnozí mdlí a nemocní, a spí mnozí,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574892,54,46,11,31,'Ješto kdybychom se sami rozsuzovali, nebyli bychom souzeni.'),
(1574893,54,46,11,32,'Ale když býváme souzeni, ode Pána býváme poučováni, abychom s světem nebyli odsouzeni.'),
(1574894,54,46,11,33,'A tak, bratří moji, když se scházíte k jedení, jedni na druhé čekávejte.'),
(1574895,54,46,11,34,'Pakli kdo lační, doma jez, abyste se nescházeli k odsouzení. Jiné pak věci, když přijdu, zřídím.'),
(1574896,54,46,12,1,'O duchovních pak dařích, bratří, nechci, abyste nevěděli.'),
(1574897,54,46,12,2,'Víte, že jste byli pohané, kteříž k modlám němým, jakž jste bývali vedeni, tak jste chodili.'),
(1574898,54,46,12,3,'Protož známoť vám činím, že žádný v Duchu Božím mluvě, nezlořečí Pánu Ježíši, a žádný nemůže říci Pán Ježíš, jediné v Duchu svatém.'),
(1574899,54,46,12,4,'Rozdílníť pak darové jsou, ale tentýž Duch,'),
(1574900,54,46,12,5,'A rozdílná jsou přisluhování, ale tentýž Pán,'),
(1574901,54,46,12,6,'A rozdílné jsou moci, ale tentýž Bůh, jenžto působí všecko ve všech.'),
(1574902,54,46,12,7,'Jednomu pak každému dáno bývá zjevení Ducha k užitku.'),
(1574903,54,46,12,8,'Nebo někomu dána bývá skrze Ducha řeč moudrosti, jinému pak řeč umění podle téhož Ducha,'),
(1574904,54,46,12,9,'Jinému víra v témž Duchu, jinému darové uzdravování v jednostejném Duchu,'),
(1574905,54,46,12,10,'Někomu divů činění, jinému proroctví, jinému rozeznání duchů, jinému rozličnost jazyků, jinému vykládání jazyků.'),
(1574906,54,46,12,11,'Ale to vše působí jeden a týž Duch, rozděluje jednomu každému obzvláštně, jakž ráčí.'),
(1574907,54,46,12,12,'Nebo jakož tělo jedno jest a mnoho má údů, ale všickni ti jednoho těla údové, mnozí jsouce, však jedno tělo jsou: tak i Kristus.'),
(1574908,54,46,12,13,'Skrze jednoho zajisté Ducha my všickni v jedno tělo pokřtěni jsme, buďto Židé, buďto Řekové, buďto služebníci, nebo svobodní, a všickni v jeden duch zapojeni jsme.'),
(1574909,54,46,12,14,'Nebo tělo není jeden úd, ale mnozí.'),
(1574910,54,46,12,15,'Dí-li noha: Poněvadž nejsem rukou, nejsem z těla, zdaliž proto není z těla?'),
(1574911,54,46,12,16,'A dí-li ucho: Když nejsem oko, nejsem z těla, zdaliž proto není z těla?'),
(1574912,54,46,12,17,'Jestliže všecko tělo jest oko, kde pak bude sluch? Pakli všecko tělo jest sluch, kde povonění?'),
(1574913,54,46,12,18,'Ale zřídil Bůh údy jeden každý z nich v těle, tak jakž jest on chtěl.'),
(1574914,54,46,12,19,'Nebo kdyby byli všickni údové jeden úd, kde by bylo tělo?'),
(1574915,54,46,12,20,'Ale nyní mnozí údové jsou, však jedno tělo.'),
(1574916,54,46,12,21,'A tak nemůžť oko říci ruce: Nepotřebí mi tebe, anebo opět hlava nohám: Nepotřebuji vás.'),
(1574917,54,46,12,22,'Nýbrž mnohem více údové, kteříž se zdadí nejmdlejší v těle býti, potřební jsou.'),
(1574918,54,46,12,23,'A kteréž máme za nejméně ctihodné údy v těle, ty větší ctí přistíráme; a nezdobní údové naši hojnější ozdobu mají,'),
(1574919,54,46,12,24,'Ozdobní pak údové naši toho nepotřebují. Ale Bůh tak způsobil tělo, poslednějšímu dav hojnější poctu,'),
(1574920,54,46,12,25,'Aby nebyla nesvornost v těle, ale aby údové jedni o druhé vespolek pečovali'),
(1574921,54,46,12,26,'A protož jestliže trpí co jeden úd, spolu s ním trpí všickni údové; pakli jest v slávě jeden úd, radují se spolu s ním všickni údové.'),
(1574922,54,46,12,27,'Vy pak jste tělo Kristovo, a údové z částky.'),
(1574923,54,46,12,28,'A některé zajisté postavil Bůh v církvi nejprv apoštoly, druhé proroky, třetí učitele, potom moci, potom ty, kteří mají dary uzdravování, pomocníky, správce jiných, rozličnost jazyků mající.'),
(1574924,54,46,12,29,'Zdaliž jsou všickni apoštolé? Zdali všickni proroci? Zdali všickni učitelé? Zdali všickni divy činí?'),
(1574925,54,46,12,30,'Zdali všickni mají dary k uzdravování? Zdali všickni jazyky rozličnými mluví? Zdali všickni vykládají?'),
(1574926,54,46,12,31,'Snažujtež se pak dojíti darů lepších, a ještěť vyšší cestu vám ukáži.'),
(1574927,54,46,13,1,'Bych jazyky lidskými mluvil i andělskými, a lásky kdybych neměl, učiněn jsem jako měď zvučící anebo zvonec znějící.'),
(1574928,54,46,13,2,'A bychť měl proroctví, a znal všecka tajemství, i všelikého umění došel, a kdybych měl tak velikou víru, že bych hory přenášel, lásky pak kdybych neměl, nic nejsem.'),
(1574929,54,46,13,3,'A kdybych vynaložil na pokrmy chudých všecken statek svůj, a bych vydal tělo své k spálení, a lásky bych jen neměl, nic mi to neprospívá.'),
(1574930,54,46,13,4,'Láska trpělivá jest, dobrotivá jest, láska nezávidí, láska není všetečná, nenadýmá se.'),
(1574931,54,46,13,5,'V nic neslušného se nevydává, nehledá svých věcí, nezpouzí se, neobmýšlí zlého.'),
(1574932,54,46,13,6,'Neraduje se z nepravosti, ale spolu raduje se pravdě.'),
(1574933,54,46,13,7,'Všecko snáší, všemu věří, všeho se naděje, všeho trpělivě čeká.'),
(1574934,54,46,13,8,'Láska nikdy nevypadá, ačkoli proroctví přestanou, i jazykové utichnou, i učení v nic přijde.'),
(1574935,54,46,13,9,'Z částky zajisté poznáváme a z částky prorokujeme.'),
(1574936,54,46,13,10,'Ale jakžť by přišlo dokonalé, tehdyť to, což jest z částky, vyhlazeno bude.'),
(1574937,54,46,13,11,'Dokudž jsem byl dítě, mluvil jsem jako dítě, myslil jsem jako dítě, smýšlel jsem jako dítě, ale když jsem učiněn muž, opustil jsem dětinské věci.'),
(1574938,54,46,13,12,'Nyní zajisté vidíme v zrcadle a skrze podobenství, ale tehdáž tváří v tvář. Nyní poznávám z částky, ale tehdy poznám, tak jakž i známostí obdařen budu.'),
(1574939,54,46,13,13,'Nyní pak zůstává víra, naděje, láska, to tré, ale největší z nich jestiť láska.'),
(1574940,54,46,14,1,'Následujtež tedy lásky, horlivě žádejte duchovních věcí, nejvíce však, abyste prorokovali.'),
(1574941,54,46,14,2,'Nebo ten, jenž mluví cizím jazykem, ne lidem mluví, ale Bohu; nebo žádný neposlouchá, ale duchem vypravuje tajemství.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574942,54,46,14,3,'Kdož pak prorokuje, lidem mluví vzdělání, i napomínání, i potěšení.'),
(1574943,54,46,14,4,'Kdož mluví cizím jazykem, sám sebe vzdělává, ale kdož prorokuje, tenť církev vzdělává.'),
(1574944,54,46,14,5,'Chtělť bych pak, abyste všickni jazyky rozličnými mluvili, ale však raději, abyste prorokovali. Nebo větší jest ten, jenž prorokuje, nežli ten, kdož jazyky cizími mluví, leč by také to, což mluví, vykládal, aby se vzdělávala církev.'),
(1574945,54,46,14,6,'A protož, bratří, přišel-li bych k vám, jazyky cizími mluvě, což vám prospěji, nebudu-liť vám mluviti, buď v zjevení neb v umění, buď v proroctví neb v učení?'),
(1574946,54,46,14,7,'Podobně jako i bezdušné věci, vydávající zvuk, jako píšťalka nebo harfa, kdyby rozdílného zvuku nevydávaly, kterak by vědíno bylo, co se píská, anebo na harfu hrá?'),
(1574947,54,46,14,8,'Ano trouba vydala-li by nejistý hlas, kdož se bude strojiti k boji?'),
(1574948,54,46,14,9,'Tak i vy, nevydali-li byste jazykem svým srozumitelných slov, kterak bude rozumíno, co se mluví? Budete jen u vítr mluviti.'),
(1574949,54,46,14,10,'Tak mnoho, (jakž vidíme,) rozdílů hlasů jest na světě, a nic není bez hlasu.'),
(1574950,54,46,14,11,'Protož nebudu-liť znáti moci hlasu, budu tomu, kterýž mluví, cizozemec, a ten, jenž mluví, bude mi také cizozemec.'),
(1574951,54,46,14,12,'Tak i vy, poněvadž jste horliví milovníci duchovních věcí, toho hledejte, abyste se k vzdělání církve rozhojnili.'),
(1574952,54,46,14,13,'A protož, kdož mluví jazykem cizím, modl se, aby mohl vykládati.'),
(1574953,54,46,14,14,'Nebo budu-li se modliti cizím jazykem, duch můj se toliko modlí, ale mysl má bez užitku jest.'),
(1574954,54,46,14,15,'Což tedy jest? Modliti se budu duchem, a modliti se budu i myslí; plésati budu duchem a plésati budu i myslí.'),
(1574955,54,46,14,16,'Nebo kdybys ty dobrořečil Bohu duchem, kterakž ten, jenž prostý člověk jest, k tvému dobrořečení řekne Amen, poněvadž neví, co pravíš?'),
(1574956,54,46,14,17,'Nebo ač ty dobře díky činíš, ale jiný se nevzdělává.'),
(1574957,54,46,14,18,'Děkuji Bohu svému, že více nežli vy všickni jazyky cizími mluvím.'),
(1574958,54,46,14,19,'Ale v sboru raději bych chtěl pět slov srozumitelně promluviti, abych také jiných poučil, nežli deset tisíců slov jazykem neznámým.'),
(1574959,54,46,14,20,'Bratří, nebuďte děti v smyslu, ale zlostí buďte děti, smyslem pak buďte dospělí.'),
(1574960,54,46,14,21,'Psáno jest v Zákoně: Že rozličnými jazyky a cizími rty budu mluviti lidu tomuto, a anižť tak mne slyšeti budou, praví Pán.'),
(1574961,54,46,14,22,'A tak jazykové jsou za div ne těm, jenž věří, ale nevěřícím, proroctví pak ne nevěřícím, ale věřícím.'),
(1574962,54,46,14,23,'A protož když by se sešla všecka církev spolu, a všickni by jazyky cizími mluvili, a vešli by tam i neučení neb nevěřící, zdaliž neřeknou, že blázníte?'),
(1574963,54,46,14,24,'Ale kdyby všickni prorokovali, a všel by tam mezi ně někdo nevěřící nebo neučený, přemáhán by byl ode všech a souzen ode všech.'),
(1574964,54,46,14,25,'A tak tajnosti srdce jeho zjeveny budou, a on padna na tvář, klaněti se bude Bohu, vyznávaje, že jistě Bůh jest mezi vámi.'),
(1574965,54,46,14,26,'Což tedy bratří? Když se scházíte, jeden každý z vás píseň má, učení má, cizí jazyk má, zjevení má, vykládání má, všecko to budiž k vzdělání.'),
(1574966,54,46,14,27,'Buďto že by kdo jazykem cizím mluvil, ať se to děje skrze dva neb nejvíce tři, a to jeden po druhém, a jeden ať vykládá.'),
(1574967,54,46,14,28,'Pakli by nebylo vykladače, nechať mlčí v shromáždění, než sobě sám nechažť mluví a Bohu.'),
(1574968,54,46,14,29,'Proroci pak dva nebo tři ať mluví, a jiní nechť rozsuzují.'),
(1574969,54,46,14,30,'Pakliť by jinému tu přísedícímu zjeveno bylo, první mlč.'),
(1574970,54,46,14,31,'Nebo můžete všickni, jeden po druhém, prorokovati, aby se všickni učili a všickni se potěšovali.'),
(1574971,54,46,14,32,'Duchovéť pak proroků prorokům poddáni jsou.'),
(1574972,54,46,14,33,'Nebo neníť Bůh původ různice, ale pokoje, jakož i ve všech shromážděních svatých učím.'),
(1574973,54,46,14,34,'Ženy vaše v shromážděních ať mlčí, nebo nedopouští se jim mluviti, ale aby poddány byly, jakž i Zákon praví.'),
(1574974,54,46,14,35,'Pakli se chtí čemu naučiti, doma mužů svých nechať se ptají. Nebo mrzká věc jest ženám mluviti v shromáždění.'),
(1574975,54,46,14,36,'Zdaliž jest od vás slovo Boží pošlo? Zdali k samým vám přišlo?'),
(1574976,54,46,14,37,'Zdá-li se sobě kdo býti prorokem nebo duchovním, nechažť pozná, co vám píši, žeť jsou přikázání Páně.'),
(1574977,54,46,14,38,'Pakli kdo neví, nevěz.'),
(1574978,54,46,14,39,'A takž, bratří, o to se snažte, abyste prorokovali, a jazyky cizími mluviti nezbraňujte.'),
(1574979,54,46,14,40,'Všecko slušně a podle řádu ať se děje.'),
(1574980,54,46,15,1,'Známoť vám pak činím, bratří, evangelium, kteréž jsem zvěstoval vám, kteréž jste i přijali, v němž i stojíte,'),
(1574981,54,46,15,2,'Skrze kteréž i spasení béřete, kterak kázal jsem vám, pamatujete-li, leč byste nadarmo uvěřili.'),
(1574982,54,46,15,3,'Vydal jsem zajisté vám nejprve to, což jsem i vzal, že Kristus umřel za hříchy naše podle Písem,'),
(1574983,54,46,15,4,'A že jest pohřben a že vstal z mrtvých třetího dne podle Písem.'),
(1574984,54,46,15,5,'A že vidín jest od Petra, potom od dvanácti.'),
(1574985,54,46,15,6,'Potom vidín více než od pěti set bratří spolu, z nichžto mnozí ještě živi jsou až dosavad, a někteří již zesnuli.'),
(1574986,54,46,15,7,'Potom vidín jest od Jakuba, potom ode všech apoštolů.'),
(1574987,54,46,15,8,'Nejposléze pak ze všech, jakožto nedochůdčeti, ukázal se i mně.'),
(1574988,54,46,15,9,'Nebo já jsem nejmenší z apoštolů, kterýž nejsem hoden slouti apoštol, protože jsem se protivil církvi Boží.'),
(1574989,54,46,15,10,'Ale milostí Boží jsem to, což jsem, a milost jeho mně učiněná daremná nebyla, ale hojněji nežli oni všickni pracoval jsem, avšak ne já, ale milost Boží, kteráž se mnou jest.'),
(1574990,54,46,15,11,'Protož i já i oni tak kážeme, a tak jste uvěřili.'),
(1574991,54,46,15,12,'Poněvadž se pak káže o Kristu, že jest z mrtvých vstal, kterakž někteří mezi vámi praví, že by nebylo z mrtvých vstání?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1574992,54,46,15,13,'Nebo není-liť z mrtvých vstání, anižť jest Kristus z mrtvých vstal.'),
(1574993,54,46,15,14,'A nevstal-liť jest z mrtvých Kristus, tedyť jest daremné kázaní naše, a daremnáť jest i víra vaše.'),
(1574994,54,46,15,15,'A byli bychom nalezeni i křiví svědkové Boží; nebo vydali jsme svědectví o Bohu, že vzkřísil z mrtvých Krista. Kteréhož nevzkřísil, (totiž) jestliže mrtví z mrtvých nevstávají.'),
(1574995,54,46,15,16,'Nebo jestližeť mrtví z mrtvých nevstávají, anižť jest Kristus vstal.'),
(1574996,54,46,15,17,'A nevstal-liť jest z mrtvých Kristus, marná jest víra vaše, ještě jste v hříších vašich.'),
(1574997,54,46,15,18,'A takť i ti, kteříž zesnuli v Kristu, zahynuli.'),
(1574998,54,46,15,19,'Jestližeť pak v tomto životě toliko naději máme v Kristu, nejbídnější jsme ze všech lidí.'),
(1574999,54,46,15,20,'Ale vstalť jest z mrtvých Kristus, prvotiny těch, jenž zesnuli.'),
(1575000,54,46,15,21,'Nebo poněvadž skrze člověka smrt, také i skrze člověka vzkříšení z mrtvých.'),
(1575001,54,46,15,22,'Nebo jakož v Adamovi všickni umírají, tak i skrze Krista všickni obživeni budou.'),
(1575002,54,46,15,23,'Ale jeden každý v svém pořádku: Prvotiny Kristus, potom ti, kteříž jsou Kristovi, v příští jeho.'),
(1575003,54,46,15,24,'Potom bude konec, když vzdá království Bohu a Otci, když vyprázdní všeliké knížatstvo, i všelikou vrchnost i moc.'),
(1575004,54,46,15,25,'Nebo musíť to býti, aby on kraloval, dokudž nepoloží všech nepřátel pod nohy jeho.'),
(1575005,54,46,15,26,'Nejposlednější pak nepřítel zahlazen bude smrt.'),
(1575006,54,46,15,27,'Nebo všecky věci poddal pod nohy jeho. Když pak praví, že všecky věci poddány jsou jemu, zjevnéť jest, že kromě toho, kterýž jemu poddal všecko.'),
(1575007,54,46,15,28,'A když poddáno jemu bude všecko, tedy i on Syn poddá se tomu, kterýž jemu poddati má všecko, aby byl Bůh všecko ve všech.'),
(1575008,54,46,15,29,'Sic jinak co činí ti, kteříž se křtí za mrtvé? Nevstávají-liť mrtví z mrtvých, i proč se křtí za mrtvé?'),
(1575009,54,46,15,30,'Proč i my nebezpečenství trpíme každé hodiny?'),
(1575010,54,46,15,31,'Na každý den umírám, skrze slávu naši, kterouž mám v Kristu Ježíši Pánu našem.'),
(1575011,54,46,15,32,'Jestližeť jsem obyčejem jiných lidí bojoval s šelmami v Efezu, co mi to prospěje, nevstanou-liť mrtví? Tedy jezme a pijme, nebo zítra zemřeme.'),
(1575012,54,46,15,33,'Nedejte se svoditi. Porušujíť dobré obyčeje zlá rozmlouvání.'),
(1575013,54,46,15,34,'Prociťte k konání spravedlnosti, a nehřešte. Nebo někteří ještě neznají Boha; k zahanbení vašemu toto mluvím.'),
(1575014,54,46,15,35,'Ale řekne někdo: Kterakž pak vstanou mrtví? A v jakém těle přijdou?'),
(1575015,54,46,15,36,'Ó nemoudrý, však to, což rozsíváš, nebývá obživeno, leč umře.'),
(1575016,54,46,15,37,'A což rozsíváš, ne to tělo, kteréž potom zroste, rozsíváš, ale holé zrno, jaké se trefí, pšenice nebo kteréžkoli jiné.'),
(1575017,54,46,15,38,'Bůh pak dává jemu tělo, jakž ráčí, a jednomu každému z těch semen jeho vlastní tělo.'),
(1575018,54,46,15,39,'Ne každé tělo jest jednostejné tělo, ale jiné zajisté tělo lidské, jiné tělo hovadí, jiné pak rybí, a jiné ptačí.'),
(1575019,54,46,15,40,'A jsou těla nebeská, a jsou těla zemská, ale jináť jest sláva nebeských, a jiná zemských,'),
(1575020,54,46,15,41,'Jiná sláva slunce, a jiná měsíce, a jiná sláva hvězd; nebo hvězda od hvězdy dělí se v slávě.'),
(1575021,54,46,15,42,'Tak i vzkříšení z mrtvých. Rozsívá se tělo porušitelné, vstane neporušitelné;'),
(1575022,54,46,15,43,'Rozsívá se nesličné, vstane slavné; rozsívá se nemocné, vstane mocné;'),
(1575023,54,46,15,44,'Rozsívá se tělo tělesné, vstane tělo duchovní. Jest tělo tělesné, jest také i duchovní tělo.'),
(1575024,54,46,15,45,'Takť i psáno jest: Učiněn jest první člověk Adam v duši živou, ale poslední Adam v ducha obživujícího.'),
(1575025,54,46,15,46,'Však ne nejprve duchovní, ale tělesné, potom pak duchovní.'),
(1575026,54,46,15,47,'První člověk byl z země zemský, druhý člověk jest sám Pán s nebe.'),
(1575027,54,46,15,48,'Jakýž jest ten zemský, takoví jsou i zemští, a jakýž ten nebeský, takovíž budou také i nebeští.'),
(1575028,54,46,15,49,'A jakož jsme nesli obraz zemského, takť poneseme obraz i nebeského.'),
(1575029,54,46,15,50,'Totoť pak pravím, bratří: Že tělo a krev království Božího dědictví nedosáhnou, aniž porušitelnost neporušitelnosti dědičně obdrží.'),
(1575030,54,46,15,51,'Aj, tajemství vám pravím: Ne všickni zajisté zesneme, ale všickni proměněni budeme, hned pojednou, v okamžení, k zatroubení poslednímu.'),
(1575031,54,46,15,52,'Neboť zatroubí, a mrtví vstanou neporušitelní, a my proměněni budeme.'),
(1575032,54,46,15,53,'Musí zajisté toto porušitelné tělo obléci neporušitelnost, a smrtelné toto obléci nesmrtelnost.'),
(1575033,54,46,15,54,'A když porušitelné toto tělo obleče neporušitelnost, a smrtelné toto obleče nesmrtelnost, tehdy se naplní řeč, kteráž napsána jest: Pohlcena jest smrt v vítězství.'),
(1575034,54,46,15,55,'Kde jest, ó smrti, osten tvůj? Kde jest, ó peklo, vítězství tvé?'),
(1575035,54,46,15,56,'Osten pak smrti jestiť hřích, a moc hřícha jest Zákon.'),
(1575036,54,46,15,57,'Ale Bohu díka, kterýž dal nám vítězství skrze Pána našeho Jezukrista.'),
(1575037,54,46,15,58,'Protož, bratří moji milí, stálí buďte a nepohnutelní, rozhojňujíce se v díle Páně vždycky, vědouce, že práce vaše není daremná v Pánu.'),
(1575038,54,46,16,1,'O sbírce pak na svaté, jakž jsem nařídil v církvích Galatských, tak i vy čiňte.'),
(1575039,54,46,16,2,'V každou neděli jeden každý z vás sám u sebe slož, schovaje podle možnosti, aby ne teprv, když k vám přijdu, sbírky se dály.'),
(1575040,54,46,16,3,'Když pak přijdu, kterékoli osoby schválíte skrze listy, tyť pošli, aby donesli tuto milost vaši do Jeruzaléma.'),
(1575041,54,46,16,4,'Pakliť by bylo potřebí, abych i já šel, půjdouť se mnou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575042,54,46,16,5,'Přijduť pak k vám, když Macedonií projdu; (nebo Macedonií míním projíti.)'),
(1575043,54,46,16,6,'Ale u vásť snad poostanu, aneb i přes zimu pobudu, abyste vy mne doprovodili, kamž bych koli šel.'),
(1575044,54,46,16,7,'Nechci zajisté s vámi se nyní toliko na zastavení shledati, ale naději se, že za nějaký čas pobudu u vás, bude-li Pán chtíti.'),
(1575045,54,46,16,8,'Zůstanuť pak v Efezu až do letnic.'),
(1575046,54,46,16,9,'Nebo otevříny jsou mi tu veliké a mocné dveře, a protivníku mnoho.'),
(1575047,54,46,16,10,'Přišel-liť by pak k vám Timoteus, hleďtež, aby bezpečně byl u vás; neboť dílo Boží dělá jako i já.'),
(1575048,54,46,16,11,'Protož nechť jím žádný nepohrdá, ale vyprovoďte jej v pokoji, ať přijde ke mně; neboť na něj čekám s bratřími.'),
(1575049,54,46,16,12,'O Apollovi pak bratru oznamuji vám, že jsem ho velmi prosil, aby šel k vám s bratřími. Ale nikoli nebyla vůle jeho, aby nyní přišel, než přijdeť, když bude míti čas příhodný.'),
(1575050,54,46,16,13,'Bděte, stůjte u víře, zmužile sobě čiňte a buďtež silní.'),
(1575051,54,46,16,14,'Všecky věci vaše ať se dějí v lásce.'),
(1575052,54,46,16,15,'Prosímť vás pak, bratří, znáte čeled Štěpánovu, že jsou oni prvotiny Achaie, a že jsou se v službu svatým vydali,'),
(1575053,54,46,16,16,'Abyste i vy poddáni byli takovým, i všelikému pomáhajícímu a pracujícímu.'),
(1575054,54,46,16,17,'Těšímť se pak z příchodu Štěpána a Fortunáta a Achaika; nebo nedostatek pro vaši nepřítomnost oni doplnili.'),
(1575055,54,46,16,18,'Potěšili zajisté mého ducha i vašeho. Protož znejtež takové.'),
(1575056,54,46,16,19,'Pozdravujíť vás sborové, kteříž jsou v Azii. Pozdravujíť vás v Pánu velice Akvila a Priscilla, s církví tou, kteráž jest v domu jejich.'),
(1575057,54,46,16,20,'Pozdravují vás všickni bratří. Pozdravte sebe vespolek v políbení svatém.'),
(1575058,54,46,16,21,'Pozdravení vlastní rukou Pavlovou.'),
(1575059,54,46,16,22,'Jestliže kdo nemiluje Pána Jezukrista, budiž proklatý: Maran atha.'),
(1575060,54,46,16,23,'Milost Pána Jezukrista budiž s vámi.'),
(1575061,54,46,16,24,'I láska má v Kristu Ježíši se všemi vámi. Amen.'),
(1575062,54,47,1,1,'Pavel, apoštol Ježíše Krista skrze vůli Boží, a Timoteus bratr, církvi Boží, kteráž jest v Korintu, se všemi svatými, kteříž jsou ve vší Achaii:'),
(1575063,54,47,1,2,'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.'),
(1575064,54,47,1,3,'Požehnaný Bůh a Otec Pána našeho Jezukrista, Otec milosrdenství, a Bůh všelikého potěšení,'),
(1575065,54,47,1,4,'Kterýž těší nás ve všelikém ssoužení našem, abychom i my mohli potěšovati těch, kteříž by byli v jakémkoli ssoužení, a to tím potěšením, kterýmž i my potěšeni jsme od Boha.'),
(1575066,54,47,1,5,'Nebo jakož se rozhojňují utrpení Kristova na nás, tak skrze Krista rozhojňuje se i potěšení naše.'),
(1575067,54,47,1,6,'Nebo buďto že souženi jsme, pro vaše potěšení a spasení souženi jsme, kteréž se působí v snášení týchž trápení, kteráž i my trpíme; buďto že potěšováni býváme, pro vaše potěšení a spasení potěšováni býváme. A naděje naše pevná jest o vás.'),
(1575068,54,47,1,7,'Poněvadž víme, že jakož jste účastníci utrpení, také i potěšení.'),
(1575069,54,47,1,8,'Nechcemeť zajisté, abyste nevěděli, bratří, o soužení našem, kteréž jsme měli v Azii, že jsme nad míru přetíženi byli a nad možnost, tak že jsme již o životu svém byli pochybili.'),
(1575070,54,47,1,9,'Nýbrž sami v sobě již jsme byli tak usoudili, že nebylo lze než umříti, abychom nedoufali sami v sobě, ale v Bohu, jenž i mrtvé křísí.'),
(1575071,54,47,1,10,'Kterýž z takového nebezpečenství smrti vytrhl nás, a vytrhuje, v něhož doufáme, že i ještě vytrhne,'),
(1575072,54,47,1,11,'Když i vy nám pomáhati budete modlitbami za nás, aby z daru toho, příčinou mnohých osob nám daného, od mnohých děkováno bylo Bohu za nás.'),
(1575073,54,47,1,12,'Nebo chlouba naše tato jest, svědectví svědomí našeho, že v sprostnosti a v upřímosti Boží, ne v moudrosti tělesné, ale v milosti Boží obcovali jsme na tomto světě, zvláště pak u vás.'),
(1575074,54,47,1,13,'Neboť nepíšeme vám nic jiného, nežli to, což čtete, aneb což prvé znáte. A naději mám, že až do konce tak znáti budete.'),
(1575075,54,47,1,14,'Jakož jste již i z stránky poznali nás, žeť jsme chlouba vaše, podobně jako i vy naše, v den Pána Ježíše.'),
(1575076,54,47,1,15,'A v tomť doufání chtěl jsem k vám přijíti nejprve, abyste druhou milost měli,'),
(1575077,54,47,1,16,'A skrze vás jíti do Macedonie, a zase z Macedonie přijíti k vám, a potom od vás abych byl doprovozen do Judstva.'),
(1575078,54,47,1,17,'O tom pak když jsem přemyšloval, zdali jsem co lehkomyslně činil? Aneb což přemyšluji, zdali podle těla přemyšluji, tak aby bylo při mně: Jest, jest, není, není?'),
(1575079,54,47,1,18,'Ale víť to věrný Bůh, že řeč naše, kteráž byla mluvena k vám, nebyla: Jest, a není.'),
(1575080,54,47,1,19,'Nebo Syn Boží Ježíš Kristus, kterýž mezi vámi kázán jest skrze nás, totiž skrze mne a Silvána a Timotea, nebyl: Jest, a není, ale bylo v kázání o něm: Jest,'),
(1575081,54,47,1,20,'(Nebo kolikžkoli jest zaslíbení Božích, v němť jsou: Jest, a v němť také jest Amen,) k slávě Bohu skrze nás.'),
(1575082,54,47,1,21,'Ten pak, kterýž potvrzuje nás s vámi v Kristu, a kterýž pomazal nás, Bůh jest.'),
(1575083,54,47,1,22,'Kterýž i znamenal nás, a dal závdavek Ducha svatého v srdce naše.'),
(1575084,54,47,1,23,'Já pak Boha za svědka beru na svou duši, že lituje vás, ještě jsem nepřišel do Korintu.'),
(1575085,54,47,1,24,'Ne jako bychom panovali nad věrou vaší, ale pomocníci jsme radosti vaší; nebo věrou stojíte.'),
(1575086,54,47,2,1,'Toto jsem pak sobě uložil, abych k vám zase s zámutkem nepřišel.'),
(1575087,54,47,2,2,'Nebo jestliže já vás zarmoutím, i kdo jest, ješto by mne obveselil, než ten, kterýž jest ode mne zarmoucen?'),
(1575088,54,47,2,3,'A protoť jsem vám to napsal, abych přijda k vám, neměl zámutku z těch, z nichž bych se měl radovati, doufaje o všech o vás, že radost má jest všech vás radost.'),
(1575089,54,47,2,4,'Nebo z velikého ssoužení a bolesti srdce psal jsem vám, s mnohými slzami, ne abyste zarmouceni byli, ale abyste poznali lásku, kteroužto k vám velikou mám.'),
(1575090,54,47,2,5,'Jestližeť jest pak kdo zarmoutil, ne mneť zarmoutil, ne toliko poněkud, abych jím neobtěžoval všech vás.'),
(1575091,54,47,2,6,'Dostiť má takový na tom trestání, kteréž měl od mnohých,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575092,54,47,2,7,'Tak abyste jemu již raději zase odpustili a potěšili ho, aby on snad přílišným zámutkem nepřišel na zahynutí.'),
(1575093,54,47,2,8,'Protož prosím vás, abyste utvrdili k němu lásku.'),
(1575094,54,47,2,9,'Nebo i proto psal jsem vám, abych zkušením zvěděl, jste-li ve všem poslušni.'),
(1575095,54,47,2,10,'Komuž pak vy co odpouštíte, i já odpouštím. Nebo i já, jestliže jsem co odpustil, komuž jsem odpustil, pro vás odpustil jsem, před obličejem Kristovým, abychom nebyli oklamáni od satana.'),
(1575096,54,47,2,11,'Nebo nejsou nám neznámá myšlení jeho.'),
(1575097,54,47,2,12,'Když jsem pak přišel do Troady, k zvěstování evangelium Kristova, ačkoli dveře mi otevříny byly skrze Pána, však neměl jsem žádného upokojení v duchu svém, protože jsem nenalezl Tita, bratra svého.'),
(1575098,54,47,2,13,'Ale požehnav jich, odšel jsem do Macedonie.'),
(1575099,54,47,2,14,'Bohu pak budiž díka, kterýž vždycky dává nám vítězství v Kristu, a vůni známosti své zjevuje skrze nás na každém místě.'),
(1575100,54,47,2,15,'Neboť jsme Kristova vůně dobrá Bohu v těch, jenž k spasení přicházejí, i v těch, kteříž hynou,'),
(1575101,54,47,2,16,'Těm zajisté jsme vůně smrtelná k smrti, oněm pak vůně života k životu. Ale k tomu kdo jest způsobný?'),
(1575102,54,47,2,17,'Neboť nejsme, jako mnozí, cizoložící slovo Boží, ale jako z upřímnosti, a jako z Boha, před obličejem Božím, o Kristu mluvíme.'),
(1575103,54,47,3,1,'Začínáme opět sami sebe chváliti? Zdaliž potřebujeme, jako někteří, schvalujících listů k vám, nebo od vás k jiným?'),
(1575104,54,47,3,2,'List náš vy jste, napsaný v srdcích našich, kterýž znají a čtou všickni lidé.'),
(1575105,54,47,3,3,'Nebo to zjevné jest, že jste vy list Kristův, zpravený skrze přisluhování naše, napsaný ne černidlem, ale Duchem Boha živého, ne na dskách kamenných, ale na dskách srdce masitých.'),
(1575106,54,47,3,4,'Doufání pak takové máme skrze Krista k Bohu,'),
(1575107,54,47,3,5,'Ne že bychom dostateční byli mysliti něco sami z sebe, jakožto sami z sebe, ale dostatečnost naše z Boha jest.'),
(1575108,54,47,3,6,'Kterýžto i hodné nás učinil služebníky Nového Zákona, ne litery, ale Ducha. Nebo litera zabíjí, ale duch obživuje.'),
(1575109,54,47,3,7,'A poněvadž přisluhování smrti, literami vyryté na dskách kamenných, bylo slavné, tak že nemohli patřiti synové Izraelští v tvář Mojžíšovu, pro slávu oblíčeje jeho, kteráž pominouti měla,'),
(1575110,54,47,3,8,'I kterakž by tedy ovšem přisluhování Ducha nemělo býti slavné?'),
(1575111,54,47,3,9,'Nebo poněvadž přisluhování pomsty slavné bylo, mnohemť se více rozhojňuje v slávě přisluhování spravedlnosti.'),
(1575112,54,47,3,10,'Nebo to, což oslaveno bylo, aniž oslaveno bylo v té částce, u přirovnání převýšené slávy nového přisluhování.'),
(1575113,54,47,3,11,'Nebo poněvadž to pomíjející slavné bylo, mnohemť více to, což zůstává, jestiť slavné.'),
(1575114,54,47,3,12,'Protož majíce takovou naději, mnohé svobody užíváme,'),
(1575115,54,47,3,13,'A ne jako Mojžíš, kterýž kladl zástření na tvář svou, aby nepatřili synové Izraelští k cíli té věci pomíjející.'),
(1575116,54,47,3,14,'Ale ztupeni jsou smyslové jejich. Nebo až do dnešního dne to zastření v čítání Starého Zákona zůstává neodkryté; nebo skrze Krista toliko se odnímá.'),
(1575117,54,47,3,15,'Protož až do dnešního dne, když se čtou knihy Mojžíšovy, zastření jest položeno na jejich srdci.'),
(1575118,54,47,3,16,'Než jakž by se obrátilo ku Pánu, odňato bude zástření.'),
(1575119,54,47,3,17,'Nebo Pán Duch jest, a kdež jest Duch Páně, tuť i svoboda.'),
(1575120,54,47,3,18,'My pak všickni odkrytou tváří slávu Páně jakožto v zrcadle spatřujíce, v týž obraz proměněni býváme od slávy v slávu, jakožto od Ducha Páně.'),
(1575121,54,47,4,1,'Protož majíce toto přisluhování, tak jakž jsme milosrdenství došli, neoblevujeme v něm.'),
(1575122,54,47,4,2,'Ale odmítáme ukrývání neslušnosti, nechodíce v chytrosti, aniž se lstivě obírajíce s slovem Božím, ale zjevováním pravdy v příjemnost uvodíce sebe u každého svědomí lidského před obličejem Božím.'),
(1575123,54,47,4,3,'Pakliť zakryté jest evangelium naše, před těmi, kteříž hynou, zakryté jest.'),
(1575124,54,47,4,4,'V nichžto Bůh světa tohoto oslepil mysli, totiž v nevěrných, aby se jim nezasvítilo světlo evangelium slávy Kristovy, kterýž jest obraz Boží.'),
(1575125,54,47,4,5,'Neboť ne sami sebe kážeme, ale Krista Ježíše Pána, sami pak o sobě pravíme, že jsme služebníci vaši pro Ježíše.'),
(1575126,54,47,4,6,'Bůh zajisté, kterýž rozkázal, aby se z temností světlo zablesklo, tenť jest se osvítil v srdcích našich, k osvícení známosti slávy Boží v tváři Ježíše Krista.'),
(1575127,54,47,4,7,'Mámeť pak poklad tento v nádobách hliněných, aby vyvýšenost moci byla Boží, a ne z nás.'),
(1575128,54,47,4,8,'Myť se všech stran úzkost máme, ale nebýváme cele potlačeni; v divných jsme nesnadnostech, ale nebýváme v tom pohlceni;'),
(1575129,54,47,4,9,'Protivenství trpíme, ale nebýváme opuštěni; býváme opovrženi, ale nehyneme.'),
(1575130,54,47,4,10,'Vždycky mrtvení Pána Ježíše na těle svém nosíme, aby i život Ježíšův na těle našem zjeven byl.'),
(1575131,54,47,4,11,'Vždycky zajisté my, kteříž živi jsme, na smrt býváme vydáváni pro Ježíše, aby i život Ježíšův zjeven byl na smrtelném těle našem.'),
(1575132,54,47,4,12,'A tak smrt v nás moc provodí, ale v vás život.'),
(1575133,54,47,4,13,'Majíce tedy téhož ducha víry, podle toho, jakž psáno jest: Uvěřil jsem, protož jsem mluvil, i myť věříme, protož i mluvíme,'),
(1575134,54,47,4,14,'Vědouce, že ten, kterýž vzkřísil Pána Ježíše, i nás skrze Ježíše vzkřísí a postaví s vámi.'),
(1575135,54,47,4,15,'Nebo to všecko pro vás se děje, aby ta přehojná milost skrze díků činění od mnohých věrných rozmohla se k slávě Boží.'),
(1575136,54,47,4,16,'Protož neoblevujeme, ale ačkoli zevnitřní člověk náš ruší se, však ten vnitřní obnovuje se den ode dne.'),
(1575137,54,47,4,17,'Nebo toto nynější lehoučké ssoužení naše převelmi veliké věčné slávy břímě nám působí,'),
(1575138,54,47,4,18,'Když nepatříme na ty věci, kteréž se vidí, ale na ty, kteréž se nevidí. Nebo ty věci, kteréž se vidí, jsou časné, ale které se nevidí, jsou věčné.'),
(1575139,54,47,5,1,'Víme zajisté, že byl-li by tohoto našeho zemského přebývání stánek zbořen, stavení od Boha máme, příbytek ne rukou udělaný, věčný v nebesích.'),
(1575140,54,47,5,2,'Pročež i v tomto stánku vzdycháme, v příbytek náš, kterýž jest s nebe, oblečeni býti žádajíce,'),
(1575141,54,47,5,3,'Jestliže však oblečení a ne nazí nalezeni budeme.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575142,54,47,5,4,'Nebo kteříž jsme v tomto stánku, lkáme, jsouce obtíženi, poněvadž bychom nechtěli svlečeni býti, ale přiodíni, aby pohlcena byla smrtelnost od života.'),
(1575143,54,47,5,5,'Ten pak, kdož nás tak k tomu způsobil, Bůhť jest, kterýž i dal nám závdavek Ducha svého.'),
(1575144,54,47,5,6,'Protož doufanlivé mysli vždycky jsouce, a vědouce, že dokudž pohostinu jsme v tomto těle, vzdáleni jsme ode Pána,'),
(1575145,54,47,5,7,'(Nebo skrze víru chodíme, a ne skrze vidění tváři Páně,)'),
(1575146,54,47,5,8,'Doufanlivéť pak mysli jsme, a oblibujeme raději vyjíti z těla a přijíti ku Pánu.'),
(1575147,54,47,5,9,'Protož i usilujeme buď v těle pohostinu jsouce, buďto z těla se berouce, jemu se líbiti.'),
(1575148,54,47,5,10,'Všickni my zajisté ukázati se musíme před soudnou stolicí Kristovou, aby přijal jeden každý odplatu za to, což skrze tělo působil, podle toho, jakž práce čí byla, buďto v dobrém, nebo ve zlém.'),
(1575149,54,47,5,11,'Protož znajíce tu hrůzu Páně, lidem k víře sloužíme, Bohuť pak známi jsme. A nadějiť mám, že i svědomí vašemu známi jsme.'),
(1575150,54,47,5,12,'Neboť ne sami sebe opět vám chválíme, ale příčinu vám dáváme, abyste se chlubili námi, a abyste to měli proti těm, kteříž se v tvárnosti chlubí, a ne v srdci.'),
(1575151,54,47,5,13,'Nebo buďto že nesmyslní jsme, Bohu nesmyslní jsme; buď že jsme rozumní, vám rozumní jsme.'),
(1575152,54,47,5,14,'Láska zajisté Kristova víže nás,'),
(1575153,54,47,5,15,'Jakožto ty, kteříž tak soudíme, že poněvadž jeden za všecky umřel, tedyť všickni zemřeli, a že za všecky umřel, aby ti, kteříž živi jsou, již ne sami sobě živi byli, ale tomu, kterýž za ně umřel i z mrtvých vstal.'),
(1575154,54,47,5,16,'A tak my již od toho času žádného neznáme podle těla. A ačkoli jsme poznali Krista podle těla, ale nyní již více neznáme.'),
(1575155,54,47,5,17,'Protož jest-li kdo v Kristu, nové stvoření jest. Staré věci pominuly, aj, nové všecko učiněno jest.'),
(1575156,54,47,5,18,'To pak všecko jest z Boha, kterýž smířil nás s sebou skrze Jezukrista, a dal nám služebnost smíření tohoto.'),
(1575157,54,47,5,19,'Nebo Bůh byl v Kristu, smířuje svět s sebou, nepočítaje jim hříchů jejich, a složil v nás to slovo smíření.'),
(1575158,54,47,5,20,'Protož my na místo Krista poselství dějeme; a jako by Bůh skrze nás žádal vás, prosíme na místě Kristově, smiřte se s Bohem.'),
(1575159,54,47,5,21,'Nebo toho, kterýž hříchu nepoznal, za nás učinil hříchem, abychom my učiněni byli spravedlností Boží v něm.'),
(1575160,54,47,6,1,'Protož napomáhajíce, i napomínáme vás, abyste milosti Boží nadarmo nebrali,'),
(1575161,54,47,6,2,'(Neboť praví Bůh: V čas příhodný uslyšel jsem tě a v den spasení spomohl jsem tobě. Aj, nyníť jest čas příhodný, aj, nyní dnové spasení.)'),
(1575162,54,47,6,3,'Žádného v ničemž nedávajíce pohoršení, aby byla bez úhony služba naše;'),
(1575163,54,47,6,4,'Ale ve všem se chovajíce jakožto Boží služebníci, ve mnohé trpělivosti, v utištěních, v nedostatcích, v úzkostech,'),
(1575164,54,47,6,5,'V ranách, v žalářích, v nepokojích, v pracech, v bdění, v postech,'),
(1575165,54,47,6,6,'V čistotě, v umění, v dlouhočekání, v dobrotivosti, v Duchu svatém, v lásce neošemetné,'),
(1575166,54,47,6,7,'V slovu pravdy, v moci Boží, skrze odění spravedlnosti, napravo i nalevo,'),
(1575167,54,47,6,8,'Skrze slávu i pohanění, skrze zlou i dobrou pověst, jakožto bludní, a jsouce pravdomluvní,'),
(1575168,54,47,6,9,'Jakožto neznámí, a jsouce známí, jakožto umírající, a aj, živi jsme, jakožto potrestaní, a nezmordovaní,'),
(1575169,54,47,6,10,'Jako smutní, avšak vždycky se radujíce, jako chudí, a mnohé zbohacujíce, jako nic nemajíce, avšak všemi věcmi vládnouce.'),
(1575170,54,47,6,11,'Ústa naše otevřína jsou k vám, ó Korinští, srdce naše rozšířeno jest.'),
(1575171,54,47,6,12,'Nejste v nás souženi, než souženi jste v srdcích vašich.'),
(1575172,54,47,6,13,'O takovéžť odplaty žádám od vás, jakožto synům pravím: Rozšiřte se i vy.'),
(1575173,54,47,6,14,'A netáhněte jha s nevěřícími. Nebo jaký jest spolek spravedlnosti s nepravostí? A jaké obcování světla s temnostmi?'),
(1575174,54,47,6,15,'A jaké srovnání Krista s Beliálem? Aneb jaký díl věřícímu s nevěřícím?'),
(1575175,54,47,6,16,'A jaké spolčení chrámu Božího s modlami? Nebo vy jste chrám Boha živého, jakož pověděl Bůh: Že přebývati budu v nich, a procházeti se, a budu jejich Bohem, a oni budou mým lidem.'),
(1575176,54,47,6,17,'A protož vyjdětež z prostředku jejich a oddělte se od nich, praví Pán; a nečistého se nedotýkejte, a já přijmu vás.'),
(1575177,54,47,6,18,'A budu vám za Otce, a vy mi budete za syny a za dcery, praví Pán všemohoucí.'),
(1575178,54,47,7,1,'Taková tedy majíce zaslíbení, nejmilejší, očišťujmež se od všeliké poskvrny těla i ducha, konajíce posvěcení naše v bázni Boží.'),
(1575179,54,47,7,2,'Přijmětež nás. Žádnémuť jsme neublížili, žádnému neuškodili, žádného neoklamali.'),
(1575180,54,47,7,3,'Nepravím toho ku potupě vaší, poněvadž jsem napřed pověděl, že v srdcích našich jste, tak abychom hotovi byli spolu s vámi zemříti i spolu živi býti.'),
(1575181,54,47,7,4,'Mnohéť jsem k vám důvěrnosti, mnohoť se vámi chlubím; naplněn jsem potěšením, a rozhojňujiť se v radosti ve všelikém soužení našem.'),
(1575182,54,47,7,5,'Nebo i když jsme byli přišli do Macedonie, žádného odpočinutí nemělo tělo naše, ale ve všem souženi jsme byli; měli jsme zevnitř boje, vnitř strachy.'),
(1575183,54,47,7,6,'Ale ten, jenž těší ponížené, potěšil nás, Bůh, skrze Titův příchod.'),
(1575184,54,47,7,7,'A netoliko příchodem jeho, ale také i potěšením tím, kteréž on měl z vás, vypravovav nám o vaší veliké žádosti nás, o vašem kvílení, a vaší ke mně horlivé milosti, takže jsem se velmi zradoval.'),
(1575185,54,47,7,8,'A ačkoli zarmoutil jsem vás listem, nelituji toho, ač jsem byl litoval. Nebo vidím, že ten list, ačkoli na čas, zarmoutil vás.'),
(1575186,54,47,7,9,'Ale nyní raduji se, ne že jste zarmouceni byli, ale že jste se ku pokání zarmoutili. Zarmoutili jste se zajisté podle Boha, takže jste k žádné škodě nepřišli skrze nás.'),
(1575187,54,47,7,10,'Nebo zámutek, kterýž jest podle Boha, ten pokání k spasení působí takové, jehož nikdy líto nebude, ale zámutek světa způsobuje smrt.'),
(1575188,54,47,7,11,'Ano hle, to samo, že jste podlé Boha zarmouceni byli, kterakou v vás způsobilo snažnost, nýbrž jakou omluvu, nýbrž zažhnutí hněvu, nýbrž bázeň, nýbrž žádost vroucí, nýbrž horlivost, anobrž pomstu? A Všelijak ukázali jste se nevinni býti v té příhodě.'),
(1575189,54,47,7,12,'A ač psal jsem vám, však ne pro toho jsem psal, kterýž tu nepravost spáchal, ani pro toho, komuž se křivda stala, ale aby vám zjevena byla pilnost naše o vás před obličejem Božím.'),
(1575190,54,47,7,13,'Protož potěšeniť jsme z potěšení vašeho. Ale mnohem hojněji zradovali jsme se z radosti Titovy, že poočerstven jest duch jeho ode všech vás,'),
(1575191,54,47,7,14,'A že chlubil-li jsem se v čem vámi před ním, nebyl jsem zahanben, ale jakož všecko mluvili jsme vám v pravdě, tak i chlouba naše, kteráž byla před Titem, pravá jest shledána.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575192,54,47,7,15,'A hojněji i srdce jeho jest k vám obráceno, nebo rozpomíná se na poslušenství všech vás, a kterak jste ho s bázní a s strachem přijali.'),
(1575193,54,47,7,16,'Raduji se pak, že ve všem mám o vás doufání.'),
(1575194,54,47,8,1,'Známuť pak vám činíme, bratří, milost Boží, danou zborům Macedonským,'),
(1575195,54,47,8,2,'Že v mnohém zkušení rozličných soužení rozhojnilá radost jejich a převeliká chudoba jejich rozhojněna jest v bohatství upřímnosti jejich.'),
(1575196,54,47,8,3,'Nebo svědectví jim vydávám, že podle možnosti, ba i nad možnost hotovi byli sděliti se,'),
(1575197,54,47,8,4,'Mnohými žádostmi prosíce nás, abychom té milosti jejich a obcování služebnost (v rozdělování toho svatým) na se přijali.'),
(1575198,54,47,8,5,'A netoliko tak učinili, jakž jsme se nadáli, ale sami sebe nejprve dali Pánu, a i nám také u vůli Boží,'),
(1575199,54,47,8,6,'Tak že jsme musili napomenouti Tita, aby jakož byl prve započal, tak také i dokonal při vás milost tuto.'),
(1575200,54,47,8,7,'A protož jakž ve všech věcech jste hojní, totiž u víře i v řeči i v známosti i ve všeliké snažnosti i v lásce vaší k nám, tak i v této milosti hojní buďte.'),
(1575201,54,47,8,8,'Ne jako rozkazuje, toto pravím, ale příčinou jiných snažnosti i vaši upřímou lásku zkušenou ukázati chtěje.'),
(1575202,54,47,8,9,'Nebo znáte milost Pána našeho Jezukrista, že pro vás učiněn jest chudý, jsa bohatý, abyste vy jeho chudobou zbohatli.'),
(1575203,54,47,8,10,'A k tomuť vám radu dávám; nebo jest vám to užitečné, kteříž jste netoliko činiti, ale i chtíti prve začali léta předešlého.'),
(1575204,54,47,8,11,'Protož nyní již to skutkem vykonejte, aby jakož hotové bylo chtění, tak také bylo i vykonání z toho, což máte.'),
(1575205,54,47,8,12,'Nebo jest-liť prve vůle hotová, podle toho, což kdo má, vzácná jest Bohu, ne podle toho, čehož nemá.'),
(1575206,54,47,8,13,'Nebo ne proto vás ponoukám, aby jiným bylo polehčení, a vám soužení, ale rovnost ať jest; nyní přítomně vaše hojnost spomoziž jejich chudobě,'),
(1575207,54,47,8,14,'Aby potom také jejich hojnost vaší chudobě byla ku pomoci, aby tak byla rovnost;'),
(1575208,54,47,8,15,'Jakož psáno: Kdo mnoho nasbíral, nic mu nezbývalo, a kdo málo, neměl nedostatku.'),
(1575209,54,47,8,16,'Ale díka Bohu, kterýž takovouž snažnost k službě vám dal v srdce Titovo,'),
(1575210,54,47,8,17,'Takže to napomenutí naše ochotně přijal, anobrž jsa v lásce k vám opravdový, sám z své dobré vůle šel k vám.'),
(1575211,54,47,8,18,'Poslaliť jsme pak s ním bratra toho, kterýž má velikou chválu v evangelium po všech sbořích,'),
(1575212,54,47,8,19,'(A netoliko to, ale také losem vyvolen jest od církví za tovaryše putování našeho, s touto milostí, kteroužto sloužíme k slávě Pánu a k vyplnění vůle vaší,)'),
(1575213,54,47,8,20,'Varujíce se toho, aby nám někdo neutrhal pro tu hojnost, kterouž my přisluhujeme,'),
(1575214,54,47,8,21,'Dobré opatrujíce netoliko před obličejem Páně, ale i před lidmi.'),
(1575215,54,47,8,22,'Poslali jsme pak s nimi bratra našeho, kteréhož jsme mnohokrát ve mnohých věcech zkusili, že jest pilný, a nyní mnohem pilnější bude pro mnohé doufání mé o vás.'),
(1575216,54,47,8,23,'Z strany Tita víte, že jest tovaryš můj, a mezi vámi pomocník můj; a z strany bratří našich, že jsou poslové církví a sláva Kristova.'),
(1575217,54,47,8,24,'Protož jistoty lásky vaší a chlouby naší o vás, k nim dokažte, před obličejem církví.'),
(1575218,54,47,9,1,'Nebo o pomoci, kteráž se sbírá na svaté, jest zbytečné psáti vám.'),
(1575219,54,47,9,2,'Vím zajisté o vaší hotovosti, pro kteroužto chlubím se vámi u Macedonských, kterak by Achaia hotova byla k tomu od předešlého léta. A ta z vás pošlá horlivost mnohými k témuž pohnula.'),
(1575220,54,47,9,3,'I poslal jsem k vám tyto bratří, aby chlouba naše vámi nebyla marná v té stránce, ale abyste, (jakž jsem řekl,) byli hotovi,'),
(1575221,54,47,9,4,'Abychom snad, přišli-li by se mnou Macedonští, a nalezli vás nehotové, nemusili se styděti, (ať nedím vy) za takovou chloubu.'),
(1575222,54,47,9,5,'Protož vidělo mi se za potřebné těchto bratří napomenouti, aby předešli mne k vám, a připravili prve opověděnou sbírku vaši, aby byla hotová jako dobrovolná sbírka, a ne jako bezděčná.'),
(1575223,54,47,9,6,'Ale totoť pravím: Kdo skoupě rozsívá, skoupě i žíti bude; a kdož rozsívá ochotně, ochotně i žíti bude.'),
(1575224,54,47,9,7,'Jeden každý jakž uložil v srdci svém, tak učiň, ne s neochotnou myslí anebo z mušení. Neboť ochotného dárce miluje Bůh.'),
(1575225,54,47,9,8,'Mocenť jest pak Bůh všelikou milost rozhojniti v vás, abyste ve všem všudy všelikou dostatečnost majíce, hojní byli ke všelikému skutku dobrému,'),
(1575226,54,47,9,9,'Jakož psáno jest: Rozsypal a dal chudým, spravedlnost jeho zůstává na věky.'),
(1575227,54,47,9,10,'Ten pak, kterýž dává símě rozsívajícímu, dejž i vám chléb k jedení, a rozmnožiž símě vaše, a přispořiž úrody spravedlnosti vaší,'),
(1575228,54,47,9,11,'Abyste všelijak zbohaceni byli ke všeliké sprostnosti, kterážto působí skrze nás, aby díky činěny byly Bohu.'),
(1575229,54,47,9,12,'Nebo služba oběti této netoliko doplňuje nedostatky svatých, ale také rozhojňuje se v mnohé díků činění Bohu, příčinou schválení služby této,'),
(1575230,54,47,9,13,'Když chválí Boha z jednomyslné poddanosti vaší k evangelium Kristovu, a z upřímé pomoci jim i všechněm učiněné,'),
(1575231,54,47,9,14,'A modlí se za vás ti, kteříž vás převelice milují pro vyvýšenou milost Boží v vás.'),
(1575232,54,47,9,15,'Díka pak budiž Bohu z nevymluvného daru jeho.'),
(1575233,54,47,10,1,'Já pak sám Pavel prosím vás skrze tichost a dobrotivost Kristovu, kterýžto v přítomnosti u vás jsem pokorný, ale v nepřítomnosti směle dověrný jsem k vám.'),
(1575234,54,47,10,2,'Prosím pak vás za to, abych přítomen jsa, nemusil doufanlivý býti tou smělostí, kterouž jsem jmín, že bych smělý byl proti některým, kteříž za to mají, že bychom my podle těla chodili.'),
(1575235,54,47,10,3,'V těle zajisté chodíce, ne podle těla rytěřujeme,'),
(1575236,54,47,10,4,'Nebo odění rytěřování našeho není tělesné, ale mocné v Bohu k vyvrácení ohrad,'),
(1575237,54,47,10,5,'Jímžto podvracíme rady, i všelikou vysokost, povyšující se proti umění Božímu, jímajíce všelikou mysl v poddanost Kristu,'),
(1575238,54,47,10,6,'A nahotově majíce pomstu proti každému neposlušenství, když naplněno bude vaše poslušenství.'),
(1575239,54,47,10,7,'A což toliko na to, co před očima jest, hledíte? Má-li kdo tu naději o sobě, že by Kristův byl, pomysliž také na to sám u sebe, že jakož on jest Kristův, tak i my Kristovi jsme.'),
(1575240,54,47,10,8,'Nebo bychť se pak i ještě hojněji chlubil mocí naší, kterouž nám dal Pán vzdělání a ne k zkažení vašemu, nebuduť zahanben;'),
(1575241,54,47,10,9,'Abych se nezdál listy strašiti vás.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575242,54,47,10,10,'Nebo listové jeho (dí někdo) jsou těžcí a mocní, ale přítomnost osobná jest mdlá, a řeč chaterná.'),
(1575243,54,47,10,11,'Toto nechať myslí takový, že jacíž jsme v slovu skrze psání, vzdáleni jsouce od vás, takoví také budeme i v skutku, přijdouce k vám.'),
(1575244,54,47,10,12,'Neboť my se neodvažujeme přimísiti aneb přirovnati k některým, kteříž sami sebe chválí. Ale ti nerozumějí, že sami sebou sebe měří a přirovnávají sebe sobě.'),
(1575245,54,47,10,13,'My pak nebudeme se nad to, což nám není odměřeno, chlubiti, ale podle míry pravidla, kteroužto míru odměřil nám Bůh, chlubiti se budeme, totiž že jsme dosáhli až k vám.'),
(1575246,54,47,10,14,'Nebo ne jako bychom nedosáhli až k vám, rozšiřujeme se nad míru. Až i k vám zajisté přišli jsme v evangelium Kristovu.'),
(1575247,54,47,10,15,'Protož my se nad to, což nám není odměřeno, nechlubíme, totiž cizími pracemi, ale naději máme, když víra vaše růsti bude v vás, že my se rozšíříme dále podle toho, jakž nám odměřeno,'),
(1575248,54,47,10,16,'Totiž, abych ještě i na těch místech, kteráž jsou za vámi dále, kázal evangelium, a ne abych v tom, což jinému odměřeno jest, a již jest hotové, se chlubil.'),
(1575249,54,47,10,17,'Ale kdo se chlubí, v Pánu se chlub.'),
(1575250,54,47,10,18,'Nebo ne ten, kdož se sám chválí, zkušený jest, ale ten, kohož Pán chválí.'),
(1575251,54,47,11,1,'Ó byste mne maličko posnesli v nemoudrosti mé, nýbrž posneste mne.'),
(1575252,54,47,11,2,'Neboť miluji vás Božím milováním. Zasnoubilť jsem zajisté vás jako čistou pannu oddati jednomu muži, Kristu.'),
(1575253,54,47,11,3,'Ale bojímť se, aby snad, jakož had svedl Evu chytrostí svou, tak nebyly porušeny mysli vaše, abyste se totiž neuchýlili od sprostnosti, kteráž jest v Kristu.'),
(1575254,54,47,11,4,'Nebo kdyby někdo přijda, jiného Ježíše vám kázal, kteréhož jsme my nekázali, aneb kdybyste jiného ducha přijali, kteréhož jste prve nepřijali, anebo jiné evangelium, kteréhož jste od nás nevzali, slušně byste to snášeli.'),
(1575255,54,47,11,5,'Neboť za to mám, že jsem nic menší nebyl velikých apoštolů.'),
(1575256,54,47,11,6,'Jestližeť pak jsem nedospělý v řeči, však ne v umění, ale ve všem všudy otevření jsme vám.'),
(1575257,54,47,11,7,'Zdali jsem zhřešil, ponižuje se, abyste vy povýšeni byli, a že jsem darmo evangelium Boží kázal vám?'),
(1575258,54,47,11,8,'Jiné jsem církve loupil, bera od nich plat k službě vaší. A byv u vás, jsa potřeben, neobtěžoval jsem žádného.'),
(1575259,54,47,11,9,'Nebo ten nedostatek můj doplnili bratří, přišedše z Macedonie. A ve všech věcech varoval jsem se, a varovati budu, abych vás neobtěžoval.'),
(1575260,54,47,11,10,'Jestiť pravda Kristova ve mně, že chlouba tato nebude mi zmařena v krajinách Achaiských.'),
(1575261,54,47,11,11,'Z které příčiny? Snad že vás nemiluji? Bůhť ví.'),
(1575262,54,47,11,12,'Ale což činím, ještěť činiti budu, abych odňal příčinu těm, kteříž hledají příčiny k tomu, aby v tom, v čemž se chlubí, nalezeni byli takoví jako i my.'),
(1575263,54,47,11,13,'Nebo takoví falešní apoštolé jsou dělníci lstiví, proměňujíce se v apoštoly Kristovy.'),
(1575264,54,47,11,14,'A není div. Nebo i satan proměňuje se v anděla světlosti.'),
(1575265,54,47,11,15,'Protož neníť to tak veliká věc, jestliže i služebníci jeho proměňují se, aby se zdáli býti služebníci spravedlnosti, jichžto konec bude podle skutků jejich.'),
(1575266,54,47,11,16,'Opět pravím, aby mne někdo neměl za nemoudrého; nýbrž i jako nemoudrého přijměte mne, ať i já se maličko něco pochlubím.'),
(1575267,54,47,11,17,'Což mluvím, nemluvímť jako ode Pána, ale jako v nemoudrosti z strany této chlouby.'),
(1575268,54,47,11,18,'Kdyžť se mnozí chlubí podle těla, i jáť se pochlubím.'),
(1575269,54,47,11,19,'Rádi zajisté snášíte nemoudré, jsouce sami moudří.'),
(1575270,54,47,11,20,'Nebo snesete i to, by vás kdo v službu podrobil, by kdo zžíral, by kdo bral, by se kdo pozdvihoval, by vás kdo v tvář bil.'),
(1575271,54,47,11,21,'K zahanbení vašemu pravím, rovně jako bychom my nějací špatní byli. Nýbrž v čem kdo smí, (v nemoudrosti mluvím,) smímť i já.'),
(1575272,54,47,11,22,'Židé jsou? Jsem i já Žid. Izraelští jsou? Jsem i já. Símě Abrahamovo jsou? I já.'),
(1575273,54,47,11,23,'Služebníci Kristovi jsou? (Nemoudře dím:) Nadto já. V pracech býval jsem hojněji, v ranách přílišně, v žalářích hojněji, v smrtech častokrát.'),
(1575274,54,47,11,24,'Od Židů pětkrát čtyřidceti ran bez jedné trpěl jsem.'),
(1575275,54,47,11,25,'Třikrát metlami mrskán jsem, jednou jsem byl ukamenován, třikrát jsem na moři tonul, ve dne i v noci v hlubokosti mořské byl jsem.'),
(1575276,54,47,11,26,'Na cestách často, v nebezpečenství na řekách, v nebezpečenství od lotrů, v nebezpečenství od svého pokolení, v nebezpečenství od pohanů, v nebezpečenství v městě, v nebezpečenství na poušti, v nebezpečenství na moři, v nebezpečenství mezi falešnými bratřími;'),
(1575277,54,47,11,27,'V práci a v ustání, v bděních často, v hladu a v žízni, v postech častokrát, na zimě a v nahotě.'),
(1575278,54,47,11,28,'Kromě toho, což zevnitř jest, dotírá na mne ten houf na každý den povstávající proti mně, to jest péče o všecky sbory.'),
(1575279,54,47,11,29,'Kdo umdlévá, abych já s ním nemdlel? Kdo se uráží, abych já se nepálil?'),
(1575280,54,47,11,30,'Jestližeť se mám chlubiti, nemocmi svými se chlubiti budu.'),
(1575281,54,47,11,31,'Bůh a Otec Pána našeho Jezukrista, kterýž jest požehnaný na věky, ví, žeť nelhu.'),
(1575282,54,47,11,32,'Hejtman v Damašku lidu Aréty krále, ostříhal města Damašku, chtěje mne do vězení vzíti.'),
(1575283,54,47,11,33,'Ale já oknem po provaze spuštěn jsem v koši přes zed, i ušel jsem rukou jeho.'),
(1575284,54,47,12,1,'Ale chlubiti mi se není dobré, nebo přišel bych k vypravování o viděních a zjeveních Páně.'),
(1575285,54,47,12,2,'Znám člověka v Kristu před lety čtrnácti, (v těle-li, nevím, čili krom těla, nevím, Bůhť ví,) kterýž byl vtržen až do třetího nebe.'),
(1575286,54,47,12,3,'A vím takového člověka, (bylo-li v těle, čili krom těla, nevím, Bůh ví),'),
(1575287,54,47,12,4,'Že jest byl vtržen do ráje, a slyšel nevypravitelná slova, kterýchž nesluší člověku mluviti.'),
(1575288,54,47,12,5,'Takovým budu se chlubiti, ale sám sebou nechci se chlubiti, než toliko nemocmi svými.'),
(1575289,54,47,12,6,'Nebo budu-li se chtíti chlubiti, nebuduť proto nemoudrým, nebo pravdu povím; ale uskrovnímť, aby někdo nesmýšlel více, nežli vidí při mně, aneb slyší ode mne.'),
(1575290,54,47,12,7,'A abych se vysokostí zjevení nad míru nepozdvihl, dán mi jest osten do těla, totiž anděl satan, aby mne poličkoval, abych se nad míru nepovyšoval.'),
(1575291,54,47,12,8,'Za to třikrát jsem Pána prosil, aby to odstoupilo ode mne.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575292,54,47,12,9,'Ale řekl mi: Dosti máš na mé milosti, neboť moc má v nemoci dokonává se. Nejraději tedy chlubiti se budu nemocmi svými, aby ve mně přebývala moc Kristova.'),
(1575293,54,47,12,10,'Protož libost mám v nemocech svých, v pohaněních, v nedostatcích, v protivenstvích, a v úzkostech, pro Krista. Nebo když mdlím, tedy silen jsem.'),
(1575294,54,47,12,11,'Učiněn jsem nemoudrým, chlubě se; vy jste mne k tomu přinutili. Neb já od vás měl jsem chválen býti; neboť jsem nic menší nebyl velikých apoštolů, ačkoli nic nejsem.'),
(1575295,54,47,12,12,'Znamení zajisté apoštolství mého prokázána jsou mezi vámi ve vší trpělivosti, i v divích a v zázracích, a v mocech.'),
(1575296,54,47,12,13,'Neb co jest, čeho byste vy méně měli nežli jiné církve, leč to, že jsem já vás neobtěžoval? Odpusťtež mi to bezpráví.'),
(1575297,54,47,12,14,'Aj, již potřetí hotov jsem přijíti k vám, a nebuduť vás obtěžovati. Nebo nehledám toho, což jest vašeho, ale vás. Neboť nemají synové rodičům pokladů shromažďovati, ale rodičové synům.'),
(1575298,54,47,12,15,'Jáť pak velmi rád náklad učiním, i sám se vynaložím za duše vaše, ačkoli velmi vás miluje, málo jsem milován.'),
(1575299,54,47,12,16,'Ale nechťž jest tak, že jsem já vás neobtěžoval, než chytrý jsa, lstí jsem vás zjímal.'),
(1575300,54,47,12,17,'Zdali skrze někoho z těch, kteréž jsem poslal k vám, obloupil jsem vás?'),
(1575301,54,47,12,18,'Dožádal jsem se Tita, a poslal jsem s ním bratra toho. Zdali vás Titus podvedl? Zdaliž jsme jedním duchem nechodili? Zdaliž ne jedněmi šlépějemi?'),
(1575302,54,47,12,19,'A zase domníváte-li se, že my se vymlouváme před vámi? Před obličejemť Božím v Kristu mluvíme, a to všecko, nejmilejší, k vašemu vzdělání.'),
(1575303,54,47,12,20,'Neboť se bojím, abych snad přijda k vám, nenalezl vás takových, jakýchž bych nechtěl, a já nebyl nalezen od vás, jakéhož byste vy nechtěli, aby snad nebyli mezi vámi svárové, závistí, hněvové, vády, utrhání, reptání, nadýmání, různice,'),
(1575304,54,47,12,21,'Aby mne opět, když bych přišel, neponížil Bůh můj u vás, a plakal bych mnohých z těch, kteříž jsou prve hřešili, a nečinili pokání z nečistoty, a z smilstva, a z nestydatosti, kterouž páchali.'),
(1575305,54,47,13,1,'Toto již po třetí jdu k vám, a v ústech dvou neb tří svědků staneť každé slovo.'),
(1575306,54,47,13,2,'Předpovědělť jsem, a předpovídám po druhé jako přítomný, a nepřítomný nyní píši těm, kteříž prve hřešili, i jiným všechněm, že přijdu-liť opět znovu, neodpustím,'),
(1575307,54,47,13,3,'Poněvadž zkusiti hledáte toho, kterýž skrze mne mluví, Krista, kterýžto k vám není nemocný, ale mocný jest v vás.'),
(1575308,54,47,13,4,'Nebo ačkoli ukřižován jest jako nemocný, ale živ jest z moci Boží. A tak i my mdlí jsme s ním, ale živi budeme s ním, z moci Boží vztahující se až k vám.'),
(1575309,54,47,13,5,'Sami sebe zkušujte, jste-li u víře; sami sebe ohledujte. Čili sami sebe neznáte, že Ježíš Kristus jest v vás? Leč jste snad zavrženi.'),
(1575310,54,47,13,6,'Ale naději mám, žeť poznáte, žeť my nejsme zavrženi.'),
(1575311,54,47,13,7,'Modlímť se pak Bohu, abyste nic zlého nečinili, ne proto, abychom my se dokonalí ukázali, ale abyste vy to, což jest dobrého, činili, my pak jako zavržení abychom byli.'),
(1575312,54,47,13,8,'Neboť nic nemůžeme proti pravdě, ale k pravdě.'),
(1575313,54,47,13,9,'Radujeme se zajisté, že ač jsme mdlí, ale vy jste silní, a za toť se i modlíme, abyste vy byli dokonalí.'),
(1575314,54,47,13,10,'Protož toto nepřítomný jsa, píši, abych snad potom přítomen jsa, nemusil býti přísný, podle moci, kterouž mi dal Pán k vzdělání, a ne k zkáze.'),
(1575315,54,47,13,11,'Naposledy, bratří mějtež se dobře, dokonalí buďte, potěšujte se, jednostejně smyslte, pokoj mějte. A Bůh lásky a pokoje budeť s vámi.'),
(1575316,54,47,13,12,'Pozdravtež jedni druhých políbením svatým. Pozdravují vás všickni svatí.'),
(1575317,54,47,13,13,'Milost Pána Jezukrista, a láska Boží, a účastenství Ducha svatého budiž se všemi vámi. Amen.'),
(1575318,54,48,1,1,'Pavel apoštol, (ne od lidí, ani skrze člověka, ale skrze Jezukrista, a Boha Otce, kterýž jej vzkřísil z mrtvých,)'),
(1575319,54,48,1,2,'I ti, kteříž jsou se mnou, všickni bratří sborům Galatským:'),
(1575320,54,48,1,3,'Milost vám a pokoj od Boha Otce a Pána našeho Jezukrista,'),
(1575321,54,48,1,4,'Kterýž vydal sebe samého za hříchy naše, aby nás vytrhl z tohoto přítomného věku zlého, podle vůle Boha a Otce našeho,'),
(1575322,54,48,1,5,'Jemuž buď sláva na věky věků. Amen.'),
(1575323,54,48,1,6,'Divím se tomu, že tak rychle od toho, kterýž vás povolal v milost Kristovu, uchýlili jste se k jinému evangelium,'),
(1575324,54,48,1,7,'Kteréž není jiné, ale jsou někteří, ješto vás kormoutí a převrátiti chtějí evangelium Kristovo.'),
(1575325,54,48,1,8,'Ale bychom pak i my neb anděl s nebe kázal vám mimo to, což jsme vám kázali, prokletý buď.'),
(1575326,54,48,1,9,'Jakož jsme již pověděli, a ještě znovu pravím: Jestliže by vám kdo co jiného kázal mimo to, což jste přijali, prokletý buď.'),
(1575327,54,48,1,10,'Nebo lidské-liž věci, čili Boží předkládám? Zdaliž lidem se líbiti hledám? Kdybych se zajisté ještě lidem zaliboval, služebník Kristův bych nebyl.'),
(1575328,54,48,1,11,'Oznamujiť pak vám, bratří, že evangelium to, kteréž kázáno jest ode mne, není podle člověka.'),
(1575329,54,48,1,12,'Nebo aniž jsem já ho přijal od člověka, ani se naučil, ale skrze zjevení Ježíše Krista.'),
(1575330,54,48,1,13,'Slýchali jste zajisté o mém obcování někdejším v Židovstvu, kterak jsem se velice protivil církvi Boží a hubil jsem ji,'),
(1575331,54,48,1,14,'A že jsem prospíval v Židovstvu nad mnohé mně rovné v pokolení mém, byv velmi horlivý milovník otcovských ustanovení.'),
(1575332,54,48,1,15,'Ale když se zalíbilo Bohu, kterýž mne byl oddělil z života matky mé a povolal skrze milost svou,'),
(1575333,54,48,1,16,'Zjeviti Syna svého mně, abych jej kázal mezi pohany, hned jsem se neporadil s tělem a krví;'),
(1575334,54,48,1,17,'Aniž jsem se vrátil do Jeruzaléma k těm, jenž prve byli apoštolé nežli já, ale šel jsem do Arabie, přišel jsem pak zase do Damašku.'),
(1575335,54,48,1,18,'Potom po třech letech navrátil jsem se do Jeruzaléma, abych navštívil Petra, a pobyl jsem u něho patnácte dní.'),
(1575336,54,48,1,19,'Jiného pak z apoštolů žádného jsem neviděl než Jakuba, bratra Páně.'),
(1575337,54,48,1,20,'Cožť pak píši vám, aj, před Bohem osvědčuji, žeť neklamám.'),
(1575338,54,48,1,21,'Potom přišel jsem do krajin Syrských a Cilických.'),
(1575339,54,48,1,22,'A nebyl jsem známý osobou sborům Židovským, kteříž byli v Kristu,'),
(1575340,54,48,1,23,'Než toliko slýchali o mně: Že ten, kterýž se nám někdy protivil, již nyní káže víru, kterouž někdy hubil.'),
(1575341,54,48,1,24,'A slavili ve mně Boha.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575342,54,48,2,1,'Potom po čtrnácti letech opět vstoupil jsem do Jeruzaléma s Barnabášem, pojav s sebou i Tita.'),
(1575343,54,48,2,2,'Vstoupil jsem pak podle zjevení, a vypravoval jsem jim evangelium, kteréž káži mezi pohany, a zvláště pak znamenitějším, abych snad nadarmo neběžel nyní i prve.'),
(1575344,54,48,2,3,'Ale ani Titus, kterýž se mnou byl, pohan byv, nebyl přinucen obřezati se,'),
(1575345,54,48,2,4,'Totiž pro podešlé falešné bratří, kteříž se byli vloudili k vyšpehování svobody naší, kterouž máme v Kristu Ježíši, aby nás v službu podrobili.'),
(1575346,54,48,2,5,'Kterýmžto ani na chvilku neustoupili jsme a nepoddali se, aby pravda evangelium zůstala u vás.'),
(1575347,54,48,2,6,'Od těch pak, kteříž se zdadí něco býti, nic mi není přidáno, ač jací jsou někdy byli, mně potom nic není, Bůhť osoby člověka nepřijímá; ti, pravím, kteříž se něco zdadí býti, nic mi nepřidali.'),
(1575348,54,48,2,7,'Nýbrž naodpor, když uzřeli, že jest mi svěřeno evangelium, abych je kázal neobřezaným, jako i Petrovi mezi Židy,'),
(1575349,54,48,2,8,'(Nebo ten, kterýž mocný byl skrze Petra z strany apoštolství mezi Židy, byl mocný i skrze mne mezi pohany,)'),
(1575350,54,48,2,9,'A poznavše milost mně danou, Jakub a Petr a Jan, kteříž se zdadí sloupové býti, podali svých pravic mně a Barnabášovi na tovaryšství, abychom my mezi pohany a oni mezi Židy kázali.'),
(1575351,54,48,2,10,'Toliko napomenuli, abychom na chudé pamatovali, což jsem se i činiti snažoval.'),
(1575352,54,48,2,11,'A když byl přišel Petr do Antiochie, zjevně jsem jemu odepřel; hoden zajisté byl trestání.'),
(1575353,54,48,2,12,'Nebo prve nežli jsou přišli někteří od Jakuba, jídal s pohany, a když přišli, ucházel a odděloval se od nich, boje se těch, kteříž byli z Židovstva.'),
(1575354,54,48,2,13,'A spolu s ním v tom pokrytství byli i jiní Židé, takže i Barnabáš uveden byl v jejich pokrytství.'),
(1575355,54,48,2,14,'Ale já uzřev, že nesprostně chodí v pravdě evangelium, řekl jsem Petrovi přede všemi: Poněvadž ty jsa Žid, pohansky živ jsi, a ne Židovsky, proč pohany k Židovskému způsobu vedeš?'),
(1575356,54,48,2,15,'My přirození Židé, a ne pohané hříšní,'),
(1575357,54,48,2,16,'Vědouce, že nebývá člověk ospravedlněn z skutků Zákona, ale skrze víru v Jezukrista, i my v Krista uvěřili jsme, abychom ospravedlněni byli z víry Kristovy, a ne z skutků Zákona, protože nebude ospravedlněn z skutků Zákona žádný člověk.'),
(1575358,54,48,2,17,'Jestliže pak hledajíce ospravedlněni býti v Kristu, nalézáme se i my hříšníci, tedy jest Kristus služebník hřícha? Nikoli.'),
(1575359,54,48,2,18,'Nebo budu-li to, což jsem zbořil, opět zase vzdělávati, přestupníkem sebe činím.'),
(1575360,54,48,2,19,'Já zajisté skrze Zákon Zákonu umřel jsem, abych živ byl Bohu.'),
(1575361,54,48,2,20,'S Kristem ukřižován jsem. Živť jsem pak již ne já, ale živ jest ve mně Kristus. Že pak nyní živ jsem v těle, u víře Syna Božího živ jsem, kterýžto zamiloval mne a vydal sebe samého za mne.'),
(1575362,54,48,2,21,'Nepohrdámť tou milostí Boží. Nebo jestližeť jest z Zákona spravedlnost, tedyť jest Kristus nadarmo umřel.'),
(1575363,54,48,3,1,'Ó nemoudří Galatští, kdož jest vás tak zmámil, abyste nebyli povolni pravdě, kterýmž před očima Ježíš Kristus prve byl vypsán a mezi vámi ukřižován?'),
(1575364,54,48,3,2,'Toto bych jen rád chtěl zvěděti od vás, z skutků-li Zákona Ducha svatého jste přijali, čili z slyšení víry?'),
(1575365,54,48,3,3,'Tak nemoudří jste? Počavše Duchem, již nyní tělem konáte?'),
(1575366,54,48,3,4,'Tak mnoho trpěli jste nadarmo? A ještě nadarmo-li.'),
(1575367,54,48,3,5,'Ten tedy, kterýž vám dává Ducha svatého a činí divy mezi vámi, z skutků-li Zákona to činí, čili z slyšení víry?'),
(1575368,54,48,3,6,'Jako Abraham uvěřil Bohu, a počteno jemu to k spravedlnosti.'),
(1575369,54,48,3,7,'A tak vidíte, že ti, kteříž jsou z víry, ti jsou synové Abrahamovi.'),
(1575370,54,48,3,8,'Předzvěděvši pak Písmo, že z víry ospravedlňuje pohany Bůh, předpovědělo Abrahamovi: Že v tobě budou požehnáni všickni národové.'),
(1575371,54,48,3,9,'A tak ti, kteříž jsou z víry, docházejí požehnání s věrným Abrahamem.'),
(1575372,54,48,3,10,'Kteříž pak koli z skutků Zákona jsou, pod zlořečenstvím jsou. Nebo psáno jest: Zlořečený každý, kdož nezůstává ve všem, což jest psáno v knihách Zákona, aby to plnil.'),
(1575373,54,48,3,11,'A že z Zákona nebývá žádný ospravedlněn před Bohem, zjevné jest, nebo spravedlivý z víry živ bude.'),
(1575374,54,48,3,12,'Zákon pak není z víry, ale ten člověk, kterýž by plnil ta přikázání, živ bude v nich.'),
(1575375,54,48,3,13,'Ale vykoupilť jest nás Kristus z zlořečenství Zákona, učiněn byv pro nás zlořečenstvím, (nebo psáno jest: Zlořečený každý, kdož visí na dřevě),'),
(1575376,54,48,3,14,'Aby na pohany požehnání Abrahamovo přišlo v Kristu Ježíši a abychom zaslíbení Ducha svatého přijali skrze víru.'),
(1575377,54,48,3,15,'Bratří, po lidsku pravím: Však utvrzené některého člověka smlouvy žádný neruší, aniž k ní kdo něco přidává.'),
(1575378,54,48,3,16,'Abrahamovi pak učiněna jsou zaslíbení, i semeni jeho. Nedí: A semenům, jako by o mnohých mluvil, ale jako o jednom: A semenu tvému, jenž jest Kristus.'),
(1575379,54,48,3,17,'Totoť pak pravím: Že smlouvy prve od Boha stvrzené, vztahující se k Kristu, Zákon, kterýž po čtyřech stech a po třidcíti letech začal se, nevyprazdňuje, tak aby slib Boží v nic obrátil.'),
(1575380,54,48,3,18,'Nebo jestližeť z Zákona pochází dědictví, tedy již ne z zaslíbení. Ale Abrahamovi skrze zaslíbení daroval jest Bůh dědictví.'),
(1575381,54,48,3,19,'Což pak Zákon? Pro přestupování ustanoven jest, dokudž by nepřišlo to símě, jemuž se stalo zaslíbení, způsobený skrze anděly v ruce prostředníka.'),
(1575382,54,48,3,20,'Ale prostředník není jednoho, Bůh pak jeden jest.'),
(1575383,54,48,3,21,'Tedy Zákon jest proti slibům Božím? Odstup to. Nebo kdyby byl Zákon dán, kterýž by mohl obživiti, jistě z Zákona byla by spravedlnost.'),
(1575384,54,48,3,22,'Ale zavřelo Písmo všecky pod hřích, aby zaslíbení z víry Jezukristovy dáno bylo věřícím.'),
(1575385,54,48,3,23,'Prve pak, nežli přišla víra, pod Zákonem byli jsme ostříháni, zavříni jsouce k té víře, kteráž potom měla zjevena býti.'),
(1575386,54,48,3,24,'A tak Zákon pěstounem naším byl k Kristu, abychom z víry ospravedlněni byli.'),
(1575387,54,48,3,25,'Ale když přišla víra, již nejsme pod pěstounem.'),
(1575388,54,48,3,26,'Všickni zajisté vy synové Boží jste v Kristu Ježíši skrze víru.'),
(1575389,54,48,3,27,'Nebo kteřížkoli v Krista pokřtěni jste, Krista jste oblékli.'),
(1575390,54,48,3,28,'Neníť ani Žid, ani Řek, ani slouha, ani svobodný, ani muž, ani žena. Nebo všickni vy jedno jste v Kristu Ježíši.'),
(1575391,54,48,3,29,'A když Kristovi jste, tedy símě Abrahamovo jste, a podle zaslíbení dědicové.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575392,54,48,4,1,'Pravímť pak, že pokudž dědic maličký jest, nic není rozdílný od služebníka, jsa pánem všeho,'),
(1575393,54,48,4,2,'Ale pod ochráncemi a správcemi jest až do času uloženého od otce.'),
(1575394,54,48,4,3,'Tak i my, když jsme byli maličcí, pod živly světa byli jsme v službu podrobeni.'),
(1575395,54,48,4,4,'Ale když přišla plnost času, poslal Bůh Syna svého učiněného z ženy, učiněného pod Zákonem,'),
(1575396,54,48,4,5,'Aby ty, kteříž pod Zákonem byli, vykoupil, abychom právo synů přijali.'),
(1575397,54,48,4,6,'A že jste synové, protož poslal Bůh Ducha Syna svého v srdce vaše, volajícího: Abba, totiž Otče.'),
(1575398,54,48,4,7,'A tak již nejsi slouha, ale syn, a poněvadž syn, tedy i dědic Boží skrze Krista.'),
(1575399,54,48,4,8,'Ale tehdáž, neměvše známosti Boha, sloužili jste těm, kteříž z přirození nejsou bohové.'),
(1575400,54,48,4,9,'Nyní pak, znajíce Boha, nýbrž poznáni jsouce od Boha, kterakž se zpátkem zase obracíte k mdlým a bídným živlům, jimž opět znovu chcete sloužiti?'),
(1575401,54,48,4,10,'Dnů šetříte, a měsíců, a časů, i let.'),
(1575402,54,48,4,11,'Bojím se za vás, abych snad nadarmo nepracoval mezi vámi.'),
(1575403,54,48,4,12,'Buďte jako já, neb i já jsem jako vy, bratří, prosím vás. Nic jste mi neublížili.'),
(1575404,54,48,4,13,'Neb víte, že s mdlobou těla kázal jsem vám evangelium ponejprve.'),
(1575405,54,48,4,14,'A pokušení mé, přišlé na tělo mé, nebylo u vás málo váženo, aniž jste pohrdli, ale jako anděla Božího přijali jste mne, jako Krista Ježíše.'),
(1575406,54,48,4,15,'Jaké tehdy bylo blahoslavenství vaše? Svědectvíť vám zajisté dávám, že, kdyby to možné bylo, oči vaše vyloupíce, byli byste mi dali.'),
(1575407,54,48,4,16,'Což tedy učiněn jsem vaším nepřítelem, pravdu vám pravě?'),
(1575408,54,48,4,17,'Milujíť vás někteří nedobře, nýbrž odstrčiti vás chtějí, abyste vy je milovali.'),
(1575409,54,48,4,18,'Slušnéť jest pak horlivě milovati v dobrém vždycky, a ne jen toliko tehdáž, když jsem přítomen vám.'),
(1575410,54,48,4,19,'Synáčkové moji, (kteréž opět rodím, až by Kristus zformován byl v vás),'),
(1575411,54,48,4,20,'Chtěl bych pak přítomen vám býti nyní a proměniti hlas svůj; nebo v pochybnosti jsem o vás.'),
(1575412,54,48,4,21,'Povězte mi, kteříž pod Zákonem chcete býti, nepozorujete-liž Zákona?'),
(1575413,54,48,4,22,'Nebo psáno jest: Že Abraham měl dva syny, jednoho z služebnice, a druhého z svobodné.'),
(1575414,54,48,4,23,'Ale ten z služebnice podle těla se narodil, tento pak z svobodné podle zaslíbení.'),
(1575415,54,48,4,24,'Kteréžto věci u figuře se staly. Nebo toť jsou ti dva Zákonové, jeden s hory Sinai, k manství zplozující, a tenť jest jako Agar.'),
(1575416,54,48,4,25,'Agar zajisté jest hora Sinai v Arabii. Dobřeť se pak k ní trefuje nynější Jeruzalém, nebo v službu podroben jest s syny svými.'),
(1575417,54,48,4,26,'Ale ten svrchní Jeruzalém svobodný jest, kterýž jest matka všech nás.'),
(1575418,54,48,4,27,'Nebo psáno jest: Vesel se neplodná, kteráž nerodíš, vykřikni a zvolej, kteráž nepracuješ ku porodu; nebo ta opuštěná mnoho má synů, více nežli ta, kteráž má muže.'),
(1575419,54,48,4,28,'Myť jsme tedy, ó bratří, tak jako Izák, synové zaslíbení.'),
(1575420,54,48,4,29,'Ale jakož tehdáž ten podle těla zplozený protivil se tomu, kterýž byl zplozen podle Ducha, tak se děje i nyní.'),
(1575421,54,48,4,30,'Než co praví Písmo? Vyvrz služebnici i syna jejího; nebo nebudeť dědicem syn služebnice s synem svobodné.'),
(1575422,54,48,4,31,'A tak, bratří, nejsmeť synové služebnice, ale svobodné.'),
(1575423,54,48,5,1,'Protož v svobodě, kterouž Kristus nás osvobodil, stůjte a nezapletejtež se zase v jho služebnosti.'),
(1575424,54,48,5,2,'Aj, já Pavel pravím vám, že budete-li se obřezovati, Kristus vám nic neprospěje.'),
(1575425,54,48,5,3,'A zase osvědčuji všelikému člověku, kterýž se obřezuje, že jest povinen všecken Zákon naplniti.'),
(1575426,54,48,5,4,'Odcizili jste se Krista, kteřížkoli v Zákoně ospravedlněni býti hledáte; vypadli jste z milosti.'),
(1575427,54,48,5,5,'My zajisté duchem z víry, naděje spravedlnosti očekáváme.'),
(1575428,54,48,5,6,'Nebo v Kristu Ježíši ani obřízka neprospívá, ani neobřízka, ale víra skrze lásku dělající.'),
(1575429,54,48,5,7,'Běželi jste dobře. Kdo jest vám překazil, abyste pravdy neposlouchali?'),
(1575430,54,48,5,8,'Neníť ta rada z toho, kterýž vás volá.'),
(1575431,54,48,5,9,'Maličko kvasu všecko těsto nakvašuje.'),
(1575432,54,48,5,10,'Jáť mám naději o vás v Pánu, že nic jiného smýšleti nebudete; ale ten, jenž kormoutí vás, trpěti bude soud, kdožť jest on koli.'),
(1575433,54,48,5,11,'Já pak, bratří, káži-li také obřízku, i pročež protivenství trpím? Tedy jest vyprázdněno pohoršení kříže.'),
(1575434,54,48,5,12,'Ó by raději odřezáni byli, kteříž vás nepokojí.'),
(1575435,54,48,5,13,'Nebo vy v svobodu povoláni jste, bratří, toliko abyste té svobody nepokládali sobě za zámysl povolování tělu, ale skrze lásku posluhujte sobě vespolek.'),
(1575436,54,48,5,14,'Nebo všecken Zákon v jednom slovu se zavírá, totiž v tom: Milovati budeš bližního svého jako sebe samého.'),
(1575437,54,48,5,15,'Pakli se vespolek koušete a žerete, hleďtež, abyste jedni od druhých zkaženi nebyli.'),
(1575438,54,48,5,16,'Ale pravímť: Duchem choďte, a žádosti těla nevykonáte.'),
(1575439,54,48,5,17,'Nebo tělo žádá proti Duchu, a Duch proti tělu. Ty pak věci jsou sobě vespolek odporné, tak abyste ne hned, což byste chtěli, to činili.'),
(1575440,54,48,5,18,'Jestliže pak Duchem vedeni býváte, nejste pod Zákonem.'),
(1575441,54,48,5,19,'Zjevníť jsou pak skutkové těla, jenž jsou: Cizoložstvo, smilstvo, nečistota, chlipnost,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575442,54,48,5,20,'Modloslužba, čarování, nepřátelství, svárové, nenávisti, hněvové, dráždění, různice, sekty,'),
(1575443,54,48,5,21,'Závisti, vraždy, opilství, hodování, a těm podobné věci. Kteréžto kdožkoli činí, toť vám předpovídám, jakož jsem i prve pravil, že království Božího dědicové nebudou.'),
(1575444,54,48,5,22,'Ovoce pak Ducha jestiť: Láska, radost, pokoj, tichost, dobrotivost, dobrota, věrnost, krotkost, středmost.'),
(1575445,54,48,5,23,'Proti takovýmť není Zákon.'),
(1575446,54,48,5,24,'Nebo kteříž jsou Kristovi, tiť jsou tělo své ukřižovali s vášněmi a s žádostmi.'),
(1575447,54,48,5,25,'Jsme-liť tedy Duchem živi, Duchem i choďme.'),
(1575448,54,48,5,26,'Nebývejme marné chvály žádostivi, jedni druhých popouzejíce a jedni druhým závidíce.'),
(1575449,54,48,6,1,'Bratří, byl-li by zachvácen člověk v nějakém pádu, vy duchovní napravte takového v duchu tichosti, prohlédaje každý sám k sobě, abys snad i ty nebyl pokoušín.'),
(1575450,54,48,6,2,'Jedni druhých břemena neste a tak plňte zákon Kristův.'),
(1575451,54,48,6,3,'Nebo zdá-li se komu, že by něco byl, nic nejsa, takového vlastní mysl jeho svodí.'),
(1575452,54,48,6,4,'Ale díla svého zkus jeden každý, a takť sám v sobě chválu míti bude, a ne v jiném.'),
(1575453,54,48,6,5,'Neb jeden každý své břímě ponese.'),
(1575454,54,48,6,6,'Sdílejž se pak ten, kterýž naučení přijímá v slovu Páně, s tím, od kohož naučení béře, vším svým statkem.'),
(1575455,54,48,6,7,'Nemylte se, Bůhť nebude oklamán; nebo cožkoli rozsíval by člověk, toť bude i žíti.'),
(1575456,54,48,6,8,'A kdož rozsívá tělu svému, z těla žíti bude porušení; ale kdož rozsívá Duchu, z Duchať žíti bude život věčný.'),
(1575457,54,48,6,9,'Činíce pak dobře, neoblevujme; nebo časem svým budeme žíti, neustávajíce.'),
(1575458,54,48,6,10,'A protož dokudž čas máme, čiňme dobře všechněm, a zvláště nejvíce pak domácím víry'),
(1575459,54,48,6,11,'Hle, jaký jsem vám list napsal svou rukou.'),
(1575460,54,48,6,12,'Ti, kteříž chtějí tvární býti podle těla, nutí vás, abyste se obřezovali, jediné aby protivenství pro kříž Kristův netrpěli.'),
(1575461,54,48,6,13,'Nebo ani sami ti, kteříž se obřezují, nezachovávají Zákona, ale chtí, abyste se obřezovali proto, aby se tělem vaším chlubili.'),
(1575462,54,48,6,14,'Ale ode mne odstup to, ať abych se v čem chlubil, jediné v kříži Pána našeho Jezukrista, skrze něhož jest mi svět ukřižován, a já světu.'),
(1575463,54,48,6,15,'Nebo v Kristu Ježíši ani obřízka nic neplatí, ani neobřízka, ale nové stvoření.'),
(1575464,54,48,6,16,'A kteříkoli tohoto pravidla následují, pokoj přijde na ně a milosrdenství, i na lid Boží Izraelský.'),
(1575465,54,48,6,17,'Dále pak žádný mi nečiň zaměstknání, já zajisté jízvy Pána Ježíše nosím na těle svém.'),
(1575466,54,48,6,18,'Milost Pána Ježíše Krista budiž s duchem vaším, bratří. Amen.'),
(1575467,54,49,1,1,'Pavel apoštol Jezukristův, skrze vůli Boží, svatým, kteří jsou v Efezu, a věrným v Kristu Ježíši:'),
(1575468,54,49,1,2,'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.'),
(1575469,54,49,1,3,'Požehnaný Bůh a Otec Pána našeho Jezukrista, kterýž požehnal nám všelikým požehnáním duchovním v nebeských věcech v Kristu.'),
(1575470,54,49,1,4,'Jakož vyvolil nás v něm před ustanovením světa k tomu, abychom byli svatí a neposkvrnění před obličejem jeho v lásce,'),
(1575471,54,49,1,5,'Předzřídiv nás k zvolení za syny skrze Ježíše Krista v sebe, podle dobře libé vůle své,'),
(1575472,54,49,1,6,'K chvále slávy milosti své, kterouž vzácné nás učinil v milém Synu svém.'),
(1575473,54,49,1,7,'V němžto máme vykoupení skrze krev jeho, totiž odpuštění hříchů, podle bohatství milosti jeho,'),
(1575474,54,49,1,8,'Kterouž rozhojnil k nám ve vší moudrosti a opatrnosti,'),
(1575475,54,49,1,9,'Oznámiv nám tajemství vůle své podle dobré libosti své, kteroužto libost předuložil byl sám v sobě,'),
(1575476,54,49,1,10,'Aby v dokonání plnosti časů v jedno shromáždil všecko v Kristu, buďto nebeské věci, buďto zemské.'),
(1575477,54,49,1,11,'V něm, pravím, v kterémžto i k losu připuštěni jsme, předzřízeni byvše, podle předuložení toho, jenž všecko působí podle rady vůle své,'),
(1575478,54,49,1,12,'Abychom tak byli k chvále slávy jeho my, kteříž jsme prve naději měli v Kristu.'),
(1575479,54,49,1,13,'V kterémžto i vy naději máte, slyševše slovo pravdy, totiž evangelium spasení vašeho, v němžto i uvěřivše, znamenáni jste Duchem zaslíbení Svatým,'),
(1575480,54,49,1,14,'Kterýž jest závdavek dědictví našeho, na vykoupení toho, což jím dobyto jest, k chvále slávy jeho.'),
(1575481,54,49,1,15,'Protož i já, slyšev o vaší víře v Pánu Ježíši, a o lásce ke všem svatým,'),
(1575482,54,49,1,16,'Nepřestávám díků činiti z vás, zmínku čině o vás na modlitbách svých:'),
(1575483,54,49,1,17,'Aby Bůh Pána našeho Jezukrista, Otec slávy, dal vám Ducha moudrosti a zjevení, v poznání jeho,'),
(1575484,54,49,1,18,'A tak osvícené oči mysli vaší, abyste věděli, která by byla naděje povolání jeho a jaké bohatství slávy dědictví jeho v svatých,'),
(1575485,54,49,1,19,'A kterak jest převýšená velikost moci jeho k nám věřícím podle působení mocnosti síly jeho,'),
(1575486,54,49,1,20,'Kteréž dokázal na Kristu, vzkřísiv jej z mrtvých a posadiv na pravici své na nebesích,'),
(1575487,54,49,1,21,'Vysoce nade všecko knížatstvo, i mocnosti, i moci, i panstvo, i nad každé jméno, kteréž se jmenuje, netoliko v věku tomto, ale i v budoucím.'),
(1575488,54,49,1,22,'A všecko poddal pod nohy jeho, a jej dal hlavu nade všecko církvi,'),
(1575489,54,49,1,23,'Kterážto jest tělo jeho a plnost všecko ve všech naplňujícího.'),
(1575490,54,49,2,1,'I vás obživil mrtvé vinami a hříchy,'),
(1575491,54,49,2,2,'V nichž jste někdy chodili podle obyčeje světa tohoto a podle knížete mocného v povětří, ducha toho, kterýž nyní dělá v synech zpoury.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575492,54,49,2,3,'Mezi nimižto i my všickni žili jsme někdy v žádostech těla našeho, činivše to, což se líbilo tělu a mysli, a byli jsme z přirození synové hněvu jako i jiní.'),
(1575493,54,49,2,4,'Ale Bůh, bohatý jsa v milosrdenství pro velikou lásku svou, kteroužto zamiloval nás,'),
(1575494,54,49,2,5,'Když jsme my ještě mrtví byli v hříších, obživil nás spolu s Kristem, jehož milostí jste spaseni,'),
(1575495,54,49,2,6,'A spolu s ním vzkřísil, i posadil na nebesích v Kristu Ježíši,'),
(1575496,54,49,2,7,'Aby ukázal v věku budoucím nepřevýšené bohatství milosti své, z dobroty své k nám v Kristu Ježíši.'),
(1575497,54,49,2,8,'Nebo milostí spaseni jste skrze víru, a to ne sami z sebe: darť jest to Boží,'),
(1575498,54,49,2,9,'Ne z skutků, aby se někdo nechlubil.'),
(1575499,54,49,2,10,'Jsme zajisté jeho dílo, jsouce stvořeni v Kristu Ježíši k skutkům dobrým, kteréž Bůh připravil, abychom v nich chodili.'),
(1575500,54,49,2,11,'Protož pamatujte, že vy byli někdy pohané podle těla, kteříž jste slouli neobřízka od těch, kteříž slouli obřízka na těle, kteráž se působí rukama,'),
(1575501,54,49,2,12,'A že jste byli za onoho času bez Krista, odcizeni od společnosti Izraele, a cizí od úmluv zaslíbení, naděje nemající, a bez Boha na světě.'),
(1575502,54,49,2,13,'Ale nyní v Kristu Ježíši vy, kteříž jste někdy byli dalecí, blízcí učiněni jste skrze krev Kristovu.'),
(1575503,54,49,2,14,'Nebo onť jest pokoj náš, kterýž učinil oboje jedno, zbořiv hradbu dělící na různo,'),
(1575504,54,49,2,15,'A nepřátelství, totiž Zákon přikázání, záležející v ustanoveních, vyprázdniv skrze tělo své, aby dvoje vzdělal v samém sobě v jednoho nového člověka, tak čině pokoj,'),
(1575505,54,49,2,16,'A v mír uvodě oboje v jednom těle Bohu skrze kříž, vyhladiv nepřátelství skrze něj.'),
(1575506,54,49,2,17,'A přišed, zvěstoval pokoj vám, dalekým i blízkým.'),
(1575507,54,49,2,18,'Neboť skrze něho obojí máme přístup v jednom Duchu k Otci.'),
(1575508,54,49,2,19,'Aj, již tedy nejste hosté a příchozí, ale spoluměšťané svatých a domácí Boží,'),
(1575509,54,49,2,20,'Vzdělaní na základ apoštolský a prorocký, kdežto jest gruntovní úhelný kámen sám Ježíš Kristus,'),
(1575510,54,49,2,21,'Na němžto všecko stavení příslušně vzdělané roste v chrám svatý v Pánu;'),
(1575511,54,49,2,22,'Na kterémžto i vy spolu vzděláváte se v příbytek Boží, v Duchu svatém.'),
(1575512,54,49,3,1,'Pro tu věc já Pavel, jsem vězeň Krista Ježíše pro vás pohany,'),
(1575513,54,49,3,2,'Jestliže však jste slyšeli o milosti Boží, kteréž jest mi uděleno k přisluhování vám,'),
(1575514,54,49,3,3,'Že skrze zjevení oznámil mi tajemství, (jakož jsem vám prve psal krátce;'),
(1575515,54,49,3,4,'Z čehož můžete, čtouce, porozuměti známosti mé v tajemství Kristovu;)'),
(1575516,54,49,3,5,'Kteréž za jiných věků nebylo známo synům lidským, tak jako nyní zjeveno jest svatým apoštolům jeho a prorokům skrze Ducha,'),
(1575517,54,49,3,6,'Totiž že by měli býti pohané spoludědicové a jednotělní, i spoluúčastníci zaslíbení jeho v Kristu skrze evangelium,'),
(1575518,54,49,3,7,'Kteréhož já učiněn jsem slouha z daru milosti Boží mně dané, podle působení moci jeho.'),
(1575519,54,49,3,8,'Mně nejmenšímu ze všech svatých dána jest milost ta, abych mezi pohany zvěstoval nestihlá bohatství Kristova,'),
(1575520,54,49,3,9,'A vysvětlil všechněm, kteraké by bylo obcování tajemství skrytého od věků v Bohu, kterýž všecko stvořil skrze Ježíše Krista,'),
(1575521,54,49,3,10,'Aby nyní oznámena byla knížatstvu a mocem na nebesích skrze církev rozličná moudrost Boží,'),
(1575522,54,49,3,11,'Podle předuložení věčného, kteréž jest uložil v Kristu Ježíši Pánu našem,'),
(1575523,54,49,3,12,'V němžto máme smělost a přístup s doufáním skrze víru jeho.'),
(1575524,54,49,3,13,'Protož prosím, abyste nehynuli v čas soužení mých pro vás, kteráž jsou sláva vaše.'),
(1575525,54,49,3,14,'A pro tu příčinu klekám na kolena svá před Otcem Pána našeho Jezukrista,'),
(1575526,54,49,3,15,'Z něhožto všeliká rodina na nebi i na zemi jmenuje se,'),
(1575527,54,49,3,16,'Aby vám dal, podle bohatství slávy své, mocí posilněnu býti skrze Ducha svého na vnitřním člověku,'),
(1575528,54,49,3,17,'Aby Kristus skrze víru přebýval v srdcích vašich,'),
(1575529,54,49,3,18,'Abyste v lásce vkořeněni a založeni jsouce, mohli stihnouti se všemi svatými, kteraká by byla širokost, a dlouhost, a hlubokost, a vysokost,'),
(1575530,54,49,3,19,'A poznati přenesmírnou lásku Kristovu, abyste tak naplněni byli ve všelikou plnost Boží.'),
(1575531,54,49,3,20,'Tomu pak, kterýž mocen jest nade všecko učiniti mnohem hojněji, nežli my prosíme aneb rozumíme, podle moci té, kterouž dělá v nás,'),
(1575532,54,49,3,21,'Tomu, pravím, buď sláva v církvi svaté skrze Krista Ježíše po všecky věky věků. Amen.'),
(1575533,54,49,4,1,'Protož prosímť vás já vězeň v Pánu, abyste hodně chodili, jakž sluší na povolání vaše, kterýmž povoláni jste,'),
(1575534,54,49,4,2,'Se vší pokorou, tichostí, i s snášelivostí, snášejíce se vespolek v lásce,'),
(1575535,54,49,4,3,'Usilujíce zachovávati jednotu Ducha v svazku pokoje.'),
(1575536,54,49,4,4,'Jedno jest tělo, a jeden Duch, jakož i povoláni jste v jedné naději povolání vašeho.'),
(1575537,54,49,4,5,'Jeden Pán, jedna víra, jeden křest,'),
(1575538,54,49,4,6,'Jeden Bůh a Otec všech, kterýž jest nade všecko, a skrze všecko, i ve všech vás.'),
(1575539,54,49,4,7,'Jednomu pak každému z nás dána jest milost podle míry obdarování Kristova.'),
(1575540,54,49,4,8,'Protož dí Písmo: Vstoupiv na výsost, jaté vedl vězně, a dal dary lidem.'),
(1575541,54,49,4,9,'Ale to, že vstoupil, co jest, jediné že i sstoupil prve do nejnižších stran země?');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575542,54,49,4,10,'Ten pak, jenž sstoupil, onť jest, kterýž i vstoupil vysoko nade všecka nebesa, aby naplnil všecko.'),
(1575543,54,49,4,11,'A onť jest dal některé zajisté apoštoly, některé pak proroky, jiné evangelisty, jiné pastýře a učitele,'),
(1575544,54,49,4,12,'Pro spořádání svatých, k dílu služebnosti, k vzdělání těla Kristova,'),
(1575545,54,49,4,13,'Až bychom se sběhli všickni v jednotu víry a známosti Syna Božího, v muže dokonalého, v míru postavy plného věku Kristova,'),
(1575546,54,49,4,14,'Abychom již více nebyli děti, zmítající se a točící každým větrem učení v neustavičnosti lidské, v chytrosti k oklamávání lstivému;'),
(1575547,54,49,4,15,'Ale pravdu činíce v lásce, rosťme v něj všelikterak, v toho, kterýž jest hlava, totiž Kristus,'),
(1575548,54,49,4,16,'Z kteréhožto všecko tělo příslušně spojené a svázané po všech kloubích přisluhování, podle vnitřní moci v míru jednoho každého údu, zrůst těla činí, k vzdělání svému v lásce.'),
(1575549,54,49,4,17,'A protož totoť pravím a osvědčuji v Pánu, abyste již více nechodili, jako i jiní pohané chodí, v marnosti mysli své,'),
(1575550,54,49,4,18,'Zatemnění v rozumu, odcizeni jsouce od života Božího, pro neznámost, kteráž jest v nich z zatvrzení srdce jejich.'),
(1575551,54,49,4,19,'Kteřížto zoufavše sobě, vydali se v nestydatost, aby všelikou nečistotu páchali s chtivostí.'),
(1575552,54,49,4,20,'Ale vy ne tak jste se vyučili následovati Krista,'),
(1575553,54,49,4,21,'Ač jestliže jste ho slyšeli a o něm byli vyučeni, jakž ta jest pravda v Ježíšovi,'),
(1575554,54,49,4,22,'Totiž, složiti ono první obcování podle starého člověka, rušícího se, podle žádostí oklamávajících,'),
(1575555,54,49,4,23,'Obnoviti se pak duchem mysli vaší,'),
(1575556,54,49,4,24,'A obléci nového člověka, podle Boha stvořeného, v spravedlnosti a v svatosti pravdy.'),
(1575557,54,49,4,25,'Protož složíce lež, mluvtež pravdu jeden každý s bližním svým; nebo jsme vespolek údové.'),
(1575558,54,49,4,26,'Hněvejte se, a nehřešte; slunce nezapadej na hněvivost vaši.'),
(1575559,54,49,4,27,'Nedávejte místa ďáblu.'),
(1575560,54,49,4,28,'Kdo kradl, již více nekraď, ale raději pracuj, dělaje rukama svýma, což dobrého jest, aby měl z čeho uděliti nuznému.'),
(1575561,54,49,4,29,'Žádná řeč mrzutá nevycházej z úst vašich, ale ať jest každé promluvení dobré k vzdělání užitečnému, aby dalo milost posluchačům.'),
(1575562,54,49,4,30,'A nezarmucujte Ducha svatého Božího, kterýmžto znamenáni jste ke dni vykoupení.'),
(1575563,54,49,4,31,'Všeliká hořkost, a rozzlobení se, i hněv, i křik, i rouhání buď odjato od vás, se vší zlostí,'),
(1575564,54,49,4,32,'Ale buďte k sobě vespolek dobrotiví, milosrdní, odpouštějíce sobě vespolek, jakož i Bůh v Kristu odpustil vám.'),
(1575565,54,49,5,1,'Buďtež tedy následovníci Boží, jakožto synové milí.'),
(1575566,54,49,5,2,'A choďtež v lásce, jakož i Kristus miloval nás, a vydal sebe samého za nás, dar a obět Bohu u vůni rozkošnou.'),
(1575567,54,49,5,3,'Smilstvo pak a všeliká nečistota, neb lakomství, aniž jmenováno buď mezi vámi, jakož sluší na svaté,'),
(1575568,54,49,5,4,'A tolikéž mrzkost, ani bláznové mluvení, ani šprýmování, kteréžto věci jsou nenáležité, ale raději ať jest díků činění.'),
(1575569,54,49,5,5,'Víte zajisté o tom, že žádný smilník aneb nečistý, ani lakomec, (jenž jest modloslužebník,) nemá dědictví v království Kristově a Božím.'),
(1575570,54,49,5,6,'Žádný vás nesvoď marnými řečmi; nebo pro takové věci přichází hněv Boží na syny nepoddané.'),
(1575571,54,49,5,7,'Nebývejtež tedy účastníci jejich.'),
(1575572,54,49,5,8,'Byli jste zajisté někdy temnosti, ale již nyní jste světlo v Pánu. Jakožto synové světla choďte,'),
(1575573,54,49,5,9,'(Nebo ovoce Ducha záleží ve vší dobrotě, a spravedlnosti, a v pravdě,)'),
(1575574,54,49,5,10,'O to stojíce, což by se dobře líbilo Pánu.'),
(1575575,54,49,5,11,'A neobcujte s skutky neužitečnými tmy, ale raději je trescete.'),
(1575576,54,49,5,12,'Nebo což se tajně děje od nich, mrzko jest o tom i mluviti.'),
(1575577,54,49,5,13,'Všecko pak, což bývá trestáno, od světla bývá zjeveno; nebo to, což všecko zjevuje, světlo jest.'),
(1575578,54,49,5,14,'Protož praví: Probuď se ty, jenž spíš, a vstaň z mrtvých, a zasvítíť se tobě Kristus.'),
(1575579,54,49,5,15,'Viztež tedy, kterak byste opatrně chodili, ne jako nemoudří, ale jako moudří,'),
(1575580,54,49,5,16,'Vykupujíce čas; nebo dnové zlí jsou.'),
(1575581,54,49,5,17,'Protož nebývejte neopatrní, ale rozumějící, která by byla vůle Páně.'),
(1575582,54,49,5,18,'A neopíjejte se vínem, v němžto jest prostopášnost, ale naplněni buďte Duchem svatým,'),
(1575583,54,49,5,19,'Mluvíce sobě vespolek v žalmích, a v chvalách, a v písničkách duchovních, zpívajíce a plésajíce v srdcích vašich Pánu,'),
(1575584,54,49,5,20,'Díky činíce vždycky ze všeho ve jménu Pána našeho Jezukrista Bohu a Otci,'),
(1575585,54,49,5,21,'Poddáni jsouce jedni druhým v bázni Boží.'),
(1575586,54,49,5,22,'Ženy mužům svým poddány buďte jako Pánu.'),
(1575587,54,49,5,23,'Nebo muž jest hlava ženy, jako i Kristus jest hlava církve, a onť jest Spasitel těla.'),
(1575588,54,49,5,24,'A tak jakož církev poddána jest Kristu, tak i ženy mužům svým ať jsou poddány ve všem.'),
(1575589,54,49,5,25,'Muži milujte ženy své, jako i Kristus miloval církev, a vydal sebe samého za ni,'),
(1575590,54,49,5,26,'Aby ji posvětil, očistiv ji obmytím vody v slovu,'),
(1575591,54,49,5,27,'Aby ji sobě postavil slavnou církev, nemající poskvrny, ani vrásky, neb cokoli takového, ale aby byla svatá a bez úhony.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575592,54,49,5,28,'Takť jsou povinni muži milovati ženy své jako svá vlastní těla. Kdo miluje ženu svou, sebeť samého miluje.'),
(1575593,54,49,5,29,'Žádný zajisté nikdy těla svého neměl v nenávisti, ale krmí a chová je, jakožto i Pán církev.'),
(1575594,54,49,5,30,'Neboť jsme údové těla jeho, z masa jeho a z kostí jeho.'),
(1575595,54,49,5,31,'A protoť opustí člověk otce i matku, a připojí se k manželce své, i budouť dva jedno tělo.'),
(1575596,54,49,5,32,'Tajemství toto veliké jest, ale já pravím o Kristu a o církvi.'),
(1575597,54,49,5,33,'Avšak i vy, jeden každý z vás, manželku svou tak jako sám sebe miluj. Žena pak ať se bojí muže svého.'),
(1575598,54,49,6,1,'Dítky poslouchejte rodičů svých v Pánu; neboť jest to spravedlivé.'),
(1575599,54,49,6,2,'Cti otce svého i matku, (toť jest přikázaní první s zaslíbením,)'),
(1575600,54,49,6,3,'Aby dobře bylo tobě a abys byl dlouhověký na zemi.'),
(1575601,54,49,6,4,'A vy otcové nepopouzejte k hněvu dítek vašich, ale vychovávejte je v cvičení a v napomínání Páně.'),
(1575602,54,49,6,5,'Služebníci, buďte poslušni pánů tělesných s bázní a s strachem, v sprostnosti srdce vašeho, jako Krista,'),
(1575603,54,49,6,6,'Ne na oko sloužíce, jako ti, jenž se lidem líbiti usilují, ale jako služebníci Kristovi, činíce vůli Boží z té duše,'),
(1575604,54,49,6,7,'S dobrou myslí sloužíce, jakožto Pánu, a ne lidem,'),
(1575605,54,49,6,8,'Vědouce, že, což by koli jeden každý učinil dobrého, za to odplatu vzíti má ode Pána, buďto služebník, buďto svobodný.'),
(1575606,54,49,6,9,'A vy páni též se tak mějte k nim, zanechajíce pohrůžky, vědouce, že i vy také máte Pána v nebesích, a přijímání osob není u něho.'),
(1575607,54,49,6,10,'Dále pak, bratří moji, posilňte se v Pánu a v moci síly jeho.'),
(1575608,54,49,6,11,'Oblecte se v celé odění Boží, abyste mohli státi proti útokům ďábelským.'),
(1575609,54,49,6,12,'Neboť není bojování naše proti tělu a krvi, ale proti knížatstvu, proti mocnostem, proti světa pánům temností věku tohoto, proti duchovním zlostem, kteréž jsou vysoko.'),
(1575610,54,49,6,13,'A protož vezměte celé odění Boží, abyste mohli odolati v den zlý, a všecko vykonajíce, státi.'),
(1575611,54,49,6,14,'Stůjtež tedy, majíce podpásaná bedra vaše pravdou, a oblečeni jsouce v pancíř spravedlnosti,'),
(1575612,54,49,6,15,'A obuté majíce nohy v hotovost k evangelium pokoje,'),
(1575613,54,49,6,16,'A zvláště pak vezmouce štít víry, kterýmž byste mohli všecky šípy ohnivé nešlechetníka toho uhasiti.'),
(1575614,54,49,6,17,'A lebku spasení vezměte, i meč Ducha, jenž jest slovo Boží,'),
(1575615,54,49,6,18,'Všelikou modlitbou a prosbou modléce se každého času v Duchu, a v tom bedlivi jsouce se vší ustavičností a prošením za všecky svaté,'),
(1575616,54,49,6,19,'I za mne, aby mi dána byla řeč v otevření úst mých svobodně a směle, abych oznamoval tajemství evangelium svatého,'),
(1575617,54,49,6,20,'Pro něžto úřad svůj konám v řetězu tomto, abych tak v něm svobodně a směle mluvil, jakž mně mluviti náleží.'),
(1575618,54,49,6,21,'A abyste i vy věděli, co se se mnou děje a co činím, všecko vám to oznámí Tychikus, milý bratr a věrný služebník v Pánu,'),
(1575619,54,49,6,22,'Jehož jsem pro to samo k vám poslal, abyste věděli o našich věcech a aby potěšil srdcí vašich.'),
(1575620,54,49,6,23,'Pokoj budiž vám bratřím, a láska s věrou, od Boha Otce a Pána Jezukrista.'),
(1575621,54,49,6,24,'Milost Boží budiž se všemi milujícími Pána našeho Jezukrista v neporušitelnosti. Amen. List tento k Efezským psán byl z Říma po Tychikovi.'),
(1575622,54,50,1,1,'Pavel a Timoteus, služebníci Ježíše Krista, všechněm svatým v Kristu Ježíši, kteříž jsou v městě Filippis, s biskupy a s jáhny:'),
(1575623,54,50,1,2,'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.'),
(1575624,54,50,1,3,'Děkuji Bohu mému, když se koli na vás rozpomenu,'),
(1575625,54,50,1,4,'(Vždycky při každé modlitbě mé, s radostí za všecky za vás prosbu čině,)'),
(1575626,54,50,1,5,'Z vašeho účastenství v evangelium, hned od prvního dne až posavad,'),
(1575627,54,50,1,6,'Jist jsa tím, že ten, kterýž začal v vás dílo dobré, dokoná až do dne Ježíše Krista,'),
(1575628,54,50,1,7,'Jakož jest mi spravedlivé tak smysliti o všech vás proto, že vás v srdci mám i v vězení mém, a v obraňování i v utvrzování evangelium, vás, pravím, všecky účastníky milosti mně dané.'),
(1575629,54,50,1,8,'Svědek mi jest zajisté Bůh, kterak po všech po vás toužím v srdci Ježíše Krista.'),
(1575630,54,50,1,9,'A za to se modlím, aby láska vaše ještě více a více se rozhojňovala v známosti a ve všelikém smyslu,'),
(1575631,54,50,1,10,'K tomu, abyste zkušením rozeznati mohli užitečné věci od neužitečných, tak abyste byli upřímí a bez úrazu, až ke dni Kristovu,'),
(1575632,54,50,1,11,'Naplněni jsouce ovocem spravedlnosti, kteréž nesete skrze Jezukrista, k slávě a k chvále Boží.'),
(1575633,54,50,1,12,'Chciť pak, bratří, abyste věděli, že to pokušení, kteréž mne obklíčilo, k většímu prospěchu evangelium přišlo,'),
(1575634,54,50,1,13,'Takže vězení mé pro Krista rozhlášeno jest po všem císařském dvoře, i jinde všudy.'),
(1575635,54,50,1,14,'A mnozí z bratří v Pánu, spolehše na vězení mé, hojnější smělost mají bez strachu mluviti slovo Boží.'),
(1575636,54,50,1,15,'Někteří zajisté jen z závisti a navzdoru, někteří pak také z oblíbení sobě toho Krista káží.'),
(1575637,54,50,1,16,'Ti pak, kteříž navzdoru Krista zvěstují, ne v čistotě, domnívají se, že mi k vězení mému soužení přidadí;'),
(1575638,54,50,1,17,'Kteří pak z lásky, ti vědí, že jsem k obraně evangelium postaven.'),
(1575639,54,50,1,18,'Ale což pak o to? Nýbrž jakýmkoli způsobem, buď v samé tvárnosti, buď v pravdě Kristus se zvěstuje, i z tohoť se raduji, a ještě radovati budu.'),
(1575640,54,50,1,19,'Neboť vím, že mi to přijde k spasení skrze vaši modlitbu a pomoc Ducha Jezukristova,'),
(1575641,54,50,1,20,'Podle pečlivého očekávání a naděje mé, že v ničemž nebudu zahanben, ale ve vší doufanlivé smělosti, jako i prve vždycky, tak i nyní veleben bude Kristus na těle mém, buďto skrze život, buďto skrze smrt.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575642,54,50,1,21,'Mně zajisté Kristus i v životě i v smrti ziskem jest.'),
(1575643,54,50,1,22,'Jest-li mi pak prospěšněji živu býti v těle pro práci, tedy nevím, co bych vyvolil.'),
(1575644,54,50,1,23,'K obémuť se k tomu nakloňuji, žádost maje umříti, a býti s Kristem, což by mnohem lépe bylo,'),
(1575645,54,50,1,24,'Ale pozůstati ještě v těle potřebněji jest pro vás.'),
(1575646,54,50,1,25,'Načež spoléhaje, vím, že pobudu a s vámi se všemi spolu pozůstanu k vašemu prospěchu a k radosti víry,'),
(1575647,54,50,1,26,'Aby se vaše ze mne chlouba v Kristu Ježíši rozhojnila, skrze mou opět vám zase přítomnost.'),
(1575648,54,50,1,27,'Toliko, jakž sluší na účastníky evangelium Kristova, se chovejte, abych, buďto přijda k vám a vida vás, buďto vzdálen jsa, slyšel o vás, že stojíte v jednom duchu, jednomyslně pracujíce u víře evangelium,'),
(1575649,54,50,1,28,'A v ničemž se nestrachujte protivníků, což jest jim jistým znamením zahynutí, vám pak spasení, a to od Boha.'),
(1575650,54,50,1,29,'Nebo vám jest to z milosti dáno pro Krista, abyste netoliko v něho věřili, ale také pro něj i trpěli,'),
(1575651,54,50,1,30,'Týž boj majíce, jakýž jste při mně i viděli, i nyní o mně slyšíte.'),
(1575652,54,50,2,1,'Protož jest-li jaké potěšení v Kristu, jest-li které utěšení lásky, jest-li která společnost Ducha svatého, jsou-li která milosrdenství a slitování,'),
(1575653,54,50,2,2,'Naplňte radost mou v tom, abyste jednostejného smyslu byli, jednostejnou lásku majíce, jednodušní jsouce, jednostejně smýšlejíce,'),
(1575654,54,50,2,3,'Nic nečiňte skrze svár anebo marnou chválu, ale v pokoře jedni druhé za důstojnější sebe majíce.'),
(1575655,54,50,2,4,'Nehledejte jeden každý svých věcí, ale každý také toho, což jest jiných.'),
(1575656,54,50,2,5,'Budiž tedy tatáž mysl při vás, jakáž byla při Kristu Ježíši,'),
(1575657,54,50,2,6,'Kterýž jsa v způsobu Božím, nepoložil sobě toho za loupež rovný býti Bohu,'),
(1575658,54,50,2,7,'Ale samého sebe zmařil, způsob služebníka přijav, podobný lidem učiněn.'),
(1575659,54,50,2,8,'A v způsobu nalezen jako člověk, ponížil se, poslušný jsa učiněn až do smrti, a to do smrti kříže.'),
(1575660,54,50,2,9,'Protož i Bůh povýšil ho nade vše a dal jemu jméno, kteréž jest nad každé jméno,'),
(1575661,54,50,2,10,'Aby ve jménu Ježíše každé koleno klekalo, těch, kteříž jsou na nebesích, a těch, jenž jsou na zemi, i těch, jenž jsou pod zemí,'),
(1575662,54,50,2,11,'A každý jazyk aby vyznával, že Ježíš Kristus jest Pánem v slávě Boha Otce.'),
(1575663,54,50,2,12,'A tak, moji milí, jakož jste vždycky poslušni byli, netoliko v přítomnosti mé, ale nyní mnohem více, když jsem vzdálen od vás, s bázní a s třesením spasení své konejte.'),
(1575664,54,50,2,13,'Bůh zajisté jest, kterýž působí v vás i chtění i skutečné činění, podle dobře libé vůle své.'),
(1575665,54,50,2,14,'Všecko pak čiňte bez reptání a bez pochybování,'),
(1575666,54,50,2,15,'Abyste byli bez úhony, a upřímí synové Boží, bez obvinění uprostřed národu zlého a převráceného; mezi kterýmižto svěťte jakožto světla na světě,'),
(1575667,54,50,2,16,'Slovo života zachovávajíce, k chloubě mé v den Kristův, aby bylo vidíno, že jsem ne nadarmo běžel, ani nadarmo pracoval.'),
(1575668,54,50,2,17,'A bychť pak i obětován byl pro obět a službu víře vaší, raduji se a spolu raduji se se všemi vámi.'),
(1575669,54,50,2,18,'A též i vy radujte se a spolu radujte se se mnou.'),
(1575670,54,50,2,19,'Mámť pak naději v Kristu Ježíši, že Timotea brzy pošli vám, abych i já pokojné mysli byl, zvěda, kterak vy se máte.'),
(1575671,54,50,2,20,'Nebo žádného tak jednomyslného nemám, kterýž by tak vlastně o vaše věci pečoval.'),
(1575672,54,50,2,21,'Všickni zajisté svých věcí hledají, a ne těch, kteréž jsou Krista Ježíše.'),
(1575673,54,50,2,22,'Ale jej zkušeného býti víte, podle toho, že jakož syn s otcem se mnou přisluhoval v evangelium.'),
(1575674,54,50,2,23,'Tohoť hle, naději mám, že pošli, jakž jen porozumím, co se bude díti se mnou.'),
(1575675,54,50,2,24,'Mámť pak naději v Pánu, že i sám brzo k vám přijdu.'),
(1575676,54,50,2,25,'Ale zdálo se mi za potřebné Epafrodita, bratra a pomocníka a spolurytíře mého, vašeho pak apoštola i služebníka, v potřebě mé poslati k vám,'),
(1575677,54,50,2,26,'Poněvadž takovou měl žádost vás všecky viděti, a velmi těžek nad tím byl, že jste o něm slyšeli, že by byl nemocen.'),
(1575678,54,50,2,27,'A bylť jest jistě nemocen, i blízek smrti, ale Bůh se nad ním smiloval, a ne nad ním toliko, ale i nade mnou, abych zámutku na zámutek neměl.'),
(1575679,54,50,2,28,'Protož tím spěšněji poslal jsem ho k vám, abyste, vidouce jej zase, zradovali se, a já abych byl bez zámutku.'),
(1575680,54,50,2,29,'Protož přijmětež jej v Pánu se vší radostí, a mějte takové v uctivosti.'),
(1575681,54,50,2,30,'Neboť jest pro dílo Kristovo až k smrti se přiblížil, opováživ se života svého, jedné aby doplnil to, v čemž jste vy měli nedostatek při posloužení mně.'),
(1575682,54,50,3,1,'Dále pak, bratří moji, radujte se v Pánu. Jednostejných věcí vám psáti mně se jistě nestýště, vám pak to bezpečné jest.'),
(1575683,54,50,3,2,'Vizte psy, vizte zlé dělníky, vizte roztržku.'),
(1575684,54,50,3,3,'Nebo myť jsme obřízka, kteříž duchem sloužíme Bohu, a chlubíme se v Kristu Ježíši, a nedoufáme v těle,'),
(1575685,54,50,3,4,'Ačkoli i já mohl bych doufati v těle. Zdá-liť se komu jinému, že by mohl doufati v těle, já mnohem více,'),
(1575686,54,50,3,5,'Obřezán jsa osmého dne, jsa z rodu Izraelského, pokolení Beniaminova, Žid z Židů, podle zákona farizeus,'),
(1575687,54,50,3,6,'A z strany horlivosti protivník církve, z strany pak spravedlnosti zákonní jsa bez úhony.'),
(1575688,54,50,3,7,'Ale to, což mi bylo jako zisk, položil jsem sobě pro Krista za škodu.'),
(1575689,54,50,3,8,'Nýbrž i všecky věci pokládám škodou býti pro vyvýšenost známosti Krista Ježíše Pána mého, pro nějž jsem to všecko ztratil, a mám to jako za smetí, jedné abych Krista získal,'),
(1575690,54,50,3,9,'A v něm nalezen byl nemající své spravedlnosti, kteráž jest z Zákona, ale tu, kteráž jest z víry Kristovy, spravedlnost, kterážto jest z Boha a u víře záleží,'),
(1575691,54,50,3,10,'Abych tak poznal jej, a divnou moc vzkříšení jeho, a společnost utrpení jeho, připodobňuje se k smrti jeho,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575692,54,50,3,11,'Zda bych tak přišel k vzkříšení z mrtvých.'),
(1575693,54,50,3,12,'Ne že bych již dosáhl, aneb již dokonalým byl, ale snažně běžím, zda bych i dostihnouti mohl, načež uchvácen jsem od Krista Ježíše.'),
(1575694,54,50,3,13,'Bratří, jáť nemám za to, že bych již dosáhl.'),
(1575695,54,50,3,14,'Ale to jedno činím, na ty věci, kteréž jsou za mnou, zapomínaje, k těm pak, kteréž jsou přede mnou, úsilně chvátaje, k cíli běžím, k odplatě svrchovaného povolání Božího v Kristu Ježíši.'),
(1575696,54,50,3,15,'Protož kteřížkoli jsme dokonalí, to smýšlejme. A pakli v čem jinak smyslíte, i toť vám Bůh zjeví.'),
(1575697,54,50,3,16,'Ale k čemuž jsme již přišli, v tom při jednostejném zůstávejme pravidle a jednostejně smysleme.'),
(1575698,54,50,3,17,'Spolunásledovníci moji buďte, bratří, a šetřte těch, kteříž tak chodí, jakož máte příklad na nás.'),
(1575699,54,50,3,18,'Neboť mnozí chodí, o nichž jsem častokrát pravil vám a nyní s pláčem pravím, žeť jsou nepřátelé kříže Kristova,'),
(1575700,54,50,3,19,'Jichžto konec jest zahynutí, jejichžto bůh jest břicho, a sláva jejich v mrzkostech jejich, kteříž o zemské věci stojí.'),
(1575701,54,50,3,20,'Ale naše měšťanství jestiť v nebesích, odkudž i Spasitele očekáváme Pána Jezukrista,'),
(1575702,54,50,3,21,'Kterýž promění to tělo naše ponížené, tak aby bylo podobné k tělu slávy jeho, podle mocnosti té, kteroužto on mocen jest i všecky věci podmaniti sobě.'),
(1575703,54,50,4,1,'A tak, bratří moji milí a přežádoucí, jenž jste radost a koruna má, tak stůjte v Pánu, milí.'),
(1575704,54,50,4,2,'Evody prosím, i Syntychény prosím, aby jednostejně smyslily v Pánu.'),
(1575705,54,50,4,3,'Ano i tebe prosím, tovaryši můj vlastní, budiž jim pomocen, kteréžto v evangelium spolu se mnou pracovaly, i spolu s Klimentem a s jinými pomocníky mými, jejichžto jména napsána jsou v knize života.'),
(1575706,54,50,4,4,'Radujte se v Pánu vždycky; opět pravím, radujte se.'),
(1575707,54,50,4,5,'Středmost vaše známa buď všechněm lidem. Pán blízko.'),
(1575708,54,50,4,6,'O nic nebuďte pečliví, ale ve všech věcech skrze modlitbu a poníženou žádost s díků činěním prosby vaše známy buďte Bohu.'),
(1575709,54,50,4,7,'A pokoj Boží, kterýž převyšuje všeliký rozum, hájiti bude srdcí vašich i smyslů vašich v Kristu Ježíši.'),
(1575710,54,50,4,8,'Dále pak, bratří, kterékoli věci jsou pravé, kterékoli poctivé, kterékoli spravedlivé, kterékoli čisté, kterékoli milé, kterékoli dobropověstné, jest-li která ctnost, a jest-li která chvála, o těch věcech přemyšlujte.'),
(1575711,54,50,4,9,'Kterýmž jste se i naučili, je i přijali, a slyšeli i viděli na mně. Ty věci čiňte, a Bůh pokoje budeť s vámi.'),
(1575712,54,50,4,10,'Zradoval jsem se v Pánu velice z toho, že již opět zase rozzelenala se péče vaše o mne. Načež bezpochyby i prve myslili jste, ale nedostalo se vám příhodného času.'),
(1575713,54,50,4,11,'Ne proto, že bych jakou nouzi měl, toto pravím; nebo já naučil jsem se dosti míti na tom, což mám.'),
(1575714,54,50,4,12,'Umímť i snížen býti, umím také i hojnost míti; všudy a ve všech věcech pocvičen jsem, i nasycen býti i lačněti, i hojnost míti i nouzi trpěti.'),
(1575715,54,50,4,13,'Všecko mohu v Kristu, kterýž mne posiluje.'),
(1575716,54,50,4,14,'Avšak dobře jste učinili, účastni byvše mého soužení.'),
(1575717,54,50,4,15,'Víte pak i vy, Filipenští, že při počátku evangelium, když jsem šel z Macedonie, žádný sbor neudělil mi z strany dání a vzetí, než vy sami.'),
(1575718,54,50,4,16,'Ano i do Tesaloniky jednou i po druhé, čehož jsem potřeboval, poslali jste mi.'),
(1575719,54,50,4,17,'Ne protože bych hledal darů, ale hledám užitku hojného k vašemu prospěchu.'),
(1575720,54,50,4,18,'Přijalť jsem pak všecko, a hojněť mám, naplněnť jsem již, vzav od Epafrodita to, což posláno bylo od vás, k vůni sladkosti, obět vzácnou a libou Bohu.'),
(1575721,54,50,4,19,'Bůh pak můj naplníť všelikou potřebu vaši podle bohatství svého slavně v Kristu Ježíši.'),
(1575722,54,50,4,20,'Bohu pak a Otci našemu sláva na věky věků. Amen.'),
(1575723,54,50,4,21,'Pozdravtež všech svatých v Kristu Ježíši. Pozdravujíť vás bratří, kteříž jsou se mnou.'),
(1575724,54,50,4,22,'Pozdravujíť vás všickni svatí, zvláště pak ti, kteříž jsou z domu císařova.'),
(1575725,54,50,4,23,'Milost Pána našeho Jezukrista se všemi vámi. Amen. List tento k Filipenským psán jest z Říma po Epafroditovi.'),
(1575726,54,51,1,1,'Pavel apoštol Ježíše Krista, skrze vůli Boží, a Timoteus bratr,'),
(1575727,54,51,1,2,'Těm, kteříž jsou v městě Kolossis, svatým a věrným bratřím v Kristu: Milost vám a pokoj od Boha Otce našeho a Pána Ježíše Krista.'),
(1575728,54,51,1,3,'Díky činíme Bohu a Otci Pána našeho Jezukrista, vždycky za vás modléce se,'),
(1575729,54,51,1,4,'Slyšavše o víře vaší v Kristu Ježíši a o lásce ke všechněm svatým,'),
(1575730,54,51,1,5,'Pro naději složenou vám v nebesích, o níž jste prve slyšeli v slovu pravdy, jenž jest evangelium.'),
(1575731,54,51,1,6,'Kteréž jest přišlo k vám, jako i na všecken svět, a ovoce nese, jako i u vás, od toho dne, v kterémž jste slyšeli a poznali milost Boží v pravdě,'),
(1575732,54,51,1,7,'Jakož jste se i naučili od Epafry, milého spoluslužebníka našeho, kterýž jest věrný k vám služebník Kristův,'),
(1575733,54,51,1,8,'Kterýž také oznámil nám lásku vaši v Duchu.'),
(1575734,54,51,1,9,'Protož i my, od toho dne, jakž jsme to uslyšeli, nepřestáváme modliti se za vás a žádati, abyste naplněni byli známostí vůle jeho ve vší moudrosti a rozumnosti duchovní,'),
(1575735,54,51,1,10,'Abyste chodili hodně Pánu ke vší jeho líbeznosti, v každém skutku dobrém, ovoce vydávajíce a rostouce v známosti Boží,'),
(1575736,54,51,1,11,'Všelikou mocí zmocněni jsouce, podle síly slávy jeho, ke vší trpělivosti a dobrotivosti s radostí,'),
(1575737,54,51,1,12,'Díky činíce Otci, kterýž hodné nás učinil účastnosti losu svatých v světle,'),
(1575738,54,51,1,13,'Kterýž vytrhl nás z moci temnosti a přenesl do království milého Syna svého,'),
(1575739,54,51,1,14,'V němžto máme vykoupení skrze krev jeho, totiž odpuštění hříchů,'),
(1575740,54,51,1,15,'Kterýž jest obraz Boha neviditelného a prvorozený všeho stvoření.'),
(1575741,54,51,1,16,'Nebo skrze něho stvořeny jsou všecky věci, kteréž jsou na nebi i na zemi, viditelné i neviditelné, buďto trůnové nebo panstva, buďto knížatstva nebo mocnosti; všecko skrze něho a pro něho stvořeno jest.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575742,54,51,1,17,'A on jest přede vším a všecko jím stojí.'),
(1575743,54,51,1,18,'A onť jest hlava těla církve, kterýž jest počátek a prvorozený z mrtvých, aby tak on ve všem prvotnost držel,'),
(1575744,54,51,1,19,'Poněvadž se zalíbilo Otci, aby v něm všecka plnost přebývala,'),
(1575745,54,51,1,20,'A skrze něho aby smířil s sebou všecko, v pokoj uvodě skrze krev kříže jeho, skrze něj, pravím, buďto ty věci, kteréž jsou na zemi, buď ty, kteréž jsou na nebi.'),
(1575746,54,51,1,21,'A vás také někdy odcizené a nepřátely, v mysli vaší obrácené k skutkům zlým, nyní již smířil,'),
(1575747,54,51,1,22,'Tělem svým skrze smrt, aby vás postavil svaté, a neposkvrněné, a bez úhony před obličejem svým,'),
(1575748,54,51,1,23,'Však jestliže zůstáváte u víře založení a pevní, a neuchylujete se od naděje evangelium, kteréž jste slyšeli, jenž jest kázáno všemu stvoření, kteréž jest pod nebem, jehožto já Pavel učiněn jsem služebník;'),
(1575749,54,51,1,24,'Kterýž nyní raduji se z utrpení mých, kteráž snáším pro vás, a doplňuji ostatky soužení Kristových na těle svém za jeho tělo, jenž jest církev,'),
(1575750,54,51,1,25,'Jejížto učiněn jsem já služebník, tak jakž mi to svěřil Bůh na to, abych vám sloužil, a tak naplnil slovo Boží,'),
(1575751,54,51,1,26,'Jenž jest tajemství skryté od věků a národů, nyní pak zjevené svatým jeho.'),
(1575752,54,51,1,27,'Jimžto Bůh ráčil známo učiniti, kteraké by bylo bohatství slavného tajemství tohoto mezi pohany, jenž jest přebývání Krista v vás, kterýž jest naděje slávy,'),
(1575753,54,51,1,28,'Kteréhož my zvěstujeme, napomínajíce všelikého člověka a učíce všelikého člověka ve vší moudrosti, abychom postavili každého člověka dokonalého v Kristu Ježíši.'),
(1575754,54,51,1,29,'O čež i pracuji, bojuje podle té jeho mocnosti, kteráž dělá ve mně dílo své mocně.'),
(1575755,54,51,2,1,'Chciť zajisté, abyste věděli, kterakou nesnáz mám o vás a o ty, kteříž jsou v Laodicii a kteřížkoli neviděli tváři mé podle těla,'),
(1575756,54,51,2,2,'Aby potěšena byla srdce jejich, spojená v lásce, a to ke všemu bohatství přejistého smyslu, ku poznání tajemství Boha i Otce i Krista Pána,'),
(1575757,54,51,2,3,'V němžto jsou skryti všickni pokladové moudrosti a známosti.'),
(1575758,54,51,2,4,'A totoť pravím proto, aby vás žádný, falešně dovodě, neoklamal podobnou k pravdě řečí.'),
(1575759,54,51,2,5,'Nebo ačkoli vzdálen jsem tělem, však duchem s vámi jsem, raduje se, a vida řád váš a utvrzení té víry vaší v Krista.'),
(1575760,54,51,2,6,'Protož jakož jste přijali Krista Ježíše Pána, tak v něm choďte,'),
(1575761,54,51,2,7,'Vkořenění a vzdělaní na něm, a utvrzení u víře, jakž jste naučeni, rozhojňujíce se v ní s díků činěním.'),
(1575762,54,51,2,8,'Hleďtež, ať by vás někdo neobloupil moudrostí světa a marným zklamáním, uče podle ustanovení lidských, podle živlů světa, a ne podle Krista.'),
(1575763,54,51,2,9,'Nebo v něm přebývá všecka plnost Božství tělesně.'),
(1575764,54,51,2,10,'A vy v něm jste doplněni, kterýžto jest hlava všeho knížatstva i mocnosti,'),
(1575765,54,51,2,11,'V němžto i obřezáni jste obřezáním ne rukou učiněným, svlékše tělo hříchů v obřezání Kristovu,'),
(1575766,54,51,2,12,'Pohřbeni jsouce s ním ve křtu, skrze kterýžto i spolu s ním z mrtvých vstali jste skrze víru, jíž jste došli z mocnosti Boží, kterýž vzkřísil jej z mrtvých.'),
(1575767,54,51,2,13,'A vás, ještě mrtvé v hříších a v neobřízce těla vašeho, spolu s ním obživil, odpustiv vám všecky hříchy,'),
(1575768,54,51,2,14,'A smazav proti nám čelící zápis, jenž záležel v ustanoveních, a byl odporný nám, i vyzdvihl jej z prostředku, přibiv jej k kříži;'),
(1575769,54,51,2,15,'A obloupiv knížatstva i moci, vedl je na odivu zjevně, triumf slaviv nad nimi skrze něj.'),
(1575770,54,51,2,16,'Protož žádný vás nesuď pro pokrm, aneb pro nápoj, anebo z strany některého svátku, nebo novuměsíce, anebo sobot,'),
(1575771,54,51,2,17,'Kteréžto věci jsou stín budoucích, ale to, od čehož se stín dělal, jestiť tělo Kristovo.'),
(1575772,54,51,2,18,'Nižádný vás nepředchvacuj svémyslně pokorou a náboženstvím andělským, v to, čehož neviděl, vysokomyslně se vydávaje, marně se nadýmaje smyslem těla svého,'),
(1575773,54,51,2,19,'A nedrže se hlavy, od níž všecko tělo po kloubích a svazích vzdělané a spojené roste Božím zrůstem.'),
(1575774,54,51,2,20,'Poněvadž tedy zemřevše s Kristem osvobozeni jste od živlů světa, pročež tak jako byste živi byli světu, těmi ceremoniemi dáte se obtěžovati?'),
(1575775,54,51,2,21,'Když říkáte: Nedotýkej se, ani okoušej, aniž se s tím obírej!'),
(1575776,54,51,2,22,'Kteréžto všecky věci samým užíváním jich přicházejí k zkáze, a toť vše není než podle přikázání a učení lidských.'),
(1575777,54,51,2,23,'Ačťkoli pak ty věci mají tvárnost moudrosti, v způsobu té nábožnosti pošmourné a v povrchní pokoře i v neodpouštění tělu, avšak nejsou v žádné platnosti, když přináležejí toliko k nasycení těla.'),
(1575778,54,51,3,1,'Protož povstali-li jste s Kristem, vrchních věcí hledejte, kdež Kristus na pravici Boží sedí.'),
(1575779,54,51,3,2,'O svrchní věci pečujte, ne o zemské.'),
(1575780,54,51,3,3,'Nebo zemřeli jste, a život váš skryt jest s Kristem v Bohu.'),
(1575781,54,51,3,4,'Když se pak ukáže Kristus, život náš, tehdy i vy ukážete se s ním v slávě.'),
(1575782,54,51,3,5,'Protož mrtvěte údy své zemské, smilstvo, nečistotu, chlípnost, žádost zlou, i lakomství, jenž jest modlám sloužení.'),
(1575783,54,51,3,6,'Pro kteréžto věci přichází hněv Boží na syny zpurné.'),
(1575784,54,51,3,7,'V kterýchžto hříších i vy někdy chodili jste, když jste živi byli v nich.'),
(1575785,54,51,3,8,'Ale již nyní složtež i vy všecko to, hněv, prchlivost, zlobivost, zlořečení i mrzkomluvnost zapuďte od úst vašich.'),
(1575786,54,51,3,9,'Nelžete jedni na druhé, když jste svlékli s sebe starého člověka s skutky jeho,'),
(1575787,54,51,3,10,'A oblékli toho nového, obnovujícího se k známosti jasné, podle obrazu toho, jenž jej stvořil,'),
(1575788,54,51,3,11,'Kdežto není Řek a Žid, obřízka a neobřízka, cizozemec a Scýta, služebník a svobodný ale všecko a ve všech Kristus.'),
(1575789,54,51,3,12,'Protož oblectež se jako vyvolení Boží, svatí, a milí, v srdce lítostivé, v dobrotivost, nízké o sobě smýšlení, krotkost, trpělivost,'),
(1575790,54,51,3,13,'Snášejíce jeden druhého a odpouštějíce sobě vespolek, měl-li by kdo proti komu jakou žalobu; jako i Kristus odpustil vám, tak i vy.'),
(1575791,54,51,3,14,'Nadto pak nade všecko oblečeni buďte v lásku, kteráž jest svazek dokonalosti.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575792,54,51,3,15,'A pokoj Boží vítěziž v srdcích vašich, k němuž i povoláni jste v jedno tělo; a buďtež vděčni.'),
(1575793,54,51,3,16,'Slovo Kristovo přebývejž v vás bohatě se vší moudrostí; učíce a napomínajíce sebe vespolek Žalmy, a zpěvy, a písničkami duchovními, s milostí zpívajíce v srdci vašem Pánu.'),
(1575794,54,51,3,17,'A všecko, cožkoli činíte v slovu nebo v skutku, všecko čiňte ve jménu Pána Ježíše, díky činíce Bohu a Otci skrze něho.'),
(1575795,54,51,3,18,'Ženy poddány buďte mužům svým tak, jakž sluší, v Pánu.'),
(1575796,54,51,3,19,'Muži milujte ženy své, a nemějtež se přísně k nim.'),
(1575797,54,51,3,20,'Dítky poslouchejte rodičů ve všem; nebo to jest dobře libé Pánu.'),
(1575798,54,51,3,21,'Otcové nepopouzejte k hněvivosti dítek svých, aby sobě nezoufaly.'),
(1575799,54,51,3,22,'Služebníci poslušni buďte ve všem pánů svých tělesných, ne na oko toliko sloužíce, jako ti, jenž se usilují lidem líbiti, ale v sprostnosti srdce, bojíce se Boha.'),
(1575800,54,51,3,23,'A všecko, což byste koli činili, z té duše čiňte, jakožto Pánu, a ne lidem,'),
(1575801,54,51,3,24,'Vědouce, že ode Pána vzíti máte odplatu věčného dědictví; nebo Pánu Kristu sloužíte.'),
(1575802,54,51,3,25,'Kdož by pak nepravost páchal, odměnu své nepravosti vezme. A neníť přijímání osob u Boha.'),
(1575803,54,51,4,1,'Páni spravedlivě a slušně s služebníky svými nakládejte, vědouce, že i vy Pána máte v nebesích.'),
(1575804,54,51,4,2,'Na modlitbě buďtež ustaviční, bdíce v tom s díků činěním,'),
(1575805,54,51,4,3,'Modléce se spolu i za nás, aby Bůh otevřel nám dveře slova, k mluvení o tajemství Kristovu, pro něž i v vězení jsem,'),
(1575806,54,51,4,4,'Abych je zjevoval, tak jakž mi náleží mluviti.'),
(1575807,54,51,4,5,'Choďtež v moudrosti před těmi, kteříž jsou vně, čas kupujíce.'),
(1575808,54,51,4,6,'Řeč vaše vždycky budiž příjemná, ozdobená solí, tak abyste věděli, kterak byste měli jednomu každému odpovědíti.'),
(1575809,54,51,4,7,'O věcech mých o všech oznámí vám Tychikus, bratr milý, a věrný slouha Kristův a spoluslužebník v Pánu;'),
(1575810,54,51,4,8,'Kteréhož jsem poslal k vám naschvál, aby zvěděl, co se děje u vás, a potěšil srdcí vašich,'),
(1575811,54,51,4,9,'S Onezimem, věrným a milým bratrem, kterýž jest tam od vás. Tiť vám všecko oznámí, co se děje u nás.'),
(1575812,54,51,4,10,'Pozdravuje vás Aristarchus, spoluvězeň můj, a Marek, sestřenec Barnabášův, (o kterémž jsem vám poručil, přišel-li by k vám, přijmětež jej;)'),
(1575813,54,51,4,11,'A Jezus, kterýž slove Justus, kteřížto jsou Židé. Ti toliko jsou pomocníci moji v kázání o království Božím; tiť mi byli ku potěšení.'),
(1575814,54,51,4,12,'Pozdravuje vás Epafras, kterýž od vás jest, slouha Kristův, kterýž vždycky úsilně pracuje na modlitbách za vás, abyste stáli dokonalí a plní ve vší vůli Boží.'),
(1575815,54,51,4,13,'Nebo svědectví jemu vydávám, žeť vás velmi horlivě miluje, a též i ty, kteříž jsou v Laodicii, i kteříž jsou v Hierapoli.'),
(1575816,54,51,4,14,'Pozdravuje vás Lukáš, lékař, bratr milý, a Démas.'),
(1575817,54,51,4,15,'Pozdravte bratří Laodicenských, i Nymfy, i té církve, kteráž jest v domu jeho.'),
(1575818,54,51,4,16,'A když bude přečten u vás tento list, spravtež to, ať jest i v Laodicenském sboru čten; a ten, kterýž jest psán z Laodicie, i vy také přečtěte,'),
(1575819,54,51,4,17,'A rcete Archippovi: Viz, abys služebnost, kterouž jsi přijal od Pána, vyplnil.'),
(1575820,54,51,4,18,'Pozdravení mou rukou Pavlovou. Pamatujtež na mé vězení. Milost Boží budiž s vámi. Amen. List tento psán k Kolossenským z Říma po Tychikovi a Onezimovi.'),
(1575821,54,52,1,1,'Pavel a Silván a Timoteus církvi Tessalonicenských v Bohu Otci a v Pánu Ježíši Kristu: Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.'),
(1575822,54,52,1,2,'Díky činíme Bohu vždycky ze všech vás, zmínku činíce o vás na modlitbách našich,'),
(1575823,54,52,1,3,'Bez přestání pamatujíce na skutek víry vaší, a na práci svaté lásky, a na trpělivost naděje Pána našeho Jezukrista, před Bohem a Otcem naším,'),
(1575824,54,52,1,4,'Vědouce, bratří Bohu milí, o vyvolení vašem.'),
(1575825,54,52,1,5,'Nebo evangelium naše k vám nezáleželo toliko v slovu, ale i v moci, i v Duchu svatém, a v jistotě mnohé, jakož víte, jací jsme byli mezi vámi a to pro vás.'),
(1575826,54,52,1,6,'A vy následovníci naši i Páně učiněni jste, přijavše slovo jeho ve mnohé úzkosti, s radostí Ducha svatého,'),
(1575827,54,52,1,7,'Takže jste učiněni příklad dobrý všem věřícím v Macedonii a v Achaii.'),
(1575828,54,52,1,8,'Nebo od vás rozhlásilo se slovo Páně netoliko v Macedonii a v Achaii, ale i na všelikém místě víra vaše, kteráž jest v Boha, roznesla se, takže již nepotřebí nám o tom nic mluviti.'),
(1575829,54,52,1,9,'Oniť zajisté sami o nás vyznávají, jaký byl příchod náš k vám a kterak jste se obrátili k Bohu od modloslužby, abyste sloužili Bohu živému a pravému,'),
(1575830,54,52,1,10,'A očekávali Syna jeho s nebe, kteréhož jest vzkřísil z mrtvých, totiž Ježíše, kterýž vysvobodil nás od hněvu budoucího.'),
(1575831,54,52,2,1,'Nebo i vy sami víte, bratří, příchod náš k vám že jest nebyl daremný.'),
(1575832,54,52,2,2,'Ale i prve trpěvše, a pohanění snáševše, (jakož víte) v městě Filippis, osvobodili jsme se v Bohu našem mluviti vám směle evangelium Boží, s mnohými odpory.'),
(1575833,54,52,2,3,'Napomínání zajisté naše nebylo z podvodu, ani z nečistoty, ani ve lsti.'),
(1575834,54,52,2,4,'Ale jakož Bůh nás hodné učinil toho, aby nám svěřeno bylo evangelium, takť mluvíme, ne jako lidem se líbíce, ale Bohu, kterýž zkušuje srdcí našich.'),
(1575835,54,52,2,5,'Anižť jsme zajisté kdy užívali řeči pochlebné, jakož víte, ani za příčinou něčeho lakomství provodili. Bůhť jest svědek.'),
(1575836,54,52,2,6,'Ani jsme hledali od lidí chvály, ani od vás, ani od jiných, ač jsme mohli vás obtěžovati, jako Kristovi apoštolé.'),
(1575837,54,52,2,7,'Ale byli jsme tiší mezi vámi, jako když matka chová dítky své.'),
(1575838,54,52,2,8,'Tak nakloněni k vám byvše, hotovi jsme byli s velikou chutí, vydati vám netoliko evangelium Boží, ale také i duše naše, protože jste nám byli velmi milí.'),
(1575839,54,52,2,9,'Nebo pamatujete, bratří, na práci naši a ustávání. Ve dne i v noci zajisté pracovavše, proto abychom žádného z vás neobtěžovali, kázali jsme u vás evangelium Boží.'),
(1575840,54,52,2,10,'Vy jste svědkové toho i Bůh, kterak jsme svatě, a spravedlivě, a bez úhony obcovali mezi vámi, kteříž jste uvěřili,'),
(1575841,54,52,2,11,'Jakož víte, kterak jednoho každého z vás, jako otec dítek svých, napomínali jsme vás a potěšovali,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575842,54,52,2,12,'I s osvědčováním, abyste chodili hodně Bohu, kterýž povolal vás do království svého a v slávu.'),
(1575843,54,52,2,13,'Protož i my díky činíme Bohu bez přestání, že přijavše slovo Boží, kteréž jste slyšeli od nás, přijali jste ne jako slovo lidské, ale jakož v pravdě jest, jako slovo Boží, kterýžto i dílo své působí v vás věřících.'),
(1575844,54,52,2,14,'Vy zajisté, bratří, následovníci učiněni jste církví Božích, kteréž jsou v Židovstvu, v Kristu Ježíši; neb jste takovéž věci i vy trpěli od vašeho pokolení, jako i oni od Židů.'),
(1575845,54,52,2,15,'Kteříž jsou i Pána Ježíše zabili, i své vlastní proroky, a nás vyhnali, a Bohu se nelíbí, a všem lidem jsou odporní,'),
(1575846,54,52,2,16,'Nedopouštějíce nám mluviti pohanům, k tomu aby spaseni byli, aby tak vždy doplňovali hříchy své. Nebo vylit jest na ně hněv Boží konečný.'),
(1575847,54,52,2,17,'My pak, bratří, zbaveni byvše vás na chvíli tělem, ne srdcem, opravdověji usilovali jsme viděti tvář vaši s mnohou žádostí.'),
(1575848,54,52,2,18,'Protož chtěli jsme přijíti k vám, (zvláště já Pavel,) jednou i po druhé, ale překazil nám satan.'),
(1575849,54,52,2,19,'Nebo která jest naše naděje neb radost aneb koruna chlouby? Zdali ne i vy před obličejem Pána našeho Jezukrista v čas příchodu jeho?'),
(1575850,54,52,2,20,'Vy jistě jste sláva naše i radost.'),
(1575851,54,52,3,1,'Protož nemohše se déle zdržeti, za nejlepší se nám vidělo, abychom v Aténách pozůstali my sami,'),
(1575852,54,52,3,2,'A poslali jsme Timotea, bratra našeho a služebníka Božího a pomocníka našeho v evangelium Kristovu, aby potvrdil vás a napomenul k tomu, což náleží víře vaší,'),
(1575853,54,52,3,3,'Aby se žádný nepohnul od ní v takových těchto souženích. Neb i sami víte, že jsme k tomu postaveni.'),
(1575854,54,52,3,4,'Ještě zajisté, když jsme u vás byli, předpovídali jsme vám, že budeme souženi; jakož se i stalo, jakž víte.'),
(1575855,54,52,3,5,'Protož i já, nemoha se déle zdržeti, poslal jsem ho k vám, abych zvěděl o víře vaší, ať by snad nějak nepokoušel vás ten pokušitel, a tak aby nebyla daremná práce naše.'),
(1575856,54,52,3,6,'Nyní pak když k nám přišel Timoteus od vás a zvěstoval nám novinu veselou o víře a lásce vaší, a že nás připomínáte dobře, žádajíce vždycky nás viděti, jako také i my vás,'),
(1575857,54,52,3,7,'Protož potěšeni jsme z vás, bratří, ve všelikém soužení a nesnadnosti naší, skrze víru vaši.'),
(1575858,54,52,3,8,'Nebo aj, živi jsme, jestliže vy pevně stojíte v Pánu.'),
(1575859,54,52,3,9,'A jakým děkováním z vás můžeme se odměniti Bohu za všecku tu radost, kterouž radujeme se pro vás před obličejem Boha našeho,'),
(1575860,54,52,3,10,'Dnem i nocí přehorlivě modléce se, abychom uzřeli tvář vaši a doplnili to, čehož by se nedostávalo víře vaší?'),
(1575861,54,52,3,11,'Sám pak Bůh a Otec náš, a Pán náš Ježíš Kristus spraviž cestu naši k vám.'),
(1575862,54,52,3,12,'A vás tentýž Pán račiž rozmnožiti a rozhojniti v lásce, kterouž máte k sobě vespolek, i ke všechněm, jako i nás k vám,'),
(1575863,54,52,3,13,'Aby tak utvrzena byla srdce vaše neposkvrněná v svatosti, před Bohem a Otcem naším, ku příští Pána našeho Jezukrista, se všemi svatými jeho.'),
(1575864,54,52,4,1,'Dále pak, bratří, prosíme vás, a napomínáme v Pánu Ježíši, jakož jste přijali od nás, kterak byste měli choditi a líbiti se Bohu, v tom abyste se rozhojnili více.'),
(1575865,54,52,4,2,'Víte zajisté, jaká přikázání vydali jsme vám skrze Pána Ježíše.'),
(1575866,54,52,4,3,'Tať jest zajisté vůle Boží, totiž posvěcení vaše, abyste se zdržovali od smilstva,'),
(1575867,54,52,4,4,'A aby uměl jeden každý z vás svým osudím vládnouti v svatosti a v uctivosti,'),
(1575868,54,52,4,5,'Ne v libosti tělesných žádostí jako i pohané, kteříž Boha neznají;'),
(1575869,54,52,4,6,'A aby žádný neutiskal ani oklamával v jakémkoli jednání bratra svého, protože mstitel jest Pán všeho toho, jakož i předpověděli jsme vám a osvědčili.'),
(1575870,54,52,4,7,'Nebo nepovolal nás Bůh k nečistotě, ale ku posvěcení.'),
(1575871,54,52,4,8,'A protož kdo by pohrdal tímto, ne člověkem pohrdá, ale Bohem, kterýž i dal Ducha svého svatého nám.'),
(1575872,54,52,4,9,'O lásce pak bratrské neníť potřebí psáti vám; nebo jste vy již tomu od Boha naučeni, abyste milovali jedni druhé.'),
(1575873,54,52,4,10,'A jistě činíte to ke všechněm bratřím ve vší Macedonii. Napomínámeť pak vás, bratří, abyste se v tom ještě více rozhojnili,'),
(1575874,54,52,4,11,'A snažili se pokojni býti a hleděti toho, což komu náleží, a pracovati rukama svýma vlastníma, jakož jsme přikázali vám,'),
(1575875,54,52,4,12,'Tak abyste slušně chodili před těmi, kteříž jsou vně, a v ničemž abyste neměli nedostatku.'),
(1575876,54,52,4,13,'Nechciť pak, abyste nevěděli, bratří, o těch, kteříž zesnuli, abyste se nermoutili, jako i jiní, kteříž naděje nemají.'),
(1575877,54,52,4,14,'Nebo jakož věříme, že Ježíš umřel a z mrtvých vstal, takť Bůh i ty, kteříž by zesnuli v Ježíšovi, přivede s ním.'),
(1575878,54,52,4,15,'Toto zajisté vám pravíme slovem Páně, že my, kteříž živi pozůstaneme do příchodu Páně, nepředejdeme těch, kteříž zesnuli.'),
(1575879,54,52,4,16,'Nebo Pán náš s zvukem ponoukajícím, s hlasem archanděla a s troubou Boží sstoupí s nebe, a mrtví, kteříž jsou v Kristu, vstanou nejprve.'),
(1575880,54,52,4,17,'Potom my živí pozůstavení spolu s nimi zachváceni budeme do oblaků, vstříc Pánu v povětří, a tak vždycky se Pánem budeme.'),
(1575881,54,52,4,18,'A protož potěšujtež jedni druhých těmito slovy.'),
(1575882,54,52,5,1,'O časích pak a chvílech, bratří, nepotřebujete, aby vám psáno bylo.'),
(1575883,54,52,5,2,'Nebo vy sami výborně víte, že ten den Páně jako zloděj v noci, tak přijde.'),
(1575884,54,52,5,3,'Neb když dějí: Pokoj a bezpečnost, tedy rychle přijde na ně zahynutí, jako bolest ženě těhotné, a neujdouť toho.'),
(1575885,54,52,5,4,'Ale vy, bratří, nejste ve tmě, aby vás ten den jako zloděj zachvátil.'),
(1575886,54,52,5,5,'Všickni vy synové světla jste a synové dne; nejsmeť synové noci, ani tmy.'),
(1575887,54,52,5,6,'Nespěmež tedy, jako i jiní, ale bděme a střízliví buďme.'),
(1575888,54,52,5,7,'Nebo kteříž spí, v noci spí, a kteříž se opíjejí, v noci opilí jsou.'),
(1575889,54,52,5,8,'Ale my, synové dne jsouce, střízliví buďme, oblečeni jsouce v pancíř víry a lásky, a v lebku, jenž jest naděje spasení.'),
(1575890,54,52,5,9,'Nebo nepostavil nás Bůh k hněvu, ale k nabytí spasení, skrze Pána našeho Jezukrista,'),
(1575891,54,52,5,10,'Kterýž umřel za nás, abychom, buďto že bdíme, buďto že spíme, spolu s ním živi byli.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575892,54,52,5,11,'Protož napomínejte se vespolek, a vzdělávejte jeden druhého, jakož i činíte.'),
(1575893,54,52,5,12,'A prosímeť vás, bratří, znejtež ty, kteříž pracují mezi vámi, a předloženi jsou vám v Pánu, a napomínají vás,'),
(1575894,54,52,5,13,'A velice je milujte pro práci jejich. A mějte se k sobě vespolek pokojně.'),
(1575895,54,52,5,14,'A prosímeť vás, bratří, napomínejte z řádu vystupujících, potěšujte choulostivých, snášejte mdlé, trpělivě se mějte ke všechněm.'),
(1575896,54,52,5,15,'Vizte, aby někdo zlého za zlé neodplacoval, ale vždycky účinnosti dokazujte, i k sobě vespolek i ke všechněm.'),
(1575897,54,52,5,16,'Vždycky se radujte,'),
(1575898,54,52,5,17,'Bez přestání se modlte,'),
(1575899,54,52,5,18,'Ze všeho díky čiňte; nebo ta jest vůle Boží v Kristu Ježíši, aby se tak dálo od vás.'),
(1575900,54,52,5,19,'Ducha neuhašujte,'),
(1575901,54,52,5,20,'Proroctvím nepohrdejte,'),
(1575902,54,52,5,21,'Všeho zkuste; což dobrého jest, toho se držte.'),
(1575903,54,52,5,22,'Od všeliké zlé tvárnosti se varujte.'),
(1575904,54,52,5,23,'On pak Bůh pokoje posvětiž vás ve všem, a celý váš duch i duše i tělo bez úhony ku příští Pána našeho Jezukrista zachováno budiž.'),
(1575905,54,52,5,24,'Věrnýť jest ten, jenž povolal vás, kterýž také i učiní to.'),
(1575906,54,52,5,25,'Bratří, modlte se za nás.'),
(1575907,54,52,5,26,'Pozdravte všech bratří v políbením svatém.'),
(1575908,54,52,5,27,'Zavazujiť vás skrze Pána, aby čten byl list tento všechněm bratřím svatým.'),
(1575909,54,52,5,28,'Milost Pána našeho Jezukrista budiž s vámi. Amen. List první k Tessalonicenským psán jest v Aténách.'),
(1575910,54,53,1,1,'Pavel a Silván a Timoteus církvi Tessalonicenské v Bohu Otci našem a v Pánu Ježíši Kristu:'),
(1575911,54,53,1,2,'Milost vám a pokoj od Boha Otce našeho a od Pána Jezukrista.'),
(1575912,54,53,1,3,'Povinniť jsme díky činiti Bohu vždycky z vás, bratří, tak jakž hodné jest, protože velmi roste víra vaše a rozmáhá se láska jednoho každého z vás, všechněch k sobě vespolek,'),
(1575913,54,53,1,4,'Takže my se vámi v sbořích Božích chlubíme, vaší trpělivostí a věrou ve všech protivenstvích a souženích, kteráž snášíte;'),
(1575914,54,53,1,5,'Kterážto jsou zjevný důvod spravedlivého soudu Božího, abyste tak za hodné jmíni byli království Božího, pro něž i trpíte,'),
(1575915,54,53,1,6,'Poněvadž spravedlivé jest u Boha, aby zase odplaceno bylo těm, kteříž vás sužují, soužením,'),
(1575916,54,53,1,7,'Vám pak, úzkost trpícím, aby dáno bylo odpočinutí s námi, při zjevení Pána Ježíše s nebe, s anděly moci jeho,'),
(1575917,54,53,1,8,'V plameni ohně, kterýž pomstu uvede na ty, jenž neznají Boha a neposlouchají evangelium Pána našeho Jezukrista,'),
(1575918,54,53,1,9,'Kteříž pomstu ponesou, věčné zahynutí, zahnáni jsouce od tváři Páně a od slávy moci jeho,'),
(1575919,54,53,1,10,'Když přijde, aby oslaven byl v svatých svých a předivný ukázal se ve všech věřících, (nebo uvěřeno jest svědectví našemu u vás,) v onen den.'),
(1575920,54,53,1,11,'Pročež i modlíme se vždycky za vás, aby vás hodné učiniti ráčil povolání toho Bůh náš a vyplnil všecku dobře libou vůli dobrotivosti své, i skutek víry mocně,'),
(1575921,54,53,1,12,'Aby oslaveno bylo jméno Pána našeho Jezukrista v vás a vy v něm, podle milosti Boha našeho a Pána Jezukrista.'),
(1575922,54,53,2,1,'Prosímeť pak vás, bratří, skrze příští Pána našeho Jezukrista a naše shromáždění v něj,'),
(1575923,54,53,2,2,'Abyste se nedali rychle vyrážeti z mysli, ani kormoutiti, buď skrze ducha, buďto skrze řeč, neb skrze list, jako od nás poslaný, jako by nastával den Kristův.'),
(1575924,54,53,2,3,'Nesvodiž vás žádný nižádným obyčejem. Neboť nenastane den Páně, než až prve přijde odstoupení, a zjeven bude ten člověk hřícha, syn zatracení,'),
(1575925,54,53,2,4,'Protivící a povyšující se nade všecko, což slove Bůh, anebo čemuž se děje Božská čest, takže se posadí v chrámě Božím, tak sobě počínaje, jako by byl Bůh.'),
(1575926,54,53,2,5,'Nepomníte-liž, že ještě byv u vás, o tom jsem vám pravil?'),
(1575927,54,53,2,6,'A nyní co mešká, víte, totiž aby on teprv zjeven byl časem svým.'),
(1575928,54,53,2,7,'Nebo již tajemství nepravosti působí, toliko až by ten, jenž jej zdržuje nyní, z prostředku byl vyvržen.'),
(1575929,54,53,2,8,'A tehdážť zjeven bude ten bezbožník, kteréhož Pán zabije duchem úst svých a zkazí zjevením jasné přítomnosti své,'),
(1575930,54,53,2,9,'Kteréhožto nešlechetníka příští jest podle mocného díla satanova, se vší mocí a divy i zázraky lživými,'),
(1575931,54,53,2,10,'A se všelikým podvodem nepravosti v těch, jenž hynou, protože lásky pravdy nepřijali, aby spaseni byli.'),
(1575932,54,53,2,11,'A protož pošle jim Bůh mocné dílo podvodů, aby věřili lži,'),
(1575933,54,53,2,12,'A aby odsouzeni byli všickni, kteříž neuvěřili pravdě, ale oblíbili sobě nepravost.'),
(1575934,54,53,2,13,'Myť pak jsme povinni děkovati Bohu vždycky z vás, bratří Pánu milí, že vyvolil vás Bůh od počátku k spasení, v posvěcení Ducha a u víře pravdy,'),
(1575935,54,53,2,14,'K čemuž povolal vás skrze evangelium naše, k dojití slávy Pána našeho Jezukrista.'),
(1575936,54,53,2,15,'A protož, bratří, stůjtež a držtež se učení vydaného, jemuž jste se naučili, buďto skrze řeč, buďto i skrze list náš.'),
(1575937,54,53,2,16,'On pak Pán náš Ježíš Kristus, a Bůh i Otec náš, kterýž zamiloval nás a dal nám potěšení věčné a naději dobrou z milosti,'),
(1575938,54,53,2,17,'Potěšujž srdcí vašich a utvrdiž vás v každém slovu i skutku dobrém.'),
(1575939,54,53,3,1,'Dále pak, bratří, modlte se za nás, aby slovo Páně rozmáhalo se a slaveno bylo, jako i u vás,'),
(1575940,54,53,3,2,'A abychom vysvobozeni byli od nezbedných a zlých lidí. Neboť ne všech jest víra.'),
(1575941,54,53,3,3,'Ale věrnýť jest Pán, kterýž utvrdí vás a ostříhati bude od zlého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575942,54,53,3,4,'Doufámeť pak v Pánu o vás, že to, což vám předkládáme, činíte i činiti budete.'),
(1575943,54,53,3,5,'Pán pak spravujž srdce vaše k lásce Boží a k trpělivému očekávání Krista.'),
(1575944,54,53,3,6,'Přikazujemeť pak vám, bratří, ve jménu Pána našeho Jezukrista, abyste se oddělovali od každého bratra, kterýž by se choval neřádně a ne podle naučení vydaného, kteréž přijal od nás.'),
(1575945,54,53,3,7,'Nebo sami víte, kterak jest potřebí následovati nás, poněvadž jsme se nechovali mezi vámi neslušně.'),
(1575946,54,53,3,8,'Aniž jsme darmo chleba jedli u koho, ale s prací a s těžkostí, ve dne i v noci dělajíce, abychom žádnému z vás nebyli k obtížení.'),
(1575947,54,53,3,9,'Ne jako bychom neměli k tomu práva, ale abychom se vám za příklad vydali, abyste nás následovali.'),
(1575948,54,53,3,10,'Nebo i když jsme byli u vás, to jsme vám předkládali: Kdož nechce dělati, aby také nejedl.'),
(1575949,54,53,3,11,'Slyšímeť zajisté, že někteří mezi vámi chodí nezpůsobně, nic nedělajíce, ale v neužitečné věci se vydávajíce.'),
(1575950,54,53,3,12,'Protož těm, kteříž takoví jsou, přikazujeme, a napomínáme jich skrze Pána našeho Jezukrista, aby pokojně pracujíce, svůj chléb jedli.'),
(1575951,54,53,3,13,'Vy pak, bratří, neoblevujte dobře činíce.'),
(1575952,54,53,3,14,'Pakli kdo neuposlechne skrze psaní řeči naší, toho znamenejte, a nemějte s ním nic činiti, ať by se zastyděl.'),
(1575953,54,53,3,15,'Avšak nemějte ho za nepřítele, ale napomínejte jako bratra.'),
(1575954,54,53,3,16,'Sám pak Pán pokoje dejž vám vždycky pokoj všelijakým způsobem. Pán budiž se všemi vámi.'),
(1575955,54,53,3,17,'Pozdravení mou vlastní rukou Pavlovou, což jest za znamení v každém listu. Takť obyčejně píši.'),
(1575956,54,53,3,18,'Milost Pána našeho Jezukrista budiž se všemi vámi. Amen. Druhý list k Tessalonicenským psán byl z Atén.'),
(1575957,54,54,1,1,'Pavel, apoštol Ježíše Krista, podle zřízení Boha spasitele našeho a pána Jezukrista, naděje naší,'),
(1575958,54,54,1,2,'Timoteovi, vlastnímu synu u víře: Milost, milosrdenství a pokoj od Boha Otce našeho a od Krista Ježíše Pána našeho.'),
(1575959,54,54,1,3,'Jakož jsem prosil tebe, abys pozůstal v Efezu, když jsem šel do Macedonie, viziž, abys přikázal některým jiného učení neučiti,'),
(1575960,54,54,1,4,'Ani oblibovati básní a vypravování rodů, čemuž konce není, odkudž jen hádky pocházejí, více nežli vzdělání Boží, kteréž jest u víře,'),
(1575961,54,54,1,5,'Ješto konec přikázání jest láska z srdce čistého a z svědomí dobrého a z víry neošemetné.'),
(1575962,54,54,1,6,'Od čehož někteří jako od cíle pobloudivše, uchýlili se k marnomluvnosti,'),
(1575963,54,54,1,7,'Chtíce býti učitelé Zákona, a nerozumějíce, ani co mluví, ani čeho zastávají.'),
(1575964,54,54,1,8,'Víme pak, že dobrý jest Zákon, když by ho kdo náležitě užíval,'),
(1575965,54,54,1,9,'Toto znaje, že spravedlivému není uložen Zákon, ale nepravým a nepoddaným, bezbožným a hříšníkům, nešlechetným a nečistým, mordéřům otců svých a matek, vražedlníkům,'),
(1575966,54,54,1,10,'Smilníkům, samcoložníkům, těm, kteříž lidi kradou, lhářům, křivým přísežníkům, a jest-li co jiného, ješto by bylo naodpor zdravému učení,'),
(1575967,54,54,1,11,'Jenž jest podle slavného evangelium blahoslaveného Boha, kteréžto mně svěřeno jest.'),
(1575968,54,54,1,12,'Protož děkuji tomu, kterýž mne zmocnil, totiž Kristu Ježíši Pánu našemu, že mne za tak věrného soudil, aby mne v službě té postavil,'),
(1575969,54,54,1,13,'Ješto jsem prve byl ruhač, a protivník, a ukrutník. Ale milosrdenství jsem došel; neb jsem to z neznámosti činil v nevěře.'),
(1575970,54,54,1,14,'Rozhojnila se pak náramně milost Pána našeho, s věrou a s milováním, kteréž jest v Kristu Ježíši.'),
(1575971,54,54,1,15,'Věrnáť jest tato řeč a všelijak oblíbení hodná, že Kristus Ježíš přišel na svět, aby hříšné spasil, z nichžto já první jsem.'),
(1575972,54,54,1,16,'Ale proto milosrdenství jsem došel, aby na mně prvním dokázal Ježíš Kristus všeliké dobrotivosti, ku příkladu těm, kteříž mají uvěřiti v něho k životu věčnému.'),
(1575973,54,54,1,17,'Protož Králi věků nesmrtelnému, neviditelnému, samému moudrému Bohu budiž čest i sláva na věky věků. Amen.'),
(1575974,54,54,1,18,'Totoť přikázání poroučím tobě, synu Timotee, totiž abys podle předešlých o tobě proroctví bojoval v tom dobrý boj,'),
(1575975,54,54,1,19,'Maje víru a dobré svědomí, kteréžto někteří potrativše, zhynuli u víře.'),
(1575976,54,54,1,20,'Z nichžto jest Hymeneus a Alexander, kteréž jsem vydal satanu, aby trestáni jsouce, učili se nerouhati.'),
(1575977,54,54,2,1,'Napomínámť pak, aby především činěny bývaly pokorné modlitby, prosby, svaté žádosti a díků činění za všelijaké lidi,'),
(1575978,54,54,2,2,'Za krále i za všecky v moci postavené, abychom tichý a pokojný život vedli ve vší zbožnosti a šlechetnosti.'),
(1575979,54,54,2,3,'Nebo toť jest dobré a vzácné před spasitelem naším Bohem,'),
(1575980,54,54,2,4,'Kterýž chce, aby všelijací lidé spaseni byli a k známosti pravdy přišli.'),
(1575981,54,54,2,5,'Jedenť jest zajisté Bůh, jeden také i prostředník Boží a lidský, člověk Kristus Ježíš,'),
(1575982,54,54,2,6,'Kterýžto dal sebe samého mzdu na vykoupení za všecky, na osvědčení časem svým.'),
(1575983,54,54,2,7,'K čemuž postaven jsem já za kazatele a apoštola, (pravduť pravím v Kristu a neklamámť,) za učitele pohanů u víře a pravdě.'),
(1575984,54,54,2,8,'Protož chtěl bych, aby se modlili muži na všelikém místě, pozdvihujíce čistých rukou, bez hněvu a bez roztržitosti.'),
(1575985,54,54,2,9,'Takž také i ženy aby se oděvem slušným s stydlivostí a s středmostí ozdobovaly, ne strojením a křtaltováním sobě vlasů, neb zlatem, anebo perlami, anebo drahým rouchem,'),
(1575986,54,54,2,10,'Ale (tak, jakž sluší ženám, kteréž dokazují při sobě zbožnosti,) dobrými skutky.'),
(1575987,54,54,2,11,'Žena ať se učí mlčeci, ve všeliké poddanosti.'),
(1575988,54,54,2,12,'Nebo ženě nedopouštím učiti, ani vládnouti nad mužem, ale aby byla v mlčení.'),
(1575989,54,54,2,13,'Adam zajisté prve jest stvořen, potom Eva.'),
(1575990,54,54,2,14,'A Adam nebyl sveden, ale žena svedena jsuci, příčinou přestoupení byla.'),
(1575991,54,54,2,15,'Ale však spasena bude v plození dětí, jestliže by zůstala u víře, a v lásce, a v posvěcení svém, s středmostí.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1575992,54,54,3,1,'Věrnáť jest tato řeč, žádá-li kdo biskupství žeť výborné práce žádá.'),
(1575993,54,54,3,2,'Ale musíť biskup býti bez úhony, jedné manželky muž, bedlivý, středmý, vážný, k hostem přívětivý, způsobný k učení.'),
(1575994,54,54,3,3,'Ne pijan vína, ne bitec, ani mrzkého zisku žádostivý, ale mírný, ne svárlivý, ne lakomec,'),
(1575995,54,54,3,4,'Kterýž by dům svůj dobře spravoval, a dítky své měl v poddanosti se vší šlechetností.'),
(1575996,54,54,3,5,'(Nebo jestliže kdo domu svého spraviti neumí, kterak o církev Páně pečovati bude?)'),
(1575997,54,54,3,6,'Ne novák, aby snad nadut jsa, neupadl v potupení ďáblovo.'),
(1575998,54,54,3,7,'A musíť také i svědectví dobré míti od těch, kteříž jsou vně, aby neupadl v pohanění a v osidlo ďáblovo.'),
(1575999,54,54,3,8,'Takž podobně jáhnové musejí býti poctiví, ne dvojího jazyku, ne mnoho vína pijící, ne žádostiví mrzkého zisku,'),
(1576000,54,54,3,9,'Mající tajemství víry v svědomí čistém.'),
(1576001,54,54,3,10,'A ti také ať jsou nejprv zkušeni, a tak ať přisluhují, jsouce bez úhony.'),
(1576002,54,54,3,11,'Též i manželky jejich musejí býti šlechetné, neutrhavé, středmé, ve všem věrné.'),
(1576003,54,54,3,12,'Jáhnové buďtež jedné manželky muži, kteříž by své dítky dobře spravovali i své domy.'),
(1576004,54,54,3,13,'Nebo kteříž by dobře přisluhovali, dobrého stupně sobě dobudou, a mnohé doufanlivosti u víře, kteráž jest v Kristu Ježíši.'),
(1576005,54,54,3,14,'Totoť píši tobě, maje naději, že brzo přijdu k tobě.'),
(1576006,54,54,3,15,'Pakliť prodlím, abys věděl, kterak máš v domu Božím chovati se, jenž jest církev Boha živého, sloup a utvrzení pravdy.'),
(1576007,54,54,3,16,'A v pravdě velikéť jest tajemství zbožnosti, že Bůh zjeven jest v těle, ospravedlněn v Duchu, ukázal se andělům, kázán jest pohanům, uvěřeno jemu na světě, vzhůru přijat jest ve slávu.'),
(1576008,54,54,4,1,'Duch pak světle praví, že v posledních časích odvrátí se někteří od víry, poslouchajíce duchů bludných a učení ďábelských,'),
(1576009,54,54,4,2,'V pokrytství lež mluvících, a cejchované majících svědomí své,'),
(1576010,54,54,4,3,'Zbraňujících ženiti se, přikazujících zdržovati se od pokrmů, kteréž Bůh stvořil k užívání s díkčiněním věřícím a těm, jenž poznali pravdu.'),
(1576011,54,54,4,4,'Nebo všeliké stvoření Boží dobré jest, a nic nemá zamítáno býti, což se s díků činěním přijímá.'),
(1576012,54,54,4,5,'Posvěcuje se zajisté skrze slovo Boží a modlitbu.'),
(1576013,54,54,4,6,'Toto předkládaje bratřím, budeš dobrý služebník Jezukristův, vykrmený slovy víry a pravého učení, kteréhož jsi následoval.'),
(1576014,54,54,4,7,'Světské pak a babské básně zavrz, ale cvič se v zbožnosti.'),
(1576015,54,54,4,8,'Nebo tělesné cvičení malého jest užitku, ale zbožnost ke všemu jest užitečná, a má i nynějšího i budoucího života zaslíbení.'),
(1576016,54,54,4,9,'Věrnáť jest tato řeč a hodná, aby všelijak oblíbena byla.'),
(1576017,54,54,4,10,'Proto zajisté i pracujeme, i pohanění neseme, že naději máme v Bohu živém, kterýž jest spasitel všech lidí, a zvláště věřících.'),
(1576018,54,54,4,11,'Ty věci předkládej a uč.'),
(1576019,54,54,4,12,'Nižádný mladostí tvou nepohrdej, ale buď příkladem věrných v řeči, v lásce, v duchu, u víře, v čistotě.'),
(1576020,54,54,4,13,'Dokudž k tobě nepřijdu, buďiž pilen čítání, a napomínání, i učení.'),
(1576021,54,54,4,14,'Nezanedbávej daru, kterýž jest v tobě, jenž jest dán skrze proroctví s vzkládáním rukou starších na tě.'),
(1576022,54,54,4,15,'O tom přemyšluj, v tom buď ustavičně, aby prospěch tvůj zjevný byl všechněm.'),
(1576023,54,54,4,16,'Budiž sebe pilen i učení, a v tom trvej; nebo to čině, i samého sebe spasíš, i ty, kteříž tebe poslouchají.'),
(1576024,54,54,5,1,'Staršího zuřivě netresci, ale napomínej jako otce, mladších jako bratří,'),
(1576025,54,54,5,2,'Starých žen jako matek, mladic jako sestr, ve vší čistotě.'),
(1576026,54,54,5,3,'Vdovy měj v uctivosti, kteréž pravé vdovy jsou.'),
(1576027,54,54,5,4,'Pakli která vdova syny nebo vnuky má, nechažť se oni učí předně k svému domu pobožnosti dokazovati, a zase rodičům se odplacovati; neboť jest to chvalitebné a vzácné před obličejem Božím.'),
(1576028,54,54,5,5,'Kterážť pak právě vdova jest a osaměla, máť naději v Bohu, a trváť na modlitbách a svatých žádostech dnem i nocí.'),
(1576029,54,54,5,6,'Ale rozkošná, ta živa jsuci, již umřela.'),
(1576030,54,54,5,7,'Protož jim to přikaž, ať jsou bez úhony.'),
(1576031,54,54,5,8,'Jestliže pak kdo o své, a zvláště o domácí péče nemá, zapřelť jest víry, a jest horší nežli nevěřící.'),
(1576032,54,54,5,9,'Vdova buď vyvolená, kteráž by neměla méně šedesáti let, kteráž byla jednoho muže manželka,'),
(1576033,54,54,5,10,'O níž by svědectví bylo, že dobré skutky činila; a jestliže dítky své zbožně vychovala, do domu pocestné přijímala, jestliže svatým nohy umývala, jestliže bídným posluhovala, jestliže každého skutku dobrého pilná byla.'),
(1576034,54,54,5,11,'Ale mladých vdov nepřijímej; nebo když, nedbajíce na Krista, v chlipnost se vydadí, teprv se vdávati chtějí,'),
(1576035,54,54,5,12,'Jsouce již hodné odsouzení, protože první víru zrušily.'),
(1576036,54,54,5,13,'Nýbrž také i zahálejíce, učí se choditi po domích; a netoliko nedělné, ale jsou i klevetné a všetečné, mluvíce, což nesluší.'),
(1576037,54,54,5,14,'Protož chci, aby se mladší vdávaly, děti rodily, hospodyně byly, a tak žádné příčiny protivníku nedávaly ku pomlouvání.'),
(1576038,54,54,5,15,'Nebo již se některé uchýlily zpět po satanovi.'),
(1576039,54,54,5,16,'Protož má-liť kdo věřící neb která věřící vdovy, opatrujž je, a nebuď obtěžována církev, aby těm, kteréž právě vdovy jsou, postačilo.'),
(1576040,54,54,5,17,'Předložení, kteříž dobře spravují, dvojí cti hodni jmíni buďte, zvláště ti, kteříž pracují v slovu Božím a v učení.'),
(1576041,54,54,5,18,'Nebo praví Písmo: Volu mlátícímu nezavížeš úst. A hodenť jest dělník své mzdy.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576042,54,54,5,19,'Proti staršímu žaloby nepřijímej, leč pode dvěma nebo třmi svědky.'),
(1576043,54,54,5,20,'Ty pak, kteříž hřeší, přede všemi tresci, aby i jiní bázeň měli.'),
(1576044,54,54,5,21,'Osvědčujiť před obličejem Božím a Pána Jezukrista, i vyvolených andělů jeho, abys těchto věcí ostříhal bez přijímání osob, nic nečině podle náchylnosti.'),
(1576045,54,54,5,22,'Nevzkládej rukou rychle na nižádného, a nepřiúčastňuj se hříchům cizím. Sebe samého ostříhej v čistotě.'),
(1576046,54,54,5,23,'Nepij již více vody, ale vína skrovně užívej, pro svůj žaludek a časté nemoci své.'),
(1576047,54,54,5,24,'Některých lidí hříchové prve zjevní jsou, předcházející soud, některých pak i následují.'),
(1576048,54,54,5,25,'A takž také i skutkové dobří prve zjevní jsou. Což pak jest jinak, ukrýti se nemůže.'),
(1576049,54,54,6,1,'Kteřížkoli pod jhem jsou služebníci, ať mají pány své za hodné vší uctivosti, aby jméno Boží a učení jeho nebylo rouháno.'),
(1576050,54,54,6,2,'Kteříž pak mají pány věřící, nechažť jich sobě nezlehčují, protože jsou bratřími, ale tím raději slouží, protože jsou věřící a milí, dobrodiní Božího účastníci. Tomu vyučuj a napomínej.'),
(1576051,54,54,6,3,'Jestližeť pak kdo jinak učí, a nepovoluje zdravým řečem Pána našeho Jezukrista, a tomu učení, kteréž jest podle zbožnosti,'),
(1576052,54,54,6,4,'Takovýť jest nadutý, nic neuměje, ale nemoudrost provodí při otázkách a hádkách o slova, z kterýchžto pochází závist, svár, rouhání, zlá domnění,'),
(1576053,54,54,6,5,'Marné hádky lidí na mysli porušených a pravdy zbavených, domnívajích se, že by zbožnost byla zisk tělesný. Takových se varuj.'),
(1576054,54,54,6,6,'Jestiť pak zisk veliký zbožnost, s takovou myslí, kteráž na tom, což má, přestati umí.'),
(1576055,54,54,6,7,'Nic jsme zajisté nepřinesli na tento svět, bezpochyby že také nic odnésti nemůžeme.'),
(1576056,54,54,6,8,'Ale majíce pokrm a oděv, na tom přestaneme.'),
(1576057,54,54,6,9,'Kteříž pak chtí zbohatnouti, upadají v pokušení, a v osidlo, a v žádosti mnohé nerozumné a škodlivé, kteréž pohřižují lidi v zahynutí a v zatracení.'),
(1576058,54,54,6,10,'Kořen zajisté všeho zlého jestiť milování peněz, kterýchžto někteří žádostivi jsouce, pobloudili od víry a sami se naplnili bolestmi mnohými.'),
(1576059,54,54,6,11,'Ale ty, ó člověče Boží, takových věcí utíkej, následuj pak spravedlnosti, zbožnosti, víry, lásky, trpělivosti, tichosti.'),
(1576060,54,54,6,12,'Bojuj ten dobrý boj víry, dosáhni věčného života, k němuž i povolán jsi, a vyznals dobré vyznání před mnohými svědky.'),
(1576061,54,54,6,13,'Přikazujiť tobě před Bohem, kterýž všecko obživuje, a před Kristem Ježíšem, kterýž osvědčil před Pontským Pilátem dobré vyznání,'),
(1576062,54,54,6,14,'Abys ostříhal přikázání tohoto, chovaje se bez poskvrny a bez úhony, až do zjevení se Pána našeho Ježíše Krista,'),
(1576063,54,54,6,15,'Kteréž časem svým ukáže ten blahoslavený a sám mocný, Král kralujících a Pán panujících,'),
(1576064,54,54,6,16,'Kterýž sám má nesmrtelnost, a přebývá v světle nepřistupitelném, jehož žádný z lidí neviděl, aniž viděti může, kterémužto čest a síla věčná. Amen.'),
(1576065,54,54,6,17,'Bohatým tohoto světa přikazuj, ať nejsou vysokomyslní a ať nedoufají v nejistém zboží, ale v Bohu živém, kterýž dává nám hojnost všeho ku požívání.'),
(1576066,54,54,6,18,'A ať dobře činí, a bohatnou v dobrých skutcích, a snadní ať jsou k udílení, i přívětiví,'),
(1576067,54,54,6,19,'Tak sobě skládajíce základ dobrý k času budoucímu, aby dosáhli věčného života.'),
(1576068,54,54,6,20,'Ó Timotee, cožť jest svěřeno, ostříhej, utíkaje bezbožných daremních křiků a odporů falešně nazvaného umění,'),
(1576069,54,54,6,21,'Kterýmž někteří chlubíce se, z strany víry pobloudili od cíle. Milost Boží s tebou. Amen. K Timoteovi první list psán byl z Laodicie, města hlavního Frygie Pakacianské.'),
(1576070,54,55,1,1,'Pavel, apoštol Ježíše Krista, skrze vůli Boží, podle zaslíbení života, kterýž jest v Kristu Ježíši,'),
(1576071,54,55,1,2,'Timoteovi milému synu: Milost, milosrdenství a pokoj od Boha Otce a Krista Ježíše Pána našeho.'),
(1576072,54,55,1,3,'Díky činím Bohu, jemuž sloužím, jako i předkové moji, v svědomí čistém, z toho, že mám na tě ustavičnou pamět na svých modlitbách ve dne i v noci,'),
(1576073,54,55,1,4,'Žádaje viděti tebe, zpomínaje na tvé slzy, abych radostí naplněn byl,'),
(1576074,54,55,1,5,'Rozpomínaje se na tu víru, kteráž v tobě jest bez pokrytství, kteráž byla nejprv v bábě tvé Loidě, a v matce tvé Eunice, a tak smyslím, že i v tobě.'),
(1576075,54,55,1,6,'Pro kteroužto příčinu napomínám tebe, abys rozněcoval v sobě dar Boží, kterýžť jest dán skrze vzkládání rukou mých.'),
(1576076,54,55,1,7,'Nebo nedal nám Bůh ducha bázně, ale moci, a milování, a mysli způsobné.'),
(1576077,54,55,1,8,'Protož nestyď se za svědectví Pána našeho, ani za mne, vězně jeho, ale čitedlen buď úzkostí přicházejících pro evangelium podle moci Boží,'),
(1576078,54,55,1,9,'Kterýž spasil nás, a povolal povoláním svatým, ne podle skutků našich, ale podle uložení svého a milosti nám dané v Kristu Ježíši před časy věků,'),
(1576079,54,55,1,10,'Nyní pak teprv zjevené skrze příští Spasitele našeho Jezukrista, kterýž zahladil smrt, život pak na světlo vyvedl, i nesmrtelnost skrze evangelium,'),
(1576080,54,55,1,11,'Jehožto já ustanoven jsem kazatelem, a apoštolem, i učitelem pohanů.'),
(1576081,54,55,1,12,'A pro tu příčinu toto všecko trpím, ale nestydímť se za to; nebo vím, komu jsem uvěřil, a jist jsem tím, že mocen jest toho, což jsem u něho složil, ostříhati až do onoho dne.'),
(1576082,54,55,1,13,'Mějž jistý příklad zdravých řečí, kteréž jsi slýchal ode mne, u víře a v lásce, kteráž jest v Kristu Ježíši.'),
(1576083,54,55,1,14,'Výborného toho pokladu ostříhej, skrze Ducha svatého přebývajícího v nás.'),
(1576084,54,55,1,15,'Víš snad o tom, že se odvrátili ode mne všickni, kteříž jsou v Azii, z nichžto jest Fygellus a Hermogenes.'),
(1576085,54,55,1,16,'Dejž milosrdenství Pán domu Oneziforovu; nebo často mi činil pohodlí, aniž se styděl za řetězy mé.'),
(1576086,54,55,1,17,'Nýbrž přišed do Říma, pilně mne hledal, a nalezl.'),
(1576087,54,55,1,18,'Dejž jemu Pán nalézti milosrdenství u Pána v onen den. A jak mi mnoho posluhoval v Efezu, ty výborně víš.'),
(1576088,54,55,2,1,'Protož ty, synu můj, zmocniž se v milosti, kteráž jest v Kristu Ježíši.'),
(1576089,54,55,2,2,'A což jsi slyšel ode mne před mnohými svědky, svěřujž to lidem věrným, kteříž by způsobní byli i jiné učiti.'),
(1576090,54,55,2,3,'A tak ty snášej protivenství, jako ctný rytíř Ježíše Krista.'),
(1576091,54,55,2,4,'Žádný, kdož rytěřuje, neplete se v obecné živnosti, aby se svému hejtmanu líbil.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576092,54,55,2,5,'A jestliže by kdo i bojoval, nebudeť korunován, leč by řádně bojoval.'),
(1576093,54,55,2,6,'Pracovati musí i oráč, prve nežli užitku okusí.'),
(1576094,54,55,2,7,'Rozuměj, coť pravím, a dejž tobě Pán ve všem smysl pravý.'),
(1576095,54,55,2,8,'Pamatujž na to, že Ježíš Kristus vstal z mrtvých, jenž jest z semene Davidova, podle evangelium mého.'),
(1576096,54,55,2,9,'V kterémžto protivenství trpím, až i vězení, jako bych zločinec byl, ale slovo Boží není u vězení.'),
(1576097,54,55,2,10,'Protož všecko to snáším pro vyvolené Boží, aby i oni spasení došli, kteréžto jest v Kristu Ježíši, s slavou věčnou.'),
(1576098,54,55,2,11,'Věrná jest tato řeč. Nebo jestližeť jsme s ním zemřeli, tedy také spolu s ním živi budeme.'),
(1576099,54,55,2,12,'A trpíme-liť, budeme také spolu s ním kralovati; pakli ho zapíráme, i onť nás zapře.'),
(1576100,54,55,2,13,'A jsme-liť nevěrní, onť zůstává věrný; zapříti sám sebe nemůže.'),
(1576101,54,55,2,14,'Tyto věci připomínej, s osvědčováním před obličejem Páně, a ať se o slova nevadí, nebo to k ničemu není užitečné, ale jest ku podvrácení posluchačů.'),
(1576102,54,55,2,15,'Pilně se snažuj vydati sebe Bohu milého dělníka, za nějž by se nebylo proč styděti, a kterýž by právě slovo pravdy rozděloval.'),
(1576103,54,55,2,16,'Bezbožných pak těch křiků daremních varuj se, neboť velmi rozmnožují bezbožnost,'),
(1576104,54,55,2,17,'A řeč jejich jako rak rozjídá se. Z nichžto jest Hymeneus a Filétus,'),
(1576105,54,55,2,18,'Kteříž při pravdě pobloudili od cíle, pravíce, že by se již stalo vzkříšení, a převracejí víru některých.'),
(1576106,54,55,2,19,'Ale pevný základ Boží stojí, maje znamení toto: Znáť Pán ty, kteříž jsou jeho, a opět: Odstup od nepravosti každý, kdož vzývá jméno Kristovo.'),
(1576107,54,55,2,20,'V domu pak velikém netoliko jsou nádoby zlaté a stříbrné, ale také dřevěné i hliněné, a některé zajisté ke cti, některé pak ku potupě.'),
(1576108,54,55,2,21,'Protož jestliže by se kdo očistil od těch věcí, bude nádobou ke cti, posvěcenou, a užitečnou Pánu, ke všelikému skutku dobrému hotovou.'),
(1576109,54,55,2,22,'Mládenčích pak žádostí utíkej, ale následuj spravedlnosti, víry, lásky, pokoje, s těmi, kteříž vzývají Pána z srdce čistého.'),
(1576110,54,55,2,23,'Bláznivých pak a nevzdělavatelných otázek varuj se, věda, že plodí sváry.'),
(1576111,54,55,2,24,'Na služebníka pak Božího nesluší vaditi se, ale aby byl přívětivý ke všem, způsobný k učení, trpělivý,'),
(1576112,54,55,2,25,'Kterýž by v tichosti vyučoval ty, jenž se pravdě protiví, zda by někdy dal jim Bůh pokání ku poznání pravdy,'),
(1576113,54,55,2,26,'Aby sami k sobě přijdouce, dobyli se z osidla ďáblova, od něhož jsou zjímáni k vykonávání jeho vůle.'),
(1576114,54,55,3,1,'Toto pak věz, že v posledních dnech nastanou časové nebezpeční.'),
(1576115,54,55,3,2,'Nebo nastanou lidé sami sebe milující, peníze milující, chlubní, pyšní, zlolejci, rodičů neposlušní, nevděční, bezbožní,'),
(1576116,54,55,3,3,'Nelítostiví, smluv nezdrželiví, utrhači, nestředmí, plaší, kterýmž nic dobrého milo není,'),
(1576117,54,55,3,4,'Zrádci, přívažčiví, nadutí, rozkoší milovníci více nežli Boha,'),
(1576118,54,55,3,5,'Mající způsob pobožnosti, ale moci její zapírajíce, a od takových se odvracuj.'),
(1576119,54,55,3,6,'Nebo z těch jsou i ti, kteříž nacházejí do domů, a jímajíce, vodí ženky obtížené hříchy, jenž vedeny bývají rozličnými žádostmi,'),
(1576120,54,55,3,7,'Kteréž vždycky se učí, ale nikdy ku poznání pravdy přijíti nemohou.'),
(1576121,54,55,3,8,'Jakož zajisté Jannes a Jambres zprotivili se Mojžíšovi, tak i tito protiví se pravdě, lidé na mysli porušení a při víře spletení.'),
(1576122,54,55,3,9,'Ale nebudouť více prospívati. Nebo nemoudrost jejich zjevná bude všechněm, jako i oněchno byla.'),
(1576123,54,55,3,10,'Ale ty jsi došel mého učení, způsobu života mého, úmyslu, víry, snášelivosti, lásky, trpělivosti,'),
(1576124,54,55,3,11,'Protivenství, utrpení, kteráž na mne přišla v Antiochii, v Ikonii, a v Lystře; kterážto protivenství snášel jsem, ale ze všech vysvobodil mne Pán.'),
(1576125,54,55,3,12,'A takž i všickni, kteříž chtějí zbožně živi býti v Kristu Ježíši, protivenství míti budou.'),
(1576126,54,55,3,13,'Zlí pak lidé a svůdcové prospívati budou ze zlého v horší, i jiné v blud uvodíce, i sami bludem pojati jsouce.'),
(1576127,54,55,3,14,'Ale ty zůstávej v tom, čemužs se naučil a cožť jest svěřeno, věda, od kohos se naučil.'),
(1576128,54,55,3,15,'A že hned od dětinství svatá Písma znáš, kteráž tě mohou moudrého učiniti k spasení skrze víru, kteráž jest v Kristu Ježíši.'),
(1576129,54,55,3,16,'Všeliké zajisté Písmo od Boha jest vdechnuté, a užitečné k učení, k trestání, k napravování, k správě, kteráž náleží k spravedlnosti,'),
(1576130,54,55,3,17,'Aby byl dokonalý člověk Boží, ke všelikému skutku dobrému hotový.'),
(1576131,54,55,4,1,'Protož já osvědčuji před obličejem Božím a Pána Jezukrista, kterýž má souditi živé i mrtvé v den zjevení svého a království svého,'),
(1576132,54,55,4,2,'Kaž slovo Boží, ponoukej včas nebo nevčas, tresci, žehři, napomínej, ve vší tichosti a učení.'),
(1576133,54,55,4,3,'Nebo přijde čas, že zdravého učení nebudou přijímati, ale majíce svrablavé uši, podle svých vlastních žádostí shromažďovati sami sobě budou učitele.'),
(1576134,54,55,4,4,'A odvrátíť uši od pravdy, a k básněm obrátí.'),
(1576135,54,55,4,5,'Ale ty ve všem buď bedliv, protivenství snášej, dílo kazatele konej, dokazuj toho dostatečně, že jsi věrný Kristův služebník.'),
(1576136,54,55,4,6,'Neb já se již k tomu blížím, abych obětován byl, a čas rozdělení mého nastává.'),
(1576137,54,55,4,7,'Boj výborný bojoval jsem, běh jsem dokonal, víru jsem zachoval.'),
(1576138,54,55,4,8,'Již za tím odložena jest mi koruna spravedlnosti, kterouž dá mi v onen den Pán, ten spravedlivý soudce, a netoliko mně, ale i všechněm těm, kteříž milují příští jeho.'),
(1576139,54,55,4,9,'Přičiň se k tomu, abys ke mně brzo přišel.'),
(1576140,54,55,4,10,'Nebo Démas mne opustil, zamilovav tento svět, a šel do Tessaloniky, Krescens do Galacie, Titus do Dalmacie.'),
(1576141,54,55,4,11,'Sám toliko Lukáš se mnou jest. Marka vezmi s sebou; nebo jest mi velmi potřebný k službě.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576142,54,55,4,12,'Tychikať jsem poslal do Efezu.'),
(1576143,54,55,4,13,'Truhličku, kteréž jsem nechal v Troadě u Karpa, když půjdeš, přines s sebou, i knihy, zvláště pergamén.'),
(1576144,54,55,4,14,'Alexander kotlář mnoho mi zlého způsobil; odplatiž jemu Pán podle skutků jeho.'),
(1576145,54,55,4,15,'Kteréhož i ty se vystříhej; nebo velmi se protivil řečem našim.'),
(1576146,54,55,4,16,'Při prvním mém odpovídání žádný se mnou nebyl, ale všickni mne opustili. Nebudiž jim to počítáno za hřích.'),
(1576147,54,55,4,17,'Pán pak byl se mnou a posilnil mne, aby skrze mne utvrzeno bylo kázání o Kristu, a aby je slyšeli všickni národové. I vytržen jsem byl z úst lva.'),
(1576148,54,55,4,18,'A vysvobodíť mne Pán od každého skutku zlého a zachová k království svému nebeskému, jemuž sláva na věky věků. Amen.'),
(1576149,54,55,4,19,'Pozdrav Prišky a Akvile, i Oneziforova domu.'),
(1576150,54,55,4,20,'Erastus zůstal v Korintu, Trofima pak nechal jsem v Milétu nemocného.'),
(1576151,54,55,4,21,'Pospěš před zimou přijíti ke mně. Pozdravuje tebe Eubulus a Pudens a Línus a Klaudia, i všickni bratří.'),
(1576152,54,55,4,22,'Pán Ježíš Kristus budiž s duchem tvým. Milost Boží s vámi. Amen. List tento druhý psán jest z Říma k Timoteovi, (kterýž první v Efezu za biskupa skrze vzkládání rukou zřízen byl,) když Pavel opět po druhé se stavěl před císařem Neronem.'),
(1576153,54,56,1,1,'Pavel, služebník Boží, apoštol pak Ježíše Krista, podle víry vyvolených Božích a známosti pravdy, kteráž jest podle zbožnosti,'),
(1576154,54,56,1,2,'K naději života věčného, kterýž zaslíbil před časy věků ten, jenž nikdy neklamá, Bůh, zjevil pak časy svými,'),
(1576155,54,56,1,3,'Totiž to slovo své, skrze kázání mně svěřené, podle zřízení Spasitele našeho Boha, Titovi, vlastnímu synu u víře obecné:'),
(1576156,54,56,1,4,'Milost, milosrdenství a pokoj od Boha Otce a Pána Jezukrista Spasitele našeho.'),
(1576157,54,56,1,5,'Z té příčiny zanechal jsem tebe v Krétě, abys to, čehož tam ještě potřebí, spravil a ustanovil po městech starší, jakož i já při tobě jsem zřídil:'),
(1576158,54,56,1,6,'Jest-li kdo bez úhony, jedné manželky muž, dítky maje věřící, na kteréž by nemohlo touženo býti, že by byli bujní, anebo nepoddaní.'),
(1576159,54,56,1,7,'Neboť biskup má býti bez úhony, jako Boží šafář, ne svémyslný, ne hněvivý, ne pijan vína, ne bijce, ne žádostivý mrzkého zisku,'),
(1576160,54,56,1,8,'Ale přívětivý k hostem, dobrotivý, opatrný, spravedlivý, svatý, zdrželivý,'),
(1576161,54,56,1,9,'Pilně se přídržící věrné řeči v učení Božím, aby mohl i napomínati učením zdravým, i ty, kteříž odpírají, přemáhati.'),
(1576162,54,56,1,10,'Neboť jsou mnozí nepoddaní, marnomluvní, i svůdcové myslí lidských, zvláště ti, jenž jsou z obřízky.'),
(1576163,54,56,1,11,'Jimž musejí ústa zacpána býti; kteříž celé domy převracejí, učíce neslušným věcem, pro mrzký zisk.'),
(1576164,54,56,1,12,'Řekl jeden z nich, vlastní jejich prorok, že Kretenští jsou vždycky lháři, zlá hovada, břicha lenivá.'),
(1576165,54,56,1,13,'Svědectví to pravé jest. A protož tresciž je přísně, ať jsou zdraví u víře,'),
(1576166,54,56,1,14,'Nešetříce Židovských básní, a přikázání lidí těch, jenž se odvracují od pravdy.'),
(1576167,54,56,1,15,'Všecko zajisté čisté jest čistým, poskvrněným pak a nevěřícím nic není čistého, ale poskvrněná jest i mysl jejich i svědomí.'),
(1576168,54,56,1,16,'Vypravují o tom, že Boha znají, ale skutky svými toho zapírají, ohavní jsouce, a nepoddaní, a ke všelikému skutku dobrému nehodní.'),
(1576169,54,56,2,1,'Ty pak mluv, což sluší na zdravé učení.'),
(1576170,54,56,2,2,'Starci ať jsou střízliví, vážní, opatrní, zdraví u víře, v lásce, v snášelivosti.'),
(1576171,54,56,2,3,'Tak také i staré ženy ať chodí zbožně, v oděvu příslušném a ať nejsou převrhlé, ani mnoho vína pijící, dobrým věcem učící,'),
(1576172,54,56,2,4,'Aby mladice vyučovaly, kterak by muže své i dítky řádně milovaly,'),
(1576173,54,56,2,5,'A byly šlechetné, čistotné, netoulavé, dobrotivé, mužům svým poddané, aby nebylo dáno v porouhání slovo Boží.'),
(1576174,54,56,2,6,'Takž i mládenců napomínej k středmosti,'),
(1576175,54,56,2,7,'Ve všech věcech sebe samého vydávaje za příklad dobrých skutků, a zachovávaje v učení celost, vážnost,'),
(1576176,54,56,2,8,'Slovo zdravé bez úhony, aby ten, jenž by se protivil, zastyděti se musil, nemaje co zlého mluviti o vás.'),
(1576177,54,56,2,9,'Služebníky uč, ať jsou poddáni pánům svým, ve všem jim se líbíce, neodmlouvajíce,'),
(1576178,54,56,2,10,'Neokrádajíce, ale ve všem věrnosti pravé dokazujíce, aby učení Spasitele našeho Boha ve všem ozdobovali.'),
(1576179,54,56,2,11,'Zjevilať se jest zajisté ta milost Boží spasitelná všechněm lidem,'),
(1576180,54,56,2,12,'Vyučující nás, abychom odřeknouce se bezbožnosti a světských žádostí, střízlivě, a spravedlivě, a zbožně živi byli na tomto světě,'),
(1576181,54,56,2,13,'Očekávajíce té blahoslavené naděje a příští slávy velikého Boha a Spasitele našeho Jezukrista,'),
(1576182,54,56,2,14,'Kterýž dal sebe samého za nás, aby nás vykoupil od všeliké nepravosti, a očistil sobě samému lid zvláštní, horlivě následovný dobrých skutků.'),
(1576183,54,56,2,15,'Toto mluv, a napomínej, a tresci mocně. Žádný tebou nepohrzej.'),
(1576184,54,56,3,1,'Napomínej jich, ať jsou knížatům a mocnostem poddáni, jich poslušni, a ať jsou k každému skutku dobrému hotovi.'),
(1576185,54,56,3,2,'Žádnému ať se nerouhají, nejsou svárliví, ale přívětiví, dokazujíce všeliké tichosti ke všem lidem.'),
(1576186,54,56,3,3,'Byliť jsme zajisté i my někdy nesmyslní, tvrdošijní, bloudící, sloužíce žádostem a rozkošem rozličným, v zlosti a v závisti bydlíce, ohyzdní, vespolek se nenávidíce.'),
(1576187,54,56,3,4,'Ale když se zjevila dobrota a láska k lidem Spasitele našeho Boha,'),
(1576188,54,56,3,5,'Ne z skutků spravedlnosti, kteréž bychom my činili, ale podle milosrdenství svého spasil nás, skrze obmytí druhého narození, a obnovení Ducha svatého,'),
(1576189,54,56,3,6,'Kteréhož vylil na nás hojně, skrze Jezukrista Spasitele našeho,'),
(1576190,54,56,3,7,'Abychom, ospravedlněni jsouce milostí jeho, byli dědicové v naději života věčného.'),
(1576191,54,56,3,8,'Věrnáť jest řeč tato, a chciť, abys těch věcí potvrzoval, ať se snaží v dobrých skutcích předčiti všickni, kteříž uvěřili Bohu. A toť jsou ty věci dobré, i lidem užitečné.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576192,54,56,3,9,'Nemoudré pak otázky, a vyčítání rodů, a sváry, a hádky o věci zákonní zastavuj; nebť jsou neužitečné a marné.'),
(1576193,54,56,3,10,'Člověka kacíře po jednom neb druhém napomínání vyvrz,'),
(1576194,54,56,3,11,'Věda, že takový jest převrácený, a hřeší, svým vlastním soudem jsa odsouzen.'),
(1576195,54,56,3,12,'Když pošli k tobě Artemana aneb Tychika, snaž se přijíti ke mně do Nikopolim; neb jsem umínil tu přes zimu pobýti.'),
(1576196,54,56,3,13,'Zéna, učeného v Zákoně, a Apollo s pilností vyprovoď, ať v ničemž nemají nedostatku.'),
(1576197,54,56,3,14,'A nechažť se také učí i naši v dobrých skutcích předčiti, a zvláště, kdež jsou toho potřeby, aby nebyli neužiteční.'),
(1576198,54,56,3,15,'Pozdravují tě, kteříž jsou se mnou, všickni. Pozdraviž těch, kteříž nás milují u víře. Milost Boží budiž se všemi vámi. Amen. K Titovi, kterýž první biskup církve Kretenské skrze vzkládání rukou zřízen byl, psán z Nikopoli města Macedonského.'),
(1576199,54,57,1,1,'Pavel, vězeň Krista Ježíše, a Timoteus bratr, Filemonovi milému, a pomocníku našemu,'),
(1576200,54,57,1,2,'A Apfie sestře milé, a Archippovi spolurytíři našemu, i vší církvi, kteráž jest v domě tvém:'),
(1576201,54,57,1,3,'Milost vám a pokoj od Boha Otce našeho a Pána Jezukrista.'),
(1576202,54,57,1,4,'Díky činím Bohu svému, vždycky zmínku o tobě čině na svých modlitbách,'),
(1576203,54,57,1,5,'Slyše o lásce tvé a víře, kterouž máš ku Pánu Ježíšovi, i ke všechněm svatým,'),
(1576204,54,57,1,6,'Aby společnost víry tvé mocná byla a tudy poznáno býti mohlo, cožkoli dobrého jest v vás skrze Krista Ježíše.'),
(1576205,54,57,1,7,'Radost zajisté máme velikou, a potěšení z lásky tvé, že srdce svatých občerstvena jsou skrze tebe, bratře.'),
(1576206,54,57,1,8,'Protož ačkoli mnohou smělost mám v Kristu rozkázati tobě, což by náleželo,'),
(1576207,54,57,1,9,'Však pro lásku raději tebe prosím, jsa již takový, totiž Pavel starý, a nyní i vězeň Ježíše Krista.'),
(1576208,54,57,1,10,'Prosímť pak tebe za syna svého, kteréhož jsem zplodil v vězení svém, Onezima,'),
(1576209,54,57,1,11,'Kterýž byl někdy tobě neužitečný, ale nyní tobě i mně velmi užitečný, jehožť jsem odeslal.'),
(1576210,54,57,1,12,'Protož ty jej, (totiž srdce mé,) přijmi.'),
(1576211,54,57,1,13,'Kteréhožto já chtěl jsem byl při sobě zanechati, aby mi posluhoval místo tebe v vězení, kteréž trpím pro evangelium;'),
(1576212,54,57,1,14,'Ale bez vědomí tvého nechtěl jsem nic učiniti, aby dobrý skutek tvůj nebyl jako bezděky, ale z dobré vůle.'),
(1576213,54,57,1,15,'Ano snad proto byl odšel na chvíli, abys jej potom věčného měl,'),
(1576214,54,57,1,16,'Již ne jako služebníka, ale více než služebníka, totiž bratra milého, zvláště mně, a čím víc tobě, i podle těla, i v Pánu.'),
(1576215,54,57,1,17,'Protož máš-li mne za tovaryše, přijmiž jej, jako mne.'),
(1576216,54,57,1,18,'Jestližeť pak v čem ublížil, anebo jest-liť co dlužen, to mně přičti.'),
(1576217,54,57,1,19,'Já Pavel psal jsem svou rukou, jáť zaplatím; ať nedím tobě, že ty i sám sebe jsi mi dlužen.'),
(1576218,54,57,1,20,'Tak, bratře, ať já uživu tebe v Pánu; očerstviž srdce mé v Pánu.'),
(1576219,54,57,1,21,'Jist jsa tvým poslušenstvím, tak jsem tobě napsal, věda, že i více, nežli pravím, učiníš.'),
(1576220,54,57,1,22,'A mezi tím připraviž mi také hospodu; neboť naději mám, že k modlitbám vašim budu vám navrácen.'),
(1576221,54,57,1,23,'Pozdravují tě Epafras, (spoluvězeň můj pro Krista Ježíše,)'),
(1576222,54,57,1,24,'Marek, Aristarchus, Démas a Lukáš, pomocníci moji.'),
(1576223,54,57,1,25,'Milost Pána našeho Jezukrista budiž s duchem vaším. Amen. List tento k Filemonovi psán byl z Říma po Onezimovi služebníku.'),
(1576224,54,58,1,1,'Častokrát a rozličnými způsoby mluvíval někdy Bůh otcům skrze proroky, v těchto pak posledních dnech mluvil nám skrze Syna svého,'),
(1576225,54,58,1,2,'Kteréhož ustanovil dědicem všeho, skrze něhož i věky učinil.'),
(1576226,54,58,1,3,'Kterýžto jsa blesk slávy, a obraz osoby jeho, a zdržuje všecko slovem mocnosti své, očištění hříchů našich skrze sebe samého učiniv, posadil se na pravici velebnosti na výsostech,'),
(1576227,54,58,1,4,'Tím důstojnější nad anděly učiněn, čím vyvýšenější nad ně jméno dědičně obdržel.'),
(1576228,54,58,1,5,'Nebo kterému kdy z andělů řekl: Syn můj jsi ty, já dnes zplodil jsem tebe? A opět: Já budu jemu Otcem, a on mi bude Synem?'),
(1576229,54,58,1,6,'A opět, když uvodí prvorozeného na okršlek země, dí: A klanějte se jemu všickni andělé Boží.'),
(1576230,54,58,1,7,'A o andělích zajisté dí: Kterýž činí anděly své duchy, a služebníky své plamen ohně;'),
(1576231,54,58,1,8,'Ale k Synu dí: Stolice tvá, ó Bože, trvá na věky věků, berla pravosti jestiť berla království tvého.'),
(1576232,54,58,1,9,'Miloval jsi spravedlnost, a nenáviděl jsi nepravosti, protož pomazal tebe, ó Bože, Bůh tvůj olejem veselé nad spoluúčastníky tvé.'),
(1576233,54,58,1,10,'A opět:Ty, Pane, na počátku založil jsi zemi, a díla rukou tvých jsouť nebesa.'),
(1576234,54,58,1,11,'Onať pominou, ty pak zůstáváš; a všecka jako roucho zvetšejí,'),
(1576235,54,58,1,12,'A jako oděv svineš je, i budouť změněna. Ale ty jsi vždycky tentýž, a léta tvá nikdy nepřestanou.'),
(1576236,54,58,1,13,'A kterému kdy z andělů řekl: Seď na pravici mé, dokavadž nepoložím nepřátel tvých za podnože noh tvých?'),
(1576237,54,58,1,14,'Zdaliž všickni nejsou služební duchové, kteříž posíláni bývají k službě pro ty, jenž mají dědičně obdržeti spasení?'),
(1576238,54,58,2,1,'Protož musímeť my tím snažněji šetřiti toho, což jsme slýchali, aby nám to nevymizelo.'),
(1576239,54,58,2,2,'Nebo poněvadž skrze anděly mluvené slovo bylo pevné, a každé přestoupení a neposlušenství vzalo spravedlivou odměnu pomsty,'),
(1576240,54,58,2,3,'Kterakž my utečeme, takového zanedbávajíce spasení? Kteréžto nejprvé začalo vypravováno býti skrze samého Pána, od těch pak, kteříž Pána slýchali, nám utvrzeno jest.'),
(1576241,54,58,2,4,'Čemuž i Bůh svědectví vydával skrze divy a zázraky, a rozličné moci, i podělování Duchem svatým, podle vůle své.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576242,54,58,2,5,'Nebo nepoddal andělům okršlku země budoucího, o kterémž mluvíme.'),
(1576243,54,58,2,6,'Osvědčilť jest pak na jednom místě jeden, řka: Co jest člověk, že naň pomníš, aneb syn člověka, že na něj patříš.'),
(1576244,54,58,2,7,'Maličkos jej menšího andělů učinil, slavou a ctí korunoval jsi ho, a ustanovils jej nad dílem rukou svých.'),
(1576245,54,58,2,8,'Všecko jsi podmanil pod nohy jeho. A kdyžť jest jemu všecko poddal, tedy ničeho nezanechal nepodmaněného jemu. Ačkoli nyní ještě nevidíme, aby jemu všecko poddáno bylo.'),
(1576246,54,58,2,9,'Ale toho maličko nižšího andělů, vidíme Ježíše, pro utrpení smrti slávou a ctí korunovaného, aby z milosti Boží za všecky okusil smrti.'),
(1576247,54,58,2,10,'Slušeloť zajisté na toho, pro kteréhož jest všecko, a skrze kteréhož jest všecko, aby mnohé syny přiveda k slávě, vůdce spasení jejich skrze utrpení dokonalého učinil.'),
(1576248,54,58,2,11,'Nebo i ten, jenž posvěcuje, i ti, kteříž posvěceni bývají, z jednoho jsou všickni. Pro kteroužto příčinu nestydí se jich nazývati bratřími,'),
(1576249,54,58,2,12,'Řka: Zvěstovati budu jméno tvé bratřím svým, uprostřed shromáždění prozpěvovati budu tobě.'),
(1576250,54,58,2,13,'A opět: Já budu v něm doufati. A opět: Aj, já a dítky, kteréž dal mi Bůh.'),
(1576251,54,58,2,14,'Poněvadž tedy dítky účastnost mají těla a krve, i on též podobně účasten jest jich, aby skrze smrt zahladil toho, kterýž má vládařství smrti, to jest ďábla,'),
(1576252,54,58,2,15,'A abyvysvobodil ty, kteřížto bázní smrti po všecken čas života svéhopodrobeni byli v službu.'),
(1576253,54,58,2,16,'Neboť nepřijal andělů, ale símě Abrahamovo přijal.'),
(1576254,54,58,2,17,'A protož ve všem připodobněn býti měl bratřím, aby milosrdný byl a věrný nejvyšší kněz v tom, což by u Boha k očištění hříchů lidu jednáno býti mělo.'),
(1576255,54,58,2,18,'Nebo že jest i sám trpěl, pokoušín byv, může také pokušení trpícím spomáhati.'),
(1576256,54,58,3,1,'A protož, bratří svatí, povolání nebeského účastníci, spatřujte apoštola a nejvyššího kněze vyznání našeho, Krista Ježíše,'),
(1576257,54,58,3,2,'Věrného tomu, kdož jej ustanovil, jako i Mojžíš byl věrný ve všem domě jeho.'),
(1576258,54,58,3,3,'Tím větší zajisté slávy tento nad Mojžíše jest hoden, čím větší má čest stavitel nežli sám dům.'),
(1576259,54,58,3,4,'Nebo všeliký dům ustaven bývá od někoho, ten pak, kdož všecky tyto věci ustavěl, Bůh jest.'),
(1576260,54,58,3,5,'A Mojžíš zajisté věrný byl v celém domě jeho, jako služebník, na osvědčení toho, což potom mělo mluveno býti.'),
(1576261,54,58,3,6,'Ale Kristus, jakožto Syn, vládne nad domem svým. Kterýžto dům my jsme, jestliže tu svobodnou doufanlivost, a tu chloubu naděje až do konce pevnou zachováme.'),
(1576262,54,58,3,7,'Protož jakž praví Duch svatý: Dnes, uslyšeli-li byste hlas jeho,'),
(1576263,54,58,3,8,'Nezatvrzujtež srdcí svých, jako při onom popouzení Boha v den pokušení toho na poušti;'),
(1576264,54,58,3,9,'Kdežto pokoušeli mne otcové vaši, zkusiliť jsou mne, a viděli skutky mé po čtyřidceti let.'),
(1576265,54,58,3,10,'Protož hněviv jsem byl na pokolení to, a řekl jsem: Tito vždycky bloudí srdcem, a nepoznávají cest mých.'),
(1576266,54,58,3,11,'Takže jsem přisáhl v hněvě svém, že nevejdou v odpočinutí mé.'),
(1576267,54,58,3,12,'Viztež, bratří, aby snad v někom z vás nebylo srdce zlé, a nevěrné, kteréž by odstupovalo od Boha živého.'),
(1576268,54,58,3,13,'Ale napomínejte se vespolek po všecky dny, dokavadž se dnes jmenuje, aby někdo nebyl zatvrzen oklamáním hřícha.'),
(1576269,54,58,3,14,'Účastníci zajisté Krista učiněni jsme, jestliže však ten počátek podstaty až do konce pevný zachováme.'),
(1576270,54,58,3,15,'Protož dokudž se říká: Dnes, uslyšeli-li byste hlas jeho, nezatvrzujte srdcí svých, jako při onom popouzení Boha.'),
(1576271,54,58,3,16,'Nebo někteří slyševše, popouzeli ho, ale ne všickni, jenž vyšli z Egypta skrze Mojžíše.'),
(1576272,54,58,3,17,'Na které se pak hněval čtyřidceti let? Zdali ne na ty, kteříž hřešili, jejichžto těla padla na poušti?'),
(1576273,54,58,3,18,'A kterým zapřisáhl, že nevejdou do odpočinutí jeho? Však těm, kteříž byli neposlušní.'),
(1576274,54,58,3,19,'A vidíme, že jsou nemohli vjíti pro nevěru.'),
(1576275,54,58,4,1,'Bojmež se tedy, aby snad opustě zaslíbení o vjití do odpočinutí jeho, neopozdil se někdo z vás.'),
(1576276,54,58,4,2,'Nebo i nám zvěstováno jest, jako i oněmno, ale neprospěla jim řeč slyšená, nepřipojená k víře, když slyšeli.'),
(1576277,54,58,4,3,'Neboť vcházíme v odpočinutí my, kteříž jsme uvěřili, jakož řekl: Protož jsem přisáhl v hněvě svém, žeť nevejdou v odpočinutí mé, ačkoli dávno odpočinul Bůh, hned po vykonání skutků od ustanovení světa.'),
(1576278,54,58,4,4,'Nebo pověděl na jednom místě o sedmém dni takto: I odpočinul Bůh dne sedmého ode všech skutků svých.'),
(1576279,54,58,4,5,'A tuto zase: Že nevejdou v odpočinutí mé.'),
(1576280,54,58,4,6,'A poněvadž vždy na tom jest, že někteří mají vjíti do něho, a ti, kterýmž prvé zvěstováno jest, nevešli pro svou nevěru,'),
(1576281,54,58,4,7,'Opět ukládá den jakýsi, Dnes, pravě skrze Davida, po takovém času, jakož řečeno jest, Dnes uslyšíte-li hlas jeho, nezatvrzujte srdcí svých.'),
(1576282,54,58,4,8,'Nebo byť byl Jozue v odpočinutí je uvedl, nebylť by potom mluvil o jiném dni.'),
(1576283,54,58,4,9,'A protož zůstáváť svátek lidu Božímu.'),
(1576284,54,58,4,10,'Neb kdožkoli všel v odpočinutí jeho, takéť i on odpočinul od skutků svých, jako i Bůh od svých.'),
(1576285,54,58,4,11,'Snažmež se tedy vjíti do toho odpočinutí, aby někdo neupadl v týž příklad nedověry.'),
(1576286,54,58,4,12,'Živáť jest zajisté řeč Boží a mocná, a pronikavější nad všeliký meč na obě straně ostrý, a dosahujeť až do rozdělení i duše i ducha i kloubů i mozku v kostech, a rozeznává myšlení i mínění srdce.'),
(1576287,54,58,4,13,'A neníť žádného stvoření, kteréž by nebylo zjevné před obličejem jeho, nýbrž všecky věci jsou nahé a odkryté očima toho, o kterémž jest řeč naše.'),
(1576288,54,58,4,14,'Protož majíce nejvyššího kněze velikého, kterýžto pronikl nebesa, Ježíše Syna Božího, držmež vyznání naše.'),
(1576289,54,58,4,15,'Nebo nemáme nejvyššího kněže, kterýž by nemohl čitedlen býti mdlob našich, ale zkušeného ve všem nám podobně, kromě hříchu.'),
(1576290,54,58,4,16,'Přistupmež tedy směle s doufáním k trůnu milosti, abychom dosáhli milosrdenství, a milost nalezli ku pomoci v čas příhodný.'),
(1576291,54,58,5,1,'Všeliký zajisté nejvyšší kněz z lidu vzatý za lidi bývá postaven v těch věcech, kteréž u Boha mají jednány býti, totiž aby obětoval i dary i oběti za hříchy,');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576292,54,58,5,2,'Kterýž by mohl, jakž sluší, lítost míti nad neznajícími a bloudícími, jsa i sám obklíčen nemocí.'),
(1576293,54,58,5,3,'A pro ni povinen jest, jakož za lid, tak i za sebe samého obětovati oběti za hříchy.'),
(1576294,54,58,5,4,'A aniž kdo sobě sám té cti osobuje, ale ten, kterýž by byl povolán od Boha, jako i Aron.'),
(1576295,54,58,5,5,'Tak i Kristus ne sám sobě té cti osobil, aby byl nejvyšším knězem, ale ten, kterýž řekl jemu: Syn můj jsi ty, já dnes zplodil jsem tebe.'),
(1576296,54,58,5,6,'Jakž i jinde praví: Ty jsi kněz na věky podle řádu Melchisedechova.'),
(1576297,54,58,5,7,'Kterýž za dnů těla svého modlitby a ponížené prosby k tomu, kterýž ho mohl zachovati od smrti, s křikem velikým a slzami obětoval, a uslyšán jest i vysvobozen z toho, čehož se strašil.'),
(1576298,54,58,5,8,'A ačkoli byl Syn Boží, z toho však, což strpěl, naučil se poslušenství.'),
(1576299,54,58,5,9,'A tak dokonalý jsa, učiněn jest všechněm sebe poslušným původem spasení věčného,'),
(1576300,54,58,5,10,'Nazván jsa od Boha nejvyšším knězem podlé řádu Melchisedechova.'),
(1576301,54,58,5,11,'O kterémž mnoho by se mělo mluviti, a to nesnadných věci k vypravení, ale vy jste nezpůsobných uší.'),
(1576302,54,58,5,12,'Nebo měvše býti v tak dlouhém času mistři, opět potřebujete učeni býti prvním počátkům výmluvností Božích, a učiněni jste mléka potřebující, a ne pokrmu hrubšího.'),
(1576303,54,58,5,13,'Kdožkoli zajisté mléka se drží, nechápá slova spravedlnosti; (nebo nemluvně jest).'),
(1576304,54,58,5,14,'Ale dokonalých jest hrubý pokrm, totiž těch, kteříž pro zvyklost mají smysly způsobné k rozeznání dobrého i zlého.'),
(1576305,54,58,6,1,'Protož opustíce řeč počátku Kristova, k dokonalosti se nesme, ne opět zakládajíce gruntu pokání z skutků mrtvých, a víry v Boha,'),
(1576306,54,58,6,2,'Křtů učení, vzkládání rukou, a vzkříšení z mrtvých, i soudu věčného.'),
(1576307,54,58,6,3,'A toť učiníme, dopustí-li Bůh.'),
(1576308,54,58,6,4,'Nebo nemožné jest jednou již osvíceným, kteříž i zakusili daru nebeského, a účastníci učiněni byli Ducha svatého,'),
(1576309,54,58,6,5,'Okusili také dobrého Božího slova, a moci věka budoucího,'),
(1576310,54,58,6,6,'Kdyby padli, zase obnoviti se ku pokání, jakožto těm, kteříž opět sobě znovu křižují Syna Božího, a v porouhání vydávají.'),
(1576311,54,58,6,7,'Země zajisté, kteráž často na sebe přicházející déšť pije, a rodí bylinu příhodnou těm, od kterýchž bývá dělána, dochází požehnání od Boha.'),
(1576312,54,58,6,8,'Ale vydávající trní a bodláky zavržená jest, a blízká zlořečení, jejížto konec bývá spálení.'),
(1576313,54,58,6,9,'My pak, nejmilejší, nadějemeť se o vás lepších věcí, a náležejících k spasení, ač pak koli tak mluvíme.'),
(1576314,54,58,6,10,'Neboť není nespravedlivý Bůh, aby se zapomenul na práci vaši a na pracovitou lásku, kteréž jste dokazovali ke jménu jeho, slouživše svatým, a ještě sloužíce.'),
(1576315,54,58,6,11,'Žádámeť pak, aby jeden každý z vás až do konce prokazoval tu opravdovou pilnost k nabytí plné jistoty naděje,'),
(1576316,54,58,6,12,'Tak abyste nebyli líní, ale následovníci těch, kteříž skrze víru a snášelivost obdrželi dědictví zaslíbené.'),
(1576317,54,58,6,13,'Abrahamovi zajisté zaslíbení čině Bůh, když neměl skrze koho většího přisáhnouti, přisáhl skrze sebe samého,'),
(1576318,54,58,6,14,'Řka: Jistě požehnám velmi tobě, a velice rozmnožím tebe.'),
(1576319,54,58,6,15,'A tak trpělivě očekávaje, dosáhl zaslíbení.'),
(1576320,54,58,6,16,'Lidé zajisté skrze většího, nežli jsou sami, přisahají, a všeliké rozepře mezi nimi konec jest, když bývá potvrzena přísahou.'),
(1576321,54,58,6,17,'A takž Bůh, chtěje dostatečně ukázati dědicům zaslíbení svých neproměnitelnost rady své, vložil mezi to přísahu,'),
(1576322,54,58,6,18,'Abychom skrze ty dvě věci nepohnutelné, (v nichž nemožné jest, aby Bůh klamal), měli přepevné potěšení, my, kteříž jsme se utekli k obdržení předložené naděje.'),
(1576323,54,58,6,19,'Kteroutož máme jako kotvu duše, i bezpečnou i pevnou, a vcházející až do vnitřku za oponu,'),
(1576324,54,58,6,20,'Kdežto předchůdce náš pro nás všel Ježíš, jsa učiněn podle řádu Melchisedechova nejvyšším knězem na věky.'),
(1576325,54,58,7,1,'Nebo ten Melchisedech byl král Sálem, kněz Boha nejvyššího, kterýž vyšel v cestu Abrahamovi, navracujícímu se od pobití králů, a dal jemu požehnání.'),
(1576326,54,58,7,2,'Kterémužto Abraham i desátek dal ze všeho. Kterýž nejprvé vykládá se král spravedlnosti, potom pak i král Sálem, to jest král pokoje,'),
(1576327,54,58,7,3,'Bez otce, bez matky, bez rodu, ani počátku dnů, ani skonání života nemaje, ale připodobněn jsa Synu Božímu, zůstává knězem věčně.'),
(1576328,54,58,7,4,'Pohleďtež tedy, kteraký ten byl, jemuž i desátky z kořistí dal Abraham patriarcha.'),
(1576329,54,58,7,5,'A ješto ti, kteříž jsou z synů Léví kněžství přijímající, přikázaní mají desátky bráti od lidu podle Zákona, to jest od bratří svých, ačkoli pošlých z bedr Abrahamových,'),
(1576330,54,58,7,6,'Tento pak, jehož rod není počten mezi nimi, desátky vzal od Abrahama, a tomu, kterýž měl zaslíbení, požehnání dal.'),
(1576331,54,58,7,7,'A jistě beze všeho odporu menší od většího požehnání béře.'),
(1576332,54,58,7,8,'A tuto desátky berou smrtelní lidé, ale tamto ten, o němž se vysvědčuje, že jest živ.'),
(1576333,54,58,7,9,'A ať tak dím, i sám Léví, kterýž desátky béře, v Abrahamovi desátky dal.'),
(1576334,54,58,7,10,'Nebo ještě v bedrách otce byl, když vyšel proti němu Melchisedech.'),
(1576335,54,58,7,11,'A protož byla-liť dokonalost spasení skrze Levítské kněžství, (nebo za toho kněžství vydán jest lidu Zákon,) jakáž toho byla potřeba, aby jiný kněz podle řádu Melchisedechova povstal, a nebyl již více podle řádu Aronova jmenován?'),
(1576336,54,58,7,12,'A poněvadž jest kněžství přeneseno, musiloť také i Zákona přenesení býti.'),
(1576337,54,58,7,13,'Nebo ten, o kterémž se to praví, jiného jest pokolení, z kteréhožto žádný při oltáři v službě nebyl.'),
(1576338,54,58,7,14,'Zjevné jest zajisté, že z pokolení Judova pošel Pán náš, o kterémžto pokolení nic z strany kněžství nemluvil Mojžíš.'),
(1576339,54,58,7,15,'Nýbrž hojněji to zjevné jest i z toho, že povstal jiný kněz podle řádu Melchisedechova,'),
(1576340,54,58,7,16,'Kterýžto učiněn jest knězem ne podle zákona přikázaní tělesného, ale podle moci života neporušitelného.'),
(1576341,54,58,7,17,'Nebo svědčí Písmo, řka: Ty jsi kněz na věky podle řádu Melchisedechova.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576342,54,58,7,18,'Stalo se zajisté složení onoho předešlého přikázaní, protože bylo mdlé a neužitečné.'),
(1576343,54,58,7,19,'Nebo ničehož k dokonalosti nepřivedl Zákon, ale na místo jeho uvedena lepší naděje, skrze niž přibližujeme se k Bohu.'),
(1576344,54,58,7,20,'A to tím lepší, že ne bez přísahy.'),
(1576345,54,58,7,21,'Nebo onino bez přísahy kněžími učiněni bývali, tento pak s přísahou, skrze toho, kterýž řekl k němu: Přisáhl Pán, a nebudeť toho litovati: Ty jsi kněz na věky podle řádu Melchisedechova.'),
(1576346,54,58,7,22,'Takť lepší smlouvy prostředníkem učiněn jest Ježíš.'),
(1576347,54,58,7,23,'A také onino mnozí bývali kněží, protože smrt bránila jim vždycky trvati;'),
(1576348,54,58,7,24,'Ale tento poněvadž zůstává na věky, věčné má kněžství.'),
(1576349,54,58,7,25,'A protož i dokonale spasiti může všecky přistupující skrze něj k Bohu, vždycky jsa živ k orodování za ně.'),
(1576350,54,58,7,26,'Takovéhoť zajisté nám slušelo míti nejvyššího kněze, svatého, nevinného, nepoškvrněného, odděleného od hříšníků, a jenž by vyšší nad nebesa učiněn byl,'),
(1576351,54,58,7,27,'Kterýž by nepotřeboval na každý den, jako onino kněží, nejprv za své vlastní hříchy oběti obětovati, potom za za hříchy lidu. Neboť jest to učinil jednou, samého sebe obětovav.'),
(1576352,54,58,7,28,'Zákon zajisté lidi mající nedostatky ustavoval za nejvyšší kněží, ale slovo přísežné, kteréž se stalo po Zákonu, ustanovilo Syna Božího dokonalého na věky.'),
(1576353,54,58,8,1,'Ale summa toho mluvení tato jest, že takového máme nejvyššího kněze, kterýž se posadil na pravici trůnu velebnosti v nebesích.'),
(1576354,54,58,8,2,'Služebník jsa svatyně, a pravého toho stánku, kterýž Pán vzdělal, a ne člověk.'),
(1576355,54,58,8,3,'Všeliký zajisté nejvyšší kněz k obětování darů a obětí bývá ustanoven, a protož potřebí bylo, aby i tento měl, co by obětoval.'),
(1576356,54,58,8,4,'Nebo kdyby byl na zemi, aniž by knězem byl, když by zůstávali ti kněží, kteříž obětují dary podle Zákona,'),
(1576357,54,58,8,5,'Sloužíce podobenství a stínu nebeských věcí, jakož Mojžíšovi od Boha řečeno bylo, když dokonávati měl stánek: Hlediž, prý, abys udělal všecko ku podobenství, kteréžť jest ukázáno na hoře.'),
(1576358,54,58,8,6,'Nyní pak tento náš nejvyšší kněz tím důstojnějšího došel úřadu, čímž i lepší smlouvy prostředníkem jest, kterážto lepšími zaslíbeními jest utvrzena.'),
(1576359,54,58,8,7,'Nebo kdyby ona první byla bez úhony, nebylo by hledáno místa druhé.'),
(1576360,54,58,8,8,'Nebo obviňuje Židy, dí: Aj, dnové jdou, praví Pán, v nichž vejdu s domem Izraelským a s domem Judským v smlouvu novou.'),
(1576361,54,58,8,9,'Ne podle smlouvy té, kterouž jsem učinil s otci jejich v ten den, když jsem je vzal za ruku jejich, abych je vyvedl z země Egyptské. Nebo oni nezůstali v smlouvě mé, a já opustil jsem je, praví Pán.'),
(1576362,54,58,8,10,'Protož tatoť jest smlouva, v kterouž vejdu s domem Izraelským po těch dnech, praví Pán: Dám zákony své v mysl jejich, a na srdcích jejich napíši je, a budu jejich Bohem, a oni budou mým lidem.'),
(1576363,54,58,8,11,'A nebudouť učiti jeden každý bližního svého, a jeden každý bratra svého, říkajíce: Poznej Pána, protože mne všickni znáti budou, od nejmenšího z nich až do největšího z nich.'),
(1576364,54,58,8,12,'Nebo milostiv budu nepravostem jejich, a na hříchy jejich, ani na nepravosti jejich nikoli nezpomenu více.'),
(1576365,54,58,8,13,'A kdyžť praví o nové, tedy pokládá první za vetchou; což pak vetší a schází, blízké jest zahynutí.'),
(1576366,54,58,9,1,'Mělať pak i první ona smlouva ustanovení z strany služeb a svatyni světskou.'),
(1576367,54,58,9,2,'Nebo udělán byl stánek první, v kterémž byl svícen, a stůl, a posvátní chlebové, a ten sloul svatyně.'),
(1576368,54,58,9,3,'Za druhou pak oponou byl stánek, kterýž sloul svatyně svatých,'),
(1576369,54,58,9,4,'Zlatou maje kadidlnici, a truhlu smlouvy, všudy obloženou zlatem, kdežto bylo věderce zlaté, mající v sobě mannu, a hůl Aronova, kteráž byla zkvetla, a dsky zákona,'),
(1576370,54,58,9,5,'Nad truhlou pak byli dva cherubínové slávy, zastěňujíci slitovnici. O kterýchž věcech není potřebí nyní vypravovati o jedné každé obzvláštně.'),
(1576371,54,58,9,6,'To vše když tak jest zřízeno, do prvního stánku vždycky vcházejí kněží, služby vykonávajíce,'),
(1576372,54,58,9,7,'Do druhého pak jedinou v rok sám nejvyšší kněz, ne bez krve, kterouž obětuje sám za sebe, i za lidské nevědomosti.'),
(1576373,54,58,9,8,'Čímž Duch svatý ukazuje to, že ještě nebyla zjevena cesta k svatyni, dokudž první stánek trval.'),
(1576374,54,58,9,9,'Kterýž byl podobenstvím na ten přítomný čas, v němžto darové a oběti se obětují, kteréž nemohou dokonalého v svědomí učiniti toho, kdož obětuje,'),
(1576375,54,58,9,10,'Toliko v pokrmích a v nápojích, a v rozličných umýváních a ospravedlňováních tělesných, až do času napravení, záležející.'),
(1576376,54,58,9,11,'Ale Kristus přišed, nejvyšší kněz budoucího dobrého, skrze větší a dokonalejší stánek, ne rukou udělaný, to jest ne tohoto stavení,'),
(1576377,54,58,9,12,'Ani skrze krev kozlů a telat, ale skrze svou vlastní krev, všel jednou do svatyně, věčné vykoupení nalezl.'),
(1576378,54,58,9,13,'Nebo jestližeť krev býků a kozlů, a popel jalovice, pokropující poskvrněných, posvěcuje jich k očištění těla,'),
(1576379,54,58,9,14,'Čím více krev Kristova, kterýžto skrze Ducha věčného samého sebe obětoval nepoškvrněného Bohu, očistí svědomí vaše od skutků mrtvých k sloužení Bohu živému?'),
(1576380,54,58,9,15,'A pro tu příčinu nové smlouvy prostředník jest, aby, když by smrt mezi to vkročila k vyplacení přestoupení těch, kteráž byla za první smlouvy, zaslíbení věčného dědictví přijali ti, jenž jsou povoláni.'),
(1576381,54,58,9,16,'Nebo kdež se děje kšaft, potřebí jest, aby k tomu smrt přikročila toho, kdož činí kšaft.'),
(1576382,54,58,9,17,'Kšaft zajisté těch, kteříž zemřeli, pevný jest, poněvadž ještě nemá moci, dokudž živ jest ten, jenž kšaft činil.'),
(1576383,54,58,9,18,'Protož ani první onen kšaft bez krve nebyl posvěcován.'),
(1576384,54,58,9,19,'Nebo když Mojžíš všecka přikázaní podle Zákona všemu lidu předložil, vzav krev telat a kozlů, s vodou a s vlnou červenou a s yzopem, tak spolu i knihy i všeho lidu pokropil,'),
(1576385,54,58,9,20,'Řka: Tatoť jest krev Zákona, kterýž vám Bůh vydal.'),
(1576386,54,58,9,21,'Ano i stánku i všech nádob k službě náležitých rovně též krví pokropil.'),
(1576387,54,58,9,22,'A téměř všecko podle Zákona krví očišťováno bývá, a bez krve vylití nebývá odpuštění vin.'),
(1576388,54,58,9,23,'Protož potřebí bylo, aby věcí nebeských příkladové těmi věcmi očišťováni byli, nebeské pak věci lepšími obětmi, nežli jsou ty.'),
(1576389,54,58,9,24,'Neboť nevšel Kristus do svatyně rukou udělané, kteráž by byla příklad s pravou svatyní se srovnávající, ale právě v nebe všel, aby nyní přítomný byl tváři Boží za nás.'),
(1576390,54,58,9,25,'Ne aby častokrát obětoval sebe samého, jako nejvyšší kněz vcházel do svatyně každý rok se krví cizí,'),
(1576391,54,58,9,26,'(Sic jinak byl by musil častokrát trpěti od počátku světa,) ale nyní jednou při skonání věků, na shlazení hřícha skrze obětování sebe samého, zjeven jest.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576392,54,58,9,27,'A jakož uloženo lidem jednou umříti, a potom bude soud,'),
(1576393,54,58,9,28,'Tak i Kristus jednou jest obětován, k shlazení mnohých lidi hříchů; podruhé pak bez hříchu ukáže se těm, kteříž ho čekají k spasení.'),
(1576394,54,58,10,1,'Zákon zajisté, maje stín budoucího dobrého, a ne sám obraz pravý těch věcí, jednostejnými, kteréž po všecka léta obětují, obětmi nikdy nemůž přistupujících dokonalých učiniti.'),
(1576395,54,58,10,2,'Sic jinak zdaliž by již nepřestaly obětovány býti, protože by již neměli žádného svědomí z hříchu ti, jenž obětují, jsouce jednou očištěni?'),
(1576396,54,58,10,3,'Ale při těch obětech připomínání hříchů děje se každého roku.'),
(1576397,54,58,10,4,'Neboť možné není, aby krev býků a kozlů shladila hříchy.'),
(1576398,54,58,10,5,'Protož vcházeje na svět, dí: Obětí a darů nechtěl jsi, ale tělo jsi mi způsobil.'),
(1576399,54,58,10,6,'Zápalných obětí, ani obětí za hřích jsi neoblíbil.'),
(1576400,54,58,10,7,'Tehdy řekl jsem: Aj, jduť, (jakož v knihách psáno jest o mně), abych činil, ó Bože, vůli tvou.'),
(1576401,54,58,10,8,'Pověděv napřed: Že obětí a darů, a zápalů, i obětí za hřích, (kteréž se podle Zákona obětují), nechtěl jsi, aniž jsi jich oblíbil,'),
(1576402,54,58,10,9,'Tehdy řekl: Aj, jduť, (jakož v knihách psáno jest o mně) abych činil, ó Bože, vůli tvou. Ruší první, aby druhé ustanovil.'),
(1576403,54,58,10,10,'V kteréžto vůli posvěceni jsme skrze obětování těla Ježíše Krista jednou.'),
(1576404,54,58,10,11,'A všeliký zajisté kněz přístojí, na každý den službu konaje, a jednostejné často obětuje oběti, kteréž nikdy nemohou odjíti hříchů.'),
(1576405,54,58,10,12,'Ale tento, jednu obět obětovav za hříchy, vždycky sedí na pravici Boží,'),
(1576406,54,58,10,13,'Již dále očekávaje, až by položeni byli nepřátelé jeho za podnož noh jeho.'),
(1576407,54,58,10,14,'Nebo jednou obětí dokonalé učinil na věky ty , kteříž posvěceni bývají.'),
(1576408,54,58,10,15,'Svědčíť pak nám to i sám Duch svatý. Nebo prve pověděv:'),
(1576409,54,58,10,16,'Tatoť jest smlouva, kterouž učiním s nimi po těch dnech, praví Pán: Dám zákony své v srdce jejich, a na myslech jejich napíši je,'),
(1576410,54,58,10,17,'Za tím řekl: A na hříchy jejich, i na nepravosti jejich nikoli nezpomenu více.'),
(1576411,54,58,10,18,'Kdežť pak jest odpuštění jich, neníť potřebí více oběti za hřích.'),
(1576412,54,58,10,19,'Majíce tedy, bratří, plnou svobodu k vjíti do svatyně skrze krev Ježíšovu,'),
(1576413,54,58,10,20,'Tou cestou novou a živou, kterouž nám způsobil skrze oponu, to jest tělo své,'),
(1576414,54,58,10,21,'A majíce kněze velikého nad domem Božím,'),
(1576415,54,58,10,22,'Přistupmež s pravým srdcem, v plné jistotě víry, očištěná majíce srdce od svědomí zlého,'),
(1576416,54,58,10,23,'A umyté tělo vodou čistou, držmež nepochybné vyznání naděje; (nebo věrnýť jest ten, kterýž zaslíbil.)'),
(1576417,54,58,10,24,'A šetřme jedni druhých, k rozněcování se v lásce a dobrých skutcích,'),
(1576418,54,58,10,25,'Neopouštějíce společného shromáždění našeho, jako někteří obyčej mají, ale napomínajíce se, a to tím více, čímž více vidíte, že se ten den přibližuje.'),
(1576419,54,58,10,26,'Nebo jestliže bychom dobrovolně hřešili po přijetí známosti pravdy, nezůstávalo by již více oběti za hříchy,'),
(1576420,54,58,10,27,'Ale hrozné nějaké očekáváni soudu, a ohně prudká pálivost, kterýž žráti má protivníky.'),
(1576421,54,58,10,28,'Kdož by koli pohrdal Zákonem Mojžíšovým, bez lítosti pode dvěma neb třmi svědky umírá.'),
(1576422,54,58,10,29,'Což se vám zdá, jak přísnějšího trestání hoden jest ten, kdož by Syna Božího pošlapával a krev smlouvy, kterouž byl posvěcen, za nehodnou drahého vážení by měl, a duchu milosti potupu učinil?'),
(1576423,54,58,10,30,'Známeť zajisté toho, jenž řekl: Mně pomsta, já odplatím, praví Pán. A opět: Pán souditi bude lid svůj.'),
(1576424,54,58,10,31,'Hroznéť jest upadnouti v ruce Boha živého.'),
(1576425,54,58,10,32,'Rozpomeňtež se pak na předešlé dny, v nichžto osvíceni byvše, mnohý boj rozličných utrpení snášeli jste,'),
(1576426,54,58,10,33,'Buďto když jste byli i pohaněními i ssouženími jako divadlo učiněni, buďto účastníci učiněni byvše těch, kteříž tak zmítáni byli.'),
(1576427,54,58,10,34,'Nebo i vězení mého čitelni jste byli, a rozchvátání statků svých s radosti jste strpěli, vědouce, že v sobě máte lepší zboží nebeské a trvanlivé.'),
(1576428,54,58,10,35,'Protož neodmítejtež od sebe smělé doufanlivosti vaší, kterážto velikou má odplatu.'),
(1576429,54,58,10,36,'Než potřebíť jest vám trpělivosti, abyste vůli Boží činíce, dosáhli zaslíbení.'),
(1576430,54,58,10,37,'Nebo ještě velmi, velmi maličko, a aj, ten, kterýž přijíti má, přijde, a nebudeť meškati.'),
(1576431,54,58,10,38,'Spravedlivý pak z víry živ bude. Pakli by se kdo jinam obrátil, nezalibuje sobě duše má v něm.'),
(1576432,54,58,10,39,'Ale myť nejsme poběhlci k zahynutí, ale věřící k získání duše.'),
(1576433,54,58,11,1,'Víra pak jest nadějných věcí podstata, a důvod neviditelných.'),
(1576434,54,58,11,2,'Pro ni zajisté svědectví došli předkové.'),
(1576435,54,58,11,3,'Věrou rozumíme, že učiněni jsou věkové slovem Božím, takže z ničeho jest to, což vidíme, učiněno.'),
(1576436,54,58,11,4,'Věrou lepší obět Bohu obětoval Abel, nežli Kain, skrze kteroužto svědectví obdržel, že jest spravedlivý, jakž sám Bůh darům jeho svědectví vydal. A skrze tu víru, již umřev, ještě mluví.'),
(1576437,54,58,11,5,'Věrou Enoch přenesen jest, aby neviděl smrti, a není nalezen, proto že jej Bůh přenesl. Prvé zajisté, než jest přenesen, svědectví měl, že se líbil Bohu.'),
(1576438,54,58,11,6,'Bez víry pak nemožné jest líbiti se Bohu; nebo přistupující k Bohu věřiti musí, že jest Bůh, a těm, kteříž ho hledají, že odplatu dává.'),
(1576439,54,58,11,7,'Věrou napomenut jsa od Boha Noé o tom, čehož ještě nebylo viděti, boje se, připravoval koráb k zachování domu svého; skrze kterýžto koráb odsoudil svět, a spravedlnosti té, kteráž jest z víry, učiněn jest dědicem.'),
(1576440,54,58,11,8,'Věrou, povolán jsa Abraham, uposlechl Boha, aby odšel na to místo, kteréž měl vzíti za dědictví; i šel, nevěda, kam příjde.'),
(1576441,54,58,11,9,'Věrou bydlil v zemi zaslíbené jako v cizí v staních přebývaje s Izákem a s Jákobem, spoludědici téhož zaslíbení.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576442,54,58,11,10,'Nebo očekával města základy majícího, jehožto řemeslník a stavitel jest Bůh.'),
(1576443,54,58,11,11,'Věrou také i Sára moc ku početí semene přijala, a mimo čas věku porodila, když věřila, že jest věrný ten, jenž zaslíbil.'),
(1576444,54,58,11,12,'A protož i z jednoho, a to již téměř umrtveného, rozplozeno jest potomků množství veliké, jako jest množství hvězd nebeských, a jako písek nesčíslný, kterýž jest na břehu mořském.'),
(1576445,54,58,11,13,'Podle víry zemřeli ti všickni, nevzavše zaslíbení, ale zdaleka je viděvše, jim i věřili, i je vítali, a vyznávali, že jsou hosté a příchozí na zemi.'),
(1576446,54,58,11,14,'Nebo ti, kteříž tak mluví, zjevně to prokazují, že vlasti hledají.'),
(1576447,54,58,11,15,'A jistě, kdyby se byli na onu rozpomínali, z kteréž vyšli, měli dosti času zase se navrátiti.'),
(1576448,54,58,11,16,'Ale oni lepší vlasti žádají, to jest nebeské. Protož i sám Bůh nestydí se slouti jejich Bohem; nebo jim připravil město.'),
(1576449,54,58,11,17,'Věrou obětoval Abraham Izáka, byv pokoušín, a to jednorozeného obětoval ten, kterýž byl zaslíbení přijal,'),
(1576450,54,58,11,18,'K němuž bylo řečeno: V Izákovi nazváno bude tobě símě,'),
(1576451,54,58,11,19,'Tak o tom smýšleje, že jest mocen Bůh i z mrtvých vzkřísiti; odkudžto jej jako z mrtvých vzkříšeného přijal.'),
(1576452,54,58,11,20,'Věrou o budoucích věcech požehnání dal Izák Jákobovi a Ezau.'),
(1576453,54,58,11,21,'Věrou Jákob, umíraje, každému z synů Jozefových požehnání dával, a poklonil se podepřev se na vrch hůlky své.'),
(1576454,54,58,11,22,'Věrou Jozef, dokonávaje, o vyjití synů Izraelských zmínku učinil, a o kostech svých poručil.'),
(1576455,54,58,11,23,'Věrou Mojžíš, narodiv se, ukryt byl za tři měsíce od rodičů svých, protože viděli krásné pacholátko, a nebáli se rozkazu královského.'),
(1576456,54,58,11,24,'Věrou Mojžíš, dorostlý již jsa, odepřel slouti synem dcery faraonovy,'),
(1576457,54,58,11,25,'Vyvoliv sobě raději protivenství trpěti s lidem Božím, nežli časné a hříšné pohodlí míti,'),
(1576458,54,58,11,26,'Větší sobě pokládaje zboží nad Egyptské poklady pohanění Kristovo; nebo prohlédal k hojné odplatě.'),
(1576459,54,58,11,27,'Věrou opustil Egypt, neboje se hněvu královského; nebo jako by viděl Neviditelného, tak se utvrdil.'),
(1576460,54,58,11,28,'Věrou slavil hod beránka a vylití krve, aby ten, jenž hubil prvorozené, nedotekl se jich.'),
(1576461,54,58,11,29,'Věrou přešli moře červené jako po suchu; o čež pokusivše se Egyptští, ztonuli.'),
(1576462,54,58,11,30,'Věrou zdi Jericha padly, když je obcházeli za sedm dní.'),
(1576463,54,58,11,31,'Věrou Raab nevěstka nezahynula s neposlušnými, pokojně přijavši špehéře.'),
(1576464,54,58,11,32,'A coť mám více praviti? Nepostačíť mi zajisté čas k vypravování o Gedeonovi, a Barákovi, a Samsonovi a Jefte, a Davidovi, a Samuelovi, a prorocích.'),
(1576465,54,58,11,33,'Kteříž skrze víru vybojovávali království, činili spravedlnost, docházeli zaslíbení, zacpávali ústa lvům,'),
(1576466,54,58,11,34,'Uhašovali moc ohně, utekli ostrosti meče, zmocněni bývali v mdlobách, silní učiněni v boji, vojska zaháněli cizozemců.'),
(1576467,54,58,11,35,'Ženy přijímaly mrtvé své vzkříšené. Jiní pak roztahováni jsou, neoblíbivše sobě vysvobození, aby lepšího dosáhli vzkříšení.'),
(1576468,54,58,11,36,'Jiní pak posměchy a mrskáním trápeni, ano i vězeními a žaláři.'),
(1576469,54,58,11,37,'Kamenováni jsou, sekáni, pokoušíni, mečem zmordováni; chodili v kožích ovčích a kozelčích, opuštěni, souženi, a zle s nimi nakládáno,'),
(1576470,54,58,11,38,'Jichžto nebyl svět hoden, po pustinách bloudíce, i po horách, a jeskyních, i v doupatech země.'),
(1576471,54,58,11,39,'A ti všickni svědectví dosáhše skrze víru, neobdrželi zaslíbení,'),
(1576472,54,58,11,40,'Protože Bůh něco lepšího nám obmýšlel, aby oni bez nás nepřišli k dokonalosti.'),
(1576473,54,58,12,1,'Protož i my, takový oblak svědků vůkol majíce, odvrhouce všeliké břímě, i snadně obkličující nás hřích, skrze trpělivost konejme běh uloženého nám boje,'),
(1576474,54,58,12,2,'Patříce na vůdce a dokonavatele víry Ježíše, kterýžto místo předložené sobě radosti strpěl kříž, opováživ se hanby, i posadil se na pravici trůnu Božího.'),
(1576475,54,58,12,3,'A považte, kteraký jest ten, jenž snášel od hříšníků taková proti sobě odmlouvání, abyste neustávali, v myslech vašich hynouce.'),
(1576476,54,58,12,4,'Ještě jste se až do krve nezprotivili, proti hříchu bojujíce.'),
(1576477,54,58,12,5,'A což jste zapomenuli na napomenutí, kteréž k vám jako k synům mluví:Synu můj, nepohrdej kázní Páně, aniž sobě stýskej, když od něho trestán býváš?'),
(1576478,54,58,12,6,'Nebo kohož miluje Pán, tohoť tresce, a švihá každého, kteréhož za syna přijímá.'),
(1576479,54,58,12,7,'Jestliže kázeň snášíte, Bůh se vám podává jakožto synům. Nebo který jest syn, jehož by netrestal otec?'),
(1576480,54,58,12,8,'Pakli jste bez kázně, kteréžto všickni synové účastni jsou, tedy jste cizoložňata, a ne synové.'),
(1576481,54,58,12,9,'Ano tělesné otce naše měli jsme, kteříž nás trestali, a měli jsme je u vážnosti; i zdaliž nemáme mnohem více poddáni býti Otci duchů, abychom živi byli?'),
(1576482,54,58,12,10,'A onino zajisté po nemnohé dny, jakž se jim vidělo, trestali, ale tento v věcech přeužitečných, totiž k tomu, abychom došli účastnosti svatosti jeho.'),
(1576483,54,58,12,11,'Každé pak trestání, když přítomné jest, nezdá se býti potěšené, ale smutné, než potomť rozkošné ovoce spravedlnosti přináší těm, kteříž by v něm pocvičeni byli.'),
(1576484,54,58,12,12,'Protož opuštěných rukou a zemdlených kolen posilňte,'),
(1576485,54,58,12,13,'A přímé kroky čiňte nohama svýma, aby, což zkulhavělo, do konce se nevyvinulo, ale raději uzdraveno bylo.'),
(1576486,54,58,12,14,'Pokoje následujte se všechněmi a svatosti, bez níž žádný neuzří Pána,'),
(1576487,54,58,12,15,'Prohlédajíce k tomu bedlivě, aby někdo neodpadl od milosti Boží, a aby nějaký kořen hořkosti nepodrostl, a neučinil překážky, skrze nějž by poškvrněni byli mnozí;'),
(1576488,54,58,12,16,'Aby někdo nebyl smilník, aneb ohyzdný, jako Ezau, kterýžto za jednu krmi prodal prvorozenství své.'),
(1576489,54,58,12,17,'Víte zajisté, že potom, chtěje dědičně dosáhnouti požehnání, pohrdnut jest. Nebo nenalezl místa ku pokání, ač ho koli s pláčem hledal.'),
(1576490,54,58,12,18,'Nebo nepřistoupili jste k hmotné hoře a k hořícímu ohni, a k vichru, a k mrákotě, a k bouři,'),
(1576491,54,58,12,19,'A zvuku trouby a k hlasu slov, kterýžto hlas kdož slyšeli, prosili, aby k nim nebylo více mluveno.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576492,54,58,12,20,'(Nebo nemohli snésti toho, což bylo praveno: A kdyby se i hovado dotklo hory, budeť ukamenováno, aneb šípem postřeleno.'),
(1576493,54,58,12,21,'A tak hrozné bylo to, což viděli, že i Mojžíš řekl: Lekl jsem se, až se třesu.)'),
(1576494,54,58,12,22,'Ale přistoupili jste k hoře Sionu, a k městu Boha živého, Jeruzalému nebeskému, a k nesčíslnému zástupu andělů,'),
(1576495,54,58,12,23,'K veřejnému shromáždění a k církvi prvorozených, kteříž zapsáni jsou v nebesích, a k Bohu soudci všech, a k duchům spravedlivých dokonalých,'),
(1576496,54,58,12,24,'A k prostředníku Nového Zákona Ježíšovi, a ku pokropení krví, lépe mluvící nežli Abelova.'),
(1576497,54,58,12,25,'Viztež, abyste neodpírali mluvícím. Nebo poněvadž onino neušli pomsty, kteříž odpírali tomu, jenž na zemi na místě Božím mluvil, čím více my, jestliže tím, kterýž s nebe mluví k nám, pohrdneme?'),
(1576498,54,58,12,26,'Jehožto hlas tehdáž byl zemí pohnul, nyní pak propověděl, řka: Ještěť já jednou pohnu netoliko zemí, ale i nebem.'),
(1576499,54,58,12,27,'A to, že dí: Ještě jednou, světle ukazuje pohnutelných věcí přenesení, jakožto rukama učiněných, aby zůstávaly ty, jenž jsou nepohnutelné.'),
(1576500,54,58,12,28,'Protož království přijímajíce nepohnutelné, mějmež milost, skrze kteroužto služme libě Bohu, s vážností a uctivostí.'),
(1576501,54,58,12,29,'Neboť Bůh náš jest oheň spalující.'),
(1576502,54,58,13,1,'Láska bratrská zůstávejž mezi vámi.'),
(1576503,54,58,13,2,'Na přívětivost k hostem nezapomínejte; skrze ni zajisté někteří, nevěděvše, anděly za hostě přijímali.'),
(1576504,54,58,13,3,'Pomněte na vězně, jako byste spolu vězňové byli, na soužené, jakožto ti, jenž také v těle jste.'),
(1576505,54,58,13,4,'Poctivéť jest u všech lidí manželství a lože nepoškvrněné, smilníky pak a cizoložníky souditi bude Bůh.'),
(1576506,54,58,13,5,'Obcování vaše budiž bez lakomství, dosti majíce na tom, což máte. Onť zajisté řekl: Nikoli nenechám tebe tak, aniž tě opustím;'),
(1576507,54,58,13,6,'Tak abychom doufanlivě říkali: Pán spomocník můj, aniž se budu báti, by mi co učiniti mohl člověk.'),
(1576508,54,58,13,7,'Zpomínejte na vůdce vaše, kteříž vám mluvili slovo Boží, jejichžto jaký byl cíl obcování, spatřujíce, následujtež jejich víry.'),
(1576509,54,58,13,8,'Ježíš Kristus jest včera i dnes, tentýž i na věky.'),
(1576510,54,58,13,9,'Učením rozličným a cizím nedejte se točiti. Výbornéť jest zajisté, aby milostí upevněno bylo srdce, a ne pokrmy, kteříž neprospěli těm, jenž se jimi vázali.'),
(1576511,54,58,13,10,'Mámeť oltář, z něhož nemají moci jísti ti, jenž stánku slouží.'),
(1576512,54,58,13,11,'Nebo kterýchž hovad krev vnášína bývá do svatyně skrze nejvyššího kněze za hřích, těch pálena bývají těla vně za stany.'),
(1576513,54,58,13,12,'Protož i Ježíš, aby posvětil lidu skrze svou vlastní krev, vně za branou trpěl.'),
(1576514,54,58,13,13,'Vyjděmež tedy k němu ven z stanů, pohanění jeho nesouce.'),
(1576515,54,58,13,14,'Neboť nemáme zde města zůstávajícího, ale onoho budoucího hledáme.'),
(1576516,54,58,13,15,'Protož skrze něho obětujme Bohu obět chvály vždycky, to jest ovoce rtů, oslavujících jméno jeho.'),
(1576517,54,58,13,16,'Na účinnost pak a na sdílnost nezapomínejte; nebo v takových obětech zvláštní svou libost má Bůh.'),
(1576518,54,58,13,17,'Povolni buďte správcům vašim a poslušni buďte jich; oniť zajisté bdějí nad dušemi vašimi, jako ti, kteříž počet mají vydati; ať by to s radostí činili, a ne s stýskáním. Neboť by vám to nebylo užitečné.'),
(1576519,54,58,13,18,'Modltež se za nás; doufámeť zajisté, že dobré svědomí máme, jakožto ti, kteříž se chceme ve všem chvalitebně chovati.'),
(1576520,54,58,13,19,'Pročež prosímť vás, abyste to hojněji činili, abych tím dříve navrácen byl vám.'),
(1576521,54,58,13,20,'Bůh pak pokoje, kterýž toho velikého pro krev smlouvy věčné Pastýře ovcí vzkřísil z mrtvých, Pána našeho Ježíše,'),
(1576522,54,58,13,21,'Učiniž vás způsobné ve všelikém skutku dobrém, k činění vůle jeho, působě v vás to, což jest libé před obličejem jeho, skrze Jezukrista, jemuž sláva na věky věků. Amen.'),
(1576523,54,58,13,22,'Prosímť pak vás, bratří, snestež trpělivě slovo napomenutí tohoto; neboť jsem krátce psal vám.'),
(1576524,54,58,13,23,'Věztež o bratru Timoteovi, že jest propuštěn, s kterýmžto, (přišel-li by brzo), navštívím vás.'),
(1576525,54,58,13,24,'Pozdravtež všech správců svých, i všech svatých. Pozdravují vás bratři z Vlach.'),
(1576526,54,58,13,25,'Milost Boží se všemi vámi. Amen. K Židům psán jest z Vlach po Timoteovi.'),
(1576527,54,59,1,1,'Jakub, Boží a Pána Jezukrista služebník, dvanácteru pokolení rozptýlenému pozdravení vzkazuje.'),
(1576528,54,59,1,2,'Za největší radost mějte, bratří moji, kdyžkoli pokušeními obkličováni býváte rozličnými,'),
(1576529,54,59,1,3,'Vědouce, že zkušení víry vaší působí trpělivost.'),
(1576530,54,59,1,4,'Trpělivost pak ať má dokonalý skutek, abyste byli dokonalí a celí, v ničemž nemajíce nedostatku.'),
(1576531,54,59,1,5,'Jestliže pak komu z vás nedostává se moudrosti, žádejž jí od Boha, kterýž všechněm dává ochotně a neomlouvá; i budeť jemu dána.'),
(1576532,54,59,1,6,'Žádejž pak důvěrně, nic nepochybuje. Nebo kdož pochybuje, podoben jest vlnám mořským, kteréž vítr sem i tam žene, a jimi zmítá.'),
(1576533,54,59,1,7,'Nedomnívej se zajisté člověk ten, by co vzíti měl ode Pána,'),
(1576534,54,59,1,8,'Jakožto muž dvojí mysli a neustavičný ve všech cestách svých.'),
(1576535,54,59,1,9,'Chlubiž se pak bratr ponížený v povýšení svém,'),
(1576536,54,59,1,10,'A bohatý v ponížení se; nebo jako květ byliny pomine.'),
(1576537,54,59,1,11,'Nebo jakož slunce vzešlé s horkostí usušilo bylinu, a květ její spadl, i ušlechtilost postavy jeho zhynula, takť i bohatý v svých cestách usvadne.'),
(1576538,54,59,1,12,'Ale blahoslavený muž, kterýž snáší pokušení, nebo když bude zkušen, vezme korunu života, kterouž zaslíbil Pán těm, jenž ho milují.'),
(1576539,54,59,1,13,'Žádný, když bývá pokoušín, neříkej, že by od Boha pokoušín byl; neboť Bůh nemůže pokoušín býti ve zlém, aniž on koho pokouší.'),
(1576540,54,59,1,14,'Ale jeden každý pokoušín bývá, od svých vlastních žádostí jsa zachvacován a oklamáván.'),
(1576541,54,59,1,15,'Potom žádost když počne, porodí hřích, hřích pak vykonaný zplozuje smrt.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576542,54,59,1,16,'Nebluďtež, bratří moji milí.'),
(1576543,54,59,1,17,'Všeliké dání dobré a každý dar dokonalý shůry jest sstupující od Otce světel, u něhožto není proměnění, ani jakého pro obrácení se někam jinam zastínění.'),
(1576544,54,59,1,18,'On proto, že chtěl, zplodil nás slovem pravdy, k tomu, abychom byli prvotiny nějaké stvoření jeho.'),
(1576545,54,59,1,19,'A tak, bratří moji milí, budiž každý člověk rychlý k slyšení, ale zpozdilý k mluvení, zpozdilý k hněvu.'),
(1576546,54,59,1,20,'Nebo hněv muže spravedlnosti Boží nepůsobí.'),
(1576547,54,59,1,21,'Protož odvrhouce všelikou nečistotu, a ohyzdnost zlosti, s tichostí přijímejte vsáté slovo, kteréž může spasiti duše vaše.'),
(1576548,54,59,1,22,'Buďtež pak činitelé slova, a ne posluchači toliko, oklamávajíce sami sebe.'),
(1576549,54,59,1,23,'Nebo byl-li by kdo posluchač slova, a ne činitel, ten podoben jest muži spatřujícímu obličej přirozený svůj v zrcadle.'),
(1576550,54,59,1,24,'Vzhlédl se zajisté, i odšel, a hned zapomenul, jaký by byl.'),
(1576551,54,59,1,25,'Ale kdož by se vzhlédl v dokonalý zákon svobody a zůstával by v něm, ten nejsa posluchač zapominatelný, ale činitel skutku, ten, pravím, blahoslavený bude v skutku svém.'),
(1576552,54,59,1,26,'Zdá-li se pak komu z vás, že jest nábožný, avšak v uzdu nepojímá jazyka svého, ale svodí srdce své, takového marné jest náboženství.'),
(1576553,54,59,1,27,'Náboženství čisté a neposkvrněné před Bohem a Otcem totoť jest: Navštěvovati sirotky a vdovy v souženích jejich a ostříhati sebe neposkvrněného od světa.'),
(1576554,54,59,2,1,'Bratří moji, nepřipojujtež přijímání osob k víře slavného Pána našeho Jezukrista.'),
(1576555,54,59,2,2,'Nebo kdyby přišel do shromáždění vašeho muž, maje prsten zlatý, v drahém rouše, a všel by také i chudý v chaterném oděvu,'),
(1576556,54,59,2,3,'A popatřili byste k tomu, jenž drahé roucho má, a řekli byste jemu: Ty sedni tuto pěkně; chudému pak řekli byste: Ty stůj tamto, aneb sedni tuto, pod podnoží noh mých;'),
(1576557,54,59,2,4,'Zdaliž jste již neučinili rozdílu mezi sebou a učiněni jste rozeznavatelé v myšleních zlých?'),
(1576558,54,59,2,5,'Slyšte, bratří moji milí, zdaliž Bůh nevyvolil chudých na tomto světě, aby bohatí byli u víře a dědicové království, kteréž zaslíbil těm, jenž jej milují?'),
(1576559,54,59,2,6,'Ale vy jste neuctili chudého. Zdaliž ne ti, jenž bohatí jsou, mocí utiskují vás, a oniť vás i k soudům přivozují?'),
(1576560,54,59,2,7,'Zdali oni nerouhají se tomu slavnému jménu, kteréž vzýváno jest nad vámi?'),
(1576561,54,59,2,8,'Jestliže pak plníte Zákon královský podle Písem: Milovati budeš bližního svého, jako sebe samého, dobře činíte.'),
(1576562,54,59,2,9,'Pakli osoby přijímáte, hřešíte, a Zákon vás tresce jako přestupníky.'),
(1576563,54,59,2,10,'Nebo kdo by koli celého Zákona ostříhal, přestoupil by pak v jediném, učiněn jest všemi vinen.'),
(1576564,54,59,2,11,'Ten zajisté, kterýž řekl: Nesesmilníš, takéť jest řekl: Nezabiješ. Pakli bys nesesmilnil, ale zabil bys, učiněn jsi přestupníkem Zákona.'),
(1576565,54,59,2,12,'Tak mluvte a tak čiňte, jakožto ti, kteříž podle zákona svobody souzeni býti máte.'),
(1576566,54,59,2,13,'Nebo odsouzení bez milosrdenství stane se tomu, kdož nečiní milosrdenství, ale chlubíť se milosrdenstvím proti odsudku.'),
(1576567,54,59,2,14,'Co prospěje, bratří moji, praví-li se kdo víru míti, a nemá-li skutků? Zdaliž jej ta víra může spasiti?'),
(1576568,54,59,2,15,'A kdyby bratr neb sestra neodění byli, a opuštění z strany každodenního pokrmu,'),
(1576569,54,59,2,16,'Řekl by pak jim někdo z vás: Jděte v pokoji a zhřejte se, a najezte se, avšak nedali byste jim potřeby tělesné, což to platno bude?'),
(1576570,54,59,2,17,'Takž i víra, nemá-li skutků, mrtváť jest sama v sobě.'),
(1576571,54,59,2,18,'Ale dí někdo: Ty víru máš, a já mám skutky. Ukažiž ty mi víru svou z skutků svých, a jáť tobě ukáži víru svou z skutků svých.'),
(1576572,54,59,2,19,'Ty věříš, že jest jeden Bůh. Dobře činíš. I ďáblovéť tomu věří, avšak třesou se.'),
(1576573,54,59,2,20,'Ale chceš-liž věděti, ó člověče marný, že víra bez skutků jest mrtvá?'),
(1576574,54,59,2,21,'Abraham otec náš zdali ne z skutků ospravedlněn jest, obětovav syna svého Izáka na oltář?'),
(1576575,54,59,2,22,'Vidíš-li, že víra napomáhala skutkům jeho a z skutků víra dokonalá byla?'),
(1576576,54,59,2,23,'A tak naplněno jest Písmo, řkoucí: I uvěřil Abraham Bohu, a počteno jest jemu to za spravedlnost, a přítelem Božím nazván jest.'),
(1576577,54,59,2,24,'Vidíte-liž tedy, že z skutků ospravedlněn bývá člověk a ne z víry toliko?'),
(1576578,54,59,2,25,'Též podobně i Raab nevěstka zdali ne z skutků ospravedlněna jest, přijavši posly a jinou cestou pryč je vypustivši?'),
(1576579,54,59,2,26,'Nebo jakož tělo bez duše jest mrtvé, takť i víra bez skutků jest mrtvá.'),
(1576580,54,59,3,1,'Nebuďtež mnozí mistři, bratří moji, vědouce, že bychom těžší odsouzení vzali.'),
(1576581,54,59,3,2,'V mnohém zajisté klesáme všickni. Kdožť neklesá v slovu, tenť jest dokonalý muž, mohoucí jako uzdou spravovati všecko tělo.'),
(1576582,54,59,3,3,'An my koně v uzdu pojímáme, aby nám povolni byli, a vším tělem jejich vládneme.'),
(1576583,54,59,3,4,'An i lodí tak veliké jsouce a prudkými větry hnány bývajíce, však i nejmenším veslem bývají sem i tam obracíny, kamžkoli líbí se tomu, kdož je spravuje.'),
(1576584,54,59,3,5,'Tak i jazyk malý úd jest, avšak veliké věci provodí. Aj, maličký oheň, kterak veliký les zapálí!'),
(1576585,54,59,3,6,'A jestiť jazyk jako oheň a svět nepravosti. Takť jest, pravím, postaven jazyk mezi údy našimi, nanečišťující celé tělo, a rozpalující kolo narození našeho, jsa rozněcován od ohně pekelného.'),
(1576586,54,59,3,7,'Všeliké zajisté přirození i zvěři, i ptactva, i hadů, i mořských potvor bývá zkroceno, a jest okroceno od lidí;'),
(1576587,54,59,3,8,'Ale jazyka žádný z lidí zkrotiti nemůže; tak jest nezkrotitelné zlé, pln jsa jedu smrtelného.'),
(1576588,54,59,3,9,'Jím dobrořečíme Bohu Otci a jím zlořečíme lidem, ku podobenství Božímu stvořeným.'),
(1576589,54,59,3,10,'Z jedněch a týchž úst pochází dobrořečení i zlořečení. Ne takť býti má, bratří moji.'),
(1576590,54,59,3,11,'Zdaliž studnice jedním pramenem vydává sladkou i hořkou vodu?'),
(1576591,54,59,3,12,'Zdaliž může, bratří moji, fíkový strom nésti olivky, aneb vinný kmen fíky? Takť žádná studnice slané a sladké vody spolu vydávati nemůže.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576592,54,59,3,13,'Kdo jest moudrý a umělý mezi vámi? Ukažiž dobrým obcováním skutky své v krotké moudrosti.'),
(1576593,54,59,3,14,'Pakliť máte mezi sebou hořkou závist a zdráždění v srdci svém, nechlubte se a neklamejte proti pravdě.'),
(1576594,54,59,3,15,'Neníť zajisté ta moudrost shůry sstupující, ale jest zemská, hovadná a ďábelská.'),
(1576595,54,59,3,16,'Nebo kdežť jest závist a rozdráždění, tu jest roztržka a všeliké dílo zlé.'),
(1576596,54,59,3,17,'Ale moudrost, kteráž jest shůry, nejprve zajisté jest čistotná, potom pokojná, mírná, povolná, plná milosrdenství a ovoce dobrého, bez rozsuzování a bez pokrytství.'),
(1576597,54,59,3,18,'Ovoce pak spravedlnosti v pokoji rozsívá se těm, kteříž pokoj působí.'),
(1576598,54,59,4,1,'Odkud pocházejí bojové a vády mezi vámi? Zdali ne odtud, totiž z libostí vašich, kteréž rytěřují v údech vašich?'),
(1576599,54,59,4,2,'Žádáte, a nemáte; závidíte sobě, a dychtíte po tom, což sobě zalibujete, a nemůžete dosáhnouti; bojujete a válčíte, avšak toho, oč usilujete, nemáte, protože neprosíte.'),
(1576600,54,59,4,3,'Prosíte, a nebéřete, protože zle prosíte, abyste na své libosti vynakládali.'),
(1576601,54,59,4,4,'Cizoložníci a cizoložnice, což nevíte, že přízeň světa jest nepřítelkyně Boží? A protož kdo by koli chtěl býti přítelem tohoto světa, nepřítelem Božím učiněn bývá.'),
(1576602,54,59,4,5,'Což mníte, že nadarmo dí Písmo: Zdali k závisti nakloňuje duch ten, kterýž přebývá v nás?'),
(1576603,54,59,4,6,'Nýbrž hojnější dává milost. Nebo dí: Bůh se pyšným protiví, ale pokorným dává milost.'),
(1576604,54,59,4,7,'Poddejtež se tedy Bohu, a zepřetež se ďáblu, i utečeť od vás.'),
(1576605,54,59,4,8,'Přibližte se k Bohu, a přiblížíť se k vám. Umejte ruce, hříšníci, a očisťte srdce vy, jenž jste dvojité mysli.'),
(1576606,54,59,4,9,'Souženi buďte, a kvělte, a plačte; smích váš obratiž se v kvílení, a radost v zámutek.'),
(1576607,54,59,4,10,'Ponižte se před obličejem Páně, a povýšíť vás.'),
(1576608,54,59,4,11,'Neutrhejtež jedni druhým, bratří. Kdož utrhá bratru a soudí bratra svého, utrhá Zákonu a soudí Zákon. Soudíš-li pak Zákon, nejsi plnitel Zákona, ale soudce.'),
(1576609,54,59,4,12,'Jedenť jest vydavatel Zákona, kterýž může spasiti i zatratiti. Ty kdo jsi, jenž soudíš jiného?'),
(1576610,54,59,4,13,'Ale nuže vy, kteříž říkáte: Dnes nebo zítra vypravíme se do onoho města, a pobudeme tam přes celý rok, a budeme kupčiti, a něco zíštěme;'),
(1576611,54,59,4,14,'(Ješto nevíte, co zítra bude. Nebo jakýť jest život váš? Pára zajisté jest, kteráž se na maličko ukáže, a potom zmizí.)'),
(1576612,54,59,4,15,'Místo toho, co byste měli říci: Bude-li Bůh chtíti, a budeme-li živi, i učiníme toto nebo onono.'),
(1576613,54,59,4,16,'Vy pak chlubíte se v pýše své. Všeliká taková chlouba zlá jest.'),
(1576614,54,59,4,17,'A protož kdo umí dobře činiti, a nečiní, hřích má.'),
(1576615,54,59,5,1,'Nuže nyní, boháči, plačte, kvílíce nad bídami svými, kteréž přijdou.'),
(1576616,54,59,5,2,'Zboží vaše shnilo a roucho vaše zmolovatělo.'),
(1576617,54,59,5,3,'Zlato vaše a stříbro zerzavělo, a rez jejich bude na svědectví proti vám, a zžířeť těla vaše jako oheň. Shromáždili jste poklad ku posledním dnům.'),
(1576618,54,59,5,4,'Aj, mzda dělníků, kteříž žali krajiny vaše, při vás zadržaná, křičí, a hlas volání ženců v uši Pána zástupů vešel.'),
(1576619,54,59,5,5,'Rozkoš jste provodili na zemi a zbujněli jste; vykrmili jste srdce vaše jakožto ke dni zabití.'),
(1576620,54,59,5,6,'Odsoudili jste a zamordovali spravedlivého, a neodpíral vám.'),
(1576621,54,59,5,7,'A protož trpěliví buďte, bratří, až do příchodu Páně. Aj, oráč očekává drahého užitku zemského, trpělivě naň očekávaje, až by přijal podzimní i jarní déšť.'),
(1576622,54,59,5,8,'Buďtež i vy trpěliví a potvrzujte srdcí vašich; neboť se přibližuje příští Páně.'),
(1576623,54,59,5,9,'Nevzdychejtež k Bohu jedni proti druhým, bratří, abyste nebyli odsouzeni. Aj, Soudce již přede dveřmi stojí.'),
(1576624,54,59,5,10,'Ku příkladu snášení protivenství a dlouhočekání, bratří moji, vezměte proroky, kteříž mluvívali ve jménu Páně.'),
(1576625,54,59,5,11,'Aj, blahoslavíme ty trpělivé. O trpělivosti Jobově slýchali jste, a dokonání Páně viděli jste; nebo velmi jest milosrdný Pán a lítostivý.'),
(1576626,54,59,5,12,'Přede všemi pak věcmi, bratří moji, nepřisahejte, ani skrze nebe, ani skrze zemi, ani kteroukoli jinou přísahou, ale buď řeč vaše: Jistě, jistě, nikoli, nikoli, abyste neupadli v odsouzení.'),
(1576627,54,59,5,13,'Jest-li kdo z vás zkormoucený? Modliž se. Pakli jest kdo mysli dobré? Prozpěvuj Pánu.'),
(1576628,54,59,5,14,'Stůně-li kdo z vás? Zavolej starších sboru, a oni modltež se za něj, mažíce jej olejem ve jménu Páně.'),
(1576629,54,59,5,15,'A modlitba víry uzdraví neduživého, a pozdvihneť ho Pán; a jestliže jest co prohřešil, budeť jemu odpuštěno.'),
(1576630,54,59,5,16,'Vyznávejtež se pak jedni druhým z hříchů svých, a modlte se jedni za druhé, abyste uzdraveni byli. Mnohoť zajisté může modlitba spravedlivého opravdová.'),
(1576631,54,59,5,17,'Eliáš člověk byl týmž bídám jako i my poddaný, a modlitbou modlil se, aby nepršelo, i nepršel déšť na zemi za tři léta a za šest měsíců.'),
(1576632,54,59,5,18,'A zase modlil se, i vydalo nebe déšť, a země zplodila ovoce své.'),
(1576633,54,59,5,19,'Bratří, jestliže by kdo z vás pobloudil od pravdy, a někdo by jej napravil,'),
(1576634,54,59,5,20,'Věziž, že ten, kdož by odvrátil hříšníka od bludné cesty jeho, vysvobodí duši jeho od smrti a přikryje množství hříchů.'),
(1576635,54,60,1,1,'Petr, apoštol Ježíše Krista, příchozím rozptýleným v Pontu, Galacii, Kappadocii, v Azii a v Bitynii,'),
(1576636,54,60,1,2,'Vyvoleným podle předzvědění Boha Otce, v posvěcení Ducha svatého, ku poslušenství a skropení krví Ježíše Krista: Milost vám a pokoj rozmnožen buď.'),
(1576637,54,60,1,3,'Požehnaný Bůh a Otec Pána našeho Ježíše Krista, kterýžto podle mnohého milosrdenství svého znovu zplodil nás v naději živou skrze vzkříšení Ježíše Krista z mrtvých,'),
(1576638,54,60,1,4,'K dědictví neporušitelnému a neposkvrněnému a neuvadlému, kteréž se chová v nebesích, nám,'),
(1576639,54,60,1,5,'Kteřížto mocí Boží ostříháni býváme skrze víru k spasení, kteréž hotovo jest, aby zjeveno bylo v času posledním.'),
(1576640,54,60,1,6,'V čemžto veselíte se, maličko nyní, (jestliže kdy potřebí jest,) zkormouceni jsouce v rozličných pokušeních,'),
(1576641,54,60,1,7,'Aby zkušení víry vaší, kteráž jest mnohem dražší nežli zlato, jenž hyne, avšak se v ohni zkušuje, nalezeno bylo vám k chvále, a ke cti i k slávě při zjevení Ježíše Krista.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576642,54,60,1,8,'Kteréhožto neviděvše, milujete; kteréhožto nyní nevidouce, avšak v něho věříce, veselíte se radostí nevýmluvnou a oslavenou,'),
(1576643,54,60,1,9,'Docházejíce konce víry vaší, spasení duší vašich,'),
(1576644,54,60,1,10,'O kterémžto spasení bedlivě přemyšlovali a je vystihati usilovali proroci, kteříž o té milosti, jenž se vám státi měla, prorokovali,'),
(1576645,54,60,1,11,'Snažujíce se tomu vyrozuměti, na který aneb jaký čas mínil by ten, kterýž v nich byl, Duch Kristův, předpovídající o utrpeních Kristových a o veliké slávě za tím jdoucí.'),
(1576646,54,60,1,12,'Kterýmž zjeveno jest, že ne sobě, ale nám tím přisluhovali, což jest vám nyní zvěstováno skrze ty, kteříž vám kázali evangelium, v Duchu svatém seslaném s nebe, na kteréžto věci žádostivi jsou andělé patřiti.'),
(1576647,54,60,1,13,'Protož přepášíce bedra mysli vaší, a střízlivi jsouce, dokonale doufejte v té milosti, kteráž vám dána bude při zjevení Ježíše Krista,'),
(1576648,54,60,1,14,'Jakožto synové poslušní, nepřirovnávajíce se prvním neznámosti vaší žádostem.'),
(1576649,54,60,1,15,'Ale jakž ten, kterýž vás povolal, Svatý jest, i vy svatí ve všem obcování vašem, buďte;'),
(1576650,54,60,1,16,'Jakož napsáno jest: Svatí buďte, nebo já Svatý jsem.'),
(1576651,54,60,1,17,'A poněvadž Otcem nazýváte toho, kterýž bez přijímání osob soudí vedle skutků jednoho každého, viztež, abyste v bázni Páně čas vašeho zde putování konali,'),
(1576652,54,60,1,18,'Vědouce, že ne těmi porušitelnými věcmi, stříbrem nebo zlatem, vykoupeni jste z marného vašeho obcování podle ustanovení otců,'),
(1576653,54,60,1,19,'Ale drahou krví jakožto Beránka nevinného a neposkvrněného, Krista,'),
(1576654,54,60,1,20,'Předzvěděného zajisté před ustanovením světa, zjeveného pak v časích posledních pro vás,'),
(1576655,54,60,1,21,'Kteříž skrze něho věříte v Boha, jenž jej vzkřísil z mrtvých, a dal jemu slávu, tak aby víra vaše a naděje byla v Bohu.'),
(1576656,54,60,1,22,'Poněvadž duše své očistili jste poslušenstvím pravdy skrze Ducha svatého, k milování neošemetnému bratrstva, z čistého tedy srdce jedni druhé milujte snažně,'),
(1576657,54,60,1,23,'Znovu zrozeni jsouce ne z porušitelného semene, ale z neporušitelného, totiž skrze živé slovo Boží a zůstávající na věky.'),
(1576658,54,60,1,24,'Nebo všeliké tělo jest jako tráva, a všeliká sláva člověka jako květ trávy. Usvadla tráva, a květ její spadl,'),
(1576659,54,60,1,25,'Ale slovo Páně zůstává na věky. Totoť pak jest to slovo, kteréž zvěstováno jest vám.'),
(1576660,54,60,2,1,'Protož složíce zlost, a všelikou lest, a pokrytství, a závist, i všecka utrhání,'),
(1576661,54,60,2,2,'Jakožto nyní zrozená nemluvňátka, mléka beze lsti, to jest Božího slova žádostivi buďte, abyste jím rostli,'),
(1576662,54,60,2,3,'Jestliže však okusili jste, kterak dobrotivý jest Pán.'),
(1576663,54,60,2,4,'K kterémužto přistupujíce, jakožto k kameni živému, od lidí zajisté zavrženému, ale od Boha vyvolenému a drahému,'),
(1576664,54,60,2,5,'I vy, jakožto kamení živé, vzdělávejte se v dům duchovní, kněžstvo svaté, k obětování duchovních obětí, vzácných Bohu skrze Jezukrista.'),
(1576665,54,60,2,6,'A protož praví Písmo: Aj, zakládámť na Sionu kámen úhelný, vybraný a drahý, a v kterýž kdokoli věří, nikoli nebude zahanben.'),
(1576666,54,60,2,7,'Vám tedy věřícím jest drahý, ale nepovolným kámen, kterýž zavrhli ti, jenž stavěli, tenť jest učiněn v hlavu úhelní, a kámen úrazu, a skála pohoršení,'),
(1576667,54,60,2,8,'Totiž těm, jenž se urážejí na slovu, nepovolní jsouce, k čemuž i odloženi jsou.'),
(1576668,54,60,2,9,'Ale vy jste rod vyvolený, královské kněžstvo, národ svatý, lid dobytý, abyste zvěstovali ctnosti toho, kterýž vás povolal ze tmy v předivné světlo své.'),
(1576669,54,60,2,10,'Kteříž jste někdy ani lidem nebyli, nyní pak jste lid Boží; kteříž jste někdy byli nedošli milosrdenství, již nyní jste došli milosrdenství.'),
(1576670,54,60,2,11,'Nejmilejší, prosímť vás, abyste jakožto příchozí a pohostinní zdržovali se od tělesných žádostí, kteréž rytěřují proti duši,'),
(1576671,54,60,2,12,'Obcování vaše mezi pohany majíce dobré, aby místo toho, kdež utrhají vám jako zločincům, dobré skutky vaše spatřujíce, velebili Boha v den navštívení.'),
(1576672,54,60,2,13,'Poddáni tedy buďte všelikému lidskému zřízení pro Pána, buďto králi, jako nejvyššímu,'),
(1576673,54,60,2,14,'Buďto vladařům, jako od něho poslaným, ku pomstě zle činících a k chvále dobře činících.'),
(1576674,54,60,2,15,'Nebo tak jest vůle Boží, abyste dobře činíce, zacpali ústa nemoudrých lidí z neznámosti vám utrhajících.'),
(1576675,54,60,2,16,'Buďtež jako svobodní, však ne jako zastření majíce své zlosti svobodu, ale jakožto služebníci Boží.'),
(1576676,54,60,2,17,'Všecky ctěte, bratrstvo milujte, Boha se bojte, krále v uctivosti mějte.'),
(1576677,54,60,2,18,'Služebníci poddáni buďte ve vší bázni pánům, netoliko dobrým a mírným, ale i zlým.'),
(1576678,54,60,2,19,'Neb toť jest milé, jestliže kdo pro svědomí Boží snáší zámutky, trpě bez viny.'),
(1576679,54,60,2,20,'Nebo jaká jest chvála, byste pak i snášeli pohlavkování, hřešíce? Ale jestliže dobře činíce, a bez viny trpíce, snášíte, toť jest milé před Bohem.'),
(1576680,54,60,2,21,'Nebo i k tomu povoláni jste, jako i Kristus trpěl za nás, nám pozůstaviv příklad, abychom následovali šlépějí jeho.'),
(1576681,54,60,2,22,'Kterýž hříchu neučinil, aniž jest lest nalezena v ústech jeho.'),
(1576682,54,60,2,23,'Kterýžto, když mu zlořečili, nezlořečil zase; trpěv, nehrozil, ale poroučel křivdy tomu, jenž spravedlivě soudí.'),
(1576683,54,60,2,24,'Kterýžto hříchy naše na svém těle sám vnesl na dřevo, abychom hříchům zemrouce, spravedlnosti živi byli, jehož zsinalostí uzdraveni jste.'),
(1576684,54,60,2,25,'Nebo jste byli jako ovce bloudící, ale již nyní obráceni jste ku pastýři a biskupu duší vašich.'),
(1576685,54,60,3,1,'Též podobně i ženy buďte poddané mužům svým, aby, byť pak kteří i nevěřili slovu, skrze zbožné obcování žen bez slova získáni byli,'),
(1576686,54,60,3,2,'Spatřujíce v bázni svaté vaše obcování.'),
(1576687,54,60,3,3,'Kterýchžto ozdoba budiž ne ta zevnitřní, v spletání vlasů, a províjení jich zlatem, anebo v odívání plášťů,'),
(1576688,54,60,3,4,'Ale ten skrytý srdce člověk, záležející v neporušitelnosti krotkého a pokojného ducha, kterýžto před obličejem Božím velmi drahý jest.'),
(1576689,54,60,3,5,'Tak jsou zajisté někdy i ony svaté ženy, kteréž naději měly v Bohu, ozdobovaly se, poddány byvše manželům svým,'),
(1576690,54,60,3,6,'Jako Sára poslušna byla Abrahama, pánem jej nazývajici; jejížto vy jste dcerky, dobře činíce a nebojíce se žádného přestrašení.'),
(1576691,54,60,3,7,'Též podobně i muži spolu s nimi bydlíce podle umění, jakožto mdlejšímu osudí ženskému udělujíce cti, jakožto i spoludědičkám života milosti, aby modlitby vaše neměly překážky.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576692,54,60,3,8,'A tak sumou, všickni buďte jednomyslní, jedni druhých bíd čitelní, bratrstva milovníci, milosrdní, dobrotiví,'),
(1576693,54,60,3,9,'Neodplacujíce zlého za zlé, ani zlořečenství za zlořečenství, ale raději dobrořečíce, vědouce, že jste k tomu povoláni, abyste požehnání dědičně obdrželi.'),
(1576694,54,60,3,10,'Nebo kdož chce milovati život, a viděti dny dobré, zkrocujž jazyk svůj od zlého, a ústa jeho ať nemluví lsti.'),
(1576695,54,60,3,11,'Uchyl se od zlého, a čiň dobré; hledej pokoje, a stihej jej.'),
(1576696,54,60,3,12,'Nebo oči Páně obrácené jsou na spravedlivé a uši jeho k prosbám jejich, ale zuřivý obličej Páně na ty, kteříž činí zlé věci.'),
(1576697,54,60,3,13,'A kdo jest, ješto by vám zle učinil, jestliže budete následovníci dobrého?'),
(1576698,54,60,3,14,'Ale kdybyste pak i trpěli pro spravedlnost, blahoslavení jste. Strachu pak jejich nebojte se, ani se kormuťte,'),
(1576699,54,60,3,15,'Ale Pána Boha posvěcujte v srdcích vašich. Hotovi pak buďte vždycky k vydání počtu všelikému, kdož by od vás požádal zprávy z naděje té, kteráž jest v vás, a to s tichostí a s bázní,'),
(1576700,54,60,3,16,'Majíce dobré svědomí, aby za to, že utrhají vám jako zločincům, zahanbeni byli ti, kteříž hanějí vaše ctné v Kristu obcování.'),
(1576701,54,60,3,17,'Lépeť jest zajisté, abyste dobře činíce, líbilo-li by se tak vůli Boží, trpěli, nežli zle činíce.'),
(1576702,54,60,3,18,'Nebo i Kristus jedinou za hříchy trpěl, spravedlivý za nespravedlivé, aby nás přivedl k Bohu, umrtven jsa z strany těla, ale obživen z strany Ducha.'),
(1576703,54,60,3,19,'Skrze něhož i těm, kteříž jsou již v žaláři, duchům přicházeje kázával,'),
(1576704,54,60,3,20,'Někdy nepovolným, když ono jednou očekávala Boží snášelivost za dnů Noé, když dělán byl koráb, v kterémžto málo, to jest osm duší, zachováno jest u vodě.'),
(1576705,54,60,3,21,'K čemužto připodobněn jsa nyní křest, i nás spaseny činí, ne to tělesné špíny smytí, ale dobrého svědomí u Boha dotázání, skrze vzkříšení Ježíše Krista.'),
(1576706,54,60,3,22,'Kterýž všed v nebe, jest na pravici Boží, podmaniv sobě anděly, i mocnosti, i moci.'),
(1576707,54,60,4,1,'Poněvadž tedy Kristus trpěl za nás na těle, i vy také týmž myšlením odíni buďte, totiž že ten, kdož na těle trpěl, přestal od hříchu,'),
(1576708,54,60,4,2,'K tomu, aby již nebyl více tělesným žádostem, ale vůli Boží v těle živ, po všecken čas, což ho ještě zůstává.'),
(1576709,54,60,4,3,'Dostiť jest zajisté nám na tom přeběhlém času života našeho, v němž jsme vůli těla podle obyčeje pohanů páchali, chodivše v nestydatých chlipnostech, v žádostech, v zbytečném pití vína, v hodování, v opilství a v ohyzdném modlosloužení.'),
(1576710,54,60,4,4,'A protož když se k nim nepřipojujete v takovém jejich vydávání se v rozpustilosti, zdá se jim to cosi nového býti, a rouhají se tomu.'),
(1576711,54,60,4,5,'Tiť vydadí počet tomu, kterýž hotov jest souditi živé i mrtvé.'),
(1576712,54,60,4,6,'Proto jest zajisté i mrtvým kázáno evangelium, aby souzeni byli podle lidí, to jest z strany těla, ale živi byli podle Boha duchem.'),
(1576713,54,60,4,7,'Všemuť se pak přibližuje konec.'),
(1576714,54,60,4,8,'A protož buďte středmí a bedliví k modlitbám. Přede vším pak lásku jedni k druhým opravdovou mějte; nebo láska přikryje množství hříchů.'),
(1576715,54,60,4,9,'Buďte vespolek přívětiví k hostem, bez reptání.'),
(1576716,54,60,4,10,'Jeden každý jakž vzal od Boha dar, tak vespolek tím sobě přisluhujte, jako dobří šafáři rozličné milosti Boží.'),
(1576717,54,60,4,11,'Mluví-li kdo, mluviž jako řeči Boží; jestliže kdo přisluhuje, činiž to jakožto z moci, kteréž jemu uděluje Bůh, aby ve všem slaven byl Bůh skrze Jezukrista, kterémuž jest sláva a císařství na věky věků. Amen.'),
(1576718,54,60,4,12,'Nejmilejší, nebudiž vám divný ten přišlý na vás oheň, pro zkušení vás, jako by se vám něco nového přihodilo.'),
(1576719,54,60,4,13,'Ale z toho, že jste účastni utrpení Kristových, radujte se, abyste i při zjevení slávy jeho radovali se s veselím.'),
(1576720,54,60,4,14,'Trpíte-li pohanění pro jméno Kristovo, blahoslavení jste. Nebo Duch ten slávy a Boží na vás odpočívá, kterémužto z strany jich zajisté rouhání se děje, ale z strany vaší oslavován bývá.'),
(1576721,54,60,4,15,'Žádný pak z vás netrp jako vražedlník, aneb zloděj, neb zločinec, anebo všetečný.'),
(1576722,54,60,4,16,'Jestliže pak kdo trpí jako křesťan, nestyď se za to, ale oslavujž Boha v té částce.'),
(1576723,54,60,4,17,'Neboť jest čas, aby se začal soud od domu Božího. A poněvadž nejprv začíná se od nás, jakýž bude konec těch, kteříž nejsou povolni evangelium Božímu?'),
(1576724,54,60,4,18,'A poněvadž spravedlivý sotva k spasení přichází, bezbožný a hříšník kde se ukáže?'),
(1576725,54,60,4,19,'A protož i ti, kteříž trpí podle vůle Boží, jakožto věrnému Stvořiteli ať poroučejí duše své, dobře činíce.'),
(1576726,54,60,5,1,'Starších, kteříž mezi vámi jsou, prosím já spolustarší, a svědek Kristových utrpení, a budoucí, kteráž zjevena bude, slávy účastník:'),
(1576727,54,60,5,2,'Paste stádo Boží, kteréž při vás jest, opatrujíce je, ne bezděky, ale dobrovolně, ne pro mrzký zisk, ale ochotně,'),
(1576728,54,60,5,3,'Ani jako panujíce nad dědictvím Páně, ale jako příkladem jsouce stádu.'),
(1576729,54,60,5,4,'A když se ukáže kníže pastýřů, vezmete tu neuvadlou korunu slávy.'),
(1576730,54,60,5,5,'Podobně i mládenci, buďte poddáni starším. A všickni poddanost jedni druhým ukazujte, pokorou vnitř se ozdobte. Bůh zajisté pyšným se protiví, ale pokorným dává milost.'),
(1576731,54,60,5,6,'Pokořtež se tedy pod mocnou ruku Boží, aby vás povýšil časem svým,'),
(1576732,54,60,5,7,'Všelikou péči vaši uvrhouce na něj. Nebo onť má péči o vás.'),
(1576733,54,60,5,8,'Střízliví buďte, bděte; nebo protivník váš ďábel jako lev řvoucí obchází, hledaje, koho by sežral.'),
(1576734,54,60,5,9,'Jemužto odpírejte, silní jsouce u víře, vědouce, že tatáž utrpení bratrstvo vaše, kteréž na světě jest, obkličují.'),
(1576735,54,60,5,10,'Bůh pak všeliké milosti, kterýž povolal nás k věčné slávě své v Kristu Ježíši, když maličko potrpíte, on dokonalé vás učiň, utvrď, zmocni i upevni.'),
(1576736,54,60,5,11,'Jemuž sláva a císařství na věky věků. Amen.'),
(1576737,54,60,5,12,'Po Silvánovi, vám věrném bratru, tak za to mám, že jsem psal vám krátce, napomínaje a osvědčuje, že tato jest pravá milost Boží, v kteréž stojíte.'),
(1576738,54,60,5,13,'Pozdravuje vás ta církev, kteráž jest v Babyloně, účastnice vyvolení vašeho, a Marek syn můj.'),
(1576739,54,60,5,14,'Pozdravtež jedni druhých v políbení laskavém. Pokoj vám všechněm, kteříž jste v Kristu Ježíši. Amen.'),
(1576740,54,61,1,1,'Šimon Petr, služebník a apoštol Ježíše Krista, těm, kteříž spolu s námi zároveň drahé dosáhli víry, pro spravedlnost Boha našeho a Spasitele Jezukrista:'),
(1576741,54,61,1,2,'Milost vám a pokoj rozmnožen buď skrze známost Boha a Ježíše Pána našeho.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576742,54,61,1,3,'Jakož nám od jeho Božské moci všecko, což potřebí bylo k životu a ku zbožnosti, darováno jest, skrze známost toho, kterýž povolal nás k slávě a k ctnosti.'),
(1576743,54,61,1,4,'Odkudžto veliká nám a drahá zaslíbení dána jsou, tak abyste skrze ně Božského přirození účastníci učiněni byli, utekše porušení toho, kteréž jest na světě v žádostech zlých.'),
(1576744,54,61,1,5,'A na to pak vy všecku snažnost svou vynaložíce, prokazujte u víře své ctnost, a v ctnosti umění,'),
(1576745,54,61,1,6,'V umění pak zdrželivost, a v zdrželivosti trpělivost, v trpělivosti pak zbožnost,'),
(1576746,54,61,1,7,'V zbožnosti pak bratrstva milování, a v milování bratrstva lásku.'),
(1576747,54,61,1,8,'Ty zajisté věci když budou při vás a to rozhojněné, ne prázdné, ani neužitečné postaví vás v známosti Pána našeho Jezukrista.'),
(1576748,54,61,1,9,'Nebo při komž není těchto věcí, slepýť jest, a toho, což vzdáleno jest, nevida, zapomenuv na očištění svých starých hříchů.'),
(1576749,54,61,1,10,'Protož, bratří, raději snažte se pevné povolání své i vyvolení učiniti; nebo to činíce, nepadnete nikdy.'),
(1576750,54,61,1,11,'Takť zajisté hojné způsobeno vám bude vjití k věčnému království Pána našeho a Spasitele Jezukrista.'),
(1576751,54,61,1,12,'Protož nezanedbámť vždycky vám připomínati těch věcí, ačkoli umělí i utvrzení jste v přítomné pravdě.'),
(1576752,54,61,1,13,'Neboť to mám za spravedlivé, dokudž jsem v tomto stánku, abych vás probuzoval napomínáním,'),
(1576753,54,61,1,14,'Věda, že brzké jest složení stánku mého, jakož mi i Pán náš Ježíš Kristus oznámil.'),
(1576754,54,61,1,15,'Přičinímť se i o to, abyste vy po odchodu mém často se na ty věci rozpomínati mohli.'),
(1576755,54,61,1,16,'Nebo ne nějakých vtipně složených básní následujíce, známu učinili jsme vám Pána našeho Jezukrista moc a příchod, ale jakožto ti, kteříž jsme očima svýma viděli jeho velebnost.'),
(1576756,54,61,1,17,'Přijalť jest zajisté od Boha Otce čest a slávu, když se stal k němu hlas takový od velebné slávy: Tentoť jest ten můj milý Syn, v němž mi se zalíbilo.'),
(1576757,54,61,1,18,'A ten hlas my jsme slyšeli s nebe pošlý, s ním byvše na oné hoře svaté.'),
(1576758,54,61,1,19,'A mámeť přepevnou řeč prorockou, kteréžto že šetříte jako svíce, jenž svítí v temném místě, dobře činíte, až by se den rozednil a dennice vzešla v srdcích vašich,'),
(1576759,54,61,1,20,'Toto nejprve znajíce, že žádného proroctví Písma svatého výklad nezáleží na rozumu lidském.'),
(1576760,54,61,1,21,'Nebo nikdy z lidské vůle nepošlo proroctví, ale Duchem svatým puzeni jsouce, mluvili svatí Boží lidé.'),
(1576761,54,61,2,1,'Bývali pak i falešní proroci v lidu, jakož i mezi vámi budou falešní učitelé, kteříž chytře uvedou sekty zatracení, i toho Pána, kterýž je vykoupil, zapírajíce, uvodíce na sebe rychlé zahynutí.'),
(1576762,54,61,2,2,'A mnozí následovati budou jejich zahynutí, skrze něž cesta pravdy bude v porouhání dávána.'),
(1576763,54,61,2,3,'A lakomě skrze vymyšlené řeči vámi kupčiti budou; kterýchžto odsouzení již dávno nemešká, a zahynutí jejich nespí.'),
(1576764,54,61,2,4,'Nebo poněvadžť Bůh andělům, kteříž zhřešili, neodpustil, ale strhna je do žaláře, řetězům mrákoty oddal, aby k odsouzení chováni byli,'),
(1576765,54,61,2,5,'I onomu prvnímu světu neodpustil, ale sama osmého Noé, kazatele spravedlnosti, zachoval, když potopu na svět bezbožníků uvedl.'),
(1576766,54,61,2,6,'A města Sodomských a Gomorských v popel obrátiv, podvrácením odsoudil, příklad budoucím bezbožníkům na nich ukázav,'),
(1576767,54,61,2,7,'A spravedlivého Lota, ztrápeného těch nešlechetníků chlipným obcováním, vytrhl.'),
(1576768,54,61,2,8,'Ten zajisté spravedlivý, bydliv mezi nimi, den ode dne hleděním i slyšením spravedlivou duši nešlechetnými jejich skutky trápil.'),
(1576769,54,61,2,9,'Umíť Pán zbožné z pokušení vytrhnouti, nepravých pak ke dni soudu potrestaných dochovati,'),
(1576770,54,61,2,10,'A zvláště těch, jenž po těle v žádosti nečisté chodí, a vrchností pohrdají, jsou i smělí, sobě se zalibující, neostýchají se důstojnostem porouhati.'),
(1576771,54,61,2,11,'Ješto andělé, jsouce větší v síle a v moci, nečiní proti nim přede Pánem potupného soudu.'),
(1576772,54,61,2,12,'Tito pak jako nerozumná hovada, kteráž za přirozením jdou, zplozená k zjímání a k zahynutí, tomu, čemuž nerozumějí, rouhajíce se, v tom svém porušení zahynou,'),
(1576773,54,61,2,13,'A tak odplatu nepravosti své ponesou, jakožto ti, kteřížto sobě za rozkoš položili, aby se na každý den v libostech svých kochali, nejsouce než poskvrny a mrzkosti, ti, kteříž s vámi hodujíce, v svých lstech se kochají,'),
(1576774,54,61,2,14,'Oči majíce plné cizoložstva, a bez přestání hřešící, přeluzujíce duše neustavičné, srdce majíce vycvičené v lakomství, synové zlořečenství.'),
(1576775,54,61,2,15,'Kteříž opustivše cestu přímou, zbloudili, následujíce cesty Balámovy, syna Bozorova, kterýž mzdu nepravosti zamiloval.'),
(1576776,54,61,2,16,'Ale měl, od koho by pokárán byl pro svůj výstupek. Nebo jhu poddaná oslice němá, člověčím hlasem promluvivši, zbránila nemoudrosti proroka.'),
(1576777,54,61,2,17,'Tiť jsou studnice bez vody, a mlhy vichrem zbouřené, jimžťo mrákota tmy chová se na věčnost.'),
(1576778,54,61,2,18,'Nebo přepyšně marné věci vypravujíce, žádostmi těla a chlipnostmi loudí ty, kteříž byli vpravdě utekli od těch, jenž bludu obcují,'),
(1576779,54,61,2,19,'Slibujíce jim svobodu, ješto sami jsou služebníci porušení, poněvadž od kohož kdo jest přemožen, tomu jest i v službu podroben.'),
(1576780,54,61,2,20,'Jestliže pak ti, jenž ušli poskvrn světa, skrze známost Pána a Spasitele Jezukrista, opět zase v to zapleteni jsouce, přemoženi byli, učiněn jest poslední způsob jejich horší nežli první.'),
(1576781,54,61,2,21,'Lépe by zajisté jim bylo nepoznávati cesty spravedlnosti, nežli po nabytí známosti odvrátiti se od vydaného jim svatého přikázání.'),
(1576782,54,61,2,22,'Ale přihodilo se jim to, což se v přísloví pravém říkává: Pes navrátil se k vývratku svému, a svině umytá do kaliště bláta.'),
(1576783,54,61,3,1,'Nejmilejší, již toto druhý list vám píši, v kterýchžto listech vzbuzuji skrze napomínání vaši upřímnou mysl,'),
(1576784,54,61,3,2,'Abyste pamatovali na slova předpověděná od svatých proroků, a na přikázání vydané vám od nás apoštolů Pána a Spasitele,'),
(1576785,54,61,3,3,'Toto nejprve vědouce, žeť přijdou v posledních dnech posměvači, podle svých vlastních žádostí chodící,'),
(1576786,54,61,3,4,'A říkající: Kdež jest to zaslibování příchodu jeho? Nebo jakž otcové naši zesnuli, všecko tak trvá od počátku stvoření.'),
(1576787,54,61,3,5,'Tohoť zajisté z úmysla věděti nechtí, že nebesa již dávno slovem Božím byla učiněna, i země z vody a na vodě upevněna.'),
(1576788,54,61,3,6,'Pročež onen první svět vodou jsa zatopen, zahynul.'),
(1576789,54,61,3,7,'Ta pak nebesa, kteráž nyní jsou, i země, týmž slovem odložena jsou a zachována k ohni, ke dni soudu a zatracení bezbožných lidí.'),
(1576790,54,61,3,8,'Ale tato jedna věc nebudiž před vámi skryta, nejmilejší, že jeden den u Pána jest jako tisíc let, a tisíc let jako jeden den.'),
(1576791,54,61,3,9,'Nemeškáť Pán s naplněním slibů, (jakož někteří za to mají, že obmeškává,) ale shovívá nám, nechtě, aby kteří zahynuli, ale všickni ku pokání se obrátili.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576792,54,61,3,10,'Přijdeť zajisté den Páně, jako zloděj v noci, v kterémžto nebesa jako v prudkosti vichru pominou, a živlové pálivostí ohně rozplynou se, země pak i ty věci, kteréž jsou na ní, vypáleny budou.'),
(1576793,54,61,3,11,'Poněvadž tedy to všecko má se rozplynouti, jací pak vy býti máte v svatých obcováních a v zbožnosti,'),
(1576794,54,61,3,12,'Očekávajíce a chvátajíce ku příští dne Božího, v němžto nebesa, hoříce, rozpustí se, a živlové pálivostí ohně rozplynou se?'),
(1576795,54,61,3,13,'Nového pak nebe a nové země podle zaslíbení jeho čekáme, v kterýchžto spravedlnost přebývá.'),
(1576796,54,61,3,14,'Protož, nejmilejší, takových věcí čekajíce, snažtež se, abyste bez poskvrny a bez úhony před ním nalezeni byli v pokoji;'),
(1576797,54,61,3,15,'A Pána našeho dlouhočekání za spasení mějte, jakož i milý bratr náš Pavel, podle sobě dané moudrosti, psal vám,'),
(1576798,54,61,3,16,'Jako i ve všech epištolách svých, mluvě v nich o těch věcech. Mezi nimiž některé jsou nesnadné k vyrozumění, kterýchžto neučení a neutvrzení natahují, jako i jiných Písem, k svému vlastnímu zatracení.'),
(1576799,54,61,3,17,'Vy tedy, nejmilejší, to prve vědouce, střeztež se, abyste bludem těch nešlechetných lidí nebyli pojati a nevypadli od své pevnosti.'),
(1576800,54,61,3,18,'Ale rozmáhejtež se v milosti a v známosti Pána našeho a Spasitele Jezukrista, jemuž sláva i nyní i na časy věčné. Amen.'),
(1576801,54,62,1,1,'Což bylo od počátku, což jsme slýchali, co jsme očima svýma viděli, a co jsme pilně spatřili, a čeho se ruce naše dotýkaly, o slovu života,'),
(1576802,54,62,1,2,'(Nebo ten život zjeven jest, a my jsme viděli jej, a svědčíme, i zvěstujeme vám ten život věčný, kterýž byl u Otce, a zjeven jest nám,)'),
(1576803,54,62,1,3,'Což jsme viděli a slyšeli, to vám zvěstujeme, abyste i vy s námi obecenství měli, a obecenství naše aby bylo s Otcem i s Synem jeho Jezukristem.'),
(1576804,54,62,1,4,'A totoť píšeme vám, aby radost vaše byla plná.'),
(1576805,54,62,1,5,'Toť jest tedy zvěstování to, kteréž jsme slýchali od něho, a zvěstujeme vám: Že Bůh jest světlo, a tmy v něm nižádné není.'),
(1576806,54,62,1,6,'Díme-li, že s ním obecenství máme, a ve tmě chodíme, lžeme a nečiníme pravdy.'),
(1576807,54,62,1,7,'Pakliť chodíme v světle, jako on jest v světle, obecenství máme vespolek, a krev Ježíše Krista Syna jeho očišťuje nás od všelikého hříchu.'),
(1576808,54,62,1,8,'Pakliť díme, že hříchu nemáme, sami se svodíme, a pravdy v nás není.'),
(1576809,54,62,1,9,'Jestliže pak budeme vyznávati hříchy své, věrnýť jest Bůh a spravedlivý, aby nám odpustil hříchy, a očistil nás od všeliké nepravosti.'),
(1576810,54,62,1,10,'Díme-li, že jsme nehřešili, činíme jej lhářem, a neníť v nás slova jeho.'),
(1576811,54,62,2,1,'Synáčkové moji, totoť vám píši, abyste nehřešili. Pakliť by kdo zhřešil, přímluvci máme u Otce, Ježíše Krista spravedlivého.'),
(1576812,54,62,2,2,'A onť jest obět slitování za hříchy naše, a netoliko za naše, ale i za hříchy všeho světa.'),
(1576813,54,62,2,3,'A po tomť známe, že jsme jej poznali, jestliže přikázání jeho ostříháme.'),
(1576814,54,62,2,4,'Dí-liť kdo: Znám jej, a přikázání jeho neostříhá, lhářť jest, a pravdy v něm není.'),
(1576815,54,62,2,5,'Ale kdožť ostříhá slova jeho, v pravděť láska Boží v tom jest dokonalá. Po tomť známe, že jsme v něm.'),
(1576816,54,62,2,6,'Kdo praví, že v něm zůstává, máť, jakž on chodil, i tento tak choditi.'),
(1576817,54,62,2,7,'Bratří, ne nějaké nové přikázání vám píši, ale přikázání staré, kteréž jste měli od počátku. A to přikázání staré jestiť slovo to, kteréž jste slyšeli od počátku.'),
(1576818,54,62,2,8,'A zase přikázání nové píši vám, kteréžto jest pravé i v něm i v vás. Nebo tma pomíjí, a světlo to pravé již svítí.'),
(1576819,54,62,2,9,'Kdo praví, že jest v světle, a bratra svého nenávidí, v temnostiť jest až posavad.'),
(1576820,54,62,2,10,'Kdož miluje bratra svého, v světle zůstává, a pohoršení v něm není.'),
(1576821,54,62,2,11,'Ale kdož nenávidí bratra svého, v temnosti jest, a v temnosti chodí, a neví, kam jde; nebo temnost oslepila oči jeho.'),
(1576822,54,62,2,12,'Píši vám, synáčkové, žeť jsou vám odpuštěni hříchové pro jméno jeho.'),
(1576823,54,62,2,13,'Píši vám, otcové, že jste poznali toho, kterýž jest od počátku. Píši vám, mládenci, že jste zvítězili nad zlým.'),
(1576824,54,62,2,14,'Píši vám, dítky, že jste poznali Otce. Psal jsem vám, otcové, že jste poznali toho, kterýž jest od počátku. Psal jsem vám, mládenci, že silní jste, a slovo Boží v vás zůstává, a že jste zvítězili nad zlým.'),
(1576825,54,62,2,15,'Nemilujtež světa, ani těch věcí, kteréž na světě jsou. Miluje-liť kdo svět, není lásky Otcovy v něm.'),
(1576826,54,62,2,16,'Nebo všecko, což jest na světě, jako žádost těla, a žádost očí, a pýcha života, toť není z Otce, ale jest z světa.'),
(1576827,54,62,2,17,'A svět hyne i žádost jeho, ale kdož činí vůli Boží, ten trvá na věky.'),
(1576828,54,62,2,18,'Dítky, poslední hodina jest, a jakož jste slýchaly, že antikrist přijíti má, i nyníť antikristové jsou mnozí. Odkudž známe, že poslední hodina jest.'),
(1576829,54,62,2,19,'Z násť jsou vyšli, ale nebyli z nás. Nebo byť byli z nás, byliť by zůstali s námi, ale vyšli z nás, aby zjeveni byli, že nejsou všickni z nás.'),
(1576830,54,62,2,20,'Vy pak máte pomazání od Svatého, a znáte všecko.'),
(1576831,54,62,2,21,'Nepsal jsem vám proto, že byste neznali pravdy, ale že ji znáte, a že všeliká lež není z pravdy.'),
(1576832,54,62,2,22,'A kdo jest lhář, nežli ten, kdož zapírá, že Ježíš není Kristus? Tenť jest antikrist; kdoť zapírá Otce, zapíráť i Syna.'),
(1576833,54,62,2,23,'Každý kdož zapírá Syna, nemáť ani Otce.'),
(1576834,54,62,2,24,'A protož zůstaniž v vás to, což jste slýchali od počátku. Zůstane-liť v vás to, co jste slýchali od počátku, i vy také v Synu i v Otci zůstanete.'),
(1576835,54,62,2,25,'A toť jest to zaslíbení, kteréž nám zaslíbil, totiž ten život věčný.'),
(1576836,54,62,2,26,'Tyto věci psal jsem vám o těch, kteříž vás svodí.'),
(1576837,54,62,2,27,'Ale pomazání to, kteréž jste vzali od něho, v vás zůstává, a aniž potřebujete, aby kdo učil vás, ale jakž pomazání to učí vás o všech věcech, a pravéť jest a neoklamavatelné, a jakž naučilo vás, tak v něm zůstávejte.'),
(1576838,54,62,2,28,'A nyní, synáčkové, zůstávejtež v něm, abychom, když by se ukázal, smělé doufání měli, a nebyli zahanbeni od něho v čas příchodu jeho.'),
(1576839,54,62,2,29,'Poněvadž víte, že on spravedlivý jest, znejtež také, že každý, kdož činí spravedlnost, z něho jest narozen.'),
(1576840,54,62,3,1,'Pohleďte, jakou lásku dal nám Otec, totiž abychom synové Boží slouli. Protoť svět nezná nás, že jeho nezná.'),
(1576841,54,62,3,2,'Nejmilejší, nyní synové Boží jsme, ale ještěť se neokázalo, co budeme. Vímeť pak, že když se okáže, podobni jemu budeme; nebo viděti jej budeme tak, jakž jest.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576842,54,62,3,3,'A každý, kdož má takovou naději v něm, očišťuje se, jakož i on čistý jest.'),
(1576843,54,62,3,4,'Každý, kdož činí hřích, činíť proti zákonu; nebo hřích jest přestoupení zákona.'),
(1576844,54,62,3,5,'A víte, že on se okázal proto, aby hříchy naše sňal, a hříchu v něm není.'),
(1576845,54,62,3,6,'Každý tedy, kdož v něm zůstává, nehřeší; ale každý, kdož hřeší, neviděl ho, aniž ho poznal.'),
(1576846,54,62,3,7,'Synáčkové, nižádný vás nesvoď. Kdož činí spravedlnost, spravedlivý jest, jakož i on jest spravedlivý.'),
(1576847,54,62,3,8,'Kdož činí hřích, z ďábla jest; nebo ďábel hned od počátku hřeší. Na toť jest zjeven Syn Boží, aby kazil skutky ďáblovy.'),
(1576848,54,62,3,9,'Každý, kdož se narodil z Boha, hříchu nečiní; nebo símě jeho v něm zůstává, aniž může hřešiti, nebo z Boha narozen jest.'),
(1576849,54,62,3,10,'Po tomtoť zjevní jsou synové Boží a synové ďáblovi. Každý, kdož nečiní spravedlnosti, neníť z Boha, a kdož nemiluje bratra svého.'),
(1576850,54,62,3,11,'Nebo toť jest to zvěstování, kteréž jste slýchali od počátku, abychom milovali jedni druhé.'),
(1576851,54,62,3,12,'Ne jako Kain, kterýž z toho zlostníka byl a zamordoval bratra svého. A pro kterou příčinu zamordoval ho? Protože skutkové jeho byli zlí, bratra pak jeho byli spravedliví.'),
(1576852,54,62,3,13,'Nedivtež se, bratří moji, jestliže vás svět nenávidí.'),
(1576853,54,62,3,14,'My víme, že jsme přeneseni z smrti do života, nebo milujeme bratří. Kdož nemiluje bratra, zůstáváť v smrti.'),
(1576854,54,62,3,15,'Každý, kdož nenávidí bratra svého, vražedlník jest, a víte, že žádný vražedlník nemá života věčného v sobě zůstávajícího.'),
(1576855,54,62,3,16,'Po tomto jsme poznali lásku, že on duši svou za nás položil, i myť tedy máme za bratří duše své klásti.'),
(1576856,54,62,3,17,'Kdo by pak měl statek tohoto světa, a viděl by bratra svého, an nouzi trpí, a zavřel by srdce své před ním, kterak láska Boží zůstává v něm?'),
(1576857,54,62,3,18,'Synáčkové moji, nemilujmež slovem, ani jazykem toliko, ale skutkem a pravdou.'),
(1576858,54,62,3,19,'A po tomť poznáváme, že z pravdy jsme, a před obličejem jeho spokojíme srdce svá.'),
(1576859,54,62,3,20,'Nebo obviňovalo-liť by nás srdce naše, ovšemť Bůh, kterýž jest větší nežli srdce naše a zná všecko.'),
(1576860,54,62,3,21,'Nejmilejší, jestližeť by nás srdce naše neobviňovalo, smělou doufanlivost máme k Bohu.'),
(1576861,54,62,3,22,'A začež ho koli prosíme, béřeme od něho; nebo přikázání jeho ostříháme, a to, což jest libého před obličejem jeho, činíme.'),
(1576862,54,62,3,23,'A totoť jest to přikázání jeho, abychom věřili jménu Syna jeho Jezukrista a milovali jedni druhé, jakož nám dal přikázání.'),
(1576863,54,62,3,24,'Nebo kdož ostříhá přikázání jeho, v němť zůstává, a on také v něm. A po tomť poznáváme, že zůstává v nás, totiž po Duchu, kteréhož dal nám.'),
(1576864,54,62,4,1,'Nejmilejší, ne každému duchu věřte, ale zkušujte duchů, jsou-li z Boha; nebo mnozí falešní proroci vyšli na svět.'),
(1576865,54,62,4,2,'Po tomto znejte Ducha Božího: Všeliký duch, kterýž vyznává Jezukrista v těle přišlého, z Boha jest.'),
(1576866,54,62,4,3,'Ale všeliký duch, kterýž nevyznává Jezukrista v těle přišlého, není z Boha; nýbrž toť jest ten duch antikristův, o kterémž jste slýchali, že přijíti má, a jižť jest nyní na světě.'),
(1576867,54,62,4,4,'Vy pak z Boha jste, synáčkové, a zvítězili jste nad nimi; nebo většíť jest ten, kterýž jest v vás, nežli ten, kterýž jest v světě.'),
(1576868,54,62,4,5,'Oni z světa jsou, a protož o světu mluví, a svět jich poslouchá.'),
(1576869,54,62,4,6,'My z Boha jsme. Kdo zná Boha, posloucháť nás; kdož pak není z Boha, neposloucháť nás. A po tomť poznáváme ducha pravdy a ducha bludu.'),
(1576870,54,62,4,7,'Nejmilejší, milujmež jedni druhé; nebo láska z Boha jest, a každý, kdož miluje, z Boha se narodil, a znáť Boha.'),
(1576871,54,62,4,8,'Kdož nemiluje, nezná Boha; nebo Bůh láska jest.'),
(1576872,54,62,4,9,'V tomť zjevena jest láska Boží k nám, že Syna svého toho jednorozeného poslal Bůh na svět, abychom živi byli skrze něho.'),
(1576873,54,62,4,10,'V tomť jest láska, ne že bychom my Boha milovali, ale že on miloval nás, a poslal Syna svého obět slitování za hříchy naše.'),
(1576874,54,62,4,11,'Nejmilejší, poněvadž tak miloval nás Bůh, i myť máme jedni druhé milovati.'),
(1576875,54,62,4,12,'Boha žádný nikdy nespatřil, ale milujeme-liť jedni druhé, Bůh v nás přebývá, a láska jeho dokonalá jest v nás.'),
(1576876,54,62,4,13,'Po tomtoť poznáváme, že v něm přebýváme, a on v nás, že z Ducha svého dal nám.'),
(1576877,54,62,4,14,'A myť jsme viděli, a svědčíme, že Otec poslal Syna svého spasitele světa.'),
(1576878,54,62,4,15,'Kdož by koli vyznával, že Ježíš jest Syn Boží, Bůh v něm přebývá, a on v Bohu.'),
(1576879,54,62,4,16,'A myť jsme poznali, a uvěřili o lásce, kterouž Bůh má k nám. Bůh láska jest, a kdož v lásce přebývá, v Bohu přebývá, a Bůh v něm.'),
(1576880,54,62,4,17,'V tomtoť jest k dokonání svému přišla láska Boží s námi, abychom bezpečné doufání měli v den soudný, kdyžto, jakýž jest on, takovíž i my jsme na tomto světě.'),
(1576881,54,62,4,18,'Bázněť není v lásce, ale láska dokonalá ven vyhání bázeň; nebo bázeň trápení má, kdož se pak bojí, není dokonalý v lásce.'),
(1576882,54,62,4,19,'My milujeme jej, nebo on prve miloval nás.'),
(1576883,54,62,4,20,'Řekl-li by kdo: Miluji Boha, a bratra svého nenáviděl by, lhář jest. Nebo kdož nemiluje bratra svého, kteréhož viděl, Boha, kteréhož neviděl, kterak může milovati?'),
(1576884,54,62,4,21,'A totoť přikázání máme od něho, aby ten, kdož miluje Boha, miloval i bratra svého.'),
(1576885,54,62,5,1,'Každý, kdož věří, že Ježíš jest Kristus, z Boha se narodil; a každý, kdož miluje toho, kterýž zplodil, milujeť i toho, kterýž zplozen jest z něho.'),
(1576886,54,62,5,2,'Po tomť poznáváme, že milujeme syny Boží, když Boha milujeme a přikázání jeho ostříháme.'),
(1576887,54,62,5,3,'Nebo toť jest láska Boží, abychom přikázaní jeho ostříhali; a přikázání jeho nejsou těžká.'),
(1576888,54,62,5,4,'Všecko zajisté, což se narodilo z Boha, přemáhá svět; a toť jest to vítězství, kteréž přemáhá svět, víra naše.'),
(1576889,54,62,5,5,'Kdo jest, ješto přemáhá svět, jediné, kdož věří, že Ježíš jest Syn Boží?'),
(1576890,54,62,5,6,'Toť jest ten, kterýž přišel vyznamenán jsa skrze vodu a krev, totiž Ježíš Kristus, ne u vodě toliko, ale u vodě a ve krvi. A Duch jest, jenž svědectví vydává, že Duch jest pravda.'),
(1576891,54,62,5,7,'Nebo tři jsou, kteříž svědectví vydávají na nebi: Otec, Slovo, a Duch Svatý, a ti tři jedno jsou.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576892,54,62,5,8,'A tři jsou, jenž svědectví vydávají na zemi: Duch, a Voda, a Krev, a ti tři jedno jsou.'),
(1576893,54,62,5,9,'Poněvadž svědectví lidské přijímáme, svědectvíť Boží větší jest. Nebo totoť svědectví jest Boží, kteréž vysvědčil o Synu svém.'),
(1576894,54,62,5,10,'Kdož věří v Syna Božího, máť svědectví sám v sobě. Kdož pak nevěří Bohu, lhářem jej učinil; nebo neuvěřil tomu svědectví, kteréž vysvědčil Bůh o Synu svém.'),
(1576895,54,62,5,11,'A totoť jest svědectví to, že život věčný dal nám Bůh, a ten život v Synu jeho jest.'),
(1576896,54,62,5,12,'Kdožť má Syna Božího, máť život; kdož nemá Syna Božího, života nemá.'),
(1576897,54,62,5,13,'Tyto věci psal jsem vám věřícím ve jméno Syna Božího, abyste věděli, že máte věčný život, a abyste věřili ve jméno Syna Božího.'),
(1576898,54,62,5,14,'A totoť jest to smělé doufání, kteréž máme k němu, že začež bychom koli prosili podle vůle jeho, slyší nás.'),
(1576899,54,62,5,15,'A kdyžť víme, že nás slyší, prosili-li bychom zač, tedyť víme, že máme některé prosby naplněné, kteréž jsme předkládali jemu.'),
(1576900,54,62,5,16,'Viděl-li by kdo bratra svého hřešícího hříchem ne k smrti, modliž se za něj, a dáť jemu Bůh život, totiž hřešícím ne k smrti. Jestiť hřích k smrti; ne za ten, pravím, aby se modlil.'),
(1576901,54,62,5,17,'Každá nepravost jestiť hřích, ale jestiť hřích ne k smrti.'),
(1576902,54,62,5,18,'Víme, že každý, kdož se narodil z Boha, nehřeší; ale ten, jenž narozen jest z Boha, ostříhá sebe samého, a ten zlostník se ho nedotýká.'),
(1576903,54,62,5,19,'Víme, že z Boha jsme, ale svět všecken ve zlém leží.'),
(1576904,54,62,5,20,'A vímeť, že Syn Boží přišel, a dal nám smysl, abychom poznali Toho Pravého, a jsmeť v tom Pravém, i v Synu jeho Ježíši Kristu. Onť jest ten pravý Bůh a život věčný.'),
(1576905,54,62,5,21,'Synáčkové, vystříhejte se modl. Amen.'),
(1576906,54,63,1,1,'Starší v Kristu vyvolené paní i synům jejím, kteréž já miluji v pravdě, a ne sám já, ale i všickni, kteříž poznali pravdu,'),
(1576907,54,63,1,2,'Pro pravdu, kteráž zůstává v nás a s námiť bude na věky:'),
(1576908,54,63,1,3,'Budiž s vámi milost, milosrdenství a pokoj od Boha Otce, i od Pána Jezukrista, Syna Otcova, v pravdě a v lásce.'),
(1576909,54,63,1,4,'Zradoval jsem se velmi, že jsem nalezl některé z synů tvých, an chodí v pravdě, jakož jsme přikázání vzali od Otce.'),
(1576910,54,63,1,5,'A nyní prosím tebe, paní, ne jako nové přikázání předkládaje tobě, ale to, kteréž jsme měli od počátku, abychom milovali jedni druhé.'),
(1576911,54,63,1,6,'A totoť jest ta láska, abychom chodili podle přikázání jeho. Přikázání pak toto jest, jakž jste slýchali od počátku, abyste v něm chodili.'),
(1576912,54,63,1,7,'Nebo mnozí bludaři vyšli na svět, kteříž nevyznávají Jezukrista přišlého v těle. Takový každý jest bludař a antikrist.'),
(1576913,54,63,1,8,'Hleďtež sebe, abychom neztratili toho, o čemž jsme pracovali, ale odplatu plnou abychom vzali.'),
(1576914,54,63,1,9,'Každý, kdož přestupuje a nezůstává v učení Kristovu, nemá Boha; kdož zůstává v učení Kristovu, tenť i Otce i Syna má.'),
(1576915,54,63,1,10,'Přichází-li kdo k vám, a tohoto učení nepřináší, nepřijímejte ho do domu, aniž ho pozdravujte.'),
(1576916,54,63,1,11,'Nebo kdož takového pozdravuje, přiúčastňuje se skutkům jeho zlým.'),
(1576917,54,63,1,12,'Mnoho vám psáti měv, nechtěl jsem svěřiti toho černidlu a papíru, ale mámť naději, že k vám přijdu, a ústy k ústům mluviti budu, aby radost naše plná byla.'),
(1576918,54,63,1,13,'Pozdravují tě synové sestry tvé v Pánu vyvolené. Amen.'),
(1576919,54,64,1,1,'Starší Gáiovi milému, kteréhož já miluji v pravdě.'),
(1576920,54,64,1,2,'Nejmilejší, žádámť obzvláštně, abys se dobře měl a zdráv byl, tak jako duše tvá dobře se má.'),
(1576921,54,64,1,3,'Zradovalť jsem se zajisté velice, když přišli bratří a svědectví vydávali o tvé upřímnosti, vypravujíce, kterak ty v upřímnosti chodíš.'),
(1576922,54,64,1,4,'Nemámť větší radosti, nežli abych slyšel, že synové moji chodí v upřímnosti.'),
(1576923,54,64,1,5,'Nejmilejší, věrně děláš, cožkoli činíš bratřím a hostem,'),
(1576924,54,64,1,6,'Kteřížto svědectví vydali o lásce tvé před církví. Kteréžto vyprovodíš-li, tak jakž sluší na Boha, dobře učiníš.'),
(1576925,54,64,1,7,'Neboť jsou pro jméno jeho vyšli, a nic nevzali od pohanů.'),
(1576926,54,64,1,8,'Mámeť tedy my takové přijímati, abychom byli pomocníci pravdy.'),
(1576927,54,64,1,9,'Psal jsem sboru vašemu, ale Diotrefes, kterýž stojí o prvotnost mezi nimi, nepřijímá nás.'),
(1576928,54,64,1,10,'Protož přijdu-liť tam, připomenuť skutky jeho, kteréž činí, mluvě proti nám zlé řeči. A nemaje dosti na tom, i sám bratří nepřijímá, i těm, kteříž by přijímati chtěli, nedopouští, a ze sboru je vylučuje.'),
(1576929,54,64,1,11,'Nejmilejší, nenásledujž zlého, ale dobrého. Kdož dobře činí, z Boha jest; ale kdož zle činí, nevidí Boha.'),
(1576930,54,64,1,12,'Demetriovi svědectví vydáno jest ode všech, i od samé pravdy; ano i my svědectví o něm vydáváme, a víte, že svědectví naše pravé jest.'),
(1576931,54,64,1,13,'Mnohoť jsem měl psáti, ale nechci psáti černidlem a pérem.'),
(1576932,54,64,1,14,'Nebo mám naději, že tě tudíž uzřím, a ústy k ústům mluviti budeme.'),
(1576933,54,64,1,15,'Pokoj budiž tobě. Pozdravují tě přátelé. Pozdraviž i ty dobrých přátel ze jména.'),
(1576934,54,65,1,1,'Judas, Ježíše Krista služebník, bratr pak Jakubův, posvěceným v Bohu Otci, a Kristu Ježíši zachovaným a k němu povolaným:'),
(1576935,54,65,1,2,'Milosrdenství vám a pokoj i láska budiž rozmnožena.'),
(1576936,54,65,1,3,'Nejmilejší, všecku snažnost vynakládaje na to, abych vám psal o obecném spasení, musil jsem psáti, vás napomínaje, abyste statečně bojovali o víru, kteráž jest jednou dána svatým.'),
(1576937,54,65,1,4,'Neboť jsou podešli někteří lidé bezbožní, prve již dávno poznamenaní k tomu odsouzení; kteřížto milost Boha našeho přenášejí v chlipnost, a toho, kterýž jest sám Hospodin, Boha a Pána našeho Jezukrista zapírají.'),
(1576938,54,65,1,5,'Protož vidělo mi se vám to připomenouti, kteříž jednou již o tom víte, že když Pán lid svůj z země Egyptské vysvobodil, potom ty, kteříž nevěřící byli, zatratil.'),
(1576939,54,65,1,6,'A ty anděly, kteříž neostříhali svého knížetství, ale opustili příbytek svůj, k soudu velikého toho dne vazbou věčnou pod mrákotou schoval.'),
(1576940,54,65,1,7,'Jako Sodoma a Gomora, a okolní města, když podobným způsobem, jako i tito, v smilstvo se vydali a odešli po těle cizím, předložena jsou za příklad, pokutu věčného ohně snášejíce.'),
(1576941,54,65,1,8,'Takéž podobně i tito, jako v hluboký sen pohřižení, tělo zajisté poskvrňují, panstvím pak pohrdají a důstojnosti se rouhají;');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576942,54,65,1,9,'Ješto Michal archanděl, když s ďáblem odpor maje, hádal se o tělo Mojžíšovo, neodvážil se proti němu vynésti soudu zlořečení, ale řekl: Ztresciž tě Pán.'),
(1576943,54,65,1,10,'Tito pak, čehož neznají, tomu se rouhají; a což od přirození znají, jako nerozumná hovada, v tom se poskvrňují.'),
(1576944,54,65,1,11,'Běda jim, nebo cestou Kainovou odešli, a poblouzením Balámovy mzdy po lakomství se vylili, a odporováním Kóre zahynuli.'),
(1576945,54,65,1,12,'Tiť jsou na hodech vašich poskvrny, když s vámi hodují bezstoudně, sami se pasouce; jsouce jako oblakové bez vody, jimiž vítr sem i tam točí, stromové uvadlí, neužiteční, dvakrát mrtví a vykořenění,'),
(1576946,54,65,1,13,'Vzteklé vody mořské, vymítajíce jako pěny svou mrzkost, hvězdy bludné, jimžto mrákota tmy zachována jest na věčnost.'),
(1576947,54,65,1,14,'Prorokoval pak také o nich sedmý od Adama Enoch, řka: Aj, Pán s svatými tisíci svými béře se,'),
(1576948,54,65,1,15,'Aby učinil soud všechněm a trestal všecky, kteříž by koli mezi nimi byli bezbožní, ze všech skutků bezbožnosti jejich, v nichž bezbožnost páchali, i ze všech tvrdých řečí, kteréž mluvili proti němu hříšníci bezbožní.'),
(1576949,54,65,1,16,'Tiť jsou reptáci žalobní, podle žádostí svých chodíce, jejichž ústa mluví pýchu, pochlebujíce osobám některým pro svůj užitek.'),
(1576950,54,65,1,17,'Ale vy, nejmilejší, pamatujte na slova předpověděná od apoštolů Pána našeho Jezukrista.'),
(1576951,54,65,1,18,'Nebo jsou pověděli vám, že v posledním času budou posměvači, podle svých bezbožných žádostí chodící.'),
(1576952,54,65,1,19,'Toť jsou ti, kteříž se sami odtrhují, lidé hovadní, Ducha Kristova nemající.'),
(1576953,54,65,1,20,'Ale vy, nejmilejší, vzdělávajíce se na té nejsvětější víře vaší, v Duchu svatém modléce se,'),
(1576954,54,65,1,21,'Ostříhejte se v lásce Boží, očekávajíce milosrdenství Pána našeho Jezukrista k věčnému životu.'),
(1576955,54,65,1,22,'A nad některými zajisté lítost mějte, rozeznání v tom majíce.'),
(1576956,54,65,1,23,'Jiné pak strašením k spasení přivozujte, jako z ohně je vychvacujíce, v nenávisti majíce i tu skrze tělo poskvrněnou sukni.'),
(1576957,54,65,1,24,'Tomu pak, kterýž mocen jest zachovati vás bez úrazu a postaviti před obličejem slávy své bez úhony s veselím,'),
(1576958,54,65,1,25,'Samému moudrému Bohu, Spasiteli našemu, budiž sláva a velebnost, císařství i moc, i nyní i po všecky věky. Amen.'),
(1576959,54,66,1,1,'Zjevení Ježíše Krista, kteréž dal jemu Bůh, aby ukázal služebníkům svým, které věci měly by se díti brzo, on pak zjevil, poslav je skrze anděla svého, služebníku svému Janovi,'),
(1576960,54,66,1,2,'Kterýž osvědčil slovo Boží a svědectví Jezukristovo, a cožkoli viděl.'),
(1576961,54,66,1,3,'Blahoslavený, kdož čte, i ti, kteříž slyší slova proroctví tohoto a ostříhají toho, což napsáno jest v něm; nebo čas blízko jest.'),
(1576962,54,66,1,4,'Jan sedmi církvím, kteréž jsou v Azii: Milost vám a pokoj od toho, Jenž jest, a Kterýž byl, a Kterýž přijíti má, a od sedmi Duchů, kteříž před obličejem trůnu jeho jsou,'),
(1576963,54,66,1,5,'A od Ježíše Krista, jenž jest svědek věrný, ten prvorozený z mrtvých, a kníže králů země, kterýžto zamiloval nás a umyl nás od hříchů našich krví svou,'),
(1576964,54,66,1,6,'A učinil nás krále a kněží Bohu a Otci svému, jemužto buď sláva a moc na věky věků. Amen.'),
(1576965,54,66,1,7,'Aj, béře se s oblaky, a uzříť jej všeliké oko, i ti, kteříž ho bodli; a budou plakati pro něj všecka pokolení země, jistě, Amen.'),
(1576966,54,66,1,8,'Jáť jsem Alfa i Omega, počátek i konec, praví Pán, Kterýž jest, a Kterýž byl, a Kterýž přijíti má, ten všemohoucí.'),
(1576967,54,66,1,9,'Já Jan, kterýž jsem i bratr váš, i spoluúčastník v soužení, i v království, i v trpělivosti Ježíše Krista, byl jsem na ostrově, kterýž slove Patmos, pro slovo Boží a svědectví Ježíše Krista.'),
(1576968,54,66,1,10,'A byl jsem u vytržení ducha v den Páně, i uslyšel jsem za sebou hlas veliký jako trouby,'),
(1576969,54,66,1,11,'An mi dí: Já jsem Alfa i Omega, ten první i poslední, a řekl: Co vidíš, piš do knihy, a pošli sborům, kteříž jsou v Azii, do Efezu, a do Smyrny, a do Pergamu, a do Tyatiru, a do Sardy, a do Filadelfie, i do Laodicie.'),
(1576970,54,66,1,12,'I obrátil jsem se, abych viděl ten hlas, kterýž mluvil se mnou, a obrátiv se, uzřel jsem sedm svícnů zlatých,'),
(1576971,54,66,1,13,'A uprostřed sedmi svícnů podobného Synu člověka, oblečeného v dlouhé roucho a přepásaného na prsech pasem zlatým.'),
(1576972,54,66,1,14,'Hlava pak jeho a vlasové byli bílí, jako bílá vlna, jako sníh, a oči jeho jako plamen ohně.'),
(1576973,54,66,1,15,'Nohy pak jeho podobné mosazi, jako v peci hořící; a hlas jeho jako hlas vod mnohých.'),
(1576974,54,66,1,16,'A měl v pravé ruce své sedm hvězd, a z úst jeho meč s obou stran ostrý vycházel; a tvář jeho jako slunce, když jasně svítí.'),
(1576975,54,66,1,17,'A jakž jsem jej uzřel, padl jsem k nohám jeho, jako mrtvý. I položil ruku svou pravou na mne, řka ke mně: Neboj se. Já jsem ten první i poslední,'),
(1576976,54,66,1,18,'A živý, ješto jsem byl mrtvý, a aj, živý jsem na věky věků. Amen. A mám klíče pekla i smrti.'),
(1576977,54,66,1,19,'Napiš ty věci, kteréž jsi viděl, a kteréž jsou, a kteréž se mají díti potom.'),
(1576978,54,66,1,20,'Tajemství sedmi hvězd, kteréž jsi viděl v pravici mé, a sedm svícnů zlatých, jest toto: Sedm hvězd jsou andělé sedmi církví; a sedm svícnů, kteréžs viděl, jest těch sedm církví.'),
(1576979,54,66,2,1,'Andělu Efezské církve piš: Totoť praví ten, kterýž drží těch sedm hvězd v pravici své, jenž se prochází uprostřed těch sedmi svícnů zlatých:'),
(1576980,54,66,2,2,'Známť skutky tvé, a práci tvou, i trpělivost tvou, a že nemůžeš trpěti zlých; a zkusil jsi těch, kteříž se praví býti apoštolé, ale nejsou, a shledals je, že jsou lháři.'),
(1576981,54,66,2,3,'A snášel jsi, a trpělivost máš, a pro jméno mé pracovals a neustal.'),
(1576982,54,66,2,4,'Ale mámť něco proti tobě, totiž že jsi tu první lásku svou opustil.'),
(1576983,54,66,2,5,'Protož pomni, odkud jsi vypadl, a čiň pokání a první skutky čiň. Pakliť toho nebude, přijdu na tebe rychle a pohnuť svícnem tvým z místa jeho, nebudeš-li pokání činiti.'),
(1576984,54,66,2,6,'Ale toto dobré do sebe máš, že nenávidíš skutků Mikulášenské roty, kterýchž i já nenávidím.'),
(1576985,54,66,2,7,'Kdo má uši, slyš, co Duch praví církvím: Tomu, kdož zvítězí, dám jísti z dřeva života, kteréž jest uprostřed ráje Božího.'),
(1576986,54,66,2,8,'Andělu pak Smyrnenské církve piš: Toto praví ten první i poslední, kterýž byl mrtvý, a ožil:'),
(1576987,54,66,2,9,'Vím o skutcích tvých, i o soužení, a chudobě tvé, (ale bohatý jsi), i o rouhání těch, kteříž se praví býti Židé, a nejsou, ale jsou sběř satanova.'),
(1576988,54,66,2,10,'Nebojž se nic toho, co trpěti máš. Aj, uvržeť ďábel některé z vás do vězení, abyste zkušeni byli, a budete míti úzkost za deset dní. Budiž věrný až do smrti, a dámť korunu života.'),
(1576989,54,66,2,11,'Kdo má uši, slyš, co Duch praví církvím: Kdo zvítězí, nebude uražen od smrti druhé.'),
(1576990,54,66,2,12,'Andělu pak Pergamenské církve piš: Totoť praví ten, kterýž má ten meč s obou stran ostrý:'),
(1576991,54,66,2,13,'Vím skutky tvé, i kde bydlíš, totiž tu, kdež jest stolice satanova, a že držíš se jména mého, a nezapřel jsi víry mé, ani v těch dnech, když Antipas, svědek můj věrný, zamordován jest u vás, tu, kdež bydlí satan.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1576992,54,66,2,14,'Ale mámť proti tobě něco málo, že tam máš ty, kteříž drží učení Balámovo, jenž učil Baláka pohoršení klásti před obličejem synů Izraelských, aby jedli modlám obětované a smilnili.'),
(1576993,54,66,2,15,'Tak i ty máš některé, kteříž drží učení Mikulášenců, což já v nenávisti mám.'),
(1576994,54,66,2,16,'Činiž pokání. Pakli nebudeš, přijdu na tebe brzy, a bojovatiť budu s nimi mečem úst svých.'),
(1576995,54,66,2,17,'Kdo má uši, slyšiž, co Duch praví církvím: Tomu, jenž vítězí, dám jísti mannu skrytou a dám jemu kamének bílý, a na tom kaménku jméno nové napsané, kteréhož žádný neví, než ten, kdož je přijímá.'),
(1576996,54,66,2,18,'Andělu pak Tyatirské církve piš: Totoť praví Syn Boží, jenž má oči jako plamen ohně, a nohy jeho podobné jsou mosazi:'),
(1576997,54,66,2,19,'Známť skutky tvé, i lásku, i přisluhování, i věrnost, i trpělivost tvou, a skutky tvé, i ty poslední, kteříž větší jsou nežli první.'),
(1576998,54,66,2,20,'Ale mámť proti tobě něco málo, že dopouštíš ženě Jezábel, kteráž se býti praví prorokyní, učiti a v blud uvoditi služebníky mé, aby smilnili a jedli modlám obětované.'),
(1576999,54,66,2,21,'Ale dalť jsem jí čas, aby pokání činila z smilstva svého, avšak nečinila pokání.'),
(1577000,54,66,2,22,'Aj, já uvrhu ji na lože, i ty, kteříž cizoloží s ní, v soužení převeliké, jestliže nebudou činiti pokání z skutků svých.'),
(1577001,54,66,2,23,'A syny její zmorduji smrtí; i zvědíť všecky církve, žeť jsem já ten, kterýž zpytuji ledví a srdce, a odplatím jednomu každému z vás podle skutků vašich.'),
(1577002,54,66,2,24,'Vámť pak pravím i jiným Tyatirským, kteřížkoli nemají učení tohoto, a kteříž nepoznali hlubokosti satanovy, jakž oni říkají: Nevzložímť na vás jiného břemene.'),
(1577003,54,66,2,25,'Avšak to, což máte, držte, dokavadž nepřijdu.'),
(1577004,54,66,2,26,'Kdož by pak vítězil a ostříhal až do konce skutků mých, dám jemu moc nad pohany.'),
(1577005,54,66,2,27,'I budeť je spravovati prutem železným, a jako nádoba hrnčířova střískáni budou, jakž i já vzal jsem od Otce svého.'),
(1577006,54,66,2,28,'A dám jemu hvězdu jitřní.'),
(1577007,54,66,2,29,'Kdo má uši, slyš, co Duch praví církvím.'),
(1577008,54,66,3,1,'Andělu pak církve Sardinské piš: Toto praví ten, jenž má sedm duchů Božích a sedm hvězd: Vím skutky tvé: máš jméno, že jsi živ, ale jsi mrtvý.'),
(1577009,54,66,3,2,'Budiž bedlivý, a potvrdiž toho, což mělo umříti. Neboť jsem nenalezl skutků tvých plných před Bohem.'),
(1577010,54,66,3,3,'Pomniž tedy, co jsi přijal a slyšel, a ostříhej toho, a čiň pokání. Pakli bdíti nebudeš, přijduť na tě jako zloděj, a nezvíš, v kterou hodinu na tě přijdu.'),
(1577011,54,66,3,4,'Ale máš některé osoby i v Sardis, kteréž neposkvrnily roucha svého, protož budouť se procházeti se mnou v bílém rouše; nebo jsou hodni.'),
(1577012,54,66,3,5,'Kdo zvítězí, tenť bude odín rouchem bílým; a nevymažiť jména jeho z knih života, ale vyznámť jméno jeho před obličejem Otce svého i před anděly jeho.'),
(1577013,54,66,3,6,'Kdo má uši, slyš, co Duch praví církvím.'),
(1577014,54,66,3,7,'Andělu pak Filadelfitské církve piš: Totoť praví ten svatý a pravý, jenž má klíč Davidův, kterýžto otvírá, a žádný nezavírá, a zavírá, žádný pak neotvírá:'),
(1577015,54,66,3,8,'Vím skutky tvé. Aj, postavil jsem před tebou dveře otevřené, a žádnýť jich nemůže zavříti. Nebo máš ač nevelikou moc, a ostříhal jsi slova mého, a nezapřels jména mého.'),
(1577016,54,66,3,9,'Aj, dávámť některé z sběři satanovy, kteříž se praví býti Židé, a nejsou, ale klamají. Aj, pravím, způsobím to, žeť přijdou a budou se klaněti před nohama tvýma, a poznajíť, že jsem já tě miloval.'),
(1577017,54,66,3,10,'Nebo jsi ostříhal slova trpělivosti mé, i jáť tebe ostříhati budu od hodiny pokušení, kteréž přijíti má na všecken svět, aby zkušeni byli obyvatelé země.'),
(1577018,54,66,3,11,'Aj, přijduť brzy. Držiž se toho, co máš, aby žádný nevzal koruny tvé.'),
(1577019,54,66,3,12,'Kdo zvítězí, učiním jej sloupem v chrámě Boha svého, a nevyjdeť již více ven; a napíšiť na něm jméno Boha svého a jméno města Boha mého, nového Jeruzaléma sstupujícího s nebe od Boha mého, i jméno své nové.'),
(1577020,54,66,3,13,'Kdo má uši, slyš, co Duch praví církvím.'),
(1577021,54,66,3,14,'Andělu pak církve Laodicenské piš: Toto praví Amen, svědek ten věrný a pravý, počátek stvoření Božího:'),
(1577022,54,66,3,15,'Vímť skutky tvé, že ani jsi studený, ani horký. Ó bys chutně studený byl anebo horký.'),
(1577023,54,66,3,16,'A tak, že jsi vlažný, a ani studený, ani horký, vyvrhu tě z úst svých.'),
(1577024,54,66,3,17,'Nebo pravíš: Bohatý jsem, a zbohatl jsem, a žádného nepotřebuji, a nevíš, že jsi bídný, mizerný, a chudý, a slepý, i nahý.'),
(1577025,54,66,3,18,'Radím tobě, abys sobě koupil ode mne zlata ohněm zprubovaného, abys byl bohatý, a v roucho bílé abys oblečen byl, a neokazovala se hanba nahoty tvé. A očí svých pomaž kollyrium, abys viděl.'),
(1577026,54,66,3,19,'Já kteréžkoli miluji, kárám a tresci; rozhorliž se tedy, a čiň pokání.'),
(1577027,54,66,3,20,'Aj, stojímť u dveří, a tluku. Jestližeť by kdo uslyšel hlas můj a otevřel dveře, vejduť k němu, a budu s ním večeřeti, a on se mnou.'),
(1577028,54,66,3,21,'Kdož zvítězí, dám jemu seděti s sebou na trůnu svém, jako i já zvítězil jsem, a sedím s Otcem svým na trůnu jeho.'),
(1577029,54,66,3,22,'Kdo má uši, slyš, co Duch praví církvím.'),
(1577030,54,66,4,1,'Potom jsem viděl, a aj, dveře otevříny byly v nebi, a hlas první, kterýž jsem byl slyšel jako trouby, an mluví se mnou, řkoucí: Vstup sem, a ukážiť, co se má díti potom.'),
(1577031,54,66,4,2,'A hned byl jsem u vytržení ducha, a aj, trůn postaven byl na nebi, a na trůnu jeden seděl.'),
(1577032,54,66,4,3,'A ten, jenž seděl, podoben byl obličejem kameni jaspidu a sardiovi; a vůkol toho trůnu byla duha, na pohledění podobná smaragdu.'),
(1577033,54,66,4,4,'A okolo toho trůnu bylo stolic čtyřmecítma, a na těch stolicích viděl jsem čtyřmecítma starců sedících, oblečených v roucha bílá. A měli na hlavách svých koruny zlaté.'),
(1577034,54,66,4,5,'A z toho trůnu pocházelo blýskání, a hromobití, a hlasové. A sedm lamp ohnivých hořících před trůnem, jenž jsou sedm Duchů Božích.'),
(1577035,54,66,4,6,'A před trůnem bylo moře sklené, podobné křišťálu, a uprostřed trůnu a vůkol trůnu čtvero zvířat, plných očí zpředu i zzadu.'),
(1577036,54,66,4,7,'A zvíře první podobné bylo lvu, a druhé zvíře podobné teleti, a třetí zvíře mající tvárnost jako člověk, a čtvrté zvíře podobné orlu letícímu.'),
(1577037,54,66,4,8,'A jedno každé z těch čtyř zvířat mělo šest křídel okolo, a vnitř plná byla očí, a neměla odpočinutí dnem i nocí, říkajíce: Svatý, svatý, svatý Pán Bůh všemohoucí, kterýž byl, a jest, i přijíti má.'),
(1577038,54,66,4,9,'A když ta zvířata vzdávala slávu a čest i díků činění sedícímu na trůnu, živému na věky věků,'),
(1577039,54,66,4,10,'Padlo těch čtyřmecítma starců před obličejem sedícího na trůnu, a klanělo se živému na věky věků, a metali koruny své před trůnem, řkouce:'),
(1577040,54,66,4,11,'Hoden jsi, Pane, přijíti slávu, a čest, i moc; nebo ty jsi stvořil všecky věci, a pro vůli tvou trvají, i stvořeny jsou.'),
(1577041,54,66,5,1,'I viděl jsem po pravici sedícího na trůnu knihy popsané vnitř i zevnitř, zapečetěné sedmi pečetmi');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1577042,54,66,5,2,'A viděl jsem anděla silného, volajícího hlasem velikým: Kdo jest hoden otevříti knihy tyto a zrušiti pečeti jejich?'),
(1577043,54,66,5,3,'I nemohl žádný, ani na nebi, ani na zemi, ani pod zemí, otevříti knih, ani pohleděti do nich.'),
(1577044,54,66,5,4,'Pročež já plakal jsem velmi, že není nalezen žádný, kterýž by hoden byl otevříti a čísti tu knihu, ani pohleděti do ní.'),
(1577045,54,66,5,5,'Tedy jeden z starců dí mi: Neplač. Aj, zvítězilť Lev, ten, kterýž jest z pokolení Judova, kořen Davidův, aby otevřel tu knihu a zrušil sedm pečetí jejích.'),
(1577046,54,66,5,6,'I viděl jsem, a aj, mezi trůnem a čtyřmi zvířaty a mezi starci Beránek stojí jako zabitý, maje sedm rohů a sedm očí, jenž jsou sedm Duchů Božích, poslaných na všecku zemi.'),
(1577047,54,66,5,7,'I přišel a vzal knihy z pravice toho, kterýž seděl na trůnu.'),
(1577048,54,66,5,8,'A jakž vzal knihy, ihned těch čtvero zvířat a těch čtyřmecítma starců padlo před Beránkem, majíce jeden každý z nich harfu a báně zlaté plné vůně, jenž jsou modlitby svatých.'),
(1577049,54,66,5,9,'A zpívali píseň novou, řkouce: Hoden jsi vzíti knihy a otevříti pečeti jejich. Nebo jsi zabit, a vykoupils nás Bohu krví svou ze všelikého pokolení a jazyku a lidu i národu.'),
(1577050,54,66,5,10,'A učinil jsi nás Bohu našemu krále a kněží, a budeme kralovati na zemi.'),
(1577051,54,66,5,11,'I viděl jsem a slyšel hlas andělů mnohých okolo trůnu a zvířat a starců, a byl počet jejich stokrát tisíc tisíců a desetkrát sto tisíců,'),
(1577052,54,66,5,12,'Řkoucích velikým hlasem: Hodenť jest ten zabitý Beránek vzíti moc, a bohatství, i moudrost, i sílu, i čest, i slávu, i požehnání.'),
(1577053,54,66,5,13,'Též všecko stvoření, kteréž jest na nebi, i na zemi, i pod zemí, i v moři, i všecko, což v nich jest, slyšel jsem řkoucí: Sedícímu na trůnu a Beránkovi požehnání, čest a sláva i síla na věky věků.'),
(1577054,54,66,5,14,'Čtvero pak zvířat řeklo: Amen. A těch čtyřmecítma starců padlo, a klaněli se živému na věky věků.'),
(1577055,54,66,6,1,'I viděl jsem, když otevřel Beránek jednu z těch pečetí, a slyšel jsem jedno ze čtyř zvířat, ano praví, jako hlasem hromovým: Pojď a viz.'),
(1577056,54,66,6,2,'I pohleděl jsem, a aj, kůň bílý, a ten, jenž seděl na něm, měl lučiště. A dána jest jemu koruna, i vyjel, přemáhaje, a aby přemáhal.'),
(1577057,54,66,6,3,'A když otevřel pečet druhou, slyšel jsem druhé zvíře, řkoucí: Pojď a viz.'),
(1577058,54,66,6,4,'I vyšel jiný kůň ryzí. A sedícímu na něm dáno jest, aby pokoj vyzdvihl z země a aby se lidé vespolek mordovali; a dán jemu meč veliký.'),
(1577059,54,66,6,5,'A když otevřel pečet třetí, slyšel jsem třetí zvíře, řkoucí: Pojď a viz. I pohleděl jsem, a aj, kůň vraný, a ten, jenž na něm seděl, měl váhu v ruce své.'),
(1577060,54,66,6,6,'I slyšel jsem hlas z prostředku čtyř zvířat, an praví: Měřice pšenice za peníz, a tři měřice ječmene za peníz, oleji pak a vínu neškoď.'),
(1577061,54,66,6,7,'A když otevřel pečet čtvrtou, slyšel jsem hlas čtvrtého zvířete, řkoucí: Pojď a viz.'),
(1577062,54,66,6,8,'I pohleděl jsem, a aj, kůň plavý, a toho, kterýž seděl na něm, jméno smrt, a peklo šlo za ním. I dána jest jim moc nad čtvrtým dílem země, aby mordovali mečem, a hladem, a morem, a šelmami zemskými.'),
(1577063,54,66,6,9,'A když otevřel pečet pátou, viděl jsem pod oltářem duše zmordovaných pro slovo Boží a pro svědectví, kteréž vydávali.'),
(1577064,54,66,6,10,'I volali hlasem velikým, řkouce: Až dokud, Pane svatý a pravý, nesoudíš a nemstíš krve naší nad těmi, kteříž přebývají na zemi?'),
(1577065,54,66,6,11,'Tedy dáno jednomu každému z nich roucho bílé, a řečeno jest jim, aby odpočívali ještě za malý čas, až by se naplnil počet spoluslužebníků jejich a bratří jejich, kteříž zmordováni býti mají, jako i oni.'),
(1577066,54,66,6,12,'I pohleděl jsem, když otevřel pečet šestou, a aj, země třesení veliké stalo se, a slunce učiněno jest černé jako pytel žíněný, a měsíc všecken byl jako krev.'),
(1577067,54,66,6,13,'A hvězdy nebeské padaly na zemi, podobně jako dřevo fíkové smítá s sebe ovoce své, když od velikého větru kláceno bývá.'),
(1577068,54,66,6,14,'A nebe se schovalo jako knihy zavřené, a všeliká hora i ostrovové z místa svého pohnuli se.'),
(1577069,54,66,6,15,'A králové země, i knížata, i bohatí, a úředníci, a mocní, i každý služebník, i všeliký svobodný, skryli se v jeskyních a v skalí hor,'),
(1577070,54,66,6,16,'A řekli horám a skalí: Padněte na nás a skrejte nás před tváří toho, jenž sedí na trůnu, a před hněvem Beránka.'),
(1577071,54,66,6,17,'Nebť jest přišel den veliký hněvu jeho. I kdo bude moci ostáti?'),
(1577072,54,66,7,1,'Potom jsem viděl čtyři anděly, stojící na čtyřech úhlech země, držící čtyři větry zemské, aby nevál vítr na zemi, ani na moře, ani na žádný strom.'),
(1577073,54,66,7,2,'A viděl jsem jiného anděla, vystupujícího od východu slunce, majícího pečet Boha živého. Kterýž zvolal hlasem velikým na ty čtyři anděly, jimž dáno, aby škodili zemi a moři,'),
(1577074,54,66,7,3,'Řka: Neškoďte zemi, ani moři, ani stromům, dokudž neznamenáme služebníků Boha našeho na čelích jejich.'),
(1577075,54,66,7,4,'I slyšel jsem počet znamenaných, sto čtyřidceti a čtyři tisíce jich zapečetěno ze všech pokolení synů Izraelských.'),
(1577076,54,66,7,5,'Z pokolení Juda dvanácte tisíců znamenaných, z pokolení Ruben dvanácte tisíců znamenaných, z pokolení Gád dvanácte tisíců znamenaných;'),
(1577077,54,66,7,6,'Z pokolení Aser dvanácte tisíců znamenaných, z pokolení Neftalím dvanácte tisíců znamenaných, z pokolení Manases dvanácte tisíců znamenaných;'),
(1577078,54,66,7,7,'Z pokolení Simeon dvanácte tisíců znamenaných, z pokolení Léví dvanácte tisíců znamenaných, z pokolení Izachar dvanácte tisíců znamenaných;'),
(1577079,54,66,7,8,'Z pokolení Zabulon dvanácte tisíců znamenaných, z pokolení Jozef dvanácte tisíců znamenaných, z pokolení Beniamin dvanácte tisíců znamenaných.'),
(1577080,54,66,7,9,'Potom pohleděl jsem, a aj, zástup veliký, kteréhož by žádný přečísti nemohl, ze všech národů a pokolení a lidí i jazyků, ani stojí před trůnem a před obličejem Beránka, oblečeni jsouce v bílé roucho, a palmy v rukou jejich.'),
(1577081,54,66,7,10,'A volali hlasem velikým, řkouce: Spasení jest od Boha našeho na trůnu sedícího a od Beránka.'),
(1577082,54,66,7,11,'A všickni andělé stáli okolo trůnu a starců a čtyř zvířat. I padli před trůnem na tváři své a klaněli se Bohu,'),
(1577083,54,66,7,12,'Řkouce: Amen. Požehnání, a sláva, a moudrost, a díků činění, a čest, a moc, i síla Bohu našemu na věky věků. Amen.'),
(1577084,54,66,7,13,'I promluvil ke mně jeden z těch starců, a řekl mi: Kdo jsou tito, kteříž oblečeni jsou v bílé roucho? A odkud přišli?'),
(1577085,54,66,7,14,'I řekl jsem jemu: Pane, ty víš. I řekl mi: To jsou ti, kteříž přišli z velikého soužení, a umyli roucha svá, a zbílili je ve krvi Beránkově.'),
(1577086,54,66,7,15,'Protož jsou před trůnem Božím, a slouží jemu dnem i nocí v chrámě jeho; a ten, jenž sedí na trůnu, přebývati bude s nimi.'),
(1577087,54,66,7,16,'Nebudouť lačněti ani žízniti více, a nebude bíti na ně slunce, ani žádné horko.'),
(1577088,54,66,7,17,'Nebo Beránek, kterýž jest uprostřed trůnu, pásti je bude, a dovedeť je k živým studnicím vod, a setře Bůh všelikou slzu s očí jejich.'),
(1577089,54,66,8,1,'A když otevřel pečet sedmou, stalo se na nebi mlčení, jako za půl hodiny.'),
(1577090,54,66,8,2,'I viděl jsem sedm andělů, kteříž stojí před obličejem Božím, jimž dáno sedm trub.'),
(1577091,54,66,8,3,'A jiný anděl přišel a postavil se před oltářem, maje kadidlnici zlatou. I dáni jsou jemu zápalové mnozí, aby je obětoval s modlitbami všechněch svatých na oltáři zlatém, kterýž jest před trůnem.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1577092,54,66,8,4,'I vstoupil dým zápalů s modlitbami svatých z ruky anděla až před obličej Boží.'),
(1577093,54,66,8,5,'I vzal anděl kadidlnici, a naplnil ji ohněm s oltáře, a svrhl ji na zem. I stalo se hromobití, a hlasové, a blýskání, i země třesení.'),
(1577094,54,66,8,6,'A těch sedm andělů, kteříž měli sedm trub, připravili se, aby troubili.'),
(1577095,54,66,8,7,'I zatroubil první anděl, a stalo se krupobití a oheň smíšený se krví, a svrženo jest to na zem. A třetí díl stromů shořel, a všecka tráva zelená spálena jest.'),
(1577096,54,66,8,8,'Potom zatroubil druhý anděl, a uvržena jest do moře jako hora veliká ohněm hořící. I učiněn jest krví třetí díl moře.'),
(1577097,54,66,8,9,'A zemřel v moři třetí díl stvoření těch, kteráž měla duši, a třetí díl lodí zhynul.'),
(1577098,54,66,8,10,'A vtom třetí anděl zatroubil, i spadla s nebe hvězda veliká, hořící jako pochodně, a padla na třetí díl řek a do studnic vod.'),
(1577099,54,66,8,11,'A jméno hvězdy té bylo Pelynek. I obrátil se třetí díl vod v pelynek, a mnoho lidí zemřelo od těch vod, nebo byly zhořkly.'),
(1577100,54,66,8,12,'Potom čtvrtý anděl zatroubil, i udeřena jest třetina slunce, a třetina měsíce, a třetí díl hvězd, takže se třetí díl jich zatměl, a třetina dne nesvítila, a též podobně i noci.'),
(1577101,54,66,8,13,'I viděl jsem a slyšel anděla jednoho, an letí po prostředku nebe, a praví hlasem velikým: Běda, běda, běda těm, kteříž přebývají na zemi, pro jiné hlasy trub tří andělů, kteříž mají troubiti.'),
(1577102,54,66,9,1,'Potom anděl pátý zatroubil, i viděl jsem, ano hvězda s nebe spadla na zem; a dán jest tomu andělu klíč od studnice propasti.'),
(1577103,54,66,9,2,'Kterýžto otevřel studnici propasti. I vyšel dým z studnice jako dým z peci veliké, i zatmělo se slunce i povětří pro dým studnice.'),
(1577104,54,66,9,3,'A z toho dýmu vyšly kobylky na zemi, jimžto dána jest moc taková, jakouž moc mají štírové zemští.'),
(1577105,54,66,9,4,'Ale řečeno jim, aby neškodily trávě zemské, ani čemu zelenému, ani kterémukoli stromoví, než toliko lidem, kteříž nemají znamení Božího na čelích svých.'),
(1577106,54,66,9,5,'Dáno jest pak jim, ne aby je zabíjely, ale trápily za pět měsíců, a aby trápení jejich bylo jako trápení od štíra, když by ušťknul člověka.'),
(1577107,54,66,9,6,'A v těch dnech hledati budou lidé smrti, ale nenaleznou jí, a žádati budou zemříti, ale smrt uteče od nich.'),
(1577108,54,66,9,7,'Způsob pak těch kobylek podobný byl koňům připraveným k boji, a na hlavách jejich byly jako koruny podobné zlatu, a tváři jejich jako tváři lidské.'),
(1577109,54,66,9,8,'A měly vlasy jako vlasy ženské, a zuby jejich byly jako zubové lvů.'),
(1577110,54,66,9,9,'Měly také pancíře jako pancíře železné, a zvuk křídel jejich jako zvuk vozů, když množství koní běží k boji.'),
(1577111,54,66,9,10,'A měly ocasy podobné štírům, a žihadla v ocasích jejich byla, a moc jejich byla škoditi lidem za pět měsíců.'),
(1577112,54,66,9,11,'A měly nad sebou krále, anděla propasti, jemuž jméno Židovsky Abaddon, a řecky Apollyon.'),
(1577113,54,66,9,12,'Bída jedna pominula, a aj, přijdou ještě dvě bídy potom.'),
(1577114,54,66,9,13,'Tedy šestý anděl zatroubil, i slyšel jsem hlas jeden ze čtyř rohů oltáře zlatého, kterýž jest před obličejem Božím,'),
(1577115,54,66,9,14,'Řkoucí k šestému andělu, kterýž měl troubu: Rozvěž ty čtyři anděly, kteříž jsou u vězení při veliké řece Eufrates.'),
(1577116,54,66,9,15,'I rozvázáni jsou ti čtyři andělé, kteříž byli připraveni k hodině, a ke dni, a k měsíci, a k roku, aby zmordovali třetí díl lidí.'),
(1577117,54,66,9,16,'A byl počet vojska lidu jízdného dvěstěkrát tisíc tisíců; nebo slyšel jsem počet jejich.'),
(1577118,54,66,9,17,'A též viděl jsem u vidění, koně a ti, kteříž seděli na nich, měli pancíře ohnivé a hyacintové a z síry. Hlavy pak těch koňů byly jako hlavy lvové, a z úst jejich vycházel oheň, a dým, a síra.'),
(1577119,54,66,9,18,'A tímto trojím zmordována jest třetina lidu, totiž ohněm, a dýmem, a sirou, kteréž vycházely z úst jejich.'),
(1577120,54,66,9,19,'Nebo moc jejich jest v ústech jejich a v ocasích jejich; ocasové zajisté jejich jsou podobni hadům, majíce hlavy, jimiž škodí.'),
(1577121,54,66,9,20,'Jiní pak lidé, kteříž nejsou zmordováni těmi ranami, nečinili pokání z skutků rukou svých, aby se neklaněly ďáblům, a modlám zlatým, a stříbrným, a měděným, i kamenným, i dřevěným, kteréžto ani hleděti nemohou, ani slyšeti, ani choditi.'),
(1577122,54,66,9,21,'Aniž činili pokání z vražd svých, ani z trávení svých, ani z smilstva svého, ani z krádeží svých.'),
(1577123,54,66,10,1,'Viděl jsem jiného anděla silného, sstupujícího s nebe, oděného oblakem, a duha na hlavě jeho byla, a tvář jeho jako slunce, a nohy jeho jako sloupové ohniví.'),
(1577124,54,66,10,2,'A v ruce své měl knížky otevřené. I postavil nohu svou pravou na moři a levou na zemi.'),
(1577125,54,66,10,3,'A volal hlasem velikým, jako by lev řval. A když dokonal volání, mluvilo sedm hromů hlasy své.'),
(1577126,54,66,10,4,'A když odmluvilo sedm hromů hlasy své, byl bych to psal. Ale slyšel jsem hlas s nebe řkoucí ke mně: Zapečeť to, co mluvilo sedm hromů, než nepiš toho.'),
(1577127,54,66,10,5,'Tedy anděl, kteréhož jsem viděl stojícího na moři a na zemi, pozdvihl ruky své k nebi,'),
(1577128,54,66,10,6,'A přisáhl skrze živého na věky věků, kterýž stvořil nebe i to, což v něm jest, a zemi i to, což na ní jest, a moře i to, což v něm jest, že již více času nebude.'),
(1577129,54,66,10,7,'Ale ve dnech hlasu sedmého anděla, když bude troubiti, dokonánoť bude tajemství Boží, jakož zvěstoval služebníkům svým prorokům.'),
(1577130,54,66,10,8,'A ten hlas, kterýž jsem byl slyšel s nebe, opět mluvil se mnou a řekl: Jdi, a vezmi ty knížky otevřené z ruky anděla, stojícího na moři a na zemi.'),
(1577131,54,66,10,9,'I šel jsem k andělu, a řekl jsem jemu: Dej mi ty knížky. I řekl mi: Vezmi, a požři je, a učiníť hořkost v břiše tvém, ale v ústech tvých budouť sladké jako med.'),
(1577132,54,66,10,10,'I vzal jsem knížky z ruky anděla, a požřel jsem je. I byly v ústech mých sladké jako med, ale když jsem je požřel, hořko mi bylo v břiše mém.'),
(1577133,54,66,10,11,'I dí mi: Musíš opět prorokovati lidem, a národům, a jazykům, i králům mnohým.'),
(1577134,54,66,11,1,'I dána mi třtina, podobná prutu, a postavil se tu anděl, a řekl mi: Vstaň, a změř chrám Boží, i oltář, i ty, kteříž se modlí v něm.'),
(1577135,54,66,11,2,'Ale síň, kteráž vně jest, vyvrz ven, a neměř jí. Neboť jest dána pohanům, a budouť tlačiti město svaté za čtyřidceti a dva měsíce.'),
(1577136,54,66,11,3,'Ale dám jej dvěma svědkům svým, kteříž budou prorokovati tisíc dvě stě a šedesáte dnů, oblečeni jsouce v pytle.'),
(1577137,54,66,11,4,'Tiť jsou dvě olivy a dva svícnové, stojící před obličejem Boha Pána vší země.'),
(1577138,54,66,11,5,'Jimžto jestliže by kdo chtěl ubližovati, oheň vyjde z úst jejich, a sžíře nepřátely jejich; a takť musí zabit býti, kdož by koli jim škoditi chtěl.'),
(1577139,54,66,11,6,'Tiť mají moc zavříti nebe, aby nepršel déšť za dnů proroctví jejich; a mají moc nad vodami, obrátiti je v krev, a bíti zemi všelikou ranou, kolikrát by koli chtěli.'),
(1577140,54,66,11,7,'Ale když dokonají svědectví své, šelma vystupující z propasti válku povede proti nim, a zvítězí nad nimi, i zmorduje je.'),
(1577141,54,66,11,8,'A ležeti budou těla jejich mrtvá na ryncích města velikého, kteréž slove duchovně Sodoma a Egypt, kdežto i Pán náš ukřižován jest.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1577142,54,66,11,9,'A vídati budou mnozí z pokolení, a z lidu, a z jazyků, i z národů těla jejich mrtvá za půl čtvrta dne, ale těl jejich mrtvých nedadí pochovati v hrobích.'),
(1577143,54,66,11,10,'Anobrž ti, kteříž přebývají na zemi, radovati se budou nad nimi a veseliti se, a dary budou posílati jedni druhým; nebo ti dva proroci trápili ty, jenž přebývají na zemi.'),
(1577144,54,66,11,11,'Ale po půl čtvrtu dni duch života od Boha poslaný vstoupil do nich, i postavili se na nohách svých, a bázeň veliká spadla na ty, kteříž je viděli.'),
(1577145,54,66,11,12,'Potom slyšeli hlas veliký s nebe, řkoucí k nim: Vstupte sem! I vstoupili na nebe v oblace, a hleděli na ně nepřátelé jejich.'),
(1577146,54,66,11,13,'A v tu hodinu stalo se země třesení veliké, a desátý díl města padl, a zbito jest v tom země třesení sedm tisíců lidu, a jiní zstrašeni jsou, a vzdali slávu Bohu nebeskému.'),
(1577147,54,66,11,14,'Bída druhá pominula, a aj, třetí bída přijde rychle.'),
(1577148,54,66,11,15,'A sedmý anděl zatroubil, i stali se hlasové velicí v nebi, řkoucí: Učiněnať jsou království všeho světa Pána našeho a Krista jeho, a kralovatiť bude na věky věků.'),
(1577149,54,66,11,16,'Tedy těch čtyřmecítma starců, kteříž před obličejem Božím sedí na stolicích svých, padli na tváři své, a klaněli se Bohu,'),
(1577150,54,66,11,17,'Řkouce: Díky činíme tobě, Pane Bože všemohoucí, Kterýž jsi, a Kterýžs byl, a Kterýž přijíti máš; nebo jsi přijal moc svou velikou a království ujal.'),
(1577151,54,66,11,18,'I rozhněvali se národové, a přišel hněv tvůj, a čas mrtvých, aby souzeni byli, a aby dána byla odplata služebníkům tvým prorokům, i jiným svatým i všechněm, jenž se bojí jména tvého, malým i velikým, a aby zkaženi byli ti, kteříž nakažují zemi.'),
(1577152,54,66,11,19,'I otevřín jest chrám Boží na nebi, a vidína jest truhla smlouvy jeho v chrámě jeho. I stalo se blýskání, a hlasové, a hromobití, a země třesení, i krupobití veliké.'),
(1577153,54,66,12,1,'I ukázal se div veliký na nebi: Žena oděná sluncem,pod jejímiž nohama byl měsíc a na jejíž hlavě byla koruna dvanácti hvězd.'),
(1577154,54,66,12,2,'A jsuci těhotná, křičela, pracujici ku porodu a trápěci se, aby porodila.'),
(1577155,54,66,12,3,'I vidín jest jiný div na nebi. Nebo aj, drak veliký ryšavý ukázal se, maje hlav sedm a rohů deset, a na těch hlavách svých sedm korun.'),
(1577156,54,66,12,4,'Jehož ocas strhl třetinu hvězd s nebe, a svrhl je na zem. Ten pak drak stál před ženou, kteráž měla poroditi, aby hned, jakž by porodila, syna jejího sežral.'),
(1577157,54,66,12,5,'I porodila syna pacholíka, kterýž měl spravovati všecky národy prutem železným. I vytržen jest syn její k Bohu a k trůnu jeho.'),
(1577158,54,66,12,6,'A žena utekla na poušť, kdež měla místo od Boha připravené, aby ji tam živili za dnů tisíc dvě stě a šedesát.'),
(1577159,54,66,12,7,'I stal se boj na nebi: Michal a andělé jeho bojovali s drakem, a drak bojoval i andělé jeho.'),
(1577160,54,66,12,8,'Ale nic neobdrželi, aniž jest nalezeno více místo jejich na nebi.'),
(1577161,54,66,12,9,'I svržen jest drak ten veliký, had starý, jenž slove ďábel a satanáš, kterýž svodí všecken okršlek světa; svržen jest, pravím, na zem, i andělé jeho s ním svrženi jsou.'),
(1577162,54,66,12,10,'A uslyšel jsem hlas veliký, řkoucí na nebi: Nyní stalo se spasení, a moc, i království Boha našeho, a moc Krista jeho; nebo svržen jest žalobník bratří našich, kterýž žaloval na ně před obličejem Boha našeho dnem i nocí.'),
(1577163,54,66,12,11,'Ale oni zvítězili nad ním skrze krev Beránka, a skrze slovo svědectví svého, a nemilovali duší svých až do smrti.'),
(1577164,54,66,12,12,'Protož veselte se nebesa, a kteříž přebýváte v nich. Běda těm, jenž přebývají na zemi a na moři; nebo ďábel sstoupil k vám, maje hněv veliký, věda, že krátký čas má.'),
(1577165,54,66,12,13,'A když uzřel drak, že jest svržen na zem, honil ženu tu, kteráž porodila toho pacholíka.'),
(1577166,54,66,12,14,'Ale dána jsou ženě dvě křídla orlice veliké, aby letěla od tváři hada na poušť, na místo své, kdež by ji živili do času a časů, a do půl času.'),
(1577167,54,66,12,15,'I vypustil had z úst svých po ženě vodu jako řeku, aby ji řeka zachvátila.'),
(1577168,54,66,12,16,'Ale země pomohla ženě; neb otevřela země ústa svá a požřela řeku, kterouž vypustil drak z úst svých.'),
(1577169,54,66,12,17,'I rozhněval se drak na tu ženu, a šel bojovati s jinými z semene jejího, kteříž ostříhají přikázání Božích a mají svědectví Ježíše Krista.'),
(1577170,54,66,12,18,'I stál jsem na písku mořském.'),
(1577171,54,66,13,1,'I viděl jsem šelmu vystupující z moře, kteráž měla sedm hlav a deset rohů. A na rozích jejích deset korun, a na hlavách jejích jméno rouhání.'),
(1577172,54,66,13,2,'Byla pak šelma ta, kterouž jsem viděl, podobná pardovi, a nohy její jako nedvědí, a ústa její jako ústa lvová. I dal jí drak sílu svou, a trůn svůj, a moc velikou.'),
(1577173,54,66,13,3,'A viděl jsem, ano jedna z hlav jejích jako zbitá byla až na smrt, ale rána její smrtelná uzdravena jest. Tedy divivši se všecka země, šla za tou šelmou.'),
(1577174,54,66,13,4,'A klaněli se drakovi, kterýž dal moc šelmě; a klaněli se šelmě, řkouce: Kdo jest podobný té šelmě? Kdo bude moci bojovati s ní?'),
(1577175,54,66,13,5,'I dána jsou jí ústa mluvící veliké věci a rouhání, a dána jí moc vládnouti za čtyřidceti a dva měsíce.'),
(1577176,54,66,13,6,'Protož otevřela ústa svá k rouhání se Bohu, aby se rouhala jménu jeho, i stánku jeho, i těm, kteříž přebývají na nebi.'),
(1577177,54,66,13,7,'Dáno jí i bojovati s svatými a přemáhati je; a dána jí moc nad všelikým pokolením, nad rozličným jazykem, i nad národem.'),
(1577178,54,66,13,8,'Protož klaněti se jí budou všickni, kteříž přebývají na zemi, jichžto jména nejsou napsaná v knihách života Beránka, toho zabitého od počátku světa.'),
(1577179,54,66,13,9,'Má-li kdo uši, slyš.'),
(1577180,54,66,13,10,'Jestliže kdo do vězení povede, do vězení půjde; zabije-li kdo mečem, musí mečem zabit býti. Zdeť jest trpělivost a víra svatých.'),
(1577181,54,66,13,11,'Potom viděl jsem jinou šelmu vystupující z země, a měla dva rohy, podobné rohům Beránkovým, ale mluvila jako drak.'),
(1577182,54,66,13,12,'Kterážto všecku moc první šelmy provozuje před tváří její; a působí to, že země i ti, kteříž přebývají na ní, klanějí se šelmě té první, jejížto rána smrtelná uzdravena byla.'),
(1577183,54,66,13,13,'A činí divy veliké, takže i ohni rozkazuje sstupovati s nebe na zem před obličejem mnohých lidí.'),
(1577184,54,66,13,14,'A svodí ty, jenž přebývají na zemi, těmi divy, kteréžto dáno jí činiti před obličejem šelmy, říkající obyvatelům země, aby udělali obraz šelmě, kteráž měla ránu od meče, a ožila zase.'),
(1577185,54,66,13,15,'I dáno jí, aby dáti mohla ducha tomu obrazu šelmy, aby i mluvil obraz šelmy, a aby to způsobila, kteřížkoli neklaněli by se obrazu šelmy, aby byli zmordováni.'),
(1577186,54,66,13,16,'A rozkazuje všechněm, malým i velikým, bohatým i chudým, svobodným i v službu podrobeným, aby měli znamení na pravé ruce své, aneb na čelích svých,'),
(1577187,54,66,13,17,'A aby žádný nemohl kupovati ani prodávati, než ten, kdož má znamení aneb jméno té šelmy, anebo počet jména jejího.'),
(1577188,54,66,13,18,'Tuť jest moudrost. Kdo má rozum, sečtiž počet šelmy. Nebo jest počet člověka, a jestiť počet ten šest set šedesáte a šest.'),
(1577189,54,66,14,1,'Tedy pohleděl jsem, a aj, Beránek stál na hoře Sion, a s ním sto čtyřidceti a čtyři tisíců majících jméno Otce jeho napsané na čelích svých.'),
(1577190,54,66,14,2,'A slyšel jsem hlas s nebe, jako hlas vod mnohých, a jako hlas hromu velikého. A hlas slyšel jsem, jako těch, kteříž hrají na harfy své.'),
(1577191,54,66,14,3,'A zpívali jakožto píseň novou, před trůnem, a před čtyřmi zvířaty, a před starci, a žádný nemohl se naučiti té písni, jediné těch sto čtyřidceti a čtyři tisíce, kteříž jsou koupeni z země.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1577192,54,66,14,4,'Totoť jsou ti, kteříž s ženami nejsou poskvrněni; nebo panicové jsou. Tiť jsou, jenž následují Beránka, kamž by koli šel; tiť jsou koupeni ze všech lidí, prvotiny Bohu a Beránkovi.'),
(1577193,54,66,14,5,'A v ústech jejich není nalezena lest; neboť jsou bez úhony před trůnem Božím.'),
(1577194,54,66,14,6,'I viděl jsem jiného anděla letícího po prostředku nebe, majícího evangelium věčné, aby je zvěstoval těm, jenž bydlí na zemi, a všelikému národu, i pokolení, i jazyku, i lidu,'),
(1577195,54,66,14,7,'Řkoucího velikým hlasem: Bojte se Boha, a vzdejte jemu chválu, neboť přišla hodina soudu jeho; a klanějte se tomu, kterýž učinil nebe i zemi i moře i studnice vod.'),
(1577196,54,66,14,8,'A jiný anděl letěl za ním, řka: Padl, padl Babylon, město to veliké, nebo vínem hněvu smilství svého napájelo všecky národy.'),
(1577197,54,66,14,9,'A třetí anděl letěl za nimi, pravě velikým hlasem: Bude-li se kdo klaněti šelmě a obrazu jejímu, a vezme-li znamení její na čelo své aneb na ruku svou,'),
(1577198,54,66,14,10,'I tenť také bude píti víno hněvu Božího, víno, pravím, kteréž jest vlito do kalichu hněvu jeho; a trápen bude ohněm a sirou před obličejem andělů svatých a před obličejem Beránka.'),
(1577199,54,66,14,11,'A dým muk jejich vstoupíť na věky věků, a nebudouť míti odpočinutí dnem i nocí ti, kteříž se klanějí šelmě a obrazu jejímu, a jestliže kdo přijme znamení jména jejího.'),
(1577200,54,66,14,12,'Tuť jest trpělivost svatých, tu jsou ti, kteříž ostříhají přikázání Božích a víry Ježíšovy'),
(1577201,54,66,14,13,'I slyšel jsem hlas s nebe, řkoucí ke mně: Piš: Blahoslavení jsou od této chvíle mrtví, kteříž v Pánu umírají. Duch zajisté dí jim, aby odpočinuli od prací svých, nebo skutkové jejich následují jich.'),
(1577202,54,66,14,14,'I pohleděl jsem, a aj, oblak bělostkvoucí, a na tom oblaku seděl podobný Synu člověka, maje na hlavě své korunu zlatou a v ruce své srp ostrý.'),
(1577203,54,66,14,15,'A jiný anděl vyšel z chrámu, volaje hlasem velikým na toho, kterýž seděl na oblaku: Pusť srp svůj a žni; nebť jest přišla tobě hodina žni, nebo již dozrala žeň země.'),
(1577204,54,66,14,16,'I spustil ten, kterýž seděl na oblaku, srp svůj na zem, a požata jest země.'),
(1577205,54,66,14,17,'A jiný anděl vyšel z chrámu toho, kterýž jest na nebi, maje i on srp ostrý.'),
(1577206,54,66,14,18,'Opět vyšel jiný anděl z oltáře, kterýž měl moc nad ohněm, a volal křikem velikým na toho, jenž měl srp ostrý, řka: Pusť srp svůj ostrý, a zbeř hrozny vinice zemské; neboť jsou uzrali hroznové její.'),
(1577207,54,66,14,19,'I spustil anděl srp svůj na zemi, a sebral vinici země, a vmetal hrozny do jezera velikého hněvu Božího.'),
(1577208,54,66,14,20,'I tlačeno jest jezero před městem, a vyšla krev z jezera až do udidl koňům za tisíc a za šest set honů.'),
(1577209,54,66,15,1,'Potom viděl jsem jiný zázrak na nebi veliký a předivný: Sedm andělů majících sedm ran posledních, v nichž má dokonán býti hněv Boží.'),
(1577210,54,66,15,2,'A viděl jsem jako moře sklené, smíšené s ohněm, a ty, kteříž zvítězili nad šelmou a obrazem jejím a nad charakterem jejím i nad počtem jména jejího, ani stojí nad tím mořem skleným, majíce harfy Boží,'),
(1577211,54,66,15,3,'A zpívají píseň Mojžíše, služebníka Božího, a píseň Beránkovu, řkouce: Velicí a předivní jsou skutkové tvoji, Pane Bože všemohoucí, spravedlivé a pravé jsou cesty tvé, ó Králi všech svatých.'),
(1577212,54,66,15,4,'Kdož by se nebál tebe, Pane, a nezveleboval jména tvého? Nebo ty sám svatý jsi. Všickni zajisté národové přijdou a klaněti se budou před obličejem tvým; nebo soudové tvoji zjeveni jsou.'),
(1577213,54,66,15,5,'Potom pak viděl jsem, a aj, otevřín jest chrám stánku svědectví na nebi.'),
(1577214,54,66,15,6,'I vyšlo sedm těch andělů z chrámu, majících sedm ran, oblečeni jsouce rouchem lněným, čistým a bělostkvoucím, a přepásáni na prsech pasy zlatými.'),
(1577215,54,66,15,7,'A jedno ze čtyř zvířat dalo sedmi andělům sedm koflíků zlatých, plných hněvu Boha živého na věky věků.'),
(1577216,54,66,15,8,'I naplněn jest chrám dýmem, pocházejícím od slávy Boží a od moci jeho, a žádný nemohl vjíti do chrámu, dokudž se nevykonalo sedm ran těch sedmi andělů.'),
(1577217,54,66,16,1,'I slyšel jsem hlas veliký z chrámu, řkoucí sedmi andělům: Jděte, vylijte sedm koflíků hněvu Božího na zemi.'),
(1577218,54,66,16,2,'I šel první anděl a vylil koflík svůj na zemi, i vyvrhli se vředové škodliví a zlí na lidech, majících znamení šelmy, a na těch, kteříž se klaněli obrazu jejímu.'),
(1577219,54,66,16,3,'Za tím druhý anděl vylil koflík svůj na moře, a učiněno jest jako krev umrlého, a všeliká duše živá v moři umřela.'),
(1577220,54,66,16,4,'Potom třetí anděl vylil koflík svůj na řeky a na studnice vod, i obráceny jsou v krev.'),
(1577221,54,66,16,5,'I slyšel jsem anděla vod, řkoucího: Spravedlivý jsi, Pane, Kterýž jsi, a Kterýž jsi byl, a Svatý, žes to usoudil.'),
(1577222,54,66,16,6,'Neboť jsou krev svatých a proroků vylévali, i dal jsi jim krev píti; hodniť jsou zajisté toho.'),
(1577223,54,66,16,7,'I slyšel jsem jiného anděla od oltáře, kterýž řekl: Jistě, Pane Bože všemohoucí, praví jsou a spravedliví soudové tvoji.'),
(1577224,54,66,16,8,'Potom čtvrtý anděl vylil koflík svůj na slunce, i dáno jest jemu trápiti lidi ohněm.'),
(1577225,54,66,16,9,'I pálili se lidé horkem velikým, a rouhali se jménu Boha toho, kterýž má moc nad těmito ranami, avšak nečinili pokání, aby vzdali slávu jemu.'),
(1577226,54,66,16,10,'Tedy pátý anděl vylil koflík svůj na stolici té šelmy, i učiněno jest království její tmavé, i kousali lidé jazyky své pro bolest.'),
(1577227,54,66,16,11,'A rouhali se Bohu nebeskému pro bolesti své a pro vředy své, avšak nečinili pokání z skutků svých.'),
(1577228,54,66,16,12,'Šestý pak anděl vylil koflík svůj na tu velikou řeku Eufrates, i vyschla voda její, aby připravena byla cesta králům od východu slunce.'),
(1577229,54,66,16,13,'A viděl jsem, ano z úst draka a z úst šelmy a z úst falešného proroka vyšli tři duchové nečistí, podobní žabám.'),
(1577230,54,66,16,14,'Nebo jsouť duchové ďábelští, ješto činí divy a chodí mezi krále zemské a všeho světa, aby je shromáždili k boji, k tomu velikému dni Boha všemohoucího.'),
(1577231,54,66,16,15,'Aj, přicházímť jako zloděj. Blahoslavený, kdož bdí a ostříhá roucha svého, aby nah nechodil, aby neviděli hanby jeho.'),
(1577232,54,66,16,16,'I shromáždil je na místo, kteréž slove Židovsky Armageddon.'),
(1577233,54,66,16,17,'Tedy sedmý anděl vylil koflík svůj na povětří, i vyšel hlas veliký z chrámu nebeského, od trůnu, řkoucí: Stalo se.'),
(1577234,54,66,16,18,'I stali se zvukové a hromobití a blýskání, i země třesení stalo se veliké, jakéhož nikdy nebylo, jakž jsou lidé na zemi, totiž země třesení tak velikého.'),
(1577235,54,66,16,19,'I roztrhlo se to veliké město na tři strany, a města národů padla. A Babylon veliký přišel na pamět před obličejem Božím, aby dal jemu kalich vína prchlivosti hněvu svého.'),
(1577236,54,66,16,20,'A všickni ostrovové pominuli, a hory nejsou nalezeny.'),
(1577237,54,66,16,21,'A kroupy veliké jako centnéřové pršely s nebe na lidi. I rouhali se Bohu lidé pro ránu těch krup; nebo velmi veliká byla ta rána.'),
(1577238,54,66,17,1,'I přišel jeden z sedmi andělů, kteříž měli sedm koflíků, a mluvil se mnou, řka ke mně: Pojď, ukážiť odsouzení nevěstky veliké, kteráž sedí na vodách mnohých,'),
(1577239,54,66,17,2,'S kteroužto smilnili králové země a zpili se vínem smilství jejího obyvatelé země.'),
(1577240,54,66,17,3,'I odnesl mne na poušť v duchu, a viděl jsem ženu sedící na šelmě brunátné; a ta šelma plná byla jmen rouhání, a měla sedm hlav a deset rohů.'),
(1577241,54,66,17,4,'Žena pak odína byla šarlatem a brunátným rouchem, a ozdobena zlatem a kamením drahým i perlami, mající koflík zlatý v ruce své, plný ohavností a nečistoty smilstva svého.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1577242,54,66,17,5,'A na čele jejím napsané jméno: Tajemství, Babylon veliký, Mátě smilstva a ohavností země.'),
(1577243,54,66,17,6,'A viděl jsem ženu tu opilou krví svatých a krví mučedlníků Ježíšových, a viděv ji, divil jsem se divením velikým.'),
(1577244,54,66,17,7,'I řekl mi anděl: Co se divíš? Já tobě povím tajemství té ženy i šelmy, kteráž ji nese, mající hlav sedm a rohů deset.'),
(1577245,54,66,17,8,'Šelma, kterous viděl, byla, a již není, a máť vystoupiti z propasti a na zahynutí jíti. I diviti se budou bydlitelé země, (ti, kterýchžto jména nejsou napsána v knihách života od ustanovení světa,) vidouce šelmu, kteráž byla, a není, avšak jest.'),
(1577246,54,66,17,9,'Tentoť pak jest smysl toho, a máť zavřenou v sobě moudrost: Sedm hlav jestiť sedm hor, na kterýchž ta žena sedí.'),
(1577247,54,66,17,10,'A králů sedm jest. Pět jich padlo, jeden jest, a jiný ještě nepřišel; a když přijde, na malou chvíli musí trvati.'),
(1577248,54,66,17,11,'A šelma, kteráž byla a není, onať jest osmý, a z sedmiť jest, i na zahynutí jde.'),
(1577249,54,66,17,12,'Deset pak rohů, kteréžs viděl, jestiť deset králů, kteříž ještě království nepřijali, ale přijmouť moc jako králové, jedné hodiny spolu s šelmou.'),
(1577250,54,66,17,13,'Tiť jednu radu mají, a sílu i moc svou šelmě dadí.'),
(1577251,54,66,17,14,'Tiť bojovati budou s Beránkem, a Beránek zvítězí nad nimi, neboť Pán pánů jest a Král králů, i ti, kteříž jsou s ním, povolaní, a vyvolení, a věrní.'),
(1577252,54,66,17,15,'I řekl mi: Vody, kteréžs viděl, kdež nevěstka sedí, jsouť lidé, a zástupové, a národové, a jazykové.'),
(1577253,54,66,17,16,'Deset pak rohů, kteréžs viděl na šelmě, ti v nenávist vezmou nevěstku, a učiní ji opuštěnou a nahou, a tělo její jísti budou, a ji páliti budou ohněm.'),
(1577254,54,66,17,17,'Neboť dal Bůh v srdce jejich, aby činili vůli jeho a aby se sjednomyslnili, a toliko dotud království své šelmě dali, dokudž by nebyla vykonána slova Boží.'),
(1577255,54,66,17,18,'A žena, kteroužs viděl, jestiť město to veliké, kteréž má království nad králi země.'),
(1577256,54,66,18,1,'Potom pak viděl jsem anděla sstupujícího s nebe, majícího moc velikou, a země osvícena byla od slávy jeho.'),
(1577257,54,66,18,2,'I zkřikl silně hlasem velikým, řka: Padl, padl Babylon ten veliký, a učiněn jest příbytkem ďáblů, a stráží každého ducha nečistého, a stráží všelikého ptactva nečistého a ohyzdného.'),
(1577258,54,66,18,3,'Nebo z vína hněvu smilstva jeho pili všickni národové, a králové zemští smilnili s ním, a kupci zemští z zboží rozkoší jeho zbohatli.'),
(1577259,54,66,18,4,'I slyšel jsem jiný hlas s nebe, řkoucí: Vyjděte z něho, lide můj, abyste se nepřiúčastňovali hříchům jeho a abyste nepřijali z jeho ran.'),
(1577260,54,66,18,5,'Neboť dosáhli hříchové jeho až k nebi a rozpomenul se Bůh na nepravosti jeho.'),
(1577261,54,66,18,6,'Dejtež jemu, jakož i on dával vám, a dejte jemu dvénásob podle skutků jeho; v koflík, kterýž naléval vám, nalijte jemu to dvénásob.'),
(1577262,54,66,18,7,'Jakž se mnoho chlubil a zbujněl byl, tak mnoho dejte jemu muk a pláče. Neboť v srdci svém praví: Sedím královna, a nejsemť vdovou, a pláče neuzřím.'),
(1577263,54,66,18,8,'Protož v jeden den přijdouť rány jeho, smrt a pláč i hlad, a ohněm spáleno bude; nebo silný jest Pán, kterýž je odsoudí.'),
(1577264,54,66,18,9,'I plakati ho budou a kvíliti nad ním králové země, kteříž s ním smilnili a svou rozkoš měli, když uzří dým zapálení jeho,'),
(1577265,54,66,18,10,'Zdaleka stojíce, pro bázeň muk jeho, a řkouce: Běda, běda, veliké město Babylon, to město silné, že jest jedné hodiny přišel odsudek tvůj.'),
(1577266,54,66,18,11,'Ano i kupci zemští budou plakati a kvíliti nad ním; nebo koupí jejich žádný nebude kupovati více,'),
(1577267,54,66,18,12,'Koupě od zlata, a stříbra, a drahého kamene, i perel, i kmentu, šarlatu, i hedbáví, i brunátného roucha, i všelikého dřeva tyinového, a všech nádob z kostí slonových, i všelikého nádobí z nejdražšího dříví, i z mědi, i z železa, i z mramoru;'),
(1577268,54,66,18,13,'A kupectví skořice, i vonných věcí, a mastí, i kadidla, i vína, i oleje, i bělí, i pšenice, i dobytka, i ovec, i koní, a vozů, i služebníků, i duší lidských;'),
(1577269,54,66,18,14,'I ovoce žádostivá duši tvé odešla od tebe, a všecko tučné a krásné odešlo od tebe, a aniž toho již více nalezneš.'),
(1577270,54,66,18,15,'Ti, pravím, kupci, kteříž v tom kupčili a jím zbohatli, zdaleka stanou pro strach muk jeho, plačíce, a kvílíce,'),
(1577271,54,66,18,16,'A řkouce: Běda, běda, ó město veliké, kteréž odíno kmentem, a šarlatem, a brunátným rouchem, a ozdobeno bylo zlatem, a kamením drahým, i perlami! nebo v jednu hodinu zahynula tak veliká bohatství.'),
(1577272,54,66,18,17,'Ano i všeliký správce lodí mořských, i všecko množství lidí, kteříž jsou na lodech, i plavci, i ti, kteříž svou živnost na moři mají, zdaleka stanou,'),
(1577273,54,66,18,18,'A zkřiknou, vidouce dým zapálení jeho, řkouce: Které město bylo podobné tomuto velikému městu!'),
(1577274,54,66,18,19,'A sypouce prach na hlavy své, křičeti budou, plačíce, a kvílíce, a řkouce: Běda, běda, město veliké, v němžto zbohatli všickni, kteříž měli lodí na moři, ze mzdy jeho; nebo jedné hodiny zpustlo.'),
(1577275,54,66,18,20,'Ale raduj se nad ním nebe i svatí apoštolé i proroci; nebo pomstilť vás Bůh nad ním.'),
(1577276,54,66,18,21,'I zdvihl jeden silný anděl kámen jako žernov veliký a hodil jím do moře, řka: Tak prudce uvržen bude Babylon, to město veliké, a již více nebude nalezeno.'),
(1577277,54,66,18,22,'A hlas na harfy hrajících, a zpěváků, a pišťců, a trubačů nebude více v tobě slyšán, a žádný řemeslník žádného řemesla nebude v tobě více nalezen, a zvuk žernovu nebude v tobě více slyšán.'),
(1577278,54,66,18,23,'Ani světlo svíce nebude v tobě více svítiti, a hlas ženicha ani nevěsty nebude v tobě více slyšán, ješto kupci tvoji bývala knížata zemská, a tráveními tvými v blud uvedeni byli všickni národové.'),
(1577279,54,66,18,24,'Ale v něm nalezena jest krev proroků a svatých i všech zmordovaných na zemi.'),
(1577280,54,66,19,1,'Potom jsem slyšel veliký hlas velikého zástupu na nebi, řkoucího: Haleluiah. Spasení, a sláva, a čest, i moc Pánu Bohu našemu.'),
(1577281,54,66,19,2,'Neboť jsou praví a spravedliví soudové jeho, kterýž odsoudil nevěstku tu velikou, jenž byla porušila zemi smilstvem svým, a pomstil krve služebníků svých z ruky její.'),
(1577282,54,66,19,3,'I řekli po druhé: Haleluiah. A dým její vstupoval na věky věků.'),
(1577283,54,66,19,4,'I padlo čtyřmecítma starců a čtvero zvířat, a klaněli se Bohu sedícímu na trůnu, řkouce: Amen, Haleluiah.'),
(1577284,54,66,19,5,'I vyšel z trůnu hlas, řkoucí: Chvalte Boha našeho všickni služebníci jeho, a kteříž se bojíte jeho, i malí i velicí.'),
(1577285,54,66,19,6,'A slyšel jsem hlas jako zástupu velikého, a jako hlas vod mnohých, a jako zvuk hromů silných, řkoucích: Haleluiah. Kralovalť jest Pán Bůh náš všemohoucí.'),
(1577286,54,66,19,7,'Radujme se, a veselme se, a chválu vzdejme jemu. Neboť jest přišla svadba Beránkova, a manželka jeho připravila se.'),
(1577287,54,66,19,8,'A dáno jest jí, aby se oblékla v kment čistý a stkvoucí, a ten kment jsouť ospravedlňování svatých.'),
(1577288,54,66,19,9,'I řekl mi: Piš: Blahoslavení, kteříž jsou k večeři svadby Beránkovy povoláni. A řekl mi: Tatoť slova Boží jsou pravá.'),
(1577289,54,66,19,10,'I padl jsem k nohám jeho, klaněti se jemu chtěje. Ale řekl mi: Hleď, abys toho nečinil. Neboť jsem spoluslužebník tvůj i bratří tvých, těch, jenž mají svědectví Ježíšovo. Bohu se klaněj! Svědectví pak Ježíšovo jestiť duch proroctví.'),
(1577290,54,66,19,11,'I viděl jsem nebe otevřené, a aj, kůň bílý, a ten, jenž seděl na něm, sloul Věrný a Pravý, a kterýž v spravedlnosti soudí i bojuje.'),
(1577291,54,66,19,12,'Oči pak jeho byly jako plamen ohně, a na hlavě jeho korun množství, a měl jméno napsané, kteréhož žádný neví, než on sám.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1577292,54,66,19,13,'A byl odín v roucho pokropené krví, a sloveť jméno jeho Slovo Boží.'),
(1577293,54,66,19,14,'A rytířstvo nebeské jelo za ním na bílých koních, jsouce odíni v kment bílý a čistý.'),
(1577294,54,66,19,15,'A z úst jeho vycházel meč ostrý, aby jím bil všecky národy. Nebo on bude je spravovati prutem železným; onť i pres vína hněvu a prchlivosti Boha všemohoucího tlačiti bude.'),
(1577295,54,66,19,16,'A máť na rouchu a na bedrách svých napsané jméno: Král králů a Pán pánů.'),
(1577296,54,66,19,17,'I viděl jsem jednoho anděla, an stojí v slunci, a zkřikl hlasem velikým, řka všechněm ptákům, kteříž létali po prostřed nebes: Pojďte a shromažďte se k večeři velikého Boha,'),
(1577297,54,66,19,18,'Abyste jedli těla králů, a těla hejtmanů, a těla silných, a těla koňů, i těch, kteříž na nich sedí, a těla všech svobodných i služebníků, i malých i velikých.'),
(1577298,54,66,19,19,'I viděl jsem šelmu a krále země a vojska jejich, ani se sjeli, aby bojovali s tím, kterýž seděl na koni, a s rytířstvem jeho.'),
(1577299,54,66,19,20,'I jata jest šelma, a s ní falešný prorok ten, kterýž činíval divy před ní, jimiž svodil ty, kteříž přijali znamení šelmy a kteříž se klaněli obrazu jejímu. I uvrženi jsou oba za živa do jezera ohnivého, hořícího sirou.'),
(1577300,54,66,19,21,'A jiní zbiti jsou mečem toho, kterýž seděl na koni, vycházejícím z úst jeho. A všickni ptáci nasyceni jsou těly jejich.'),
(1577301,54,66,20,1,'I viděl jsem anděla sstupujícího s nebe, majícího klíč od propasti a řetěz veliký v ruce své.'),
(1577302,54,66,20,2,'I chopil draka, hada toho starého, jenž jest ďábel a satan, i svázal jej za tisíc let.'),
(1577303,54,66,20,3,'A uvrhl ho do propasti, i zavřel jej tam a svrchu nad ním zapečetil, aby nesvodil více národů, až by se vyplnilo tisíc let; neboť potom musí býti propuštěn na malý čas.'),
(1577304,54,66,20,4,'I viděl jsem stolice, a posadili se na nich, i dán jest jim soud, a viděl jsem duše stínaných pro svědectví Ježíšovo a pro slovo Boží, a kteříž se neklaněli šelmě, ani obrazu jejímu, a aniž přijali znamení jejího na čela svá, anebo na ruce své. A ožili a kralovali s Kristem tisíc let.'),
(1577305,54,66,20,5,'Jiní pak mrtví neožili, dokudž by se nevyplnilo tisíc let. A toť jest první vzkříšení.'),
(1577306,54,66,20,6,'Blahoslavený a svatý, kdož má díl v prvním vzkříšení. Nad těmiť ta druhá smrt nemá moci, ale budou kněží Boží a Kristovi, a kralovati s ním budou tisíc let.'),
(1577307,54,66,20,7,'A když se vyplní tisíc let, propuštěn bude satanáš z žaláře svého.'),
(1577308,54,66,20,8,'I vyjde, aby svodil národy, kteříž jsou na čtyřech stranách země, Goga a Magoga, a aby je shromáždil k boji, kterýchžto počet jest jako písku mořského.'),
(1577309,54,66,20,9,'I vstoupili na širokost země a obklíčili stany svatých, i to město milé, ale sstoupil oheň od Boha s nebe a spálil je.'),
(1577310,54,66,20,10,'A ďábel, kterýž je svodil, uvržen jest do jezera ohně a síry, kdež jest i šelma, i falešný prorok, a budouť mučeni dnem i nocí na věky věků.'),
(1577311,54,66,20,11,'I viděl jsem trůn veliký bílý, a sedícího na něm, před jehož tváří utekla země i nebe, a místo jim není nalezeno.'),
(1577312,54,66,20,12,'I viděl jsem mrtvé, malé i veliké, stojící před obličejem Božím, a knihy otevříny jsou. A jiné knihy také jsou otevříny, to jest knihy života, i souzeni jsou mrtví podle toho, jakž psáno bylo v knihách, totiž podle skutků svých.'),
(1577313,54,66,20,13,'A vydalo moře mrtvé, kteříž byli v něm, tolikéž smrt i peklo vydali ty, kteříž v nich byli, i souzeni jsou jeden každý podle skutků svých.'),
(1577314,54,66,20,14,'Smrt pak a peklo uvrženi jsou do jezera ohnivého, a toť jest smrt druhá.'),
(1577315,54,66,20,15,'I ten, kdož není nalezen v knihách života, uvržen jest do jezera ohnivého.'),
(1577316,54,66,21,1,'Potom viděl jsem nebe nové a zemi novou. Nebo první nebe a první země byla pominula, a moře již nebylo.'),
(1577317,54,66,21,2,'A já Jan viděl jsem město svaté, Jeruzalém nový, sstupující od Boha s nebe, připravený jako nevěstu okrášlenou muži svému.'),
(1577318,54,66,21,3,'I slyšel jsem hlas veliký s nebe, řkoucí: Aj, stánek Boží s lidmi, a bydlitiť bude s nimi, a oni budou lid jeho, a on Bůh s nimi bude, jsa jejich Bohem.'),
(1577319,54,66,21,4,'A setřeť Bůh všelikou slzu s očí jejich, a smrti již více nebude, ani kvílení, ani křiku, ani bolesti nebude více; nebo první věci pominuly.'),
(1577320,54,66,21,5,'I řekl ten, kterýž seděl na trůnu: Aj, nové činím všecko. I řekl mi: Napiš to. Neboť jsou tato slova věrná a pravá.'),
(1577321,54,66,21,6,'I dí mi: Již se stalo. Jáť jsem Alfa i Omega, počátek i konec. Jáť žíznivému dám z studnice vody živé darmo.'),
(1577322,54,66,21,7,'Kdož zvítězí, obdržíť dědičně všecko, a buduť jemu Bohem, a on mi bude synem.'),
(1577323,54,66,21,8,'Strašlivým pak, a nevěrným, a ohyzdným, a vražedlníkům, a smilníkům, a čarodějníkům, a modlářům, i všechněm lhářům, připraven jest díl jejich v jezeře, kteréž hoří ohněm a sirou, jenž jest smrt druhá.'),
(1577324,54,66,21,9,'I přišel ke mně jeden z sedmi andělů, kteříž měli sedm koflíků plných sedmi ran nejposlednějších, a mluvil se mnou, řka: Pojď, ukážiť nevěstu, manželku Beránkovu.'),
(1577325,54,66,21,10,'I vnesl mne v duchu na horu velikou a vysokou, a ukázal mi město veliké, ten svatý Jeruzalém, sstupující s nebe od Boha,'),
(1577326,54,66,21,11,'Mající slávu Boží. Jehož světlost byla podobná k kameni nejdražšímu, jako k kameni jaspidu, kterýž by byl způsobu křišťálového,'),
(1577327,54,66,21,12,'A mělo zed velikou a vysokou, v níž bylo dvanácte bran, a na těch branách dvanácte andělů, a jména napsaná, kterážto jména jsou dvanáctera pokolení synů Izraelských.'),
(1577328,54,66,21,13,'Od východu slunce brány tři, od půlnoci brány tři, od poledne brány tři, od západu brány tři.'),
(1577329,54,66,21,14,'A zed městská měla základů dvanácte, a na nich jména dvanácti apoštolů Beránkových.'),
(1577330,54,66,21,15,'A ten, kterýž mluvil se mnou, měl třtinu zlatou, aby změřil město i brány jeho i zed jeho.'),
(1577331,54,66,21,16,'Položení města toho čtverhrané jest, jehož dlouhost tak veliká jest jako i širokost. I změřil to město třtinou a vyměřil dvanácte tisíců honů; dlouhost pak jeho, i širokost, i vysokost jednostejná jest.'),
(1577332,54,66,21,17,'I změřil zed jeho, a naměřil sto čtyřidceti a čtyři loktů, měrou člověka, kteráž jest míra anděla.'),
(1577333,54,66,21,18,'A bylo stavení zdi jeho jaspis, město pak samo zlato čisté, podobné sklu čistému.'),
(1577334,54,66,21,19,'A základové zdi městské všelikým kamenem drahým ozdobeni byli. Základ první byl jaspis, druhý zafir, třetí chalcedon, čtvrtý smaragd,'),
(1577335,54,66,21,20,'Pátý sardonyx, šestý sardius, sedmý chryzolit, osmý beryllus, devátý topazion, desátý chryzoprassus, jedenáctý hyacint, dvanáctý ametyst.'),
(1577336,54,66,21,21,'Dvanácte pak bran dvanácte perel jest, a jedna každá brána jest z jedné perly; a rynk města zlato čisté jako sklo, kteréž se naskrze prohlédnouti může.'),
(1577337,54,66,21,22,'Ale chrámu jsem v něm neviděl; nebo Pán Bůh všemohoucí chrám jeho jest a Beránek.'),
(1577338,54,66,21,23,'A to město nepotřebuje slunce ani měsíce, aby svítily v něm; nebo sláva Boží je osvěcuje, a svíce jeho jest Beránek.'),
(1577339,54,66,21,24,'A národové lidí k spasení přišlých, v světle jeho procházeti se budou, a králové zemští přenesou slávu a čest svou do něho.'),
(1577340,54,66,21,25,'A brány jeho nebudou zavírány ve dne; noci zajisté tam nebude.'),
(1577341,54,66,21,26,'A snesou do něho slávu a čest národů.');
INSERT INTO verses (id, version_id, book_id, chapter, verse, text) VALUES
(1577342,54,66,21,27,'A nevejdeť do něho nic poskvrňujícího, anebo působícího ohyzdnost a lež, než toliko ti, kteříž napsaní jsou v knihách života Beránkova.'),
(1577343,54,66,22,1,'I ukázal mi potok čistý vody živé, světlý jako křišťál, tekoucí z trůnu Božího a Beránkova.'),
(1577344,54,66,22,2,'Uprostřed pak rynku jeho a s obou stran potoka bylo dřevo života, přinášející dvanáctero ovoce, na každý měsíc vydávající ovoce své, a listí své k zdraví národů.'),
(1577345,54,66,22,3,'A ničeho zlořečeného již více nebude, ale trůn Boží a Beránkův bude v něm, a služebníci jeho sloužiti jemu budou.'),
(1577346,54,66,22,4,'A tvář jeho viděti budou, a jméno jeho budeť na čelích jejich.'),
(1577347,54,66,22,5,'A noci tam nebude, aniž budou potřebovati svíce, ani světla slunečného; nebo Pán Bůh je osvěcuje, a kralovati budou na věky věků.'),
(1577348,54,66,22,6,'I řekl mi: Slova tato jsouť věrná a pravá, a Pán, jenž jest Bůh svatých proroků, poslal anděla svého, aby ukázal služebníkům svým, co se díti musí brzo.'),
(1577349,54,66,22,7,'Aj, přijduť rychle. Blahoslavený, kdož ostříhá slov proroctví knihy této.'),
(1577350,54,66,22,8,'Já pak Jan viděl jsem a slyšel tyto věci. A když jsem slyšel a viděl, padl jsem, klaněti se chtěje před nohama anděla toho, kterýž mi tyto věci ukazoval.'),
(1577351,54,66,22,9,'Ale řekl mi: Hleď, abys toho nečinil. Neboť jsem spoluslužebník tvůj a bratří tvých proroků, a těch, jenž ostříhají slov knihy této. Bohu se klaněj.'),
(1577352,54,66,22,10,'Potom řekl mi: Nezapečeťuj slov proroctví knihy této; neboť jest blízko čas.'),
(1577353,54,66,22,11,'Kdo škodí, škodiž ještě; a kdo smrdí, smrdiž ještě; a kdo jest spravedlivý, ospravedlniž se ještě; a svatý posvětiž se ještě.'),
(1577354,54,66,22,12,'A aj, přijduť brzo, a odplata má se mnou, abych odplatil jednomu každému podle skutků jeho.'),
(1577355,54,66,22,13,'Jáť jsem Alfa i Omega, počátek i konec, první i poslední.'),
(1577356,54,66,22,14,'Blahoslavení, kteříž zachovávají přikázání jeho, aby měli právo k dřevu života a aby branami vešli do města.'),
(1577357,54,66,22,15,'Vně pak budou psi a čarodějníci, a smilníci, a vražedlníci, a modláři, i každý, kdož miluje a činí lež.'),
(1577358,54,66,22,16,'Já Ježíš poslal jsem anděla svého, aby vám svědčil o těchto věcech v církvích. Já jsem kořen a rod Davidův, a hvězda jasná a jitřní.'),
(1577359,54,66,22,17,'A Duch i nevěsta řkou: Pojď. A kdož slyší, rciž: Přijď. A kdož žízní, přijdiž, a kdo chce, nabeř vody života darmo.'),
(1577360,54,66,22,18,'Osvědčujiť pak každému, kdož by slyšel slova proroctví knihy této, jestliže by kdo přidal k těmto věcem, žeť jemu přidá Bůh ran napsaných v knize této.'),
(1577361,54,66,22,19,'A jestliže by kdo ujal něco od slov proroctví tohoto, odejmeť Bůh díl jeho z knihy života, a z města svatého, a z těch věcí, kteréž jsou napsány v knize této.'),
(1577362,54,66,22,20,'Takť praví ten, kterýž svědectví vydává o těchto věcech: Jistěť přijdu brzo. Amen. Přijdiž tedy, Pane Ježíši.'),
(1577363,54,66,22,21,'Milost Pána našeho Jezukrista se všemi vámi. Amen.');
